(window.__CBP=window.__CBP||[]).push("תאנים מתאנתי אוכל מהם עראי ומעשרן דמאי בד״א בע״ה אבל בחבר אוכל ואינו צריך לעשר דברי רבי רשב״ג אומר וכו' אמר רבי נראים דברי מדברי אבא מוטב שיחשדו חבירים לתרום שלא מן המוקף ואל יאכילו לעמי הארץ טבלים ופירשו בגמרא דה״ק במה דברים אמורים בע״ה שאמר לחבר אבל חבר (כלומר) שאמר לעם הארץ וחבר אחר שומעו אוכל ואינו צריך לעשר דודאי עשורי עשריה ההוא חבר קמא אע״פ שאינו מוקף דניחא ליה לחבר דלעביד איסורא קלילא ולא ליעביד ע״ה איסורא רבה ורשב״ג סבר איפכא ופירש״י דכשא״ל לקוט לך תאנים סתם ולא פירש כמה מעשרן ודאי כיון שאינו יודע כמה ליקט ודאי שלא עישר עליהן אבל כשא״ל כלכלה זו כיון שיודע כמה הם אמרינן דעישר עליהם ולכך חבר זה אינו מעשר אלא דמאי:\",2,0],[8,355,10,11,\"מותר להאכיל את העניים ואת האורחים דמאי. משנה ריש פרק ג' דדמאי (משנה א').\",1,0],[8,355,10,11,\"ומה שכתב וצריך להודיען. שם בירושלמי:\",2,0],[8,355,10,12,\"גבאי צדקה גובין סתם וכו'. שם במשנה וכחכמים:\",1,0],[8,355,10,13,\"רופא חבר שהיה מאכיל לחולה עם הארץ וכו' עד סוף הפרק. שם בירושלמי והטעם פשוט שאין לחבר להאכיל בידו דבר איסור בפיו ומיהו בתוך ידו לא גזרו כיון שהוא של חולה והוא ספק שהרי מצוי לו ורופא לאו מידי עביד אבל בודאי אף לתוך ידו אסור שהרי מסייע ידי עוברי עבירה וכן אם הדמאי של חבר הרופא אין לחבר להאכיל דבר בלתי מתוקן:\",1,0],[8,355,11,1,\"אסור למכור את הדמאי לע\\\"ה או לשלוח לו וכו'. משנה פ\\\"ג דדמאי (משנה ג').\",1,0],[8,355,11,1,\"ומ\\\"ש אבל מוכרים אותו ומשלחים אותו לת\\\"ח וכו':\",2,0],[8,355,11,2,\"כל המשפיעים במדה גסה וכו'. משנה פ\\\"ב דדמאי (משנה ד'):\",1,0],[8,355,11,2,\"ומ\\\"ש מפני שהם מוסיפים על המדה. שם בירושלמי:\",2,0],[8,355,11,4,\"ומ\\\"ש סלי זיתים וענבים וכו'. שם במשנה פטר רבי יוסי:\",1,0],[8,355,11,4,\"כתב הראב\\\"ד לא ראינו מחלוקת על רבי יוסי שהוא מתיר במשנה עכ\\\"ל. ורבינו משמע ליה דיחידאה הוא ופליגי עליה רבנן דאל\\\"כ למה נשנה בלשון יחיד:\",2,0],[8,355,11,5,\"אמר אחד מהן באו ונתקן הפירות וכו'. ירושלמי שם.\",1,0],[8,355,11,5,\"וכתב הראב\\\"ד א\\\"א בדמאי ירושלמי פרק ב' וכו'. ואני אומר דברי רבינו מבוארים שם שאין תנאי ב\\\"ד זה אלא כשאמר אחד מהן באו ונתקן הפירות האלו:\",2,0],[8,355,11,6,\"חבר וע\\\"ה שירשו את אביהם עם הארץ וכו'. משנה פ\\\"ו דדמאי (משנה ט'):\",1,0],[8,355,11,8,\"מי שהיה נושא ירק וכו' עד לא יחזיר עד שיעשר. משנה פ\\\"ג דדמאי (משנה ב'):\",1,0],[8,355,11,9,\"המוצא פירות בדרך וכו'. משנה פרק שני דמכשירין (משנה י'):\",1,0],[8,355,11,10,\"נטלן לאכלן וכו' עד ה\\\"ז מותר וכו'. משנה פרק ג' דדמאי (משנה ג'):\",1,0],[8,355,11,11,\"קניבת ירק וכו'. תוספתא פרק רביעי דדמאי ודומה לזה נתבאר בפרק י\\\"א דתרומות:\",1,0],[8,355,11,12,\"הנותן לפונדקית וכו'. פרק ג' דדמאי (משנה ה'):\",1,0],[8,355,11,12,\"ומ\\\"ש אבל הנותן לחמותו או לשכנתו וכו'. שם במשנה הנותן לחמותו מעשר את שהוא נותן לה ואת שהוא נוטל ממנה מפני שהיא חשודה להחליף את המתקלקל א\\\"ר יהודה רוצה היא בתקנת בתה ובושה מחתנה ובירושלמי (הלכה ו') אמר רבי יוחנן אוף קדמייתא על דעתיה דרבי יהודה היא דרבי יהודה אמר הנותן לחמותו כנותן לפונדקית ורבנין אמרין הנותן לחמותו כנותן לשכנתו כהדא דתניא הנותן לשכנתו פת לאפות לו תבשיל לעשות לו אינו חושש לא משום שביעית ולא משום מעשרות אימתי בזמן שנתן לה שאור ותבלין אבל אם לא נתן לה שאור ותבלין חושש משום שביעית ומשום מעשרות. ופירש ר\\\"ש אף קדמייתא על דעתיה דרבי יהודה וה\\\"ק דברי רבי יהודה שרבי יהודה אומר רוצה היא בתקנת בתה ופסק רבינו כרבנין.\",2,0],[8,355,11,12,\"ומ\\\"ש בין שנשא בתה בין שאירסה. שם בירושלמי:\",3,0],[8,355,11,13,\"המוליך חטיו וכו' עד להחליף הפקדון. משנה פרק ג' דדמאי (משנה ד'):\",1,0],[8,355,11,13,\"כתב הראב\\\"ד ואם מפני הספק הזה וכו'. טעמו לומר דהוי ספק שמא החליפן בחטים של עם הארץ שמא לא החליפן ואת\\\"ל החליפן בחטים של עם הארץ שמא אותו עם הארץ עישר ותרם פירותיו ואני אומר דמאחר דקיימא לן רוב עמי הארץ מעשרין הם ואפילו הכי חיישינן להו משמע דרבנן אחמור בהו בהא למיחש אפילו למיעוטא והוא הדין דאחמור בהו למיחש אפילו לספק ספיקא. ומה שכתב אלא שמא החליפם משלו ומירוח העכו\\\"ם חייב מדרבנן יתבאר בסמוך:\",2,0],[8,355,11,14,\"עם הארץ שהיה משתמש וכו'. תוספתא פרק ג' דדמאי:\",1,0],[8,355,11,15,\"המפקיד פירותיו אצל הנכרי וכו'. משנה פ\\\"ג דדמאי (משנה ד') וכתנא קמא:\",1,0],[8,355,11,15,\"כתב הראב\\\"ד בגמרא מקשה הכא את אמר דמאי וכו'. שם בירושלמי (הלכה ג') בלשון הזה הכא את אמר לטוחן הנכרי דמאי והכא את אמר אצל הנכרי כפירותיו כאן קופה בקופות כאן פירות בפירות והראב\\\"ד מתוך שהוא סובר דמירוח העכו\\\"ם חייב מדרבנן גורס הכא את אמר ודאי במקום הכא את אמר כפירותיו וע\\\"פ מה שפירש הוא ז\\\"ל שהחששא היא שיחליף בפירותיו מפני כך כשהיא קופה בקופות מאחר שהוא מתיירא קרוב הדבר שלא החליף ומש\\\"ה לא הוי אלא דמאי אבל כשהפקיד פירות בלא קופה מאחר שהנכרי חזקתו מחליף כיון שאינו מתיירא הו\\\"ל ודאי החליף ולפיכך הוי ודאי אבל לדעת רבינו שסובר דמירוח עכו\\\"ם בשל עכו\\\"ם פטור אפילו מדרבנן כשאמרו הרי הן כפירותיו לא אמרו אלא בהפקיד אצלו חולין מתוקנין וכמו שכתב רבינו ומש\\\"ה הקשו למה אמרו כפירותיו לומר שאם הפקיד אצלו חולין מתוקנין אינו צריך להפריש כלום ולא אמרו שיהיו דמאי כמו שאמרו במוליך לטוחן נכרי ושני דהתם קופה בקופות כלומר דרך להוליך לטחון כל אחד בקופתו ועשויות להתחלף קופה בקופות ע\\\"ה שהיא דמאי אבל מפקיד אצל נכרי לא שייך להחליף אלא בפירותיו שהן פטורים וזה הוא פירוש הכא פירות בפירות:\",2,0],[8,355,11,15,\"ועל מ\\\"ש רבינו כמו שביארנו בהלכות תרומות דגנך ולא דגן עכו\\\"ם. כתב הראב\\\"ד חייבים מדרבנן עכ\\\"ל. וטעמו מדגרסינן במנחות פרק רבי ישמעאל מירוח העכו\\\"ם אי פוטר תנאי היא תורמין משל ישראל וכו' דר\\\"מ ורבי יהודה סברי אינו פוטר ורבי יוסי ור\\\"ש סברי פוטר ובתר הכי אמר רבא מ\\\"ד מירוח העכו\\\"ם פוטר גלגול העכו\\\"ם פוטר מ\\\"ד מירוח העכו\\\"ם אינו פוטר גלגול העכו\\\"ם אינו פוטר ואותבוה רב פפא ורבינא לרבא מדתניא וכו' והא האי תנא דאמר מירוח העכו\\\"ם אינו פוטר גלגול העכו\\\"ם פוטר מדרבנן גזירה משום בעלי כיסים וטעם רבינו משום דבפ\\\"ק דבכורות גבי הלוקח טבלים ממורחים מן העכו\\\"ם אי דמרחינהו עכו\\\"ם דגנך אמר רחמנא ולא דגן עכו\\\"ם משמע בהדיא דדיגון עכו\\\"ם אפי' מדרבנן פוטר וא\\\"ת תיקשי לן מאי דתנן בפ\\\"ג דדמאי גבי מפקיד פירותיו אצל נכרי ר\\\"ש אומר הרי הן דמאי ואם איתא דמירוח עכו\\\"ם פוטר אפילו מדרבנן מאחר דרבי יוסי ור\\\"ש סברי דמירוח העכו\\\"ם פוטר אמאי אמר ר\\\"ש דהוו דמאי הא אפילו החליפן פטורים הם וי\\\"ל דסבר ר\\\"ש דחיישינן שמא ישראל אחר הפקיד אצלו והוחלפו אלו באלו ולפיכך הם דמאי וכן פירש רבינו בפירוש המשנה ובהא לא קי\\\"ל כר\\\"ש:\",3,0],[8,355,12,1,\"הלוקח פירות וכו'. משנה רפ\\\"ד דדמאי (משנה א'):\",1,0],[8,355,12,1,\"ומה שכתב אפי' היו לו פירות אחרות מתוקנים מאותו המין וכו'. ירושלמי שם:\",2,0],[8,355,12,2,\"אע\\\"פ שהוא אוכל על פיו בשבת וכו'. שם במשנה.\",1,0],[8,355,12,2,\"ומ\\\"ש על שאכל בשבת: היתה שבת ויו\\\"ט סמוך לה וכו' וכן בשני י\\\"ט של גליות. ירושלמי שם:\",2,0],[8,355,12,3,\"הנשבע על חבירו שיאכל עמו בשבת וכו'. משנה שם (מ\\\"ב):\",1,0],[8,355,12,4,\"מי שאינו נאמן וכו'. משנה א' שם תרומת מעשר של דמאי שחזרה למקומה ר״ש שזורי אומר אף בחול שואלו ואוכלו על פיו ואמרינן בפרק בהמה המקשה (חולין דף ע״ה:) ובפרק אע״פ ובפרק הקומץ רבה (מנחות דף ל״ד) דהלכה כר״ש שזורי.\",1,0],[8,355,12,4,\"ומ\\\"ש בין למקום אחר בין למקומה הכי אמרינן בירושלמי בפרק ד' דמסכת דמאי לר\\\"ש.\",2,0],[8,355,12,4,\"ומ\\\"ש כשם שאימת שבת על עמי הארץ וכו'. שם בירושלמי ובתוספתא דדמאי פ\\\"ה:\",3,0],[8,355,12,4,\"וכתב הראב\\\"ד דברים הללו זרים הם אצלי וכו'. משיג על מה שפירש רבינו שאמר וחזר ואמר הפרשתיה שאם נפלה לפחות ממאה לא סגי כשיפרישנה וע\\\"כ אי סגי לה בשיפרישנה צ\\\"ל שנפלה למאה וא\\\"כ אין כאן דימוע והיאך קאמר אימת דימוע עליו ולפיכך פירש דהב\\\"ע כשנפלה לפחות ממאה ושואלין אותו אם הדמאי הזה היה מתוקן מקודם ונמצא שלא היה צריך להפריש ממנו תרומת מעשר והכל מותר וכן פירש\\\"י בפרק ד' דחולין. ואם תאמר א\\\"כ למה הפריש ממנו יש לומר דלפי שהחבירים לא היו מאמינים אותו אי נמי שהפרישה החבר ולדעת רבינו יש לומר שמ\\\"ש והפרשתיה היינו שעשה בענין שנתקן המדומע דהיינו שנתערב עם פירות חולין שלא במתכוין עד שעלתה בק\\\"א, ומ\\\"מ מ\\\"ש הראב\\\"ד שאם נפלה לפחות מק' אינו נוח לי והכי הל\\\"ל שאם נפלה לפחות ממאה כי הפרישה מאי הוי. ועל פירוש רבינו ק\\\"ל דבירושלמי משמע כפירוש הראב\\\"ד דגרסינן התם (פ\\\"ד ה\\\"א) אמר רבי אבין לא דמיא ההיא שאלתא לההיא קמייתא תמן לא בגין דחשיד לך אלא בגין דזבנית מינך אתמול חטין וחמית אוכלוסין עליך ואמרית דילמא דאנשיתה מתקנה מתקנים הויין ברם הכא בגין דחשדתך ותקינתן ותתקריין מתקנן הויין רבי שמואל בריה דרבי יוסי בן ר' בון אמר תני בר קפרא כן אימת הדימוע עליו והוא אומר אמת ומדקאמר מתקנן הויין משמע בהדיא כפירוש הראב\\\"ד ויש לתמוה למה לא הביא הראב\\\"ד ראיה לפירושו מהירושלמי הזה ולענין מה שקשה ממנו על פירוש רבינו אפשר לומר שהוא ז\\\"ל מפרש דרבי אבין בתמיהא קאמר לא דמיא ההיא שאלתא כלומר הכא כיצד יאמר לו הייתי חושד אותך ולפיכך תקנתים וזה אומר כיון שזה היה חושד אותי לא אומר לו אמת ומשיב תני בר קפרא שאעפ\\\"כ יאמר לו אמת משום דאימת דימוע עליו:\",4,0],[8,355,12,5,\"מי שאינו נאמן וכו'. ומה שכתב לפיכך מי שאינו נאמן וכו'. כתב הראב\\\"ד אני לא מצאתי כן לא בתוספתא וכו'. ואני אומר שטעם רבינו משום דרישא דברייתא בירושלמי פ\\\"ד דדמאי ובתוספתא דמעשר שני פ\\\"ג הכי איתא תני ראו אותו מפריש שני נאמן לראשון דר\\\"א וחכמים אומרים הנאמן לראשון נאמן לשני הנאמן לשני אינו נאמן לראשון וחכמים אמאי דקתני רישא דברייתא ראו אותו מפריש קיימי וידוע דהלכה כחכמים ונתן רבינו טעם לדבר שכיון שראינו שהפריש מעשר ראשון שהוא צריך לתתו ללוי מכ\\\"ש שהפריש מעשר שני שאינו צריך לתתו לאחרים שהוא עצמו יעלה ויאכלנו בירושלים אבל אם ראינוהו שהפריש מעשר שני אין להחזיקו שהפריש מעשר ראשון לפיכך המוציא פירות מביתו כלומר שלא ראינוהו מפריש אלא מפיו אנו חיים שאמר פירות אלו מעשר ראשון נאמן שהרי הוא בחזקת שאומר אמת מהטעם הנזכר ואין צריך להפריש מהם תרומה גדולה ואם אומר שהפריש מהם תרומת מעשר גם תרומה זו אין צריך להפריש דמהימנינן ליה ומטעם זה ג\\\"כ אין צריך להפריש עליהם תרומה ומעשרות אבל אם אמר אלו מעשר שני אינו נאמן מהטעם שנזכר:\",1,0],[8,355,12,5,\"ומ\\\"ש עוד הראב\\\"ד הוציא להם מעשר שני וכו'. נראה שכתבו משום דהאי בבא מוכחא כפירוש רבינו דמיירי באינו מוחזק לנאמן אלא שראו אותו שהפריש מעשר שני ואחר כך אמר שהוא פדוי נאמן ובהאי גוונא מיפרשא ההיא דהנאמן לראשון נאמן לשני וכפירוש רבינו. ותירץ דאין ראיה משום דהתם בשלא ראו אותו שהפרישו וטעמא אחרינא איכא דאימת קדושתו עליו. ומ\\\"מ צריך טעם למה כשאמר פדוי לי ופדוי לכם אינו נאמן ואפשר דה\\\"ג פדוי לי [ופדו] לכם וה\\\"ק פדוי הוא לי שפדיתיו אבל אם אתם לא תרצו לסמוך עלי פדו לכם ששם פקפוק בדבר אין סומכין עליו ואף גירסת ופדוי לכם תתפרש ע\\\"פ זה וה\\\"ק פדוי הוא גם לכם אם תרצו לסמוך עלי:\",2,0],[8,355,12,7,\"האומר למי שאינו נאמן על המעשרות וכו' עד הרי אלו נאמנים. משנה פ\\\"ד דדמאי (מ\\\"ה):\",1,0],[8,355,12,7,\"וכתב הראב\\\"ד הנכנס לעיר וכו'. א\\\"א בירושלמי שלא בפניו נאמן בפניו אינו נאמן עכ\\\"ל. וגירסא דידן בירושלמי כך היא אמרו לו שהוא נאמן ה\\\"ז נאמן אמרו לו שאינו נאמן בפניו אינו נאמן שלא בפניו נאמן וטעמא דמילתא דכשאמרו לו בפניו שאינו נאמן ודאי קושטא קאמרי אבל כשאמרו שלא בפניו לישנא בישא הוא ואינם נאמנים להוציאו מחזקתו:\",2,0],[8,355,12,8,\"ומ\\\"ש בד\\\"א בזמן שאינו מכיר אדם שם וכו' עד לא יקח אלא מן המומחה. תוספתא פ\\\"ה דדמאי:\",1,0],[8,355,12,8,\"כתב עוד הראב\\\"ד בד\\\"א בזמן שאינו מכיר אדם וכו' א\\\"א אמת כי התוספתא כך היא וכו'. ק\\\"ל לפי פירוש הראב\\\"ד שמכיר אדם שם פירושו שמכיר אדם מומחה שם היכי קתני סיפא ואם שהה שם שלשים יום אע\\\"פ שאינו מכיר אדם שם לא יקח אלא מן המומחה שאם אינו מכיר מומחה שם היאך יקח מן המומחה וצ\\\"ל דה\\\"ק לא יקח אלא ממי שיאמרו לו הרבה מבני העיר שהוא מומחה וע\\\"פ זה נוכל לפרש גם הרישא דה\\\"ק בד\\\"א שהוא סומך על אחד שיאמר לו איש פלוני נאמן בזמן שאינו מכיר אדם שם אבל אם מכיר אדם שם אינו סומך על אחד שיאמר לו פלוני נאמן אלא על מי שהוא מוחזק למומחה להרבה מבני העיר וטעמו משום דעל ידי אותו שהוא מכיר שהוא מבני העיר יגידו לו האמת שפלוני מומחה בעיני כל בני העיר ולא יהתלו כמו שאפשר שיהתלו בו כשאינו מכיר אדם שם:\",2,0],[8,355,12,9,\"ומ\\\"ש ולא התירו דברים אלו אלא וכו'. בתוספתא דדמאי פרק חמישי:\",1,0],[8,355,12,10,\"החמרים שנכנסו לעיר וכו'. משנה ספ\\\"ד דדמאי (משנה ז') ומייתי לה בפ\\\"ב דכתובות (דף כ\\\"ד) למירמי מינה דרבנן אדרבנן דסברי התם דאין לחוש לגומלין ותירצו בשכלי אומנותו בידו ומדברי רבינו כאן שלא התנה כן נראה שהוא מפרש כפיר\\\"ח דאמתניתין דהתם קאי שאותו שאומר עליו שהוא כהן מביא כלים שמשתמשים בהם בטהרה כמו כלי גללים וכל אחד נזהר מלטמא אותו ולכך נאמן אלא שבפ\\\"ב מהא\\\"ב כתב דין אותה ברייתא ולא התנה בה כן ולכן צ\\\"ל שסובר רבינו דכי מסקינן בתר הכי דרבי יהודה ורבנן במעלין מתרומה ליוחסין קמיפלגי מיתרצא נמי קושיא דרבנן אדרבנן ולא צריכים תו לאוקמא בשכלי אומנותו בידו:\",1,0],[8,355,12,11,\"המוכר פירות בסוריא וכו'. משנה ספ\\\"ו דדמאי (מי\\\"א):\",1,0],[8,355,12,11,\"כתב הראב\\\"ד מפני שרוב פירות שבסוריא וכו' ורבינו בפירוש המשנה כתב הטעם מפני שלא גזרו דמאי על הקונה פירות מפירות סוריא אלא א\\\"כ ידוע שהפירות מקרקע ישראל:\",2,0],[8,355,12,11,\"ומ\\\"ש והיה רוב ממכרו משדהו וכו'. שם בירושלמי והוא שיהא רוב מכנסו משלו:\",3,0],[8,355,12,12,\"עניים שאמרו פירות אלו של לקט שכחה ופאה וכו' עד ירק מבושל מקדרתו לעני. משנה בפרק בתרא דפאה (מ\\\"ב) ויש בספר רבינו חסרון וכך צריך להגיה כיצד חטים אלו לקט שכחה ופאה הם הרי אלו נאמנים קמח זה של לקט שכחה ופאה הוא אינם נאמנים ואין צ\\\"ל שאינם נאמנים על הפת וכן נמצא בספר מוגה.\",1,0],[8,355,12,12,\"ומ\\\"ש והוא שיהיה קרוב מן הגורן וכו' שם בירושלמי:\",2,0],[8,355,12,15,\"ומ\\\"ש וכן בן לוי שאמר פירות אלו ממעשר שניטלה תרומתו וכו' אבל אין נאמן עליו לפוטרו ממעשר שני. שם בירושלמי:\",1,0],[8,355,12,16,\"אין כל הדברים האלו אמורים וכו' אבל מי שהוא חשוד למכור תרומה וכו'. משנה בפרק עד כמה (בכורות דף ל') וכר״ש משום דרבא עבד עובדא כוותיה:\",1,0],[8,355,12,16,\"ומה שכתב אפילו קרבי דגים וכו'. שם בגמרא.\",2,0],[8,355,12,16,\"ומ\\\"ש ואין אסור אלא כל שלפניו אבל אצרו מותר וכו'. בספ\\\"ב דע\\\"ז (דף ל\\\"ט מ').\",3,0],[8,355,12,16,\"ומ\\\"ש וכן החשוד למעשר שני וכו'. הכי משמע מדתני ר\\\"ש כל שיש בו זיקת תרומה ומעשרות אין לוקחין ממנו דאשני מעשרות קאי.\",4,0],[8,355,12,16,\"ומ\\\"ש וכל זה קנס מדבריהם. אע\\\"פ שבירושלמי בסוף מעשרות אמרו דלרבי יהודה דפליג אר\\\"ש משום קנס הוא לאו למימרא דלרבי שמעון לא הוי קנס דודאי לכ\\\"ע משום קנס הוא אלא דלרבי יהודה הוי קנס מרובה ולרבי שמעון הוי קנס מועט:\",5,0],[8,355,12,17,\"חשוד שהעיד על של אחרים וכו'. משנה פרק חמישי דבכורות (דף ל\\\"ה) וכרשב\\\"ג וקי\\\"ל כל מקום ששנה רשב\\\"ג במשנתנו הלכה כמותו ועוד דבפרק בתרא דיומא (דף ע\\\"ח) איפסיקא הלכתא כרשב\\\"ג:\",1,0],[8,355,12,17,\"ומ\\\"ש לפיכך ע\\\"ה שאמר זה טבל וכו' אפילו בשלו נאמן. כתב הראב\\\"ד אין דבר זה מחוור שהרי הנכנס לעיר וכו'. ויש לומר לדעת רבינו מה שהקשו בגמרא ועד אחד נאמן משום דמתניתין מיתניא סתמא ומשמע דאתיא ככ\\\"ע מקשה דלא אתיא כרבי מאיר ומשני דמודה רבי מאיר בההיא משום חיי נפש לומר דמצי אתיא ככ\\\"ע ואין זה ענין לפסק דין. ומ\\\"ש ואם קבעו הלכה כרשב\\\"ג וכו' רומז לההיא דסוף יומא דלענין מטיל מום בבכור איתמרא וי\\\"ל דא\\\"כ הו\\\"ל לפרושי דלא פסק הלכה כרשב\\\"ג אלא בהא ורשב\\\"ג משמע ודאי דבכל איסורים נמי קאמר דנאמן על של חבירו ומדר\\\"מ דאמר החשוד על הדבר לא מעידו דמשמע דבכל דבר קאמר נשמע לרשב\\\"ג דאמר נאמן על של חבירו דבכל דבר קאמר הלכה כמותו וסתם לן תנא דבכורות כר\\\"מ י\\\"ל דהא סתם ואח\\\"כ מחלוקת הוא סתם בספ\\\"ד ומחלוקת בפ\\\"ה וכל סתם ואח\\\"כ מחלוקת אין הלכה כסתם:\",2,0],[8,355,12,18,\"המוכר פירות לחבירו וכו'. עי' במה שכתבתי בסוף ה' פסולי המוקדשין:\",1,0],[8,355,13,1,\"פירות שחזקתן מן ההפקר כגון השיתין וכו'. משנה פרק קמא דדמאי (משנה א'):\",1,0],[8,355,13,1,\"ומ\\\"ש והן שעדיין לא הטילו שאור. שם בירושלמי וכחכמים ופירוש משיטילו שאור כתב רבינו בפירוש המשנה פ\\\"ק דמעשרות משיתרפו ויתנפחו כלחם החמץ כי זה מנהג התמרים בעת הבישול:\",2,0],[8,355,13,1,\"ומ\\\"ש אפי' א\\\"ל ע\\\"ה אינם מעושרים וכו'. שם בירושלמי וכרבי יוחנן:\",3,0],[8,355,13,2,\"הבכורות והסייפות וכו'. שם בירושלמי. ומה שחילק בין בקעה לגינה שם בתוספתא:\",1,0],[8,355,13,2,\"וכן החומץ העשוי מן התמדים גרסינן בדלי\\\"ת והוא שם משנה וירושלמי ומשמע התם דהיינו דוקא במקום שאין החרצנים חשובים ומפקירים אותם או בשלא מצא אלא כדי מדתו:\",2,0],[8,355,13,3,\"כשגזרו על הדמאי וכו'. פ\\\"א משנה שם (משנה ג') מכזיב ולהלן פטור מן הדמאי ובירושלמי שם הלכה ג' אמר רבי יוחנן בשעה שגזרו על הדמאי לא גזרו על דברים הללו.\",1,0],[8,355,13,3,\"ומ\\\"ש וכזיב עצמה כלחוץ. שם בירושלמי:\",2,0],[8,355,13,3,\"וכל הפירות הנמצאות מכזיב ולחוץ וכו':\",3,0],[8,355,13,4,\"פירות שידוע שהן מפירות הארץ וכו'. משנה ברפ\\\"ב דדמאי (משנה א') ואלו דברים מתעשרים דמאי בכל מקום הדבילה והתמרים והחרובין האורז והכמון ובירושלמי חיוב המינין האלו על ידי שאין כיוצא בהן בח\\\"ל צרכו חכמים למנותן והא דבילה בבצרה שחיקה היא והא תמרי' באלכסנדריא דקיקין אינון והא חריב בבאירי גידוד הוא והא אורז בחולתא אבתר הוא סימוק הוא והא כמון בקיפרוס עקום הוא.\",1,0],[8,355,13,4,\"ומ\\\"ש רבינו מתעשרים דמאי בכל ארץ ישראל ובסוריא כלומר דהיינו פי' בכל מקום דקתני מתניתין אבל בח\\\"ל לא כמ\\\"ש בפ\\\"א מהלכות תרומות שפירות א\\\"י שיצאו חוצה לארץ פטורים:\",2,0],[8,355,13,5,\"החמרים שהביאו פירות לצור וכו'. ירושלמי פ\\\"ק דדמאי הלכה ג':\",1,0],[8,355,13,5,\"והאורז אין חוששין לו וכו'. משנה רפ\\\"ב דדמאי (מ\\\"א) האורז שבח\\\"ל כל המשתמש ממנו פטור:\",2,0],[8,355,13,6,\"הלוקח מבעלי אוצרות בצור וכו'. ירושלמי פ\\\"ק דדמאי:\",1,0],[8,355,13,6,\"וכן חמור יחידי וכו'. גם זה ירושלמי שם:\",2,0],[8,355,13,7,\"הלוקח מבעלי אוצר בצידון וכו' עד פטור מן הדמאי. גם זה שם בירושלמי:\",1,0],[8,355,13,11,\"הלוקח מן העכו\\\"ם וכו' עד עדיין לא הוחזק תגר. ירושלמי בפ\\\"ד דדמאי:\",1,0],[8,355,13,11,\"כשגזרו על הדמאי וכו'. עד פטורים מן הדמאי. תוספתא פירקא קמא דדמאי וכחכמים:\",2,0],[8,355,13,13,\"לא הלכו חכמים בפירות ח\\\"ל וכו'. תוספתא בסוף מעשרות.\",1,0],[8,355,13,13,\"ומ\\\"ש רבו בעיר וכו' עד ליושנו. תוספתא פ\\\"ד דדמאי:\",2,0],[8,355,13,14,\"ואלו דברים וכו' הלוקח פירות לזריעה וכו'. משנה פ\\\"ק דדמאי (משנה ג')\",1,0],[8,355,13,14,\"ומ\\\"ש או למלוגמא או לרטייה או יין לקילור. תוספתא פ\\\"ק.\",2,0],[8,355,13,14,\"ומ\\\"ש ותוספת הביכורים. משנה בסוף ביכורים (משנה י'):\",3,0],[8,355,13,15,\"הלוקח פירות לאכילה וכו'. פרק קמא דחולין (דף ו') וירושלמי בפרק קמא דדמאי.\",1,0],[8,355,13,15,\"ומ\\\"ש לא ימכרם לעכו\\\"ם. תוספתא פרק קמא דדמאי וכב\\\"ה:\",2,0],[8,355,13,16,\"שמן שלוקח הסורק וכו' עד חייב בדמאי. משנה בסוף פירקא קמא דדמאי (משנה ד'):\",1,0],[8,355,13,17,\"עכו\\\"ם ששאל וכו' עד ואינו חושש. תוספתא פ\\\"ק דדמאי:\",1,0],[8,355,13,18,\"הלוקח יין למורייס וכו'. שם בתוספתא ובפרק קמא דחולין בגמרא עלה ו'.\",1,0],[8,355,13,18,\"ומ\\\"ש שלא גזרו על תערובת דמאי וכו' עד חייבת בדמאי. בפ\\\"ק דחולין:\",2,0],[8,355,13,19,\"כל אלו הפטורים וכו'. חוץ משירי מנחות ירושלמי פרק קמא דדמאי.\",1,0],[8,355,13,19,\"ומ\\\"ש אבל אם תיקן את הדמאי בודאי וכו'. תוספתא פרק רביעי דדמאי פלוגתא דתנאי ופסק כרבי עקיבא:\",2,0],[8,355,13,19,\"וכתב הראב\\\"ד א\\\"א תמה אני וכו'. נראה מדבריו שהוא גורס בדברי רבינו אם תיקן את הדמאי בודאי בבי\\\"ת וכן היה גורס או שתיקן את הודאי בדמאי בבי\\\"ת ומפני כך הוקשה לו ולי נראה שאין לגרוס אלא הודאי כדמאי בכ\\\"ף וה\\\"ק שאם תיקן הדמאי כמו שמתקנים הודאי שמפרישין ממנו תרומה גדולה או שתיקן הודאי כמו שמתקנים הדמאי שאין מפרישין ממנו תרומה גדולה לא עשה כלום וטעמא דרישא דסתם ע\\\"ה מפרישין תרומה גדולה ונמצא שתרומה גדולה שהפריש אינה כלום וטעמא דסיפא פשוט מפני שלא הפריש תרומה גדולה זהו פירוש הירושלמי והתוספתא לדעת רבינו והשתא אין משנתנו ענין לירושלמי ולא לתוספתא ויש לתמוה על הראב\\\"ד איך עלה בדעתו שדברי רבינו כאן הם דין המשנה שהרי דין משנתנו כתבו רבינו בפ\\\"ה מהלכות תרומות ככתב המשנה וכלשונה. ועל מאי דסבר הראב\\\"ד שפירוש התוספתא הוא כדין המשנה קשה איך עלה בדעתו ששני תנאים החולקים בתוספתא הם דלא כמתניתין דאי מתניתין היא סברא שלישית היאך לא נזכרה אותה סברא בתוספתא וע\\\"ק שכתב ולפי התוספתא הלכה כרבי יוסי והא קיימא לן כרבי עקיבא מחבירו ואין לומר דכיון דמשמיה דרבי יצחק קאמר לה הוה ליה תרי דכיון דלא אמרה אלא משמיה כחד חשיבי וע\\\"ק אמאי פסק כרבי יוסי דברייתא ושבק סתם מתניתין והא קיימא לן סתם במתניתין ומחלוקת בברייתא הלכה כסתם וע\\\"ק שאם פירוש התוספתא דמאי שתקנו על הודאי ודאי שתקנו על דמאי כמו שפי' הראב\\\"ד קשה לר\\\"ע דמאי שתקנו על הודאי אמאי לא עשה כלום דאין לומר דטעמא משום דהוי מן הפטור על החיוב דהא איכא למיחש שמא לא הופרש ממנו והוה ליה מן החייב על החייב וכיוצא בזה יקשה בין לרבי עקיבא בין לרבי יוסי בודאי שתקנו על הדמאי אמאי לא עשה כלום וכן קשה לרבי יוסי בדמאי שתקנו על הודאי שנתן טעם למה אין תרומתו תרומה לפי שאין תרומה אחר תרומה ולא ה\\\"ל ליתן טעם אלא משום דסתם עמי הארץ מפרישין תרומה גדולה הוה ליה מן הפטור על החיוב הילכך פירוש רבינו נראה לע\\\"ד שהוא עיקר:\",3,0],[8,355,13,20,\"כל העיר מוכרים ודאי וכו'. תוספתא פרק ד' דדמאי:\",1,0],[8,355,14,2,\"הלוקח מן הסיטון וכו' עד נאמן. משנה פרק חמישי דדמאי (משנה ו'):\",1,0],[8,355,14,2,\"ומה שכתב אע\\\"פ שמכיר את החבית. ירושלמי:\",2,0],[8,355,14,2,\"היה מוכר כשות וכו'. תוספתא פ\\\"ה דדמאי:\",3,0],[8,355,14,4,\"הלוקח מבעל הבית וכו' עד לא יעשר מזה על זה. משנה ז' פרק חמישי דדמאי:\",1,0],[8,355,14,6,\"הלוקח פת וכו' עד משני נחתומין. משנה שם (פ\\\"ה מ\\\"ב) הלוקח מן הנחתום מעשר מן החמה על הצוננת ומן הצוננת על החמה אפילו מטפוסין הרבה דברי רבי מאיר רבי יהודה אוסר שאני אומר חטים של אמש משל אחד ושל היום משל אחר וכו'. הלוקח מן הפלטר מעשר מכל טפוס וטפוס דברי רבי מאיר רבי יהודה אומר מאחד על הכל מודה ר' יהודה בלוקח מן המנפול שהוא מעשר מכל אחד ואחד ופירש רבינו ר' יהודה אוסר אפילו יהיה הכל עשוי בדפוס אחד שהוא חושש שמא יהיה זה הלחם מחטה ישנה וזה האחר מחטה חדשה והעיקר בידינו אין מעשרין מן החדש על הישן ולא מן הישן על החדש וכתב עוד מי שילוש הקמח ועושה אותה ככרים ויאפהו נקרא נחתום והלוקח מן הנחתום למכור לבני אדם נקרא פלטר וכו' ורבי מאיר אומר שהנחתום יתקנהו בדפוס אחד יהיה קטן או גדול וכשנמצא אצל הפלטר דפוסים הרבה משתנים זה מזה נדע שהוא לקח מאנשים רבים וע\\\"כ מעשר מכל דפוס ודפוס לפי שלכל דפוס מין ממיני הזרע ורבי יהודה אומר כי הנחתום בעצמו המתקן הלחם אפשר שיעשה מעיסה אחת מינים הרבה מן הלחם בדפוסים משתנים זה מזה לפיכך אלו הדפוסים המשתנים אשר נמצאו אצל פלטר זה מאיש אחד לקחם. ופירוש מנפול הוא מוכר הלחם כמו כן אבל הוא קונה משני נחתומים שלא יכירם כגון שיהיו ט' מוכרים ועשרה נחתומים נותנים להם הלחם ואין ספק שאחד מאלו הט' מוכרים לקח משנים על כן כל מי שלוקח מאחד מהם מעשר מכל דפוס ודפוס והלכה כר' יהודה עכ\\\"ל. וצ\\\"ל דהא דשרי רבי יהודה בלוקח מן הפלטר לעשר מאחד על הכל משום דמחד נחתום זבין היינו בשכולם משל אמש או משל היום אבל אם קצתו משל אמש וקצתו משל היום לא דלא עדיף מנחתום גופיה:\",1,0],[8,355,14,7,\"תשעה מנפולין שלקחו מעשרה וכו'. ירושלמי שם:\",1,0],[8,355,14,8,\"הלוקח מן העני וכו' עד מכל מתנה ומתנה. משנה שם פרק חמישי (משנה ה') ופירש רבינו בולל ונוטל הוא שיערב הכל ויוציא המעשר מהכל וזה יהיה כשיתנו לו הרבה לפי שנאמר מאחר שזה הנותן נתן מתנה גדולה איש נדיב הוא ולא יקשה בעיניו המעשר ונאמר שעכ\\\"פ הוציא המעשרות ויתעשר הכל דמאי [ואם] היתה מתנה מועטת נחשוב עליו שהוא כילי ולא עישר ולפיכך לא יתערב הכל שמא יפריש מדמאי על הודאי ורבינו שמשון פירש בולל דורס התמרים או הגרוגרות ומערבן יחד והם נבללים ומתערבים ונמצא מפריש מן החיוב על החיוב דקסבר יש בילה בדבר היבש אבל פרוסת פת ופלחי דבילה אין נבללין ואתי להפריש מן הפטור על החיוב בזמן שמתנה מרובה בזמן שהכל נותנים מתנה מרובה שכל המתנות שוות אז מועלת בילה אבל בזמן שהמתנה מועטת כלומר שמתנה אחד מעוטה מחבירתה לא מהני בילה דדילמא כל חד וחד לא מתרמי דיליה וחיישינן שמא מן הרוב מפריש על המועט כך נראה פירוש משנה זו בירושלמי:\",1,0],[8,355,14,10,\"שחק את הפת ועשאה וכו'. תוספתא שם:\",1,0],[8,355,14,10,\"פועלים או אורחים וכו'. גם זה שם בתוספתא:\",2,0],[8,355,14,10,\"סליקו להו הלכות מעשר\",3,0],[8,356,1,1,\"אחר שמפרישין וכו' ובשנה שלישית וששית מפרישין מעשר עני וכו'. פירקא קמא דראש השנה עלה י\\\"ב:\",1,0],[8,356,1,1,\"ומ\\\"ש כמו שביארנו. הוא בפרק ששי ממתנות עניים:\",2,0],[8,356,1,2,\"באחד בתשרי הוא ר\\\"ה וכו'. משנה שם:\",1,0],[8,356,1,2,\"ומה שכתב ובט\\\"ו בשבט הוא ראש השנה למעשר האילנות. ג\\\"ז שם במשנה:\",2,0],[8,356,1,3,\"והחרובין אע\\\"פ שחנטו פירותיהם וכו'. שם עלה ט\\\"ו ע\\\"ב ת\\\"ר אילן שחנטו פירותיו וכו' עד אם קיבלה אם לא קיבלה:\",1,0],[8,356,1,3,\"ומ״ש רבינו יראה לי שאין הדברים אמורים וכו': כתב הראב״ד אין סברתו נכונה וכו'. וי״ל דרבינו לטעמיה דסבר דכל הדומה לדגן תירוש ויצהר חייב בתרומה ומעשרות מן התורה כדמשמע מדבריו בפ״ב מהלכות תרומות אבל קשה הא דאמרינן ר״פ כיצד מברכין (ברכות דף ל״ו) ה״א ה״מ במעשר אילן דבארץ גופה דרבנן ושמא י״ל שיפרש רבינו דהתם בפירות גרועים דוקא דומיא דצלף דביה איירי התם דלא הוי דומיא דתירוש ויצהר. ומ״ש שלא חילקו אלא בין מעשר לשביעית וכו' כלומר דאיכא מ״ד התם אתרוג בת ששית שנכנסה לשביעית פטורה מן המעשר ופטורה מן הביעור. ומה שכתב ואם כדבריו מה ענין בנות שוח וכו' טעמו שאם כדברי רבינו דהא דאמר רבי נחמיה והחרובין שחנטו פירותיהם וכו' בחרובי צלמונה שהם גרועות הדברים אמורים אם כן מאי מותיב ר״ל מבנות שוח ולי קשה עוד דקתני רבי נחמיה כגון דקלים וזיתים וחרובין קתני חרובין דומיא דדקלים וזיתים שאינם פסולת מינם ואפשר דה״ק רבינו יראה לי שמה שנהגו העם כרבי נחמיה בחרובין לא נהגו כן אלא בחרובי צלמונה וכיוצא בהן וכו' שאע״פ שרבי נחמיה בכל פירות האילן שעושין בריכה אחת אמרה לא נהגו כמותו אלא בחרובין ולא בכל החרובין אלא בחרובי צלמונה:\",2,0],[8,356,1,4,\"הירק בשעת לקיטתו עישורו וכו':\",1,0],[8,356,1,5,\"וכן האתרוג בלבד וכו'. משנה פרק שני דבכורים (משנה ו') וכרבן גמליאל ואיתיה בפ\\\"ק דר\\\"ה (דף ג' וי\\\"ד):\",1,0],[8,356,1,6,\"ואע\\\"פ שהולכין אחר לקיטתו וכו'. פ\\\"ק דר\\\"ה עלה ט\\\"ו וכרבי יוחנן:\",1,0],[8,356,1,6,\"כתב הראב\\\"ד כמה דבריו מבולבלים וכו'. טעמו לומר שהוא ז\\\"ל מפרש דע\\\"כ לא אמרו ר\\\"י ור\\\"ל בת ששית שנכנסה לשביעית לעולם ששית דאזלי בתר חנטה אלא לענין אם הוא טבל ואם פטורה מן הביעור ולא איירו לענין אם מפריש מעשר שני או מעשר עני דבהא נקטינן כר' יוסי דאמר אבטולמוס העיד משום חמשה זקנים אחר לקיטתו למעשר ופי' רש\\\"י למעשר לענין שניה נכנסת לג' או שלישית נכנסת לרביעית ורבינו סובר דכיון דסמוך להא דרבי יוסי איתמר הא דר\\\"י ור\\\"ל בההוא גוונא דרבי יוסי מיירו ופסק כוותייהו:\",2,0],[8,356,1,7,\"האביונות של צלף וכו'. ירושלמי ספ\\\"ד דמעשרות אביונות נותנים עליהם וכו':\",1,0],[8,356,1,7,\"כתב הראב״ד שנה זה המחבר כב״ש וכו'. טעמו מדגרסינן בר״פ כיצד מברכין (ברכות דף ל״ו) אמר רב יהודה אמר רב צלף של ערלה וכו' עד וב״ש במקום ב״ה אינה משנה וכיון דלב״ה אינו כלאים בכרם ה״ל ודאי אילן ודינו כשאר פירות האילן למ״ש ומ״ע ולפי זה הירושלמי הזה אתי כב״ש ולית הלכתא כוותיה ורבינו סובר שהירושלמי זה אפילו כב״ה אתי דאע״ג דס״ל דהוי כאילן ה״מ לכלאים ולערלה אבל לענין מעשר שני ומעשר עני החמירו בו וטעמא משום דכיון דאין בדבר זה הפסד החמירו בו ולשון הירושלמי מוכיח כן שכתב וליידא מלה כלומר לאי זה דבר נתנו עליהם חומרי זרעים משמע בהדיא דלא נתנו עליו חומרי זרעים אלא לדבר זה בלבד:\",2,0],[8,356,1,8,\"האורז והדוחן וכו'. בפירקא קמא דראש השנה (דף י\\\"ג ע\\\"ב) תנן התם האורז והדוחן וכו' ופסק כשמואל דאמר הכל הולך אחר גמר פרי:\",1,0],[8,356,1,8,\"ומ\\\"ש וכן פול המצרי אע\\\"פ שמקצתו השריש וכו'. שם פסק שמואל הלכה כר\\\"ש שזורי דאמר הכי וכתב הראב\\\"ד אם הכל הולך אחר גמר הפרי וכו'. ולכאורה נראה לתמוה שאם קושיא זו קושיא דשמואל אדשמואל ה\\\"ל לאקשויי דאמר הכל הולך אחר גמר פרי ואיהו גופיה אמר הלכה כר\\\"ש שזורי דאמר פול המצרי שמקצתו השריש לפני ר\\\"ה ומקצתו לאחר ר\\\"ה צובר גורנו לתוכו אבל לפי האמת אין כאן קושיא שהרי פירש\\\"י וכי אמר שמואל הלכה כר\\\"ש שזורי לא מטעמיה קאמר דאילו ר\\\"ש שזורי טעמיה משום בילה וטעמא דשמואל משום דכוליה חדש הוא שגדל ונגמר אחר ר\\\"ה עכ\\\"ל וכך הוא מוכרח בגמרא וכך מבואר בדברי רבינו ואפשר דודאי דפשיטא להראב\\\"ד הוא ולא בא להשיג על רבינו אלא מפני שתפס לשון צובר גורנו לתוכו שלשון זה לא יצדק אלא למאן דסובר דבתר השרשה אזלינן ואם יתרום מזה על זה ה\\\"ל תורם מן החדש על הישן ולפיכך צובר גרנו לתוכו כלומר יבלול אותו יפה לאחר שנתן מן הראשון בזוית זו ומן השניה בזוית זו יחזור ויצברנו לאמצע הגורן כדי שיהיה כולו כאחד נבלל יחד יפה נמצא כשיתרום ויעשר יהא מן החדש במעשר לפי מה שיש חדש בגורן ומן הישן לפי מה שיש ישן וכדפירש\\\"י. וי\\\"ל שרבינו מפרש לשון צובר גרנו לתוכו דהיינו לומר שאע\\\"פ שלא יפריש מכל אחד לבדו אלא שצובר כל גרנו לתוכו ונמצא מעושר מזה על זה שפיר דמי לר\\\"ש שזורי משום דיש בילה ולשמואל משום דכוליה חדש הוא. ומ\\\"מ שותא דמרן הראב\\\"ד ז\\\"ל לא ידענא דסיים בה דהא קי\\\"ל דאין בילה אלא ליין ושמן וזה אינו ענין למ\\\"ד הכל הולך אחר גמר פרי ושמא י\\\"ל דחדא ועוד קאמר חדא שאם הכל הולך אחר גמר פרי אין צריך לצבור גרנו לתוכו ואת\\\"ל דלא אזלינן בתר גמר פרי אלא בתר השרשה כי צובר גרנו לתוכו מאי הוי הא קי\\\"ל דאין בילה אלא ליין ושמן וכבר יישבתי דברי רבינו:\",2,0],[8,356,1,9,\"הבצלים הסריסים וכו'. משנה פרק שני דשביעית (משנה ט') וכחכמים.\",1,0],[8,356,1,9,\"ומ\\\"ש אע\\\"פ שהתחילו ליבש וכו':\",2,0],[8,356,1,10,\"פול המצרי שהביא שליש לפני ר\\\"ה וכו' עשה קצצין גמורין וכו' עד ומירקו על זרעו. פירוש קצצין גמורין כתב הר\\\"י קורקוס ז\\\"ל דהיינו שנתמלא השבולת כל צרכה והוא יותר מתרמלו:\",1,0],[8,356,1,10,\"כתב הראב\\\"ד פול המצרי שהביא שליש וכו'. א\\\"א והוא שליקט לפני ר\\\"ה וכו'. והנה נוסחת ספרי הירושלמי שבידינו הוא כנוסחת רבינו ואע\\\"פ שבתוספתא אמרו על פול המצרי לא שמענו מאחר שבירושלמי פירשו כל משפטיו למה לא נפסוק כמותו. ומ\\\"ש אף כי מצא ספרים משובשים מאן נימא לן שנוסחת רבינו משובשת ואולי מפני מ\\\"ש בהשגות שאחר זה כתב שמצא ספרים משובשים ושם איישב נוסחת רבינו. ומ\\\"ש ומסתבר אפילו זה הפול ככסבר ושבת הוא תמהני מאחר שבירושלמי איבעיא ולא איפשיטא היכי פשיט לה איהו ז\\\"ל:\",2,0],[8,356,1,10,\"כתב עוד הראב\\\"ד והוא שליקט ממנו לפני ר\\\"ה א\\\"א הירושלמי שהעתיק ממנו משובש וכו' וי\\\"ל שרבינו מפרש הא דאמר שמואל בפ\\\"ק דר\\\"ה שהולכים אחר גמר פרי גמר פרי גמור קאמר וכן נראה מדברי התוספות שם.\",3,0],[8,356,1,10,\"ועל מ\\\"ש רבינו שלש אריות וכו' כתב הראב\\\"ד לא ידענו מהו אריות ופירש דהיינו לקיטות.\",4,0],[8,356,1,10,\"ועל מ\\\"ש רבינו אם לא הביאו וכו' עד אע\\\"פ שלא נמנעו. כתב הראב\\\"ד נ\\\"ל שהוא שבוש וכו' ולע\\\"ד נראה דאין כאן שיבוש וה\\\"ק הא דבעינן שימנע ממנו ג' אריות דוקא בשהביא שליש לפני ר\\\"ה אבל אם לא הביא שליש אלא לאחריו לא בעינן שימנע ממנו ג' אריות. ומ\\\"ש והטעם שאין מחשבת זרע חלה וכו' הוא ע\\\"פ גירסתו ופירושו. ומ\\\"ש אמת הוא כך מצא בירושלמי וכו' י\\\"ל שטעם רבינו לסמוך על הירושלמי יותר מעל התוספתא משום דלא ידעינן אי מיתניא בי רבי חייא ורבי אושעיא:\",5,0],[8,356,1,11,\"פירות שנה שנייה וכו'. משנה פ\\\"ב דמכשירין (משנה י\\\"א) ולשון המשנה הולכים אחר הרוב [להקל] מחצה למחצה להחמיר וכתב רבינו מפריש מעשר שני מן הכל אבל לא מ\\\"ע וכו' כך כתב רבינו בפירוש המשנה הנזכרת על מחצה על מחצה להחמיר והכי תנן בפ\\\"ד דידים דמעשר שני הוי להחמיר לגבי מעשר עני:\",1,0],[8,356,1,11,\"וכתב הראב\\\"ד ולמה לא יפריש מ\\\"ע וכו' ובאמת דברי רבינו תמוהים ור\\\"ש פירש כהראב\\\"ד שיפריש מעשר אחד ויחלל המעשר על מעות והפירות יחלק לעניים והמעות יאכל בירושלים והיינו שני עישורים דר\\\"ע דפ\\\"ק דעירובין ופרק קמא דר\\\"ה. ועל מ\\\"ש הראב\\\"ד אפילו אחר הרוב אין לילך באיסורי טבל כתב הר\\\"י קורקוס ז\\\"ל לא ידעתי איך הקשה כן דאם זה נקרא טבל תיקשי ליה אמתני' דמכשירין שאמרה בהדיא דהולכים אחר הרוב לכן אני אומר דאין נקרא טבל אלא בשלא הוציא כל מה שצריך להוציא אבל זה כבר הוציא כל מה שצריך להוציא אלא שהמעשר שהוציא הוא ספק אם הוא שני או עני ומאחר שהוציא כל מה שצריך להוציא לא נשאר בו טבל וכיון שנסתלק מכאן דין טבל אלא שאנו מסופקים מעשר זה מה יעשה בו מותר לעשות חול קדש ולא קדש חול וזהו פירוש מה שאמרו הולכים להחמיר ולדעת הר\\\"א והר\\\"ש ה\\\"ל לפרש ולומר מפריש שניהם אבל לשון הולכים להחמיר משמע דאחר אחד מהם אנו הולכים אלא שהולכים אחר החמור והוא השני שצריך לאוכלו בקדושה כך נ\\\"ל לדעת רבינו ונראה חילוק נכון ומוכרח שאם המועט נשאר טבל כדברי הר\\\"א איך אמרו הולכין אחר הרוב דטבל לא בטיל עכ\\\"ל ומשום דקשיא ליה ההיא דפ\\\"ק דר\\\"ה דר\\\"ע הפריש שני עישורין כתב לחלק ביניהם:\",2,0],[8,356,1,11,\"וכן פירות שהם ספק וכו'. נלמד ממה שקדם בסמוך:\",3,0],[8,356,1,12,\"כל הפטור ממעשר ראשון וכו':\",1,0],[8,356,1,13,\"פירות שהוציא מהם מעשר ראשון וכו'. ירושל' דמעשרות פ\\\"ב:\",1,0],[8,356,1,14,\"מעשר שני הואיל וטעון הבאת מקום וכו' לפיכך לא חייבו להפריש מעשר שני בסוריא. בפ' בתרא דבכורות (דף נ\\\"ג) לימא מתניתין דלא כר\\\"ע דתניא ר\\\"ע אומר יכול יעלה אדם מעשר בהמה מח\\\"ל לארץ (בזמן שב\\\"ה קיים) ויקריבנו ת\\\"ל והבאתם שמה עולותיכם וזבחיכם ואת מעשרותיכם בשני מעשרות הכתוב מדבר אחד מעשר בהמה ואחד מעשר דגן מקום שאתה מעלה מעשר דגן אתה מעלה מעשר בהמה וממקום שאי אתה מעלה וכו' אפילו תימא ר\\\"ע כאן ליקרב כאן ליקדש ובפ\\\"ג דתמורה (דף כ\\\"א) רבי ישמעאל אומר יכול יעלה אדם מעשר שני ויאכלנו בירושלים ודין הוא בכור טעון הבאת מקום ומעשר טעון הבאת מקום וכו' אף מעשר אינו נאכל אלא בפני הבית בן עזאי אומר יכול יעלה אדם מעשר שני ויאכלנו בכל הרואה וכו' אף מעשר אינו נאכל אלא לפנים מן החומה ואע\\\"ג דלגבי הבאה מח\\\"ל בכור יליף ממעשר כמבואר בדברי ר\\\"ע ורבינו תלה כאן מעשר בבכור אלא רצה לכלול רבינו גם דברי רבי ישמעאל ודברי בן עזאי כלומר הואיל וטעון הבאת מקום וכו' ולמד מן בכור אסמכתא למעשה דרבנן שלא יעלו אותו מח\\\"ל דאילו מן התורה אין מעשר בח\\\"ל וז\\\"ש לפיכך לא חייבו וכו' כלומר כי היכי דבכור אין מעלין אותו גם מעשר אין מפרישין אותו ולפיכך לא חייבו ומה שחייבו בשנער ומצרים מפני מעשר עני ומ\\\"מ לא יעלה אותו עד שיפדנו מאסמכתא דבכור כך נ\\\"ל ביאור דברי רבינו עכ\\\"ל הר\\\"י קורקוס ז\\\"ל:\",1,0],[8,356,1,14,\"כתב הראב\\\"ד אין הטעם הזה מספיק וכו'. כתב הר\\\"י קורקוס ז\\\"ל אפשר שאעפ\\\"כ מספיק הוא דבשלמא בבכור אפשר לומר בו יאכל במומו אבל במעשר שני טעון הבאת מקום ואם יפרישו יהיו צריכין להעלותו ואנן קי\\\"ל דאין מביאין אותו מח\\\"ל לכך לא חייבו בסוריא ובמצרים ובשנער חייבו מפני שהיו עניי ישראל מצויים שם ויפדנו ויעלה פדיונו אבל בסוריא נראה שלא היו עניים מצויים שם וגם שיטעו ויסברו שהיא כשאר א\\\"י ויעלו המעשר עצמו. ומה שרצה לומר שמה שאמרו אין מע\\\"ש בסוריא מן התורה קאמר וגזרו מעשרות ולא נטע רבעי אינו משמע כן פ\\\"ה דמעשר שני גם פ\\\"ז דפאה כי שם אמרו לא למדו נטע רבעי אלא ממעשר כמה דתימא אין מעשר שני בסוריא כך אין נטע רבעי בסוריא מוכח בהדיא דשקולים הם עכ\\\"ל:\",2,0],[8,356,2,1,\"מעשר שני נאכל לבעליו לפנים מחומת ירושלים. משנה בסוף זבחים (דף קי\\\"ב:) ובפרק אלו הן הלוקין.\",1,0],[8,356,2,1,\"ומה שכתב ונוהג בפני הבית ושלא בפני הבית אבל אינו נאכל בירושלים אלא בפני הבית וכו' מפי השמועה למדו וכו'. פ' אלו הן הלוקין (מכות דף י״ט). כתב סמ״ג על מ״ש רבינו אף מע״ש לא יאכל אלא בפני הבית ובספר התרומה כתב שאם הפירות לא הוכשרו שמותר אף בזמה״ז לאכלן בירושלים לא ידעתי מניין לו ע״כ. ואיני יודע מאי קשיא ליה שרבינו מביא ראיה מהפסוק שאינו נאכל אלא בפני הבית וכי לא הוכשר מאי הוי:\",2,0],[8,356,2,2,\"מדת חסידות שפודין מעשר שני וכו' והורו הגאונים שאם רצה לפדות שוה מנה בפרוטה לכתחלה בזמן הזה פודה וכו'. דין ההקדש פרק המקדיש ופרק הזהב:\",1,0],[8,356,2,2,\"ועל מ\\\"ש ומשליך הפרוטה לים הגדול. כתב סמ\\\"ג אבל לשאר נהרות צריך לשחקה בתחלה כדאיתא בפ' כל שעה:\",2,0],[8,356,2,3,\"ועל מ\\\"ש רבינו וכן אם חילל מע\\\"ש שוה מנה על ש\\\"פ מפירות אחרות. כתב הראב\\\"ד תמה אני אם אמרו הגאונים וכו'. ברפ\\\"ד יתבאר טעמו וטעם רבינו ומ\\\"מ מה שכתב הראב\\\"ד שרבינו תלה זה בדברי הגאונים אין נראה כן מדברי רבינו שלא כתב בשם הגאונים אלא שאם רצה לפדות שוה מנה בפרוטה פודה:\",1,0],[8,356,2,4,\"כשם שאין אוכלים מעשר שני וכו' עד לפיכך אין מפרישין מעשר שני בירושלים בזמן הזה. תוספתא פ\\\"ג דמעשר שני ונראה לי דהא דאין פודין אותו שם היינו דוקא במעשר שלא נטמא אבל אם נטמא פודים אותו בירושלים כמו שכתב לקמן בסמוך ובפ\\\"ג ומתניתין היא בפ\\\"ב דמעשר שני. וכתב הטור מעשר שני בזה\\\"ז מותר להכשירו כדי שיטמא והכי אמרינן בירושלמי פרק שלישי דמעשר שני הלכה ששית רבי פנחס מסאב לה ופדי לה.\",1,0],[8,356,2,4,\"ומה שכתב רבינו מוציאין את הפירות בטבלן חוץ לעיר ומפרישין אותו שם ופודהו. שם אמר רבי זעירא רבי חנינא ורבי יונתן וריב\\\"ל עלו לירושלים נתמנו להם פירות ובקשו לפדותן בגבולין אמר לון חד סבא אבוכון לא הוון עבדין כן אלא מפקן חוץ לחומה ופודים אותן שם:\",2,0],[8,356,2,5,\"כל האוכל כזית מעשר שני וכו' לוקה כו'. משנה פ' אלו הן הלוקין (מכות דף י״ג):\",1,0],[8,356,2,5,\"ומ\\\"ש ולוקה על כל א' וא' בפני עצמו וכו'. שם ופ\\\"ק דכריתות:\",2,0],[8,356,2,6,\"אינו לוקה מן התורה וכו'. פרק אלו הן הלוקין (מכות דף י״ט:) א״ר אסי אמר רבי יוחנן מעשר שני מאימתי חייבים עליו משיראה פני החומה מ״ט דאמר קרא לפני ה' אלהיך תאכלנו וכתיב לא תוכל לאכול בשעריך כל היכא דקרינן ביה לפני ה' אלהיך תאכלנו קרינן ביה לא תוכל לאכול בשעריך וכל היכא דלא קרינן ביה לפני ה' אלהיך תאכלנו לא קרינן ביה לא תוכל לאכול בשעריך (וקודם מימרא זו איתא התם) אמר רב ביבי אמר רב אסי מניין למע״ש טהור שפודין אותו אפילו בפסיעה אחת סמוך לחומה שנאמר כי לא תוכל שאתו והקשו התוספות א״כ שמותר לאכול כל שלא נכנס לפנים מן החומה למה הוזקק לפדות לעולם מע״ש ותירצו דאע״ג דליכא לאו מ״מ עשה איכא דכתיב וצרת הכסף אבל לא בלא פדייה וזהו מכת מרדות שכתב רבינו:\",1,0],[8,356,2,7,\"מקצת מעשר בפנים וכו'. שם לענין בכורים וילפינן מינה למעשר שני:\",1,0],[8,356,2,8,\"אין פודין מעשר שני בירושלים. במשנה פרק כיצד צולין (פסחים דף ע״ה):\",1,0],[8,356,2,8,\"ומ״ש אא״כ נטמא וכו'. בפרק אלו הן הלוקין (מכות דף י״ט:) אר״א מניין למעשר שני שנטמא שפודין אותו אפילו בירושלים ת״ל כי לא תוכל שאתו ואין שאת אלא אכילה:\",2,0],[8,356,2,8,\"ומ\\\"ש היה הוא בפנים וכו'. שם בעיא ופשטוה מדכתיב כי ירחק ממך המקום ממילואך פי' מלואך משאך ומפרש דה\\\"ק אפילו לא יהיה המקום רחוק אלא משאך ה\\\"ז נפדה:\",3,0],[8,356,2,8,\"ומ\\\"ש אפילו היה אוחז אותו בקנה וכו'. שם בעי' עלתה בתיקו ואמרינן בתר הכי (דף כ') רבינא אמר כגון דנקיט ליה בקניא ותפשוט בעיא דרב פפא ונראה שרבינו מפרש דהיינו לומר דהא דדייקנא הא בגבולין לוקה ג' בדעייליה ואפקיה ואקשינן א\\\"ה מאי למימרא איצטריך כגון דכי אפקיה נקיט ליה בקניא וקמ\\\"ל דדינו כאילו אפקיה לגמרי וה\\\"ה לרב פפא דהוי כאילו לא נכנס כלל ורש\\\"י פי' בהיפך:\",4,0],[8,356,2,9,\"מעשר שני שנכנס לירושלים. משנה פ\\\"ג דמ\\\"ש וכת\\\"ק (משנה ה'):\",1,0],[8,356,2,9,\"ומ\\\"ש אפילו של דמאי וכו'. יש לתמוה דהא תני בפ\\\"ק דדמאי הדמאי אין לו חומש וכו' ונכנס לירושלים ויוצא ורבינו עצמו כתב לקמן בסמוך וכן פירות דמאי אע\\\"פ שנגמרה מלאכתן ועברו בירושלים פודין מע\\\"ש שלהם בחוץ. ומצאתי בפ\\\"ג דמעשר שני ירושלמי (הלכה ד') על משנת פירות שנגמרה מלאכתן ועברו בתוך ירושלים יחזור מע\\\"ש שלהם ויאכל בירושלים א\\\"ר זעירא ובלבד בפירות שהן טבולין לדמאי הא דמאי עצמו כבר תפסתו מחיצה פירוש הא דמאי עצמו מעשר שני של דמאי ונראה שעל זה סמך רבינו ומפרש דההיא דנכנס לירושלים ויוצא דוקא בפירות הטבולים לדמאי.\",2,0],[8,356,2,9,\"ומ\\\"ש וכן פירות הנלקחים בכסף מעשר וכו'. הכי משמע בפרק הזהב עלה נ\\\"ג:\",3,0],[8,356,2,9,\"עבר והוציאן או שיצאו וכו' עד ואסור להוציאו. שם ואע\\\"פ שמה שאמרו שם שאע\\\"פ שאין שוה פרוטה קלטוה מחיצות משמע שאין בו ממש כתב רבינו אין בחומשו וכו' משום דהתם תניא ממעשרו ולא כל מעשרו פרט למעשר שני שאין בו שוה פרוטה ואסיקנא דהיינו אין בחומשו שוה פרוטה וסובר רבינו דה\\\"ה לענין קליטת מחיצות.\",4,0],[8,356,2,9,\"ומ\\\"ש אבל מעות מעשר שני נכנסים ויוצאים משנה פ\\\"ג דמע\\\"ש:\",5,0],[8,356,2,10,\"פירות שנגמרה מלאכתן וכו'. משנה ו' פרק ג' דמעשר שני וכת\\\"ק.\",1,0],[8,356,2,10,\"ומ\\\"ש אפי' עשה כל הפירות האלו מעשר שני וכו'. ומ\\\"ש חומר הוא וכו' אעיקרא דמילתא קאי:\",2,0],[8,356,2,11,\"פירות שלא נגמרה וכו'. משנה שם פ\\\"ג דמעשר שני וכב\\\"ה.\",1,0],[8,356,2,11,\"ומה שכתב וכן פירות דמאי וכו'. שם במשנה והדמאי נכנס ויוצא ונפדה וכבר נתבאר בסמוך:\",2,0],[8,356,2,12,\"פירות מעשר שני שנטמאו וכו'. שם (מ\\\"ט) וכב\\\"ה וכדפריש בר קפרא בירושלמי:\",1,0],[8,356,2,13,\"ומ\\\"ש בד\\\"א בשהכניסם על מנת שלא תתפשם המחיצות וכו'. ג\\\"ז שם בירושלמי:\",1,0],[8,356,2,14,\"תלתן של מעשר שני וכו'. משנה שם פ\\\"ב (מ\\\"ג) תלתן של מע\\\"ש יאכל צמחונין ובירושלמי כיני מתניתין מותר להאכל צמחונין.\",1,0],[8,356,2,14,\"ומה שכתב וכן כרשיני מעשר וכו' עד ויאכלו בחוץ. משנה ד' שם וכחכמים.\",2,0],[8,356,2,14,\"כתב הראב\\\"ד כמדומה לי שהטעהו הירושלמי וכו'. טעמו משום דמדברי רבינו נראה שבאו להקל לומר שמותר לאכלה צמחונים ואין זה פשט המשנה שבמשנה באו לומר חומר שיש במעשר שני יותר מבתרומה ואם כן פירוש יאכל צמחונין היינו לומר עכ\\\"פ יאכלו צמחונים ורבינו בפירוש המשנה כתב כדברי הראב\\\"ד ופה חזר בו מפני הירושלמי שפשטו כדברי רבינו פה ואין זה הוצאת המשנה מפשטה דתאכל צמחונין שפיר משתמע מותר שתאכל צמחונין ואין חוששין משום דבר שאין דרכו ליאכל וכמו שפירש רש\\\"י ומה שנשנה שם לענין שיש חומר במעשר שני מבתרומה לא לענין אכילת צמחונין היא אלא לענין שאר דברים שנשנו שם באותה משנה.\",3,0],[8,356,2,14,\"ועל מ\\\"ש רבינו ואם עשה מהם עיסה וכו' כתב הראב\\\"ד מפורש בירושלמי וכו'. שם אמתניתין דקתני כרשיני מעשר שני נכנסים לירושלים ויוצאים אמרינן קל הוא שהקילו בכרשינין ובלבד בעיסה של כרשינין ע\\\"כ ומשמע להראב\\\"ד דהיינו לומר שאינו רשאי להוציאם לאכלם חוץ לירושלים אלא שמוציאם לעשות מהם עיסה ולחזור ורבינו נראה דמשמע ליה דהיינו לומר שאם עשה מהם עיסה הרי זו מותרת ליכנס לירושלים ולהוציאה. ומכל מקום נראה דגם לרבינו לא יאכלנ' חוץ לירושלים ונראה לי שהטעם שהקילו בעיסה מפני שהכרשינין עצמם נאכלים לאדם על ידי הדחק והעיסה מהם אינה נאכלת אלא יותר בדוחק:\",4,0],[8,356,2,15,\"אילן שעומד לפנים מן כו'. כך היא הגירסא נכונה כגירסת רבינו לפנינו והדין משנה שם (פ\\\"ג מ\\\"ז) אילן שעומד בפנים ונוטה לחוץ או עומד בחוץ ונוטה לפנים מכנגד החומה ולפנים כלפנים מכנגד החומה ולחוץ כלחוץ ובס\\\"פ אלו הן הגולין (מכות דף י\\\"ב) רמי האי מתניתין אמתניתין דספ\\\"ג דמעשרות דקתני בירושלים הכל הולך אחר הנוף ומשני הא רבי יהודה הא רבנן ואמרינן דלרבי יהודה באילן הלך אחר נופו לחומרא עיקרו בחוץ ונופו בפנים כי היכי דבנופו לא מצי פריק בעיקרו נמי לא מצי פריק עיקרו בפנים ונופו לחוץ כי היכי דבנופו לא מצי אכיל בלא פדייה בעיקרו נמי לא מצי אכיל בלא פדייה והיה נראה שע\\\"פ זה פסק רבינו כן אבל קשה אמאי שבק רבנן ופסק כר\\\"י ועוד למה השמיט דין עיקרו בחוץ ונופו בפנים ולכן נראה שרבינו סמך על מאי דאיתא התם בתר הכי רב אשי אמר מאי אחר הנוף אף אחר הנוף ונ\\\"ל שרבינו מפרש דרב אשי אתא לשנויי דלא ליקשו הני משניות אהדדי דתרוייהו כרבנן ומתניתין דקתני דבירושלים הולך אחר הנוף היינו להחמיר ולומר שאם נופו נוטה חוץ לחומה כיון שנכנס תחת נופו דינו כנכנס לפנים לענין שאין פודין אותו ומתניתין דקתני מכנגד החומה ולחוץ כלחוץ היינו לענין שאין אוכלים שם ופסק כרב אשי דבתרא הוא ועוד דמסתבר טעמיה:\",1,0],[8,356,2,16,\"בתים שבצד החומה וכו'. שם במשנה בתי הבדים שפתחיהם בפנים וחללן לחוץ או שפתחיהם לחוץ וחללן לפנים בית שמאי אומרים הכל כלפנים וב\\\"ה אומרים מכנגד החומה ולפנים כלפנים מכנגד החומה ולחוץ כלחוץ ובירושלמי (הלכה ד:) אמר רבי אלעזר לחומרין ר' יוסי בעי מהו לחומרין אמר רבי יונה הדא דתנינן תמן בתי הבדים שפתחיהם לפנים וחללן לחוץ מכנגד החומה ולפנים כלפנים מכנגד החומה ולחוץ כלחוץ אין שוחטין שם קדשים קלים כלפנים ולא פודים שם מעשר שני כלחוץ פתחיהם לחוץ וחללן לפנים מכנגד החומה ולחוץ כלחוץ מכנגד החומה ולפנים אין שוחטים שם קדשים קלים כלפנים ולא פודים שם מעשר שני כלחוץ ומדברי רבינו נראה שאין נוסחא זו בירושלמי מכוונת ויש בה טעות סופר וק\\\"ל:\",1,0],[8,356,2,16,\"והחלונות ועובי החומה כלפנים. משנה בפרק כיצד צולין (פסחים דף פ״ה:) ובגמרא (דף פ״ו) מותיב לרב דאמר גגין ועליות לא נתקדשו דראש החומה דומה לגגין ועליות ומשני משכחת לה בבר שורא ופירש רש״י בר שורא חומה קטנה לפנים מחומה גדולה והיא נמוכה ושוה לקרקע גובה העזרה עכ״ל וצריך טעם למה השמיטו רבינו:\",2,0],[8,356,3,1,\"האוכל מעשר שני בטומאה לוקה וכו' עד והאוכל טמא. בפרק הערל (יבמות דף ע״ג):\",1,0],[8,356,3,1,\"ומה שכתב והוא שיאכלנו בירושלים קודם שיפדה וכו'. בפרק אלו הן הלוקין משנה שלישית כתב רבינו אינו חייב מלקות על אכילת מעשר שני בטומאה עד שיאכלנו בירושלים דאמר רחמנא בבכור שנפל בו מום בשעריך תאכלנו הטמא והטהור יחדיו ואמר בכאן לא תוכל לאכול בשעריך ובאה הקבלה ג\\\"כ בזה לא תוכל לאכול בירושלים כבשעריך כלומר לא תוכל לאכול מעשר בטומאה בירושלים כמו שתוכל לאכול בכור בטומאה בשעריך עכ\\\"ל:\",2,0],[8,356,3,3,\"ומ״ש ואפילו להדליק בו את הנר וכו'. בפרק הערל (יבמות דף ע״ג):\",1,0],[8,356,3,3,\"כבר ביארנו. בפרק ב'.\",2,0],[8,356,3,3,\"ומ\\\"ש ואוכלים את דמיו בטהרה וכו' כמו שיתבאר בפרק רביעי.\",3,0],[8,356,3,3,\"ומ\\\"ש אפילו נטמאו הפירות כולם כשהם טבל וכו':\",4,0],[8,356,3,4,\"הערל כטמא ואם אכל מעשר שני לוקה וכו'. בפרק הערל בעיא ואסיקנא דלרבי עקיבא ערל כטמא ואף רבי יצחק סבר ערל אסור במעשר דאמר רבי יצחק מניין לערל שאסור במעשר וכו':\",1,0],[8,356,3,4,\"וטמא שטבל אוכל וכו'. משנה בסוף נגעים (משנה ג') ובפירקא קמא דכלים:\",2,0],[8,356,3,5,\"האוכל מעשר שני באנינות של תורה לוקה וכו'. בפרק שני דבכורים (משנה ב') תנן המעשר והבכורים וכו' אסורים לאונן ובפרשת והיה כי תבא כתוב גבי מעשר שני לא אכלתי באוני ממנו וק\\\"ל שאין ראיה מכאן שילקה על זה אבל רבינו אזיל לטעמיה שכתב בספר המצות שלו בשורש שמיני במה שצוה הכתוב לנו שנאמר לא אכלתי באוני ממנו ולא בערתי ממנו בטמא ולא נתתי ממנו למת הורה על היות כל פועל מאלו מוזהר ממנו וכבר השיג עליו הרמב\\\"ן.\",1,0],[8,356,3,5,\"ומה שכתב והוא שיאכלנו במקום אכילתו בירושלים נלמד ממה שנתבאר בסמוך גבי אם אכלו בטומאה.\",2,0],[8,356,3,5,\"ומה שכתב אבל אם אכלו בחוץ באנינות וכו' מכין אותו מכת מרדות. לענין אכלו באנינות של דבריהם פשוט הוא ולענין אכלו בחוץ באנינות:\",3,0],[8,356,3,6,\"איזהו אונן וכו'. בפ' טבול יום עלה ק\\\"א וכחכמים:\",1,0],[8,356,3,7,\"ולא מעשר שני בלבד וכו'. פ' טבול יום ובפרק האשה דפסחים (דף צ\\\"ב):\",1,0],[8,356,3,8,\"אין נותנין פירות מעשר שני לע\\\"ה וכו'. ירושלמי פירקא קמא דדמאי ובפרק שלישי דמעשר שני אין מוסרין ודאי לעם הארץ.\",1,0],[8,356,3,8,\"ומה שכתב ולא פירות הנלקחות במעות מעשר ולא מעות מעשר: ומותר לאכול מעשר שני של דמאי וכו'. משנה בפירקא קמא דדמאי (משנה ב'):\",2,0],[8,356,3,8,\"אין מפקידין מעשר שני אפילו אצל חבר וכו'. תוספתא פ\\\"ד דמעשר שני מפקיד אדם מעשר שני שלו אצל חבר ושל דמאי אצל ע\\\"ה אבא חילפי בן קרויה אומר בראשונה היו עושין כן חזרו לומר אפילו חבר אין מפקידין אצלו שאין אתה יודע מי עומד אחריו ע\\\"כ בתוספתא וזהו שכתב רבינו אין מפקידין מעשר שני אצל חבר וכו' ומצאתי בקצת ספרי רבינו שמסיים בה אבל מפקידין מעשר שני של דמאי אצל ע\\\"ה ונראה שכך היה גורס הראב\\\"ד בספרי רבינו שהיה בידו ונראה שהטעם משום דמשמע דלא חששו אלא בשל ודאי ולא בשל דמאי:\",3,0],[8,356,3,8,\"והראב\\\"ד כתב על דברי רבינו א\\\"א לא מצאתי דבר זה בשום מקום וכו'. ונוסחת הראב\\\"ד בתוספתא אינה מכוונת דקתני מפקידין מע\\\"ש של דמאי אצל חבר דמשמע אבל לא של ודאי ואמאי לא ותו דקתני ושל ודאי אצל ע\\\"ה דמשמע אבל לא של דמאי קשה אטו מי חמיר דמאי מודאי ואע\\\"פ שהראב\\\"ד הרגיש בזו וכתב שהטעם מפני שמיקל בו וקשה שהרי שנינו הדמאי נותנו לע\\\"ה ויאכל כנגדו וכן שנינו ואם היה ע\\\"ה נותן לו מדמאי וכמה קולות הקילו בדמאי וכ\\\"ש שלא היה להם לחוש מלהפקידו אצל ע\\\"ה הילכך נראה לי שאותה נוסחא משובשת ורבינו שמשון הביא תוספתא זו בפרק ד' דטבול יום וגורס כגירסת תוספתא דידן. ומה שרצה הראב\\\"ד לחלק בין פקדון דמעות לפקדון דפירות קשה לי דפקדון דפירות מי לא שכיח דליהוי לזמן ארוך ותו דאפילו לא ליהוי לזמן ארוך מי ליכא למיחש שימות הנפקד ביום אשר הפקיד אותו או למחרתו הילכך נוסחת רבינו ונוסחת תוספתא דידן עיקר:\",4,0],[8,356,3,9,\"מעשר שני אסור וכו'. משנה פ\\\"ק דדמאי (משנה ב') הדמאי אין לו חומש וכו' ומאבדין את מיעוטו בדרכים משמע הא ודאי לא והכי אמרינן בירושלמי.\",1,0],[8,356,3,9,\"ומה שכתב וכמה הוא מיעוט פחות מכגרוגרת וכו'. שם בירושלמי (הלכה ב') אמתניתין דמאבדין את מיעוטו בדרכים דבי רבי ינאי אמרי פחות מאוכל מותר לאבד בפרוס אבל בשלם עד כגרוגרת רבי יוחנן אמר בשם ר\\\"ש בן יוצדק בשלם עד כגרוגרת בפרוס אפילו כמה מותר מה פליגין ר' מנא אמר לא פליגי דבי ר' ינאי אמרי פחות מאוכל מותר לאבד בפרוס אבל בשלם עד כגרוגרת ר\\\"י אמר בשם ר\\\"ש בן יוצדק בין בפרוס בין בשלם עד כגרוגרת ויש לתמוה שגם למה ששנה רבי מנא דבריהם פליגין והיאך אמר דלא פליגי ואפשר דבקדמייתא ל\\\"ג בדרבי ינאי בשלם עד כגרוגרת אלא בשלם כגרוגרת ומשמע דפליגי גם בשלם דלרבי ינאי כגרוגרת מותר לאבד ולר\\\"י עד גרוגרת מותר לאבד אבל לא כגרוגרת דעד ולא עד בכלל ואתא רבי מנא למימר דבשלם לא פליגי דמאי כגרוגרת דאמר רבי ינאי עד כגרוגרת ואכתי ק\\\"ל למה הוצרך לשנות דברי ר\\\"י לומר דלא מפליג בין פרוס לשלם ולכן נראה לומר דל\\\"ג בתנייתא דר' ינאי אבל בשלם אלא ובשלם וה\\\"פ פחות מאוכל מותר לאבד בפרוס ובשלם והיינו עד כגרוגרת דכגרוגרת הוא שיעור אוכל לענין הוצאת שבת והשתא למאי דמסיק רבי מנא לא פליגי ר' ינאי ור\\\"י כלל ואפילו לגירסא דידן פסק רבינו כר\\\"י משום ר' שמעון בן יוצדק דאף על גב דר\\\"י תלמידיה דרבי ינאי הוא ואין הלכה כתלמיד במקום הרב שאני הכא דמשמיה דר' שמעון בן יוצדק קאמר לה:\",2,0],[8,356,3,9,\"והראב\\\"ד כתב א\\\"ר יוחנן משום ר\\\"ש בן יהוצדק כו'. טעמו להשיג על רבינו שדבריו לא כמר ולא כמר שהוא ז\\\"ל לא היה גורס עד אלא כגרוגרת ולא מיעט אלא יותר מכגרוגרת אבל כגרוגרת מותר ולאפוקי מרבינו שפסק דכגרוגרת אסור וכבר כתבתי טעם פסק רבינו שהיה גורס עד כגרוגרת:\",3,0],[8,356,3,9,\"ומה שכתב רבינו והמפריש מעשר שני של דמאי כו' משום דמשמע לרבינו דהא דר\\\"י ורבי ינאי קאי נמי למאי דקתני בההיא מתניתין נותנו לעם הארץ ויאכל כנגדו סמוך למאבדים את מעוטו בדרכים. ומיהו איכא למידק דהכא משמע בלשון רבינו דמ\\\"ש של דמאי שמותר ליתנו לעם הארץ דוקא פחות מכגרוגרת הא כגרוגרת אינו רשאי ליתנו לעם הארץ ולעיל בסמוך כתב סתם דמותר ליתנו לעם הארץ ומשמע דבין מעט בין הרבה מותר ליתנו לעם הארץ. ונראה שרבינו לעיל סמך על מה שאמר כאן דדוקא פחות מכגרוגרת:\",4,0],[8,356,3,9,\"וכתב הראב\\\"ד א\\\"א אפילו כגרוגרת וכו'. כבר נתבאר שטעמו שלא היה גורס עד כגרוגרת ורבינו גורס עד כגרוגרת. ומ\\\"ש וכדברי רבי ינאי אפילו עד כביצה נראה שטעמו להשיג שה\\\"ל לפסוק כר' ינאי ודלא כר\\\"י דאין הלכה כתלמיד במקום הרב וכבר כתבתי טעם רבינו ומכל מקום למדנו מדברי הראב\\\"ד שגם הוא ז\\\"ל סובר דהא דר\\\"י ורבי ינאי קאי נמי לנותנו לע\\\"ה ויאכל כנגדו:\",5,0],[8,356,3,10,\"מעשר שני ניתן לאכילה ושתיה וסיכה. משנה פ\\\"ב דמעשר שני (משנה א').\",1,0],[8,356,3,10,\"ומה שכתב ואסור להוציאו בשאר צרכיו וכו'. משנה בספ\\\"ק דמע\\\"ש זה הכלל כל שהוא חוץ לאכילה ושתיה וסיכה מדמי מעשר שני יאכל כנגדו:\",2,0],[8,356,3,10,\"ומ\\\"ש שנאמר לא נתתי ממנו למת לא הוצאתיו בדבר שאינו מקיים את הגוף אע\\\"פ שהרמב\\\"ן בפירוש התורה כתב על דברי רבינו בזה שהם דברי הבאי נראה דלא דבר ריק הם דברי רבינו כמו שאכתוב בסמוך.\",3,0],[8,356,3,10,\"ומ\\\"ש ואם הוציאו ממנו בשאר דברים אפילו בדבר מצוה וכו'. משנה בסוף מעשר שני (משנה י\\\"ב) ולא נתתי ממנו למת לא לקחתי ממנו ארון ותכריכין למת ומשמע לרבינו דבדרך אפילו מיתניא ומשום דאיכא למידחי ולומר דדוקא נקט למת הא לחי דומיא דלמת דהיינו ליקח בגדים לחי שרי לכך כתב רבינו דאין לומר כן דגם זה הוי בכלל למת כיון שאינו דבר שהוא חוזר להיות חי דהיינו אכילה ושתיה שחוזר להיות חלק אבר:\",4,0],[8,356,3,11,\"מעשר שני אוכל דבר שדרכו וכו' עד השמן. משנה פ\\\"ב דמע\\\"ש (משנה א'):\",1,0],[8,356,3,11,\"ומ\\\"ש ולא יסחוט את הפירות כו'. משנה פי\\\"א דתרומות (משנה ג'):\",2,0],[8,356,3,11,\"ואין מחייבין אותו לאכול פת שעיפשה וכו'. ירושלמי פרק ב' דמעשר שני:\",3,0],[8,356,3,12,\"ומ״ש כל שמותר לזרים לאוכלו בתרומה וכו': שמרים שנתן עליהם מים וכו'. פרק המוכר פירות (בבא בתרא דף צ״ז) וכת״ק ובספרי רבינו כתוב במעשר בחולין שניהם בבי״ת ודבר פשוט הוא שט״ס הוא דבשניהם צריך להיות כ״ף:\",1,0],[8,356,3,15,\"יין של מעשר שנפל לתוכו דבש ותבלין וכו' עד השבת לשני. משנה בפ\\\"ב דמעשר שני (משנה א') ומסיים בה שם במשנה זה הכלל כל ששבחו ניכר השבח לפי חשבון וכל שאין שבחו ניכר השבח לשני ובירושלמי אמר רבי יוחנן כל שיש בו הותיר מדה השבח לפי חשבון וכל שאין בו הותיר מדה השבח לשני רשב\\\"ל אמר כל שטעם שבחו ניכר השבח לפי חשבון וכל שאין טעם שבחו ניכר השבח לשני וידוע דהלכה כר\\\"י:\",1,0],[8,356,3,15,\"כתב הראב\\\"ד אין זה דרך הירושלמי וכו'. נראה שבא להשיג על מה שכתב רבינו שכל שאין שבחו ניכר אפילו הותיר המדה השבח לשני בלבד דמשמע דגם יתרון המדה לשני וע\\\"ז כתב שאין זה דרך הירושלמי דמשמע שלא נחלקו ר\\\"י וריש לקיש אלא בשנשאר המדה שהיתה בו תחלה ודמי התערובות שעירב בו היה ד' זוזים והשביח ושוה ה' זוזים אבל לא הותיר על המדה דלר\\\"י אין לבעל התערובות חלק בזוז שהשביח כיון שלא הותיר על המדה ולריש לקיש יש לו בו חלק כיון שעל ידו הותיר אבל כשהותיר המדה ולא היה בו שבח לא איירי ביה בירושלמי ואפשר דכ\\\"ע מודו שהמדה לבעל התערובות ולמה יאבד זה מה שעירב ולזה נראה שכיון הראב\\\"ד ורבינו תפס לשון המשנה והירושלמי כפשטן דמתניתין קתני כל ששבחו ניכר השבח לפי חשבון ור\\\"י התנה עוד שיותיר על המדה ואז יהיה השבח לפי חשבון אבל אם חסר אחת משתי אלה השבח לשני.\",2,0],[8,356,3,15,\"ועל מה שכתב רבינו כיצד השבח לפי חשבון וכו' כתב הראב\\\"ד א\\\"א זו החלוקה איני יודע וכו'. ואני אומר שאין מחלוקת ביניהם שמ\\\"ש רבינו חושבין הכל בארבעה ורביע פירושו חושבין כאילו הקרן ארבעה ורביע ונותנין לבעל התערובות זוז ורביע והשאר למעשר שני וכדברי הראב\\\"ד ואפשר שגירסא אחרת היתה להראב\\\"ד בדברי רבינו ולפיכך השיגו וגירסא דספרים דידן נכונה:\",3,0],[8,356,3,16,\"מעשר שני אע\\\"פ שניתן לסיכה וכו'. תוספתא בריש מע\\\"ש ופירוש צינית מכה שתחת פרסת הרגל והטעם משום דרפואה אינה בכלל אכילה:\",1,0],[8,356,3,17,\"מעשר שני ממון גבוה הוא. בפרק האיש מקדש (קידושין דף נ״ד:) פלוגתא דתנאי ואיפסיקא הלכתא בגמרא כר״מ דאמר הכי:\",1,0],[8,356,3,17,\"ומ\\\"ש ואינו נקנה לו במתנה אא\\\"כ נתן לו הטבל. שם בגמרא אליבא דר\\\"מ ונתנו טעם בגמרא למה כשנתן לו את הטבל נקנה לו משום דקסבר מתנות שלא הורמו לאו כמי שהורמו דמיין ויש לתמוה היאך פסק רבינו שאם נתן לו את הטבל נקנה לו והרי הוא ז\\\"ל פסק בפ\\\"ו מהלכות מעשרות ובכמה דוכתי דמתנות שלא הורמו כמי שהורמו דמיין. ותירץ הר\\\"י קורקוס ז\\\"ל שסובר רבינו דדוקא להאי מילתא אמרו לאו כמי שהורמו דמיין דע\\\"כ לא אמר ר\\\"מ מע\\\"ש ממון גבוה אלא דוקא כשהורם ונקרא עליו שם מעשר דהא מדכתיב לה' הוא יליף לה וקרא אחר שהורם ונקרא מעשר משמע.\",2,0],[8,356,3,17,\"ומ\\\"ש והמקבל מפריש המעשר פשוט הוא.\",3,0],[8,356,3,17,\"ומ\\\"ש ואין מקדשין בו וכו'. משנה בריש מע\\\"ש (משנה ב').\",4,0],[8,356,3,17,\"ומ\\\"ש ואין מרהינין אותו וכו' עד ואם רצה הלה ליתן. שם ירושלמי:\",5,0],[8,356,3,19,\"מעשר שני אין וכו'. משנה שם.\",1,0],[8,356,3,19,\"ומ״ש אפילו דינרי זהב ואפילו לחלל עליהם מע״ש אחר וכו'. בפרק במה מדליקין (שבת דף כ״ב:) ודברי רבינו בפירושו שלא כפירוש רש״י:\",2,0],[8,356,3,20,\"האחין שחלקו וכו'. בירושלמי ריש מע\\\"ש (הלכה א') האחין שחלקו מהו שישקלו זה כנגד זה תנן לא יאמר אדם לחבירו בירושלים הילך יין ותן לי שמן וכו' הוו בעו מימר אסור אשכח תני מותר ומשמע להראב\\\"ד דקאי אבעי' דהאחין שחלקו וכו' לפיכך כתב נ\\\"ל שהוא מותר ורבינו משמע ליה דלא קאי אלא למאי דסמיך ליה הא לך יין שאין לי שמן אבל בעיא דהאחין שחלקו מהו שישקלו זה כנגד זה לא פשטו בה דבר ומיהו יש לתמוה למה פסקה לחומרא כיון דמילתא דרבנן היא ה\\\"ל למיפסק לקולא וצ\\\"ע. ויש חסרון בספרי רבינו וכך היא הנוסחא הנכונה בספר מוגה האחים שחלקו אין שוקלים זה כנגד זה וכן מעות מע\\\"ש אין שוקלין כנגדן ולא מוכרים אותן ואין מחליפין.\",1,0],[8,356,3,20,\"ומ\\\"ש ולא יתנם לשולחני להתנאות בהם ולא ילוה אותם להתגדל בהם ואם הלוון שלא יעלו חלודה מותר. תוספתא בריש מעשר שני:\",2,0],[8,356,3,21,\"ומה שכתב ואין פורעין מהם את המלוה. תוספתא פרק ז' דשביעית וירושלמי פירקא קמא דמעשר שני:\",1,0],[8,356,3,22,\"לא יאמר אדם וכו'. משנה ריש פרק ג' דמעשר שני (משנה א') ופירש רבינו בה אין שינוי בענין אלא נקיות לשון ובחרו מאמרם לחלק מפני שיהיה כמי שנתן פירות מעשר שני שכר למי שהעלם וזה אסור לפי שהוא בעצמו חייב להגיעם שם ור\\\"ש פירש משום דאסור לפרוע חובו ממעשר שני וזה נראה כפורע שכירות הדרך ממעשר שני:\",1,0],[8,356,3,23,\"אומר אדם לחבירו וכו'. בפרק ב' דמעשר שני (משנה ב') ר\\\"ש אומר אין סכין שמן של מעשר שני בירושלים וחכמים מתירים ופירש רבינו על פי הירושלמי שרבי שמעון אומר שאסור לאדם שיאמר לחבירו שימשח אותו בשמן של מע\\\"ש ושתמשח יד מושחו ותהיה שכרו על המשיחה שמושחו ואינו מותר שישתכר אדם ממעות מע\\\"ש וחכמים מתירים זה כי הם אומרים שאין דמים למשיחת ידו ואין מקפידין בזה וידוע דהלכה כחכמים:\",1,0],[8,356,3,24,\"כבר ביארנו וכו'. לעיל בפרק זה.\",1,0],[8,356,3,24,\"ומ״ש לפיכך אנו אומרים שהגונב מע״ש וכו'. בפרק מרובה (בבא קמא דף ע״ו) אמרינן דגונב הקדש פטור מכפל ובפרק הזהב דרשינן לרעהו ולא של הקדש:\",2,0],[8,356,3,25,\"המקדיש מעשר שני שלו וכו'. תוספתא פ' חמישי דמעשר שני:\",1,0],[8,356,4,1,\"הרוצה לפדות פירות מעשר שני וכו' ואם לא פירש וכו'. משנה פ' ד' דמעשר שני (משנה ז') וכרבי יוסי:\",1,0],[8,356,4,2,\"וכן אם רצה לחלל פירות המעשר וכו' ולא יחלל ממין על שאינו מינו וכו'. ירושל' רפ\\\"ד דמעשר שני.\",1,0],[8,356,4,2,\"ומ״ש ואם חילל הרי הן מחוללות: כתב הראב״ד והראשונים לא יצאו לחולין וכו' נראה דהיינו מדתניא התם (סוכה דף מ':) אחד שביעית ואחד מע״ש מתחללין על בהמה חיה ועוף ומסיק מאי שביעית דמי שביעית דאי לא תימא הכי מעשר מעשר ממש והא כתיב וצרת הכסף בידך אלא דמי מעשר ה״נ דמי שביעית ופירש״י וצרת דאין מתחלל אלא על המטבע דבר שיש עליו צורה. ומ״ש ואפי' דיעבד נראה שטעמו מדקתני מתחללים דמשמע דיעבד כדאמרינן בפ' הזהב אפ״ה קאמר דמעשר ממש אינו מתחלל ולרבינו י״ל דהכא מתחללין לאו דוקא דהא בתוספתא קתני מחללין דמשמע לכתחלה. ומ״ש ופרי שני דיעבד אין וכו' נלמד מהא דתניא אחד שביעית ואחד מע״ש מתחללין ואוקימנא בדמי מע״ש ומתחללין דיעבד משמע ליה כמו שכתבתי בסמוך. ומ״ש אלא בדמאי דמחלל לכתחלה. בהשגה שאחר זה אכתוב שמהירושלמי למד כן וטעמו להשיג על רבינו שא״א להעמיד דבריו אפילו בפרי שני דלכתחלה אין מחללין והוא ז״ל כתב וכן אם רצה לחלל פירות המעשר על פירות אחרות דמשמע אפי' לכתחלה וכבר כתבתי דלדעת רבינו דמי מעשר מחללין לכתחלה ובסמוך אכתוב שמהירוש' משמע כדברי רבינו דקתני אין מחללין ממין על שאינו מינו משמע הא על מינו מחללין והשתא אין ראיה מההיא דלולב הגזול דהתם שאני שהוא ממין על שאינו מינו. ומ״ש בס״פ לולב הגזול והכתיב וצרת הכסף בידך לא שיהא כסף דוקא אלא למעוטי שלא יחלל על שאינו מינו והא דבפ' הזהב (בבא מציעא דף מ״ד:) מוכח דפרי ראשון אינו מתחלל על פרי אלא על מטבע שנשאו ונתנו שם אי דהבא פירא הוי אי טבעא לחלל עליו מעשר שני משמע דלמ״ד פירא אין מחללין עליו י״ל דדהבא שאני דעד כאן לא שרי רבינו לחלל אלא על פירות שהם אוכל ויש להביא ראיה לדברי רבינו ממה ששנינו בפירקא בתרא דטבול יום בראשונה היו אומרים מחללין על פירות ע״ה חזרו לומר אף על מעותיו וכן פירשה רבינו דמיירי בפירות לחלל על פירות דסתם חילול הכי משמע:\",2,0],[8,356,4,2,\"כתב עוד הראב\\\"ד מה שהקפידו על מינו אינו אלא בדמאי וכו'. נראה דמשום דמהירושלמי הזה קשה למ\\\"ש בהשגה שקודם זו שפירות הראשונים של מעשר אינם מתחללים אלא על הכסף והרי כאן שלא מיעטו אלא ממין על שאינו מינו הא ממין על מינו מחללין ולפיכך העמיד הירושלמי הזה בדמאי דוקא וזה דוחק שלדמאי קראו מעשר שני סתם ועוד ק\\\"ל אם הקפידו על דמאי למה לא הקפידו על הודאי:\",3,0],[8,356,4,3,\"הפודה מעשר שני וכו'. ירושלמי סוף פרק קמא דדמאי:\",1,0],[8,356,4,3,\"וכתב הראב\\\"ד אני אומר שאם חילל פירות על פירות וכו'. דבר פשוט הוא דלטעמיה אזיל שסובר שאין פירות ראשונים של מעשר שני מתחללין אלא על הכסף:\",2,0],[8,356,4,3,\"ומה שכתב של דמאי אינו צריך ברכה. שם במשנה הדמאי מפרישין אותו ערום ופירש בירושלמי לומר שאינו טעון ברכה:\",3,0],[8,356,4,4,\"כשפודין את המעשר וכו'. ירושלמי ריש פ\\\"ד דמעשר שני:\",1,0],[8,356,4,4,\"כתב הראב\\\"ד נ\\\"ל שלא אמרו דבר זה וכו'. ויש לתמוה מאחר שהוא כתב למעלה שלעולם אין פירות הראשונים מתחללין אלא על כסף היאך כתב כאן שלא אמרו דבר זה אלא כשפודין אותו על פירות ואם בדמאי קאמר ה\\\"ל לפרש ואפשר דממה שכתב לעיל ממילא משמע דבדמאי מיירי. ועוד יש לדקדק בדבריו דבתחלת דבריו משמע דמסתבר ליה טעמו של רבינו ובסוף דבריו נתן טעם אחר ואפשר דה\\\"ק אם טעם זה אמת נ\\\"ל שלא אמרו אלא כשפודין אותו על פירות אבל העיקר אצלי טעם אחר והוא שלא לפגום את המעשר. וא\\\"ת מה טעם הוא זה שלא לפגום את המעשר מפני שדמי מעשר פחותים מדמי חולין ולמה הם פחותים מדמי חולין הלא כשפודה אותו הרי הוא חולין גמורים וי\\\"ל דמ\\\"מ כיון ששם מעשר עליו כשבאין לפדותו דמיו פחותים מדמי חולין:\",2,0],[8,356,4,5,\"אין מחללין וכו'. בפ\\\"ק דדמאי (משנה ב') במשנה שנינו דכל הני מותר בדמאי משמע אבל לא בודאי:\",1,0],[8,356,4,5,\"ומ\\\"ש ואם עבר וחילל וכו'. שם בירושלמי:\",2,0],[8,356,4,6,\"אין מחללין וכו'. פרק קמא דמעשר שני (משנה ה') במשנה הלוקח פירות שוגג יחזרו דמים למקומן מזיד יעלו ויאכלו במקום ואם אין מקדש ירקבו ולא חשש רבינו לבאר דבריו דבמזיד מיירי דמדנקט לשון חילול משמע דבמתכוין לחלל מיירי.\",1,0],[8,356,4,6,\"ומ״ש ולא יחללם על בהמה חיה ועוף וכו' אבל אם חילל על שחוטים וכו'. בפרק לולב הגזול (סוכה דף מ') וכחכמים:\",2,0],[8,356,4,7,\"בשעת הדחק מותר וכו'. משנה ו' פ\\\"ב דמ\\\"ש:\",1,0],[8,356,4,8,\"מעשר שני של דמאי מחללין וכו'. משנה בפ\\\"ק דדמאי (משנה ב') וכחכמים ודברי רבינו בה כפירוש התוספות בפרק הזהב:\",1,0],[8,356,4,9,\"אין פודין פירות מעשר אלא בכסף וכו'. וכן אם פדה לעצמו והוסיף חומש וכו'. ואין פודין בכסף שאינו מטבע וכו'. בפרק קמא דמעשר שני (משנה ב') תנן אין מחללין מעשר שני על אסימון ובפרק הזהב (בבא מציעא דף נ״ד) דטעמא משום דכתיב וצרת דבר שיש עליו צורה ואמרינן התם דחומשו כמותו.\",1,0],[8,356,4,9,\"ומ\\\"ש ואם פדה בלשון של כסף וכו': ואין פודין בפחות מפרוטה וכו'. ירושלמי פ\\\"ד אמר רבי חזקיה זה שהוא מחלל לא יהא מחלל על חצי פרוטה שלא יהא כמחלל על אסימון אלא על פרוטה ע\\\"כ. ונראה שכוונת רבינו והירושלמי דאף אם יש במעשר כמה פרוטות ומחלל אותו על מטבעות שיש בכל אחת חצי פרוטה אינו מחולל דכל מטבע פחות מפרוטה הרי הוא כאסימון:\",2,0],[8,356,4,10,\"אין פודין במטבע שאינו יוצא וכו'. משנה בריש מע\\\"ש.\",1,0],[8,356,4,10,\"ומ\\\"ש ומטבע מלכים הראשונים וכו'. שם בירושלמי (הלכה א') מטבע של מלכים הראשונים וכו' אם היה יוצא ע\\\"ג צורתו מחלל ואם לאו אינו מחלל ובתוספתא מטבע היוצא משם של מלכים הראשונים מחללים אותו עליהם ורבינו תפס לשון התוספתא ופירושה כמו שמבואר בלשון הירושלמי:\",2,0],[8,356,4,11,\"אינו פודה במעות שאינן ברשותו. משנה שם:\",1,0],[8,356,4,11,\"ומ\\\"ש נפל כיסו לבור וכו'. שם בירושלמי נפל כיסו לבור ובו מאה רבוא והיה יכול להוציא חמשים רבוא להעלותם אותם חמשי' רבוא כמו שהם ברשותו ע\\\"כ. והדבר מבואר דה\\\"ק אותם חמשים רבוא שישארו כמו שהם ברשותו ורבינו לא חשש להאריך וכיון שלמדנו שכיסו בבור מיקרי ברשותו וממילא משמע שאינו מחלל אלא עד שיעור מה שישאר אחר מה שצריך להוציא בהעלאתו. ודע שבתוספתא פ\\\"ק כתוב נפל כיסו לבור אין מחללין וצריך להעמידה באינו יכול להעלותו:\",2,0],[8,356,4,12,\"היה בא בדרך ומעות בידו וכו'. בפרק הגוזל ומאכיל (בבא קמא דף קט״ו:) והתניא מי שבא בדרך ומעות בידו ואנס כנגדו לא יאמר הרי פירות שיש לי בתוך ביתי מחוללין על מעות הללו ואם אמר דבריו קיימים הב״ע בשיכול להציל אי בשיכול להציל לכתחלה אמאי לא יאמר בשיכול להציל [ע״י] הדחק ולפ״ז מה שאמר רבינו פודה בהם פירות שבבית לא שיוכל לעשות כן לכתחלה אלא שאם פדה פדוי:\",1,0],[8,356,4,13,\"המניח מעות וכו'. משנה וגמרא ס״פ כל הגט (גיטין דף ל״א:) וכרבנן דפליגי על ר״א בן שמוע:\",1,0],[8,356,4,14,\"מי שהיה עומד בטבריה וכו'. בפרק הגוזל עצים וכו' (דף צ\\\"ז:) אין מחללין על מעות של כאן והם בבבל ושל בבל והם כאן של בבל והם בבבל מחללין ואוקימנא בשמלכיות מקפידות א\\\"ה של בבל והם בבבל למאי חזו דזבין בהו בהמה ומסיק לירושלים ובירושלמי פ\\\"ק דמע\\\"ש (הלכה א') אין מחללין לא על המעות שהם בבבל ולא על המעות שבבבל כאן לא המעות שכאן בבבל בעומד בבבל ולא המעות שבבבל כאן בעומד כאן היו לו מעות מבבל לבבל והוא עומד כאן נימר אם היתה דרך פתוחה מחלל ואם לאו אינו מחלל ע\\\"כ ודברי רבינו תמוהים שאינם לא בתוספתא ולא בירושלמי הזה והם היפך גמרא דידן וכבר השיגו הראב\\\"ד וכתב א\\\"א מן הגמרא שלנו הכל בהיפך וכו'. וע\\\"כ לומר שגירסא אחרת היתה לרבינו בגמרא והר\\\"י קורקוס ז\\\"ל כתב לפי זה הירושלמי מה שאמרו בפרק הגוזל עצים אין מחללין על מעות של בבל והם כאן וכו' האי והם אבעלים קאי דכיון דבעלים כאן אין מחללין על המעות שבבבל אף אם המעות בבבל והם מטבע בבל וכן אם הבעלים בבבל אין מחללים על מעות של כאן אף אם המעות כאן והם מטבע כאן והוא הדין הראשון שכתב רבינו היה עומד בטבריא וכו' אינו מחלל והוא מה שכתב בירושלמי לא על מעות של בבל כאן בעומד כאן אפילו שהמעות של בבל והם בבבל כיון שהוא עומד כאן אין מחללין, ומה שכתב דברייתא על מעות של בבל והם בבבל מחללים היינו שהבעלים בבבל אפילו שאין המעות שם כיון שהבעלים עומדים במקום שיוצאים והוא הנקרא מקום חלולם לדעת רבינו מחללים והוא מ\\\"ש בירושלמי לא על מעות של כאן והם בבבל בעומד בבבל ומעות של כאן ויוצאים כאן אפי' אם גם המעות בבבל כיון שהם מטבע כאן אינו מחלל דאי עומד כאן אפילו אין המטבע כאן כיון שהם מטבע היוצא במקום שהוא עומד מחלל דבהכי קפיד רחמנא כמ\\\"ש וצרת הכסף בידך וסבר כיון שאם היו כאן במקום שמחלל יוצאים מצוי בידך קרינן ביה. ועדיין קשה לדעת רבינו דהא תנן אין מחללין על מעות שאינם ברשותו ומפרשים בהגוזל עצים כגון שהיו לו מעות בקסטרא או בהר המלך וא\\\"כ היאך מחלל בטבריא על מעות העומדות בבבל. ואפשר לחלק העומדת בקסטרא או בהר המלך שאני שהוא מקום שיש בו סכנת דרכים ואין שיירות מצויות עכ\\\"ל:\",1,0],[8,356,4,16,\"האומר מעשר וכו' עד באותה שעה. תוספתא פ\\\"ד דמ\\\"ש ואיתא בפרק בכל מערבין וכחכמים וא\\\"ת דהתם מוכח דטעמא דמ\\\"ד חילל משום ברירה ומאחר שרבינו פוסק ברפ\\\"ז מהלכות מעשרות ופ\\\"א מהלכות תרומות דבדאורייתא אין ברירה לא הו\\\"ל לפסוק חילל ותירץ הר\\\"י קורקוס ז\\\"ל דאפשר דהכא אין אנו צריכים לטעם ברירה שכיון שזה אמר ה\\\"ז מחולל על סלע שתעלה בידי ממ\\\"נ המעשר פדוי ופדיון מעשר בכיס זה הוא וכולם בספק מ\\\"מ איזה סלע שיהיה ה\\\"ז חילל ובשעה שיעלה הסלע נאמר זהו הסלע שחילל עליו וכתב לתרץ למה הגמרא לא תירץ שם כן. ולי נראה דרבינו לטעמיה אזיל שתרומה בזמן הזה דרבנן:\",1,0],[8,356,4,17,\"הפודה מעשר שני וכו'. תוספתא בספ\\\"ג ואיתא בפרק הוציאו לו:\",1,0],[8,356,4,18,\"כשפודין מעשר שני וכו'. בפרק הזהב (בבא מציעא דף נ״ב):\",1,0],[8,356,4,18,\"ומ\\\"ש ויש לו לפדות בשער הזול וכו'. משנה פ\\\"ד דמ\\\"ש (משנה ב'):\",2,0],[8,356,4,18,\"ומ״ש ואם עבר ופדה וכו' או חילל וכו'. בפרק הזהב (בבא מציעא דף נ״ז) הקדש שוה מנה שחילל על שוה פרוטה מחולל:\",3,0],[8,356,4,19,\"היתה הסלע חסירה וכו'. משנה וגמרא פרק הזהב (בבא מציעא דף נ״ב ע״ב) ובפי' ריב״ן:\",1,0],[8,356,4,19,\"פדה בסלע ונמצאת רעה יחליפנה. תוספתא פ\\\"ד:\",2,0],[8,356,4,20,\"אין פודין מע\\\"ש אכסרה וכו'. משנה פ\\\"ד דמ\\\"ש (מ\\\"ב).\",1,0],[8,356,4,20,\"ומ\\\"ש אפילו אחד מהם עכו\\\"ם או בעל המעשר. שם בירושלמי:\",2,0],[8,356,4,20,\"ומ\\\"ש ואפילו איש ושתי נשיו וכן מ\\\"ש ג' תגרים. בגמרא דידן בפ\\\"ק דסנהדרין (דף י\\\"ד) ת\\\"ר מע\\\"ש שאין דמיו ידועים פודים אותו בג' לקוחות אבל לא בשלשה שאינם לקוחות אפי' עכו\\\"ם אחד מהם אפי' אחד מהם בעלים בעי רבי ירמיה ג' ומטילים לתוך כיס אחד מהו ת\\\"ש איש ושתי נשיו פודים מע\\\"ש שאין דמיו ידועים דילמא כגון רב פפא ובת אבא סוראה ופירש\\\"י לקוחות סוחרים בקיאים בשומא בת אבא סוראה אשת רב פפא וכו' והיתה עושה לעצמה עכ\\\"ל. ורבינו סתם הדברים כדברי הברייתא ולא חש למאי דדחי דילמא וכו' דדיחויא בעלמא הוא:\",3,0],[8,356,4,20,\"וכופין את הבעלים לפתוח ראשון זה חומר במעשר מן ההקדש. זו היתה גירסת רבינו בתוספתא דמ\\\"ש פ\\\"ג אבל גירסת ספרים דידן בתוספתא כגירסת הראב\\\"ד כופין את הבעלים לפתוח ראשון אם אמר הרי הוא שלי באיסר יכול לחזור בו זה חומר בהקדש מבמע\\\"ש. והר\\\"י קורקוס ז\\\"ל כתב דאפילו תימא דגירסת רבינו כגירסא דידן דיכול לחזור בו משום דסבר דאתיא כמ\\\"ד מע\\\"ש ממון הדיוט הוא אבל לדידן דקי\\\"ל ממון גבוה הוא אינו יכול לחזור:\",4,0],[8,356,4,21,\"אין מוליכין פירות וכו' עד להמכר בזול. משנה וירושלמי ברפ\\\"ד דמעשר שני:\",1,0],[8,356,4,22,\"היו לו פירות מעשר שני בגורן וכו'. משנה שם:\",1,0],[8,356,5,1,\"הפודה מעשרו לעצמו וכו'. משנה פ\\\"ד דמע\\\"ש (מ\\\"ג) הפודה מע\\\"ש שלו מוסיף עליו חמישיתו בין שהוא שלו בין שניתן לו במתנה.\",1,0],[8,356,5,1,\"ומ״ש בין שניתן לו בטבלו. בפ' האיש מקדש (קידושין דף נ״ד:) אמרינן דלר״מ דסבר מע״ש ממון גבוה הוא איך יתן מה שאינו שלו אלא מיירי בדיהיב ליה בטיבליה ובתורת כהנים פרשת בחוקותי יליף לה ושם הזכיר יורשים:\",2,0],[8,356,5,1,\"ומה שכתב כמו שביארנו. הוא בפ\\\"ג הי\\\"ז:\",3,0],[8,356,5,1,\"ומ״ש אם היה שוה ארבעה נותן חמשה. בפרק הזהב (בבא מציעא דף נ״ד) איפשיט דחומשא מלבר:\",4,0],[8,356,5,2,\"ואשה שפדת מע\\\"ש שלה וכו'. בפירקא קמא דקידושין (דף כ\\\"ד) וגירסת רבינו כגירסת ר\\\"ת:\",1,0],[8,356,5,2,\"וכן אם פדה וכו' בסוף פרק התודה (מנחות דף פ\\\"ב) המתפיס מעות מע\\\"ש לשלמים כשהוא פודן מוסיף עליהם שני חומשים אחד לקודש ואחד למעשר:\",2,0],[8,356,5,3,\"פדה פירות מעשרו והוסיף חומש וכו'. בפ' הזהב (בבא מציעא נ״ד:) אמר רבא גבי גזל כתיב וחמשיתיו יוסף עליו וכו' גבי מעשר לא מיכתב כתיב [ולא מיתנא תנא] ולא איבעויי איבעיא לן ופירש״י לא איבעויי איבעיא לן דפשיטא שאינו מוסיף שאין במעשר שום רמז:\",1,0],[8,356,5,4,\"מעשר שני שאין וכו'. בפרק הזהב (בבא מציעא דף נ״ג:) ת״ר אם גאול יגאל איש ממעשרו ממעשרו ולא כל מעשרו פרט למע״ש שאין בו שוה פרוטה ואסיקנא דאין בחומשו שוה פרוטה קאמר ומפרש רבינו דמיעוטא היינו לענין שאינו מוסיף חומש ורש״י פירש דהיינו לענין שאינו בר פדיון:\",1,0],[8,356,5,4,\"וכן מעשר שאין דמיו ידועים וכו'. ירושלמי פרק ד' דמעשרות:\",2,0],[8,356,5,4,\"וכל מעשר שהוא וכו'. הכי משמע בפ\\\"ק דקידושין (דף כ\\\"ד) ומפורש הוא בירושלמי פרק ד' דמעשר שני:\",3,0],[8,356,5,4,\"ומעשר שני של דמאי אינו מוסיף עליו חומש. משנה פ\\\"ק דדמאי (משנה ב') הדמאי אין לו חומש:\",4,0],[8,356,5,5,\"הפודה מעשר שני וכו'. בפרק הזהב (בבא מציעא דף נ״ב):\",1,0],[8,356,5,6,\"הפודה מעשר ביותר על דמיו וכו'. ירושלמי פרק רביעי דמעשר שני:\",1,0],[8,356,5,7,\"בעל הבית אומר בסלע וכו' עד כדי שלא יוסיף חומש. משנה פ\\\"ד דמעשר שני (משנה ג'):\",1,0],[8,356,5,8,\"ומה שכתב אבל לא יאמר לו פדה לי בהן. ירושלמי שם.\",1,0],[8,356,5,8,\"ומה שכתב וכן אם אמר לו פדה לך משלך. נ\\\"ל שטעות סופר הוא וצריך לכתוב וכן אם אמר לו פדה לי משלך וכך הוא בירושלמי שם פדה לי משלך פדה לך משלי אינו מוסיף חומש. ומהתוספתא פ\\\"ד נראה דאף אם לא אמר ליה פדה לך אלא פדה בהם שרי:\",2,0],[8,356,5,9,\"ומ\\\"ש אבל לא יתן המעות לפדות לבנו ולבתו הקטנים וכו'. שם במשנה:\",1,0],[8,356,5,9,\"ומ״ש נתן לשפחתו העבריה וכו'. בגיטין פרק התקבל (גיטין דף ס״ה):\",2,0],[8,356,5,10,\"וכן מערים וכו'. מ\\\"ה פ\\\"ד דמע\\\"ש:\",1,0],[8,356,5,10,\"ומ\\\"ש כשהוא בטבלו. הוא ע\\\"פ מה שנתבאר בפ' זה שאינו רשאי לתת מע\\\"ש במתנה:\",2,0],[8,356,5,11,\"שני אחים או שני שותפים וכו'. תוספתא פ\\\"ד דמעשר שני:\",1,0],[8,356,5,11,\"אשה שהכניסה לבעלה. פ\\\"ק דקידושין עלה כ\\\"ד:\",2,0],[8,356,5,12,\"הפודה מעשר שני לעצמו וכו'. בפ' הזהב (בבא מציעא דף נ״ד) וכר' יהושע:\",1,0],[8,356,5,13,\"מעות מעשר שני אם רצה לצרפן בדינרי זהב וכו'. משנה פרק ב' דמעשר שני (מ\\\"ז) וכבית הלל:\",1,0],[8,356,5,13,\"ומה שכתב ואם צרפו לעצמו אינו מוסיף חומש וכו':\",2,0],[8,356,5,14,\"הפורט סלע ממעות מעשר שני וכו'. משנה פ\\\"ב דמעשר שני (משנה ח') וכב\\\"ה שתי משניות ומפרש רבינו שתיהן שהיה לו סלע ורצה להחליפו בפרוטות:\",1,0],[8,356,5,15,\"מותר לחלל כסף וכו'. ירושל' שם אמתני' דקתני ר\\\"מ אומר אין מחללין כסף ופירות על הכסף וחכמים אומרים מחללין. ר\\\"ל אומר מה פליגין ר\\\"מ ורבנן בפירות שאין בהם כדי כסף אבל בפירות שיש בהם כדי כסף אף רבנין מודוי חצי דינר כסף וחצי דינר פירות מותר דינר כסף ודינר פירות אסור:\",1,0],[8,356,5,15,\"וכתב הראב\\\"ד לא כמו שהוא סובר וכו'. דייק הראב\\\"ד מדברי רבינו שהוא סובר שהאיסור הוא משום הפירות מדכתב לא יחלל עם הכסף אלא בפני עצמן ואם היה סובר שהאיסור הוא משום הכסף הכי הל\\\"ל לא יחלל הכסף עמהם ודעת רבינו הוא דכשהפירות מועטים פחות מדינר אינם ראויים ליפדות בפני עצמם ולפיכך הם נפדים עם הכסף ופשט לשון הירושלמי כדברי רבינו:\",2,0],[8,356,6,1,\"מעות חולין ומעות מעשר שנתפזרו וכו'. משנה פ\\\"ב דמע\\\"ש (מ\\\"ה):\",1,0],[8,356,6,1,\"ומ\\\"ש או שליקט מצד אחד וכו'. ירושלמי שם.\",2,0],[8,356,6,1,\"ומ\\\"ש מתנה ואומר אם אלו שבידי וכו'. גם זה שם בירושלמי:\",3,0],[8,356,6,2,\"סלע של מעשר שני ושל חולין שנתערבו וכו'. משנה שם:\",1,0],[8,356,6,3,\"האומר לבנו וכו'. משנה בפ\\\"ד דמע\\\"ש (מי\\\"ב):\",1,0],[8,356,6,3,\"ומ\\\"ש הרי שם מאתים ונמצא מנה הרי הוא חולין. לשון המשנה הכל מעשר וכבר השיגו הראב\\\"ד וטעם רבינו משום דתניא בפ\\\"ק דביצה (דף י':) ובפ\\\"ק דפסחים (דף ו') גבי בעיא דעכבר ובירושלמי פ\\\"ד דמע\\\"ש הניח מאתים ומצא מנה מנה מונח ומנה מוטל דברי רבי וחכמים אומרים הכל חולין וא\\\"כ מתני' רבי היא וחכמים פליגי עליה והלכתא כוותייהו דרבים נינהו. ואע\\\"ג דבפרק החולץ אמרינן דסתם במתניתין ומחלוקת בברייתא הלכה כסתם. שאני הכא דבפ\\\"ק דביצה טרחו אמוראי לאוקומי מתני' כחכמים משמע דסברי דהכי הלכתא ולא כסתם:\",2,0],[8,356,6,3,\"הניח מנה מעשר ונמצא מאתים וכו'. בפ\\\"ק דביצה (דף י':) ופסק כחכמים וכמ\\\"ד בשני כיסים מחלוקת אבל בכיס אחד הכל חולין:\",3,0],[8,356,6,7,\"אמר לו אביו כיס מעשר שני לי בבית וכו' עד ואם במתכוין דבריו קיימים. תוספתא פ\\\"ה דמעשר שני:\",1,0],[8,356,6,8,\"המוצא כלי וכו'. משנה פ\\\"ד דמע\\\"ש (מ\\\"י):\",1,0],[8,356,6,8,\"ומ\\\"ש ואם היה של מתכת וכו'. משנה שם וכרבנן דפליגי אר' יהודה:\",2,0],[8,356,6,9,\"מעות הנמצאות וכו'. משנה ט' שם כל המעות הנמצאות הרי אלו חולין אפילו דינר זהב עם הכסף ועם המעות מצא בתוכן חרס וכתוב עליו מעשר הרי זה מעשר ופי' רבינו בנמצאות בירושלים מיירי ונתן טעם הואיל ושוקי ירושלים מתכבדים בכל יום וטעם זה נאמר בפרק אלו מציאות ובפ\\\"ק דפסחים גבי הא דתנן בפ\\\"ז דשקלים מעות שנמצאו בירושלים בשאר ימות השנה חולין ובשעת הרגל הכל מעשר:\",1,0],[8,356,6,10,\"מעות הנמצאות לפני סוחרי בהמה וכו' והנמצאות בהר הבית וכו'. משנה פרק ז' דשקלים (משנה ב') והטעם שנתן רבינו. שם בירושלמי:\",1,0],[8,356,6,11,\"תיבה שנשתמש בה חולין וכו'. בפירקא קמא דפסחים (דף ז') והתם מוקי לה בשאינו יודע איזה מהן בסוף אי נמי שנשתמשו בה צבורין צבורין אי נמי כגון דאשתכח בגומא וצריך טעם למה השמיט רבינו אוקימתות אלו:\",1,0],[8,356,6,12,\"מצא פירות וכו'. תוספתא פרק שני דמעשר שני:\",1,0],[8,356,6,12,\"וכן המעות הנמצאות בין חולין למעשר. משנה פ\\\"ז דשקלים:\",2,0],[8,356,6,13,\"מעשר שני של דמאי ושל ודאי שנתערבו וכו'. בתוספתא הנזכרת:\",1,0],[8,356,6,14,\"פירות מעשר שנתערבו בפירות חולין וכו'. פשוט הוא:\",1,0],[8,356,6,14,\"ומה שכתב לפיכך אם נתערבו בירושלים אסורים בכל שהן וכו'. כך פירש רבינו ורבינו שמשון מה ששנינו בפרק ב' דבכורים ואסור לאכול כל שהן בירושלים.\",2,0],[8,356,6,14,\"ומה שכתב כמנין נראה דהכי פירושו אוסר בכל שהוא כמו שאוסר דבר שבמנין:\",3,0],[8,356,6,15,\"הזורע מעשר שני וכו'. בפרק תשיעי דתרומות (משנה ד') גידולי הקדש ומעשר שני חולין ופודה אותם בזמן זרעם ובירושלמי (הלכה ב') מה הפרש בין הקדש למעשר שני מעשר שני בין בדבר שזרעו כלה בין בדבר שאין זרעו כלה נפדה משמע בהדיא דבמקום הראוי לפדייה מיירי. ובפ\\\"ב דבכורים בירושלמי (הלכה ב') רמי האי מתני' אמתניתין דבכורים והעלו הן דתימר גידוליהן אסורים איסור מחיצה והן דתימר גידוליהן מותרים היתר זרות. ונראה שרבינו מפרש הא דאמר איסור מחיצה היינו כשנכנסו תוך המחיצות יש עליהם איסור כבתחילה והא דתנן מותרים היתר זרות דהיינו חוץ לחומה. ואפשר שזהו מה שאמרה המשנה אסורים מליאכל בירושלים דהיינו לומר אסורים מליאכל כשזרע בירושלים:\",1,0],[8,356,6,16,\"מעשר שני בטל ברוב וכו'. בפרק הזהב (בבא מציעא דף נ״ג):\",1,0],[8,356,7,1,\"פירות הנלקחות בכסף מעשר שני וכו'. משנה פרק ג' דמעשר שני (משנה י').\",1,0],[8,356,7,1,\"ומ\\\"ש אלא אם כן נטמאו. שם במשנה וכתנא קמא. ומה שחילק בין נטמאו באב הטומאה לנטמאו בולד הטומאה הטעם מבואר דכשאינו נטמא אלא מדבריהם מאחר דמדאורייתא טהור אינו נאכל בחוץ ומאחר שהוא טמא אע\\\"פ שאינו אלא מדבריהם יפדה:\",2,0],[8,356,7,4,\"אין נלקח בכסף מעשר וכו'. משנה וגמרא ריש פרק בכל מערבין (עירובין דף כ״ז:) ופרק ג' מינים (נזיר דף ל״ה).\",1,0],[8,356,7,4,\"ומ\\\"ש ולא פירות המחוברים לקרקע ולא פירות שאינם יכולים להגיע לירושלים. משנה פרק קמא דמעשר שני (משנה ה'):\",2,0],[8,356,7,5,\"הדבש והביצים והחלב וכו'. כתב מגדל עוז שיש ללמוד כן מדתניא בסיפרי פרשת ראה על פסוק עשר תעשר וגו' עד ואכלת יכול אף דבש וחלב ת״ל היוצא השדה ומשמע דאי לא מעטינהו קרא הוו בכלל ואכלת וגבי מעשר שני איתמר ואכלת וביצים אמרינן פרק בא סימן (נדה דף נ') דמטמאין טומאת אוכלים ובפרק ג' דעוקצין (משנה ו') משמע דכל שמטמא טומאת אוכלים הוא נלקח בכסף מעשר עכ״ל ואי מהא לא איריא דההיא דעוקצין רבי יוחנן בן נורי היא ור״ע פליג עליה והלכה כר״ע מחבירו אבל הטעם הוא משום דבפרק בא סימן אמרינן דנמנו וגמרו כר״י בן נורי:\",1,0],[8,356,7,6,\"התמד עד שלא החמיץ וכו'. משנה פ\\\"ק דמע\\\"ש (משנה ג') ופ\\\"ק דחולין (דף כ\\\"ה):\",1,0],[8,356,7,6,\"ומ\\\"ש לקחו עד שלא החמיץ וכו'. פ\\\"ק דחולין שם:\",2,0],[8,356,7,7,\"ומ״ש במה דברים אמורים בנתן ג' מים וכו'. בפ' המוכר פירות (בבא בתרא דף צ״ו) וכרבנן דאחרים:\",1,0],[8,356,7,8,\"לולבי זרדין וכו' עד נלקחין. תוספתא פ\\\"ק דמעשר שני ותוספתא דעוקצין פ\\\"ג:\",1,0],[8,356,7,8,\"והקור נלקח בכסף מעשר. משנה פ\\\"ג דעוקצין (משנה ז'):\",2,0],[8,356,7,9,\"הכרכום אינו נלקח וכו'. תוספתא פ\\\"ק דמע\\\"ש:\",1,0],[8,356,7,9,\"ומ״ש לפיכך ראשי בשמים הפלפלין וכו'. בפ״ג דעוקצין (מ״ה) איפליגו ביה תנאי ובפרק בא סימן (נדה דף נ') אמר רבי יוחנן בן נורי נמנו וגמרו שאין נלקחים בכסף מעשר:\",2,0],[8,356,7,10,\"השבת אם ליתן טעם וכו'. בפרק בא סימן (נדה דף נ״א):\",1,0],[8,356,7,10,\"עירב מים ומלח וכו'. בר״פ בכל מערבין (עירובין דף כ״ז):\",2,0],[8,356,7,11,\"אין לוקחים תרומות בכסף מעשר וכו'. משנה בפרק ג' דמע\\\"ש (משנה ב') כת\\\"ק.\",1,0],[8,356,7,11,\"ומ\\\"ש מפני שהוא ממעט אכילתו ואכילתה. שם בירושלמי:\",2,0],[8,356,7,12,\"ומ\\\"ש לוקחין בהמה לזבחי שלמים וכו'. במשנה שם:\",1,0],[8,356,7,12,\"בראשונה היו לוקחים בהמות וכו'. ירושלמי פ\\\"ק דמע\\\"ש אלא שכתוב בטעות ונוסחת רבינו עיקר:\",2,0],[8,356,7,13,\"אין לוקחים פירות שביעית וכו'. ג\\\"ז שם בירושלמי:\",1,0],[8,356,7,14,\"הלוקח מים וכו' עד לא קנה המעשר. משנה שם פ\\\"ק (משנה ה'):\",1,0],[8,356,7,14,\"ומ״ש אע״פ שיצאו המעות לחולין: כתב עליו הראב״ד אמר אברהם זה שיבוש אלא יחזרו דמים למקומן וכו'. ובאמת כי בירושלמי (הלכה ג') אמרו על משנתנו תמן תנינן אין לוקחים עבדים וקרקעות ובהמה טמאה מדמי שביעית ואם לקח יאכל כנגדו וכא את אמר הכין רבי יונה אמר איתפלגון רבי חייא בר יוסף ושמואל חד אמר כאן דרך מכירה כאן דרך חילול וחרנא אמר כאן שהמוכר קיים וכאן שהלך לו המוכר, ובפ' האיש מקדש (קידושין נ״ה:) ת״ר אין לוקחין בהמה במעות מעשר שני ואם לקח בשוגג יחזרו דמים למקומן במזיד תעלה ותאכל במקום ורמי עלה מדתנן אין לוקחין בהמה טמאה עבדים וקרקעות במעות מע״ש אפילו בירושלים ואם לקח יאכל כנגדן וכו' ואמאי יחזרו דמים למקומן כי התם אמר שמואל בשברח ופרש״י בשברח המוכר שהדמים בידו וזה מבואר כד' הראב״ד. ומצאתי כתוב שה״ר יונתן הכהן כתב להעמיד דברי רבינו שמאחר שמים ומלח ופירות מחוברים או שאינם יכולים להגיע לירושלים הם נודעים לכל שאסור ללקחן ודאי מזיד הוא ומעשר במזיד מתחלל עכ״ל. ואין דבריו נראין דאם כן לוקח עבדים וקרקעות ובהמה דאמרינן בפרק האיש מקדש שאדם יודע שאין מעות מעשר מתחללין עליהם ואפ״ה אמרינן יחזרו דמים למקומן. וליישב דברי רבינו נ״ל שגם רבינו פוסק דלוקח מים ומלח וכו' שיחזרו דמים למקומן ואם ליתיה למוכר יאכל כנגדן כי מ״ש לקמן זה הכלל כל שהוציא חוץ לאכילה ושתייה וסיכה וכו' קאי גם ללוקח מים ומלח וכו' שהדין שוה בכולם דאי ליתיה למוכר יאכל כנגדן ואם איתיה יחזרו דמים\",2,0],[8,356,7,14,\"למקומן ומ\\\"ש כאן אע\\\"פ שיצאו המעות לחולין אתא לאפוקי ממ\\\"ד בירושלמי כאן דרך מכירה כאן דרך חילול דהיינו לומר דכי תנן לא קנה מעשר היינו כשהיה דרך מכירה וכי קתני יאכל כנגדו דמשמע שהמכר קיים כשהיה דרך חילול ורבינו סובר דלא קי\\\"ל כוותיה כיון דגמ' דידן לא מפליג אלא בין איתיה למוכר לליתיה וכאידך אמורא דפליג על האי דמפליג בין דרך מכירה לדרך חילול וזהו שכתב אע\\\"פ שיצאו המעות לחולין כלומר אע\\\"פ שהיה דרך חילול לא קנה מעשר ואי ליתיה למוכר יאכל כנגדו ואם איתיה יחזרו דמים למקומן ואם תאמר ואי דרך חילול הוה הוי מזיד ואמאי יאכל כנגדו או יחזרו דמים למקומן הא מעשר מזיד מתחלל. וי\\\"ל דלאו מדינא אמרי' דיאכל כנגדו או יחזרו דמים למקומן אלא משום קנסא כדאמרי' בפ' האיש מקדש והשתא אתי שפיר מה שאמר רבינו לקח עבדים וכו' בין מזיד בין שוגג אם ברח המוכר יאכל כנגדו ואם המוכר קיים יחזרו דמים למקומן:\",3,0],[8,356,7,15,\"הלוקח פירות וכו'. משנה פ\\\"ק דמע\\\"ש (משנה ה') הלוקח פירות שוגג יחזרו הדמים למקומן מזיד יעלו ויאכלו במקום ואם אין מקדש ירקבו ומפרש רבינו דלוקח פירות חוץ לירושלים דאילו בירושלים אמאי יחזרו דמים למקומן הלא זה הוא דין מעות מע\\\"ש לוקח בהם פירות ואוכלם שם:\",1,0],[8,356,7,16,\"וכן אין לוקחים בהמה וכו'. ג\\\"ז משנה ו' שם הלוקח בהמה שוגג יחזרו דמים למקומן מזיד תעלה ותאכל במקום ואם אין מקדש תקבר ע\\\"י עורה. ובספרי רבינו (היה) כתוב מזיד במקום שוגג ושוגג במקום מזיד וט\\\"ס הוא ומפרשה רבינו בלוקח חוץ לירושלים מהטעם שכתבתי בסמוך:\",1,0],[8,356,7,17,\"לקח עבדים וקרקעות וכו'. ג\\\"ז משנה שם (משנה ז') אין לוקחין עבדים וקרקעות ובהמה טמאה מדמי מעשר שני ואם לקח יאכל כנגדן וכו' זה הכלל כל שהוא חוץ לאכילה ולשתיה ולסיכה מדמי מע\\\"ש יאכל כנגדו. ומה שחילק רבינו בין ברח המוכר ללא ברח בספ\\\"ב דקידושין (דף נ\\\"ו:):\",1,0],[8,356,7,17,\"ומה שאמר וכן אם הביא עולות וכו'. שם במשנה:\",2,0],[8,356,7,18,\"לקח חיה לזבחי שלמים וכו'. בס״פ התודה (מנחות דף פ״ב:):\",1,0],[8,356,7,18,\"לקח בהמה לשלמים וכו'. ירושלמי פרק ג' דמעשר שני:\",2,0],[8,356,7,18,\"כתב הראב\\\"ד א\\\"א מאי אף על פי כן וכו'. וי\\\"ל דרבינו ה\\\"ק אף על פי שאין בו חומש משום מעשר יש בו חומש משום פודה קדשים:\",3,0],[8,356,7,19,\"המתפיס מעות מעשר לשלמים וכו'. בס״פ התודה (מנחות דף פ״ב) פלוגתא דרבי יוחנן ורבי אלעזר ופסק כרבי אלעזר משום דרבי אמי סבר כוותיה ורבא נמי משמע דס״ל כוותיה:\",1,0],[8,356,7,20,\"האוכל מעשר שני וכו' אם פירות המעשר עצמן אכל יצעק לשמים כך היא הגירסא הנכונה בדברי רבינו. והדין בירושלמי פרק קמא דמע\\\"ש (הלכה א') האוכל מעשר שני שלו בין שוגג בין מזיד יצעק לשמים דברי רשב\\\"ג רבי אומר שוגג יצעק לשמים מזיד יחזרו דמיו למקומן ופסיק התם הלכה כרבי במעות וכרשב\\\"ג בפירות ופירוש יצעק לשמים נראה דהיינו לומר שיתפלל לשם שימחול לו ואינו צריך להחזיר דמים:\",1,0],[8,356,7,20,\"כתב הראב\\\"ד יצא ידי שמים א\\\"א יצעק לשמים. נראה שהיה גורס בדברי רבינו יצא ידי שמים ומשמע להרב רבי אברהם בן דוד ז\\\"ל דהיינו לומר שאינו צריך לאכול כנגדו ואין עליו עון אשר חטא וגורס יצא היו\\\"ד בפת\\\"ח (קמ\\\"ץ) ומפני כך משיג עליו שאינו כן שחטא חטא וצריך לצעוק עליו לשמים שימחול לו וליישב דברי רבינו יש לומר לאותה גירסא שגורס יצא ידי שמים היו\\\"ד בצירי והיינו לומר שצריך לצאת ידי שמים דהיינו שיתפלל ויצעק להקב\\\"ה שימחול לו עונו:\",2,0],[8,356,7,20,\"כתב עוד הראב\\\"ד ואם כסף מעשר אכל יחזרו דמים למקומן א\\\"א ומשלם מה שאכל וכו'. נראה שבא לומר שיש חסרון לשון בדברי רבינו שכך הוה ליה לכתוב יחזרו דמים למקומן וישלם מה שאכל:\",3,0],[8,356,8,2,\"הלוקח בהמה לזבחי שלמים וכו' עד יצא הקנקן לחולין. משנה בפ״ק דמעשר שני ופירוש יצא העור לחולין שאין צריך לאכול דמיו בירושלים ובר״פ בכל מערבין (עירובין דף כ״ז:) יליף לה מקרא. ומה שחילק בין תגר לשאינו תגר שם בירושלמי ופירש רבינו הטעם שכשהמוכר אינו יודע בסחורה אינו חושב שמכר אלא הבשר והיין בלבד ואינו מקפיד על העור והקנקן ולפיכך יצאו לחולין לפי שלא קנאו במעות מע״ש אבל אם קנאו מסוחר שיודע דמי הקנקן והעור לא יצא דמי העור והקנקן לחולין דודאי מכרו בשיווי העור והקנקן דסתם סוחר מקפיד גם על העור והקנקן ולא מכר לו אלא גם בשיווי העור והקנקן. וקאמר תו התם דהוא הדין ללוקח תגר וצריך טעם למה השמיטו רבינו ואפשר דלא היה גריס לה ואפילו תימא דגריס לה איכא למימר דסבירא ליה דאתי למיפלג ולאוסופי אקמייתא ונקטינן כקמייתא דד״ה היא ועוד דמסתבר טעמיה.\",1,0],[8,356,8,2,\"ועל מה שכתב רבינו לפיכך צריך המוכר לפתוח ראשי הכדים וכו'. כתב הראב\\\"ד לא ידעתי מה צורך וכו'. ויש לומר דלא משום שיהא לו הנאה בדבר נקט צריך אלא לישנא דמתניתין נקט דקתני מפתיח ואינו צריך לערות וה\\\"ק אם רצה שלא יצא קנקן לחולין פותח ראשי הכדים, ובשם ספר הבתים מצאתי יראה כי דעת הרב כדי שלא יצא לחולין שלא יהא נבלע עם היין שכיון שפתחן גילה דעתו שאין רצונו למכור הקנקן ע\\\"כ. ומ\\\"ש הראב\\\"ד ולא עוד אלא אם פתח הפסיד וכו' איני יודע מה הפסד יש למוכר אם הקונה יאכל כנגד קנקנו, ונראה שטעמו לומר דכי אמרינן לא יצא קנקן לחולין היינו לומר שאע\\\"פ שיחזירו הקנקן לבעליו צריך הוא לאכול כנגדו ואין זה במשמע דעת רבינו.\",2,0],[8,356,8,2,\"ומ\\\"ש לפיכך צריך המוכר לפתוח ראשי הכדים וכו'. משנה ספ\\\"ג דמ\\\"ש (משנה י\\\"ג) ב\\\"ש אומרים מפתיח ומערה לגת וב\\\"ה אומרים מפתיח ואינו צריך לערות וידוע דהלכה כב\\\"ה ומפרשה רבינו דקאי אמתניתין דפרק קמא דקתני כדי יין סתומות מקום שדרכן לימכר סתומות יצא קנקן לחולין פתוחות לא יצא קנקן לחולין והשתא קאמרי ב\\\"ש שכדי שלא יצא קנקן לחולין צריך שיפתח הכדים ויערם לגת דלא מיקרו פתוחות לענין זה בלאו הכי ולב\\\"ה במפתיח ראשי הכדים סגי לשלא יצא קנקן לחולין ואינו צריך לערות.\",3,0],[8,356,8,2,\"ומ\\\"ש רבינו ואם רצה להחמיר על עצמו וכו'. שם פ\\\"ג:\",4,0],[8,356,8,2,\"כתב הראב\\\"ד ואם רצה להחמיר על עצמו וכו'. א\\\"א פירוש שמדקדק על היין וכו' ופשוט הוא ונראה דליישב לשון להחמיר דקתני אתא ורבינו כתב בפירוש המשנה ואם מכר במדה ואמר מדת כך וכך בכך וכך דמים יצא קנקן לחולין ואפילו היו סתומות וטעמא מפני שיודע דמי היין ובודאי קיבל כל דמי שיווי היין בלא הבלעת הקנקן ולפיכך הקנקן חולין שלא חלה עליו קדושת המעות:\",5,0],[8,356,8,3,\"לקחן פתוחות או סתומות וכו' עד לא יצאו דמי הכלי לחולין. שם במשנה מסיים בה בד\\\"א וכו' במקום שדרכן לימכר פתוחות לא יצא קנקן לחולין, וה\\\"פ בד\\\"א שצריך לפתוח הכדים לשלא יצא קנקן לחולין במקום שדרכן לימכר סתומות וכו':\",1,0],[8,356,8,3,\"כתב הראב\\\"ד ויודע דמי היין והקנקן צריך לאותן הדמים, פירוש שהמוכר יודע כמה שוה היין ואין בו כדי הדמים שקיבל אלא עם הקנקן. ובנ\\\"א כתוב היין במקום הדמים וה\\\"פ מאחר שהוא מדקדק כ\\\"כ וקיבל כל דמי שיווי היין למה לא שייר הקנקן אצלו לכך אמר והקנקן צריך לאותו היין כלומר שאם היו מריקים אותו לכלי אחר היה מתקלקל. וטעם דינים אלו דכיון דמקרא ילפינן מדכתיב וביין מלמד שלוקחים יין על גב קנקן לא ילפינן מקרא אלא כשלוקחם סתומות דהוי יין אגב קנקן אבל פתוחות הוי כלוקח כל דבר בפני עצמו ולא בטל קנקן וכלוקח מן התגר דמיא ולא יצא קנקן לחולין כיון שהם פתוחות אע\\\"פ שהוא במקום שדרכן למכור סתומות כיון שזה פתחם הוי כלוקח קנקן בפני עצמו ואין זה נקרא יין על גבי קנקן וכן סתומות במקום שדרכן לימכר פתוחות כיון שדרך המקום כן הר\\\"ז כלוקח אותם פתוחות:\",2,0],[8,356,8,4,\"ומ\\\"ש לקח אגוזים ושקדים וכו'. משנה שם פ\\\"ק (מ\\\"ג).\",1,0],[8,356,8,4,\"ומ\\\"ש לקח חותל של תמרים וכו' קופה של תמרים וכו'. ירושלמי פ\\\"ק דמע\\\"ש:\",2,0],[8,356,8,5,\"מי שהיה לו יין וכו' עד קנה מעשר את הקנקן. משנה פ\\\"ג דמע\\\"ש (משנה י\\\"ב):\",1,0],[8,356,8,5,\"הפקיד לתוך הקנקן רביעית חולין וכו' עד את הקנקנים. תוספתא פ\\\"א ופ\\\"ב דמע\\\"ש (דף ס\\\"ז:) ובירושלמי פרק ג' (הלכה ו') רביעית חולין יש לי בחבית זו יצא קנקן לחולין:\",2,0],[8,356,8,6,\"צבי שלקחו בכסף מעשר וכו' לקחו חי ושחטו וכו'. משנה פ\\\"ג דמע\\\"ש (משנה י\\\"א):\",1,0],[8,356,8,6,\"המניח דינר וכו' הוקרו המעות וכו'. משנה פ\\\"ד דמ\\\"ש (משנה ח') וכת\\\"ק:\",2,0],[8,356,8,7,\"הלוקח פירות בסלע וכו' עד של דמאי: כתב הראב\\\"ד א\\\"א א\\\"א לזה בלא שיבוש וכו':\",1,0],[8,356,8,7,\"ועתה אבאר דע כי בפ\\\"ד דמע\\\"ש (משנה ו') תנן משך ממנו מעשר בסלע ולא הספיק לפדותו עד שעמד בשתים נותן לו סלע ומשתכר בסלע ומע\\\"ש שלו משך ממנו מעשר בשתים ולא הספיק לפדותו עד שעמד בסלע נותן לו סלע מחולין וסלע של מע\\\"ש שלו ואם היה ע\\\"ה נותן לו מדמאי ובירושלמי (הלכה ד') מתניתין דלא כרשב\\\"ג דתנינן רשב\\\"ג אומר לעולם משיכתו של מעשר שני הוא פדיונו ומפרש רבינו שקרא במשנה זה מעשר לפירות הנלקחים במעות מעשר וקרא פדייה נתינת הכסף של מעשר וברישא כיון שמשך הפירות נקנו לו בסלע כדין הדיוט ולפיכך אף על פי שהוקרו אינו צריך ליתן אלא סלע והשכר למעשר שכל אותם פירות צריך לאוכלם בתורת מעשר ובסיפא אף ע\\\"פ שמשך ממנו הפירות בשתים ונקנו לו אם הוזלו לא יפסיד המעשר ולא יתן משל מעשר אלא סלע בלבד. ומה שאמרו בירושלמי מתני' דלא כרשב\\\"ג לא קאי אלא אסיפא כלומר דלרשב\\\"ג כשם שברישא נקנו לו הפירות בסלע על ידי משיכה ואע\\\"פ שהוקרו אינו צריך לתת אלא סלע כשעת משיכה כן בסיפא כיון שמשך הפירות בשתים לצורך מעשר נתחייב המעשר בשתים ואע\\\"פ שהוזלו הפירות חייב לתת שתים משל מעשר כשעת משיכה והיינו דקתני בדרשב\\\"ג לעולם כלומר בין ברישא בין בסיפא לעולם בתר שעת משיכה אזלינן דמשיכתו של מעשר הוא פדיונו בין להחמיר בין להקל ואילו לתנא דמתניתין אע\\\"ג דברישא אזיל בתר שעת משיכה בסיפא לא אזיל בתר שעת משיכה לגבי מעשר אלא בתר שעת פדייה להקל על המעשר. ובזה נסתלק מה שהשיג הראב\\\"ד על רבינו ממה שאמר בירושלמי מתניתין דלא כרשב\\\"ג דאמר לעולם משיכתו של מעשר הוא פדיונו ומה שהשיג וכתב ועוד שבוש אחר שהלוקח פירות של חולין להחליפן בכסף מעשר מה עשה המעשר בכאן והלא הפירות שנמשכו חולין הם אטו אפוטרופוס של מעשר הוא שיהא ידו כיד המעשר עכ\\\"ל. י\\\"ל שמאחר שהוא משך אותם הפירות על מנת לפרעם ממעות מעשר נתחייבו מעות המעשר בכך לרשב\\\"ג בין להקל בין להחמיר ולתנא דמתני' להקל על המעשר ולא להחמיר כמו שנתבאר. אך ק\\\"ל על דברי רבינו מה שכתב שנאמר ונתן הכסף וקם לו בנתינת הכסף קונה שאילו היה שונה בתחלה שאם נתן לו סלע של מעשר בסאה פירות ולא הספיק למשוך הסאה פירות עד שעמדה בשתים נוטל הסאה פירות בסלע שנתן תחלה הוה שייך למיתני שנאמר ונתן הכסף וקם לו בנתינת הכסף קונה אבל השתא דקתני ברישא איפכא שאם משך פירות בסלע ולא הספיק ליתן את הסלע עד שהוקרו הפירות ועמדו בשתים אינו נותן אלא סלע היכי שייך למיתני עליה שנאמר ונתן הכסף וקם לו בנתינת הכסף קונה כלפי לייא הא איפכא הוא. ונראה שזו היתה כוונת הראב\\\"ד במה שכתב א\\\"א לזה בלא שיבוש שהרי לא נתן לו כסף ובמשיכתו הוא קונה עכ\\\"ל. ואפשר לומר שרבינו מפרש ונתן הכסף וקם לו כשבא ליתן הכסף יקום ויהיה לו ריוח ואע\\\"פ שבשער שעת נתינת הכסף היה ראוי לתת שתים יקום לו וירויח ולא יתן אלא סלע וזהו שסיים וכתב בנתינת הכסף קונה כלומר בערך שער שעת נתינת הכסף הוא מרויח:\",2,0],[8,356,8,7,\"ודע דבפרק האיש מקדש מביא משנה זו להוכיח דסתם לן תנא כרבי יהודה דאמר מע\\\"ש ממון הדיוט הוא ואמרו ת\\\"ש משך ממנו מעשר בסלע ולא הספיק לפדותו עד שעמד בשתים נותן לו סלע ומשתכר סלע ומע\\\"ש שלו מני אילימא ר\\\"מ אמאי משתכר בסלע ונתן הכסף וקם לו אמר רחמנא אלא לאו רבי יהודה ומאחר דאיפסקא הלכתא התם כר\\\"מ דאמר מע\\\"ש ממון גבוה הוא נמצא דלית הלכתא כאותה משנה ואע\\\"פ כן כתבה רבינו אלא ששינה בפירושה כי היכי דתיקום כהלכתא דפשט לשונה דמשך ממנו פירות מעשר בסלע ואינו נותן אלא סלע וקנה כל פירות המעשר שהוא שוה שתים ונמצא שהוא מרויח לעצמו סלע. ורבינו כתב כאן והשכר למעשר וכמו שביארתי לעיל דאזלינן להחמיר משום דמ\\\"ש ממון גבוה הוא:\",3,0],[8,356,8,9,\"נתן לו סלע של מעשר וכו' עד פדייתו היא משיכתו. תוספתא בפ\\\"ד דמעשר שני בלשון הזה ומה ששנינו והדין ביניהם נ\\\"ל דהיינו לומר שבמע\\\"ש העמידו דבריהם על דין תורה שמעות קונות והטעם שנשתנה דין ב' בבות אלו מב' בבות הקודמות משום דהתם שאני שלא נתן מעות המעשר עד לבסוף:\",1,0],[8,356,8,10,\"מי שהיו לו פירות חולין וכו' עד אומר כן אף לע\\\"ה. הכל משנה בפ\\\"ג דמע\\\"ש (משנה ד'):\",1,0],[8,356,8,13,\"ומותר לחלל פירות מע\\\"ש וכו'. בפ\\\"ד דטבול יום (משנה ה') ופ\\\"ד דמ\\\"ש:\",1,0],[8,356,8,13,\"כתב הראב\\\"ד לא בכל ענין כמו שהוא פושט וכו'. ובנוסחא דידן בתוספתא כתוב אם משום חוב מותר וצ\\\"ע:\",2,0],[8,356,8,14,\"המניח דינר של מעשר וכו'. משנה רפ\\\"ד דמע\\\"ש (משנה ח') המניח איסר של מעשר שני ואכל עליו י\\\"א באיסר ואחד ממאה באיסר בית שמאי אומרים הכל עשרה וב\\\"ה אומרים בודאי י\\\"א ובדמאי עשרה ופירש רבינו בפירוש המשנה וז\\\"ל ענין זה המאמר שאם יהיה אותו איסר של מע\\\"ש של דמאי ואכל בי' חלקים מי\\\"א חלק האיסר ונשאר עליו חלק מי\\\"א כבר יצא האיסור לחולין וכו' ואם יהיה האיסר של מע\\\"ש של ודאי הדין בו א' מק' וכו' ואמרי ב\\\"ש דכל עשרה בין דמאי בין ודאי כיון שלא נשאר בו כאיסר אלא עשיריתו יצא לחולין אבל אם נשאר בו יותר צריך לאכול כנגדו וכו' ואמרו ב\\\"ה בודאי י\\\"א ובדמאי עשרה אבל אם נשאר עליו כאיסר של דמאי עשירית נתחייב לאכול כנגדו וזה לפי שהעיקר אצלינו כי מה שהוא שוה פחות משוה פרוטה אין חוששין לו בכל התורה לא לענין גזל ולא לענין נהנה מן ההקדש ולא לשום ענין וכו' ופרוטה היא אחד משמנה באיסר האיטלקי נמצא עשירית האיסר שמנה עשיריות הפרוטה וכשתוסיף עליהם החומש החייב מי שפודה מע\\\"ש שלו שכבר ביארנו שהוא רביעית הדבר הנפדה יהיה הכל פרוטה וכשנשאר מהאיסר עשיריתו חוששין עליו לפי שכשמוסיפין עליו החומש יהיה הכל ש\\\"פ ואם הוא פחות מהעשירית אין חוששין לו לפי שאין בו שוה פרוטה אפילו בתוספת החומש ולפיכך אמרו בודאי י\\\"א ובדמאי עשרה לפי שאינו חייב בחומש ועשיריתו הוא פחות מש\\\"פ כמו שביארנו ע\\\"כ לשונו:\",1,0],[8,356,8,14,\"ומ\\\"ש שנשאר ממנו פחות מד' חומשי שוה פרוטה. כתב הראב\\\"ד ז\\\"ל שהוא שיבוש וראוי להיות שנשאר ממנו ד' חומשי פרוטה עכ\\\"ל ולע\\\"ד נראין דברי רבינו מכוונים שאם נשארו ד' חומשי פרוטה כשאתה מוסיף עליו חומש הרי כאן פרוטה שלימה ולא יצא לחולין ולכך צריך שישאר פחות מד' חומשי פרוטה ויש בספרי רבינו חסרון תיבת אלא וכך מצאתי בספר מוגה עד שלא נשאר ממנו אלא פחות מפרוטה והרא\\\"ש הקשה על פירוש זה דאיך נתיר לזלזל במע\\\"ש שאין בו ש\\\"פ להוציאו לחולין לכתחלה דהא אמר חזקיה מעשר שני שאין בו שוה פרוטה מחללו על מעות הראשונות ועוד דהא קי\\\"ל דאין מוסיפין חומש על פדיון שני וזה פדיון שני הוא ועוד שאמרו בירושלמי ב\\\"ש כר\\\"א הנאמן על השני נאמן על הראשון ולפי פי' זה אין ענין לב\\\"ש בדר\\\"א ולראשונה יש לתרץ דהא אסיקנא דחזקיה אין בחומשו קאמר אבל בקרן יש יותר מג' פרוטות כמבואר בדברי רבינו בפ\\\"ה, והר\\\"י קורקוס ז\\\"ל כתב דעי\\\"ל דאם מתחלה היה פחות מש\\\"פ לבד ודאי שאין לזלזל בו ולהוציאו לחולין לכתחלה אלא הכא הרי אותו פחות מש\\\"פ הנשאר כאילו נתחלל על מה שאכל והוי כמו הבלעה שאין אדם מצמצם מעותיו ודמי לדחזקיה ואין זה זילזול וגם זה חילול מעשר הוא ואין אדם מצמצם בחילול שהרי אם היה לו פחות מפרוטה מחללו על מעות אחרות שחילל עליהם כבר מטעם זה דמסתמא יש בהם תוספת דאין אדם מחלל בצמצום כי ירא פן יפחות וכיון שכן גם כן החילול עצמו אם ישאר פחות מפרוטה לא נחוש לו דאומרין שהיה לו תוספת וזה נכון ומכל מקום ודאי דלכתחילה אין אומרים לו אכול ט' חלקים ותניח העשירית אם אכל שמנה אומרים לו אכול שנים אבל אם אכל אחת אז אותו עשירית הנשאר כיון שהוא פחות מש\\\"פ אין חוששין לו מטעם שנתבאר עכ\\\"ל. ולי אין צורך לידחק בכל זה שהתירוץ הראשון הוא אמת וא\\\"כ קושיא מעיקרא ליתא וקושיא שניה נמי ליתא דהא דאין מוסיפין חומש בפדיון שני היינו על החומש דוקא אבל על הקרן גם בפדיון שני מוסיף חומש כדאיתא בפרק הזהב ומבואר בדברי רבינו בפ\\\"ה. ולשלישית שהקשה מהירושלמי הנה ר\\\"ש פי' משנה זו ע\\\"פ הירושלמי והקשה עליו הרא\\\"ש ור\\\"ש עצמו נתקשה בפירוש הירושלמי ואליהו עתיד לפרש. ופירוש רבינו במשנה מחוור וה\\\"ר עובדי' ז\\\"ל לא כתב אלא פירוש זה אע\\\"פ שבמקומות אחרים דרכו לימשך אחר פירושי רבינו שמשון:\",2,0],[8,356,8,15,\"טמאים וטהורים שהיו אוכלים וכו'. משנה ספ\\\"ב דמע\\\"ש (משנה י'):\",1,0],[8,356,8,15,\"וכתב הראב\\\"ד שלא יטמאוהו א\\\"א פירשו בגמרא וכו' ויש לדקדק הא בדאורייתא אין ברירה ושמא לכך נתכוון הראב\\\"ד להשיג על רבינו למה פסק כמשנה זו דהא אתיא דלא כהלכתא ומ\\\"מ על מ\\\"ש הראב\\\"ד בשם הגמ' יש לדון דהכי איתא בירושלמי (הלכה ד') על משנה זו מה נן קיימין אם באומר מכבר משקה מעורב הוא ואם באומר לכשישתו למפרע חולין שתו אלא כי נן קיימין באומר מכבר לכשישתה, ונראה דה\\\"פ אם באומר מכבר כלומר אם באומר מעכשיו תהא מחוללת סלע זו על מה שישתו טהורים משקה מעורב ונמצאו טמאים שותים מעשר ואם באומר לכשישתו תהא מחוללת עליו למפרע חולין שתו שבשעה ששתו עדיין לא נתחלל והיאך יתחלל לאחר שכבר שתו אותו אלא באומר מכבר לכשישתו כלומר סמוך לעת שמתחילים לשתות תהא סלע זו מחוללת עליו דהשתא חל החילול קודם שיתחילו לשתות ולא מופלג אלא סמוך ביותר בשעה שפירש היין מהכד לפיהם דהשתא אינו ענין לברירה. והראב\\\"ד מפרש דמדבר לכשישתו היינו מעכשיו לכשישתו והרי זה ברירה. ומכל מקום יש חסרון לשון בדברי הראב\\\"ד וצריך להגיה אלא מעכשיו לכשישתו ורבינו העתיק המשנה כצורתה כמנהגו בכמה מקומות.\",2,0],[8,356,8,15,\"ומה שכתב ובלבד שלא יגעו הטמאים במאכל וכו'. פשוט הוא ובירושלמי בטמאים טמאים טמא מת שאין כלי חרס מיטמא מאחוריו אבל בטמאים טומאת זיבה שהזב מטמא בהיסט לא במה דברים אמורים כשאין אחר מערה אבל אם יש אחר מערה אפילו טמאים טומאת זיבה:\",3,0],[8,356,9,1,\"נטע רבעי הרי הוא קדש וכו'. ומ\\\"ש ודינו להאכל בירושלים לבעליו וכו'. כ\\\"כ רבינו בסה\\\"מ שלו סי' קי\\\"ט וז\\\"ל נטע רבעי דינו שיעלהו לירושלים ויאכלוהו שם בעליו כמו מעשר שני בשוה ואין לכהנים בו כלום שנאמר ואיש את קדשיו לו יהיו משך הכתוב כל הקדשים ונתנם לכהן ולא שייר מהם אלא תודה ומעשר ושלמים ופסח ומעשר בהמה ומע\\\"ש ונטע רבעי שיהיו לבעלים עכ\\\"ל. והוא בסיפרא ובפרק בתרא דמע\\\"ש (הלכה ב') ירושל' כתיב ובשנה החמישית תאכלו את פריו להוסיף לכם תבואתה ר\\\"י הגלילי אומר הרי את כמוסיף פירות חמישית על פירות רביעית מה פירות חמישית לבעלים אף פירות רביעית לבעלים. ובסיפרא פרשת קדושים נתבאר שטעון הבאת מקום כמעשר:\",1,0],[8,356,9,1,\"ומה שכתב וכשם שאין מעשר שני בסוריא כך אין נטע רבעי בסוריא. ירושלמי פ\\\"ז דפאה ופ\\\"ה דמע\\\"ש ובתשובות להרמב\\\"ן סימן קנ\\\"ו הביא הירושלמי הזה ופלפל בו והעלו דנטע רבעי נוהג אפי' בח\\\"ל ושכן דעת כמה גדולים מכל מקום פשט הירושלמי כדברי רבינו.\",2,0],[8,356,9,1,\"ומ\\\"ש ובנטע רבעי הוא אומר וכו' צריך להתפרש כמו שנתבאר בסמוך:\",3,0],[8,356,9,2,\"הרוצה לפדות נטע רבעי וכו' ואם פדהו לעצמו מוסיף חומש. משנה פרק חמישי דמעשר שני (משנה ג') ובפרק האיש מקדש (קידושין דף נ״ד):\",1,0],[8,356,9,2,\"ומה שכתב ואין פודין אותו עד שיגיע לעונת המעשר וכו'. בסיפרא פרשת קדושים.\",2,0],[8,356,9,2,\"ומה שכתב ואין פודים אותו במחובר וכו' תוספתא בסוף מעשר שני (דף ס\\\"ח:) כרם רבעי וכו' בית שמאי אומרים אין פודים אותם ענבים אלא יין ובית הלל אומרים יין וענבים אבל הכל מודים שאין פודים במחובר לקרקע. כתוב בתשובות להרמב\\\"ן סימן קנ\\\"ז וז\\\"ל הרמב\\\"ם נתן טעם למה אין פודים אותו במחובר מפני שהוא כמעשר שני ואין מעשר שני במחובר ורבינו שמשון כתב שאי אפשר לומר טעם זה משום דבפרק מרובה משמע דפדיון במחובר מועיל דבר תורה דאמרינן התם א\\\"ר יוחנן גזל ולא נתייאשו הבעלים שניהם אינם יכולים להקדיש זה לפי שאינו שלו וזה לפי שאינו ברשותו ואקשינן עלה מדתנן הצנועים מניחים המעות ואומר כל הנלקט מזה יהא מחולל על המעות הללו ופרקינן לא תימא כל הנלקט אלא כל המתלקט כלומר דקודם לקיטה היו הצנועים פודים ולא אחר לקיטה שכבר זכו בהם אחרים ולא היה כח ביד הבעלים לחלל ע\\\"כ. ומכאן קשה לדברי הרמב\\\"ם ואע\\\"ג דאסיקנא התם אלא לעולם כל הנלקט מ\\\"מ לאו מכח קושיא זו שאין פודין נטע רבעי במחובר חזר בו אלא דבכדי לא משבשינן וכ\\\"ש ממאי דמתרצינן מעיקרא ואמרינן אימא כל המתלקט שמעינן דמדאורייתא אית ליה פדיון אפילו במחובר וקשיא הא שמעתא דמרובה אתוספתא ומעשים בכל יום שפודים במחובר, ועם מ\\\"ש רבינו שמשון נתיישב שהוא ז\\\"ל פי' דטעמא דאין פודין במחובר לפי שאינם בקיאים בשומא בעודו במחובר והא דמחללין גבי צנועים התם עבוד שלא יכשלו וזה נכון ומכלל דבריו בזמן הזה שאין מדקדק בשוויו אלא כשמואל דאמר אם חיללו על ש\\\"פ מחולל הילכך מוקמינן ליה אדינא דאורייתא ואפילו במחובר שפיר דמי עכ\\\"ל. ולענין מה שהקשה על רבינו מפרק מרובה י\\\"ל דכיון דאסיקנא אלא לעולם כל הנלקט אע\\\"ג דלאו מכח קושיא זו דאין פודין במחובר הדר ביה איכא למימר אה\\\"נ דאי לא הוה אידך קושיא הוה מהדר מכח האי קושיא דאין פודין במחובר ונכון הדבר לומר כן כדי שלא לדחות תוספתא השנויה סתם בלא מחלוקת:\",3,0],[8,356,9,2,\"ומ״ש לפיכך אינו נקנה במתנה אלא אם נתנו בוסר. בפרק האיש מקדש (קידושין דף נ״ד:) והתנן הפודה מע״ש שלו מוסיף עליו חמישיתו בין שהוא שלו בין שניתן לו במתנה וכו' מי מצי יהיב ליה והא גמר קדש קדש ממעשר אלא לאו רבי יהודה ומשני לעולם רבי מאיר והב״ע כגון דיהיב כשהוא סמדר ודלא כרבי יוסי דאמר סמדר אסור מפני שהוא פרי. ומ״מ י״ל למה שינה רבינו וכתב בוסר במקום סמדר דמשמע דבוסר גדול מסמדר וע״כ לא שרינן אלא סמדר ולא בוסר ואין לומר שטעמו משום דמשמע ליה טעמא דשרינן סמדר משום דאינו פרי ובוסר נמי אינו פרי שהרי כשהגיע לכפול הלבן מברכין עליו בורא פרי האדמה וצריך עיון.\",4,0],[8,356,9,2,\"ומה שאמר ודינו בשאר הדברים וכו':\",5,0],[8,356,9,3,\"והפודה כרם רבעי רצה פודהו ענבים רצה פודהו יין. תוספתא פרק חמישי דמ\\\"ש וכב\\\"ה.\",1,0],[8,356,9,3,\"ומה שכתב וכן הזיתים. ומה שכתב אבל שאר הפירות אין משנין מברייתן. משנה בפי\\\"א דתרומות (משנה ג') ושאר כל הפירות אין משנין אותן מברייתן בתרומה ומע\\\"ש אלא זיתים וענבים. ונטע רבעי יליף קדש קדש ממעשר:\",2,0],[8,356,9,4,\"כרם רבעי אין לו לא שכחה וכו'. משנה בפ' בתרא דמע\\\"ש (משנה ג') ופ\\\"ז דפאה (משנה ו') ב\\\"ש אומרים יש לו פרט ויש לו עוללות וכו' וב\\\"ה אומרים כולו לגת וטעמא דב\\\"ה דילפי קדש קדש ממעשר:\",1,0],[8,356,9,4,\"ומה שכתב ואין מפרישין ממנו תרומה ומעשרות וכו'. שם בירושלמי:\",2,0],[8,356,9,5,\"ענבים של כרם רבעי וכו'. משנה פ\\\"ה דמע\\\"ש (משנה ב'):\",1,0],[8,356,9,5,\"ומ\\\"ש ושאר כל הפירות וכו'. שם בירושלמי שמתחלה לא גזרו אלא על הענבים:\",2,0],[8,356,9,6,\"כיצד פודין נטע רבעי וכו' עד כל הנלקט מפירות אלו מחולל על המעות הללו. משנה בפ\\\"ה דמע\\\"ש (משנה ד'):\",1,0],[8,356,9,7,\"ומ״ש רבינו מי שהיה לו נטע רבעי בשנת השמיטה וכו' וגם כתב והצנועים היו מניחים את המעות בשנת השמטה. כרשב״ג דהלכה כמותו כדאמרינן בפ' מרובה (בבא קמא דף ס״ט):\",1,0],[8,356,9,7,\"כתוב בתשובות להרמב\\\"ן סי' קנ\\\"ו על מה שכתב רבינו והצנועים היו מניחים את המעות וכו'. אינו מחוור דהא קיימא לן כר' יוחנן דאמר גזל ולא נתייאשו הבעלים שניהם אינם יכולים להקדיש וכו' ואע\\\"ג דמתניתין קתני הנלקט אנן לא קי\\\"ל כסתמא זו אלא כסתמא אחרינא דאין הגונב אחר הגנב משלם תשלומי כפל וכדמסיים עליה קרא ואי כי יקדיש את ביתו קדש מה ביתו ברשותו אף כל ברשותו. ואולי דעת הרב דשאני נטע רבעי דכיון דממון גבוה הוא ואפי' הכי אוקמיה רחמנא ברשותיה לאחולי מש\\\"ה לא איכפת לן ביה אי מחיל ליה ואפי' כי ליתיה ברשותיה דסוף סוף אפילו כי איתיה ברשותיה לאו דיליה הוא ואפ\\\"ה מצי מחיל ליה וכדאמר רבא התם בפ' מרובה אי לאו דאמר רבי יוחנן צנועים ורבי דוסא אמרו דבר אחד ה\\\"א מאן תנא צנועים ר\\\"מ היא לאו אמר ר\\\"מ מעשר ממון גבוה הוא ואפילו הכי לענין פדייה אוקמיה רחמנא ברשותיה דכתיב ואם גאול יגאל איש ממעשרו וכו' קרייה רחמנא מעשרו ומוסיף חומש כ\\\"ר נמי גמר קדש קדש ממעשר וכו' מה קדש דכתיב גבי מעשר אע\\\"ג דממון גבוה הוא וכו' לענין אחולי אוקמיה רחמנא ברשותיה [הילכך אע\\\"ג דליתיה ברשותיה מצי מחיל] דהא כי איתיה ברשותיה לאו דידיה הוא ומצי מחיל והא ליתא דהא רבא לא פליג אדרבי יוחנן אלא אי לאו דאמר רבי יוחנן ליתא להאי טעמא וכיון שכן הוא דצנועים ליתא כלל דאי אמר כל הנלקט לא הוי פדיון דלאו ברשותיה וכדר' יוחנן ואי אמר כל המתלקט לא אפשר משום דבדאורייתא אין ברירה ולא ידענא לה פתר להא דצנועים לפסק הלכה עכ\\\"ל. וי\\\"ל לדעת רבינו דלא דחינן מתניתין מהלכתא משום דלפי האמת ליכא לאקשויי מדצנועים להא דאמר רבי יוחנן זה אינו יכול להקדיש לפי שאינו ברשותו משום דאע\\\"ג דאין אדם יכול להקדיש דבר שאינו ברשותו יכול הוא לחלל דבר שאינו ברשותו וכמו שהוכיחו התוספות בדיבור המתחיל הוא דאמר כצנועים ואם כן כל מאי דשקיל וטרי גמרא ומסיק דרבי יוחנן לית ליה דצנועים היינו לפום מאי דקס\\\"ד דכשם שאין אדם יכול להקדיש דבר שאינו ברשותו כך אינו יכול לחלל דבר שאינו ברשותו אבל לפום קושטא דמילתא שפיר מצי סבר ר' יוחנן שאדם יכול לחלל דבר שאינו ברשותו וכדצנועים והא דאמר רבא אי לאו דאמר רבי יוחנן צנועים ורבי דוסא אמרו דבר אחד ה\\\"א מאן תנא צנועים ר\\\"מ היא וכו' היינו לומר דאפילו למאי דקס\\\"ד לדמויי חילול להקדש ה\\\"א דרחמנא אוקמיה ברשותיה לענין חילול אבל לפום קושטא לא צריכין להכי דבלאו הכי שפיר יכול לחלולי נטע רבעי של חבירו שלא מדעתו וכדאמרן:\",2,0],[8,356,9,8,\"באחד בתשרי ר\\\"ה לערלה ולרבעי. משנה פ\\\"ק דר\\\"ה (דף י'):\",1,0],[8,356,9,8,\"ומ\\\"ש אלא ל' יום בשנה חשובים שנה וכו' עד מר\\\"ה של שנת י\\\"ד עד סופה. שם וכר' יוסי ור' יהודה דאיפסיקא הלכתא כותייהו בס\\\"פ הערל לרב דהלכה כוותיה באיסורי ומפרש רבינו כפירוש התוספות דאערלה קאי:\",2,0],[8,356,9,12,\"ומ\\\"ש ואם נתעברה השנה נתעברה לערלה ולרבעי. ומה שכתב נטע הנטיעה מר\\\"ח תשרי וכו'. זהו דעת רבינו שסובר שכשאמרו ופירות נטיעה זו אסורים עד ט\\\"ו בשבט לא אמרו אלא דוקא בנטיעה שהקלנו עליה מתחלתה שעלו לה ל' יום לשנה שלימה ולפיכך מחמירים עליה בסופה והיינו דאמר פירות נטיעה זו וכתב הר\\\"ן שהרז\\\"ה חולק ופלוגתא היא בירושלמי וכתב הראב\\\"ד הירוש' הזה בהשגות וז\\\"ל. א\\\"א דבר זה הוציא מהירושלמי של ר\\\"ה וכו'. ויש לתמוה על מ\\\"ש הר\\\"ן דפלוגתא היא בירושלמי דלפי האמת לאו פלוגתא היא דאע\\\"ג דאקשי ליה אפילו נטעו ל' יום לפני ר\\\"ה יהא אסור עד ל' יום לפני ר\\\"ה הרי השיב לו ושתק ועוד דהאי דאקשי ליה אפילו נטעו ל' יום לפני ר\\\"ה אינו סותר דין זה שכתב רבינו וק\\\"ל:\",1,0],[8,356,9,12,\"מונה שלש שנים מיום ליום. כתב הראב\\\"ד מיום ליום שאמרו מט\\\"ו לשבט עד ט\\\"ו לשבט וכו'. ואני אומר שמ\\\"ש שאינו ר\\\"ל מראש תשרי לראש תשרי לפי שאינן שלימות וכו' פשוט הוא ולא הוצרך רבינו לבארו אבל מה שכתב מט\\\"ו בשבט לט\\\"ו בשבט אינו מדוקדק שכבר אפשר שיהיה קודם לכן או אחרי כן כי המנין הוא מיום הנטיעה ועוד י\\\"ד ימים של קליטה ופשוט הוא:\",2,0],[8,356,9,12,\"וראיתי לגאונים דברים וכו'. נראה שכיון לדברי בה\\\"ג שכתבו התוס' ורבינו שמשון והרא\\\"ש ודחאום בשתי ידים ורבינו תלה הדבר בט\\\"ס:\",3,0],[8,356,9,13,\"העלין והלולבין ומי הגפנים וכו' עד והנובלות כולן אסורות. משנה פ\\\"ק דערלה (משנה ז') ובת\\\"כ מייתי לי' מקרא וכבר כתבתי לעיל דלית הלכתא כר' יוסי דאמר הסמדר אסור:\",1,0],[8,356,10,1,\"כל שהוא חייב בערלה יש לו רבעי וכו'. ירושלמי בפ\\\"ק דערלה כל שאין לו ערלה אין לו רבעי והיינו דוקא בארץ דאילו בח\\\"ל הרי נטע שהוא חייב בערלה מן ההלכה ואינו חייב ברבעי כמבואר בפ' זה ובפ\\\"י ממאכלות אסורות:\",1,0],[8,356,10,2,\"הנוטע אילן מאכל וכו'. משנה בפ\\\"ק דערלה (משנה א'):\",1,0],[8,356,10,2,\"נטעו לסייג וכו'. ירושלמי שם:\",2,0],[8,356,10,2,\"נטעו שלש שנים לסייג וכו'. ג\\\"ז שם בירושלמי:\",3,0],[8,356,10,3,\"נטע אילן וחשב וכו'. משנה שם לר' יוסי ונראה שסובר רבינו דלא אתא לאיפלוגי את\\\"ק אלא לפרושי ויש הוכחה לזה מהירושלמי דמוקי לרבי יוסי בין לרשב\\\"ג בין לרבי וכן פסק הרא\\\"ש כר\\\"י:\",1,0],[8,356,10,3,\"והצלף חייב בערלה האביונות בלבד וכו'. בריש פרק כיצד מברכין (ברכות דף ל״ו) מסיק הלכתא כמר בר רב אשי דזריק את האביונות ואכיל את הקפריסין:\",2,0],[8,356,10,4,\"הנוטע לרבים וכו'. משנה שם בפרק קמא (מ\\\"ב) וכת\\\"ק.\",1,0],[8,356,10,4,\"ומ\\\"ש בתוך שדהו שם בירושלמי:\",2,0],[8,356,10,4,\"ומ״ש שנאמר ונטעתם אפילו לרבים. בר״פ כל שעה (פסחים דף כ״ג) ואע״פ ששם אמרו לרבנן ונטעתם ליחיד משמע כתב רחמנא לכם להביא הנטוע לרבים לא חשש רבינו.\",3,0],[8,356,10,4,\"ומ\\\"ש בד\\\"א בא\\\"י וכו' [ירושלמי שם]:\",4,0],[8,356,10,5,\"הנוטע ברשות הרבים או בספינה והעולה מאליו. משנה שם פ\\\"ק דערלה והוסיף רבינו וכתב ברה\\\"י משום דתני בתוספתא דערלה העולה מאליו פטור. ובהכי ניחא מאי דתניא בסיפרא ונטעתם פרט לעולה מאליו דלא תיקשי דמתניתין ברה\\\"י ודסיפרא בר\\\"ה:\",1,0],[8,356,10,5,\"ומ\\\"ש ונכרי שנטע בין לישראל בין לעצמו. בפיהמ\\\"ש כתב רבינו דדוקא בנטע לישראל וכאן חזר בו משום דבכמה דוכתי משמע בנטע העכו\\\"ם לעצמו אסור משום ערלה כמו שכתב ה\\\"ג:\",2,0],[8,356,10,6,\"העולה מאליו במקום חורשים וכו' עד חייב בערלה. ירושלמי פ\\\"ק דערלה:\",1,0],[8,356,10,7,\"הנוטע למצוה וכו'. גם זה שם בירושלמי:\",1,0],[8,356,10,7,\"הקדישו ואחר כך נטע וכו'. גם זה שם בירושלמי:\",2,0],[8,356,10,8,\"הנוטע בעציץ שאינו נקוב חייב בערלה וכו'. גם זה שם בירושלמי:\",1,0],[8,356,10,9,\"אילן שנטעו בתוך הבית חייב בערלה. ג\\\"ז שם בירושל':\",1,0],[8,356,10,9,\"זה שנטעו עכו\\\"ם עד שלא באו לארץ פטור וכו' עד משעת ביאה. ג\\\"ז שם בירושלמי:\",2,0],[8,356,10,10,\"עכו\\\"ם שהרכיב אילן מאכל וכו'. ג\\\"ז שם בירושל':\",1,0],[8,356,10,10,\"ויש לנכרי נטע רבעי וכו'. משנה פ\\\"ג דתרומה (מ\\\"ט) וכת\\\"ק:\",2,0],[8,356,10,11,\"אחד הנוטע גרעינה כו'. בסיפרא פ' קדושים נטע ייחור מניין תלמוד לומר כל עץ. ויש בספרי רבינו חסרון וכן מצאתי בספר מוגה או שעקר את כל האילן ממקומו ונטעו במקום אחר:\",1,0],[8,356,10,11,\"זעזעו ולא עקרו וכו' עד ואם לאו חייב. משנה פירקא קמא דערלה (מ\\\"ג):\",2,0],[8,356,10,13,\"אילן שקצצו מעם הארץ וכו'. ירושלמי ספ\\\"ק דשביעית וכחכמים:\",1,0],[8,356,10,14,\"אחד הנוטע ואחד המבריך וכו'. בפ\\\"ק דר\\\"ה (דף ט':) משמע בברייתא דמבריך ומרכיב חייב בערלה ובסיפרא תניא ונטעתם פרט למבריך ומרכיב ותירצו רבינו ורבינו שמשון בפירוש המשנה פ\\\"ק דערלה (מ\\\"ה) דההיא דסיפרא מיירי בשלא נפסקה מן האב והיא יונקת ממנו וההיא ברייתא דפירקא קמא דר\\\"ה בשנפסקה וכ\\\"כ הר\\\"ן דפירקא קמא דר\\\"ה בהלכות ערלה:\",1,0],[8,356,10,15,\"ומ\\\"ש גדל זה הילד שהבריך ועשה פירות וכו'. משנה פ\\\"ק דערלה הבריכה שנה אחר שנה ונפסקה מונה משעה שנפסקה בריכה שנפסקה והיא מליאה פירות אם הוסיף במאתים אסור:\",1,0],[8,356,10,16,\"ילדה שסיבכה בזקנה והיו פירות בילדה וכו'. מימרא בפרק הנודר מן הירק עלה נ\\\"ז:\",1,0],[8,356,10,17,\"אילן שהבריך ממנו בד אחד בארץ וכו'. משנה פ\\\"ק דערלה (משנה ה') אילן שנעקר ובו בריכה והוא חיה ממנה חזרה הזקינה להיות כבריכה. ויש בספרי רבינו תיבת מפני מיותרת וצריך למוחקה:\",1,0],[8,356,10,18,\"הרי שהבריך בד אחד בארץ וצמח וכו'. שם במשנה כתבתיה בסמוך הבריכה שנה אחר שנה ונפסקה מונה משעה שנפסקה:\",1,0],[8,356,10,19,\"אילן היוצא מן הגזע פטור מן הערלה מן השרשים חייב. תוספתא אלא ששם שנויה בסגנון זה אילן העולה בין מן הגזע בין מן השרשים חייב רבי יהודה אומר העולה מן הגזע חייב מן השרשים פטור ורבינו גירסא אחרת היתה לו ששנוי בה בדברי ת\\\"ק מן הגזע פטור מן השרשים חייב. ובפרק המוכר פירות פירשו רואה פני חמה זהו גזע שאינו רואה פני חמה זהו מן השרשים:\",1,0],[8,356,10,19,\"ילדה פחותה מטפח וכו' עד לשאר האילנות. בס\\\"פ משוח מלחמה עלה מ\\\"ג:\",2,0],[8,356,10,20,\"נוטעין יחור של ערלה וכו'. משנה פ\\\"ק דערלה (משנה ט')\",1,0],[8,356,10,20,\"ומה שכתב ואם עבר ונטע וכו'. בס״פ כל הצלמים (עבודה זרה מ״ח:) וטעמא משום דזה וזה גורם מותר:\",2,0],[8,356,10,21,\"ומ\\\"ש וכן אין מרכיבין כפניות של ערלה וכו'. משנה שם בפ\\\"ק דערלה:\",1,0],[8,356,10,21,\"ומ\\\"ש עבר והרכיב מותר וכו'. כבר נתבאר בסמוך:\",2,0],[8,356,11,1,\"מצות עשה להתודות לפני ה' וכו' שנאמר כי תכלה לעשר וכו'. פשוט הוא:\",1,0],[8,356,11,3,\"ומ\\\"ש ואין מתודין וידוי זה אלא אחר השנה שמפרישין בה מעשר עני וכו' עד בין פירות הארץ. משנה וירושלמי בפרקא בתרא דמע\\\"ש (משנה י') וכתוב בספרי רבינו אחר השנה שמפרישין בה מעשר שני והוא ט\\\"ס וצריך להגיה מעשר עני במקום מעשר שני:\",1,0],[8,356,11,4,\"אין מתודין אלא ביום כו'. משנה בסוף פרק ב' דמגילה (דף כ':):\",1,0],[8,356,11,4,\"ובין בפני הבית בין שלא בפני הבית חייב לבער ולהתודות: כתב הראב\\\"ד זה שיבוש שהוידוי אינו אלא לפני ה' ואין לפני ה' אלא בבית עכ\\\"ל. ואפשר לומר שטעם רבינו שכיון שהוא חייב לבער אפילו שלא בפני הבית למה ימנע מלהתודות ואי משום לפני ה' אינו מוכרח דבכל מקום הוי לפני ה' היכא דליכא מקדש או בדיעבד:\",2,0],[8,356,11,5,\"וידוי זה נאמר בכל לשון וכו'. משנה ר״פ אלו נאמרים (סוטה דף ל״ב:):\",1,0],[8,356,11,5,\"וכל אחד ואחד וכו':\",2,0],[8,356,11,6,\"ומצותו במקדש וכו' ואם התודה בכל מקום יצא. כבר נתבאר:\",1,0],[8,356,11,7,\"אינו מתודה עד שלא ישאר אצלו וכו'. פשוט הוא ומבואר במשנה פ\\\"ה דמע\\\"ש:\",1,0],[8,356,11,7,\"וערב י\\\"ט האחרון היה הביעור. משנה בפרקא בתרא דמע\\\"ש (משנה ו') ובספרינו כתוב ערב י\\\"ט הראשון של פסח של רביעית ושל שביעית היה הביעור וגירסת רבינו אחרון במקום ראשון ויש להוכיח כן מדאמרינן בירושלמי (הלכה ה') ויתודה בי\\\"ט הראשון של פסח כדי שיהא לו מה לאכול ברגל ויתודה בשחרית עד כאן מצוה הוא לאכול. ואם איתא שהביעור היה מעי\\\"ט הראשון הרי לא היה לו מה לאכול ברגל:\",2,0],[8,356,11,7,\"ומ\\\"ש ולמחר. שם במשנה (משנה י') במנחה ביו\\\"ט האחרון היו מתודים:\",3,0],[8,356,11,8,\"כיצד הוא עושה וכו'. משנה ו' שם.\",1,0],[8,356,11,8,\"ומ\\\"ש הרי זה מבערן ומשליך לים או שורף. זהו פי' מה ששנינו שם במשנה מע\\\"ש והביכורים מתבערים בכל מקום. ומה שהשוה נטע רבעי למעשר שני הוא מדאמרינן בפרק שני דקידושין דיליף קדש קדש ממעשר וגם ממה ששנינו בפרק בתרא דמע\\\"ש בערתי הקדש זה מע\\\"ש ונטע רבעי.\",2,0],[8,356,11,8,\"ומה שכתב נשאר אצלו מעשר שני של דמאי אינו חייב לבערו. משנה פרק קמא דדמאי (משנה ב') הדמאי אין לו חומש ואין לו ביעור:\",3,0],[8,356,11,8,\"ומ\\\"ש נשאר אצלו ביכורים הרי הם מתבערים בכ\\\"מ. שם במשנה וכת\\\"ק:\",4,0],[8,356,11,9,\"ומ\\\"ש במה דברים אמורים ששורף ומבער וכו' אבל אם נשאר תבשיל וכו'. שם במשנה וכבית הלל.\",1,0],[8,356,11,9,\"ומ\\\"ש וכן יין ותבלין הרי הם כמבוערים. שם בירושלמי:\",2,0],[8,356,11,10,\"פירות שלא הגיעו לעונת המעשרות וכו'. משנה שם:\",1,0],[8,356,11,11,\"מי שהיו פירותיו רחוקים ממנו וכו'. ג\\\"ז משנה שם:\",1,0],[8,356,11,11,\"ומ\\\"ש אבל אינו יכול להקנות להם המעשר בחליפין וכו'. נראה שלמד כן מעובדא דרבן גמליאל וזקנים ששנינו שם ונתקבלו זה מזה שכר ולמה הוצרכו לכך יותר נקל היה להקנותם בקנין סודר אלא מפני שנראה כמכירה:\",2,0],[8,356,11,12,\"ומניין שאינו יכול להתודות וכו' עד אינו יכול להתודות. משנה שם:\",1,0],[8,356,11,13,\"נשרף טבלו אינו יכול להתודות וכו'. ירושלמי שם:\",1,0],[8,356,11,13,\"ובזמן שהיו נותנין מעשר ראשון לכהנים וכו'. פ' עגלה ערופה (סוטה דף מ״ח):\",2,0],[8,356,11,14,\"מי שאין לו אלא מעשר שני בלבד וכו' עד אינו מתודה. ירושלמי בפ\\\"ב דבכורים:\",1,0],[8,356,11,15,\"לא עברתי ממצותיך שלא הפריש ממין על שאינו מינו וכו' עד סוף הפרק. משנה בסוף מעשר שני (משנה יא יב):\",1,0],[8,356,11,15,\"סליקו להו הלכות מע\\\"ש ונטע רבעי\",2,0],[8,357,1,1,\"עשרים וארבע מתנות ניתנו לכהנים וכו'. בפרק הזרוע (חולין דף קל״ג):\",1,0],[8,357,1,1,\"וכל כהן שאינו מודה בהן וכו'. בפ' הזרוע ובפרק הקומץ רבה (מנחות דף י״ח:) כל כהן שאינו מודה בעבודה אין לו חלק בכהונה ואיני יודע למה שינה רבינו הלשון וכל שכן במקום שאפשר שיבא ממנו שינוי הבנת ענין:\",2,0],[8,357,1,2,\"וכל האוכל מתנה שיש בה קדושה מברך וכו':\",1,0],[8,357,1,3,\"שמנה מתנות מהם אין אוכלים אותם הכהנים וכו'. רבינו חילקם בחילוק זה:\",1,0],[8,357,1,12,\"מנו חכמים מתנות אלו על דרך אחרת וכו'. בסוף פרק הגוזל עצים (ב\\\"ק דף ק\\\"י:) ובירושלמי סוף חלה:\",1,0],[8,357,2,1,\"מצות עשה להביא בכורים למקדש וכו'. משנה בסוף שקלים (דף י\\\"א) ובסיפרי פרשת והיה כי תבא כל זמן שיש לך מזבח יש לך ביכורים וכל זמן שאין לך מזבח אין לך בכורים:\",1,0],[8,357,2,1,\"ומ״ש ובא״י בלבד. פ״ק דכלים (מ״ו) ובפ' ראשית הגז (חולין דף קל״ו):\",2,0],[8,357,2,1,\"ומביאים בכורים של דבריהם מערי סיחון ועוג. משנה בסוף פרק קמא דבכורים (משנה י') אלו מביאים וקורין וכו' מזיתי שמן מעבר הירדן רבי יוסי הגלילי אומר אין מביאים בכורים מעבר הירדן שאינה ארץ זבת חלב ודבש וידוע דהלכה כת\\\"ק. ומשמע לרבינו דלא פליג ת\\\"ק אלא מדאורייתא אבל מדרבנן מודו דמיחייב וכבר כתב מהרי\\\"ק בסי' קנ\\\"ב להוכיח מהיכן משמע ליה הכי:\",3,0],[8,357,2,1,\"ומ\\\"ש ומסוריא שהקונה בסוריא כקונה בירושלים. משנה בסוף חלה (משנה י\\\"א):\",4,0],[8,357,2,1,\"אבל עמון ומואב ובבל וכו'. עמון ומואב ירושלמי בסוף בכורים ובתוספתא פ\\\"ק ומשמע לרבינו דה\\\"ה בבבל:\",5,0],[8,357,2,1,\"ואם הביא ביכורים מחוצה לארץ אינם ביכורים כו':\",6,0],[8,357,2,2,\"אין מביאים ביכורים אלא משבעת המינין וכו'. משנה בפ\\\"ק דבכורים (מ\\\"ג):\",1,0],[8,357,2,2,\"ומ\\\"ש ואם הביא חוץ משבעת המינים לא נתקדשו. ירושלמי שם (הלכה ג'):\",2,0],[8,357,2,3,\"אין מביאים לא מתמרים שבהרים וכו'. גם זה משנה שם:\",1,0],[8,357,2,3,\"ומ\\\"ש ואם הביא שלא מן המובחר כגון תמרים שבהרים וכו'. בפרק כל קרבנות הצבור (מנחות דף פ\\\"ד:) ובירושלמי פ\\\"ק דבכורים פלוגתא בתמרים שבהרים ובפירות שבעמקים ופסק כרבי יוחנן דאמר לא נתקדשו ותניא תו תמן תאנים סורות ומרוקבות וענבים מאובקות ומעושנות אין מביאין ומשמע לרבינו שאם הביא לא נתקדשו דלא עדיפי מתמרים שבהרים ופירות שבעמקים:\",2,0],[8,357,2,4,\"אין מביאים בכורים משקין חוץ מזיתים וענבים וכו'. משנה בסוף תרומות (משנה ג') ומייתי לה בפרק העור והרוטב (חולין דף ק\\\"כ:) ופרק ב דערכין:\",1,0],[8,357,2,4,\"ומ\\\"ש ואם הביא משקין אין מקבלים ממנו. בסוף חלה (משנה י\\\"א) תנן יוסף הכהן הביא ביכורי יין ושמן ולא קיבלו ממנו ומוקי לה בירושלמי (הלכה ה') כשלא בצרן מתחלה לכך וההיא דסוף תרומות בשבצרן מתחלה לכך. ואיני יודע למה לא חילק רבינו בכך. ובפירוש המשנה כתב רבינו ומה שאמרו שהביכורים מביאים אותם יין ושמן הוא לדעת רבי יהודה כי הוא לומד הביכורים מן התרומה וכן אמרו מני ר' יהודה דאמר דון מינה ואוקי באתרה וגמר לה ביכורים מתרומה ואין הלכה כרבי יהודה עכ\\\"ל. ודברי רבינו נראה כאן שהוא פוסק כההיא דסוף תרומות ולא כההיא דיוסף הכהן. ומכל מקום יליף מינה למשקין דשאר פירות שאם הביא אין מקבלים ממנו:\",2,0],[8,357,2,5,\"הקרובים לירושלים וכו'. משנה פרק ג' דבכורים (משנה ג'):\",1,0],[8,357,2,6,\"אין מביאים בכורים קודם לעצרת וכו'. משנה פירקא קמא דביכורים (משנה ג') וסוף חלה (משנה י'):\",1,0],[8,357,2,6,\"ומ\\\"ש אלא יניחם שם עד שתבא עצרת וכו'. תוספתא בריש בכורים:\",2,0],[8,357,2,6,\"וכן אין מביאין ביכורים אחר חנוכה וכו'. כן משמע במשנה פירקא קמא דביכורים דקתני מן החג ועד החנוכה מביא ואינו קורא משמע הא אחר חנוכה אינו מביא:\",3,0],[8,357,2,6,\"וכתב הראב\\\"ד ואיך יתכן זה וכו'. ויש לומר דכיון דמחנוכה ואילך כלים לחיה מן השדה ולא קרינן בהו מארצך כדדריש בסיפרי אינם נחשבים משנה שעברה:\",4,0],[8,357,2,7,\"אין מביאין בכורים לא מן החדש על הישן וכו'. ירושלמי פירקא קמא דבכורים (הלכה ו'):\",1,0],[8,357,2,7,\"אחד הנטוע ואחד העולה מאליו וכו'. ריש פרק כל קרבנות הצבור (דף פ\\\"ד):\",2,0],[8,357,2,8,\"ופירות של שותפין חייבין וכו'. כך כתוב בספרי רבינו המוגהים והוא בפרק ראשית הגז (חולין דף קל״ו):\",1,0],[8,357,2,9,\"הגדל בעציץ וכו'. פ' כל קרבנות הצבור:\",1,0],[8,357,2,9,\"ועל מ\\\"ש אבל מביא הוא מן הגדל בגנה ובחורבה. כתב הראב\\\"ד הוא פסק כר\\\"ל וכו'. וי\\\"ל לדעת רבינו דהתם הכי איתא תנן התם אין מביאים ביכורים חוץ משבעת המינים ולא מתמרים שבהרים ולא מפירות שבעמקים ואמרינן עלה ר\\\"י אמר אם הביא לא קידש ר\\\"ל אמר אם הביא קידש וכו' תני חדא שבגג ושבחורבה שבעציץ ושבספינה מביא וקורא ותניא אידך מביא ואינו קורא בשלמא לר\\\"ל גג אגג לא קשיא הא בגג דמערה הא בגג דבית חורבה אחורבה לא קשיא הא בחורבה עבודה הא בחורבה שאינה עבודה כו' אלא לר\\\"י קשיא תנאי היא דתניא שבגג ושבחורבה מביא וקורא שבעציץ ושבספינה אינו מביא כל עיקר ופירש\\\"י תנאי היא דאיכא תנא דאמר שבעציץ ושבספינה אינו מביא וה\\\"ה לתמרים שבהרים ושבעמקים עכ\\\"ל. וצ\\\"ל על כרחנו דבשגג ושבחורבה עדיפי מתמרים שבהרים ושבעמקים דבהני קתני בברייתא דמסייעא לר\\\"י מביא וקורא ובהנך קאמר ר\\\"י דאם הביא לא קידש והשתא אתי שפיר פסק רבינו כר\\\"י. והתימה על הראב\\\"ד שגזר אומר שרבינו פסק כר\\\"ל והיאך אפשר להעלות כן על הדעת שהרי ר\\\"ל מפליג בגג בין של בית לשל מערה ובחורבה בין עבודה לשאינה עבודה ובעציץ בין נקוב לשאינו נקוב ובספינה בין של עץ לשל חרס ורבינו לא מפליג כלל. וי\\\"ל דהראב\\\"ד לטעמיה דסבר לר\\\"י אינו מביא מן הגג ומהחורבה כלל דלפי זה מי שיאמר שיביא אינו אלא כר\\\"ל וק\\\"ל למה לא פסק כר\\\"י ותו דאפילו כר\\\"ל לא אתיא דאיהו מפליג בין גג לגג ובין חורבה לחורבה ורבינו לא מפליג ותו דמפליג בין עציץ וספינה לגג וחורבה והיינו לא כר\\\"ל ולא כר\\\"י. זהו ביאור דברי הראב\\\"ד וכבר יישבתי דעת רבינו:\",2,0],[8,357,2,10,\"הנוטע אילן בתוך שדהו והבריכו וכו' עד מאדמתך. פירקא קמא דביכורים (משנה א'):\",1,0],[8,357,2,11,\"נתן לו חבירו רשות להבריך וכו'. אפילו לשעה וכו'. שם בירושלמי וכר' יונה ורבי יוחנן:\",1,0],[8,357,2,11,\"ואם היה האילן סמוך למצר חבירו או נוטה לשדה חבירו וכו'. בס״פ לא יחפור (בבא בתרא דף כ״ז):\",2,0],[8,357,2,12,\"האריסין והחכירין ובעלי זרוע וכו'. משנה פ\\\"ק דביכורים (משנה ב'):\",1,0],[8,357,2,12,\"ומה שכתב ואפילו נתייאשו הבעלים. בירושלמי:\",2,0],[8,357,2,13,\"הקונה אילן בתוך שדה חבירו אינו וכו'. משנה ו' בפ\\\"ק דבכורים הקונה שני אילנות בתוך של חבירו מביא ואינו קורא ר\\\"מ אומר מביא וקורא וכו' ובמי\\\"א הקונה ג' אילנות בתוך (שדה) של חבירו מביא וקורא ר\\\"מ אומר אפילו שנים וידוע דהלכה כת\\\"ק דאמר דוקא ג' אילנות מביא וקורא.\",1,0],[8,357,2,13,\"ומ״ש ואע״פ שאין לו אלא אילנות בלבד אינו סותר מ״ש תחלה יש לו קרקע די״ל דה״ק אע״פ שקניית השלשה אילנות היה בענין שלא קנה קרקע על הדרכים שנתבארו בפרק כ״ד מהלכות מכירה כיון שקנה ג' הואיל ובקניית שלשה אפשר להמצא בדרך שקנה קרקע קנה אע״פ שעכשיו קנאו בדרך שאין לו קרקע חשיב כקנה קרקע לענין בכורים. ואפשר דיליף לה רבינו מדסתם תנא ותני הקונה ג' אילנות בתוך של חבירו מביא וקורא דמשמע דבכל גווני שקנה שלשה מביא וקורא אע״פ שאין זה הכרע דהא בפרק הספינה (בבא בתרא דף פ״ב) קתני סתמא קנה ג' קנה קרקע וצריך לאוקומי בהנך גווני דמוקי לה בגמרא. והר״י קורקוס ז״ל כתב וז״ל נ״ל דכוונת רבינו דודאי בקונה סתם מיירי שכן כתב בתחלת לשונו שלשה יש לו\",2,0],[8,357,2,13,\"קרקע ומ\\\"ש אע\\\"פ שאין לו אלא אילנות ה\\\"פ ואע\\\"פ שזה לא קנה בפירוש אלא אילנות ואין עיקר דעתו אלא על האילנות והקרקע לא הזכירו ולא פירשו בשעת המקח וא\\\"כ הרי הוא כמי שאין לו קרקע ואיך יאמר פרי האדמה אשר נתת לי והוא לא קנה אותה שלא החשיב והזכיר אלא האילנות והרי הוא בעיניו כמי שאין לו אלא אילנות אפ\\\"ה כיון דסתמא יש לו הרי הוא כאילו קנה קרקע עכ\\\"ל.\",3,0],[8,357,2,13,\"ומ\\\"ש הקונה אילן אינו מביא לפי שאין לו קרקע נראה שטעמו מדתני ת\\\"ק דהקונה שני אילנות מביא ואינו קורא משמע שאם לא קנה אלא אילן אחד אינו מביא דאל\\\"כ לישמעינן באילן אחד דמביא וכל שכן בשנים אע\\\"פ שיש לדחות דאינו קורא אתא לאשמועינן דאפילו בשנים אינו קורא כל שכן באחד י\\\"ל דהל\\\"ל הקונה פחות מג' אילנות ואף גם זה יש לדחות ולומר דמשום דלר\\\"מ בשנים מביא וקורא נקט בת\\\"ק שנים אבל אה\\\"נ דלת\\\"ק דין אילן אחד שוה לשנים וי\\\"ל דממשנה יתירה קא דייק דכיון דהוה בעי למיתני הקונה שלשה אילנות מביא וקורא ר\\\"מ אומר אפילו שנים וממילא משמע הא שנים מביא ואינו קורא למה ליה למיתני הקונה שני אילנות מביא ואינו קורא אלא ודאי היינו ללמדנו דבשנים דוקא הוא דמביא ואינו קורא הא באחד בלבד אינו מביא וקצת סמך יש לזה מדקאמר בפרק הספינה מ\\\"ט דר\\\"מ באילן אחד ומ\\\"ט דרבנן בשני אילנות ולא קאמר ומ\\\"ט דרבנן בין באילן א' בין בשני אילנות אע\\\"פ שאין טעם לחלק בין אילן אחד לשני אילנות כיון שאין לו קרקע בין בזה ובין בזה אפשר שגם זה בכלל מה ששאל מ\\\"ט דרבנן בשני אילנות. אח\\\"כ מצאתי בירושלמי דביכורים פ\\\"ק (הלכה ו') אחד אינו מביא כל עיקר שנים מביא ואינו קורא וזה מבואר כדברי [רבינו]. ומ\\\"מ רבינו שנתן טעם לאילן אחד מפני שאין לו קרקע יקשה מ\\\"ש שני אילנות וי\\\"ל דה\\\"ק מפני שאין לו קרקע בודאי מה שאין כן בשני אילנות דמספקא לן כדאמר בפ' הספינה וכתבו רבינו בפ\\\"ד. וא\\\"ת למה השמיט רבינו דין קונה שני אילנות שמביא ואינו קורא וי\\\"ל דמדיוקא דרישא וסיפא איכא למשמע מינה דמדקתני באילן אחד אינו מביא משמע הא שנים מביא ומדקתני בשלשה הרי הוא כמי שקנה קרקע כלומר וקורא משמע הא שנים אינו קורא ולקמן בפ\\\"ד כתבו בפירוש כמו שהוא שנוי במשנה מביא ואינו קורא כדי לכוללו עם השנויים באותו פרק שמביא ואינו קורא. ועל מש\\\"כ רבינו ג' יש לו קרקע ואע\\\"פ שאין לו אלא אילנות בלבד הרי הוא כמי שקנה קרקע:\",4,0],[8,357,2,13,\"כתב הראב\\\"ד לא כי אלא מפני שבסתם וכו' ואני כבר כתבתי טעם לדברי רבינו:\",5,0],[8,357,2,13,\"קנה אילן א' וקרקעו הרי זה מביא. משנה פ\\\"ק דביכורים (מי\\\"א) קנה אילן וקרקעו מביא וקורא ויש לתמוה למה השמיט רבינו וקורא ונראה דט\\\"ס הוא אי נמי שמאחר שמפני שקנה קרקע מביא פשיטא שקורא:\",6,0],[8,357,2,14,\"הלוקח פירות תלושין ולקח הקרקע וכו' עד שהרי יש לו קרקע ופירותיה. ירושלמי שם:\",1,0],[8,357,2,14,\"מכר לו פירות חוץ מן הקרקע אפילו מחוברים מוכר אינו מביא שהרי אין לו פירות ולוקח אינו מביא שהרי אין לו קרקע. כך היא הגירסא בספרי רבינו המוגהי' והחלוקה הראשונה היא בירושלמי פ״ק (הלכה ו') והחלוקה השנית דבר פשוט הוא ובפרק הספינה (בבא בתרא דף פ״א) אמרו דלר״מ לוקח פירות מן השוק (בלא קרקע) מביא וקורא והקשה מהקונה אילן אחד וכו' וסלקא בתיובתא:\",2,0],[8,357,2,14,\"ומ\\\"ש חזר המוכר ולקח הפירות וכו'. ירושלמי פרק קמא:\",3,0],[8,357,2,15,\"המוכר שדהו לעכו\\\"ם וכו'. משנה בסוף פרק השולח (דף מ\\\"ז) ולרש\\\"י גירסא אחרת ופשטא דגמרא דקאמר שתי תקנות הוו וכו' משמע כדפירש\\\"י וצריך ליישבו לדעת רבינו ועיין במ\\\"ש בפי' המשנה:\",1,0],[8,357,2,15,\"כתב הראב\\\"ד המוכר שדהו לעכו\\\"ם וכו' א\\\"א אע\\\"פ שבכרו ברשות העכו\\\"ם עכ\\\"ל. וכתב הר\\\"י קורקוס ז\\\"ל ונראה דרבינו לטעמיה אזיל שהוא מפרש מה שכתב אין קנין לעכו\\\"ם בא\\\"י להפקיע היינו אם חזר ישראל וקנה השדה כמה שכתב בפרק א' מהלכות תרומות ולכך כתב כאן וחזר ולקחה ממנו שסובר רבינו דברייתא בהכי מיירי ובשבכרו ברשות העכו\\\"ם אפשר דדמי לפירות שנתמרחו ברשות העכו\\\"ם שאין ישראל הקונה חייב עכ\\\"ל:\",2,0],[8,357,2,16,\"אשרה שבטלה וכו':\",1,0],[8,357,2,17,\"הבכורים אין להם שיעור וכו'. משנה בריש פאה.\",1,0],[8,357,2,17,\"ומה שכתב אבל מדבריהם צריך להפריש אחד מששים. ירושלמי רפ״ג דביכורים והכי משמע בגמרא דידן פרק ראשית הגז (חולין דף קל״ז).\",2,0],[8,357,2,17,\"ומ\\\"ש והרוצה לעשות כל שדהו בכורים עושהו. משנה פ\\\"ב דבכורים (משנה ד'):\",3,0],[8,357,2,18,\"הפריש ביכוריו וחזר והוסיף עליהן או עטרן וכו' עד אינה כבכורים. משנה שם פ\\\"ג (משנה י\\\"א).\",1,0],[8,357,2,18,\"ומ\\\"ש ואע\\\"פ שאינה ביכורים אינה נאכלת אלא בטהרה: ומ\\\"ש ואין מעטרין את הביכורים וכו'. שם (משנה ט') וכר\\\"ע מחבירו:\",2,0],[8,357,2,19,\"כיצד מפרישין וכו' עד הרי אלו ביכורים. משנה בפ\\\"ג (מ\\\"א):\",1,0],[8,357,2,19,\"ומה שכתב ואע\\\"פ שעדיין לא בשלו כל צרכן וכו'. שם בירושלמי:\",2,0],[8,357,2,19,\"לא הפרישם במחובר וכו'. ומ\\\"ש ואם נטמאו הפירות כולם וכו' נראה דיליף לה מדתנן בפ\\\"ב דביכורים (משנה ה') גבי תר\\\"מ שוה לביכורים ניטלת מן הטהור על הטמא כביכורים משמע אם הכל טמא לא:\",3,0],[8,357,2,19,\"ומ״ש וכן יראה לי שהביכורים [שנטמאו] אינו מסיק בהם התנור וכו'. יש לתמוה למה תלה הדבר ביראה לי שזה פשוט בפרק הערל (יבמות דף ע״ג) וגם בירושלמי בפ״ב דבכורים (הלכה א') ואפשר שמה שכתב יראה לי אינו לענין הדין אלא לענין הטעם שנתן מפני שהם כקדשי מקדש דאע״ג דהתם מייתי לה מלא ביערתי ממנו בטמא ההוא במעשר הוא דכתיב והגמ' קיצר במובן:\",4,0],[8,357,2,20,\"המפריש בכוריו ונמקו וכו'. משנ' פ\\\"ק דביכורים (מ\\\"ח):\",1,0],[8,357,2,21,\"המפריש בכוריו להעלותן בידו וכו'. ירוש' פ\\\"ק דבכורים הלכה ו':\",1,0],[8,357,3,1,\"הבכורים נותנים אותן לאנשי משמר וכו'. משנה בסוף ביכורים (משנה י\\\"ב):\",1,0],[8,357,3,1,\"וכבר ביארנו שהם קרויים תרומה וכו'. משנה ריש פרק ב' דביכורים (משנה א') התרומה והביכורים חייבים עליהם מיתה וחומש ומייתי לה בפרק הערל (יבמות דף ע״ג):\",2,0],[8,357,3,1,\"ומה שכתב והוא שיאכלם מאחר שנכנסו לחומת ירושלים. בפרק אלו הן הלוקין (מכות דף י״ח י״ט) בכורים מאימתי חייבים עליהם משיראו פני הבית וכתב רבינו בספר המצות שלו בסימן קמ״א דמשיראה פני הבית היינו משהגיע לפנים מחומת ירושלים וכן נראה מדבריו עוד שם בסימן קל״ט והטעם לומר דמשיכנסו לפנים מהחומה אז רואים פני הבתים שבעיר ודייקא דנקט משיראו ולא נקט עד שיראו וכן משמע מהא דר״ש שאכתוב דיליף בכורים ממעשר במכ״ש ואם איתא שאינם שוים איכא למיפרך:\",3,0],[8,357,3,2,\"היו מקצתן בפנים ומקצתן בחוץ וכו'. פרק אלו הן הלוקין (שם):\",1,0],[8,357,3,3,\"כהן שאכל בכורים חוץ לירושלים וכו'. שם עלה י\\\"ז ותרומת ידך אלו הבכורים אמר ר\\\"ש מה בא זה ללמדנו אם לאוכלן חוץ לחומה ק\\\"ו ממעשר הקל ומה מעשר הקל האוכלו חוץ לחומה לוקה בכורים לא כ\\\"ש הא לא בא הכתוב אלא לאוכל בכורים עד שלא קרא עליהם ולפי שאין עונשין מן הדין כתב רבינו שלוקה מדכתיב לא תוכל לאכול בשעריך:\",1,0],[8,357,3,3,\"וכן אם אכלם הכהן וכו'. שם אהא דתנן גבי אלו הן הלוקין האוכל בכורים עד שלא קרא עליהם אמר רבה בר בר חנה אמר רבי יוחנן זו דברי ר' עקיבא סתימתאה אבל חכמים אומרים בכורים הנחה מעכבת בהם קריאה אינה מעכבת בהם ומשמע התם דהלכה כחכמים:\",2,0],[8,357,3,4,\"ומ\\\"ש בכורים שיצאו חוץ למחיצתן וחזרו מותרים באכילה. בריש פרק בהמה המקשה חולין (דף ס\\\"ד):\",1,0],[8,357,3,6,\"אכילת בכורים וכו' שהן אסורים לאונן וטעונין הבאת מקום. משנה בפרק שני דביכורים (משנה ב') ומייתי לה בפרק הערל (יבמות דף פ״ג:):\",1,0],[8,357,3,6,\"וכהן טהור שאכל ביכורים טמאים לוקה וכו': ומניין שהביכורים אסורים לאונן וכו'. בפרק כל שעה (פסחים דף ל״ו):\",2,0],[8,357,3,6,\"ומה שכתב מכין אותו מכת מרדות. כלומר אבל לא מלקות מפני שהוא לאו הבא מכלל עשה:\",3,0],[8,357,3,7,\"הבכורים טעונים כלי שני וכו'. נראה דתיבת שני ט\\\"ס היא וצריך למוחקה ואם נפשך לקיימה היינו לומר שלא יביאם בכלי שהביאם מן השדה לבית אלא ישימם בכלי אחר ויוליכם ויליף מדכתיב ושמת בטנא והלכת והראשון נראה יותר וכ\\\"נ מדברי רבינו בסוף הפרק גבי שהביכורים טעונים ז' דברים הבאת מקום וכלי ולא כתב כלי שני.\",1,0],[8,357,3,7,\"ומ\\\"ש ומצוה מן המובחר להביא כל מין ומין בכלי בפני עצמו תוספתא פ\\\"ב דביכורים מצוה להביאה בז' כלים ואם הביאם בכלי אחד יצא פירוש בז' כלים כשהם ז' מינים.\",2,0],[8,357,3,7,\"ומה שכתב ולא יביאם וכו' עד אשכולות של ענבים מבחוץ. תוספתא בסוף ביכורים:\",3,0],[8,357,3,8,\"הביאם בכלי מתכות עד והסלים לכהנים. משנה פ\\\"ג דביכורים (משנה ח'):\",1,0],[8,357,3,8,\"ומ\\\"ש ואם נטמאו הביכורים אין הסלים לכהנים. יש לתמוה דבירושלמי פ\\\"ק דביכורים (הלכה ה') אמרינן איפכא ויליף לה מדכתיב ולקח הכהן הטנא מידך כלומר שאינו לוקח הטנא וכך היא גירסת ר\\\"ש והרא\\\"ש אבל רבינו גורס אין הסלים לכהנים ולפי זה יליף מדכתיב הטנא משמע הטנא הנזכר עם הביכורים כשהם ראויים:\",2,0],[8,357,3,9,\"כשהיו מביאים הביכורים וכו'. משנה בפ\\\"ג דביכורים (משנה ה') הגוזלות שע\\\"ג הסלים היו עולות ומה שבידם ניתנים לכהנים ומפרש רבינו דהכי קאמר הגוזלות שבידם ניתנים לכהנים:\",1,0],[8,357,3,9,\"והראב\\\"ד כתב אומר אני מה שבידם וכו' כלומר שהוא מפרש דמה שבידם היינו הביכורים עצמם ופשטא דלישנא משמע כדברי רבינו. וכתב רבינו וכן היו תולים מצד הסלים כר' יוסי דאמר הכי בתוספ' וסבר רבינו דלאו לאיפלוגי אתא אלא לפרושי דע\\\"ג הסלים דתנן לא על גביהם ממש היו כדי שלא יטנפו את הפירות:\",2,0],[8,357,3,10,\"מצות עשה להתודות במקדש וכו'. מבואר במקרא ובמשנה פ\\\"ג דביכורים.\",1,0],[8,357,3,10,\"ומ״ש ואין קורין אותה אלא בלשון הקדש. משנה ר״פ אלו נאמרים (סוטה דף ל״ב).\",2,0],[8,357,3,10,\"ומ\\\"ש שנאמר וענית ואמרת וכו'. יש קיצור בלשון רבינו דהתם במתניתין מייתי לה מדכתיב הכא וענית ולהלן הוא אומר וענו הלוים ואמרו מה להלן בלשון הקדש אף כאן בלשון הקדש:\",3,0],[8,357,3,11,\"בראשונה כל מי שהיה יודע לקרות וכו'. משנה פרק ג' דביכורים (מ\\\"ז):\",1,0],[8,357,3,12,\"המביא בכורים יש לו רשות וכו'. תוספתא פרק ב' דביכורים.\",1,0],[8,357,3,12,\"ומה שכתב הגיע להר הבית וכו' עד מניחו בצד המזבח. משנה ו' פרק ג'.\",2,0],[8,357,3,12,\"ומה שכתב בקרן דרומית מערבית בדרומה של קרן. שם בירושלמי:\",3,0],[8,357,3,12,\"ומניין שהם טעונים תנופה וכו'. בפרק כל המנחות (מנחות דף ס״א) ויליף מדכתיב הכא מידיך וכתיב התם ידיו תביאנה.\",4,0],[8,357,3,12,\"ומה שכתב וכיון שטעונים תנופה כך טעונים קרבן שלמים וכו'. במשנה פרק ב' (משנה ד') טעונים קרבן ושיר ותנופה ולינה ובירושלמי (הלכה ג') טעונים קרבן נאמר כאן שמחה ונאמר להלן שמחה מה שמחה שנאמר להלן שלמים אף כאן שלמים ותיבת וכיון שכתובה בספרי רבינו אינו נוחה לי שאין הקרבן תלוי בתנופה.\",5,0],[8,357,3,12,\"ומה שכתב ואין הקרבן מעכב טעמו מדאמרינן שם בירושלמי גבי טעונים לינה דכתיב ופנית בבקר הא כל הפונות שאתה פונה לא יהיו אלא בבקר אמר רבי יונה הדא דתימא כשאין עמהם קרבן אבל יש עמהם קרבן בלא כך טעון לינה מחמת הקרבן נראה בהדיא שאין הקרבן מעכב. ומה שכתב רבינו לקמן בסמוך הביא בכוריו למקדש וקרא והקריב שלמים לא יצא באותו היום לאו למימרא דתרתי בעינן אלא רבינו סידרא דמילתא לכתחלה נקט ואם לא הביא קרבן טעון לינה משום ביכורים כמו שנתבאר:\",6,0],[8,357,3,13,\"ואימתי קורין בשיר עליהם וכו'. משנה פ\\\"ג דביכורים (משנה ד'):\",1,0],[8,357,4,2,\"כל המביא ביכורים וכו' ומה שכתב ואלו מביאים ולא קורין וכו'. משנה פרק קמא דביכורים:\",1,0],[8,357,4,3,\"ומ\\\"ש הגר מביא וקורא וכו'. שם בירוש' איפסיקא הלכתא כרבי יהודה דאמר הכי.\",1,0],[8,357,4,3,\"ומה שכתב ולאברהם היתה השבועה וכו'. כלומר אע\\\"פ שאברהם אב לכל העולם לא נטלו הגרים חלק בארץ מפני שבתחילה קודם שנאמר לו כי אב המון גוים נתתיך היתה השבועה וכו' נמצא שלא זכו בה אלא בניו ממש:\",2,0],[8,357,4,3,\"וכן כהנים ולוים וכו'. משנה בסוף מעשר שני (משנה י\\\"ד) וכרבי יוסי לענין וידוי מעשר ומינה ילפינן לבכורים:\",3,0],[8,357,4,4,\"הקונה שני אילנות. משנה דבכורים פ\\\"ק (מ\\\"ו):\",1,0],[8,357,4,4,\"ומה שכתב לפי שהדבר ספק וכו' עד מעכבת בו. בפרק הספינה (בבא בתרא דף פ״א):\",2,0],[8,357,4,5,\"הפריש ביכוריו וכו עד מביא וקורא. משנה פרק קמא דבכורים (מ\\\"ז) וכת\\\"ק:\",1,0],[8,357,4,6,\"המוכר שדהו לפירות וכו'. בסוף פרק השולח (גיטין דף מ״ז.) וכר״ל דאיפסקא הלכתא כוותיה:\",1,0],[8,357,4,6,\"ומה שכתב אבל מביא אדם מנכסי אשתו ביכורים וקורא וכו'. שם:\",2,0],[8,357,4,6,\"ומה שכתב אע\\\"פ שמתה אשתו וכו'. שם:\",3,0],[8,357,4,7,\"המוכר שדהו וכו' עד אינו כקנין הגוף. גם זה בסוף פרק השולח (גיטין דף מ״ח) ופירש רבינו בה דלא כפירש״י:\",1,0],[8,357,4,8,\"הפריש ביכורים וכו'. ירושלמי פ\\\"ק דביכורים ובנוסחא דידן כשהיה אביו חולה או מסוכן ורבינו גריס ומסוכן וכן מוכרח לגרוס שם:\",1,0],[8,357,4,8,\"הפריש ביכוריו ושלחן ביד אחר וכו'. בס״פ השולח (גיטין דף מ״ז):\",2,0],[8,357,4,9,\"הפריש ביכוריו ואבדו וכו' עד ולא שתים. משנה פ\\\"ק דביכורים (משנה ח'):\",1,0],[8,357,4,10,\"הביא בכוריו ונטמאו וכו'. כתב הראב\\\"ד הביא בכוריו ונטמאו בעזרה וכו'. א\\\"א יניחום שם עד שירקבו או עד שיתמסמסו עכ\\\"ל. ורבינו לישנא דמתני' נקט דקתני נופץ ופירש רבינו נוער ור\\\"ש פירש מפזרן והראב\\\"ד בא לומר אחר שמריקם שם מה יעשה בהם יניחם עד שירקבו או עד שיתמסמסו:\",1,0],[8,357,4,12,\"הפריש בכוריו ויבש המעיין וכו'. שם וכת\\\"ק:\",1,0],[8,357,4,13,\"המביא ביכורים כו'. שם מן החג ועד חנוכה מביא ואינו קורא ובפרק כל שעה (פסחים דף ל״ו) יהיב טעמא לפי שאינו זמן שמחה.\",1,0],[8,357,4,13,\"ומ״ש רבינו אע״פ שהפרישם קודם החג וכו' יש לתמוה דהא בפרק אלו הן הלוקין אמר רבי אלעזר אמר רבי הושעיא הפריש ביכורים קודם לחג ועבר עליהם החג ירקבו ויהיב טעמא בגמרא משום דכל שאינו ראוי לבילה בילה מעכבת בו וצ״ל שדחאה רבינו לזו מהלכה מקמי ההיא דפרק השולח (גיטין דף מ״ז:) דאמר ר״י בר חנינא בצרן ושגרן ביד שליח ומת שליח בדרך מביא ואינו קורא שנאמר ולקחת והבאת עד שתהיה לקיחה והבאה כאחד ואע״ג דבירושלמי מוקי לה בשליקטן לשלחן ע״י שליח אבל ליקטן להביאן הוא לא ישלחם ביד אחר שכל הביכורים שנראו להתיר בקריאה אינם נתרים אלא בקריאה מאחר דגמרא דידן מייתי להא דר״י בר חנינא בפרק הספינה (בבא בתרא דף פ״א) ובפרק השולח סתמא ואי הוה סבר גמרא דידן כירושלמי לא הוה שתיק מלפלוגי בהכי וכגמרא דידן נקטינן ועוד דמתניתין דהפריש ביכוריו ואח״כ מכר שדהו ומתניתין דיבש המעיין ונקצץ האילן דמיתנו סתמא אתו כר״י בר חנינא ואע״ג דבירושלמי משני להו שינויא דחיקא ולא סמכינן עליה ולפי זה מ״ש רבינו לעיל בפרק זה גבי הקונה שני אילנות שכל שאינו ראוי לקריאה מפני הספק הקריאה מעכבת בו התם שאני דמחמת ספק הוא:\",2,0],[8,357,4,14,\"הביכורים והתרומות וכו' הם נכסי כהן וכו'. לגבי בכורים משנה פ\\\"ב ופ\\\"ג דביכורים (משנה י\\\"ב):\",1,0],[8,357,4,14,\"והתרומות וחלה וקרן וחומש ומתנות בהמה. ברייתא פרק הזרוע עלה קל\\\"א:\",2,0],[8,357,4,15,\"ואף ע\\\"פ שהביכורים עולים באחד ומאה וכו'. משנה ברפ\\\"ב דביכורים (מ\\\"א):\",1,0],[8,357,4,15,\"ומה שכתב אם נתערבו בחולין בירושלים אסורים בכל שהן במינה וכו'. גם זה שם במשנה (משנה ב') גבי יש במעשר והביכורים מה שאין כן בתרומה ודקדק לכתוב במינם משום דאילו שלא במינם אפילו דבר שיש לו מתירין בטל כמו שכתב רבינו בפ\\\"ק מהלכות מ\\\"א.\",2,0],[8,357,4,15,\"ומה שכתב אפילו זרע הבכורים וכו'. שם במשנה הנזכרת.\",3,0],[8,357,4,15,\"ומ\\\"ש אבל הזורע בכורים קודם שיכנסו לירושלים וכו'. משנה פרק ט' דתרומות (משנה ד') הבכורים גידוליהם חולין ובירושלמי רמי תרי משניות הללו אהדדי ומסיק הן דתימר גידוליהן אסורים איסור מחיצה והן דתימר גידוליהן מותרים היתר זרות וזה מבואר כדברי רבינו:\",4,0],[8,357,4,17,\"כיצד מעלין את הביכורים וכו'. משנה פרק ג' דביכורים (משנה ב'):\",1,0],[8,357,4,17,\"ומ\\\"ש מפני אהל הטומאה. וכן מה\",2,0],[8,357,4,17,\"שכתב להודיע שהביכורים משבעת המינים. וכן מה\",3,0],[8,357,4,17,\"שכתב והם הולכים בכל הדרך וקורין שמחתי באומרים לי בית יי' נלך. וכן מה\",4,0],[8,357,4,17,\"שכתב אם באו אנשים הרבה וכו'. וכן\",5,0],[8,357,4,17,\"מ\\\"ש ומשיכנסו כולם בשערי ירושלים יתחילו לקרות עומדות היו רגלינו וכו'. וכן מה\",6,0],[8,357,4,17,\"שכתב ואומרים הללויה הללו אל בקדשו וכו'. הכל שם בירושלמי:\",7,0],[8,357,4,17,\"ומה שכתב ולא היו מהלכים ביום אלא שתי ידות בלבד. בתוספתא פרק ב' דביכורים לא היו מהלכים כל היום כולו אלא שתי ידות ביום.\",8,0],[8,357,4,17,\"ומ\\\"ש היה להם לח ויבש וכו'. ירושלמי שם צמוקים היה מעטרן בענבים:\",9,0],[8,357,5,1,\"מצות עשה להפריש תרומה מן העיסה וכו' וראשית זו אין לה שיעור מן התורה וכו'. בספרי פרשת שלח:\",1,0],[8,357,5,1,\"והעושה כל עיסתו חלה וכו'. משנה ספ\\\"ק דחלה (מ\\\"ט):\",2,0],[8,357,5,2,\"ומדברי סופרים שמפרישין אחד מכ\\\"ד וכו' עד כדי שלא יהא חוטא נשכר. משנה פ\\\"ב דחלה (משנה ז'):\",1,0],[8,357,5,4,\"וחלה טמאה לכהן וכו'. פשוט הוא דתרומה קרייה רחמנא:\",1,0],[8,357,5,5,\"אין חייבין בחלה מן התורה וכו' עד אינה אלא מדבריהם. בפ״ב דכתובות (דף כ״ה) ובפרק יוצא דופן (נדה דף מ״ז):\",1,0],[8,357,5,6,\"פירות חוצה לארץ וכו'. משנה ריש פ\\\"ב דחלה (משנה א') וכרבי עקיבא:\",1,0],[8,357,5,6,\"וכתב הראב\\\"ד פירות הארץ שיצאו ח\\\"ל פטורים א\\\"א פירוש ד\\\"ת אבל חייבים מדרבנן בשתי חלות עכ\\\"ל. ולא היה צריך לכתוב דהרי רבינו כתבו בסמוך:\",2,0],[8,357,5,7,\"מפרישין חלה בח״ל וכו'. בפרק עד כמה (בכורות דף כ״ז):\",1,0],[8,357,5,7,\"ואין מביאין חלות ח\\\"ל וכו'. משנה בסוף חלה (משנה י') נתאי איש תקוע הביא חלות מביתר ולא קבלו ממנו אנשי אלכסנדריא הביאו חלותיהם מאלכסנדריא ולא קבלו מהם.\",2,0],[8,357,5,7,\"ומ\\\"ש ואם הביא מניחה עד ערב פסח וכו'. שם בירושלמי:\",3,0],[8,357,5,8,\"שלשה דינים לחלה בשלש ארצות וכו'. משנה ח' פרק רביעי דחלה.\",1,0],[8,357,5,8,\"ומה שכתב ומפני מה מפרישין בה שתי חלות וכו'. שם בירושלמי:\",2,0],[8,357,5,8,\"כתב הראב\\\"ד ומותרת לזבים ולזבות א\\\"א נ\\\"א אסורה לזבים ולזבות וכו'. לטעמיה אזיל שכתב בפ\\\"ז מהלכות תרומות שזבים וזבות אפי' טבלו אסורים לאכול בתרומה אפילו של ח\\\"ל וכבר כתבתי שם שהפוסקים הסכימו שכשאמרו בתרומת ח\\\"ל שאסורה לזבים לא אמרו אלא בשלא טבלו אבל אם טבלו מותרים הם וא\\\"כ מה ששנינו בסוף חלה (משנה ח') גבי חלת ח\\\"ל שאסורה לזבים היינו דוקא בשלא טבלו אבל אם טבלו מותרים הם:\",3,0],[8,357,5,8,\"ומ\\\"ש ואצ\\\"ל לשאר טמאים כלומר הנך טמאים שאין טומאה יוצאה מגופם דקילי כדאיתא בפרק עד כמה וכתבה רבינו בפרק שביעי מהלכות תרומות:\",4,0],[8,357,5,9,\"בזמן הזה שאין שם עיסה טהורה וכו'. כ\\\"כ בה\\\"ג וסמ\\\"ג ורש\\\"י:\",1,0],[8,357,5,10,\"חלת ח\\\"ל וכו'. נתבאר בפ\\\"ז מהלכות תרומות:\",1,0],[8,357,5,10,\"כתב הראב\\\"ד ואינו צריך להפריש שניה א\\\"א כבר כתבנו מה שנראה לנו מהגמרא ומהלכות הרב עכ\\\"ל הוא הדבר אשר דברתי שכתב בפ\\\"ז מהלכות תרומות שתרומת ח\\\"ל אסורה לזבים ולזבות אפי' טבלו:\",2,0],[8,357,5,11,\"ומ\\\"ש וכן אם היה שם כ\\\"ג שטבל וכו'. משנה פ\\\"ד דחלה (משנה ח') גבי חלת ח\\\"ל טבול יום אוכלה.\",1,0],[8,357,5,11,\"ומ״ש וא״צ להפריש חלה שניה בח״ל נראה שיש ללמוד קצת כן מדתנן בפ״ד דחלה ר״ג אומר שתי חלות בסוריא ר״א אומר חלה אחת משמע דאפי' לר״ג דוקא בסוריא הוא דהוו שתי חלות ואמרינן בר״פ עד כמה (בכורות דף כ״ו) אמר רבינא הילכך נדה קוצה לה חלה ואוכל לה כהן קטן ואי ליכא כהן קטן שקלא לה בריש מסא ושדיא בתנורא והדר מפרשא חלה אחריתי הרי בהדיא דכי אכיל לה כהן אינו צריך להפריש חלה שנייה:\",2,0],[8,357,5,11,\"כל המפריש חלה מברך תחילה וכו'. נתבאר ממה שיבא בסמוך:\",3,0],[8,357,5,11,\"כתב הראב\\\"ד א\\\"א כתב רב אחא ז\\\"ל וקורא לה שם ואומר ה\\\"ז תרומה עכ\\\"ל. טעמו משום דחלה שם העוגה וכבר כתב סמ\\\"ק שאין להקפיד בין יזכירו חלה בין יזכירו תרומה.\",4,0],[8,357,5,11,\"ומ״ש בין בח״ל כלומר אע״פ שאינה אלא מדבריהם מברך עליה כשם שמברכין על כל מצות דרבנן כדאמרינן בפרק במה מדליקין (שבת דף כ״ג).\",5,0],[8,357,5,11,\"ומ\\\"ש וכשם שמברך על הטהורה כך מברך על הטמאה בפ\\\"ב דחלה (משנה ג') תנן כשם שהוא קורא לטהורה כך הוא קורא לטמאה לזו קורא חלה בשם ולזו קורא חלה בשם.\",6,0],[8,357,5,11,\"ומ\\\"ש לפיכך אין האיש ערום מפריש חלה וכו'. משנה בפ\\\"ב דחלה.\",7,0],[8,357,5,11,\"ומ״ש וכל פניה טוחות בקרקע הכי מוקי לה בפרק מי שמתו (ברכות דף כ״ה):\",8,0],[8,357,5,12,\"הנדה וכיוצא בה וכו' שאינה מוזהרת על מגעה. בר״פ עד כמה (בכורות דף כ״ז):\",1,0],[8,357,5,12,\"ואם היה שם כהן קטן וכו' ה\\\"ז מותר לאכלה עם הזר על שלחן אחד. בפ\\\"ד דחלה (משנה ח').\",2,0],[8,357,5,12,\"ומ״ש לפי שאינה מדמעת ואפילו נתערבה שוה בשוה. נראה שאע״פ שאמרו בר״פ עד כמה דחלת ח״ל בטלה ברוב טעמו של רבינו מדגרסי' בירושלמי (פ״ד ה״י) על הא דתנן ונאכלת עם הזר על השלחן הורה רבי אבהו בבצרה שהיא צריכה רוב אמר רבי יונה מלמד שהיא עולה בפחות ממאה ואינה נאסרת באחד ומאה אמר רבי זעירא מתניתין אמרה אפי' אחד באחד דתנינן ונאכלת עם הזר על השלחן כלומר משום דאם תתערב עם פתו של זר מותרת לזר וס״ל דהלכה כרבי זעירא דמתניתין מסייעא ליה וכן פסק סמ״ג ואע״פ שבתרומת ח״ל לא התיר שמואל לבטלה אלא ברוב אפשר דהיינו דוקא במתכוין לבטלה אבל היכא דאינו מתכוון לבטלה אלא שהוא אוכלה עם הזר על השלחן וממילא היא מתערבת לפעמים אפילו לא נתערבה אלא שוה בשוה מותר ורש״י כתב בפרק עד כמה אהא דאמר שמואל תרומת ח״ל בטלה ברוב לאוכלה זר ולא בעינן ק״א ולאחר שעירבה ברוב חולין יכול לאכול זר או כהן בימי טומאתו לאחר שבטלה. והתוספות כתבו אהא דאמר שמואל תרומת ח״ל בטילה ברוב להתירה לכהן טמא וכו' ולא כמו שפירש הקונטרס לאכלה זר וכו' דבהדיא מוכח במנחות פרק רבי ישמעאל (מנחות דף ס״ג) דאסורה לזר וכו' דדייק התם הא דישראל אינה מדמעת משמע דאינה עולה לאכול לזרים אלא בק״א וכ״כ בסה״ת והרשב״א בפסקי חלה שלו כתב דההיא דשמואל אף לאכלה היא ומיהו דוקא ברוב אבל שוה בשוה לא דלית הלכתא כרבי זעירא דירושלמי והא דמשמע בפ״ר ישמעאל דחלת ח״ל מדמעת התם כשנתערבה חד בחד וא״נ לרבי זעירא דירושלמי בפחות מחד בחד עכ״ל:\",3,0],[8,357,5,12,\"ומ״ש ונותנים כו'. משנה בפ״ד דחלה (משנה ח') ונתנת לכל כהן וכו' ופירש״י בר״פ כל הבשר (חולין דף ק״ד:) דהיינו אפי' לכהן ע״ה:\",4,0],[8,357,5,12,\"ה\\\"ג ואין בה משום כהן המסייע במתנותיו שהוא אסור ואם רצה לאכול תחלה ואח\\\"כ יפריש ובספרים דידן חסר כל זה והוא ט\\\"ס.\",5,0],[8,357,5,12,\"ומ״ש ואין בה משום כהן המסייע וכו'. בר״פ עד כמה (בכורות דף כ״ז):\",6,0],[8,357,5,12,\"ומה שכתב ואם רצה לאכול תחלה ואח\\\"כ יפריש החלה וכו'. ג\\\"ז שם:\",7,0],[8,357,5,15,\"החלה נקראת תרומה לפיכך אינה ניטלת וכו' כתרומה. בספ\\\"ק דחלה ובפ\\\"ק דטבול יום.\",1,0],[8,357,5,15,\"ומ\\\"ש ואינה ניטלת מן הטהור על הטמא לכתחילה. בספ\\\"ב דחלה (משנה ח') וכחכמים.\",2,0],[8,357,5,15,\"ומ\\\"ש וכל שאמרנו בתרומה לא יתרום כו'. פשוט הוא שהרי היא נקראת תרומה.\",3,0],[8,357,5,15,\"ומ\\\"ש הסומא והשכור מפרישין חלה לכתחילה וכו'. כלומר אע\\\"פ שאין תורמין לכתחילה כמו שנתבאר בפ\\\"ק דתרומות הכא שאני דלא שייך ההוא טעמא:\",4,0],[8,357,6,1,\"הלוקח מן הנחתום חייב בחלה. משנה בפ\\\"ה דדמאי (מ\\\"א) הלוקח מן הנחתום נוטל כדי תרומת מעשר וחלה. וא\\\"ת הא תנן בפ\\\"ב דדמאי הנחתומים לא חייבו אותם חכמים להפריש אלא כדי ת\\\"מ וחלה וכתבה רבינו בפ\\\"ט מהלכות מעשר אלמא שהנחתום הוא חייב להפריש חלה בירושלמי (הלכה א') רמי להו אהדדי ותירץ רבי יוחנן כאן בעושה בטהרה כאן בעושה בטומאה כאן בעושה בטהרה נחתום מפריש הואיל וראויה לכהן לאכילה אבל עושה בטומאה לא הטריחו למוכר להפריש כיון דלא חזיא אלא להסיק תחת תבשילו ולוקח שיאכל הוא יפריש ור\\\"א תירץ כאן במדה דקה כאן במדה גסה כלומר במדה דקה צריך הנחתום להפריש מפני התינוקות שקונים מהם ואינם בקיאים להפריש. ויש לתמוה על רבינו שכתב שתי המשניות סתם ולא פירש:\",1,0],[8,357,6,1,\"ומ\\\"ש ומפריש מן החמה על הצוננת וכו' אפילו מדפוסים הרבה. בפ\\\"ה דדמאי (משנה ג') איפליגו תנאי לענין דמאי ור\\\"ש מתיר בחלה וכתב רבינו שמשון בחלה אפי' ר\\\"י מודה אפילו של אמש בשל היום ואפילו מב' דפוסין דאפילו מתרי גברי זבן לא חיישינן שהרי אצל הנחתום נתחייבה בחלה שהוא גילגל את העיסה:\",2,0],[8,357,6,2,\"אין חייבים וכו'. משנה בריש חלה (משנה א'):\",1,0],[8,357,6,3,\"הלקט והשכחה וכו'. ג\\\"ז משנה שם.\",1,0],[8,357,6,3,\"ומ\\\"ש שהקדימו בשבלים. ירושלמי שם:\",2,0],[8,357,6,3,\"ומ\\\"ש ומותר העומר. משנה שם ובמנחות פרק רבי ישמעאל ופירש\\\"י משום דחיוב חלה היינו גלגול דעיסה וגלגול של זו ביד הדיוט הוא לאחר שנפדה.\",3,0],[8,357,6,3,\"ומ\\\"ש ושתי הלחם ולחם הפנים. מהטעם שנאמר במותר העומר:\",4,0],[8,357,6,4,\"עיסה של מעשר שני וכו'. בפרק חלק (סנהדרין דף קי״ב) ובפרק לולב הגזול (סוכה דף ל״ה) ובפרק כל שעה (פסחים דף ל״ח) עיסה של מעשר שני לדברי ר״מ פטורה מן החלה לדברי חכמים חייבת ופסק כחכמים ויש לתמוה דהא פסק הוא ז״ל בפרק ג' מהלכות מעשר שני (הלכה י״ז) כר״מ דאמר מעשר שני ממון גבוה הוא וא״כ הו״ל למיפסק דפטורה מן החלה. ותירץ הר״י קורקוס ז״ל דטעמיה משום דבפרק לולב הגזול (סוכה דף ל״ה) גבי הא דתנן של ערלה פסול אמרינן מ״ט פליגי בה רבי חייא ורבי אסי חד אמר לפי שאין בה היתר אכילה וחד אמר לפי שאין בה דין ממון ואסיקנא דבהיתר אכילה כ״ע לא פליגי דבעינן כי פליגי בדין ממון רבי חייא סבר היתר אכילה בעינן דין ממון לא בעינן ורבי אסי סבר דין ממון נמי בעינן מאי בינייהו אתרוג של מעשר שני בירושלים אליבא דר״מ למ״ד לפי שאין בה היתר אכילה הרי יש בו היתר אכילה פירוש ומתניתין דתנן התם אתרוג של מעשר שני בירושלים לא יטול ואם נטל כשר אתיא אפילו כר״מ ולמ״ד בעינן נמי דין ממון מתניתין כרבנן דוקא אתיא דסברי ממון הדיוט והרי יש בו דין ממון ולא כרבי מאיר דאמר ממון גבוה הוא נמצא דלרבי חייא בהיתר אכילה תליא מילתא ואין כאן ענין לדין ממון וגבי מצה הכי קי״ל דיוצאין בשל מעשר שני בירושלים וכן פסק רבינו בפרק ו' מהלכות חמץ ומצה דר״ע הכי ס״ל התם ור״י הגלילי הוא דפליג עליה וקי״ל כר״ע מחבירו וע״כ ר״מ כר״ע ס״ל אע״ג דסבר ממון גבוה הוא דאי לא קשיא הלכתא אהלכתא אלא ודאי האי פסקא כרבי חייא אתיא דדין ממון לא בעינן אלא היתר אכילה בלחוד גם גבי אתרוג כן פסק רבינו כסתם מתניתין דאם נטל כשר וכרבי חייא דתלי בהיתר אכילה דלדידיה אתיא סתם מתניתין כר״מ דהלכתא כוותיה עכ״ל. והאריך ליישב הסוגיא לדרך זה ואני אומר עוד דודאי כרבי חייא קי״ל לגבי רבי אסי דהא רביה דרביה הוא ואין הלכה כתלמיד במקום הרב. כתב עוד הר״י קורקוס ז״ל נ״ל ראיה גמורה ומוכרחת לזה מדתניא בתוספתא דחלה פרק קמא עיסת מעשר שני בירושלים חייבת בחלה ספק מדומע חייב בחלה דברי ר״מ רבי יוסי פוטר הרי תוספתא מוכחת דאעיסה ליכא מאן דפליג וגם ר״מ מודה בה דבספק מדומע פליג בסיפא משמע דמודה ברישא גם בספרי פרשת שלח אמרו מראשית עריסותיכם שומע אני אף עיסת תרומה ומעשר שני ת״ל תרימו את שמורם קדש והשאר חולין ולא שזה וזה קדש אבל אמרו עיסת מעשר שני בירושלים חייבת בחלה ובודאי כיון שאמרו בתחילה ולא שזה וזה קדוש דאליבא דר״מ הוא דאמר ממון גבוה הוא ועלה קאמר אבל אמרו עיסת מעשר שני בירושלים חייבת בחלה מוכח דלר״מ נמי חייבת ואפשר דטעמא דשאני תרומה שהוא קדש גמור ואסור לזרים משא״כ במעשר עכ״ל.\",1,0],[8,357,6,4,\"ומ\\\"ש ועיסת שביעית. משנה סוף פרק ט' דשביעית.\",2,0],[8,357,6,4,\"ומ\\\"ש וספק מדומע. ירושלמי פרק קמא דחלה:\",3,0],[8,357,6,4,\"ומ\\\"ש אבל המדומע פטור מן החלה. משנה שם פרק קמא (משנה ד'):\",4,0],[8,357,6,5,\"חלות תודה וכו'. משנה פרק קמא דחלה (מ\\\"ו):\",1,0],[8,357,6,6,\"עיסת השותפים. בריש פרק ראשית הגז.\",1,0],[8,357,6,6,\"ומ\\\"ש והעושה עיסה לרבים וכו'. תוספתא פ\\\"ק דחלה:\",2,0],[8,357,6,7,\"העושה עיסה מן וכו'. ירושלמי רפ\\\"ה דדמאי ופרק קמא דחלה:\",1,0],[8,357,6,9,\"העושה עיסה וכו'. סיפרי זוטא ויליף לה מדכתיב עריסותיכם:\",1,0],[8,357,6,9,\"עיסת הכלבי' וכו'. משנה פרק קמא דחלה (משנה ח') ובירושלמי (הלכה ה') איפליגו כמה הוא עיסת כלבים ונראה מדברי רבינו שפסק כמ\\\"ד דאפילו עשאה גלוסקין והא תנינן בזמן וכו' ואם אין הרועים אוכלין ממנה תפתר בשעשאה משעה ראשונה שלא יאכלו הרועים ממנה ואם כן אפילו עשאה כמצתו של שלמה ואין בה שום גריעות ולא שינוי ולא היכר מאחר שעשאה משעה ראשונה שלא יאכלו ממנה שכתב לעיל בסמוך העושה עיסה לבהמה ולחיה פטורה וכתב לקמן שאין חייבת אלא עיסה שסופה לאפות לחם למאכל אדם ומפני שעיסת הכלבים דרך הרועים לפעמים לאכול ממנה כלומר שדרך אותם רועים לאכול מאותה עיסה או שאפאה ע\\\"ד כן נקרא לחם העשוי למאכל אדם וחייב. וכתב הר\\\"י קורקוס ז\\\"ל דמש\\\"ה לא סיים רבינו ואם אין הרועים אוכלים ממנה פטורה כדמסיים במתני' לפי שכבר כתבו לעיל העושה עיסה לבהמה ולחיה וכו':\",2,0],[8,357,6,9,\"עיסת העכו\\\"ם וכו' עד ה\\\"ז חייבת בחלה. משנה פ\\\"ג דחלה (משנה ה'):\",3,0],[8,357,6,10,\"עכו\\\"ם שהפריש חלה וכו' עד פחות משיעור חלה. במנחות פרק רבי ישמעאל (דף כ\\\"ז):\",1,0],[8,357,6,11,\"המערב קמח חטים וכו'. משנה פ\\\"ג דחלה ומייתי לה בפרק התערובות (זבחים דף ע\\\"ח) להוכיח דנותן טעם ברוב דאורייתא דס\\\"ל דמיירי אע\\\"ג דרובא אורז.\",1,0],[8,357,6,11,\"ומ\\\"ש ואפילו היה השאור חטים וכו'. משנה שם:\",2,0],[8,357,6,11,\"ומשמע ממשניות אלו שאע\\\"פ שאין בחטים חמשת רבעים כל שיש בעיסה חמשת רבעים חייבת אם יש בה טעם דגן והרשב\\\"א בפסקי חלה שלו כתב אבל בירושלמי אמרו (הלכה ה') מתניתין דלא כרשב\\\"ג דרשב\\\"ג אומר לעולם אינה חייבת בחלה עד שיהיה בה דגן כשיעור רבי יעקב בר אידי בשם ר\\\"ל הלכה כרשב\\\"ג וכ\\\"כ הראב\\\"ד והכין מסתבר כיון שפסקו כך בירושלמי ע\\\"כ:\",3,0],[8,357,6,11,\"והראב\\\"ד כתב כאן על דברי רבינו אם יש בה טעם דגן. א\\\"א נראה מן הירושלמי וכו'. וכתב עוד אפי' היה השאור חטים א\\\"א והוא שיהא השאור מעיסה חייבת עכ\\\"ל. והוכרח לומר כן מפני שהוא סובר דאינה חייבת עד שיהא בה דגן כשיעור וסתם שאור אין בו כשיעור ולפיכך הוצרך להעמיד מתניתין דמחייב בשבאה מעיסה חייבת. ויש לתמוה על רבינו שמאחר שבירושלמי אמרו מתניתין דלא כרשב\\\"ג ופסקו שם הלכה כרשב\\\"ג הרי דחאוה למשנה זו מהלכה ולמה פסק כמותה. ואפשר שרבינו היה גורס מתניתין כרשב\\\"ג וכן הוא בספרים שלנו וה\\\"פ מתניתין דקתני שהאורז נגרר אחר החטים אינה חייבת בחלה עד שיהא בה טעם דגן כדרשב\\\"ג דהיינו כשיעור דקאמר רשב\\\"ג כלומר שיהא בה דגן כשיעור שיתן בה טעם דגן ויש הוכחה לפירוש זה מדקתני בתוספתא (דף ס\\\"ח ע\\\"ג) העושה עיסה מהחטים ומהאורז רשב\\\"ג אומר אינה חייבת בחלה עד שיהא בה כשיעור ואין אדם יוצא בה ידי חובתו בפסח עד שיהא בה כשיעור והשתא אי כשיעור עיסת חלה קאמר מה מעלה ומוריד זה לענין לצאת י\\\"ח בפסח אלא ודאי כשיעור דקאמר היינו שיהא בה טעם דגן כדפרישית ולא משמע ליה דכשיעור דקתני לענין פסח היינו שיהא בו כזית בכדי א\\\"פ. חדא דדוחק לפרש כשיעור דרישא היינו עיסת חלה וכשיעור דסיפא כזית בכדי א\\\"פ ועוד דמשמע ליה ז\\\"ל דאע\\\"פ דאין בו כזית בכדי א\\\"פ יוצא בה אדם י\\\"ח בפסח וכמ\\\"ש הרב המגיד בפרק ו' מהלכות פסח שהוא דעת רבינו והרמב\\\"ן ז\\\"ל:\",4,0],[8,357,6,12,\"עיסה שנילושה ביין וכו'. משנה בפרק ב' דחלה (משנה ב') ואף על גב דבירושלמי (הלכה א') אמר רבי יוסי בר חנינא דמתניתין כרבי אלעזר איש ברתותא משום רבי יהושע כלומר ולא כרבי עקיבא משום רבי יהושע הא רבי יוחנן פליג עליה התם ואמר ד\\\"ה היא ועוד דאפילו לרבי יוסי בר חנינא כיון דמשום רבי יהושע הוא דאיפליגו אפשר דרבי אלעזר איש ברתותא בתרייתא הוא ושפיר דמי למימר הכי מדסתם לן תנא כוותיה וכן פסק הרשב\\\"א.\",1,0],[8,357,6,12,\"ומה שכתב או מים רותחים או שהרתיח וכו'. משנה פרק קמא דחלה (משנה ו') המעיסה בית שמאי פוטרין ובית הלל מחייבין החליטה בית שמאי מחייבים ובית הלל פוטרים ובפרק כל שעה (פסחים דף ל״ז) קתני עלה איזו היא המעיסה ואיזה היא החליטה המעיסה קמח על גבי מוגלשין החליטה מוגלשין שעל גבי קמח פירוש מוגלשין מים רותחים רבי ישמעאל ברבי יוסי אומר משום אביו זה וזה לפיטור ואמרי לה זה וזה לחיוב וכו' ותנא קמא מאי שנא המעיסה ומאי שנא החליטה אמר רבי יהודה וכו' תברא מי ששנה זו לא שנה זו ופסק רבינו כלישנא דאמר זה וזה לחיוב וטעמו משום דבירושלמי פירקא קמא דחלה (הלכה א') שנויה בלשון הזה וחכמים אומרים לא כדברי זה ולא כדברי זה אלא הנאפה בתנור חייב וכיוצא בזה בפרק כל שעה בגמרא דידן וכיון דתנייה בלשון חכמים אלמא סבר דהלכתא כוותיה והכי אמרינן בפרק החולץ (יבמות דף מ') אף על גב דחלטיה מעיקרא כיון דהדר אפייה בתנור לחם קרינן ביה.\",2,0],[8,357,6,12,\"ומה שכתב אם אפאה וכו' עד ואחר כך הדביק הבצק. פלוגתא דרבי יוחנן וריש לקיש בפרק כל שעה ופסק כרבי יוחנן וכן פסק הרי\\\"ף והרא\\\"ש והרשב\\\"א.\",3,0],[8,357,6,12,\"ומה שכתב בין בקרקע בפרק כיצד מברכין (ברכות דף ל״ז:) האי טרוקנין חייבת בחלה מאי טרוקנין וכו' כובא דארעא פי' שעושין חפירה בקרקע ואופים שם.\",4,0],[8,357,6,12,\"ומה שכתב ואחר כך הרתיחן באש מלמטה כלומר ואין צריך לומר אם האור מהלך מן הצד ולא מלמטה דבהא אפילו ריש לקיש מודה כדאיתא בירושלמי וטעמא משום דזהו דרך אפיית פת פורני.\",5,0],[8,357,6,12,\"ומה שכתב או שנתן לתוכה תבלין נלמד מדאמרינן בפרק כיצד מברכין (ברכות דף מ״ה) דפת הבאה בכסנין אם קבע סעודתו עליו מברך המוציא לחם מן הארץ וכיון דאיקרי לחם חייב בחלה:\",6,0],[8,357,6,12,\"ומה שכתב אבל העושה עיסה ליבשה בחמה. בפרק כל שעה אמרינן דמודה ביה רבי יוחנן.\",7,0],[8,357,6,12,\"ומה שכתב או לבשלה בקדרה. הכי אמרינן בירושלמי (הלכה ג') ריש לקיש אמר כל שהאור מהלך תחתיו אינו חייב בחלה אמר ליה רבי יוחנן ובלבד על ידי משקה:\",8,0],[8,357,6,12,\"וכן קלי שלשין אותו וכו'. ירושלמי פירקא קמא דחלה קמח קלי שעשאו בצק חייב בחלה רבי יוסי בשם רבי יוחנן אמר והוא שאפאן משמע בהדיא שאם לא אפאן פטור:\",9,0],[8,357,6,13,\"עיסה שלשה תחלה וכו'. שם פ\\\"ק (מ\\\"ה) עיסה שתחלתה סופגנים וסופה סופגנים פטורה מן החלה תחלתה עיסה וסופה סופגנים תחילתה סופגנים וסופה עיסה חייבת בחלה ופירש הרמב\\\"ן שבדעתו הדבר תלוי שאם מתחלה עשאה ע\\\"ד לחם אז חייבת בגלגול אע\\\"פ שלבסוף עשאה סופגנין ואם עשאה ע\\\"ד סופגנים אע\\\"פ שמתחלה בלילתה קשה פטורה וכן העלה הרא\\\"ש והר\\\"ש וזה דעת רבינו וכ\\\"כ הרשב\\\"א שדעת זה עיקר. ולאפוקי מפירוש ר\\\"ת.\",1,0],[8,357,6,13,\"ומ\\\"ש וכן קלי. נתבאר בסמוך:\",2,0],[8,357,6,14,\"לחם העשוי לכותח וכו'. בפרק כיצד מברכין (ברכות דף ל״ז:) ופירש״י לחם העשוי לכותח אין אופין אותו בתנור אלא בחמה כעכין ערוכה ומקוטפת כגלוסקאות נאות גלי דעתיה דללחם עשאה כלמודים כנסרים בעלמא שלא הקפיד על עריכתם:\",1,0],[8,357,6,15,\"כמה שיעור העיסה וכו'. פרק כיצד משתתפין (עירובין דף פ״ג ע״א) ת״ר ראשית עריסותיכם כדי עיסותיכם וכמה עיסותיכם כדי עיסת המדבר דכתיב והעומר עשירית האיפה הוא מכאן אמרו ז' רבעים קמח ועוד חייבים בחלה שהם שש ירושלמיות שהן חמש של צפורי ופירש״י שם ובפרק אלו עוברין האיפה ג' סאין כדיליף בפרק התודה והעומר עשירית של ג' סאין שהם י״ח קבין שהם ע״ב לוגין עשירית ע' לוגין ז' לוגין עשירית של שני לוגין חומש הלוג שהוא ביצה וחומשא והיינו דקאמר ז' רבעים ועוד ז' רבעי הקב דהיינו ז' לוגין ועוד ביצה וחומשא שהן שש ירושלמיות שהרי שש מדבריות נעשו חמש ירושלמיות נשאר לנו לוג מדברי וחומשו דביצה וחומשא הוי חומש הלוג ביצה חומש לחמש ביצים והחומש ביצה הוא תוספת לביצה הששית הרי לוג וחומשו והם נעשים לוג ירושלמי שהרי ששה חומשים נעשו חמשה הרי עומר המדבר שש רבעים ירושלמיות וסאה צפורית עודפת על ירושלמית שתות מלבר כדאמרינן בעירובין הרי עומר שהיה ששה רבעי ירושלמית נכנס בחומש צפוריים ומאחר ששבעה רבעי קב מדבריים וחומש הוי שיעור העיסה וכל רובע קב מהם הוא שש ביצים עולה מ״ג ביצים וחומש שיעור עיסה החייבת בחלה וע״פ זה יתבאר לך שמ״ש רבינו ששיעור העומר שני קבין פחות חומש הוא ע״פ המדה המדברית שהאיפה ג' סאין והסאה ששה קבין נמצאת האיפה י״ח קבין נמצאת עשיריתה שני קבין פחות חומש שהן ז' לוגין ועוד מדבריים שהם ה' לוגין צפוריים והיינו דתנן בפ״ק דעדיות חמשה רבעים חייבים בחלה שהלוג רביעית הקב הוא והרביעית אצבעיים על אצבעיים וכו'.\",1,0],[8,357,6,15,\"ומ\\\"ש שהם משקל תק\\\"כ זוז מזוזי מצרים פירוש כל זוז היא משקל דרה\\\"ם וכל סלע ד' דינרים וכל דינר ו' מעין נמצא כל דינר משקלו דרה\\\"ם וחצי וכל סלע משקלו ששה דרה\\\"ם נמצא פ\\\"ו סלעים עולים תקי\\\"ו דרה\\\"ם ושני שלישי סלע הם ד' דרה\\\"ם הרי תק\\\"כ דרה\\\"ם לפ\\\"ו סלעים ושני שלישי סלע.\",2,0],[8,357,6,15,\"ומ\\\"ש כולם מצטרפין לשיעור. משנה בריש חלה:\",3,0],[8,357,6,16,\"אסור לאדם וכו'. ירושלמי רפ\\\"ג דחלה (הלכה א') הדא אמרה שאסור לאדם לעשות עיסתו קבין:\",1,0],[8,357,6,16,\"והמפריש חלה מעיסה וכו'. משנה פ\\\"ד דחלה (משנה ד') וכחכמים:\",2,0],[8,357,6,16,\"עשה עיסה פחותה מכשיעור ואפאה וכו'. משנה פ״ב דחלה (משנה ד') העושה עיסתו קבין ונגעו זה בזה פטורים מן החלה עד שישוכו ר״א אומר אף הרודה ונותן לסל הסל מצרפן לחלה ואיפסיקא הלכתא כוותיה בפרק אלו עוברין (פסחים דף מ״ח) ובפ״ק דנדה (דף ח').\",3,0],[8,357,6,16,\"ומ\\\"ש ואין התנור מצרפן לחלה. בפרק אלו עוברין תניא ר\\\"א אומר הסל מצרפן רבי יהושע אומר התנור מצרפן רשב\\\"ג אומר ככרות של בבל שנושכות זו בזו מצטרפות ומשמע דלר\\\"א סל דוקא מצרף ולא תנור ופסק כמותו משום דהא איפסיקא הלכתא כוותיה דמשמע דלאפוקי נמי מדרבי יהושע איפסיקא ותו דרשב\\\"ג נמי סבר דאין תנור מצרפן והו\\\"ל רבי יהושע יחיד לגבייהו והרשב\\\"א כתב בפסקי חלה שלו וז\\\"ל ואפשר היה לומר דרבי יהושע תנור ולא סל קאמר ור\\\"א אפילו הסל מצרף וכ\\\"ש התנור אבל בירושלמי (הלכה ב') גרסינן אית תנא תני הסל מצרף ואין התנור מצרף ואית תנא תני התנור מצרף ואין הסל מצרף וכיון שכך מסתברא דבחלת הארץ דאורייתא בין בסל בין בתנור מצטרפין וחייבים בחלה מספק אבל בח\\\"ל דוקא בסל כר\\\"א והרמב\\\"ם כתב אבל בתנור אינו מצרפן ולא חילק בין בארץ לח\\\"ל ולא ידעתי מי הביאו לידי כך עכ\\\"ל. ואני בעניי גברא רבה חזינא ותיובתא לא חזינא שרבינו יפרש דהאי תנאי דפליגי בירושלמי הם רבי אליעזר ורבי יהושע והא איפסיקא הלכתא כר\\\"א ועוד דאפילו אי הוה סבר רבינו כהרשב\\\"א לא היה לו לחלק בין א\\\"י לח\\\"ל משום דחלה אף בא\\\"י בזמן הזה אינה כימי עזרא אלא מדרבנן כמבואר בדברי רבינו פ\\\"א מהלכות תרומות ופ\\\"ה מהלכות חלה:\",4,0],[8,357,6,17,\"היו הככרות נושכות זו בזו וכו'. הרשב\\\"א בפסקי חלה שלו כתב וז\\\"ל העושה עיסתו קבין ונגעו זה בזה פטורים מן החלה עד שישוכו פירוש אע\\\"פ שנגעו לאחר עריכה זה בזה אינם מצטרפין אבל אם השיכן זה לזה הואיל והם לאדם אחד מצטרפין וחייבים ואי זו היא נשיכה שנינו בתוספתא דטהרות איזהו הנושך התולש ממנו כל שהוא כלומר שאי אפשר שלא יתלוש מזה עם זה כשמפרידן ר' אליעזר אומר אפילו אינו מדביקן בעודן עיסה אלא שאפאן ונתנן בסל הסל מצרפן לחלה והוא שיהו ממין אחד ואע\\\"פ שאינן נוגעות זו בזו כגון כעכין וכדאמרינן פרק אלו עוברין (פסחים דף מ\\\"ח:) השיך הככרות זו בזו לאחר אפייה כל שאינן בתוך כלי אינן מצטרפות ואני תמה ממה שכתב רבינו משה שכך כתב עשה עיסה פחותה מכשיעור ואפאה ונתן הפת לסל הסל מצרפן לחלה היו הככרות נושכות זו בזו וכו' חייבים בחלה אע\\\"פ שאינם בסל דאלמא משמע מדבריו דכל שהן כככרות של בבל חייבים ולא הוצרכו לסל אלא כעכין ונראה שהוא ז\\\"ל פירש עד שישוכו דמתניתין אפי' לאחר אפייה ואינו אלא בלישה ואפילו לר\\\"א דמחמיר טפי מדרבנן ואמר שאף הסל מצרפן הוה סבר ריב\\\"ל דדוקא ככרות של בבל כדאמר פרק אלו עוברין אמר רב יוסף הני נשי דידן נהוג למיפא קפיזא קפיזא א\\\"ל אביי מאי דעתיך לחומרא חומרא דאתי לידי קולא הוא דקא מפקען ליה מחלה אמר ליה דעבדין כר\\\"א דתנן ר\\\"א אומר אף הרודה ונותן לסל וכו' ואמר רב יהודה אמר שמואל הלכה כרבי אליעזר ואקשי עלה והא איתמר עלה אמר ריב\\\"ל לא שנו אלא ככרות של בבל שנושכות זו מזו אבל כעכין לא אלמא לריב\\\"ל אליבא דר\\\"א תרתי בעינן נשיכת ככרות וצירוף סל ורבנן הקלו בלאחר אפייה ואמרו דאין מצטרפין אלא בשנשכו בעיסה והיינו דלא הזכירו ככרות אלא העושה עיסתו קבין ונגעו זה בזה כלומר שני הקבין בעיסתן והא דתניא רבי אליעזר אומר הסל מצרפן רבי יהושע אומר תנור מצרפן רשב\\\"ג אומר ככרות שנושכות זו בזו מצטרפות רשב\\\"ג מחמיר הוא מדכולהו ור\\\"א ורבי יהושע אינם מודים לו בכך ואפשר שהרב ז\\\"ל מפרש דר\\\"א ורבי יהושע איירי בכעכין ובשאר ככרות שהם כעין כעכין שאינם נושכות זו מזו ורשב\\\"ג איירי בככרות הנושכות ולא פליגי וקי\\\"ל כרשב\\\"ג דלא אשכחן מאן דפליג עליה והא דתנן במתניתין עד שישוכו אפילו לאחר אפייה קאמר ולא גריס הרב בדברי ר\\\"א אף הרודה אלא הרודה ות\\\"ק סבר שהכל תלוי בנשיכה אבל סל בלא נשיכה לא מעלה ולא מוריד ור\\\"א אליבא דריב\\\"ל סבר דתרתי בעינן נשיכה וסל כבככרות של בבל ור\\\"א לקולא וכדאסיקנא אמר רבי חנינא אפילו כעכין ור\\\"א לחומרא או נשיכה כככרות של בבל או כעכין וצרוף סל קאמר זה נ\\\"ל להעמיד דברי הרב אע\\\"פ שהוא דחוק מאד שנמחוק הספרים שכתב בהם אף הרודה ועוד שנפרש דר\\\"א ורבי יהושע לא דברו אלא בכעכין דוקא ועוד דלריב\\\"ל ודאי רבי אליעזר חולק הוא על רשב\\\"ג דהא אף ככרות הנושכות בעו צירוף סל וכיון דאליבא דריב\\\"ל פליגי עליה דרשב\\\"ג אנן מאן לימא לן דלא פליגי עכ\\\"ל. ולענין מ\\\"ש רבינו מפרש שישוכו דמתני' הוי אפי' לאחר אפייה תמהני שאיני יודע מה נשיכה שייך אחר גמר אפייה ועוד שאיני רואה הוכחה בדבריו לומר שיהא סובר כן ונראה שרבינו מפרש דמתניתין דעד שישוכו היינו שנדבקו זה בזה בתנור כמו שאירע לפעמים שנדבקים שם יפה וכשמוציאין אותם מהתנור יתראו כאילו שניהם אחד אם לא יפרידו אותם וכ\\\"כ בפירוש המשנה ונגעו זה בזה ר\\\"ל בעת האפייה שנגעו קצת ככרות לקצתם שאין חייבות בחלה עד שידבקו קצתם בקצתם דיבוק יפה עכ\\\"ל וכן פירש\\\"י. ולענין מה שנדחק לפרש המשנה והגמרא לדעת רבינו אני איישב בלי שנמחוק גירסת הספרים ובלי דוחק והוא לומר שרבינו מפרש דר\\\"א אומר אע\\\"פ שלא נשכו זה בזה אם נתנן לסל הסל מצרפן והוה סבר ריב\\\"ל דלא א\\\"ר אליעזר הסל מצרפן אלא בככרות של בבל שהן כתבנית שכשהן דחוקות בתנור עשויות לישוך זו בזו כלומר לידבק דיבוק יפה הילכך כשלא נשכו מהני להו צירוף סל אבל כעכין שמתוך שהן בתבנית אף ע\\\"פ שיהיו נדחקות בתנור אינם נושכות זו בזו לא מהני להו צירוף סל ורבי חנינא סבר דאף בכעכין אר\\\"א דמהני להו צירוף סל נמצא שכשנשכו זה בזה בין לת\\\"ק בין לרבי אליעזר מצטרפין וכשלא נשכו זה בזה ונתנן בסל לת\\\"ק אין מצטרפין ולרבי אליעזר מצטרפין ומשמע דרשב\\\"ג דברייתא היינו ת\\\"ק דמתניתין ופליג ארבי אליעזר ורבי יהושע ואמר לא סל ולא תנור מצרפן אלא אם נושכות זו בזו מצטרפות בלא סל ותנור ואם אין נושכות זו בזו לא מהני להו צירוף סל ותנור ור\\\"א ורבי יהושע סברי שאם נושכות זו בזו מצטרפות בלא סל ותנור וכשאין נושכות סל מצרפן לרבי אליעזר ותנור לרבי יהושע והשתא מ\\\"ש רבינו היו הככרות נושכות זו בזו ונתקבץ מן הכל שיעור חלה חייבים בחלה אע\\\"פ שאינם בסל דברי הכל היא וליכא מאן דפליג ביה. ובכן עלו דברי רבינו כהוגן בלי פקפוק:\",1,0],[8,357,6,17,\"אפה מעט מעט וכו'. בפרק אלו עוברין בעיא דלא איפשיטא ופסק בה בדאורייתא לחומרא ובדרבנן לקולא:\",2,0],[8,357,6,18,\"קמח שלא רקדו וכו'. משנה פ\\\"ב דחלה (מ\\\"ו):\",1,0],[8,357,6,19,\"נחתום שעשה עיסה וכו'. משנה בפ\\\"ק דחלה (משנה ז').\",1,0],[8,357,6,19,\"ומ\\\"ש שאם לא תמכר יעשנה פת. שם בירושלמי (הלכה ה') נחתום לא בדעתו הדבר תלוי בדעת הלקוחות הדבר תלוי שמא (לא) ימצא לקוחות והוא חוזר ועושה אותה עיסה כך נראה שהיא גירסת רבינו.\",2,0],[8,357,6,19,\"ומ\\\"ש אבל העושה עיסה לחלקה בצק אסורה. שם בירושלמי:\",3,0],[8,357,6,19,\"כתב הראב\\\"ד נ\\\"ל מהגמרא שאף האשה שעשתה וכו':\",4,0],[8,357,6,19,\"ודע שלשון הירושלמי בפרק הנזכר כך הוא הממרח כריו של חבירו שלא מדעתו ר\\\"י אמר נטבל ר\\\"ל אמר לא נטבל מתיב ר\\\"ל קמיה דר\\\"י והא תנן וכן נשים שנתנו לנחתום לעשות להן שאור אם אין בשל אחת כשיעור פטורה מן החלה ואין בשל כולהון כשיעור א\\\"ל שניא היא שכן העושה עיסה ע\\\"מ לחלקה בצק פטורה מן החלה א\\\"ל והתנינן נחתום שעשה שאור לחלק חייב בחלה א\\\"ל לא תתיבני נחתום נחתום לא בדעתו הדבר תלוי בדעת הלקוחות הדבר תלוי שמא ימצא לקוחות וימלך לעשותה עיסה ע\\\"כ. כך היא הגירסא נכונה והיא גירסת הראב\\\"ד והיא גירסת הרשב\\\"א בפסקי חלה שלו ובנוסחא דידן כתוב מתיב ר\\\"י לר\\\"ל וט\\\"ס הוא. וז\\\"ל רבינו שמשון בפירוש המשנה [נחתום] שעשה שאור לחלק כדי חיוב חלה עשה בבת אחת אלא שדעתו לחלק לכמה עיסות ואין בכל חלק וחלק כשיעור ופליגי בירושלמי אי נחתום דוקא אי לא ונשים שנתנו לנחתום לעשות להן שאור ובין כולן יש כשיעור ולש הכל בבת אחת שלא מדעתן ירושלמי הממרח כריו של חבירו שלא מדעתו רבי יוחנן אמר נטבל ר\\\"ל אמר לא נטבל מתיב ר\\\"י לר\\\"ל והתנן וכן נשים שנתנו לנחתום לעשות להן שאור אם אין בשל אחת מהם כדי שיעור פטורה מן החלה ואין בשל כולהון כשיעור בתמיה לומר לא נטבל וטעות סופר בירושלמי וקאמר ר\\\"י בעושה עיסה ע\\\"מ לחלקה [בצק] פטורה מן החלה כדמשני הכא אמר ליה שניא היא שכן העושה עיסה לחלקה בצק פטורה מן החלה אמר ליה והתנן נחתום שעשה שאור לחלק חייב בחלה אמר ליה לא תתיבני נחתום לא בדעתו הדבר תלוי בדעת הלקוחות הדבר תלוי שמא ימצא לקוחות ונטבלו מיד כלומר לא יחלק אם ימצא קונים עכ\\\"ל. ורבינו פסק כר\\\"י שמחלק בין נחתום לאחר והראב\\\"ד סובר דלא קי\\\"ל כוותיה אלא כר\\\"ל דפליג עליה ואמר נחתום לאו דוקא ונסתייע בזה מעובדא דירושלמי דאמר דחיישי' שמא תמלך לעשותה עיסה ה\\\"נ חיישינן שמא תמלך שלא לחלקה וכן מדיוקא דמתניתין ויש לומר לדעת רבינו שאין לנו לדחות הכלל שבידינו דהלכה כר\\\"י לגבי ר\\\"ל וההיא דירושלמי לא מכרעה דהתם עשתה עיסתה אטרינא שהם סופגנין ואחר כך רצתה ליקח קצת ממנה לאפותה ושאלה אם יכולה לאכלה בלא חלה כיון שאין במה שלקחה לאפות שיעור חלה ואסר לה משום שמא תמלך על כולה או על שיעור חלה לאפותה דאיכא למימר שאני התם דמתחלה עשתה כל עיסתה ע\\\"ד לעשותה כולה אטרינא ואחר כך נמלכה לאפות קצתה דכיון דחזינן שנמלכה על קצתה איכא למיחש שמא תמלך על כולה או על כדי שיעור חלה מה שאין כן בעושה עיסתה לחלק דכיון דלא ראינו שנמלכה לא חיישינן שתמלך ומה שרצה לדייק ממתניתין דנשים שנתנו לנחתום לעשות להן שאור וכו' סובר רבינו דמדנקט רישא נחתום משמע בהדיא דדוקא נחתום הא שאר כל אדם שעשה עיסה לחלק פטורה ואיידי דאיירי רישא בנחתום נקט בסיפא בנחתום לומר דאע\\\"ג דברישא נחתום שעשה עיסה לחלק חייב בנחתום דסיפא פטור ומשום דאין דרך אשה אחת לתת קמח לנחתום לעשות עיסה לחלק נקטה בנשים שנתנו. ועי\\\"ל שהרי רבינו שמשון פירש דה\\\"ק נשים שנתנו לנחתום לעשות להן שאור ובין הכל יש שיעור ולש הכל בבת אחת שלא מדעתן ולפי פירוש זה לא שייך לדייק מה שדייק הראב\\\"ד שאין זה ענין לעושה עיסה לחלק ודין עושה עיסה לחלק הא שמעינן מדיוקא דרישא כדאמרן:\",5,0],[8,357,6,20,\"נשים שנתנו קמח לנחתום לעשות להם וכו'. משנה שם:\",1,0],[8,357,7,1,\"שתי עיסות וכו'. משנה רפ\\\"ד דחלה (מ\\\"א) שתי נשים שעשו שני קבין ונגעו זה בזה אפילו הן ממין א' פטורין ובזמן שהם של אשה אחת מין במינו חייב ושלא במינו פטור.\",1,0],[8,357,7,1,\"ומה שכתב ואם ידוע שאינם מקפידין וכו' וכן מה שכתב ואם היה מקפיד וכו'. שם בירושלמי (ה\\\"א):\",2,0],[8,357,7,3,\"וכיצד מצטרפות וכו'. שם במשנה ב' אי זהו מין במינו החטים אינם מצטרפות [עם הכל] אלא עם הכוסמין השעורים מצטרפות עם הכל חוץ מן החטים ר״י בן נורי אומר שאר המינים מצטרפים זה עם זה ופסק כר״י בן נורי משום דמשמע ליה דר״י בן נורי לאו לאיפלוגי את״ק אתא אלא לפרושי דאע״ג דבירושלמי אמרו מהו שיירתא רב הונא אמר אם אומר את השיפון מין כוסמין מצטרף עם החטים שבולת שועל מין שעורים אינו מצטרף עם החטים ופירשו ר״ש והרא״ש דת״ק פליג אר״י בן נורי בשאר מינים דלת״ק שיפון מין כוסמין ושבולת שועל מין שעורים ואין מצטרפין ולי נראה שפירושם דחוק בלשון הירושלמי אלא ה״פ משום דר״י בן נורי אמר שאר מינים מצטרפין זה עם זה נראה ששיפון וכוסמין ושבולת שועל שלשתן מין אחד הם ומאחר שהחטים מצטרפות עם הכוסמין למה לא יצטרפו עם השיפון ושבולת שועל ושני רב הונא דאע״ג דשאר מינים מצטרפין זה עם זה לא יחוייב בשביל זה שיצטרפו עם החטים דבשלמא שיפון מאחר שהוא מין כוסמין להיותו דומה לו יש מקום לומר שמצטרפים עם החטים אבל שבולת שועל שהוא מין שעורים פשיטא שאינם מצטרפין עם החטים נמצא שלא למדנו מהירושלמי אלא דלת״ק אם נאמר דשיפון מין כוסמין מצטרף אבל לענין שאר מינים שמצטרפים זה עם זה ליכא מאן דפליג אר״י בן נורי. זה נ״ל שהוא דעת רבינו בפירוש הירושלמי הזה. ומה ששנינו במנחות ס״פ ר' ישמעאל (מנחות דף ע') תנא כוסמין מין חטים שבולת שועל מין שעורים צ״ל דאף מין חטים קאמר ושפיר מצטרפים שלשתן זה עם זה דשלשתן מין שעורים הם אלא שהכוסמין הם מין שעורים ומין חטים:\",1,0],[8,357,7,4,\"עיסת חדש וכו' ולא יתרום מאמצע שתיהן. משנה (דף שם) וירושלמי בפ\\\"ד דחלה וכחכמים.\",1,0],[8,357,7,4,\"ומ\\\"ש אלא יביא עיסה אחרת חדש או ישן. שם בירושלמי קב חדש מצטרף ומשמע דהיינו לומר שאם היה ישן מצד זה וישן מצד זה וחדש באמצע מצרפן וה\\\"ה אם היה חדש מצד זה וחדש מצד זה וישן באמצע שהוא מצרפן:\",2,0],[8,357,7,4,\"בד\\\"א בעיסה שנגעה וכו'. בירושלמי בריש חלה (הלכה א') רמי מתניתין דחמשת מינים מצטרפין זה עם זה אמתניתין דהחטים אינן מצטרפות אלא עם הכוסמין וכו' ומשני כאן בנשוך כאן בבלול:\",3,0],[8,357,7,5,\"עיסה שהיא וכו'. משנה ג' פרק רביעי דחלה שני קבים וקב אורז או קב תרומה באמצע אינם מצטרפין.\",1,0],[8,357,7,5,\"ומה שכתב או מדומע או עיסת עכו\\\"ם בירושלמי:\",2,0],[8,357,7,6,\"היה באמצע עיסה וכו'. שם במשנה.\",1,0],[8,357,7,6,\"ומ\\\"ש וכן אם היה ביניהם עיסת הקדש וכו' עד הרי שתי העיסות שבצדדין מצטרפות לחלה. שם בירושלמי (הלכה ב'):\",2,0],[8,357,7,7,\"שתי עיסות שכל אחת מהן פחותה מכשיעור וכו'. משנה ה' שם וכחכמים:\",1,0],[8,357,7,9,\"שני עכו\\\"ם שעשו עיסה וכו' עד מפני שעשאוה לחלק. ירושלמי בפ\\\"ג דחלה (הלכה ד'):\",1,0],[8,357,7,9,\"כתב הראב\\\"ד אבל שני ישראלים וכו'. א\\\"א אין דבר זה מחוור וכו' ורבינו סובר שאין לדחות הירושלמי בכך וע\\\"כ יש למצוא טעם לדברי הירושלמי דלא תיקשי ליה מהעושה עיסתו קבין והשיכן או צרפן בסל דחייב וי\\\"ל דשאני התם שעדיין לא היה לה שעת חובה מעולם הילכך כל שהגיע לה שעת חובה חייבת אבל הכא שכבר היה לה שעת חובה שהרי היה כשיעור ונפטרה מפני שעשאוה לחלק שוב אינה חוזרת להתחייב דה\\\"ל כאילו הורמה ממנה חלתה באותה שעה והרי זו דומה לאותה ששנינו בפרק ג' דחלק (משנה ג') הקדישה עיסתה עד שלא גלגלה וגלגלה הגזבר ואח\\\"כ פדאתה פטורה שבשעת חובתה היתה פטורה ואין זה ענין אצל דיחוי דמצות:\",2,0],[8,357,7,10,\"היתה העיסה ביד עכו\\\"ם והישראל בשותפות וכו'. גם זה שם בירושלמי ישראל ועכו\\\"ם שעשו שני קבין וחלקו והוסיף זה על שלו וזה על שלו ניחא חלקו של ישראל חייב חלקו של עכו\\\"ם מהו כלום חלקו של עכו\\\"ם חייב אלא מחמת חלקו של ישראל חלקו של ישראל חייב וחלקו של עכו\\\"ם פטור. והראב\\\"ד גורס כלום חלקו של ישראל חייב אלא מחמת חלקו של עכו\\\"ם והיא הגירסא הנכונה ופסק רבינו כירושלמי הזה כפשוטו שהוא בניחותא:\",1,0],[8,357,7,10,\"והראב\\\"ד כתב על דברי רבינו א\\\"א דומה דקשיא דידיה אדידיה וכו'. ואני אומר דגם לפירוש הראב\\\"ד קשה לירושלמי עצמו שפסק בשני עכו\\\"ם לפטור ובשני ישראלים לחיוב דישראל ועכו\\\"ם אמאי שניהם חייבים הל\\\"ל של עכו\\\"ם חייב ושל ישראל פטור לפיכך נראה ליישב הירושלמי לדברי רבינו דשל ישראל חייבת משום דכיון שחלקו היה מחובר עם של עכו\\\"ם ועכו\\\"ם לאו בר חיובא הוא נמצא שלא בא עיסה זו עדיין לידי חיוב חלה מעולם והוי כעושה עיסתו קבין והשיכן או צרפן בסל דחייב וז\\\"ש כלום חלקו של ישראל חייב אלא מחמת חלקו של עכו\\\"ם כלומר דאין חלקו של ישראל חייב אלא מפני שהמשלים שיעור חלה היה חלקו של עכו\\\"ם דלאו בר חיובא הוא והוי חלקו של ישראל כאילו נלוש לבדו הילכך כשיוסיף עליו וישלים לכשיעור חייב ומה שאמרו אחר זה חלקו של ישראל חייב חלקו של עכו\\\"ם פטור היינו לומר דכיון דחזינן דחלקו של ישראל חייב מטעמא דאמרן ממילא שמעינן דחלקו של עכו\\\"ם פטור דכיון דחלק העכו\\\"ם מחובר לחלק ישראל דבר חיובא הוא א\\\"כ הוי כאילו לש העכו\\\"ם שיעור חלה וכבר היה לה שעת חובה ונפטרה מפני שהיה עכו\\\"ם באותה שעה ושוב אינה חוזרת להתחייב כמו שנתבאר וצ\\\"ל דבעשו עיסה זו על מנת שלא לחלק ואחר כך נמלכו וחלקו מיירי דאי מתחלה עשאוה ע\\\"מ לחלק לא היה לה שעת חובה מעולם והכי דייק לישנא דרבינו שכתב בבבא זו היתה העיסה ביד העכו\\\"ם וביד הישראל בשותפות מה שלא כתב כן בשאר בבות והיינו לומר שלא עשאוה לחלקה אלא להיות ביניהם בשותפות ואחר כך נמלכו וחלקוה ומש\\\"ה של עכו\\\"ם פטורה שכבר היה לה שעת חובה אבל אם מתחלה עשאוה ע\\\"מ לחלקה של עכו\\\"ם נמי חייבת דהא לא היה לה שעת חובה מעולם:\",2,0],[8,357,7,11,\"הנוטל שאור וכו' עד שיפריש חלה על הכל. משנה פרק ג' דחלה (משנה ח').\",1,0],[8,357,7,11,\"ומ\\\"ש שהטבל במינו אוסר בכל שהוא. גם זה שם במשנה:\",2,0],[8,357,7,12,\"עיסה הטבולה לחלה וכו'. בסוף פ' ב' דחלה (משנה ח') תנן ר\\\"א אומר ניטלת מן הטהור על הטמא כיצד שתי עיסות אחת טמאה ואחת טהורה נוטל כדי חלה מעיסה שלא הורמה חלתה ונותן פחות מכביצה באמצע כדי שיטול מן המוקף וחכמים אוסרין. ופירש שם רבינו א\\\"ר אליעזר שנוטל אדם מעיסה טהורה שלא הורמה חלתה שיעור תרומה החייבת לעיסה טמאה ולעיסה טהורה ואח\\\"כ נוטל פחות מכביצה מעיסה טמאה ומחלקה ונותן בצדה מצד א' עיסה טהורה ובצדה מצד שני עיסה טמאה ויהיה אותו החלק שהוא פחות מכביצה באמצע ואח\\\"כ יניח השיעור שבו שיעור שתי חלות על אותו החלק הטמא שהוא פחות מכביצה ומוציאו לשם חלה על שתי העיסות ואז יהיה תורם מן המוקף כיון שכל אותם השיעורים דבוקים זה בצד זה ותהיה החלה טהורה והעיסה טהורה ג\\\"כ עומדת בטהרתה לפי שכל אחת מהן לא נגעה אלא בפחות מכביצה אוכל טמא וכו' ומה שהוא פחות מכביצה מאוכל טמא אינו מטמא טומאת אוכלים עכ\\\"ל. ובס\\\"פ כשם קאמר אהא דמתניתין ותניא כביצה סברוה אידי ואידי בעיסה ראשונה וחולין הטבולים לחלה לאו כחלה דמו מאי לאו בהא קמיפלגי דמ\\\"ס אין שני עושה שלישי בחולין ומ\\\"ס שני עושה שלישי בחולין אמר רב מרי בריה דרב כהנא דכ\\\"ע אין שני עושה שלישי בחולין והכא בחולין הטבולים לחלה קמיפלגי מ\\\"ס כחלה דמו ומ\\\"ס לאו כחלה דמו ואיבעית אימא דכ\\\"ע חולין הטבולין לחלה לאו כחלה דמו ואין שני עושה שלישי בחולין והכא לגרום טומאה לחולין שבא\\\"י קמיפלגי מ\\\"ס מותר לגרום טומאה לחולין שבא\\\"י ומ\\\"ס אסור לגרום טומאה לחולין שבא\\\"י ופי' רש\\\"י ותניא בברייתא דאליבא דר\\\"א ונותנת אף כביצה באמצע ואפ\\\"ה לא מטמא לה לחלק עד שלא נקרא עליה שם סברוה רבנן הני דבי מדרשא דבעו למשמע מינה דר\\\"א אין שני עושה שלישי בחולין ס\\\"ל. אידי ואידי הך ברייתא נמי אליבא דר\\\"א דשרי כביצה ומתניתין דאמרה פחות תרוייהו בעיסה ראשונה העיסה הטמאה ראשונה לטומאה היא ואפילו הכי קאמר ר\\\"א בברייתא כביצה ואע\\\"ג דמטמאת אמצעית מחמת ראשונה והו\\\"ל שנייה לא הדרא ועבדא לה לחלה עד שלא קרא עליה שם שלישי ואע\\\"ג דמעיסת חולין הטבולין לחלה היא עכ\\\"ל. ובפ\\\"ד דע\\\"ז אסיקנא דמותר לגרום טומאה לחולין שבא\\\"י וכן בפ\\\"ק דחולין ובפרק קמא דנדה ורבינו פוסק כר\\\"א ונראה שטעמו מדאמרי' בירושלמי (הלכה ג') ר' טבי וכו' אמר הלכה כר\\\"א רבי יצחק בר נחמן אמר וכו' הלכה כר\\\"א רב הונא אמר אין הלכה כר\\\"א רבי יוסי ברבי בון אמר וכו' אין הלכה כר\\\"א אתא עובדא קמיה ולא אורי אמר תרתי כל קבל תרי אינון אמר ליה והא רבי יצחק בר נחמן אורי אפילו כן לא אורי. ויש לתמוה כיון דתרי ותרי נינהו חזר הדין לפסוק כחכמים דרבים נינהו וכבר השיגו הראב\\\"ד:\",1,0],[8,357,7,12,\"וכתב א\\\"א הוא פסק כר\\\"א וכו'. ואפשר דכיון דרבי יצחק בר נחמן אורי מעשה רב ולא שבקינן מאי דפשיטא ליה לרבי יצחק בר נחמן משום מאי דמספקא ליה לרבי יוסי ברבי בון ועוד דאפילו לרבי יוסי ברבי בון כיון דתרי ותרי נינהו ה\\\"ל ספיקא במידי דרבנן הוא אזלינן לקולא ומהאי טעמא נמי פסק כברייתא דקתני כביצה:\",2,0],[8,357,7,12,\"ומה שכתב הראב\\\"ד מפני שהוא מטמא חלתה פחות מכביצה יש לתמוה דהא תנן פרק ב' דערלה (משנה ד') לעולם אינו מטמא עד שיהא בו כביצה:\",3,0],[8,357,7,13,\"עושה אדם עיסה בטהרה וכו'. משנה ו' פרק ד' דחלה:\",1,0],[8,357,8,1,\"המפריש חלתו קמח וכו'. פרק שני דחלה (משנה ה') המפריש חלתו קמח אינה חלה וגזל ביד כהן העיסה עצמה חייבת בחלה והקמח אם יש בו כשיעור חייב בחלה ואסורה לזרים דברי רבי יהושע אמרו לו מעשה וקפשה זקן זר אמר להם אף הוא קילקל לעצמו ותיקן לאחרים ורבינו שלא כתב אסורה לזרים נראה שפוסק דלא כרבי יהושע ומשמע לי שהטעם משום דס\\\"ל דרבנן דאמרו לו פליגי עליה ופסק כוותייהו דרבים נינהו:\",1,0],[8,357,8,2,\"אימתי מפרישין חלה וכו'. משנה פרק ג' דחלה (משנה א') כיון שהיא נותנת את המים מגבהת חלתה ובלבד שלא יהא שם חמשת רבעים קמח:\",1,0],[8,357,8,2,\"ומ\\\"ש ואם אמר הרי זה חלה וכו'. בירושלמי (הלכה א') אלא שמוסיף שם ועל הקרן שניתן תחתיה ולא ידעתי למה השמיטו רבינו:\",2,0],[8,357,8,2,\"וכתב הראב\\\"ד אימתי מפרישין החלה כשיתן את המים א\\\"א אין יפה לעשות כן וכו'. טעמו שהוא סובר שכוונת רבינו שעיקר המצוה להפריש החלה מכיון שהיא נותנת את המים וע\\\"כ הקשה עליו דא\\\"כ היאך שנינו שמותר לאכול עראי מן העיסה עד שתתגלגל וכתב שמה שאמרו שם בירושלמי כיון שהיא נותנת את המים זו היא ראשית עריסותיכם לא שיעשה כן לכתחלה אלא היינו לומר שאם עשה כן הרי קיים מצות ראשית עריסותיכם שהיא נחשבת עיסה וי\\\"ל שאין דעת רבינו כמו שחשב הראב\\\"ד אלא אין כוונתו לומר שיהא זה עיקר המצוה שיותר טוב להמתין עד אחר גמר לישה ותיעשה הכל גוף אחד אלא כוונתו לומר שאם רצה למהר להפריש חלתה בטהרה שמא תטמא העיסה מכיון שהיא נותנת המים רשאי להפריש וזהו פירוש הירושלמי שאמרו כיון שהיא נותנת את המים זהו ראשית עריסותיכם אבל עיקר חיוב חלה משתתגלגל בחטים ותטמטם בשעורים וזהו מה שכתב בסמוך מאימתי תתחיי' העיסה בחלה משתתגלגל בחטים וזהו ממש דעת הראב\\\"ד וזהו דעת הרשב\\\"א והרא\\\"ש וכתבו דהכי איתא בהדיא בירושלמי פ\\\"ק דביצה (דף פ' ע\\\"ד) ופרק אלו עוברין (דף ל':) דגרסינן התם הלש עיסה ביו\\\"ט מפריש חלתה ביו\\\"ט וכו' אמר רבי שמואל [אחוי דרבי ברכיה תיפתר] בעיסה טמאה שאינו מפריש אלא בסוף אמר רבי יוסי ברבי בון בדין היה בעיסה טהורה שלא יפריש חלתה אלא בסוף תקנה תקנו בה שיפרישנה תחלה שלא תטמא העיסה ואע\\\"ג דגבי מאימתי תתחייב העיסה בחלה כתב רבינו משתתגלגל בחטים ויתערב הקמח במים כמו שכתב גבי אימתי מפרישין חלה ויתערב הקמח במים צ\\\"ל דלא דמי עירוב לעירוב דעירוב דרישא היינו מה שמעורב מעצמו ע\\\"י נתינת המים בלבד ועירוב דסיפא היינו מה שמתערב הקמח עם המים ע\\\"י שמגלגל ומערב בידיו הקמח עם המים:\",3,0],[8,357,8,3,\"הניח העיסה עד שלש הכל וכו'. עד ה\\\"ז מפריש מן הפת:\",1,0],[8,357,8,4,\"מאימתי תתחייב העיסה בחלה וכו'. נתבאר בסמוך:\",1,0],[8,357,8,4,\"ומ\\\"ש ואוכלים עראי מן העיסה עד שתתגלגל בחטים וכו'. משנה רפ\\\"ג דחלה (מ\\\"א) ופירש הערוך דרך החטים ללוש ולגלגל יפה אבל השעורים כשילוש אותן עיסתו מתפרדת ואינו יכול לגלגלן יפה על כן מטמטמו ביד ועוזבו עכ\\\"ל.\",2,0],[8,357,8,4,\"ומ\\\"ש והכוסמין כחטים ושבולת שועל ושיפון כשעורים נראה שהוא נלמד מדאמר במנחות פרק ששי (דף ע') כוסמין מין חטים שיפון ושבולת שועל מין שעורים ומפרש רבינו דאף לענין גלגול וטמטום קאמר והכוסמין אע\\\"ג דמצטרפים אף עם השעורים מ\\\"מ טבע עיסתה לענין גלגול כעיסת חטים:\",3,0],[8,357,8,5,\"נתגלגלה בחטים ונטמטמה בשעורים וכו'. משנה רפ\\\"ג דחלה שם:\",1,0],[8,357,8,6,\"פה יש חסרון הרבה בספרי רבינו מטעות סופר ולכן אעתיק כל מה שחסר ואחר כך אבארנו והילך מה שחסר (ה\\\"ו-הי\\\"ג): עיסה שנדמעה עד שלא תתגלגל פטורה משתתגלגל חייבת וכן המקדיש עיסתו או המפקיר אותה קודם שתתגלגל ופדאה או זכה בה ואח\\\"כ גלגלה או הקדישה או הפקיר אותה אחר שנתגלגלה ופדאה או זכה בה ה\\\"ז חייבת בחלה. הקדישה קודם שתתגלגל ונתגלגלה ביד ההקדש ואחר כך פדאה פטורה שבשעת חובתה היתה פטורה. וכן נכרי שנתן לישראל לעשות לו עיסה ונתנה לו במתנה עד שלא גלגלה חייבת משגלגלה פטורה גר שנתגייר והיתה לו עיסה נתגלגלה עד שלא נתגייר פטורה ואם משנתגייר חייבת ואם ספק חייבת בחלה לפי שהוא עון מיתה וזר שאכל חלת ספק זו וכיוצא בה אין חייב עליה חומש. עיסה שנולד לה ספק טומאה קודם שתתגלגל יעשנה בטומאה לפי שמותר לטמא חולין שבא\\\"י ותשרף חלתה נולד לה אחר שנתגלגלה ספק טומאה שודאה מטמא את החולין מן התורה יגמרנה בטהרה שכל שודאה מטמא את החולין גזרו על ספיקו בחולין הטבולים לחלה שלא יטמאו אותן הואיל ונטבלו לחלה ותהיה החלה הזאת תלויה לא נאכלת ולא נשרפת. לא יעשה אדם עיסתו בטומאה לכתחלה אלא יזהר וישתדל ויטהר הוא וכליו כדי להפריש חלה טהורה היה בינו ובין המים יותר מד' מילין יעשנה בטומאה ויפריש חלה טמאה. אין עושין חלת ע\\\"ה בטהרה אבל עושין עיסת חולין בטהרה כיצד מגבל העיסה זה החבר ומפריש ממנה כדי חלתה ומניחה בכלי גללים או כלי אבנים או כלי אדמה שאין מקבלים טומאה וכשיבא ע\\\"ה נוטל את שתיהן את העיסה ואת החלה ואומרים לו הזהר שמא תגע בחלה שמא תחזור לטבלה ומפני מה התירו לו זה משום כדי חייו של גבל. אשת חבר מרקדת ובוררת עם אשת עם הארץ אבל משתטיל מים לעיסה לא תסייע מפני שהיא עושה עיסתה בטומאה וכן הנחתום שעושה בטומאה לא לשין וכו'. והילך ביאורו:\",1,0],[8,357,8,7,\"עיסה שנדמעה עד שלא תתגלגל פטורה משתתגלגל חייבת. משנה ב' שם:\",1,0],[8,357,8,7,\"וכן המקדיש עיסתו וכו' עד שבשעת חובתה היתה פטורה. משנה ג' שם ובמנחות פ' ר' ישמעאל (מנחות דף ס״ז) יליף מקרא דגלגול הקדש פוטר.\",2,0],[8,357,8,7,\"ומ\\\"ש או הפקיר אותה. נלמד מדין הקדש:\",3,0],[8,357,8,8,\"וכן נכרי שנתן לישראל לעשות לו עיסה וכו'. משנה ה' שם:\",1,0],[8,357,8,9,\"ומ״ש גר שנתגייר והיתה לו עיסה וכו'. משנה שם ואיתא בפ' הזרוע (חולין דף קל״ד):\",1,0],[8,357,8,9,\"ומ\\\"ש ואם ספק חייבת בחלה לפי שהוא עון מיתה וכו'. ג\\\"ז משנה שם בפ\\\"ג דחלה ובירושלמי מפרש טעמא:\",2,0],[8,357,8,10,\"עיסה שנולד לה ספק טומאה וכו'. משנה ב' שם נולד לה ספק טומאה עד שלא גלגלה תיעשה בטומאה משגלגלה תיעשה בטהרה:\",1,0],[8,357,8,10,\"ומ\\\"ש לפי שמותר לטמא חולין שבארץ ישראל וכו' וכן מה שכתב ספק טומאה שודאה מטמא את החולין מן התורה וכו' עד ולא נשרפת. בפרק קמא דנדה (דף ז'):\",2,0],[8,357,8,10,\"וכתב הר\\\"י קורקוס ז\\\"ל שהלשון הכתוב בספרי רבינו שכל שודאו מטמא את החולין גזרו על ספיקו בחולין הטבולין לחלה שלא יטמאו אותם ט\\\"ס הוא וצריך להיות גזרו על ספיקו דחולין הטבולים לחלה שיטמאו אותם והוא ליתן טעם לדין שכתב בסוף דבריו שחלתה תלויה כי להיות ודאו חמור החמירו בספיקו להיות החלה תלויה ואסורה ליאכל משא\\\"כ בטבולת יום שחלתה טהורה לפי שודאה קל לא החמירו בספיקה אפילו בטבולה לחלה כיון דמדינא לאו כחלה דמו ואף ע\\\"פ שלשון רבינו נראה שבא לתת טעם למה שכבר הזכיר דיגמרנה בטהרה א\\\"א שתהיה זו כוונתו מכח הסוגיא דפרק קמא דנדה הנזכר וגם ממקומו הוא מוכרח דאדרבה כל הטומאה יותר קלה ראוי לומר בספיקה יגמור בטהרה שכיון שמן התורה אין כאן טומאה איך יגמרנה בטומאה אלא ודאי מה שהצריכו ספק שודאו מטמא את החולין להיות חלתה טהורה הוא שהצריכו כן ועל סוף הלשון סמך רבינו עכ\\\"ל:\",3,0],[8,357,8,11,\"לא יעשה אדם עיסתו בטומאה וכו'. נלמד ממה שיבא בסמוך:\",1,0],[8,357,8,11,\"היה בינו ובין המים יותר על ד' מילין וכו'. בירושלמי פ״ב (הלכה ב') ובפרק העור והרוטב (חולין דף קכ״ב) לגבל ולתפלה ולנט״י ד' מילין ודברי רבינו כפירוש רש״י דמ״ש ל״ש אלא לפניו וכו' לא קאי אלא לתפלה ולנ״י ולא לגבל וכן נראה מהירושלמי שכתבתי שלא חילק בכך:\",2,0],[8,357,8,12,\"אין עושין חלת ע״ה בטהרה וכו' עד משום כדי חייו של גבל. בסוף פרק הניזקין (גיטין דף ס״ב):\",1,0],[8,357,8,13,\"אשת חבר מרקדת וכו'. משנה בסוף פרק הניזקין (גיטין דף ס״א) ובסוף פרק ה' דשביעית (משנה ט'):\",1,0],[8,357,8,13,\"וכן הנחתום שעושה בטומאה וכו'. משנה בע\\\"ז פ' רבי ישמעאל (נ\\\"ה):\",2,0],[8,357,8,14,\"הלוקח מנחתום ע\\\"ה בסוריא וכו'. ירושלמי פ\\\"ד דחלה (ה\\\"ד):\",1,0],[8,357,8,15,\"הלוקח בח\\\"ל מן הנחתום וכו' עד סוף הפרק. גם זה ירושלמי שם:\",1,0],[8,357,8,15,\"כתב הראב\\\"ד ואין צ\\\"ל המתארח אצלו א\\\"א מהגמרא נראה וכו'. ואני אומר דבנוסחא דידן בירושלמי פ\\\"ד דחלה כתוב כדברי רבינו דלא שרי במתארח אלא אצל בע\\\"ה אלא דמסיים בה רבי יונה בשם ר' חנניה חברין דרבנין במתארח אצלו לעיסתו אמר רבי יונה והן שראו אותו מגבל אצל אחר וצריך טעם למה השמיטה רבינו ואפשר לומר שסובר רבינו שדברי יחיד הם ולית הלכתא כוותיה:\",2,0],[8,357,9,1,\"מצות עשה ליתן כל זובח בהמה טהורה וכו' עד אבל לא במוקדשים. בר״פ הזרוע (חולין דף ק״ל):\",1,0],[8,357,9,2,\"כל הקדשים שקדם מום קבוע וכו'. משנה שם ובפ\\\"ב דבכורות (דף י\\\"ד):\",1,0],[8,357,9,3,\"ספק בכור חייב במתנות וכו' עד שהמוציא מחבירו עליו הראיה. בפרק ב' דבכורות (דף י״ח:). ובענין נסתפק בשנים ולקח הכהן מספק וכו' פסק כרבי יוסי לגבי ר״מ ועוד דבפ״ק דמציעא (דף י״ב:) פסק שמואל כרבי יוסי דאמר עשו את שאינו זוכה כזוכה ואע״ג דבפרק כל הגט (גיטין דף ל') אמר עולא מתניתין כרבי יוסי ואמוראי פליגי ואמרו כולהו כעולא לא אמרי כיחידאה לא מוקמינן איכא למימר דלאו דסבירא ליה דלית הלכתא כוותיה אלא דמ״מ רצו להעמיד סתם מתניתין כרבים ועי״ל דיש לחלק בין ההיא דפרק כל הגט לההיא דפ״ב דבכורות וההיא דפרק קמא דמציעא:\",1,0],[8,357,9,4,\"בהמת קדשים שנפסלה במומה וכו'. בפרק הזרוע (חולין דף קל״ב) תנן בכור שנתערב במאה בזמן שמאה שוחטים את כולם פוטרים את כולם אחד שוחט את כולם פוטרים לו אחד ובגמרא ואמאי יבא עליו כהן משני צדדין וכו' אמר רב אושעיא בבא לידי כהן ומוכרו לישראל במומו:\",1,0],[8,357,9,5,\"אין חייב במתנות וכו'. פשוט הוא ולא נכתב אלא להיות הצעה לדינים הבאים אחריו:\",1,0],[8,357,9,5,\"כלאים הבא מכבש ועז חייב במתנות. בפ' הזרוע בברייתא ודריש לה מיתורא דאם:\",2,0],[8,357,9,5,\"ומ״ש וכוי אע״פ שהוא ספק וכו'. בפרק הזרוע ת״ר הזרוע והלחיים והקיבה נוהגים בכלאים ובכוי רבי אליעזר אומר כלאים הבא מן העז ומן הרחל חייב במתנות (מן התייש ומן הצביה) פטור מהמתנות מכדי קי״ל דלענין (כסוי הדם) מתנות לא משכחת לה אלא בצבי הבא על התיישה ובין לרבי אליעזר בין לרבנן מספקא להו אי חוששין לזרע האב ובשה ואפי' מקצת שה קא מיפלגי וכו' בשלמא לרבי אליעזר וכו' אלא לרבנן נהי נמי דקסברי שה ואפילו מקצת שה פלגא לישקול ואידך פלגא לימא ליה אייתי ראיה דאין חוששין לזרע האב ושקול אמר רב הונא בר חייא מאי חייב נמי דקאמר בחצי מתנות. הא דאמר מכדי קי״ל דלענין מתנות לא משכחת לה אלא בצבי הבא על התיישה וכו' פירוש דבפרק אותו ואת בנו (חולין דף ע״ט:) מקיש אהאי ברייתא במאי עסקינן אילימא בתיש הבא על הצבייה וילדה בשלמא לר״א וכו' אלא לרבנן נהי דסברי שה ואפילו מקצת שה פלגא לא יהיב ליה אידך פלגא לימא ליה אייתי ראיה דחוששין לזרע האב ושקול ואסיקנא דלא משכחת להאי פלוגתא דרבנן ור״א אלא בצבי הבא על התיישה וכו' ובפ' הזרוע (חולין דף קל״ב) אמרינן בתר הכי כי אתא רבין א״ר יוחנן כוי לרבנן חייב בכולהו מתנות דתניא שה מה ת״ל אם שה לרבות את הכוי. וכתב הר״ן פירש״י דאע״ג דמספקא לן אי חוששין לזרע האב להכי אהני רבוייא דאפילו לית ביה אלא מקצת שה חייב אף בחצי האחר דבלאו רבוייא הוא מיחייב בפלגא דשה ואפילו מקצת שה משמע ואהני רבוייא דאם לאידך פלגא והאי פירושא לא נ״ל דכיון דאיצטריך רבויא ניפשוט מינה דחוששין לזרע האב דאי אין חוששין אמאי איצטריך קרא לרבויי ובר״פ בתרא דיומא (דף ע״ד) נמי אמרינן גבי הא דתניא כוי וחצי שיעור הואיל ואינו בעונש אינו באזהרה ת״ל כל חלב ומוכחינן מינה דכוי בריה בפני עצמה היא דאי ספיקא וכי איצטריך קרא לרבויי ספיקא לפיכך נ״ל דרבין ורבי יוחנן דאסיק דכוי לרבנן חייב בכולהו מתנות לאו בצבי הבא על התיישה מוקי לה אלא ס״ל דכוי בריה בפני עצמה ורבייה קרא לשוויי כבהמה ומיהו מודה לרב הונא בר חייא דכוי הבא מן הצבי ומן התיישה אינו חייב אלא בחצי מתנות ומדברי הרמב״ם למדתי שכך כתב בפ״ט מהלכות בכורים הכוי אע״פ שהוא ספק מפרישין ממנו כל המתנות צבי הבא על העז וילדה חייב בחצי מתנות אם שה אפילו מקצת שה ע״כ אבל אינו נראה כן מסוגיית אותו ואת בנו עכ״ל הר״ן. ונראה דהיינו מדתניא בפרק אותו ואת בנו (חולין דף ע״ט:) כלאים הבא מן העז ומן הרחל אותו ואת בנו נוהג בו כוי אין אותו ואת בנו נוהג בו אמר רב חסדא איזהו כוי שנחלקו בו רבי אליעזר וחכמים הבא מן התייש ומן הצביה וכו' דמשמע בהדיא דכוי לאו בריה בפני עצמו הוא אלא הבא מן הבהמה ומן החיה הוא:\",3,0],[8,357,9,5,\"והטור כתב על דברי רבינו איני מבין דבריו למה מפרישים כל המתנות כיון שאינו חייב ליתנם והלא אינם טובלים ע\\\"כ טעמו שהבין בדברי רבינו שדעתו לומר דכוי היינו הבא מן הבהמה ומן החיה וקאמר דמפרישים ממנו כל המתנות ולא יתנם כולם לכהן דבצבי הבא על העז יתן החצי ובתייש הבא על הצבייה לא יתן כלום והוקשה לו אם אינו נותנם למה הוצרך להפרישם ועוד יש לתמוה על רבינו דמנא ליה הא דרבי יוחנן חייב בכל קאמר משמע דחייב ליתנם כולם לכהן ועוד דמשמע דמייתי לה גמרא לומר דליתא לדרב הונא דאמר מאי חייב דאמרי רבנן חייב בחצי מתנות דהא רבי יוחנן אמר דחייב בכולהו מתנות:\",4,0],[8,357,9,5,\"וליישב דברי רבינו נראה דודאי סבר דכוי בריה בפני עצמה היא כמו שכתב הר\\\"ן וכרבי יוסי בפרק אותו ואת בנו וכרב יהודה דאמר התם הכי ורב חסדא דאמר בפרק אותו ואת בנו איזהו כוי שנחלקו בו רבי אליעזר וחכמים הבא מן התייש ומן הצבייה סבר דכוי זה הבא מן הבהמה ומן החיה וכמ\\\"ד התם הכי ולא קי\\\"ל כוותיה:\",5,0],[8,357,9,5,\"ועי\\\"ל דלא גריס רבינו בברייתא דפרק אותו ואת בנו כדברי ר\\\"א כוי אין אותו ואת בנו נוהג בו אלא הכי גריס מן התייש ומן הצביה אין אותו ואת בנו נוהג בו וכמו שהיא שנויה בפרק הזרוע גבי מתנות דהשתא ע\\\"כ ל\\\"ג בדברי רב חסדא איזהו כוי דר\\\"א לא איפליג אלא אכלאים ולא אכוי ואע\\\"ג דרש\\\"י דחה גירסא זו בברייתא משום דא\\\"כ מאי אתא רב חסדא לאשמועינן י\\\"ל דטובא אשמעינן דלא נימא דהא דאמר ר\\\"א הבא מן התייש ומן הצביה לאו דוקא דהוא הדין לבא מן הצבי ומן התיישה ולא אתא אלא לאפוקי מן העז ומן הרחל וכדאמר רב פפא לענין אותו ואת בנו משכחת לה לפלוגתייהו דרבנן ורבי אליעזר בין בתייש הבא על הצביה בין בצבי הבא על התיישה קמ\\\"ל וכן מתבאר מדברי רבינו בכסוי הדם דכוי בריה בפני עצמה היא.\",6,0],[8,357,9,5,\"ומ\\\"ש הכוי מפרישין ממנו כל המתנות היינו לומר שמפרישים ונותנם לכהן כולם שאע\\\"פ שהוא ספק נתרבה מאם וכדרבין אמר רבי יוחנן ובצבי הבא על העז פסק דחייב בחצי מתנות כרבנן דאמרי חייב וכדאסיק רב הונא בר חייא ובתייש הבא על הצביה ליכא לאוקמי דאם כן לרבנן נמי ליפטר דנהי נמי דאפילו מקצת שה אמרינן מאן לימא לן דאיכא מקצת שה דילמא אין חוששין לזרע האב וכוליה צבי הוא והמע\\\"ה ואל יקשה על מה שכתבתי שרבינו סובר דכוי בריה בפני עצמה היא ממה שכתב בפ\\\"א ממאכלות אסורות כלאים הבא מבהמה טהורה עם חיה טהורה הוא הנקרא כוי חלבו אסור וכו' שזו נוסחא משובשת ובנוסחא האמיתית אין כתוב בבא זו הוא הנקרא כוי אלא בבבא למעלה ממנה כתוב וכל שיסתפק לך אם הוא מין חיה או בהמה והוא הנקרא כוי חלבו אסור:\",7,0],[8,357,9,6,\"אחד השוחט לאכילת עכו\\\"ם וכו'. כתב הראב\\\"ד פירוש דילפינן מכיסוי הדם וכו'. ואין צורך ללמוד משם דתוספתא ערוכה היא בפרק תשיעי דחולין השוחט לרפואה לאכילת עכו\\\"ם לאכילת כלבים חייב במתנות:\",1,0],[8,357,9,7,\"בהמת השותפים חייבת וכו'. בר״פ ראשית הגז (חולין דף קל״ה) וכת״ק:\",1,0],[8,357,9,9,\"הלוקח בהמה מפירות שביעית וכו'. פ\\\"ק דבכורות (דף י\\\"ב).\",1,0],[8,357,9,9,\"כהנים ולויים פטורים וכו'. וספק הם הלוים וכו' עד מנדין אותו עד שיתן. בפרק הזרוע (חולין דף קל״ב):\",2,0],[8,357,9,9,\"ומ\\\"ש רבינו ואם נטל הכהן לא יחזיר תמה עליו הר\\\"ן דמאי שנא מספק בכור שאם תקפו כהן מוציאין מידו כדאמרי' בפ\\\"ק דמציעא (דף ו':) וי\\\"ל דאין כאן תמיהא שרבינו סובר ג\\\"כ בההיא שאם תקפו כהן אין מוציאין מידו שכן כתב בפרק ה' מהלכות בכורות ושם ביארתי טעמו:\",3,0],[8,357,9,10,\"השוחט לעכו״ם ולכהן וכו'. הטור כתב על דברי רבינו ואינו נראה כן מתוך הגמרא אלא בשותף עם הכהן בכל ענין צריך לרשום ובעכו״ם אם יושב עמו במטבחיים אז אין צריך לרשום עכ״ל. ואמת כן משמע פשט השמועה דהכי איתא בפרק הזרוע (חולין דף קל״ג) על מתניתין דהמשתתף עמהם צריך שירשום ואפילו עם העכו״ם ורמינהו המשתתף עם כהן צריך לרשום והמשתתף עם העכו״ם וכו' אין צריך לרשום הב״ע דיתיב עכו״ם אמסחתא דכוותא גבי כהן דיתיב אמסחתא אמאי צריך לרשום דאמרי בישרא קא זבין אי הכי עכו״ם נמי אמרי בישרא קא זבין אלא הב״ע דיתיב אכספתא דכוותא גבי כהן דיתיב אכספתא אמאי צריך לרשום אמרי הימוני הימניה עכו״ם נמי אמרי הימוני הימניה אין אמונה בעכו״ם איבעית אימא סתם עכו״ם מיפעא פעי ופירש״י דיתיב עכו״ם אמסחתא כשהטבח מוכר הבשר דמוכחא מילתא דעכו״ם שותף הוא וכו'. דיתיב עכו״ם אכספתא על הארגז שנותן בה הטבח המעות כשמקבלם תמיד מהלוקחים דהא ודאי מוכחא מילתא שפיר דעכו״ם שותף בה. דאמרי הרואים הימוני הימניה לשמרם לו שלא יגנבום הימנו. אין אמונה בעכו״ם אין ישראל רגילים להאמין בהם איבעית אימא לעולם כדאוקימנא מעיקרא דיתיב עכו״ם אמסחתא וכהן נמי דיתיב אמסחתא ולא דמו דסתם עכו״ם מיפעא פעי תדיר הוא צועק אל תתנם בכך אלא בכך והכל יודעים שיש לו חלק בה אבל כהן צנוע הוא וסומך על הטבח ואין הכל יודעים שהוא שותף וזה מבואר כדברי הטור. וליישב דברי רבינו צ״ל שהוא ז״ל סובר דכי אמרינן ואב״א עכו״ם מיפעא פעי לא בדיתיב אמסחתא היא אלא אע״ג דלא יתיב אמסחתא עכו״ם מיפעא פעי אפילו חוץ למטבחי' ומודיע לכל שהוא שותף ומש״ה תניא דהמשתתף עם העכו״ם אינו צריך לרשום ומתניתין דקתני המשתתף עמהם צריך לרשום אכהן דוקא קאי ולא אעכו״ם ומאי עמהם עם כהנים דעלמא וה״מ בדלא יתיב אמסחתא או אכספתא אבל אי יתיב אמסחתא או אכספתא אין צריך לרשום דמוכחא מילתא שהוא שותף וז״ש ונושא ונותן עמו דיתיב אכספתא נמי בכלל נושא ונותן שהרי הוא מקבל ממנו המעות שקיבל מהלוקחים דאל״כ איכא למיתמה על רבינו דנהי דפסק כלישנא דאי בעית אימא משום דבתרא היא אמאי פסק לענין משתתף עם כהן כלישנא דמסחתא דקמא הוא לכך אני אומר שפסק כדברי שניהם דס״ל לרבינו דלענין דינא לא פליגי לישני:\",1,0],[8,357,9,10,\"ואהא דתנן צריך שירשום פירש\\\"י שיעשה בו סימן שיבינו הרואים שאינו כולו של ישראל והר\\\"ן כתב ישראל המשתתף עמהם שוחטים ומקבלים ביניהם פטור מהמתנות אפילו חלקו של ישראל ומיהו צריך שירשום ויעשה לו סימן כמו שהיו רגילים לרשום בשר שפטור מהמתנות וכדי שיבינו הרואים שאין כולם של ישראל ולא יחשדוהו ברשע. והרמב\\\"ם כתב בפ\\\"ט מהלכות בכורים המשתתף עם הכהן צריך שירשום חלקו כדי שיניח המתנות בחלק הכהן שאם לא סיים חלקו חייב במתנות מפני שאין הכל יודעים שהכהן שותף בו וכו' ואיכא למידק [וחלקו] של ישראל אמאי פטור והא אמרינן בגמרא דכוי הבא מצבי שבא על התיישה דלרבנן חייב בחצי מתנות משום דשה אפילו מקצת שה משמע וה\\\"נ נהי דחלקו של כהן פטור חלקו של ישראל מיהא ליחייב איכא למימר דלא דמי דנהי דאמרינן דשה ואפילו מקצת שה ה\\\"מ דכל שיות שבו חייב דבכה\\\"ג כוליה שה מיקרי אבל הכא דמקצת שיות פטור כה\\\"ג לא חייב רחמנא עכ\\\"ל. ודע שיש בקצת ספרי רבינו חסרון וכך צריך להגיה והמשתתף עם העכו\\\"ם אינו צריך לרשום:\",2,0],[8,357,9,11,\"התנה הכהן עמו וכו'. בסוף המשנה הנזכרת ואם אמר [לו] חוץ מן המתנות פטור מן המתנות ומפרשה רבינו כשהכהן שותף עמו חוץ מן המתנות ורש\\\"י פירשה בשמכר לו הכהן פרה חוץ מן המתנות. בספר כתיבת יד כתוב בדברי רבינו התנה הכהן עמו שהוא מוכר הכל חוץ מן המתנות.\",1,0],[8,357,9,11,\"ומ\\\"ש אבל אם אמר לו הכהן ע\\\"מ שהמתנות שלי וכו'. שם:\",2,0],[8,357,9,12,\"היה הכהן שותף בראש וכו'. שם.\",1,0],[8,357,9,12,\"ומ\\\"ש אמר לו הכהן הרי הבהמה כולה שלי וכו'. שם בעיא דאיפשיטא (דף קל\\\"ד):\",2,0],[8,357,9,14,\"בהמה שלא הורמו מתנותיה וכו'. מסקנא דגמרא שם (דף קל\\\"ב:):\",1,0],[8,357,9,14,\"ומה שכתב והמתנות עצמן אסור לישראל לאכלן וכו' עבר ואכלן וכו'. שם (דף ק\\\"ל:) אמר רב חסדא המזיק מתנות כהונה או שאכלן פטור מלשלם מאי טעמא איבעית אימא משום דכתיב וזה איבעית אימא משום דהוה ליה ממון שאין לו תובעים ופירש רש\\\"י המזיק מתנות כהונה קודם שיתנם לכהן השליכן לאור או לים. דכתיב בהן וזה דמשמע בעודם קיימות חייב ליתנם אבל אינם קיימות לא חייב הכתוב בהם תשלומין. שאין לו תובעים אין לו בעלים שיוכלו לתבעו בדין שזה יכול לומר לכהן אחר אני נותנם ולא לך. והר\\\"ן כתב על פירוש רש\\\"י ותמהני אם כן מאי איריא [הזיק] אפילו איתנהו בעינייהו נמי אין להם תובעים ומשמע לי דה\\\"ק כיון דמתנות כהונה ממון שאין לו תובעים הוא נהי דכי איתנהו בעינייהו מיחייב משום מצוה כי ליתנהו בעינייהו אין כאן מצוה ולא דין ממון הילכך פטור לגמרי לפיכך נ\\\"ל דאפילו בבא לצאת ידי שמים פטור ולא נתחוור לי מה שכתבו התוספות דאיכא בין לישנא קמא ללישנא בתרא דלמאן דמפיק לה מדכתיב וזה אפילו בבא לצאת ידי שמים פטור וללישנא בתרא כיון דלא פטר ליה אלא משום דהוי ממון שאין לו תובעים בבא לצאת ידי שמים חייב ולא ידעתי למה דהנהו גווני דאמרינן בהו בפרק הגוזל ובפרק המפקיד בספק ממון דחייב בדיני שמים לא דמי להאי כלל דהכא אי לא מיחייב משום מצוה משום מאי מיחייב ומיהו ודאי לתרתי לישני מדת חסידות שישלם מדמייתי עלה בגמרא ת\\\"ש בע\\\"ה העובר ממקום למקום וצריך כלומר שנצטרך למזונות נוטל לקט שכחה ופאה ומעשר עני וכו' מכל מקום משמע דלכולהו לישני אפילו בבא לצאת ידי שמים פטור ואין בזה אלא מדת חסידות בלבד עכ\\\"ל. ורבינו\",2,0],[8,357,9,14,\"כתב אינו חייב לשלם מפני שאין לו תובע ידוע משמע דס\\\"ל כדברי התוספות ופסק כלישנא בתרא לחומרא דאם לא כן אמאי שבקיה ללישנא קמא דיהיב טעמא מקרא ותו איכא למידק הכי מדשני לישנא דרב חסדא דאמר פטור וכתב אינו חייב דמשמע אין בית דין מחייבין אותו ומדנקט גבי אכלן עבר משמע דלכתחלה מיהא אסור לאכלן:\",3,0],[8,357,9,14,\"ומה שכתב והקונה אותם וכו'. יתבאר בסמוך:\",4,0],[8,357,9,15,\"אמר לטבח וכו'. בקצת ספרי רבינו יש טעות סופר והכי גרסינן אמר לטבח מסור לי בני מעיה של פרה והיו בהם מתנות נותנם לכהן ואינו מנכה הטבח לו מן הדמים לקחם ממנו במשקל נותנם לכהן ומנכה הטבח לו מן הדמים והוא משנה שם (דף קל\\\"ב) אמר [לו] מכור לי בני מעיה של פרה זו והיו בהם מתנות נותנם לכהן ואין מנכה לו מהדמים לקחן הימנו במשקל נותנן לכהן ומנכה לו מן הדמים ופירש\\\"י נותנם לוקח זה לכהן ואין המוכר מנכה ללוקח מהדמים שהרי היה יודע הלוקח שהמתנות שם וזה לא מכר לו הקיבה. לקח ממנו במשקל הליטרא כך וכך ושקל לו הקיבה נותנם לו לוקח לכהן שהרי הגזילה אצלו וצריך להשיב והטבח ינכה לו מהדמים ע\\\"כ שמכר דבר שאינו שלו ובגמרא (דף קל\\\"ד) אמר רב לא שנו אלא ששקל לעצמו אבל שקל לו טבח הדין עם הטבח ורב אסי אמר אפילו שקל לו טבח הדין עמו לימא בדרב חסדא קמיפלגי דאמר רב חסדא גזל ולא נתייאשו הבעלים ובא אחר ואכלו רצה מזה גובה רצה מזה גובה וכו' לא דכ\\\"ע אית להו דרב חסדא והכא במתנות כהונה נגזלות קמיפלגי ופירש\\\"י לא שנו היכא דלקח ממנו במשקל דקתני נותנם לוקח לכהן והוא חוזר ותובע דמים מן הטבח אלא בששקלן לוקח לעצמו דכיון דטבח לא נגע בהן אינו בעל דינו של כהן לפיכך זה לוקח נותנם והוא שואל לו הדמים שעל הטבח היה מוטל אבל שקלן לו הטבח הדין של כהן ומחלוקתו ותביעתו אף עם הטבח והטבח חוזר עליהם אם יש בעין נותנם לכהן והכי מפרש בריש הגוזל דאף עם הטבח קאמר עכ\\\"ל. ופסקו הפוסקים כרב משום דרבו הוא וכתב הר\\\"ן על דברי רבינו שנראה מדבריו שהוא מפרש אמר רב לא שנו דחייב הלוקח ליתן לכהן אלא ששקל לעצמו אבל לא שקל לעצמו רשאי הלוקח לאכלן שהראשון הוא שגזלן והלוקח מותר לאכלן מפני שמתנות כהונה נגזלות ע\\\"כ. ומ\\\"מ יש לתמוה על רבינו למה השמיט חילוק בין שקל לעצמו ללא שקל לעצמו כמו שחילק רב וי\\\"ל משום דאמרינן בגמרא איכא דמתני לה באפי נפשה רב אמר מתנות כהונה נגזלות ורב אסי אמר אין נגזלות ולההוא לישנא לא מפלגינן בין שקל לעצמו ללא שקל לעצמו ופסק כההוא לישנא משום דלישנא בתרא הוא וגם משום דלההיא לישנא אתיא מתניתין כפשטה:\",1,0],[8,357,9,16,\"המשלח בשר לחבירו וכו'. תוספתא פ' הזרוע המשלח בשר לחבירו והיו בו מתנות אין חוששין שמא מתנות כהונה הם פירוש אינו חושש שמא גזל אותם המשלח אלא תולה שמהכהן קנאם דאחזוקי אינשי ברשיעי לא מחזקינן:\",1,0],[8,357,9,16,\"מקום שאין בו כהן. בס״פ הזרוע (חולין דף קל״ב):\",2,0],[8,357,9,17,\"הרוצה ליתן המתנות לכהן אחד וכו' ואם היו של שור וכו'. שם (דף קל\\\"ב:):\",1,0],[8,357,9,18,\"איזהו הזרוע וכו' עד פיקה של גרגרת. משנה שם (דף קל\\\"ד:):\",1,0],[8,357,9,18,\"ומ\\\"ש עם הלשון שביניהם. כן פירש\\\"י שם:\",2,0],[8,357,9,19,\"אין מולגין אותן וכו'. שם הלחיים למאי אתא להביא צמר שבראשי כבשים ושיער שבזקן תיישים.\",1,0],[8,357,9,19,\"ומ\\\"ש והקיבה בחלב שעליה וכו' עד לבעלים. גם זה שם:\",2,0],[8,357,9,20,\"הכהנת אוכלת המתנות וכו' עד בגלל אשתו. שם (דף קל\\\"א):\",1,0],[8,357,9,20,\"ומה שכתב אבל חללה וכו': ואם רצה הכהן למכור המתנות וכו'. אפילו לעכו\\\"ם או להאכילה לכלבים:\",2,0],[8,357,9,21,\"כהן שהיו לו חברים וכו'. בפרק הזרוע (חולין דף קל״ג) האי כהנא דאית ליה צורבא מדרבנן בשבבותיה ודחיקא ליה מילתא ליזכי ליה מתנתא ואע״ג דלא אתי לידיה במכרי כהונה ולויה ונראה שסובר רבינו דצורבא דרבנן לאו דוקא אלא אורחא דמילתא נקט ומיהו דחיקא ליה שעתא בעינן כדאיתא התם כי אמרי אנא למאן דלא אפשר ליה.\",1,0],[8,357,9,21,\"ומ\\\"ש אבל היה הכהן שמשו וכו'. שם גבי עובדא דרבא:\",2,0],[8,357,9,22,\"לא יחטוף הכהן וכו' עד סוף הפרק. שם וכתבו התוספות שאם ערב להם מבושל יותר מצלי אין לכפותו לאכול צלי כי דרך המלכים לאכול מה שערב להם יותר:\",1,0],[8,357,10,1,\"מצות עשה ליתן לכהן ראשית הגז וכו' ולוים בכלל ישראל במצוה זו. כלומר אע\\\"ג דבזרוע לחיים וקיבה לוים פטורים בראשית הגז חייבים וטעמא משום דהתם לא נפטרו לוים אלא משום דכתיב מאת העם ומספקא לן דילמא לוים לא הוו בכלל עם אבל בראשית הגז דלא אידכר ביה עם לא באו לכלל ספק:\",1,0],[8,357,10,1,\"ואין לראשית הגז שיעור מן התורה ומד״ס שלא יפחות מס' וכו'. בפרק ראשית הגז (חולין דף קל״ז:) אמרינן דראשית הגז בס' ומשמע התם דהיינו מדרבנן דאילו מדאוריית' בכל שהוא דומיא דתרומה דמייתי התם:\",2,0],[8,357,10,1,\"ואינה נוהגת אלא בארץ. אע״ג דתנן בפרק ראשית הגז (חולין דף קל״ה) דנוהג בארץ ובחו״ל הא אמר רב נחמן התם (דף קל״ו:) נהוג עלמא כתלתא סבי וחד מינייהו ר' אלעאי דאמר ראשית הגז אינו נוהג אלא בארץ:\",3,0],[8,357,10,1,\"ומה שכתב בין בפני הבית וכו' אבל לא במוקדשין. שם במשנה:\",4,0],[8,357,10,2,\"ומ\\\"ש כיצד הרי שהקדיש בהמות וכו' או הקדיש בהמה וכו'. שם בגמרא אבל לא במוקדשין מאי טעמא לא אמר קרא [גז] צאנך ולא צאן הקדש והקשו על זה טעמא דכתב רחמנא גז צאנך הא לאו הכי ה\\\"א קדשים חייבים בראשית הגז וכו' עד יצא זה שמחוסר גזיזה פדייה ונתינה. והר\\\"י קורקוס ז\\\"ל תמה על רבינו שכתב הרי שהקדיש בהמתו לבדק הבית וגזזה וכו' שהרי אוקימתא זו נדחית משום דלא אתיא אלא למ\\\"ד קדשי בדק הבית לא בעו העמדה והערכה ואילו רבינו פסק בפרק חמישי מהלכות ערכין דבעו העמדה והערכה וע\\\"ק שכתב אוקימתא דרב מני דאמר חוץ מגיזה דלא מיתרצא אלא בדאמר חוץ מגיזה וכחישה ולמה השמיט רבינו כחישה וע\\\"ק למה השמיט רבינו אוקימתא דרב והאריך ונדחק מאד ביישוב תמיהות אלו. ולי אין כאן תמיהא כלל דרבינו לא נחת הכא לענין דינא כלל אלא לומר דמשכחת לה דאיצטריך קרא דצאנך למעוטי מוקדשין או כגוונא קמא למ\\\"ד קדשי בדק הבית לא בעו העמדה והערכה או כדאמר חוץ מגיזתה בענין שיועיל ולא חש להביא אוקימתא דרב דכיון דאייתי תרי גווני דאיצטריך קרא סגי:\",1,0],[8,357,10,3,\"כל הקדשים וכו' פטורים מראשית הגז. משנה שם (דף ק\\\"ל) ופרק ב' דבכורות (דף י\\\"ד):\",1,0],[8,357,10,4,\"אין חייבין בראשית הגז אלא הכבשים בלבד. משנה פרק ראשית הגז (חולין דף קל״ה) ויליף לה בגמרא (דף קל״ז) מדכתיב לעמוד לשרת כלומר וראשית גז צאנך תתן לו כי בו בחר לעמוד לשרת שיתן לו דבר הראוי לשירות ואין דבר הראוי לשירות אלא של רחלים פי' דהיינו תכלת דכתב קרא בבגדי כהונה וכתב הר״י קורקוס ז״ל ונראה שלזה נתכוון רבינו במ״ש שהצמר שלהם הוא הראוי לבגדים ופירושו לבגדים שהכהן רגיל ללבוש דהיינו בגדי כהונה שאם כוונת רבינו לבגדים סתם הלא נוצה של עזים ראוי לבגדים.\",1,0],[8,357,10,4,\"ומ\\\"ש זכרים כנקבות ג\\\"ז שם במשנה מכר לו זכרים אבל לא נקבות זה נותן לעצמו וזה נותן לעצמו.\",2,0],[8,357,10,4,\"ומ\\\"ש היה צמרן קשה וכו' שם תנא דבי רבי ישמעאל (דף קל\\\"ו):\",3,0],[8,357,10,6,\"היה הצמר שלהן אדום וכו'. הכי משמע שם במשנה.\",1,0],[8,357,10,6,\"ומ\\\"ש אבל אם גזז הצמר וצבעו וכו' עד אחר שלבנו. משנה שם:\",2,0],[8,357,10,6,\"התולש צמר רחלים בידו וכו'. שם פלוגתא דרבי יוסי ורבנן ופסק כרבנן ומה שקשה על זה ממה שפסק בפ\\\"ב ממתנות עניים נתבאר שם:\",3,0],[8,357,10,7,\"ראשית הגז נוהג בכלאים ובכוי. תוספתא פ\\\"י דחולין:\",1,0],[8,357,10,7,\"כתב הראב\\\"ד נ\\\"ל לענין ראשית הגז וכו'.\",2,0],[8,357,10,7,\"ומ״ש ובטרפה בפרק ראשית הגז (חולין דף קל״ו:) פריך וליתני חומר בראשית הגז שנוהג בטריפות מה שאין כן במתנות אמר רבינא הא מני רבי שמעון היא דתניא ר״ש פוטר את הטריפות מראשית הגז מ״ט דר״ש וכו' ומסקינן דיליף צאן צאן ממעשר וכתב הר״ן וכיון דשקלינן וטרינן טובא עליה דר״ש ומתניתין אתיא כוותיה היה ראוי לפסוק כמותו והרי״ף שהביא משנתנו כצורתה דאתיא כר״ש לפום מאי דאמרינן בגמרא משמע דהכי ס״ל אלא שראיתי להרמב״ם שכתב ראשית הגז נוהג בטרפה ולא ידעתי למה דכיון דמתני' אתיא כר״ש אפילו פליגי רבנן עליה בברייתא היה ראוי לפסוק כסתם משנתנו אבל אפשר שהוא סובר דרבינא דאמר הא מני ר״ש היא לאו למימרא דס״ל דתנא דמתניתין נקיט כר״ש אלא הכי קאמר משום דפלוגתא דר״ש ורבנן היא לא תנא ליה לפי שלא רצה להכניס עצמו במחלוקת וכיון דמתניתין לא מוכחא בהא מידי ודאמרינן מני ר״ש היא מוכח דרבנן פליגי עליה נקטינן ככללין דיחיד ורבים הלכה כרבים ובפ' יוצא דופן נמי משמע דגמרא הכי ס״ל דטרפה חייבת בראשית הגז דאמרינן עלה דמתניתין דתנן כל שחייב במעשרות מיטמא טומאת אוכלים אע״ג דאיכא מידי שחייב במעשרות ואינו מיטמא טומאת אוכלים דהיינו הפרט ולא המין ואמרינן עלה הנ״מ דקתני סיפא כל שחייב בראשית הגז חייב במתנות ואם איתא כלומר דכל קתני ולא מין דוקא הא איכא טרפה דחייבת בראשית הגז ואינה חייבת במתנות דאע״ג דרבינא דחי התם ואמר ר״ש היא דתנן ר״ש פוטר את הטריפה מראשית הגז כדקאמר הכא אפילו הכי משמע דגמרא הכי ס״ל דטריפה חייבת בראשית הגז וההיא דרבינא דהתם דחייה בעלמא היא דמסקנא הכי סלקא התם דמין קתני זה נראה לי בטעמו של הרמב״ם ז״ל עכ״ל:\",3,0],[8,357,10,7,\"אבל הגוזז את המתה פטור. תוספתא ר\\\"פ ראשית הגז וטעמא משום דלא גז מיקרי ולא צאן מיקרי:\",4,0],[8,357,10,8,\"המפריש ראשית הגז ואבד וכו'. תוספתא פרק ראשית הגז וטעמא משום דכתיב ביה נתינה לא מיפטר עד שיתן לו:\",1,0],[8,357,10,8,\"האומר כל גיזותי ראשית דבריו קיימים. בפ' ראשית הגז (חולין דף קל״ז) אמרינן דלרבי אלעאי ראשית הגז אינו נוהג אלא בארץ משום דיליף נתינה נתינה מתרומה וכו' אי מה תרומה בעינן ראשית ששיריה ניכרים אף ראשית הגז כן אין והתניא האומר כל גרני תרומה וכל עיסתי חלה לא אמר כלום הא כל גיזי ראשית דבריו קיימים ותניא אידך לא אמר כלום אלא לאו ש״מ הא רבי אלעאי הא רבנן ויש לתמוה שמאחר שרבינו פסק כר' אלעאי דאין ראשית הגז נוהג אלא בארץ הוה ליה לפסוק שהאומר כל גיזותי ראשית לא אמר כלום ובסמוך יתבאר:\",2,0],[8,357,10,9,\"הלוקח גז צאנו של עכו\\\"ם. שם (דף קל\\\"ה) איתמר גזז ומכר ראשונה (ראשונה) וכו' רב חסדא אמר חייב דהא גזז רבי נתן בר הושעיא אמר פטור בעידנא דקא מלא שיעורא בעינן צאנך וליכא תנן הלוקח גז צאנו של עכו\\\"ם פטור מראשית הגז הא צאנו לגזוז חייב אמאי כל חד וחד בתר גיזה נפקא ליה מרשותיה תרגמה רב חסדא אליבא דר' נתן בר הושעיא כגון שהקנן לו כל ל' יום ומאחר שרבינו פסק כרב חסדא מהטעם שאכתוב ממילא קים ליה מתניתין כפשטא ומפרש רבינו דהלוקח גז צאנו של עכו\\\"ם היינו שלקח ממנו אחר שגזזן וצאנו לגזוז היינו שלקח הצאן לגיזתן וגזזן הישראל ואם לקח הגיזה קודם גזיזה שיגזוז אותה המוכר ה\\\"ז נקרא גז צאנו של עכו\\\"ם אחר שגזזן העכו\\\"ם ורש\\\"י והר\\\"ן פירשו בע\\\"א:\",1,0],[8,357,10,10,\"הלוקח גז צאנו של חבירו וכו'. משנה וגמרא שם:\",1,0],[8,357,10,11,\"היו שני מיני גיזה וכו'. משנה שם. ודע דבגמרא (דף קל\\\"ו) על הא דאמר ר' אלעאי אין ראשית הגז נוהג אלא בארץ משום דיליף נתינה נתינה מתרומה אמרינן אי מה תרומה מחדש על הישן לא אף ראשית הגז מחדש על הישן לא אין והתניא היו לו שתי רחלות גזז והניח גזז והניח שנים ושלשה שנים אין מצטרפות הא חמש מצטרפות והתניא אין מצטרפות ופירש\\\"י אם היו לו ה' צאן וגזז השתים בשנה זו וג' בשנה שנייה דהשתא איכא גיזין של ה' צאן מצטרפות ואע\\\"ג דחדש וישן הוא והתניא אידך דאפילו ה' אין מצטרפות וכו' אלא שמע מינה הא רבי אלעאי הא רבנן ותו פריך אי מה תרומה גדל בחיוב חייב גדל בפיטור פטור אף ראשית הגז נמי גדל בחיוב חייב גדל בפיטור פטור וכו' וכ\\\"ת הכי נמי והא תנן הלוקח גז צאנו של עכו\\\"ם פטור מראשית הגז הא צאנו לגזוז חייב מתניתין דלא כר' אלעאי אי מה תרומה ממין על שאינו מינו לא אף ראשית הגז [ממין על שאינו מינו לא וכו'] אין והא תנן היו לו שני מינים שחופות ולבנות מכר לו שחופות אבל לא לבנות זה נותן לעצמו וזה נותן לעצמו אלא מעתה סיפא דקתני זכרים אבל לא נקבות זה נותן לעצמו וזה נותן לעצמו הכי נמי משום דתרי מיני נינהו אלא עצה טובה קמ\\\"ל דליתיב ליה מהאי דרכיך ומהאי דאשון הכא נמי עצה טובה קמ\\\"ל דליתיב ליה מתרוייהו הא אוקימנא למתניתין דלא כרבי אלעאי. ומעתה יש לתמוה על מה שנראה מדברי רבינו בזכרים ונקבות מדין שני מינים נגעו בה וכבר נתבאר בגמרא שכתבתי דלית בה אלא משום עצה טובה וכן יש לתמוה שמאחר שפסק כרבי אלעאי דאין ראשית הגז נוהג אלא בארץ למה פסק דלא כוותיה באומר כל גיזותי ראשית כמו שכתבתי בסמוך. ומ\\\"ש הר\\\"ן בזה אינו עולה לדעת רבינו שמה שהתיר להפריש מן החדש על הישן הוי תיובתיה ומה שנ\\\"ל שאפשר לומר בזה לדעת רבינו הוא דמשמע ליה ז\\\"ל דלא אלים האי מנהגא דנהוג עלמא כרבי אלעאי לענין דאינו נוהג אלא בארץ למידחי כל הני סתמי דאתו כרבנן ומסתיין דננקוט כוותיה במאי דנהוג כוותיה לחוד והבו דלא לוסיף עלה הוא ובענין ההוא דזכרים ונקבות יש לומר דלישנא דמתני' נקט כמנהגו ומה שיתפרש במתני' יתפרש בדבריו ועי\\\"ל דה\\\"מ למימר ליה אה\\\"נ דזכרים ונקבות תרי מיני נינהו וכפשטא דמתני' דלא גרעי מתאנים שחורות ולבנות דחשיב התם תרי מיני לענין תרומה אלא דאהדר ליה לפום שיטתיה. ובספרי רבינו כתוב זה נותן לעצמו על מה שמכר והוא ט\\\"ס וצריך למחוק תיבת שמכר ולכתוב במקומה ששייר:\",1,0],[8,357,10,12,\"גר שנתגייר והיו לו גיזות וכו'. בס״פ הזרוע (חולין דף קל״ד) ח' ספיקות נאמרו בגר ד' מהם לפיטור וחד מינייהו ראשית הגז:\",1,0],[8,357,10,13,\"כמה צאן יהיה לו ויהיו חייבות בראשית הגז אין פחות מחמש. משנה פרק ראשית הגז (חולין דף קל״ה) וכב״ה ואע״ג דאמרינן בגמרא (דף קל״ז) שקילס רבי סברת ר״י דאמר ד' ראה רבינו לסמוך יותר על ב״ה דמתניתין וכ״כ הרב ר' יצחק אלפס בשם בה״ג ומר חפץ גאון.\",1,0],[8,357,10,13,\"ומ\\\"ש והוא שיהיה בגיזה שלהן אין פחות ממשקל ס' סלע ותהיה גיזת כל אחת מחמשתן אין פחות ממשקל י\\\"ב סלע וכו' עד מראשית הגז. שם בגמרא פלוגתא ופסק רבינו כמ\\\"ד הכי דרבים נינהו וכן נראה שהוא דעת הרי\\\"ף. ופסק נמי כרב דאמר מחומשות דליכא מאן דפליג עליה בהא:\",2,0],[8,357,10,14,\"השותפין חייבים בראשית הגז. בריש פרק ראשית הגז (חולין דף קל״ה:) (ותוספתא שם):\",1,0],[8,357,10,14,\"ומ\\\"ש והוא שיהיה בחלק כ\\\"א מהן כשיעור וכו'. נראה שהוא מדין חלה בנשים שנתנו לנחתום לעשות להן שאור וצ\\\"ע:\",2,0],[8,357,10,15,\"ראשית הגז מצותה בתחלה וכו'. תוספתא פרק ראשית הגז:\",1,0],[8,357,10,15,\"היו לו חמש צאן וגזז אחת מהן בלבד וכו'. כבר כתבתי בפרק זה פלוגתא דרב חסדא ורב נתן בר הושעיא ופסק כרב חסדא משום דהוא מארי דגמרא טפי ועוד דמתניתין אתיא ליה כפשטה ואע\\\"ג דרב חסדא גופיה תרגמה למתניתין אליבא דרב נתן שינויא הוא ולא סמכינן עליה ודברי רבינו בפירוש מחלוקת זה מוחלק מפירוש רש\\\"י וצריך ליישב פירוש זה מאי דמותיב עלה גמרא מהלוקח גז צאנו של עכו\\\"ם.\",2,0],[8,357,10,15,\"ומ\\\"ש רבינו ויש לו להפריש מן החדש על הישן וכו'. כבר נתבאר:\",3,0],[8,357,10,16,\"מי שהיו לו גיזות הרבה וכו'. משנה שם וכמה הוא נותן לו משקל ה' סלעים ביהודה שהם עשר בגליל ואוקמוה בגמרא בישראל שיש לו גיזין הרבה וכו'.\",1,0],[8,357,10,16,\"ומ\\\"ש מלובן וכו' עד כדי מתנה המועלת. משנה וגמרא שם:\",2,0],[8,357,10,17,\"ראשית הגז חולין לכל דבר וכו'. פ' הזרוע (חולין דף קל״א:) כל דבר שאינו בקדושה כגון הזרוע וכו' ובפרק בא סימן (נדה דף נ״א:) השוה מתנות וראשית הגז:\",1,0],[8,357,11,2,\"מצות עשה לפדות כל איש וכו' ואין האשה חייבת וכו'. בפרק קמא דקידושין (דף כ\\\"ט:):\",1,0],[8,357,11,2,\"עבר האב ולא פדהו וכו'. שם:\",2,0],[8,357,11,3,\"היה הוא לפדות וכו'. שם (דף מ\\\"ט) ובפ' יש בכור:\",1,0],[8,357,11,4,\"היה בנו לפדות וכו'. בפ\\\"ק דקידושין וכתנא קמא:\",1,0],[8,357,11,5,\"הפודה את בנו מברך וכו'. ומ\\\"ש וחוזר ומברך שהחיינו. בסוף פסחים (דף קכ\\\"א):\",1,0],[8,357,11,6,\"מצוה זו נוהגת בכ\\\"מ. בספ\\\"ק דקידושין (דף ל\\\"ז) אמרינן דכל מצוה שהיא חובת הגוף נוהגת בין בארץ בין בח\\\"ל.\",1,0],[8,357,11,6,\"ומ״ש ובכל זמן: ובכמה פודהו וכו' בין בשוה כסף מן המטלטלין שגופן ממון וכו' עד אינו פדוי. משנה וגמ' פ' יש בכור (בכורות דף נ':):\",2,0],[8,357,11,7,\"כתב לכהן וכו'. משנה שם:\",1,0],[8,357,11,7,\"נתן לו כלי וכו'. בפרקא קמא דקידושין (דף ח') תניא עגל זה לפדיון בני טלית זו לפדיון בני לא אמר כלום עגל זה בה' סלעים לפדיון בני טלית זו בה' סלעים לפדיון בני וכו' בנו פדוי [האי פדיון] ה\\\"ד אילימא דלא שוי כל כמיניה אלא לאו אע\\\"ג דשוי וכיון דלא קייצי לא לעולם דלא שוי וכגון דקביל כהן עילויה כי הא דרב כהנא שקל סודרא מבי פדיון הבן אמר ליה לדידי חזי לי ה' סלעים אמר רב אשי לא אמרן אלא כגון רב כהנא דגברא רבה הוא (ולא אזיל בגילוי הראש) ומיבעיא ליה סודרא ארישיה אבל כ\\\"ע לא כי הא דמר בר רב אשי זבן סודרא מאימיה דרבא מקובי שוה י' בי\\\"ג וכתב הר\\\"ן (דף תרכ\\\"ג ע\\\"ב) על הא דאמר רב אשי לא אמרן אלא כגון רב כהנא נראה דה\\\"ה למי שדרכו להתייקר באי זה חפץ שנותן בו לפעמים דמים הללו דמהני דאי לא תימא הכי עגל זה בה' סלעים במה בנו פדוי [אלא ודאי כדאמרן] ומיהו משמע דבעינן שיהא דרכו להתייקר בכיוצא בזה עד כדי דמים הללו הא לאו הכי לא מצי אמר לדידי שוי לי אלא שיש לתמוה על הרמב\\\"ם שכתב [בפי\\\"א מה' בכורים] נתן לו כלי שאינו שוה בשוק חמש סלעים וקבלו הכהן בה' סלעים הרי בנו פדוי ולא חילק אם דרכו להתייקר בו אם לאו עכ\\\"ל. ול\\\"נ שסובר רבינו שכל שהוא שוה ה' סלעים לשום אדם אע\\\"פ שלכהן זה אינו שוה כ\\\"כ יכול לקבלו בה' סלעים והא דאמר רב אשי לא אמרן אלא כגון רב כהנא וכו' היינו לומר דאי לשום אדם אינו שוה ה' סלעים לא מהני מאי דאמר רב כהנא לדידי שוה לי ה' סלעים וה\\\"פ לא אמרן אלא כגון סודרא דלרב כהנא ודכוותיה שוה לפעמים ה' סלעים אבל כ\\\"ע כלומר מילתא דלכ\\\"ע לא שוי ה' סלעים כיון דלשום אדם בעולם לא שוה ה' סלעים לאו כל כמיניה וז\\\"ש כלי שאינו שוה בשוק ה' סלעים כלומר בשוק אינו שוה כ\\\"כ אבל לקצת בני אדם שוה ה' סלעים וקבלו הכהן בחמש סלעים בנו פדוי:\",2,0],[8,357,11,7,\"נתן ה' סלעים לעשרה כהנים וכו'. פרק יש בכור (בכורות דף נ״א:):\",3,0],[8,357,11,8,\"רצה הכהן להחזיר לו הפדיון מחזיר וכו' עד יחזיר. גם זה שם:\",1,0],[8,357,11,8,\"וכן אם פירש ונתן לו וכו'. בפירקא קמא דקידושין (דף ו':) ומסיים בה התם ואסור לעשות כן מפני שנראה ככהן המסייע בבית הגרנות ואיני יודע למה השמיטו רבינו:\",2,0],[8,357,11,9,\"כהנים ולוים פטורים וכו'. בריש בכורות (דף ד') ומשנה ריש פ\\\"ב (דף י\\\"ג):\",1,0],[8,357,11,10,\"ישראל הבא מן הכהנת ומן הלויה וכו'. מסקנא דהלכתא בפרק הזרוע (חולין דף קל״ב):\",1,0],[8,357,11,11,\"לויה המעוברת מעכו״ם בנה פטור וכו' וכהנת המעוברת מעכו״ם וכו'. בפרק יש בכור (בכורות דף מ״ז):\",1,0],[8,357,11,12,\"כהן שנולד לו בן חלל וכו' עד שהרי זכה האב בפדיונו. שם:\",1,0],[8,357,11,13,\"השפחה שנשתחררה וכותית שנתגיירה וכו'. משנה שם (דף מ\\\"ו) נתגיירה מעוברת [וילדה] נשתחררה מעוברת וילדה כו' בכור לכהן:\",1,0],[8,357,11,13,\"ומ\\\"ש אין ידוע אם קודם שנתגיירה ילדה וכו'. פשוט הוא:\",2,0],[8,357,11,14,\"הנכרית והשפחה שילדו וכו'. שם במשנה וכת\\\"ק.\",1,0],[8,357,11,14,\"ומ\\\"ש וכן הבא אחר הנפלים. שם במשנה:\",2,0],[8,357,11,14,\"כל נפל וכו' עד וחייב לפדות. משנה שם (דף מ\\\"ז:):\",3,0],[8,357,11,15,\"חתך העובר במעיה וכו'. שם במשנה (דף מ\\\"ו) והיוצא מחותך הבא אחריו אינו בכור לכהן:\",1,0],[8,357,11,15,\"בן שמנה חדשים שהוציא ראשו וכו' וכן בן תשעה שמת וכו'. משנה שם.\",2,0],[8,357,11,15,\"ומה שכתב ומשתצא פדחתו וכו'. משנה בפרק המפלת (נדה דף כ\\\"ח) ומייתי לה בבכורות (דף מ\\\"ו:) פרק יש בכור:\",3,0],[8,357,11,16,\"יוצא דופן והבא אחריו וכו'. משנה בסוף פ\\\"ב דבכורות (דף י\\\"ט) וכרבי עקיבא:\",1,0],[8,357,11,17,\"מאימתי יתחייב בפדיון וכו'. פשוט במשנה פרק יש בכור (בכורות דף מ״ח):\",1,0],[8,357,11,17,\"מת הבן בתוך שלשים יום ואפילו ביום שלשים וכו'. משנה פרק יש בכור (בכורות דף מ״ט) וכת״ק.\",2,0],[8,357,11,17,\"ומ\\\"ש וכן אם נעשה טרפה. בפ\\\"ק דב\\\"ק (דף י\\\"א:) ודברי רבינו כפירוש התוספות.\",3,0],[8,357,11,17,\"ומ\\\"ש וכן אם הקדים ונתן לכהן וכו'. משנה פרק יש בכור וכת\\\"ק:\",4,0],[8,357,11,18,\"מי שפדה בנו בתוך שלשים יום וכו'. בפרק יש בכור (בכורות דף מ״ט) איתמר הפודה את בנו בתוך שלשים יום רב אמר פדוי ושמואל אמר אינו פדוי דכ״ע מעכשיו אין בנו פדוי וכו' לאחר ל' יום דאיתנהו למעות ודאי בנו פדוי כי פליגי לאחר ל' יום ונתעכלו המעות וכו' והלכתא כוותיה דשמואל וכו' תני תנא קמיה דרב יהודה הפודה את בנו בתוך ל' יום בנו פדוי א״ל שמואל אמר אין בנו פדוי ואת אמרת בנו פדוי ואף על גב דקי״ל [הלכה] כרב באיסורי וכשמואל בדיני הכא הלכתא כשמואל ולפי זה יש לתמוה למה פסק רבינו כרב וצ״ל שדעת רבינו כדעת הרא״ש (דף ס״ז ע״ד) שכתב ונראה שהלכה כרב דהך ברייתא מסייעא ליה ועוד דהלכתא כרב באיסורי ואע״ג דלכאורה רב יהודה כשמואל ס״ל מדמשבש לברייתא לאוקומה כשמואל מ״מ כיון דקי״ל הלכתא כרב באיסורי לא שבקינן האי כללא אף אי רב יהודה תלמידו פליג עליה וסבר כשמואל ומיהו תימה למה היה רב יהודה משבש האי תנא אם היה שונה כרב הילכך נראה לפרש דהאי תנא סתמא תנא בנו פדוי ולא פירש אם אמר מעכשיו או אם אמר לאחר שלשים יום וא״ל רב יהודה שמואל אמר אין בנו פדוי אף לאחר ל' יום אם נתעכלו המעות וגם לרב מעכשיו אין בנו פדוי ואת תני סתמא בנו פדוי מוטב שתשנה אין בנו פדוי ואתיא ככ״ע לרב בדאמר מעכשיו ולשמואל אף לאחר ל' יום אם נתעכלו המעות ולא יטעו בדבריך להקל עכ״ל. ואין ספק שלא היתה בנוסחת גמרא שלהם פסק הלכה בהדיא כשמואל כמו שהוא בנוסחא שלנו:\",1,0],[8,357,11,19,\"מי שהוא ספק וכו'. מתבאר מהדינים שיבאו בפרק זה:\",1,0],[8,357,11,19,\"מת האב בתוך ל' יום וכו' עד שיודיעוהו שלא נפדה. משנה פרק יש בכור (בכורות דף מ״ט) ומייתי לה בפרק השואל (דף ק״ב):\",2,0],[8,357,11,20,\"מי שלא בכרה אשתו וכו' עד פטור שהמע\\\"ה. משנה שם (דף מ\\\"ח):\",1,0],[8,357,11,20,\"מת האב בין בתוך ל' בין אחר ל' יום וכו'. הטור כתב על זה ואינו נראה כן בגמרא אלא אם מת האב תוך ל' יום אפילו לא חלקו פטורים ואם מת לאחר ל' יום אפילו חלקו חייבים עכ״ל. ורבינו בפירוש המשנה כתב כדברי הטור וכאן חזר בו ולכן אעתיק לשון המשנה והגמרא ומשם יתבאר. תנן פרק יש בכור (בכורות דף מ״ח) מי שלא בכרה אשתו וילדה שני זכרים מת האב והבנים קיימים ר״מ אומר אם נתנו עד שלא חלקו נתנו ואם לאו פטורים רבי יהודה אומר נתחייבו הנכסים ובגמרא דמת האב אימת אילימא דמית לאחר ל' יום בהא אמר ר״מ כי חלקו פטורין והא אישתעבדו להו נכסיה אלא דמית בתוך ל' יום מ״ש כי חלקו דאזיל לגבי האי ומדחי ליה ואזיל לגבי האי ומדחי ליה כי לא חלקו נמי ליזיל לגבי האי ולדחייה וליזיל לגבי האי ולדחייה וכו' אלא אמר רבא לעולם שמת לאחר ל' יום [ואי דאיכא נכסי טובא הכי נמי דשקיל] והב״ע דליכא אלא ה' סלעים ודכ״ע אית להו דרב אסי דאמר האחין שחלקו מחצה יורשים ומחצה לקוחות ודכ״ע מלוה הכתובה בתורה לאו ככתובה בשטר דמיא ודכ״ע אית להו דרב פפא דאמר מלוה ע״פ גובה מהיורשים ואינו גובה מהלקוחות והכא בחמש ולא חצי חמש קמיפלגי וכו' א״ה [רבי יהודה אומר] נתחייבו הנכסים נתחייב גברא מיבעי ליה ועוד תניא ר' יהודה אומר האחין שחלקו וכו' אלמא חמש ולא חצי חמש ס״ל אלא דכ״ע חמש ולא חצי חמש והכא בדרב אסי ורב פפא קא מיפלגי ואיכא דמתני לה אסיפא נתחייבו הנכסים אימת אילימא דמית לאחר ל' יום מכלל דר״מ סבר כי חלקו פטורים הא אישתעבדו להו נכסיה אלא בתוך ל' יום כי חלקו אמאי מחייב רבי יהודה ליזיל גבי האי ולדחייה ולגבי האי ולדחייה ואסיקנא כמו בלישנא קמא:\",2,0],[8,357,11,20,\"והשתא כיון דאוקמה רבא במת לאחר ל' יום משמע דבמת בתוך ל' יום מודה רבי יהודה דפטורים משום דאזיל גבי האי ודחי ליה וכו' וזהו טעמו של רבינו בפירוש המשנה ושל הטור. וטעמו של רבינו כאן נראה שהוא מדחזינן ללישנא קמא כי מתמה אמית בתוך שלשים יום ואמר ליזיל גבי האי ולדחייה וכו' לא מתמה אלא אדר\\\"מ ולא אדר' יהודה משמע דלר' יהודה דאמר נתחייבו הנכסים ניחא ליה דלא מצי כל חד לדחוייה משום דאע\\\"ג דמית תוך שלשים יום כשהגיע יום ל' חל החיוב על הנכסים ואע\\\"ג דלישנא בתרא מתמה אדרבי יהודה ואמר ליזיל לגבי האי ולדחייה וכו' פסק כלישנא קמא משום דמסתבר טעמיה:\",3,0],[8,357,11,21,\"שתי נשיו שלא בכרו וכו' עד ואחריה זכר. משנה שם (דף מ\\\"ח):\",1,0],[8,357,11,25,\"שתי נשיו אחת בכרה וכו' עד וזו שבכרה ילדה זכר. ג\\\"ז משנה שם ויש טעות סופר בקצת ספרי רבינו בסוף בבא זו וה\\\"ג מת האב ינתן מן הנכסים ה' סלעים, ופסק כר\\\"י לגבי ר\\\"מ:\",1,0],[8,357,11,26,\"שתי נשים של ב' אנשים וכו' עד לפדות את עצמו. ג\\\"ז משנה שם:\",1,0],[8,357,11,27,\"וכן מבכרת שלא שהתה וכו'. תוספתא שם:\",1,0],[8,357,11,28,\"ילדו שתי נקבות וזכר וכו'. משנה פרק יש בכור:\",1,0],[8,357,11,30,\"שתי נשים של שני אנשים אחת בכרה וכו'. פה יש חסרון בקצת ספרי רבינו מט\\\"ס וה\\\"ג שתי נשים של שני אנשים אחת בכרה ואחת לא בכרה וילדו ב' זכרים זה שלא בכרה אשתו נותן ה' סלעים לכהן. ילדו זכר ונקבה אין כאן לכהן כלום. ילדו שני זכרים ונקבה זה שלא בכרה אשתו נותן חמשה סלעים שלא נפטר אלא בב' ספיקות. ודינים אלו עד אין כאן לכהן כלום. גם זה משנה שם:\",1,0],[8,357,11,30,\"כתב הראב\\\"ד שתי נשים וכו' ילדו זכר ונקבה או שני זכרים ונקבה אין כאן לכהן כלום א\\\"א טעה בזה שזה חייב וכו':\",2,0],[8,357,11,30,\"וכתב עוד ילדו שני זכרים ונקבה זה שלא בכרה אשתו וכו' א\\\"א כל זה שבוש אלא שניהם פטורים כמו שכתבתי למעלה עכ\\\"ל. טעמו מפני שהוא גורס במתניתין דשתי נשיו אחת בכרה ואחת לא בכרה זכר ונקבה אין כאן לכהן כלום ואינו גורס שני זכרים ונקבה וכן בשתי נשים של שני אנשים אחת בכרה ואחת לא בכרה גרסינן זכר ונקבה אין כאן לכהן כלום ובגמרא (דף מ\\\"ט) תני רב הונא שני זכרים ונקבה אין כאן לכהן כלום ותנא דידן כיון דבשני אנשים משכחת לה באיש אחד ושתי נשים לא משכחת לה לא מתני ליה ופירש\\\"י תני רב הונא גבי שתי נשים של ב' אנשים שלא בכרו וילדו שני זכרים ונקבה במחבוא אין כאן לכהן כלום ואע\\\"ג דחד הוי בכור ממ\\\"נ דאם האחת ילדה שני זכרים הא' בכור ואם זכר ונקבה ילדה נמצאת חבירתה ילדה זכר לבדו והוא בכור ואפילו הכי הבן אינו חייב לפדות את עצמו דא\\\"ל אין אני בכור אלא חבירי. באיש אחד ושתי נשים לא משכחת לה כיון דאיכא חד בכור יהיב ה' סלעים לכהן להכי לא תני ליה דכל הנך דתנא כאן אין כאן לכהן כלום שוים בין איש אחד ושתי נשיו בין בשתי נשים של שני אנשים עכ\\\"ל. וע\\\"פ הדברים האלה כתב הראב\\\"ד טעה בזה וכתב עוד גבי שתי נשים של שני אנשים וילדו שני זכרים ונקבה זה שלא בכרה אשתו נותן חמשה סלעים א\\\"א כל זה שבוש וכו'. הראב\\\"ד בהרגישו קושיא דבאיש אחד ושתי נשיו נמי איכא לספוקי שמא אותה שלא בכרה ילדה נקבה לבד או נקבה ואח\\\"כ זכר כתב דבאיש אחד אין ספק ספיקא פוטר אותו ואיני יודע טעם לזה. ורבינו גורס במשנה כגירסת הראב\\\"ד ומפרש דהא דתני רב הונא ב' זכרים ונקבה אין כאן לכהן כלום ארישא קאי דוקא וגורס כיון דבאיש אחד ושתי נשיו משכחת לה ובשני אנשים לא משכחת לה לא מתני ליה ומפרש דבאיש אחד ושתי נשיו משכחת לה דאין כאן לכהן כלום משום דאיכא למימר זו שלא בכרה ילדה נקבה תחלה ואחריה זכר ובשני אנשים לא משכחת לה שלא יהא לכהן כלום ונתן טעם לדבר שלא נפטר אלא בשתי ספיקות ומ\\\"מ דברי רבינו תמוהים מ\\\"ש מאיש אחד ושתי נשיו שכתב בשני זכרים ונקבה שאין כאן לכהן כלום דהתם נמי אינו נפטר אלא בשני ספיקות דאם אותה שלא בכרה ילדה זכר בלבד חייב ואם היא ילדה הזכר והנקבה חייב אא\\\"כ ילדה הנקבה תחלה ועוד הקשה עליו הטור שגם אינו מתחייב אלא בשני ספיקות שמא ילדה אשתו נקבה ואם ילדה זכר ונקבה פטור אא\\\"כ יצא הזכר תחלה וכיון דאיכא למימר הכי והכי אין מוציאין מן הספק וצ\\\"ע. והר\\\"י קורקוס כתב שנ\\\"ל שגירסת רבינו היפך מגירסא דידן והכי גריס ותנא דידן כיון דבאיש אחד ושתי נשים הוא דמשכחת לה בשני אנשים לא משכחת לה לא מתני ליה וה\\\"פ באיש אחד ושתי נשים אחת בכרה ואחת לא בכרה והוא הדין שכתב למעלה ילדו זכר ונקבה או שני זכרים ונקבה אין כאן לכהן כלום שאני אומר וכו' וקצת טעם י\\\"ל כדברי דכשהוא איש אחד ואיש זה נולד לו נקבה בודאי ה\\\"ז אומר נקבה זו לבד ילדה אותה שלא בכרה ואת\\\"ל שילדה ג\\\"כ אני אומר שילדה נקבה תחלה ואין זה דבר רחוק ולפיכך פטור כיון שיש לאיש זה אשה שבכרה במה לתלות הזכרים או הזכר גם יש לו נקבה לומר שזו היא פטרה רחם אותה שלא בכרה אבל בב' אנשים לא משכחת לה דכיון שזה לא בכרה אשתו ויש כאן ב' זכרים לפנינו ואין לזה אשה אחרת שבכרה לתלות אין פוטרין אותו בשיתלה באשת חבירו וזהו שאמרו בשני אנשים לא משכחת לה והוא הדין שהזכיר רבינו:\",3,0],[8,357,12,1,\"מצות עשה לפדות וכו' ואם לא רצה לפדותו מ\\\"ע לערפו וכו'. כתב הראב\\\"ד בחיי ראשי אין זה מן הפלפול וכו'. ורבינו סמך על פשטא דמשנה בפ' קמא דבכורות (דף י\\\"ג) דקתני מצות פדייה קודמת למצות עריפה דאם לא כן לא היה התנא מוציא עבירה בלשון מצוה:\",1,0],[8,357,12,1,\"ושתי מצות אלו נוהגות בכ\\\"מ ובכל זמן. בספ\\\"ק דקידושין (דף ל\\\"ז) אמרינן הרי תפילין ופטר חמור דכתיב בהו ביאה ונוהג בין בארץ בין בחו\\\"ל:\",2,0],[8,357,12,1,\"ומצות פדייה קודמת למצות עריפה. משנה פ\\\"ק דבכורות (דף י\\\"ב):\",3,0],[8,357,12,2,\"השה שפודין בו נותנו לכהן. משנה שם.\",1,0],[8,357,12,2,\"ומ\\\"ש שנאמר כל פטר רחם וגו' כך היא הגירסא הנכונה והוא בפ' קרח ומדכתיב יהיה לך יליף שהוא לכהן. וספרים שכתוב בהם שנאמר כל פטר חמור ט\\\"ס הוא. ומה שסיים רבינו ואת בכור הבהמה הטמאה תפדה בהמה הטמאה האמורה כאן הוא החמור בלבד משום דמלישנא דקרא הוה משמע דבכל בכור בהמה טמאה נוהגת דין בכורה:\",2,0],[8,357,12,4,\"פטר חמור אסור בהנאה וכו'. בפ\\\"ק דבכורות (דף ט':) פטר חמור אסור בהנאה דברי ר' יהודה ור\\\"ש מתיר ואמרינן בגמרא (דף י\\\"א) דפליגי בין בהנאת דמיו בין בהנאת גופו ומשמע התם דהלכה כר' יהודה:\",1,0],[8,357,12,4,\"וכתב הראב\\\"ד אם דמיו אסורים וכו'. ואיני יודע מה קשה לו על דברי רבינו שהרי דבריו דברי הגמרא הם ואפשר שאינו תמה אלא על הגמרא:\",2,0],[8,357,12,4,\"ואם מת קודם פדיון או שערפו יקבר וכו'. משנה שם (דף י\\\"ב:):\",3,0],[8,357,12,4,\"לפיכך אם לא פדהו ונתן פטר החמור בעצמו לכהן וכו' עד בפניו. ברייתא ומימרא ספ\\\"ק דבכורות (דף י\\\"א):\",4,0],[8,357,12,5,\"הפריש פדיון פטר חמור וכו'. משנה שם (דף י\\\"ב:) המפריש פדיון פטר חמור ומת כלומר השה רבי אליעזר אומר חייב באחריותו וכו' וחכ\\\"א אינו חייב באחריותו וכו' מת פטר חמור ר\\\"א אומר יקבר ומותר בהנאתו של טלה וחכ\\\"א אינו צריך להקבר וטלה לכהן ופירש\\\"י אינו צריך להקבר דמעידנא דאפרשיה לטלה קם ליה ברשות כהן ופטר חמור פדוי וידוע דהלכה כחכמים ותנן תו התם (דף ט') גבי פדיון פטר חמור אם מת נהנים בו ומוקי לה בגמרא (דף י\\\"א:) דמת ביד בעלים ונהנה בו כהן סד\\\"א כל כמה דלא מטא לידיה לא זכה ביה קמ\\\"ל דמעידנא דאפרשיה ברשותא דכהן קאי:\",1,0],[8,357,12,6,\"מאימתי חייב לפדותו וכו'. בספ\\\"ק דבכורות (דף י\\\"ב:) תניא פטר חמור לאלתר ורמינהי אין בערכין וכו' ובפטר חמור פחות משלשים [יום] ומוסיפים עד עולם אמר ר\\\"נ לומר שאם פדאו פדוי וכו' רב ששת אמר לומר שאינו עובר עליו ופירש\\\"י לומר שאם פדאו פדוי הא דקתני לעיל פדיון פטר חמור לאלתר שאם פדאו לאלתר [פדוי] אבל עיקר מצות פדייה לא מקיים רב ששת אמר לעולם מצות פדיון לאלתר והא דקתני אין בערכין ובפטר חמור פחות משלשים [יום] שאינו עובר עליו עד שלשים יום מכאן ואילך עובר עכ\\\"ל. וידוע דהלכה כרב ששת באיסורי.\",1,0],[8,357,12,6,\"ומ\\\"ש אין כאן אלא מצות עיכוב בלבד. כלומר אין כאן דבר אחר אלא שנתעכב ולא למצוה והיינו עובר עליו דקאמר רב ששת:\",2,0],[8,357,12,7,\"לא רצה לפדותו עורפו וכו'. משנה שם (דף יג):\",1,0],[8,357,12,7,\"ומ\\\"ש ואין ממיתין אותו לא במקל וכו'. ברייתא שם (דף י'):\",2,0],[8,357,12,8,\"אין פודין לא בעגל וכו'. משנה שם (דף י\\\"ב):\",1,0],[8,357,12,9,\"אין פודין בשה הדומה לאחר וכו'. שם איבעיא להו מהו לפדות בנדמה כלומר בן רחל הדומה לעז ולא איפשיטא ופסק בה לכתחלה לחומרא ובדיעבד לקולא דכיון דספק הוא אין מחייבין אותו לחזור לפדותו כיון דאין בו קדושת הגוף:\",1,0],[8,357,12,9,\"ופודין בבן פקועה. שם פלוגתא דאמוראי ופסק כרב אשי דבתרא הוא:\",2,0],[8,357,12,9,\"ואין פודין בפסולי המוקדשין וכו'. שם בעיא דאיפשיטא:\",3,0],[8,357,12,10,\"פודין בשה בין זכרים וכו'. משנה (שם דף ט'):\",1,0],[8,357,12,12,\"שה שלקחו מדמי שביעית וכו'. גם זה [בעיא דאיפשיטא] שם (דף י\\\"ב):\",1,0],[8,357,12,12,\"אם אין לו שה לפדותו וכו'. בפ\\\"ק דבכורות (דף ט':) אמרינן דלרבי יהודה דסתם לן תנא כוותיה הקפידה תורה על פטר חמור לפדותו בשה ואקשינן ומי הקפידה והא רב נחמיה בריה דרב יוסף פריק ליה בשילקא בשוויו בשוויו לא קאמרי כי קאמרי שלא בשוויו ומסיק (דף י\\\"א) דטעמא דרבי יהודה משום דלא יהא חמור מן ההקדש ולא אמרה תורה בשה להחמיר עליו אלא להקל עליו תניא (דף י':) תפדה [אפילו] כל שהוא ופסק רב יוסף הלכתא הכי וכמה אמר רב יוסף אפילו פטרוזא בת דנקא אמר רבא אף אנן נמי תנינא וכו'. ופירש\\\"י בשילקא עשבים שלוקות. חמור מן ההקדש שפודהו בכסף בשוויו. להחמיר עליו שלא יפדהו אלא בשה. אלא להקל עליו שאם פודהו בשה יכול לפדותו בפטרוזא. פטרוזא שה כחוש. ואמרינן בגמרא רבי יהודה נשיאה הוה ליה פטר חמור שדריה לקמיה דרבי טרפון אמר ליה כמה בעינא למיתב לכהן אמר ליה הרי אמרו עין יפה בסלע עין רעה בשקל בינונית ברגיא אמר רבא הלכתא ברגיא וכמה [ברגיא] תלתא זוזי וכו' קשיא הלכתא אהלכתא ל\\\"ק כאן בבא לימלך כאן בעושה מעצמו ופירש\\\"י קשיא הלכתא אהלכתא הכא אמרת הלכתא ברגיא ולעיל אמרת הלכה [כדברי חכמים] דאפילו בת דנקא. ויש לתמוה על רבינו למה לא חילק בין בא לימלך לעושה מעצמו כדמפליג גמרא וכ\\\"כ עליו הראב\\\"ד ז\\\"ל א\\\"א והשה עצמו צריך שישוה ג' זוזים וכו'. ועוד יש לדקדק בדברי רבינו שכתב לחלק בין אם היו דמי פטר חמור ג' זוזין או יותר לכשהם פחות מניין לו לחלק כן ושמא גירסא אחרת היתה לו בגמרא וצ\\\"ע:\",2,0],[8,357,12,13,\"הפודה פטר חמור של חבירו וכו'. מימרא פירקא קמא דבכורות (דף י\\\"א):\",1,0],[8,357,12,14,\"כהנים ולוים פטורים וכו'. משנה בריש בכורות (דף ד') ובריש פ\\\"ב (דף י\\\"ג):\",1,0],[8,357,12,15,\"הלוקח עובר חמורו וכו'. משנה בריש בכורות.\",1,0],[8,357,12,15,\"ומ\\\"ש ואין קונסין אותו על דבר זה. שם בגמרא כל הני למה לי צריכי דאי תנא לוקח ה\\\"א וכו' אבל מוכר דמפקע ליה מקדושה אימא ליקנסיה קמ\\\"ל כלומר דלא נימא נחייביה בבכורה משום קנס:\",2,0],[8,357,12,15,\"היה העכו\\\"ם שותף וכו' עד הרי זה חייב. פלוגתא דאמוראי בריש בכורות (דף ג') ופסק כרב הונא דאמר אפילו אזנו בין באם בין בעובר דר' יוחנן קאי כוותיה דאמר אפילו מום קל. וכתב הטור על דברי רבינו ואיני יודע למה כתב היה לו באחד משניהם אבר אחד דהוא הדין נמי אפילו אין לו אלא כל שהוא ביד או ברגל פטור שאין צריך שיהיה לו כל האבר עכ\\\"ל. וי\\\"ל דס\\\"ל לרבינו דכשיש לעכו\\\"ם שותפות בכל הבהמה אפילו אחד מאלף שותף מיקרי ופוטר אבל כשאין לו שותפות אלא באבר אחד על זה אמרו בגמרא וכמה תהיה שותפות העכו\\\"ם ותהא פטורה מן הבכורה ואמר רב הונא אפילו אזנו ומשמע דכל אזנו קאמר מדאתקיף ליה ר\\\"נ לימא ליה שקול אזנך וזיל ופסק כרבי יוחנן דאמר אפילו מום קל ופירש\\\"י אפילו אין לעכו\\\"ם שותפות אלא באזנה שאם היה נוטל חלקו אינה לא נבלה ולא טרפה אלא מום קל בעלמא פטורה מן הבכורה וא\\\"ת היכי משכחת לה שיחתוך שום אבר ולא תהיה בעלת מום שכתב בהיה לו אבר אחד אם אפשר שיחתך ולא תהיה בעלת מום וי\\\"ל דמשכחת לה שהיה יתר כמין אצבע בידיו או ברגליו ואין בו עצם שאם חתכו כשר:\",3,0],[8,357,12,15,\"וכן המקבל חמור מן העכו\\\"ם וכו' או עכו\\\"ם שקיבל מישראל וכו'. משנה בריש בכורות:\",4,0],[8,357,12,16,\"גר שנתגייר וכו'. פרק הזרוע (חולין דף קל״ד) גבי ח' ספיקות נאמרו בגר ארבעה לפיטור וחד מינייהו פטר חמור פירוש לענין ממון ומיהו כיון דקי״ל ספק איסור לחומרא צריך לפדותו להפקיע איסורו שאסור בהנאה והפדיון מעכבו לעצמו דהמע״ה:\",1,0],[8,357,12,17,\"עכו״ם שהפריש פטר חמור וכו'. מנחות פ' ר' ישמעאל (מנחות דף ס״ז):\",1,0],[8,357,12,18,\"פרה שילדה כמין חמור וכו'. משנה פירקא קמא דבכורות (דף ה':).\",1,0],[8,357,12,18,\"ומה שכתב ואם יש בו מקצת סימני חמור חייב בבכורה. שם בעיא דאיפשיטא באת\\\"ל ופסק באת\\\"ל כמנהגו:\",2,0],[8,357,12,20,\"חמורו שלא בכרה וכו'. משנה פרק קמא דבכורות (דף ט') חמורו שלא בכרה וילדה שני זכרים נותן טלה אחד לכהן זכר ונקבה מפריש טלה אחד לעצמו שתי חמוריו שלא בכרו וילדו שני זכרים נותן שני טלאים לכהן זכר ונקבה או שני זכרים ונקבה נותן טלה אחד לכהן שתי נקבות וזכר או שני זכרים ושתי נקבות אין [כאן] לכהן כלום אחת בכרה ואחת שלא בכרה וילדו שני זכרים נותן טלה אחד לכהן זכר ונקבה מפריש טלה אחד לעצמו. ובגמרא (דף ט':) מפריש טלה לעצמו וכיון דלעצמו הוא למה ליה לאפרושי לאפקועי לאיסוריה מיניה:\",1,0],[8,357,12,21,\"כתב הראב\\\"ד ילדו שתי נקבות וכו' עד ואינו צריך להפריש טלה לעצמו. א\\\"א יש כאן שבושים והספיקות שמא הזכר יצא אחרי הנקבה עכ\\\"ל. נראה שטעמו מפני שהוא סובר כדברי רש\\\"י והתוספות שסוברים דכל היכא דקתני בענין פטר חמור אין כאן לכהן כלום מפריש טלה לאפקועי איסוריה והוא לעצמו ורבינו כתב דבשתי נקבות וזכר או שני זכרים ושתי נקבות אינו צריך להפריש טלה לעצמו וזה אצל הראב\\\"ד שיבוש משום דכיון דלא מפסיד מידי למה לא יתקן בהפרשת טלה וכתב שיש כאן שיבושים משום דמשמע מדברי רבינו דבזכר ונקבה או שני זכרים ונקבה מפריש טלה לעצמו אע\\\"פ שלא הוזכרה במשנה וגם הוא זכרונו לברכה לא הזכירו שהרי לא מיעט אלא שתי נקבות וזכר או שני זכרים ושתי נקבות וזה בעיני הראב\\\"ד שיבוש לחלק במה ששנו אין כאן לכהן כלום בין זה לזה שבזה מפריש טלה לעצמו ובזה אינו צריך להפריש ולדעת רבינו י\\\"ל דשאני ב' זכרים ונקבה דמתוך שהוא צריך לעשות בהם מעשה ליתן טלה אחד לכהן אמרינן ליה דיפריש טלה אע\\\"ג דתרי ספיקי הוא אבל בב' נקבות וזכר או ב' זכרים וב' נקבות כיון דאינו צריך לעשות מעשה ליתן שום טלה לכהן לא אמרינן שיפריש טלה לעצמו מאחר דתרי ספיקי הוא. ומ\\\"ש והספיקות שמא הזכר יצא אחר הנקבה טעמו להשיג על רבינו למה כתב שיש כאן ספיקות הרבה שהכל נכלל בספק אחד שהוא שמא הזכר יצא אחר הנקבה:\",1,0],[8,357,12,22,\"וכן הלוקח חמור מן העכו\\\"ם ואין ידוע אם בכרה וכו':\",1,0],[8,357,12,23,\"מי שהיו לו עשרה טלאים וכו' עד סוף הפרק. בפרק קמא דבכורות עלה י\\\"א:\",1,0],[8,358,1,2,\"מצות עשה לשבות וכו' אינו לוקה מן התורה אלא על הזריעה וכו'. בריש מועד קטן (דף ג') ובחרישה בשביעית נחלקו ר' יוחנן ור' אלעזר חד אמר לוקה וחד אמר אינו לוקה ומספיקא לא מלקינן ליה ועוד דרבא דאמר אהני תולדות מיחייב אאחרנייתא לא מיחייב סבר כוותיה ועוד דבירושלמי פ\\\"ז סיימו דרבי יוחנן סבר אין לוקין:\",1,0],[8,358,1,5,\"אין נוטעין בשביעית אפילו אילן סרק. ירושלמי פ\\\"ד דשביעית (הלכה ד') רשב\\\"ג אומר נוטעין אילן סרק בשביעית משמע דרבנן אסרי.\",1,0],[8,358,1,5,\"ומ\\\"ש ולא יחתוך היבולת וכו'. משנה פ\\\"ב דשביעית (מ\\\"ב) ואיתא בגמרא בריש מ\\\"ק (דף ג'):\",2,0],[8,358,1,5,\"ומ\\\"ש ולא יפסג. בריש מ\\\"ק ופירש\\\"י כשהאילן הוא רך הרבה ויראים שמא ישבר סומכין אותו והר\\\"ן כתב שאילן שענפיו נוטים לכאן ולכאן קושרים אותם כדי שיעלו למעלה ולא יכבדו על גוף האילן:\",3,0],[8,358,1,6,\"אין מציתין את האור וכו'. תוספתא פ\\\"ג וירושלמי פ\\\"ד דשביעית (הלכה ד') וכת\\\"ק.\",1,0],[8,358,1,6,\"ומ\\\"ש באישת הקנים שם [באישת הקנים] מחיצת הקנים:\",2,0],[8,358,1,6,\"ואין מלמדין את הפרה וכו' ושורין וכו' עד במוצאי שביעית. ירושלמי שם:\",3,0],[8,358,1,6,\"הראב\\\"ד כתב נ\\\"א ומשיירין את הזרעים משביעית למוצאי שביעית עכ\\\"ל ואיני יודע מה מלמדנו:\",4,0],[8,358,1,6,\"ומ\\\"ש ומקיימים האלויי בראש הגג אבל אין משקין אותו. שם בירוש' ולא נתפרש לי פירוש האלויי ומ\\\"כ פי' האלויי העולים בראש הגג וטעמו מפני שאל\\\"ף ועי\\\"ן מתחלפות. ומ\\\"מ יש לתמוה מאי אשמעינן דמקיימין אותו והא אף בשדה העולה בו מקיימין אותו. והראב\\\"ד כתב נ\\\"א מקיימין את העלין שבגג עכ\\\"ל. וגם עליו יש לתמוה כן ואפשר לדחוק ולומר דה\\\"ק אע\\\"פ שאין איסור בקיומו אין משקין אותו ויותר נכון לומר דהכי קאמר אע\\\"פ שירקות רכין אין מקיימין אותן כמו שיתבאר בפרק ד' מפני מראית העין שיבאו לומר שנזרעו בשביעית אבל העולים בראש הגג אע\\\"פ שהם רכים מותר לקיימם דליכא למיחש שיאמרו שנזרעו בשביעית שאין דרך לזרוע בגג אלא מאליו עולה ונראה שלכך היה שונה העלים להורות דברכים מיירי:\",5,0],[8,358,1,7,\"סוקרין את האילן בסיקרא וטוענין אותו באבנים. ירושלמי פ\\\"ד דשביעית (ומ\\\"ק דף ב'):\",1,0],[8,358,1,7,\"ומ\\\"ש ועודרין תחת הגפנים. בריש מ\\\"ק ורש\\\"י כתב דל\\\"ג לה משום דלעיל קתני מנין לעידור שאסור ורבינו נראה שלא היה גורס ההיא דמנין לעידור דאסור.\",2,0],[8,358,1,7,\"ומ\\\"ש והמקשקש בזיתים אם להברות את האילן אסור וכו'. שם ופירש\\\"י קשקוש היינו עידור אלא שעידור בגפנים וקשקוש בזיתים:\",3,0],[8,358,1,8,\"משקין בית השלחין וכו'. משנה שם:\",1,0],[8,358,1,8,\"וכן שדה האילנות וכו'. משנה שם (דף ו':) רבי אליעזר בן יעקב אומר מושכין את המים מאילן לאילן ובלבד שלא ישקה את כל השדה וכו' וחכמים מתירים ובירושלמי שם (הלכה ג') ובסוף פ\\\"ב דשביעית (הלכה ז') מה נן קיימין אם במרווחין דברי הכל אסור אם ברצופין דברי הכל מותר אלא כי נן קיימין בנטועין מטע עשר לבית סאה רבי אליעזר בן יעקב עבד לון כמרווחין ורבנן עבדין לון כרצופין הא רבנן אמרי במרווחין אסור להשקות מהו להמשיך [נילף הדא דרבנן מן דרבי אליעזר בן יעקב כמה דראב\\\"י אמר במרווחין אסור להשקות ומותר להמשיך] כן רבנן אמרי במרווחין אסור להשקות ומותר להמשיך. ואע\\\"פ שמשנת ראב\\\"י קב ונקי פסק רבינו כחכמים דרבים נינהו ואע\\\"פ שבפ\\\"ח מהלכות שביתת יום טוב פסק כראב\\\"י היינו משום דאשכחן מימרא דרב יהודה אם היתה שדה מטוענת מותר דשייכא בדראב\\\"י דאילו לרבנן לא איצטריך ורב יהודה לא איירי אלא במועד אבל בשביעית הדרינן לכללין ופסקינן כרבים דהא איכא טעמא לחלק בין שביעית לחול המועד כדאיתא בירושלמי פרק ב' דשביעית:\",2,0],[8,358,1,8,\"ומ\\\"ש וכן עפר הלבן וכו'. משנה פרק ב' דשביעית (משנה י') מרביצין בעפר לבן בשביעית דברי ר\\\"ש ראב\\\"י אוסר ומן הדין היה לפסוק כראב\\\"י שמשנתו קב ונקי אלא מפני שאמרו שם בירושלמי אתיא דר\\\"ש כרבנן ודראב\\\"י כשיטתיה דתנינן תמן מושכין את המים מאילן לאילן וכו' וכיון דר\\\"ש כרבנן פסק הלכה כרבנן וכן פסק בפירוש המשנה:\",3,0],[8,358,1,9,\"ועושין עוגיות לגפנים. ברייתא בריש מ\\\"ק (דף ג') לענין שביעית ולפי מה ששנינו שם במשנה אין עושין עוגיות לגפנים לא קאי אלא למועד ולא לשביעית ובפירש\\\"י עוגיות עגול סביב:\",1,0],[8,358,1,9,\"ועושין אמת המים בתחלה. משנה שם ופסק כחכמים.\",2,0],[8,358,1,9,\"ומה שכתב וממלאים את הנקעים מים. שם בברייתא:\",3,0],[8,358,1,10,\"ומפני מה התירו כל אלה וכו' שאין אסור מן התורה אלא אותם שתי אבות וכו'. בריש מ\\\"ק:\",1,0],[8,358,1,11,\"משרבו האנסין וכו'. בפרק זה בורר (סנהדרין דף כ״ו) משרבו האנסין ומאי נינהו ארנונא כדמכריז רבי ינאי פוקו וזרעו בשביעית משום ארנונא חזרו לומר אוספי [שביעית] כשרים ומפרש רבינו שהטילו מלכי רומי לעשות מחנות לחיילותיהם ורש״י פירש ארנונא מס שגובה מן התבואות כך וכך מן השדה לשנה. פוקו זרעו בשביעית שביעית בזמן הזה דרבנן דבטלה קדושת הארץ. והראב״ד כתב אנו קבלנו וכו':\",1,0],[8,358,1,11,\"וכן מי שכפאו אנס וכו'. נראה שבא ללמדנו שאף על פי שלא יהיה האנס מלך או עבד מלך הרי זה עושה.\",2,0],[8,358,1,11,\"ומה שכתב בחנם נראה שהטעם כדי שלא יבואו להערים:\",3,0],[8,358,1,12,\"הנוטע בשביעית וכו'. משנה פ\\\"ב דתרומות (משנה ג').\",1,0],[8,358,1,12,\"ומ\\\"ש מפני שישראל חשודים וכו'. שם בירושלמי:\",2,0],[8,358,1,13,\"החורש את שדהו וכו'. משנה פ\\\"ד דשביעית (משנה ב') שדה שנטייבה או שנדיירה לא תזרע במוצאי שביעית:\",1,0],[8,358,1,13,\"ומ\\\"ש ואין חוכרין אותה ממנו. גם זה משנה ג' שם חוכרים נירים מן העכו\\\"ם בשביעית אבל לא מישראל.\",2,0],[8,358,1,13,\"ומה שכתב ואם מת יזרענה בנו. שם בירושלמי ובפרק מי שהפך (מועד קטן דף י״ג) ובפרק השולח (גיטין דף ל״ה:) ובפרק כל פסולי המוקדשין (דף מ״ד):\",3,0],[8,358,1,14,\"המעביר קוצים מארצו וכו'. משנה בפרק רביעי דשביעית (משנה ב') שדה שנתקווצה תזרע במוצאי שביעית.\",1,0],[8,358,1,14,\"ומ\\\"ש או שסקל ממנה אבנים וכו'. במועד קטן (דף ג'):\",2,0],[8,358,1,15,\"הטומן לפת וכו'. משנה ספ\\\"ק דכלאים (משנה ט'):\",1,0],[8,358,1,15,\"הטומן את הלוף וכו'. משנה פ\\\"ה דשביעית (משנה ב') וכחכמים:\",2,0],[8,358,1,15,\"ומותר למרס באורז בשביעית וכו'. משנה ספ\\\"ב דשביעית (משנה י') ממרסין באורז בשביעית ר\\\"ש אומר אבל אין מכסחין ופי' הר\\\"ש ממרסין באורז שמשקין עפר האורז ומערבבין המים בעפר מלשון נתנו לממרס אבל אין מכסחין שאין חותכין עלין של אורז תרגום לא תזמור לא תכסח. ופסק רבינו כרבי שמעון ונראה לי שהטעם מפני שהוא מפרש שרבי שמעון לא לחלוק בא אלא לפרש וכן נראה מדבריו מפירוש המשנה:\",3,0],[8,358,1,17,\"בראשונה היו אומרים וכו'. משנה ריש פ\\\"ד (מ\\\"א) וירושלמי פ\\\"ד דשביעית.\",1,0],[8,358,1,17,\"ומ\\\"ש היתה בהמתו עומדת בתוך וכו'. שם בירושלמי:\",2,0],[8,358,1,18,\"הקוצץ אילן וכו' עד מותר לשרש. משנה שם (משנה ד) וכב\\\"ה ואע\\\"פ שהיא שנויה בזיתים הוא הדין לכל אילן:\",1,0],[8,358,1,19,\"המבקיע בזית וכו'. משנה ה' שם:\",1,0],[8,358,1,20,\"המזנב בגפנים וכו'. גם זה משנה ו' שם וכרבי עקיבא:\",1,0],[8,358,1,21,\"אין קוצצין בתולת שקמה וכו'. משנה ה' שם ופסק כרבי יהודה וכן פסק בפירוש המשנה ואפשר שהטעם מפני שהוא סובר שרבי יהודה לא לחלוק בא אלא לפרש:\",1,0],[8,358,1,22,\"אילן שנפשח וכו'. גם זה משנה ו' שם:\",1,0],[8,358,2,1,\"לא יוציא אדם זבלים וכו'. נלמד ממה שיבא.\",1,0],[8,358,2,1,\"ומ\\\"ש ולא יעשה אשפה בתוך שדהו וכו'. משנה רפ\\\"ג דשביעית (משנה א') ופסק כר' יוסי לגבי ר\\\"מ ורבי יהודה,\",2,0],[8,358,2,1,\"ומתוק פירש בירוש' פקוע והוא מלשון פקועות שדה וכו' והוא הנקרא בערבי חנט\\\"ל והוא מר וקראוהו מתוק ע\\\"ד סגי נהור.\",3,0],[8,358,2,1,\"ומשיקשר פירש בירוש' משיעשה קשרים קשרים:\",4,0],[8,358,2,1,\"ולא יעשה אשפה פחותה מק\\\"נ סאה של זבל וכו'. משנה שם (מ\\\"ב) עד כמה מזבלין עד ג' ג' אשפתות לבית סאה של עשר עשר משפלות של לתך לתך וידוע שהכור שלשים סאין ולתך חצי כור.\",5,0],[8,358,2,1,\"ומ\\\"ש ואם רצה להוסיף יוסיף. שם במשנה מוסיפין על המשפלות ואין מוסיפין על האשפתות ר\\\"ש אומר אף על האשפתות וכתב רבינו אם ירצה להוסיף מוסיף כלומר אם ירצה להוסיף בכל אשפה יותר מק\\\"נ סאה מוסיף והיינו דתנן מוסיפין על המשפלות.\",6,0],[8,358,2,1,\"ומ\\\"ש היה לו דבר מועט וכו'. שם במשנה ג' ופסק כת\\\"ק.\",7,0],[8,358,2,1,\"ומ\\\"ש ולא יעשה בכל בית סאה יתר מג' אשפתות היינו כת\\\"ק דאמר אין מוסיפין על האשפתות:\",8,0],[8,358,2,2,\"והרוצה לעשות כל שדהו וכו'. משנה ג' שם עושה אדם את שדהו ג' ג' אשפתות לבית סאה יתר מכאן מחציב דברי ר\\\"ש וחכ\\\"א עד שיעמיק ג' או עד שיגביה ג' כך היא גירסת ספרי המשנה ונוסחא אחרת יתר מכאן מותר וזו גירסא נכונה וגם גירסת מחציב יש לפרש כן דמחציב הוא מלשון חצובא שהם רגלי הקנקן ויש קנקנים שיש להם הרבה רגלים ופירוש יתר מכאן כלומר אפילו יותר משלש אשפתות לבית סאה מותר לעשות ור\\\"ש לטעמיה ואע\\\"ג דתנא ליה ברישא הדר תנייה כדאמרינן בירושלמי ולמה תניתא תרי זימנין אמר רבי ירמיה כאן בפוחת מן המשפלות וכו' ומשמע לי שרבינו מפרש דמתני' תרי מילי קתני ברישא שאם רצה לעשות כל שדהו ג' ג' אשפתות לבית סאה עושה והדר קתני שאם רצה להוסיף יותר מג' ג' אשפתות לבית סאה מותר לרבי שמעון ולחכמים אסור להוסיף יותר משלש אשפתות לבית סאה אלא ע\\\"י שיעמיק שלשה או יגביה שלשה וכו'.\",1,0],[8,358,2,2,\"ומ\\\"ש והעושה זבלו אוצר עושה. משנה שם וכת\\\"ק ופי' הר\\\"ש עושה אדם את זבלו אוצר דאותן שלש אשפתות לבית סאה אם בא להניחן במקום אחד בשדה ואפילו מאה משפלות במקום אחד מותר ולא תימא כי היכי דאסרי רבנן יותר משלש אשפתות לבית סאה ה\\\"נ אסור במקום אחד יותר משיעור שלש אשפתות קמ\\\"ל דמותר:\",2,0],[8,358,2,3,\"ומה שכתב רבינו היה מעמיד הזבל על הסלע וכו'. היינו סיפא דמתניתין שכתבתי בסמוך יתר מכאן מותר דברי ר\\\"ש וחכ\\\"א עד שיעמיק שלשה או עד שיגביה שלשה וידוע דהלכה כחכמים ומשמע לרבינו דהוא הדין לנותן על הסלע מדקתני התם בבבא אחריתי דרבי אליעזר בן עזריה משוה נותן על הסלע למעמיק שלשה או מגביה שלשה משמע דת\\\"ק גם בנותן על הסלע בעי שיגביה שלשה:\",1,0],[8,358,2,4,\"מותר לאדם להוציא זבל וכו' עד וגומם עד לארץ. הכל משנה שם (משנה ד'):\",1,0],[8,358,2,4,\"כתב הראב\\\"ד עיקם עלינו את הדרך וכו'. ויש לומר שרבינו מפרש כאן שמה ששנינו ומוציא מן הסהר ונותן לתוך שדהו מילתא באפי נפשה היא דאשמעינן שמותר להוציא זבל מהסהר ולתת בתוך שדהו בין שהיה הסהר בתוך שדהו או בתוך שדה חבירו וכדרך ששנה ברישא עושה אדם שדהו שלש שלש אשפתות לבית סאה דהתם איירי במוציא הזבל מהחצר והכא איירי במוציא מהסהר ואשמעינן דחצר וסהר שוים הן ולהורות לנו שאינו מקושר ומוציא מן הסהר וכו' עם המדייר שדהו וכו' דלא נימא דוקא בהאי גוונא שעוקר שלש רוחות וכו' הוא שמוציא מהסהר ונותן לתוך שדהו אבל בגוונא אחרינא אינו מוציא מהסהר ונותן לתוך שדהו ולהזהר מזה הקדים רבינו מוציא מן הסהר ואין בדבר עיקום ולא בילבול אדרבה אפריון נמטייה:\",2,0],[8,358,2,8,\"ומ\\\"ש בד\\\"א בשנתכוון לתקן שדהו וכו'. לשון המשנה בד\\\"א מתוך שלו אבל מתוך של חבירו מה שהוא רוצה יטול בד\\\"א בזמן שלא התחיל בו מערב שביעית אבל אם התחיל בו מערב שביעית מה שהוא רוצה נוטל. ובירושלמי תני אמר רבי יודא בד\\\"א בזמן שלא נתכוון לתיקון שדהו אבל אם נתכוון לתיקון שדהו אפילו יותר מכאן מותר אמר רבן שמעון בן גמליאל [בד\\\"א] בזמן שלא נתכוון לתיקון שדהו אבל אם נתכוון לתיקון שדהו אפי' פחות מכאן אסור אמר רב ביבי הורי רבי ייסא כדון תניא לקולא ורבינו נראה שגורס הורי רבי ייסא כדון תניא לחומרא ועל האומר לקולא תמהני איך יתכן שיקל בנתכוון לתקן שדהו יותר מכשלא נתכוון וגם על סברת רבי יהודה יש לתמוה כן ונראה שהיא כתובה בטעות וכך צריך להגיה בד\\\"א שנתכוון לתיקון שדהו אבל לא נתכוון אפילו יותר מכאן מותר:\",1,0],[8,358,2,9,\"אבנים שראויות וכו' עד לא ינטלו. גם זה משנה שם (משנה ז') אבנים שזעזעתן המחרישה ובירושלמי לא סוף דבר בשזעזעתן [המחרישה] אלא אפילו מחרישה עתידה לזעזען:\",1,0],[8,358,2,10,\"המסקל שדהו וכו' עד יטול את כולן. ג\\\"ז במשנה שם:\",1,0],[8,358,2,11,\"לא ימלא אדם גיא עפר וכו'. ג\\\"ז משנה ח' שם ולא יסמוך בעפר אבל עושה הוא חייץ וכל אבן שיכול לפשוט ידו וליטלה ה\\\"ז תנטל:\",1,0],[8,358,2,11,\"כתב הראב\\\"ד המשנה לא דברה על זה כלל אבל היא כך וכו'. ואני אומר שהוקשה לרבינו מה תיקון יש בבנין המדרגות ע\\\"פ הגאיות ולפיכך פירש בפירוש משנה זו כך כשיבנה מדרגה על הגאיות ההם ויישר אותם לתקנם לא יסמוך בעפר ר\\\"ל לא יחזיר העפר לגאיות ההם כדי שישוה פניהם עכ\\\"ל. נראה שהוא ז\\\"ל מפרש דרישא אסיפא סמיך וה\\\"ק כשבונים מדרגות על פי הגאיות לא יסמוך בעפר כלומר לא יחזיר עפר לגאיות ההם כדי שישוה פניהם ומ\\\"מ יש לתמוה למה לא חילק רבינו בין ערב שביעית משפסקו גשמים לשביעית משפסקו גשמים כמו שחילקו במשנה וצ\\\"ע. ועל מה ששנינו אבל עושה הוא חייץ פירש שם רבינו חייץ הוא מחיצה ר\\\"ל להבדיל אותו הגיא מכל השדה עכ\\\"ל. וע\\\"פ מה שפירש באין בונין מדרגות ע\\\"פ הגאיות שאין אסור בנין המדרגות אלא שלא יסמוך בעפר איך יפול על זה אבל עושה הוא חייץ ואפשר דה\\\"ק לא יחזיר העפר לגאיות משום דהוי תיקון הקרקע אבל עושה הוא חייץ שאף ע\\\"פ שהוא שבח לגיא להיות מובדל משאר שדות מ\\\"מ אינו תיקון הקרקע ממש. ועל מה ששנינו וכל אבן שהוא יכול לפשוט ידו וליטלה פירש רבינו האבנים שיהיו קרובים לפי הגאיות כדי שיוכל להושיט ידו ולקחתם מותר לו לקחתם ומה שלא אפשר לקחתם עד שירד בגיא אינו מותר לו לקחתם מפני שכשנראה אותו יורד או ישלשל עצמו לקחת אותם נאמר שהוא לתקן שדהו נתכוון עכ\\\"ל. והר\\\"ש פירש כל אבן שבשדהו אפילו קטנה אם הוא יכול לפשוט ידו וליטלה ולבנות בה גדר של אבנים כגון שסמוכים לגדר הרי זה תנטל שהגדר מוכיח עליו דלבנות הגדר נוטלה ולא לתקן השדה לזריעה עכ\\\"ל. והראב\\\"ד פירש כל אבן שהוא יכול לפשוט כשעומד בר\\\"ה וליטול אותה מתוך שדה חבירו תנטל ואין כאן משום גזל וכו' והוא על פי הירושלמי דאמאי דתנן כל אבן שהוא יכול לפשוט את ידו וליטלה ה\\\"ז תנטל א\\\"ר יעקב בר בון בשם ר\\\"ל זאת אומרת שאסור ללקט צרורות מתוך שדה חבירו די מנכש ויהיב עשביה עליהון הדא דתימא בבקעה אבל בהרים ובטרשים וטיבו חשב ליה:\",2,0],[8,358,2,12,\"אבני כתף וכו'. ג\\\"ז משנה ט' שם וכרבי יוסי:\",1,0],[8,358,2,12,\"כתב הראב\\\"ד מ\\\"מ אפילו מתוך שלו עכ\\\"ל.\",2,0],[8,358,2,12,\"ומ\\\"ש וכן הקבלן מביא מ\\\"מ. ג\\\"ז משנה שם:\",3,0],[8,358,2,12,\"וכתב הראב\\\"ד פירוש קבלן שקיבל לעשותו חייץ וכו'. ותמיהא לי וכי נתכוון לחלוק שדהו מה בכך הא תנן אבל עושה הוא חייץ וצ\\\"ע. ופי' הר\\\"ש הקבלן מלשון מקבלי קיבולת שדרכו לעשות בנינים בקיבולת מביא מ\\\"מ ואפילו פחותות מאבני כתף דאין כוונתו אלא לקבץ אבנים ואפילו מביא משדות שלו שרי דאי משדות אחרים אפילו אינו קבלן שרי כדתנן לעיל דמתוך של חבירו מה שהוא רוצה נוטל וי\\\"מ קבלן שקיבל שדה באריסות דלא חשיב האי שדה כשלו ונוטל ממנו אפילו קטנות אע\\\"פ שהוא אריס בה עכ\\\"ל. ורבינו בפירוש המשנה כתב כי\\\"מ:\",4,0],[8,358,2,13,\"פרצה שהיא סוגה בעפר וכו'. ירושלמי שם (הלכה י') אמאי דתנן הבונה גדר בינו ובין ר\\\"ה מותר להעמיק עד הסלע ל\\\"ש אלא בינו לבין ר\\\"ה הא בינו לבין חבירו אסור בשביעית אבל במועד אפילו בינו לבין ר\\\"ה אסור בפירצה שהיא סגה את העפר אבל בפירצה שאינה סגה את העפר מותר לגדרה בשביעית וכו' ושאינה מכשלת את הרבים אבל אם היתה מכשלת אע\\\"פ (שאינה) סגה את העפר מותר לגדרה בשביעית ע\\\"כ:\",1,0],[8,358,2,13,\"וכתב הראב\\\"ד זו הגירסא משובשת מצאתיה בירושלמי וכו':\",2,0],[8,358,2,14,\"אסור לבנות גדר וכו'. ירושלמי שם.\",1,0],[8,358,2,14,\"ומ\\\"ש אבל בונה גדר בינו ובין רשות הרבים וכו' עד סוף הפרק. משנה ג' שם:\",2,0],[8,358,3,1,\"עבודת הארץ בשנה ששית וכו' עד כדין תורה. בריש מ\\\"ק (דף ג') ובתוספתא פירקא קמא דשביעית ובירושלמי שם:\",1,0],[8,358,3,2,\"אי זו שדה האילן וכו' עד ואע\\\"פ שיש בהם מי שאינו ראוי לעשות. משנה פרק קמא דשביעית (משנה ב'):\",1,0],[8,358,3,4,\"כתב הראב\\\"ד חורשין כל בית סאה בשבילן א\\\"א נ\\\"ל מהגמרא וכו'. משיג על רבינו שסיים וכתב ואע\\\"פ שיש בהם מי שאינו ראוי לעשות שמהירושלמי נראה שכל אחד מהאילנות יהיה ראוי לעשות לערך ס' מנה ולדעת רבינו נ\\\"ל דמתניתין קשיתיה דקתני עד שיהו משלשה ועד תשעה ולא הוה ליה למיתני אלא עד שיהיו עשרה ולכך פירש דמג' עד ט' יש להם דין אחר דג' בעינן שכל אחד יהא ראוי לעשות ואם יש בהם אחד שאינו ראוי לעשות אין חורשים להם אלא לצרכן וכשהם מג' ועד ט' אע\\\"פ שיש בהם אחד שאינו ראוי לעשות חורשין כל בית סאה בשבילן. ומ\\\"ש בירושלמי ובלבד שלא יפחות מחשבון משולשים נראה דקאי אמג' ועד ט' דלא תימא כיון שהם יותר משלשה אע\\\"פ שיעשו פחות מס' מנה חורשין כל בית סאה אלא צריך שלא יפחות ממה שצריך שיעשו כשהם שלשה דהיינו ס' מנה וזעירא בר' חנינא אמר שלא יפחות מחשבון מתושעים היינו לומר שמשלשה ולמעלה צריך שיהו כל שלשה ראויים לעשות ס' מנה ונמצא שכשהם ט' צריך שיהיו ראויים לעשות שלשה ככרים של ס' מנה כל אחד ופסק רבינו כרב ביבי משום דמשמיה דרבי חנינא קאמר לה דהוא מאריה דגמרא טובא טפי מזעירא:\",1,0],[8,358,3,5,\"היו עשרה אילנות וכו' עשר נטיעות וכו'. ג\\\"ז משנה שם (משנה ד').\",1,0],[8,358,3,5,\"ומ\\\"ש ודבר זה הל\\\"מ. בפ' לולב וערבה (סוכה ל\\\"ג):\",2,0],[8,358,3,6,\"היו עשויות שורה אחת וכו' עד לעשרה. משנה ספ\\\"ק דשביעית:\",1,0],[8,358,3,6,\"כתב הראב\\\"ד היו עשויות שורה אחת מוקפות א\\\"א נ\\\"ל מהגמרא דאו מוקפות עטרה קתני במתניתין עכ\\\"ל. איני יודע מהיכא יליף לה ומ\\\"מ לישנא דמתניתין משמע דאו מוקפות קתני דמוקפות בעטרה אינו כתבנית עשויות שורה וכן פירש רבינו בפירוש המשנה שורה הוא שיהיו כשורה אחת על קו אחד. ומוקפות עטרה להיות כקשת עגולה עכ\\\"ל. ור\\\"ש פירש שורה שנטועה במקום אחד כחומה ואין מפוזרות וכו' מוקפות עטרה גדר סביב וא\\\"כ איני יודע למה הוצרך להזהיר ולומר דאו קתני ויש ספרים דגרסי במתניתין או מוקפות וכתב רבינו שמשון שהטעם שאין חורשין להם אלא לצרכן משום דכשמפוזרות נראה כחורש לצורך האילן אבל היכא דקיימין במקום אחד נראה כמתקן את הארץ לצורך שביעית ולא לצורך האילן.\",2,0],[8,358,3,6,\"ומ\\\"ש והדילועין וכו'. שם וכתנא קמא:\",3,0],[8,358,3,7,\"איזו היא נטיעה וכו'. גם זה פרקא קמא משנה ח' שם וכר' עקיבא:\",1,0],[8,358,3,8,\"אילן שנקצץ. ג\\\"ז משנה שם דברי רבי שמעון ויש לתמוה למה פסק כיחידאה ואין לומר שטעמו משום דאמרינן בירושלמי רבי שמעון ורבי אליעזר בן יעקב אמרו דבר אחד וכמו שכתב בפירוש המשנה דכיון דחכמים פליגי עלייהו הוה ליה למיפסק כרבים ואין לומר דמשום דמשנת ראב\\\"י קב ונקי שהרי בפ\\\"א פסק רבינו דלא כוותיה ועוד דכי אמרינן פלוני ופלוני אמרו דבר אחד הוה ליה שיטה ולא קיי\\\"ל כוותייהו:\",1,0],[8,358,3,9,\"אף בזמן המקדש מותר לסקל וכו' עד ולא מנקבין. משנה פרק שני דשביעית (משנה ב' - ה'):\",1,0],[8,358,3,10,\"ובזמן המקדש אין בונין מדרגות וכו'. משנה פ\\\"ג דשביעית (משנה ח'):\",1,0],[8,358,3,11,\"אף בזמן הזה אין נוטעין וכו'. משנה פרק ב' דשביעית (משנה ו') אין נוטעין ואין מבריכין ואין מרכיבין ערב שביעית פחות משלשים יום לפני ר\\\"ה ואם נטע או הבריך או הרכיב יעקור רבי יהודה אומר כל הרכבה שאינה קולטת לשלשה ימים שוב אינה קולטת רבי יוסי ור\\\"ש אומרים לשתי שבתות ואיפסיקא הלכתא בסוף פרק הערל (יבמות דף פ\\\"ג) כר' יוסי ור\\\"ש ואמרינן בפ\\\"ק דר\\\"ה (דף י') שמלבד השתי שבתות של קליטה צריך שלשים יום.\",1,0],[8,358,3,11,\"ומ\\\"ש ואם לא עקר הפירות מותרים ואם מת קודם שיעקור וכו'. ירושלמי שם:\",2,0],[8,358,4,1,\"כל שתוציא הארץ וכו' הכל מותר לאכלו מן התורה שנאמר והיתה שבת הארץ לכם לאכלה ואפילו שדה שנטייבה וכו'. בת\\\"כ והיתה שבת הארץ לכם מן השבות בארץ אתה אוכל ואי אתה אוכל מן השמור מכאן אמרו שדה שנטייבה ב\\\"ש אומרים אין אוכלין פירותיה בשביעית וב\\\"ה אומרים אוכלים ואיתא נמי להאי פלוגתא במתניתין פ\\\"ד דשביעית (משנה ב') וידוע דהלכה כב\\\"ה.\",1,0],[8,358,4,1,\"ומ\\\"ש וזה שנאמר את ספיח קצירך לא תקצור שלא יקצור כדרך שקוצר בכל שנה וכו' בת\\\"כ לא תבצור כדרך הבוצרים:\",2,0],[8,358,4,2,\"ומ\\\"ש ומד\\\"ס שיהיו כל הספיחים אסורים באכילה בת\\\"כ חכמים אומרים אין ספיחים מן התורה אלא מד\\\"ס ותניא תו התם את ספיח קצירך מכאן סמכו חכמים על הספיחים שיהיו אסורים בשביעית ובפ\\\"ט דשביעית (משנה א') תנן וחכ\\\"א כל הספיחים אסורים ואע\\\"פ שרבינו בפירוש המשנה פירשה לענין אחר כאן הוא מפרשה לענין זה:\",1,0],[8,358,4,2,\"ומ\\\"ש ולמה גזרו עליהם מפני עוברי עבירה וכו'. כן יש ללמוד מהמשנה הנזכרת דקתני התם ר' יהודה אומר ספיחי חרדל מותרין שלא נחשדו עליהם עוברי עבירה ואע\\\"פ שאין הלכה כמותו אלא כחכמים שאמרו כל הספיחים אסורים יש ללמוד מדבריו טעם איסור הספיחים:\",2,0],[8,358,4,3,\"ומ\\\"ש כגון הפיגם והירבוזין השוטים וכל כיוצא בהם. שם במשנה:\",1,0],[8,358,4,4,\"ספיחים העולים בשדה וכו'. ירושלמי פ' הספינה:\",1,0],[8,358,4,4,\"וכן התבן וכו'. פ\\\"ט דשביעית ירושלמי:\",2,0],[8,358,4,4,\"כתב הראב\\\"ד א\\\"א לא גזרו עליו איסור ספיחים וכו'. כך כתוב בספר כתיבת יד. וגם רבינו לא איירי אלא בדין ספיחין ודין קדושת שביעית כתב בפ\\\"ה ושם כתב דין התבן:\",3,0],[8,358,4,5,\"ספיחים של שביעית שיצאו למוצאי שביעי' וכו'. תוספתא פ\\\"ד דשביעית ספיחים של שביעית אין תולשין אותן ביד אבל חורש כדרכו ובהמה רועה כדרכה ומדקתני חורש על כרחנו לומר דלא מיירי בשביעית אלא בספיחי שביעית שיצאו למוצאי שביעית:\",1,0],[8,358,4,6,\"ועל מה שכתב רבינו ועד מתי אסורים ספיחי שביעית. כתב הראב\\\"ד א\\\"א חפשתי זו המימרא ולא מצאתיה וכו'. ואני אומר דאישתמיטתי' למרן מקום דין זה ודחק עצמו לבקש מקום מוצאו ולא עלה בידו ודברי רבינו מבוארים בפרק שני דדמאי ירושלמי וז\\\"ל ולענין ספיחים מראש השנה ועד חנוכה איסור ספיחים מהחנוכה ועד עצרת היתר ספיחים מן העצרת ועד ראש השנה צריכה ופסק רבינו דמעצרת ועד ראש השנה לקולא משום דאיסור ספיחים אינו אלא מדרבנן והתוספות בפרק מקום שנהגו (פסחים דף נ\\\"ח:) בד\\\"ה כל הספיחים הביאו הירושלמי הזה וכתוב בו מחנוכה ועד ראש השנה היתר ספיחים ונראה שכך היה גירסת רבינו:\",1,0],[8,358,4,6,\"והזורע ספיחי שביעית במוצאי שביעית וכו'. משנה פרק תשיעי דתרומות (משנה ד'):\",2,0],[8,358,4,7,\"בצלים שיצאו משביעית למוצאי שביעית וכו'. תוספתא פ\\\"ג.\",1,0],[8,358,4,7,\"ומה שכתב וכן שאר הפירות אין לוקחין אותם במוצאי שביעית כו' עשה הבכיר וכו'. משנה בפרק ו' דשביעית מאימתי מותר אדם ליקח ירק במוצאי שביעית משיעשה כיוצא בו עשה הבכיר הותר האפיל רבי התיר ליקח ירק במוצאי שביעית מיד ומשמע בירושלמי דהלכה כרבי. וכן משמע בפ\\\"ק דסנהדרין ומשמע לרבינו שדין שאר פירות כדין ירק לתנא קמא:\",2,0],[8,358,4,8,\"מאימתי מותר אדם ליקח לוף וכו'. משנה פ\\\"ה דשביעית (משנה ה') וכתנא קמא:\",1,0],[8,358,4,9,\"באחד בתשרי ר\\\"ה וכו'. משנה בריש ראש השנה:\",1,0],[8,358,4,9,\"פירות ששית שנכנסו לשביעית וכו'. פ\\\"ק דר\\\"ה (עלה י\\\"ב ע\\\"ב) מייתי מתני' דפירקא קמא דמעשרות מאימתי הפירות חייבים במעשרות התאנים משיבחלו התבואה והזיתים משיביאו שליש מנה\\\"מ אמר רבי אסי אמר ר' יוחנן מקץ שבע שנים וכו' אלא לומר לך כל תבואה שהביאה שליש בשביעית לפני ראש השנה אתה נוהג בו מנהג שביעית בשמינית ומשם יש ללמוד להביאה שליש בששית לפני ר\\\"ה שאתה נוהג בו מנהג ששית בשביעית:\",2,0],[8,358,4,11,\"האורז והדוחן וכו' הולכים בהם אחר גמר הפרי וכו'. פ\\\"ק דר\\\"ה (דף י\\\"ג:) מייתי הא דתנן בפרק ב' דשביעית האורז והדוחן והפרגין והשומשמין שהשרישו לפני ר\\\"ה מתעשרין לשעבר ומותרים בשביעית ואם לאו אסורים בשביעית ומתעשרים לשנה הבאה ומייתי תו בברייתא דר\\\"ש שזורי סבר שזרעו לזרע אזלינן ביה בתר השרשה ובתר הכי אמר שמואל הכל הולך אחר גמר פרי ופירש\\\"י במיני קטניות פליגי דר\\\"ש אזיל בתר השרשה ורבנן לא אזלי [בתר השרשה] למדנו דאשכח שמואל תנא דלא אזיל בתר השרשה בקטניות אלא אחר גמר פרי ועליה סמיך לפלוגי עליה דר\\\"ש שזורי ועלה דהא מתניתין דתנינן לעיל האורז והדוחן וכו' שהשרישו וכו' ומשמע לרבינו דהא דאמר שמואל הכל הולך אחר גמר הפרי גם לענין שביעית היא:\",1,0],[8,358,4,12,\"הירק בשעת לקיטתו וכו'. פרק קמא דר\\\"ה (דף י\\\"ב) אמרינן הכי לענין תרומה ומעשר ומשמע לרבינו דה\\\"ה לענין שביעית:\",1,0],[8,358,4,12,\"והאתרוג אפילו היה כפול וכו'. יש בקצת ספרי רבינו חסרון מט״ס בסוף בבא זו וכך צריך להגיה ואפילו היה כככר בששית הואיל ונלקט בשביעית הרי הוא כפירות שביעית והדין הוא בפ״ב דבכורים (משנה ו') תנן אתרוג שוה לאילן בג' דרכים ולירק בדרך אחד שוה לאילן בערלה וברבעי ובשביעית ולירק בדרך אחד שבשעת לקיטתו עישורו דברי ר״ג רבי אליעזר אומר שוה לאילן בכל דבר. ובפ״ק דר״ה (דף ט״ו) אמר רבה אתרוג בת ששית שנכנסה לשביעית פטורה מן המעשר וכו' עד חייבים עליהם משום טבל ופירש״י אמר רבה אתרוג בת ששית שחנטה בששית וכו' עד חייבת משום טבל דבתר חנטה אזלינן ובפרק לולב הגזול (סוכה דף ל״ט:) אמרינן דסתם מתני' דהתם סבר כרבותינו דאושא דאמרינן אתרוג בתר לקיטה לשביעית ורבינו נראה דספוקי מספקא ליה אי אזלינן ביה אחר חנטה לשביעית כחמשה זקנים וכמתניתין דפ״ב דבכורים או אחר לקיטתו כרבותינו דאושא וכסתם מתניתין דפ' לולב הגזול וכן מספקא ליה אי אזלינן ביה אחר חנטה למעשרות כרבי אליעזר דפ״ב דבכורים וכר״י ור״ל דבתראי נינהו או אזלינן ביה בתר לקיטה כר״ע דפ״ב דבכורים וכחמשה זקנים וכרבותינו דאושא ופסק בתרוייהו לחומרא:\",2,0],[8,358,4,13,\"וכן פירות שביעית משיצאו למוצאי שביעית וכו'. ארישא דמילתא קאי דקתני פירות ששית שנכנסו לשביעית אם היו תבואה או קטניות וכו' והגיעו לעונת המעשרות האורז והדוחן וכו' אחר גמר פרי והירק כשעת לקיטתו והשתא קאמר דהוא הדין לפירות שביעית שיצאו למוצאי שביעית שהולכים בתבואה וקטניות וכו' אחר עונת המעשרות ובאורז ודוחן וכו' אחר גמר פרי ובירק אחר לקיטתו והוא מבואר שם ויליף מדכתיב במועד שנת השמטה לומר לך כל תבואה שהביאה שליש לפני ר\\\"ה אתה נוהג בה מנהג שביעית בשמינית ושליש היינו עונת המעשרות:\",1,0],[8,358,4,14,\"פול המצרי שזרעו לזרע וכו'. בפרק שני דשביעית (משנה ז') גבי מתניתין דהאורז והדוחן וכו' בתר השרשה תנן רבי שמעון שזורי אומר פול המצרי שזרעו לזרע בתחלה כיוצא בהן כלומר דאזלינן בהו בתר השרשה וכבר כתבתי בסמוך דהלכה כשמואל דאמר לא הלכו בקטניות אלא אחר גמר פרי וגרסינן בירושלמי פרק שני דשביעית (הלכה ח') על פול המצרי זרעו לזרע לפני ר\\\"ה השביעית ונכנסה שביעית בין זרעו בין ירקו מותר זרעו לירק לפני ראש השנה שביעית ונכנסה שביעית בין זרעו בין ירקו אסור זרעו לזרע ולירק לפני ר\\\"ה השביעית ונכנסה שביעית פשיטא זרעו מותר ירקו מהו תני רבי חייא אסור תני רבי חלפתא בן שאול מותר מ\\\"ד מותר דבר תורה מ\\\"ד אסור מפני מראית העין ורבינו שסתם וכתב וכן אם זרע לזרע ולירק אסור אפשר שהיתה לו נוסחא אחרת בירושלמי או שהוא סובר שאף ע\\\"פ שבתחלה אמרו פשיטא זרעו מותר כי אסיקנא דמ\\\"ד אסור מפני מראית העין קאי אף אזרעו:\",1,0],[8,358,4,15,\"עבר וזרעו בשביעית ויצא לשמינית אם זרעו וכו'. שם בירושלמי זרעו לזרע לפני ר\\\"ה השמינית ונכנסה שמינית בין זרעו בין ירקו אסור זרעו לירק לפני ר\\\"ה השמינית ונכנסה שמינית בין זרעו בין ירקו מותר זרעו לזרע ולירק לפני ראש השנה השמינית ונכנסה שמינית זרעו אסור וירקו מותר:\",1,0],[8,358,4,15,\"וכתב הראב\\\"ד לא מצינו בזורע בשביעית שום היתר וכו'. ואני אומר שמתוך דבריו ז\\\"ל נלמד להליץ בעד רבינו ולומר דאיירי במקומות שהשביעית מדבריהם. והר\\\"י קורקוס ז\\\"ל תירץ דאע\\\"ג דאסור לזרוע ואם זרע אפילו בשוגג יעקור הכא מיירי דעבר וזרע בשביעית ויצא לשמינית ומל' עבר וזרע ויצא וכו' וכבר נתבאר ספ\\\"ג שאע\\\"פ שהדין נותן לעקור אם עבר ולא עקר הפירות מותרים והולכים בו אחר גמר פרי ואין בפירות אלא איסור ספיחים בלבד ומעתה הדין שוה אפילו במקום שהשביעית מן התורה ואפילו זרעו ישראל כפשט הירושלמי ול\\\"ק מידי עכ\\\"ל:\",2,0],[8,358,4,16,\"בנות שוח וכו'. משנה רפ\\\"ה דשביעית (משנה א'):\",1,0],[8,358,4,17,\"הבצלים הסריסים ופול המצרי וכו'. משנה פ\\\"ב שם (משנה ט') וכחכמים ואע\\\"פ שפסק רבינו לעיל בסמוך הולכים אחר גמר פרי י\\\"ל שגמר פריין תלוי בשסמוך לגמרן ימנעו מהם מים שלשים יום ובשל בעל שלש עונות:\",1,0],[8,358,4,18,\"הדלועין שקיימן לזרע וכו'. ג\\\"ז משנה שם (משנה י') ובירושלמי כיצד הוא בודק [רבי יוסי בן חנינא אומר] עוקצו אם מתאחה אסור ואם לאו מותר פירוש אם מתאחה הנקב ונסתם נראה שעדיין הוא לח ואסור ואם אין הנקב נסתם הדבר מוכיח שכבר הוקשו ומותר:\",1,0],[8,358,4,18,\"וכן הירקות וכו'. תוספתא פרק שני דשביעית כל ירקות שהוקשו לפני ר\\\"ה מותר לקיימן בשביעית אם היו רכים אסור לקיימן בשביעית מפני מראית העין כלומר שיאמרו הרואים שנזרעו בשביעית וזהו שכתב רבינו אסור לקיימן משום ספיחים כלומר שאע\\\"פ שהיה ראוי לומר שמותר לקיימן כמו שמותר לקיים הספיחים אסרו לקיימן מפני מראית העין מתוך שהם רכים יבואו לומר שנזרעו בשביעית:\",2,0],[8,358,4,18,\"ואין מחייבים אותו לשרש את הלוף וכו' ואין מחייבים אותו לשרש את הקנדס וכו'. תוס' פ\\\"ב דשביעית:\",3,0],[8,358,4,19,\"לוף של ערב וכו'. משנה פ\\\"ה דשביעית (משנה ד') וכב\\\"ה:\",1,0],[8,358,4,20,\"הבצלים שירדו עליהם גשמים וכו'. משנה פרק ו' דשביעית (מ\\\"ג) ואיתא בפרק הנודר מן הירק.\",1,0],[8,358,4,20,\"ומ\\\"ש ובין כך ובין כך וכו'. פשוט הוא:\",2,0],[8,358,4,21,\"בצל שעקרו בשביעית וכו'. פרק הנודר מן הירק:\",1,0],[8,358,4,21,\"כתב הראב\\\"ד לא עשה רבי אבהו מעשה אלא במרוכנים וכו'. וי\\\"ל לדעת רבינו דבפרק הנודר מן הירק בגמרא דידן לא אוקמוה במרוכנין אלא בדרך דילמא. ועוד דבירושלמי הכי איתיה רבי יוסי בשם ר' יוחנן בצל שעקרו ושתלו מכיון שהשחיר מתעשר לפי כולו ולא שניא בין שעקרו בשביעית ושתלו למוצאי שביעית [בין שעקרו בשביעית] רבי זעירא אמר מכיון שרבה עליו החדש מותר ר' לא ורבי אימי תרויהון אמרי אסור וכו' רבי אבהו עאל לארבאל וכו' ושאלין ליה באילין בצליא והורי לון הדא דר' זעירא מכיון שרבה עליו החדש מותר חמתון סמיכין עלוי אמר לון אני לא אמרתי אלא במרוכנין א\\\"ר יהודה בר פזי אנא ידע ראשה וסופה כדשמע דר' לא ור' אימי פליגין שמט מיניה. משמע מהכא דרבי זעירא בכל גוונא שרי אפילו בשאינם מרוכנים ולא א\\\"ר אבהו אני לא אמרתי במרוכנין אלא משום דשמע דרבי לא ורבי אימי פליגי ומאחר דגמרא דידן שרי אלמא ס\\\"ל כרבי זעירא וכיון דרבי זעירא לא מפליג בין מרוכנין לשאינם מרוכנים אנן נמי לא מפלגינן:\",2,0],[8,358,4,22,\"הפירות שיוציא האילן וכו'. בתורת כהנים ומשנה וירושלמי פ\\\"ה דשביעית ופירוש מוקצה מקום שדרכן לשטוח בו התאנים ליבש. ולענין זיתים. לשון המשנה אין עושים זיתים בבד ובקוטב אבל כותש הוא ומכניס לבודידה ר\\\"ש אומר אף טוחן הוא בבית הבד ומכניס לבודידה ובירושלמי רבותינו התירו לעשות בקוטב ר\\\"י הורי לאילין דרבי ינאי לטחון בריחיים כרבי שמעון ולעשות דרבי בקוטב כרבנן וכתב רבינו בפירוש המשנה קוטב הוא גת קטן לזיתים ובודידה שם הבד והיא גת קטנה עד מאד ובזה נתבארו דברי רבינו. מ\\\"ש כותש ומכניס לתוך גת קטן ביותר הם דברי רבנן שאמרו כותש ומכניס לבודידה.\",1,0],[8,358,4,22,\"ומ\\\"ש וטוחן בבית הבד ומכניס לבד קטנה הוא מ\\\"ש בירושלמי שרבי יוחנן הורה לשל רבי ינאי לטחון בריחים ולעשות בקוטב ולכך כתב בתחלה קטנה ביותר כי כן הוא פירוש בודידה ובסוף לא כתב אלא בד קטנה ותו לא כי הקוטב אינו כ\\\"כ קטן כמו הבודידה:\",2,0],[8,358,4,24,\"מצות עשה להשמיט וכו'. ומ\\\"ש וכן אם אסף כל פירותיו לתוך וכו'. במכילתא והשביעית תשמטנה שלא יאמר אדם מפני מה אמרה תורה וכו' לא שיאכלו העניים הריני מכניסם לתוך ביתי ומחלקם לעניים ת\\\"ל והשביעית תשמטנה וכו' מגיד שפורץ בה פרצות אלא שגדרו חכמים מפני תיקון העולם כלומר שגדרו שלא יפרוץ פרצות בשדהו אבל לגדור ודאי שהוא עובר ומבטל מצות עשה אף אם דעתו להפקירם אח\\\"כ:\",1,0],[8,358,4,24,\"ומ\\\"ש ויש לו להביא וכו'. משנה פ\\\"ה דשביעית (משנה ז'):\",2,0],[8,358,4,25,\"אין שביעית נוהגת אלא בא\\\"י בלבד וכו'. ירושלמי פ\\\"ו דשביעית (הלכה א') ומשנה בספ\\\"ק דקידושין (דף ל\\\"ו:) כל מצוה שהיא תלויה בארץ אינה נוהגת אלא בארץ:\",1,0],[8,358,4,25,\"ונוהגת בין בפני הבית וכו'. בפרק השולח (גיטין דף ל\\\"ו) לגבי פרוזבול רבי היא דתניא וזה דבר השמטה שמוט בשתי שמטות הכתוב מדבר אחת שמטת קרקע ואחת שמטת כספים בזמן שאתה משמט קרקע אתה משמט כספים ובזמן שאי אתה משמט קרקע אי אתה משמט כספים ופירש רש\\\"י אע\\\"ג דהלל בבית שני הוה ס\\\"ל לאביי דבבית שני הואיל ולא היה היובל נוהג לא נהגו שמיטין מדאורייתא ודאמרי' בערכין מנו יובלות לקדש שמיטין מדרבנן קאמר [ומצאתי בתלמידי רבינו יצחק הלוי שכתב במס' גיטין] בירושלמי מניין שאין השמטה נוהגת אלא בזמן שהיובל נוהג שנאמר וזה דבר השמטה שמוט אחת שמטת יובל ואחת שמטת שביעית אבל בת\\\"כ ראיתי דשביעית נוהגת בזמן שאין יובל נוהג ואומר אני שהוא מחלוקת עכ\\\"ל. ומדברי רבינו פה נראה שהוא סובר דאף שלא בפני הבית נוהגת מן התורה ופסק כההיא דת\\\"כ משום דמשמע דההיא כחכמים דפליגי עליה דרבי והלכה כרבים אבל קשה שהרי כתב בפרק ט' ההיא דקתני רבי בזמן שאתה משמט קרקע אתה משמט כספים ועוד דההיא דפרוזבול ליתא אלא אליבא דרבי וכיון שרבינו פסקה לההיא דפרוזבול משמע דסבר לה כרבי והיאך נאמר שכאן פסק כחכמים לפיכך נ\\\"ל דלעולם כרבי ס\\\"ל ול\\\"ק שהוא ז\\\"ל מפרש הא דאמר רבי בשתי שמטות הכתוב מדבר אחת שמטת קרקעות לא אשמטת קרקעות בשביעית קאמר דההיא לעולם נהגה אף שלא בפני הבית אלא ליובל קרי שמטת קרקעות שהרי השדות חוזרות לבעלים וכמבואר בדבריו רפ\\\"ט וכן פירש ר\\\"ת אבל קשה שכתב רבינו בפירוש בזמן שאין היובל נוהג אינו נוהג אחת מכל אלו חוץ משביעית בארץ והשמטת כספים בכל מקום מדבריהם הרי שכתב בשביעית בזמן שאין היובל נוהג אינה אלא מדבריהם ואפילו שביעית דקרקעות וי\\\"ל דמדבריהם דקאמר לא קאי אלא להשמטת כספים דסמיך ליה דאילו שמטת קרקעות מדאורייתא נמי נהגה בכל זמן ואי הוה אמרינן שמה שכתב רבינו כאן דנוהגת אף שלא בפני הבית מדרבנן הוה ניחא אבל פשטא דמילתא דמדאורייתא קאמר:\",2,0],[8,358,4,26,\"כל שהחזיקו בו עולי בבל וכו'. משנה בפ\\\"ו דשביעית (מ\\\"א) ג' ארצות לשביעית כל שהחזיקו בו עולי בבל מארץ ישראל ועד כזיב לא נאכל ולא נעבד וכל שהחזיקו בו עולי מצרים מכזיב ועד הנהר ועד אמנה נאכל אבל לא נעבד ומן הנהר ומאמנה ולפנים נאכל ונעבד ומפרש רבינו נאכל ולא נאכל לענין הספיחים. ובמשנה לא פירש כן:\",1,0],[8,358,4,27,\"סוריא אע\\\"פ שאין שביעית נוהגת בה וכו'. משנה ב' שם עושים בתלוש בסוריא אבל לא במחובר דשין וזורין ודורכין ומעמרין אבל לא קוצרין ולא בוצרין ולא מוסקין ובירושלמי אמר ר' אבהו שלא יהו הולכים ומשתקעין שם בתלוש למה הוא מותר מן גו דו חמי רווחא [קריב] לא נפיק:\",1,0],[8,358,4,27,\"אבל עמון ומואב ומצרים ושנער וכו'. פ\\\"ד דידים (משנה ג') מתוך מחלוקת ר\\\"ט ור\\\"א ב\\\"ע מתבאר שמותר לזרוע בהם בשביעית:\",2,0],[8,358,4,28,\"עבר הירדן שביעית נוהגת בה מדבריהם. בירושלמי פרק ו' דשביעית רבי יצחק בר נחמן ור\\\"ל שאל לרבי חנינא הקונה מעמון ומואב מהו [א\\\"ל קשיתי קמי רבי ייסא לית עמון ומואב דמשה] אמר רבי מנא קשיתה קמי רבי חגיי לית עמון ומואב דמשה לית עמון ומואב דר\\\"א בן עזריה אמר רבי יוסי בר בון כתיב כי חשבון עיר סיחון מלך האמורי היא צריכה לר\\\"ש טהרה מיד סיחון ועוג או לא טהרה אין תימר טהרה חייבת אין תימר לא טהרה פטורה אמר ר' תנחומא החל רש לרשת את ארצו עשיתי את ארצו חולין לפניך משמע בהדיא דחייבת בשביעית ומתניתין היא בפ\\\"ט דשביעית (משנה ב') ג' ארצות לביעור יהודה ועבר הירדן והגליל ומשמע לרבינו שאין חיובה אלא מדבריהם.\",1,0],[8,358,4,28,\"ומ\\\"ש רבינו וספיחי סוריא ועבר הירדן מותרים באכילה לא יהיו ארצות אלו חמורים וכו' כתב עליו הראב\\\"ד מה היה צריך להביאו מק\\\"ו הרי לא החזיקו עולי בבל עכ\\\"ל. וי\\\"ל דאין אנו יודעים אם כבשו עולי בבל קצת ארצות מעבר הירדן ומסוריא שהיו בבית שני מלכים תקיפים כמו שמצינו בינאי המלך שכבש ששים עיר כדאיתא בקידושין פרק האומר:\",2,0],[8,358,4,29,\"עכו\\\"ם שקנה קרקע בא\\\"י וכו'. כתב על זה בעל כפתור ופרח בפרק מ\\\"ז תימה על זה אמאי פירותיו של עכו\\\"ם מותרים מזה הטעם שכך שנינו לא נאכל ולא נעבד והרב עצמו פירש שאם תיעבד על ידי אחר אסור לאכול ממה שתוציא וזה אפילו בקרקע העכו\\\"ם שאם היה דעת הרב שאינו נעבד ר\\\"ל בקרקע ישראל אבל בקרקע העכו\\\"ם נעבד א\\\"כ היה בא מטעם יש קנין ואם הוא כן לא היה צריך ז\\\"ל לזכרון ספיחים ומ\\\"ש ז\\\"ל פה שלא גזרו על הספיחים וכו' אלא ודאי הוא שספיחי ישראל בקדושת עזרא אסורים משום גזירה אבל לזרוע אסור מן התורה והעכו\\\"ם אינם מצווים על השביעית ומש\\\"ה אין לנו לגזור עליהם ולאסור ספיחים אבל מה שהוא אסור מן התורה מפני שבת הארץ וקדושתה לא הופקע אותו איסור בקנינו מטעם שאין קנין לעכו\\\"ם בארץ ישראל להפקיע מידי מעשר ושביעית שהרי אינם חייבים במעשר ואפילו הכי פירותיהם חייבים ה\\\"נ אינם חייבים בשביעית אבל בפירותיהם נוהג שביעית שהרי ביטול גזירת ספיחים לא התיר עבודה בשביעית וכמו שכתב הוא ז\\\"ל בהלכות שמטה שהספיחים מותרים והעבודה אסורה ואין לומר מי שספיחיו אסורים פירותיו אסורים ומי שספיחיו מותרים פירותיו מותרים שהרי איסור הפירות אינו בא מכח הספיחים אלא איסור הספיחים בא מכח איסורי הפירות ותלי תניא בדלא תניא והיאך נתלה היתר פירות העכו\\\"ם מפני היתר ספיחיו והספיחים אסורים משום גזירה לא הפירות וכיבוש עולי מצרים אם עבדו ישראל אסור מדרבנן ולזה אם עבדו העכו\\\"ם נאכל הוא וממשנת אינו נאכל ואינו נעבד נראה בפירוש שפירות העכו\\\"ם בעבודתו שהם אסורים ולזה לא מצא הרב היתר לפירות העכו\\\"ם בשביעית אלא משום שהעכו\\\"ם אינם מצווים על השביעית דאי לאו הכי לכתוב פירות העכו\\\"ם בשביעית מותרים ולשתוק ע\\\"כ לשונו והאריך עוד ובסוף דבריו כתב ואל הרב יש לי להאמין אף על שמאל שהוא ימין ובפרק חלק בענין בני כנען שבאו לדון עם ישראל בענין שאמר להם אלכסנדרוס החזירו להם תשובה וכו' הניחו שדותיהם כשהם זרועות וברחו ואותה שנה שביעית היתה וסמכו ישראל עליהם א\\\"כ מה שזרע העכו\\\"ם בקרקעו בארץ ישראל מקדושה שניה בשביעית אסור אבל ספיחיו מותרים ובקדושה ראשונה אם זרע העכו\\\"ם נאכל הוא וכ\\\"ש שספיחיו מותרים אבל לא נעבד לישראל ואם עבדו אסור דקדושה דרבנן יש בו עכ\\\"ל. וכל דבריו הם שלא בהשגחה שמה שהוקשה לו מדקתני לא נאכל ולא נעבד ופירש רבינו שאם תיעבד על ידי אחר אסור לאכול ממה שתוציא יש לומר שאע\\\"פ שבפירוש המשנה כתב כן כאן בפרק זה פירשה לענין ספיחים ועוד מה שכתב בפירוש המשנה שאם תיעבד על ידי אחר אסור לאכול וכו' היינו דוקא בשאותו אחר ישראל אבל אם הוא עכו\\\"ם מותר ומ\\\"ש עוד אבל מה שהוא אסור מן התורה מפני שבת הארץ וקדושתה לא הופקע וכו' לא דק דבהדיא כתב רבינו בפ\\\"ט ובפ\\\"ו דשמיטת קרקע בזמן שאין היובל נוהג אינו אלא מדבריהם ומ\\\"ש לא נפקע אותו איסור בקנינו מטעם שאין קנין לעכו\\\"ם בארץ ישראל להפקיע מידי מעשר ושביעית אשתמיטתיה מה שכתב רבינו בפ\\\"א מהלכות תרומות שמה שאמרו אין קנין לעכו\\\"ם בארץ להפקיע מן המצות היינו לענין שאם חזר ישראל ולקחה ממנו אינה ככיבוש יחיד אלא הרי היא כאילו לא נמכרה לעכו\\\"ם מעולם אבל בעודה ביד עכו\\\"ם מופקעת היא ומה שפירותיהם חייבים במעשר אינו אלא כשמירחם ישראל דוקא. ומ\\\"ש ה\\\"נ אינם חייבים בשביעית אבל בפירותיהם נוהג שביעית שהרי ביטול גזירת ספיחים לא ביטל עבודה בשביעית וכמו שכתב הוא ז\\\"ל שהספיחים מותרים ועבודה אסורה ע\\\"כ הדבר ברור שאינם ענין זו לזו דהתם בשדה ישראל שהחזיקו בה עולי מצרים ולא עולי בבל והכא בשדה עכו\\\"ם. ומ\\\"ש ואין לומר מי שספיחיו אסורים וכו' עד ולשתוק אילו היה יורד לסוף דעת רבינו לא היה כותב כן שמה שכתב רבינו ולא גזרו על הספיחים לא לתת טעם להיתר פירות שזרע העכו\\\"ם בשדהו בא כמו שנראה מדברי כפתור ופרח. שפירוש דברי רבינו כך הם עכו\\\"ם שקנה קרקע בארץ ישראל וזרעה בשביעית פירותיה מותרים כלומר מפני שהשדה של עכו\\\"ם וגם לא נעבד בה עבודה ע\\\"י ישראל הלכך מותרים ומשום דאיכא לאקשויי אהא אע\\\"פ שלא נעבדה ע\\\"י ישראל היה לנו לאסרה דלא גריעי מספיחים שלא עובדו על ידי ישראל ואפילו הכי אסורים לכך תירץ אילו היו הספיחים אסורים מן הדין היה כדבריך אבל מאחר שהספיחים אינם אסורים אלא משום שמא יזרע ובעכו\\\"ם לא שייך לגזור שמא יזרעו שהרי אינם מצווים על השביעית הילכך ליכא קושיא מספיחים ומעתה אין שום פקפוק בדברי רבינו. ויש לתמוה עליו שהביא ההוא מעשה דפרק חלק שהיא מפורשת כדברי רבינו וא\\\"כ לא היה לו לתמוה עליו וכן קשה שמביא אותו מעשה והוא מעשה לסתור דבריו. ויש להביא ראיה לדברי רבינו מדגרס בירושלמי ספ\\\"ט דשביעית ריב\\\"ל היה מפקד לתלמידיה לא תזבון לי ירק אלא מגנתא דסיסרא קם עמיה זכור לטוב אמר ליה אזיל אימור לרבך לית הדא גנתא דסיסרא דיהודאי הוה וקטליה ונסבה מיניה אין בעית מחמרא על נפשך אשתווי לחברך ונראה דה\\\"פ שריב\\\"ל צוה לתלמידו שלא יקנה ירק בשביעית אלא מגנתא דסיסרא דהוה משמע ליה שהיתה של סיסרא הכתוב במקרא ומעולם לא נכבשה מישראל ואם כן אע\\\"פ שהעכו\\\"ם עובדה בשביעית פירותיה מותרים אבל בשדות אחרות שהיו עכשיו של עכו\\\"ם יש להסתפק שמא מקודם היו של ישראל וכיון שנעבדו בשביעית פירותיהם אסורים אף ע\\\"פ שעבדם עכו\\\"ם אמר ליה זכור לטוב שגם שדה זו היא של ישראל מקודם ולפי חששתו גם זה היה אסור אבל לפי האמת גם זה פירותיו מותרים כיון דבחזקת עכו\\\"ם הוא ועכו\\\"ם עבדו ולכן לא יחמיר על עצמו יותר ממה שמחמירים חביריו והא דאמרינן בירושלמי שאסור לטחון עם העכו\\\"ם בארץ בשביעית צריך להעמידה בספיחים שגדלו בשדה ישראל:\",1,0],[8,358,4,30,\"עיירות א\\\"י הסמוכות לספר וכו'. תוספתא פרק רביעי דשביעית:\",1,0],[8,358,5,1,\"פירות שביעית ניתנו לאכילה ולשתיה וכו'. ירושלמי רפ\\\"ז דשביעית:\",1,0],[8,358,5,1,\"ומ\\\"ש מפי השמועה למדו תהיה אף להדלקת הנר ולצבוע בה צבע. בת\\\"כ פ' בהר סיני:\",2,0],[8,358,5,2,\"לאכילה ולשתייה כיצד כו'. משנה בפ\\\"ח דשביעית (משנה ב').\",1,0],[8,358,5,2,\"ומה שכתב דבר שדרכו ליאכל חי לא יאכלנו מבושל זה נלמד ממה ששנינו שם לאכול דבר שדרכו לאכול:\",2,0],[8,358,5,3,\"ומ\\\"ש דבר שדרכו להאכל מבושל אין אוכלים אותו חי. ירושלמי רפ\\\"ח דשביעית.\",1,0],[8,358,5,3,\"ומ\\\"ש לפיכך אין שולקין אוכלי בהמה זהו פירוש מה ששנינו שם גבי דבר שאינו מיוחד לא למאכל אדם ולא למאכל בהמה חשב עליו למאכל אדם ולמאכל בהמה נותנים עליו חומרי אדם וחומרי בהמה.\",2,0],[8,358,5,3,\"ומ\\\"ש ואינו מטפל לאכול תבשיל שנפסל והפת שעיפשה. ירושלמי פרק שמיני דשביעית:\",3,0],[8,358,5,4,\"ומ\\\"ש ואין מבשלין ירק של שביעית וכו'. משנה שם (משנה ז') וכתנא קמא לגבי ר\\\"ש ואע\\\"ג דבירושלמי משמע דהלכה כר\\\"ש דשרי לא סמך עליו רבינו משום דירושלמי לטעמיה שסובר דר\\\"מ ור\\\"ש הלכה כר\\\"ש אבל גמרא דידן בפ' מי שהוציאוהו מסיק להו בתיקו.\",1,0],[8,358,5,4,\"ומ\\\"ש ואם בישל מעט ואכלו מיד מותר וכו'. שם בירושלמי נהיגין הוינן מבשלים על יד על יד ואוכלים מיד ומשמע דאפילו לכתחלה שרי וצריך טעם למה לא התיר רבינו אלא בדיעבד ונראה שגם רבינו מתיר לכתחלה.\",2,0],[8,358,5,4,\"ומ\\\"ש ואם בישל הכי קאמר רצה לבשל וסוף הלשון מוכיח כן שכתב מותר:\",3,0],[8,358,5,5,\"פירות המיוחדים למאכל אדם וכו' הלכה הבהמה וכו'. תוספתא פרק חמישי דשביעית:\",1,0],[8,358,5,6,\"לסיכה כיצד וכו'. משנה פרק ח' דשביעית (משנה ב'):\",1,0],[8,358,5,6,\"ומ\\\"ש ולא יפטם את השמן. תוספתא פ\\\"ו דשביעית אין עושין היין אלונתית ואת השמן ערב ומסיים בה ואם עשה את היין אלונתית ואת השמן ערב סך את השמן ואין סך מהיין והשמיטו רבינו מפני שהוא בכלל מה שכתב לעיל בסמוך.\",2,0],[8,358,5,6,\"ומ\\\"ש ולא יסוך במרחץ אבל סך הוא מבחוץ ונכנס. ירושלמי פ\\\"ח דשביעית:\",3,0],[8,358,5,7,\"שמן של שביעית אין חוסמין בו תנור וכירים ואין סכין בו מנעל וסנדל. ירושלמי שם ותוספתא פ\\\"ו דשביעית.\",1,0],[8,358,5,7,\"ומ\\\"ש ואין סכין אותו בידים טמאות נפל על בשרו משפשפו בידים טמאות. תוספתא שם.\",2,0],[8,358,5,7,\"ומ\\\"ש לא יסוך רגלו וכו' עד ע\\\"ג קטבליא. תוספתא שם וירושלמי פ\\\"ח דשביעית:\",3,0],[8,358,5,8,\"להדלקת הנר כיצד וכו' מכרו ולקח בו שמן אחר וכו'. תוספתא פרק ה' דשביעית וירושלמי פ\\\"ז שמן של שביעית מדליקין בו מכרו ולקח בו שמן אחר אין מדליקין בו ומסיים בה בירושלמי החליף שמן בשמן שניהם אסורים:\",1,0],[8,358,5,8,\"ולא יתן השמן לתוך המדורה וכו'. תוספתא פרק ששי דשביעית:\",2,0],[8,358,5,9,\"לצביעה כיצד וכו' אבל אין צובעין לבהמה וכו'. ירושלמי רפ\\\"ח דשביעית:\",1,0],[8,358,5,9,\"ומ\\\"ש שאין קדושת שביעית חלה על צבעי בהמה. היינו לומר שכשלמדו מפי השמועה שפירות שביעית ניתנו לצביעה היינו לצביעת אדם שצביעתו חל עליה קדושת שביעית ולפיכך מותר אבל על צביעת בהמה אינה חלה לפיכך אסור לצבוע בהם לבהמה:\",2,0],[8,358,5,10,\"מיני כבוסים וכו' אבל אין מכבסין בפירות שביעית. בפרק לולב הגזול (סוכה דף מ') ובפ' הגוזל עצים (בבא קמא דף ק״ב) תניא אין מוסרין פירות שביעית לא למשרה ולא לכביסה רבי יוסי אומר מוסרין מאן וכו' כמאן אזלא הא דתניא לאכלה ולא למלוגמא לאכלה ולא לזילוף לאכלה ולא לעשות ממנה אפיקטויזין כמאן כרבי יוסי דאי כרבנן הא איכא נמי משרה וכביסה ופסק רבינו כרבנן דרבים נינהו וסובר רבינו דע״כ לא אפליגו אלא בפירות וכדדייק לישנא דברייתא ולישנא דקרא דלאכלה אבל במיני כבוסים שאינם פירות אף לרבנן מכבסים בהם ובירושלמי פ״ז דשביעית מיני כביסות מהו שיהא עליהן קדושת שביעית נשמעינה מן הדא הירענין והבורית והאהל יש להן קדושת שביעית. פירוש קדושת שביעית חלה על הכביסה ולפיכך מכבסים בהם ואע״ג דבפרק לולב הגזול הקשו לרבנן דממעטי משרה וכביסה הא כתיב לכם דמשמע לכל צרכיכם ותירצו לכם דומיא דלאכלה שהנאתו וביעורו שוה יצאו משרה וכביסה שהנאתן אחר ביעורן ופירשו שם שמשעה ששורה הפשתן או הבגדים ביין שעה אחת נתקלקל והנאתן אינה עד לבישה י״ל שלא אמרו כן אלא בפירות דשייך לאכלה אבל מיני כביסות דלא שייך בהם לאכלה שפיר מתרבו מלכם אע״פ שהנאתם וביעורם אינו שוה:\",1,0],[8,358,5,11,\"כלל גדול אמרו בפרות שביעית וכו'. משנה רפ\\\"ח דשביעית (משנה א'):\",1,0],[8,358,5,12,\"מותר למכור אוכלי אדם וכו'. תוספתא סוף פרק ה' דשביעית וירושלמי פרק ז':\",1,0],[8,358,5,13,\"פירות שביעית אין מוציאין אותם וכו'. משנה ספ\\\"ו דשביעית (משנה ה').\",1,0],[8,358,5,13,\"ומ\\\"ש אפילו לסוריא שם אמר ר' שמעון שמעתי בפירוש שמוציאין לסוריא ומשמע דלת\\\"ק אפילו לסוריא אין מוציאין ופסק כתנא קמא.\",2,0],[8,358,5,13,\"ומ\\\"ש ואין מאכילין אותם לא לעכו\\\"ם ולא לשכיר וכו' עד אבל נזונית משל בעלה. תוספתא פרק ה' דשביעית:\",3,0],[8,358,5,16,\"אין אוספים פירות שביעית כשהם בוסר וכו'. בת\\\"כ.\",1,0],[8,358,5,16,\"ומה שכתב ומאימתי יהיה מותר לאכול פירות האילן בשדה וכו' עד לעונת המעשרות. משנה פ\\\"ד דשביעית (מ\\\"ז):\",2,0],[8,358,5,17,\"מותר לקוץ אילנות וכו' עד משיוציאו בוסר. משנה שם ופירש רבינו שמשון משישלשלו כשיתחיל להכביד ולתלות כעין שלשלת. משיגריעו משיגדלו הענבים קצת ונקרא גירוע ובפרק מקום שנהגו (פסחים דף נ״ג) מפרש דשיעורן כפול הלבן ובירושלמי (שביעית פ״ד ה״ח) א״ר יונה משיזחילו מים כמה דאת אמר כי יגרע נטפי מים עכ״ל:\",1,0],[8,358,5,18,\"ואין קוצצין את הכפניות בשביעית וכו'. בפ' מקום שנהגו (פסחים דף נ״ב):\",1,0],[8,358,5,19,\"אין שורפין תבן וקש וכו'. בפרק ט' דשביעית (משנה ז') מאימתי נהנין ושורפין בתבן ובקש של שביעית משתרד רביעה שניה משמע דקודם לכן אסור.\",1,0],[8,358,5,19,\"ומה שכתב אבל מסיקין בגפת ובזגין וכו'. תוספתא פרק ששי דשביעית:\",2,0],[8,358,5,20,\"מרחץ שהוסקה וכו'. משנה בספ\\\"ח דשביעית (משנה י\\\"א). וא\\\"ת מאחר שכתב בסמוך שאין שורפין תבן וקש של שביעית מפני שהוא מאכל בהמה היאך התירו להסיק מרחץ בהן. וי\\\"ל דאם הוסק דיעבד קאמר דמותר לרחוץ בה ועי\\\"ל דלכתחלה נמי מותר להסיק בהן מרחץ משום דצורך אדם הוא וכדתנן כל שאינו מיוחד למאכל אדם עושין ממנו מלוגמא לאדם:\",1,0],[8,358,5,20,\"וכתב הראב\\\"ד המשנה לא אמרה אלא מותר לרחוץ וכו'. מ\\\"ש אבל בשכר לא דהוי כסחורה י\\\"ל דלא נאסרה סחורה אלא בדבר שראוי לאכילה וכדדרשינן לאכלה ולא לסחורה. ומ\\\"ש ואם כדבריו אדם חשוב לא ירחוץ בשום מרחץ בשביעית ומאי איריא כשהוסק בתבן וקש של שביעית י\\\"ל דאה\\\"נ ותבן וקש של שביעית דנקט משום רישא לאשמועינן שאף על פי שהם של שביעית מותר לרחוץ במרחץ שהוסק בהן. ועוד יש לומר דהוסקה בתבן וקש לרבותא נקט שאף על פי שידוע שלא הוסקה אלא בתבן וקש לא ירחוץ בה:\",2,0],[8,358,5,21,\"הקליפין והגרעינין וכו': והקור קדושת שביעית חלה עליו וכו'. ירושלמי פ\\\"ד (הלכה ז'):\",1,0],[8,358,5,22,\"הצורר תבלין של שביעית ונותן לתוך התבשיל וכו'. תוספתא דשביעית פרק ששי:\",1,0],[8,358,5,23,\"אין נותנין תבן וקש וכו'. ג\\\"ז תוספתא ספ\\\"ה וירושלמי פ\\\"ט (הלכה ז'):\",1,0],[8,358,5,23,\"כתב הראב\\\"ד ואם נתן הרי הוא כמבוער והוא שיישן עליו וכו'. ואפשר שלא היה כן בגי' רבינו ואת\\\"ל שהיה כן בגירסתו י\\\"ל שהוא מפרש דוהוא שיישן עליו לא שיישן עליו ממש קאמר אלא שנתנו בכר כדי לישן עליו ולא הוצרך רבינו לפרש דמסתמא לכך נותנו בכר והר\\\"י קורקוס ז\\\"ל תירץ שמפרש שלא נאמר כן אלא לרבי אושעיא דמחמיר שלא ליהנות בתבן עד שתסרח:\",2,0],[8,358,5,23,\"תנור שהסיקוהו וכו'. גם זה תוספתא שם. וכ' הר\\\"י קורקוס ז\\\"ל צריך טעם לחלק בין מרחץ לתנור כי במרחץ אמרו מותר לרחוץ בה ובתנור אמרו יוצן ואפשר דבמרחץ היסקו הוא לרחוץ בה והנאה זו אינה ניכרת ולא נראית לעין ואין בה ממש אבל תנור היסקו הוא לבשל בו דבר או לאפות בו פת והנאה זו נראית וניכרת היא ושבח עצים ניכר בפת ובתבשיל כי על ידי תבן וקש של שביעית הוכשר דבר זה לאכילה ודבר ניכר הוא כי מתחלה היה חי ועכשיו מבושל ולכך אמרו בו יוצן עכ\\\"ל:\",3,0],[8,358,5,23,\"ומשתרד רביעה שניה וכו'. פ\\\"ט דשביעית (משנה ז'):\",4,0],[8,358,6,1,\"אין עושין סחורה בפירות שביעית. משנה פ\\\"ח דשביעית.\",1,0],[8,358,6,1,\"ומ״ש ואם רצה למכור מעט וכו'. בפ' לולב הגזול (סוכה דף ל״ט:) אוקימנא הא דתנן בפ״ט דשביעית הפיגם והירבוזין וכו' ונלקחים מכל אדם בשביעית בכדי מן שנו כלומר בכדי מזונותיו דוקא ולא יותר ומשמע התם דהיינו מזון ג' סעודות ורבינו אע״פ שלא הזכיר פה מזון ג' סעודות סמך על מ״ש ברפ״ח דדוקא מזון ג' סעודות.\",2,0],[8,358,6,1,\"ומ\\\"ש ואותן הדמים הרי הם כפירות שביעית וכו' ואותו הפרי הנמכר וכו'. הוא ע\\\"פ מה שיתבאר בפרק זה:\",3,0],[8,358,6,2,\"לא יהיה לוקח ירקות שדה וכו' עד הרי זה מותר. משנה פרק ז' דשביעית (משנה ג'):\",1,0],[8,358,6,3,\"כשמוכרין פירות שביעית וכו' עד לא יאגוד אותן. משנה שם פ\\\"ח (משנה ג'):\",1,0],[8,358,6,3,\"וכתב הראב\\\"ד לשון המשנה וב\\\"ה אומרים וכו' ואין פירושו מוכרח:\",2,0],[8,358,6,5,\"פירות ח\\\"ל וכו'. ירושלמי שם ותוספתא פרק רביעי:\",1,0],[8,358,6,6,\"חומר בשביעית מבהקדש וכו' האחרון נתפש בשביעית והפרי עצמו הוא כמו שהיה. משנה פ\\\"ח דשביעית (משנה ז'):\",1,0],[8,358,6,7,\"ומ״ש כיצד לקח בפירות שביעית או בדמיהם בשר וכו'. בס״פ האיש מקדש (קידושין דף נ״ד) ובע״ז פרק ר' ישמעאל (עבודה זרה דף נ״ד):\",1,0],[8,358,6,8,\"אין שביעית מתחללת וכו'. בפרק לולב הגזול (סוכה דף מ:) אמר רבי אלעזר אין שביעית מתחללת אלא דרך מקח ורבי יוחנן אמר בין דרך מקח בין דרך חילול ואסיק רב אשי (שם דף מא) מחלוקת בפרי שני אבל בפרי ראשון דברי הכל דרך מקח אין דרך חילול לא ופסק כר\\\"י:\",1,0],[8,358,6,9,\"וכשמחללין פרי הנלקח שנית וכו'. שם ברייתא וכחכמים:\",1,0],[8,358,6,10,\"דמי שביעית אין פורעים מהם את החוב וכו' עד וצריך להודיע. ירושלמי פ\\\"ג דדמאי (הלכה א') ותוספתא פ\\\"ז דשביעית:\",1,0],[8,358,6,10,\"וכן אין לוקחים מהם וכו' ואין מביאים מהם וכו' ואין סכין כלים וכו'. משנה בפ\\\"ח דשביעית (מ\\\"ח):\",2,0],[8,358,6,11,\"אין נותנים מהם לא לבלן וכו' עד מתנת חנם. ג\\\"ז משנה שם (משנה ה'):\",1,0],[8,358,6,12,\"האומר לפועל הא לך איסר וכו'. גם זה משנה שם (משנה ד') ופירש רש\\\"י בריש פרק בתרא דעבודה זרה (דף ס\\\"ב) לקוט לי בו לשון מכר הוא דמשמע לקוט לי שוויו ירק שכרו אסור לשהותו אחר זמן הביעור אלא מתבער בשביעית לקוט לי ירק לשון שכירות הוא ולא לשון מכר ואין לו דמים שיתפסו בקדושת שביעית. ולדעת רבינו צ\\\"ל דמתניתין בירקות שאין דרך לזרעם אבל בירקות שדרך לזרען אפילו גדלו בששית כל גידולם אסורים בשביעית כמבואר בדבריו פרק רביעי ולישנא דמתניתין הכי מוכח דקתני לקח ממין ירקות שדה ומדנקט ירקות שדה משמע דבירקות שגדלו מאליהם בשדה מיירי:\",1,0],[8,358,6,13,\"החמרים העושים וכו' עד משום כדי חייו. בריש פרק בתרא דע\\\"ז (דף ס\\\"ב:) מסקנא דרבא ופירש רבינו הא דחמרים בעושים מלאכה אסורה וכ\\\"כ הר\\\"ן וכך הוא בירושלמי (פ\\\"ח הלכה ו'):\",1,0],[8,358,6,14,\"הלוקח מן הנחתום וכו'. משנה פרק שמיני דשביעית (משנה ד'):\",1,0],[8,358,6,15,\"אוכלין פירות שביעית בטובה וכו'. משנה פרק ד' דשביעית (משנה ב') וכב\\\"ה:\",1,0],[8,358,6,15,\"מי שנתנו לו פירות שביעית וכו'. בספ\\\"ט דשביעית (משנה ט') מי שהיו לו פירות שביעית שנפלו לו בירושה או שנתנו לו במתנה ר\\\"א אומר ינתנו לאוכליהן וחכמים אומרים אין החוטא נשכר אלא ימכרו לאוכליהן ודמיהם יתחלקו לכל אדם ומפרש בירושלמי (פרק ט' הלכה ט') דר\\\"א סבר כב\\\"ש דאין אוכלין פירות שביעית בטובה וחכמים לדבריו דר\\\"א קאמרי ומשמע דלדידהו מותר לו לאכלם:\",2,0],[8,358,7,1,\"פירות שביעית אין אוכלים מהם וכו'. בת״כ ופרק תשיעי דשביעית (משנה ב' ג') ופרק מקום שנהגו (פסחים דף נ״ב):\",1,0],[8,358,7,3,\"היו לו פירות מרובין מחלקן מזון ג' וכו'. משנה פ' תשיעי דשביעית (משנה ח') מי שהיו לו פירות שביעית והגיע שעת הביעור מחלק מזון שלש סעודות לכל אחד ואחד ועניים אוכלים אחר הביעור אבל לא עשירים דברי רבי יהודה ר״י אומר אחד עניים ואחד עשירים אוכלים אחר הביעור וכך היא שנויה בת״כ ובירושלמי וכך היא גירסת רבינו שמשון וכך היא גירסת הרמב״ן שכתב בפירוש התורה וכתב פירוש עניים כל שלקטו הפירות משדות אחרים מן ההפקר עשירים בעלי השדות עצמם שלקטו אותם מן השדות שלהם בהפקרם. וכן גירסת התוס' בפרק מקום שנהגו (פסחים דף נ״ב:) בד״ה מתבערין וידוע דהלכה כר' יוסי וכתבו לפי גירסתם זו דהא דמשמע בכל מקום דאסור לאכול אחר הביעור היינו שמחזיק בהם כשלו אבל אחר שהפקירן והוציאן מרשותו שיאכל מהם בין אדם בין חיה אם חזר וזכה בהם והכניסם לתוך ביתו אוכל והולך עד שיכלו וכן אמרו בתוספתא פרק שמיני מי שיש לו פירות שביעית והגיע שעת הביעור מחלק מהם לשכניו ולקרוביו ולמיודעיו ומוציא ומניח על פתח ביתו ואומר אחינו בית ישראל כל מי שצריך ליטול יבא ויטול וחוזר ומכניסן לתוך ביתו ואוכל והולך עד שעה שיכלו, גם ספר מצות גדול כתב תוספתא זו וכתב עליה הנה למדת שהביעור הוא שלא יחזיק אדם בפירות אלא יפקיר הכל ודרך הפקר מותרים לאכול ובירושלמי פ״ט (הלכה ה') רבי יצחק בר רדופא הוה ליה עובדא וכו' פירוש שהיה זמן לבער פירות שביעית אתא וכו' שאל לרבי יאשיה אמר ליה חמי תלת רחמין ואבקרה קומיהון פירוש שלשה אוהבים שאפילו שתפקיר הפירות לא יזכו בהם. קפודקאי דצפרי שאלון לרבי אמי כגון (אנן דלית לן רחמין היך צורכא מתעביד) אמר לון כד תחמון רגלא צלילא תהוון מפקין לה לשוקא ומבקרין ליה והדרין וזכיין ביה ורבינו היה גורס במשנה שכתבתי רבי יוסי אומר אחד עניים ואחד עשירים אין אוכלים אחר הביעור וכך מבואר בדבריו בהדיא בפירוש המשנה הלכה שלישית מפרק חמישי ופסק כרבי יוסי. כתב הרב רבי' יעקב קורקוס ז״ל על גירסת התוספות ורבינו שמשון וספר מצות גדול וז״ל תקנה גדולה ליושבי הארץ בזמן הזה כי אע״פ שמותר לקנות פירות מעכו״ם כמו שיתבאר ספ״ד מ״מ כיון שאין קנין לעכו״ם חלה קדושת שביעית על הפירות וצריך לבערם בזמן הביעור והרי הם כספיחים העולים בשדה בור ודומיהם מהספיחים המותרים כי אע״פ שלא גזרו בהם גזירת ספיחים מ״מ קדושת שביעית עליהם וחייב לבערם והוא הדין לפירות העכו״ם כיון שאין קנין להם והרי הם כספיחים שגדלו בקרקע ישראל שחייבים בביעור כי הדלות רב ועצום ובמה שכתבתי יכולים לקיים מצות ביעור בלא ביעור וכאשר יעץ רבי אמי להנהו קפודקאי אע״פ שלדעת רבינו צריך לשרוף אותם ולבערם וזהו הביעור וכן כתב רש״י פ' מקום שנהגו שהביעור הוא במקום מדרס רגל חיה ובהמה, מ״מ כדאי הם הגאונים הנזכרים והראיות לסמוך עליהם כ״ש בשעת הדחק כי רב הוא עכ״ל. והראב״ד כתב ואסור לאכול אחר הביעור. אמר אברהם בחיי ראשי לא האיר ולא הצהיר מהו הביעור ומחלוקת תנאים הללו היא בפרק תשיעי דשביעית וכתב רבינו דינן לקמן בסמוך הכובש שלשה כבשים בחבית אחת וכו':\",1,0],[8,358,7,3,\"ואם לא מצא אוכלין בשעת הביעור שורף באש וכו' גם הראב\\\"ד מסכים עם רבינו שהביעור הוא לשרפם ולאבדם לגמרי וכבר נתבאר שאין כן דעת התוס' ורבינו שמשון וסמ\\\"ג ודעת הרמב\\\"ן בפירוש התורה כמותם וכתב שלא מצינו שמנו פירות שביעית בכלל הנשרפין ולא בכלל הנקברים אלא ענינו שצריך להפקירן לא יותר והכריח הדבר מהתוספתא שכתבתי וביאר לשטה זו כל מ\\\"ש הראב\\\"ד ודחה סברת רבינו והראב\\\"ד בשתי ידים, והראב\\\"ד ליישב התוספתא כתב שהם שני ביעורים ופירוש עד שיכלה כלומר עד שיכלה אותו המין מכל הארץ ולשון אוכל והולך עד שיכלו לא משמע אלא עד שיכלו אותם פירות עצמם שזכה בהם מן ההפקר כי כבר קיים בהם מצות ביעור. וכתב עוד וכשאין אוצר בעיר ולא ב\\\"ד והפירות ביד המלקט אותם מההפקר הוא צריך לבערם מן הבית בשעת הביעור ומפקירן על פתח ביתו ואוכלים והולכים לעולם וזו היא שביעית במינה במשהו לביעור כמו שמוזכר במסכת נדרים מפני שיש לה היתר בביעור מביתו ומ\\\"מ אינם נאסרים באכילה כלל אבל אם עירבן בביתו אחר הביעור אסורים הם באכילה לגמרי וזו היא שביעית שאוסרת בנ\\\"ט לאחר הביעור שאין לה מתירים ואפשר שהאיסור הזה מדבריהם הוא ואולי הביעור כולו חומרא מד\\\"ס והברייתות השנויות בת\\\"כ בענין הביעור אסמכתא מדבריהם:\",2,0],[8,358,7,4,\"היו לו צמוקים וכו'. כך פירש רבינו ממה ששנינו בפרק תשיעי דשביעית (מ\\\"ד) אוכלים על המופקר אבל לא על השמור.\",1,0],[8,358,7,4,\"ומ\\\"ש אבל אם יש שם ענבים קשים ביותר וכו' נראה שזהו פירוש מה ששנינו שם אוכלין על הטפיחין ופי' רבינו שם טפיחין קיבוץ טופח והם הגרגרים הקשים ממיני התבואה והקטנית שאינם נזרעים אבל צומחין מכח הארץ וישארו בארץ ימים רבים לרוב יבשותם וחזקתם והם כשאר המינים כגון הקורטמאן ממין השעורים ששמו טופח עכ\\\"ל. וע\\\"פ דרך זה לקח פה הדמיון בענבים:\",2,0],[8,358,7,5,\"אילן שעושה פירות שתי פעמים בשנה וכו'. משנה פ\\\"ט דשביעית [אוכלים] על הטפיחין ועל הדיפרא אבל לא על הסתוניות:\",1,0],[8,358,7,6,\"הכובש שלשה כבשים וכו' משנה שם (משנה ה') ופסק בירושלמי הלכה כר\\\"ג:\",1,0],[8,358,7,6,\"ומ\\\"ש ואם התחיל בה וכו'. שם בירושלמי מכיון שהתחיל באוצר כמבוער הוא:\",2,0],[8,358,7,7,\"וכשם שמבערים את הפירות וכו'. פ\\\"ז (מ\\\"א) כל שהוא מאכל אדם ומאכל בהמה וממין הצובעין ואינו מתקיים בארץ יש להם שביעית ולדמיו שביעית יש להם ביעור ולדמיו ביעור וביעור הדמים נתבאר בפ\\\"ו מההיא דלקח בפירות שביעית בשר וכו':\",1,0],[8,358,7,11,\"שלש ארצות לביעור וכו'. משנה פ\\\"ט דשביעית (משנה ב') וכפי' רבינו שמשון.\",1,0],[8,358,7,11,\"ומ\\\"ש וג' ארצות אלו כולן חשובות כאחת לזיתים ולתמרים שם במשנה (מ\\\"ג) ובירושלמי תני אף לחרובין:\",2,0],[8,358,7,11,\"ואוכלים בתמרים וכו' עד החנוכה. בפרק מקום שנהגו (פסחים דף נ״ג) ודקדק רבינו לכתוב בענבים עד הפסח של מוצאי שביעית משום דשל תחלת שביעית כבר נגמר פריין בששית:\",3,0],[8,358,7,12,\"המוליך פירות שביעית וכו'. משנה פרק מקום שנהגו (פסחים דף נ') וכת״ק:\",1,0],[8,358,7,12,\"ופירות הארץ שיצאו לח\\\"ל וכו'. שם (דף נ\\\"ב:) ת\\\"ר פירות שיצאו לח\\\"ל מתבערין בכ\\\"מ שהן רשב\\\"א אומר יחזרו למקומן ויתבערו ומשמע התם דאין הלכה כרשב\\\"א וכן אמרו בירושלמי ספ\\\"ו דשביעית (הלכה ד') הורי רבי אמי כהן תניא קמיא לקולא:\",2,0],[8,358,7,13,\"כלל גדול אמרו בשביעית וכו' עד והעקרבנין. משנה פ\\\"ז דשביעית (מ\\\"א) ומייתי לה בפרק בא סימן (נדה דף נ\\\"א):\",1,0],[8,358,7,13,\"כתב הראב\\\"ד שהרי מתקיים בארץ אלא נהנין וצובעין בו עד ר\\\"ה א\\\"א זו דברי ר\\\"מ וכו'. ואני אומר שנוסחא דידן בספרי רבינו אין להם ביעור ולא לדמיהם שהרי מתקיים בארץ אלא נהנין וצובעין בו עד ר\\\"ה כך נמצא בספר מוגה והרי זה כחכמים שאמרו אין להם ביעור ולא לדמיהם ביעור אבל אי קשיא הא קשיא שמ\\\"ש אלא נהנין וצובעין בו עד ר\\\"ה נראה שאינו כחכמים דלדידהו אפילו אחר ר\\\"ה נמי נהנין וצובעין בו ואפילו ר\\\"מ אינו מחמיר אלא בדמיהם שיתבערו עד ר\\\"ה אבל בהם עצמם מודה שאין להם ביעור כלל ואפשר שכוונתו לומר שאין להם ביעור כלל ומשום דכשיש ביעור היינו שיתבער קודם ר\\\"ה נמצא שבאמרו נהנים וצובעים בו עד ר\\\"ה הוי כאומר אינו מתבער כלל. ומ\\\"מ לשון שהרי מתקיים בארץ צריך ליישבו לנוסחא זו דמה טענה היא זו לומר דאין לדמיהם ביעור וצ\\\"ל דארישא קאי אין להם ביעור שהרי מתקיים בארץ וכיון שכן א\\\"א לבער אלא נהנים וצובעים בו עד ר\\\"ה וכ\\\"ש אחר ר\\\"ה וכיון שלהם אין ביעור גם לדמיהם אין ביעור:\",2,0],[8,358,7,14,\"כתב עוד הראב\\\"ד וכל שאינו מיוחד לא למאכל אדם וכו' א\\\"א אי אפשר זה בלא שיבוש שאם אינו ממאכל וכו': וי\\\"ל שרבינו מפרש שמה ששנינו בבבא שנית ומתקיים בארץ לא קאי אלא למין הצבעים כגון הפואה והרכפה אבל שאר דברים שאינם מאכל אדם ולא מאכל בהמה כגון עיקר הלוף והשוטה ועיקר הדנדנה והערקבנין בין שהם מתקיימים בין שאינם מתקיימים אין להם ביעור ולא לדמיהם ביעור וכן נראה מדבריו בפירוש המשנה והראב\\\"ד שכתב א\\\"א זה בלא שיבוש וכו' טעמו מפני שהוא ז\\\"ל מפרש המשנה כפשטה דמאי דקתני בבבא שנית ומתקיים בארץ קאי לכל מה ששנוי בבבא ההיא ולפיכך נראה לו שיש שיבוש וכבר כתבתי הפירוש שמפרש רבינו במשנה.\",1,0],[8,358,7,14,\"ומ״ש שאם אינו ממאכל אדם וכו' עד והקורנית הוא משנה בפ״ח. ומ״ש הראב״ד שחומרי אדם היינו שיש להם שביעית במשנה הנזכרת משמע דחומרי אדם היינו שאין עושין מלוגמא וכן פירשו רבינו ור״ש ויש לתמוה על הראב״ד שעירב משנה זו עם האחרת שאין אותה משנה ענין לזו דההיא לענין שמאכל בהמה עושים ממנו מלוגמא ואין שולקין אותו ומאכל אדם אין עושין ממנו מלוגמא ושולקין אותו והעשוי לעצים תלוי במחשבה אבל משנה זו אינה עסוקה בזה אלא לומר שיש להם דין שביעית שאין עושים סחורה מהם ושאין להם ולא לדמיהם ביעור וזה אינו תלוי במחשבה אלא אע״פ שאינו מיוחד לא למאכל אדם ולא למאכל בהמה הואיל ואינם עצים ממש יש להם שביעית ולדמיהם שביעית אבל אין להם ביעור ולא לדמיהם ביעור וזה פשוט ומבואר ורבינו כתב דין אותה משנה בפרק ה'. ומ״ש הראב״ד וכללו של דבר כל שאינו מתקיים בארץ וכו' וכן מה שכתב ויש מין המתקיים בארץ שנחלקו עליו הוא ע״פ פירושו במשנה הנזכרת וכבר כתבתי שרבינו מפרש דלא מפלגא מתניתין בין מתקיים לשאינו מתקיים אלא במין הצבעים בלבד. ומ״ש עוד הראב״ד ויש מין המתקיים בארץ שנחלקו עליו רבי יהודה וחכמים וכו' טעות סופר יש כאן וצריך להגיה ר״מ במקום ר' יהודה. והר״י קורקוס ז״ל כתב וז״ל הנה מחלוקתם תלוי בחילוק גירסאות כי רבינו כתב כן מהמשנה שבפרק הנזכר ז״ל ועוד כלל אחר אמרו כל שאינו מאכל אדם ומאכל בהמה וממין הצובעים ומתקיים בארץ יש לו שביעית ולדמיו אין לו ביעור ואין לדמיו ביעור ואי זה זה עיקר הלוף השוטה ועיקר הדנדנה והערקבנין וכו' וממין הצובעים הפואה והרכפא יש להם שביעית וכו'. כך גירסת רבינו וה״פ כל שאינו מאכל אדם ולא מאכל בהמה ולא ממין הצובעים אפילו אינו מתקיים או שהוא ממין הצובעים ומתקיים בארץ יש לו ולדמיהם שביעית ואין להם ולדמיהם ביעור. ואל החלוקה הראשונה הביא משל מעיקר הלוף השוטה והדנדנה וכו' כי לדעת רבינו אינם מאכל אדם גם אינם מתקיימים בארץ. ואל החלוקה השנית שהיא ממין הצובעים ומתקיים הביא משל הפואה והרכפא ולשיטתו צריך לגרוס בפרק בא סימן (נדה דף נ״א:) יש לו שביעית ואין לו ביעור הפואה והרכפא דאילו עיקר הלוף והדנדנה לדעת רבינו אינם מתקיימים ושם אמרו דכתיב וכו' והני לא כלו נינהו וע״כ צריך לשנות הגירסא אבל ר״ש והרא״ש גורסין ועוד כלל אחר אמרו כל שהוא מאכל אדם ומאכל בהמה וממין הצובעים ומתקיים בארץ ועלה קאי כגון הלוף השוטה והדנדנה והערקבנין וכו' סוברים שכל אלו ראויים לאדם ולבהמה ומתקיים בארץ וזו נראה גירסת הר״א ולכך כתב שכל אלו תלויים במחשבה והם האזוב וכו' ולא נתפרש באלו וכו' כי לפי גירסתם ודאי כן הוא כי לא הוזכר במשנה מה שאינו מאכל אדם ולא מאכל בהמה ולא הצובעים אלא פואה וקורנית ואזוב ובהם לא נתבאר דין ביעור אבל עיקר הלוף וכו' לדעתו ראוי למאכל אדם ולמאכל בהמה והוא כשיטת ר״ש והרא״ש שכתבתי ולפי זו השיטה כלל אמרו כללו של דבר כל שאינו מתקיים בארץ יש לו ולדמיו ביעור דעיקר הלוף וחביריו מתקיימים הם אבל לשיטת רבינו לאו כללא הוא דהא איכא לוף שוטה וחבריו שהם מתקיימים וגירסת התוספות בר״פ כלל גדול כגירסת רבינו שמשון והרא״ש והר״א עכ״ל:\",2,0],[8,358,7,15,\"קליפי רמון והנץ שלו וכו' עד ונושרים מאילנותיהם. משנה שם פ\\\"ז (מ\\\"ג) גרעינים לא אאגוזים קאי דאגוזים אין להם גרעינים אלא גרעיני שאר פירות קאמר וראויים להסקה ויש להם שביעית כיון שעיקר הפרי ראוי למאכל אדם חלה קדושת שביעית עליהן אבל אין להם ביעור כיון שאינם עיקר הפרי:\",1,0],[8,358,7,16,\"עלי זיתים ועלי קנים וכו'. עלי קנים אין להם ביעור ירושלמי פרק תשיעי (הלכה ה').\",1,0],[8,358,7,16,\"ומ\\\"ש עלי זיתים:\",2,0],[8,358,7,18,\"ועד מתי יהיה אדם רשאי ללקט וכו' ועד מתי יהיו העניים מותרים וכו'. משנה פ\\\"ט דשביעית (משנה ו' ז'):\",1,0],[8,358,7,19,\"הורד והכופר וכו'. משנה פ\\\"ז דשביעית (משנה ו'):\",1,0],[8,358,7,19,\"הקטף והוא שרף היוצא מהאילנות וכו'. בפ\\\"ז דשביעית תנן הקטף יש לו שביעית ולדמיו שביעית ר\\\"ש אומר אין לקטף שביעית מפני שאינו פרי וגרסינן בפ\\\"ק דנדה (דף ח':) א\\\"ל רבי ירמיה לרבי זירא ואת לא תסברא דמאן תנא קטפא פירא רבי אליעזר הוא והתנן ר' אליעזר אומר המעמיד בשרף הערלה אסור אפילו תימא רבנן ע\\\"כ לא פליגי רבנן עליה דר\\\"א אלא בקטפא דגווזא אבל בקטפא [דפירא] מודו ליה דתנן א\\\"ר יהושע שמעתי בפירוש שהמעמיד בשרף העלין ובשרף העיקרין מותר ובשרף הפגין אסור מפני שהוא פרי ואב\\\"א כי פליגי רבנן עליה דר\\\"א באילן העושה פירות אבל באילן שאינו עושה פירות מודו דקטפו זה הוא פריו דתנן ר\\\"ש אומר אין לקטף שביעית וחכמים אומרים יש לקטף שביעית מפני שקטפו זה הוא פריו מאן חכמים לאו רבנן דפליגי עליה דר\\\"א ופסק רבינו כהני תרי תירוצי דמשמע דתרווייהו קושטא נינהו אבל איתא התם בתר הכי א\\\"ל ההוא סבא הכי א\\\"ר יוחנן מאן חכמים ר\\\"א דאמר קטפו זהו פריו אי ר\\\"א מאי איריא אילן שאינו עושה פרי אפילו אילן העושה פרי קטפו זהו פריו לדבריהם דרבנן קאמר להו לדידי אפילו אילן העושה פרי נמי קטפו זהו פריו לדידכו אודו לי מיהת באילן שאינו עושה פירות דקטפו זהו פריו ורבנן אמרי ליה לא שנא והשתא יש לתמוה למה פסק דלא כרבי יוחנן ואפשר לומר שטעמו משום דלא אשכחן מאן דאמר הכי משמיה דרבי יוחנן אלא ההוא סבא לא סמכינן עליה דאם איתא בבי מדרשא הוו ידעי לה. ועוד דטעמא דחיקא הוא לומר דלדבריהם דרבנן קאמר ואפשר דאם איתא דאמרה רבי יוחנן דרך משא ומתן אמרה ולא לקושטא דמילתא:\",2,0],[8,358,7,21,\"הכובש ורד שביעית וכו'. משנה ספ\\\"ז דשביעית (משנה ז') ורד חדש שכבשו בשמן ישן ילקט את הורד וישן בחדש חייב בביעור ובירושלמי (הלכה ב') הכא את אמר וילקט את הורד והכא את אמר חייב בביעור ר' אבהו בשם ר' יוחנן תרין תניין אינון א\\\"ר זעירא יכיל אנא פתר [בתרי פתרי] ורד חדש שכבשו בשמן ישן ורד של שביעית שכבשו בשמן של ששית וישן בחדש ורד שביעית בשמן של שמינית וכמאן דמוקי לה בתרי פתרי נקיטינן דהוא עדיף מדמוקים לה בתרי תנאי וכדאמרי' בפרק אע\\\"פ דמוקמינן מתניתין בתרי טעמי ולא מוקמינן לה בתרי תנאי. וז\\\"ל רבינו בפירוש המשנה ורד חדש שכבשו בשמן ישן הוא שיטמין ורד של שביעית בשמן של ששית הרי הוא מלקט אותו מפני שלא יכנס כל הוורדים וטעמם בשמן שהשמן הוא ישן והורד חדש אלא אם יניחהו זמן רב וישן בחדש הוא לתת ורד של שביעית בשמן של מוצאי שביעית וזהו יכנס בו כח הורד וטעמו מיד ומפני זה יבער השמן עכ\\\"ל פירוש כי הורד הישן נותן כח וטעם יותר מהר מן החדש והשמן החדש נוח לקלוט טעם יותר מהישן:\",1,0],[8,358,7,22,\"חרובין של שביעית שכבשן וכו'. ג\\\"ז שם במשנה סופה דמתניתין דבסמוך חרובין חדשים שכבשן ביין ישן וישנים בחדש חייבים בביעור ופירש רבינו שם החרובין ביין יכנס בו טעם החרובין מיד ומפני זה על שני הדרכים חייב לבער היין עכ\\\"ל פירוש שהחרובין קולטין טעם היין מיד ולא דמו לוורד בשמן:\",1,0],[8,358,7,22,\"זה הכלל פירות שביעית שנתערבו וכו'. שם במשנה:\",2,0],[8,358,8,3,\"כדרך שאסור לעבוד הארץ בשביעית וכו'. ואלו כלים שאין האומן רשאי למוכרם וכו' עד וכל כליה. משנה פרק ה' דשביעית (משנה ו'):\",1,0],[8,358,8,4,\"ומ\\\"ש ומותר למכור סתם למי שאינו חשוד וכו'. ירושלמי שם (הלכה ג'):\",1,0],[8,358,8,5,\"היוצר מוכר חמשה כדי שמן וכו' עד שמא יביא לארץ. משנה שם (משנה ז'):\",1,0],[8,358,8,6,\"ומוכר לחשוד פרה וכו'. משנה א' שם וכבית הלל ואיתא פירקא קמא דעבודה זרה (דף ט\\\"ו):\",1,0],[8,358,8,6,\"ומוכר לו שדהו וכו' אבל לא ימכור לו שדה האילן וכו'. תוספתא סוף פרק ג' דשביעית:\",2,0],[8,358,8,6,\"ומשאילו סאה וכו'. עד וכולן בפירוש אסורין. משנה פרק ה' דשביעית (משנה ח'):\",3,0],[8,358,8,7,\"וכן משאלת וכו' מחזיקין ידי עכו״ם וכו'. משנה ט' שם ובס״פ הניזקין (גיטין דף ס״א):\",1,0],[8,358,8,8,\"ומותר לרדות עמהם הכוורת. ירושלמי פרק רביעי (הלכה ג') הורי רבי אמי לרדות עמו כלומר ולאפוקי מר\\\"א דחשיב כוורת כקרקע בסוף שביעית (משנה ז') ובסוף עוקצין ובתוספתא דבסוף עוקצין:\",1,0],[8,358,8,8,\"וחוכרים מהם נירין וכו'. משנה פרק רביעי דשביעית (משנה ג'):\",2,0],[8,358,8,9,\"מותר לעשות בסוריא בתלוש וכו'. משנה פרק ששי דשביעית (משנה ב'):\",1,0],[8,358,8,10,\"כשם שאסור לעשות סחורה וכו' עד משום כדי חייו של מוכר. בפרק לולב הגזול (סוכה דף ל\\\"ט):\",1,0],[8,358,8,12,\"בד\\\"א בזמן שהיה מוכר וכו' אבל היה מוכר פירות שחזקתן מן ההפקר וכו'. משנה פ\\\"ט דשביעית (משנה א'):\",1,0],[8,358,8,13,\"וכל דבר שאינו חייב במעשרות כגון וכו'. משנה בסוף מעשרות (משנה ח'):\",1,0],[8,358,8,16,\"בד\\\"א בעם הארץ סתם וכו'. משנה בפרק עד כמה (בכורות דף כ\\\"ט:) וכרבי שמעון ואע\\\"ג דמתניתין לגבי חשוד להיות מוכר תרומה לשם חולין היא ילפינן מינה לחשוד על השביעית:\",1,0],[8,358,8,16,\"ואין לוקחין ממנו פשתן וכו' עד ולא על השביעית. משנה שם ולשון המשנה אבל לוקחין ממנו טווי ובגדים ופירש רבינו שם בגדים אלו שבכאן ר\\\"ל כעין בגדים כגון הגדילים שהם מעשה עבות מן הפשתן עצמו לא מן הטווי לפי שהואיל והתיר לקנות הטווי כל שכן הדבר העשוי מן הטווי עכ\\\"ל והוא פירוש לדברי הגמרא שם. וז\\\"ש שזור במקום בגדים השנוי שם במשנה, ובירושלמי (פ\\\"ה ה\\\"ג) סוף מעשרות ופשתן לאו קיסמין הוא א\\\"ר חיננא מפני זרעה וז\\\"ש רבינו שיש עליו זיקת שביעית:\",2,0],[8,358,8,17,\"כל החשוד על הדבר וכו': כתב הראב\\\"ד כבר כתבתי בפי\\\"ב מהל' מעשר שאין לסמוך על זה עכ\\\"ל וכבר כתבתי שם טעם רבינו:\",1,0],[8,358,8,18,\"הכהנים חשודים על השביעית לפי שהם אומרים וכו' לפיכך סאה תרומה וכו'. בפרק זה בורר (סנהדרין דף כ״ו):\",1,0],[8,358,8,19,\"הצבענין והפטמין וכו'. תוספתא פ\\\"ה דשביעית ובירושלמי פרק ט':\",1,0],[8,358,8,20,\"גבאי קופה בשביעית לא יהיו וכו'. תוספתא פ\\\"ג דדמאי:\",1,0],[8,358,8,20,\"ומותר ללוות מן העניים וכו'. פרק בתרא דע\\\"ז:\",2,0],[8,358,9,1,\"מצות עשה להשמיט המלוה וכו':\",1,0],[8,358,9,3,\"אין שמיטת כספים נוהגת מן התורה וכו' עד כדי שלא תשתכח וכו'. בפרק השולח גיטין (דף ל\\\"ו) וכרבי ונראה מדברי רבינו שמפרש שמה שאמרו שם בזמן שאתה משמט קרקע אתה משמט כספים ליובל קרי משמט קרקע שהרי שדות חוזרות לבעלים וכמו שכתב בסוף פרק עשירי אבל שמיטת קרקע אף בזמן הזה נוהגת מן התורה:\",1,0],[8,358,9,4,\"אין שביעית משמטת כספים אלא בסופה. בספרי ובערכין פרק המקדיש (ערכין דף כ״ח:):\",1,0],[8,358,9,5,\"שחט את הפרה וכו'. משנה בפרק בתרא דשביעית (משנה ב'):\",1,0],[8,358,9,5,\"וכתב הראב\\\"ד אישתמיטתיה מאי דאמור בירושלמי וכו'. וכתב בעל מגדל עוז שטעם רבינו מדמותיב מינה לרב יוסף בפרק שואל ודחיק לשנויי ולא דחי הא מני רבי יהודה היא עד כאן לשונו. ולי נראה שטעם רבינו משום דקשיא ליה היאך אפשר לומר דפליגי רבנן בההיא דהשוחט את הפרה דלא מקריא הקפת חנות אלא כשלקח ממנו כמה פעמים בהקפה אז אינו חוב עד שיזקפם עליו במלוה אבל אם לא לקח ממנו בהקפה אלא פעם אחת הרי הוא כשאר חוב ומשמט וכך נראה קצת מדברי רבינו בפירוש המשנה ואם כן הא דהשוחט את הפרה כרבנן נמי אתיא דמאחר שלא לקח ממנו אלא פעם אחת משמט ואם כן כי אמר רבי אלעזר דרבי יהודה היא היינו משום דמתניתין סתמא קתני אפילו חזר והקיף בו ביום ומשום הכי אסור דאי חזר והקיף ממנו בו ביום דמשמט היינו לרבי יהודה אבל כשלא הקיף ממנו אלא פעם זו על דעת לשלם לו קודם שיקח ממנו פעם אחרת לרבנן נמי אם היה החדש מעובר משמט ואם כן שפיר עבד רבינו דפסקה למשנה זו להלכה דפשטה בשלא הקיף ממנו אלא פעם זו על דעת לשלם לו קודם שיקח ממנו בהקפה פעם אחרת דלדברי הכל אם היה החדש מעובר משמט ועוד יש לומר שכיון שאינו יכול לפרוע בשעת המכר מפני שהוא יום טוב הרי הוא כאילו לא מכר לו בהקפה שאילו לא היה יום טוב היה פורעו מיד ואם כן הוי כאילו זקפה עליו במלוה עד שיגיע עת שיוכל לתובעו וכך נראה מדברי רבינו בפירוש המשנה וכן נראה מהירושלמי וא\\\"כ כרבי עקיבא אתיא:\",2,0],[8,358,9,6,\"שביעית משמטת את המלוה וכו'. בפ״י דשביעית (משנה א') תנן שביעית משמטת את המלוה בשטר ושלא בשטר ואיתמר עלה בפרק השולח (גיטין דף ל״ז) רב ושמואל דאמרי תרווייהו בשטר שיש בו אחריות נכסים שלא בשטר שאין בו אחריות נכסים וכל שכן מלוה על פה ור״י ור״ל דאמרי תרווייהו בשטר שטר שאין בו אחריות נכסים שלא בשטר מלוה ע״פ אבל שטר שיש בו אחריות נכסים אינו משמט כלומר דכיון ששיעבד לו קרקעותיו כגבוי דמי וכמי שהקרקעות בחזקת המלוה הם וגבויות ממש ואין כאן חוב תניא כוותיה דר״י ור״ל ש״ח משמט ואם יש בו אחריות נכסים אינו משמט תניא אידך סיים לו שדה אחת בהלואתו כלומר הראה בסימניה ומצריה וייחדה לו לגבותו כגבוי דמי ולא עוד אלא אפי' כתב כל נכסיו אחראין וערבאין אינו משמט כלומר אע״ג דלא דמי לגבוי כסיים ובתר הכי אמרינן דר״י פסק בשטר שיש בו אחריות נכסים דמשמט והקשו לו והא מר הוא דאמר אינו משמט והשיב וכי מפני שאנו מדמים כלומר נראה בעינינו וכמדומים אנחנו ולא שמענו מרבותינו נעשה מעשה כלומר להוציא ממנו בידים וההיא ברייתא דילמא ב״ש היא דאמרי שטר העומד ליגבות כגבוי דמי הרי שאפי' ר״י פסק דמשמט. וכתב הר״ן בשם הרמב״ן דסיים לו שדה בהלואתו נמי משמט דהא סבר האי תנא בכל שטר שיש בו אחריות נכסים שאינו משמט ואידחי ליה ואמרינן באי זהו נשך (דף ס״ז:) האי משכנתא באתרא דמסלקי שביעית משמטת וכ״ש סיים ואפשר דמוקי לה באפותיקי מפורש ולאו מילתא היא דאפילו הכי משמט [כלומר] כיון שיכול לסלקו כל שעה שירצה אבל הרמב״ם פסקה בפ״ט מה״ש ומשמע לי דס״ל דלא מדחינן אלא מאי דמידחי בגמרא בהדיא אבל סיים לו שדה כיון דלא מידחי לא מדחינן ליה עכ״ל והאריך לדחות ההיא דמשכנתא וכתב בעל התרומות בשער מ״ה הרמב״ם פסק כברייתא דקתני סיים לו שדה בהלואתו אינו משמט ומסתברא דמיירי באתרא דלא מסלקי עכ״ל:\",1,0],[8,358,9,6,\"והשביעית משמטת את השבועה. משנה בסוף פרק כל הנשבעין (שבועות דף מ״ה) ומייתי לה מדכתיב וזה דבר השמיטה ורבינו מייתי לה מלא יגוש ותניא בתוספתא דבר שהשביעית משמטתו משמטת שבועתו ודבר שאין השביעית משמטתו אינה משמטת שבועתו:\",2,0],[8,358,9,7,\"במה דברים אמורים בשבועת הדיינים וכו'. כן מתבאר מהתוספתא שכתבתי בסמוך וכן פירש\\\"י על המשנה שכתבתי בסמוך ושביעית משמטת את השבועה לאו אהך שבועה דשותפות קאי דאין שביעית משמטת שותפות ולא שבועתה ובזה אין מקום למה שכתב הראב\\\"ד כמדומה לי דבר זה הוציא מן הירושלמי וכו' ויש לדקדק בדברי רבינו שכתב אבל שבועת השומרים והשותפים וכיוצא בהם משבועות שאם יודה בהם ישלם הרי זה ישבע אחרי השמטה שהרי שבועת הדיינים אם יודה ישלם וא\\\"כ היאך כתב דשביעית משמטתה וצ\\\"ל דה\\\"ק אבל שבועת השומרים והשותפים שאם יודה ואח\\\"כ יעבור עליו שביעית ישלם ולא תהא משמטתו שביעית מפני שאינם דרך מלוה ואין שביעית משמטת אלא מלוה ה\\\"ז ישבע אחר השמיטה. ומכל מקום יש לגמגם על זה הירושלמי דהא משמע דרבנן פליגי ארבי מאיר ולמה פסק כיחידאה ואפשר דטעמא משום דסתם לן תנא כוותיה א\\\"נ י\\\"ל דליכא מאן דפליג אר\\\"מ דהא מקרא מלא הוא אלא משום דאיתמר משמיה בית מדרשא קבעוה בשמו:\",1,0],[8,358,9,8,\"הלוהו ותבעו וכפר בו וכו': כתב הראב\\\"ד הנה הוא סובר טעמא דחזר והודה וכו'. וי\\\"ל דלדעת רבינו שבמה שכתב הר\\\"ן בפרק הנשבעים לא תקשה לרבינו ממתניתין דשבועות דבמתניתין עסקינן שתבעו קודם שביעית והודה במקצת וכפר במקצת ואותו מקצת שכפר בו אין שביעית משמטתו כדאמרינן בירושלמי (שביעית פ\\\"י ה\\\"א) מלוה ונעשית כפרנית אינה משמטת וסד\\\"א כיון שתבעו קודם שביעית והודה במקצת וכפר במקצת ותביעת אותה מקצת במקומה עומדת שלא נשמטה בשביעית ישבע עליה לאחר שביעית קמ\\\"ל דשביעית משמטת שבועה זו דכיון שהשמיטה אותו מקצת שהודה בו נמצא שאינו אלא כופר בכל ואף השבועה מחמת אותו מקצת של הודאה נשמטה כיון שהממון נשמט אף הדיבור של שבועה שבא מכחו נשמט עכ\\\"ל:\",1,0],[8,358,9,8,\"וכתב הרא\\\"ש בתשובה סוף כלל פ\\\"ו על הירושלמי דכפרנית ונעשית מלוה משמטת קשיא להו מדתנן בפירקא בתרא דשביעית כל מעשה בית דין אינם משמטים ומפרש בירושלמי גזרי דיינים כגון התובע את חבירו וכפר לו והביא עדים וחייבוהו ב\\\"ד וכתבו לו פסק דין הוי כגבוי ואינו משמט וי\\\"ל דהא דכפרנית ונעשית מלוה מיירי שלא כתבו פסק דין לכך [לא] הוי כגבוי עכ\\\"ל. וכן נראה מלשון רבינו:\",2,0],[8,358,9,9,\"המלוה את חבירו וקבע לו זמן וכו'. מימרא בפרק קמא דמכות (דף ג') ופסק כלישנא בתרא וכן פסקו רבינו תם והרא\\\"ש והרמב\\\"ן וספר התרומות:\",1,0],[8,358,9,9,\"התנה עמו שלא יתבענו וכו'. ירושלמי פ\\\"י דשביעית. וכתב הר\\\"י קורקוס ז\\\"ל נ\\\"ל טעם הדבר שאע\\\"פ שאינו יכול לנגוש אותו כיון שהחוב מוטל עליו והוא חייב לפרוע בכל עת לצאת ידי שמים גם אם יתפוס המלוה משל הלוה יכול ליקח אותו בחובו קרינן ביה לא יגוש ולא דמי לקובע זמן שאין עליו שום חיוב בתוך הזמן:\",2,0],[8,358,9,10,\"המלוה את חבירו והתנה עמו וכו'. בפרק קמא דמכות מימרא דשמואל ע\\\"מ שלא תשמיטני שביעית שביעית משמטתו על מנת שלא תשמטני בשביעית אין שביעית משמטתו ופירש\\\"י שביעית משמטתו שהשביעית אינה מסורה בידו להתנות שלא תהא משמטת וכתב הרא\\\"ש בתשובה שלא תשמיטני בשביעית תנאי זה אגברא קאי ומועיל:\",1,0],[8,358,9,12,\"הקפת חנות וכו' שכר שכיר וכו' קנסות של אונס ומפתה וכו'. הכל משנה פ\\\"י דשביעית וכתב רבינו בפירוש המשנה הקפת חנות היא האמנה במקח ובממכר שבין בני אדם ובעלי החניות שיוציא עליו כל מה שצריך וכשיקבץ סך ממון עליו יפרעהו וזה הנקבץ לא יהיה נשמט בשנה השביעית מפני שאינו על דרך חוב ולא מכר לו בעל החנות על מנת שיהיה חוב אבל מכר לו מעט מעט עד שנתקבץ לו הכל ויתן לו ממונו עכ\\\"ל. ונראה לי שטעם הדבר שמאחר שדרך להקיף זמן אחר זמן ואינו נפרע ממנו עד שיזדמנו לו מעות ואין דרך לנוגשו הוי כאילו הלוהו עד אחר שביעית שאין שביעית משמטתו וזהו טעם שכר שכיר שאינו נשמט מפני שדרך לקבץ שכר שנה או שנתים ביד השוכר אותו ואינו נוגשו לתתם לו אבל הם בידו כפקדון או כהלוהו עד אחר השביעית. וכתב עוד רבינו בפירוש המשנה הקנסות שחייב הכתוב לאונס ומפתה ומוציא שם רע אינם כשאר חובות אבל הם חיובים שהאיש ההוא נתחייב בהם והאיש ההוא לא יהיה פטור עד שיפרעם עכ\\\"ל. ואיני יורד לסוף חילוק זה דגם הלוה מחבירו חייב הוא לפורעו אלא שהשביעית משמטתו ואפשר לומר שמאחר שכתובים בתורה הוה ליה כגבויים או כמסורים ביד בית דין:\",1,0],[8,358,9,12,\"ומ\\\"ש רבינו ומאימתי נזקפין וכו'. בפ\\\"ב דגיטין (דף י\\\"ח):\",2,0],[8,358,9,13,\"המגרש את אשתו וכו'. בפ\\\"ב דגיטין פלוגתא דרב ושמואל ופסק כשמואל דהלכתא כוותיה בדיני:\",1,0],[8,358,9,14,\"המלוה על המשכון. משנה פ\\\"י דשביעית (משנה ב').\",1,0],[8,358,9,14,\"ומ״ש והוא שיהיה החוב כנגד המשכון וכו'. כתב רבינו שמשון שם בירושלמי אמר שמואל אפילו על המחט דכתיב אשר יהיה לך את אחיך תשמט ידיך פרט שיש לאחיך בידך והיינו כרשב״ג דס״פ שבועת הדיינים דאמר אע״פ שאינו שוה אלא פלג אינו משמט עכ״ל. וכ״כ הרא״ש בפרק השולח והשתא קשה על רבינו למה פסק והוא שיהיה החוב כנגד המשכון וכו' ונ״ל שטעמו משום דההיא דס״פ שבועת הדיינים (שבועות דף מ״ד:) הכי איתא לימא כתנאי המלוה [את חבירו] על המשכון ונכנסה שמטה אף ע״פ שאינו שוה אלא פלג אינו משמט דברי רשב״ג רבי יהודה הנשיא אומר אם היה משכונו כנגד חובו אינו משמט ואם לאו משמט מאי אינו משמט דקאמר תנא קמא אילימא כנגדו מכלל דרבי יהודה הנשיא סבר כנגדו נמי משמט אלא אמאי תפיס משכון אלא לאו כנגד כולו ובדשמואל קמיפלגי לא לעולם כנגדו ובהא קא מיפלגי תנא קמא סבר כנגדו [אינו משמט] רבי יהודה הנשיא סבר כנגדו נמי משמט ודקא אמרת למאי תפיס ליה משכון לזכרון דברים בעלמא. והשתא יש לתמוה על רבינו שמשון והרא״ש דנקטי בפשיטות דלרשב״ג אפילו אינו שוה אלא פלג משמט כל החוב דהא קאמרה גמרא לעולם כנגדו ואף ע״ג דדרך דחייה איתמר מ״מ לא מיפשט פשיטא מילתא דלרשב״ג משמט כולו ורבינו סובר דנקטינן כהאי אוקימתא דתנא קמא סבר כנגדו משום דלאוקימתא קמייתא קם ליה שמואל כרשב״ג ורבינו פסק ברפ״י משכירות דלא כשמואל ובפלוגתא דתנאי אית לן למינקט כרשב״ג לגבי רבי יהודה הנשיא הילכך ע״כ לומר דנקיטינן כאוקימתא דתנא קמא סבר כנגדו ומהירוש' (שביעית פ״י ה״א) דאמר שמואל אפילו על המחט אין ראיה דשמואל לטעמיה אזיל דאמר אבד קתא דמגלא אבד אלפא זוזי ולית הלכתא כוותיה ועוד דמשמע דבירושלמי גופיה פליגי עליה דשמואל דלא גרסינן דכתיב אלא הכי גרסינן אשר יהיה לך את אחיך וכו' ולאו מדברי שמואל הוא אלא מדברי מאן דפליג עליה וה״ק דינא דמשכון לא ילפינן ליה אלא מפרט לשל אחיך בידך והיינו כנגד מה שיש לאחיך בידך דוקא לא על יותר ממה שיש לאחיך בידך ובכן עלו דברי רבינו על נכון ודעת הר״ן כדעת רבינו שכתב בפרק השולח כי אמרינן דאינו משמט דוקא כנגד החוב אבל מה שהחוב יתר על המשכון משמט דהכי מסקינן בפ' שבועת הדיינים עכ״ל:\",2,0],[8,358,9,15,\"המוסר שטרותיו לבית דין וכו'. שם במשנה:\",1,0],[8,358,9,15,\"וכן בית דין שחתכו את הדין וכו'. גם זה משנה וכל מעשה בית דין אינן משמטין ובירושלמי מעשה בית דין אלו גזרי דיינים:\",2,0],[8,358,9,16,\"כשראה הלל הזקן וכו'. משנה שם (מ\\\"ג):\",1,0],[8,358,9,16,\"כתב הראב״ד אבל שמטה של תורה אין הפרוזבול מועיל לו א״א זה אינו מחוור דאביי הוא דאמר הכי וכו' טעמו דבפרק השולח (גיטין דף ל״ו) מקשה מי איכא מידי דמדאורייתא משמטא שביעית ותקין הלל דלא משמטא אמר אביי בשביעית בזמן הזה [דרבנן] וכו' ומי איכא מידי דמדאורייתא לא משמטא שביעית ותקון רבנן דמשמט ותירץ אביי שב ואל תעשה שאני רבא אמר הפקר בית דין הפקר. והראב״ד מפרש כרש״י שפירש דשינויא דרבא קאי גם למאי דאקשי ברישא ומי איכא מידי דמדאורייתא משמטא אבל רבינו נראה שמפרש כפי' התוספות דלא קאי אלא למי איכא מידי דמדאורייתא לא משמטא ורבנן תקינו דלשמיט וטעמא דכיון שאין הממון בידו הפקירוהו ב״ד אבל להוציא מידו שלא כדין תורה כלומר אילו היתה שמיטת כספים דאורייתא לא הוו מתקני להוציא מידו ע״י הפקר אבל קושיא קמייתא דמי איכא מידי דמדאורייתא משמטא לא מיתרצא אלא כדאביי:\",2,0],[8,358,9,17,\"אין כותבין פרוזבול וכו'. בפרק השולח (גיטין דף ל\\\"ז):\",1,0],[8,358,9,17,\"וכתב הר\\\"ן ומכל מקום בית דין דרבי אמי ורבי אסי לאו דוקא אלא הוא הדין לכל בית דין חשוב שבדור וכן כתבו בתוספות שר\\\"ת כתב פרוזבול מטעם זה עכ\\\"ל וכ\\\"כ הרא\\\"ש בתשובה וכ\\\"כ הריב\\\"ש בשם הרשב\\\"א וכתב שכן נראה מדברי הרי\\\"ף שכתב סתם דיני פרוזבול וכן נראה דעת רבינו ממה שכתב אלא חכמים גדולים ביותר ולא סתם וכתב אין כותבין פרוזבול אלא בבית דין של רבי אמי ורבי אסי כלישנא דגמרא ועוד שכתב שהם ראויים להפקיע ממון וכיון דכל בית דין חשוב שבדור ראוי להפקיע ממון ממילא משמע דכל בית דין חשוב שבדור הוי כבית דין של רבי אמי ורבי אסי וכן משמע עוד ממ\\\"ש בסמוך גבי תלמידי חכמים שהלוו זה את זה:\",2,0],[8,358,9,18,\"זהו גופו של פרוזבול וכו'. משנה פרק עשירי דשביעית (משנה ד'):\",1,0],[8,358,9,19,\"אין כותבין פרוזבול וכו'. גם זה משנה ו' שם.\",1,0],[8,358,9,19,\"ומה שכתב אפי' קלח של כרוב השאילו מקום לתנור או לכיריים וכו' בפרק השולח:\",2,0],[8,358,9,19,\"היתה לו שדה ממושכנת בעיר כותבין עליה פרוזבול. גם זה במשנה שם היתה לו שדה ממושכנת בעיר כותבין עליה פרוזבול ופירש שם רבינו דאפי' היא ממושכנת במשכנתא דסורא דכתבי במישלם שנייא אילין תיפוק ארעא דא בלא כסף ואין לו בה רשות עד שישלם הזמן אפילו הכי כותבין עליה פרוזבול ואף על גב דמתניתין קתני ממושכנת בעיר נראה דאורחא דמילתא נקט ולאו דוקא ולפיכך השמיט רבינו תיבת בעיר:\",3,0],[8,358,9,21,\"כותבין לאיש על נכסי אשתו וכו'. גם זה במשנה שם בשם רבי חוצפית וכתב שם רבינו רבי חוצפית איני רואה חולק עליו:\",1,0],[8,358,9,21,\"אין לו קרקע וכו' היה לו חוב על חבירו וכו'. ברייתא פרק השולח (גיטין דף ל״ז).\",2,0],[8,358,9,21,\"ומה שכתב אחד שלוה מחמשה וכו' עד פרוזבול א' לכולן. גם זה משנה בפ\\\"י דשביעית (משנה ה'):\",3,0],[8,358,9,23,\"כתב הפרוזבול תחלה וכו'. בתוספתא אלא ששנויה בהיפך ונראה שט\\\"ס הוא שהטעם מהופך וקל להבין:\",1,0],[8,358,9,23,\"ומה שכתב לפיכך פרוזבול המוקדם כשר וכו'. במשנה שם:\",2,0],[8,358,9,24,\"המוציא שטר חוב וכו' ואם אמר פרוזבול היה לי ואבד וכו'. ולא עוד וכו' אומרים לתובע היה לך פרוזבול ואבד וכו'. מימרא פרק השולח (גיטין דף ל״ז):\",1,0],[8,358,9,24,\"ומ\\\"ש שמזמן הסכנה ואילך וכו'. משנה ס\\\"פ הכותב (כתובות פ\\\"ט) ב\\\"ח שהוציא ש\\\"ח ואין עמו פרוזבול הרי אלו לא יפרעו רשב\\\"ג אומר מן הסכנה ואילך וכו' ב\\\"ח גובה שלא בפרוזבול ונראה מדברי רבינו כאן ובפירוש המשנה שהוא מפרש שבזמן הסכנה דהיינו שגזרו עכו\\\"ם גזירה על המצות היו יריאים לשמור פרוזבוליהם התקינו שיהא המלוה נאמן לומר פרוזבול היה לי ואבד ואע\\\"פ שעבר הגזירה נאמן לומר פרוזבול היה לי ואבד שלא לחלק בין זמן לזמן ור\\\"ש בן גמליאל מפרש הוא והלכה כמותו ואת\\\"ל שהוא חולק הא קי\\\"ל כל מקום ששנה רשב\\\"ג במשנתנו הלכה כמותו:\",2,0],[8,358,9,24,\"והיתומים אינם צריכים פרוזבול. מימרא בפרק השולח (גיטין דף ל״ז):\",3,0],[8,358,9,26,\"הוציא פרוזבול וטען הנתבע וכו' עד ואוכל דבר אסור. נלמד ממה שנתבאר שנאמן לומר פרוזבול היה לי ואבד:\",1,0],[8,358,9,27,\"תלמידי חכמים שהלוו זה את זה. בפרק השולח רבנן דבי רב אשי מסרי מילייהו להדדי. כתב הראב\\\"ד דבריו סותרים זה את זה עכ\\\"ל. כלומר שהוא כתב לעיל שאין כותבין פרוזבול אלא חכמים גדולים ביותר כבית דינו של רבי אמי ורבי אסי שהם ראויים להפקיע ממון בני אדם אבל שאר בתי דינין אין כותבין וי\\\"ל שכבר כתבתי שדעת רבינו דב\\\"ד דרבי אמי ורבי אסי לאו דוקא אלא שהם גדולים בדורם כרבי אמי ורבי אסי בדורם דכל ב\\\"ד חשוב בדור ראוי להפקיע ממון וכותב פרוזבול דיפתח בדורו כשמואל בדורו ורבנן דרב אשי היינו גדולי בני בית דינו והיו חשובים להפקיע ממון ורבינו לא חשש לכתוב כאן שצריך שיהיו ב\\\"ד חשוב שסמך על מה שכתב בפרק זה ולא בא כאן אלא להשמיענו שתלמידי חכמים שהלוו זה את זה אינם צריכים כתיבה ובמסירת דברים סגי ותלמידים שכתב היינו תלמידים מב\\\"ד חשוב שבדור וכרבנן דבי רב אשי:\",1,0],[8,358,9,29,\"כל המחזיר חוב וכו' אמר לו אע\\\"פ כן וכו'. משנה פרק י' דשביעית (מ\\\"ח וט'):\",1,0],[8,358,9,29,\"ומה שכתב וצריך המלוה לומר וכו' ואל יאמר לו בחובי וכו' החזיר לו חובו וכו'. בפרק השולח (גיטין דף ל״ז) ודברי רבינו במה שכתוב בגמרא ותלי ליה עד שיאמר לו אעפ״כ שלא כפירוש רש״י אלא קרוב לפירוש הערוך:\",2,0],[8,358,9,30,\"מי שנמנע מלהלוות וכו'. מבואר בתורה ובפ\\\"י דשביעית (מ\\\"ג) שנינו כשראה הלל שהיו העם נמנעים מלהלוות זה את זה ועוברים על מה שכתוב בתורה השמר לך פן יהיה דבר עם לבבך בליעל וכו'.\",1,0],[8,358,9,30,\"ומה שכתב וכל מקום שנאמר השמר או פן או אל וכו'. בפ' השוחט והמעלה (זבחים דף ק\\\"ו):\",2,0],[8,358,10,3,\"מצות עשה לספור שבע שנים וכו' ומאימתי התחילו למנות מאחר י\\\"ד שנה וכו'. בפ\\\"ב דערכין (דף י\\\"ב:).\",1,0],[8,358,10,3,\"ומ\\\"ש שנאמר שש שנים תזרע שדך כלומר דלא קרינן שביעית אלא היכא דהוי שדך המיוחד לך ועד שעברו שבע שכבשו ושבע שחלקו לא היה שדה מיוחד לכל אחד:\",2,0],[8,358,10,3,\"ומ\\\"ש י\\\"ז יובלים משנכנסו לארץ וכו' עד ושנת ל\\\"ו ביובל היתה. בפרק בתרא דערכין:\",3,0],[8,358,10,3,\"כתב הראב\\\"ד י\\\"ז יובלים מנו ישראל א\\\"א זה הוא לדעת רבי יהודה וכו'. כלומר ואם כן קשיא דידיה אדידיה כי כתב י\\\"ז יובלות מנו דהוי אליבא דר\\\"י וכתב ששנת ל\\\"ו היתה שנה שחרב בה הבית דהוי אליבא דרבנן ותירץ הר\\\"י קורקוס אמת הוא כי שם בגמרא הביאו ברייתא זו להקשות ממנה למאי דאוקימנא ברייתא אחרת שאמרו בה וכן בשניה פירוש שגם בית שני חרב במוצאי שביעית כר' יהודה דאמר שנת חמשים עולה לכאן ולכאן דבית שני עמד ת\\\"כ שנה שמונה יובלות ועשרים שנה הוצא שמונה שנים משמנה יובלות נמצא כ\\\"ח שנים שהם ד' שמטות נמצא שבמוצאי שביעית חרב בית שני ועל זה מקשה אי ברייתא ר' יהודה קשיא בית ראשון דלדידיה בית ראשון לא חרב במוצאי שביעית דתניא י\\\"ז יובלות וכו' ואילו לר' יהודה הוסף י\\\"ז שנה של י\\\"ז יובלות נמצא בשלש בשבוע חרב הבית אבל לא מפני זה אתיא ברייתא כר' יהודה דוקא דלעולם כר\\\"ע אתיא ולאו דוקא י\\\"ז שנים של יובל אלא מנין יובלות קאמר וכיון שמן היובל הי\\\"ז מנו רובו חשיב ליה שהרי לא אמרו י\\\"ז יובלות עשו דודאי לא עשו אלא ט\\\"ז אבל מנין י\\\"ז הם אע\\\"ג דבצרי להו י\\\"ד שנה מ\\\"מ כיון שמן הי\\\"ז מנו ל\\\"ו שנה שפיר שייך למיתני י\\\"ז יובלות מנו דמנין י\\\"ז מנו וכן נראה מלשון רש\\\"י דברייתא כר\\\"ע אתיא ובודאי דכיון דסתמא מיתניא אין להעמיד אותה כיחידאה ומנו קתני ולא עשו כאשר דקדקתי ומנו רוב יובל הי\\\"ז קאמר ובפירוש כתבו התוספות שם דההיא ברייתא אתיא כרבנן דלר' יהודה לא אתיא מה שאמרו שם בברייתא שאם אתה אומר משנכנסו מנו נמצא בית חרב בתחלת יובל מוכח דלרבנן שייך לומר י\\\"ז יובלות מנו עכ\\\"ל.\",4,0],[8,358,10,3,\"ומ\\\"ש נמצאת אומר בשנת אלפים ותק\\\"ג וכו' כל זה מבואר בהקדמה ששנה שיצאו בה ישראל ממצרים היתה שנת אלפים ותמ\\\"ח ליצירה כדאיתא בפרק קמא דע\\\"ז עלה ט' ומ' שנה שהיו במדבר וי\\\"ד שכבשו וחלקו סך שני אלפים ותק\\\"ב ומשנה שאחריה התחילו למנות.\",5,0],[8,358,10,3,\"ומ\\\"ש מר\\\"ה מאחר מולד אדם הראשון שהיא שנה שניה ליצירה כלומר שהעולם התחיל להבראות בכ\\\"ה לאלול למולד בהר\\\"ד שהוא מולד תהו ואדם הראשון נברא ביום ו' והוא ר\\\"ה ומולדו וי\\\"ד וקאמר רבינו שכשאנו מונים כך שנים לבריאת עולם הוא מר\\\"ה של מולד וי\\\"ד ולא מר\\\"ה של מולד בהר\\\"ד שהוא מולד תהו שבאותה שנה התחילה היצירה שאין אנו חוששין אלא על יצירת האדם שהוא עיקר בריאת העולם.\",6,0],[8,358,10,3,\"ומ\\\"ש רבינו שת\\\"י שנים עמד בית ראשון כלומר מאחר שכתוב שבת\\\"פ שנים ליציאת מצרים נבנה הבית והבית עמד ת\\\"י שנים סך תת\\\"צ הוצא מהם מ' שנה שהלכו במדבר ישארו תת\\\"נ שהם שיעור י\\\"ז יובלות הוצא מהם י\\\"ד שכבשו ושחלקו נשארו תתל\\\"ו נמצא שחרב הבית בשנת ל\\\"ו ליובל והיא שנה שאחר שמטה ולפיכך קראה מו\\\"ש שהרי שנת ל\\\"ה ביובל היתה שמטה:\",7,0],[8,358,10,3,\"כיון שחרב הבית וכו' ובשנה השביעית מבנינו עלה עזרא וכו' ומשנה זו התחילו למנות. בפרק ב' דערכין (דף י\\\"ב י\\\"ג) וכרב אשי.\",8,0],[8,358,10,3,\"ומ\\\"ש אע\\\"פ שלא היתה שם יובל בבית שני מונין היו אותו כדי לקדש שמטות. בפרק בתרא דערכין (דף ל\\\"ב ל\\\"ג) ופי' רש\\\"י ודאי יובל לא היה נוהג שיהו עבדים נפטרים משום יובל ולא שדות של מוכר חוזרות אבל שמיטין היו נוהגים לשמט כספים ולשמט מזרע וקציר דהא צריכים למנות שנת יובל כדי שיבואו השמיטין במקומם שלסוף שבע השמטות היו מניחים שנת החמשים שלא היו מונים אותה לשמטה הבאה מפני שהיא ראויה להיות שנת יובל ושנה שלאחריה מתחיל המנין דאם לא היו מונים יובלות היו מונים אותה שנה לחשבון השמיטין והיו השמיטין שלא במקומן:\",9,0],[8,358,10,4,\"נמצאת למד שהשנה שחרב בה הבית באחרונה. כלומר כשאתה מונה שנה מיום החרבן עד י\\\"ב חדש שכל מה שאירע באותה שנה מיקרי שאירע בשנת החרבן כשאתה תופס תחלתה מתשרי שאחר חרבן כשני חדשים אותה שנה מוצאי שביעית היתה ושנת ט\\\"ו מן היובל הט' היתה והטעם שמונין מתשרי שממנו הוא המנין לשמיטין ויובלות. והכי אסיק רב אשי שבית שני נמי במוצאי שביעית חרבה והוצרך רבינו לפרש כמו שכתבתי ששנה שחרב בשניה פירושו כשאתה מונה מיום החרבן י\\\"ב חדש וכו' הוא כדי שיצדק לומר שגם בשניה חרב במוצאי שביעית והחשבון מבואר שבית השני עמד ת\\\"כ שנים הוצא שש קודם שעלה עזרא נשארו תי\\\"ד הוצא המאות ליובלות נשארו י\\\"ד נמצא שתשרי שאחר החרבן היא שנה ראשונה של שמטה שלישית דהיינו מוצאי שביעית וט\\\"ו ליובל וגירסת רבינו נראה לי שהיא גירסת רש\\\"י אלא שאין כתוב בה ונטפי חד שתא וכך היא גירסת ספרים ישנים ומוגהים כפי מה שהעיד בעל כפתור ופרח.\",1,0],[8,358,10,4,\"ומ\\\"ש ולפי חשבון זה שנה זו שהיא אלף ק\\\"ז לחרבן וכו' כלומר מאחר שהקדמנו ששנה שמתחלת תשרי שאחר חרבן היתה שנה ראשונה של שמטה כשתוציא אלף ק\\\"ז המאוחרות ליובלות ישארו בידך ז' והשביעית היא שנת שמטה שדעת רבינו שגם אחר חרבן בית שני מנו יובלות לקדש שמיטין דלענין זה כך לי אחר חרבן כמו קודם חרבן כרבנן דסברי הכי:\",2,0],[8,358,10,5,\"ומה שכתב אבל כל הגאונים אמרו וכו' שלא מנו באותם ע' שנה וכו' אלא שמטות בלבד בלא יובל. לשון זה קשה בעיני דמאי נ\\\"מ בין זה למ\\\"ש רבינו בתחלה נשארה הארץ חריבה ע' שנה כלומר ולא נמנו כלל ולא התחילו למנות עד שנה שביעית לבנין ואם כן לא מנו בהם יובל גם לאותו דרך וכן קשה מה שכתב וכן משחרב באחרונה לא מנו שנת החמשים אלא שבע שבע בלבד שנראה שלדרך הראשון גם משחרב מנו יובלות ורבינו כתב בדרך הראשון אע\\\"פ שלא היה שם יובל בבית שני מונים היו אותו כדי לקדש שמטות משמע לכאורה דבבית שני דוקא עשו כן אבל אחר שחרב לא מנו יובלות ומיהו בהא איכא למימר דלענין זה כך לי אחר חרבן כמו קודם חרבן שאע\\\"פ שלא היה יובל נוהג מנו אותו כדי לקדש שמיטין ובכן יצא החשבון מכוון כמו שכתבתי לעיל אבל קמייתא קשיא. וצ\\\"ל דהכי קאמר אבל הגאונים אמרו שאע\\\"פ שחרב הבית לא בטל מנין השמיטין אבל לא היו מונין יובלות אבל שמיטין היו מונין בין בזמן חרבן בית ראשון בין בזמן בית שני בין לאחר חרבנו הילכך כיון ששנה שחרב בה הבית היתה מוצאי שביעית שהיא שנה ראשונה של שמטה כשאתה מונה ע' של חרבן ות\\\"כ שעמד בית שני ואלף ק\\\"ז מזמן חרבן בית שני שעולה הכל אלף תצ\\\"ו תחלקם לשביעיות האלף ות' הם מאתים שמטות והקצ\\\"ו הם כ\\\"ח שמטות נשאר בידך אחת והיא שנה ראשונה של שמטה דהיינו מוצאי שביעית. ואע\\\"פ שדברי רבינו באו בכאן בקיצור בתשובה באו מבוארים יותר שכתב וז\\\"ל אבל מצאנו תשובה לגאון רבינו האי ז\\\"ל ענינה שמנין ראשון לא בטל ושעליו אנו סומכים אבל לא מנו יובלות משחרב הבית ראשונה אלא שמיטין בלבד. ואמר באותה תשובה שהחשבון הזה ירושה הוא בידיהם ושהיא סדורה בפי הכל וכך נמצא בתשובה שקודם רבינו האי ז\\\"ל מכמה שנים כדברי הגאון ולפי חשבון זה נמצא הבית חרב במו\\\"ש כמו שאמרנו ותהיה שנה שהיא תפ\\\"ו לשטרות שנת שמטה והביא הראיה מהא דאמרינן בתחלת ע\\\"ז האי מאן דבעי למידע כמה שני בשבוע וכו' דש\\\"מ לא מנינן יובל אלא ז' ז' בלבד מונה ולא השגיח על הדברים שנתפרשו במסכת ערכין כאילו אינם כתובים והדברים מראים דהאי מימרא וחושבנא דיליה אליבא דמ\\\"ד עזרא לא קידש אלא זכר בעלמא עבד וקדושה ראשונה קדשה לשעתה וקדשה לעתיד לבא ואזיל מימרא קמא דאמרינן והוא דסליק אליבא דשמעתא ממסכת ערכין אליבא דמ\\\"ד עזרא קידש וקדושה ראשונה קדשה לשעתה ולא קידשה לעתיד לבא ודבר זה נחלקו בו התנאים והאמוראים כמו שנתבאר בגמ' שבועות פ\\\"ב ובכמה מקומות בגמרא אזלא שמעתא כמ\\\"ד לא קידש עד כאן לשונו. ולע\\\"ד נראה שאם טעם הגאונים משום דסבירא להו כמ\\\"ד קדושה ראשונה קידשה גם לעתיד לבא כלומר ומש\\\"ה אע\\\"פ שחרב הבית בראשונה לא בטלה קדושתה הילכך לא בטל מנין ראשון כיון שקדושתה לעולם קיימת מה נשתנה קודם חרבן ששנת יובל לא היתה נכנסת במנין השמטות וכרבנן דאמרי הכי ואחר שחרב הבית עשו כר' יהודה ולא מנו אלא שבע שבע וכן יקשה אם תאמר שקידשה לעתיד לבא. וע\\\"ק דמה ענין קידשה לעתיד לבא או לא קידשה לענין זה דהא שמטת קרקעות נוהגת היא אע\\\"פ שחרב הבית וכמבואר בדברי רבינו רפ\\\"ט וכפי פירוש רבינו ופירוש ר\\\"ת דבזמן שאתה משמט קרקעות היינו יובל אבל שמטת קרקעות לעולם נוהגת מן התורה מיהו בהא איכא למימר דבהכי תליא מילתא אבל קמייתא קשיא. לכך נראה לי שטעם הגאונים דסבירא להו דבזמן שהיובל נוהג עבדו כרבנן ואין היובל נכנס במנין השמטות שמאחר שקדושת היובל לחוד וקידוש השמטה לחוד אינו בדין שיכנס היובל בכלל שני שבוע אבל כשאין היובל נוהג כיון שאין קדושה נוהגת בשנת החמשים יותר מבשאר שנים דין הוא שיכנס היובל בכלל שני שבוע כיון שאין לו קדושה ולכך משחרב הבית בראשונה לא מנו אלא שבע שבע ואע\\\"פ שנבנה הבית מאחר שלא היה יובל נוהג מפני שאין יושביה עליה ואע\\\"ג דאמרינן בסוף ערכין מנו יובלות לקדש שמיטין כבר אמרו שם דאתיא כרבנן דסברי דאף בזמן שאין היובל נוהג אין שנת החמשים עולה מן המנין ואע\\\"פ שנראה מסוגיא דגמרא דרבנן ורבי יהודה פליגי בין בזמן שהיובל נוהג בין בזמן שאינו נוהג ונמצא שסברא זו שאני כותב לדעת הגאונים היא דלא כמאן אפשר לומר דגמרא רצה להשיב למקשה לפי שטתו אבל לפי האמת רבנן לא אמרו אלא בזמן שהיובל נוהג דוקא אבל בזמן שאין היובל נוהג לא וההיא דאמרו בסוף ערכין דכשגלו שבט ראובן ושבט גד לדעת רבנן דאי קידשה לעתיד לבא נוהגת שמטה מן התורה מנו יובלות לקדש שמיטין לא קשיא דאיכא למימר דשאני התם שהיו מצפים שיחזרו כמו שחזרו לבסוף ולפיכך לא ראו להפסיק סדר היובלות ואפשר לומר עוד שלא אירע יובל באותם שנים ששהו והא דקאמר משגלו שבט ראובן ושבט גד בטלו יובלות לא בטלו ממש קאמר אלא היו ראויים ליבטל אילו לא חזרו קאמר ואפשר שבאיזה מקום מצאו הגאונים גילוי לפרש כן כדרבנן או אפשר שהיא סברא שלישית מצאוה הגאונים בשום מקום.\",1,0],[8,358,10,5,\"ומה שכתב אבל כל הגאונים אמרו וכו' וכן משחרב באחרונה וכו' וכן עולה מגמרת ע\\\"ז וכו' כלומר מדאמרינן בפ\\\"ק דע\\\"ז (דף ט':) האי מאן דלא ידע בכמה בשבוע הוא עומד וכו' ונחשוב כללי ביובלי ופרטי בשבועי ונשקול ממאה תרתי ונשדי אפרטי ונחשובינהו לפרטי בשבועי וידע כמה שני בשבוע ומדקאמר ונשקול ממאה תרי דהיינו שתים של יובל משמע בהדיא שלא מנו אלא שמטות בלבד בלא יובל וכרבי יהודה:\",2,0],[8,358,10,5,\"כתב הראב\\\"ד ושנת השמטה ידועה היא וכו' א\\\"א הגאונים שאמרו שאין מונים משנת החרבן וכו'. ואני כבר ביארתי דעת הגאונים באר היטב ע\\\"פ דברי רבינו בתשובה והפירוש שפירש הראב\\\"ד בו ונשקול מכל מאה תרתי בקשתי לו חבר ולא מצאתיו:\",3,0],[8,358,10,6,\"ולפי חשבון זה תהא שנה זו שהיא אלף וק\\\"ז לחרבן מוצאי שביעית. כלומר מאחר שנתבאר שהחרבן היה בשנת השמטה כשתחלק אלף ומאה ליובלות יותרו בידך כ\\\"ב שנים תוסיף עליהם שבע הנשארים הרי הם כ\\\"ט הכ\\\"ח הם ד' שמטות ישאר בידך אחת והיא תחלת שמטה שהיא מוצאי שביעית והיא שנת ד' אלפים ותתקל\\\"ו ליצירה נמצא לפי זה ששנת ה' אלפים ושלש מאות ועשרים ושבע היא שמטה וכך המנהג פשוט:\",1,0],[8,358,10,7,\"שנת יובל וכו'. בפרק ב' דערכין (דף י\\\"ב) ובפרק קמא דראש השנה (דף ט') ובפרק קונם יין וכרבנן דפליגי אדרבי יהודה דאמר שנת חמשים עולה לכאן ולכאן ואזדא לטעמיה שכתב בתחלה קודם סברת הגאונים שמנו יובלות לקדש שמיטין בין בזמן בית שני בין אחר שחרב כי על פי כן יצא לו ששנת אלף וק\\\"ז לחרבן היתה שנת שמטה לפי אותה סברא:\",1,0],[8,358,10,8,\"משגלה שבט ראובן וכו' והוא שלא יהיו מעורבבין וכו'. בפרק בתרא דערכין (דף ל\\\"ב):\",1,0],[8,358,10,9,\"ובזמן שהיובל נוהג נוהג בח\\\"ל וכו'. בספ\\\"ק דקידושין (דף לח:) שילוח עבדים חובת הגוף היא כלומר ופשיטא שנוהג בח\\\"ל ומשני סד\\\"א הואיל דכתיב וקראתם דרור בארץ בארץ אין בח\\\"ל לא ת\\\"ל יובל היא מכל מקום אם כן מה תלמוד לומר בארץ בזמן שהדרור נוהג בארץ נוהג בח\\\"ל ואיתיה בפרק קמא דר\\\"ה (דף ט').\",1,0],[8,358,10,9,\"ומה שכתב שבזמן שהיובל אינו נוהג אין דין ע״ע ודין בתי ערי חומה ודין שדה אחוזה ודין שדה חרמים ואין מקבלים גר תושב. בערכין ס״פ המקדיש שדהו (ערכין דף כ״ט):\",2,0],[8,358,10,9,\"ומה שכתב חוץ משביעית בארץ וכו'. לא קאי אלא לשמטת כספים דאילו שביעית בארץ אף בזמן הזה הוא מה\\\"ת כמו שכתבתי ברפ\\\"ט:\",3,0],[8,358,10,10,\"מצות עשה לתקוע בשופר בעשירי בתשרי וכו' עד תעבירו שופר. ר\\\"פ בתרא דר\\\"ה (דף ל').\",1,0],[8,358,10,10,\"ומ\\\"ש ותוקעין בשופר תשע וכו'. משנה פ\\\"ג דר\\\"ה (דף כ\\\"ו:) שוה היובל לר\\\"ה לתקיעה ולברכות ובפרק בתרא דר\\\"ה (דף ל\\\"ד) יליף מקראי שהן ט' תקיעות.\",2,0],[8,358,10,10,\"ומ\\\"ש ומעבירים שופר בכל גבול ישראל. מדכתיב תעבירו שופר בכל ארצכם:\",3,0],[8,358,10,11,\"שופר של יובל ושל ר\\\"ה אחד הוא לכל דבר וכו'. משנה פ\\\"ג דר\\\"ה (דף כ\\\"ו:).\",1,0],[8,358,10,11,\"ומה שכתב אלא שביובל תוקעין בין בב\\\"ד שקדשו בו את החדש וכו' עד אלא בפני ב\\\"ד. שם (דף ל'):\",2,0],[8,358,10,13,\"שלשה דברים מעכבים ביובל וכו'. בפרק קמא דראש השנה עלה ט' ע\\\"ב וכחכמים:\",1,0],[8,358,10,14,\"ומ\\\"ש מר\\\"ה ועד יוה\\\"כ לא היו עבדים נפטרים וכו'. שם עלה ח' ע\\\"ב:\",1,0],[8,358,10,16,\"דין היובל בשביתת הארץ וכו' יתירה שביעית על היובל וכו'. בת\\\"כ פרשת בהר ובסיפרי פרשת ראה:\",1,0],[8,358,10,16,\"יובל משמיט קרקע בתחלתו וכו'. בערכין פרק המקדיש (ערכין דף כ״ח):\",2,0],[8,358,11,1,\"ארץ ישראל המתחלקת לשבטים וכו'. ואם מכר לצמיתות שניהם עוברים בלא תעשה ואין מעשיהם מועילים וכו':\",1,0],[8,358,11,2,\"והמוכר שדה לששים שנה וכו'. [בבא מציעא דף ע\\\"ט]:\",1,0],[8,358,11,3,\"לא ימכור אדם את ביתו וכו' אא\\\"כ העני אבל למכור ולהניח הדמים בכיסו וכו'. ת\\\"כ פרשת בהר סיני.\",1,0],[8,358,11,3,\"ומה שכתב ואם עבר ומכר מ\\\"מ וכו'. בתוספתא פרק חמישי דערכין:\",2,0],[8,358,11,4,\"דין מוכר שדה אחוזתו וכו'. מפורש בכתוב לפי רוב השנים תרבה מקנתו וכו' וכתיב וחשב את שני ממכרו והשיב את העודף לאיש אשר מכר לו:\",1,0],[8,358,11,5,\"לא גאלה וכו'. מפו' בכתוב ואם לא מצאה ידו די השיב לו והיה ממכרו ביד הקונה אותו עד שנת היובל ויצא ביובל ושב לאחוזתו:\",1,0],[8,358,11,6,\"מכרה לו והיא מלאה פירות וכו'. משנה וברייתא בפירקא בתרא דערכין:\",1,0],[8,358,11,7,\"הקנים והזמורות וכו'. בתוספתא דערכין פרק חמישי:\",1,0],[8,358,11,8,\"הלוקח שדה אחוזה וכו'. במציעא פ' המקבל (בבא מציעא דף ק״ט):\",1,0],[8,358,11,9,\"המוכר את שדהו וכו'. משנה ר\\\"פ בתרא דערכין (דף כט:).\",1,0],[8,358,11,9,\"ומ\\\"ש ואפילו רצה הלוקח אסור. שם:\",2,0],[8,358,11,9,\"ומ״ש מעת לעת. ברייתא בפרק השג יד (ערכין דף י״ח ע״ב) ויליף לה מקרא:\",3,0],[8,358,11,10,\"וצריך שיאכל הלוקח וכו' עד הרי אלו עולין למנין. משנה שם (דף כ\\\"ט ע\\\"ב) וטעמא דהובירה פירש\\\"י משום דאיהו אפסיד אנפשיה וא\\\"כ ה\\\"ה להובירה שתי שנים ורבינו דנקט הניחה בורה שנה ואכלה שנה לאו דוקא:\",1,0],[8,358,11,11,\"מכרה בשנת היובל עצמה וכו'. שם פלוגתא דרב ושמואל ופסק כשמואל:\",1,0],[8,358,11,12,\"מכרה שנה אחת לפני היובל וכו'. ג\\\"ז שם:\",1,0],[8,358,11,14,\"מכר נקעים מלאים מים או טרשים וכו' עד ולא לאילנות. פ\\\"ב דערכין (דף י\\\"ד ע\\\"ב) אלא שדין נקעים מלאים מים אינו שם ואפשר שחסרון הוא בספרים דידן אי נמי דמדאשכחן דיהיב גמרא טעמא לטרשין משום דלאו בני זריעה ממילא משמע דה\\\"ה לנקעים מלאים מים שגם הם אינם בני זריעה וגם בכל דוכתא דינם שוה בין לענין מכר בין לענין הקדש:\",1,0],[8,358,11,15,\"מכר שדהו לראשון וכו':\",1,0],[8,358,11,16,\"מכרה לראשון במאה דינר וכו'. עד הרי זה מחשב עם האחרון. משנה פירקא בתרא דערכין (דף ל):\",1,0],[8,358,11,16,\"וכן אם מכר במאה והשביחה וכו' עד ומריעין כח הלוקח. שם:\",2,0],[8,358,11,18,\"המוכר שדה אחוזתו וכו' עד או אינו גואל. משנה שם.\",1,0],[8,358,11,18,\"ומ\\\"ש ואם רצו קרוביו לגאול וכו'. מקרא מלא דבר הכתוב והוזכר פ\\\"ק דקידושין ובספרי רבינו כתוב או דודו או בן דודו וגו' וט\\\"ס הוא כי פסוק זה במוכר עצמו הוא דכתיב אבל במוכר שדה אחוזה כתיב ובא גואלו הקרוב אליו וכן נמצא בספר כתיבת יד:\",2,0],[8,358,11,19,\"הנותן שדהו מתנה וכו'. משנה בס״פ יש בכור (בכורות דף נ״ב ע״ב) וכחכמים:\",1,0],[8,358,11,20,\"האחים שחלקו וכו'. בס\\\"פ יש בכור.\",1,0],[8,358,11,20,\"ומ\\\"ש חלקו ביובל וכו': וכן הבכור והמייבם וכו'. משנה פרק יש בכור ואלו שאין חוזרין ביובל הבכור והיורש את אשתו והמייבם את אשת אחיו ואמרינן בגמרא דמחזירין זה לזה ומאי אין חוזרין אין חוזרין לבטלה כלומר שיהא מאבד חלק בכורתו אלא חוזרים וחולקים ונוטל פי שנים כבתחילה כך פירש\\\"י ומדברי רבינו נראה דה\\\"ק אין מחזירין לבטל החלוקה לגמרי ולחזור ולחלוק כבתחילה אלא החלוקה קיימת רק שמחליפים של זה בשל זה דאילו לפירוש רש\\\"י קשה מהיכא תיסק אדעתין שיהיה מפסיד זה חלק בכורתו:\",2,0],[8,358,11,21,\"ומ\\\"ש אבל היורש את אשתו וכו'. לטעמיה אזיל שפסק בפרק [י\\\"ב] מהלכות אישות כמ\\\"ד הכי:\",1,0],[8,358,11,21,\"ואם ירש ממנה בית הקברות וכו'. משנה ס\\\"פ יש בכור כר\\\"י בן ברוקא ומשמע דליכא מאן דפליג עליה בהא:\",2,0],[8,358,12,1,\"המוכר בית וכו'. משנה בפ\\\"ב דערכין (דף ל\\\"א) המוכר בית בבתי ערי חומה ה\\\"ז גואל מיד וגואל כל י\\\"ב חדש ואמרינן בגמרא די\\\"ב חדש מעת לעת בעינן ויש לתמוה למה השמיטו רבינו:\",1,0],[8,358,12,1,\"וכשרוצה לפדות וכו' ואינו גורע ללוקח כלום. כלומר ולא כשדה אחוזה שמגרע מדמי המכר לפי הזמן שהיה בידו כמו שנתבאר בפרק שלפני זה:\",2,0],[8,358,12,2,\"ואין הקרובים פודים אותה וכו'. בפרק קמא דקידושין (דף כ' כ\\\"א) בעיא דאיפשיטא:\",1,0],[8,358,12,2,\"ויש לו למכור מנכסיו ולפדותו: אבל לא ילוה ויגאל ולא יגאל לחצאין. בפרק בתרא דערכין עלה ל\\\"א וכרבנן:\",2,0],[8,358,12,3,\"מת הלוקח יפדה מיד בנו וכו'. משנה פ' בתרא דערכין (כ' כ\\\"א):\",1,0],[8,358,12,4,\"מכר לראשון וכו'. שם במשנה אין מונין שנה אלא משעה שמכר שנאמר עד מלאת לו שנה ופירש רש\\\"י שאם מכרה ראובן לשמעון בניסן ושמעון ללוי באייר כיון שהגיע ניסן הבא נחלט שנאמר עד מלאת לו שנה משמע לזה שהיתה אחוזה שלו מונים ובגמרא (דף ל\\\"א ע\\\"ב) למי חולט רבי אלעזר אמר ראשון חולט רבי יוחנן אמר שני חולט משום דמה מכר ראשון לשני כל זכות שתבא לידו וידוע דהלכה כרבי יוחנן לגבי רבי אלעזר דאין הלכה כתלמיד במקום הרב:\",1,0],[8,358,12,4,\"הגיע שנים עשר חדש ולא גאלה וכו'. משנה שם.\",2,0],[8,358,12,4,\"ומה שכתב וכן אם נתן הבית וכו'. שם במשנה:\",3,0],[8,358,12,5,\"היתה שנה מעוברת וכו'. גם זה משנה שם:\",1,0],[8,358,12,6,\"מכר שני בתים וכו'. מימרא שם עלה ל\\\"א ע\\\"ב):\",1,0],[8,358,12,7,\"הגיע יום י\\\"ב חדש ולא נמצא הלוקח וכו'. משנה שם תקנת הלל:\",1,0],[8,358,12,8,\"המקדיש בית עיר חומה וכו'. ברייתא שם עלה ל\\\"א ע\\\"ב:\",1,0],[8,358,12,9,\"מכר בית עיר חומה והגיע יובל וכו'. שם עלה ל\\\"א:\",1,0],[8,358,12,10,\"המוכר בית בבתי החצרים וכו'. משנה שם (דף ל\\\"ג):\",1,0],[8,358,12,11,\"כל שהוא לפנים מן החומה וכו'. משנה שם (דף ל\\\"ב) וכתנא קמא:\",1,0],[8,358,12,12,\"בית שאין בו ד' אמות וכו'. פרק קמא דסוכה (דף ג') ופירש\\\"י אינו נחלט אלא פודהו לעולם ויוצא ביובל אם לא גאלו כשאר קרקע בלא בנין:\",1,0],[8,358,12,12,\"וירושלים אין הבית נחלט בה. בפ' בתרא דערכין (ל\\\"ב) ובפ' מרובה:\",2,0],[8,358,12,12,\"ובית הבנוי בחומה וכו'. משנה שם וכרבי יהודה לגבי רבי שמעון:\",3,0],[8,358,12,13,\"עיר שגגותיה חומתה וכו'. משנה שם (דף ל\\\"ב).\",1,0],[8,358,12,13,\"ומה שכתב או שהים חומתה. ברייתא שם:\",2,0],[8,358,12,14,\"אין המקום נקרא ערי חומה וכו'. משנה שם (דף ל\\\"ג).\",1,0],[8,358,12,14,\"ומ\\\"ש ויקיפוה חומה תחילה וכו' מימרא דריב\\\"ל פירקא קמא דמגילה (דף ג' ע\\\"ב):\",2,0],[8,358,12,16,\"אין סומכין אלא על חומה המוקפת בשעת כיבוש הארץ וכו'. שם בעלה הנזכר:\",1,0],[8,358,12,16,\"וכתב הראב\\\"ד חידוש גדול אני רואה בכאן וכו'. כוונתו לומר שרבינו דבריו סותרים את דבריו שכתב שמשגלו בטלה קדושת יהושע אפילו אם היא עדיין מוקפת והיאך כתב שאם היתה מוקפת בימי יהושע אף ע\\\"פ שאינה מוקפת עתה הרי היא כמוקפת וצריך לומר דעתה לאו אחר שגלו קאי אלא אקודם שגלו בחרבן ראשון קאי וקרי עתה לגבי שעת כיבוש יהושע וזה מבואר מאד בדברי רבינו:\",2,0],[8,358,12,16,\"וכיון שגלו בחרבן ראשון וכו' עד סוף הפרק. פרק בתרא דערכין (דף ל\\\"ב) תניא רבי ישמעאל ברבי יוסי אומר למה מנו חכמים את אלו כלומר עיירות מוקפות חומה מימות יהושע שמנו שם במשנה שכשעלו בני גולה מצאו אלו וקידשום אבל ראשונות בטלו משבטלה קדושת הארץ קסבר קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד לבא ורמינהי אמר רבי ישמעאל בר רבי יוסי וכי אלו בלבד היו והלא כבר נאמר ששים עיר כל חבל ארגוב כל אלה ערים בצורות אלא למה מנו חכמים את אלו שכשעלו בני גולה מצאו אלו וכו' ומנאום ולא אלו בלבד אלא כל שתעלה לך מסורת בידך מאבותיך שמוקפת חומה מימות יהושע בן נון כל מצות הללו נוהגות בה מפני שקדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא איבעית אימא תרי תנאי ואליבא דרבי ישמעאל ואיבעית אימא חדא מינייהו ר\\\"א ברבי יוסי אמרה דתניא ר' אלעזר ברבי יוסי אומר אשר לוא חומה אע\\\"פ שאין לו עכשיו והיה לו קודם לכן מ\\\"ט דמ\\\"ד [קדושה ראשונה קידשה לשעתה] ולא קידשה לעתיד לבא דכתיב ויעשו כל הקהל השבים מן השבי וכו' אלא מקיש ביאתן בימי עזרא לביאתן בימי יהושע וכו' ואומר והביאך ה' אלהיך אל הארץ אשר ירשו אבותיך וירשתה מקיש ירושתך לירושת אבותיך מה ירושת אבותיך בחידוש כל הדברים הללו אף ירושתך בחידוש כל הדברים הללו ואידך דבעו רחמי על יצרא דעבודה זרה ובטלוהו וכו' ופסק רבינו כמאן דאמר דלא קידשה לעתיד לבא משום דמסתבר טעמיה טפי ועוד דאמרינן בפירקא קמא דחולין עלה ז' גבי רבי שהתיר בית שאן מפני שאכל שם רבי מאיר עלה ירק משום דסבר לה כי הא דאמר רבי שמעון בן אליקים משום רבי אלעזר בן פדת הרבה כרכים כבשום עולי מצרים וכו' וקסבר קדושה ראשונה לא קידשה לעתיד לבא כיון דכל הני תנאי ואמוראי סברי הכי אבל יש לתמוה על רבינו שפסק כמ\\\"ד לא קידשה לעתיד לבא ופסק דעיר שהיתה מוקפת חומה מימות יהושע אפילו בזמן שאינה מוקפת הרי היא כמוקפת והיינו כר\\\"א ברבי יוסי דדריש אשר לו חומה וכו' ומשום דדריש הכי מוכח בגמרא דסבר קידשה לעתיד לבא והרי זה כמזכה שטרא לבי תרי וי\\\"ל דרבינו פסק כר\\\"א ברבי יוסי משום דבפ\\\"ק דמגילה עלה ג' מתיב לריב\\\"ל מדר\\\"א ברבי יוסי אלמא הלכתא כוותיה וכי היכי דלא תיקשי הלכתא אהלכתא איכא למימר אפשר דלא פליג אמאן דאמר לא קידשה לעתיד לבא והכי קאמר אע\\\"פ שאין לו חומה עכשיו וכו' אקודם שגלו בחרבן ראשון דוקא קאי וכי משני גמרא תרי תנאי ואליבא דרבי ישמעאל ולא בעי לשנויי ההיא ר\\\"א בר\\\"י היא סבר דאיכא לפרושי מילתיה כדאמרינן דלא פליג אמאן דאמר לא קידשה לעתיד לבא וכיון דסתם גמרא בפ\\\"ק דמגילה מתיב מיניה נקיטינן כוותיה בגוונא דלא ליפלוג אמאי דקי\\\"ל דלא קידשה לעתיד לבא:\",3,0],[8,358,12,16,\"כתב הראב\\\"ד וכן לעתיד לבא א\\\"א הא דלא כרבי יוסי וכו':\",4,0],[8,358,13,2,\"שבט לוי אע\\\"פ וכו' אלף הראשונים מגרש וכו'. בסוטה פרק חמישי (דף כ\\\"ז) משנה וכר\\\"א בנו של רבי יוסי הגלילי ודלא כר\\\"ע דאמר אלפים תחום שבת משום דקיימא לן בפ\\\"י דתחומין דרבנן וכתב רבינו ברפ\\\"ז מהלכות שבת דתוך י\\\"ב מיל אינו אלא מדבריהם ומפרש רבינו כפשטא דמתני' ששלשת אלפים אמה היו ודלא כפירוש רש\\\"י שלא היו אלא אלפים ואע\\\"ג דברייתא דכיצד מעברין (דף נ\\\"ז:) מסייע ליה דחאה רבינו מקמי מתני' כפשטא:\",1,0],[8,358,13,5,\"ונותנים לכל עיר בית הקברות חוץ לתחום זה וכו'. פרק ב' דמכות (דף י\\\"ב):\",1,0],[8,358,13,5,\"אין עושין בערי הלוים עיר מגרש וכו'. משנה בסוף ערכין (דף ל\\\"ג ע\\\"ב):\",2,0],[8,358,13,5,\"ומ\\\"ש מפי השמועה למדו וכו'. שם בגמרא:\",3,0],[8,358,13,5,\"ומה שכתב וכן בשאר ערי ישראל. משנה וכתנא קמא:\",4,0],[8,358,13,6,\"לא יסתור וכו'. תוספתא דערכין סוף פרק חמישי:\",1,0],[8,358,13,7,\"כהנים ולוים שמכרו שדה וכו'. משנה בסוף ערכין כהנים ולוים מוכרים לעולם וגואלים לעולם שנאמר גאולת עולם תהיה ללוים ופירש רש\\\"י דלאו בשנת היובל עצמה דהא איכא למימר ק\\\"ו ומה מכורה כבר יוצאת וכו' ולכך כתב רבינו ואפילו סמוך ליובל:\",1,0],[8,358,13,8,\"ישראל שירש את אבי אמו לוי וכו'. ג\\\"ז משנה שם וכחכמים:\",1,0],[8,358,13,10,\"כל שבט לוי מוזהרים וכו'. סיפרי פרשת שופטים:\",1,0],[8,358,13,10,\"ובן לוי או כהן וכו': כתב הראב\\\"ד אם כן לא יטלו בהם תרומות ומעשרות וכו'. טעמו לומר שבמדין לא נטלו חלק בביזה כשאר ישראל אלא והרמות מכס ליי' וגו' ממחציתם תקחו וגו' ונתת לאלעזר הכהן תרומת יי' וממחצית בני ישראל תקח אחד אחוז מן החמשים וגו' ונתת אותו ללוים ומדין לא היתה מהארץ שנכרת עליה ברית ומאחר שלא נטלו הלוים בביזתה חלק שוה עם ישראל מוכח מילתא דלא שנא בין ארץ שלא נכרת עליה ברית לארץ שנכרת עליה ברית ומה שנטלו שם לא בתורת ביזה נטלו אלא בתורת תרומה שצוה לתת להם הוראת שעה ומאחר שתמורת חלקם בארץ נתן להם הקדוש ברוך הוא תרומות ומעשרות לפי דעת רבינו שבארץ שלא נכרת עליה ברית יש להם חלק בארץ ובביזה לא יטלו בו תרומות. ואני אומר שאין זו השגה דאימר דאה\\\"נ וסוריא מוכיח שאין בה תרומות ומעשרות מדאורייתא וסובר רבינו דאדרבא משם ראיה דמדחזינן דבארץ שנכרת עליה ברית לא נטלו חלק בביזה כלל ובמדין נטלו אתא לגלויי דמדין כיון שלא נכרת עליה ברית לא היתה בכלל לא היה לכהנים חלק בביזה וה\\\"ה לכל שאר הארצות שלא נכרת עליהן ברית ומה שלא נטלו במדין חלק שוה עם ישראל גזירת הכתוב היתה הוראת שעה:\",2,0],[8,358,13,10,\"סליק בריך רחמנא\",3,0],[8,359,1,1,\"מצות עשה לעשות בית לה' וכו' שנאמר ועשו לי מקדש. ז\\\"ל רבינו בספר המצות שלו מצוה עשרים הוא שצונו לבנות בית הבחירה לעבודה בו יהיה ההקרבה והבערת האש תמיד ואליו תהיה ההליכה והעליה לרגל והקבוץ בכל שנה והוא אמרו יתעלה ועשו לי מקדש. ולשון ספרי ג' מצוות נצטוו ישראל בעת כניסתן לארץ למנות להם מלך ולבנות להם בית הבחירה ולהכרית זרעו של עמלק הנה התבאר שבנין בית המקדש מצוה בפני עצמה והא דספרי איתא נמי בפרק כ\\\"ג (סנהדרין דף כ':) וסמ\\\"ג כתב וז\\\"ל תניא ג' מצות נצטוו ישראל וכו' ואחר שיניח להם המקום מכל אויביהם מסביב לבנות בית הבחירה שנאמר ועברתם את הירדן וישבתם בארץ ואח\\\"כ והיה המקום אשר יבחר ה' אלהיכם בו לשכן שמו שם שמה תביאו את כל אשר אנכי מצוה אתכם עולותיכם וזבחיכם וכו' זמן מצוה זו של בנין בית הבחירה לא הגיעה עד ימי דוד וכן הוא אומר בדוד ויהי כי ישב המלך בביתו וה' הניח לו מסביב מכל אויביו ויאמר המלך אל נתן הנביא ראה נא אנכי יושב בבית ארזים וארון האלהים יושב בתוך היריעה עכ\\\"ל. ונראה שלא רצה לומר שהמצוה היא ועשו לי מקדש כמ\\\"ש רבינו משום דההוא קרא במשכן שבמדבר מיירי ורבינו לא נראה לו שהמצוה היא והיה המקום אשר יבחר ה' אלהיכם וגו' וכסמ\\\"ג משום דהתם לא פקיד לבנות בית הבחירה אלא סיפור בעלמא הוא דקאמר שיביאו קרבנות למקום שיבחר ה' אבל לא מצינו במקרא ציווי שיבנו בית הבחירה ואע\\\"פ שבפרק כ\\\"ג הביאו מקרא דוהיה המקום אשר יבחר ה' לא לענין שיהא ציווי בנין בית הבחירה ממקרא זה אלא לומר שהכרתת זרעו של עמלק קודמת לבנין בית הבחירה מדכתיב והיה בהניח לכם מכל אויביכם וכו' והיה המקום אשר יבחר ה' ולפיכך לא רצה להביא ראיה מפסוק זה והביא ראיה מועשו לי מקדש ואע\\\"ג דההיא פרשה במשכן שבמדבר מיירי משמע דהאי קרא כלל הוא לכל מקום בין למשכן שבמדבר בין לשילה ונוב וגבעון בין לבית עולמים ודיקא נמי דקאמר ועשו לי מקדש ולא קאמר ועשו לי משכן. וכן הוא בגמרא סנהדרין ט\\\"ז שבועות י\\\"ד וכן תעשו לדורות וכו':\",1,0],[8,359,1,2,\"כיון שנכנסו לארץ העמידו המשכן בגלגל ארבע עשרה שנה וכו' עד כיון שנבנה המקדש בירושלים נאסרו כל המקומות כולן לבנות בהם בית לה' ולהקריב בהם קרבן וכו'. הכל מבואר בסוף זבחים במשנה (קי\\\"ב:) ובגמרא (ד' קי\\\"ו):\",1,0],[8,359,1,4,\"ואנשי בית שני כשבנו בימי עזרא וכו'. בפרק ב' דמדות (משנה ה') וארבע לשכות היו בארבעה מקצועותיה של מ' מ' אמה ולא היו מקורות וכך הם עתידים להיות שנאמר ויוציאני אל החצר החיצונה וכו' ובפרק שלישי גבי מזבח קאמר רבי יוסי כשעלו בני הגולה הוסיפו עליו וכו' שנאמר והאריאל י\\\"ב ארך וכו' ובפרק ד' (דף ע':) ושני פשפשין היו לשער הגדול וכו' שבדרום לא נכנס בו אדם מעולם ועליו הוא מפורש על ידי יחזקאל ויאמר אלי ה' השער הזה יהיה סגור:\",1,0],[8,359,1,5,\"ואלו הן הדברים שהן עיקר בבנין הבית וכו' עד הוא הנקרא עזרה. בפרק ב' דמדות ופרק ד' ופרק ה':\",1,0],[8,359,1,5,\"ומ\\\"ש והכל נקרא מקדש. פשוט הוא:\",2,0],[8,359,1,6,\"ועושים במקדש כלים וכו' עד משוך לדרום. בפרק ג' דמדות (משנה ו'):\",1,0],[8,359,1,6,\"ומזבח לקטרת ומנורה ושלחן. מפורש בתורה.\",2,0],[8,359,1,6,\"ומה שכתב ושלשתם בתוך הקדש וכו' עד ושלחן מימין. מבואר בפרשת תרומה ובפרשת פקודי:\",3,0],[8,359,1,6,\"ומ\\\"ש ומזבח הקטרת משוך מבין שניהם לחוץ. בפרק ג' דיומא (דף ל\\\"ג:):\",4,0],[8,359,1,7,\"ועושים בתוך העזרה גבולין וכו'. בפ\\\"ב דמדות (מ\\\"ו) ראשי פספסין מבדילין בין עזרת ישראל לעזרת הכהנים:\",1,0],[8,359,1,7,\"ובונים בה בתים וכו'. במסכת מדות (שם):\",2,0],[8,359,1,8,\"כשבונים ההיכל והעזרה וכו'. במלכים כתוב אבנים גדולות אבנים יקרות ליסד הבית ובמכילתא פרשת מזבח אדמה ואם מזבח אבנים רצה של אבנים עושה רצה של לבנים עושה וילפינן מיניה לבנין הבית:\",1,0],[8,359,1,8,\"ואין מפצלין את אבני הבנין בהר הבית וכו' ואח\\\"כ מכניסין אותם לבנין. גם זה במכילתא פרשת מזבח אדמה אבל בפרק עגלה ערופה (סוטה דף מ\\\"ח:) תנו רבנן שמיר שבו בנה שלמה את בהמ\\\"ק שנאמר והבית בהבנותו אבן שלמה מסע נבנה הדברים ככתבן דברי רבי יהודה אמר לו רבי נחמיה וכי אפשר לומר כן והלא כבר נאמר כל אלה אבנים יקרות וגו' מגוררות במגרה א\\\"כ מה תלמוד לומר לא נשמע בבית בהבנותו שהיה מתקן מבחוץ ומכניס מפנים אמר רבי נראין דברי רבי יהודה באבני מקדש ודברי רבי נחמיה באבני ביתו ופירש\\\"י דברים ככתבן כמשמען אבן שלמה מסע כמה שהסיעה מן ההר ולא סיתתוה שוב בכלי ברזל וכיון דרבי אמר נראין דברי רבי יהודה באבני המקדש יש לתמוה על רבינו למה הניח דברי רבי יהודה ופסק כרבי נחמיה ואפשר דמשום דסתם מכילתא כרבי נחמיה ותו דפשטא דקרא מסייע ליה מש\\\"ה פסק כוותיה והכרעת רבי אינה הכרעה מפני שהיא הכרעת דעת שלישית דלאו הכרעה היא כדאיתא בסוף פירקא קמא דפסחים ועוד דגמרא בפירקא קמא דתמיד שאכתוב בפרק זה כרבי נחמיה אתי:\",2,0],[8,359,1,9,\"ואין בונין בו עץ בולט כלל וכו'. נלמד ממ\\\"ש לקמן בסמוך:\",1,0],[8,359,1,9,\"ואין עושין אכסדרות של עץ בכל העזרה וכו'. בספ\\\"ק דתמיד (דף כ\\\"ח:):\",2,0],[8,359,1,9,\"כתב הראב\\\"ד ואין בונין בו עץ כלל א\\\"א והלא לשכת כ\\\"ג של עץ וכו'. מה שכתב והלא לשכת כ\\\"ג של עץ היתה הכי איתא בסוף מדות (פרק ה') שלשכת כ\\\"ג היתה נקראת לשכת העץ. ומ\\\"ש עוד ובשמחת בית השואבה מקיפין כל העזרה גזוזטרא וכו'. בפרק שני דמדות (משנה ה'). ומ\\\"ש אבל בעזרת הנשים ובהר הבית מותר כלומר וההיא דשמחת בית השואבה בעזרת הנשים היתה ובספ\\\"ג מהלכות ע\\\"ז תירץ דשאני ההיא דלשעתה היתה וכתב שם עוד ובימה של עץ שהיו עושים למלך בשעת הקהל לשעתה היתה:\",3,0],[8,359,1,9,\"ותמיהא לי הא דתנן בפרק ג' דמדות וכלונסות של ארז היו קבועים מכתלו של היכל לכתלו של אולם כדי שלא יבעט ושמא יש לומר שלא קבועים ממש קאמר בבנין אלא קבועים בעלמא בלא בנין ועל פי זה יש לתרץ ללשכת כ\\\"ג שלא היתה קבועה בבנין אלא בלא בנין ועי\\\"ל שלשכת כ\\\"ג לא של עץ היתה אלא בנין אבנים ולא נקראת של עץ אלא מפני שהניחו בה עצים אי זה פעם וטעמא דמסתבר הוא דאם לא כן למה נשתנת לשכה זו לעשותה של עץ יותר משאר לשכות שהיו של בנין. ועי\\\"ל דהראב\\\"ד ניחא ליה לשכת כהן גדול שתהא של עץ מפני שסובר שלשכה זו היתה בנויה במקום דריסת רגלי ישראל ולא אסרו אלא משער נקנור ולפנים שהוא אצל המזבח ומקשה לרבינו שסתם דבריו ומשמע מדבריו שבכל הבית אין בונין עץ אפילו בעזרת הנשים ולדעת רבינו יש לתרץ דכל העזרה דקאמר היינו משער נקנור ולפנים כדברי הראב\\\"ד:\",4,0],[8,359,1,10,\"ומרצפין את כל העזרה באבנים יקרות. הכי משמע בכמה דוכתי:\",1,0],[8,359,1,10,\"ואם נעקרה אבן וכו'. פרק שני דזבחים (דף כ\\\"ד). וכתב הראב\\\"ד עוד אמרו שם וכו'. ויתבאר פרק ה' מהלכות ביאת המקדש:\",2,0],[8,359,1,11,\"ומצוה מן המובחר לחזק את הבנין וכו'. פשוט הוא.\",1,0],[8,359,1,11,\"ומ\\\"ש אם יכולים לטוח אותו בזהב וכו'. שכן שלמה טח אותו בזהב:\",2,0],[8,359,1,12,\"אין בונין את המקדש בלילה וכו'. בפרק ב' דשבועות (דף ט\\\"ו:):\",1,0],[8,359,1,12,\"ועוסקין בבנין מעלות השחר עד צאת הכוכבים. הכי כתיב בעזרא.\",2,0],[8,359,1,12,\"ומ\\\"ש והכל חייבין לבנות ולסעד בעצמם ובממונם אנשים ונשים כמקדש המדבר. דכתיב ויבאו האנשים על הנשים וכתיב ויעשו כל חכמי לב וכתיב וכל אשה חכמת לב בידיה טוו:\",3,0],[8,359,1,12,\"ואין מבטלין תינוקות של בית רבן לבנין. מימרא פרק כל כתבי (שבת דף קי״ט:):\",4,0],[8,359,1,12,\"ואין בנין בהמ\\\"ק דוחה יום טוב. בפ\\\"ב דשבועות (דף ט\\\"ו:):\",5,0],[8,359,1,13,\"המזבח אין עושין אותו אלא בנין אבנים וכו'. במכילתא רבי ישמעאל אומר מזבח אדמה תעשה לי שלא תבנהו לא ע\\\"ג כיפין ולא על גבי עמודים והתם קאמר דקרא דואם מזבח אבנים חובה ואע\\\"ג דתנאי פליגי עליה התם פסק רבינו כוותיה משום דבר\\\"פ קדשי הקדשים זבחים (דף נ\\\"ח) סתם גמרא כוותיה:\",1,0],[8,359,1,14,\"כל אבן שנפגמה וכו'. בפ\\\"ק דחולין (דף י\\\"ח) וכמה פגימת המזבח כדי שתחגור בה צפורן מיתיבי כמה פגימת המזבח רבי שמעון בן יוחאי אומר טפח ראב\\\"י אומר כזית ל\\\"ק הא בסידא הא באבנא ופירש\\\"י באבנא כל דהו כדכתיב אבנים שלימות. וכתבו התוס' וכמה פגימת המזבח כדי שתחגור בה צפורן ואם תאמר והיאך בנו המזבח דאנה ימצאו אבנים בלא פגימה ואם יחליקו בברזל איכא איסורא דלא תניף עליהן ברזל וליכא למימר נמי ע\\\"י שמיר דע\\\"כ ע\\\"י שמיר נמי לא יהיו חלוקות שלא תחגור בהן הצפורן מדאמרינן בפ\\\"ד דע\\\"ז גבי אבני המזבח ששקצום מלכי יון וגנזום בית חשמונאי היכי נעביד נתברינהו אבנים שלימות אמר רחמנא ננסרינהו פי' לעשות בלא פגימה לא תניף עליהם אמר רחמנא והשתא לעבדינהו ע\\\"י שמיר אלא ודאי שמיר אין עושה אותן חלקות שלא תחגור בהם הצפורן וי\\\"ל דבפרק איזהו מקומן משמע שבנו אותו באבנים קטנות חלקות שלא היה בהם שום פגימה כגון חלוקי אבנים של נחל.\",1,0],[8,359,1,14,\"ומה שכתב רבינו הרי זו פסולה לכבש ולמזבח. בפ\\\"ג דמדות (משנה ד') משמע שדין אבני הכבש שוים לדין אבני המזבח:\",2,0],[8,359,1,14,\"ומה שכתב ומהיכן היו מביאים אבני מזבח מן בתולת הקרקע חופרין עד שמגיעין למקום הניכר שאינו מקום עבודה ובנין. שם אחד אבני הכבש ואחד אבני המזבח מבקעת בית כרם וחופרין למטה מבתולה ומביאים משם אבנים שלימות שלא הונף עליהם ברזל.\",3,0],[8,359,1,14,\"ומ\\\"ש או מן הים הגדול. בפרק אי זהו מקומן (דף נ\\\"ד) אמרינן גבי בנין המזבח מביא חלוקי אבנים מפולמות:\",4,0],[8,359,1,14,\"וכן אבני ההיכל והעזרות שלימות היו. נראה שלא כתב כן אלא לענין שלא יהיה בהם פגם כדכתיב אבן שלמה מסע נבנה אבל היו מסתתין ומשוין אותן בכלי ברזל מבחוץ ומכניסין אותן כמו שכתב לעיל מפצלין ומסתתין אותן מבחוץ משא\\\"כ באבני מזבח שאסור להניף עליהן ברזל הכי אמרינן בפ\\\"ק דתמיד (דף כ\\\"ו:) אהא דתנן שבית המוקד היה מוקף רובדין של אבן מקשה רובדין מאי ניהו גזרתא דאצטבתא וכו' ומי מפלגי אבנים והכתיב והבית בהבנותו אבן שלימה וגו' ושני אביי דמתקני ומייתו מעיקרא ופירש המפרש קודם שיביאו האבנים בעזרה היו מתקנות על ידי ברזל וכו' וחוץ לעזרה מותר לחתכן ולהשוותן בברזל אבל משבאו לעזרה אסור להניף עליהן ברזל והכי מוכח במכילתא דאמרינן התם לא תבנה אתהן גזית בו אי אתה בונה גזית אבל אתה בונה גזית בהיכל ובבית קדשי הקדשים הא מה אני מקיים ומקבות והגרזן וכל כלי ברזל וכו' בבית אינו נשמע אבל בחוץ נשמע כי חרבך הנפת עליה ותחללה רשב\\\"א אומר המזבח נברא להאריך ימיו של אדם וכו' עכ\\\"ל. משמע דלא נאסר הנפת ברזל אלא על המזבח בלבד משום דנברא להאריך ימיו של אדם אבל אבנים של בנין בית המקדש אין הנפת ברזל עליהן פוסלן ובלבד שלא יתקן בפנים וכן מוכח מתוך דברי רבינו דעד השתא לא איירי אלא לענין שלא יהא בהם פגם ועדיין לא הזכיר פיסול הנפת ברזל ולקמן בסמוך שהזכירו לא הזכירו אלא לענין אבני המזבח בלבד:\",5,0],[8,359,1,15,\"אבני היכל ועזרות וכו'. תוספתא סוף פרק שני דמגילה:\",1,0],[8,359,1,15,\"כל אבן שנגע בה הברזל וכו'. בפרק שלישי דמדות (משנה ד'):\",2,0],[8,359,1,15,\"ומ\\\"ש והבונה אבן שנגע בה ברזל במזבח או בכבש לוקה שנאמר לא תבנה אתהן גזית והבונה אבן פגום עובר בעשה. (דכתיב אבנים שלימות תבנה את מזבח ה' אלהיך) פשוט הוא.\",3,0],[8,359,1,15,\"ומה שכתב שדין הכבש שוה בזה למזבח הוא מדתנן בפ\\\"ג דמדות אחד אבני הכבש ואחד אבני המזבח מבקעת בית כרם וכו' ומביאים אבנים שלימות שלא הונף עליהם ברזל:\",4,0],[8,359,1,16,\"אבן שנפגמה וכו'. בפ\\\"ג דמדות נפגמה אחת מהן היא פסולה וכולן כשרות ומשמע לרבינו דה\\\"ה לנגע בה ברזל:\",1,0],[8,359,1,16,\"ומלבנין את המזבח פעמים בשנה וכו'. שם. כתב הראב\\\"ד וכן מכל העזרות והלשכות שהן קדש עכ\\\"ל. ויש להקשות שכבר כתבתי בסמוך שאבני ההיכל והעזרות אע\\\"פ שצריך שלא יהיה בהם פגם מותר להניף עליהם ברזל שהרי לא אסר הכתוב הנפת הברזל אלא על אבני המזבח ואע\\\"פ שאין מתקנים אותם בפנים בכלי ברזל כדכתיב ומקבות והגרזן כל כלי ברזל לא נשמע בבית בהבנותו ה\\\"מ לעשות מלאכה בהם בכלי ברזל בענין שישמע קול הברזל אבל ליגע בהם ברזל אפי' בפנים אין בכך כלום:\",2,0],[8,359,1,17,\"אין עושין מדרגות למזבח. פשוט הוא.\",1,0],[8,359,1,17,\"ומה שכתב אלא בונין כמו תל בדרומו של מזבח וכו' והוא הנקרא כבש. בפרק ג' דמדות תנן כבש היה לדרומו של מזבח ובפרק קדשי קדשים (זבחים דף ס״ב:) מייתי לה מקראי.\",2,0],[8,359,1,17,\"ומה שכתב והעולה במעלות על המזבח לוקה. פשוט הוא:\",3,0],[8,359,1,17,\"וכן הנותץ אבן אחת מן המזבח וכו' לוקה שנאמר ונתצתם את מזבחותם כו'. בסיפרי מניין לנותץ אבן אחת מן ההיכל ומן המזבח ומן העזרות שהוא בלא תעשה תלמוד לומר ונתצתם את מזבחותם לא תעשון כן לה' אלהיכם ואין לתמוה על רבינו שכתב או מן ההיכל או מבין האולם ולמזבח דמשמע דוקא הני אבל עזרות לא שסמך על מ\\\"ש בפרק ו' מיסודי התורה שהוא עיקר דין זה. ולשון וכן שכתב רבינו אינו מדוקדק.\",4,0],[8,359,1,17,\"ומה שכתב דרך השחתה כלומר שאם נותץ כדי לתקן ודאי שרי:\",5,0],[8,359,1,18,\"המנורה וכליה וכו' אין עושין אותם אלא מן המתכת בלבד ואם עשאום של עץ וכו'. בפרק הקומץ רבה (מנחות דף כ\\\"ח:) תני רב פפא וכו' מנורה היתה באה מן העשת ומן הזהב עשאה של כסף כשרה של בעץ של אבר ושל גיסטרון רבי פוסל ורבי יוסי בר יהודה מכשיר של עץ ושל עצם ושל זכוכית דברי הכל פסולה ופסק רבינו כרבי יוסי בר יהודה משום דאיתא התם ברייתא סתם דקתני משאר מיני מתכות כשרה ואף על גב דמייתי התם ברייתא אחריתי דקתני כלי שרת שעשאן של עץ רבי פוסל ורבי יוסי בר יהודה מכשיר פסק רבינו לפסול משום דמשמע התם דרבים פליגי עליה דרבי יוסי בר יהודה בהא.\",1,0],[8,359,1,18,\"ומה שכתב היו הקהל עניים עושים אותם אפילו של בדיל ואם העשירו עושים אותם של זהב בפרק הקומץ רבה שם ובפרק כל הצלמים (עבודה זרה דף מ״ג) [וכן עוד בראש השנה (כ״ד)]:\",2,0],[8,359,1,19,\"אפילו המזרקות והשפודין וכו' אם יש כח בצבור עושים אותם של זהב. בפרק אמר להם הממונה (יומא דף ל\\\"ז) מונבז המלך עשה כל ידות הכלים של י\\\"ה של\",1,0],[8,359,1,19,\"זהב ומ\\\"ש אפילו שערי העזרה מחפין אותם זהב אם מצאה ידם. בפ\\\"ב דמדות (משנה ג') כל השערים שהיו שם נשתנו להיות של זהב חוץ משערי נקנור מפני שנעשה בהם נס:\",2,0],[8,359,1,20,\"אין עושין כל הכלים מתחלתן וכו'. בתוס' פרק שני דמגילה:\",1,0],[8,359,1,20,\"ומה שכתב וכלי גבוה עד שלא נשתמש בהם גבוה רשאי להשתמש בהם הדיוט וכו'. שם גבי העושה תיבה ומטפחות לספר:\",2,0],[8,359,1,20,\"אבנים וקורות שחצבן מתחילה לבה\\\"כ וכו'. שם אבנים וקורות שחצבן מתחילה להדיוט אין בונין אותם בהר הבית ומשמע לרבינו דלהדיוט היינו בית הכנסת ולגבי הר הבית הדיוט קרי ליה ויש לתמוה מי דחקו לרבינו לפרש כן ולמה לא פירש דלהדיוט ממש קאמר ואפשר דבדוכתא אחרינא איתיה בהדיא:\",3,0],[8,359,2,1,\"המזבח מכוון ביותר ואין משנין אותו ממקומו לעולם. בפרק קדשי קדשים (זבחים דף ס״ב) ג' נביאים עלו עמהם מן הגולה אחד שהעיד להם על מקום המזבח וכו':\",1,0],[8,359,2,2,\"ומסורת ביד הכל וכו' עד כשנברא. בפרקי רבי אליעזר ובמדרשות:\",1,0],[8,359,2,2,\"ומ\\\"ש ומשם נברא בב\\\"ר בפסוק וייצר ובירושלמי דנזיר פרק כה\\\"ג:\",2,0],[8,359,2,3,\"מדות המזבח מכוונות הרבה וכו' ואין להוסיף על מדתו וכו'. בריש פרק קדשי קדשים (זבחים דף נ״ח:):\",1,0],[8,359,2,4,\"ומ״ש ושלשה נביאים עלו עמהם מן הגולה וכו'. בפרק קדשי קדשים (זבחים דף ס״ב):\",1,0],[8,359,2,5,\"מזבח שעשה משה וכו'. בפרק קדשי קדשים (זבחים דף נ״ט:) תניא ושלש אמות קומתו דברים ככתבן דברי רבי יהודה ר' יוסי אומר נאמר כאן רבוע ונאמר להלן רבוע מה להלן גובהו פי שנים בארכו אף כאן גבהו פי שנים בארכו וכו' א״ל רבי יוסי והלא כבר נאמר ואת קלעי החצר ואת מסך שער החצר אשר על המשכן ועל המזבח מה משכן י' אמות אף מזבח י' אמות וכו' ומה ת״ל וג' אמות קומתו משפת סובב ולמעלה ופירש״י משפת סובב ולמעלה עד מקום הקרנות ולמטה הימנו ו' אמות וגובה הקרנות אמה הרי עשר וידוע דהלכה כרבי יוסי לגבי רבי יהודה ועוד דסתם גמרא בפרק שתי הלחם (מנחות דף צ״ו) כרבי יוסי ופירש״י וג' אמות קומתו במזבח הנחשת כתיב ונאמר להלן רבוע במזבח הזהב אמה ארכו ואמה רחבו רבוע ואמתים קומתו אף כאן גבהו פי שנים כארכו הרי י' אמות וכו' משפת סובב ולמעלה עד מקום הקרנות ולמטה הימנו ו' אמות וגובה הקרן אמה ועיין במה שאכתוב לקמן בפרק זה:\",1,0],[8,359,2,5,\"ומזבח שעשו בני הגולה וכו'. משנה בפ\\\"ג דמדות (משנה א').\",2,0],[8,359,2,6,\"עשר אמות של גובה המזבח וכו'. בפי\\\"ז דכלים (משנה י') תנן רבי יהודה אומר אמה של בנין בת ששה טפחים ושל כלים ה' ומייתי לה בפ' שתי הלחם במנחות (דף צ\\\"ז) ומייתי עלה קרא דכתיב ואלה מדות המזבח באמות אמה אמה וטפח וחיק האמה ואמה רוחב וגבולה אל שפתה סביב זרת האחד וכו' חיק האמה זה יסוד אמה רוחב זה סובב וגבולה אל שפתה סביב וכו' אלו הקרנות ופירש\\\"י מדות המזבח מזבח העולה. באמות אמה אמה וטפח באמות בינוניות יהא מאמותיו אמה וטפח דאמותיו והן בשל חמשה דהוה ליה של ששה אמה וטפח באלו. וחיק האמה כלומר באלו אמות אני אומר שיהו בנות חמשה וחיק האמה דהיינו יסוד. אלו הקרנות זרת אמה האחד דמאמצעית האבן מודד והויא זרת לכל רוח דהיינו אמה כל זרת חצי אמה ומסיק התם חיק האמה בגובהה אמה רוחב כניסה ופירש\\\"י חיק האמה בגובהה אותה אמה שמן הרצפה ועד היסוד באמה בת ה'. ואמה רוחב כניסה דסובב באמה בת ה' אבל כניסה דיסוד באמה בינונית. וגבולה על שפתה סביב דגבהו דקרן באמה בת ה' עכ\\\"ל. אבל רבינו מפרש דכי אמרינן ואמה רוחב כניסה אשתי כניסות קאי בין דיסוד בין דסובב דתרווייהו באמה בת ה' טפחים ולפ\\\"ז כי קתני חיק האמה זה יסוד אמה רוחב זה סובב ואסיקנא חיק האמה בגובהה לאו לאפוקי כניסה היא דכניסה נמי הוי באמה בת ה' אלא לאשמועינן דגובהה באמה בת ה' הוא דאתא וכי קאמר במסקנא ואמה רוחב כניסה היינו בין כניסה דיסוד בין כניסה דסובב:\",1,0],[8,359,2,6,\"ומ\\\"ש וגובה כל המזבח נ\\\"ח טפחים. הכי אמרינן התם בגמרא על פי מה שנתבאר שגובה המזבח עשר אמות וכל אמה בת שש טפחים זולת אמות היסוד ואמות הקרנות שהם בנות חמש טפחים:\",2,0],[8,359,2,7,\"ומ״ש וכך היתה מדתו וצורתו עלה ה' טפחים וכנס ה' טפחים זה יסוד וכו'. בפ״ג דמדות (משנה א') תנן המזבח היה ל״ב על ל״ב עלה אמה וכנס אמה זה יסוד נמצא ל' על ל' עלה ה' וכנס אמה זה הסובב נמצא כ״ח על כ״ח מקום הקרנות אמה מזה ואמה מזה נמצא כ״ו על כ״ו מקום הילוך רגלי הכהנים אמה מזה ואמה מזה נמצא כ״ד על כ״ד מקום המערכה ואמרינן עלה בפ' שתי הלחם (מנחות דף צ״ז:) עלה אמה וכנס אמה זה יסוד נמצא ל' על ל' שלשים ושני טפחים הויין כלומר כיון דכניסה דיסוד לא הוי אלא באמה בת ה' פשו טפח מכאן וטפח מכאן ותו עלה ה' וכנס אמה זהו סובב נמצא כ״ח על כ״ח כ״ח וד' טפחים הוי אלא דכיון דלא הוי אמה לא חשיב ליה ואע״ג דהא דאמרינן כיון דלא הוי אמה לא חשיב ליה אתמר למאי דס״ד דחיק האמה כנסה ובתר הכי אסיקנא דחיק האמה כגבהה כבר נתבאר שרבינו סובר דלמסקנא נמי כנסה דיסוד באמה בת ה' טפחים וזהו שכתב רבינו בפי' המשנה פ״ג דמדות מה שאמר נמצא ל' על ל' הוא ל' ושני טפחים על ל' ושני טפחים לפי שלא כנס אלא ה' טפחים כמו שביארנו וכן אמר נמצא כ״ח על כ״ח היינו כ״ח וד' טפחים אלא שהוא לא מנה הטפחים שהוא פחות מאמה כיון דלא הוי אמה לא חשיב ליה וזה המאמר קיים עכ״ל. כלומר אע״ג דהא דכיון דלא הוי אמה לא חשיב ליה אתמר למאי דס״ד הוא מאמר קיים דגם למאי דאסיקנא אמרינן הכי. ודע דאפי' לפירוש רש״י אנו צריכין לומר דמתניתין לאו דוקא דהא גם למסקנא כניסה דסובב באמה בת ה' טפחים ואם כן ע״כ כי קתני נמצא כ״ח על כ״ח היינו כ״ח ושני טפחים על כ״ח ושני טפחים אלא דכיון דהוי בציר מאמה לא חשיב ליה ולדעת רבינו דכניסה דיסוד נמי הוי באמה בת ה' טפחים הוה ליה ד' טפחים דלא חשיב להו. ובהשגות רחבו כ״ד אמה וד' טפחים על כ״ד אמה וד' טפחים. א״א אולי אינו כן כי הד' טפחים הם כניסת הקרנות מדפני המזבח עכ״ל. ודבר פשוט הוא שטענת אולי אינה טענה וכל שכן למה שכתבתי דלפירש״י נמי כ״ח על כ״ח לאו דוקא. וכתוב בפרוש ה״ר שמעיה על מתניתין דבסמוך עלה אמה וכנס אמה עלה ה' וכנס אמה הכניסות שנה במשנה אבל עלה שלש זה מקום הקרנות שלא היה שם כניסה לא קא חשיב ואותן ג' כתובות במקרא וג' אמות קומתו משפת סובב ולמעלה עכ״ל. כלומר דאמרינן בפרק קדשי קדשים לרבי יוסי דנקטינן כוותיה דמאי דכתיב וג' אמות קומתו היינו משפת סובב ולמעלה וכמו שכתבתי לעיל והיינו מקום הקרנות ובסמ״ג מצאתי שהיה כתוב כן במשנה עצמה שהוא גורס במשנה עלה ה' אמות וכנס אמה זהו סובב עלה ג' וכנס אמה זהו מקום הקרנות כלומר וגובה כל קרן אמה הרי עשר אמות גובה המזבח וכיון שכן יש להגיה בדברי רבינו אצל מ״ש ונמצא רחבו כ״ח אמה וד' טפחים על כ״ח אמה וד' טפחים עלה י״ח טפחים וכונס לקרן זוית של הי״ח בנין חלול מרובע לכל ד' קרנות וכך מצאתי בספר מוגה:\",1,0],[8,359,2,8,\"ומ\\\"ש רבינו גובה כל קרן ה' טפחים וריבוע כל קרן אמה על אמה נתבאר בסמוך.\",1,0],[8,359,2,8,\"ומ\\\"ש וד' הקרנות חלולות היו מתוכן שם (זבחים דף נ\\\"ד:) א\\\"ר כהנא אבנים של קרנות חלולות היו שנאמר ומלאו כמזרק כזויות מזבח הכא נמי אבנים שלמות אמר רחמנא אלא דמחית מידי מתותיה ושקיל ליה ופירש\\\"י קרנות של מזבח חלולות היו נקובים נקבים עמוקים בארבעתן שיפול דם החטאת ויבלע לתוכו. כמזרק כזויות מזבח אלמא בית קיבול יש במזרקים. דמחית מידי מתותיה מקלות וקסמים דקים נתן בין חלוקי האבנים וכשיבש הוציאם ונשארו מקומות בנקבים חלולים ולא הוצרך לפגום פגימות לנקבים:\",2,0],[8,359,2,8,\"ומ\\\"ש וגובה מקום המערכה י\\\"ח טפחים. כתב הראב\\\"ד על זה לא ידעתי מהו גובה המערכה וכו'. ובאמת שדבריו בזה תמוהים בעיני שאיך עלה על דעתו לומר דמקום מערכה הוא התפוח. גם מ\\\"ש שהנוסחא המדוייקת רוחב מקום המערכה י\\\"ח טפחים וכו' איני יודע איך אפשר לומר כך שהרי כתב רבינו בסמוך שרוחב המערכה כ\\\"ד אמות וארבע טפחים ונתבאר שהוא משנה וגמרא ואיך יתכן לומר שרוחב מקום המערכה י\\\"ח טפחים כמו שכתב הראב\\\"ד שהיא הנוסחא המדוייקת גם מ\\\"ש ושני הטפחים הם שפיחתו משתי הקרנות ברחבן ואולי יש לומר שאותם שני טפחים היו פגימה וכו' איני יכול ליישבו דרבינו מיירי בגובה ואותם שני טפחים הם ברוחב ומה ענין זה לזה. ומה שכתב אחר כל זה התבוננתי מדבריו שהוא קורא מן הסובב ולמעלה מקום מערכה מי יתן ואדע מאחר שהתבונן וירד לסוף דעתו למה לו לכתוב לנו מה שעלה בדעתו קודם שהתבונן בדבריו ומה גם בהיותם דברים תמוהים. ומה שסיים הראב\\\"ד וזהו שכתב וגובה מקום מערכה י\\\"ח טפחים שהם שלש אמות ולמעלה במזבח של משה כתב כמו כן בזה הלשון כי בלשון אחרת ידבר אל העם הזה ומשנה לשון חכמינו עכ\\\"ל. מ\\\"ש ולמעלה במזבח של משה כתב כמ\\\"כ בזה הלשון כלומר שכתב למעלה מזבח שעשה משה ושעשה שלמה ושעשו בני הגולה ושעתיד להעשות כולם י' אמות גובה כל אחד מהם וזה הכתוב בתורה וג' אמות קומתו מקום המערכה בלבד ולשם כתב כהוגן שהזכיר אמות וכאן שינה לשונו להזכיר טפחים ואני אומר דרבינו תנא דווקנא הוא ומפני שאמות גובה המזבח קצתם בנות חמש טפחים כמו שנתבאר הוצרך לכתוב מדת כל דבר גובה המזבח בלשון טפחים להודיענו באי זה מקום נמדד באמה בת ה' טפחים ובאי זה מקום נמדד באמה בת ששה יגמלהו ה' כצדקו שהאיר עינינו.\",3,0],[8,359,2,8,\"ומ\\\"ש רבינו נמצא חצי גובה המזבח כ\\\"ט טפחים מסוף הסובב מבואר ממה שקדם:\",4,0],[8,359,2,9,\"ומה שכתב וחוט של סיקרא היה חוגר באמצע המזבח להבדיל בין דמים העליונים לדמים התחתונים. משנה בפ\\\"ג דמדות (משנה א').\",1,0],[8,359,2,9,\"ומ\\\"ש נמצא גובהו מן הארץ עד מקום המערכה ט' אמות פחות טפח. הוא פשוט ממה שנתבאר שאמות גובה היסוד היתה בת ה' ומשם עד הסובב ה' אמות בנות ששה וגובה מקום המערכה ג' אמות בנות ו' שהם ט' אמות בנות ו' טפחים פחות טפח:\",2,0],[8,359,2,10,\"יסוד המזבח וכו'. בפ״ג דמדות תנן היסוד היה מהלך על פני כל הצפון ועל פני כל המערב ואוכל בדרום אמה אחת ובמזרח אמה אחת ובפרק איזהו מקומן (זבחים דף נ״ג:) אמרי' קרן מזרחית דרומית לא היה לו יסוד מ״ט אמר ר' אלעזר לפי שלא היתה בחלקו של טורף דאמר רב שמואל בר רב יצחק מזבח אוכל בחלקו של יהודה אמה ופי' רש״י טורף בנימין דכתיב ביה זאב יטרף שנתנבא עליו יעקב בבקר יאכל עד באחסנתיה יתבני מדבחא ואותה הקרן לא היתה בחלקו כדמפרש ואזיל וכו' מזבח היה אוכל בחלקו של יהודה אמה אמה במזרחו אמה בדרומו כל הארך וכו' על פני כל המזרח שכשמגיע לקרן מזרחית צפונית היתה כלה בסמוך לקרן אמה כל הארך בעובי האמה אלא שלא היתה אמה שבמזבח על פני כל המזרח וכו' וכן אכילת האמה הדרומית לא היתה מהלכת על פני כל הדרום שכשמגעת לקרן דרומית מערבית כלה בסמוך לקרן אמה כדתנן היסוד היה מהלך על פני כל הצפון ועל פני כל המערב ואוכל במזרח אמה אחת ובדרום אמה אחת נמצא יסוד לשלשת הקרנות ובתר הכי (דף נ״ד) אמרינן רב אמר בבנין ולוי אמר בדמים ופירש״י בבנין בקרן דרומית מערבית בנו יסוד אמה בארך הדרום וחדלו להם כל הדרום וכל המזרח עד אמה סמוך לקרן צפונית מזרחית כדתנן אוכל במזרח אמה ובדרום אמה ולוי אמר בדמים יסוד היה על פני כל המזרח אבל לא נותנים דמים בחלקו של יהודה ופסק רבינו כרב משום דפשטא דמתניתין כוותיה. ומוקי בגמרא אליבא דרב מתני' דהמזבח ל״ב על ל״ב מן הצד ופירש״י מן הצד לאו בארבעת רבעיו חשיב אלא מצד צפון היה ל״ב אבל מזרח ודרום לא היה אלא ל״א על ל״א דקרן דרומית מזרחית חסרה לה אמה לדרום ואמה למזרח ומותיב בגמרא לרב מדתניא כיצד בונים את המזבח מביא מלבן ל״ב על ל״ב וגובהו אמה ומביא חלוקי אבנים מפולמות בין גדולות בין קטנות ומביא סיד וקוניא וזפת וממחה ושופך וזהו מקום יסוד כלומר אלמא יסוד בולט בו מד' רוחותיו ומשני דגייז ליה אבנים שלימות כתיב דמחית מידי מתותיה ושקיל ליה ופירש״י דגייז ליה לאחר שיבש סתר הבנין מעל חלקו של יהודה ופרכינן והא אבנים שלימות כתיב שיהא חלק ולא פגימות וא״א לסתירה להיות חלקה. דמנח מידי תותיה כלומר במקומו על כנגד חלקו של יהודה הניח עץ ארוך ועביו כעובי המלבן וחלק בתוך המלבן ולא יכול להדביק עם חלוקי האבנים ע״י שפיכת המיחוי של סיד ושל קוניא ולכשיבש קצת נטלו ונשאר מקומו חלק:\",1,0],[8,359,2,11,\"ובקרן מערבית דרומית וכו' עד ומנקין אותו. משנה בפרק שלישי דמדות (משנה ב') ולשון המשנה שהדמים הניתנין על יסוד מערבי ועל יסוד דרומי יורדים בהם ומתערבין באמה ויוצאים לנחל קדרון. ופי' ה\\\"ר שמעיה שהדמים הניתנים על יסוד מערבי ועל יסוד דרומי באותה אמה שהיסוד אוכל בדרום. וכתב שם רבינו כבר נתבאר ששירי הדם יש מהם ששופכים על יסוד מערבית ויש מהם ששופכים על יסוד דרומית לפיכך נתן הב' נקבים בקרן מערבי דרומי עכ\\\"ל. ובכן יהי' פשוט לפניך מה ששנינו מתערבין:\",1,0],[8,359,2,13,\"וכבש היה בנוי לדרומו של מזבח וכו'. גם זה משנה שם (משנה ג') ובפרק קדשי הקדשים (דף ס\\\"ב:) מייתי מקראי דכבש בדרום ותניא במכילתא לא תעלה במעלות על מזבחי עשה כבש למזבח שלא יעשה מדרגות שגורמים לגילוי ערוה מחמת הרחבת הפסיעות אין לי אלא עליה ירידה מניין ת\\\"ל אשר לא תגלה ערותך עליו:\",1,0],[8,359,2,13,\"ומה שכתב והיה אוכל בארץ שלשים אמה מצד המזבח ופורח ממנו אמה על היסוד ואמה על הסובב. בפרק קדשי הקדשים רמו מתני' אהדדי דתני חדא כבש היה לדרומו של מזבח ארך ל״ב והמזבח ל״ב ארך הרי ארך המזבח והכבש ס״ד וכי מני להו אהדדי בפרק ה' דמדות (משנה א') הכבש והמזבח ס״ב והא ס״ד הוי תופסין בקרקע העזרה והתם לגבי תפיסת הקרקע מני להו ומשני נמצא פורח אמה על יסוד ואמה על סובב ופירש״י שראש הכבש פורח ועולה על [שתי אמות של] כניסת היסוד והסובב [מגיע לראש המזבח] ונמצאו שתי אמות העליונות שלו נבלעות בל״ב אמות [של מזבח] ובפרק איזהו מקומן (זבחים דף נ״ד) מקשה לרב דאמר דהא דתניא מזרחית דרומית לא היה לו יסוד בבנין מדקתני פורח אמה על יסוד מכלל דאיכא כניסת היסוד לדרום דהא כבש לדרום הוא ומשני אימא כנגד אמה יסוד ופירש״י כנגד מקום שהכניסה ראויה להיות ולא שהיתה שם ומיהו שתי אמות נבלעות לתוך ל״ב של מזבח שהיה נכנס לתוך הפנימי שכנגד בליטה שהיסוד התחיל לאכול בה בדרום אמה אחת:\",2,0],[8,359,2,13,\"ומה שכתב ואויר מעט היה מפסיק בין הכבש למזבח כדי ליתן האיברים למזבח בזריקה. בפרק קדשי הקדשים (דף ס\\\"ב:) שאל ר\\\"ש בר יוסי בן לקוניא את ר' יוסי אומר היה רשב\\\"י אויר יש בין כבש למזבח א\\\"ל ואתה אי אתה אומר כן והלא כבר נאמר ועשית עולתיך הבשר והדם מה דם בזריקה אף בשר בזריקה א\\\"ל שאני אומר עומד בצד מערכה וזורק כשהוא זורק למערכה דליקה הוא זורק או למערכה שאינה דליקה זורק הוי אומר למערכה דליקה הוא זורק התם משום דלא אפשר רב פפא אמר כי דם מה דם אויר קרקע מפסיקו אף בשר אויר מפסיקו ופירש\\\"י אויר יש בין כבש למזבח שלא היה ראש הכבש נוגע במזבח אלא אויר מעט מפסיק בינתים וכו'. מה דם עולה שעומד בארץ וזורק מן הכלי כדכתיב וזרקו אף בשר בזריקה אלמא אויר יש ומחמת האויר הוא זריקה שעומד בכבש וזורק אל עבר האויר למערכה וכו' שאני אומר בצד המערכה בראש המזבח [וזורק] ולהכי אתא קרא. א\\\"ל כשהוא זורק למערכה דליקה הוא זורק וכו' כלומר משום הא למה לי קרא פשיטא דע\\\"כ הוא זורקו שהרי אין יכול לסדר סביב על ראשי העצים שאין המערכה דולקת שם אלא הימנו והלאה מקום שהמערכה דולקת והתם משום דלא אפשר הוא דע\\\"כ כי אתא קרא לאשמועינן אתא דיש אויר בין כבש למזבח. רב פפא אמר לא מצית אמרת דהיקש לאשמועינן אתא דעומד בצד המערכה וזורק דהפסקת אויר רצפה בעינן כי דם מה דם אויר קרקע הרצפה מפסיק בינו למזבח אף בשר וכו':\",3,0],[8,359,2,13,\"ומה שכתב וגובה הכבש תשע אמות פחות שתות עד כנגד המערכה. זה פשוט ממה שנתבאר שגובה המזבח עד ראש המערכה למעלה ט' אמות וכולם באמה בת ו' טפחים חוץ מאמה יסוד שהיא באמה בת ה':\",4,0],[8,359,2,14,\"ומ\\\"ש ושני כבשים קטנים יוצאים ממנו שבהם פונים ליסוד ולסובב ומובדלים מן המזבח כמלא נימא. מימרא דרב יהודה בפרק קדשי הקדשים ומסיים בה משום שנאמר סביב ורבי אבהו אמר רבוע ופירש\\\"י שני כבשים קטנים יוצאים מן הכבש וכו' אותו שפונין בו לסובב יצא במזרחו של כבש לימין ויוצא ומתחיל בשיפולו של כבש ונמשך ועולה באלכסון עד שמגיע לסובב והפונה ליסוד יוצא למערבו להוליך בו שירים של חטאת שיורד מן המזבח פונה לשמאלו ליסוד דרומי ומתחיל לצאת בשיפולו של כבש רחוק מן המזבח כדי שיהא נוח לשפע ולירד ליסוד. משום שנאמר סביב שיהא היקף למזבח כל דהו ואי היה מחוברין שוב אין היקף אפילו כחוט:\",1,0],[8,359,2,14,\"ומ\\\"ש וחלון היתה במערבו של כבש אמה על אמה ורבובה היתה נקראת שבה נותנין פסולי חטאת העוף וכו'. במשנה פרק ג' דמדות ורבובה היתה לו במערבו וכו' ששם היו נותנים פסולי חטאת העוף. וכתב הראב\\\"ד על דברי רבינו א\\\"א לא כי אלא החלון לבד והרבובה לבד וכך היא שנויה במסכת מדות עכ\\\"ל. ושותיה דמר לא ידענא שאין במסכת מדות זולת המשנה שכתבתי בסמוך ורבינו כתב בפי' המשנה דאיתא בתוספתא בזבחים חלון היתה במערבו של כבש אמה על אמה ורבובה היתה נקראת ששם זורקין פסולי חטאת העוף עד שתעובר צורתה ותצא לבית השריפה עכ\\\"ל. והוא הלשון שהעתיק פה תיבה בתיבה. ולשון רבובה פירש ה\\\"ר עובדיה שהוא כמו נבובה כלומר שהיתה חלולה:\",2,0],[8,359,2,15,\"ושני שלחנות היו במערב הכבש אחד של שיש וכו'. בפרק ששי דשקלים (משנה ד'):\",1,0],[8,359,2,16,\"כשבונין המזבח וכו' עד וישארו הקרנות חלולים. הכל בפרק איזהו מקומן (זבחים דף נ״ד ע״א וב') ונתבאר בפרק זה. ופירש״י מלבן דפוס מרובע עשוי מד' קרשים. קוניא ניתוך אבר כעין שעושים לציפוי כלי חרס שקורין פלומי״ר:\",1,0],[8,359,2,17,\"ארבע קרנות של מזבח ויסודו ורבועו מעכבין וכו'. בפרק קדשי הקדשים (דף ס\\\"ב) תנו רבנן קרן וכבש ויסוד וריבוע מעכבין מדת ארכו ומדת רחבו ומדת קומתו אין מעכבין מנא ה\\\"מ אמר רב הונא אמר קרא המזבח כל מקום שנא' המזבח לעכב ופירש\\\"י וריבוע אם אין המזבח מרובע. בכל מקום שנא' המזבח לעכב דהמזבח משמע כשהוא כן הוא דמיקרי מזבח ואי לא לא ובקרן כתיב קרנות המזבח וביסוד כתיב אל יסוד המזבח ובכבש כתיב אל פני המזבח והוא הכבש שהוא פניו של מזבח שעולין לו דרך שם כי היכי דחשיב צד מזרחית פני אהל מועד מחמת שהפתח שם ובריבוע כתיב רבוע יהיה המזבח. ואהא דתניא מדת ארכו ומדת רחבו ומדת קומתו אין מעכבין אמר רבי מני ובלבד שלא יפחתנו ממזבח שעשה משה וכמה אמר רב יוסף אמה מחכו עליה חמש אמות ארך וחמש אמות רוחב רבוע יהיה המזבח א\\\"ל אביי דילמא מקום מערכה קאמר מר אמר ליה מר דגברא רבא הוא ידע מאי קאמינא ופירש\\\"י דילמא מקום מערכה קאמר דהוי אמה שבין הקרנות ומקום הילוך ממעטים בו אמתיים לכל צד פש ליה אמה על אמה:\",1,0],[8,359,2,18,\"מזבח שנפגם מבניינו וכו'. בפ\\\"ק דחולין (דף י\\\"ח) אמרינן דפגימת המזבח כדי שתחגור בה צפורן מיתיבי כמה פגימת המזבח רשב\\\"י אומר טפח ראב\\\"י אומר כזית ל\\\"ק הא בסידא הא באבנא ופירש\\\"י באבנא כל דהו דכתיב אבנים שלימות ופסק רבינו כרשב\\\"י משום דמאריה דגמרא הוא טפי מראב\\\"י ואע\\\"ג דקי\\\"ל משנת ראב\\\"י קב ונקי אפשר דה\\\"מ במשנה אבל לא בברייתא:\",1,0],[8,359,3,1,\"המנורה מפורשת צורתה בתורה וכו' נמצאו כל הגביעים כ״ב וכו'. ברייתא בפרק הקומץ רבה (מנחות דף כ״ח) ובגמרא בשלמא גביעים כ״ב דכתיב ובמנורה ד' גביעים וכתיב ג' גביעים משוקדים בקנה ד' דידה וי״ח דקנים הא כ״ב כפתורים נמי י״א כפתורים תרי וששה דקנים וכפתר וכפתר וכפתר הא י״א אלא פרחים ט' מנ״ל פרחיה תרי וששה דקנים תמניא הוו אמר רב שלמן כתיב עד פרחה ופירש״י י״ח דקנים דכתיב ג' גביעים משוקדים בקנה האחד. כפתוריה דמנורה גופה תרי ושית דקני דיש בכל קנה וקנה כפתר דכתיב ג' גביעים משוקדים בקנה האחד הרי ח' וכפתר תחת שני הקנים וכן לשנים האחרים וכו'. עד פרחה ריבה לך הכתוב חד פרח:\",1,0],[8,359,3,1,\"ומ״ש והכל משוקדים. כתב הר״י קורקוס ז״ל שכתב כן רבינו מדאמרינן בפרק הוציאו לו (יומא דף נ״ב:) ה' מקראות אין להם הכרע ואחד מהם משוקדים דמספקא לן אי קאי אגביעים או אכפתוריה ופרחיה ולכך מפרש אתרוייהו דמספיקא עבדינן כולהו משוקדים שאף אם יעשו משוקדים ואין צריך להיות משוקדים אין בכך הפסד אבל אם יניח מלעשות משוקדים אם צריך משוקדים איכא קפידא עכ״ל.\",2,0],[8,359,3,1,\"ומ\\\"ש וכולן מעכבין זה את זה ואפילו חסר א' מהמ\\\"ב מעכב את כולן. בתוספתא פ\\\"ו דמנחות גביעיה כפתוריה ופרחיה מעכבין זה את זה:\",3,0],[8,359,3,4,\"במה דברים אמורים בשעשאה של זהב וכו'. בפרק הקומץ רבה (מנחות דף כ\\\"ח) ויליף להו מקראי ופירש רש\\\"י מן העשת עשייתה חתיכה שלימה ומכה בקורנס עד שיצאו ממנה כל כליה:\",1,0],[8,359,3,4,\"ומ\\\"ש אם היתה חלולה נראה לפרש דהיינו לומר שאינה מקשה:\",2,0],[8,359,3,5,\"ומה שכתב ואין עושין אותה מן הגרוטאות וכו'. בפרק הקומץ רבה ויליף לה מקרא ופירש\\\"י גרוטאות זהב שבור:\",1,0],[8,359,3,6,\"המלקחיים והמחתות וכלי השמן וכו'. בפ' שתי מדות (מנחות דף פ\\\"ח) תניא מנורה ונרותיה באות מן הככר ואין מלקחי' ומחתותיה מן הככר רבי נחמיה אומר מנורה היתה באה מן הככר ולא נרותיה ומלקחיה ומחתותיה באות מן הככר במאי קא מיפלגי בהאי קרא דתניא ככר זהב טהור יעשה אותה למדנו למנורה שבאה מן הככר מניין לרבות נרותיה ת\\\"ל את כל הכלים האלה יכול שאני מרבה אף מלקחיה ומחתותיה ת\\\"ל אותה דברי ר' נחמיה קשיא דר' נחמיה אדר' נחמיה תרי תנאי ואליבא דר' נחמיה ר' יהושע בן קרחה אומר מנורה באה מן הככר ואין מלקחיה ומחתותיה ונרותיה באים מן הככר ואלא מה אני מקיים את כל הכלים האלה שהיו כלים של זהב ואמרינן בגמרא דאמוראי סברי כמ\\\"ד מנורה ונרותיה באות מן הככר ומש\\\"ה פסק רבינו כן.\",1,0],[8,359,3,6,\"ומה שכתב רבינו שהרי נאמר במנורה זהב טהור וחזר ואמר ומלקחיה ומחתותיה זהב טהור וכו'. מצאתי כתוב דאיתיה בברייתא דמלאכת המשכן פ\\\"ט:\",2,0],[8,359,3,7,\"שבעה קני מנורה מעכבין זה את זה וכו'. משנה בפרק הקומץ רבה (מנחות דף כ״ח).\",1,0],[8,359,3,7,\"ומ\\\"ש בין שהיתה של זהב בין שהיתה של שאר מיני מתכות הכי אמרינן בגמרא ואימא נמי באה זהב באה קנים אינה באה זהב אינה באה קנים ההוא פמוט מיקרי.\",2,0],[8,359,3,7,\"ומ\\\"ש וכל הנרות קבועים בקנים כך פירש\\\"י שבעה נרותיה בראש כל קנה וקנה היה נר אחד כעין בזך ושם נותנין השמן והפתילות:\",3,0],[8,359,3,8,\"ומ״ש ששת הנרות הקבועים בששת הקנים היוצאים מן המנורה כולם פניהם לנר האמצעי שעל קני מנורה וכו'. בפרק שתי הלחם (מנחות דף צ״ח:) תניא אל מול פני המנורה יאירו שבעת הנרות מלמד שהיו מצדדין פניהם כלפי נר אמצעי ופירש״י האמצעי עומד על גופה של מנורה והשאר על הקנים ומשמע קרא אותן שעל הקנים מצודדות כלפי אותה של מערב.\",1,0],[8,359,3,8,\"ומ\\\"ש וזה הנר האמצעי פניו כנגד קדשי הקדשים והוא הנקרא נר מערבי. יתבאר לקמן בפרק זה:\",2,0],[8,359,3,9,\"הגביעים דומים לכוסות וכו' עד נשתיירו ג' טפחים שבהם ג' גביעים כפתור ופרח. הכל ברייתא בפרק הקומץ רבה (מנחות דף כ״ח:).\",1,0],[8,359,3,9,\"ומ\\\"ש כמין תפוחים כרותיים. פירש\\\"י שם מקום:\",2,0],[8,359,3,11,\"ואבן היתה לפני המנורה וכו'. משנה בסוף פ\\\"ג דתמיד (כ\\\"ט:):\",1,0],[8,359,3,12,\"השלחן היה ארכו י״ב טפח ורחבו ששה. בפרק שתי הלחם (מנחות דף צ״ו) תנן השלחן ארכו עשרה ורחבו חמשה וכו' דברי ר' יהודה ר' מאיר אומר השלחן אורכו י״ב ורחבו ששה ופירש״י ארכו י' ורחבו ה' כדכתיב אמתים ארכו ואמה רחבו ור' יהודה לטעמיה דאמר אמת כלים באמה בת חמשה וכו' ורבי מאיר לטעמיה דאמר כל האמות היו בינוניות וצריך טעם למה פסק כר' מאיר ואפשר שטעמו מפני ששנינו שם במשנה דאבא שאול ס״ל כוותיה.\",1,0],[8,359,3,12,\"ומ\\\"ש והיה מונח ארכו לאורך הבית וכו' וכן שאר כל הכלים ארכן לארכו של בית. משנה שם:\",2,0],[8,359,3,12,\"ומ\\\"ש חוץ מן הארון שהיה ארכו לרוחב הבית. שם (דף צ\\\"ח) תנו רבנן כל הכלים שבמקדש ארכן לארכו של בית חוץ מארון שארכו לרחבו של בית וכו' מדבדיו כך היו מונחין ובדיו מנ\\\"ל דתניא ויאריכו הבדים יכול לא היו נוגעים בפרוכת ת\\\"ל ויראו אי ויראו יכול יהו מקרעין בפרוכת ויוצאין ת\\\"ל לא יראו החוצה הא כיצד דוחקין ובולטין בפרוכת ודומין כמין שני דדי אשה שנאמר צרור המור דודי לי בין שדי ילין ומנ\\\"ל דבדיו לפותיא דארון הוו יתבי דילמא לארכו דארון הוו יתבי אמר רב יהודה תרי גברי באמתא ופלגא לא מסתגי להו ומנ\\\"ל דבארבעה הוו דרו להו דכתיב ונסעו הקהתים תרי נושאי המקדש נמי תרי. ופירש\\\"י כל הכלים כגון שלחנות ארכן לארכו של בית ממזרח למערב וכו'. [ובדיו] מנ\\\"ל דכך היו בדיו מונחים ממזרח למערב וכו'. פרכת היתה פרוסה בפתח בית קדשי הקדשים וכו'. כמין שני דדי אשה אלמא בדים ממזרח למערב קיימי ראשן אחד למערב וראשן אחד למזרח בתוך הפתח וש\\\"מ רחבו של ארון ממזרח למערב שהיה ארכו של בית. תרי גברי באמתא ופלגא אי הוו בדים לארכו לא היה בין בד לבד אלא שתי אמות ומחצה עכ\\\"ל:\",3,0],[8,359,3,12,\"ומ״ש וכן נרות המנורה היו כנגד רוחב הבית בין הצפון ובין הדרום. בפרק שתי הלחם (מנחות דף צ״ח:) אמרינן דרבי סבר דמנורה מזרח ומערב ור' אלעזר בר' שמעון סבר צפון ודרום ואמרינן דטעמא דרבי משום דכתיב בנר מערבי יערוך אותו לפני ה' מכלל דכולהו לאו לפני ה' ואי ס״ד צפון ודרום כולהו נמי לפני ה' נינהו ור' אלעזר בר' שמעון וכו' הא כתיב יערוך אותו דמצדד להו אצדודי דתניא אל מול פני המנורה יאירו שבעת הנרות מלמד שהיו מצדדין פניהם כלפי צד אמצעי. ופירש״י מזרח ומערב הג' קנים במזרח והשלשה במערב. מדכתיב בנר מערבי לפני ה' דכתיב יערוך אותו וכו' לפני ה' דמשמע אותו לפני ה' ואין אחר לפני ה' אלמא חד הוא דהוי כלפי מערב לצד בית קדשי הקדשים אלמא מזרח ומערב היו מונחים והחיצון של צד מערב קרי ליה נר מערבי דאי בצפון אשתכח דכולהו פי הפתילות שוות למערב וכו'. והכתיב אותו דמשמע א' לפני ה' ותו לא. מצדד להו אצדודי לעולם צפון ודרום מנחי ואפ״ה ליכא אלא חד כלפי מערב והיינו אמצעי שפי הפתילה כלפי מערב ושאר הפתילות מצודדות פיהן כלפי האמצעי שג' של צד צפון מצודדות כלפי דרום ושלשה של צד דרום מצודדות כלפי צפון. אל מול פני המנורה אמצעי עומד על גופה של מנורה והשאר על הקנים ומשמע קרא אותן שעל הקנים מצודדות כלפי אותם של מערב. ובר״פ במה מדליקין (שבת דף כ״ב: ד״ה נר מערבי) כתב רש״י למ״ד מזרח ומערב היו מונחים סדר הקנים קרי מערבי נר שני שבצד החיצון שהוא במזרח ולמ״ד צפון ודרום [היו] מונחים האמצעי קרי מערבי על שם שהיה פיו כנגד מערב וכל שאר נרות כלפי האמצעי דכתיב אל מול פני המנורה דהיינו אמצעי יאירו וגו' של צפון היו פונים לדרום ושבדרום פונים לצפון. נרות לוצ״ש של זהב עכ״ל. ואע״ג דהלכה כרבי מחבירו פסק רבינו כר' אלעזר בר' שמעון משום דקרא דאל מול פני המנורה יאירו שבעת הנרות מסייע ליה, ואין לומר שטעם רבינו משום דהוה עדיף מיניה בתורה כדאיתא בפ' הפועלים שאף ע״פ כן לא יצא מגדר חבירו ותדע שהרי בפ״ח מהלכות כלי המקדש פסק כרבי לגבי ר״א בר' שמעון:\",4,0],[8,359,3,12,\"וכתב הראב\\\"ד וכן נרות המנורה היו כנגד רוחב הבית בין הצפון והדרום. א\\\"א זה הוא מחלוקת תנאים וכו'. ומשנה זו פ\\\"ג דתמיד ומדקתני נרות מזרחיים משמע ודאי דאתיא כמ\\\"ד מזרח ומערב היו מונחים דאילו למ\\\"ד צפון ודרום לא שייך למיתני מזרחיים ולא מערביים אלא צפוניים או דרומיים ואין מזה השגה על רבינו שהוא סובר שמשנה זו כרבי ולא קי\\\"ל כוותיה וכ\\\"כ רבינו בפירוש המשנה ואין להקשות דסתם מתני' דפרק שתי הלחם אתיא כרבי דקתני כל הכלים שבמקדש ארכן לארכו של בית דההוא כללא לאו דוקא דהא ארון לכ\\\"ע ארכו לרחבו של בית כמו שנתבאר ואדרבה יש להוכיח דאתיא כר\\\"א בר\\\"ש ותנא ושייר ארון ונרות דאי כרבי דלא שייר אלא ארון קשיא מאי שייר דהאי שייר:\",5,0],[8,359,3,13,\"ארבעה סניפין של זהב היו לשלחן וכו'. משנה בפרק שתי הלחם (מנחות דף צ״ו) ופירש״י מפוצלים לתת ראשי הקנים באותם פיצולים והרבה פיצולין יש בהם למנין הקנים.\",1,0],[8,359,3,13,\"ומ\\\"ש והם הנאמרים בתורה וקשותיו שם בגמרא ופירש\\\"י על שם שמקשה הלחם ומחזקו שלא ישבר:\",2,0],[8,359,3,14,\"ומ\\\"ש וכ\\\"ח קנים של זהב כל אחד מהם כחצי קנה חלול היו לו וכו'. משנה שם (דף צ\\\"ו).\",1,0],[8,359,3,14,\"ומה שכתב והם הנקראין מנקיותיו. שם בגמרא (דף צ\\\"ז) ופרש\\\"י על שם שמנקים את הלחם מעיפוש.\",2,0],[8,359,3,14,\"ומ\\\"ש ושני הבזיכין שמניחים בהם הלבונה וכו' הן הנקראים כפותיו והדפוסים שעושין בהם לחם הפנים הם הנקראים קערותיו. גם זה שם בגמרא:\",3,0],[8,359,3,15,\"אלו הארבעה עשר קנים וכו' עד נמצאו ארבעה עשר בכל מערכה ומערכה. ברייתא שם ומסיים בה העליונה אינה צריכה אלא שנים לפי שאין עליה משאוי התחתונה אינה צריכה כל עיקר לפי שמונחת על טהרו של שלחן ופירש\\\"י לפי שאין משוי עליה שיכבידנה על שלמטה הימנה. על טהרו של שלחן ולא מיעפש:\",1,0],[8,359,3,16,\"ושני שלחנות היו באולם מבפנים על פתח הבית וכו'. גם זה שם במשנה (דף צ\\\"ט:):\",1,0],[8,359,3,17,\"מזבח הקטרת היה מרובע אמה על אמה. מפורש בתורה בסוף פרשת תצוה אמה ארכו ואמה רחבו רבוע יהיה ובפרק שתי הלחם (מנחות דף צ״ז) ובפרק קמא דעירובין (דף ד') אמרי' דהוה אמה בת ה' טפחים ואיני יודע למה השמיטו רבינו.\",1,0],[8,359,3,17,\"ומ\\\"ש והוא נתון בהיכל מכוון בין הצפון לדרום וכו'. בפ\\\"ג דיומא (דף ל\\\"ג:) שלחן בצפון משוך מן הכותל שתי אמות ומחצה ומנורה בדרום משוכה מן הכותל שתי אמות ומחצה מזבח ממוצע ועומד באמצע ומשוך כלפי חוץ קימעא ונוקמיה להדייהו כיון דכתיב ואת המנורה נוכח השלחן בעינן דחזו אהדדי ופירש\\\"י משוכה מן הכותל שתי אמות ומחצה כמדת השלחן דהא כתיב נכח השלחן זה בצד זה. כלפי חוץ כלפי מזרח לצד פתח ההיכל. לוקמיה בהדייהו מכוון בינייהו ולמה נמשך לחוץ:\",2,0],[8,359,3,17,\"ומ\\\"ש ושלשתן היו מונחים משליש ההיכל ולפנים וכו'. תוספתא פרק ב' דיומא:\",3,0],[8,359,3,18,\"הכיור היו לו שנים עשר דד וכו'. בס״פ אמר להם הממונה (יומא דף ל״ז) תנן בן קטין עשה שנים עשר דד לכיור שלא היו לו אלא שנים ובגמרא תנא כדי שיהו שנים עשר אחיו הכהנים העוסקים בתמיד מקדשין ידיהם ורגליהם בבת אחת.\",1,0],[8,359,3,18,\"ומ\\\"ש ומוכני עשו לו שיהיו בה המים תמיד וכו'. שם משנה אף הוא עשה מוכני לכיור שלא יהיו מימיו נפסלין בלינה ובגמרא מאי מוכני אמר אביי גילגלא דהוה משקעא ליה ופירש\\\"י מוכני מפרש בגמרא גלגל לשקעו בו בבור שהיו מימיו מחוברים למימי הכיור ואי לא הוו מיפסלי בלינה לפי שקדשו בכלי ולאו כבוד הוא ליפסל מים קדושים. ורבינו כתב בפירוש המשנה הכיור מכלל כלי שרת וכשהיו בו מים נתקדשו ונפסלו בלינה וזה עשה כלי סביב לכיור והיו בו המים תמיד והיו שותתין מאותו כלי לכיור כדי הצורך ראשון ראשון ואותו הכלי היה נקרא מוכני עכ\\\"ל. וכך הם דבריו כאן ונראה שהוא מפרש גלגלא דהוה משקעא ליה היינו לומר שעשה כלי עגול כגלגל סביבות הכיור שהיה הכיור משוקע בתוכו וכשהיו רוצים היו פותחין פי אותו כלי והמים שותתין ממנו לכיור כדי הצורך ראשון ראשון. ועל דרך זה יש לפרש מה שאמרו בפ\\\"ב דזבחים (דף כ') כיור שלא שיקעו מבערב מקדש ממנו לעבודת לילה ולמחר אינו מקדש והראב\\\"ד הורגל על פירוש רש\\\"י ולכך תמה על דברי רבינו וכתב עליו בהשגות דברים זרים אני רואה בכאן וכו' ויש לתמוה עליו דאטו מפני שהוא מקובל כפי' רש\\\"י מי שפירש פירוש אחר דבר זר יאמר לו וגם על מה שכתב מפורש ביומא ובזבחים יש לתמוה שאין פירושו מפורש בגמרא יותר מפירוש רבינו:\",2,0],[8,359,3,18,\"ודע שרבינו כתב בפ\\\"ה מהלכות ביאת המקדש מי כיור נפסלין בלינה וכיצד היו עושים משקעים אותו במי מקוה או [במי] מעיין ולמחר מעלין אותו וממלאין אותו כל יום בבקר עכ\\\"ל. נראה מדבריו אלה שהם כפירוש רש\\\"י והראב\\\"ד ואפשר שרבינו מפרש שני הפירושים וכאן כתב האחד ושם כתב האחר:\",3,0],[8,359,4,1,\"אבן היתה בקדש הקדשים וכו'. מ\\\"כ דאיתיה במלאכת המשכן פ\\\"ד.\",1,0],[8,359,4,1,\"ומה שכתב ונגנז עמו מטה אהרן והצנצנת וכו'. בפ\\\"ק דכריתות (דף ה:) ובפרק שלישי דהוריות (דף י\\\"ב) ובפרק חמישי דיומא (דף נ\\\"ב) משנגנז ארון נגנז צנצנת המן וצלוחית שמן המשחה ומקלו של אהרן שקידיה ופרחיה וארגז ששגרו פלשתים דורון לאלהי ישראל ומי גנזו יאשיהו מלך יהודה גנזו שנאמר ויאמר ללוים המבינים כו' תנו את ארון הקדש וכו' ופירש\\\"י בכריתות תנו את ארון הקדש בבית אשר בנה שלמה כי אין לכם משא בכתף וגרסינן בשקלים ירושלמי פ\\\"ו אמר להם אם גלה עמכם לבבל שוב אין אתם מחזירים אותו בכתפיכם וגנזו.\",2,0],[8,359,4,1,\"ומ\\\"ש ואף אורים ותומים שהיו בבית שני לא היו משיבים ברוח הקדש וכו' עד כדי שלא יהא מחוסר בגדים. כ\\\"כ התוספות ספ\\\"ק דיומא. והראב\\\"ד כתב לא היו משיבים א\\\"א והלא אורים ותומים ורוח הקדש וכו' טעמו דתניא בספ\\\"ק דיומא (דף כ\\\"א ע\\\"ב) אלו חמשה דברים שהיו בין מקדש ראשון למקדש שני ואלו הן ארון וכפורת וכרובים אש ושכינה ורוח הקדש ואורים ותומים ופרש\\\"י ארון וכפורת וכרובים כולה חדא מילתא ושכינה לא שרתה בו ורוח הקדש לא היתה בנביאים משנת שתים לדריוש ואילך עכ\\\"ל. ורבינו אפשר דחשיב ארון וכפורת וכרובים בתלתא ושכינה ורוח הקדש ואורים ותומים לא חשיב להו אלא בחדא ואפילו את\\\"ל דחשיב לארון וכפורת וכרובים בחדא ושכינה ורוח הקדש ואורים ותומים בתלתא ל\\\"ק שרבינו מפרש דרוח הקדש היינו נבואה שנסתלקה מהנביאים משנת שתים לדריוש וזהו חסרון גדול בישראל שלא היו נביאים להוכיחם בדבר ה' ועוד היה להם חסרון אחר שחסרו גם כן תשובת אורים ותומים. ומ\\\"ש עוד הראב\\\"ד שאינו מחשבון הבגדים טעמו שהוא קורא אורים ותומים לשם המפורש שהיו נותנין בין כפלי החשן כדכתיב ונתת אל החשן את האורים ואת התומים ורבינו קורא פה אורים ותומים לחשן בדרך השאלה:\",3,0],[8,359,4,2,\"בבית ראשון היה כותל מבדיל וכו'. בפרק הוציאו לו (יומא דף נ״א:) וכתב רש״י דבמקדש שני לא בנו אותו כותל מפני שהיה גבוה מאה אמה ועביו לא היה אלא אמה דאינה יכולה לעמוד בגובה ק' אמה ולהוסיף על עביה א״א דכתיב הכל בכתב מיד ה' עלי השכיל והם דברי הגמרא בפרק קמא דבתרא (דף ג'):\",1,0],[8,359,4,2,\"ומ\\\"ש רבינו וכיון שבנו בית שני נסתפק להם וכו'. בירושלמי דכלאים פ\\\"ח (הלכה ד') אמה טרקסין מה מבפנים או מבחוץ אמר ר' יוסי מן מה דכתיב וארבעים באמה היה הבית הוא ההיכל לפני הדא אמרה מבפנים אמר ליה רבי מנא והכתיב ויעש את בית קדש הקדשים עשרים אמה ארך ועשרים אמה רוחב הדא אמרה מבחוץ:\",2,0],[8,359,4,2,\"ומ\\\"ש רבינו אבל במקדש ראשון לא היה שם אלא פרוכת אחת וכו' נראה דלמשכן קרי מקדש ראשון דאילו בבית ראשון לא היה פרוכת אלא כותל:\",3,0],[8,359,4,3,\"ההיכל שבנו בני הגולה וכו' עד הרי הכל ק' אמה. משנה בפרק ד' דמדות (משנה ו'). ובהשגות א\\\"א לא האיר ולא הזהיר וכו'. ואני אומר שהמנהג בארץ תוגרמה בבנין בית השרים לעשות גג מנסרים מצויירים בציורים והוא הנקרא טבא\\\"ן ולמעלה ממנו התקרה העיקרית שהיא מגולית לאויר השמים וחלל בין הטבא\\\"ן ובין אותה תקרה העיקרית ואם לפעמים תדלף אותה תקרה העיקרית ירד הדלף באותו חלל על גבי הטבא\\\"ן ולכך נקרא אותו חלל בית דילפא והטבא\\\"ן נקרא כיור והיה גובהו אמה וכן כתב רבינו בעצמו בפירוש המשנה היה נהוג אצלם בבניינם לעשות לבית שני קירויים קירוי למעלה מחבירו ונותנים בין שניהם מעט הרחקה וקורים אותו החלל בית הדילפא על שם הדלף כדי שאם יטיף הקירוי העליון יעמדו המים באותו החלל:\",1,0],[8,359,4,3,\"ודע שהר\\\"ר שמעיה פירש במשנה האוטם שש אמות המפתן גבוה מהארץ שש אמות בבנין אטום חומה סתומה וצריך לומר מעלות היו באולם שמהם עולים על המפתן ומורדות בהיכל לירד בהן מהמפתן עכ\\\"ל. וטעמו מפני שאם האוטם הוא היסוד המובלע בקרקע לא היה לתנא למנותו בכלל רום ההיכל. אבל רבינו פירש שם אוטם הוא בנין אטום שבונין בגוף הקרקע יסוד ועליו מעמידים הכתלים עכ\\\"ל נראה שהאוטם היה כולו מובלע בקרקע. וכאן כתב כמו יסוד לו ויש לדון בדבריו לומר שסובר שלא היה האוטם הזה מובלע בקרקע וכדברי ה\\\"ר שמעיה:\",2,0],[8,359,4,4,\"מן המערב למזרח מאה אמה וכו'. נוסחת הדפוס שבספרי רבינו כתובה בטעות והילך הנוסחא הנכונה ובין כותל שני ושלישי שש אמות ובין כותל שלישי ורביעי שש אמות ואלו המדות הן של עובי הכותל וכו' ובמקום שכתוב עשר אמות והאולם צריך למחוק ג' תיבות אלו ולכתוב והאולם י\\\"א אמה ולכתוב אחריו ועובי כותל האולם חמש אמות וכל זה משנה שם (משנה ז') מן המזרח למערב מאה אמה כותל האולם חמש והאולם י\\\"א כותל ההיכל שש ותוכו ארבעים אמה טרקסין עשרים אמה בית קדשי הקדשים כותל ההיכל שש והתא שש כותל התא חמש מן הצפון לדרום ע' אמה כותל המסבה ה' והמסבה ג' כותל התא ה' והתא ו' כותל ההיכל ו' ותוכו עשרים אמה כותל ההיכל ו' והתא ו' וכותל התא ה' ובית הורדת המים ג' אמות והכותל ה' אמות האולם עודף עליו ט\\\"ו אמה מן הצפון וט\\\"ו מן הדרום והוא היה נקרא בית החליפות ששם גונזין את הסכינים. וכתב רבינו בפירוש המשנה בפרק הנזכר על מה ששנינו שם במשנה שלישית ול\\\"ח תאים היו שם ט\\\"ו בצפון וט\\\"ו בדרום ושמנה במערב שבצפון ושבדרום ה' על גבי ה' וה' על גביהן ושבמערב ג' על גבי ג' ושנים על גביהן כשתסתכל בצורת ההיכל שציירנו תמצא בצפון ה' הרחקות והם כותל מסבה ומסבה וכותל התא והתא וכותל ההיכל וכמותם בדרום לפיכך אמר שעל אלו ה' הרחקות היו חמשה תאים ועל ה' תאים [חמשה] וכיוצא בו היה בדרום ואל יטעך שקראם כותל מסבה ומסבה וכותל התא והתא וכותל ההיכל אחר כך חזר וקראם כולם תאים לפי שההרחקה שיש בין שני הכתלים הוא התא וכולם תאים אבל בכותל המסבה וכותל התא וכותל ההיכל לא היה כותל סתום אלא שני כתלים וביניהם הרחקה (כמו שציירנו) ולקצת התאים היו שמות כגון שקרא השורה התחתונה מהם מסבה ובית הורדת המים וזולתם וכו' וכשתסתכל בצורה גם כן תמצא במערב שלש הרחקות והם כותל התא והתא וכותל ההיכל והיו עליהם שלשה תאים ושנים על גביהן עכ\\\"ל. ועל פי הדברים האלה יהיו מבוארים לפניך דבריו פה כי מ\\\"ש מן המערב למזרח ק' אמה וזהו חשבונן ארבעה כתלים זה לפנים מזה וביניהם ג' מקומות פנויים בין הכותל המערבי ובין הכותל שלפנים ממנו ה' אמות זהו מה ששנינו כותל התא ה' וכבר נתבאר שכותל התא ששנינו לא היה כותל סתום אלא שני כתלים וביניהם הרחקה ועובי השני כתלים עם ההרחקה שביניהם היו ה' אמות.\",1,0],[8,359,4,4,\"ומ\\\"ש ובין כותל שני ושלישי שש אמות זהו מה ששנינו והתא ו' ומה שכתב ובין כותל ג' וד' ו' אמות זהו מה ששנינו וכותל ההיכל שש וכבר נתבאר שכותל ההיכל ששנינו לא היה כותל סתום אלא ב' כתלים וביניהם הרחקה ועובי ב' הכתלים עם ההרחקה שביניהם היה ו' אמות.\",2,0],[8,359,4,4,\"ומה שכתב ואלו המדות הן של עובי הכותל עם המקום הפנוי שבין שני כתלים הוא מבואר במה שכתבתי.\",3,0],[8,359,4,4,\"ומ\\\"ש ואורך קדש הקדשים כ' אמה מבואר במשנה שכתבתי בסמוך.\",4,0],[8,359,4,4,\"ומ\\\"ש ובין שתי הפרוכות המבדילות בינו ובין הקדש אמה. נתבאר בפרק זה והוא מה ששנינו אמה טרקסין.\",5,0],[8,359,4,4,\"ומ\\\"ש ואורך הקדש מ' אמה זהו מה ששנינו בהיכל תוכו מ' אמה.\",6,0],[8,359,4,4,\"ומ\\\"ש ועובי הכותל המזרח שבו השער ו' אמות זהו מה ששנינו כותל ההיכל ו'.\",7,0],[8,359,4,4,\"ומ\\\"ש והאולם י\\\"א אמות ועובי כותל האולם ה' מבואר במשנה:\",8,0],[8,359,4,5,\"ומ\\\"ש מן הצפון לדרום ק' אמה וכו'. זהו מה ששנינו האולם עודף עליו ט\\\"ו אמות מן הצפון וט\\\"ו מן הדרום ומפרש רבינו דהיינו לומר שעובי כותל האולם ה' אמות בצפון וה' בדרום כמו שהוא במזרח ותוכו של אולם בצפון י' אמות וכן בדרום כשם שארכו ממזרח למערב י\\\"א אמה:\",1,0],[8,359,4,5,\"וכתב בהשגות כל זה הבל ורעיון רוח וכו'. ואני אומר כל עצמו של הראב\\\"ד לייחס טעות לרבינו הוא ממה ששנינו במשנה הנזכרת ההיכל צר מאחריו ורחב מלפניו ודומה לארי וכבר פירשו רבינו בפירוש המשנה וז\\\"ל היה כל ההיכל ק' על ק' אבל היו מטין הבנין מעט צר לצד המערב וכשימשך לצד המזרח מתרחב כדמות האריה שהוא רחב מלפניו וצר מאחוריו עד כאן לשונו. ולפי זה אינו ענין לנדון שלנו:\",2,0],[8,359,4,5,\"ומ\\\"ש רבינו וכתלי הקדש ששה כתלים זה לפנים מזה וביניהם ה' מקומות פנויין בין כותל חיצון ובין השני ה' אמות. זהו מה ששנינו כותל המסבה ה' וכבר נתבאר שכותל המסבה ששנינו לא היה כותל סתום אלא שני כתלים והרחקה ביניהם ועובי שני הכתלים עם ההרחקה שביניהם היו חמש אמות.\",3,0],[8,359,4,5,\"ומ\\\"ש ובין שני ושלישי ג' זהו ששנינו והמסבה ג'.\",4,0],[8,359,4,5,\"ומ\\\"ש וחמש בין ג' וד' זהו מה ששנינו כותל התא ה' וכבר נתבאר שכותל התא ששנינו לא היה כותל סתום אלא שני כתלים והרחקה ביניהם ועובי שני הכתלים עם ההרחקה שביניהם היה חמש אמות.\",5,0],[8,359,4,5,\"ומ\\\"ש ובין רביעי וחמישי שש זהו מה ששנינו והתא ו'.\",6,0],[8,359,4,5,\"ומ\\\"ש ובין חמישי וכותל הפנימי שש זהו מה ששנינו כותל ההיכל ו' ועל פי מה שנתבאר שלא היה כותל סתום אלא ב' כתלים והרחקה ביניהם ועובי שני הכתלים עם ההרחקה שביניהם היה ו' אמות.\",7,0],[8,359,4,5,\"ומ\\\"ש נמצא הכל מ' אמה מצד זה. פשוט הוא.\",8,0],[8,359,4,5,\"ומ\\\"ש ומ' אמה מצד שכנגדו זהו ששנינו כותל ההיכל ו' והתא ו' וכותל התא חמש ובית הורדת המים ג' והכותל ה' ועל פי מה שנתבאר הרי כ\\\"ה ועם כותל האולם שהם ט\\\"ו עולה הכל מ'.\",9,0],[8,359,4,5,\"ומ\\\"ש ורוחב הבית עשרים. מבואר במשנה:\",10,0],[8,359,4,6,\"הפשפש הוא שער קטן וכו' עד ומהלך עד שער הגדול ופותחו. בפ\\\"ד דמדות (משנה ב'):\",1,0],[8,359,4,7,\"השער הגדול היה רחבו י' אמות וגובהו וכו' עד לכסות אחורי הדלתות. שם ומסיים בה שכל הבית טוח בזהב חוץ מאחורי הדלתות ופירש ה\\\"ר עובדיה ז\\\"ל שתים בפנים בעובי הכותל שכלפי פנים ושתים בחוץ בעביו שכלפי החוץ שעוביו של כותל ההיכל היה ו' אמות ולסוף אמה חיצונה של עובי הכותל היו הדלתות החיצונות אחת לימין הפתח ואחת לשמאלו כל דלת מהם רחבה ה' אמות וכשהיו נעולות היו נוגעות זו בזו וסותמות רוחב חלל הפתח שרחבו י' אמות וכשהיו נפתחות לצד פנים מכסות חמש אמות של עובי הכותל ושתים דלתות אחרות כמדת אלו היו קבועות בסוף עובי הכותל לצד פנים וכשהן נפתחות מכסות חמש אמות מפה וה' אמות מפה מרוחב כותל ההיכל בפנים ושם לא היה הכותל טוח בזהב כמו שאר הבית לפי שלא היה נראה ע\\\"כ:\",1,0],[8,359,4,8,\"פתחו של אולם היה גבוה מ' אמה וכו' עד ונדבך של אבנים היה בין כל אחת ואחת. משנה בפ\\\"ג דמדות. ופי' ה\\\"ר עובדיה ז\\\"ל מלתריות קורות מצויירות ומכויירות של מילא של אילן שגדלים בו עפצים שקרויים מילין. התחתונה הקורה התחתונה מושכבת על משקוף הפתח לרחבו של פתח שהוא רחב עשרים אמה והקורה עודפת על הפתח אמה מזה ואמה מזה נמצא ארכה כ\\\"ב וקורה שניה שלמעלה הימנה עודפת על הראשונה אמה מזה ואמה מזה נמצא ארכה כ\\\"ד והשלישית כ\\\"ו והרביעית כ\\\"ח והחמישית ל'. ונדבך שורה כמו נדבכין די אבן גלל. בין כל אחת ואחת חמש קורות אלו לא היו נוגעות זו בזו אלא שורה של בנין אבנים היתה בין זו לזו עכ\\\"ל:\",1,0],[8,359,4,8,\"כתבו התוספות בפ' כל הצלמים (עבודה זרה דף מ״ג) אהא דתניא לא יעשה אדם בית תבנית היכל אכסדרה תבנית אולם שהאולם היה פרוץ במילואו לרוח מזרחית:\",2,0],[8,359,4,9,\"ההיכל היה בניינו רחב מלפניו וצר מאחוריו כמו ארי. נתבאר בפרק זה:\",1,0],[8,359,4,9,\"ויציעים היו מקיפים לבית כולו וכו'. בפרק ד' דמדות (משנה ד') התחתונה ה' ורובד ו' האמצעית ו' ורובד ז' והעליונה ז' שנאמר היציע התחתונה חמש באמה רחבה והתיכונה שש באמה רחבה והשלישית שבע באמה רחבה ופי' ה\\\"ר עובדיה מחוץ לכותל המסבה שהוא הכותל החיצון של הקדש היו יציעים דהיינו גזוזטראות מקיפים את הבית מג' רוחות מערב צפון ודרום והיו היציעים הללו תחתיים שניים ושלישים היציע התחתונה חמש באמה רחבה והרובד שעליה דהיינו התקרה שעל התחתונה שהיא הרצפה שעל התיכונה שש באמה רחבה לפי שכותל המסבה היה הולך ומצר כלפי מעלה וכשמגיע אל הרובד שעל גב התחתונה היה נכנס לפנים אמה א' ועל אותה אמה הבולטת היו נתונים קורות היציע נמצאת היציע התיכונה רחבה אמה א' יותר מן התחתונה דהיינו אותה אמה שנכנס הכותל לפנים וכן כשמגיע לרובד שע\\\"ג התיכונה שהיא הרצפה של שלישית היה הכותל מצר ונכנס לפנים אמה אחת כדי שיניח ראש הקורה על אותה אמה שכותל תיכונה בולט ויוצא לחוץ יותר מכותל העליונה ונמצאת היציע העליונה רחבה אמה יותר מן התיכונה ושתי אמות יותר מן התחתונה וזהו שנאמר כי מגרעות נתן לבית חוצה לבלתי אחוז בקירות הבית כלומר היה מגרע ומחסר מעובי הכותל מבחוץ אמה א' ברובד של התיכונה ועוד אמה אחרת ברובד של העליונה כדי שיהיה לו מקום לשום בהם ראשי הקורות של הרובד כדי שלא יצטרך לאחוז בקירות הבית לעשות חורים בכותל ולתחוב שם ראשי הקורות עכ\\\"ל:\",2,0],[8,359,4,9,\"וכתב בהשגות רובד על גבה א\\\"א איני יודע מהו על גבה אלא וכו'. ולשון על גבה שהוקשה לו בדברי רבינו מבואר במה שכתבתי. ודע ממה שכתוב פה בספרי הדפוס וכן סביב לכתלי האולם מלמטה עד למעלה כך היו הג' יציעים מקיפים לבית משלש רוחות הכל מיותר וצריך למחקו:\",3,0],[8,359,4,9,\"וכן סביב לכתלי האולם וכו'. בפרק ג' דמדות (משנה ו') אמה ורובד ג' אמה ורובד ג' והעליונה אמה ורובד ד' ופירש רבינו שכתלי האולם היו בנויים כסדר הזה והוא שאמה א' מגובה הכותל לארכו היה חלק ושוה כשאר הכתלים אח\\\"כ בנין בולט מהכותל כגון כצוצרא גבהו ג' אמות אח\\\"כ מרחיק אמה ג\\\"כ ויוצא בנין והוא הנקרא רובד וכן כל בניינו אמה ורובד שלש וכצוצרא העליונה היה בו ד' אמות וכן היה סובב ההיכל כמו שיתבאר בפרק זה עכ\\\"ל. ומ\\\"ש וכן היה סובב ההיכל היינו שהיה בו רובד למקום תקרת היציע התחתונה וכן לתקרת התיכונה ולא שיהא מוקף רובדים כמו של אולם:\",4,0],[8,359,4,10,\"כל אלו המקומות הפנויים וכו' עד ואחד להיכל. בפ\\\"ד דמדות (משנה ג'):\",1,0],[8,359,4,10,\"וכתב בהשגות בדיוטא אחת א\\\"א אין צורך לזה ומה נשתנו שנים מן השלשה עכ\\\"ל. ואני אומר שמ\\\"ש בדיוטא אחת אפשר דקאי גם לשלשה שהשלשה היו בדיוטא אחת:\",2,0],[8,359,4,10,\"וכתב עוד בהשגות ואחד להתא שבו הפשפש א\\\"א לא היה שם תא אחר וכו'. וז\\\"ל רבינו בפי' המשנה מה שאמר אחד לפשפש ר\\\"ל לתא שיש בו הפשפש הצפוני שבו נכנסים להיכל וזהו הפתח שהיה בצפונו של תא שהיו לו חמשה פתחים והתא הזה היה בשורה אמצעית מהתאים והוא שעל גבי המסבה עכ\\\"ל. ולפי זה לא היה תא יתר ואין כאן השגה:\",3,0],[8,359,4,12,\"ומסיבה היתה עולה וכו' עד כדי שלא יזונו עיניהם מבית קדשי הקדשים. בפרק רביעי דמדות (משנה ג') פי' מסיבה בנין כמין עמוד חלול עשוי כמו מעלות סביב והעולה בו עולה דרך היקף כן כתב הרד\\\"ק בפי' יחזקאל וכן פירש רש\\\"י בפרק קמא דיומא מסיבה בנין אבנים מעלות מגלגלות וסובבות במקיף עמוד כמין עץ גלגל של גת. ולולים פירש הרמב\\\"ם לול הוא פתח קטן.\",1,0],[8,359,4,12,\"ומ\\\"ש ופעם אחת בשנה מפסח לפסח מלבנין את ההיכל. בפ\\\"ג דמדות (משנה ד'):\",2,0],[8,359,5,1,\"הר הבית והוא הר המוריה וכו'. בפרק שני דמדות (משנה א') הר הבית היה חמש מאות אמה על ת\\\"ק אמה.\",1,0],[8,359,5,1,\"ומ\\\"ש והיה מוקף חומה ומ\\\"ש וכיפין ע\\\"ג כיפין היו בנויות מתחתיו וכו'. בפ\\\"ג דפרה (משנה ג') הר הבית והעזרות תחתיהם חלול מפני קבר התהום ומשמע לרבינו שהיה כיפין ע\\\"ג כיפין כמו ששנינו בפרק הנזכר גבי כבש פרה.\",2,0],[8,359,5,1,\"ומ״ש וכולו היה מקורה. ומ״ש סטיו לפנים מסטיו. בפ״ק דפסחים (דף י״ג:) ובפרק לולב וערבה (סוכה דף מ״ה) ופירש״י האצטבא סביב סביב מקפת ובתוך אותו היקף עוד אחר:\",3,0],[8,359,5,2,\"ומ\\\"ש וה' שערים היו לו אחד מן המערב ואחד מן המזרח וכו'. בפ\\\"ק דמדות (משנה ג').\",1,0],[8,359,5,2,\"ומ\\\"ש רוחב כל שער י' אמות וגובהו עשרים ויש להם דלתות. בפרק שני דמדות (משנה ג'):\",2,0],[8,359,5,3,\"ומ\\\"ש לפנים ממנו סורג וכו' עד גובהו י' אמות בפרק הנזכר ופירוש סורג מקלעות עצים ארוגות זו על גבי זו באלכסון כלשון מסרגין את המטות וכתב הרא\\\"ש שהסורג נעשה לטלטול שבת ולזה היה גבוה י' טפחים כדין כל מחיצה דהיקף הר הבית לא מהני דהוי הוקף ולבסוף פתח דלא מהני.\",1,0],[8,359,5,3,\"ומ״ש ועליו הוא אומר בקינות ויאבל חל וחומה. בפ' כיצד צולין (פסחים דף פ״ו):\",2,0],[8,359,5,4,\"לפנים מן החיל העזרה וכו'. בפ\\\"ה דמדות (מ\\\"א):\",1,0],[8,359,5,4,\"ומ\\\"ש וז' שערים היו לה שלשה מן הצפון וכו' עד ואחד במזרח. בפרק קמא דמדות (מ\\\"ד)\",2,0],[8,359,5,4,\"ומ\\\"ש בשערים שבצפון ושבדרום סמוכים למערב. שם בפ\\\"ב (מ\\\"א) ובשקלים פ\\\"ו.\",3,0],[8,359,5,4,\"ומ״ש ואחד במזרח מכוון כנגד בית קדשי קדשים באמצע. בפ' הרואה (ברכות דף נ״ד) שנינו לא יקל אדם ראשו כנגד שער המזרח שהוא מכוון כנגד בית קדשי הקדשים:\",4,0],[8,359,5,5,\"ומ\\\"ש כל שער מהם היה רחבו י' אמות וכו'. בפ\\\"ב דמדות.\",1,0],[8,359,5,5,\"ומ\\\"ש ושער זה הוא נקרא שער העליון. ומ\\\"ש והוא שער נקנור. בפ\\\"ק דמדות (מ\\\"ד):\",2,0],[8,359,5,6,\"העזרה לא היתה מכוונת באמצע הר הבית וכו'. בפרק שני דמדות הר הבית היה חמש מאות אמה על ת\\\"ק אמה רובו מן הדרום שני לו מן המזרח שלישי לו מן הצפון מיעוטו מן המערב ופירש רבינו אמר שהעזרה לא היתה באמצע הר הבית אלא היה הרוחק שיש בין חומת הר הבית ובין חומת העזרה לצד דרום יותר מן הרוחק שיש ביניהם מצד מזרח והרוחק ממזרח יותר מהצפוני והצפוני יותר מן המערבי עכ\\\"ל:\",1,0],[8,359,5,7,\"ולפני העזרה במזרח היתה עזרת הנשים וכו' עד כדי שלא יהיו מעורבבין. בפ\\\"ב דמדות:\",1,0],[8,359,5,10,\"ובית גדול היה בצד עזרה בצפונה מבחוץ וכו' עד בה יורדים לבית הטבילה. בפ\\\"ק דמדות (משנה ו') ופרש\\\"י בפ\\\"ק דיומא (דף ט\\\"ו:) וארבע לשכות היו לבית המוקד פתוחות לה שתים בקדש ושתים בחול של בית המוקד מקצתה בנויה בתוך עזרה מקודשת ומקצתה בחול וראשי פספסין חתיכות עצים מבדילים לסימן במקום המפסיק בין קדש לחול.\",1,0],[8,359,5,10,\"ומ\\\"ש רבינו מערבית דרומית לשכת הטלאים. אע\\\"ג דבפרק שלישי דתמיד (דף ל') תנן שהיתה צפונית מערבית בפ\\\"ק דמדות (משנה ו') תנן מערבית דרומית ובפ\\\"ק דיומא רמי להו ומסיק דמערבית דרומית הואי:\",2,0],[8,359,5,11,\"היורד לבית הטבילה מלשכה זו היה הולך במסיבה ההולכת תחת המקדש כולו וכו'. בריש מסכת תמיד (דף כ\\\"ה):\",1,0],[8,359,5,12,\"אורך העזרה מן המזרח למערב קפ\\\"ז וזהו חשבונן וכו' עד מקום דריסת רגלי ישראל והוא הנקרא עזרת ישראל י\\\"א אמה. בפ\\\"ה דמדות (משנה א'):\",1,0],[8,359,5,13,\"ומ\\\"ש ורוחב העזרה מן הצפון לדרום קל\\\"ה וזהו חשבונן וכו'. שם מן הצפון לדרום קל\\\"ה מן הכבש ולמזבח ס\\\"ב מן המזבח לטבעות שמונה אמות מקום הטבעות כ\\\"ד מן הטבעות לשלחנות ד' מן השלחנות לננסים ארבע מן הננסים לכותל העזרה ח' אמות והמותר בין הכבש לכותל ומקום הננסים ונראה מדברי רבינו שהח' אמות ששנינו עליהם מן הטבעות לשלחנות ארבע מן השלחנות ולננסים ארבע הם מקום השלחנות שח' שלחנות היו שם כדתנן בפרק ששי ממסכת שקלים והיו נתונות בח' אמות אלו. וה\\\"פ מן הטבעות למחצית השלחנות ארבע ומחצית השלחנות לננסים ארבע וממה ששנינו והמותר בין הכבש לכותל ומקום הננסים מפרש רבינו דחציין דהיינו י\\\"ב אמות וחצי לבין הכבש ולכותל וי\\\"ב ומחצה למקום הננסים. ופירוש ננסים הם עמודים קצרים ואנקליות של ברזל קבועים בהם שבהם תולין ומפשיטין כמו ששנינו בפ\\\"ג דמדות (מ\\\"ה):\",1,0],[8,359,5,15,\"מכותל צפוני של עזרה עד כותל המזבח וכו' עד והוא המקום ששוחטין בו קדשי הקדשים. פלוגתא דתנאי בפרק ב' דזבחים (דף כ') ופסק כרבי דאמר הכי:\",1,0],[8,359,5,17,\"שמונה לשכות היו בעזרת ישראל וכו' עד וגג שלשתן שוה. בפרק חמישי דמדות (משנה ג').\",1,0],[8,359,5,17,\"ומה שכתב וחציה היה קדש וחציה היה חול וכו' עד היו הסנהדרין יושבין. בפרק שני דיומא (דף כ\\\"ה).\",2,0],[8,359,5,17,\"ומ\\\"ש ושתי לשכות אחרות היו שם בעזרת ישראל וכו'. פרק קמא דמדות (משנה ד') ופרק קמא דיומא (דף י\\\"ט):\",3,0],[8,359,6,1,\"המקדש כולו לא היה במישור וכו'. בפ\\\"ב דמדות (משנה ג') לפנים ממנו החיל י' אמות וי\\\"ב מעלות היו שם רום מעלה חצי אמה ושלחה חצי אמה ופירש\\\"י בפירקא קמא דיומא (דף ט\\\"ו) שלחה משך רוחב המעלה חצי אמה וארכה בכל רוחב ההר לצפון ולדרום:\",1,0],[8,359,6,2,\"ומה שכתב ועולה ממנה לעזרת ישראל שהוא תחלת העזרה בט\\\"ו מעלות וכו'. בפרק ב' דמדות וחמש עשרה מעלות עולות [מתוכה] לעזרת ישראל ושנינו באותו פרק כל המעלות שהיו שם רום מעלה חצי אמה ושלחה חצי אמה:\",1,0],[8,359,6,3,\"ומה שכתב ועולה ממנו לעזרת הכהנים במעלה גבוהה אמה ועליה דוכן יש בו ג' מעלות וכו'. שם גבי עזרת ישראל ועזרת הכהנים רבי אליעזר בן יעקב אומר מעלה היתה [שם] וגבהה אמה והדוכן נתון עליה ובו ג' מעלות של חצי חצי אמה נמצאת עזרת הכהנים גבוהה מעזרת ישראל שתי אמות ומחצה ופירש\\\"י בפ\\\"ק דיומא ובו שלש מעלות של חצי אמה שעולים בה לדוכן:\",1,0],[8,359,6,4,\"ומ\\\"ש ועולה משם לאולם בי\\\"ב מעלות וכו'. בפ\\\"ג דמדות (מ\\\"ו) ויש לגמגם על זה שהרי שנינו בפ\\\"ב דמדות כל המעלות שהיו שם רום מעלה חצי אמה ושלחה חצי אמה חוץ משל אולם הרי שמעלות האולם לא היו במדה זו וה\\\"ר עובדיה כתב גבי מעלות האולם ה\\\"ג רום מעלה [חצי אמה] ושלחה אמה וכו' וכך גריס ה\\\"ר שמעיה ולגירסת רבינו קשה בין האולם ולמזבח כ\\\"ב אמה וי\\\"ב מעלות היו שם רום מעלה חצי אמה ושלחה חצי אמה וצ\\\"ע:\",1,0],[8,359,6,5,\"ומה שכתב נמצא גובה קרקע ההיכל על קרקע שער המזרח של הר הבית כ\\\"ב אמות וגובה שער הבית עשרים אמה לפיכך העומד כנגד שער המזרח אינו רואה פתח ההיכל ומפני זה עשו כותל שעל גבי שער זה נמוך וכו'. בפרק שני דמדות וכל הכתלים שהיו שם היו גבוהים חוץ מכותל המזרחי שהכהן השורף את הפרה עומד בראש הר המשחה ומתכוון ורואה בפתחו של היכל בשעת הזיית הדם ופירש\\\"י בפרק קמא דיומא (ט\\\"ז) כל הכתלים שהיו שם בכל בנייני הר הבית היו גבוהים הרבה מאד שהיו כל פתחים שבהם גבוהים עשרים אמה לבד ממה שעל הפתחים הרבה מאד. חוץ מכותל מזרחי והוא התחתון לרגלי הר הבית שבו נכנסים לחיל שלפני עזרת הנשים ומן החיל נכנסים לעזרת הנשים ומעזרת נשים לעזרה הגדולה. שכהן השורף את הפרה עומד בהר המשחה הוא הר הזיתים אשר על פני ירושלים מקדם ופני הכהן למערב ומתכוין ורואה מעל גובה ראש הכותל דרך השערים שלפנים ממנו פתחו של היכל כשהוא מזה בדם כדכתיב והזה אל נכח פני אהל מועד ואם היה הכותל גבוה אע\\\"פ שהשערים מכוונים זה כנגד זה שער הר הבית כנגד שער עזרת הנשים ושער עזרת הנשים כנגד שער העזרה הגדולה ושער העזרה כנגד פתח ההיכל לא היה יכול לראות את פתח ההיכל דרך פתחים לפי שההר הולך ומגביה ועולה עד שקרקע פתח ההיכל גבוה עשרים אמות יותר מקרקעי רגלי הר הבית ונמצאת אסקופת ההיכל גבוהה ממשקוף פתח הר הבית ולא יוכל לראות חלל פתח ההיכל דרך אותו פתח עכ\\\"ל. ורבינו בפירוש המשנה פ\\\"ב דמדות אמתני' דכל הכתלים שהיו שם היו גבוהים כתב ככל מה שכתב בפרק זה באר היטב:\",1,0],[8,359,6,6,\"ומ\\\"ש ולשכות היו שם תחת עזרת ישראל וכו'. בפרק ב' דמסכת מדות.\",1,0],[8,359,6,6,\"ומה שכתב ועל הדוכן העולה מעזרת ישראל לעזרת הכהנים היו הלוים עומדים בשעה שאומרים שירה על הקרבן. בס\\\"פ ב' דערכין (דף י\\\"ג):\",2,0],[8,359,6,7,\"הלשכות הבנויות בקדש ופתוחות לחול וכו'. בפרק ג' דמעשר שני (משנה ח) תנן הלשכות בנויות בקדש ופתוחות לחול תוכן חול וגגותיהן קדש בנויות בחול ופתוחות לקדש תוכן קודש וגגותיהן חול ובס״פ כיצד צולין (פסחים דף פ״ה:) אמר רב גגין ועליות לא נתקדשו וכו' ת״ש הלשכות הבנויות בקדש ופתוחות לחול תוכן חול וגגותיהן קדש תרגמה רב חסדא בשגגותיהן שוין לקרקע העזרה א״ה אימא סיפא בנויות בחול ופתוחות לקדש תוכן קדש וגגותיהן חול ואי ס״ד בשגגותיהם שוין לקרקע עזרה ה״ל מחילה ואמר רבי יוחנן מחילות לא נתקדשו כי קאמר ר' יוחנן בפתוחות להר הבית כי תניא ההיא בפתוחות לעזרה והתניא רבי יהודה אומר מחילות מתחת ההיכל חול כי תניא ההיא שפתוחות לחול. ת״ש וגגן קדש ותסברא והא קתני וגגין הללו אין אוכלין שם קדשי קדשים ואין שוחטין שם קדשים קלים ואלא קשיא גגן קדש אמר רב חמא בר גוריא לאותן שתי אמות דתנן שתי אמות היה בשושן הבירה וכו' ופירש״י גגין ועליות לא נתקדשו בין גגי ירושלים בקדושת ירושלים לקדשים קלים בין גגי לשכות העזרה בקדושת עזרה לקדושת קדשי קדשים. פתוחות לחול שאין להם פתח לעזרה אלא להר הבית. תוכן חול כקדושת הר הבית ולא כעזרה דבתר פתחא אזלינן בשגגותיהם שוים לקרקע שהלשכות בנויות מחילות תחת הקרקע הילכך גגים דידהו ה״ל כי ארעא. כי אמרה רבי יוחנן להא דמחילות לא נתקדשו בפתוחות להר הבית דגבי שילוח בעל קרי המשתלח חוץ להר הבית אמרה בפרק אלו דברים וכו'. וכי תניא ההיא דתוכן קדש בפתוחות לעזרה להכי נקט פתוחות דבתר פתיחתן אזלינן. והתניא מחילות שתחת ההיכל חול וקס״ד בפתוחות לעזרה קאמר ומשנינן בפתוחות לחול [להר הבית]. ובפרק איזהו מקומן (זבחים דף נ״ו) תני תנא קמיה דרב נחמן כל העזרה היתה קפ״ז על רחב קל״ה א״ל הכי אמר לי אבא כגון זה כהנים נכנסים לשם ואוכלים שם קדשי קדשים ושוחטין שם קדשים קלים וחייבים משום טומאה למעוטי מאי וכו' למעוטי לשכות ואי בנויות בחול ופתוחות לקדש והא תנן תוכן קדש מדרבנן ודאורייתא לא והא תניא לשכות בנויות בחול ופתוחות לקדש מנין שהכהנים נכנסים לשם ואוכלים שם קדשי קדשים ושירי מנחה ת״ל בחצר אהל מועד יאכלוה התורה רבתה חצרות הרבה אצל אכילה אחת אמר רבא לאכילה שאני אבל לענין טומאה לא והתניא לשכות הבנויות בחול ופתוחות לקדש כהנים נכנסים לשם ואוכלים שם קדשי קדשים ואין שוחטין שם קדשים קלים וחייבים משום טומאה לאו אמרת אין שוחטין תני נמי אין חייבין. ופירש״י הא אנן תנן תוכן קדש וליחייב עלייהו משום טומאה. מדרבנן מצות חכמים היא שלא יכנסו להם בטומאה אבל כרת וקרבן ליכא. והתניא מנין ללשכות וכו' ומדמרבינן להו לענין אכילה שמע מינה קדושים הן מן התורה דאי מדרבנן וקרא אסמכתא הוא היאך הקילו חכמים לעקור דבר ולהכשיר מקום חול לאכילת קדשי קדשים. חצרות הרבה במקום קדוש בחצר אהל מועד. לאכילה שאני דרבי בה קרא חצרות הרבה. ואין שוחטין שם קדשים קלים דהא בעינן לפני אהל מועד למעוטי צידי צדדין. לאו אמרת [דקתני] בה אין שוחטין אלמא לא קדישי תני נמי אין חייבין משום טומאה עכ״ל:\",1,0],[8,359,6,9,\"ומ״ש רבינו החלונות ועובי החומה כלפנים וכו'. בפ' כיצד צולין (פסחים פ״ה:) תנן החלונות ועובי החומה כלפנים ובפרק איזהו מקומן משמע דבין לאכילת קדשי קדשים בין לטומאה היו כלפנים. ופירש״י (באיזהו מקומן) החלונות עובי חלל החלונות שבחומות העזרה סביב מבפנים ועובי החומה בראשה מלמעלה:\",1,0],[8,359,6,9,\"ודע דבפרק כיצד צולין (פסחים דף פ״ו) אהא דמוקי רב חסדא מתניתין בלשכות בנויות בקדש ופתוחות לחול גגותיהן קדש בשגגותיהן שוים לקרקע העזרה מתיב מדתנן החלונות ועובי החומה כלפנים בשלמא החלונות משכחת להו דשוו לקרקע העזרה אלא עובי החומה היכי משכחת לה משכחת לה בבר שורא. ופירש״י עובי החומה אלמא ראש החומה נתקדש דדמו לגגין ועליות. בר שורא חומה קטנה לפנים מחומה גדולה והיא נמוכה ושוה לקרקע גובה העזרה שקרקע העזרה הולך וגבוה ועולה במעלות עכ״ל. ויש לתמוה על רבינו למה סתם דבריו ולא פירש דהא דהחלונות ועובי החומה כלפנים דוקא בששווים לקרקע העזרה אבל אם אינו שוה לקרקע העזרה אינו כלפנים וכבר השיג עליו הראב״ד בזה וכתב ועובי החומה כלפנים א״א אף אלו בששוים לקרקע העזרה ומשכחת להו בבר שורא עכ״ל. וצריך לדחוק ולומר שסמך רבינו על מה שכתב לעיל בסמוך גבי לשכות אם היו גגותיהם שוים עם קרקע העזרה דממילא משמע דהוא הדין לחלונות ועובי החומה:\",2,0],[8,359,6,10,\"בית דין שרצו להוסיף על ירושלים וכו'. בפירקא קמא דסנהדרין (דף ב') ובפרק ב' דשבועות (דף י\\\"ד):\",1,0],[8,359,6,11,\"אין מוסיפין על העיר או על העזרות וכו'. בפ\\\"ב דשבועות תנן שאין מוסיפין על העיר ועל העזרות אלא במלך ונביא ובאורים ותומים ובסנהדרין של ע\\\"א ובשתי תודות ובשיר וב\\\"ד מהלכים ושתי תודות אחריהם וכו' וכל שלא נעשה בכל אלו הנכנס לשם אין חייב עליה. ובגמרא מנא ה\\\"מ אמר רב שימי בר חייא דאמר קרא ככל אשר אני מראה אותך את תבנית המשכן ואת תבנית כל כליו וכן תעשו לדורות ופירש\\\"י מנא ה\\\"מ דבעינן כל הני לתוספת עזרה. וכן תעשו קרא יתירא למדרש לדורות וכימי משה דהוא מלך ונביא ואחיו כ\\\"ג ואורים ותומים וע' זקנים. שתי תודות מנחמיה בן חכליה גמרינן ובגמ' תני שתי תודות שאמרו בלחמן ולא בבשרן ויליף לה מקרא דמאי נינהו חמץ. ואמרינן תו בגמרא וב\\\"ד מהלכין ושתי תודות אחריהם למימרא דב\\\"ד קמי תודה אזלי והכתיב וילך אחריהם הושעיה וחצי שרי יהודה ה\\\"ק ב\\\"ד מהלכין ושתי תודות מהלכות וב\\\"ד אחריהם ואמרינן תו בגמרא כיצד מהלכות רבי חייא ור' שמעון ברבי חד אמר זו כנגד זו וחד אמר זו אחר זו מ\\\"ד זו כנגד זו הפנימית הך דמקרבא לחומה ומ\\\"ד זו אחר זו הפנימית הך דמקרבא לב\\\"ד. ואיני יודע מניין לו לרבינו לפסוק כמ\\\"ד זו אחר זו ואפשר דמשום דפשטא דמילתא משמע טפי דמהלכות זו אחר זו מש\\\"ה נקט הכי:\",1,0],[8,359,6,12,\"ומה שכתב ועומדים בכנורות ובנבלים וכו'. שם אהא דתנן ובשיר תנו רבנן שיר של תודה בכנורות ובנבלים ובצלצלים על כל פינה ופינה ועל כל אבן גדולה שבירושלים אומר ארוממך ה' כי דליתני וגו' ושיר של פגעים וכו' ואומר יושב בסתר עליון וגו' עד כי אתה ה' מחסי ואומר מזמור לדוד בברחו וגו' ופירש רש\\\"י ארוממך ה' הוא מזמור חנוכת הבית לכך אומר אותו. שיר של פגעים יושב בסתר עליון לפי שאמרו משה בהקמת המשכן. ואומר מה רבו צרי וגו' לפי שנאמר בו רבים אומרים לנפשי אין ישועתה לו באלהים סלה שהיו מתלוצצים צרי יהודה ובנימין כשהיו בני ישראל בני הגולה בונים החומה ורבינו לא כתב אלא ארוממך ה' כי דליתני וצריך טעם למה ובשלמא מה רבו צרי איכא למימר דלא נאמר אלא באותו זמן שהיו הצרים מתלוצצים עליהם אבל היכא דאין צרים מתלוצצים עליהם לא אמרינן ליה אבל יושב בסתר עליון משמע דלעולם אמרינן ליה וי\\\"ל דמזמור יושב בסתר עליון נמי אינו ענין לאומרו אלא כשיש צרים הנלחמים בהם דכתיב מחץ יעוף יומם וגו' יפול מצדך אלף וגו':\",1,0],[8,359,6,12,\"ומה שכתב ואוכלים שם לחם תודה אחת וכו'. שם אפלוגתא דכיצד מהלכות השתי תודות תנן הפנימית נאכלת והחיצונה נשרפת בשלמא למ\\\"ד זו אחר זו אמטו להכי פנימית נאכלת וכו' אלא למ\\\"ד זו כנגד זו תרוייהו בהדי הדדי מיקדשי וליטעמיך למ\\\"ד זו אחר זו חדא מי מיקדשא וכו' אלא אמר רבי יוחנן על פי נביא נאכלת ועל פי נביא נשרפת ומפרש רבינו דכי מסיק אלא אמר רבי יוחנן היינו לומר לא תיתני פנימית נאכלת וחיצונה נשרפת אלא האחת נאכלת והאחת נשרפת והנביא אמר להם אי זו יאכלנו ואי זו ישרפו:\",2,0],[8,359,6,13,\"וכן אם הוסיפו על העזרה וכו'. אמר רמי בר חמא אין העזרה מתקדשת אלא בשיירי מנחה מ\\\"ט וכו' כירושלים מה ירושלים דבר הנאכל בה ויוצא ממנה נפסל אף עזרה דבר הנאכל בה ויוצא ממנה נפסל:\",1,0],[8,359,6,14,\"כל מקום שלא נעשה וכו'. שם (דף ט\\\"ז) אהא דתנן כל שלא נעשה בכל אלו הנכנס לשם אין חייבין עליה איתמר רב הונא אמר בכל אלו תנן רב נחמן אמר באחת מכל אלו תנן רב הונא אמר בכל אלו תנן קסבר קדושה ראשונה קדשה לשעתה וקידשה לעתיד לבוא ועזרא זכר בעלמא הוא דעבד רב נחמן אמר באחת מכל אלו תנן סבר קדושה ראשונה קדשה לשעתה ולא קדשה לעתיד לבא ועזרא קדושי קדיש ואע\\\"ג דלא היו אורים ותומים ואמרינן דתנאי פליגי בהאי מילתא מר סבר קדושה ראשונה קדשה לשעתה ולא קדשה לעתיד לבא ומר סבר קדשה לשעתה וקדשה לעתיד לבא ופסק רבינו כמ\\\"ד קדשה לשעתה וקדשה לעתיד לבא ומדאמרינן התם בגמרא תנאי היא דתנן א\\\"ר אליעזר שמעתי כשהיו בונים בהיכל עושים קלעים להיכל וקלעים לעזרות וכו' א\\\"ר יהושע שמעתי שמקריבין אע\\\"פ שאין בית אוכלים קדשי קדשים אע\\\"פ שאין קלעים קדשים קלים ומעשר שני אע\\\"פ שאין חומה מפני שקדושה ראשונה קדשה לשעתה וקדשה לעתיד לבא מדר' יהושע סבר קדשה לעתיד לבא מכלל דר' אליעזר סבר לא קדשה לעתיד לבא והא קי\\\"ל דרבי אליעזר ור' יהושע הלכה כר' יהושע וכ\\\"ש למאי דדחי התם דילמא דכ\\\"ע קדשה לעתיד לבא ומר מאי דשמיע ליה קאמר ומר מאי דשמיע ליה קאמר וכ\\\"ת קלעים למה לי לצניעותא בעלמא דהשתא אף ר' אליעזר סבר דקדשה לעתיד לבא. ועוד דבפרק השוחט ומעלה (זבחים דף ק\\\"ז:) גרסי' איתמר המעלה בזמן הזה רבי יוחנן אמר חייב ר\\\"ל אמר פטור ר\\\"י אמר חייב קדושה ראשונה קדשה לעתיד לבא ר\\\"ל אמר פטור וכו' לא קדשה לעתיד לבא ובפלוגתא דר' אליעזר ור' יהושע ודחי דילמא דכ\\\"ע קדשה לעתיד לבא ומר מאי דשמיע ליה קאמר וכו' וידוע דהלכה כר\\\"י לגבי ר\\\"ל וא\\\"כ קי\\\"ל דקדשה לעתיד לבא וכל שכן למאי דדחי דכ\\\"ע קדשה לעתיד לבא. וכתוב בהשגות א\\\"א סברת עצמו היא זו וכו'. ומ\\\"ש שזו סברת עצמו ולא ידע מאין לו כבר הוכחתי מאין לו לומר כן במקדש וירושלים:\",1,0],[8,359,6,16,\"ומ\\\"ש בשאר א\\\"י שלא קדשה לעתיד לבא נתבאר בראש הלכות תרומות בס\\\"ד. ומ\\\"ש הראב\\\"ד ובכמה מקומות במשנה אם אין מקדש ירקב ובגמרא אמרו דנפול מחיצות אלמא למ\\\"ד קדושה ראשונה לא קדשה לעתיד לבא לא חילק בין מקדש וירושלים לשאר א\\\"י י\\\"ל אין משם ראיה דכיון דחזינן דרבי יהושע דהלכתא כוותיה סבר דקדשה לעתיד לבא ולא הזכיר אלא ירושלים ומקדש ממילא אית לן למשמע דבהני דוקא קאמרי לא בשאר א\\\"י ונתן רבינו טעם לדבר אך הנך מקומות דקתני אם אין מקדש ירקב קשו ואין לומר דאתו דלא כהלכתא שהרי רבינו פסק כן בפ\\\"ז מהלכות מעשר שני וצ\\\"ע. ומ\\\"ש ולא עוד אלא שאני אומר שאפילו לרבי יוסי דאמר קדושה שניה קדשה לעתיד לבא לא אמר אלא לשאר א\\\"י וכו' אני אומר אם קבלה נקבל ואם לדין יש תשובה דאעפ\\\"כ למה היה מניח עזרא מלקדש לעתיד לבא שמא בזמן החרבן יותן לנו רשות להקריב. ומ\\\"ש לפיכך הנכנס עתה שם אין בו כרת אני תמה דמעיקרא משמע דכמספק אמרה ובסוף דבריו נראה דפשיטא ליה וחידוש גדול הוא והיה צריך להביא ראיה. ומ\\\"מ מ\\\"ש רבינו אבל חיוב הארץ בשביעית ובמעשרות אינו אלא מפני שהוא כיבוש רבים וכיון שנלקחה הארץ מידיהם בטל הכיבוש וכו' וכיון שעלה עזרא וקדשה לא קדשה בכיבוש אלא בחזקה שהחזיקו בה וכו' איני יודע מה כח חזקה גדול מכח כיבוש ולמה לא נאמר בחזקה גם כן משנלקחה הארץ מידנו בטלה חזקה ותו בראשונה שנתקדשה בכיבוש וכי לא היה שם חזקה אטו מי עדיפא חזקה בלא כיבוש מחזקה עם כיבוש וצל\\\"ע:\",1,0],[8,359,7,1,\"מצות עשה ליראה מן המקדש וכו' ולא מן המקדש אתה ירא וכו'. בפרק קמא דיבמות (דף ו':):\",1,0],[8,359,7,2,\"ואיזהו יראתו וכו' עד אלא יקיפו מבחוץ. שם ובפרק הרואה (ברכות דף נ״ד):\",1,0],[8,359,7,2,\"ומ״ש ולא יכנס לו אלא לדבר מצוה. בפרק בני העיר (מגילה דף כ״ח:) אמרינן הכי לגבי בית הכנסת וכ״ש לבית המקדש:\",2,0],[8,359,7,3,\"וכל הנכנסין להר הבית נכנסין דרך ימין וכו' עד ויקרבוך. בפרק שני דמדות (משנה ב') וכר\\\"י:\",1,0],[8,359,7,4,\"כל שהשלים עבודה וכו'. בפרק הוציאו לו (יומא דף נ״ג) כהנים בעבודתן ולוים בדוכנן וישראל במעמדן כשהן נפטרים לא היו מחזירים פניהם והולכים אלא מצדדין פניהם והולכים ומשמע דמצדדין דקתני היינו משום דא״א לאדם לילך לאחוריו לגמרי וכן א״א לו לילך לאחוריו אלא מעט מעט אע״פ שהוא מצדד ולפיכך כתב רבינו מעט מעט. ומ״ש בנחת איני יודע לו טעם דבכלל מעט מעט הוא וסמ״ג השמיטו:\",1,0],[8,359,7,5,\"לא יקל אדם את ראשו כנגד שער מזרחי של עזרה וכו'. בפרק הרואה (ברכות דף נ״ד):\",1,0],[8,359,7,5,\"וכל הנכנס לעזרה יהלך בנחת. כתב הראב\\\"ד פי' שלא ילך דרך הדיוטות:\",2,0],[8,359,7,6,\"ואסור לכל אדם לישב בכל העזרה וכו'. בסוף פרק אלו נאמרין (דף ו':) ופ\\\"ק דתמיד (דף כ\\\"ז.) ופ\\\"ב דיומא (דף כ\\\"ה):\",1,0],[8,359,7,6,\"ומה שכתב והסנהדרין שהיו יושבים בלשכת הגזית לא היו יושבים בחציה של חול. בפרק ב' דיומא (דף כ\\\"ה.) אמרינן דלשכת הגזית היתה בנויה חציה בקדש וחציה בחול מדקתני התם דזקן יושב במערבה ואי לאו דחציה בחול היכי מצי יתיב:\",2,0],[8,359,7,7,\"אף על פי שהמקדש היום וכו'. בפרק בני העיר (מגילה דף כ״ח) ופירקא קמא דיבמות (דף ו':).\",1,0],[8,359,7,7,\"ומה שכתב מה שמירת שבת לעולם וכו'. לשון סיפרא:\",2,0],[8,359,7,8,\"בזמן שהמקדש בנוי וכו'. בפרק הרואה (ברכות דף ס״א:) אהא דתנן לא יקל ראשו כנגד שער המזרח אמר רבי יוחנן לא אמרו אלא מן הצופים ולפנים וברואה וכשאין גדר ובזמן שהשכינה שורה ופירש״י מן הצופים מקום שיכולים לראות משם הר הבית ומשם והלאה אין יכולים לראותו. וברואה שיכול לראות משם פרט אם מקום נמוך הוא. ובשאין גדר מפסיק בינו להר הבית. ובזמן שהשכינה שורה שבית המקדש קיים:\",1,0],[8,359,7,9,\"אסור לאדם לעולם שיפנה או שיישן בין מזרח למערב וכו'. בפרק הרואה (ברכות דף ס״א) [מדין שיפנה אמנם מדין שינה לא נזכר שם אלא (בדף ה') גבי אבא בנימין].\",1,0],[8,359,7,9,\"ומה שכתב וכל המטיל מים מן הצופים ולפנים וכו'. בירושלמי בפרק הרואה (דף י\\\"ד:) וכל הדברים הללו ביארתי באר היטב בספר בית יוסף שעל טור א\\\"ח בסימן ב' עיין עליו ויש ט\\\"ס בדברי רבינו וצריך להגיה וכל המטיל מים מן הצופים ולפנים לא ישב ופניו כלפי הקדש אלא לצפון או לדרום או יסלק הקדש לצדדין וכן כתוב בספרי רבינו המוגהים:\",2,0],[8,359,7,10,\"ואסור לאדם שיעשה וכו'. עד אעפ״י שיש לה ז' קנים. בפרק כל הצלמים (עבודה זרה דף מ״ג):\",1,0],[8,359,7,11,\"שלש מחנות היו במדבר וכו' עד מעלה יתירה בבית עולמים. בפרק בתרא דזבחים (דף קי\\\"ו קי\\\"ז):\",1,0],[8,359,7,12,\"כל ארץ ישראל מקודשת מכל הארצות וכו':\",1,0],[8,359,7,13,\"עשר קדושות הן וכו'. בפ\\\"ק דכלים (משנה ז):\",1,0],[8,359,7,13,\"ומ\\\"ש ואין קוברים בתוכן מת עד שירצו שבעה טובי העיר. לשון המשנה שם ומשכיבין לתוכן מת עד שירצו יצא אין מחזירין אותו ופירש שם רבינו עד שירצו אנשי המדינה בכלל או שבעת טובי העיר שאם רצו לקוברו במקום מהמדינה יוכלו לקוברו יצא המת מהמדינה אין להם להחזירו למדינה לקברו שם ואפילו ירצו כולם, נראה שהוא מפרש דמשכיבין לתוכן מת היינו שמניחין אותו במשכבו ואין קוברין אותו בעיר עד שירצו בני המדינה. ובהשגות א\\\"א לא שמעתי כאן לא רצון טובי העיר וכו' נראה שהוא גורס ומסבבין לתוכן מת עד שירצו ואין בדבריו השגה לדברי רבינו כי לא שמעתי אינה ראיה:\",2,0],[8,359,7,13,\"רצו בני העיר להוציא הקבר מהמדינה וכו'. עד מפנין אותו. באבל רבתי פרק י\\\"ד ובירושלמי סוף נזיר איתיה נמי אלא שיש שם קצת חילוף:\",3,0],[8,359,7,14,\"ירושלים מקודשת וכו'. בפ\\\"ק דכלים (משנה ח):\",1,0],[8,359,7,14,\"ואלו דברים שנאמרו בירושלים אין מלינין וכו'. בס״פ מרובה (בבא קמא פ״ב:) י' דברים נאמרו בירושלים אין הבית חלוט בה ואינה מביאה עגלה ערופה ואינה נעשית עיר הנדחת ואינה מטמאה בנגעים ואין מוציאין בה זיזין וגזוזטראות ואין עושין בה אשפתות ואין עושין בה כבשונות ואין עושין בה גנות ופרדסין חוץ מגינת ורדין שהיתה מימות נביאים הראשונים ואין מגדלין בה תרנגולין ואין מלינין בה את המת ובגמרא יהיב טעמא לכולהו ופירש״י אין הבית חלוט בה כדין בתי ערי חומה:\",2,0],[8,359,7,14,\"ומ\\\"ש ואין מעבירין בתוכה עצמות אדם ואין נותנין בתוכה מקום לגר תושב. תוספתא בפ\\\"ו דנגעים.\",3,0],[8,359,7,14,\"ומ״ש ואין משכירין בה בתים. בפ״ק דיומא (דף י״ב) ובפרק בני העיר (מגילה דף כ״ז) ומפרש טעמא מפני שאינן שלהם ופירש״י אין משכירין בעלי בתים את בתיהם לעולי רגלים אלא בחנם נותנים להם ונכנסין לתוכן.\",4,0],[8,359,7,14,\"ומ\\\"ש ואין מקיימין בה קברות חוץ מקברי בית דוד וקבר חולדה וכו'. בתוספתא (שם) ובספ\\\"ק דבתרא כל הקברות מתפנין חוץ מקבר המלך ומקבר הנביא ר\\\"ע אומר אף קבר המלך וקבר הנביא מתפנין אמרו לו והלא קבר בית דוד וקבר חולדה הנביאה היו בירושלים ולא נגע בהם אדם מעולם. ואע\\\"ג דאמר ר\\\"ע משם ראיה מחילה היתה עשויה להם והיתה מוציאה את הטומאה לנחל קדרון כדאיתא בירושלמי סוף נזיר לא חש רבינו לכתוב אלא דברי ת\\\"ק.\",5,0],[8,359,7,14,\"ומ״ש וכן לא יגדלו הכהנים תרנגולים בכל א״י וכו'. משנה בס״פ מרובה (בבא קמא דף ע״ט:):\",6,0],[8,359,7,15,\"הר הבית מקודש ממנה וכו'. בפרק קמא דכלים (משנה ח'):\",1,0],[8,359,7,15,\"ומה שכתב ומותר להכניס המת עצמו להר הבית וכו'. בפרק אלו דברים (פסחים דף ס״ז) ובפרק היה נוטל (סוטה דף כ' ע״ב):\",2,0],[8,359,7,16,\"החיל מקודש ממנו וכו'. בפ\\\"ק דכלים. כתב הראב\\\"ד אף זה מדבריהם עכ\\\"ל:\",1,0],[8,359,7,16,\"ומ\\\"ש ובועל נדה:\",2,0],[8,359,7,17,\"עזרת הנשים מקודשת וכו'. בפ\\\"ק דכלים עזרת הנשים מקודשת ממנו שאין טבול יום נכנס לשם ואין חייבין עליה חטאת.\",1,0],[8,359,7,17,\"ומ\\\"ש אבל מן התורה מותר לטבול יום להכנס למחנה לויה. בפ\\\"ק דיבמות (דף י'):\",2,0],[8,359,7,18,\"עזרת ישראל מקודשת וכו'. בפרק קמא דכלים עזרת ישראל מקודשת ממנה שאין מחוסר כפורים נכנס לשם וחייבים עליה חטאת ותני עלה בתוספתא שחייבין על זדונה כרת:\",1,0],[8,359,7,19,\"עזרת הכהנים מקודשת ממנה וכו'. גם זה שם:\",1,0],[8,359,7,20,\"בין האולם ולמזבח וכו'. גם זה שם.\",1,0],[8,359,7,20,\"ומה שכתב וקרועי בגדים כתב הר\\\"י קורקוס ז\\\"ל דאפשר דטעמו מדכתיב ראשיכם אל תפרעו ובגדיכם לא תפרומו הוקשו קרועי בגדים לפרועי ראש:\",2,0],[8,359,7,21,\"ההיכל מקודש וכו' בית קדש הקדשים וכו'. גם זה בפרק קמא דכלים:\",1,0],[8,359,7,23,\"מקום שהיה בעלייה וכו'. תוספתא פרק קמא דכלים ואיתא בפרק כיצד צולין (פסחים דף פ״ו) ואף על פי ששם שנינו אין נכנסים לה אלא פעם אחת בשבוע ואמרי לה פעמיים בשבוע ואמרי לה פעם אחת ביובל נקט רבינו כמאן דאמר אחת בשבוע דהיא סברא מציעתא:\",1,0],[8,359,7,23,\"בשעה שנכנסין הבנאים לבנות ולתקן וכו'. בתוספתא דכלים פירקא קמא הכל נכנסים לבנות ולתקן ולהוציא את הטומאה מצוה בכהנים אין כהנים נכנסין לויים [אין לויים] נכנסין ישראלים [מצוה] בטהורים אין טהורים נכנסין טמאים מצוה בתמימים אין תמימים נכנסין בעלי מומין ומפרש בסוף עירובין (דף ק\\\"ה) מצוה בתמימים אין שם תמימים נכנסין בעלי מומין מצוה בטהורים אין שם טהורים נכנסין טמאים אידי ואידי כהנים אין ישראלים לא.\",2,0],[8,359,7,23,\"ומה שכתב רבינו טמא ובעל מום וכו'. שם בסוף עירובין איבעיא להו טמא ובעל מום אי זה מהם נכנס רב חייא בר אשי אמר רב טמא נכנס דהא אשתרי בעבודת צבור ר\\\"א אמר בעל מום נכנס דהא אשתרי באכילת קדשים ופסק רבינו כר\\\"א דפליג ארב משום דאמר טומאה הותרה בציבור ובפירקא קמא דיומא (דף ו':) איתמר טומאת המת רב נחמן אמר הותרה בצבור ורב ששת אמר דחויה היא בצבור וקיימא לן דהלכה כרב ששת לגבי רב נחמן באיסורי ואם כן דחויה היא בצבור ולא הותרה ולפי זה הנוסחא הנכונה בספרי רבינו היא יכנס בעל מום ואל יכנס טמא כמ\\\"ש בספרים ולא כמו שראיתי מי שהגיה יכנס טמא ואל יכנס בעל מום וטעות הוא בידו שעלה בדעתו שמה שכתב רבינו שהטומאה דחויה בצבור הוא טעם להקל בטמא ואינו אלא הוא טעם להחמיר בטמא כמו שכתבתי:\",3,0],[8,359,7,23,\"וכל הנכנסים להיכל לתקן יכנסו בתיבות. בפרק רביעי דמדות (משנה ה) ולולין היו פתוחים בעלייה לבית קדש הקדשים שבהם היו משלשלין את האומנים בתיבות כדי שלא יזונו עיניהם מבית קדש הקדשים ויש לתמוה דמשמע ממתניתין דדוקא בקדש הקדשים אמרו ולא בהיכל ורבינו שכתב הנכנסים להיכל מנין לו.\",4,0],[8,359,7,23,\"ומה שכתב אם אין שם תיבות או אי אפשר להם שיעשו בתיבות יכנסו דרך פתחים. בתוספתא דכלים פירקא קמא:\",5,0],[8,359,8,1,\"שמירת המקדש מצות עשה וכו' אינו דומה פלטרין שיש עליו שומרים וכו'. בספרי זוטא פרשת קרח על\",1,0],[8,359,8,1,\"פסוק וארבע ועשרים עדה וכו' והיכן וזר לא יקרב:\",2,0],[8,359,8,1,\"היו שומרים וכו' עד סוף\",3,0],[8,359,8,4,\"מצות שמירתו וכו'.\",1,0],[8,359,8,4,\"בספרי הפרק. בפירקא קמא דתמיד פרשת קרח על פסוק (דף כ\\\"ה:) ובפירקא קמא דמדות אתה ובניך אתך לפני אהל מועד: (משנה א'):\",2,0],[8,359,8,5,\"ומ\\\"ש והרובין. מפרש בגמרא פ\\\"ק דתמיד (דף כ\\\"ג) דהיינו נערים שלא הגיעו לעשות עבודה כגון פחותים מי\\\"ג:\",1,0],[8,359,8,6,\"ומה שכתב ומניחים אותם כנגד ראשיהם. הוא כאוקימתא דרב פפא בר״פ בא לו (יומא דף ס״ט) דהכי מסיק גמרא דכנגד ראשיהם היו מניחים אותם לא תחת ראשיהם כי היכי דלא ליתהנו מבגדי כהונה ואע״ג דבתר הכי משמע דבגדי כהונה ניתנו ליהנות מהם איכא למימר דההיא דרך לבישה דוקא ועל מה ששנינו (תמיד דף כ״ח) העמידו עושי חביתין לעשות חביתין פריך בגמרא למימרא דחביתין הוו קדימי והתניא מנין שאין דבר קודם לתמיד של שחר כו' אמר רב יהודה להחם חמין לרבוכה ופירש״י דמותר להחם חמין לעסוק בה ומשמגיע זמן הקטרתה לאחר שיקריבו איברי התמיד יקטיר כמו כן את החביתין ואיני יודע למה קיצר רבינו מלבאר זה:\",1,0],[8,359,8,12,\"ומ\\\"ש רבינו חוץ מלילי שבת וכו' ואע\\\"ג דקיימא לן דאין שבות במקדש משום דכהנים זריזים הם וטלטול נר בשבת אינו אלא שבות שאני הכא דאפשר בנרות הדלוקים מערב שבת:\",1,0],[8,360,1,1,\"מצות עשה לעשות שמן המשחה וכו' שנאמר ועשית אותו שמן משחת קדש. פשוט הוא:\",1,0],[8,360,1,2,\"וככה עשהו משה רבינו במדבר לקח מן המור והקנמון והקדה וכו'. בפירקא קמא דכריתות (דף ה') תנו רבנן שמן המשחה מר דרור חמש מאות קדה חמש מאות קנמן בשם מחציתו מאתים וחמשים וקנה בשם מאתים וחמשים נמצאו כולם אלף ושבע מאות וחמשים מנינא קמשמע לן הא קא קשיא ליה אימא קנה בשם כקנמן בשם מה קנמן בשם מחציתו מאתים וחמשים אף קנה בשם מחציתו מאתים וחמשים דהוה ליה תרין אלפין ואימא הכי נמי אם כן לכתוב קרא קנמן בשם וקנה בשם מחצה ומחצה מאתים וחמשים. ופירש רש\\\"י קנמן בשם חמש מאות דהכי אמר קרא מחציתו מאתים וחמשים דלהכי נקט מחציתו שלא יהו שוקלים אותו הכל ביחד אלא לחצאין כדי שיהו שם שתי הכרעות. תנא הכי קשיא ליה כלומר להכי אשמעינן ברייתא דאי ממשמעותא דקרא ה\\\"א קנה בשם כקנמן בשם דמחציתו דקרא אתרווייהו קאי קמשמע לן:\",1,0],[8,360,1,2,\"ומ\\\"ש רבינו ושוחק כל אחד ואחד לבדו ועירב הכל. נראה דיליף מקטרת דכתיב ביה ממולח ומתרגמינן מערב אבל צריך טעם מניין לרבינו ששוחק ואח\\\"כ מערב דילמא מערב ואח\\\"כ שוחק והכי משמע מקרא דברישא כתיב ממולח ובתר הכי כתיב ושחקת ונראה דמשמע לרבינו שיותר יפה מתערב אחר שחיקה מקודם שחיקה וקרא לאו לסידרא איכתיב. ויותר נראה לומר שטעם רבינו מפני שהוא מפרש דמאי דכתיב בקטרת בד בבד יהיה היינו לומר שיהיו שחוקים כל אחד לבדו וכמו שפירש הרד\\\"ק בספר השרשים:\",2,0],[8,360,1,2,\"ומה שכתב ושרה אותם במים זכים וכו'. בפרק קמא דכריתות ת\\\"ר שמן המשחה שלקו העיקרים ד\\\"ר יהודה א\\\"ל ר' יוסי והלא לסוך העיקרים אינו סיפק כיצד עושה הביאו העיקרים ושראם במים והציף עליהן שמן המשחה וקלט את הריח וקפחו ופירש\\\"י לסוך העיקרים בשמן אינו סיפק דשמן לא הוה אלא י\\\"ב לוגין ועיקרין הוו טובא שס\\\"ח מנין. ושראם במים שיבלעו המים ולכשיציף עליהם השמן לא יבליעוהו. וקפחו קנחו קפחו משה לשמן מעל העיקרים ונתנו בצלוחית:\",3,0],[8,360,1,3,\"המור הוא הדם הצרור בחיה שבהודו וכו'. זה פשוט בפי העולם לומר שמור הוא מוסק. ובהשגות אין דעתי מקבלת שיכנסו במעשה הקדש וכו'. מ\\\"ש שאין דעתי מקבלת שיכנסו במעשה הקדש דם שום חיה כ\\\"ש דם חיה טמאה יש לומר שכיון שנשתנה מצורת דם ונעשה כעפר בעלמא והוא בשם מריח ריח טוב ביותר למה יגרע. ומ\\\"ש עוד אבל המור הוא האמור בשיר השירים באתי לגני וגו' אריתי מורי עם בשמי והוא מין עשב או ממין אילן וריחו נודף כן הוא דעת הרמב\\\"ן בפירוש התורה בפרשת כי תשא וכתב שדעתו שהוא השרף הנקרא מירא:\",1,0],[8,360,1,3,\"ומ\\\"ש והקנמון הוא העץ שבא מאיי הודו וכו'. הוא נקרא בערבי עוד הנדי וכ\\\"כ בפירוש המשנה.\",2,0],[8,360,1,3,\"ומ\\\"ש והקדה הוא הקשט יש לתמוה על זה שהרי אונקלוס תרגם קדה קציעתא ורבינו בפרק שאחר זה מנה קציעה וקשט בשתים.\",3,0],[8,360,1,3,\"ומ\\\"ש וקנה בשם הם הקנים הדקים כתבן האדומים וכו'. נראה שהוא התבן המבושם הנקרא בערבי אדכר ובלע\\\"ז אישקינ\\\"טי והרמב\\\"ן כתב בפירוש התורה שקנה בשם הוא הנקרא בערבי דרציני והוא קנילא:\",4,0],[8,360,1,4,\"העושה שמן המשחה כמעשה הזה וכו' במזיד חייב כרת וכו'. ובפ\\\"ק דכריתות שנינו שבשוגג חייב חטאת.\",1,0],[8,360,1,4,\"ומ\\\"ש והוא שעשה אותו להמשח בו אבל אם עשהו להתלמד או ליתנו לאחרים פטור וכו' ואין חייבין אלא על סיכת שמן המשחה שעשה משה שנאמר ממנו וכו'. שם (דף ה') ת\\\"ר המפטם את השמן ללמד בו למוסרו לצבור פטור לסוך חייב והסך ממנו פטור לפי שאין חייבים אלא על סיכת שמן המשחה שעשה משה בלבד. ותניא תו התם כמה יסוך ויהא חייב ר' מאיר אומר כל שהוא ר' יהודה אומר כזית וידוע דהלכה כר' יהודה.\",2,0],[8,360,1,4,\"ומה שכתב ומעולם לא נעשה שמן אחר חוץ ממה שעשה משה. בפירקא קמא דכריתות ת\\\"ר שמן [שעשה משה במדבר] בו שלקו העיקרים וכו' ובו נמשחו כהנים גדולים ומלכים וכולו קיים לעתיד לבא ובפרק שתי מדות אמרו הין דעבד משה לשמן המשחה כיון דלדורות לא היה צריך לפי שעה הוא דעבדיה ואגניז:\",3,0],[8,360,1,6,\"אחד הסך את עצמו וכו'. פשוט הוא.\",1,0],[8,360,1,6,\"ומ\\\"ש הסך כלים ובהמה ועכו\\\"ם שהם כמותה או שסך מתים בו פטור וכו'. ברייתא שם פ\\\"ק דכריתות (דף י':):\",2,0],[8,360,1,7,\"אין מושחין ממנו לדורות וכו'. בפ\\\"ק דכריתות.\",1,0],[8,360,1,7,\"ומ\\\"ש ומשוח מלחמה פשוט הוא ששמו מוכיח עליו שנקרא משוח.\",2,0],[8,360,1,7,\"ומ\\\"ש אפילו כהן בן כהן מושחין אותו. שם אפילו כ\\\"ג בן כ\\\"ג טעון משיחה ויליף לה מקרא:\",3,0],[8,360,1,8,\"ומ\\\"ש בבית שני שלא היה שמן המשחה היה כ\\\"ג מתרבה בלבישת בגדים בלבד וכו'. בפרק בתרא דהוריות (דף י\\\"ב) מתבאר זה ובפרק ד' כתב רבינו שכ\\\"ג מושחים אותו שבעה ימים זה אחר זה וכן מרבים אותו בשמנה בגדים ז' ימים זה אחר זה:\",1,0],[8,360,1,9,\"כיצד מושחין את הכהן וכו' ומלכי בית דוד מושחים אותו כמין נזר על ראשו. בפ\\\"ק דכריתות ת\\\"ר מושחין את המלכים כמין נזר ואת הכהנים כמין כי [מאי כמין כי אמר רב מנשיא כמין כי יונית] תני חדא בתחילה מציק שמן על ראשו ואחר כך נותן לו שמן בין ריסי עיניו ותני אחריתי בתחלה נותן לו שמן בין ריסי עיניו ואח\\\"כ מציק לו שמן על ראשו ומפרש התם טעמייהו ופסק רבינו כברייתא קמייתא דמסתבר טעמיה.\",1,0],[8,360,1,9,\"ומה שכתב ולא ימשח במקומות אחרות ולא ירבה בשמן. פשוט הוא שכל שסך במקום שאינו צריך דמי לשאר אדם שסך בו וה\\\"ה למרבה בשמן שהרי אינו צריך:\",2,0],[8,360,1,10,\"הנותן משמן המשחה ע\\\"ג מלך וכו'. שם (דף ו':) פלוגתא דר' מאיר ורבי יהודה ופסק כרבי יהודה דפטר:\",1,0],[8,360,1,10,\"ומ\\\"ש אבל הסך ממנו אפילו למלך וכ\\\"ג חייב וכו'. נלמד ממה שיבא בסמוך.\",2,0],[8,360,1,10,\"ומ\\\"ש וכ\\\"ג שנטל משמן המשחה שבראשו וסך במעיו חייב כרת. מימרא שם (דף ז') ויליף לה מדכתיב על בשר אדם לא ייסך.\",3,0],[8,360,1,10,\"ומ\\\"ש והוא שיסוך ממנו בכזית. כבר כתבתי בסמוך שזה דעת רבי יהודה דהלכה כוותיה לגבי ר' מאיר:\",4,0],[8,360,1,10,\"וכתב בהשגות והוא שיסוך ממנו בכזית א\\\"א לא מחוור מתוך הגמרא דכריתות וכו'. וטעמו מדתניא התם הסך בשמן המשחה למלכים ולכהנים ר\\\"מ מחייב ורבי יהודה פוטר וכמה יסוך ויהא חייב רבי מאיר אומר כל שהוא רבי יהודה אומר כזית והאמר ר' יהודה פטור כי פטר רבי יהודה גבי מלכים וכהנים גבי הדיוט מחייב ר' מאיר ור' יהודה במאי פליגי אמר רב יוסף בהא פליגי רבי מאיר סבר על בשר אדם לא ייסך כתיב וכתיב ואשר יתן ממנו על זר מה סיכה כל שהוא אף נתינה כל שהוא ורבי יהודה סבר ילפינן נתינה דעל זר מנתינה דעלמא מה נתינה דעלמא כזית אף נתינה דעל זר כזית אבל סיכה לממשח מלכים וכהנים ד\\\"ה כל שהוא ואמר רב יוסף במאי פליגי ר' מאיר ור' יהודה גבי מלכים וכהנים רבי מאיר סבר ואשר יתן ממנו על זר כתיב ומלך וכהן השתא זרים נינהו ורבי יהודה סבר בעינן עד דאיכא זר מתחלתו ועד סופו ומלך וכהן לאו זרים הוו ופירש רש\\\"י למלכים וכהנים גדולים לאחר שנמשחו. מה סיכה כל שהוא דלא אשכחן שיעור בסיכה וכו'. נתינה בעלמא כזית דגמרינן מנתינה דונתן לכהן את הקדש דכתיב ביה אכילה [ואיש כי יאכל קודש] וכל אכילה כזית. מעיקרא לאו זרים הם דהא נמשחו מתחלה עכ\\\"ל. ופשטא דגמרא כהראב\\\"ד דדוקא בנתינה הוא דאמר רבי יהודה כזית משום דילפא מנתינה דעלמא אבל סיכה דלא ילפא מנתינה הויא בכל שהוא לכולי עלמא. ולדעת רבינו אפשר לומר דכי יליף רבי יהודה נתינה דעל זר בכזית מנתינה דעלמא ה\\\"ה לסיכה דזר דהויא בכזית לדידיה דילפא מנתינה דאיתקש סיכה לנתינה והיינו דקתני וכמה יסוך ויהא חייב ר' מאיר [סבר] כל שהו ור\\\"י כזית ואם איתא כמה יתן הוה ליה למיתני ולא כמה יסוך אלא ודאי בסיכה נמי סבר רבי יהודה דצריך כזית והא דמסיים רב יוסף אבל סיכה לממשח מלכים וכהנים ד\\\"ה כל שהו היינו במושב מלכים וכהנים שלא נמשחו אבל אם כבר נמשחו פטור לרבי יהודה על הנתינה דלאו זרים נינהו ובפחות מכזית פטור אף על הסיכה:\",5,0],[8,360,1,11,\"אין מושחין את המלכים אלא ע\\\"ג המעיין. שם (דף ה':) ויהיב טעמא כדי שתמשך מלכותן ומייתי לה מדכתיב והורדתם אותו אל גיחון:\",1,0],[8,360,1,11,\"ואין מושחין מלך בן מלך וכו' עד מפני יהויקים אחיו. שם:\",2,0],[8,360,1,11,\"ומ\\\"ש וזה שמשח אלישע ליהוא לא בשמן המשחה משחו וכו'. גם זה שם:\",3,0],[8,360,1,12,\"כל כלי המקדש שעשה משה במדבר וכו' ודבר זה אינו נוהג לדורות וכו'. בפ' שני דשבועות (דף ט\\\"ו) כל הכלים שעשה משה משיחתן מקדשתן מכאן ואילך עבודתן מחנכתן ומייתי לה התם מקראי ואיתא נמי להאי ברייתא בפ\\\"ק דיומא עלה י\\\"ב:\",1,0],[8,360,1,13,\"הכפות והקערות וכו' ושאר כלי שרת כולן של כסף ושל זהב היו. בס״פ המזבח מקדש (זבחים דף פ״ח:) אמרינן אין עניות במקום עשירות.\",1,0],[8,360,1,13,\"ומ\\\"ש ומותר לעשותן משאר מתכות כמו שביארנו. בפרק ראשון מהלכות בית הבחירה.\",2,0],[8,360,1,13,\"ומ\\\"ש וכולן מתקדשין במלאכתן. נתבאר בסמוך.\",3,0],[8,360,1,13,\"ומ\\\"ש ואם נשברו מתיך אותם ועושה אותם כלי אחר ואין קדושתן מסתלקת מהן לעולם:\",4,0],[8,360,1,14,\"כלי הקדש שניקבו או שנסדקו אין סותמין אותן וכו'. בסוף פרק המזבח מקדש ת\\\"ר כלי קדש שניקבו אין מתיכין אותן ואין מתיכין לתוכן אבר נפגמו אין מתקנין אותן ופירש\\\"י אין מתיכין אותן כמו שעושין למדות מנוקבות שמתיכין אותו סביבות הנקב ונסתם הנקב. ואין מתיכין לתוכן אבר לסתום הנקב וכולהו משום דמיחזי כעניות ולאו אורח ארעא:\",1,0],[8,360,1,15,\"סכין שנשמט מן הנצב וכו'. שם סכין שנפגמה אין משחיזין את פגימתה נשמטה אין מחזירין אותה אבא שאול אומר סכין מטרפת היתה במקדש ונמנו עליה כהנים וגנזוה ופירש\\\"י נפגם פגימה גדולה שתיקון השחזתה ניכר. סכין מטרפת שהיתה רכה ליפגם פגימות דקות תמיד ומטרפת את הקדשים.\",1,0],[8,360,1,15,\"ומ\\\"ש רבינו שגונזין אותם בצד ההיכל וכו':\",2,0],[8,360,1,16,\"שתי מדות של יבש היו במקדש וכו' עד הואיל והיה במקדש בימי משה שמדד בו שמן לשמן המשחה. משנה וגמרא במנחות פרק שתי מדות (מנחות דף פ״ח) ופסק כת״ק:\",1,0],[8,360,1,18,\"ומה שכתב ובחצי לוג שהיה במקדש היו מודדין מים למי סוטה וכו' עד שאמרנו. משנה וגמרא שם:\",1,0],[8,360,1,19,\"כל המדות האלו קדש וכו'. משנה וגמרא שם ופסק כת\\\"ק. ופירוש בירוצי היינו מה שנופל מן הכלי לאחר שנתמלא:\",1,0],[8,360,2,1,\"הקטרת נעשית בכל שנה ושנה ועשייתו וכו' עד י\\\"א סממנים נאמרו לו למשה בסיני. בפ\\\"ק דכריתות (דף ו') ומפרש התם קראי דהוו אחד עשר:\",1,0],[8,360,2,2,\"ומ\\\"ש ומוסיפין עליהם בלא משקל מלח סדומית. כן שנינו בברייתא בפ\\\"ק דכריתות (דף ו' ע\\\"א) ובירושלמי פ' טרף בקלפי מלח סדומית רובע כלומר רובע הקב ואינו שיעור משקל אלא שיעור מדה. ואין לתמוה למה לא כתב רובע הקב כלשון הברייתא שי\\\"ל שסמך על מה שכתב כן לקמן בסמוך.\",1,0],[8,360,2,2,\"ומ\\\"ש וכפת הירדן ועשב אחד שמעלה עשן. שם בברייתא הנזכרת.\",2,0],[8,360,2,2,\"ומה שכתב ולא היו יודעים אותו אלא אנשים ידועים וכו'. בפרק אמר להם הממונה:\",3,0],[8,360,2,3,\"ומה שכתב וזהו משקל אחד עשר סמנים וכו' עד להקטיר ביום הכיפורים. הכל בברייתא שהזכרתי לעיל. ובמקום נטף שנו בברייתא הנזכרת צרי ובסוף הברייתא רבן שמעון בן גמליאל אומר הצרי אינו אלא שרף הנוטף מעצי הקטף. ודע שדינר הוא משקל מיתקאל שהוא דרמא וחצי והדרמא משקל ששים וארבע שעורות בינוניות.\",1,0],[8,360,2,3,\"ומה שכתב והשאר הוא מותר הקטרת שאמרנו בשקלים כלומר שבכל שנה היה נשאר מאותם שלשה מנין שלא היה מקטיר מהם אלא מלא חפניו והמותר היו עושים ממנו מה שכתב רבינו בהלכות שקלים:\",2,0],[8,360,2,4,\"ומ\\\"ש נטף האמור בתורה הוא עצי הקטף וכו' בברייתא הנזכרת לעיל רבן שמעון בן גמליאל אומר הצרי אינו אלא שרף הנוטף מעצי הקטף. וכתב הרמב\\\"ן בפירוש התורה ראיתי לרב רבינו משה שמכניס בקטרת עץ האילן הנקרא בערבי עוד בלסאן נראה שסבור כי רבן שמעון בן גמליאל בא לחלוק ולומר שאין הצרי מסמני הקטרת כי הוא אינו אלא שרף ובקטרת אין השרף נכנס בו אלא הקטף עצמו עכ\\\"ל. ואיני יודע מניין לו שלא יכנס השרף בקטרת ועוד שהרי החלבנה והלבונה שרף הם והם נכנסים בקטרת ויותר נכון לומר שרשב\\\"ג בא לפרש דברי ת\\\"ק ולומר אל תחשוב שצרי השנוי כאן הוא טריאק\\\"א כמו הצרי אין בגלעד שזה ודאי לא יכנס בקטרת אבל הוא שרף הנוטף מעצי הקטף שקוטפים העץ ונוטף ממנו שרף הוא שהיה נכנס בקטרת ונכון הוא שיהיה העץ הזה עץ הבלסאמ\\\"ו כדברי הרמב\\\"ן וכ\\\"כ בערוך בערך קטף ולדעת רבינו שמכניס בקטרת עוד בלסאן נאמר שהוא ז\\\"ל מפרש שהעץ עצמו של הבלסאן נקרא צרי ורשב\\\"ג בא לחלוק ולומר שצרי אינו העץ עצמו אלא השרף הנוטף ממנו כשקוטפין אותו והוא הנכנס בקטרת לא העץ ופסק כת\\\"ק:\",1,0],[8,360,2,4,\"ומ\\\"ש והשחלת הוא הצפורן וכו'. כן תרגם אונקלוס שחלת טופרא.\",2,0],[8,360,2,4,\"ומה שכתב והחלבנה כמו דבש שחור וריחו קשה כך אמרו בפ\\\"ק דכריתות שהחלבנה ריחה רע ונראה מדברי רבינו שהוא הנקרא בערבי מיעה סאילה שהוא כמו דבש שחור והעולם לועזים חלבנה גאלבנ\\\"ו ובפירוש המשנה פרק קמא דכריתות כתב המעתיק שמיעה הוא אשטור\\\"ק וטעות הוא בידו וכן מה שכתב שיש אומרים שחלבנה הוא מחלב ויש אומרים שהוא לדאן הכל טעות.\",3,0],[8,360,2,4,\"ומ\\\"ש רבינו וזהו שמות הסמנים בערבי עוד באלסאן הוא נטף וקראוהו בברייתא הנזכרת צרי וכבר נתבאר.\",4,0],[8,360,2,4,\"ואצפר איל טיב הוא שחלת.\",5,0],[8,360,2,4,\"ומיעה הוא חלבנה.\",6,0],[8,360,2,4,\"ולכאן הוא לבונה.\",7,0],[8,360,2,4,\"ומוסק הוא מור וכבר נתבאר בפרק ראשון שיש חולקים בזה.\",8,0],[8,360,2,4,\"וקציעה הוא שמו גם בברייתא הנזכרת.\",9,0],[8,360,2,4,\"וסנבאל אלנדרין הוא שבלת נרד השנוי בברייתא הנזכרת.\",10,0],[8,360,2,4,\"וזעפרן הוא כרכום השנוי בברייתא.\",11,0],[8,360,2,4,\"וקושט הוא שמו גם בברייתא הנזכרת.\",12,0],[8,360,2,4,\"ועוד הירדי הוא קנמון.\",13,0],[8,360,2,4,\"וקסר סליכא הוא קלופה השנוי בברייתא הנזכרת.\",14,0],[8,360,2,4,\"וענבר הוא כפת הירדן:\",15,0],[8,360,2,4,\"כתב סמ״ג קנמון אינו קניל״ה בלע״ז שהרי מקניל״ה יש הרבה ואילו מקנמון אמרינן בפרק במה אשה (שבת דף ס״ג) שנגנז ולא נשתייר כי אם מעט ומשתכח בגזאי [דצימצמאי] מלכתא עכ״ל. ולפי זה גם כן אינו עוד הירדי שהרי נמצא הרבה:\",16,0],[8,360,2,5,\"כיצד מפטמין את הקטרת מביא תשעה קבין בורית כרשינה ושף בה את הצפורן. הגירסא הנכונה בדברי רבינו ואחר כך שורה את הצפורן באחד ועשרים קב יין קפריסין או יין ישן לבן והוא יין חזק ביותר והוא בברייתא הנזכרת לעיל יין קפריסין סאין תלתא וקבין תלתא אם לא מצא יין קפריסין מביא חמר חיור עתיק.\",1,0],[8,360,2,5,\"ומה שכתב ואחר כך שוחק כל אחד מן הסממנים בפני עצמו הדק אפשר שטעמו משום דכתיב ביה ממולח שתרגומו מערב ומשמע לרבינו דהיינו שישחוק כל אחד לבדו ואחר כך יערבם דאחר שחיקה מתערבים יותר יפה מקודם שחיקה ויותר נראה שטעמו מדכתיב בד בבד יהיה וכמו שכתבתי בראש פרק ראשון.\",2,0],[8,360,2,5,\"ומה שכתב וכשהוא שוחק אומר הדק היטב וכו'. בפירקא קמא דכריתות ופירש\\\"י הממונה אומר כן לשוחק ומפרש טעמא בגמרא שהקול יפה לבשמים.\",3,0],[8,360,2,5,\"ומה שכתב ומערב הכל. כבר כתבתי דהיינו מדכתיב ממולח:\",4,0],[8,360,2,6,\"ומ\\\"ש וכל מעשיה בקדש בתוך העזרה. בפ\\\"ק דכריתות (דף ז') קדש היא קדש תהיה לכם כל מעשיה לא יהיו אלא בקודש.\",1,0],[8,360,2,6,\"ומ\\\"ש ומשל הקדש. בפ\\\"ד דשקלים (משנה ה') ובפרק קמא דשבועות (דף י':):\",2,0],[8,360,2,6,\"ומ\\\"ש והמפטם את הקטרת מן החולין או בכלי של חולין פסולה. נראה דמשמע ליה הכי מדתניא כל מעשיה לא יהיו אלא קדש וטעמא מדכתיב תרי זימני קדש ובירושלמי פרק ד' דשקלים (הלכה ז') פטמה בחולין רבי יוסי ברבי חנינא אמר פסולה ר' יהושע בן לוי אמר כשרה מאי טעמא דרבי יוסי ברבי חנינא קדש היא שתהא הויתה בקדש מ\\\"ט דריב\\\"ל קדש היא שתהא באה מתרומת הלשכה אתיא דר\\\"י בר' חנינא כשמואל ודריב\\\"ל כר\\\"י ולפי זה היה ראוי להכשיר כריב\\\"ל ור\\\"י מ\\\"מ מאחר דגמרא דידן סתם וכתב כל מעשיה לא יהיו אלא בקדש דמשמע דעיכובא הוא פסק כן:\",3,0],[8,360,2,7,\"פעמים בשנה היו מחזירין אותו למכתשת וכו' עד כדי שלא יפוג ריחה. בפ' קמא דכריתות (דף ו':) והוה משמע ליה דתרי מילי נינהו חדא שפעמים בשנה היו שוחקים אותה שנית שבימות החמה היו מפזרין אותה אפילו שלא בשעת שחיקה ובימות הגשמים צוברין אותה אף שלא בשעת שחיקה אלא שמלשון הברייתא נראה שכשמחזירה למכתשת קאמר שבימות החמה מחזירה פזורה ובימות הגשמים מחזירה צבורה:\",1,0],[8,360,2,8,\"נתן לתוכה דבש כל שהוא פסלה חיסר וכו'. בברייתא הנזכרת ובפ' הוציאו לו (דף כ\\\"ג) מנין שנותן בה מעלה עשן שנאמר וכסה ענן הקטרת את הכפרת הא לא נתן בה מעלה עשן או שחיסר אחת מכל סמניה חייב מיתה ופירש\\\"י או שחיסר דכתיב הקטרת שלימה ולא חסרה ומקשה התם ותיפוק ליה דקא מעייל ביאה ריקנית א\\\"ר ששת הב\\\"ע כגון ששגג בביאה והזיד בהקטרה רב אשי אמר אפילו תימא הזיד בזו ובזו כגון דעייל שתי הקטרות אחת שלימה ואחת חסרה אביאה לא מיחייב דקא עייל ליה שלימה אהקטרה מיחייב דקא מקטר קטרת חסרה. וכתב זה רבינו בסוף הל' עבודת יה\\\"כ:\",1,0],[8,360,2,8,\"פטמה מעט מעט וכו'. בפ\\\"ק דכריתות איפליגו תנאי ופסק כחכמים ומימרא הכא ומימרא דרבא התם אתיא כוותייהו:\",2,0],[8,360,2,9,\"העושה קטורת מי\\\"א סממנים אלו וכו'. הכי משמע מדתנן בפ\\\"ק דכריתות המפטם את הקטרת וקרא נמי כתיב איש אשר יעשה כמוה להריח בה ונכרת מעמיו הכי משמע:\",1,0],[8,360,2,9,\"ומה שכתב ובשוגג מביא חטאת קבועה. בריש כריתות.\",2,0],[8,360,2,9,\"ומ\\\"ש אע\\\"פ שלא עשה המשקל כולו אלא חציו או שלישו וכו'. בפ\\\"ק דכריתות אהא דתניא וחכמים אומרים בכל יום היה מתקן במתכונתה ומכניס מסייע ליה לרבא דאמר קטרת שפטמה לחצאין חייב דכתיב והקטרת אשר תעשה כל שתעשה והא אפשר דעבדה פרס בשחרית ופרס בין הערבים ופירש\\\"י במתכונתה לישנא דקרא אם היה רוצה לפטם הקטרת דבר יום ביומו עושה הילכך יחיד שלא פיטם אלא מנה חייב וחצאין דרבא לאו דוקא אלא כל דראוי להקטיר:\",3,0],[8,360,2,10,\"עשאה להתלמד בה או למוסרה לציבור פטור. ברייתא שם ויליף לה מקרא:\",1,0],[8,360,2,10,\"הריח בה ולא עשאה וכו'. ברייתא שם המריח בה פטור אלא שמעל ופירש\\\"י המריח בה בקטרת של צבור:\",2,0],[8,360,2,11,\"מזבח הזהב שבהיכל וכו'. מבואר במקראות ס\\\"פ תצוה ועשית מזבח מקטר קטרת וגו' לא תעלו עליו קטורת זרה ועולה ומנחה ונסך לא תסכו עליו וקטרת שאינה כזו או שהתנדב אותה יחיד או רבים כלומר ולא מסרה לצבור הרי היא בכלל קטרת זרה:\",1,0],[8,360,2,12,\"בעת שמוליכין את הארון ממקום למקום וכו'. בפרק אלו נאמרים (סוטה דף ל״ה):\",1,0],[8,360,2,13,\"כשנושאים אותו על הכתף כו': ומ\\\"ש ונזהרים שלא ישמטו הבדים מן הטבעות וכו'. בפרק בא לו (יומא דף ע\\\"ב):\",1,0],[8,360,3,1,\"זרע לוי כולו מובדל לעבודת המקדש וכו'. פשוט הוא.\",1,0],[8,360,3,1,\"ומ\\\"ש ומ\\\"ע להיות הלוים פנויים ומוכנים לעבודת המקדש בין רצו בין שלא רצו בסיפרי פרשת קרח שומע אני אם רצה יעבוד אם לא רצה לא יעבוד תלמוד לומר ועבד הלוי בעל כרחו:\",2,0],[8,360,3,1,\"ומה שכתב ובן לוי שקיבל עליו כל מצות לויה חוץ מדבר אחד אין מקבלין אותו עד שיקבל את כולן. בפרק עד כמה (בכורות דף ל':) ופירש״י דברי לוים לשורר ולשרת ולהיות שוער:\",3,0],[8,360,3,2,\"עבודה שלהם היא שיהיו שומרים המקדש. בראש מסכת מדות (פ\\\"א מ\\\"א).\",1,0],[8,360,3,2,\"ומ\\\"ש ויהיו מהם שוערים וכו' ויהיו מהם משוררים וכו' עד הוי אומר זו שירה. בפ\\\"ב דערכין (דף י\\\"א ע\\\"א ב'):\",2,0],[8,360,3,2,\"ומתי אומר שירה על כל עולות הצבור החובה וכו'. בפ\\\"ב דערכין (דף י\\\"א:) בעי רבי אבין עולת נדבת צבור טעונה שירה או אינה טעונה שירה ואסיקנא ת\\\"ש דתני רב מרי בריה דרב כהנא לעולותיכם ולזבחי שלמיכם מה עולה קדש קדשים אף שלמים קדש קדשים ומה שלמים קבוע להם זמן אף עולה קבוע לה זמן ופירש\\\"י מה עולה האמורה כאן קדש קדשים דאין לך עולה קדשים קלים אף שלמים האמורים כאן שטעונין שיר בשלמים קדשי קדשים משתעי ואין לך שלמים קדשי קדשים אלא כבשי עצרת דשלמי צבור הן וכתיב בה קדש יהיו לה' לכהן ומה שלמים האמורים כאן לגבי שיר קבוע להם זמן דהא אוקימנא בכבשי עצרת אף עולה האמורה כאן שקבוע לה זמן לאפוקי נדבת צבור דאין קבוע לה זמן.\",3,0],[8,360,3,2,\"ומ\\\"ש בעת ניסוך היין. שם מימרא דרב שמואל בר נחמני (שם דף י\\\"א. וי\\\"ב. וברכות ל\\\"ה):\",4,0],[8,360,3,2,\"ומ\\\"ש וכן הנסכים הבאים בפני עצמן אין אומרים עליהם שירה. שם (דף י\\\"ב) בעיא דלא איפשיטא ופסקה לקולא:\",5,0],[8,360,3,3,\"לוי האונן מותר לעבוד ולשורר. בסיפרי פרשת שמיני פ\\\"ב:\",1,0],[8,360,3,3,\"ואין פוחתין מי\\\"ב לוים עומדים על הדוכן וכו' ומוסיפין עד לעולם. משנה בפ\\\"ב דערכין (דף י\\\"ג).\",2,0],[8,360,3,3,\"ומ\\\"ש ואין אומרים שירה אלא בפה בלא כלי וכו' ואחרים היו עומדים שם מנגנים בכלי שיר מהם לוים ומהם ישראלים מיוחסין וכו'. שם במשנה (דף י') גבי מכים בחליל ועבדי הכהנים היו דברי ר' מאיר רבי יוסי אומר משפחת בית הפגריא ובית צפריא מעימאום היו משיאים לכהונה רבי חנינא בן אנטיגנוס אומר לוים היו ופירש\\\"י ועבדי הכהנים היו אותם המכים בחליל. משיאין לכהונה כהנים היו נושאים בנותיהם שישראלים מיוחסים היו ובגמרא (דף י\\\"א) לימא בהא קא מיפלגי דמאן דאמר עבדים קסבר עיקר שירה בפה וכלי לבסומי קלא הוא דעביד ומאן דאמר לוים היו קסבר עיקר שירה בכלי ותסברא ר' יוסי מאי קסבר אי קסבר עיקר שירה בפה עבדים סגיא אי קסבר עיקר שירה בכלי לוים בעינן לעולם קסבר עיקר שירה בפה והכא במעלין מדוכן ליוחסין ולמעשרות קא מיפלגי ופירש\\\"י ר' יוסי דאמר ישראלים מיוחסים היו מאי קסבר אלא דכ\\\"ע עיקר שירה בפה וידוע דהלכה כרבי יוסי לגבי רבי מאיר והוא הדין לגבי רבי חנינא בן אנטיגנוס דהא הוא מארי גמרא טפי מיניה.\",3,0],[8,360,3,3,\"ומ\\\"ש ואין אלו המשוררים על פי הכלים עולין למנין הי\\\"ב. שם (דף י\\\"ג:) במשנה אין פוחתין מי\\\"ב לוים עומדים על הדוכן ומוסיפין עד לעולם ובתר הכי תנן ר' אליעזר בן יעקב אומר אין עולים למנין ופירש רבינו שם כבר אמרנו שעיקר השירה בפה ואמר רבי אליעזר בן יעקב שהאומרים השיר על הכלים ואין אומרים בפה אינם עולים ממנין שנים עשר לוים:\",4,0],[8,360,3,4,\"ובמה הם מנגנים וכו'. אלו הם כלי הניגון המוזכרים שם במשנה:\",1,0],[8,360,3,4,\"ומ\\\"ש ואין פוחתין משני חלילים וכו' עד ולא מוסיפין על י\\\"ב. שם במשנה (דף י\\\"ד)\",2,0],[8,360,3,4,\"ומ\\\"ש ואין פוחתין משתי חצוצרות וכו'. שם במשנה (דף י\\\"ג) אין פוחתין משתי חצוצרות וכו' ומוסיפין עד עולם ובגמרא ועד כמה אמר רב הונא וכו' עד מאה ועשרים ומייתי לה מקרא מחצצרים בחצוצרות.\",3,0],[8,360,3,4,\"ומ\\\"ש ואין פוחתין מתשעה כנורות וכו'. שם אין פוחתין מתשעה כנורות ומוסיפין עד לעולם והצלצל לבד מנא הני מילי א\\\"ר אסי דאמר קרא ואסף במצלתים להשמיע מצלתים תרי הוו כיון דחדא עבידתא עבדי וחד גברא עביד בהו קרי להו חד ופירש\\\"י עבידתא חד עבדי דאין אחד מועיל בלא חבירו שהן שתי חתיכות רחבות של מתכת ומכין זו על זו:\",4,0],[8,360,3,5,\"בימי המועדות כולם וכו': החצוצרה היתה נעשית מן העשת של כסף וכו' עד פסולה. ברייתא בפרק הקומץ רבה (מנחות דף כ״ח) ויליף לה התם מקראי:\",1,0],[8,360,3,5,\"והחלילין שהיו מנגנים בהם היה אבוב שלהם של קנה וכו' עד ובשמנת ימי החג. משנה בפרק שני דערכין (דף י') פירש\\\"י אבוב היינו חליל. ולא היה מחלק מסיים אלא באבוב יחידי כשהיה מגיע לסיום הנעימה היה אחד מהחלילין מאריך לאחר שתיקת האחר שזו היא חילוק יפה יותר משיסיימו שניהם כאחד. חילוק היינו סיום שמחלק בין נעימה לנעימה ולא היו מסיימים כולם בבת אחת אלא אחד מסיים לבסוף וזה הוא נוי גדול:\",2,0],[8,360,3,6,\"בשנים עשר יום בשנה וכו'. משנה בפרק שני דערכין.\",1,0],[8,360,3,6,\"ומ״ש וחליל זה דוחה שבת וכו'. בר״פ החליל (סוכה דף נ״א) א״ר ירמיה מחלוקת בשיר של שואבה וכו' אבל בשיר של קרבן דברי הכל עבודה היא ודוחה את השבת ורב יוסף דפליג עליה איתותב:\",2,0],[8,360,3,7,\"אין בן לוי נכנס לעזרה לעבודתו וכו'. בספ\\\"ק דחולין (דף כ\\\"ד).\",1,0],[8,360,3,7,\"ומה שכתב ואינו נכנס לעבודה עד שיגדיל ויהיה איש וכו'. משנה בפ\\\"ב דערכין (דף י\\\"ג:) אין הקטן נכנס לעזרה ולעבודה אלא בשעה שהלוים עומדים בשיר ולא היו אומרים בנבל וכנור אלא בפה כדי ליתן תבל בנעימה ופירש\\\"י אין לוי קטן נכנס לשום עבודה כגון לכבד את העזרה ולהגיף את הדלתות:\",2,0],[8,360,3,7,\"ואיכא למידק דמשמע מהכא דמשיגדיל ויהיה איש כשר לעבודה וזה סותר מ\\\"ש למעלה שאינו נכנס לעבודה עד שיהא בן שלשים שנה. ויש לומר דהתם לשיר שהיא חכמה גדולה וצריכה לימוד המוסיק\\\"א והכא לשאר עבודות שאינם צריכות לימוד כגון הגפת דלתות וכיוצא בהן. ועי\\\"ל דהתם לשתהיה עבודה מיוחדת לו תמיד והכא מיירי לעבוד אי זה פעם במקרה דיקא נמי דלעיל כתב לעבודתו והכא כתב לעבודה. ויש מי שתירץ דהתם בזמן שהיו נושאים בכתף שהיה צריך למשא ואין לדחות דמה לימוד צריך למשא דאמרינן בספ\\\"ק דחולין גבי שצריך ה' שנים ללימוד שאני הלכות עבודה דתקיפין ופירש\\\"י להוריד המשא ולפרקו ולנטותו ולהעמיד קרסיו וקרשיו והשיר לקרבן בפה ובכלי:\",3,0],[8,360,3,8,\"זה שנאמר בתורה בלוים וכו' אבל לדורות אין הלוי נפסל בשנים ולא במומין אלא בקול. בספ\\\"ק דחולין (שם דף כ\\\"ד):\",1,0],[8,360,3,9,\"שמואל הרואה ודוד המלך חלקו הלוים לכ\\\"ד משמרות וכו'. בפרק בתרא דתעניות (דף כ\\\"ז).\",1,0],[8,360,3,9,\"ומ\\\"ש וכל אנשי משמר מחלק אותם ראש המשמר לבתי אבות. איכא למידק דמשמע מדבריו אלה שראש המשמר מחלק אנשי המשמר לבתי אבות וכל בית אב עובד יום אחד מיוחד בשבוע א\\\"כ מה זה שכתב וראשי האבות מחלקים אלו העובדים ביום שלהם והלא כבר חילקם ראש המשמר. וי\\\"ל שראש המשמר מחלק אנשי משמר שלו לשבעה בתי אבות ואע\\\"פ שיהיו במשמר אנשים רבים אינו מחלקם אלא לשבעה חלקים כל חלק נקרא בית אב אבל אינו מסיים אי זה בית אב יעבוד ביום א' ואי זה ביום שני וזה עושים ראשי בתי אבות שהם מסיימים ואומרים בית אב פלוני יעבוד ביום א' ובית אב פלוני ביום שני וכן כולם. כך היה נראה לפרש דברי רבינו פה אבל ממ\\\"ש בפרק שאחר זה כל ראש משמר היה מחלק משמרו לבתי אבות עד שיהיה כל בית אב ואנשיו עובד ביום אחד מימות השבת והאחר ביום של אחריו והאחר ביום שלאחריו ולכל בית אב ואב ראש אחד ממונה עליו נראה שראש משמר היה מסיים היום שיעבוד בו בית אב זה וכן לכל בית אב יומו ולפי זה מ\\\"ש\",2,0],[8,360,3,9,\"פה וראשי בית אב מחלקים אלו העובדים ביום שלהם היינו שבית אב המיוחד לעבוד ביום א' ראש בית אב שלו מסיים לעבודתו פלוני ופלוני יהיו שוערים ופלוני ופלוני יהיו משוררים ופלוני יהיה שוער בשער פלוני ופלוני בשער פלוני ופלוני ישורר בכלי שיר פלוני ופלוני ישורר בכלי שיר פלוני וזהו שכתב וראשי האבות מחלקים אלו העובדים ביום שלהם איש איש על עבודתו וזהו בראשי בתי הלוים אבל ראשי אבות הכהנים לא היו מיחדים שום עבודה לשום אחד כי אם ע\\\"פ הפייס ותמהני למה הוצרכו לפייס היה לראשי אבות לחלק העובדים ביום שלהם איש איש על עבודתו כמו שהיו עושים הלוים וצריך עיון:\",3,0],[8,360,3,9,\"וכל הלוים מוזהרים על עבודת המזבח וכו'. בפ\\\"ב דערכין (דף י\\\"א) ולא ימותו גם הם גם אתם אתם בשלהם והם בשלכם במיתה הם בשלהם אינם במיתה אלא באזהרה אמר אביי נקטינן משורר ששיער בשל חבירו במיתה שנאמר והחונים לפני המשכן קדמה לפני אהל מועד מזרחה וגו' והזר הקרב יומת מאי זר אילימא זר ממש הכתיב חדא זימנא אלא זר דאותה עבודה מיתיבי משורר ששיער ושוער ששורר אינם במיתה אלא באזהרה תנאי היא דתניא מעשה ברבי יהושע בן חנניה שהלך לסייע בהגפת דלתות אצל רבי יוחנן בן גודגדא א\\\"ל בני חזור לאחוריך שאתה מן המשוררי' ולא מן השוערים מאי לאו בהא קא מיפלגי דמר סבר מיתה היא וגזרו בה רבנן ומר סבר אזהרה היא ולא גזרו בה (רבנן) דכ\\\"ע אזהרה היא מ\\\"ס מסייע גזרו ביה רבנן ומ\\\"ס לא גזרו ביה רבנן ופירש\\\"י אתם בשלהם הכהנים שנכנסו בעבודת לוים וכו' כגון לוי משורר שהגיף דלתות ולוי משוער שאמר שיר שהרי הלוים היו חלוקין זה למשוער וזה למשורר. אלא באזהרה לא איתפרש לן. אביי לית ליה הא מתניתא דקתני לעיל הם בשלהם אינו במיתה דהא משכחת תנא אחרינא דקאי כוותיה. זר ממש כגון ישראל. הא כתיב חדא זימנא בההיא פרשתא גופה וקאי נמי אעבודת הלוים. ר' יוחנן בן גודגדא סבר משורר ששיער במיתה כשהוא מגיף לבדו וגזרו רבנן במסייע דלא ליתי למעבד לחודיה ורבי יהושע סבר אפילו כי עביד לחודיה אינו אלא באזהרה ולא גזרו רבנן במסייע. וסובר רבינו שמאחר דאביי דבתרא הוא מפרש פלוגתא דרבי יהושע בן חנניה ור' יוחנן בן גודגדא באי הויא במיתה או באזהרה ופסקה למילתיה כמ\\\"ד במיתה נקיטינן כוותיה ואע\\\"ג דבגמרא דחי דכ\\\"ע אזהרה היא וכו' לא שבקינן מאי דפשיטא לאביי משום מאי דדחי הגמרא ועוד דלישנא דסיפרי כאוקמתא דאביי משמע כמו שאכתוב בסמוך. וספר מצות גדול כתב (לאוין סימן רצ\\\"ו) אמר אביי נקיטינן משורר ומשוער בשל חבירו במיתה וכו' מיתיבי משורר ששיער ושוער ששורר אינו במיתה אלא באזהרה ומתרץ תנאי היא ודוחה שם ודילמא דכ\\\"ע באזהרה ודומה שנדחו שם דברי אביי מאחר שאינו מתרץ כלום עכ\\\"ל וכבר כתבתי טעם רבינו שפסק כאביי. ועדיין קשה היאך פסק רבינו דלוי שסייע לוי במלאכה שאינה מלאכתו חייב מיתה דהא אביי נמי לא חייב מיתה למסייע שהרי אמר מר סבר מיתה הוא וגזרו בה רבנן וצ\\\"ל שבגירסת רבינו לא היה מסיים וגזרו בה רבנן אלא הכי גריס מ\\\"ס מיתה היא ומ\\\"ס אזהרה היא וקאי גם למסייע שכל ששינה עבודתו אפילו כל שהוא חייב מיתה ומה לי שיהיה מסייע סוף סוף הרי נתעסק בעבודה שאינה שלו ולשון סיפרי שאכתוב בסמוך דקתני שאמר לו רבי יוחנן בן גודגדא לרבי יהושע שאתה מתחייב בנפשך הכי משמע שהיה חייב אע\\\"פ שלא היה אלא מסייע. ומ\\\"מ יש לתמוה על רבינו שפסק דכהן שעבד עבודת לוי אינו במיתה דהא תניא ולא ימותו גם הם גם אתם אתם בשלהם והם בשלכם במיתה. וספר מצות גדול כתב על דברי רבינו ועוד כתב שכהן שעובד עבודת לוי אינו במיתה אלא בלא תעשה כברייתא אחרת אשר שם עכ\\\"ל ואני לא מצאתי בפרק הנזכר שום ברייתא ששנוי בה כן. ומצאתי בספר המצות לרבינו וז\\\"ל לשון סיפרי אך אל כלי הקדש ואל המזבח לא יקרבו אזהרה שמענו עונש מניין ת\\\"ל ולא ימותו אין לי אלא לוים שנענשים ומוזהרים על עבודת כהנים כהנים על עבודת לוים מניין ת\\\"ל גם הם מעבודה לחברתה מניין ת\\\"ל גם אתם ביקש רבי יהושע לסייע את רבי יוחנן ב\\\"ג בהנעלת דלתות אמר לו חזור בך שאתה מתחייב בנפשך שאתה מן המשוררים ואני מן השוערים הנה התבאר כי לוי שיעבוד במקדש זולת עבודתו חייב מיתה בידי שמים וכן הכהנים לא יתעסקו בעבודת הלוים אבל אם עבדו אינם במיתה אלא במלקות ובמכילתא אל כלי הקדש יכול אם נגעו יהיו חייבים תלמוד לומר על עבודתו משום עבודה הם חייבים ולא משום נגיעה אין לי אלא הלוים על ידי כהנים כהנים ע\\\"י לוים מניין ת\\\"ל גם אתם ושם אמרו הכהנים ע\\\"י הלוים במלקות והלוים ע\\\"י הכהנים במיתה עכ\\\"ל. ואיני יודע למה דחה ברייתא השנוייה בגמרא וסמך על ברייתא השנויה במכילתא. ועוד קשה לי על הראיה שהביא מסיפרי דאדרבה שם משמע דכשם שהלוים על עבודת כהנים במיתה כך כהנים על עבודת לוים במיתה דהא מייתי לה מגם הם והרי גם אתם דריש ליה ללוי בעבודת לוי חבירו במיתה ומשמע דגם הם נמי מידריש בגוונא דדריש גם אתם ומהי תיתי לן דגם הם לא קאי אעונש נמי דמסתמא משמע דגם אעונש קאי וזה דעת הראב\\\"ד שכתב א\\\"א והלא כבר נאמר ולא ימותו גם הם גם אתם ובסיפרי נמי הכי דריש ליה לעונש ואזהרה עכ\\\"ל. וי\\\"ל שטעם רבינו משום דבסיפרי מסיים בה רבי אומר אינו צריך שהרי כבר נאמר אל תכריתו וגו' וזאת עשו להם אין לי אלא לוים שענושים ומוזהרים על עבודת כהנים כהנים על עבודת לוים מניין ת\\\"ל ובנסוע המשכן יורידו אותו הלוים מעבודה לחבירתה מניין ת\\\"ל (עמהם) והחונים לפני המשכן קדמה וכו' מה ת\\\"ל גם הם גם אתם לפי שבא קרח וערער כנגד אהרן וכו' ומדמייתי לכהנים על עבודת הלוים מדכתיב יורידו אותו הלוים כלומר ולא הכהנים והרי אין שם עונש אלא ל\\\"ת הבא מכלל עשה ומדאמר רבי אינו צריך משמע דלא פליגי לענין דינא אלא במשמעות דורשין וכיון דלרבי כהנים בעבודת לוים אין בהם עונש הוא הדין לת\\\"ק כי מרבי לכהנים בעבודת לוים לא מרבי להו אלא לאזהרה ולא לעונש. ויש לדקדק כי מייתי מעבודה לחברתה מניין מוהחונים לפני המשכן קדמה ומשמע דלוי בעבודת לוי אחר קאמר ומייתי מדמסיים ביה קרא והזר הקרב יומת וקשה שהרי שם משה ואהרן ובניו שומרים שהם כהנים וי\\\"ל דמשה לוי הוא. ודע שגירסת סיפרי אינה מיושבת בעיני דמייתי לכהנים על עבודת לוים מדכתיב גם הם והלא הם אלוים קאי ותו דמייתי (כהנים על עבודתם) מעבודת לוי לעבודת לוי מדכתיב גם אתם והלא אתם אכהנים קאי ולכן נראה שהגירסא הנכונה כהנים על עבודת לוים מניין ת\\\"ל גם אתם מעבודה לחבירתה מנין כלומר מעבודת לוי אחד לעבודת לוי אחר מניין ת\\\"ל גם הם ולפי סברת רבינו ה\\\"פ לא יקרבו ולא ימותו גם הם דלוי שעבד עבודת כהן או עבודת לוי חבירו במיתה ומאי דכתיב בתר הכי גם אתם דהיינו כהן בעבודת לוי לא קאי אלא [אלא] יקרבו ולא אולא ימותו:\",4,0],[8,360,3,9,\"ומה שכתב אבל ליגע מותרים. בסיפרי זוטא פרשת קרח דריש הכי מקרא וכבר כתבתי בסמוך שכתב רבינו דאיתיה נמי במכילתא:\",5,0],[8,360,4,1,\"הכהנים הובדלו מכלל הלוים וכו'. כך מנאה במנין המצות:\",1,0],[8,360,4,2,\"ומ״ש וצריך כל אדם מישראל וכו'. בס״פ הניזקין (גיטין דף נ״ט:) ועיין שם בפירש״י ותוספות:\",1,0],[8,360,4,3,\"משה רבינו חלק הכהנים לשמנה משמרות וכו' ובימי שמואל. בפ' בתרא דתעניות (דף כ\\\"ז):\",1,0],[8,360,4,5,\"ומצות עשה להיות כל המשמרות שוים ברגלים וכו' עד וקבעום כל משמר ומשמר בשבתו. בסוף פרק החליל (סוכה דף נ״ו):\",1,0],[8,360,4,6,\"ומ\\\"ש וכן עבודת לחם הפנים במשמר שזמנו קבוע. שם בתוספתא לחם הפנים עבודתו במשמר הקבוע ואכילתו בכל המשמרות פי' עבודתו סילוקו וסידורו והקטרת הבזיכים ומפורש הטעם בתוספות משום דבגמרא מרבינן ליה חלק כחלק יאכלו משמע לאכילה רבייה רחמנא ולא לעבודה:\",1,0],[8,360,4,6,\"ומה שכתב אבל עבודת שתי הלחם בכל המשמרות. נראה דהיינו מפני שהוא בכלל מה שאמרו בס\\\"פ החליל שמה שאמור ברגלים היו כל המשמרות שוות.\",2,0],[8,360,4,6,\"ומ\\\"ש ומניין שאינו מדבר אלא ברגלים שנאמר מאחד שעריך מכל ישראל וכו'. שם.\",3,0],[8,360,4,6,\"ומ\\\"ש ומניין שאינו מדבר אלא בכהנים וכו'. בסיפרי פרשת שופטים:\",4,0],[8,360,4,7,\"ומ״ש וכן כהן שהיה לו קרבן הרי זה בא למקדש ומקריבו בכל יום שירצה וכו' והעור של קרבנו ואכילתו שלו. כך היא הגירסא הנכונה בדברי רבינו והיא גירסת סמ״ג והדין בס״פ הגוזל עצים (בבא קמא דף ק״ט:) תנו רבנן מניין לכהן שבא ומקריב קרבנותיו בכל עת ובכל שעה שירצה ת״ל ובא בכל אות נפשו ושרת ומניין שעבודתה ועורה שלו ת״ל ואיש את קדשיו לו יהיו ופירש״י עבודתה שכר עבודתה דהיינו בשרה. וכתב הראב״ד ועור הקרבן ועבודתו לאותו הכהן בלבד שנתן לו א״א לא כי אלא אכילתו ועורו של בעליו עכ״ל. ופשטא דגמרא כדברי הראב״ד דקאמר גבי היה זקן או חולה נותנה לכל כהן שירצה אי דמצי עביד עבודה עבודתה ועורה נמי תיהוי דידיה משמע תיהוי דידיה דבעל הקרבן קאמר הרי דכי משוי שליח עבודתה ועורה של בעל הקרבן אבל רבינו מפרש דכי קאמר תיהוי דידיה לאו אבעליו קאי אלא אכל כהן שירצה דקתני קאי דהיינו שליח.\",1,0],[8,360,4,7,\"ומ״ש ואפילו חטאתו מקריב ומכפר ע״י עצמו. בפרק אלו מנחות (מנחות דף ע״ד) יליף לה מקרא:\",2,0],[8,360,4,8,\"ומ\\\"ש היה הכהן בעל הקרבן בעל מום וכו' שם בברייתא הנזכרת מסיים בה אם היה בעל מום נותנה לכהן שבאותה משמר ועבודתה ועורה שלו ומדברי רש\\\"י נראה שהוא גורס נותנה לאנשי משמר וכן נראה מדברי רבינו ופירש\\\"י אם היה בעל מום ראוי לאכול ואינו ראוי להקריב אין ראוי לעשות שליח להקריבה כל מי שירצה אלא נותנה לבני המשמר והואיל והוא ראוי לאכילה קרינן ביה ואיש את קדשיו לפיכך עבודתה ועורה שלו לישנא אחרינא גרסינן עבודתה ועורה לאנשי המשמר כיון דהם הקריבוה עכ\\\"ל. ורבינו גורס כלשון הזה.\",1,0],[8,360,4,8,\"ומ\\\"ש היה זקן או חולה שיכול לעבוד ע\\\"י הדחק נותן קרבנו לכל כהן שירצה וכו'. שם אם היה זקן או חולה נותנה לכל כהן שירצה ועבודתה ועורה לאנשי משמר האי זקן או חולה היכי דמי אי דמצי עביד עבודה עבודתה ועורה נמי תיהוי דידיה ואי דלא מצי עביד עבודה שליח היכי משוי אמר רב פפא שיכול לעשות ע\\\"י הדחק עבודה [דכי עביד ע\\\"י הדחק עבודה] היא משוי שליח אכילה דכי אכיל ע\\\"י הדחק אכילה גסה היא ואכילה גסה לאו כלום היא מש\\\"ה עבודתה ועורה לאנשי משמר:\",2,0],[8,360,4,9,\"היה טמא בקרבנות הצבור וכו'. שם א\\\"ר ששת אם היה כהן טמא בקרבן צבור נותנה לכל מי שירצה ועבודתה ועורה לאנשי משמר היכי דמי אי דאיכא טהורים טמאים מי מצו עבדי ואי דליכא טהורים עבודתה ועורה לאנשי משמר הא טמאים נינהו ולא מצו אכלי אמר רבא אימא לבעלי מומין טהורים שבאותו משמר. ופירש\\\"י טמאים מי מצו עבדי וכיון דלא מצו עבדי שליח היכי משוו. ודברי רבינו תמוהים שכתב נותנו לבעלי מומין טהורים שבאותו משמר דמשמע שנותנו לבעלי מומין טהורים שיקריבוהו והא בעלי מומין לאו בני הקרבה נינהו ועוד שכתב שעורו ועבודתו לאנשי משמר הטמאים והרי בגמרא הקשו הא טמאים נינהו ולא מצו אכלי ושני רבא אימא לבעלי מומין טהורין שבאותו משמר והיאך כתב רבינו בהפך ונראה דמש\\\"ה כתב הראב\\\"ד א\\\"א כל זה שבוש אלא נותנו לכל כהן שירצה לעבדה ועורה ועבודתה לבעלי מומין טהורים שבאותו משמר. וגם על דבריו אני תמיה למה כתב שעורה לבעלי מומין ולמה לא יהיה לאנשי משמר:\",1,0],[8,360,4,9,\"וליישב דברי רבינו נראה שיש למחוק מדבריו תיבת ועבודתו.\",2,0],[8,360,4,9,\"ומ\\\"ש נותנו לבעלי מומין טהורים שבאותו משמר לא לענין הקרבת הקרבן קאמר דפשיטא שאחד מהכהנים הטמאים מקריבו ולא בעלי מומין אלא לענין בשר הקרבן קאמר שנותנו לבעלי מומין טהורים שבאותו משמר שיאכלוהו ועורו לאנשי משמר הטמאים דכי אמר רבא אימא לבעלי מומין טהורים שבאותו משמר לא קאי אלא לעבודתה דהיינו אכילת בשר הקרבן שא\\\"א לטמאים לאכלו אבל עורה לטמאים שבאותו משמר והשתא שפיר קאמר רב ששת עבודתה ועורה לאנשי משמר דהיינו לומר דעבודתה דהיינו אכילת בשרה לבע\\\"מ טהורים שבאותו משמר ועורה לאנשי משמר הטמאים ועי\\\"ל שאין צריך למחוק מדברי רבינו שום תיבה אלא להקדים תיבה לחבירתה דה\\\"ג בדברי רבינו נותנו לבעלי מומין טהורין לעבודתו ועורו לאנשי משמר הטמאים וכמו שפירשתי:\",3,0],[8,360,4,9,\"ודע שהתוס' כתבו תימה עורה אמאי הויא לבעלי מומין עכ\\\"ל. ובמה שפירשתי לדעת רבינו ניחא דלא הוי אלא לאנשי המשמר הטמאים ולא חש רבינו לכתוב דנותן הקרבן לעשותו לכל כהן שירצה כדקתני בברייתא משום דכיון דכולם טמאים הוי כאילו כולם טהורים וכבר קדם שהוא רשאי ליתן קרבנו להקריבו לכל כהן שירצה:\",4,0],[8,360,4,9,\"ואכתי קשיא דהתם כתב שעור הקרבן לאותו הכהן בלבד שנתן לו וכאן כתב שהוא לאנשי משמר וי\\\"ל דרבינו ה\\\"ק א\\\"א לאכלו לא הוא ולא שאר אנשי משמר התמימים מפני שכולם טמאים אבל עורו לאנשי משמר הטמאים שאם הוא הקריבו הרי הוא לו ואם נתנו לאחר להקריבו הרי הוא של המקריבו:\",5,0],[8,360,4,9,\"ואפשר היה לקיים גירסת הספרים ועורו ועבודתו וע\\\"פ מה שפירשתי ונפרש דנותנו לבעלי מומין היינו אכילת הבשר ועבודתה לטמאים היינו הקרבתה אלא שקשה שלפי זה עבודתו דנקט רבינו משונה מעבודתו שאמרו בגמרא:\",6,0],[8,360,4,10,\"היה הקרבן של כ\\\"ג והיה אונן וכו'. גם זה שם (ב\\\"ק דף ק\\\"י) אמר רב אשי אם היה כ\\\"ג אונן נותנה לכל כהן שירצה ועבודתה ועורה לאנשי משמר מאי קא משמע לן תנינא כ\\\"ג מקריב ואינו אוכל ואינו חולק לאכול לערב סד\\\"א כי חס רחמנא עליה דכ\\\"ג לקרובי הוא אבל לשוויי שליח לא מצי משוי קא משמע לן. ופירש\\\"י אם היה כ\\\"ג אונן ויש לו קרבן עצמו להקריב. נותנו לכל כהן שירצה כיון שכ\\\"ג מקריב אונן:\",1,0],[8,360,4,11,\"כל ראש משמר ומשמר מחלק משמרו לבתי אבות וכו'. [נתבאר פ\\\"ג ה\\\"ט]:\",1,0],[8,360,4,12,\"וממנים כ\\\"ג וכו'. נתבאר בפ\\\"א:\",1,0],[8,360,4,12,\"ומ\\\"ש ואם אין שם שמן המשחה וכו'. גם זה נתבאר שם:\",2,0],[8,360,4,13,\"כיצד מרבין אותו בבגדים לובש ח' בגדים ופושטן וכו' וכשם שרבוי בגדים ז' כך משיחה בשמן ז' יום אחר יום. פ\\\"ק דיומא עלה ה' תניא וכפר הכהן אשר ימשח אותו ואשר ימלא את ידו לכהן תחת אביו מה ת\\\"ל לפי שנאמר שבעת ימים ילבשם הכהן תחתיו מבניו אין לי אלא נתרבה ז' ונמשח ז'. נתרבה ז' ונמשח יום א' נתרבה יום א' ונמשח ז' מניין ת\\\"ל אשר ימשח אותו ואשר ימלא את ידו מ\\\"מ אשכחן ריבוי ז' לכתחלה משיחה ז' לכתחלה מנ\\\"ל אב\\\"א מדאצטריך קרא למעוטיה ואב\\\"א דאמר קרא [ובגדי הקדש אשר לאהרן וגו'] למשחה בהם ולמלא בם את ידם איתקש משיחה לריבוי מה ריבוי ז' אף משיחה ז' ובסיפרי תניא לפי שנא' שבעת ימים ילבשם הכהן תחתיו מבניו שיכול אין לי אלא שנמשח ז' ונתרבה יום אחד נמשח יום א' ונתרבה ז' נתרבה יום א' נמשח יום א' (ונתרבה ז' נתרבה יום א' נמשח יום א') ואפי' שעה מניין ת\\\"ל אשר יוצק על ראשו שמן המשחה אפילו שעה אחת ומילא את ידו ללבוש את הבגדים אפילו שעה אחת. כתב הראב\\\"ד ואם עבד קודם שיתרבה בבגדים כל ז' א\\\"א נראה מדבריו ימים שהיה בהם המשיחה וכו'. ואין בדבריו הכרע לדחות פירושו של רבינו, והר\\\"י קורקוס ז\\\"ל כתב שגם דעת רבינו כהראב\\\"ד וביאור מ\\\"ש ואם עבד היינו עבודה שצריך לה כ\\\"ג דהיינו עבודת יוה\\\"כ וזהו שסיים וכתב נעשה כ\\\"ג לכל דבר כלומר אפילו לעבודת יה\\\"כ:\",1,0],[8,360,4,14,\"אין בין כהן משוח בשמן המשחה וכו'. משנה פ\\\"ק דמגילה (דף ט':) ופרק בתרא דהוריות (דף י\\\"א:):\",1,0],[8,360,4,15,\"אין מעמידין כ\\\"ג אלא ב\\\"ד של ע\\\"א. תוספתא בפרק ג' דסנהדרין:\",1,0],[8,360,4,15,\"ואין מושחין אותו אלא ביום וכו'. בתורת כהנים פרשת צו אין כהן גדול נמשח אלא ביום דכתיב ביום המשח אותו.\",2,0],[8,360,4,15,\"ומ\\\"ש וכן אם נתרבה בבגדים בלבד אין מרבין אותו אלא ביום. אפשר דיליף לה מדאיתקיש משיחה ורבוי להדדי:\",3,0],[8,360,4,15,\"ואין ממנין שני כהנים גדולים כאחת. בתורת כהנים פרשת צו ומפיק לה מדכתיב אותו:\",4,0],[8,360,4,16,\"וממנין כהן אחד יהיה לכהן גדול כמו המשנה למלך וכו'. בסוף הוריות (דף י\\\"ג):\",1,0],[8,360,4,17,\"ומ\\\"ש ועוד ממנים קתיקולין להיות לסגן כמו הסגן לכ\\\"ג ואין פוחתין משנים. בירושלמי דשקלים פרק אלו הם הממונים (הלכה י\\\"ב) ומוכח לה מקרא:\",1,0],[8,360,4,17,\"ומ\\\"ש וממנין אמרכלין אין פחות מז'. במשנה בפ' הנזכר ובירושלמי שם מוכח מקרא דהיו ז' ובסוף הוריות מאי אמרכל אמר רב חסדא אמר כלא ופירש\\\"י אמר כלא שממונה על כולם ואין משיבין על דבריו.\",2,0],[8,360,4,17,\"ומ\\\"ש ומפתחות העזרה בידם רצה האחד לפתוח אינו יכול עד שיכנסו כל האמרכולין ויפתחו. בתוספתא פ\\\"ב דשקלים:\",3,0],[8,360,4,18,\"ומה שכתב וממנין גזברין מתחת ידי האמרכולין ואין פוחתין משלשה גזברים. משנה פרק אלו הם הממונים (משנה ב') ופירש\\\"י בסוף הוריות גזבר ממונה על האוצרות שבמקדש.\",1,0],[8,360,4,18,\"ומה שכתב והגזברים הם שגובים כל ההקדשות ופודים וכו':\",2,0],[8,360,4,19,\"כהן הגדול המשוח קודם למרובה בבגדים וכו' עד משאר הכהנים. בסוף הוריות (דף י\\\"ג) חוץ מקתיקול שאינו מוזכר שם ומ\\\"מ למדו רבינו ממ\\\"ש בסמוך דאיתא בירושלמי דשקלים ומשמע התם שהקתיקול מעולה מהאמרכל:\",1,0],[8,360,4,19,\"ומ\\\"ש נמצאו הכהנים תמיד שמנה מעלות זו למעלה מזו. נ\\\"ל שכתב תמיד לומר דבזמן דליכא שמן המשחה הוי המרובה בבגדים במקום כהן משוח:\",2,0],[8,360,4,19,\"ואיכא למידק דטפי מח' מעלות מנה כאן וי\\\"ל דעובר מחמת מום ומחמת קרי לא הוו בכלל המנין דהא לא הוו תמיד וקשה דאכתי ט' מעלות הוו. וי\\\"ל דכהן הדיוט לא הוי בכלל המנין שהוא הצד התחתון שבכולן ולא יקרא בשם מעלה. ועי\\\"ל דמשוח מלחמה אינו מכלל הח' מעלות מפני שאין המלחמה ענין לעבודה בבהמ\\\"ק:\",3,0],[8,360,4,20,\"כשימות המלך או כהן גדול וכו'. בסיפרי פרשת שופטים הוא ובניו שאם מת בנו עומד תחתיו מניין לכל פרנסי ישראל שבניהם עומדים תחתיהם ת\\\"ל בקרב ישראל מה שהוא בקרב ישראל בנו עומד תחתיו ובת\\\"כ תניא ובנים לא היו להם הא אם היו להם בנים הם היו קודמים אע\\\"פ שלא היו שקולים כאלעזר ואיתמר:\",1,0],[8,360,4,20,\"ומ\\\"ש והוא שיהיה ממלא מקומו בחכמה או ביראה אע\\\"פ שאינו כמותו בחכמה. בס\\\"פ הנושא (כתובות דף ק\\\"ג:) ותניא בת\\\"כ לכהן תחת אביו מלמד שהבן קודם לכל אדם יכול אע\\\"פ שאינו ממלא מקומו ת\\\"ל ואשר ימלא את ידו בזמן שממלא מקומו של אביו הוא קודם לכל אדם ואם לאו יבא אחר וישמש תחתיו:\",2,0],[8,360,4,21,\"משוח מלחמה אין בנו מתמנה תחתיו לעולם וכו'. בס״פ בא לו (יומא דף ע״ב-ע״ג) יכול יהא בנו של משוח מלחמה משמש תחתיו כדרך שבנו של כ״ג משמש תחתיו תלמוד לומר שבעת ימים ילבשם הכהן תחתיו מבניו אשר יבא אל אהל מועד מי שראוי לבא אל אהל מועד:\",1,0],[8,360,4,21,\"ומ\\\"ש וכשכהן משוח מלחמה משמש במקדש וכו'. שם כי אתא רב דימי אמר בגדים שכ\\\"ג משמש בהם משוח מלחמה משמש בהם ואותיבנא עליה מדתניא דברים שבין כ\\\"ג לכהן הדיוט פר כהן משוח וכו' ומשמש בח' כלים וכו' וכולן אין נוהגות במשוח מלחמה ואע\\\"ג דשני שינויא דחיקא הוא ובתר הכי אמרינן דאמוראי לא ס\\\"ל להא דרב דימי ואסיקנא כי אתא רבין אמר לאו משמש בהן איתמר אלא נשאל בהן איתמר ואע\\\"ג דתניא התם משוח מלחמה אינו משמש לא בארבעה ככהן ההדיוט ולא בח' ככ\\\"ג וקאמר עלה אביי אלא זר משוית ליה אלא ככ\\\"ג משום איבה ככהן הדיוט משום מעלין בקדש ולא מורידין היינו אליבא דרב דימי דסבר דראוי לשמש בח' כלים אי משמש בד' הוי הורדה אבל לדידן דסבירא לן דאינו ראוי לשמש בח' ליכא הורדה ובסוף הוריות מייתי הא דדברים שבין כהן גדול לכהן הדיוט פר כהן משוח וכו' ולא מייתי אידך ברייתא דמשוח מלחמה אינו משמש לא בארבעה ככהן הדיוט:\",2,0],[8,360,4,21,\"מעלין משררה לשררה וכו'. בכמה דוכתי אמרינן מעלין בקדש ולא מורידין מהם במשנה פרק שתי הלחם (מנחות דף צ״ט):\",3,0],[8,360,4,21,\"ומ\\\"ש אלא אם סרח:\",4,0],[8,360,4,22,\"ומ\\\"ש וכ\\\"ג שעבר עבירה ושחייב עליה מלקות וכו'. בירושלמי דפרק ב' דסנהדרין כהן גדול שחטא מלקין אותו ואין מורידין אותו מגדולתו ומשמע דבב\\\"ד של שלשה מלקין אותו וכ\\\"כ רבינו בפרק י\\\"ז מהלכות סנהדרין. ומה שכתוב בקצת ספרי רבינו בב\\\"ד של ע\\\"א הוא שיבוש:\",1,0],[8,360,5,1,\"כהן גדול צריך שיהיה גדול וכו'. בת״כ וביומא (דף י״ח) ובפרק הורה כהן משיח (הוריות דף ט') ובסוף פרק הזרוע (חולין דף קל״ד):\",1,0],[8,360,5,3,\"וחייב כ\\\"ג לנהוג כבוד בעצמו וכו' עד הרשות בידו. תוספתא פ\\\"ד דסנהדרין:\",1,0],[8,360,5,4,\"ומ\\\"ש לא יכנס לבית המשתה ולא לסעודה של רבים וכו'. ומ\\\"ש אבל הולך הוא אם רצה לבית האבל וכשהוא הולך אינו הולך בערבוביא עם שאר הכהנים אלא מסבבין אותו הכהנים וחולקין לו כבוד והסגן ממצעו בינו לבין העם וכו'. בפ\\\"ב דסנהדרין (דף י\\\"ח) וכשהוא מנחם אחרים דרך כל העם עוברים זה אחר זה והממונה ממצעו בינו לבין העם ופירש\\\"י וכשהוא מנחם בשורה כשחוזרין מקבורת המת שאינו שלו דרך כל העם עוברים זה אחר זה ומנחמין את האבל שעומד במעמדו והממונה סגן הכהנים ממצעו לכ\\\"ג בינו לבין העם שהממונה בימינו וכל העם בשמאלו והוא באמצע ובגמרא (דף י\\\"ט) ת\\\"ר כשהוא עובר בשורה לנחם את אחרים סגן ומשוח שעבר בימינו וראש בית אב ואבלים וכל העם משמאלו ופירש\\\"י משוח שעבר כגון שאירע פסול בכ\\\"ג ומינו אחר תחתיו ומשעבר פיסולו של ראשון חוזר לעבודתו ושני קרי ליה משוח שעבר.\",1,0],[8,360,5,4,\"ומה שכתב ואומר לאבלים תנוחמו גם זה שם (דף י\\\"ט:).\",2,0],[8,360,5,4,\"ומה שכתב והם מכבדין אותו כפי כחן. פשוט הוא:\",3,0],[8,360,5,5,\"ומ\\\"ש מת לו מת אינו יוצא אחריו וכו'. שם במשנה מת לו מת אינו יוצא אחר המטה אלא הן נכסין והוא נגלה וכו' ויוצא עמהם עד פתח העיר דברי ר' מאיר ר\\\"י אומר אינו יוצא מן המקדש משום שנאמר ומן המקדש לא יצא וידוע דהלכה כר\\\"י ולפיכך פסק רבינו שאינו יוצא מן המקדש. אבל יש לתמוה למה כתב שאינו יוצא מפתח ביתו דהא דלא כמאן וי\\\"ל שטעמו מדאמרינן בגמרא שפיר קאמר ר' יהודה אמר לך ר' מאיר אי הכי לביתו נמי לא אלא הכי קאמר ומן המקדש לא יצא מקדושתו לא יצא וכיון דאית ליה היכרא לא אתי למנגע ור' יהודה אגב מרריה דילמא מיקרי ואתי ונגע ופי' רש\\\"י מקדושתו לא יצא כלומר יעשה חיזוק בדבריו שלא יגרום לצאת מקדושה וליטמא עד כאן לשונו. וכיון דטעמיה דר\\\"י אינו אלא משום דילמא מיקרי ונגע כשאינו יוצא מפתח ביתו סגי וכן משמע מדאמר רבי מאיר א\\\"ה ביתו נמי לא וקרא דמן המקדש לאו דוקא מן המקדש דהוא הדין אם אינו יוצא מפתח ביתו ודבר זה מדברי סופרים וקרא אסמכתא בעלמא וכן כתב הרמב\\\"ן בפירוש התורה.\",1,0],[8,360,5,5,\"ומה שכתב וכל העם באים לנחמו לביתו והוא עומד בשורה וסגן בימינו וראש בית אב וכל העם משמאלו. שם בגמרא וקאמר בגמרא אבל משוח שעבר לא אתי גביה מאי טעמא חלשא דעתיה קסבר קא חדי בי ואיני יודע למה השמיטו רבינו.\",2,0],[8,360,5,5,\"ומ\\\"ש ואומרים לו אנו כפרתך וכו'. שם במשנה ופירש\\\"י אנו כפרתך בנו תתכפר אתה ואנו תחתיך לכל הראוי לבא עליך:\",3,0],[8,360,5,6,\"ומ\\\"ש וכשמברין אותו וכו' שם במשנה.\",1,0],[8,360,5,6,\"ומ\\\"ש ואינו קורע על מתו וכו'. בסוף הוריות (דף י\\\"ב:) תנן כ\\\"ג פורם מלמטה וההדיוט מלמעלה ובגמרא אמר רב למטה למטה ממש למעלה למעלה ממש ואע\\\"ג דשמואל פליג עליה פסק רבינו כרב משום דהלכתא כוותיה באיסורי.\",2,0],[8,360,5,6,\"ומ\\\"ש ואינו מרבה פרע לעולם וכו' אלא מספר מע\\\"ש לע\\\"ש. בפרק ב' דתענית ובפרק כ\\\"ג (סנהדרין דף כ\\\"ב:).\",3,0],[8,360,5,6,\"ומה שכתב ואינו מספר בתער אלא בזוג וכו'. בפרק הנודר מן המבושל (נדרים דף נ״א) ובס״פ כהן גדול תספורת של כהן גדול דכתיב כסום יכסמו את ראשיהם ה״ד אמר רבא ראשו של זה בצד עיקרו של זה ופירש הר״ן בצד עיקרו של זה מצמצם היה שלא יעלה אחד מהשערות על חבירו והרא״ש כתב כסום יכסמו את ראשיהם ככוסמת הזה ראשו של זה בצד עיקרו של זה ובכ״ג איירי מדכתיב בקרא ויין לא ישתו כל כהן מכלל דהך לאו בכל כהן איירי ועוד דברישא כתיב וראשם לא יגלחו והיינו בשאר כהנים עכ״ל:\",4,0],[8,360,5,6,\"כתב הראב\\\"ד איני מבין המופת הזה וכו'. ולא ידעתי מה הוקשה לו שמאחר שבכל שערות ראשו גוזז משער התחתון שלא ישתייר ממנו אלא כדי שיגיע לעיקר שער שעליו הרי הוא נראה כאילו צמח כאחד ופירושו של הראב\\\"ד נראה דהיינו לומר שגוזז שער התחתון כנגד ראשו של אותו שהוא למעלה ממנו בענין שמצחו ופדחתו מגולה משער התחתון ולא נשאר על מצחו ופדחתו שער אלא כנגד ראשו של עליון שלמעלה מהתחתון. ואם תאמר מה קושי יש בתגלחת זו שהוצרך בן אלעשה לפזר מעותיו עליה. וי\\\"ל שלא שער התחתון בלבד היה מגלח אלא ע\\\"ד זו היה מגלח שער שלישי שלמעלה מהשני ומשייר השער הד' כדרך ששייר השני ומגלח השער החמישי כדרך שגילח השער התחתון והג' ועל דרך זה היה משייר ומגלח עד תום כל השערות שבראש:\",5,0],[8,360,5,7,\"ובית יהיה לו מוכן במקדש והוא הנקרא לשכת כהן גדול. בפרק אחרון דמדות (משנה ה'):\",1,0],[8,360,5,7,\"ומ\\\"ש ותפארתו וכבודו שיהיה יושב במקדש כל היום וכו':\",2,0],[8,360,5,8,\"כהן גדול דן ודנין אותו ומעידין עליו. בפרק כהן גדול (סנהדרין דף י״ח).\",1,0],[8,360,5,8,\"ומה שכתב ואין דנין אותו דיני נפשות אלא בב\\\"ד הגדול בלבד. בפ\\\"ק דסנהדרין:\",2,0],[8,360,5,9,\"ומ\\\"ש היה יודע עדות אינו חייב להעיד וכו' ואם היתה עדות למלך ישראל ה\\\"ז הולך בב\\\"ד הגדול ומעיד לו. בפ' כ\\\"ג תנן כ\\\"ג מעיד ומעידין אותו ובגמרא מקשה מעיד והתניא והתעלמת פעמים שאתה מתעלם כגון כהן והוא בבית הקברות או זקן ואינה לפי כבודו כלומר והכא זילותא הוא לכ\\\"ג למיתי לאסהודי לבעל דין אמר רב יוסף מעיד למלך והא תנן המלך לא דן ולא דנין אותו לא מעיד ולא מעידין אותו אלא אמר רבי זירא מעיד לבן מלך בן מלך הדיוט הוא אלא מעיד בפני המלך והא אין מושיבין מלך בסנהדרין משום יקרא דכ\\\"ג אתי ויתיב מקבלי ניהליה סהדותיה קאי איהו ואזיל ומעיינין ליה אנן בדיניה ויש לתמוה על רבינו שכתב שאם היתה עדות למלך ישראל הולך בב\\\"ד ומעיד לו דהא ההיא אוקימתא דאוקימנא דמעיד למלך אידחיא לה ולא הוה ליה לכתוב אלא שאם היה כ\\\"ג יודע עדות מביאים המלך ויושב בבית דין ושם יעיד הכ\\\"ג וילך לו ויעיינו הדיינים בדין ואין לומר דבמלכי בית דוד דן ודנין אותם הוה ליה לרבינו לומר ואם היה יודע עדות למלך ממלכי בית דוד ומדנקט למלך ישראל משמע דבכל מלך ישראל מיירי אפי' אינו מבית דוד ואפשר לומר דמאחר שבזמן הזה בעונותינו שאין לנו לא מלך ולא שר ולא נפקא לן מידי בין מלכי ישראל למלכי בית דוד להכי סתם וכתב ואם היה יודע עדות למלך ישראל דמלך בית דוד גם הוא לא נפיק מכלל מלך ישראל ועי\\\"ל שקיצר ולא חשש לפרש מפני שסמך על מ\\\"ש בפ\\\"ג מהלכות סנהדרין ועי\\\"ל שמאחר שמן הדין אפי' מלכי ישראל דן ודנין אותם אלא דמשום מעשה שהיה בעובדא דשמעון בן שטח גזרו ואמרו מלכי ישראל לא דן ולא דנין אותם כתב רבינו כאן מה שהוא לפי הדין:\",1,0],[8,360,5,10,\"וכבר ביארנו בספר קדושה וכו'. מפורש בתורה:\",1,0],[8,360,5,10,\"ואינו נושא שתי נשים. הרב בעל המגיד בהלכות א\\\"ב בפרק י\\\"ז כתב מהיכן למד רבינו לומר כן והראב\\\"ד שם חלק על רבינו.\",2,0],[8,360,5,10,\"ומ\\\"ש רבינו ואם נשא שתים אינו יכול לעבוד ביום הצום עד שיגרש לאחת. בפ\\\"ק דיומא (דף י\\\"ג) וטעמא משום דוכפר בעדו ובעד ביתו אמר רחמנא ולא בעד שני בתים:\",3,0],[8,360,5,10,\"וחולץ וחולצין לאשתו ומיבמין את אשתו. משנה בפרק שני דסנהדרין (דף י\\\"ח).\",4,0],[8,360,5,10,\"ומ\\\"ש ואם גירש אשה מותרת לינשא לשאר העם. הכי משמע מדתנן שם גבי מלך אין נושאין את אלמנתו ולא תנן הכי גבי כהן גדול:\",5,0],[8,360,5,11,\"בזמן שכ״ג נכנס להיכל להשתחוות שלשה אוחזין בו וכו'. בפירקא בתרא דתמיד (דף ל״ג:) אלא שבמשנה לא הזכירו להיכל ורבינו כתבו כדי שלא תטעה לומר שהיה נכנס בבית קדשי הקדשים וכמו שעלה בדעת התוספות בפרק הקומץ רבה (מנחות דף כ״ז:) בד״ה להיכל לפי גירסת ספרינו ולפי מה שכתב רבינו צריך לומר דהא דתנן הגביה לו את הפרוכת שלפי דבריו גם שם היה פרוכת:\",1,0],[8,360,5,12,\"ומ\\\"ש בכל יום שירצה להקטיר הקטרת מקטיר. בפ\\\"ק דיומא (דף י\\\"ד) תנן דכ\\\"ג כל שבעה ימים הוא זורק את הדם ומקטיר את הקטורת ומטיב את הנרות וכו' ושאר כל הימים אם רצה להקריב מקריב ומשמע לרבינו דאכל הנך עבודות דרישא קתני דבשאר כל הימים אם רצה להקריב מקריב ולא הזכיר מהנך עבודות אלא קטרת משום דאית בה הנאה שמעשרת כדאיתא בפ\\\"ב דיומא (דף כ\\\"ו) וכיון דבזו אם רצה להקריב מקריב כ\\\"ש לאינך.\",1,0],[8,360,5,12,\"ומ\\\"ש ונוטל חלק בראש וכו'. בפ\\\"ק דיומא (דף י\\\"ד) תנן שכ\\\"ג מקריב חלק בראש ונוטל חלק בראש ואיתא נמי בברייתא בסוף הוריות (דף י\\\"ב:) ופירש\\\"י ונוטל חלק בראש אע\\\"פ שאינו מקריב וביומא פירש\\\"י מקריב חלק בראש ראש הוא להקטיר ולהקריב כל חלק שיבחר. ונוטל חלק בחלוקת אכילת קדשים בראש מנה יפה שיבחר לו ובגמרא (יומא י\\\"ז:) ת\\\"ר כיצד מקריב חלק בראש אומר עולה זו אני מקריב מנחה זו אני מקריב כיצד נוטל חלק בראש אומר חטאת זו אני אוכל אשם זה אני אוכל ומשמע לרבינו שבכלל זה אם מקרבן אחד רצה ליטול מנה אחת יפה נוטל וכ\\\"ש הוא.\",2,0],[8,360,5,12,\"ומ\\\"ש והרי הוא בקדשי הגבול כשאר הכהנים. כן משמע מדלא אשכחן שייפו כחו בהם:\",3,0],[8,360,5,13,\"בזמן שרוצה כהן גדול להקריב וכו' עד ואם רצה לסמוך בלבד ויהיה אחר זורק לאש עושה. בסוף תמיד (דף ל\\\"ג:) ומייתי לה בסוף פרק שתי מדות (מנחות דף צ\\\"ד) ופירש\\\"י הושיט הראשון מאותם י\\\"ב שעסוקים בתמיד וסומך עליהם כהן גדול וזורקן על האישים ונשמט השני והולך לו ובא חבירו שלישי ומושיט לראשון והראשון לכהן גדול:\",1,0],[8,360,5,14,\"ומ\\\"ש ואין שם סמיכה על האברים אלא לכ\\\"ג בלבד מפני כבודו וכו'. בסוף פרק שתי מדות ופירש\\\"י משום יקרא דכהן גדול שיהא נראה כמו שהקריב הוא את כולן:\",1,0],[8,360,5,15,\"כשיגדל הכהן ויעשה איש הרי הוא כשר לעבודה וכו'. בסוף פ\\\"ק דחולין (דף כ\\\"ד:) תנו רבנן איש מזרעך לדורותם מכאן אמר ר\\\"א קטן פסול לעבודה [ואפי' תם] מאימתי כשר לעבודה משיביא שתי שערות אבל אחיו הכהנים אין מניחין אותו לעבוד עד שיהיה בן עשרים:\",1,0],[8,360,5,15,\"ומ\\\"ש ואינו נכנס לעזרה לעבודה תחילה וכו'. בספ\\\"ב דערכין (דף י\\\"ג:) תנן אין קטן נכנס לעזרה לעבודה אלא בשעה שהלוים אומרים בשיר ואע\\\"ג דמשמע דלא איירי בכהן אלא בלוי וכדפירש\\\"י דהא גבי לוים מיתני וכמו שהשיג הראב\\\"ד וכתב א\\\"א זה טעות גדולה שלא אמרו דבר זה במשנה וכו' משמע לרבינו דהוא הדין לכהן דמ\\\"ש והכי משמע מדקתני לעבודה דמיירי בכהן דאילו בלוי שאומר בשיר אינה עבודה אלא עבודת עבודה. ועוד שהאומר בשיר אינו עובד עבודה אחרת דמשורר ששיער במיתה וא\\\"כ מאי לעבודה דקתני הילכך משמע דה\\\"ק אין קטן לוי וכהן נכנס לעזרה לוי לעבודת לוי וכהן לעבודת כהן אלא לוי בשעה שהלוים עומדים בשיר וכיון דשייך בכהן לישנא דעבודה אע\\\"ג דבלוי הוי עבודת עבודה לית לן בה. וצ\\\"ל לדעת רבינו דקטן דתנן היינו שהביא שתי שערות דאילו פחות מכאן פסול הוא לעבודה:\",2,0],[8,360,5,16,\"אין הכהן עובד תחלה וכו'. בסוף פרק התכלת (מנחות דף נ\\\"א:) תניא זה קרבן אהרן ובניו אשר יקריבו לה' ביום המשח אותו יכול יהו אהרן ובניו מקריבין קרבן אחד ת\\\"ל אשר יקריבו לה' אהרן בפני עצמו ובניו בפני עצמן בניו אלו כהנים הדיוטות את אומר כהנים הדיוטות או אינו אלא כהנים גדולים כשהוא אומר והכהן המשיח תחתיו מבניו הרי כהן גדול אמור הא מה אני מקיים בניו אלו כהנים הדיוטות ופירש רש\\\"י כהנים הדיוטות דכשהכהן הדיוט נתחנך לעבודה באותו יום היה מקריב עשרון.\",1,0],[8,360,5,16,\"ומה שכתב ועובד בידו בתוספתא סוף שקלים:\",2,0],[8,360,5,16,\"ומה שכתב ואם עבד קודם שיביא עשירית האיפה וכן כהן גדול שעבד וכו' עד כשרה. ירושלמי פרק ז' דשקלים (הלכה ו') ותוספתא סוף שקלים:\",3,0],[8,360,5,17,\"כהן שלא עבד עדיין מימיו וכו'. שם בירושלמי בו ביום נתקרב בתחילה לעבודה בו ביום נתמנה להיות כ\\\"ג מביא שתים אחת לחינוכו ואחת לעבודת היום.\",1,0],[8,360,5,17,\"ומ\\\"ש ואחר כך מקריב עשירית האיפה שלישית וכו'. פשוט הוא:\",2,0],[8,360,6,7,\"אי אפשר שיהיה קרבנו של אדם קרב וכו' לפיכך תקנו נביאים הראשונים וכו' עד ודבר זה מנהג. בפרק בתרא דתעניות (דף כ\\\"ז) זולת מ\\\"ש שקורים בס\\\"ת ג' אנשים דהכי אמרינן בפרק הקורא עומד [כל שיש בו מוסף ואינו יו\\\"ט קורין ארבעה מכלל] דכל יום שאין בו קרבן מוסף קורין ג':\",1,0],[8,360,6,7,\"וכתב בהשגות והיא יתירה להם א\\\"א איני יודע מהו שאמר והיא יתירה להם וכו':\",2,0],[8,360,6,7,\"וכתב עוד ובתפלה השניה א\\\"א זו התפלה השניה שאמר וכו':\",3,0],[8,360,6,7,\"וכתב עוד ובתפלה שניה א\\\"א הראה דעתו בכאן וכו' הרי המוסף דוחה של מוסף ושל מנחה כחזרתו של ר\\\"ע וכו':\",4,0],[8,360,6,7,\"ואני אומר שמ\\\"ש שאיני מוצאה אלא ביום שיש בו מוסף טעמו מדתנן בפרק בתרא דתעניות (דף כ\\\"ו) בג' פרקים בשנה הכהנים נושאים את כפיהם ד' פעמים ביום בשחרי' ובמוסף ובמנחה ובנעילת שערים בתעניות ובמעמדות וביוה\\\"כ ומתמה בגמרא תעניות ומעמדות מי איכא מוסף חסורי מיחסרא והכי קתני בג' פרקים כהנים נושאים כפיהם כל זמן שמתפללים ויש מהם ד' פעמים ביום שחרית ומוסף ומנחה ונעילת שערים ואלו הם ג' פרקים בתעניות ובמעמדות ובי\\\"ה ופירש\\\"י יש מהם ד' פעמים ביום יה\\\"כ שיש בו מוסף ומדמתמהינן ואמרינן תעניות ומעמדות מי איכא מוסף משמע דאין מוסף במעמדות אבל רבינו כתב שם בפירוש המשנה הנזכר שיעור זו המשנה כך בג' פרקים הכהנים נושאים את כפיהם בכל תפלה ויש מהם ד' פעמים ביום והוא יה\\\"כ ומקצת המעמדות כמו שיתבאר כי בתעניות אין בהם תפלת מוסף אבל במעמדות היו מתפללים תפלה יתירה בכל יום והיא נקראת תפלת מוסף עכ\\\"ל. וכתב עוד בפרק הנזכר [על משנת יום שיש בו הלל וכו'] אמרו במה שקדם שאנשי המעמד קורים במוסף מורה שיש במעמד מוסף וכבר ביארנו כי ענין תפלתם היא הנוספת המיוחדת באנשי מעמד ושאנשי מעמד היו מתפללים תפלה יתירה בכל יום והיא נקראת מוסף וביום שיש בו תפלת מוסף לכל העם בכלל תדחה הקריאה באותה תפלה היתירה ובתפלת המנחה עכ\\\"ל. ולפ\\\"ז צ\\\"ל שלא היה גורס תעניות ומעמדות מי איכא מוסף אלא כך היה גורס תעניות מי איכא מוסף כלומר דלא מתמה אלא אתעניות בלבד דאילו מעמדות ניחא ליה דהא אית בהו מוסף כמו ביוה\\\"כ ואפשר לומר דגריס כגירסא דידן דמתמה נמי אמעמדות לומר דמדנקט מעמדות בהדי יום הכפורים משמע דכי היכי דביוה\\\"כ לעולם איכא תפלת מוסף ה\\\"נ במעמדות לעולם יש בהם תפלת מוסף והא ליתא שהרי יש ימי מעמד שאין בהם מוסף. ומתוך מה שכתבתי יתבאר שאין מקום להשגה ראשונה ושניה:\",5,0],[8,360,6,8,\"ומ\\\"ש רבינו שמנת ימי חנוכה וכו'. שם (דף כ\\\"ו) במשנה כל יום שיש בו הלל אין מעמד בשחרית קרבן מוסף אין בנעילה קרבן עצים אין במנחה דברי ר\\\"ע א\\\"ל בן עזאי כך היה רבי יהושע שונה קרבן מוסף אין במנחה קרבן עצים אין בנעילה חזר ר\\\"ע להיות שונה כבן עזאי ופירש\\\"י כל יום שיש בו הלל אין בו מעמד שחרית אותם שהיו בירושלים לא היו מתפללין על קרבן אחיהם לפי שאין להם פנאי [לעשות מעמדו] שקורים את ההלל ומפני ההלל היו דוחים את המעמד. קרבן מוסף יום שיש בו קרבן מוסף בירושלים אין מעמד בנעילה בירושלים וכ\\\"ש במנחה הסמוכה למוסף לפי שהיו טרודים במוסף שיש בו להקריב בהמות יותר מתמיד שהוא אחד ואין לך מוסף בלא שתי בהמות ולא היה להם פנאי כלל שהכהנים של מעמד טרודין במוסף וישראל שבהם היו טרודים לחטוב עצים ולשאוב מים ודוחה אפי' מעמד דנעילה וכו'. קרבן עצים אותו יום שהיה בו קרבן עצים אפילו לא היה בו מוסף היה נדחה מעמד של מנחה מפני קרבן עצים מפני שקרבן עצים קודם למנחה ודוחה מעמד הסמוך לו ושל נעילה. כך היה רבי יהושע שונה קרבן מוסף אין במנחה עכ\\\"ל. ובגמרא מה הפרש בין זה לזה הללו דברי תורה והללו דברי סופרים וכתב רבינו בפי' המשנה יום שיש בו הלל בלי מוסף הם ימים של חנוכה ולפי שהם מד\\\"ס עשו להם חיזוק ודחו המעמד מתחילת היום ויום שיהיה בו קרבן מוסף ידחה מעמד מתפלת מוסף שלהן ומתפלת מנחה.\",1,0],[8,360,6,8,\"ומ\\\"ש הראב\\\"ד בהשגה שלישית שכתבתי בסמוך הראה דעתו בכאן וכו' שאם היה תפלת מוסף הרי המוסף דוחה של מוסף ושל מנחה נראה שטעמו לומר שאם היתה כוונתו באותה תפלה יתירה שכתב על יום שיש בו תפלת מוסף הרי יום שיש בו קרבן מוסף אין בו מעמד במוסף והוא כתב לא היה מעמד בתפלה שניה ומשמע שכוונת רבינו לומר שמתפללין תפלה שניה שלהם אלא שלא היו עושים בה מעמד כלומר שלא היו קורים בה בתורה כבשאר ימים אבל התפלה השניה ההיא לעולם היו מתפללים אותה ולכן כתב שהראה דעתו שתפלה שניה שאמר אינה תפלת מוסף. ואני אומר שדבר פשוט הוא בדברי רבינו שתפלה שניה שלהם אינה תפלת המוספים אבל היא תפלה נוספת שהם מתפללים בכל יום וביום שיש בו תפלת מוסף לכל העם תדחה הקריאה באותה תפלה היתירה ובתפלת המנחה כלומר וכ\\\"ש בתפלה היתירה ההיא וכמ\\\"ש בפירוש המשנה שכתבתי בסמוך ובכן עלו דברי רבינו מכוונים כהלכה דחזרתו של ר\\\"ע קרבן מוסף אין במנחה ומיהו מה שסיים אלא בשחרית ובנעילה אינו נוח לי דאטו נעילה קריאה אית בה וכן יקשה על מ\\\"ש וכל יום שהיה בו קרבן עצים לא היה בו מעמד בנעילה וע\\\"כ צריך לפרש שיום שיש בו קרבן מוסף לא היו מתפללים תפלה שניה שלהם וגם לא תפלת המנחה מפני שהיו טרודים בהקרבת המוספין וכדפירש\\\"י וכל יום שהיה בו קרבן עצים לא היו מתפללין תפלת נעילה ואע\\\"פ שלפי זה דבריו מוחלקים פה ממ\\\"ש בפירוש המשנה בכמה מקומות מצינו כן:\",2,0],[8,360,6,9,\"ומ\\\"ש רבינו ומהו קרבן העצים וכו'. במשנה בפרק בתרא דתעניות (דף כ\\\"ו).\",1,0],[8,360,6,9,\"ומ\\\"ש והיה להם כמו י\\\"ט ואסורין בו בהספד ובתענית וכו'. בפ\\\"ק דתעניות (דף י\\\"ב) אמר רבי אלעזר בר צדוק אני מבני בניו של סנאב בן בנימין ופעם אחת חל ט\\\"ב להיות בשבת ודחינוהו לאחר השבת והתענינו בו ולא השלמנוהו מפני שיו\\\"ט שלנו היה ופירש\\\"י כי יו\\\"ט שלנו היה כדלקמן בשלשה פרקים זמן עצי הכהנים וכו' בעשרה בו בני סנאב בן בנימין:\",2,0],[8,360,6,10,\"ומה שכתב רבינו אפילו יחיד שהתנדב עצים וכו'. בירושלמי פרק שני דחגיגה האומר הרי עלי עצים למזבח וגיזריו למערכה אסור בהספד ותענית ומלעשות מלאכה בו ביום:\",1,0],[8,360,6,11,\"אנשי מעמד אסורים מלספר ומלכבס וכו' עד סוף הפרק. משנה וגמרא בפרק ב' דתעניות (דף ט\\\"ו:):\",1,0],[8,360,7,1,\"חמשה עשר ממונים היו במקדש וכו'. בפ\\\"ה דשקלים (מ\\\"א) במשנה ונתבאר בדברי רבינו בפירוש המשנה:\",1,0],[8,360,7,1,\"וכתב בהשגות א\\\"א ולמה לא מנה הממונה על הפקיע והוא מכין הפתילות:\",2,0],[8,360,7,1,\"ואני אומר אמת הדבר כי בירושלמי פירשו מה ששנינו במשנה הנזכרת בן בבי על הפקיע כמו שפירש הראב\\\"ד אבל בגמרא דידן פ\\\"ב דיומא (דף כ\\\"ג) אמר אביי מריש ה\\\"א הא דתנן בן בבי (ממונה) על הפקיע פתילתא וכו' כיון דשמענא להא דתניא ולא עוד אלא שלוקה מן הממונה בפקיע אמינא מאי פקיע נגדא ופירש\\\"י נגדא רצועות מלקות ורבינו תפס כגמרא דידן שדחה פירוש הירושלמי מכח הברייתא. ויש לתמוה על הראב\\\"ד למה תפס על רבינו שעשה כהוגן וכשורה ובמקום דנמטייה אפריון השיגו ואין לומר שתמה עליו למה לא מנה גם הממונה על הכנת הפתילות דא\\\"כ ה\\\"ל י\\\"ו ממונים ותנא דמתני' לא מני אלא ט\\\"ו:\",3,0],[8,360,7,2,\"ומ\\\"ש רבינו זה שעל הזמנים הוא ואנשיו כו' כיון שיגיע עת הקרבן מכריז וכו'. בירושלמי פרק הנזכר וזהו ששנינו במשנה הנזכרת גביני כרוז:\",1,0],[8,360,7,3,\"ומ״ש ובכל יום תוקעין במקדש שלש תקיעות וכו'. בפרק החליל (סוכה דף נ״ג:):\",1,0],[8,360,7,4,\"ומ\\\"ש זה שעל השומרים הוא איש הר הבית וכו' עד ושורף את כסותו. בפ\\\"ק דמדות (משנה ב) וזהו ששנינו בפ\\\"ה דשקלים (משנה א) בן בבי על הפקיע:\",1,0],[8,360,7,5,\"אין פוחתין במקדש מכ\\\"א תקיעות בכל יום וכו'. משנה בפרק החליל.\",1,0],[8,360,7,5,\"ומ\\\"ש ואם חל ר\\\"ח או יו\\\"ט להיות בשבת וכו' עד לכל המוספין. שם (דף נ\\\"ד) מסיק בתיובתא למ\\\"ד הכל לפי המוספין תוקעין:\",2,0],[8,360,7,6,\"ומ\\\"ש ובע\\\"ש מוסיפין שש ג' וכו' עד בשעה שמנסכין המים. שם במשנה ע\\\"ש שבתוך החג היו שם שמנה וארבעים תקיעות שלש לפתיחת שערים שלש לשער העליון שלש לשער התחתון שלש למילוי המים ושלש על גבי המזבח ט' לתמיד של שחר ט' לתמיד של בין הערבים ט' למוספין ג' להפטיר את העם וג' להבדיל בין קדש לחול. ופירש\\\"י ג' לשער עליון דאמרן לעיל גבי שמחת בית השואבה עמדו שני כהנים בשער העליון היורד מעזרת ישראל לעזרת הנשים קרא הגבר תקעו והריעו ותקעו. ג' לשער התחתון דאמרן לעיל הגיעו לעזרה תקעו והריעו ותקעו והיו מאריכים בהם עד שהגיעו לשער היוצא למזרח והוא שער התחתון וכו'. ג' למילוי המים אחר שמילאו ושבו ובאו להם לעזרה דרך שער המים ותנן בפרק לולב וערבה הגיעו לשער המים תקעו והריעו ותקעו עכ\\\"ל. ומדברי רבינו נראה שהוא מפרש דלשער התחתון דקתני היינו לפתיחת שער העליון ולפתיחת שער התחתון:\",1,0],[8,360,7,6,\"ודע שיש בספרי רבינו חסרון הניכר וכך צריך להגיה וכן תוקעים ג' למילוי המים ואין תוקעים למילוי המים בשבת.\",2,0],[8,360,7,6,\"ומ\\\"ש ואין תוקעין למילוי המים בשבת. גם זה שם ופירש\\\"י שכבר נתמלא מע\\\"ש כדתנן בפרק לולב וערבה אלא שהיה ממלא מע\\\"ש:\",3,0],[8,360,7,9,\"הממונה שעל הקינים וכו' עד שיד הקדש על העליונה. נלמד מענין הממונה על הנסכים שיתבאר בסימן זה.\",1,0],[8,360,7,9,\"ומ\\\"ש וכן קן שנמצא פסול או שנפסל וכו'. בספ\\\"ז דשקלים (מ\\\"ז) רבי יוסי אומר המספק את הקינין מספק את הפסולות ואין לתמוה למה לא פסק כת\\\"ק דאמר שקינים פסולות באות משל צבור דאיכא למימר שפסק כרבי יוסי משום דמסתבר טעמיה ועוד דת\\\"ק הוי ר\\\"ש כמפורש בריש אותה משנה ופסק כרבי יוסי לגבי ר\\\"ש:\",2,0],[8,360,7,9,\"וכתוב בהשגות א\\\"א לא כי הממונה על הקינין וכו'. ואני אומר שאין זו השגה דפירושי נינהו ומר מפרש הכי ומר מפרש הכי:\",3,0],[8,360,7,10,\"זה שעל החותמות הוא שמקבל דמי וכו'. יתבאר בסמוך:\",1,0],[8,360,7,11,\"ומ\\\"ש כיצד ארבע חותמות היו במקדש האחד כתוב עליו עגל וכו'. בפרק ה' דשקלים (משנה ג'):\",1,0],[8,360,7,12,\"ומ\\\"ש כל מי שיביא קרבנותיו למקדש נותן דמי הנסכים לזה הממונה על החותמות וכו' עד הנסכים. בפרק הנזכר.\",1,0],[8,360,7,12,\"ומ\\\"ש ואם היה מצורע עשיר מביא ג' עשרונין ולוג שמן ואין דוגמתו כשאר החותמות אבל מצורע עני אינו טעון להביא אלא עשרון אחד כמו שטעון הגדי ולכן נותנין לו חותם של גדי.\",2,0],[8,360,7,12,\"ומ\\\"ש רבינו ושם כל היום כתוב על החותם וכו' עד שיוקרו הנסכים. שם במשנה ושם (כל) היום כתוב עליהם מפני הרמאין ופירוש רבינו בה נכון וכן פירש בפי' המשנה וכתב שם עוד פירוש אחר והוא כדי שלא ימצא חותם שנפל קודם לכן לבעליו או לאחיה או ליוחנן ויגבה בו ואין אותו פי' נכון כ\\\"כ משום דא\\\"כ למה לכתוב שם היום יכתבו שם בעליו ודי והראב\\\"ד כתב על דברי רבינו לא כי אלא שמא יעשנו אובד ויבא לידי אחר ויוציא חותמו ואין לומר שהוא מפרש כאותו פי' אחר שכתב רבינו בפי' המשנה דא\\\"כ מאי שמא יעשנו אובד דקאמר שמא יאבדנו מיבעי ליה ויש ספר שהוגה בהשגת הראב\\\"ד ליום אחר במקום לידי אחר וטעמו לומר שמא יצניענו ויאמר שאבד ממנו ויתבע מהממונין שיחזירו לו הדמים שנתן וימצאו דמי החותם ההוא יתר על החותמות הנמצאים ויחזירום לו וביום אחר יוציא אותו חותם ויתנו לו נסכים כדי אותו חותם. ומ\\\"מ יש לתמוה גם בהשגה זו גם בקודמת למה דחה פי' רבינו לומר לא כי אלא בהיות פי' רבינו מתיישב ג\\\"כ:\",3,0],[8,360,7,13,\"משלשים יום לשלשים יום וכו' עד כשער הזול. בספ\\\"ד דשקלים (מ\\\"ט):\",1,0],[8,360,7,13,\"ומ\\\"ש והשכר שמשתכר ההקדש בשערים וכו'. בפ\\\"ד דשקלים (משנה ד') תנן ר\\\"ע אומר מותר תרומה קיץ למזבח מותר נסכים לכלי שרת רבי חנינא סגן הכהנים אומר מותר נסכים קיץ למזבח ומותר התרומה לכלי שרת וכתב שם רבינו עוד יתבאר לך בפרק שאחר זה כי הנסכים היה הקדש משתכר בהם והיה מתקבץ ממנו דמים יתרים והם נקראים מותר נסכים ופסק רבינו כרבי חנינא. ויש לתמוה דהא קי\\\"ל הלכה כר\\\"ע מחבירו ואפשר שטעמו משום דכיון דרבי חנינא סגן הכהנים הוה מסתמא במילי דמקדש טפי הוה בקי מר\\\"ע.\",2,0],[8,360,7,13,\"ומ\\\"ש ואין מקיצין את המזבח בעולות עוף וכו' בפ\\\"ק דשבועות (דף י\\\"ב:):\",3,0],[8,360,7,14,\"הכהנים מפני שהם עומדים על הרצפה תמיד וכו' עד להיכל ולשערים. הוא ביאור הממונין שכתב בראש הפרק:\",1,0],[8,360,7,16,\"ויש בספרי רבינו חסרון וכך צריך להגיה ושתי פרוכות היו עושים בכל שנה להבדיל בין הקדש לקדש הקדשים והוא משנה בפרק בתרא דשקלים (דף י״א ע״א): ומ״ש וחוטי הפרוכת כפולים ששה וכו' עד הרי כ״ד חוטים. שם ובפרק בא לו (יומא דף ע״ב).\",1,0],[8,360,7,16,\"ומ\\\"ש וטפח היה עביה וכו' עד עשרים אמה. בפרק בתרא דשקלים:\",2,0],[8,360,7,17,\"ומ״ש ושלש עשרה פרוכות היו במקדש שני וכו'. מימרא פרק הוציאו לו (יומא דף נ״ד):\",1,0],[8,360,7,18,\"פרוכת שנטמאת בולד הטומא' מטבילין וכו' עד שהיא נאה. בפרק ב' דשקלים:\",1,0],[8,360,7,19,\"וכל הכלים שהיו במקדש היו להם שניים ושלישים וכו'. משנה בסוף חגיגה (דף כ\\\"ז:):\",1,0],[8,360,7,20,\"זה הממונה על מעשה בגדי כהונה וכו'. כתב הראב\\\"ד אומר אני שהוא פינחס המלביש עכ\\\"ל. ופשוט הוא ואיני יודע מה מלמדנו.\",1,0],[8,360,7,20,\"ומ\\\"ש רבינו ולשכה היתה לו במקדש. בפרק קמא דמדות (משנה ד'):\",2,0],[8,360,8,1,\"בגדי כהונה ג' מינים וכו' בגדי כהן הדיוט הם ארבעה כלים וכו'. מפורשים בתורה.\",1,0],[8,360,8,1,\"ומ״ש וארבעתן של פשתן וחוטן כפול ששה. בפרק בא לו (יומא דף ע״ב).\",2,0],[8,360,8,1,\"ומ\\\"ש לבנים וכו'. ומ\\\"ש והאבנט לבדו רקום בצמר. בפ\\\"ק דיומא (דף י\\\"ב:) כי אתא רבין אמר אבנטו של כ\\\"ג בי\\\"ה ד\\\"ה של בוץ בשאר ימות השנה ד\\\"ה של כלאים לא נחלקו אלא באבנטו של כהן הדיוט בין בשאר ימות השנה בין בי\\\"ה שרבי אומר של כלאים ורבי אלעזר בר\\\"ש אומר של בוץ וידוע שהלכה כרבי מחבירו:\",3,0],[8,360,8,2,\"בגדי זהב הם בגדי כ\\\"ג והם ח' כלים וכו'. לשון זה קשה בעיני שהרי הארבעה של כל כהן אינם של זהב וצ\\\"ל דה\\\"ק בגדי זהב הם מיוחדים בכהן גדול ובגדי כ\\\"ג הם שמנה כלים הארבעה של כל כהן ומעיל ואפוד וכו' ואלו הארבעה הנוספים בכהן גדול הם של זהב.\",1,0],[8,360,8,2,\"ומ\\\"ש ואבנטו של כ\\\"ג מעשה רוקם הוא מדכתיב ואבנט תעשה מעשה רוקם.\",2,0],[8,360,8,2,\"ומ\\\"ש והוא דומה במעשיו לאבנט כהן הדיוט נתבאר בסמוך.\",3,0],[8,360,8,2,\"ומ\\\"ש ומצנפת האמורה באהרן היא האמורה בבניו וכו' לפיכך נקראת מגבעת. נ\\\"ל שטעמו לומר כדברי הרמב\\\"ן שאכתוב בסמוך שאותיות גיכ\\\"ק מתחלפות והו\\\"ל כאילו כתיב מקבעת והוא מלשון קובע וכן תירגם המתרגם מגבעות כובעין וכתב הראב\\\"ד ולפיכך נקרא מגבעת א\\\"א אני אומר אין מעשהו של זה כמעשהו של זה וכו'. והרמב\\\"ן כתב בפרשת תצוה וז\\\"ל כתב רש\\\"י שהמצנפת כמין כובע שהרי במקום אחר קורא לה מגבעת ומתרגמינן כובעין וזה אינו שהרי אמרו שהמצנפת ארכה י\\\"ו אמה והרי היא כעין צניף שצונף בה ראשו מגלגל ומחזיר מגלגל ומחזיר סביב ראשו כפל על כפל ומצנפת של כ\\\"ג אינה קרויה מגבעת בשום מקום אבל בכהן הדיוט אמר הכתוב מגבעת ואף היא מצנפת היא אלא שקושר בה כל ראשו ומעלה הכפלים עליו כעין מגבעת שהוא כובע כדברי אונקלוס כי מגבעת כמו מקבעת כאשר אמרתי בחילופי הגימ\\\"ל והקו\\\"ף אלא שהמגבעת כמו המצנפת ולכך יזכירו חכמים תדיר בכ\\\"ג והדיוט מצנפת בתורת כהנים ובמסכת יומא שנינו כהן גדול משמש בח' בגדים וההדיוט בארבעה בכתנת ומכנסים מצנפת ואבנט מוסף עליו כהן גדול חשן ואפוד ומעיל וציץ עכ\\\"ל. ודבריו מסכימים לדברי רבינו:\",4,0],[8,360,8,3,\"בגדי לבן הם ארבעה הפשתן לבדו הם. בפרק בא\",1,0],[8,360,8,3,\"לו כלים שמשמש בהם (דף ע\\\"ב).\",2,0],[8,360,8,3,\"ומה שכתב ושתי כתנות כהן גדול ביום הכיפורים וכו' אחרות היו לו לכ\\\"ג בי\\\"ה וכו' עד וארבעתן לבנים וכו'. מה\",3,0],[8,360,8,3,\"שכתב מוסיף משלו. משנה בפרק שלישי שהם לבנים כך קורא אותם דיומא (דף ל\\\"ד:).\",4,0],[8,360,8,3,\"ומה שכתב במשנה דיומא בגדי לבן.\",5,0],[8,360,8,3,\"ומה ומקדיש התוספת וכו'. כן\",6,0],[8,360,8,3,\"משמע שכתב וחוטן כפול ששה ומן שם בגמרא (דף ל\\\"ה):\",7,0],[8,360,8,4,\"בגדי כהונה מצותן שיהיו חדשים נאים ומשולשים וכו'. בפ\\\"ב דזבחים (דף י\\\"ח:) יליף מקרא דמצוה שיהיו חדשים.\",1,0],[8,360,8,4,\"ומ\\\"ש שיהיו נאים ומשולשים מתבאר ממה שיבא בסמוך:\",2,0],[8,360,8,4,\"היו מטושטשין או מקורעין או ארוכים יתר על מדתו או קצרים וכו'. בפ\\\"ב דזבחים ת\\\"ר היו מרושלין מסולקים משוחקים ועבד עבודתו כשרה היו מטושטשין או מקורעין ועבד עבודתו פסולה אמר רב יהודה אמר שמואל מרושלין כשרים מסולקים פסולים והתניא מסולקין כשרים אמר רמי בר חמא ל\\\"ק כאן שסילקן על ידי אבנט כאן דליתנהו מעיקרא כלל רב אמר אחד זה ואחד זה פסולים וכו' ומי אמר שמואל וכו' מסולקין פסולים והתניא מסולקים כשרים א\\\"ל בר מינה דההיא דשנייה רמי בר חמא אלא לרב קשיא וכ\\\"ת מאי מרושלים מסולקין ע\\\"י אבנט אבנט מיגז אגיז אלא מסולקים קשיא א\\\"ר זירא רב חדא תני מרושלין שסילקן ע\\\"י אבנט כשרים. ופירש\\\"י מרושלין נגררין בקרקע מסולקים מן הקרקע מתוך שהם קצרים. משוחקים ישנים כשרים ואע\\\"ג דכתיב מדו בד שתהא כמדתו מצוה בעלמא היא ולא לעכב. מטושטשין בטיט. מקורעים ואפי' הן חדשי' דלאו בגד הוא הראוי לעבודה דבעינן לכבוד ולתפארת. אחד זה ואחד זה אחד מרושלין ואחד מסולקין יותר מדאי שלא ע\\\"י אבנט. אלא לרב קשיא מרושלין וכ\\\"ת מאי מרושלין דמכשר תנא כגון שסילקן עד למדתו ע\\\"י אבנט וקא מכשר ליה תנא דקסבר אבנט מיגז אגיז כלומר כל סילוק שע\\\"י אבנט הו\\\"ל כחותך ונוטל היתר שבהן ומכשירו. אלא מסולקין קשיא דקתני כשרים וסתם מסולקין גבוהים מן הקרקע למעלה מרגליו משמע ולרב ליכא לאוקומה כגון שסילקן ע\\\"י אבנט כדתרצינן דהא ע\\\"כ לרב דשני דסילוק אבנט מיגז אגיז השתא הוו כלהו כקצרים מעיקרא. רב חדא תני להנך מרושלין ומסולקים דברייתא בחדא מילתא תני להו מרושלין שסילק רישולן ע\\\"י אבנט עד כדי מדתו כשרים אבל מסולקים יותר מדאי פסולין ואפי' ע\\\"י אבנט וידוע דהלכה כרב באיסורי:\",3,0],[8,360,8,4,\"והשתא מ\\\"ש רבינו לפסול בארוכין יתר על כדי מדתו היינו כרב דפסל\",4,0],[8,360,8,4,\"במרושלין ומ\\\"ש לפסול בסילקן באבנט כלומר ושהיו כדי מדתו וסילקן באבנט ונעשו פחות מכדי מדתן היינו כרב משום דאבנט מיגז\",5,0],[8,360,8,4,\"אגיז ומ\\\"ש להכשיר בארוכים וסילקן באבנט עד שנעשו כדי מדתו היינו כדפריש רב בברייתא:\",6,0],[8,360,8,5,\"כל בגד מבגדי כהונה וכו'. ברייתא בס״פ המזבח מקדש (זבחים דף פ״ח:) ופסק כיש אומרים משום דאין עניות במקום עשירות.\",1,0],[8,360,8,5,\"ומ״ש אלא מניחן לפתילות. במשנה פ' החליל (סוכה נ״א:):\",2,0],[8,360,8,5,\"ובגדי כהן גדול שבלו גונזין אותן: ובגדי לבן שעובד בהם ביום הצום וכו'. בפ' שני דיומא (דף כ\\\"ד) ופרק קמא דכריתות (דף ו') ופרק ב\\\"ש זבחים (דף מ\\\"ו) והניחם שם מלמד שטעונין גניזה רבי דוסא אומר ראויים הם לכהן הדיוט ומה תלמוד לומר והניחם שם שלא ישתמש בהם יה\\\"כ אחר ופסק כת\\\"ק:\",3,0],[8,360,8,6,\"מכנסי כהנים הדיוטים שבלו וכו'. משנה בר״פ החליל (סוכה דף נ״א).\",1,0],[8,360,8,6,\"ומ״ש וכתנות כהנים הדיוטים שבלו היו עושין מהם פתילות למנורת תמיד. בפרק במה מדליקין (שבת דף כ״א) תני רמי בר חמא פתילות ושמנים שאמרו חכמים אין מדליקין בהם בשבת אין מדליקין בהם במקדש משום שנאמר להעלות נר תמיד וכו' שתהא שלהבת עולה מאליה ולא שתהא עולה על ידי ד״א תנן מבלאי מכנסי כהנים ומהמייניהם היו מפקיעין ומהם מדליקין שמחת בית השואבה שאני ת״ש דתני רבה בר מתנה בגדי כהונה שבלו מפקיעין אותם ומהם היו עושים פתילות למקדש מאי לאו דכלאים לא דבוץ ופירש״י המייניהם כתיב ואת האבנט שש משזר ותכלת וארגמן וקי״ל תכלת עמרא הוא ותניא לעיל לענין שבת הוסיפו עליהם של צמר לפיסול וקתני מדליקין בהם במקדש. בית השואבה שאני דלא כתיב בה להעלות ולאו דאורייתא היא. מאי לאו דכלאים כגון אבנט עכ״ל. ודייק רבינו כתנות כהנים למעט אבנט דאין עושין מהם פתילות למנורת תמיד משום דאית בהו עמרא ואין להדליק בהם למנורת התמיד ומכנסים תנן דבשמחת בית השואבה מדליקין בהם ולא נשאר לפתילות מנור' התמיד כ״א כתונת ומצנפת וצריך טעם למה השמיט רבינו מצנפת ואפשר דתנא כתנות והוא הדין למצנפות אי נמי משום דמצנפות דקות ביותר ולא חזו לפתילות לכך השמיטם:\",2,0],[8,360,8,7,\"כל בגדי הכהנים וכו'. בפ\\\"ג דיומא (דף ל\\\"ה:) ובירושלמי פרק רביעי דשקלים (הלכה א').\",1,0],[8,360,8,7,\"ומה שכתב וכן כל כלי השרת ועצי המערכה שמסרן יחיד לצבור הרי הם כשרים אף כל קרבנות הצבור וכו'. עצי המערכה בסוף תעניות (דף כ\\\"ח) אמרינן זמן עצי הכהנים שכשעלו בני הגולה לא מצאו עצים בלשכה עמדו אלו והתנדבו משלהם ובתוספתא פרק שני דשקלים כל קרבנות הצבור נתנדבו מעצמן כשרים ובלבד שימסרום לצבור ולמד רבינו מזה לכלי שרת ועצי המערכה שצריך שימסרם לצבור:\",2,0],[8,360,8,8,\"בגדי כהנים הדיוטים וכו'. בפרק ה' דתמיד (דף ל״ב:) תנן חלונות היו שם וכתוב עליהם תשמישי הכלים ובסוף החליל (סוכה דף נ״ו) תנן בילגה חלונה סתומה וכתב שם רבינו כיוצא במה שכתב כאן:\",1,0],[8,360,8,9,\"ולמה עשו ארבעה חלונות לכל משמר וכו':\",1,0],[8,360,8,10,\"כהן גדול מניח בגדי זהב בלשכה שלו וכו':\",1,0],[8,360,8,11,\"בגדי כהונה מותר ליהנות בהם וכו'. בעיא דאיפשיטא בר״פ בא לו (יומא דף ס״ח ס״ט).\",1,0],[8,360,8,11,\"ומ\\\"ש חוץ מן האבנט וכו'. שם ובפ\\\"ק דתמיד אהא דתנן לא היו ישנים בבגדי קדש אלא פושטין ומקפלין ומניחין תחת ראשיהם אמרינן (דף כ\\\"ז) נהי דניתנו ליהנות בהם תיפוק ליה משום איסורא דכלאים הניחא למ\\\"ד אבנטו של כ\\\"ג בשאר ימות השנה לא זהו אבנטו של כהן הדיוט אלא למ\\\"ד אבנטו של כ\\\"ג זהו אבנטו של כהן הדיוט כלומר דשל הדיוט הוי של כלאים מאי איכא למימר וכבר נתבאר בר\\\"פ זה שרבינו פוסק כמ\\\"ד דאבנטו של כהן הדיוט הוי של כלאים ואע\\\"ג דאסיק התם רב אשי דבגדי כהונה לית בהו משום כלאים משום דקשים הם היינו לענין הצעה אבל ללבוש אפילו שהם קשים אסור ולפיכך כתב רבינו דאבנט אסור לכהן הדיוט ללבשו אלא בשעת עבודה והוא הדין לכהן גדול בשאר ימות השנה שאז אבנטו כלאים כשל כהן הדיוט ולא נקט רבינו כהן הדיוט אלא לאפוקי כהן גדול ביה\\\"כ:\",2,0],[8,360,8,11,\"וכתב הראב\\\"ד א\\\"א לא מחוור מן הגמרא הכי אלא כל היום מותר במקדש עד כאן לשונו. ונראה שטעמו משום דמייתי שם בגמרא ברייתא דקתני בגדי כהונה היוצא בהם למדינה אסור ובמקדש בין בשעת עבודה בין שלא בשעת עבודה מותר ומשמע להרב רבי אברהם בן דוד דמדסתים ותני בגדי כהונה אף אבנט בכלל ומשמע ליה דבכל ענין שרי להו אף משום כלאים ורבינו משמע ליה דהאי ברייתא לאו לענין היתר כלאים מיתניא אלא לענין היתר הנאת בגדי כהונה וכדמסיים בה מפני שבגדי כהונה ניתנו ליהנות בהן אבל היתר אבנט שהוא כלאים אינו אלא בשעת עבודה בלבד וכדאמרינן בריש ערכין (דף ג':) בהדיא גבי כלאים דאשתרי גבי כהנים נהי דאשתרי בעידן עבודה בלא עידן עבודה לא אשתרי ויש לתמוה על הראב\\\"ד מההיא דערכין וצריך לדחוק ולומר שהוא מפרש דעידן עבודה לאו דוקא אלא הוה ליה כאילו אמר במקדש אלא משום דבמקדש דשרינן שלא בשעת עבודה טעמא משום דבמקום עבודה הוא מגו דאשתרי בשעת עבודה אשתרי אף שלא בשעת עבודה מש\\\"ה נקט בעידן עבודה ומפני שראה הראב\\\"ד חולשת דברים אלו לא כתב דבריו כגוזר אומר להשיג:\",3,0],[8,360,8,12,\"אין הכהנים לובשים לעבודה אלא צמר ופשתים בלבד. ברפ\\\"ט דכלאים (משנה א'):\",1,0],[8,360,8,13,\"ומ״ש וכל מקום שנאמר בתורה שש או בד הוא הפשתים והוא הבוץ. בפרק בא לו (יומא דף ע״א:) ובפ״ב דזבחים (דף י״ח:):\",1,0],[8,360,8,13,\"ומ\\\"ש ותכלת האמורה בכל מקום הוא הצמר הצבוע כעצם השמים. ומ\\\"ש הארגמן הוא הצמר הצבוע אדום וכו'. כתב הראב\\\"ד א\\\"א לי נראה ארגמן וכו'. טעמו שארגמן מלה מורכבת ארוג מין והמפרשים פירשו כדברי רבינו:\",2,0],[8,360,8,14,\"כל מקום שנאמר בתורה שש וכו'. בפרק בא לו שם.\",1,0],[8,360,8,14,\"ומ\\\"ש ומקום שנאמר בד אם היה חוט אחד לבדו כשר ומצוה מן המובחר שיהא כפול ששה. בפרק שני דזבחים אמרו בגדים שנאמר בהם בד צריכין שיהיו של בוץ חדשים שזורין ושיהיו חוטן כפול ששה יש מהם למצוה ויש מהם לעכוב ונראה שרבינו מפרש יש מהם למצוה היינו שיהיה כפול ששה ויש מהם לעכוב היינו חוט אחד ורש\\\"י לא פירש כן וגם פשטא דשמעתא לא משמע הכי.\",2,0],[8,360,8,14,\"ומה שכתב מקום שנאמר משזר בלבד צריך שיהא חוטן כפול שמנה. בפרק בא לו:\",3,0],[8,360,8,15,\"כל מקום שנאמר בתורה מעשה רוקם וכו'. בפרק בא לו (יומא דף ע״ב:) רוקם מעשה מחט לפיכך פרצוף אחד חושב מעשה אורג לפיכך שני פרצופות ומפרש לה רבינו כפשטה. ורש״י מפרש בענין אחר:\",1,0],[8,360,8,16,\"וכיצד מעשה הבגדים הכתנת וכו' משבצת היתה. מבואר בכתוב.\",1,0],[8,360,8,16,\"ומה שכתב ובית יד שלה נארג בפני עצמו ומחברין אותו עם גוף הכתונת. בפרק בא לו (יומא דף ע״ב:):\",2,0],[8,360,8,17,\"אורך הכתונת וכו'. הוא על פי מה שנתבאר בפרק זה שבגדי כהונה לא יהו ארוכים ולא קצרים.\",1,0],[8,360,8,17,\"ומה שכתב ואורך בית יד שלה וכו'. בפרק בא לו:\",2,0],[8,360,8,18,\"המכנסים בין של כ\\\"ג בין של כהן הדיוט וכו'. מבואר בכתוב.\",1,0],[8,360,8,18,\"ומ\\\"ש ושנצים יש להם ואין להם לא בית הנקב ולא בית הערוה וכו'. בר\\\"פ ב' דנדה (דף י\\\"ג:) ופירש\\\"י אין להם לא בית הנקב וכו' כלומר חללו רחב ותלוי למטה ולא היה תיק בין הירכים להיות האבר מתעטף בו שלא יבא האבר לידי הרהור והיינו בית הערוה ובית הנקב כשהן קצרות כנגד נקב הרעי כתבנית אדם נכנסות בעגבותיו ומלוכלכות בזיעה וגנאי הוא לבגדי הקדש בכך. ל\\\"א בית הנקב ובית הערוה דרכן היה לעשות נקבים במכנסי' כנגד בית הערוה להשתין מים לחוץ דרך שם וכן כנגד בית הרעי וכשגומר קושר הנקב ברצועה וסותמו עכ\\\"ל:\",2,0],[8,360,8,19,\"המצנפת של כ\\\"ג או הדיוט ארכו י\\\"ו אמות. כן כתב הרמב\\\"ן בפרשת תצוה בשם רז\\\"ל.\",1,0],[8,360,8,19,\"ומ״ש והאבנט רחבו כמו ג' אצבעות ואורך ל״ב אמה: ובגדי כהונה כולן אין עושין אותן מעשה מחט וכו'. בפרק בא לו (יומא דף ע״ב:) וס״פ המזבח מקדש (זבחים דף פ״ח):\",2,0],[8,360,9,1,\"כיצד מעשה הציץ וכו'. בפרק במה אשה יוצאה (שבת דף סג:) ואיתיה נמי בפרק קמא דסוכה (דף ה') אלא ששם כתוב יו״ד ה״א מלמעלה וקדש למ״ד מלמטה ורבינו כתב כגירסת פ' במה אשה ואע״ג דפליג התם ר' אליעזר בר' יוסי ואמר אני ראיתיו ברומי וכתוב עליו קדש לה' בשיטה אחת פסק כת״ק.\",1,0],[8,360,9,1,\"ומ\\\"ש ואם כתבו בשיטה אחת כשר נראה דהיינו מדאמר ר\\\"א ברבי יוסי אני ראיתיו דאף על גב דהלכה כת\\\"ק היינו לכתחילה אבל בדיעבד מיהא הלכה כרבי אליעזר ברבי יוסי ומטעם זה כתב ופעמים כתבוהו בשיטה אחת דכיון דעד ראיה הוא רבי אליעזר ברבי יוסי אמרינן דפעמים כתבוהו כן:\",2,0],[8,360,9,1,\"וכתבו התוספות [בסוכה] קדש למ\\\"ד מלמטה י\\\"מ למטה ממש זה למעלה מזה ולא מסתבר שאין זה כדרך קריאתו אלא יש לפרש זה שלא כנגד זה קדש למ\\\"ד בתחלת שיטה תחתונה והשם בסוף שיטה עליונה:\",3,0],[8,360,9,2,\"ומ\\\"ש והאותיות בולטות בפניו חופר את האותיות מאחוריו וכו' צריך לכתוב בו האותיות משום דכתיב ויכתבו עליו מכתב וצריך שיחפור מאחריו משום דכתיב ופתחת עליו פתוחי חותם. וכתב הראב\\\"ד אינו חופר אלא מכה בדפוס צורת האותיות וכו' כלומר דבדרך זה אין מקום לדיבוק על השעוה ולא נעלם מרבינו דרך זה ולא בחר בו משום דכשמכה בדפוס אינו יכול לכוון שיבא הפתוח כנגד האותיות הכתובות בכיון ממש ועוד דפתוחי חותם אינו הכאה בדפוס:\",1,0],[8,360,9,2,\"והוא נקוב בשתי קצותיו וכו'. כתב הראב\\\"ד עוד יש בו נקב באמצע וכו'. דעתו כדעת רש\\\"י בפרשת תצוה והרמב\\\"ן הקשה עליו והעלה כדברי רבינו:\",2,0],[8,360,9,3,\"המעיל כולו תכלת. מבואר בפסוק.\",1,0],[8,360,9,3,\"ומ״ש וחוטיו כפולים י״ב. בפרק בא לו (יומא דף עא:) יליף לה מקרא.\",2,0],[8,360,9,3,\"ומ\\\"ש ופיו ארוג בתחלת אריגתו. היינו מדכתיב בפרשת תצוה במעיל והיה פי ראשו בתוכו שפה יהיה לפיו סביב מעשה אורג ופירש\\\"י פתיחת בית הצואר בתוכו כתרגומו כפיל לגויה כפול להיות לו לשפה כפול בו והוא מעשה אורג ולא במחט.\",3,0],[8,360,9,3,\"ומ\\\"ש ואין לו בית יד כתב הראב\\\"ד א\\\"א זו מנין לו עכ\\\"ל. והנה הרמב\\\"ן בפירוש התורה כתב כדברי רבינו ואפשר דבאי זו ברייתא מצאו כן.\",4,0],[8,360,9,3,\"ומ\\\"ש אלא נחלק לשתי כנפים כתב הראב\\\"ד וגם זו מנין לו עכ\\\"ל. וגם בזה פירש הרמב\\\"ן כדברי רבינו:\",5,0],[8,360,9,3,\"והקורע פי המעיל לוקה וכו'. וה״ה לכל בגדי כהונה וכו'. בפרק בא לו (יומא דף ע״ב).\",6,0],[8,360,9,3,\"ומ\\\"ש דרך השחתה. פשוט הוא ונלמד ממה שנתבאר בפרק א' מהלכות בית הבחירה (פ\\\"א דין י\\\"ז) גבי נותץ אבן אחת מהמזבח:\",7,0],[8,360,9,4,\"ומביא תכלת וארגמן ותולעת שני כל מין וכו'. בפרק בא לו (יומא דף עא:).\",1,0],[8,360,9,4,\"ומה שכתב ועושה אותם כמין רמונים שלא פתחו פיהם ותולה אותם במעיל ומביא ע״ב זוגים ובהם ע״ב ענבולים הכל זהב ותולה בו וכו'. בס״פ המזבח מקדש (זבחים דף פח:) ת״ר מעיל כולו של תכלת היה שנאמר ויעש את מעיל האפוד כליל תכלת הא כיצד מביא תכלת וארגמן ותולעת שני שזורין ועושה אותם כמין רמונים שלא פתחו פיהן וכו' ומביא ע״ב זוגין שבהם ע״ב ענבלים ותולה בהם שלשים וששה בצד זה ול״ו בצד זה רבי דוסא אומר משום ר' יהודה ל״ו היו י״ח מצד זה וי״ח מצד זה ופסק רבינו כת״ק ופירש״י נראה בעיני דה״ג שוליו כיצד היה מביא וכו' דברמונים נאמרו ג' צבעים וכו'. ענבלין מה שתלוי בתוכן לקשקש ותולה בו אצל הרמון והוא פעמון כדכתיב פעמון ורמון ובתוך הרמונים דקרא לאו בתוך החלל קאמר אלא ביניהם פעמון אחד בין שני רמונים. מצד זה מלפניו ומלאחריו עכ״ל. וכן פירש״י עוד בפרשת תצוה והוא כדברי רבינו ושלא כדברי ראב״ע והרמב״ן ופשט לשון הברייתא משמע כפירוש רבינו ורש״י דקתני מביא ע״ב זגין שבהם ע״ב ענבולין ותולה בהן דאילו לפי' הרמב״ן והראב״ד הרמונים היה תולה במעיל לא הזגין כי הם היו בתוך הרמונים לפי דבריהן:\",2,0],[8,360,9,5,\"הזהב שבאריגת האפוד והחשן האמור בתורה וכו'. בפרק בא לו (יומא דף ע״ב) יליף לה מקרא:\",1,0],[8,360,9,6,\"כיצד מעשה החשן אורג בגד מעשה חושב וכו'. מבואר בכתוב. כתב הסמ\\\"ג מעשה החשן היה ארוג ממינים הללו מעשה חושב ארכו אמה ורחבו זרת וכופלו לשנים נמצא זרת על זרת מרובע ונתת אל חשן המשפט את האורים ואת התומים פירש\\\"י הוא כתב שם המפורש שהיה נותנו בתוך כפלי החשן שעל ידו הוא מאיר דבריו ומתמם דבריו עכ\\\"ל וכך הם דברי הרמב\\\"ן בפירוש התורה:\",1,0],[8,360,9,7,\"ומ״ש וכותב בתחלה למעלה מראובן אברהם יצחק ויעקב וכותב למטה מבנימין שבטי יה. בס״פ בא לו (יומא דף ע״ג) כיצד נעשית רבי יוחנן אמר בולטות ר״ל אמר מצטרפות והא לא כתיב בהו צד״י א״ר שמואל בר יצחק אברהם יצחק ויעקב כתיב שם והא לא כתיב טי״ת א״ר אחא בר יעקב שבטי ישורון כתיב שם ופירש״י והא לא כתיב בכל השבטים ואם צריך לה כגון והצל תציל מהיכא באה ובירושלמי ס״פ בא לו אית תנויי תני הקול היה שומע אית תנויי תני הכתב היה בולט מ״ד הכתב [היה] בולט והא לית חי״ת בשבטים ולא צד״י ולא קו״ף אברהם יצחק ויעקב כתוב עליהם והא לית טי״ת בשבטים כל אלה שבטי ישראל היה חקוק עליהם ויש לתמוה למה שינה רבינו לכתוב שהיה כתוב למטה שבטי יה ונראה שהוא מפרש דעליהם דקאמר הוי כמו ועליו מטה מנשה דהוי פירושו סמוך לו ומשמע ליה דלמטה כתוב כן ולא למעלה דלא לשתמע דקאי אאברהם יצחק ויעקב דכתיבי לעיל ואכתי איכא למידק למה השמיט רבינו כל אלה וי״ל משום דלא כתיב בגמ' דידן ואם תאמר למה כתב יה במקום ישראל דירושלמי או ישורון דגמרא דידן וי״ל דכיון דבחד גמרא כתיב הכי ובאידך גמרא כתיב הכי משמע דישראל וישורון לאו דוקא דלא אתו למימר אלא דכתיב טי״ת וכיון שכן עדיף לן למימר דהוה כתיב שבטי יה דכתיב ביה עדות לישראל דדמי למאי דכתיב בחשן לזכרון (להם) לפני ה':\",1,0],[8,360,9,8,\"ומ\\\"ש ועושה על ארבע זויות של חשן ד' טבעות זהב וכו'. מפורש במקרא פרשת תצוה ורש\\\"י בפירוש התורה בסוף פרשת פקודי כתב באורך מעשה האפוד ויש קצת שינוי בין דבריו לדברי רבינו ע\\\"ש:\",1,0],[8,360,9,9,\"האפוד רחבו כרוחב גבו של אדם מכתף לכתף וכו': ומפתח על שתי וכו' כתולדותם. בפרק ואלו נאמרים (סוטה דף ל\\\"ו) תניא שתי אבנים טובות היו לו לכ\\\"ג על כתפיו אחת מכאן ואחת מכאן ושמות י\\\"ב שבטים כתוב עליהם ששה על אבן זו וששה על אבן זו שנא' ששה משמותם על האבן האחת וגו' שניה כתולדותם ולא ראשונה כתולדותם מפני שיהודה מוקדם וחמשים אותיות היו כ\\\"ה על אבן זו וכ\\\"ה על אבן זו ר' חנינא בן גמליאל אומר לא כדרך שחלוקין בחומש הפקודים חלוקין באבני האפוד אלא כדרך שחלוקים בחומש שני כיצד בני לאה כסדרן בני רחל א' מכאן וא' מכאן בני השפחות באמצע ומה אני מקיים כתולדותם כשמותם שקרא להם אביהם ולא כשמות שקרא להם משה ראובן ולא ראובני שמעון ולא שמעוני ופי' רש\\\"י כסדר לידתן ששה האחרונים כסדרן גד אשר יששכר זבולן יוסף בנימין זהו סדר לידתן וששה ראשונים נכתבו בה יהודה ראובן שמעון לוי דן נפתלי כסדר לידתן חוץ מיהודה וכו'. לא כדרך שחלוקין בחומש הפקודים הוא ספר וידבר שנסדרו בראשו אלה שמות האנשים אשר יעמדו וגו' ובחומש שני בתחלת ואלה שמות ראובן שמעון לוי ויהודה יששכר זבולן באחת מהן בשנית בנימין דן ונפתלי גד ואשר ויוסף. א\\\"כ מה ת\\\"ל כתולדותם הואיל ולא כסדר תולדותם נסדרו עכ\\\"ל. ותמהני על רבינו שכתב שהאבן שכתוב ראובן על כתפו הימנית וכו' שנראה שסובר שהיה כתוב על אבן זו ראובן לוי יששכר נפתלי גד יהוסף ועל השניה היה כתוב שמעון יהודה זבולן דן אשר בנימן וכן כתב בפירוש המשנה פרק בא לו שאינו מכוון עם מה שאמרו בגמרא שם לא אליבא דת\\\"ק דמקדים יהודה ורבינו לא הקדימו ועוד דלת\\\"ק דן ונפתלי גד ואשר קודמין ליששכר וזבולן שזהו סדר תולדותם ואילו רבינו הקדים יששכר וזבולן לדן ונפתלי גד ואשר וגם לא אליביה דרבי חנינא בן גמליאל דלדידיה בנימין בראש השנית ובני השפחות בתריה ובסוף יוסף כדפרש\\\"י ואילו רבינו כותב יוסף בסוף הראשונה ובנימין בסוף השניה. וי\\\"ל שרבינו היה מפרש דברי רבי חנינא בן גמליאל על פי מה שכתבו הוא ז\\\"ל דבאמצע לאו באמצע בני רחל קאמר אלא בין בני לאה ובני רחל ואע\\\"ג דרבי חנינא בן גמליאל הקדים בני רחל לבני השפחות לאו למימרא שיכתבו מוקדמים אלא שיהיו בני גבירה זו מצד זה ובני גבירה זו מצד זה ובני השפחות באמצע לשתי הגבירות ופסק כמותו משום דמסתבר טעמיה.\",1,0],[8,360,9,9,\"ומה שכתב וכותבין שם יוסף יהוסף כן כתב גם בפירוש המשנה בפרק בא לו ותמהני עליו שהרי בפרק אלו נאמרים תניא נ' אותיות היו כ\\\"ה על אבן זו וכ\\\"ה על אבן זו ומקשה נ' נכי חדא הויין אמר רבי יצחק יוסף הוסיפו לו אות אחת מתקיף לה רב נחמן בר יצחק כתולדותם בעינן ופירש\\\"י כשמות שקרא להם אביהם בעינן אלא כל התורה כולה בנימן והכא בנימין שלם כתיב כדכתיב ואביו קרא לו בנימין ומאחר דרבי יצחק דאמר שהיה כתוב יהוסף אידחי קשה היאך פסק רבינו כמותו ועוד קשה למה לא כתב שבנימין היה מלא כדאסיקנא וי\\\"ל שרבינו מפרש דלא אקשי כתולדותם בעינן אלא אליבא דת\\\"ק אבל לרבי חנינא בן גמליאל לא דריש כתולדותם אלא לענין דלא לכתוב ראובני שמעוני.\",2,0],[8,360,9,9,\"ומה שכתב והאבן שכתוב בה ראובן על כתפו הימנית וכו' נראה דהיינו מדאמרינן בירושלמי פרק אלו נאמרין הראשונים נכתבים מימינו של כהן גדול משמאלו של קורא והאחרונים נכתבים משמאלו של כהן גדול מימינו של קורא:\",3,0],[8,360,9,9,\"ועושה בכל כתף וכו'. מפורש במקראות:\",4,0],[8,360,9,10,\"וכל המזיח חשן מעל האפוד ומפרק חיבורן דרך קלקול לוקה. בפרק בא לו (יומא דף ע״ב):\",1,0],[8,360,9,11,\"וחשב האפוד קשור על לבו. כתב הראב\\\"ד א\\\"א הפליג לעלות ואינו אלא למטה מטיבורו עכ\\\"ל. ואני אומר שרבינו בפרק שאחר זה נתן טעם לדבריו:\",1,0],[8,360,10,1,\"כיצד סדר לבישת הבגדים לובש המכנסים תחלה וכו'. בפ\\\"ב דיומא (דף כ\\\"ה) מנין שלא יהא דבר קודם למכנסים ת\\\"ך ומכנסי בד יהיו על בשרו:\",1,0],[8,360,10,2,\"ולא יחגרו ביזע במקום שמזיעין. בפרק שני דזבחים (דף י\\\"ט):\",1,0],[8,360,10,3,\"ושערו היה נראה בין ציץ למצנפת כו'. בפרק ב' דזבחים שם. ודע דתניא בסוף פרק ראשית הגז (חולין דף קל״ח) כיפה של צמר היתה מונחת בראש כהן גדול ועליה ציץ נתון לקיים מה שנאמר ושמת אותו על פתיל תכלת ולא ידעתי למה השמיטו רבינו:\",1,0],[8,360,10,4,\"וכהן גדול ששימש בפחות משמונה בגדים אלו וכו'. בסוף פרק הנשרפין (סנהדרין דף פ\\\"ג:) גבי חייבי מיתה מני מחוסר בגדים ומייתי לה מדכתיב וחגרת אותם אבנט וכו' אין בגדיהם עליהם אין כהונתם עליהם וה\\\"ל זרים ואמר מר זר ששימש במיתה ובריש פרק ב' דזבחים (דף טו:) מייתי לה נמי להא דתנן התם מחוסר בגדים עבודתו פסולה ופירש\\\"י מחוסר בגדים כהן גדול ששימש בפחות משמנה וכהן הדיוט בפחות מארבעה והכי משמע התם בגמרא:\",1,0],[8,360,10,5,\"ומה שכתב כשם שהמחוסר בגדים חייב מיתה ופוסל העבודה וכו'. ברייתא בריש פרק ב' דזבחים (דף י\\\"ח) לבש שני מכנסים שני אבנטים חסר אחת יותר אחת וכו' ועבד עבודתו פסולה.\",1,0],[8,360,10,5,\"ומה שכתב או כהן הדיוט שלבש בגדי כהן גדול ועבד וכו'. שם אכתי מהכא נפקא מהתם נפקא ונתנו בני אהרן הכהן הכהן בכיהונו כהן גדול שלבש בגדי כהן הדיוט ועבד עבודתו פסולה אי מהתם הוה אמינא ה\\\"מ עבודה דמעכבא כפרה וכו' ואכתי מהכא נפקא מהתם נפקא וערכו בני אהרן הכהנים הכהנים בכיהונם מכאן לכהן הדיוט שלבש בגדי כהן גדול ועבד עבודתו פסולה אי מהתם ה\\\"א ה\\\"מ חיסור אבל ייתור לא קמ\\\"ל:\",2,0],[8,360,10,6,\"נאמר בבגדי כהונה על בשרו ולבשם וכו'. בפרק שני דזבחים (דף י\\\"ט).\",1,0],[8,360,10,6,\"ומה שכתב לפיכך אין הכהן יכול לעבוד בתפילין של יד וכו'. שם אמר ר' אמי [למוד ערוך הוא בידינו] תפילין חוצצות וכו' והתניא [אם הניחן] אינם חוצצות ל\\\"ק הא דיד הא דראש הא דיד דכתיב ילבש על בשרו שלא יהא דבר חוצץ בינו לבשרו דראש נמי כתיב ושמת המצנפת על ראשו תנא שערו היה נראה בין ציץ למצנפת ששם מניח תפילין ופירש\\\"י הילכך ליכא חציצה ותנא דאיצטריך לאשמועינן אם הניחן אינם חוצצות משום יתור בגדים הוא דאיצטריך לאשמועינן דלאו בגד הוא עכ\\\"ל. ונראה שלזה כיון רבינו במה שהאריך וכתב ואם רצה להניחן בשעת העבודה מניח:\",2,0],[8,360,10,7,\"וצריך להזהר בשעה שלובש וכו'. שם בעי רבא נכנסה לו רוח בבגדו מהו על בשרו בעינן והא ליכא או דילמא דרך לבישה בכך כינה מהו שתחוץ מתה לא תיבעי לך דודאי חייצא חיה מאי מי אמרינן כיון דאתא ואזלא רביתא היא ולא חייצא או דילמא כיון דקפיד עלה חייצא עפר מהו שיחוץ עפר ודאי חייץ אלא אבק עפר מהו בית השחי מהו שיחוץ על בשרו בעינן והא ליכא או דילמא דרך לבישה בכך הכניס ידו לתוך חיקו מהו גופו מי חייץ או לא נימא מהו שתחוץ נימא ודאי חייצא אלא נימא מדולדלת מהו בעי מר בר רב אשי יצא שערו בבגדו מהו שערו כגופו דמי או לאו כגופו דמי ופירש\\\"י נכנסה לו רוח בבגדו והבדילתו מבשרו בשעת עבודה. רביתא היא הרי היא כבשרו. כיון דקפיד עלה ברצונו לא תהא כבשרו. אבק עפר דק ואינו מרגיש בו. בית השחי מהו שיחוץ כגון בית יד של חלוקין שהוא רחב ואינו נוגע בבית השחי מהו שיחוץ וצריך שיהיו בתי זרועותיו דחוקים ונוגעים בבשר גופו. ידו שהיא גופו. נימא משמע דאתיא מעלמא. נימא מדולדלת מן הבגד מגורדין ותחובה בו קצת אלא שנתקה מעיקרה. יצא שערו מראשו למטה עד שנכנס בין כתנתו לבשרו מהו את\\\"ל ידו לא חייצא שערו מאי עכ\\\"ל. ולא איפשיטו כל הני בעיי ולפיכך פסק בהם רבינו דלכתחלה להזהר ומיהו בדיעבד אין לנו כח לפסול העבודה בכך ולומר יביא קרבן אחר דאיכא למיחש שמביא חולין בעזרה ואין לומר יביא קרבן אחר ויתנה דמאחר שיש קרבנות דלא שייך בהם להתנות דהיינו חטאות ואשמות וקרבנות הצבור לא מפליג בינייהו ונראה שרבינו לא היה גורס בית השחי מהו וביצא שערו בבגדו נראה שמפרש דלא כפירוש רש\\\"י:\",1,0],[8,360,10,8,\"כרך על בשרו בגד שלא במקום בגדים. בפ\\\"ב דזבחים (דף י\\\"ט) ופ\\\"י דעירובין (דף ק\\\"ג) אהא דתנן כהן שלקה באצבעו כורך עליה גמי במקדש אמר רבי יהודה ברי' דרבי חייא לא שאנו אלא גמי אבל צלצול קטן הוי ייתור בגדים ורבי יוחנן אמר לא אמרו ייתור בגדים אלא במקום בגדים אבל שלא במקום בגדים לא הוי ייתור ותיפוק לי' משום חציצה בשמאל אי נמי שלא במקום עבודה ופליגא דרבא דאמר רבא וכו' במקום בגדים אפילו נימא אחת חוצצת שלא במקום בגדים ג' על ג' חוצצות פחות מכאן אינן חוצצות אדרבי יוחנן ודאי פליגא אדרבי יהודה ברי' דרבי חייא מי לימא דפליגא שאני צלצול קטן דחשוב ע\\\"כ כלישנא בתרא ופירש רש\\\"י צלצול קטן אזור קטן שלש על שלש חוצצות כלומר הוי ייתור בגדים ואיידי דנקט במקום בגדים לישנא דחציצה דשייכא בה נקט נמי במסקנא לישנא דחציצה. ודאי פליגא דהא אמר לא הוי ייתור בגדים ואפילו ג' על ג' במשמע. מי לימא דפליגא דאמר צלצול קטן חוצץ ורבא אמר פחות מג' אינו חוצץ. דחשוב לפי שעשוי לנוי והוי בגד עכ\\\"ל. ופסק רבינו כרבא דבתרא הוא:\",1,0],[8,360,10,9,\"כהן שלקה באצבעו וכו'. משנה בפרק י' דעירובין.\",1,0],[8,360,10,9,\"ומה שכתב או בגד שאין בו שלש על שלש ועובד. נתבאר בסמוך.\",2,0],[8,360,10,9,\"ומה שכתב ואם נתכוון להוציא דם אסור. שם במשנה אם להוציא דם כאן וכאן אסור ופרש\\\"י אם להוציא דם שמהדקה בגמי כדי להוציא דם וכו' אסור שאין זה צורך עבודה ועוד דה\\\"ל חובל.\",3,0],[8,360,10,9,\"ומה שכתב והוא שלא יחוץ הגמי או הבגד בין בשרו לכלי בשעת העבודה כתוב בהשגות א\\\"א דבריו סותרים זה את זה וכו':\",4,0],[8,360,10,9,\"ואני אומר נראה שהראב\\\"ד מפרש דהא דאמר רבא שלא במקום בגדים שלש על שלש חוצצות פחות משלש על שלש אינן חוצצות דחוצצות ואינן חוצצות לענין חציצה בין יד לכלי איתמר ומש\\\"ה השיג וכתב שדבריו סותרים את דבריו אבל לפי האמת דעת רבינו כפירוש רש\\\"י דחוצצות ואינן חוצצות לא לענין חציצה איתמר אלא לענין ייתור בגדים והריטב\\\"א הכריע כפרש\\\"י דאי חציצה כפשטה למה חלקו בין במקום בגדים לשלא במקום בגדים והא כולה עבודה בגופו של כהן בעינן וראוי שיחוץ אפילו נימא אחת בכל מקום ועוד דאם איתא דלהדיא אמר רב חסדא פחות מג' אינן חוצצות היכי אקשי לעיל להדיא ותיפוק לי' משום חציצה דמשמע דמילתא דפשיטא היא דאפילו גמי וצלצול קטן חוצצין והא רבא ורב חסדא פליגי לפי שיטה זו ותו כשתירץ בשמאל אי נמי בימין ושלא במקום בגדים אמאי לא אמר דכרבא אמר רב חסדא ס\\\"ל:\",5,0],[8,360,10,10,\"עשו בבית שני אורים וכו'. הכי משמע מדאמרינן בפ\\\"ק דקידושין (דף ל\\\"א) דבימי בית שני בקשו חכמים אבנים לאפוד וז\\\"ל סמ\\\"ג בבית שני היה החשן שא\\\"א להיות כ\\\"ג מחוסר בגדים אבל אותו השם לא היה שם.\",1,0],[8,360,10,10,\"ומ״ש וכל כהן שאינו מדבר ברוח הקדש ואין השכינה שורה עליו אין נשאלין. בריייתא בס״פ בא לו (יומא דף עג:) ומייתי לה מקרא:\",2,0],[8,360,10,11,\"וכיצד שואלין עומד וכו'. בסוף פרק בא לו (יומא ע״ג) ת״ר כיצד שואלין השואל פניו כלפי נשאל והנשאל פניו כלפי שכינה ופרש״י פניו כלפי נשאל כלפי כהן. כלפי שכינה כלפי אורים ותומים ושם המפורש שבתוך החשן עכ״ל. ורבינו לא בחר בפירוש רש״י משום דאם כן מאי והנשאל פניו כלפי שכינה דקתני כיון דלאורים ותומים קרי שכינה הרי האורים ותומים היו על לבו ולא שייך למיתני פניו כלפי שכינה דמשמע דאפשר שלא יהיו פניו כלפי החשן ועוד שאם השואל פניו כלפי הנשאל קאמר הל״ל השואל פניו כלפי שכינה מאחר דלאורים ותומים קרי שכינה ולפיכך פירש דלארון קרי שכינה וע״פ זה הוכרח לפרש דהשואל פניו כלפי נשאל דקתני שפניו פונות למקום שפונים פני הנשאל נמצא שהשואל לאחורי נשאל דאילו כלפי פני נשאל הל״ל השואל והנשאל פניהם כלפי שכינה:\",1,0],[8,360,10,11,\"ואינו שואל בקול רם וכו'. שם.\",2,0],[8,360,10,11,\"ומ\\\"ש ומיד רוח הקדש לובש את הכהן וכו' באותיות שבולטות מן החשן כנגד פניו וכו'. שם רבי יוחנן אמר בולטות ר\\\"ל אמר מצטרפות ופרש\\\"י האותיות בולטות כגון עי\\\"ן משמעון למ\\\"ד מלוי ה\\\"א מיהודה לומר עלה וכל אחת אינה זזה ממקומה אלא בולטת במקומה והוא מצרפן:\",3,0],[8,360,10,12,\"ומ\\\"ש אין שואלין על שני דברים כאחד ואם שאל משיבין על הראשון בלבד. ברייתא שם:\",1,0],[8,360,10,12,\"ואין נשאלין בהם להדיוט וכו' עד אלו ב\\\"ד הגדול.משנה וגמרא שם:\",2,0],[8,360,10,13,\"זה שאתה מוצא בדברי נביאים שהכהנים היו חוגרים אפוד בד וכו'. כתב כן כי היכי דלא תיקשי לן היאך כתוב גבי אחימלך בן אחיטוב פ\\\"ה כהנים חגורים אפוד בד:\",1,0],[8,360,10,13,\"סליק להו הלכות כלי המקדש:\",2,0],[8,361,1,1,\"כל כהן הכשר לעבודה וכו'. מ\\\"ש הכשר לעבודה בסיפרא אתה ובניך אתך מה אתה כשר אף בניך כשרים יצאו חללים ובעלי מומין.\",1,0],[8,361,1,1,\"ומ\\\"ש שאסור לו להכנס מן המזבח ולפנים. אף ע\\\"ג דבקרא כתיב באהל מועד בת\\\"כ מייתי מקרא דה\\\"ה למן המזבח ולפנים וכתבתי ברייתא זו בסוף פרק זה.\",2,0],[8,361,1,1,\"ומ\\\"ש שעבודתו פסולה. בפ' כ\\\"ג (סנהדרין כ\\\"ב) אמרינן דשתויי יין מחלי עבודה ופירש\\\"י דכתיב יין ושכר אל תשת וגו' וסמיך ליה ולהבדיל בין הקדש ובין החול משמע בין עבודה קדושה לעבודה מחוללת ומייתי לה ברפ\\\"ב דזבחים (דף י\\\"ז ע\\\"ב).\",3,0],[8,361,1,1,\"ומ\\\"ש וחייב מיתה בידי שמים. מבואר בכתוב ומשמע מדברי רבינו דאסור להכנס מהמזבח ולפנים אע\\\"פ שלא עבד אבל אינו חייב מיתה אא\\\"כ עבד:\",4,0],[8,361,1,1,\"ומ\\\"ש והוא ששתה רביעית יין חי בבת אחת מיין שעברו עליו מ' יום אבל אם שתה פחות מרביעית יין וכו'. בפ\\\"ג דכריתות (דף י\\\"ג ע\\\"ב) ת\\\"ר יין ושכר אל תשת יכול אפילו כל שהוא אפילו מגתו ת\\\"ל ושכר אין אסור אלא כדי לשכר וכמה כדי לשכר רביעית יין בן מ' יום אם כן מה ת\\\"ל יין לומר לך שמוזהרים עליו כל שהו ומוזהרים עליו מגתו רבי יהודה אומר יין אין לי אלא יין שאר משכרים מנין ת\\\"ל ושכר א\\\"כ מה ת\\\"ל יין על היין במיתה ועל שאר משקין באזהרה ר' אליעזר אומר יין אל תשת ושכר אל תשתהו כדרך שכרותו הא אם הפסיק בו או שנתן לתוכו מים כל שהוא פטור במאי פליגי ת\\\"ק סבר גמרי' שכר שכר מנזיר ור' יהודה לא יליף שכר שכר מנזיר ורבי אליעזר סבר מאי שכר מידי דהוא משכר כמאן אזלא הא דתניא אכל דבלה קעילית ושתה דבש או חלב ונכנס למקדש ושימש לוקה כמאן כר' יהודה אמר רב יהודה בר אחותאי הלכה כרבי אליעזר. ופירש רש\\\"י מוזהרים עליו בכל שהוא ומגתו אבל אינו במיתה עד שישתה רביעית בן מ' יום וזהו שכתב רבינו אבל אם שתה פחות מרביעית יין וכו' פטור ואינו מחלל עבודה כלומר איסורא מיהא איכא. ומ\\\"מ יש לתמוה כיון שמוזהרים על כל שהוא ועל יין מגתו למה לא כתב שלוקים עליהם. וי\\\"ל דעל כל שהוא פשיטא שאין לוקין כשם שאין לוקין על כל שאר איסורין שבתורה בכל שהוא ומדלא לקי על יין כל שהו ה\\\"ה דלא לקי על יין מגתו דתרוייהו חד טעמא להו שאינם משכרים:\",5,0],[8,361,1,1,\"שתה יתר מרביעית יין וכו'. שם אמרינן דרב אשי לא בעא לאורויי משום שכרות וא\\\"ל רב אחא והא אמר רב הלכה כר' אליעזר (דאמר יין אל תשת ושכר אל תשתהו דרך שכרותו הא אם הפסיק בה או שנתן לתוכו מים כל שהוא פטור) ומר הא קרמי ביה מיא א\\\"ל הא ל\\\"ק ברביעית הא ביותר מרביעית:\",6,0],[8,361,1,1,\"ועל מ\\\"ש רבינו ופוסל את העבודה. כתוב בהשגות א\\\"א לא מחוור מן הגמרא וכו' טעמו משום דכיון דלא אשכחן לגמרא דמפליג בין רביעית ליותר מרביעית אלא בענין הוראה כמו שכתבתי בסמוך מהי תיתי לן לחייב מיתה ולפסול עבודה וטעם רבינו דאע\\\"ג דעל ענין הוראה הוא נאמר חילוק זה מ\\\"מ משמע דר' אליעזר אף לענין עבודה פטר בהפסיק בו או נתן לתוכו מים ומאחר שלמדנו שאין דבריו אמורים אלא ברביעית ממילא משמע דיותר מרביעית כדקאי קאי לחיוב מיתה ולפסול עבודה:\",7,0],[8,361,1,2,\"היה שכור משאר משקים וכו'. שם בברייתא שכתבתי בסמוך רבי יהודה אומר יין אין לי אלא יין שאר משכרים מנין ת\\\"ל ושכר אם כן מה תלמוד לומר יין על היין במיתה ועל שאר משקין באזהרה ומשמע לרבינו דהלכה כרבי יהודה מדאמרינן התם כמאן אזלא הא דתניא אכל דבילה קעילית ושתה דבש או חלב ונכנס למקדש ושימש לוקה כמאן כרבי יהודה ואע\\\"ג דבס\\\"פ על אלו מומין (דף מ\\\"ה:) אמרינן דמתניתין דהתם דלא כרבי יהודה הא דקאמר גמרא בדוכתא כמאן אזלא הא דתניא וכו' כרבי יהודה עדיף כנ\\\"ל לדחוק לדעת רבינו ובספר המצות לרבינו כתוב דברייתא דסיפרא כרבי יהודה ואינו הכרע דסתם סיפרא רבי יהודה וכן השיגו הרמב\\\"ן. ועדיין יש לתמוה עליו דהא אמרינן בגמרא במאי פליגי ת\\\"ק ורבי יהודה ת\\\"ק סבר גמרינן שכר שכר מנזיר ומש\\\"ה סבר שלא הזהירה תורה אלא על היין ולא על שאר משכרים ורבי יהודה לא יליף שכר מנזיר וכיון שרבינו פסק בתחלת הפרק לומר דאיכא איסורא בפחות מרביעית וביין מגתו כתנא קמא היאך פסק כאן כרבי יהודה והוי כמזכה שטרא לבי תרי ויש לתמוה למה לא השיגו הראב\\\"ד ואפשר לומר שאע\\\"פ שרבינו סובר דהלכה כרבי יהודה מ\\\"מ נראה לו לחוש לדברי התנא קמא לאסור כל שהוא ויין מגתו איסורא בעלמא ואין לדחוק ולומר דפטור דקתני רבינו גבי פחות מרביעית ויין מגתו פטור ומותר קאמר דאם כן היכי מסיים בה ואינו מחלל עבודה פשיטא וע\\\"ק דמשמע דרבי אליעזר לא דריש ושכר אלא לדרך שכרותו לא לרבות שאר משכרים כרבי יהודה וכיון דאיפסיקא הלכתא בגמרא כרבי אליעזר וכן פסק רבינו היאך פסק כרבי יהודה ואפשר לומר שרבינו מפרש דרבי אליעזר לא פליג ארבי יהודה דודאי משמע ליה דשכר אתא לרבות שאר משכרים אלא דמוסיף עליה לומר דכיון דבמשכר תלה רחמנא ממילא משמע דלא אסר יין אלא דרך שכרותו ואפשר עוד לומר דאף את\\\"ק לא פליג רבי אליעזר דכיון דאמשכר קפיד רחמנא וריבה שאר משכרים מיניה נשמע דביין לא אסר אלא כדי לשכר דהיינו רביעית ויין בן ארבעים יום והשתא אתי שפיר דפסק רבינו כתנא קמא וכדברי ר' יהודה משום דאיפסיקא הלכתא כרבי אליעזר ור\\\"א ס\\\"ל כר\\\"י וכת\\\"ק ואפשר דמש\\\"ה אמרינן בגמרא דקרי רב עליה דר\\\"א טוביינא דחכימי משום דמשכר משמע ליה כל תלת מילי דידיה ודרבי יהודה ות\\\"ק. אח\\\"כ מצאתי בתשובות הרשב\\\"א סי' שס\\\"ג שנשאל איך הלך רבינו בשיטת רבי יהודה ובגמרא כריתות פרק אמרו לו גרסינן כמאן אזלא הא דתניא אכל דבילה קעילית ושתה דבש או חלב ונכנס למקדש ושימש לוקה ארבעים כמאן כרבי יהודה והתם איפסיקא הלכתא כרבי אליעזר [וקרי רב עליה טוביינא דחכימי] ורבי אליעזר כיון דאפקיה לשכר דרך שכרותו שאר משכרין לית ליה ואפילו נפרש [כמאן] כרבי יהודה דאילו לר\\\"א מחמרינן טפי ומחייב מיתה בשאר משכרין וכו' מ\\\"מ יש להשיג עליו [שכתב] על היין במיתה ועבודתו מתחללת וכו' ושיטה זו כרבי יהודה אזלא וכו' ושמא דעת הרמב\\\"ם לפרש כמאן כר\\\"י ולאפוקי מדת\\\"ק אתי דכיון דיליף שכר מנזיר א\\\"כ שאר משכרין לא כתיבי כלל לא למיתה ולא לאזהרה אבל לא אתי לאפוקי מדרבי אליעזר דכיון דברייתא דר\\\"א לא יליף שכר מנזיר ודריש שכר כדי שכרותו שמא כל המשכרין כדי שכרותן הוו באזהרה. עכ\\\"ל השאלה:\",1,0],[8,361,1,2,\"והשיב נראה שהרמב\\\"ם תפס לו דרך אחרת באותה הלכה וכו' והדין עמו דכשתמצא לומר דר\\\"א לא יליף שכר מנזיר א\\\"כ [שכר] איצטריך לשאר המשכרין דכל היכא דאיכא לאוקמי בשאר המשכרין כפשוטו לא דרשינן ליה ליין ולראוי לשכר וכו' גם לפרש כמאן אזלא הא דתניא כמאן כר\\\"י לאפוקי מדת\\\"ק בלחוד ולא מדר\\\"א אין נ\\\"ל שיטת הגמרא כן דכיון שהזכיר מחלוקתן של ת\\\"ק ורבי יהודה ורבי אליעזר ועלה קאמר כמאן אזלא הא דתניא כמאן כרבי יהודה דוקא קאמר ונראה לי שכך הוא מפרשה יין אל תשת [יכול] אפילו כל שהוא ואפילו יין מגתו דיין אפי' כל שהוא במשמע ואפילו מגתו תלמוד לומר ושכר אין אסור אלא כדי לשכר כלומר אין איסור שנאמר בו דהיינו למיתה אלא כדי לשכר כלומר שיעור הראוי לשכר דהיינו רביעית ושיהיה ממשו ראוי לשכר דהיינו שעברו עליו ארבעים יום וכל ששתה ממנו כדי רביעית אפי' הפסיק בו ואפילו נתן לתוכו מים חייב [שהרי שתה] שיעור הראוי לשכר מיין שממשו ראוי לשכר תוך שיעור שתיה דהיינו תוך שיעור אכילת פרס אבל שאר המשכרים לעולם לא דילפינן שכר מנזיר ומיהו כיון דילפינן שכר מנזיר תו לא איצטריך יין דמיניה משמע יין ומשמע נמי שיש בו כדי לשכר דלהכי אפקיה בלשון שכר ולא אמר יין בהדיא אלא אם אינו ענין לכדי לשכר דהא משכר נפקא יין כדי לשכר תנהו ענין ליין שאינו כדי לשכר ולאזהרה דאי כולהו אפי' למיתה לכתוב יין ולא איצטריך שכר ורבי יהודה סבר שכר כמשמעו לכל המשכרין ובין יין בין שאר משכרים במשמע דלא ילפינן שכר מנזיר ושכר דאיצטריך לשאר משכרין לא דרשינן מיניה כדי לשכר אלא ששתה מהם ואפילו פחות מרביעית חייב וכל שכן אם שתה רביעית אע\\\"פ שהפסיק בו או שנתן לתוכו מים דבדרך שכרותו ובכדי שכרות לא קפדינן אלא במינים המשכרים ותדע לך דהא לרבנן אי לאו דכתיב שכר דמיניה דריש כדי לשכר הוו אמרי יין אפי' כל שהוא והילכך רבי יהודה דאיצטריך ליה שכר לשאר המשכרין יין או שכר דכתב רחמנא אפילו כל שהוא ואפי' מגתו משמע ולמה נאמר יין לחלק יין למיתה ושאר משכרים לאזהרה ורבי אליעזר סבר יין אל תשת שכר אל תשת שלא תשתהו דרך שכרותו. ורבי אליעזר לא יליף שכר מנזיר ויין לחלק כרבי יהודה אלא דסבירא ליה כרבנן בכדי לשכר ועדיפא מדרבנן דבעינן ראוי לשכר בשעת שתייה ממש שישתנו דרך שכרותו שלא יפסיק בו ושלא יתן לתוכו מים. וטעמא דידיה דכל מקום שנאמר שכר אחד מכל המשכרין כדי לשכר קאמר ומדכתב הכא אל תשת כדי לשכר בשעת שתייתו ממש וכל שהפסיק בו או שנתן לתוכו מים כל שהוא ולא שתה ממנו אלא רביעית אינו ראוי לשכר בשעת שתייה ממש ותדע לך דר\\\"א אפי' שאר המשכרין אית ליה כרבי יהודה מדקאמר יין אל תשת שכר אל תשת הזכיר אל תשת גבי יין ואל תשת גבי שכר ואילו לא בא ר\\\"א לומר אלא שלא ישתה יין דרך שכרותו ויליף שכר מנזיר הכין הוה ליה למימר יין אל תשת שכר שלא תשתנו דרך שכרותו. ועוד דמדקאמרי בין ת\\\"ק בין רבי יהודה א\\\"כ יין למה לי שמע מינה דאינהו נמי בהא כר\\\"י דלעיל מיניה ס\\\"ל ולא בא לחלוק עליו בחילוק המינין דיין ודאי לחלק אלא בהא בלחוד הוא דפליג עליה בשלא תשתנו דרך שכרותו דמאי שכר הוא דמשכר והיינו נמי דאמרינן במאי פליגי ת\\\"ק סבר ילפינן שכר מנזיר ור\\\"י סבר לא ילפינן שכר מנזיר ור\\\"א מאי שכר והוא דמשכר ולא מפרשינן מאי קסבר אי יליף שכר מנזיר כרבנן או לא יליף כר\\\"י אלא מאי שכר והוא דמשכר דאלמא אדרבי יהודה דסמיך קאי וא\\\"ל בשאר המשכרין מודינא לך ויין לחלק אלא בשעורן דבשתייתן פליגנא דמאי שכר והוא דמשכר וכיון דכתיב אל תשת בשעת שתייה [ממש] קאמר והיינו דאוקימנא ברייתא דאכל דבילה קעילית כרבי יהודה דוקא דההיא ודאי מפקא מדת\\\"ק דלדידהו שאר המשכרין אינן אפי' באזהרה ומפקא מדר\\\"א דלדידיה שיעור הראוי לשכר בעינן ותנא דההיא ברייתא מדלא יהיב שיעורא שמע מינה אפילו בפחות מרביעית קאמר. והילכך כיון דאיפסיקא הלכתא כר\\\"א אינו במיתה ולא באזהרה אפילו על היין אלא אם כן שתה ממנו רביעית מיין שעברו עליו ארבעים יום ורביעית נמי הוא שלא יפסיק בו ושלא יתן לתוכו מים כלל ושאר המשכרין לאזהרה עד שישתה מהן כדי לשכר וכן פסק הרב רבינו משה זכרונו לברכה. ונמצאו דבריו עולים כהוגן לפי פירושנו זה.\",2,0],[8,361,1,2,\"ואם תאמר א\\\"כ בריש פ\\\"ק דנזיר דאמרינן שכר דכתב רחמנא גבי נזיר למילף מיניה שכר דמקדש [ולאפוקי מדרבי יהודה דתניא אכל דבילה קעילית וכו' אמאי לא קאמר] לאפוקי מדרבי יהודה ומדרבי אליעזר יש לומר דהתם לאו כרוכלא חשיב ואזיל אלא מכל מקום מדרבי יהודה וממאן דס\\\"ל כוותיה קאמר. ועוד משום דר\\\"י אמרה בהדיא קאמר הכין. ולכשתמצא לומר דר\\\"א כוותיה ס\\\"ל מפקא מיניה דר\\\"א. ונ\\\"ל עוד שהזקיקו לרב לפרש כן כדי שלא להוציא סתם מתניתין דנזיר לבר מהילכתא דלכאורה סתם מתניתין דפ\\\"ק דנזיר כרבי יהודה דלא יליף שכר דמקדש מנזיר דתנן התם הריני נזיר מן החרצנים הרי זה נזיר וכל דקדוקי נזיר עליו ואמרינן עלה בגמרא מתניתין דלא כרבי שמעון דאמר עד שיזיר מכולן. ואמרינן מ\\\"ט דר\\\"ש דאמר קרא מכל אשר יצא מגפן היין. ורבנן מאי טעמא דאמר קרא מיין ושכר יזיר. ור\\\"ש הא כתיב מיין ושכר ההוא לאסור יין מצוה כיין הרשות. ורבנן הא מיבעיא להו לאסור יין מצוה כיין הרשות א\\\"כ לימא קרא מיין מיין ור\\\"ש היינו טעמיה דכתב שכר לאלופי שכר שכר למקדש דכתיב יין ושכר אל תשת מה נזיר יין הוא דמיתסר שאר משכרין לא אף גבי מקדש נמי יין הוא דליתסר אבל שאר המשכרין לא לאפוקי מדר\\\"י דתניא ר\\\"י אומר אכל דבילה קעילית ושתה דבש או חלב וכו' ומדלא קא בעי תו ורבנן הא מיבעי לאלופי אמקדש כדבעא בכל הנך דלעיל משמע לכאורה דרבנן לא איצטריך להכין דהשתא נמי לא ילפינן דשכר דמקדש אפילו שאר המשכרין קאמר. וכיון דסתם מתניתין כר\\\"י שמע מינה הלכתא כוותיה. והאי דכריתות דאיפסיקא הלכתא כר\\\"א לא מפקא מינה בעיקר משכרין דהא איכא לפרושה כדפרישית. ואלא מיהו למאי דפרישית דר\\\"י אפילו בכל שהוא מחייב איכא למידק מהא דאמרינן בנזיר פרק ג' מינין אמר ר\\\"א עשר רביעיות ומנקט רב ששת חמש חיוורתא וחמש סומקאתא נזיר ועושה פסח שהורו במקדש ומתו. ומקדש היינו שתה רביעית יין ושימש במקדש ואקשינן התם ותו ליכא והא איכא מי רביעית נוטלין לידים לאחד ואפילו לשנים ופרקינן בפלוגתא לא קא מיירי כו' והא איכא כמה מים נותן לתוכן כל שהן ר\\\"י אומר ברביעית בפלוגתא לא קא מיירי אלמא כל הנך עשר ליכא מאן דפליג אפילו בחדא מינייהו ולפי מה שפירשתי הא איכא מקדש דפליג רבי יהודה ומחייב אפילו בפחות מרביעית ויש לי לומר דפלוגתא דר\\\"י לאו פלוגתא היא משום דכבר פסק רב הלכתא כר\\\"א ולפום כן לא חש לה ר\\\"א דעשר רביעיות דבתר רב הוה ודמיא לההיא דאמרינן בריש פ\\\"ק דיבמות גבי ליתני שש עשרה אמו אנוסת אביו פלוגתא דרבי יהודה ורבנן היא ובפלוגתא לא קא מיירי ואקשינן והא בית שמאי מתירין צרות לאחין ובית הלל אוסרין ופרקינן בית שמאי במקום בית הלל אינה משנה. ואי נמי איכא למימר דבפלוגתא דחיוורתא קאמר דלא מיירי אבל בסומקאתא איירי בפלוגתא דהא קא חשיב רביעית דם משני מתים דפליגי רבנן ואמרי דדוקא רביעית ממת אחד והא קא חשיב רביעית יין לנזיר דלרבי עקיבא בכזית ואמרו רבותינו הצרפתים זכרונם לברכה דחיוורתא הוא דקאמר דלא איירי בהו בפלוגתא אבל בסומקאתא איירי ואף אני אומר דרביעית יין דמקדש אע\\\"ג דפלוגתא היא לא חש לה ואיירי בה:\",3,0],[8,361,1,2,\"עוד יש לפרש לדעת הר\\\"מ ז\\\"ל דר\\\"י בפחות מרביעית לא מחייב דאין שתייה פחותה מרביעית ובמקדש אל תשת כתיב ואע\\\"ג דאמר ת\\\"ק יכול אפילו כל שהוא ואפי' יין מגתו. כל שהוא אינו עיקר אלא יכול יין מגתו הוא העיקר אבל כיון שסופנו לרבות כל שהוא ויין מגתו באזהרה נקט הכא בגררא יכול אפילו כל שהוא ואפילו יין מגתו. אי נמי יכול אפי' כל שהו דקאמר ת\\\"ק בדוקא קא אמר ולא כל שהוא ממש אלא כזית ומשום דאיהו יליף שכר דמקדש משכר דנזיר ושכר דנזיר למשנה אחרונה בכזית דיליף שתייה מאכילה בדין היה דנימא נמי דשכר דמקדש בכל שהוא דהיינו בכזית אלא דכיון דכתיב יין וכתיב שכר על כרחין שכר לכדי לשכר הוא דאתא. והא דקאמר יין יכול אפי' כל שהוא לאו למימרא דאי לא כתב רחמנא אלא יין הוה אמינא דאפילו כל שהוא דאדרבה למאי דפרישית משכר הוא דהוה ילפינן דמינה הוא דילפינן מנזיר אלא הכי קאמר יין ושכר יכול אפילו כל שהוא משום דילפינן מנזיר תלמוד לומר שכר כלומר כיון דכתיב יין וכתיב שכר על כרחין לכדי לשכר דאי לא כתב רחמנא אלא שכר הוה משמע אפי' יין כזית דילפינן שכר מנזיר ואפילו יין מגתו כנזיר ואי כתב נמי יין לחודיה הוה משמע יין רביעית ואפילו מגתו אבל השתא דכתיב יין ושכר ממילא שמעינן דשכר יין כדי לשכר קאמר ומ\\\"מ כיון דכתיב יין וכתיב שכר הוה ליה כמו שכתוב יין יין תרי זמני וההוא דאפקיה בלשון שכר ליין כדי לשכר ולמיתה ואידך לפחות מרביעית ואפילו מגתו ולאזהרה. וכל שהוא דפרישית דיש לו שיעור יש לנו הרבה כיוצא בו בגמרא וחד מינייהו בעירובין בפ' חלון ומגביהו מן הקרקע כל שהוא וכמה כל שהוא טפח ואחד בראשית הגז וכמה הן גוזזות כל שהוא וכמה כל שהוא וכו' אבל לר\\\"י דלא יליף שכר מנזיר וכתיב אל תשת אין שתייה פחותה מרביעית אבל איהו סבר דשאר משכרין נמי ברביעית ובהא פליג עליה רבי אלעזר דשאר המשכרין אין להם שיעור למעלה אלא עד שישתכר דלהכי אפקינהו רחמנא בלשון שכר וברייתא דקתני סתם שתה דבש או חלב ולא קתני ונשתכר ומשמע דאפי' לא נשתכר אלא ששתה מהם שיעור הידוע דהיינו רביעית ששיעורו ליין חייב היינו ר\\\"י ודלא כרבי אליעזר וכן יראה מדברי הר\\\"מ ז\\\"ל שכתב גבי יין והוא ששתה רביעית [יין] בבת אחת ובשאר המשכרין כתב היה שכור משאר המשכרין וכו' ואם נכנס ועבד והוא שכור דאלמא ביין לעולם ברביעית חי ובבת אחת ובשאר המשכרין עד שיהא שכור ממש ויש לו פנים עכ\\\"ל:\",4,0],[8,361,1,3,\"וכשם שאסור לכהן להכנס למקדש וכו'. בפרק שלישי דכריתות (דף י\\\"ג:) ופרק הדר (עירובין דף ס\\\"ד) ומשמע דאין חייבין מיתה על ההוראה והכי יליף לה בסיפרא.\",1,0],[8,361,1,3,\"ומ\\\"ש אפילו אכל תמרים וכו'. בפרק קמא דכתובות (דף י':) אמר רב אכל תמרים אל יורה.\",2,0],[8,361,1,3,\"ומ\\\"ש ואם הורה בדבר שהוא מפורש בתורה עד שידעוהו הצדוקים מותר כגון שהורה שהשרץ טמא וכו'. בפ\\\"ג דכריתות (דף י\\\"ג:).\",3,0],[8,361,1,4,\"ומ\\\"ש ומותר לשכור ללמד תורה וכו'. שם ת\\\"ר ולהבדיל בין הקדש ובין החול אלו דמים נערכים וכו' ביד משה זה הגמרא יכול אף המשנה ת\\\"ל ולהורות רבי יוסי ברבי יהודה אומר יכול אף הגמרא ת\\\"ל ולהורות אמר רב הלכה כרבי יוסי ברבי יהודה דהא רב לא מוקים אמורא [עליה] מיומא טבא לחבריה משום שכרות שאני רב דאורי מורי וניקום דלא לורי כל היכא דיתיב רב לא סגי ליה בלא הוראה ולדברי רבינו מבוארים בפירושו ורש\\\"י פירש בענין אחר:\",1,0],[8,361,1,5,\"שתה כדי רביעית בלבד וכו'. בפרק כהן גדול (סנהדרין דף כ״ב:) ובפרק הדר ובפ״ב דתעניות (דף י״ז:) אמר רב אחא דרך מיל ושינה כל שהוא מפיגין את היין ואתמר עלה ל״ש אלא ששתה כדי רביעית אבל יותר מכדי רביעית כל שכן דדרך טורדתו ושינה משכרתו:\",1,0],[8,361,1,5,\"ועל מ\\\"ש רבינו שתה כדי רביעית בלבד וכו' ומותר לעבוד. כתב הראב\\\"ד אף זה לא מחוור וכו'. וטעם רבינו דכיון דאמרינן דמותר להורות משום דלא הוי בכלל ושכר אל תשת ממילא משמע דמותר לעבוד והא דנקט רבי אליעזר פטור לאו דוקא אי נמי משום דבהפסיק בה דקתני בהדה נקט פטור דכיון דמכל מקום שתה רביעית יין חי אינו מותר לעבוד לא שייך למיתני בה אלא פטור אבל בהיה מים כל שהוא מותר נמי הוא והכי דייק לשון רבינו דהכא גבי מותר לעבוד נקט היה בה מים כל שהוא ולא נקט הפסיק בה. אבל הא קשיא לי שכתב לעיל שתה רביעית והפסיק בה או מזגה במים פטור ואינו מחלל עבודה וכאן כתב דרביעית אם היה בה מים כל שהוא מותר לעבוד ונראה לי דלעיל אגב אינך נקט למזגה במים דפטור ואינו מחלל עבודה והכא נקט להיה בה מים ואפקה מכלל הנך ואשמעינן דהאי לא בלבד שפטור ואינו מחלל עבודה אלא אף מותר לעבוד. ויותר נראה לי דלעיל היה רביעית שלם יין חי ולפיכך כשמזגו במים פטור אבל אסור אבל הכא שהיה פחות מרביעית יין חי והמים השלימוהו לרביעית מותר.\",2,0],[8,361,1,5,\"ומה שכתב באם שתה יותר מרביעית אפילו מזוג וכו'. כבר נתבאר בפרק זה שדין יותר מרביעית מזוג שוה לרביעית חי. ודקדק רבינו לכתוב שינה מעט כלומר דאילו שינה הרבה מפיגה את היין:\",3,0],[8,361,1,6,\"אנשי המשמר מותרים לשתות יין בלילות וכו'. משנה בפרק שני דתעניות (דף ט\\\"ו:) אנשי משמר מותרים לשתות יין בלילות אבל לא בימים ואנשי בית אב לא ביום ולא בלילה ובגמרא (דף י\\\"ז) תנו רבנן מפני מה אמרו אנשי משמר מותרים לשתות יין בלילות אבל לא בימים שמא תכבד העבודה על אנשי בית אב ויבאו ויסייעו להם ומפני מה אנשי בית אב לא ביום ולא בלילה מפני שהם עסוקין תמיד בעבודה וסובר רבינו שהטעם שמא ישתה בלילה וישכים לעבודתו ועדיין לא סר יינו מעליו וכתב עליו בהשגות אינו מן הטעם הזה אלא מפני שהקטרת אימורים כל הלילה עכ\\\"ל וכך הם דברי רש\\\"י ולדעת רבינו י\\\"ל דאי משום הקטרת אימורים היה אפשר לתקן שיקטירו אותם קודם שישתו:\",1,0],[8,361,1,7,\"כל כהן שידע מאי זה משמר הוא וכו'. שם.\",1,0],[8,361,1,7,\"ומה שכתב לא היה מכיר משמרתו ולא בית אבותיו וכו'. שם אינו מכיר משמרתו ומשמרת אבותיו ויודע שבתי אבותיו קבועים שם אסורים לשתות יין כל השנה רבי אומר אומר אני אסור לשתות יין לעולם אבל מה אעשה שתקנתו קלקלתו אמר אביי כמאן שתו האידנא כהני חמרא כרבי ופירש רש\\\"י רבי אומר אומר אני כהן אסור וכו' כלומר אי חיישינן לשמא יבנה יהא אסור לעולם אפי' המכיר משמרתו ומשמרת בית אבותיו דחיישינן שמא ישתנה סדר משמרות ושמא יעבדו כולם לחנוכת הבית בבת אחת ונמצא זה צריך לעבוד אבל מה אעשה שתקנתו קלקלתו דהרי כמה שנים שלא חזרה בירה וקלקלה זו תקנתו לשתות יין בהדיא ולשמא יבנה לא חיישינן עכ\\\"ל. ודברי הראב\\\"ד בהשגות כדברי רש\\\"י ולפיכך כתב הלכה כרבי וכו' ורבינו סובר שלא בא רבי לחלוק אלא על אינו מכיר משמרתו ומשמרת בית אב שלו אבל במכיר משמרתו ומשמרת בית אב שלו וכן במכיר משמרתו ואין מכיר משמרת בית אב שלו ליכא פלוגתא בין רבי לתנא קמא ובאינו מכיר משמרתו ומשמרת בית אב שלו אינו גורס ויודע שאבותיו קבועים שם דאי לא כן לא הו\\\"ל להשמיטו:\",2,0],[8,361,1,7,\"ועל מה שכתב רבינו שאינו יכול לעבוד עד שיקבע בבית אב שלו ובמשמרתו. כתב הראב\\\"ד כמה דבריו חלושים וקלושים וכו'. ואני אומר שכשיבנה בית המקדש אפילו אם יבנה בידי שמים לא בו ביום שיבנה יודיע המשמרות הראויות ושבתם ועוד שדעת רבינו שבלא בנין בית המקדש אפשר להקריב קרבנות כמו שכתב בספר ששי מהלכות בית הבחירה ועוד יש לומר דרבינו לא בא ללמד שכשיבנה בית המקדש אסור לו לשתות עד שיקבע אלא בא ליתן טעם למה מותר לשתות יין בזמן הזה והכי קאמר שאינו יכול לעבוד עד שיקבע בבית אב שלו ובמשמרתו וכיון שעכשיו אינו קבוע אינו ראוי לעבודה ולפיכך מותר ביין ולכשיבנה בית המקדש ויקבע אז יאסר ולא קודם:\",3,0],[8,361,1,8,\"כהן שגדל שערו וכו'. בס״פ הנשרפין (סנהדרין דף פ״ג.) ואם תאמר מה צורך להיקש זה הא מקרא משמע ראשיכם אל תפרעו ולא תמותו הא אם תפרעו תמותו יש לומר דקרא אפשר לפרשו לרשות דהכי קאמר אע״פ ששאר אבלים שלא קרעו ולא פרעו במיתה אינכם בכלל חיוב זה:\",1,0],[8,361,1,9,\"ומ״ש ואין פרועי ראש מחללים עבודה אע״פ שהוא במיתה עבודתו כשירה. מסקנא דגמרא בפ״ב דתענית (דף י״ז:) ובס״פ כה״ג (סנהדרין דף כ״ב:):\",1,0],[8,361,1,10,\"ומה שכתב כשם שאין הכהנים מוזהרין על היין כו'. שם בפרקים הנזכרים:\",1,0],[8,361,1,10,\"וכתב בהשגות א\\\"א ליתיה להאי כללא וכו'. ותירץ במגדל עוז דלאו בשעת ביאה קאמר אלא בזמן ביאה למעוטי בזמן הזה עכ\\\"ל. ואינו נראה שהרי בגמרא אמרו בזמן ביאה ורבינו שינה וכתב בשעת ביאה ולכן נ\\\"ל שרבינו מפרש דאפילו בזמן הבית כהן שאינו רגיל לעבוד הוי שלא בזמן ביאה כלומר שלא בשעת ביאה ומותר לו לגדל פרע וכן מבואר בדברי רבי' שכתב לפיכך כהן הדיוט העובד מגלח מל' יום לל' יום:\",2,0],[8,361,1,10,\"במה דברים אמורים בכהן הדיוט וכו'. בסוף הוריות (דף י\\\"א:):\",3,0],[8,361,1,11,\"כמה הוא גידול פרע שלשים יום כנזיר וכו' לפיכך כהן הדיוט וכו'. בס\\\"פ כה\\\"ג שם ובפ\\\"ב דתענית ודקדק רבינו לכתוב העובד לרמוז למה שנתבאר בסמוך לדעתו שאין אסורים לגדל פרע אלא בשעת ביאה למקדש:\",1,0],[8,361,1,12,\"ואנשי משמר אסורים לספר ולכבס בשבתן וכו'. משנה (דף ט\\\"ו:) וגמרא (דף י\\\"ז) בפ\\\"ב דתעניות ומסיים שם במשנה ובחמישי מותרים מפני כבוד השבת ואיני יודע מפני מה השמיטו רבינו:\",1,0],[8,361,1,13,\"מי ששלמה משמרתו בתוך הרגל כו'. ברייתא בפרק אלו מגלחין (מועד קטן דף י״ז:) ואמרינן התם דתנא דמתניתין פליג וא״כ יש לתמוה על רבינו למה פסק דלא כוותיה ואפשר שטעמו מדחזינן דאייתי בגמרא האי ברייתא ומפרש טעמה. וה״ה כתב בפרק ז' מהלכות יו״ט שטעם רבינו משום דהכי איתא התם תנא האבל והכהן מותרים בגילוח ואוקמוה בדשלים משמרתו ברגל תנא דידן סבר כיון דתנן בשלשה פרקים היו כל המשמרות שוות באימורי הרגלים ובחילוק לחם הפנים כמאן דלא שלים משמרתו ברגל דמי ותנא ברא סבר אע״ג דשייך בהנך משמרות משמרתיה מיהא שלמה ליה ומאחר דהלכה כתנא ברא באבל כנזכר שם כן הלכה כמותו בכהן. והר״י קורקוס ז״ל כתב דלא מכרעא מילתא דמתניתין פליגא דאיכא למימר תנא ושייר כדשייר מי שאבדה לו אבידה:\",1,0],[8,361,1,14,\"דין קרועי בגדים ודין פרועי ראש אחד הוא וכו'. פשוט הוא.\",1,0],[8,361,1,14,\"ומה שכתב שעבודתו כשירה ולא חללה. נתבאר בסמוך:\",2,0],[8,361,1,15,\"יראה לי שכל כהן הכשר לעבודה וכו' אף על פי שלא עבד וכו'. הראב\\\"ד כתב אם נכנס מן המזבח ולפנים אמר אברהם זה לא מצאתיו וכו'. והרמב\\\"ן בהשגותיו לספר המצות כתב שטעם רבינו ממה שאמרו בסיפרא מנין שאינו חייב אלא בשעת עבודה תלמוד לומר אתה ובניך אתך ומפרש רבינו דבשעת עבודה דקתני היינו ביום בשעה שהעבודה כשירה וחייב מלקות קאמר והרמב\\\"ן חולק עליו ומפרש דבשעת עבודה היינו שעת עבודה ממש כלומר אם עבד והוא שתוי או פרוע ראש או קרוע בגדים אבל ליכנס בלבד בלא עבודה אינו אסור מן התורה ומה ששנינו בסוף פרק קמא דכלים (משנה ט) בין האולם ולמזבח מקודש ממנו שאין בעלי מומין ופרועי ראש נכנסים לשם אינו אלא ממעלות דרבנן והאריך עוד בזה לסתור דברי רבינו וכן כתב עוד בפירוש התורה בפרשת שמיני. וליישב דעת רבינו י\\\"ל שרבינו סובר כמאן דאמר בפרק טרף בקלפי (יומא דף מ\\\"ד:) מעלות דאורייתא ומפרש דהיינו לומר שהאיסור ליכנס שם פרועי ראש וכו' הוא מדאורייתא אע\\\"פ שנשנו שם קצת מעלות שע\\\"כ הם דרבנן היכא דאפשר לפרש שהם דאורייתא אמרינן ולפי שראה רבינו דהאי בשעת עבודה דקתני בסיפרא אפשר לפרשו כדפריש הרמב\\\"ן כתב דין זה בדרך יראה לי ולא כתבו סתם:\",1,0],[8,361,1,16,\"ומ\\\"ש ודין הנכנס ככה מן המזבח ולפנים וכו'. בתורת כהנים פרשת שמיני בבואכם אל אהל מועד אין לי אלא בביאה מנין אף ביציאה תלמוד לומר אתה ובניך מנין לעשות המזבח כאהל מועד תלמוד לומר אתה ובניך רבי אומר נאמר כאן בבואכם אל אהל מועד ונאמר בקידוש ידים ורגלים בבואכם אל אהל מועד מה להלן עשה גישת מזבח כביאת אהל מועד ועשה בו יציאה כביאה ואינו חייב אלא בשעת עבודה אף כאן כן. וכתב סמ\\\"ג מנין אף ביציאה תלמוד לומר אתה ובניך פירוש אפילו אחד מהם יוצא מנין לעשות המזבח כאהל מועד תלמוד לומר אתה ובניך פירוש בדבר שאתה ובניך חלוקים משאר ישראל ע\\\"כ לשונו. ואיני יודע היכי יליף יציאה מאתה ובניך ואפשר דמייתורא דריש ליה דהל\\\"ל יין ושכר אל תשתו בבואכם ואתה ובניך אתך אייתר למדרש באם אינו ענין לאסור אף ביציאה:\",1,0],[8,361,1,16,\"ועל מה שכתב רבינו כגון ששתה רביעית יין בין האולם ולמזבח וכו'. כתב הראב\\\"ד אמר אברהם אם לדבריו אין צורך שישתה היין בין האולם ולמזבח וכו' נראה שטעמו דאין לומר לחייב ביציאה היינו שהכניס יין בפנים ושתה שם דמי נתן יין בפנים ותורת כהנים ה\\\"פ אין לי אלא בביאה דבבואכם משמע כשהם נכנסים ממש רגל אחת בפנים ורגל אחת בחוץ לא ישתו אבל לשתות קודם שיתחילו ליכנס כלל לא קמשמע לן ולהאי קרי יציאה כיון דכששותים עדיין הם בחוץ. ומה שכתב אם לדבריו כלומר שהוא סובר דאף אם נכנס מן המזבח ולפנים לוקה דאילו להראב\\\"ד לפנים מן המזבח אינו אלא ממעלות דרבנן כמו שכתב בהשגה שקודם זו. ומה שסיים וכתב ובמזבח מיתה נמי איכא בשתויי יין כלומר דלדעת רבינו אע\\\"ג דבבואכם קאי בין למזבח בין לפנים מן המזבח ולא תמותו לא קאי אלא למזבח בלבד:\",2,0],[8,361,1,17,\"וכן אסור לכל אדם בין כהן בין ישראל וכו' עד סוף הפרק. נראה שהוא מסברא שזה בכלל מה שנצטוינו ליראה מהמקדש.\",1,0],[8,361,1,17,\"ומה שכתב כשהוא שתוי יין או שכור היינו לומר דאפילו לא שתה יין אלא שהוא שכור משאר משכרין דאילו שכור מיין בקל וחומר אתי משתוי ולא הוה צריך למימר:\",2,0],[8,361,2,1,\"אין כ\\\"ג נכנס לקדש הקדשים וכו'. משנה בפ\\\"ק דכלים (משנה ט).\",1,0],[8,361,2,1,\"ומ\\\"ש וכהן הדיוט נכנס לקדש לעבודה בכל יום. נראה דהיינו להקטיר קטורת על מזבח הזהב שהוא בהיכל:\",2,0],[8,361,2,2,\"והוזהרו כל הכהנים שלא יכנסו לקדש וכו'. אע\\\"פ שמפשט הכתוב לא נצטווה בלא יבא אלא אהרן בתורת כהנים דרשו שאין תלמוד לומר אחיך ולמה נאמר אחיך לרבות את הבנים ובפסיקתא מסיים בה וכן הוא אומר וישמע אברם כי נשבה אחיו והוא לוט בן אחיו.\",1,0],[8,361,2,2,\"ומה שכתב שנאמר ואל יבא בכל עת אל הקדש זה קדש הקדשים מבית לפרוכת להזהיר על כל הבית תמיה לי מאחר דקרא לא קאמר אלא הקדש מניין לנו לומר זה קדש הקדשים ותו היכי מרבה כל הבית מדכתיב מבית לפרוכת דמבית לפרוכת קדש הקדשים משמע והיכי מרבה מיניה כל הבית. ונראה דה\\\"פ אילו לא נאמר אלא על הקדש הייתי אומר דלפני לפנים קרי קדש אבל להיכל לא נאסר משום דתפסת מועט תפסת והשתא דכתב מבית לפרוכת דהיינו קדש הקדשים על כרחך לומר דאל הקדש להזהיר על כל הבית אתא דאילו לפני לפנים כבר הזהיר במבית לפרוכת ודקדק רבינו לכתוב להזהיר על כל הבית לומר דאף על גב דמבית לפרוכת הוי במיתה בהיכל אינו אלא באזהרה כמו שיתבאר בסמוך:\",2,0],[8,361,2,3,\"כהן שנכנס לקדש הקדשים וכו'. ובספרי ואל יבא בכל עת זה יום הכיפורים אל הקדש לרבות שאר ימות השנה:\",1,0],[8,361,2,3,\"וכמה פעמים הוא נכנס לשם וכו'. תוספתא בפרק קמא דכלים:\",2,0],[8,361,2,4,\"והנכנס לקדש חוץ לקדש הקדשים וכו'. בפרק הקומץ רבה (מנחות דף כ״ז:) טהורין שנכנסו לפנים ממחיצתן להיכל כולו בארבעים מבית לפרכת אל פני הכפורת במיתה ר״י אומר כל היכל כולו ומבית לפרכת בארבעים ואל פני הכפורת במיתה במאי קא מיפלגי בהאי קרא ואל יבא בכל עת אל הקדש מבית לפרכת אל פני הכפורת אשר על הארון ולא ימות רבנן סברי אל הקדש בלא יבא מבית לפרוכת ואל פני הכפרת בלא ימות ורבי יהודה סבר אל הקדש ומבית לפרוכת בלא יבא ואל פני הכפורת בלא ימות ופירש״י מבית לפרוכת לפני לפנים ששם ארון ואל פני הכפורת נמי היינו מבית לפרוכת אלא שהלך עד לפני הארון וידוע דהלכה כרבנן.\",1,0],[8,361,2,4,\"ומ\\\"ש רבינו או להשתחוות, ה\\\"ק אם נכנס שלא לעבודה או להשתחוות דלהכנס לעבודה או להשתחוות מותר וזו היא ששנינו פ\\\"ז דתמיד (דף ל\\\"ג:) בזמן שכהן גדול נכנס להשתחוות ג' אוחזין בו וכך הם דברי התוספות בפרק הקומץ ומ\\\"ש בפרק י\\\"ט מסנהדרין כהן שנכנס להיכל שלא בשעת עבודה לוקה צ\\\"ל דהשתחויה בכלל עבודה היא שם וסמ\\\"ג כתב וז\\\"ל הנכנס להיכל חוץ לקדש הקדשים שלא לעבודה או להשתחוות וכהנים שלא עבדו בין גדול ובין הדיוט לוקה ואינו חייב מיתה ומה ששנינו בזמן שכ\\\"ג נכנס להשתחוות בגמר עבודה מדבר עכ\\\"ל נראה מדבריו דכשאינו בגמר עבודה אם נכנס להשתחוות לוקה ולפי זה דברי רבינו ה\\\"פ הנכנס לקדש שלא לעבודה או שנכנס להשתחוות אם אינו בגמר עבודה לוקה:\",2,0],[8,361,2,5,\"כהן שיצא מן המקדש בשעת העבודה בלבד חייב וכו'. בסיפרא פרשת שמיני ומפתח אהל מועד לא תצאו יכול בין בשעת עבודה בין שלא בשעת עבודה ת\\\"ל ומן המקדש לא יצא ולא יחלל אימתי אינו יוצא ולא יחלל הוי אומר בשעת עבודה כי שמן משחת ה' עליכם אין לי אלא אהרן ובניו שאם יצאו בשעת עבודה חייבים מיתה מנין לכהנים שבכל הדורות ת\\\"ל כי שמן משחת ה' עליכם. וכתב הראב\\\"ד תימה גדול הוא זה וכו'. נראה שטעמו של הראב\\\"ד משום דכתיב כי שמן משחת ה' עליכם ודעת הרמב\\\"ן בזה כדעת רבינו ומתוך דבריו נתיישבה תמיהתו של הרמב\\\"ן שכתב בהשגותיו לספר המצות בעיקר החמישי וז\\\"ל ת\\\"ל כי שמן משחת ה' עליכם לומר שאפילו כהנים הדיוטים שבכל הדורות כאלעזר ואיתמר באזהרה זו שלא להניח עבודה ולצאת כל זמן שיכולים לעשותה והראיה כי שמן משחת ה' עליכם מדלא כתיב כי בשמן הקדש נמשחתם ואמר שמשחת ה' עליהם שהוא לדורות כמו שאמר בהם והיתה להם משחתם לכהונת עולם לדורותם עכ\\\"ל וכ\\\"כ עוד בפי' התורה סוף פ' צו:\",1,0],[8,361,2,5,\"וכן זה שנאמר בכהן גדול:\",2,0],[8,361,2,6,\"אם כן מפני מה נשנית אזהרה זו בכ״ג וכו'. בר״פ כל הזבחים (זבחים דף כ״ח) אונן [דפסול] מנ״ל דכתיב ומן המקדש לא יצא ולא יחלל הא אחר שלא יצא חילל ופירש״י ומן המקדש וגו' לעיל מיניה כתיב לאביו ולאמו לא יטמא ובכהן גדול משתעי וסמיך ליה ומן המקדש וגו' כלומר אף ביום שמתו אביו ואמו אין צריך לצאת מן המקדש אלא עומד ומקריב ולא יחלל שאין הקדשים מתחללין בכך הא הדיוט שלא יצא ועבד חילל עכ״ל. ויש לדקדק בדברי רבינו שכתב שאפילו כהן הדיוט שיצא מן המקדש בשעת עבודה חייב מיתה משמע שהטעם מפני שנראה כמזלזל העבודה אם יניחנה מפני ששמע שמת לו מת ויצא נראה שגומר עבודתו ואח״כ יצא שהרי כתב שאינו מוזהר מלצאת אלא בשעת עבודה בלבד ואח״כ כתב שכהן הדיוט שהיה במקדש בעבודתו ושמע שמת לו מת אינו עובד נראה שמיד ששמע מפסיק ומסלק ידו מעבודתו ומאחר שאסור לגמור עבודתו למה אסור לו לצאת מיד דכך לי שעת עבודה כיון שאינו יכול לעבוד כמו שלא בשעת עבודה ונ״ל שאע״פ שאינו יכול לגמור עבודתו אם יצא קודם שתגמר העבודה ע״י אחר נראה כמזלזל בעבודה ועי״ל שאם היה מותר לו להפסיק עבודתו ולצאת כששמע שמת לו מת איכא למיחש שמא כשיפסיק העבודה ויצא בבהלה תהיה העבודה בטלה מאין מתעסק בה עד שיתעוררו שאר הכהנים לבא לגמור ואין לך זלזול גדול מזה ולפיכך אסרה לו לצאת עד שתגמר העבודה ע״י אחר:\",1,0],[8,361,2,6,\"כתב הראב\\\"ד אע\\\"פ שאינו יוצא א\\\"א וכיון שהוא חייב להתאבל עליו וכו'. ואיני רואה כאן השגה שלא כתב רבינו שאסור לו לצאת אלא בשעת עבודה בלבד ואחר גמר עבודה יצא ויטמא:\",2,0],[8,361,2,6,\"ומה שכתב ואם עבד והוא אונן של תורה חילל עבודתו וכו'. בסוף פרק הנשרפין (סנהדרין דף פ\\\"ד) תניא דאונן אסור לעבוד ואמרינן בגמרא מנ\\\"ל דכתיב ומן המקדש לא יצא [ולא יחלל] הא אחר שלא יצא חילל ופירש\\\"י ומן המקדש לא יצא כלומר אע\\\"פ שמתו אביו ואמו אין צריך לצאת מן המקדש שאם יעבוד לא יחלל הא כהן אחר שלא יצא חילל. וברפ\\\"ב דזבחים (דף ט\\\"ו) נמי תנן דאונן שקיבל פסל ויליף לה מהאי קרא ומקראי אחריני ומייתי לה בק\\\"ו.\",3,0],[8,361,2,6,\"ומ\\\"ש בין בקרבן יחיד בין בקרבן צבור. הכי אסיקנא ברפ\\\"ב דזבחים שם.\",4,0],[8,361,2,6,\"ומ\\\"ש אבל כהן גדול עובד כשהוא אונן שנאמר ומן המקדש לא יצא ולא יחלל וכו'. וכבר נתבאר בסמוך ובפרק קמא דיומא (דף י\\\"ג:) תניא היה עומד ומקריב [על גבי המזבח] ושמע שמת לו מת מניח עבודתו ויצא דברי רבי יהודה ר' יוסי אומר יגמור ופירשו התוספות דבכהן גדול מיירי וכן דעת רבינו:\",5,0],[8,361,2,7,\"ומה שכתב ומנין שעבודת האונן פסולה מקל וחומר וכו'. בריש פרק שני דזבחים (דף ט\\\"ז):\",1,0],[8,361,2,8,\"ומה שכתב ואע\\\"פ שכהן גדול עובד אונן אסור לאכול בקדשים וכו'. משנה בסוף הוריות (דף י\\\"ב:) כ\\\"ג מקריב אונן ולא אוכל וההדיוט לא מקריב ולא אוכל.\",1,0],[8,361,2,8,\"ומ״ש וכן אינו חולק לאכול לערב. ברייתא בר״פ טבול יום (זבחים דף צ״ט).\",2,0],[8,361,2,8,\"ומ\\\"ש אונן שעבד אינו לוקה. פשוט הוא דהא לית ביה לאו מפורש.\",3,0],[8,361,2,8,\"ומ\\\"ש ומותר ליגע בקדשים וכו'. משנה וגמרא (דף צ\\\"ח צ\\\"ט) וגמרא בר\\\"פ טבול יום:\",4,0],[8,361,2,9,\"אי זהו אונן וכו'. בפרק טבול יום (זבחים דף צ״ט:) אנינות לילה מדברי תורה דברי רבי יהודה רבי שמעון אומר אינה [מדברי תורה] אלא מד״ס ופסק כר״ש משום דרבי ס״ל כר״ש כדאיתא בפ' הנזכר (דף ק״א) הן היום אני היום אסור ולילה מותר ולדורות בין ביום ובין בלילה אסור דברי ר' יהודה רבי אומר אנינות לילה אינה מדברי תורה אלא מד״ס ועוד דסתם לן תנא כוותיה בפסחים ס״פ האשה (דף צ״א:) וכן הכריח הרי״ף בפרק היה קורא (דף י״ח):\",1,0],[8,361,2,10,\"ומ״ש ומת ששהה ימים וכו'. בפרק טבול יום (זבחים דף ק״א) עד מתי מתאונן עליו כל זמן שאינו נקבר אפילו מכאן עד י' ימים דברי רבי וחכמים אומרים אין מתאונן עליו אלא אותו היום בלבד ואיתא תו התם [תריץ הכי] עד מתי הוא מתאונן עליו כל אותו היום בלא לילו רבי אומר כל זמן שלא נקבר תופס לילו. ופירש״י [ע״כ] בליל יום קבורה פליגי דקאמר רבי אפילו קברו לסוף י' ימים מתאונן עליו ליל יום קבורה וחכמים אומרים אינו מתאונן עליו ביום הקבורה אלא יום עצמו אבל לא לילו וידוע דהלכה כחכמים.\",1,0],[8,361,2,10,\"ומ\\\"ש לפיכך מי שמת לו מת לאחר יום המיתה כל יום הקבורה אינו מקריב ואינו אוכל בקדשים מדבריהם. כבר נתבאר.\",2,0],[8,361,2,10,\"ומ\\\"ש וטובל. בפרק חומר בקדש (דף כ\\\"א) תנן דאונן צריך טבילה לקדש.\",3,0],[8,361,2,10,\"ומ\\\"ש ואוכל לערב. כבר נתבאר דהלכה כחכמים דיום קבורה אינו תופס\",4,0],[8,361,2,10,\"לילו ומ״ש ויום שמועה קרובה וכו'. בפרק טבול יום (זבחים דף ק') תניא יום שמועה כיום קבורה למצות ז' ול' ולאכילת פסחים כיום ליקוט עצמות אחד זה ואחד זה טובל ואוכל בקדשים לערב ושקיל וטרי בה גמרא ומסיק תנאי היא כלומר וסיפא כחכמים דאמרי יום קבורה אינו תופס לילו.\",5,0],[8,361,2,10,\"ומ\\\"ש אבל יום המיתה וכו'. כבר נתבאר.\",6,0],[8,361,2,10,\"ומ\\\"ש חוץ מן הפסח בלבד שהוא אוכל לערב (אבל לא בקדשים) ומפרש בגמרא טעמא משום דאנינות לילה דרבנן גבי פסח לא העמידו דבריהם במקום כרת גבי קדשים העמידו דבריהם במקום עשה.\",7,0],[8,361,2,10,\"ומ\\\"ש כמו שיתבאר במקומו. בהלכות פסח פ\\\"ו:\",8,0],[8,361,2,11,\"האבל אינו משלח קרבנותיו כל ז'. בפ' אלו מגלחין (מועד קטן דף ט״ו) אבל אינו משלח קרבנותיו דתניא רבי שמעון אומר שלמים בזמן שהוא שלם ולא בזמן שהוא אונן ופירש״י לפיכך נקראים שלמים בזמן שהוא שלם בדעתו שדעתו מיושבת עליו ובתוספתא דזבחים פרק י״א אין אונן רשאי להביא זבחים כל שבעה.\",1,0],[8,361,2,11,\"ומ\\\"ש אפילו יין או עצים או לבונה. תוספתא פרק י\\\"א דזבחים:\",2,0],[8,361,2,11,\"וכן מצורע אינו משלח קרבנותיו וכו'. בפרק ואלו מגלחין (מועד קטן דף ט״ו) יליף לה מקרא.\",3,0],[8,361,2,11,\"ומה שכתב אבל המנודה יש בו ספק אם משלח אם אינו משלח. שם.\",4,0],[8,361,2,11,\"ומ\\\"ש לפיכך אם הקריבו עליו נרצה. נראה דטעמא משום דמייתי התם למפשטה מדתניא כל אותן שנים שהיו ישראל במדבר מנודים היו ושלחו קרבנותיהם ודחי אביי דילמא מנודה לשמים שאני דקיל קיל והא אמרת חמיר ספוקי מספקא ליה ומדחי ליה וכיון דחזינן דמנודין לשמים שלחו קרבנותיהם לכתחלה אפילו אם תימצי לומר דמנודה לשמים קיל ממנודה לבריות מסתיין דנימא דהיינו דמנודה לבריות לא ישלח קרבנותיו לכתחלה אבל לומר דאף בדיעבד לא נרצה אין לנו:\",5,0],[8,361,2,12,\"טמא שרץ וכיוצא בו וכו'. בפרק תמיד נשחט פסחים (דף ס\\\"ב) בכל הזבחים ערל וטמא משלחין קרבנותיהם ואילו בפסח ערל וטמא אין משלחין פסחיהם ופירש\\\"י ערל וטמא משלחין קרבנותיהם בעזרה חוץ מפסח דבעינן ראוי לאכלו שאכילת בעליו מעכבת בו דכתיב לפי אכלו תכוסו וכתבו התוספות קשה לר\\\"י טמא איך משלח קרבנותיו והא בעי סמיכה וכו' וכל הסומך ראשו ורובו מכניס ותירץ דהכא מיירי בעופות וכן משני בהשולח אי נמי בבכור ובמעשר דלא בעו סמיכה ובפרק ב' דזבחים (דף כ\\\"ב:) אמר ריש לקיש דטמא שרץ משלח קרבנותיו וטמא מת אינו משלח קרבנותיו ובפרק מי שהיה טמא פסחים (דף צ\\\"ג) סבר רב נחמן כמ\\\"ד שוחטין וזורקין על טמא שרץ:\",1,0],[8,361,2,12,\"ומ\\\"ש חוץ מפסח שאין שוחטין אותו על טמא שרץ. פירוש עד שיטבול אבל טבול יום דמת אין שוחטין עליו כמבואר בפרק ששי מהלכות קרבן פסח.\",2,0],[8,361,2,12,\"ומ\\\"ש אבל טמא מת אין מקריבין עליו כלל עד שיטהר. כבר כתבתי בסמוך דבפרק שני דזבחים אמרינן דריש לקיש אמר הכי ואע\\\"ג דאמרינן התם דזקני דרום סברי דטמא מת משלח קרבנותיו משמע התם דלא קיימא לן כוותייהו דמתיב עלייהו ולא שני אלא בדוחק ואמרינן התם דאף זקני דרום לא אמרו אלא בדיעבד אבל למצוה לא ישלח וא\\\"כ ריש לקיש דפליג עלייהו בדיעבד נמי קאמר ומש\\\"ה כתב רבינו אין מקריבין עליו כלל כלומר אפילו בדיעבד לא מהני ובכלל זה גם כן לומר שאע\\\"פ שטבל אין מקריבין עליו כמו שנתבאר:\",3,0],[8,361,3,2,\"מצות עשה לשלח כל הטמאים מן המקדש וכו' זה המחנה האמור כאן הוא מחנה שכינה וכו'. ומ\\\"ש שמחנה שכינה הוא מפתח עזרת ישראל ולפנים וכן מ\\\"ש שמחנה ישראל הוא מפתח ירושלים ולפנים. תוספתא פ\\\"ק דכלים כשם שהיו במדבר שלש מחנות מחנה שכינה ומחנה לויה ומחנה ישראל כך היו בירושלים מפתח ירושלים עד פתח הר הבית מחנה ישראל מפתח הר הבית עד שער נקנור מחנה לויה משער נקנור ולפנים מחנה שכינה והן קלעים שהיו במדבר ואיתא נמי בספרי פרשת נשא ובסוף זבחים (דף קי\\\"ו):\",1,0],[8,361,3,2,\"ומ\\\"ש שומע אני שהמצורע והזב וטמא מת וכו' מה מצורע שטומאתו חמורה חמור שילוחו משילוח חבירו וכו'. בספרי פרשת נשא וישלחו מן המחנה כל צרוע וכל זב וגו' שומע אני שלשתן במקום אחד ת\\\"ל במצורע בדד ישב מחוץ למחנה וגו' מצורע היה בכלל ויצא מן הכלל לימד על הכלל כולו מה מצורע שחמורה טומאתו וחמור שילוחו משילוח חבירו פירוש מדכתיב בדד ישב נראה שהוא לבדו שם שאין אחר במחיצתו אף כל שחמורה טומאתו חמור שילוחו משילוח חבירו מכאן מנו חכמים למחיצות כל שהזב מטמא מצורע מטמא חמור מצורע שמטמא בביאה כל שהמת מטמא הזב מטמא חמור הזב שמטמא תחת אבן מסמא וכיוצא בזה דריש בפסחים פרק אלו דברים (דף מ\\\"ה) ובפרק שלשה מינין (נזיר דף ס\\\"ז):\",2,0],[8,361,3,4,\"ומ\\\"ש טמא מת אפילו המת עצמו וכו'. בפרק הנזכר:\",1,0],[8,361,3,5,\"ומ״ש החיל משלחין ממנו עכו״ם וכו'. בפ״ק דכלים (מ״ח) החיל מקודש ממנו שאין עכו״ם וטמאי מתים נכנסים לשם. ומה שהוסיף רבינו ובועלי נדות. ברייתא בפסחים פ' אלו דברים (פסחים דף ס״ח) ששנינו בה בועל נדה כטמא מת והעלו שם דלמחנות קאמר.\",1,0],[8,361,3,5,\"ומ\\\"ש אבל טבו\\\"י נכנס לשם שכבר טבל. כן משמע שם:\",2,0],[8,361,3,6,\"ומ\\\"ש עזרת הנשים משלחין ממנו טבול יום וכו'. ג\\\"ז שם.\",1,0],[8,361,3,6,\"ומ\\\"ש ואסור טבול יום במחנה לויה מד\\\"ס. ברפ\\\"ג דזבחים (דף ל\\\"ב) ובפ\\\"ק דיבמות (ז':) א\\\"ר יוחנן אפילו עשה לית ביה שנאמר ויעמוד יהושפט בקהל יהודה [וירושלים בבית ה'] לפני החצר החדשה מאי חדשה שחידשו בה דברים ואמרו טבול יום לא יכנס למחנה לויה:\",2,0],[8,361,3,7,\"ומ\\\"ש מעזרת ישראל וכו'. גם זה בפרק קמא דכלים.\",1,0],[8,361,3,7,\"ומ״ש שנאמר וכפר עליה הכהן וטהרה. בס״פ הנשרפין (סנהדרין דף פ״ג:):\",2,0],[8,361,3,8,\"הטמא המשולח מהר הבית וכו'. כ\\\"כ גם בסמ\\\"ג ל\\\"ת סי' ש\\\"ד ותמהני על זה דגרסינן בר\\\"פ אלו דברים (פסחים ס\\\"ח) תני תנא קמיה דר' יצחק בר אבדימי ויצא אל מחוץ למחנה זו מחנה שכינה ואל יבוא אל תוך המחנה זו מחנה לויה מכאן לבעל קרי שיצא חוץ לשתי מחנות אמר ליה אכתי לא עיילתיה אפיקתיה וכו' אלא אימא מחוץ למחנה זה מחנה לויה ואל יבא אל תוך המחנה זה מחנה שכינה ונראה שלא היה כתוב כן בגירסתם וכן נראה מדברי רבינו בספר המצות שלו סי' ע\\\"ח:\",1,0],[8,361,3,8,\"ומ״ש וכן מצורע שנכנס לירושלים. תוספתא כתבה רבינו בפירוש המשנה פרק קמא דכלים (משנה ח') ופירשה ובפרק אלו דברים (פסחים דף ס״ז) אמר רב חסדא מצורע שנכנס לפנים ממחיצתו פטור שנאמר בדד ישב מחוץ למחנה מושבו הכתוב נתקו לעשה איתיביה מצורע שנכנס לפנים ממחיצתו בארבעים זבים וזבות שנכנסו לפנים ממחיצתן בארבעים וכו' תנאי היא דתניא בדד ישב לבדו ישב שלא יהיו טמאים אחרים יושבים עמו יכול יהיו זבים וטמאי מתים משתלחים למחנה אחת ת״ל ולא יטמאו את מחניהם ליתן מחנה לזה ומחנה לזה דברי רבי יהודה ורבי שמעון אומר אינו צריך הרי הוא אומר וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש יאמר טמא מת ואל יאמר זב וכו' למה נאמר מצורע ליתן לו מחנה שלישית כשהוא אומר בדד ישב הכתוב נתקו לעשה ופירש״י תנאי היא דאיכא תנא דלא מייתי ליה קרא לעשה אלא ליתן לו מחנה שלישית ואע״ג דרב חסדא סבר דפטור כיון דפלוגתא דרבי יהודה ור' שמעון היא פסק רבינו כר' יהודה דהלכה כוותיה לגבי דרבי שמעון ורב חסדא איכא למימר דהאי ברייתא לא שמיע ליה מדלא אמר הלכה כפלוני ואי הוה שמיע ליה הוה אמר הלכה כר' יהודה כ״כ סמ״ג במל״ת סימן ש״ד.\",2,0],[8,361,3,8,\"ומ\\\"ש אבל אם נכנס לשאר ערים המוקפות חומה אע\\\"פ שאינו רשאי לפי שנאמר בדד ישב אינו לוקה. כ\\\"כ רבינו בפירוש המשנה פ\\\"ק דכלים:\",3,0],[8,361,3,9,\"נכנס המצורע להר הבית לוקה שמונים. בתוספתא פרק קמא דכלים ופירשה רבינו שם בפירוש המשנה ונראה דמשום דמקרא דולא יטמאו את מחניהם לוקה ארבעים כשנכנס לפנים מחומת ירושלים שהרי טימא מחנה ישראל וכדתניא בסיפרי וכשנכנס עוד להר הבית לוקה עוד ארבעים מפני שטימא מחנה לויה ונמצא שעבר שנית על ולא יטמאו את מחניהם אי נמי שכשנכנס להר הבית עבר משום ואל יבא אל תוך המחנה זה מחנה לויה וכמו שכתב רבינו לעיל בסמוך וקשה דאם כן הל\\\"ל נמי שאם נכנס למחנה שכינה לוקה ק\\\"כ שהרי טימא גם מחנה שכינה ולוקה עליו שלישית ואפשר דכיון דגלי לן שאם נכנס למחנה לויה לוקה שמונים ממילא משמע שאם נכנס למחנה שכינה לוקה ק\\\"כ:\",1,0],[8,361,3,9,\"אבל טמא מת או טבול יום שנכנס לעזרת הנשים וכו'. כבר נתבאר בפ\\\"ז שמפתח הר הבית עד שער נקנור שהוא שער עזרת ישראל מחנה לויה ונתבאר שטמא מת מותר במחנה לויה וחכמים אסרו לטמא מת ליכנס בחיל כמו ששנינו בפרק קמא דכלים (משנה ח') אע\\\"פ שהוא מחנה לויה ואסרו לטבול יום ליכנס בעזרת הנשים כמו ששנינו שם אע\\\"פ שגם היא ממחנה לויה וכיון דאין איסורן אלא מדרבנן אין בהם מלקות אבל מכת מרדות יש בהם כשאר איסורי דרבנן. ומ\\\"מ יש לדקדק בדברי רבינו שהיה לו לכתוב טמא מת שנכנס לחיל או טבול יום שנכנס לעזרת הנשים כמו שהוא במשנה פרק קמא דכלים וכן שנינו עוד בתוספתא כתבה רבינו בפי' המשנה פ\\\"ק דכלים החיל ועזרת הנשים מעלה יתירה בבית עולמים והטמאים שנכנסו לשם פטורים:\",2,0],[8,361,3,9,\"ומ״ש או מחוסר כפורים שנכנס לעזרת ישראל, וכתב עליו הראב״ד זה שיבוש דמחוסר כפורים שנכנס למחנה שכינה וכו'. ותמהני למה הלך להביא ראיה מהתוספתא והניח מלהביא מדתניא בפרק הקומץ רבה (מנחות דף כז:) מחוסרי כפרה שנכנסו לעזרה בשוגג חייב חטאת במזיד ענוש כרת. וליישב דברי רבינו י״ל דמשמע בפרק שני דזבחים (דף י״ז:) דאיכא תנא דסבר מחוסר כפורים לאו כזב דמי ואע״ג דקאמר התם לא דכ״ע [מחוסר כפורים דזב] כזב דמי והכא בהא קא מיפלגי וכו' האי דחייה בעלמא היא אבל קושטא דמילתא דפלוגתא היא וכדמוכח קצת בפ' ג' מינין וההיא דתוספתא וההיא דהקומץ רבה כמ״ד מחוסר כפרה דזב כזב דמי ורבינו פסק כמ״ד לאו כזב דמי ומכל מקום צריך טעם למה פסק כן. ובפרק י״ח מהלכות פסולי המוקדשים כתב האוכל קדש אחר שטבל קודם שיעריב שמשו או קודם שיביא כפרתו לוקה ואינו חייב כרת שנאמר וטומאתו עליו עד שתהיה כל טומאתו עליו עכ״ל. ודרשא זו דטומאתו עליו באיזה מקום מייתי לה ועלה סמך רבינו גם בכאן. אחר כך מצאתי להר״י קורקוס ז״ל שכתב דטעמיה משום דבפרק שני דזבחים בעינן לאוקמיה פלוגתא דרבנן ויוסף הבבלי בהכי ומוקי רבנן כמ״ד לאו כזב דמי גם רבי יוחנן הכי ס״ל גבי טבול יום וכל שכן גבי מחוסר כפורים ותו דבפ' ג' מינין אמרינן דכ״ע מחוסר כפורים דזב לאו כזב דמי גם בסמוך כתבתי בשם רבינו שמשון דתנא דכלים צ״ל דסבר לאו כזב דמי ותני לה גבי הלכתא פסיקתא גם סוגיא דמעילה ובסוטה דרבנן דפליגי אאבא שאול סברי לאו כזב דמי כאשר כתוב שם בתוספתא דלשיטת רש״י צ״ל כן ושיטת רבינו עד כאן לשונו:\",3,0],[8,361,3,10,\"וכשם ששילוח טמאים מן המקדש בעשה וכו'. זה פשוט וכתב רבינו בספר המצות סימן ל\\\"א וז\\\"ל לשון מכילתא צו את בני ישראל וישלחו מן המחנה בעשה ומנין בל\\\"ת ת\\\"ל ולא יטמאו את מחניהם עכ\\\"ל. אך\",1,0],[8,361,3,10,\"מ\\\"ש זה מחנה שכינה דמשמע לכאורה דאתא למעוטי שאר מחנות שאינו לוקה עליהם קשה דמהי תיתי לן דקרא סתם איירי משמע דאכולהו מחנות קאי ואין לומר דמדכתיב ולא יטמאו את מחניהם אשר אני שוכן בתוכם משמע דמחנה שכינה דוקא קאמר דעבר עליו בלא תעשה ולא על שאר מחנות שיקשה לזה ממה שכתב רבינו לעיל בפרק זה והוא שנוי בתוספתא נכנס המצורע להר הבית לוקה שמונים ואפשר לומר דמן המקדש דנקט רבינו מקום המקודש קאמר וכל המחנות בכלל:\",2,0],[8,361,3,11,\"ומניין שאינו עובר אא\\\"כ נכנס וכו'. כתב רבינו בסה\\\"מ שלו סי' ע\\\"ז דהכי איתא בספרי:\",1,0],[8,361,3,12,\"טמא שנכנס למקדש וכו'. פשוט הוא:\",1,0],[8,361,3,12,\"ואין חייבין כרת או קרבן וכו'. בפרק שני דשבועות (דף י\\\"ז).\",2,0],[8,361,3,12,\"ומ\\\"ש כמו שביארנו. בהלכות בית הבחירה פרק ו':\",3,0],[8,361,3,13,\"כל שנטמא בטומאה מן המת שהנזיר מגלח עליה. בפרק כהן גדול דנזיר (דף נ\\\"ו:) תנן רבי אליעזר אומר משום רבי יהושע כל טומאה מן המת שהנזיר מגלח עליה חייבין עליה על ביאת המקדש וכל טומאה מן המת שאין הנזיר מגלח עליה אין חייבין עליה על ביאת המקדש.\",1,0],[8,361,3,13,\"ומ\\\"ש שכבר נתפרש בנזירות. הוא בפרק שביעי.\",2,0],[8,361,3,13,\"ומ״ש או שיגע באדם או בכלים שנטמאו באותן טומאות שהנזיר מגלח עליהם וכו': כתב הראב״ד שיבוש הוא זה שאין הנזיר מגלח וכו'. ואני אומר פשטן של דברים כדברי הראב״ד דתנן בפרק כהן גדול (נזיר דף נ״ד) שאין הנזיר מגלח על כלים הנוגעים במת ותנן נמי (דף נ״ו) כל טומאה מן המת שאין הנזיר מגלח עליה אין חייבין עליה על ביאת המקדש ומאחר שאין הנזיר מגלח על כלים הנוגעים במת אין חייבין עליהם על ביאת המקדש אבל רבינו מפרש דהא דתנן כל טומאה מן המת שאין הנזיר מגלח עליה אין חייבין עליה על ביאת המקדש לא לענין כלים הנוגעים במת איתניא אלא לענין טומאות הפורשות מן המת כגון רביעית דם ורובע עצמות אבל כלים הנוגעים במת אע״פ שאין הנזיר מגלח עליהם חייבין עליהם על ביאת המקדש מדגרסינן בירושלמי בפרק כהן גדול תמן תנינן שנים טמאים במת אחד טמא טומאת ז' ואחד טמא טומאת ערב שלשה טמאים במת שנים טמאים טומאת ז' ואחד טמא טומאת ערב ד' טמאים במת שלשה טמאים טומאת ז' ואחד טמא טומאת ערב כיצד שנים בני אדם הנוגעין במת טמא טומאת ז' ואדם הנוגע בו טמא טומאת ערב (כיצד ג' כלים הנוגעים במת וכלים בכלים טמא טומאת ז' והשלישי בין אדם בין כלים טמא טומאת ערב כיצד ד' כלים הנוגעים במת ואדם בכלים וכלים באדם טמא טומאת ז' הד' בין אדם בין כלים טמא טומאת ערב) רבי יוחנן בשם רבי ינאי וכולהון תורה הם אצל תרומה אבל על ביאת המקדש אינו חייב אלא על שני שנגע בראשון מה טעם ואיש אשר יטמא ולא יתחטא הטעון חיטוי חייב על ביאת המקדש ושאינו טעון חיטוי אינו חייב על ביאת המקדש. התיבון הרי אדם הנוגע בכלים ונוגעים במת טעון חיטוי והוא שני אמר ר' אבין בר חייא בטומאת איש באיש לא בטומאת איש בכלים מילתיה דרבי אבין בר חייא אינו חייב אלא על הראשון בלבד מאחר שאילו אדם באדם אינו חייב אלא על הראשון בלבד וה״פ דלגבי ביאת המקדש אינו חייב אלא על שני שנגע בראשון דהיינו הנוגע במי שנגע במת אבל שלישי שנגע בשני דהיינו הנוגע במי שנגע בנוגע במת פטור ויהיב טעמא משום דכתיב ואיש אשר יטמא ולא יתחטא וכו' וכיון דאדם הנוגע באדם שנגע במת אינו טעון חיטוי שהרי אינו טמא אלא טומאת ערב הנוגע בו אינו חייב על ביאת המקדש ולפ״ז ה״פ דקרא ואיש אשר יטמא במי שטעון חיטוי ולא יתחטא ונכרתה אבל אם יטמא במי שאינו טעון חיטוי לא. התיבון הרי אדם הנוגע בכלים הנוגעין במת טעון חיטוי שהרי הוא טמא טומאת שבעה ולפי זה יהיה אדם הנוגע בו חייב על ביאת המקדש אע״פ שהוא שלישי בשני והיאך אמרת שאינו חייב אלא שני שנגע בראשון ושני רבי אבין בר חייא אמר בטומאת איש באיש לא בטומאת איש בכלים ולפי שאלו דברים סתומים בלי טעם דמשמע דאתא לפלוגי בין טומאת איש באיש לטומאת איש בכלים וקשה שזה סותר מאמר רבי יוחנן שאמר סתם אינו חייב אלא שני בראשון וכללא הוא אף לטומאת איש בכלים לכך הוצרך לפרש דבריו ואמר מילתיה דרבי אבין בר חייא וכו' כלומר לאו כדקא ס״ד דמפליג בינייהו דלעולם אינו חייב אלא הנוגע בראשון ולא הנוגע בשני אפילו נוגע באדם שנגע בכלים שנגעו במת וטעמא משום דלית לן לפלוגי בינייהו וכיון דאדם הנוגע באדם שנגע במת אין הנוגע בו חייב על ביאת המקדש מפני שנגע במי שאינו בר חיטוי כן אדם הנוגע באדם שנגע בכלים שנגעו במת אע״פ שנגע במי שהוא בר חיטוי פטור על ביאת המקדש כיון שהוא שלישי בשני ואין לנו לחייב אלא שני בראשון בלבד ומשום דקשה דטפי הוה עדיף למיתלי כולה מילתא במי שטעון חיטוי דאידכר בקרא ולא למיתלי בשני שנגע בראשון דלא אידכר בקרא לכך הקדים רבי יוחנן ואמר כולהון תורה הם כלומר דברי קבלה הן וקאי גם למאי דאמר אבל על ביאת המקדש אינו חייב אלא על שני שנגע בראשון וז״ש רבינו שדברים אלו הלכה מפי הקבלה ואע״פ שרבינו שמשון בפ״ק דאהלות מפרש ירושלמי זה בדרך אחרת לדעת רבינו צריך לפרשו כמו שפירשתי ונתבארו דבריו ואע״ג דבתר הכי קאמר בירושל' אמר רבי אילא הוא עצמו שנגע במת חייב כלומר אבל הנוגע במי שנגע במת פטור כבר הביאו שם ברייתא החולקת עם רבי אילא וכיון דתניא כוותיה דרבי יוחנן הכי נקטינן. ודע דבתר הכי מייתי בירושלמי לסיועי לרבי יוחנן מדתנן כל טומאה שהנזיר מגלח עליה חייבים עליה על ביאת המקדש וכו' ראשון שהנזיר מגלח עליו חייבין עליו על ביאת המקדש שני שאין הנזיר מגלח עליו אין חייבין עליו [על ביאת מקדש] וה״פ לדעת רבינו ראשון דהיינו הנוגע במת שהנזיר אם נגע במת מגלח עליו חייבין עליו על ביאת המקדש כלומר הנוגע באותו ראשון ונכנס למקדש חייב שני דהיינו הנוגע במי שנגע במת שאם הנזיר נגע במי שנגע במת אינו מגלח עליו אין חייבין עליו על ביאת המקדש כלומר הנוגע באותו שני ונכנס למקדש פטור.\",3,0],[8,361,3,13,\"ומ\\\"ש או שנטמא בשאר אבות טומאות של תורה. קצת מהן מפורשות בפרשת ויקרא גבי מטמא מקדש וה\\\"ה אשארא:\",4,0],[8,361,3,14,\"ומ\\\"ש כללו של דבר כל הטעון ביאת מים מן התורה חייב כרת על ביאת המקדש ואפילו אחר שטבל עד שיעריב שמשו. משנה בפרק י\\\"א דמסכת פרה (משנה ד') כל הטעון ביאת מים מד\\\"ת אם בא אל המקדש בין לפני ביאתו במים בין לאחר ביאתו חייב.\",1,0],[8,361,3,14,\"וכתב הרב רבי אברהם בן דוד על מה שכתב רבינו כל הטעון ביאת מים וכו'. דבריו סותרים את דבריו עכ\\\"ל. ונראה שטעמו מפני שכתב אחר כך וכן הנוגע בכלים וכו' או שנגע באדם וכו' הרי זה פטור והרי אלו טעונים ביאת מים מן התורה ופטור ואם תאמר הרי ההיא דכל הטעון ביאת מים מן התורה מתניתין היא וההיא דהנוגע בכלים וכו' דעדיפא מינה קאמר הראב\\\"ד שאינו חייב על מגע כלים על ביאת מקדש ויש לומר דמתניתין דכל הטעון ביאת מים לא קשיא דהכי מיתניא התם כל הטעון ביאת מים מן התורה מטמא את הקדש ואת התרומה ואת החולין ואת המעשר ואסור על ביאת המקדש לאחר ביאתו במים מטמא את הקדש ופוסל את התרומה ואם בא על המקדש בין לפני ביאתו במים בין לאחר ביאתו חייב ואיכא למימר דכללא דכל הטעון ביאת מים לשאר מילי הוא אבל לענין חיוב מקדש לאו כללא הוא אלא אתא למימר שהטעון ביאת מים מן התורה אם הוא חייב על ביאת המקדש אע\\\"פ שבא במים חייב עד שיעריב שמשו אבל רבינו דלא מייתי ליה אלא לענין חיוב ביאת מקדש ולא עוד אלא שכתב כללו של דבר קשיא. והיה אפשר לתרץ דדברי רבינו נמי כך הם מתפרשים כללו של דבר כל אחד מאלו שאמרנו שחייבים עליהם על ביאת המקדש והוא טעון ביאת מים מן התורה אפילו טבל חייב כרת עד שיעריב שמשו אבל המתטמא בטומאות מן המת שאין הנזיר מגלח עליהם אף על פי שהוא טמא טומאת שבעה והוא טעון ביאת מים מן התורה הרי זה פטור על ביאת המקדש:\",2,0],[8,361,3,15,\"ומ\\\"ש ואע\\\"פ שהוא פטור מכין אותו מכת מרדות. הכי משמע מדאמרינן אין חייבין עליה על ביאת המקדש חיובא הוא דליכא הא איסורא איכא אבל מצאתי שרבינו כתב בפ\\\"ה מהלכות טומאת מת וז\\\"ל נמצאת אומר אדם שנגע במת ואדם באדם אחר הראשון טמא טומאת שבעה והשני [טמא] טומאת ערב כלים הנוגעים במת וכלים בכלים שניהם טמאים טומאת ז' אבל השלישי בין אדם בין כלים טמא טומאת ערב כלים הנוגעים במת ואדם בכלים וכלים באדם שלשתן טמאים טומאת ז' הרביעי בין אדם בין כלים טמא טומאת ערב בד\\\"א לענין תרומה וקדשים אבל לחייב כרת על ביאת מקדש או על אכילת קדשים אינו חייב אלא על השנים בלבד הראשון שנגע במת והשני שנגע בו כדין תורה שנאמר וכל אשר יגע בו הטמא יטמא אבל הנוגע בכלים שנגעו באדם או הנוגע באדם שנגע בכלים שנגעו במת פטור כמו שביארנו בהלכות ביאת המקדש שהדברים האלו אע\\\"פ שהם דברי קבלה אינם דין תורה שהרי לא נתפרשו בתורה אלא זה שנטמא במת שהוא אב והשני הנוגע בו שהוא ראשון בין אדם בין כלים עכ\\\"ל. וכך הם דבריו פה והשתא דברי רבינו מתיישבים כפשטן בלי סתירה שבתחילה אמר כל הטעון ביאת מים מן התורה כלומר מפורש ממש בתורה דהיינו הראשון שנגע במת והשני שנגע בו כדכתיב וכל אשר יגע בו הטמא יטמא אבל המתטמא בטומאות מן המת שאין הנזיר מגלח עליהם וכן הנוגע בכלים שנגעו באדם שנגע במת וכו' שנמצא שהוא שלישי לראשון שנגע במת הרי זה פטור על ביאת המקדש שדברים אלו הלכה מפי הקבלה כלומר ומאחר שאינם מפורשים בתורה אינם בכלל כל הטעון ביאת מים מן התורה וזה עיקר:\",1,0],[8,361,3,16,\"המכניס שרץ וכיוצא במקדש וכו'. בסוף עירובין (דף ק\\\"ד:) [אמר רב טבי בר קיסנא] אמר שמואל המכניס טמא שרץ למקדש חייב שרץ עצמו פטור וכו' לימא כתנאי שרץ שנמצא במקדש וכו' מאי לאו בהא קא מיפלגי וכו' לא דכ\\\"ע חייב והכא בהא קא מיפלגי וכו' וכיון דאסיקנא דכ\\\"ע חייב משמע דהכי הלכתא ועוד דאמרינן בתר הכי אלא כהני תנאי דתנן מהיכן מוציאין אותו וכו' מאי לאו בהא קא מיפלגי וכו' אמר רבי יוחנן ושניהם מקרא אחד דרשו ופירש\\\"י אמר רבי יוחנן לענין עיולי כ\\\"ע המכניס שרץ חייב ולענין להוציא הנמצא בעזרה בשבת בהאי קרא פליגי עכ\\\"ל ויש סיוע לדבריו מדקאמר מאי לאו בהא קא מיפלגי ולפי זה הא דאמר אלא כהני תנאי היינו לומר אלא לימא כהני תנאי וכיון דאסיקנא ה\\\"נ דחייב משמע דהכי הלכתא ואפי' לפירוש התוס' דהא דרבי יוחנן מילתא באפי נפשה היא ולא אתא לדחויי הא דקאמר אלא כתנאי מ\\\"מ תנא דאמר חייב הוא ר\\\"ע והלכה כמותו.\",1,0],[8,361,3,16,\"ומ\\\"ש אבל הזורק כלים טמאים למקדש אפילו היו כלים שנגעו במת פטור מן הכרת אבל חייב מלקות. בירושלמי פרק כהן גדול דנזיר:\",2,0],[8,361,3,16,\"ומ\\\"ש מפי השמועה למדו וכו'. הכי איתא בתורת כהנים וכתב הראב\\\"ד על זה ומאחר שעל כיבוס בגדים אין בו כרת וכו' ויש לתמוה עליו למה כתב כן על דברי רבינו שהרי דבריו דברי ת\\\"כ הם וכמו שתירץ הרב רבי אברהם ב\\\"ד לעצמו כך נתרץ לרבינו כ\\\"ש שהמסתכל בדברי רבינו יבין דלדידיה קושיא מעיקרא ליתא שהוא מפרש הא דשמואל לא במכניס כלי טמא שרץ הוא אלא במכניס אדם טמא שרץ הוא וחייב כרת הוא כפשטא דלישנא דחייב:\",3,0],[8,361,3,17,\"יראה לי שאינו לוקה אלא על בגדים שהם אב הטומאה וכו' אבל בגד שהוא ראשון אם הכניסו למקדש אינו לוקה עליו. כתב הראב\\\"ד על זה והלא טמא שרץ אינו אב הטומאה וחייב סוף דבר צריך לדקדק אחריו עכ\\\"ל. ואיני יודע היאך יצדק פה לשון סוף דבר ומ\\\"ש צריך לדקדק אחריו איני יודע מה דקדוק שייך בזה דמלתא דסברא היא כיון שהקילה תורה בכלים לפוטרם מכרת כן נאמר שהקילה בכלי שהוא ראשון לפוטרו אף ממלקות ומה שהקשה מטמא שרץ כבר כתבתי דלרבינו לא בכלי טמא שרץ מיירי אלא באדם טמא שרץ:\",1,0],[8,361,3,18,\"וכן טמא שהכניס ידו למקדש מכין אותו מכת מרדות. ברפ\\\"ג דזבחים (דף ל\\\"ב) [אמר עולא] אמר ר\\\"ל טמא שהכניס ידו לפנים לוקה וכו' דביאה במקצת שמה ביאה לענין מלקות אבל לא לענין כרת ובתר הכי אמרינן (דף ל\\\"ג:) כי אתא רבין אמר רבי אבהו לענין טמא שנגע בקדש איתמר ופירש\\\"י לא יליף ר\\\"ל מלקות מההוא קרא אלא לטמא שנגע בקדש ולא איירי בביאת מקדש כלל עכ\\\"ל. וסובר רבינו דכיון דלרבי אבהו לא איירי ר\\\"ל בביאת מקדש כלל אין לנו לחייבו מלקות משום ביאת מקדש כיון דפלוגתא היא ומיהו מדרבנן מיתסר ומכין עליו מכת מרדות.\",1,0],[8,361,3,18,\"וכתב הראב\\\"ד על דברי רבינו שמעתא דזבחים קשיא עליה וכו'. ויש לי קושיא בדבריו שכתב ואמרי' התם עשה שיש בו כרת הוא והא אסיק התם רבינא דלענין מלקות אמרה ר\\\"ל ולא לענין כרת ומה לנו אי אמרינן התם עשה שיש בו כרת הוא ונ\\\"ל דה\\\"ק שמעתא דזבחים קשיא עליה דאמר ריש לקיש טמא שהכניס ידו למקדש לוקה וקס\\\"ד התם לומר דכרת נמי איכא משמע מדאורייתא הוא הילכך אע\\\"ג דאסיק רבינא דלא לענין כרת אמרה ריש לקיש אלא לענין מלקות ע\\\"כ מלקות דאורייתא קאמר ולא מכת מרדות דרבנן כדקאמר הרמב\\\"ם ומ\\\"מ במה שכתבתי נסתלקה השגתו.\",2,0],[8,361,3,18,\"ומ״ש ואי משום שמעתא דיומא היינו דגרסינן בר״פ אמר להם הממונה (יומא דף ל״א) א״ל אביי לרבי יוסף ביאה במקצת שמה ביאה או לא א״ל בהונות יוכיחו שהם ביאה במקצת ותניא מצורע טובל ועומד בשער ניקנור ופירש״י שמה ביאה לענין טבילה זו וצריך לטבול אם בא להכניס אחד מאבריו לעזרה עכ״ל. וחשש הראב״ד שמא משם למד רבינו לומר דביאה במקצת אינה אלא מדרבנן דכיון דלענין טבילה לנכנס בעזרה שהיא דרבנן איבעיא כי פשיט ממצורע נמי מדרבנן היא וכן הוא דעת התוספות ודחה הראב״ד ראיה זו וכתב דאדרבה משם ראיה דביאה במקצת דמצורע דאורייתא דאל״כ לא היו מחמירים במעלות דרבנן ואני אומר שאין טענה זו מוכרחת ועוד שמלבד זה כבר כתבתי טעם רבינו:\",3,0],[8,361,3,18,\"וכן כל טמא באב מאבות הטומאות של דבריהם וכו'. זה פשוט:\",4,0],[8,361,3,19,\"טמא שנכנס למקדש דרך גגות פטור וכו'. ברייתא בפ\\\"ב דשבועות (דף י\\\"ז:) ומדקתני פטור משמע אבל אסור מדרבנן ומפני כך כתב רבינו ואף על פי שהוא פטור מכרת מכין אותו מכת מרדות. כתב הראב\\\"ד ואע\\\"פ שהוא פטור מכרת מלקין אותו א\\\"א חסר מכאן עכ\\\"ל. ואני שמעתי ולא אבין מה חסרון יש כאן ובנוסחא אחרת לא היה כתוב בה א\\\"א חסר מכאן ובסוף ההשגה הקודמת המתחלת שמעתא דזבחים קשיא עליה וכו' היה כתוב ואע\\\"פ שהוא פטור מכרת מלקין אותו. מצאתי ספר מוגה מספרי רבינו שכתוב בו [ואפילו נכנס במגדל הפורח באויר] בין שנכנס למקדש [במגדל] דרך גגות בין שנכנס דרך פתחים:\",1,0],[8,361,3,20,\"כל מקום שחייבים על זדונו וכו'. בסוף עירובין (ק\\\"ד:) תנן שרץ שנמצא במקדש כהן מוציאו בהמיינו שלא לשהות את הטומאה דברי ר' יוחנן בן ברוקא ר' יהודה אומר בצבת של עץ שלא לרבות את הטומאה מהיכן מוציאין אותו מן ההיכל ומן האולם ולמזבח [דברי ר\\\"ש בן ננס] ר\\\"ע אומר כל מקום שחייבין על זדונו כרת ועל שגגתו חטאת משם מוציאין אותו ושאר כל המקומות כופין עליו פסכתר ופירש\\\"י בצבת של עץ שהוא פשוטי כלי עץ ופסק רבינו כרבי יהודה וכר\\\"ע:\",1,0],[8,361,3,21,\"אחד טמא שנכנס למקדש טהור וכו': נכנס למקדש ונטמא שם אחר שנכנס וכו'. בפרק שני דשבועות (דף י\\\"ד:) תנן נטמא בעזרה וכו' והשתחוה או ששהה כדי השתחויה או בא לו בארוכה חייב ובקצרה פטור ופירש רש\\\"י או שבא לו בארוכה שיוצא לו דרך ארוכה שיש קצרה ממנה לצאת חייב ואפילו לא שהה תחלה ושיעורים הללו הלכה למשה מסיני הם במי שנטמא בתוך העזרה. בקצרה פטור היכא דלא שהה ולא השתחוה ובגמרא (דף ט\\\"ז:) השתחוה אמר רב לא שנו אלא שהשתחוה כלפי פנים אבל השתחוה כלפי חוץ שהה אין לא שהה לא ופירש רש\\\"י לא שנו דבהשתחויה כל דהו אפילו לא שהה בה כדי השתחויה חייב אלא שהשתחוה כלפי פנים לצד מערב אבל השתחוה כלפי חוץ לצד מזרח אין זו השתחויה ואי שהה כדי השתחויה מיחייב משום שהייה ואי לא לא.\",1,0],[8,361,3,21,\"ומה שכתב אפילו טימא עצמו במזיד. שם (דף י\\\"ז) בעי רב אשי טימא עצמו במזיד מהו באונס גמירי שהייה במזיד לא גמירי שהייה או דלמא בפנים גמירי שהייה לא שנא באונס לא שנא במזיד תיקו ופסק לקולא:\",2,0],[8,361,3,22,\"ומה שכתב חייב כרת ואם היה שוגג מביא קרבן. שם (דף ט\\\"ז:) בעי רבא צריך שהייה למלקות או [אין צריך שהייה למלקות] לקרבן גמירי שהייה למלקות לא [גמירי שהייה] או דילמא בפנים גמירי שהייה לא שנא לקרבן לא שנא למלקות תיקו ופסק לקולא:\",1,0],[8,361,3,23,\"ומה שאמר וכמה שיעור שהייתו כדי לקרות ויכרעו אפים ארצה וכו' שם כמה שיעור שהייה פליגי בה רבי יצחק בר נחמני וחד דעמיה וכו' דחד אמר כמימריה דהאי פסוקא וחד אמר כמויכרעו לסופיה וכל בני ישראל רואים ברדת האש וכבוד ה' על הבית ויכרעו אפים ארצה על הרצפה וישתחוו והודות לה' כי טוב כי לעולם חסדו ופסוק זה הוא בדברי הימים ויש לתמוה למה פסק רבינו להחמיר כמאן דאמר מויכרעו לסופיה ולא כמאן דאמר כמימריה דהאי פסוקא דמשמע כמימריה דכוליה פסוקא מראשו עד סופו ושמא יש לומר שרבינו מפרש דמ\\\"ד כמימריה דהאי פסוקא אינו כל הפסוק אלא עד ויכרעו בלבד ואם כן הוה ליה מ\\\"ד מויכרעו לסופיה מיקל ופסק כוותיה ובירושלמי פרק אמר להם הממונה תנינן תמן השתחוה או ששהה כדי השתחויה עד כמה היא שיעור השתחויה רבי סימון בשם רבי יהושע בן לוי עד כדי ויכרעו אפים ארצה [על הרצפה] וישתחוו רבי אבהו מוסיף עד והודות לה' כי טוב כל\\\"ח ועל פי זה יש לפרש דמ\\\"ד כמימריה דהאי פסוקא היינו כדי ויכרעו אפים ארצה וישתחוו בלבד דהשתא הוי מאן דאמר מויכרעו לסופיה מיקל ומספיקא פסק כמאן דמיקל:\",1,0],[8,361,3,24,\"יצא בקצרה אע\\\"פ שלא רץ וכו'. מימרא דרבא שם (דף י\\\"ז):\",1,0],[8,361,3,24,\"יצא בארוכה וכו' הואיל ויצא בארוכה חייב. שם בעיא דאיפשיטא:\",2,0],[8,361,3,24,\"יצא בקצרה והלך מעט וכו'. שם בעיא דלא איפשיטא ופסקה לקולא:\",3,0],[8,361,4,1,\"טמא שעבד במקדש חילל עבודתו. משנה ריש פ\\\"ב דזבחים (דף י\\\"ז:).\",1,0],[8,361,4,1,\"ומה שכתב אף על פי שלא שהה שם. בפרק שני דשבועות (דף ט\\\"ז:). ואם יקשה עליך היאך אפשר לו לעבוד ולא ישהה ביארו רבינו בסמוך.\",2,0],[8,361,4,1,\"ומה שכתב וחייב מיתה בידי שמים. בסוף פרק הנשרפין (סנהדרין דף פ״ד).\",3,0],[8,361,4,1,\"ומה שכתב שנאמר וינזרו מקדשי בני ישראל וכו' ולהלן הוא אומר ומתו בו כי יחללוהו מה חילול האמור שם חייב מיתה בידי שמים וכו'. שם:\",4,0],[8,361,4,2,\"אף ע״פ שאם עבד בטומאה אינו חייב וכו'. משנה בס״פ הנשרפין (סנהדרין דף פא:):\",1,0],[8,361,4,3,\"והיאך אפשר לו לעבוד ולא ישהה וכו' וביציאתו היה צנור בידו וכו'. בפ\\\"ב דשבועות (דף י\\\"ז:):\",1,0],[8,361,4,4,\"וכן טמא שטבל ועבד קודם שיעריב שמשו עבודתו פסולה. ברפ\\\"ב דזבחים (דף י\\\"ז).\",1,0],[8,361,4,4,\"ומ״ש וחייב מיתה בידי שמים שנאמר ולא יחללו שם אלהיהם. בס״פ הנשרפין (סנהדרין דף פ״ג:) טבול יום ששימש מנ״ל דתניא רבי סימאי אומר רמז לטבול יום שאם עבד חילל מנין תלמוד לומר קדושים יהיו לאלהיהם ולא יחללו אם אינו ענין לטמא ששימש דנפקא לן מוינזרו תנהו ענין לטבול יום ששימש ויליף חילול חילול מתרומה מה להלן במיתה אף כאן במיתה.\",2,0],[8,361,4,4,\"ומ\\\"ש רבינו שעדיין טמא הוא שנאמר ובא השמש וטהר וכו' הוא לתת טעם למה חלוק ממחוסר כפורים.\",3,0],[8,361,4,4,\"וכתב הראב״ד על מ״ש רבינו טמא שטבל ועבד קודם שיעריב שמשו חייב מיתה בידי שמים א״א כיון שטבול יום שנכנס למקדש בכרת וכו'. ויש לתמוה כיון דקושיא זו לכ״ע איתא למה כתבה בהשגות כאילו הוא פרטית לרבינו. ונ״ל שמכח קושיא זו היה אפשר לפרש דהא דתנן בפרק י״א ממסכת פרה (משנה ד') ואם בא אל המקדש בין לפני ביאתו בין לאחר ביאתו חייב היינו חיוב מלקות אבל מכרת פטור מאחר שטבל אבל לרבינו שכתב חייב כרת קשיא וי״ל דיש במיתה בידי שמים משא״כ בכרת דכרת היינו שאינו מגיע לששים שנה כדאמרינן בשילהי מועד קטן (דף כ״ח) ואיכא נמי כרת דיומי כדאמרי' נמי התם ומיתה בידי שמים אין לה זמן קבוע כמו שכתבו התוס' בפרק במה מדליקין (שבת דף כ״ה) בד״ה כרת ועוד יש ביניהם דכרת הוא וזרעו נכרתים משא״כ במיתה בידי שמים כמו שכתבו התוס' בפ״ק דיבמות (דף ב') ועוד יש ביניהם שהחייב מיתה בידי שמים עלה מות בחלוניו וב״ח מקנה קנינו מתים פרתו רועה באפר והיא מתה תרנגולתו רועה באשפה והיא מתה.\",4,0],[8,361,4,4,\"ומ\\\"ש אבל מחוסר כפורים שעבד אע\\\"פ שעבודתו פסולה וחילל. ברפ\\\"ב דזבחים (דף י\\\"ז).\",5,0],[8,361,4,4,\"ומ\\\"ש ה\\\"ז פטור. יש לתמוה דהא בס\\\"פ הנשרפין מני בכלל אלו שבמיתה מחוסר כפורים ואמרי' בגמרא (דף פ\\\"ג:) מנ\\\"ל אמר רב הונא דאמר קרא וכפר עליה הכהן וטהרה מכלל שהיא טמאה ואמר מר טמא ששימש במיתה ורבינו עצמו בפרק י\\\"ט דסנהדרין מנה מחוסר כפורים בכלל מחוייבי מיתה שחייבים מלקות וצ\\\"ע וכבר השיגו הראב\\\"ד וכתב אבל מחוסר כפורים שעבד אע\\\"פ שעבודתו פסולה וחילל הרי זה פטור אמר אברהם והא אמרינן במכות עוד טומאתו בו וכו'. ולא ידעתי למה לא הקשה עליו גם מדידיה אדידיה כמו שהקשיתי וסמ\\\"ג כתב בסי' ש\\\"ה מחוסר כפורים שעבד תניא שהוא במיתה ועבודתו פסולה וחילל עכ\\\"ל ומאחר שהוא רגיל להביא דברי רבינו בכל מקום יש לתמוה עליו למה לא הביאם גם פה ויקשה מההיא ברייתא. ולענין מה שהשיג הראב\\\"ד יש לומר שרבינו סובר דהלכה כמ\\\"ד מחוסר כפורים דזב לאו כזב דמי כמו שכתבתי בפ\\\"ג:\",6,0],[8,361,4,6,\"כהן שעבד ואח״כ נודע שהיה טמא וכו' ואם היא טומאת התהום הציץ מרצה וכו'. משנה פרק כיצד צולין (פסחים דף פ':) ואע״ג דבענין פסח איתניא משמע דה״ה לכל הקרבנות אלא שיש ביניהם קצת חילוק כמו שאכתוב בסמוך.\",1,0],[8,361,4,6,\"ומ\\\"ש ואפילו נודע לו שהוא טמא קודם שיזרוק הדם וזרק הורצה וכו'. שם וכלישנא בתרא אלא דאיכא למידק שממ\\\"ש רבינו נראה דלכתחילה אינו זורק כל שנודע לו ובפרק ז' מהלכות קרבן פסח נראה מדבריו דלכתחילה נמי שוחט וזורק וצריך לומר שטעמו משום דשאני קרבן פסח שהוא חובה והיא מצוה עוברת.\",2,0],[8,361,4,6,\"ומ\\\"ש וכבר ביארנו טומאת התהום. בנזירות פ\\\"ו:\",3,0],[8,361,4,7,\"וכן הציץ מרצה על טומאת דברים הקרבין וכו' אבל אינו מרצה על טומאת הנאכלים. בפ' כיצד צולין (פסחים דף ע״ז) אמרי' דליכא תנא דשמעת ליה מרצה על אכילות אלא ר״א ופירש״י על אכילות על טומאה שנגעה בבשר ובשירי מנחה הנאכלים אלא על טומאת הדם וקמצים ואימורים.\",1,0],[8,361,4,7,\"ומה שכתב ולא על טומאת האדם שנטמא בטומאה ידועה. משנה שם (דף פ':) שהציץ מרצה על טומאת הדם ואינו מרצה על טומאת הגוף נטמא טומאת התהום הציץ מרצה.\",2,0],[8,361,4,7,\"ומ\\\"ש אלא א\\\"כ היתה הטומאה הדחויה בציבור שהציץ מרצה עליה. משנה שם (דף ע\\\"ט) נטמא הקהל או רובו או שהיו כהנים טמאים והקהל טהורים יעשנו בטומאה:\",3,0],[8,361,4,8,\"ומה שכתב ואין הציץ מרצה אלא בזמן שהוא על מצחו וכו'. בפרק כיצד צולין (פסחים דף ע\\\"ו) ובריש יומא (דף ד') פלוגתא דרבי יהודה ורבי שמעון ופסק כרבי יהודה. וכתב הר\\\"י קורקוס ז\\\"ל דאיכא למידק דבגמרא אקשו לר\\\"י ושני דקסבר דטומאה הותרה בצבור ומאחר שפסק רבינו בסוף הפרק שטומאה דחויה היא בצבור הוי תרתי דסתרן. ותירץ שסובר רבינו שאותה קושיא אינה מוכרחת לומר כן ותירץ לו כן לרווחא דמילתא והאריך בדבר להוכיח כן:\",1,0],[8,361,4,9,\"כל קרבן שאין קבוע לו זמן וכו' וכל קרבן שקבוע לו זמן וכו'. משנה רפ\\\"ב דתמורה (דף י\\\"ד). בס\\\"פ ולא כל הטומאות הוא דוחה אלא טומאת המת לבדה. פשוט בפ\\\"ב דזבחים (דף כ\\\"ב):\",1,0],[8,361,4,10,\"כל קרבנות הצבור קבוע זמנן וכו'. ברפ״ב דתמורה (דף י״ד) תנן יש בקרבנות הצבור מה שאין בקרבנות היחיד שקרבנות הצבור דוחים את השבת ואת הטומאה וקרבנות יחיד אינם דוחים לא את השבת ולא את הטומאה אמר ר״מ והלא חביתי כהן גדול ופר י״ה קרבן היחיד ודוחין את השבת ואת הטומאה אלא שזמנו קבוע ופירש״י אלא שזמנו קבוע כלומר אין הטעם תלוי אלא בקביעות זמן אותן שזמנן קבוע שאם עבר הזמן אין להם תשלומין דוחים שבת וטומאה אפי' דיחיד וכל שאין להם זמן קבוע אינם דוחים שבת וטומאה ואפילו דצבור כגון פר העלם דבר של צבור ושעירי ע״ז עכ״ל ומשמע שדברי ר״מ הם דברים אמתיים וכן כתב רבינו בפירוש המשנה וכן משמע בגמרא פרק הוציאו לו (יומא דף נ') וכן בפ״ק דיומא עלה ז' וא״כ יש לתמוה על זה שכתב כאן כל קרבנות הצבור קבוע להם זמן שהרי פר העלם דבר של צבור ושעירי ע״ז אין זמנן קבוע ואפשר דה״ק כל קרבנות הצבור הקבועים:\",1,0],[8,361,4,11,\"ומ״ש וכל קרבן מהם שקרב בטומאה אינו נאכל וכו'. בפרק כיצד צולין (פסחים דף ע״ו) תנן חמשה דברים באים בטומאה ואינם נאכלים בטומאה העומר ושתי הלחם ולחם הפנים וזבחי שלמי צבור ושעירי ר״ח ופירש״י אין לך קרבן ציבור נאכל אלא אלו:\",1,0],[8,361,4,12,\"כיצד דוחה את הטומאה וכו'. משנה שם (דף ע\\\"ט) נטמא קהל או רובו או שהיו הכהנים טמאים והקהל טהורים יעשה בטומאה.\",1,0],[8,361,4,12,\"ומ\\\"ש או שהיו אלו ואלו טהורים והיו כלי השרת טמאים למת. שם בברייתא.\",2,0],[8,361,4,12,\"ומ\\\"ש ויתעסקו בו הטמאים והטהורים כאחד ויכנסו כולם לעזרה. שם בברייתא שאין קרבן ציבור חלוק ופירש\\\"י שאין קרבן ציבור הבא בטומאה חלוק מאחר שהקרבן רובו בטומאה אף היחיד עושה בטומאה.\",3,0],[8,361,4,12,\"ומ״ש אבל הטמאים בטומאה אחרת וכו' לא יתעסקו ולא יכנסו לעזרה ואף ע״פ שנעשה בטומאה ואם עברו ועשו או נכנסו לעזרה חייבים כרת על הביאה ומיתה על העבודה וכו'. בפרק מי שהיה טמא (פסחים דף צ״ה:) תנן הפסח שבא בטומאה לא יאכלו ממנו זבין וזבות נדות ויולדות ואם אכלו פטורים [מכרת] ור״א פוטר אף על ביאת המקדש ופירש״י ואם אכלו פטורים מכרת דאוכל קדשים בטומאה כדיליף בברייתא בגמרא אבל מביאת מקדש לא פטרינהו [רחמנא] וידוע דהלכה כת״ק:\",4,0],[8,361,4,13,\"ומ\\\"ש ופסח שבא בטומאה וכו'. שם בעיא ואיפשיטא בתרי לישני חד לחומרא וחד לקולא ופסק לקולא משום דמספיקא לית לך לחיובי ועוד דלישנא בתרא לקולא:\",1,0],[8,361,4,14,\"היו מקצת בית אב טמאים ומקצתם טהורים וכו'. בפ״ק דיומא (דף ו':) איתמר טומאת המת רב נחמן אמר הותרה היא בציבור ורב ששת אמר דחויה היא בציבור [כל] היכא דאיכא טמאים וטהורים בההוא בית אב כ״ע לא פליגי דטהורים עבדי טמאים לא עבדי כי פליגי לאהדורי ולאתויי טהורים מבית אב אחרינא רב נחמן אמר היתר היא בציבור ולא מהדרינן ורב ששת אמר טומאה דחויה היא בצבור [ומהדרינן] ופסק רבינו כרב ששת משום דהלכתא כוותיה באיסורי ועוד דאמרי' בפ' כיצד צולין (פסחים דף ע״ז) דליכא תנא דשמעת ליה דאמר טומאה הותרה בציבור אלא רבי יהודה ואמרינן בתר הכי (דף ע״ז) דרב חסדא סבר טומאה דחויה היא בצבור וכן א״ר יצחק וסובר רבינו דלמ״ד דחויה היא אפי' היתה כל המשמרה טמאה מחזירים על משמרה אחרת ואע״פ שלא הזכירו בגמ' אלא לחזור על בית אב אחר לאו דוקא אלא משום דלרב נחמן אפי' על בית אב אחר אין מחזירין נקטיה.\",1,0],[8,361,4,14,\"ומ\\\"ש אם היו רוב הכהנים הנכנסים בירושלים בזמן הקבוע טמאים יעשו בטומאה:\",2,0],[8,361,4,16,\"ומנין שטומאת מת דחויה היא בצבור וכו'. סיפרי פרשת בהעלותך:\",1,0],[8,361,4,17,\"והרי הדבר מפורש בכתובים שנאמר שם בדברי הימים אצל חזקיהו כי רבת העם אשר לא התקדשו וכו'. ומה שכתב ומהו זה שנאמר כי אכלו את הפסח בלא ככתוב כלומר אם תאמר אדרבה משם ראיה שאין דוחין טומאה מפני קרבן ציבור שהרי חזקיהו שדחאה כתוב עליו כי אכלו את הפסח בלא ככתוב והוצרך לבקש רחמים על שעשה כן לא מפני כך כתוב עליו כן אלא מפני שעיברו אותה השנה מפני הטומאה:\",1,0],[8,361,4,18,\"ועוד אחרת היתה שם וכו'. בפ\\\"ק דסנהדרין (דף י\\\"ב) ת\\\"ר אין מעברין את השנה מפני הטומאה ואם עיברוה מעוברת רבי יהודה אומר אינה מעוברת א\\\"ר יהודה מעשה בחזקיה מלך יהודה שעיבר השנה מפני הטומאה ובקש רחמים על עצמו רבי שמעון אומר אם עיברוה מפני הטומאה מעוברת אבל מפני מה ביקש רחמים על עצמו שאין מעברין אלא אדר והוא עיבר ניסן בניסן ומפרש בגמרא דחזקיה טעה בדשמואל דאמר שמואל אין מעברין את השנה ביום ל' של אדר הואיל וראוי לקובעו ניסן והוא [עיברו משום] דסבר הואיל וראוי לא אמרינן רבי שמעון בן יהודה אומר מפני שהשיא את ישראל לעשות פסח שני ומפרש בגמרא דהיינו כגון שהיו ישראל מחצה טמאים ומחצה טהורים ונשים משלימות לטהורים ועודפות עליהם מעיקרא סבר נשים בראשון חובה דהוו מיעוטן טמאים ומיעוטן מידחו לפסח שני ולבסוף סבר נשים בראשון רשות דהוה ליה טמאים רובא ורובא לא מידחו לפסח שני ומשמע דלרבי יהודה לא ביקש רחמים מפני שעיבר ניסן בניסן אלא מפני שעיבר מפני הטומאה ולרבי שמעון לא ביקש רחמים מפני שעיבר מפני הטומאה אלא מפני שעיבר ניסן בניסן וא\\\"כ יש לתמוה על רבינו היאך כתב שני הטעמים דהוי כמזכה שטרא לבי תרי ועוד דכיון דבדיעבד מעוברת למה הוצרך לבקש רחמים ואין לומר דאעפ\\\"כ כיון דלכתחילה אין מעברין הוצרך לבקש רחמים דהא משמע בברייתא שכתבתי בסמוך שאילו היתה מעוברת בדיעבד לא היה צריך לבקש רחמים ועוד שכתב רבינו שביקש רחמים על עצמו ועל החכמים שהסכימו עמו דהא תניא בתוספתא שזה אחד משלשה דברים שעשה חזקיהו ולא הודו לו ועוד למה השמיט טעמו של רבי שמעון בן יהודה. ומיהו בההיא דעל החכמים איכא למימר שאע\\\"פ שרוב החכמים לא הודו לו קצת חכמים הסכימו עמו ובסמ\\\"ג כתוב שריו במקום החכמים ומכל מקום קושיי קמאי צריכים יישוב. ונ\\\"ל שרבינו כתב דעיברה מפני הטומאה כדברי רבי יהודה דהלכה כוותיה לגבי ר\\\"ש ואף ע\\\"פ דמשמע דאי הואי מעוברת בדיעבד כשעיברוה מפני הטומאה לא היה צריך לבקש רחמים היינו לרבי שמעון אבל לרבי יהודה אע\\\"ג דבדיעבד מעוברת מכל מקום הוצרך לבקש רחמים על עצמו וסובר רבינו שאע\\\"פ שעיבר השנה בטומאה כדרבי יהודה דקי\\\"ל כוותיה ופשטא דקראי הכי מוכחי אין לנו לדחות ולומר שלא עיבר ניסן דהא סתם לן תנא דתוספתא הכי הילכך אית לן למימר דתרתי עבד חדא דעיבר ניסן ועוד שעיברה מפני הטומאה ולא חש רבינו לכתוב דברי ר\\\"ש בן יהודה משום דיחידאה הוא דהא רבי יהודה ור\\\"ש פליגי עליה:\",1,0],[8,361,5,1,\"מצות עשה לקדש הכהן העובד ידיו ורגליו וכו'. פשוט הוא בפסוק.\",1,0],[8,361,5,1,\"ומה שכתב ועבודתו פסולה. משנה בפרק שני דזבחים (דף ט\\\"ו ע\\\"ב).\",2,0],[8,361,5,1,\"ומה שכתב בין כהן גדול בין כהן הדיוט דכתיב והיתה לו ולזרעו חק עולם:\",3,0],[8,361,5,2,\"ומה שכתב ומנין שעבודתו פסולה וכו'. בפרק שני דזבחים (דף י\\\"ט):\",1,0],[8,361,5,3,\"אין הכהן צריך לקדש בין כל עבודה ועבודה וכו'. שם תנו רבנן קידש ידיו ורגליו ביום אין צריך לקדש בלילה בלילה צריך לקדש ביום דברי רבי שהיה רבי אומר לינה מועלת בקידוש ידים ורגלים רבי אלעזר ברבי שמעון אומר אין לינה מועלת בקידוש ידים ורגלים תניא אידך היה עומד ומקריב על גבי המזבח כל הלילה לאורה טעון קידוש ידים ורגלים דברי רבי רבי אלעזר בר\\\"ש אומר כיון שקידש ידיו ורגליו מתחלת עבודה אפילו מכאן עד עשרה ימים אינו צריך לקדש ופירש\\\"י אינו צריך לקדש בלילה אם לא יצא ולא הסיח דעתו. צריך לקדש ביום כדמסיים מילתיה שהלינה פוסלת בקידוש ועמוד השחר הוא העושה לינה עכ\\\"ל. ופסק רבינו כרבי משום דקי\\\"ל הלכה כרבי מחבירו.\",1,0],[8,361,5,3,\"ומ\\\"ש והוא שלא יצא מן המקדש. מתבאר שם:\",2,0],[8,361,5,3,\"ומ\\\"ש ולא יישן ולא יטיל מים ולא יסיח דעתו. היסח דעת מבואר שם וממילא משמע לשינה דסתם ישן מסיח דעתו ומטיל מים משנה פרק הממונה (דף כ\\\"ח).\",3,0],[8,361,5,3,\"ומ\\\"ש ואם עשה אחד מארבעתן צריך לחזור ולקדש. כלומר ואם לא קידש ועבד עבודתו פסולה חוץ מהיוצא מהמקדש כדבסמוך:\",4,0],[8,361,5,5,\"יצא מהמקדש וחזר ועבד וכו'. בפ\\\"ב דזבחים (דף כ':) בעיא דלא איפשיטא ומספיקא לא פסלינן עבודה. ודע דבגמרא בעינן למפשטה מדתניא יצאו ידיו הרי אלו בקדושתן ודחי יצאו ידיו לא קא מיבעיא לן כי קא מיבעיא לן יצא כל גופו מאי וקשיא לי נפשטה מאידך גיסא דדוקא יצאו ידיו הרי אלו בקדושתן הא יצא גופו לא דא\\\"ל נשמעינן יצא כל גופו וכל שכן ליצאו ידיו וי\\\"ל דאי הוה תני יצא כל גופו ה\\\"א דוקא יצא כל גופו ולא ידיו אבל אם הוציא ידיו אפי' בלחודייהו נמי:\",1,0],[8,361,5,5,\"וזה הכלל היה במקדש וכו' וכל המיסך את רגליו וכו'. משנה בפ' הממונה (דף כ\\\"ח):\",2,0],[8,361,5,5,\"יצא חוץ לחומת העזרה וכו'. ברייתא בפרק שני דזבחים (דף כ':) יצא חוץ למחיצת חומת העזרה אם לשהות טעון טבילה אם לפי שעה טעון קידוש ידים ורגלים ובגמרא בעי למיפשט מיניה בעיין דבסמוך ודחי הב\\\"ע כגון שיצא להסך את רגליו ופירש\\\"י דקתני אם לשהות טעון טבילה שיצא להסך רגליו לגדולים ודכוותיה סיפא דקתני אם לפי שעה טעון קידוש שיצא להטיל מים והדבר מבואר שיש חסרון בלשון רבינו וכך צריך להגיה יצא חוץ לחומת העזרה אם לשהות בחוץ יצא כשחוזר טעון טבילה ואם לחזור מיד יצא כשחוזר טעון קידוש ידים ורגלים בלבד וכן מצאתי בספר מוגה.\",3,0],[8,361,5,5,\"ומ\\\"ש ואם לא טבל ולא קידש ועבד וכו' עבודתו כשירה. היינו מדלא איפשיטא בעיין דבסמוך מספקא לן אי האי ברייתא ביצא להסך רגליו או להטיל מים וכדדחי אי לא הילכך מספיקא לא פסלינן עבודה בדיעבד:\",4,0],[8,361,5,5,\"הוציא ידיו חוץ לחומת העזרה אינו צריך לחזור כו'. שם ברייתא כתבתיה בסמוך:\",5,0],[8,361,5,6,\"נטמאו ידיו מטבילן והן טהורים וכו'. שם בברייתא:\",1,0],[8,361,5,6,\"נטמא גופו באכילת אוכלים טמאים וכו'. שם (דף כ':) איבעיא להו טומאה מהו שתועיל לקידוש ידים ורגלים וכו' תיפוק לי כיון דבעי למעבד הערב שמש אסוחי מסח דעתיה כגון דאיטמי סמוך לשקיעת החמה ומשום דהאי מילתא לא שכיחא נקט רבינו במקום נטמא סמוך לשקיעת החמה אכל אוכלים טמאים וכו' שאינו צריך הערב שמש ובעיין לא איפשיטא ומספיקא לא פסלינן עבודה בדיעבד:\",2,0],[8,361,5,7,\"כהן גדול שלא טבל ולא קידש ידיו ורגליו וכו'. ברייתא וגמרא שם (דף י\\\"ט):\",1,0],[8,361,5,8,\"קידש ידיו היום צריך לחזור ולקדש למחר וכו' שהידים נפסלות בלינה. היינו כרבי בברייתא שכתבתי בפרק זה:\",1,0],[8,361,5,8,\"קידש בלילה וכו'. גם זה כרבי בברייתא שכתבתי בפרק זה:\",2,0],[8,361,5,9,\"קידש ידיו ורגליו לתרומת הדשן וכו' אינו צריך לחזור ולקדש אחר שהאיר היום וכו'. שם (דף כ') אמר רבי יוחנן קידש ידיו ורגליו לתרומת הדשן למחר אינו צריך לקדש שכבר קידש מתחילת עבודה למאן אי לרבי הא אמר פסלא לינה אי לרבי אלעזר ברבי שמעון הא אמר אין צריך לקדש אפילו מכאן עד עשרה ימים אמר אביי לעולם לרבי ולינה דרבנן היא ומודה דמקרות הגבר ועד צפרא לא פסלא לינה רבה אמר לעולם רבי אלעזר ברבי שמעון דתחלת עבודה ולא בסוף עבודה ופירש\\\"י מתחילת עבודה שזו תחילת עבודת יום הבא. לעולם רבי אלעזר ברבי שמעון וראה רבי יוחנן דבריו של רבי אלעזר נכונים במקדש בתחילת עבודת היום דלא פסל בה לינה ולא במי שקידש בלילה להקטיר חלבים שהוא סוף עבודת יום אתמול:\",1,0],[8,361,5,10,\"מצוה לקדש ממי הכיור ואם קידש מאחד מכלי השרת ה\\\"ז כשר. ברייתא בפרק שני דזבחים. ומפרש טעמא משום דכתיב ירחצו לרבות כלי שרת.\",1,0],[8,361,5,10,\"ומ\\\"ש אבל בכלי החול אין מקדשין. שם (דף כ\\\"ב) ומפרש טעמא משום דכתיב ממנו למעט כלי חול.\",2,0],[8,361,5,10,\"ומ\\\"ש קידש בכלי שרת בחוץ וכו'. ברייתא שם (דף כ':).\",3,0],[8,361,5,10,\"ומ\\\"ש ואין מקדשין בתוך הכיור וכו'. שם (דף כ\\\"א) בעיא דלא איפשיטא הילכך לכתחילה לא יקדש אלא ממנו אבל אם קידש בתוכו ועבד מספיקא לא מחללינן עבודה:\",4,0],[8,361,5,11,\"הטביל ידיו ורגליו במי מקוה אפי' במעיין אין זה קידוש כלל וכו'. ברייתא שם (דף כ:) טבל במי מערה ועבד עבודתו פסולה ופירש\\\"י במי מערה שהם כשרים לטבילה וה\\\"ה למים חיים:\",1,0],[8,361,5,11,\"ובכל כלי הקדש מקדשין בין שיש בהם רביעית וכו'. שם (דף כ\\\"א:) אמר ר' יוסי בר חנינא כל כיור שאין בו כדי לקדש ארבעה כהנים ממנו אין מקדשין בו שנאמר ורחצו ממנו משה אהרן ובניו מיתיבי בכל הכלים מקדשין בין שיש בהן רביעית בין שאין בהן רביעית ובלבד שיהו כלי שרת אמר רב אדא בר אחא בקודח בתוכו ופירש\\\"י בקודח בתוכו קודח דפנו של כיור ותוחב בתוכו כלי קטן ומקצתו לחוץ ויוצק ממי הכיור ומוציא אבל באפי נפשיה בעינן שיעור ארבעה כהנים ולפי זה יש קיצור בדברי רבינו שה\\\"ל לפרש דהא דמכשירין באין בו רביעית היינו דוקא בקודח בתוכו והתוספות פי' בקודח מתוכו היינו שנוטל ממימיו בכלי קטן וכשר לקדש כיון שבאין מכלי גדול ורבי' אפשר שהיה מפרש כפי' התוספות. ולפיכך לא חש לפרש שמאחר שכתב בסמוך שצריך להיות בכיור מים כדי לקדש ארבעה כהנים ממילא משמע שכשכתב שמקדשין בכלי שרת אפי' אין בהם רביעית בנוטל בכלי שרת מהכיור היא דאל\\\"כ הוה עדיף שאר כלי שרת מכיור ונראה שגם הראב\\\"ד היה מפרש כדברי התוספות ולפיכך לא כתב על רבינו בדרך השגה אלא כמבאר תוספת ביאור שכתב וז\\\"ל בין שאין בהם (כדי) רביעית א\\\"א ובקודח מן הכיור שיש בו לקדש ממנו ד' כהנים:\",2,0],[8,361,5,12,\"כל המימות כשרים וכו'. שם (דף כ\\\"ב:) פלוגתא דתנאי בברייתא ופסק כחכמים.\",1,0],[8,361,5,12,\"ומ\\\"ש ובלבד שלא ישתנה מראיהן וכו'. טיט הנרוק וכו' מימרא דר\\\"ל שם:\",2,0],[8,361,5,13,\"כמה מים צריכים להיות בכיור וכו'. מימרא שם כתבתיה בסמוך וכתב רבינו פסוק הכתוב בפרשת כי תשא שאין כתוב בו אלא אהרן ובניו והוצרך לכלול פינחס עמהם כדי שיהיו ד' ותמיהא לי שבזמן שנאמרה אותה פרשה עדיין לא מתו נדב ואביהוא וא\\\"כ הוה ליה לאצרוכי שיהיו מים בכיור כדי לקדש ה' או ששה ורש\\\"י גריס ורחצו ממנו משה ואהרן תרין ובניו תרין והוא פסוק הכתוב בפרשת פקודי והשתא ניחא דה\\\"ק יהיה בכיור מים שיעור שירחצו ממנו משה ואהרן ושנים מבניו דמיעוט רבים שנים דאם לא כן הול\\\"ל וכל בניו:\",1,0],[8,361,5,14,\"מי כיור נפסלין בלינה כמו שביארנו. בספ\\\"ג מהלכות בית הבחירה:\",1,0],[8,361,5,14,\"וכיצד היו עושין משקעים אותו במי מקוה כו'. בפרק הממונה (דף ל\\\"ז) תנן אף הוא עשה מוכני לכיור שלא יהיו מימיו נפסלין בלינה ומפרש בגמרא דמוכני היינו גלגלא לשקועי ליה. וביארתי זה בספ\\\"ג מהלכות בית הבחירה:\",2,0],[8,361,5,15,\"הים שעשה שלמה כמקוה היה וכו'. ירושלמי פרק ג' דיומא:\",1,0],[8,361,5,16,\"כיצד מצות קידוש וכו'. פלוגתא דתנאי בברייתא פרק שני דזבחים (דף י\\\"ט:) ופסק כת\\\"ק.\",1,0],[8,361,5,16,\"ומ\\\"ש וכל החוצץ בטבילה חוצץ בקידוש ידים. ומ\\\"ש ואינו מקדש כשהוא יושב מפני שהיא כעבודה וכו'. שם וליתיב מיתב ולקדש אמר קרא לשרת ושירות מעומד הוא ופירש\\\"י אמר קרא לשרת או בגשתם אל המזבח לשרת איתקש קידוש לשירות:\",2,0],[8,361,5,17,\"ומ\\\"ש וכל העובד והוא יושב חילל ועבודתו פסולה. שם (דף כ\\\"ג.).\",1,0],[8,361,5,17,\"ומ\\\"ש ואינו לוקה מפני שאזהרה שלו מכלל עשה היא. פשוט הוא:\",2,0],[8,361,5,17,\"וכן כל העוסק בעבודה וכו' עד או על רגלי חבירו פסל. משנה שם (דף ט\\\"ז:).\",3,0],[8,361,5,17,\"ומ\\\"ש וכן אם היה דבר חוצץ בינו ובין הכלי שעבד בו פסל. שם (דף כ\\\"ד) ופירש\\\"י לא יהא דבר חוצץ בין כהן לכלי [שרת] בקבלת הדם כדכתיב ולקח הכהן שתהא לקיחה בעצמו של כהן.\",4,0],[8,361,5,17,\"ומ\\\"ש ואין עבודה אלא בימין ואם עבד בשמאל פסול. שם במשנה.\",5,0],[8,361,5,17,\"ומ\\\"ש ואינו לוקה. היינו מדגמרינן לה מדכתיב באצבע ולקח מלמד שלא תהא קבלה אלא בימין באצבע ונתן מלמד שלא תהא נתינה אלא בימין וכיון דאתיא מלאו הבא מכלל עשה אין לוקין עליו:\",6,0],[8,361,5,18,\"רגלו אחת על הכלי ורגלו אחת על הרצפה. יש בלשון רבינו חסרון וצריך להוסיף רגלו אחת על האבן ורגלו אחת על הרצפה וכך מצאתי בספר מוגה וכך היא שנויה בברייתא שם. וכן מבואר בסוף לשון רבינו שכתב רואין כל שינטל הכלי או האבן:\",1,0],[8,361,5,18,\"קיבל בימין ושמאל מסייעתו עבודתו כשירה וכו'. תוספתא פרק קמא דזבחים:\",2,0],[8,361,5,19,\"נתנדדה אבן מאבני העזרה לא יעמוד עליה בשעת העבודה וכו'. בפ' ב' דזבחים בעי רבי אמי וכו' נדלדלה האבן ועמד עליה מהו היכא דאין דעתו לחברה לא תיבעי לך דודאי חייצא כי תיבעי לך דדעתו לחברה. רבה זוטי בעי לה הכי נעקרה האבן ועמד במקומה מהו וכו' דרך שירות בכך או אין דרך שירות בכך תיקו ורבינו בפרק א' מהלכות בית הבחירה כתב ואם נעקרה אבן אע\\\"פ שהיא עומדת במקומה הואיל ונתקלקלה פסולה ואסור לכהן העובד לעמוד עליה בשעת עבודה עד שתקבע בארץ ויש לתמוה עליו למה השמיט יתר הדברים ולא כתבם לא כאן ולא שם. והראב\\\"ד כתב שם עוד אמרו שם שאם נעקרה האבן ועמד הכהן במקומה בגומא ועבד אין דרך שירות בכך עכ\\\"ל. ויש לתמוה למה החליט המאמר דאין דרך שירות בכך דמשמע דעבודתו פסולה והלא כיון שעלתה בתיקו אין לנו לפסול העבודה מספק ועוד קשיא לי למה לא השיגו על שהשמיט לחלק בין דעתו לחברה לאין דעתו לחברה דבהא עבודתו פסולה ובהא אין לנו כח לפסלה בדיעבד ולדעת רבינו יש לומר שהוא ז\\\"ל סובר דכי אמרינן דהיכא דאין דעתו לחברה ודאי חייצא לא לפסול העבודה קאמר אלא לומר דצריך ליזהר לכתחילה ומיבעיא ליה היכא דדעתו לחברה אי שרי לכתחילה לעמוד עליה וכיון דלא איפשטא נקטינן לחומרא דלכתחילה לא יעמוד עליה בין שדעתו לחברה בין שאין דעתו לחברה ואם עמד עליה בין כך ובין כך עבודתו כשירה ולא חשש לכתוב דין נעקרה האבן ועמד במקומה משום דמשמע דרבה זוטי הוא דבעי לה הכי אבל סתם גמרא לא אסתפקא ליה הא ומשמע דמיפשט פשיטא ליה דדרך שירות בכך:\",1,0],[8,361,6,1,\"כל כהן שיש בו מום בין מום קבוע בין מום עובר. [משנה] בפרק ז' דבכורות (דף מ\\\"ג) מומין אלו בין קבועים בין עוברים פסולים באדם ובפרק טבול יום ובת\\\"כ אין לי אלא בעל מום קבוע בעל מום עובר מנין ת\\\"ל כל אשר בו מום.\",1,0],[8,361,6,1,\"ומה שכתב לא יכנס למקדש מן המזבח ולפנים דכתיב בפרשת אמור גבי בעל מום ואל המזבח לא יגש.\",2,0],[8,361,6,1,\"ומ\\\"ש ואם עבר ונכנס לוקה אע\\\"פ שלא עבד. קשיא לי דבפרק י\\\"ט מסנהדרין נראה מדברי רבינו שאינו לוקה אלא א\\\"כ נכנס להיכל.\",3,0],[8,361,6,1,\"ומ\\\"ש ואם עבד במקדש פסול וחילל עבודה. בקידושין פרק האומר (דף ס\\\"ו:) ובתורת כהנים ובריש פרק מומין אלו (בכורות דף מ\\\"ג) ופרק שמיני דתרומות.\",4,0],[8,361,6,1,\"ומ\\\"ש מפי השמועה למדו שאזהרה זו לא יקרב לעבודה. בתורת כהנים לא יקרב להקריב לחם אלהיו אין לי אלא תמידין שהם קרויים לחם שנאמר את קרבני לחמי לאישי שאר כל הקרבנות מנין ת\\\"ל שוב לחם מנין לרבות את הדם ת\\\"ל להקריב ואומר ויקריבו בני אהרן את הדם אליו:\",5,0],[8,361,6,1,\"וא\\\"ת מה צורך ללמוד מפי השמועה שאזהרה זו לא יקרב לעבודה הרי מפורש הוא בכתוב אשר בו מום לא יקרב להקריב לחם אלהיו ואפשר דה\\\"ק מפי השמועה למדו שאזהרה זו לכל מין קרבן ולדם כדיליף לה מקרא בת\\\"כ שכתבתי בסמוך ועי\\\"ל דקרא כתיב בתר הכי כי כל איש אשר בו מום לא יקרב וה\\\"א דעל קריבה למזבח לבד חייב אע\\\"פ שלא עבד לכך הוצרך ללמוד מפי השמועה שאינו כן:\",6,0],[8,361,6,2,\"ומ\\\"ש וכן בעל מום עובר שעבד פסל ולוקה שנאמר כל איש אשר בו מום לא יקרב. מפי השמועה למדו שזו אזהרה לבעל מום עובר. בתורת כהנים ובריש פרק מומין אלו:\",1,0],[8,361,6,2,\"ואין בעלי מומין שעבדו במיתה אלא במלקות בלבד. בסוף פרק הנשרפין (סנהדרין דף פ״ד) ובת״כ פלוגתא דרבי וחכמים ופסק כחכמים:\",2,0],[8,361,6,3,\"כל המומין כולם וכו'. בפרק טבול יום (זבחים דף צ״ח:) ובתורת כהנים פרשת אמור פ״ב:\",1,0],[8,361,6,4,\"ומה שכתב ולא המומין הכתובים בתורה בלבד וכו' עד ואם היה בו דבר מדברים שהם מפני מראית העין אינו לוקה. בריש פרק מומין אלו (בכורות דף מ\\\"ג):\",1,0],[8,361,6,7,\"אין פוסל באדם אלא מומין שבגלוי וכו' אע״פ שנעשה טריפה עבודתו כשירה. בתוספתא פרק רביעי היה בו מום מבפנים אינו מום שנאמר עור ופסח מה עור ופסח [המיוחדין] מום שבגלוי ואינו חוזר ובסוף פרק מומין אלו (בכורות דף מ״ה:) במשנה אלו כשרים באדם ופסולים בבהמה אותו ואת בנו וטריפה:\",1,0],[8,361,6,8,\"הערל הרי הוא כבן נכר וכו'. בפרק ב' דזבחים (דף י\\\"ט).\",1,0],[8,361,6,8,\"ומ\\\"ש ולוקה כזר שעבד. ברייתא בסוף פרק הנשרפין (סנהדרין דף פ\\\"ג) ערל אונן ויושב אינם במיתה אלא באזהרה ופירש\\\"י ערל שמתו אחיו מחמת מילה ובגמרא ערל מנא לן אמר רב חסדא דבר זה מתורת משה רבינו לא למדנו עד שבא יחזקאל בן בוזי ולמדו כל בן נכר ערל לב וערל בשר לא יבא אל מקדשי לשרתני ופירש רש\\\"י והיינו אזהרה מדברי קבלה בעלמא ולא לקי עלה ורבינו שכתב שלוקה טעמו מדאמרינן בפרק ב' דזבחים עד דאתא יחזקאל מנא לן ואסיקנא גמרא גמירי לה ואתא יחזקאל ואסמכיה אקרא וכיון דגמרא גמירי לה דלא יבא לשרת כי לקי לא משום אזהרה דדברי קבלה לקי אלא משום אזהרה דגמרא ועם כל זה רצה רבינו שיהא נרמז בתורה קצת ולפיכך כתב שהוא כזר:\",2,0],[8,361,6,9,\"כהן שהיה נושא נשים בעבירה וכו' וכן מי שהיה מטמא למתים וכו'. בסוף פרק מומין אלו (בכורות דף מ\\\"ה מ\\\"ו) משנה וגמרא.\",1,0],[8,361,6,9,\"ומה שכתב רבינו עבודתו פסולה היינו לומר דלכתחילה פסול מלעבוד אבל אם עבד לא חילל כמו שכתב בסמוך ובספר מוגה נמצאת מחוק עבודתו פסולה וכתוב במקומו פסול והוא הגירסא הנכונה. ואמרינן התם בגמרא מאי שנא הכא דסגי ליה בקבלה ומאי שנא התם דמדרינן ליה התם יצרו תוקפו. ובקצת ספרי רבינו כתוב גבי מטמא למתים עד שיקבל עליו בנדר והוא טעות סופר וצריך למוחקו ולכתוב במקומו בב\\\"ד וכך מצאתי בספר מוגה:\",2,0],[8,361,6,10,\"כהן שעבד ונבדק ונמצא חלל עבודתו כשירה וכו'. בקידושין פרק האומר (דף ס\\\"ז) תניא היה עומד ומקריב על גבי מזבח ונודע שהוא בן גרושה או בן חלוצה עבודתו כשירה (דכתיב ברך ה' חילו וגו' אפילו חולין שבו תרצה) ואף על פי דבפרק ח' דתרומות פליגי בה רבי אליעזר ורבי יהושע ידוע דהלכה כרבי יהושע דאמר הכי ועוד דגמרא תני סתמא כרבי יהושע ולכאורה הוה משמע דלא מכשרינן אלא מה שעבד קודם שנודע אבל אם עבד אחר שנודע חילל ורבינו משמע ליה דכיון דלא אשכחן בקרא דמחלל עבודתו אדרבה אשכחן בהדיא דלא מחלל מהי תיתי לן לומר שאם עבד לאחר שנודע חילל ותנא אורחא דמילתא נקט דאין דרך לעבוד אחר שנודע:\",1,0],[8,361,6,11,\"בית דין הגדול היו יושבים בלשכת הגזית וכו' עד ומשמש עם אחיו הכהנים. משנה בסוף מדות (פ\\\"ה מ\\\"ד).\",1,0],[8,361,6,11,\"ומ\\\"ש מי שנמצא כשר בייחוסו ונמצא בו מום יושב בלשכת העצים ומתלע עצים למערכה. בפ\\\"ב דמדות (מ\\\"ה).\",2,0],[8,361,6,11,\"ומ״ש וחולק בקדשים עם אנשי בית אב ואוכל. משנה בריש פרק טבול יום (זבחים דף צ״ח:) ובסוף מנחות (דף ק״ט):\",3,0],[8,361,7,3,\"כל המומין הפוסלין כו' וזהו פרטן: חמשה באוזן ואלו הם מי שנפגם סחוס אזנו וכו'. בריש פרק על אלו מומין שוחטין את הבכור (דף ל\\\"ז) נפגמה אזנו מן החסחוס אבל לא מן העור נסדקה אף על פי שלא חסרה ניקבה מלא כרשינה או שיבשה אי זו היא יבשה כל שתנקב ואינה מוציאה טיפת דם ופירש רש\\\"י סחוס תנוך האוזן וכו' אבל לא מן העור דהדרא בריא ולא הוי מומא והאי עור היינו אליה רכה של אזן. פגימה אינה בלא חסרון אבל סדק משמע נמי בלא חסרון ובגמרא וכמה שיעור פגימה כדי שתחגור בה צפורן.\",1,0],[8,361,7,3,\"ומה שכתב מי שהיתה אזנו כפולה לשתים וכו'. משנה שם (מ':) אזן הגדי שהיתה כפולה אמרו חכמים בזמן שהוא עצם אחד מום ואם אינו עצם אחד אינו מום ופירש רש\\\"י שהיתה כפולה שיש לו שתי אזנים מצד אחד אזן בתוך אזן. בזמן שהיא עצם אחד שאין להם אלא תנוך א' שנכפל התנוך העליון לתוכו ונתחבר למטה הרי זה מום ואם אינו עצם אחד שהתנוכים מובדלים למעלה אינו מום וטעמא לא איתפרש לי עכ\\\"ל ורבינו נראה שגורס בהיפך וכתב סמ\\\"ג דהכי גריס בתוספתא והיא הגירסא הנכונה שנימוקה עמה:\",2,0],[8,361,7,4,\"שלשה בריס העין וכו'. שם (דף לח:) במשנה ובגמרא מאי ריס וכו' תורא ברא דעינא ופירש רש״י שורה חיצונה של עין היינו בת עין המכסה את העין ובדברי התוס' בפרק מומין אלו (בכורות דף מ״ג:) בד״ה ושנשרו מבואר יותר שכתבו דהיינו עור המקיף את העין וכתב רבינו בפירוש המשנה ריס עפעף העין:\",1,0],[8,361,7,5,\"שמונה בעין וכו'. בפרק מומין אלו (בכורות דף מ״ד) תנו רבנן עיור בין סומא בשתי עיניו בין באחת מעיניו ובמשנה פ' על אלו מומין (בכורות דף ל״ח:) היה בעינו דק תבלול חלזון נחש עינב איזהו תבלול לבן הפוסק בסירא ונכנס בשחור שחור נכנס בלבן אינו מום [שאין מומין בלבן] חורוור והמים הקבועים ופירש רש״י סירא שורה שבעין סביב לשחור וכו' ואם חוט של לבן יוצא מן הלבן ופוסק אותה שורה ונכנס בשחור הוי מום. שחור ונכנס בלבן אם חוט יוצא מהשחור ופוסק בסירא ונכנס בלבן אינו מום שאין מומין בלבן דלאו עין הוא אלא שומן העין ומפרש בגמרא דחלזון היינו נחש וכתב רבינו בפירוש המשנה דהיינו שיצמח בעין בשר מותר וימשך עד שחופה קצת משחור העין ושמו בערבי טפרא. ומה שהקשה הראב״ד וכתב מי שיצא בשר יתר בעיניו א״א לא ידעתי אם עשה זה כנגד חלזון וכו'. יש לומר שהדבר ברור שיבלת בעיניו השנוי שם היינו שיש בעיניו יבלת שקורין בירוג״ה ואינו ענין לטפרא.\",1,0],[8,361,7,5,\"ומה שכתב רבינו מי שאינו רואה בשתי עיניו וכו' עד מחמת שהיו בה סנורים קבועים היינו חורוור והמים הקבועים.\",2,0],[8,361,7,5,\"ומה שכתב מי שהיתה נקודה לבנה בתוך השחור וכו' עד אבל אם היתה צפה הואיל והיא שחורה בשחור אינו מום. שם בגמרא:\",3,0],[8,361,7,6,\"שלשה בחוטם וכו'. שם במשנה (דף ל\\\"ט) ותניא שם בגמ' ניקבו חוטמין זה לתוך זה מבחוץ ה\\\"ז מום מבפנים אינו מום והשמיטו רבינו מפני שהוא סובר שמום זה מהמיוחדים בבהמה ואינם ראויים להיות באדם כמ\\\"ש בפ\\\"ב מהלכות איסורי מזבח ואיני יודע למה אינם ראויים להיות באדם:\",1,0],[8,361,7,7,\"ששה בפה ואלו הן מי שניקבה שפתו וכו' מי שנסדקה שפתו וכו'. שם במשנה שפמו שניקבה [שנפגמה] שנסדקה ובגמרא אמר רב פפא תורא ברא דשיפתיה.\",1,0],[8,361,7,7,\"ומ\\\"ש מי שעצם לחיו התחתון עודף על העליון. שם במשנה מעשה שהלחי התחתון עודף על העליון ושאל ר\\\"ג לחכמים ואמרו הרי זה מום ובגמרא והא גבי אדם הוא דתנן וכו' איש ששוה בזרע אהרן אבל גבי בהמה לא ותירצו הא דאית בה עצם הא דלית בה עצם פי' כשהעודף הוא בלחי בעצמו בין באדם בין בבהמה הוא מום אבל כשאין עודף אלא השפה בלבד לא עצם הלחי באדם הוי מום ובבהמה אינו מום.\",2,0],[8,361,7,7,\"ומ\\\"ש מי שפיו נבלם מחמת גופו וברייתו וכו'. שם ת\\\"ר פיו בלום ורגליו מבולמות מחמת הרוח אינו מום מחמת העצם ה\\\"ז מום ופירש\\\"י בלום נפוח וכו' ובתוספתא אם מחמת הרוח אינו מום ואם מחמת עצמו הרי זה מום פי' מחמת עצמו מחמת גופו וברייתו כלומר שהיה כך מעצמו מתחלת ברייתו.\",3,0],[8,361,7,7,\"ומ\\\"ש ושניטל רוב המדבר של לשונו. שם במשנה (בכורות דף מ') גבי מומין שמנה אילא ביבנה ואף על פי ששנינו שם שזה אחד מהמומים שאמרו לו חכמים לא שמענו את אלו הא מסיים התם במשנה שבית דין של אחריהם אמרו הרי זה מום וקי\\\"ל כוותייהו משום דבתראי נינהו ועוד שהסכימו לדברי אילא שהיה בקי מאד ועוד שהחכמים שלא הודו לו לא נחלקו עמו ממש אלא אמרו לא שמענו את אלו ואין לא שמענו ראיה:\",4,0],[8,361,7,8,\"שנים עשר באיברי הזרע וכו'. מקרא מפורש ומעוך וכתות ונתוק וכרות ואיפליגו בפרק על אלו מומין (בכורות דף ל\\\"ט:) אי הוי דוקא בגיד או אי הוי בביצים דרבי יהודה אמר כולהו אף בביצים ורבי אליעזר בן יעקב סבר כולהו בגיד דוקא ורבי יוסי סבר מעוך וכתות אף בביצים נתוק וכרות בגיד דוקא ופסק רבינו דלא כרבי אליעזר בן יעקב משום דרבי יהודה ורבי יוסי פליגי עליה ובפלוגתא דרבי יהודה ורבי יוסי פסק כרבי יהודה משום דמסתבר טעמיה דמעוך וכתות ונתוק בחדא מחתא מחתינהו הכא לית לן לפלוגי בינייהו:\",1,0],[8,361,7,8,\"מי שאין לו אלא ביצה אחת וכו'. שם (דף מ') ורבי עקיבא אומר שם שבודקין אותו על ידי מיעוך וכתבו רבינו בפרק שלישי מהלכות בכורות:\",2,0],[8,361,7,8,\"ומ\\\"ש הטומטום והאנדרוגינוס. ג\\\"ז שם (דף מ\\\"א):\",3,0],[8,361,7,9,\"ששה בידים וברגלים ואלו הם הפסח. מבואר בתורה.\",1,0],[8,361,7,9,\"ומ\\\"ש ומי שנשמטה ירכו וכו'. גם זה שם (דף מ') בעל חמש רגלים או שאין לו אלא ג' וכו' השחול והכסול אי זהו שחול שנשמטה יריכו וכסול שאחת מיריכותיו גבוהה.\",2,0],[8,361,7,9,\"ומ\\\"ש מי שנשבר עצם ידו וכו'. משנה שם נשבר עצם ידו או עצם רגלו אף ע\\\"פ שאינו ניכר ובגמרא אינו ניכר מי קא הוי מומא אמר רב פפא אינו ניכר מחמת עצמו אבל ניכר מחמת מלאכה ופירש\\\"י מחמת עצמו שאין השבר נראה אבל ניכר הוא מחמת שצולע והילוך הרגל זו היא מלאכתו עכ\\\"ל. ונראה דביד נמי אע\\\"פ שאין השבר נראה אם כשעושה מלאכה ניכר הוי מום ולא נקט רש\\\"י רגל אלא משום שאין עושין בו מלאכה והוצרך לפרש דהילוכו זו היא מלאכתו ומדברי רבינו נראה דאע\\\"פ שאינו ניכר דקתני לא קאי אלא לעצם רגלו אבל עצם ידו בעינן שיהא ניכר.\",3,0],[8,361,7,9,\"ומ\\\"ש ומי שרגליו מבולמות. שם בברייתא (דף מ':) גבי פיו בלום וכתבתיה בפרק זה:\",4,0],[8,361,7,10,\"ארבעה ראויים להיות בכל הגוף וכו'. שם (דף מ\\\"א) במשנה ואלו שאין שוחטין עליהם לא במקדש ולא במדינה וכו' בעל גרב ובעל יבלת ובעל חזזית ובגמרא [וגרב לא ופירש\\\"י] וגרב לא [הוי מום גמור] והכתיב גרב באורייתא גבי עורת או שבור וכו' וחזזית לא הוי מום והא כתיב ילפת באורייתא [גבי מומין] ותניא [גרב זה החרס ילפת] זו חזזית המצרית וכו' בשלמא חזזית אחזזית לא קשיא כאן בחזזית מצרית כאן בחזזית דעלמא אלא גרב אגרב קשיא גרב אגרב נמי ל\\\"ק הא בלח הא ביבש לח מיתסי יבש לא מיתסי ולא מיתסי והכתיב יככה ה' בשחין מצרים ובגרב ובחרס ומדכתיב ובחרס הרי גרב לח אמור וקאמר אשר לא תוכל להרפא אלא תלתא [גרב] הוי דקרא [גבי מומין] יבש בין מבפנים בין מבחוץ. דמתני' לח מבחוץ ומבפנים. דמצרים לח מבפנים ויבש מבחוץ. הרי דחזזית המצרית וגרב יבש מבפנים ומבחוץ וכן לח מבפנים ויבש מבחוץ הוו מומין קבועים ולח מבפנים ומבחוץ הוי מום שאינו קבוע ואם כן צריך לומר דגרב יבש שכתב כאן רבינו היינו אפילו לח מבפנים ויבש מבחוץ.\",1,0],[8,361,7,10,\"ומה שכתב וזהו הגרב האמור בתורה אע\\\"ג דבגמרא אמרו דקרא יבש מבפנים ומבחוץ דמצרית לח מבפנים ויבש מבחוץ לאו למימרא דמצרית לאו היינו דקרא דגבי מומין דלא אתא אלא לפרושי מאי ניהו דמצרית ומ\\\"מ כיון דמום קבוע הוא דכתיב אשר לא תוכל להרפא בכלל גרב דקרא דגבי מומין הוא.\",2,0],[8,361,7,10,\"ומה שכתב מי שיש בו יבלת שיש בה עצם וזהו יבלת. שם בגמרא (דף מ':).\",3,0],[8,361,7,10,\"ומה שכתב מי שיש בו חזזית מצרית. שם (דף מ\\\"א) במשנה ובגמרא:\",4,0],[8,361,7,11,\"כל עצם שבגלוי שנחרץ בו חריץ וכו'. במשנה שם (דף מ' ע\\\"ב) שנפגם עצם ידו או עצם רגלו ופירש\\\"י נפגם שניכר המום.\",1,0],[8,361,7,11,\"ומ\\\"ש ואין הצלעות בכלל עצמות שבגלוי. בתוספ' פ\\\"ד נשתברו רוב צלעותיו או שהיה בו מום מבפנים אינו מום שנאמר עור ופסח מה עור ופסח המיוחדים מום שבגלוי ואינו חוזר ומשמע לרבינו דמדסמכיה למום מבפנים מההוא טעמא הוא דלא הוי מום והכי דריש לה בתורת כהנים בהדיא יכול שאני מרבה שבר צלע תלמוד לומר שבר יד או שבר רגל מה אלו מיוחדים שמומן בגלוי ואין חוזרין יצא שבר צלע שמומו בגלוי:\",2,0],[8,361,7,12,\"ועוד יש שם שלשה מומין וכו' והמזוהם. שם (דף מ\\\"א) במשנה זקן וחולה ומזוהם ובספ\\\"ק דחולין (דף כ\\\"ד) ת\\\"ר משיביא שתי שערות עד שיזקין כשר לעבודה וכו' עד שיזקין עד כמה א\\\"ר אלעזר א\\\"ר חנינא עד שירתת ופירש\\\"י ידיו ורגליו רותתין מאין כח.\",1,0],[8,361,7,12,\"ומ״ש אבל הטריפה כשר באדם ופסול בבהמה וכן יוצא דופן וכו'. משנה בסוף פרק מומין אלו (בכורות דף מ״ו:):\",2,0],[8,361,7,13,\"המזוהם. כבר כתבתי בסמוך דבמתני' מיתני גבי מומי בהמה.\",1,0],[8,361,7,13,\"ומ״ש וכהן שהוא מזוהם בזיעתו רוחץ ושף כל גופו בבושם ועובד היה ריח פיו רע נותן בפיו פלפל או זנגביל וכיוצא בהן ועובד. בס״פ המדיר (כתובות דף ע״ה).\",2,0],[8,361,7,13,\"ומ\\\"ש ואם עבד בזיהום זיעתו או בזיהום פיו הרי זה חילל עבודתו. כן משמע מדחשיב להו מומין בפרק ב' מאיסורי מזבח מנה רבינו המומין המיוחדים בבהמה:\",3,0],[8,361,8,1,\"כל המומין המיוחדים באדם וכו'. בריש פרק מומין אלו (בכורות דף מ״ג) בין קבועין בין עוברים פסולים באדם יתר עליהם האדם הכילון והלפתן והמקבן ושראשו שקוע וסקיפס ובגמרא כילון דדמי רישיה לאכלא לפתן דדמי [רישיה] לגרגלידא דלפתא תנא וצוארו עומד באמצע ראשו. מקבן דדמי רישיה למקבת ושראשו שקוע מלפניו. וסקיפס מאחריו כדאמרי אינשי שקיל פיסא. וכתב רבינו בפי' המשנה אכלא כלי שיש לו צואר ארוך ששואבין בו היין מהחבית וענין הדמיון הזה שיהא אמצע ראשו בולט גבוה למעלה והלפתן נגזר מלפת והוא שיהא ראשו על צוארו כראש הלפת על העלין שלה וכו'. המקבן [גזור מן המקבות והוא] שיהא ראשו כמו מקבת ויהא קדקדו גבוה למעלה. ושראשו שקוע הוא שיהא דמות ראשו כמי שנתן ידו על גובה ראשו ונתפשט עד שבלטו צדדיו וקורין אותו קובי. וסקיפס הוא שיהא אחורי ראשו בולט לצד ערפו כמו שבולטין הצדדין מהקובי עכ״ל. ולפי זה מאי שכתב רבינו מי שאמצע קדקדו שוקע למטה וכו' הוא פירוש שראשו שקוע.\",1,0],[8,361,8,1,\"ומ\\\"ש מי שאמצע קדקדו עולה למעלה וכו'. הוא פירוש הכילון.\",2,0],[8,361,8,1,\"ומי שראשו יוצא מאחריו כנגד ערפו. הוא פי' סקיפס ולפי זה יהיה פירוש שקיל פיסא שנראה כמי שנטל חתיכה והניחה מאחריו. וכתב הראב\\\"ד מי שאמצע א\\\"א דומה שלא בא זה אלא לערבב את העולם וכו'. נראה שטעמו מפני שהוא גורס כגירסת רש\\\"י שראשו שקוע לפניו ופירש דהיינו שראשו משופע לפניו באלכסון. ובסקיפס מאחריו פירש\\\"י שגובה ראשו חסר מאחריו. שקיל פיסא שנראה כמי שניטל ממנו חתיכה ונראה להראב\\\"ד שכל החולק על פירוש דברים אלו כחולק על פירוש הגמרא ומפני כך כתב שלא תפס דרך הגמרא וזו אינה השגה שכבר יישבתי פירוש רבינו על לשון הגמרא כפי גירסתו. עוד שנית השיגו ששינה סדר המשנה וכתב שראשו שקוע תחלה ושני לו הכילון ושלישי לו המקבן ורביעי לו סקיפס וחמישי לו הלפתן וזהו שכתב ופרטיו לא באו דרך הגמרא וגם זו אינה השגה שרבינו סידר דבר עם דבר שכנגדו מי שאמצע קדקדו שוקע אצל מי שאמצע קדקדו עולה ומי שפאת ראשו כנגד פניו עם מי שראשו יוצא מאחריו:\",3,0],[8,361,8,1,\"הקרח שאין בכל ראשו שיער כל עיקר וכו'. משנה שם הקרח פסול איזהו קרח כל שאין לו שיטה של שער מקפת מאזן לאזן ואם יש לו הרי זה כשר ובגמרא איכא תרי לישני ולישנא בתרא אם יש לו הרע זה כשר אמר רבא ל\\\"ש אלא שיש לו לאחריו ואין לו לפניו אבל יש לו בין לאחריו בין לפניו פסול וכ\\\"ש שיש לו לפניו ואין לו לאחריו ודאין לו כלל דפסול:\",4,0],[8,361,8,2,\"שנים בצוואר וכו' מי שצוארו ארוך הרבה וכו'. שם:\",1,0],[8,361,8,3,\"ארבעה באוזן וכו'. שם במשנה (דף מ\\\"ד) הצמם והצומע אי זהו צומע שאזניו קטנות והצמם שאזניו דומות לספוג ופירש\\\"י לספוג שכווצות וסתומות ובגמרא תניא אף הצימח לא הוו ידעי רבנן מאי צימח שמעו רבנן לההוא טייעא דהוה אמר מאן בעי צימח ואשתכח גדיא ומפרש רבינו דהיינו שאזניו מדולדלות למטה כמו של גדי וכן נראה מדברי רש\\\"י ואע\\\"ג דבתר הכי תניא התם יש דברים שהם כמומין ואינם כמומין וכו' הצימח והצמם והצומע סובר רבינו דכי היכי דלא קי\\\"ל כההיא ברייתא בצימח וצומע משום דסתם מתני' תני דהוו מומין ה\\\"ה דלא קי\\\"ל כוותה בצימח ועי\\\"ל דההיא ברייתא מיתניא גבי מומי בהמה ומתני' דחשיב להו מומין באדם כדפירש\\\"י דטעמא לפי שאינו שוה בזרעו של אהרן.\",1,0],[8,361,8,3,\"ומה שכתב מי שאחת מאזניו משונה מחבירתה במראה. איני יודע זו מנין לו דאי מדתנן בפרק על אלו מומין (בכורות דף מ':) עינו אחת גדולה ועינו אחת קטנה אזנו אחת גדולה ואחת קטנה במראה אבל לא במדה היינו לומר שנראה לכל שזו גדולה מזו אבל אם אינו ניכר אלא במדה אינו מום וכן פירש ה״ר עובדיה ז״ל ואם נאמר שרבינו אינו מפרש כן אלא אזניו משונות זו מזו במראה הוי מום אבל אם אינם משונות זו מזו אלא במדה אינו מום יקשה מאי אחת גדולה ואחת קטנה ואפשר שהוא מפרש שמצד שמשונות זו מזו במראה נראות אחת גדולה ואחת קטנה וכל זה דוחק אבל הנכון הוא שסובר רבינו שזהו זוגדוס השנוי במשנה וכן פירש הוא ז״ל שם ואכתוב לשונו בסמוך גבי מי ששער אחד מריסי עיניו משונה משער ריס אחר:\",2,0],[8,361,8,4,\"חמשה בגבינים וכו' משנה בפרק מומין אלו (בכורות דף מ״ג:) אין לו גבינין או אין לו אלא גבין אחד זהו גבן האמור בתורה רבי דוסא אומר שגביניו שוכבים ר' חנינא בן אנטיגנוס אומר שיש לו שני גבין ושתי שדראות ובגמרא וגבן דאין לו משמע ורמינהו גבן שיש לו גבינין הרבה אין לו גבינין או אין לו אלא גבין אחד מנין תלמוד לומר או [גבן] אמר רבא זהו מדרש או גבן וכתב רבינו בפירוש המשנה גבינין גבות העין. גביניו שוכבים הוא שיהא שער גביניו רב עד שהוא מגיע על עפעפי עיניו וכו' ואין ר' דוסא ות״ק ור' חנינא חולקין אם אלו מומין [או אינן מומין] רק הכל מודים שהם מומין ואינם חולקין אלא אי זהו גבן האמור בתורה עכ״ל.\",1,0],[8,361,8,4,\"ומ\\\"ש רבינו מי שאין לו שער בגביניו והוא גבן האמור בתורה יש לתמוה עליו שכפי מה שאמרו בגמרא כך הל\\\"ל והוא מדרש או גבן האמור בתורה:\",2,0],[8,361,8,4,\"מי שאחד מגביניו משונה מחבירו וכו'. בתוספתא דבכורות פ\\\"ה מונה בכלל המומין גביניו אחד שחור ואחד לבן והוא בכלל זוגדוס שאכתוב בסמוך:\",3,0],[8,361,8,5,\"ארבעה בריס העין וכו'. בפרק מומין אלו (בכורות דף מ״ד) שנשרו ריסי עיניו פסול מפני מראית העין ובגמרא תנא הזויר והלופין והתמין זויר דמזויר עינים לופין דנפישי זיפי תימין שתמו זיפי ותנא גבי מומין תני להו והתנן שנשרו ריסי עיניו פסול מפני מראית העין לא קשיא הא דאשתיור גרדומי הא דלא אשתיור גרדומי ופירש״י אשתיור גרדומי שרשים לא הוי מום אלא מפני מראית העין ומשום דהכא מיירי רבינו לענין מומין ממש כתב מי שאין לו שער כלל.\",1,0],[8,361,8,5,\"ומה שכתב מי ששער אחד מריסי עיניו משונה משער ריס אחר. שם במשנה זוגדוס ובגמרא זוגדוס מחוי רב הונא חד מדידן וחד מדידהו ופירש\\\"י שיש לו עין אחד דומה לעין אלו היושבים נגדי ועין אחת שלי מיתיבי וכו' זוגדוס אחד שחור ואחר לבן תנא כל זוגא דלא שוי אהדדי זוגדוס קרי ליה וכתב רבינו בפירוש המשנה ידוע שיש בגוף איברים שדומים זה לזה כגון העינים והאזנים וגבות העינים וזולתם וכשיהיה בין אחד לחבירו שינוי באי זה דבר שיהא אותו שינוי כגון שיהא בגב עינו אחד שער הרבה מאד ובשני מעט מזעיר או שיהא האחד מהם שחור והשני לבן או עינו האחת שחורה והשניה כעין התכלת או עינו אחת גדולה והשניה קטנה או אחד משני עפעפיו לבן והשני שחור וכן בשאר האברים שהם זוגות הרי הוא בעל מום ויקרא זו גדוס.\",2,0],[8,361,8,5,\"ומ\\\"ש מי שעפעפיו סגורות מעט וכו'. נראה שרבינו היה גורס כגירסת הערוך שכתב בערך טרוטות וזה לשונו בפרק מומין אלו טרוטות דמרמצן עיניה פירוש שעפעפיו סגורות ואינם פתוחות אלא מעט עכ\\\"ל:\",3,0],[8,361,8,6,\"אחד עשר בעינים ואלו הן מי שהיו שתי עיניו למעלה מהמקום הראוי להם קרובים מפדחתו מי שהיו שתי עיניו למטה מהמקומות הראוי להם. כך היא הגירסא הנכונה בספרי רבינו וכן מצאתי בספר מוגה וכן הוא בסמ\\\"ג והיא במשנה בפרק מומין אלו שתי עיניו למעלה ושתי עיניו למטה ומפרש לה בגמרא הכי.\",1,0],[8,361,8,6,\"ומ\\\"ש מי שהיו שתי עיניו עגולות וכו'. שם. עיניו טרוטות ופירש\\\"י עגולות.\",2,0],[8,361,8,6,\"ומה שכתב מי שעיניו מוזרות וכו'. נראה דהיינו מה ששנו שם תנא הזויר ומפרש דהיינו דמזיר עיניה.\",3,0],[8,361,8,6,\"ומ\\\"ש עיניו גדולות הרבה כשל עגל מי שעיניו קטנות כשל אווז. שם במשנה ובפרק שני מהלכות מזבח אבאר דכל שכן עינו אחת גדולה והשניה קטנה דהוי מום:\",4,0],[8,361,8,6,\"ומ\\\"ש מי שדמעיו זולפות תמיד מי שלחלוחית נמשכת מראש עינו וכו'. שם במשנה הצירן ובגמרא הצירן עיניו [טרוטות] צירניות דומעות דולפות וטורדות וכתב רבינו בפירוש המשנה צירן מי שעיניו דומעות או שנוזלים קצות עיניו תמיד והוא מה שאמרו בפירוש השם הזה דומעות זולפות.\",5,0],[8,361,8,6,\"ומ\\\"ש מי שמקבץ ריסי עיניו ועוצמן וכו'. שם במשנה סכי שמש ובגמרא תני רב יוסף סני שמש ופירש\\\"י ששונא השמש ואינו יכול לראות מקום שחמה זורחת שם. וכתב רבינו בפירוש המשנה סני שמש שונאי השמש והירח והכוונה בזה שבשעה שרוצה להביט אל השמש או לירח או לדברים המאירים מאמץ ומקבץ עפעפי עיניו ומקטין אותו.\",6,0],[8,361,8,6,\"ומ\\\"ש מי שראיית עינו מעורבבת וכו'. שם במשנה רואה את החדר ואת העליה כאחד.\",7,0],[8,361,8,6,\"ומה שכתב מי שאחת מעיניו משונה מחבירתה בין במקומה. שם במשנה עינו אחת למעלה ואחת למטה.\",8,0],[8,361,8,6,\"ומה שכתב בין במראה כגון שהיתה אחת שחורה ואחת פתוכה וכו'. זהו זוגדוס שכתבתי למעלה:\",9,0],[8,361,8,7,\"ששה בחוטם וכו'. שם במשנה החרום פסול אי זהו חרום הכוחל שתי עיניו כאחת ובגמרא תנו רבנן חרום שחוטמו שקוע וכו' רבי יוסי אומר אין חרום אלא הכוחל שתי עיניו כאחת אמרו לו הפלגת אע\\\"פ שאינו כוחל שתי עיניו כאחת ופירש\\\"י שקוע למעלה בין עיניו ומאחר שהוא סתם במתני' כרבי יוסי ומחלוקת בברייתא הוה לן למיפסק כרבי יוסי וכסתם דמתני' ויש לתמוה על רבינו שלא פסק כן ואפשר שפסק כן מפני ששנויה בלשון תימה הפלגת משמע דלאו סברא היא ולכך הביאו בגמרא אותה ברייתא לגלות דלא קי\\\"ל כההיא סתם מתני'.\",1,0],[8,361,8,7,\"ומ\\\"ש מי שאמצע חוטמו בולט למעלה מי שעוקץ חוטמו נוטף למטה מי שחוטמו עקום לצד אחד. שם חוטמו בולם חוטמו סולד חוטמו נוטף.\",2,0],[8,361,8,7,\"ומ\\\"ש מי שחוטמו גדול מאיבריו מי שחוטמו קטן מאיבריו. שם במשנה.\",3,0],[8,361,8,7,\"ומ\\\"ש כיצד משערין אותו באצבע קטנה שעל ידו וכו'. שם בברייתא:\",4,0],[8,361,8,8,\"שלשה בשפתים וכו'. שם במשנה.\",1,0],[8,361,8,8,\"ומ\\\"ש מי שפיו רפוי ורירו יורד מפיו. שם (דף מ\\\"ג:) א\\\"ר יוחנן וכו' הזבלגנין פסולין ופירש רבינו כפירוש שני דערוך:\",2,0],[8,361,8,9,\"שלשה בבטן וכו'. שם במשנה (דף מ\\\"ד:):\",1,0],[8,361,8,10,\"שלשה בגב ואלו הן מי ששדרתו עקומה. שם במשנה (דף מ\\\"ג:) מי שיש לו שני גבין ושתי שדראות ובגמרא למימרא דחיי והא איתמר המפלת בריה שיש לה שני גבין וכו' בששדרתו עקומה ופירש\\\"י ומיחזי כגבין שדרות הרבה.\",1,0],[8,361,8,10,\"ומ\\\"ש מי שיצאה חוליה משדרתו וכו'. שם במשנה (דף מ\\\"ג) בעלי חטוטרת ר\\\"י מכשיר וחכמים פוסלין וידוע דהלכה כחכמים ודברי רבינו בפירוש המשנה כמו שהם כאן. ובגמרא דאית בה עצם כ\\\"ע לא פליגי דפסלא כי פליגי דלית בה עצם ורבינו נראה שמפרש דאית בה עצם היינו לומר שיש פגע בעצם כלומר שיצאה חוליא משדרתו וכו':\",2,0],[8,361,8,11,\"ששה בידים ואלו הן מי שיש בידו אצבע יתירה וכו'. שם (דף מ\\\"ה) במשנה יתר בידיו וברגליו.\",1,0],[8,361,8,11,\"ומ\\\"ש אפילו היה שש ושש. שם במשנה שש ושש כ\\\"ד ר\\\"י מכשיר וחכמים פוסלין וידוע דהלכה כחכמים.\",2,0],[8,361,8,11,\"ומה שכתב ואם חתך את היתרת כשר ואם היה בה עצם אפי' חתכה פסול. משנה שם. ודע דבגמרא גרסינן אמר רבי יוחנן ובנספרת על גב היד ופירש\\\"י שנספרת עם שאר האצבעות שעומדת בשורתן בההיא קתני מתניתין דחשיב אבר ולפי זה יש לתמוה למה השמיטו רבינו לכן נראה שרבינו מפרש דה\\\"ק אפילו נספרת ע\\\"ג היד הוי מום ולפיכך כתב סתם לפסול.\",3,0],[8,361,8,11,\"ומ\\\"ש מי שחסר אצבעו מידו. פשוט הוא.\",4,0],[8,361,8,11,\"ומ\\\"ש מי ששתי אצבעות ידיו קלוטות עד למטה מהפרק ואם חתכן והפרישן עד הפרק כשר. משנה שם.\",5,0],[8,361,8,11,\"ומ\\\"ש באי זה פרק אמרו וכו'. כן משמע מפשטא דמתני'.\",6,0],[8,361,8,11,\"ומ\\\"ש מי שאצבעותיו מורכבות זו על גבי זו מי שפיקה יוצאת מגודלו. משנה שם ופירש\\\"י פיקה חתיכת בשר עגולה כפיקה יוצאת מגודלו.\",7,0],[8,361,8,11,\"ומ\\\"ש מי שהוא אטר יד ימינו וכו'. שם במשנה השולט בשתי ידיו רבי פוסל וחכמים מכשירים ובגמרא ת\\\"ר אטר בין ביד בין ברגל פסול:\",8,0],[8,361,8,12,\"ארבעה באיברי הזרע וכו'. שם במשנה (מ\\\"ד:) המאושכן ובעל גבר תנא מאושכן בביצים ובעל גבר בגיד וכו' ועד כמה מחוי רב יהודה עד רכובה תניא ר\\\"א בן יעקב אומר עד רכובה פסול למעלה מרכובה כשר איכא דאמרי עד רכובה כשר למטה מרכובה פסול ויש לתמוה על רבינו שפסק כל\\\"ק ואפשר שהוא ז\\\"ל מפרש דאיכא דאמרי לא קאי אדר\\\"א בן יעקב אלא אדר\\\"י ויש הוכחה לדבר מדנקט לישנא דאיכא דאמרי ואי אדראב\\\"י פליג לא הל\\\"ל אלא וי\\\"א והשתא אתי שפיר שפסק כראב\\\"י שמשנתו קב ונקי. ועי\\\"ל שפסק כל\\\"ק משום דבשל תורה הלך אחר המחמיר.\",1,0],[8,361,8,12,\"ומ\\\"ש מי שנמרחו אשכיו וכו'. שם במשנה אין לו ביצים אין לו אלא ביצה אחת זהו מרוח אשך האמור בתורה ר' ישמעאל אומר כל שנמרחו אשכיו ר\\\"ע אומר כל שרוח באשכיו רבי חנינא בן אנטיגנוס אומר כל שמראיו חשוכים ופירש\\\"י שנמרחו אשכיו שנימוחו ביציו ופירש רבינו בפירוש המשנה שכל אלו התנאים מודין שכל אלו הם מומין לא נחלקו אלא בפי' מרוח אשך האמור בתורה ויש לתמוה על רבינו שכתב ארבעה באיברי הזרע ובפרטן אי אתה מוצא אלא שלשה ומצאתי בסמ\\\"ג ג' מי שנימוחו מבושיו והוא הכיס של ביצים שנימוחו הביצים שלו בתוכו ד' מי שהרוח במבושיו ונפחו והוא מרוח אשך עכ\\\"ל ונראה שכך צריך להגיה בספרי רבינו וכן מצאתי בספר מוגה. ועדיין יש לתמוה למה לא כתב שאע\\\"פ שלא נימוחה אלא ביצה אחד הוא בעל מום כדמשמע ממה ששנינו אין לו אלא ביצה אחת ולכן נראה לי שרבינו מפרש אין לו אלא ביצה אחת היינו שנברא מתחלת ברייתו חסר ביצה אחת אבל בנימוחו אשכיו לא מפסיל עד שימוחו שתיהן וכדמשמע מלישנא דרבי ישמעאל שנמרחו אשכיו לשון רבים ולדעת רבי ישמעאל הא דכתב קרא מרוח אשך לשון יחיד פירושו שאין לו שום אשך ואין לתמוה למה השמיטו רבינו אין לו אלא ביצה אחת שכבר כתבו בפרק שקודם זה אצל מומין הפוסלים באדם ובבהמה:\",2,0],[8,361,8,13,\"ט\\\"ו בשוקים וכו'. משנה שם. וכתב הראב\\\"ד המשנה אמרה פיקה יוצא מגודלו וכו'. ונראה שמ\\\"ש רבינו מי שפיקתו יוצאת והפיקה היא העיגול שלמעלה מן העקב וכו' הוא מהא דאמרינן בפרק מומין אלו תנא השופנר ואמר רבי יוחנן דהיינו שאין לו כסתות כל עיקר ומפרש דהיינו שאין לו אותה פיקה שקורין בלע\\\"ז טודיליי\\\"ו.\",1,0],[8,361,8,13,\"ומ\\\"ש מי שפיקתו יוצאת היינו שיצאה ואינה ודוחק.\",2,0],[8,361,8,13,\"ומה שכתב מי שעקבו יוצא לאחוריו וכו'. משנה וגמרא שם (דף מ\\\"ה):\",3,0],[8,361,8,13,\"ומ\\\"ש מי שפרסותיו רחבות כשל אווז אע\\\"פ שאינה קלוטה כשל אווז. משנה שם פרסותיו רחבות כשל אווז ובגמרא אר\\\"פ לא תימא דטרפא ולא סדיקא אלא כיון דטרפא אע\\\"ג דסדיקא ופירש\\\"י טרפא קלושה והערוך פי' טרפא רחבה ומשונה.\",4,0],[8,361,8,13,\"ומ\\\"ש מי שפיקה יוצאה מגודלו. משנה שם ופירש\\\"י פיקה חתיכת בשר עגולה כפיקה.\",5,0],[8,361,8,13,\"ומ\\\"ש מי שיש ברגלו אצבע יתירה וכו' עד או שחתכן והפרישן כשר. נתבאר בפרק זה גבי יד:\",6,0],[8,361,8,13,\"ומ\\\"ש מי שרגלו כולה שוה וכו'. בתוספתא דבכורות פ\\\"ה רגלו מכיש מלמעלה ומפסיע מלמטה ועוד שם אצבעותיו גדומות.\",7,0],[8,361,8,13,\"ומ\\\"ש מי שרגלו עקומה דומה למגל וכו'. בתוספתא דבכורות פ\\\"ה פרסתו חלולה עקומה דומה למגל.\",8,0],[8,361,8,13,\"ומ\\\"ש מי שרגלו חלולה וכו'. כתבו התוספות וסמ\\\"ג שכן פירש הערוך על מה ששנו בברייתא פרק מומין אלו תנא בעל הפיקין אמר רבי יוחנן בעל הפיקין שיש לו כסתות הרבה.\",9,0],[8,361,8,13,\"ומ\\\"ש המקיש בקרסוליו בעת שמהלך מי שמקיש בארכובותיו בעת שמהלך. משנה שם.\",10,0],[8,361,8,13,\"ומ\\\"ש מי שהוא אטר ברגל ימינו. נתבאר לעיל גבי יד:\",11,0],[8,361,8,14,\"ארבעה בכל הגוף וכו'. משנה בפרק הנזכר (דף מ\\\"ד).\",1,0],[8,361,8,14,\"ומ\\\"ש הארוך ביותר הננס והוא הקצר ביותר וכו'. משנה (דף מ\\\"ה:) הקפח והננס ובגמרא קפח תני רב זביד גבוה איני והתני ר' אבהו מנין שהקב\\\"ה משתבח בבעלי קומה וכו' אמר רב פפא באריכא שמיטא סגיא ופירש\\\"י דארוך הוא דק שאינו עבה לפי ארכו:\",2,0],[8,361,8,15,\"שמונה בעור הבשר ואלו הן הכושי וכו'. משנה שם הכושי והגיחור והלבקן וכו' ובעלי נגעים טהורים ובגמרא גיחור וכו' סומקא גיהיא לבקן חיורא ופי' הערוך סומקא גיהיא אדום ביותר.\",1,0],[8,361,8,15,\"ומ״ש מי שהיתה בעור פניו שומא שיש בה שער וכו' מי שהיתה בעור פניו שומא שיש בה איסר או יותר. הכל סוף פרק המדיר (כתובות דף ע״ה).\",2,0],[8,361,8,15,\"ומ\\\"ש בעלי הדלדולין וכו'. משנה בפרק מומין אלו:\",3,0],[8,361,8,16,\"ועוד יש באדם ד' מומין ואלו הן החרש והשוטה. שם במשנה.\",1,0],[8,361,8,16,\"ומ\\\"ש והנכפה אפילו לימים רבים מי שרוח רעה מבעתתו תמיד או בעתים ידועים. משנה שם (דף מ\\\"ד:) נכפה אפילו אחת לימים רוח קצרית באה עליו ופירש רש\\\"י רוח קצרית רוח שד וסובר רבינו דכי היכי דנכפה אפילו אחת לימים ה\\\"ה לרוח קצרית דמאי שנא:\",2,0],[8,361,8,17,\"ואלו פסלו מפני מראית העין מי שנשרו ריסי עיניו. נתבאר בפרק זה.\",1,0],[8,361,8,17,\"ומ\\\"ש ומי שניטלו שיניו. שם במשנה (דף מ\\\"ד):\",2,0],[8,361,9,1,\"זר שעבד במקדש עבודתו פסולה וכו'. ריש פרק ב' דזבחים (דף ט\\\"ז:).\",1,0],[8,361,9,1,\"ומ\\\"ש וחייב מיתה בידי שמים שנאמר והזר הקרב יומת. סוף פרק הנשרפין (סנהדרין דף פ\\\"א:) במשנה זר ששימש במקדש רבי עקיבא אומר בחנק וחכמים אומרים בידי שמים וידוע דהלכה כחכמים.\",2,0],[8,361,9,1,\"ומ\\\"ש מפי השמועה למדו וכו' והיכן הזהיר עליו וכו'. בסיפרי פרשת קרח והזר הקרב יומת לעבודה עונש שמענו אזהרה לא שמענו ת\\\"ל וזר לא יקרב אליכם:\",3,0],[8,361,9,1,\"איזהו זר כל שאינו מזרע אהרן הזכרים שנאמר וערכו בני אהרן. כך היא הנוסחא הנכונה ובקצת ספרי רבינו יש חסרון הניכר:\",4,0],[8,361,9,2,\"אע\\\"פ שהזרים מוזהרים וכו' אין חייבין מיתה אלא על עבודה תמה וכו'. בזבחים (דף קט\\\"ו) אהא דתנן אין חייבין עליה משום זרות ובפרק שני דיומא (דף כ\\\"ד).\",1,0],[8,361,9,2,\"ומ\\\"ש ואין הזר חייב מיתה אלא על ד' עבודות בלבד וכו'. מימרא דרב פרק שני דיומא (דף כ\\\"ד) ואע\\\"ג דלוי פליג ואמר אף תרומת הדשן פסק רבינו כרב והתם יליף לה מדכתיב ועבדתם עבודת מתנה אתן את כהונתכם והזר הקרב יומת עבודת מתנה ולא עבודת סילוק ועבדתם עבודה תמה ולא עבודה שיש אחריה עבודה ופירש\\\"י עבודת מתנה שאתה נותן על המזבח ולא עבודת סילוק שאתה מסלק וסר מעל המזבח כגון תרומת הדשן. עבודה תמה עבודה שהיא גומרת ומתממת את הדבר ולא שיש אחריה עבודה כגון שחיטה וקבלה והולכה שיש אחריה זריקה אבל זריקה עבודה אחרונה שבדם וכן הקטרה בקומץ מנחה ובאיברים ופדרים וכן ניסוך היין בכל השנה וכן המים בחג:\",2,0],[8,361,9,3,\"כיצד על הזריקה בין שזרק בפנים בין שזרק בחוץ. לאו בחוץ קאמר דהיאך יתחייב על זריקה בחוץ משום זר שעבד אלא בפנים היינו לפני לפנים ובחוץ היינו בהיכל והכי תניא התם עבודות שזר חייב עליהם מיתה זריקת דם בין לפנים בין לפני לפנים ופירש\\\"י בין לפנים הזאות שעל הפרוכת בין לפני לפנים שעל בין הבדים דיוה\\\"כ.\",1,0],[8,361,9,3,\"ומ\\\"ש בין שהזה הזאה אחת מכל הזיות הדם בין שהזה הזאה אחת מכל קרבנות המצורע. שם בברייתא ואין לתמוה על רבינו שכתב בין שהזה אחת מכל הזיות הדם למה חזר ופרט הזיות קרבנות המצורע דהתם דריש מדכתיב בההוא קרא לכל דבר המזבח ולמבית לפרוכת לכל דבר המזבח לאתויי שבע הזיות שבפנים ושבמצורע ופירש\\\"י שבע הזיות שבפנים שמזה על הפרוכת מפר העלם דבר ופר משיח ושל יוה\\\"כ. ושבמצורע שמזה מלוג שמן בהיכל וכו' דסלקא דעתך אמינא לאו דבר המזבח הוא להכי רבי לכל. ודע ששנו עוד שם בברייתא המזה בחטאת העוף והממצה ויש לתמוה למה השמיט רבינו ממצה ואפשר דמשמע ליה דבכלל אחת מכל הזיות הדם היא:\",2,0],[8,361,9,4,\"כיצד על הקטרה וכו' אפילו הפך באיברים שלא נתעכלו בצינורא. בפרק שני דשבועות (דף י\\\"ז:) אמר רב הונא זר שהפך בצינורא חייב מיתה וקאמר עלה בגמרא ה\\\"ד אי דלא הפיך לא מעכל להו פשיטא ואי דלא הפיך בהו נמי מעכלי מאי קא עביד לא צריכא דאי לא הפיך בהו מיעכלי בתרתי שעי והשתא מיעכל בחד שעתא הא קמשמע לן דכל קרובי עבודה עבודה היא:\",1,0],[8,361,9,4,\"וכן אם הקטיר קטרת על מזבח הזהב וכו'. כן יש ללמוד קצת מפרק השוחט ומעלה בחוץ (דף ק\\\"ט:) אהא דתנו רבנן המקטיר כזית בחוץ חייב חצי פרס בפנים פטור וצריך עיון:\",2,0],[8,361,9,5,\"והמסדר שני גיזרי עצים על המערכה וכו'. בפרק שני דיומא (דף כ\\\"ד:) פלוגתא דרב ורבי יוחנן ופסק כרבי יוחנן דאמר סידור שני גיזרי עצים עבודה תמה היא וסידור האיברים תחלת סידור אחר הוא:\",1,0],[8,361,9,5,\"אבל היוצק והבולל והפותת והמולח וכו'. אלו חוץ ממצית אש על המזבח מנויים במשנה בסוף זבחים (דף קי\\\"ב:) וקתני בהו אין בהם משום זרות וטעמא כמו שנתבאר שכולם עבודה שיש אחריה עבודה ולאו עבודה תמה היא ומצית אש על המזבח נמי לאו עבודה תמה היא שיש אחריה סידור שני גיזרי עצים:\",2,0],[8,361,9,6,\"שחיטת הקדשים כשירה בזרים וכו' מקבלה ואילך מצות כהונה. בר״פ כל הפסולים (זבחים דף ל״א:).\",1,0],[8,361,9,6,\"ומה שכתב וכן ההפשט והניתוח והולכת עצים למזבח כשירה בזרים שנאמר באיברים והקטיר הכהן המזבחה וכו'. בסוף פרק שני דיומא (דף כ\\\"ו כ\\\"ז):\",2,0],[8,361,9,7,\"ומ\\\"ש וכן הדלקת הנרות כשירה בזרים. שם הדלקה לאו עבודה היא. ופירש\\\"י דהא כיון שהדליק ברוב היוצא השלהבת עולה מאליה אבל הצתת אש עבודה שיש בה טורח היא שצריך להצית האור בעצי המערכה. וכתב הריטב\\\"א תימה דהא כתיב דבר אל אהרן וכו' בהעלותך את הנרות ואפשר לומר דלהכי לא אפקיה בלשון חיוב דבר אל אהרן ויעלה את הנרות לומר דלאו עבודה היא לחייב עליה מיתה בזר כשם שאין חיוב בעבודה שאינה תמה עכ\\\"ל.\",1,0],[8,361,9,7,\"ועל מה שכתב רבינו לפיכך אם הטיב הכהן את הנרות והוציאן לחוץ מותר לזר להדליקן כתב הראב\\\"ד הפליג כשאמר מותר לזר להדליקן אלא שאם הדליקן כשירות עכ\\\"ל. וטעמו של רבינו דכיון דלאו עבודה היא מישרא נמי שרי כמו שחיטה שהיא כשירה בזרים:\",2,0],[8,361,9,8,\"הרמת הדשן צריכה כהן וכו' ואם הרים ישראל לוקה ואינו חייב מיתה כו'. כבר כתבתי דבפ\\\"ב דיומא פלוגתא דרב ולוי ופסק כרב:\",1,0],[8,361,9,8,\"וכן אם דישן מזבח הפנימי והמנורה אינו חייב מיתה. כך מצאתי מוגה בקצת ספרי רבינו וטעמו מפני שהן עבודות סילוק וכמו שנתבאר בפרק זה גבי הרמת דשן:\",2,0],[8,361,9,9,\"סידר המערכה פורקה וחוזר הכהן וסודרה וכו'. בספ\\\"ב דיומא (דף כ\\\"ז:) אמר ר' אסי אמר ר' יוחנן זר שסידר את המערכה חייב כיצד הוא עושה פורקה וחוזר [הכהן] וסודרה מתקיף לה רבי זירא וכי יש לך עבודה שכשירה בלילה ופסולה בזר וכו' אלא כי איתמר הכי איתמר אמר רבי אסי אמר רבי יוחנן זר שסידר שני גיזרי עצים חייב הואיל ועבודה תמה היא ומשמע דסידור מערכה כשירה בזר וכאתקפתא דרבי זירא ואם כן יש לתמוה על רבינו שפסק דסידור מערכה בזר פסולה ושמא יש לומר דמשמע ליה דלא מתמה רבי זירא וכי יש עבודה שכשירה בלילה וכו' אלא משום דמחייב ליה מיתה אבל משום פיסולא בלא חיוב מיתה לא הוה מתמה וכן פירש\\\"י אהא דמתקיף לה רבי זירא וכי יש לך עבודה שיש אחריה עבודה ופסולה בזר להתחייב מיתה עכ\\\"ל וטעמא משום דכיון דאמאי דאמר רבי אסי אמר רבי יוחנן זר שסידר את המערכה חייב מתקיף ע\\\"כ לומר דמחיוב מיתה מתקיף:\",1,0],[8,361,9,10,\"הטמא ובעל מום ושלא רחוץ ידים ורגלים וכו'. בסוף זבחים (דף קי\\\"ב:) תנן דאין חייבים על עבודה שאינה תמה משום זרות ולא משום טומאה ולא משום מחוסר בגדים ולא משום שאינו רחוץ ידים ורגלים. ואיני יודע למה השמיט רבינו מחוסר בגדים וכתב הר\\\"י קורקוס אפשר שכיון שכתב שמחוסר בגדים הוא כזר ומשום זר היא דמחייבינן כמו שכתב בסוף הלכות כלי המקדש לא הוצרך להזכירו. וכתב עוד ובעל מום לא הוזכר במשנה ורבינו הזכירו אפשר שסובר רבינו דלאו דוקא נקט במתני' הני אלא ה\\\"ה לכל חיוב שחייבין משום עבודה שאין חיוב אלא בעבודה תמה ובעבודת מתנה דילפינן מזר דחד טעמא הוא וגם בבעלי מום כתיב ואל המזבח לא יקרב והיינו לעבודה כמו שנתבאר ודין כולם שוה דמאי שנא עכ\\\"ל. ומדברי רבינו משמע דעל עבודה שהזר חייב עליה מיתה גם אלה חייבים מיתה ותימה שהרי ברפ\\\"ו כתב אין בעלי מומין במיתה וצריך לומר דהכי קאמר אין חייבין כל חד כדאיתיה טמא ושלא רחוץ ידים ורגלים מיתה ובעל מום מלקות אלא על עבודה שהזר חייב מיתה:\",1,0],[8,361,9,11,\"כהן טבול יום ומחוסר כפורים שנטמא וכו' ועבד חייב על כל אחת ואחת. כתב הראב\\\"ד א\\\"א בתוספתא פרק י\\\"ב דזבחים וכו' ומאחר שרבינו פוסק דאיסור חל על איסור בכולל או מוסיף או בת אחת והכא טבול יום ומחוסר כפורים בת אחת הן. כיצד שהרי יש טבול יום שאינו צריך להביא קרבן ואם כן איננו מחוסר כפורים והטמא שצריך להביא קרבן כמו המצורע אם טבל הרי הוא טבול יום ומחוסר כפורים וכשנטמא בטומאה אחרת נוסף עליו איסור שעד עתה היה מותר ליכנס לעזרת הנשים עתה היה אסור ליכנס להר הבית ומגו דאתוסף איסור בכניסה איתוסף איסור בעבודה שאינו רחוץ ידים ורגלים יש בו איסור אפילו לכהן הטהור ומגו דאתוסף חיוב לטהור איתוסף לטמא וכתב ר\\\"י קורקוס ז\\\"ל הקדים רבינו טבול יום ומחוסר כפורים לטמא היפך מהתוספתא שאם היה טמא קודם לא שייך תו טבול יום ומחוסר כפורים שהכל בכלל טמא וגם בתוספתא צריך לפרש כן כהן טמא שהיה מקודם טבול יום ומחוסר כפורים עכ\\\"ל. ואם כן יפה פסק דחייב על כל אחת ואחת.\",1,0],[8,361,9,11,\"ומ\\\"ש רבינו ואם היה זר אינו לוקה אלא אחת משום זרות. בתוספתא דבזבחים פרק י\\\"ב וטעמא משום דלא הוזהר מלעבוד טמא ומחוסר בגדים ושלא רחוץ ידים ורגלים אלא מי שהוא ראוי לעבוד אבל הזר הואיל ואינו ראוי לעבוד אינו עובר בשום אחד מאלה:\",2,0],[8,361,9,12,\"זר ששימש בשבת חייב משום שבת ומשום זרות וכו'. בס״פ ד' אחין (יבמות דף ל״ג:) פלוגתא דרבי יוסי ורבי שמעון ופסק כרבי יוסי. וכתב הראב״ד שתיהן שבאו עליו בבת אחת וכו'. ואיני יודע מי הזקיקו לכך דהא לא אוקי הכי בגמרא אלא גבי פלוגתא דרבי חייא ובר קפרא אבל בתר הכי אמרינן מיתיבי זר ששימש בטומאה וכו' ואילו מליקה שיירה למאן שיירה אילימא לר' יוסי השתא באיסור כולל מחייב שתים באיסור בת אחת מיבעי' ובלאו הכי כיון דרבינו פוסק כמ״ד איסור חל על איסור באיסור כולל כמ״ש בפ״ח ממאכלות אסורות שפיר עבד דסתים לה הכא סתומי ואיסור כולל היינו זר מעיקרא שרי במלאכה ואסור בעבודה אתיא לה שבת מגו דאתסר במלאכה אתסר נמי בעבודה בעל מום מעיקרא שרי באכילה ואסור בעבודה איטמי ליה מגו דאיתסר באכילה איתסר נמי בעבודה:\",1,0],[8,361,9,13,\"כל כהן שעבד ע\\\"ז בין במזיד בין בשוגג וכו' ה\\\"ז לא ישמש במקדש לעולם וכו'. בסוף מנחות (דף ק\\\"ט:) איפליגו רב נחמן ורב ששת בעבד בשוגג ופסק כרב ששת דהלכתא כוותיה באיסורי.\",1,0],[8,361,9,13,\"ומה שכתב אחד העובד אותה בשירות כגון שנעשה כומר לע\\\"ז או המשתחוה לה או המודה בה וקבלה עליו באלוה הרי זה פסול לעולם עבר והקריב אין קרבנו ריח ניחוח אע\\\"ג שהיה שוגג בעת ששרת וכו'. גם זה שם פלוגתא דרב נחמן ורב ששת בהיה שוגג ופסק כרב ששת.\",2,0],[8,361,9,13,\"ומ\\\"ש אבל השוחט לע\\\"ז בשוגג אם עבר והקריב קרבנו ריח ניחוח. שם אמר רב יהודה כהן ששחט לע\\\"ז קרבנו ריח ניחוח משום דכתיב יען אשר ישרתו אותם לפני גלוליהם וכו' ולא יגשו אלי לכהן לי אי עבד שירות אין שחיטה לאו שירות הוא וגבי פלוגתא דרב נחמן ורב ששת בשגג בזריקה לע\\\"ז א\\\"ר נחמן מנא אמינא לה דתניא וכפר הכהן על הנפש השוגגת בחטאה בשגגה מלמד שהכהן מתכפר ע\\\"י עצמו (בעון ע\\\"ז) במאי אילימא בשחיטה מאי איריא שוגג אפי' מזיד נמי אלא לאו בזריקה ורב ששת אמר לך לעולם בשחיטה ובמזיד לא נעשה משרת לע\\\"ז ואע\\\"ג דפשטא דברייתא משמע שהוא מתכפר על ידי עצמו אפילו לכתחילה סובר רבינו דמכיון דרב יהודה נקט קרבנו ריח ניחוח דמשמע אם עבר והקריב נתקבל אבל לכתחלה לא יקריב אית לן לפרושי דברייתא נמי מתכפר ע\\\"י עצמו בדיעבד קאמר:\",3,0],[8,361,9,14,\"מי שעבר ועשה בית חוץ למקדש וכו'. משנה בסוף מנחות (דף ק\\\"ט) הכהנים ששימשו בבית חוניו לא ישמשו במקדש.\",1,0],[8,361,9,14,\"ומ\\\"ש וכן כלים שנשתמשו בהם שם לא ישתמשו בהם במקדש לעולם אלא יגנזו. בפרק רבי ישמעאל (ע\\\"ז דף נ\\\"ב) בעיא דאיפשיטא.\",2,0],[8,361,9,14,\"ומ\\\"ש ויראה לי שאם עבד כהן ששימש שם במקדש לא פסל. טעמא דמסתבר הוא דכיון דמשום קנסא הוא דמיפסלי כדאמרינן בפ' רבי ישמעאל בדיעבד אין לקנסם:\",3,0],[8,361,9,15,\"נמצאו כל הפסולים לעבודה שמונה עשר וכו'. ובספרי הדפוס יש חסרון הניכר וצריך להגיה ולהוסיף מי שיש בין רגלו ובין הארץ דבר חוצץ.\",1,0],[8,361,9,15,\"ומה שכתב כל אלו פסולים לעבודה ואם עבדו חללו חוץ מפרועי ראש וקרועי בגדים. מסקנא דגמרא בפרק שני דתענית (דף י\\\"ז:) ופרק כ\\\"ג.\",2,0],[8,361,9,15,\"ומ\\\"ש והשוחט לע\\\"ז בשוגג וכו'. כבר נתבאר בפרק זה:\",3,0],[8,361,9,15,\"סליקו הלכות ביאת המקדש\",4,0],[8,362,1,1,\"מצות עשה להיות כל הקרבנות תמימים וכו'. בסיפרא:\",1,0],[8,362,1,2,\"ומ\\\"ש וכל המקדיש בהמה שיש בה מום לגבי המזבח עובר בלא תעשה ולוקה על הקדשו שנאמר כל אשר בו מום לא תקריבו מפי השמועה למדו שזו אזהרה למקדיש בעלי מומין. בפרק קמא דתמורה (דף ו').\",1,0],[8,362,1,2,\"ומה שכתב אפילו הקדישו לדמים לוקה וכו'. שם (דף ז') אמר רבא השתא דאמור טעמא דבעל מום דלקי משום דבזיא מילתייהו אפילו מקדיש ליה לדמי נסכים נמי לקי ותניא כוותיה דרבא וכתבו התוספות דה\\\"ה למקדיש לדמי עולה ואיני יודע למה למדוהו בה\\\"ה דהא כל שכן הוא שהרי פירש\\\"י אפילו אקדשיה לדמי נסכים דהשתא ליכא בזיון כל כך שאין במינו ראוי לנסכים עכ\\\"ל. ונראה שהנוסחא האמיתית בדברי רבינו אפילו הקדישו לדמי נסכים:\",2,0],[8,362,1,3,\"המתכוין לומר שלמים ואמר עולה וכו' לא אמר כלום. בפרק שלישי דתרומות (משנה ח').\",1,0],[8,362,1,3,\"ומה שכתב לפיכך המתכוין לומר על בעל מום עולה והקדישו שלמים וכו' אינו לוקה. פשוט הוא:\",2,0],[8,362,1,3,\"מי שדימה שמותר להקדיש בעל מום למזבח. בפרק שני דתמורה (דף י\\\"ז) תנן עשה שוגג כמזיד בתמורה ולא עשה שוגג כמזיד במוקדשין ובגמרא מאי טעמא וכו' אמר קרא יהיה קדש לרבות שוגג כמזיד היכי דמי שוגג כמזיד אמר חזקיה כסבור שהוא מותר להמיר דכוותה גבי קדשים כסבור מותר להקדיש בעלי מומין למזבח גבי תמורה לקי גבי קדשים לא לקי. וכתב הראב\\\"ד על דברי רבינו טעה בזה כי מי שדי בדברי רש\\\"י שכתב גבי תמורה לקי דרבי ביה קרא שוגג כמזיד גבי מה שמותר להקדיש בעל מום למזבח וכו'. ותירוץ השגה זו מבואר קדשים לא לקי דלא מצינו מלקות אלא במזיד ובהתראה עכ\\\"ל. ועל מה שכתב הראב\\\"ד דהוי הקדש טעות יש לדון דלא מיקרי הקדש טעות אלא כגון אומר שור שחור שיצא מביתי ראשון ויצא לבן שנתכוון להקדיש גוף אחד ונמצא גוף אחר אבל אם דימה שמותר להמיר שוגג מיקרי ולא טעות:\",3,0],[8,362,1,4,\"השוחט בעל מום לשם קרבן לוקה וכו'. וכן המקטיר אימורי בעלי מומין על המזבח לוקה וכו'. בפרק קמא דתמורה (דף ו') ודקדק רבינו לכתוב לשם קרבן משום דאמרינן בגמרא שומע אני אף קדשי בדק הבית תלמוד לומר ואל פתח אהל מועד לא הביאו וכו' שאין ראוי לפתח אהל מועד אין חייבין עליו משום שחוטי חוץ כלומר והוא הדין לשוחט בעל מום שאינו חייב משום בעל מום.\",1,0],[8,362,1,4,\"ומה שכתב נמצאת למד שאם הקדיש בעל מום ושחטו וכו' לוקה ד' מלקיות. שם אלא ששם אמרו שעובר משום ה' שמות משום דמני בל תקטירו ב' לאוין בל תקטירו כולו בל תקטירו מקצתו וכתב רבינו בסה\\\"מ שלו (מצוה צ\\\"ד) דאמרינן בפרק קמא דתמורה (דף ז':) המעלה איברי בעלי מומין על גבי המזבח אמר אביי עובר משום בל תקטירו כולו ובל תקטירו מקצתו רבא אמר אין לוקין על לאו שבכללות מיתיבי המקדיש בעלי מומין לגבי מזבח עובר משום ה' שמות אלמא לוקין על לאו שבכללות וכו' תיובתא דרבא תיובתא הנה נתבאר לך שזה שאמרו עובר בה' אמנם הוא עם סברתו שסובר שלוקין על לאו שבכללות ולכן ימנה הלאו שכולל כולם ומקצתם בשני שמות וזה הוא המפורסם מדעת אביי בכל מקום ולדעת רבא שאמר אין לוקין על לאו שבכללות אמנם יתחייב מלקות אחת וכו' ויהיו כולם ארבעה לאוין לבד עכ\\\"ל. ומשום דקי\\\"ל בעלמא דהלכה כרבא לגבי אביי הילכך לא חיישינן לההיא ברייתא דסברה דלוקין על לאו שבכללות ויש לתמוה דכיון דאיתותב רבא מברייתא היכי אפשר דנקטינן כוותיה כיון דלא אשכחן תנא דפליג אהאי ברייתא וי\\\"ל דכיון דלא מני גמרא הא עם יע\\\"ל קג\\\"ם דהלכה כאביי משמע דקים ליה לגמרא דהלכה כרבא בהא ולא קי\\\"ל כההיא ברייתא ואיכא תנא דפליג עלה ואע\\\"ג דלא אידכר ההוא תנא הכא בגמרא. ודע דבנוסחא דידן בגמרא הגירסא מהופכת וגירסת רבינו עיקר:\",2,0],[8,362,1,5,\"אחד בעל מום קבוע או בעל מום עובר וכו'. ז\\\"ל רבינו בספר המצות שלו צ\\\"ה הזהירנו מהקריב בעל מום עובר והוא אמרו לא תזבח לה' אלהיך שור ושה אשר יהיה בו מום ונתבאר בספרי שבבעל מום עובר הכתוב מדבר וזה גם כן ילקה עליו כשעבר והקריבו עכ\\\"ל. וטעמו ממה שפירשו שם על פסוק זה מנין לבעל גרב ובעל יבלת ובעל חזזית תלמוד לומר כל דבר רע והרי בעל יבלת מום עובר הוא וכן בעל גרב לח ובעל חזזית ומייתי להו מהאי קרא ואע\\\"ג דבקרא דדריש מיניה בעל מום לא כתיב אלא לא תזבח איכא למימר דכיון דחזינן דקפיד קרא בבעל מום עובר לענין זביחה כמו בבעל מום קבוע ילפינן מיניה דה\\\"ה לשאר לאוין והרמב\\\"ן בהשגותיו על סה\\\"מ כתב וז\\\"ל אני אומר שהמניעה במום קבוע ועובר לאו אחד תמנה שהכתוב מרבה והולך עד שאסר כל מום בין קבוע בין עובר וגם בלאו הראשון נתרבו וכך אמרו בסיפרא וישנו בגמרא תמורה אשר בו מום אין לי אלא מום קבוע מום עובר מנין תלמוד לומר כל אשר בו מום ובשניהם עובר בכל חמשה שמות הללו ונאמרו הכתובים להשלים האיסור ולא אמרו בסיפרי בפסוק לא תזבח לה' אלהיך שור או שה אשר יהיה בו מום שבא למום עובר בלבד אלא גם שם נתרבה הכל וזה מאמרם שם אין לי אלא תם ונעשה בעל מום ממעי אמו מנין ת\\\"ל כל דבר רע מנין בעל גרב ובעל יבלת ובעל חזזית ת\\\"ל מום כל דבר רע מנין לזקן וחולה וכו' עכ\\\"ל:\",1,0],[8,362,1,6,\"ולא קרבנות ישראל בלבד וכו'. מבואר בכתוב:\",1,0],[8,362,1,7,\"המטיל מום בקדשים וכו' מפי השמועה למדו שזה אזהרה שלא יתן בו מום. בסיפרי ובפרק פסולי המוקדשין (דף ל\\\"ד):\",1,0],[8,362,1,7,\"ואינו לוקה אלא בזמן שבית המקדש קיים וכו'. בפרק קמא דעבודה זרה (דף י\\\"ג) אהא דתניא אין מקדישין וכו' בזמן הזה ואם הקדיש בזמן הזה בהמה נועל בפניה והיא מתה מאליה וכו'. ולשוייה גיסטרא אמר רבא מפני שנראה כמטיל מום בקדשים נראה מום מעליא הוא ה\\\"מ בזמן שב\\\"ה קיים דחזי להקרבה השתא דלא חזי להקרבה לית לן בה ופירש\\\"י ה\\\"מ דהוי מטיל מום גמור ואסור משום כל מום לא יהיה בו בזמן ב\\\"ה דקרינא ביה תמים יהיה לרצון להקריב אבל השתא נראה בעל מום הוא ולא אסור מדאורייתא אבל דעת רבינו דאסור מדאורייתא אלא שאינו לוקה:\",2,0],[8,362,1,8,\"הטיל מום בקדשים וכו'. פלוגתא דתנאי בברייתא בפ' פסולי המוקדשין (דף ל\\\"ג:) ופסק כחכמים:\",1,0],[8,362,1,9,\"אחד המטיל מום בקדשים עצמם וכו' וכן המטיל מום בתשיעי של טעות עשירי אינו לוקה. בפרק שלישי דתמורה (דף כ\\\"א):\",1,0],[8,362,1,10,\"המקדיש בעל מום למזבח וכו'. בפרק קמא דתמורה (דף ה') המקדיש בעלי מומין לגבי מזבח אע\\\"פ שהוא בלא תעשה מה שעשה עשוי.\",1,0],[8,362,1,10,\"ומה שכתב ותפדה בערך הכהן ותצא לחולין ויביא בדמיה קרבן. בסוף תמורה תניא (דף ל\\\"ב) אם כל בהמה טמאה אשר לא יקריבו ממנה קרבן לה' והעמיד את הבהמה לפני הכהן והעריך הכהן אותה בבעלי מומין שיפדו הכתוב מדבר וכתב שם רש\\\"י דע\\\"כ בקדשי מזבח מיירי.\",2,0],[8,362,1,10,\"ומה שכתב וכן הדין בבהמת קדשים שנפל בה מום. שם אמרינן לר' יוחנן דהאי ברייתא כוותיה דאותה למעוטי בעל מום מעיקרו שאינו בכלל העמדה והערכה לדברי הכל וקשה היכי רבינו לא מפליג בינייהו ואפשר שרבינו פסק כלוי דאמר התם הכל היו בכלל העמדה והערכה ואפילו בעל מום ואע\\\"ג דאקשינן ללוי והכתיב אותה ואסיקנא בקשיא אשכחן דמסיק בקשיא והלכתא כוותיה וכיון דלוי קשיש מרבי יוחנן פסק רבינו כוותיה ועי\\\"ל דכרבי יוחנן פסק רבינו דע\\\"כ לא אמר ר' יוחנן אותה למעוטי בעל מום מעיקרו אלא לומר דבעל מום מעיקרו אפילו אם מת נפדה דלא בעינן בהו והעמיד אבל בכשהוא חי לדברי הכל נפדה הוא בערך הכהן וזה עיקר שהרי כן כתב רבינו בסמוך גבי מה בין בעלת מום קבוע לבעלת מום עובר:\",3,0],[8,362,1,10,\"ומצות עשה היא לפדות קדשים שנולד בהם מום וכו'. בפ\\\"ב דבכורות (דף ט\\\"ו ע\\\"א):\",4,0],[8,362,1,10,\"וכבר ביארנו בערכין פ״ה שזה שנאמר וכו'. בסוף תמורה דף ל״ג ע״א ובריש פרק על אלו מומין (בכורות ל״ז ע״ב):\",5,0],[8,362,1,11,\"מה בין בעלת מום קבוע לבעלת מום עובר כו'. בפ\\\"ב דבכורות (דף ט\\\"ו:).\",1,0],[8,362,1,11,\"ומ\\\"ש ואם נתעברה קודם שתפדה וילדה אחר פדיון הולד חולין. ג\\\"ז שם.\",2,0],[8,362,1,11,\"ומ״ש ואם מתה קודם שתפדה נפדית אחר שתמות וכו'. במשנה שם (דף י״ד) ובפ' הזרוע (חולין דף ק״ל).\",3,0],[8,362,1,11,\"ומ\\\"ש אבל המקדיש בעלת מום עובר או תמימה ואחר שהקדישה נולד לה מום קבוע אם מתה קודם שתפדה תקבר וכו'. במשנה פ\\\"ב דבכורות ופ' הזרוע.\",4,0],[8,362,1,11,\"ומ\\\"ש ואם נשחטה קודם שתפדה ה\\\"ז נפדית. בפ\\\"ק דמעילה קדשי מזבח תמימים ונעשו בעלי מומין ועבר ושחטן רבי אומר יקברו וחכ\\\"א יפדו.\",5,0],[8,362,1,11,\"ומה שכתב נפדית כל זמן שהיא מפרכסת. בפ\\\"ב דחולין (דף ל') וכ\\\"ת דבעי העמדה והערכה והתנן שחט בה שנים או רוב שנים ועדיין היא מפרכסת הרי היא כחיה לכל דבריה.\",6,0],[8,362,1,11,\"ומ\\\"ש ואם ילדה יקרב ולדה. בפ\\\"ב דבכורות (דף ט\\\"ז) אמרינן על קדם הקדשן את מומן ולדותיהן שנולדו לפני פדיון מקדש קדשי ואמרינן דבפרק אלו קדשים איפליגו אי קדשי ליקרב או אי קדשי לרעייה ופסק רבינו כשמואל ורבא ולא כבר פדא ורב פפא משום דשמואל ורבא הוו מארי דגמרא טפי מינייהו:\",7,0],[8,362,1,11,\"נתעברה קודם שתפדה וילדה אחר וכו'. בפ\\\"ב דבכורות (דף י\\\"ד) שנינו גבי קדם הקדשן את מומן ולדן אסור לאחר פדיון ומפרש בגמרא דמיירי באיעבר לפני פדיון ואתיליד לאחר פדיון ואמרינן בגמרא (דף ט\\\"ו:) אותן ולדות מה תהא עליהן אמר רב הונא כונסן לכיפה והן מתין דהיכי ליעבד לקרבינהו מכח קדושה דחויה קא אתו לפרקינהו לא אלימי למתפס פדיונן אמרי במערבא משום רבי חנינא סמוך לפדיונן מתפיסן לשם אותו זבח ופרש\\\"י קדושה דחויה דאית בהו תרתי לריעותא חדא דאמותן בעלי מומין שנראו ונדחו ועוד דלאחר פדיון נולדו והן עצמן אין יכול להתפיסן לקדושה גמורה להקריב והואיל ואידחו תו לא מיחזו. לא אלימי למיתפס פדיונן בקדושתן כדי שיצאו הם לחולין שכבר יצאה קדושתן אגב פדיון דאמן וכו'. סמוך לפדיון אמן מתפיסן לשם אותו זבח דהשתא חיילא עלייהו קדושה לעצמן דחשבינהו ולא פקעא קדושתייהו על ידי פדיית אמן עכ\\\"ל ואמרינן בגמרא בעא מיניה רבינא מרב ששת מהו שמתפיסם לכל זבח שירצה א\\\"ל אין מתפיסן (אלא לשם אותו הזבח) ותניא כוותיה ופסק רבינו כרבי חנינא משום דרב ששת ורבינא דבתראי נינהו סברי כוותיה וברייתא דתניא כוותיה דרב ששת כוותיה אתיא. ויש בקצת ספרי רבינו טעות סופר והנוסחא הנכונה לפי שאינו יכול להקריבו מכח אמו לפי שבא מכח קדושה דחויה:\",8,0],[8,362,1,12,\"כל פסולי המוקדשין כשיפדו וכו'. משנה בפרק פסולי המוקדשין (דף ל\\\"א:):\",1,0],[8,362,1,12,\"התפיס בכור לבדק הבית וכו'. בפרק התערובות (דף ע\\\"ה:) בעיא דאיפשיטא:\",2,0],[8,362,2,1,\"כל המומין הפוסלין באדם ובבהמה חמשים וכבר נמנו. בפ\\\"ז מהלכות ביאת המקדש:\",1,0],[8,362,2,2,\"ומ״ש ויש מומין אחרים מיוחדים בבהמה וכו'. קשה לי דהא חטיה החיצונות והפנימיות למה לא יפסלו באדם דהא [אחר שנשנו מומין האמורין בבכור שנינו בריש פרק מומין אלו] (בכורות דף מ״ג) מומין אלו פוסלין באדם.\",1,0],[8,362,2,2,\"ומ\\\"ש רבינו וכ\\\"ג הם ואלו הם אם היה גלגל עינה עגול כשל אדם. בפרק אלו מומין במשנה (דף מ') את שגלגל עינו עגול כשל אדם ובגמרא למימרא דלאו היינו אורחיה ורמינהו המפלת כמין בהמה חיה ועוף וכו' מאי טעמא דרבי מאיר הואיל וגלגל עינו עגול כשל אדם אמר רב יוסף ל\\\"ק הא באוכמא הא בחיורא ופירש רש\\\"י באוכמא שחור של עין הבהמה אינו עגול כשל אדם הא בציריא כל בית מושב הלובן והוא עגול כשל אדם ע\\\"כ נראה שהוא גורס הא באוכמא הא בציריא. ויש לתמוה על רבינו שסתם דבריו ולא חילק בזה אולי לא היה זה בגירסתו.\",2,0],[8,362,2,2,\"ומ\\\"ש עינה אחת גדולה כשל עגל והשניה קטנה כשל אווז אבל אם היתה אוזן גדולה ואוזן קטנה אפילו קטנה עד כפול כשר. שם (דף מ':) רבי חנינא בן אנטיגנוס אומר את שיבלת בעינו וכו' עינו אחת גדולה ואחת קטנה אזנו אחת גדולה ואחת קטנה במראה אבל לא במדה ובגמרא תנא גדולה כשל עגל קטנה כשל אווז אזנו אחת גדולה וכו' ורבנן עד כמה תניא אחרים אומרים אפילו אינה לשנייה אלא כפול כשירה. ומשמע דעינו גדולה כשל עגל וכו' רבנן קאמרי לה והכי משמע בריש בכורות (דף ג') ולפיכך פסק רבינו כן ואמרינן בריש בכורות דדוקא עינה אחת גדולה והשניה קטנה הוי מום בבהמה אבל אם היו שתי עיניה גדולות או שתיהן קטנות בבהמה כשר ובאדם פסול וזהו שדקדק רבינו לכתוב כאן במומי בהמה עינה אחת גדולה והשניה קטנה ובפ\\\"ח מהלכות ביאת מקדש גבי מומי אדם כתב מי שעיניו גדולות או שעיניו קטנות כלומר אפילו שתיהן גדולות או שתיהן קטנות דכשר בבהמה פסול באדם וכל שכן אם עינו אחת גדולה והשניה קטנה דאף בבהמה פסול:\",3,0],[8,362,2,2,\"אם יש בלובן עינה יבלת שיש בה שיער. בפרק על אלו מומין (בכורות דף מ':) על אלו מומין שוחטין את הבכור את שיבלת בעינו ורמינן עלה הא דתנן אלו שאין שוחטים עליהם לא במקדש ולא במדינה וכו' בעל יבלת ושני אידי ואידי בעיניו ולא קשיא הא בשחור הא בלבן והא אין מומין בלבן אלא אידי ואידי בלבן ואמר ר״ל ל״ק הא דאית בה שער הא דלית בה שער ומשמע שרבינו אינו מפרש כפירש״י אבל הוא מפרש אידי ואידי מתניתין דעל מומין אלו שוחטין את הבכור את שיבלת בעיניו ומתניתין דאין שוחטין עליהם לא במקדש ולא במדינה בלבן ול״ק הא דהוי מום בדאית בה שער וההיא דאין שוחטין עליהם לא במקדש ולא במדינה בדלית בה שער ומ״מ ק״ל דמשמע דבשחור פשיטא דהוי מומא וכן פירש ה״ר עובדיה וא״כ יש לתמוה על רבינו דמשמע מדבריו דדוקא בלובן הוי מום ולא בשחור דאם לא כן הל״ל אם יש אפילו בלובן עיניה יבלת וצריך לדחוק ולומר דאם יש בלובן עיניה דנקט רבינו לרבותא נקטיה וכל שכן בשחור. ועוד יש לתמוה דכיון שהקשה והא אין מומין בלבן היכי מתרץ אידי ואידי בלבן ול״ק הא דאית בה שיער הא דלית בה שיער ואי אית בה שיער מאי הוי והא אין מומין בלבן ויש לדחוק ולומר דהכי מתרץ ליה כי שמיע לך דאין מומין בלבן ה״מ ביבלת שאין בה שער אבל ביש בה שער בלבן נמי הוי מום:\",4,0],[8,362,2,2,\"אם ניקב העור שבין שני חוטמיה במקום הנראה. בתוספתא דבכורות פ״ד ניקבו חוטמיו זה לתוך זה בפנים לא ישחוט מבחוץ ישחוט פירוש מבפנים לא ישחוט במדינה מפני שאינו מום מבחוץ ישחוט שהוא מום ובגמרא פרק על אלו מומין (בכורות דף ל״ט) תנו רבנן ניקבו חוטמיו זה לתוך זה מבחוץ הרי זה מום מבפנים אינו מום:\",5,0],[8,362,2,2,\"פיה דומה לשל חזיר פרוס וכו'. בפרק על אלו מומין (בכורות דף מ'):\",6,0],[8,362,2,3,\"חטיה החיצונות וכו'. משנה שם (דף ל\\\"ט) חטיו החיצונות שנפגמו שנגממו והפנימיות שנעקרו ובספרי רבינו כתוב שניקבו ונראה שטעות סופר הוא אלא שבסמ\\\"ג מצאתי כמו שכתוב בספרי רבינו ונראה שנוסחא אחרת היתה להם וכתב סמ\\\"ג חטיה החיצונות יינציב\\\"א בלע\\\"ז ופנימיות הם שהשינים הגדולות קבועים בהם:\",1,0],[8,362,2,4,\"אם ניטלו קרניה וזכרותן עמהם ולא נשאר מהם כלום. בפרק מומין אלו (בכורות דף מ״ד) אמר אמימר ניטלו קרניהן וזכרותן עמהם פסולה ואין פודין עליהם ניטלו טלפים וזכרותן עמהם פסולה ונפדין עליהם מיתיבי ניטלו קרנים וטלפים וזכרותן עמהם פסולים ונפדין עליהם לא קשיא הא דאתעקר אתעקורי הא דאיגום איגומי [דאיגום איגומי] פסול ורמינהו פרה שקרניה וטלפיה שחורים יגוד תרגמא זעירי מעילוי זכרות. ופירש״י זכרותן היינו עצם התחוב בתוך הקרנים זכרות הטלפים והיינו עצם שבתוך הטלפים דזו היא כף הרגל. ואין נפדין עליהם וכו'. דלא הוי מום גמור אלא לאיפסולי. ומדאמרינן הא דאתעקר איתעקורי הא דאיגום איגומי וכן מדתרגמא זעירי מעילוי זכרות משמע בהדיא דכל שניטל מהזכרות אפילו איגום איגומי פסולה ולא שאני לן בין אתעקר אתעקורי לאיגום איגומי אלא לענין אם נפדין עליהם וכ״כ רבינו לקמן בפרק זה גבי חליים שהן פוסלין ואין נפדין עליהם אם נגממו קרניו אע״פ שנשאר מזכרותן מעט סמוך לבשר תפדה והטעם פשוט משום דכיון דמימרא דאמימר בקרנים אוקימנא באיגום איגומי סיפא דלישניה בטלפים ע״כ מיתוקמא נמי באיגום איגומי ואפ״ה אמר דנפדים עליהם אלמא דבטלפים אפילו איגום איגומי הוי מום קבוע לפדות עליו.\",1,0],[8,362,2,4,\"ומה שכתב אבל נקבה שיש לה קרנים כשירה. ברייתא שם יש דברים שהם כמומין ואינם כמומין וכו' ואלו הם עז שאין לו קרנים ורחל שיש לה קרנים ומשמע לי דהיינו בעז שאין לו קרנים מתחלת ברייתו דומיא דרחל שיש לה קרנים ועוד דאילו בהיו לו וניטלו הא אמרינן בסמוך דפסול ולפי זה יש לתמוה על רבינו למה לא כתב דין זה ואפשר שרבינו מפרש דעז שאין לו קרנים דמכשר בברייתא היינו בניטלו קרניו בלא זכרות:\",2,0],[8,362,2,4,\"אם נפגם העור שחופה את גיד הבהמה. במשנה (דף ל\\\"ט:) בפרק על אלו מומין נפגם הזובן ובגמרא אמר רבי אלעזר נפגם ולא ניטל כיס ולא זכרות ופירש\\\"י הזובן זהו נרתק שהגיד חבוי בו. נפגם הזובן הוי מום דלא הדרא בריא ולא ניטל דניטל לא הוי מום דחוזר לאיתנו כיס אם נפגם הוי מום אבל זכרות גיד עצמו שנפגם לא הוי מום דמעלה ארוכה עכ\\\"ל ולא ידעתי למה קיצר רבינו מלהזכיר זה.\",3,0],[8,362,2,4,\"ומ\\\"ש אם נפגמה הערוה של נקבה. שם במשנה:\",4,0],[8,362,2,4,\"אם נפגם הזנב מן העצם אבל לא מן הפרק. שם במשנה ופירש\\\"י מן הפרק אם נפגם בין הפרקים מעלה ארוכה.\",5,0],[8,362,2,4,\"ומ\\\"ש אם היה ראש הזנב מפוצל לשנים כשני עצמים. שם במשנה היה ראש הזנב מפציל עצם כשני עצמים ומפרש בתוספתא שהיה ראש הזנב מופצל לשני עצמות.\",6,0],[8,362,2,4,\"ומה שכתב אם היה בין חוליא לחוליא מלא אצבע כשר. גם זה שם במשנה:\",7,0],[8,362,2,4,\"אם היה הזנב קצר וכו' ובטלה אורך שתי חוליות מום וכו'. שם משנה וגמרא:\",8,0],[8,362,2,4,\"זנב הגדי שהיה רך ומדולדל דומה לשל חזיר. שם (דף מ':) במשנה זנב הגדי שהוא דומה לשל חזיר ובגמרא אמר רב פפא לא תימא דקטינא אלא דכריכא אע\\\"ג דאלימא ופרש\\\"י כריכא עגולה שזנב הטלה הוי רחבה יתר על עביה. קטינא דקה מאד עכ\\\"ל. וכתב הראב\\\"ד על דברי רבינו דומה שהוא גורס דרכיכא וקטינא וכו':\",9,0],[8,362,2,4,\"אם נשבר עצם מן הזנב. נלמד מתוספתא דבסמוך דלא הכשיר בנשתברו רוב צלעותיו אלא מפני שאינם בגלוי אבל נשבר עצם מן הזנב מאחר שהוא בגלוי הוי מום:\",10,0],[8,362,2,4,\"אבל אם נשבר עצם מצלעותיו כשר וכו'. בתוספתא דבכורות פ\\\"ד נשתברו רוב צלעותיו או שהיה בו מום מבפנים אינו מום שנאמר עור או פסח מה עור ופסח מומין [המיוחדין מום] שבגלוי. ובגמרא (דף ל\\\"ט) פרק על אלו מומין בעי אם יש מחוסר אבר מבפנים למאי אי לבכור פסח או עור כתיב או לקדשים עורת או שבור כתיב ופרש\\\"י פסח או עור כתיב דמשמע בגלוי אין בסתר לא:\",11,0],[8,362,2,5,\"בעלת חמש רגלים וכו'. משנה פרק על אלו מומין (בכורות דף מ'):\",1,0],[8,362,2,5,\"אם היתה אחת מרגליו וידיו וכו'. שם במשנה שרגליו קלוטות כשל חמור ובגמרא אמר רב פפא לא תימא דעגולין ולא סדיקן אלא כיון דעגילן אע\\\"ג דסדיקן:\",2,0],[8,362,2,5,\"אם נגממו טלפיה וכו'. כבר נתבאר בפרק זה אצל ניטלו קרניה:\",3,0],[8,362,2,6,\"כל מום מע״ג מום המנויים בבהמה וכו'. בס״פ על אלו מומין (בכורות דף מ״א:) תנן על אלו מומין שוחטין את הבכור ופסולי המוקדשין נפדין עליהם.\",1,0],[8,362,2,6,\"ומ\\\"ש חוץ מזקן וחולה ומזוהם שאע\\\"פ שאינו כשר לקרבן אינו נפדה וכו'. שם במשנה ואלו שאין שוחטין עליהן לא במקדש ולא במדינה חוורור והמים שאינן קבועים וחוטיו הפנימיות שנפגמו אבל לא שנעקרו ובעל גרב ובעל יבלת ובעל חזזית וזקן וחולה ומזוהם ושנעבדה בו עבירה ושהמית אדם ע\\\"פ עד אחד או ע\\\"פ הבעלים וכתב רבינו בפירוש המשנה לא ישחוט עליהם במדינה לפי שאינן מומין קבועים:\",2,0],[8,362,2,7,\"ומ\\\"ש ארבעה מומין עוברים יש באדם ובבהמה. במשנה (דף מ\\\"ג) מומין אלו בין קבועים בין עוברים פוסלין באדם.\",1,0],[8,362,2,7,\"ומ\\\"ש ואלו הן גרב לח. נתבאר במה שכתבתי בפ\\\"ז מביאת המקדש דהיינו בלח מבפנים ומבחוץ שהוא יכול להתרפא.\",2,0],[8,362,2,7,\"ומ\\\"ש חזזית שאינה מצרית. נתבאר שם.\",3,0],[8,362,2,7,\"ומ\\\"ש מים שיורדים בעין ואינן קבועים סנוירים שאינם קבועים. היינו דתנן בפ' הנזכר (דף מ\\\"א) חוורור והמים שאינם קבועים גבי שאין שוחטין עליהם לא במקדש ולא במדינה:\",4,0],[8,362,2,9,\"יש ארבעה חוליים אחרים וכו' ואלו הם מי שבלובן עינו יבלת שאין בה שיער. כבר כתבתי בפרק זה דבגמרא אוקימנא הא דתנן גבי אלו שאין שוחטין עליהן לא במקדש ולא במדינה בעל יבלת כשהיה בלבן יבלת שאין בה שער.\",1,0],[8,362,2,9,\"ומה שכתב אם נגממו קרניו אף על פי שנשארו מזכרותן מעט סמוך לבשר. נתבאר בפרק זה.\",2,0],[8,362,2,9,\"ומה שכתב אם נפגמו חיטיו הפנימיות. במשנה שכתבתי בסמוך:\",3,0],[8,362,2,9,\"ומה שכתב וכן בהמת קדשים שנעבדה בה עבירה או שהמיתה את האדם וכו'. מפרש במשנה הנזכרת ובפרק כל האסורים תניא הרובע והנרבע הם כקדשים שקדם מום עובר להקדשן וצריכים מום קבוע לפדות עליהם:\",4,0],[8,362,2,10,\"בהמה שנולד בה אחד מהטרפיות וכו'. בר\\\"פ המזבח מקדש אמרינן דטריפה פסולה מעל גבי המזבח ובר\\\"פ התערובות (דף ע\\\"א:) אמרינן דטריפה שנתערבה בזבחים ירעו עד שיסתאבו.\",1,0],[8,362,2,10,\"ומה שכתב רבינו הרי הוא אומר הקריבהו נא לפחתך. יש לתמוה שהרי בתורת כהנים ובפרק ו' דתמורה (דף כ\\\"ט) דורש כשהוא אומר מן הבקר למטה וכו' להוציא את הטריפה משמע שמן התורה הוא דהא דריש לה מקרא ובפרק בתרא דבכורות (דף נ\\\"ז) יליף דטרפה פסול לקרבן בגזירה שוה ואפשר שסובר רבינו דסמך בעלמא הוא דמסמיך להו אקרא ואגזירה שוה דהא קיימא לן דלא מיפסיל משום מום אלא בגלוי דוקא אי נמי דה\\\"ק אפילו לא היה בה איסור מן התורה הוי ליה לפסלה משום הקריבהו נא לפחתך.\",2,0],[8,362,2,10,\"ומ\\\"ש ואע\\\"פ שאינה ראויה לקרבן אין פודין אותה וכו'. משנה בתמורה (דף ל') ס\\\"פ כל האסורים על גבי המזבח:\",3,0],[8,362,2,11,\"ומ״ש נשחטה ונמצאת טרפה הרי זה תצא לבית השרפה. בפרק כיצד צולין (פסחים דף פ״ב) אמרינן דמדכתיב בקדש באש תשרף לימד על כל פסולים שבקדש בשריפה:\",1,0],[8,362,2,11,\"וכן אם נמצא אחד מאיבריה הפנימיים חסר וכו' הרי זו אסורה למזבח ותשרף וכו'. בפרק על אלו מומין (בכורות דף ל״ט) בעי רב אחדבוי בר אמי יש מחוסר אבר מבפנים או אין מחוסר אבר מבפנים וכו' לאישחוטי ולאיפרוקי לא איבעי' לן כי מיבעי' לן לאיפסולי מאי תמים יהיה לרצון אמר רחמנא תמים אין חסרון לא או דילמא תמים יהיה לרצון כל מום לא יהיה בו מה מום מאבראי אף חסרון מאבראי ת״ש ואת שתי הכליות ולא בעל כוליא אחת ולא בעל ג' כוליות ותניא אידך יסירנה לרבות בעל כוליא אחת וכו' לימא בהא קא מיפלגי דמר סבר חסרון מבפנים שמיה חסרון וכו' ולא קשיא וכו' ופירש רש״י לאישחוטי בכור על חסרון שבפנים ולאפרוקי קדשים לא מיבעי' דלא חשיב מומא כולי האי:\",2,0],[8,362,2,12,\"אי זו היא סנורים קבועים וכו'. משנה וגמרא בפרק על אלו מומין (בכורות דף ל״ח):\",1,0],[8,362,2,13,\"ובמה יודע שהמים קבועים וכו' עד הרי אלו קבועים ודאי. משנה וגמרא שם:\",1,0],[8,362,2,14,\"ומ\\\"ש ואם חסר א' מכל אלו הרי זה ספק וכו' עד סוף הפרק. הכל שם בעיא דלא איפשיטו זולת שבנוסחא דידן בגמרא (דף ל\\\"ט) קודם שתייה ודאי מעלי לה (בשערי) לאחר שתייה מאי ורבינו גריס איפכא. ודע שאמרו שם את\\\"ל בסעודה ראשונה. וא\\\"ת דלפי שיטת רבינו שהיא דכל היכא דאמרינן את\\\"ל איפשיטא ההיא בעיא הוה ליה לפרש שאם לא היה בסעודה ראשונה אינה ספק אלא ודאי שלא הוקבע המום י\\\"ל שמ\\\"ש ואם חסר אחד מכל אלו הרי זה ספק לא קאי לסעודה ראשונה דכל שלא אכלה קודם סעודה ראשונה ודאי לא הוקבע המום ומפני כך כשכתב כיצד לא הזכיר לא סעודה ראשונה ולא שניה משום דאם לא היה קודם סעודה ראשונה אינה ספק כמ\\\"ש:\",1,0],[8,362,3,1,\"אין המומין פוסלין בעוף וכו'. בריש פרק ב' דתמורה (דף י\\\"ד) ופ\\\"ג דמנחות (דף כ\\\"ה) תמות וזכרות בבהמה ואין תמות וזכרות בעופות.\",1,0],[8,362,3,1,\"ומ״ש בד״א במומים קטנים אבל עוף שיבש גפו או נקטעה ידו או נסמית עינו או נקטעה רגלו אסור לגבי המזבח וכו'. משנה בפרק חטאת העוף (זבחים דף ס״ח) ובת״כ תמים זכר בבקר תמות וזכרות בבהמה ואין תמות וזכרות בעוף יכול שיבש גפו ושנסמית עינו ושנקטעה רגלו תלמוד לומר מן העוף ולא כל העוף.\",2,0],[8,362,3,1,\"ומ\\\"ש וכן אם נולד בו אחת מהטריפות וכו'. נתבאר בפרק שקודם זה דטעמא משום הקריבהו נא לפחתך וההוא טעמא שייך גם בעוף:\",3,0],[8,362,3,2,\"תורים קטנים פסולים וכו'. משנה בפ\\\"ק דחולין (דף כ\\\"ב) ופירש\\\"י תחלת הציהוב כשמתחילין להביא נוצה יפה צהובה סביב לצוארו פסולים בזה ובזה וכו' דבבני יונה פסולים משום גודלן ובתורים מפני קטנן דיצאו מכלל קטנים ולכלל גדולים לא באו.\",1,0],[8,362,3,2,\"ומ\\\"ש ועד מתי יהיו בני יונה כשרים כל זמן שעוקר כנף ומתמלא מקום עיקרו דם. שם מאימתי בני יונה כשרים וכו' מכי שמיט גדפא מיניה ואתי דמא ופירש\\\"י מאימתי בני יונה כשרים דביום שנולדו מאוסים הם ורבינו נראה שהיה גורס עד אימתי בני יונה כשרים ונראה שהיא הגירסא הנכונה.\",2,0],[8,362,3,2,\"ומ\\\"ש והתורים כשרים משיזהבו. שם ופירש\\\"י שיהיו כנפי גופם גדולים ואדומים ומזהיבים כזהב:\",3,0],[8,362,3,3,\"הטומטום והאנדרוגינוס וכו'. בסוף פרק על אלו מומין (בכורות דף מ״א) תנן דטומטום ואנדרוגינוס אין נשחטין לא במקדש ולא במדינה וחכמים אומרים אין מום גדול מזה.\",1,0],[8,362,3,3,\"ומה שכתב הרי הם פסולים למזבח מדרך אחרת וכו' לפיכך אף העוף שהוא טומטום או אנדרוגינוס פסול למזבח הכי אמרי' בפ' המזבח מקדש (זבחים דף פ״ה) דטומטום ואנדרוגינוס דעוף מטמאים כגריס בבית הבליעה כלומר אם מלקה ופירש רש״י אע״פ שלא נאמר תמות וזכרות בעופות קסבר בריה בפני עצמה היא ואינה ספק זכר ספק נקבה עכ״ל. ואע״ג דרבי אליעזר פליג עליה בפרק על אלו מומין פסק רבינו כתנא דסתם ברייתא ואע״ג דתניא בתורת כהנים העוף שלא נאמר בו זכר ונקבה אין טומטום ואנדרוגינוס פוסלין בו לא חש לה רבינו משום דס״ל דרבי אליעזר היא ולא קי״ל כוותיה. ומ״מ יש לדון על הטעם שכתב רבינו שהרי לא נאמר זכר תמים בעוף וצריך לומר דה״ק כיון שלמדנו בקרבנות שהטומטום והאנדרוגינוס מין אחר א״כ בעוף ג״כ הם מין אחר והתורה לא הכשירה מהעוף אלא תורים ובני יונה ואלו אינם לא תורים ולא בני יונה:\",2,0],[8,362,3,4,\"וכן הכלאים ויוצא דופן ומחוסר זמן וכו' עד פרט ליתום. בת\\\"כ.\",1,0],[8,362,3,4,\"ומ\\\"ש שנולד אחר שנשחטה אמו. משנה בפרק בתרא דבכורות (דף נ\\\"ז) איזהו יתום כל שמתה אמו או נשחטה ואחר כך ילדה ואיני יודע למה השמיט רבינו שמתה אמו:\",2,0],[8,362,3,5,\"הנדמה אע״פ שאינו כלאים וכו'. פרק יוצא דופן (נדה דף מ״א) ופרק שני דבכורות (דף י״ז).\",1,0],[8,362,3,5,\"ומ\\\"ש אע\\\"פ שיש בו מקצת סימנים וכו' שאין לך מום קבוע גדול מן השנוי. אע\\\"ג דתנן בפרק שני דבכורות (דף ט\\\"ז:) שאם יש בו מקצת סימנים חייב בבכורה הא אמרינן בריש מכילתין (דף ג':) בשם רבי יוחנן דמום קבוע הוי לישחט עליו ופירש\\\"י דהא דקתני חייב ליתנו לכהן קאמר אבל למזבח לא קרב דהאי דאישתני מום קבוע הוי לישחט עליו בחוץ והתוספות כתבו בפרק בתרא דכריתות בכל מקום רגיל לדלג נדמה כאילו הוא בכלל כלאים וזה דעת רבינו שכשמנה כל האסורים למזבח לקמן דילג נדמה:\",2,0],[8,362,3,6,\"וכן הרובע והנרבע והמוקצה לעבודה זרה וכו'. משנה וגמרא בתמורה פרק כל האסורים (תמורה דף כ״ח).\",1,0],[8,362,3,6,\"ומ\\\"ש וכן בהמה או עוף שהרגו את האדם הרי הם כרובע ונרבע ופסולים למזבח. במשנה ריש פרק התערובות (דף ע\\\"א:):\",2,0],[8,362,3,7,\"ויראה לי שאע״פ שאין כל הפסולים האלו וכו'. בפרק אותו ואת בנו (חולין דף פ':) גבי הא דתנן דשוחט אותו ואת בנו קדשים בפנים לוקה ופריך ולילקי נמי משום לאו דמחוסר זמן דתניא מנין לכל הפסולים שבשור ושבשה שהוא בלא ירצה תלמוד לומר ושור ושה שרוע וקלוט וגו' לימד על הפסולים שבשור ושבשה שהוא בלא ירצה כי קא חשיב לאו דאותו ואת בנו לאוי נוכראי לא קא חשיב וכו' ר' זירא אמר הנח למחוסר זמן שהכתוב נתקו לעשה מ״ט דאמר קרא מיום השמיני והלאה ירצה מיום השמיני אין מעיקרא לא לאו הבא מכלל עשה עשה וי״ל מאחר שמפורש בדברי רבי זירא דלא לקי למה תלה הדבר בעצמו שכתב ויראה לי ואין לומר דמשום דיש מחלוקת בדבר דלמאי דשני לאוי נוכראי לא קא חשיב לוקה הוא ובפרק בתרא דזבחים (דף קי״ד) אמרינן דלא אמר רבי זירא אלא לרבנן אבל לר״ש לקי מש״ה תלה הדבר בעצמו לומר שהוא פוסק כרבנן וכדרבי זירא דמה נשתנה דין זה משאר דינין שהוא מכריע בין המחלוקות וכותבם סתם ואינו תולה הדבר בעצמו ועוד יש לתמוה עליו למה תולה הדבר בשלא נתפרשה אזהרתן ואינו כן שהרי הגמרא אומרת נתפרשה אזהרתן ולא פטר מחוסר זמן אלא מפני שניתק לעשה ועוד שכל שאר פסולים חוץ ממחוסר זמן ילקה עליהם שהרי לא נתקן לעשה ומיהו בהא אפשר לומר שרבינו הוקשה לו דהא לא ירצה לא משמע דמזהר דלא יקריבוהו ולא לימד אלא שלא יעלה לרצון אבל אזהרה שלא יקריבנו אין כאן ולכך משמע ליה דה״מ לשנויי הכי אלא דלפום מאי דס״ד דמקשה דלא ירצה היינו להזהיר שלא יקריבוהו שני ליה אבל אפשר דאין כאן אזהרה מלהקריב כדאמרינן ומפני כך לא רצה רבינו לכתוב שהכתוב נתקו לעשה דהוה משמע דפשיטא ליה דלא ירצה הוי אזהרה שלא יקריבוהו אלא תלה הדבר בשלא נתפרשה אזהרתן לומר דאפשר דלא ירצה לא בא להזהיר שלא להקריב ואפילו את״ל שבא להזהיר שלא להקריב כיון שאינו מפורש שהרי אפשר שלא בא להזהיר שלא יקריבנו אלא לומר שלא יעלה לרצון אין ללקות מספק ויש סעד לדבריו דלקמן בסמוך כתב רבינו טעם פיטור מחוסר זמן ממלקות מפני שהוא לאו הבא מכלל עשה ולא כתב מפני שניתק לעשה כדרבי זירא משום דדילמא לא ירצה לא בא להזהיר שלא יקריבנו ואין כאן לאו לשנצטרך לומר שניתק לעשה:\",1,0],[8,362,3,7,\"אבל אתנן זונה ומחיר כלב וכו'. זה על הכלל הידוע בכמה מקומות בגמרא לאו שבכללות אין לוקין עליו ודברי רבינו בכאן ע\\\"פ דרכו בספר המצות שלו בשורש התשיעי בפירוש לאו שבכללות אין לוקין עליו אבל הרמב\\\"ן בהשגותיו חולק עליו ומפרש בע\\\"א:\",2,0],[8,362,3,8,\"מצות עשה להקריב כל הקרבנות מיום השמיני והלאה וכו' ואע\\\"פ שמחוסר זמן פסול אינו לוקה וכו'. נתבאר בסמוך:\",1,0],[8,362,3,9,\"תורים שלא הגיע זמנן וכו'. מחוסר זמן כבר נתבאר בסמוך שאינו לוקה עליו משום דלית ביה אלא לאו הבא מכלל עשה ותורים שלא הגיע זמנן ובני יונה שעבר זמנן לא לקי עלייהו מהאי טעמא דלית בהו לאו ולא שמעינן להו דפסולי אלא מדכתב והקריב מן התורים או מן בני היונה:\",1,0],[8,362,3,10,\"המקדיש טומטום ואנדרוגינוס וטריפה וכו' ואינן כבעל מום שבעל מום יש במינו קרבן. בסוף פרק שני דתמורה (דף י\\\"ז ע\\\"א) תנן רבי אליעזר אומר הכלאים הטריפה ויוצא דופן [וטומטום ואנדרוגינוס] לא קדושים ולא מקדישין וכתב רבינו בפירוש המשנה שדברי ר\\\"א אין עליהן חולק עכ\\\"ל. ואפילו אם היה עליהם חולק מאחר דאמוראי שקלי וטרי לפרושי מילתיה הוה משמע דהלכתא כותיה ואע\\\"ג דאתמר עלה בגמרא אמר שמואל לא קדושים בתמורה ולא מקדישין לעשות תמורה לא למעט ולומר שאם הקדישן בפה יהיו קדושים דאדרבה במכ\\\"ש אתיא וכן פירש\\\"י וז\\\"ל לא קדושים בתמורה ואע\\\"פ שהתמורה חלה קדושת הגוף על בעל מום קבוע אינה חלה על אלו וכל שכן שאין קדושת הגוף חלה עליה בהקדש הפה אלא קדושת דמים כעצים ואבנים ואינם צריכים מום ליפדות עכ\\\"ל.\",1,0],[8,362,3,10,\"ועל מ\\\"ש רבינו וימכרו ויביא בדמיהם כל קרבן שירצה כתב הראב\\\"ד מדקאמר ויביא בדמיהם כל קרבן שירצה וכו'. וי\\\"ל שמ\\\"ש\",2,0],[8,362,3,10,\"רבינו ואינם כבעל מום לא לענין קדישי ולא קדישי קאמר אלא לענין\",3,0],[8,362,3,10,\"מ\\\"ש ה\\\"ז כמקדיש עצים ואבנים קאי כלומר ואינו חייב מלקות ואתא למיהב טעמא אמאי לא מחייב מלקות כמו מקדיש בעלי מומין וקאמר דשאני התם שיש במינו קרבן. והם דברי רב פפא בגמרא:\",4,0],[8,362,3,10,\"אבל המקדיש רובע ונרבע וכו'. בר״פ כל האסורים (תמורה דף כ״ח) תניא הרובע והנרבע וכו' הם כקדשים שקדם מום עובר להקדשן וצריכים מום קבוע ליפדות עליהם:\",5,0],[8,362,3,10,\"וכן המקדיש מחוסר זמן וכו'. פשוט הוא:\",6,0],[8,362,3,10,\"כתב הראב\\\"ד ונרבע א\\\"א מ\\\"ט לא תני יתום שנולד אחר שנשחטה אמו עכ\\\"ל. ומשמע דקאי למה שכתב אבל המקדיש רובע ונרבע וכו' הרי זה כבעל מום עובר אמאי לא תני בהדייהו יתום והר\\\"י קורקוס ז\\\"ל תירץ דיתום הוי בכלל יוצא דופן דכיון שנולד אחר שנשחטה אמו אין זו לידה וכך אמרו פרק שני דחולין (דף ל\\\"ח:) [אי דמתה אימיה] והדר ילידתיה מכי יולד נפקא וכתב רש\\\"י דהיינו יוצא דופן ושם העמידו הפסוק בזה פירש למיתה וזה פירש לחיים ומשום דקי\\\"ל דא\\\"א לצמצם השמיטו רבינו:\",7,0],[8,362,3,12,\"כל האסורים לגבי המזבח וכו'. משנה בר״פ התערובות (דף ע':) ובתמורה ר״פ כל האסורים (תמורה דף כ״ח).\",1,0],[8,362,3,12,\"ומ״ש וכולם ולדותיהן מותרים. משנה בפרק כל האסורים (תמורה דף ל':):\",2,0],[8,362,3,12,\"ומ\\\"ש חוץ מולד נרבעת ונעבדת ומוקצת ושהמיתה את האדם. בפרק כל האסורים (שם:) אמר רבא ולד הנרבעת אסורה היא וולדה נרבעו ולד נוגחת אסורה היא וולדה נגחו ולד מוקצת ונעבד מותר מ\\\"ט לאימיה אקציה לאימיה פלחי לה איכא דאמרי ולד מוקצה ונעבד אסור מ\\\"ט דניחא ליה בניפחיה ופסק רבינו כלישנא בתרא:\",3,0],[8,362,3,13,\"ומ\\\"ש בד\\\"א בשנעבדה בה עבירה או שהמיתה כשהיתה מעוברת וכו' אבל אם נתעברה אחר שנעבדה בה עבירה או אחר שהמיתה הרי ולדה כשר למזבח. שם פלוגתא דאמוראי ופסק כרבא דאמר הכי.\",1,0],[8,362,3,13,\"ומ\\\"ש אפילו נרבעת כשהיא מוקדשת ואחר כך נתעברה וכו'. שם מימרא דרב נחמן ואית בה תרי לישני ופסק כלישנא קמא וכתב הר\\\"י קורקוס ז\\\"ל דטעמא דכיון דלא הוי אלא משום ביזוי אזלינן לקולא ותו דרבא דמוקי פלוגתייהו בזה וזה גורם משמע דלא מפליג מידי דהא לא קאמר דמודו אלא היכא דהיא וולדה נגחו ונרבעו וכל השאר זה וזה גורם הוא ומותר ולא מפלגינן מידי וזה ברור עכ\\\"ל.\",2,0],[8,362,3,13,\"ומ\\\"ש וכן אפרוח ביצת טריפה מותר למזבח. ברייתא שם:\",3,0],[8,362,3,14,\"המשתחוה לקמה חטיה מותרים למנחות וכו'. בעיא בפרק כל הצלמים (עבודה זרה דף מ״ו:) ובעא מר זוטרא בריה דרב למפשטה מדתנן כל האסורים למזבח ולדותיהם מותרים כלומר וקמח למנחות דמי לולדות ואע״ג דדחי ליה התם מדאמר רב נחמן עיברו ולבסוף נרבעו ד״ה אסורים הא אסיקנא התם הכי השתא התם מעיקרא בהמה והשתא בהמה דשא הוא דאחיזא באנפה הכא מעיקרא חיטי והשתא קמחא:\",1,0],[8,362,3,14,\"וכן בהמה שפטמה וכו'. ס״פ כל האסורים (תמורה דף כ״ט):\",2,0],[8,362,3,15,\"לוקחין כל הקרבנות מהעכו\\\"ם וכו'. ברייתא בריש פרק שני דעבודה זרה (דף כ\\\"ב:):\",1,0],[8,362,4,1,\"אחד הבהמה ואחד העוף וכו'. נתבאר בפרק שקודם זה ולגבי עוף בפרק המזבח מקדש (זבחים דף פ״ה:) בעי ר' ירמיה אם יש נרבע בעופות ופשטינן ממתני' דיש נרבע בעופות אמר רב נחמן בר יצחק אף אנן נמי תנינא הנרבע והמוקצה והנעבד ואתנן ומחיר וטומטום ואנדרוגינוס כולם מטמאים בגדים בבית הבליעה שמע מינה:\",1,0],[8,362,4,2,\"הרובע והנרבע ושהמית את האדם וכו'. במשנה בריש פרק התערובות (דף ע') ובפ\\\"ו דתמורה (דף כ\\\"ח):\",1,0],[8,362,4,2,\"ומ\\\"ש היה שם עד אחד וכו'. בקידושין פרק האומר (דף ס\\\"ה ס\\\"ו) אמר אביי אמר לו עד אחד שורך נרבע והלה שותק נאמן ותנא תונא וכו' ומשמע טעמא מפני שהבעל שותק הא אם היה מכחיש אין העד נאמן:\",2,0],[8,362,4,3,\"בהמה ששחקו בה והגיחוה עד שהמיתה את האדם וכו'. בפרק שור שנגח ד' וה' (בבא קמא דף מ':) פלוגתא דרב ושמואל ופסק כרב דהלכה כוותיה באיסורי:\",1,0],[8,362,4,3,\"אין הבהמה נפסלת משום רובע וכו'. כתב הראב״ד זה המחבר דימה איסור מזבח וכו'. מ״ש ומתניתין היא בנדה הוא בפרק יוצא דופן (נדה דף מ״ה).\",2,0],[8,362,4,3,\"ומ\\\"ש ואולי אין מדמין שהרי נרבע על פי הבעלים או ע\\\"פ עד אחד שאינו במיתה ופסול למזבח י\\\"ל דשאני התם שהביאה היתה ביאה ואע\\\"פ שלא נודע הדבר בשני עדים כיון שנודע על פי עד אחד והבעל שותק מהימנינן ליה ליפסל מעל גבי המזבח אבל כשהנרבע פחות מכשיעור אפילו יש שני עדים בדבר אין כאן ביאה כלל וכיון שכן אין כאן נעבדה בה עבירה ואפילו אם תימצי לומר שהרובע נהנה לא מיפסלא משום הכי כיון שאין כאן ביאה דהוי ליה כמעשה חידודין דאע\\\"פ ששניהם נהנים לא מיחייבי מיתה ולא מיפסלי מעל גבי המזבח. ומה שלא הזכירו בפרק יוצא דופן כשהבהמה רובעת לפחות משלש שנים משום דהיא מילתא דלא שכיחא כלל:\",3,0],[8,362,4,4,\"מאימתי תפסל הבהמה או העוף וכו'. בתמורה בפרק כל האסורים (תמורה דף כ״ט) א״ר יצחק אין מוקצה אסור עד שיעבדו ופירש״י עד שיעבדו בו שום עבודה לצורך עבודה זרה או משיכת קרון או שום דבר אבל מקמי הכי לא מיתסרי. וכתב הראב״ד יש בספרים שלנו נוסחא אחרינא וכו' ונוסחא זו שכתב הראב״ד רש״י הזכירה גם כן ודברי רבינו כנוסחא האחרת והתוס' מכריע כדברי רבינו ומכל מקום קשיא לי על רבינו למה פסק כרב יצחק כיון דפליגי עליה דאמרי' עלה עולא א״ר יוחנן עד שימסרוהו למשרתי ע״ז בהא א״ר יוחנן עד שיאכילוהו כרשיני עבודה זרה אמר ליה רבי אבא לבהא מפלגיתו אתון אעולא אמר ליה לא עולא נמי כי קאמר הוא דספי ליה כרשיני עבודה זרה ומאחר דרבי יוחנן פליג אדרב יצחק הוה ליה למיפסק כרבי יוחנן ויש לומר דבתר הכי אמרי' תני רב חנניה טריטאה קמיה דרבי יוחנן אין מוקצה אסור אלא עד שיעשו בו מעשה הוא תני ליה והדר אמר לה מאי מעשה עד שיגוזו ויעבדו בו וכיון דרב יצחק אתי כתני קמיה דרבי יוחנן פסק הכי ולא חש לעולא ולבהא ועוד דהא דתני קמיה דר' יוחנן ברייתא היא בתוספתא פרק ששי ואיכא למימר דבתר דאמר רבי יוחנן לדעולא ולדבהא שמעה להאי ברייתא הדר ביה ומשום הכי שתיק כי תנא קמיה דקבלה מיניה:\",1,0],[8,362,4,4,\"ומ\\\"ש רבינו שאין הקדש לע\\\"ז. בתוספתא הנזכרת מסיים אבל אמר שור זה לעבודה זרה ובית זה לעבודה זרה לא אמר כלום שאין הקדש לע\\\"ז:\",2,0],[8,362,4,5,\"הרובע והנרבע בין שהיתה הבהמה שלו בין של חבירו וכו' אבל המוקצה אם היה שלו וכו' הנעבד בין שעבד שלו בין של חבירו וכו' עד הרי זה אסור. הכל בתוספתא דתמורה פ' רביעי אלא שמה שאמר רבינו שאם הקצה אחר הקדשו מותר לא מצאתיו בתוספתא בנעבד כתוב באונס כשר ואפשר שחסרון וטעות סופר יש בתוספתא שבידינו:\",1,0],[8,362,4,6,\"וכתב הראב\\\"ד בין שעבד שלו בין שעבד של חבירו א\\\"א במסכת ע\\\"ז פרק ררב ישמעאל (דף נ\\\"ד) אוקמוה בשל חבירו בשעשה בה מעשה עכ\\\"ל. ולדעת רבינו י\\\"ל דהתם לאסרה להדיוט אבל לגבוה אף על פי שלא עשה בה מעשה נאסרה וכדתנן פרק כל האסורים גבי מוקצה ונעבד שאסורים למזבח זה וזה מותרים באכילה וכבר כתבתי שדברי רבינו הם דברי התוספתא: והנעבד הוא וכל מה שעליו אסורים למזבח וכו'. משנה בריש פרק כל האסורים שם איזהו מוקצה המוקצה לעבודה זרה הוא אסור ומה שעליו מותר ואי זהו הנעבד כל שעובדים אותו הוא ומה שעליו אסור זה וזה מותרים באכילה.\",1,0],[8,362,4,6,\"ומה שכתב שכל ציפוי נעבד אסור בהנאה מפורש שם מדכתיב לא תחמוד כסף וזהב עליהם וכו'.\",2,0],[8,362,4,6,\"ומה שכתב רבינו אסורים למזבח דמשמע אבל לא להדיוט אנעבד גופיה קאי דאילו מה שעליו אף להדיוט אסור בהנאה:\",3,0],[8,362,4,7,\"המשתחוה להר וכו'. בפרק כל הצלמים (עבודה זרה דף מ״ו) בעיא דאיפשיטא.\",1,0],[8,362,4,7,\"ומ\\\"ש המשתחוה למעיין הנובע בארצו הרי מימיו פסולין לנסך. שם (דף מ\\\"ז) בעיא דלא איפשיטא וספיקה לחומרא. כתב הר\\\"י קורקוס ז\\\"ל בשם התוספות שנובע בארצו ואינו מתפשט לחוץ שאם מתפשט לחוץ הא אמרינן במרובה מעיין היוצא בתחלה בני העיר מסתפקים אם כן מים של רבים הם ואינם נאסרים ולכך לא כתב רבינו מארצם במ\\\"ם כלשון הגמרא עכ\\\"ל.\",2,0],[8,362,4,7,\"ומה שכתב אשרה שבטלה אין מביאין ממנה גיזרין למערכה. שם בעי ר\\\"ל המשתחוה לדקל לולבו מהו למצוה כי אתא רב דימי אמר באשירה שביטלה קא מבעי' ליה ולא איפשיטא ולחומרא וכיון דלענין לולב למצוה מספיקא פסלינן לה מכ\\\"ש דפסלינן לה לגיזרין למערכה.\",3,0],[8,362,4,7,\"ומ\\\"ש וכן המשתחוה לבהמה כשם שנפסלה למזבח צמר שלה פסול לבגדי כהונה וקרניה פסולים לחצוצרות וכו' עד ובני מעיה לנימין. שם בעיי דלא איפשיטו ולחומרא. ודע דהתם בעי בהאי לישנא צמרה מהו לתכלת וקא מתמה תכלת דמאי אי דכהנים היינו דרמי בר חמא ופירש\\\"י תכלת דכהנים דבגדי כהונה לצורך עבודה וקא מיבעיא לן מכשירי קרבן כקרבן דמו או לא ואת\\\"ל כקרבן דמו היכא דנשתנה כשצובעין אותו יש שינוי בנעבד להתירו לגבוה או לא. היינו בעיא דרמי בר חמא דהיינו תרתי בעיי דבעא רמי בר חמא לעיל עכ\\\"ל. ובעיא דרמי בר חמא היא במשתחוה לקמה חטיה מהו למנחות יש שינוי בנעבד או לא ופשטינן דיש שינוי לנעבד ומותר וכן פסק רבינו בס\\\"פ שקודם זה וא\\\"כ ה\\\"ל למיפסק דלבגדי כהונה כשר מאחר דאישתני לכך נ\\\"ל שרבינו מפרש דלא דמיא למשתחוה לקמה דהתם שינוי גמור הוא דמעיקרא חיטי והשתא קמחא אבל הכא דמעיקרא צמר והשתא צמר אע\\\"ג דמעיקרא לבן והשתא תכלת לאו שינוי גמור היא ולא קאמר היינו דרמי בר חמא אלא משום בעיא דמשתחוה להר אבניו מה הן למזבח דאמרינן דמיבעי' ליה אי מכשירי קרבן כקרבן דמו או לא:\",4,0],[8,362,4,8,\"אי זהו אתנן האומר לזונה הא ליך דבר זה בשכריך. משנה בפרק כל האסורים (תמורה דף כ״ט).\",1,0],[8,362,4,8,\"ומה שכתב אחד זונה כותית וכו' או ישראלית. שם פלוגתא דאביי ורבא בזונה ישראלית ופסק כרבא.\",2,0],[8,362,4,8,\"ומ\\\"ש שפחה. מתבאר שם במשנה האומר לחבירו הא לך טלה ותלין שפחתך אצל עבדי וכמו שיבוא בפרק זה.\",3,0],[8,362,4,8,\"ומ\\\"ש שהיא ערוה עליו. שם.\",4,0],[8,362,4,8,\"ומ\\\"ש או מחייבי לאוין. שם כגון אלמנה לכהן גדול ואליבא דרבא מיתוקמא כרבנן דפליגי אר\\\"ע וסברי דקידושין תופסין בחייבי לאוין.\",5,0],[8,362,4,8,\"ומ\\\"ש אבל הפנויה אפי' היה כהן אתננה מותר. שם לאפוקי מרבי אלעזר דאמר פנוי הבא על הפנויה שלא לשם אישות עשאה זונה כלומר והרי היא אסורה לכהן.\",6,0],[8,362,4,8,\"ומ\\\"ש וכן אשתו נדה אתננה מותר אף על פי שהיא ערוה. שם פלוגתא דרב ולוי ופסק כרב ואיני יודע למה ואדרבה משמע בגמרא דלית הלכתא כוותיה דאמרינן ורב האי תועבה מאי עביד ליה מיבעי ליה לכדאביי דאמר זונה כותית אתננה אסור וכו' וכיון דלא קיימא לן כאביי אלא כרבא וכמו שפסק רבינו לעיל בסמוך היאך פסק כרב ואפשר שטעמו משום דרבי סבר הכי ואע\\\"ג דאמרי' דרב מיבעי ליה לכדאביי לאו דוקא דלדידן דלא קי\\\"ל כאביי נימא דלרב תועבה אתא לרבות הזכור:\",7,0],[8,362,4,9,\"נשא אחת מחייבי לאוין וכו'. נראה שטעם רבינו דמשמע ליה דכי אוקימנא אליבא דרבא כגון אלמנה לכ\\\"ג וכרבנן דתופסין בה קידושין אפילו בקידשה ונשאה מיתוקמא:\",1,0],[8,362,4,9,\"והזכור אתננו אסור. מימרא בפרק כל האסורים.\",2,0],[8,362,4,9,\"ומ\\\"ש נתנה האשה אתנן לבועל הרי זה מותר משום אתנן. שם: ודע דתניא תו התם אם נתן לה שכר הפקעתה מותר ופירש\\\"י שכר הפקעתה שכר מה שביטלה ממלאכתה ולא שכר ביאה ולא ידעתי למה השמיטו רבינו:\",3,0],[8,362,4,10,\"האומר לחבירו הא לך דבר זה וכו'. משנה שם האומר לחבירו הילך טלה זה ותלין שפחתך אצל עבדי רבי [מאיר] אומר אינו אתנן וחכמים אומרים אתנן ובגמרא (דף ל') שפחה לעבד מישרא שרי ואסיקנא בעבד עברי וטעמייהו דרבנן משום דהב\\\"ע כשאין לו אשה ובנים.\",1,0],[8,362,4,10,\"ומ\\\"ש וה\\\"ה באומר לזונה הא ליך דבר זה והבעלי לפלוני הישראלי הרי זה אתנן. ק\\\"ל דפשיטא ובמכ\\\"ש אתיא מעבד שאינו חייב בכל המצות כמו הישראלי וי\\\"ל דה\\\"א שאני התם שהוא עבדו קמ\\\"ל:\",2,0],[8,362,4,11,\"פסק עם הזונה ליתן לה טלה אחד ונתן לה הרבה וכו'. משנה וגמרא שם וקמ\\\"ל דלא תימא מתנה היא דיהיב לה אלא כולהו מכח אתנן אתו:\",1,0],[8,362,4,11,\"נתן לה אתננה ולא בא עליה וכו' (עיין בפנים). כך היא הגירסא הנכונה בדברי רבינו ודינים אלו בפרק כל האסורים (שם) נתן לה ואחר כך בא עליה אתננה מותר וליחול עלה אתנן למפרע א\\\"ר אלעזר שקדמה והקריבתו ה\\\"ד אי דאקנייה ניהלה לאלתר פשיטא דמותר וכו' ואלא דאמר לה לא נקני לך עד שעת ביאה מי מציא מקרבה ליה כי יקדיש את ביתו קדש לה' אמר רחמנא מה ביתו ברשותו אף כל ברשותו לא צריכא דאמר ליה לא ניקני ליך עד שעת ביאה ואי מצטריך ליך ניקני לך מעכשיו:\",2,0],[8,362,4,12,\"ומ\\\"ש קדמה והקדישתו וכו'. שם בעיא דלא איפשיטא:\",1,0],[8,362,4,13,\"בא עליה ולא נתן לה ולאחר זמן נתן לה וכו'. שם בא עליה ואחר כך נתן לה אתננה מותר והא תניא בא עליה ונתן לה אפילו עד י\\\"ב חדש אתננה אסור וכו' ל\\\"ק הא דא\\\"ל הבעלי לי בטלה זה הא דא\\\"ל הבעלי לי בטלה סתם טלה זה והא מחוסר משיכה בזונה כותית דלא קניא במשיכה ואיבעית אימא אפי' בזונה ישראלית כגון דקאי בחצירה הא יהיב לה מעיקרא דשויא לה אפותיקי ואומר לה אם עד יום פלוני יהיבנא לך זוזי מוטב ואם לא טלה באתננך ופירש\\\"י בטלה זה הואיל דיהביה בשעת ביאה חייל עליה אתנן מיד. טלה סתם דמשדר לה בתר הכי מתנה בעלמא הוא ואין אתנן אלא המיוחד בשעת ביאה. הא יהביה ניהלה מעיקרא דהואיל וקאי בחצירה קניא ליה בשעת ביאה מיד ואמאי קרי ליה ואחר כך נתן ועוד פשיטא וכו'. עד יום פלוני משקלין לך כך וכך ואי לא שקלי ליה הילכך מטי ולא יהיב לה זוזי איגלאי מילתא דאדידיה הואי ביאה ומיהו אח\\\"כ הוא דהא לא הוי דידה עד דמטי יום פלוני ואיצטריך לאשמועינן דאסור עכ\\\"ל. ולשון רבינו שכתב שאינה צריכה משיכה אינו מכוון עם לשון הגמרא שאמרה בזונה כותית דלא קניא במשיכה וטעם רבינו מפני שהוא סבור יד עכו\\\"ם קונה בין בכסף בין במשיכה כמבואר בדבריו בפ\\\"א מה' זכיה ולפי זה ע\\\"כ לפרש בהאי דלא קניא במשיכה פירושו דלא צריכה משיכה דבכסף בלחוד קניא והביאה היא במקום כסף והילכך זונה ישראלית שאינה קונה בכסף בלא משיכה אינו אתנן אבל זונה כותית שאין צריך משיכה לקניינה הוי אתנן:\",1,0],[8,362,4,14,\"אין אסור משום אתנן ומחיר וכו' נתן לה מעות ולקחה בהם קרבן הרי זה כשר. משנה שם (דף ל').\",1,0],[8,362,4,15,\"נתן לה חטים ועשאתן סולת וכו'. שם ב\\\"ש אוסרים וב\\\"ה מתירים:\",1,0],[8,362,4,15,\"נתן לה בהמת קדשים באתננה לא נאסרה למזבח. משנה שם.\",2,0],[8,362,4,15,\"ומ\\\"ש ואפילו מנה אותה על פסחו וחגיגתו באתננה לא נפסלו המוקדשין וכו'. שם אהא דממעט מוקדשין מדכתיב לכל נדר להוציא את הנדור ומקשה טעמא דמעטינהו קרא הא לא מעטינהו קרא ה\\\"א כי יהיב לה מוקדשין חל עליהם אתנן ומחיר והא לאו ממוניה הוא אמר רב הושעיא בממנה על פסחו ורבי היא וכו' [דאמר] אם אין לו ממנה אחרים עמו על פסחו ועל חגיגתו ומעותיו חולין ופסק רבינו בהלכות קרבן פסח פ\\\"ד הלכה כרבי.\",3,0],[8,362,4,15,\"ומ\\\"ש רבינו שכבר זכה בהם גבוה משעה שהקדישן. היינו לומר דאע\\\"ג דהממנה אחרים עמו על פסחו המעות חולין וא\\\"כ כשמנה את זו על פסחו באתננה היה ראוי ליפסל לא נפסל מפני שמשעה שהקדישו זכה בו גבוה ואימעיט מדין אתנן מלכל נדר להוציא את הנדור:\",4,0],[8,362,4,15,\"וכן אם נתן לה דבר שאינו שלו לא פסלו וכו'. נלמד ממה שכתבתי בסמוך שאמרו והא לאו ממוניה הוא:\",5,0],[8,362,4,15,\"אבל אם נתן לה עופות וכו'. שם תנן נתן לה מוקדשים הרי אלו מותרים עופות הרי אלו אסורים שהיה בדין מה אם המוקדשין שהמום פוסל בהם אין אתנן ומחיר חל עליהם עופות שאין המום פוסל בהם אינו דין שלא יהא אתנן ומחיר חל עליהם תלמוד לומר לכל נדר להביא את העוף.\",6,0],[8,362,4,15,\"ועל מה שכתב אפילו הם מוקדשים כתב הראב\\\"ד לא כן אנו מקובלים וכו'. ואני תמה על הראב\\\"ד היכי שבקיה לרגזנותיה שלא כתב בדרך השגה והיא קושיא חזקה שא\\\"א לומר שנתרבו עופות לאיסור אתנן אפילו הם מוקדשין וכשנתמעטו מוקדשין מאיסור אתנן חוץ ממוקדשי עוף הוא שנתמעטו דהא עופות לא בהדיא נתרבו כי היכי דתימא דנתרבו אפילו הם מוקדשין דלא איתרבו אלא מלכל נדר וא\\\"כ כי ממעטינן נדור עופות נדור נמי ממעטינן ועוד דמוקדשין א\\\"א בשום פנים לחול עליהם איסור אתנן דהא לאו ממוניה הוא כדמקשה גמרא. ובעל מגדל עוז תירץ דמאי אע\\\"פ שהם מוקדשין דקאמר הרמב\\\"ם שהם ראויים להיות מוקדשין כלומר תורים ובני יונה וכל שכן אווזים ותרנגולים שאינם ראויים להיות מוקדשין שאתנן חל עליהם ואסורים עכ\\\"ל ופירוש דחוק הוא ביותר. ואפשר לומר דמאי אע\\\"פ שהם מוקדשים דקאמר רבינו אע\\\"פ שהקצה להקריבן אבל עדיין לא הקדישן בפה.\",7,0],[8,362,4,15,\"ומ\\\"ש רבינו ומדברי קבלה הוא דבר זה:\",8,0],[8,362,4,16,\"אי זהו מחיר כלב וכו'. משנה שם (דף ל') ופשוט הוא.\",1,0],[8,362,4,16,\"ומ\\\"ש וכן אם החליף כלב בכמה בהמות או עופות וכו'. פשוט הוא:\",2,0],[8,362,4,17,\"שני שותפים שחלקו וכו'. משנה שם שני שותפין אחד נטל עשרה ואחד [נטל] ט' וכלב שכנגד הכלב אסור ושעם הכלב מותר ובגמרא ניפוק חדא להדי כלבא והנך כולהו לישתרו הב\\\"ע כגון דטפי דמי כלב מחד מינייהו והאי טופיינא דכלב שדי בכולהו:\",1,0],[8,362,4,18,\"נשתנה המחיר וכו'. ברייתא שם גבי אתנן וב\\\"ה מתירים משום דכתיב שניהם הם ולא שינוייהם ועוד דרשו שם הם ולא ולדותיהם ולא ידעתי למה השמיטו רבינו:\",1,0],[8,362,4,18,\"אתנן כלב ומחיר זונה מותרים. משנה שם.\",2,0],[8,362,4,18,\"ומ\\\"ש אתנן זונה ומחיר כלב מותרים לבדק הבית שהרי הם משתנים. זה פשוט שאפי' למזבח שינוייהם מותרים.\",3,0],[8,362,4,18,\"ומ\\\"ש אבל גופן לא יעשה ריקועים לבית וכו'. שם תנו רבנן בית ה' אלהיך פרט לפרה שאין באה לבית דברי ר' אלעזר וחכמים אומרים לרבות את הריקועים ופסק כחכמים ואע\\\"ג דאמר רב חסדא מאן חכמים רבי יוסי ברבי יהודה מכל מקום כיון דתנא דברייתא שנאו בלשון חכמים הכי נקטינן ועוד דבפרק שני דמסכת פרה (משנה ג') שנינו אתנן ומחיר פסולה ר' אלעזר מכשיר הרי ששנה דברי החולק על רבי אלעזר בסתם אלמא לית הלכתא כרבי אלעזר:\",4,0],[8,362,5,1,\"שאור ודבש אסורים לגבי מזבח וכו'. בת״כ כי כל שאור וכל דבש לא תקטירו אין לי אלא מרובה מניין אפילו מועט ת״ל כל. ודע דבפרק כל המנחות (מנחות דף נ״ח) ת״ר שאור בל תקטירו אין לי אלא כולו מקצתו מנין ת״ל כי כל מאי קאמר אמר אביי ה״ק שאור בל תקטירו אין לי אלא כזית חצי כזית מנין ת״ל כל [עירובו מנין ת״ל כי כל] רבא אמר ה״ק שאור בל תקטירו אין לי אלא קומץ חצי קומץ מנין ת״ל כל וכו' במאי קא מיפלגי אביי סבר יש קומץ פחות משני זיתים [ויש הקטרה פחותה מכזית ורבא אמר אין קומץ פחותה מב' זיתים] ואין הקטרה פחותה מכזית ומשמע דרבא דפליג אאביי ודריש דרשא דכל לחצי קומץ סבר דלא מיחייב על שאור ודבש בפחות מכזית כשאר איסורין דהא לית ליה קרא לחיובי בכחצי זית וא״כ יש לתמוה למה פסק רבינו כאביי ודלא כרבא. ועוד שכתב לקמן בסמוך ואין הקטרה פחותה מכזית והיינו כרבא וזה סותר מ״ש כאן. ואפשר שרבינו מפרש דרבא לא פליג אאביי דדריש מכל לרבויי חצי זית דשאור ודבש אלא שמוסיף לדרוש נמי לחצי קומץ דתרוייהו משתמע.\",1,0],[8,362,5,1,\"ומ\\\"ש ואין הקטרה פחותה מכזית היינו בתערובות וצריך שיהא כזית אע\\\"פ שאין בו אלא כל שהוא משאור ודבש לוקה.\",2,0],[8,362,5,1,\"ומ\\\"ש ואינו חייב אלא אם הקטירן עם הקרבן או לשם קרבן יתבאר בסמוך.\",3,0],[8,362,5,1,\"ומ\\\"ש ואחד המקטיר עצמן או המקטיר תערובות שלהם לוקה. ברייתא בפרק כל המנחות.\",4,0],[8,362,5,1,\"ומ״ש לוקה על כל אחד מהם בפני עצמו ואם הקטיר שניהם כאחד אינו לוקה אלא אחת. בפרק כל המנחות (מנחות דף נ״ח:) פלוגתא דאביי ורבא והלכה כרבא דאמר לאו שבכללות אין לוקין עליו ודברי רבינו כאן הם ע״פ דרכו בסה״מ שלו בשורש הט' בפירוש לאו שבכללות אין לוקין עליו והרמב״ן בהשגותיו חולק עליו ומפרש בע״א. והראב״ד כתב א״א בספרים שלנו רבא מחייב שתים וארבע וכו' ואני אומר שגם גירסת ספרינו כגירסת הראב״ד אבל גירסת רבינו יותר נכונה משום דסוגיין דגמרא דאין לוקין על לאו שבכללות ואם כגירסת הראב״ד היה לנו לומר דלוקין כרבא שאין זו מיע״ל קג״ם דהלכה בהו כאביי:\",5,0],[8,362,5,2,\"נפל מהם כל שהוא בקטרת נפסלה. בברייתא דפיטום הקטרת פ\\\"ק דכריתות (דף ו') תניא אם נתן בה דבש פסלה ומשמע דהיינו מדכתיב לא תקטירו וא\\\"כ אין חילוק בין שאור לדבש ולא נקט תנא דבש אלא משום דמעלי לקטורת וכדקתני התם אם היה נותן קורטוב דבש אין אדם יכול לעמוד מפני ריחה ומפני מה אין נותנין בה דבש משום שנאמר כל שאור וכל דבש לא תקטירו.\",1,0],[8,362,5,2,\"ומ\\\"ש ואם הקטיר ממנה בהיכל לוקה. נראה שהטעם מפני שעבר בבל תקטירו.\",2,0],[8,362,5,2,\"ומ\\\"ש בהיכל מפני שהקטרת הקטורת בכל יום במזבח הזהב שהיה בהיכל ואינו עובר משום מקטיר דבש בקטורת אלא כשמקטיר במקום המיוחד לו אבל הקטיר חוץ מההיכל אינו עובר משום מקטיר דבש.\",3,0],[8,362,5,2,\"ומ\\\"ש ואין הקטרה פחותה מכזית. כרבא דאמר הכי כמ\\\"ש בראש פרק זה:\",4,0],[8,362,5,4,\"העלה שאור או דבש בפני עצמן למזבח לשם עצים פטור וכו'. בפרק התערובות (דף ע\\\"ו) אהא דתניא התם למחרת מביא אשמו ולוגו ואומר אם של מצורע ה\\\"ז אשמו וזה לוגו וכו' ומקשה והא בעי הקטרה ומשני דאקטיר ליה ומקשה אימתי אי בתר מתנות שבע הוה ליה שירים שחסרו וכו' אי קודם מתנות שבע כל שממנו לאישים הרי הוא בבל תקטירו אמר רב יהודה בריה דר\\\"ש בן פזי דמסיק להו לשם עצים דתניא רבי אליעזר אומר לריח ניחוח אי אתה מעלה אבל אתה מעלה לשום עצים ופרש\\\"י בל תקטירו דכתיב כי כל שאור וכל דבש לא תקטירו ממנו אשה לה' והאי ממנו יתירא הוא ודרשינן ביה נמי לא תקטירו כל שממנו אשה לה' בכלל הזה קדשים ושירי מנחה ולחם הפנים שקרב מהם כבר לאישים האמורים [וכן הקומץ] וכן הבזיכים קיימי שירים בבל תקטירו וכו'. לריח ניחוח אי אתה מעלה בתר ההוא קרא דכל שממנו לאישי' כתיב קרבן ראשית תקריבו אותם ואל המזבח לא יעלו לריח ניחוח קרבן ראשית אשאור ודבש הכתוב בראש המקרא העליון קאי וקאמר יש לך להביא מהם בכורים מהדבש ושתי הלחם מהשאור ואל המזבח לא יעלו אכוליה קרא קאי ואדרשא דבל תקטירו דשירים עכ\\\"ל.\",1,0],[8,362,5,4,\"ומ״ש אפי' הקטיר דבר שאינו ראוי להקטרה בדבש או בשאור הואיל והוא מן הקרבן לוקה כיצד המעלה מבשר חטאת ואשם וכו'. בפרק כל המנחות (מנחות דף נ״ז:) ת״ר מנין למעלה מבשר חטאת ומבשר אשם ומבשר קדשי קדשים ומקדשים קלים וממותר העומר וממותר שתי הלחם ומלחם הפנים ומשירי מנחות שהוא בלא תעשה ת״ל כי כל שאור וכל דבש לא תקטירו ממנו אשה ליי' כל שממנו לאישים הרי הוא בבל תקטירו עכ״ל:\",2,0],[8,362,5,4,\"וכתב הראב\\\"ד על דברי רבינו בחיי ראשי נשתבש בלשון הברייתא וכו'. ויש לתמוה על הראב\\\"ד היאך משוי לרבינו טועה לומר שהוא סבור שאינו חייב על שאור ודבש אא\\\"כ יש עמהם צד קרבן וח\\\"ו מלטעות רבינו בזה והרי דבריו מבוארים בראש הפרק שכתב ואינו חייב אלא אם הקטירן עם הקרבן או לשם קרבן ומדכתב תיבת או המבדלת משמע בהדיא דבהקריבן בפני עצמן לשם קרבן חייב לאפוקי שאם העלה אותם בפני עצמן לשם עצים פטור כמו שנתבאר בסמוך ואם העלם עם הקרבן חייב בכל גווני אפי' העלה השאור והדבש לשם עצים וזה מבואר בדבריו שכתבתי בסמוך אם הקטירן עם הקרבן או לשם קרבן דהיינו לומר אם הקטירן עם הקרבן אפילו הקטירן לשם עצים כיון דאיכא קרבן בהדייהו חייב או אם הקטירן לשם קרבן אפילו הקטירן לבדם חייב והשתא קאמר דכשהקטירם לשם עצים דאמרן שאם הקטירן עם הקרבן חייב לא מיבעיא אם הקטירן עם חלק מהקרבן הראוי להקטרה אלא אפי' הקטירם עם חלק מהקרבן שאינו ראוי להקטרה כגון בשר חטאת ובשר אשם וכו' חייב כיון שהם קרויים קרבן אבל אי קשיא בדברי רבינו הא קשיא כיון דהאי דרשא דכל שהוא ממנו לאישים הרי הוא בבל תקטירו מידריש בלא הקטירם עם שאור ודבש כדאיתא בפרק התערובות שכתבתי בסמוך וכתבו רבינו לקמן בסמוך א\\\"כ מנא ליה למדרשיה להקטירם עם שאור ודבש ואע\\\"ג דאיכא למימר דמשמע לרבינו דברייתא דמנין למעלה מבשר חטאת ומבשר אשם וכו' במקטירם עם שאור ודבש היא מדקבעה הגמרא בר\\\"פ כל המנחות באות מצה דעסיק בדיני הקרבת שאור אימתי חייב אכתי איכא למיבעי מנא ליה לגמרא למימר הכי וי\\\"ל דמשמע ליה לגמרא דאי דרשא דכל שהוא ממנו לאישים הרי הוא בבל תקטירו לא אתיא אלא להקטירם בלא שאור ודבש בלבד היא לא הו\\\"ל למכתביה גבי שאור ודבש ומדכתביה גבייהו משמע דאף במקטירם עם שאור ודבש היא וא\\\"ת אכתי אימא דלא אתא אלא להקטירם עם שאור ודבש ולא להקטירם בלא שאור ודבש וא\\\"כ ההיא דפ' התערובות מנ\\\"ל וי\\\"ל דא\\\"כ לכתוב קרא לא תקטירו אשה ממנו ומדכתב ממנו אשה משמע למדרש כל שממנו לאישים הרי הוא בבל תקטירו אפי' אין עמו שאור ודבש. ועדיין יש לדקדק דא\\\"כ כשהקטיר שאור ודבש אפי' לשם עצים עם חלק מהקרבן שאינו ראוי להקטרה ילקה שתים משום שאור ודבש ומשום כל שממנו לאישים וכההיא דפרק התערובות ומדברי רבינו לא משמע דלקי אלא אחת ואין לומר דטעמא דמשום דהוי לאו שבכללות שאינו לוקה על שניהם אלא אחת לדעתו ז\\\"ל שהרי כתב בסמוך וכן אסור להקטיר על המזבח מכל דברים אלו שאינם ראויים להקטרה ולא כתב שלוקה ואפשר לומר שסובר רבינו שעיקר הלאו למקטיר שאור ודבש עם חלק מהקרבן שאינו ראוי להקטרה ולקי עליה ומדלא כתב אשה ממנו דרשינן דהוא הדין להקטיר דבר שממנו לאישים בלא שאור ודבש לדרשא בעלמא אבל לא ללקות עליו כיון דעיקר קרא לאו להכי אתא.\",3,0],[8,362,5,4,\"ומ\\\"ש רבינו חטאת העוף וכו' ולוג שמן של מצורע. בפרק כל המנחות (דף כ\\\"ח) בעי רמי בר חמא מרב חסדא המעלה מבשר חטאת העוף על המזבח מהו כל שממנו לאישים אמר רחמנא והאי אין ממנו לאישים או דילמא כל ששמו קרבן והאי נמי שמו קרבן א\\\"ל כל ששמו קרבן והאי נמי שמו קרבן וכו' כתנאי ר\\\"א אומר כל שממנו לאישים רב עקיבא אומר כל ששמו קרבן מאי בינייהו אמר רב חסדא בשר חטאת העוף איכא בינייהו רב אמר לוג שמן של מצורע איכא בינייהו ופירש\\\"י כל ששמו קרבן אמר רחמנא דלא יקטירו משיריו דהכי כתיב בתר דההוא קרא קרבן ראשית ומקרא נדרש לפניו. עוף שמו קרבן דכתיב ואם מן העוף עולה קרבנו. לוג שמן של מצורע אין ממנו לאישים אבל קרבן איקרי כדאמרינן באלו מנחות לכל קרבנם לרבות לוג שמן של מצורע ובגופיה נמי כתיב והקריב אותו ואת לוג השמן עכ\\\"ל ופסק רבינו כר\\\"ע.\",4,0],[8,362,5,4,\"ומ\\\"ש רבינו המעלה כזית מאחת מאלו בחמץ או בדבש בין למזבח בין לכבש לוקה. שם אברייתא שכתבתי לעיל מנין למעלה מבשר חטאת מבשר אשם וכו' איתמר המעלה מכולם על הכבש רבי יוחנן אמר חייב דתניא מזבח אין לי אלא מזבח כבש מנין ת\\\"ל ואל המזבח לא יעלו לרצון ורבי אלעזר אמר פטור מ\\\"ט דאמר קרא שאור ודבש קרבן ראשית תקריבו אותם אותם הוא דרבי לך כבש כמזבח אבל מידי אחרינא לא ופסק רבינו כרבי אלעזר דגבי המעלה מבשר חטאת ואשם וכו' בחמץ או בדבש כתב בין למזבח בין לכבש לוקה וגבי אסור להקטיר על המזבח דבר מכל דברים אלו השמיט כבש ויש לתמוה למה פסק כר\\\"א במקום רבי יוחנן וכתב הר\\\"י קורקוס ז\\\"ל דטעמא משום דסוגיא דבפרק התערובות (דף ע\\\"ז) כוותיה (וע\\\"ש תוס' ד\\\"ה מרבנן וכו' הך סוגיא כרבי אלעזר וכו'):\",5,0],[8,362,5,6,\"המקטיר איברי בהמה טמאה ע״ג המזבח לוקה וכו'. בפרק כל הפסולין (זבחים דף ל״ד) איתמר המעלה איברי בהמה טמאה ע״ג המזבח ר״ל אומר לוקה וכו' טהורה אין טמאה לא ולאו הבא מכלל עשה לוקין עליו ור' יוחנן אמר אין לוקין עליו לאו הבא מכלל עשה אין לוקין עליו מתיב רבי ירמיה אותם תאכלו ולא בהמה טמאה ולאו הבא מכלל עשה עשה א״ל רבי יעקב לרבי ירמיה [בר תחליפא] אסברא לך באיברי בהמה טמאה דכ״ע לא פליגי כי פליגי בחיה והכי איתמר רבי יוחנן אמר עובר בעשה וכו' בהמה אין חיה לא ר״ל אמר אינו עובר עליו בלא כלום ההוא למצוה ואיתותב ר״ל ופירש״י ולאו הבא מכלל עשה עשה כך שנויה בתוך הברייתא ומסקינן בלא תעשה מנין ת״ל אך את זה לא תאכלו אלמא מדאיצטריך לא תעשה אחרינא לאו אזהרה הוא. דכ״ע לא פליגי דעשה הוא דאיכא ותו לא עכ״ל ולפי זה ליכא הכא אלא עשה וזהו שכתב הראב״ד כך לוקה על הקרבתה א״א וכי עדיפא מבעלת מום וכו' ביאור דבריו שכך ראוי ללקות על הקרבתה כיון שלוקה על בעלת מום מכ״ש שראוי ללקות על זו אבל מה נעשה שבגמרא אינו עולה כן. וליישב דברי רבינו יש לדקדק שכתב כשם שלוקה על אכילת הטמאה הבא מכלל עשה כמו שביארנו במקומו כך לוקה על הקרבתה ובפ״ב ממאכלות אסורות כתב מכלל שנאמר וכל בהמה מפרסת פרסה וכו' שומע אני שכל שאינה מעלת גרה וכו' אסורה ולאו הבא מכלל עשה עשה הוא ובגמל ובחזיר ובארנבת ובשפן נאמר את זה לא תאכלו ממעלי הגרה וממפריסי הפרסה וכו' הא למדת שהן בלא תעשה ואע״פ שיש בהם סימן אחד וכ״ש שאר בהמה וחיה טמאה שאין בה סימן כלל שאיסור אכילתה בלא תעשה יתר על עשה הבא מכלל אותה תאכלו עכ״ל וא״כ יש לתמוה מה מביא מאכילת בהמה טמאה שנאמר בה לא תעשה להקרבתה שלא נאמר בה לא תעשה וא״ת דכיון דאין מזהירין מן הדין האי לאו כליתיה דמי כבר כתב הרב המגיד שכיון שנאסרו בלאו הבא מכלל עשה אפשר ללאו שלהם לבא מק״ו ולא מיקרי מזהיר מן הדין וא״כ אין ראיה מאכילתה להקרבתה כלל וי״ל דכיון דבהמה טמאה גריעא מבעל מום כשהזהירה תורה על הקרבתו בלאו יש לנו להביא בהמה טמאה לאסור הקרבתה בלאו מק״ו ויש לחזק דין זה יותר דכיון דאשכחן דאפיק רחמנא בעל מום בלשון בהמה טמאה כדאמרינן בר״פ כל המנחות (דף ק״א) ובסוף תמורה (דף ל״ב) ואם כל בהמה טמאה אשר לא יקריבו ממנו קרבן לה' בבעלי מומין שיפדו הכתוב מדבר כי אסר רחמנא להקריב בעל מום בלאו בהמה טמאה בכלל ומעתה ההיא דפרק כל הפסולים לא הויא תיובתא דכי אמרינן ת״ל את זה לא תאכלו גמל וארנבת שפן וחזיר וילפינן מינייהו בק״ו לשאר בהמה טמאה לאסור אכילתה בלאו הכי נמי כיון שאסר בעל מום למזבח בלאו ילפינן בהמה טמאה למזבח בלאו מק״ו או משום דבכלל בעל מום היא וא״כ כי אמרינן באיברי בהמה טמאה כ״ע לא פליגי לא כדפירש״י אלא היינו לומר דכ״ע לא פליגי דלוקה משום דאזהר עליה בלאו כדאמרן:\",1,0],[8,362,5,7,\"הגונב או הגוזל והקריב הקרבן פסול. בפרק מרובה (בבא קמא דף ס״ו:) קרבנו ולא הגזול.\",1,0],[8,362,5,7,\"ומ״ש ואם נתייאשו הבעלים הקרבן כשר אפילו היתה חטאת וכו' ומפני תקנת מזבח אמרו שהחטאת הגזולה אם נודעה לרבים אינה מכפרת וכו' וכן העולה. בפרק הניזקין (גיטין דף נ״ה) תנן העיד רבי יוחנן בן גודגדא וכו' על חטאת הגזולה שלא נודעה לרבים שהיא מכפרת מפני תיקון המזבח ובגמרא אמר עולא דבר תורה בין נודעה בין לא נודעה אינה מכפרת מ״ט יאוש כדי לא קני ומה טעם אמרו לא נודעה מכפרת שלא יהיו כהנים עצבים וכו' והא אנן מפני תיקון המזבח תנן וכו' כיון דכהנים עצבים נמצא מזבח בטל ורב יהודה אמר דבר תורה בין נודעה בין לא נודעה מכפרת מ״ט יאוש כדי קני ומה טעם אמרו נודעה אינה מכפרת שלא יאמרו מזבח אוכל גזילות בשלמא לעולא היינו דקתני חטאת אלא לרב יהודה מאי איריא חטאת אפי' עולה נמי לא מיבעיא קאמר לא מיבעיא עולה דכליל היא אלא אפילו חטאת נמי דחלב ודם הוא דסליק לגבי מזבח ואידך כהנים אכלי ליה אפ״ה גזור שלא יאמרו מזבח אוכל גזילות ופירש״י בין נודעה מכפר אם נתייאשו הבעלים וכו'. דכליל היא ואמרי מזבח אוכל גזילות. ופסק רבינו כרב יהודה ויש לתמוה שמאחר שרבינו פוסק דיאוש כדי לא קני כמבואר פ״ה מהלכות גניבה היאך פסק כרב יהודה דאמר יאוש כדי קני שזה סותר מה שפסק בהלכות גניבה ועוד דמתניתין לא מייתבא שפיר לרב יהודה דאמרינן בגמרא תנן החטאת הגזולה שלא נודעה לרבים שהיא מכפרת מפני תיקון המזבח בשלמא לעולא ניחא אלא לרב יהודה איפכא מיבעי ליה ה״נ קאמר לא נודעה מכפרת נודעה אינה מכפרת מפני תיקון המזבח והשתא כיון דמתני' כפשטא אתיא כעולא ה״ל למיפסק כוותיה וי״ל דאע״ג דבעלמא יאוש כדי לא קני הכא קני משום דאמרינן בגמרא מתיב רבא גנב והקדיש ואח״כ טבח ומכר משלם תשלומי כפל ואינו משלם תשלומי ד' וה' ותני עלה בחוץ כה״ג ענוש כרת ואי אמרת יאוש כדי לא קני מאי עבידתיה ואסיקנא אוקמוה רבנן ברשותיה כי היכי דליחייב עלה ומשמע דהכי הלכתא מדחזינן דבתר הכי שקיל וטרי רבא אליבא דהאי אוקימתא. ואמרינן בירושלמי (הלכה ו') דרבים היינו שלשה ולא ידעתי למה השמיטו רבינו:\",2,0],[8,362,5,7,\"כתב הראב\\\"ד ואפילו היה חטאת א\\\"א אין כאן אפי' עכ\\\"ל. טעמא משום דמשמע ליה דקאי למאי דסמיך ליה שאם נתייאשו הבעלים הקרבן כשר ויותר היה ראוי להכשיר חטאת שאין ממנה למזבח אלא חלב ודם מעולה שכולה למזבח וכדאמרינן בגמרא וכתבו רבינו בסמוך וא\\\"כ לא יתכן להביא חטאת באפילו ול\\\"נ לפרש דארישא קאי שכתב הקרבן פסול וקאמר דאפילו חטאת שהכהנים אוכלים את בשרה אפי' הכי פסול ואינו מתקבל:\",3,0],[8,362,5,8,\"הגונב עולת חבירו והקריבה סתם וכו'. ירושלמי פ״ב דשקלים (הלכה א') ובפרק מרובה (בבא קמא דף ע״ו) גבי מתני' דר״ש אומר גונב קדשים שחייב באחריותן חייב בשוחט תמימים לשם בעלים פריך והרי חזרה קרן לבעלים פי' שהבעלים נתכפרו בו.\",1,0],[8,362,5,8,\"ומ\\\"ש שם לשם בעלים לאו דוקא דסתמא נמי כשר כדאיתא בריש זבחים לאפוקי שלא לשמו נקט הכי:\",2,0],[8,362,5,9,\"אין מביאין מנחות ונסכים לא מן הטבל וכו' עד ואין צריך לומר מערלה וכלאי הכרם. בתוספתא דמנחות ספ״ח וגם בתוספתא דמעילה ספ״ק ובפרק אלו עוברין (פסחים דף מ״ח) ממשקה ישראל מן המותר לישראל מכאן אמרו אין מביאין נסכים מן הטבל.\",1,0],[8,362,5,9,\"ומ\\\"ש ולא מן החדש קודם לעומר. איתיה נמי במשנה במנחות פרק רבי ישמעאל.\",2,0],[8,362,5,9,\"ומ\\\"ש ולא מן החדש וכו'. לא אמנחות בלבד קאי אלא אף אנסכים כדאיתא בפרק כל קרבנות ציבור.\",3,0],[8,362,5,9,\"ומ\\\"ש ואם הביא לא נתקדשו וכו'. במשנה פ' רבי ישמעאל דמנחות (ס\\\"ח:) אין מביאים מנחת בכורים ומנחת בהמה קודם לעומר ואם הביא פסול ומשמע לרבינו דהיינו לומר דהוו קדשים שנפסלו ומשמע ליה דהוא הדין לכל אינך:\",4,0],[8,362,5,10,\"כל המנחות אין מביאים אותם מן החדש וכו'. משנה במנחות פרק רבי ישמעאל:\",1,0],[8,362,5,10,\"ומביאים נסכים מן המוקצה ביום טוב. בפרק אלו עוברין עלה מ\\\"ח ממשקה ישראל מן המותר לישראל מכאן אמרו אין מביאין נסכים מן הטבל יכול לא יביא מן המוקצה אמרת מה טבל מיוחד שאיסור גופו גרם לו אף כל שאיסור גופו גרם לו יצא מוקצה שאין איסור גופו גרם לו אלא איסור דבר אחר גרם לו:\",2,0],[8,362,5,11,\"מצות עשה למלוח כל הקרבנות וכו'. ואין לך דבר שקרב למזבח בלא מלח חוץ מיין הנסכים והדם והעצים. בפרק הקומץ רבה (מנחות דף כ) וכרבי ישמעאל בנו של ר״י בן ברוקא.\",1,0],[8,362,5,11,\"ומ\\\"ש ודבר זה קבלה ואין לו מקרא לסמוך עליו. איני יודע למה כתב כן שהרי מפורש שם שנתן רבי ישמעאל בנו של רבי יוחנן בן ברוקא טעם לדבריו מה הפרט מפורש דבר שמקבל טומאה ועולה לאישים וישנו על מזבח החיצון וכו' יצאו עצים שאין מקבלין טומאה יצאו דם ויין שאין עולה לאישים יצא קטרת שאינה על מזבח החיצון. ונראה דמשמע לרבינו דהאי דרשא דכלל ופרט וכלל לאו דרשא גמורה היא למעט עצים שנקראו קרבן בהדיא כמו שכתוב והגורלות הפלנו על קרבן העצים ואילולי הקבלה לא היינו ממעטין אותם:\",2,0],[8,362,5,11,\"ומצוה למלוח הבשר וכו'. בפרק הקומץ רבה (מנחות דף כ״א) כיצד הוא עושה מביא האבר ונותן עליו מלח וחוזר והופכו ונותן עליו מלח ומעלהו.\",3,0],[8,362,5,11,\"ומ\\\"ש כמולח בשר לצלי יש לתמוה דאמרי' התם בתר הכי בסמוך אמר אביי וכן לקדרה ונראה שרבינו היה גורס וכן לצלי וכן גורס הר\\\"ן וכתב ספר מצות גדול שכן גורס ריב\\\"א.\",4,0],[8,362,5,11,\"ומ\\\"ש ואם מלח כל שהוא אפי' בגרגיר אחד מלח כשר. שם תקריב כל שהוא ומפרש רבינו דהיינו שאם מלח כל שהוא כשר ודלא כדפירש\\\"י ובת\\\"כ ובתוספתא דמנחות ספ\\\"ט משמע כפי' רבינו:\",5,0],[8,362,5,12,\"הקריב בלא מלח לוקה וכו': ומ\\\"ש ואף ע\\\"פ שלוקה הקרבן כשר והורצה חוץ מן המנחה וכו'. כן משמע מפשט הכתוב על כל קרבנך תקריב מלח למצוה ולא לעכב אבל במנחה שכתוב ולא תשבית משמע ודאי לעכב ובפרק הקומץ רבה עלה י\\\"ט אמר רב כל מקום שהחזיר הכתוב בתורת המנחה אינו אלא לעכב וכן אמר שמואל אבל ק\\\"ל דאמרינן שם בגמרא עלה הרי מלח דלא תנא ביה קרא ומעכבא ביה דתניא ברית מלח עולם היא שתהא ברית אמורה במלח דברי רבי יהודה רש\\\"א נאמר כאן ברית מלח עולם היא ונאמר להלן ברית כהונת עולם כשם שא\\\"א לקרבנות בלא כהונה כך אי אפשר לקרבנות בלא מלח אמר רב יוסף רב כתנא דידן ס\\\"ל דאמר בלא מלח כשר א\\\"ל אביי א\\\"ה לא יצק נמי לא יצק כלל אלא לא יצק כהן אלא זר ה\\\"נ לא מלח כהן אלא זר אמר ליה וכי תעלה על דעתך שזר קרב לגבי מזבח ואיבעית אימא כיון דכתיבא ביה ברית כמאן דתנא ביה קרא דמיא ומשמע מהכא דבכל קרבנות מעכב מלח ונ\\\"ל שרבינו גורס כמו שכתבו התוספות שגורס רבינו תם מלח ברית והוא קרא דכתיב בפרשת ויקרא לא תשבית מלח ברית אלהיך מעל מנחתך אבל ברית מלח עולם היא לא כתיב גבי קרבנות אלא גבי מתנות כהונה עכ\\\"ל דהשתא לא אמרינן דמעכב אלא במנחה ואע\\\"ג דמדברי ר\\\"ש משמע דבכל קרבנות מיירי איכא למימר דכיון דלר' יהודה לא מיירי אלא במנחות נקטינן כוותיה דר\\\"י ורבי שמעון הלכה כר' יהודה שסובר רבינו דבהא פליגי ולאפוקי מדפירש\\\"י דלא פליגי אלא במשמעות דורשין ואם תאמר והא מתניתין דלא מלח כשר גבי מנחה כתיב והיאך פסק רבינו דלא כסתם מתניתין וכיון דאפשר לומר דתנא דידן ס\\\"ל דלא תנא קרא דמליחה הכי ה\\\"ל למיפסק וי\\\"ל דמתניתין דלא כר\\\"י ודלא כרבי שמעון מאחר דאפשר לאוקמא דרב ס\\\"ל כוותייהו הכי נקטינן ועי\\\"ל דשינויא דשני בו איבעית אימא מסתברא דלישנא דברייתא כמאן דתנא ביה הוא מילתא דמסתבר הוא ונקטינן כוותיה ויש הוכחה לדבר לומר דלא קי\\\"ל כהאי סתמא דמתניתין מדאקשי גמרא בפשיטות והרי מלח דלא תנא ביה קרא ומעכבא ביה:\",1,0],[8,362,5,13,\"המלח שמולחין בו הקרבנות וכו'. בפרק הקומץ רבה (מנחות דף כ״א):\",1,0],[8,362,5,13,\"ובשלשה מקומות היו נותנים המלח וכו' עד סוף הפרק. בפרק הקומץ רבה:\",2,0],[8,362,6,1,\"כשם שמצוה להיות כל קרבן תמים ונבחר וכו'. משנה במנחות ס״פ כל קרבנות (מנחות דף פ״ז) ר״י בר״י אומר יין שעלה בו קמחין פסול שנאמר תמימים יהיו לכם ומנחתם תמימים יהיו לכם ונסכיהם ואע״ג דמשמע דרבנן פליגי עליה לא פליגי עליה אלא למימר דיין שעלה בו קמחין שפיר הוי תמימים אבל עיקר דרשא לכ״ע איתא.\",1,0],[8,362,6,1,\"ומ\\\"ש שלא יביא נסכים לא מיין מעושן ולא מסלת שהתליעה. שם במשנה.\",2,0],[8,362,6,1,\"ומ\\\"ש ולא יבלול בשמן שריחו או טעמו רע. שם (דף פ\\\"ו) שמן של ריח רע לא יביא ואם הביא פסול:\",3,0],[8,362,6,2,\"ומ\\\"ש וכן עצי המערכה לא יהיו אלא נבחרים ולא יהיה בהם תולעת וכו'. בפ\\\"ב דמדות (משנה ה') כל עץ שנמצא בו תולעת פסול מעל גבי המזבח.\",1,0],[8,362,6,2,\"ומ״ש דה״מ כשהתליע כשהוא לח אבל אם התליע כשהוא יבש גורר המקום שהתליע. מימרא דשמואל בפרק כל קרבנות (מנחות דף פ״ה:).\",2,0],[8,362,6,2,\"ומ\\\"ש ועצי סתירה פסולים לעולם לא יביאו אלא חדשים. תוספתא פ\\\"ט דמנחות:\",3,0],[8,362,6,3,\"המקדיש יין פסול וכו'. בס״פ כל קרבנות (מנחות דף פ״ז) בעיא דלא איפשיטא:\",1,0],[8,362,6,5,\"הסולת והיין והשמן והלבונה וכו'. בד\\\"א שנפסלו או שנטמאו אחר שנתקדשו בכלי שרת וכו'. ברפי\\\"ב דמנחות (דף ק':) המנחות והנסכים שנטמאו עד שלא קדשו בכלי יש להם פדיון משקדשו בכלי אין להם פדיון העופות והעצים והלבונה וכלי שרת משנטמאו אין להם פדיון שלא נאמר פדיון אלא בבהמה ובגמרא (דף ק\\\"א) אמר שמואל אפילו הם טהורים נפדים וכו' רב כהנא אמר טמאים נפדין טהורים אין נפדים וכן אמר רבי אושעיא וכו'. איכא דאמרי אמר ר' אושעיא אפילו טהורים נפדים רבי אלעזר אומר כולם טמאים נפדים טהורים אין נפדין חוץ מעשירית האיפה של מנחת חוטא שהרי אמרה תורה מחטאתו ופסק כר\\\"א דלישנא בתרא דאתי כרב כהנא ור' אושעיא דל\\\"ק.\",1,0],[8,362,6,5,\"ומה שכתב רבינו שנאמר והעמיד והעריך כל שישנו בהעמדה נערך וכו': וכל הנסכים שנטמאו וכו'. בסוף פרק כל התדיר (זבחים דף צ״ב):\",2,0],[8,362,6,6,\"מי החג שנטמאו והשיקן וטיהרן וכו' אם הקדישן ואח״כ טיהרן וכו'. מימרא בפרק כל שעה (פסחים דף ל״ד):\",1,0],[8,362,6,7,\"זיתים וענבים שנטמאו וכו'. מימרא דרבי יוחנן שם:\",1,0],[8,362,6,8,\"מעלה יתירה עשו חכמים בקדשים וכו'. גם זה שם:\",1,0],[8,362,6,8,\"וכן העצים והלבונה וכו'. משנה (דף מ\\\"ה) וגמרא (דף מ\\\"ז:) בזבחים בס\\\"פ ב\\\"ש ולשון וכן שכתב רבינו היינו לומר שגם אלו עשו מעלה בהם ואמרו שיקבלו טומאה:\",2,0],[8,362,6,9,\"ואלו הן היינות הפסולין לגבי המזבח וכו'. משנה בפרק כל קרבנות (מנחות דף פ״ו:) אין מביאין אליוסטן ואם הביא כשר וכו' אין מביאין לא מתוק ולא מעושן ולא מבושל ואם הביא פסול ובגמרא (דף פ״ז) והא קתני רישא אין מביאין אליוסטן ואם הביא כשר אמר רבינא כרוך ותני רב אשי אמר חוליא דפירא לא מאיס חוליא דשמשא מאיס ומדברי רש״י נראה דגריס חוליא דפירא מאיס חוליא דשמשא לא מאיס והיא הנוסחא הנכונה ופירש רבינו בפי' המשנה אליוסטן מלשון שמש ר״ל שנותנים אותו בכדים תחת השמש עד שיתבשל ומה שכתב רבינו בכאן נראה שהוא מפרש שאליוסטן הוא שמחממין אותו בשמש ולא נתן בו טעם בישול אבל אם נתבשל בשמש עד שנשתנה טעמו כבישול דינו כמבושל באש.\",1,0],[8,362,6,9,\"ומ״ש וכן יין צימוקין ויין מגתו וכו'. בפרק המוכר פירות (בבא בתרא דף צ״ז).\",2,0],[8,362,6,9,\"ומ״ש ויין הדליות ויין כרם הנטוע בבית השלחין או בבית הזבלים או יין גפנים שנזרע זרע ביניהם או יין כרם שלא נעבד כל אלו היינות לא יביא לכתחלה. במשנה סוף פרק כל קרבנות (מנחות דף פ״ו):\",3,0],[8,362,6,10,\"יין שנתגלה פסול מעל גבי המזבח. בפרק המוכר פירות (בבא בתרא דף צ״ח:) ובסוכה סוף פרק רביעי (דף מ״ח):\",1,0],[8,362,6,10,\"הדלה גפן על גבי תאנה יינה פסול לנסכים. בפרק ב' דבכורות (דף י\\\"ז):\",2,0],[8,362,6,11,\"סלת שהתליעה רובה וכו'. ברייתא בפרק כל קרבנות (מנחות דף פ״ה:).\",1,0],[8,362,6,11,\"ומ\\\"ש התליע רוב חטה אחת הרי זה ספק. שם בעי ר' ירמיה ברוב חטה או ברוב סאה תיקו ומשמע דהכי פירושה הא דאמרינן דחטים שהתליעו רובן פסולות היינו כשהתליע רוב כל חטה וחטה אבל אם לא התליע רוב כל חטה וחטה אע\\\"פ שהתליע רוב סאה או כולה מאחר שלא התליע מכל חטה אלא מיעוטה כשר או דילמא כיון שהתליעה רוב סאה אע\\\"פ שלא התליע מכל חטה אלא מיעוטה פסול אבל מדברי רבינו נראה שהוא מפרש מי סגי ברוב חטה אחת שתהיה מתלעת אפילו היא מעורבת בסאה חטים שלא התליעו או דילמא לא מיפסיל עד שיתליעו רוב חטים שבסאה:\",2,0],[8,362,6,11,\"וכל סולת שנשאר בה קמח פסולה:\",3,0],[8,362,6,12,\"כיצד בודקין מכניס הגזבר ידו לתוך הסולת וכו'. משנה בפרק כל קרבנות (מנחות דף פ״ה).\",1,0],[8,362,6,12,\"ומ\\\"ש אבל סולת חטים שנזרעו בבית השלחין וכו' לא יביא לכתחילה ואם הביא כשר. משנה שם.\",2,0],[8,362,6,12,\"ומ\\\"ש או בארץ שלא נרה ולא עבדה משמע לרבינו דהא דתנן בפ' כל קרבנות כיצד הוא עושה נרה שנה ראשונה וכן מה שאמרו שם בגמרא שעובדה היינו לכתחלה דוקא:\",3,0],[8,362,6,13,\"חטים שלקטן מגללי הבקר וזרעם הרי אלו ספק וכו'. בפרק ר' ישמעאל (מנחות דף ס\\\"ט) בעיא דלא איפשיטא:\",1,0],[8,362,6,14,\"ואלו הן השמנים הפסולים וכו' עד כל אלו פסולים. משנה וברייתא בפרק כל קרבנות (מנחות דף פ״ה:) חוץ משמן של פגין דתנן התם אין מביאין אנפיקנון ואם הביא פסול ובגמרא (דף פ״ו) והתניא ואם הביא כשר וכו' ל״ק הא רבי חייא הא רבי שמעון ברבי ויש לתמוה למה לא פסק כסתם מתניתין. וי״ל שרבינו היה גורס במתניתין ואם הביא כשר וכך היה גורס רבינו תם.\",1,0],[8,362,6,14,\"ומ\\\"ש אבל שמן זית שנטעו בבית הזבלים או בבית השלחין או שנזרע וכו' עד ואם הביא כשר. משנה שם:\",2,0],[8,362,6,15,\"כל המנחות והנסכים כשרים מהארץ ומחוצה לארץ עד סוף הפרק. שם במשנה:\",1,0],[8,362,7,2,\"לא כל דבר שאינו פסול מביא אותו לכתחלה וכו' אלא כל שיביא לקרבן יביא מן המובחר וכך היו עושים בזמן המקדש מביאים אילים ממואב וכו' עד ומביאין שמן מתקוע. בפרק כל קרבנות (מנחות דף פ״ה פ״ז:):\",1,0],[8,362,7,3,\"כל העצים החדשים כשרים למערכה וכו' עד ובשל עץ שמן. משנה וגמרא בפ' ב' דתמיד (דף כ\\\"ט) ובמקום מה שאמרו בגמרא בתאנה דלא עבדא פירי כתב רבינו תאנה של חרשים כלומר של יערים:\",1,0],[8,362,7,3,\"והגיזרין שעשה משה וכו'. מימרא בזבחים פ' קדשי הקדשים (ס\\\"ב:):\",2,0],[8,362,7,4,\"וכיצד היו עושין בזריעת חיטי המנחות והנסכים וכו' עד ואחר כך זורע. בפ' כל קרבנות (מנחות דף פ״ה) תנן כיצד הוא עושה נרה שנה א' ובשנה ב' זורעה קודם לפסח ע' יום והיא עושה סלת מרובה ומפרש בברייתא ובגמ' נר חציה וזורע חציה. ופי' רבינו בה מבואר ורש״י פי' בע״א.\",1,0],[8,362,7,4,\"ומ\\\"ש ואם לא היתה השדה עבודה חורש ושונה וכו'. שם.\",2,0],[8,362,7,4,\"ומ\\\"ש ובורר את החיטים יפה יפה. ומ\\\"ש ואח\\\"כ שף את החיטים ובועט בהם הרבה עד שיתקלפו:\",3,0],[8,362,7,5,\"כל החיטים של מנחות טעונות שלש מאות שיפה ות\\\"ק בעיטה וכו'. משנה (דף ע\\\"ו) בפרק אלו מנחות.\",1,0],[8,362,7,5,\"ומ\\\"ש וחושב ההולכה וההובאה בשיפה אחת להחמיר. שם בעיא דלא איפשיטא:\",2,0],[8,362,7,6,\"היין מביא ענבים וכו'. משנה וברייתא שם (דף פ\\\"ו:) ופירש\\\"י רוגליות גפנים נמוכים שהוא יפה.\",1,0],[8,362,7,6,\"ומ\\\"ש ואין מניחין אותן אחת אחת וכו'. שם בברייתא (דף פ\\\"ז) אין מניחין אותן שתים שתים אלא אחת אחת ואין כן גירסת רבינו.\",2,0],[8,362,7,6,\"ומ\\\"ש ואינו ממלא החבית עד פיה כדי שיהא ריחו נודף. משנה בפרק כל קרבנות ופירש\\\"י כשהיא חסרה קימעא היין נודף יותר מכשהיא מליאה.\",3,0],[8,362,7,6,\"ומ\\\"ש ואינו מביא לא מפי החבית וכו' עד אלא משלישה ומאמצעה. משנה שם:\",4,0],[8,362,7,6,\"ומ\\\"ש של האמצעית נראה שכך היה גורס רבינו שם:\",5,0],[8,362,7,7,\"ומ\\\"ש היה הגזבר יושב וכו' עד ואינו לוקה. משנה שם:\",1,0],[8,362,7,7,\"מאימתי מביא מאחר ארבעים יום לדריכתו. משנה בפ\\\"ו ממס' עדיות (מ\\\"א).\",2,0],[8,362,7,7,\"ומ״ש עד שתי שנים וכו'. בפרק כל קרבנות (מנחות דף פ״ו:) תנן אין מביאין ישן דברי רבי וחכמים מכשירין ובגמרא (דף פ״ז) מאי טעמא דרבי אמר קרא לכבש יין מה כבש בן שנתו אף יין בן שנתו אי מה כבש בן שתי שנים פסול אף יין בן שתי שנים פסול וכ״ת הכי נמי והא תניא יין בן שתי שנים לא יביא ואם הביא כשר מאן שמעת ליה דאמר לא יביא רבי וקאמר אם הביא כשר אלא אמר רבא היינו טעמא דרבי דכתיב אל תרא יין כי יתאדם וידוע דהלכה כת״ק ומשמע לרבינו דע״כ לא פליג ת״ק על רבי אלא בבן שתי שנים או יותר מעט אבל במיושן יותר לתנא קמא נמי לכתחלה לא יביא.\",3,0],[8,362,7,7,\"ומ\\\"ש והוא שלא יפסד טעמו. פשוט הוא דלא עדיף ממעושן דפסול:\",4,0],[8,362,7,8,\"תשעה מינים בשמן וכו' עד והשוה והפחות. משנה שם (דף פ\\\"ו).\",1,0],[8,362,7,8,\"ומ\\\"ש שהרוצה לזכות עצמו יכוף יצרו הרע וירחיב ידו ויביא קרבנו מן היפה המשובח ביותר שבאותו המין שיביא ממנו וכו'. הם דברי רבינו ראויים אליו:\",2,0],[8,362,7,8,\"בריך רחמנא דסייען\",3,0],[8,363,1,1,\"כל הקרבנות של מיני נפש חיה וכו'. הכל מבואר בתורה כמו שכתב רבינו בסוף דבריו:\",1,0],[8,363,1,4,\"ומה שכתב ואין הצבור מקריבין אשם לעולם ולא עוף. בריש פרק ב' דתמורה (דף י\\\"ד) אשם ביחיד איתיה בצבור ליתיה, ובתורת כהנים ואם מן העוף יחיד מביא עוף ואין צבור מביא עוף:\",1,0],[8,363,1,6,\"ומ\\\"ש וקרבן הגר והוא עולה מן הבהמה או שני בני יונה או שתי תורים וכו'. פ' ד' מחוסרי כפרה (כריתות דף ח' ט'):\",1,0],[8,363,1,7,\"כל קרבנות היחיד חייב באחריותן וכו'. משנה בפרק ב' דתמורה קרבנות היחיד חייבין באחריותן ובאחריות נסכיהם וקרבנות הצבור אין חייבין (לא) באחריותן ולא באחריות נסכיהם אבל חייבין באחריות נסכיהם משקרב הזבח, ופירש רש\\\"י קרבנות היחיד חייבים באחריותם כלומר ויש מהם מאותן שקבוע להם זמן שאפילו עבר זמנם חייבין להקריבם כגון עולת יולדת וקרבנות מצורע אם עבר שמיני שלו יכול להקריבן לאחר זמן אבל קרבנות הצבור שיש להם זמן אם עבר זמנן בטל קרבנן.\",1,0],[8,363,1,7,\"משקרב הזבח שאם קרב הזבח בזמנו ולא קרבו נסכים עמו חייב להקריבם אפילו מכאן עד עשרה ימים עכ\\\"ל, וכן פירש רבינו בפירוש המשנה והכי משמע בגמרא. וממה שכתב\",2,0],[8,363,1,7,\"רבינו חוץ מן הנדבה נראה שהוא מפרש שבכלל מה שאמרו ביחיד חייב באחריותן שאם הפריש קרבנו ואבד חייב באחריותו והדין מפורש בריש קנים:\",3,0],[8,363,1,7,\"ומה שכתב רבינו וקרבן היחיד שקבוע לו זמן הרי הוא כקרבן צבור וכו'. פשוט הוא דכיון שעבר זמנו בטל קרבנו. וקרבן יחיד שקבוע לו זמן היינו חביתי כהן גדול ופר יום הכפורים:\",4,0],[8,363,1,8,\"כל עולת בהמה אינה באה אלא מן הזכרים וכו' עד ואין העוף בא שלמים. הכל מבואר בתורה בפ' ויקרא.\",1,0],[8,363,1,8,\"ומה שכתב בין גדולים בין קטנים דכתיב ומיום השמיני והלאה ירצה.\",2,0],[8,363,1,8,\"ומ\\\"ש ואחד בהן הזכר והנקבה. ברפ\\\"ב דתמורה (דף י\\\"ד) אין תמות וזכרות בעופות:\",3,0],[8,363,1,9,\"ומ\\\"ש החטאת באה מחמשה מינים האלו מן הזכרים ומן הנקבות. מפורש בפרשת ויקרא שיש חטאות שהן באות זכרים ויש חטאות שהן באות נקבות.\",1,0],[8,363,1,9,\"ומה שכתב מן הגדולים ומן הקטנים, בפ' ויקרא. כתוב בקצת הנוסחאות פר שהוא גדול שבמינו ובקצת כתוב שעירת עזים שהיא קטנה שבמינה:\",2,0],[8,363,1,10,\"ומ\\\"ש האשם אינו בא אלא מזכרי הכבשים בלבד. מפורש בפ' ויקרא.\",1,0],[8,363,1,10,\"ומ\\\"ש יש אשם בא מגדולי מין זה וכו'. בפרשת ויקרא האשמות הם איל ובפ' נשא גבי נזיר האשם הוא כבש:\",2,0],[8,363,1,11,\"ומ\\\"ש השלמים באים מן הכבשים וכו'. מפורש בפ' ויקרא.\",1,0],[8,363,1,11,\"ומ\\\"ש ואין העוף בא שלמים. בת\\\"כ בפרשת ויקרא אין עוף בא שלמים:\",2,0],[8,363,1,11,\"הקטנים הם בני שמונה ימים, מקרא מפורש ומיום השמיני והלאה ירצה.\",3,0],[8,363,1,11,\"ומ\\\"ש עד שנה תמימה וכו'. בפרקא בתרא דערכין (דף ל\\\"א) גבי בתי ערי חומה תנו רבנן שנה תמימה רבי אומר מונה שס\\\"ה ימים כמנין ימות החמה וחכמים אומרים מונה י\\\"ב חודש מיום ליום ואם נתעברה נתעברה לו. ובסוף תוספתא דנגעים שנה האמורה בתורה שס\\\"ה כנגד ימות החמה דברי רבי וחכמים אומרים מאחד בניסן לאחד בניסן מט' באב לט' באב אם נתעברה שנה נתעברה לו.\",4,0],[8,363,1,11,\"ומ\\\"ש ובבקר עד שלש שנים שלימות מיום ליום. בפ\\\"ק דמסכת פרה (משנה ב') רבי יוסי הגלילי אומר פרים בני שתים וחכמים אומרים בני שלש.\",5,0],[8,363,1,11,\"ומ\\\"ש ובצאן עד שתי שנים שלימות. בפ\\\"ק דפרה כבשים בני שנה ואילים בני שתים וכולם מיום ליום:\",6,0],[8,363,1,12,\"אע\\\"פ שכל הקרבנות כשרים וכו'. משנה סוף פרק קמא דפרה, וכתב שם רבינו שנלמד זה מדכתיב והלאה אבל בבכור נאמר וביום השמיני תתנו לי ופסח ומעשר נשוו לבכור לענין מתן דמים כדאיתא בפרק איזהו מקומן. ושנוי שם שנדרים ונדבות דינם שוה לבכור ומעשר ופסח ולא ידעתי למה השמיטו רבינו:\",1,0],[8,363,1,13,\"שעות מונין לקדשים וכו'. בפ' שני דזבחים (דף כ״ה:) ובפרק על אלו מומין (בכורות דף ל״ט:) זאת אומרת שעות פוסלות בקדשים. ופירש״י דשנה האמורה בקדשים אמרינן בפרק יוצא דופן דאין מונין לה מתשרי כשאר ראשי שנים אלא מיום שנולד מעת לעת בשנה הבאה וילפינן לה מקראי דכתיב בהו בן שנתו שנתו שלו ולא של מנין העולם ואשמועינן הכא דלא תימא מיום ליום הוא דבעינן ולא משעה לשעה [אלא אף משעה לשעה] שאם נולד בניסן בי״ד בט' שעות ושחטו לשנה הבאה בי״ד בניסן בט' שעות אסור לזרוק דמו בעשירית שכבר עברה שנתו:\",1,0],[8,363,1,14,\"כל מקום שנאמר בתורה כבש וכו' עד והוא הנקרא פלגס. בסוף פרקא קמא דפרה.\",1,0],[8,363,1,14,\"ומה שכתב וכל מקום שנאמר בו עגל הרי זה בן שנה. בפירקא קמא דראש השנה (דף י').\",2,0],[8,363,1,14,\"ומה שכתב פר בן שתים. בפירקא קמא דמסכת פרה רבי יוסי הגלילי אומר פרים בני שתים שנאמר ופר שני בן בקר תקח לחטאת וחכמים אומרים אף בני שלש ופסק כרבי יוסי הגלילי. ואיני יודע למה לא פסק כחכמים דרבים נינהו ועוד דבפירקא קמא דראש השנה (דף י') תניא כוותייהו ועוד שהוא עצמו כתב בסמוך הגדולים בבקר עד שלש שנים שלימות מיום ליום ובהקדמתו לפירוש משניות סדר זה כתב שפר הוא בן ג'. וי\\\"ל שרבינו מפרש דחכמים נמי ילפי מפר שני שיהא בן שתי שנים והיינו לענין שאם התנדב פר לא יהא פחות משתי שנים אלא שסוברים שלא יהא גדול יותר מבן ג' ופסק כחכמים.\",3,0],[8,363,1,14,\"ומה שכתב שעיר עזים בן שתים כל שנה שניה הוא נקרא שעיר יש לתמוה על זה דהא תנן פירקא קמא דפרה חטאות הצבור וכו' כשרים מיום שלשים והלאה וחטאות הצבור היינו שעירי ראשי חדשים ושל מועדות וכתיב בהם שעיר עזים אלמא דשעיר עזים הוא בן שנה. וכן נראה מפירש\\\"י פ' שלח לך דשעיר עזים הוא תוך שנה ובריש פרק ט\\\"ז מהלכות אלו משמע דשעיר הוא נקרא שנה שניה שכתב אם אמר הרי עלי גדי והביא שעיר יצא וכתב עוד קבע בעזים ושכח יביא שעיר. ולכן נראה שיש להגיה בלשון רבינו ולגרוס שעיר עזים בן שנה שעיר בן שתים:\",4,0],[8,363,1,16,\"כל קרבנות הצבור זכרים. משנה בפ\\\"ב דתמורה (דף י\\\"ד).\",1,0],[8,363,1,16,\"ומ\\\"ש וכן חטאות הצבור מן העז או מן הבקר ואין בהם מן הכבשים וכו' עד ושלש לצבור אלו הם כללים לקוחים מפסוקי התורה:\",2,0],[8,363,1,17,\"כל הקרבנות האלו נקראים זבחים וכו' עד הם הנקראים אימורים. כל זה נלמד ממקומות ממסכת זבחים:\",1,0],[8,363,1,17,\"כתב הראב\\\"ד ז\\\"ל הם הנשרפות שתים ליחיד א\\\"א נראה שהוא מונה שעירת יחיד וכו'. דברי הראב\\\"ד תמוהים שכתב נראה שהוא מונה שעירת יחיד בכלל שעירים הנשרפים וזה לא נמצא רמז לו בדברי רבינו שהרי כתב הא למדת שחמש חטאות הם הנשרפות שתים ליחיד וכבר נתבאר בתחלת דבריו שחטאות היחיד הנשרפות הם פר כהן משיח הבא על כל המצות ופר של כ\\\"ג ביוה\\\"כ ולא באו כאן שעירי ע\\\"ז אפילו ברמז וכן כתב ג\\\"כ בפירוש המשנה בהקדמתו לסדר קדשים וז\\\"ל יתבאר לך שאין שורפין מכל חטאות היחיד אלא פר הבא על כל המצות ופר יוה\\\"כ ושאר כולם יאכלו עכ\\\"ל. ולא נזכרו בדברי רבינו שעירי ע\\\"ז אלא בקרבנות הצבור שכתב כל חטאות של צבור נאכלות חוץ משעיר של יוה\\\"כ שחבירו משתלח וכן שעירי ע\\\"ז ופר העלם עכ\\\"ל. והם מה שמביאין בע\\\"ז פר ושעיר לכל שבט ופר ושעיר לבית דין וכתב בפי\\\"ב מהלכות שגגות שהם נשרפים והם הנקראים שעירי ע\\\"ז. ולכן אני אומר שאין ספק שספר מוטעה נזדמן להראב\\\"ד בדברי רבינו ולכן כתב מ\\\"ש וגירסת ספרינו בדברי רבינו היא נכונה:\",2,0],[8,363,1,18,\"ואלו הם האימורים וכו'. מפורש בתורה פ' ויקרא.\",1,0],[8,363,1,18,\"ומ״ש ובכללו חלב שעל הקיבה. שם בת״כ ואת כל החלב אשר על הקרב ר' ישמעאל אומר להביא חלב שעל הקיבה ר״ע אומר להביא חלב שעל הדקין ובפ' אלו טרפות (חולין דף מ״ט) מייתי להאי ברייתא וקאמר דנהוג כהני כהא דר״ע ולא ידעתי למה פסק רבינו דלא כר״ע ואפשר שטעמו משום דבפרק אלו טרפות אמרינן בחלב הקיבה דאקשתא כ״ע לא פליגי דאסור כי פליגי בדאייתרא ואיכא דאמרי איפכא אלמא לכ״ע יש חלב אסור בקיבה ומפרש רבינו דהיינו כרבי ישמעאל דאילו לר״ע לא הוה מעלה מחלב הקיבה כלל ולא כדפירש״י.\",2,0],[8,363,1,18,\"ומ\\\"ש ונוטל מן הכבד מעט עם היותרת. בת\\\"כ יליף לה מקרא.\",3,0],[8,363,1,18,\"ויותרת הכבד. כתב רבינו בהקדמתו לסדר קדשים שהוא הקצה התחתון היוצא ממנו כמו הבהן מן היד.\",4,0],[8,363,1,18,\"ומ\\\"ש ואם היה הקרבן ממין הכבשים מוסיף על אלו האליה תמימה. מפורש בתורה.\",5,0],[8,363,1,18,\"ומ\\\"ש עם החוליות מן השדרה. בת\\\"כ יכול יטלנה עם השדרה ת\\\"ל לעומת העצה יכול לא יכנס לפנים מן העצה ת\\\"ל יסירנה יכנס לפנים מן העצה ומשמע לרבינו דהיינו שיטול עמו חוליות השדרה ולא מיעט אלא שלא יטול כל השדרה.\",6,0],[8,363,1,18,\"ומ\\\"ש וכל האימורים היו נשרפים על מזבח החיצון. זה פשוט שהרי המזבח הפנימי אסור להעלות עליו כ\\\"א קטרת בלבד כדאיתא בסוף פ' תצוה:\",7,0],[8,363,1,19,\"היתה הבהמה מעוברת וכו'. בפרק בהמה המקשה (חולין דף ע\\\"ה) מה חלב ושתי כליות האמור באשם מוצא מכלל שליל אף כל מוצא מכלל שליל. ופירש רש\\\"י מוצא מכלל שליל חלב זה מוצא מכלל חלב שליל שאינך יכול לומר חלב שליל יקריב הנמצא באשם שהרי אין אשם נקבה אף כל אפילו בקרבנות הבאים נקבה חלב האמור בהם מוצא מכלל שליל:\",1,0],[8,363,2,1,\"היין והסולת שמביאין עם הקרבן וכו'. פשוט הוא:\",1,0],[8,363,2,1,\"ומנחת נסכים אינה טעונה לא תנופה ולא הגשה ולא לבונה. במשנה פרק כל המנחות (מנחות דף נ״ט וס״א).\",2,0],[8,363,2,1,\"ומ״ש אבל טעונה מלח. בפרק הקומץ רבה (מנחות דף כ״א:) בשלשה מקומות המלח נתונה וכו' בראש המזבח ששם מולחים הקומץ והלבונה וכו' ומנחת נסכים.\",3,0],[8,363,2,1,\"ומ״ש וכולה נשרפת. פשוט הוא שהרי לא מצינו שתהא נקמצת ובהדיא תנן בפרק אלו מנחות (מנחות דף ע״ד:) מנחות ונסכים למזבח ואין בה לכהנים.\",4,0],[8,363,2,1,\"ומ\\\"ש על מזבח החיצון. גם זה פשוט שמזבח הפנימי אסור להעלות עליו כי אם קטרת בלבד כמו שמפורש בסוף פרשת תצוה.\",5,0],[8,363,2,1,\"ומ\\\"ש ויתנסך היין ואין נותנין אותו על האש. בפ' אלו מנחות אהא דתנן בזו יפה כח המזבח מכח כהנים ותו ליכא וכו' והא איכא נסכים לשיתין אזלי ומאי בזו לאפוקי מדשמואל דאמר שמואל המתנדב יין מביא ומזלפו על גבי אישים ופירש\\\"י לשיתין אזלי ולא לאישים.\",6,0],[8,363,2,1,\"ומ״ש אלא מגביה ידו. אין לומר שטעמו מדתנן בפרק לולב וערבה (סוכה דף מ״ח:) למנסך אומרים לו הגבה ידך שפעם אחת ניסך על גבי רגליו ורגמוהו כל העם באתרוגיהם דבניסוך המים דוקא אמרו כן שהיא הלכה למשה מסיני ואין הצדוקים מודים בה וחוששין שלא יהא אותו כהן צדוקי אבל בניסוך היין אין צורך להגביה ידו מפני חששא זו אלא אורחא דמילתא נקט:\",7,0],[8,363,2,1,\"ועל מ\\\"ש רבינו ויוצק על היסוד. כתב הראב\\\"ד זה שיבוש שלא היה יוצק על היסוד אלא בספל של יין שהיה בקרן מערבית דרומית עם ספל של מים של ניסוך המים בחג עכ\\\"ל. היה נראה לומר שטעמו מדתנן בפרק לולב וערבה שני ספלים של כסף היו שם וכו' ומנוקבים כמין שני חוטמין דקים וכו' מערבי של מים ומזרחי של יין וסובר הראב\\\"ד שכך היו עושים לכל הנסכים שהיו נותנים אותו בספל וממנו יורד לשיתין, ורבינו סובר שמאחר שלא הוזכרו בגמרא ספלים אלא בניסוך דחג משמע שלא היו הספלים משמשים אלא לאותו ניסוך בלבד ואע\\\"ג דתניא בסיפרי פ' נסכים על גבי ספלים או אינו אלא על גבי האישים אם אתה אומר כן נמצאת מכבה את המדורה וזה מבואר כדברי הראב\\\"ד, ל\\\"ק דההיא כר' יהודה דאמר דבר שאין מתכוין אסור וכדאוקמוה בס\\\"פ כל התדיר (זבחים צ\\\"ב) ואע\\\"ג דאמרינן לאפוקי מדשמואל דאמר מזלפו על האישים לדעת רבינו יש לומר דלאו מש\\\"ה נימא דלספלים כיון דאפשר דנימא דליסוד דספלים שאמרו לאו דוקא אלא למעט שלא ינסך על גבי האישים ודוחק:\",8,0],[8,363,2,2,\"אין טעון נסכים אלא עולת בהמה ושלמים בלבד וכו' עד או במועדיכם. בפרק שתי מדות (מנחות צ':) תנן כל קרבנות הצבור והיחיד טעונין נסכים חוץ מן הבכור והמעשר והפסח והחטאת והאשם אלא שחטאתו של מצורע ואשמו טעונין נסכים ויליף לה בגמרא מקרא והתם יליף נמי דעוף אין לו נסכים:\",1,0],[8,363,2,4,\"כמה הוא שיעור נסכים וכו'. מפורש בתורה:\",1,0],[8,363,2,5,\"אין מוסיפין על השיעורים האלו וכו'. בפ\\\"ק דמנחות תנן ריבה שמנה וחיסר שמנה וכו' פסולה ואמרי' בפ' המנחות והנסכים ובספרי שהטעם מדכתיב בנסכים ככה וא\\\"כ ה\\\"ה ליין. ובתוספתא רפ\\\"ח דמנחות כל המנחות שריבה מדת חלות או שחיסר מדת חלות או שהיתה מדה חסרה מחבירתה או יתירה מחבירתה הרי אלו פסולות ומשמע דכללא הוא בין ליין בין לשמן:\",1,0],[8,363,2,5,\"ומ״ש חוץ מכבש העולה וכו'. משנה בפרק שתי מדות (מנחות דף פ״ט:) הכבש הבא עם העומר אע״פ שמנחתו כפולה לא היו נסכיו כפולים ובגמרא בברייתא יכול כשם שמנחתו כפולה כך יינו כפול ת״ל ונסכו יין רביעית ההין יכול לא יהא יינו כפול שאינו נבלל עם מנחתו אבל יהא שמנו כפול שנבלל עם מנחתו ת״ל ונסכה כל נסכין לא יהו אלא רביעית מאי תלמודא אמר ר' אלעזר כתיב ונסכה וקרינן ונסכו כיצד נסכה דמנחה כנסכו דיין מה יין רביעית אף שמן נמי רביעית. ונראה שיש חסרון בלשון רבינו וצריך להגיה ולכתוב לא נכפל יינו ושמנו כי השמן הוא עיקר החידוש שהוא נלמד מדרשא.\",2,0],[8,363,2,5,\"ועל מה שכתב רבינו חוץ מכבש העולה שמקריבין ביום הנפת העומר שהנסכים שלו שני עשרונים בלול בשלישית ההין שמן. כתב הראב\\\"ד זה שיבוש ובהדיא גרסינן במנחות וכו'. ונראה ודאי שיש טעות סופר בדברי רבינו וצריך להגיה ולכתוב ברביעית ההין שמן:\",3,0],[8,363,2,6,\"המצורע מביא עם שלשה כבשים שלו וכו' שלשה עשרונים ומפי השמועה למדו וכו'. ברייתא בפרק שתי מדות (מנחות דף צ״א) על הא דתנן אלא שחטאתו ואשמו של מצורע טעונין נסכים:\",1,0],[8,363,2,6,\"והמקריב את הפלגס וכו'. משנה בסוף פ״ק דפרה ובפ' שתי מדות (מנחות דף צ״א) ועיין במ״ש בפ״י מהלכות אלו:\",2,0],[8,363,2,7,\"ההין הוא י״ב לוג. בפרק שתי מדות (מנחות דף פ״ט):\",1,0],[8,363,2,8,\"כשמודדין הנסכים או המנחות וכו' אין מודדין אותו במדה של שלשה עשרונים לפר וכו' אלא מודד הכל בעשרון שהיה במקדש. משנה בריש פרק שתי מדות (מנחות דף פ״ז).\",1,0],[8,363,2,8,\"ומה שכתב וכן השמן של נסכים מודדין אותו במדתו שבמקדש. כלומר שהיו במקדש חצי ההין ושלישית ההין ורביעית ההין כמו ששנינו בפרק שתי מדות למדוד בכל מדה מהן לקרבן הראוי לו ע\\\"פ מ\\\"ש בפרשת שלח לך.\",2,0],[8,363,2,8,\"ומה שכתב ושמן של מנחות היחיד בלוג שבמקדש כמנין העשרונות כך מנין הלוגין. משנה שם (דף פ\\\"ז) וכת\\\"ק:\",3,0],[8,363,2,9,\"בירוצי המדות של סלת חול וכו' ובירוצי היין והשמן קדש וכו'. משנה שם (דף צ') ופירש\\\"י בירוצי מה שנופל מן הכלי אחר שנתמלא.\",1,0],[8,363,2,9,\"ומ\\\"ש לפי שהוא יורד ע\\\"ג הכלי וכו'. היינו כת\\\"ק וכר\\\"ע שם.\",2,0],[8,363,2,9,\"ומ\\\"ש ולמה יתקדשו הבירוצין וכו'. שם בגמרא וכרבינא דאסיק הכי ואע\\\"ג דעל דברי ר\\\"י הגלילי אתמר מיניה נשמע לת\\\"ק ולר\\\"ע:\",3,0],[8,363,2,10,\"מה היו עושים בבירוצים וכו' עד והעורות לכהנים. ברייתא שם (דף צ':) פירוש אם לנו שלא הקריבן עם הזבח האחר נפסלו בלינה דכיון שיש שם זבח אחר נתקדשו הבירוצין ליפסל בלינה אבל אם אין שם זבח אחר לא נתקדשו כלל ופודין אותן ויוצאין לחולין ודמיהן לקיץ המזבח. ולשון מקיצין מפרש בגמרא פ\\\"ק דשבועות (דף י\\\"ב) שהוא כאדם שמביא בקינוח סעודה מיני מתיקה והוא מלשון קיץ כדכתיב הלחם והקיץ לאכול לנערים כלומר מקריבין אותם שלא לשם תמידים אלא כמו מיני מגדים שאינם מעיקר הסעודה:\",1,0],[8,363,2,12,\"הסלת עם השמן של נסכים וכו'. משנה בפרק התכלת (מנחות דף מ״ד:).\",1,0],[8,363,2,12,\"ומ\\\"ש ולא הנסכים מעכבין את הזבח אלא מביא אדם קרבנו היום ונסכיו אחר עשרה ימים. בפ\\\"ב דמנחות (דף ט\\\"ו:) ובתוספתא דזבחים פ\\\"ה.\",2,0],[8,363,2,12,\"ומ״ש והוא שלא קדשו הנסכים בכלי שרת וכו'. משנה בפרק התודה (מנחות דף ע״ט) הנסכים שקדשו בכלי ונמצא הזבח פסול אם יש שם זבח אחר יקריב עמו ואם לא יפסלו בלינה הרי בהדיא שאם קדשו בכלי נפסלו בלינה.\",3,0],[8,363,2,12,\"ומ\\\"ש אחד יחיד ואחד צבור:\",4,0],[8,363,2,13,\"אין מביאין נסכים אלא מן החולין וכו'. ואפילו תודה שמביא לחמה מן המעשר לא יביא נסכים אלא מן החולין. משנה במנחות פרק התודה (מנחות דף פ״ב) הנסכים בכל מקום לא יביאו אלא מן החולין:\",1,0],[8,363,2,14,\"כל שיעורי הנסכים האמורים בספר יחזקאל וכו'. בפ' התכלת (מנחות דף מ״ה):\",1,0],[8,363,2,15,\"ומ\\\"ש וכן קרבנות שהקריבו בימי עזרא וכו':\",1,0],[8,363,3,1,\"שנים שרצו להביא שלמים או עולה בשותפות מביאין וכו' ואפי' עוף יבוא בשותפות. משנה בס\\\"פ המנחות (ק\\\"ד.) ויליף לה בגמרא מקראי ואיתא נמי בת\\\"כ פ' ויקרא:\",1,0],[8,363,3,2,\"ואחד אנשים ואחד נשים או עבדים מביאים כל הקרבנות. זה פשוט שהכתוב השוה אשה לאיש לכל דינין שבתורה וכבר אמרו שנשים אינן סומכות ושנינו בפ\\\"ק דקדושין (דף ל\\\"ו) הסמיכות והתנופות וכו' נוהגות באנשים ואינם נוהגות בנשים משמע שמביאות קרבן וכל מצות שהאשה חייבת בהם עבד חייב בהן:\",1,0],[8,363,3,2,\"אבל הנכרים אין מקבלין מהם אלא עולות. בפ״ק דחולין (דף י״ג:) ובפרק אלו מנחות (מנחות דף ע״ג:) תניא איש איש לרבות הנכרים שנודרים נדרים ונדבות כישראל.\",2,0],[8,363,3,2,\"ומ\\\"ש אפי' עולת העוף מקבלין מן הנכרי. בפרק אלו מנחות תניא אין לי אלא עולה שלמים מנין תלמוד לומר נדריהם. תודה מנין תלמוד לומר נדבותם. מנין לרבות העופות והיין והלבונה והעצים ת\\\"ל [נדריהם] לכל [נדריהם וכו'] א\\\"כ מה ת\\\"ל עולה עולה פרט לנזירות דברי ר\\\"י הגלילי ר\\\"ע אומר אשר יקריבו לה' לעולה אין לי אלא עולה בלבד ופסק רבינו כר\\\"ע ומשמע לרבינו דעולת העוף לא נפקא מכלל עולה סתם.\",3,0],[8,363,3,2,\"ומ\\\"ש ולא מנחות. אע\\\"ג דגבי אלו מנחות נקמצות ושיריהם לכהנים (דף ע\\\"ב:) מני מנחת נכרי האי מוקי לה בגמרא (דף ע\\\"ג:) כר' יוסי הגלילי ואע\\\"ג דסתם מתניתין כר\\\"י הגלילי לא פסק רבינו כוותיה משום דרב הונא סבר דלא כוותיה.\",4,0],[8,363,3,2,\"ומ\\\"ש אף על פי שהוא עובד ע\\\"ז. הכי משמע בפרק קמא דחולין.\",5,0],[8,363,3,2,\"ומ\\\"ש אבל אין מקבלין מהם שלמים וכו'. נתבאר בסמוך בפ\\\"ק דשקלים תנן גבי נכרי וכותי אין מקבלין מידם קיני זבין קיני זבות קיני יולדות חטאות ואשמות זה הכלל כל (שהוא) נידר ונידב מקבלין מידם וכל שאינו לא נידר ולא נידב אין מקבלין מידם ושם נתבאר בירושלמי שאין מקבלים מיד הכותים אלא עולות. גם שם (דף ג') נתבאר דקיני זבין וקיני זבות אכותי שהוזכר שם קאי דאילו בנכרי לא שייך זבים וזבות:\",6,0],[8,363,3,3,\"נכרי שהביא שלמים מקריבים אותם עולות וכו'. מימרא בפרק אלו מנחות (מנחות דף ע״ג:) ופירש״י לבו לשמים כוונתו היא שיהו קרבנותיו כליל לשמים ולא שיאכלו.\",1,0],[8,363,3,3,\"ומ\\\"ש נדר שלמים ונתנם לישראל וכו' עד כהן אוכלו. שם:\",2,0],[8,363,3,4,\"ישראל שהוא מומר לע\\\"ז וכו'. בפ\\\"ק דחולין (דף ה') מכם וכו' להוציא את המומר וכו' מן הבהמה להביא בני אדם שדומים לבהמה מכאן אמרו מקבלין קרבנות מפושעי ישראל כדי שיחזרו בהם בתשובה חוץ מן המומר וכו' לנסך את היין ולחלל שבתות בפרהסיא:\",1,0],[8,363,3,4,\"ומ\\\"ש היה מומר לעבירה וכו'. שם והא מהכא נפקא מהתם נפקא מעם הארץ פרט למומר ר\\\"ש וכו' אומר אשר לא תעשינה בשגגה ואשם השב מידיעתו מביא קרבן על שגגתו אינו שב מידיעתו אינו מביא [קרבן] על שגגתו ואמרינן מאי בינייהו ואמר רב המנונא מומר לאכול חלב והביא קרבן על הדם ששגג בו ואילו היה יודע שהיה דם לא היה אוכלו לת\\\"ק מומר שמו ולא מקבלינן מיניה ולר\\\"ש שב מידיעתו הוא בדם ומקבלינן מיניה. ובפ\\\"ג דהוריות (דף י\\\"א) אמרינן אהא דרב המנונא והא רבא אמר דכ\\\"ע מומר לאכול חלב לא הוי מומר לדם אלא הכא באוכל נבילה לתיאבון ונתחלף לו בשומן ואכלו קא מיפלגי מ\\\"ס כיון דלתיאבון קא אכיל במזיד מומר הוא ומ\\\"ס כיון דאילו אשכח דהיתרא לא אכיל דאיסורא לאו מומר הוא. ופי' רש\\\"י באוכל נבלה לתיאבון דכי אין לו בשר דהיתרא אוכל חלב ונבילה ונתחלף לזה שומן בחלב ואכלו דסבור דשומן הוא ואכלו קמיפלגי ולכשנודע לו דחלב הוא רוצה להקריב קרבן ת\\\"ק סבר כיון דלתיאבון אכיל במזיד מומר הוא ואין מקבלין מידו ופסק רבינו כת\\\"ק וכאוקימתא דרבא:\",2,0],[8,363,3,5,\"עולות הנכרים אין מביאין עמהם נסכים וכו'. בפרק אלו מנחות (מנחות דף ע״ג:) כמאן אזלא הא דתנן אמר ר״ש שבעה דברים התקינו ב״ד וזה אחד מהם נכרי ששלח עולתו ממדינת הים אם שלח עמה נסכיה קרבים משלו ואם לאו קרבים משל ציבור לימא ר״י הגלילי היא ולא ר״ע אפילו תימא ר״ע עולה וכל חבירתה מאן תנא להא דתנו רבנן אזרח אזרח מביא נסכים ואין הנכרי מביא נסכים יכול לא תהא עולתו טעונה נסכים ת״ל ככה מני לא ר״י הגלילי ולא ר״ע אי ר״י הגלילי הא אמר אפילו יין נמי אי ר״ע הא אמר עולה אין מידי אחרינא לא אי בעית אימא ר״י הגלילי סמי מההיא יין ואי בעית אימא ר״ע עולה וכל חבירתה ופירש״י אפילו תימא ר״ע דהא דאמר ר״ע דאין נודרין אלא עולה עולה וכל חבירתה דהיינו נסכים אבל נסכים לחודייהו לא וכבר קדם שרבינו פסק כר״ע ולא הבנתי דעת רבינו דאי ס״ל דהנך מתנייתא כר״ע ועולה וכל חבירתה קאמר ה״ל למיפסק דמביאין נסכים משלהם עם עולותיהם ואם לא שלחו עמהם נסכים יקרבו משל ציבור ואי ס״ל דהא דשנינן דר״ע עולה וכל חבירתה קאמר שינויא דחיקא הוא אבל קושטא דמילתא היא דר״ע עולה דוקא קאמר א״כ אפי' משל ציבור נמי לא ליתו. ושמא יש לומר דרבינו ספוקי מספקא ליה ומש״ה לפוטרן בלא נסכים א״א דדילמא ר״ע עולה וכל חבירתה קאמר ולומר שיביאום משלהם א״א דדילמא ר״ע עולה דוקא קאמר ומש״ה פסק שלא יביאו משלהם אלא משל ציבור. והר״י קורקוס כתב שרבינו סמך על המשנה וברייתא שבריש תמורה (דף ב':) והסוגיא שעליה כי שם אמרו בברייתא קדשי נכרים לא נהנים וכו' ואין מביאין עליהם נסכים ובמשנה (דף ק״ג) אמרו ואין מביאין עליהם נסכים ואמרו מנה״מ דת״ר אזרח אזרח טעון נסכים וכו' ולפי אותה סוגיא על כרחין צריכין אנו לפרש דלגמרי ממעט שאין הנכרי מביא נסכים שהרי במשנה אמרו דאין מביאין עליהם דהיינו עם העולות ויליף לה מברייתא מוכח דאזרח לגמרי ממעט ויכול לא תהא עולתו טעונה אפי' משל צבור קאמר וכן פי' רש״י שם לפי אותה גירסא דגריס במשנה עליהם והיא גירסת רבינו והאריך לתת טעם למה סמך רבינו על אותה משנה ואותה סוגיא ולא על משנת שקלים וסוגיית מנחות.\",1,0],[8,363,3,5,\"ומ״ש ואינן טעונות סמיכה שאין סמיכה אלא בישראל באנשים ולא בנשים. משנה בס״פ שתי מדות (מנחות דף צ״ג) ויליף לה בגמרא מדכתיב גבי סמיכה בני ישראל:\",2,0],[8,363,3,6,\"כל קרבנות בהמה שיקריב היחיד וכו' סומך עליהם כשהם חיים חוץ מן הבכור והמעשר והפסח וכו'. גם זה משנה שם (דף צ\\\"ב):\",1,0],[8,363,3,7,\"ומה שכתב העוף אינו טעון סמיכה. הכי משמע בפרק כל הגט (גיטין דף כ״ח:) על מתניתין דהשולח חטאתו ממדינת הים:\",1,0],[8,363,3,7,\"וכן כל המעות שדינם שיפלו לתיבות של נדבה וכו' אין בעל אותם המעות וכו' עד של אנשי משמר. משנה בסוף פרק שלישי דתמורה (דף כ').\",2,0],[8,363,3,7,\"ומה שכתב אם היה כהן. לשון המשנה ואף על פי שהוא כהן וכך נראה לי להגיה בלשון רבינו אף על פי במקום אם:\",3,0],[8,363,3,8,\"הכל סומכין חוץ מחרש שוטה וקטן וכו' עד ולא יד שלוחו. בסוף פרק שתי מדות (מנחות דף צ\\\"ג):\",1,0],[8,363,3,9,\"חמשה שהביאו זבח אחד כולם סומכים עליו. משנה שם (דף צ\\\"ד).\",1,0],[8,363,3,9,\"ומה שכתב זה אחר זה וכו'. בתוספתא דמנחות פ\\\"י:\",2,0],[8,363,3,9,\"מי שמת והניח קרבנו עולה וכו'. משנה בס״פ שתי מדות (מנחות דף צ״ב) ואע״ג דאמרי' בריש תמורה דר' יהודה סבר דיורש אינו סומך כיון דסתם לן תנא התם ובפרק שתי מדות ובריש ערכין דלא כוותיה נקטינן כסתם מתניתין:\",3,0],[8,363,3,10,\"אין סמיכה בקרבנות הצבור וכו'. משנה פרק שתי מדות.\",1,0],[8,363,3,10,\"ומ\\\"ש ושלשה מן הסנהדרין סומכין. בפ\\\"ק דסנהדרין (דף ב') סמיכת זקנים בשלשה.\",2,0],[8,363,3,10,\"ומ\\\"ש ודבר זה הלכה מפי משה רבינו שאין בצבור אלא שתי סמיכות. בס\\\"פ שתי מדות שם:\",3,0],[8,363,3,11,\"אין סומכין אלא בעזרה. ברפ\\\"ג דזבחים.\",1,0],[8,363,3,11,\"ומ\\\"ש סמך חוץ לעזרה חוזר וסומך מבפנים. ומ\\\"ש ואם היה בעל הקרבן עומד בחוץ וכו'. ברפ\\\"ג דזבחים (דף ל\\\"ג) איכא דאמרי אמר רב יוסף כל הסומך ראשו ורובו מכניס מ\\\"ט כל כחו בעינן.\",2,0],[8,363,3,11,\"ומ\\\"ש ואין סומך אלא הטהור ואם סמך הטמא סמך. ברפ\\\"ג דזבחים (דף ל\\\"ב) אהא דתנן שהשחיטה כשרה בטמאים ורמינהי וסמך ושחט מה סמיכה בטהורים אף שחיטה בטהורים מדרבנן. ומשמע לרבינו דאסמיכה נמי קאי ומש\\\"ה אם סמך סמך ואפי' את\\\"ל שסובר דסמיכה בטהורים כשסמכו טמאים אפי' אם נאמר דלא הויא סמיכה הא אמרן שאם לא סמך כפר:\",3,0],[8,363,3,12,\"במקום שסומכין שוחטין ותיכף לסמיכה שחיטה. משנה בס\\\"פ שתי מדות ובגמרא מאי קאמר ה\\\"ק במקום שסומכין שוחטין שתיכף לסמיכה שחיטה ולא ידעתי למה לא כ\\\"כ רבינו.\",1,0],[8,363,3,12,\"ומ\\\"ש ואם שחט במקום אחר או ששהא שחיטתו כשירה. נלמד ממ\\\"ש לקמן בסמוך.\",2,0],[8,363,3,12,\"ומ\\\"ש והסמיכה שיירי מצוה היא וכו' עד כאלו לא כפר. משנה וברייתא בס\\\"פ שתי מדות ואיתיה בריש זבחים (דף ו') ויליף לה מקרא בריש יומא (דף ה'):\",3,0],[8,363,3,13,\"וצריך הסומך לסמוך בכל כחו. כבר כתבתי דאיתיה בריש פ\\\"ג דזבחים.\",1,0],[8,363,3,13,\"ומ״ש בשתי ידיו על ראש הבהמה וכו' עד בין ידיו ובין הבהמה. בס״פ שתי מדות (מנחות צ״ג:):\",2,0],[8,363,3,14,\"וכיצד סומך וכו'. משנה בפ\\\"ג דיומא (דף ל\\\"ה:).\",1,0],[8,363,3,14,\"ומ\\\"ש ומתודה על חטאת עון חטאת וכו'. שם ובתוספתא דמנחות פ\\\"י וכר\\\"ע:\",2,0],[8,363,3,15,\"היה הקרבן שלמים וכו' עד סוף הפרק. פשוט הוא:\",1,0],[8,363,4,1,\"כל הקרבנות אין מקריבין אותם אלא ביום שנאמר ביום צוותו את בני ישראל וכו'. בכמה מקומות מהם פרק דם חטאת (זבחים צ\\\"ח).\",1,0],[8,363,4,1,\"ומ״ש וכיון ששקעה החמה נפסל הדם. מימרא בפרק איזהו מקומן (זבחים דף נ״ו):\",2,0],[8,363,4,2,\"כל שקרבו מתיריו ביום מעלין אותו וכו'. מקרא מלא הוא היא העולה על מוקדה על המזבח כל הלילה וכו'. בפ\\\"ג דמנחות (דף כ\\\"ו) תניא אין לי אלא דברים שדרכן ליקרב בלילה כגון איברים ופדרים מעלן ומקטירן מבוא השמש ומתעכלין והולכים כל הלילה ופירש\\\"י אברי עולה התירן הכתוב בלילה דכתיב על מוקדה וכו' ואברים ופדרים מהאי קרא גופיה נפקי.\",1,0],[8,363,4,2,\"ומה שכתב וכדי להרחיק את האדם מפשיעה אמרו חכמים וכו' עד אלא עד חצות הלילה. משנה ברפ\\\"ק דברכות:\",2,0],[8,363,4,3,\"אע״פ שמותר להקטיר וכו' עד למוצאי שבת. במנחות פ' ר' ישמעאל (מנחות דף ע״ב) ובתוספתא דערכין ספ״ב:\",1,0],[8,363,4,4,\"כל דבר שאינו קרב אלא ביום וכו' מותר להקריבן עם מבוא השמש וכו'. ברייתא בפ' הקומץ רבה (מנחות דף כ״ו:) וברפ״ב דתמורה (דף י״ד) תניא אין לי אלא דברים שדרכן ליקרב בלילה כגון איברים ופדרים שמעלן מבוא השמש ומתעכלין והולכין כל הלילה כולו דברים שדרכן ליקרב ביום כגון הקומץ והלבונה והקטרת ומנחת כהנים ומנחת כהן משיח ומנחת נסכים שמעלן ומקטירן וכו' עם בוא השמש שמתעכלין והולכין כל הלילה מנין ת״ל זאת תורת העולה ריבה. ופירש״י אין לי אעל המזבח כל הלילה קאי. מבוא השמש אחר בוא השמש. קומץ ולבונה וכל הקרבנות דרכן ליקרב ביום דנפקא לן מביום צוותו בת״כ ולא יצא מאותו כלל אלא איברי עולה שהתירן הכתוב בלילה דכתיב על מוקדה וכו'. אברים ופדרים שדרכן ליקרב בלילה מהאי קרא גופיה נפקא בת״כ עם בוא השמש קודם בוא השמש:\",1,0],[8,363,4,5,\"הנסכים הבאים עם הזבח וכו' אבל הנסכים הבאים בפני עצמם וכו' עד כאיברי העולות. בפ\\\"ב דתמורה שם. ביאור הדברים מקדישן לכתחלה בלילה בכלי שרת ומקריבן בלילה ואם הקדישן בכלי שרת בלילה ולא הקריבן עד שעלה השחר עלות השחר פוסלת בהם:\",1,0],[8,363,4,6,\"כל היום כשר לסמיכה וכו' עד כשר כל הלילה. משנה בספ\\\"ב דמגילה (דף כ':).\",1,0],[8,363,4,6,\"ומ\\\"ש ואעפ\\\"כ זריזין מקדימין למצות. בפרק קמא דפסחים (דף ד'):\",2,0],[8,363,4,7,\"כל הזבחים אין שוחטין אותן לכתחלה אלא בסכין מכלי שרת. בס״פ דם חטאת (זבחים דף צ״ז:) ובס״פ התודה (מנחות דף פ״ב:) ומייתי לה מדכתיב ויקח את המאכלת והתם עולה הוה דכתיב ויעלהו לעולה תחת בנו.\",1,0],[8,363,4,7,\"ומ״ש ואם שחט בכל דבר ששוחטין בו החולין אפילו בקרומית של קנה כשרים. אהא דתנן בר״פ כל הפסולים (זבחים דף ל״א:) שהשחיטה כשירה בטמאים פירש״י בטמא שרץ קאמר שאינו מטמא כלי דלאו אב הטומאה הוא או בטמא מת וכגון שבדק בקרומית של קנה ושחט בה אבל בסכין לא שהוא מטמא את הסכין והסכין מטמא את הבשר והם דברי הגמ' בריש חולין (דף ב':) והקשו התוספות דהא בעינן כלי ותירצו כגון דתיקנה לקרומית ועבדה כעין כלי. ורבינו סובר דלא בעי כלי אלא לכתחלה:\",2,0],[8,363,4,8,\"כל הזבחים שקיבל מדמם פחות מכדי הזיה לא נתקדש הדם. בפ\\\"ק דמנחות (דף ז':):\",1,0],[8,363,4,8,\"וצריך להתכוין לקבל כל הדם. מימרא בפרק שני דזבחים (דף כ\\\"ה) אמר רב יהודה אמר רב השוחט צריך שיקבל כל דמו של פר.\",2,0],[8,363,4,8,\"ומ\\\"ש כיצד הוא עושה אוחז הסימנין בידו ומוציאן עם הורידין לתוך המזרק. שם א\\\"ר ירמיה בר אבא השוחט צריך שיתן ורידין לתוך הכלי.\",3,0],[8,363,4,8,\"ומ״ש ושוחט שנים או רוב שנים. בריש פ' השוחט (חולין דף כ״ז).\",4,0],[8,363,4,8,\"ומה שכתב ומגביה הסכין למעלה וכו'. פ' שני דזבחים (דף כ\\\"ה) אמר רב יהודה אמר שמואל השוחט צריך שיגביה סכין למעלה שנאמר ולקח מדם הפר ולא דם הפר ודבר אחר.\",5,0],[8,363,4,8,\"ומ\\\"ש ודם שבסכין מקנחו בשפת המזרק. גם זה שם פירוש בשפת המזרק מאחוריו שלא יכנס דם במזרק:\",6,0],[8,363,4,9,\"ומ\\\"ש אויר כלי הרי הוא ככלי היה מקבל הדם ונפחתו שולי המזרק וכו' שם בעיי דאיפשיטו:\",1,0],[8,363,4,10,\"כל הזבחים צריך העובד שתהיה מחשבתו לשם הזבח וכו'. בריש זבחים תנן כל הזבחים שנזבחו שלא לשמן כשרים אלא שלא עלו לבעלים לשם חובה חוץ מן הפסח והחטאת, ומשמע בגמ' דהאי שלא לשמן היינו בין בשינוי קדש בין בשינוי בעלים ויליף בגמרא דבכל ד' עבודות אלו צריך שלא ישנה בקדש ולא בבעלים.\",1,0],[8,363,4,10,\"ומ\\\"ש רבינו ואם שחט ועבד שאר עבודות סתם ולא חשב כלל וכו'. שם בגמרא דייק טעמא דשלא לשמן הא סתמא עלו לבעלים לשם חובה אלמא סתמא נמי כלשמן דמי משום דזבחים בסתם לשמן עומדים. ואם כן יש לתמוה על רבינו למה כתב בעולה ובשלמים וכו' דמשמע דדוקא הני עלו לבעלים לשם חובה ולא חטאת ופסח והא ליתא דבכולהו סתמן כלשמן דמי ועלו לבעלים לשם חובה וצ\\\"ע:\",2,0],[8,363,4,11,\"ומ\\\"ש וצריך שתהיה מחשבתו בשעת שחיטת העולה לשם הזבח ולשם הזובח וכו'. משנה בס\\\"פ ב\\\"ש (זבחים מ\\\"ו:) לשם ששה דברים הזבח נזבח לשם זבח לשם זובח לשם השם לשם אישים לשם ריח לשם ניחוח וחטאת ואשם לשם חטא. ופירש\\\"י לשם זובח לאפוקי שינוי קדש כגון לשם זבח אחר. לשם זובח לאפוקי לשם שינוי בעלים. ובגמ' לשם אישים לאפוקי כבבא ופירש\\\"י כבבא על מנת לעשותו חתיכות צלויות בגחלים. לשם ריח לאפוקי אברים שצלאן ואח\\\"כ העלן. לשם ניחוח לשם נחת רוח לפני הקב\\\"ה שאמר ונעשה רצונו.\",1,0],[8,363,4,11,\"ומ\\\"ש ואם שחט סתם כשר. כבר נתבאר.\",2,0],[8,363,4,11,\"ומ\\\"ש והשוחט חטאת ואשם וכו'. במשנה שכתבתי בסמוך:\",3,0],[8,363,5,1,\"כבר ביארנו ששחיטת הקדשים כשירה בזרים וכו'. בר״פ כל הפסולים (זבחים דף ל״א:).\",1,0],[8,363,5,1,\"ומה שכתב וכל הזבחים קבול דמן בכלי שרת וכו' כיצד קדשי קדשים וכו'. בריש פ' איזהו מקומן (זבחים דף מ״ז):\",2,0],[8,363,5,2,\"ומ\\\"ש בכל המקום שביארנו גבולותיו בתחלת ספר זה. בפרק ה' מהלכות בית הבחירה.\",1,0],[8,363,5,2,\"ומ״ש וקדשים קלים שחיטתן וקיבול דמן בכל מקום מן העזרה. בפ' איזהו מקומן (זבחים דף נ״ה):\",2,0],[8,363,5,3,\"ומ״ש ומנין שאין שוחטין קדשי קדשים אלא בצפון וכו' עד ישחטו את האשם. בר״פ איזהו מקומן (זבחים דף מ״ז ומ״ח). ויש לשאול למה הוצרך רבינו לכתוב וכשם שהחטאת נקראת קדש קדשים כך העולה שהרי בלאו הכי יש ראיה שנשחטה בצפון. וי״ל שלא הוצרך לכתוב כן אלא כדי שיצדק השם שכתב לנשחטין בצפון שהם קדשי קדשים:\",1,0],[8,363,5,3,\"ומ״ש ושלמי צבור הוקשו לחטאת וכו'. בפרק איזהו מקומן (זבחים דף נ״ה) מקשה על ראיה זו וכי חטאת מהיכן למדה מעולה דבר הלמד בהיקש חוזר ומלמד בהיקש אלא מדתני רב מרי על עולותיכם ועל זבחי שלמיכם מה עולה קדש קדשים אף זבחי שלמי ציבור קדשי קדשים מה עולה בצפון אף זבחי שלמי ציבור בצפון. ויש לתמוה למה הניח רבינו פסוק שהוקשו לעולה והביא פסוק שהוקשו לחטאת דדחינן ליה בגמרא. ושמא יש לדחוק ולומר דהשתא דאתא קרא דהיקשא דלעולה מהיקשא דחטאת נמי גמרינן וכיון דעיקר שם קדש קדשים בחטאת הוא דכתיב מש״ה נקט היקשא דחטאת. ועי״ל דלפום מאי דאסיק אדעתיה דחטאת למדה מעולה בהקש אתיב ליה אלא כדתני רב מרי אבל לפי האמת לא למדה בהיקש אלא כאילו כתיב בחטאת גופיה בהדיא הוא דהא מפורש דבר הכתוב במקום אשר תשחט העולה תשחט החטאת והוי כאילו כתוב תשחט החטאת בצפון.\",2,0],[8,363,5,3,\"ומה שכתב מקום השחיטה הוא מקום הקבלה. בריש פרק איזהו מקומן (זבחים דף מ״ט) קבלה בצפון מנא לן דכתיב ולקח הכהן מדם החטאת כלומר וילפינן שאר קדשי הקדשים מחטאות. ופירש״י ולקח הכהן בתר ושחט כתיב ומשמע במקום העולה נמי והך לקיחה קבלה היא דגמר בג״ש בתורת כהנים עכ״ל. ואיני יודע למה השמיט רבינו ראיה זו:\",3,0],[8,363,5,4,\"ומנין ששוחטין קדשים קלים בכל העזרה אפי' אחורי ההיכל וכו'. שם (דף נ\\\"ה) ת\\\"ר ושחטו פתח אהל מועד ושחט אותו לפני אהל מועד ושחט אותו לפני אהל מועד להכשיר כל הרוחות בקדשים קלים ק\\\"ו לצפון ומה קדשי קדשים שלא הוכשרו בכל הרוחות הוכשרו בצפון קדשים קלים שהוכשרו בכל הרוחות אינו דין שהוכשרו בצפון ומפרש בגמרא דהני תלתא קראי חד לגופיה דניבעי פתח אהל מועד כדלקמן בסמוך וחד להכשיר צדדין וחד לפסול צידי צדדין וצפון לא איצטריך קרא. ופירש רש\\\"י לפני משמע כל שלפני ההיכל. וחד להכשיר צדדין כל רוחב העזרה דלא תימא כנגד הפתח דוקא להכי הדר כתב לפני ולא כתב פתח וכל האויר בכלל לפני דלא כתב כנגד. וחד לפסול צידי צדדין כגון לשכות ואפי' תוכן קדש פסולות לשחיטה דלא תימא מדפתח לאו דוקא לפני נמי לאו דוקא. ודברי רבינו שכתב שהרי נאמר בשלמים ושחטו פתח אהל מועד להכשיר כל הרוחות נראה שהוא טעות סופר דהא מהאי קרא לא ילפינן אלא דניבעי פתח אהל מועד לכך נ\\\"ל שצריך להגיה ולכתוב ושחט אותו לפני אהל מועד. ומכל מקום מה שכתב רבינו אפילו אחורי ההיכל צריך למוד מנין לו [עיין תוספות יום טוב זבחים פ\\\"ה מ\\\"ז דכך נתבאר להדיא בסוגיין דזבחים נ\\\"ה].\",1,0],[8,363,5,4,\"ומה שכתב ואם שחטן בהיכל כשרים. בפרק קדשי קדשים (זבחים דף ס״ג) אמר רבי יוחנן שלמים ששחטן בהיכל כשרים שנאמר ושחטו פתח אהל מועד ולא יהא טפל חמור מן העיקר.\",2,0],[8,363,5,4,\"ומ״ש אבל אם שחטן בגגו של היכל פסולים שאין הגגות ראויות לשחיטה כלל וכו'. בפרק כיצד צולין (פסחים דף פ״ה:) אמר רב גגין ועליות לא נתקדשו ואע״ג דמתיב עליה מדתניא שעלית בית קדשי הקדשים מקודשת ושני שאני היכל דכתיב ויתן דוד לשלמה בנו את תבנית האולם וגו' ועליותיו וגו' וכתיב הכל בכתב מיד ה' עלי השכיל אלמא עליות ההיכל נתקדשו ומשמע דה״ה לגגו, י״ל דשאני עליות שנזכרו בכתוב אבל גג שלא הוזכר בכתוב גם הוא בכלל מה שאמר רב גגין לא נתקדשו.\",3,0],[8,363,5,4,\"ומ\\\"ש אלא בקרקע העזרה. כתב כן למעט עליות. אחר כך מצאתי בפרק שני דזבחים אמר עולא השוחט על גגו של היכל חייב משום שחוטי חוץ הואיל ואין ראוי לשחיטת כל זבח וזה מבואר מדברי רבינו שאין גגו של היכל כשר לשחיטת שום זבח:\",4,0],[8,363,5,5,\"שלמים ששחטן קודם שיפתחו דלתות ההיכל פסולים וכו'. מימרא בפרק איזהו מקומן (זבחים דף נ״ה:).\",1,0],[8,363,5,5,\"ומ\\\"ש אפי' היו דלתותיו מוגפות. שם ופירש\\\"י מוגפות סגורות ולא נעולות.\",2,0],[8,363,5,5,\"ומ\\\"ש אבל הפרוכת שעליו אינה פוסלת. שם בעיא דאיפשיטא:\",3,0],[8,363,5,6,\"העולה והאשם והשלמים וכו'. בשלשתן שנינו בפרק איזהו מקומן דמן טעון שתי מתנות שהן ד' ואיפליגו תנאי בפירושה ופסק כת\\\"ק דאמר (דף נ\\\"ג:) יכול יזרקנו זריקה אחת ת\\\"ל סביב אי סביב יכול יקיפנו בחוט ת\\\"ל וזרקו הא כיצד כמין ג\\\"ם ופירש\\\"י כמין ג\\\"ם זורק כנגד הפינה מן הכלי והדם מתפשט לשתי רוחות הפינה והרי היא כמין ג\\\"ם אות יונית עשויה ככ\\\"ף פשוטה. ואע\\\"ג דרב ושמואל פליגי התם ואתי שמואל כת\\\"ק ומשמע דרב סבר דלית הלכתא כת\\\"ק וא\\\"כ לא ה\\\"ל למיפסק כשמואל לגבי רב באיסורי י\\\"ל דברייתא לא הוה שמיע לרב דאי הוה שמיע ליה לא הוה פליג את\\\"ק.\",1,0],[8,363,5,6,\"ומ\\\"ש רבינו מחצי המזבח ולמטה. בריש קינים עולת בהמה למטה ואם שינה פסול פירוש למטה מחוט הסיקרא שחוגר באמצע המזבח:\",2,0],[8,363,5,6,\"ומ\\\"ש על קרן מזרחית צפונית וכו'. שם אהא דתנן בעולה דטעונה שתי מתנות שהן ארבע פירש\\\"י שתי מתנות בקרן מזרחית צפונית ובקרן מערבית דרומית שכנגדה באלכסון והכי תנן במסכת תמיד בא לו לקרן מזרחית צפונית נותן מזרחה צפונה מערבית דרומית נותן מערבה דרומה וטעמא משום דקרן מזרחית דרומית לא היה לה יסוד כדאמרינן בשמעתין ועולה טעונה מתן דמה כנגד היסוד וכדרבינן לעיל.\",3,0],[8,363,5,6,\"ומ\\\"ש וה\\\"ה לאשם. כלומר שגם הוא נאמר בו סביב בפ' צו.\",4,0],[8,363,5,6,\"ומ\\\"ש ושירי הדם נשפכים על גג היסוד הדרומי. שם (דף נ\\\"ב) אמאי דכתיב בפר כהן משיח ואת כל דם הפר ישפוך אל יסוד מזבח העולה דריש דה\\\"ק תן יסוד למזבח של עולה ופירש\\\"י תן יסוד למזבח של עולה תן תורת שפיכת יסוד שירים להלכות מזבח של עולה שיהא המזבח טעון בעולה ובכל הדמים הניתנין עליו שפיכת שירים אל היסוד אם נשאר בכלי כלום כשזורק ממנו שתי זריקות לשתי קרנות ישפכנו ליסוד ומשום דבעולה לא כתיבי שפיכת שירים איצטריך למילף מהכא. ואמרינן תו התם השתא דכתיב אל יסוד מזבח העולה אגגו דיסוד ופירש\\\"י השתא דכתיב אל יסוד המזבח יסוד שהוא דומה למזבח דהיינו גגו של יסוד:\",5,0],[8,363,5,7,\"החטאות הנאכלות דמן וכו'. משנה בפרק איזהו מקומן.\",1,0],[8,363,5,7,\"ומה שכתב מחצי מזבח ולמעלה וכו'. בריש קנים חטאת בהמה נעשית למעלה ואם שינה פסל.\",2,0],[8,363,5,7,\"ומ״ש וכיצד הוא עושה כשלוקח הכהן הדם במזרק וכו'. ברייתא בפרק איזהו מקומן (זבחים דף נ״ג).\",3,0],[8,363,5,7,\"ומ\\\"ש וסומך באצבעו הגדולה מכאן. שם וחומר בגודל מלמעלה ובאצבע קטנה מלמטה ורבינו גורס גדולה במקום קטנה. אי נמי קטנה בערך הגודל קאמר. ונראה שמפרש רבינו חומר צובר מלשון חומרים כלומר שמעמיד הדם שיהיה צבור ולא יתפשט באצבע.\",4,0],[8,363,5,7,\"ומ\\\"ש ומחטא ויורד כנגד חודה של קרן וכו'. שם ופירש\\\"י ומחטא זריקת חטאת קרוי חיטוי כמו הכהן המחטא.\",5,0],[8,363,5,7,\"ומ\\\"ש ואם נתן סמוך לקרן כאמה אחת מכאן ואמה אחת מכאן כפר. שם אמאי דתנן חטאות הצבור והיחיד דמן טעון ארבע מתנות על ארבע קרנות אמרינן בגמרא היכי עביד ר' יוחנן ור' אלעזר חד אמר נותן אמה אילך ואמה אילך וחד אמר מחטא ויורד כנגד חודו של קרן אליבא דרבי אליעזר ברבי שמעון דאמר היא עצמה אינה נעשית אלא בגופה של קרן דכולי עלמא לא פליגי כי פליגי אליבא דרבי (דאמר דמים העליונים ניתנין מחוט הסיקרא ולמעלה) מר סבר אמה אילך ואמה אילך כנגד קרן הוא ומר סבר כנגד חודה אין טפי לא. ופי' רש\\\"י היא כלומר כל עצמה ועיקר מצותה אינו אלא שם. דכ\\\"ע לא פליגי דלא בעינן חודה דקרן כתיב ואמה על אמה ברום אמה הניתן בראש המזבח בכל זוית וזוית בכל מקום שבה קרוי קרן כי פליגי אליבא דרבי דמכשיר לה מחוט הסיקרא ולמעלה ואע\\\"ג דלאו קרן מר סבר כי היכי דקרן היא אמה על אמה אף כל שתחתיו כנגדו הוי קרן ומר סבר כיון דקרא לאו אקרנות ממש קפיד דשאר המזבח לא שייך לשון קרן אלא בחודה של זוית עכ\\\"ל. ולפי זה פסק רבינו כרבי דהלכה כמותו מחבירו ועוד דאמוראי פליגי אליביה ובפלוגתא דאמוראי פסק כמאן דאמר אמה אילך ואמה אילך. ונראה לי שהטעם דכיון דלר' אליעזר בר\\\"ש לא בעינן חודה של קרן עדיף טפי למימר דרבי מכשיר באמה אילך ואמה אילך כדי שלא להגדיל מחלוקתם ביותר. ועוד יש לומר דכיון דאיפליגו אמוראי במילתא אין אנו יכולים לפסול באמה אילך ואמה אילך ומש\\\"ה פסק דלכתחלה בעינן חודה של קרן ואם נתן אמה אילך ואמה אילך בדיעבד כפר:\",6,0],[8,363,5,8,\"ומ״ש וצריך לטבול אצבעו על כל קרן וקרן וכשגומר הנתינה על הקרן מקנח אצבעו בשפת המזרק וכו'. בפרק דם חטאת (זבחים דף צ״ג:) תניא וטבל [ולא מספג וכו'] (והזה מן הדם) מן הדם שבענין למעוטי מאי למעוטי שירים שבאצבע. ופירש״י והזה מן הדם שבענין מדם האמור בענין טבילה שהזה ממנו ראשונה יזה את כולן שצריך לחזור לטבול בו אצבעו על כל הזיה טבילה.\",1,0],[8,363,5,8,\"ומ\\\"ש מקנח אצבעו בשפת המזרק. שם:\",2,0],[8,363,5,9,\"אין בכל הקרבנות קרבן וכו'. איני יודע מה מלמדנו.\",1,0],[8,363,5,9,\"ומ״ש וצריך שיהא שם דם כדי טבילה לא שיספג אצבעו מדם. ברייתא בפרק ב״ש (זבחים דף מ':) ובפרק דם חטאת וטבל ולא מספג דם עד שיהא בדם שיעור טבילה מעיקרו ופירש״י מספג מקנח בשולי הכלי או בדפנותיו וכו'. שיעור טבילה מעיקרא וכו' משעת קבלה ראשונה למעוטי קבל פחות מכדי טבילה בכלי זה ופחות מכדי טבילה בכלי זה ועירבן והכי מפרש לה במנחות ובפרק דם חטאת ויליף לה מדקרינן וטבל בדם ולא קרינן בדם משמע בדם שהיה כבר משעה ראשונה עכ״ל. ומפשט דברי רבינו לא משמע הכי אלא כולה חדא מילתא היא וה״ק צריך שיהא שם כדי טבילה כדי שלא יהא מספג שאם לא יהא שם דם כדי טבילה נמצא שהוא מספג ואנן בעינן וטבל. ויש לתמוה דאי חדא מילתא היכי דריש ולא מספג מוטבל ושיהא בדם שיעור טבילה מבדם ועוד דבגמרא מצריך להו דאי כתב רחמנא וטבל ה״א אע״ג דליכא שיעור טבילה מעיקרו ואי כתב רחמנא בדם הו״א אפילו מספג אלמא תרי מילי נינהו לפיכך צריך לפרש דברי רבינו דתיבת וצריך מושך עצמו ואחר עמו וה״ק וצריך שיהא שם דם כדי טבילה וכן צריך עוד שלא יספג:\",2,0],[8,363,5,10,\"ומנין הוא מתחיל וכו'. משנה בפ' איזהו מקומן (זבחים דף נ״ג).\",1,0],[8,363,5,10,\"ומ\\\"ש זה יסוד דרומי. בגמ' יליף לה.\",2,0],[8,363,5,10,\"ומ\\\"ש שנאמר ואת כל דמה ישפוך אל יסוד מזבח העולה. נראה להגיה ולכתוב במקומו ואת כל דמה ישפוך אל יסוד המזבח וכן נמצא בספר מוגה דבחטאות פנימיות כתיב אל יסוד מזבח העולה אשר פתח אהל מועד והוא מערבי שפוגע בו תחלה בצאתו אבל בחיצוניות כתיב אל יסוד המזבח ולכך פנימיות מפורש וחיצוניות סתום:\",3,0],[8,363,5,11,\"כל החטאות הנשרפות וכו' ושירי הדם היה שופך על יסוד מערבי של מזבח החיצון וכו'. שם במשנה (דף מ\\\"ז) שיירי הדם היה שופך על יסוד מערבי של מזבח החיצון ובגמרא (דף נ\\\"ב) מ\\\"ט א\\\"ק אל יסוד מזבח העולה אשר פתח אהל מועד ההוא דפגע ברישא ופירש\\\"י יסוד שכנגד הפתח וזו היא מערבו של מזבח שהוא כנגד פתח ההיכל:\",1,0],[8,363,5,12,\"והיכן מזין מדמן וכמה מזה מהן וכו'. כמו שיתבאר בהל' עבודת יוה\\\"כ פ\\\"ד:\",1,0],[8,363,5,12,\"ומ״ש ואם לא כיון בהזיות שבפנים כשרות. פ' הקומץ רבה (מנחות דף כ״ז):\",2,0],[8,363,5,13,\"פרים הנשרפין ושעירים הנשרפין וכו'. מפורש בתורה:\",1,0],[8,363,5,14,\"ומ\\\"ש וכל הדמים הניתנין על מזבח הזהב וכו'. כתוב בתשובת הרשב\\\"א בסימן ש\\\"צ שנשאל על מ\\\"ש רבינו שהיה עומד בין מזבח למנורה והלא המזבח משוך היה כלפי חוץ והוא צריך לצאת מכל המזבח ותשובתו כתבתי בהל' עבודת יוה\\\"כ פ\\\"ד. והר\\\"י קורקוס כתב אפשר שרבינו מפרש עד דנפק מכוליה היינו שלא יעמוד בין מזבח לפרוכת אלא יוצא לצד ימינו עד שיצא מכנגד כל המזבח וזהו שכתב בין מזבח למנורה ונמצא עומד מהמזבח ולפנים מכנגד הצד הדרומי כמ\\\"ש בפ\\\"ד מהל' עבודת יוה\\\"כ כי מצד צפון יוצא. ועדיין קשה שא\\\"כ למה אינו נותן תחלה בקרן דרומית מערבית שהוא יותר קרוב לו שהרי מנורה בדרום היתה לימין היוצא נמצא שזה מדלג קרן דרומית מערבית ודרומית מזרחית ונותן בשלישי שהוא צפונית ולמה, ואפשר שסובר רבינו שזהו מ\\\"ש שנותן מבחוץ כלומר לצד האחר וזהו שאמר שיהו הזאות אלו הראשונות מלמטה למעלה כי אולי יתלכלכו בגדיו אבל האחרונה שהיתה לפניו מלמעלה למטה כדי שלא יתלכלכו בגדיו וכמ\\\"ש שם וכתבו רבינו בעבודת יוה\\\"כ ומשם כתב רבינו כן.\",1,0],[8,363,5,14,\"ומ\\\"ש שם לפני ה' מזבח לפני ה' ולא כהן היינו שלא יפסיק הכהן בין מזבח לפרוכת אבל עדיין אין מזבח בין כהן לפרוכת כי לצד דרום היה נמשך נמצא מזבח לפני ה' בלא הפסק וכהן אינו לפני ה' רק לצד המנורה או לחוץ יותר ועדיין סוגית הגמרא צריכה יישוב עוד עכ\\\"ל.\",2,0],[8,363,5,14,\"ומ״ש מתחיל מקרן מזרחית צפונית וכו'. משנה פ' הוציאו לו (יומא דף נ״ח):\",3,0],[8,363,5,14,\"וכתוב בתשובות הרשב\\\"א סי' שפ\\\"ח שנשאל שמשנה זו עכ\\\"פ שנויה לדעת ר' יוסי שסובר שלא היתה שם אלא פרוכת אחת ופרופה לצפון לימין הנכנס וכשחוזר מן הפתח למזבח הזהב פוגע תחלה בצפונית ואינו יכול להתחיל שם כדאמרינן. וגמר שאלה זו ותשובתה אכתוב בהלכות עבודת יוה\\\"כ פרק ד':\",4,0],[8,363,5,15,\"פר כהן משיח הבא על כל המצות וכו'. מדכתיב בה ולקח הכהן המשיח מדם הפר והביא אותו אל אהל מועד וכו'.\",1,0],[8,363,5,15,\"ומ\\\"ש ואם קיבל והזה כהן הדיוט כשר. בת\\\"כ פרשת ויקרא:\",2,0],[8,363,5,16,\"שעירי עבודה זרה והם שעירים הנשרפין וכו'. בפרק בית שמאי (זבחים דף מ״א):\",1,0],[8,363,5,17,\"הבכור והמעשר והפסח וכו'. משנה בפרק איזהו מקומן (זבחים דף נ״ו:) ובר״פ ב״ש (זבחים דף ל״ז).\",1,0],[8,363,5,17,\"ומ\\\"ש באי זה רוח שירצה משלש זויות המזבח שהרי קרן מזרחית דרומית לא היה לה יסוד כמו שביארנו. בפ\\\"ב מהל' בית הבחירה:\",2,0],[8,363,5,17,\"ומנין שאינם טעונין אלא מתנה אחת וכו' מפי השמועה למדו שהוא הדין במעשר ופסח וכו'. בפ' ב״ש (זבחים דף ל״ז) ובפרק איזהו מקומן (זבחים דף נ״ו:) מדכתב ואת דמם תזרוק מלשון רבים לימד על בכור ומעשר ופסח שטעונין מתן דמים ואימורין על גבי המזבח כנגד היסוד מנא לן וכו' אתיא זריקה זריקה מעולה. ואיני יודע למה תלה הדבר במפי השמועה דהא מקראי יליף לה מדכתיב דמם לשון רבים. ואפשר שטעמו משום דלא מפרש בהדיא דדמם מרבה מעשר ופסח:\",3,0],[8,363,5,18,\"כל הזבחים מקטירין וכו'. מפורש בתורה:\",1,0],[8,363,5,18,\"וכל הזבחים מפשיטין אותן וכו'. בפרק טבול יום (זבחים דף ק״ג:) נתבאר דכולי עלמא מודו דאין הפשט קודם זריקה וכתב רש״י מפני שאסור לשהות הדם כל כך ובסוף הלכות פסולי המוקדשין כתב רבינו זבח שהופשט קודם זריקה אינו פוסל:\",2,0],[8,363,5,19,\"כל עורות קדשי הקדשים לכהנים וכו' אבל עורות קדשים קלים לבעלים וכו'. משנה בפרק טבול יום (זבחים דף ק״ג):\",1,0],[8,363,5,20,\"כל [קדשי] הקדשים שאירע בהם פיסול וכו'. משנה שם:\",1,0],[8,363,5,20,\"וכל העורות מחלקין אותם כו'. תוספתא בפרק בתרא דמנחות ובגמרא ס״פ מקום שנהגו (פסחים דף נ״ז) ופ' החליל ופ' הגוזל (בבא קמא דף ק״י):\",2,0],[8,363,5,21,\"המתפיס עולתו לבדק הבית וכו' עד אלא ימכרו העורות ויפלו לבדק הבית. בפרק טבול יום (זבחים דף ק״ג:):\",1,0],[8,363,5,21,\"אחד עולת איש וכו'. גם זה שם אלא שבגמ' כתוב גר במקום מ\\\"ש בספרי רבינו עכו\\\"ם. וגירסת רבינו נראית נכונה דלגירסת גמרא דידן קשה מאי קא משמע לן דמהיכא תיסק אדעתין לפלוגי בין גר לישראל:\",2,0],[8,363,6,1,\"מצות עשה לעשות העולה וכו'. פשוט הוא:\",1,0],[8,363,6,3,\"צמר שבראשי כבשים וכו' עד אחר חצות לא יחזיר. משנה וגמרא בפרק המזבח מקדש (זבחים דף פ״ה:) פירש״י אין בהם ממש שנשרפו כולן. ובפרק שני דמעילה (דף ט':) דייק דדוקא פקעו מעל גבי המזבח לא יחזיר הא על גבי המזבח יחזיר:\",1,0],[8,363,6,4,\"כשמנתח איברי העולה וכו'. בפ״ב דיומא (דף כ״ה) תנן הפייס השני מי שוחט וכו' מי מעלה איברים לכבש ובפ״ד דתמיד (דף ל״א:) תנן גבי איברי התמיד הלכו ונתנום מחצי הכבש ולמטה במערבו ומלחום ובפ' הקומץ רבה (מנחות דף כ״א:) תניא שאחד מג' מקומות שהמלח נתון היה על גבי הכבש ששם מולחים האיברים.\",1,0],[8,363,6,4,\"ומ\\\"ש ואחר כך מעלים כל האיברים לראש המזבח. בפ\\\"ב דיומא (דף כ\\\"ו) תנן הפייס הרביעי מי מעלה איברים מן הכבש למזבח ובפ\\\"ה דתמיד תנן אמר להם בואו והפיסו מי מעלה אברים מן הכבש למזבח.\",2,0],[8,363,6,4,\"ומ״ש ומסיר גיד הנשה בראש המזבח ומשליכו ע״ג הדשן שבאמצע המזבח. מימרא בר״פ גיד הנשה (חולין דף צ'):\",3,0],[8,363,6,4,\"ומ״ש וזורק כל האיברים על האש וכו'. כן משמע בסוף מסכת תמיד ובפרק טבול יום (זבחים דף ק״ד) אמרו מה דם בזריקה אף בשר בזריקה.\",4,0],[8,363,6,4,\"ומ\\\"ש ואחר שזרקן חוזר ועורך אותם על האש וכו'. בסיפרא פ\\\"ד.\",5,0],[8,363,6,4,\"ומ״ש ואיברים שצלאן ואחר כך העלן למזבח אין בהם משום ריח ניחוח. מימרא בפרק הקומץ רבה (מנחות דף כ״א):\",6,0],[8,363,6,5,\"כיצד מנתחין את העולה לא היה שובר את הרגל וכו'. במסכת תמיד פ' ד'.\",1,0],[8,363,6,5,\"ומ\\\"ש ואם היה שור מפשיטו בלי תליה. ומ\\\"ש ומפשיט עד שהוא מגיע לחזה וכו' עד הולך ומדיחן. שם. ודע שיש בספרי רבינו חסרון הניכר שאצל מה שכתב וחותך את הידים ונותנן לאחר צריך לכתוב וחותך רגל הימנית ונותנה למי שזכה בראש ושתי ביצים עמה:\",2,0],[8,363,6,6,\"ומ\\\"ש לא ביין ולא במזוג ולא בשאר משקין. בפ\\\"ב דזבחים (דף כ\\\"ב) במים ולא ביין במים ולא במזוג.\",1,0],[8,363,6,6,\"ומ\\\"ש וכל המימות כשרים. שם במים לרבות שאר מים ופירש\\\"י שאר מים ואפילו מכונסים:\",2,0],[8,363,6,6,\"כמה מדיחן הכרס מדיחין אותה בבית המדיחין כל צרכה וכו' עד ונותנו ביד אחר. בפ\\\"ד דתמיד (דף ל\\\"א) ובפ\\\"ב דיומא (דף כ\\\"ה) מייתי לה מקרא ואע\\\"פ ששנו שם שאדם אחר היה נוטל החביתין לא מנאו רבינו מפני שחביתין הללו חביתי כ\\\"ג הן ואינם תלויים בקרבן:\",3,0],[8,363,6,7,\"ומ\\\"ש נוקב את החזה. הטעם ששנינו נוקב מפני שהחזה כאהל על הדפנות וכשנוטלו משם נשאר המקום כחלון כי הוא קצר ונשאר מקומו כנקב. ויש בספרי רבינו ט\\\"ס שכתב ונוקב את הריאה וצריך למחוק תיבת הריאה ולכתוב במקומה החזה גם בג' מקומות כתוב שזרה במקום שדרה:\",1,0],[8,363,6,7,\"ומ\\\"ש עד השדרה. פירוש אצל השדרה כי השדרה היה מניח עד דופן השמאלי. פירוש גרה הוא הצואר על שם כי שם הוא מעלה גרה. ופירוש עוקץ הוא זנב:\",2,0],[8,363,6,11,\"ומ\\\"ש שמוליך הרגל עם הראש. נתבאר טעמו בפ' שני דיומא (דף כ\\\"ה כ\\\"ו):\",1,0],[8,363,6,16,\"ומ\\\"ש אבל אם היה איל מוליכים הקרבים שנים והסלת בשנים. משנה בפרק שני דיומא (דף כ\\\"ו:):\",1,0],[8,363,6,18,\"ומ\\\"ש השור מוליכים אותו כ\\\"ד הראשון מוליך את הראש וכו' עד הרי כ\\\"ד. שם במשנה:\",1,0],[8,363,6,19,\"ומ\\\"ש ולמה לא יחלקו האבר הגדול של שור לחלקים וכו'. סיפרא פ\\\"ה.\",1,0],[8,363,6,19,\"ומ\\\"ש בד\\\"א בעולות וכו'. במשנה:\",2,0],[8,363,6,20,\"עולת העוף כיצד היתה נעשית וכו' עד כל ששינה בה מאחר תמצית הדם כשירה. משנה בפרק קדשי הקדשים (דף ס\\\"ד:).\",1,0],[8,363,6,20,\"ומה שכתב למעלה מן החוט שבאמצע המזבח. בפרק קמא דקינים עולת העוף נעשית למעלה וכו' ואם שינה וכו' פסל:\",2,0],[8,363,6,22,\"ומ\\\"ש ושסע אותו בכנפיו בידו בלא סכין. בפרק קדשי הקדשים (דף ס\\\"ה:) ת\\\"ר ושסע אין ושסע אלא בידו וכן הוא אומר וישסעהו כשסע הגדי:\",1,0],[8,363,6,23,\"כיצד מולקין קוצץ ויורד בצפורן. פרק קדשי קדשים (זבחים דף ס״ה) ובתוספתא דזבחים פ״ז.\",1,0],[8,363,6,23,\"ומ\\\"ש ואם רצה להוליך ולהביא מוליך ומביא. בפרק קמא דחולין (דף כ') פלוגתא דרב הונא ורבה ופסק כרב הונא דרבי אבין ורבי ירמיה סברי הכי.\",2,0],[8,363,6,23,\"ומ\\\"ש ואם רצה להיות דורס ויורד בצפורן דורס. שם אמר רב כהנא מצות מליקה קוצץ ויורד וזו היא מצותה וכו' אמר רבי ירמיה כל שכן דמוליך ומביא כשר ומאי זו היא מצותה אף זו היא מצותה:\",3,0],[8,363,6,23,\"ומ\\\"ש ואם נעקרו הסימנין אינו חושש. שם תני רמי בר יחזקאל אין עיקור סימנים בעוף ופירש רבא בר קיסי דהיינו במליקה ופירש\\\"י דכיון דדרסה וחלדה לא פסלי בה עיקור סימנין נמי לא פסיל בה.\",4,0],[8,363,6,23,\"ומ\\\"ש וחותך שדרה ומפרקת בלא רוב בשר שאם חתך רוב בשר הרי זה כמתה קודם שיגיע לסימנים. שם.\",5,0],[8,363,6,23,\"ומ\\\"ש וצריך לחתוך שני הסימנים בעולה כשהוא יורד. שם פלוגתא דתנאי בברייתא ופסק כתנא קמא.\",6,0],[8,363,6,23,\"ומ\\\"ש והמולק בסכין אינה מליקה. משנה בפרק דם חטאת.\",7,0],[8,363,6,23,\"ומ\\\"ש או מן הצדדין. משנה פרק קמא דחולין (דף י\\\"ט:).\",8,0],[8,363,6,23,\"ומ\\\"ש וכל העורף כשר למליקה. גם זה משנה שם:\",9,0],[8,363,7,1,\"מצות עשה לעשות החטאות כמצותן וכו' כמו שבארנו. בפ\\\"ה:\",1,0],[8,363,7,1,\"ומפשיטה ומפריש האימורים ומולחן וזורקן על גבי האשים ואם רצה ליתן את האימורים בכלי כשמוליכן למזבח נותן. בפ' שני שעירי (יומא דף ס״ז:) אהא דתנן הוציא את אימוריהן ונתנם במגס והקטירם ע״ג המזבח גרסינן בגמ' אטו במגס מקטר ליה אימא להקטירם והכי איתא נמי בפרק שני דסוטה (דף ט״ו) ובפרק תמיד נשחט (פסחים דף ס״ה:) ואע״פ שרש״י מחק גירסא זו התוספות קיימוה ופירשו דהכי פריך וכי חובה הוא שיוליכנו במגס למזבח נהי דכשקרען והוציא אימורין נותנן במגס ולא על גבי רצפה שלא יהו קדשי שמים מוטלים כנבלה מ״מ כשמעלן למזבח יכול להעלותם בידו ומדקתני ליה גבי סדר יוה״כ משמע דכך הוא ובענין אחר אין לעשות ולהכי פריך וכי חובה הוא לעשות כן להעלותם במגס עכ״ל. ונתבארו דברי רבינו:\",2,0],[8,363,7,2,\"וכיצד מעשה וכו' כמו שבארנו. בפ\\\"ה.\",1,0],[8,363,7,2,\"ומ״ש ומנתחין אותם שם כנתחי העולה בעורן. בפ' איזהו מקומן (זבחים נ״א.) ובפ' שני שעירי (יומא ס״ח:):\",2,0],[8,363,7,3,\"שלשה מקומות לשריפה אחד בתוך העזרה וכו' עד כמצותן. בפרק טבול יום (זבחים דף ק״ד:) וכדתני לוי:\",1,0],[8,363,7,5,\"ושריפת כל הנשרפין כשירה בזר ובלילה: וכל הנשרפין חוץ לעזרה כל העצים כשרים לשריפתן וכו'. בתורת כהנים פרשת ויקרא ובפרק כיצד צולין (פסחים דף ע״ה):\",1,0],[8,363,7,6,\"חטאת העוף כיצד היתה נעשית וכו'. בפ' קדשי קדשים במשנה (דף ס\\\"ד:).\",1,0],[8,363,7,6,\"ומ\\\"ש כמו שביארנו. בפ' [חמישי].\",2,0],[8,363,7,6,\"ומ\\\"ש ויורד בצפרנו עד שיחתוך הסימנין או רוב אחד מהם. בפ\\\"ק דחולין (דף כ\\\"א).\",3,0],[8,363,7,6,\"ומ\\\"ש ואינו מבדיל הראש מן הגוף ואם הבדיל פסל. משנה בפרק קדשי קדשים והוא מבואר בכתוב ולא יבדיל. כתב ספר מצות גדול פי' רש\\\"י ולא יבדיל שאין מולק אלא בסימן אחד. בפרק קדשי הקדשים (דף ס\\\"ה:) כיצד מולקין חטאת העוף חותך שדרה ומפרקת בלא רוב בשר עד שמגיע לושט או לקנה חותך סימן אחד או רובו ורוב בשר עמו ובעולה שנים או רוב שנים ורבינו משה פירש לאו זה שלא יבדיל הראש מהגוף ואני מביא ראיה לדבריו שלמד שם סתם מליקה האמורה בעולת העוף ממליקה המפורשת בחטאת העוף מה להלן ממול עורף וכו' אי מה להלן (בחטאת העוף) מולק ואינו מבדיל אף כאן מולק ואינו מבדיל ת\\\"ל ומלק והקטיר מה הקטרה הראש בעצמו והגוף לעצמו אף מליקה הראש לעצמו והגוף לעצמו ומנין שהקטרת הראש לעצמו והגוף לעצמו שהרי שתי פעמים כתיב והקטיר בפרשה אחד לראש ואחד לגוף וכתב ושסע בינתים עכ\\\"ל.\",4,0],[8,363,7,6,\"ומה שכתב ומזה מדמה על קיר המזבח למטה מאמצעו וכו' עד וזהו קיר התחתון. בפרק קדשי הקדשים (דף ס\\\"ד:) וכתב רש\\\"י בריש מנחות (דף ג') הזאה אוחז בגוף העוף ומעלה ומוריד בכח והדם ניתז מעצמו. מיצוי סוחט בין אצבעותיו ונצוק הדם הולך למרחוק:\",5,0],[8,363,7,7,\"ומ\\\"ש ומיצוי חטאת העוף מעכב. משנה שם [בזבחים] מיצה דם הגוף פסולה ובפרק ב' דמעילה (דף ח' ט') איפליגו אמוראי במילתא ולמ\\\"ד אינו מעכב אותבוהו כמה אמוראי ושנינהו שנויי דחיקי ולא סמכינן עלייהו.\",1,0],[8,363,7,7,\"ומ\\\"ש ואין למזבח בה אלא דמה וכו'. משנה בפ' קדשי הקדשים (דף ס\\\"ד):\",2,0],[8,363,7,8,\"כיצד אוחז חטאת העוף בשעת מליקה וכו'. שם וכדתנא במתניתא.\",1,0],[8,363,7,8,\"ומ\\\"ש ואם שינה ואחז בכ\\\"מ כשירה:\",2,0],[8,363,7,9,\"וכל מקום מן המזבח כשר למליקתה וכו' עד מדם הנפש. משנה וגמ' (דף ס\\\"ג:) בפרק קדשי הקדשים:\",1,0],[8,363,7,10,\"שלשה דברים היתה קרן דרומית מערבית משמשת למעלה ושלשה למטה וכו' עד סוף הפרק. שם.\",1,0],[8,363,7,12,\"ומה שכתב ומתחיל ומקיף מקרן דרומית מזרחית וכו' נותנים המים או היין בידו ומנסך. הוא מדתנן בפרק בתרא דתמיד (דף ל\\\"ג:) בא לו להקיף את המזבח מהיכן הוא מתחיל מקרן דרומית מזרחית וכו' נתנו לו יין לנסך:\",1,0],[8,363,8,2,\"חומר בחטאת הבהמה משאר קדשי קדשים וכו' עד טעונים כיבוס. משנה בפרק דם חטאת (זבחים דף צ״ב).\",1,0],[8,363,8,2,\"ומ\\\"ש אבל העור הקשה הרי הוא כעץ וגורד הדם מעליו. שם (דף צ\\\"ד) אוקימתא דרבא.\",2,0],[8,363,8,2,\"ומ\\\"ש ואחד דם חטאת הנאכלת. משנה שם.\",3,0],[8,363,8,2,\"ומ\\\"ש אבל לא חטאת העוף וכו'. שם בגמרא:\",4,0],[8,363,8,3,\"חטאת שנפסלה אין דמה טעון כיבוס וכו' עד וראוי לכיבוס. משנה שם:\",1,0],[8,363,8,4,\"ומה שכתב אבל אם ניתז על כלי עץ וכו' אלא גורדן בלבד. שם (דף צ\\\"ד) בגמרא:\",1,0],[8,363,8,5,\"ניתז על עור הדג אינו טעון כיבוס וכו'. נלמד ממה ששנינו שם (דף צ\\\"ג:) אין טעון כיבוס אלא דבר שהוא ראוי לקבל טומאה.\",1,0],[8,363,8,5,\"ומ\\\"ש אבל אם ניתז על עור בהמה. שם במשנה פלוגתא דתנאי ופסק כר' יהודה דסתם לן תנא כוותיה (דף צ\\\"ג):\",2,0],[8,363,8,6,\"ניתז מן הצואר על הבגד וכו'. משנה שם ניתז מן הצואר על הבגד אינו טעון כיבוס מן הקרן ומן היסוד אינו טעון כיבוס נשפך על הרצפה ואספו אינו טעון כיבוס אין טעון כיבוס אלא הדם שנתקבל בכלי וראוי להזאה ובגמרא ת\\\"ר יכול ניתז מן הקרן ומן היסוד יהא טעון כיבוס ת\\\"ל אשר יזה פרט לזה שכבר הוזה ואמרינן תו בגמרא הא תו למה לי מה טעם קאמר מה טעם נשפך על הרצפה ואספו אין טעון כיבוס לפי שאין טעון כיבוס אלא דם שנתקבל בכלי וראוי להזאה ראוי להזאה למעוטי מאי למעוטי קיבל פחות מכדי הזאה בכלי זה ופחות מכדי הזאה בכלי זה ופירש\\\"י מן הקרן של מזבח ומן היסוד של שירים ובפ' ב\\\"ש תרגימנא דמן הקרן מן הקרן ממש ומן היסוד מן הראוי ליסוד דמשניתן דמה אין שירים טעונים כיבוס וטעמא מפרש בגמרא עכ\\\"ל. ומפני כך כתב רבינו ניתז מן הצואר על הבגד או מעל קרן המזבח והשמיט מן היסוד וכ\\\"כ בפירוש לקמן בסמוך ופירש\\\"י עוד הא תו למה לי למיתני אין טעון כיבוס אלא שנתקבל בכלי הא תנא ליה נשפך על הרצפה קיבל פחות מכדי הזיה בכלי זה וחזר ועירבו עכ\\\"ל:\",1,0],[8,363,8,7,\"נתן ארבע המתנות וכו'. בר\\\"פ ב\\\"ש.\",1,0],[8,363,8,7,\"ומ\\\"ש וכן בחטאות הנשרפות. משנה בפ' דם חטאת אע\\\"פ שאין הכתוב מדבר אלא בנאכלות שנאמר במקום קדוש תאכל אחד הנאכלות ואחד הפנימיות שנאמר תורת החטאת תורה אחת לכל החטאות:\",2,0],[8,363,8,8,\"ניתז מאצבעו וכו'. בר״פ דם חטאת (זבחים דף צ״ג:). ויש בקצת ספרי רבינו שכתוב שבאמצע במקום שבאצבע וט״ס הוא:\",1,0],[8,363,8,9,\"ניתז מן הבגד וכו'. שם (דף צ\\\"ב:) בעא מיניה לוי ניתז מבגד לבגד מהו מבגד קמא אידחי ליה בכיבוס או דילמא לא א\\\"ל זו שאלה טעון כיבוס ממה נפשך אי אוספו וכשר הא כשר ואי אוספו ופסול כר\\\"ע דאמר היתה לו שעת הכושר ונפסלה דמה טעון כיבוס. ופירש\\\"י אידחי ליה לכיבוס וכו' (דכיון) דאיזקיק לכיבוס אידחי ליה [מתורת הזאה] ולא קרינן בה ראוי להזאה ולא בעי כיבוס האי אחרון. זו שאלה בניחותא יפה שאלת ואשיבך עליה. אי אוספו וכשר אע\\\"ג דאיזקיק לכיבוס לא בטל מתורת דם וכו'. הא כשר וטעון האחרון כיבוס. ואת\\\"ל שאם אוספו מהראשון פסול וכו' אנא כר\\\"ע ס\\\"ל דאמר היתה לה שעת הכושר לזריקה ונפסלה דמה טעון כיבוס והאי הרי בתחילתו בכלי נתקבל והיתה לו שעת הכושר ואח\\\"כ נפסל בנפילתו על בגד הראשון עכ\\\"ל. והשתא כיון דסתם לן תנא דלא כר\\\"ע לא חיישינן למאן דאמר דס\\\"ל כוותיה ועוד דבבעיא דאיתא התם בגמ' בסמוך משמע בהדיא דאמוראי בתראי לא סבירא להו כר\\\"ע כיון דמספקא לן אי אוספו ופסיל בעיין לא איפשיטא ומיהו ק\\\"ל נהי דלא איפשיטא בעיין מ\\\"מ מספיקא ה\\\"ל להחמיר ולהטעינו כיבוס ושמא יש לומר דכיבוס במקום קדוש אינו דרך כבוד כלפי מעלה ומספיקא לא מזלזלינן ביה. ויותר נכון לומר דכיון דסתם לן תנא דלא כר\\\"ע ואמוראי בתראי נמי לא ס\\\"ל כר\\\"ע הא איפשיטא בעיין איפכא מלוי:\",1,0],[8,363,8,9,\"ניתז על בגד טמא אינו טעון כיבוס. שם בעי מיניה רמי בר חמא מרב חסדא ניתז על בגד טמא מהו אמר רב הונא בריה דרב יהושע מדקא מיבעיא ליה הכי ש\\\"מ היתה לו שעת הכושר ונפסלה אין דמה טעון כיבוס ה\\\"מ בזה אחר זה אבל בבת אחת לא או דילמא לא שנא א\\\"ל פלוגתא דר' אליעזר ורבנן וכדמתרץ אביי דתניא ר\\\"א אומר מי חטאת שנטמאו מטהרין שהרי נדה מזין עליה וכו'. במאי קא מיפלגי אמר אביי בדנין טומאה קדומה מטומאה שבאותה שעה קא מיפלגי מר סבר דנין ומר סבר אין דנין. ופירש\\\"י ניתז על בגד טמא ונטמא בנגיעתו בו מי הוי דם פסול כאילו נטמא קודם לכן ולא בעי כיבוס או דילמא כיון דבעידנא דנפל עליה אכתי כשר הוי והרי פסול דם וטעינת כיבוס לבגד באים כאחד כדמפרש ואזיל רב הונא בריה דרב יהושע. מדקא מיבעיא ליה הכי מכלל דפשיטא ליה בטמא קודם לכן דלא בעי כיבוס ואע\\\"ג דהיתה לו שעת הכושר ש\\\"מ סבר וכו' ומיהו היכא דפיסול דם ונפילת בגד באים כאחד מבעיא ליה הכי מי אמרינן ה\\\"מ דפסולה אין דמה טעון כיבוס בזה אחר זה שנפסל ואח\\\"כ ניתז וכו'. מטהרים את האדם מטומאת מת כאילו לא נטמא שהרי נדה שנטמאת במת מזין עליה לפני טבילת נידתה וטובלת אחת בשביל שתי הטומאות וכו'. בדנין טומאה קדומה כגון מי חטאת לפני הזאתו מטומאה שבאותה שעה כגון הזאת נדה שטומאת המים והזאה באים כאחד קא מיפלגי ר\\\"א סבר דנין ורבנן סברי אין דנין ולגבי ניתז דם חטאת על בגד טמא דאיבעיא לן נמי פלוגתא דר\\\"א ורבנן היא דלר\\\"א אין טעון כיבוס דטומאה שבשעת נפילה כטומאה שלפני נפילה ולרבנן לא דמו אהדדי עכ\\\"ל. וקשה דלפי זה ה\\\"ל לרבינו לפסוק כרבנן דסברי בניתז על בגד טמא טעון כיבוס וצ\\\"ע. וכתב הר\\\"י קורקוס ז\\\"ל ואפשר שסובר רבינו שאין הדבר מוכרח דרבנן שאין דנין שם טומאה קדומה מטומאה שבאותה שעה לומר שמי חטאת שנטמאו יטהרו שמפני זה יסברו שאם ניתז על בגד טמא שטעון כבוס שאפשר דלאו הא בהא תליא ומ\\\"מ ודאי שר' אליעזר שדן שם טומאה קדומה מטומאת שעה ע\\\"כ יסבור שגם כאן שאין טעון כיבוס כמו נפסל קודם שניתז הילכך הכי נקטינן. או אפשר שגירסא אחרת או שיטה אחרת היתה לרבינו באותה סוגיא. או אולי לשון רבינו בספרים מוטעה והוא צריך להיות טעון כיבוס והוא היותר קרוב אצלי עכ\\\"ל:\",2,0],[8,363,8,9,\"ניתז דם חטאת על הבגד וכו'. בס״פ דם חטאת (זבחים דף צ״ח:).\",3,0],[8,363,8,9,\"ומ\\\"ש אבל אם ניתז דם החולין תחלה וניתז עליו דם החטאת אינו טעון כיבוס וכו'. שם בעיא דאיפשיטא:\",4,0],[8,363,8,10,\"כשמכבסין את מקום הדם וכו' וכל שבעת הסממנין שמעבירין על הכתם מעבירין על דם חטאת וכו'. בפרק דם חטאת (זבחים דף צ״ה):\",1,0],[8,363,8,11,\"כלי חרס שנתבשלה בו החטאת הנאכלת וכו'. משנה בפרק דם חטאת (זבחים דף צ״ג).\",1,0],[8,363,8,11,\"ומ\\\"ש אע\\\"פ שלא נאמר כאן במקום קדוש וכו'. שם (דף צ\\\"ד:) מנא ה\\\"מ דת\\\"ר תכבס במקום קדוש שבירת כלי חרס מנין ת\\\"ל וכלי חרס אשר תבושל בו ישבר מריקה ושטיפה בכלי נחשת מנין ת\\\"ל ואם בכלי נחשת בושלה ומורק ושוטף במים פירוש דכיון דכתיב וי\\\"ו בתר במקום קדוש דכתיב ברישא בתריה גרירא:\",2,0],[8,363,8,11,\"ואחד כלי שבישל בו או כלי שהערה לתוכו רותח. משנה שם (דף צ\\\"ה:):\",3,0],[8,363,8,12,\"מריקה בחמין ושטיפה בצונן. שם (דף צ\\\"ו:) פלוגתא דתנאי ופסק כחכמים וכסתם מתני'.\",1,0],[8,363,8,12,\"ומ\\\"ש במים לא ביין וכו'. שם.\",2,0],[8,363,8,12,\"ומ\\\"ש והמריקה והשטיפה כמריקת הכוס ושטיפתו. משנה שם. ופירש\\\"י מריקה מבפנים ושטיפה מבחוץ ככוס של ברכה כדאמרינן בברכות שטעון הדחה מבפנים ושטיפה מבחוץ:\",3,0],[8,363,8,12,\"והשפוד והאסכלה מגעילן במים חמין על גבי האש. משנה בפרק דם חטאת (זבחים דף צ״ז) השפוד והאסכלה מגעילן בחמין.\",4,0],[8,363,8,12,\"ומ\\\"ש ואח\\\"כ מדיחן:\",5,0],[8,363,8,13,\"בד״א שבישל בהן וכו'. ברייתא בפרק דם חטאת (זבחים דף צ״ו:) חומר בהזאה שהזאה ישנה בחטאות החיצונות ובחטאות הפנימיות וישנה לפני זריקה משא״כ במריקה ושטיפה:\",1,0],[8,363,8,13,\"בישל במקצת הכלי כולו טעון מריקה ושטיפה. שם בברייתא:\",2,0],[8,363,8,14,\"צלה הבשר באויר תנור של חרס וכו'. שם (דף צ\\\"ה:) בעי רמי בר חמא תלאו באויר תנור מהו אבישול ובילוע הוא דקפיד רחמנא או דילמא אבישול בלא בלוע ופירש\\\"י תלאו לשפוד של חטאת לצלותו באויר תנור דנתבשל בו אבל לא נבלע בו כלום מהו מי הוי תנור טעון שבירה או לא ולא איפשיטא בעיין וזהו שכתב רבינו יש בדבר ספק. ויש לתמוה למה לו להודיענו שהוא דבר ספק ולא פסקה לחומרא סתם כדרכו בשאר ספקי דאורייתא וצריך עיון:\",1,0],[8,363,8,14,\"ולא בחטאת בלבד וכו'. משנה שם ובגמרא יליף לה מקרא.\",2,0],[8,363,8,14,\"ומ\\\"ש עקב אכילה פירוש תיכף לאכילה והוא משנה שם (דף צ\\\"ו:) ר' טרפון אומר בישל בו מתחלת הרגל יבשל בו כל הרגל וחכ\\\"א עד זמן אכילה. ופירש\\\"י יבשל בו כל הרגל בלא מריקה ושטיפה ולסוף הרגל ימרוק וישטוף ובגמ' (דף צ\\\"ו) וחכמים אומרים עד זמן אכילה מאי קאמר אמר רב נחמן וכו' ממתין לה עד זמן אכילה והדר עביד לה מריקה ושטיפה:\",3,0],[8,363,8,14,\"כתב הראב\\\"ד לא ידעתי מהו עקב אכילה אבל כך אמרו חכמים שממתין כל זמן אכילה והדר עביד ליה מריקה ושטיפה עכ\\\"ל. ונוסחתו בגמרא נכונה דגריס כל זמן אכילה לאפוקי מספרים דידן בגמרא דגרסי עד זמן אכילה וגם רש\\\"י שם אהא דתניא הא כיצד ממתין לה עד זמן אכילה והדר עביד לה מריקה ושטיפה כתב ממתין זמן אכילה והשמיט תיבת עד.\",4,0],[8,363,8,14,\"ומ\\\"ש וכן השפוד והאסכלה מגעילן עקב אכילה וכו'. הכי משמע לדברי חכמים שכתבתי בסמוך:\",5,0],[8,363,8,14,\"ומה שכתב וימרוק וישטוף בין כלי מתכות בין כלי חרס חוץ מן החטאת ששובר בה כלי חרס השיגו הראב\\\"ד וכתב טעות הוא בידו ובהדיא בתוספתא שאין טעון אלא שבירה עכ\\\"ל. ורבינו מפרש דלא קיימא תוספתא אלא לחטאת בלבד אבל שאר קדשים אף כלי חרס אינם טעונים אלא מריקה ושטיפה שהרי לא מצינו שהצריכה תורה שבירה לכלי חרס אלא בחטאת בלבד. והילך לשון התוספתא בפרק י' דזבחים ר\\\"ש אומר קדשים קלים אין טעונין מריקה ושטיפה אבל טעונין הדחה משום נותן טעם כבשים פסולים אין טעונין מריקה ושטיפה וכו' כלי חרס אין טעונין אלא שבירה היכן שוברו בפנים יצא לחוץ נכנס ושוברו בפנים. הראב\\\"ד מפרש דאקדשים קלים דקתני לעיל קאי ורבינו סבר דמילתא באפי נפשה הוא ולא מיירי אלא בחטאת ויש סעד לדבריו מדמסיים בה ששוברו בפנים שהוא הדין השנוי במשנה גבי חטאת. ועוד דקתני תו בתוספתא שם חומר במריקה ושטיפה שהמריקה ושטיפה נוהגים בקדשי קדשים ובקדשים קלים ומדשבקה לשבירה משמע שאינה נוהגת אלא בחטאת בלבד.\",6,0],[8,363,8,14,\"ומה שכתב ומבשל ושונה ומשלש מיד וכו'. הכי משמע לרבינו מלישנא דחכמים שאמרו זמן אכילה שכל תוך זמן אכילה מבשל והולך אפילו כמה פעמים.\",7,0],[8,363,8,14,\"ומה שכתב עד סוף אכילה. הכי משמע לרבינו לישנא דזמן אכילה דהיינו עד סוף אכילה וכן בדין דהא אין דרך למרוק ולשטוף עד אחר אכילה:\",8,0],[8,363,8,15,\"כלי גללים וכלי אבנים וכו'. נראה שטעמו משום דכתיב וכלי חרס אשר תבושל בו ישבר ואם בכלי נחשת בושלה ומורק ושוטף משמע דוקא הני ולא שאר מינים וכלי אדמה שלא נתבשלו אינן בכלל כלי חרס, ואין לומר דלפי זה הוה ליה לרבינו למעט גם כן כלי עץ דלא איצטריך למעט אלא הני דדמו לכלי חרס הכתוב בתורה:\",1,0],[8,363,8,15,\"נאמר בחטאת כל אשר יגע בבשרה וכו'. ברייתא בפרק דם חטאת (זבחים דף צ״ז:) כל אשר יגע בבשרה וכו' יקדש להיות כמוה הא כיצד אם פסולה היא תפסל כשרה היא תאכל כחמור שבה, ויש בקצת ספרי רבינו חסרון הניכר:\",2,0],[8,363,8,16,\"ומ\\\"ש בד\\\"א כשנבלע וכו'. שם בברייתא.\",1,0],[8,363,8,16,\"ומ\\\"ש ואחד החטאת ואחד שאר הקדשים וכו'. גם זה שם:\",2,0],[8,363,8,17,\"ומ\\\"ש נגע בשרה ברקיק ונבלע במקצתו וכו'. משנה וברייתא שם:\",1,0],[8,363,8,18,\"כלי שבישל בו קדשים וחולין וכו'. משנה וגמרא שם.\",1,0],[8,363,8,18,\"ומ\\\"ש ואם לא נתן טעם זה בזה וכו' אבל הכלי טעון מריקה ושטיפה. שם אהא דקאמר אם אין בהם בנ\\\"ט אין הקלים נאכלים כחמורים ואין טעונין מריקה ושטיפה פריך נהי דקדשי קדשים לא ניבעי קדשים קלים ניבעי. ופירש\\\"י נהי דלא בעו מריקה לסוף זמן אכילת חמורים דהא מועטים ובטלי נבעי מיהא משום קלים לסוף זמן אכילתן אמר אביי מאי אין טעונים דקאמר קדשי קדשים אבל קדשים קלים טעונים. ומדברי הראב\\\"ד נראה שהיה גורס בלשון רבינו אבל [הכל] במקום הכלי שכתב אבל הכל טעון מריקה ושטיפה פירוש קדשי קדשים וקדשים קלים עכ\\\"ל. וגירסת הכלי עיקר וכמו שכתבתי:\",2,0],[8,363,8,19,\"בגד שניתז עליו דם החטאת ויצא חוץ לעזרה וכו'. משנה בפרק דם חטאת (זבחים דף צ״ד:).\",1,0],[8,363,8,19,\"ומה שכתב וצריך להניח בו שלם כדי מעפורת וכו'. שם בגמרא:\",2,0],[8,363,8,20,\"ומה שכתב מעיל שניתז עליו דם חטאת ויצא ונטמא בחוץ וכו'. מימרא שם (דף צ\\\"ה):\",1,0],[8,363,8,21,\"כלי חרס שבישל בו חטאת ויצא וכו'. משנה שם (דף צ\\\"ד:).\",1,0],[8,363,8,21,\"ומה שכתב בכדי שורש קטן ואם ניקב נקב גדול מזה אינו שוברו בפנים וכו'. שם בגמרא:\",2,0],[8,363,8,21,\"וכן כלי מתכות שבישל בו ויצא חוץ לעזרה וכו'. משנה שם.\",3,0],[8,363,8,21,\"ומה שכתב וחוזר ומרדדו וכו'. שם בגמרא:\",4,0],[8,363,9,1,\"מצות עשה לעשות כל האשמות וכו' כמו שביארנו. בפרק ה' מהלכות אלו.\",1,0],[8,363,9,1,\"ומ\\\"ש ואם רצה להוליכם בכלי מוליך. נתבאר ברפ\\\"ז.\",2,0],[8,363,9,1,\"ומ״ש ושאר בשרם נאכל לזכרי כהונה בעזרה כחטאת. משנה בפ' איזהו מקומן (זבחים דף נ״ד:):\",3,0],[8,363,9,2,\"אשם מצורע יש בקבלת דמו שינוי כמו שיתבאר בהלכות מחוסרי כפרה. בפרק ד':\",1,0],[8,363,9,4,\"וכיצד מעשה שלמי צבור שוחט וזורק הדם כמו שביארנו. בפרק חמישי.\",1,0],[8,363,9,4,\"ומה שכתב והשאר נאכל לזכרי כהונה בעזרה כחטאת וכאשם. משנה בפרק איזהו מקומן (זבחים דף נ״ג).\",2,0],[8,363,9,4,\"ומה שכתב כמו שביארנו. הוא בפרק א':\",3,0],[8,363,9,6,\"וכיצד מעשה שלשתן וכו' ומפריש החזה ושוק הימין ונותן האימורים עם החזה והשוק על ידי הבעלים וכהן מניח ידו תחת ידי הבעלים ומניף הכל לפני ה' במזרח. בפרק כל המנחות (מנחות דף ס״א ס״ב:) יליף לה מקראי.\",1,0],[8,363,9,6,\"ומה שכתב וכן כל הטעון תנופה במזרח מניפין אותו. משנה שם (דף ס\\\"א) תנופה היתה במזרח ופירש רש\\\"י תנופה במזרח כלומר אפילו במזרחו של מזבח יכול להניף וכל שכן במערבו שקרוב יותר להיכל עכ\\\"ל. ואין כן דעת רבינו. ובגמרא והניף לפני ה' במזרח והא אמרת לפני ה' יכול במערב אמרי ה\\\"מ מנחה דאיקרי חטאת וחטאת טעונה יסוד וקרן דרומית מזרחית לא היה לו יסוד אבל הכא לפני ה' קרינן ביה ופירש רש\\\"י לפי דרכו ולישנא דלפני ה' קרינן ביה כוותיה משמע אבל רבינו מפרש דלא אמרי במערב אלא במנחה אבל בתנופה מזרח בעינן. ותמיהא לי על דברי רבינו דלפני ה' טפי משמע במערב מבמזרח והיכי אפשר לומר דדוקא במזרח וצריך עיון:\",2,0],[8,363,9,7,\"ומ\\\"ש וכיצד הוא מניף מוליך ומביא מעלה ומוריד. שם במשנה:\",1,0],[8,363,9,7,\"ואם היה הקרבן תודה וכו'. משנה בפ' התודה (מנחות דף ע״ז:).\",2,0],[8,363,9,7,\"ומ\\\"ש נותן את החלבים על ידי הבעלים וכו'. ברייתא בפ' כל המנחות באות (ס\\\"ב) מניח אימורים על פיסת היד וחזה ושוק עליהם וכ\\\"מ שיש לחם הלחם מלמעלה. ומשמע לרבינו דאימורים דקתני לא כל האימורים אלא החלבים בלבד דהא מקרא דעל אשי החלבים יליף לה:\",3,0],[8,363,9,9,\"היה הקרבן איל נזיר וכו'. בפרק שני דמדות שנינו שבעזרת הנשים היתה לשכת הנזירים ששם הנזירים מבשלים שלמיהם.\",1,0],[8,363,9,9,\"ומ״ש ולוקח הכהן הזרוע בשלה מן האיל. מדסתם רבינו דבריו משמע ששאר האיל היה מבשל כשהזרוע מחובר בו ופלוגתא היא בפרק גיד הנשה (חולין דף צ״ח) ופסק רבינו כלישנא קמא משום דאתי כפשטיה דקרא. ונראה שרבינו מפרש כפירוש התוס' שפירשו דלת״ק מבשלו כשהזרוע מחובר בו ופסק כוותיה.\",2,0],[8,363,9,9,\"ומ״ש עם אחד מעשרה מן הלחם הבא עמו. בפ' התודה (מנחות דף ע״ח) שנינו נזירות היתה באה שתי ידות כמצה שבתודה חלות ורקיקין ואין בה רבוכה ובכל מין במצה שבתודה היו עשר חלות כמו ששנינו שם נמצא שהיה בנזיר י' חלות וי' רקיקין וכתיב ולקח הכהן את הזרוע וכו' וחלת מצה אחת ורקיק מצה אחד ונתן על כפי הנזיר.\",3,0],[8,363,9,9,\"ומה שכתב עם החזה והשוק דכתיב והניף אותם הכהן תנופה לפני ה' קדש הוא לכהן על חזה התנופה ועל שוק התרומה.\",4,0],[8,363,9,9,\"ומ\\\"ש והאימורים ומניח הכל על ידי הנזיר וכו'. נלמד ממה שנאמר בפירוש זבח שלמים בפרשת צו ונתבאר לעיל בסמוך:\",5,0],[8,363,9,10,\"אי זהו חזה כל הרואה את הקרקע למעלה עד הצואר וכו'. ברייתא בר״פ אלו טרפות (חולין דף מ״ה).\",1,0],[8,363,9,10,\"ומ״ש ואי זהו זרוע מן הפרק של ארכובה וכו'. משנה ס״פ הזרוע (חולין דף קל״ד).\",2,0],[8,363,9,10,\"ומ\\\"ש והזרוע האמורה היא הזרוע של ימין. ברייתא שם.\",3,0],[8,363,9,10,\"ומ\\\"ש ושכנגדה ברגל הוא שוק האמור בכל מקום. שם במשנה:\",4,0],[8,363,9,11,\"ואין הכהנים זוכין בחזה ושוק אלא לאחר הקטר אימורים. ברייתא בר\\\"פ תמיד נשחט (פסחים נ\\\"ט:) יכול יהיו כהנים רשאים בחזה ושוק קודם הקטרת אימורים תלמוד לומר והקטיר הכהן את החלב המזבחה והדר והיה החזה לאהרן ולבניו:\",1,0],[8,363,9,12,\"וכן הלחם שמניף בתודה ובאיל נזיר וכו'. משנה פרק התודה (דף ע\\\"ד:):\",1,0],[8,363,9,12,\"והלחם שמניף עם החזה ושוק וכו'. פשוט הוא:\",2,0],[8,363,9,13,\"הלחם המורם מן התודה וכו'. בפ' התודה (מנחות דף ע״ז:) בעיא דלא איפשיטא ופסק בה לקולא לענין מיתה וחומש. ומן הדין לא היה לרבינו לכתוב פטורו ממיתה דהא מיתה בידי שמים הוא וקמי שמיא גליא ומיפשטא בעיא אלא שנגרר אחר לשון הבעיא.\",1,0],[8,363,9,13,\"ועל מ\\\"ש ואינו מדמע כתרומה יש לתמוה דכיון דספיקא הוא ה\\\"ל למיפסק לחומרא:\",2,0],[8,363,9,13,\"וכתב הר\\\"י קורקוס ז\\\"ל ואפשר שבתערובת המותר מן התודה קאמר כי שיעורה מדרבנן הוא לדעת הרב כמו שנתבאר במקומו הילכך אזלינן לקולא אבל בספק תודה ודאי דלחומרא וזהו כוונת רבינו במ\\\"ש אינו מדמע כתרומה עכ\\\"ל:\",3,0],[8,363,9,14,\"היה בעל התודה כהן וכו':\",1,0],[8,363,9,15,\"שנים שהביאו שלמים בשותפות וכו'. משנה בס״פ שתי מדות (מנחות דף צ״ג:):\",1,0],[8,363,9,16,\"היתה אשה בעלת הקרבן אינה מניפה וכו' והאשה כהן מניף על ידה. בפרק כל המנחות (דף ס\\\"ח:).\",1,0],[8,363,9,16,\"ומה שכתב ולעולם אין אשה מניפה אלא הסוטה והנזירה בלבד. משנה בפרק קמא דקידושין (דף ל\\\"ו).\",2,0],[8,363,9,16,\"ומה שכתב ותנופה קודמת להגשה וכו'. משנה פרק כל המנחות (מנחות דף ס״א):\",3,0],[8,363,9,17,\"כיצד הוא הלחם שמביא עם התודה וכו'. משנה בר״פ התודה (מנחות דף ע״ו ע״ז):\",1,0],[8,363,9,18,\"ומ״ש וכיצד מחמצן מביא שאור כדי חמוצן ונותנו לתוך המדה וכו'. בר״פ כל המנחות (מנחות דף נ״ב) במשנה פלוגתא דר״מ ורבי יהודה ופסק כרבי יהודה.\",1,0],[8,363,9,18,\"ומ״ש והרי הוא מודד עשרון עשרון שלימים. משנה ר״פ שתי מדות (מנחות דף פ״ז) עשרון מה היה משמש. בו היה מודד לכל המנחות לא היה מודד לא בשל שלשה לפר ולא בשל שנים לאיל אלא מודדן עשרונות.\",2,0],[8,363,9,18,\"ומ״ש והעשרה עשרונים של מצה עושה מהם שלשים חלות שוות עשר חלות מכל מין עשר חלות מאפה תנור ועשר חלות רקיקין ועשר חלות מורבכת. משנה בפרק התודה (מנחות דף ע״ז):\",3,0],[8,363,9,20,\"וכיצד היא המורבכת וכו'. בת\\\"כ מורבכת מלמד שנעשית ברותחין כל צרכה.\",1,0],[8,363,9,20,\"ומ\\\"ש ואופה אותה מעט ואחר כך קולה אותה בשמן. יתבאר בפרק י\\\"ג גבי חביתי כ\\\"ג:\",2,0],[8,363,9,20,\"וכמה שמן הוא עושה וכו' עד לרקיקין. משנה וברייתא בפ' שתי מדות (מנחות דף פ״ח פ״ט):\",3,0],[8,363,9,21,\"ומ״ש החלות לותת הסלת שלהן בשמינית של שמן וכו'. משנה פ' אלו מנחות (מנחות דף ע״ד:) החלות טעונות בלילה והרקיקין משיחה:\",1,0],[8,363,9,21,\"והכהן נוטל מן הכל ארבע חלות וכו'. משנה בפ' התודה (מנחות דף ע״ז:):\",2,0],[8,363,9,22,\"ולחמי תודה שאפה אותן ד' חלות יצא. מימרא דשמואל בסוף אלו מנחות (מנחות דף ע״ו) ואע״ג דאמרי' התם דרב הונא פליג פסק רבינו כשמואל.\",1,0],[8,363,9,22,\"ומ\\\"ש והוא שיפריש החלה שלהן אחת מכל קרבן כשהם בצק. שם.\",2,0],[8,363,9,22,\"ומ״ש שאין מפרישין פרוסה וכו'. משנה בפ' התודה (מנחות דף ע״ז:):\",3,0],[8,363,9,23,\"וכיצד הוא הלחם הבא עם איל נזיר וכו'. משנה בפרק התודה (מנחות דף ע״ח).\",1,0],[8,363,9,23,\"ומ\\\"ש רקיקין משוחין בשמן ועשר חלות לותת הסלת שלהן בשמן. מפורש בתורה.\",2,0],[8,363,9,23,\"ומ\\\"ש והכל מאפה תנור. מפורש בפ' ויקרא שהחלות והרקיקין הם מאפה תנור.\",3,0],[8,363,9,23,\"ומ״ש ושמן שלהן רביעית. משנה בפרק שתי מדות (מנחות דף פ״ח).\",4,0],[8,363,9,23,\"ומ״ש ושיעור זה הלמ״מ. פרק ג' מינים (נזיר דף ל״ח) ופ' שתי מדות (פ״ט).\",5,0],[8,363,9,23,\"ומ\\\"ש והכהן לוקח שתי חלות אחת מכל מין. מפורש בתורה:\",6,0],[8,363,9,24,\"שני מיני לחם שבנזיר וכו'. משנה בפ' הקומץ רבה (מנחות דף כ״ז).\",1,0],[8,363,9,24,\"ומ\\\"ש ומעשה הלחם של שניהם חוץ לעזרה:\",2,0],[8,363,9,25,\"כיצד מעשה הבכור והמעשר והפסח וכו' עד סוף הפרק. משנה בפרק איזהו מקומן (זבחים דף נ״ו:):\",1,0],[8,363,10,1,\"אכילת החטאת והאשם מצות עשה וכו' הכהנים אוכלים ובעלים מתכפרים. בפרק תמיד נשחט (פסחים דף נ״ט):\",1,0],[8,363,10,2,\"ומ\\\"ש וכן אכילת שירי מנחות מ\\\"ע וכו'. פשוט הוא:\",1,0],[8,363,10,3,\"ואין חטאת ואשם ושירי מנחות נאכלים אלא לזכרי כהונה בעזרה. משנה פ' איזהו מקומן (זבחים דף נ״ד:).\",1,0],[8,363,10,3,\"ומ״ש ואם נאכלו בהיכל נאכלו וכו'. בפרק קדשי קדשים (זבחים דף ס״ג).\",2,0],[8,363,10,3,\"ומ״ש וכן שלמי צבור הרי הן כחטאת וכאשם. משנה בפרק איזהו מקומן (זבחים דף נ״ד:).\",3,0],[8,363,10,3,\"ומ\\\"ש כמו שביארנו. הוא בפ\\\"ט:\",4,0],[8,363,10,4,\"חזה ושוק של שלמים וכו' עד שהרי הם קדשים קלים כשלמים. (בפ' איזהו מקומן) [בפ' קרח]:\",1,0],[8,363,10,5,\"ומה שכתב והחלונות ועובי החומה כלפנים. משנה בפרק כיצד צולין (פסחים דף פ״ה):\",1,0],[8,363,10,6,\"השלמים נאכלים ביום הזביחה וכו' עד ובכור ומעשר הדומים להם. בפרק איזהו מקומן (זבחים דף נ״ו:):\",1,0],[8,363,10,8,\"ומ\\\"ש וכל אלו הנאכלים ליום ולילה דין תורה שנאכלין עד שיעלה עמוד השחר וכו'. שם (דף נ\\\"ז:) ובפ\\\"ק דברכות (דף ט'):\",1,0],[8,363,10,9,\"כל קרבנות בין קדשי קדשים וכו'. בר״פ הערל (יבמות דף ע').\",1,0],[8,363,10,9,\"ומ״ש אפי' העריב שמשו ולא הביא כפרתו אינו אוכל בקדשים. בפרק בתרא דנגעים ובפרק טבול יום (זבחים דף צ״ח צ״ט) ובפסחים פ' האשה (דף צ':).\",2,0],[8,363,10,9,\"ומה שכתב והטומטום אסור לאכול בקדשים וכו'. ברייתא בפרק הערל (יבמות דף ע״ב).\",3,0],[8,363,10,9,\"ומ\\\"ש אבל אנדרוגינוס יראה לי שאוכל בקדשים קלים. כלומר והוא שמל ובר\\\"פ הערל תניא אנדרוגינוס אוכל בתרומה ואינו אוכל בקדשים. ופי' רש\\\"י פירוש בקדשי קדשים מיירי שאין נאכלים אלא לזכרי כהונה וזה ספק אשה הוא עכ\\\"ל:\",4,0],[8,363,10,10,\"ומותר לאכול הקדשים בכל מאכל. משנה בפ' איזהו מקומן (זבחים דף נ״ה).\",1,0],[8,363,10,10,\"ומ״ש אפילו הכהנים מותרין לאכול חלקם וכו' ולשנות באכילתן ולאכלם צלויים וכו'. משנה בס״פ כל התדיר (זבחים דף צ'.).\",2,0],[8,363,10,10,\"ומ\\\"ש אפילו הכהנים. נראה דכתב כן משום דסד\\\"א שהכהנים צריכים שלא יאכלו אלא לש\\\"ש ולכן לא יאכלו אותם במטעמים דרך תענוג קמ\\\"ל משום דכתב בהו רחמנא למשחה ומתרגמינן לשון גדולה כמו שהמלכים אוכלים.\",3,0],[8,363,10,10,\"ומ\\\"ש אבל לא תבלין של תרומה וכו'. שם במשנה פלוגתא דר\\\"ש ור\\\"מ ופסק כר\\\"מ:\",4,0],[8,363,10,10,\"והעצמות הנשארות מותרות וכו'. בפרק המזבח מקדש (זבחים דף פ״ו) ובפרק דם חטאת (זבחים דף צ״ח) אשם מה אשם עצמותיו מותרין אף כל עצמותיו מותרין ופירש״י מה אשם עצמותיו מותרין לעשות מהם כלים אני שמעתי שהרי נאכל לכהנים ונותר בעצמות לא שייך אלא בדבר הנאכל. אף כל ואפילו עולה ומיבעיא לי הא נמי מחטאת הוה מצי יליף ונראה בעיני דמלו יהיה יתירא נפקא ליה באשם דכתיב ביה לכהן לו יהיה עכ״ל. כתב הר״י קורקוס ז״ל כתב רבינו הנשארות כלומר שאין בהם שום דבר ראוי לאכילה דתנן בתרומות פרק י״א עצמות קדשים בזמן שמכנסן אסורות ואם השליכן מותרות ומיירי ביש עליהם קצת בשר ולכן אם מחשיבן אסורות ואין מותר אלא נשארות שאינו מחשיבן ולא מצניען כ״כ תוספות שם עכ״ל:\",5,0],[8,363,10,11,\"היתה להם אכילה מועטת וכו' עד שלא תהא נאכלת אכילה גסה. בפרק רביעי דתמורה (דף כ\\\"ג).\",1,0],[8,363,10,11,\"ומה שכתב וכן בשירי המנחות. בתורת כהנים והנותרת ממנה יאכלו אהרן ובניו וכו' יאכלוה שיאכלו עמה חולין ותרומה בזמן שהיא מועטת:\",2,0],[8,363,10,12,\"אין מבשלים חטאת או אשם וכו' עד ובזמן אכילתן. בתוספתא דזבחים פרק עשירי:\",1,0],[8,363,10,12,\"חתיכה של קדשי קדשים וכו' עד ומותר לטהורים. בפרק ב' דערלה (משנה ט\\\"ז):\",2,0],[8,363,10,12,\"כתב הראב\\\"ד ומותרות לכהנים א\\\"א והוא שיהא בשל היתר כדי להעלות את האיסור עכ\\\"ל. ואני אומר שדבר פשוט הוא וכתבו רבינו בהדיא בפירוש המשנה שם אבל קשה שלא הוה ליה ליכתוב או או וצריך עיון:\",3,0],[8,363,10,14,\"נאמר בעולה עור העולה אשר הקריב לכהן לו יהיה וכו' ומי שאינו ראוי בשעת הקרבן וכו'. בריש פרק טבול יום (זבחים דף צ״ט:):\",1,0],[8,363,10,15,\"ומ״ש ולמה חלק הכתוב במנחות כו'. ומ״ש אין חולקין מנחה כנגד מנחה וכו'. בפ' האיש מקדש (קידושין דף נ״ג) ובפרק אלו מנחות (מנחות דף ע״ג) ובתורת כהנים:\",1,0],[8,363,10,16,\"ומ\\\"ש וכן אין חולקין עוף כנגד עוף וכו'. בתוספתא פ' י\\\"א דזבחים:\",1,0],[8,363,10,17,\"אין הקטן חולק אפילו בקדשים קלים וכו'. בפרק האיש מקדש ובריש פרק אלו מנחות לכל בני אהרן תהיה וכו' איש כאחיו וגו' איש חולק ואפי' בעל מום ואין קטן חולק אפי' תם.\",1,0],[8,363,10,17,\"ומה שכתב וכן אשה ואנדרוגינוס וכו'. אפשר דיליף לה מדכתיב לכל בני אהרן תהיה בני אהרן ולא בנות אהרן ואנדרוגינוס דספק אשה הוא אינו חולק מן הספק:\",2,0],[8,363,10,17,\"אבל בעל מום בין קבוע בין עובר חולק ואוכל. בר״פ טבול יום (זבחים דף צ״ט).\",3,0],[8,363,10,17,\"ומ\\\"ש בין שנולד במומו וכו'. ברייתא שם.\",4,0],[8,363,10,17,\"ומ\\\"ש אבל אם היה טמא אינו חולק לאכול לערב. בר\\\"פ טבול יום שם:\",5,0],[8,363,10,18,\"וכהן גדול אוכל שלא בחלוקה וכו'. משנה בריש יומא (דף י\\\"ד) שכ\\\"ג מקריב חלק בראש ונוטל חלק בראש:\",1,0],[8,363,10,19,\"כל הראוי לאכילת הקדשים וכו'. ריש פרק [טבול יום] (דף צ\\\"ח:) טבול יום ומחוסר כפורים אינם חולקים בקדשים לאכול לערב אונן נוגע ואינו מקריב ואינו חולק לאכול לערב בעלי מומין בין בעלי מומין עוברין בין בעלי מומין קבועים חולקין ואוכלים אבל לא מקריבים כל שאינו ראוי לעבודה אינו חולק בבשר:\",1,0],[8,363,10,20,\"ומ\\\"ש רבינו שכהן גדול האונן מקריב ואינו אוכל. משנה בסוף הוריות (דף י\\\"ב:):\",1,0],[8,363,10,20,\"ומ\\\"ש וכל שאינו ראוי לעבוד אינו [ראוי] לאכול חוץ מבעל מום שהרי נתפרש בתורה. משנה וגמרא שם:\",2,0],[8,363,10,20,\"כתב הראב\\\"ד כל שאינו ראוי וכו' חוץ מכהן גדול א\\\"א ויש וכו'. וחמשה דברים הללו שנויים במשנה פרק כיצד צולין. ומתוך דברי הראב\\\"ד נתיישב למה לא כתב רבינו פה חמשה דברים אלו דהנך שאני שהם קרבנות הצבור ומחמת כן מקריבין אותם בטומאה שטומאה דחויה היא בצבור:\",3,0],[8,363,10,21,\"כל שאין לו חלק בבשר אין לו חלק בעורות. משנה ר״פ טבול יום (זבחים דף צ״ח:):\",1,0],[8,363,10,21,\"אפילו טמא בשעת זריקת דמים וכו'. שם במשנה:\",2,0],[8,363,10,22,\"ומ\\\"ש נטמא אחר זריקה וטבל והרי הוא טהור אף בשעת הקטר חלבים וכו'. שם (דף ק\\\"ב:) בעיא דלא איפשיטא:\",1,0],[8,363,10,23,\"קרבן צבור הבא בטומאה וכו'. שם (דף צ\\\"ט) בעי רב אושעיא טמא בקרבנות צבור מהו שיחלקו לו מי אמרינן המחטא אמר רחמנא והאי נמי מחטא הוא או דילמא ראוי לאכילה חולק שאינו ראוי לאכילה אינו חולק אמר רבינא ת\\\"ש כ\\\"ג מקריב אונן ואינו אוכל ואינו חולק לאכול לערב ש\\\"מ ראוי לאכילה בעינן ש\\\"מ. ופירש\\\"י מהו שיחלקו לו מקרבן צבור לאכול לערב ובקרבן צבור שהקריבוהו טהורים קא מבעיא ליה אי פלגינן מיניה להאי טמא הואיל וראוי לחטוי דקרבן צבור דוחה טומאה או דילמא ראוי לאכילה בעינן אבל בהקריבוהו טמאים לא מבעיא לן שהרי אינו נאכל כדאיתא בפרק כיצד צולין ורבינו בפ\\\"ד מהלכות ביאת המקדש פסקה לההיא דפ' כיצד צולין וא\\\"כ יש לתמוה היאך כתב כאן קרבן צבור הבא בטומאה וכו' אין חולקין עם הטהורים לאכול לערב דמשמע שהטהורים אוכלים אותו. וכתב הר\\\"י קורקוס ז\\\"ל שצריך לפרש דברי רבינו כך קרבן צבור שיכולים להביאו בטומאה כשהיה צורך לכך וז\\\"ש הבא בטומאה ולא אמר שבא בטומאה אע\\\"פ שהטמאין מקריבין אותו כלומר שיכולים להקריבו בשהשעה צריכה לכך ולכך לא כתב שהטמאים הקריבוהו אלא מקריבין דהיינו שיכולים להקריב ואעפ\\\"כ אינם חולקים עם טהורים שהקריבוהו דסד\\\"א שקרבן כזה טמאים וטהורים שוים כיון שהיה אפשר שיקריבוהו טמאים וראוי לחיטוי קרינן ביה קמ\\\"ל דלא שהרי אינם ראויין לאכילה ולעולם בהקריבוהו טהורים מיירי. ובהא ניחא נמי מה שלא הוציא זה מהכלל דכ\\\"ג מקריב ואינו אוכל [דכ\\\"ג] מהקרבן שהקריב קאמר אבל טמא בקרבנות צבור לאו בהקריב הוא מיירי ולא שייך למימר שאינו אוכל ומקריב עכ\\\"ל. ולי אין צורך לידחק בכך בפירוש דברי רבינו אלא דברים כפשוטן שהקריבוהו טמאים שיש קרבן צבור שהוא בא בטומאה והוא קרבן פסח כדתנן בפרק כיצד צולין וכתבו רבינו בהל' קרבן פסח פ\\\"י וכגון שהיו הקהל מחצה טהורים ומחצה טמאים שכולם עושים בראשון והטהורים עושים לעצמם בטהרה והטמאים עושים לעצמם בטומאה ואוכלים אותו בטומאה והשתא קאמר שאע\\\"פ שיכולים הטמאים להקריב פסחיהם אינם יכולים להמנות עם הטהורים אע\\\"פ שלערב יהיו טהורים ויהיו ראויים לאכילה עם הטהורים:\",1,0],[8,363,11,1,\"כל האוכל כזית מבשר העולה וכו' לוקה. בפרק אלו הן הלוקין (מכות דף י״ז):\",1,0],[8,363,11,2,\"ומ\\\"ש וחלבה ובשרה וסלתה וכו' חמשתן מצטרפין לכזית. משנה בפ\\\"ד דמעילה (דף ט\\\"ו:):\",1,0],[8,363,11,3,\"וכן האוכל כזית מכל האימורין וכו' כל שהוא כליל למזבח אכילתו בלא תעשה. פרק אלו הן הלוקין (מכות דף י״ח:) ר' אליעזר אומר כל שהוא בכליל תהיה ליתן לא תעשה על אכילתו:\",1,0],[8,363,11,3,\"מצאתי כתוב דע כי אין מעילה באימורים עד אחר זריקת דמים ואע\\\"ג דאוכל מבשר קדשים לוקה אינו לוקה משום לאו דמעילה דהא אם אכל בשוגג מאימורי קדשים קלים קודם זריקה אינו מביא אשם מעילות. וקשה דנראה לאו דלא לאכול מבשר עולה היינו לאו דמעילה וראיה לזה שלא מנה הרמב\\\"ם לאו דמעילה בהלכות מעילה שסמך על מה שכתב כאן וא\\\"א לומר דלענין קרבן בשוגג אין מעילה באימורים עד לאחר זריקת דם ולמלקות יש בהם לאו דמעילה אפי' קודם זריקת דמים דהא מתניתין סתמא תנן קדשים קלים לפני זריקת דמים אין מועלים לא באימורים ולא בבשר פ\\\"ק דמעילה (דף ז'). ונראה דיש כאן שני לאוין האחד הוא לאו וכל מנחת כהן כליל תהיה לא תאכל ומשם למדנו לכל הראוי לאשים שאם אכלו הוא בל\\\"ת ואם אכל בשר אימורים קדשים קלים לוקה משום לאו זה. ויש עוד לאו אחר הנהנה מן ההקדש במזיד ואם אכל מבשר עולה או מאימורי חטאת ואשם עובר על שנים לאו דמעילה ולאו דכל מנחת כהן וכן מנה הרמב\\\"ם שני לאוין פרק י\\\"ט מהלכות סנהדרין ולא ירדתי לסוף דעתו למה לא כתב בהלכות מעילה לאו דנהנה מן ההקדש במזיד עכ\\\"ל:\",2,0],[8,363,11,3,\"וכן האוכל כזית מבשר חטאות הנשרפות לוקה וכו'. זה בכלל מה שנתבאר בסמוך כל שהוא בכליל תהיה ליתן לא תעשה על אכילתו ואיתיה בתורת כהנים פרשת צו בהדיא לגבי פרים ושעירים הנשרפים:\",3,0],[8,363,11,4,\"כל האוכל כזית מבשר הקדשים אפילו קדשים קלים קודם זריקת דמים לוקה וכו'. בפ' אלו הן הלוקין (מכות דף י״ז י״ח):\",1,0],[8,363,11,5,\"ומ\\\"ש וה\\\"ה לאוכל קדשים קלים חוץ לירושלים שהוא לוקה וכו'. שם.\",1,0],[8,363,11,5,\"ומ\\\"ש ואחד בשר חטאת ואשם או שירי מנחות:\",2,0],[8,363,11,6,\"בשר קדשי הקדשים שיצא חוץ לחומת העזרה וכו'. בריש פרק בהמה המקשה (חולין דף ס\\\"ח:):\",1,0],[8,363,11,7,\"נכנס בשר קדשים קלים להיכל הרי זה כשר. בסוף פרק התערובת (זבחים דף פ״ב:):\",1,0],[8,363,11,8,\"זר שאכל כזית מבשר קדשי קדשים בעזרה וכו'. בפרק אלו הן הלוקין (מכות דף י\\\"ח:) אמר רב גידל אמר רב זר שאכל מחטאת ואשם לפני זריקה פטור מ\\\"ט [דאמר קרא] ואכלו אותם אשר כופר בהם וכו' כל היכא דקרינן ביה ואכלו אותם אשר כופר בהם קרינן ביה וכל זר לא יאכל קדש וכל היכא דלא קרינן ביה ואכלו אותם אשר כופר בהם לא קרינן ביה וכל זר לא יאכל קדש.\",1,0],[8,363,11,8,\"ומה שכתב אבל אם אכל הזר בשר קדשי קדשים בחוץ לוקה משום אוכל בחוץ לא משום זר שאכל קדש וכו' וכן אם אכלן בעזרה וכו'. כל זה בכלל מימרא דרב גידל:\",2,0],[8,363,11,9,\"זר שאכל כזית מחטאת העוף לוקה שתים וכו'. בסוף פרק ארבעה אחין (יבמות דף ל\\\"ג) ופירש רש\\\"י כולל לא משכחת לה דהא בשעת מליקה חיילי תרוייהו דכל זמן שלא נמלקה היה עליה איסור מעילה ולא זה הוא איסור זרות [האמור] בקרבן שניתר לאכילת כהנים וכשנמלקה ונראית לכהנים פקע מינה איסור אזהרת מעילה וחייל עליה איסור זרות דזר לא יאכל ואיסור מליקה באיסור בת אחת:\",1,0],[8,363,12,1,\"המנחות הם מן הקרבנות וכו':\",1,0],[8,363,12,2,\"וכל המנחות סולת חטים וכו'. משנה רפ\\\"ב דסוטה (דף י\\\"ד):\",1,0],[8,363,12,3,\"שלש מנחות לצבור עומר התנופה וכו' כמו שיתבאר. בפ\\\"ז מה' תמידין:\",1,0],[8,363,12,3,\"והמנחה השלישית היא לחם הפנים וכו' כמו שיתבאר. בפרק הנזכר:\",2,0],[8,363,12,4,\"ותשע מנחות היחיד וכו'. במשנה בפרק כל המנחות באות (מנחות דף ס'). ויש בנוסחאות שלנו בדברי רבינו חסרון וצריך לכתוב מנחת מאפה תנור והיא באה בנדר ונדבה מנחת רקיקין והיא באה בנדר ונדבה:\",1,0],[8,363,12,5,\"כל המנחות הקריבות לגבי המזבח וכו'. בהקומץ רבה (דף כ\\\"ה) תנן העשרון מיעוטו מעכב את רובו ופירש\\\"י שאם חסר כל שהוא פסול.\",1,0],[8,363,12,5,\"ומ\\\"ש וחמש מנחות הבאות בנדר ונדבה יש לו להתנדב ולנדור מהם כל מה שירצה וכו'. פשוט הוא.\",2,0],[8,363,12,5,\"ומה שכתב אבל מנחת העומר ומנחת חוטא וכו' לא פחות ולא יתר. בס\\\"פ אלו מנחות (דף ע\\\"ז:) ת\\\"ר כל המנחות שריבה במדת עשרונן או שמיעט במדת עשרונן פסולות, וע\\\"כ לומר דכל המנחות הבאות שלא בנדר ונדבה קאמר:\",3,0],[8,363,12,6,\"כל המנחות הקריבות לגבי המזבח טעונות הגשה. משנה בפרק כל המנחות באות (דף ס').\",1,0],[8,363,12,6,\"ומ\\\"ש שהגשה במערב. שם במשנה (דף ס\\\"א).\",2,0],[8,363,12,6,\"ומ״ש שהוא כנגד חודה של קרן דרומית מערבית. ברייתא בפרק הקומץ רבה (מנחות דף י״ט:) ויליף לה מקראי.\",3,0],[8,363,12,6,\"ומ״ש ואינן טעונות תנופה חוץ ממנחת סוטה ועומר התנופה וכו'. משנה בפרק כל המנחות (מנחות דף ס״א):\",4,0],[8,363,12,7,\"כל המנחות הקריבות לגבי המזבח טעונות שמן ולבונה חוץ ממנחת חוטא ומנחת קנאות וכו'. משנה בפרק כל המנחות (מנחות דף נ״ט).\",1,0],[8,363,12,7,\"ומ״ש לוג שמן לכל עשרון וקומץ לבונה לכל מנחה בין שהיתה עשרון אחד בין שהיתה ששים עשרונים. פלוגתא דתנאי במשנה פרק שתי מדות (מנחות דף פ״ח) ופסק כת״ק ולא כראב״י משום דקראי מסייעי לת״ק.\",2,0],[8,363,12,7,\"ומה שכתב שאין מביאין בכלי אחד יתר על ששים עשרון כמו שיתבאר בפרק י\\\"ז:\",3,0],[8,363,12,8,\"נתן והקריב לוקה על השמן בפני עצמו וכו'. משנה בפרק כל המנחות (מנחות דף נ״ט) גבי מנחת חוטא ומנחת קנאות.\",1,0],[8,363,12,8,\"ומ\\\"ש נתן (ב) כלי שיש בו שמן או לבונה על גביה אינו עובר ולא פסל. גם זה שם במשנה:\",2,0],[8,363,12,8,\"מנחת החינוך והחביתין וכו' כמו שיתבאר. בפרק שלשה עשר:\",3,0],[8,363,12,9,\"כל המנחות הקריבות לגבי המזבח נקמצות וכו'. ר\\\"פ (דף ע\\\"ב) אלו מנחות נקמצות ושיריהם לכהנים מנחת הסלת והמחבת והמרחשת וכו'.\",1,0],[8,363,12,9,\"ומ\\\"ש חוץ ממנחת זכרי כהונה וכו'. שם ומקרא מלא הוא. ודקדק רבינו לכתוב זכרי כהונה משום דמנחת כהנת נאכלת כמו ששנינו בפרק היה נוטל סוטה (דף כ\\\"ג).\",2,0],[8,363,12,9,\"ומה שכתב רבינו הא למדת וכו'. לאפוקי מרבי שמעון דאמר בפרק אלו מנחות מנחת חוטא של כהנים נקמצת:\",3,0],[8,363,12,10,\"ומ\\\"ש הכהנת מנחתה נקמצת וכו'. כבר נתבאר:\",1,0],[8,363,12,10,\"כתב הראב\\\"ד הכהנת מנחתה נקמצת. א\\\"א כהנת זו לא ידעתי מה היא וכו'. כלומר שנשואה לכהן אפי' ישראלית כתב רבינו לקמן בסמוך שאין שירי מנחתה נאכלין וכו'. ואני אומר שאיני יודע ממה תמה הראב\\\"ד על רבינו דהא איצטריך לאשמועינן שאע\\\"פ שהיא בת כהן והיא פנויה מנחתה נקמצת ושיריה נאכלים כדין מנחת ישראל:\",2,0],[8,363,12,11,\"ולדות שנתערבו והרי כל אחד מהם ספק מנחתם נקמצת וכו'. בפרק נושאין (דף ק'):\",1,0],[8,363,12,12,\"כל הנשואות לכהנים וכו' עד מתפזרים על בית הדשן. בפרק היה נוטל (סוטה דף כ״ג) משנה וברייתא:\",1,0],[8,363,12,12,\"הקמיצה בכל מקום בעזרה. משנה בפרק קדשי קדשים (זבחים דף ס״ג).\",2,0],[8,363,12,12,\"ומ\\\"ש ואם קמץ בהיכל כשירה. מימרא בפ\\\"ק דמנחות (דף ח') ובפרק קדשי קדשים שם:\",3,0],[8,363,12,13,\"מקדשין מנחה וכו'. מימרא בפ\\\"ק דמנחות (דף ז').\",1,0],[8,363,12,13,\"ומ\\\"ש ואין מקדשין הקומץ בכלי שעל גבי קרקע. שם בעיא דאיפשיטא:\",2,0],[8,363,12,13,\"ומאימתי יותרו השירים באכילה וכו'. בפרק הקומץ רבה (מנחות דף כ״ו:) פלוגתא דאמוראי ופסק כר' יוחנן משום דמשמע התם דאמוראי סברי כוותיה:\",3,0],[8,363,12,14,\"כל המנחות הקריבות לגבי המזבח מצה. ר\\\"פ (דף נ\\\"ב:) כל המנחות באות מצה חוץ מחמץ שבתודה ושתי הלחם.\",1,0],[8,363,12,14,\"ומ\\\"ש וכן שירי המנחות וכו' עד ואם החמיצו שיריה לוקה. משנה שם (דף נ\\\"ה).\",2,0],[8,363,12,14,\"ומ\\\"ש שמותר לאכלן בדבש. שם.\",3,0],[8,363,12,14,\"ומ״ש והמחמץ אחר המחמץ חייב. מימרא דרבי יוחנן שם (דף נ״ו:) ופרק כל פסולי המוקדשין (בכורות דף ל״ג:).\",4,0],[8,363,12,14,\"ומ\\\"ש ולוקין על כל עשיה ועשיה שבה וכו'. משנה שם וחייב על לישתה ועל עריכתה ועל אפייתה. ודע דאיתא בגמרא (דף נ\\\"ו) אמר רב פפא אפאה לוקה שתים אחת על עריכתה ואחת על אפייתה והא אמרת מה אפיה מיוחדת שהיא מעשה יחידי וחייבין עליה בפני עצמה ל\\\"ק הא דעריך הוא ואפה הוא הא דעריך חבריה ויהיב ליה ואפה. ופירש\\\"י לוקה שתים דאפיה גמר עריכה היא. ערך הוא ואפה הוא לאחיובי תרתי אתרוייהו. ערך חבריה ואפה הוא מחייב חבריה חדא ואיהו תרתי אאפיה ואעריכה דגמר גמרה עכ\\\"ל. והתוס' פירשו בענין אחר ויש לתמוה למה השמיט רבינו מימרא זו:\",5,0],[8,363,12,16,\"הניח שאור על גבי העיסה והלך וישב לו וכו'. מימרא שם (ע\\\"ב):\",1,0],[8,363,12,17,\"תבל השירים בקצח או בשומשמין וכו'. ברייתא בפרק הקומץ רבה (מנחות דף כ״ג:) תבלה בקצח או בשומשמין וכו' ומשמע לרבינו דהיינו דוקא בשירים אבל בקומץ פסול מפני שהוא יתר דהא תנן בפ״ק דמנחות (דף ו') קמץ ועלה בידו גרגיר של מלח או קורט של לבונה פסול מפני שאמרו הקומץ היתר והחסר פסול:\",1,0],[8,363,12,17,\"כתב הראב\\\"ד תבל השירים בקצח או בשומשמין או בכל מיני תבלין ושמנים כשירה א\\\"א נ\\\"ל במצה האפויה נשנית וכו'. ואני אומר שאין זה מוכרח שהרי אע\\\"פ שגבלה בתבלין אפשר לשמרה שלא תחמץ כדרך שאמרו בנילושות בפושרין:\",2,0],[8,363,12,18,\"המחמץ מנחה פסולה פטור וכו'. ברייתא בפרק כל המנחות באות מצה (מנחות דף נ״ז):\",1,0],[8,363,12,18,\"חמצה כשהיא כשירה ויצאת לחוץ וכו'. שם בעיא דלא איפשיטא ולקולא.\",2,0],[8,363,12,18,\"ומ\\\"ש חמצה בראשו של מזבח אינו לוקה וכו'. ג\\\"ז שם בעיא דלא איפשיטא ולקולא:\",3,0],[8,363,12,19,\"המחמץ לחם הפנים אינו לוקה וכו' אבל מנחת נסכים אין בה מלקות וכו'. שם תניא אשר תקריבו לרבות מנחת נסכים לחימוץ דברי ר\\\"י הגלילי ר\\\"ע אומר לרבות לחם הפנים לחימוץ ופסק כר\\\"ע ואמרינן בגמ' מנחת נסכים מי פירות הם ומי פירות אינם מחמיצין אמר ר\\\"ל אומר היה ר\\\"י הגלילי מנחת נסכים מגבלה במים וכשירה משמע דר\\\"ע לא סבר הכי. ומ\\\"מ קשה דרבינו יליף לחם הפנים מכל המנחה וברייתא יליף לה מאשר תקריבו. וי\\\"ל דבגמרא הכי איתא תנו רבנן אילו נאמר אשר תקריבו לה' לא תעשה חמץ הייתי אומר אין לי בלא תעשה חמץ אלא קומץ בלבד מנחה מנין ת\\\"ל וכו' כל המנחה אשר תקריבו לה' וכו' למה לי מיבעי ליה לכדתניא אשר תקריבו לרבות מנחת נסכים לחמוץ דר\\\"י הגלילי וכו' ואיכא למידק מאי קשיא ליה אשר תקריבו לה' למה לי הא דרשינן ליה למעוטי פסולה. וי\\\"ל דמשמע ליה דהוה מצי למעוטי פסולה מדהוה ליה למיכתב כל מנחה וכתב כל המנחה משמע המנחה הידוע הכשירה ולא הפסולה וא\\\"כ אשר תקריבו לה' למה לי וקאמר לרבות מנחת נסכים לר\\\"י הגלילי ולחם הפנים לר\\\"ע. ומשמע לרבינו דאשר תקריבו לאו באנפי נפשיה מידריש אלא היינו לומר דאתא לגלויי על כל המנחה דאף לחם הפנים בכלל ומפני כך תפס כל המנחה:\",1,0],[8,363,12,20,\"החטים של מנחות אין לותתים אותם שמא יחמיצו וכו'. בס״פ כל שעה (פסחים דף מ':).\",1,0],[8,363,12,20,\"ומ\\\"ש אבל מנחת העומר הואיל והיא של צבור וכו'. שם ומאי שנא ממנחת העומר ותניא מנחת העומר לותתין אותה צבור שאני ופירש רש\\\"י שהיא קרבן צבור וכל עסקיה היו עושים ע\\\"פ ב\\\"ד ובודאי ב\\\"ד זריזים הם:\",2,0],[8,363,12,21,\"כל המנחות הנאפות וכו'. משנה בפרק כל המנחות (מנחות דף נ״ה):\",1,0],[8,363,12,22,\"ובמקום שמבשלים קדשי קדשים שם אופים את המנחות וכו'. בפרק שתי הלחם (מנחות דף צ\\\"ו) במשנה כל המנחות יש בהם מעשה כלי בפנים ובגמרא שאלו את רבי זו מנין אמר להם הרי הוא אומר ויאמר אלי זה המקום אשר יבשלו שם הכהנים את האשם ואת החטאת אשר יאפו את המנחה לבלתי הוציא אל החצר החיצונה ומפרש רבינו כפירוש התוספות דלמאי דקתני בפנים קאי ומשמע דלא גרס מאי דגריס בספרים דידן מה אשם וחטאת טעונים כלי אף מנחה נמי טעונה כלי, ואם תמצי לומר דגריס ליה רבינו יפרש דאתרוייהו קאי אבפנים ואכלי:\",1,0],[8,363,12,23,\"המנחות טחינתן והרקדתן בחוץ וכו'. בתוספתא דמנחות פרק י\\\"א מנחות יש בהן מעשה כלי בפנים טיחונן והרקדתן בחוץ לישתן ועריכתן ואפייתן בפנים. וכל שכתב רבינו אינו מדוקדק שהרי שתי הלחם ולחם הפנים קרויין מנחה ופסק רבינו בפ\\\"ח מתמידין ומוספין שלישתן ועריכתן בחוץ וכן שנוי בפ' שתי הלחם:\",1,0],[8,363,12,23,\"וכל מעשיהם כשרים בזר וכו'. בפרק הקומץ רבה (מנחות דף י״ח):\",2,0],[8,363,12,23,\"ומחבת ומרחשת היו בעזרה וכו'. בס״פ כל המנחות (מנחות דף ס״ג):\",3,0],[8,363,12,23,\"ותנור של מקדש של מתכת היה. בפ' דם חטאת (זבחים דף צ״ו) ומפרש התם טעמא דכיון דאיכא שתי הלחם ולחם הפנים דאפייתן בתנור וקדושתן בתנור ה״ל כלי שרת וכלי שרת דחרס לא עבדינן ופירש״י וקדושתן בתנור שאין נעשים בכלי שרת לפי שאין טעונים שמן ואמרינן בפרק שתי הלחם לישתן ועריכתן בחוץ ואפייתן בפנים דתנור מקדש להו:\",4,0],[8,363,13,2,\"מצות עשה לעשות כל מנחה וכו' וכיצד עשיית חביתי כ״ג וכו'. בפרק התכלת (מנחות דף נ':) תנן חביתי כ״ג לא היו באים חצאים אלא מביא עשרון שלם וחוצהו ומקריב מחצה בבקר ומחצה בין הערבים. ובפ' שתי מדות (מנחות דף פ״ז) תנן חצי עשרון מה היה משמש שבו היה מודד חביתי כ״ג מחצה בבקר ומחצה בין הערבים ובגמרא ורמינהי חביתי כ״ג לא היו באים חצאים אלא מביא עשרון שלם וחוצהו אמר רב ששת מאי מודד נמי דקתני מחלק ובפ״ק דמנחות (דף ח') גרסינן חביתין של כ״ג ר' יוחנן אמר אינה קדושה לחצאין ורבי אלעזר אמר מתוך שקריבה לחצאין קדושה לחצאין א״ר אחא מ״ט דר״י אמר קרא מנחת תמיד מחציתה בבקר הבא מנחה ואח״כ חציה ופסק כר״י.\",1,0],[8,363,13,2,\"ומ״ש ומביא עמה ג' לוגין שמן שנאמר בשמן תעשה וכו'. בפ' התכלת (מנחות דף נ״א).\",2,0],[8,363,13,2,\"ומ״ש ובולל הסולת. משנה פרק אלו מנחות (מנחות דף ע״ד:) חלות בוללן [דברי רבי] וחכ״א הסולת וידוע דהלכה כחכמים.\",3,0],[8,363,13,2,\"ומ\\\"ש וחולטה ברותחין. כך פירשו בת\\\"כ מורבכת:\",4,0],[8,363,13,2,\"ולש מכל חצי עשרון שש חלות נמצאו י״ב חלות. בפרק אלו מנחות (מנחות דף ע״ו) תנן חביתי כ״ג שהם באות י״ב וקאמר בגמ' דאתיא חוקה חוקה מלחם הפנים:\",5,0],[8,363,13,3,\"ומ\\\"ש ואחת אחת היו נעשות. נראה דטעמא משום דיליף מלחם הפנים.\",1,0],[8,363,13,3,\"ומ״ש וכיצד עושה מחלק הג' לוגין ברביעית שבמקדש רביעית לכל חלה. בפרק שתי מדות (מנחות דף פ״ח:).\",2,0],[8,363,13,3,\"ומ״ש ואופה החלה מעט ואח״כ קולה אותה וכו'. בפרק התכלת (מנחות דף נ':) אתמר חביתי כ״ג כיצד עושים אותם ר' חייא בר אבא א״ר יוחנן אופה ואח״כ מטגנה ורב אסי א״ר חנינא מטגנה ואח״כ אופה א״ר חייא בר אבא כוותיה דידי מסתברא תופיני תאפנה נא וכו' רבי אומר תאפנה נאה ר' יוסי אומר תאפנה ריבה אית ליה נא ואית ליה נאה. ופירש״י תאפנה נאה בשעת אפייתה בתנור תהא נאה ואם מטגנה תחלה הרי היא שחורה מן השמן ומן המחבת. תאפנה נא בשעת אפייתה תהא נא כמו אל תאכלו ממנו נא כלומר בכך תהא מבושלת קצת ואינה מבושלת כל צרכה והיינו טיגון בהא מודו כ״ע דתרוייהו בעינן כדכתיב על מחבת בשמן וכתיב תופיני עכ״ל. ורבינו נראה שהוא מפרש הא דא״ר יוסי תאפינה ריבה אית ליה נא ואית ליה נאה היינו לומר דמדכתיב תופיני תאפנה חד לומר שתאפה נא כלומר שלא יאפה אותה אלא קצת וזהו שכתב ואופה החלה מעט ואינו מבשלה הרבה וכן דורש שתאפה קודם הטיגון וזהו שכתב ואח״כ קולה אותה ופסק כר״י משום דנימוקו עמו וגם הכא מסתבר טעמיה:\",3,0],[8,363,13,4,\"ואח״כ חולק כל חלה וחלה לשנים באומד וכו': כתב הראב״ד ואחר כך חולק כל חלה וחלה א״א זו לא שמענו וכו'. ואין לומר שעוד יש לתמוה על רבינו מדתנן בפרק התכלת (מנחות דף נ':) וכהן שהקריב מחצה שחרית ומת ומינו כהן אחר תחתיו לא יביא חצי עשרון מביתו (ולא) חצי עשרונו של ראשון משמע שאחר שהקריב מחצה שחרית עדיין מנחת הערב היא בסלת חצי עשרון, שיש לדחות דמאי חצי עשרון דקתני חצי החלות ויש סעד לזה שלא מצינו לחביתי כ״ג שיהו נעשות אלא בשחרית בלבד וא״כ ע״כ חצי עשרונו של ראשון דקתני היינו חצי עשרון מחלות אפויות:\",1,0],[8,363,13,4,\"ולענין מ״ש הראב״ד נראה שטעמו של רבינו מדגרסינן בפרק שתי מדות (מנחות דף פ״ז:) בעי מיניה רמי בר חמא מרב חסדא חביתי כ״ג במה מחלקן ביד או בכלי פשיטא דביד דאי בכלי טורטני יכניס ויכניס כיון דבקללה כתיב לאו אורח ארעא עכ״ל. וזה מבואר כדברי רבינו דהא ההוא דקללה בלחם הוא דכתיב דקדק רבינו לכתוב באומד לרמוז למה שאמרו דחולקן ביד ולא בכלי ויש לתמוה על הראב״ד היאך כתב זו ולא שמענו.\",2,0],[8,363,13,4,\"ומ״ש ולוקח החציים וכופל כל אחד לשנים וכו'. בפרק אלו מנחות (מנחות דף ע״ה:) תנן מנחת כהנים כופל אחד לשנים ושנים לארבעה מנחות כ״ג לא היה מכפלה, ובגמרא תניא מנחת כהן גדול היה מכפלה והא אנן תנן לא היה מכפלה אמר רבה לא היה מכפלה לארבעה אבל מכפלה לשנים:\",3,0],[8,363,13,4,\"ומ״ש ואם היתה מנחת חינוך אינו חוצה וכו'. נראה שכ״כ מדתנן בפרק אלו מנחות מנחת כהן משיח לא היה מכפלה. ומפרש רבינו דמנחת כהן משיח דקתני היינו מנחה שמקריב ביום שנתחנך כדכתיב זה קרבן אהרן ובניו אשר יקריבו לה' ביום המשח אותו, ובפרק התכלת (מנחות דף נ״א:) תניא והכהן המשיח וכו' יכול יקריבוה חצאין תלמוד לומר אותה כולה ולא חציה דברי ר״י ר״ש וכו' כליל תקטר שתהא כולה בהקטרה ופירש״י שיקטירו כלה ולא לחצאין דבהא לא פליג:\",4,0],[8,363,13,5,\"מנחת הסלת כיצד היתה נעשית מביא עשרון וכו' ומודד בעשרון של מקדש. משנה בפרק שתי מדות (מנחות דף פ״ז) עשרון מה היה משמש בו היה מודד לכל המנחות לא היה מודד לא בשל ג' לפר ולא בשל שנים לאיל אלא מודדן עשרונות.\",1,0],[8,363,13,5,\"ומ\\\"ש ונותן שמן בכלי ואחר כך נותן עליו את הסלת וכו'. משנה (דף ע\\\"ד:) וברייתא פרק אלו מנחות כל המנחות הנעשות בכלי טעונות ג' מתנות שמן יציקה ובלילה ומתן שמן בכלי קודם לעשייתו.\",2,0],[8,363,13,5,\"ומ\\\"ש רבינו ובולל הסלת בו ואח\\\"כ נותנה בכלי שרת נראה שהכלי שהיה בולל בו לא היה כלי שרת אבל מדאמרינן בפ\\\"ק דמנחות (דף ט') גבי בללה חוץ לחומת העזרה ר' יוחנן אמר פסולה דאע\\\"ג דבלילה כשירה בזר כיון דעשייתו בכלי היא נהי דכהונה לא בעיא פנים מיהת בעיא משמע דבלילה בכלי שרת היא דאל\\\"כ מאי עשיתו בכלי היא דקאמר וצ\\\"ע:\",3,0],[8,363,13,6,\"מנחת המחבת והמרחשת כיצד. ג' מתנות השמן שם במשנה.\",1,0],[8,363,13,6,\"ומה שכתב ואח״כ לשה בפושרין. בפרק כל המנחות באות מצה (מנחות דף נ״ב) כל המנחות נילושות בפושרין ומשמרן שלא יחמיצו:\",2,0],[8,363,13,7,\"מה בין מחבת למרחשת מרחשת יש לה שפה וכו'. בפרק כל המנחות באות מצה (דף מ\\\"ג) פלוגתא דתנאי ופסק כר' חנינא בן גמליאל דמסתבר טעמיה ועוד דאמרינן בגמ' דב\\\"ה סברי כוותיה:\",1,0],[8,363,13,8,\"מנחת מאפה תנור כיצד וכו'. בפרק אלו מנחות (מנחות דף ע״ד:) אהא דתנן כל המנחות הנעשות בכלי טעונות שלש מתנות שמן אמרינן בגמרא למעוטי מאי אמר רב פפא למעוטי מנחת מאפה ופירש״י לאפוקי מנחת מאפה שאין כל מעשיה בכלי שהרי נאפות בתנור שאין טעונה יציקה אבל אידך שתי מתנות צריכה. ותנן תו התם חלות טעונות בלילה והרקיקין משיחה:\",1,0],[8,363,13,9,\"ומ״ש רבינו וכיצד מושחן וכו' עד שיכלה כל השמן שבלוג. בפרק אלו מנחות (מנחות דף ע״ה) תניא רקיקין הבאים בפני עצמם מביא לוג שמן ומושחן וחוזר ומושחן עד שיכלה כל שמן שבלוג ר״ש בן יהודה אומר משום ר״ש מושחן כמין כ״י ושאר השמן נאכל לכהנים ופסק כת״ק. ואיני יודע למה דהא סתם לן התם במתני' כר״ש וקי״ל סתם במתניתין ומחלוקת בברייתא הלכה כסתם דמתניתין:\",1,0],[8,363,13,10,\"כל ד' מנחות אלו האפויות כשאופין אותן אופין כל עשרון עשר חלות. בפרק אלו מנחות (מנחות דף ע״ו) פלוגתא דרבי יהודה ור״מ במשנה ופסק כר' יהודה:\",1,0],[8,363,13,10,\"ומ\\\"ש ואם רבה בחלות או מיעט כשר. שם:\",2,0],[8,363,13,10,\"וכיצד פותתים אותן כופל את החלה לשנים וכו' עד וכולן פתיתין כזיתים. שם במשנה (דף ע\\\"ה:)\",3,0],[8,363,13,10,\"ומה שכתב ואם הגדיל הפתיתין או הקטין אותם כשרים. משנה וגמרא בהקומץ רבה (דף י\\\"ח):\",4,0],[8,363,13,11,\"לא בלל לא פתת וכו'. משנה שם:\",1,0],[8,363,13,12,\"סדר הבאת המנחה כיצד וכו' עד נותנו ע\\\"ג האשים מכלי שרת. הכל בפ\\\"ב דסוטה (דף י\\\"ד:) ובתוספתא פ\\\"ק דמנחות.\",1,0],[8,363,13,12,\"ומ\\\"ש כלי שהוא ראוי לכלי שרת אמרינן שם בגמרא דהיינו לאפוקי של עץ דלא חזי לכלי שרת.\",2,0],[8,363,13,12,\"ומה שכתב ודיו אמרינן בגמ' אלא תימא שהמנחה עצמה צריך שתגע במזבח.\",3,0],[8,363,13,12,\"ומ\\\"ש וקומץ שחלקו בשני כלים אינו קדוש. פ\\\"ק דמנחות (דף ז').\",4,0],[8,363,13,12,\"ומ״ש ואם מנחת כהנים היא אינו קומץ. פלוגתא דתנאי בר״פ אלו מנחות (מנחות דף ע״ב:) ופסק כת״ק:\",5,0],[8,363,13,13,\"כיצד קומצין מנחות הנקמצות כדרך שקומץ כל האדם פושט אצבעותיו על פס ידו וקומץ. כך היא הגירסא הנכונה בספרי רבינו והדין בפ\\\"ק דמנחות (דף י\\\"א) מלא קומצו כדקמצי אינשי ופירש\\\"י כדקמצי אינשי מכניס צדי אצבעותיו ודוחק בקמח והקמח נכנס בתוך ידו ושנינו שם במשנה כיצד הוא עושה פושט את אצבעותיו על פס ידו ובגמרא אמר ליה אביי לרבא כיצד קומצין אמר ליה כדקמצי אינשי איתיביה וכו' זו קמיצה. ופירש\\\"י ממנה מתחיל הקומץ מאותה אצבע שאצל הקטנה. אלא להשוות כלומר קומץ מלא היד כדי שלא יהא חסר ואח\\\"כ מוחק באצבע קטנה מלמטה. היכי עביד וכו' אמר רב חופה שלשה אצבעותיו עד שמגיע על פס ידו וקומץ וכו' בקומצו אי בקומצו יכול בראשי אצבעותיו ת\\\"ל מלא קומצו הא כיצד חופה שלש אצבעותיו על פס ידו וקומץ. במחבת ובמרחשת מוחק בגודלו מלמעלה ובאצבעו קטנה מלמטה וזו (אחת) מעבודות הקשות שבמקדש. ופירש\\\"י כי אמרינן דכלהו אצבעות בעינן לקמיצה להשוות דאם יוציא קמח למטה מן הקומץ מוחקו ומשויהו באצבע קטנה שלא יהא מבורץ וכן מלמעלה בגודל. היכי עביד אמתניתא מהדר דקתני זו קמיצה דממנה מתחיל הקומץ. ת\\\"ל בקומצו והרים ממנה בקומצו בראשי אצבעותיו מעט שלא יגיע עד פס ידו. במחבת ומרחשת דמעשיהם אפויים וכו' פותתן וקומץ הילכך א\\\"א לפותתן דקות כ\\\"כ וכשהוא קומץ יוצאות חוץ למקומם הילכך מוחק בגודלו מלמעלה ובאצבע קטנה מלמטה. עבודה קשה שבמקדש דבקושי גדול הוא משוה שלא יהא לא חסר ולא יתר עכ\\\"ל. וכתב הר\\\"י קורקוס ז\\\"ל יש לתמוה על רבינו שלא כתב ג' אצבעות וכתב כאשר קומץ אדם כי לא נתבאר בגמרא כוונת לשון זה והוא הפך מסקנת הגמרא גם יש לתמוה למה לא כתב שזו מעבודות הקשות שבמקדש וראיתי שכתב בפרוש המשנה האמת בסדר הקמיצה והוא מה שלמדנו מהגמרא מה שאמר מלא קמצו כדקמצי אינשי ונדחו דברי האומר שהוא מהעבודות הקשות עכ\\\"ל, נראה שסמך על מה שאמר רב פפא בתר הכי פשיטא לי כדקמצי אינשי וחולק על מ\\\"ש בשלש אצבעות לבד ושמוחק ושיש בה קושי. ומ\\\"מ איני יודע איך יחלוק רב פפא על הברייתא ואיך נפסוק כרב פפא הפך הברייתא עכ\\\"ל. ואני אומר שאפשר לומר דכיון דחזינן דר\\\"פ דבתראה אמר פשיטא לי כדקמצי אינשי ממילא משמע דאיהו ידע דהאי מתניתא משבשתא היא ולא מיתניא בי רבי חייא ורבי אושעיא.\",1,0],[8,363,13,13,\"ומה שכתב קמץ בראשי אצבעותיו או מן הצדדין. בעיא שם ופירש רש\\\"י בראשי אצבעותיו שהכניס ראשי אצבעותיו בקמח ופס ידו כלפי קמח וקומץ מלא קומצו עד פס ידו כתקנו. מן הצדדין שנתן גב ידו על הקמח והוליך ידו עד שנכנס הקמח דרך צידי ידו לתוך ידו ל\\\"א מן הצדדין מצידי הכלים שלא קמץ באמצע הכלי. ואסיקנא בתיקו ומש\\\"ה נקיט לה רבינו בדיעבד לקולא. ודע דתו איבעיא לן התם ממטה למעלה מאי ופירש רש\\\"י שהכניס אצבעותיו בקמח וגב היד כנגד הקמח וקומץ וסלקא בתיקו ויש לתמוה למה השמיטה רבינו:\",2,0],[8,363,13,13,\"ודע דבמתניתין תנן התם (קמצו בראשי אצבעותיו פסול) מפני שאמרו הקומץ החסר והיתר פסול איזהו יתר שקמצו מבורץ וחסר שקמצו בראשי אצבעותיו ופירש רש\\\"י בראשי אצבעותיו מעט שלא פשטו על פס כל היד ולא הוצרך רבינו לכתוב זה שמאחר שכתב כדרך שקומץ כל אדם פושט אצבעותיו על פס ידו וקומץ ממילא משמע שכל שפיחת מזה פסול.\",3,0],[8,363,13,13,\"ומה שכתב ואם הוסיף בקומץ וכו'. זהו שכתבתי בסמוך ששנינו הקומץ היתר פסול:\",4,0],[8,363,13,14,\"אין קומץ פחות מכשני זיתים. בפ' הקומץ רבה (מנחות דף כ״ו) פלוגתא דריב״ל ור' יוחנן ופסק כריב״ל וכמו שכתבו התוספות בפרק אלו עוברין (פסחים דף מ״ג:) וגם בפרק כל המנחות (מנחות דף נ״ח:) נחלקו בזה אביי ורבא וסבר רבא כריב״ל:\",1,0],[8,363,13,14,\"ומקצת הקומץ מעכב את כולו וכו' עד ומקצת השמן מעכב את כלו. משנה בפ' הקומץ רבה (מנחות דף כ״ז).\",2,0],[8,363,13,14,\"ומ\\\"ש אין פחות מלוג לעשרון כמו שביארנו. בפי\\\"ב ובפרק זה:\",3,0],[8,363,14,1,\"מתנדב אדם ונודר עולה ושלמים וכו' כמו שביארנו. בפ\\\"ב ובפרק י\\\"ב מהלכות אלו:\",1,0],[8,363,14,1,\"ומתנדב או נודר יין בפני עצמו. משנה בס\\\"פ המנחות (דף ק\\\"ד:).\",2,0],[8,363,14,1,\"ומ\\\"ש או לבונה בפני עצמה. בסיפרא פ\\\"ט.\",3,0],[8,363,14,1,\"ומ\\\"ש או שמן בפני עצמו. בס\\\"פ המנחות פלוגתא דר\\\"ע ורבי טרפון ופסק כר\\\"ט ובס\\\"פ כל התדיר (זבחים צ\\\"א) במשנה סבר ר\\\"ש כר\\\"ע. ויש לתמוה למה דחה רבינו דבריהם ופסק כר' טרפון וכתב הר\\\"י קורקוס ז\\\"ל דטעמא משום דסתם לן תנא בפרק בתרא דמנחות (דף ק\\\"ז) כרבי טרפון דתנן הרי עלי שמן לא יפחות מלוג וכתב רש\\\"י הך סתמא כרבי טרפון וכיון שכן ה\\\"ל מחלוקת ואחר כך סתם והלכה כסתם גם בפרק אלו מנחות ובפ' כל התדיר סובר כן שמואל עכ\\\"ל ושפתים ישק, ועל הקדמתו אני מוסיף לחזק טעם לפסוק כן דרבי נמי סבור כר\\\"ט דההיא דמתני' הכי איתא הרי עלי שמן לא יפחות מלוג רבי אומר ג' לוגין.\",4,0],[8,363,14,1,\"ומ\\\"ש או עצים למערכה. בסיפרא פ\\\"ט:\",5,0],[8,363,14,2,\"שנים מתנדבים או נודרים וכו' אפילו פרידה אחת אבל המנחה אינה באה בשותפות. משנה וגמרא בס\\\"פ המנחות (דף ק\\\"ד):\",1,0],[8,363,14,3,\"הניח מנחה לשני בניו וכו'. פ\\\"ק דזבחים (דף ה'):\",1,0],[8,363,14,4,\"איזהו נדר ואי זו היא נדבה וכו' עד אינו חייב באחריותו. בריש קינים:\",1,0],[8,363,14,6,\"האומר דמי שור זה עלי עולה וכו'. משנה בערכין ס\\\"פ האומר משקלי (דף כ':) ואמר בגמרא ל\\\"ש אלא דאמר דמי שור זה עלי עולה אבל אמר שור זה עלי עולה כיון דאמר זה ומת אינו חייב באחריותו עלי להביאו קאמר:\",1,0],[8,363,14,6,\"אמר הרי עלי עולה על מנת שלא אתחייב באחריותה. פשוט בסוף מנחות:\",2,0],[8,363,14,7,\"כבר ביארנו. בסוף הלכות ביאת המקדש:\",1,0],[8,363,14,7,\"והאומר הרי עלי עולה שאקריבנה במקדש וכו' עד ואינה נזירות. משנה וגמרא בסוף מנחות (דף ק\\\"ט):\",2,0],[8,363,14,8,\"חטאת ואשם אינם באים אלא על חטא וכו'. מתבאר במשנה סוף פרק השוחט (חולין דף מ״א:).\",1,0],[8,363,14,8,\"ומה שכתב האומר הרי עלי חטאת או אשם וכו'. תוספתא פרק שלישי דתמורה הרי זה חטאת והרי זה אשם אע\\\"פ שחייב לא אמר כלום הרי אלו לחטאתי והרי אלו לאשמי אם היה חייב דבריו קיימים ואם לאו לא אמר כלום ע\\\"כ.\",2,0],[8,363,14,8,\"ומה שכתב או הרי המעות האלו לחטאתי או לאשמי דבריו קיימים. מתבאר במשנה פרק ב' דשקלים:\",3,0],[8,363,14,9,\"האומר קרבן מצורע זה או וכו'. בר״פ השג יד (ערכין דף י״ז) תנן עני שהעריך את העשיר נותן ערך עני ועשיר שהעריך את העני נותן ערך עשיר אבל בקרבנות אינו כן הרי שאמר קרבנו של מצורע זה עלי היה מצורע עני מביא קרבן עני עשיר מביא קרבן עשיר ובגמרא היה מצורע עני מביא קרבן עני ואע״ג דמדירו עשיר ואם דל הוא אמר רחמנא ולא דל הוא אמר ר' יצחק כשהיה מדירו עני וכו' אבל מדירו עשיר ה״נ דמייתי בעשירות א״כ מאי אבל בקרבנות אינו כן חדא אמצורע עני ומדירו עני וחדא למעוטי מצורע עשיר ומדירו עני. ולפי זה כשכתב\",1,0],[8,363,14,9,\"רבינו מביא הנודר קרבן עני היינו דוקא כשהיה הנודר עני אבל אם היה הנודר עשיר מביא קרבן עשיר וכן כתב רבינו בפירוש בסוף הלכות מחוסרי כפרה ולא חשש לפרש כאן לפי שסמך על מ\\\"ש שם:\",2,0],[8,363,14,10,\"האומר חטאתו ועולתו וכו'. בס\\\"פ האומר משקלי (דף כ\\\"א.) ואע\\\"ג דפליגי התם עולא פסק כשמואל:\",1,0],[8,363,14,11,\"האומר הרי עלי כנדרי רשעים וכו'. בפ\\\"ק דנדרים (דף ט') תנן כנדרי רשעים נדר בנזיר ובקרבן ובשבועה ובגמרא ודילמא הכי קאמר כנדרי רשעים לא נדרנא אמר שמואל כנדרי רשעים הריני עלי והימנו הריני בנזירות עלי בקרבן הימנו בשבועה הריני נזירות דילמא הריני בתענית קאמר אמר שמואל כשהיה נזיר עובר לפניו. וכתב הר\\\"ן אם אמר כנדרי רשעים עלי חייב קרבן ומסתברא נמי דדוקא כשהיתה בהמה מונחת לפניו. ורבינו כתב בפ\\\"א מהל' נדרים וז\\\"ל האומר לחבירו הרי עלי כנדרי רשעים אם אוכל לך שמנדריהם נזיר וקרבן ושבועה ואכל חייב בכולן וכו' אמר כנדרי רשעים הריני והיה נזיר עובר לפניו חייב בנזירות כנדרי רשעים עלי חייב קרבן כנדרי רשעים שלא אוכל ממנו חייב בשבועה עכ\\\"ל. ונראה מדבריו שהוא מפרש שדברי המשנה הם כוללים שני חלקים. האחד שאומר שמנדריהם נזיר קרבן ושבועה. השני היא שלא אמר אלא כנדרי רשעים בלבד. ונראה שדעתו שלא הצריכו נזיר עובר אלא בהריני משום דדילמא הריני בתענית קאמר אבל באומר עלי אין צריך שתהא בהמה מונחת לפניו.\",1,0],[8,363,14,11,\"ומ\\\"ש כנדרי כשרים לא נתחייב בכלום הרי עלי כנדבות כשרים הרי זה נדר בנזיר ובקרבן. שם במשנה והטעם לפי שאין הכשרים נודרים אבל הם מתנדבים בנזיר ובקרבן.\",2,0],[8,363,14,11,\"ומה שכתב וכל כינויי קרבן כקרבן. משנה שם:\",3,0],[8,363,14,12,\"אין הנודר ולא המתנדב חייב וכו'. משנה פ״ג דתרומות ומייתי לה בנזיר פרק מי שאמר (נזיר דף כ״ו) ופרק תמיד נשחט (פסחים דף ס״ג):\",1,0],[8,363,14,12,\"נתכוון לנדור בעולה וכו': בנדרים ונדבות אינו צריך להוציא בשפתיו כלום כיצד גמר בלבו שזו עולה וכו'. בפ\\\"ג דשבועות (דף כ\\\"ו:):\",2,0],[8,363,14,13,\"אחד נדרים ונדבות עם שאר הדברים שאדם חייב בהם וכו' עד שיעברו עליו רגלי השנה כולה. פירקא קמא דראש השנה (דף ד':) ואף על גב דסתם מתניתין התם כרבי שמעון לא חש לה רבינו משום דתנא קמא דברייתא פליג ורבי מאיר ורבי אליעזר בן יעקב וכיון דרבים טובא פליגי עליה לא חיישינן לסתם ועוד דמשמע דרבא סבר הכי וסתם ספרי כתנא קמא דברייתא. וכתב הר\\\"י קורקוס ז\\\"ל עוד דאפשר דהאי סתמא דמתני' לא עדיף כולי האי דלאו האי דינא אתא לאשמועינן אלא אתא למימר דניסן ראש השנה לשנים ולרבי שמעון ראש השנה לרגלים ולא למיסתם כרבי שמעון נחית עכ\\\"ל.\",1,0],[8,363,14,13,\"ומה שכתב ואין לוקין על לאו זה וכו'. פשוט הוא:\",2,0],[8,363,14,14,\"הקדיש בהמה למזבח ועברו עליו שני רגלים וכו'. פירקא קמא דראש השנה (דף ה':).\",1,0],[8,363,14,14,\"ואחד האיש ואחד האשה עובר בבל תאחר. שם (דף ו':) בעיא דאיפשיטא.\",2,0],[8,363,14,14,\"ומה שכתב אבל היורש אינו עובר בבל תאחר. גם זה שם בעיא דאיפשיטא אליבא דרבי זירא ואף על גב דמשמע דאביי פליג נקטינן דרבי זירא:\",3,0],[8,363,14,15,\"כל הקרבנות שעברו עליהם שלשה רגלים לא נפסלו וכו'. ברייתא שם:\",1,0],[8,363,14,15,\"ובכל יום ויום אחד השלשה רגלים הוא עובר בלא תאחר. מימרא דרבא שם:\",2,0],[8,363,14,15,\"ובית דין מצווין לעשותו מיד וכו' עד כופין אותו עד שיקריב וכו'. ג\\\"ז שם:\",3,0],[8,363,14,17,\"כל חייבי עולות ממשכנין אותם וכו'. משנה ס\\\"פ האומר משקלי (דף כ\\\"א).\",1,0],[8,363,14,17,\"ומ\\\"ש חוץ מחטאת נזיר וכו'. שם מימרא דרב פפא ואע\\\"ג דאמר נמי רב פפא פעמים שחייבי עולות אין ממשכנין אותם בעולת מצורע דתניא ר' ישמעאל בנו של ר\\\"י בן ברוקא אומר כשם שחטאתו ואשמו עיכבתו כך עולתו עיכבתו לא חש לה רבינו לכתבה משום דמשמע ליה דיחידאה היא דר' ישמעאל קאמר לה ורבנן פליגי עליה ואע\\\"ג דרב פפא אמר פעמים וכו' לאו משום דס\\\"ל כוותיה אלא אתא למימר דאע\\\"ג דמתניתין סתמא מיתניא חייבי עולות ממשכנין אותם האי כללא ליתיה לכ\\\"ע דלרבי ישמעאל אין ממשכנין בעולת מצורע:\",2,0],[8,363,15,1,\"האומר ולדה של זו עולה והיא שלמים וכו'. משנה פ' כיצד מערימין (תמורה דף כ״ה) וכר' יוסי דפליג אר״מ.\",1,0],[8,363,15,1,\"ומ\\\"ש אע\\\"פ שחזר בו בתוך כדי דיבור וכו'. מימרא דר\\\"פ שם:\",2,0],[8,363,15,2,\"האומר ידה של זו עולה וכו'. ברייתא בפ\\\"ק דתמורה (דף י\\\"א) וכר\\\"מ ור' יהודה ואע\\\"ג דפליגי עלייהו ר' יוסי ור\\\"ש פסק רבינו כר\\\"מ ור' יהודה משום דשקלי וטרו אמוראי אליבייהו ועוד דת\\\"ק דמתני' דתמורה כוותייהו וכדמפרש בפרק בהמה המקשה דהא דאמר ר' יוסי בפ\\\"ק דתמורה (דף י':) והלא במוקדשים האומר רגלה של זו עולה כולה עולה לאו דת\\\"ק מודה בהכי אלא ר' יוסי טעמא דנפשיה קאמר.\",1,0],[8,363,15,2,\"ומ\\\"ש והוא שיהא זה המחוייב עולה וכו'. שם (י\\\"א:) אמר מר תמכר לצרכי עולות והא קא מייתי בהמה מחוסרת אבר אמר רבא באומר הרי עלי עולה בחייה. ופירש\\\"י הרי עלי להקדיש כל האיברים שהבהמה חיה ממנה והרי כן עשה שהמוכר לא הקדיש אלא אבר שאינה חיה ממנו. וכתב עוד רש\\\"י ל\\\"א ירושלמי והא מייתי בהמה דמקדיש גופה כי ליתיה כוליה לדידיה כלומר האי לוקח הא מייתי בהמה שאין הגוף שלו ומשני כגון דאמר כזוזא מן הדא בהמה לעולה כלומר שוה זוז מבהמה זו לעולה והרי קנה זוז [וזוז] הילכך יצא דהא לא נדר עולה שלימה עכ\\\"ל. ודברי רבינו לשון ירושלמי זה.\",2,0],[8,363,15,2,\"ומ\\\"ש האומר לבה או ראשה של זו עולה וכו'. שם מודה ר' יהודה בדבר שהנשמה תלויה בו:\",3,0],[8,363,15,2,\"הקדיש אבר אחד מן העוף וכו'. שם בעי רבא בעוף מהו בהמה אמר רחמנא והא לאו בהמה היא או דילמא קרבן אמר רחמנא והא קרבן הוא תיקו. ופירש\\\"י לרבי יוסי בעי לה הקדיש רגל עוף דתור או בן יונה מי פשטה קדושה בכוליה או לא עכ\\\"ל. וא\\\"א לומר כן לדעת רבינו שהרי הוא פסק שאם בבהמה הקדיש אבר שאין הנשמה תלויה בו אינו קדוש אלא אותו אבר בלבד והיאך אפשר להסתפק בעוף אם יהיה כולו קדוש ולכן נראה לומר שרבינו מפרש דבאבר שהנשמה תלויה בו מיבעיא ליה אי קדש כולו כמו בבהמה או לא:\",4,0],[8,363,15,3,\"האומר בהמה זו חציה עולה וחציה שלמים וכו'. ברייתא פ' כיצד מערימין (תמורה דף כ״ו) ופסק כר' יוסי:\",1,0],[8,363,15,3,\"היה מחוייב חטאת וכו'. שם בהמה חציה חטאת וחציה עולה כולה תקרב עולה דברי ר\\\"מ ר' יוסי אומר תמות ושוין באומר חציה חטאת וחציה עולה שתמות וידוע דהלכה כר' יוסי ופירש רש\\\"י דכיון דאינו מחוייב חטאת הילכך תמות וקשה דהא אמרי' בפ' [קמא דנדרים] דאם אמר הרי זו חטאת אם אינו מחוייב חטאת לא אמר כלום וכבר הקשו עליו התוספות כן. ורבינו מפרש לה במחוייב חטאת וכיון שא\\\"א לו להתכפר בה משום דחציה עולה חטאת לאו בת רעיה היא הילכך תמות:\",2,0],[8,363,15,4,\"בהמת השותפין שהקדיש אחד מהם חציה שלו וכו'. בפ״ק דזבחים (י״ב:) ובפ' בתרא דכריתות ופרק כיצד מערימין ופ״ק דקידושין (דף ז') א״ר יוחנן בהמה של ב' שותפין הקדיש חציה וחזר ולקח חציה והקדישה קדושה ואינה קריבה ועושה תמורה ותמורתה כיוצא בה ש״מ תלת שמע מינה בעלי חיים נדחים וש״מ דיחוי מעיקרו הוי דיחוי ושמע מינה יש דיחוי בדמים. ובפרק מי שהיה טמא (פסחים צ״ח) קאמר גמרא על מתני' דהמפריש נקבה לפסחו דשמע מינה הני תלת דר' יוחנן, ורבינו שפסק דלא כוותיה משום דבפרק שני שעירי (יומא דף ס״ד) פליג רב עליה דר״י ואמר בעלי חיים אינם נדחים ואמרינן בגמ' דמתני' דיקא כרב דקתני אם של שם מת זה שעלה עליו הגורל לשם יתקיים תחתיו ואידך כדקאי קאי ובתר הכי מתיב מדתנן ועוד אמר ר' יהודה נשפך הדם ימות המשתלח וכו' בשלמא לרב בהא פליגי ר' יהודה ורבנן אלא לרבי במאי פליגי אמר רבא הא אמרינן דיקא מתניתין כוותיה דרב ובתר הכי קאמר גמרא (דף ס״ה) ואיכא דקא מותיב הכי ועוד אמר ר' יהודה נשפך הדם ימות המשתלח וכו' בשלמא לרב רישא פליגי בחטאת הצבור וסיפא פליגי בבעלי חיים אלא לר״י מאי. ועוד קשיא וכיון דמתניתין דיקא כרב נקטינן כוותיה ואע״ג דמתניתין ר״פ מי שהיה טמא דייקא כר' יוחנן י״ל דההיא כר״י דיחידאה הוא. ועוד דבפרק קדשי קדשים (זבחים דף נ״ט) אמרינן דר״ש ב״ר ור' ישמעאל ברבי יוסי ס״ל כרב ועוד דבפרק התערובת (זבחים דף ע״ג) אמרינן דסתם מתני' דקינים כמ״ד בעלי חיים אינם נדחים. מ״כ בשם המאירי אע״פ שהוא קדושת דמים אין לשון זה ברור אצלי שהרי בשאין בה אלא קדושת דמים ראוי לומר יותר שלא ידחה עכ״ל:\",1,0],[8,363,15,5,\"האומר דמי בהמה וכו' אם היתה ראויה ליקרב עולה נתקדשה קדושת הגוף וכו'. בפ' אלו קדשים (קי\\\"ח:) תנן המפריש נקבה לעולה וילדה זכר ירעה עד שיסתאב וימכר ויביא בדמיו עולה ר' אליעזר אומר הוא עצמו יקרב עולה וע\\\"כ לא פליג ת\\\"ק אלא משום דהוי ולד אבל בהמה עצמה שאמר עליה דמי בהמה זו עולה לכ\\\"ע אם היא ראויה נתקדשה קדושת הגוף והיא עצמה תקרב עולה. ושם (דף קי\\\"ט:) תנן המפריש נקבה לאשם תרעה עד שתסתאב ותמכר ויביא בדמיה אשם וכו' ר\\\"ש אומר תמכר שלא במום ובגמרא למה לי תסתאב תמכר כיון דלא חזיא למילתא היינו מומא אמר רב יהודה אמר רב היינו טעמא דאמרינן מיגו דנחתא לה קדושת דמים נחתא נמי קדושת הגוף אמר רבא זאת אומרת הקדיש זכר לדמיו קדוש קדושת הגוף ופירש\\\"י הקדיש זכר לדמי עולה או אשם מיגו דנחתא ליה קדושת דמים נחתא ליה קדושת הגוף וכיון דאיהו גופיה חזי להקרבה קרב.\",1,0],[8,363,15,5,\"ומ\\\"ש ואם אינה ראויה תמכר ויביא בדמיה עולה. מפשט דברי רבינו נראה שהוא פוסק כר\\\"ש דבסמוך, ויש לתמוה למה פסק כיחידאה ועוד דמאחר שבסמוך פסק כרבא דאמר זאת אומרת וכו' דאתי כת\\\"ק היאך חזר בו כאן ופסק כר\\\"ש ועוד דבפ\\\"ד מהל' פסוהמ\\\"ק פסק רבינו בפירוש כת\\\"ק דר\\\"ש ולכן צ\\\"ל דתמכר דקאמר הכא רבינו לאו למימרא דתמכר שלא במום אלא כלפי שאמר ברישא שהיא עצמה תקרב עולה אמר בסיפא שלא תקרב אלא תמכר ולא חשש לבאר שלא תמכר אלא ע\\\"י שיפול בה מום מפני שסמך על מה שכתב בפ\\\"ד מהלכות פסולי המוקדשין:\",2,0],[8,363,15,6,\"אמר על בהמה טמאה וכו' עד ויביא בדמיהן עולה. משנה בס״פ כיצד מערימין (תמורה דף כ״ז:):\",1,0],[8,363,15,7,\"האומר דמי פרה זו לעולה כל שלשים יום וכו'. ס״פ ארבעה נדרים (נדרים דף כ״ט) שור זה עולה כל שלשים יום ולאחר שלשים יום שלמים כל שלשים יום עולה לאחר שלשים יום שלמים ואקשינן היכי פקעא קדושת הגוף בכדי ואוקימנא הב״ע דאמר לדמי. וכדי לבאר דברי רבינו ודברי הראב״ד אעתיק סוגיא דגמרא שם בס״פ ארבעה נדרים (נדרים דף כ״ח) תנן הרי נטיעות אלו קרבן אם אינן נקצצות טלית זו קרבן אם אינה נשרפת יש להם פדיון הרי נטיעות אלו קרבן עד שיקצצו טלית זו קרבן עד שתשרף אין להם פדיון ובגמרא ולעולם אמר בר פדא פדאן חוזרות וקדושות פדאן חוזרות וקדושות עד שיקצצו נקצצו פודן פעם אחת ודיו עולא אמר כיון שנקצצו שוב אין פודן א״ל רב המנונא קדושה שבהן להיכן הלכה ומה אילו אמר לאשה היום את אשתי ולמחר אי את אשתי מי נפקא בלא גט אמר ליה רבא מי קא מדמית קדושת דמים לקדושת הגוף קדושת דמים פקעא בכדי קדושת הגוף לא פקעא בכדי אמר ליה אביי קדושת הגוף לא פקעא בכדי והתנן שור זה עולה כל שלשים יום ולאחר שלשים יום שלמים כל שלשים יום עולה לאחר שלשים יום שלמים אמאי קדושת הגוף היא ופקעא בכדי הב״ע דאמר לדמי אי הכי אימא סיפא לאחר שלשים יום עולה ומעכשיו שלמים אא״ב חדא בקדושת הגוף וחדא בקדושת דמים היינו דאצטריך לתנא למיתנא תרתי דסד״א קדושת הגוף לא פקעא בכדי קדושת דמים פקעה בכדי אמטו להכי תנא תרתי אלא אי אמרת אידי ואידי קדושת דמים למה לי למיתנא תרתי השתא י״ל מקדושה חמורה לקדושה קלה פקעא מקדושה קלה לקדושה חמורה צריכא למימר לימא תהוי תיובתא דבר פדא וכו' ה״ק אם לא אמר מעכשיו שלמים לאחר שלשים יום עולה הוה מידי דהוה אאומר לאשה התקדשי לי לאחר שלשים יום דמקודשת ואע״פ שנתעכלו המעות פשיטא לא צריכא דהדר ביה ע״כ בגמרא ופירש המפרש אימא סיפא דההיא דאמר שור זה לאחר שלשים יום עולה ומעכשיו ועד ל' יום שלמים הכי הוי כדאמר איהו וכו'. השתא מקדושה חמורה לקדושה קלה פקעא וכו' ותיובתא דעולא וליכא פירוקא. נימא תהוי תיובתא דבר פדא דהכא אמר דאפילו קדושת הגוף פקעא בכדי ובר פדא אמר נקצצו פודן פעם אחת דאפילו קדושת דמים לא פקעא בכדי. חסורי מחסרא והכי קתני האומר שור זה עולה כל שלשים יום ומעכשיו לאחר שלשים יום שלמים כל שלשים יום עולה לאחר שלשים יום שלמים דהואיל ואמר מעכשיו חל עליה שם שלמים מעכשיו ומשום הכי הוי שלמים לאחר שלשים יום דקדושת הגוף פקעא בהכי בכדי הואיל ואמר מעכשיו אבל אם לא אמר מעכשיו שלמים לאחר שלשים יום עולה הוי אפילו לאחר שלשים יום דהתם לא פקעא קדושת הגוף בכדי דמקודשת לאחר שלשים יום דכי לא אמר מעכשיו דמיא להא דהאומר לאשה הילך פרוטה זו והתקדשי לי לאחר שלשים יום דמקודשת לאחר שלשים יום עכ״ל. והשתא כיון דאיתותב עולא קם לה הלכתא כבר פדא וכדתריץ רב פפא ברייתא אליביה ולפי זה לא ה״ל לרבינו לאוקומה בדאמר לדמי אלא בדאמר מעכשיו. והר״ן כתב א״א בשלמא חדא בקדושת הגוף וחדא בקדושת דמים היינו דקתני תרתי וכו' אלא לדידך דסבירא לך דקדושת הגוף לא פקעא בכדי ומוקמת לה בקדושת דמים תרתי למה לי ואיתותב רבא דודאי שמעינן מהא דאפילו קדושת הגוף (לא) פקעא בכדי הילכך רבא לא ה״ל לאהדורי לרב המנונא מי מדמית קדושת הגוף לקדושת דמים דאלמא ס״ל דקדושת הגוף דהקדש לא פקעא כקדושת הגוף דאשה אלא הכי הל״ל דלא דמי אשה להקדש משום דאין אישות לחצאין וכו' אבל הקדש איתיה לזמן ידוע ואפילו קדושת הגוף פקעא ביה בכדי הילכך פרכיה דרב המנונא ליתא דהא ברייתא מסייעא ליה לעולא דכיון דברייתא מוכחא דאפילו קדושת הגוף פקעא בכדי כ״ש קדושת דמים ומש״ה אמר לימא תיהוי תיובתא דבר פדא עכ״ל. וגם זה אינו מתיישב לדעת רבינו דלפי פירוש זה אפילו קדושת הגוף פקעא בכדי וא״כ לא ה״ל לרבינו לאוקמה בדאמר לדמי. ולכן נראה לי שרבינו סובר דכיון דרבא לא אהדר מידי לאביי וגם לא אמר גמרא תיובתא דרבא טעמא הוי משום דלא חש ליה דמאי דאמר אא״ב חדא בקדושת הגוף וחדא בקדושת דמים היינו דאיצטריך לתנא למיתני תרתי וכו' לאו קושיא היא דאיכא למימר כולה חדא וכרוך ותני והכי קאמר בין שאמר שור זה עולה כל שלשים יום ולאחר שלשים שלמים בין שאמר מעכשיו שלמים ולאחר שלשים יום עולה דבריו קיימים אי נמי הכי קאמר האומר שור זה עולה כל שלשים יום ולאחר שלשים יום שלמים הוי כאומר מעכשיו שלשים יום שלמים ולאחר שלשים יום עולה דכיון דקדושה בתרייתא חמורה פשיטא דמפקעא לקדושה קלה דקדימה ואשמעינן דהוא הדין לקדושה קלה בתרייתא דמפקעא לקדושה חמורה דקדימה כיון שתלאה בזמן וכל זה בדאמר לדמי. ויש הכרח לזה דמאי דבעא אביי למימר דאף קדושת הגוף פקעא בכדי פליגי כולהו אמוראי עליה עולא ורב המנונא ובר פדא ורבא ואף אביי לא אמרה מסברא אלא משום דקשיא ליה בברייתא למה לי למיתנא תרתי וכיון דאפשר לתרוצי דלא תנא אלא חדא כדאמרן קמה לה הלכתא לכ״ע דקדושת הגוף לא פקעא בכדי וקדושת דמים פקע בכדי לכ״ע בר מבר פדא ואף רב פפא אפשר דלא אתא אלא לשנויי אליבא דבר פדא וכדמוכח לישנא דאמר לך בר פדא וליה לא סבירא ליה אלא כאינך אמוראי דסברי דקדושת דמים פקעא בכדי:\",1,0],[8,363,15,7,\"וכתב הראב\\\"ד א\\\"א ואם מכרה תוך שלשים יום חלה קדושת עולה על דמיה וכו'. מה שכתב אם יטעון טוען עלינו ויאמר קדושת דמים פקעא בכדי טעמו של טוען זה משום דרבא שהוא בתרא אומר הכי. ומ\\\"ש נשיב ונאמר בר פדא חולק על זה כלומר וכיון דפלוגתא דאמוראי היא ה\\\"ל ספיקא דאיסורא ולחומרא וא\\\"ת אית לן למיפסק כרבא דבתרא הוא ופליג אבר פדא לכך כתב ורב פפא דבתרא הוא מתרץ לברייתא אליבא דבר פדא כלומר גם בר פדא אית ליה אמורא בתרא דסבר כוותיה הילכך הוה ליה ספיקא דאיסורא ולחומרא ולא פקעא קדושה בכדי הילכך מחללין על בהמה או על מעות לצורך עולה ואח\\\"כ מקריבים שלמים. ומ\\\"ש ונ\\\"ל שהפדיון כל שהוא טעמו מדאמרינן בפירוש משמיה דשמואל הקדש שוה מנה שחללו על שוה פרוטה מחולל וא\\\"ת א\\\"כ למה תלה הדבר בנ\\\"ל הא מימרא דשמואל היא י\\\"ל דאיכא למימר דשמואל לא איירי אלא בהקדש בדק הבית דוקא ועוד דאיכא למימר דשמואל לא אמר אלא בדיעבד אבל לא לכתחלה והכא משום דלקיומי נדריה הוא אמר הראב\\\"ד דנראה ליה דלכתחלה נמי פודין בכל דהו דאי אמרת שיפדה בשוויו איכא למיחש שיקשה עליו להוציא הוצאה מרובה ולא יקיים נדרו. ומ\\\"ש ועוד דקי\\\"ל הקדיש זכר לדמיו הוא עצמו יקרב עולה וכו' כתב כן להכריע דלא פקעא קדושה זו בכדי אבל ק\\\"ל א\\\"כ מאי דשני רבא הב\\\"ע דאמר לדמי וכי אמר לדמי מאי הוי כיון דקי\\\"ל הקדיש זכר לדמיו הוא עצמו יקרב עולה נמצא שהוא קדוש קדושת הגוף ולא פקעא קדושתיה בכדי. ואפשר לדחוק ולומר דאע\\\"ג דקי\\\"ל הוא עצמו יקרב עולה מכל מקום כיון דכי אקדשיה לדמיו אקדשיה לא חמיר כקדושת הגוף ממש וכי מטי זמן ל' יום דאמר פקע קדושתיה ומיהו לאו בכדי. ונ\\\"ל שיש בלשון הראב\\\"ד חסרון אצל מ\\\"ש ובר פדא מתרץ לברייתא וכך יש להגיה פרה זו כל שלשים יום עולה לאחר שלשים יום שלמים אם אמר מעכשיו שלמים לאחר שלשים יום דבריו קיימים לא אמר מעכשיו אין דבריו קיימים:\",2,0],[8,363,15,7,\"ודע שכתב הר\\\"ן הנזכר דאמר לדמי וכגון דהוי בעל מום דאילו תם אפילו אמר לדמי קדוש קדושת הגוף דקי\\\"ל המתפיס תמימים לבדה\\\"ב מידי מזבח לא יצאו ואיכא מ\\\"ד דהאי פירוקא סליק לרבא דס\\\"ל דקדושת דמים פקעא בכדי אבל לבר פדא אכתי לא ניחא דהא לדידיה אפי' קדושת דמים נמי לא פקעא בכדי ואיכא מ\\\"ד דאפי' לבר פדא ניחא דכיון דבמקדיש לדמי עסקינן מוקי לה בר פדא בשפדאו ומש\\\"ה חיילה עליה לאחר שלשים יום קדושת שלמים וכ\\\"ת א\\\"ה פשיטא נ\\\"ל דסד\\\"א דכיון שבשעה שאמר לאחר שלשים יום שלמים לא היה ראוי לחול דקדושת עולה לא פקעא בכדי וכיון שכן נימא דאפי' לאחר שפדאה לא תחול קדושת שלמים קמ\\\"ל דקדושת שלמים מתלא תליא וקיימא וכי משכחא רווחא חיילא עכ\\\"ל:\",3,0],[8,363,15,7,\"ולדברי רבינו קשה מההיא דהקדיש זכר לדמיו הוא עצמו יקרב עולה וא\\\"כ בנדון דידן קדשה קדושת הגוף ואין לה פדיון דאין לומר דמוקי לה בבעל מום ולא בשפדאו דא\\\"כ ה\\\"ל לפרושי. ונראה לומר דסבר רבינו כמו שכתבתי לעיל דאע\\\"ג דקי\\\"ל הוא עצמו יקרב עולה מכל מקום כיון דכי אקדשיה לדמיו אקדשיה לא חמור כקדושת הגוף ממש וכי מטי זמן שלשים יום דאמר פקע קדושתיה. ועי\\\"ל דשאני הכא דאיכא תרתי לגריעותא חדא דאמר דמים תרתי דאמר לעולה בלמ\\\"ד. ועי\\\"ל דדייק רבינו שכתב פרה לומר דשור דנקט בגמרא לאו דוקא דלא מיירי אלא בנקבה שאינה ראויה לעולה ותירוץ זה מדברי הר\\\"י קורקוס ז\\\"ל:\",4,0],[8,363,15,8,\"היתה לו בהמה מעוברת וכו' והרי הן חולין. משנה בפרק כיצד מערימין (תמורה דף כ״ד:).\",1,0],[8,363,15,8,\"ומה שכתב כמו שביארנו. הוא בפ\\\"ב מהל' איסורי מזבח:\",2,0],[8,363,15,8,\"והמקדיש עובר במעי בעלת מום וכו'. פלוגתא דאמוראי בסוף פ\\\"ק דתמורה (דף י\\\"א) ופסק כר' יוחנן:\",3,0],[8,363,16,1,\"הנודר גדול והביא קטן לא יצא. משנה בסוף מנחות (דף ק\\\"ז:).\",1,0],[8,363,16,1,\"ומה שכתב קטן והביא גדול יצא. גם זה שם במשנה ופסק כתנא קמא ודלא כרבי:\",2,0],[8,363,16,2,\"נדר עולה מן הכבשים או מן האילים והביא פלגס ה״ז ספק. בעיא בסוף פ״ק דחולין (כ״ג:) וקאמר אליבא דר״י לא תיבעי לך דאמר בריה הוי וכו' כי תבעי לך אליבא דבר פדא דאמר מייתי ומתני וסלקא בתיקו. ובפרק שתי מדות (מנחות צ״א:) אסיקנא לבר פדא בקשיא. ויש לתמוה על רבינו שהי״ל לפסוק שלא יצא ידי נדרו כרבי יוחנן דאמר הכי לא להניח הדבר בספק וכבר פדא דאסיקנא בקשיא. ותירץ הר״י קורקוס ז״ל דכיון דלא אסיקנא בתיובתא הוה אפשר למפסק כוותיה וה״ל ספיקא אי הלכה כר' יוחנן או אי הלכה כבר פדא עכ״ד:\",1,0],[8,363,16,2,\"וכן הנודר עולת עוף מן התורים או מן בני היונה וכו'. בספ\\\"ק דחולין (דף כ\\\"ב:) בעיא דלא איפשיטא:\",2,0],[8,363,16,2,\"נדר שחור והביא לבן וכו'. משנה בסוף מנחות (דף ק\\\"ז:).\",3,0],[8,363,16,2,\"ומ\\\"ש זכר והביא נקבה וכו'. נלמד מק\\\"ו משחור והביא לבן:\",4,0],[8,363,16,3,\"הנודר סתם מביא מן הגדולים שבמין שנדר. הכי משמע במשנה בסוף מנחות וכן מפורש בתוספתא פרק י\\\"ג.\",1,0],[8,363,16,3,\"ומה שכתב ואם אותו מקום רגילים לקרות בסתם וכו'. שם במשנה הרי עלי עולה יביא כבש ראב\\\"ע אומר תור או בן יונה ובגמרא ולא פליגי מר כי אתריה ומר כי אתריה, ודברי רבינו בפירושה מבוארים ורש\\\"י פירש בע\\\"א:\",2,0],[8,363,16,4,\"מי שנדר שור או איל וכו'. שם במשנה הרי עלי שור יביא הוא ונסכיו במנה עגל יביא הוא ונסכיו בחמש איל יביא הוא ונסכיו בשתים כבש יביא הוא ונסכיו בסלע. ומשמע לרבינו שדמים אלו הם דמי הבינוני שבכל מין וכן כתב בפירוש המשנה וז\\\"ל אלו הדמים הם הדמים הבינונים לאלו הדברים באותו זמן באותן ארצות. ובתוספתא פרק י\\\"ג איל לא גדול ולא קטן אלא בינוני ורש\\\"י פירש בענין אחר.\",1,0],[8,363,16,4,\"ומ\\\"ש ואם הביא הכחוש יצא ידי נדרו:\",2,0],[8,363,16,5,\"האומר הרי עלי שור שוה מנה וכו' עד לא יצא. משנה בסוף מנחות (דף ק\\\"ז:) ואע\\\"ג דמסיים בה עגל בחמש יביא חוץ מנסכיו איל בשתים יביא בשתים חוץ מנסכיו כבש בסלע יביא בסלע חוץ מנסכיו ולא חש רבינו לכתבו משום דמשור במנה נשמע לאינך דכל שקבע דמים לקרבן אין הנסכים בכלל. ודע דמתני' הכי איתא שור במנה והביא שנים במנה לא יצא ואפי' זה במנה חסר דינר וזה במנה חסר דינר ולא ידעתי למה השמיט רבינו האי אפילו:\",1,0],[8,363,16,6,\"האומר שור זה עולה וכו'. גם זה משנה שם (דף ק\\\"ח:).\",1,0],[8,363,16,6,\"ומה שכתב ואפילו הביא בדמיו איל אחד יצא. שם איבעיא להו ממינא למינא מאי ופירש רש\\\"י שור זה עולה ונסתאב מהו שיביא בדמיו איל תא שמע שור זה עולה ונסתאב לא יביא בדמיו איל אבל מביא בדמיו שני אילים וכו' ש\\\"מ אי הכי מאי איריא תרי אפילו חד נמי דהא בנסתאב לרבנן לא שאני להו בין גדול לקטן תרי תנאי ואליבא דרבנן. ומשמע דהשתא סבירא להו דרבנן דסתם מתניתין אפילו ממינא למינא נמי דהא מדמינן נסתאב למינא אחרינא ופסק רבינו כרבנן דסתם מתני':\",2,0],[8,363,16,6,\"אמר שני שוורים אלו עולה וכו'. משנה שם:\",3,0],[8,363,16,6,\"ומה שכתב איל זה עולה ונפל בו מום אם רצה יביא בדמיו כבש וכן אם נדר כבש ונפסל אם רצה יביא בדמיו איל. גם זה שם במשנה:\",4,0],[8,363,16,7,\"אמר הרי עלי עולה וכו'. בפרק מרובה (בבא קמא דף ע״ח:):\",1,0],[8,363,16,7,\"אמר שור זה ודמיו עלי עולה וכו'. מימרא בסוף מנחות (דף ק\\\"ח:):\",2,0],[8,363,16,8,\"האומר אחד מכבשי הקדש וכו' עד ואח\\\"כ יצא י\\\"ח. משנה שם וגבי היו שלשה אמרינן בגמרא היכי עביד ממתין עד שיומם ומחיל ליה לקדושתיה בגדול ומפרש רבינו דה\\\"פ תחל הקדושה מאליה על הגדול.\",1,0],[8,363,16,8,\"ומ\\\"ש ואם אמר שור שבשוורי הקדש וכו'. טעמא משום דשור שבשוורי משמע המעולה שבהם:\",2,0],[8,363,16,9,\"וכן הנודר עולה מן הבקר וכו'. שם (דף ק\\\"ז) פירשתי מן הבקר ואיני יודע מה פירשתי יביא פר ועגל, ובגמרא אמאי ולייתי פר ממה נפשך הא מני רבי היא דאמר קטן והביא גדול לא יצא אי רבי אימא סיפא וכו' רישא וסיפא רבי מציעתא רבנן אין והכי קאמר דבר זה מחלוקת רבי ורבנן ופסק רבינו כרבנן.\",1,0],[8,363,16,9,\"ומ\\\"ש וכן אם קבע בכבשים ושכח מה קבע יביא איל קבע בעזים ושכח (מה קבע) יביא שעיר. מתבאר מתוך המשנה שאכתוב בסמוך.\",2,0],[8,363,16,9,\"ומ\\\"ש שכח באי זה מין מן הבהמה קבע עולתו וכו'. משנה שם מן הבהמה ואיני יודע מה פירשתי יביא פר ועגל איל שעיר גדי וטלה, ומתוך מה שכתבתי בסמוך בשם הגמרא דמתני' רבי אבל לרבנן אין צריך להביא אלא הגדול דהיינו פר ואיל ושעיר ממילא משמע שאם זכור שקבע בכבשים ושכח מה קבע יביא איל ואם זכור שקבע בעזים ושכח מה קבע יביא שעיר:\",3,0],[8,363,16,9,\"כתב הראב\\\"ד פירש אחד מהם וכו' עד הרי זה יביא שור א\\\"א המשנה אמרה יביא פר ועגל וכו'. הדבר מבואר שאין זה השגה אלא טעם לדברי רבינו למה לא פסק כסתם מתני' וכבר נתבאר.\",4,0],[8,363,16,9,\"ומ\\\"ש ואם נסתפק לו שמא קבע עולתו בעוף וכו'. שם במשנה:\",5,0],[8,363,16,10,\"נדר תודה ושלמים וכו' עד שעיר ושעירה. שם במשנה ואע\\\"פ ששנויה שם אליבא דרבי כבר נתבאר דנקטינן כרבנן דאמרי שאינו צריך להביא אלא גדול:\",1,0],[8,363,16,10,\"האומר הרי עלי עולת עוף מביא תור או וכו'. ברפ\\\"ב דכריתות (דף ט') לפי שנאמר בתורים והקריב שומע אני האומר הרי עלי עולת העוף לא יפחות משני פרידין ת\\\"ל והקריבו אפילו פרידה אחת:\",2,0],[8,363,16,11,\"האומר הרי עלי למזבח יביא קומץ לבונה וכו'. בסוף מנחות (דף ק\\\"ו:) ת\\\"ר הרי עלי למזבח יביא לבונה שאין לך דבר שקרב לגבי מזבח אלא לבונה פירשתי ואיני יודע מה פירשתי יביא מכל דבר שקרב למזבח ותו ליכא והא איכא עולה איכא עורה לכהנים והא איכא עולת העוף איכא מוראה ונוצה והא איכא נסכים לשיתין אזלי והא איכא מנחת נסכים כיון דאיכא מנחה דאכלי כהנים מינה לא פסיקא ליה. ופירש\\\"י פירשתי אחד מאותם הקריבים כולם למזבח ואיני יודע איזה מהם פירשתי וקס\\\"ד דודאי מדנחית למנינא דעתיה אמידי דלית ביה היתר שירים לכהנים ואע\\\"ג דאינו נקטר כולו כמו עולת העוף ומנחת נסכים והילכך יביא מכולם אבל היכא דאמר [הרי עלי] למזבח סתם משמע דבר שנקטר היינו לבונה. ותו ליכא אמילתא קמייתא קאי דאין לך דבר הקרב כולו למזבח אלא לבונה. מוראה ונוצה נזרקין אצל מזבח הפנימי ונבלעים במקומם וכו'. לא פסיקא ליה דלימא דבר הקרב כולו למזבח משום מנחת נסכים הואיל ואיכא מנחת נדבה דאינה כולה למזבח עכ\\\"ל. ומשמע לרבינו דכי אמרו גבי נסכים לשיתין אזלי היינו לומר דכיון שאינם נקטרים במזבח אינם בכלל אמירתו למזבח אבל בכלל אמירתו פירשתי ואיני יודע מה פירשתי הם.\",1,0],[8,363,16,11,\"ומ\\\"ש ויין בפני עצמו. כלומר מלבד היין שאביא עם מנחת נסכים דדילמא ליין לבדו נתכוון דהא קי\\\"ל מתנדבין יין דאל\\\"כ מאי קמ\\\"ל רבינו הא יין לעולם הוא קרב בפני עצמו:\",2,0],[8,363,16,12,\"אמר הרי עלי בסלע למזבח יביא כבש וכו'. בפ\\\"ב דכריתות (דף י'):\",1,0],[8,363,16,13,\"האומר הרי עלי לבונה לא יפחות מקומץ הרי עלי עצים לא יפחות משני גזרים. משנה בפ\\\"ו דשקלים.\",1,0],[8,363,16,13,\"ומ״ש עביין כמחוקות וארכן אמה. בפרק קדשי קדשים (זבחים דף ס״ב) גיזרין שעשה משה ארכן אמה ורחבן אמה ועביין כמחק גודש סאה וכתבו רבינו בפ״ז מאיסורי מזבח:\",2,0],[8,363,16,13,\"הרי עלי עץ מביא גזר אחד וכו'. ירושלמי פ\\\"ו דשקלים.\",3,0],[8,363,16,13,\"ומ\\\"ש ואם רצה להביא דמי העצים וכו'. כתב הר\\\"י קורקוס ז\\\"ל נראה שכתב כן ממ\\\"ש במעילה פרק הנהנה (דף י\\\"ט:) איכא בינייהו עצים פירוש דלרבי הם כשאר קרבן מזבח ואין להם פדיון ולרבנן הם כקדשי בדק הבית ויש להם פדיון ומביא דמים במקומם. ובהקומץ רבה (דף כ\\\"א:) מה עצים משל צבור וכו' ואמרו יכול האומר הרי עלי וכו' יביא עצים מתוך ביתו ת\\\"ל על העצים וגו' אשר על המזבח מה מזבח משל צבור אף עצים וכו' ומינה למתנדב עצים ג\\\"כ שיכול ליתן דמיהם ולפ\\\"ז יבואו העצים משל צבור באותם דמים שנותן אבל אם נתכוון להביא במעילה אין צורך להביא עצים כי מעות אלו פדיונן הם והתוס' ורש\\\"י נראה שאינם מפרשים כן ההיא דמעילה עכ\\\"ל:\",4,0],[8,363,16,14,\"מי שנדר או התנדב שמן כיצד עושין בו וכו'. בפ' כל התדיר (זבחים צ\\\"א:) אמר שמואל לדברי האומר מתנדבין שמן קומצו ושיריו נאכלים ופירש\\\"י קומצו ומקטיר הקומץ.\",1,0],[8,363,16,14,\"ומ\\\"ש ונותן עליו מלח. מתבאר מתוך מ\\\"ש בספ\\\"ה מהל' איסורי מזבח:\",2,0],[8,363,16,14,\"וכיצד עושין ביין הבא בפני עצמו נותן עליו מלח. קשיא לי שכתב בספ\\\"ה מהל' איסורי מזבח שאין לך דבר שקרב למזבח בלא מלח חוץ מיין הנסכים והדם והעצים וי\\\"ל דביין הנסכים דוקא קאמר והכא ביין הבא בנדבה.\",3,0],[8,363,16,14,\"ומ״ש ומנסכו כולו וכו'. בס״פ כל התדיר תניא דיין הבא בנדבה כולו לספלים ויש לתמוה על זה דהא גרסינן התם אמר שמואל המתנדב יין מביא ומזלפו על גבי האשים דאמר קרא ויין לנסך תקריב אשה ריח ניחוח והא קא מכבה ומסיק דסבר לה כר״ש דאמר דבר שאין מתכוין מותר וההיא ברייתא דלספלים כר' יהודה וקשה כיון דקי״ל כר״ש אמאי לא פסק כשמואל. וי״ל שטעמו מדאמרינן בפרק אלו מנחות (מנחות דף ע״ד:) גבי הא דתנן בזה יפה כח מזבח לאפוקי מדשמואל דאמר המתנדב יין מביאו ומזלפו על גבי האשים וכיון דסתם מתני' מפקא מדשמואל לית הלכתא כוותיה. וא״ת סוף סוף כיון דקי״ל דבר שאין מתכוין מותר קשיא הלכתא אהלכתא י״ל דההיא ברייתא דאמרה שאם אתה אומר לאשים איכא לא תכבה היינו לתת טענה אליבא דר' יהודה למה לא יהא על גבי האישים ולרווחא דמילתא אמר הכי אבל לפי האמת בלאו ההיא טענה קבלה היתה ביד האומר לספלים שכך היתה מצותה והיינו דבאידך ברייתא קתני סתם יין בדברי ר״ע לספלים בלא שום טענה. והר״י קורקוס ז״ל תירץ שרבינו סובר דהוי פסיק רישיה שא״א שיזלף אא״כ יכבה וכמו שאמרו שם בברייתא או אינו אלא לאשים אמרת לא יכבה ומה שהעמידו שם כר' יהודה היינו מקמי דתיקום לן דמודה ר״ש בפסיק רישיה אבל בתר דאסיקנא דמודה וליתא לדשמואל וברייתא אפי' לר״ש ויש סיוע לדברי רבינו ממה שמצינו ר״ע בהגוזל דסבר כר״ש ואיהו אמר לספלים ע״כ משום דפסיק רישיה הוא עכ״ל:\",4,0],[8,363,16,14,\"והלבונה הבאה בפני עצמה נותן עליה מלח. מתבאר מתוך מ\\\"ש בספ\\\"ה מהל' איסורי מזבח.\",5,0],[8,363,16,14,\"ומ\\\"ש וכולה לאשים. פשוט הוא דהא אינה ראויה לאכילה:\",6,0],[8,363,16,17,\"מי שנדר נדר לא יביאנו ממעות מעשר שני וכו' עד שהיא ממעות מעשר שני. משנה בסוף פרק התודה (מנחות דף פ״א:) ובגמרא תודה היא ולחמה מן המעשר יביא יביא לא סגיא דלא מייתי רב נחמן ורב חסדא אמרי רצה מביא לא רצה לא יביא. ופירש״י לא סגי דלא מייתי תרוייהו מן המעשר וכו' ולא מן החולין. רצה מביא מן המעשר. ויש לתמוה למה כתב ואם הביא הכל מן החולין יצא על אומר תודה ממעות מעשר ולחמה מן החולין ולא כתב כן על היא ולחמה מן המעשר כמו שהוא בגמרא וצ״ל שסמך על מ״ש וכן משמע ששתיהן שוות.\",1,0],[8,363,16,17,\"ומה שכתב ואף על פי שפירש שיביא לחמה מן המעשר לא יביא נסכים ממעות מעשר שני וכו'. משנה שם (דף פ\\\"ב) ונסכים בכ\\\"מ לא יבואו אלא מן החולין. וכתבו התוספות דכל דבר שכולו למזבח אינו בא מן המעשר כדתניא בסיפרי דממעט עולות דבעינן אכילה שיש בה שמחה.\",2,0],[8,363,16,17,\"ומה שכתב רבינו לפי שנאמר בהם והקריב המקריב קרבנו וכו':\",3,0],[8,363,17,1,\"הנודר מנחה מאפה תנור וכו'. משנה בסוף פרק כל המנחות באות מצה (מנחות דף ס״ג):\",1,0],[8,363,17,3,\"האומר הרי עלי במחבת והביא במרחשת וכו'. משנה בפרק המנחות (דף ק\\\"ב:). ויש בספרי רבינו חסרון מטעות סופר שכתוב אמר להביא בכלי אחד וצריך להגיה ולכתוב אמר אלו להביא בכלי אחד.\",1,0],[8,363,17,3,\"ומה שכתב לא קבען בשעת הנדר וכו'. שם בגמרא (דף ק\\\"ג):\",2,0],[8,363,17,4,\"אמר הרי עלי שני עשרונות להביא בכלי אחד וכו' עד כשתי מנחות שנתערבו. הכל משנה שם:\",1,0],[8,363,17,5,\"האומר הרי עלי מנחה וכו' משנה בפרק בתרא דמנחות (דף ק\\\"ד:) אלא שמ\\\"ש בספרים באומר הרי עלי מנחות יביא שני מיני מנחות אינו נכון אלא יביא שתי מנחות ואפילו ממין אחד. ונראה דהאי מיני טעות סופר הוא וצריך למוחקו וכך היא הגירסא הנכונה יביא שתי מנחות מחמשתן. וכן מ\\\"ש\",1,0],[8,363,17,5,\"בספרים אמר הרי עלי מיני מנחות גם הוא טעות סופר וצריך למחוק מיני ולכתוב במקומו מין וכן מצאתי בספר מוגה:\",2,0],[8,363,17,5,\"אמר הרי עלי מין מנחות וכו'. ברייתא שם (דף ק\\\"ה).\",3,0],[8,363,17,5,\"ומ\\\"ש וכן אם אמר מיני מנחה וכו'. שם בעיא ולא איפשיטא ויש לתמוה למה פסקה לחומרא דהא איכא למיחש דמייתי חולין בעזרה ונ\\\"ל דמייתי ומתנה שאם אינו חייב בה תהא נדבה:\",4,0],[8,363,17,5,\"קבע נדרו במין מהם ושכחו וכו'. משנה שם (דף ק\\\"ד:):\",5,0],[8,363,17,6,\"אין היחיד מביא מנחה בכלי אחד יותר מס' עשרון וכו'. משנה בפ' המנחות (דף ק\\\"ג:) וכתב הר\\\"י קורקוס ז\\\"ל שדקדק רבינו לכתוב אין היחיד מביא לרמוז מה שאמרו שם שהציבור מביא בי\\\"ט ראשון של חג שחל להיות בשבת ס\\\"א עשרון.\",1,0],[8,363,17,6,\"ומ\\\"ש ואמרו חכמים כל הראוי לבילה אין הבילה מעכבת בו וכו'. מימרא דרבי זירא שם (דף י\\\"ח:) ובר\\\"פ הקומץ רבה:\",2,0],[8,363,17,7,\"ומ\\\"ש אמר הרי עלי קכ\\\"א עשרון וכו'. פשוט הוא:\",1,0],[8,363,17,7,\"אמר הרי עלי עשרון וכו'. משנה בפ\\\"ב דמנחות (דף ק\\\"ד:).\",2,0],[8,363,17,7,\"ומ\\\"ש פירש נדרו ושכח וכו'. שם במשנה ופירש\\\"י יביא ס' עשרונים דבטפי מהכי ליכא לספוקי (דאין מנחה יתירה על ס' עשרונים) דאי בציר מהכי נדר לא איכפת לן דמתנה ואומר כמה שפירשתי יהיו לנדרי והשאר יהא נדבה עכ\\\"ל.\",3,0],[8,363,17,7,\"וכתב רבינו בכלי אחד כן פירש\\\"י ומוכרח הוא.\",4,0],[8,363,17,7,\"ומ\\\"ש שכח כמה עשרון פירש ובאי זה מין קבעו הרי זה מביא ששים עשרון מכל מין ומין מחמשתן. שם במשנה פירשתי מנחה של עשרונים ואיני יודע מה פירשתי יביא ס' עשרון רבי אומר יביא מנחות של עשרונות מאחד עד ששים ומשמע דהלכה כת\\\"ק. ולפי זה צריך לדחוק ולומר שמפרש רבינו דה\\\"פ מביא ס' עשרון מכל מין מחמשתן ונמצא מביא שלש מאות עשרון וטעמא משום דכיון שאינו יודע מאיזו מנחה נדר וכמה עשרונות נדר הא איכא לספוקי שמא ס' עשרון נדר ואיכא לספוקי בכל מנחה מחמשת המנחות:\",5,0],[8,363,17,8,\"ומ\\\"ש קבע נדרו ושכח כמה עשרונות נדר ובכמה כלים נדר וכו'. שם (דף ק\\\"ו) ת\\\"ר פירשתי מנחה וקבעתי בכלי אחד של עשרונים ואיני יודע מה פירשתי יביא מנחה של ס' עשרון דברי חכמים רבי אומר יביא מנחות של עשרונים מאחד ועד ס' שהם אלף ותת\\\"ל. פירשתי ואיני יודע מה פירשתי ואיזו מהם פירשתי ואיני יודע כמה פירשתי יביא ה' מנחות של ס' ס' שהן שלש מאות דברי חכמים רבי אומר יביא ה' מנחות של ס' עשרונים מאחד עד ס' שהם ט' אלפים וק\\\"ן ע\\\"כ בגמרא וכן שנוי בתוספתא. וכתבו התוספות שהם אלף ותת\\\"ל כיצד קח בידך מאחד עד ס' וצרף תחלתן לסופן עד האמצע כגון אחד וס' הם ס\\\"א שנים ונ\\\"ט הם ס\\\"א שלשה ונ\\\"ח הם ס\\\"א כן תמנה עד ל' דשלשים ול\\\"א נמי הם ס\\\"א ויעלה לך שלשים פעמים ס\\\"א עכ\\\"ל. ודברי\",1,0],[8,363,17,8,\"רבינו במה שכתב קבע נדר ושכח כמה עשרונות נדר ובכמה כלים נדר וכו' וכן מ\\\"ש ואם שכח אף באיזה מין קבע וכו' דברים מכוונים בטעמים הם לדעת ת\\\"ק דמתני' כפי מה שפירשתי דבריו במשנה אבל איני יודע ליישבם ע\\\"פ הברייתא שכתבתי לדברי חכמים ואם באנו לומר שרבינו פוסק כדברי ר\\\"מ מאי זה טעם שיהיה בזה יתיישבו לדעתו השתי בבות האחרונות שכתב רבינו אך הבבא שכתב הרי זה מביא ס' עשרון מכל מין ומין מחמשתן דהיינו שלש מאות קשה שלא מצינו לו כן לא במשנה ולא בברייתא. ואולי נוסחא אחרת היתה לו לרבינו וצ\\\"ע:\",2,0],[8,363,17,9,\"האומר הרי עלי מנחת שעורים וכו'. בפרק המנחות (דף ק\\\"ג) האומר הרי עלי מנחה מן השעורים יביא מן החטים קמח יביא סלת בלא שמן ולבונה יביא שמן ולבונה חצי עשרון יביא עשרון שלם עשרון ומחצה יביא שנים רבי שמעון פוטר שלא התנדב כדרך המתנדבים ובגמרא שם ורפ\\\"ב דנזיר (דף ט':) אמאי נדר ופתחו עמו הוא אמר חזקיה הא מני ב\\\"ש היא דאמרי תפוס לשון ראשון וכו' ר' יוחנן אמר אפילו תימא ב\\\"ה באומר אילו הייתי יודע שאין נודרין כך לא הייתי נודר כך אלא כך אמר חזקיה ל\\\"ש אלא דאמר מנחה מן השעורים אבל אמר מנחה מן העדשים לא מכדי חזקיה כמאן מוקי לשמעתיה כב\\\"ש וב\\\"ש משום תפוס לשון ראשון הוא מה לי מן השעורים מה לי מן העדשים הדר ביה כו' ורבי יוחנן אמר אפילו מן העדשים מכדי ר' יוחנן כמאן אמרה לשמעתיה כב\\\"ה וב\\\"ה משום דטעי הוא בשעורים טעי בעדשים לא טעי לדבריו דחזקיה קאמר ליה ומשמע דנקטינן כר' יוחנן דהא חזקיה הדר ביה. ובתר הכי אמרינן אמר זעירי לא שנו אלא דאמר מנחה אבל לא אמר מנחה לא. ומדברי רבינו משמע שהוא מפרש דאר' יוחנן דאמר אפי' תימא ב\\\"ה היא קאי וה\\\"ק לא שנו דבאומר אילו הייתי יודע שאין נודרין כך אלא כך יביא אלא דאמר מנחה מוכרת אבל לא אמר מנחה מוכרת אלא מנחת סמוך שאמר מנחת שעורים או מנחת חצי עשרון לאו כלום הוא. והשתא לפי זה באומר מנחת סמוך לית דין ולית דיין דלא אמר כלום ומתניתין באומר מנחה מוכרת ובהא קתני מתניתין דיביא וכששאלו אותו ואמר אילו הייתי יודע שאין נודרים כך לא הייתי נודר פטור וכדאוקי ר' יוחנן מתני' ולפ\\\"ז מ\\\"ש\",1,0],[8,363,17,9,\"רבינו או מנחה בלא שמן ולבונה ט\\\"ס הוא וצריך להגיה ולכתוב מנחת בתי\\\"ו.\",2,0],[8,363,17,9,\"ומ\\\"ש רבינו באומר מנחה מן העדשים שואלין אותו וכו' אע\\\"ג דבגמרא אמרינן דלרבי יוחנן אליבא דב\\\"ה בשעורים טעי בעדשים לא טעי משמע לרבינו דהיינו מקמי דידעינן לדזעירי אבל בתר דידעינן לדזעירי דמפליג בין מנחה למנחת כיון דמנחה מוכרת באפי נפשיה הוא כך לי מנחה מן העדשים כמו מנחה מן השעורים. ויש לתמוה על רבינו למה לא חילק בקמח בין אומר מנחת לאומר מנחה כמו שחילק באחרים השנויים עמו במשנה ודוחק לומר דרבינו תנא ושייר קמח לבד:\",3,0],[8,363,17,10,\"ומ\\\"ש נדר עשרון ומחצה וכו'. נראה דבאומר עשרון ומחצה מיירי דאמר בסמוך אמר הרי עלי מנחה קאי אבל אם לא אמר מנחה אלא אמר הרי עלי עשרון ומחצה או שאמר הרי עלי מנחת עשרון ומחצה אינו מביא אלא עשרון אחד.\",1,0],[8,363,17,10,\"ומ\\\"ש רבינו אמר הרי עלי קמח וכו' ולא הזכיר שם מנחה ה\\\"ז פטור וכו' מכלל דברי זעירי הוא נלמד דכל שלא אמר מנחה מוכרת בין שאמר מנחת סמוך בין שלא הזכיר שם מנחה פטור:\",2,0],[8,363,17,10,\"ודע דבגמרא מתיב אהא דזעירי מדתנן במתני' קמח יביא סלת בלא שמן ולבונה יביא עמה שמן ולבונה חצי עשרון יביא עשרון שלם ולא תני בהו מנחה ואוקי לכולה בדאמר מנחה והדר מתיב אי הכי אימא סיפא עשרון ומחצה יביא שנים כיון דאמר מנחה איחייב ליה בעשרון כי אמר חצי עשרון לאו כלום קאמר לא צריכא דאמר הרי עלי מנחה חצי עשרון ועשרון דכיון דאמר מנחה איחייב ליה בעשרון ולאו כלום קאמר כי הדר אמר עשרון מייתי עשרון אחרינא ויש לתמוה על רבינו למה לא חילק בין אומר הרי עלי מנחת עשרון וחצי עשרון לאומר הרי עלי מנחת חצי עשרון ועשרון כמו שחילקו בגמ'. וי\\\"ל דמשמע דגמ' הכי מיפרשא א\\\"ה אימא סיפא וכו' כיון שאמר מנחה איחייב ליה בעשרון וכי אמר עשרון לאו מוסיף אעשרון קמא אלא הוי כאומר הרי עלי מנחה של עשרון מדלא אמר הרי עלי מנחה ועשרון ולפי האמת האי לאו תיובתא הוא דאיכא למימר כיון דסתם מנחה עשרון לא היה לו לומר עשרון ומדאמר עשרון הוי כאומר ועשרון והילכך אם אמר אם הייתי יודע הייתי אומר ועשרון או שתי מנחות או שני עשרונים כדרך המתנדבים מביא שנים אלא שרצה להשיב לו כפי דרכו דלא משמע ליה דועשרון קאמר וחילק לו בין אומר חצי עשרון ועשרון לאומר עשרון ומחצה וכיון דלפום קושטא לא צריכינן לפלוגי בהכי מש\\\"ה לא מפליג רבינו:\",3,0],[8,363,17,10,\"והרב ראב\\\"ד כתב על דברי רבינו האומר הרי עלי מנחת שעורים וכו' עד פטור שלא התנדב. א\\\"א אין לסמוך על הכללות האלו שאם בדקו וכו'. הדבר מבואר שהראב\\\"ד סובר דליתא לדזעירי מפני שהוא מפרש דזעירי אליבא דחזקיה דאוקי מתני' כב\\\"ש אמרה וכן פירש\\\"י וכבר כתבתי שרבינו מפרשה דלר\\\"י אליבא דב\\\"ה אמרה משום דדוחק לומר דאיכפיל זעירי ואמוראי דשקלי וטרו אליביה לאשמועינן אליבא דב\\\"ש ועוד דכיון דחזקיה דאוקי מתני' כב\\\"ש הדר ביה היכי אפשר למימר דאתא זעירי למימר מלתא אליביה. ומ\\\"ש עוד הראב\\\"ד לר\\\"מ דאמר תפוס לשון ראשון נראה שכוונתו לומר טעם אחר לדחויי לדזעירי מהלכתא משום דבגמ' מתיב אהא דזעירי א\\\"ה ר\\\"ש פוטר שלא התנדב כדרך המתנדבים אמר רבא ר\\\"ש בשיטת ר' יוסי אמרה דאמר בגמר דבריו אדם מיתפיס משמע דת\\\"ק כר\\\"מ וכיון דקי\\\"ל דר\\\"מ ור\\\"י הלכה כר\\\"י ממילא אזדא ליה מילתא דת\\\"ק מהלכתא לזעירי ולע\\\"ד נראה שאין זה הכרח דאיכא למימר דת\\\"ק לזעירי אף לר' יוסי אמרה דס\\\"ל לזעירי דאין זה ענין לפלוגתא דר\\\"מ ור\\\"י וקל להבין. ומ\\\"ש עוד וכן מ\\\"ש בסוף שאם אמר הרי עלי קמח או הרי עלי עשרון הרי הוא כמי שלא נדר מעולם אינו כלום שהכל תלוי בבדיקה כמ\\\"ש, ספר מוטעה נזדמן להראב\\\"ד בדברי רבינו והנוסחא הנכונה או הרי עלי חצי עשרון וכבר ביארתי דבריו:\",4,0],[8,363,17,10,\"מצאתי כתוב בשם הר\\\"י בנבנשת ז\\\"ל הרי עלי מנחת שעורים וכו'. כשאמר הרי עלי מנחה מן השעורים או מנחה בלא שמן ולבונה מנחה בה\\\"א ושאלו אותו ואמר אילו הייתי יודע הייתי נודר כדרך המתנדבים ה\\\"ז חייב להקריב כדרך שמקריבים ואע\\\"ג דבשעה שנדר אין בנדרו ממש דהוי נדר ופתחו עמו דכשאמר מן השעורים הותר הנדר שנדר הרי עלי מנחה כשאמר אח\\\"כ הייתי נודר כדרך שמקריבין ביטל הפתח של נדר והוה ליה כאילו לא אמר בשעת הנדר אלא הרי עלי מנחה לבד אבל כשאמר מנחת שעורים בתי\\\"ו אע\\\"פ שיאמר אח\\\"כ אילו הייתי יודע הייתי נודר כדרך שמקריבים א\\\"א להבדיל פתח הנדר מן הנדר ולומר הרי הוא כאילו אמר מנחת בתי\\\"ו ומנחת בתי\\\"ו אין ממש בדבריו ואין צ\\\"ל כשאמר הרי עלי מנחה מן השעורים ואמר אח\\\"כ אילו הייתי יודע שמבדילין ואומרים הרי עלי דיבור בפני עצמו ומן השעורים הוה ליה כמאן דליתיה שאפשר שטעה וחשב שיכול להביא מן השעורים כיון שמצינו מנחת סוטה מן השעורים אלא אפילו אמר מן העדשים שאין יחיד ולא ציבור מקריבים עדשים אפילו הכי חייב כנ\\\"ל לפרש דבריו, וצריך לעיין בגמ' ובזה נסתלקה קושיית הראב\\\"ד בהשגות עכ\\\"ל:\",5,0],[8,363,17,10,\"וכן האומר הרי עלי תודה בלא לחם וזבח בלא נסכים. כך היא הגירסא הנכונה וכך היא שנויה בברייתא פרק התודה (מנחות דף פ״א:) ודע דבההיא ברייתא מסיים בה כופין אותו ומביא תודה ולחמה זבח ונסכים ובגמ' אמאי נדר ופתחו עמו הוא אמר חזקיה הא מני בית שמאי היא דאמרי תפוס לשון ראשון וכו' רבי יוחנן אמר אפי' תימא ב״ה באומר אילו הייתי יודע שאין נודרים כך (אלא כך) לא הייתי נודר כך אלא כך ומאי כופין דקא בעי הדר ביה וכבר נתבאר בסמוך דנקטינן כר' יוחנן. ויש לדקדק על דברי רבינו שכתב כאן ה״ז פטור ולא כתב שואלין אותו וכו' כמו שכתב לעיל ואין לומר שמפני שכאן אמר בפירוש בלא לחם ובלא נסכים לעולם הוא פטור עד שיאמר אילו הייתי יודע שאין מקריבים כך הייתי נודר כדרך הנודרים דלעיל נמי אמר בפירוש בלא שמן ולבונה ואפילו הכי כתב ששואלין אותו לכך נראה דהה״נ דבהא נמי שואלין אותו כדלעיל ולא חש להאריך דיגיד עליו רעו:\",6,0],[8,363,17,11,\"האומר הרי עלי לחמי תודה יביא תודה ולחמה וכו'. מימרא דרב הונא בספ\\\"ק דחולין (דף כ\\\"ג:).\",1,0],[8,363,17,11,\"ומ\\\"ש הרי עלי לפטור תודתו של פלוני וכו'. נלמד מתוך הסוגיא שם:\",2,0],[8,363,17,12,\"מתנדב או נודר אדם יין בפני עצמו. משנה בס\\\"פ המנחות (דף ק\\\"ד:).\",1,0],[8,363,17,12,\"ומ\\\"ש ואין מתנדבים לוג יין ולא שני לוגין וכו'. משנה שם:\",2,0],[8,363,17,14,\"ומ\\\"ש נדר ה' לוגין אומרים לו השלם ששה וכו'. בס\\\"פ המנחות (דף ק\\\"ד) איבעיא להו יש קבע לנסכים או אין קבע לנסכים ה\\\"ד כגון דאייתי חמשה אי אמרת אין קבע לנסכים משיך ומקריב ארבעה מינייהו דחזי לאיל ואידך הוי נדבה ומשמע התם דבעיין לא איפשיטא ופסקה רבינו לחומרא.\",1,0],[8,363,17,14,\"ומ\\\"ש אבל אם נדר לוג או ב' פטור. הכי משמע שם בברייתא דקתני שמתנדבין [נסכים וכמה] שלשה לוגין וכו' יכול יפחות ת\\\"ל ככה:\",2,0],[8,363,17,14,\"ואין מתנדבים ולא נודרים פחות מלוג שמן וכו'. מפורש בגמרא אצל דין שיבא בסמוך ואליבא דתנא קמא:\",3,0],[8,363,17,15,\"האומר הרי עלי יין לא יפחות משלשה לוגין הרי עלי שמן לא יפחות מלוג. משנה בסוף מנחות (דף ק\\\"ז):\",1,0],[8,363,17,15,\"פירש נדרו ושכח כמה לוג נדר וכו'. שם במשנה פירשתי ואיני יודע מה פירשתי יביא כיום המרובה ובגמרא תנא כיו\\\"ט הראשון של חג שחל להיות בשבת:\",2,0],[8,363,18,1,\"כל הקרבנות כולם וכו' מ\\\"ע להקריבן בבית הבחירה וכו'. בסיפרי פ' ראה:\",1,0],[8,363,18,1,\"וכן מצות עשה להיות כל אדם מטפל וכו'. בסיפרי פרשת ראה והוזכר בתמורה פ' אלו קדשים (דף קט\\\"ז:) וצריך טעם למה פרט רבינו וכתב קרבנות בהמה:\",2,0],[8,363,18,2,\"המקריב קרבן חוץ לעזרה וכו'. בריש פרק השוחט והמעלה (זבחים דף ק״ז):\",1,0],[8,363,18,2,\"ומ\\\"ש כרת וכו'. פשוט הוא בתורה.\",2,0],[8,363,18,2,\"ומה שכתב בשוגג מביא חטאת קבועה. משנה בריש כריתות:\",3,0],[8,363,18,3,\"וכן השוחט קדשים חוץ לעזרה וכו'. פשוט הוא.\",1,0],[8,363,18,3,\"ומ\\\"ש ואם שחט בשוגג מביא חטאת קבועה. ג\\\"ז משנה בריש כריתות:\",2,0],[8,363,18,4,\"והיכן הזהיר על השחיטה בחוץ בהיקש וכו'. בריש פרק השוחט ומעלה (זבחים דף ק״ז):\",1,0],[8,363,18,5,\"השוחט קדשים והעלם בחוץ חייב שתים וכו'. משנה שם (זבחים דף ק\\\"ז) וכתנא קמא.\",1,0],[8,363,18,5,\"ומה שכתב שחט בפנים והעלה בחוץ חייב על העליה וכן אם שחט בחוץ והעלה בפנים חייב על השחיטה. שם במשנה:\",2,0],[8,363,18,6,\"אינו חייב אלא על שחיטת קדשים הראויין ליקרב לגבי המזבח וכו'. משנה פ' בתרא דזבחים (דף קי\\\"ב):\",1,0],[8,363,18,7,\"שחט בחוץ מחוסר זמן בגופו או בבעלים וכו'. משנה ובגמרא שם וכת\\\"ק:\",1,0],[8,363,18,10,\"אשם תלוי וחטאת העוף הבאה על הספק וכו': כתב הראב\\\"ד לא ידעתי מאין הוציא זה ואני מצאתי בתוספתא וכו'. ויש לתמוה עליו שכתב שלא ידע מאין הוציא זה דהא תניא פ\\\"ד דכריתות (דף י\\\"ח) השוחט אשם תלוי בחוץ ר\\\"מ מחייב וחכמים פוטרים ופירש\\\"י וחכמים פוטרים דלא איקבע איסורא דשמא חולין הוא והתוספתא שכתב הראב\\\"ד הוא בפי\\\"א דקרבנות ולא חש לה רבינו משום דאתיא כר\\\"מ דלא בעי קביעותא לאיסורא ולא קיימא לן כוותיה אלא כחכמים:\",1,0],[8,363,18,10,\"כתב הר\\\"י קורקוס ז\\\"ל דכיון דאמרינן דטעמא דחכמים בברייתא משום דלא איקבע איסורא הוא הדין והוא הטעם לחטאת העוף הבא על הספק דמ\\\"ש הרי לא נקבע האיסור וברייתא נקט אשם תלוי משום דשכיח:\",2,0],[8,363,18,10,\"אשם מצורע ששחטו בחוץ שלא לשמו חייב וכו'. מימרא בפ' בתרא דזבחים (דף קי\\\"ד:):\",3,0],[8,363,18,10,\"וכל קרבן שהוא פטור על שחיטתו בחוץ כך הוא פטור על העלאתו. נלמד ממה שכתב רש״י בפרק השוחט והמעלה (זבחים דף קי״א) אמתני' דהמולק את העוף:\",4,0],[8,363,18,11,\"שני שעירי יום הכפורים ששחטן בחוץ וכו' עד שהרי אינו ראוי לבא לפני ה'. משנה וגמ' פ' בתרא דזבחים (דף קי\\\"ב:):\",1,0],[8,363,18,11,\"וכתב הראב\\\"ד שני שעירי וכו' א\\\"א אני שונה בברייתא עד שלא הגריל וכו'. ואני אומר שמעתא הכי איתא בפרק בתרא דזבחים אהא דתנן שעיר המשתלח שהקריבו בחוץ פטור שנאמר ואל פתח אהל מועד לא הביאו וכל שאינו ראוי לבא אל פתח אהל מועד אין חייבין עליו אמרינן בגמ' (דף קי\\\"ג) ורמינהו קרבן שומע אני אפילו קדשי בדק הבית וכו' ת\\\"ל ואל פתח אהל מועד לא הביאו וכו' יכול שאני מוציא שעיר המשתלח תלמוד לומר לה' לרבות שעיר המשתלח ל\\\"ק כאן קודם הגרלה כאן לאחר הגרלה אחר הגרלה נמי הא איכא וידוי אלא אמר רבי מני ל\\\"ק כאן קודם וידוי כאן לאחר וידוי ופירש\\\"י הא איכא וידוי דבעי ליכנס להתודות עליו עכ\\\"ל. ופירוש ברייתא זו לדעת רבינו מבואר ורש\\\"י פירש בע\\\"א. ומה שהקשה הראב\\\"ד על רבינו ממה ששנו בברייתא פרק שני שעירי עד שלא הגריל עליהם יש לומר דלמאי דמסיק בפרק בתרא דזבחים צריך לשנויי דתנא לוידוי הגרלה קרי ליה:\",2,0],[8,363,18,12,\"השוחט שלמים בחוץ קודם שיפתחו דלתות ההיכל פטור וכו'. מימרא בפרק שני שעירי (יומא דף ס״ב:):\",1,0],[8,363,18,12,\"השוחט את הפסח בחוץ וכו'. שם (דף ס\\\"ג) פלוגתא דאמוראי ופסק כרבין משום דרב אשי דבתרא הוא מתני הכי והאי שאר ימות השנה היינו בר מיום י\\\"ד קודם חצות שאם שחטו אז בפנים פסול כמ\\\"ש בפרק א' מקרבן פסח וכבר נתבאר בפרק זה שכל שאינו ראוי ליקרב אין חייבין עליו משום שחוטי חוץ:\",2,0],[8,363,18,13,\"בהמת חולין שעוברה קדשי מזבח אסור לשחטה בחוץ וכו'. בסוף פ\\\"ק דתמורה (דף י\\\"ב) בעא מיניה אביי מרב יוסף היא חולין וולדה שלמים ושחטה בחוץ מהו מי מיחייב עליה משום שחוטי חוץ או לא א\\\"ל מי קרינן ביה והביאום לה', ל\\\"א א\\\"ל ראוי לפתח אהל מועד חייבים עליו בחוץ:\",1,0],[8,363,18,14,\"גנב והקדיש ואחר כך שחט בחוץ חייב. בפרק הניזקין (גיטין דף נ״ה:) גנב והקדיש ואח״כ טבח ומכר משלם תשלומי כפל ואינו משלם תשלומי ד' וה'. ותני עלה בחוץ כי האי גוונא ענוש כרת ואי אמרת יאוש כדי לא קני כרת מאי עבידתיה אמר רב שיזבי כרת וכו' שעל ידי דבריהם בא לו אוקמוה רבנן ברשותיה כי היכי דליחייב עליה אמר רבא הא ודאי קא מיבעיא ליה כי אוקמוה רבנן ברשותיה משעת גניבה או משעת הקדשה למאי נפקא מינה לגיזותיה וולדותיה מאי הדר אמר רבא מסתברא משעת הקדשה שלא יהא חוטא נשכר. ויש לתמוה על רבינו שכתב ומאימתי העמידוה ברשותו כדי לחייבו עליה כרת שהרי בהדיא אמרו למאי נ״מ לגיזותיה וולדותיה משמע דלא נפקא לן למידי אחרינא והיאך כתב רבינו דנ״מ לחייבו עליה כרת. ועוד דלענין לחייבו עליה כרת מה לי אם העמידוה ברשותו משעת גניבה או משעת הקדשה כיון שהעמידוה ברשותו הקדשה סגי לחייבו כרת אם ישחטנה בחוץ וצ״ע:\",1,0],[8,363,18,15,\"היתה הבהמה כולה בחוץ וצוארה בפנים ושחט חייב וכו' אחד השוחט במקדש וצואר בפנים ושאר גוף הבהמה בחוץ וכו' אבל השוחט בגגו של היכל הרי זה פטור. בפרק השוחט ומעלה (דף ק\\\"ז:) אמר עולא השוחט על גגו של היכל חייב הואיל ואין ראוי לשחיטת כל זבח מתקיף לה רבא א\\\"כ נכתוב רחמנא אל מחוץ למחנה ולא בעי אל פתח אהל מועד אל פתח אהל [מועד] למה לי לאו למעוטי גגו (של היכל) ולרבא א\\\"כ נכתוב אל פתח אהל מועד במחנה אל מחוץ למחנה למה לי לאו לאיתויי גגו וכו' כולה בפנים וצוארה בחוץ [בחוץ פשיטא] אמאי קפיד רחמנא אשחיטה שחיטה בחוץ היא אלא לאיתויי כולה בחוץ וצוארה בפנים.\",1,0],[8,363,18,15,\"ומ\\\"ש רבינו אחד השוחט במקדש וצוארה בפנים וכו' שנאמר אל פתח אהל מועד לא יביאנו אינו נוח לי דהא מהאי קרא לא ילפינן אלא למעוטי גגו של היכל. ונראה לי שצריך להגיה ולכתוב אבל השוחט בגגו של היכל אע\\\"פ שאינו ראוי לשחיטה כלל הרי זה פטור שנאמר ואל פתח אהל מועד לא יביאנו. א\\\"נ יש לומר דמשמע לרבינו דמואל פתח אהל מועד יליף שפיר דבעינן שתהא צוארה בפנים:\",2,0],[8,363,18,16,\"שנים שאחזו בסכין ושחטו בחוץ פטורין וכו'. משנה פ' השוחט ומעלה (דף ק\\\"ח) ומייתי לה בגמ' מדכתיב ההוא ובת\\\"כ מייתי לה מדכתיב דם שפך. ולא ידעתי למה שינה רבינו להביא מפסוק אחר:\",1,0],[8,363,18,16,\"ואחד ששחט בחוץ וכו'. משנה פרק השוחט ומעלה חומר בשחיטה מבעליה וכו' שהשוחט להדיוט חייב:\",2,0],[8,363,18,17,\"השוחט בחוץ בלילה וכו'. בפרק השוחט ומעלה (דף קי\\\"א:) איפליגו במתני' ת\\\"ק ור\\\"ש ואמרינן עלה בגמ' אמר זעירי שחיטת בהמה בלילה איכא בינייהו וה\\\"ק השוחט בהמה בפנים בלילה והעלה בחוץ פטור שחט בחוץ בלילה והעלה בחוץ חייב ר\\\"ש אומר כל שחייבים עליו בחוץ וכו'.\",1,0],[8,363,18,17,\"ומ״ש וכן אם קבל בכלי חול בפנים וזרק בחוץ פטור. שם על משנה זו רבא אמר קבלה בכלי חול איכא בינייהו וה״ק המקבל בכלי חול בפנים והעלה בחוץ פטור המקבל בכלי חול בחוץ והעלה בחוץ חייב ר״ש אומר כל שחייבים עליו בחוץ וכו' ואע״ג דאסיקנא דר״ש אמלק בחוץ והעלה בחוץ קאי מ״מ משמע דלא הוו בעו הני אמוראי למימר אליבא דת״ק אלא מאי דקים להו דהוי דינא הכי ואע״ג דבפ' המזבח מקדש (זבחים דף פ״ד) אמר רבי יוחנן השוחט בהמה בלילה בפנים והעלה בחוץ חייב הא איתותב ואסיקנא בתיובתא ואע״ג דבתר הכי אמרינן ואיבעית אימא וכו' שינויא דחיקא הוא ולא סמכינן עליה:\",2,0],[8,363,18,17,\"וכתב הראב\\\"ד השוחט בחוץ בלילה א\\\"א בחיי ראשי אין צורת ההלכה כפירושו וכו'. ביאור הדברים שרבינו מפרש שכשאמרו העלה בחוץ בין ברישא בין בסיפא אלילה דקתני רישא קאי. והראב\\\"ד מפרש דלא קאי אלילה דרישא אלא היינו לומר שהעלה ביום ומפני כך הוצרך לתת טעם אחר לדבר. ואיני יודע מה עול מצא בדברי רבינו כי רחק מעליו דפשטא דמילתא משמע דטפי עדיף למימר דסיפא אלילה דרישא קאי מלמימר דסיפא לא הוי בגוונא דרישא:\",3,0],[8,363,18,18,\"וכן המולק את העוף בחוץ פטור וכו' עד סוף הפרק. משנה (דף קי\\\"א) שם.\",1,0],[8,363,18,18,\"ועל מה שכתב רבינו שהשחיטה בחוץ כשירה והרי היא כמליקה בפנים כתב הראב\\\"ד זה הטעם אין בו טעם אלא שלא חייב הכתוב בעוף אלא מה שחייב בבהמה עכ\\\"ל. ולא זכיתי להבין דבריו שהרי ע\\\"כ חייב בעוף מה שלא חייב בבהמה שהרי מלק בפנים והעלה בחוץ בעוף חייב ובבהמה פטור ושחט בפנים והעלה בחוץ בבהמה חייב ובעוף פטור:\",2,0],[8,363,19,1,\"אין המעלה בחוץ חייב עד שיעלה לראש המזבח וכו'. משנה פרק השוחט ומעלה (דף ק\\\"ח) ופסק כת\\\"ק:\",1,0],[8,363,19,1,\"ואינו חייב עד שיעלה לשם וכו'. שם במשנה המעלה להדיוט פטור ובגמ' יליף לה מדכתיב ואל פתח אהל מועד לא יביאנו לעשות אותו לה':\",2,0],[8,363,19,2,\"אינו חייב אלא על העלאת דבר הראוי לאשים ולמזבח וכו'. נלמד ממה שיבא בסמוך. ובפרק השוחט ומעלה (דף ק\\\"ט) דריש מדכתיב ואל פתח אהל מועד לא יביאנו כל המתקבל בפתח אהל מועד חייבים עליו בחוץ:\",1,0],[8,363,19,3,\"מכאן אמרו הזורק את הדם. בפרק קמא דזבחים (דף ד':) מה לזביחה וזריקה שכן עבודה וחייבין עליה בחוץ.\",1,0],[8,363,19,3,\"ומה שכתב או המקטיר איברי עולה או אימורין או קומץ או לבונה או קטרת או מנחת כהנים או מנחת נסכים. משנה בפרק השוחט ומעלה (דף ק\\\"ט:).\",2,0],[8,363,19,3,\"ומ\\\"ש או המנסך ג' לוגין יין או מים בחוץ חייב. שם בברייתא ומשמע הברייתא שנסוך מים זה יהא בחג וכן פירש\\\"י ורבינו קיצר במובן:\",3,0],[8,363,19,4,\"אבל הזורק שירי הדם בחוץ וכו'. שם (דף ק״י:) במשנה רבי נחמיה אומר שירי הדם שהקריבן בחוץ חייב משמע דת״ק פטר ואמרינן בגמ' (דף קי״א) השתא דאמר רב אדא וכו' מחלוקת (אי שירים מעכבי) בשירים הפנימים אבל בשירים החיצונים דברי הכל לא מעכבי כי קאמר רבי נחמיה בשירים הפנימים וא״כ לת״ק דר' נחמיה אפי' שירים הפנימים שהקריבן בחוץ פטור. ועוד דבפ' איזהו מקומן (זבחים דף נ״ב) מסיק רב פפא דכ״ע בין ר״א בין ר' ישמעאל שירים אין מעכבין ומהדר התם לאשכוחי תנא דסבר שירים מעכבין.\",1,0],[8,363,19,4,\"ומה שכתב וכן המנסך יין או מים פחות משלשה לוגין בחוץ פטור וכו'. נלמד מברייתא שכתבתי בסמוך.\",2,0],[8,363,19,4,\"ומ\\\"ש וכן המעלה מבשר חטאת מבשר אשם וכו' פטור. משנה בפ' בתרא דזבחים (דף קי\\\"ב:):\",3,0],[8,363,19,5,\"המעלה את הבהמה כולה בחוץ חייב וכו'. משנה פרק השוחט ומעלה (דף ק\\\"ט:) המקריב קדשים ואימוריהם בחוץ חייב ובגמרא (דף ק\\\"י) אמאי והא איכא חציצה ופירש רש\\\"י שהבשר שאינו ראוי להקטרה חוצץ בין אימורים למערכה ודכוותה בפנים לאו העלאה היא דרחמנא אמר על העצים אשר על האש אמר שמואל בשהפכן וכו' רב אמר מין במינו אינו חוצץ ופסק כרב דהלכתא כוותיה לגבי שמואל באיסורי ואף על גב דרבי יוחנן אמר אפילו שלא הפכן הא מני רבי שמעון היא ולא חיישי ליה דהא משום דמוקי למתניתין כיחידאה וקרוב הדבר שאף הוא לא אמרה אלא לומר דאפשר לאוקומי מתניתין הכי ולא לומר שתהא הלכה כיחידאה:\",1,0],[8,363,19,5,\"ומה שכתב אבל המעלה מנחה שלא נקמצה פטור וכו' קמצה וחזר קומצה לתוכה וכו'. משנה וגמרא שם:\",2,0],[8,363,19,6,\"היוצק והבולל והפותת וכו'. משנה וברייתא בפ' בתרא דזבחים (דף קי\\\"ב):\",1,0],[8,363,19,7,\"פרה אדומה ששרפה חוץ ממקום שריפתה וכו'. משנה שם:\",1,0],[8,363,19,7,\"ומ\\\"ש אחר שהתודה עליו. נתבאר בפ' זה:\",2,0],[8,363,19,7,\"אבל קדשים פסולין שהיה פיסולן בקדש וכו'. משנה בפ' השוחט ומעלה:\",3,0],[8,363,19,9,\"כל דבר שחייבין על העלאתו בחוץ וכו' כיצד הקומץ או לבונה והאימורין וכו' ואינו חייב על החסר. משנה וברייתא שם (דף ק\\\"ט:):\",1,0],[8,363,19,9,\"ומ\\\"ש הוציאו שלם וחסר בחוץ והעלה ה\\\"ז ספק. שם (דף ק\\\"י) בעיא דלא איפשיטא:\",2,0],[8,363,19,10,\"העלה אבר שאין בו כזית בשר והיה העצם משלימו לכזית חייב. שם (דף ק\\\"ז) פלוגתא דר\\\"י ור\\\"ל ופסק כר\\\"י.\",1,0],[8,363,19,10,\"ומ\\\"ש היה מלח משלימו לכזית וכו'. שם (דף ק\\\"ח) בעיא דלא איפשיטא.\",2,0],[8,363,19,10,\"ומ\\\"ש ועולה ואימוריה מצטרפין לכזית. משנה שם (דף ק\\\"ט) המעלה כזית מן העולה ומן האימורים בחוץ חייב:\",3,0],[8,363,19,11,\"העלה וחזר והעלה חייב על כל אבר ואבר. משנה שם (דף ק\\\"ח) העלה וחזר והעלה חייב על כל עליה (ועליה) דברי ר\\\"ש ר' יוסי אומר אינו חייב אלא אחת ובגמרא אמר ר\\\"ל מחלוקת בארבעה וחמשה איברים וכו' אבל אבר אחד דברי הכל אינו חייב אלא אחת ור' יוחנן אמר מחלוקת באבר אחד וכו' אבל בארבעה וחמשה איברים ד\\\"ה חייב על כל אבר ואבר ופסק כר' יוסי אליבא דר' יוחנן וז\\\"ש בסמוך העלה אבר חסר פטור. ומ\\\"ש שם הראב\\\"ד לא האיר דבריו שהרי שנינו המעלה כזית מעולה ומאימורים בחוץ חייב אלמא לא קפדינן אאבר שלם, יש לומר שאין זו ראיה דכיון דלרבי יוסי אם העלה וחזר והעלה אבר אחד אינו חייב אלא אחת והיינו אפילו יש בו כמה זיתים ממילא משמע דהא דתנן העלה כזית מעולה ומאימוריה בחוץ חייב שאותו זית הוא אבר אי נמי כשהוא ממקום שאינו אבר כגון שהוא בשר או חלב. ומ\\\"ש וכי איתמרא שמעתא במוקטרי פנים שיחסרו בהקטרתן והוציאן והקטירן בחוץ דהלכה כרבי יוסי דפטור עכ\\\"ל. ואין פשט המשנה מורה כדבריו דקתני העלה וחזר והעלה משמע דכל העליות בחוץ הן:\",1,0],[8,363,19,11,\"זרק הדם והעלה האיברים חייב שתים וכו'. כך היא הגירסא הנכונה והדין שם (דף ק\\\"ז) זורק מקצת דמים בחוץ מנ\\\"ל (דחייב) מדתניא דם יחשב לרבות הזורק דברי רבי ישמעאל ר\\\"ע אומר או זבח לרבות הזורק ובגמ' שם א\\\"ר אבהו שחט וזרק לדברי ר' ישמעאל חייב אחת לדברי ר\\\"ע חייב שתים וכו' אביי אמר אפילו לר' ישמעאל חייב שתים להכי פלגינהו קרא שם תעלה ושם תעשה שחט וזרק והעלה לדברי הכל חייב שתים ופי' רש\\\"י לרבי ישמעאל נפקא ליה זריקה מדם שפך בעונש של שחיטה. אינו חייב אלא אחת דחד כרת וחד לאו הוא לר\\\"ע נפקא ליה מאו זבח דכתיב גבי העלאה חייב שתים משום דשמות מוחלקין. שם תעשה ושם תעלה הזכיר העליה לבדה והשאר כללן בעשיה אחת למימרא דלא מחייב אכולהו אלא חדא. פלגינהו קרא הוציא העלאה מכלל שאר עשיות למימר דמיחייב עלה באפי נפשה ואשארה באפי נפשייהו. שחט וזרק והעלה לד\\\"ה בין לרבי ישמעאל בין לר\\\"ע חייב שתים לרבי ישמעאל [כיון דכולהו בהעלה] מיחייב אהעלאה חדא דאית ליה קרא בהדיא ואשחיטה וזריקה חדא דמחד קרא נפקי ולר\\\"ע אשחיטה מיחייב חדא ואהעלאה וזריקה חדא עכ\\\"ל. ומדברי רבינו נראה שהוא מפרש דכי אמר אביי להכי פלגינהו קרא לר\\\"מ נמי הוה האי טעמא ולפיכך כתב שהרי חילק הכתוב בין מעלה לעושה ולפ\\\"ז כי אמרינן בשחט וזרק והעלה חייב שתים לר\\\"ע נמי אהעלאה חייב אחת ועל שחיטה וזריקה אחת ובכך עלו דברי רבינו כהוגן אלא שיש בו קצת קיצור שה\\\"ל לכתוב שאם שחט וזרק והעלה אינו חייב אלא שתים. וי\\\"ל דמשמע ליה דהא לא איצטריך לאשמועינן דמדכלל כולן בלעשות אותו ממילא משמע דלא מחייב אכולהו אלא חדא ומאי דאיצטריך לאשמועינן היינו שאם העלה וזרק חייב נמי אהעלאה מפני שהוציא הכתוב העלאה מכלל שאר עשיות וממילא משמע דה\\\"ה לשוחט וזרק והעלה אינו חייב אלא שתים:\",2,0],[8,363,19,11,\"כתב הראב\\\"ד כיצד הקומץ וכו' א\\\"א הספרים שלנו אינם משוים לזו הגירסא וכו'. והנך רואה שגירסת רש\\\"י כגירסת רבינו ונראה מסוף דברי הראב\\\"ד שהיה גורס בדברי רבינו שחט וזרק חייב שתים וכתב שהוא גירסא משובשת שאינו חייב אלא אחת ולא אמר שחייב שתים אלא במעלה ושוחט או זורק משום דפלגינהו קרא ואין ספק שטעות סופר היה בספרו והנוסחא הנכונה כמו שכתבתי. ומ\\\"מ מה שכתב בדברי הראב\\\"ד אף לדברי ר\\\"ע חייב שתים איני יכול ליישבו דא\\\"כ צריך לומר דלרבי אבהו לרבי ישמעאל חייב שתים ולרבי עקיבא אינו חייב אלא אחת והם דברים הפוכים כמו שנתבאר. והר\\\"י קורקוס ז\\\"ל כתב שמתוך דברי רש\\\"י נראה לי דגריס אביי אמר אפילו לר\\\"ע אינו חייב אלא אחת:\",3,0],[8,363,19,11,\"העלה אבר חסר פטור שנאמר וכו'. נתבאר בסמוך:\",4,0],[8,363,19,12,\"שנים שאחזו באבר והעלוהו בחוץ חייבים וכו'. משנה שם:\",1,0],[8,363,19,13,\"הזורק מקצת מתנות בחוץ חייב. משנה שם (דף ק\\\"י):\",1,0],[8,363,19,13,\"המקבל דם חטאת בכוס אחד וכו'. משנה שם (דף קי״א:) חטאת שקבל דמה בכוס אחד נתן בחוץ וחזר ונתן בפנים בפנים וחזר ונתן בחוץ חייב שכולו ראוי (לבא) בפנים קבל בב' כוסות נתן שניהם בפנים פטור שניהם בחוץ חייב אחד בפנים ואחד בחוץ פטור אחד בחוץ ואחד בפנים חייב על החיצון והפנימי מכפר. ובגמ' (דף קי״ב) בפנים ונתן בחוץ שירים נינהו הא מני ר' נחמיה היא וכו'. אי ר' נחמיה אימא סיפא קבל דמה בשני כוסות וכו' אחד בפנים ואחד בחוץ פטור והאמר רבי נחמיה שיירי הדם שהקריבן בחוץ חייב סיפא אתאן לת״ק דר״א בר״ש דאמר כוס עושה דיחוי לחבירו. ופלוגתא דראב״ש ות״ק בפרק כל הפסולין (זבחים דף ל״ד) ושם מתבאר דלדברי שניהם אין השני ראוי ואם כן אינו חייב עליו בחוץ. ויש לתמוה על רבינו שכתב אחד בפנים ואחד בחוץ חייב וכבר השיגו הראב״ד וכתב הזורק מקצת וכו' עד או אחד בפנים א״א זה אינו כלום דאחד בפנים ואחד בחוץ בין למ״ד עושה את חבירו דחוי בין למ״ד עושה אותו שירים שני לא חזי בפנים עכ״ל וצ״ע. והר״י קורקוס ז״ל כתב וז״ל ונראה שרבינו סומך על מ״ש שם למה הדבר דומה למפריש חטאתו ואבדה והפריש אחרת תחתיה ואח״כ נמצאת הראשונה והרי שתיהן עומדות שחט שתיהן בחוץ חייב אחד בפנים ואחד בחוץ פטור אחד בחוץ ואחד בפנים חייב וכו' ושאלו בגמרא דמה למדנו מדמיון זה ותירצו הא קא משמע לן הא מני רבי היא אבודה בשעת הפרשה מתה וה״ק טעמא דאבדה הא הפריש שתי חטאות לאחריות חדא מינייהו מעיקרא בטלה היא וכו' פירוש ולא אמרינן בכי הא שאם הקריב אחד בפנים ואחד בחוץ פטור אלא חייב בכל גוונא. וסובר רבינו שהכוונה לומר שגם גבי כוסות דמי לשתיהן לאחריות כי מתחלה לאחריות עומדות וזהו למה״ד כלומר מה שאני פוטר בכוסות היכא דאחד בפנים ואחד בחוץ היינו למאן דסבר דיחוי דדמי לאבודה אבל אם הפריש לאחריות חייב והוא הדין בכוסות דלא אמרינן דיחוי אלא דמי לאחריות אי נמי אפילו אם הוא דיחוי אחר שהקריב אחד בפנים מתחלה לא היה דחוי וחייב. ומ״מ דחוק הוא פירוש זה ואולי גירסא אחרת היתה לו וצ״ע עכ״ל:\",2,0],[8,363,19,14,\"הקומץ והלבונה של מנחה וכו' וכן שני בזיכי לבונה וכו' שהקריב אחד מהם בחוץ וכו'. משנה בפרק השוחט והמעלה (דף ק\\\"א) ופסק כת\\\"ק:\",1,0],[8,363,19,15,\"מי ששחט קדשים בזמן הזה והעלם חוץ לעזרה. שם (דף ק\\\"י:) פלוגתא דרבי יוחנן וריש לקיש ופסק כר\\\"י:\",1,0],[8,363,19,16,\"השוחט קדשי נכרים בחוץ חייב. במשנה פ' ב\\\"ש (זבחים מ\\\"ה) פלוגתא דר\\\"ש ור' יוסי ופסק כר' יוסי.\",1,0],[8,363,19,16,\"ומה שכתב וכן המעלן בחוץ פשוט הוא דדין מעלה שוה לדין שוחט:\",2,0],[8,363,19,16,\"והנכרים מותרים להקריב עולות לשם בכל מקום וכו'. בסוף זבחים (דף קט\\\"ז):\",3,0],[8,363,19,16,\"סליק הלכות מעשה הקרבנות בס\\\"ד\",4,0],[8,364,1,1,\"מצות עשה להקריב שני כבשים עולות בכל יום וכו'. מפורש בתורה:\",1,0],[8,364,1,2,\"ואימתי זמן שחיטתן וכו'. משנה פ\\\"ג דתמיד (דף ל') ובפרק ג' דיומא (דף כ\\\"ח).\",1,0],[8,364,1,2,\"ומ״ש פעם אחת דחקה השעה. בפ״ו דעדיות ואמרינן בפ' תפלת השחר (ברכות דף כ״ז) דהכי הלכתא.\",2,0],[8,364,1,2,\"ומה שכתב רבינו שהיה זה בבית שני רבינו כתב כן שם בשם הירושלמי:\",3,0],[8,364,1,3,\"תמיד של בין הערבים שוחטין אותו משיאריך הצל וכו'. עד קודם שיכנס השבת. בריש פרק תמיד נשחט (פסחים דף נ״ח):\",1,0],[8,364,1,6,\"אע\\\"פ שאין שוחטין אחר תמיד של בין הערבים וכו'. בפרק ב' דמגילה (דף כ':) תנן כל היום כשר לקריאת המגילה וכו' ולהקטרה ופירש\\\"י בהקטרת קומץ קאמר וכו' ואינה כשירה אלא ביום:\",1,0],[8,364,1,6,\"ומקטירין איברי עולות והאימורים עד חצי הלילה כמו שביארנו במעשה הקרבנות. פ\\\"ד:\",2,0],[8,364,1,6,\"ואיברים ואימורים שלא נתאכלו וכו' מהפכים בהם כל הלילה עד הבקר וכו':\",3,0],[8,364,1,7,\"איברים של תמיד דוחין את הטומאה ואין דוחין את הטומאה אלא בערב שבת וכו'. כך היא הנוסחא בספרי רבינו וה״פ אלא בע״ש בלבד מקטירים כלומר מבעוד יום בלבד מקטירין אותם ולא בליל שבת והוא מדאמרינן בס״פ טרף בקלפי (יומא דף מ״ו) אמר רב הונא תמיד תחלתו דוחה סופו אינו דוחה מאי אינו דוחה רב חסדא אמר דוחה את השבת ואינו דוחה את הטומאה ורבא אמר דוחה את הטומאה ואינו דוחה את השבת ופסק כרבא דבתרא הוא. וכתב הריטב״א בספ״ק דיומא אם לא היה פנאי להקטירם בערב שבת מעלים אותם בליל שבת לראש המזבח ואינם נפסלים בראש המזבח בלינה אפילו עד כמה ימים וזו שאמרו לא הסריח בשר קדש מעולם אפילו היו בראש המזבח כמה ימים עכ״ל:\",1,0],[8,364,1,7,\"חלבי שבת קריבין בלילי יו״ט וכו'. בר״פ תמיד נשחט (פסחים דף נ״ט:) רמי ליה רב ספרא לרב כתיב לא ילין לבקר זבח חג הפסח לבקר הוא דלא ילין הא כל הלילה ילין והכתיב עולת שבת בשבתו ולא עולת חול בשבת ולא עולת חול ביו״ט א״ל וכו' הכא בי״ד שחל להיות בשבת עסקינן דחלבי שבת קריבים ביום טוב. ובסוף פרק אלו קשרים (שבת דף קי״ד) תנו רבנן עולת שבת בשבתו לימד על חלבי שבת שקריבים ביוה״כ יכול אף של יוה״כ בשבת ת״ל בשבתו דברי ר' ישמעאל ר״ע אומר עולת שבת בשבתו למד על חלבי שבת שקריבים ביו״ט יכול אף ביוה״כ ת״ל בשבתו וידוע דהלכה כר״ע:\",2,0],[8,364,1,9,\"אין פוחתין מששה טלאים המבוקרים וכו'. משנה וגמרא פ' שני דערכין (דף י\\\"ג).\",1,0],[8,364,1,9,\"ומה שכתב ואע\\\"פ שהיו מבקרין אותו מתחלה לא היו שוחטין את התמיד עד שמבקרין אותו שניה קודם שחיטה לאור האבוקות ומשקין אותו מים בכוס של זהב. משנה פ\\\"ג דתמיד (דף ל'):\",2,0],[8,364,1,10,\"והכל כמעשה העולה שכתבנו במעשה הקרבנות. בפרק ו' ופרק ט':\",1,0],[8,364,1,10,\"ולא היו כופתין את הטלה וכו'. ריש פ' ד' דתמיד לא היו כופתין את הטלה אלא מעקדין אותו ובגמ' (דף ל\\\"א:) תנא יד ורגל כעקידת יצחק בן אברהם. לא היו כופתין את הטלה מאי טעמא רב הונא ורב חסדא חד אמר משום בזיון קדשים וחד אמר משום דמהלך בחוקי המינין מאי בינייהו איכא בינייהו דכפתיה בשיראי אי נמי בהוצא דדהבא:\",2,0],[8,364,1,10,\"ועל מה\",3,0],[8,364,1,10,\"שכתב שלא יחקו את המינין: כתב הראב\\\"ד א\\\"א אני שמעתי שמא יצטער בכפייתו ויפרכס עד שיטיל מום באחד מאבריו ובגמרא מצאנו דפליגי רב הונא ורב חסדא חד אמר משום בזיון קדשים וחד אמר משום חקי המינין ואפשר שהטעם הראשון הוא בזיון קדשים אבל חקי המינין לא ידעתי מהו עכ\\\"ל. ודע שפירש המפרש לא היו כופתין את הטלה בשעת שחיטה ד' רגלים יחד וכו' אלא מעקדים אותו [יד ורגל] כעקידת יצחק בן אברהם ובגמרא פירש מפני שהוא מהלך בחוקי המינין כשמקריבין זבח לע\\\"ז הם כופתין אותו כך ד' רגלים יחד. דכפתיה בשיראי וכו' משום חקי המינין איכא עכ\\\"ל. ופסק רבינו כמאן דאמר משום דמהלך בחוקי המינין שהוא טעם יותר כולל ולחומרא.\",4,0],[8,364,1,10,\"ומה שכתב וכך היתה עקידתו וכו' עד שיהיו נשחטין כנגד השמש. פרק ד' דתמיד (שם):\",5,0],[8,364,1,12,\"טעו או שגגו אפילו הזידו וכו'. משנה וברייתא פרק התכלת (מנחות דף מ״ט ונ') ודלא כר״ש:\",1,0],[8,364,2,1,\"מצות עשה להיות אש יקודה על המזבח תמיד וכו' אף על פי שהאש ירדה מן השמים מצוה להביא אש מן ההדיוט וכו'. בסוף פירקא קמא דיומא (דף כ\\\"א:):\",1,0],[8,364,2,2,\"בבקר עורכים עצים וכו'. בפרק שני דתמיד (דף כ\\\"ט:) וכן מצוה להעלות וכו' וכן מוסיפים שני גזרים עם תמיד של בין הערבים וכו' עד בכהן אחד. בפרק שני דיומא (דף כ\\\"ו:) יליף לה מקראי:\",1,0],[8,364,2,4,\"ושלש מערכות של אש עושים בראש המזבח בכל יום וכו' עד בצדי מערכה גדולה. בפ' טרף בקלפי במשנה (דף מ\\\"ג:) וברייתא (דף מ\\\"ה) פלוגתא דתנאי ופסק כר\\\"י:\",1,0],[8,364,2,6,\"המכבה אש המזבח לוקה וכו' אפילו גחלת אחת ואפי' הורידה מעל המזבח וכבה לוקה. מימרא בס״פ כל התדיר (זבחים דף צ״א).\",1,0],[8,364,2,6,\"ומ״ש אבל אש מחתה ואש מנורה וכו'. בס״פ טרף בקלפי (יומא דף מ״ו:) אתמר המכבה אש מחתה ומנורה אביי אמר חייב רבא אמר פטור ואמרינן בלישנא בתרא דאחתיה אארעא וכבייה דכ״ע ל״פ דפטור כי פליגי דכבייה בראשו של מזבח וידוע דהלכה כרבא:\",2,0],[8,364,2,7,\"כשמסדר עצי מערכה גדולה מסדרה במזרח המזבח. בפ' ב' דתמיד (דף כ\\\"ט) סידר את המערכה גדולה מזרחה.\",1,0],[8,364,2,7,\"ומ\\\"ש ויהיה מראה שהתחיל לסדר מן המזרח. זה פירוש על מה ששנינו שם וחזיתה מזרחה.\",2,0],[8,364,2,7,\"ומ\\\"ש וריוח היה בין הגזרים וכו'. שם:\",3,0],[8,364,2,7,\"כתב הראב״ד כשמסדר עצי המערכה וכו'. א״א זה כתב במקום וחזיתה מזרחה ולא כיון יפה וכו'. ודברי הראב״ד על כל בבא זו אינם מוכרחים. ומה שפירש הראב״ד בתפוח אין נראה כן מדברי רש״י שם ובר״פ גיד הנשה (חולין דף צ':):\",4,0],[8,364,2,8,\"ואחר שמסדר מערכה גדולה וכו' עד של לחם הפנים. משנה בפ\\\"ב דתמיד (דף כ\\\"ט) ומייתי לה בגמרא ר\\\"פ קדשי הקדשים (דף נ\\\"ח) ופירש\\\"י עצי תאנה בשל תאנה היו רגילין וטעם אגדה הוא שבו היתה תקנה לאדם הראשון ויעשו להם חגורות. מערכה שניה של קטרת אצל מערכה גדולה היו מסדרים מערכה קטנה ליטול ממנה גחלים להכניס על מזבח הפנימי ג' קבין לכל בקר וערב להקטיר עליהם קטרת, ובמס' יומא פרק טרף בקלפי בסופיה ילפינן מקרא דעל מזבח החיצון צריך להיות מערכה לכך כנגד מערבית דרומית של מזבח ומשוך לצד צפון להרחיקו מן הקרן ד' אמות וטעמא מפרש לקמיה וכו' באומד חמש סאין גחלים לפי אומד ה' סאין גחלים היו נותנים שם עצים. ובפ' קדשי הקדשים מפרש טעמא למה היתה כנגד קרן מערבית דרומית משוך מן הקרן לצד צפון ד' אמות גם נתבאר שם למה נותנין שני הבזיכים במערכה של קטרת:\",1,0],[8,364,2,9,\"מערכה שלישית של קיום האש וכו'. ומ״ש ולא יצית האש למטה וכו'. בפ' טרף בקלפי (יומא דף מ״ה):\",1,0],[8,364,2,10,\"הרמת הדשן מעל המזבח בכל יום מ\\\"ע וכו' והיא עבודה מעבודות כהונה. בפ\\\"ב דיומא (דף כ\\\"ג).\",1,0],[8,364,2,10,\"ומ\\\"ש ובגדי כהונה שתורם בהן הדשן יהיו פחותים וכו' עד קדרה לרבו. שם, אלא שלא אמרו שם כן אלא על הוצאת הדשן לא על תרומת הדשן וגם דקרא דופשט את בגדיו ולבש בגדים אחרים אוהוציא את הדשן כתיב לא אוהרים את הדשן. ויש לתמוה על רבינו ששינה. ומצאתי כתוב בשם הריטב\\\"א בפ\\\"ק דיומא דתרומת הדשן צריכה בגדים פחותים משאר עבודות מדכתיב ולבש הכהן מדו בד ומכנסי בד ילבש על בשרו דהל\\\"ל ומכנסי בד על בשרו ואמרו שם בגמרא ילבש לרבות את השחקים פירוש בגדי כהונה פחותין לפי שאינו דרך ארץ שימזוג כוס לרבו בבגדים שבישל הקדרות עכ\\\"ל. וע\\\"פ זה אפשר ליישב דברי רבינו דמדכתיב ילבש ילפינן דתרומת הדשן הויא בבגדים פחותים משום דרך ארץ א\\\"כ כי כתיב ופשט את בגדיו ולבש בגדים אחרים לא אהוצאת הדשן בלבד קאי אלא אף אהרמת הדשן וה\\\"ל כאילו כתיב והרים את הדשן וכבר קודם לכן פשט את בגדיו ולבש בגדים אחרים ומש\\\"ה תפס רבינו הכתוב כאילו כתיב ופשט את בגדיו ולבש בגדים אחרים קודם והרים את הדשן ולא הוצרך רבינו לכתוב גבי הוצאת הדשן שיהיו בגדיו פחותים דמהרמת הדשן הוא נלמד וכל שכן נמי הוא:\",2,0],[8,364,2,11,\"אימתי תורמין הדשן וכו'. משנה בסוף פ\\\"ק דיומא (דף כ'):\",1,0],[8,364,2,12,\"כיצד תורמין מי שזכה לתרום טובל וכו' עד והמנורה. בפ\\\"ק דתמיד (דף כ\\\"ח):\",1,0],[8,364,2,12,\"כתב הריטב\\\"א פ\\\"ק דיומא שלא היה חותה מהגחלים שנעשו מהעצים שבמערכה אלא דוקא מהגחלים של איברים שנשרפו כמ\\\"ש אשר תאכל האש את העולה אלמא שמהגחלים שנעשו מאיברי העולה היה חותה ויש לזה ראיה גדולה בגמרא, ולא ידעתי למה לא הוזכר בשום מקום תרומת גחלים אלא תרומת הדשן וכתב על זה הר\\\"י בנבנשת ז\\\"ל נלע\\\"ד כי בעת תרומת הדשן היו שם קצת איברי עולה שנתאכלו וקצת שלא נתאכלו לגמרי והם גחלים בוערות קרוב להיות דשן לזה לא היה חותה מאיברי העולה הנשרפין קצת אשר למעלה במערכה אבל מפנה את הגחלים אילך וחותה מאברי העולה אשר הם למטה שנשרפו לגמרי עכ\\\"ל:\",2,0],[8,364,2,13,\"אחר שירד זה שתרם רצים אחריו הכהנים וכו' עד מפני שהוא נוי למזבח. בפ\\\"ב דתמיד (דף כ\\\"ח:):\",1,0],[8,364,2,14,\"כל מי שירצה מהכהנים ממלא מן הדשן וכו': ומעולם לא נתעצל הכהן מלהוציא את הדשן. בפ\\\"ב דתמיד:\",1,0],[8,364,2,15,\"ואע\\\"פ שאין הוצאתו לחוץ עבודה אין בעלי מומין מוציאין אותו. בפ\\\"ב דיומא (דף כ\\\"ג) ופסק כת\\\"ק אליבא דר' יוחנן:\",1,0],[8,364,2,15,\"וכשמוציאין אותו חוץ לעיר וכו': ולא יפזרנו שם וכו'. בפרק כל שעה (פסחים דף כ״ו) ובשילהי תמורה (דף ל״ד) אמרינן דתרומת הדשן אסור בהנאה דתניא ושמו בנחת ושמו כולו ושמו שלא יפזר:\",2,0],[8,364,2,15,\"כתב הראב\\\"ד ושמו שיניחנו בנחת. א\\\"א זה לא נאמר אלא על תרומת הדשן וכו'. טעמו של הראב\\\"ד משום דכי כתיב ושמו בתרומת הדשן שהכהן תורם בכל יום שחרית ונותנו אצל המזבח כמו שכתב רבינו לעיל בפרק זה הרמת הדשן מעל המזבח מ\\\"ע על דשן זה הוא שאמרו שהוא אסור בהנאה ומועלין בו לא על שאר הדשן שנשאר שם שמורידין אותו למטה ומוציאין אותו חוץ לעיר:\",3,0],[8,364,2,15,\"כתב הר\\\"י קורקוס ז\\\"ל נראה שדין ההנאה למד רבינו מההיא דפרק ב' דמעילה שנחלקו רב ור\\\"י בנהנה מאפר שעל תפוח לאחר שהרימו הדשן דר\\\"י סבר שמועלין ורב סבר שאין מועלין והלכה כר\\\"י וכן פסק רבינו בהל' מעילה:\",4,0],[8,364,3,1,\"מצות עשה להקטיר הקטורת וכו': לא הקטירו בבקר יקטירנו בין הערבים. משנה בפרק התכלת (מנחות דף מ״ט):\",1,0],[8,364,3,1,\"ומ\\\"ש ואפילו היו מזידין. שם כת\\\"ק דר' שמעון.\",2,0],[8,364,3,1,\"ומ\\\"ש ואין מחנכין מזבח הזהב אלא בקטורת של בין הערבים. שם פלוגתא דתנאי (דף נ') ואמר אביי דמסתברא כמ\\\"ד הכי:\",3,0],[8,364,3,2,\"כמה מקטירין ממנה בכל יום וכו'. פ\\\"ק דכריתות (דף ו':) ובפ\\\"ד דיומא (דף מ\\\"ג:):\",1,0],[8,364,3,2,\"מזבח שנעקר מקטירין הקטורת במקומו. מימרא פרק קדשי קדשים (זבחים נ\\\"ט):\",2,0],[8,364,3,2,\"וקטורת שפקעה מעל המזבח אפילו קרטין שבה אין מחזירין אותן. מימרא פרק הקומץ רבה (מנחות דף כ״ו:) ופירש״י אפילו קרטים שלימים וחשובים שבה:\",3,0],[8,364,3,3,\"בעת שמקטירין הקטורת בהיכל וכו'. בספ״ק דכלים ואיתא בפ' טרף בקלפי (יומא דף מ״ד). וכתב רבינו בעת שמקטירים הקטרת בהיכל בכל יום לרמוז על מה שכתב בגמרא דבקטרת יוה״כ שהוא לפני ולפנים אין צריך לפרוש אלא מההיכל שהוא קרוב אבל מבין האולם ולמזבח אין צריך לפרוש.\",1,0],[8,364,3,3,\"ומ\\\"ש וכן בשעה שיכנס בדם חטאות הנעשות בפנים וכו'. ברייתא וגמרא שם:\",2,0],[8,364,3,4,\"כיצד סדר הקטרת הקטורת בכל יום וכו'. בפרק שלישי דתמיד (דף ל':):\",1,0],[8,364,3,4,\"ומה שכתב מי שזכה בקטרת נוטל כלי מלא קטרת וגדוש וכו'. בפרק ששי דתמיד (דף ל\\\"ג):\",2,0],[8,364,3,5,\"כתב הראב\\\"ד וכיצד חותה וכו'. עד שנתאכלו במערכה א\\\"א אין זה בנוסחא המדוייקת לענין קטרת אלא לענין תרומת הדשן עכ\\\"ל. ואני אומר פשטא דמתניתין שבפרק הנזכר משמע דלענין קטרת מיתניא ואיני יודע נוסחא אחרת:\",1,0],[8,364,3,7,\"ומ\\\"ש ומקדים לפניהם זה שדישן המזבח הפנימי וכו' עד ויקטיר המקטיר וישתחוה ויצא. בפרק ו' דתמיד שם:\",1,0],[8,364,3,10,\"דישון המנורה וכו'. יתבאר בסמוך:\",1,0],[8,364,3,10,\"והדלקת הנרות דוחה את השבת ואת הטומאה וכו'. בתורת כהנים פרשת אמור:\",2,0],[8,364,3,11,\"וכמה שמן הוא נותן לכל נר וכו'. משנה וברייתא פ' שתי מדות (מנחות דף פ״ח פ״ט)\",1,0],[8,364,3,11,\"ומ\\\"ש ואין מחנכין את המנורה וכו'. משנה בפ' התכלת (דף ס\\\"ט):\",2,0],[8,364,3,12,\"מהו דישון המנורה כל נר שכבה מסיר הפתילה וכו'. פ' שתי מדות (מנחות דף פ״ח:) נר שכבתה נדשן השמן נדשנה הפתילה כיצד עושה מטיבה ונותן בה שמן במדה ראשונה ומדליקה. ופירש״י נר שכבתה בחצי הלילה או קודם אור היום. נדשן השמן נדשנה הפתילה האי נדשן השמן לאו דוקא אלא הכי קאמר כשם שהפתילה שכבתה אין לה תקנה שהרי היא כדשן כן השמן שנשאר בנר הרי הוא כדשן ואין לו תקנה דהואיל ונדשנה הפתילה נדשן השמן כיצד הוא עושה מטיבה שמשליך כל מה שבנר לחוץ ונותן בה השמן ופתילה אחרת ומדליקה. במדה ראשונה חצי לוג כמו שנתן מתחילה או כמה שחסרה במה שזורק לחוץ.\",1,0],[8,364,3,12,\"ומ\\\"ש והדלקת הנרות היא הטבתם זהו דעת רבינו שהוא סובר שגם בבקר מדליק הנרות דכי כתיב והקטיר עליו אהרן קטרת סמים בבקר בבקר בהטיבו את הנרות פירוש בהטיבו בהדליקו. והאחרונים חולקים עליו ואומרים שאין הדלקת הנרות אלא בין הערבים ופירוש בהטיבו אינו הדלקה אלא תיקון הפתילות וכל זה תמצא באורך בתשובות הרשב\\\"א סי' ש\\\"ט ומ\\\"ט. ומדברי רש\\\"י שכתבתי בסמוך וממה שכתב בפירוש התורה נראה שדעתו כדעת האחרונים וכן נראה שהוא דעת הראב\\\"ד ממה שכתב בפרק שני מעבודת יוה\\\"כ וכן דעת אונקלוס.\",2,0],[8,364,3,12,\"ומ\\\"ש ונר שמצאו שלא כבה מתקנו:\",3,0],[8,364,3,13,\"נר מערבי שכבה וכו'. בפרק ו' דתמיד.\",1,0],[8,364,3,13,\"ומ\\\"ש אבל שאר הנרות כל נר שכבה מהם מדליקו מנר חבירו בפרק ג' דתמיד (דף ל':):\",2,0],[8,364,3,13,\"כתב הראב\\\"ד נר מערבי וכו'. א\\\"א נראה מדבריו שהוא עיכוב לנר מערבי שלא להדליקו וכו'. מה שהביא מדתנן מצאן שכבו מדשנן ומדליקן מן הדולקין צריך לדחוק לדעת רבינו דאע\\\"ג דקתני שכבו לשון רבים לאו דוקא דלא קאי אלא אחד מינייהו דהיינו נר מזרחי שכל נר מערבי לעולם אינו מדליקו אלא ממזבח העולה ומפרש לה רבינו כפשטה ולא כדפירש הראב\\\"ד דלא אתא אלא למעוטי מזבח הפנימי ובית הכירים בלבד ולא למעט הדלקתו משאר נרות אלא אף למעט הדלקתו משאר נרות אתא:\",3,0],[8,364,3,14,\"ומ\\\"ש וכיצד מדליקו מושך הפתילה עד שמדליקה ומחזירה לפי שהנרות קבועים במנורה. פרק שני דשבת (דף כ\\\"ב:).\",1,0],[8,364,3,14,\"ומ\\\"ש ואינו יכול להדליק בנר אחר משום בזיון. שם וכשמואל וכמו שכתב המגיד משנה בהלכות חנוכה:\",2,0],[8,364,3,15,\"כל הפתילות שאסור להדליק בהם בשבת וכו'. ברפ\\\"ב דשבת (דף כ\\\"א) ודקדק רבינו לכתוב במנורה משום דהתם מותיב מדתנן מבלאי מכנסי הכהנים ומהמיניהם היו מפקעים ומהם היו מדליק כלומר ובגדי כהונה הוה בהו תכלת והוא צמר שהוא מהדברים שאסור להדליק בשבת בפתילתו ומשני שמחת ביה השואבה שאני:\",1,0],[8,364,3,16,\"לא היה מטיב כל הנרות בפעם אחת וכו'. פרק ג' דיומא (דף ל\\\"ג).\",1,0],[8,364,3,16,\"ומה שכתב כדי להרגיש כל העזרה. שם כריש לקיש ואף על גב דרבי יוחנן פליג ואמר דטעמא משום דכתיב בבקר בבקר בהטיבו את הנרות חלקהו לשני בקרים כיון דלא נפיק לן מינה מידי לענין דינא לא חש מלמינקט כריש לקיש. כך היה נראה לי אלא שאמרו שם בגמרא דלר\\\"י צריך להפסיק בין הטבת חמש נרות להטבת שתי נרות בעבודה אחרת ולריש לקיש א\\\"צ להפסיק בעבודה אחרת והשתא יקשה על רבינו שכתב שצריך לעשות ביניהם עבודה אחרת והיינו כר' יוחנן וכתב שטעם חילוק הטבת הנרות לשתים הוא כדי להרגיש כל העזרה והיינו כר\\\"ל והוה כמזכה שטרא לבי תרי. ונראה לי שטעם רבינו דלר\\\"ל נמי לא אמר אלא שאין צריך להפסיק ביניהם בעבודה אחרת אבל אם רצה להפסיק ביניהם בעבודה אחרת לית לן בה הילכך כי מפסיק ביניהם בעבודה אחרת שפיר דמי לכולי עלמא ונקט טעמו של ר\\\"ל מפני שאינו צריך דרשא ואריכות כמו בטעמו של ר' יוחנן:\",2,0],[8,364,3,17,\"זה שזכה בדישון המנורה וכו'. בפ' ג' דתמיד.\",1,0],[8,364,3,17,\"ומ\\\"ש ואח\\\"כ נכנס ומטיב שני הנרות וכו'. בפרק ששי דתמיד (דף ל\\\"ג):\",2,0],[8,364,3,18,\"חביתי כהן גדול מצות עשה להקריבם בכל יום מחצה בבקר וכו'. משנה בס״פ התכלת (מנחות דף נ':).\",1,0],[8,364,3,18,\"ומ\\\"ש ולישתן ואפייתן דוחין את השבת ואת הטומאה וכו'. שם (דף נ').\",2,0],[8,364,3,18,\"ומ\\\"ש כמו שבארנו בפי\\\"א ממעשה הקרבנות:\",3,0],[8,364,3,19,\"ומה שכתב טחינת סולתן והרקדתן בחוץ ואינם דוחים את השבת. משנה בפ' שתי הלחם (מנחות דף צ״ו):\",1,0],[8,364,3,20,\"כהן שהקריב מחצה בשחרית ומת כו' ומינו כהן אחר תחתיו לא יביא חצי עשרון מביתו וכו' עד ושני חצאין אובדין. משנה בס״פ התכלת (מנחות דף נ':).\",1,0],[8,364,3,20,\"ומ\\\"ש דה\\\"ה לנטמא או נולד לו מום:\",2,0],[8,364,3,21,\"ומה שכתב ואלו השני חצאין האובדים וכו'. ברייתא בס״פ התכלת (מנחות דף מ״ח:).\",1,0],[8,364,3,21,\"ומ\\\"ש וכן אם אבד או נטמא החצי של בין הערבים. ברייתא פרק התכלת ואיתיה בתוספתא דמנחות פר\\\"ז.\",2,0],[8,364,3,21,\"ומ\\\"ש והיכן שורפין אותן בעזרה:\",3,0],[8,364,3,22,\"מת כ״ג בשחרית וכו' שלימה היתה קריבה. בפ״ז דשקלים ובס״פ התכלת (מנחות דף נ״א:) במשנה פלוגתא דר״ש ור' יהודה ופסק כר״י:\",1,0],[8,364,3,22,\"מת כ\\\"ג קודם שיקריבו בבקר ולא מינו כהן אחר וכו' עד סוף הפרק. בס\\\"פ התכלת שם:\",2,0],[8,364,3,22,\"ומ\\\"ש אין כופלין שמנה ולבונתה. שם (דף נ\\\"ב) וכרבנן דפליגי אאבא יוסי בן דוסתאי:\",3,0],[8,364,4,1,\"כל העבודות האלו שעושים בכל יום בפייס היו עושים אותם וכיצד היו עושין אותם וכו'. בפרק ב' דיומא (דף כ\\\"ד:).\",1,0],[8,364,4,1,\"ומה שכתב ומלובשים הם בבגדי כהונה. שם פלוגתא דר\\\"נ ורב ששת ופסק כרב ששת:\",2,0],[8,364,4,2,\"ומ\\\"ש ושאר הכהנים מוסרים אותה לחזנים וכו'. שם (דף ס\\\"ו:) ובפרק ה' דתמיד:\",1,0],[8,364,4,3,\"כיצד מפיסין וכו' עד ויפקדם בטלאים. בפ\\\"ב דיומא (דף כ\\\"ב:) וכתב הריטב\\\"א בשם התוספות שזה שנוטל המצנפת לא היה יודע סך המנין והאומר המנין לא היה יודע ממי נטל המצנפת:\",1,0],[8,364,4,5,\"ארבעה פייסות היו מפיסין בכל יום בשחרית וכו' עד למזבח. ברפ\\\"ב דיומא (דף כ\\\"ב) וענין שני גזרי עצים פירש\\\"י רפ\\\"ב דיומא שני בקעיות עצים ארוכים כמדת רוחב המערכה ונותן אותו ממעל לעצי המערכה ומקרא יליף לה לקמן עכ\\\"ל. וז\\\"ל הריטב\\\"א פירש\\\"י בריש יומא אחר שסידר המערכה והדלקה נותן לרוחב המערכה שני עצים ארוכים ארכן לרוחב המערכה.\",1,0],[8,364,4,5,\"ומה שכתב והוא מכניס מחתה וכו':\",2,0],[8,364,4,6,\"הפייס השני זוכים בו י\\\"ג על סדר עמידתן וכו' עד היין של נסכין. משנה וגמרא בפ\\\"ב דיומא (דף כ\\\"ה):\",1,0],[8,364,4,6,\"כתב הריטב\\\"א פ\\\"ב דיומא הזורק הוא מקטיר האיברים כדי שתעשה עבודת הדם והבשר בכהן אחד וכתב עוד משום דשחיטה וזריקה היא עיקר עבודת התמיד היו מקדימין אותה אף על גב דדישון מזבח הפנימי היו עושים תחלה:\",2,0],[8,364,4,7,\"הפייס השלישי אומר להם הממונה וכו' עד הפיסו וזכה מי שזכה. שם במשנה (דף כ\\\"ו) ודלא כראב\\\"י דאמר בפ\\\"ה דתמיד (דף ל\\\"ב:) המעלה איברים לכבש הוא מעלה אותם ע\\\"ג המזבח:\",1,0],[8,364,4,8,\"תמיד של בין הערבים אין מפיסין לו פייס אחר וכו'. בפ\\\"ב דיומא (דף כ\\\"ו) מימרא דר\\\"י ואע\\\"ג דשני גזרים של שחר היו בכהן אחד ושל בין הערבים היו בשני כהנים כדתנן בפרק הנזכר כבר כתב הריטב\\\"א שמי שזכה בהם בבקר אומר בערב לחבירו זכה עמי בעץ שני.\",1,0],[8,364,4,8,\"ומ\\\"ש חוץ מן הקטרת וכו'. שם.\",2,0],[8,364,4,8,\"ומה שכתב ואם כבר הקטירו כולם מימיהם וכו':\",3,0],[8,364,4,9,\"בשבת שיש שם תמידין ומוספין ושני בזיכי לבונה וכו'. בסוף סוכה (דף נ\\\"ו:) משמרה היוצאה עושה תמיד של שחר ומוספין וכתב הריטב\\\"א פ\\\"ב דיומא העומד אחר י\\\"ג כהנים הי\\\"ד זוכה בבזך אחר והט\\\"ו זוכה בבזך שני.\",1,0],[8,364,4,9,\"ומה שכתב והמשמר האחר שיכנס בשבת מפיסין פייסות אחרות לתמיד של בין הערבים שם ובפרק ב' דיומא אהא דאמר ר\\\"י אין מפיסין על תמיד של בין הערבים אלא כהן שזכה בו בשחרית יזכה בו בין הערבים מתיב והתניא כשם שמפיסין שחרית כך מפיסין בין הערבים וכו' אמר רב שמואל בר יצחק הכא בשבת עסקינן הואיל ומשמרות מתחדשות:\",2,0],[8,364,4,9,\"ואלו ואלו חולקין בלחם הפנים. משנה בסוף סוכה (דף נ\\\"ו):\",3,0],[8,364,4,10,\"ומ״ש ואין אוכלים את הלחם עד שיקטירו שני בזיכי לבונה על האש. בפרק שתי הלחם (מנחות דף צ״ט:) תנן הקטירו הבזיכים והחלות מתחלקות לכהנים.\",1,0],[8,364,4,10,\"ומה שכתב והלבונה טעונה מלח וכו'. בסיפרא פי\\\"ד:\",2,0],[8,364,4,11,\"ומה שכתב ואחר קרבן המוספין מקטירים שני הבזיכין. בפ\\\"ג דיומא (דף ל\\\"ג) אביי (הוה) מסדר סדר מערכה משמא דגמרא ואליבא דאבא שאול וכו' ומוספין קודמין לבזיכין.\",1,0],[8,364,4,11,\"ומ\\\"ש ושני כהנים מקטירים שני הבזיכין. משנה פרק שני דיומא (דף כ\\\"ו:):\",2,0],[8,364,4,12,\"כיצד חולקין לחם הפנים וכו' והנכנסין חולקין ביניהם בצפון כו'. משנה בסוף סוכה (דף נ\\\"ו).\",1,0],[8,364,4,12,\"ומ\\\"ש ובזמן שיהיה יו\\\"ט של אחד משלשה רגלים בשבת וכו' עד ימצא אחר. משנה וגמרא בסוף סוכה:\",2,0],[8,364,4,12,\"כתב הראב\\\"ד וכן אם חל יו\\\"ט האחרון להיות בערב שבת וכו' עד ודבר זה תקנה א\\\"א איני יודע מה שאמר כדי שיתאחרו וכו'. וי\\\"ל לדעת רבינו דמאי כדי שיתאחרו דקאמר שיתאחרו במקדש ולא ימנעו מלבא למקדש וכ\\\"ת מה תועלת יש לנו כשיבאו למקדש שאם יתאחר אחד מבעלי משמר מלבא למקדש ימצא אחר שיבא במקומו וטעם מתיישב הוא:\",3,0],[8,364,4,13,\"חל יום אחד להפסיק בין השבת ובין יום טוב וכו'. משנה שם חל יום אחד להפסיק בינתים משמר שזמנו קבוע היה נוטל י' חלות והמתעכב נוטל שתים. ופירש\\\"י חל יום אחד להפסיק בינתים כגון שחל יו\\\"ט ראשון בשני בשבת שהיו יכולים לבא באחד בשבת והם קדמו ובאו מע\\\"ש או שחל יום טוב אחרון להיות בחמישי שהיו יכולים לילך מע\\\"ש ונתעכבו שם בשבת כל המשמרות שנתעכבו אין נוטלין אלא שתי חלות ומשמר שזמנו קבוע נוטל עשר וחולקין אותם בין משמר הנכנס למשמר היוצא כדרך כל שבתות השנה עכ\\\"ל. וכך הם דברי הראב\\\"ד שכתב חל יום א' וכו' עד וזה הנכנס נוטל שתים א\\\"א כל מ\\\"ש כאן הבל ורעיון רוח שהמשמר שזמנו קבוע הם שתי משמרות של אותה שבת והם נוטלין עשר חלות והמשמר שהוא רחוק מביתו ולא יגיע לביתו ביום א' מתעכב שם ונוטל שתי חלות עכ\\\"ל. אבל רבינו מפרש חל יום א' להפסיק בינתים הוא שיהיה יום טוב ראשון של חג בשני (בשבת) או יום טוב אחרון יום ה' וכשאירע כן לא ישאר למשמר השני הנכנס אלא עבודת יום ראשון בלבד ויבוא החג וישתתפו כלם בעבודה אם יחול יום טוב הראשון יום שני או יכנס המשמר שני יום שבת אם יחול יו\\\"ט האחרון יום חמישי לפי שכל יום שבת הוא יום שמתחלפין תצא אחת ותכנס השניה ומחלקים לחם הפנים וכשיזדמן לאחת מהמשמרות זה המשמר שלא ישאר לו לעבוד אלא יום אחד יתעצל בדבר ויתעכב מלבא ותרגום ויתמהמה ואיתעכב ולפיכך תקנו לו שיקח מלחם הפנים שתי ככרות בלבד עכ\\\"ל בפירוש המשנה. נמצא לפירוש זה כשחל יום טוב ביום שני בשבת שקודם יו\\\"ט משמר היוצא נוטל עשר והנכנס נוטל שתים וכשחל יום טוב האחרון להיות בחמישי בשבת שאחר המועד משמר הנכנס נוטל עשר והיוצא נוטל שתים. ופירוש מתיישב הוא ואיני יודע למה ההביל אותו הראב\\\"ד ואדרבא לישנא דהמתעכב דנקט מתניתין אתי שפיר טפי לפירוש רבינו דהיינו המתאחר מלבא לעבודה ואילו לפירוש רש\\\"י והראב\\\"ד נהי דכשחל יו\\\"ט האחרון בחמישי שייך לומר המתעכב כשחל יו\\\"ט הראשון בשני לא שייך לומר אלא המקדים:\",1,0],[8,364,4,14,\"כהן גדול נוטל לעולם מכל משמר חצי החלות וכו' עד סוף הפרק. בפרק קמא דיומא (דף י\\\"ז:):\",1,0],[8,364,5,1,\"מצות עשה לסדר לחם הפנים וכו'. ועורכים אותו שני סדרים וכו'. מבואר בתורה:\",1,0],[8,364,5,2,\"ומ״ש ובין כל שתי חלות שלשה קנים של זהב וכו' וסומך כל מערכה בשתי קשוות. פרק שתי הלחם (מנחות דף צ״ו) במשנה.\",1,0],[8,364,5,2,\"ומ\\\"ש ונותנין בצד כל מערכה כלי שיש בו קומץ לבונה וכו' כתוב בתורה ונתת על המערכת לבונה זכה ובמשנה פרק שתי הלחם אמרינן שהיה בשני בזיכין.\",2,0],[8,364,5,2,\"ומ״ש ושולים היו לבזיכים וכו'. בברייתא פרק תמיד נשחט (פסחים דף ס״ד:) ובתוספתא דמנחות פי״א.\",3,0],[8,364,5,2,\"ומה שכתב בצד כל מערכה. הוא כאבא שאול דאמר [מנחות צ״ו.] ונתת על המערכת לבונה זכה הוא כמו ועליו מטה מנשה שפירושו אצלו ופסק כמותו מפני שדעת רבי שם [דף ס״ב.] גבי הנפת לחם וכבשים כמותו והלכה כרבי משום דמפרשי אמוראי טעמו ועוד דבפ' הקומץ [מנחות דף כ״ו: כ״ז] בעו ר' יצחק אליביה כן כתב הר״י קורקוס ז״ל:\",4,0],[8,364,5,3,\"שני הסדרים מעכבים זה את זה וכו'. משנה בפ' הקומץ רבה (מנחות דף כ״ז:):\",1,0],[8,364,5,3,\"ואין מחנכין את השולחן אלא בלחם הפנים בשבת. משנה בפרק התכלת (מנחות דף מ״ט):\",2,0],[8,364,5,3,\"מיום השבת ליום השבת מוציאין את הלחם וכו'. משנה בפרק שתי הלחם (מנחות דף ק':):\",3,0],[8,364,5,4,\"ומ\\\"ש וכיצד מסדרים את הלחם וכו' עד החלות מתחלקות לערב. משנה שם (דף צ\\\"ט:):\",1,0],[8,364,5,6,\"כיצד מעשה לחם הפנים וכו'. משנה בפ' אלו מנחות (מנחות דף ע״ו:).\",1,0],[8,364,5,6,\"ומ\\\"ש ומנפין מהם בי\\\"א נפה. שם במשנה.\",2,0],[8,364,5,6,\"ומ\\\"ש לא נפה אותה באחד עשר נפה או שלא הוציאן מכ\\\"ד סאין וכו'. שם בברייתא כל המנחות שריבה במדת סאין שלהם או שמיעט במדת סאין שלהם כשירות:\",3,0],[8,364,5,7,\"לישתן ועריכתן בחוץ ואפייתן בפנים וכו'. משנה פרק שתי הלחם (מנחות דף צ״ה:) אחד שתי הלחם ואחד לחם הפנים לישתן ועריכתן בחוץ ואפייתן בפנים וכו' רבי יהודה אומר כל מעשיהם בפנים ופסק כת״ק.\",1,0],[8,364,5,7,\"ומ\\\"ש כשאר כל המנחות, הוא תימה שהרי כתב בספי\\\"ב ממעשה הקרבנות המנחות לישתן ועריכתן ואפייתן בפנים. ודוחק לומר שמ\\\"ש כשאר כל המנחות לא קאי אלא אאפייתן.\",2,0],[8,364,5,7,\"ומ״ש ולשין אותן אחת אחת וכו'. משנה פרק שתי הלחם (מנחות דף צ״ד):\",3,0],[8,364,5,9,\"כל חלה מהן מרובעת וכו'. בפרק שתי הלחם (מנחות דף צ״ה) תניא על אפיית לחם הפנים כמין כוורת היה לה בתנור ודומה כמין טבלא מרובעת ובגמ' (דף צ״ד) אתמר לחם הפנים כיצד עושים אותו ר' חנינא אמר כמין תיבה פרוצה ר' יוחנן אמר כמין ספינה רוקדת ומתיב בגמרא לר״י מהאי ברייתא דדומה כמין טבלא מרובעת ושני ופיה דומה כמין טבלא מרובעת ומדסתם רבינו וכתב שהיתה מרובעת משמע שפסק כר' חנינא וצריך טעם למה דהא בגמרא [שם צ״ה.] קאמר דתניא כוותיה דר״י. ואפשר שטעמו משום דר' חנינא עדיף מר״י וקשיש מיניה דהא פקיד [כתובות ק״ג:] ר' חנינא בר חמא ישב בראש והוי כמו תנא:\",1,0],[8,364,5,9,\"אורך כל חלה מהם עשרה טפחים וכו'. משנה פרק שתי הלחם (דף נ\\\"ו) פלוגתא דר\\\"י ור\\\"מ ופסק כר\\\"מ ונראה שהטעם משום דאבא שאול סבר כוותיה.\",2,0],[8,364,5,9,\"ומ\\\"ש ורומה ז' אצבעות. הוא פי' מה ששנינו וקרנותיו ז' אצבעות. והרלב\\\"ג כתב בפירוש התורה פרשת תרומה וז\\\"ל כופל מן האורך טפחיים מכאן וטפחיים מכאן ואותם הטפחיים עומדים בגובה כמו דפנות. וענין קרנותיה לפי הנראה לא היתה החלה בעלת ארבע צלעות בשלימות אבל היתה בעלת ח' צלעות ארבע צלעות לצד הזויות באלכסון והם אשר קראום קרנות ואורך כל קרן מהם היה ז' אצבעות ובזה האופן ישלם לזה הלחם שיהיו לו פנים רבים בכל אחד משטחיו המקיפים בו כי כל אחד מששת השטחים המקיפים בכל גוף שיהיה בזה התואר נחלק לג' שטחים עד שכבר יקיפו בו י\\\"ח שטחים ששה שטחים בכל א' מדפניו וארבע בתושבת החלה. ואולם עובי אלו החלות לא הוגבל כי כבר יתחלף לפי קושי הבצק ורכותו, ולפי דעתי היה עביו פחות מאצבע וזה יתבאר משיעור העשרון שהיה עשירית ג' סאין ואמה על אמה ברום שלש אמות היה מחזיק מ' סאה ולזה יהיה שיעור העשרון אמה על אמה ברום חצי אצבע וחמישית חומש אצבע שהם כמו ש' אצבעות ורביע אצבע בקירוב. ובהיות הענין כן הנה החלה הנעשית משני עשרונים מעשרה טפחים אורך וחמשה טפחים רוחב לא יהיה כי אם שש שמיניות אצבע בקירוב כשהונח שיעור הבצק כשיעור הסלת אשר ממנו נעשה והוא מבואר שהבצק כשיהיה מצה לא יהיה נוסף כמותו על כמות הקמח ואם היה שיהיה נוסף הנה הוא מעט אבל יראה בחוש שכמות הבצק הזה הוא פחות מכמות הקמח ולזה לא יתכן שיהיה עובי אלו החלות כי אם פחות מאצבע ולזאת הסבה תמהנו על הרמב\\\"ם במה שפירש וקרנותיו ז' שעובי החלה היה ז' אצבעות ועוד שכבר התבאר שם שיעור שתי הלחם שהיו באים בעצרת שהם באים חמץ שהיה כל אחד מהם עשרון והנה היה ארכו שבעה טפחים ורחבו ארבעה וקרנותיו ארבע אצבעות והוא מבואר שהבצק שיהיה חמץ הוא רב הכמות ממה שהיה בהיותו מצה ואם היה הרצון בקרנותיו עביו הנה יהיה שיעור החלה שהיא מצה הבאה משני עשרונים יותר מג' שיעורים מהחלה שהיא חמץ הבאה מעשרון אחד וזה בלתי אפשר בשום פנים עם שהוא רחוק שיהיה מוגבל האורך והרוחב והעובי כי הכמות יתחלק לפי קושי הבצק ורכותו וכו' ולזה הוא מבואר כי הרצון בקרנותיו כמו שפירשנו אנחנו עכ\\\"ל:\",3,0],[8,364,5,10,\"אין אפיית לחם הפנים דוחה את השבת ולא את יום טוב וכו' עד ונותנן לארך השלחן. משנה שם:\",1,0],[8,364,5,12,\"סידר הלחם בשבת כמצותו וכו' אבל אם הקטיר הבזיכים בשבת נפסל הלחם. כך היא הגירסא בספרים שבידינו ואיני יכול להלום לשון אבל. ומצאתי בספר ישן אבל אם הקטיר הבזיכים בשבת לא נפסל הלחם. ודינים אלו משנה בפרק שתי הלחם (מנחות דף ק') סידר את הלחם בשבת ואת הבזיכים לאחר השבת והקטיר את הבזיכים בשבת פסול ואין חייבין עליו משום פגול נותר וטמא. סידר את הלחם ואת הבזיכים בשבת והקטיר הבזיכים לאחר השבת פסול ואין חייבין עליהן משום פגול נותר וטמא סידר את הלחם ואת הבזיכים לאחר השבת והקטיר הבזיכים בשבת כיצד יעשה יניחנה לשבת הבאה שאפילו היא על השלחן ימים רבים אין בכך כלום. ופירש״י פסול דמחוסר זמן הוא שלא היה על השלחן אלא ששה ימים והכא א״א לתקן ולומר יניחנו עד שבת הבאה דכיון דלחם נסדר כדינו בשבת קידשו שלחן ושוב אינו יכול להשהותו אלא עד שבת ראשונה דמפסיל בלינה הואיל ולן הלחם בלא בזיכין, משום פגול אם הקטירו על מנת לאכול מן הלחם למחר אינו פגול שלא קרב המתיר כמצותו, ולא משום נותר שאין נותר חל על הלחם שהרי אין ראוי לאכילה, וטמא האוכלו בטומאת הגוף אינו בכרת כדאמרינן בהקומץ הניתר לטהורים חייבים עליו משום טומאה וזה לא ניתר לטהורים מעולם דבזיכין הוו מתירים דידיה ולא קרבו כהלכתן לאחר השבת למחר. יניחנה לשבת הבאה ויעמוד שבועים על השלחן דכיון דלא נסדר בשבת אין שלחן מקדשו עד השבת הילכך לא מפסיל בלינה למוצאי שבת עכ״ל. ובבא בתרייתא מייתי לה בפרק שתי מדות (מנחות דף צ') ופירש״י סידר את הלחם ואת הבזיכין לאחר השבת שלא כמצותו דמצותו היה לסדרו בשבת פסולה לפי שצריך שיהא הלחם על השלחן שתי שבתות. כיצד יעשה שיהיו כשרים הלחם והבזיכים יניחנו שלא יקטיר הבזיכין ולא יסלק הלחם עד לשבת שניה הבאה ונמצא הלחם והבזיכין על השלחן ט״ו ימים ושני ימי שבת שאפי' הוא על השולחן אותם ז' ימים שעד לשבת יותר מדינו אין בכך כלום עכ״ל. נראה שהוא גורס בהאי בבא נמי פסולה ובפ״ג דיומא (דף כ״ט) נמי מייתי בגמרא האי בבא וגריס בה פסולה. ורבינו נראה שגורס בבבא שניה סידר את הלחם ואת הבזיכין בשבת והקטיר הבזיכים לאחר השבת פסול וחייבין עליו משום פגול נותר וטמא. ואין לומר שטעמו משום דכיון שסידר הלחם והבזיכים כמשפטם חל עליו שם קדושה ליפסל משום פגול נותר וטמא ומכל מקום כיון שלא הקטיר הבזיכים בשבת כדינם אלא לאחר השבת פסול דהא תנן בפ״ב דמעילה (דף ט') דאין חייבין על הלחם משום פגול נותר וטמא עד שיקרבו הבזיכין ומאחר שלא קרבו הבזיכין כמצותן לא ה״ל להתחייב משום פגול נותר וטמא כדאשכחן ברישא שמפני שלא הוקטרו הבזיכין כמצותן אין חייבין עליו משום פגול נותר וטמא. ואפשר שטעם רבינו דשאני התם דכיון שלא סידר הבזיכין בשבת לא היה כח ליחייב בהקטרתם משום פגול נותר וטמא אע״פ שהוקטרו בשבת אבל כשסידר הבזיכין עם הלחם בשבת חל על הבזיכין כח לחייב בהקטרתן משום פגול נותר וטמא כשיוקטרו אע״פ שלא יוקטרו כמצותן ואע״ג דתנן בפ״ק דמנחות (דף י״ב) ובפ״ב דזבחים (דף כ״ט) שאין חייבין עליו משום פגול עד שיקרב המתיר כמצותו י״ל דלא אתא לאפוקי אלא שלא יהא עירוב מחשבת פסול אחר עם מחשבת הפגול אבל בגוונא דנ״ד לא. ובבבא שלישית גורס סידר הלחם והבזיכים לאחר השבת נפסל הלחם הקטיר הבזיכין בשבת לא נפסל הלחם כיצד יעשה יניחנה לשבת הבאה וכו' והטעם דכיון שסידר הלחם והבזיכין לאחר השבת לא נתקדשו ואע״פ שיבא יום שבת והם על השלחן הילכך אם הקטיר הבזיכין לאחר השבת כלומר קודם שיגיע שבת הלחם אינו קדוש מאחר שלא הונחו שם בשבת וגם לא הוקטרו בשבת שהרי אין שם בזיכין ונפסל שאין לו תקנה עוד ואינו קדוש כלומר שאין חייבין עליו משום פגול נותר וטמא אבל אם הקטיר הבזיכים בשבת לא נפסל הלחם דכיון דביום השבת היו הבזיכים עם הלחם על השלחן נתקדש הלחם וזהו שכתב רבינו לא נפסל הלחם שזו היא הנוסחא הנכונה בדברי רבינו לא נפסל ולא כספרים דגרסי נפסל. ומ״מ יש לדקדק מאי נ״מ בשלא נפסל הלחם דכיון דאין לו בזיכים שיוקטרו בשבת הבא להתיר הלחם אינו ניתר ואין לומר שיש לו תיקון ע״י שיסדר עמו בזיכים אחרים בשבת זו ויקטירם בשבת הבאה וע״י כך יותר הלחם דאם כן לא ה״ל למשנה ולרבינו להשמיט תיקון זה. ואפשר לומר דכי אמרינן נפסל הלחם ישרף וכי אמרי' לא נפסל היינו שלא ישרף. ואין לתמוה על רבינו שהיפך סדר המשנה וכתב בבא שלישית בשניה שעשה כן מפני שבבא שלישית כשהקטיר הבזיכים לאחר שבת הבאה אינו קדוש הלחם ונפסל כמו בבבא ראשונה לפיכך סמכה לה:\",1,0],[8,364,5,15,\"נפרסה חלה אחת מן הלחם וכו' עד ואף על פי שלא פירק המערכה. ברייתא ומימרא בפירקא קמא דמנחות (דף ט':):\",1,0],[8,364,5,16,\"נטמא אחד מן הסדרין בין לפני הקטרה וכו' עד סוף הפרק. משנה פרק הקומץ זוטא (דף י\\\"ד:) ופסק כחכמים:\",1,0],[8,364,6,1,\"סדר עבודות התמידות בכל יום כך הוא וכו'. בפ\\\"ק דתמיד (דף כ\\\"ו).\",1,0],[8,364,6,1,\"ומה שכתב ואחר כך מסדר מערכה גדולה וכו'. שם בפרק ב' (דף כ\\\"ט):\",2,0],[8,364,6,1,\"ומ\\\"ש ואח\\\"כ נכנסין ללשכת הכלים כו' עד השני שזכה בדישון המנורה. שם בפ\\\"ג (דף ל'):\",3,0],[8,364,6,2,\"ומה שכתב והמדשן את המזבח מדשנו בשעה שהשוחט שוחט את התמיד:\",1,0],[8,364,6,3,\"ומה שכתב ואחר שזורקין הדם מטיב זה בהיכל חמש נרות. בפ\\\"ג דיומא (דף ל\\\"ג) גבי אביי הוה מסדר מערכה אליבא דאבא שאול אמרינן דישון מזבח הפנימי קודם להטבת חמש נרות והטבת חמש נרות קודם לדם התמיד ודם התמיד קודם להטבת שתי נרות והטבת שתי נרות קודם לקטורת. ובפ\\\"ק (דף י\\\"ד:) אמרינן דהא דמפסיק בין הטבת חמש נרות להטבת שתי נרות בדם התמיד פליגי רבנן עליה ואמרי דלא הוה מפסיק בינייהו אלא בקטרת ופסק רבינו כרבנן ולפי זה כך הוא הסדר דישון מזבח הפנימי קודם לדם התמיד ודם התמיד קודם להטבת חמש נרות והטבת חמש נרות קודמת לקטרת וקטורת קודמת להטבת שתי נרות.\",1,0],[8,364,6,3,\"ומה שכתב וכל אחד ואחד מעלה אבר שזכה בו לכבש הוא על פי מה שנתבאר בפרק ד'.\",2,0],[8,364,6,3,\"ומה שכתב ונותנים האיברים מחצי כבש ולמטה במערבו ושל מוספין היו נותנין אותו מחצי הכבש ולמטה במזרחו. בסוף שקלים ובפרק ד' דתמיד (דף ל״א:) ושם כתב המפרש הטעם ורש״י בפרק החליל (סוכה דף נ״ד:):\",3,0],[8,364,6,3,\"ומה שכתב ושל ראשי חדשים נותנים על המזבח מלמעלה. בסוף שקלים משנה ושל ראשי חדשים ניתנים על כרכוב המזבח מלמעלה ובירושלמי איזהו כרכוב המזבח אמה בין קרן לקרן מקום הילוך רגלי כהנים.\",4,0],[8,364,6,3,\"ומ\\\"ש ומולחים שם האיברים. גם זה במשנה שם.\",5,0],[8,364,6,3,\"ומ״ש כדי לפרסמו שהוא ר״ח. בפרק החליל (סוכה דף נ״ה) ופירש״י לכך סודרים אותו למעלה משאר איברים להראות שהם חשובים ולהודיע שהוקבע החדש בזמנו.\",6,0],[8,364,6,3,\"ומ\\\"ש וזורקין מלח ע\\\"ג הכבש אפילו בשבת כדי שלא יחליק וכו'. משנה בסוף עירובין (דף ק\\\"ד) בוזקין מלח על גבי הכבש בשביל שלא יחליקו. ופירש\\\"י בוזקין מלח מפזרין ומכתתין ובגמרא א\\\"ל רב אחא בריה דרבא לרב אשי האי מלח ה\\\"ד אי דמבטלה קא מוסיף אבנין וכתיב הכל בכתב מיד ה' עלי השכיל ואי דלא קא מבטלה הא הויא חציצה וכו' בהולכת עצים למערכה דלאו עבודה היא:\",7,0],[8,364,6,4,\"ואחר שמעלים האיברים לכבש מתכנסין כולם ללשכת הגזית. בפרק ד' דתמיד (דף ל\\\"א:).\",1,0],[8,364,6,4,\"ומ\\\"ש והממונה אומר להם ברכו ברכה אחת וכו' עד מוסיפין ברכה אחת בפ\\\"ה דתמיד (דף ל\\\"ב:).\",2,0],[8,364,6,4,\"ומה שכתב והיא שיאמרו אנשי משמר היוצא לאנשי משמר הנכנס מי ששיכן את שמו בבית הזה וכו'. בסוף פרק קמא דברכות (דף י\\\"ב).\",3,0],[8,364,6,4,\"ומ\\\"ש ואח\\\"כ מפיסין פייס שלישי ורביעי וכו'. בפ\\\"ה דתמיד.\",4,0],[8,364,6,4,\"וכתב רבינו שים שלום במקום ברכת כהנים האמור במשנה שם משום שלא היה שם ברכת כהנים עד לאחר הקטרה כדאיתא שם במשנה וכתבו רבינו בסמוך. וקרי לשים שלום ברכת כהנים מפני שסמוך לה מברכים ברכת כהנים והתוס' כתבו דברכת כהנים ממש קאמר שקורין אותה עכשיו בלא נשיאות כפים.\",5,0],[8,364,6,4,\"ומ\\\"ש ונכנס ומקטיר ואח\\\"כ נכנס זה שזכה בדישון ומטיב שתי הנרות. אע\\\"ג דבפ\\\"ו דתמיד שנוי הטבת שתי נרות קודם לקטרת כבר נתבאר בפרק זה דלא קי\\\"ל הכי אלא כרבנן דאמרי בקטרת היה מפסיק בין הטבת חמש נרות להטבת שתי נרות.\",6,0],[8,364,6,4,\"ומ\\\"ש ויוצא זה שהקטיר עם מדשן המנורה ועומד על מעלות האולם הוא ואחיו הכהנים. בפ\\\"ז דתמיד שנינו באו ועמדו על מעלות האולם:\",7,0],[8,364,6,5,\"כשיגיעו בין האולם ולמזבח וכו' עד היה מעמיד את הטמאים על שער המזרח. בפ\\\"ו דתמיד.\",1,0],[8,364,6,5,\"ומ״ש מפני החשד. בפרק כיצד צולין (פסחים דף פ״ב) וכרבא דאמר הכי ופירש״י מפני החשד שלא יחשדום שמפני מלאכתן הם נחדלים מלעבוד עבודה:\",2,0],[8,364,6,5,\"ודע שזה שכתב כשיגיעו בין האולם ולמזבח הוא מוקדם למה שכתב קודם לכן ועומד על מעלות האולם הוא ואחיו הכהנים וכך הוא במשנה דמסכת תמיד. וכך היה הסדר שאחר שהפיסו פייס שלישי ורביעי בעזרה היו הולכין בעזרה מצד המזרח לצד המערב וכשהגיעו בין המזבח והאולם נטל אחד מהם את המגריפה וזרקה בין האולם ולמזבח והיו הולכים לאולם וכשהחלו עולים במעלות האולם מי שזכה בקטרת מי שזכה בדישון המנורה היו מקדימין לפניהם ועובדים עבודתם ובאו גם הם ועמדו על מעלות האולם ומברכים ברכת כהנים.\",3,0],[8,364,6,5,\"ומ\\\"ש ואח\\\"כ מעלה זה שזכה באיברים את האיברים מן הכבש ולמזבח. בפ\\\"ג דיומא (דף ל\\\"ג) אהא דמסדר אביי סדר מערכה אליבא דאבא שאול הטבת שתי נרות קודם לקטרת וקטורת קודם לאיברים וכבר נתבאר בפרק זה דרבנן פליגי עליה ואמרו קטרת קודם להטבת שתי נרות והטבת שתי נרות קודם לאיברים.\",4,0],[8,364,6,5,\"ומ\\\"ש ומברכין ברכת כהנים ברכה אחת בשם המפורש כמו שביארנו במקומה. בפי\\\"ד מהל' תפלה:\",5,0],[8,364,6,5,\"ואח\\\"כ מעלים סלת הנסכים וכו'. בפ\\\"ג דיומא אהא דמסדר אביי סדר מערכה אמרינן איברים קודמין למנחה ומנחה לחביתין וחביתין לנסכים. ופירש רש\\\"י איברים להקטיר איברי התמיד על מזבח החיצון. למנחה מנחת נסכו של תמיד דכתיב ועשירית האיפה סלת למנחה לנסכים לנסך יינו של תמיד:\",6,0],[8,364,6,5,\"ובשעת הניסוך אומרים הלוים השיר וכו':\",7,0],[8,364,6,6,\"כשהיו נותנים היין למנסך וכו' עד ועל כל תקיעה השתחויה. בסוף תמיד:\",1,0],[8,364,6,8,\"ואין אומרים שירה אלא על עולות הצבור וכו'. בפ\\\"ב דערכין (דף י\\\"א:) איבעיא אם עולת נדבת צבור טעון שירה ואסיקנא על עולותיכם ועל זבחי שלמיכם מה עולה קדש קדשים אף שלמים קדש קדשים פירוש ואין לך שלמים קדשי קדשים אלא כבשי עצרת דכתיב בהו קדש יהיו ומעתה מה שלמים דמיירי קבוע להם זמן אף עולה שקבוע לה זמן לאפוקי נדבת ציבור.\",1,0],[8,364,6,8,\"ומ\\\"ש וכן נסכין הבאים בפני עצמם וכו'. גם זה שם:\",2,0],[8,364,6,9,\"השיר שהיו הלוים אומרים וכו'. בסוף מסכת תמיד ויהיב טעמא בפרק בתרא דראש השנה (דף ל\\\"א):\",1,0],[8,364,6,9,\"במוספי שבת אומרים שירת האזינו וחולקין אותה לששה פרקים וכו' עד ומי כמוכה. בפרק בתרא דראש השנה שם:\",2,0],[8,364,6,9,\"במוסף של ראש השנה היו אומרים הרנינו לאלהים עוזנו וכו' עד יחיל מדבר. שם (דף ל' ע\\\"ב):\",3,0],[8,364,6,10,\"ראש חדש שחל להיות בשבת וכו'. ברייתא בפרק החליל (סוכה דף נ״ד:) ואע״ג דהתם אוקי רב ספרא מאי דוחה דוחה לקדם היינו כדי לתרוצי ברייתא אליבא דרבי אחא ומכיון דאיתותב התם ר' אחא נקטינן ברייתא כפשטא:\",1,0],[8,364,6,11,\"בשבת מקטירים את שני בזיכי לבונה עם המוספין. בפרק שלישי דיומא (דף ל\\\"ד) בסדר מערכה דמסדר אביי מוספין קודמין לבזיכין והא תניא בזיכין קודמין למוספין תנאי היא אמר אביי מסתברא כמאן דאמר מוספין קודמין לבזיכין. ורבינו\",1,0],[8,364,6,11,\"שכתב עם המוספין קודם ניסוך יין של מוספין היינו לומר שבזיכין אחר המוספין והכי דייק לישניה שכתב קודם ניסוך היין של מוספין ומכל מקום צריך למוד מנין לו שהיו קודם לניסוך היין:\",2,0],[8,364,6,11,\"וכסדר שעושים בכל יום בבקר וכו' כמו שביארנו. בפרק ד':\",3,0],[8,364,7,1,\"בראשי חדשים מקריבין מוסף ראש החדש אחר תמיד של שחר. כסדר מערכה שסידר אביי בפרק ג' דיומא (דף ל\\\"ג) תמידין קודמין למוספין:\",1,0],[8,364,7,2,\"מעשה כל העולות אחד הוא וכו' כמעשה החטאת הנאכלת שביארנו. בפ\\\"ו ופ\\\"ז מהלכות מעשה הקרבנות:\",1,0],[8,364,7,3,\"ביום שני של פסח וכו' כמו שביארנו. בפי\\\"ב מהלכות הנזכרות:\",1,0],[8,364,7,4,\"ומ\\\"ש וזמנו קבוע לפיכך דוחה את השבת ואת הטומאה. משנה בפ\\\"ב דתמורה (דף י\\\"ד) ואיתא בפ' רבי ישמעאל (מנחות ע\\\"ב:):\",1,0],[8,364,7,5,\"אין מביאין מנחה זו אלא מא\\\"י וכו' עד יביאו מן היבש. משנה במנחות פרק כל קרבנות הצבור (דף פ\\\"ה:) וקצתו בת\\\"כ:\",1,0],[8,364,7,10,\"דרכן היה להביא משדות שבדרום. במנחות שם (דף פ\\\"ה) והטעם מפני שבהם חמה זורחת כל היום.\",1,0],[8,364,7,10,\"ומ\\\"ש היה נר חצי השדה וכו'. שם:\",2,0],[8,364,7,11,\"עומר זה מן השעורים היה בא וכו'. במנחות פרק ר' ישמעאל (מנחות דף ס״ח) ופרק כל קרבנות (מנחות דף פ״ד):\",1,0],[8,364,7,11,\"וכיצד היה נעשה וכו' עד מפני הטועים. משנה במנחות פרק ר\\\"י (דף ס\\\"ה):\",2,0],[8,364,7,12,\"קצרוהו ונתנוהו בקופות וכו' עד כשיירי כל המנחות. גם זה משנה שם (דף ס\\\"ו).\",1,0],[8,364,7,12,\"ומ\\\"ש כמו שביארנו. הוא בפ\\\"ג מהל' ביכורים ופרק י\\\"ג מהלכות מעשר ראשון:\",2,0],[8,364,7,12,\"ואימתי קומצין אותו לאחר שמקריבים מוסף היום. משום דתדיר קודם.\",3,0],[8,364,7,12,\"ומ\\\"ש וכבש העולה בסוף הוריות (דף י\\\"ג) עומר קדם לכבש הבא עמו:\",4,0],[8,364,7,14,\"אסור לקצור בארץ ישראל מין מחמשת מיני תבואה וכו' עד אלא יניחם צבתים צבתים. משנה במנחות פרק ר' ישמעאל (מנחות דף ע״א):\",1,0],[8,364,7,14,\"ומ\\\"ש קודם לקצירת העומר. יש לתמוה דבגמרא משמע דקודם הבאת העומר קאמר:\",2,0],[8,364,7,15,\"ומה שאמר תבואה שלא הביאה שליש וכו'. פלוגתא דתנאי שם ופסק כר' יהודה דאמר אימתי אינו אלא לפרש דברי תנא קמא:\",1,0],[8,364,7,17,\"כבר ביארנו. פ\\\"ז מאיסורי מזבח:\",1,0],[8,364,7,17,\"שאין מביאין מנחות וכו'. ג\\\"ז משנה שם (דף ס\\\"ח ע\\\"ב):\",2,0],[8,364,7,18,\"וכל המקריב מנחה מן החדש תחלה מברך שהחיינו. הכי משמע בהא דתניא בפרק כיצד מברכין (ברכות דף ל״ז:) היה עומד ומקריב מנחות בירושלים אומר ברוך שהחיינו ודלא כפירש״י והתוספות:\",1,0],[8,364,7,19,\"תבואה שזרעה אחר שקרב העומר וכו'. כך היא הגירסא הנכונה בדברי רבינו והוא במנחות פרק ר' ישמעאל (מנחות דף ס״ח ע״ב) בעיא דלא איפשיטא:\",1,0],[8,364,7,20,\"וכן תבואה שהיתה בקרקע וחנטו עליה וכו'. גם זה שם בעיא דלא איפשיטא:\",1,0],[8,364,7,21,\"והקוצר קודם קצירת העומר אינו לוקה והקציר כשר:\",1,0],[8,364,7,22,\"מ״ע לספור שבע שבתות תמימות וכו' עד מליל ט״ז בניסן. במנחות פרק רבי ישמעאל (מנחות דף ס״ו):\",1,0],[8,364,7,22,\"שכח ולא מנה בלילה מונה ביום. כן כתב בה\\\"ג.\",2,0],[8,364,7,23,\"ואין מונין אלא מעומד וכו'. כתב הר\\\"י בן גיאת שזה קבלה מפי רבותינו ואסמכוה אקרא דבקמה קרי ביה בקומה. ובזוהר פרשת תצוה כתב סוד הדבר למה צריך למנות מעומד:\",1,0],[8,364,7,24,\"מצוה זו על כל איש מישראל. בפרק ר' ישמעאל תנו רבנן וספרתם לכם שתהא ספירה לכל אחד ואחד.\",1,0],[8,364,7,24,\"ומ״ש בכל מקום ובכל זמן. דעת רבינו שאף בזמן הזה היא מצוה מן התורה ובפרק ר' ישמעאל (מנחות דף ס״ז) אמרינן אמר אביי מצוה למימני יומי ומצוה למימני שבועי [רבנן] דבי רב אשי מני יומי ומני שבועי אמימר מני יומי ולא מני שבועי אמר זכר למקדש [הוא]. ופירש״י ולא מני שבועי אמר האי מניינא דהשתא לאו חובה הוא דהא ליכא עומר אלא זכר למקדש בעלמא הוא הילכך ביומי סגי עכ״ל. ומשמע דאביי ורב אשי נמי סברי דזכר למקדש בעלמא הוא ואפ״ה מצוה למימני שבועי. ומדברי רבינו נראה שהוא מפרש דאי הוה סבירא להו דזכר למקדש בעלמא הוא לא הוו מצרכי למימני שבועי ומשום דסבירא ליה דגם בזמן הזה מצוה מן התורה מצרכי למימני שבועי ופסק כוותייהו וכ״כ הר״ן לדעת רבינו.\",2,0],[8,364,7,24,\"ומ\\\"ש ונשים ועבדים פטורין ממנה. משום דמצות עשה שהזמן גרמא הוא:\",3,0],[8,364,7,25,\"וצריך לברך בכל לילה וכו'. פשוט הוא שמברכין עליה כדרך שמברכין על כל המצות.\",1,0],[8,364,7,25,\"ומה שכתב מנה ולא בירך יצא וכו'. פשוט הוא דברכות אינם מעכבות:\",2,0],[8,364,8,1,\"ביום חמשים מספירת העומר וכו'. בפרשת אמור כתוב והקרבתם על הלחם שבעת כבשים ופר בן בקר אחד ואילים שנים יהיו עולה ושעיר חטאת ושני כבשים שלמים ובפרשת פנחס כתוב והקרבתם עולה פרים שנים איל אחד שבעה כבשים שעיר עזים אחד מלבד עולת התמיד. ובפרק התכלת (מנחות דף מ״ה ע״ב) איפליגו תנאי ודעת ר״ע שאין [כבשים] של ת״כ הן האמורים בחומש הפקודים ונתבאר שם שאותם שבפרשת אמור באים בגלל הלחם אבל שבפרשת פנחס בגלל עצמם הם באים כי הם מוספי היום ואע״ג דרבי טרפון פליג עליה פסק רבינו כר״ע:\",1,0],[8,364,8,2,\"שתי הלחם אינן באים אלא מן החדש ומן הארץ וכו'. במנחות (דף ע\\\"ג:) ר\\\"פ כל קרבנות הצבור והיחיד באים מהארץ ומח\\\"ל מן החדש ומן הישן חוץ מהעומר ושתי הלחם שאינם באים אלא מן החדש ומן הארץ ובגמ' מתני' דלא כי האי תנא דתניא עומר הבא מן הישן כשר שתי הלחם הבאות מהישן כשירות אלא שחיסר מצות עומר דכתיב תקריב את מנחת בכוריך ואפי' מן העליה ופירש\\\"י מן העליה ישנים שבעליה. ורבינו פסק כברייתא ויש לתמוה למה הניח המשנה ופסק כברייתא ואפשר שלזה נתכוון הראב\\\"ד שכתב הלכה זו בהפך עכ\\\"ל. ואפשר שכוונתו לומר דלישנא דמתני' דקתני שאינם באים היינו לומר שאם לא הביא מהחדש פסול מדקאמר עלה מתני' דלא כי האי תנא וכיון שרבינו פוסק כברייתא לא ה\\\"ל לתפוס בלשון המשנה, ולזו י\\\"ל דלישנא דשאינם באים שפיר משמע לכתחלה כי מסיים בה אם הביא מן הישן כשר ומאי דדייק בגמ' מתניתין דלא כי האי תנא היינו משום דלא מסיים בה הכי. ולענין אמאי שבק מתני' ופסק כברייתא י\\\"ל דטעמיה משום דבגמרא מפרש טעמא דברייתא ולא פירש טעמא דמתני', ואפשר לומר עוד שרבינו מפרש דלתנא דמתניתין נמי אם הביא מן הישן כשר ולישנא דמתני' הכי משמע דהא כל קרבנות וכו' באים מן הישן היינו אפילו לכתחלה ובההוא גוונא קאמר דעומר ושתי הלחם אינם באים אלא מן החדש דהיינו לכתחילה ומאי דקאמרה גמרא מתני' דלא כי האי תנא היינו ללמד דלתנא דברייתא לכתחילה נמי מותר להביא שתי הלחם מן הישן מדלא קתני לא יביא מן הישן ואם הביא כשר ועוד מדפלגינהו בברייתא לעומר ושתי הלחם ולא ערבינהו למיתני עומר ושתי הלחם הבאים מן הישן כשרים משמע דטעמא משום דלא שוו בדינייהו דעומר לכתחלה צריך להביא מהחדש אבל שתי הלחם לכתחלה נמי יכול להביא מן הישן לדעת הברייתא ומאי דקאמר בגמרא על הברייתא והא כתיב ראשית למצוה היינו למצוה מן המובחר ומאן דלא בעי מצוה מן המובחר יכול להביא מן הישן אף לכתחילה לתנא דברייתא אבל לתנא דמתני' לכתחילה צריך להביא מן החדש ומאי דקאמר ע\\\"כ לא פליגי אלא בחדש היינו לכתחלה אבל אם לא מצא לכ\\\"ע יביא מהישן ולפי פי' זה שפיר פסק רבינו כתנא דמתני' ואע\\\"פ שרש\\\"י בכמה לשונות הוא נזהר מפירוש זה רבינו אפשר שמפרשו:\",1,0],[8,364,8,3,\"חטים שירדו בעבים וכו'. במנחות פ רבי ישמעאל (ס\\\"ט:) בעיא דלא איפשיטא ופירש\\\"י שירדו בעבים עם המטר כששתו העבים באוקיאנוס בלעו ספינה מליאה חטים:\",1,0],[8,364,8,3,\"וכיצד היו עושים מביאין ג' סאין חטים חדשות וכו' עד ובי\\\"ג נפה. בס\\\"פ אלו מנחות (דף ע\\\"ז:).\",2,0],[8,364,8,3,\"ומ\\\"ש כמו שביארנו. בפ\\\"ו מהל' בכורים ובפי\\\"ג מהל' מעה\\\"ק:\",3,0],[8,364,8,5,\"ומ\\\"ש וכולן אם ריבה כמדת הסאים שבאים מהם או מיעט כשר. ברייתא פ' כל המנחות ואיתיה בתוספתא דמנחות פ\\\"ח העומר ושתי הלחם ולחם הפנים שריבה מדת עשרונן או שחיסר מדת עשרונן שהיתה מדה מרובה מחברתה או חסרה מחברתה הרי אלו פסולות ריבה מדת סאין או שחיסר מדת סאין הרי אלו כשירות:\",1,0],[8,364,8,6,\"ולשין אותן אחד אחד וכו' עד שהוא י״ט. משניות בפרק שתי הלחם (מנחות דף צ״ד):\",1,0],[8,364,8,9,\"ומ״ש וכיצד עושה מביא שאור ממקום אחר וכו'. משנה בריש פרק כל המנחות (מנחות דף נ״ב ע״ב) פלוגתא דר״מ ור״י וידוע דהלכה כר״י:\",1,0],[8,364,8,10,\"ומ״ש ומרובעות הן אפשר דיליף לה מלחם הפנים. ומ״ש אורך כל חלה שבעה טפחים ורחבה ארבעה טפחים וגובהה ד' אצבעות. משנה בפרק שתי הלחם (מנחות דף צ״ו) ומפרש רבינו קרנותיו גובהה ורש״י פירש בע״א:\",1,0],[8,364,8,11,\"כיצד הנפת הלחם וכו' ומניפם בעודם חיים. משנה בפ' כל המנחות (מנחות דף ס״א).\",1,0],[8,364,8,11,\"ומ\\\"ש ואם הניף זה בפני עצמו וזה בפ\\\"ע יצא. שם יליף מקראי גבי אשם ולוג שמן שטעונים תנופה כאחד ואם הניף זה בעצמו וזה בעצמו יצא ומשמע דילפינן מהתם לשני כבשי עצרת.\",2,0],[8,364,8,11,\"ומ\\\"ש ולוקח חזה ושוק. שם (דף ס\\\"ב) ת\\\"ר זבחי שלמי ציבור טעונים תנופה לאחר שחיטה ותנופתן כמות שהן דברי רבי וחכ\\\"א כחזה ושוק.\",3,0],[8,364,8,11,\"ומ\\\"ש ומניחם בצד שתי הלחם. שם פלוגתא דתנאי בברייתא ופסק כרבי משום דמסתבר טעמיה ועוד דאבא שאול סבר כוותיה.\",4,0],[8,364,8,11,\"ומ\\\"ש ומניח ב' ידיו מלמטה. שם במשנה.\",5,0],[8,364,8,11,\"ומ\\\"ש ומניף הכל כאחד במזרח במקום כל התנופות מוליך ומביא מעלה ומוריד. שם במשנה.\",6,0],[8,364,8,11,\"ומ\\\"ש ואם הניפן אחד אחד יצא. אפשר שהוא נלמד מאשם ולוג שמן כדבסמוך:\",7,0],[8,364,8,11,\"ומה שכתב וכן שתי החלות נוטל כ\\\"ג אחת מהן. זה על פי מה שנתבאר בספ\\\"ד שכ\\\"ג בלחם הפנים נוטל מכל משמר חצי החלות:\",8,0],[8,364,8,11,\"ושאר הבשר נאכל לכהנים. כלומר ואינם כשאר שלמים שהם קדשים קלים ונאכלים לבעלים חוץ מהאימורים אבל שלמים אלו קדש קדשים הם ואינם נאכלים אלא לכהנים.\",9,0],[8,364,8,11,\"ומ\\\"ש ושתיהן נאכלות אותו היום וחצי הלילה וכו':\",10,0],[8,364,8,12,\"שחט שני כבשים על ארבע חלות וכו'. בפרק התכלת (מנחות דף מ״ו:) ת״ר שחט שני כבשים על ארבע חלות מושך שתים מהם ומניפן והשאר נאכלים בפדיון ואמרי' בגמ' אליבא דר״י דהיינו דוקא בדאמר ליקדשו תרתי מגו ארבע אבל אם לא אמר כן לא קדשי.\",1,0],[8,364,8,12,\"ומ\\\"ש והשאר פודים אותם בפנים. שם אמרינן הכי אליבא דרבי דאמר שחיטה מקדשם אבל לר\\\"א בר\\\"ש דפליג עליה אין פודין אותם אלא בחוץ. ופסק רבינו כרבי דהלכה כרבי מחבירו:\",2,0],[8,364,8,13,\"שחט ארבעה כבשים על שתי חלות וכו'. שם (דף מ\\\"ח):\",1,0],[8,364,8,14,\"שתי החלות מעכבות זו את זו ושני הכבשים מעכבין זה את זה. משנה פרק הקומץ רבה (מנחות דף כ״ז):\",1,0],[8,364,8,14,\"מת אחד משניהם וכו' יקח זוג לשני. תוספתא בפ\\\"ה דמנחות:\",2,0],[8,364,8,14,\"שחט אחד מהם לשמו. כלומר ואח\\\"כ מת האחר או נעשה טריפה או ברח יקח לו זוג לראשון והוא בתוספתא הנזכרת:\",3,0],[8,364,8,15,\"שתי הלחם מעכבין את הכבשים וכו'. במשנה פרק התכלת (מנחות דף מ״ה:) פלוגתא דתנאי הלחם מעכב את הכבשים ואין הכבשים מעכבים את הלחם דברי ר״ע אמר ר״ש בן ננס לא כי אלא הכבשים מעכבים את הלחם והלחם אינו מעכב (את) הכבשים שכן מצינו כשהיו ישראל במדבר ארבעים שנה קרבו כבשים בלא לחם אף כאן יקרבו כבשים בלא לחם אר״ש הלכה כדברי בן ננס אבל אין הטעם כדבריו [שכל האמור בחומש הפקודים קרב במדבר] וכל האמור בת״כ אין קרב במדבר משבאו לארץ קרבו אלו ואלו ומפני מה אני אומר יקרבו כבשים [בלא לחם] שהכבשים מתירים את עצמם ולא הלחם בלא כבשים שאין לו מי יתירנו, ולכאורה משמע דהלכה כר״ש ור״ש בן ננס דרבים נינהו ועוד דיהבי טעמא למילתייהו ויש לתמוה על רבינו שפסק כר״ע וז״ש הראב״ד הלכה זו בהפך עכ״ל. וי״ל לדעת רבינו שהוא סובר דמ״מ הלכה כר״ע דהוא מאריה דגמרא טפי מהנך תנאי וטעמא דבן ננס הא איפרך וטעמא דרבי שמעון איכא למידחי דאע״ג דר״ש יהיב טעמא שלחם בלא כבשים אין לי מי יתירנו איכא למימר דאע״ג דכשהלחם בא עם הכבשים הכבשים מתירין את הלחם כשהלחם בא לבדו הוא עצמו מתיר את עצמו. ועוד דבגמרא אמרינן מ״ט דרבי עקיבא גמר יהיו מתהיינה מה להלן לחם אף כאן לחם ובן ננס גמר יהיו יהיו מה להלן כבשים אף כאן כבשים ושקיל וטרי גמרא ובסוף קמה טענת ר״ע ולפיכך פסק כוותיה ועוד דאיתא התם בגמרא (דף נ״ו) ת״ר שתי הלחם הבאות בפני עצמן יונפו כו' עד אף שתי הלחם נמי לאכילה והאי ברייתא כר״ע אתיא ומדשקלי וטרו בה אמוראי משמע דסברי דהלכתא כוותיה.\",1,0],[8,364,8,15,\"ומ״ש ואם הונפו עם הכבשים מעכבים זה את זה ואם אבד הלחם יאבדו הכבשים וכו' בפרק התכלת (מנחות דף מ״ו) איבעיא לן תנופה עושה זיקה או לא ואסיקנא בתיקו וא״כ לא היה לרבינו לכתוב הלכה פסוקה בדבר וכבר השיגו הראב״ד וכתב א״א ספק הוא בגמרא עכ״ל. ואפשר שטעם רבינו מדאמרי' בתר הכי א״ל אביי לרבא מ״ש ב' כבשים דמעכבי לחם ומאי שנא שבעה כבשים ופר ואילים דלא מקדשי לחם ולא מעכבי א״ל הואיל והוזקקו זה לזה בתנופה משמע דס״ל דתנופה עושה זיקה:\",2,0],[8,364,8,16,\"שתי הלחם הבאות בפני עצמן וכו'. ברייתא וגמרא שם:\",1,0],[8,364,8,16,\"הפר ושני האילים וכו'. משנה שם (דף מ\\\"ד):\",2,0],[8,364,8,17,\"שני פרים של מוסף היום ופר וכו'. משנה שם הפרים והאילים והכבשים והשעירים אינם מעכבים זה את זה ובגמרא הני פרים וכבשים וכו' דעצרת וכו' אילים דהיכא וכו' אי דתורת כהנים הויה כתיב בהו לעולם דעצרת דתורת כהנים וה\\\"ק לא אילים דתורת כהנים מעכבי ליה לאיל דחומש הפקודים ולא איל דחומש הפקודים מעכב לאילים דתורת כהנים אלא פרים דאפילו אהדדי לא מעכבי ואילים דהכא והכא הוא דלא מעכבי אינהו מעכבי תנא מילי מילי קתני. פי' וגבי פרים וכבשים אין מעכבים אפילו אהדדי אבל אילים אהדדי מעכבי אלא שבתורת כהנים עם של חומש הפקודים אינם מעכבין אלו לאלו:\",1,0],[8,364,8,19,\"ומ\\\"ש שבעה כבשים וכו' אינם מעכבים כו'. לא אלו את אלו ולא הם בעצמם וכמו שביאר מיד שאין המוספין מעכבין וכו' והוא כמו שנתבאר מהמשנה דבהו אין עיכוב כלל ומילי מילי קתני. ודברי רבינו מדוייקים כן דגבי פרים כתב שני פרים אין מעכבין זה את זה וגבי אילים לא כתב כן אלא כתב איל וכו' ושני אילים אין מעכבין ולא כתב כמו שכתב גבי פרים אין מעכבין זה את זה מוכח דשני אילים גופייהו מעכבין ולא דמו לפרים וגבי פרים היה יכול לכתוב כמו שכתב גבי אילים דהתם נמי איכא פר אחד ושני פרים אלא ודאי לכך נתכוון.\",1,0],[8,364,8,19,\"ומ\\\"ש אם נשחטו כולן מעכבין זה את זה. שם (דף מ\\\"ו:) אמר ר\\\"י הכל מודים שאם הוזקקו זה לזה שמעכבין זה את זה ואי זו היא זיקה שלהם שחיטה ופירש\\\"י שאם הוזקקו זה לזה שהיה ביחד ואח\\\"כ אבד לחם או כבשים שמעכבין זה לזה והנותר לפנינו יצא לבית השריפה דנדחה באיבוד חבירו ואי זו היא זיקה שלהן הקבעתן יחד שחיטה שאם היה לחם בשעת שחיטה ואח\\\"כ אבד או לחם או כבשים אבד הכל. ויש לתמוה על מה שכתב הראב\\\"ד איל של מוסף וכו' א\\\"א לא ידעתי שחיטה זו בכאן מה היא והל\\\"ל אבל הן עצמן דת\\\"כ מעכבין זה את זה מ\\\"ט הויה כתיב בהו עכ\\\"ל, שהרי מ\\\"ש רבינו שאם נשחטו מעכבין זה את זה מבואר הוא בברייתא וכדברי ר\\\"י שכתבתי. וכתב הר\\\"י קורקוס ז\\\"ל דעת הראב\\\"ד כרש\\\"י דההיא דר\\\"י אכבשים שאין מעכבין את הלחם לחוד קאי דבהנהו דוקא קובעת שחיטה עכ\\\"ל:\",2,0],[8,364,8,20,\"ומה שכתב ואינם חייבים להקריב השאר למחר וכו': לא מצאו אלא שני כבשים וכו'. בפרק התכלת (מנחות דף מ״ט) בעיא דלא איפשיטא:\",1,0],[8,364,9,1,\"באחד בתשרי מקריבים מוסף היום וכו'. מפורש בפרשת פנחס.\",1,0],[8,364,9,1,\"ומ״ש לפיכך אם חל להיות בשבת היו שם ג' מוספין וכו'. בפ' החליל (סוכה דף נ״ד):\",2,0],[8,364,9,2,\"שכל התדיר מחבירו קודם את חבירו. משנה בזבחים ר״פ כל התדיר (זבחים דף פ״ט):\",1,0],[8,364,9,2,\"ומה שכתב וכן כל המקודש מחבירו קודם את חבירו. שם במשנה.\",2,0],[8,364,9,2,\"ומה שכתב היה לפניו תדיר ומקודש וכו'. שם (דף צ':) בעיא דלא איפשיטא ולפיכך פסק רבינו דאי זה מהם שירצה יקדים ופירש\\\"י תדיר ומקודש כגון דם עולת תמיד ודם חטאת התמיד תדיר והחטאת מקודש ממנו כדתנן דם חטאת קודם לדם עולה מפני שהוא מרצה:\",3,0],[8,364,9,3,\"ומ\\\"ש עבר או שכח ושחט את שאינו תדיר וכו'. שם (דף צ') בעיא בשחט את שאינו תדיר תחלה ומשמע דאיפשיטא ולמד רבינו ממנו לשחט את הפחות בקדושה תחלה:\",1,0],[8,364,9,4,\"ומ״ש ואם נשחטו שניהם כאחד יהיה זה ממרס בדם וכו'. נלמד ממה ששנינו בפרק תמיד נשחט (פסחים דף ס״א) שחט קרבן פסח קודם לתמיד יהיה אחד ממרס בדמו עד שיזרק דם התמיד:\",1,0],[8,364,9,5,\"דם חטאת קודם לדם עולה וכו' איברי עולה קודמין לאימורי חטאת וכו'. משנה שם זבחים (דף פ\\\"ט):\",1,0],[8,364,9,5,\"דם חטאת ואיברי עולה וכו'. שם בעיא דלא איפשיטא.\",2,0],[8,364,9,5,\"ומ\\\"ש דם העולה ודם אשם וכו'. בעיא שם (דף צ') ואתינן למיפשטה מדתנן חטאת קודמת לאשם חטאת הוא דקדמה ליה לאשם אבל עולה לא מאי לאו דם לא אאימורים דיקא נמי דקתני מפני שהיא מתנה ש\\\"מ. ולפ\\\"ז משמע דבעיין אפשיטא ורבינו דמשמע מדבריו דלא איפשיטא אפשר שלא היה גורס האי דיקא נמי דקתני:\",3,0],[8,364,9,6,\"חטאת קודמת לעולה וכו'. משנה וברייתא שם. וכתב הר\\\"י קורקוס ז\\\"ל נראה שהכוונה שישחוט החטאת ויקריב אותה לגמרי ואח\\\"כ העולה ולעיל דמפליג בין דם לאיברים שאמרו שהדם של חטאת הוא שקודם ואיברי עולה קודמין היינו כשנשחטו שניהם ושני הדמים לפנינו ואנו באים לידע אי זה דם יקדום שזורק של חטאת ואחר שזורק שני הדמים ואיברי שניהם לפנינו ואנו באים לדון על האיברים אז מקדים של עולה מפני שכולה כליל עכ\\\"ל. והאריך להוכיח שכן צריך לפרש.\",1,0],[8,364,9,6,\"ומ\\\"ש וכן בשעת הפרשה וכו'. תוספתא פרק י' דזבחים:\",2,0],[8,364,9,7,\"בקרבנות החג אינו כן וכו' עד שכך הוא סדר הכתוב בתורה. בפרק כל התדיר (זבחים דף צ') וכרבינא דאמר כמשפט כתיב בהו:\",1,0],[8,364,9,7,\"שעיר ע\\\"ז קודם לשעיר נשיא. בסוף הוריות (דף י\\\"ג) ויהיב טעמא משום דהאי צבור והאי יחיד.\",2,0],[8,364,9,7,\"ומ\\\"ש ושעיר נשיא קודם לשעירת יחיד. שם ויהיב טעמא משום דהאי מלך והאי הדיוט.\",3,0],[8,364,9,7,\"ומ\\\"ש ושעירת יחיד קודמת לכבשה. שם ואע\\\"ג דאמר התם אביי דתנאי היא פסק רבינו כתנא דסתם גמרא כוותיה ויהיב טעמא התם שעירה עדיפא שכן נתרבה אצל ע\\\"ז ביחיד. ונראה שרבינו מפרש דה\\\"ק שכשנכתבה אצל ע\\\"ז ביחיד לא לענין זה לבדו נתייחדה שהרי לחטאות אחרות היא באה ונתרבית לבא גם על ע\\\"ז דיחיד:\",4,0],[8,364,9,8,\"אפילו חטאת העוף של יולדת קודמת לכבשה. תוספתא פ\\\"י דזבחים פירוש לכבשה לכבש שלה במפיק ה\\\"א וה\\\"ק החטאת בכל ענין קודם לעולה אפילו של יולדת שאינה על חטא ידוע:\",1,0],[8,364,9,8,\"חטאת קודמת לאשם וכו'. עד שהם מיני דמים. משנה בפרק כל התדיר (זבחים דף פ״ט:):\",2,0],[8,364,9,8,\"וכל החטאות שבתורה וכו'. משנה שם (דף צ':) ופירש\\\"י מפני שהוא בא על ידי הכשר מפני שהוא בא להכשיר את המצורע לקדשים ולביאת המקדש הילכך חשיבות הוא לגביה שטהרה תלויה בו:\",3,0],[8,364,9,8,\"ומ\\\"ש והתודה קודמת לאיל נזיר וכו'. שם (דף צ') בעיא דאיפשיטא:\",4,0],[8,364,9,8,\"הרי שהיו לפניו חטאת העוף ומעשר וכו' היו שם חטאת העוף ומעשר ועולת בהמה וכו'. שם (דף צ':) איבעיא להו חטאת העוף ועולת בהמה ומעשר איזה מהם קודם וכו' הכא תרגימו מין זבח עדיף במערבא אמרי עיילא בה עולת בהמה בחטאת העוף ואגבהתה ממעשר. ופירש\\\"י הכא תרגימו בבבל. מין זבח עדיף ויקדים מעשר ואח\\\"כ חטאת ועולה דאילו עולת בהמה לא מצי קדמה לחטאת העוף מגזירת הכתוב. עיילא בה חשיבות דעולת בהמה שבאה עמה והיא חשובה ממעשר שהיא קדשי הקדשים וכליל ומגזירת הכתוב החטאת קודמת ואע\\\"פ שזו מין זבח. ואגבהתה ממעשר לבטל חשיבות שם מין זבח שבו דהא בעולה נמי איתיה לאותה חשיבות ובטל ליה מגזירת הכתוב הילכך יקדים חטאת העוף לעולה ועולה למעשר. ופסק רבינו כבני מערבא משום דמסתבר טעמייהו:\",5,0],[8,364,9,9,\"הרי שהיו מיני בהמה הרבה ממין קרבן אחד וכו'. גם זה שם:\",1,0],[8,364,9,9,\"העומר קודם לכבש הבא עמו וכו' עד לדבר הבא בגלל הלחם. ברייתא בסוף הוריות (דף י\\\"ג:):\",2,0],[8,364,9,10,\"מנחת האיש קודמת למנחת האשה וכו'. תוספתא פ\\\"י דזבחים.\",1,0],[8,364,9,10,\"ומ״ש מנחת חוטא קודמת למנחת נדבה וכו' מנחת נדבה ומנחת סוטה אי זו מהם שירצה יקדים. בעיא בפרק כל התדיר (זבחים דף צ') נדבה קודמת שכן טעונה שמן ולבונה א״ד מנחת סוטה קודמת שכן באה לברר עון ולא איפשיטא הלכך אי זו מהם שירצה יקדים דשקולות הם:\",2,0],[8,364,9,11,\"ומ\\\"ש מנחות קודמין ליין וכו' עד והבא אחרון קרב אחרון. תוספתא פ\\\"י דזבחים אע\\\"פ שיש בה קצת ט\\\"ס ומשמע התם שמה שאמרו אימתי בזמן שבאו כולם כאחת וכו' קאי גם למנחת האיש קודמת וכו' ומנחת חטים קודמת וכו':\",1,0],[8,364,10,11,\"בכל יום ויום מימי החג וכו'. בפרק החליל (סוכה דף נ״ה) ופירש״י ואם חל שבת באחד מהם ידחו שיר המועד מלפני שיר שבת ימוטו ידחה שהוא שיר אחרון ונדחה מפני שאמרו באחד בשבת שיר שהיה ראוי לומר אתמול שאין מדלגין סדר השיר ובשני שיר של אחד בשבת נמצא האחרון נדחה:\",1,0],[8,364,10,12,\"כבר ביארנו. בהלכות כלי המקדש פ\\\"ג ופ\\\"ד.\",1,0],[8,364,10,12,\"ומ״ש וכולם עובדים בשוה ברגלים ובחג הסוכות היה כל משמר מקריב פר אחד או איל אחד וכו' עד ובשמיני חוזרים לפייס כולם כאחד כשאר הרגלים. משנה בפרק החליל (סוכה דף נ״ה:):\",2,0],[8,364,10,13,\"ומ\\\"ש כמו שביארנו. הוא בהלכות כלי המקדש פ\\\"ב:\",1,0],[8,364,10,14,\"ביום טוב הראשון של חג שחל להיות בשבת היה שם מנחת נסכים וכו'. משנה בפ' המנחות והנסכים (מנחות דף ק״ג:).\",1,0],[8,364,10,14,\"ומ\\\"ש ולא היו מערבים אותם. שם במשנה:\",2,0],[8,364,10,15,\"ומ״ש ולעולם אין מערבים נסכים וכו'. בפרק שתי מדות (מנחות דף פ״ט) תנן מערבין נסכי פרים בנסכי אילים נסכי כבשים בנסכי כבשים של יחיד בשל ציבור של יום בשל אמש אבל אין מערבין נסכי כבשים בנסכי פרים ואילים ואם בללן אלו בפני עצמן ואלו בפני עצמן ונתערבו כשרים אם עד שלא בלל פסול ובגמרא ורמינהי והקטירו שלא יערב חלבים בחלבים אר״י אם נתערבו קאמר א״ה ואין מערבין נסכי כבשים בנסכי פרים ואילים ואפילו נתערבו נמי לא והא מדקתני סיפא בללן אלו בפני עצמן ואלו בפני עצמן ונתערבו כשרים מכלל דרישא לכתחילה קאמר אמר אביי ה״ק מערבין יינן אם נתערבה סלתן ושמנן ויין לכתחלה לא והתניא בד״א בסלת ושמן אבל יין מערבים אלא אמר אביי ה״ק היכא דהוקטר סלתן ושמנן מערבין יין לכתחילה היכא דלא הוקטר אם נתערב סולתן ושמנן מערבין נמי יינן ואם לאו אין מערבין דילמא אתי לערובי סלת ושמן לכתחלה. ופירש״י מערבין נסכי פרים האי מיין ושמן קאמר וה״ק מערבין יין נסכי פרים ביין נסכי אילים ואע״ג דלפר אית ליה ג' עשרון סלת וחצי ההין יין ושמן ולאיל שני עשרון סלת ושלישית ההין יין וכן שמן אעפ״כ מערבין זה בזה משום דשניהן בלילתן שוה דלתרווייהו איכא שני לוגין לעשרון דבאיל כתיב שלישית ההין לאיל דהיינו ארבעה לוגין והוא הדין לשמן וכתיב שלשה עשרונים לפר דהיינו שני לוגין לעשרון וכיון דבלילתן שוה מש״ה מערבין נסכיהם ומערבין נמי נסכי כבשים בנסכי כבשים כגון בנסכי מוספין משום דתרוייהו בלילתן רכה דבשניהם יש שלשה לוגין שמן לעשרון וכו'. אבל אין מערבין וכו' משום דהללו בלילתם רכה והללו בלילתן עבה. בללן לנסכי פרים בפני עצמן ולנסכי כבשים בפני עצמן ושוב נתערבו כשרים ואם נתערבו עד שלא בלל פסולה. שלא יערב חלבים הכי נמי לא יערב נסכים. אמר ר' יוחנן לא תימא מערבין לכתחלה אלא אם נתערבו קאמר והא דקתני והקטיר שלא יערב לכתחלה מיירי. א״ה דקתני במתני' אבל אין מערבין נסכי כבשים בנסכי פרים דאפילו נתערבו דיעבד נמי לא והא מדקתני סיפא נתערבו כשרות דהיינו דיעבד מכלל דרישא אין מערבין לכתחלה וה״ה רישא דרישא נמי מערבין לכתחלה והדרא קושיא לדוכתיה שלא יערב חלבים בחלבים. אמר אביי ודאי רישא דמתני' דתני מערבין לכתחלה היא ולא תיקשי לך ונתערבו נסכים דמתני' ביינן קא מיירי וה״ק מערבין יינן של נסכים פרים ואילים לכתחלה אם נתערב כבר סלתן בשמנן מאליהן הואיל והתחיל לערב ליכא משום לא יערב חלבים והא דתני אבל אין מערבין נסכי כבשים בנסכי פרים אפילו היכא דנתערב סלתן ושמנן. ויין לכתחילה לא אפילו דכבשים ופרים אם לא נתערב סלתן ושמנן והא תניא במה דברים אמורים דאין מערבין נסכי כבשים בנסכי פרים ואילים בסלת ושמן אבל יין מערבין לכתחלה בין נתערב סלתן ושמנן בין לא נתערב אלא אמר אביי היכא דהוקטר כבר סלתן ושמנן של פרים ואילים כמצותן מערב יין לכתחלה דליכא למיחש דילמא אתי לערובי סלתן ושמנן דבני הקטרה נינהו ואיכא משום והקטירו שלא יערב חלבים בחלבים שהרי כבר מעורבין ועומדין ואם לאו דלא הוקטר סלתן ושמנן אין מערבין דחיישינן דילמא אתי לאיערובי סלת ושמן לכתחילה דאסור שלא יערב חלבים בחלבים והא דקתני ברישא אבל יין מערבין היינו אם הוקטר סלתן ושמנן והא דקתני מציעתא דמתניתין אבל אין מערבין היינו בשלא נתערב סלתן ושמנן עכ״ל. נמצא דאין מערבין חלבים בחלבים ולא סלתן ושמנן מדינא דכתיב והקטירו ויין ביין אין מערבין לכתחלה משום גזירה וסלתן ושמנן לעולם אין מערבין אלו עם אלו ואם בללו אלו בפ״ע ואלו בפ״ע ואח״כ נתערבו כשרים אם עד שלא בלל פסל ויין אם הוקטר שמנן ויינן מערבין יינן לכתחלה ואם לא הוקטרו אם נתערב סלתן ושמנן מערבין נמי יינן לכתחלה ואם לאו אין מערבין. ומדכתב רש״י והא דקתני מציעתא דמתני' אבל אין מערבין היינו בשלא נתערבו סלתן ושמנן משמע בהדיא דהא דתנן מערבין נסכי פרים בנסכי אילים נסכי כבשים בנסכי כבשים נמי ביין היא שנוייה וכן פירשה רבינו גם בפירוש המשנה אלא שרש״י מפרש דמיירי בשלא נתערבו ורבינו מפרש לה בשנתערבו. ועל פירש״י קשה לי דאי כשלא נתערבו מיירי מאי איריא נסכי כבשים בנסכי פרים ואילים אפילו נסכי כבשים בנסכי כבשים נמי אין מערבין יינן משום גזירה. לכן נ״ל למחוק ברש״י תיבת בשלא ולגרוס והא דקתני מציעתא דמתני' אבל אין מערבין היינו אפילו נתערבו סלתן ושמנן ומה שפירש״י במתניתין בנסכי סלת ושמן הוא למאי דקס״ד ולפ״ז הא דקתני אם בללן אלו בפני עצמן ואלו בפני עצמן וכו' מילתא באפי נפשה היא דהא לא קאי איין דאיירי ביה ברישא אלא אסלת ושמן ומשמע דאכולהו קאי אפילו לנסכי פרים בנסכי אילים נסכי כבשים בנסכי כבשים דכיון דטעמא משום דכתיב והקטירו בהני נמי איכא משום והקטירו. וא״ת א״כ דמערבין ואין מערבין דקתני רישא ביין מיירי מ״ש הני מהני וי״ל דכיון דנסכי כבשים אינם שוים לנסכי פרים ואילים מחמירין בהו טפי שאפילו נתערבו סלתן ושמנן אין מערבין יינן כל זמן שלא הוקטרו סלתן ושמנן. וע״פ הדברים האלה נתבארו דברי רבינו עד סוף הפרק, אלא שאצל מ״ש וכשמערב נסכי פרים ביין נסכי אילים נראה שצריך להגיה ולכתוב וכשמערב מערב יין נסכי פרים ביין נסכי אילים יין נסכי כבשים ביין נסכי כבשים:\",1,0],[8,364,10,15,\"סליקו להו הלכות תמידין ומוספין בס\\\"ד..\",2,0],[8,365,1,1,\"כל הפסולים לעבודה וכו' עד הזבח כשר. משנה וגמרא בפרק כל הפסולין (זבחים דף ל״א ל״ב:):\",1,0],[8,365,1,2,\"ומ\\\"ש וכן פר כהן גדול של יום הכפורים וכו' אף פרה אדומה ששחטה זר כשירה. בפרק טרף בקלפי (יומא דף מ\\\"ב) אתמר שחיטת פרה (אדומה) ופרו וכו' חד אמר פרה פסולה ופרו כשירה וחד אמר פרו פסולה ופרה כשירה ובתר הכי (דף מ\\\"ג:) אמרינן תני תנא קמיה דר\\\"י כל השחיטות כשירות בזר חוץ משל פרה א\\\"ל ר\\\"י פוק תני לברא לא מצינו שחיטה בזר פסולה ור\\\"י ל\\\"מ לתנא דלא ציית אלא אפי' לרביה לא ציית דאמר ר\\\"י משום ר\\\"ש בן יהוצדק שחיטת פרה בזר פסולה ואני אומר כשירה לא מצינו שחיטה שפסולה בזר. ופסק רבינו כר\\\"י משום דלגבי פרו הלכה כרב באיסורי ועוד דה\\\"ל רב ור\\\"י תרי לגבי שמואל ולגבי פרה ה\\\"ל שמואל ור\\\"י תרי לגבי רב ואע\\\"ג דר\\\"ש בן יהוצדק רביה פסל בפרה כיון דראה ר\\\"י דבריו ודחאן נקטינן כוותיה:\",1,0],[8,365,1,3,\"השוחט את הקדשים ולא נתכוין לשחיטה וכו'. בס\\\"פ ב\\\"ש (זבחים דף מ\\\"ז) ובפ\\\"ק דחולין (דף י\\\"ג) בעיא דאיפשיטא:\",1,0],[8,365,1,4,\"ולא ישחוט ב' ראשים כאחד בקדשים וכו'. ברפ\\\"ב דחולין (דף כ\\\"ט) תני רב יוסף תזבח שלא יהו שנים שוחטין זבח אחד תזבחוהו שלא יהא אחד שוחט ב' זבחים ואמרינן בתר הכי אמר רבב\\\"ח אר\\\"י זו דברי ר\\\"א בר\\\"ש [סתימתאה] אבל חכ\\\"א שנים שוחטין זבח אחד וסתם מתני' שם (דף ל':) השוחט שני ראשים כאחד שחיטתו כשירה ואוקמוה בקדשים ומש\\\"ה דיעבד אין לכתחלה לא:\",1,0],[8,365,1,5,\"ומ\\\"ש אבל שנים שוחטים בהמה אחת וכו'. משנה שם ומשמע דבקדשים מיירי דומיא דרישא:\",1,0],[8,365,1,6,\"הקטן אינו שוחט קדשים אע\\\"פ שהגדול עומד וכו'. הכי משמע בהדיא בפ\\\"ק דחולין (י\\\"ב:).\",1,0],[8,365,1,6,\"ומ\\\"ש אפי' היתה מחשבתו ניכרת מתוך מעשיו אינה מחשבה להקל אלא להחמיר כיצד היתה עולה עומדת בדרום וכו'. שם (דף י\\\"ג) בעיא דאיפשיטא מחשבתו ניכרת מתוך מעשיו מדאורייתא אין לו מדרבנן יש לו. ופירש\\\"י מדרבנן יש לו ולחומרא במעלה פירותיו לגג מפני הכנימה והיפך בהם ה\\\"ז בכי יותן מדאוריי' אין לו וגבי היה עולה בדרום ומשכה לצפון ושחטה לא סמכינן עלה.\",2,0],[8,365,1,6,\"ומ\\\"ש אלא להחמיר. כגון ששחט ע\\\"מ לזרוק דמו אחר שתשקע החמה הויא מחשבתו מחשבה והזבח פגול:\",3,0],[8,365,1,7,\"קדשי קדשים שנשחטו בדרום או שנתקבל דמן בדרום פסולים. נלמד ממה שיבא בסמוך:\",1,0],[8,365,1,8,\"היה עומד בדרום והושיט ידו לצפון ושחט שחיטתו כשירה. ברייתא בפרק ב' דזבחים (דף כ\\\"ו):\",1,0],[8,365,1,9,\"ומ\\\"ש היה עומד בדרום והושיט ידו וקיבל הדם בצפון קבלתו פסולה. שם. ופירש\\\"י שחיטתו כשירה לקמן ילפינן לה אותו בצפון ואין השוחט בצפון אבל המקבל בצפון:\",1,0],[8,365,1,10,\"ומ\\\"ש הכניס ראשו ורובו בצפון הרי הוא כעומד בצפון. ג\\\"ז שם:\",1,0],[8,365,1,11,\"שחטה בצפון ופרכסה כו'. שם פרכסה ויצתה לדרום וחזרה כשירה ופירש\\\"י (משום) דאין פיסול יוצא אלא מתוך המחיצות והאי וחזרה לאו דוקא. ורבינו מפרש דהאי וחזרה איצטריך לאשמועינן שאם אחר שחזרה קיבל דמה בצפון כשירה ואם קיבל דמה עד שלא חזרה פשיטא דפסולה.\",1,0],[8,365,1,11,\"ומ״ש אפי' הוציאה לדרום כשירה. בר״פ דם חטאת (זבחים דף צ״ב:):\",2,0],[8,365,1,12,\"וכן קדשים קלים שהיו בפנים כו' הכניס ידו וקיבל קבלתו פסולה וכו'. שם (דף כ\\\"ז) בברייתא ופירש\\\"י הכניס ראשו ורובו כאילו לא נכנס כדילפינן לקמן בשמעתין בבואם אל אהל מועד עד שיבא כולו וגבי עזרה דכתיב לעמוד לפני ה' בעיא כולו דכיון דגלי בחדא גלי בכולהו והכי אמרינן בשמעתין.\",1,0],[8,365,1,12,\"ומ\\\"ש אפי' היה העובד כולו בפנים וציצתו בחוץ עבודתו פסולה וכו'. שם בעיא דאיפשיטא ופירש\\\"י ציצתו ציצת ראשו דהיינו שערו:\",2,0],[8,365,1,13,\"פרכסה הבהמה ויצאה לחוץ וכו'. זה מבואר בטעמו.\",1,0],[8,365,1,13,\"ומ\\\"ש כמו שיתבאר. הוא בס\\\"פ זה ושם מבואר שאין הזריקה מועלת ליוצא אלא לשרפו אבל לא לאכלו ומשמע דהוא הדין הכא:\",2,0],[8,365,1,14,\"היתה הבהמה כולה בפנים וכו'. שם בעא מיניה אבוה דשמואל משמואל היא בפנים ורגלה בחוץ מהו א\\\"ל כתיב והביאום לה' עד שתהא כולה בפנים:\",1,0],[8,365,1,15,\"ומ\\\"ש שחטה והיא כולה בפנים ואח\\\"כ הוציאה רגלה לחוץ וכו'. ג\\\"ז שם (דף כ\\\"ח:) א\\\"ר אמי א\\\"ר אלעזר היא בפנים ורגליה בחוץ חתך ואח\\\"כ שחט כשירה שחט ואחר כך חתך פסולה חתך ואח\\\"כ שחט כשירה בעל מום קא מקריב אלא אימא קיבל ואח\\\"כ חתך פסולה חתך ואח\\\"כ קיבל כשירה והא א\\\"ר זירא הצורם אוזן בבכור ואח\\\"כ קיבל דמו פסול וכו' א\\\"ר חסדא אמר אבימי חותך באבר עד שמגיע לעצם. קיבל ואח\\\"כ חתך פסולה שמעת מיניה דם המובלע באיברים דם הוא דילמא משום שמנונית ש\\\"מ בשר קדשים קלים שיצא לפני זריקה פסול דילמא בקדשי קדשים. ופירש\\\"י חותך באבר עד שהוא מגיע לעצם דלאו מום הוא והדם מעוכב ע\\\"י חתיכה מלעלות וליכנס לפנים. ש\\\"מ דם המובלע באיברים דם ובשר נמי לא הוי דאלת\\\"ה אהיכא חייל פיסול יוצא אמיא בעלמא. דילמא משום שמנונית דחזיא לאכילה וחשיבא לאיפסולי ביוצא וכו' ומובלע בדם הרגל ונפקא דרך בית השחיטה ופסלה ליה לדם שבמזרק:\",1,0],[8,365,1,15,\"כתב הראב״ד שחטה והיא כולה וכו' עד מפני שמנונית וכו'. א״א לא ידעתי זה מהו שהיוצא בקדשי קדשים וכו' עד לבעלים לכפרה קאמר וכן עיקר. דבריו מבוררים שהוא משיג על רבינו שנראה מדבריו שהוא מכשיר בחותך הבשר עד שהוא מגיע לעצם ואח״כ מקבל הדם דהא לענין טומאה איבעיא לן בפ' כיצד צולין (פסחים דף פ״ה) אי גזרו רבנן טומאה ביוצא או לא ולא איפשיטא ונקטינן לחומרא דגזרו טומאה ביוצא ואע״ג דמידי דרבנן הוא משום חומרא דקדשים נקטינן ביה לחומרא ומאחר דיוצא טמא אף מה שבפנים טמא דהא רבינא דבתרא הוא סבר בפ' בהמה המקשה דחיבורי אוכלים כמאן דמפרתי דמו ונגעי בהדדי וא״כ טימא היוצא למה שבפנים ופסול ושמעתא בפ' שני דזבחים (דף כ״ה כ״ו) דמכשר דלא כרבינא ולא הו״ל לרבינו לפסוק כוותיה אלא כרבינא דבתרא הוא ומשום דקשה לומר דשמעתא דזבחים ליפלוג ארבינא הדר ואמר דאפשר דאף שמעתא דזבחים סברה כרבינא דנפסל הבשר לאכילה ולא אתיא אלא לאכשורי זיבחא לבעלים לכפרה אבל הבשר אה״נ דאסור וה״ל לרבינו לפרושי. וליישב דעת רבינו י״ל דאי נימא דשמעתא דזבחים פליגא ארבינא למינקט כסתם גמרא עדיף מלמינקט כרבינא ואפי' למ״ש דהך שמעתא לאו לאכשורי בישרא לאכילה קאמר וכו' אין השגה על רבינו שהרי דרכו להעתיק לשון הגמרא כמות שהיא. ועי״ל דסבר רבינו דבעיא דפ' כיצד צולין דלא איפשיטא נקטינן לקולא כיון דבדרבנן היא והשתא שמעתא דזבחים לא פליגא ארבינא ולאכשורי בישרא לאכילה אתא:\",2,0],[8,365,1,15,\"כתב עוד ואח\\\"כ חתך פסול וכו' א\\\"א אפילו אחר זריקה וכו'. כלומר משיג על מ\\\"ש רבינו שבשר קדשים קלים שיצא קודם זריקה כשר דמאי איריא קודם זריקה אפילו אחר זריקה נמי ואפשר לומר דמאי יצא דקאמר רבינו יצא חוץ לחומת ירושלים. ועי\\\"ל דאפי' את\\\"ל דביוצא חוץ לעזרה מיירי ה\\\"ק אע\\\"ג דדם האיברים לאו דם הוא לענין שנאמר שאם הזה ממנו כשר מ\\\"מ כיון דאית ביה שמנונית לא חשבינן ליה כמיא בעלמא למימר דלא ליחול עליה פיסול יוצא כלומר שע\\\"י השמנונית חשיב דם לחול עליו פיסול יוצא:\",3,0],[8,365,1,16,\"תלה הבהמה ושחטה באויר העזרה פסולה וכו'. שם:\",1,0],[8,365,1,17,\"ומ\\\"ש היתה הבהמה בארץ ונתלה וכו'. (זבחים כ\\\"ו) נתלה ושחט מהו א\\\"ל פסולה א\\\"ל אישתבשת שחיטה על ירך ולא שוחט על ירך נתלה וקיבל מהו א\\\"ל כשירה א\\\"ל אישתבשת אין דרך שירות בכך תלה וקיבל מהו א\\\"ל פסולה א\\\"ל אישתבשת שחיטה על ירך ולא קבלה על ירך אמר אביי בקדשי קדשים כולם פסולים בר מנתלה ושחט בקדשים קלים כולם כשירים בר מנתלה וקיבל אמר רבא מ\\\"ש תלה וקיבל בקדשים קלים דכשרה דאויר פנים כפנים דמי בקדשי קדשים נמי אויר צפון כצפון דמי אלא אמר רבא בין בקדשי קדשים בין בקדשים קלים כשירים בר מתלה ושחט בקדשי קדשים נתלה וקיבל בין בקדשי קדשים בין בקדשים קלים. ופירש\\\"י בר מתלה ושחט בקדשי קדשים דבעינן על ירך אבל בקדשים קלים דלא כתיב על ירך כשירה. תלה וקיבל כשר בכולן דדרך שירות בכך ואויר צפון כצפון דמי ובקבלה לא כתיב על ירך. ונתלה וקיבל בקדשים קלים נמי פסול דקבלה שירות היא ואין דרך שירות בכך אבל נתלה ושחט כשרה דשחיטה לאו שירות הוא ועל ירך נמי לאו בשוחט כתיב אלא בבהמה עכ\\\"ל. ומזה יתבאר לך שיש טעות סופר בדברי רבינו וכן צריך להגיה, היתה הבהמה בארץ ונתלה ושחט והוא תלוי באויר כשירה תלה את הבהמה ושחטה באויר העזרה בקדשי קדשים פסול בקדשים קלים כשר:\",1,0],[8,365,1,18,\"שחט מיעוט סימנים בחוץ וגמרן בפנים. בפרק ב' דחולין (דף כ\\\"ט:) אמר ר\\\"ל וכו' אינה לשחיטה אלא בסוף ורבי יוחנן אמר ישנה לשחיטה מתחלה ועד סוף ואסיקנא לא נחלקו אלא כגון ששחט מיעוט סימנים בחוץ וגמרן בפנים למ\\\"ד ישנה לשחיטה מתחלה ועד סוף מיחייב למאן דאמר אינה אלא לבסוף לא מיחייב וידוע דהלכה כרבי יוחנן.\",1,0],[8,365,1,18,\"ומה שכתב או ששחטן בדרום וגמרן בצפון פסולים. נלמד ממה שנתבאר בסמוך:\",2,0],[8,365,1,19,\"נתלה וקיבל הדם וכו' היה עומד בעזרה ותלה המזרק בידו וקיבל הדם באויר וכו'. נתבאר בסמוך:\",1,0],[8,365,1,21,\"נתן מזרק לתוך מזרק וקיבל כשר. בפ' הוציאו לו (יומא דף נ״ח) בעא מיניה רמי בר חמא מרב חסדא הניח מזרק בתוך מזרק וקיבל בו את הדם מהו מין במינו חוצץ או אינו חוצץ ובעא למיפשטה ודחי ליה ואעפ״כ כיון דאשכחן לרבא דאמר בפרק לולב הגזול (סוכה דף ל״א) דמין במינו אינו חוצץ פסק רבינו כן. ועוד דאמרינן בפ' הוציאו לו איכא דאמרי הכי בעא מיניה דרך שירות בכך או אין דרך שירות בכך ת״ש דתנא דבי ר' ישמעאל ואת כלי השרת אשר ישרתו בם בקדש שני כלים ושירות אחת:\",1,0],[8,365,1,21,\"הניח סיב בתוך המזרק וקיבל וכו'. שם בעיא ובעא למיפשטה ודחי לה ובתר הכי אמרינן איכא דאמרי הכי פשט ליה בדם כשר בקומץ פסול ופסק כלישנא בתרא:\",2,0],[8,365,1,22,\"קבלת הדם והולכתו למזבח וזריקתו וכו' אינה כשירה אלא בכהן הכשר לעבודה. בספ\\\"ק דזבחים (דף י\\\"ג וי\\\"ד).\",1,0],[8,365,1,22,\"ומ\\\"ש וכן הולכת איברים לכבש. בפ\\\"ג דזבחים (דף ל\\\"ה).\",2,0],[8,365,1,22,\"ומ\\\"ש כמו שביארנו בקמיצת המנחה. פי\\\"ג ממעשה הקרבנות. ובמליקת העוף בפ\\\"ו מהלכות הנזכרות:\",3,0],[8,365,1,23,\"והולכה שלא ברגל אינה הולכה וכו'. מימרא דר\\\"י בספ\\\"ק דזבחים (דף י\\\"ד וט\\\"ו):\",1,0],[8,365,1,25,\"קיבל בימינו ונתן לשמאלו וכו' עד ואספו ונתנו לכלי השרת נפסל הזבח. משנה רפ\\\"ב (דף ט\\\"ו:) ורפ\\\"ג דזבחים (דף ל\\\"ב):\",1,0],[8,365,1,26,\"נשפך מקצת הדם מצואר בהמה על הארץ וכו'. בפ\\\"ב דזבחים (דף כ\\\"ה) אהא דתנן נשפך על הרצפה ואספו פסול ת\\\"ר ולקח הכהן המשיח מדם הפר מדם הנפש ולא מדם העור ולא מדם התמצית, ומשמע לרבינו דכל שאינו מדם העור ולא מדם התמצית אף על פי שנשפך מקצתו בארץ כשר ואף על גב דאמרינן התם השוחט צריך שיקבל את כל דמו של פר יש לומר דהיינו לכתחלה דוקא אי נמי ההיא בשלא נשפך דם מצואר לארץ אבל אם נשפך מקצת דם מצואר לארץ הדם הנשאר היינו כל הפר והיינו דתנן נשפך על הרצפה ואספו פסול הא אם לא אספו לא נפסל הזבח דמקבל דם הנשאר בצואר כשר:\",1,0],[8,365,1,27,\"כל הזבחים שקיבל דמן אחד מהפסולים לעבודה נפסל הזבח. משנה ריש פרק ב' דזבחים (דף ט\\\"ו:).\",1,0],[8,365,1,27,\"ומה שכתב או שהוליך את הדם למזבח או שזרקו למזבח כהלכתו נפסל הזבח. בסוף פרק קמא דזבחים (דף י\\\"ד) תניא זר אונן שכור בעל מום בקבלה בהולכה בזריקה פסל וכן יושב וכן שמאל.\",2,0],[8,365,1,27,\"ומה שכתב רבינו כהלכתו נראה דה\\\"ק אפילו אם זרקו כהלכתו נפסל הזבח, ויותר נראה לומר דדוקא זרקו כהלכתו פסל אבל זרקו שלא כהלכתו לא פסל דלא חשיבא זריקה:\",3,0],[8,365,1,27,\"קיבל הכשר ונתן לפסול וכו' עד שהרי אי אפשר לתקן דבר זה. בסוף פירקא קמא דזבחים אמר עולא אמר רבי יוחנן הולכה שלא ברגל לא שמה הולכה אפשר לתקונה או לא אפשר לתקונה וכו' אתמר אמר עולא אמר ר' יוחנן הולכה שלא ברגל פסולה אלמא לא אפשר לתקונה ובתר הכי אמרינן הוליכו זר והחזירו כהן וחזר והוליכו פליגי בה בני רבי חייא ורבי ינאי ח\\\"א כשר וח\\\"א פסול מר סבר אפשר לתקונה ומ\\\"ס לא אפשר לתקונה הוליכו כהן והחזירו וחזר והוליכו זר א\\\"ר שימי בר אשי לדברי המכשיר פסול לדברי הפוסל מכשיר רבא אמר אף לדברי הפוסל פסול מ\\\"ט דהא צריך לאמטוייה. ופסק כמ\\\"ד לא אפשר לתקונה משום דרבי יוחנן קאי כוותיה ופסק נמי כרבא:\",4,0],[8,365,1,28,\"קיבל הפסול וכו'. משנה ברפ\\\"ג דזבחים (דף ל\\\"ב).\",1,0],[8,365,1,28,\"ומ\\\"ש שאין הפסולים לעבודה עושים הדם הנשאר שירים חוץ מן הטמא וכו'. בפ\\\"ק דמעילה (דף ה'):\",2,0],[8,365,1,28,\"כתב הראב\\\"ד עושה שירים כיצד וכו' א\\\"א סבור אני שטעה בזה וכו'. ואני אומר שגם רבינו סובר כן וכשכתב כאן כיצד קיבל הטמא קיבל וזרק קאמר וסמך על מ\\\"ש בפ\\\"ג מה' מעילה קיבלו הפסולים את הדם וזרקוהו וחזרו הכשרים לעבודה וקיבלו שאר דם הנפש וזרקוהו אין מועלין בבשרן שאין הפסולים עושים שאר דם הנפש שירים חוץ מן הטמא כיצד קיבל הטמא וזרק אע\\\"פ שחזר הכשר וקיבל שאר דם הנפש וזרקו הרי אלו לא היתה להם שעת היתר וכו':\",3,0],[8,365,1,29,\"בהמה שחסר מאיבריה כל שהוא וכו'. מימרא דרבי זירא בפרק שני דזבחים (דף כ״ו) ובפרק על אלו מומין (בכורות דף ל״ט):\",1,0],[8,365,1,30,\"ומ\\\"ש אבל אם חסרה אחר קבלה קודם זריקה אפי' אבד הבשר קודם זריקת הדם או נשרף אם נשתייר כזית מן הבשר או כזית מן האימורים זורק את הדם ואם לאו אינו זורק. גם זה שם.\",1,0],[8,365,1,30,\"ומ\\\"ש ובעולה אפי' כחצי זית מן הבשר וחצי זית מן האימורים וכו'. בהקומץ רבה (דף כ\\\"ו) ובתוספתא דזבחים פ\\\"ד והטעם פשוט משום דכולה להקטרה:\",2,0],[8,365,1,31,\"ומ\\\"ש נשאר פחות מכזית וכו' ואם זרק לא הורצה. הכי משמע שם:\",1,0],[8,365,1,31,\"נפסל הבשר קודם זריקה כו'. בפרק כיצד צולין (פסחים דף ע״ט):\",2,0],[8,365,1,32,\"בשר קדשים קלים וכו'. בזבחים פרק כל התדיר (זבחים דף צ') פלוגתא דרבי יוחנן ור״ל ופסק כר' יוחנן וכן היא ג״כ פלוגתא דר' אליעזר ור״ע ופסק כר״ע.\",1,0],[8,365,1,32,\"ומ\\\"ש והזריקה מועלת ליוצא לשרפו אבל לא לאכלו. בספ\\\"ק דמעילה (דף ז':) כי אמר ר' עקיבא זריקה מועלת ליוצא לשריפה אבל לאכילה הוא דלא מרצה. ופירש\\\"י דלהכי מהניא ליה זריקה שאינו נשרף לאלתר כפסולים אלא עד שתעובר צורתו:\",2,0],[8,365,1,32,\"כתב הראב\\\"ד א\\\"א לא ידעתי מהו זה וכו'. כלומר דהשתא מהדר רבינו למ\\\"ש לעיל או שיצא חוץ לעזרה לא יזרוק הדם ואם זרק הורצה וקאמר דלא הורצה אלא להעלותו על גבי המזבח אבל לא לאכלו וה\\\"ה לבשר קדשים קלים שיצא חוץ לחומת ירושלים שאם זרק הדם הורצה לשרפו אבל לא לאכלו, וכתב שדבריו מבולבלים שהכניס דין בשר קדשים קלים שיצא חוץ לעזרה בין הדבקים וכך ה\\\"ל לכתוב ואם זרק הורצה וה\\\"ה לבשר קדשים קלים שיצא חוץ לחומת ירושלים ואח\\\"כ ה\\\"ל לכתוב דין בשר קדשי קדשים שיצא חוץ לחומת העזרה. ואני אומר שטעמו של רבינו שבתחלה כתב דין בשר קדשי קדשים שיצא חוץ לעזרה (ואח\\\"כ כתב דין בשר קדשים קלים שיצא חוץ לעזרה) ואח\\\"כ כתב דין בשר שיצא חוץ למחיצתו קודם זריקה דהיינו בשר קדשי קדשים חוץ לעזרה ובשר קדשים קלים חוץ לחומת ירושלים שהזריקה מועלת בהם לשורפו אבל לא לאכלו:\",3,0],[8,365,1,33,\"וכן אימורי קדשים קלים כו'. בפרק כל התדיר (זבחים דף צ') מייתי הא דתנן בפרק קמא דמעילה אימורי קדשים קלים שיצאו לפני זריקת דמים ר״א אומר אין מועלין בהם ואין חייבין עליהם משום פגול נותר וטמא ר״ע אומר מועלין בהם וחייבים עליהם משום פגול נותר וטמא ואסיק רב פפא בדהדר עיילינהו כולי עלמא לא פליגי והכא בדאיתנהו אבראי פליגי. ואע״ג דלכאורה משמע דרב פפא בדרך דחייה אמרה מכל מקום מדאקשינן והא רב פפא הוא דאמר בדאיתנהו אבראי כולי עלמא לא פליגי וכו' ושני ה״מ גבי שתי הלחם וכו' משמע דבקושטא דמילתא אמרה:\",1,0],[8,365,1,33,\"וכתב הראב\\\"ד ואם החזירן מקטירין אותם א\\\"א [זה] אינו מחוור עכ\\\"ל. טעמו דס\\\"ל דאע\\\"ג דמועלים בהם וחייבין עליהם משום פגול וכו' כיון שיצאו לחוץ נפסלו מלהקטירן. ורבינו סובר שמאחר שמועלין בהם וחייבין עליהם משום פגול וכו' לא נפסל הזבח:\",2,0],[8,365,1,34,\"כל הזבחים של יחיד וכו'. בפרק כיצד צולין (פסחים דף ע״ז) אהא דתנן חמשה דברים באים בטומאה ואינם נאכלים בטומאה העומר ושתי הלחם וכו' אמרינן נימא מתני' דלא כר' יהושע דתניא (ועשית עולותיך הבשר והדם) רבי יהושע אומר אם אין דם אין בשר אם אין בשר אין דם. ופירש״י אם אין בשר ראוי כגון שנטמא או שאבד אין הדם נזרק וכיון דאמר רבי יהושע בעינן תרתי וציץ אאכילות לא מרצה היכי אתי בטומאה ואסיקנא (דף ע״ח) מתניתין כר״י ול״ק כאן ביחיד כאן בצבור. ופירש״י ביחיד לכתחלה פסולה ואם זרק הורצה ומתני' בצבור באין לכתחלה דטומאת צבור דחויה היא.\",1,0],[8,365,1,34,\"ומה שכתב וכן אימורים או איברי עולה שנטמאו והקטירן הציץ מרצה כמו שביארנו. בפרק רביעי מהלכות ביאת המקדש:\",2,0],[8,365,1,34,\"ומה שכתב וכל קרבנות הצבור שנטמא הבשר והחלב כולו הרי זה זורק את הדם. נתבאר בסמוך דטומאה דחויה היא בצבור:\",3,0],[8,365,1,35,\"דם קדשים שיצא חוץ לעזרה וכו'. בס\\\"פ התערובות (דף פ\\\"ב) תנן גבי דמים פסולים שאין הציץ מרצה על היוצא:\",1,0],[8,365,1,36,\"וכל דם הקדשים אינו מקבל טומאה כלל וכו'. בסוף פרק ב״ש (זבחים דף מ״ו:).\",1,0],[8,365,1,36,\"ומ״ש על הארץ תשפכנו כמים וכו'. בסוף פירקא קמא דפסחים (דף ט״ז:) מנין לדם קדשים שאינו מכשיר שנאמר על הארץ תשפכנו כמים וכו' ומתיב התם מדתניא דם שנטמא וזרקו במזיד לא הורצה ומשני התם מדרבנן. וק״ל מדתנן בפרק כיצד צולין (פסחים דף פ':) הנזיר ועושה פסח הציץ מרצה על טומאת הדם ומשמע דמדאורייתא טמא הדם מדקתני הציץ מרצה וצ״ע:\",2,0],[8,365,1,37,\"ודם ששקעה עליו חמה וכו'. מימרא בס״פ איזהו מקומן (זבחים דף נ״ו):\",1,0],[8,365,2,1,\"כל הדמים הניתנים על מזבח החיצון וכו'. ברפ\\\"ד דזבחים (דף ל\\\"ו:) וכב\\\"ה:\",1,0],[8,365,2,2,\"ומ\\\"ש וכל הניתנים בזריקה שנתנם בשפיכה יצא וכו'. שם ת\\\"ר מנין לניתנים על מזבח החיצון שנתנן במתנה אחת שכיפר ת\\\"ל ודם זבחיך ישפך. ופירש\\\"י ישפך שפיכה אחת משמע דלא כתיב סביב. והאי להכי הוא דאתא האי מבעי ליה לכדתניא וכו' מנין לניתנין בזריקה שנתנן בשפיכה יצא ת\\\"ל ודם זבחיך ישפך סבר לה כר\\\"ע דאמר לא זריקה בכלל שפיכה ולא שפיכה בכלל זריקה. ופירש\\\"י מנין לניתנין בזריקה כל הדמים שכתוב בהם זריקה וכו' וכל זריקה מרחוק משמע שזורק מן הכלי למזבח למרחוק שפיכה עומד אצל היסוד ושופך. ודם זבחיך ישפך כל זבחים במשמע. ובתר הכי אמרינן (דף ל\\\"ז:) וכל הנך תנאי דמפקי להאי ודם זבחיך ישפך לדרשא אחרינא האי כל הניתנים על מזבח החיצון שנתן מתנה אחת כיפר מנא להו סברי כב\\\"ה דאמרי אף חטאת שנתנה מתנה אחת כיפר וילפינן כולהו מחטאת. ויש לתמוה על רבינו דמייתי לה מודם זבחיך ישפך דכיון דפסק כב\\\"ה דאמרי אף חטאת שנתנה מתנה אחת כיפר מחטאת ילפינן לה ולא מודם זבחיך ותו כיון דאמרינן דמאן דיליף שאם נתנן מתנה אחת כיפר מודם זבחיך ישפך סבר לה כר\\\"ע דאמר דניתנין בזריקה שנתנן בשפיכה לא יצא היאך רבינו מזכי שטרא לבי תרי. מיהו בהא איכא למימר דאע\\\"ג דמאן דיליף וכו' סבר לה כר\\\"ע אפשר דר\\\"ע לא סבר לה כוותיה אבל אכתי קשה דכיון דההיא דמנין לניתנין בזריקה שנתנן בשפיכה יצא אתיא דלא כר\\\"ע לא ה\\\"ל להביאה. והר\\\"י קורקוס ז\\\"ל כתב שפסק כאותה ברייתא ואם נתן בשפיכה יצא משום דמשמע דהלכתא היא דבפסחים (דף פ\\\"ט.) פריך מינה ומסיק דאמרינן בדיעבד אבל לכתחלה לא עכ\\\"ל. ולענין קושיא קמייתא איכא למימר שדרך רבינו לסמוך הדבר לפסוק שנראה לו שהוא פשוט ללמוד ממנו הדין יותר מהפסוק שמביא ממנו הגמרא ודרך הגמרא לעשות כן בכמה מקומות:\",1,0],[8,365,2,3,\"כל הדמים הניתנים על מזבח הפנימי וכו'. שם במשנה:\",1,0],[8,365,2,4,\"חטאת שנתן ממנה מתנה אחת ומתו הבעלים וכו' עד חייב משום מעלה בחוץ. מימרא דרבי יוחנן שם (דף ל\\\"ח:) ופירש רש\\\"י אינם באות בלילה ואף על פי שאינן מעכבות ולאו זריקה גמורה היא מיהו דם נפסל בשקיעת החמה ואין מעלין לגבי מזבח לכתחלה באות לאחר מיתה אם נתן מתנה ראשונה ומתו בעליה כבר כיפר בראשונה ואין שם חטאת גמורה על הדם עוד ליפסל משום חטאת שמתו בעליה וכו' הזורק אותה בחוץ חייב שהרי ראויות לפנים בתורת זריקה גמורה:\",1,0],[8,365,2,7,\"היה מזה ונקטעה ידו של מזה וכו'. בסוף פ\\\"ק דזבחים (דף ט\\\"ו:) בעיא דאיפשיטא:\",1,0],[8,365,2,8,\"שינה מתן קרבנות בחטאת וכו':\",1,0],[8,365,2,9,\"נתן הדם מן הקרן ולפנים וכו':\",1,0],[8,365,2,10,\"דם שמצותו ליתן אותו למעלה וכו' עד הרי בשר הזבח פסול. משנה בפרק שני דזבחים (דף כ\\\"ו).\",1,0],[8,365,2,10,\"ומ\\\"ש ואע\\\"פ כן נתכפרו הבעלים בו. מימרא דשמואל שם ואף על גב דר\\\"י פליג עליה הא אסיקנא בקשיא ואמוראי טובא התם ס\\\"ל כשמואל מדשקלי וטרו אליביה.\",2,0],[8,365,2,10,\"ומה שכתב במה דברים אמורים כשהיה זה הזורק כשר לעבודה וכו' עד ויזרוק הדם במקומו. ג\\\"ז שם:\",3,0],[8,365,2,11,\"דמי קדשים שנתערבו וכו' עד יתן הכל מתן ד'. משנה בפ' התערובות (דף פ').\",1,0],[8,365,2,11,\"ומה שכתב בין דם בדם בין כוסות בכוסות הכי משמע התם בגמרא.\",2,0],[8,365,2,11,\"ומ\\\"ש נתערבו הניתנין מתנה אחת בניתנין מתן שתים שהן כארבע וכו' נלמד ממה ששנו שם במשנה ופלוגתא דר\\\"א ורבי יהושע ופסק כרבי יהושע:\",3,0],[8,365,2,11,\"נתערבו הניתנים למעלה בניתנין למטה ישפך הכל לאמה. שם במשנה פלוגתא דר\\\"א ורבנן ופסק כרבנן.\",4,0],[8,365,2,11,\"ומ\\\"ש אפי' נתערבו שירי החטאת עם דם העולה וכו'. שם פלוגתא דאמוראי ופסק כרבי יהודה:\",5,0],[8,365,2,12,\"ומ\\\"ש ואם לא שאל אלא נתן מן התערובת למעלה ולמטה ה\\\"ז כשר. שם במשנה.\",1,0],[8,365,2,12,\"ומ\\\"ש נתן למעלה ושאל יתן למטה ואלו ואלו עלו לו. ברייתא שם:\",2,0],[8,365,2,13,\"נתערבו הניתנין בפנים בניתנין בחוץ וכו' בד\\\"א בשאר דמים הניתנין בחוץ חוץ מן החטאת וכו' עד פסולה. שם במשנה (דף פ\\\"א:) ופסק כחכמים דפליגי אר\\\"ע ואר\\\"א.\",1,0],[8,365,2,13,\"ומ\\\"ש שדם חטאת שנכנס להיכל אפי' חטאת יחיד הנאכלת אסור וכו'. שם (דף פ\\\"ב) בברייתא דברי ר\\\"י הגלילי. ומדברי רבינו נראה שהוא גורס אין לי אלא חטאת צבור של יחיד מנין ת\\\"ל כל.\",2,0],[8,365,2,13,\"ומ\\\"ש והוא שיבא דרך שער ההיכל וכו'. ג\\\"ז שם בסוף הפרק:\",3,0],[8,365,2,14,\"פר העלם ושעיר ע\\\"ז וכו' וכן פר ושעיר של יוה\\\"כ וכו' עד נפסל. שם (דף פ\\\"ב ע\\\"ב) בעי רבא פר העלם דבר של צבור ושעיר ע\\\"ז שהכניס דמן לפנים מהו מי אמרי' אל הקדש פנימה [כל היכא דקרינן אל הקדש] קרינן ליה פנימה כל היכא דלא קרינן אל הקדש לא קרינן פנימה או דילמא שלא מקומן הוא ואת\\\"ל שלא מקומן הוא פר ושעיר של יוה\\\"כ שהזה מדמן על הבדים והוציא להיכל והכניסן מהו מי אמרינן מקומן הוא או דילמא הואיל ונפק נפק ואת\\\"ל הואיל ונפק נפק הזה דמן על הפרוכת והוציאן למזבח והכניסן [מהו] הכא ודאי חד מקום הוא או יציאה קרינן ביה תיקו. ופירש\\\"י פר העלם דבר שמצות כפרתו בהיכל והכניסו לפני לפנים מהו מי אמרי' כל היכא דקרינן ביה פיסול דאל הקדש כגון בחטאות החיצונות קרינן ביה פיסול דפנימה וכו' דהא כי הדדי כתיבי או דילמא שלא במקומו הוא והויא הכנסה ומיפסיל. והוציאן להיכל להזות על הפרוכת כמשפטן. מקומן הוא שהרי הוזקקו לשם תחלתן. או דילמא כיון דנפק בעשיית כל מצותו נפיק ליה לגמרי וה\\\"ל שלא מקומו. והוציאו למזבח להזות ז' (הזאות) על טהרו. ומתן ד' על קרנותיו כדכתיב ויצא אל המזבח אשר לפני ה' וכפר עליו ותנן זה מזבח הזהב בפרק הוציאו לו ואמרי' התם דלהכי כתיב ויצא עד דנפיק מכוליה מזבח שלא יעמוד בין המזבח ולפרוכת בשעת מתנות המזבח אלא בין המזבח לפתח לצד המזבח הכא חד מקום הוא שאין הפסק מזבח בינתים ולא הויא הכנסה שלא במקומה או דילמא רחמנא שוייה שני מקומות דכתיב ביה יציאה עכ\\\"ל. וכדרך פירש\\\"י הוא פירוש הראב\\\"ד שכתב וז\\\"ל א\\\"א אני איני סובר כפירושו כו'. ורבינו דחה פירוש זה משום דלישנא דהואיל ונפק נפק משמע דמטעם שיצא חוץ למקומו הוא דפסלינן ליה ולא משום הכנסה. ולענין תרי בעיי קמאי כיון דאיפשיטו באת\\\"ל פסק כן רבינו והשלישית שעלתה בתיקו פסקה לחומרא. והר\\\"י קורקוס ז\\\"ל כתב שיש לתמוה על רבינו שהיה לו לכתוב בבבא השלישית לא יעשה מספק ואם עשה הורצה ואפשר דלא שייך בזה הורצה כיון דספק יוצא הוא ואין הציץ מרצה על היוצא מ\\\"מ ה\\\"ל לכתוב ספק כמו בסמוך כי לשון שכיון שיצא הדם חוץ למקומו נפסל משמע דמן הודאי קאמר. ואפשר דסבר רבינו דרבא הוא דאסקה בתיקו ומיהו גמרא משמע התם דלא מספקא ליה וכ\\\"נ שם בברייתא דר\\\"י הגלילי גם בפרק טבול יום נראה כן גבי חטאת אהרן שמא בחוץ היתה בקדש היתה וקדש היינו היכל משמע שכל שיצאה מן ההיכל נפסלה עכ\\\"ל:\",1,0],[8,365,2,15,\"חטאת שקיבל דמה בב' כוסות וכו'. משנה שם (דף פ\\\"ב).\",1,0],[8,365,2,15,\"ומ\\\"ש נכנס אחד מהם להיכל וכו' אף החיצון פסול. שם במשנה מחלוקת ופסק כחכמים.\",2,0],[8,365,2,15,\"ומ\\\"ש והזה ממנו. שם במשנה הנזכרת נכנס לכפר אע\\\"פ שלא כיפר פסל דברי ר\\\"א ר\\\"ש אומר עד שיכפר ופסק כר\\\"ש משום דר' יהודה סבר כוותיה כמו שיתבאר בסמוך:\",3,0],[8,365,2,16,\"ומ\\\"ש דם חטאת שהכניסו לכפר בו בפנים ולא כיפר אלא הוציאו וכו' אם הכניסו בשוגג ה\\\"ז כשר וכו'. שם במשנה ר' יהודה אומר אם הכניס שוגג כשר ומשמע לרבינו דר\\\"י אר\\\"ש קאי וה\\\"ק הא דמכשיר ר\\\"ש כשלא כיפר היינו דוקא כשנכנס שוגג אבל אם הכניסו במזיד אע\\\"פ שלא כיפר פסול. אבל קשה דהתם בגמרא (דף פ\\\"ג) אמרינן אר' יהודה דאמר אם הכניס שוגג כשר הא מזיד פסול בשכיפר או בשלא כיפר ופירש\\\"י בשכיפר וכר\\\"ש ס\\\"ל או אפי' בשלא כיפר וכר\\\"א אמר ר' ירמיה ממשמע שנאמר ואת פר החטאת וכו' ורבי יהודה לכפר לא משמע ליה מ\\\"ט לאו משום דמיבעיא ליה לג\\\"ש. ופירש\\\"י מ\\\"ט לאו משום דמפיק להאי לכפר לג\\\"ש דר\\\"ש ללמד על דמים החיצונים שנכנס דמם לפנים שאין פסול אא\\\"כ כיפר כר\\\"ש ועוד דבס\\\"פ כל הפסולין אמרינן (דף ל\\\"ו) והתנן א\\\"ר יהודה הכניס בשוגג כשר הא במזיד פסול וקי\\\"ל בשכיפר הרי בהדיא דמפרש גמרא דר' יהודה לא פסל במזיד אא\\\"כ כיפר. וא\\\"כ היאך פסק רבינו שבמזיד אע\\\"פ שלא כיפר פסל. וכתב הר\\\"י קורקוס ז\\\"ל שטעם רבינו משום דמסיק שם בפ' כל הפסולים על תרי תנאי ואליבא דרבי יהודה פי' דתנא דההיא ברייתא דמוכח מינה לר' יהודה דדוקא בכיפר פליג אההיא מתני' וגם מתני' דפרק התערובות מצינן לפרושה כההיא דכל הפסולים ובדלא כיפר מיירי, ומעתה הדין עם רבינו שלא לסמוך על אותו פשיטות ולהניח משנה דכל הפסולים אלא דחינן ברייתא מקמי מתניתין ומפרשים בלא כיפר עכ\\\"ל, ודבריו אלו צל\\\"ע:\",1,0],[8,365,2,17,\"הכניס החטאת עצמה וכו'. בפ' דם חטאת (זבחים דף צ״ב) ובפ' דם חטאת נתבאר שאפי' הכניסה קודם שקיבל דמה וכשהוציאה קיבל דמה כשירה ולכך כתב רבינו הכניס החטאת עצמה ולא כתב הכניס בשר כלשון הגמ' כך כתב הר״י קורקוס ז״ל:\",1,0],[8,365,2,18,\"חטאת העוף שפרכסה ונכנסה להיכל כשירה. שם (דף צ\\\"ב:):\",1,0],[8,365,2,19,\"הכניס דם חטאת העוף וכו'. גם זה שם בעי ר' אבין חטאת העוף שהכניס דמה בצוארה בפנים מהו צוארה ככלי שרת דמי ומיפסיל או דילמא כצואר בהמה מדמה אמר רחמנא ולא בשרה. ופירש\\\"י שהכניס דמה בצוארה בפנים בין מליקה להזיה מהו שתפסל משום וכל חטאת אשר יובא. ככלי שרת דמי שהרי לא הוזקקה בקבלת כלי וזהו כליה ומיפסיל בהכנסת הדם שהכניסה בכלי להיכל או דילמא וכו' ובהמה שהכניסה לפנים משנשחטה הוציאה וקיבל דמה לא מיפסלה דמדמה אמר רחמנא ולא שהכניסו עם בשרה עכ\\\"ל ולא איפשיטא:\",1,0],[8,365,2,20,\"ומ\\\"ש נשפך דם חטאת העוף ואספו וכו'. שם בעי רבי אבין נשפך על הרצפה ואספו מהו אצרוכי הוא דלא אצרכיה רחמנא כלי שרת והילכך אוספו וכשר או דילמא מיפסל פסל ביה רחמנא כלי שרת והילכך אוספו ופסול. ופירש\\\"י נשפך על הרצפה מצואר העוף. אצרוכי הוא דלא אצרכיה רחמנא כלי שרת וצואר דידיה הוא במקום כלי שרת והלכך לאוספו כשר ולהזותו למזבח דה\\\"ל כנשפך מן הכלי על הרצפה ואספו דכשר. א\\\"ד מיפסל פסל ביה רחמנא כלי שרת דדוקא שייר ולא כתב ביה קבלה משום דבעי להזותו מן העוף עצמו למזבח וכ\\\"ש ברצפה פוסלתו עכ\\\"ל ולא איפשיטא.\",1,0],[8,365,2,20,\"ומ\\\"ש לפיכך תשרף וכו'. קאי גם להכניס דם חטאת העוף להיכל בצוארה ופשוט הוא:\",2,0],[8,365,2,21,\"חטאת שקיבל דמה בארבעה כוסות וכו' עד נשפכים לאמה. בפרק שלישי דזבחים (דף ל״ד ע״ב) ופרק הוציאו לו (יומא דף נ״ז:) ברייתא ואע״ג דפליג ר' אלעזר בר' שמעון פסק כתנא קמא:\",1,0],[8,365,2,22,\"דם שנפל לתוך המים וכו'. בפרק התערובות (דף ע\\\"ז:) שנינו דם שנתערב במים אם יש בו מראה דם כשר ובגמרא אמר רבי חייא בר אבא א\\\"ר יוחנן לא שנו אלא שנפלו מים לתוך דם אבל נפל דם לתוך מים ראשון ראשון בטל.\",1,0],[8,365,2,22,\"ומ\\\"ש או לתוך דמי חולין וכן מ\\\"ש נפל לתוכו יין או דם חולין וכו'. שם במשנה נתערב ביין וכו' בדם בהמה או בדם החיה רואים אותו כאילו הוא מים:\",2,0],[8,365,2,23,\"דם הקדשים שנתערב בדם פסולי המזבח וכו'. משנה שם (דף ע\\\"ט:) דם תמימים בדם בעלי מומין ישפך לאמה כוס בכוסות ר\\\"א אומר אם קרב כוס אחד יקרבו כל הכוסות וחכ\\\"א אפי' קרבו כלם חוץ מאחד מהם ישפך לאמה.\",1,0],[8,365,2,23,\"ומ\\\"ש וכל הזבחים פסולים. פשוט הוא מאחר שלא נזרק הדם לא הותרו ואע\\\"פ שאין בדם הפסול שיעור לבטל הכשר ישפך לאמה דגזרינן דילמא אתי לאכשורי כשיש בדם הפסול או התמצית לבטל הכשר והא דלא גזרינן בנתערב בדם חולין משום דדם חולין לא שכיח בעזרה:\",2,0],[8,365,2,23,\"נתערב בדם התמצית וכו'. משנה שם (דף ע\\\"ח):\",3,0],[8,365,2,25,\"האימורים ואיברי העולות וכו' עד או בידו פסולים. בתוספתא דזבחים ספ״ק ואיתא בגמרא פרק הקומץ רבה (מנחות דף כ״ו):\",1,0],[8,365,2,26,\"איברים שסידרן וכן קומץ שסידרו וכו' עד סוף הפרק. בפ' הקומץ בעיי דסלקו בתיקו ואע\\\"פ שאמרו שם דאליבא דמ\\\"ד על ממש לא תיבעי כבר נתבאר בפרק שרבינו פוסק כמ\\\"ד על היינו בסמוך:\",1,0],[8,365,3,1,\"קדשי קדשים ששחטן בראש המזבח וכו'. משנה בר״פ קדשי קדשים (זבחים דף נ״ח) פלוגתא דתנאי ופסק כר' יוסי דנימוקו עמו ופריך בגמרא השתא כולו לעולה כשר כולו לשלמים מיבעיא ומשני סד״א עולה היא דדחיק ליה מקום אבל שלמים דלא דחיק ליה מקום אימא לא קמ״ל:\",1,0],[8,365,3,2,\"עולה ששחטה בראש המזבח או ששחטה למטה וכו'. משנה בפ' המזבח מקדש (זבחים דף פ״ד) עולה שעלתה חיה לראש המזבח תרד שחטה בראש המזבח יפשיט וינתח במקומה.\",1,0],[8,365,3,2,\"ומ\\\"ש ומוריד את הקרבים ומדיחן. הכי אמרי' שם בברייתא ואע\\\"ג דהתם מיירי בנפסלה ילפינן מינה לכשירה במכל שכן.\",2,0],[8,365,3,2,\"ומה שכתב ומוריד העור ונותנו לכהנים. פשוט הוא.\",3,0],[8,365,3,2,\"ומ\\\"ש דה\\\"ה לשחטה למטה והעלה לראש המזבח. הכי משמע מדתנן בראש הפרק הנזכר (דף פ\\\"ג) כל הראוי לאשים אם עלה לא ירד ועוד דמשמע דאתיא בכ\\\"ש משחטה בראש המזבח:\",4,0],[8,365,3,3,\"ומ\\\"ש וכן זבחים שחוטים שעלו לגבי מזבח וכו' שכל הראוי לאשים אם עלה לראש המזבח לא ירד וכן מ\\\"ש מה עולה שהיא ראויה לאשים וכו'. משנה הזכרתיה בסמוך לר' יהושע ואע\\\"ג דפליג עליה ר\\\"ג לא פסק רבינו כמותו משום דר\\\"ע ור\\\"י הגלילי ור\\\"ש פליגי עליה.\",1,0],[8,365,3,3,\"ומ\\\"ש שנאמר כל הנוגע במזבח יקדש. שם במשנה ובגמרא:\",2,0],[8,365,3,4,\"עולה שהעלה חיה לראש המזבח תרד וכו'. משנה כתבתיה בסמוך:\",1,0],[8,365,3,5,\"ומ\\\"ש וכן קומץ המנחה שלא נתקדש בכלי שרת. בר\\\"פ המזבח מקדש שם.\",1,0],[8,365,3,5,\"ומ\\\"ש וכל איסורי המזבח שעלו ירדו וכו' וכן בהמת הקדשים שנשחטה בלילה וכו'. שם במשנה (דף פ\\\"ד) אלו אם עלו לא ירדו הלן והיוצא והטמא ושנשחט חוץ לזמנו וחוץ למקומו ושקבלו פסולים וזרקו את דמו ר' יהודה אומר ושנשחטה בלילה ושנשפך דמה ושיצא דמה חוץ לקלעים אם עלתה תרד רבי שמעון אומר לא תרד שהיה פיסולו בקדש שרבי שמעון אומר כל שפיסולו בקדש הקדש מקבלו לא היה פיסולו בקדש אין הקדש מקבלו ואלו לא היה פיסולן בקדש הרובע והנרבע והמוקצה והנעבד והאתנן והמחיר והכלאים והטרפה והיוצא דופן ובעלי מומין ובגמרא תניא ר' יהודה אומר זאת והיא העולה מיעוטים פרט לנשחטה בלילה ושנשפך דמה ושיצא דמה חוץ לקלעים שאם עלתה תרד ר\\\"ש אומר עולה אין לי אלא עולה כשירה מנין לרבות שנשחטה בלילה וכו' והניתנין למטה שנתנן למעלה ולמעלה שנתנן למטה והניתנין בחוץ שנתנן בפנים בפנים שנתנן בחוץ וכו' ת\\\"ל תורת העולה ריבה וכו' ור' יהודה מייתי לה מהכא מפני מה אמרו לן בדם כשר שהרי לן כשר באימורין לן באימורין כשר שהרי לן כשר בבשר יוצא שהיוצא כשר בבמה טמא הואיל והותר לעבודת צבור חוץ לזמנו הואיל ומרצה לפיגולו חוץ למקומו הואיל ואיתקש לחוץ לזמנו שקבלו פסולים וזרקו את דמו בהני פסולים דחזו לעבודת צבור וכי דנים דבר שלא בהכשרו מדבר שבהכשרו תנא אזאת תורת העולה ריבה סמיך ליה. ופירש\\\"י לן בדם כשר שאם עלה לא ירד. שהרי לן כשר באימורים שאם עלו לא ירדו. שהרי לן כשר בבשר כגון בשר שלמים הנאכלים לשני ימים. יוצא וכו' וביוצא דאימורי עולה ואימורי קדשים אבל יוצא דדם פסל ר' יהודה ולכך כתב רבינו זבח שיצא ופירש\\\"י חוץ לזמנו דאשכחן ליה ריצוי אפילו בפנים שמרצה לפיגולו ליענש כרת. דחזו לעבודת צבור כגון טמא. דבר שלא בהכשרו כגון לן באימורים. מדבר שבהכשרו לן בבשר ויוצא דמקדש מיוצא דבמה שאין שם מחיצה עכ\\\"ל. ופסק רבינו כר' יהודה:\",2,0],[8,365,3,7,\"ומ\\\"ש או קדשי קדשים שנשחטו בדרום או שנתקבל דמן בדרום אע\\\"פ שכל אלו פסולים אם עלו [לראש המזבח] לא ירדו. יש לתמוה דבריש מעילה (דף ב') גבי קדשי קדשים ששחטן בדרום וקיבל דמן בצפון בצפון וקיבל דמן בדרום איבעיא להו עלו מהו שירדו רבה אמר אם עלו ירדו רב יוסף אמר אם עלו לא ירדו אליבא דר' יהודה לא תיבעי לך דכ\\\"ע לא פליגי שאם עלו ירדו כי פליגי אליבא דר\\\"ש ואע\\\"ג דאיתותב רבא דאמר אם עלו ירדו היינו משום דאמר הכי לר\\\"ש אבל לר' יהודה לכ\\\"ע ירדו. ורבינו שפסק בסמוך כר' יהודה ה\\\"ל לפסוק כאן שאם עלו ירדו ושמא נוסחא אחרת היתה לרבינו בזה. והר\\\"י קורקוס ז\\\"ל נדחק מאד ליישב זה ולא כתבתיו שלא להאריך:\",1,0],[8,365,3,8,\"וכשם שאם עלו לא ירדו כו'. משנה בפ' המזבח מקדש (זבחים דף פ״ד):\",1,0],[8,365,3,9,\"ומ״ש ואם משלה בהם האור אע״פ שירדו יעלו שניה וכו'. מימרא דעולא שם (דף פ״ה:) ובפרק בית שמאי (זבחים דף מ״ג):\",1,0],[8,365,3,10,\"קומץ שנתפגל כו'. גם זה בפרק ב״ש (זבחים דף מ״ג):\",1,0],[8,365,3,11,\"איברים וחלבים וקמצים שלנו בראשו של מזבח וכו'. בפ' המזבח מקדש (זבחים דף פ״ז) אתמר איברים שלנו בעזרה מקטיר והולך כל הלילה לנו בראשו של מזבח מקטיר והולך לעולם ירדו רבה אמר יעלו רבא אמר לא יעלו ופסק כרבא דבתרא הוא:\",1,0],[8,365,3,12,\"ומ\\\"ש ואויר מזבח כמזבח. שם בעא ר\\\"ל מר\\\"י ואסיקנא דבעומד האדם בראש המזבח ואוחז האבר בידו פשיטא דאויר מזבח כמזבח דמי כי מיבעיא ליה [דעומד בקרקע העזרה] ונקיט ליה בקניא כנגד המזבח מאי תיקו. ויש לתמוה על רבינו שסתם דבריו ולא חילק והר\\\"י קורקוס ז\\\"ל דחק עצמו להוכיח שנפשטה הבעיא ממקומות אחרים ולי אין צורך לכך אלא מאחר דלא איפשיטא בעיא מספיקא לא תרד:\",1,0],[8,365,3,12,\"אימורי קדשים קלים וכו'. כלומר אע״פ שהעלום בפסלות כיון שנזרק הדם אח״כ לא ירדו. בר״פ המזבח מקדש ובספ״ק דמעילה מימרא דעולא ובפ' המזבח מקדש (זבחים דף פ״ג:) בעיא דאיפשיטא ועיין במ״ש רבינו רפ״ב מהל' מעילה. וכתבו התוס' דאימורי קדשים קלים דנקט לרבותא וכ״ש קדשי קדשים:\",2,0],[8,365,3,13,\"הפריש שני אשמות לאחריות ושחט את שניהם וכו' הרי אלו ירדו. בסוף פרק קמא דמעילה (דף ז') אילו הפריש שתי אשמות לאחריות ושחט את שניהם וקדם והעלה אמורים של אחד מהם קודם זריקה אי אתה מודה שאם עלו ירדו. ופירש\\\"י לאחריות שאם יאבד אחד מהם שיתכפר באחר והאי דנקט שני אשמות וכ\\\"ש שתי חטאות דחטאת חמירא קדושתה מאשם. ושחט את שניהם וקדם והעלה אימורים של אחד מהם קודם זריקה ואח\\\"כ זרק הדם ואשם שלא קרבו אמורים אי אתה מודה שאם עלו באותן אימורים שירדו דזריקת דם דאידך לא מהניא להני אימורים דלאו דידיה משום דמגופא אחרינא נינהו עכ\\\"ל. וכתב הראב\\\"ד והוא שזורק דם האחר וכו'. ומבואר הוא בדברי רש\\\"י שכתבתי ואין מזה השגה על רבינו שלא כתבו שהוא העתיק דברי הגמרא כמנהגו:\",1,0],[8,365,3,14,\"הזבח הפסול והנסכים הפסולים שעלו למזבח וכו'. פלוגתא דתנאי במשנה ר״פ המזבח מקדש (זבחים דף פ״ג) ופסק כר״ש שסובר כר' יהושע.\",1,0],[8,365,3,14,\"ומ\\\"ש וכן נסכים הבאים בפני עצמן שנפסלו ועלו וירדו. שם (דף פ\\\"ד) נסכים הבאים בפני עצמן לדברי כולן ירדו:\",2,0],[8,365,3,15,\"עוף שמלקו זר ועלה וכו'. בפ' חטאת העוף (זבחים דף ס״ט) א״ר יצחק שמעתי שתים אחת קמיצת זר ואחת מליקת זר אחת תרד ואחת לא תרד [ולא ידענא] א״ר חזקיה מסתברא קמיצה תרד מליקה לא תרד מ״ש מליקה דישנה בבמה קמיצה נמי ישנה בבמה וכו' אלא אימא אין קידוש בכלי שרת במנחה בבמה. ופירש״י הילכך לא ילפינן זר במקדש לענין קמיצה מזר בבמה דלא דמי הך קמיצה להך קמיצה דבמקדש הואיל וקדשה בכלי שרת איפסלא בזר עכ״ל.\",1,0],[8,365,3,15,\"ומ\\\"ש רבינו כאילו לא נתקדש כלל. לעיל קאי וה\\\"ק וקומץ המנחה שקמצו זר ועלה ירד כאילו לא נתקדש כלל אע\\\"פ שזה פסול וזה פסול.\",2,0],[8,365,3,15,\"ומ\\\"ש ואחד הזר ואחד שאר הפסולים. הכי משמע משום דמהי תיתי לן לפלוגי בינייהו:\",3,0],[8,365,3,16,\"ואלו אם עלו ירדו וכו' עד אם עלו ירדו. משנה בפרק המזבח מקדש שם:\",1,0],[8,365,3,17,\"קומץ שמיצה שמנו על העצם וכו'. בפרק הקומץ רבה (מנחות דף כ״ג) בעיא דלא איפשיטא, ורש״י והראב״ד גורסים על העצים ומפרשים אותה בענין אחר וז״ל ההשגות א״א בנוסחא שלנו שמנו על העצים ומה שפירש וכו' עד וזה הבעיא במנחות פ' הקומץ. וז״ל הגמרא בעא רבא קומץ שמיצה שמנו על העצם מהו חיבורי עולים כעולים דמו או לאו כעולים דמו ומפרשה רבינו לענין ירד אם יחזיר ולא איפשיטא ופסק רבינו דיחזיר משום דמספיקא לא מזלזלינן בקדשים שלא להעלותם שמא הדין נותן להעלותם. ומה שהקשה הראב״ד שדבר הלמד מענינו הוא וכו' וחתם דבריו וזו הבעיא במנחות פ' הקומץ כלומר תדע שאין בעיא זו ענין עליה וירידה שהרי היא במנחות פרק הקומץ דמיירי בענין חסרון הקומץ או שמנו ואלו היתה ענין לירידה ועליה בזבחים פ' המזבח מקדש ה״ל לאתויי. ואני אומר שאע״פ שטענה זו טענה היא מ״מ אינה מכרחת ולפי גירסת רבינו הוצרך לפרש כמו שפירשה ויש כדמות ראיה לגירסת רבינו מדאמרינן עלה לאו היינו דר״י ור״ל דאתמר המעלה אבר שאין בו כזית ועצם משלימו לכזית וכו':\",1,0],[8,365,3,18,\"מזבח הפנימי מקדש פסולים וכו' עד וכן כל כיוצא בזה. בפרק שני דזבחים (דף כ\\\"ז:) ויהיבו טעמא בגמרא משום דמזבח הפנימי כלי שרת ופירש\\\"י שהוא כלי שרת ונמשח עם המשכן:\",1,0],[8,365,3,18,\"כשם שהמזבח מקדש את הראוי לו וכו'. משנה פרק המזבח מקדש (זבחים דף פ״ו).\",2,0],[8,365,3,18,\"ומ\\\"ש וכן כשיגיע לכלי שרת כל דבר הראוי לו מתקדש. שם.\",3,0],[8,365,3,18,\"ומ\\\"ש ולא יפדה לעולם. משנה בריש פרק המנחות (דף ק'):\",4,0],[8,365,3,19,\"אין כלי הלח מקדשות את היבש וכו'. משנה פרק המזבח מקדש (זבחים דף פ״ח).\",1,0],[8,365,3,19,\"ומ\\\"ש בד\\\"א במדות הלח ויבש וכו' אבל המזרקות מקדשות הלח והיבש. מימרא דשמואל שם ופ\\\"ק דמנחות (דף ח':):\",2,0],[8,365,3,19,\"כלי שרת מקדשים דם הפסול ליקרב. בר\\\"פ בתרא דכריתות (דף כ\\\"ג) תנן אשם תלוי שנודע שלא חטא לר' יוסי אם כבר נשחט וקיבל הדם בכוס יזרק ופסק כר' יוסי דנימוקו עמו:\",3,0],[8,365,3,20,\"כל כלי השרת אין מקדשין אלא במקדש. מימרא דשמואל בפ' המזבח מקדש.\",1,0],[8,365,3,20,\"ומ\\\"ש אלא מדעת. מימרא דר\\\"י פ\\\"ק דמנחות (דף ז').\",2,0],[8,365,3,20,\"ומ״ש ואין מקדשין אלא מתוכן. מימרא דשמואל בפ' המזבח מקדש (זבחים דף פ״ח).\",3,0],[8,365,3,20,\"ומ\\\"ש ואין מקדשין אלא שלימים ניקבו אם עושים מעין מלאכתן שהיו עושים והם שלימים מקדשין ואם לאו אין מקדשין. משנה שם.\",4,0],[8,365,3,20,\"ומ\\\"ש ואין מקדשין אלא מליאים. מימרא דשמואל שם.\",5,0],[8,365,3,20,\"ומ\\\"ש אבל המדות אין מקדשות חסרות אלא אם דעתו למלאותם וכו'. שם ופ\\\"ק דמנחות (דף ח') מימרא דר\\\"י וברייתא שניהם מליאים אין מליאים אלא שלימים וכו' א\\\"ר יוסי אימתי בזמן שאין דעתו להוסיף אבל דעתו להוסיף ראשון ראשון קידש ופירוש מלאים פירש\\\"י שיש בהם שיעור הצריך לאותו דבר ואין דעתו להוסיף פירש שאין דעתו להשלים השיעור. ומדברי רש\\\"י נראה שיש בנוסחא דידן בגמרא חסרון לשון המדבר בענין המדות.\",6,0],[8,365,3,20,\"ומה שכתב ואם אין [דעתו] למלאותן מקדשות להפסל אבל לא ליקרב. נראה שלמד כן מדאמרינן בפ\\\"ק דמנחות (דף ז') בעא מיניה מר\\\"י כלי שרת מהו שיקדשו פסולים (ופירש\\\"י) כגון אם קמץ זר ונתן בכלי ויש לדקדק שדין זה סותר מ\\\"ש לעיל בפ' זה כלי שרת מקדשים דם הפסול ליקרב. ושמא י\\\"ל דשאני בין דם לשאר דברים ועי\\\"ל שלמד כן מדאמרינן בס\\\"פ המזבח (דף פ\\\"ח) אין כלי הלח מקדשים את היבש אמר רב אין מקדשין ליקרב אבל מקדשין ליפסל:\",7,0],[8,365,3,21,\"כלי שרת מקדשין שלא בזמנן כו'. בס״פ שתי הלחם (מנחות דף ק'):\",1,0],[8,365,3,23,\"מזבח שנפגם וכו' אבל קדשים חיים שהיו שם בעזרה כשנפגם לא נפסלו וכו'. בפ' קדשי קדשים (זבחים דף נ״ט) אמר רב מזבח שנפגם כל הקדשים שנשחטו שם פסולים והכי א״ר [שמעון] ברבי משום רבי ישמעאל בר' יוסי ומייתי לה מדכתיב וזבחת עליו את עולותיך ואת שלמיך וכי עליו אתה זובח אלא כשהוא שלם ולא כשהוא חסר וכו' ור״י אמר אחד זה ואחד זה פסולים במאי קא מיפלגי רב סבר בעלי חיים אינם נדחים ור״י סבר ב״ח נדחים. ופירש״י שנשחטו שם בעזרה כשהוא שלם והאי עליו בגינו ובשבילו קאמר. אחד זה ואחד זה בין שנשחטו בשעת פגימתן בין שנשחטו אחר תיקונו פסולים. ופסק רבינו כרב ונתבאר בפט״ו מהלכות מעשה הקרבנות:\",1,0],[8,365,3,24,\"הקדיש בהמות עד שלא נבנה המזבח כו'. שם אהא דתניא כל הקדשים שהיו עד שלא נבנה המזבח פסולים פריך נבנה דחויים מעיקרא נינהו כלומר וכשרים הם:\",1,0],[8,365,3,25,\"וכן אין אוכלים קדשים והמזבח פגום וכו'. שם (דף ס') א\\\"ר אלעזר מזבח שנפגם אין אוכלים בגינו שירי מנחה שנאמר ואכלוה מצות אצל המזבח וכי אצל המזבח אכלוה אלא בזמן שהוא שלם ולא בזמן שהוא חסר אשכחן שירי מנחה קדשי קדשים מנ\\\"ל ת\\\"ל קדש קדשים קדשים קלים מנין אמר אביי אתיא מדרשא דר' יוסי וכו':\",1,0],[8,365,4,1,\"ולד חטאת ותמורת חטאת וכו'. משנה רפ\\\"ד דתמורה (דף כ\\\"א:) ופ\\\"ג דמעילה (דף י':).\",1,0],[8,365,4,1,\"ומ\\\"ש נמצאת אחר שנשחטה החטאת השניה שהפריש קודם שיזרק דמה ה\\\"ז ספק וכו'. בפ\\\"ד דתמורה (דף כ\\\"ב:) בעיא דלא איפשיטא.\",2,0],[8,365,4,1,\"ומ\\\"ש וכיצד הן מתות וכו'. פ\\\"ק דע\\\"ז ופ\\\"ד דנזיר (דף כ\\\"ה).\",3,0],[8,365,4,1,\"ומ\\\"ש ודברים אלו כולם מפי משה רבינו נשמעו. ברפ\\\"ג דתמורה (דף י\\\"ח) ופ\\\"ב דבכורות (דף ט\\\"ז):\",4,0],[8,365,4,1,\"אין כל הדברים אמורים וכו' עד ואין כל ישראל מתים. בפרק שני דתמורה (דף ט\\\"ו):\",5,0],[8,365,4,2,\"פר ושעיר של יום הכפורים וכו'. בפ' שני שעירי (יומא דף ס״ה) פלוגתא דתנאי ופסק כר' אלעזר בר״ש דסתם מתני' כוותיה ובפירקא קמא דשבועות (דף י״ב) מייתי לה וגריס ר' אלעזר ור״ש ולפי גירסא זו פסק כוותייהו משום דרבים נינהו.\",1,0],[8,365,4,2,\"ומ\\\"ש ולמה לא יקרבו עצמם נדבה וכו'. בפ\\\"ק דשבועות שם:\",2,0],[8,365,4,3,\"המפריש חטאתו ואבדה וכו'. בפ\\\"ד דתמורה (דף כ\\\"ב:) איפליגו ר' ורבנן בנמצאת קודם כפרה דלרבי תמות ולרבנן תרעה וידוע דהלכה כרבנן ואמר רב הונא אמר רב (דף כ\\\"ג) הכל מודים שאם משך אחת והקריבה שהשניה מתה לא נחלקו אלא בבא לימלך דרבי סבר לא עשו תקנה בקדשים וכו' ורבנן סברי עשו תקנה בקדשים ואמרינן ליה התכפר באבודה ושאינה אבודה תרעה. ופירש\\\"י שאם משך אחת מהן והקריבה מדעתו דחה האחרת בידים דגלי דעתיה דלא איכפת לי' מינה ואפי' משך האבודה ונתכפר בה והנשארת היא שלא נאבדה מעולם מתה וכי פליגי רבנן היינו בבא לימלך דגלי דעתיה דניחא ליה עכ\\\"ל. ואע\\\"ג דר' אבא פליג ארב הונא פסק רבינו כרב הונא משום דמסתבר טעמיה ועוד דאתיא ליה סתם מתני' כדברי הכל:\",1,0],[8,365,4,3,\"היתה אחת מהן תמימה ואחת בעלת מום וכו'. בפ\\\"ד דתמורה (דף כ\\\"ד) תניא היו לפניו שתי חטאות אחת תמימה ואחת בעלת מום תמימה תקרב בעלת מום תפדה נשחטה בעלת מום עד שלא נזרק דמה של תמימה מותרת משנזרק דמה של תמימה אסורה ר' אלעזר בר\\\"ש אומר אפילו בשר בעלת מום בקדירה ונזרק דמה של תמימה יוצא לבית השריפה. ונראה מדברי רבינו שהוא פוסק כר' אלעזר בר\\\"ש וצריך טעם למה פסק כיחידאה ואפשר שטעמו משום דבגמרא העמידו ברייתא דאין מרגילין כראב\\\"ש ושקלו וטרו אמוראי בטעמא. ויותר נראה לומר שפסק כרבנן ויש חסרון בדברי רבינו וכך צריך להגיה נשחטה בעלת מום קודם שיזרק דם התמימה מותרת אחר שנזרק דמה אסורה בהנאה:\",2,0],[8,365,4,3,\"היו שתיהן בעלי מומין ימכרו שתיהם וכו'. משנה שם (דף כ\\\"ב):\",3,0],[8,365,4,4,\"הפריש חטאתו ואבדה וכו'. מימרא דר' זירא פ' התודה (מנחות דף פ':) ואע״ג דאביי פליג עליה פסק רבינו כר' זירא וצריך טעם למה מאחר דאביי בתרא הוא, ואפשר שטעמו משום דאמאי דאמר התם רבא הפריש תודתו ואבדה וחזר והפריש אחרת תחתיה וכו' א״ר זירא וכן לענין חטאות הפריש חטאתו ואבדה והפריש אחרת תחתיה וכו' וכיון דר״ז בשיטת רבא אמרה פסק כמותו ולא חש לדאביי:\",1,0],[8,365,4,5,\"המפריש שתי חטאות וכו'. פרק כיצד מערימין (תמורה כ\\\"ה).\",1,0],[8,365,4,5,\"ומה שכתב והשניה תרעה וכו'. פרק ולד חטאת (שם כ״ד) ופרק מי שהיה טמא (פסחים צ״ז:):\",2,0],[8,365,4,6,\"הפריש חטאת מעוברת וילדה וכו'. מימרא דר״י פרק כיצד מערימין (תמורה דף כ״ה):\",1,0],[8,365,4,7,\"המפריש חטאתו ועברה שנתה וכו'. מימרא דר\\\"ל רפ\\\"ד דתמורה.\",1,0],[8,365,4,7,\"מ\\\"ש וכן הפריש חטאתו ונפל בה מום יביא בדמיה אחרת. משנה בספ\\\"ד דתמורה (דף כ\\\"ב):\",2,0],[8,365,4,8,\"כל חטאת שאבדה וכו'. ברפ\\\"ד דתמורה תנן ולד חטאת וחטאת שמתו בעליה ימותו שעברה שנתה ושאבדה ונמצאת בעלת מום אם משכיפרו הבעלים תמות וכו' ואם עד שלא כיפרו הבעלים תרעה עד שתסתאב ותמכר ויביא בדמיה אחרת ובגמרא אמר ר\\\"ל חטאת שעברה שנתה רואין אותה כאילו עומדת בבית הקברות ורועה. ופירש\\\"י רועה עד שתסתאב. תנן שעברה שנתה ואבדה ונמצאת בעלת מום אם אחר שכיפרו בעלים מתה תיובתא ופירש\\\"י תיובתא דר\\\"ל דפסיק ואמר רועה ומשמע אפי' כפרו הבעלים. ואסיקנא הכי קתני עברה שנתה ואבדה או אבדה ונמצאת בעלת מום אחר שכיפרו הבעלים מתה קודם שכיפרו הבעלים תרעה עד שתסתאב ותמכר ופירש\\\"י עברה שנתה ואבדה ונמצאת תמימה וכיפרו הבעלים באחרת או אבדה ונמצאת בעלת מום דאיכא נמי תרתי לריעותא וכיפרו הבעלים באחרת מתה קודם שכיפרו הבעלים שאין רוצים להתכפר באחרת תרעה הך דעברה שנתה ואבדה ונמצאת תמימה וכי אמר ר\\\"ל דאפי' כיפרו אח\\\"כ רועה בלא אבדה דחדא הוא דאיכא לריעותא. ונראה שיש ייתור לשון בדברי רבינו וצריך למוחקו וכך צריך להגיה כל חטאת שאבדה ונמצאת קודם כפרה אינה מתה אלא תרעה עד שיפול בה מום ויפלו דמיה לנדבה:\",1,0],[8,365,4,9,\"היתה גנובה או גזולה וכו'. מימרא דאביי שם:\",1,0],[8,365,4,9,\"היתה עיקר אבידתה בלילה אע\\\"פ שהיתה אבודה בשעת כפרה אינה מתה אלא תרעה. ג\\\"ז שם:\",2,0],[8,365,4,10,\"אבדה ממנו ולא מן הרועה וכו'. מימרא דרב פפא שם:\",1,0],[8,365,4,11,\"וכל אלו שרועות רועות עד שיפול בהם מום ויפלו דמיהן לנדבה. בפ' שלישי דתמורה (דף י\\\"ט):\",1,0],[8,365,4,12,\"היתה אבודה ממנו ומן הרועה וכו'. בפ\\\"ד דתמורה (דף כ\\\"ב:) בעיא דלא איפשיטא:\",1,0],[8,365,4,13,\"היתה נחבאת אחורי הדלת. שם ה\\\"ד אבודה א\\\"ר אושעיא אפילו אחת בעדרו וכו' ור\\\"י אמר אחורי הדלת הוא דליכא דקא חזי לה אבל אבראי דאיכא דחזי לה לא הויא אבודה או דילמא אחורי הדלת דאי מהדר אפיה חזי לה הויא אבודה וכ\\\"ש אבראי דלא קחזי לה תיקו. ופסק רבינו כר\\\"י ונראה שהוא מפרש אבראי בסתר המדרגה ומספק פסק לחומרא. ורש\\\"י פירש בע\\\"א:\",1,0],[8,365,4,13,\"היתה בשדה או באגם וכו'. אפשר שרבינו מפרש שגם זה בכלל אבראי שכתבתי בסמוך:\",2,0],[8,365,4,14,\"השולח חטאתו ממדינת הים וכו'. משנה בפ' כל הגט (גיטין דף כ״ח).\",1,0],[8,365,4,14,\"ומ\\\"ש בד\\\"א בחטאת העוף וכו'. שם בגמרא (כ\\\"ח:) והא בעי סמיכה אמר רב יוסף בקרבן נשים רב פפא אמר בחטאת העוף:\",2,0],[8,365,4,14,\"אבל אשם ודאי שמתו בעליו וכו'. משנה פ\\\"ג דתמורה (דף כ\\\"א ע\\\"ב).\",3,0],[8,365,4,14,\"ומ\\\"ש שכל שבחטאת תמות באשם ירעה וכו'. ברפ\\\"ג דתמורה (דף י\\\"ח):\",4,0],[8,365,4,15,\"וכל אשם שניתק לרעייה אם הקריבו עולה כשר. שם ופ״ק דמנחות (דף ד') ובפסחים פרק אלו דברים (פסחים דף ע״ג) [ובזבחים פ״א (דף ה':)] אמר רב הונא אמר רב אשם שניתק לרעייה ושחטו סתם כשר לעולה ניתק אין לא ניתק לא ופירש״י שניתק לרעייה שמתו בעליו או שנתכפרו באחר וניתק מדין אשם לרעייה שאמרו לו ב״ד הוציאו וירעה ושחטו סתם כשר לעולה הואיל וסופו לקיץ המזבח שהוא עולה. ניתק אין דמיעקר שם אשם מיניה משנמסר לרועה וקם סתמיה לעולה לא ניתק לא הוי סתמיה לעולה דאמר קרא [אשם] הוא בהוייתו יהא. ובפסחים פרק אלו דברים מסיק עלה לא תימא ששחטו סתם [כשר לשום עולה] אלא אימא שחטו לשום עולה כשר.\",1,0],[8,365,4,15,\"ומ\\\"ש רבינו ולמה לא יקרב בעצמו לכתחלה וכו'. בפסחים פ' אלו דברים שם:\",2,0],[8,365,4,16,\"המפריש נקבה לאשמו וכו' עד ויפלו דמיה לנדבה. משנה בפ\\\"ג דתמורה (דף י\\\"ט:).\",1,0],[8,365,4,16,\"ומ\\\"ש וכן ולדה. שם אהא דתנן דמפריש נקבה לעולה וילדה זכר ירעה עד שיסתאב וימכר ויביא בדמיו עולה ר\\\"א אומר הוא עצמו יקרב עולה א\\\"ר יוסי בר חנינא מודה ר\\\"א במפריש נקבה לאשם דאין בנה קרב אשם:\",2,0],[8,365,4,17,\"הפריש נקבה לעולתו וילדה זכר וכו'. משנה כתבתיה בסמוך:\",1,0],[8,365,4,18,\"ומ\\\"ש אבל הדיוט שהפריש זכר לחטאת ונשיא שהפריש שעירה לחטאת וכו'. שם ת\\\"ר המפריש נקבה לעולתו ולפסחו ולאשמו עושה תמורה וכו' עד ראב\\\"ע אומר תור או בן יונה. ופירש\\\"י לפסחו ולאשמו לא מצינו אשם ופסח נקבה וכו' עד דאפילו גבי נדבה דעשיר סתם חזיא עולת העוף:\",1,0],[8,365,4,18,\"וכתב הראב\\\"ד אבל הדיוט וכו' עד הרי אלו אין מתקדשים א\\\"א אין דבריו מחוורים שכל אותם דברים וכו' עד לפרושי טעמא דר\\\"ש באשם. ואיני יודע איך נתפייס הראב\\\"ד ביישוב השגה זו במ\\\"ש ואולי מפני שאמר רבינו אין אני רואה דבריו של ר\\\"ש בפסח וכו' שאילו היה רבינו פוסק במפריש נקבה לאשם תמכר כר\\\"ש היו טענות אלו טענות אבל מאחר שרבינו פוסק בה שתרעה וכרבנן אין טענות אלו טענות דה\\\"ל כמזכי שטרא לבי תרי. ואפשר לדחוק ולומר שטעם רבינו הוא מדאמרינן אלא מעתה כהן גדול שהקדיש פרה לפרו תקדש יחיד שהפריש שעיר לשעירתו תקדש א\\\"נ נשיא שהפריש שעירה לשעירו תקדש משמע דפשיטא ליה לגמרא בכל הני דלא קדש לדברי הכל ואע\\\"ג דבמקריב נקבה לאשם סבר ת\\\"ק דתרעה בהני דחטאת נינהו סבר דלא קדשי:\",2,0],[8,365,4,19,\"הביא אשם תלוי ונודע לו שלא חטא וכו'. בכריתות רפ\\\"ו (דף כ\\\"ג:) המביא אשם תלוי ונודע לו שלא חטא [אם עד שלא נשחט] יצא וירעה בעדר דברי ר\\\"מ וחכ\\\"א ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה ובגמרא במאי פליגי ר\\\"מ סבר כיון דלא צריך ליה לא מקדיש ליה ורבנן סברי מתוך שלבו נוקפו גומר ומקדיש תנא בין שנודע לו שחטא ובין שנודע לו שלא חטא פליגי ר\\\"מ ורבנן.\",1,0],[8,365,4,19,\"ומ\\\"ש הפרישו אפי' ע\\\"פ עדים והוזמו יפלו דמיו לנדבה. שם (דף כ\\\"ד) א\\\"ר יהודה אמר רב מודים חכמים [לר\\\"מ] באשם תלוי שהוזמו עדיו שיצא וירעה בעדר מ\\\"ט ע\\\"כ לא פליגי רבנן עליה אלא היכא דאפרשיה על פי עצמו דאמרי' לבו נוקפו אבל היכא דע\\\"פ עדים אפרשיה לא הוה סמוך עילוויהו דעדים דסבר דילמא אתו אחרים ומזמי להו מתיב רבא שור הנסקל אינו כן וכו' בפלוגתא אשם תלוי שהוזמו עדיו ר' אלעזר אומר הרי היא כמנחת קנאות וכו' תצא לחולין ר\\\"י אמר ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה ופסק רבינו כר\\\"י לגבי רב ועוד דרבא דבתרא הוא מתיב לרב ואע\\\"ג דשני שינויא דחיקא הוא.\",2,0],[8,365,4,19,\"ומ\\\"ש רבינו יפלו דמיו לנדבה. כלומר אחר שרעה עד שנסתאב.\",3,0],[8,365,4,19,\"ומ\\\"ש ואם אחר שנשחט נודע לו הדם ישפך והבשר ישרף וכו'. שם במשנה.\",4,0],[8,365,4,19,\"ומ\\\"ש נודע לו אחר שנזרק הדם הבשר יאכל וכו'. ג\\\"ז שם במשנה:\",5,0],[8,365,4,20,\"אשם ודאי אינו כן וכו' עד הבשר יצא לבית השריפה. גם זה שם במשנה:\",1,0],[8,365,4,21,\"מי שנתחייב באשם תלוי וכו'. שם א\\\"ר ששת דמודה ר\\\"מ בהא [ויהיב טעמא] משום דכיון דאפריש תרי סבר אי מירכס חד מיכפרנא באידך וכיון דגלי דעתיה דלבו נוקפו היה כו' גמר והקדישו ופירש\\\"י לאחריות שאם יאבד האחד יקריב לחבירו:\",1,0],[8,365,4,22,\"כל האשמות שבתורה באים בני שתים וכו'. משנה בפרק כל התדיר (זבחים דף צ':) ופירש רש\\\"י ובאים בכסף שקלים (כדיליף בפרק דם שחיטה) דכתיב בערכך כסף שקלים באשם מעילות ואתי אשם תלוי ואשם גזילות בג\\\"ש בערכך בערכך ואשם שפחה חרופה גמר באיל באיל וכו'. חוץ מאשם נזיר. דכתיב כבש בן שנתו ומדאיל בן שתי שנים בשתי סלעים כבש בן שנה לאו בשתי סלעים הוא:\",1,0],[8,365,4,22,\"אשם תלוי בא מן הקטנים או מן הגדולים. ומה שכתב מפי השמועה למדו שאינו בא אלא בכסף שקלים. בפרק דם שחיטה (כריתות דף כ״ב:) יליף מקרא דאשם תלוי בכסף שקלים:\",2,0],[8,365,4,23,\"הוזלו אילים וכו'. בסוף כריתות (דף כ\\\"ז):\",1,0],[8,365,4,24,\"הפריש אשמו והיה בשעת הפרשה יפה סלע וכו'. שם איבעיא להו אדם מתכפר בשבח הקדש או לא ואסיקנא ת\\\"ש בשעת הפרשה יפה סלע בשעת כפרה יפה שתי סלעים יצא:\",1,0],[8,365,4,24,\"היה בשעת הפרשה יפה שתים וכו'. תוספתא בסוף כריתות.\",2,0],[8,365,4,24,\"ומ\\\"ש חזר ונעשה יפה שתים יחזור לכשרותו שאין ב\\\"ח נדחים כמו שביארנו. בפט\\\"ו ממעשה הקרבנות:\",3,0],[8,365,4,25,\"הפריש שתי סלעים לאשם וכו'. משנה שם (דף כ\\\"ו:):\",1,0],[8,365,4,26,\"היה חייב באשם בן שנה והביא בן שתים וכו' עד ויצא לבית השריפה. [בתוספתא דזבחים פ״ק] ובפ' התכלת (מנחות דף מ״ח:):\",1,0],[8,365,4,26,\"זה הכלל כל הפסול בחטאת פסול באשם וכו'. בתוספתא דזבחים פ\\\"ק שם:\",2,0],[8,365,4,27,\"עולת נזיר עולת יולדת וכו'. בתוספתא דזבחים פ\\\"ק אלא שכתוב שם שלא עלו לבעלים לשם חובה ולא ידעתי למה השמיטו.\",1,0],[8,365,4,27,\"ומ\\\"ש זה הכלל כל שאינו פוסל בעולת נדבה וכו'. ג\\\"ז שם:\",2,0],[8,365,5,1,\"המפריש מעות לחטאתו וכו'. משנה בכמה מקומות מהם פרק ד' דנזיר (דף כ\\\"ד) ופרק ג' דמעילה (דף י\\\"א):\",1,0],[8,365,5,2,\"הפריש מעות לחטאתו ואבדו וכו' עד ולא הספיק ליקח בהם עד שנמצאת חטאתו והרי היא בעלת מום תמכר ויביא מאלו ומאלו חטאת והשאר יפלו לנדבה. הכל משנה בפ\\\"ד דתמורה (דף כ\\\"ב):\",1,0],[8,365,5,5,\"הפריש שני צבורי מעות לאחריות וכו'. מימרא דר' אמי שם (דף כ\\\"ג:):\",1,0],[8,365,5,6,\"המפריש חטאתו או דמי חטאתו וכסבור שהוא חייב וכו'. ירושלמי בפ\\\"ב דשקלים.\",1,0],[8,365,5,6,\"ומ\\\"ש הפריש שתים או דמי שתים וכו'. שם הפריש ב' וסבור שהוא חייב ב' ונמצא שאינו חייב אלא אחת אותה השניה מה את עביד לה אלא רועה.\",2,0],[8,365,5,6,\"ומ\\\"ש והשאר יפלו לנדבה, אדמי שתים קאי כפשטיה ואשתים היינו לומר רועה עד שתסתאב ויפלו דמיה לנדבה:\",3,0],[8,365,5,7,\"הלוקח מעות בידו או וכו'. שם במשנה המכנס מעות ואמר הרי אלו לשקלי ב\\\"ש אומרים מותרן נדבה ובית הלל אומרים מותרן חולין אלו לחטאתי שוין שהמותר נדבה שאביא מהם חטאתי שוין שהמותר חולין ופירושה מבואר דכשאומר שאביא מהם חטאתי לא הקדיש אלא מה שצריך מהם לחטאתו בלבד ורבינו כתב סיפא והשמיט רישא אלו לחטאתי ולא ידעתי למה.\",1,0],[8,365,5,7,\"ומ\\\"ש הלוקח מעות בידו או שהיה מלקט. שם בירושלמי לגבי שקלים חילקו בין מכניס פרוטרוט לאומר אלו לשקלי ורבינו שהשוה אותם לענין שאביא מהם חטאתי צ\\\"ע מהיכא יליף לה.\",2,0],[8,365,5,7,\"ועל מ\\\"ש רבינו שנ\\\"ל שהדבר ק\\\"ו בשאר הקרבנות. כ' הראב\\\"ד א\\\"א אני אין לי אלא קרבן חובה וכו'. ואני בעניי נ\\\"ל שי\\\"ל דאפי' בעולה ושלמים כל שאמר שאביא מהם משמע שלא התנדב כל אותם הדמים דלשון שאביא מהם מורה שלא הקדיש מהם אלא כדי עולה ושלמים בלבד ומה ששנינו מותר עולה לעולה מותר שלמי' לשלמי' אינו אלא באומר הרי אלו לעולה או לשלמים אבל אם אמר שאביא מהם עולה או שלמים דינו כאומר שאביא מהם חטאתי או אשמי שלא הקדיש מהם אלא כדי אותו קרבן שאמר בין שהוא חובה בין שהוא נדבה:\",3,0],[8,365,5,8,\"המפריש מעות למנחת חוטא וכו'. בפירקא בתרא דמנחות (דף ק\\\"ח):\",1,0],[8,365,5,8,\"וכן מותר לחמי תודה. בפ\\\"ב דשקלים ירוש' מותר לחמו של נזיר ירקב א\\\"ר יוסי ויאות להקריבו בפ\\\"ע אי אתה יכול שאין לך לחם קרב בפ\\\"ע להקריבו עם נזירות אחרת אי אתה יכול שאין לך נזירות באה בלא לחם לפום כן איצטריך למימר מותר לחמו של נזיר ירקב סברין למימר הוא מותר לחמו הוא מותר נסכים א\\\"ר יוסי בר ביבין מותר נסכים קדשי קדשים אינון ויפלו לנדבה.\",2,0],[8,365,5,8,\"ומ\\\"ש מותר לחמי תודה. נראה שהוא נלמד מדין מותר לחמו של נזיר שהטעם בשניהם שוה:\",3,0],[8,365,5,8,\"כבר ביארנו בשקלים שמותר השקלים חולין וכו' עד מותר נזיר לאותו נזיר. הכל משנה במס' שקלים פ\\\"ב:\",4,0],[8,365,5,9,\"במה דברים אמורים שמותר חטאת לנדבה וכו'. מה שכתב רבינו שאם הפריש מעות לחטאת בהמה והעני מביא תחתיהן עוף וכו' עד שאין לעוף פדיון. הכל משנה בסוף כריתות ומתוך שנראה דמתני' דשקלים ומתני' דסוף כריתות (דף כ\\\"ז:) קשו אהדדי תירץ רבינו דמתני' דשקלים בחטאת קבועה ומתני' דסוף כריתות בקרבן עולה ויורד:\",1,0],[8,365,5,11,\"כל חייבי קינין שבתורה שהפרישו מעות לקיניהם וכו' עד שאין הקינין מתפרשות אלא בלקיחת הבעלים. בפרק טרף בקלפי (יומא דף מ״א) ובסוף כריתות (דף כ״ח) אמר רב חסדא אין הקינין מתפרשות אלא או בלקיחת הבעלים או בעשיית כהן. פי' בלקיחת הבעלים כשקנאם אמר זה לחטאתי וזה לעולתי אבל אם קנה שנים לחובתו ואחר זמן אמר זה לחטאתי וזה לעולתי לא הוקבעו ויכול לשנותם:\",1,0],[8,365,5,12,\"ומ\\\"ש לפיכך אם הפריש מעות לקינין סתם וכו'. הוא ע\\\"פ מה ששנינו בפ' ולד חטאת וכתבו רבינו בפ' זה:\",1,0],[8,365,5,13,\"מי שהיה מחוייב וכו' רצה להביא בהם חטאת בהמה יביא עולת בהמה יביא תוספתא בפ\\\"ק דמעילה אלא שאינה מכוונת בלשון רבינו וזה לשון הראב\\\"ד א\\\"א מצאתי דבר זה בגמרא דנזיר ובתוספתא שהוא בחילוף וכו' עד אמאי ילכו לים המלח. ומ\\\"ש שהוא בגמ' נזיר הוא בפ\\\"ד (דף כ\\\"ו) מי שהיה מחוייב חטאת ואמר הרי עלי עולה והפריש מעות ואמר הרי אלו לחובתי רצה להביא בהם חטאת בהמה לא יביא עולת בהמה לא יביא מת והיו לו מעות סתומים ילכו לים המלח ורבינו גורס יביא.\",1,0],[8,365,5,13,\"ומ\\\"ש הראב\\\"ד מסתבר דהכי הוא וכו' כלומר הוא משיג על גירסת רבינו שאם רצה להביא מהם חטאת או עולה יביא וא\\\"כ למה כשמת ילכו לים המלח מ\\\"ש ממה שנתבאר בסמוך גבי הפריש מעות לקינין סתם ומת שיפלו לנדבה מפני שהם ראויים לבא כולם עולה. ואפשר שגירסת רבינו רצה להביא חטאת בהמה יביא עולת בהמה לא יביא והטעם מבואר דלא שביק איניש מלהביא מה שהיה חייב מקודם ומביא מה שנתחייב אח\\\"כ וכ\\\"ש בהיות מה שנתחייב תחלה חטאת ומה שנתחייב אח\\\"כ עולה. ומ\\\"ש הראב\\\"ד בשם התוספתא שאם מת יפלו המעות לנדבה מפני שכולם ראויים לבא עולה. הוא בפ\\\"ק דמעילה ומסיים בה מת הדמים ילכו לים המלח מפני שדמי חטאת מעורבין בהם וקשה עליו וגם על התוספתא למה אם רצה להביא בהם עולת העוף לא יביא מ\\\"ש ממ\\\"ש בסמוך שאפי' אמר אלו דמי חטאתי ואלו דמי עולתי יש לו לערב המעות ולוקח בכל חטאת או עולה. ונראה שמפני שהרגיש הראב\\\"ד בקושיא זו כתב והתוספתא יותר מתוקנת מן הגמרא כלומר אע\\\"פ שגם על התוספתא קשה למה לא יביא עולה מ\\\"מ היא מתוקנת יותר מהגמרא מפני שעל הגמ' קשה מינה ובה:\",2,0],[8,365,6,1,\"כל הזבחים שנתערב וכו'. משנה ריש פרק התערובות (דף ע':).\",1,0],[8,365,6,1,\"ומה שכתב ואם הקריב הורצה. שם אמר רבא אי אקריב ארצי ואותבוה ממתני' דקינין ואוקמוה ההיא מתניתין כמאן דאמר בעלי חיים אין נדחים. וכבר נתבאר בפרק ט\\\"ו ממעשה הקרבנות דהלכה כמאן דאר אין בעלי חיים נדחים:\",2,0],[8,365,6,2,\"נתערב בהם אחד וכו'. עד שהרי דמי חולין הם. משנה שם:\",1,0],[8,365,6,4,\"נתערב שור הקדש בשוורים. בפ' בתרא דמנחות (דף ק\\\"ח:) שור של הקדש שנתערב באחרים הגדול שבהם הקדש וכלם ימכרו לצרכי עולות ודמיהם חולין, ודבר פשוט דלדוגמא נקט עולות כלומר אם היה אותו שור עולה ומינה נילף שאם היה מין זבח אחר ימכרו לצרכי אותו המין וכן מפורש בתוספתא בפרק הנזכר:\",1,0],[8,365,6,4,\"נתערבו קדשים בקדשים וכו'. משנה בפרק התערובות (דף ע\\\"ח:).\",2,0],[8,365,6,4,\"ומ\\\"ש בד\\\"א בקרבנות נשים וכו'. שם מימרא דרב יוסף (דף ע\\\"ד:):\",3,0],[8,365,6,5,\"נתערבו מין בשאינו מינו וכו'. משנה שם (דף ע\\\"ה:):\",1,0],[8,365,6,6,\"ומ\\\"ש שאין ממעטין באוכליהן ולא במקום אכילתן. נתבאר בפ\\\"י ממעשה הקרבנות:\",1,0],[8,365,6,7,\"ומ\\\"ש אע\\\"פ שכבר הקריב עולה שחייב בה או שלמים וכו'. תוספתא בפ\\\"ח ממס' זבחים:\",1,0],[8,365,6,8,\"חטאת שנתערבה וכו'. תוספתא פרק ח' דזבחים אלא ששם כתוב שנתערבה באחת מכל הזבחים:\",1,0],[8,365,6,8,\"ואם קדם והקריב וכו'. שם:\",2,0],[8,365,6,9,\"וכן אם נתערבו וכו'. גם זה שם:\",1,0],[8,365,6,9,\"כתב הר\\\"י קורקוס ז\\\"ל איני יודע טעם למיתה זו או להולכת מעות לים המלח כי כבר נתבאר שלא קבלו ההלכה שחטאת מתה אלא באבודה דוקא לא בגנובה. ואפשר היה לומר דנתערבה הוי אבידה טפי מגניבה וכאשר הוזכר פ\\\"ד דתמורה (דף כ\\\"ב:) בדעת ר' אושעיא שאפילו נתערבה אחת באחת הויא אבודה ואפי' בדברי ר\\\"י שאמרו שם אבל אבראי כתב רש\\\"י שהלכה ונתערבה. אלא שאין נראה כן דעת רבינו כלל כי דברי הבעיא דבעי אליבא דר\\\"י פי' באבודה ומשום שמא יש אחד שרואה אותה ולא הזכיר נתערבה או שסובר דאביי דאמר נקטינן אבודה ולא גזולה פליג או שר\\\"י חולק וסובר שאין תערובת אבודה אלא אחורי הדלת וכאשר כתב רש\\\"י בצד אחד מהבעיא דבעדר כיון דחזו לכולהו אף על פי שאינה ניכרת אינה אבודה ופסק כר\\\"י כיון דבעי אליביה ואם כן מיתה זו כאן למה כיון דאפשר ברעיה וצל\\\"ע עכ\\\"ל:\",2,0],[8,365,6,10,\"תודה שנתערבה וכו'. שם:\",1,0],[8,365,6,10,\"כתב הראב\\\"ד תודה שנתערבה א\\\"א והא קא ממעט באכילת זרוע בשלה עכ\\\"ל. ואסיפא דמלתא קאי דקתני נתערבה באיל נזיר שניהם יקרבו וכו' ומשיג על רבינו שמאחר שכל אחד מהם ספק איל נזיר צריך ליקח מכל אחד מהם זרוע בשלה ואינו נאכל אלא לכהנים ובני ביתם ונמצא שממעט באכילת זרוע של תודה שדינה ליאכל לכל אדם. ואני אומר שאם השגה זו השגה אינה על רבינו מפני שהוא העתיק דברי התוספתא אבל לפי האמת אפשר לומר דכיון שאינו ממעט באכילת כל הקרבן אלא במקצתו לא חיישינן:\",2,0],[8,365,6,10,\"כתב הראב\\\"ד ויביא בדמי היפה א\\\"א אינה טעונה לחם עכ\\\"ל. ונ\\\"ל שהשגה זו היא על\",3,0],[8,365,6,10,\"מ\\\"ש וכן אם נתערבה התודה בשאר זבחים וכו' ויביא בדמי היפה תודה אחרת וכתב על זה שאינה טעונה לחם וכ\\\"נ מדברי התוספתא ורבינו שלא הזכירו כאן לחם וצריך טעם למה לא יביא לחם בשביל התודה כשם שהוא מביא בנתערבה בתמורתה שאע\\\"פ שאין התמורה טעונה לחם מביא לחם בשביל התודה. ונ\\\"ל דלא קאי אלא אסיפא דקתני אע\\\"פ שקרבה תודתו דהשתא כיון דקרבה תודתו שוב אין כאן לחם. ומכל מקום תמיהא לי דמילתא דפשיטא היא ולא היה צריך הראב\\\"ד לכתבו ושמא י\\\"ל דאתא לאשמועינן דבבא זו אע\\\"פ שנראה ששוה סיפא דידה לרישא דידה אינם שוים לגמרי דרישא דנתערבה בשאר זבחים יביא עמה לחם וסיפא דקרבה תודתו לא יביא עמה לחם:\",4,0],[8,365,6,12,\"בכור שנתערב בפסח שניהם ירעו וכו'. בפרק מי שהיה טמא (פסחים דף צ\\\"ח) תנן הפסח שנתערב בבכורות רבי שמעון אומר אם חבורת כהנים יאכלו ובגמרא והא קא מייתי קדשים לבית הפיסול וכו' ורבנן היכי עבדינן אמר רבא ממתין לו עד שיוממו ויביא בהמה שמינה ולימא כל היכא דאיתיה לפסח תחול עליה דהאי ואכיל להו בתורת בכור בעל מום. ופירש רש\\\"י ורבנן דאמרי אין מביאין (קדשים לבית הפיסול) היכי עבדי לפסח שנתערבה בבכורות בשלמא גבי אשם שנתערב בשלמים או פסח שנתערב בעולה ואשם איכא למימר ירעו וימכרו ויביא בדמיהם אותם קרבנות וכו' אבל בכור נאמר בו לא תפדה ואין לו פדיון ואינו תופס את דמיו ואינו יוצא מקדושתו לחול על המעות אלא נאכל לכהן במומו ופסח בר פדיון הוא ואינו נאכל בלא פדיון. ממתין עד שיוממו ויביא בהמה שמינה כיפה שבהם ונימא כל היכא דאיתיה לפסח תיחול קדושתה אהנך מעות ומייתי בהנך מעות שלמים כדין מותר הפסח עכ\\\"ל:\",1,0],[8,365,6,12,\"כתב הראב\\\"ד בכור שנתערב ויאכלו כבכור א\\\"א והבכור בעל מום וכו'. ואני תמה על מה שהשיג על רבינו בכור בעל מום אי זו אכילה חמורה יש בו שאין תלונתו על רבינו דרבינו לישנא דגמ' נקט דקאמר דאכיל להו בתורת בכור בעל מום כ\\\"ש שלפי האמת אין כאן תלונה כלל שהרי פירש רש\\\"י ואכיל להו לכל התערובת בתורת בכור בעל מום ואי זו היא תורתו אינו נשחט באיטליז ואינו נמכר באיטליז ואינו נשקל בליטרא ואם היה מכיר בפסח שנפדה היה שוחטו ומוכרו באיטליז אם ירצה עכ\\\"ל. ומ\\\"ש מה תיקן לבעל הפסח והיה צריך לפרש תיקונו. י\\\"ל שרבינו סמך על מ\\\"ש בפרק רביעי מקרבן פסח:\",2,0],[8,365,6,13,\"וכן מעשר וכו'. בתוספתא דזבחים פרק שמיני:\",1,0],[8,365,6,13,\"הבכור והמעשר שנתערבו וכו'. שם ודלא כר\\\"ש:\",2,0],[8,365,6,14,\"וכן שאר קדשים וכו'. משנה בפרק התערובות (דף ע\\\"א:):\",1,0],[8,365,6,15,\"אשם שנתערבה וכו'. משנה בפרק התערובות (דף ע\\\"ה:) וכרבנן דפליגי ארבי שמעון.\",1,0],[8,365,6,15,\"ומה שכתב ואם קדם והקריב אשמו שניהם יפלו לנדבה. תוספתא פרק ח' דזבחים:\",2,0],[8,365,6,16,\"כל הקדשים אפשר וכו'. משנה בפרק התערובות (דף ע\\\"א:):\",1,0],[8,365,6,17,\"וכל אלו המתערבים וכו'. שם אמר רבא השתא דאמרי רבנן לא נקריב אי אקריב לא מרצי ואותביה ממתני' דקינים ושני הא כמאן דאמר בעלי חיים נדחים הא כמאן דאמר אינם נדחים וכיון דפסק רבינו כמאן דאמר בעלי חיים אינם נדחים כמו שנתבאר בפרק ט\\\"ו ממעשה הקרבנות ממילא קמה לה הלכתא דלא כרבא ואע\\\"ג דרבא בתרא הוא וה\\\"ל למיפסק כוותיה איכא למימר דאליבא דמאן דאמר בעלי חיים נדחים אמרה וליה לא ס\\\"ל:\",1,0],[8,365,6,18,\"בהמה שנמצאת מירושלים ועד וכו'. בפ״ז דשקלים תנן בהמה שנמצאת מירושלים ועד מגדל עדר וכו' זכרים עולות ונקבות זבחי שלמים ומייתי לה בפרק האיש מקדש (קידושין דף נ״ה) ומסיק עלה ר״י ממתין לה עד שתומם ומייתי שתי בהמות ומתנה וכו' זכרים עולות דילמא תודה היא דמייתי נמי תודה והא בעיא לחם דמייתי נמי לחם ודילמא אשם הוא אשם בן שתי שנים ואישתכח בן שנה ודילמא אשם מצורע הוא נזיר הוא לא שכיחי ודילמא פסח הוא פסח בזמנו מיזהר זהירי ביה ושלא בזמנו שלמים הוא ודילמא בכור ומעשר הוא למאי הלכתא למיכלינהו במומן ה״נ במומן מתאכלי וכו' נקבות זבחי שלמים דילמא תודה היא דמייתי תודה והא בעי לחם דמייתי נמי לחם ודילמא חטאת היא חטאת בת שנתה ואשתכח בת שתי שנים ודילמא חטאת שעברה שנתה לא שכיח אשתכח בת שנתה מאי וכו' אמר אביי (בת שנתה) כחטאת (ודאי) כונסה לכיפה והיא מתה מאליה ומשמע מדברי רבינו דכי אמרינן דמייתי תודה היינו לומר דמייתי לה ומתנה עליה ואומר אם שלמים היא הריני מקריבה לשם שלמים ואם תודה היא הריני מקריבה לשם תודה דתרווייהו קדשים קלים נינהו ומתנותיהם שוה ותאכל כחמור שבהם ליום ולילה עד חצות.\",1,0],[8,365,6,18,\"ומ\\\"ש רבינו ונסכיו משל צבור. בפ\\\"י דשקלים:\",2,0],[8,365,6,19,\"נתערבו קדשים בקדשים וכו'. נלמד ממה ששנינו במשנה בפרק התערובות שם:\",1,0],[8,365,6,19,\"נתערבו בפסולי המוקדשין וכו'. נלמד מדאיפליגו בפ' התערובות במשנה ר' אליעזר ורבנן באיברים שנתערבו באיברי בעלי מומין ופסק כרבנן:\",2,0],[8,365,6,20,\"איברי חטאת שנתערבו באיברי עולה וכו' עד ה\\\"ז ישרף בעזרה וכו'. משנה בפרק התערובות (דף ע\\\"א) פלוגתא דר\\\"א ופסק כרבנן:\",1,0],[8,365,6,21,\"ומ\\\"ש אפילו אבר באלף איברים:\",1,0],[8,365,6,22,\"חתיכות קדשי קדשים וכו'. משנה שם (דף ע\\\"ה ע\\\"ב):\",1,0],[8,365,6,23,\"חתיכה של חטאת טמאה וכו' עד סוף הפרק. ברייתא בפרק הערל (יבמות דף פ\\\"א ע\\\"ב) ופירש רש\\\"י דטעמא דקתני לא יעלו משום דאפשר למכרן לכהן בהפסד מועט:\",1,0],[8,365,7,1,\"כל הפסולים לעבודה שמלקו מליקתן פסולה וכו'. משנה בפ' חטאת העוף (זבחים דף ס\\\"ח) כל הפסולים שמלקו מליקתן פסולה ואינם מטמאות בבית הבליעה.\",1,0],[8,365,7,1,\"ומ\\\"ש וכן אם מלק בלילה וכו' עד אלא דבר שהוא כשר למזבח. שם במשנה:\",2,0],[8,365,7,4,\"ומ״ש אבל הנרבע והמוקצה וכו' עד והרי אין פיסולן בקדש. נלמד מהמשנה הנזכרת והוא מפורש בברייתא פרק המזבח מקדש (זבחים דף פ״ה:):\",1,0],[8,365,7,5,\"כבר ביארנו במעשה הקרבנות. בפ\\\"ז:\",1,0],[8,365,7,5,\"חטאת העוף שעשאה למעלה פסולה וכו' עד ובלבד שלא עלתה לבעלים לשם חובה. בפ' חטאת העוף (זבחים דף ס״ו) ודקדק רבינו לכתוב בחטאת העוף ושעשה הזייתה משום דאילו מליקתה בכ״מ כשירה כמו שמפורש שם ע״ב בגמ':\",2,0],[8,365,7,9,\"כל אלו העופות שנפסלו מפני מקום עשייתן וכו' עד שכל אלו פיסולן בקדש. נלמד מהמשנה שהזכרתי בר\\\"פ זה:\",1,0],[8,365,7,10,\"חטאת העוף הבאה וכו'. מתבאר ממה שיבא בסמוך:\",1,0],[8,365,7,10,\"וכיצד תבא על הספק וכו'. פשוט הוא.\",2,0],[8,365,7,10,\"ומ\\\"ש ואין לנו חטאת בהמה על ספק וכו'. ג\\\"ז פשוט. ומ\\\"כ שדקדק רבינו לכתוב כגון שהיתה ספק זבה או ספק יולדת מפני שאינן יכולות לאכול בקדשים עד שיביאו כפרתן ולכך התירו להן להביא ספק חולין לעזרה אבל ספק מטמא מקדש לא התירו לו להביא ספק חולין לעזרה:\",3,0],[8,365,7,11,\"חטאת העוף הבאה על הספק וכו'. משנה בכריתות פ' דם שחיטה (כריתות דף כ״ב:) האשה שהביאה חטאת העוף ספק אם עד שלא נמלק נודע לה שילדה ודאי תעשנה ודאי שממין שהיא מביאה על לא הודע מביאה על הודע. ובפרק המביא אשם תלוי (דף כ״ו:) אתמר עלה אמר רב מזה דמה וממצה דמה וכיפרה ומותרת באכילה ור״י אמר אסורה באכילה גזירה שמא יאמרו חטאת העוף הבאה על הספק נאכלת ופירש״י האשה שהביאה וכו' ועלה קאי רב ואמר אם משנמלקה נודע לה כן שילדה ודאי מזה וכו' תניא כוותיה דר״י חטאת העוף הבאה על הספק אם עד שלא נמלקה נודע לה שלא ילדה תצא לחולין או תמכר לחברתה אם עד שלא נמלקה נודע לה שילדה ודאי תעשה ודאי שממין שמביאה על לא הודע מביאה על הודע אם משנמלקה נודע לה שילדה אסורה ופסק כר״י ואע״ג דתני לוי כוותיה דרב ברייתא דתני סתם גמרא עדיפא מינה וגם מתניתין בפרק דם שחיטה דקתני אם עד שלא נמלקה וכו' כר״י דייקא דלרב ה״ל למיתני אם עד שלא הזה:\",1,0],[8,365,7,12,\"ומה שכתב נודע לה שאינה חייבת בה מאחר שנמלקה ה\\\"ז תקבר. משנה בפרק המביא אשם תלוי:\",1,0],[8,365,8,1,\"חטאת העוף שנתערב בעולת העוף וכו'. פ\\\"ק דקינים ופירש\\\"י אחד בריבוא ימותו כולם דבכל אחת איכא לספוקי שמא עולה היא ופסולה למטה או שמא חטאת ופסולה למעלה:\",1,0],[8,365,8,1,\"בד\\\"א כשהיו מפורשות בשעת לקיחת הבעלים וכו':\",2,0],[8,365,8,4,\"וכיצד דיניהם אם נתערבה חטאת בחובה זו הסתומה וכו'. וכן אם נתערבו עולה בחובה זו הסתומה וכו'. שם ופירש\\\"י חובה קרי קן שלם של יולדת או של זבה והוא אחת חטאת ואחת עולה וכו' ואם פרידה המופרשת לחטאת מעורבת עם ב' קינים של חובה שהם סתומים ועתה חמש פרידים מעורבין יחד אין יכול לעשות אלא שתים חטאת שזהו מנין הכשר בשני קינין של חובה דאי עבד ג' חטאות שמא משני קינין עבד להו ולא מהמעורב בהם ומב' קינים אינו יכול לעשות רק ב' חטאות ולא מצי עביד אפי' אחת עולה שמא יקח החטאת המעורבת וכן עולה שנתערבה בחובה בקן סתומה אין כשר אלא שנתערבה זו בזו אחת לזו ואחת לזו שתים לזו ושתים לזו שלש לזו ושלש לזו מחצה כשר ומחצה פסול אחת לזו ושתים לזו ושלש לזו ועשר לזו ומאה לזו הממועט כשר. ופירש\\\"י אבל חובה שנתערבה זו בזו קן סתומה של לידה שהוא אחד חטאת ואחד עולה ונתערבו השני פרידין בקן אחת סתומה של לידה או של זיבה מאשה אחרת מחצה כשר ומחצה פסול יכול להקריב שני פרידין אחד עולה ואחד חטאת ולא יותר דאי עבד שני עולות שמא יעשה אותן מקן אחד של לידה או של זיבה וכן אם נתערבו הרבה קינים יחד יקריב חציו אחד חטאת ואחד עולה וחציו האחר פסולים והיינו כי נתערבו בשוה כדאמרינן אחת לזו ואחת לזו או שתים לזו ושתים לזו או שלש לזו ושלש לזו שיכול ליקח השלשה קינים אי זה שלש פרידים שירצה אי זה לחטאת ואי זה לעולה אבל אחד לזו ושנים לזו ושלש לזו ועשר לזו ומאה לזו הממועט כשר. אם נתערבו קן חטאת סתומה של זיבה בשני קינים של לידה או בשלשה אינו יכול להקריב אלא קן אחד פרידה אחת לחטאת ופרידה אחת לעולה אבל שתי עולות לא מצי עביד פן יקח הקן שהוא מבורר תחלה ללידה אחת שאינו יכול להקריב ממנו רק אחת חטאת ואחת עולה וכן אם נתערבו כולם יחד האחת והשתים והשלש והעשר לא יוכל להקריבו רק קן אחד שני פרידים או עשר קינים במאה יקריב עשרים פרידים כמו שיכול לעשות מעשר קינים וזהו המועט כשר. בין משם אחד לידה ולידה משתי נשים בין שני שמות לידה וזיבה אפי' מאשה אחת כדמפרש (במתני') כיצד משם אחד. וז\\\"ל רבינו בפירוש המשנה אומר כי מה שהקדים לומר אין כשר אלא מנין עולות שבחובה אינו אלא אם נתערבו קינים נדבה שהם עולות כולם בקיני חובה שחציין עולות וחציין חטאות אבל חובה שנתערבה בחובה וכו' שאם היו שוות אלו כנגד אלו יהא המחצית כשר והמחצית פסול בהכרח באי זה צד שעשאן וכו' ויהיה שוה בזה כהן נמלך ר\\\"ל ששואל לאשה אי זה יעשה חטאת ואי זה יעשה עולה וכהן שאינו נמלך אלא שהדבר מסור לו אבל אם היה מנין אחת משתיהן יותר ממנין האחרת [הרי יש בזה חילוק והוא] שאם עשה הכל למעלה או למטה המחצית כשר והמחצית פסול בהכרח וכו' ואם עשה החצי למעלה והחצי למטה וכו' המועט אז כשר ע\\\"מ שיהא נמלך ולא יהיה מסור לו לעשות עולה מה שירצה וחטאת מה שירצה הרי בעלת המנין המועט אומרת לו שזה המחצית שנעשה למעלה בו נבלעה עולה שלי לפי שהוא המועט והמחצית שעשית למטה בו נבלעה חטאת שלי לפי שהוא ג\\\"כ המועט ואני לא מסרתי הדבר אליך ולא הרשות עכ\\\"ל:\",1,0],[8,365,8,6,\"עשה חציין למטה וחציין למעלה אם אחר ששאל עשה כן המועט כשר וכו' זה הכלל כל שעשה הכהן מדעתו וכו'. שם בפ\\\"ג בד\\\"א בכהן נמלך אבל בכהן שאינו נמלך אחת לזו ואחת לזו שתים לזו ושתים לזו שלש לזו ושלש לזו עשה כולן למעלה מחצה כשר ומחצה פסול כולם למטה מחצה כשר ומחצה פסול חציין למעלה וחציין למטן את שלמעלה מחצה כשר ומחצה פסול ואת שלמטה מחצה כשר ומחצה פסול אחת לזו ושתים לזו ושלש לזו ועשר לזו ומאה לזו עשה כלן למעלה מחצה כשר ומחצה פסול כולם למטה מחצה כשר ומחצה פסול חציין למעלה וחציין למטה המרובה כשר זה הכלל כ\\\"מ שאתה יכול לחלוק את הקינים ולא יהו משל אשה אחת בין למעלה בין למטה מחצה כשר מחצה פסול וכ\\\"מ שאי אתה יכול לחלוק את הקינין עד שיהיו משל אשה אחת בין למעלה בין למטה המרובה כשר. ופירש המפרש בד\\\"א בכהן נמלך אפירקא קמא קאי והכי קאמר בד\\\"א דחטאת שנתערבה בעולה ועולה בחטאת אפי' אחת בריבוא ימותו כלם וכן אחת לזו ושתים לזו ושלש לזו דמועט כשר כל אלו הדינין בכהן נמלך כלומר לכתחלה נמלך הכהן איך משפטן אבל בכהן שאינו נמלך ועשה הכל מדעתו בדיעבד ועשה קן שלם למעלה לאשה אחת וכן קן שלם לאשה אחת הילכך כולם למעלה מחצה כשר עולות ומחצה פסול חטאות וכן למטה בענין זה וכן משמע בריש פרק התערובות דהאי בד\\\"א אפרקין קמא קאי. וז\\\"ל רבינו בפירוש המשנה זה שהוציא מן הכלל הוא שב על הלכה רביעית מהפרק הראשון שאמר המועט כשר אמר שאין זה אלא בכהן נמלך אם עשה חציין למעלה וחציין למטה אבל כהן שאינו נמלך אלא עושה לרצונו למעלה ולמטה כשר המרובה והוא מגיד מאי זה טעם יהיה כן ואמר שכל זמן שאפשר לחלק הכלל המעורב ואין מעופות האשה האחת בשני החצאין יחד הרי כשעשה חציין למטה וחציין למעלה מחצה כשר ומחצה פסול לפי שאנו אומרים אפשר שעופות של אחת היו כולן למעלה או למטה שחציו לעולם כשר וזה אפשר לעולם כל זמן שיהיה מנין כנגד מנין (הנה הכל אפשר) לחלק בשני חצאין ומקריבין החצי למעלה והחצי למטה ושלא יהיו מקצת העופות שהקריבו למעלה ומקצת מה שהקריבו למטה משל אשה אחת ואז המחצית שנעשה באחד משני הצדדין וכל זמן שא\\\"א לחלק הכלל המעורב ולעשות חציו למעלה וחציו למטה אלא שעופות האחת כבר נעשה מהם למעלה ולמטה הרי הרוב כשר לפי שבעלת הרוב היא שנעשה מעופות שלה למעלה [ולמטה] בהכרח וא\\\"א זה אלא כשיהיה מנין זו יותר ממנין זו עכ\\\"ל. והראב\\\"ד כתב על דברי רבינו עשה חציין למטה א\\\"א זה כתב בשביל שראה במשנה רפ\\\"ג וכו' עד וממעט בהשלמת חובתה. ונ\\\"ל להגיה ולכתוב במקום חבירותיה חבירתה כלומר אותה שנתערב קינים עמה. וטעם רבינו לחלק בין נמלך לשאינו נמלך נתכוון רבינו לבאר בפירוש המשנה שכתבתי בסמוך ואין דבריו מובנים לי:\",1,0],[8,365,8,8,\"שנים שלקחו קיניהם בעירוב וכו'. שם בשם ר' יוסי.\",1,0],[8,365,8,8,\"ומ״ש שאין הקינין מתפרשים וכו' כמו שביארנו. הוא בפ״ה ושם נתבאר ואע״ג דבפ' בכל מערבין (עירובין דף ל״ו) בעי לאורויי מהכא דרבי יוסי סבר יש ברירה ומוקי לה בשהתנו ורבינו פוסק דבדאורייתא אין ברירה וכיון שכן קשה על רבינו שהיה לו לומר דבשהתנו מיירי. וי״ל דאמרינן עלה א״ה מאי למימרא קמ״ל כדרב חסדא דאמר אין הקינין מתפרשות אלא או בלקיחת בעלים או בעשיית כהן ומפרש דהשתא דקמ״ל כדרב חסדא אין צריך להתנות אלא אע״ג דלא התנו כהתנו דמי:\",2,0],[8,365,8,9,\"היו לפני הכהן חטאות ועולות וכו' עד סוף הפרק. בפ' ג' דקינים חטאת לזו ועולה לזו עשה כולן למעלה מחצה כשר ומחצה פסול וכו' ואם תאמר והא תנן חטאת שנתערבה בעולה אפי' אחד בריבוא ימותו כולם. וי\\\"ל שאין כאן תערובת כלל אלא כל קן היה בפני עצמו וכל אחד הקריב בפני עצמו אלא שטעה הכהן בהקרבתן וכשהקריב חציין וחציין יודע היה ואח\\\"כ שכח ומסופק אם טעה אם לא. זה דעת רבינו בפירוש המשנה:\",1,0],[8,365,8,10,\"היו לפניו ג' צבורי עופות וכו'. ג\\\"ז שם ופירש רבינו במשנה זו על דרך שכתבתי שפירש במשנה שקודם זו שלא היה כאן תערובת כלל וע\\\"ש:\",1,0],[8,365,9,1,\"קן סתומה שפרח ממנה גוזל לאויר וכו'. בפרק ב' דקינים וכתב רבינו שם דע כי (כל) מה שנאמר בכל הלכות אלו חזר אינו ר\\\"ל שחזר אותו העוף בעצמו לפי שכל זמן שיהא כן אין שם הפסד כל עיקר אבל ר\\\"ל כשאמר וחזר שמאחר שפרח לכת ראשונה והרי אפשר שהוא הראשון בעצמו שחזר לחבורתו או הוא עוף אחר:\",1,0],[8,365,9,5,\"ומ\\\"ש והשלישית יש לה שני עופות והרביעית יש לה ארבעה והחמישי' יש לה ששה והששית יש לה שמנה והשביעית יש לה י\\\"ב. במשנה [שם] שנינו השלישית יש לה אחת הרביעית שתים החמישית יש לה שלש הששית יש לה ארבע השביעית שש. והענין דבמתני' נקט מנין הקינים וכל קן זוג אחד ורבינו נקט מנין הפרידין והיינו דנקט בלישניה עופות וע\\\"ד זה תקיש ותדין בשאר. וע\\\"ש בפירוש המשנה לרבינו ותמצא הכל מבואר:\",1,0],[8,365,9,6,\"קן סתומה וקן מפורשת וכו'. גם זה שם:\",1,0],[8,365,9,7,\"חטאת מכאן ועולה וסתומה באמצע וכו' עד סוף הפרק. שם:\",1,0],[8,365,10,1,\"האשה שאמרה הרי עלי קן כשאלד זכר וכו' עד סוף הפרק. בפ' ד' דקינים ואיתא בפרק חטאת העוף (זבחים ס\\\"ז:):\",1,0],[8,365,10,1,\"כתב הראב\\\"ד בד\\\"א כשהביאה וכו' עד ושתים למטה א\\\"א ולא ידע הכהן אי זה מין עשה למטה ואי זה מין עשה למעלה עכ\\\"ל. ואני אומר שזה פשוט הוא ובכלל לא ידע אי זה מהן עושה למעלה הוא:\",2,0],[8,365,10,3,\"פירשה נדרה ואמרה לכהן אלו לנדרי וכו' ויעשו השלשה למעלה. תיבת השלשה צריך למחוק ולכתוב במקומה\",1,0],[8,365,10,3,\"השנים וכן מ\\\"ש\",2,0],[8,365,10,3,\"אצל קבעה נדרה ואמרה אם אלד זכר וכו' שכבר עשה שנים למטה שהם חטאת שש תיבות אלו נראה שהם שיבוש וצריך למוחקם:\",3,0],[8,365,10,3,\"כתב הראב\\\"ד בד\\\"א כשהביאה הארבעה בתחלה וכו' עד וכן אם. א\\\"א דבריו מבולבלים וכו'. והר\\\"י קורקוס ז\\\"ל כתב וז\\\"ל כתב רבינו במשנה ענין קבעה שפירשה (בשעת נדרה) מין פלוני ותביא אותו לכהן עם חובתה ועשה שתים למטה ושתים למעלה ולא ידע אם הנדר נעשה למעלה או למטה וגם היא נסתפק לה איזה משני המינים קבעה בו נדרה אם התורים או בני יונה וזה הוא ההפרש שיש בין קבעה לפירשה שפירשה הוא שתאמר בשעת הבאת נדרה וחובתה אלו לנדרי ואלו לחובתי וקבעה נדרה הוא שתאמר בשעת הנדר הרי עלי קן ממין פלוני והוא מדבר כאן במי שקבעה נדרה והביאה אותו ואח\\\"כ שכחה מאיזה מין קבעה אבל ודאי אצלה שהוא קבוע עכ\\\"ל בספר מוגה. ונראה שבבא זו מדברת שאינה יודעת אי זה מין הם הד' פרידים שנתנה לכהן אבל מ\\\"מ יודעת היא שהם מין אחד שאם יודעת אי זה מין הוא שנתנה א\\\"א להסתפק באי זה מין קבעתו שהרי נדרה נתנה. וזה נראה מוכרח וביארו רבינו במשנה וז\\\"ל וזה אם היו הארבעה מין אחד והיה ודאי אצלה שנתנה לכהן מין ולא ידעה מאי זה מין הוא גם כתב שאין אנו יודעים מאי זה מין הוא הארבעה שנולד בהם הספק ע\\\"כ. והוא מוכרח וע\\\"פ הקדמה זו הדבר ברור שלא נפטרה מספק נדרה כלל וצריכה להביא ד' לנדרה שתי תורים ושני בני יונה. אבל קשה טובא איך יספיק אחד לתשלום חובתה והרי אינה יודעת מאי זה מין היה החטאת ואם תביא תור שמא היה בן יונה או להפך וכבר נתבאר שצריך חטאת ועולה ממין אחד ובמשנה כתב ותביא גוזל אחד תור או בן יונה להשלים חובתה והצריכו תור או בן יונה לפי שאין אנו יודעים מאיזה מין היו הארבעה וכו'. ודברים אלו צריכים ביאור וכפי הכתוב בספרים שהגוזל הוא לעולה א\\\"א ליישבו שהרי גבי פירשה חייבת להביא כל החובה מספק לפי שאינה יודעת מאי זה מין היו העולות שתביא חטאתה מאותו המין ומה לי אם היו שני מינים או מין אחד ואינה יודעת אי זה מין היה הכל ספק אחד הוא. ואפשר לפרש כוונת רבינו ביודעת איזה מין נתנה לכהן אלא ששכחה באיזה מין קבעה נדרה וד\\\"מ נתנה תורים ונסתפקה שמא בני יונה פירשה ושלא כדין נתנה לכהן תורים ואם היו יודעים שמה שנתנה לנדרה נעשו למעלה לא היה נשאר עליה מספק נדרה אלא שני בני יונה ובהם נפטרה מנדרה ועתה שמא מה שנתנה לנדרה עשו למטה ונמצא כל ספיקה עליה לכך מביאה שתי תורים ושני בני יונה וכולם למעלה בספק נדרה ומחובתה תביא גוזל אחד כי מעולה אחת נפטרה בתורים ראשונים ממ\\\"נ אם שלמעלה היו נדרה הרי לא היתה צריכה להביא אלא שני בני יונה לתשלום נדרה ומהשני תורים שמביאה עתה אחד יעלה לחובתה והאחר פסול וצריכה חזרה לחטאת לתשלום חובתה ואינה צריכה יותר ואם שנים ראשונים היו נדרה הרי שלמעלה היו חובתה והרי נפטרה מהעולה בראשונים ונמצא לפי זה שממ\\\"נ צריכה להביא גוזל אחד לחטאת ממין הראשונים.\",4,0],[8,365,10,3,\"ומ\\\"ש בספרי רבינו גוזל אחד למעלה. מ\\\"כ שהוא טעות ובמשנה כתב בפירוש תביא תור ובן יונה ותעשה חטאת ממ\\\"נ והוא הנשאר מחובתה. והשתא דאתינא להכי שהכרחתי שהאחד הוא חטאת י\\\"ל שתקריב מאיזה מין שתרצה ויוצאה ממ\\\"נ שאם תביא תור כשר ממ\\\"נ אם הראשונים היו תורים א\\\"כ הנדר היו תורים ואם קרבו למעלה הרי נפטרה והשתי תורים אחרונים יעלה אחד מהם לחובתה והרי תור לחטאת ויצאה ידי חובתה ואם קרבו למטה הרי יצאה מידי עולת חובה באחד מתורים ראשונים של מעלה ותורים שניים לנדרה והרי תור לחטאת ואם היו בני יונה א\\\"כ הנדר היה בני יונה ובבני יונה אחרונים ממ\\\"נ יצאה ונמצא תורים שניים עולה אחד מהם לחובתה וכן כשמביאה בני יונה יוצאה ממ\\\"נ על הדרך שנתבאר כי ידוע כי מין שהביאה נדרה. ובהשגות א\\\"א דבריו מבולבלים וכו'. ובודאי כי הלשון סתום ומוטעה כאשר הכרחתי ולא פירשה איזה מין נתנה לכהן וצריך לתקן כאשר כתבתי וילמוד סתום אשר כאן ממפורש במשנה. וכתב עוד אבל וכו'. טעם בבא זה מבואר שכיון שהראשונים שני מינים ואינו יודע מה עשה למעלה ומה עשה למטה א\\\"א שיועיל דבר לנדרה כי שמא נדרה קרב למטה ולא לחובתה כי אינו יודע איזה מין למעלה ואיזה למטה ואנן בעינן עולה וחטאת מין אחד ולכך מביאה הכל. וצריך לדעת כי גם בבא של קבעה מיירי לשיטת רבינו כשפירשה אלו לנדרי דאל\\\"כ איך שייך לומר ולא ידע איזו עשה וכו' כיון שהכל מין אחד מה שייך לומר כן גם אין שייך לומר שמא הנדר עשה למטה שכתב במשנה אלא דודאי היא ייחדה אשר לנדרה אלא שלא אמרה כן לכהן כמו בפירשה והיא שכחה ומ\\\"מ בשנים שמביא מקריב סתם ולכך שייך ממ\\\"נ שנתבאר. ואפשר שלא ידע שכתב רבינו מפני בבת שני מינים נקט לה ולעולם לא ייחדה. אלא שלשון המשנה אינו מוכיח כן גם הענין נראה שהוא כאשר כתבתי:\",5,0],[8,365,10,3,\"וכתב\",6,0],[8,365,10,3,\"עוד וכן אם נתנתם וכו'. טעם בבא זו מבואר כי לא עולה לה דבר מחמת הספק לכך תביא כל חיובה וחלוקה זו לא הוזכרה במשנה אמנם אמרו שם נתנתם לכהן ואינה יודעת מה נתנה ועשה הכהן ואין ידוע מה עשה צריכה להביא ד' פרידים לנדרה ושתים לחובתה וחטאת א' בן עזאי אומר שתי חטאות והוקשה לרבינו חטאת זה למה כיון שהביאה כל חובתה ולכך פירשה דקבעה גם חובתה ולא ידעה מה קבעה ולפ\\\"ז הוצרך להוסיף כבש אע\\\"פ שלא הוזכר שכיון שקבעה ולא ידעה מה קבעה מביאה קן מאיזה מין שתרצה וכבש ופרידה וא\\\"ת וניחוש דילמא חובתה בתורים או בבני יונה ולמה תפטר בקן מאיזו מין שתרצה ונראה דלהא לא חיישינן כי אין דרך לפרש לחיובה תורים או בני יונה רק קרבן עני או קרבן עשיר עכ\\\"ל.\",7,0],[8,365,10,3,\"ומ\\\"ש ששני פרידין שבהן צריך שיהיו ממין אחד נלמד בספרא מדכתיב שתי תורים וכו' אחת לעולה ואחת לחטאת ממין שיביא עולה יביא חטאת:\",8,0],[8,365,10,5,\"ומ\\\"ש וכל החטאות האלו אינן נאכלות מפני שהן ספק. פשוט הוא בסוף תמורה (דף ל\\\"ד) חטאת העוף הבאה על הספק תשרף:\",1,0],[8,365,11,1,\"כל המנחות שקמצן אחד מהפסולים לעבודה הרי הן פסולים. משנה בפ\\\"ק דמנחות (דף ו').\",1,0],[8,365,11,1,\"ומ\\\"ש וכן אם לקט הלבונה פסל אע\\\"פ שלא קמץ. ברפ\\\"ב (דף י\\\"ג:) מימרא דר' ינאי ופירש\\\"י ליקוט לבונה דלאחר הקטרת הקומץ היה מלקט [הלבונה] מעל הסולת ומקטירו:\",2,0],[8,365,11,2,\"קמץ הכשר ונתן לפסול וכו'. בפ״ג דזבחים (דף ל״ב) תנן קיבל הכשר ונתן לפסול יחזיר לכשר קיבל בימינו ונתן לשמאלו יחזיר לימינו קיבל בכלי קדש ונתן לכלי חול יחזיר לכלי קודש ופריך בגמרא (דף ל״ד:) ולהוי דחוי ואסיקנא כל שבידו לא הוי דחוי ומדין זבחים יש ללמוד למנחות. וא״ת אמאי לא תנא רבינו בהו תקנתא כדתנן במתני' שכתבתי בסמוך לענין קבלת דם. וי״ל משום דאיתא בתוספתא דמנחות פ״ה קמץ הכשר ונתן לפסול יחזיר לכשר וכו' קמץ בימינו ונתן לשמאלו יחזיר לימינו וכו' בכלי קדש ונתן לכלי חול יחזיר לכלי קדש וכו' דברי ר' אלעזר ור״ש וחכ״א קמץ הכשר ונתן לפסול פסלתו מתנתו קמץ בכלי קדש ונתן לכלי חול פסלתו מתנתו קמץ בימינו ונתן לשמאלו פסלתו מתנתו וידוע דהלכה כחכמים. ואם תאמר ולחכמים מאי שנא קמיצה מדם וי״ל דבפרק הקומץ רבה (מנחות דף כ״ו:) מייתי מאי דתני בהאי תוספתא וחכ״א כיון שנתנו לשמאל פסלתו מתנתו וקאמר עלה בגמ' מ״ט משום דבעי לקדושי בכלי וכיון שנתן לשמאל נעשה כדם שנשפך מצואר בהמה על הרצפה ואספו שפסול. ופירש רש״י פסלתו מתנתו (מה שנתן בשמאלו) ושוב אין לו תקנה בחזרה מאי טעמא משום דבעי לקדושי בכלי וכו' ואספו שפוסל עוד להקדישו בכלי דאי לא הוי עוד האי קומץ קידוש כלי לא הוה מיפסל דהוה כדם שנשפך מן הכלי על הרצפה שכשר אבל מאחר דבעי כלי לית ליה תקנתא בחזרה כדפרישית דהוה ליה כנשפך על הרצפה מן הצואר שפסול דנפקא לן מולקח מדם הפר דם מהפר יקבלנו וקידוש קומץ במקום קבלת דם ושמאל בלא כלי הרי היא כרצפה עכ״ל:\",1,0],[8,365,11,3,\"קמץ ועלה בידו צרור או גרגיר מלח או קורט לבונה פסול. משנה בפירקא קמא דמנחות (דף י':):\",1,0],[8,365,11,4,\"קמץ עד שהוא בחוץ ונכנס לפנים וכו'. תוספתא פ\\\"ה דמנחות. ומה שצריך קמיצה בפנים איתיה בפ\\\"ק דמנחות. ופירוש בפנים כל העזרה:\",1,0],[8,365,11,5,\"נתפזר הקומץ על גבי הרצפה יחזור ויאספנו. תוספתא פ\\\"ה דמנחות. מ\\\"כ מ\\\"ש נתפזר הקומץ על הרצפה יחזור ויאספנו מיירי שנתפזר אחר שנתנו לכלי שרת אבל אם קמץ ונפל מידו לארץ פסול כמו שהוא דין הדם:\",1,0],[8,365,11,6,\"היתה המנחה שלא בכלי שרת וכו'. בפ' הקומץ רבה (מנחות דף כ״ו) תניא חכמים אומרים קומץ טעון כלי שרת כיצד קמצו מכלי שרת ומקדשו בכלי שרת ומעלו ומקטירו בכלי שרת:\",1,0],[8,365,11,6,\"ומה שכתב או שבללה בשמנה חוץ לעזרה פסולה וכו'. בפירקא קמא דמנחות (דף ע') אתמר בללה חוץ לחומת העזרה רבי יוחנן אמר פסולה ריש לקיש אמר כשירה וידוע דהלכה כרבי יוחנן ועוד דתניא כוותיה ומפרש בגמרא טעמא דרבי יוחנן אף על גב דבלילה כשרה בזר כיון דעשייתו בכלי היא אף על גב דכהונה לא בעיא קדושת פנים מיהת בעיא:\",2,0],[8,365,11,7,\"כל המנחות שיצק עליהם השמן פסול לעבודה וכו'. בפרק הקומץ רבה (מנחות דף י״ח) תנן לא יצק לא בלל ולא פתת ולא מלק ולא הניף לא הגיש וכו' כשירה ובגמ' מאי לא יצק אילימא לא יצק כלל עיכובא כתיב בה אלא לא יצק כהן אלא זר אי הכי לא בלל נמי לא בלל כהן אלא זר הא לא בלל כלל פסולה והתנן ששים נבללין ששים ואחד אין נבללין והוינן בה כי אין נבללין מאי הוי והא תנן לא בלל כשירה ואמר ר' זירא כל הראוי לבילה אין בילה מעכבת בו וכל שאינו ראוי לבילה בילה מעכבת בו מידי איריא הא כדאיתא והא כדאיתא לא יצק לא יצק כהן אלא זר לא בלל לא בלל כלל ובתר הכי אמרינן מתני' (דמכשיר יציקה בזר) דלא כר״ש (דאמר יציקה ובלילה ופתיתה ומליחה בעו כהן) מ״ט דרבנן אמר קרא ויצק עליה שמן ונתן עליה לבונה והביאה אל בני אהרן הכהן מקמיצה ואילך מצות כהונה לימד על יציקה ובלילה שכשירה בזר.\",1,0],[8,365,11,7,\"ומ\\\"ש רבינו הגישן או הניפן חוזר הכהן ומגיש או מניף. ומ\\\"ש ואם לא הגיש ולא הניף הכהן כשירות וכו'. נתבאר בסמוך:\",2,0],[8,365,11,8,\"מנחה שנפל לתוכה שמן מנחה אחרת וכו'. בפ' ראשון דמנחות (דף י\\\"א) תנן ריבה שמנה חיסר שמנה וכו' פסולה ובגמ' היכי דמי ריבה שמנה א\\\"ר אלעזר כגון שהפריש לה שני לוגין ולוקמה כגון דעריב בה שמן דחולין ושמן דחבירתה וכו' ר\\\"א לא מיבעיא קאמר לא מיבעיא דחולין ודחבירתה דפסיל אבל הפריש לה שני לוגין הואיל והאי חזי ליה והאי חזי ליה אימא לא ליפסיל קמ\\\"ל:\",1,0],[8,365,11,8,\"חיסר לבונתה כשירה וכו'. שם במשנה חיסר לבונתה פסולה ובגמ' ת\\\"ר חסרה ועמדה על קורט אחד פסולה על שני קורטים כשירה דברי ר' יהודה ר\\\"ש אומר על קורט אחד כשירה פחות מכאן פסולה וכו' א\\\"ר יצחק בר יוסף א\\\"ר יוחנן ג' מחלוקת בדבר דר\\\"מ סבר קומץ בתחלה וקומץ בסוף. ופירש\\\"י ר\\\"מ סתם מתני' דקתני חיסר לבונתה פסולה ופסק רבינו כר' יהודה וצריך ליתן טעם למה לא פסק כסתם מתני' ואפשר שטעמו משום דר\\\"י ור\\\"ש פליגי עליה והו\\\"ל ר\\\"מ יחידאה לגבייהו ולא חיישינן לסתמא כיון דרבים פליגי עליה ובפלוגתא דר\\\"י ור\\\"ש ידוע דהלכה כר\\\"י וא\\\"ת כיון דסתם רבי כר\\\"מ הוה ליה למיפסק כוותיה י\\\"ל דכיון דלא אשכחן בברייתא דפליגי אלא ר\\\"י ור\\\"ש טפי הוה עדיף לפרושי מתני' אליבא דר\\\"י דהלכתא כוותיה לגבי ר\\\"ש מלאוקומי לה בפלוגתא תליתאה ור\\\"י דאמר ג' מחלוקות בדבר בעא לדיוקי לישנא דחסר לבונתה דמשמע אפי' חיסר כל שהוא. ואינו מוכרח. ועוד דמדר\\\"י נשמע דס\\\"ל דהלכה כר\\\"י מדאמר ג' מחלוקות בדבר ר\\\"מ ור\\\"י ור\\\"ש בידוע דהלכה כר\\\"י לגבייהו דאל\\\"כ לא הל\\\"ל הכי אלא אמתני' דחיסר לבונתה הול\\\"ל א\\\"ר יוחנן אפילו חיסר כל שהוא:\",2,0],[8,365,11,9,\"ריבה שמנה ולבונתה וכו'. שם בגמרא אמתני' דחיסר לבונתה פסולה הא יתיר [כשירה והתניא יתיר] פסולה אמר רמי בר חמא כגון שהפריש לה שני קמצים ומשמע לרבינו דכי אמר ר' אלעזר גבי ריבה שמנה כגון שהפריש לה שני לוגין שני לוגין דוקא קאמר ויגיד עליו רעו יתיר לבונתה דלא מיפסיל בפחות משני קמצים ולא כדפירש\\\"י שכתב אהא דאמרינן ולוקמה כגון דעריב שמן דחולין וכו' ולוקמה כגון דעריב ביה פורתא שמן דחול וכו':\",1,0],[8,365,11,10,\"מנחת חוטא שנתן עליה שמן וכו'. בפ' כל המנחות באות מצה (מנחות דף נ״ט:) וחייב על השמן בפני עצמו ועל הלבונה בפני עצמה נתן עליה שמן פסלה לבונה ילקטנה.\",1,0],[8,365,11,10,\"ומ\\\"ש או על הקומץ שלה. ומ\\\"ש היתה שחוקה ה\\\"ז פסולה מספק וכו'. שם בעא רבה בר רב הונא מר\\\"י נתן עליה לבונה שחוקה מהו משום דאפשר ללוקטה והא לא אפשר ללקטה או דילמא משום דלא מיבלעא והא נמי לא מיבלעא ובתר הכי אמרינן מאי הוי עלה אמר ר\\\"נ בר יצחק תניא מנחת חוטא ומנחת קנאות שנתן עליה לבונה מלקט את הלבונה וכשירה וכו' ופירש\\\"י אלמא מדקאמר כל זמן שלבונה בתוכה פסולה היא ש\\\"מ בלקיטה תליא מילתא. ורבינו שכתב מספק צ\\\"ל דלא גריס מאי הוי עלה וברייתא דמייתי ר\\\"נ בר יצחק מילתא באפי נפשה היא דמייתי לה לאקשויי עלה ואמאי פסלה במחשבה דחוי הוא ואינה ענין לבעיא דילן:\",2,0],[8,365,11,11,\"נתן שמן על שיריה וכו'. שם במשנה:\",1,0],[8,365,11,12,\"נתן משהו שמן ע\\\"ג כזית מן המנחה וכו' עד פסל עד שילקט. שם א\\\"ר יצחק בר יוסף א\\\"ר יוחנן נתן משהו שמן ע\\\"ג כזית מנחה פסל מ\\\"ט לא ישים שימה כל דהו עליה עד דאיכא שיעורא וא\\\"ר יצחק בר יוסף א\\\"ר יוחנן נתן כזית לבונה ע\\\"ג משהו מנחה פסל מ\\\"ט לא יתן כתיב עד דאיכא נתינה עליה הוי ריבוי אחר ריבוי ואין ריבוי אחר ריבוי אלא למעט ואיכא דאמרי א\\\"ר יצחק בר יוסף בעי ר' יוחנן נתן משהו שמן ע\\\"ג כזית מנחה מהו מי בעינן שימה כנתינה או לא תיקו. ופירש\\\"י בלבונה כתיב נתינה ונתינה בכזית כדכתיב ונתן לכהן את הקדש ובההיא נתינה כתיב אכילה וכל אכילה בכזית. עליה משמע דבמנחה בעינן כזית הוי ריבוי אחר ריבוי דגבי שמן כתיב עליה דהיינו כזית וגבי לבונה עליה הוי ריבוי אחר ריבוי ואינו אלא למעט דגבי לבונה לא בעינן כזית מנחה דעל משהו נמי חייב:\",1,0],[8,365,11,14,\"גבלה במים וקמץ כשירה וכו':\",1,0],[8,365,11,15,\"מנחה שקמצה פעמים כשירה וכו'. בפ' הקומץ רבה (מנחות דף כ״ו) תנן הקטיר קמצה פעמים כשירה ובגמרא אמר ריב״ל פעמים ולא פעמי פעמים ור״י אמר פעמים ואפילו פעמי פעמים מאי בינייהו א״ר זירא יש קומץ פחות משני זיתים ויש הקטרה פחותה מכזית ריב״ל סבר אין קומץ פחות משני זיתים ואין הקטרה פחותה מכזית ור״י סבר יש קומץ פחות משני זיתים ויש הקטרה פחותה מכזית ופסק כריב״ל לגבי ר״י כמו שכתבו התוס' בפ' בני העיר (מגילה דף כ״ז בד״ה כוותיה דרב פפי) ומשמע דלרבינו ה״פ ריב״ל סבר אין קומץ פחות משני זיתים ומשום הכי קתני מתני' הקטיר קומצה פעמים כלומר שהקטיר בכל פעם חצי קומץ דהיינו כזית כשירה אבל אם הקטיר קומצה בפעמי פעמים דהיינו שיקטיר בכל פעם פחות מכזית פסולה דאין הקטרה פחותה מכזית ולפי זה אם היה הקומץ גדול שיש בו כמה זיתים אפי' הקטירו בכמה פעמים כשירה והוא שלא יהא בכל קומץ פחות מכזית:\",1,0],[8,365,11,16,\"הקריב הקומץ בלא מלח פסולה וכו'. הכי דרשינן בפרק הקומץ רבה (מנחות דף כ'):\",1,0],[8,365,11,16,\"מנחה שחסרה וכו'. בפ\\\"ק דמנחות (דף ט') פלוגתא דרבי יוחנן וריש לקיש וידוע דהלכתא כר\\\"י ועוד דהא איתותב ר\\\"ל:\",2,0],[8,365,11,17,\"התנדב קומץ לבונה בפ\\\"ע וכו'. בפ\\\"ק דמנחות (דף י\\\"א:) מימרא דרב יצחק בר' יוסף אמר ר\\\"י:\",1,0],[8,365,11,18,\"הפריש שני קמצים למנחה אחת וכו' וכן אם הפריש ארבעה קמצים וכו'. שם מימרא דרמי בר חמא:\",1,0],[8,365,11,19,\"קומץ מנחה שנטמא וכו' יצא הקומץ חוץ לעזרה וכו'. משנה בפרק הקומץ רבה (מנחות דף כ\\\"ה):\",1,0],[8,365,11,20,\"קמץ את המנחה ואחר כך נטמאו שיריה כולם וכו'. משנה שם (דף כ\\\"ו) נטמאו שיריה נשרפו שיריה אבדו שיריה כמדת רבי אליעזר כשירה וכמדת ר' יהושע פסולה, ופירש\\\"י כמדת ר' אליעזר דאמר בפרק כיצד צולין דם אע\\\"פ שאין בשר ה\\\"נ קומץ אע\\\"פ שאין שירים (בשיריה) כשירה להקטיר הקומץ. כמדת ר' יהושע דאמר אם אין בשר אין דם אם אין דם אין בשר. ובגמרא אמר רב והוא שנטמאו כל שיריה אבל מקצת שיריה לא ואסיקנא דהוא הדין לנשרפו ואבדו. ובתוספתא פ\\\"ד דמנחות תניא דהוא הדין ליצאו חוץ לקלעים. ופירש\\\"י והוא שנטמאו כל שיריה הוא דאמר ר' יהושע דפסול להקטיר הקומץ וידוע דהלכה כרבי יהושע.\",1,0],[8,365,11,20,\"ומ\\\"ש ואם הקטיר הורצה. תוספתא בפרק ד' דמנחות:\",2,0],[8,365,11,20,\"נשאר מעט מן השירים וכו'. בפ\\\"ק דמנחות (דף ט'):\",3,0],[8,365,11,21,\"היתה מחיצה מלמטה וכו'. בפרק הקומץ רבה (מנחות דף כ״ג כ״ד) איבעיא לן עשרון שחלקו והניחם בביסא מהו לקמוץ מזה על זה אמר רבא ת״ש דתניא והרים ממנו מן המחובר שלא יביא עשרון בשני כלים ויקמוץ הא בכלי אחד דומיא דשני כלים קומץ אמר ליה אביי דילמא שני כלים ה״ד כגון קפיזא דקבא דאע״ג דעריבי מעילאי כיון דמפסקן מחיצתא דקפיזא מתתא. הא כלי אחד דומיא דשני כלים ה״ד כגון עריבת תרנגולים ואע״ג דמפסקן מחיצתא הא נגיע אבל הכא דלא נגיע כלל תיבעי לך. ונראה שרבינו מפרש כגון קפיזא דקבא היינו שהיתה מחיצה מלמטה והוא מעורב מלמעלה ולהכי קרי שני כלים ופסול כלומר והתם משום דמפסקי מחיצתא מתתא מיהא פסול אבל הכא דליכא מחיצה כלל אפשר דכשר וכגון עריבת התרנגולים היינו שהוא חלוק מלמעלה ומעורב מלמטה ולהאי קרי כלי אחד וכשר:\",1,0],[8,365,11,23,\"ומ\\\"ש חלק העשרון בכלי אחד וכו' לא יקמוץ ואם קמץ לא יקטיר. הטעם משום דכיון דהיא בעיא דלא איפשיטא ספיקא היא.\",1,0],[8,365,11,23,\"ומה שכתב ואם הקטיר הורצה ולא יאכלו השירים. נראה דיליף לה מהדין שכתב לעיל בסמוך:\",2,0],[8,365,11,24,\"קמץ ונתן הקומץ למעלה על השלחן וכו'. בפ' שתי מדות (מנחות דף פ״ז:) בעא מיניה רמי בר חמא מרב חסדא שלחן מהו שיקדש קמצים בגודש שלו מדמקדש לחם קמצים נמי מקדש או דילמא דחזי ליה מקדש דלא חזי ליה לא מקדש [א״ל אינו מקדש] איני והא אמר ר' יוחנן לדברי האומר טפחים ומחצה כופל נמצא שולחן מקדש ט״ו טפח למעלה לדברי האומר טפחים כופל נמצא שלחן מקדש י״ב טפח למעלה א״ל אינו מקדש ליקרב אבל מקדש ליפסל. ודברי רבינו באינו מקדש ליקרב וכו' כפירוש רש״י בפירוש ראשון שכתב הא דאמרינן אינו מקדש מאי דלא חזי ליה היינו ליקרב שאין הקומץ מתקדש שם שעדיין יש לו לקדשו בכלי אחר קודם שיקטירנו אבל מקדש הקמצים ליפסל דקדשי ליפסל בלינה:\",1,0],[8,365,11,25,\"הדביק הקומץ לדופן הכלי וכו'. בפ״ק דמנחות (דף י״א) ובר״פ הוציאו לו (יומא מ״ז:) בעיא דלא איפשיטא:\",1,0],[8,365,11,26,\"עשרון שחלקו ואבד אחד מחלקיו וכו' עד והרי החלקים אינן נוגעים זה בזה. מימרא דרבא פרק שלישי דמנחות (דף כ\\\"ד):\",1,0],[8,365,11,28,\"קומץ מנחה שנתערב בקומץ מנחה אחרת וכו' עד הרי אלו כשירות. משנה בפ' הקומץ רבה (מנחות דף כ״ב):\",1,0],[8,365,11,29,\"שתי מנחות שלא נקמצו ונתערבו זו בזו וכו' עד סוף הפרק. הכל משנה שם (דף כ\\\"ג):\",1,0],[8,365,12,1,\"שתי הלחם ולחם הפנים וכו'. תוספתא פ״ח דמנחות ואיתא בגמ' ס״פ אלו מנחות (מנחות דף ע״ו:) ת״ר כל המנחות שריבה במדת עשרונן או שמיעט במדת עשרונן פסולות:\",1,0],[8,365,12,2,\"חלות תודה ורקיקי נזיר שחסרו וכו' עד ויביא נסכים אחרים למלאותן. תוספתא פרק רביעי דמנחות:\",1,0],[8,365,12,6,\"נסכים שקדשו בכלי ונפסל הזבח וכו'. משנה בפ' התודה (מנחות דף ע״ט) הנסכים שקדשו בכלי ונמצא זבח פסול אם יש שם זבח אחר יקרבו עמו ואם לאו יפסלו בלינה, ובגמ' אמר זעירי אין הנסכים מתקדשים אלא בשחיטת הזבח מ״ט אמר קרא זבח ונסכים תנן נסכים שקדשו בכלי ונמצא הזבח פסול אם יש זבח אחר יקרבו עמו ואם לאו יפסלו בלינה מאי לאו דאיפסיל בשחיטה לא דאיפסיל בזריקה כמאן כרבי דאמר שני דברים המתירים מעלים זה בלא זה אפי' תימא ר״א בר״ש כגון שקיבל דמן בכוס ונשפך וכו' סבר לה כוותיה דאבוה דאמר כל העומד ליזרק כזרוק דמי. ונראה שרבינו מפרש דהכי פריך מאי לאו דאיפסיל הזבח בשחיטה ואם איתא דשחיטת הזבח מקדש את הנסכים ולא קודם אמאי יפסלו בלינה הא לא קדשו כלל דהא שחיטה דפסול לא חשיבא שחיטה לקדושי נסכים. ומשני לא דאיפסיל בזריקה דהואיל וכבר קדשו נסכים בשעת שחיטה הילכך אע״ג דאיפסיל זבח בזריקה אם יש שם זבח אחר יקרבו עמו וכן פירש״י בלשון אחר. והראב״ד כתב על דברי רבינו נפסל מקבלה ואילך א״א זה כתב לר״א בר״ש דבעי שני דברים המתירים ואם נתקבל הדם ונשפך כמי שנזרק דמי אבל לרבי אפי' בשחיטה לחודה קדשו ליקרב עם זבח אחר עכ״ל:\",1,0],[8,365,12,6,\"ודע שפירש\\\"י כמאן כרבי דאמר בפרק התכלת שחט הכבשים לשמן וזרק דמן שלא לשמן הלחם קדוש ואינו קדוש. שני המתירים כגון זריקה ושחיטה מקדשין הקרבן לקדושה. מעלים זה בלא זה והני שחיטה וזריקה מקדשים הם הנסכים וכיון דנסכים אלו הוקדשו בשחיטה אע\\\"ג דאיפסיל זבח בזריקה קדשו נסכים בשחיטה וכו'. אפילו תימא ר' אלעזר דאמר אין מעלין זה בלא זה דאמר לא קדש הלחם עד שישחוט ויזרוק דמן לשמן. הב\\\"ע כגון שקיבל הדם בכוס ונשפך אח\\\"כ נפסל בזריקה ור' אלעזר סבר לה כאבוה דאמר כל העומד ליזרק כזרוק דמי להכי דנתקדשו שני המתירים בשחיטה ובזריקה אבל להכי לא הוי כזרוק שיהא הזבח כשר עכ\\\"ל. ופסק רבינו כרבי וזהו\",2,0],[8,365,12,6,\"שכתב אם נפסל בשחיטה לא קדשו הנסכים ליקרב נפסל מקבלה ואילך קדשו הנסכים ליקרב כלומר אם השחיטה היתה כתקנה אע\\\"פ שנפסל אח\\\"כ בקבלה או בזריקה קדשו הנסכים ליקרב. וזה מבואר בדברי רבינו ואיני יודע למה כתב הראב\\\"ד על רבינו זה כתב לר' אלעזר בר\\\"ש וכו' שהרי מבואר בדבריו שאינו פוסק אלא כרבי וכדפרישית. ואין לדחוק ולומר שטעמו מפני שהיה לו לרבינו לכתוב ואם לא נפסל בשחיטה קדשו הנסכים ואם נפסל אח\\\"כ אם היה זבח אחר זבוח וכו' ומאחר שכתב נפסל מקבלה ואילך משמע ליה דנפסל אחר קבלה קאמר דהוה ליה שני דברים המתירים בכשרות שחיטה וקבלה ואח\\\"כ נשפך הדם וכר\\\"א בר\\\"ש שא\\\"א לפרש כן בדברי רבינו משום דהא זעירי דאמר אין הנסכים מתקדשים אלא בשחיטה לא אתי אלא כרבי דאילו לר\\\"א בר\\\"ש אינם מתקדשים עד שיעשה שני המתירים דהיינו שחיטה וזריקה בכשרות וכי שני אפילו תימא ר\\\"א בר\\\"ש קאי אאוקימתא דאוקימנא במתני' דאיפסיל בזריקה דאילו זעירי פשיטא דלא אתי כוותיה וא\\\"כ מאחר שרבינו פסקה לדזעירי שאין הנסכים מתקדשים ליקרב אלא בשחיטת הזבח וכמבואר בדבריו עוד בפרק י\\\"ז גבי כבשי עצרת ע\\\"כ לומר שפסק כרבי ולא כר\\\"א בר\\\"ש.\",3,0],[8,365,12,6,\"ומ\\\"ש ואם נפסל מקבלה ואילך היינו לומר שנפסל בקבלה עצמה או באחת משאר עבודות שאחר קבלה ומה שלא כתב ואם לא נפסל בשחיטה מפני שהיה צריך להאריך ולכתוב עוד ואח\\\"כ נפסל בקבלה או באחת משאר עבודות. וליישב דברי הראב\\\"ד נראה לומר שהוא ז\\\"ל היה מפרש דכי שני אפי' תימא ר\\\"א בר\\\"ש לזעירי נמי קאי לומר דשפיר אתי כר\\\"א בר\\\"ש והא דלא אדכר זעירי אלא שחיטה משום דעיקר מילתיה אתא לאשמועינן דלא נימא דבכניסתן בכלי בלבד נתקדשו אלא שצריך ג\\\"כ שחיטת הזבח וזעירי לא נחית נפשיה לפלוגתא דלכ\\\"ע צריך נמי שחיטת הזבח אלא לרבי בהכי סגי ולר' אלעזר בר\\\"ש צריך נמי קבלה ואף על גב דמייתי לה מדכתיב זבח ונסכים דמשמע דבשחיטה בלחוד סגי איכא למימר דלר' אלעזר בר\\\"ש כיון דגלי קרא דצריך שחיטה כיון דס\\\"ל דב' דברים המתירים אין מעלין זה בלא זה ממילא משמע דקבלה נמי צריך. כל זה לתת מקום לדברי הראב\\\"ד אבל דברי רבינו מבוארים שהם כרבי וכמו שנתבאר:\",4,0],[8,365,12,6,\"ומ\\\"ש רבינו אם היה שם זבח אחר זבוח באותה שעה. הכי אמרינן בגמרא דמתני' הכי מיפרשא אם יש שם זבח אחר יקריבו עמו בד\\\"א בשהיה זבח זבוח באותה שעה אבל (אם) אין זבח זבוח באותה שעה נעשה כמי שנפסלו בלינה ופסולים.\",5,0],[8,365,12,6,\"ומ\\\"ש רבינו בד\\\"א בקרבן צבור וכו' שם אם יש שם זבח אחר יקרבו עמו והאמר רב חסדא שמן שהפרישו לשם מנחה זו פסול לשם מנחה אחרת אמר רבי ינאי לב ב\\\"ד מתנה עליהם אם הוצרכו הוצרכו ואם לאו יהו לזבח אחר.\",6,0],[8,365,12,6,\"ומ\\\"ש רבינו דלא אמרינן לב בית דין מתנה עליהם אלא בקרבנות צבור. בפרק קמא דזבחים (דף ו':) קרבנות צבור קאמרת שאני קרבנות צבור דלב ב\\\"ד מתנה עליהם:\",7,0],[8,365,12,7,\"וכל הזבחים שנזבחו שלא לשמן יקרבו נסכיהם:\",1,0],[8,365,12,8,\"ולד תודה ותמורתה והמפריש תודתו ואבדה וכו' עד בין לפני כפרה בין לאחר כפרה. משנה וגמרא בפרק התודה (מנחות דף ע״ט:):\",1,0],[8,365,12,9,\"הפריש תודתו ואבדה והפריש אחרת תחתיה וכו' עד שתיהם אינן טעונות לחם. מימרא דרבא שם (דף פ':):\",1,0],[8,365,12,10,\"המפריש מעות לתודתו וכו' עד וזו התודה האחרונה תקרב בלא לחם. תוספתא פ\\\"ח דמנחות:\",1,0],[8,365,12,11,\"האומר הרי זו תודה והרי זה לחמה וכו'. בפרק התודה (מנחות דף פ') מימרא דרבי אבא:\",1,0],[8,365,12,12,\"הפריש מעות לתודתו וכו'. שם מימרא דרבא ומפרש טעמא משום דלחם איקרי תודה תודה לא איקרי לחם:\",1,0],[8,365,12,13,\"האומר הרי זה תודה וכו'. שם תני רבי חייא תודה שנתערבה בתמורתה ומתה אחת מהן חבירתה אין לה תקנה היכי נעביד נקריב לחם בהדה דילמא תמורה היא לא נקריב לחם בהדה דילמא תודה היא והראב\\\"ד כתב על דברי רבינו א\\\"א מה תקנה יש בזה וכו'. ואיני מבין מה השגה היא זו דהא בגמרא אמרינן היכי דמי אי דאמר עלי לא סגי דלא מייתי ליה בהמה אחרינא ולחם ולימא אי הך דקיימא תמורה היא הא תודה והא לחמה אי הך דקיימא תודה היא הא לחמה והא תהוי אחריות לא צריכא דאמר הרי זו ע\\\"כ. ומאחר שרבינו פתח באומר הרי זו תודה וכדאוקימנא לדרבי חייא לא נשארה עליו שום תלונה. ואין לומר שמשיג על רבינו שכתב אלא תרעה שלא נזכר בדברי רבי חייא ואם בא לומר שיש לה תקנה ברעייה הא לאו תקנה היא ואם היה רוצה לומר תקנה הל\\\"ל יביא אחרת ולחמה וכו' דמי הגיד לו שבא לומר תקנה שכל עצמו לא בא לומר אלא שלא תקרב זו לעולם וכדתני רבי חייא אין לה תקנה אלא שסיים לומר מה יעשה בה. גם אין לומר שסובר הראב\\\"ד שמה שאמר רבי חייא אין לה תקנה היינו לומר שלה בעצמה אין תקנה אבל ליפטר מחיובו צריך לעשות תקנה שיביא אחרת ולחמה וכו' דכיון דלא אמר הרי זו אין כאן שום חיוב:\",1,0],[8,365,12,14,\"תודה שנפרסה חלה מחלותיה כולן פסולות. ברייתא בסוף פרק קמא דמנחות (דף י\\\"ב:) ודייק רבא הא יצתה הני דאיכא גוואי כשירות ומוקי לה כר\\\"ע ואע\\\"ג דאביי דחי התם ואמר דילמא ר' אליעזר היא דחייה בעלמא היא ועוד דכרבא נקטינן וכיון דמכשר ביצאה כ\\\"ש דמכשר בנטמאת שהציץ מרצה ומפרש לה רבינו בתודה דאף על גב דקרא דמייתי בגמרא בלחם הפנים כתיב ילפינן מיניה לתודה וגם במנחה כתיב הכי ולשון הגמ' שאמרו זריקה מועלת בתודה הוא דשייך.\",1,0],[8,365,12,14,\"ומה שכתב נפרס לחמה או נטמא או יצאה וכו' עד וממה שבפנים על מה שבחוץ. הכל ברייתא פרק התכלת (מנחות דף מ\\\"ו):\",2,0],[8,365,12,14,\"וכתב הראב\\\"ד תודה שנפרסה וכו'. א\\\"א במאי עסקינן אי קודם שחיטה נפרסה וכו'. תחלת דבריו דבר פשוט הוא נלמד מברייתא דפ' התכלת שהזכרתי בסמוך. ומ\\\"ש בין נפרס בין יצא בין נטמא הכל פסול וכו'. למדו הראב\\\"ד מהברייתא הנזכרת דקתני מששחטה נפרס לחמה הדם יזרק והלחם פסול וכו' מששחטה יצא לחמה הדם יזרק והלחם פסול מששחטה נטמא לחמה הדם יזרק וכו' והלחם פסול ומשמע ליה להראב\\\"ד דכיון דנפרס לחמה ויצא ונטמא בחדא גוונא תננהו אין חילוק ביניהם וכיון דתניא בספ\\\"ק דמנחות שאם נפרסה אחת מהן כולן פסולות וע\\\"כ היינו בין שחיטה לזריקה כמו שנתבאר הוא הדין לנטמא אחת מן החלות או שיצאה ואע\\\"ג דבברייתא בספ\\\"ק דמנחות אהא דתניא שאם נפרסה אחת מהן כולן פסולות דייק רבא הא יצתה הני דאיכא גוואי כשירות ואביי דייק הא נטמאת הנך כשירות אפשר דאכתי לא הוה שמיע להו ברייתא דפ' התכלת ורבינו לא נראה לו לומר דלא הוה שמיע להו ההיא ברייתא אע\\\"ג דשמיע להו ההיא ברייתא דייקי מהאי ברייתא דנפרס לחמה דוקא קתני ואע\\\"ג דברייתא דהתכלת תני להו בחד גוונא איכא למימר מידי איריא הא כדאיתא והא כדאיתא:\",3,0],[8,365,12,15,\"תודה שנשחטה על שמונים חלות וכו' ואם אמר יקדשו ארבעים מתוך שמונים וכו'. בפ' התודה (מנחות דף ע״ח:) פלוגתא דחזקיה ור״י ומייתי לה בפ' האיש מקדש (קידושין דף נ״א) ובפ' מי שהוציאוהו (עירובין דף נ') ופסק רבינו כר״י ויש לתמוה אמאי לא פסק כחזקיה דרביה הוא.\",1,0],[8,365,12,15,\"ומ\\\"ש מושך וכו'. נתבאר בפ' התכלת:\",2,0],[8,365,12,16,\"השוחט את התודה וכו'. משנה וברייתא בפ' התודה (מנחות ע״ח:) ופירש רש״י חוץ לחומת בית פגי היינו לחומת הר הבית:\",1,0],[8,365,12,17,\"שחטה עד שלא קרמו פני הלחם בתנור וכו' עד סוף הפרק. משנה שם:\",1,0],[8,365,12,18,\"שחטה ונפסלה בשחיטתה וכו' קדש הלחם. אע\\\"ג דאחר שנתפגל הביאה קדוש להפסל בטבול יום ובלינה דאין חייבים משום פגול ומשום נותר אלא הבשר שהותר שעה אחת קאמר קדש הלחם להתחייב עליו משום פגול.\",1,0],[8,365,12,18,\"ומ\\\"ש וכן הדין באיל נזיר וכו'. שם בגמרא:\",2,0],[8,365,13,1,\"שלש מחשבות הן וכו'. מתבאר והולך.\",1,0],[8,365,13,1,\"ומה שכתב מחשבת שינוי השם וכו'. בפרק קמא דזבחים תנן כל הזבחים שנזבחו שלא לשמן כשרים אלא שלא עלו לבעלים לשם חובה חוץ מן הפסח והחטאת ובגמרא יליף מקראי דבפסח וחטאת פוסל בין שינוי קדש בין שינוי בעלים.\",2,0],[8,365,13,1,\"ומה שכתב רבינו כגון שהיה עולה ויחשב שהוא שלמים אע\\\"ג דכל הזבחים חוץ מפסח וחטאת כשרים שלא לשמן כיון דלא עלו לבעלים לשם חובה שפיר שייך למימר בהו שם פיסול.\",3,0],[8,365,13,1,\"ומה שכתב או ישחטנו לשם עולה ושלמים או לשם שלמים ולשם עולה. הוא ממה ששנינו בסוף פרק קמא דזבחים (דף י\\\"ג) גבי פסח וחטאת ששחטן לשמן ושלא לשמן או שלא לשמן ולשמן:\",4,0],[8,365,13,1,\"מחשבת המקום כיצד וכו'. מבואר במשנה פרק ב' דזבחים (דף כ\\\"ה):\",5,0],[8,365,13,1,\"מחשבת הזמן כיצד וכו' עד הרי הקרבן פגול. מבואר שם במשנה:\",6,0],[8,365,13,2,\"ומ\\\"ש מפי השמועה למדו שזה שנאמר בתורה ואם האכל יאכל וכו'. בפ\\\"ב דזבחים (דף כ\\\"ט).\",1,0],[8,365,13,2,\"ומה שכתב אחד אכילת אדם ואחד אכילת מזבח וכו'. שם (דף כ\\\"ח):\",2,0],[8,365,13,4,\"ומ\\\"ש אבל קרבן שלא נפסדה מחשבתו אלא נזרק על המזבח כהלכתו וכו'. שם (דף כ\\\"ו כ\\\"ט).\",1,0],[8,365,13,4,\"ומ״ש לפיכך אין מתפגל אלא דבר שיש לו מתירין בין לאדם בין למזבח. משנה בפ' ב״ש (זבחים דף מ״ג):\",2,0],[8,365,13,4,\"אחד זבח שחשב בו אחת משלש מחשבות אלו וכו' נמצאת למד שבארבע עבודות הזבח נפסל וכו'. משנה בספ\\\"ק דזבחים (דף י\\\"ג):\",3,0],[8,365,13,5,\"ומ״ש והעוף בשני דברים וכו'. משנה בפ' קדשי קדשים (זבחים דף ס״ד ס״ה):\",1,0],[8,365,13,6,\"ומ\\\"ש והמנחות הנקמצות בד' וכו'. משנה בפירקא קמא דמנחות (דף י\\\"ב) ובריש פ\\\"ב דמנחות [י\\\"ג] ובספ\\\"ק דזבחים (דף י\\\"ג:) מדמה ארבע עבודות אלו לארבע עבודות שבזבח דקומץ היינו שוחט. מוליך היינו מוליך. מקטיר היינו זורק. נותן בכלי דמי לקבלה. ופירש\\\"י קומץ דמי לשוחט שזה נוטל ומפריש חלק לגבוה מחלק כהנים וכן זה:\",1,0],[8,365,13,8,\"וכן המחשב באחת מארבע עבודות אלו וכו' כיצד המחשב בשעת שחיטה וכו' להניח דם הזבח או אימוריו למחר וכו' עד הזבח כשר. משנה בפרק שלישי דזבחים (דף ל\\\"ו).\",1,0],[8,365,13,8,\"ומ\\\"ש וכן אם חשב בשעת קמיצת המנחה וכו' להניח קומצה או לבונתה למחר וכו'. הוא נלמד מדין הזבח:\",2,0],[8,365,13,9,\"כבר ביארנו שהולכה שלא ברגל אינה הולכה וכו'. בסוף פ\\\"ק דזבחים (דף י\\\"ד ט\\\"ו) אמר ר\\\"י הולכה שלא ברגל לא שמה הולכה ואע\\\"ג דאמרינן התם דאותביה ר\\\"נ ואסיקנא בתיובתא משמע לרבינו דלא אותביה לעיקר מימריה אלא למאי דסיים בה אלמא לא אפשר לתקונה הוא דאותביה. וכן יש לדקדק ממה שפירש\\\"י תיובתא דעולא כלומר לעולא דאמר אלמא לא אפשר לתקונה הוא דמותבינן ולא למאי דאמר משום ר\\\"י הולכה ברגל לא שמה הולכה:\",1,0],[8,365,13,9,\"ומ\\\"ש רבינו והמהלך במקום שא\\\"צ הרי זה הולכה וכו'. בספ\\\"ק דזבחים (דף י\\\"ג) תנן שהזבח נפסל בארבעה דברים בשחיטה ובקיבול ובהילוך ובזריקה ר\\\"ש מכשיר בהילוך וכו' ר\\\"א אומר המהלך במקום שהוא צריך להלך מחשבה פוסלת ובמקום שא\\\"צ להלך אין מחשבה פוסלת ואמרינן בגמ' (דף ט\\\"ו:) דלר\\\"א קבלו בפנים והוציאו לחוץ זהו הילוך שאין צריך הא חזר והכניסו הילוך שצריך להלוך הוא. ופרש\\\"י בפנים לצד המזבח והוציאו לחוץ כלומר ריחקו מהמזבח [הנך] חוץ ופנים כולהו בעזרה. ולת\\\"ק אפי' קבלו בפנים והוציאו לחוץ וחשב עליו בשעה שהוציאו לחוץ פוסלת וידוע דהלכה כת\\\"ק. והראב\\\"ד כתב כבר ביארנו וכו' עד הרי זו הלכה א\\\"א לא נהיר דסוגיין כולה כר' אלעזר דאמר לא שמה הולכה עכ\\\"ל. וליישב דעת רבינו י\\\"ל שאין הכרח לומר דסוגיין כר' אלעזר דאע\\\"ג דאיפליגו אביי ורבא בפירוש מילתיה דר' אלעזר ורבנן לאו משום דס\\\"ל הלכה כר\\\"א אלא לפרושי מילתיה דת\\\"ק דמדר\\\"א נשמע לת\\\"ק. ודעת רבינו שלא כדברי רש\\\"י באי תניא תניא שרבינו מפרש דלתנא קמא הילוך פוסל בכל גוונא אפילו במקום שאינו צריך להלך:\",2,0],[8,365,14,1,\"אין המחשבה הולכת אלא אחר העובד וכו'. בס\\\"פ ב\\\"ש (זבחים מ\\\"ו:) א\\\"ר יוסי שאין המחשבה הולכת אלא אחר העובד ובגמ' (דף מ\\\"ז) מתני' דלא כי האי תנא דתניא א\\\"ר אליעזר בר' יוסי שמעתי שהבעלים מפגלים. ומשמע לרבינו דהלכה כמתני' ועוד דאמרינן התם בגמרא אמר אביי ר\\\"א בר' יוסי ור' אלעזר ורשב\\\"א כולהו ס\\\"ל זה מחשב וזה עובד הויא מחשבה וכל כה\\\"ג ה\\\"ל שיטה ולית הלכתא כחד מינייהו:\",1,0],[8,365,14,2,\"ואין המחשבה [מועלת] וכו'. מימרא דרבא בפ\\\"ב דזבחים (דף כ\\\"ו ע\\\"ב) ובמנחות (דף ה':).\",1,0],[8,365,14,2,\"ומ\\\"ש ממי שהוא ראוי כיצד אחד מן הפסולים לעבודה שקבל הדם או הוליך כו' ואותו דם שקיבל או שזרק מקצתו ישפך לאמה. פשוט הוא.\",2,0],[8,365,14,2,\"ומ\\\"ש ואם נשאר דם הנפש יחזור הראוי לעבודה ויקבל וכו'. משנה בפ\\\"ג דזבחים (דף ל\\\"ב).\",3,0],[8,365,14,2,\"ומ\\\"ש אבל אם חשב הפסול במחשבתו בשעת שחיטה פסל במחשבתו וכו'. שם במשנה.\",4,0],[8,365,14,2,\"ומ\\\"ש יש קרבנות שאם נעשו שלא לשמן כשרים כמו שיתבאר. הוא פט\\\"ו:\",5,0],[8,365,14,2,\"לפיכך אם קיבל הדם כהן זה וכו' פסל הזבח כאילו עשאו לשמו וכו'. נראה שהטעם שמאחר דשלא לשמו פסל בעלמא והכא לא פסל הוי כמי שאינו ראוי לעבודה כראוי לענין שיהא פוסל במחשבה שאע\\\"פ שיש דם הנפש לא מהני שיחזור הכשר ויקבל אכן צריך לימוד מנין לו לרבינו זה:\",6,0],[8,365,14,3,\"בדבר הראוי לעבודה כיצד וכו'. בפ\\\"ק דמנחות (דף ה':) איפליגו אמוראי במילתא ורבא דהוא בתרא אמר מנחת העומר שקמצה שלא לשמה כשירה ושיריה נאכלין ואינה צריכה מנחת העומר אחר להתירה שאין המחשבה מועלת אלא במי שהוא ראוי לעבודה ובדבר הראוי לעבודה ובמקום הראוי לעבודה במי שהוא ראוי לעבודה לאפוקי כהן בעל מום ובדבר הראוי לעבודה לאפוקי מנחת העומר דלא חזיא דחידוש הוא ובמקום הראוי לעבודה לאפוקי נפגם המזבח. ופירש\\\"י מנחת העומר של שעורים ואינה ראויה אלא לעבודה זו להתיר ולא משום קרבן אתיא וכו' והא דפסלה מחשבה במנחת קנאות משום דרחמנא קרייה חטאת.\",1,0],[8,365,14,3,\"ומ\\\"ש וכן המחשב במנחת קנאות והלבונה עליה וכו'. כן משמע בתוספתא דמנחות ספ\\\"ה:\",2,0],[8,365,14,3,\"וכתב הראב\\\"ד על דברי רבינו לא מחוורא האי גירסא וכו' עד שקרב העומר והותר באכילה. ולפי נוסחתו מנחת העומר היינו מנחה שהוקרבה אחר שהביאו העומר קודם שיביאו שתי הלחם והנך רואה כמה דחוק פירוש זה וההכרע שכתב אינו כדאי לדחות גירסת רבינו ורש\\\"י דאיכא למימר לבונה דנקט במנחת קנאות חדא ועוד קאמר חדא שהיא של שעורים ועוד שאין עליה לבונה:\",3,0],[8,365,14,4,\"במקום הראוי לעבודה כיצד מזבח שנפגם וכו'. מבואר במימרא דרבא שכתבתי בסמוך.\",1,0],[8,365,14,4,\"ומ\\\"ש קמץ את המנחה בחוץ וחשב וכו'. פשוט הוא:\",2,0],[8,365,14,5,\"אלו דברים שאינם ראויים לאכילה וכו' עד דבר העומד לשריפה. הוא הקדמה למה שיבא אח\\\"כ:\",1,0],[8,365,14,7,\"ומ\\\"ש ואלו שאינם ראויים לא לאכילה ולא להקטרה בשר חטאת הנשרפת. זה פשוט דלא מיקרי ראוי להקטרה אלא דבר הנקטר ע\\\"ג המזבח בלבד.\",1,0],[8,365,14,7,\"ומ\\\"ש והעור של בהמה כולו חוץ מעור שתחת האליה הוא ראוי לאכילה. בפרק שני דזבחים (דף כ\\\"א) אמרינן דעור שתחת האליה ראוי למאכל אדם.\",2,0],[8,365,14,7,\"ומ\\\"ש אבל המוראה בפרק ג' דזבחים (דף ל\\\"ה) מני בברייתא מוראה בהדי הנך דאין מפגלין ולא מתפגלין מפני שאינם ראויים לא למאכל אדם ולא למאכל מזבח. ומה שפירש בו רבינו שהוא הקרום הדק הדבק בעור ומבדיל בינו ובין הבשר אפשר שפירש כן מפני שהוא שם בברייתא סמוך לאלל.\",3,0],[8,365,14,7,\"ומ\\\"ש וכן העצמות והגידים והטלפים. משנה שם בפרק ג' דזבחים.\",4,0],[8,365,14,7,\"ומ\\\"ש והנוצה של עוף. משנה בפ\\\"ק דטהרות דאינה מצטרפת לטומאה.\",5,0],[8,365,14,7,\"ומה שכתב והצפרניים והחרטום. שם במשנה החרטום והצפרניים מטמאין ומיטמאים ומצטרפין ובפ' העור והרוטב (חולין דף קכ״א) מקשה חרטום עץ בעלמא הוא ומוקי לה בחרטום תחתון של עליון ופירש״י קליפת רצועה דקה יש בתוך הפה דבוקה לחרטום עליון לארכו וצפרניים מוקי לה במקום שמובלעים בבשר.\",6,0],[8,365,14,7,\"ומה שכתב וראשי גפיים וראש הזנב. גם זה שם וכת\\\"ק ולא כר' יוסי דאמר התם דמצטרפין לטומאה שכן מניחים בפטומות.\",7,0],[8,365,14,7,\"ומ\\\"ש אפילו מקומות הרכים מכל אלו הדבוקים בבשר וכו'. נתבאר במ\\\"ש בסמוך דמוקי בגמרא הא דקתני צפרניים מצטרפים במקום שמובלעים בבשר משמע דראשי גפיים וראשי הזנב דקתני אינם מצטרפין אפי' במובלעין בבשר נמי קאמר דאינם מצטרפין.\",8,0],[8,365,14,7,\"ומ\\\"ש וכן המרק והתבלין והשליל והשיליא וביצת העוף והבשר שפולטתו הסכין בשעת הפשטן וכו'. משנה בפ' ג' דזבחים (דף ל\\\"ז):\",9,0],[8,365,14,8,\"ומ\\\"ש ומחשבין על דבר העומד לאיבוד או לשריפה. בפ\\\"ק דמעילה (דף ז'):\",1,0],[8,365,14,8,\"המחשב באחת מאותן ארבע העבודות וכו' עד הזבח כשר. גם זה שם במשנה.\",2,0],[8,365,14,8,\"ומה שכתב כיצד חשב לשתות מדם הזבח וכו'. בפרק הקומץ רבה (מנחות דף י״ז:) תניא השוחט את הזבח לשתות מדמו למחר וכו' כשר.\",3,0],[8,365,14,8,\"ומה שכתב וכן אם חשב לאכול מפרים ושעירים הנשרפים וכו'. בפ\\\"ג דזבחים (דף ל\\\"ה) חישב באכילת פרים ובשריפתן לא עשה ולא כלום. וצריך טעם למה השמיט מלכתוב דה\\\"ה אם חשב לשרפן למחר שהם כשרים:\",4,0],[8,365,14,9,\"חשב שיאכלו הטמאים וכו'. בספ\\\"ג דזבחים (דף ל\\\"ו ע\\\"ב) אמר רב חסדא אמר רבינא בר שילא חישב שיאכלוהו טמאים למחר חייב (כרת) אמר רבא תדע דבשר לפני זריקה לא חזי וכי מחשב ביה מיפסיל ולא היא התם זריק ומיחזי הכא לא מיחזי כלל ומשמע לרבינו דהא דקאמר ולא היא לא לדחויי דינא דרב חסדא אתמר אלא לדחויי סייעתא דאייתי רבא ואע\\\"ג דסייעתא אידחיא דינא לא אידחי מאחר דרב חסדא ורבינא בר שילא ורבא ס\\\"ל הכי וליכא מאן דפליג עלייהו. ויש סעד לזה מדאמר ר' ינאי זבחים (דף ל\\\"א) חישב שיאכלוהו כלבים למחר הוי פגול דכתיב יאכלו הכלבים ומי עדיפי כלבים מטמאים.\",1,0],[8,365,14,9,\"ומ\\\"ש כמו שביארנו. כלומר שהזבח מתפגל במחשבת חוץ לזמנו:\",2,0],[8,365,14,10,\"אין אכילה פחותה מכזית וכו' עד הזבח כשר. משנה בפרק ג' דזבחים (דף כ\\\"ט:).\",1,0],[8,365,14,10,\"ומ\\\"ש חשב לאכול כחצי זית בחוץ ולהקטיר כחצי זית בחוץ וכו' שאין אכילה והקטרה מצטרפין. שם.\",2,0],[8,365,14,10,\"ומ\\\"ש ואם הוציאו בלשון אכילה וכו' לשון אכילה אחד הוא. שם בגמ' (דף ל\\\"א):\",3,0],[8,365,14,10,\"חשב לאכול או להקטיר כחצי זית וכו'. מתבאר בספ\\\"ב דזבחים (דף ל\\\"א):\",4,0],[8,365,14,10,\"חשב לאכול כחצי זית ושתאכל בהמה או חיה כחצי זית וכו'. שם מימרא דר' ינאי:\",5,0],[8,365,14,10,\"חשב על כזית שיאכלוהו שנים הרי אלו מצטרפין. שם ע\\\"ב בעיא דאיפשיטא:\",6,0],[8,365,14,10,\"חשב לאכול כזית ביותר מכדי אכילת פרס הרי זה מצטרף. שם בעיא דרבא ובעי אביי למפשטה ממתניתין ודחי ליה. ומשמע לרבינו דדחייה בעלמא היא דפשטא דמתני' כדאמר אביי היא והכי הלכתא. ואפשר שלא היה בגירסתו דחייה כלל:\",7,0],[8,365,14,10,\"חשב בשעת זביחה לאכול כחצי זית וכו'. ברייתא בפ\\\"ב דמנחות (דף י\\\"ד:).\",8,0],[8,365,14,10,\"ומ\\\"ש וכן אם חשב על כזית בשעת קבלה ועל כזית בשעת הולכה. נ\\\"ל שטעות סופר יש כאן וצריך להגיה כחצי זית בשעת קבלה וכחצי זית בשעת הולכה והוא שם בגמרא אהאי ברייתא דבסמוך א\\\"ד שחיטה וזריקה דתרוייהו מתירין אין קבלה והולכה לא ואיכא דאמרי הנך דמירחקן וכ\\\"ש הני דמיקרבן ופסק רבינו כלישנא דמחמיר ועוד דבתרא הוא ועוד דבגמ' משמע דלרבנן מצטרפות ארבע עבודות:\",9,0],[8,365,14,10,\"חשב להקטיר כחצי זית וכו'. ברפ\\\"ב דמנחות (דף י\\\"ג) תנן דלת\\\"ק לבונה נמי מפגלת כמו המנחה עצמה וכן מבואר במתניתין בפ\\\"ק:\",10,0],[8,365,14,10,\"אחד המחשב לזרוק דם הזבח וכו'. משנה בפ' שני דזבחים (דף כ\\\"ח).\",11,0],[8,365,14,10,\"ומ\\\"ש כיון שחשב על כדי הזיה מן הדם פסל. פשוט הוא שאם לא חשב על כדי הזיה לא פסל:\",12,0],[8,365,15,1,\"כל הזבחים שנשחטו במחשבת שינוי השם וכו'. משנה בריש זבחים.\",1,0],[8,365,15,1,\"ומ\\\"ש ואחד המשנה שם הזבח בשעת שחיטה או בשעת קבלה או בשעת הולכה או בזריקה. גם זה משנה שם (דף י\\\"ג).\",2,0],[8,365,15,1,\"ומ\\\"ש בין בקרבנות יחיד בין בקרבנות הצבור. מתבאר בפ\\\"ק דזבחים (דף ד') דשנוי קדש ישנו בצבור כביחיד אבל שינוי בעלים לא שייך בצבור שהרי הכל בעליו:\",3,0],[8,365,15,1,\"כיצד לא עלו לשם חובה וכו' וכן אם שחט עולות ראובן וכו'. שם בגמ' יליף מקראי דבין שינוי קדש בין שינוי בעלים בעינן בכולהו קרבנות לשמן למצוה ובפסח וחטאת לעכב.\",4,0],[8,365,15,1,\"ומ״ש בד״א כשעקר שם הזבח בזדון אבל אם טעה ודימה שזו העולה שלמים הוא וכו'. בפ' התכלת (מנחות דף מ״ט) איפליגו אמוראי עקירה בטעות אי הויא עקירה או לא ורבא דהוא בתרא אמר דעקירה בטעות לא הויא עקירה ואביי נמי משמע דסבר כוותיה ובפסחים פ' אלו דברים (פסחים דף ע״ב.) מתמה גמרא אמתני' דהתם שמע מינה עקירה בטעות הויא עקירה משמע דס״ל דלא הויא עקירה.\",5,0],[8,365,15,1,\"ומ\\\"ש וכן החטאת והפסח שעשאן במחשבת שינוי השם בטעות כשרים וכו'. הוא מה שכתבתי בסמוך דאיתא בפ' אלו דברים גבי הפסח:\",6,0],[8,365,15,1,\"וכן עולת העוף שמלקה וכו'. אריש פירקא קאי דקתני כל הזבחים שנשחטו במחשבת שינוי השם כשרים אלא שלא עלו לבעלים לשם חובה חוץ מן החטאת והשתא קאמר דהוא הדין לקרבן העוף דשינוי השם פסול בחטאת ובעולה כשר אלא שלא עלה לבעלים לשם חובה והוא מבואר במשנה פ' קדשי הקדשים (ס\\\"ד:):\",7,0],[8,365,15,2,\"וכן כל המנחות וכו'. משנה בריש מנחות כל המנחות שנקמצו שלא לשמן כשירות אלא שלא עלו לבעלים משום חובה חוץ ממנחת חוטא ומנחת קנאות.\",1,0],[8,365,15,2,\"ומ\\\"ש שאם חשב באחת מארבע עבודות שלהן מחשבת שינוי השם פסולות וכו'. משנה שם (דף י\\\"ב) ובפי\\\"ג ביאר רבינו מה הן ארבע עבודות דמנחות:\",2,0],[8,365,15,2,\"שינוי השם במנחה כיצד וכו'. מתבאר בגמ' בריש מנחות:\",3,0],[8,365,15,3,\"אסור לחשב בקדשים וכו' לפיכך זבח ששחטו שלא לשמו וכו' חייב להשלים שאר עבודות לשמן וכו'. דיוקא דמתני' ומימרא דרבא בריש זבחים ובריש מנחות.\",1,0],[8,365,15,3,\"ומה שכתב אפילו שחט וקבל והוליך וכו' חייב לזרוק במחשבה נכונה. מימרא דרבא בפ\\\"ק דזבחים (דף ז').\",2,0],[8,365,15,3,\"ומ\\\"ש רבינו כמו שיתבאר. הוא בפרק י\\\"ז:\",3,0],[8,365,15,3,\"ומפני מה נשתנה דין החטאת והפסח וכו'. בריש זבחים (דף ז') וריש מנחות (דף ד':):\",4,0],[8,365,15,4,\"חטאת ששחטה לשם זבח אחר וכו' אבל אם שחטה לשם חולין הרי זה כשירה וכו' עד ואין החולין מחללין קדשים. מימרות אמוראים בס\\\"פ ב\\\"ש (זבחים מ\\\"ו:):\",1,0],[8,365,15,6,\"שחטה לשם חטאת אחרת וכו' פסולה. בפ\\\"ק דזבחים (דף ז') אמר רבא חטאת ששחטה לשם חטאת כשירה וכו' מ\\\"ט ושחט אותה לחטאת אמר רחמנא והרי חטאת וכו' שחטה על מי שמחוייב חטאת פסולה על מי שמחוייב עולה כשירה מ\\\"ט וכפר עליו ולא על חבירו חבירו דומיא דידיה דמחוייב כפרה כמותו. ופירש\\\"י חטאת חלב ששחטה לשם חטאת דם כשירה ועולה לבעלים אפי' שינוי קדש אין כאן. ובדף ט' ע\\\"ב גרסינן אמר רבא חטאת חלב ששחטה לשם חטאת ע\\\"ז כשירה לשם חטאת נזיר לשם חטאת מצורע פסולה. הני עולות נינהו כלומר דכיון שאינן באות אלא להכשיר ולא לכפר על חטא ידוע ה\\\"ל עולות. בעי רבא חטאת חלב ששחטה לשם חטאת דטומאת מקדש מהו מי אמרינן כרת כמותה או דילמא אין קבוע כמותה. רב אחא בריה דרבא מתני כולהו לפיסולא ושחט אותה לחטאת לשם אותה חטאת אמר ליה רב אשי לרב אחא בריה דרבא היכי מתניתו לה א\\\"ל אנן בשינוי בעלים מתנינן לה אמר רבא חטאת ששחטה על מי שמחוייב חטאת דם וחטאת ע\\\"ז פסולה על מי שמחוייב חטאת נזיר וחטאת מצורע כשירה ובעינן לה הכי בעי רבא חטאת חלב ששחטה על מי שמחוייב חטאת דטומאת מקדש וקדשיו כלומר שהיא בעולה ויורד מהו מי אמרינן כרת כמותה או דילמא אין קבוע כמותה תיקו. ופסק רבינו כרב אחא בריה דרבא משום דרב אשי דהוא בתרא משמע דסבר כוותיה דמדלא אהדר ליה מידי משמע דקיבלה מיניה. ועוד דסתם גמרא דסוף כריתות (דף כ\\\"ז) כוותיה דקאמר שאם הפריש בהמה על החלב והביאה על הדם על הדם והביאה על החלב לא כפר ובבעיא דרבא דסלקא בתיקו פסק לחומרא. ומ\\\"מ עדיין יש לתמוה למה השמיט הא דאמר רבא חטאת ששחטה על מי שמחוייב חטאת נזיר חטאת מצורע כשירה וצ\\\"ל שלא היה כן בגירסתו אלא הכי גריס א\\\"ל רב אשי לרב אחא בעיא דרבא היכי מתניתו לה א\\\"ל אנן בשינוי בעלים מתנינן לה והכי מתנינן לה בעי רבא חטאת חלב ששחטה וכו':\",1,0],[8,365,15,9,\"שחטה לשם מת כשירה וכו'. מימרא דרבא שם:\",1,0],[8,365,15,9,\"שחטה לשם מי שאינו חייב קרבן כלל וכו'. גם זה מימרא דרבא שם (דף ז') ולקמן בסמוך אבאר:\",2,0],[8,365,15,10,\"שחטה לשמה וכו'. שם (זבחים ט':) פלוגתא דר\\\"י ור\\\"ל ופסק כר\\\"י דהלכה כוותיה לגבי ר\\\"ל ועוד דר\\\"נ אמר פסולה ורבה אמר כשירה והדר ביה רבה מק\\\"ו דרב אשי:\",1,0],[8,365,15,11,\"הפסח ששחטו במחשבת שינוי השם וכו'. אפשר שהטעם מדכתיב ביה לה' משמע דלשם חולין פסול:\",1,0],[8,365,15,11,\"בד\\\"א ששחטו בזמנו וכו' אבל אם שחטו שלא בזמנו במחשבה שלא לשמו כשר. משנה בריש זבחים כל הזבחים שנזבחו שלא לשמן כשרים אלא שלא עלו לבעלים לשם חובה חוץ מן הפסח והחטאת הפסח בזמנו והחטאת בכל זמן.\",2,0],[8,365,15,11,\"ומ\\\"ש אפילו שחטו בשחרית וכו'. שם במשנה (דף י\\\"ב) פלוגתא דתנאי ופסק כבן בתירא דפסל משום דשקלי וטרו אמוראי אליביה והראב\\\"ד שכתב על דברי רבינו א\\\"א זהו כבן בתירא ור' יהושע מכשיר עכ\\\"ל. משיג עליו למה הניח ר' יהושע דהוא מארי דגמרא טפי וכבר כתבתי טעם לדבר.\",3,0],[8,365,15,11,\"ומ״ש שלא לשם בעליו נעשה כמי שאין לו בעלים בזמנו ופסול. בפסחים פרק תמיד נשחט (פסחים דף ס':) בעיא דאיפשיטא:\",4,0],[8,365,15,12,\"פסח ששחטו (שלא) לשמו בארבעה עשר קודם חצות פסול וכו'. נתבאר בסמוך ואיני יודע למה שנאו. וצ\\\"ל דהאי שלא טעות סופר הוא ומוכיחים הדברים כן מדמסיים בה פסול לפי שאינו זמנו והיינו טעמא לא שייר אלא בלשמו והוא מדאמר ר\\\"י פוסל היה בן בתירא בפסח ששחטו [בארבעה עשר] שחרית בין לשמו בין שלא לשמו לשמו דבעי בין הערביים ובפ' תמיד נשחט שם תנן שחטו (לפסח) קודם חצות פסול שנאמר בו בין הערבים:\",1,0],[8,365,15,12,\"עברה שנתו ושחטו בזמנו וכו' הרי אלו כשרים וכו'. בפירקא קמא דזבחים (דף י״א:) ובפסחים פרק תמיד נשחט (פסחים דף ס״ב:) פלוגתא דרבי אליעזר ורבי יהושע ופסק כרבי יהושע:\",2,0],[8,365,15,13,\"תודה ששחטה לשם שלמים וכו'. פירקא קמא דזבחים (דף ד'):\",1,0],[8,365,15,14,\"עולה ששחטה על מי שאינו מחוייב קרבן כלל וכו'. נלמד ממ\\\"ש בסמוך שאמר רבא גבי חטאת בפ\\\"ק דזבחים (דף ז') אלא שיש לגמגם ששם נתן טעם שמא מחוייב הוא ואינו יודע וכאן נתן טעם שא\\\"א שלא יהיה חייב כפרה לשמים וכו' ובגמרא נתנו טעם זה ולא הראשון. ומשמע לי דרבינו הוה גריס בגמרא תרווייהו כלשון שכתבם והוי כיהיב תרי טעמי חדא שמא מחוייב הוא ואינו יודע ועוד שודאי הוא מחוייב שאין לך אדם מישראל וכו':\",1,0],[8,365,15,15,\"עולה הבאה לאחר מיתה וכו'. מימרא דרבא בפרק קמא דזבחים (דף ז':) ואע\\\"ג דאיכא מאן דפליג עליה התם פסק כרבא דבתרא הוא:\",1,0],[8,365,15,16,\"שני כבשי עצרת ששחטן לשם אילים וכו' עד מפני שהיא עקירה בטעות. בפרק התכלת (מנחות דף מ״ט) תני רבה בר בר חנה קמי דרב כבשי עצרת ששחטן לשם אילים כשירים ולא עלו לבעלים לשם חובה א״ל רב עלו ועלו אמר רב חסדא מסתברא מילתיה דרב בכסבור אילים ושחטן לשם כבשים שהרי כבשים לשם כבשים נשחטו אבל כסבור אילים ושחטן לשם אילים לא עקירה בטעות הויא עקירה רבא אמר עקירה בטעות לא הויא עקירה. ופסק כרבא דבתרא הוא ועוד דאביי משמע התם דסבר כוותיה ומשמע דדוקא משום דהוי עקירה בטעות קאמר רבא דעלו לבעלים אבל אם לא היתה בטעות לא עלו:\",1,0],[8,365,15,17,\"אשם מצורע ששחטו שלא לשמו וכו'. ברייתא בפ\\\"ק דמנחות (דף ה') ובפרק שתי מדות:\",1,0],[8,365,15,18,\"ומ\\\"ש כבש הבא עם העומר ששחטו שלא לשמו וכו'. שם (דף פ\\\"ט) א\\\"ר יוחנן אשם מצורע ששחטו שלא לשמו טעון נסכים שאם אי אתה אומר כן פסלתו מתקיף לה רב מנשיא בר גדא אלא מעתה כבש הבא עם עומר ששחטו שלא לשמו תהא מנחתו כפולה שאם אי אתה אומר כן פסלתו ותמיד של שחר ששחטו שלא לשמו יהא טעון שתי גזירים בכהן אחד שאם אי אתה אומר כן פסלתו וכו' אין ה\\\"נ אלא אמר אביי חדא מינייהו נקט רבי אבא אמר בשלמא הנך עולות נינהו אי לא חזי לעולת חובה קרבי לעולת נדבה אלא הכא אי לא מוקמת ליה במילתיה אשם נדבה מי איכא ופסק כר' אבא דמסתבר טעמיה:\",1,0],[8,365,15,19,\"שני כבשי עצרת ששחטן שלא לשמן וכו' עד להקטיר אימורים בערב. ברייתא בפ' התכלת (מנחות דף מ״ז):\",1,0],[8,365,15,20,\"וכן שלמי נזיר ששחטן שלא לשמן אע\\\"פ שלא וכו'. שם תני לוי:\",1,0],[8,365,15,20,\"וכן אשם נזיר ואשם מצורע ששחטן שלא לשמן וכו'. גם זה שם תני לוי ובפ\\\"ק (דף ד') דאמר רב וכו' אשם נזיר ואשם מצורע ששחטן שלא לשמן פסולים ואסיקנא בתיובתא:\",2,0],[8,365,16,1,\"כבר ביארנו וכו' ואם חשב מחשבת הזמן הקרבן פגול עד אין זה פגול אלא פסול. משנה בפ\\\"ב דזבחים (דף כ\\\"ט).\",1,0],[8,365,16,1,\"ומ\\\"ש וה\\\"ה בעופות. משנה בפ' קדשי הקדשים (דף ס\\\"ד:).\",2,0],[8,365,16,1,\"ומ\\\"ש ובמנחות. משנה בפ\\\"ק דמנחות:\",3,0],[8,365,16,2,\"המחשב באחת מד' עבודות וכו' עד הרי הקרבן פסול ואינו פגול. משנה בפרקים הנזכרים.\",1,0],[8,365,16,2,\"ומ\\\"ש וכן אם עירב המחשבה בהקטרה ה\\\"ז פסול ואינו פגול. גם זה משנה בפרקים הנזכרים לאכול כחצי זית להקטיר כחצי זית כשר שאין אכילה והקטרה מצטרפין:\",2,0],[8,365,16,3,\"חשב לאכול או להקטיר וכו'. מתבאר ממה שיבא:\",1,0],[8,365,16,4,\"חשב על חצי זית במחשבת הזמן וכו'. פלוגתא דאמוראי בסוף פרק שני דזבחים (דף ל\\\"א) ופסק כרבא:\",1,0],[8,365,16,4,\"וכן אם חשב על חצי זית וכו'. שם מימרא דרב אשי:\",2,0],[8,365,16,5,\"חשב על הדמים הניתנים למטה וכו' ועירב עמהם מחשבת הזמן ה\\\"ז פגול. ברייתא שם (כ\\\"ז).\",1,0],[8,365,16,5,\"ומ\\\"ש ואם חשב עמהם וכו'. ברייתא הנזכרת ופשוט הוא.\",2,0],[8,365,16,5,\"ומ\\\"ש לבדה לאו דוקא דה\\\"ה דאפי' עירב עם מחשבת המקום מחשבת הזמן אינו פגול כמו שנתבאר:\",3,0],[8,365,16,6,\"חשב על הדם הניתן למעלה וכו' עד הרי זה פסול ואינו פגול. שם:\",1,0],[8,365,16,6,\"כתב הראב\\\"ד חשב על הדם א\\\"א כדומה לי שיש כאן שבוש עכ\\\"ל. טעמו מדאמרינן התם בגמרא דטעמא מידי דהוה אמחשבת הינוח ופירש\\\"י ור' יהודה היא דפסל ליה, ורבינו פסק דלא כר' יהודה ונמצא סותר מ\\\"ש פה ולכן כתב שיש כאן שיבוש. וי\\\"ל שרבינו אינו מפרש כפירוש רש\\\"י אלא לפי שהקשה א\\\"ה איפסולי נמי לא ליפסול אהדר ליה דכי היכי דאשכחן לר' יהודה במחשבת הינוח דאע\\\"ג דלא הוי פגול מיפסיל ה\\\"נ לרבנן דחשב על הדם הניתן וכו' אע\\\"פ שאינו פגול מיפסיל.\",2,0],[8,365,16,6,\"ומ\\\"ש ומאחר שביארנו וכו' למה לא יהיה פגול במחשבה זו וכו' עד הרי זה פסול ואינו פגול. שם בדף הנזכר:\",3,0],[8,365,16,7,\"חשב מחשבת זמן בשעת קמיצה וכו' אינה פגול עד שיחשב מחשבת הזמן בכל המתיר. משנה בפ\\\"ב דמנחות (דף ט\\\"ז) פלוגתא דת\\\"ק ור\\\"מ ופסק כת\\\"ק. ומה שכתוב בדברי רבינו או בשעת זריקתן ט\\\"ס הוא וצריך למוחקו ולכתוב במקומו או בשעת הקטרתן:\",1,0],[8,365,16,8,\"חשב בשעת הקטרת הקומץ וכו'. פלוגתא דאמוראי בספ\\\"ב דמנחות (דף י\\\"ז) ופסק כמ\\\"ד דאין הקטרה מפגלת הקטרה משום דרב וכמה אמוראי סברי הכי.\",1,0],[8,365,16,8,\"ומ\\\"ש וכן אם הקטיר הלבונה לבדה או הקומץ לבדו וכו'. כבר נתבאר בסמוך דהלכה כת\\\"ק דאמר אין מפגלין בחצי מתיר.\",2,0],[8,365,16,8,\"ומ\\\"ש אבל אם הקטיר הקומץ לבדו וחשב שיקטיר לבונה למחר ואח\\\"כ הקטיר הלבונה וחשב שיאכל השירים למחר הרי זה פגול וכו'. שם הקטיר קומץ להקטיר לבונה ולבונה לאכול שירים למחר פיגול מאי קמ\\\"ל אי הקטרה מפגלת הקטרה קמ\\\"ל לימא הקטיר קומץ להקטיר לבונה אי מפגלין בחצי מתיר קמ\\\"ל לימא הקטיר קומץ (להקטיר לבונה) ולאכול שירים למחר אי תרוייהו קמ\\\"ל לימא הקטיר קומץ להקטיר לבונה ולאכול שירים למחר אמר רב אדא בר אהבה לעולם קסבר אין הקטרה מפגלת הקטרה ואין מפגלין בחצי מתיר ושאני הכא דפשטא לה מחשבה בכולה מנחה. ופירש\\\"י מאי קמ\\\"ל קס\\\"ד דמשום חדא מהנך מחשבות מיפגלא וחד מינייהו אשמעינן ופיגול משום מחשבה להקטיר לבונה למחר הוא ולא משום לאכול שירים דאין מפגלין בחצי מתיר, לימא הקטיר קומץ להקטיר לבונה ולא לימא לאכול שירים כיון דההיא מחשבה לא מהניא למה לי מחשבה בהדי קמייתא ואי פגול משום לאכול שירים הוא דמפגלין בחצי מתיר אבל להקטיר לבונה לא מהניא למה לי לצרפה בהדה. ואי תרווייהו קמ\\\"ל ואי לאכול קאמר שלא חישב באחד מהן לימא להקטיר לבונה ולאכול שירים דמשמע תרתי מילי וכו'. דפשטה לה מחשבה לכולה מנחה ואע\\\"ג דלא מיפגיל בחדא מינייהו השתא דחשיב בתרווייהו מיפגלא:\",3,0],[8,365,16,9,\"הקטיר כדי שומשום מן הקומץ וכו'. שם (דף ט\\\"ז:) הקטיר שומשום לאכול שומשום עד שכלה קומץ כולו רב חסדא ורב המנונא ורב ששת חד אמר פגול וחד אמר פסול וחד אמר כשר, ורבינו לא פסק כמ\\\"ד כשר משום דהוי ספיקא ולחומרא ולא פסק כמ\\\"ד פגול וחייב כרת משום דספק עונשים להקל. ועי\\\"ל דטעמיה משום דמ\\\"ד כשר ה\\\"ל חד לגבי תרי דפסלי ומ\\\"ד דחייב כרת הו\\\"ל חד לגבי תרי דפטרי ליה:\",1,0],[8,365,16,10,\"מנחת חוטא וכו'. ברייתא פרק כל המנחות (מנחות דף כ\\\"ט):\",1,0],[8,365,16,11,\"שירים שחסרו בין קמיצה להקטרה וכו'. בסוף פרק א' דמנחות (דף י\\\"ב) בעיא דלא איפשיטא:\",1,0],[8,365,17,1,\"כל הדמים הניתנים וכו' עד היא העיקר. משנה בר״פ ב״ש (זבחים דף ל״ו:).\",1,0],[8,365,17,1,\"ומ\\\"ש אבל כל הדמים הניתנים על מזבח הפנימי וכו'. שם במשנה כל הניתנים על מזבח הפנימי אם חיסר אחת מהמתנות לא כיפר לפיכך אם נתנן כולן כתקנן ואחת שלא כתקנה פסול ואין בו כרת. ופירש\\\"י לפיכך הואיל וכולן מתירות אין זו מתרת בלא זו ואין מפגלת בל\\\"ז אם נתנם כולם בשתיקה ואחת שלא כתקנה כגון שנתנה במחשבת חוץ למקומו או חוץ לזמנו פסול שלא כיפר בראשונות ואין בו כרת שאין האחרונה מפגלתו שאין מפגלין בחצי מתיר:\",2,0],[8,365,17,3,\"טבילת אצבע וכו'. בפרק קמא דזבחים (דף י\\\"ג):\",1,0],[8,365,17,4,\"היה עומד בעזרה וכו' עד שהרי חשב בחוץ בדבר הנעשה בחוץ. בפ״ב דמנחות (דף י״ד) ואיתיה נמי בפרק ב״ש (זבחים דף מ״ג):\",1,0],[8,365,17,7,\"התודה מפגלת את הלחם וכו' עד והכבשים אינם פגול. משנה בפרק שני דמנחות (דף ט\\\"ו):\",1,0],[8,365,17,8,\"ומ\\\"ש חשב באחת מארבע עבודות וכו'. שם ע\\\"א בעא מיניה ר\\\"א מרב השוחט את התודה לאכול למחר כזית ממנה ומלחמה מהו. ופירש רש\\\"י ממנה ומלחמה כחצי זית מזה וכחצי זית מזה. לאיפגולי תודה לא מיבעיא לי השתא כולו מלחמה לא מיפגלא ממנה ומלחמה מיבעיא כי קא מיבעיא לי לאיפגולי לחם מי מצרף תודה לאיפגולי לחם או לא א\\\"ל אף בזו הלחם מפוגל והתודה אינה מפוגלת וכו' ואיכא דמתני לה אכבשים בעא מיניה השוחט את הכבשים לאכול למחר כזית מהם ומלחמה מהו וכו' מי מצטרפי כבשים לאיפגולי לחם או לא אמר ליה אף בזו הלחם מפוגל והכבשים אינם מפוגלים וכו' מאן דמתני לה אתודה כ\\\"ש אכבשים ומאן דמתני לה אכבשים כבשים הוא דהוזקקו זה לזה לתנופה אבל תודה דלא הוזקקה זה לזה לתנופה לא. ופירש\\\"י אבל תודה לא פשיטא ליה דליפגול לחם. ופסק כלישנא דתודה פשט ליה וכ\\\"ש לכבשים ואע\\\"ג דלישנא קמא הוא משום דכיון דאיכא תרי לישני ה\\\"ל ספיקא ולחומרא. והר\\\"י קורקוס ז\\\"ל כתב טעם אחר דלא שבקינן מאי דפשיטא להאי לישנא למנקט ספיקא דאידך לישנא:\",1,0],[8,365,17,9,\"המקטיר שני בזיכי לבונה וכו'. מתבאר ממה שיבא:\",1,0],[8,365,17,11,\"השוחט שני כבשי עצרת וכו' עד שני הסדרים פיגול. משנה בפ\\\"ב דמנחות (דף י\\\"ג:) פלוגתא דתנאי ופסק כחכמים:\",1,0],[8,365,17,12,\"וכן אם חשב מחשבת הזמן וכו'. שם (דף י\\\"ד:) בעיא דר\\\"י ופשטוה מברייתא:\",1,0],[8,365,17,13,\"אבל אם נטמאת אחת משתי החלות וכו'. גם זה שם במשנה פלוגתא דתנאי ופסק כחכמים.\",1,0],[8,365,17,13,\"ומ\\\"ש בין לפני זריקה בין לאחר זריקה. שם א\\\"ר אלעזר מחלוקת לפני זריקה אבל לאחר זריקה דברי הכל וכו' והטהור יאכל:\",2,0],[8,365,17,14,\"חשב בעבודת אחד משני הכבשים וכו'. ג\\\"ז שם במשנה פלוגתא דתנאי ופסק כחכמים:\",1,0],[8,365,17,15,\"שחט אחד וחשב לאכול כחצי זית מחלה זו למחר ושחט השני וחשב לאכול חצי זית מחלה שנייה למחר הרי אלו מצטרפין לפגול. כ\\\"ה הגירסא הנכונה והדין בפ\\\"ב דמנחות (דף י\\\"ד) פלוגתא דרבי ורבנן ופסק כחכמים.\",1,0],[8,365,17,15,\"ומ\\\"ש וה\\\"ה בשני הבזיכים עם שני הסדרים. נלמד מהדין שכתב בסמוך:\",2,0],[8,365,17,16,\"חשב באחד משני הכבשים וכו'. משנה בפרק ב' דמנחות (דף ט\\\"ז):\",1,0],[8,365,17,17,\"ומ\\\"ש שחט אחד מהם וחשב בשעת שחיטתו שיאכל מבשר השני למחר וכו'. גם זה שם במשנה ולשונה שיאכל מחבירו למחר ובעי ר' אבא זוטי (דף ט\\\"ו) מחבירו כבש חבירו משמע ולא מיפגיל או דילמא לחם משמע ומפגיל ליה ואתינן למפשטה ממתניתין ודחי דילמא דפריש ואמר מחבירו כבש ולכך כתב רבינו מבשר דליכא לספוקי בלחם. ויש לתמוה למה השמיט רבינו דין האומר מחבירו:\",1,0],[8,365,17,18,\"שני כבשי עצרת אין מקדשין את הלחם אלא בשחיטה וכו' שחטו לשמן וכו' הלחם קדוש ואינו קדוש. כך היא הגירסא הנכונה בלשון רבינו והוא בפרק התכלת (מנחות דף מ״ז) פלוגתא דתנאי ופסק כרבי מחבירו. ועוד ששם העמידו דר״ע ור״א כרבי ס״ל והא דתניא קדוש ואינו קדוש מפרש רבא דהיינו לומר קדוש ואינו ניתר לכהנים:\",1,0],[8,365,17,19,\"שתי הלחם שיצאו בין שחיטה לזריקה וכו'. שם פלוגתא דתנאי ופסק כר\\\"ע. וכתב רבינו אע\\\"פ שהם בחוץ בגמרא מתקיף לה ר\\\"פ ממאי דכי איתנהו אבראי פליגי דילמא בדאיתנהו אבראי כ\\\"ע לא פליגי דאין זריקה מועלת ליוצא ובהדר עיילינהו פליגי. ומה שרצו להכריח מדרב גידל שאמרו ולאו איתותב רב גידל אעפ\\\"כ תפס רבינו דבדרך דחייה אמר כן ר\\\"פ אי נמי דגריס רבינו ולאו איתותב רב גידל בניחותא כמו שכתבו התוספות:\",1,0],[8,365,17,20,\"כבשי עצרת ששחטן לשמן וכו'. שם (דף מ\\\"ה) א\\\"ר יוחנן הכל מודים שאם הוזקקו זה לזה שמעכבין זה את זה ואיזהו זיקה שלהן שחיטה. ופירש\\\"י שאם הוזקקו זה לזה שהיו ביחד ואח\\\"כ אבד לחם או כבשים שמעכבים זה לזה והנותר לפנינו יצא לבית השריפה דנדחה באבוד חבירו.\",1,0],[8,365,17,20,\"ומ\\\"ש זרק דמן במחשבת הזמן אחר שאבד הלחם הרי אלו ספק אם הותרו באכילה או לא. שם (דף מ\\\"ז:) בעא מיניה ר' ירמיה מר' זירא כבשי עצרת ששחטן לשמן ואבד הלחם מהו שיזרקו דמן לשמן להתיר בשר באכילה א\\\"ל יש דבר שאינו כשר לשמו וכשר שלא לשמו ולא והרי פסח וכו' והרי תודה שאני תודה דרחמנא קרייה שלמים. ופירש\\\"י מהו שיזרוק דמן שלא לשמן אלא לשם שלמים להתיר בשר באכילה דודאי לשמן לא הוו כדאמרינן לעיל הכל מודים שאם הוזקקו זה לזה מעכבין זה את זה עכ\\\"ל. ומשמע דכיון דלא אשכחן מידי ה\\\"ל לתפוס בתמיהתו של ר' זירא ולומר דפסול ולפיכך יש לתמוה על רבינו שפסק דהוי ספק. וכתב הר\\\"י קורקוס ז\\\"ל שסובר רבינו דכיון דלא בדרך פשיטות אתמר בעיין לא איפשיטא. ודע שמ\\\"ש בספרי רבינו וזרק דמן במחשבת הזמן ט\\\"ס הוא וצריך להגיה וזרק דמן שלא לשמן. ומוכרח הוא דאי כגירסת הספרים אטו מחשבת הזמן גורמת היתר אכילה. והנגיד רבינו יהושע מבני בניו של רבינו ביאר הלכה זו בתשובה וז\\\"ל כששחטן לשמן וזרק דמן לשמן אחר אבד הלחם היו שני הכבשים פסולים להעדר הלחם לפי שהלחם מעכב את הכבשים כמו שנתבאר בפ\\\"ח וכשאבד הלחם נפסלו הכבשים וכשאבד הלחם תחלה הנה אין לשחיטת כבשי עצרת תכלית כלל וכאילו שחט חולין ולכן אם שחטן קודם שיאבד הלחם וזרק דמן במחשבת הזמן אחר אבידת הלחם היה זה אצל החכמים ספק אם הם חולין לגמרי ויותרו לפי שנזרק דמן אחר שאבד הלחם ואין כאן פגול או מאחר ששחטן קודם שיאבד הלחם לא יותרו באכילה ולכן היה ספק עכ\\\"ל:\",2,0],[8,365,18,1,\"כל המחשב מחשבה שאינה נכונה בקדשי' וכו'. בסוף פ\\\"ב דזבחים [דף כ\\\"ט]:\",1,0],[8,365,18,2,\"ומ\\\"ש ואעפ\\\"כ אינו לוקה אין המחשב' מעשה. פשוט הוא ומבואר סוף פרק ב' דזבחים:\",1,0],[8,365,18,4,\"כל קרבן שנאמר שהוא פסול וכו' עד הרי הם בכלל כל תועבה. בספרי פרשת ראה:\",1,0],[8,365,18,5,\"ומ\\\"ש עד שיולד להם מום אחר. כחכמים בפ\\\"ה דבכורות (דף ל\\\"ד):\",1,0],[8,365,18,6,\"כל קרבן שנתפגל במחשבת הזמן וכו'. משנה בריש כריתות.\",1,0],[8,365,18,6,\"ומ\\\"ש שנאמר והנפש האוכלת ממנו עונה תשא. שם בגמרא:\",2,0],[8,365,18,8,\"אין חייבין כרת אלא על אכילת דברים שהותרו וכו' עד והקטורת והדם. בפרק ב״ש (זבחים דף מ״ג) משנה.\",1,0],[8,365,18,8,\"ומה שכתב והיין בין יין הבא עם הנסכים בין יין הבא בפני עצמו. שם במשנה גבי אלו דברים שאין חייבין עליהם משום פגול תני והנסכים הבאים בפנ\\\"ע דברי ר\\\"מ וחכ\\\"א אף הבאים עם הבהמה ופסק כחכמים.\",2,0],[8,365,18,8,\"ומ\\\"ש ולוג שמן של מצורע. שם במשנה ר\\\"ש אומר אין חייבין עליו משום פיגול ור\\\"מ אומר חייב עליו משום פיגול שדם האשם מתירו ופסק כר\\\"ש דמיקל דלית לן לחיובי מספיקא ועוד דמסתבר טעמיה כמו שביאר רבינו בסמוך.\",3,0],[8,365,18,8,\"ומ\\\"ש וא\\\"ת והלא דם האשם מתירו אינו תלוי בו וכו'. בפ\\\"ב דמנחות (דף ט\\\"ו):\",4,0],[8,365,18,9,\"אסור להותיר וכו' שנאמר בקרבן תודה לא תותירו ממנו עד בקר. בפרשת אמור ובתורת כהנים פרשת צו מרבה כל הקרבנות.\",1,0],[8,365,18,9,\"ומ״ש אינו לוקה שהרי הכתוב ניתקו לעשה שנאמר והנותר ממנו עד בקר וכו'. בקרבן פסח בס״פ אותו ואת בנו (חולין דף פ״ג) לא תותירו וכו' והנותר באש תשרופו בא הכתוב ליתן עשה אחר לא תעשה לומר שאין לוקין עליו דברי ר״י רבי יעקב אומר לא מן השם הוא זה אלא משום [דהוה ליה לאו שאין בו מעשה וכל] לאו שאין בו מעשה אין לוקין עליו. ויש לתמוה על רבינו מאחר דקי״ל דלאו שאין בו מעשה אין לוקין עליו אמאי שבק האי טעמא ונקט טעמא אחרינא, וי״ל דלרבותא נקט לומר דאפילו אם היה לאו שיש בו מעשה לא היו לוקין עליו:\",2,0],[8,365,18,10,\"האוכל כזית מבשר קדשים וכו'. משנה בריש כריתות.\",1,0],[8,365,18,10,\"ומה שכתב שנאמר ואוכליו עונו ישא. שם (דף ה') בגמ' יליף לה בג\\\"ש נאמר כאן ואוכליו עונו ישא ונכרתה ולהלן הוא אומר והנפש האוכלת ממנו עונה תשא:\",2,0],[8,365,18,10,\"ומאימתי יתחייב כרת על אכילת הנותר וכו'. בפרק איזהו מקומן (זבחים דף נ״ז:) כר״י דת״כ ולאפוקי מחזקיה:\",3,0],[8,365,18,10,\"והיכן הזהיר הכתוב על הפגול ועל הנותר במלואים וכו'. פ' אלו הן הלוקין (מכות דף י״ח:):\",4,0],[8,365,18,11,\"ומ\\\"ש והפגול והנותר מצטרפים זה עם זה לכזית. בפ\\\"ד דמעילה (דף י\\\"ז.) במשנה הפגול והנותר אין מצטרפין (זה עם זה) ובגמרא אמר רב יהודה אמר שמואל ל\\\"ש אלא לטומאת ידים דמדרבנן היא אבל לענין אכילה מצטרפין דתניא ר\\\"א אומר לא יאכל כי קדש הם כל שבקדש פסול בא הכתוב ליתן לא תעשה על אכילתו.\",1,0],[8,365,18,11,\"ומ\\\"ש וכל הפגולין והנותרים מצטרפין. שם (דף ט\\\"ו) במשנה כל הפגולים מצטרפין זה עם זה כל הנותרים מצטרפין זה עם זה וכבר נתבאר בסמוך דלענין אכילה פגול ונותר מצטרפין זה עם זה:\",2,0],[8,365,18,12,\"אסור לטמא את הקדשים או לסבב להם טומאה. בפרק ג' דזבחים (דף ל״ג:) ובפ' אלו הן הלוקין (מכות דף י״ד) נחלקו רבי יוחנן ור״ל במטמא קדשים ר״ל אמר לוקה ור' יוחנן אמר אינו לוקה ומשמע דאיסורא מיהא איכא:\",1,0],[8,365,18,12,\"אבל אדם טהור שאכל כזית מקדשים שנטמאו לוקה. בפרק כל שעה (פסחים דף כ״ד:) והבשר כל טהור יאכל בשר למה לי לרבות אימורים, ופירש״י אימורים שנטמאו ואכלן הטהור ומקשי אימורים מהתם נפקא דתניא והנפש אשר תאכל בשר מזבח השלמים אשר לה' לרבות את האימורים התם טומאת הגוף בכרת הכא טומאת בשר בלאו, ולפ״ז הא דתנן בפרק השוחט ומעלה טהור שאכל טמא פטור שאינו חייב אלא על טומאת הגוף לענין כרת קאמר אבל מילקא לקי גם על טומאת בשר. ובפרק כל הפסולים (זבחים דף ל״ד) אתמר טמא שאכל בשר קדש לפני זריקה ר״ל אמר לוקה רבי יוחנן אמר אינו לוקה וכו' אמר אביי [מחלוקת] בטומאת הגוף אבל בטומאת בשר [ד״ה] לוקה וכו' ורבא אמר אבל בטומאת בשר ד״ה אינו לוקה וידוע דהלכה כרבא. ולפיכך צ״ל שמ״ש כאן רבינו שטהור שאכל כזית מקדשים שנטמאו לוקה באוכל אחר זריקה:\",2,0],[8,365,18,12,\"וה\\\"ה לשאר הקרבנות. כלומר דבשר לאו דוקא דה\\\"ה ללבונה וכדתנן בספ\\\"ג דמעילה (דף י\\\"ג) ובספ\\\"ד דזבחים (מ\\\"ו:) מרבה לה מוהבשר:\",3,0],[8,365,18,12,\"אחד קדשים שנטמאו לפני כפרה וכו': ואינו לוקה אלא האוכל אחר זריקת דמים וכו'. פלוגתא דר' יוחנן ור״ל בפ' כל הפסולין (זבחים דף ל״ד) ופסק כר' יוחנן:\",4,0],[8,365,18,13,\"כל אדם שנטמא וכו'. בר״פ השוחט ומעלה (דף ק״ו) תנן הטמא שאכל בין קדש טמא בין קדש טהור חייב. ומה שהתנה שצריך שיהא חייב על ביאת המקדש אפשר שהטעם מדמקיש קדש למקדש כדאיתא בפרק כל הפסולים (זבחים דף ל״ג:).\",1,0],[8,365,18,13,\"ומ\\\"ש במזיד הרי זה נתחייב כרת וכו' ואם אכל בשגגה מביא קרבן עולה ויורד. משנה בריש כריתות ומפורש בתורה.\",2,0],[8,365,18,13,\"ומ״ש ומנין שאינו מדבר אלא בטומאת הגוף וכו'. בפ' ב״ש (נזיר דף ל״ג:) מייתי לה מקראי אחריני ורבי מייתי לה מהאי קרא ומשמע לרבינו דמהאי קרא משתמע טפי:\",3,0],[8,365,18,13,\"והיכן הזהיר על עון זה ביולדת וכו'. בפרק כל הפסולין (זבחים דף ל״ג:) ובפרק אלו הן הלוקין (מכות דף י״ד) אמר ר״ל הכי ואע״ג דר״י פליג ויליף לה מקרא אחרינא כתב רבינו כר״ל משום דתניא כוותיה:\",4,0],[8,365,18,14,\"והאוכל קדש אחר שטבל וכו'. בפי\\\"א דמס' פרה תנן גבי טעון ביאת מים מן התורה אם בא אל המקדש בין לפני ביאתו בין לאחר ביאתו חייב ומשמע דה\\\"ה לאוכל קדש ומשמע לרבינו דהיינו דוקא לענין מלקות אבל פטור מכרת מדכתיב וטומאתו עליו ונכרתה דמשמע דלא מיחייב כרת אלא בזמן שכל טומאתו עליו:\",1,0],[8,365,18,14,\"וכתב הראב\\\"ד לוקה ואינו חייב [כרת] א\\\"א זה שיבוש שכבר כתבנו למעלה שהוא בכרת עכ\\\"ל. וכבר כתבתי בזה בפ\\\"ג מהלכות ביאת המקדש:\",2,0],[8,365,18,15,\"היה טמא בטומאת וכו'. פשוט הוא ואיתיה במשנה פי\\\"א ממסכת פרה:\",1,0],[8,365,18,16,\"אינו חייב כרת וכו'. משנה בפ\\\"ב דמעילה (דף י').\",1,0],[8,365,18,16,\"ומ״ש אבל אם אכל את הבשר קודם זריקת הדם אינו לוקה וכו'. בפרק כל הפסולים (זבחים דף ל״ג:) פלוגתא דר״י ור״ל ופסק כר״י.\",2,0],[8,365,18,16,\"ומ\\\"ש זה הכלל כל שיש לו מתירים אין חייבין עליו וכו' עד חייבים עליו משום טומאה. משנה בפ\\\"ב דמעילה (דף י').\",3,0],[8,365,18,16,\"ומ\\\"ש אפי' נטמא הבשר קודם שיטמא האוכל וכו'. בפרק השוחט ומעלה (דף ק\\\"ח) פלוגתא דר\\\"י הגלילי ורבנן ופסק כרבנן.\",4,0],[8,365,18,16,\"ומ״ש וכן אם אכל מבשר חטאות הנשרפות והוא טמא וכו'. משנה פ״ב דמעילה (דף ט') פרים [הנשרפים] ושעירים הנשרפים מועלים בהם משהוקדשו וכו' הוזה דמן חייבין עליהן משום פגול נותר וטמא ומייתי לה בפ' כל הפסולים (זבחים דף ל״ה:):\",5,0],[8,365,18,17,\"כבר נתבאר לך שאף דברים וכו'. משנה בפ' ב״ש (זבחים דף מ״ה:) דברים שאין חייבים עליהם משום פגול חייבין עליהם משום נותר ומשום טמא חוץ מן הדם ובגמרא יליף לה מקראי:\",1,0],[8,365,18,19,\"טמא שאכל אימורים חייב כרת אכל פסח שלא נצלה וכו'. בספ\\\"ג דזבחים (דף ל\\\"ז:) אמר רב חסדא מרגלא בפומיה דרב דימא בר חיננא בשר פסח שלא הוצלה ולחמי תודה שלא הורמה חייבין עליהם משום טומאה אמר רבא תדע דתניא אשר לה' לרבות אימורי קדשים קלים לטומאה אלמא אע\\\"ג דלאו בני אכילה נינהו חייבין עליהם משום טומאה ה\\\"נ אע\\\"ג דלאו בני אכילה נינהו חייבין עליהם משום טומאה ולא היא התם אימורי קדשים קלים חזו לגבוה לאפוקי בשר פסח שלא הוצלה ולחמי תודה שלא הורמה דלא חזו לא לגבוה ולא להדיוט, לישנא אחרינא אימורים לא חזו ולא היא הנך חזו למילתייהו הני לא חזו כלל, דמשמע לכאורה דכיון דאסיקנא ולא היא אידחייא לה מהלכתא ויש לתמוה על רבינו שפסקה. וצ\\\"ל שרבינו סובר דלא אמרינן ולא היא אלא לדחויי ראייה דבעא רבא לאתויי מאימורי קדשים קלים אבל עיקר דינא דאמר רב חסדא דמרגלא בפומיה דרב דימא בר חיננא לא אידחי ועוד דרבא הכי סבר ותיבת אבל שכתב רבינו לעיל קאי שכתב אינו חייב כרת על קדש שיש לו מתירים עד שיאכל ממנו אחר שקרבו מתיריו ולפ\\\"ז הוה ס\\\"ד דה\\\"ה לפסח שלא נצלה ולחמי תודה שלא הורמה חלתן מאחר שאינם ראויין כמות שהן הם דומים לאוכל קדש קודם שיקרבו מתיריו ולא ליחייב כרת עלייהו קמ\\\"ל:\",1,0],[8,365,18,19,\"אי אפשר שיתחייב אדם על וכו'. בפ\\\"ג דכריתות (דף י\\\"ד) אהא דתנן יש אוכל אכילה אחת וחייב עליה ד' חטאות פריך וניתני חמש חטאות ונוקמה כגון [דאכל] כזית פגול בחדא בהמה קמיירי בשתי בהמות לא קמיירי ונותר ופגול בחדא בהמה לא משכחת לה. ופירש\\\"י ונותר ופגול בחדא בהמה ליכא דפגול אינו אלא בארבע עבודות של דם הילכך מדפגלה לא חזיא לא לאכילת אדם ולא לאכילת מזבח הילכך לא חייל עלה נותר. ודע דבתר הכי פריך אלמה לא משכחת לה כגון שהעלה אבר פגול לגבי מזבח דפקע פגוליה מינה וה\\\"ל נותר וכדאמר עולא קומץ פגול שהעלה לגבי מזבח פקע פגולו ממנו וה\\\"ל נותר באבר אחד קא מיירי בשני איברים לא קא מיירי, ומשמע לי דה\\\"פ דההוא אבר פגול שהעלהו ע\\\"ג המזבח דפקע פיגוליה מיניה וה\\\"ל נותר תו לא מיחייב עליה משום פגול ואי בעית לחיובי על אכילה אחת משום פגול ומשום נותר צריך לאוקומי בשאכל חצי אכילה מאבר פגול זה שהעלהו ע\\\"ג המזבח וחצי אכילה משאר איברי בהמה הפגולה שלא העלם ע\\\"ג המזבח ובשני איברים לא קא מיירי מתני'. ויש לתמוה עליו שסתם דבריו ולא פירש דה\\\"מ באבר אחד אבל בשני איברים משכחת לה וצ\\\"ל דנקט לישנא דמתני' לבד:\",2,0],[8,365,18,20,\"הפגול והנותר והטמא וכו'. בפ' התערובת (זבחים דף ע״ח) פלוגתא דר״פ ור״א ופסק כר' אלעזר משום דרבא אותביה לר״פ ושני ליה בשינויי דחיקי. עוד דבירושלמי פ״ק דחלה איפלגו ר״י ור״ל במילתא ור״י סבר כר״א:\",1,0],[8,365,18,21,\"ופגול או נותר או טמא וכו'. בפרק ב״ש (זבחים דף מ״ג) מימרא דר״י ופריש לה ר' זירא:\",1,0],[8,365,18,21,\"ואימורים מצטרפים וכו'. ברייתא וגמ' דזבחים (דף ק\\\"ט):\",2,0],[8,365,18,22,\"זבח שנתפגל וכו'. משנה בפ\\\"ג דזבחים (דף ל\\\"ה).\",1,0],[8,365,18,22,\"ומ\\\"ש מן הצפרנים מן החרטום ומן הנוצה. נתבאר בפרק י\\\"ד:\",2,0],[8,365,18,23,\"אכל מן השליל או מן השליא וכו'. שם מימרא דר\\\"א:\",1,0],[8,365,18,23,\"כתב הראב\\\"ד א\\\"א דוקא בשפיגל הזבח וכו'. וכך מבואר שם בגמ' ואע\\\"פ שגם רבינו לא איירי אלא בשפיגל הזבח וכן מבואר בדבריו בפי\\\"ד מפני שכתב רבינו כאוכל משאר בשר הזבח נזהר הראב\\\"ד שלא נטעה לומר שדינן לגמרי כשאר בשר הזבח וכתב אבל במחשבת עצמן לא:\",2,0],[8,365,18,24,\"קדשי עכו״ם אין חייבים עליהם משום פגול ולא משום נותר וכו'. משנה בפ' ב״ש (זבחים דף מ״ה) פלוגתא דר״ש ור' יוסי ופסק כר״ש וצריך טעם למה. ואפשר שטעמו מדגרסינן בריש תמורה (דף ב':) דבעי רמי בר חמא עכו״ם מהו שימיר ולא אפשר לאוקומי הבעיא לר' יוסי וכמו שכתבו התוס' שם בתירוץ שני וכיון דרמי בר חמא בעי אליבא דר״ש אלמא הלכתא כוותיה ועוד דגמ' מפרש טעמיה בסתם. ויש מי שאומר שרבינו מפרש דמתני' דקתני דברי רבי שמעון ורבי יוסי מחייב לא קאי אלא אשוחטן בחוץ דסמיך ליה לא לאין חייבין עליהם משום פגול נותר וטמא דלעיל מיניה דההוא סתם מתני' היא:\",1,0],[8,365,18,24,\"וכן הלבונה והקטרת והעצים וכו'. משנה בפ' ב״ש (זבחים דף מ״ה:) דברים שאין חייבין עליהם משום פגול חייבין עליהם משום נותר וטמא חוץ מן הדם ר״ש מחייב בדבר שדרכו לאכול אבל כגון העצים והלבונה והקטרת אין חייבין עליהם משום טומאה, ופסק רבינו כר״ש ולא ידעתי למה וכבר השיגו הראב״ד וכתב לא משום פגול א״א זה לדעת ר״ש אבל לרבנן חייבים עליהם כרת עכ״ל. ועוד יש לתמוה דר״ש נמי לא פליג אלא בטומאה ולא בנותר וא״כ למה כתב רבינו שאין חייבין עליהם משום נותר וטמא י״ל דמשמע ליה דנותר וטמא בחדא שייטא שייטי וילפי מהדדי. ועוד יש לתמוה על\",2,0],[8,365,18,24,\"מ\\\"ש ולא משום טומאת הגוף דמשמע אבל משום טומאת עצמן חייבין בגמ' (דף מ\\\"ו:) איפליגו אמוראי חד אמר מחלוקת בטומאת בשר אבל בטומאת הגוף דברי הכל אינו לוקה וחד אמר מחלוקת בטומאת הגוף אבל בטומאת בשר ד\\\"ה לוקה וח\\\"א כמחלוקת בזו כך מחלוקת בזו אמר רבא מסתברא כמ\\\"ד כמחלוקת בזו כך מחלוקת בזו מ\\\"ט כיון דלא קרינן ביה וטומאתו עליו ונכרתה לא קרינן ביה והבשר אשר יגע בכל טמא והאמר מר והבשר לרבות עצים ולבונה ההוא לפיסולא בעלמא ופירש\\\"י מעלה דרבנן היא וקרא אסמכתא בעלמא, והשתא ה\\\"ל לרבינו למיפסק כרבא דבתרא הוא, ואפשר לדחוק ולומר דלא פסק כרבא משום דמשמע ליה דדרשא דוהבשר לרבות עצים ולבונה דרשא גמורה היא מדאורייתא ולא כרבא דאמר דאסמכתא בעלמא היא והשתא אע\\\"ג דלמ\\\"ד מחלוקת בטומאת הגוף אבל בטומאת בשר ד\\\"ה לוקה פסק כר\\\"ש למ\\\"ד מחלוקת בטומאת בשר אבל בטומאת הגוף ד\\\"ה אינו לוקה פסק בטומאת הגוף כדברי הכל ובטומאת בשר כת\\\"ק. אבל קשה דבנותר משמע שפסק כר\\\"ש כמ\\\"ש ואפשר לומר דלא איפליגו ת\\\"ק ור\\\"ש אלא לענין מלקות אבל לכ\\\"ע אין חייבין כרת ומדכתב רבינו אין חייבין עליהם כרת משמע אבל מלקות חייבין והיינו כת\\\"ק:\",3,0],[8,365,19,1,\"מצות עשה לשרוף כל הקדשים שנטמאו וכו': וכל פסולי המוקדשין הכל נשרפין. משנה בסוף תמורה (דף ל״ג:) ואיתיה בפ' כל שעה (פסחים דף ל״ד.) ואמרינן בפ' כיצד צולין (דף כ״ב:) דגמרא גמירי לה:\",1,0],[8,365,19,2,\"קרבן שנתפגל או וכו'. בפ' כל שעה ובפ' כיצד צולין (פסחים דף פ״ב) תנן הפסח שיצא או שנטמא ישרף מיד נטמאו הבעלים או שמתו תעובר צורתו וישרף בי״ו ותנן תו התם (דף פ״א:) נטמא שלם או רובו שורפין אותו לפני הבירה מעצי המערכה נטמא מיעוטו והנותר שורפין אותו בחצרותיהם ועל גגותיהם מעצי עצמם וכתבו רבינו בפ״ד מהל' קרבן פסח:\",1,0],[8,365,19,3,\"פרים ושעירים הנשרפים וכו'. בס״פ טבול יום (זבחים דף ק״ה:) בעיא דלא איפשיטא:\",1,0],[8,365,19,3,\"כתב הר\\\"י קורקוס ז\\\"ל יש לתמוה על רבינו שכתב ספק זה שהרי לא נסתפקו בגמ' אלא לדעת ר\\\"ל שאמר פרק כל התדיר עדיין לא הגיע זמנו לצאת אבל לר\\\"י שסובר שבשר כיון שסופו לצאת ליכא לספוקי מידי מכ\\\"ש כאן שחייב להוציאו וכמו שהקשו מאי קא מבעיא ליה ותירצו דלא מיבעיא אלא לר\\\"ל וכיון דרבינו פ\\\"א פסק כר\\\"י אין עוד ספק ואיך כתב רבינו שהוא ספק. ונראה שסובר רבינו שמ\\\"ש שם כן הוא קודם שידענו שאין זריקה מועלת לאכלו אבל אחר שהעלינו במעילה שאין זריקה מועלת לאכלו אלא לשרפו כיון שיצא פסול באכילה כיון שעדיין לא הגיע זמנו, ואפשר שמ\\\"ש אליבא דמ\\\"ד וכו' הכוונה לומר שמפני אותו טעם נסתפקו כאן ולכך לא אמרו אליבא דר\\\"ל קא מיבעיא ליה והשתא ניחא דבעי אליבא דהלכתא דודאי כיון שהדבר ברור שאין הלכה כר\\\"ל לגבי ר\\\"י לא ה\\\"ל לשאול סתם מהו אלא ודאי גם לר\\\"י שייכא בעיין עכ\\\"ל:\",2,0],[8,365,19,3,\"וכן אם יצא חצי הבהמה ברוב האבר וכו' וכן אם נשאום ה' להוציאן ויצאו ג' וכו'. גם זה שם בעיא דלא איפשיטא:\",3,0],[8,365,19,3,\"כתב הראב\\\"ד לפיכך נפסלו מספק א\\\"א לא היתה אותה בעיא וכו'. ואני אומר אע\\\"פ שאותה בעיא היתה סתמית בעי רבי אליעזר פרים ושעירים הנשרפים [שיצא רובן במיעוט אבר] יש לפרש לענין פיסול יוצא כדברי רבינו ועוד דלעיל בסמוך מייתי גמרא בעי רבי אליעזר יציאה (קודם זריקת דמים) מהו שתועיל בפרים ושעירים הנשרפים ואיכא למימר מדהך בעיא לענין פיסול יוצא האי בעיא נמי לענין פיסול יוצא.\",4,0],[8,365,19,3,\"ועל מ\\\"ש רבינו וכן אם נשאום כתב א\\\"א אף זו לענין טומאת בגדים וכו'. טעמו מדאמרינן בתר רוב מתעסקין אזלינן או בתר רוב בהמה ומדנקט רוב מתעסקים משמע ליה דלענין טומאת המתעסקים הוא ועוד דאמרינן התם בסמוך בעי ר\\\"א פרים ושעירים הנשרפים שיצאו וחזרו מהו מי אמרינן כיון דנפקי איטמו להו או דילמא כיון דהדור הדור ומדבעיא זו לענין טומאה קמייתא נמי לענין טומאה ונראה שלפיכך כתב ומי שיש לו לב יבין זאת. ולדברי רבינו י\\\"ל דההיא דרוב מתעסקין לא מכרעא דתהוי לענין טומאה ולא לענין פיסול יוצא וכן בעיא דבסמוך לא מכרעא ואע\\\"פ שפירש\\\"י כדברי הראב\\\"ד כבר הקשו עליו התוס' והעלו כפירוש רבינו וגם רש\\\"י גבי בעיא דיצא חצי כתב דלענין אם נטמא אח\\\"כ שישרף בפנים קא מיבעיא ליה. כתב הר\\\"י קורקוס ז\\\"ל כתב רבינו שא\\\"צ באלו עיבור צורה אלא מפני שמא הוא שורף קדשים שאין ראויים לשריפה ומשום ביזוי קדשים נגעו בה אבל אלו שממה נפשך נשרפין הם ומתחלתם דינם לשריפה לענין שינוי מקום אין צורך לעבור צורה ואין כאן ביזוי הקדשים עכ\\\"ל:\",5,0],[8,365,19,5,\"בשר הנמצא בעזרה וכו'. בפ\\\"ז דשקלים וכתב רבינו בפירוש המשנה העולה כולה כליל ולפיכך אין חותכין אותם חתיכות ודי לעשותה איברים, וכתב דנ\\\"מ לאם עבר אדם ואכלו אם אכל מה שנמצא בירושלים אינו חייב כלום לפי שהוא שלמים ואם אכל כהן חתיכות הנמצאים בעזרה אינו חייב כלום:\",1,0],[8,365,19,5,\"וכתב הראב\\\"ד למי שעבר ואכל א\\\"א לספק מעילה עכ\\\"ל. נראה דהיינו לומר שאם הוא חטאת או שלמים אינו חייב עליהם קרבן מעילה שהרי הם מותרים לזרים ואם הוא עולה חייב קרבן מעילה. ומשמע מדקדוק דברי הראב\\\"ד לכאורה דאיברים שנמצאו בעזרה אע\\\"פ שהם בחזקת עולה אין חייבין עליהם קרבן מעילה ודאית אלא קרבן ספק מעילה אבל א\\\"א לומר כן משום דבפ' רביעי דכריתות (דף י\\\"ז) ת\\\"ק סבר דאין חייב על ספק מעילות אשם תלוי:\",2,0],[8,365,19,5,\"אין שורפין את הנותר אלא ביום וכו' אף על פי שהשלמים אסורים באכילה מתחלת ליל שלישי וכו'. בפרק איזהו מקומן (זבחים דף נ״ו:) ובריש פסחים (דף ג').\",3,0],[8,365,19,5,\"ומה שכתב וכן הפגול אינו נשרף אלא ביום. נראה שטעמו משום דפגול ונותר בחדא שייטא שייטי:\",4,0],[8,365,19,5,\"ואין שריפת טמא ונותר ופגול דוחה את יום טוב וכו'. משנה פרק כיצד צולין (פסחים דף פ\\\"ג) ואיתיה בגמרא דתמורה (דף ד') ובפרק במה מדליקין:\",5,0],[8,365,19,5,\"ומותר לשרוף טמא ונותר ופגול כאחד. ברייתא פירקא קמא דפסחים (דף ט\\\"ו:) וכבית הלל:\",6,0],[8,365,19,6,\"בשר קדשי קדשים שנטמא בפנים וכו' עד בולד הטומאה. פלוגתא דתנאי בפירקא בתרא דשקלים ופסק כר\\\"ע:\",1,0],[8,365,19,6,\"ומימיהם של כהנים וכו' ולא עוד אלא אפילו שמן שנפסל בטבול יום וכו'. משנה ובגמ' בפ\\\"ק דפסחים (דף י\\\"ד). ויש בלשון רבינו ט\\\"ס שחסר תיבה אחת והגירסא הנכונה שנטמא בולד הטומאה:\",2,0],[8,365,19,7,\"נותר של קדשים קלים שורפין אותו בעליו בבתיהם. משנה בפרק כיצד צולין (פסחים דף פ\\\"א:):\",1,0],[8,365,19,8,\"מי שיצא מירושלים וכו'. משנה בס״פ אלו עוברין (פסחים דף מ״ט).\",1,0],[8,365,19,8,\"ומ\\\"ש אם יש בו כזית וכו'. שם פלוגתא דתנאי ופסק כחכמים וכר' יהודה.\",2,0],[8,365,19,8,\"ומ״ש ואם הוא אורח וכו'. אוקימתא דגמ' בפ' כיצד צולין (פסחים דף פ״ב) ותשלום דינין אלו כתב רבינו בפ״ד מהלכות קרבן פסח:\",3,0],[8,365,19,9,\"כל עצמות הקדשים שאין בהם מוח וכו'. ברייתא פ' כיצד צולין (פסחים דף פ״ג) כל עצמות הקדשים אינם טעונין שריפה חוץ מעצמות הפסח מפני התקלה הני עצמות ה״ד אי לימא דלית בהו מוח עצמות הפסח למה להו שריפה אלא פשיטא דאית בהו מוח ואי ס״ד שימוש נותר מילתא היא עצמות קדשים אמאי אין טעונין שריפה א״ר נחמן בר יצחק הב״ע כגון שמצאן חלוצים עצמות קדשים דאין בהם משום שבירת עצם קמי דנהוו נותר חלצינהו ולא הוו שימוש נותר ולא בעי שריפה עצמות הפסח דיש בהם משום שבירת עצם לבתר דנהוי נותר הוא דחלצינהו וה״ל שימוש נותר ובעו שריפה. ופירש״י כל עצמות נותר מן הקדשים אינם טעונים שריפה אלא שוברם ומוציא המוח ושורפו ומשליך את העצמות חוץ מעצמות פסח שאינו יכול לשברן מפני תקלת עצם לא תשברו בו לפיכך נשרפים ע״י מוח שבהם וכו'. שמצאם חלוצים כולה מתניתין מיתוקמא במוצא עצמות חלוצין כלומר שבורין ונחלץ מוח מהם. עצמות קדשים דמותר לשברן אמרי סתמא דמילתא לא אתא מוח דידהו לידי נותר ומקמי איסורייהו דניתו לידי נותר חלצינהו ואין כאן שימוש נותר. לבתר הכי דאיפסיל חלצינהו דתו לית ביה איסור שבירה כר״ש ויש כאן שימוש נותר עכ״ל:\",1,0],[8,365,19,9,\"וכתב הראב\\\"ד אינם טעונים שריפה א\\\"א שמצאן חלוצים מפסולי קדושה עכ\\\"ל. ואם היתה כוונתו ללמדנו שיהיו חלוצים לא היה צריך לכך שהרי בביאור כתב רבינו שאין בהם מוח, ולכן נ\\\"ל שמפני שרבינו סתם וכתב כל עצמות הקדשים דמשמע בכל גוונא מיירי בא לבאר שאינו כן דלא מיירי אלא כשמצאן ואינו יודע מה טיבן ואנו אומרים באומד הדעת מאחר שהם חלוצים פסולי המוקדשין היו כלומר נותר ולפיכך מפגלין בין עצמות פסח לעצמות שאר קדשים וכמו שנתבאר. ועי\\\"ל משום דלישנא דשאין בהם מוח משמע אפילו שלא היה בהם מוח מעולם לכך כתב שמצאם חלוצים כלומר דוקא כשהיה בהם מוח ונחלץ ממנו אבל אם לא היה בהם מוח מעולם לא:\",2,0],[8,365,19,9,\"כבר ביארנו. בקרבנות ספ\\\"ה.\",3,0],[8,365,19,9,\"ומ״ש אבל אם נפסל קודם הפשט הרי העור כבשר וישרף הכל. משנה פרק טבול יום (זבחים דף ק״ג:):\",4,0],[8,365,19,9,\"וכן זבח שהופשט ונמצא טריפה. שם במשנה פלוגתא דתנאי ופסק כחכמים.\",5,0],[8,365,19,9,\"ומה שכתב או שנפסל במחשבת הזמן או במחשבת המקום וכו'. משנה שם (דף ק\\\"ג) כל שלא זכה המזבח בבשרה לא זכו כהנים בעורה. ופירש\\\"י כל שלא זכה המזבח בבשרה כגון שאירע בה פיסול קודם זריקה לא היתה בה שעת היתר למזבח.\",6,0],[8,365,19,9,\"ומה שכתב אבל אם נעשה במחשבת שינוי השם וכו'. גם זה משנה שם.\",7,0],[8,365,19,9,\"ומה שכתב וזבח שהופשט קודם זריקה אינו פוסל. שם פלוגתא דתנאי בברייתא ופסק כרבי פירוש אם הופשט קודם זריקה אין העור נפסל עוד אפילו נפסל בשר קודם זריקה זריקה מרצה על העור לבדו:\",8,0],[8,365,19,10,\"אלו הן הנשרפים כו'. משנה בסוף תמורה (דף ל\\\"ג) כל הקדשים שנשחטו חוץ לזמנן וחוץ למקומן הרי אלו ישרפו.\",1,0],[8,365,19,10,\"ומ״ש וכן המנחה שנטמא. משנה פ' היה נוטל (סוטה דף כ״ב ע״ב) ומשמע ליה דה״ה לנפסלה או נותרה.\",2,0],[8,365,19,10,\"ומ\\\"ש ואשם תלוי שנודע לו שלא חטא קודם שנזרק דמו. משנה בפרק בתרא דכריתות (דף כ\\\"ג:).\",3,0],[8,365,19,10,\"ומ\\\"ש וחטאת העוף הבאה על הספק. במשנה בסוף תמורה (דף ל\\\"ד) פלוגתא ופסק כת\\\"ק.\",4,0],[8,365,19,10,\"ומ\\\"ש ושער נזיר טהור. גם זה שם בגמרא.\",5,0],[8,365,19,10,\"ומ\\\"ש והערלה וכלאי הכרם ודבר שאין דרכו להשרף. שם במשנה:\",6,0],[8,365,19,11,\"ואלו הם הנקברים קדשים שמתו שם. במשנה וכת\\\"ק.\",1,0],[8,365,19,11,\"ומ\\\"ש וקדשים שהפילו נפל הפילו שליא וכו' עד שנשחטו בעזרה. ג\\\"ז שם במשנה וכת\\\"ק:\",2,0],[8,365,19,12,\"האורג מלא הסיט משער נזיר ומפטר חמור בשק ידלק. בערלה פ\\\"ג:\",1,0],[8,365,19,13,\"כל הנקברים אפרן אסור. בסוף תמורה (דף ל\\\"ד).\",1,0],[8,365,19,13,\"ומ\\\"ש וכל הנשרפין של הקדש אפרם מותר חוץ מדשן המזבח וכו'. שם דנשרפים אפרן מותר ומותיב עליה מדתניא כל הנשרפים אפרם מותר חוץ מאפר אשרה ואפר הקדש לעולם אסור ומשני כי תניא אפר הקדש אסור בתרומת הדשן דלעולם אסור דתניא ושמו בנחת ושמו כולו ושמו שלא יפזר. ופירש\\\"י ושמו כולו וכיון דטעון גניזה אסור בהנאה:\",2,0],[8,365,19,13,\"וכתב הראב\\\"ד חוץ מדשן המזבח א\\\"א הרמת הדשן עכ\\\"ל. נראה שטעמו לומר שלא אמרו אסור אלא דשן שהיה מרים כהן בכל יום ממזבח העולה כדכתיב והרים את הדשן אשר תאכל האש את העולה ושמו אצל המזבח וכדמפרש טעמא בגמרא וכדפירש\\\"י ודישון מזבח הפנימי ודישון המנורה אינם בכלל זה, ורבינו סובר דילפינן להו מדישון מזבח העולה. ועי\\\"ל דרבינו לטעמיה אזיל שהוא סובר דדשן שע\\\"ג המזבח אסור בהנאה וכמבואר בדבריו בסוף הפרק:\",3,0],[8,365,19,14,\"כל הנשרפין לא יקברו וכל הנקברין לא ישרפו וכו'. משנה בסוף תמורה שם:\",1,0],[8,365,19,15,\"היה מקריב עמו בזבחים וכו'. בפרק הניזקין (גיטין דף נ״ד:) ת״ר היה עושה עמו בטהרות א״ל טהרות שעשיתי עמך נתפגלו וכו' נאמן אבל א״ל טהרות שעשיתי עמך ביום פלוני נטמאו וזבחים שעשיתי עמך ביום פלוני נתפגלו אינו נאמן מ״ש רישא ומ״ש סיפא אמר אביי כל שבידו נאמן רבא אמר כגון דאשכחיה ולא אמר ליה ולא מידי ולבתר הכי אשכחיה וא״ל. ופירש״י כל שבידו לעשות בשעה שמודיעו נאמן ורישא כגון שעודן בידו לטמאן ולפגלן וגבי קרבנות בכהן העובד מיירי כגון שהודיעו בין שחיטה לזריקה ואמר פיגלתי בשחיטה שעדיין בידו לפגלן בשאר עבודות אבל ביום פלוני שכבר יצאו מידו לאו כל כמיניה. רבא אמר אע״פ שאין בידו נאמן וסיפא כגון דאשכחיה מקמי האידנא ולא א״ל והשתא א״ל. והרשב״א כתב שהראב״ד פירש דהא דאמר אביי כל שבידו נאמן היינו כל זמן שהוא תחת ידו ואם א״ל בשעה שהוא יוצא מתחת ידו [אינו] נאמן. ולענין דינא משמע דהלכה כרבא כדקי״ל בכל דוכתא. אבל הראב״ד פוסק כאביי משום דעובדי דמייתי התם דאתא קמי' דרב אמי משמע ליה דאתו כאביי ולפיכך כתב על דברי רבינו א״א כל שבידו נאמן עכ״ל. ולי קשה על רבינו דלא אתי לא כאביי ולא כרבא דאי כאביי ה״ל לפלוגי בין ישנן בידו לאינן בידו ואי כרבא ה״ל לפלוגי בין אשכחיה ולא אמר ליה ללא אשכחיה. ואפשר לומר דפסק כאביי דטעמא דנאמן ברישא משום דהוו בידו ולישנא דברייתא הכי דייק דקאמר היה עושה עמו בטהרות ואמר ליה דמדקתני עושה עמו משמע שהיו מסורות בידו ודייק רבינו לכתוב וא״ל נתפגלו ולא כתב וא״ל זבחים שעשיתי עמך נתפגלו כדקתני בברייתא כדי לרמוז יותר על התכיפות לומר דבעודו עושה בזבחים שעדיין היו בידו א״ל נתפגלו וכן נראה מדבריו בפ״א מהלכות תפילין שפוסק כאביי. ונראה שהראב״ד כמפרש דברי רבינו כתב כל שבידו נאמן וע״פ מ״ש דטעמא דפסק כאביי משום דעובדא דרבי אמי דמייתי התם משמע דלא כרבא ודברי רבינו בפ״א מהל' תפילין הכי משמע. ונראה עוד שרבינו אינו מפרש כל שבידו כפירש״י מדסתים לה סתומי אלא כפירוש הראב״ד. ועדיין נשאר לדקדק בדברי רבינו בסיפא למה האריך ולא סתם וכתב אינו נאמן כלישנא דברייתא ונראה שטעמו משום דקשיא ליה על הך סיפא דקתני אינו נאמן מדמשמע בקידושין פרק האומר (דף ס״ה) דבין לאביי בין לרבא אם א״ל ע״א נטמאו טהרותיך והלה שותק נאמן ואע״ג דאינו בידו, וניחא ליה דהתם מיירי כשהוא נאמן לו.\",1,0],[8,365,19,15,\"ומ\\\"ש ואם לאו שורת הדין שאינו נאמן וכו'. נראה שטעמו מדאמרינן בפ' הניזקין ההוא דאמר לחבריה טהרות שעשיתי עמך ביום פלוני נטמאו אתא לקמיה דרבי אמי אמר ליה שורת הדין אינו נאמן אמר לפניו רבי אסי רבי אתה אומר כן הכי אמר ר' יוחנן משום ר' יוסי מה אעשה שהתורה האמינתו היכן האמינתו אמר ר' יצחק בר ביסנא כה\\\"ג ביה\\\"כ יוכיח דכי אמר פיגול מהימן ומנא ידעינן והא כתיב וכל אדם לא יהיה באהל מועד אלא לאו משום דמהימן וכו' ודילמא דחזיניה בפשפש קשיא, ומדאמר שורת הדין אינו נאמן משמע דה\\\"ק הרוצה לנהוג כפי הדין אינו נאמן אבל הרוצה להחמיר לעצמו הרי זה משובח ועוד דר' יוחנן אמר משום ר' יוסי מה אעשה שהתורה האמינתו ואע\\\"ג דאסיקנא בקשיא מכ\\\"מ יש לחוש לו לומר שהמחמיר על עצמו הר\\\"ז משובח. אחר שכתבתי כל זה מצאתי לרבינו שכתב בסוף הל' מטמאי משכב ומושב כדברי רבא ולכן נ\\\"ל שרבינו מפרש דאביי ורבא לא פליגי לענין דינא אלא בפירושא דברייתא היכי מייתבא שפיר טפי ולכך כתב רבינו דברי שניהם וסמך כאן על מ\\\"ש שם ושם סמך על מ\\\"ש כאן:\",2,0],[8,365,19,15,\"סליקו להו הלכות פסולי המוקדשין בס\\\"ד:\",3,0],[8,366,1,1,\"ביום הצום מקריבין תמיד בשחר וכו'. מפורש בתורה פ' אחרי מות ופרשת פנחס.\",1,0],[8,366,1,1,\"ומ״ש ואיל הבא משל צבור האמור בפרשת אחרי מות והוא האיל האמור בחומש הפקודים. בפ' בא לו (יומא דף ע':) פלוגתא דרבי ור' אלעזר בר״ש דרבי סבר אחד הוא ור' אלעזר בר״ש סבר אחד האמור בפרשת אחרי מות ואחד האמור בחומש הפקודים ופסק כרבי משום דהלכה כרבי מחבירו ועוד דאמרינן התם דר״מ ור״א סברי כוותיה.\",2,0],[8,366,1,1,\"ומ״ש והוא נאכל לערב. משנה בפ' שתי הלחם (מנחות דף צ״ט):\",3,0],[8,366,1,2,\"עבודת כל ט\\\"ו בהמות אלו וכו'. בפ\\\"ק דיומא (דף ל\\\"ב:) ובהוריות (דף י\\\"ב) כל עבודות יוה\\\"כ אינם כשירות אלא בכ\\\"ג.\",1,0],[8,366,1,2,\"ומ\\\"ש ואחד כהן המשוח בשמן המשחה או המרובה בבגדים. הכי משמע במשנה פירקא בתרא דהוריות (דף י\\\"א) והכי תניא התם בהדיא בדף י\\\"ב.\",2,0],[8,366,1,2,\"ומ\\\"ש ואם היתה שבת אף מוסף שבת אין מקריב אותו אלא כ\\\"ג: ומ\\\"ש וכן שאר הקטורת של יום זה וכו' והטבת הנרות הכל עשוי בכ\\\"ג. נראה דמשמע ליה הכי מדתנן בריש יומא (דף י\\\"ד) כל שבעת הימים הוא מקטיר את הקטרת ומטיב את הנרות והיינו כדי שיהא מלומד לעשותם ביוה\\\"כ:\",3,0],[8,366,1,2,\"כתב הריטב\\\"א בפ\\\"ק דיומא בשם הרמב\\\"ם דמדאורייתא אין חובה בכ\\\"ג אלא בעבודת היום ממש אבל תמידין ועבודות של כל יום כשירות בכהן הדיוט אלא דמצוה בכ\\\"ג ור\\\"ש כתב דאפי' תרומת הדשן שהיתה עבודת לילה אינה כשירה אלא בכ\\\"ג ולדעת ר\\\"ש והרז\\\"ה אין פייסות ביוה\\\"כ לפי שכל העבודות בכ\\\"ג אבל הגאונים בפיוטיהם הזכירו פייסות ביוה\\\"כ לכן כתב הרמב\\\"ן בספר המלחמות דאף ביוה\\\"כ היו פייסות אחד לתרומת הדשן והשני מי מדשן מזבח הפנימי והמנורה דמכשירי עבודה הם ונעשים בכהן הדיוט וסידור המערכות ושני גזרי עצים הכל נעשה בכהן הדיוט שהם מכשירי עבודה. ה\\\"ג מי מוליך מחתה למזבח פנימי להקטיר וכ\\\"ג מקטיר וזה מוליך המחתה גחלי אש עכ\\\"ל:\",4,0],[8,366,1,2,\"ומ\\\"ש נשוי שנאמר וכפר בעדו ובעד ביתו. משנה בריש יומא:\",5,0],[8,366,1,3,\"שבעת ימים קודם ליום הכפורים מפרישין כהן גדול וכו'. משנה בריש יומא.\",1,0],[8,366,1,3,\"ומה שכתב ומפרישין אותו מאשתו כל שבעת ימים אלו שמא תמצא אשתו נדה וכו'. שם (דף ז') בגמרא.\",2,0],[8,366,1,3,\"ומה שכתב ומתקינין לו כהן אחר שאם יארע בו פיסול וכו'. שם במשנה:\",3,0],[8,366,1,3,\"בין שאירע בו פיסול קודם תמיד של שחר וכו' אינו צריך חינוך אלא עבודתו מחנכתו וכו'. שם (דף י\\\"ב) פלוגתא דאמוראי ופסק כרב פפא משום דברייתא מסייעא ליה.\",4,0],[8,366,1,3,\"ומה שכתב ומתחיל מעבודה שפסק בה ראשון. הכי משמע שם לרב פפא:\",5,0],[8,366,1,3,\"עבר יום הכפורים וכו'. שם (דף י\\\"ב:) ת\\\"ר אירע בו פיסול ומינו אחר תחתיו ראשון חוזר לעבודתו שני כל מצות כהונה גדולה עליו דברי ר\\\"מ ר' יוסי אומר ראשון חוזר לעבודתו שני אינו ראוי לא לכ\\\"ג ולא לכהן הדיוט וכו' כ\\\"ג משום איבה כהן הדיוט משום מעלים בקדש ולא מורידין אמר רבה בר בר חנה אמר ר\\\"י הלכה כר' יוסי ומודה ר' יוסי שאם עבר ועבד עבודתו כשירה וכו' ואם מת ראשון שחוזר לעבודתו. ויש לתמוה על רבינו שפסק כר' יוסי ולא שבק מלמינקט לישנא דר\\\"מ והוי כמזכי שטרא לבי תרי. וי\\\"ל דלישנא דכל מצות כהונה גדולה עליו כולל שני דברים אחד שהוא עובד בכ\\\"ג שני שהוא אסור בדברים שכ\\\"ג אסור בהם ור' יוסי לא פליג עליה אלא במאי דאמר שהוא עובד בכ\\\"ג אבל במאי דאמר דאסור בדברים שכ\\\"ג אסור בהם מודה דהא מדינא עובד בכ\\\"ג אי לאו משום איבה. ואכתי איכא למידק למה השמיט רבינו שאינו ראוי לכהן הדיוט וי\\\"ל דממ\\\"ש כל מצות כהונה גדולה עליו משמע.\",6,0],[8,366,1,4,\"בשבעת ימים אלו וכו'. בפ\\\"ק דיומא (דף ח') תניא אחד כ\\\"ג של יוה\\\"כ ואחד שורף את הפרה מזין עליו כל שבעה וכו' דברי ר\\\"מ ר' יוסי אומר [אין מזין עליו אלא] שלישי ושביעי בלבד ר' חנינא סגן הכהנים אומר כהן השורף את הפרה מזין עליו כל שבעה כ\\\"ג ביום הכפורים אין מזין עליו אלא שלישי ושביעי (בלבד) וכיון דר' יוסי ור' חנינא סברי בשל יום הכפורים בשלישי ובשביעי הלכתא כוותייהו ובלאו הכי הא קי\\\"ל דהלכה כר' יוסי לגבי ר\\\"מ.\",1,0],[8,366,1,4,\"ומ\\\"ש ואם חל שבת בשלישי או בשביעי שלו דוחין את ההזייה. שם:\",2,0],[8,366,1,5,\"כל שבעת ימים מרגילין אותו בעבודות וכו' עד מתעסקין עמו עד שיגיע זמן שחיטה. במשנה פירקא קמא דיומא (דף י\\\"ד):\",1,0],[8,366,1,8,\"ומ\\\"ש ולא היו שוחטין עד שמכירים שעלה עה\\\"ש בודאי וכו'. משנה בפ\\\"ג דיומא (דף כ\\\"ח) ופ\\\"ג דתמיד (דף ל'):\",1,0],[8,366,2,1,\"כל מעשה התמידין והמוספין וכו'. בפ\\\"ג דיומא (דף ל\\\"א ל\\\"ב):\",1,0],[8,366,2,2,\"ומ\\\"ש כל עת שישנה הבגדים וכו'. שם:\",1,0],[8,366,2,2,\"ומ\\\"ש כיצד בתחלה פושט בגדי חול שעליו וטובל וכו' עד עם החביתין והנסכים. משנה שם:\",2,0],[8,366,2,2,\"כתב הראב\\\"ד ומטיב את הנרות וכו'. א\\\"א אמת כך הוא לשון המשנה וכו'. כוונת הראב\\\"ד שהוא סבור שפירוש בהטיבו את הנרות אינו הדלקת הנרות כמ\\\"ש רבינו בפרק שלישי מתמידין ומוספין אלא הטבת הנרות היינו דישונן ותיקון הפתילות החדשות וכסברת האחרונים שנתבאר בתשובות הרשב\\\"א סימן ש\\\"ט שהם סוברים שלא היה מדליק הנרות אלא בין הערבים בלילה ובבקר היה מטיבן ולא מדליקן זולת נר המערבי שלא היה מטיבו בבקר לפי שצריך שיהיה דולק תמיד ובין הערבים היה מטיבו ומדליקו ועליו קתני ומטיב את הנרות. ורבינו סבור שגם בבקר היה מדליק הנרות דבהטיבו היינו בהדליקו כמו שכתב בפרק ג' מתמידין ומוספין וא\\\"כ בין הערבים היה נכנס לדשנן ולתקנן ולהדליקן ולדידיה אתי שפיר לישנא דמתני' דקתני בין הערבים ומטיב את הנרות כלישנא דכתיב בבקר בהטיבו את הנרות.\",3,0],[8,366,2,2,\"ומ״ש ומקריב הפר ושבעה כבשים של מוסף היום. במשנה פרק בא לו (יומא דף ע') פלוגתא דתנאי ופסק כר״ע.\",4,0],[8,366,2,2,\"ומ\\\"ש ואח\\\"כ מקדש ידיו ורגליו וכו' עד ולובש בגדי חול ויוצא. מבואר במשנה מפרק ג' דיומא עד סוף פרק שביעי:\",5,0],[8,366,2,3,\"כל הטבילות האלו והקידושין כולן במקדש וכו'. משנה בפ\\\"ג דיומא.\",1,0],[8,366,2,3,\"ומה שכתב שאינה אלא להוסיף כוונתו וכו'. פרק ג' דיומא (דף ל') בברייתא פלוגתא דבן זומא ור\\\"י ופסק כר\\\"י:\",2,0],[8,366,2,3,\"וכל כהן שלא טבל וכו'. שם:\",3,0],[8,366,2,4,\"היה כהן גדול זקן או חולה וכו'. משנה וברייתא שם (דף ל\\\"א ע\\\"ב):\",1,0],[8,366,2,5,\"בכל יום כהן גדול מקדש ידיו ורגליו מן הכיור וכו' עד שלא ייגע. משנה בפרק רביעי דיומא (דף מ\\\"ג):\",1,0],[8,366,2,5,\"בכל יום ויום היו על המזבח וכו'. פלוגתא דתנאי משנה שם ופסק כרבי יוסי:\",2,0],[8,366,2,6,\"זה שנאמר בתורה וכפר בעדו וכו' מפי השמועה למדו שזה וידוי דברים. ברייתא בפ\\\"ג דיומא (דף ל\\\"ו).\",1,0],[8,366,2,6,\"ומ\\\"ש נמצאת [למד] שהוא מתודה ביום זה ג' וידויים וכו' עד עשר פעמים. במשנה ובברייתא בפרק הנזכר (דף ל\\\"ו ל\\\"ז) ובפ' טרף בקלפי.\",2,0],[8,366,2,6,\"ומ״ש ובכולם היה מזכיר השם ככתבו וכו' בראשונה היה מגביה את קולו בשם וכו' עד אפי' חביריו הכהנים. ברייתא בריש פרק עשרה יוחסין (קידושין דף ע״א):\",3,0],[8,366,2,7,\"כל הכהנים והעם העומדים בעזרה וכו'. במשנה פ״ג דיומא (דף ל״ה:) ובפ' טרף בקלפי (יומא דף ל״ט) ובפ' שני שעירי (יומא דף ס״ו).\",1,0],[8,366,2,7,\"ומ\\\"ש ובשלשת הוידויים היה מתכוין לגמור את השם כנגד המברכים וכו': וכל היום כשר וכו'. משנה בסוף פרק שני דמגילה (דף כ':):\",2,0],[8,366,3,1,\"שני הגורלות וכו'. עד ובבית שני עשו אותם של זהב. בפרק ג' דיומא (דף ל\\\"ו).\",1,0],[8,366,3,1,\"ומ״ש ומניחים הגורלות בכלי אחד וכו' עד וקלפי שמו. בפרק טרף בקלפי (יומא דף ל״ט):\",2,0],[8,366,3,2,\"היכן מגריל וכו'. משנה בפ\\\"ג דיומא (דף ל\\\"ז) בא לו למזרח העזרה לצפון המזבח ובגמרא מדקאמר לצפון המזבח מכלל דמזבח לאו בצפון קאי מני ראב\\\"י היא דתניא צפונה לפני ה' שיהא צפון כולו פנוי דברי ראב\\\"י והא רישא ר\\\"א בר\\\"ש היא כולה ראב\\\"י היא ותני בבין האולם ולמזבח. ופירש\\\"י מדקאמר לצפון המזבח שהוצרך למשכו מכנגד המזבח ולצפון. מכלל דמזבח לאו בצפון הוה קאי. אין כלום מהמזבח בצפון העזרה ואי הוו קיימי כנגד מזרחה של מזבח פורתא לאו בצפון קיימי. צפונה על ירך המזבח צפונה ל' אויר משמע אל צפון שהוא האויר הפנוי. והא רישא ר' אלעזר בר\\\"ש דאמר מזבח מקצתו בצפון שהכשיר שחיטת הפר בין האולם ולמזבח. כולה ראב\\\"י ותני ברישא פרו היה עומד כבין האולם ולמזבח סמוך לבין האולם ולמזבח אצל מקצוע צפונית של מזבח שהיה מקרבו אצל הפתח בכל יכולת משום חולשא דכ\\\"ג ויותר מכאן לא היה יכול לקרבו דאי מעייל ליה כנגד מזרח המזבח לאו בצפון הוא עכ\\\"ל. ומשמע דהלכה כראב\\\"י אי משום דמשנתו קב ונקי או משום דסתם לן תנא כוותיה. ורבינו שכתב כאן כוותיה שפיר. אבל יש לתמוה על מ\\\"ש בפ\\\"ד ופרו היה עומד בין האולם למזבח ולראב\\\"י ה\\\"ל לכתוב כבין האולם ולמזבח ונראה שצריך להגיה שם כן.\",1,0],[8,366,3,2,\"ומ\\\"ש ומעמיד השעירים פניהם למערב ואחוריהם למזרח. הכי תניא בפרק הנזכר (דף ל\\\"ו) כיצד סומך הזבח עומד בצפון ופניו למערב ואע\\\"ג דתנן התם (דף ל\\\"ה:) פרו היה עומד בין האולם ולמזבח ראשו לדרום ופניו למערב ואמרינן בגמ' היכי משכחת לה אמר רב בעוקם ראשו הא אמרינן בגמרא ונוקמיה להדיא אמר אביי גזירה שמא ירביץ גללים. ופירש\\\"י ונוקמיה להדיא אחוריו למזבח ופניו להיכל. שמא ירביץ גללים וגנאי הוא להראות בית הרעי שלו לצד המזבח והכי שפיר טפי להיות זנבו בצפון וראשו לדרום נמצא זנבו שלא כנגד המזבח שאינו מושכו לצד דרום כל אורך הפר אלא שיהא מקצת גופו בין האולם ולמזבח עכ\\\"ל. וא\\\"כ הכא דמעמידן במזרח העזרה לצפון המזבח דליכא למיחש שמא יראה בית הרעי שלו לצד המזבח שהרי הם מרוחקים מהמזבח לצד מזרח העזרה מעמידן כדתניא הזבח עומד בצפון ופניו למערב וממילא דהוו אחוריו למזרח.\",2,0],[8,366,3,2,\"ומ\\\"ש וכ\\\"ג בא לשם והסגן מימינו וראש בית אב משמאלו. משנה שם (דף ל\\\"ז):\",3,0],[8,366,3,3,\"ומ״ש טרף בקלפי והעלה שני גורלות וכו' עד ושל שמאל על של שמאל. משנה בפ' טרף בקלפי (יומא דף ל״ט).\",1,0],[8,366,3,3,\"ומ\\\"ש ואם לא נתן לא עירב אלא שחיסר מצוה שההנחה מצוה שאינה מעכבת. הכי אמרינן שם (דף מ':).\",2,0],[8,366,3,3,\"ומ\\\"ש וההגרלה מעכבת. שם אסיקנא למ\\\"ד הגרלה לא מעכבא בתיובתא. לפיכך ההנחה כשירה בזר והעלאת הגורלות מן הקלפי פסולה בזר. נלמד ממ\\\"ש בסמוך:\",3,0],[8,366,3,4,\"וקושר לשון של זהורית וכו' עד כנגד בית שחיטתו. שם במשנה (דף מ\\\"א) ומפרש הגמ' דה\\\"ק ולנשחט יקשרנו כנגד בית שחיטתו שלא יתערב זה בזה ולא באחרים. ופירש\\\"י דקושר לנשחט לשון כנגד צוארו. ויש לתמוה על רבינו שסתם במקום שהיה לו לפרש.\",1,0],[8,366,3,4,\"ומ\\\"ש שהלשון משקל שתי סלעים. שם פלוגתא דאמוראי ומשמע התם כמאן דאמר הכי.\",2,0],[8,366,3,4,\"ומ״ש ושוחט את פר החטאת אשר לו ואת השעיר שעלה עליו הגורל וכו' עד אלא כמצליף. במשנה פ' הוציאו לו (יומא דף נ״ג:):\",3,0],[8,366,3,5,\"ומ\\\"ש בין בדי הארון קרוב לכפורת בטפח: ומ\\\"ש ואח\\\"כ מערב שני הדמים וכו' עד אמצעו של מזבח זה. משנה בפרק הוציאו לו שם:\",1,0],[8,366,3,6,\"ומ\\\"ש וכל אלו המ\\\"ג הזיות טובל אצבעו בדם טבילה על כל הזיה וכו'. תוספתא פ\\\"ג דיומא ובגמרא פ' דם חטאת ופ\\\"ק דמנחות.\",1,0],[8,366,3,6,\"ומ״ש ושיירי הדם היה שופך על יסוד מערבי של מזבח החיצון. משנה בפ' הוציאו לו (יומא דף נ״ח ע״ב):\",2,0],[8,366,3,7,\"ואח״כ משלח את השעיר החי ביד איש המוכן וכו' עד להוציאן לבית השריפה. במשנה בפ' שני שעירי (יומא דף ס״ו).\",1,0],[8,366,3,7,\"ומ\\\"ש ומוציא את אימוריהן ונותנם בכלי ומקטירן. לישנא דמתניתין נקט והיה ראוי לכתוב להקטירן כדמגיה בגמרא ולא חש מפני שסמך על מ\\\"ש בפ\\\"ד כיצד הוא הסדר.\",2,0],[8,366,3,7,\"ומ\\\"ש ומנתחין אותם שם בעורן כמו שביארנו. הוא בפ\\\"י מהלכות מעשה הקרבנות:\",3,0],[8,366,3,8,\"כיון שהגיע שעיר למדבר וכו' עד סוף הפרק. במשנה פ' בא לו כ״ג (יומא דף ס״ח:) זולת חתימת הברכות שאינם מבוארות בגמרא אבל בירושלמי שם נזכרו קצתם:\",1,0],[8,366,4,1,\"סדר כל המעשים וכו'. פ\\\"ב דיומא (דף כ\\\"ב).\",1,0],[8,366,4,1,\"ומ\\\"ש כשיגיעו לשחוט את התמיד פורסין סדין של בוץ בין כ\\\"ג ובין העם וכו' עד והחביתין והנסכים. משנה פ\\\"ג דיומא (דף ל').\",2,0],[8,366,4,1,\"ומ״ש ואחר התמיד מקריב הפר ושבעת הכבשים של מוסף היום. פלוגתא דתנאי במשנה פ' בא לו (יומא דף ע') ופסק כר״ע:\",3,0],[8,366,4,1,\"ואח\\\"כ מקדש ידיו ורגליו ופושט בגדי זהב וטובל וכו' עד לפני ה' תטהרו. במשנה פ\\\"ג דיומא (דף ל\\\"ה:).\",4,0],[8,366,4,1,\"ואח״כ מגריל על שני השעירים וכו' עד ומניחן על הרובד שבעזרה. במשנה פ' טרף בקלפי (יומא דף מ״ג:).\",5,0],[8,366,4,1,\"ומ\\\"ש ונותנו למי שמנדנדו כדי שלא יקרוש (ומניחו) על הרובד של היכל מבחוץ. לשון המשנה על הרובד הרביעי שבהיכל ופריך בגמ' והא כתיב וכל אדם לא יהיה באוהל מועד וא\\\"כ איך היה ממרס בהיכל ותירצו תני של היכל. ופירש\\\"י כל הרצפה עשויה שורות שורות טבלאות אבני שיש וכל שורה קרויה רובד. תני של היכל כשיוצא מהיכל לעזרה מונה את הרובדין והוי האי רביעי להיכל.\",6,0],[8,366,4,1,\"ומה שכתב וחותה בה אש מעל המזבח מן הסמוך למערב וכו': ומוציאין לו את הכף וכלי מלא קטרת וכו'. במשנה פ' הוציאו לו (יומא דף מ״ז).\",7,0],[8,366,4,1,\"ומ\\\"ש דקה מן הדקה. בפ\\\"ק דכריתות (דף ו') בברייתא דפטום הקטרת.\",8,0],[8,366,4,1,\"ומ״ש לא מחוקות ולא גדושות. בפ' הוציאו לו (יומא דף מ״ח) בעיא דאיפשיטא:\",9,0],[8,366,4,1,\"כבר ביארנו שהולכה בשמאל פוסלת וכו'. מהל' ביאת המקדש פ\\\"ה.\",10,0],[8,366,4,1,\"ומ״ש אבל מפני כובד המחתה ועוד שהיא חמה וכו'. בר״פ הוציאו לו (יומא דף מ״ז). וק״ל כיון שהולכה בשמאל פוסלת היאך הכשירו כאן מפני טעמים הללו. ואפשר דהולכה בשמאל לא פסלה אלא מדרבנן א״נ אע״ג דהולכה בשמאל בדם פסלה מדאורייתא משום דא״א שלא בהילוך בקטרת לא פסלה ובהכי אכשר רחמנא:\",11,0],[8,366,4,1,\"ומהלך בהיכל עד שהוא מגיע לקדש הקדשים וכו' עד על אבן השתיה. במשנה פ' הוציאו לו (יומא דף מ״ט ע״ב):\",12,0],[8,366,4,1,\"ומ״ש ואוחז שפת הכף בראשי אצבעותיו או בשיניו וכו' וזו היא עבודה קשה שבמקדש. ברייתא בפ' הוציאו לו (יומא דף נ״א:).\",13,0],[8,366,4,1,\"ומ\\\"ש וצובר את הקטרת על גבי הגחלים. שם בברייתא הנזכרת וצוברה כדי שיהא עשנה שוהה לבא וי\\\"א מפזרה כדי שיהא עשנה ממהרת לבא ופסק כת\\\"ק.\",14,0],[8,366,4,1,\"ומ\\\"ש לפנים במחתה כדי שתהיה הקטרת קרובה לארון ורחוק מפניו שלא יכוה. בפ\\\"ו דמסכת תמיד (דף ל\\\"ג).\",15,0],[8,366,4,1,\"ומ״ש וממתין שם וכו' שלא להבעית את העם. משנה בפ' הוציאו לו (יומא דף נ״ב:).\",16,0],[8,366,4,1,\"ומ\\\"ש וכך היה מתפלל וכו'. שם בגמ' (דף נ\\\"ג). ורבינו לא כתב שיפרשו בשעת הזאות הנעשות לפני ולפנים לפי שסמך על מה שכתב בפ\\\"ג מהל' תמידין זה בנין אב לכל הכפרות וכו':\",17,0],[8,366,4,2,\"בשעת הקטרת הקטורת וכו' עד ובשעת מתן דמים בהיכל. בפ' טרף בקלפי (יומא דף מ״ד):\",1,0],[8,366,4,2,\"ואח״כ נוטל דם הפר מזה שהוא מנדנדו וכו' עד על יסוד מערבי של מזבח החיצון. במשנה פ' הוציאו לו (יומא דף נ״ג ע״ב).\",2,0],[8,366,4,2,\"ומ\\\"ש ועל כולן הוא נותן מלמטה למעלה חוץ מן האחרונה וכו'. שם (דף נ\\\"ח ע\\\"ב) כר\\\"א דפליג את\\\"ק. ונראה שטעם רבינו משום דבגמרא פליגי ר\\\"מ ורבי יהודה אליביה:\",3,0],[8,366,4,2,\"כתוב בתשובות הרשב\\\"א סימן שפ\\\"ח אמרת שהוקשה במה ששנינו בפרק הוציאו לו מהיכן הוא מתחיל מקרן מזרחית צפונית. עכ\\\"פ משנה זו שנויה לדעת ר' יוסי שסובר שלא היתה שם אלא פרוכת אחת ופרופה לצפון לימין הנכנס וכשחוזר מן הפתח למזבח הזהב פוגע תחלה בצפונית מערבית ואינו יכול להתחיל שם כדאמרינן עד דנפיק מכוליה מזבח ומתוך כך הולך מזרחית צפונית הא לרבנן מן הדרום היה יוצא ועכ\\\"פ צריך להתחיל מדרומית מזרחית. ונפלאתי מדברי הרמב\\\"ם ז\\\"ל אחר שפסק גם הוא כרבנן היאך פסק בזו דמצפונית מזרחית הוא מתחיל:\",4,0],[8,366,4,2,\"והשיב נ\\\"ל שהרב ז\\\"ל סבור דההוא תנא דמהיכן הוא מתחיל לאו ר' יוסי היא אלא תנא אחרינא ור' יוסי הוא דפליג את\\\"ק בפרופות הדרום כחיצונה לת\\\"ק מדלא קתני ולא היתה אלא אחת ופרופה מן הצפון והאי תנא דמהיכן הוא מתחיל פליג אפתחא אבל אפרוכות לא דלדידיה נמי אית ליה דשתי פרוכות היו שם וברייתא דאיפליגו בה ר\\\"ע ור' יוסי דקתני מהיכן הוא מתחיל מקרן מזרחית דרומית וכו' דברי ר\\\"ע ור' יוסי הגלילי אומר מקרן מזרחית צפונית ואוקימנא פלוגתייהו בפתחא או בצפון או בדרום וכתוב בספרים דר\\\"י הגלילי סבר לה כר' יוסי דאמר פתחא בצפון דר\\\"ע סבר כר\\\"מ דאמר פתחא בדרום. ונראה שרש\\\"י ז\\\"ל גריס כן לדעת הרב ז\\\"ל לא גרסינן בה ר\\\"י הגלילי סבר לה כר' יוסי אלא סבר לה כרבנן דהיינו תנא דמהיכן הוא מתחיל. ובספרים שלנו כן הגיהו בהם סבר לה כרבנן ומחקו גירסת הספרים שכתוב בהם סבר לה כר' יוסי ואפשר דמשום הכי הגיה כן נמצא דלרבנן דמהיכן הוא מתחיל שתי פרוכות היו שם שלא מצינו שחלק בזה בהדיא אלא שהחיצונה פרופה מן הצפון ופנימית מן הדרום וכי נפיק נפיק מן הצפון ובזה יתקיימו דברי הרב ז\\\"ל שהוא פסק בפרוכות כת\\\"ק משום דלא אשכח דפליג עליה בהדיא אלא ר' יוסי ויחידאה הוא ובפסחים פסק כת\\\"ק דמהיכן הוא מתחיל דהוי סתמא בתרא ואע\\\"ג דמחלוקת ר\\\"ע ור\\\"י הגלילי הוא בברייתא ור\\\"ע כת\\\"ק וקי\\\"ל כר\\\"ע מחבירו אפי' הכי סתמא בתרא דמתני' עדיפא דאי רבי לא שנאה ר' חייא מנין לו. עוד כתב אמרת עוד וכן הוספתי תמה במשנה זו ג\\\"כ במה שאמר ר\\\"א במקומו הוא עומד כלומר שאינו צריך הקפת רגל דודאי מאי דקאמר בתר הכי שעל כולם הוא נותן מלמטה למעלה אדר\\\"א קאי דלא מצריך הקפה ברגל אלא ביד ונמצא שבשלש הזאות שבשלש קרנות נעשות ברחוק אמה יכול להזות מלמטה למעלה כלומר שמשפיל ידו וזורק כלפי מעלה ואינו חושש שיפול דמו על זרועותיו חוץ מזו שעומד לפני הקרן וקרוב לו ביותר שנותן בה מלמעלה למטה. ואני רואה לר\\\"מ ז\\\"ל שפסק שצריך הקפה ברגל ועם זה פסק שעל כולם הוא נותן וכו' ואחר שהוא מסבב הקרנות ברגל מה הפרש בין זו לזו והם כלן סמוכות לו עכ\\\"ל:\",5,0],[8,366,4,2,\"באמת פשוטה של משנה משמע דלת\\\"ק כולן מלמעלה למטה, הן וכדקתני התחיל מחטא ויורד משום דלדידיה מקיף ברגל ומתני' דקתני על כלן הוא נותן מלמטה למעלה חוץ מזו בלבד ר' יהודה היא דתניא ר\\\"י אומר ר\\\"א אומר במקומו הוא עומד ומחטא על כולם הוא נותן מלמטה למעלה חוץ מזו שהיתה לפניו ממש שנותן מלמעלה למטה דאלמא ר\\\"א בלחוד הוא דתני לה למתני' אבל לרבנן כולן מלמעלה למטה, אלא אפשר שהרב ז\\\"ל סובר דאף ת\\\"ק הוא ומ\\\"מ לא מפקא מדר\\\"א והא דאמרינן מתני' מני ר' יהודה היא משום דלר\\\"מ ר\\\"א אית ליה בכולן נותן מלמעלה למטה חוץ מזו שהיא לפניו באלכסון אמרינן דמתני' ר' יהודה היא דמתני' ודאי אף לכשתמצא לומר דאף ת\\\"ק היא מ\\\"מ לא מפקא מדר\\\"א. ודקא קשיא לך ואחר שהוא מסבב הקרנות ברגל מה הפרש בין זו לזו והרי כלם סמוכות לו אפשר לומר לדעת הרב שזו בלבד שהיא לפניו ממש לפי שיש לו לצאת מכל המזבח נותן מלמעלה למטה כי היכי דלא ליתווסן מאניה אבל בצפונית מערבית שהוא לו באלכסון נותן מיד ממקומו כדי שלא יעבור על המצות וישהא המתנה ואחר כך מקיף ברגל לצפונית מערבית ומשם נותן מיד לקרן מערבית דרומית ונותן מיד לקרן דרומית מזרחית ונמצא שאין מכולן אחת מהן לפניו ממש אלא זו בלבד כנזכר לעיל דרך הרב בזו אע\\\"פ שפשטה של שמועה נראית כמו שאמרת. עוד כתב אמרת עוד אשוב אתפלא\",6,0],[8,366,4,2,\"במ\\\"ש שבין מזבח למנורה היה עומד והלא המזבח משוך היה כלפי חוץ והוא צריך לצאת מכל המזבח עכ\\\"ל. ובאמת כך נ\\\"ל כמו שאמרת אלא שהיה באפשר לומר שהרב סבור דמזבח לפני ה' ממש מדכתיב ויצא אל המזבח אשר לפני ה' דמשמע דביציאתו פוגע במזבח מיד ועוד מדתניא לפני ה' מה ת\\\"ל דאמר ר' נחמיה לפי שמצינו בפרשת יוה\\\"כ שעומד לפנים מן המזבח ומזה על הפרכת יכול אף זה כן ת\\\"ל מזבח קטרת סמים אשר לפני ה' מזבח לפני ה' ואין כהן לפני ה' דאלמא המזבח לפני ה' ממש שאין דבר חוצץ בין הכהן לפרוכת אלא המזבח בלבד ומנורה ושלחן משוכים כלפי חוץ מן המזבח הפנימי ולחוץ ואינו באפשר שהרי היה מקדים כהן דישון מזבח הפנימי לנרות ואמרינן (דף פ') אמר להם הממונה מ\\\"ט אמר אביי גמרא גמירנא סברא לא ידענא רבא אמר כדר\\\"ל דאמר אין מעבירין על המצות ומאי פגע ברישא מזבח הפנימי ואף הרב עצמו כן כתב בפ\\\"ג מהל' בית הבחירה שכך כתב שם מזבח הקטרת היה מרובע והוא נותן בהיכל מכוון בין הצפון לדרום משוך מבין השלחן והמנורה לחוץ עכ\\\"ל. ומ\\\"ש הר\\\"י קורקוס בזה כתבתי בהל' מעשה הקרבנות פ\\\"ה.\",7,0],[8,366,4,2,\"ומ\\\"ש רבינו ומזה מדם התערובת על טהרו של מזבח שבע פעמים בצד הדרום. שם (דף נ\\\"ח:) איפליגו תנאי ופסק כר' יוסי דאמר בצד דרומי היה נותן וטעמא משום דנמוקו עמו ועוד שהוא מאריה דגמרא טפי מאידך תנא דפליג עליה. וטהרו של מזבח פירשו בגמ' דהיינו גילויו כלומר שמגלה הגחלים והאפר ממקום שמזה. וכתב הר\\\"י קורקוס ז\\\"ל דאיכא למידק שבפ\\\"ג כתב על אמצעו של מזבח וכן כתב בפרק חמישי ממעשה הקרבנות והיאך כתב כאן בצד הדרום ותירץ דאמצעו לאו דוקא אלא הכוונה לאפוקי שלא היה בקרנות כשאר ההזאות ולעולם בחלק הדרומי מאמצעו היה נותן כאשר כתב וביאר כאן:\",8,0],[8,366,4,2,\"ואח״כ בא אצל שעיר המשתלח וכו' עד אחר שהגיע שעיר למדבר. במשנה פ' שני שעירי (יומא דף ס״ח:):\",9,0],[8,366,4,2,\"ומה שכתב שהקריאה בעזרת הנשים. בגמרא פרק בא לו (יומא דף ס״ט:):\",10,0],[8,366,4,2,\"ואחר כך מקדש ופושט בגדי לבן וכו' עד ומקריב תמיד של בין הערבים. משנה וברייתא בפרק בא לו (יומא דף ע') ופסק כר״ע:\",11,0],[8,366,4,2,\"ואח\\\"כ מקדש ידיו ורגליו ופושט בגדי זהב וכו' עד סוף הפרק. במשנה שם פרק בא לו:\",12,0],[8,366,5,1,\"כל עבודות שעובד בבגדי לבן וכו'. בסוף פרק הוציאו לו (יומא דף ס.) ופסק כרבי יהודה לגבי ר' נחמיה אי משום דהוא מאריה דגמרא טפי ואי משום דר' יוסי אמר אימתי משמע דלפרש דברי תנא קמא אתא:\",1,0],[8,366,5,2,\"קטרת שחפנה וכו' וכן שעיר ששחטו וכו'. מימרות שם:\",1,0],[8,366,5,3,\"איל ושעיר המוספין וכו'. במשנה בסוף פרק הוציאו לו (יומא דף ס') כל מעשה יום הכפורים האמור על הסדר אם הקדים מעשה לחבירו לא עשה כלום ויתבאר עוד בסמוך:\",1,0],[8,366,5,4,\"הקדים דם השעיר וכו'. שם במשנה הקדים דם השעיר לדם הפר יחזור ויזה מדם השעיר לאחר דם הפר. ובגמרא (דף ס\\\"א) אהא דאמר עולא שעיר ששחטו קודם מתן דמו של פר לא עשה כלום תנן הקדים דם השעיר לדם הפר יחזור ויזה מדם השעיר אחר דם הפר ואם איתא יחזור וישחוט מיבעי ליה תרגמה עולא במתנות שבהיכל. ופירש\\\"י הקדים דם השעיר קס\\\"ד במתנות שבפנים קאמר דה\\\"ל שעיר ששחטו קודם מתן דמו של פר. תרגמה עולא במתנות שבהיכל קאמר אבל שחיטת השעיר במקומה היתה לאחר מתן הפר בפנים:\",1,0],[8,366,5,5,\"נשפך הדם עד שלא גמר וכו'. משנה וברייתא שם:\",1,0],[8,366,5,8,\"ומ\\\"ש גמר מתנות המזבח ואחר כך נשפך הדם אינו צריך להביא דם אחר וכו'. שם בברייתא:\",1,0],[8,366,5,8,\"ואם דם הפר הוא שנשפך וכו'. שם אהא דאמר ר' חנינא קטרת שחפנה קודם שחיטתו של פר לא עשה ולא כלום תנן אם עד שלא גמר מתנות שבפנים נשפך הדם יביא דם אחר ויחזור ויזה בתחילה בפנים ואם איתא יחזור ויחפון מיבעי ליה בקטרת לא קא מיירי. ופירש רש\\\"י ומיהו ודאי צריך להקטיר קטרת אחרת אחר שחיטת פר זה, וא\\\"כ יש לתמוה על רבינו שכתב ויחפון קטרת פעם שנייה קודם שחיטת הפר. והנגיד רבינו יהושע מבני בניו של רבינו כתב ששאלו ממנו שמאחר שרבינו כתב בתחלת הפרק קטרת שחפנה קודם שחיטת הפר לא עשה כלום היאך כתב כאן שיחפון קטורת פעם שנייה קודם שחיטת הפר. והשיב מאחר ששחט פר בתחלה ולא קרה לו מה שיפסידוהו הנה יותר חפינת הקטרת קודם שחיטת הפר השני מאחר שהוא אחר שחיטת הפר הראשון שלא אירע בו פיסול עכ\\\"ל. ולשון הגמרא דקאמר בהקטרה לא קא מיירי קשה דמשמע דודאי צריך לחפון אחר שחיטת פר שני, וצריך לדחוק ולומר שרבינו מפרש בקטרת כה\\\"ג לא קא מיירי רבי חנינא כלומר אין כאן צורך לחפינת קטורת אחר שחיטת פר שני דקודם לו שפיר דמי. ול\\\"נ דטעות סופר יש כאן וצריך להגיה ולכתוב אחר במקום קודם:\",2,0],[8,366,5,9,\"ואין מטמא בגדים וכו'. שם פלוגתא בברייתא (ס\\\"ח:) ופסק כחכמים:\",1,0],[8,366,5,10,\"נתערב לו דם הפר בדם השעיר. שם (דף נ\\\"ו) מימרא דרבי ירמיה. ופירש\\\"י נתערב וכו' קודם שנתן בפנים כלום. והקשה הר\\\"י קורקוס ז\\\"ל שא\\\"כ איך יתן אחת למעלה ושבע למטה לשם פר וכן לשם שעיר שא\\\"כ נמצא ששחט שעיר קודם שנתן דם הפר וכבר נתבאר שהוא פסול אלא ע\\\"כ מיירי כשנתן כבר מתנות לפני ולפנים ובא ליתן מתנות ההיכל וכמו שתירצו בגמרא מתני' דהקדים דבסמוך לכך כתב רבינו קודם שיגמור ההזיות כלומר אבל נתן מקצתן עכ\\\"ל.\",1,0],[8,366,5,10,\"ומ\\\"ש נתערבו במתנה אחרונה נותן אחת למטה לשם פר וכו'. שם נתערבו לו דמים בדמים במתנות אחרונות וכו' נותן שבע למטה לשם פר וחוזר ונותן אחת למעלה ושבע למטה לשם שעיר. ופירש\\\"י במתנות אחרונות אחר שנתן אחת למעלה מדם הפר. ורבינו גורס נתערבו לו דמים בדמים במתנה אחרונה נותן אחת למטה לשם פר וחוזר ונותן אחת למעלה ושבע למטה לשם שעיר:\",2,0],[8,366,5,11,\"נתחלפו הכוסות וכו'. שם. ויש בלשון רבינו תוספת שכ' וחוזר ונותן מן השני אחת למעלה ושבע למטה וצריך למוחקו וכך מצאתי בס' מוגה:\",1,0],[8,366,5,11,\"כתב הר\\\"י קורקוס ז\\\"ל דע שזה ג\\\"כ מדבר במתנות היכל דמתנות לפני ולפנים א\\\"א מהטעם שנתבאר בסמוך דשעיר ששחטו קודם הזיות הפר לא עשה כלום וגם בזה לא דק רש\\\"י עכ\\\"ל:\",2,0],[8,366,5,12,\"קבל דם הפר בשתי כוסות וכו'. גם זה שם.\",1,0],[8,366,5,12,\"ומה שכתב ואותם הכוסות שנתערבו ישפכו לאמה. הכי אמר התם ר\\\"פ ואף על גב דרב הונא בריה דרב יהושע פליג עליה פסק כר\\\"פ:\",2,0],[8,366,5,13,\"פר של יום הכפורים אף על פי שכ״ג קונה אותו משלו וכו'. בפ' הוציאו לו (יומא דף נ״א:).\",1,0],[8,366,5,13,\"ומה שכתב לפיכך אם מת כהן גדול קודם שישחט הפר וכו' עד נכנס בדם ומכפר בו. שם (מ\\\"ט:) פלוגתא דאמוראי ופסק הכי משום דרב אשי דבתרא הוא אמר (נ') מסתברא כמ\\\"ד דם איקרי פר:\",2,0],[8,366,5,14,\"שני שעירי יוה״כ וכו' עד שאין חטאת הצבור מתה. משנה בריש פרק שני שעירי (יומא דף ס״ב):\",1,0],[8,366,5,15,\"ומה שכתב והשני מן השנים שהגריל עליהם. בסוף דף ס\\\"ד פלוגתא דרב ור\\\"י ופסק כרב דאמר אין בעלי חיים נדחים וכבר כתבתי בפרק ט\\\"ו מהלכות מעשה הקרבנות למה פסק כן.\",1,0],[8,366,5,15,\"ומה שכתב שיקריבו הראשונים. נלמד מדין הפריש חטאתו ואבדה דפסולי המוקדשין:\",2,0],[8,366,5,16,\"פר ושעיר של יוה״כ שאבדו וכו'. בברייתא פרק הוציאו לו (יומא דף נ') ופרק שני שעירי (יומא דף ס״ה) פלוגתא דתנאי ופסק כר״א ור״ש דאמרי הכי משום דרבים נינהו ועוד דאתו כסתם מתני'.\",1,0],[8,366,5,16,\"ומ״ש וכן אם נמצאו הראשונים קודם שיקרבו אלו יקרבו הראשונים היינו כרב דאמר בפ' שני שעירי (יומא דף ס״ד) דסבר לה כר' יוסי דאמר מצותו בראשון.\",2,0],[8,366,5,16,\"ומ\\\"ש וירעו השניים וכו' שאין חטאת הצבור מתה. כבר נתבאר:\",3,0],[8,366,5,17,\"המום פוסל בשעיר המשתלח וכו' וכן אם נעשה מחוסר זמן וכו' עד היא שחיטתו. שם (ד' ס\\\"ג ס\\\"ד):\",1,0],[8,366,5,19,\"היה טריפה פסול וכו'. בפירקא קמא דחולין (דף י\\\"א) גבי הא דאמרי' מנא הא מילתא דאמור רבנן זיל בתר רובא וכו' אתיא משעיר המשתלח וכו':\",1,0],[8,366,5,19,\"חלה השעיר וכו' עד בכל דבר שממיתו. בפרק שני שעירי (יומא דף ס״ו ע״ב):\",2,0],[8,366,5,22,\"ומ\\\"ש ואיברי שעיר זה מותרים בהנאה. שם (דף ס\\\"ז) פלוגתא דרב ושמואל ואמר רבא מסתברא כמ\\\"ד מותרים:\",1,0],[8,366,5,23,\"נפחתה תקרה של היכל לא היה מזה וכו'. בפ' ב״ש (זבחים דף מ'):\",1,0],[8,366,5,24,\"מזבח שלא נתחנך בקטרת לא יזה עליו וכו'. בתורת כהנים פ' ויקרא גבי כהן משיח על פסוק מזבח קטרת הסמים שיתחנך בקטרת הסמים ולא בדם. ופרק התכלת (מנחות דף מ\\\"ט) שנינו שאין מחנכין את מזבח הזהב אלא בקטרת:\",1,0],[8,366,5,25,\"חסר מן הקטרת וכו'. בפ' הוציאו לו (יומא דף נ״ג).\",1,0],[8,366,5,25,\"ומ\\\"ש וכן חייב מיתה על ביאתו בלא מצוה לפיכך אם שגג בביאה וכו' או שנכנס בקטרת שלימה וכו'. שם:\",2,0],[8,366,5,26,\"הקטיר מן הקטרת של קדש הקדשים כו'. נלמד ממה שאמרו בפרק השוחט ומעלה (דף ק\\\"ט ע\\\"ב) גבי אם הקטיר כזית בחוץ חייב:\",1,0],[8,366,5,27,\"חפינת הקטרת עבודה והמחשב' פוסלת בה. בריש פרק הוציאו לו (יומא דף מ\\\"ח) בעיא דאיפשיטא:\",1,0],[8,366,5,27,\"וכן חתיית הגחלים לקטורת נפסלת במחשבה וכו'. שם בעיא דלא איפשיטא ופסק לחומרא ולא כתב שהיא ספק כמ\\\"ש באינך בעיי דבסמוך משום דלא שייך למימר ביה לא יחתה לכתחלה דיחזור ויחתה לכתחלה שפיר דמי:\",2,0],[8,366,5,28,\"חפן בראשי אצבעותיו וכו' עד וקרב זו לזו. (דף מ\\\"ז:) שם בעיא דלא איפשיטא.\",1,0],[8,366,5,28,\"ומ\\\"ש או שנתפזרה קטרת מידו על הארץ ואספה. שם (דף מ\\\"ח) בעיא דלא איפשיטא.\",2,0],[8,366,5,28,\"ומ\\\"ש או שחפן חבירו ונתן לחפניו או שחפן ומת ונכנס שני במה שחפן ראשון וכו'. שם (דף מ\\\"ט) בעיא דלא איפשיטא:\",3,0],[8,366,5,28,\"סליק הלכות עבודת יום הכפורים בס\\\"ד (סנהדרין פ\\\"ד) מ\\\"ט דרבי וכו' גמר חטא חטא מתרומה ורבנן אמרי אמר קרא (ומתו) בו בו ולא במעילה. ופירש\\\"י וממיתה לחודא הוא דאימעט דגבי מיתה הוא דכתיב בו אבל אזהרה מיגמר גמר להזיד במעילה בגזירה שוה דחטא חטא מתרומה. ומכל מקום אין מקום להשיג על רבינו למה לא הביא אותה ראייה מאחר שהביא ראייה הכתובה בגמ'.\",4,0],[8,366,5,28,\"ומ\\\"ש רבינו והוא הדין לשאר כל קדש וכו'. אין לתמוה עליו לומר דהא התם מייתי קרא לתודה ושלמים ובכור וחטאת ואשם דהתם באוכל בחוץ ואם תאמר דמקרא אחרינא מייתי לה גמ' בדוכתא אחרינא דבפרק בתרא דתמורה (דף ל\\\"ב:) אמר ר' ינאי אין מעילה מפורשת מן התורה אלא בעולה בלבד שנאמר נפש כי תמעול מעל וכו' מקדשי ה' המיוחדים לה' אבל חטאת ואשם לא נפקא אלא מדרבי דתניא רבי אומר כל חלב לה' לרבות [אימורי] קדשים קלים למעילה, ואיכא למימר דההיא דפ\\\"ב דתמורה לא לענין חיוב מלקות במזיד אתמר. וא\\\"ת מנא ליה דהוא הדין לשאר כל קדש וי\\\"ל דיליף לה בבנין אב מעולה:\",5,0],[8,366,5,28,\"מעל בשגגה משלם וכו'. מפורש בפרשת ויקרא:\",6,0],[8,367,1,4,\"תשלום הקרן והבאת האשם וכו'. ברייתא ס״פ הגוזל עצים (בבא קמא דף קי״א) מנין שאם הביא מעילתו ולא הביא אשמו אשמו ולא הביא מעילתו שלא יצא ת״ל באיל האשם ונסלח לו וגו' יכול כשם שאיל ואשם מעכבים כך חומש מעכב ת״ל באיל האשם ונסלח איל ואשם מעכבים ואין חומש מעכב. ופירש״י מעילתו קרן דהקדש שמעל בו. באיל האשם ונסלח משמע אין סליחה אלא בשניהם. איל כמשמעו. האשם קרן כדיליף לקמיה עכ״ל. כלומר דאמרינן לקמן בסמוך ויליף הקדש מהדיוט מה אשם דהתם קרן אף אשם דהכא קרן. ופירש״י אשם דכתיב בגזל הגר קרן הוא כדאמרינן לעיל:\",1,0],[8,367,1,5,\"הביא מעילתו עד שלא הביא אשמו לא יצא. כלומר שאם הביא מעילתו ואח\\\"כ הביא אשמו לא יצא שצריך שתחלה יביא אשמו ואחר כך יביא מעילתו:\",1,0],[8,367,1,5,\"כתב הראב\\\"ד שלא הביא אשמו לא יצא א\\\"א אינו משוה עם הגמ' של פ' הגוזל רבה עכ\\\"ל. טעמו לומר דהתם תניא מנין שאם הביא אשמו עד שלא הביא מעילתו שלא יצא ת\\\"ל באיל האשם האשם בשכבר ופירש\\\"י באיל האשם משמע באיל שהוא בא חובה לאשם שהוא קרן אלמא קרן ברישא מייתא. ותירץ הר\\\"י קורקוס ז\\\"ל נראה שדברי רבינו והברייתא הכל יוצא לדרך אחד ורבינו קרא אשמו את הקרן כלישנא דסליק מיניה שאמר איל ואשם וגם כלישנא דקרא דמיניה יליף דהיינו באיל האשם האשם בשכבר כלומר שהביאו כבר קודם האיל וכיון דלישנא דקרא הכי להודיע שמשם כתב כן רבינו, ומעילתו שבדברי רבינו היינו אשם מעילתו דשייך נמי שפיר לישנא דמעילתו. ונראה עוד דברייתא נקט הכי מפני שעדיין לא אמרה דרשא דאשם הוי קרן דבתר האי דרשא מיתניא ההיא אבל רבינו שהקדים כבר והודיע דאשם דקרא היינו קרן נקט לישנא דקרא ומעתה מעילתו ודאי דהיינו קרבן מעילתו ונמצא רבינו משוה עם הגמרא והיא היא עכ\\\"ל:\",2,0],[8,367,1,5,\"נסתפק לו אם מעל וכו'. במשנה פרק דם שחיטה (כריתות דף כ״ב) פלוגתא דר״ע ורבנן ופסק כרבנן:\",3,0],[8,367,1,5,\"והחומש הרי הוא כתחלת ההקדש וכו'. בפרק הזהב (בבא מציעא דף נ״ד):\",4,0],[8,367,1,5,\"וכבר ביארנו כמה פעמים. בהלכות מעשר ובהלכות תרומות ובהלכות ערכין:\",5,0],[8,367,1,5,\"שהחומש אחד מארבעה בקרן וכו'. בפרק הזהב (בבא מציעא דף נ״ד) אסיקנא הכי:\",6,0],[8,367,1,6,\"יש דברים שאין חייבים עליהם מעילה וכו'. בפ\\\"ג דמעילה שנינו שיש דברים שאין נהנין מהם ולא מועלים. ופירש\\\"י בפ\\\"ד דנזיר (דף כ\\\"ח) בד\\\"ה לא נהנין מדרבנן ובריש מעילה (דף ב') אמרינן שדברים שאין מועלין בהם אלא מדרבנן אין משלמין חומש:\",1,0],[8,367,1,7,\"כל קדשי מזבח וכו'. בפרק ג' דבכורות (דף כ\\\"ה) ואמרינן התם דקדשי בדק הבית אינם אסורים בגיזה ועבודה אלא מדרבנן וכתבו רבינו לקמן בפרק זה.\",1,0],[8,367,1,7,\"ומ\\\"ש והגוזז את השור או העובד בצאן לוקה מן התורה. שם מנין ליתן את של זה בזה וכו' ת\\\"ל לא תעבוד ולא תגוז. ופירש\\\"י וי\\\"ו מוסיף על ענין ראשון וילמדו שניהם זה מזה.\",2,0],[8,367,1,7,\"ומ\\\"ש ותולש אינו כגוזז. שם:\",3,0],[8,367,1,8,\"ספק קדשים וכו'. הרי הם אסורים בגיזה ועבודה וכו'. בפ\\\"ב דבכורות (דף י\\\"ח:) ואיתיה בפ\\\"ק דמציעא:\",1,0],[8,367,1,9,\"בהמת הקדש שנפל בה מום ונפדית וכו' אינה מותרת בגיזה ועבודה וכו' עד ואינם יוצאים לחולין להגזז ולהעבד לעולם. משנה פרק שני דבכורות (דף י\\\"ד) ופרק הזרוע (חולין דף ק\\\"ל):\",1,0],[8,367,1,9,\"ואסור להרביע בבכור או בפסולי המוקדשין. בפרק אלו הן הלוקין (מכות דף כ״ב) אמר ר' הושעיא המרביע שור פסולי המוקדשין לוקה. ופירש״י המרביע שור פסולי המוקדשין שנפדה אפילו על מינו לוקה שהרי גוף אחד ועשאו הכתוב שני גופים דתורת חולין ותורת קדשים יש עליו עכ״ל. ואיני יודע למה לא כתב רבינו שלוקה.\",2,0],[8,367,1,9,\"ומה שכתב שאסור להרביע בבכור:\",3,0],[8,367,1,10,\"מותר לתלוש השיער לכתחלה וכו'. בפרק ג' דבכורות (דף כ\\\"ה כ\\\"ו).\",1,0],[8,367,1,10,\"ומה שכתב ואותו השיער שתלש או שנשר וכו' הרי זה אסור בהנאה אפילו לאחר שישחטו מפני מומן וכו'. שם במשנה פלוגתא דתנאי ופסק כחכמים ואליבא דר\\\"י דאמר בגמרא אמר ר\\\"נ הלכה כר\\\"י הואיל ותנן בבחירתא כוותיה וכו' אמר ר\\\"נ בר יצחק מתני' נמי דיקא וכו'.\",2,0],[8,367,1,10,\"ומ\\\"ש אבל צמר הנושר מהחטאת והאשם מותר וכו'. שם בגמ'.\",3,0],[8,367,1,10,\"ומ\\\"ש ואם נתלש מן העולה הרי זה ספק. שם בעיא דלא איפשיטא:\",4,0],[8,367,1,10,\"וכל שיתלש מכל הקדשים וכו' חוץ מן הבכור וכו'. כתב הר\\\"י קורקוס ז\\\"ל שיש ללמוד כן מדקתני בברייתא בכור בעל מום משמע וכן מדנקט דוקא בכור מהטעם שנתבאר בבעיא עולה תמימה משמע דבבעלת מום ליכא ספיקא:\",5,0],[8,367,1,11,\"השוחט הבכור וכו'. משנה בפרק ג' דבכורות (דף כ\\\"ד:):\",1,0],[8,367,1,12,\"קדשי בדק הבית וכו'. מימרא דר״א שם (דף כ״ה) והעמידו אותה מדרבנן. ונתבאר גם בפ' ראשית הגז (חולין דף קל״ה):\",1,0],[8,367,1,13,\"המקדיש עובר למזבח וכו' והרי היא מותרת בגיזה וכו'. פרק קמא דתמורה (דף י\\\"ב):\",1,0],[8,367,1,13,\"הקדיש אבר אחד מן הבהמה וכו'. שם בעיא דלא איפשיטא:\",2,0],[8,367,2,1,\"קדשים קלים אין מועלים בהם וכו'. משנה בפרק קמא דמעילה (דף ו').\",1,0],[8,367,2,1,\"ומה שכתב ואין מועלין בדבר הנאכל. נתבאר בפרק שקודם זה.\",2,0],[8,367,2,1,\"ומה שכתב אפילו העלה אימורים שלהם למזבח קודם זריקה אין מועלין בהם עד שיזרוק הדם. פרק המזבח מקדש (זבחים דף פ״ה:):\",3,0],[8,367,2,1,\"הוציא אימוריהם לחוץ וכו'. משנה בפירקא קמא דמעילה אימורי קדשים קלים שיצאו לפני זריקת דמים ר\\\"א אומר אין מועלין בהם וכו' רבי עקיבא אומר מועלין בהם ואמרינן בגמ' דר\\\"ע סבר אפי' זריקה שלא כתקנה מייתי לידי מעילה וידוע דהלכה כר\\\"ע.\",4,0],[8,367,2,1,\"ומ\\\"ש שהזריקה מועלת ליוצא בין להקל בין להחמיר היינו לומר דאימורי קדשים קלים שיצאו לפני זריקת דמים כשיזרק הדם מועלים בהם ובשר קדשי קדשים שיצא לפני זריקת דמים כשיזרק הדם אין מועלין בו וכדתנן בפ\\\"ק דמעילה אליבא דר\\\"ע:\",5,0],[8,367,2,2,\"כל קדשי קדשים מועלים בהם וכו' עד מועלים בו והוא בבית הדשן. משנה בפרק ב' דמעילה (דף ט'):\",1,0],[8,367,2,5,\"וכן פרה אדומה וכו'. בפ״ד דפרה שנינו לעולם מועלים בה וכו' עד שתעשה אפר. ובפ״ז דשקלים שנינו שהתקינו בית דין שלא יהו מועלים באפר פרה. וקאמר עלה בבבלי ובירושלמי בדין הוא שימעלו בה והם גזרו שלא ימעלו בה והתני' חטאת מלמד שמועלין בה בה מועלין ואין מועלין באפרה ובגמ' דידן פ' התכלת (מנחות דף נ״א נ״ב) מקשה על מאי דתנן שהוא תנאי ב״ד שלא יהו מועלים באפרה דאורייתא היא דתניא חטאת מלמד שמועלין בה היא בה מועלין באפרה אין מועלין אמר רב אשי שתי תקנות הוו דאורייתא בה מועלין באפרה אין מועלין כיון דחזו דקא מזלזלי בה וקא עבדי מינה למכתן גזרו בה מעילה כיון דחזו דפרשי מספק הזאות אוקמוה אדאורייתא ולפי זה הא דתנן שהוא תנאי ב״ד קאי אמאי דאוקמוה אדאורייתא.\",1,0],[8,367,2,5,\"ומ\\\"ש רבינו אע\\\"פ שהיא כקדשי בדק הבית, קשה דמאי אע\\\"פ אטו קדשי בדק הבית מי לא מעלי בהו. ואפשר דה\\\"ק אע\\\"פ שאינה קדשי מזבח וגם אינה קדשי בדק הבית אלא דומה לקדשי בדק הבית וכיון שאינה קדשים ממש לא היה מן הדין שימעלו בה אלא דקרייה רחמנא חטאת:\",2,0],[8,367,2,6,\"חטאת בהמה ואשם וכו' עד הוזה דמה אין בה מעילה. משנה פ\\\"ב דמעילה (דף ט').\",1,0],[8,367,2,6,\"ומ\\\"ש אבל אסור ליהנות במוראתה ונוצתה וכו'. בסוף תמורה (דף ל\\\"ד) עולת העוף שנתמצה דמה מוראתה ונוצה שלה יצאו מידי מעילה ואסיקנא דמ\\\"מ אסורים בהנאה משום דנקברים הם כדאמרינן בפ\\\"ק דיומא נבלעים במקומן וכל הנקברים אפרן אסור:\",2,0],[8,367,2,7,\"המנחות מועלין בהן משהוקדשו וכו' עד הותרו השירים באכילה ואין בהם מעילה. משנה בפרק ב' דמעילה (דף י').\",1,0],[8,367,2,7,\"ומה שכתב ואם נפסלו השירים או חסרו וכו'. סוף פירקא קמא דמנחות בעיא דלא איפשיטא:\",2,0],[8,367,2,8,\"לחם הפנים מועלים בו משהוקדשו וכו' עד נזרק דם הכבשים הותרו באכילה. משנה בפרק ב' דמעילה (דף ט'):\",1,0],[8,367,2,9,\"הנסכים מועלים בהם וכו'. משנה בפרק שלישי דמעילה (דף י\\\"א).\",1,0],[8,367,2,9,\"ומה שכתב מים שמנסכים בחג הסוכות וכו'. גם זה משנה שם (דף י\\\"ג).\",2,0],[8,367,2,9,\"ומה שכתב מועלין בכולן. שם אהא דתנן נתנן בצלוחית מועלין בהם אמר ר\\\"ל אין מועלין אלא בג' לוגין ור' יוחנן אמר מועלין בכולן וידוע דהלכה כר\\\"י:\",3,0],[8,367,2,10,\"לוג שמן של מצורע מועלין בו משהוקדש בכלי וכו' עד הותרו השירים באכילה. ברייתא בפרק בית שמאי (זבחים מ\\\"ה) וכתנא קמא דרבי:\",1,0],[8,367,2,11,\"כל דמי שחיטת הקדשים אין מועלין בו. משנה בפ\\\"ג דמעילה (דף י\\\"א).\",1,0],[8,367,2,11,\"ומ\\\"ש בין לפני כפרה בין לאחר כפרה. שם בגמרא:\",2,0],[8,367,2,11,\"כתב הראב״ד אותה מעילה אינה אלא מדרבנן והכי איתא ביומא עכ״ל. הוא בפ' הוציאו לו (יומא דף נ״ט).\",3,0],[8,367,2,11,\"ומ\\\"ש יצא לנחל קדרון מועלין בו. שם במשנה.\",4,0],[8,367,2,11,\"ומ״ש אבל המקיז דם לבהמת קדשים הרי הוא אסור בהנאה ומועלין בו. מימרא שם (דף י״ב) ואיתא בפרק אין עומדין (ברכות דף ל״א) והכריח שם הר״ר יונה דמועלין בו מן התורה. וכתב הרא״ש דאפילו בדם קדשים קלים דאע״ג דליכא בהו מעילה איכא בהו איסורא דאורייתא:\",5,0],[8,367,2,12,\"העצמות והגידים והקרניים והטלפיים וכו' עד מועלים בהם לעולם. בפ' המזבח מקדש (זבחים דף פ״ו) אהא דתנן העצמות והגידים והקרנים והטלפים שפירשו לא יעלו אמרינן בגמרא אמר רבה וכו' לא שנו אלא שפירשו לאחר זריקה אבל פירשו קודם זריקה אתיא זריקה ושריתינהו וכו' מתיב וכו' עצמות קדשים לפני זריקה מועלין בהן לאחר זריקה אין מועלים בהן ושל עולה מועלים בהן לעולם אימא ושל עולה פירשו לפני זריקה אין מועלין בהן לאחר זריקה מועלים בהן לעולם ופליגא דר״א דאמר ר״א פירשו לפני זריקה מועלים בהם לאחר זריקה לא נהנים ולא מועלים ופירש״י לא שנו דקאמר פירשו ירדו ומיהו איתנהו בכלל קדשים אלא שפירשו לאחר זריקה דכיון דבשעת זריקה מחוברים הוו קובעתן זריקה למזבח וכי פירשו ה״ל קדשים פסולים אבל פירשו לפני זריקה דכיון דבשעת זריקה לאו בני מזבח היו אתיא זריקה ושריתינהו להדיוט וכו'. עצמות קדשים הנאכלים כגון חטאת ואשם מועלים בהם דאין כאן שעת היתר לכהנים. ופליגא דר״א אדרבה. פירשו לפני זריקה מועלים בהם לעולם דכיון דפירשו ואינהו לאו בני הקטרה נינהו לא אהני להו זריקה ובאיסורייהו קיימו עכ״ל. ובאמת כי סוגיא זו יש בה כמה תימה כמו שיראה המעיין. ומכ״מ רבינו נראה שפסק כר״א דאתי כרישא דברייתא דרב אדא בר אהבה ובעולה פסק כברייתא דרב אדא בר אהבה. וי״ל גבי קדשי קדשים דקאמר לפני זריקה מועלין בהם מה פירושו א״ת דמועלין בהם לעולם ואמאי לא שריא להו זריקה כי היכי דשריא בעולה וא״ת דמועלין בהם דקאמר אינו אלא עד שעת זריקה מדלא נקט בהו אין מועלין בהם לאחר זריקה כדנקט בעולה ונקט בהו מועלים משמע דלעולם מועלים בהם וא״כ תיקשי מה שהקשיתי מ״ש מעולה. ונ״ל דקושטא דמלתא דמועלין בהם דנקט בקדשי קדשים אינו אלא עד שעת זריקה כמו בעולה ודייק למינקט בהו מועלים בהם לומר שאע״פ שהם מקדשים הנאכלים מועלים בהם עד שעת זריקה. ובעולה נקט אין מועלים בהם לומר שאע״פ שהם מעולה שכולה כליל אין מועלין בהם לאחר זריקה:\",1,0],[8,367,2,12,\"עצמות העולה שפקעו מעל גבי המזבח וכו'. בפרק הנזכר בדף הנזכר במשנה איברים שפקעו מע\\\"ג המזבח קודם חצות יחזיר ומועלים בהם לאחר חצות לא יחזיר ואין מועלין בהם. ובגמ' (דף פ\\\"ו) אתמר פירשו קודם חצות והחזירן אחר חצות רבה אמר חצות שני עוכלתן רב חסדא אמר עמוד השחר עוכלתן וכו' פירשו קודם חצות והחזירן לאחר עמוד השחר רבה אמר חצות שני עוכלתן רב חסדא אמר אין בהם עיכול לעולם מתקיף לה רב יוסף ומאן לימא לן דחצות בראש המזבח משויא להו עיכול דילמא כל היכא דמשכחת להו משויא להו עיכול שלחו להו מתם הלכתא כרב יוסף אתמר נמי אמר רבי חייא בר אבא פירשו קודם חצות והחזירן לאחר חצות לא נהנים ולא מועלים וכו' יוצאים מידי מעילה א\\\"ל רב פפא לאביי וכי מאחר דשלחו מתם הלכתא כרב יוסף ואמר רבי חייא בר אבא וכן תני בר קפרא רבה ורב חסדא במאי פליגי א\\\"ל בשמניח ע\\\"כ בגמרא. וקשה בעיני ליישב דברי רבינו על פי הדברים האלה כמו שהוא מבואר לכל מעיין. ומה שנ\\\"ל לומר על צד הדחק הוא שפסק כרב יוסף דאמרינן בגמרא דהלכתא כוותיה וכיון דרב יוסף סבר דחצות כל היכא דמשכחת להו משויא להו עיכול באיברים שפקעו יליף מינה רבינו לעצמות שפקעו:\",2,0],[8,367,2,13,\"גחלת שפקעה מעל המזבח וכו'. תוספתא פרק קמא דמעילה.\",1,0],[8,367,2,13,\"ומ\\\"ש אבל גחלת של קדשי בדק הבית מועלין בה ושלהבת לא נהנין ולא מועלין. משנה בסוף מסכת יו\\\"ט (דף ל\\\"ט):\",2,0],[8,367,2,14,\"דשן מזבח החיצון וכו'. בפ״ב דמעילה (דף ט') אתמר הנהנה מאפר תפוח שעל גבי המזבח רב אמר אין מועלין בו ור״י אמר מועלין בו לפני תרומת הדשן כ״ע לא פליגי דמועלין בו כי פליגי לאחר תרומת הדשן וידוע דהלכה כר״י. ובפ' ב״ש (זבחים דף מ״ה) וברפ״ג דמעילה (דף מ״ו) קאמר סתם גמ' דתרומת הדשן אע״פ שנעשית מצותו מועלים בו:\",1,0],[8,367,2,15,\"ומ\\\"ש דישון מזבח הפנימי ודישון המנורה לא נהנים ולא מועלים. משנה במעילה פרק שלישי:\",1,0],[8,367,2,16,\"כל בהמת קדשי קדשים שהיא בעלת מום וכו' הכי משמע בפ\\\"ג דמעילה (דף י\\\"ב). וכתב הר\\\"י קורקוס ז\\\"ל איכא למידק שכתב רבינו בפ\\\"א שכל שקדם מום קבוע להקדשו אין אסור בגיזה ועבודה אלא מדבריהם ואמאי הא אסור מן התורה למעול בו, וי\\\"ל דמיירי בשאינו נהנה מאותה גיזה ואותה עבודה א\\\"נ שאין בה שוה פרוטה.\",1,0],[8,367,2,16,\"ומ\\\"ש אבל תורים שלא הגיע זמנם ובני יונה שעבר זמנם וכו'. משנה פ\\\"ג דמעילה:\",2,0],[8,367,3,1,\"קדשי מזבח שמתו וכו'. מימרא דר\\\"י בפ\\\"ג דמעילה (י\\\"ב) ובריש מעילה שם. ואיכא למידק אמאי נקט רבינו קדשי מזבח הא ר\\\"י קדשים סתם נקט. וי\\\"ל דלרבותא נקט קדשי מזבח וכ\\\"ש קדשי בדק הבית ועוד משום דבהאי פירקא עסיק בדיני קדשי מזבח מש\\\"ה פתח בהו.\",1,0],[8,367,3,1,\"ומ\\\"ש וכן אם נפסלו בדברים שיפסלו בהם הקרבנות מועלים בהם מד\\\"ס בד\\\"א בשלא היה להן שעת היתר לאכילת כהנים וכו' כיצד קדשי קדשים שנפסלו קודם שיגיע הדם למזבח כהלכתן כגון ששחטן בדרום אע\\\"פ שקיבל בצפון וכו' עד שהרי לא היה להם שעת היתר. משנה בריש מעילה קדשי קדשים ששחטן בדרום מועלים בהם שחטן בדרום וקיבל דמן בצפון בצפון וקיבל דמן בדרום שחט ביום וזרק בלילה שחט בלילה וזרק ביום או ששחטן חוץ לזמנן וחוץ למקומן מועלים בהם כלל אמר ר' יהושע כל שהיה לה שעת היתר לכהנים אין מועלים בה וכל שלא היה לה שעת היתר לכהנים מועלים בה אי זו היא שהיה לה שעת היתר לכהנים שלנה ושנטמאת ושיצאת ואי זו היא שלא היה לה שעת היתר לכהנים שנשחטה חוץ לזמנה וחוץ למקומה ושקיבלו פסולים וזרקו את דמה.\",2,0],[8,367,3,1,\"ומ\\\"ש רבינו או שזרקוהו פסולים אע\\\"פ שקיבלוהו כשרים. שם נחלקו חזקיה ור\\\"י אי סגי בנראה לזריקה דהיתר זריקה שנינו או בעי שעת היתר אכילה דחזקיה סבר היתר זריקה סגי הילכך כל שנתקבל הדם שלא בהכשר סגי להוציא מידי מעילה ור\\\"י סבר דלא אלא שיזרק בהכשר ויותר באכילה ופסק רבינו כר\\\"י מפני ששם הביאו כמה ראיות לדבריו ואע\\\"ג דשנינהו חזקיה שינויי דחיקי נינהו ועוד דסוגיא דפי\\\"ב דמנחות כר\\\"י רהטא. ובגמ' אתמר עלו מהו שירדו רבה אמר אם עלו ירדו רב יוסף אמר אם עלו לא ירדו אליבא דר' יהודה לא תיבעי לך דכ\\\"ע לא פליגי דאם עלו ירדו כי פליגי אליבא דר\\\"ש וכו' תנן קדשי קדשים ששחטן בדרום מועלין בהם בשלמא לרב יוסף ניחא אלא לרבה קשיא מאי מועלים בהם מדרבנן ואע\\\"ג דהא דאוקימנא מתני' דקתני מועלין בהם מדרבנן אליבא דרבה הוא משמע דלרב יוסף מועלין בהם מדאורייתא ובמסקנא בגמרא אסיקנא לרבה בתיובתא והוי משמע לכאורה דכיון דהלכה כרב יוסף ולדידיה מועלין דקתני מתני' הוי דאורייתא הכי נקטינן כי דייקינן בה נקטינן דמועלים בהם דקתני מתני' היינו מדרבנן משום דהא דאוקימנא מתני' דמועלין בהם היינו מדרבנן לרבה אבל לרב יוסף הוי מדאורייתא היינו אליבא דר\\\"ש אבל לר' יהודה הא אמרינן דכ\\\"ע לא פליגי דאם עלו ירדו וא\\\"כ אין מועלין בהם מדאורייתא וכיון דקי\\\"ל הלכה כר' יהודה לגבי ר\\\"ש כל שלא היה לה שעת היתר לכהנים אין מועלין בה אלא מד\\\"ס.\",3,0],[8,367,3,1,\"ומ\\\"ש או שיצא הבשר והדם כולו. נ\\\"ל שט\\\"ס יש כאן וצריך להגיה או שיצא הדם והבשר כולו דגרסינן בפ\\\"ק דמעילה (דף ו' וז') אמר ר' יוחנן כי אמר ר\\\"ע זריקה מועלת ליוצא שיצא מקצתו אבל יצא כולו לא, ופירש\\\"י שיצא מקצת הבשר ולא יצא כולו דמיגו דמהניא זריקה למקצת שבפנים מהני נמי לההוא מקצת שיצא אבל יצא כולו לא וכו' דכמו דליתיה לבשר דמי אמר רב פפא לא אמר ר\\\"ע זריקה מועלת ליוצא אלא שיצא בשר אבל יצא דם אין זריקה מועלת ליוצא ותניא כוותיה משמע בהדיא דדם אפי' יצא מקצתו אין זריקה מועלת דהא בשר אין זריקה מועלת בו אלא ביצא מקצתו ובההוא גוונא אמר דבדם אין זריקה מועלת.\",4,0],[8,367,3,1,\"ומ\\\"ש או שיצא מקצת הבשר קודם זריקת דמים וכו' שהרי היה לו שעת היתר לאכילה. כלומר ואח\\\"כ זרק הדם וכמ\\\"ש לעיל בסמוך דזריקה מועלת כשיצא מקצת הבשר:\",5,0],[8,367,3,3,\"קיבלו הפסולים את הדם וכו' עד ואין זריקת השירים מועלת. בפ\\\"ק דמעילה (דף ה') ועיקרה פ\\\"ג דזבחים וכבר נתבאר דין זה פ\\\"א מה' פסולי המוקדשין:\",1,0],[8,367,3,3,\"וכבר ביארנו שאין בקדשים קלים וכו' אבל קדשים קלים שנתפגלו אע״פ שנזרק הדם אין מועלין באימוריהם. מימרא דרב גידל אמר רב בפ״ק דמעילה (דף ג') ואע״ג דאותביה רב פפא לאביי ואישתיק הא אמרינן התם דכי אתא אביי קמיה דרבי אבא שני ליה ואע״ג דבפ' התכלת (מנחות דף מ״ז) פריך מדרב גידל וקאמר ולא איתותב דרב גידל לאו למימרא דאיתותב דרב גידל ואידחי ליה אלא היינו לומר דכיון דאיכא תיובתא עליה דרב גידל אע״ג דשני לה בשינויא דחיקא לאו איהו כדאי למיפרך מיניה. ועוד י״ל דרב פפא הוא דאותביה לדרב גידל בפ״ק דמעילה ואיהו הוא דקאמר בפרק התכלת ולא איתותב דרב גידל משום דלא שמיע ליה שינויא דרבי אבא א״נ שמיע ליה ולא ס״ל אבל אנן דידעינן לשינויא דרבי אבא נקטינן שפיר כרב גידל אמר רב ולא דחינן ליה כיון דאיכא שינויא לתיובתיה ור' אבא ואביי ס״ל כוותיה ועוד דהתם בפ״ק דמעילה מייתי גמ' סייעתא להא דרב גידל. והר״י קורקוס ז״ל כתב שטעם רבינו משום דלא איתותב רב גידל אלא במאי דאמר בזריקת פגול אינה מוציאה אבל במאי דאמר אינה מביאה הלכתא כוותיה.\",2,0],[8,367,3,3,\"ומ\\\"ש רבינו וכן אם יצא הדם וכו'. ברייתא בפ\\\"ק דמעילה (דף ז'):\",3,0],[8,367,3,4,\"כל חטאות המתות וכו' אסור ליהנות בהם ואם נהנה לא מעל. משנה פ\\\"ג מעילה (דף י') ופ\\\"ד דתמורה (דף כ\\\"א):\",1,0],[8,367,3,6,\"המפריש חטאתו ואבדה והפריש אחרת תחתיה וכו'. בסוף פ\\\"ק דמעילה (דף ז') ופירש\\\"י אלא ששחט שניהם בבת אחת כגון ששחטום שני כהנים כאחד דכחד גופא דמי דלא קדמה שחיטה של אחת לשל חבירתה אבל בזה אחר זה לא וכו' משום דבשעה ששחט הראשונה מיד נעשית השנייה מותר חטאת:\",1,0],[8,367,3,7,\"כל חטאת העוף וכו'. משנה בזבחים פ\\\"ז (דף ס\\\"ו:).\",1,0],[8,367,3,7,\"ומ\\\"ש חוץ מעולת העוף שנמלקה למטה כמליקת חטאת לשם חטאת. שם במשנה פלוגתא דר\\\"א ור' יהושע ופסק כרבי יהושע:\",2,0],[8,367,3,8,\"מנחה שנתפגלה וכו'. נלמד ממה ששנינו בריש מעילה כמו שנתבאר בר\\\"פ זה:\",1,0],[8,367,3,9,\"וכן קומץ שיצא לחוץ או לן וכו' אבל אם נטמא הקומץ והקטירו וכו'. משנה בפ\\\"ג דמנחות (דף כ\\\"ה) נטמא הקומץ והקריבו הציץ מרצה יצא והקריבו אין הציץ מרצה:\",1,0],[8,367,3,9,\"יצאו השירים וכו'. בתוספתא פ\\\"ד דמנחות נטמאו השירים והקטיר את הקומץ בשתיקה הכל מודים שאין מועלין בהם. ואיכא למידק שזה סותר מ\\\"ש בפ\\\"ב ואם נפסלו השירים או חסרו ואח\\\"כ הקטיר הקומץ הואיל והקטרה זו אינה מתרת השירים באכילה הרי הדבר ספק אם יצאו ידי מעילה וצ\\\"ע:\",2,0],[8,367,3,9,\"כתב הר\\\"י קורקוס ז\\\"ל יש לדקדק במ\\\"ש רבינו יצאו השירים או נטמאו ואח\\\"כ הקטיר הקומץ אע\\\"פ שהם אסורים באכילה אין מועלין וכו' ומ\\\"ש מיצא הבשר שנתבאר בסמוך שמועלין בו והרי בשר ושירים דין אחד להם שאם נטמא או יצא לא יזרק ואם זרק הורצה וכמ\\\"ש פ\\\"א מפסולי המוקדשין וכן דין השירים בפי\\\"א וכיון דגבי שירים חשיב קרב כמצותו כיון שבדיעבד הורצה ה\\\"ה גם לבשר. לכך נראה דהכא נטמא מקצתו מיירי רבינו שדינו [להקטיר] הקומץ לכתחלה כיון שנשאר במקומו וכמ\\\"ש גבי בשר וגבי קומץ וכבר נתבאר בראש הפרק כן גבי בשר והוא מ\\\"ש כאן גבי קומץ וזהו שקראו קרב הקומץ כמצותו כי דינו להקטירו לכתחלה וז\\\"ש אע\\\"פ שאסור באכילה דמשמע שזה הוא החידוש ותו לא וסמך על מה שביאר גבי בשר גם על מ\\\"ש שהרי קרב הקומץ כמצותו וזה אינו אלא בנשתייר עכ\\\"ל:\",3,0],[8,367,3,10,\"הנהנה מקדשי קדשים כולם וכו'. פלוגתא דרב ולוי בפ\\\"ב דמעילה (דף ט') ופסק כרב דאמר מה שנהנה יפלו לנדבה ותניא כוותיה ואע\\\"ג דתניא כוותיה דלוי לא עדיפא כולי האי דמשמע דהוא גופיה תני לה דלמדים לפני חכמים היינו לוי כך כתב הר\\\"י קורקוס ז\\\"ל. ופירש\\\"י מה שנהנה כלומר קרן וחומש שחייב לשלם בשביל מה שנהנה יפלו לנדבה לקרבנות צבור. והתוס' פירשו לנדבה לעולות קיץ למזבח.\",1,0],[8,367,3,10,\"ומה שכתב או שנהנה מן העולה כולה או מן הקומץ והלבונה ומנחת כהנים והחביתין יפול מה שנהנה לנדבה. בתוספת' שאכתוב בסמוך.\",2,0],[8,367,3,10,\"ומ\\\"ש מעל בקרבנות הצבור יפול מה שנהנה ללשכה. שם בברייתא קרבנות צבור לצבור. ופירש רש\\\"י לנדבת צבור לשופרות, ובסוף תוספתא דמעילה דנהנה מקדשי קדשים לפני זריקת דמים מקדשים קלים לאחר זריקת דמים מן העולה מן הקומץ ולבונה ומנחת כהן משוח ומנחת נסכים יפלו ללשכה מקרבנות צבור יפלו לנדבה כך היא נוסחא דידן בתוספתא, וגירסת רבינו בתוספתא היתה מהופכת מנוסחא דידן ויש ראיה לנוסחת רבינו דבגמ' דידן תניא גבי הנהנה מקדשי קדשים לפני זריקת דמים ומקדשים קלים לאחר זריקת דמים מה שנהנה יפלו לנדבה. ופירוש ללשכה מ\\\"כ בשם הרא\\\"ש דהיינו לבדק הבית לשיירי לשכה:\",3,0],[8,367,3,11,\"נהנה קודם זריקה וכו'. ה\\\"ז פטור. מימרא דרבא שם (דף י'):\",1,0],[8,367,3,12,\"קדשי המזבח חלבן וביציהן וכו'. משנה בפ\\\"ג דמעילה (דף י\\\"ב).\",1,0],[8,367,3,12,\"ומ\\\"ש לפיכך ולד הקדשים וכן ולד המעשר לא יינק מאמו. גם זה משנה שם (דף י\\\"ג).\",2,0],[8,367,3,12,\"ומ\\\"ש ויש לאדם להתנדב ולומר וכו'. זהו פירוש רבינו במה ששנינו שם ואחרים מתנדבים כן ורש\\\"י פירש בע\\\"א:\",3,0],[8,367,3,12,\"כתב הראב\\\"ד יהיה הקדש לולדות הקדשים א\\\"א ואם יאמר יהיה הקדש לולדות וכו'. ויש לתרץ שמ\\\"ש רבינו יהיה הקדש היינו לומר יהא מזומן וכדברי הראב\\\"ד. ועי\\\"ל שאפי' יאמר יהיה הקדש כיון שסיים ביה לולדות הואיל ותכף תיבה זו לזו ולכך נתכוין מתחלה דבריו קיימין וכדא\\\"ר יוסי בתמורה (דף י\\\"א) גבי האומר עולה היא וולדה שלמים:\",4,0],[8,367,3,13,\"הקדיש בהמה ועוף למזבח קדושת דמים וכו'. משנה וגמרא שם:\",1,0],[8,367,4,1,\"המפריש מעות לחטאתו וכו'. בריש תוספתא דמעילה.\",1,0],[8,367,4,1,\"ומ\\\"ש הפריש לשלמיו אין מועלין בהם. משנה במעילה פרק ג' (דף י\\\"א) המפריש מעות לנזירותו לא נהנים ולא מועלים מפני שהם ראויים לבא כולם שלמים:\",2,0],[8,367,4,2,\"הקדיש אבר אחד לדמיו למזבח הרי זה ספק וכו'. בפ\\\"ק דתמורה (דף י\\\"א) בעיא דלא איפשיטא. ודע דבספרי רבינו כתוב לפיכך תקבר וט\\\"ס הוא וצריך להגיה לפיכך תקרב וכך מצאתי בספר ישן וכך הם דברי רבינו בהל' ערכין פ\\\"ה ושם ובפט\\\"ו ממעשה הקרבנות ביאר היאך תקרב. ומה שיש לדקדק בדין זה כתבתי שם.\",1,0],[8,367,4,2,\"ועל מ\\\"ש רבינו ואם נפדה אין מועלין בפדיונו כתב הראב\\\"ד א\\\"א למה אין מועלין בפדיונו וכו'. וטעם רבינו דשמא לא פשטא בכולה ונמצא שדמיה חולין זולת דמי אותו אבר ולפי זה צ\\\"ל דאין מועלין בפדיונו היינו בדמי אותה בהמה כל היתר על דמי אותו אבר. ועוד י\\\"ל דבכלל צדדי הבעיא הוא שכיון שדבריו סותרים את דבריו שאמר לדמיו ואמר למזבח דילמא לא חיילא קדושה כלל. והר\\\"י קורקוס ז\\\"ל תירץ שכיון שאינו ראוי לפדיון דשמא לא פשטה קדושת הגוף בכולו נמצא שאינו תופס פדיונו ואין דמים אלו דמי פדיון אלא דמים אחרים וחולין הם עכ\\\"ל:\",2,0],[8,367,4,3,\"המפריש מעות לנזירותו וכו' עד ומועלין בהם. משנה בפ\\\"ג דמעילה (דף י\\\"א) המפריש מעות לנזירותו לא נהנים ולא מועלים מפני שהם ראויים לבא כולם שלמים מת והיו לו מעות סתומים יפלו לנדבה מעות מפורשים דמי חטאת ילכו לים המלח וכו' דמי עולה יביאו עולה ומועלין בהם. ופי' רש\\\"י המפריש מעות ולא פירש אלו לחטאת ואלו לעולה ואלו לשלמים לא נהנים ולא מועלים בכל אותם מעות מפני שהם ראויים להביא כולם שלמים כלומר דבכל מנה ומנה מצינן למימר זה הפריש לשלמים ושלמים קדשים קלים נינהו ואין בהם מעילה וכו'. ומ\\\"ט אזיל לקולא דאי אמרת נימא דכולם ראויים להביא עולה ואיכא מעילה בכולהו מכל מקום דמי שלמים איכא בינייהו דאינם בני מעילה ואי מייתי עלייהו קרבן מעילה אשתכח דקא מייתי חולין לעזרה הלכך לקולא דלא נהנין ולא מועלין. מעות סתומים דלא פריש יפלו לנדבה דהלכה היא בנזיר דמי חטאת ילכו לים המלח דחטאת שמתו בעליה היא. דמי עולה יביאו עולה דדורון בעלמא היא דלאו לכפרה אתיא. וכתבו התוס' מפני שהם ראויים לבא כולם שלמים דכיון דלא פירש אם ירצה יביא כל המעות לשלמים. ובפרק רביעי דנזיר (דף כ\\\"ד כ\\\"ה) אהא דתנן היו לו מעות סתומים יפלו לנדבה פריך והלא דמי חטאת מעורבים בהם אמר ר\\\"י הלכה היא בנזיר, ופירשו רש\\\"י והתוספות הלכה למשה מסיני הוא דסתומים יפלו לנדבה אף על פי שדמי חטאת מעורבים בהם:\",1,0],[8,367,4,3,\"אמר אלו לחטאתי והשאר וכו' עד ואם מת יפלו לנדבה וכו' ומועלים בהם. תוספתא פירקא קמא דמעילה אלא שיש בה קצת טעות סופר ואיתא בפרק ד' דנזיר כלשון רבינו. ואיכא למידק למה מועלין בשאר בכולן והלא סתומים הם ומ\\\"ש ממה שנתבאר בסמוך דסתומים אין מועלין בהם, וכתבו התוס' דמיירי במת דליכא למימר ביה מימליך ומייתי שלמים וכ\\\"כ בתוספתא פירקא קמא דמעילה ועוד דשאני הכא שאמר והשאר לשאר נזירותי משמע דלכל הנשאר עליו קאמר ועוד שכיון שהתחיל לפרש השאר נמי הוו כמפרש שכל חיובו מביא במעות אלו.\",2,0],[8,367,4,3,\"ומה שכתב הפריש מעות ואמר אלו לחטאתי וכו' ומועלין במקצתן. יש לתמוה ודלמא אותו מקצת מאשר ייחד לשלמים ואין בו מעילה ולא יביא קרבן מעילה מספק דילמא מייתי חולין בעזרה כדאמרינן לעיל בסמוך. ותירץ הר\\\"י קורקוס ז\\\"ל דאפשר דמקצתן דקאמר היינו כשהם יותר מדמי שלמים אי נמי שכיון שנתערבו בכל זוז יש בו חטאת ועולה ושלמים. והראשון נראה יותר:\",3,0],[8,367,4,4,\"ומ\\\"ש אחד ממחוייבי קינין וכו' ומועלין במקצתן. מבואר דטעמא משום דליכא בהן שלמים אלא חטאת ועולה.\",1,0],[8,367,4,4,\"ומ\\\"ש ואם מתו יפלו לנדבה טעמא מפרש בפרק ד' דנזיר כמו שכתבתי בסמוך הלכה היא בנזיר ומסיק שם דהלכה היא בחייבי קינים נמי:\",2,0],[8,367,4,5,\"המפריש חטאת על אכילת חלב וכו'. ברייתא וגמרא בסוף כריתות (דף כ\\\"ז).\",1,0],[8,367,4,5,\"ומ\\\"ש הפריש מעות לחטאת חלב וקנה בהם חטאת דם וכו'. שם בברייתא.\",2,0],[8,367,4,5,\"ומ\\\"ש לחלק בין שוגג למזיד. שם בתוספתא. ופירוש לא מעל היינו לומר דבאותו מעשה שעשה לא מעל אלא שבגמרא תלי כפרה במעילה ורבינו עשה בהפך:\",3,0],[8,367,4,6,\"המפריש שתי סלעים לאשם וכו' עד ויפלו לנדבה. משנה וגמרא שם (דף כ\\\"ו:)\",1,0],[8,367,4,7,\"הנהנה מדמי חטאת וכו' וכן אם נהנה מדמי אשם עד שלא קרב אשמו יוסיף חומש ויביא בדמיו אשמו. כך היא הנוסחא הנכונה בדברי רבינו ובספרים כתוב ויביא בדמיו חטאתו והוא ט\\\"ס. ודינין אלו ברייתא בפ\\\"ב דמעילה (דף ט') הנהנה מדמי חטאת ומדמי אשם עד שלא קרבה חטאתו יוסיף ויביא חטאת עד שלא קרב אשמו יוסיף ויביא אשם קרבה חטאתו ילכו לים המלח כבר קרב אשמו יפלו (דמיו) לנדבה וכו' קרבנות המזבח למזבח קרבנות בדק הבית לבדק הבית. ופי' רש\\\"י כגון שנהנה ממקצת הדמים שהפריש לחטאתו או לאשמו אם נודע לו שמעל קודם שקרב החטאת והאשם מהשאר מוסיף הקרן והחומש על המעות שנשארו ויביא בכולן החטאת או האשם ואם לא נודע לו עד אחר שהקריב חטאתו א\\\"נ נודע לו קודם אלא שלא בא לשלם עד שקרבה ה\\\"ל חטאת שמתו בעליה ולמיתה אזלא וים המלח למעות במקום מיתה לבהמה אבל באשם קי\\\"ל כל שבחטאת מתה באשם רועה ויפלו דמיה לנדבה הילכך מעות אלו יפלו לנדבה ובגמרא העמידו רישא זו אליבא דר\\\"ש וס\\\"ל כל חטאת שכיפרו בעליה באחרת תמות ולכך מעות ילכו לים המלח כיון שהיו ראויים להכלל עם החטאת ולא נכלל וקרבה החטאת אבל חכמים שסוברים שלא אמרו חטאת שכיפרו בעליה מתה אלא באבדה ונמצאת אחר כפרה ה\\\"נ לא ילכו לים המלח והיינו סיפא דכל קרבנות מזבח למזבח דמשמע בין קודם כפרה בין לאחר כפרה והעלה אביי דרישא ר\\\"ש וסיפא רבנן ואחר כך אמרו שם (דף מ\\\"ד) אמר רבא הא דאמרת כבר קרבה חטאתו ילכו לים המלח ה\\\"מ דאתיידע ליה קודם כפרה אבל (אתיידע ליה) לאחר כפרה יפלו (דמים) לנדבה שאין מפרישין בתחילה לאיבוד. פי' שכשנודע קודם כפרה ה\\\"ל להוסיף קרן וחומש על דמי חטאת שהרי לא היתה תחלת הפרשתן לאיבוד וכיון שלא הוסיף הוי כחטאת שכיפרו בעליה ולמיתה אבל כשנודע לו אחר שקרב חטאת אם מתה ילכו לים המלח נמצא תחלת הפרשתן לאיבוד הילכך יפלו לנדבה. ויש לתמוה על רבינו כיון שהלכה כרבנן דאין חטאת שכיפרו בעליה מתה אלא כשנמצאת אחר כפרה כמו שנתבאר בפרק רביעי מפסולי המוקדשין איך כתב רישא דברייתא ודברי רבא דכולהו בדרישא שייכא דאילו לרבנן דסברי שכל שנמצאת קודם כפרה אינה מתה ה\\\"ה כאן שנודע לו קודם כפרה אין הולכות לים המלח דרישא ודברי רבא ע\\\"כ אדר\\\"ש קיימי. ותירץ הר\\\"י קורקוס ז\\\"ל שסובר רבינו שכיון שרבא אמר סתם הא דאמרת ה\\\"מ וכו' אבל וכו' מ\\\"ט אין מפרישין וכו' ודאי דלהלכה אמר כך ולא אליבא דר\\\"ש בלחוד ופליג אדאביי דמוקי רישא כר\\\"ש דוקא וסבר רבא דרבנן מודו בכי הא דדוקא באבדה הוא שאמרו כן לפי שחטאת זו היתה עיקר חטאת ואינה יוצאה מדין חטאת ואין אומרין שתמות אלא א\\\"כ היתה אבודה בשעת כפרה שהרי נדחית לגמרי מהקרבה אבל מעות אלו לא הפרישן לקנות חטאת ובכל דהו אזלי לים המלח ומודו רבנן לר\\\"ש בכי הא. א\\\"נ י\\\"ל דדמיא הא מילתא להא דאמר רב הונא שאם משך אחת מהן דכ\\\"ע מודו שהשנייה מתה אף על פי שנמצאת קודם כמו שנתבאר פרק רביעי דתמורה ופרק רביעי מפסולי המוקדשין וטעמא משום דדחיה בידים היא ולא נחלקו אלא בבא לימלך וה\\\"נ כיון שנודע לו והיה יכול להוסיף בחטאת ולא הוסיף ולא בא לימלך הא דחנהו בידים ואביי אפשר דפליג עלה אבל רבא סבר כרב וברייתא כרבנן ומפרש דינא אליבא דהלכתא. גם מדברי המקשה שם יש קצת סיוע לזה שלא הקשה אלא משום דמשמע ליה דכל קדשי מזבח למזבח בכל גוונא רישא ר\\\"ש היא ופליגא אסיפא וע\\\"ז תמה רישא ר\\\"ש וסיפא רבנן וא\\\"ל אין אבל אם הסיפא לא מיירי בכל גוונא פירוש דלא הוי כללא דסיפא גוונא דרישא לא אצטרכינן לאוקמה רישא ר\\\"ש וסיפא רבנן כדפרישית דלא דמי עכ\\\"ל:\",1,0],[8,367,4,8,\"המוכר עולתו ושלמיו לא עשה כלום וכו'. בפסחים פרק האשה (דף פ\\\"ט:) ואיתיה בתוספתא דפסחים פ\\\"ז:\",1,0],[8,367,4,9,\"יש מעילה בנדרים וכו'. בעיא דאיפשיטא בפרק אין בין המודר (נדרים דף ל״ה).\",1,0],[8,367,4,9,\"ומה שכתב לפיכך אין לה פדיון וכו' עד לפיכך יש לה פדיון. שם:\",2,0],[8,367,4,9,\"היתה לפניו ככר של הפקר וכו' עד לפי טובת הנייה שבה. מימרא דרבה שם (דף ל\\\"ד:):\",3,0],[8,367,4,10,\"האומר לחבירו ככרי עליך הקדש וכו'. שם בעיא דאיפשיטא.\",1,0],[8,367,4,10,\"ומ\\\"ש וכן כל כיוצא בזה משאר הקונמות וכו'. טעמו משום דלישנא דברייתא וגמרא יש מעילה בקונמות.\",2,0],[8,367,4,10,\"ומה שכתב וכל דברים הנאסרים עליו מנדר כזה מצטרפים וכו':\",3,0],[8,367,4,11,\"האומר הנטיעות האלו קרבן אם אינם נקצצות וכו'. משנה וגמרא פרק ג' דנדרים (דף כ\\\"ח).\",1,0],[8,367,4,11,\"ומה שכתב וכיון שנקצצו אינם צריכים פדיון וכו'. שם (דף כ\\\"ח כ\\\"ט) פלוגתא דאמוראי ופסק כעולא דמשמע התם דרבא דהוא בתרא סבר כוותיה.\",2,0],[8,367,4,11,\"ומ\\\"ש במה דברים אמורים בשפדאן המקדיש אבל אם פדאן אחר וכו'. מימרא דר' יוחנן שם (דף ל'):\",3,0],[8,367,5,1,\"אחד המקדיש לבדק הבית וכו'. משנה בפרק ג' דמעילה (דף י\\\"ג). וציר וחומץ שכתב רבינו. בת\\\"כ פרשת ויקרא:\",1,0],[8,367,5,2,\"כל קדשי בדק הבית וכו'. משנה בפרק ד' דמעילה (דף ט\\\"ו):\",1,0],[8,367,5,3,\"אכל והאכיל את חבירו וכו' עד ומעל. משנה בספ\\\"ה דמעילה (דף כ'):\",1,0],[8,367,5,5,\"אין מעילה אלא בתלוש מן הקרקע וכו'. ברייתא שם (דף י\\\"ח):\",1,0],[8,367,5,5,\"הדש בשדה הקדש מעל וכו'. פ\\\"ג דמעילה (דף י\\\"ב).\",2,0],[8,367,5,5,\"ומ\\\"ש רבינו שהאבק של השדה מועיל לשדה פי' שהאבק של השדה מועיל לאותו דבר שנידש בשדה. ומ\\\"ש וכן אם חרש וכו': הדר במערת הקדש. ספ\\\"ה דמעילה (דף כ').\",3,0],[8,367,5,5,\"ומ\\\"ש או בצל אילן או שובך. בתוספתא דמעילה פ\\\"ק הדר בצלו של שובך או בצלה של מערה לא נהנין ולא מועלין.\",4,0],[8,367,5,5,\"ומ\\\"ש וכן המקדיש בית בנוי הדר בו לא מעל אבל המקדיש עצים ואבנים וכו'. שם בגמרא פ\\\"ה. ואיכא למידק דהא לא חילק ר\\\"ל בכך אלא כי היכי דלא תסייעיה לרב דאמר המשתחוה לבית אסרו ומאחר שרבינו פסק בפ\\\"ח מע\\\"ז כרב לא ה\\\"ל לחלק בכך כאן. וי\\\"ל דמשמע לרבינו דהא דמפליג ר\\\"ל לא לדחויי דלא תסייעיה לרב בלחוד אמרה אלא לקושטא דמילתא אמרה ולישנא דידיה הכי מוכח דאמר התם כשהקדישו ולבסוף בנאו משמע דקושטא הכי הוא. ויש סעד לזה מדהוה מצי לשנויי הנאה הנראית לעינים אסרה תורה כדשני לעיל ושני התם כשהקדישו ולבסוף בנאו משמע דהכי ס\\\"ל ולפיכך פסקה רבינו ואפ\\\"ה לא דחאה לדרב משום דלא אשכחן דפליג עליה בהדיא ואית לן למימר דטעמא משום חומרא דע\\\"ז:\",5,0],[8,367,5,6,\"גדולי הקדש מועלין בהם וכו'. משנה בפ״ג דמעילה (דף י״ג) פלוגתא דת״ק ור' יוסי ופסק כר' יוסי וצריך טעם למה. והר״י קורקוס ז״ל כתב שטעמו משום דבפרק הספינה (בבא בתרא דף ע״ט) הובאה משנה זו ושנו הרישא בשם ר״י ושנו בברייתא אמר רבי נראין דברי ר״י לר' יוסי בבור ושובך משמע דקים ליה דת״ק היינו ר״י וידוע דר״י ורבי יוסי הלכה כרבי יוסי גם שם העלה רבה דפליגי ת״ק ורשב״א דבבור ושובך דוקא פליגי אבל בשדה ואילן ד״ה מועלין במה שבתוכן דגידולי הקדש הם הילכך הכי נקטינן גם פ״ד דפסחים נתבאר שמועלין בגדולי הקדש גבי שלשה דברים שעשו אנשי יריחו גם בתמורה פ״ז שנינו ומועלים בגידוליהם הילכך כרבי יוסי נקטינן עכ״ל:\",1,0],[8,367,5,6,\"ומ\\\"ש אבל המקדיש בור ריקן וכו'. שם במשנה.\",2,0],[8,367,5,6,\"ומ\\\"ש וכן הזבל והפרש וכו'. שם (דף מ\\\"ו:) ופירש\\\"י הזבל הוא הפרש של קדשים שהוא בחצר ה\\\"ה בכל מקום אלא שדרכו בחצר של הקדש. ומצאתי כתוב ללשכה לא לקיץ המזבח קאמר דא\\\"כ הל\\\"ל לנדבה אלא לשיירי הלשכה:\",3,0],[8,367,5,6,\"מעין שהוא יוצא מתוך שדה הקדש וכו' עד ולא מועלין. משנה פ\\\"ג דמעילה שם:\",4,0],[8,367,5,6,\"כתב הראב\\\"ד ערבה הגדילה א\\\"א זה שיבוש שלא נאמר במשנה וכו'. ואיני יודע למה יאמר שהוא שיבוש למי שיפרש פירוש אחר שלא כפירושו:\",5,0],[8,367,5,6,\"אילן של הדיוט הסמוך לשדה הקדש וכו'. ג״ז משנה שם שרשי אילן של הדיוט באים בשל הקדש ושל הקדש באין בשל הדיוט לא נהנים ולא מועלין. ובפרק לא יחפור (בבא בתרא דף כ״ו:) מקשה דמרישא משמע דבתר אילן אזלינן ובסיפא משמע דבתר קרקע אזלינן ומשני כאן בתוך ט״ז אמה כאן חוץ לט״ז אמה:\",6,0],[8,367,5,7,\"קן שבראש האילן של הקדש וכו'. משנה בפ\\\"ג דמעילה (י\\\"ג:) קן שבראש אילן של הקדש לא נהנין ולא מועלין שבאשרה יתיז בקנה ומוקי לה בגמ' אליבא דר\\\"י ההיא של אשרה יתיז בקנה בדאייתי עצים מעלמא ומקשה א\\\"ה אמאי של הקדש אין נהנין ואין מועלין אלא בגידולין הבאים לאחר מכאן וקסבר אין מועלין בגידולין ה\\\"נ מסתברא וכו' א\\\"ר אבהו א\\\"ר יוחנן לעולם דאייתי מעלמא ומאי יתיז יתיז אפרוחים ואסיקנא אפרוחים כאן וכאן מותרין ביצים כאן וכאן אסורים אמר רב אשי אם אפרוחים צריכין לאימן כביצים דמו ומשמע דקן דאייתי עצים מעלמא נהנים ממנו ויש לתמוה על רבינו שסתם וכתב שאין נהנים בו:\",1,0],[8,367,5,9,\"המקדיש את היער וכו' עד ולא בנביה. משנה שם:\",1,0],[8,367,5,9,\"כתב הראב\\\"ד והוא הגוף הקשה א\\\"א אינו כן אלא העלה הנובל וכו'. ואין משם ראייה דהכא גריס רבינו נבייה בבי\\\"ת. והר\\\"י קורקוס ז\\\"ל כתב וז\\\"ל רבינו כתב במשנה שיש גורסין נוייה שזו החתירה הקשה דומה לנוייה שהיא בפני עצמה בתוך הפרי עכ\\\"ל:\",2,0],[8,367,5,10,\"המקדיש את עבדו וכו'. בפירקא קמא דסנהדרין (דף ט״ו) ובפרק השולח (גיטין דף ל״ט) פלוגתא דתנאי ופסק כתנא קמא:\",1,0],[8,367,5,11,\"הזורע פירות הקדש וכו'. פ\\\"ט דתרומות גדולי הקדש ומע\\\"ש חולין ופודה אותם בזמן זרעם. ופירש ר\\\"ש כגון שזרע סאה והוסיף כמה סאין א\\\"צ לפדות אלא סאה אחת, ובתוספתא דתרומות פ\\\"ח גידולי הקדש אין חייבין עליהם קרן וחומש [על מקום אחר] אלא לפי חשבון וחייבים בחלה הידים וטבול יום אין פוסלין בהם כדרך שפוסלין בחולין:\",1,0],[8,367,5,12,\"שמרים של הקדש וכו'. ברייתא בפרק המוכר פירות (בבא בתרא דף צ״ז).\",1,0],[8,367,5,12,\"ומ\\\"ש והנהנה לא מעל. כן פירש\\\"י דחומרא היא מדרבנן ומיהו אם נתן ג' ומצא ד' יין גמור הוא. וכתב הר\\\"י קורקוס ז\\\"ל דהא דאין מועלין בלא מצא ד' וסתמו הכי הוא.\",2,0],[8,367,5,12,\"ומ\\\"ש במה דברים אמורים בקדשי בדק הבית וכו' שם:\",3,0],[8,367,5,13,\"המקדיש תרנגולת למזבח וכו'. משנה וגמרא פ\\\"ג דמעילה (דף י\\\"ב):\",1,0],[8,367,5,14,\"כתנות כהונה שבלו וכו'. בפרק האיש מקדש (קידושין דף נ״ד):\",1,0],[8,367,5,15,\"קדשי עכו\\\"ם אם לבדק הבית הקדישו מועלין בהם. בפ' ב\\\"ש (זבחים מ\\\"ה) ובריש תמורה.\",1,0],[8,367,5,15,\"ומ\\\"ש ואם קדשי מזבח הן וכו'. שם פלוגתא דר\\\"ש ור' יוסי ופסק כר\\\"ש ואיני יודע למה ואפשר שטעמו משום דבסוף פרק קמא דערכין (דף ה':) מייתי ברייתא סתמא כר\\\"ש:\",2,0],[8,367,5,16,\"קול ומראה וריח וכו'. פ' כל שעה (פסחים דף כ״ו.) ובפ״ק דכריתות (דף ו'.) ופירשו שם דקודם שתעלה תמרתו מועל:\",1,0],[8,367,6,1,\"יש דברים שהאדם נהנה בהם ולא יפגמו וכו' עד בדבר עצמו. משנה בפ\\\"ה דמעילה (דף י\\\"ח):\",1,0],[8,367,6,2,\"קדשי קדשים התמימים וכו'. שם במשנה (דף י\\\"ח.) תלש מן החטאת כשהיא חיה לא מעל עד שיפגום כשהיא מתה כיון שנהנה מעל ובגמרא (דף י\\\"ט:) מכדי אי בבהמה תמימה היינו כוס של זהב אמר רב פפא בבעלת מום עסקינן. ופירש\\\"י מכדי בחטאת בהמה תמימה מיירי מתני' וכו' עד הילכך לא תני בה עד שיפגום:\",1,0],[8,367,6,2,\"כתב הראב\\\"ד קדשי קדשים התמימים א\\\"א זה אמרו מעצמו ואין לו סמך וכו'. ואני שמעתי ולא אבין שהרי דברי רבינו מבוארים בגמ' שכתבתי בסמוך והיאך כתב עליו שמעצמו אמרו ואפשר שלא היה כתוב כן בנוסחא שלו. ועל מ\\\"ש שהקרבן התמים וכו' אפשר שיפול בו מום, כתב בעל מ\\\"ע דהשתא מיהא תמים הוא ואין לנו בהקדשות אלא מקומו ושעתו כדאיתא בתוספתא רפ\\\"ב דמעילה ובשעה שנהנה פגם ועוד תניא התם ועוד שתהא הנאתו ופגימתו כאחד עכ\\\"ל:\",2,0],[8,367,6,3,\"המועל בקדשי וכו'. בפרק האיש מקדש (קידושין דף נ״ב:) תנן המקדש וכו' בהקדש במזיד קידש בשוגג לא קידש דברי רבי מאיר רבי יהודה אומר בשוגג קידש במזיד לא קידש ובגמרא (דף נ״ה) פסק הלכה כרבי יהודה דאמר הקדש בשוגג מתחלל במזיד אין מתחלל.\",1,0],[8,367,6,3,\"ומה שכתב במה דברים אמורים בשמעל בקדש והוציאו בתורת חולין והקנהו לאחר. בפ\\\"ה דמעילה (דף כ') תנן נטל פרוטה של הקדש ה\\\"ז לא מעל נתנה לחבירו הוא מעל וחבירו לא מעל ופירש\\\"י הנותן מעל שהוציאה לחולין.\",2,0],[8,367,6,3,\"ומ\\\"ש אבל אם נהנה בו ופגמה ולא הקנה לאחר יש בו מועל אחר מועל ואין מועל אחר מועל במוקדשין אלא בהמה וכלי תשמיש בלבד כיצד בקע בקורדום וכו'. שם במשנה (דף י\\\"ט:) אין מועל אחר מועל במוקדשין אלא בהמה וכלי שרת כיצד רכב על גבי בהמה ובא חבירו ורכב ובא חבירו ורכב כולם מעלו שתה בכוס של זהב ובא חבירו ושתה ובא חבירו ושתה כולם מעלו תלש מן החטאת ובא חבירו ותלש ובא חבירו ותלש כולם מעלו:\",3,0],[8,367,6,3,\"וכתב הראב\\\"ד על דברי רבינו א\\\"א בכל זה יצא מכלל משנתנו. ואני אומר שמ\\\"ש ובודאי בהמה דומיא דכלי שרת אינו הכרע דמדקתני רכב על גבי בהמה משמע דבבהמה טמאה איירי שדרכה ברכיבה ולא בבהמה טהורה שאין דרכה ברכיבה. ועוד דבהמה תמימה בהדיא קתני לה תלש מן החטאת ובא חבירו ותלש וכו' כולם מעלו ואם כן כי קתני רכב על גבי בהמה ע\\\"כ בבהמה טמאה היא, ועל פי הדברים האלה אין התוספתא סותרת המשנה דכי קתני מתני' ובא חבירו ורכב בבהמה טמאה מיירי שאינה קדושה אלא קדושת דמים דומיא דבקע בקרדום דקתני בתוספתא וכיון דבהמה דקתני במתני' אינה טהורה שקדושה קדושת הגוף אלא טמאה שאינה קדושה אלא קדושת דמים הוא הדין לכלי שרת דקתני מתני' בכלי תשמיש איירי שאינם קדושים אלא קדושת דמים ויש בהם מועל אחר מועל ובזה באו מוסכמים המשנה והתוספתא. אך קשה לזה דאמרי' בגמ' מני מתני' ר' נחמיה היא וכו' עד לא כ\\\"ש ופירש רש\\\"י אם אחרים מביאין לקדושתן כלומר כיון דכלי שרת חמירי וכו' משמע בהדיא דכלי שרת דתנן במתני' בכלי שרת ממש הוא. לכן נראה שרבינו מפרש דכלי שרת דמתני' כלי שרת ממש הם וכבר הזכירה רבינו בסמוך לקמן ואף על פי שכתבו בלשון יראה לי היינו לענין שאם נתנה לחבירו וחבירו לחבירו כולם מעלו אבל לענין שיש בו מועל אחר מועל מדינא הוא מאחר שהיא קדושה קדושת הגוף וכלי תשמיש שכתב כאן היינו כגון קרדום וכיוצא בו שאינם קדושים אלא קדושת דמים וכדאיתא בתוספתא והוא נלמד ממתני' דקתני על גבי בהמה ומיירי בבהמה טמאה שאינה קדושה אלא קדושת דמים וכדפרישית ומינה נילף לכלי תשמיש שאינם קדושים אלא קדושת דמים:\",4,0],[8,367,6,4,\"ומה שכתב נטל הקורדום ונתנו לחבירו וכו' נטל הכוס ונתנו לחבירו וכו' נתן החמור לחבירו מתנה וכו'. בתוספתא דמעילה פרק שני והוא נלמד מהמשנה שכתבתי בסמוך נתנה לחבירו הוא מעל וחבירו לא מעל.\",1,0],[8,367,6,4,\"ומה שכתב וכן המשאיל קרדום של הקדש וכו'. בפרק השואל (דף צ\\\"ט):\",2,0],[8,367,6,5,\"בהמת קדשי מזבח וכו'. משנה בפ\\\"ה דמעילה (דף י\\\"ט) תלש מן החטאת ובא חבירו ותלש ובא חבירו ותלש כולם מעלו.\",1,0],[8,367,6,5,\"ומ\\\"ש וכן אם נתנה לחבירו וחבירו לחבירו כולם מעלו: כתב הראב\\\"ד דבר זה לא נמצא לו יסוד וכו'. והנה הראב\\\"ד עצמו מצא לו יסוד מהתוספתא. ומ\\\"ש אבל ק\\\"ל מ\\\"ש עולה, מדברי רבינו נראה דלאו דוקא עולה אלא ה\\\"ה לכל קדשי מזבח וחדא מקדשי מזבח נקט. אבל עדיין קשה דלא ה\\\"ל למינקט אלא קל שבכולן ומינה נילף לחמורים ואמאי נקט עולה שהיא חמורה שבכולן. וכתב הר\\\"י קורקוס ז\\\"ל דטעמא משום דפתח בה קרא בתחלת הקרבנות. ודע שיש נוסחא בספרי רבינו שגורס בהמת קדשי קדשים והיא גירסא נכונה דאילו קדשים קלים אין מועלין בהם עד שיזרק הדם כדתנן בפ\\\"ק דמעילה (דף ו'):\",2,0],[8,367,6,6,\"בהמת קדשי קדשים שנפל בה מום וכו'. בספ\\\"ה דמעילה (דף כ') פלוגתא דתנאי בברייתא ופסק כחכמים:\",1,0],[8,367,6,7,\"אמרו חכמים שהנוטל אבן וכו'. בפרק ה' דמעילה שם תנן נטל אבן או קורה של הקדש הרי זה לא מעל נתנה לחבירו הוא מעל וחבירו לא מעל ובגמרא ומאי שנא הוא ומאי שנא חבירו אמר שמואל בגזבר המסורות לו עסקינן, ומשמע לרבינו דכי פריך מאי שנא הוא ומאי שנא חבירו היינו לומר דכשם שהוא מעל היה ראוי לומר חבירו מעל גם כן ואוקמוה בגזבר המסורות לו הא בשאר כל אדם שניהם מעלו. ויש סיוע לפירוש רבינו ממה ששנינו בתוספתא פרק חמישי דמעילה וכתבה רבינו בסמוך המפריש שקלו והוציאו בשאר צרכיו בין הוא בין חבירו מעל. והוקשה לרבינו דכיון דקיימא לן אין מועל אחר מועל בדבר שקדוש קדושת דמים היאך מעלו שניהם ולכך העמידה במועל בזדון, וק\\\"ל אם כן אמאי דחיק גמרא לאוקמיה בגזבר לישני דהכא במאי עסקינן בשוגג דאין בו מועל אחר מועל. ואפשר שטעמו של רבינו משום דהא לא איצטריכא לתנא לאשמועינן הכא דהא אשמעינן לעיל בההוא פירקא. ובענין מה שהעמידה בגזבר המסורות לו מפרש רבינו דקאי למקבל האבן או קורה לפי שלא נהנה בנתינה זו שנתן לו שתחת ידו היתה קודם שיתננה לו. אבל רש\\\"י פירש מאי שנא דכי נטלה הוא לא מעל ומאי שנא דכי נתנה לחבירו מעל בגזבר המסורות אותו אבן או קורה עסיקינן דכי נטלו הוא עדיין ברשותו הם וברשות הקדש נינהו כמתחלה אבל כי נתנו לחבירו הרי שיצאו מרשות הקדש לחול עכ\\\"ל. והראב\\\"ד כתב ונתנה לחבירו שניהם מעלו א\\\"א אף בזה עזב כל הדרך הסלולה וכו'. טעמו מפני שהוא מפרש דכי פריך מאי שנא הוא ומאי שנא חבירו היינו לומר שכיון שנטלה הוא מעל אף על פי שלא נתנה לחבירו כמ\\\"ש לקמן בסמוך.\",1,0],[8,367,6,7,\"ומה שכתב רבינו הנוטל פרוטה של הקדש על דעת שהיא שלו וכו' עד בכל עת שירצה. משנה בפרק ה' דמעילה (דף כ'):\",2,0],[8,367,6,7,\"וכתב הראב\\\"ד נטל אבן או קורה א\\\"א זו היא שהעמידו בגמרא בגזבר וכו'. וכבר נתבאר זה בסמוך:\",3,0],[8,367,6,9,\"וכן אם נתנה לאחד מבעלי אומניות וכו' עד ואם מישראל לא מעל. בפ' הזהב (בבא מציעא דף מ״ח). ויש לתמוה דהתם אליבא דר״ל דאמר משיכה קונה מן התורה קיימינן ואנן קיימא לן כר״י דאמר דבר תורה מעות קונות:\",1,0],[8,367,6,11,\"המוציא מעות הקדש בצרכיו וכו' לפיכך המביא מנחות ונסכים וכו'. תוספתא פירקא קמא דמעילה וכחכמים ובגמרא פרק הנהנה (דף י\\\"ט) פלוגתא דר\\\"ש ור\\\"י והלכה כר\\\"י דאמר הכי:\",1,0],[8,367,6,12,\"ומה שכתב נתן שקלו ממעות הקדש כשיתרמו התרומה וכו'. בפרק ב' דשקלים תנן השוקל שקלו מן ההקדש אם נתרמה תרומה ואחר כך קרבה הבהמה מעל.\",1,0],[8,367,6,12,\"ומ\\\"ש שאינו מועל עד שיקנו בהמה ויזרוק דמה. הוא ע\\\"פ מה שנתבאר לעיל בסמוך:\",2,0],[8,367,6,13,\"המפריש שקלו וכו'. תוספתא פ\\\"ק דמעילה. וכתב הראב\\\"ד בין הוא בין חבירו מעל א\\\"א זה מן הטעות הראשון עכ\\\"ל. כלומר דאזדא רבינו לטעמיה שפירש במאי דפריך בגמ' מ\\\"ש הוא ומאי שנא חבירו דהיינו לומר דהל\\\"ל שניהם מעלו. ויש לתמוה על הראב\\\"ד שמאחר שדברי הרמב\\\"ם פה הם דברי התוספתא לא הל\\\"ל שהם טעות אדרבה ה\\\"ל ללמוד מתוספתא זו שפירוש רבינו בההיא פירכא אמת:\",1,0],[8,367,6,13,\"נתנו לחבירו לשוקלו וכו'. משנה בפ\\\"ב דשקלים שם.\",2,0],[8,367,6,13,\"ומה שכתב ולעולם אין מועלין בשיירי הלשכה. בירושלמי פ\\\"ב דשקלים ובגמרא פ\\\"ב דקידושין (דף נ\\\"ד) פלוגתא דרבי יהודה ורבי מאיר והלכה כרבי יהודה דאמר הכי.\",3,0],[8,367,7,1,\"מי ששגג ולקח הקדש או מעות הקדש ונתנו לשליח להוציאו בתורת חולין וכו' עד ואם לא עשו שליחותו בעה\\\"ב פטור. משנה בפ\\\"ב דמעילה (דף כ'):\",1,0],[8,367,7,1,\"אמר לשלוחו תן לאורחים חתיכה חתיכה של בשר וכו'. שם במשנה אמר תן להם חתיכה חתיכה והוא אמר להם טלו שתים שתים והם נטלו ג' ג' כולם מעלו ובגמ' ש״מ מוסיף על שליחותו הוי שליח אמר רב ששת דאמר שליח טלו אחת מדעתו ואחת מדעתי. פירוש ש״מ מוסיף על שליחותו הוי שליח ותפשוט הא דאיבעיא לן בפ' אלמנה ניזונית (כתובות דף צ״ח:) האי מאן דאמר לשלוחיה זיל זבין לי ליתכא דארעא ואזל זבין ליה כורא שהוא פי שנים מי אמרינן מוסיף על דבריו של משלח הוי וליתכא מיהא קנה או דילמא מעביר על דבריו וליתכא נמי לא קנה. ורבינו פסק בפ״א משלוחין דמוסיף על שליחותו הוי וטעמו משום דבפ' אלמנה ניזונית (כתובות דף צ״ט) אמרינן א״ד הא לא תיבעי לך וכו' דודאי מוסיף על דבריו הוי ומשמע דכי אמר ש״מ מוסיף על שליחותו הוי שליח מדקתני דבעה״ב נמי מעל דייק דאת״ל מעביר על דבריו הוי לא מעל בעה״ב ושני רב ששת דמהא לא תפשוט דאפי' את״ל דמוסיף על שליחותו לא הוי שליח שאני הכא דא״ל טלו אחת מדעתו ואחת מדעתי דכיון דא״ל בהדיא אחת מדעתו הרי נעשה שליחותו של בעה״ב בפירוש ומש״ה מעל אבל אם היה אומר סתם טלו שתים אפשר דהו״ל מעביר על דבריו של בעה״ב ולא מעל בעה״ב והכי אמרינן בהדיא בגמ' בפ' אלמנה נזונית. והשתא כיון שרבינו פסק דמוסיף על דבריו הוי כשפסק דבעה״ב חייב בכל גוונא שפיר. אבל מה שפסק ברישא שהשליח פטור קשה דהא אפי' אי הוי מוסיף מעל על מה שהוסיף. וכתב הר״י קורקוס ז״ל שאפשר לומר שדעת רבינו דאוקמתא דרב ששת לאו לדחויי דלא תילף דמוסיף הוי אמר כן אלא כי היכי דלא תיקשי כיון שזה לא עקר השליחות למה מעל דהא תנן עשה שליחותו בעה״ב מעל ולא השליח ומשמע ליה אפילו הוסיף על מה שצוה דלאו דוקא צוה כן אלא שלא יפחות לזה העמידה בשאמר טלו אחד מדעתי וכיון שכן ראוי שימעול גם השליח ובגמ' קבע אותה למידחי דלא תיפשוט דמוסיף הוי כיון דבהכי מיירי מעתה לא דמיא מתני' לבעיין עכ״ל. והאריך עוד בדבר:\",2,0],[8,367,7,2,\"ומ\\\"ש בד\\\"א כשהיו החתיכות מקדשי בדק הבית אבל אם היו בשר עולה וכיוצא בו לא מעל אלא האוכל בלבד וכו': כתב הראב\\\"ד אבל אם היו בשר עולה א\\\"א תוספתא היא במעילה וכו'.\",1,0],[8,367,7,2,\"ומ״ש רבינו ובכל התורה כולה אין שליח לדבר עבירה אלא במעילה. בפ' האיש מקדש (קידושין דף מ״ג:).\",2,0],[8,367,7,2,\"ומ\\\"ש שלא יתערב בה איסור אחר. כבר נתבאר שהוא תוספתא:\",3,0],[8,367,7,3,\"הנותן פרוטת הקדש לשלוחו וכו' עד השליח מעל. משנה בפרק בתרא דמעילה (דף כ\\\"א):\",1,0],[8,367,7,4,\"נתן לו שתי פרוטות וכו'. משנה וגמרא שם:\",1,0],[8,367,7,5,\"השולח פרוטה ביד שלוחו וכו' עד שהרי הוא שוגג. ברייתא שם.\",1,0],[8,367,7,5,\"ומ\\\"ש הודיעו לחנוני וכו' שלשתן פטורין. נלמד ממה שקדם דמזיד פטור.\",2,0],[8,367,7,5,\"ומ\\\"ש ונתפס המקח להקדש:\",3,0],[8,367,7,6,\"ומ\\\"ש וכיצד יעשה כדי להציל החנווני מן החטא וכו'. משנה שם.\",1,0],[8,367,7,6,\"ומ\\\"ש וכן פרוטה שנתערבה בכל הכיס וכו' עד לא מעל עד שיוציא את כל הכיס. ג\\\"ז משנה שם ופסק כחכמים. והטעם שאין מעילה מן הספק לדעת חכמים הילכך לא מעל עד שיוציא האחרונה דאז הוי ודאי. ואם תאמר וליבטיל ברובא יש לומר דדבר שיש לו מתירין הוא א\\\"נ מטבע חשיב ולא בטיל:\",2,0],[8,367,7,7,\"אמר כיס מכיסי הקדש וכו'. תוספתא פ\\\"ק דמעילה וצ\\\"ע שזה סותר מ\\\"ש בפט\\\"ז ממעשה הקרבנות באומר שור משוורי הקדש:\",1,0],[8,367,7,8,\"המועל בפחות משוה פרוטה וכו'. ברייתא פרק הזהב (בבא מציעא דף נ״ה:) ואת אשר חטא מן הקדש ישלם לרבות פחות משוה פרוטה להשבון:\",1,0],[8,367,7,9,\"המפקיד מעות אצל בעה״ב ונשתמש בהם וכו' עד וכאילו השתמש ברשות. משנה בפרק ב' דמעילה (דף כ״א) ומיפרשא בגמרא פרק המפקיד (בבא מציעא דף מ״ג). וחנווני פלוגתא דר״מ ור״י וידוע דהלכה כר״י:\",1,0],[8,367,7,10,\"ועל מה שכתב רבינו הפקידן אצל שולחני או חנווני וכו' שניהם פטורים וכו'. כתב הר\\\"י קורקוס ז\\\"ל בפרק המפקיד תניא המפקיד מעות אצל שולחני אם צרורים לא ישתמש בהם לפיכך אם הוציא לא מעל הגזבר מותרים ישתמש בהם לפיכך אם הוציא מעל הגזבר. ויש לתמוה על רבינו שכתב שניהם פטורים הפך ברייתא זו וליכא מאן דפליג עלה ותירץ שרבינו דחה ברייתא זו מהדין שכתב בפ\\\"ו שאם קנה חפץ ונתן מעות הקדש ולא משך לא מעל והא התם עדיף ממפקיד ומותר הוא להוציאם ואעפ\\\"כ לא מעל עד שימשוך כי אז נהנה בהם או בדבר שאין צריך משיכה וכ\\\"ש בזה שכיון שאין אנו מחייבין אותו עד שיוציא והוציא דוקא לר\\\"נ דהלכתא כותיה שאינו חייב באונסין א\\\"כ אתה בא לחייבו מטעם שליח לא מטעם נתינתו לו בידו וכיון שחידוש הוא שחידשה תורה במעילה אין לך בו אלא חידושו ולכך דוקא בשעשאו שליח בפירוש וא\\\"ל להוציאן אבל שיעשה שליח מאלו לחייבו אין לנו. ומעתה סובר רבינו דמתני' דנתנה לבלן מעל דמוכח דוקא בלן אבל דבר הצריך משיכה לא מעל דהיתר תשמיש לא מייתי לידי מעילה וכן ההיא דנתנה לספר לא מעל כולהו פליגי על אותה ברייתא וסברי שאין מעילה אלא א\\\"כ א\\\"ל בפירוש עכ\\\"ל:\",1,0],[8,367,7,11,\"האשה שהכניסה מעות של הקדש לבעלה וכו'. בעיא דאיפשיטא בפרק השואל (דף צ\\\"ו ע\\\"ב):\",1,0],[8,367,8,1,\"הפועלים שהם עושים בהקדש וכו' הדש כרשיני הקדש הרי זה חוסם את הפרה וכו'. משנה וגמרא בפרק ג' דמעילה (דף י\\\"ג):\",1,0],[8,367,8,3,\"אין מחללין את ההקדש על המלאכה וכו'. הכי משמע במשנה פ\\\"ד דשקלים ומפורש בתוספתא פ\\\"ק דמעילה:\",1,0],[8,367,8,4,\"כשבונים במקדש וכו':\",1,0],[8,367,8,5,\"כשפוסקים עם האומנין וכו'. בפי״ז דכלים ומייתי לה בפרק שתי הלחם (מנחות דף צ״ח) ובפ' על אלו מומין (בכורות דף מ') ובגמרא אמרו חד לכספא ודהבא, ויש לתמוה על רבינו שהשמיטו:\",1,0],[8,367,8,6,\"תנאי ב\\\"ד שיהו הכהנים נאותים במלח ובעצים וכו'. בשקלים פ\\\"ז.\",1,0],[8,367,8,6,\"ומ\\\"ש אבל לא יתנו מלח המקדש בחולין שלהם. בפ' ג' דמנחות (דף כ\\\"א):\",2,0],[8,367,8,7,\"ומ\\\"ש מלח שע\\\"ג האבר מועלים בו שע\\\"ג הכבש ושעל ראש המזבח אין מועלין בו. תוספתא פ\\\"ו דמנחות ואיתא בגמרא פ' הקומץ רבה שם. ופירש\\\"י שע\\\"ג הכבש שנופל שם כשמולחין את הקומץ אין מועלין בו דשוב אינו ראוי:\",1,0],[8,367,8,8,\"ראוי לאדם להתבונן במשפטי התורה הקדושה וכו'. דברי רבינו ודרכיו אמונה והם ראוים אליו:\",1,0],[8,367,8,8,\"סליקו הלכות מעילה בס\\\"ד\",2,0],[8,368,1,1,\"מצות עשה לשחוט הפסח בי\\\"ד לחדש ניסן וכו' עד זכר בן שנה. מבואר בכתוב פרשת בוא אל פרעה.\",1,0],[8,368,1,1,\"ומ\\\"ש ואחד האיש ואחד האשה חייבים במצוה זו. בפסחים פ' האשה (דף צ\\\"א:) פלוגתא דתנאי ולענין פסח ראשון פסק כר' יהודה ור' יוסי לגבי ר\\\"ש ולענין פסח שני פסק בפ\\\"ב כר' יוסי, ומה שיש לדקדק עליו ממ\\\"ש בפ\\\"ה אכתוב שם. ואע\\\"ג דבפ\\\"ק דסנהדרין (דף י\\\"ב:) אמרינן דחזקיה המלך ביקש רחמים על עצמו וסבר בסוף דנשים בראשון רשות משום ר\\\"ש אמרו לה אבל לר' יוסי ור' יהודה דהלכה כוותייהו שביקש חזקיה רחמים על עצמו לא מפני כך היה אלא מפני שעיבר ניסן בניסן:\",2,0],[8,368,1,2,\"מי שביטל מצוה זו בזדון וכו' ה\\\"ז חייב כרת. מפורש בתורה בפרשת בהעלותך ויתבאר בפרק חמישי:\",1,0],[8,368,1,3,\"אין שוחטין את הפסח אלא בעזרה וכו'. הכי משמע במתני' פ' תמיד נשחט (פסחים דף ס״ד).\",1,0],[8,368,1,3,\"ומ\\\"ש אף בשעת היתר הבמות לא היו מקריבים את הפסח בבמת יחיד. במגילה (דף ט':) ואיתא נמי בסוף זבחים (דף קי\\\"ז וקי\\\"ח).\",2,0],[8,368,1,3,\"ומ\\\"ש וכל המקריב את הפסח בבמת יחיד לוקה וכו'. פרק בתרא דזבחים (דף קי\\\"ד:) ר\\\"ש אומר מנין לזובח פסח בשעת איסור הבמות שהוא בל\\\"ת שנאמר לא תוכל לזבוח את הפסח יכול אף בשעת היתר הבמות כן ת\\\"ל באחד שעריך לא אמרתי לך אלא בשעה שכל ישראל נכנסים בשער אחד אימת אילימא אחר חצות כרת נמי מיחייב אלא לאו קודם חצות לעולם לאחר חצות ובשעת היתר הבמות קאי והא בשעת איסור הבמות קאמר איסור במה לו היתר במה לחבירו. ופירש\\\"י איסור במה לו לקרבן זה היתר במה לחבירו לעולה ושלמים וכו'. וסיפא ה\\\"ק יכול אף בשעה שהוא מותר בבמה (כן) כגון קודם חצות שהוא לשלמים ת\\\"ל וכו'. בשער אחד בבמה גדולה לשחוט פסחיהם. וכתב ה\\\"ר אברהם בנו של רבינו בהדיא איפריש בגמרא דאם הקדישן בשעת היתר במות והקריבן בשעת היתר במות פטור מכלום וכל הקדשים אמרינן ל\\\"ש קרבנות הצבור או קרבן יחיד ולולא שכתב בפסח לא תוכל לזבוח לא היה בו בשעת היתר במות אפילו לאו והיינו דאתא ר\\\"ש בברייתא לאשמעינן דפסח בלחוד חייב עליה לאו ולא פליגי רבנן בפסח כלל עכ\\\"ל. ובפסחים פ' האשה (דף צ\\\"א) מייתי האי ברייתא דר\\\"ש ומשמע שם דר' יהודה ור' יוסי ס\\\"ל הכי:\",3,0],[8,368,1,4,\"שחיטת הפסח אחר חצות וכו' ואם שחטו אחר חצות קודם תמיד של בין הערבים כשר וכו' עד ואם נזרק דם הפסח קודם דם התמיד כשר. משנה בפרק תמיד נשחט (פסחים דף ס״א).\",1,0],[8,368,1,4,\"ומ״ש אחר שמקטירים קטרת של בין הערבים ואחר שמטיבין את הנרות. בפרק תמיד נשחט (פסחים דף נ״ט) פלוגתא דברייתות ופסק כברייתא דקתני הכי משום דמשמע התם דמסתבר טעמא:\",2,0],[8,368,1,5,\"השוחט את הפסח בזמנו וכו' עד ה״ז לוקה. משנה בפרק תמיד נשחט (פסחים דף ס״ג).\",1,0],[8,368,1,5,\"ומ\\\"ש והפסח כשר. הכי משמע התם מדקתני ה\\\"ז עובר בלא תעשה ולא קתני ה\\\"ז פסול והכי איתא בתוספתא פ\\\"ג ובירושלמי מפרש דזבח קרייה רחמנא:\",2,0],[8,368,1,6,\"דם הפסח טעון שפיכה כנגד היסוד. בפרק האשה (דף פ״ט) אמרינן דפסח בשפיכה דהיינו בנחת מן המזרק לקיר המזבח דנפקא לן בפרק בית שמאי מתן דם דפסח מודם זבחיך ישפך. ואף על גב דבפרק תמיד נשחט (פסחים דף ס״ד) תנן זורקו זריקה אחת נגד היסוד פסק כרבינו דהוי בשפיכה משום דבסוף פסחים (דף קכ״א) אמרינן דבין ר' ישמעאל ובין ר' עקיבא סברי דדם פסח בשפיכה ובסיפרי פ' קרח אמרינן דר' יאשיהו ור' יצחק סברי דפסח ומעשר בשפיכה:\",1,0],[8,368,1,6,\"ואחר ששופכים דמו וכו'. משנה בפרק תמיד נשחט (פסחים דף ס״ד:):\",2,0],[8,368,1,6,\"ומ\\\"ש ומקטיר אותם חלבים וכל זבח וזבח לבדו. שם. גבי פסח מעוכין והקטירו שלא יערב חלביו של זה בשל זה.\",3,0],[8,368,1,6,\"ומ\\\"ש ובעל הזבח נוטל פסחו עם העור שלו. בסוף פרק תמיד נשחט:\",4,0],[8,368,1,7,\"המניח אימורים ולא הקטירם עד שלנו וכו'. במכילתא פרשת משפטים לא ילין חלב חגי עד (ה) בקר בא הכתוב ללמדך על החלבים שהן נפסלין בלינה:\",1,0],[8,368,1,8,\"ומקטירים חלבי פסחים כל הלילה וכו'. בפ' תמיד נשחט (פסחים דף נ״ט):\",1,0],[8,368,1,9,\"הפסח נשחט בשלש כתות וכו'. משנה בפ' תמיד נשחט (פסחים דף ס״ד):\",1,0],[8,368,1,9,\"ומ\\\"ש ואין פחות מל' בני אדם בכל כת וכת היו הכל נ' נכנסים בתחלה ל' וכו'. שם א\\\"ר יצחק אין הפסח נשחט אלא בשלש כתות של שלשים שלשים בני אדם מ\\\"ט קהל ועדה וישראל מספקא לן אי בבת אחת אי בזה אחר זה הילכך בעינן שלש כתות של שלשים שלשים בני אדם דאי בבת אחת הא איכא ואי בזה אחר זה הא איכא הילכך בחמשין נמי סגי דעייל תלתין [ועבדי עיילי עשרה] ונפקי עשרה ועיילי עשרה ונפקי עשרה:\",2,0],[8,368,1,11,\"ומ\\\"ש ואם שחטו כולן בבת אחת כשר. הכי משמע דר' יצחק לאו לאיפסולי אמר דאם כן הל\\\"ל הכי פסח שנשחט בפחות משלש כתות פסול:\",1,0],[8,368,1,11,\"כיצד נשחט נכנסה הכת הראשונה וכו' עד ומעולם לא שלשו. משנה שם:\",2,0],[8,368,1,12,\"על כל קריאה וקריאה תוקעים שלש תקיעות. שם במשנה נכנסה כת ראשונה וכו' נעלו דלתות העזרה תקעו והריעו ותקעו שחט ישראל וכו'. ואמאי דתנן קראו את ההלל. פירש\\\"י כשמתחילין לשחוט מתחילים לקרות.\",1,0],[8,368,1,12,\"ומה שכתב שהקוראים היו לויים. בתוספתא פ\\\"ד לויים על דוכנן קוראים את ההלל.\",2,0],[8,368,1,12,\"ומ\\\"ש הואיל ואין לו נסכים וכו'. שם בירושלמי:\",3,0],[8,368,1,13,\"הכהנים עומדים שורות שורות ובידיהם מזרקי כסף ומזרקי זהב וכו' עד כנגד היסוד. משנה בפ' תמיד נשחט שם:\",1,0],[8,368,1,15,\"ומ\\\"ש כדי שיתעסקו רבים במצוה. שם בגמ' יהיב טעמא משום ברב עם הדרת מלך.\",1,0],[8,368,1,15,\"ומה שכתב ומקבל מזרק אחד מלא ואח\\\"כ מחזיר את הריקן. שם בגמרא יהיב טעמא משום דאין מעבירין על המצות.\",2,0],[8,368,1,15,\"ומה שכתב ותולין ומפשיטין את כולו נראה שכתב כן לאפוקי מר' ישמעאל בנו של ר\\\"י בן ברוקא דאמר בתוספתא פ\\\"ד י\\\"ד שחל להיות בשבת לא היה מפשיט אלא עד מקום חזה.\",3,0],[8,368,1,15,\"ומ״ש ממחה את קרביו. בר״פ אלו דברים (פסחים דף ס״ה:) תנן דמיחוי קרביו דוחה את השבת ובגמרא (דף ס״ח) מאי מיחוי קרביו רב הונא אמר שמועכן בסכין רב חייא בר רב אמר שירקא דמעייא דנפקא אגב דוחקא דסכינא שירקא דמעייא ליחה האדוקה במעים שיוצאה מהם בדוחק בסכין. ופרש״י דטעמא דמיחוי קרביו דוחה שבת כדי שלא יסריחו.\",4,0],[8,368,1,15,\"ומ\\\"ש ומוציא את האמורים וכו'. שם במשנה קרעו והוציאו את אימוריו ונתנם במגס והקטירם ע\\\"ג המזבח.\",5,0],[8,368,1,15,\"ומ\\\"ש ומולחין. היינו מדכתיב על כל קרבנך תקריב מלח.\",6,0],[8,368,1,15,\"ומ\\\"ש וכיצד תולין ומפשיטין וכו' עד ורוחצין את העזרה בשבת. שם במשנה:\",7,0],[8,368,1,16,\"ומ\\\"ש שאין איסור שבות במקדש אפילו בדבר שאינו צורך עבודה. שם בגמ' (דף ס\\\"ה) אמרינן דר' נתן סבר שבות שאינה צריכה לא התירו ומשמע דחכמים פליגי עליה ופסק כוותייהו. ועוד דהא תנן בפ' תמיד נשחט שהכהנים היו עושים מעשה ומדיחים את העזרה בשבת ואע\\\"ג דמסיים בה דשלא ברצון חכמים היה איכא למימר מאן חכמים ר' נתן וכיון דרבים פליגי עליה לית הלכתא כוותיה:\",1,0],[8,368,1,17,\"אין כל אחד ואחד מוליך את פסחו לביתו בשבת וכו'. משנה שם (דף ס\\\"ה):\",1,0],[8,368,1,18,\"שחיטת הפסח וזריקת דמו. משנה וכר\\\"ע פרק אלו דברים.\",1,0],[8,368,1,18,\"ומ\\\"ש ואם אפשר לחתוך יבלתו בידו בשבת חותך ואם היתה יבשה חותכה אפילו בכלי. שם בגמ' (דף ס\\\"ח:) ובסוף עירובין (דף ק\\\"ג).\",2,0],[8,368,1,18,\"ומ\\\"ש וכן צלייתו והדחת קרביו אינם דוחים. משנה בפ' אלו דברים שם:\",3,0],[8,368,1,19,\"שכח ולא הביא סכין לא יביאנה בשבת אלא נותנה בין קרני הכבש או בצמרו וכו' עד ואינו חושש. שם (דף ס\\\"ו).\",1,0],[8,368,1,19,\"ומה שכתב הואיל וקבוע לו זמן מותר להקדישו בשבת וכו'. פירש רש\\\"י חובות הקבוע להם זמן לבו ביום ש\\\"ד דהואיל ונשחטים היום יכול להקדישן היום:\",2,0],[8,368,1,20,\"השוחט את הפסח ונמצא בעל מום או טריפה וכו'. מתבאר קצת במשנה סוף פרק אלו דברים:\",1,0],[8,368,2,1,\"אין שוחטין את הפסח אלא למנויו וכו'. בפרק תמיד נשחט (פסחים דף ס״א):\",1,0],[8,368,2,2,\"יחיד ששחט את הפסח לעצמו כשר והוא שיהיה ראוי לאכול את כולו וכו'. בפ' האשה (דף צ\\\"א) תנן אין שוחטין את הפסח על היחיד דברי ר' יהודה ר' יוסי מתיר ואפי' חבורה של מאה שאינם יכולים לאכול כזית אין שוחטים עליהם. ובגמ' ת\\\"ר מנין שאין שוחטין את הפסח על היחיד ת\\\"ל לא תוכל לזבוח את הפסח באחד שעריך דברי ר' יהודה ר' יוסי אומר יחיד ויכול לאכלו שוחטים עליו עשרה ואין יכולים לאכלו אין שוחטין עליהם וידוע דהלכה כר' יוסי.\",1,0],[8,368,2,2,\"ומ\\\"ש ומשתדלין שלא ישחט לכתחלה על יחיד וכו'. קשה מאחר שפסק כר' יוסי מאי האי דקאמר שלא ישחט לכתחלה על היחיד דר' יוסי אפי' לכתחלה מתיר. ותירץ ה\\\"ר אברהם בנו של רבינו שלא כתב בפירוש אין שוחטין לכתחלה אלא דרך זירוז שמשתדלין שלא ישחט לכתחלה על יחיד ולא סמך בזה אלא על הכתוב שהביא יעשו אותו והוא הכתוב האמור בפסח ראשון כל עדת ישראל יעשו אותו עכ\\\"ל. ואני אומר דאכתי קושיין לא מיתרצא שאם רבי יוסי מתיר לכתחלה ולא הצריך לזרז ולא דרש הפסוק לכך מנין לו לרבינו לחוש דבר שלא אמרו ר' יוסי. אבל התירוץ הנכון הוא שדברי רבינו מבוארים בפ' מי שהיה (דף צ\\\"ה) דקאמר ורבנן האי יעשו אותו מאי עבדי ליה מיבעי ליה שאין שוחטין את הפסח על היחיד דכמה דאפשר לאהדורי מהדרינן. ומשמע לרבינו דכר' יוסי אתיא דאילו לר' יהודה מאי כמה דאפשר לאהדורי מהדרינן הא אמר דאין שוחטין על היחיד כלל:\",2,0],[8,368,2,3,\"אין שוחטין את הפסח אלא על מי שראוי לאכול וכו' אפילו חבורה של מאה וכו'. משנה כתבתיה בסמוך אפי' חבורה של מאה שאינם יכולים לאכול כזית אין שוחטין עליהם. ומפרש רבינו דבעינן שלא יהא בהם אפילו אחד שאינו יכול כזית אף על פי שרש\\\"י לא פירש כן:\",1,0],[8,368,2,4,\"אין עושין חבורה נשים ועבדים וכו'. משנה וגמרא שם.\",1,0],[8,368,2,4,\"ומ\\\"ש אבל עושים חבורה כולה נשים אפי' בפסח שני. שם פלוגתא דתנאי בברייתא ופסק כר' יוסי.\",2,0],[8,368,2,4,\"ומ\\\"ש או כולם עבדים. היינו מדקי\\\"ל שעבד שוה לאשה במצות.\",3,0],[8,368,2,4,\"ומ״ש ושוחטין על הקטנים שיהיו מכלל בני החבורה וכו'. בס״פ לולב הגזול (סוכה דף מ״ב) קטן שיכול לאכול כזית צלי שוחטים עליו את הפסח שנאמר איש לפי אכלו. ופירש״י שוחטים עליו את הפסח ממנין אותו על בני החבורה ואי לא לא דכתיב איש לפי אכלו תכוסו הראוי לאכילה.\",4,0],[8,368,2,4,\"ומ\\\"ש רבינו שאינן בני דעת. ק\\\"ל דטפי הוה עדיף למעוטי מדכתיב בפסח איש. ולטעם שנתן רבינו קשה מהי תיתי לן דבעינן בשחיטת פסח שיהא בן דעת. וי\\\"ל דמאיש לא משמע ליה למעוטי קטן דא\\\"כ הוה ממעט אף מלהמנות עם בני החבורה ומדתניא שוחטים עליו את הפסח משמע דס\\\"ל לגמרא דהאי איש לאו למעוטי קטן אתא. ומ\\\"ש שאינם בני דעת. אפשר דטעמא משום דמי שאין בו דעת אין הקדשו הקדש. ואפשר לומר דה\\\"ק דוקא בשאינם בני דעת כלומר דוקא בשלא הגיעו לעונת הנדרים אבל אם הם בני דעת כלומר שהגיעו לעונת הנדרים שהקדשן הקדש ש\\\"ד.\",5,0],[8,368,2,4,\"ומ\\\"ש ואין עושין חבורה כולה חולים או זקנים או אוננים אע\\\"פ שהם יכולים לאכול וכו'. שם במשנה ועל כולם אין שוחטין עליהם בפני עצמם כדי שלא יביאו את הפסח לידי פיסול:\",6,0],[8,368,2,4,\"וכן אין עושים חבורה כולה גרים וכו'. מימרא בגמרא שם, ופירש\\\"י ידקדקו משום שאינם בני תורה יחמירו עליו לדקדק ויפסלוהו על חנם:\",7,0],[8,368,2,5,\"שחטו שלא למנוייו וכו' עד כאילו לא חישב עליהם. משנה בפרק תמיד נשחט (פסחים דף ס״א):\",1,0],[8,368,2,6,\"ומ\\\"ש שחטו למולים וזרק הדם לשם מולים וערלים פסול וכו'. שם אפלוגתא דרבה ורב חסדא אמר רבה מנא אמינא לה דתניא יכול יפסל בני חבורה הבאים עמו וכו' ורב חסדא אדרבה לאידך גיסא ת\\\"ל וכל ערל כולה ערלה פסלה מקצתה לא פסלה אבל זריקה אפי' מקצתה נמי פסלה וכ\\\"ת מאי וכו' חומריה דזריקה דלא מיקבע פיגול אלא בזריקה. ומאחר שרבינו פסק בסמוך כרב חסדא ממילא משמע דנקטינן דמקצת זריקה פסלה וא\\\"כ שחט למולין וזרק לשם מולין וערלים פסול:\",1,0],[8,368,2,6,\"והראב\\\"ד כתב א\\\"א הא דלא כהלכתא וכו'. וטעמו משום דאיתא בגמרא עלה דההיא מתקיף לה רב אשי ממאי דהאי וכל ערל כולה משמע דילמא וכו' משמע כל דהוא ערלה כתב רחמנא זאת דעד דאיכא כולה ערלה לא פסלה ל\\\"ש בשחיטה ל\\\"ש בזריקה אלא אמר רב אשי רב חסדא ורבא בהאי קרא קא מיפלגי ונרצה לו לכפר עליו וכו' ומשמע להראב\\\"ד דלקושטא קאמר הכי רב אשי. ויש לתמוה דהא לא אמר הכי אלא בדרך דילמא והיאך כתב דרב אשי קא פסיק מקצת ערלה לא פסלה, ורבינו משמע ליה דלא שבקינן מאי דפשיטא ליה לסתם גמרא אליבא דרב חסדא משום מאי דמספקא לרב אשי ועוד דלמאי דאוקים רב אשי פלוגתייהו אקשינן דרב חסדא אדרב חסדא ושני בדוחק הילכך אוקמתא קמייתא עדיפא.\",2,0],[8,368,2,6,\"ומה שכתב שחטו למולים שיתכפרו בו ערלים פסול. שם פלוגתא (דרבא) [דרבה] ורב חסדא ופסק כרב חסדא.\",3,0],[8,368,2,6,\"ומה שכתב שחטו לאוכליו לזרוק דמו שלא לאוכליו הפסח כשר וכו'. ברייתא בפרק כיצד צולין (פסחים דף ע״ח:). מצאתי כתוב וה״ה אם זרק דמו שלא לאוכליו כשר דאין דין מחשבת אוכלין אלא בשחיטה בלבד ריש פירקא קמא דזבחים קאמר מה לשחיטה שכן נפסלת שלא לשם אוכלין בפסח:\",4,0],[8,368,2,7,\"מי שהוא בריא בשעת שחיטה וחולה בשעת זריקה וכו'. שם:\",1,0],[8,368,2,10,\"שוחט אדם ע\\\"י בנו ובתו הקטנים וכו' עד ואינם יוצאים אלא בשל עצמן. ברייתא וגמ' בפ האשה (דף פ\\\"ח):\",1,0],[8,368,2,11,\"האשה שהיא בבית בעל וכו' עד בשע שחיטה. משנה ר\\\"פ האשה (ד פ\\\"ז) בזמן שהיא בבית בעלה שח עליה בעלה ושחט עליה אבי תאכל משל בעלה הלכה רג הראשון לעשות בבית אביה שח עליה אביה ושחט עליה בעל תאכל במקום שהיא רוצה ובגמר ורמינהי אשה רגל הראשון אוכל משל אביה מכאן ואילך רוצ אוכלת משל אביה רוצה מש בעלה ל\\\"ק כאן בשרדופה ליל כאן בשאינה רדופה ומשמע דה\\\" ברייתא ברדופה ולפיכך רג הראשון משל אביה מכאן ואיל ממקום שתרצה ומתני' בשאינ רדופה הילכך רגל ראשון ממקו שתרצה מכאן ואילך משל בעל וכן פירש\\\"י. והשתא איכא למתמ על רבינו שכתב היתה נחפז דהיינו רדופה דברייתא והשמי דין אינה רדופה דמתניתין דרג הראשון תאכל ממקום שתרצה ונ\\\"ל שסובר שרוב הבנות ד רדופות ללכת לבית אביהן ברג הראשון וזהו שכתבו כדרך הבנו ומשום דאינה רדופה לא שכיח לא חש רבינו לכתבו. ועוד אפש שסמך על דאיכא למילפה מד רדופה דכיון דרדופה רגל הראש משל אביה ממילא משמע דשאינ רדופה רגל הראשון ממקו שתרצה וכיון דברדופה שא רגלים ממקום שתרצה ממיל משמע דבשאינה רדופה מש בעלה:\",1,0],[8,368,2,11,\"וכן יתום ששחטו על אפוטרופוסים וכו'. שם\",2,0],[8,368,2,11,\"במשנה ומ\\\"ש בד\\\"א ביתום קטן אבל גדו נעשה כממנה עצמו על שני פסחים וכו' עד אינו אוכל אלא מן הנשחט ראשון. בירושלמי פרק האשה:\",3,0],[8,368,2,12,\"עבד של שני שותפים וכו'. בפ' האשה שם תנן עבד של שני שותפין לא יאכל משל שניהם ורמינן עלה מדתניא רצה מזה אוכל רצה מזה אוכל ושני במתני' בדקפדי אהדדי ברייתא דלא קפדי אהדדי. ופירש רש\\\"י דקפדי אהדדי שני הבעלים ואינם רוצים לההנות זה מזה. ורבינו מפרש דקפדי זה על זה שלא יגנבנו כלומר וחושש זה שאם יאכל אצל חבירו ימשיך לב העבד אליו ויגנבנו:\",1,0],[8,368,2,13,\"מי שחציו עבד וחציו בן חורין וכו'. שם (דף פ\\\"ז) תנן מי שחציו עבד וחציו בן חורין לא יאכל משל רבו ובגמ' (דף פ\\\"ח) משל רבו הוא דלא יאכל אבל משל עצמו יאכל והא תניא לא יאכל לא משלו ולא משל רבו ל\\\"ק כאן כמשנה ראשונה כאן כמשנה אחרונה דתנן מי שחציו עבד וחציו בן חורין עובד את רבו יום אחד ואת עצמו יום אחד דברי ב\\\"ה בש\\\"א וכו' כופין את רבו ועושה אותו בן חורין חזרו ב\\\"ה להורות כדברי ב\\\"ש. ופרש\\\"י כמשנה ראשונה קודם שחזרו ב\\\"ה לא יאכל משל עצמו מפני שאין חלק עבדות נמשך אחר דעתו. במשנה אחרונה הואיל ובידנו לשחררו הרי הוא כבן חורין ואוכל משל עצמו. ולפי זה יש לתמוה על רבינו שפסק כמשנה ראשונה וכבר השיגו הראב\\\"ד. ואפשר לומר שרבינו מפרש דלמשנה ראשונה יאכל משל עצמו שמאחר שצד חירות ניכר לעצמו שהרי עובד את עצמו יום אחד צד עבדות נגרר אחריו ואוכל משל עצמו אבל למשנה אחרונה שלא עשו לו תקנה לעבוד את עצמו יום אחד אין צד חירות ניכר הלכך אין צד עבדות נמשך אחריו וכיון שכן לא יאכל לא משל רבו ולא משל עצמו. ורבינו כתב בפיהמ\\\"ש כלשון הזה ואמרו לא יאכל משל רבו וכמו כן לא יאכל משל עצמו לפי כי עוד יתבאר לך כי הוא לא יניח עבד חציו בן חורין וחציו עבד ולפיכך לא יאכל ממנו בשום פנים עד שיעשה בן חורין. ומ\\\"ש בכאן לא יאכל משל רבו שיראה ממנו שהוא אוכל זהו דעת האומר מניחין עבד חציו בן חורין עכ\\\"ל. ואין דבריו מובנים לי דמה טעם לומר שמפני שאין מניחין עבד חציו בן חורין שאם אירע שהניחוהו שלא יאכל כלל כיון שמן הדין אוכל הוא ואין לומר דה\\\"ק כיון שאין מניחין אותו נמצא שמי שחציו עבד וחציו בן חורין אינו אוכל כלל לפי שאינו נמצא ומי שאינו נמצא אינו אוכל כלל דא\\\"כ למה לו לכתוב זה בחיבור דנראה דיש נפקותא בזה לענין אכילת פסח דלא יאכל כלל אם היה נמצא וזה אינו שאם היה נמצא למה יגרע מלאכול משל עצמו. ואפשר לומר דה\\\"ק דלמשנה ראשונה שתקנו שיעבוד את עצמו יום אחד תקנו ג\\\"כ שיאכל משל עצמו אע\\\"ג דמדינא אינו אוכל לא משלו ולא משל עצמו ולמשנה אחרונה ביטלו כל מה שתיקנו הילכך לא יאכל כלל. אחר שכתבתי זה מצאתי כתוב שנשאל ה\\\"ר אברהם בנו על זה שנראה שרבינו פה פוסק כמשנה ראשונה והשיב לדברי המשנה ראשונה עבדינן ליה תקנה להוציאו מחיובו ומפני זה אוכל משל עצמו ולדברי משנה אחרונה אע\\\"פ שזו היא תקנתו להוציאו י\\\"ח לא עבדינן ליה תקנה שמא יהיה זה גורם לעיכוב שחרורו אלא אומרים לרבו זה אינו אוכל משלך דלא קרינן ביה עבד איש ולא משל עצמו שאינה תקנה גמורה אלא מהר ושחררו כדי שלא ימנע מן המצוה ולפיכך נתן טעם עד שיעשה בן חורין אבל למשנה ראשונה דליכא חיוב לשחררו עבדינן ליה תקנה במצות שהוא חייב בהן מספק מד\\\"ס דאילו מן התורה פטור כדדייק רבינו ממתני' בפ\\\"ק דחגיגה (דף ד') והא דקאמר התם הכל חייבים בראיה לאיתויי מי שחציו עבד וחציו בן חורין דחויה היא מקמי הא דרבינא עכ\\\"ל. וע\\\"פ זה יתבארו דברי רבינו שבפירוש המשנה:\",1,0],[8,368,2,14,\"עד כמה נמנין על הפסח וכו' עד שהרי נשחט עליו. משנה בפרק האשה (דף פ\\\"ט):\",1,0],[8,368,2,14,\"נמנו עליו וחזרו אחרים ונמנו עליו וכו'. בפרק כיצד צולין (פסחים דף ע״ח:):\",2,0],[8,368,2,15,\"הממנה אחרים עמו על חלקו וכו'. משנה בפרק האשה (דף פ\\\"ט:).\",1,0],[8,368,2,15,\"ומ\\\"ש וכן בני חבורה שהיה אחד מהן גרגרן וכו'. ברייתא שם:\",2,0],[8,368,3,1,\"האומר לעבדו צא ושחוט עלי את הפסח וכו'. משנה וגמ' בפ' האשה (דף פ\\\"ח:).\",1,0],[8,368,3,1,\"ומ\\\"ש הלך ושחט גדי וטלה וכו'. שם במשנה שחט גדי וטלה יאכל מן הראשון ובגמרא והתניא אין נמנין על שני פסחים כאחד מתני' במלך ומלכה והתניא וכו' מעשה במלך ומלכה וכו' אמר ר\\\"ג מלך ומלכה דדעתן קלה עליהם יאכלו מן הראשון אנו לא נאכל לא מן הראשון ולא מן השני. ופירש\\\"י אין נמנין על שני פסחים כאחד לאכול בשעת אכילה מאחד מהם שירצה דאין ברירה וכי בעי למיכל מהאי דילמא בשעת שחיטה לא הוה דעתיה עילויה הילכך לא אכיל וזה שהמנה את רבו על שני פסחים ורבו סמך עליו היאך יאכל מן הראשון. במלך ומלכה שתלויים על עבדיהם ואין מקפידים על סעודתם אם גדיים אם טלאים הילכך אין כאן דין ברירה דתרוייהו ניחא ליה לפיכך יאכל מן הראשון דכיון דליכא קפידא יצא בראשון י\\\"ח ואידך בכדי נשחט וכו' שדעתן קלה כדאמרן שאין מקפידים אם גדי אם טלה. ורבינו נראה שמפרש טעמא דמלך ומלכה משום שלום מלכות והיינו שדעתו קלה עליהם ומשמע לי דהיינו לומר שאם נאמר למלך שלא יאכל כלל יכעוס על עבדו ויהרגהו או שמא יכעוס על החכמים שאמרו דלא יאכל כלל משום דאין ברירה שיעלה על דעתו של מלך דיש ברירה מן הדין אלא שלהקניטו אמרו כן. ודברי רבינו בפירוש המשנה אינם מובנים לי:\",2,0],[8,368,3,2,\"האומר לשלוחו צא ושחוט עלי את הפסח וכו'. משנה וגמרא בפ' האשה (דף פ\\\"ח).\",1,0],[8,368,3,2,\"ומ\\\"ש ואם שכח השולח קודם שיזרק הדם חייבים לעשות פסח שני שכח אחר שנזרק הדם פטור מלעשות פסח שני. שם במשנה שכח רבו מה אמר לו שניהם יצאו לבית השריפה ופטורים מלעשות פסח שני ובגמ' אמר אביי ל\\\"ש אלא ששכח אחר זריקה דבעידנא דאיזדרק דם הוי חזי לאכילה אבל שכח לפני זריקה וכו' חייבים לעשות פסח שני ואף על גב דאמרינן התם איכא דמתני לה אברייתא דחמשה שנתערבו עורות פסחיהם וכו' ומאן דמתני לה אברייתא אבל אמתניתין לא וכו' פסק רבינו כלישנא קמא שהוא לישנא דסתם גמרא ולא כלישנא דאיכא דמתני ועוד דמאן דמתני אמתניתין עדיף משום דכל שכן אברייתא.\",2,0],[8,368,3,2,\"ומה שכתב וכן הדין באומר לעבדו צא ושחוט עלי וקבע לו וכו'. המשנה שנויה שם באומר לעבדו ושינה רבינו וכתבה באומר לשלוחו משום דבזה אין צריך להוסיף על השנוי במשנה ואח\\\"כ כתב הדין דאומר לעבדו כמו שהוא שנוי במשנה וכתב עליה מאי דאתמר עלה בגמרא שלי מה שקנה עבד קנה רבו אמר אביי הולך אצל רועה שרגיל רבו אצלו דניחא ליה בתקנתא דרביה ומקני לה חד מינייהו על מנת שאין לרבו רשות בו. ואע\\\"פ שרבינו בפ\\\"ג מהל' זכייה כתב דלא מהני האי לישנא לשלא יקנה רבו כתב לישנא דגמ' וסמך על מ\\\"ש בפרק הנזכר:\",3,0],[8,368,3,3,\"בני חבורה שאמרו לאחד וכו'. דברים פשוטים הם נלמדים ממה שיתבאר לקמן בסמוך:\",1,0],[8,368,3,6,\"חבורה שאבד פסחה וכו' עד אינם אחראים זה לזה. משנה בפ' מי שהיה טמא (פסחים דף צ״ח:) ופירש״י אם שלו נשחט ראשון הואיל והם אמרו לו שחוט עלינו על שלו הם נמנים ושוב אין יכולים להמנות על שלהן ושלהם ישרף דפסח בלא בעלים הוא ואוכלים כולם משלו. ואם שלהם נשחט ראשון הוא אוכל משלו שהרי לא נמנה על שלהם והם אוכלים משלהם שהרי חזרו בהם מן האבוד ומשכו ידיהם ממנו. והם אינם אוכלים עמו שמא שלהם נשחט ראשון ונמשכו מזה. ושלהם יצא לבית השריפה שמא שלו נשחט ראשון ואין נמנין על השני. ופטורים מפסח שני דממ״נ בראשון נמנו ואכילה לא מעכבא. אמר להם אם איחרתי שחטו עלי. יחיד שהלך לבקשו ואמר לבני חבורה אם איחרתי שחטו עלי והמנוני עמכם והם לא אמרו שחוט עלינו. הוא אוכל עמהם ושלו ישרף דכיון שהמנוהו על שלהם הרי נמשך מן הראשון וחוזר בו משליחותו. ושלו יצא לבית השריפה שמא שלהן נשחט ראשון ונמשך משלו שהרי עשאן שלוחים. ופטור מפסח שני ממ״נ בראשון יצא. אמר להם שחטו עלי אם איחרתי ואמרו לו בקש ושחוט עלינו יאכלו כלם מן הראשון דהם שלוחיו והוא שלוחם. ואם אינו ידוע אי זה נשחט ראשון ישרפו שניהם ופטורין מפסח שני. אינם אחראין זה לזה אין אחריות וטענה זה על זה ואין חוששין איזה נשחט ראשון אלא הם אוכלים משלהם והוא אוכל משלו עכ״ל:\",1,0],[8,368,3,6,\"ולפי זה מ\\\"ש רבינו אמר להם זה ששלחוהו לבקש פסח שאבד ולשחטו לאו למימרא שאמרו לו ושחוט עלינו דא\\\"כ היינו בבא דאמר להם ואמרו לו ולמה נשתנה דין זה וזהו שמפני כך הוכרח רש\\\"י לפרש והם לא אמרו לו שחוט עלינו. אלא ע\\\"כ לומר דולשחטו ה\\\"פ שנשחטהו אנחנו לא שישחטהו הוא עליהם, ודייקא לישנא דרבינו שלא כתב ולשחטו עליהם:\",2,0],[8,368,3,6,\"ומ\\\"ש אע\\\"פ שהיה בלבם וכו' או שהיו שם רמיזות ודברים. נ\\\"ל שלמד כן רבינו מייתורא דמתניתין דאל\\\"כ מאי קמ\\\"ל פשיטא:\",3,0],[8,368,3,8,\"שתי חבורות שנתערבו פסחיהם וכו' עד ונמצא שלא הפסידו כלום. גם זה משנה שם:\",1,0],[8,368,3,9,\"חמשה שנתערבו עורות פסחיהם וכו' עד סוף הפרק. ברייתא וגמרא בפ' האשה (דף פ\\\"ח פ\\\"ט):\",1,0],[8,368,4,1,\"כבר נתבאר בהל' פסולי המוקדשין. פט\\\"ו:\",1,0],[8,368,4,1,\"השוחט את הפסח על בני חבורה וכו'. בתוספתא פרק רביעי השוחט את הפסח על בני חבורה ואמר שלא לשמו שחטתיו שורת הדין אינו נאמן ע\\\"כ. ומשמע לרבינו דהיינו דוקא בסתם בני אדם אבל אם הוא מוחזק להם לנאמן סומכים עליו וכדאמרינן בקדושין פ' האומר גבי א\\\"ל ע\\\"א זינתה אשתך. ומדקתני שורת הדין אינו נאמן דייק רבינו שאם רצה שלא להעמיד עצמו על הדין ה\\\"ז משובח:\",2,0],[8,368,4,1,\"כתב הראב\\\"ד ה\\\"ז משובח ויביא פסח שני א\\\"א אין כאן שבח וכו'. ובאמת דבר תימה הוא שהרי גם רבינו כתב כן בסוף פ\\\"ג. ואפשר לומר דמאי יביא פסח שני דקאמר הכא שימנה עם אחרים על פסח שני:\",3,0],[8,368,4,2,\"בשר הפסח שנטמא וכו'. משנה פרק כיצד צולין (פסחים דף ע״ח:) נטמא הבשר והחלב קיים אינו זורק (את) הדם.\",1,0],[8,368,4,2,\"ומה שכתב ואם זרק לא הורצה. שם פלוגתא דחכמים ורבי נתן ופסק כחכמים ואע\\\"ג דרב אמר דמתניתין כרבי נתן לא חש לה רבינו כיון דרבים פליגי עליה ועוד דאמרינן ומאי דוחקיה דרב לאוקמה כרבי נתן ועוד דמאי דאמרינן דדחקיה דא\\\"כ ליתני פסול אינו הכרע דאיכא למימר דאגב סיפא נקט רישא ואף על גב דבתר הכי אמרינן דרב אמר דמתניתין כרבי יהושע כיון דחכמים פליגי עליה כוותייהו נקטינן:\",2,0],[8,368,4,2,\"ומה שכתב ואם לא נודע לו עד שנזרק הדם הורצה וכו'. שם (דף פ':) כרבינא דאמר טומאתו בין שוגג בין מזיד הורצה זריקתו בשוגג הורצה במזיד לא הורצה:\",3,0],[8,368,4,2,\"נטמאו מקצת האברים וכו'. תוספתא פרק ששי נטמאו חלבים והבשר קיים אם יש כזית לכל אחד ואחד יזרוק ואם לאו לא יזרוק. ומשמע לרבינו דבנטמא קצת הבשר עסקינן מדקתני אם יש כזית לכל אחד ואחד ודוחק:\",4,0],[8,368,4,2,\"נטמאו האימורים והבשר קיים וכו'. משנה שם (דף ע\\\"ח:) נטמא החלב והבשר קיים זורק את הדם:\",5,0],[8,368,4,2,\"נטמאו הבעלים אחר שנשחט וכו'. משנה שם נטמא (טומאת) הגוף אין הציץ מרצה וכו' שהציץ אינו מרצה על טומאת הגוף נטמא טומאת התהום הציץ מרצה.\",6,0],[8,368,4,2,\"ומה שכתב כמו שביארנו בהלכות ביאת המקדש. הוא בפרק [רביעי]:\",7,0],[8,368,4,3,\"הפסח שיצא מירושלים וכו'. משנה פ' כיצד צולין (פסחים דף פ״ב) הפסח שיצא או שנטמא ישרף מיד נטמאו הבעלים או שמתו תעובר צורתו וישרף בט״ז.\",1,0],[8,368,4,3,\"ומ\\\"ש אפי' אם נטמאו או מתו קודם זריקת הדם וכו'. שם בגמ'.\",2,0],[8,368,4,3,\"ומ\\\"ש זה הכלל וכו'. ברייתא שם. ומה\",3,0],[8,368,4,3,\"שהשוה משכו ידיהם לנטמאו או מתו. בסוף פרק אלו דברים (פסחים דף ע״ג:).\",4,0],[8,368,4,3,\"ומה שכתב לפיכך אם שחטו אחר שנודע שמשכו הבעלים את ידם וכו'. זה פשוט שהרי פיסולו בגופו הוא:\",5,0],[8,368,4,3,\"במה דברים אמורים שישרף אם נטמאו הבעלים וכו' אבל אם התחילו כלם ונטמאו מקצתם וכו'. ירושלמי סוף פרק כיצד צולין התחילו אלו ונטמאו אלו זכו טהורים בחלקם של טמאים ולא עוד אלא אפילו התחילו ונטמאו הם זכו טהורים בחלקן של טמאים אבל אם התחילו אלו (ואלו) ונטמא אחד מהם לא זכו טהורים בחלקן (של טמאין):\",6,0],[8,368,4,3,\"נטמא שלם או רובו וכו'. משנה פרק כיצד צולין (פסחים דף פ״א:).\",7,0],[8,368,4,3,\"ומה שכתב כדי שלא יחשדו אותם וכו' לפיכך אם ישרפוהו בקש או בקנים וכו'. שם (דף פ\\\"ב) פלוגתא דאמוראי ופסק כרבא דאמר מפני החשד. ופירש רש\\\"י שלאחר שריפתם מחזירים מותר העצים לתוך ביתן והרואה חושדן בגונבי עצי המערכה ונהנים מהם. ודע דבגמרא רמי אמתני' ברייתא דקתני דנטמא מיעוטו נמי שורפין אותו לפני הבירה מעצי המערכה ומשני דההיא באכסנאי משום דאין לו עצים וצריך טעם למה השמיטו רבינו.\",8,0],[8,368,4,3,\"ומה שכתב נטמא מיעוטו וכן הנותר שורפין אותו בחצרותיהן מעצי עצמן וכו'. גם זה שם במשנה:\",9,0],[8,368,4,4,\"המפריש נקבה לפסחו או זכר בן שתי שנים וכו'. בפרק מי שהיה טמא (פסחים דף צ״ז:) תנן המפריש נקבה לפסחו או זכר בן שתי שנים ירעה עד שיסתאב [וימכר] ויפלו דמיו לנדבה ובגמ' שמע מינה בעלי חיים נדחים ודחוי מעיקרא הוי דיחוי. ומאחר שנתבאר בפרק ג' מהלכות פסולי המוקדשין ופרק ט״ו ממעשה הקרבנות שרבינו פוסק כמאן דאמר אין בעלי חיים נדחים ממילא משמע שיביא בדמיו פסח.\",1,0],[8,368,4,4,\"ומ\\\"ש ואם לא נפל בו מום וכו' יביא בדמיו שלמים. הוא מדאמרינן בפרק (שני דשקלים) שמותר פסח יקרב שלמים:\",2,0],[8,368,4,5,\"הפריש פסחו ומת וכו'. משנה שם (דף צ\\\"ח).\",1,0],[8,368,4,5,\"ומ\\\"ש ואם היה ממונה עם אביו עליו וכו'. ברייתא שם.\",2,0],[8,368,4,5,\"ומ\\\"ש בד\\\"א כשמת אביו אחר חצות י\\\"ד וכו'. שם בגמרא וכאוקימתא דרב אשי:\",3,0],[8,368,4,6,\"מי שאבד פסחו ומצאו וכו'. משנה שם (דף צ\\\"ו) הפסח שנמצא קודם שחיטת הפסח ירעה עד שיסתאב וימכר ויביא בדמיו שלמים וכן תמורתו אחר שחיטת הפסח יקרב שלמים וכן תמורתו. ופירש\\\"י הפסח שאבד והפריש אחר תחתיו ונמצא הראשון קודם שחיטת השני דהיה עומד לפנינו בשעת שחיטה הרי קבעתו שעת שחיטה בשם פסח וזה שלא הקריבו דחהו בידים לא יקרב עוד הוא עצמו שלמים דאין זה מותר הפסח וכו'. וכן תמורתו אם המיר הוא בו בהמת חולין אח\\\"כ הרי הוא כמוהו אין קרב הוא עצמו שלמים אלא דמיו ואם לאחר שחיטת השני נמצא הרי לא קבעתו שעת שחיטה בשם פסח ולא נדחה בידים ויביא שלמים ויקרב הוא עצמו שלמים. ובגמ' רבה אמר קודם שחיטה ולאחר שחיטה שנינו ר' זירא אמר קודם חצות ולאחר חצות שנינו וכו' כתנאי הפסח שנמצא קודם שחיטה ירעה לאחר שחיטה יקרב ר\\\"א אומר קודם חצות ירעה לאחר חצות יקרב משמע דהלכה כרבה דקאי כת\\\"ק דפליג אר\\\"א ועוד דלקמן בגמ' אמרינן דר\\\"י כרבה ס\\\"ל ואיתא תו בגמ' אמר רבא ל\\\"ש אלא שנמצא אחר שחיטה והמיר בו אחר שחיטה אבל נמצא קודם שחיטה והמיר בו אחר שחיטה תמורתו מכח קדושה דחויה אתיא ולא קרבה. ופירש\\\"י ל\\\"ש דתמורה קריבה אלא שנמצא אחר שחיטה שאפי' הפסח לא נדחה אבל נמצא קודם שחיטה שהוא עצמו נדחה אע\\\"פ שתמורתו לא נדחית בידים אינה קריבה שהרי מכח קדושה דחויה באה: והשתא מ\\\"ש\",1,0],[8,368,4,6,\"רבינו יקריב איזה מהם שירצה לשם פסח הכי משמע מפירוש רש\\\"י במתני' והכי איכא למגמר מדתנן בפ\\\"ד דתמורה (דף כ\\\"ג) המפריש חטאתו ואבדה והפריש אחרת תחתיה והרי שתיהן עומדות אחת מהן תקרב והשנייה תמות אלמא איזו מהם שירצה יקריב וה\\\"ה לפסח.\",2,0],[8,368,4,6,\"ומ\\\"ש והשני יקרב שלמים. יש לתמוה עליו שלא הל\\\"ל אלא והשני ירעה עד שיפול בו מום ויביא בדמיו שלמים כמו ששנינו במשנה שכתבתי בסמוך. וכבר השיגו הראב\\\"ד וכתב א\\\"א זה שיבוש אלא ירעה עד שיסתאב ויביא בדמיו שלמים עכ ל. ואפשר לדחוק ולומר דאה נ דסבר רבינו שירעה וכו וקיצר בלשונו משום דלא נתכוין אלא ללמד שהשני לא יקרב לשם פסח. ואפשר לומר דרבינו סבר דמתני' דקתני השני ירעה אתיא כמ\\\"ד ב\\\"ח נדחים ומאחר דאיהו ז\\\"ל סבר דאין בעלי חיים נדחים כמו שנתבאר בפ\\\"ג מהלכות פסולי המוקדשין ובפט\\\"ו מקרבנות ממילא משמע שהשני הוא עצמו יקרב שלמים. וא\\\"ת היאך פסק רבינו דנמצא קודם שחיטתו שתמורתו אינה קריבה אלא תרעה והא אין ב\\\"ח נדחים. וי\\\"ל דלא מטעם ב\\\"ח נדחים פסק רבינו כן אלא מפני שזה השני היה ראוי להקריבו פסח וראוי להקריבו שלמים וכיון שלא היתה בו קדושה אחת בלבד קבועה אין בו כח להתפיס תמורתו להקרב וזהו פירוש מכח קדושה דחויה אתיא לדעת רבינו:\",3,0],[8,368,4,6,\"כתב הר״י קורקוס ז״ל יש כאן מקום עיון במה שכתב רבינו שיקריב איזה שירצה והוא דעת רבנן פ' שני שעירי (יומא דף ס״ד) ורבי יוסי פליג וסבר יקריב הראשון והקשו שם לרב דאמר שאם מת אחד מהזוג של שני שעירים שהדין הוא שיקח זוג אחר ודעת רב שם שהראשון יקרב והשני ירעה נהי דאין ב״ח נדחין יקריב אי זה שירצה ותירצו דרב סבר כר' יוסי דאמר גבי פסח שהראשון יקריב ורבינו כתב והשני מן השנים שהגריל בסוף ירעה והוא דעת רב שהעמידו כרבי יוסי וכאן פסק כרבנן שאי זה שירצה יקריב וא״כ קשיא דידיה אדידיה. ונראה שדעת רבינו שאע״פ שאמרו שם דרב כר' יוסי לאו למימרא דסבר כוותיה גבי פסח אלא ה״ק כי היכי דרבי יוסי סבר גבי פסח מצוה בראשון מפני שהופרש לשם פסח תחלה כן סובר רב כאן ומיהו אפשר שאפילו רבנן מודו שכיון שלא בא דיחוי אלא מצד חבירו אין לדחותו ומתחלה מ״ד יביא הזוג לא לדחות הראשון שלא נדחה מצדו (אלא יפריש אחר תחתיו) ואינו מביא שנים אלא לקיים מצות הגרלה אבל גבי פסח כיון שאבד והפריש אחר במקומו כשנמצא די לנו שנאמר שנראה ויקריב אי זה שירצה שלא נצריך אותו להקריב השני דוקא וכמו שנראה מדברי רבי עקיבא שאמר הפסח שאבד ונמצא ירעה וכו' וכן מצאתי בירושלמי סוף פרק מי שהיה הפריש פסחו ואבד וכו' אית תנויי תני מצוה להקריב את הראשון ואית תנויי תני מצוה להקריב את השני והטעם שכיון שאבד והפריש אחר מצוה באותו שהפריש כיון שהראשון היה אבוד וזה שמיעט רבינו אבל שנאמר שיקריב הראשון אין לנו כי כיון שאבד ועל כרחך צריך שיפריש אחר ובשעת הפרשה לא היה שם הראשון הראשון הפסיד חשיבותו אפי' שנמצא ורב אפילו כרבנן אמרה למילתיה. ואפשר עוד שדעת רבינו גם שם שאי זה שירצה יקריב ולכך לא כתב שם הראשון יקרב אלא כתב השני ירעה וכו' והכוונה שאפי' שהקריב הראשון ירעה השני ולא אמרינן ימות הואיל ומתחלה לא הביאו אלא להגריל על של עזאזל שמת. אי נמי אפשר דסד״א שאם הקריב הראשון שהשני אין צריך לרעות אלא הוא חולין שלא קידשו הגורל כי לא קידש אלא הצריך קמשמע לן שהשני ירעה אף אם הקריב הראשון וכל שכן אם הקריב השני שודאי הראשון רועה כי קדש הוא בלי ספק וכיון שלא כתב שיקריב הראשון ממילא שיקריב אי זה שירצה ואין קפידא בדבר ואם היה צריך להקריב הראשון היה מפרש כן נראה לי עכ״ל:\",4,0],[8,368,4,7,\"פסח שעברה שנתו וכו'. ברייתא שם (דף צ\\\"ו:):\",1,0],[8,368,4,8,\"פסח שנתערב בשלמים וכו'. זה פשוט על פי מה שנתבאר דמותר פסח קרב שלמים:\",1,0],[8,368,4,8,\"נתערב בזבחים אחרים ירעו עד שיסתאבו וכו'. משנה בפרק מי שהיה טמא (פסחים דף צ״ח) וכתב רש״י ובדמי היפה שבהם פסח אם קודם הפסח נסתאבו אם לאחר הפסח נסתאבו יביאנו שלמים. וכך הוא בתוספתא אלא שיש בה קצת שינוי:\",2,0],[8,368,4,8,\"נתערב בבכורות ירעו הכל וכו'. משנה וגמרא שם וכרבנן דפליגי ארבי שמעון:\",3,0],[8,368,4,9,\"המפריש פסחו עד שלא נתגייר וכו'. בירושלמי פ' האשה קאמר בהו צריך להמנות על פסח אחר וסובר רבינו דהיינו כמ\\\"ד ב\\\"ח נדחים:\",1,0],[8,368,4,10,\"המפריש מעות לפסחו והותירו יביא המותר שלמים. פ\\\"ק דזבחים (דף ט') מימרא דר\\\"נ:\",1,0],[8,368,4,10,\"הממנה אחרים על פסחו ועל חגיגתו וכו' עד סוף הפרק. בפרק האשה (דף צ') וכרבי דפליגי אמוראי אליביה ובפלוגתא דרבא ור' זירא פסק כמאן דמחמיר:\",2,0],[8,368,5,1,\"מי שהיה טמא בשעת שחיטת הפסח וכו' ה\\\"ז מביא פסח בי\\\"ד לחדש השני וכו'. מפורש במקרא בפ' בהעלותך.\",1,0],[8,368,5,1,\"ומ\\\"ש ושחיטת פסח זה מ\\\"ע בפני עצמה ודוחה את השבת שאין השני תשלומין לראשון אלא רגל בפנ\\\"ע לפיכך חייבים עליו כרת. בר\\\"פ מי שהיה טמא (צ\\\"ג) פלוגתא דתנאי ופסק כרבי ויתבאר בסמוך:\",2,0],[8,368,5,2,\"מי ששגג או נאנס ולא הקריב בראשון וכו'. שם (דף צ\\\"ג) הזיד בזה ובזה לד\\\"ה חייב שגג בזה ובזה ד\\\"ה פטור הזיד בראשון ושגג בשני לרבי ורבי נתן חייב ולר' חנינא בן עקביא פטור שגג בראשון והזיד בשני לרבי חייב לרבי נתן ולר' חנינא בן עקביא פטור וכבר נתבאר בסמוך שרבינו פוסק כרבי:\",1,0],[8,368,5,2,\"כתב הראב\\\"ד מי ששגג או נאנס ולא הקריב בראשון וכו'. א\\\"א שנה זה במשנתו כרבי ור' נתן ור\\\"ח בן עקביא פליגי עליה עכ\\\"ל. טעמו לומר דבשלמא בהזיד בראשון ושגג בשני דפסק חייב ניחא דפסק כרבי ור' נתן דרבים נינהו אלא בשגג בראשון והזיד בשני קשה אמאי פסק כרבי דמחייב דהוי יחידאה לגבי ר' נתן ור\\\"ח בן עקביא. וי\\\"ל שטעמו של רבינו משום דאמרינן בגמרא דרבי סבר וחדל לעשות הפסח ונכרתה דלא עבד בראשון א\\\"נ קרבן ה' לא הקריב במועדו בשני וממאי דהא חטאו ישא כרת הוא דקסבר מגדף היינו מברך השם וכתיב במברך השם ונשא חטאו וגמר האי חטאו דהכא מחטאו דהתם מה להלן כרת אף כאן כרת ורבי נתן ור\\\"ח בן עקביא סברי מגדף לאו היינו מברך את השם ובפ\\\"ק דכריתות (דף ז') אמרינן דחכמים ס\\\"ל דמגדף היינו מברך את השם וכיון דקם ליה רבי כחכמים הלכתא כוותיה ואע\\\"פ שרש\\\"י שם משבש גירסת הספרים ומהפך סברת חכמים לר\\\"ע רבינו נקט כגירסת הספרים. וה\\\"ר אברהם בנו של רבינו הקשו לו הקושיא זו שהקשה הראב\\\"ד והשיב לא נכנס הספק אלא מזה שאמרת שבין לר' נתן בין לר\\\"ח בן עקביא שני תשלומין דראשון ולא הכין הוא דהכי אמרינן במאי קא מיפלגי רבי סבר שני רגל בפ\\\"ע הוא פירושו שאין השני תלוי בראשון אלא חיוב בעצמו כשאר הרגלים לפיכך אם הזיד לדבריו בראשון ושגג בשני חייב וכן אם שגג בראשון והזיד בשני ור' נתן סבר שני תשלומין לראשון הוא ותקוני לראשון לא מתקנינן ולפיכך לדבריו אם הזיד בראשון ושגג בשני חייב שהמזיד בראשון נראה לחיוב דתקוני לראשון לא מתקנינן ואם לא ישלם התשלומין אפילו שגג בעת התשלומין חייב לא מפני שלא עשה את השני ששגג בו אלא מפני שלא עשה את הראשון שהזיד בו ור\\\"ח בן עקביא סבר שני תקנתא דראשון הוא ולדבריו אם שגג בראשון אפילו הזיד בשני או שגג בשני אפילו הזיד בראשון פטור כדאסקוה. וטעם הדבר שאם הזיד בראשון לא נראה לחיוב שכבר עשה לו הכתוב לדבריו תקנה בשני ואם שגג בשני פטור שבשעת התקנה שוגג היה וכן אם שגג בראשון והזיד בשני פטור שהראשון שהוא עיקר החיוב פטור הוא עליו מפני ששגג בו ואין השני עיקר חיוב עד שנחייב אותו עליו אם הזיד בו ולא הזיד בראשון הילכך לדברי ר' חנינא אינו חייב אלא כשהזיד בזה ובזה נמצא עכשיו ר' נתן סבר שני תשלומין דראשון ולא תקנתא ור' חנינא סבר שני תקנתא דראשון הוא ולאו תשלומין שענין התשלומין אינו ענין התקנה כדפרישית והנה רבי סבר שני רגל בפ\\\"ע הוא בא ר' נתן וחלק עליו ואמר שני תשלומין בא ר' חנינא וחלק עליו חלוקה אחרת ואמר שני תקנה הוא הילכך הלכה כרבי לגבי כל חד מינייהו דהלכה כרבי מחבירו עכ\\\"ל:\",2,0],[8,368,5,2,\"ומ\\\"ש אבל מי שהיה טמא או בדרך רחוקה וכו'. שם במשנה (דף צ\\\"ב:) מי שהיה טמא או בדרך רחוקה ולא עשה את הראשון יעשה את השני שגג או נאנס ולא עשה את הראשון יעשה את השני א\\\"כ למה נאמר טמא או שהיה בדרך רחוקה (אלא) שאלו פטורים מן הכרת ואלו חייבים בהכרת ופירש רבינו בפירוש המשנה כשהיה טמא או בדרך רחוקה [בפסח ראשון] ולא עשה את השני אינו חייב כרת לפי שנפטר מפסח ראשון שנאמר בו לשון כרת ונדחה לפסח שני שלא נאמר בו לשון כרת וכששגג או נאנס בפסח ראשון ולא עשה את השני חייב כרת כי לשון התורה כל מי שלא היה טמא או בדרך רחוקה ולא עשה פסח כלל חייב כרת והוא אמרו יתברך והאיש אשר הוא טהור ובדרך לא היה וכו' וזה עניין אומרם בכאן אלו פטורים מן ההכרת ואלו חייבים בהכרת עכ\\\"ל. ובזה אין מקום להשגת הראב\\\"ד שכתב אע\\\"פ שהזיד בשני א\\\"א עכשיו סותר את דבריו וכו':\",3,0],[8,368,5,3,\"ומי שהיה בדרך רחוקה וכו'. שם פלוגתא דר\\\"נ ורב ששת ופסק כרב ששת דהלכתא כוותיה באיסורי:\",1,0],[8,368,5,4,\"טמא שיכול ליטהר בפסח ראשון שלא טבל וכו'. בפרק אלו דברים (פסחים דף ס״ט:) יכול לא יהא ענוש כרת אלא שהיה טהור ושלא היה בדרך רחוקה ערל וטמא שרץ ושאר כל הטמאים מנין ת״ל והאיש:\",1,0],[8,368,5,5,\"כשם שמילת עצמו מעכבתו מלעשות פסח וכו'. פשוט בריש פרק הערל (יבמות דף ע':):\",1,0],[8,368,5,5,\"וכן טבילת אמהותיו לשם עבדות מעכבתו וכו': כתב הראב\\\"ד א\\\"א בתוספתא דפסחים בדברים שבין פסח מצרים לפסח דורות עכ\\\"ל:\",2,0],[8,368,5,6,\"הקטן אין מילת עבדיו וטבילת שפחותיו מעכבתו וכו'. יש לתמוה דתניא במכילתא וכל עבד איש אשה וקטן מנין ת\\\"ל מקנת כסף מ\\\"מ. ונראה שרבינו הוה גריס וכל עבד איש ולא של אשה וקטן:\",1,0],[8,368,5,7,\"גר שנתגייר בין פסח ראשון לפסח שני וכו'. בריש פרק מי שהיה טמא פלוגתא דרבי ור' נתן ופסק כרבי מחבירו:\",1,0],[8,368,5,7,\"ומה שכתב ואם שחטו עליו בראשון פטור. איכא למידק אטו קטן בר חיובא ופיטורא הוא. וכתב הר\\\"י קורקוס ז\\\"ל דכיון דרחמנא רבייה לקטן שישחטו עליו וממנין אותו נפטר הוא בכך מן השני:\",2,0],[8,368,5,8,\"נשים שנדחו לשני וכו'. בפרק האשה (דף צ\\\"א:) אשה בראשון שוחטין עליה בפני עצמה ובשני עושין אותה טפילה לאחרים דברי ר' יהודה ור' יוסי אומר אשה בשני שוחטין עליה בפני עצמה ואין צריך לומר בראשון רבי שמעון אומר אשה בראשון עושין אותה טפילה לאחרים בשני אין שוחטין עליה כל עיקר ופוסק רבינו כר' יהודה וכן פסק עוד בר\\\"פ ז' משום דאמרינן כמאן אזלא הא דאמר רבי אלעזר בשני רשות ובראשון חובה ודוחה את השבת כמאן כר' יהודה משמע דהלכתא כוותיה. ויש לתמוה דבפרק ב' אצל מ\\\"ש עושים חבורה כולה נשים אפילו בפסח שני משמע דפסק כר' יוסי כמ\\\"ש שם. וי\\\"ל דאף על גב דלענין עושין חבורה שכולה נשים בפסח שני פסק כר' יוסי כדקי\\\"ל דהלכתא כוותיה לגבי ר' יהודה מכל מקום לענין דוחה את השבת לא ראה לפסוק כמותו מדמשמע מר\\\"א שכתבתי בסמוך דסבר כר' יהודה בהא:\",1,0],[8,368,5,8,\"ואי זו היא דרך רחוקה ט״ו מילין חוץ לחומת ירושלים. בפרק מי שהיה טמא (פסחים דף צ״ג:) במשנה פלוגתא דתנאי ופסק כר״ע דאמר אי זו היא דרך רחוקה מן המודיעים ולחוץ וכמדתה לכל רוח ואמרינן בגמ' אמר עולא מן מודיעים ולחוץ ט״ו מילין:\",2,0],[8,368,5,9,\"ומ\\\"ש מי שהיה בינו ובין ירושלים יום י\\\"ד עם עליית השמש ט\\\"ו מילין או יתר וכו'. הכי משמע שם בגמ' בט\\\"ו מילין שאמרו הם מתחילים מהנץ החמה לא מעלות השחר ואמרינן בגמרא עולא לטעמיה דאמר אי זו היא דרך רחוקה כל שאינו יכול ליכנס בשעת שחיטה ופסק כעולא. ואפשר לומר דטעמא משום דמשמע קצת דר\\\"י דאמר כמה מהלך אדם ביום עשר פרסאות וכו' לאגמורן כדעולא אתא דאל\\\"כ למנ\\\"מ. ומפרש רבינו דכל שאינו יכול ליכנס בשעת שחיטה דאמר עולא היינו תחלת שעת שחיטה דהיינו אחר חצות ופשטא דסוגיא הכי מוכחא דאמר ט\\\"ו מיל מצפרא לפלגא דיומא.\",1,0],[8,368,5,9,\"ומ\\\"ש הלך ולא הגיע מפני שעכבוהו בהמות בדחקם. ברייתא שם (דף צ\\\"ד) היה עומד לפנים מהמודיעים ואינו יכול ליכנס מפני גמלים וקרונות המעכבות אותו יכול לא יהא חייב ת\\\"ל ובדרך לא היה והרי לא היה בדרך. ויש לתמוה על רבינו שנראה לכאורה שהוא פוסק בהפך ונראה שזהו שכתב עליו הראב\\\"ד אינו תופס דרך הגמרא ע\\\"כ. ונראה שרבינו מפרש דה\\\"ק יכול לא יהא חייב כרת אם הזיד ולא עשה את השני כדין מי שהיה בדרך רחוקה כיון שנתעכב בדרך ת\\\"ל ובדרך לא היה והרי לא היה בדרך כלומר אע\\\"פ שנתעכב בדרך כיון שעיכובו לא היה מחמת מרחק הדרך קרינן ביה ובדרך לא היה והרי הוא כאונס אחר ואם הזיד ולא עשה את השני חייב כרת.\",2,0],[8,368,5,9,\"ומ\\\"ש או שהיה בירושלים והיה חולה ברגליו וכו'. ירושלמי פ' מי שהיה טמא היה נתון מן המודיעים ולפנים ורגליו רעות יכול יהא חייב ת\\\"ל וחדל יצא זה שלא חדל ונראה דה\\\"פ יכול יהא חייב כרת אף על פי ששגג ולא הקריב בשני ת\\\"ל וחדל כלומר דוקא כשהזיד בראשון הוא כששגג בשני חייב כרת יצא זה שלא חדל מלעשות הראשון כרצונו:\",3,0],[8,368,5,9,\"מי שהיה חבוש חוץ לחומת ירושלים וכו' במה דברים אמורים בשהיה חבוש ביד ישראל וכו'. משנה וגמרא בפרק האשה (דף צ\\\"א):\",4,0],[8,368,5,9,\"ומה שכתב ואם לא יצא פטור מלעשות פסח שני וכו'. במשנה הנזכרת.\",5,0],[8,368,5,9,\"ומה שכתב וכן האונן והחולה והזקן שהם יכולים לאכול וכו'. שם במשנה הנזכרת לפיכך אם אירע בהם פיסול פטורים מלעשות פסח שני. ופירש\\\"י לפיכך הואיל ובשעת שחיטה ראויים היו ונזרק הדם עליהם וכו' פטורין מלעשות פסח שני:\",6,0],[8,368,6,1,\"אי זהו טמא שנדחה לפסח שני וכו' כגון זבין וזבות וכו'. בריש פרק מי שהיה (דף צ\\\"ג) ת\\\"ר אלו שעושים את השני הזבין והזבות המצורעין והמצורעות ובועלי נדות והיולדות ופירש\\\"י שכל אלו טומאה ארוכה.\",1,0],[8,368,6,1,\"ומ\\\"ש אבל הנוגע בנבלה ובשרץ וכו', כלומר שאינם אלא טומאת ערב,\",2,0],[8,368,6,1,\"הרי זה טובל וכו'. הוא מדאיתא בפרק האשה (דף צ') אמר רב יהודה אמר רב שוחטין וזורקין על טבול יום ומחוסר כפורים ואין שוחטין וזורקין על טמא שרץ ועולא אמר אף שוחטין וזורקין על טמא שרץ ופסק כרב יהודה אמר רב משום דרב רבן של כל בני גולה הוא ועוד דסוגיא כוותיה אזלא ובפרק כיצד צולין (פסחים דף פ״א) אמרו דרבי יוסי סובר כן וגם בריש פרק מי שהיה (דף צ״ג) אמרו דר״ע סובר כן וכן כתבו בתוספות דכמה תנאי סברי כרב ופירש״י אין שוחטין וזורקין על טמא שרץ ואע״פ שבידו לטבול היום ובגמ' לרב ומ״ש טבול יום דחזי לאורתא טמא שרץ נמי חזי לאורתא מחוסר טבילה טבול יום נמי מחוסר הערב שמש שמשא ממילא ערבא מחוסר כפורים נמי הא מחוסר כפרה הוא שקינו בידו טמא שרץ נמי הרי מקוה לפניו דילמא פשע א״ה מחוסר כפורים נמי דילמא פשע כגון דמסרינהו לב״ד וכו' חזקה אין ב״ד של כהנים עומדים משם עד שיכלו מעות שבשופרות:\",3,0],[8,368,6,2,\"טמא מת שחל שביעי שלו להיות בי\\\"ד וכו' אין שוחטין עליו אלא נדחה לפסח שני וכו'. שם אליבא דרב יהודה אמרינן הכי:\",1,0],[8,368,6,2,\"כתב הראב\\\"ד אין דרך ההלכה הולכת כן וכו'. ואני אומר שמ\\\"ש שהרי רב שאמר אין שוחטין וזורקין מכאן למד, כלומר דאמרינן בגמרא לרב דאמר אין שוחטין וזורקין על טמא שרץ מדאורייתא לא חזי מדכתיב איש איש כי יהיה טמא לנפש מי לא עסקינן שחל שביעי שלו להיות בערב פסח דהיינו טומאת שרץ ואמר רחמנא נדחי. וי\\\"ל לדעת רבינו דאע\\\"ג דאמרינן דטמא מת שחל שביעי שלו בערב פסח דהיינו טמא שרץ לאו לגמרי מדמי להו אלא לומר דכשם שטמא מת אע\\\"פ שיכול לעלות בו ביום אמר רחמנא נדחי ה\\\"נ טמא שרץ מיהו הא כדאיתא והא כדאיתא בטמא שרץ אחר שטבל שוחטין וזורקין עליו משא\\\"כ בטמא מת שאפי' הזה וטבל אין שוחטין וזורקין עליו. ומ\\\"ש דקרא בשלא הזה ולא טבל ומעשה הוה ששחטו וזרקו עליהם קודם טבילה והזייה ולא שאלו אלא אחר זמן שחיטה ונדחו, דברי תימה הם למה לא שאלו קודם מעשה ושאלו אחר מעשה וכי בתר דעבדין מתמלכין ועוד קשה למה נדחו הל\\\"ל להם שיזו עליהם ויטבלו ואח\\\"כ ישחטו להם פסח אחר ויזרקו עליהם את הדם ועוד שהרי בסיפרי מפורש כדברי רבינו והביאו רש\\\"י בפירושיו בפרשת בהעלותך למה נגרע אמר להם אין קדשים קרבים בטומאה אמרו לו א\\\"כ יזרק הדם על הטמאים והבשר יאכל לטהורים אמר להם לא שמעתי עמדו ואשמעה. ומ\\\"ש עוד הראב\\\"ד והכתוב מעיד כן שאמרו אנחנו טמאים לנפש אדם ואם לאחר טבילה והזייה מאי טומאה הויא בהו. תמהני איך פה קדוש יאמר דבר זה דכל זמן שלא העריב שמשן אכתי לאו טהורים נינהו ועוד לפי דבריו דברי בורות דברו לומר שהם טמאים והיו יכולים ליטהר בהזייה וטבילה ועוד היכי קאמר ביום ההוא לא היו יכולים הא למחר היו יכולים והלא כך היו יכולים ביום כמו למחר שאם יטבלו בו ביום היו יכולין לעשות ואם לא יטבלו גם למחר לא יכולים לעשות. ועוד קשה על הראב\\\"ד שהכתוב מכחישו שכתוב אנחנו טמאים לנפש אדם למה נגרע לבלתי הקריב את קרבן ה' ואם כדבריו כבר הקריבו קרבן לה' ולא היתה השאלה אלא אם יעלה להם הקרבן שהקריבו כבר קודם הזייה וטבילה. ודוחק גדול לפרש דלבלתי הקריב את קרבן ה' היינו שיעלה להם הקרבן שכבר הקריבו דאין זה במשמע וכמדומה לי שזו ראיה שאין עליה תשובה.\",2,0],[8,368,6,2,\"ומ\\\"ש בד\\\"א בשנטמא בטומאות מן המת שהנזיר מגלח עליהם וכו': כתב הראב\\\"ד שהנזיר מגלח עליהם א\\\"א לא מצאתי לזה שורש וכו'. ביאור דבריו שלא מצא שורש לחילוק זה כלומר שהראב\\\"ד סובר שאף בטומאות שהנזיר מגלח עליהם אם טבל והזה שוחטים עליו כמבואר בדבריו בהשגה שקודם זו ואפי' לפי סברת רבינו שסובר שאע\\\"פ שטבל והזה אין שוחטין עליו דין הוא לומר דה\\\"מ בטומאות שהנזיר מגלח עליהם אבל בטומאות שאין הנזיר מגלח עליהם כיון שאם אכל קדש בטומאה זו אין חייבין עליה לא כרת ולא קרבן דין הוא שלא ידחה מפסחו. ויש נוסחא בהשגה זו שבמקום אף אם סברת עצמו הוא כתוב אבל סברת עצמו היא והיא הנוסחא הנכונה:\",3,0],[8,368,6,3,\"זב שראה שתי ראיות וספר שבעה ימים וכו'. בפ' האשה (פסחים דף צ') תנן זב שראה שתי ראיות שוחטין עליו בשביעי.\",1,0],[8,368,6,3,\"ומ\\\"ש וטבל בשביעי. בגמ' אמרינן הכי אליבא דרב יהודה דאמר שוחטין וזורקין על טבול יום ואין שוחטין וזורקין על טמא שרץ וכבר נתבאר בסמוך שרבינו פסק הלכה כמותו.\",2,0],[8,368,6,3,\"ומ\\\"ש ואם ראה זוב אחר שנזרק הדם הרי זה פטור מלעשות פסח שני. בפרק כיצד צולין (פסחים דף פ\\\"א) ר' יוסי אומר זב בעל שתי ראיות ששחטו וזרקו עליו בשביעי שלו ואחר כך ראה וכן שומרת יום כנגד יום ששחטו וזרקו עליה בשני שלה ואח\\\"כ ראתה הרי אלו מטמאים משכב ומושב למפרע ופטורים מלעשות פסח שני:\",3,0],[8,368,6,3,\"וכן שומרת יום כנגד יום וכו'. משנה פרק האשה שם (פסחים דף צ').\",4,0],[8,368,6,3,\"ומ\\\"ש טובלת קודם שישחטו עליה. הוא אליבא דרב יהודה שפסק רבינו כמותו כמו שנתבאר בסמוך.\",5,0],[8,368,6,3,\"ומ\\\"ש אם ראתה דם אחר שנזרק דם הפסח פטורה מלעשות פסח שני. נתבאר בסמוך.\",6,0],[8,368,6,3,\"ומ\\\"ש ואין שוחטין על הנדה בשביעי שלה וכו'. שם (פסחים דף צ':):\",7,0],[8,368,6,4,\"מחוסרי כפורים ושחל יום הבאת קרבנותיהם בארבעה עשר וכו' עד ולא יקריבו אותן. שם וכתבתיו בריש פרק זה:\",1,0],[8,368,6,5,\"מצורע שחל שמיני שלו להיות בארבעה עשר וראה קרי בו ביום וכו'. בסוף פרק האשה (דף צ\\\"ב):\",1,0],[8,368,6,6,\"טמא מת שחל שביעי שלו להיות בשבת אין מזין עליו. בר״פ אלו דברים (פסחים דף ס״ה ס״ו) פלוגתא דתנאי ופסק כר״ע ובס״פ האשה (דף צ״ב) פסק רבא הכי.\",1,0],[8,368,6,6,\"ומה שכתב ואפי' חל שביעי שלו להיות בי\\\"ג בניסן והוא שבת ידחה ליום י\\\"ד. פשוט הוא:\",2,0],[8,368,6,6,\"וכתב הראב\\\"ד כל זה שיבוש שאם בא שביעי שלו בשבת וכו'. ורבינו חולק על הראב\\\"ד וסובר שאין צריך שיהא השביעי חמישי לשלישי אלא אפילו היה ט' או י' אין בכך כלום כמ\\\"ש בפי\\\"א מהל' פרה.\",3,0],[8,368,6,6,\"ומ\\\"ש רבינו ומזין עליו ואין שוחטים עליו כמו שביארנו אלא ידחה לפסח שני. הוא מ\\\"ש בפרק זה שטמא מת שחל שביעי שלו להיות בי\\\"ד אע\\\"פ שטבל והוזה עליו אין שוחטין עליו אלא נדחה לפסח שני.\",4,0],[8,368,6,6,\"ומ\\\"ש רבינו והלא איסור הזייה בשבת משום שבות והפסח בכרת והיאך יעמידו דבריהם במקום כרת וכו': כתב הראב\\\"ד א\\\"א זה המפרש שפירש טעם להזאה וערל וכו'. ואיני מבין דבריו שמ\\\"ש רבינו מפני שהיום שהוא אסור בהזייה משום שבות אינו זמן הקרבן שחייבין עליו כרת אינו טעם אלא לכשחל שביעי שלו בי\\\"ג שחל להיות בשבת למה אין מזין עליו בו ביום אבל לכשחל שביעי שלו בי\\\"ד שחל בשבת א\\\"צ טעם זה שהרי אפילו יזו עליו בו ביום אין שוחטין עליו לדעת רבינו כמו שנתבאר בפ' זה. ומ\\\"ש והערל אם יטבול ביומו מה בכך ולמה נמנע אותו מלאכול עכ\\\"ל. גם זה איני מבין שמה יש בזה למה שנתן טעם רבינו שהעמידו דבריהם במקום כרת מפני שעדיין אינו חייב במצוה ומוטב שלא נניחנו לטבול בו ביום ותתקיים גזירת חכמים. ומזה תשובה ג\\\"כ למ\\\"ש ועוד דב\\\"ה אפילו ערל שמל ל' יום קודם הפסח קאמרי שלא יטבול ויאכל וכו' שמוטב שלא יטבול להתחייב במצות משיטבול ותתקיים גזירת חכמים ואפשר שאפילו עבר וטבל אין שוחטין עליו דלא נתנו חכמים דבריהם לשיעורים. ומ\\\"ש ועוד לדבריו מצורע למה לא העמידו דבריהם והרי הוא בהזייה עכ\\\"ל. איני יודע מי הגיד לו שמצורע מותר להזות עליו בשבת שלא סבר כן לא בגמ' ולא בדברי רבינו ולא עוד אלא שודאי א\\\"א לו ליטהר אם חל שביעי שלו להיות בשבת אם מפני שלא בהזייה בלבד שהיא משום שבות הוא נטהר שהרי צריך שחיטת הצפור שהיא מן התורה ועוד שאע\\\"פ שהזו עליו בשביעי אין שוחטין עליו את הפסח עד שיביא קרבנותיו ואם חל י\\\"ד להיות בשבת א\\\"א לו להביא קרבנותיו שהרי אינם דוחים את השבת וא\\\"כ לא ה\\\"ל מקום להראב\\\"ד להזכיר הזיית מצורע כאן ומה שאמרו בסוף פרק האשה שבמצורע לא העמידו דבריהם במקום כרת היינו שהתירו לו ליכנס לעזרת נשים אע\\\"פ שהוא טבול יום. ומ\\\"ש אבל הטעם לכולם שהשבות שיכול לבא לידי איסור כרת וכו' יש מקום לבעל דין לחלוק שלא היה לחכמים לדחות עכשיו איסור כרת ודאי בערל משום גזירת ספק שמא יבא שנה אחרת לידי ספק כרת. ומה שכתב וכן איזמל אבל אונן ובית הפרס שנידש ומצורע לבהונות וכו'. מבואר בס\\\"פ האשה (דף צ\\\"ב):\",5,0],[8,368,6,7,\"ישראל ערל שמל בע\\\"פ שוחטין עליו אחר שמל. פשוט בס\\\"פ האשה שם.\",1,0],[8,368,6,7,\"ומה שכתב אבל גר שנתגייר ביום י\\\"ד ומל וטבל אין שוחטין עליו וכו'. שם פלוגתא דב\\\"ש וב\\\"ה ופסק כב\\\"ה.\",2,0],[8,368,6,7,\"ומ\\\"ש והלא גזירה זו מדבריהם והפסח בכרת ואיך העמידו דבריהם במקום כרת וכו': כתב הראב\\\"ד ביום הקרבן שהוא יום י\\\"ד. א\\\"א כאן סותר מה שאמר למעלה וכו'. זה נמשך אחר מ\\\"ש בהשגה שקודם זו לא עמד טעמו בו כי יום י\\\"ד הוא זמן שחיטת הפסח וזריקתו והם לעונש הכרת בעצמו וכבר כתבתי שם כי מ\\\"ש רבינו מפני שהיום שהוא אסור בהזייה משום שבות אינו זמן הקרבן שחייבים עליו כרת אינו טעם אלא לכשחל שביעי שלו בי\\\"ג שחל להיות בשבת למה אין מזין עליו בו ביום ואינו טעם לכשחל שביעי שלו בי\\\"ד שחל להיות בשבת כי גם רבינו סובר שם כי יום י\\\"ד הוא זמן הקרבן והם דבריו כאן ואין בהם סתירה:\",3,0],[8,368,6,8,\"מי שבא בבית הפרס הרי זה מנפח והולך ואם לא מצא עצם ולא נטמא שוחט ואוכל פסחו וכו'. בפסחים סוף פרק האשה שם.\",1,0],[8,368,6,8,\"ומ\\\"ש וכן בית הפרס שנדוש טהור לעושה פסח. מימרא שם:\",2,0],[8,368,6,9,\"האונן ראוי לאכול הפסח לערב וכו'. משנה וגמרא שם (דף ע\\\"א:).\",1,0],[8,368,6,9,\"ומ\\\"ש טובל ואח\\\"כ אוכל. שם במשנה ובפרק בתרא דחגיגה.\",2,0],[8,368,6,9,\"ומה שכתב במה דברים אמורים שמת לו מת אחר חצות וכו'. היינו כאוקימתא דאביי בזבחים פרק טבול יום (זבחים דף ק').\",3,0],[8,368,6,9,\"ומה שכתב ואם שחטו וזרקו עליו טובל ואוכל לערב. גם זה נלמד מאוקימתא דרבא שם אידי ואידי אחר חצות ול\\\"ק כאן קודם ששחטו וזרקו עליו כאן לאחר ששחטו וזרקו עליו. ומשמע לרבינו דאביי ורבא לא פליגי לענין דינא דבמת אחר חצות שוחטין עליו ואוכל ובמת קודם חצות אין שוחטין עליו ואם שחטו וזרקו עליו אוכל וליכא בינייהו אלא לענין תרוצי מתנייתא דמר מתרץ להו הכי ומר מתרץ להו הכי:\",4,0],[8,368,6,9,\"מת לו מת בי\\\"ג וקברו בי\\\"ד וכו'. גם זה שם אוקימתא דרב אשי וביאור הדברים דאנינות דיום מיתה והוא ג\\\"כ יום קבורה הוי דאורייתא ואנינות לילה שאחריו הוי מדבריהם אבל אנינות יום קבורה שאינו יום מיתה אינו אלא מדבריהם ובלילה של אחריו אין אנינות כלל אפילו מדבריהם כך מבואר בגמרא וגם בדברי רבינו פרק שני מהלכות ביאת מקדש:\",5,0],[8,368,6,9,\"ויום שמועה ויום ליקוט עצמות הרי הוא כיום קבורה וכו' עד וטובל ואוכל בקדשים לערב. משנה בסוף פרק האשה. ובגמרא (דף צ\\\"ב) מלקט עצמות הא בעי הזאה שלישי ושביעי אימא שליקטו לו עצמות ורבינו קיצר במובן:\",6,0],[8,368,6,10,\"מי שחופר בגל לבקש על המת אין שוחטין עליו וכו'. משנה שם (דף צ\\\"א).\",1,0],[8,368,6,10,\"ומה שכתב שחטו עליו ולא נמצא שם מת הרי זה אוכל לערב. כן משמע שם.\",2,0],[8,368,6,10,\"ומ\\\"ש נמצא שם מת אחר שנזרק הדם וכו'. משנה וגמ' שם:\",3,0],[8,368,6,11,\"מי שעבר בדרך ומצאו מת מושכב לרוחבה של דרך וכו' עד לפי שאי אפשר שלא יגע ושלא יסיט ושלא יאהיל. בפרק כיצד צולין (פסחים דף פ״א:) ובפרק ט' דנזיר (דף ס״ג) ומפרש רבינו דהא דקתני במה דברים אמורים במהלך ברגליו קאי ארישא דקתני מושכב לרחבו של דרך ולא כדפי' רש״י דקאי אמצאו משובר ומפורק ומפרש רבינו שאף על פי שהוא מושכב לרוחב הדרך אם הוא מהלך ברגליו ואפשר שנטה מהדרך מעט בענין שלא נגע ולא הסיט ולא האהיל מה שאין כן ברוכב או טעון.\",1,0],[8,368,6,11,\"ומ\\\"ש רבינו ושוחט ואוכל פסחו. כלישנא בתרא דרב אשי דאפילו נודע לו לפני זריקה הציץ מרצה ומשמע לרבינו דאפילו לכתחלה שוחט קרבן פסח שהוא קרבן חובה והיא מצוה עוברת משא\\\"כ בשאר הקרבנות שאם נודע לו קודם זריקה אם זרק הורצה אבל לכתחלה לא יזרוק כדמשמע מדברי רבינו פ\\\"ד מהל' ביאת המקדש:\",2,0],[8,368,6,12,\"מי שעשה פסח בחזקת שהוא טהור וכו'. משנה בפ' כיצד צולין (פסחים דף פ':) נטמא טומאת התהום הציץ מרצה.\",1,0],[8,368,6,12,\"ומ\\\"ש ודבר זה הלכה מפי הקבלה. שם בגמ' טומאת התהום הלכתא גמירי לה וקרא אסמכתא בעלמא.\",2,0],[8,368,6,12,\"ומ\\\"ש אבל אם נודע לו שהיה טמא בטומאה ידועה חייב בפסח שני. פשוט הוא:\",3,0],[8,368,6,13,\"מי שנטמא במת וכו'. מימרא דרב המנונא בפירקא בתרא דנזיר (דף ס\\\"ד:) אמר רב המנונא נזיר ועושה פסח שהלכו בקבר התהום בשביעי שלהם טהורים מ\\\"ט לא אלימא טומאת התהום למיסתר מתיב רבא ירד ליטהר מטומאת מת טמא שחזקת הטמא טמא וכו' א\\\"ל מודינא לך בנזיר שמחוסר תגלחת א\\\"ל רבא אף אנא מודינא בעושה פסח דלא מחוסר ולא כלום אמר ליה אביי והא מחוסר הערב שמש א\\\"ל שמשא ממילא ערבא:\",1,0],[8,368,6,13,\"וכתב הראב\\\"ד אבל אם נטמא בטומאת התהום א\\\"א לא נראה מן הגמרא דנזיר וכו'. ואני אומר שגם מדברי רבינו יש ללמוד כן שכיון שטבל בשביעי פסקה טומאה ראשונה וטבילה זו בשביעי היא אחר שהוזה עליו בו ביום וכמו ששנינו הזה ושנה וטבל ועוד דמדכתב פסקה טומאה ראשונה משמע בהדיא שאחר שהוזה בו ביום מיירי דאל\\\"כ עדיין לא פסקה טומאה ראשונה.\",2,0],[8,368,6,13,\"ומה שכתב אבל אם נטמא בטומאת התהום בששי לטומאתו. מילתא פסיקתא נקט וה\\\"ה לנטמא בשביעי קודם שטבל:\",3,0],[8,368,7,1,\"רבים שהיו טמאי מת בפסח ראשון וכו'. משנה בפרק כיצד צולין (פסחים דף ע״ט).\",1,0],[8,368,7,1,\"ומ\\\"ש או כלי שרת טמאים. שם בברייתא.\",2,0],[8,368,7,1,\"ומ\\\"ש ודבר זה בטומאת המת בלבד כמו שביארנו בביאת המקדש. פ\\\"ד:\",3,0],[8,368,7,2,\"היו הקהל מחצה טהורים ומחצה טמאי מת וכו'. שם פלוגתא דאמוראי ופסק כרב.\",1,0],[8,368,7,2,\"ומ\\\"ש ואוכלים אותו בטומאה. משנה שם (דף ע\\\"ו:) הפסח שבא בטומאה נאכל בטומאה שלא בא מתחלתו אלא לאכילה.\",2,0],[8,368,7,2,\"ומ\\\"ש היו טמאי מת עודפים על הטהורים אפילו אחד יעשו כולם בטומאה. שם (דף ע\\\"ט) פלוגתא דתנאי בברייתא ופסק כת\\\"ק:\",3,0],[8,368,7,3,\"היו האנשים מחצה טמאי מת ומחצה טהורים וכו'. שם בדף הנזכר מתרצינן הכי ברייתא אליבא דרב דקי\\\"ל כוותיה:\",1,0],[8,368,7,4,\"היה רוב הקהל זבים וכו'. ומיעוטן טמאי מת וכו'. שם (דף פ') מימרא דרב:\",1,0],[8,368,7,5,\"היו רוב הקהל טמאי מת ומיעוטן זבים וכו'. שם בדף הנזכר פלוגתא דאמוראי ופסק כרב הונא:\",1,0],[8,368,7,6,\"היו שליש הקהל טהורים וכו'. שם בדף הנזכר:\",1,0],[8,368,7,6,\"כיצד משערים הפסח וכו'. פרק מי שהיה (דף צ\\\"ד:) בטמאים הלך אחר רוב העומדים בעזרה. ובירושלמי פ' כיצד צולין (הלכה ו') לטומאה הלכו אחר רוב נכנסים לעזרה מה בכל כת וכת משערים או אין משערין אלא כת הראשונה בלבד א\\\"ר יוסי ב\\\"ר בון עד שהם מבחוץ הן משערין את עצמן:\",2,0],[8,368,7,7,\"יחיד שנטמא בספק רה\\\"י וכו' וצבור שנטמא בספק רשות היחיד וכו'. ירושלמי סוף פרק האשה יחיד שנטמא בספק רה\\\"י בפסח ר' הושעיא רבה אמר ידחה לפסח שני ר\\\"י אמר משלחין אותו לדרך רחוקה וכו' צבור שנטמא בספק רשות היחיד בפסח ר\\\"י אמר יעשו בספיקן רבי הושעיא רבה אמר יעשו בטומאה אף רבי הושעיא מודה שיעשו בספיקן לא אמר רבי הושעיא אלא לחומרן ופסק רבינו כרבי הושעיא דרביה דר\\\"י הוא:\",1,0],[8,368,7,8,\"פסח שהקריבוהו בטומאה הרי זה נאכל בטהרה וכו'. משנה בפרק כיצד צולין (פסחים דף ע״ו:). ויש טעות סופר בספרי רבינו וצריך להגיה ולמחוק בטהרה ולכתוב במקומו בטומאה:\",1,0],[8,368,7,8,\"ואינו נאכל לכל טמא אלא לטמאי מת וכו'. משנה בפרק מי שהיה טמא (פסחים דף צ״ה:) הפסח שבא בטומאה לא יאכלו ממנו זבים וזבות נדות ויולדות ואם אכלו פטורים ומשמע לרבינו דלא מיעטה המשנה אלא דוקא הני טמאים שטומאה יוצאה מגופם אבל שאר טמאים שאין טומאה יוצאה מגופם יאכלו והכי אמרינן בפרק חמישי דבכורות (דף ל״ג:) על משנה זו דפליג רחמנא בין טומאה יוצאה עליו מגופו לאין טומאה יוצאה עליו מגופו.\",2,0],[8,368,7,8,\"ומה שכתב מפי השמועה למדו שהנאכל לטהורים וכו'. פרק מי שהיה בגמרא.\",3,0],[8,368,7,8,\"ומה שכתב אפילו אכלו טמאי המת מהאימורים שלו פטורים. שם בעיא דאיפשיטא:\",4,0],[8,368,7,8,\"במה דברים אמורים שהפסח יאכל בטומאה וכו'. נלמד ממה שיבא בסמוך:\",5,0],[8,368,7,9,\"ומ״ש שחטוהו בטהרה ונטמאו רוב הצבור קודם זריקת הדם וכו'. בפרק כיצד צולין (פסחים דף ע״ח:). וקשה שדברי רבינו סותרים זה את זה שבתחלה כתב בד״א שהפסח יאכל בטומאה כשנטמאו הצבור קודם זריקת הדם ואח״כ כתב שחטוהו בטהרה ונטמאו רוב הצבור קודם זריקת הפסח לא יאכל. וי״ל דאהא דת״ר שחטו בטהרה ואח״כ נטמאו הבעלים יזרק הדם בטהרה ואל יאכל בשר בטומאה וכו' אר״י הכא במאי עסקינן בצבור וכו' אי בצבור אמאי אין הבשר נאכל בטומאה גזירה שמא יטמאו הבעלים וכו' ויאמרו אשתקד לא נטמאנו ואכלנו השתא נמי ניכול ולא ידעי דאשתקד כי אזדריק דם בעלים טמאים הוו השתא בעלים טהורים הוו. ודברי רבינו כך הם מתבארים בד״א שהפסח יאכל בטומאה בשנטמאו קודם זריקת הדם אף על פי ששחטוהו בטהרה זה הוא מן הדין אבל משום גזירה אם שחטוהו אם נטמאו בעלים אפילו קודם זריקה לא יאכל:\",1,0],[8,368,7,9,\"היו כלי שרת טמאים בשרץ וכו'. בפרק כיצד צולין (פסחים דף ע״ט) פלוגתא דאמוראי ופסק כרב חסדא דרבי יצחק סבר כוותיה:\",2,0],[8,368,8,2,\"אכילת בשר הפסח בלילי ט\\\"ו מ\\\"ע וכו' ואין מצה ומרור וכו'. במכילתא מנין אתה אומר שאם אין להם מצה ומרור הן יוצאין ידי חובתן בפסח ת\\\"ל יאכלוהו:\",1,0],[8,368,8,2,\"ומ\\\"ש אבל מרור בלא פסח אינו מצוה. בס\\\"פ ע\\\"פ (דף ק\\\"כ) אמר רבא מצה בזמן הזה דאורייתא ומרור דרבנן מ\\\"ש מרור דכתיב על מצות ומרורים (יאכלוהו) בזמן דאיכא פסח יש מרור בזמן דליכא פסח ליכא מרור מצה נמי הא כתיב על מצות ומרורים מצה הא מיהדר הדר ביה קרא דכתיב בערב תאכלו מצות:\",2,0],[8,368,8,3,\"מצוה מן המובחר לאכול בשר הפסח אכילת שובע. במכילתא הפסח נאכל אכילת שובע ואין מצה ומרור נאכלין אכילת שובע, כלומר אחר אכילת מצה ומרור יאכלוהו.\",1,0],[8,368,8,3,\"ומ״ש לפיכך אם הקריב שלמי חגיגה בי״ד אוכל מהם תחלה ואח״כ אוכל בשר הפסח וכו'. ברייתא בפ' אלו דברים (פסחים דף ע').\",2,0],[8,368,8,3,\"ומ״ש ואם לא אכל אלא כזית יצא י״ח. כך דין סתם אכילה. ובמשנה פ' האשה (דף צ״א) ואפילו חבורה של ק' שאינם יכולים לאכול כזית. והכי משמע מדאמרינן בפ' כיצד צולין (פסחים דף פ״ה:) כזיתא דפסחא בביתא והלילא פקע באיגרא:\",3,0],[8,368,8,4,\"ושניהם אינם נאכלים אלא צלי אש. משנה פ' מי שהיה טמא (פסחים דף צ״ה):\",1,0],[8,368,8,4,\"אכל נא ומבושל כאחת אינו לוקה אלא אחת וכו'. בס״פ כל שעה (פסחים דף מ״א) אמר אביי וכו' אכל נא ומבושל לוקה שלשה רבא אמר אין לוקין על לאו שבכללות א״ד תרתי הוא דלא לקי חדא מיהת לקי איכא דאמרי חדא נמי לא לקי כך היא גי' רבינו וידוע דהלכה כרבא אלא שיש לתמוה למה פסק כל״ק. וכ״פ עוד בפי״ח מהל' סנהדרין וכבר השיגו הרמב״ן ואפשר שטעמו משום דאמרי' איכא דאמרי וא״ד לא מתבריר הי הוי לישנא קמא והי הוי ל״ב והילכך נקטינן לקולא ומה גם בדין מלקות שהוא כמיתה:\",2,0],[8,368,8,4,\"אכל ממנו נא או מבושל מבע\\\"י אינו לוקה וכו'. ברייתא שם:\",3,0],[8,368,8,5,\"אכל ממנו כזית צלי מבע\\\"י וכו'. גם זה שם ודלא כר' יהודה:\",1,0],[8,368,8,6,\"נא שהזהירה עליו תורה וכו' אבל אם אכל ממנו בשר חי אינו לוקה וכו'. גם זה שם:\",1,0],[8,368,8,6,\"צלהו כל צרכו וכו'. גם זה שם ברייתא ומימרא דרב אשי:\",2,0],[8,368,8,7,\"מבושל שהזהירה עליו תורה וכו'. משנה וברייתא שם (דף מ'):\",1,0],[8,368,8,8,\"צלהו ואחר כך בשלו וכו'. שם ת\\\"ר במים אין לי אלא במים שאר משקין מנין אמרת ק\\\"ו וכו' רבי אומר וכו' שאר משקין מנין ת\\\"ל בשל מבושל מ\\\"מ מאי בינייהו צלי קדרה. ופירש\\\"י צלי קדרה שמבשלין אותו בקדרה בלא מים ובלא שום משקה אלא מים הנפלטים משמנו למאן דיליף לה מק\\\"ו הכא שרי לרבי דיליף מריבויא האי נמי בשל מבושל הוא. ואמרינן תו בגמרא ורבנן האי בשל מבושל מאי עבדי ליה מיבעי ליה לכדתניא בשלו ואחר כך צלאו או שצלאו ואח\\\"כ בשלו חייב. ויש לתמוה על רבינו שמאחר שפסק כרבנן דצלאו ואחר כך בשלו חייב ה\\\"ל לפטור בצלי קדרה דלא מיחייבין אלא לרבי דלית הלכתא כוותיה. ונ\\\"ל שרבינו מפרש דלרבנן נמי חייב על צלי קדרה מריבויא דבשל מבושל וכי אמרינן דאיכא בינייהו צלי קדרה היינו לומר דמק\\\"ו לא הוה משתמע אבל מבשל מבושל ודאי משתמע שפיר לכ\\\"ע.\",1,0],[8,368,8,8,\"ומה שכתב אבל מותר לסוך אותו ביין ובשמן וכו' ומותר לטבל הבשר אחר שנצלה וכו'. משנה שם:\",2,0],[8,368,8,9,\"אין צולין את הפסח וכו'. נלמד ממה שיתבאר לקמן שאם נגע בחרסו של תנור יקלוף את מקומו ולא מפליג בין שהתנור של אבן בין שהוא של מתכת.\",1,0],[8,368,8,9,\"ומ״ש לפיכך אם היה כלי מנוקב וכו'. בר״פ כיצד צולין (פסחים דף ע״ד) תנן אין צולין הפסח לא על השפוד ולא על האסכלה ומפרש בגמרא שאם היתה אסכלה מנוקבת מותר:\",2,0],[8,368,8,9,\"כתב הראב\\\"ד והוא שלא יגע בכלי וכו'. ונ\\\"ל דרבינו משמע ליה דא\\\"כ לא הוו שתקי בגמרא מלהזכיר כן גבי אסכלה מנוקבת ועוד דאם כדברי הראב\\\"ד פשיטא אלא חרסו של תנור שאני שאין האור שולט בו כמו ששולט באסכלה מנוקבת. ואפשר דרבינו נמי בלא יגע מיירי ולישנא דגמ' נקט.\",3,0],[8,368,8,9,\"ומ\\\"ש ואין צולין אותו בשפוד של מתכת וכו'. בראש הפרק הנזכר ויהיב טעמא משום דחם מקצתו חם כולו וקא מיטוי מחמת השפוד ורחמנא אמר צלי אש ולא צלי מחמת דבר אחר:\",4,0],[8,368,8,10,\"הסיק את התנור וגרף את כל האש וכו'. מימרא דר\\\"י (דף ע\\\"ה).\",1,0],[8,368,8,10,\"ומ\\\"ש חתכו ותלהו על גבי גחלים הרי זה צלי אש. ברייתא שם בשם רבי ומשמע לרבינו דכיון דלא אשכחן מאן דפליג עליה נקטינן הכי:\",2,0],[8,368,8,10,\"צלהו ע״ג סיד או חרסית. הכי משמע בר״פ כיצד צולין. ודין חמי טבריא בס״פ כל שעה (פסחים דף מ״א):\",3,0],[8,368,8,10,\"כיצד צולין אותו וכו'. ר\\\"פ (דף ע\\\"ד) כיצד צולין את הפסח מביאין שפוד של רמון ותוחבו מתוך פיו עד בית נקובתו ונותן את כרעיו ואת בני מעיו לתוכו דברי רבי יוסי הגלילי רבי עקיבא אומר כמין בישול הוא זה אלא תולן חוצה לו וידוע דהלכה כר\\\"ע מחבירו.\",4,0],[8,368,8,10,\"ומ\\\"ש ותולהו לתוך התנור והאש למטה כלומר שאם לא היה האש למטה שגרפו הרי זה אסור שאין זה צלי אש כמו שנתבאר בסמוך. ובגמ' קאמר דדוקא שפוד של רמון משום דשפוד של שאר עצים מפיק מיא והוי כמבושל ופריך של רמון נמי אית ביה קיטרי כלומר וע\\\"י קיטרי מפיק מיא ומשני שיעי קיטרי ואי בעית אימא בנבגא בר שתא דלית ביה קיטרי והא איכא בי פיסקיה דמפיק לבי פיסקיה לבר. ופירש\\\"י והא איכא בי פיסקי ראש השפוד שהוא מקום חתך ומוציא מים. דמפיק לבי פיסקי לבר חוץ לפי הפסח דאי מפקי מיא לא עיילי לפסח. ורבינו השמיט כל זה משום דמשמע דמדרבנן הוא למיחש להכי ומשום הכי נקט לקולא כלישנא קמא דשני שיעי קיטרי ולא כתב דמפיק לבי פיסקיה לבר משום דאורחא דעלמא הכי הוא להוציא ראש השפוד לחוץ ואין צורך להתנות בכך. ואפשר שזהו פירוש מה שאמר דמפיק לבר כלומר מנהגא דעלמא הכי הוא:\",5,0],[8,368,8,14,\"ומה שכתב נגע הבשר בחרסו של תנור וכו' עד שאין פודין מעשר שני בירושלים. הכל משנה בריש פרק כיצד צולין (פסחים דף ע\\\"ה) אלא דגבי נטף מרוטבו על החרס וחזר עליו שנינו יטול את מקומו. ובקצת ספרי רבינו טעות סופר וכך מצאתי בנוסחא מדוייקת נטף מרוטבו על החרס וחזר עליו יטול את מקומו. שכל המרק והליחה שתפרוש ממנו כשיצלה אסורה שהרי אינה בשר צלי:\",1,0],[8,368,8,14,\"ומה שכתב רבינו בנטף מרוטבו על הסלת יקלוף את מקומו. בלשון המשנה יקמוץ את מקומו ואיני יודע למה שינה רבינו. ונראה דטעות סופר הוא בספרי רבינו דלא שייך בסלת לשון קליפה:\",2,0],[8,368,8,14,\"ואין צולין שני פסחים כאחד וכו'. ברייתא שם (דף ע\\\"ו) ופירוש מפני התערובת שמא יתחלפו זה בזה ונמצא פסח נאכל שלא למנוייו:\",3,0],[8,368,8,15,\"שאין הפסח נאכל אלא עד חצות וכו' ודין תורה שיאכל כל הלילה וכו'. פרק איזהו מקומן (זבחים דף נ״ו):\",1,0],[8,368,8,15,\"שהוא טעון הלל באכילתו. משנה פרק מי שהיה טמא (פסחים דף צ״ה):\",2,0],[8,368,8,15,\"ושאין בני חבורה וכו'. משנה בסוף פסחים (דף ק\\\"כ) וכרבי יוסי:\",3,0],[8,368,9,1,\"כל האוכל מן הפסח וכו'. בס״פ כיצד צולין (פסחים דף פ״ו) מתניתין מני רבי יהודה היא דתניא על הבתים אשר יאכלו אותו בהם מלמד שהפסח נאכל בשתי חבורות יכול יהא האוכל אוכל בשני מקומות ת״ל בבית אחד יאכל וכו' דברי ר״י ר״ש אומר על הבתים אשר יאכלו אותו בהם מכאן שהפסח נאכל בשני מקומות יכול יהא נאכל בשתי חבורות ת״ל בבית אחד יאכל. ופירש״י על הבתים אשר יאכלו אותו משמע שני בני אדם אוכלים פסח אחד בשני בתים דכתיב יאכלו שנים אותו חד פסח בתים שנים. יכול יהא אדם אחד אוכל ממנו בשני מקומות כגון בשני חדרים או בשתי חבורות ההופכות פניהם ת״ל בבית אחד יאכל ור״י סבר יש אם למסורת כדלקמן יאכל כתיב משמע אדם אחד אוכלו בבית אחד ולא בשני בתים אבל לגבי אוכלים הרבה כתיב בתים הרבה עכ״ל. וידוע דהלכה כר״י. וזהו שכתב רבינו כל האוכל כלומר אדם אחד אינו אוכל אלא בחבורה אחת אבל שנים או יותר יכולים לאכלו כל אחד בחבורה אחת וכתב הר״א בנו של רבינו קשה מ״ש לקמן גבי שתי חבורות שנפרצה מחיצה מביניהם וכו' שאין הפסח נאכל בשתי חבורות דהא כר״ש אתיא ולפיכך כתב שצריך למוחקו ולכתוב במקומו שאין נעקרים מחבורה לחבורה. ובספרים דידן הרכיבו שתי הנוסחאות וכתוב בהם שאין הפסח נאכל בשתי חבורות ואין נעקרים מחבורה לחבורה. ואני אומר שנוסחא דשאין הפסח נאכל בשתי חבורות ל״ק מידי דה״ק מאחר שהתחילו לאכול בחבורה אחת נתחדשה להם חבורה אחרת אם היו אוכלים ונמצא כל יחיד מהם אכל בשתי חבורות וזה אסור לר״י ולא התיר אלא לאכול כל אחד בחבורה אחת לבדה. וגירסת שאין נעקרין מחבורה לחבורה כך היא מתפרשת כמו שפירשתי גירסת שאין הפסח נאכל בשתי חבורות שהרי בסוף פסחים (דף קי״ט:) אהא דתנן אין מפטירין אחר הפסח אפיקומן אמרינן מאי אפיקומן אמר רב שלא יעקרו מחבורה לחבורה ופירשב״ם לא יעקרו וכו' אחר שאכלו הפסח בחבורה לא ילכו בחבורה אחרת לאכול (לא פת) ולא את שום דבר דילמא אתי למיכל פסח בשני מקומות ואנן תנן סתמא כר״י פרק כיצד צולין דפסח נאכל בשתי חבורות ואין האוכל אוכל הפסח בשני מקומות ולא תקשה למה שפירשתי בגירסת שאין הפסח נאכל בשתי חבורות שזהו לשון ר״ש והיאך תפסו לר״י שכבר מצינו כיוצא בזה. ומאחר שביאר רבינו בתחלת הפרק במה הדבר תלוי ממילא משמע שהלשון ע״פ מה שקדם יתפרש:\",1,0],[8,368,9,1,\"והמוציא ממנו כזית בשר מחבורה לחבורה וכו'. בס״פ כיצד צולין (פסחים דף פ״ה).\",2,0],[8,368,9,1,\"ומ\\\"ש והוא שיניחנו בחוץ שהוצאה כתובה בו כשבת לפיכך צריך עקירה והנחה כהוצאת שבת. מימרא דר' אמי שם ע\\\"ב:\",3,0],[8,368,9,1,\"ואין מוציא אחר מוציא בפסח שכיון וכו'. ירושלמי בסוף פרק כיצד צולין ויידא אמר דא יש שובר אחר שובר ואין מוציא אחר מוציא:\",4,0],[8,368,9,1,\"מן האגף ולפנים כלפנים וכו'. משנה בפרק כיצד צולין שם.\",5,0],[8,368,9,1,\"ומ\\\"ש והאגף עצמו כלחוץ. הכי משמע בגמרא שם.\",6,0],[8,368,9,1,\"ומ\\\"ש החלונות ועובי הכותלים כלפנים. שם במשנה.\",7,0],[8,368,9,1,\"ומ\\\"ש הגגים והעליות אינם בכלל בית. מימרא דרב שם:\",8,0],[8,368,9,2,\"בשר הפסח שיצא חוץ לחבורתו וכו' נאסר באכילה וכו'. פשוט הוא.\",1,0],[8,368,9,2,\"ומ\\\"ש כמו שביארנו במעשה הקרבנות. בפי\\\"א. ובספרים כתוב שהכל בשריפה וצריך להגיה ולכתוב שהכל כטריפה:\",2,0],[8,368,9,2,\"אבר שיצא מקצתו חותך עד שמגיע לעצם וכו'. משנה בפרק כיצד צולין שם:\",3,0],[8,368,9,3,\"שתי חבורות שהיו אוכלות בבית אחד וכו'. נראה שלמד כן מדתניא בס\\\"פ כיצד צולין ברייתא שם חוצה תן לה חוצה ואף ע\\\"ג דרש\\\"י כתב דל\\\"ג ליה נראה דרבינו גריס ליה.\",1,0],[8,368,9,3,\"ומ״ש ואלו הופכים את פניהם הילך ואוכלים וכו'. משנה פ' כיצד צולין (פסחים דף פ״ו). ויש לתמוה מאחר שכל חבורה יש לה היקף למה צריכים להפוך פניהם אלו הילך ואלו הילך כדי שלא יראו מעורבים הרי ע״י ההיקף אינם נראים מעורבין. ואפשר לומר דבהיקף כל דהו סגי להו ואע״פ שעדיין רואים אלו את אלו. ואפשר [דמאי] דקאמר היקף לאו מחיצה ממש קאמר אלא למעוטי שלא ישבו אלו כנגד אלו שאז נראים כחבורה אחת אלא אלו הופכים פניהם הילך ואלו הופכים פניהם הילך לזה קורא היקף:\",2,0],[8,368,9,4,\"היו המים שמוזגים בו יינם באמצע הבית וכו'. זהו פירוש רבינו למה ששנינו בפרק כיצד צולין גבי שתי חבורות שהיו אוכלות בבית אחד וכו' והמיחם באמצע כשהשמש עומד למזוג קופץ את פיו מחזיר את פניו עד (שהוא) מגיע אצל חבורתו ואוכל.\",1,0],[8,368,9,4,\"ומה שכתב מותר לכלה להחזיר פניה וכו'. שם במשנה:\",2,0],[8,368,9,5,\"שתי חבורות שנפרצה מחיצה מביניהם וכו'. שם ע\\\"ב היו יושבים ונפרסה מחיצה ביניהם לדברי האומר פסח נאכל בשתי חבורות אוכלים לדברי האומר אין הפסח נאכל בשתי חבורות אין אוכלים היו יושבים ונסתלקה מחיצה מביניהם לדברי האומר האוכל אוכל בב' מקומות אוכלים לדברי האומר אין האוכל אוכל בב' מקומות אין אוכלים יתיב רב כהנא פשיט ליה מיפשט א\\\"ל רב אשי [לרב כהנא] ותיבעי לך איבעי סילוק מחיצה ועשיית מחיצה מי הוי כשני מקומות וכו' או לא תיקו. ופירש\\\"י פשיט ליה מיפשט אומרה לשמועה זו פשוטה ומפורשת כמו שאמרנו שעשיית מחיצה עושה אותן שתי חבורות וסילוק מחיצה עושה אותן ב' מקומות ולא מספקא ליה בה מידי עכ\\\"ל. וכיון דרב אשי מספק בהו פסקו רבינו לחומרא. ומה שיש לדקדק על מ\\\"ש שאין הפסח נאכל בשתי חבורות כתבתי בראש פ' זה:\",1,0],[8,368,9,6,\"בני חבורה שנכנסו ג' מהם וכו'. זהו פירוש מאי דגרסינן בס״פ כיצד צולין (פסחים דף פ״ו:) אמר רב הונא בני חבורה נכנסים בשלשה ויוצאים אפי' באחד אמר רבה והוא דעייל בעידנא דרגילי למיעל והוא דרגש בהו דיילא אמר רבינא ונותנים שכר (דמים) ולית הלכתא כוותיה. והראב״ד פירש בענין אחר וכתב וז״ל א״א סבב פני כל השמועה לענין אחר שאין הדעת מתיישב עליו וכו'. וכך הם דברי רש״י ז״ל אבל דברי רבינו חננאל שכתבו התוס' כדברי רבינו בפירוש נכנסים בשלשה:\",1,0],[8,368,9,6,\"כתב הר\\\"י קורקוס וז\\\"ל מה שמפרש רבינו במה שאמרו יוצאין אפי' אחד הוא דחוק והוא מה שמשיג עליו הראב\\\"ד שאין בו טעם כי מה צורך להודיענו כך ולמה יצטרך להמתין אחד לחבירו כי טעם הכניסה לא שייך כלל ביציאה ולא הל\\\"ל דין היציאה כלל ולדברי רבינו דסד\\\"א כיון שנשתתפו ונתחברו שיכריחו אלו את אלו לישב עד הסוף לצוותא בעלמא שלא ישאר יחידי א\\\"נ כדי שלא יותירו ויביאו לידי נותר קמ\\\"ל שזה אומר לו אם תרצה תסלק ידך גם אתה כי אני לא אמתין, ואפשר שהיוצא אין עליו חיוב נותר כיון שהניח השאר אוכלים ולפי שיטת רבינו דברי רבינא גם דברי רבה אכניסה לחוד קאי דביציאה לא שייך לפלוגי מידי ולא נתינת דמים עכ\\\"ל:\",2,0],[8,368,9,7,\"המאכיל כזית מן הפסח וכו' למומר לע\\\"ז או לגר תושב או לשכיר ה\\\"ז עובר בל\\\"ת. מתבאר בכתוב.\",1,0],[8,368,9,7,\"ומה שכתב בין מפסח ראשון בין מפסח שני. הכי משמע בפ' מי שהיה טמא (פסחים דף צ״ו).\",2,0],[8,368,9,7,\"ומ\\\"ש ובן נכר האמור בתורה זה העובד אל נכר. במכילתא בן נכר אחד ישראל מומר ואחד עכו\\\"ם במשמע ואע\\\"ג דלא כתיב אלא כל בן נכר לא יאכל בו תושב ושכיר לא יאכל משמע לרבינו דלאו לדידהו מזהיר דעכו\\\"ם לא חיישי למאי דמזהיר קרא אלא לישראל מזהיר שלא יאכילום וקרי ביה לא יאכיל ומ\\\"מ כיון דלא כתיב בהדיא לא תאכילום אין לוקין עליו:\",3,0],[8,368,9,7,\"כתב הראב\\\"ד המאכיל כזית מן הפסח וכו' עד תושב ושכיר לא יאכל בו. א\\\"א ואפילו ישראל שאינו ממונה עמו וכו'. י\\\"ל שאם לשאינו ממונה עמו מלפי אכלו תכוסו נפקא וכדפירש\\\"י בס\\\"פ איזהו מקומן. ומ\\\"ש ואין צורך לגר תושב שהוא ערל כלומר דמכל ערל לא יאכל בו נפקא י\\\"ל דאתא לתושב ושכיר שהוא גבעוני או ישמעאלי מהול או לגר שמל ולא טבל כדאיתא בפרק הערל. ועוד דאזהרת ערל אתא לערל ישראל שהוא עצמו מוזהר מלאכול ותושב הערל. ושכיר איצטריך להזהיר לישראל שלא יאכילנו כמו שנתבאר בסמוך:\",4,0],[8,368,9,8,\"ערל שאכל כזית מבשר פסח לוקה וכו' אבל אוכל הוא מצה ומרור. בפרק מי שהיה טמא (פסחים דף צ״ו) דריש ערל לא יאכל בו בו אינו אוכל אבל אוכל הוא מצה ומרור.\",1,0],[8,368,9,8,\"ומ\\\"ש וכן מותר להאכיל מצה ומרור לגר תושב ולשכיר. טעמו משום דדרשא דלא יאכל בו לא נאמר אלא במצה ומרור:\",2,0],[8,368,9,9,\"כשם שמילת בניו ועבדיו מעכבתו וכו' עד סוף הפרק. בפרק הערל (יבמות דף ע'):\",1,0],[8,368,10,2,\"השובר עצם בפסח טהור ה״ז לוקה וכו' אבל בפסח שבא בטומאה וכו'. משנה וגמרא בפרק כיצד צולין (פסחים דף פ״ד):\",1,0],[8,368,10,2,\"אחד השובר את העצם בליל ט\\\"ו וכו'. שם ע\\\"ב פלוגתא דרבי ות\\\"ק ופסק כת\\\"ק.\",2,0],[8,368,10,2,\"ומ\\\"ש או ששבר אחר כמה ימים ה\\\"ז לוקה לפיכך שורפים עצמות הפסח וכו'. שם (דף פ\\\"ג):\",3,0],[8,368,10,3,\"אין חייבין אלא על שבירת עצם וכו'. שם בדף פ\\\"ה:\",1,0],[8,368,10,3,\"ומ\\\"ש היה עליו כזית בשר ושבר העצם שלא במקום הבשר חייב וכו'. שם (דף פ\\\"ד:) פלוגתא דר\\\"י ור\\\"ל ופסק כר\\\"י:\",2,0],[8,368,10,4,\"השובר אחר שובר בעצם אחד לוקה. ירושלמי פרק כיצד צולין בשתי התראות אפי' עצם אחד ושברו וחזר ושברו חייב שתים, ועוד שם בסוף הפרק ויידא אמר יש שובר אחר שובר:\",1,0],[8,368,10,5,\"השורף עצמות והמחתך גידים אינו חייב משום שבירת עצם. שם (דף פ\\\"ד):\",1,0],[8,368,10,6,\"פסח שהוא נא או מבושל וכו'. שם בדף הנזכר.\",1,0],[8,368,10,6,\"ומ\\\"ש אפילו נפסל בטומאה ויציאה וכו' בד\\\"א כשהיתה לו שעת הכושר ונפסל וכו'. גם זה שם פלוגתא דרבי ות\\\"ק בדף הנזכר ופסק כת\\\"ק:\",2,0],[8,368,10,7,\"ומה שכתב שבר עצם האליה אינו לוקה וכו'. גם זה שם פלוגתא דרבי ותנא קמא ופסק כרבי. ויש לתמוה למה בשאר פסק כתנא קמא ובזו פסק כרבי וכבר השיגו הראב\\\"ד. ונראה שטעם רבינו משום דרב אשי דבתרא הוא אמר על שבירת עצם האליה דהא ודאי אינו ראוי לאכילה כלל:\",1,0],[8,368,10,9,\"הסחוסים וכו' עד כגון ראשי כנפיים והסחוסים. זהו פירוש רבינו למה ששנינו בפרק הנזכר כל הנאכל בשור הגדול יאכל בגדי הרך ראשי כנפיים והסחוסים ובגמרא רבה רמי תנן כל הנאכל בשור הגדול יאכל בגדי הרך ושאינו נאכל לא אימא סיפא ראשי כנפיים והסחוסים והא הני לא מתאכלי בשור הגדול ואסיק רבא מה הן קתני והכי קתני כל הנאכל בשור הגדול בשלקא יאכל בגדי הרך בצלי ומה הם ראשי כנפיים והסחוסים ותניא כוותיה. ופירש\\\"י כל הנאכל בשור הגדול וכו' אבל מה שאין נאכל בשור הגדול אין נמנין עליו בפסח אע\\\"פ שעכשיו רך הוא עתיד להקשות בסופו עכ\\\"ל:\",1,0],[8,368,10,9,\"והראב\\\"ד כתב א\\\"א מה נשתנו סברותיו וכו'. ומה שהקשה על רבינו שא\\\"כ הל\\\"ל כל שאינו נאכל בשור הגדול אינו נאכל בגדי הרך אין זה כדאי לסתור פירוש רבינו ואם קושיא זו קושיא גם לפירוש רש\\\"י קשיא. ועוד שלפירוש הראב\\\"ד קשה דלא הל\\\"ל יאכל בגדי הרך דמשמע דמותר לאכלו אלא הכי הל\\\"ל ראוי לאכילה בגדי הרך ולפיכך יש לתמוה למה הפליא להתמיה על פירוש רבינו:\",2,0],[8,368,10,10,\"גידים הרכים שסופן וכו' אין נמנין עליהם. שם:\",1,0],[8,368,10,10,\"ונמנים על מוח שבראש ואין נמנין על מוח וכו'. שם:\",2,0],[8,368,10,11,\"כשאדם אוכל את הפסח חותך הבשר ואוכל וכו': כתב הראב\\\"ד בחיי ראשי אין איסור גדול מזה וכו'. ומ\\\"ש ותרבא דתותי מתנא, י\\\"ל שלא עלה על דעת שרבינו מתיר לצלותו עם חלב האסור מן התורה אלא גיד הנשה שאין בגידין בנ\\\"ט ושמנו שאין בו איסור אלא שישראל קדושים נהגו בו איסור ובפסח לא נהגו כדי שלא יבא לחתך בו אבר אבל חלב האסור מנקרים אותו ואפילו החוטים והקרומות האסורים משום חלב מסירים אותם אע\\\"פ שאין אסורים אלא מדרבנן כמבואר בפ\\\"ח מהמ\\\"א דייקא נמי דקתני שאין מנקין אותו כשאר הבשר דמשמע שמנקין אותו אלא שאינו כשאר בשר.\",1,0],[8,368,10,11,\"ומ\\\"ש והקרומות שאין בהם איסור מיירי דומיא דשאר גידים ועצמות דנקט שאין בהם איסור והראש יושיבנו בית שחיטתו לצד מטה או ינעוץ בחוטמו איזה דבר ויושיב חוטמו לצד מטה ויצא כל דם שבו וקרומות שבראש אינם אלא משום דם ונורא מישאב שייב וכשיפרק עצמות הראש יוציאם ויניחם עם שאר העצמות והגידים. ויש סמך לדברי רבינו מדתניא בפרק [ז' דתוספתא פסחים] נצלה החיצון ולא נצלה הפנימי קולף ואוכל עד שמגיע לנא:\",2,0],[8,368,10,11,\"ואם השאיר ממנו וכו'. מקרא מפורש בפ' בהעלותך.\",3,0],[8,368,10,11,\"ומ״ש ואינו לוקה על לאו זה שהרי ניתק לעשה וכו'. בפ' כיצד צולין (פסחים דף פ״ד) ופ״ק דתמורה (דף י״ד) ופ' ד' מיתות (סנהדרין דף ס״ג) ופ״ק דמכות אמר הכי ר״י ור' יעקב אמר לא מן השם הוא זה אלא משום דה״ל לאו שאין בו מעשה ואין לוקין עליו ואע״ג דקושטא דמלתא היא דלאו שאין בו מעשה אין לוקין עליו נקט רבינו טעמא דר״י לאשמועינן רבותא דאפילו אי הוה ביה מעשה הוה מיפטר מאידך טעמא. ופ״א מהלכות אלו גבי מניח אימורים כ' רבינו טעם דהוי לאו שאין בו מעשה:\",4,0],[8,368,10,12,\"כשמקריבים את הפסח וכו' אימתי מביאין עמו חגיגה זו וכו'. משנה פ' אלו דברים (פסחים דף ס״ט:):\",1,0],[8,368,10,13,\"ומ\\\"ש חגיגת י\\\"ד רשות. שם בגמ'.\",1,0],[8,368,10,13,\"ומ\\\"ש ונאכלת לשני ימים ולילה. משנה שם.\",2,0],[8,368,10,13,\"ומ\\\"ש ואסור להניח מבשר חגיגת י\\\"ד ליום ג' וכו'. שם (דף ע\\\"א).\",3,0],[8,368,10,13,\"ומ״ש והמותיר אינו לוקה. משנה פ' כיצד צולין (פסחים דף פ״ד) והוא מהטעם שנתבאר בסמוך:\",4,0],[8,368,10,14,\"בשר חגיגה שעלה עם הפסח על השלחן וכו'. ירושלמי בפרק אלו דברים וכתבו הראב\\\"ד:\",1,0],[8,368,10,15,\"מה בין פסח ראשון לפסח שני וכו'. משנה פרק מי שהיה טמא (פסחים דף צ״ה).\",1,0],[8,368,10,15,\"ומ\\\"ש ומוציאין אותו חוץ לבית אכילתו. יש לתמוה על זה דהא תניא התם בגמ' ככל חקת הפסח יעשו אותו יכול כשם שהראשון אסור בבל יראה ובל ימצא כך שני אסור וכו' ת\\\"ל וכו' בכלליה דלא ישאירו ממנו עד בקר מאי קא מרבה ליה לא תוציאו ממנו דדמי ליה דהאי מיפסיל בנותר והאי מיפסיל ביוצא, וא\\\"כ קשה היכי ממעט רבינו יוצא, וי\\\"ל דבגמ' קאמר דמרבי ליה משום דדמי ליה דהוי לאו שניתק לעשה דומיא דנותר. ופירש\\\"י דלית ליה להאי תנא הא דתניא בפ' כיצד צולין האוכלו ה\\\"ז בלא תעשה דובשר בשדה טריפה אלא מותר להחזירו ולאכלו עכ\\\"ל. ומאחר דקי\\\"ל כההוא תנא דמוציא חייב משום ובשר בשדה טריפה תו ליכא לרבויי יוצא מנותר שזה ניתק לעשה וזה לא ניתק לעשה.\",2,0],[8,368,10,15,\"ומ\\\"ש ואין מביאין עמו חגיגה. תוספתא פ\\\"ח.\",3,0],[8,368,10,15,\"ומ\\\"ש ומוציאין אותו חוץ לבית אכילתו. נראה דט\\\"ס יש כאן וצריך למוחקו ולכתוב במקומו ומוציאין אותו חוץ לחבורתו כעין מ\\\"ש ברישא גבי פסח ראשון אין מוציאין ממנו חוץ לחבורה.\",4,0],[8,368,10,15,\"ומ״ש ואינו בא בטומאה וכו' עד על מצה ומרור. במשנה פ' מי שהיה טמא (פסחים דף צ״ה).\",5,0],[8,368,10,15,\"ומ\\\"ש ואין מותירים מהם ואין שוברים בהן את העצם. מקרא מפורש בפרשת בהעלותך.\",6,0],[8,368,10,15,\"ומ\\\"ש ולמה לא ישוה השני לראשון לכל הדברים וכו'. שם בגמ':\",7,0],[8,368,10,15,\"שכלל זה שנאמר במצרים וכו' אין אותם דברים נוהגים לדורות וכו'. משנה בפ' מי שהיה טמא (פסחים דף צ״ו):\",8,0],[8,368,10,15,\"סליקו הלכות קרבן פסח בס\\\"ד\",9,0],[8,369,1,1,\"שלש מצות עשה נצטוו ישראל בכל רגל וכו'. בפ\\\"ק דחגיגה (דף ו':):\",1,0],[8,369,1,1,\"הראייה האמורה בתורה וכו'. בפ\\\"ק דחגיגה (דף ז') מאי הראיון ר\\\"י אמר ראיית פנים בעזרה ור\\\"ל אמר ראיית פנים בקרבן בעיקר הרגל כ\\\"ע לא פליגי דראיית פנים בקרבן כי פליגי בשאר ימות הרגל. ופירש\\\"י עיקר הרגל ביו\\\"ט ראשון.\",2,0],[8,369,1,1,\"ומ\\\"ש ויביא עמו קרבן עולה. מבואר שם.\",3,0],[8,369,1,1,\"ומ\\\"ש בין מן העוף בין מן הבהמה. יש לתמוה על זה דהא תניא בפ\\\"ק דחגיגה (דף ו') לא יראו פני ריקם בזבחים אתה אומר בזבחים או אינו אלא בעופות ומנחות ודין הוא וכו' אף ראייה האמורה לגבוה זבחים ומה הן זבחים עולות. ופירש\\\"י בזבחים צריך להביא קרבן בהמה הזבוחים בסכין ולא עולת עוף שהיא נמלקת מה חגיגה האמורה להדיוט זבחים של בהמה דכתיב לא ילין חלב חגי עד בקר במידי דאית ליה חלב הקרב לגבוה קאמר עכ\\\"ל. והיאך כתב רבינו בין מן העוף. וכתב הר\\\"י קורקוס ז\\\"ל שבמקום או אינו אלא בעופות היה גורס רבינו או אינו אלא במנחות או היה גורס או אינו אלא בכספים כמו שהיא שנויה במכילתא ומשמע ליה דעופות בכלל זבחים הם:\",4,0],[8,369,1,1,\"ומי שבא לעזרה ולא הביא וכו': החגיגה האמורה בתורה וכו'. מבואר בפ\\\"ק דחגיגה שם.\",5,0],[8,369,1,1,\"ומ\\\"ש והדבר ידוע שאין שלמים באים אלא מן הבהמה. פשוט הוא:\",6,0],[8,369,1,1,\"ושתי מצוות אלו וכו'. פשוט הוא דמ\\\"ע שהזמן גרמא הן ועוד דבראייה כתיב יראה כל זכורך. ובפ\\\"ק דחגיגה (דף ו':) תניא ג' מצוות נצטוו ישראל בעלותם לרגל ראייה וחגיגה ושמחה וכו' יש בשמחה מה שאין בשתיהם שהשמחה נוהגת באנשים ובנשים משא\\\"כ בשתיהן. ופירש\\\"י השמחה נוהגת בנשים דכתיב ושמחת אתה וביתך. משא\\\"כ בשתיהם דמ\\\"ע שהזמן גרמא הן והכתוב לא ריבה אותן:\",7,0],[8,369,1,1,\"והשמחה האמורה ברגלים וכו' שנאמר וזבחת שלמים וכו'. פסוק זה אינו כתוב בחג אלא על גבי הר עיבל בפרשת כי תבא ולא כתבו רבינו אלא ללמוד משם דסתם שמחה הוי בזביחת שלמים ומינה דושמחת בחגך היינו בזביחת שלמים וכו'. ובגמ' פ' ע\\\"פ (דף ק\\\"ט) תניא בזמן שב\\\"ה קיים אין שמחה אלא בבשר שנאמר וזבחת שלמים וכו'.\",8,0],[8,369,1,1,\"ומ\\\"ש ונשים חייבות במצוה זו. נתבאר בסמוך ואיתא נמי בפ\\\"ק דקידושין (דף ל\\\"ד:):\",9,0],[8,369,1,1,\"וכתב הראב\\\"ד ונשים חייבות במצוה זו א\\\"א לא בקרבן וכו'. ודבריו מבוארים בפ\\\"ק דקידושין דמקשה דנילף למ\\\"ע שהזמן גרמא לחיובא באשה משמחה ומשני אביי אשה בעלה משמחה אלמנה מאי איכא למימר בשרויה אצלו. ופירש\\\"י בעלה משמחה אין חובת השמחה תלויה בה אלא על בעלה שישמחנה קרי ביה ושימחת. אלמנה מאי איכא למימר הא כתיב בה שמחה דכתיב והגר והיתום והאלמנה. בשרויה אצלו לא נצטוית היא אלא בעניה הכתוב מדבר ונצטוה מי שהיא שרויה אצלו לשמחה משלו. וכתבו התוס' מפר\\\"ת אשה בעלה משמחה בשלמי שמחה שלו שהחובה מוטלת על בעלה ובאלמנה על ששרויה אצלו אבל היא גופא לא מיחייבא לאיתויי שלמי שמחה עכ\\\"ל. ואין תפיסה על רבינו למה לא האריך לבאר זה:\",10,0],[8,369,1,2,\"הראייה והחגיגה אין להם שיעור מן התורה. הראייה משנה בראש מס' פאה ומייתי לה פ\\\"ק דחגיגה.\",1,0],[8,369,1,2,\"ומ\\\"ש אבל מד\\\"ס שלא יהא קרבן עולת ראייה פחות משוה מעה כסף ולא שלמי חגיגה פחות משוה שתי כסף. שם בברייתא (דף ז') ואיתא נמי בפ' הנזכר במשנה פלוגתא דב\\\"ש וב\\\"ה ופסק כב\\\"ה.\",2,0],[8,369,1,2,\"ומ\\\"ש ומצוה להביא כפי עשרו וכו'. משנה שם (דף ח':):\",3,0],[8,369,1,3,\"שלמי שמחה לא נתנו להם חכמים שיעור וכו'. בעת שיעלה אדם לירושלים לחוג וכו' לא יביא שוה כסף וכו'. בפרק יש בכור (בכורות דף נ״א) וכפירוש התוספות:\",1,0],[8,369,1,4,\"מי שלא הקריב ביו\\\"ט הראשון וכו'. בפ\\\"ק דחגיגה (דף ט').\",1,0],[8,369,1,4,\"ומ\\\"ש וכולם תשלומי ראשון הם. שם ופסק כרבי יוחנן לגבי רבי אושעיא ויש לתמוה על זה דהא רבי אושעיא גדול מר\\\"י דרביה הוה:\",2,0],[8,369,1,5,\"ומ\\\"ש ומצוה להקדים ולהקריב בראשון וכו'. פשוט הוא ממה שנתבאר בסמוך.\",1,0],[8,369,1,5,\"ומ\\\"ש וכל המאחר הרי זה מגונה ועליו נאמר נוגי ממועד אספתי:\",2,0],[8,369,1,6,\"ומ\\\"ש עבר הרגל ולא חג אינו חייב באחריותו ועל זה וכיוצא בו נאמר מעוות לא יוכל לתקון. משנה פ\\\"ק דחגיגה שם:\",1,0],[8,369,1,7,\"מי שלא חג ביום טוב הראשון וכו'. שם במשנה.\",1,0],[8,369,1,7,\"ומה שכתב וכן מי שלא חג ביום חג השבועות חוגג כל שבעה וכו'. בפרק אלו מגלחין (מועד קטן דף כ״ד:) ובפ״ב דחגיגה (דף כ״ז):\",2,0],[8,369,1,8,\"עולת ראיה ושלמי חגיגה וכו'. דין חגיגה משנה בפרק אלו דברים (פסחים דף ס״ט ע״ב) ובפרק כיצד צולין (פסחים דף ע״ז ע״ב) ועולת ראייה ילפא מינה כיון דשייך בה טעמא דידה:\",1,0],[8,369,1,8,\"ואף על פי שאין מקריבין ביום טוב וכו'. בפרק ב' דביצה (דף י\\\"ט) ובפ\\\"ב דחגיגה (דף י\\\"ז) פלוגתא דב\\\"ש וב\\\"ה ופסק כב\\\"ה:\",2,0],[8,369,1,9,\"ומ\\\"ש כשמקריב המקריב עולת ראייתו וכו' סומך עליה. שם כב\\\"ה.\",1,0],[8,369,1,9,\"ומ\\\"ש בכל כחו. בפ\\\"ב דחגיגה (דף ט\\\"ז:):\",2,0],[8,369,1,10,\"המפריש עולת ראייתו וכו'. פרק יש בכור נקיט לה בפשיטות על מתניתין דמת לאחר שלשים יום ואיתא בירושלמי בפרק קמא דחגיגה אלא ששם אמרו שאם ירשו קרקע אפילו לא הפרישה חייבים יורשים להביאה ולא ידעתי למה השמיטו רבינו:\",1,0],[8,369,1,10,\"מותר להקריב בחולו של מועד נדרים ונדבות וכו'. ריש פרק ב' דתמורה (דף י\\\"ד) ובפרק קמא דחגיגה (דף ז'):\",2,0],[8,369,1,11,\"מי שהיו לו אוכלים מרובין וכו' עד סוף הפרק. משנה פ\\\"ק דחגיגה (דף ח':):\",1,0],[8,369,2,1,\"נשים ועבדים פטורים מן הראיה וכו' עד מפני שהם ספק אשה. משנה וגמ' בריש חגיגה.\",1,0],[8,369,2,1,\"ומ\\\"ש ומי שחציו עבד וחציו ב\\\"ח פטור וכו'. שם הכל חייבים בראייה לאיתויי חציו עבד וחציו בן חורין ולרבינא דאמר וכו' פטור וכו' ל\\\"ק כאן כמשנה ראשונה כאן כמשנה אחרונה. ופי' רש\\\"י משנה אחרונה לאחר שהודו ב\\\"ה לב\\\"ש שיש על ב\\\"ד לכוף את אדונו לשחררו ה\\\"ל כאילו משוחרר כבר וחייב. ועל פי פירוש זה כתב הראב\\\"ד על דברי רבינו הא דלא כהלכתא דהיא כמשנה ראשונה עכ\\\"ל. ובפ\\\"ב מקרבן פסח כתבתי ליישב דברי רבינו:\",2,0],[8,369,2,1,\"ומנין שכל אלו פטורים מן הראיה וכו'. שם חוץ ממ\\\"ש ועוד הרי נאמר בבוא כל ישראל להוציא העבדים:\",3,0],[8,369,2,2,\"המקמץ וכן המצרף נחשת במחצב שלו והעבדנין וכו'. שם (דף ד') בברייתא אחרים אומרים המקמץ והמצרף נחשת והבורסי פטורים מן הראייה שנאמר כל זכורך יצאו אלו שאינן ראויים לעלות עם כל זכורך כלומר מפני שריחן רע. ומשמע לרבינו דכיון דבלשון אחרים מיתניא משמע דרבנן פליגי עלייהו ומחייבי ונקטינן כוותייהו ואע\\\"ג דבגמ' אמרינן ואלא קרא למאי אתא לכדאחרים לא מכרעא מילתא דליהוי הלכתא כוותייהו דאיכא למימר דרבנן דפליגי עלייהו דרשי ליה לדרשא אחריתי. והר\\\"י קורקוס ז\\\"ל כתב דאחרים לא ממעטי להו אלא בעודם במאיסותם מפני שאינם יכולים לעלות עם כל זכורך אבל כשיטהרו מלבושיהם הרי הם כשאר כל אדם:\",1,0],[8,369,2,3,\"כל קטן שיכול לאחוז בידו של אביו וכו'. שם.\",1,0],[8,369,2,3,\"ומה שכתב ואם היה הקטן חגר וכו' אף על פי שהוא ראוי לרפואה וכו'. שם (דף ו') בעיא דאיפשיטא:\",2,0],[8,369,2,4,\"כל החייב בראייה חייב בחגיגה וכו'. הכי משמע בפ\\\"ק דחגיגה (דף ו') גבי הא דתניא ר\\\"י הגלילי אומר שלש מצות נצטוו ישראל בעלייתן לרגל (ובדף ב'):\",1,0],[8,369,2,5,\"מי שהיה חגר או סומא ביום ראשון וכו'. שם (בדף ט') פלוגתא דאמוראי ופסק כר\\\"י.\",1,0],[8,369,2,5,\"ומ\\\"ש וכן אם נטמא בלילי יו\\\"ט הראשון וכו'. שם ומי אמר ר\\\"י הכי והאמר חזקיה נטמא ביום מביא בלילה אינו מביא ור\\\"י אמר אף בלילה נמי מביא וכו' קסבר ר' יוחנן לילה אינו מחוסר זמן. ופירש רש\\\"י נטמא ביום גבי נזיר מביא קרבן אחד על טומאות הרבה וכו' אלמא אע\\\"ג דלא נראה לקרבן יש לו תשלומין. קסבר ר\\\"י אין חסרון זמן במי שהגיע לילו להקריב קרבנותיו מחר הילכך מחוייב הוא בקרבן אלא שהלילה מעכבו מלהביא אבל חגר ביום ראשון אין עליו שום חובת ראייה לפיכך אין לו עליו תשלומין עכ\\\"ל. ומכאן נלמוד דלחזקיה אם נטמא בליל יו\\\"ט הראשון שהוא פטור כיון דכשהאיר יו\\\"ט הראשון היה פטור ואע\\\"ג שיטבול בו ביום אינו מיטהר עד שיעריב שמשו אבל אם נטמא ביו\\\"ט הראשון חייב כיון דכשהאיר יו\\\"ט הראשון היה חייב:\",2,0],[8,369,2,6,\"מי שבא לעזרה בתוך ימי החג וכו'. שם (דף ז') פלוגתא דר\\\"י ור\\\"ל ופסק כר\\\"י. ודע דאיתא התם איתיביה ר\\\"י לר\\\"ל יראה יראה מה אני בחנם אף אתם בחנם אלא כל היכא דאתא ולא אייתי כ\\\"ע לא פליגי דעייל ומתחזי ונפיק כי פליגי דאתא ואייתי ר\\\"י אמר וכו' ראיית פנים הוא דאין לה שיעור הא לקרבן יש לו שיעור ור\\\"ל אמר וכו' אפי' קרבן אין לו שיעור. ורבנו לא חש להאי לישנא משום דכיון דלא אתמר בגמ' אלא כי היכי דלא תיקשי מאי דמשמע לן במילתיה דר\\\"ל לא חיישינן לה ונקטינן כלישנא קמא שהוא מאי דמשתמע טפי כפשטא דמילתייהו. ועי\\\"ל שהוא מפרש דיש שיעור לקרבן דלישנא בתרא לא בשיעור פעמים שהוא מביא מיירי דכל פעמים שהוא רוצה להביא קרבן מביא אלא בשיעור דמי הקרבן קאמר שלא יהא פחות דראייה מעה כסף וחגיגה שתי כסף ולא יפרש רבינו פלוגתא דר\\\"י ור\\\"ל כדפירש\\\"י אלא כמו שפירשו התוס' בשם הירושלמי:\",1,0],[8,369,2,7,\"הפריש עשר בהמות לחגיגתו וכו'. בפ\\\"ק דחגיגה (דף ח':) ודברי רבינו אע\\\"פ שהם סתומים נראה לפרשם כפירוש ר\\\"ח שכתבו התוס' שם:\",1,0],[8,369,2,8,\"עולת ראיה אינה באה אלא מן החולין וכו'. משנה וגמרא פ\\\"ק דחגיגה (דף ז':).\",1,0],[8,369,2,8,\"ומ\\\"ש אבל שלמי חגיגה באות ממעות מעשר שני המעורבות עם מעות חולין וכו'. שם (דף ח') ואיתיה בירושלמי פרק קמא דפיאה וכר\\\"י. וצריך טעם למה לא פסק כחזקיה רביה דפליג עליה. ונראה שהטעם משום דברייתא דמסייע לר\\\"י עדיפא דמייתי לה מקרא ועוד דלטפול מעות למעות ה\\\"ל חזקיה יחידאה דהא רב חסדא ורב ששת ס\\\"ל כר\\\"י דטופלין מעות למעות. ולומר דאף טופלין בהמה לבהמה ה\\\"ל רב ששת יחידאה דליכא שום אמורא דליסבר כוותיה.\",2,0],[8,369,2,8,\"ומ\\\"ש והוא שיהיה שיעור אכילה ראשונה מן החולין. נלמד מברייתא הובאה שם ואע\\\"פ שהובאה לסייע לחזקיה דפליג אר\\\"י שפיר ילפינן מינה הא מילתא לדידן דקי\\\"ל כר\\\"י:\",3,0],[8,369,2,8,\"וכתב הראב\\\"ד א\\\"א זה הכל שיבוש דשלמי חגיגה נמי אינה באה אלא מן החולין וכו'. ואני שמעתי ולא אבין דהא לד\\\"ה יש חילוק בין עולת ראייה לשלמי חגיגה דעולת ראייה צריך שתהא כולה מן החולין ולא יהא שום תערובת מעשר לא בטופל בהמה לבהמה ולא בטופל מעות למעות אבל שלמי חגיגה מותר לטפול מעשר וחולין למר טופל מעות למעות ולמר טופל בהמה לבהמה וא\\\"כ מה זה שכתב הראב\\\"ד דשלמי חגיגה נמי אינה באה דלא הכי היא וכדאמרן ורבינו פוסק כמ\\\"ד טופל מעות למעות אבל לא בהמה לבהמה ומה ז\\\"ש ולמ\\\"ד טופלין בהמה לבהמה אפשר שטופלין בהמת מעשר וכו' אבל למ\\\"ד אין טופלין בהמה לבהמה לא משכחת לה. דמשמע מדבריו שרבינו סובר שטופלים בהמה לבהמה כמבואר בדבריו. ומ\\\"ש אבל לא ביו\\\"ט חוששין שמא יעשר ביו\\\"ט איני יודע למה הוצרך לכתבו ועוד שרבינו כבר כתב דין זה. והר\\\"י קורקוס ז\\\"ל כתב ביאור דברי הראב\\\"ד נראה שסובר דלעולם בשלמי חגיגה מיירי ברייתא אבל בטופל הוא דקאמר דבשאר הימים מותר לטפול לשלמי חגיגה אבל לא ביו\\\"ט שמא יעשר ולמ\\\"ד אין טופלין בהמה לבהמה לא משכחת לה דין זה ולסיועי לחזקיה מייתי לה התם וקשה לרבינו שכתב שיוצא ידי חובת שלמי חגיגה במעשר בהמה והלא חולין בעינן ומאי שנא מעשר בהמה ממעות מעשר שני דלא נפיק אלא בטופל והלא גם מעשר בהמה אינם חולין. זו כוונת השגת הראב\\\"ד. ואפשר שגם רבינו בטופל מיירי ולומר שיכול להביא הכל לשם חגיגה אע\\\"פ שלא פירש ונסמך על מ\\\"ש למעלה. ומ\\\"מ לשון יוצא י\\\"ח שכתב רבינו דחוק לפי זה אלא דרבינו לשון הברייתא הוא דנקט עכ\\\"ל והאריך עוד:\",4,0],[8,369,2,9,\"ומ\\\"ש רבינו ויוצא אדם י\\\"ח שלמי חגיגה במעשר בהמה ואין מביאין אותו ביו\\\"ט וכו'. שם בדף הנזכר:\",1,0],[8,369,2,10,\"יוצאין ישראל י\\\"ח שלמי שמחה בנדרים ונדבות וכו' עד שאינם בשר המשמח. משנה שם (דף ז':):\",1,0],[8,369,2,10,\"כבר ביארנו בפסחים וכו' אלא יוצא בה י״ח שמחה. בפ' אלו דברים (פסחים דף ע') אמתני' דתנן נאכלת לשני ימים ולילה אחד מתני' דלא כבן תימא דתניא בן תימא אומר חגיגה הבאה עם הפסח הרי היא כפסח ואינה נאכלת אלא ליום ולילה וחגיגת חמשה עשר נאכלת לשני ימים ולילה אחד וחגיגת י״ד יוצא בה משום שמחה ואינו יוצא בה משום חגיגה. והראב״ד כתב על דברי רבינו איני יודע מאי לפיכך וכו'. ובאמת שלשון לפיכך קשה דמשמע דמשום שהיא רשות יוצא בה י״ח שמחה שאם היתה חובה לא היה יוצא בה י״ח שמחה. ומה שהקשה דאותה ברייתא כבן תימא וכו' י״ל שסובר רבינו דלא פליגי רבנן אבן תימא אלא במאי דאמר דאינה נאכלת אלא ליום ולילה אבל מאי דקתני יוצא בה משום שמחה ואינו יוצא בה משום חגיגה דברי הכל היא. ומ״ש הראב״ד דלבן תימא היא חובה אינו מוכרח דהא טעמיה דאינו נאכל אלא ליום ולילה אמרי' בגמ' דהוי משום דהקישה הכתוב לפסח ואין במשמע זה שתהא חובה אלא ה״ק אם רצה להביא חגיגה דינה כפסח:\",2,0],[8,369,2,12,\"מי שהיו לו שלמי וכו' שא\\\"צ לשחוט שלמי שמחה בשעת שמחה. שם (בדף ע\\\"א) פלוגתא דאמוראי ופסק כרבין משום דרב יוסף ורבה אקשו לעולא משמע דלא ס\\\"ל כוותיה ותו דאשינויי דחיקי לא סמכינן:\",1,0],[8,369,2,13,\"לא יביא אדם תודה ביום י\\\"ד וכו'. בפ\\\"ב דביצה (דף י\\\"ט:).\",1,0],[8,369,2,13,\"ועל מ\\\"ש ואם הביא יוצא בה י\\\"ח שמחה. הקשה הר\\\"י קורקוס ז\\\"ל דהא תודה אינה נאכלת אלא ליום ולילה ואם כן תודה זו ששחטה ע\\\"פ איך יוצא בה ידי שמחה הא איפסילא בלינה ואין לומר דיוצא ידי שמחת לילה קאמר שלא מצינו שיהא חייב בשמחה בלילה הראשון שאם כן יהא חייב לשחוט שלמי שמחה בערב הרגל לשמוח בלילה והאריך ובסוף העלה דלאו אשחטה בע\\\"פ קאי אלא אם הביא במועד קאמר כי בכלל מ\\\"ש לא בעיו\\\"ט כ\\\"ש במועד וה\\\"ק ואם הביא בזמן שחייב בשמחה יוצא י\\\"ח שמחה:\",2,0],[8,369,2,14,\"האומר הרי עלי תודה וכו'. שם בדף הנזכר בעיא דאיפשיטא. וגי' רבינו שאצא בה ואעפ״כ אינו יוצא בה דכיון שאמר הרי עלי תודה נתחייב בתודה וכי הדר אמר שאצא בה י״ח חגיגה לאו כל כמיניה דוגמא לדבר מה ששנינו בפרק התודה (מנחות דף פ״א) האומר הרי וכו' תודה עלי מן החולין ולחמה מן המעשר יביא היא ולחמה מן החולין ובזה נסתלקה השגת הראב״ד שכתב א״א בספרים שלנו וכו':\",1,0],[8,369,2,14,\"כשיזבח אדם שלמי חגיגה ושלמי שמחה לא וכו': ומצוה בלוי יותר מן הכל וכו':\",2,0],[8,369,3,1,\"מצות עשה להקהיל כל ישראל וכו'. מפורש בתורה פרשת וילך ואיתא בפ\\\"ק דחגיגה (דף ג') טף למה:\",1,0],[8,369,3,2,\"כל הפטור מן הראייה פטור ממצות הקהל וכו'. שם:\",1,0],[8,369,3,3,\"אימתי היו קורין במוצאי וכו' עד בלשון הקדש. משנה בפרק אלו נאמרים (סוטה דף מ״א):\",1,0],[8,369,3,4,\"ומה שכתב תוקעים בחצוצרות. בתוספתא דסוטה פרק שביעי:\",1,0],[8,369,3,5,\"הקריאה והברכות בלשון הקדש וכו'. בפ' אלו נאמרים (סוטה דף ל״ב) תנן דפרשת המלך נאמרה בלשון הקדש.\",1,0],[8,369,3,5,\"ומה שכתב שגם הברכות נאמרים בלה\\\"ק וכו': אע\\\"פ שיש שם לועזות וכו':\",2,0],[8,369,3,7,\"יום הקהל שחל להיות בשבת וכו'. משנה [וגמרא] בפ\\\"ק דמגילה (דף ה').\",1,0],[8,369,3,7,\"ומ\\\"ש מפני תקיעת חצוצרות וכו'. [ירו' פ\\\"ק דמגילה]:\",2,0],[8,369,3,7,\"כתב הראב\\\"ד שאינן דוחין את השבת א\\\"א ואפילו יום טוב אינו דוחה וכו'. וי\\\"ל דההיא דירושלמי אינה עניין לדרבינו שבירושלמי (שם) באו ליתן טעם למה אין עושים יום הקהל ביו\\\"ט עצמו ונתנו טעם מפני הבימה שא\\\"א לעשותה ביו\\\"ט וגם מעי\\\"ט א\\\"א לעשותה שלא לדחוק העזרה ורבינו בא ליתן טעם למה כשחל מוצאי יו\\\"ט הראשון בשבת למה מאחרין אותו עד לאחר השבת שמפני דוחק העזרה לא ה\\\"ל לדחותו שני ימים ונתן טעם מיוחד לזה מפני התקיעות והתחינות שאינם דוחים את השבת אבל אילו היו עושים אותו ביו\\\"ט לא היו נאסרים התקיעות והתחינות מפני שהם דברים מיוחדים לעשות בו ביום דבחג הסוכות אמר רחמנא ואפילו ביו\\\"ט. ועי\\\"ל דהכי איתא בירושלמי ובהקהל רבי בא אמר מפני התקיעה ר' יצחק אמר מפני הבימה ויעשו אותם מאתמול שלא לדחוק את העזרה. ומעתה יש לתמוה על הראב\\\"ד היאך משיג על רבינו מהירושלמי מאחר שדברי רבינו ג\\\"כ הם בירושלמי לדעת אחד מהאמוראים ולא עוד אלא שאפשר שר' יצחק לא לחלוק על ר' בא אתא אלא להוסיף ולומר שעוד יש טעם אחר בדבר:\",3,0],[8,369,3,7,\"סליקו הלכות חגיגה בס\\\"ד\",4,0],[8,370,1,1,\"מצות עשה להפריש כל פטר רחם הזכרים וכו'. מפורש בתורה פ' בא אל פרעה ופ' ראה.\",1,0],[8,370,1,1,\"ומ\\\"ש בין שהיו טריפות:\",2,0],[8,370,1,2,\"ומ\\\"ש ופדיונם לכהנים. בפרק רביעי דחלה (משנה ט').\",1,0],[8,370,1,2,\"ומה שכתב ובכור בהמה טהורה נשחט בעזרה וכו'. משנה בפ' איזהו מקומן (זבחים דף נ״ו:):\",2,0],[8,370,1,3,\"בכור בהמה טהורה שהוא בעל מום וכו'. פשוט בכמה מקומות מהם סוף פ' איזהו מקומן (זבחים דף נ״ז) ובפ' ב״ש:\",1,0],[8,370,1,3,\"ומ\\\"ש אם רצה אוכלו בכ\\\"מ. דע\\\"כ לא שנינו בס\\\"פ איזהו מקומן שהבכור נאכל בכל העיר אלא בתם אבל בעל מום נאכל בכל מקום.\",2,0],[8,370,1,3,\"ומ\\\"ש או מוכרו. בריש מעשר שני (משנה ב').\",3,0],[8,370,1,3,\"ומ\\\"ש או מאכילו למי שירצה אפי' לנכרי. במשנה פ\\\"ה דבכורות (דף לב:) פלוגתא דתנאי ופסק כב\\\"ה.\",4,0],[8,370,1,3,\"ומ\\\"ש והרי הוא נכסי כהן. רפ\\\"ב דבכורים תנן דבכורים נכסי כהן ומשמע לרבינו דבכור בכלל בכורים הוא ובסוף מסכת בכורים (פ\\\"ג מי\\\"ב) תנן ולמה אמרו הבכורים כנכסי כהן שהוא קונה מהם עבדים וקרקעות ובהמה טמאה וב\\\"ח נוטלם בחובו ואשה בכתובתה:\",5,0],[8,370,1,4,\"מצוה להקדיש בכור בהמה טהורה וכו'. בסוף המקדיש שדהו (דף נ\\\"ט.):\",1,0],[8,370,1,5,\"מצות בכור בהמה טהורה נוהגת בארץ ובח״ל. כך היא הנוסחא האמיתית והכי משמע בסוף פ״ג דתמורה (דף כ״א) ובפ' אלו טריפות (חולין דף מ״ד:) אמרינן דאמרה ליה בת רב חסדא לרבא אבא שרי בוכרא ולא זבן מיניה בשרא ובפ' קמא דבכורות (דף ג':) רב מרי בר רחל ה״ל ההיא חיותא דהוה מקני לאודנייהו לנכרי ובפרק אין צדין (ביצה דף כ״ז:) ההוא גברא דאייתי בוכרא קמיה דרבא:\",1,0],[8,370,1,5,\"ומ\\\"ש ואין מביאין בכורות מח\\\"ל שנאמר ואכלת לפני ה' אלהיך וגו' אלא יאכל במומו ואם הביא אין מקבלין ממנו ולא יקרב אלא יאכל במומו. בספ\\\"ג דתמורה (דף כ\\\"א) פלוגתא דתנאי ופסק כר\\\"ע. ודע שבספרי רבינו היה כתוב מצות בכור בהמה טהורה אינה נוהגת אלא בארץ וע\\\"פ זה השיגו הראב\\\"ד וכתב טעות היא זו גם הרמב\\\"ן בהל' בכורות תמה עליו והקשה עליו כמה קושיות וכן הרשב\\\"א והר\\\"ן בתשובה וכולם ספר מוטעה נזדמן להם בדברי רבינו והגירסא שכתבתי בדבריו היא הכתובה בספרינו והיא הנוסחא האמיתית:\",2,0],[8,370,1,6,\"ומצוה זו נוהגת וכו'. בסוף שקלים (פ\\\"ח מ\\\"ח) ובפירקא בתרא דבכורות (דף נ\\\"ג) והכי איכא למילף מהנך שהבאתי גבי נוהגת בח\\\"ל.\",1,0],[8,370,1,6,\"ומ״ש ואינה נוהגת במוקדשין כשהן בקדושתן קודם שיפדו בין קדשי מזבח בין קדשי בדק הבית. משנה בפ' הזרוע (חולין דף ק״ל) ופ״ב דבכורות (דף י״ד). ודע ששנינו במשנה הנזכרת דהא דאמרינן דקודם שיפדו פטורים מן הבכורה הא אחר שנפדו חייבים ה״מ בשקדם מום קבוע להקדשן אבל אם קדם הקדשן את מומן או מום עובר להקדשן ולאחר מכאן נולד להם מום קבוע להקדשן אפי' אחר שנפדו פטורים מן הבכורה וביאר זה רבינו בפ' ה':\",2,0],[8,370,1,7,\"הכל חייבים בבכורה כהנים וכו'. משנה בפ\\\"ב דבכורות (דף י\\\"ג).\",1,0],[8,370,1,7,\"ומ\\\"ש ואע\\\"פ שהבכור לכהן אם נולד לו בכור מקריב דמו ואימוריו וכו'. פשוט הוא ע\\\"פ מה שנתבאר שהכהנים חייבים.\",2,0],[8,370,1,7,\"ומ\\\"ש אבל בכור אדם ובכור בהמה טמאה כהנים ולוים פטורין. משנה בפ\\\"ק (דף ד') ופ\\\"ב דבכורות (דף י\\\"ג):\",3,0],[8,370,1,8,\"הבכור נאכל בתוך שנתו וכו'. משנה בפ' עד כמה (בכורות דף כ״ו:).\",1,0],[8,370,1,8,\"ומה שכתב מאימתי מונה לו וכו' עד אבל אם לא ידע בודאי שכלו לו חדשיו מונה לו מיום שמיני. בפ\\\"ק דר\\\"ה (דף ו' ז'):\",2,0],[8,370,1,9,\"נולד לו מום בתוך שנתו וכו'. משנה בפרק עד כמה (בכורות דף כ״ח:).\",1,0],[8,370,1,9,\"ומה שכתב נולד לו מום בסוף שנתו וכו'. שם בדף כ\\\"ח.\",2,0],[8,370,1,9,\"וומה שכתב נולד לו מום אחר שנתו וכו'. משנה שם:\",3,0],[8,370,1,11,\"הבכור בזמן הזה וכו' עד מקיימו שלשים יום. שם:\",1,0],[8,370,1,11,\"מצאתי כתוב ועד שלא נראה לחכם רשאי לקיימו. כן הוא לשון הברייתא ופירושו חייב לקיימו דהא כל עוד שלא נפל בו מום א\\\"א לשחטו וע\\\"כ יקיימנו ואטו דתנא סיפא אם נולד לו מום וכו' רשאי תנא ברישא רשאי עכ\\\"ל. והתוס' כתבו שפירוש זה דחוק:\",2,0],[8,370,1,12,\"שנה של בכור היא שנת לבנה תמימה וכו'. פרק קמא דר\\\"ה (דף י\\\"ז) ופ\\\"ה דערכין (דף ל\\\"א) פלוגתא דתנאי ופסק כחכמים:\",1,0],[8,370,1,12,\"נולדו לו שני טלאים וכו'. מימרא פ\\\"ק דערכין (דף ל\\\"א:):\",2,0],[8,370,1,13,\"עבר ואיחר הבכור לאחר שנתו וכו' עד משנה לחבירתה. פרק קמא דר\\\"ה (דף ה':):\",1,0],[8,370,1,15,\"אין נותנין את הבכור לכהן כשיולד וכו' עד הרי זה נותנו לו. משנה וגמרא בריש פרק עד כמה (בכורות דף כ״ו:):\",1,0],[8,370,1,15,\"ויראה לי שהבכור נותן לכל כהן שירצה. נראה דהיינו לומר דטובת הנאה לבעלים:\",2,0],[8,370,1,16,\"כהן שאכל כזית מבכור תמים וכו' וכן זר שאכל כזית מבכור וכו'. בפרק אלו הן הלוקין (מכות דף י״ז):\",1,0],[8,370,1,17,\"הבכור אין פודין אותו וכו'. בר״פ כל פסולי המוקדשין (בכורות דף ל״א:) ופ״ק דתמורה (דף ה':):\",1,0],[8,370,1,17,\"וכן אין מוכרין אותו כשהוא תם וכו' עד ואע\\\"פ שהוא תמים. בפ\\\"ק דתמורה (דף ח':).\",2,0],[8,370,1,17,\"ומ\\\"ש בין לכהן בין לישראל. שם (דף ח':) אמר רב חסדא ל\\\"ש (דמותר למכרו תמים) אלא כהן לכהן אבל כהן לישראל אסור וכו' מפני שנראה ככהן המסייע בבית הגרנות, ובתר הכי בעובדא דמר זוטרא איקלע לבי רב אשי אמרינן דלא סבירא להו הא דרב הונא בריה דרב יהושע דקאמר על מילתיה דרב חסדא, וכיון דבי רב אשי דבתרא הוא סברי דאפילו לישראל שרי ומר זוטרא נמי משמע דקבלה מינייהו הכי נקטינן:\",3,0],[8,370,1,18,\"ומ״ש בכור בעל מום יש לכהן למוכרו בכל זמן וכו'. בר״פ כל פסולי המוקדשין (בכורות דף ל״א) ובפ״ק דתמורה (דף ה').\",1,0],[8,370,1,18,\"ומ\\\"ש וכשהוא מוכר בשר בכור בעל מום מוכרו בבית אבל לא בשוק. משנה ר\\\"פ כל פסולי המוקדשין שם.\",2,0],[8,370,1,18,\"ומ\\\"ש אבל בשר בכור תמים אינו נמכר וכו'. פשוט הוא והכי משמע בפ\\\"ק דתמורה שם.\",3,0],[8,370,1,18,\"ומה שכתב וכהנים שנמנו על הבכור מותרים לשקול מנה כנגד מנה בבכור. ר\\\"פ כל פסולי המקודשין (דף ל\\\"א) תנן שוקלין מנה כנגד מנה בבכור ומפשטא משמע דארישא קאי דקתני בבכור בעל מום אינו נשקל בליטרא ומדברי רבינו כאן נראה שהוא מפרשה בבכור תמים בזמן המקדש:\",4,0],[8,370,1,19,\"המפשיט בכור בעל מום וכו'. בספ\\\"ד דתמורה (דף כ\\\"ד) תניא דאין מרגילין בבכור ולא בפסולי המוקדשין ואוקימנא לה בתנאי דלית הלכתא כוותייהו. ומה שאמרו שם במערבא אמרי מפני שנראה כעובד עבודה בקדשים ר\\\"י בר אבין אמר גזירה שמא יגדל מהם עדרים עדרים מפרש רבינו דאדר\\\"א בר\\\"ש קאי ולא כדפירש\\\"י והרא\\\"ש:\",1,0],[8,370,2,3,\"כל המומים הקבועים וכו' אם נפל אחד מהם בבכור הרי זה נשחט עליו בכל מקום וכו' עד ירעה עד שיפול בו מום. משנה פרק על אלו מומין (בכורות דף מ״א):\",1,0],[8,370,2,4,\"יוצא דופן והבא אחריו וכו'. משנה פרק ב' דבכורות (דף י\\\"ט) וכרבי עקיבא.\",1,0],[8,370,2,4,\"ומה שכתב אפילו יצאת נקבה דרך דופן וכו'. שם בגמרא:\",2,0],[8,370,2,5,\"בכור שהוא אנדרוגינוס וכו'. משנה בסוף פרק על אלו מומין (בכורות דף מ״א) ופסק כחכמים:\",1,0],[8,370,2,5,\"נולד טומטום הרי זה ספק בכור וכו'. מימרא דר\\\"ח שם.\",2,0],[8,370,2,5,\"ומה שכתב בין שהטיל מים ממקום זכרות וכו'. הכי משמע התם בגמרא דלרב חסדא לא שאני ליה בטומטום בין מטיל ממקום זכרות למטיל ממקום נקבות הרי זה ספק בכור וכמו שכתבתי בספר בית יוסף ליורה דעה. ובקצת ספרי רבינו כתוב הרי זה בכור בין שהטיל האנדרוגינוס ממקום זכרות ט\\\"ס הוא וצריך למחוק תיבת האנדרוגינוס משום דההוא אין בו קדושה כלל וכך מצאתי בספר כתיבת יד. ויש לתמוה על רבינו שפסק דמטיל מים ממקום זכרות נמי ספיקא ויאכל במומו לבעלים והא בין לרב חסדא בין לר\\\"ל זכר הוי והכי משמע דהוי לרבי אלעאי נמי. ונראה שטעמו משום דכיון דרב חסדא סתם ואמר דטומטום ספיקא הוא ולא מפליג הכי נקטינן ולא חיישינן למאי דאמרינן מטיל מים במקום זכרות כולי עלמא לא פליגי דזכר הוא משום דההיא דחייה בעלמא היא כי היכי דלא תיקום כתנאי:\",3,0],[8,370,2,6,\"רחל שילדה כמין עז וכו'. משנה בפ\\\"ב דבכורות (דף ט\\\"ז:):\",1,0],[8,370,2,6,\"ומ\\\"ש והוא בעל מום קבוע וכו'. בפ\\\"ק דבכורות (דף ג') מימרא דר' יוחנן.\",2,0],[8,370,2,6,\"ומ\\\"ש אפילו פרה שילדה כמין חמור וחמור שילדה כמין סוס פטור מן הבכורה. משנה בפ\\\"ק דבכורות (דף ה') ובגמ' (דף ו') איבעיא להו פרה שילדה כמין חמור ויש בו מקצת סימנים מהו וכו' את\\\"ל כיון דאידי ואידי בני מיקדש בבכורה קדוש חמור שילדה כמין סוס מהו וכו' את\\\"ל כיון דמין טמאה הוא קדוש פרה שילדה כמין סוס מהו הכא ודאי הא טמאה והא טהורה הא בת מיקדש בבכורה והא לאו בת מיקדש בבכורה או דילמא סימנים מילתא היא ולא איפשיטא. וכבר נודע דרך רבינו לפסוק כאת\\\"ל ומפני כך פסק בפרה שילדה כמין חמור שאם יש בו מקצת סימני פרה הרי זה בכור לכהן ולענין חמור שילדה כמין סוס דאמרינן ביה את\\\"ל כיון דמין טמאה הוא קדוש אע\\\"פ שלא הזכירו כאן בסוף הלכות בכורים כתב שאם יש בו מקצת סימני חמור חייב ולענין פרה שילדה כמין סוס ויש בו קצת סימני פרה כיון דלא איפשיטא פסק שהוא ספק בכור. ומ\\\"מ מ\\\"ש בבבא זו אע\\\"פ שיש בו מקצת סימני פרה אינו נוח לי דמפשטא דלישנא איכא למשמע דאין בו מקצת סימני פרה ויש בו מקצת סימני פרה שוין הם דשניהם ספק ואינו כן שאם אין בו סימני פרה ודאי אינו בכור כלל וצ\\\"ל שלא השוום אלא לענין שאינם בכור ודאי אבל הא כדאיתיה והא כדאיתיה שזה אינו בכור כלל וזה ספק וזה פשוט.\",3,0],[8,370,2,6,\"ומ\\\"ש רבינו גבי ספק בכור יאכל במומו לבעלים. הוא מדקי\\\"ל המע\\\"ה.\",4,0],[8,370,2,6,\"ומ\\\"ש ואם תקפו כהן אין מוציאים מידו. טעמו מדאמרינן בפ\\\"ק דמציעא (דף ז':) אעובדא דההיא מסותא דהוו מינצו עלה בי תרי א\\\"ר המנונא מתני' היא ספק בכורה המע\\\"ה והא הכא דאם תקפו כהן אין מוציאין מידו וכי לא תקפו אסור בגיזה ועבודה. אבל קשה דהא בתר הכי אמרינן א\\\"ל רבה וכו' לעולם אימא לך תקפו כהן מוציאין אותו מידו ואפ\\\"ה אסורים בגיזה ועבודה וכו' א\\\"ל רב חנניא לרבה תניא דמסייע לך. והשתא למה דחה רבינו דברי רבה ורב חנניא וברייתא ופסק כרב המנונא. וי\\\"ל דהא דאמר רבה לעולם אימא לך תקפו כהן מוציאין מידו ואפ\\\"ה אסור בגיזה ועבודה וכו' סובר רבינו דחייה בעלמא היא וסייעתא דרב חנניא לאו סייעתא כולי האי דכיון דברשות ישראל הוא והמע\\\"ה אע\\\"ג דאם תקפו כהן אין מוציאין מידו לא נפיק מידי ממונו של ישראל ושפיר יכול לפטור עצמו בו. ובתשובות הרשב\\\"א סי' שי\\\"א כתוב שנשאל על זה והשיב באמת גם לי נראה פשיטותא של הלכה כן אלא דבעינן למשכוני נפשין אדרבינו לחזר אחר זכותו והשתדל להראות פנים לדברי רבינו:\",5,0],[8,370,2,7,\"המטיל מום בבכור וכו'. במשנה פרק כל פסולי המוקדשין (בכורות דף ל״ד) פלוגתא דתנאי ופסק כחכמים.\",1,0],[8,370,2,7,\"ומ\\\"ש ואם מת זה החוטא מותר לבנו לשוחטו וכו'. שם בעיא דאיפשיטא:\",2,0],[8,370,2,8,\"הרגיל לבכור שיפול בו מום וכו'. בברייתא פרק כל פסולי המוקדשין שם.\",1,0],[8,370,2,8,\"ומ\\\"ש או שהלך בין ברזל וכו'. מעובדא דרבי צדוק דבסמוך איכא למילף הכי ולישנא דאו שהלך היינו לומר שהוליכו הוא שם שאם הלך מעצמו ודאי דלא הוי מרגיל שיפול בו מום.\",2,0],[8,370,2,8,\"ומ״ש או שאמר לנכרי להטיל בו מום וכו' זה הכלל כל מום שנעשה לדעתו וכו'. משנה פרק כל פסולי המוקדשין (בכורות דף ל״ה):\",3,0],[8,370,2,9,\"ומ\\\"ש אמר אילו נפל מום בבכור זה הייתי שוחטו וכו'. שם במשנה מעשה בזכר של רחלים זקן ושערו מדולדל וראהו קסדור אחד אמר מה טיבו של זה אמרו לו בכור הוא ואינו נשחט אא\\\"כ היה בו מום נטל פגיון וצרם אזנו ובא מעשה לפני חכמים והתירו ואחר שהתירו הלך וצרם באזני בכורות אחרים ואסרום:\",1,0],[8,370,2,10,\"ראינוהו שעשה מעשה המרגיל וכו' כיצד כגון שנתן לו שעורים במקום דחוק וכו'. שם (דף ו') בעובדא דר' צדוק:\",1,0],[8,370,2,11,\"היה בכור רודף את האדם וכו'. משנה שם (דף ל\\\"ה).\",1,0],[8,370,2,11,\"ומ\\\"ש ואפילו בעט בו מפני שרדפו מקודם וכו'. שם תרי לישני דרב פפא ופסק כלישנא בתרא וכ\\\"ג הרמב\\\"ן. וכתב הרא\\\"ש ולא ידענא טעמא מאי דבשל תורה הוא ואפשר דהיינו טעמא דאע\\\"ג דאיסור דהטלת מום הוי דאורייתא מה שאינו נאכל באותו מום הוי מדרבנן עכ\\\"ל:\",2,0],[8,370,2,12,\"קטנים שהטילו מום בבכור דרך שחוק וכו' עד לא ישחט עליו. משנה שם:\",1,0],[8,370,2,13,\"בכור שאחזו דם יקיז וכו'. משנה שם (ל\\\"ב:) פלוגתא דתנאי וכן בברייתא ופסק כר\\\"ש דמתניתין ודברייתא דהכי איפסיקא הלכתא בגמ':\",1,0],[8,370,2,14,\"מותר להטיל מום וכו'. מימרא דרב יהודה בפירקא קמא דבכורות (דף ג').\",1,0],[8,370,2,14,\"ומה שכתב בד\\\"א בזמן הזה וכו'. ריש פ' כיצד מערימין (דף מ'):\",2,0],[8,370,2,15,\"עד שהעיד מפי עד אחר וכו' אפילו אשה נאמנת וכו'. בפ' כל פסולי המוקדשין (בכורות דף ל״ו):\",1,0],[8,370,2,16,\"כל המומין הראויים לבא בידי אדם וכו'. משנה שם (דף ל\\\"ה) כל המומין הראויים לבא בידי אדם רועים ישראל נאמנים רועים כהנים אינם נאמנים רשב\\\"ג אומר נאמן הוא על של חבירו ואינו נאמן על של עצמו ר\\\"מ אומר החשוד על הדבר לא דנו ולא מעידו. ובגמרא איפליגו ר\\\"י ורבי אלעזר בפירושא דמתני' חד אמר רועי ישראל בי כהנים נאמנים וכו' רועי כהנים בי ישראל אינם נאמנים מימר אמר כיון דקא טרחנא ביה לא שביק לדידי ויהיב לאחריני וה\\\"ה כהן לכהן דחיישינן לגומלין ואתא רשב\\\"ג למימר נאמן הוא על של חבירו ואינו נאמן על של עצמו ואסיקנא דהלכה כרשב\\\"ג. וכתב הרא\\\"ש רועה כהן בשל ישראל מהימן דלאו של עצמו הוא והכי חזינא בפירושא דרבוותא ואיכא מאן דאמר דפסק דלא מהימן והיינו כלישנא קמא דאמר רועי כהנים בשל ישראל אינם נאמנים וס\\\"ל דלא פליג רשב\\\"ג אלא אמאי דמחסרא דמתני' דהיינו כהן לכהן דלא חייש איהו לגומלין אבל רועה כהן בישראל לא פליג דכיון דסבר לא שביק לדידיה בשל עצמו דמי והך סברא לא מעליא היא דכיון דאפילו בנו ובתו מהימני סברא הוא דכ\\\"ש רועי כהן בשל ישראל ועוד דלא מסתברא דקאי אמאי דמחסרא מתני' דוקא ולא קאי אעיקר מתני' ועוד בר מן דין הא ללישנא בתרא רועי כהן בי ישראל אפילו לת\\\"ק הימוני מהימן וכיון דפלוגתא דלישני הוא ליכא איסורא אלא גזירה דרבנן גרידא לקולא נקטינן ועוד דמתני' כפשוטה אתיא כי האי לישנא וללישנא קמא צריך לחסורה הילכך האי לישנא עדיף ונקטינן מינה דרועי כהנים בי ישראל נאמנין וכ\\\"פ הלכתא הרמב\\\"ן ז\\\"ל עכ\\\"ל. ואני אומר שמתוך דבריו נתבאר טעמו של רבינו שהוא כההיא סברא שכתב ברישא והקושיא שהקשה על אותה סברא לא מכרעי דאפשר לתרוצינהו:\",1,0],[8,370,2,17,\"כהן שהעיד לכהן אחר וכו'. שם במשנה וגמרא ופסק כרבן שמעון בן גמליאל.\",1,0],[8,370,2,17,\"ומה שכתב שכל הכהנים חשודים להטיל מום בבכור וכו'. שם.\",2,0],[8,370,2,17,\"ומ\\\"ש כל, כלומר אפילו הוא חבר וכמו שנתבאר בפרק זה.\",3,0],[8,370,2,17,\"ומ\\\"ש אפילו בניו ובני ביתו של כהן מעידים לו על הבכור אבל לא אשתו וכו'. שם:\",4,0],[8,370,2,18,\"בכור שהיה ביד כהן וכו'. זהו פירוש מה ששנינו בפרק הנזכר (דף ל\\\"ו) נאמן הכהן לומר הראיתי בכור זה ובעל מום הוא:\",1,0],[8,370,2,19,\"וכן נאמן הכהן לומר על בכור בעל מום וכו'. מימרא דרב יהודה (דף ל\\\"ו). וכתב הרא\\\"ש דדוקא באומר ישראל פלוני נתנו לי במומו אבל אם אמר ישראל סתם שאינו מזכירו לא. ובספר ב\\\"י ליורה דעה סי' שי\\\"ד כתבתי טעמו וטעם רבינו:\",1,0],[8,370,3,1,\"אין שוחטין את הבכור אלא ע\\\"פ מומחה וכו'. בפ\\\"ק דסנהדרין (דף ה').\",1,0],[8,370,3,1,\"ומ\\\"ש אפילו היה מום גדול וגלוי לכל וכו'. יתבאר בסמוך.\",2,0],[8,370,3,1,\"ומ״ש וכל הבכורות אדם רואה חוץ מבכורות עצמו. בסוף פרק ב' דנגעים ובסוף פרק עד כמה (בכורות דף ל״א.) ומוקמינן לה ביחיד מומחה דאילו בשלשה יכול להיות אחד מהשלשה דלא חשידי כלום בשבילו וכך הם דברי רבינו:\",3,0],[8,370,3,2,\"אם אין שם מומחה וכו'. במשנה ס״פ כל פסולי המוקדשין (בכורות דף ל״ו:) פלוגתא דתנאי ואיפסיקא בגמרא הלכתא כת״ק.\",1,0],[8,370,3,2,\"ומ\\\"ש וכן בכור שיצא ח\\\"ל ונפל בו מום מובהק וכו'. מימרא שם התרת בכור בח\\\"ל ע\\\"פ שלשה בני הכנסת ובמומים מובהקים. וכתב רבינו שיצא ח\\\"ל לרבותא דאע\\\"פ שנולד בארץ אינו צריך מומחה וכל שכן אם נולד בח\\\"ל:\",2,0],[8,370,3,3,\"אין רואים את הבכור לישראל וכו' עד לגזול מתנות כהונה. מימרא דרב יהודה שם.\",1,0],[8,370,3,3,\"ומ\\\"ש לפיכך אם היה חכם וכו'. נלמד ממה שיבא בסמוך.\",2,0],[8,370,3,3,\"ומ\\\"ש היה המום גלוי לכל וכו'. שם:\",3,0],[8,370,3,4,\"השוחט את הבכור ואח״כ הראה את מומו וכו'. במשנה פ' עד כמה (בכורות דף כ״ח) פלוגתא דתנאי ופסק כר״מ וכ״כ הרא״ש בשם בעל הלכות גדולות והרמב״ן משום דהלכה כר״מ בגזירותיו:\",1,0],[8,370,3,5,\"בכור שהיתה לו ביצה אחת ושני כיסים וכו'. במשנה פ' על אלו מומין (בכורות דף מ') פלוגתא דתנאי ופסק כר״ע:\",1,0],[8,370,3,6,\"מי שאינו מומחה וראה את הבכור וכו'. משנה בפרק עד כמה (בכורות דף כ״ח).\",1,0],[8,370,3,6,\"ומה שכתב וכמה משלם וכו'. שם בגמרא [עמוד ב'].\",2,0],[8,370,3,6,\"ומ\\\"ש מפני שקנסו את בעל הבהמה וכו'. שם מ\\\"ט וכו' אמר רב הונא בר מנוח וכו' משום גזירת מגדלי בהמה דקה נגעו בה. ופירש\\\"י משום גזירת בהמה דקה נגעו בה מום טורח מגדלי בהמה דקה שיש בה טורח גדול לגדלה וזה שהתיר הבכור הצילו לכהן מטורח גדול דשמא אם הראהו לאחר לא היה מתירו לו והיה לו עוד טיפול מרובה עד שיפול בו מום להכי נגעו בו דאינו משלם אלא רביע. ל\\\"א מפני מגדלי בהמה דקה שעוברים על דברי חכמים כדתנן אין מגדלין בהמה דקה בארץ ישראל קנסו חכמים דלא לישקול אלא רביע עכ\\\"ל. והראב\\\"ד כתב א\\\"א אין כאן קנס וכו'. ודברי רבינו כלשון אחרון של רש\\\"י:\",3,0],[8,370,3,7,\"הנוטל שכרו להיות רואה בכורות וכו'. משנה שם.\",1,0],[8,370,3,7,\"ומ\\\"ש ולא יטול שכר על בהמה זו וכו'. שם בגמרא (דף כ\\\"ט):\",2,0],[8,370,3,8,\"החשוד על הבכורות וכו'. משנה שם.\",1,0],[8,370,3,8,\"ומ\\\"ש אפילו של נקבה. פלוגתא שם במשנה ופסק כת\\\"ק.\",2,0],[8,370,3,8,\"ומ\\\"ש ואין לוקחים ממנו צמר וכו' עד ועורות עבודים וכו'. שם במשנה ובגמרא:\",3,0],[8,370,3,9,\"השוחט את הבכור ומכרו וכו'. משנה שם (דף ל\\\"ז) וכתב רבינו דין זה פרק ט\\\"ז מהל' מכירה:\",1,0],[8,370,3,10,\"בכור שנמצא טריפה וכו'. בפ' טבול יום (זבחים ק\\\"ג) תנן כל הקדשים שאירע בהם פיסול קודם להפשטן אין עורותיהם לכהנים לאחר הפשטן עורותיהם לכהנים א\\\"ר חנינא סגן הכהנים מימי לא ראיתי עור שיוצא לבית השריפה אמר ר\\\"ע מדבריו למדנו שהמפשיט את הבכור ונמצא טריפה שיאותו הכהנים בעורו וחכ\\\"א אין לא ראינו ראיה אלא יוצא לבית השריפה. ובגמרא (דף ק\\\"ד) א\\\"ר חייא בר אבא אר\\\"י הלכה כר\\\"ע ואף ר\\\"ע לא אמר אלא כשהתירו מומחה אבל לא התירו מומחה לא והלכתא כחכמים בשר בקבורה והעור בשריפה ומפרש רבינו דחכמים ל\\\"פ אר\\\"ע דר\\\"ע מיירי בבעל מום וחכמים מיירו בתמים והלכה כר\\\"ע והלכה כחכמים.\",1,0],[8,370,3,10,\"ומ\\\"ש רבינו אחר שהופשט. לומר דאילו קודם שהופשט העור כבשר בקבורה כדאיתא בברייתא בגמרא:\",2,0],[8,370,3,11,\"הבכור שנאכל בשרו וכו' כך נהנים בגיזותיו. כן משמע במשנה (דף כ\\\"ה:) בפ\\\"ג דבכורות.\",1,0],[8,370,3,11,\"ומ\\\"ש אבל כל צמר שנגזז ממנו כשהוא חי אפי' נשר אסור בהנאה אפי' אחר שחיטתו. כלומר ע\\\"פ מומחה שהותר הצמר שבעור אסור הצמר שנשר ממנו כשהוא חי ואצ\\\"ל אחר מיתתו שאסור הצמר שבעור וכבר נתבאר בפ\\\"א מהל' מעילה.\",2,0],[8,370,3,11,\"ומ\\\"ש וכבר ביארנו בהלכות מעילה וכו'. בפ' הנזכר:\",3,0],[8,370,3,12,\"בכור [שהיה בו צמר] מדובלל וכו'. שם.\",1,0],[8,370,3,12,\"ומה שכתב והוא הצמר שעיקרו הפוך כלפי ראשו. שם (דף כ\\\"ו:) פלוגתא דאמוראי ופסק כריש לקיש דהוא מאריה דגמרא טפי מרב נתן בר אושעיא ועוד דרבי אלעזר נמי ס\\\"ל כר\\\"ל ועוד דר' אלעא פריש טעמא דר\\\"ל משמע דכוותיה ס\\\"ל ועוד דטעמא דיהיב ר' אלעא טעמא דמסתבר הוא:\",2,0],[8,370,3,13,\"גיזת בכור אפילו בעל מום וכו'. בספ\\\"ג דבכורות (דף כ\\\"ה:) תניא בעלי מומין אסורים בכל שהו ומפרש לה ר\\\"נ בגיזת בכור בעל מום שנתערבה בגיזי חולין ואע\\\"ג דר' יוסי פליג ואמרינן בגמרא מאן ת\\\"ק ר' יהודה וה\\\"ל למיפסק כר' יוסי לגבי ר' יהודה הא איפסיקא התם בגמ' הלכה כר' יהודה אבל איכא למידק דאמרינן התם דאמרוה להא דר\\\"נ קמיה דר' ירמיה וקרי להו בבלאי טפשאי וכו' לא שמיע להו הא דאמר ר\\\"י מחלוקת בשבדק ולא מצא וכו' ור' אסי אמר ר\\\"י מחלוקת בשבדק ומצא משמע דליתא להא דר\\\"נ והיאך פסק רבינו כמותו. וי\\\"ל דמשמע דלא פליגי אלא בפירושא דברייתא היכי מיתוקמא שפיר טפי אבל לענין דינא לא פליגי עליה:\",1,0],[8,370,3,13,\"האורג מלא הסיט מצמר הבכור וכו'. בפ\\\"ג דערלה (משנה ג') האורג מלא הסיט מצמר בכור בבגד ידלק הבגד וכתב הר\\\"ש מוקי לה בשלהי תמורה (דף ל\\\"ד.) בדעבד מיניה צפרתא דחשיב ולא בטיל הא לאו הכי שרי דבטיל ברובא. ופירש\\\"י שעשה מהאיסור צורת צפור דחשיב דמיפה ליה לכוליה [שק] ולא מיבטיל. ורבינו שלא חילק בין עבד מיניה צפרתא ללא עבד נראה שטעמו משום דלא מוקי בגמרא בדעבד מיניה צפרתא אלא למאי דקתני התם משער נזיר ומפטר חמור בשק ידלק השק וסובר רבינו דלא ילפינן מיניה לבכור אע\\\"ג דכי הדדי מיתני במסכת ערלה דדוקא בשער נזיר ופטר חמור דלא חשיב הוא דפריך וליבטיל ברובא ואיצטריך לשנויי דעבדיה כצפרתא אבל גבי צמר בכור ל\\\"ק לן דליבטיל ברובא דמלא הסיט צמר חשיב ולא בטיל אפי' בכמה אבל קשה על זה דגם בדין שער בשק לא חילק בסוף הל' פסולי המוקדשין. והר\\\"י קורקוס ז\\\"ל כתב שרבינו מפרש דלאו דוקא שארג צפרתא אלא ה\\\"ק כיון שהוא מלא הסיט שראוי לצפרתא חשיב ולא בטיל דאי בעשה צפרתא דוקא מלא הסיט למה הוזכר. א\\\"נ שסובר רבינו שאותה קושיא ואותו תירוץ הם דלא כהלכתא דהא קי\\\"ל דבגד שאבד בו כלאים אינו בטל והא נמי דכוותה אע\\\"פ שחילקו המפרשים לשאר איסורים רבינו אינו מחלק:\",2,0],[8,370,3,13,\"וכתב הראב\\\"ד גיזת בכור אפילו בעל מום וכו' קשיא לן בטווי וארוג בעינן מלא הסיט וכו'. ואיכא למידק עליה לתירוצא קמא טווי וארוג דבעינן מלא הסיט ע\\\"כ בנגזז מן החי היא דאילו אחר מיתה מותר ליהנות בגיזותיו כמ\\\"ש רבינו בפ' זה וכיון שכן למה גזרו בגיזה יותר מבטווי וארוג הבא מן הגיזה. ולכן נ\\\"ל שצריך להגיה ולגרוס א\\\"כ במקום א\\\"נ וכוליה חד תירוצא הוא וה\\\"ק כיון דגיזה לא מיתסר אלא משום קנסא לא קנסו שיאסר בכל שהו אלא כשהוא בגיזה אבל כשנשתנה לטווי וארוג לא גזרו שיאסר בכל שהוא והוקשה לו א\\\"כ למה במוקדשים טווי ואריג מקדשין בכל שהן ותירץ דמיירי בקדשים שיש להם פדיון ומשום דדבר שיש לו מתירין אפילו באלף לא בטל:\",3,0],[8,370,4,1,\"בהמת השותפין חייבת בבכורה וכו'. פלוגתא דתנאי בר״פ ראשית הגז (חולין דף קל״ה) ופסק כת״ק.\",1,0],[8,370,4,1,\"ומ\\\"ש שאם היה שותף בפרה או בעובר אפילו היה לנכרי אחד מאלף וכו'. טעמו דכיון דיש לו חלק בכל הבהמה אפילו הוא אחד מאלף שותף מיקרי ואמרינן בריש בכורות (דף ג') בכור מקצת בכור משמע כתב רחמנא כל עד דאיכא כוליה.\",2,0],[8,370,4,1,\"ומ\\\"ש באם או בולד. הכי אמרינן בריש בכורות (דף ב'):\",3,0],[8,370,4,1,\"ומ\\\"ש היה לו באחד משניהם אבר אחד וכו'. שם (דף ג') וכמה תהא שותפות של נכרי ותהא פטורה מן הבכורה כלומר כשהנכרי אינו שותף אלא באבר אחד במה תהא שותפותו ויפטור מן הבכורה אמר רב הונא אפילו אזנו מתקיף לה ר\\\"נ ולימא ליה שקול אזנך וזיל אתמר רב חסדא אמר דבר שעושה אותו נבלה ורבא אמר דבר שעושה אותו טריפה ובתר הכי אר\\\"י אפילו מום קל. ופירש\\\"י אפי' אין לנכרי שותפות אלא באזנה שאם היה נוטל חלקו אינה לא נבילה ולא טריפה אלא מום קל בעלמא פטורה מן הבכורה ופסק רבינו כר\\\"י ורב הונא. וא\\\"ת היכי משכחת לה שיחתך שום אבר ולא תהיה בעלת מום. וי\\\"ל דמשכחת לה כגון שהיה יתר אצבע בידו או ברגלו ואין בו עצם שאם חתכו כשר:\",4,0],[8,370,4,2,\"הלוקח עובר פרתו של נכרי וכו'. משנה בפרק ב' דבכורות (דף י\\\"ג).\",1,0],[8,370,4,2,\"ומ\\\"ש ואין קונסין אותו על דבר זה. הכי איכא למילף משקלא וטריא דריש בכורות:\",2,0],[8,370,4,3,\"המקבל בהמה מן הנכרי וכו'. בריש בכורות (דף ב':) ר\\\"י אומר המקבל בהמה מן הנכרי וילדה מעלים אותה בשיווי ונותן חצי דמיו לכהן והנותן לו בקבלה כו' נותן כל דמיו לכהן וחכמים אומרים כל זמן שיד נכרי באמצע פטורה מן הבכורה וידוע דהלכה כחכמים:\",1,0],[8,370,4,4,\"המקבל צאן מן הנכרי בממון קצוב וכו'. משנה בפרק ב' דבכורות (דף ט\\\"ז:) ואיפלגו בה אמוראי ורבינו נתן כלל בדבר דכל ולדות שיש רשות לנכרי לגבות מהם פטורים וכל ולדות שאין לו רשות לגבות מהם חייבים ולדוגמא נקט ולדות וולדי ולדות ומפני כך השמיט מה ששנו במשנה העמיד ולדות תחת אמותיהם ולדי ולדות פטורים ולדי ולדי ולדות חייבים ולא איפלגו אמוראי אלא בכמה דורות הוא דרך להיות אחריות הנכרי עליהם ולדברי הכל דין זה שכתב רבינו אמת:\",1,0],[8,370,4,5,\"ישראל שנתן מעות לנכרי וכו' וכן אם קנה הנכרי מישראל בדיניהם וכו'. מימרא ברפ\\\"ב דבכורות (דף י\\\"ג):\",1,0],[8,370,4,6,\"גר שנתגייר וכו'. בסוף פרק הזרוע (חולין דף קל״ד):\",1,0],[8,370,4,7,\"הלוקח בהמה מן הנכרי וכו'. משנה בריש פרק ג' דבכורות (דף י\\\"ט:) אם ספק יאכל במומו לבעלים:\",1,0],[8,370,4,8,\"לקח בהמה מניקה מן הנכרי וכו'. גם זה משנה שם (דף כ\\\"ג:) ואיפסיקא בגמ' הלכתא כרשב\\\"ג דמתני'.\",1,0],[8,370,4,8,\"ומ\\\"ש ואפילו היה זה שמניקה כמו מין אחר ואפילו כמין חזיר וכו'. מימרא דרבי יוחנן שם (דף כ\\\"ד).\",2,0],[8,370,4,8,\"ומ\\\"ש וכן בהמה שהיא חולבת וכו'. בפ\\\"ג דבכורות (דף כ\\\"ו:) פלוגתא דר' יהושע ור\\\"ע ופסק כר' יהושע דרביה הוא:\",3,0],[8,370,4,9,\"הלוקח בהמה מישראל הרי זה בחזקת שבכרה וכו'. שם (דף כ\\\"א:) פלוגתא דאמוראי ופסק כר' יוחנן:\",1,0],[8,370,4,10,\"בהמה דקה שהפילה עובר וכו'. משנה וגמ' בר\\\"פ הנזכר (דף י\\\"ט כ') ובדף הנזכר בגמרא:\",1,0],[8,370,4,10,\"לפיכך הלוקח בהמה מן הנכרי וכו'. בריש פרק הנזכר פלוגתא דתנאי ופסק כרבי עקיבא:\",2,0],[8,370,4,10,\"וכן בהמה [גסה] שהפילה שליא הרי זה סימן ולד וכו'. משנה שם ופ' בהמה המקשה:\",3,0],[8,370,4,10,\"ומה שכתב ומותר להשליך אותה שליא לכלבים וכו' אבל בהמת קדשים שהפילה שליא תקבר וכו'. משנה (דף ע\\\"ז) וגמרא פרק בהמה המקשה:\",4,0],[8,370,4,11,\"בהמה גסה שהפילה חררת דם וכו'. משנה פרק ג' דבכורות (דף כ\\\"א:)\",1,0],[8,370,4,11,\"ומ\\\"ש ולמה קוברים אותו וכו'. שם בגמ' ואע\\\"פ שטעם זה נאמר בגמ' לר\\\"ש דאמר דאינה מטמאה לדידן נמי צ\\\"ל כן כי היכי דלא תיקשי לן מ\\\"ש משליא דישליכנה לכלבים וכ\\\"כ התוס':\",2,0],[8,370,4,12,\"כבר ביארנו בענין נדה וכו' אבל ולד בהמה לא עמדו חכמים על מניין הימים שיגמר בו. שם (דף כ\\\"א:).\",1,0],[8,370,4,12,\"ומ\\\"ש אבל אמרו שהמפלת טינוף אינה מתעברת אחריו וכו'. מימרא דזעירי שם (דף כ'):\",2,0],[8,370,4,13,\"בהמה שיצאה מליאה ובאתה ריקנית וכו'. פ' המפלת (דף נ\\\"ט):\",1,0],[8,370,4,13,\"ואין לנפלי בהמה פטירת רחם וכו'. בפ' שלישי דבכורות (דף נ\\\"ב).\",2,0],[8,370,4,13,\"ומ\\\"ש של ערב. מימרא דרבי יוחנן שם. פ' הערוך פיקה כמו כדור קטן שמשימים בראש הכוש שטוים בו ואותו שטוים בו השתי קטן מאותו שטוים בו הערב:\",3,0],[8,370,4,13,\"כתב הראב\\\"ד ז\\\"ל א\\\"א דגרסינן בבכורות שמעתי וכו':\",4,0],[8,370,4,14,\"מבכרת המקשה לילד וכו'. משנה פרק בהמה המקשה (חולין דף ס\\\"ט:) ומפרש רבינו דמאי דקתני נפטרה מן הבכורה אסיפא דוקא קאי ולא כרש\\\"י שפירש דארישא נמי קאי.\",1,0],[8,370,4,14,\"ומה שכתב ואם חתך אבר והניחו וכו' נתקדש למפרע. שם בגמרא אליבא דרב הונא דהלכה כוותיה כדבסמוך:\",2,0],[8,370,4,15,\"ומ\\\"ש יצא שליש ומכרו לנכרי וכו' יצא שליש דרך דופן וכו'. שם פלוגתא דרב הונא ורבה ופסק כרב הונא:\",1,0],[8,370,4,16,\"יצא מיעוט אבר גדול וכו'. פשוט שם.\",1,0],[8,370,4,16,\"ומ\\\"ש יצא חצי העובר והוא רובו של אבר היוצא וכו'. שם (דף ע') בעיא דלא איפשיטא:\",2,0],[8,370,4,17,\"בכור שכרכו בסיב וכו'. שם בעיי דלא איפשיטו וגירסת רבינו כגירסת ר\\\"ח שכתבו התוספות:\",1,0],[8,370,4,20,\"הדביק שני רחמים זה לזה וכו' נפתחו כותלי בית הרחם וכו' נעקרו בית הרחם [ונתלו] בצוארו הרי זה ספק. שם בעיי דלא איפשיטו:\",1,0],[8,370,4,21,\"נגממו כותלי בית הרחם אינו קדוש. בעיא שם וא\\\"ל נגעת בבעיא דאבעיא לן דבעי ר' זירא מר' אסי עומד מרובה על הפרוץ ויצא דרך פרוץ פרוץ מרובה על העומד ויצא דרך עומד מאי ע\\\"כ לא איבעיא לי אלא פרוץ מרובה על העומד דאיכא עומד בעולם אבל נגממו לא קא מיבעיא לי. ופירש רש\\\"י נגממו ניטל מעובי הכותלים מבפנים סביב סביב וכו' ל\\\"א נגממו מבפנים ושפה חיצונה משמרת עכ\\\"ל ופירוש ראשון נראה יותר:\",1,0],[8,370,5,1,\"רחל שלא בכרה וכו'. בפרק ב' דבכורות (דף י\\\"ז) פלוגתא דרבי יוסי הגלילי וחכמים במשנה ופסק כחכמים.\",1,0],[8,370,5,1,\"ומ\\\"ש הכהן נוטל את הכחוש. שם במשנה פלוגתא דר\\\"ע ור\\\"ט ופסק כר\\\"ע.\",2,0],[8,370,5,1,\"ומ\\\"ש והשני ספק בכור. שם במשנה.\",3,0],[8,370,5,1,\"ומ\\\"ש מת אחד מהם אין לכהן כלום וכו'. שם במשנה פלוגתא דר\\\"ע ור\\\"ט ופסק כר\\\"ע.\",4,0],[8,370,5,1,\"מ\\\"ש וכן אם ילדה זכר ונקבה וכו'. שם (דף י\\\"ח) במשנה:\",5,0],[8,370,5,2,\"שתי רחלות שלא בכרו וכו' עד שזה הזכר ספק בכור הוא. הכל משנה שם:\",1,0],[8,370,5,3,\"כל בכור שהוא ספק דינו שירעה וכו'. פשוט שם במשנה.\",1,0],[8,370,5,3,\"ומ\\\"ש ואם תפשו הכהן וכו'. נתבאר בפרק שני.\",2,0],[8,370,5,3,\"ומ\\\"ש אבל אינו מקריבו וכו'. פשוט הוא:\",3,0],[8,370,5,4,\"מי שהיה בעדרו מבכרות וכו'. משנה פרק שלישי דבכורות (דף כ\\\"ג:):\",1,0],[8,370,5,6,\"שנים שהפקידו שני זכרים וכו'. פ\\\"ב דבכורות (דף י\\\"ח:) הכל מודים בשנים שהפקידו אצל רועה שמניח רועה ביניהם ומסתלק וכו' ובאחד שהפקיד אצל בעל הבית שהמוציא מחבירו עליו הראיה לא נחלקו אלא בחצר בעה\\\"ב ורועה כהן ר\\\"ט סבר אקנויי קא מקני ליה בחצירו וניחא ליה דלתעביד מצוה וה\\\"ל כשנים שהפקידו אצל רועה שמניח רועה ביניהם ומסתלק ור\\\"ע סבר כיון דאית ליה פסידא לא מקני ליה מדעם וה\\\"ל כאחד שהפקיד אצל בעה\\\"ב שהמע\\\"ה ופסק הלכה כר\\\"ע:\",1,0],[8,370,5,7,\"לא נחשדו ישראל על הבכורות וכו'. בפרק כל פסולי המוקדשין (בכורות ל״ו:):\",1,0],[8,370,5,8,\"כל הקדשים שקדם להם מום קבוע להקדשן וכו'. משנה פ״ב דבכורות (דף י״ד) ופרק הזרוע (חולין דף ק״ל):\",1,0],[8,370,5,9,\"הלוקח בהמה ממעות מעשר שני וכו'. ירושלמי פ\\\"ק דמעשר שני וכרבי זעירא דמסייעא ליה מתניתא:\",1,0],[8,370,5,9,\"אבל הלוקח בהמה וכו'. בספ\\\"ק דבכורות (דף י\\\"ב:) אמר רב חסדא בהמת שביעית פטורה מן הבכורה וכו' לאכלה אמר רחמנא ולא לשריפה ופירש\\\"י לשריפה ואי מיחייב בבכור סלקי אימורים לגבוה עכ\\\"ל. והראב\\\"ד השיג על רבינו שכתב ולא לסחורה ולא ה\\\"ל לכתוב אלא ולא לשריפה כמו שאמרו בגמרא. ונראה שבנוסחת רבינו היה כתוב ולא לסחורה.\",2,0],[8,370,5,9,\"ומ\\\"ש רבינו הרי זה משתכר בבכור היינו לומר שאינו חייב לבערו בזמן הביעור ונותנו לכהן ויש לו טובת הנאה:\",3,0],[8,370,5,9,\"וכן אסור לעשות סחורה בבכורות וכו'. בפ\\\"ז דשביעית:\",4,0],[8,370,5,10,\"ומ\\\"ש לקח בכור למשתה בנו וכו'. גם זה משנה שם:\",1,0],[8,370,5,11,\"אין שמין בכורות תמימים לישראל וכו'. תוספתא בפ\\\"ג דבכורות, וכתב רבינו בזמן הזה כלומר דאי בזמן הבית קרב הוא ונאכל לכהנים בלבד ומאי שומא איכא:\",1,0],[8,370,6,1,\"מצות עשה להפריש אחד מעשרה וכו'. בת\\\"כ פרשת בחקותי:\",1,0],[8,370,6,2,\"מעשר בהמה נוהג בחולין. משנה בר\\\"פ בתרא דבכורות (דף נ\\\"ג).\",1,0],[8,370,6,2,\"ומ\\\"ש אבל חכמים אסרו לעשר בהמה בזמן הזה וכו'. שם בגמרא.\",2,0],[8,370,6,2,\"ומה שכתב ואם עבר ועשה וכו'. פשוט הוא דכיון שאין הטעם אלא משום דלא ליתי לידי תקלה היכא דעבר ועישר למה לא יהיה קדוש:\",3,0],[8,370,6,3,\"הכל חייבים במעשר בהמה וכו':\",1,0],[8,370,6,4,\"ודין מעשר בהמה שיהיה נשחט בעזרה וכו'. משנה בס״פ איזהו מקומן (זבחים נ״ו:).\",1,0],[8,370,6,4,\"ומ\\\"ש ואם היה בעל מום וכו'. בפ' בתרא דבכורות (דף נ\\\"ז) אמרינן דמעשר לא פסיל ביה מומא:\",2,0],[8,370,6,5,\"מעשר בהמה אסור למכרו כשהוא תמים וכו'. בפ״ק דמעשר שני תנן מעשר בהמה אין מוכרים אותו תמים חי ולא בעל מום חי ושחוט וכתב ה״ר עובדיה תמים חי והה״נ שחוט וכו' ואיידי דבעי למיתני סיפא גבי בכור מוכרים אותו תמים חי תנא נמי רישא תמים חי. ובפ״ק דתמורה (דף ה':) ובר״פ כל פסולי המוקדשין (בכורות דף ל״א:) תניא במעשר נאמר לא יגאל ואינו נמכר לא חי ולא שחוט ולא תם ולא בעל מום ופירש״י לא יגאל ואינו נמכר דגמרינן מלא יגאל (דחרמים) כדלקמן:\",1,0],[8,370,6,6,\"ומ\\\"ש מד\\\"ס שאסור למוכרו בעל מום ואפילו שחוט וכן מ\\\"ש שזה מד\\\"ת וזה מד\\\"ס. בר\\\"פ כל פסולי המוקדשין אמר רבא מנא אמינא לה (דמעשר בהמה שנשחט מותר למוכרו בהבלעה) דכתיב והיה הוא ותמורתו יהיה קדש לא יגאל אימתי עושה תמורה מחיים אימתי אינו נגאל מחיים הא לאחר שחיטה נגאל ורבנן הוא דגזרו לאחר שחיטה אטו לפני שחיטה וכו' דבר שאינו נישום מחיים לא גזרו ביה רבנן פירוש דבר המתחשב מחיים כי עיקר קונה הבהמה מחיים אינו מחשיב לא העור והגידים והחלב, ולפי זה הא דתניא במעשר נאמר לא יגאל ואינו נמכר לא חי ולא שחוט לא תם ולא בעל מום אסמכתא בעלמא היא דמדאורייתא לא מיתסרא מכירתו אלא תמים חי דומיא דתמורה:\",1,0],[8,370,6,6,\"ומ״ש לפיכך אין שוקלין מנה כנגד מנה במעשר וכו'. הכי משמע במתני' ר״פ כל פסולי המוקדשין (בכורות דף ל״א) דקתני ושוקלין מנה כנגד מנה בבכור ומשמע דוקא בבכור אבל לא במעשר:\",2,0],[8,370,6,7,\"ומעשר בהמה של יתומים וכו'. בריש פרק כל פסולי המוקדשין שם:\",1,0],[8,370,6,8,\"מעשר בהמה שנשחט במומו וכו' עד בהבלעה מותר. שם וכתבתיו בסמוך.\",1,0],[8,370,6,8,\"ומ\\\"ש ואם היו דמי העצמות יקרים וכו'. שם פלוגתא ופסק לקולא כדרבנן:\",2,0],[8,370,6,9,\"הכל נאמנים על מומי מעשר וכו'. משנה בסוף פרק כל פסולי המוקדשין (בכורות דף ל״ו:) ומפרש טעמא בגמרא משום דאי בעי שדי מומא בכוליה עדריה.\",1,0],[8,370,6,9,\"ומ\\\"ש ורואה אדם מומי מעשר שלו ומתירו אם היה מומחה. מבואר [שם ל\\\"א] מהטעם הנזכר:\",2,0],[8,370,6,10,\"הלוקח טלאים שנולדו בשנה זו וכו' לפיכך השותפים שנשתתפו בבהמות וכו' עד אחר שיתוף זה השני. הכל משנה בפרקא בתרא דבכורות (דף נ\\\"ה: ונ\\\"ו:).\",1,0],[8,370,6,10,\"ומ\\\"ש ואע\\\"פ שחלקו גדיים כנגד גדיים וכו'. שם פלוגתא דאמוראי ופסק כר\\\"נ וכתוב בספרי רבינו וטלאים כנגד גדיים וט\\\"ס הוא וצריך להגיה ולכתוב וטלאים כנגד טלאים.\",2,0],[8,370,6,10,\"ומ\\\"ש ועשרה כנגד עשרה. שם פלוגתא דאמוראי ופסק כר\\\"י:\",3,0],[8,370,6,11,\"האחין והשותפין שחלקו בכספים וכו' אבל אם חלקו הבהמות כו'. מימרא דר' ירמיה שם (דף נ\\\"ו:):\",1,0],[8,370,6,12,\"הלוקח עשרה עוברים וכו'. מימרא דר\\\"י בדף הנזכר:\",1,0],[8,370,6,13,\"כהן שנפלו לו עשר בהמות וכו'. בס״פ הגוזל עצים (בבא קמא דף ק״י:) בעיא דאיפשיטא:\",1,0],[8,370,6,14,\"הכל נכנסים לדיר להתעשר וכו' עד אינו מתעשר. משנה וגמרא בפירקא בתרא דבכורות (דף נ\\\"ז). ודע דאמרינן בפירקא קמא דזבחים ליל שמיני נכנס לדיר להתעשר ואיני יודע למה השמיטו רבינו:\",1,0],[8,370,6,15,\"אין הלוקח פטור וכו' לפיכך הלוקח טלאים בתוך שבעת ימי הלידה וכו'. שם (דף נ\\\"ו) אמרינן דברייתא דקתני דלקוח חל על מחוסר זמן אינה משנה ואת\\\"ל משנה רבי שמעון בן יהודה היא ומשמע דחכמים פליגי עליה והלכתא כוותייהו:\",1,0],[8,370,6,16,\"כל בהמה שהיא ספק וכו'. נלמד מהדין שיבא בסוף הלכות אלו והוא בפ' הנזכר (דף נ\\\"ח:) קפץ אחד מהמנויים לתוכם כולם פטורים ובתוספתא דסוף בכורות תניא נתערב בהם יתום או לקוח כולם פטורים:\",1,0],[8,370,7,1,\"מי שהיו לו עשרה טלאים וכו'. במשנה פרק בתרא דבכורות (דף נ\\\"ח:) פלוגתא דתנאי ופסק כת\\\"ק:\",1,0],[8,370,7,1,\"כיצד עושה וכו'. שם במשנה.\",2,0],[8,370,7,1,\"ומ\\\"ש ואמותיהם מעמיד מבחוץ וכו'. ברייתא וגמרא שם [ובתוספתא דבכורות שם].\",3,0],[8,370,7,1,\"ומ\\\"ש מתחיל ומונה אותם בשבט וכו' עד וקידש עשירי ה\\\"ז מעשר. שם במשנה:\",4,0],[8,370,7,2,\"אין צריך לצרף וכו'. נלמד ממה שיבא בסמוך:\",1,0],[8,370,7,2,\"היו לו חמשה טלאים בירושלים וכו' עד ט\\\"ז מיל. במשנה פ' בתרא דבכורות (דף נ\\\"ד:):\",2,0],[8,370,7,3,\"ומ\\\"ש היו ג' עדרים וכו' עד להתעשר. שם פלוגתא דרב ושמואל ופסק כרב באיסורי:\",1,0],[8,370,7,4,\"אין מעשרים מן הצאן על הבקר וכו'. משנה שם (דף נ\\\"ג):\",1,0],[8,370,7,5,\"אין מעשרים מן הנולדים בשנה זו וכו'. משנה וגמרא שם:\",1,0],[8,370,7,6,\"כל הנולדים מאחד בתשרי עד כ\\\"ט באלול וכו' עד אין מצטרפין. משנה בפרק בתרא דבכורות (דף נ\\\"ז:):\",1,0],[8,370,7,6,\"ילדו תולדות בתוך שנתן וכו'. כן משמע בתוספתא דבכורות פ\\\"ז:\",2,0],[8,370,7,7,\"אין הטלאים הנולדים כמו הטבל וכו'. מתבאר ממה שיבא בסמוך:\",1,0],[8,370,7,8,\"קבעו חכמים ג' זמנים בשנה וכו'. פ' בתרא דבכורות (דף נ\\\"ז:) פלוגתא דתנאי ופסק כר\\\"ע.\",1,0],[8,370,7,8,\"ומ\\\"ש ואם שחט ה\\\"ז מותר. משנה שם:\",2,0],[8,370,7,8,\"ומ\\\"ש ולמה קבעו הגרנות בימים אלו וכו'. שם בגמרא (דף נ\\\"ח):\",3,0],[8,370,7,9,\"הכניס כל הצאן וכו'. שם (דף נ\\\"ט:) מימרא דרבא וברייתא.\",1,0],[8,370,7,9,\"ומ\\\"ש ואע\\\"פ שידע שאלו ישארו במניין וכו'. שם:\",2,0],[8,370,8,1,\"המכניס צאן לדיר וכו'. ברייתא בסוף בכורות (דף ס':) ומשנה בנזיר פרק בית שמאי (נזיר דף ל״א).\",1,0],[8,370,8,1,\"ומה שכתב אבל אם קרא לתשיעי או לאחד עשר עשירי וכו' עד מפני שהוא עצמו כתמורה. משנה בפירקא בתרא דבכורות:\",2,0],[8,370,8,2,\"ומ\\\"ש וטעון נסכים כשלמים: ומה שכתב ואינו עושה תמורה. בסוף בכורות (דף ס') במשנה פלוגתא דר\\\"מ ור\\\"י ופסק כר\\\"י.\",1,0],[8,370,8,2,\"ומה שכתב במה דברים אמורים כשהיה המונה הוא בעל הבהמות וכו'. מימרא בסוף בכורות (דף ס\\\"א) ופסק כרב פפא לגבי רב פפי והכי קיימא לן בכל דוכתא דטעות שליח בכל שהוא דאמר לי' לתקוני שדרתיך ולא לעוותי:\",2,0],[8,370,8,3,\"זה שאמרנו שאם קרא וכו'. משנה שם (דף ס').\",1,0],[8,370,8,3,\"ומה שכתב ואפילו יצא העשירי ולא קראהו לא עשירי ולא אחד עשר וכו'. ברייתא שם (בדף נ\\\"ט):\",2,0],[8,370,8,4,\"יצאו ט' וי' כאחד וכו' וכן אם יצאו עשירי וי\\\"א כאחד וכו'. מימרא דרבא (בדף ס'):\",1,0],[8,370,8,5,\"התחיל למנות ויצאו וכו'. משנה שם.\",1,0],[8,370,8,5,\"ומ\\\"ש וכן אם מנאן ג' ג' בכל פעם ופעם וכו'. שם פלוגתא דאמוראי ופסק כר\\\"י דאמר מונאן זוגות זוגות קינטרין קינטרין י' למניינן הוא קדוש וכדפריש רב מרי למניין שלו הוא קדוש ומשמע דרבא סבר כוותיה מדמתרץ ברייתא אליביה:\",2,0],[8,370,8,6,\"יצאו בתחלה שנים וכו'. שם במשנה:\",1,0],[8,370,8,7,\"מנאן למפרע וכו'. שם (בדף ס'):\",1,0],[8,370,8,8,\"קרא לתשיעי עשירי ונשאר העשירי בדיר וכו' עד שהמנין הראוי פוטר. שם (דף נ\\\"ט ע\\\"ב):\",1,0],[8,370,8,9,\"הכניס י' טלאים וכו' עד שהרי ששה היו שם נשארים בתוך הדיר. שם בדף הנזכר:\",1,0],[8,370,8,11,\"מי שהיו לו תשעה עשר טלאים וכו' עד שאותן התשעה נמנו מניין הראוי. גם זה בדף הנזכר (ובדף ס'):\",1,0],[8,370,8,12,\"היה מונה והוציא הטלה ראשו וכו'. הכי משמע שם (בדף ס'):\",1,0],[8,370,8,13,\"היה מונה והפסיק וכו'. בתוספתא בסוף בכורות:\",1,0],[8,370,8,14,\"היה מונה היוצאים וכו' עד סוף הפרק. משנה בפרק בתרא דבכורות (דף נ\\\"ח:):\",1,0],[8,370,8,14,\"סליקו הלכות בכורות בס\\\"ד\",2,0],[8,371,1,1,\"כל העובר בשגגה על אחת ממצות ל\\\"ת שיש בה מעשה שחייבין עליה כרת ה\\\"ז חייב להקריב קרבן חטאת וכו':\",1,0],[8,371,1,2,\"וכל עבירה שחייבים על זדונה כרת חייבים על שגגתה חטאת חוץ מג' עבירות וכו'. משנה בריש כריתות וכחכמים.\",1,0],[8,371,1,2,\"ומ\\\"ש הפסח והמילה מפני שהם מ\\\"ע וחטאת אין מביאין אלא על שגגת לא תעשה וכו'. שם (דף ג') בגמרא וכל זה יליף בת\\\"כ פרשת ויקרא מקראי.\",2,0],[8,371,1,2,\"ומ\\\"ש והמגדף מפני שאין בו מעשה כו'. שם במשנה וגמ' (דף ז').\",3,0],[8,371,1,2,\"ומ״ש לפיכך וכו'. בפרק ארבע מיתות (סנהדרין דף ס״ב):\",4,0],[8,371,1,3,\"כל כריתות שבתורה וכו'. חוץ מטמא שאכל קדש וטמא שנכנס למקדש וכו'. שם במשנה:\",1,0],[8,371,1,4,\"חטאת קבועה היא הבאה מן הבהמה בלבד וכו'. מפורש בתורה:\",1,0],[8,371,1,4,\"ומה הוא הקרבן שמביא וכו'. מקראות אלו מפורשים בתורה:\",2,0],[8,371,1,5,\"אחד יחיד ששגג באחת באלו או מרובים וכו'. משנה בפרק ב' דהוריות (דף ז':) אין חייבין אלא על העלם דבר עם שגגת המעשה וכן המשיח ופירש\\\"י אין בית דין חייבים קרבן אלא על העלם דבר עם שגגת מעשה וכן המשיח. וצבור הוא דכי עבדי בשגגת מעשה לחודיה מייתן כל חד וחד כשבה או שעירה דדיניהם כיחידים דכיון דלא עשו על פי בית דין מיחלקי כולהו מהדדי והוו יחידים ויחידים חייבים בשגגת מעשה אבל משיח בשגגת מעשה לחודיה פטור מכלום כדאמר לקמן בפרקא בתרא פרט למשיח דאינו מביא בשגגת מעשה כלל עכ\\\"ל:\",1,0],[8,371,2,1,\"אין אדם חייב חטאת על שגגתו וכו'. משנה בס״פ הזורק (שבת דף ק״ב):\",1,0],[8,371,2,2,\"עבר עבירה ויודע שהיא בלא תעשה וכו'. בריש פרק כלל גדול (שבת דף ס״ט) פלוגתא דר״י ור״ל ופסק כר״י.\",1,0],[8,371,2,2,\"ומה שכתב אבל אם ידע שהיא בכרת ושגג בקרבן וכו'. שם פלוגתא דמונבז ורבנן ופסק כרבנן:\",2,0],[8,371,2,3,\"מי שלא נודע וכו' כיצד חלב ונותר לפניו וכו'. משנה פ\\\"ד דכריתות (דף י\\\"ט) פלוגתא דר\\\"א ור' יהושע וידוע דהלכה כר' יהושע:\",1,0],[8,371,2,4,\"חטא ונודע לו חטאתו וחזר ושכחו וכו'. תוספתא פרק שני דכריתות חטא ונודע לו חטאתו ושכח באי זה חטא חטא הרי זה מביא חטאת ותשחט לשם מה שהיא ותאכל עכ\\\"ל. כלומר ישחטנה ויאמר הרי זה לשם חטאת שאני חייב אע\\\"פ שאיני זוכר מה הוא יהיה לשם מה שאני חייב על החטא שחטאתי:\",1,0],[8,371,2,4,\"וכתב הראב\\\"ד א\\\"א הא אפילו לרבי יהושע עכ\\\"ל.\",2,0],[8,371,2,4,\"ועל מ\\\"ש רבינו כשאר חטאות הנאכלות כתב הראב\\\"ד א\\\"א סיפא דתוספתא ק\\\"ל וכו'. ומאי דק\\\"ל הוא מבואר דמשמע מלישנא דתוספתא שאע\\\"פ שהביא חטאת חוזר ומביא חטאת אחרת וקשה דכיון שהביא חטאת לשם מה שהיא ונתכפר כשאח\\\"כ נודע לו באי זה חטא חטא היאך יביא חטאת אחרת הא ה\\\"ל חולין בעזרה. וכתב בעל מ\\\"ע שלא נמצא זה בתוספתא שלו וכ\\\"נ שלא היה בנוסחת רבינו ונוסחת תוספתא דידן כמו נוסחת הראב\\\"ד ומאי דק\\\"ל להראב\\\"ד אפשר ליישבו דחטאת שמביא ראשונה מכפר קצת ולכשיודע לו חטאו ויביא חטאת אחרת תגמר הכפרה:\",3,0],[8,371,2,5,\"שגג בשם אחד והם שני גופים חייב וכו'. משנה שם (דף י\\\"ט) ובפ' ספק אכל ר\\\"ש שזורי ור\\\"ש אמרו לא נחלקו על דבר שהוא משם אחד שהוא חייב:\",1,0],[8,371,2,6,\"כל המחוייב חטאת קבועה על שגגתו וכו' כיצד תינוק שנשבה לבין העכו״ם וכו'. בר״פ כלל גדול (שבת דף ס״ח:) רב ושמואל דאמרי תרווייהו אפי' תינוק שנשבה בין העכו״ם וכו' כהכיר ולבסוף שכח דמי וחייב ור״י ור״ל דאמרי תרווייהו דוקא הכיר ולבסוף שכח אבל תינוק שנשבה בין העכו״ם וכו' פטור ופסק כרב ושמואל והטעם משום דבגמרא אותבינן על ר״י ור״ל מברייתא ושני אמרי לך ר״י ור״ל לאו מי איכא מונבז דפטר אנן דאמרינן כמונבז ומשמע ליה ז״ל דאין לפרש דר״י ור״ל סברי דהלכה כמונבז אלא ודאי לא באו לומר אלא דאיכא מאן דסבר הכי אבל לענין הלכה כרבנן ס״ל. ועי״ל דכי אמרו ר״י ור״ל האי מימרא לא הוה שמיע להו פלוגתא דמונבז ורבנן והוו אמרי הכי מסברא וכי אותיבו עלייהו מברייתא דמונבז ורבנן דחקו עצמם לומר אנן דאמרינן כמונבז כי היכי דלא ליסלקו בתיובתא אבל לענין הלכה בתר דשמעו ברייתא דפלוגתא דמונבז ורבנן ודאי דלימרו הלכה כרבנן ואע״ג דאמרינן התם ורבנן שגגה במאי ר' יוסי אמר כיון ששגג בכרת וכו' ור״ל אמר עד שישגוג בלאו וכרת דמשמע דהוו ידעי פלוגתא דמונבז ורבנן י״ל דהאי בתר דשמעו ברייתא דפלוגתא דמונבז ורבנן כי אותיבו עלייהו מינה אבל מעיקרא לא הוה שמיע להו, ומזה קצת ראיה לומר דלענין דינא ס״ל דהלכה כרבנן מדאיפליגו בפירושא דמילתייהו:\",1,0],[8,371,2,7,\"השוגג בלא כוונה בעריות וכו'. בפ\\\"ד דכריתות (דף י\\\"ט).\",1,0],[8,371,2,7,\"ומ״ש נתכוון להגביה את התלוש וחתך את המחובר וכו'. שם ובפ' כלל גדול (שבת דף ע״ג) נתכוון להגביה את התלוש וחתך את המחובר פטור מ״ט דהא לא איכוון לשום חתיכה לחתוך את התלוש וחתך את המחובר אביי אמר חייב דהא איכוון לשום חתיכה רבא אמר פטור דהא לא איכוון לחתיכה דאיסורא, וידוע דהלכה כרבא וכ״פ רבינו בספ״ז, וא״כ צ״ל דמאי דנקט הכא רבינו נתכוון להגביה את התלוש לאו לדיוקא נקטיה אלא להיותו דבר פשוט לפיטור וסמך על מה שיכתוב בספ״ז וזה שאמר כמו שביארנו במקומו:\",2,0],[8,371,2,8,\"כל העושה מצוה מן המצות וכו' כיצד הבא על יבמתו והיא נדה וכו'. בפסחים פרק אלו דברים (פסחים דף ע״ב:) ר״י [אמר] אשתו נדה בעל חייב (דה״ל לשיולי) יבמתו נדה בעל פטור וכו' מ״ש יבמתו דקא עביד מצוה אשתו נמי קא עביד מצוה באשתו מעוברת והאיכא שמחת עונה שלא בשעת עונתה והאמר רבא חייב אדם לשמח אשתו סמוך לוסתה א״ה אפילו יבמתו נמי יבמתו בזיז מינה אשתו לא בזיז מינה, ומשמע דבאשתו נמי פטור אא״כ היתה מעוברת ושלא בשעת עונתה וסמוך לוסתה. ורבינו שסתם וכתב דבאשתו חייב נראה שסובר דכי אמרינן אשתו לא בזיז מינה תו לא צריכי לאוקמי בהני אוקמתי אלא בכל גוונא חייב כיון דלא בזיז מינה ה״ל לשיולה:\",1,0],[8,371,2,8,\"ומ״ש וכן מי שהיו לו שני תינוקות וכו'. משנה בפ' ר״א דמילה (שבת דף קל״ז) פלוגתא דר״א ורבי יהושע ויש על משנה זו לשונות בגמרא ובתר הכי אמרינן תני ר' חייא אומר היה ר״מ לא נחלקו ר״א ורבי יהושע על מי שהיו לו שני תינוקות אחד למול בע״ש ואחד למול בשבת ושכח ומל את של ע״ש בשבת שהוא חייב על מה נחלקו על מי שהיו לו שני תינוקות אחד למול אחר השבת ואחד למול בשבת ושכח ומל את שלאחר השבת בשבת שר״א מחייב חטאת ור' יהושע פוטר השתא רבי יהושע סיפא דלא קא עביד מצוה [פוטר רישא דקא עביד מצוה] מחייב אמרי דבי רבי ינאי רישא כגון שקדם ומל את של שבת בע״ש דלא ניתנה שבת לידחות סיפא ניתנה שבת לידחות. ופסק רבינו כי הני לישנא משום דר' חייא תני לה ודבי ר' ינאי מפרשי לה ועוד דבפסחים פ' אלו דברים (פסחים דף ע״ב) מוקים לה הכי. ולפ״ז אע״פ שאותו שמל בשבת לא היה ראוי למול בשבת כיון שהיה שם אחר שהיה ראוי למול פטור מאחר דניתנה שבת לידחות אצלו וא״כ יש לתמוה על רבינו שכתב ומל שניהם דמשמע שאם לא מל אלא אותו שלא היה ראוי למול בשבת חייב וצ״ל דלא נקט רבינו ומל שניהם אלא משום חלוקת אחד למול בע״ש ואחד למול בשבת דאם מל של שבת בע״ש ושל ע״ש בשבת חייב הוא מאחר שלא היה שם מי שראוי למולו בשבת אבל בחלוקת אחד למול אחר השבת ואחד למול בשבת ונתחלף לו ומל שלאחר השבת בשבת פטור לר' יהושע מאחר שהיה שם מי שראוי למולו בשבת:\",2,0],[8,371,2,9,\"אומן שבא למול וכו'. שם (דף קל\\\"ג:) אמרינן דכל כי האי גוונא ענוש כרת ומשמע לרבינו דכיון דענוש כרת חייב חטאת. ויש לתמוה על רבינו שכתב ה\\\"ז חייב חטאת שהרי התרו בו שהתראה אינה טעם לחייב חטאת אלא לפטור מחטאת, וי\\\"ל דהכא שאני שלא נתכוון לעבור במזיד ולפי שהיה עולה על הדעת לפוטרו מחטאת מפני שהוא אנוס לכך כתב שמאחר שהתרו בו אינו אנוס וגם אינו מזיד כיון שלא נתכוון לעבור ולא חשיב אלא שוגג ולפיכך חייב חטאת:\",1,0],[8,371,2,10,\"המוציא את הלולב ביום טוב ראשון של חג שחל וכו'. משנה בפרק לולב הגזול (סוכה דף מ״א:) בשם ר' יוסי ובפסחים פרק אלו דברים (פסחים דף ע״א:) משמע דר' יהושע ס״ל כוותיה ואמר אביי עלה שם בסוכה לא שנו אלא שלא יצא בו אבל יצא בו קודם שהוציא חייב. ופירש״י משום דהשתא אינו טרוד בדבר מצוה וז״ש רבינו הוציא וכו' כדי לצאת בו:\",1,0],[8,371,2,10,\"וכן השוחט את הפסח וכו'. משנה בפסחים ס״פ אלו דברים (פסחים דף ע״א:):\",2,0],[8,371,2,11,\"שחט את הפסח בשבת שלא לשמו וכו'. משנה וגמרא שם.\",1,0],[8,371,2,11,\"ומ\\\"ש כמו שביארנו בהלכות פסולי המוקדשין. בפ' ט\\\"ו:\",2,0],[8,371,2,12,\"שחט זבחים אחרים לשם פסח וכו'. שם במשנה פלוגתא דר\\\"א ורבי יהושע וידוע דהלכה כר' יהושע. ומצאתי כתוב שנשאל ה\\\"ר אברהם בנו של רבינו דבפרק אלו דברים משמע דתלי פלוגתא דר\\\"מ ור\\\"ש בשוחט בשבת זבחים שאינם ראויים בפלוגתייהו דמי שיש לו שני תינוקות למול ורבינו פסק בתינוקות כר\\\"מ ובזבחים כר\\\"ש והשיב אע\\\"ג דלא ס\\\"ל כלישנא דר\\\"ש בתינוקות דמסקנא דגמ' וסוגיא דשמעתא כר\\\"מ וסבור כוותיה בזבחים דדוקיא דמתני' לאו כוותיה אזלא ולא משום דס\\\"ל בענין זבחים כר\\\"ש דאמרינן בגמרא (דף ע\\\"ב:) מאן תנא דשאני ליה בין ראויים לשאינם ראויים ר\\\"ש היא דתניא הזבחים וכו' וליכא מאן דפליג על האי אוקימתא והואיל וסתם לן תנא כר\\\"ש ש\\\"מ לית הלכתא כר\\\"מ בהא ולא מפני כן נסבור כוותיה בתינוקות דהאי כדאיתיה והאי כדאיתיה.\",1,0],[8,371,2,12,\"ומה שכתב וכן אם שגג ושחטו בשבת שלא לאוכליו וכו' עד שהרי הפסח כשר. משנה שם:\",2,0],[8,371,2,13,\"השוחט בשבת קרבן צבור שלא לשמו ה\\\"ז וכו'. בתוספתא דפסחים (פרק ה') חטאת ציבור ששחטה בשבת שלא לשמה הרי זה חייב ויקטיר אימורין לערב.\",1,0],[8,371,2,13,\"ומ״ש אם שחט יתר על חובת וכו'. במשנה פ' אלו דברים (פסחים דף ע״א:) אמרינן שהשוחט לשם אימורי צבור בשבת חייב ואיתיה נמי בתוספתא הנזכרת:\",2,0],[8,371,2,14,\"שחט קרבנות יחיד שאין דוחין את השבת וכו'. בתוספתא דפסחים פ\\\"ה חטאת היחיד ועולת יחיד ששחטן בשבת לשמן וזרק דמן שלא לשמן חייב שהורצו הבעלים ובפ\\\"ב (דף כ') נחלקו רבא ורבה בר רב הונא בעבר ושחט נדרים ונדבות ביו\\\"ט והיינו קרבן יחיד שאין דוחין שכתב רבינו.\",1,0],[8,371,2,14,\"ועל מה שכתב רבינו והבשר מותר בהנאה. כתב הר\\\"י קורקוס איני יודע מה הנאה היא זו כיון שאינו נאכל מפני שאין הדם נזרק וכתיב ודם זבחיך ישפך והדר והבשר תאכל מה הנאה יכול ליהנות בבשר קדש והרי זבח שנפסל הוא נשרף וזה זבח פסול הוא כי דם ששקעה עליו חמה נפסל הזבח כמבואר בהלכות פסולי המוקדשין:\",2,0],[8,371,2,15,\"היו לפניו שתי בהמות של צבור וכו'. מימרא דרבה במנחות פ' ר' ישמעאל (מנחות דף ס״ד.).\",1,0],[8,371,2,15,\"ומ\\\"ש נמצאת הראשונה השמינה טריפה בבני מעיים וכו'. בעיא שם ואמרינן לאו היינו דרבה ורבא דאתמר שמע שטבע תינוק בים ופירש מצודה להעלות דגים והעלה דגים חייב להעלות דגים והעלה דגים ותינוק רבה אמר פטור ורבא אמר חייב וע\\\"כ רבה לא פטר אלא כיון דשמע אמרינן דעתיה אתינוק אבל לא שמע לא ואיכא דאמרי אמר ליה היינו פלוגתא דרבה ורבא דאתמר לא שמע שטבע תינוק בים ופירש מצודה להעלות דגים והעלה דגים חייב להעלות דגים והעלה תינוק ודגים רבה אמר פטור ורבא אמר חייב רבה אמר פטור זיל בתר מעשיו ורבא אמר חייב זיל בתר מחשבתו ופסק רבינו כלישנא בתרא וכמ\\\"ד פטור וטעמו ביאר הרב המגיד בפרק שני מהלכות שבת:\",2,0],[8,371,2,16,\"מי שהיה לפניו בלילי הפסח צלי של פסח ונותר וכו'. בפסחים פ' אלו דברים (פסחים דף ע״ב) מימרא דר״ל ואיכא עליה תרי לישני בחד רבי יוחנן מחייב ובחד פטר ופסק כלישנא דמחייב ואע״ג דהוא לישנא קמא משום דלא משוי פלוגתא בין ר' יוחנן ור״ל:\",1,0],[8,371,3,1,\"מי שהעידו עליו עדים שחטא וכו'. משנה פ\\\"ג דכריתות (דף י\\\"א:) פלוגתא ופסק כחכמים:\",1,0],[8,371,3,2,\"ומ\\\"ש שתק ולא הכחיש את העדים וכו'. שם בגמרא בר\\\"פ.\",1,0],[8,371,3,2,\"ומ\\\"ש אפילו אמרה לו אשה וכו'. כן משמע שם.\",2,0],[8,371,3,2,\"אמר לו עד אחד חלב הוא זה ושתק כו':\",3,0],[8,371,3,3,\"כבר ביארנו בהלכות פסולי המוקדשין. פרק ט\\\"ו.\",1,0],[8,371,3,3,\"ומה שכתב יתר על זה אמרו הפריש חטאתו על חלב שאכל אמש וכו'. משנה בפרק ב' דכריתות [דף כ\\\"ז].\",2,0],[8,371,3,3,\"ומה שכתב ואין צריך לומר שאם הפרישה אביו ומת וכו'. שם במשנה:\",3,0],[8,371,3,3,\"כתב הר\\\"י קורקוס ז\\\"ל שם נתבאר דאפילו של מין חטאת שהופרשה כדברי רבינו דהיינו כגון מחלב על חלב ומדם לדם ובודאי דעל חטא אחר אפילו הוא גופיה לא יביאנה וזה פשוט. ומכאן תבין כי מה שאמרו לא יביאנו בנו אחריו אפילו על חטא שחייב בנו וכדברי רבינו שכתב והיה הבן מחוייב באותו החטא והדבר מעצמו מוכרח דאילו על אביו חטאת שמתו בעליה למיתה אזלא גם לאחר מיתה אין כפרה וזה פשוט. גם באותה ברייתא למדו דהוא עצמו אפילו מקלה לקלה ומחמורה לחמורה לא כיפר וכבר הוזכר ונתבאר בהלכות מעילה פרק רביעי גם בהלכות פסולי המוקדשין פרק ט\\\"ו. ונראה שמכאן למד רבינו דדוקא בששינה מחלב לדם הוא דלא כיפר אי נמי מחלב האב לחלב בנו אבל מחלב של אמש לחלב היום של עצמו כיפר ושפיר קרינן ביה קרבנו על חטאתו כיון שהוא על אותו מין ושנאמר שאמרו במשנה לא קאי אדסמיך ליה דהיינו אפילו על חלב שאכל אמש וכו' אלא אעיקרא דדינא דלא יביא מחטא על חטא לכך שינה רבינו וכתב לא יביא וכו' שנאמר וכו' ואחר כך כתב יותר על זה אמרו דהיינו שהחמירו חכמים שלא לעשות לכתחלה וזהו לשון אמרו ולכך כתב שאם עשה כיפר, וכן בתוספתא דכריתות פרק אמרו הפריש חטאת לחלב והביאה על דם על דם והביאה על חלב הרי זה מעל ולא כיפר על כרחך מוכח דמחלב לחלב כיפר והיינו דאיצטריך קרא למעוטי מאב לבן משום דבאב גופיה כיפר כיון שהוא על מין אותו חטא דאי באב גופיה לא כיפר קרא בבן למה לי וזה מוכרח עכ\\\"ל:\",4,0],[8,371,3,6,\"המביא חטאת על שני חטאים וכו' וכן שנים שהביאו חטאת אחת על שני חטאיהם וכו' עד לשם החטא השני. הכל תוספתא פ\\\"ב דכריתות. כתב הר\\\"י קורקוס ז\\\"ל דין שתי חטאות על שני חטאים פירוש שהפריש סתם שני אלו על שני חטאים ויכול לפרש אח\\\"כ כאשר ירצה ושפיר קרינן ביה קרבנו על חטאתו כי אין כאן משנה מחטא לחטא. וקשה לי על זה דבשלמא אם שתי החטאות מין אחד שפיר דהוי מדרבנן כמו שנתבאר ומדרבנן יש ברירה אלא אם אחד חלב ואחד דם שהוא מדאורייתא כיון שבתחלת הפרשתם לא פירש וקי\\\"ל דבדאורייתא אין ברירה איך יוכל לפרש אח\\\"כ. ואפשר שכוונת רבינו שיקריב אחד לחטא אחד סתם ואחד לחטא אחר ולא שיפריש כל אחד לשם חטא פלוני. וכ\\\"נ קצת שכתב רבינו זו תשחט לשם חטא האחד והשנייה לשם החטא השני ולשון התוספתא כן הוא זו תשחט לשם מה שהיא וזו תשחט לשם מה שהיא עכ\\\"ל:\",1,0],[8,371,3,7,\"כבר ביארנו בהלכות מעשה הקרבנות. פ\\\"ג ושם נתבאר:\",1,0],[8,371,3,8,\"מי ששגג והפריש חטאתו וכו'. בפרק קמא דכריתות (דף ז') ופרק קמא דזבחים (דף י\\\"ב) אמר רבי יוחנן דאינו חוזר ונראה ואיתיה בפרק נגמר הדין (סנהדרין דף מ\\\"ז) , ומשמע לרבינו דרבי יוחנן לטעמיה דאמר בעלי חיים נדחין אבל לרב דאמר אין ב\\\"ח נדחין חוזר ונראה וכבר נתבאר בפרק שלישי מהלכות פסולי המוקדשין ובפרק ט\\\"ו ממעשה הקרבנות שרבינו פוסק הלכה כרב:\",1,0],[8,371,3,9,\"חייבי חטאות ואשמות ודאים וכו' עד שכל היום מכפר. משנה פרק בתרא דכריתות (דף כ\\\"ה):\",1,0],[8,371,3,10,\"אין יוה\\\"כ ולא החטאת וכו'. בפ\\\"ק דכריתות (דף ז') פלוגתא דר\\\"י ור\\\"ל ופסק כר\\\"י ואביי ורבא נמי סברי כר\\\"י:\",1,0],[8,371,3,11,\"כל אשמות שבתורה וכו'. בריש פרק ארבעה מחוסרי כפרה (כריתות דף ח':) ותניא בפ״ג דנזיר (דף י״ח:) הביא חטאתו ולא הביא אשמו מונה:\",1,0],[8,371,3,11,\"ספק נזיר וספק מחוסרי כפרה וספק סוטה כו'. פ\\\"ב דכריתות (דף צ\\\"ו):\",2,0],[8,371,3,12,\"מי שהוא מחוייב חטאת או אשם וכו'. בסוף פ\\\"ק דערכין (דף ז':):\",1,0],[8,371,4,1,\"העושה עבירות הרבה בהעלם אחת וכו'. בריש כריתות:\",1,0],[8,371,4,1,\"וכן אם עשה מעשה אחד שהוא חייב עליו משום שמות הרבה וכו'. בס״פ ד' אחין (יבמות דף ל״ד) פלוגתא דתנאי ופסק כסתם מתני'.\",2,0],[8,371,4,1,\"ומ\\\"ש כיצד השוחט בהמת קדשים וכו' עד שהרי שלשת האיסורין באים כאחד. בפ\\\"ב דחולין (דף מ').\",3,0],[8,371,4,1,\"ומ\\\"ש בד\\\"א באומר בגמר זביחה הוא עובד וכו' וכן מ\\\"ש היתה חטאת העוף וכו'. גם זה שם.\",4,0],[8,371,4,1,\"ומ״ש וכן העושה מלאכה ביוה״כ וכו'. ברייתא בס״פ גיד הנשה (חולין דף ק״א:):\",5,0],[8,371,4,1,\"הבא על אשת אחיו הקיים וכו'. משנה בס״פ ארבעה אחין (יבמות דף ל״ג:). ודע דבמתני' אמרינן שאם היו אחיות חייב עליה משום אחות אשה דה״ל איסור כולל ואיני יודע למה השמיטו רבינו. והר״י קורקוס ז״ל כתב שהטעם משום דאיסור אחות אשה הוא איסור כולל ובכל זה הפרק לא הזכיר איסור כולל כי אם בפ״ו:\",6,0],[8,371,4,1,\"הבא על אביו חייב שתים וכו' וכן הבא על אחי אביו חייב שתים וכו'. מימרא בפ' ד' מיתות (סנהדרין דף נ״ד):\",7,0],[8,371,4,1,\"הבא על הזכור והביא זכור עליו וכו' וכן הבא על הבהמה והביא בהמה עליו וכו'. שם ובריש כריתות (דף ג') פלוגתא דרבי ישמעאל ור\\\"ע ופסק כר\\\"ע, ועיין במה שכתב רבינו בפרק שאחר זה:\",8,0],[8,371,4,2,\"יש בועל בעילה אחת וחייב עליה ח' חטאות וכו'. משנה בפ\\\"ג דכריתות (דף י\\\"ג):\",1,0],[8,371,4,2,\"ומה שכתב רבינו ונשאת סרח זו לאחי יעקב מאמו. כלומר שאילו אחי יעקב מאביו נשאה לא היה שייך לומר שיבמה יצחק שהרי היתה ערוה עליו שהרי היא כלתו ואם כן אין כאן איסור אשת אב.\",2,0],[8,371,4,2,\"ומה שכתוב בספרים נוסף בה איסור ליעקב משום אשת אביו ומשום אשת אח. טעות סופר וצריך למחוק משום אשת אח ולכתוב במקומו משום אשת איש וכן מצאתי בספר מוגה:\",3,0],[8,371,4,3,\"ומה שכתב כל אלו שתאסר זו הערוה עליהם באיסור מוסיף צריך שיהיו האנשים האחרים מצויים בעולם וכו'. נלמד מדאמרינן בגמרא שם (דף פ\\\"ו:) ומי אית לרבי יוסי איסור חל על איסור וכו' ותירצו כגון דאיכא ברא לסבא וכו':\",1,0],[8,371,4,4,\"מי שהיה נשוי ג' נשים וכו'. משנה בכריתות שם:\",1,0],[8,371,4,5,\"אבל הבא על אחותו שהוא אחות אביו וכו'. גם זה משנה שם (דף ט\\\"ו) וגמרא בריש כריתות (דף ב'):\",1,0],[8,371,5,1,\"הבא על ערוה אחת ביאות הרבה וכו'. בפ\\\"ג דכריתות (דף ט\\\"ז) פלוגתא דתנאי ופסק כחכמים.\",1,0],[8,371,5,1,\"ומ״ש שהידיעות מחלקות. בפ' כלל גדול (שבת דף ע״א:):\",2,0],[8,371,5,2,\"הבא על הערוה ביאות הרבה וכו'. בפרק ג' דכריתות (דף ט\\\"ו):\",1,0],[8,371,5,3,\"הבא על עריות הרבה בהעלם אחת וכו'. משנה שם:\",1,0],[8,371,5,4,\"האשה שהביאה עליה בהמות הרבה וכו'. נלמד ממ\\\"ש קודם:\",1,0],[8,371,5,5,\"האשה שהלך בעלה למדה״י וכו'. בפ' האשה רבה (יבמות דף פ״ז:) תנן גבי אשה שהלך בעלה למדה״י ובאו ואמרו מת בעליך שאם נשאת ע״פ ב״ד תצא ופטורה מן הקרבן ואמרינן בגמרא (דף צ״ב) דזעירי אמר ליתא למתני' ואע״ג דר״נ פליג עליה הא רבא דבתרא הוא סבר כוותיה ואמרינן תו בגמרא דאף ר״א סבר הכי:\",1,0],[8,371,5,5,\"ומ\\\"ש ואם נשאת לאנשים הרבה חייבת על כל איש ואיש מפני שהם גופין מוחלקים. ברייתא שם.\",2,0],[8,371,5,5,\"ומ\\\"ש או שזינתה עם אנשים הרבה. שם במשנה (דף פ\\\"ז:) הורוה ב\\\"ד לינשא והלכה וקלקלה חייבת בקרבן ובגמרא (דף צ\\\"ב) מאי קלקלה ר\\\"א אומר זינתה ר\\\"י אמר אלמנה לכ\\\"ג גרושה וחלוצה לכהן הדיוט מ\\\"ד זינתה כ\\\"ש אלמנה לכ\\\"ג מ\\\"ד אלמנה לכ\\\"ג אבל זינתה לא מ\\\"ט אתון הוא דשויתון פנויה ותניא כוותיה דר\\\"י ומשמע דהלכה כר\\\"י ולפיכך יש לתמוה על מה שפסק רבינו שאם זינתה חייבת חטאת. וי\\\"ל דלא אתמר דר\\\"י אלא אליבא דמתני' דאמרה שאם נשאת ע\\\"פ ב\\\"ד פטורה מן הקרבן אבל כיון דאסיקנא דליתא למתני' אלא אעפ\\\"י שהורוה בית דין לינשא חייבת בקרבן אף לרבי יוחנן אין חילוק בין זינתה לנשאת דבין בזו ובין בזו חייבת בקרבן:\",3,0],[8,371,5,5,\"הבא על הנדה בשגגה וכו'. בספ\\\"ג דכריתות (דף י\\\"ז):\",4,0],[8,371,5,6,\"הבא על אשתו שלא בשעת וסתה וכו'. בפ\\\"ב דשבועות (דף י\\\"ז י\\\"ח):\",1,0],[8,371,5,6,\"ומ\\\"ש אבל אם עבר ובא עליה סמוך לוסתה וכו'. גם זה שם (דף י\\\"ח) אי שלא בשעת וסתה אנוס הוא. ומיהו אפשר דהא דחשיב ליה אנוס היינו דוקא כשבדקה לפני תשמיש אבל אם לא בדקה קודם תשמיש לא חשיב ליה אנוס דכיון שהוא ז\\\"ל סובר שאם אין לה וסת אסורה לשמש עד שתבדוק ואפילו יש לה וסת דרך הצנועות לבדוק אפשר שאף בזו אם לא בדקה אינו אנוס.\",2,0],[8,371,5,6,\"ומ\\\"ש לפיכך אם נמצא על עד שלו וכו'. משנה בפ\\\"ב דנדה (דף י\\\"ד).\",3,0],[8,371,5,6,\"ומ\\\"ש ואם שהתה כדי שתושיט ידה וכו' ואם שהתה כדי שתרד מן המטה וכו'. שם (דף ט\\\"ו) בגמרא:\",4,0],[8,371,5,7,\"מי שעבר ובעל וכו'. משנה פרק ב' דשבועות (דף י\\\"ד ע\\\"ב).\",1,0],[8,371,5,7,\"ומה שכתב ואם לא ידע שאסור לפרוש מיד וכו' עד ובהעלם אחת עשה הכל. שם (דף י\\\"ח).\",2,0],[8,371,5,7,\"ומה שכתב והוא הדין בשאר העריות. פשוט הוא:\",3,0],[8,371,6,1,\"דין שגגת המאכלות וכו'. משנה וגמרא פ\\\"ג דכריתות (דף י\\\"א ט\\\"ו:):\",1,0],[8,371,6,1,\"ומ\\\"ש אפילו הם בשלשה תמחויין. שם במשנה א\\\"ר יהושע דתמחויים מחלקים ומשמע דר\\\"ע פליג עליה וצריך טעם למה פסק כר\\\"ע דתלמידיה הוא.\",2,0],[8,371,6,1,\"ומ\\\"ש אבל אם אכל כזית חלב ונודע לו וכו'. פ\\\"ד דכריתות (דף י\\\"ז:) במשנה:\",3,0],[8,371,6,1,\"אכל כחצי זית חלב וחזר ואכל כחצי זית חלב וכו'. משנה פ\\\"ג דכריתות (דף י\\\"ח:):\",4,0],[8,371,6,2,\"אכל נותר מחמשה זבחים וכו'. גם זה שם במשנה (דף ט\\\"ז:) משמע דר\\\"ע פליג אר' יהושע ופסק רבינו כר\\\"ע אע\\\"ג דתלמידיה הוא משום שהשיב על דבריו ושתק.\",1,0],[8,371,6,2,\"ומ\\\"ש וכן השוחט חמשה זבחים בחוץ וכו'. שם במשנה ששאל ר\\\"ע והשיב ר' יהושע שחייב על כל אחד ואחד והביא ראיה לדבר ואמרי' בגמרא שהקשה ר\\\"ש על ראייתו:\",2,0],[8,371,6,3,\"הקיז דם לבהמתו וכו'. בפ\\\"ה דכריתות (דף כ\\\"ב) פלוגתא דר\\\"י ור\\\"ל ופסק כר\\\"י. אלא שיש לתמוה על מ\\\"ש רבינו בהעלם אחת דמשמע הא בשתי העלמות חייב וא\\\"כ הוי כר\\\"ל והר\\\"י קורקוס ז\\\"ל האריך ביישוב תמיהא זו ובסוף הניח הדבר בצ\\\"ע:\",1,0],[8,371,6,4,\"האוכל מאכלות הרבה וכו'. משנה פרק שלישי דכריתות (דף יג:):\",1,0],[8,371,6,4,\"וכן האוכל כזית אחד וכו' לפיכך הטמא שאכל כזית חלב והוא נותר וכו'. משנה שם.\",2,0],[8,371,6,4,\"ומ\\\"ש והוא שיצטרף אוכל אחר עם כזית זה וכו'. שם (דף י\\\"ד) בגמרא וטעמא משום דאין חייב ביום הכפורים אלא על ככותבת:\",3,0],[8,371,6,5,\"האוכל ושותה ביום הכפורים וכו'. משנה פרק בתרא דיומא (דף פ\\\"א):\",1,0],[8,371,6,6,\"העושה מלאכה ביוה״כ וכו'. ברייתא בס״פ גיד הנשה (חולין דף ק״א:) ואע״פ שכבר כתב רבינו דין זה בפ״ד חזר ושנאו כאן לחלק בינו לבין אוכל ושותה שקדם:\",1,0],[8,371,6,7,\"אכל כחצי זית חלב וכחצי זית דם וכו'. משנה פרק ג' דכריתות (י\\\"א:):\",1,0],[8,371,6,8,\"אכל כחצי זית ונודע לו וכו'. בסוף פרק הבונה (שבת דף ק\\\"ה) ובפרק ג' דכריתות (דף י\\\"ו:) פלוגתא דתנאי ופסק כחכמים:\",1,0],[8,371,6,8,\"וכן אם הוציא שתי אמות בשוגג וכו'. בסוף פרק הזורק (שבת דף ק\\\"ב):\",2,0],[8,371,6,9,\"האוכל כזית חלב וכו'. בפירקא קמא כלל גדול (דף ע\\\"א:) פלוגתא דרבי יוחנן וריש לקיש ופסק כרבי יוחנן. וכתב רבינו שידיעות מחלקות כרב אשי דאמר בתרווייהו פליגי ואף על פי שבגמרא דחו הכרע דרב אשי לא שבקינן מאי דפשיטא לרב משום דילמא דקאמר גמרא בדרך דחייה.\",1,0],[8,371,6,9,\"ומה שכתב וכן יראה לי שה\\\"ה בבעילות. כך היא הגירסא האמיתית ולא כנוסחא דגריס בפעולות. מ\\\"כ וכן הדין בבעילות ומביא שתי חטאות אף על פי שהבעילות הם בגוף אחד והאכילה היא שני גופין. או נפרש מביא חטאת אחת אף על פי שהבעילות א\\\"א לעשותן בבת אחת והאכילה אפשר לאכול שני זיתים בבת אחת ועלה על הדעת לומר דבעילות יתחייב שתים עכ\\\"ל:\",2,0],[8,371,6,10,\"אכל כזית ומחצה וכו'. שם בדף הנזכר אפילו לר\\\"י:\",1,0],[8,371,6,11,\"אכל שני זיתי חלב בהעלם אחת וכו' עד אינו צריך להביא חטאת אחרת. בדף הנזכר פלוגתא דאביי ורבא. ויש לתמוה על רבינו שלעיל בסמוך פסק באוכל כזית חלב וכזית חלב בהעלם אחת ונודע לו על הראשון וחזר ונודע לו על השני מביא שתי חטאות שהידיעות מחלקות והיינו כר\\\"י וכאן כתב אכל שני זיתי חלב בהעלם אחת ונודע על אחד מהם וחזר ואכל כזית אחר בהעלמו של שני והביא חטאת על הראשון ראשון ושני מתכפרים אלמא שאינו חייב על שניהם אלא חטאת אחת אע\\\"פ שנודע על הראשון וזה הפך מה שקדם ובפרק שאחר זה גבי מי שקצר וטחן בשגגת שבת וזדון מלאכות דבריו כיוצא מ\\\"ש כאן גבי אכל שני זיתי חלב בהעלם אחת שידיעות אינם מחלקות. וי\\\"ל שסובר רבינו דהא דאמר ר\\\"י באוכל כזית חלב וכזית חלב בהעלם אחת שהידיעות מחלקות דוקא כשנודע לו על הראשון וחזר ונודע לו על השני קודם שיביא קרבן כלל אבל אם כשנודע לו על הראשון הביא קרבן קודם שיוודע לו השני נתכפר לו על השני ואע\\\"פ שיוודע לו אח\\\"כ על השני אינו צריך להביא קרבן אחר כיון שבשעה שהקריב קרבן ראשון עדיין לא נודע מקרבן שני והיינו ההיא דאביי ורבא באכל שני זיתי חלב בהעלם אחת שאם הביא קרבן על הראשון ראשון ושני מתכפרים וכן ההיא דקצירה וטחינה. ולישנא דגמרא ולישנא דרבינו דייק כן דבההיא דר\\\"י נקטו וחזר ונודע לו על השני ובההיא דאביי ורבא לא נקטו בגמרא וחזר ונודע ומאי דנקט רבא בקצר וטחן וחזר ונודע מפרש דחזר ונודע אחר שהביא קרבן אבל אם היה נודע על השני קודם שיקריב קרבן היה חייב שתים ובההיא סלקי דר\\\"י ורבא תרווייהו כהלכתא ולא תיקשי לן הלכתא אהלכתא כדקשיא לפירש\\\"י והתוספות. ואע\\\"ג דבגמרא משמע דטפי עדיף לחיובי שתים בנודע לו אחר כפרה מבנודע לו קודם כפרה דאמרינן ור\\\"ל הא כתיב על חטאתו והביא ההיא לאחר כפרה י\\\"ל דההוא לר\\\"ל אבל לר\\\"י הוי איפכא דבנודע לו לאחר כפרה אינו חייב להביא עוד קרבן שכבר נתכפר. והוכרח רבינו לפרש כן מהטעמים שכתבתי דלא תיקשי הלכתא אהלכתא ומדיוקא דלישנא בגמרא דבדרישא נקט וחזר ונודע ובדאביי ורבא לא נקטיה, וזה מבואר מאד בדברי רבינו בפרק שאחר זה גבי מי שקצר וטחן וגם בפ' זה גבי הביא חטאת על הראשון גבי הביא חטאת על האמצעי. ולפ\\\"ז מ\\\"ש רבינו אבל אם נודע לו על שניהם כאחד מביא חטאת אחת כשנודעו לו שניהם קודם הקרבת הקרבן נודע לו על שניהם כאחד מיקרי ואע\\\"פ שהיה שהות בין ידיעה לידיעה. וי\\\"ל במ\\\"ש רבינו וכשיוודע לו על הראשון והשלישי אינו צריך להביא אחרת שכיון שהקדים שנודע לו על אחת מהם וחזר ואכל כזית בהעלמו של שני היאך אפשר לכתוב וכשיוודע לו על הראשון ולא ה\\\"ל לכתוב אלא וכשיודע לו על השלישי. וי\\\"ל שרצה רבינו לכלול בדבריו גם כשלא נודע לו הראשון מעיקרא שאם הביא קרבן על האמצעי ואח\\\"כ נודע לו מהראשון והשלישי שהוא פטור, ועי\\\"ל דה\\\"ק אם אחר שנודע לו על הראשון ואכל כזית בהעלמו של שני חזר ונעלם ממנו הראשון והביא חטאת על האמצעי נתכפר ואפילו שיחזור להוודע לו על הראשון פטור ומה שי\\\"ל עוד על דין זה אכתוב בפרק שאחר זה גבי מי שקצר וטחן:\",1,0],[8,371,6,11,\"ומצאתי שמורי הרב מו\\\"ה יעקב בי רב ז\\\"ל נשאל על לשון זה והשיב שהריטב\\\"א השיג על רבינו וכתב בלשון הזה על מה שכתב הרמב\\\"ם האוכל כזית חלב וכזית חלב בהעלם אחת וכו' דאמרינן פרק כלל גדול א\\\"ל מסתברא בין בזו ובין בזו מחלוקת הילכך לר\\\"י דקי\\\"ל כוותיה אפילו ידיעה גרידא מחלקת, ותמהני על הרמב\\\"ם היכי מזכי שטרא לבי תרי שהרי הוא עצמו פסק כן ואע\\\"פ כן כתב אכל שני זיתי חלב בהעלם אחת ונודע לו על אחד מהם וחזר ואכל כזית בהעלמו של שני והביא חטאת על הראשון ראשון ושני מתכפרים אבל שלישי לא נתכפר ואליבא דר\\\"י דקי\\\"ל כוותיה אפילו שני מתכפר עכ\\\"ל. ותמה מורי עליו למה לא השיג השגה זו יותר גדולה שאיך פסק הרמב\\\"ם היפך כל העולם שאפילו ר\\\"ל מודה שכפרה מחלקת וכתב עוד מה שאפשר לומר בזה הלשון כדי לתקנו וקודם שאפרש פירושו ראוי לדקדק שני דברים באלו השני פסקים. בפסק האחד כתב האוכל כזית חלב וכזית חלב בהעלם אחת וכו' ובפסק השני אמר אכל שני זיתי חלב בהעלם אחת וראוי לשאול למה נקט כזית חלב וכזית חלב בהעלם אחת ולמטה אמר אכל שני זיתי חלב בהעלם אחת ובגמרא כתוב בשני המאמרים אכל שני זיתי חלב בהעלם אחת. ועוד יש להקשות בזה הפסק האחרון שכתב וז\\\"ל הביא חטאת על האמצעי שלשתן מתכפרים וכו' וכשיוודע לו על הראשון ועל השלישי אין צריך להביא חטאת אחרת והא כשהביא קרבן על האמצעי כבר היה יודע מאכילת הראשון ובהעלמו של שני וידיעת הראשון אכל הזית השלישי לכן אני אומר שהזיתים שדיבר בהם רבא אכל השנים זה אחר זה בסמוך באכילה אחת ר\\\"ל שלא היה הפרש זמן בין אכילת הראשון לשני וכשאכל הג' בהעלמו של שני ידע את שתיהן בבת אחת האמצעי והשלישי.\",2,0],[8,371,6,11,\"ומ\\\"ש הרמב\\\"ם הביא קרבן על תלוי הדבר או יביא קרבן אחד של שגגת שבת ויתכפר על כלם כי היכי דאם הביא קרבן על זית האמצעי של חלב האמצעי שיתכפרו כלם ואם הביא קרבן על הזית הראשון או על השלישי צריך שתי חטאות. ודע שכפי הנושא שהוא עמוק וזר להתיישב אלו הפסקים של הרמב\\\"ם שא\\\"א ליישבו אלא בזה האופן ואם תעיין היטב במה שכתבתי שבודאי צ\\\"ע גדול תמצא שהוא דבר נאה ומתוקן כדי ליישב כוונת הרמב\\\"ם ולא יהיה סותר קצתו אל קצתו עכ\\\"ל:\",3,0],[8,371,6,12,\"מי שאכל חתיכה משתי חתיכות וכו'. בפ\\\"ד דכריתות (דף י\\\"ח:) ת\\\"ר אכל ספק חלב ונודע לו רבי אומר אומר אני כשם שמביא חטאת על כל אחד ואחד כך מביא אשם תלוי על כל אחד ואחד ר\\\"י בר יהודה ור\\\"א ור\\\"ש אומרים אינו מביא אלא אשם תלוי אחד וכו' א\\\"ר זירא כך שנה רבי ידיעות ספק מחלקות לחטאת רבא אמר אין ידיעות ספק מחלקות לחטאת אלא ה\\\"ק כשם שאם היתה לו ידיעת ודאי מביא חטאת על כל אחד ואחד כך אם היתה לו ידיעת ספק מביא אשם תלוי על כל אחד ואחד ופירש\\\"י ונודע לו שספק הוא כשם שאם יודע לו באחרונה שכלם חלב ודאי היה מביא חטאת על כל אחד ואחד דידיעות ספק שבינתיים מחלקות לחטאת דלא הוי העלם אחד כך מביא אשם תלוי על כל אחד כל זמן שלא נודע לו ידיעה ודאית כאן שנה רבי כדפרישית. ואמרינן תו בגמרא אמר ר\\\"ל ידיעת ספק מחלקות לחטאת אמר ר\\\"י אין ידיעות ספק מחלקות לחטאות אלא ה\\\"ק כשם שאם היתה לו ידיעת ודאי מביא חטאת על כל אחד ואחד כך אם היתה לו ידיעת ספק מביא אשם תלוי על כל אחד ואחד בשלמא לר\\\"י היינו דתני לאשם כחטאת אלא לר\\\"ל חטאת כאשם מיבעי ליה קשיא ומשמע לרבינו דהלכה כרבי מדשקלי וטרו אמוראי לפרושי טעמיה וכרבא דבתרא הוא וכר\\\"י לגבי ר\\\"ל ועוד דהא אסיקנא לר\\\"ל בקשיא:\",1,0],[8,371,7,1,\"המשתחוה לע\\\"ז וכו'. בפ' ד' מיתות תני ר' זכאי קמיה דר\\\"י זיבח וקיטר וניסך והשתחוה בהעלם אחת אינו חייב אלא אחת א\\\"ל פוק תני לברא ורב יוסף סבר כר\\\"י ואמרינן בתר הכי דר' אמי ס\\\"ל כר' זכאי ואביי דבתראה הוא פליג עליה הילכך קם לה הלכתא כר\\\"י.\",1,0],[8,371,7,1,\"ומה שכתב בד\\\"א בשהזיד בע\\\"ז וכו'. שם אמרינן ועשה מאחת מהנה וכו' אחת שהיא הנה זדון ע\\\"ז ושגגת עבודות הנה שהיא אחת שגגת ע\\\"ז וזדון עבודות האי שגגת ע\\\"ז היכי דמי ואסיקנא באומר מותר ואע\\\"ג דבתר הכי אמרינן דלא מצית מוקמת האי קרא בע\\\"ז מ\\\"מ דינא קושטא הוא דזדון ע\\\"ז ושגגת עבודות אינו חייב אלא אחת ושגגת ע\\\"ז וזדון עבודות חייב על כל אחת ואחת:\",2,0],[8,371,7,3,\"כלל גדול אמרו וכו'. משנה ר\\\"פ כלל גדול (דף ס\\\"ו:).\",1,0],[8,371,7,3,\"ומ\\\"ש או שנשבה והוא קטן לבין העכו\\\"ם או נתגייר והוא בין העכו\\\"ם. שם רב ושמואל ור\\\"י ור\\\"ל ופסק כרב ושמואל וכבר כתבתי הטעם בפ\\\"ב. ויש לתמוה על מ\\\"ש רבינו שנתגייר קטן דאפילו גדול נמי אפשר שלא ידע מצות שבת. וי\\\"ל משום דאם נתגייר גדול ודאי שהודיעוהו מצות שבת אבל גר קטן שמטבילין אותו ע\\\"ד ב\\\"ד א\\\"צ להודיעו.\",2,0],[8,371,7,3,\"ומ\\\"ש וכל היודע עיקר שבת וכו' וכל היודע שהיום שבת וכו'. שם במשנה.\",3,0],[8,371,7,3,\"ומ\\\"ש או ידע שהן אסורות ולא ידע שחייבים עליהם כרת. נתבאר בפ\\\"ב:\",4,0],[8,371,7,3,\"מצאתי כתוב שנשאל ה\\\"ר אברהם בנו של רבינו על לשון זה בשלמא בבא דסיפא לא קשיא לי דהיינו זדון שבת ושגגת מלאכות אלא בבא דרישא לא ידע לה לשבת אלא בעשה ואפ\\\"ה חייב על כל אחת ואחת ואנן לא אשכחן זדון שבת אלא בלאו מדאותביה לר\\\"ל שישגוג בלאו וכרת מהא דתנן אבות מלאכות ארבעים חסר אחת והוינן בה מניינא למה לי וכו' והיכי משכחת לה בזדון שבת ושגגת מלאכות בשלמא לר\\\"י דאמר כיון ששגג בכרת אע\\\"פ שהזיד בלאו משכחת לה דידע לשבת בלאו אלא לר\\\"ל דאמר עד שישגוג בלאו וכרת דידע לה בשבת במאי ואוקימנא דידע לה בתחומין ואליבא דר\\\"ע ואי ידיעת עשה שמה ידיעה נוקמה כגון שידע לשבת בעשה ולא תידוק מדקאמר ז\\\"ל ולא ידע שמלאכות אלו אסורות אבל יודע הוא במלאכות אחרות שהרי חזר ואמר אפילו עשה הל\\\"ט בהעלם אחת חייב ל\\\"ט חטאות מכלל שידיעת עשה שמה ידיעה ובתחומין ואליבא דר\\\"ע ליכא לאוקומה דלית הלכתא כוותיה ואי אמרת כגון שידע שיש מלאכות אסורות ולא ידע שאלו הל\\\"ט הן האסורות אין זה אלא אבות מלאכות דאלת\\\"ה אמאי לא משכחת לה אלא בתחומין ואליבא דר\\\"ע נוקמה לשגגת מלאכות כגון שלא ידע שאלו הל\\\"ט הן האסורות ומדלא משנינן הכי ש\\\"מ דל\\\"ש הכי ול\\\"ש הכי זדון שבת הוא ולא עוד אלא אפי' תימא דס\\\"ל כר\\\"ע הא לא אזלא אלא כר\\\"ל ובבא דסיפא דקאמר ז\\\"ל או שידע שהן אסורות ולא ידע שחייבים עליהם כרת אתי לר\\\"י דאמר כגון ששגג בכרת אע\\\"פ שהזיד בלאו דאי כר\\\"ל הא אמרת עד שישגוג בלאו וכרת ומייתי לה קרא מאשר תעשינה בשגגה וא\\\"כ ה\\\"ל חדא כר\\\"ל וחדא כר\\\"י. והשיב לעולם ידיעת עשה לא שמה ידיעה ולא פסק אלא כר\\\"י ובבא דרישא לא קשיא שדבריו ז\\\"ל מדוקדקים ולא ידע שמלאכות אלו אסורות ואפשר דידע במלאכות אחרות ודקשיא לך מדאמר בסוף אפילו עשה הארבעים חסר אחת וכו' אבבא דסיפא קאי דאמר או שידע שהן אסורות ולא ידע שחייבין עליהן כרת א\\\"נ ידע לה בתולדות ושגג באבות כולן כגון דידע שהצר בכלי צורה עובר על לא תעשה כל מלאכה שניכרת לו מלאכה זו שהיא מלאכה ושגג באב עצמו שאין המכה בפטיש אסור ולא ניכר לו ענין המלאכה בזו וכן כל כיוצא בזה ולפי זה הפירוק ליכא קושיא אפילו נאמר דאתרי בבי קאי כשאמר אפילו עשה הארבעים חסר אחת. ואפשר לפרק פירוק אחר כדאמרת כגון שידע שיש בה מלאכות אסורות ולא ידע שאלו הם הל\\\"ט ודקשיא לך א\\\"כ אמאי לא פריק הגמרא הכי אליבא דר\\\"ל טעמא דמילתא משום דר\\\"ש ס\\\"ל עד שישגוג בלאו וכרת ולפיכך נסיב הגמרא אליביה מידי דלית ביה כרת כלל דהוא תחומין ואליבא דר\\\"ע, א\\\"נ חדא מגו תרתי אשמעינן ולאו משום דלא פריק בגמרא הכי נימא דכה\\\"ג זדון מלאכות כדאמרת דלעולם אי אפשר שיהיה זדון מלאכות שלפי זה הפירוק המלאכות שידע השבת בהם והם שעלו בדעתו אינם מלאכות כלל דאבות מלאכות ארבעים חסר אחת ותו ליכא ואלו הארבעים חסר אחת שהן מלאכות הרי שגג בהן ולא ידע שהן אסורות לא הן ולא תולדותיהן עכ\\\"ל:\",5,0],[8,371,7,4,\"שכח שהיום שבת ושגג אף במלאכות וכו'. שם (דף ע':) ואסיקנא לא שנא ופירש רש\\\"י ואינו חייב אלא אחת:\",1,0],[8,371,7,5,\"העושה אב ותולדותיו וכו'. בספ\\\"ג דכריתות (דף ט\\\"ז). במשנה פלוגתא דר\\\"א ור\\\"ע ופסק כר\\\"ע:\",1,0],[8,371,7,6,\"ומ\\\"ש עשה תולדה של אב זה וכו' יראה לי שהוא חייב שתי חטאות. מצאתי כתוב שנשאל ה\\\"ר אברהם בנו של רבינו למה אמר יראה לי והלא גמרא ערוכה בריש ב\\\"ק מאי איכא בין אב לתולדה נ\\\"מ דאי עביד שני אבות בהדי הדדי א\\\"נ שתי תולדות בהדי הדדי מיחייב תרתי א\\\"כ מאי יראה לי דקאמר. והשיב לא אמר בגמרא שתי תולדות של שני אבות ולפיכך אמר יראה לי שאפשר לומר דהאי דאמרינן בגמרא שתי תולדות של אב אחד לאו אליבא דהלכתא ואפשר שנתעלם זה המקום ממנו ז\\\"ל בעת שכתב יראה לי ומ\\\"מ הדין אמת ואליבא דהלכתא עכ\\\"ל. ואני שמעתי ולא אבין מ\\\"ש שאפשר לומר דהא דאמרינן בגמרא שתי תולדות של אב אחד שהרי מק\\\"ו יש לחייב על שתי תולדות משני אבות. והר\\\"י קורקוס ז\\\"ל כתב שיש לדחוק שכתב כן רבינו מפני שיש תולדה דשייכא לשני אבות ואם התרו בו משום זה או משום זה חייב כגון משמר דאי אתרו ביה משום בורר חייב ומשום מרקד חייב והשתא אם עשה תולדה מאחת מאלו השני אבות ועשה גם תולדה זו דשייכא לאב של התולדה האחרת ולאב אחר גם כן סד\\\"א שלא יתחייב אלא אחת כיון ששתי התולדות מאב אחד הם קמ\\\"ל כיון שאחת מהן שייכא גם לאב אחר חייב שתים ושדינן זו בתר האב האחר והרי הם של שתי אבות. מ\\\"מ דוחק לפרש כן דלא הוה סתים רבינו. והיותר קרוב אצלי שלא היה גורס בגמ' א\\\"נ שתי תולדות בהדדי הדדי ולכך כתב יראה לי עכ\\\"ל:\",1,0],[8,371,7,7,\"עשה מלאכות הרבה מעין מלאכה אחת וכו'. משנה פרק כלל גדול העושה מלאכות הרבה מעין מלאכה אחת אינו חייב אלא חטאת אחת:\",1,0],[8,371,7,8,\"עשה מלאכות הרבה מעין מלאכה אחת בשבתות הרבה וכו'. משנה בספ\\\"ג דכריתות שם אמר ר\\\"ע שאלתי את ר\\\"א העושה מלאכות הרבה בשבתות הרבה מעין מלאכה אחת בהעלם אחת מהו חייב אחת על כולן או אחת על כל אחת ואחת א\\\"ל חייב על כל אחת ואחת ואיפליגו אמוראי בפירושא דמתני' ורב חסדא אמר זדון שבת ושגגת מלאכות אפילו ר\\\"ע ס\\\"ל דכגופין דמיין וכי בעי מיניה שגגת שבת וזדון מלאכות הוא דבעי מיניה דימים שבינתיים אי הויין ידיעה לחלק ופשט ליה ימים שבינתיים דהויין ידיעה לחלק וקביל מיניה ופסק רבינו כוותיה משום דאותביה לרבא ואע\\\"ג דשני שינויי דחיקי נינהו ועוד דשמואל סבר כרב חסדא כדפירש\\\"י:\",1,0],[8,371,7,10,\"מי שקצר וטחן כגרוגרת בשגגת שבת וזדון מלאכות וכו'. מימרא דרבא פרק כלל גדול (שבת דף ע':). ודע דאמרינן התם בגמ' (דף ע״א) על הא דרבא ומי אית ליה לרבא גרירא והא אתמר אכל שני זיתי חלב בהעלם אחת ונודע לו על אחד מהם וחזר ואכל כזית בהעלמו של שני אמר רבא הביא קרבן על ראשון ראשון ושני מתכפרים שלישי אינו מתכפר וכו' אביי אמר אפילו הביא קרבן על אחד מהם נתכפרו כלם בתר דשמעה מאביי סברה א״ה טחינה נמי תגרר לטחינה גרירא אית ליה גרירא דגרירא לית ליה. ומשמע דהדר ביה רבא לגבי אביי ואמר אפילו הביא קרבן על אחד מהם נתכפרו כולם וכן פירש״י וא״כ יש לתמוה על רבינו שבפרק הקודם לזה פסק כההיא דאכל שני זיתי חלב בהעלם אחת כדהוה אמר רבא שאם הביא חטאת על הראשון ראשון ושני מתכפרים שלישי אינו מתכפר וכיון דאמרינן דהדר ביה רבא לגבי אביי ה״ל למפסק שאפילו הביא קרבן על אחד מהם נתכפרו כלם. ועוד קשה ששני פסקים אלו סותרים זה את זה שאם אתה אומר בדין של פרק זה שקצירה גוררת קצירה וטחינה שעמה צריך אתה לומר בדין שבפרק שקודם זה שאפי' הביא קרבן על אחד מהם נתכפרו כלם והיאך לא פסק רבינו כן וה״ז כמזכי שטרא לבי תרי. ולתרץ זה י״ל היכי קאמר בתר דשמעה מאביי סברה ה״ל למימר הדר ביה רבא מההיא ולכן סובר רבינו שאין לפרש דהדר ביה רבא אלא ה״ק כששמע רבא שאביי סובר כמה גדול כח גרירא לדעתו שאפילו הביא קרבן על אחד מהם נתכפרו כלם סבר דמהניא גרירא לקצירה וטחינה שעמה אבל לא חשיב כח גרירא כ״כ שיועיל כאוכל שני זיתי חלב שאפילו הביא קרבן על אחד מהם נתכפרו כלם. וטעם יש בדבר לחלק בין גרירא זו לגרירא זו שבענין קצירה וטחינה שפיר שייך ביה למימר גרירא דכיון דבשגגת שבת נעשו שתיהם ה״ל כדבר אחד אבל אוכל שני זיתי חלב בהעלם אחת ההעלם אינו מצוי שיעלם ממנו שהחלב אסור אבל ההעלם הראוי הרגיל וההוה הוא שיעלם ממנו שזה חלב ויסבור שהוא שומן וא״כ כשאכל כזית חלב זה וסבור שהוא שומן ואח״כ אכל כזית חלב זה וסבור שהוא שומן הרי הם כשני דברים ואע״פ שמתכפרים שניהם בקרבן אחד מ״מ לא חשיבי כ״כ כדבר אחד לשיתכפר בקרבנו של ראשון השלישי שלא היה בהעלמו אע״פ שהיה בהעלמו של שני:\",1,0],[8,371,7,10,\"ומצאתי למורי הרב מהר\\\"י בי רב ז\\\"ל שנשאל ממנו לשון זה של רבינו והשיב שהריטב\\\"א הוקשה לו והניח הדבר בצ\\\"ע ושהוא ז\\\"ל נראה לו ליישב זה כשנאמר שאע\\\"פ שבגמ' הקשו מרבא לרבא והמתרץ הודה לדבריו זהו מפני שרצה להודות לו הקדמתו וכוונתו לומר אפילו שאודה לך שהנושאים שוים אומר לך ששמעה מאביי קבלה מיניה והדר ביה, אבל האמת הוא שהקושיא מתחלה אינו קושיא ולא דמי כלל שמי שיאמר שהעושה קצירה וטחינה בשגגת שבת אין בכאן אלא מעשה אחד שהשגגה לא היתה אלא בשסבר שלא היה שבת ואין שם אלא מעשה אחד שהוא שגגת שבת אבל באכל שני זיתי חלב יש שם שני מעשיות ומפני זה כשאנו אומרים שהקצירה גוררת קצירה וטחינה שעמה אין זה גרירא שהכל הוא דבר אחד שכיון שנתכפר שגגת שבת כל מה שעשה ג\\\"כ מתכפר שהכל הוא מעשה אחד ואינו גרירה שהכל הוא אחד אבל בענין שני זיתי חלב שאכל בהעלם אחת ונודע לו על הראשון ואכל השלישי בהעלם השני למה יתכפר השלישי בשביל השני והקרבן לא נעשה בשביל השני אלא בשביל הראשון ומפני שהיה בהעלמו מתכפר השני עכ\\\"ל:\",2,0],[8,371,7,10,\"ונסתייע מדברי המאירי. והר\\\"י קורקוס ז\\\"ל כתב שאפשר שמה שתירצו כן היינו משום דסברי דהפרשות דוקא מחלקות הילכך הכא דלא הויא אלא ידיעה לחודה לא עדיפא מההיא דקצר וטחן ואיצטריך לומר דהדר ביה אבל כיון דאסיקנא דידיעות לחודייהו מחלקות ר\\\"ל בנודע ונודע א\\\"כ מינה דידיעה דידע קודם זית שלישי חשיבא טובא ומחלקת טובא לבטל טעם גרירה. ואפשר עוד שסובר רבינו דבתר דאקשו מטחינה ותירצו גרירה אית ליה גרירה דגרירה לית ליה אין אנו צריכין עוד לומר דהדר ביה אלא אמרינן ההיא דזית שלישי אינו מתכפר עם הראשון משום דחשיב גרירה לגרירה דזית שני נקרא גרירה עם הראשון כמו שנתבאר ממ\\\"ש שהקציר' גוררת קצירה וכיון ששלישי אינו בהעלמו של ראשון חשיבא כגרירה לגרירה ודוקא גבי נושא דידן נפטר שהרי ברישא מחשיבים ארבעתן כשגגה אחת דוק ותשכח עכ\\\"ל. וכתב עוד וז\\\"ל וכתב רבינו ונודע לו על קצירה של שגגת וכו' ואילו במימרא אמרו על קצירה וטחינה כבר פירש\\\"י דעל קצירה או על טחינה קאמר ואין צריך לידיעת שתיהן וכיון שהם בהעלם אחת כל שנודע לו על אחת כנודע על שתיהן דמי ושתיהן גוררות שתים השניות וזה דעת רבינו עכ\\\"ל. על מ\\\"ש רבינו קצר כחצי גרוגרת וכו' מצאתי כתוב בספר אחר כלשון הזה כתב הראב\\\"ד אנו אין לנו אלא לחטאות ולא מצטרפי עכ\\\"ל. וכבר כתבתי טעם לדברי רבינו:\",3,0],[8,371,7,11,\"המתכוין לחתוך את התלוש וכו'. בפרק כלל גדול (שבת דף ע״ב:) ובפרק ב' דכריתות (דף י״ט) פלוגתא דאביי ורבא ופסק כרבא:\",1,0],[8,371,7,12,\"החותה גחלים בשבת שהוא מכבה את וכו'. בספ\\\"ד דכריתות (דף כ') ואע\\\"ג דאיפליגו תנאי בברייתא במלתא היכא דנתכוון לכבות ולהבעיר כ\\\"ע ל\\\"פ דחייב ופירש\\\"י החותה ממלא כלים מצבור הגחלים מכבה העליונות שעכשיו נעשות תחתונות וכבות מחמת משא של עליונות ומבעיר התחתונות מחמת משא שהיא עליהן וכשהן עכשיו עליונות מתבערות:\",1,0],[8,371,7,12,\"חתה גחלים להתחמם מהם וכו'. גם זה שם ופירש\\\"י שאינה צריכה לגופה כגון זה שאינו צריך להבעירן אלא להתחמם בחתייתן ומ\\\"מ ידוע היה שיתבערו וע\\\"מ כן עשה והוי ליה מתכוין מיהו מלאכה שאינה צריכה לגופה הויא הך הבערה עכ\\\"ל. ורבינו מפרש לה דחייב שתים משום מכבה ומבעיר ותמיהא לי שכתב בסמוך שאם נתכוון לכבות ולהבעיר חייב שתים הא אם לא נתכוון לא והכא אם נתכוון היינו הך ועוד למה איצטריך לומר שחייב משום דמלאכה שאינה צריכה לגופה חייב עליה תיפוק ליה מפני שהוא מתכוין ואם אינו מתכוין אמאי חייב וצ\\\"ע ואפשר לומר שמאחר שהוא יודע שודאי יתבערו הוי כפסיק רישיה:\",2,0],[8,371,8,1,\"כל חטא שחייבים על שגגתו חטאת קבועה וכו'. משנה פ\\\"ב דכריתות וחכ\\\"א אין מביאים אשם תלוי אלא על דבר שזדונו כרת ושגגתו חטאת.\",1,0],[8,371,8,1,\"ומ\\\"ש קבועה. כן משמע פ\\\"ב דהוריות (דף ט') וכן יתבאר ממ\\\"ש בפי\\\"א גבי מי שנתספק לו אם נכנס וכו':\",2,0],[8,371,8,2,\"אינו חייב באשם תלוי עד שיהיה שם איסור קבוע כיצד אכל חלב וספק אם היה כזית או פחות מכזית וכו'. משנה בפ\\\"ד דכריתות (דף י\\\"ז).\",1,0],[8,371,8,2,\"ומ\\\"ש או שעשה מלאכה בשבת ולא ידע מעין אי זו מלאכה ה\\\"ז מביא אשם תלוי. ולכאורה יש לתמוה שמאחר שהוא יודע ודאי שעשה מלאכה שחייב עליה חטאת מנין לו לרבינו שאינו מביא חטאת אלא אשם. וי\\\"ל שלמד כן רבינו מדתנן (דף י\\\"ט) בפ' ספק אכל חלב ונותר לפניו אכל אחד מהם ואינו יודע אי זה מהם אכל אשתו נדה ואחותו עמו בבית שגג באחת מהן ואינו יודע באי זה מהן שגג [שבת ויוה\\\"כ ועשה מלאכה בין השמשות ואינו יודע באיזה מהן עשה] ר\\\"א מחייב חטאת ור' יהושע פוטר ויהיב טעמא בגמרא לרבי יהושע משום דכתיב אשר חטא בה עד שיודע לו במה חטא ותנן נמי התם דאיפליגו על העושה מלאכה בתוך היום ואין ידוע אם בשבת עשה אם ביום הכפורים עשה או על העושה ואין ידוע מעין אי זו מלאכה עשה ופסק כר' יהושע ור\\\"ש כר' יהודה דאמר פוטר היה ר' יהושע אף מאשם תלוי. אבל קשה שבפרק זה לקמן פסק רבינו בההיא דחלב ונותר לפניו כר' יהודה דאמר פוטר היה ר' יהושע אף מאשם תלוי והכא הוא מחייבו אשם תלוי וצ\\\"ע.\",2,0],[8,371,8,2,\"ומ\\\"ש אבל אם היתה לפניו חתיכה אחת וכו'. שם (דף י\\\"ח) פלוגתא דאמוראי ורוב מנין ורוב בנין סברי דבחתיכה אחת פטור.\",3,0],[8,371,8,2,\"ומ\\\"ש וכל האוכל חלב הכוי פטור מאשם תלוי וכו' עד שהרי אין שם איסור קבוע. שם.\",4,0],[8,371,8,2,\"ומ\\\"ש וכן הבא על אשה שהיא ספק נדה או ספק ערוה וכו'. ומ\\\"ש לפיכך האשה שנמצא דם על עד שלה לאחר זמן. נתבאר בפ\\\"ה:\",5,0],[8,371,8,2,\"ומ״ש והנושא יבמתו בתוך שלשה חדשים וילדה וכו'. יש לתמוה על זה דהא תנן בפ' החולץ (יבמות דף ל״ה) ספק בן תשעה לראשון ספק בן שבעה לאחרון וכו' חייבים אשם תלוי וצ״ל דההיא מתני' אתיא כהנהו דסברי דאפי' בחתיכה אחת ספק חלב ספק שומן חייב ואע״ג דסתם לן הכי מאחר דרוב בנין ורוב מנין סברי בכריתות דהוא דוכתה דפטור הכי נקטינן וכבר רמזה רבינו בפירוש המשנה בפ' החולץ:\",6,0],[8,371,8,3,\"האוכל חתיכה וכו'. משנה ריש פרק ג' דכריתות (דף י\\\"א:). ומה שכתב הראב\\\"ד לא ידעתי היאך נקבע האיסור בכאן אלא אם כן יאמר העד חתיכה של חלב שהיתה עם השומן אכלת והאחר יאמר לא אכל אלא השומן עכ\\\"ל, אפשר לומר שלכך נתכוון רבינו. ויותר נראה לומר דשפיר מקרי איקבע איסורא על פי עד אחד אף על פי שאין שם אלא חתיכה א':\",1,0],[8,371,8,3,\"וכן כל הבא על אשת איש וכו'. נלמד ממה שקדם ובפרק ב' דכתובות (דף כ\\\"ב:) גבי שנים אומרים מת ושנים אומרים לא מת.\",2,0],[8,371,8,3,\"ומ\\\"ש אבל ספק מקודשת לא נקבע האיסור. פשוט הוא על פי מה שקדם ובפ\\\"ב דכתובות גבי שנים אומרים לא נתקדשה:\",3,0],[8,371,8,4,\"מי שהיו לפניו שתי חתיכות וכו'. ברייתא פרק ד' דכריתות (דף י\\\"ח) ובבא עכו\\\"ם או כלב ואכל את הראשונה ובא ישראל ואכל את השנייה וכן באכל את הראשונה במזיד והשנייה בשוגג קתני פטור ורבי מחייב ובאכלוה שנים בשוגג שניהם חייבים לרבי אבל לרבנן השני פטור מן הדין ופסק רבינו כרבי ונראה שטעמו משום דעל מאי דאמר רב שאינו חייב אשם תלוי על חתיכה אחת ספק אמרו תלת אמוראי כל חד טעמא חד ופסק רבינו כמאן דיהיב טעמא משום דבעינן דאיקבע איסורא ולההוא טעמא בכל הני כיון דאיקבע איסורא חייב כרבי וכיון דרב סבר כרבי פסק כוותיה אבל קשה דה\\\"ט ר\\\"נ אמריה ורבא ור' זירא יהבי טעמי אחריני ולהנהו טעמי אמרינן דפטור בהני וכרבנן וכיון דרבא דבתרא הוא פטר ור' זירא נמי סבר כוותיה ואתו כרבנן אמאי שבקינהו ופסק כר\\\"נ וכרבי דיחידאה הוא וצ\\\"ע:\",1,0],[8,371,8,5,\"חלב ונותר לפניו וכו'. במשנה פ\\\"ד דכריתות (דף י\\\"ט) פלוגתא דר\\\"א ורבי יהושע וכרבי יהודה דאמר פוטר היה רבי יהושע אף מאשם תלוי:\",1,0],[8,371,8,6,\"כל דבר שחייבים על ודאו חטאת קבועה וכו' כיצד כשם שאם אכל חלב ודם וכו'. משנה שם (דף י\\\"ז):\",1,0],[8,371,8,7,\"האוכל חתיכה משתי חתיכות וכו'. שם (דף י\\\"ח) ברייתא פלוגתא דתנאי ופסק כרבי אע\\\"ג דרבים פליגי עליה משום דמפרשי אמוראי למילתיה:\",1,0],[8,371,8,9,\"חתיכה של שומן וכו' עד סוף הפרק. בפ\\\"ה דכריתות (דף כ\\\"ג) משנה:\",1,0],[8,371,9,1,\"על חמש עבירות מביאין קרבן אשם וכו'. מפורש בתורה ואיתיה במשנה פרק איזהו מקומן (זבחים דף נ״ד):\",1,0],[8,371,9,1,\"על שפחה חרופה כיצד וכו'. משנה וגמ' בפ\\\"ב דכריתות (דף ט').\",2,0],[8,371,9,1,\"ומ\\\"ש והוא שתהיה גדולה ומזידה. פשוט הוא דאל\\\"כ לא תתחייב מלקות.\",3,0],[8,371,9,1,\"ומ\\\"ש ותהיה בעולה. מימרא שם (דף י\\\"א):\",4,0],[8,371,9,2,\"ומ\\\"ש ומפי השמועה למדו וכו'. ברייתא וגמרא בדף הנזכר:\",1,0],[8,371,9,3,\"בן תשע שנים ויום אחד וכו': כתב הראב\\\"ד בן תשע שנים ויום אחד וכו' א\\\"א אומר אני שזה שיבוש וכו'. ועוד היה לו להקשות שאפילו בגדול אין האיש לוקה אלא האשה. ולפי האמת ספר מוטעה נזדמן להראב\\\"ד בדברי רבינו והנוסחא שלנו היא לוקה והוא מביא קרבן והיא הנוסחא האמיתית ואף על גב דבפרק ב' דכריתות (דף י\\\"א) אהא דתנן כל העריות אחד גדול ואחד קטן קטן פטור מסקינן דה\\\"ק כל עריות אחד גדול ואחד קטן קטן פטור וגדול חייב הכא גדול נמי פטור מ\\\"ט דהא מקישין אהדדי ולפי זה לכאורה הל\\\"ל שהיא לא תלקה אי אפשר לומר כן דהא איתא תו התם תנו רבנן בזמן שהאשה לוקה האיש מביא קרבן אין האשה לוקה אין האיש מביא קרבן ויליף לה מקרא והשתא כי אמרינן דבשפחה אחד גדול ואחד קטן גדול נמי פטור היינו דוקא בשהשפחה קטנה שאינה לוקה אז גדול הבא עליה פטור מקרבן אבל אם השפחה גדולה והבא עליה קטן היא לוקה מאחר שהיא גדולה שהאיש נתלה באשה ואין האשה נתלית באיש ומשמע לרבינו שמאחר שהיא חייבת גם הוא חייב בקרבן אלא שאינו מביאו עד שיגדיל ובתורת כהנים איש פרט לקטן יכול שאני מוציא בן תשע שנים תלמוד לומר ואיש:\",1,0],[8,371,9,4,\"כבר ביארנו בהל' ביאות אסורות. פ\\\"ג.\",1,0],[8,371,9,4,\"ומ\\\"ש לפיכך אם אמרו לו שנים בעלת שפחה חרופה וכו'. בפ\\\"ג דכריתות (דף י\\\"ב:):\",2,0],[8,371,9,5,\"הבא על השפחה ביאות הרבה וכו'. משנה וגמ' בפ\\\"ב דכריתות (דף ט').\",1,0],[8,371,9,5,\"ומ\\\"ש בד\\\"א בשפחה אחת וכו'. שם בעיא דאיפשיטא:\",2,0],[8,371,9,6,\"בעל שפחה והפריש אשמו וכו'. בפרק כלל גדול (שבת דף ע״ב):\",1,0],[8,371,9,7,\"על הגזל כיצד וכו'. בפרק הגוזל עצים משנה (דף ק\\\"ג:):\",1,0],[8,371,9,7,\"כבר ביארנו בהלכות שבועות. בפ\\\"ז ופ\\\"ח:\",2,0],[8,371,9,8,\"על המעילה כיצד וכו'. משנה וגמרא בפרק הזהב (בבא מציעא דף נ״ה):\",1,0],[8,371,9,9,\"האוכל מדבר שמועלין בו וכו'. משנה פרק ג' דכריתות (דף ט\\\"ו:):\",1,0],[8,371,9,9,\"חומרא יתירה יש במעילה וכו'. שם במשנה:\",2,0],[8,371,9,10,\"כל המחוייב אשם ודאי וכו'. בפרק כלל גדול (שבת דף ע״א:) אמרינן למ״ד אשם ודאי לא בעי ידיעה בתחלה בעל ה' בעילות וכו' וכתב רש״י דפלוגתא דר״ט ור״ע הוא פרק דם שחיטה דר״ע סבר דבעי ידיעה בתחלה ופסק כמותו:\",1,0],[8,371,9,10,\"וכל חטא שחייבים עליו אשם ודאי אחד המלך וכו'. משנה פ\\\"ב דהוריות (דף ט'):\",2,0],[8,371,9,11,\"כל חטא שחייבים עליו וכו'. במשנה פרק חמישי דכריתות (דף כ\\\"ב:) פלוגתא דר\\\"ע ות\\\"ק ומייתי לה בר\\\"פ איזהו מקומן ופסק כת\\\"ק:\",1,0],[8,371,9,12,\"היתה לפניו חתיכה של חולין וכו' עד סוף הפרק. משנה שם:\",1,0],[8,371,9,13,\"כבר ביארנו בהלכות מאכלות אסורות. פרק ארבעה עשר:\",1,0],[8,371,10,1,\"ששה מצותן שיקריבו קרבן עולה ויורד ואלו הן וכו'. משנה בפ\\\"ב דכריתות (דף י':) ובמשנה תנן ה' משום דמני מקדש וקדשיו בחדא ורבינו מני להו בתרתי:\",1,0],[8,371,10,2,\"ומ\\\"ש אפילו היתה ידה משגת לשה ואינה משגת לנכסיו מביאה קרבן עני. בת\\\"כ פרשת תזריע יש לה שה ואין לה צרוכין מנין שתביא קרבן עני ת\\\"ל די שה:\",1,0],[8,371,10,5,\"מפי השמועה למדו שזה שחייב וכו'. ברייתא פירקא קמא דשבועות (דף ו':).\",1,0],[8,371,10,5,\"ומ\\\"ש אע\\\"פ שהדבר מפי הקבלה הרי הוא כמפורש שהרי בפירוש חייבה תורה כרת לטמא שאכל קדש וכו':\",2,0],[8,371,10,6,\"כל קרבנות שהאשה חייבת וכו' עד ומאכילן. בסוף נגעים (משנה י\\\"ב) אע\\\"ג דרבי קתני לה משמע דליכא מאן דפליג עליה ומייתי האי מתני' בפ\\\"ד דנדרים (דף ל\\\"ה:) ובפרק התקבל (דף ק\\\"ד) (ובפ\\\"ד דנזיר דף כ\\\"ד):\",1,0],[8,371,10,7,\"המלך וכהן משיח מביאין קרבנן וכו': כתב הראב\\\"ד מביאין קרבנן על שבועת העדות א\\\"א אין המלך חייב בשמיעת הקול וכו'. וטעמו מדתנן בפ\\\"ב דהוריות (דף ח':) על ב\\\"ד וכהן משיח אין חייבים על שמיעת קול ועל ביטוי שפתים ועל טומאת מקדש וקדשיו והנשיא כיוצא בהן דברי ר\\\"י הגלילי ר\\\"ע אומר הנשיא חייב בכולם חוץ משמיעת קול שהמלך לא דן ולא דנין אותו וסובר דהלכה כר\\\"ע. וטעם רבינו מדתנן בההוא פירקא בתר הכי על שמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו ב\\\"ד פטורים והיחיד והנשיא והמשיח חייבים אלא שאין כ\\\"ג [משיח] חייב על טומאת מקדש וקדשיו דברי ר\\\"ש ומה הן מביאין קרבן עולה ויורד ר\\\"א אומר הנשיא מביא שעיר ושתי משניות אלו סותרות זו את זו דברישא קתני שאין כהן משיח חייב על שמיעת קול ועל ביטוי שפתים ועל טומאת מקדש וקדשיו ובסיפא קתני שהוא חייב עליהם ולפיכך הוצרך לפרש דמאי דקתני ברישא שאין כהן משיח חייב על אלו היינו לענין שאם הורה לעצמו שוגג ועשה שוגג שדינו שמביא פר כמו שנתבאר בפט\\\"ו ועל שמיעת קול וביטוי שפתים וטומאת מקדש וקדשיו אינו חייב להביא פר כדין כהן משיח ומאי דקתני בסיפא שעל שמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו חייב כהן משיח היינו לומר שחייב להביא קרבן עליהם כשאר ההדיוטות וכ\\\"כ רבינו ז\\\"ל בפירוש המשנה דייקא דקתני בסיפא ומה הן מביאין קרבן עולה ויורד שהוא קרבן הדיוט. ולענין דברי ר\\\"ע סובר רבינו שאין הלכה כר\\\"ע משום דמשמע דיחידאה הוא ואין לומר היכי אפשר דפליגי ארבי עקיבא דהא דינא בטעמא קאמר שהמלך לא דן ולא דנין אותו י\\\"ל דהא לא מכרעא דהא אמרינן בפרק כ\\\"ג ל\\\"ש אלא מלכי ישראל אבל מלכי בית דוד כתיב בהו דינו לבקר משפט ויש לתמוה על הראב\\\"ד שנראה מדבריו שאין כ\\\"ג חייב על טומאת מקדש וקדשיו אפילו בהדיוט היאך יישב מתני' דמחייבת לכהן משיח בטומאת מקדש וקדשיו. ויש לדקדק בדברי הראב\\\"ד למה לא כתב ולא המשיח בשמיעת קול כדתנן בההיא מתני' שכתבתי בסמוך ואפשר לומר דסמך אשמיעת קול דרישא וה\\\"ק אין המלך חייב בשמיעת קול ולא המשיח בשמיעת קול ולא בטומאת מקדש וקדשיו אבל קשה למה לא כתב שכהן משיח פטור משבועת ביטוי כדתנן בההיא מתניתין:\",1,0],[8,371,10,7,\"כבר ביארנו בהלכות שבועות. פ\\\"ט ופי\\\"א:\",2,0],[8,371,10,8,\"כל המביא קרבן על הזדון וכו'. בתוספתא דכריתות פ\\\"ק ארבעה מביאין על הזדון כשגגה כולם באונס פטורים חוץ מן הנזיר וטעם למה הנזיר חייב באונס נתבאר בפ\\\"ד ממחוסרי כפרה דהיינו משום דכתיב פתע פתאום פתע זה שוגג פתאום זה האונס ומדאיצטריך רחמנא לרבויי אונס בנזיר משמע דבעלמא פטור וכדקי\\\"ל אנוס רחמנא פטריה ורבינו לא מוציא כאן נזיר מהכלל לחייבו באונס מפני שסמך על מה שכתב במקומו פ\\\"ו:\",1,0],[8,371,10,9,\"מי שהפריש מעות לכבשה של חטאתו וכו'. משנה בפ' בתרא דכריתות (דף כ\\\"ז:).\",1,0],[8,371,10,9,\"ומה שכתב ויחלל אותם על המעות וכו'. פשוט הוא:\",2,0],[8,371,10,10,\"אפילו היה מורישו גוסס הרי זה עני וכו'. בפ\\\"ג דערכין (דף י\\\"ח):\",1,0],[8,371,10,11,\"עשיר שהפריש כבשה או שעירה וכו'. משנה וגמרא בסוף כריתות (דף כ\\\"ו ע\\\"ב):\",1,0],[8,371,10,12,\"הפריש עשירית האיפה והעשיר כו'. תוספתא דכריתות בפרק בתרא:\",1,0],[8,371,10,13,\"עשיר שהפריש קן וכו'. בסוף כריתות (דף כ\\\"ז כ\\\"ח) אמרינן איפכא משום דדחוי מעיקרא הוי ורבינו פוסק כמ\\\"ד דלא הוי דחוי כמו שנתבאר בפ\\\"ג מהל' פסולי המוקדשין:\",1,0],[8,371,10,13,\"עני שהקריב קרבן עשיר וכו'. בסוף נגעים:\",2,0],[8,371,11,1,\"שינוי יש בשגגת טומאת מקדש וקדשיו וכו' אבל בטומאת מקדש וקדשיו וכו' בסוף והעלם בינתיים וכו'. משנה בפ\\\"ק דשבועות ובתוספתא פ\\\"ה דזבחים שהפיגול והנותר בידיעה אחת והטומאה בשתי ידיעות.\",1,0],[8,371,11,1,\"ומ\\\"ש כיצד נטמא וידע שנטמא וידע שזה מקדש וזה קדש וכו'. משנה בפ\\\"ב דשבועות (דף י\\\"ד):\",2,0],[8,371,11,1,\"ומנין שדין שגגת מקדש וקדשיו כך הוא וכו'. ברייתא בפ\\\"ק דשבועות (דף ד') וכרבי דסבר כר' ישמעאל דמחייב על העלם הטומאה ועל העלם המקדש וסבר כר\\\"ע דבעי ידיעה בתחלה ובסוף:\",3,0],[8,371,11,2,\"נטמא וידע שנטמא וכו'. במשנה סוף פ\\\"ב דשבועות (דף י\\\"ד:) פלוגתא דתנאי ופסק דלא כר\\\"א דר\\\"ע ור' ישמעאל פליגי עליה ובפלוגתא דר\\\"ע ור' ישמעאל פסק כרבי ישמעאל דמחייב על העלם הטומאה ועל העלם המקדש משום דרבי סבר כוותיה כמ\\\"ש בסמוך.\",1,0],[8,371,11,2,\"ומה שכתב אבל אם נעלם ממנו הלכות טומאה כגון שנטמא בכעדשה מן השרץ וכו' וכן מי שלא ראה המקדש מימיו וכו'. בפ\\\"ב דשבועות (דף י\\\"ט) בעיי דלא איפשיטו:\",2,0],[8,371,11,3,\"מי שנטמא בעזרה וכו'. משנה בפרק שני דשבועות (דף י\\\"ד):\",1,0],[8,371,11,4,\"מי שטימא עצמו במזיד וכו' עד או אינו כעזרה. שם (דף י\\\"ז) בעיי דלא איפשיטו:\",1,0],[8,371,11,5,\"מי שנסתפק לו אם נכנס למקדש וכו'. משנה בפ\\\"ק דכריתות תנן על אלו חייבין על זדונן כרת ועל שגגתן חטאת ועל לא הודע שלהם אשם תלוי חוץ מן מטמא מקדש וקדשיו מפני שהוא בעולה ויורד ומפרש בגמרא (דף ז') דהכי קאמר חוץ ממטמא מקדש וקדשיו שאינו מביא אשם תלוי ופירש\\\"י שאין אשם תלוי בא אלא על ספק חטאת קבועה כדמפרש בפ\\\"ב דכריתות וחכ\\\"א אין מביאין אשם תלוי אלא על הדבר שזדונו כרת ושגגתו חטאת ומפרש טעמא בגמרא דיליף מצות מצות מחטאת חלב:\",1,0],[8,371,11,6,\"מי שהיו לפניו שני שבילין וכו' ובעת שהלך שכח שהלך בראשון וכו'. בפ\\\"ד דכריתות (דף י\\\"ח י\\\"ט) פלוגתא דתנאי ופסק כת\\\"ק:\",1,0],[8,371,11,6,\"ומ\\\"ש הלך בראשון ונכנס למקדש וכו'. שם בברייתא הנזכרת:\",2,0],[8,371,11,7,\"ומה שכתב הזה שלישי ושביעי וטבל וכו'. בברייתא הנזכרת ופסק כתנא קמא ואליבא דר\\\"י דאוקמה כרבנן:\",1,0],[8,371,11,8,\"היה טמא ואמרו לו שנים נכנסת למקדש וכו' אמרו לו שנים טמא היית כשנכנסת למקדש וכו'. בפרק ג' דכריתות (דף י\\\"א:) תנן שנים אומרים אכלת (חלב) והוא אומר לא אכלתי ר' מאיר מחייב אמר ר\\\"מ אם הביאוהו שנים לידי מיתה החמורה לא יביאוהו לידי קרבן הקל אמרו לו מה אם ירצה יאמר מזיד הייתי ודברי רבינו בשתי בבות אלו תמוהים דבבבא קמייתא כתב דברי חכמים שאם ירצה יאמר מזיד הייתי ובבבא שנית כתב דברי ר\\\"מ אם הביאוהו שנים לידי מיתה החמורה וכו'. ולבאר זה צריך להעתיק לשון הגמרא גרסינן התם (דף י\\\"ב) איבעיא להו מ\\\"ט דרבנן משום דאדם נאמן על עצמו יותר ממאה איש או דילמא משום דאמרינן מיגו דאי בעי אמר מזיד הייתי פטור כי אמר נמי לא אכלתי מהימן ופטור ומאי נ\\\"מ למפשט מינה לטומאה דאי אמרת טעמייהו דרבנן משום דאדם נאמן על עצמו יותר ממאה ל\\\"ש טומאה חדשה ול\\\"ש טומאה ישנה ואי אמרת טעמייהו דרבנן משום דאמרינן מיגו כי פטרי ליה רבנן מטומאה ישנה אבל מטומאה חדשה מיחייב מ\\\"ט טומאה ישנה מיגו דאי בעי אמר טבלתי פטור כי אמר נמי לא נטמאתי פטור דאיכא למימר מאי לא נטמאתי דקאמר לא עמדתי בטומאתי אלא טבלתי אבל טומאה חדשה מיחייב מ\\\"ט דכי אמר נמי טבלתי מיחייב דאמרי ליה עדים השתא נטמאת מאי ת\\\"ש א\\\"ל ע\\\"א נטמאת והוא אומר לא נטמאתי פטור יכול אפילו שנים אמר ר\\\"מ ק\\\"ו אם הביאוהו שנים למיתה החמורה לא יביאוהו לידי קרבן קל וחכ\\\"א אדם נאמן על עצמו יותר ממאה איש ש\\\"מ טעמייהו דרבנן משום דאמרינן אדם נאמן על עצמו יותר ממאה איש אמר רבי אמי לעולם טעמא דרבנן משום דאמרינן מיגו וה\\\"ק מתוך שאם רצה לומר לא נטמאתי פטור הילכך אדם נאמן ע\\\"י עצמו יותר ממאה איש א\\\"ה היינו חלב מהו דתימא אכלתי חלב קמתריץ דיבוריה לא אכלתי שוגג אלא מזיד אבל נטמאתי והוא אומר לא נטמאתי לא קמתריץ דיבוריה קא משמע לן ה\\\"נ לא עמדתי בטומאתי אבל טבלתי ת\\\"ש וכו' א\\\"ל ע\\\"א נטמאת והוא אומר לא נטמאתי פטור יכול אפי' שנים מכחישים אמר ר\\\"מ אם הביאוהו שנים לידי מיתה החמורה לא יביאוהו לידי קרבן הקל ר\\\"י אומר נאמן אדם על עצמו יותר ממאה איש ומודים חכמים לר\\\"י בחלבים ובביאת מקדש אבל בטומאה לא מודו ליה במאי עסקינן אילימא בטומאה ישנה מ\\\"ש חלבים וביאת מקדש דמודו ליה דאם רצה יאמר מזיד הייתי טומאה ישנה נמי מתרץ דיבוריה דאם רצה יאמר לא עמדתי בטומאתי אלא טבלתי אמר רבינא לעולם בטומאה ישנה וכגון דאמרי ליה עדים אכלת קדשים בטומאת הגוף והוא א\\\"ל לא נטמאתי דהכא לא מתרץ דיבוריה דל\\\"ל לא עמדתי בטומאה אבל טבלתי מאי א\\\"ל טבלתי ואכלתי כי א\\\"ל הכי אתכחש ליה דיבוריה. ופירש\\\"י מיגו דאי בעי וכו' אם היה רוצה לשקר היה יכול לומר מזיד הייתי ומה שאמרתי לא אכלתי לא אכלתי שוגג אלא מזיד. לטומאה כגון א\\\"ל נטמאת ומיד באת למקדש. טומאה ישנה אתמול נטמאת והיום נכנסת. טומאה חדשה ליכא מיגו דטבלתי ל\\\"ל דהא א\\\"ל בשעת טומאה נכנסת וא\\\"נ טבלת לא העריב שמשך וכו' וליכא למימר נמי מזיד דבעינן דליתרץ דיבוריה ואי הוה אמר לא נכנסתי הוה מתרץ דיבוריה לא נכנסתי שוגג אלא מזיד אבל כיון דא\\\"ל לא נטמאתי כי אמר נמי לא נטמאתי שוגג אלא מזיד לא מיפטר מקרבן דטומאה לא איכפת לן אי שוגג אי מזיד הוה וביאת מקדש הואי שוגג וכו'. לעולם טעמייהו דרבנן משום מיגו ובטומאה ישנה הוא דפליגי וכו'. אבל בטומאה כגון היכא דאמר לא נטמאתי לא מודו ליה ולא ס\\\"ל דפטור אלמא טעמייהו דרבנן משום דמיגו דמתרץ דיבוריה כגון לא עשיתי שוגג אלא מזיד אבל גבי לא נטמאתי וכו' לא מודו לר\\\"י ואיפשיט בעיין דטעמא משום מיגו [ותו לא מידי] וקא פריך גמרא דבאי זה טומאה עסקינן דליכא מיגו אי בטומאה ישנה הא איכא מיגו ואמאי לא מודו ליה בישנה. אמר רבינא לעולם איכא ישנה דלית בה מיגו. וכגון דאמרי נטמאת אתמול ואכלת היום קדשים דהיינו טומאת הגוף ונתחייבת חטאת והוא אומר לא נטמאתי ואכחשינהו בין באכילה בין בנגיעה דלא אכל ולא נגע קדשים בטומאה ואי הדר אמר השתא לא נטמאתי דקא אמינא לא עמדתי בטומאה לא קא מכוין למיפטר מקרבן. ל\\\"א מאכילה דאית בה קרבן מכחיש להו מנגיעה לא מכחיש להו ואיתכחש בדוכתיה בטומאת מגע קמא. מודים חכמים לר\\\"י בחלבים ובביאת מקדש דשייך בהו קרבן אבל בטומאה גרידתא בלא ביאת מקדש דליכא קרבן לא מודו ליה בטומאה ולא נגע בטהרות ובמאי עסקינן אי בטומאה ישנה וכו' אלא מדפסיק ותני דלא מודו ליה בשום טומאה ש\\\"מ טעמא לאו משום מיגו. בטומאה ישנה איכא מיגו אלא טעמא משום דאדם נאמן על עצמו הילכך היכא דאיכא קרבן הכי אבל בטומאה גרידתא לא. אמר רבינא לעולם טעמא משום מיגו בחלבים ובטומאת מקדש איכא מיגו דלא נכנסתי שוגג אלא מזיד וגבי טומאה דלא מודו ליה משום דליכא מיגו ואע\\\"ג דשייך ביה קרבן ואיכא טומאה ישנה דלית בה מיגו כגון א\\\"ל אכלת חלב קדשים וכו'. והתוס' [בד\\\"ה ודחי רבינא] פירשו בשם ר\\\"י לעולם בטומאה ישנה דקאמרי רבנן דחייב כגון דקאמרי עדים אכלת קדשים בטומאת הגוף והוא אומר לא נטמאתי דלא חשבי רבנן דמתרץ דיבוריה בהא דאי הוה אמרינן שר\\\"ל לא עמדתי בטומאתי אלא טבלתי תחלה כבר אתכחיש ליה מיגו קמא שאמר לא נטמאתי דמשמע לא שוגג ולא מזיד כיון שלא השיב להם על האכילה כמו שאמרו לו. ורבינו נראה שהוא פסק כדאמר רבינא ואע\\\"ג דלכאורה משמע דדרך דחייה אתמר משמע ליה לרבינו דהוי מסקנא וקושטא דמילתא משום דמסתבר טעמיה והוא מפרש דברי רבינא דע\\\"כ לא פליגי רבנן עליה דר\\\"מ אלא כשא\\\"ל נכנסת והוא אומר לא נכנסתי דלא מכחיש סהדי משום דמצי מתרץ דיבוריה לא נכנסתי שוגג אלא מזיד והוי דומיא דחלבים אבל כי א\\\"ל אכלת קדשים בטומאת הגוף והוא אומר לא נטמאתי דלא מצי מתרץ דיבוריה משום דאי הוה מהדר להו לא אכלתי כדאמרו ליה אי הוה טומאה ישנה ה\\\"מ מתרץ דיבוריה לא אכלתי בטומאה שטבלתי קודם אבל השתא דאינהו אמרי ליה אכלת בטומאה והוא מהדר להו לא נטמאתי ודאי משמע דהכי קאמר להו לא נטמאתי מעולם וכיון דקא מכחיש להו לסהדי מודו רבנן לר\\\"מ דאינו נאמן אפילו בטומאה ישנה שאם הביאוהו שנים לידי מיתה החמורה וכו'. ודקדק רבינו לכתוב בבבא השנית וידעת שאתה טמא משום דאל\\\"כ לא יתחייב קרבן כמ\\\"ש בר\\\"פ זה:\",1,0],[8,371,11,8,\"ועדיין יש לדקדק בדברי רבינו דאמרינן התם בגמ' אמר ר\\\"נ הלכה כר' יהודה אמר רב יוסף לא אמרה אלא בינו לבין עצמו ולעצמו וכיון דאיפסיקא בגמרא הלכתא כר' יהודה דאמר הוא נאמן על עצמו יותר ממאה איש אפי' שמכחיש לסהדי מהימן ולמה פסק רבינו דכי מכחיש לסהדי לא מהימן וכבר השיגו הראב\\\"ד בזה וכתב וז\\\"ל א\\\"א זו הסוגיא שלנו וכו'. ונ\\\"ל שרבינו סובר שמה שאמר ר\\\"נ הלכה כר' יהודה לא לענין קרבן אמר אלא לענין טהרות שהוא נוגע בהן שהן טהורות וזהו שאמר רב יוסף לא אמרה אלא בינו לבין עצמו וכו' כלומר לא אמר ר\\\"ל דהלכה כר' יהודה לענין קרבן אלא לענין טהרות שנגע בהם בלבד ואף גם זאת לעצמו דוקא הוא דנאמן לאכלם אבל אחרים אינם רשאים לאכלם והוא עצמו ג\\\"כ אינו רשאי לאכלם בפני אחרים כדי שלא יזלזלו בטהרות אבל ענין קרבן פשיטא דהלכה כרבנן. ולדברי הראב\\\"ד שמפרש דלא אמר ר' יהודה אלא בינו לבין עצמו שלא יגע בטהרות אחרים דמשמע דלא איירי ר' יהודה לענין קרבן אלא לענין טהרות בלבד קשה שמתחלת דבריו משמע דלענין קרבן איירי ר' יהודה ועוד דבהדיא משמע הכי בגמרא ואם נאמר דה\\\"ק לענין קרבן מיירי ר\\\"י ולענין אכילת טהרות לא אמרה אלא בשל עצמו איני יודע מה לו להראב\\\"ד להזכיר זה:\",2,0],[8,371,11,9,\"טומאת מקדש וקדשיו שהיה לה ידיעה בתחלה וכו'. משנה בפ\\\"ק דשבועות.\",1,0],[8,371,11,9,\"ומ\\\"ש על שאין בה ידיעה לא בתחלה ולא בסוף וכו'. שם במשנה פלוגתא דתנאי ופסק כר' יהודה.\",2,0],[8,371,11,9,\"ומ\\\"ש ועל זדון טומאת מקדש וקדשיו וכו'. שם במשנה:\",3,0],[8,371,12,1,\"כל דבר שחייבין על שגגתו חטאת קבועה וכו'. משנה פ\\\"ב דהוריות (דף ח').\",1,0],[8,371,12,1,\"ומ\\\"ש הרי ב\\\"ד חייבים להביא קרבן חטאת של שגגתן בהוראה וכו' עד מפני שתלו בב\\\"ד. משנה שם בפ\\\"ק (דף ג':):\",2,0],[8,371,12,1,\"ומה הוא הקרבן שמביאים על שגגה זו וכו'. משנה שם פ\\\"ב (דף ט').\",3,0],[8,371,12,1,\"ומ\\\"ש מביאים כל הקהל וכו' ואם בשאר מצות וכו'. שם בפ\\\"א (דף ד':) במשנה פלוגתא דתנאי ופסק כר' יהודה ואע\\\"פ שאין ב\\\"ד מביאין כתב בתחלת הפרק הרי בית דין חייבין להביא מפני שמה שמביאין הצבור בשביל הב\\\"ד הם מביאים.\",4,0],[8,371,12,1,\"ומ\\\"ש בין שעשו כל ישראל וכו' בין שעשו רוב ישראל אע\\\"פ שהם מיעוט מניין השבטים בין שעשו רוב השבטים אע\\\"פ שהם מיעוט ישראל וכו'. שם (דף ה') פלוגתא דתנאי בברייתא ופסק כר\\\"ש בן אלעזר דמסתבר טעמיה.\",5,0],[8,371,12,1,\"ומה שכתב מביאין כמניין כל השבטים וכו' שאף אלו שלא חטאו מביאים על ידי החוטאים. שם במשנה פלוגתא דתנאי ופסק כר\\\"י.\",6,0],[8,371,12,1,\"ומ\\\"ש אפי' עשה שבט אחד והוא רוב הקהל הרי כל הקהל מביאים י\\\"ב פרים וי\\\"ב שעירים. שם בדף הנזכר בברייתא לר' יהודה שבט שעשה בהוראת ב\\\"ד הגדול אפי' שבטים חייבים ובעינן דלהוי רוב הקהל כר\\\"ש בן אלעזר:\",7,0],[8,371,12,2,\"בית דין שנסתפק להם וכו'. שם ת\\\"ר ידעו שהורו וטעו מה הורו יכול יהו חייבין ת\\\"ל ונודעה החטאת ומפרשה רבינו שהורו ונסתפק להם אם שגגו אם לאו:\",1,0],[8,371,12,2,\"במה דברים אמורים שבית דין חייבים וכו' עד סוף הפרק. מתבאר בפרקים הבאים:\",2,0],[8,371,13,1,\"כיצד אם חסר אחר מכל הדרכים וכו' הרי שהורו ב\\\"ד של אחד מהשבטים להם וכו'. משנה בפ\\\"ק דהוריות שם (דף ה') ופסק כחכמים דאמרי אין חייבין אלא על הוראת בית דין הגדול שבירושלים שנאמר ואם כל עדת ישראל ישגו ולא עדת אותו שבט.\",1,0],[8,371,13,1,\"ומ\\\"ש וכן אם הורו ב\\\"ד הגדול שדם הלב מותר ולא היה ראש ישיבה עמהם וכן אם טעו וידע אחד מהם שטעו וכו'. הכל משנה שם (דף ד':):\",2,0],[8,371,13,1,\"ידע אחד מן הסנהדרין וכו'. שם (דף צ':) מדיוקא דמתני'.\",3,0],[8,371,13,1,\"ומה שכתב ואלו ששתקו אם עשו על פי אלו שהורו הרי אלו חייבים וכו'. משנה שם (דף ב') הורו בית דין וידע אחד מהם [שטעו] או תלמיד שראוי להוראה והלך ועשה על פיהם וכו' הרי זה חייב מפני שלא תלה בבית דין:\",4,0],[8,371,13,1,\"וכן אם נשאו ונתנו בדבר וכו'. מימרא בריש הוריות ופסק כלישנא בתרא ואליבא דשמואל ואביי ור' אבא ורבינא הכריחו כן ממשניות:\",5,0],[8,371,13,1,\"וכן אם הורו ועשו מיעוט הקהל על פיהם וכו'. בריש הוריות (דף ב':) זו דברי ר\\\"י אבל חכ\\\"א יחיד שעשה בהוראת בית דין חייב:\",6,0],[8,371,13,2,\"והסנהדרין עצמן שעשו בהוראתן וכו'. שם (דף ג') אהא דתניא הורו ועשו ר\\\"מ פוטר וחכמים מחייבין מוקים רב פפא דבב\\\"ד משלים לרוב צבור קא מיפלגי ומפרש רבינו ר\\\"מ פוטר לציבור מפני שב\\\"ד מביאים עליהן כיון שרוב הצבור עשו וחכמים מחייבין לצבור שאין ב\\\"ד מביאין עליהם כיון דבלאו ב\\\"ד אינם רוב והלכה כחכמים ואע\\\"ג דר\\\"פ בדרך דחייה אמרה משמע לרבינו דאי לאו דס\\\"ל דקושטא דדינא הכי הוא לא הוה מוקים ליה בהכי:\",1,0],[8,371,13,2,\"עשו רוב אנשי א\\\"י ע\\\"פ וכו' וכן אם עשו רוב השבטים וכו'. כבר נתבאר בפי\\\"ב דהיינו כר\\\"ש בן אלעזר.\",2,0],[8,371,13,2,\"ומ\\\"ש ואין משגיחין על יושבי ח\\\"ל וכו'. מימרא בריש הוריות (דף ג'):\",3,0],[8,371,13,2,\"ושבט מנשה ואפרים אינם חשובים כשני שבטים וכו'. הכי משמע ספ\\\"ק דהוריות (דף ו':) וכדפירש\\\"י:\",4,0],[8,371,13,3,\"היו העושים מרובים וכו'. שם (דף ג') וכרבנן דפליגי ארבי שמעון:\",1,0],[8,371,13,4,\"הורו בית דין בחלב מן החלבים שהוא מותר וכו'. שם בעיא דלא איפשיטא וכיון דספיקא הוא ה\\\"ל לפסוק דבין בית דין בין הם פטורים מן הקרבן ולפיכך יש לתמוה על פסק רבינו וכבר השיגו הראב\\\"ד. וע\\\"כ לומר שנוסחא אחרת היתה לרבינו או שנדחוק לומר שיתנו ויאמרו אם אנו פטורים הרי זה נדבה וצריך:\",1,0],[8,371,13,4,\"במה דברים אמורים כשהיה המורה בית דין אחד וכו'. שם בעיא דלא איפשיטא:\",2,0],[8,371,13,5,\"וכן אם לא היו העושים שוגגים על פי ההוראה וכו' בד\\\"א כשהיה זה שידע שטעו וכו' ונתכוין לאכול שומן וכו'. בריש הוריות איכא לישני בהאי מלתא ובתר הכי אמרינן בפלוגתא וכו' רב אמר פטור ור' יוחנן אמר חייב ופסק כרבי יוחנן.\",1,0],[8,371,13,5,\"ומ\\\"ש דאינו מצטרף למנין השוגגים על פיהם פשוט הוא דאמרינן בגמרא דאפילו רב מודה בהא:\",2,0],[8,371,13,5,\"וכן אם תלה בעצמו ואכל חלב הקיבה וכו'. שם (דף ב':) אמרינן זה הכלל התולה בעצמו חייב לאיתויי מאי לאיתויי מבעט בהוראה. ונ\\\"ל שרבינו מפרש דהיינו שאומר שלא היה הוא צריך להוראתן בזה שכבר היה הוא יודע שמותר:\",3,0],[8,371,13,5,\"זה הכלל התולה בבית דין פטור וכו'. משנה בריש הוריות.\",4,0],[8,371,13,5,\"ומה שכתב וכל החייב בפני עצמו אינו מצטרף עם השוגגים לעשות רוב. זה דבר פשוט:\",5,0],[8,371,13,6,\"הורו בית דין להתיר דבר האסור בזדון וכו' עד סוף הפרק. משנה בפרק קמא דהוריות (דף ד':):\",1,0],[8,371,14,1,\"בית דין ששגגו וכו'. משנה בפירקא קמא דהוריות (ג':):\",1,0],[8,371,14,2,\"ומ\\\"ש בדברים שאינם מפורשים בתורה ומבוארים וכו'. מימרא שם בדף ד'.\",1,0],[8,371,14,2,\"ומ\\\"ש אבל אם טעו והורו ואמרו המוציא מרשות לרשות הוא שחייב וכו' עד מותר לבא עליה. שם בגמרא.\",2,0],[8,371,14,2,\"אך מ\\\"ש או שעקרו אב מאבות מלאכות והורו שאינה מלאכה הרי אלו חייבים יש לתמוה עליו דהא בעיא דלא איפשיטא היא שם וה\\\"ל למפשטה לקולא. ואפשר לדחוק ולומר שיתנו ויאמרו אם אנו פטורין הרי זה נדבה. ועוד י\\\"ל דגמ' בעא למיפשטה מתחלת מתני' והשואל דחה וכיון שכן לא שבקינן מאי דבעא גמרא למיפשט משום הנך דיחויי:\",3,0],[8,371,14,2,\"וכן אם הורו ואמרו שמי שפירשה אשתו נדה וכו'. משנה פ\\\"ב דהוריות (דף ח':) חייבין על עשה ועל ל\\\"ת שבנדה ואי זו מ\\\"ע שבנדה פרוש מן הנדה ובפ\\\"ב דשבועות (דף י\\\"ד:) תנן אי זו היא מ\\\"ע שבנדה שחייבים עליה היה משמש עם הטהורה ואמרה לו נטמאתי ופירש מיד חייב:\",4,0],[8,371,14,2,\"וכן אם טעו ואמרו שאוכל דם וכו':\",5,0],[8,371,14,3,\"הורו ב״ד שיצא השבת וכו'. בפרק האשה רבה (יבמות דף צ״ב).\",1,0],[8,371,14,3,\"ומ\\\"ש וכן אם התירו ב\\\"ד א\\\"א להנשא. שם פלוגתא דתנאי ופסק כרבא דבתרא הוא:\",2,0],[8,371,14,4,\"בית דין שהורו בשגגה וכו'. בפרק קמא דהוריות (דף ג':) במשנה פלוגתא דתנאי ופסק כר\\\"א וכר\\\"ע:\",1,0],[8,371,14,5,\"ומה שכתב ולא עוד אלא הנבהל לצאת וכו'. שם פלוגתא דתנאי ופסק כרבי עקיבא:\",1,0],[8,371,14,5,\"כתב הראב\\\"ד ועשה על פיהם מאחר שידעו פטור א\\\"א דוקא שעשה אחר שחטאו רוב הקהל על פיהם וכו'. ודבר פשוט הוא ולא חשש רבינו לכתבו כאן לפי שסמך על מה שכתב בסוף פרק י\\\"ב במה דברים אמורים שבית דין חייבים ואלו שעשו על פיהם פטורים מן הקרבן כשהיו המורים בית דין הגדול של אחד ושבעים וכו' ויעשו כל הקהל או רובן על פיהם אבל אם חסר אחד מכל אלו הדברים הרי בית דין פטורין מן הקרבן וכל מי ששגג ועשה מעשה מביא חטאת קבועה על שגגתו:\",2,0],[8,371,15,1,\"כבר ביארנו שכל שגגה וכו' בד\\\"א שכהן משיח מביא פר על שגגתו וכו'. משנה וגמרא בריש פרק ב' דהוריות (דף ו' ז'):\",1,0],[8,371,15,2,\"הורה לעצמו ושכח מאיזה טעם הורה וכו'. משנה וגמרא שם (דף ז'):\",1,0],[8,371,15,3,\"הורה לעצמו לבטל מקצת ולקיים מקצת וכו'. משנה שם:\",1,0],[8,371,15,3,\"שאין הכהן משיח חייב קרבן וכו'. גם זה משנה שם. ופירש\\\"י (כהן) משיח בשגגת מעשה לחודיה פטור מכלום כדאמרינן לקמן בפ\\\"ב מעם הארץ פרט למשיח דאינו מביא בשגגת מעשה כלל:\",2,0],[8,371,15,4,\"הורה הכהן המשיח עם ב\\\"ד וכו'. משנה שם הורה עם הצבור ועשה עם הצבור מתכפר לו עם הצבור.\",1,0],[8,371,15,4,\"ומ\\\"ש ואם היו העושים הם המביאים קרבן הוא אינו מביא קרבן וכו' שהרי א\\\"צ כפרה בפני עצמו. נתבאר בסמוך:\",2,0],[8,371,15,5,\"הורה עם בית דין בשגגה וכו'. שם (דף ז':) בעיא דלא איפשיטא. ואיני יודע למה פסק שמביא פר לעצמו ואפשר דמביא פר ומתנה קאמר שיאמר אם אני חייב הרי הוא לחובתי ואם אני פטור הרי הוא נדבה וצ\\\"ע:\",1,0],[8,371,15,6,\"כהן משיח שנתספק לו וכו' אבל הנשיא אם נסתפק לו וכו'. משנה שם (דף ט') אשם תלוי היחיד והנשיא חייבים ומשיח וב\\\"ד פטורים.\",1,0],[8,371,15,6,\"ומ\\\"ש מפני שאין שגגתו תלויה בהוראתו: אי זהו נשיא האמור בתורה וכו'. משנה פ\\\"ג דהוריות (דף י').\",2,0],[8,371,15,6,\"ומ\\\"ש בין שהיה מבית דוד או משאר שבטי ישראל ואם היו מלכים רבים ואין אחד מהם עובד את חבירו וכו'. שם (דף י\\\"א:):\",3,0],[8,371,15,6,\"ואי זהו כהן משיח וכו'. משנה שם:\",4,0],[8,371,15,7,\"כהן גדול שנמשח בשמן המשחה וכו' לפי שאין בין כהן משיח המשמש וכו'. משנה שם ופרק קמא דמגילה (דף ט':):\",1,0],[8,371,15,8,\"נשיא שעשה עם הצבור וכו'. פשוט פרק ב' דהוריות (דף ז'):\",1,0],[8,371,15,9,\"נשיא שנצטרע עבר מנשיאותו. ברייתא וגמרא שם בפרק ג' (דף י'):\",1,0],[8,371,15,9,\"ונשיא שעבר מנשיאותו הרי הוא כהדיוט. משנה שם.\",2,0],[8,371,15,9,\"ומ\\\"ש חטא כשהיה נשיא וכו'. שם (דף ט':) במשנה:\",3,0],[8,371,15,10,\"כהן משיח או מלך שחטאו עד שלא נתמנו וכו'. משנה שם (דף י') וכתנא קמא.\",1,0],[8,371,15,10,\"ומ\\\"ש לפיכך אכל ספק חלב כשהוא הדיוט וכו'. פשוט הוא שם (דף י\\\"א).\",2,0],[8,371,15,10,\"ומ\\\"ש אכל חצי זית חלב כשהוא הדיוט וחצי זית כשהוא נשיא וכו'. ברייתא וגמרא שם.\",3,0],[8,371,15,10,\"ומ\\\"ש אכל כחצי זית כשהוא הדיוט ונתמנה וכו'. שם בעיא דלא איפשיטא:\",4,0],[8,371,15,10,\"סליקו הלכות שגגות בס\\\"ד\",5,0],[8,372,1,1,\"ארבעה הם הנקראים מחוסרי כפרה וכו'. משנה רפ\\\"ב דכריתות (דף ח':):\",1,0],[8,372,1,2,\"גר שמל וטבל וכו'. שם.\",1,0],[8,372,1,2,\"ומ\\\"ש הביא פרידה אחת בשחרית וכו'. ברייתא שם.\",2,0],[8,372,1,2,\"ומ\\\"ש שקרבנו של גר עולת בהמה או שני בני יונה וכו'. גם זה ברייתא שם:\",3,0],[8,372,1,3,\"הזב והזבה קרבן כל אחד מהם ב' תורים וכו'. מפורש בתורה:\",1,0],[8,372,1,4,\"הזב והזבה והמצורע וכו'. מפורש בתורה פ' מצורע:\",1,0],[8,372,1,5,\"היולדת אינה מביאה קרבנה ביום מ' לזכר וכו'. הכי משמע בקרא בפרשת כי תזריע דכתיב ובמלאת ימי טהרה לבן או לבת תביא כבש בן שנתו לעולה וכו'.\",1,0],[8,372,1,5,\"ומ\\\"ש ואם הביאה קרבנה תוך ימי מלאת לא יצאת. בסיפרא פרשת תזריע. וכתב הראב\\\"ד זהו תימה גדול וכו'. ולדברי רבינו י\\\"ל דשאני הכא דקפיד קרא ובמלאת ימי טהרה תביא ולא קודם.\",2,0],[8,372,1,5,\"ומ״ש אפילו הביאה על ולדות הראשונים בתוך ימי מלאת של ולד זה יצאת. יש לתמוה על זה דתניא בת״כ יכול לא תביא בתוך מלאת על ולדות הראשונים ת״ל תביא. וצ״ל שרבינו היה גורס בהפך יכול תביא בתוך מלאת על ולדות הראשונים ת״ל תביא כלומר דה״ל כאילו אומר קודם מלאת לא תביא כלל וכן איכא למשמע קצת ממאי דתניא בפ' בתרא דנזיר (דף ס״ד:) ובעל מ״ע כתב שפסק רבינו בהפך מההיא דסיפרא משום דההיא ר' יהודה הוא דסתם סיפרא ר״י ויחידאה הוא שהוא חולק על חכמים בפרק ארבעה מחוסרי כפרה (כריתות דף י') ברייתא דתני יולדת שוחטין וזורקין עליה ביום ארבעים לזכר וביום שמונים לנקבה והקשו ע״כ טמאה היא ואוקמוה כר״י דאמר ולד שני כמאן דליתיה דמי ופירש רש״י דמיירי בשני ולדות שילדה היום אחד ומחר אחד דיום אחד וארבעים לזה הוי יום ארבעים לזה והיתה ראויה להביא קרבנה על הראשון ולכך שוחטין עליה מוכח דלרבנן אינה ראויה להביא אפילו על הראשון כל שהיא בתוך מלאת של ולד שני:\",3,0],[8,372,1,5,\"עברו ימים אלו ולא הביאו כפרתן וכו': וכל זמן שלא הביאו חטאתם וכו'. בתורת כהנים סוף פרשת תזריע אחד לעולה ואחד לחטאת וכפר מלמד שהכפרה בחטאת וטהרה לאכול בזבחים אבל אין ראיה מכאן אלא למעט עולה דלא מעכב כפרה דדורון בעלמא היא אבל אשם שהוא מעכב כפרה מהי תיתי שאינו מעכב מלאכול בקדשים ובהדיא אמרינן בפרק האומר משקלי (דף כ״א) שחטאתו ואשמו מעכבים והכי משמע נמי בפרק תמיד נשחט (פסחים דף נ״ט) לכן נראה שמ״ש בספרי רבינו אבל העלה והאשם אינם מעכבים טעות סופר הוא וצריך למחוק תיבת והאשם:\",4,0],[8,372,1,5,\"כבר ביארנו במעשה הקרבנות פרק י״ד שכל מחוייבי קרבן אין מקריבין על ידם אלא מדעתם חוץ ממחוסרי כפרה וכו'. ומה שכתב שהרי מביא אדם קרבן על בניו ובנותיו הקטנים וכו'. בסוף נגעים (משנה י״ג) ואף על פי שלא שנינו שם קטנים אלא בניו ובנותיו סתם בפ' אין בין המודר (נדרים דף ל״ה:) גרסינן אמר רבי יוחנן הכל צריכים דעת חוץ ממחוסרי כפרה שהרי אדם מביא קרבן על בניו ועל בנותיו הקטנים שנאמר זאת תורת הזב בין גדול בין קטן:\",5,0],[8,372,1,6,\"אי זו היא זבה וכו'. כך דרשו בתורת כהנים על ואשה כי תזוב זוב דמה ימים רבים.\",1,0],[8,372,1,6,\"ומה שכתב וכבר ביארנו בענין הנדה אימתי תהיה האשה זבה בדמים שתראה וכו'. בפרק [ששי] מהלכות איסורי ביאה:\",2,0],[8,372,1,6,\"כל מקום שאמרנו שהיא זבה וכו'. בסוף תמורה (דף ל\\\"ד) שנינו חטאת העוף הבאה על הספק תשרף:\",3,0],[8,372,1,6,\"ושם ביארנו מה תלד האשה או מה תפיל וכו'. בפרק חמישי מהלכות איסורי ביאה:\",4,0],[8,372,1,7,\"האשה שלא הוחזקה עוברה והפילה וכו'. משנה פ\\\"ק דכריתות (ז':).\",1,0],[8,372,1,7,\"ומ\\\"ש וכן שתי נשים שהפילו וכו'. שם במשנה. וכתב רבינו שלא הוחזקה מעוברת משום דאי הוחזקה מעוברת אין כאן ספק דנפל גמור הוא כמ\\\"ש פרק [חמישי] מהלכות איסורי ביאה:\",2,0],[8,372,1,8,\"אחת היולדת ואחת המפלת וכו' עד ואינה מביאה אלא קרבן אחד על הכל. משנה בפ\\\"ב דכריתות [ט':] וכת\\\"ק ודלא כר' יהודה:\",1,0],[8,372,1,9,\"היולדת טומטום ואנדרוגינוס וכו'. כתב הר\\\"א בנו שדעת רבינו פה שהמפלת לאור מ\\\"א לזכר חייבת בקרבן כמו מפלת לאור פ\\\"א לנקבה דהכי תניא בתוספתא דכריתות ודקשיא לך דלא משכחת יום מ' לעיבורה בהיתר לזכר אא\\\"כ עבר מ\\\"ז יום ובטומטום ואנדרוגינוס נ\\\"ד יום וכי ברשיעי עסקינן, וי\\\"ל שאפשר שיהיה הדבר בשגגה:\",1,0],[8,372,1,10,\"האשה שיש עליה ספק חמש לידות וכו' עד והשאר עליה חובה. משנה בפ\\\"ק דכריתות (דף ח').\",1,0],[8,372,1,10,\"ומ״ש וכן הדין בזב. כתב הראב״ד היו עליה ה' לידות ודאות וכו' א״א הא דלא כהלכתא וכו'. ואני איני יודע אנה שנויה משנה אחרונה שהרי שנינו בסוף פ״ק דכריתות האשה שיש עליה ה' זיבות מביאה קרבן אחד ואוכלת בזבחים ואין השאר עליה חובה ה' לידות ודאות וה' זיבות ודאות מביאה קרבן אחד ואוכלת בזבחים והשאר עליה חובה מעשה שעמדו קינים בירושלים בדינרי זהב אמר רשב״ג המעון הזה לא אלין הלילה עד שיעמדו בדינרין בסוף נכנס לב״ד ולימד האשה שיש עליה ה' לידות ודאות ה' זיבות ודאות מביאה קרבן אחד ואוכלת בזבחים ואין השאר עליה חובה ועמדו קינים בו ביום ברבעתים. ופירש״י נכנס לב״ד ולימד אע״פ שהיקל על ד״ת עת לעשות לה' הוא שאלמלא לא ימצאו יחדלו מלהביא אפילו אחד ויאכלו קדשים בטומאת הגוף עכ״ל. והרי אין כאן משנה אחרונה שאף רשב״ג סובר שהשאר עליה חובה ומה שאמר ואין השאר עליה חובה הוראת שעה היתה כדי שלא יחדלו מלהביא כלל. ואולי הראב״ד היה מפרש שרשב״ג לא להוראת שעה בלבד אמרה אלא לדורות קבעה כדי שאם לעת״ל יתייקרו לא יבואו להמנע מלהביא כלל ולזה קורא משנה אחרונה ויש רשות ביד ב״ד לעקור דבר מה״ת בשב ואל תעשה כדאמרינן בפ' האשה רבה (יבמות דף צ'). ומ״ש ואולי יש הפרש בין משהה קרבנותיה מזידה למשהה אנוסה כלומר שאע״פ שרשב״ג תיקן לדורות לא תיקן אלא למשהה אנוסה לא למשהה מזידה. ואין לומר שהראב״ד מפרש דרשב״ג פליג את״ק וסבר דמדינא אף ביש עליה חמש לידות ודאות מביאה קרבן אחד ואוכלת בזבחים ואין השאר עליה חובה והכי דייק לישנא דנכנס לב״ד ולימד דמשמע שלימד להם דין חדש הפך ת״ק והודו לו ב״ד מאחר שהניחוהו לעשות מעשה ולפ״ז א״ש לישנא דמשנה אחרונה. דא״כ הדינין שיבואו בסמוך והם שנויים בברייתא [כולהו דלא כהלכתא] ומיהו אפשר דסבר הראב״ד דהנהו ברייתות אליבא דמשנה ראשונה. ומ״מ איני יודע לפי דרכו מה תיקן למה שלא כתב רבינו ההיא דמשנה אחרונה שאין השאר עליה חובה.\",2,0],[8,372,1,10,\"ומ\\\"ש וכן הדין בזב: היו עליה ה' לידות ודאות וה' לידות ספק וכו'. ברייתא שם:\",3,0],[8,372,1,11,\"האשה שנתגיירה וכו'. בסוף פרק הזרוע (חולין דף קל״ד) שמונה ספיקות נאמרו בגר ד' לחיוב ואחד מהם קרבן אשתו:\",1,0],[8,372,1,11,\"כבר ביארנו בהלכות שגגות. פרק ג':\",2,0],[8,372,1,12,\"האשה שיש עליה לידה או זיבה וכו'. בפסחים פ' האשה (דף צ':):\",1,0],[8,372,1,13,\"האשה שהביאה חטאתה ומתה וכו'. סוף פרק שני דקינים.\",1,0],[8,372,1,13,\"ומה שכתב אף על פי שלא הפרישה אותן מחיים וכו'. בפירקא קמא דקידושין (דף י\\\"ג:) ואיפסיקא הלכתא בגמרא כמאן דאמר הכי:\",2,0],[8,372,2,1,\"הזב האמור בתורה וכו'. בתוספתא דזבחים פ\\\"ב מה בין זוב לשכבת זרע זוב בא מבשר המת ושכבת זרע מבשר החי זוב דוהה כלובן ביצה המוזרת ושכבת זרע קשורה כלובן ביצה שאינה מוזרת:\",1,0],[8,372,2,2,\"הרואה ראיות הזוב וכו'. רפ\\\"ב דכריתות (דף ח':):\",1,0],[8,372,2,2,\"מכאן אמרו בשבעה דרכים בודקים את הזב וכו'. משנה בסוף נזיר (דף ס\\\"ה:) ובפ\\\"ב דזבים ובקדושין (דף ב'):\",2,0],[8,372,2,3,\"הרואה קרי אינו מתטמא בזוב מעת לעת וכו'. פרק ב' דזבים שם.\",1,0],[8,372,2,3,\"ומה שכתב וכן למראה ולהרהור וכו' עד כל זמן שהוא מצטער. תוספתא בפרק שני:\",2,0],[8,372,2,5,\"מי שמל ואחר כך ראה זוב וכו'. שם בתוספתא וטעמא דאין לך חולי גדול מהמילה והא קיימא לן דחולי הוא אחד מהדרכים שבודקים את הזב:\",1,0],[8,372,2,5,\"עכו\\\"ם שראה קרי ואחר כך נתגייר וכו'. בפרק ב' דזבים ורבינו שמשון האריך שם בטעם הדבר. וכתב הראב\\\"ד א\\\"א מפרש בתוספתא אימתי בזמן שנתגייר כשהוא מהול אבל מל ואחר כך ראה תולין כל זמן שמצטער עכ\\\"ל. ואיני יודע מה מלמדנו שרבינו כתב בסמוך דין זה דמל ואחר כך ראה וממילא משמע דהא דראה קרי ואחר כך נתגייר בשנתגייר כשהוא מהול הוא. ובספרי הדפוס שכתוב שנתגייר וראה קרי הוא טעות סופר וצריך לכתוב בהפך שראה קרי ונתגייר וכן מצאתי בספר מוגה:\",2,0],[8,372,2,5,\"קטן אין תולין לו וכשם שתולין לקטן בחליו כך תולין לו בחולי אמו וכו'. בתוספתא דזבים פרק ב':\",3,0],[8,372,2,5,\"במה דברים אמורים שבודקין את הזב בדרכים אלו כו'. משנה פרק ב' דזבים שם ראה ראייה ראשונה בודקין אותו בשנייה בודקין אותו בג' אין בודקין אותו. ובפ' בנות כותים (נדה דף ל״ה) אמר רב הונא ראיה ראשונה [של זב] מטמאה באונס ת״ש ראה ראיה ראשונה בודקין אותו מאי לאו לטומאה לא לקרבן ופירש רש״י לא לקרבן דאי קמייתא באונס לא מצטרפא לג' לחייבו קרבן.\",4,0],[8,372,2,5,\"ומה שכתב ראיה שלישית אין בודקין אותו בה וכו'. שם וכתנא קמא:\",5,0],[8,372,2,6,\"הרואה ראיה אחת של זוב וכו'. בריש זבים וכב\\\"ה.\",1,0],[8,372,2,6,\"ומה שכתב אין בין זב שראה שתי ראיות וכו'. משנה בפ\\\"ק דמגילה (דף ח').\",2,0],[8,372,2,6,\"ומ\\\"ש ודברים אלו דברי קבלה וכו':\",3,0],[8,372,2,7,\"אחד הרואה שתי ראיות וכו' לפי שתלה הכתוב את הזבה בימים וכו' והזב לא תלה אותו בימים. רפ\\\"ב דכריתות (דף ח') ופ\\\"ב דב\\\"ק (דף כ\\\"ד):\",1,0],[8,372,2,8,\"ומ\\\"ש ואם הפסיק בין ראיה לראיה יום גמור אינן מצטרפות וכו'. כן משמע בפירקא קמא דזבים:\",1,0],[8,372,2,9,\"ראיית הזב אין לה שיעור וכו'. משנה פרק יוצא דופן (נדה דף מ'):\",1,0],[8,372,2,14,\"היה הזוב נגרר ויוצא ולא פסק וכו' עד הרי זה זב גמור. בפ\\\"ב דזבים:\",1,0],[8,372,2,14,\"ראה ראיה אחת מקצתה בסוף היום וכו' עד סוף הפרק. בפ\\\"ק דזבים, ועיין במ\\\"מ פ\\\"ה מהל' שבת:\",2,0],[8,372,3,1,\"כל הימים שהזב רואה בהם זיבות וכו'. מפורש בתורה בפ' מצורע.\",1,0],[8,372,3,1,\"ומ\\\"ש ואם ראה ראיה של זוב אפי' בסוף יום ז' וכו'. בפ\\\"ק דזבים:\",2,0],[8,372,3,2,\"זב שראה קרי באחד משבעת ימי הספירה וכו'. בפ\\\"ק דזבים וכב\\\"ה:\",1,0],[8,372,3,3,\"זב שבדק ביום ראשון מימי הספירה. משנה בפרק תינוקת (נדה דף ס״ח:) פלוגתא דתנאי ואיפסיקא הלכתא בגמ' כר״א דאמר הכי.\",1,0],[8,372,3,3,\"ומ\\\"ש אפי' בדק ביום הטומאה עצמה וכו'. שם אמר רב יהודה אמר רב נדה שהפרישה בטהרה בשלישי שלה סופרתו למנין שבעה והעלו שכוונת רב היא להודיענו שאף על פי שלא בדקה אלא יום שלישי דהיינו יום שפוסקת ויום שביעי סגי דסופן אף על פי שאין תחלתן. וכתב בעל התרומה דאפילו לרב אם בדקה יום שפסקה בו ויום שמיני שאין לה אלא יום שמיני דהכא לא תחלתן איכא ולא סופן איכא וכן כתב ה\\\"ה בשם המפרשים אבל רבינו כתב כאן ובדק [בשביעי] או בשמיני וכו' הרי זה בחזקת טהרה ואפשר דביום השמיני דקאמר היינו היכא שבדק בראשון וכמימרא דרב דאיפליג התם בהדי רבי חנינא והלכתא כרב דאמר תחלתן אף על פי שאין סופן וצריך עיון:\",2,0],[8,372,3,4,\"כל ראיה שהיא סותרת וכו' כמו שביארנו. הוא מ\\\"ש בפ\\\"ב ואם הפסיק הזב בין ראיה לראיה יום גמור אינן מצטרפות.\",1,0],[8,372,3,4,\"ומ\\\"ש אפי' ראה בתוך ימי הספירה ג' ראיות זו אחר זו וכו' שראיות אלו לסתירה הן. בספ\\\"ק דכריתות (דף ח').\",2,0],[8,372,3,4,\"ומ\\\"ש ראה ג' ראיות בליל שמיני וכו'. גם זה משמע שם.\",3,0],[8,372,3,4,\"ומ\\\"ש במה דברים אמורים בזב בעל שתי ראיות עד ואינו מביא קרבן על הזיבה זו האחרונה. הכל שם. ומכל מקום יש לתמוה דאמרינן התם ומי אמר ר' יוחנן לילה מחוסר זמן והאמר חזקיה וכו' כי קאמר ר\\\"י שתים בלילה ואחת ביום אינו מביא לדברי האומר מחוסר זמן דמשמע דר\\\"י סבר דלילה לאו מחוסר זמן. וי\\\"ל דפסק רבינו כחזקיה דאמר לילה מחוסר זמן ועוד דאמרינן התם הני תנאי סברי לילה מחוסר זמן:\",4,0],[8,372,3,6,\"הכל מתטמאים בזיבה אפילו קטן בן יומו. בריש ערכין (דף ג').\",1,0],[8,372,3,6,\"ומה שכתב והגרים והעבדים וחרש שוטה וסריס אדם וסריס חמה. ריש פרק ב' דזבים:\",2,0],[8,372,3,7,\"הטומטום והאנדרוגינוס וכו'. גם זה שם.\",1,0],[8,372,3,7,\"ומ\\\"ש היה מונה שבעה ימים נקיים ללובן וכו'. שם בתוספתא פ\\\"ג והטעם דאם היה מונה לאודם ורואה לובן אינו סותר ממ\\\"נ דאי הוי אשה שפיר מונה דאין לובן מטמא בה ולא שייך לומר שיסתור ואם איש הוא הרי הוא בכלל השבעה נטהר שאינו אלא קרי בעלמא וכן איפכא. ומ\\\"מ אם ראה ב' או ג' כבר נתבאר שהם ספק והולכים להחמיר וצריכים ז' נקיים מחדש לא מדין סתירה אלא שמא זה שראה עתה הוא המטמא אותו לא הראשון:\",2,0],[8,372,4,1,\"כשיתרפא הצרוע וכו'. פ\\\"ב דנגעים.\",1,0],[8,372,4,1,\"ומה שכתב ולמחר בח' טובל פעם שניה. ג\\\"ז שם וכת\\\"ק:\",2,0],[8,372,4,1,\"ומה שכתב ומפני מה טובל בשמיני וכו'. בפרק ג' דיומא (דף ל':):\",3,0],[8,372,4,2,\"נתאחר ולא גילח בשביעי וכו'. פשוט הוא במשנה פ' ג' מינין (נזיר דף מ״ד:):\",1,0],[8,372,4,2,\"כיצד עושין לו וכו' המצורע עומד חוץ לעזרת ישראל. מפני שהוא מחוסר כפורים ותנן בפירקא קמא דכלים שמחוסר כפורים אסור ליכנס לעזרת ישראל.\",2,0],[8,372,4,2,\"ומה שכתב כנגד פתח מזרחית באסקופת שער ניקנור ופניו למערב. בתורת כהנים על פסוק והעמיד הכהן המטהר לפני ה' פתח אהל מועד מעמידן בשער ניקנור אחוריהם למזרח ופניהם למערב:\",3,0],[8,372,4,2,\"ושם עומדים כל מחוסרי כפרה וכו'. בפ\\\"ק דסוטה (דף ח') אהא דתנן שעל פתח שער ניקנור משקין את הסוטות ומטהרים את היולדות ואת המצורעים בשלמא סוטות וכו' ומצורעים דכתיב לפני ה' אלא יולדות מ\\\"ט [אילימא] משום דאתיין וקיימין אקרבנייהו וכו' א\\\"ה זבין וזבות נמי ומשני אה\\\"נ ותנא חדא מינייהו נקט:\",4,0],[8,372,4,2,\"והכהן לוקח אשם של מצורע וכו'. מפורש בתורה.\",5,0],[8,372,4,2,\"ומ\\\"ש ואם הניף זה בפני עצמו וזה בפני עצמו יצא. בת\\\"כ דריש לה מדכתיב אותו לאשם:\",6,0],[8,372,4,2,\"ומ\\\"ש ואח\\\"כ מביא את האשם של מצורע עד הפתח ומכניס שתי ידיו לעזרה וסומך שתי ידיו עליו ושוחטין אותו מיד ומקבלים שני כהנים את דמו אחד מקבל בכלי וכו'. בסוף נגעים:\",7,0],[8,372,4,2,\"וכתב הראב״ד ואח״כ מביא א״א אין כאן אח״כ וכו'. וז״ל התוספתא פ״ה דנגעים מביא אשמו ולוגו בידו ומעמידו בשער ניקנור והכהן עומד מבפנים ומצורע מבחוץ ומצורע מניח ידו תחת ידו של כבש והכהן מניח ידו על המצורע ומוליך ומביא מעלה ומוריד וסומך שתי ידיו עליו ונכנס ושוחטו בצפון כל הסמיכות שבמקדש תיכף שחיטה חוץ מזו שהיתה בשער ניקנור עכ״ל התוספתא. והראב״ד דייק מדקתני ומוליך ומביא מעלה ומוריד וסומך והדר קתני ונכנס ושחטו משמע דבמקום שמניף שם היה סומך ותו מדקתני כל הסמיכות שבמקדש תיכף שחיטה חוץ מזו שהיתה בשער ניקנור משמע שהסמיכה היתה תיכף לתנופה במקום שהיה מניף ואח״כ היה הכהן נוטל האשם ממקום התנופה ונכנס ושוחטו בצפון. ולרבינו י״ל דהא לא מכרעא אע״פ שסמכה סמיכה לתנופה לאו למימרא שיהיה במקומה דמסתמא כל שאנו יכולים לסמוך סמיכה לשחיטה יש לנו לעשות ומי הכריחנו להדחיק בזו והא דקתני כל הסמיכות שבמקדש תיכף שחיטה חוץ מזו היינו לומר שבשאר הקרבנות בעל הקרבן נכנס בעזרה ובמקום שרוצים לשחוט הקרבן שם סומך ותיכף שוחט שם וכאן א״א לעשות כן מפני שאין המצורע יכול ליכנס בעזרה אלא מכניס ידיו לעזרה לחלל השער וסומך שם והכהן מוליך האשם משם לצפון העזרה ושוחט שם והיינו דקתני ונכנס ושוחטו בצפון כלומר נכנס מפתח העזרה לצפון הרי שסמיכה זו מרוחקת קצת מהשחיטה ומשמע שהתנופה היתה חוץ לעזרה ודבר תימה הוא. אבל מדקדוק לשון רבינו נראה שבפנים היה מניפו הכהן לבדו ואח״כ מביאו לפתח העזרה כדי שיסמוך עליו המצורע אבל ק״ל דקתני בתוספתא שהמצורע היה מניף עם הכהן וצ״ע. והר״י קורקוס ז״ל כתב שדעת רבינו דכיון שבפרק כל הפסולים (זבחים דף ל״ג) הביאו תוספתא זו ופריך מינה למ״ד ביאה במקצת לא שמה ביאה וא״כ ליעייל ידיה ולסמוך וישחטו אותו שם פי' אלא שהיו צריכים להוציא האשם מן העזרה ולחזור ולהכניסו ומשני דקסבר האי תנא שאין אותו מקום כשר לשחיטה והיה צריך להכניסו לפנים ולא הוי תיכף לסמיכה, נראה מכאן דרישא דקתני בתנופת מצורע מניח ידו לאו מתרצתא היא דהא בתנופה לפני ה' בעינן וא״כ הרי כאן ביאה במקצת ע״כ. אלא ודאי נראה מכאן דבתנופה לא חיישינן ואין בה הכנסת יד אלא כהן מניף במקום שמניף השאר ואח״כ מוציאו בפתח לסמוך וגם כיון שהקשו ליעייל ידיה ולסמוך ויהיה תיכף נראה שאין שם הכנסת יד אלא לסמיכה מפני התכיפה אבל תנופה כהן לבדו מניף כי אין לחוש בה לתכיפה וגם תנופה יכול הכהן להניף בשביל הבעלים כמו שמצינו בכמה מקומות שהקפידו על הסמיכה ולא הקפידו על התנופה אף אם לא תהיה בבעלים והרי השולח חטאתו כהן מניף על ידו לכך לא הצריכו בה להכניס ידו כמו בסמיכה וקרא דתנופה לא קאמר אלא כהן וגם דכיון דכתיב לפני ה' צריך שיניף במקום שמניף שאר תנופות ואע״פ שבתוספתא אמרו שסמיכה זו לא היה תיכף לה שחיטה כבר אמרו בפרק כל הפסולים דלמ״ד ביאה במקצת לא שמה ביאה מעייל ידיה וסומך להיות תיכף השחיטה ככל הסמיכות שהקפידה תורה על התכיפה בהם אך לא לדעת ר״י בר״י שסובר שאין המקום כשר לשחיטת קדשי קדשים וכבר נתבאר בהל' בית הבחירה לדעת רבינו שעד שער מזרחי שהוא שער ניקנור כשר לשחיטת קדשי קדשים והכל נקרא צפון גם נתבאר בהל' ביאת המקדש דביאה במקצת לא שמה ביאה וכיון שכן ה״ז מכניס ידיו וסומך כמ״ש כאן ושוחטין שם דתיכף לסמיכה שחיטה ככל הסמיכות עכ״ל. ומ״ש הראב״ד כמו שהגהתי למעלה הוא מ״ש אין כאן אח״כ.\",8,0],[8,372,4,2,\"ומ\\\"ש ואחד בידו הימנית ומערה לידו השמאלית וכו' עד פסל. בתוספתא פ\\\"ק דזבחים והר\\\"י קורקוס ז\\\"ל כתב דאיתא בתוספתא (פרק בתרא) דנגעים זה שקיבל בכלי מקבל בימין וזה שקיבל ביד מקבל בשמאל ואם שינה פסל וזה הפך ממה שכתב רבינו ונדחק בפירושה דמאי דקתני זה שקיבל ביד מקבל בשמאל היינו לומר שמקבל בשמאל מן הימין שקבל בה מהבהמה ואם שינה שקיבל מן הבהמה פסל:\",9,0],[8,372,4,2,\"הכהן שקיבל מקצת הדם בכלי וכו' עד ואם לא נתן לא כיפר. הכל בסוף נגעים.\",10,0],[8,372,4,2,\"ומ\\\"ש ואם נתן על השמאל לא יצא. שם דלא כר\\\"ש.\",11,0],[8,372,4,2,\"ומ\\\"ש ויוצק לתוך כפו של חבירו השמאלית וכן מ\\\"ש וטובל אצבעו הימנית. בסוף נגעים.\",12,0],[8,372,4,2,\"ומ\\\"ש על כל הזיה טבילת אצבע בשמן. בת\\\"כ.\",13,0],[8,372,4,2,\"ומ\\\"ש ואם הזה ולא כיון כנגד בית קדשי קדשים כשירות. נראה דהיינו מדתני' בתוספתא פ\\\"ק דזבחים הזיות שבמצורע שהזן שלא לשמן שאינם מכוונות הרי אלו כשירות.\",14,0],[8,372,4,2,\"ומה שכתב ואח\\\"כ יבא אצל מצורע וכו' ואם לא נתן לא כיפר. בפרק בתרא דנגעים אם נתן כיפר ואם לא נתן לא כיפר דברי ר\\\"ע ר\\\"י בן נורי אומר שיירי מצוה הן בין שנתן בין שלא נתן כיפר ומעלין עליו כאילו לא כיפר ומייתי לה בריש זבחים (דף י':) ומפרש לה.\",15,0],[8,372,4,2,\"ומה שכתב ושאר הלוג מתחלק לכהנים. משנה בס״פ כל התדיר (זבחים דף צ״א):\",16,0],[8,372,4,3,\"שיירי הלוג וכו'. בסוף פרק כל התדיר אמר ר\\\"ש אם ראית שמן שהוא מתחלק בעזרה אי אתה צריך לשאול מה הוא אלא מותר רקיקי מנחות ישראל ולוג שמן של מצורע ומאחר שהיה מתחלק בעזרה משמע שהיה נאכל לזכרי כהונה שהם מצויים שם.\",1,0],[8,372,4,3,\"ומ״ש ואסור לאכול מלוג השמן וכו'. בפרק ב״ש (זבחים דף מ״ה) תניא לוג שמן של מצורע מועלין בו עד שיזרק הדם נזרק הדם לא נהנין ולא מועלין רבי אומר מועלין עד שיתן מתנותיו ושוין שאסור באכילה עד שיתן מתן שבע ומתן בהונות. ומשמע לרבינו דאסור באכילה דקתני היינו מן התורה:\",2,0],[8,372,5,1,\"אי זהו תנוך אזן וכו'. בת\\\"כ.\",1,0],[8,372,5,1,\"ומ\\\"ש נתן על צידי הבהונות כשר נתן על צידי צידיהן פסול. בפ\\\"ק דמנחות (דף י\\\"א):\",2,0],[8,372,5,1,\"בין שנתן השמן על דם האשם עצמו מלמעלה וכו' אפילו נתקנח הדם וכו'. שם:\",3,0],[8,372,5,1,\"אין לו בהן יד ימנית וכו' אין לו טהרה עולמית. בסוף נגעים שם וכת\\\"ק:\",4,0],[8,372,5,2,\"אשם מצורע ששחטו שלא לשמו וכו' עד וצריך אשם אחר להכשירו. ברייתא פ״ק דמנחות (דף ה') ובס״פ הוציאו לו (יומא דף ס״א:):\",1,0],[8,372,5,3,\"הקדים חטאתו לאשמו וכו'. פ\\\"ק דמנחות:\",1,0],[8,372,5,4,\"יש לאדם להביא אשמו היום וכו' ואם רצה לשנות הלוג לאשם מצורע אחר משנה וכו'. פ\\\"ב דמנחות (דף ט\\\"ו):\",1,0],[8,372,5,4,\"חסר הלוג וכו'. בסוף נגעים וכר\\\"ע:\",2,0],[8,372,5,5,\"יצק מן השמן בכפו וכו' עד ומיתר השמן. ברייתא בס״פ הוציאו לו (יומא דף ס״א) וכת״ק. וכתב הר״י קורקוס ז״ל שרבינו פסק בספ״ד שאם לא נתן מתנות הראש לא כיפר והיאך כתב כאן שאינן מעכבות ואפשר לומר דכשהם בעין ולא נתן לא כיפר אבל כשנשפכו אינן מעכבות:\",1,0],[8,372,5,6,\"הקדים מתן שמן על הבהונות וכו'. פירקא קמא דמנחות (דף ה'):\",1,0],[8,372,5,7,\"נתן שבע המתנות שלא לשמן וכו':\",1,0],[8,372,5,8,\"מצורע שנתנגע אחר שהביא אשמו וכו'. בפ\\\"ב דכריתות (דף ט':) תנן דמצורע שנתנגע נגעים הרבה אינו מביא אלא קרבן אחד והדר תני הביא צפריו ונתנגע לא עלה לו עד שיביא חטאתו דברי ר\\\"ש ר' יהודה אומר עד שיביא אשמו ובגמרא הביא צפריו ונתנגע וכו' והא אמרת אינו מביא אלא קרבן אחד חסורי מחסרא והכי קתני הביא צפריו ונתנגע אינו מביא אלא קרבן אחד ולאקבועי בעניות ועשירות לא מיקבע עד שיביא חטאתו ר' יהודה אומר עד שיביא אשמו. ופירש\\\"י אינו מביא אלא קרבן אחד על נגעים הרבה אלמא חדא צרעת אריכתא היא ואמאי מחייבת ליה לאיתויי צפרים אכל נגע. ולאקבועי בעניות וה\\\"ק ולא עלו הצפרים ליקבע בעניות ובעשירות שאם היה עני בשעת הבאת צפרים והעשיר צריך להביא קרבן עשיר ואם היה עשיר והעני מביא עני בדלות עד שיביא חטאתו דבתר חטאת אזלינן בין בעניות בין בעשירות עכ\\\"ל. ואיכא למידק [מנ\\\"ל לרבינו הא] מאחר דאוקימנא דמתני' לאו לענין מצורע שנתנגע איתניא אלא לענין לאיקבועי בעניות ועשירות. וי\\\"ל דמ\\\"מ כיון דלמאי דמתרץ למתניתן אמר הביא צפריו ונתנגע אינו מביא אלא קרבן אחד משמע דוקא כשנתנגע אחר הצפרים הוא דאינו מביא אלא קרבן אחד הא אם נתנגע אחר הבאת האשם שהוא הקרבן הראשון צריך להביא קרבן על כל אחד ואחד:\",1,0],[8,372,5,9,\"מצורע שהביא קרבן עני והעשיר וכו'. משנה וגמ' שכתבתי בסמוך ופסק כר\\\"י לגבי ר\\\"ש ואע\\\"ג דראב\\\"י פליג עלייהו בברייתא ואמר הכל הולך אחר צפרים לא חש ליה כיון שלא נשנה במשנה:\",1,0],[8,372,5,10,\"שני מצורעים שנתערבו קרבנותיהם וכו'. בסוף נגעים ובפ' תינוקת (נדה דף ע') הקשו על זה והאיכא אשם פירוש ששוה בעשיר ובעני ואיך יביא אשם מספק דילמא מייתי חולין לעזרה ותירץ שמואל בשקרב אשמו קודם האחר ואז יש לו תקנה בחטאת העוף ואי לא לא והקשו על זה דאי כר״י הא קבעה ליה אשם פירוש שכיון שהביא אשם בעשירות אינו יכול להביא עוד בדלות ואי לר״ש הא יכול להביא אשם על תנאי וא״כ למה הוצרך להעמיד בקרב אשמו ומסיק סבר לה כר״ש בחדא דלא קבע אשם וכר״י בחדא דאינו יכול להביא אשם ע״ת, והשתא מאחר שרבינו פסק כר״י דאשם קבע בעשירות היאך כתב כאן תקנה זו שיכתוב נכסיו כיון שבעת הקרבת האשם היה עשיר אי אפשר בתקנה זו וצ״ע:\",1,0],[8,372,5,11,\"עשיר שאמר קרבנו של מצורע זה עלי וכו'. משנה וגמרא בפ\\\"ד דערכין (דף י\\\"ז) וצ\\\"ע שם:\",1,0],[8,373,1,1,\"כל הממיר לוקה על כל בהמה שימיר וכו' מפי השמועה למדו וכו'. פרק קמא דתמורה (דף ג'). ויש לתמוה דהא אמרינן בגמ' דאמר ר\\\"י לתנא לא תיתני ממיר דבדבורו עביד מעשה וא\\\"כ למה כתב רבינו שאין בו מעשה ולא חש לדר' יוחנן וכבר הרגיש בזה [המגיד משנה] בפרק י\\\"ג מהלכות שכירות:\",1,0],[8,373,1,1,\"ולמה לוקין על התמורה וכו' מפני שיש בה עשה ושני לאוין. בריש תמורה (דף ד').\",2,0],[8,373,1,1,\"ומ\\\"ש שאין לאו שבה שוה לעשה שהצבור והשותפין אין עושים תמורה וכו'. משנה בפ\\\"ב דתמורה (דף י\\\"ד):\",3,0],[8,373,1,1,\"נמצאת אומר שהיחיד שהמיר הרי התמורה קודש. פשוט הוא בלשון המקרא.\",4,0],[8,373,1,1,\"מ\\\"ש ואפי' המיר בשבת. תוספתא ריש תמורה:\",5,0],[8,373,1,1,\"ואחד מהשותפין שהמיר וכו' הרי זה לוקה. הכי משמע מדלא קתני הצבור והשותפין מותרים להמיר:\",6,0],[8,373,1,2,\"אחד הממיר בזדון או שהמיר בשגגה. משנה בפ\\\"ב דתמורה (דף ט\\\"ז:) ר\\\"י בר יהודה אומר עשה שוגג כמזיד בתמורה וכתב רבינו בפירוש המשנה והלכה כרבי יוסי דאין חולק עליו. ואני אומר אפילו אם היה נמצא מי שחולק עליו הלכתא כוותיה דר\\\"י בר יהודה מדאיפליגו אמוראי אליביה ועוד דאמרינן בפ\\\"ק (דף י\\\"ג) גבי הא דתנן ר' יהודה אומר הולד עושה תמורה ורבנן (יהיה) לרבות שוגג כמזיד אלמא רבנן הכי סבירא להו.\",1,0],[8,373,1,2,\"ומ\\\"ש כיצד המתכוין לומר ה\\\"ז תמורת עולה שיש לי וכו' עד ואינו לוקה עליה. שם ה\\\"ד שוגג כמזיד אמר חזקיה כסבור שהוא מותר להמיר (גבי תמורה לקי) גבי קדשים לא לקי ר\\\"ל ור\\\"י אמרי כסבור לומר תמורת עולה ואמר תמורת שלמים. ל\\\"א גבי תמורה קדיש גבי קדשים לא קדיש כסבור לומר שחור ואמר לבן גבי תמורה לקי גבי קדשים לא לקי ר\\\"י אומר באומר תצא זו ותכנס זו גבי קדשים כאומר שנולד בהם מום נאכלים בלא פדיון גבי תמורה לקי רב ששת אמר באומר אכנס לבית זה ואקדיש ואמיר מדעתי ונכנס והמיר והקדיש שלא מדעתו גבי תמורה לקי גבי קדשים לא לקי. ופירש\\\"י גבי תמורה לקי דרבי ביה קרא יהיה שוגג כמזיד גבי קדשים לא לקי דלא מצינו מלקות אלא במזיד ובהתראה. כסבור לומר שור שחור שיצא מבית זה תחלה יהא תמורה תחת זה ויצא מפיו שור לבן גבי תמורה קדיש ולקי דהא גלי ביה קרא גבי קדשים אם בעל מום הוא למזבח לא לקי דהא לא קדיש דהקדש טעות אינו הקדש. תצא זו ותכנס זו ואותה של הקדש תמימה היא ולא נפקא לחולין אלא תופסת זו בקדושתה והויא תמורה והוא סבור שתצא לחולין כבעל מום ולא להמיר נתכוון ואפילו הכי לקי וגבי קדשים נמי דומיא דהאי שהיה יודע שהקדשים אסורים לזרים אבל סבור הוא דהיכא דנפל בהם מום נאכלין בלא פדיון והיינו דומיא דהאי שהיה יודע שהתמורה אסורה אבל בכה\\\"ג דסבר דמותר לא אמר יותר ונכנס והקדיש והמיר שלא מדעתו שבעל מחשבות הוא ולא היה יודע מה היה אומר בתמורה קדש ולקי דגלי קרא שוגג כמזיד בקדשים לא קדיש ואי איכא בעל מום למזבח לא לקי דהא לא קדיש דהקדש טעות הוא עכ\\\"ל. ומשמע דכל הני אמוראי לא פליגי לענין שהיא תמורה דכל חד מהני הויא תמורה מיהו לענין מלקות משמע ליה לרבינו דאף על גב דבמתכוין לומר ה\\\"ז תמורת עולה שיש לי ואמר תמורת שלמים לוקה משום דנתכוין להמיר אבל כסבור מותר להמיר אינו בדין שילקה דהוי כאנוס ובהא פליגי רבי יוחנן וריש לקיש עליה דחזקיה וכן בההיא דרב ששת כיון דהמיר שלא מדעתו הוי כאנוס ואינו לוקה. ויש לתמוה למה השמיט רבינו ההוא דאמר רבי יוחנן באומר תצא זו ותכנס זו:\",2,0],[8,373,1,2,\"וכתב הראב\\\"ד אבל אם דימה שמותר להמיר והמיר וכו' א\\\"א בפירוש אמרו בגמרא וכו'. טעמו משום דלא משמע להראב\\\"ד מלקות בקדשים אלא בגוזז ועובד ומשמע ליה דבגוונא דקתני בקדשים [לא] לקי קתני בתמורה לקי ורבינו סבר לה כדפירש רש\\\"י דבתמורה לקי משום ממיר ובקדשים לא לקי משום מקדיש בעלי מומין למזבח:\",3,0],[8,373,1,2,\"וכתב עוד הראב\\\"ד ונכנס ושכח והמיר שלא מדעתו הרי זה תמורה א\\\"א אין כאן שכחה וכו'. ואין פירושו מוכרח:\",4,0],[8,373,1,3,\"אין אדם ממיר בהמתו בקרבן שאינו וכו' עד שאין אדם מקדיש דבר שאינו שלו. שם (דף ט'):\",1,0],[8,373,1,4,\"המתכפר הוא שעושה תמורה וכו'. שם בריש פרק קמא (דף ב':):\",1,0],[8,373,1,5,\"היורש ממיר. שם פ\\\"ק (דף ב').\",1,0],[8,373,1,5,\"ומ\\\"ש הניח בהמה לשני בניו ומת וכו'. מימרא דר\\\"י פ\\\"ק דזבחים (דף ה'):\",2,0],[8,373,1,6,\"אין קדשי נכרים עושים תמורה וכו'. ריש פירקא קמא דתמורה ובפרק בית שמאי (זבחים מ\\\"ה) ובערכין (דף ה':) ופסק כרבי שמעון אף על גב דרבי יוסי פליג עליה מפני שבגמרא הביאו ברייתא זו לפשוט בעיא אחרת מרבי שמעון. וכתב הר\\\"י קורקוס ז\\\"ל דאפשר עוד לומר דר' יוסי לא פליג ארבי שמעון בהא.\",1,0],[8,373,1,6,\"ומה שכתב אבל מדברי סופרים שהנכרי שהמיר ה\\\"ז תמורה. כן יש ללמוד ממ\\\"ש לא ממירים גבי לא נהנים ולא מועלין דהיינו לא נהנים מדרבנן ולא מועלין מדאורייתא:\",2,0],[8,373,1,6,\"הקדיש הנכרי בהמה שיתכפר בה ישראל וכו'. בריש תמורה בעיא דלא איפשיטא:\",3,0],[8,373,1,6,\"כתב הראב\\\"ד אין קדשי נכרים עושים תמורה מן התורה א\\\"א שיבושין יש כאן וכו'. ודבריו מבוארים בריש תמורה ואינם סותרים דברי רבינו דאיכא למימר התם מדאורייתא אבל מדברי סופרים נכרי ממיר:\",4,0],[8,373,1,7,\"אחד אנשים ואחד נשים וכו'. משנה בריש תמורה:\",1,0],[8,373,1,8,\"קטן שהגיע לעונת נדרים שהמיר וכו'. שם בעיא ואמרינן עלה את\\\"ל עביד תמורה וכו' נכרי מהו שימיר וכבר נודע דרך רבינו לפסוק כאת\\\"ל ולפיכך יש לתמוה למה פסק שהוא ספק. ואפשר שרבינו לא היה גורס את\\\"ל:\",1,0],[8,373,1,9,\"אין הכהנים ממירים בחטאת ובאשם וכו'. משנה שם (דף ד':).\",1,0],[8,373,1,9,\"ומה שכתב ואין הכהנים ממירים בבכור וכו'. שם במשנה.\",2,0],[8,373,1,9,\"ומ\\\"ש אבל הבעלים שהמירו בבכור כל זמן שהוא בביתם עושים תמורה. ברייתא שם (דף ח':).\",3,0],[8,373,1,9,\"ומ\\\"ש וכן כהן שהמיר בבכור שנולד לו וכו'. נלמד ממתני' וגמרא פ\\\"ק דתמורה:\",4,0],[8,373,1,10,\"אילו של כ״ג עושה תמורה וכו'. פ' הוציאו לו (יומא דף נ' נ״א):\",1,0],[8,373,1,12,\"העופות והמנחות אינם עושים תמורה וכו' עד יצאו קדשי בה\\\"ב. משנה בפ\\\"ק דתמורה (דף י\\\"ג):\",1,0],[8,373,1,12,\"ומה שכתב מה מעשר בהמה הוקש למעשר דגן וכו'. בריש תמורה (דף ג'):\",2,0],[8,373,1,13,\"המקדיש בעלת מום קבוע אינה עושה תמורה עד ה״ז עושה תמורה וכו'. משנה פרק הזרוע (חולין דף ק״ל) ופ״ב דבכורות (דף י״ד):\",1,0],[8,373,1,14,\"הממיר תמים בבעל מום וכו' עד הרי זה תמורה. משנה פ\\\"ק דתמורה (דף ט').\",1,0],[8,373,1,14,\"ומ\\\"ש בין בבת אחת בין בזו אחר זו. כתב הר\\\"י קורקוס ז\\\"ל דיליף לה מדאיפליגו ר\\\"ל ור\\\"י שם אליבא דר\\\"ש אם ממירים וחוזרים וממירין ור\\\"י אמר כשם שאין ממירין שנים כאחד כך אין ממירין וחוזרין וממירין משמע דאליבא דרבנן שממירין שנים כאחד הוא הדין שממירים וחוזרים וממירים דלא שאני לן בין בזה אחר זה לבבת אחת.\",2,0],[8,373,1,14,\"ומה שכתב ולוקה כמנין הבהמות שהמיר:\",3,0],[8,373,1,15,\"אין התמורה עושה תמורה וכו' עד ולא תמורת תמורתו. משנה וגמרא פירקא קמא דתמורה (דף י\\\"ב).\",1,0],[8,373,1,15,\"ומה שכתב אבל הממיר בבהמה וחזר והמיר בה וכו'. שם (דף ט') אמר רבי יוחנן טעמא דר\\\"ש כשם שאין ממירין אחד בשנים כך אין ממירין וחוזרים וממירים משמע דלתנא קמא דממירין אחד בשנים ממירין וחוזרין וממירים:\",2,0],[8,373,1,16,\"אין ממירים איברים וכו'. משנה פירקא קמא דתמורה (דף י') ופסק כתנא קמא:\",1,0],[8,373,1,17,\"הממיר בכלאים או בטריפה וכו'. משנה בסוף פ\\\"ב דתמורה (דף י\\\"ז) ואע\\\"פ שהיא שנויה בשם ר' אלעזר כתב רבינו בפירוש המשנה הלכה כר\\\"א ואין חולק עליו. וק\\\"ל שבתוספתא תני דלת\\\"ק עושים תמורה. וי\\\"ל שמאחר שבמשנתנו לא הזכירו כן משמע דסבר תנא דמתני' דליתא לההיא תוספתא:\",1,0],[8,373,1,18,\"הרובע והנרבע הרי הם כבעל מום וכו'. תוספתא פרק קמא דתמורה:\",1,0],[8,373,1,19,\"בהמה שחציה קדש וחציה חולין וכו'. תוספתא פרק קמא דתמורה שם:\",1,0],[8,373,1,20,\"כל החטאות שדינם שימותו וכו' עושה תמורה:\",1,0],[8,373,1,21,\"המפריש נקבה לפסחו או לעולתו וכו' עד סוף הפרק. ברייתא פ\\\"ג דתמורה (דף י\\\"ט כ'):\",1,0],[8,373,2,1,\"התמורה הוא שיאמר בעל הקרבן וכו' עד ואינה תמורה. משנה בסוף פרק כיצד מערימין (תמורה דף כ״ו):\",1,0],[8,373,2,2,\"היו לפניו שתי בהמות וכו'. שם (דף כ\\\"ז) על המשנה הנזכרת רב אשי אמר אפי' בבעל מום נמי משכחת לה (תחת זו) לישנא דאחולי ומשכחת דהוי לישנא דאתפוסי ידו אקדש חול הוי ידו אחול קדש הוי:\",1,0],[8,373,2,3,\"היו לפניו שלש בהמות וכו'. שם כל אלו בעיות נתפשטו באת\\\"ל חוץ מאחת שעלתה בתיקו ופסק בה להקל משום דאין מלקין על הספק:\",1,0],[8,373,2,4,\"האומר הרי זו תמורת עולה ושלמים דבריו קיימים וכו' עד סוף הפרק. משנה וגמ' שם (דף כ\\\"ה) וכר\\\"י:\",1,0],[8,373,3,1,\"כיצד דין התמורות ליקרב וכו' עד שאינה טעונה לחם. משנה בפרק ג' דתמורה (דף י\\\"ח):\",1,0],[8,373,3,1,\"תמורת הפסח וכו'. בפ' מי שהיה טמא (פסחים דף צ״ו:) אמתני' דאמר ר' יהושע שמעתי שתמורת הפסח קריבה וכו' איפליגו רבה ור' זירא ופסק רבינו כר' זירא ולא ידעתי למה דלכאורה משמע דהלכתא כרבה:\",2,0],[8,373,3,2,\"תמורת הבכור והמעשר וכו' עד כך אין פודין תמורתן. משנה בפרק ג' דתמורה (דף כ\\\"א):\",1,0],[8,373,3,3,\"בהמה שהקדישה חציה עולה וכו'. בתוספתא פרק ג' דתמורה.\",1,0],[8,373,3,3,\"ומ\\\"ש וכן כל בהמת הקדש שאינה קריבה מפני תחלת הקדשה הרי תמורתה כמוה. נלמד מהתוספתא הנזכרת:\",2,0],[8,373,3,3,\"אמר חצי בהמה זו תמורה וכו'. בפ' כיצד מערימין (תמורה דף כ״ו) אמר אביי הכל מודים היכא דאמר חצייה עולה וחצייה מעשר ד״ה עולה קריבה היכא דאמר חציה תמורה וחציה מעשר מאי תמורה קריבה שכן נוהגת בכל הקדשים או דילמא מעשר קריבה שכן מקדש לפניו ולאחריו תיקו. ופירש״י חציה עולה וחציה מעשר ד״ה עולה קריבה אפי' נתכוון מתחלה לכך דלא חשיבא מלתא בתרייתא מידי דאין מעשר קדושה כה״ג אלא דרך מנין ויהא הוא עשירי והוא הדין נמי אם אמר חציה עולה וחציה תמורה לא חיילא תמורה לגבי עולה דלא קאי שום בהמה גביה שהוא ממיר בה אלא חציה מעשר וחציה תמורה ותרוייהו כי הדדי נינהו וכו' עכ״ל. ורבינו נראה שהיה גורס הכל מודים היכא דאמר חצייה תמורה וחציה עולה ד״ה עולה קריבה חציה עולה וחציה מעשר תקרב עולה חציה תמורה וחציה מעשר הרי זה ספק ואינה קריבה וגירסא זו מתפרשת על דרך פירש״י. והראב״ד פירש בענין אחר שכתב וז״ל א״א לישנא דגמ' הכל מודים וכו' דילמא להכי איכוון מעיקרא:\",3,0],[8,373,3,4,\"המקדיש בעל מום עובר וכו'. משנה פרק הזרוע (חולין דף ק״ל) ופרק ב' דבכורות (דף י״ד).\",1,0],[8,373,3,4,\"ומה שכתב אינה קריבה ואינה נפדית. בפרק ב' דבכורות (דף ט\\\"ו) בגמרא:\",2,0],[8,373,3,5,\"כל התמורות שהיו בעלי מומין קבועין מתחלתן וכו'. משנה בסוף פרק שני דתמורה (דף ט\\\"ז) חומר בתמורה מבקדשים שהקדושה חלה עליה בבעלת מום קבוע ואין יוצא וכו':\",1,0],[8,373,3,6,\"עולה שנתערבה בזבחים וכו'. תוספתא ספ\\\"ג דתמורה וז\\\"ל עולה שנתערבה בזבחים ירעו עד שיסתאבו וימכרו ויביא (בדמי) יפה שבהן זבח ובדמי יפה שבהן עולה המיר באחת מהן ואין יודע באי זו מהן המיר הרי זה מביא מעות או זבח מתוך ביתו ואומר אם תמורת עולה היא הרי זה שלמים אם תמורת שלמים הוא זה הרי זה עולה והרי הן כשני זבחים שנתערבו זה בזה. חזר והמיר באחת מהן ואין ידוע באי זה מהן המיר הרי זה מביא מעות או זבח מתוך ביתו ואומר אם תמורת תמורה היא זו חולין היא (זו עולה) [הרי] היא שלמים אם תמורת שלמים היא זו הר\\\"ז עולה והרי הן כזבח ותמורה שנתערבו זה בזה עכ\\\"ל. פירוש בזבחים בשלמים ומביא זבח אחר מתוך ביתו פי' זבח זה בהמת חולין:\",1,0],[8,373,3,6,\"כתב הראב\\\"ד עולה שנתערבה בזבחים וכו'. אמר אברהם כל זה מועתק מן התוספתא וכו':\",2,0],[8,373,3,6,\"ובעל מ\\\"ע כתב וז\\\"ל לשון התוספתא שהגיע לידי הרמב\\\"ם ז\\\"ל אין בו שיבוש וגם לא בדברי עצמו והצעת ההלכה כך היא עולה שנתערבה בזבחים פירוש באחד משאר זבחים ד\\\"מ והמיר באחת מהן שאמר על בהמת חולין הרי זו תמורת זו אע\\\"פ שהוא מכיר הבהמה שהמיר בה אין ידוע לנו אם זו השלישית תמורת עולה או שלמים מפני ספק התערובת שאירע בשתים הראשונות מביא בהמה אחרת ר\\\"ל בהמה רביעית כדי לתקן הבהמה השלישית ואומר אם תמורת עולה היא השלישית על המעורבת הרי זו רביעית שלמים כלומר בתחלת הקדש אני מקדישה עתה שלמים ואם תמורת שלמים היא השלישית שאמרתי על המעורבת הרי זו הרביעית עולה כלומר בתחלת הקדש אני מקדישה עתה עולה ונמצאת בהמה שהביא רביעית עם התמורה השלישית כעולה ושלמים שנתערבו זה בזה ותמורותיהן כיוצא בהן דממ\\\"נ אחת מהשלישית והרביעית עולה והאחרת שלמים האחת מדין תמורה והאחרת מדין תחלת הקדש בתנאי שהתנה והן בדמיון הראשונה והשנייה שנתערבו ולא הוכרו לדעת אי זו מהן עולה ואי זו מהן שלמים חזר והמיר באחת משתיהן כלומר אמר על בהמה חמישית הרי זו תמורת זו על אחת מהשתים האחרונות שהן השלישית והרביעית ואין ידוע באי זה ר\\\"ל באי זו משתים האחרונות המיר אם בתמורה שהיא השלישית והרי זו החמישית תמורה ואם ברביעית שהוא בתחלת הקדש המיר והרי זו החמישית בתמורת תחלת הקדש שהקדיש הרביעית בתנאי ומה תקנה יש בה מביא זבח אחר כלומר בהמה ששית תמימה הראויה לזבח מתוך ביתו כלומר שהיא חולין ואומר על התמורה השנייה שהיא החמישית אם תמורת תמורה היא זו וקי\\\"ל דאין תמורה עושה תמורה הרי הששית שהביא חולין כלומר שאין צורך לחלל החמישית שהרי היא חולין משכבר המירה בתמורה ואם תמורת עולה או שלמים היא החמישית שאמרנו שהביא בתמורת השניה הרי זו הששית שהביא עתה עולה או שלמים שתתחלל בה קדושת החמישית המסופקת והרי דין זו הששית שהביא בתמורת השניה לחלל ספק התמורה השנייה שהיא החמישית כשהיא עומדת עם התמורה והשניה בעצמה שתיהן עומדות לפנינו החמישית והששית בזבח שהרי זבח אחר הוא שהביא ששית ותמורה שהיא החמישית שנתפסה שניה בספק תמורת העולה והשלמים ותמורותיהן כיוצא בהן ע\\\"כ פירוש דבריו ודברי התוספתא על נוסחא אמיתית ופירוש נכון ע\\\"כ לשון המ\\\"ע. והר\\\"י קורקוס ז\\\"ל כתב וז\\\"ל ביאור דברי רבינו זו שעולה נתערבה בשלמים והמיר באחת שתערובת זה נמצא שזו התמורה ספק עולה ספק שלמים לצאת ידי ספק של התמורה צריך להקריב עולה ושלמים לכך צריך להביא בהמה אחרת ויאמר אם זו תמורת עולה שנמצא שגם היא צריכה ליקרב עולה זה אני מקדיש לשלמים ואם זו היא תמורת שלמים זאת אני מקדיש לעולה ונמצא עתה התמורה וזאת הבהמה האחת עולה והאחת שלמים ממ\\\"נ אחת מכח התמורה ואחת הקדיש הוא ואין ידוע איזו יקריב עולה ואיזו יקריב שלמים ולכן ירעו עד שיסתאבו ויביא עולה ושלמים ונמצא שלתקן התמורה הוצרכנו להקדיש אחת תחילה וכשיוממו השתים יחללם על שתים אחרות וכן הוא לשון התוספתא עולה שנתערבה בזבחים וכו' והחלוקה הראשונה שאמרו בה ירעו לא שייכא לדין תמורה אלא היא הקדמה להודיענו אחר שיביא הבהמה ויקדיש אותה והרי שתיהן אחת עולה ואחת שלמים ואין ידוע מה דינם לכך הקדימה להודיע דינם ורבינו כבר ביאר הדין בפרק ששי מהל' פסולי המוקדשין וכדברי הר\\\"א יש תקנה אחרת שאין צריך רק לשתי בהמות תמות מתחלה וימתין עד שתומם התמורה כי ממ\\\"נ צריך להמתין וכן גם לדרך רבינו ויביא שתי בהמות ויאמר אם זו תמורת העולה זו שלמי נדבה ואם זו תמורת השלמים זו עולת נדבה. ונראה שסובר שגם כוונת התוספתא הוא כן שכשיפול בה מום יביא שתים מתוך ביתו וכו' ובודאי לפי זה לא שייך בעולה ושלמים שנתערבו וכו' אלא שלדעת הר\\\"א נפקותא של זה לחזר והמיר וזה שאמר כל זה מועתק מהתוספתא וכו'. מ\\\"מ לשון התוספתא כדברי רבינו היא שמביא תחלה זבח ואח\\\"כ אמר הרי שתיהן כשני זבחים והדבר מוכרח לפ\\\"ז דהיינו בעולה ושלמים ואין יודע איזו עולה ואיזו שלמים ובא להשלים להודיע דין תקנת תמורה זו דהוי כנתערבו ואח\\\"כ מתחיל בדין אחר דהיינו חזר והמיר וכו' ולדעת הר\\\"א מה שאמרו והרי הם כשני זבחים הוא הקדמה להן חזר והמיר וכו' ומה שאמרו תחלה מביא זבח על כרחין צריך שתים שא\\\"א לסברתו לתקן אלא בשתים וגם צריך להיות כל זה אחר שנפל בה מום כי אין חילול עד שיפול בו מום ולדעת רבינו אין זבח זה חילול רק הקדש מחדש. אלא שקשה למה הוצרכו לעשות תערובת זבח עתה כיון שסוף סוף צריך להביא שתים עולה ושלמים ימתין עד שתומם כדברי הר\\\"א ובדין חזר והמיר שאמרו בתוספתא גם זה לדעת רבינו על הדרך שכתב שיקדיש עתה מחדש אותו זבח שמביא ויאמר אם זו שהמרתי המרתי בתמורה אינה כלום וזה הזבח שאני מביא חולין הוא ואם המרתי בשניה שהקדשתי אני מקדיש זבח זה שאני מביא באופן אם אותה תמורת עולה שהזבח הראשון שהקדשתי היה עולה כי התמורה היה שלמים זה אני מקדיש לשלמים ואם היה שלמים זה אני מקדיש לעולה וזה שכתב רבינו אם תמורת עולה או שלמים ה\\\"ז שהביא עולה או שלמים כלומר אם תמורת עולה זו שלמים ואם תמורת שלמים זו עולה גם בזה כתב הר\\\"א ולפיכך כשחזר והמיר באחת מהן וכו' ע\\\"כ:\",3,0],[8,373,3,7,\"שלמים שנתערבו בבכור או במעשר וכו'. תוספתא בפ' הנזכר:\",1,0],[8,373,4,1,\"כיצד דין ולדות ולד שלמים ולד תמורת שלמים הרי אלו כשלמים וכו'. משנה פרק ג' דתמורה (דף י\\\"ז).\",1,0],[8,373,4,1,\"ומה שכתב במה דברים אמורים בולדות עצמם אבל ולדי ולדות אינם קריבים וכו'. שם וכרבי יהושע בן לוי:\",2,0],[8,373,4,3,\"השוחט את החטאת ומצא בה בן ארבעה חי וכו'. כך היא הגירסא הנכונה והיא ברייתא בפירקא קמא דתמורה (דף י':) וקסבר האי תנא ולדות קדשים ממעי אימן הם קדושים ואף על גב דאיכא תנא דפליג ואמר בהוייתן הם קדושים משמע לרבינו דהלכה כהאי תנא מדאמרינן בריש פרק כיצד מערימין (תמורה דף כ״ה) דרבן שמעון בן גמליאל סבר כההוא תנא משמע דרבנן פליגי עליה והלכתא כוותייהו. אבל יש לתמוה דהוה ליה למפסק כרבן שמעון בן גמליאל דכל מקום ששנה במשנתנו הלכה כמותו וצריך עיון:\",1,0],[8,373,4,4,\"ולד תמורת האשם וכו'. משנה פרק ג' דתמורה (דף כ':).\",1,0],[8,373,4,4,\"ומ\\\"ש ואם ילדה זכר אחר שהקריב אשמו. שם אמר רב נחמן וכו' מחלוקת לפני כפרה אבל לאחר כפרה דברי הכל הוא עצמו יקרב עולה ופריך והא תני רב חנניה לסיועי לריב\\\"ל ואסיק בקשיא ומשמע לרבינו דכיון דלא אסיקנא בתיובתא לית לן למדחייה לדרב נחמן ורבה בר אבוה מהלכתא לשוויינהו טועים. ואפשר דבגירסת רבינו לא הוה מסיק לה בקשיא אלא הוה מתרץ לה. והראב\\\"ד כתב א\\\"א זה אין לו שורש וכו'. וכבר כתבתי טעם לדברי רבינו. ולענין מה שהקשה הראב\\\"ד כתב הר\\\"י קורקוס ז\\\"ל די\\\"ל דמפריש נקבה לעולה עיקר הקדושה אינה קריבה וכיון דאימיה לא קרבה גם הולד לא יקרב אבל ולד תמורת אשם עיקר הקדושה זכר היה וקרב ונהי דתמורה הלכתא גמירי לה ולד תמורה נהי דאשם א\\\"א שיקרב מידי קדושת מזבח לא נפיק ובנולד קודם שהקריב דאיכא למיחש לאיחלופי גזרו שלא יקרב הוא עצמו אלא דמיו ובהכי לא אתי לאיחלופי לרבנן כיון שהוא עצמו אינו קרב אבל נולד אחר שהקריב אשמו אפילו יקריב הולד עצמו עולה לא שייך איחלופי ולפיכך לא גזרו עכ\\\"ל:\",2,0],[8,373,4,4,\"הפריש נקיבה לאשמו וכו'. פשוט פרק ג' דתמורה (דף י\\\"ט).\",3,0],[8,373,4,4,\"ומ\\\"ש ואם כבר הקריב אשמו יפלו דמיהם לנדבה. שם במשנה:\",4,0],[8,373,4,5,\"ולד תמורת העולה וכו'. משנה שם (דף י\\\"ח:).\",1,0],[8,373,4,5,\"ומ\\\"ש הפריש נקבה לעולתו וילדה וכו'. גם זה משנה שם ופסק כת\\\"ק:\",2,0],[8,373,4,5,\"כבר ביארנו במעשה הקרבנות וכו': וב\\\"ד מקריבים באותם המעות עולות נדבה וכו' עד ונסכיה משלו. משנה בפרק ג' דתמורה (דף כ':):\",3,0],[8,373,4,6,\"ולד המעשר תמורת המעשר וכו'. ג\\\"ז משנה שם (דף כ\\\"א):\",1,0],[8,373,4,7,\"ולד תמורת הפסח וכו'. שם משמע הכי:\",1,0],[8,373,4,7,\"הפריש נקבה לפסחו וילדה וכו'. שם (דף י\\\"ט):\",2,0],[8,373,4,8,\"ולדות הקדשים שיצאו דרך דופן וכו':\",1,0],[8,373,4,9,\"ולד בעלת מום וכו'. בפירקא קמא (דף י') פלוגתא דבר פדא ור\\\"י ופסק כר\\\"י:\",1,0],[8,373,4,10,\"קדשים שהפילו וכו'. משנה בסוף תמורה (דף ל\\\"ג:):\",1,0],[8,373,4,11,\"המשנה את הקדשים וכו'. בסוף פרק המקדיש שדהו (ערכין דף כ״ט).\",1,0],[8,373,4,11,\"ומ\\\"ש שאין משנים אותן מקדושה לקדושה אחד קדשי מזבח ואחד קדשי בדק הבית. משנה בפ\\\"ב דתמורה (דף ל\\\"ב).\",2,0],[8,373,4,11,\"ומ\\\"ש כיצד אם הקדיש לבדק ההיכל וכו': כתב הראב\\\"ד זה לא ידעתי מנין לו וכו'. ומ\\\"ש והרי הוא מודה שמשנין בדק הבית נראה לי שדייק כן ממה שאמר אם הקדיש לבדק ההיכל לא ישנה לבדק המזבח משמע דוקא מחמור לקל אין משנין אבל מקל לחמור משנין. ואפשר לומר שרבינו סבור שטענה זו שטען הראב\\\"ד לחלק בין קדשי מזבח לקדשי בדק הבית היא כדאי לומר שבבדק הבית רשאי לשנות מקל לחמור אבל אינה כדאי לומר שיהא רשאי לשנות מחמור לקל.\",3,0],[8,373,4,11,\"ומה שכתב רבינו שאין לוקין על לאו זה. טעמא משום דהוי לאו שאין בו מעשה. וכתב הר\\\"י קורקוס ז\\\"ל ואע\\\"ג דמקדיש בעל מום לוקה התם שאני דבדיבוריה עביד מעשה שמשנה הבהמה מחולין לקדש אבל כאן לא עביד כלום בדיבוריה כי אין דבריו מועילים כלל כמבואר שם גם בבכורות פרק אחרון (דף נ\\\"ג:) אמרו השתא קדושה חמורה אקדושה קלה לא חיילא קלה אחמורה מבעיא מאי היא דתנן אחד קדשי מזבח ואחד קדשי בדק הבית אין משנין אותם מקדושה לקדושה וכו' מוכח ודאי הכי הוא דלא חיילא ולא אמר כלום ומסתמא כל כמה דלא מפרש שאם עשה חל עכ\\\"ל:\",4,0],[8,373,4,13,\"כיצד מערימין על הבכור וכו' עד שהבכור ביציאתו הוא שמתקדש. משנה וגמרא ברפ\\\"ה דתמורה (דף כ\\\"ד:):\",1,0],[8,373,4,13,\"סליקו הלכות תמורה בס\\\"ד\",2,0],[8,374,1,1,\"המת מטמא במגע ובמשא ובאהל טומאת שבעה וטומאת מגע ואהל מפורשים בתורה. כמ״ש רבינו וטומאת משא בפרק כ״ג ונזיר (דף נ״ו ע״ב) במשנה ובפרק תינוקת (נדה דף ס״ט) ושנינו בפ״ב דאהלות דאפי' עצם כשעורה מטמא במשא:\",1,0],[8,374,1,2,\"טומאת משא מפי השמועה וק״ו הדברים וכו'. סיפרי פ' פרה על פסוק וכל אשר יגע על פני השדה ויש לתמוה דהא אין עונשין מן הדין וכן אמרו שם על פסוק הנוגע במת לכל נפש אדם בא ולימד על המת שמטמא במגע הא עד שלא יאמר יש לי בדין אם מטמא באהל לא יטמא [במגע] אלא אם אמרת כן ענשת מן הדין ואפשר לומר שמשם למדנו שאין עונשין מן הדין שזה בניין אב. ואם תאמר והרי בטומאת משא ובבת ובאיסור אכילת בשר בחלב ענשו מן הדין וי״ל שמאחר שבת הבת אינה אסורה אלא מחמת הבת שהיא אמה ממילא משמע שהיא אסורה ואין כאן עונשין מן הדין וכך אמרו בפרק הנשרפין (סנהדרין דף ע״ו) גבי איסור הבת וכי עונשין מן הדין גילוי מילתא בעלמא הוא ופירש״י כמ״ש, ובשר בחלב מכיון שאסר בישולו הוי בכלל לא תאכל כל תועבה כל שתיעבתי לך הרי הוא בבל תאכל א״נ דמשמע שלא אסרה תורה לבשל אלא כדי שלא יבוא לאכול ובמת משמע דגילוי מילתא בעלמא הוא שמאחר שמטמא במגע ובאהל ממילא משמע שמטמא במשא והתוס' בריש ב״ק גמגמו בהא דאין עונשין מן הדין:\",1,0],[8,374,1,2,\"אין טומאת משא במת מד\\\"ס וכו'. בא ללמדנו שלא נאמר דטומאת משא מדרבנן והא דמייתי לה מק\\\"ו אסמכתא בעלמא הוא:\",2,0],[8,374,1,3,\"מ\\\"ש ואפילו בלשונו. פ\\\"ק דקידושין (דף כ\\\"ה).\",1,0],[8,374,1,3,\"ומ\\\"ש וכן יראה לי שאם נגע בצפרניו או בשיניו נטמא. למד כן מדתנן בפרק שלישי דאהלות שאם נגע בצפרניו ובשיניו של מת נטמא ומשמע לרבינו דה\\\"ה לטהור שנגע בטומאה בצפרניו ובשיניו דכיון דבמת חשיבי כגופו ה\\\"ה דבחי חשיבי כגופו דמאי שנא.\",2,0],[8,374,1,3,\"ומ״ש אבל אם תחב אדם טומאה בכוש וכו'. פרק יוצא דופן (נדה דף מ״ב ע״ב) ואמר רבא דנהי דבמגע לא מטמא במשא מיהא מטמא וז״ש לא נטמא הבולע משום מגע כלומר אבל משום משא מטמא וכתבו רבינו לקמן בסמוך:\",3,0],[8,374,1,4,\"קרום שעל המכה וכו' וכשות שעל הקטן וכו'. משנה פ\\\"ט דמקואות (משנה ד'):\",1,0],[8,374,1,4,\"וכתב הראב\\\"ד א\\\"א אמת שכך פירש בערוך וכו'. ולי נראה שמה שכתב הערוך שהוא שיער הדק שעל בשר הקטן אינו שיער ממש אלא כמין שיער הגדל על בשר הקטן ונקרא בערבי זגאב ובלשון לעז ויליי\\\"ו והוא נושר מאליו ולכך אמרו שאינו חשוב כגוף משא\\\"כ בשיער ממש:\",2,0],[8,374,1,4,\"וכן לכלוכי צואה וכו' אינם כעור הבשר לא לטמא ולא להתטמא. כך היא הגירסא הנכונה בספרי רבינו והיא תוספתא בפ\\\"ו דמקואות וז\\\"ל שאמרו חוצצין ושאמרו אין חוצצין לא טמאין ולא מיטמאין חוץ מקרום שעל המכה:\",3,0],[8,374,1,5,\"כשם שאדם מתטמא בנגיעתו וכו' חוץ מכלי חרס וכו'. משנה ספ\\\"ק דחולין (דף כ\\\"ד ע\\\"ב) ובפרק ב' דכלים:\",1,0],[8,374,1,5,\"וזהו כלל גדול בטומאה וכו'. ואין אדם וכלים מקבלים טומאה אלא מאב הטומאה. בריש ב\\\"ק (דף ב' ע\\\"ב):\",2,0],[8,374,1,6,\"טומאת משא האמורה בכל מקום וכו' אפילו היה בינו לבינה אבן וכו'. לכאורה נראה שטעם רבינו מהא דאמרינן בר״פ ר״ע (שבת דף פ״ב ע״ב) דאמרינן דנדה מטמאה באבן מסמא ופי' אבן מסמא נתבאר שם ובר״פ דם הנדה (נדה דף נ״ה) ברש״י ובתוס' וברבינו שמשון פ״ק דכלים (משנה ג') ובפ״ה דזבים ובפרק תינוקת ברש״י אבל קשה דבפרק תינוקת (נדה דף ס״ט ע״ב) תנן הזב והזבה וכו' שמתו מטמאין במשא עד שימוק הבשר ואמרינן בגמרא מאי במשא אילימא במשא ממש אטו כל מת מי לא מטמא במשא אלא מאי במשא באבן מסמא משמע דמת שאינו זב אינו מטמא באבן מסמא ולכן נ״ל שאבן מסמא הוא שהכלים למטה ואבן גדולה מונחת עליהם והטמא יושב על האבן ומצד גודל האבן וכובדה אין הטמא נישא על הכלים ובכה״ג אינם טמאים אלא בזב וחביריו בלבד וכמ״ש רבינו בפ״ה מהלכות אלו ופ״ו מהלכות מטמאי משכב ומושב והוא מבואר במשנה פ״ו דעדיות (משנה ג') ופ״ד דזבים וכדדריש לה בת״כ גבי זב וה״ה לחביריו וכן בפרק ר' עקיבא אמרו דנדה מטמאה באבן מסמא וה״ה לחביריה אבל כל שאר המטמאים במשא ואפילו מת אינם מטמאים כן וכמ״ש רבינו פ״ה מהלכות אלו. ומ״ש רבינו כאן אינו ענין לאבן מסמא דאבן מסמא היא מלמטה על המרכב או על המשכב ומ״ש רבינו הוא שהאבן מונחת על המטמא במשא והכלים מונחים עליה שהרי הם נישאים על הזב וזו היא ששנינו בפ״ה דזבים (משנה ב) גבי כלל שני דרבי יהושע אצבעו של זב (תחת האבן או) תחת הנדבך הטהור מלמעלה מטמא שנים ופוסל אחד הטמא מלמעלה והטהור מלמטה מטמא שנים ופוסל אחד דזב לענין זה לאו דוקא דה״ה לכל המטמאים במשא.\",1,0],[8,374,1,6,\"ומ\\\"ש ואחד הנושא על ראשו או על ידו או על שאר גופו. נלמד מהמשנה שכתבתי בסמוך.\",2,0],[8,374,1,6,\"ומ\\\"ש או שנשאה אחר והניחה למעלה מזה וכו':\",3,0],[8,374,1,7,\"מסיט בכלל נושא הוא. בפרק העור והרוטב (חולין דף קכ״ד ע״ב) אטו נושא לאו מסיט הוא גם בפרק ר״ע הוזכר היסט משום משא ובסיפרי גבי מת למדו שמטמא בהיסט ק״ו מנבילה ובריש תוספתא דאהלות שהמסיט מטמא במת ואע״פ שבסוף פרשת פרה כתוב שם שאינו מטמא בהיסט לא חש לה רבינו מפני שהוא היפך התוספתא:\",1,0],[8,374,1,8,\"הנושא בתוך בית הסתרים וכו'. בפרק יוצא דופן (נדה דף מ״ב) כמ״ש בסמוך.\",1,0],[8,374,1,8,\"ומ\\\"ש אא\\\"כ נבלע הטומאה בתוך מעיו וכו'. שם.\",2,0],[8,374,1,8,\"ומ״ש ואם טבל טהר ואע״פ שהטומאה בתוך מעיו. משנה בסוף נדה ואיתא בפרק בהמה המקשה (חולין דף ע״א ע״ב):\",3,0],[8,374,1,9,\"אין מתטמא במשא אלא האדם בלבד וכו'. תוספתא בריש אהלות ובתורת כהנים ובמשנה פ\\\"ה דזבים (מ\\\"ג) כל הנושא ונישא על המשכב טהור חוץ מן האדם:\",1,0],[8,374,1,10,\"טומאת אהל אינה בשאר טומאות אלא במת בלבד. משנה פ\\\"ק דכלים (מ\\\"ד) חמור מכולם המת שהוא מטמא באהל מה שאין כולם מטמאין.\",1,0],[8,374,1,10,\"ומ\\\"ש ובין שהאהיל האדם או הכלי וכו'. בריש פ\\\"ג דאהלות (משנה א'):\",2,0],[8,374,1,11,\"אחד הבא כלו לאהל המת או הבא מקצתו וכו'. בפ' ג' מינים (נזיר דף מ״ג) ואיתיה בת״כ:\",1,0],[8,374,1,11,\"נגע במשקוף וכו'. משנה פי\\\"ב דאהלות נגע במשקוף טמא.\",2,0],[8,374,1,11,\"ומ\\\"ש וצירף ידו. איני יודע למה הצריך שיצרף ידו שמלשון המשנה משמע דבנגיעה בעלמא טמא ואין צורך לצירוף יד ואפשר דמשמע לרבינו דלישנא דנגיעה לאו דוקא ואינו טמא אא\\\"כ צירף ידו או אפשר דנגיעה היינו צירף ידו שכתב רבינו וכאילו יהיב טעמא למה אם נגע טמא וצ\\\"ע.\",3,0],[8,374,1,11,\"ומ\\\"ש נגע באסקופה וכו'. ג\\\"ז שם במשנה וכר' יהושע ונראה מדברי רבינו שם דטעמא משום דכשטומאה בבית הוי הבית כקבר סתום ומטמא כל סביביו הילכך הנוגע באסקופה מטפח ולמעלה טמא כנוגע בכותל מכותלי הבית. מטפח ולמטה טהור כנוגע בקרקע עולם וזה הפך ממ\\\"ש בשמו בסמוך לחד לישנא אצל צירף ידו ואפשר שכאן חזר בו ור\\\"ש כתב רבי יהושע מטמא באסקופה מטפח ולמעלה משום דדרך הטומאה לצאת:\",4,0],[8,374,1,11,\"כתב הראב\\\"ד נגע באסקופה מטפח ולמטה וכו'. א\\\"א מצאתי בתוספתא דאהלות וכו'. כתב תוספתא זו מפני שנותנת טעם למה מטפח ולמטה טהור מטפח ולמעלה טמא:\",5,0],[8,374,1,12,\"אחד המת מישראל או מן העכו״ם מטמא במגע ובמשא. בפרק הבא על יבמתו (יבמות דף ס״א) מסקנא דרבינא אפילו לרשב״י:\",1,0],[8,374,1,13,\"ומ״ש ואין העכו״ם מטמא באהל. שם לרשב״י ואע״ג דרבנן פליגי עליה פסק כמותו משום דמשמע שם דרבינא סבר כוותיה ועוד דבס״פ המקבל (בבא מציעא דף קי״ד ע״ב) אמרי' דא״ל רבה לאליהו לאו כהן הוא מר מ״ט קאי בבית הקברות א״ל לא מתני מר טהרות דתניא רשב״י אומר קברי עכו״ם אינם מטמאין:\",1,0],[8,374,1,13,\"וכן העכו״ם אינו נעשה טמא מת וכו'. בפרק בתרא דנזיר (דף ס״א ע״ב) אמרינן יצא העכו״ם שאין לו טומאה ובפרק לא יחפור (בבא בתרא דף כ') אמרינן דעכו״ם שישב בחלון ממעט בחלון אלמא לאו בר קבולי טומאה הוא וכן מפורש בתוספתא ריש אהלות. ודין בהמה מבואר בריש פרק ח' דאהלות שבהמה וחיה חוצצין מפני הטומאה:\",2,0],[8,374,1,14,\"ומדברי סופרים שיהיו העכו״ם וכו'. פרק בנות כותיים (נדה דף ל״ד):\",1,0],[8,374,1,14,\"אחד גדול ואחד קטן כו'. משנה וגמרא בפרק קמא דערכין (דף ג') ובפרק יוצא דופן (נדה דף מ״ג ע״ב) ושיעור לשון רבינו כך הוא אפילו בטומאת מת שנאמר בה איש מטמא אף הקטן משום שנאמר ועל כל הנפשות ומוקי לה שם שכלו לו חדשיו.\",2,0],[8,374,1,14,\"ומ״ש אבל בן שמונה הרי הוא כאבן וכו'. בפרק לא יחפור (בבא בתרא דף כ') בן שמונה הרי הוא כאבן וממעט בחלון:\",3,0],[8,374,1,15,\"המת אינו מטמא עד שתצא נפשו אפילו מגוייד או גוסס. משנה פרק קמא דאהלות (משנה ו').\",1,0],[8,374,1,15,\"ומה שכתב אפילו נשחטו בו ב' הסימנים כו'. בפרק מי שאחזו (גיטין דף ע' ע״ב) אמר שמואל שחט בו שנים [או רוב שנים] ורמז ואמר כתבו גט לאשתי הרי אלו יכתבו ויתנו אלמא חי הוא ובפרק העור והרוטב (חולין דף קכ״א ע״ב) גבי בהמה שחט בה שנים או רוב שנים [ומפרכסת] מטמאה טומאת אוכלין אבל לא טומאת נבילה אבר ובשר הפורשים כפורש מן החי ובפרק ב' דחולין (דף ל') תניא שחט בה שנים או רוב שנים ועדיין היא מפרכסת הרי היא כחיה לכל דבריה. אך קשה דבפירקא קמא דאהלות (משנה שם) תנן הותזו ראשיהם אף על פי שמפרכסים טמאים וקאמר עלה בסוף פירקא קמא דחולין (דף כ״ח) מאי הותזו ר״ל אמר הותזו ממש ר' אסי אמר [רבי מני] כהבדלת עולת העוף וכו' לר' אלעזר בר״ש ומשמע התם דאפילו מאן דאמר הותזו ממש היינו שחיטת שני הסימנים וצריך לומר שרבינו מפרש דהותזו ממש היינו שנחתך כל הצואר משום דנשברה מפרקת ורוב בשר עמה הא לאו הכי אף על פי שנחתכו הסימנים אינו מטמא וזה נראה מדבריו בסוף פרק ד' משאר אבות הטומאה גבי הותזו ראשיהם דגבי שרץ ואף על גב דלמאי דאמר התם דא״ל ר' ירמיה לר' אסי כהבדלת העוף לרבנן ולא פליגיתו משמע דלחתיכת שני הסימנים קרי הותזו דהא רבנן לא ממעטי אלא דלא נימא דברוב שנים סגי אבל בכל השנים משמע דסגי למליקה ומדקאמר ולא פליגיתו משמע דמאן דאמר הותזו ממש בחתיכת שני הסימנים סגי וי״ל דאפילו תימא דלישנא קמא סבר הכי וכדמשמע מפירש״י ללישנא בתרא ליכא הכרע ואיכא למימר דהותזו ממש היינו הותז לגמרי כפשטיה ועוד י״ל דאפילו ללישנא קמא בעינן הותז כל הראש לגמרי וכפשטא דלישנא דברייתא דקתני אף מליקה הראש בעצמו והגוף לעצמו ודלא כפירש״י:\",2,0],[8,374,1,15,\"נשברה מפרקתו ורוב בשרה עמה וכו' עד סוף הפרק. בסוף פרק קמא דחולין (דף כ': כ\\\"א.):\",3,0],[8,374,2,1,\"הנפל אע\\\"פ שעדיין לא נתקשרו איבריו בגידין וכו'. בפרק כה\\\"ג ונזיר (דף נ').\",1,0],[8,374,2,1,\"ומ\\\"ש וכן כזית מבשר המת. משנה שם (דף נ\\\"ט ע\\\"ב)\",2,0],[8,374,2,1,\"ומ״ש בין לח בין יבש וכו'. משנה ריש פרק דם הנדה (נדה דף נ״ד ע״ב) וכתנא קמא ואמרינן בגמרא (דף נ״ה) דלרבי יוחנן אם יבש כל כך עד שנפרך טהור ובפ״ג יתבאר:\",3,0],[8,374,2,1,\"ומ\\\"ש והנצל בבשר מטמא בכזית. משנה רפ\\\"ב דאהלות (מ\\\"א) ופרק כה\\\"ג ונזיר (דף נ'):\",4,0],[8,374,2,1,\"איזהו נצל וכו'. שם בגמרא:\",5,0],[8,374,2,2,\"אף על פי שהשיעורין כולם הלכה למשה מסיני הן. בפירקא קמא דעירובין.\",1,0],[8,374,2,2,\"ומה שכתב אמרו חכמים תחלת ברייתו של אדם כזית וכו'. בסיפרי זוטא:\",2,0],[8,374,2,3,\"אבר שנחתך מן האדם החי וכו'. משנה בפ\\\"ב דאהלות (שם במשנה) ופכה\\\"ג ונזיר (דף נ').\",1,0],[8,374,2,3,\"ומה שכתב אפילו אבר של קטן בן יומו שהאיברים אין להם שיעור. פ\\\"ק דאהלות (משנה ז').\",2,0],[8,374,2,3,\"ומ\\\"ש שנאמר כל אשר יגע על פני השדה וכו' והדבר ידוע וכו'. סיפרי פרשת חקת.\",3,0],[8,374,2,3,\"ומ\\\"ש מפי השמועה וכו'. פ' כה\\\"ג (דף נ\\\"ג נ\\\"ד).\",4,0],[8,374,2,3,\"ומ״ש בד״א כשהיה האבר שלם וכו'. בתוספתא דאהלות פ״ק ובסיפרי יליף לה מקרא ובס״פ העור והרוטב (חולין דף קכ״ח ע״ב) תניא הכי לגבי בהמה ושרצים.\",5,0],[8,374,2,3,\"ומ\\\"ש אבל הכוליא והלשון וכו'. שם כר\\\"ע. ודע דאמרינן התם בגמרא דר\\\"ע לא מצרך בשר אלא אפילו ארכובה הנמכרת עם הראש שאין בה בשר כלל אלא גידים ועצמות מטמא וא\\\"כ יש לתמוה על רבינו שהצריך בשר כיון דר\\\"ע לא מצריך ועוד דרבי יוסי הגלילי קאי כוותיה והוה לי' תרי לגבי רבי דמצריך וצ\\\"ע:\",6,0],[8,374,2,3,\"חסר מן העצם של וכו'. בפ\\\"ב דאהלות (משנה ה') אלו שאם חסרו טהורים וכו' אבר מן החי שחסר עצמו וכתב ר\\\"ש נראה שחסר עצמו לאו דליכא עצם כלל אלא אפילו חסר ממנו שאינו כברייתו ואפילו קולית גדולה שחסר משהו ממנה תו לא מטמאה משום אבר מן החי והשתא ניחא דלא תני שחסר בשרו דאי יש בו בשר הרבה וחסר מטמא לעולם עד שיחסר מכדי להעלות ארוכה וכן תנן נמי בעדיות פרק ו' וכו' מרובה טומאת עצמות מטומאת בשר שהבשר הפורש מן החי טהור ואבר הפורש מן החי והוא כברייתו טמא והיינו כברייתו שלא חסר העצם אך עומד שלם כמו שנברא עכ\\\"ל. גם רבינו כתב שם התנו באבר מן החי שחסר עצמו לא אמר ג\\\"כ שחסר בשרו לפי שאם חסר בשרו ונשאר עליו כדי לעלות ארוכה הנה הוא מטמא וכו' אולם אם נחסרו קצת העצמות מזה האבר ואע\\\"פ שנשאר בשרו בכללו ובזה הבשר יותר מכזית הנה הוא לא יטמא מין ממיני הטומאה ואפילו הנשאר מן העצם האבר לא נדמהו עצם כשעורה מן המת וזהו ההפרש בין אבר מן החי ובין אבר מן המת לפי שאבר מן המת כזית בשר הפורש ממנו ועצם כשעורה הפורש ממנו טמא עכ\\\"ל. ואע\\\"פ שיש בו קצת ט\\\"ס כוונתו נכרת שהוא כמ\\\"ש כאן.\",7,0],[8,374,2,3,\"ומה שכתב אם נשאר עליו בשר שראוי לעלות בו ארוכה וכו'. משנה בפירקא קמא דכלים (משנה ה'):\",8,0],[8,374,2,3,\"ובשר הפורש מן החי טהור. משנה פרק ו' דעדיות (משנה ג').\",9,0],[8,374,2,3,\"ומ\\\"ש וכן עצם בלא בשר הפורש וכו'. כן משמע שם במשנה:\",10,0],[8,374,2,4,\"אבר הפורש מן המת וכו'. משנה שם ובעדיות רבי יהושע ורבי נחוניא בן אלינתן.\",1,0],[8,374,2,4,\"ומה שכתב והוא שיהיה שלם כברייתו. בספרי פרשת חקת ובתוספתא דאהלות פרק קמא.\",2,0],[8,374,2,4,\"ומה שכתב חסר עצמו אם נשאר עליו כזית בשר מטמא כמת שלם. בפרק ב' דאהלות (משנה א') דכזית בשר מן המת מטמא באהל והוא פשוט בכמה מקומות.\",3,0],[8,374,2,4,\"ומה שכתב חסר הבשר ולא חסר העצם אם נשאר עליו כדי לעלות ארוכה בחי וכו'. כך היא הגירסא בדברי רבינו והדין בפרק קמא דכלים (מ\\\"ה). ואם חסר קצת עצמו ולא נשאר בו כזית בשר אבל יש בבשר הנשאר כדי לעלות ארוכה כתב רבינו בפרק שאחר זה שמטמא במגע ובמשא ואינו מטמא באהל ולא חשש רבינו לכתבו כאן מפני שסמך על מה שכתב שם:\",4,0],[8,374,2,4,\"כתב הראב\\\"ד אם נשאר עליו כדי להעלות ארוכה בחי מטמא כמת שלם וכו'. א\\\"א טעה בזה שאם חסר העצם אינו כמת שלם וכו'. ט\\\"ס יש כאן שאין דברי הראב\\\"ד ענין למ\\\"ש רבינו אם נשאר עליו כדי להעלות ארוכה בחי אלא למ\\\"ש חסר עצמו אם נשאר עליו כזית בשר מטמא כמת שלם ומ\\\"מ איני מבין דברי הראב\\\"ד שהשיג על רבינו שכתב ואם חסר עצמו אם נשאר עליו בשר כזית מטמא כמת שלם והראב\\\"ד סובר שאינו כמת שלם אלא מטמא במגע ובמשא ואינו מטמא באהל ויש לתמוה עליו שהרי שנינו ברפ\\\"ב דאהלות (משנה א') שכזית מן המת מטמא באהל ואין סברא לחלק בין כזית בשר הפורש מן המת לכזית בשר הפורש מאבר שפירש מן המת וצ\\\"ע:\",5,0],[8,374,2,5,\"מוח שבתוך העצם וכו' עד לכל דבר. בפרק העור והרוטב (חולין דף קכ״ה) וכר״י ובתוספתא ריש אהלות שם שנינו מוח הרי הוא כבשר לכל דבר:\",1,0],[8,374,2,6,\"האבר והבשר המדולדלים באדם וכו'. משנה בפרק העור והרוטב (חולין דף קכ״ט ע״ב) האבר והבשר המדולדלים באדם טהורים ופירש״י משום דכי ימות כתיב ומשמע לרבינו דאפילו באינם יכולים לחזור ולחיות מיירי דאי יכולים לחזור ולחיות פשיטא.\",1,0],[8,374,2,6,\"ומ\\\"ש מת האדם הרי הבשר טהור וכו'. שם מת האדם הבשר טהור האבר מטמא משום אבר מן החי ואינו מטמא משום אבר מן המת דברי ר\\\"מ ור\\\"ש מטהר ובגמרא ור\\\"ש ממ\\\"נ אי מיתה עושה ניפול ליטמא משום אבר מן החי ואי אין מיתה עושה ניפול ליטמא משום אבר מן המת ר\\\"ש בעלמא קאי דקאמר תנא קמא וכו' אינו מטמא משום אבר מן המת אלמא אבר מן המת בעלמא מטמא וכו' וכבר נתבאר שאבר מן המת מטמא וא\\\"כ קם ליה הלכה כר\\\"מ:\",2,0],[8,374,2,6,\"מה בין אבר מן החי לאבר מן המת וכו'. בפ\\\"ו דעדיות (משנה ג') וכר' יהושע דבכל חדא הוי רבים במקום יחיד כמבואר שם.\",3,0],[8,374,2,6,\"ומ\\\"ש ואבר מן המת בשר הפורש ממנו ועצם הפורש ממנו וכו'. פשוט הוא:\",4,0],[8,374,2,7,\"ובין אבר מן החי ובין אבר מן המת אין להם שיעור. בפרק קמא דאהלות (משנה ז') האיברים אין להם שיעור:\",1,0],[8,374,2,7,\"אמרו חכמים רמ\\\"ח איברים יש באיש וכו'. שם.\",2,0],[8,374,2,7,\"ומ״ש ובאשה רנ״א. בס״פ מומין אלו (בכורות דף מ״ה) אמרינן שתלמידי ר' ישמעאל בדקו ומצאו באשה רנ״ב ואמר להם באשה יש ארבע איברים יתירים ב' צירים וב' דלתות ואמרינן בתר הכי ר״א אומר כשם שצירים לבית כך צירים לאשה ר' יהושע אומר כשם שדלתות לבית כך דלתות לאשה וכו' ר״ע אומר כשם שמפתח לבית כך מפתח לאשה וכו' ולר״ע קשיא דתלמידי רבי ישמעאל דילמא איידי דזוטרא איתמוחי מתמח ומדמקשה לר״ע ולא מקשה לר״א ורבי יהושע משמע דס״ל דר״א ורבי יהושע מר אמר חדא ומר אמר חדא ולא פליגי ולדברי שניהם רנ״ב איברים הוו באשה וכדר' ישמעאל ור״ע מוסיף עוד מפתח והו״ל רנ״ג איברים באשה ולפיכך יש לתמוה על רבינו שכתב שאינם אלא רנ״א דהוי דלא כמאן ואפשר לומר שסובר רבינו דר״א ורבי יהושע פליגי ור״ע מוסיף אחד מינייהו ה״ל רנ״א באשה ופסק כמותו והא דלא מקשה גמרא מתלמידי ר' ישמעאל על ר״א ורבי יהושע אין הכרע דאיכא למימר דמשמע להו דתרי מינייהו ליכא למר צירים ולמר דלתות אי נמי איתנהו אלא דלא חשיבי איברים אבל דר״ע שלא הוזכר כלל קשיא.\",3,0],[8,374,2,7,\"ומה שכתב כל אבר מהם שפירש וכו' מטמא במגע ובמשא ובאהל. בפ\\\"ק דאהלות (משנה ח').\",4,0],[8,374,2,7,\"ומ\\\"ש שפירש כברייתו. הוא ממ\\\"ש לעיל שצריך שיהיה שלם כברייתו בשר וגידים ועצמות.\",5,0],[8,374,2,7,\"ומ״ש חוץ מג' איברים יתרים שבאשה שאינן מטמאים באהל. בס״פ מומין אלו (בכורות דף מ״ה) האיברים יתירים שבאשה אמר רבא וכולם אין מטמאין באהל שנאמר זאת התורה אדם כי ימות באהל דבר השוה לכל אדם:\",6,0],[8,374,2,7,\"וכן אצבע יתירה וכו' עד תרומה וקדשים. שם ופרק בא סימן (נדה דף מ״ט ע״ב):\",7,0],[8,374,2,8,\"עצמות המת שאין עליהם בשר וכו'. משנה פ' כה\\\"ג ונזיר (דף מ\\\"ט ע\\\"ב) ופרק שני דאהלות (מ\\\"א) ובפ' כה\\\"ג ונזיר (דף נ\\\"ב) איבעיא לן אם צריך שתיהן שדרה וגולגולת או דילמא שדרה או גולגולת ובעי למפשט דאו או קתני ודחי ליה ויש לתמוה על רבינו שכתב הדין בפשיטות וכתב הר\\\"י קורקוס ז\\\"ל דאעפ\\\"כ כיון דאשכחן שמאי דאמר בהדיא או שדרה או גולגולת אלא דדחי דילמא שאני שמאי דמחמיר לא שבקינן מאי דאשכחן בהדיא כיון דלא אשכחן בה פלוגתא ומנ\\\"ל לחדושי פלוגתא וגם כי כל חלוקות המשנה או או קתני ומסתמא הני הוו דכוותייהו עכ\\\"ל.\",1,0],[8,374,2,8,\"ומ\\\"ש ואם חסרה אפילו חוליא אחת. בפ\\\"ב דאהלות (משנה ג') וכב\\\"ה.\",2,0],[8,374,2,8,\"ומ״ש ואם חסרה כסלע וכו'. בפרק ב' דאהלות שם כמה הוה חסרון וכו' בגלגולת ב״ה אומרים כדי שינטל מן החי וימות ומפרש בפרק על אלו מומין (בכורות דף ל״ז ע״ב) דהיינו כסלע.\",3,0],[8,374,2,8,\"ומ״ש היו בה נקבים קטנים וכו'. נלמד ממה שאמרו בפרק אלו טריפות (חולין דף מ״ה) וכדברי התוספות שם:\",4,0],[8,374,2,8,\"כל בניינו של אדם וכו'. בס״פ מומין אלו (בכורות דף מ״ה) ותוספתא פ״ג דאהלות:\",5,0],[8,374,2,8,\"כיצד כגון שתי שוקיו וירך א' וכו'. בס\\\"פ מומין אלו שם.\",6,0],[8,374,2,8,\"ומ\\\"ש ואם חסר כל שהוא וכו'. פשוט הוא:\",7,0],[8,374,2,8,\"רוב מניינו כיצד וכו'. פ\\\"ב דאהלות (משנה א').\",8,0],[8,374,2,8,\"ומ״ש אע״פ שהיה אדם זה יתר באיבריו או חסר באיבריו וכו'. בס״פ מומין אלו (בכורות דף מ״ה).\",9,0],[8,374,2,8,\"ומ\\\"ש אא\\\"כ היתה אצבע שיש בה צפורן או שהיתה נספרת ע\\\"ג היד. נתבאר בפרק זה:\",10,0],[8,374,2,9,\"שאר עצמות המת וכו' אם היה בהם רובע הקב. פ\\\"ב דאהלות שם אלו מטמאים באהל וכו' רובע עצמות מרוב הבנין או מרוב המנין ופרק קמא דעדיות ב\\\"ש אומרים רובע עצמות מן העצמים בין משנים בין מג' וב\\\"ה אומרים רובע עצמות מן הגוייה מרוב הבנין או מרוב המנין שמאי אומר אפילו מעצם א' משמע דלסתם מתניתין דפ\\\"ק דאהלות ולב\\\"ה דפ\\\"ו דעדיות רובע עצמות אינם מטמאים באהל אא\\\"כ הם מרוב הבניין או מרוב המניין וקשה דא\\\"כ מ\\\"ש רבינו ששאר עצמות אע\\\"פ שאין בהם לא רוב מנין ולא רוב בנין אם יש בהם רובע מטמאין באהל אתי דלא כב\\\"ה ודלא כסתם מתניתין דאהלות והוא דבר תימה ומצאתי בפירוש המשנה לרבינו מוגה שכתב בריש פ\\\"ב דאהלות אהא דתנן אלו מטמאים באהל רובע עצמות מרוב הבנין או מרוב המנין רוב בניינו ורוב מניינו של מת אע\\\"פ שאין בהם רובע הנה אלו ג' שיעורים בעצמות הערומים מן הבשר אחד מהם שיהיו באלו העצמות רוב גודל הגוף אשר הוא עצמותיו ואע\\\"פ שלא יהיה בהם רובע הקב. השני שיהיה בו רוב המנין והוא קכ\\\"ה איברים ואף ע\\\"פ שלא יהיה בהם רובע, והשלישי שיהיה בהם רובע עצמות או יותר אע\\\"פ שלא יהיה בהם לא רוב בניינו ולא רוב מניינו הנה אלו העצמות יטמאו באהל הואיל ויש בהם רובע מ\\\"מ כבר ביארנו ששורש זה כולו אמרו יתעלה בעצם אדם ואלו השיעורים הג' שיהיה בכל אחד מהם עצם אדם עד כאן לשון רבינו בפירוש המשנה המוגה ודבריו אלה הם כדבריו כאן אבל יש לתמוה שדברים אלו הם היפך פשט לשון המשנה ונראה שרבינו מפרש דהא דקתני רובע עצמות מרוב הבנין או מרוב המנין לאו למימרא שצריך שאותו רובע יהיה מהעצמות שברוב הבנין או רוב המנין אלא ה\\\"ק רובע עצמות שאין בהם לא רוב בנין ולא רוב מנין וכפי דקדוק דבריו פה הכי פירושא דמתניתין רובע עצמות שאין בהם מרוב הבנין ולא מרוב המנין כלומר אעפ\\\"י שהוא משאר עצמות זולתם אבל קשה לפי' זה מאי דאיתא בפ' כה\\\"ג (דף נ\\\"ב ע\\\"ב) על משנה זו א\\\"ר יהושע יכולני לעשות דברי ב\\\"ש וב\\\"ה כאחד שב\\\"ש אומרים משנים או מג' או מב' שוקים וירך א' או מב' יריכים ושוק א' וכו' וצ\\\"ל שסובר רבינו מדאמר יכולני משמע שהיה יכול לפרש כן אבל לפי האמת אינו מפרש כן.\",1,0],[8,374,2,9,\"ומ\\\"ש אפילו עצם כשעורה וכו'. שם:\",2,0],[8,374,2,10,\"היה עצם אחד אפילו יש בו רובע וכו'. במשנה שכתבתי בסמוך שמאי אומר אפילו מעצם אחד ומשמע דיחידאה הוא ולית הלכתא כוותיה ועוד דאמרו בפ' כה\\\"ג שאני שמאי שמחמיר טפי משמע בהדיא דלית הלכתא כוותיה:\",1,0],[8,374,2,10,\"טומאת עצם אחד הלכה מפי השמועה לפי שנאמר כל הנוגע בעצם למדו מפי השמועה אפי' עצם כשעורה וכו'. בפ' כה\\\"ג (דף נ\\\"ג נ\\\"ד).\",2,0],[8,374,2,10,\"ומ״ש ולפי שטומאתו הלכה. שם ובפרק העור והרוטב (חולין דף קכ״ו:) ובפ״ק דעירובין (דף ד'):\",3,0],[8,374,2,10,\"ומ\\\"ש הרי הוא מדין תורה ולא מד\\\"ס. כלומר אפילו לפי שיטתו שסובר שכל הנלמד בי\\\"ג מדות נקרא ד\\\"ס זה שהוא הל\\\"מ נקרא דין תורה כמ\\\"ש בהקדמתו לסדר זרעים:\",4,0],[8,374,2,11,\"מת שהרקיבו עצמותיו בקבר וכו'. בפרק שני דאהלות ופרק כה\\\"ג ונזיר (דף מ\\\"ט ע\\\"ב) תנן דמלא תרווד רקב מטמא באהל ובגמ' (דף נ' ע\\\"ב) וכמה שיעורו חזקיה אמר מלא פיסת היד ור' יוחנן אמר מלא חפניו ופסק כרבי יוחנן דאמרינן בגמרא דאתי כחכמים.\",1,0],[8,374,2,11,\"ומה שכתב שמטמא במשא ואינו מטמא במגע. בפרק העור והרוטב (חולין דף קכ״ו ע״ב) ותוספתא פ״ד דאהלות.\",2,0],[8,374,2,11,\"ומה שכתב ואפילו גבלו במים אינו חבור. משנה בפרק ב' דאהלות שם:\",3,0],[8,374,2,12,\"דם המת מטמא כמת במגע ובמשא ובאהל וכו' וכמה שיעורו רביעית. משנה בפ' כה\\\"ג (דף מ\\\"ט ע\\\"ב) ופרק ב' דאהלות שם:\",1,0],[8,374,2,12,\"ומ\\\"ש אפילו תמצית הדם וכו'. בר\\\"פ התערובות (דף ע\\\"ט ע\\\"ב) ובפרק כיסוי הדם (דף פ\\\"ז ע\\\"ב) אמרינן דצללתא דדמא מטמא באהל והוא דאיכא רביעית ופירש\\\"י צללתא דדמא אותם מים שהם מהדם עצמו כשהוא נקרש יש סביבותיו צלול כמים:\",2,0],[8,374,2,13,\"דם החי וכו'. נלמד ממה שיבא בסמוך:\",1,0],[8,374,2,13,\"נתערב הדם וכו' אפילו חצי רביעית מחיים וחציה אחר מיתה וכו'. בפ״ב דאהלות שם וכר' עקיבא והוא דעת חכמים בפרק תינוקת (נדה דף ע״א) והוא נקרא דם תבוסה.\",2,0],[8,374,2,13,\"ומה שכתב אלא שטומאתו מד\\\"ס. בפרק ט' דנדה (דף ס\\\"ב ע\\\"ב) ופרק הגוזל ומאכיל אמרו שאני דם תבוסה דרבנן:\",3,0],[8,374,2,14,\"הרוג שהי' מוטל על המטה ודמו מנטף וכו'. בסוף נדה (דף ע\\\"א) וכחכמים:\",1,0],[8,374,2,14,\"יצא ממנו רביעית דם בלבד וכו'. שם וכחכמים:\",2,0],[8,374,2,15,\"הקבר כל זמן שהטומאה בתוכו וכו' ואחד הנוגע בגגו של קבר וכו'. משנה פרק ז' דאהלות ופרק כהן גדול ובספרי.\",1,0],[8,374,2,15,\"ומה שכתב אבל המעמיד כלים או אבנים וכו' ושניהם הגולל או הדופק מטמאין במגע ובאהל כקבר ואינם מטמאין במשא וכו'. פרק ב' דאהלות:\",2,0],[8,374,2,15,\"ומה שכתב וטומאתן מדברי סופרים. דוקא בשכלים שכסה בהם הם כלי גללים וכיוצא בהם שאינם מקבלים טומאה שאם לא כן אף מן התורה טמא טומאת שבעה אדם הנוגע בהנך כלים המאהילים על המת:\",3,0],[8,374,2,15,\"כתב הראב\\\"ד א\\\"א לא מחוור ובמסכת חולין גרסינן כל אשר יגע על פני השדה וכו'. כלומר וכיון דרבי עקיבא יליף לה מקרא בפרק בהמה המקשה (חולין דף ע\\\"ב) משמע דמדאורייתא היא ורבי ישמעאל הא אמר הלכתא גמירי להו ומיניה נשמע לרבי עקיבא דכי היכי דלרבי ישמעאל הוי דאורייתא הוא הדין דלרבי עקיבא נמי הוי דאורייתא אלא דלמר הוי מקרא ולמר הוי מהלכתא ורבינו סובר דכיון דלא מפורש בקרא משמע דקרא אסמכתא בעלמא.\",4,0],[8,374,2,15,\"ומה שכתב ואינם מטמאין במשא. בפרק ב' דאהלות שם.\",5,0],[8,374,2,15,\"ומה שכתב לפיכך אם גרר הגולל וכו'. תוספתא פרק ג' דאהלות וביאור דברי רבינו כך הם והוא שיהיה בנוי וסתום כלומר דהא דאחד הנוגע בגגו או הנוגע בכותליו טמא הני מילי בשהיה בנוי לאפוקי מעמיד כלים או אבנים וכו' שאינו טמא אלא הנוגע בגולל או בדופק עצמם לא הנוגע בצדדים שאינם מהגולל והדופק ועל פי זה הנוגע בדופק דופקין טהור כך נראה לי ליישב דברי רבינו וגם נראה לומר דה\\\"ק הקבר וכו' מטמא דין תורה אבל המעמיד כלים וכו' טומאתן מדברי סופרים והתנה שיהיה סתום לאפוקי שלא יהא פתוח מן הצד:\",6,0],[8,374,2,15,\"ומה שכתב ודברים שסומכים את הדופק וכו'. פרק ב' דאהלות:\",7,0],[8,374,2,16,\"שדה שנחרש בה קבר וכו'. בסוף אהלות (פי\\\"ח מ\\\"ב):\",1,0],[8,374,2,16,\"וכן כל ארצות העכו\\\"ם וכו'. שם ובפרק שני (משנה ג').\",2,0],[8,374,2,16,\"ומ\\\"ש שטומאתם מד\\\"ס. בספ\\\"ב דכתובות (דף כ\\\"ח ע\\\"ב) ופ' כה\\\"ג:\",3,0],[8,374,3,1,\"אלו מטמאין במגע ובמשא ובאהל וכו'. פ\\\"ב דאהלות (מ\\\"א) ופירוש נצל בשר המת שנימוח ונעשה כמין ליחה סרוחה.\",1,0],[8,374,3,1,\"ומה שכתב אפילו נפל שלא נתקשרו איבריו בגידים וכו'. בפרק כה\\\"ג עלה נ':\",2,0],[8,374,3,2,\"ואלו מטמאים במגע ובמשא וכו'. (עיין בפנים). כך היא הנוסחא הנכונה בדברי רבינו וכן מצאתיה בספר מוגה ודינים אלו מדתנן בפ\\\"ב דאהלות אלו מטמאין במגע ובמשא ואינם מטמאים באהל אבר מן המת ואבר מן החי שאין עליהם בשר כראוי ובפ\\\"ק דכלים (משנה ה') גבי אדם תנן פירש ממנו אבר שיש עליו בשר כראוי מטמא במגע ובמשא ובאהל שיעור הבשר כדי לעלות ארוכה ובפ\\\"ו דעדיות תנן אבר שיש עליו בשר כראוי מטמא במגע ובמשא ובאהל חסר הבשר טמא חסר העצם טהור ופירש ה\\\"ר עובדיה אם חסר מהבשר שהיה עליו ונשאר בו בשר שראוי שיעלה ארוכה מטמא משום אבר אבל אם חסר כל שהוא מהעצם שבאבר אינו מטמא משום אבר אבל טמא משום בשר וזהו באבר מן המת דאילו באבר מן החי אם חסר מהעצם כל שהוא טהור לגמרי כמו שנתבאר בפרק שקודם זה שאם חסר כל שהוא מהעצם אף על פי שכל הבשר קיים טהור לגמרי מפני שבשר הפורש מן החי טהור אבל אם חסר מבשרו אם נשאר מן הבשר כדי להעלות ארוכה מטמא במגע ובמשא ובאהל ואם לאו מטמא במגע ובמשא ואינו מטמא באהל. ובדין אבר מן המת נתבאר שאם לא חסר העצם וחסר מהבשר אם הנשאר אין בו כדי להעלות ארוכה הרי הוא כשאר עצמות שהם מטמאים במגע ובמשא ואינם מטמאים באהל. ודין אבר מן המת שחסר העצם ונשאר בו בשר שאין בו כזית אבל יש בו כדי להעלות ארוכה שהוא מטמא במגע ובמשא נתבאר ממה שפירשנו במשנה דחסר העצם טהור משום אבר אבל מטמא משום בשר ודין הבשר הוא שאם אין בו כזית אם יש בו להעלות ארוכה מטמא במגע ובמשא ואינו מטמא באהל כמו שנתבאר במשנה פרק קמא דכלים שכתבתי בסמוך. כך צריך לפרש כפי נוסחא זו שמצאתי:\",1,0],[8,374,3,3,\"הגולל והדופק מטמאין במגע ובאהל וכו'. פרק ב' דאהלות (משנה ד') וכת\\\"ק:\",1,0],[8,374,3,3,\"הרקב מטמא במשא ובאהל ואינו מטמא במגע. כך היא הנוסחא הנכונה וכמו שנתבאר בפרק שקודם זה:\",2,0],[8,374,3,3,\"ומ\\\"ש טומאת אבר שאין עליו בשר כראוי. כלומר ואין בו עצם כשעורה דאם כן טמא מן התורה:\",3,0],[8,374,3,3,\"כתב הראב\\\"ד א\\\"א אף בזה טעה דאבר שאין עליו בשר כראוי וכו'. ויש לומר שכבר ימצא אבר שאין עליו בשר כראוי שעצם שבו לא יהא בו כשעורה כגון שהוא מנפל קטן וכדאמרינן בפרק כה\\\"ג על הא דתנן (דף מ\\\"ט ע\\\"ב) על אלו טומאות הנזיר וכו' וכזית מן המת.\",4,0],[8,374,3,3,\"ומ\\\"ש ורביעית דם באהל. מקרא הוא על כל נפשות מת לא יבא י\\\"ל שסובר רבינו דקרא אסמכתא בעלמא הוא שאם היה מן התורה היה הנזיר מגלח עליה. ומ\\\"ש הראב\\\"ד וחצי קב עצמות וחצי לוג דם כמת שלם נינהו וכו' וכן מ\\\"ש ונ\\\"ל מה שדימו ביאת מקדש לטומאת נזיר וכו'. אינו ענין להשיג על רבינו אלא ליתן טעם למה עצם כשעורה מטמא במגע ומשא ולא באהל ורביעית דם מטמא באהל ואינו מגלח על מגעו ועל משאו ולמה תלו חיוב טומאת מקדש בתגלחת נזיר:\",5,0],[8,374,3,4,\"אין רקב המת מטמא עד שיקבר ערום וכו'. בפכה״ג (דף נ״ח) ובפרק המפלת (נדה דף כ״ז ע״ב).\",1,0],[8,374,3,4,\"ומ\\\"ש ויהיה כולו שלם. ג\\\"ז שם:\",2,0],[8,374,3,4,\"ורקב המטמא שנתערב בו עפר כל שהוא וכו'. בפרק המפלת (נדה דף כ\\\"ז) מלא תרווד רקב שנפל לתוכו עפר כל שהוא טמא וכת\\\"ק ואיתיה בתוספתא פ\\\"ד דאהלות:\",3,0],[8,374,3,4,\"ולא אמרו רקב אלא למת בלבד וכו'. בפרק המפלת עלה כ\\\"ז:\",4,0],[8,374,3,5,\"קברו שני מתים כאחד או שגזזו שערו או צפרניו וכו'. בפרק כה\\\"ג (דף נ\\\"א).\",1,0],[8,374,3,5,\"ומ\\\"ש או שקברו אשה מעוברת וכו'. שם בעי רבי ירמיה עובר במעי אשה וכו' את\\\"ל כיון דסופו לצאת מיפרש פריש מינה דה\\\"ל רקב האשה שנתערב בו רקב אחר וכבר נתפרסם שדעת רבינו לפסוק כאת\\\"ל:\",2,0],[8,374,3,6,\"טחן המת וכו'. שם:\",1,0],[8,374,3,7,\"ומה שכתב טחנו כולו והניחו עד שירקיב או שהרקיב מקצתו וכו'. שם בעיי ולא איפשיטו:\",1,0],[8,374,3,8,\"מלא חפנים ועוד וכו'. זהו פירוש מה ששנינו בפרק ב' דאהלות מלא תרווד רקב ועוד עפר קברות טמא וכת״ק וכתב רבינו שם ועפר קברות הנזכר בכאן הנמצא בקבר עפר ובו לחות המת ודמו [נראית] ואינו יודע אם הוא הרקב הנזכר שהוא מטמא באהל או הוא עפר שנתערב בו הליחה והדם והוא אמרם בתוספתא מלא תרווד רקב ועוד תבוסה שנמצאת בקבר ואין ידוע מה טיבה זהו עפר קברות עכ״ל. ונ״ל דמיירי במת שנקבר ערום בארון של שיש וכן פירש רבי' שמשון ופשוט הוא דאל״כ אין לו רקב. ואמרינן בפרק המפלת (נדה דף כ״ז) שהטעם לפי שא״א למלא תרווד ועוד עפר קברות שאין בו מלא תרווד רקב ודברי רבינו מגומגמים שכתב שאינו יודע אם הוא רקב וסיים שהרי יש במלא חפנים ועוד מלא חפנים רקב והלא עיקר הספק אם הוא רקב אם לאו ומי מוציאנו מידי ספק זה ואפשר שמאחר שאנו רואים שנקבר זה ערום בארון של שיש מחזקינן ליה ברקב ואם תאמר אכתי ניחוש שמא דבר אחר מעורב בו הרי יש במלא חפנים ועוד מלא חפנים רקב ואיני יודע מנין לנו שא״א למלא תרווד ועוד וכו' שאין בו מלא תרווד רקב וצריך עיון, ומ״מ ביאור דברי רבינו שאם הוא עפר שנתלכלך בנצל המת ודמו אינו מטמא כלל שאין כאן כזית נצל ולפיכך מטילין אותו לחומרו שאם היה הדין שעפר שנתלכלך בנצל המת ודמו מטמא נמצא שמה שאנו אומרים שהוא רקב היה להקל שלא יטמא במגע:\",1,0],[8,374,3,9,\"המת שנשרף וכו'. בפרק המפלת.\",1,0],[8,374,3,9,\"ומה שכתב וכן שפיר מרוקם וכו'. שם ופסק כריש לקיש משום דר\\\"י דפליג עליה אוקימנא כר\\\"א דלית הלכתא כוותיה:\",2,0],[8,374,3,10,\"בשר המת שנפרך וכו'. בר״פ דם הנדה (נדה דף נ״ה) אמרינן דלר״י דוקא יבש כעצם טמא אבל איפריך איפרוכי טהור ולר״ל איפריך איפרוכי נמי טמא ואמרינן בגמרא דהיכא דאיקמח והוי עפרא לר״ל נמי טהור ומדברי רבינו שכתב ונעשה קמח נראה שהוא פוסק כר״ל והוא תימה היאך פוסק כר״ל במקום ר״י ועוד שבריש פ״ב כתב דיבש כחרס מטמא משמע דוקא כחרס שאינו עשוי ליפרך אבל אם יבש יותר מחרס הוא עשוי ליפרך וטהור אע״פ שלא נפרך והיאך פסק כאן בהיפך. וצ״ל שמ״ש כאן שנפרך ונעשה קמח לא שנפרך ממש קאמר אלא היינו לומר שהוא יבש כל כך עד שאילו יפרך יעשה כקמח טהור וזהו פירוש דאיפריך איפרוכי שאמר בגמרא שהוא טהור לר״י וכל שלא הגיע יבשותו לכך היינו יבש כחרש דטמא גם לר״י:\",1,0],[8,374,3,10,\"וכן אפר השרופים טהור וכן התולעים וכו'. בפ\\\"ב דאהלות וכחכמים:\",2,0],[8,374,3,11,\"עור האדם כבשרו. כך הוא הגירסא בדברי רבינו והוא משנה פרק העור והרוטב (חולין דף קכ״ב).\",1,0],[8,374,3,11,\"ומ\\\"ש ואם עבדו כל צרכו או שהלך בו כדי עבודה וכו'. משנה וגמרא שם וכלישנא בתרא דעולא:\",2,0],[8,374,3,12,\"עור הבא כנגד פניו של אדם וכו'. פ\\\"ק דבכורות (דף ז:):\",1,0],[8,374,3,13,\"כל שבמת טמא וכו' עד נטמא כל אשר בבית. בפרק ג' דאהלות ואיתיה בפרק דם הנדה (דף נ\\\"א).\",1,0],[8,374,3,13,\"ומ\\\"ש הואיל וגזען מחליף. טעם זה אמרו בגמרא לשיער וצפורן אבל לשינים נתנו טעם שלא נבראו עמו ורבינו קיצר כיון דלא נפקא לן מידי.\",2,0],[8,374,3,13,\"ומ\\\"ש וכן הנוגע בשערו וכו'. בסיפרי פרשת חקת והוא נלמד ממה שנתבאר בסמוך:\",3,0],[8,374,3,13,\"שערו העומד להגזז וכו'. בפרק כהן גדול (דף נ\\\"ח) בעיא דלא איפשיטא:\",4,0],[8,374,3,13,\"כל משקה היוצא מן המתים טהור חוץ מדמו וכו' עד לא גזרו על משקיו. בפרק כיסוי הדם (דף פ\\\"ז ופ\\\"ח ע\\\"ב) ואיתיה בתוספתא פ\\\"ד דאהלות:\",5,0],[8,374,3,14,\"כבד שנימוחה וכו'. פירקא בתרא דבכורות עלה נ\\\"ה:\",1,0],[8,374,3,14,\"דם קטן שיצא כולו וכו'. פ\\\"ב דאהלות וכחכמים:\",2,0],[8,374,3,15,\"ואלו אם חסרו כל שהוא טהורים וכו'. פ\\\"ב דאהלות:\",1,0],[8,374,4,1,\"רביעית דם הבאה משני מתים טהורה וכו' עד כשאר כל העצמות. פרק ב' דאהלות וכחכמים:\",1,0],[8,374,4,2,\"אבר מן החי משני אנשים טהור. גם זה שם וכחכמים.\",1,0],[8,374,4,2,\"ומ\\\"ש ואפילו מאיש אחד אם נחלק לשנים טהור. ג\\\"ז שם וכת\\\"ק:\",2,0],[8,374,4,3,\"כזית בשר משני מתים וכו'. תוספתא פ\\\"ד דאהלות. וכתב רבינו ומלא חפנים רקב משני מתים שכל אחד מהן יש לו רקב כלומר שנקבר כל אחד בפני עצמו דאילו נקברו יחד כבר נתבאר שנעשים גלגילון זה לזה והכי אוקימנא לה בגמרא בפרק כה\\\"ג (דף נ\\\"א):\",1,0],[8,374,4,3,\"וכן כחצי זית בשר וכחצי זית נצל מצטרפין זה עם זה ושאר כל הטומאות שבמת אין מצטרפין זה עם זה מפני שלא שוו בשיעוריהן. כך היא הנוסחא הנכונה בדברי רבינו והיא תוספתא פ\\\"ג דאהלות:\",2,0],[8,374,4,4,\"עצם כשעורה שנחלק לשנים וכו'. בפרק ב' דאהלות עצם כשעורה שנחלק לשנים ר\\\"ע מטמא ור\\\"י בן נורי מטהר ופסק כר\\\"ע ומשמע לרבינו דע\\\"כ לא מטמא אלא במשא אבל במגע מודה ר\\\"ע והוא נלמד ממ\\\"ש לקמן גבי כזית מן המת שחתכו לחלקים:\",1,0],[8,374,4,4,\"וכן רובע עצמות המת שנדקדקו וכו'. בפ\\\"ב דאהלות וכחכמים:\",2,0],[8,374,4,5,\"כזית מן המת שחתכו לחלקים וכו'. נראה שזהו מה ששנינו בתוספתא פ\\\"ד דאהלות חלב שהיה מפורד (וחתכו) [והתיכו] טהור שאין חיבורי אדם חיבור:\",1,0],[8,374,4,6,\"כזית חלב שלם שהתיכו וכו' עד טהור. תוספתא פ\\\"ד דאהלות ומייתי לה בפרק כה\\\"ג (דף נ' ע\\\"ב):\",1,0],[8,374,4,7,\"שדרה שנגררו ממנה רוב חוליות שלה וכו'. בפרק כה\\\"ג (דף נ\\\"ב שם) והיא פ\\\"ב דאהלות:\",1,0],[8,374,4,8,\"כל המטמאין באהל שנחלקו וכו'. ריש פרק ג' דאהלות וכחכמים ואיתא פרק העור והרוטב (חולין דף קכ\\\"ד ע\\\"ב) וריש פרק ג' דעדיות (משנה א'):\",1,0],[8,374,4,8,\"כתב הראב\\\"ד כל המטמאין באהל וכו' האהל מצרפן א\\\"א אף על פי שאין שם צירוף אהל עכ\\\"ל. פי' שאם היה באויר ונגע בחצי זית בידו אחת ובחצי זית בידו אחרת או האהיל על כחצי זית וכחצי זית האהיל עליו טמא אף על פי שאין שם צירוף אהל ורבינו בסוף פרק זה כתבם אלא דהשתא כתב כלישנא דמתניתין כל המטמאין באהל שנחלקו והכניסן לתוך הבית ולאפוקי מרבי דוסא בן הרכינס דמטהר בהא:\",2,0],[8,374,4,9,\"עצם שיש עליו כזית בשר וכו' עד שאין חיבורי אדם חיבור. שם (דף מ\\\"ח ע\\\"ב):\",1,0],[8,374,4,11,\"מלא חפנים רקב וכו' עד הבית טהור להבא. גם זה שם וכתנא קמא ואיתיה בפרק המפלת (נדה דף כ\\\"ז ע\\\"ב):\",1,0],[8,374,4,11,\"ומה שכתב וכל שהיה בו בעת שנבלעה וכו'. נדה פרק האשה (דף ס\\\"ב ע\\\"ב):\",2,0],[8,374,4,12,\"כזית מן המת שאבד בתוך הבית וכו'. תוספתא פרק רביעי דאהלות וכתב הר\\\"י קורקוס ז\\\"ל ונראה הטעם דזית בשר מצוי שיאכלו אותו חולדה או חתול ולכך תולין במידי דשכיח טובא כי האי אבל נמצא אין אומרים אחר הוא זה אלא כאן נמצא וכאן היה עכ\\\"ל:\",1,0],[8,374,4,13,\"רביעית דם שנשפך באויר וכו' עד שכל הבלוע שאינו יכול לצאת טהור. משנה בפ\\\"ג דאהלות (משנה ג') וכתב הרא\\\"ש נשפך על האסקופה והיא קטפרס בין מה שיש מן האסקופה תחת תקרת הבית בין מה שיש ממנה לחוץ כולה מקום מדרון והדם נשפך על כולה נמצא מקצתו תחת האהל ומקצתו חוץ לאהל הבית טהור דאין קטפרס חיבור אבל אם היה הדם מונח בגומא ומקצתו מבפנים הבית טמא:\",1,0],[8,374,4,13,\"כתב הראב\\\"ד נשפך על האסקופה וכו' א\\\"א זו המשנה קשה עלי וכו'. ואני אומר שמה שפירש במשנה נכון הוא אך מה שהקשה על התוספתא יש לתמוה דהא מסיים בה חזרו לומר קטפרס בין מבפנים בין מבחוץ הבית טהור וצריך לומר דטעמא דמשנה ראשונה אתא לפרושי:\",2,0],[8,374,4,13,\"כיצד משערין אותה וכו'. תוספתא פרק ד' דאהלות ואיתא בנדה פרק האשה:\",3,0],[8,374,4,14,\"המשא והמגע והאהל ג' שמות הם וכו' כיצד הנוגע בכשני חצאי זיתים וכו' עד סוף הפרק. ברפ״ג דאהלות (משנה א') וכחכמים ואיתא בפרק העור והרוטב (חולין דף קכ״ד ע״ב) ויש חסרון בספרי רבינו והילך הגירסא הנכונה כיצד הנוגע בכשני חצאי זיתים או שנשא שני חצאי זיתים בבת אחת או שהאהיל על כשני חצאי זיתים או שהאהיל על כחצי זית וכחצי זית [אחר] מאהיל עליו:\",1,0],[8,374,5,1,\"כל המתטמאים מחמת המת וכו'. בריש אהלות לענין מגע ויליף לה בסיפרי מקראי:\",1,0],[8,374,5,2,\"אבל אדם שנגע באדם שנטמא במת וכו' וכאילו נגע זה השני במת עצמו. בפרק שלשה מינין (נזיר דף מ״א ע״ב) אמרינן וטומאת חיבורין דאורייתא הא [אמר רב יצחק בר יוסף] א״ר ינאי לא אמרו טומאה בחיבורין אלא לתרומה וקדשים אבל לנזיר ועושה פסח לא ואי אמרת דאורייתא מאי שנא כאן בחיבורי אדם באדם כאן בחיבורי אדם במת ופירש״י כאן כלומר מי דמי ההוא בחיבורי אדם באדם שזה נוגע במת והוא בחבירו ומש״ה לא חשיבא ליה טומאה בחיבורין לענין נזיר ועושה פסח אבל קשה דבפ״ב דע״ז (דף ל״ז ע״ב) אמרו דהא דמדאורייתא דיקרב בדיקרב אינו טמא אלא טומאת ערב ה״מ שלא בחיבורין אבל בחיבורין טמא טומאת שבעה דכתיב הנוגע במת לכל נפש אדם יטמא שבעת ימים וכתיב כל אשר יגע בו הטמא יטמא והנפש הנוגעת תטמא עד הערב הא כיצד כאן בחיבורין כאן שלא בחיבורין ופירש״י בחיבורים בשעה שהיה נוגע במת בא חבירו ונגע בו שלא בחיבורין לאחר שפירש מן המת בא חבירו ונגע בו. כל אשר יגע בו הטמא יטמא משמע שבעת ימים כסתם טומאת המת. ולפיכך יש לתמוה על רבינו שכתב דאפילו בחיבורים אינו טמא אלא טומאת ערב מדאורייתא וכתב הר״י קורקוס ז״ל שטעם רבינו משום דבתר הכי איתא בגמרא אמר רבא לא אמינא לכו לא תתלו בוקי סריקי בר״נ וכו' ומאחר שאמר רבא כן ממילא נתבטל כל מה שאמרו תחלה משמיה דר״נ וההיא דרשא דדריש התם מדכתיב הנוגע במת וגו' יטמא שבעת ימים וכתיב וכל אשר יגע בו הטמא יטמא דמשמע ליה יטמא שבעת ימים כסתם טומאת מת ליתא אלא יטמא עד הערב קאמר ע״כ. אבל קשה לי דבס״פ כיצד הרגל (דף כ״ה ע״ב) יליף רבא מקרא דכל טומאות שאתם מטמאים במת לא יהיו פחותים מז'. וי״ל דשאני הכא דבחד קרא אמר יטמא שבעת ימים ובאידך לא אמר אלא יטמא משמע דלאו שבעת ימים קאמר:\",1,0],[8,374,5,2,\"במה דברים אמורים לענין תרומה וקדשים. נתבאר בסמוך:\",2,0],[8,374,5,3,\"כלים שנטמאו במת וכו'. פרק קמא דחולין (דף ג') ופרק כה\\\"ג (דף נ\\\"ד ע\\\"ב) ובפ\\\"ק דפסחים (דף י\\\"ד) הכא בנר של מתכת שנטמא בטמא מת עסקינן דרחמנא אמר בחלל חרב חרב הרי הוא כחלל וה\\\"ל אב הטומאה וסובר רבינו דלאו דוקא כלי מתכות אלא ה\\\"ה לשאר כלים וכדעת ר\\\"י שכתב ר\\\"ש בפ\\\"ק דאהלות והרמב\\\"ן בפ\\\"ב דבתרא וסמ\\\"ג ולא כר\\\"ת ורש\\\"י שכתבו דלא אמרו אלא בכלי מתכות בלבד ודעת רבינו שהכלי נעשה כמת אפי' לא נטמא אלא באהל והיינו לענין אם נגע באחרים אבל אם האהיל עליהם לא וכן דעת הרמב\\\"ן בפרק הנזכר ובפי' התורה על פסוק וכל אשר יגע על פני השדה ולקמן בסמוך אכתוב דמתני' היא:\",1,0],[8,374,5,3,\"וכתב הראב\\\"ד וה\\\"ה לשאר כלים וכו'. א\\\"א אנו אין לנו אלא בחרב וכו'. הדבר מבואר שרבינו והראב\\\"ד פליגי בפלוגתא דר\\\"י ורבינו תם:\",2,0],[8,374,5,3,\"הרי הוא אומר כל הורג נפש וכו'. בסיפרי פרשת חוקת:\",3,0],[8,374,5,4,\"נמצאת אומר אדם שנגע במת וכו' עד והרביעי בין אדם בין כלים טמא טומאת ערב. בריש אהלות:\",1,0],[8,374,5,5,\"בד\\\"א לענין תרומה וקדשים וכו'. ירושלמי פרק כה\\\"ג וכר\\\"י והביאו הר\\\"ש פ\\\"ק דאהלות (משנה ב') והרמב\\\"ן בפרק לא יחפור:\",1,0],[8,374,5,5,\"ועל מ\\\"ש רבינו שהדברים האלו אע\\\"פ שהם דברי קבלה אינם דין תורה שהרי לא נתפרשו בתורה. כתב הראב\\\"ד א\\\"א ראיתי זה האיש וכו'. ול\\\"נ דרבינו לטעמיה אזיל שכתב בס' המצות שלו שכל דבר שאינו מפורש בתורה אלא שהוא נדרש מן המקראות נקרא דברי סופרים כלומר שצריך שידרשוהו סופרים מהמקראות אף על פי שדינן דין תורה והכא ה\\\"ק שהדברים האלו אף על פי שהם דברי קבלה ומשפטן דין תורה מאחר שלא נתפרשו בתורה בהדיא אלא אתו מדרשא כדאיתא בספרי יש לחלק בינם למה שהוא מפורש בתורה ולומר שאין חייבין עליהם על טומאת מקדש וקדשיו.\",2,0],[8,374,5,5,\"ומה שכתב הילכך אפילו אדם באדם שהוא מפורש בתורה אינו חייב קרבן על ביאת המקדש וכו'. בפרק כהן גדול בירושלמי פלוגתא דר\\\"י ור' אבין בר חייא ופסק הראב\\\"ד כר' אבין בר חייא ורבינו פסק כר\\\"י. וא\\\"ת מאחר שאדם הנוגע באדם שנגע במת אין הנזיר מגלח עליו היאך חייבים עליו על ביאת המקדש והא תנן בפרק הנזכר שכל טומאה מן המת שאין הנזיר מגלח עליה אין חייבין על ביאת המקדש. כבר הקשו כן שם בירושלמי לר\\\"י ותירצו לא נצרכה אלא לטומאות הפורשות מן המת כלומר שאין אותו הכלל אמור אלא לענין טומאות הפורשות מן המת בלבד לא לענין אדם שנגע באדם שנגע במת:\",3,0],[8,374,5,7,\"כלי חרס שנגע במת וכו' ואינו מטמא אדם ולא כלי חרס אחר וכו' שאין כלי חרס נעשה אב הטומאה לעולם וכו' עד ולא שאר כלים ובגדים. בתוספתא בפרק י\\\"ז דאהלות ובעירובין (דף ק\\\"ד ע\\\"ב) ופירש רש\\\"י הטעם דלמדרס זב לא חזי ובטמא מת כתיב וחטאו וכלי חרס לאו בר חיטוי הוא דכתיב ואותו תשבורו ובפרק ח' דכלים (משנה ד') תנן קדירה שהיא נתונה בתנור וכו' שאין כלי חרס מטמא כלים וכתב שם רבינו דבתורת כהנים מייתי לה מקרא ובסוף פירקא קמא דפסחים (דף כ') יכול יהיו כל הכלים מיטמאים מאויר כלי חרס תלמוד לומר וכל אשר בתוכו יטמא וסמיך ליה מכל האוכל [אשר יאכל] אוכל מיטמא מאויר כלי חרס ואין כל הכלים מיטמאין מאויר כלי חרס וכתב רש\\\"י ואשמעינן קרא דאוכלים ומשקים הוא דמקבלי טומאה מולד הטומאה אבל כלי לא ומהאי פירוקא נפקא לן בכל דוכתא הא דקיימא לן דאין כלי ראשון מטמא כלי וכו'. ואדם נמי שאינו אב הטומאה כגון נוגע בנבילה או בשרץ אינו מטמא כלי כו'. אלמא ולד הטומאה אינו מטמא כלי וכן אדם לא מצינו לו טומאה בכל התורה אלא מאב הטומאה וכן מבואר בריש בבא קמא כמו שאכתוב בסמוך:\",1,0],[8,374,5,7,\"זה כלל גדול בטומאות וכו'. בריש בבא קמא תנן אבות הטומאות השרץ וכו' תולדותיהן לאו כיוצא בהן דאילו אב מטמא אדם וכלים ואילו תולדה אוכלים ומשקים מטמא אדם וכלים אינו מטמא:\",2,0],[8,374,5,7,\"וכל המטמא אדם וכלים בנגיעה וכו'. נתבאר בסמוך:\",3,0],[8,374,5,8,\"כל הנוגע באב הוא הנקרא ראשון. פסחים עלה י\\\"ד:\",1,0],[8,374,5,9,\"כל המתטמא מחמת המת טומאת שבעה וכו' כדי לטמא אדם וכלים וכו'. בריש כלים:\",1,0],[8,374,5,10,\"כל המתטמא מחמת המת טומאת ערב וכו'. פשוט הוא.\",1,0],[8,374,5,10,\"ומ\\\"ש אפשר שיהיה הרביעי מן המת וכו' כמו שביארנו לענין תרומה וקדשים. לעיל בפרק זה:\",2,0],[8,374,5,11,\"אדם או כלים שנטמאו במגע ארץ העכו\\\"ם וכו': כתב הראב\\\"ד אדם או כלים שנטמאו וכו' וגולל ודופק וכו' א\\\"א סמי מכאן גולל ודופק כמ\\\"ש למעלה עכ\\\"ל. כלומר שבפ' ב' השיג על רבינו שכתב שגולל ודופק הם מד\\\"ס וכבר כתבתי שם טעם רבינו:\",1,0],[8,374,5,12,\"האהל עצמו המאהיל על טומאה וכו'. בסיפרי ובפ\\\"ק דאהלות גבי הא דאמר ר\\\"ע יש לי חמישי:\",1,0],[8,374,5,12,\"בד\\\"א בשהיה האהל בגד או שק או כלי עץ. כלומר פשתן דוקא שנקרא עץ אבל שאר עצים לא כמו שביאר בסמוך.\",2,0],[8,374,5,12,\"ומ״ש או עור אחד עור בהמה וחיה בין המותרים לאכילה בין האסורים לאכילה שנאמר ויפרוש את האהל על המשכן וכו'. בפרק במה מדליקין (שבת דף כ״ח):\",3,0],[8,374,5,12,\"ומ\\\"ש אבל אם היה האהל נסרים של עץ וכו'. שם והכי משמע ברפ\\\"ז דכלים וכמ\\\"ש רבינו שם:\",4,0],[8,374,5,12,\"וכ\\\"מ שנאמר הבית טמא וכו'. נלמד ממ\\\"ש בסמוך:\",5,0],[8,374,5,12,\"כתב הראב\\\"ד אבל אם היה האהל וכו' עד או של מתכת ה\\\"ז טהור א\\\"א והוא שנעשה אהלים קבועים וכו' עד לא ביריעה וסדין של פשתן וכו' כך כתבו התוס' בפרק במה מדליקין:\",6,0],[8,374,5,12,\"ואין לך יוצא מן העץ וכו'. משנה פרק במה מדליקין (שבת דף כ״ז ע״ב):\",7,0],[8,374,5,13,\"בגדים הנוגעים במת אע\\\"פ שהן כמת וכו' אינם כמת לטמא באהל. כבר כתבתי שכן דעת הרמב\\\"ן ומתניתין היא כדבסמוך. אבל במה שכתב רבינו שאינו כמת לטמא במשא כתב שצריך עיון ותמהני עליו שנראה שדברי רבינו מתניתין היא בריש כלים אבות הטומאות השרץ וכו' וטמא מת וכו' הרי אלו מטמאים אדם וכלים במגע וכו' ואינם מטמאים במשא וכתב שם רבינו לפי שבכל אותם המנויים בא בהם הנוגע ולא הנושא ומשמע דהוא הדין שאינו מטמא באהל וכל שכן הוא וכן דרשו בסיפרי והנוגע בכל טמא נפש אין טמא נפש מטמא אלא בנוגע.\",1,0],[8,374,5,13,\"ומ\\\"ש וכל המאהיל עליהם או שהאהילו וכו'. בספט\\\"ו דאהלות מאהיל על המת ומאהיל על הכלים הנוגע במת ומאהיל על הכלים טהורים:\",2,0],[8,374,5,14,\"המת אינו מטמא משכב ומושב מתחתיו וכו'. בפרק ששי דעדיות (משנה ב') ופרק ד' דזבים חומר בזב מבמת וכו' שהזב עושה משכב ומושב מתחתיו לטמא אדם ולטמא בגדים ועל גבי מדף לטמא אוכלים ומשקים מה שאין המת מטמא וכתב שם רבינו טמא מדף פירוש אילו השלכנו על הזב מאה או אלף כיסויין זה על גבי זה הכיסוי העליון טמא מדף ומטמא אוכלים ומשקין ואין חילוק בין הבגד הדבוק בגוף מלמעלה ובין הבגד העליון אשר כנגד הרקיע הכל טמא וכל הכלים אשר על הזב כולם ראשון לטומאה וביאור מדף חסר אות והוא כמו מנדף כלומר טומאתו נודפת למרחוק הרבה שאפילו היה בין האוכלים חציצה רבה יטמאה אפילו אחר אלף בגדים כאילו יעבור ריחו ויגיע עליהם ויטמאם כמו ריחו נודף עכ\\\"ל.\",1,0],[8,374,5,14,\"ומה שכתב במה דברים אמורים שכל הבגדים או הכלים שתחתיו או שלמעלה ממנו טהורים וכו' או שהיה מבדיל בינו ובין הכלים אבן. פרק בתרא דנדה (דף ס\\\"ט) ועיין בפירוש המשנה פרק חמישי דזבים:\",2,0],[8,374,6,1,\"עצמות הדג ועורו וכו'. בפרק י\\\"ז דכלים כל שבים טהור ובתורת כהנים ממעט שאם עשה מהם כלים אינם מקבלים טומאה ויליף לה מדכתב או בגד או עור מה בגד מדבר הגדל ביבשה אף עור מדבר הגדל ביבשה.\",1,0],[8,374,6,1,\"ומה שכתב וכן ירוקה שעל פני המים. למד כן ממה ששנינו כל שבים טהור:\",2,0],[8,374,6,2,\"כלי גללים וכלי אבנים וכלי אדמה אינם מקבלים טומאה. הכי משמע ריש פרק י' דכלים ובפרק במה אשה (דף ס״ט ע״ב) ובמנחות פרק רבי ישמעאל (עבודה זרה דף נ״ח):\",1,0],[8,374,6,2,\"וכן כלי עץ העשוי לנחת וכו'. פרק ט\\\"ו דכלים ומייתי לה בשילהי חגיגה (דף כ\\\"ו:) ויהיב טעמא משום דדומיא דשק בעינן שהוא מיטלטל מלא וריקן:\",2,0],[8,374,6,3,\"כלי עץ פשוטיהם טהורים ומקבליהן טמאים וכו'. כלים רפ\\\"ב ורפט\\\"ו:\",1,0],[8,374,6,3,\"כלי חרס פשוטיהם טהורים וכו'. רפ\\\"ב דכלים.\",2,0],[8,374,6,3,\"ומ\\\"ש ואינם טמאים אלא מאוירן. שם וספ\\\"ק דחולין (דף כ\\\"ה).\",3,0],[8,374,6,3,\"ומ\\\"ש או בהיסט הזב. בפ\\\"ק דנדה (דף ו') ובפרק הניזקין ובתורת כהנים פ' מצורע:\",4,0],[8,374,6,3,\"היה כלי חרס עם המת באהל וכו' ואם היה מוקף צמיד פתיל וכו'. מבואר בתורה ואיתיה בפ\\\"י דכלים.\",5,0],[8,374,6,3,\"ומ\\\"ש ובהיסט הזב וכו'. בתוספתא דכלים פרק ששי ותוספתא דזבים פ\\\"ג ותורת כהנים:\",6,0],[8,374,6,4,\"העושה גולל מדבר שאינו מקבל טומאה וכו'. נלמד מדין בהמה ומדין חבית דבסמוך.\",1,0],[8,374,6,4,\"ומ\\\"ש וכן בהמה. בפט\\\"ו דאהלות וכת\\\"ק.\",2,0],[8,374,6,4,\"ומ\\\"ש שכפתה. משום דאל\\\"כ הרי היא הולכת לכאן ולכאן ואין כאן גולל:\",3,0],[8,374,6,4,\"וכן חבית שהיא מליאה משקין מוקפת צמיד פתיל וכו' עד טהורים. בספט\\\"ו דאהלות:\",4,0],[8,374,6,5,\"קורה שעשאה גולל לקבר וכו' עד כולה גולל. שם קורה שעשאה גולל לקבר בין עומדת בין מוטה על צדה אין טמא אלא כנגד פתח עשה ראשה גולל לקבר אין טמא אלא עד ד' טפחים ובזמן שהוא עתיד לגוד:\",1,0],[8,374,6,5,\"וכתב הראב\\\"ד על דברי רבינו והרי היא עומדת על הקבר כמו אילן א\\\"א א\\\"כ היינו עומדת וכו'. ורבינו מפרש העומדת ומוטה על צדה תרווייהו כשהקורה מוטלת לאורך הקבר אלא דעומדת היינו שהטילה על הקבר לרחבה וקתני שאם היתה ארוכה או רחבה יותר מהקבר אין טמא אלא כנגד הקבר דוקא והשאר טהור לפי שאינו צריך לגולל אבל כשהעמידה על הקבר כמו אילן אע\\\"פ שמתוך שכולה עומדת על פתח הקבר היה ראוי לטמאה כולה אפילו כשעתיד לקוץ מתוך שאינו צורך לגולל ממנה אלא קצתה לא טימאו ממנה אלא עד ד' טפחים והוא שעתיד לקוץ:\",2,0],[8,374,6,6,\"שתי אבנים גדולות וכו'. תוספתא ספ\\\"ג דאהלות. כתב הר\\\"י קורקוס ז\\\"ל נראה דמאהיל על שתיהן דקתני הכוונה על כל אחת משתיהן דכיון שגדולות הן כל אחת חשובה גולל בהיות חבירתה שם מונעת הטומאה מלצאת אבל כל שניטלה האחת טהרה חבירתה ואין שם גולל עליה כיון שיש לטומאה דרך לצאת והיינו למאהיל שלא כנגד הקבר אלא כנגד כותל הקבר דכנגד הקבר תיפוק ליה משום קבר דמטמא כל מאהיל עליו ולכך אמרו המאהיל על גבי שתיהן טמא כלומר אפילו על אותה שאינה כנגד הקבר כי השתים גולל הן חשובות ולפי זה אם היו פחות מד' טפחים שאין טמא רק הנוגע על אותה שכנגד הקבר והאחרת בטלה ואי מיירי בששתיהן קצתן כנגד הקבר אפשר דנקט ארבעה טפחים משום סיפא דניטלה אחת מהן שאם היו פחות מד' אפילו ניטלה אחת טמאה הנשארת או אפשר דאורחא דמלתא נקט כי לעשות שתי אבנים גולל מסתמא גדולות ואין נראה לומר שאם היה פחות מד' כל אחת לא נחשבה גולל דאבן אחת בעינן א\\\"נ קטנות בנויות דהא מנא לן לומר כן עכ\\\"ל:\",1,0],[8,374,6,7,\"גל של צרורות וכו'. תוספתא דאהלות פרק ט\\\"ו וכחכמים וכתב רבינו שמשון שעשה כמין כור ברזל בגל ונמצאת כיפת הגל גולל עד ד' טפחים בעובי הגולל סדר הפנימי היינו צרורות הנתונות על פתחו של קבר עכ\\\"ל. וכתב הר\\\"י קורקוס ז\\\"ל ורבינו כתב לשון התוספתא אלא שהוסיף אבל הנוגע בשאר אבנים טהור ובחלוקה שבסמוך הזכיר מאהיל ונראה שכוונתו בזה הוא מפני שזה הגל הוא סדר על סדר וכשאמרו סדר הפנימי היינו התחתון הסמוך לקבר אבל אשר עליו הכל טהור ור\\\"י סובר שכל גובה ארבעה טפחים טמא וכמו נוגע דקורה עומדת שהוזכר וכיון שכן קשה שהרי כל המאהיל על התחתון על העליון הוא מאהיל וא\\\"א שיאהיל על התחתון לבדו (דכך כתב) דלענין נגיעה הוא דשייך לומר כן וכן גבי קורה עומדת כמו אילן כתב נוגע וכאשר תדקדק כן שבכ\\\"מ שתופס נוגע לא שייך לומר האהיל עכ\\\"ל:\",1,0],[8,374,6,8,\"ארון שהוא חקוק בסלע וכו' עד ומטמא מכל סביביו. תוספתא פ\\\"י דאהלות ארון שהוא חקוק בסלע ומכוסה הנוגע בה מכ\\\"מ טהור ואינו טמא אלא כנגד כיסויה בלבד למה זה דומה לבור גדול מלא מתים ואבן גדולה נתונה על פיו שאינו טמא אלא כנגד חללו בלבד היתה בנויה בכותלה של נפש אם היתה נראית כל שהיא לתוך הנפש הכל טמא ואם לאו אינו טמא אלא כנגד כיסויה בלבד בנה הנפש על גבה הרי היא כקבר סתום ומטמאה מכל סביבותיה ופירש רבינו שמשון בפ\\\"ט חקוק בסלע צור שמששת ימי בראשית שאינו מיטלטל. בכותלה של נפש שבנו אצלה נפש וכותל הנפש בנוי על גבה. אם היתה נראית שנראה כל שהוא הארון בתוך הנפש הנכנס לתוכה של נפש טמא ואם לאו שנשאר ע\\\"פ הארון לחוץ וצד ארון של צור נכנס בבנין אינו טמא אלא כנגד כיסויה של ארון בלבד ותוך הנפש טהור בנה הנפש על גבה על הארון עצמה שכולה כנפש הרי היא הנפש כולה כקבר סתום עכ\\\"ל. ואיני יודע למה השמיט רבינו הבבא האמצעית:\",1,0],[8,374,6,8,\"היתה הארון החקוקה בסלע רחבה מלמעלה וכו' עד הנוגע בה מ\\\"מ טמא. פ\\\"ט דאהלות.\",2,0],[8,374,6,8,\"ומ\\\"ש היתה שוה וכו'. שם וכרב יהושע:\",3,0],[8,374,6,8,\"וכתב הראב\\\"ד היתה הארון החקוקה בסלע רחבה מלמטה וכו' א\\\"א לא נראה כן מן התוספתא שהיא כחקוקה בסלע וכו'. ולדעת רבינו י\\\"ל שהוא סובר דאדרבה רישא דתוספתא גילתה דמתניתין מיירי בחקוקה וכ\\\"כ בפירוש המשנה שמהתוספתא למד לומר דמתניתין מיירי בחקוקה בסלע וכ\\\"כ ג\\\"כ הר\\\"ש והרא\\\"ש ועוד שאם מיירי בבנין קשה מה שהקשה הראב\\\"ד לעצמו שאין ניצל מתורת גולל ודופק. ומה שהקשה הראב\\\"ד לרבינו שדבריו סותרים את דבריו י\\\"ל דברישא שכתב הנוגע בסלע מ\\\"מ טהור שהוא חקוק מלמעלה והכניס בו המת וכסהו למעלה בגולל ואין לו דין קבר סתום לטמא סביביו כיון שאין שם בנין הילכך אינו מטמא אלא א\\\"כ נגע בגולל ובסיפא מיירי שאין הארון פתוח מלמעלה אלא מצדו לארכו והכניס המת דרך שם והוא סתום מעצמו מלמעלה ומלמטה ובזה שייך לחלק בין רחבה מלמטה וצרה מלמעלה רחבה מלמעלה וצרה מלמטה לכשהיא שוה למטה ולמעלה וכל זה אינו ענין לרישא שפתחו מלמעלה וזה סתום מלמעלה ולענין טעם למה חילקו בו בין רחבה מלמטה וצרה מלמעלה לרחבה מלמעלה וצרה מלמטה לכשהיא שוה י\\\"ל דלעולם מלמעלה טמא מפני שהוא כגולל וכשהיא רחבה מלמטה לא מחשיב למטה כארון וכשהיא צרה למטה מחשיב למטה כארון וכשהיא שוה מטפח ולמעלה מחשיב כארון מטפח ולמטה לא מחשיב כארון אלא כקרקע עולם לר' יהושע דהלכתא כוותיה:\",4,0],[8,374,6,8,\"ניקב ארון בסלע והכניס המת כמין נגר. שם העשוי כמין גלוסקוס הנוגע בה מ\\\"מ טהור חוץ ממקום פתיחתה ופירש רבינו גלוסקוס הוא כמין נגר וכו' אבל אשר יתאמת אצלי לפי הענין שזאת התמונה היא כמו תיבה מן הצד כאילו הוא נוקב בעצם האבן מקום יכנס ממנו המת ונועל זה השער ולזה כנגד פתיחתה טמא על דמיון מה שביארה התוספתא בבור מלא מתים לפי שזאת התמונה הוא בור על הצד הזה עכ\\\"ל:\",5,0],[8,374,6,8,\"וכתב הראב\\\"ד ניקב ארון בסלע וכו'. א\\\"א דבר זה פירוש למה ששנו במשנה וכו':\",6,0],[8,374,6,8,\"והא דתנן תו התם העשוי כמין קמטרא הנוגע בה מ\\\"מ טמא והשמיטו רבינו לפי שהוא נכלל במה שנתבאר:\",7,0],[8,374,6,9,\"מערה שהקבר בתוכה וכו'. פט\\\"ו דאהלות חצר הקבר העומד בתוכה טהור עד שיהיה בה ארבע אמות כדברי ב\\\"ש וב\\\"ה אומרים ארבעה טפחים וכתב רבינו בפירוש המשנה כבר התבאר שזה החצר מקורה ופתח המערות אשר בם הקברות פתוח אצל זה החצר והיא אשר תקרא חצר הקבר ומי שעמד בה הוא טהור לפי שאם היה בה פחות מד' על ד' הנה הוא מתקרב אל פי המערה ויטמא וכו' ואם היה זה החצר מגולה הנכנס לתוכה טהור באי זהו ענין אם לא שיגע בפתח המערה. ובתוספתא [איזה היא חצר הקבר זו הגת שהמערות פתוחות לתוכה אם יש בה כשיעור הנכנס לשם טמא בד\\\"א בזמן שאינה פתוחה לאויר אבל] בזמן שפתוחה לאויר אפילו אינו מרוחק מן השקוף אפילו כל שהוא טהור ובלבד שלא יגע בשקוף ומפרש רבינו אינה פתוחה לאויר היינו שהיא מקורה. ומ\\\"ש הראב\\\"ד אם היה בה מגולה לצד המערה וכו'. טעמו משום דאל\\\"כ הרי הטומאה יוצאת מפתח המערה לחצר ע\\\"י הקירוי וטעם רבינו נראה שהוא מפני שאין דרך טומאה זו לצאת ולפיכך כל שאינו מתקרב לפתח המערה פחות מד' טפחים טהור כל שאינו נוגע בשקוף. ומ\\\"ש לפי טעותו הגהתי. נראה שהטעם שנוסחתו בדברי רבינו היתה כמ\\\"ש בספרי הדפוס ובזמן שהחצר מקורה אם היה בה ד' טפחים על ד' טפחים והנוסחא האמיתית אם היה בה מגולה בצד המערה ד' טפחים על ד' טפחים וכן מצאתי בספרי כתיבת יד והוא כמ\\\"ש הראב\\\"ד שהגיה:\",1,0],[8,374,6,9,\"ודע דבס״פ משוח מלחמה (סוטה דף מ״ד) קאמר על ב״ה בד״א שפתחה מן הצד אבל פתחה מלמעלה ארבע אמות ולא ידעתי למה השמיטו רבינו:\",2,0],[8,374,7,1,\"בית סתום שהמת בתוכו או שהיה לו פתח ופרץ את פצימיו וכו' (עיין בפנים) כך היא הגירסא הנכונה בדברי רבינו וכך מצאתיה בספר מוגה. והדין תוספתא ספי\\\"ו דאהלות וברייתא בפ\\\"ק דבתרא (דף י\\\"ב):\",1,0],[8,374,7,1,\"וכמה יהא שיעור הפתח וכו'. פ\\\"ג דאהלות ומסיים בה להציל הטומאה על הפתחים אבל להוציא [את] הטומאה בפותח טפח:\",2,0],[8,374,7,2,\"המת בתוך הבית וכו'. בפ\\\"ז דאהלות המת בבית ובו פתחים הרבה כולם טמאים נפתח א' מהם הוא טמא וכולן טהורים חשב להוציאו באחד מהם או בחלון שהוא ארבעה על ארבעה טפחים הציל על כל הפתחים בש\\\"א והוא שחשב עד שלא ימות המת וב\\\"ה אומרים אף משמת היה סתום ונמלך לפתחו בש\\\"א כשיפתח ארבעה טפחים וב\\\"ה אומרים כשיתחיל ומודים בפותח בתחלה עד שיפתח ארבעה טפחים ופי' רבינו כאשר היו הפתחים כולם נעולים הנה יהיה הבית כולו כקבר ולזה יטמא כל מה שיגע בו וזה לשונם בית סתום מטמא כל סביביו וכאשר נפתח אחד מהפתחים או חשב להוציא המת מפתח ידוע ואע\\\"פ שלא נפתח עדיין או שהיה בכלל הפתחים פתח בנוי [וחשב להרוס הבנין ההוא ולהוציא המת ממנו והתחיל להרוס] הנה הציל על כל הפתחים כולן וכאשר היה בהם פתח נעול הנה אשר ישב תחת המשקוף היוצא על זה הפתח לא יטמא וזהו ענין היות הפתח כבר הציל מן הטומאה כמו שביארנו בפ\\\"ג וסבת זה היות הבית יוצא מדין קבר ונשאר בית ואינו מטמא כל סביביו וכו' וענין פותח בתחלה לפתוח פתח בא' הכתלים במקום שלא היה שם פתח ויחשוב להוציאו בו עכ\\\"ל. והר\\\"ש והרא\\\"ש פירשו דטעמא דכולם טמאים משום דסוף טומאה לצאת בחד מינייהו ולא ידענא בהי מינייהו הילכך חשיבי כולהו כפתוחים.\",1,0],[8,374,7,2,\"ומ\\\"ש בזמן שכולם נעולין. בתוספתא פ\\\"ח דאהלות.\",2,0],[8,374,7,2,\"ומ\\\"ש ואע\\\"פ שחשב אחר שמת המת. כב\\\"ה.\",3,0],[8,374,7,2,\"ומ\\\"ש וכן אם התחיל לחתור פתח וכו'. זהו ששנינו ומודים בפותח בתחלה עד שיפתח ד' טפחים.\",4,0],[8,374,7,2,\"ומ\\\"ש היה שם פתח סתום וכו'. ג\\\"ז כב\\\"ה:\",5,0],[8,374,7,2,\"היו בו חלונות הרבה וכו'. תוספתא פ\\\"ח דאהלות. וכתב הר\\\"י קורקוס ז\\\"ל מ\\\"ש דחלונות לא הצילו על הפתחים היינו דלא חשב כלל שמן הסתם אין דרך להוציא המת דרך חלונות שאם חשב להוציאו משם כבר נתבאר שחלון ד' מציל וכ\\\"ש אם פתח בכוונה להוציאו משם וזהו שכתב נפתחו דהיינו מאליהן ומחשבה אין כאן עכ\\\"ל. ולי נראה דמיירי בחלונות שאין בהם ארבעה מש\\\"ה לא הצילו על הפתחים וכולן טמאות וכדתנן גבי המת פתחו בארבעה טפחים להציל טומאה על הפתחים אבל להוציא את הטומאה בפותח טפח ובהכי ניחא מאי דקתני כשהן מוגפות כולן טהורות שאם היה בהן ארבעה אע\\\"פ שהן מוגפות היה להן להיות טמאות:\",6,0],[8,374,7,2,\"פתח קטן בתוך פתח גדול וכו' עד ואם הערים שניהם טמאים. תוספתא פ\\\"ח דאהלות:\",7,0],[8,374,7,2,\"וכתב הראב\\\"ד פתח קטן בתוך פתח גדול המאהיל ע\\\"ג שניהם טמא א\\\"א נ\\\"ל בצד הפתח קאמר עכ\\\"ל. וכתב עוד היו שניהם מתאימים וכו'. א\\\"א כך היא התוספתא וכו' וקמ\\\"ל אע\\\"פ ששניהם דומים לפתח א' טיהר א' את חבירו עכ\\\"ל. ונראה דוחק מה שפירש בתוך הפתח דהיינו בצד הפתח ואפשר דה\\\"ק שפתח פתח גדול ביותר בכותל ובתוך הפתח הגדול בנה וסתם קצת ממנה מלמעלה ומלמטה ומן הצד ונשאר פתח קטן בצד הפתח הגדול ושניהם מתאימים היינו שהשאיר הפתח הגדול כמות שהוא אלא שחלקו באמצע במזוזה וקתני בתרווייהו שהמאהיל על שניהם טמא ומשמע לי דהיינו לומר שאם האהיל על אי זה משניהם טמא וברישא אשמעינן דלא תימא דפתח קטן בטל לגבי פתח גדול ואם האהיל עליו לא נטמא וכן אם חשב להוציאו בקטן לא טיהר את הגדול קמ\\\"ל ובסיפא אשמעינן שאע\\\"פ שנראה שהוא פתח אחד טיהר א' את חבירו וכמ\\\"ש הראב\\\"ד ורבינו שמשון בפ\\\"ח דאהלות הביא תוספתא זו ופירש פתח קטן בתוך פתח גדול כגון אותם שערים גדולים שבשער עצמו עושים דלת או חלון קטן לפי שאין רוצים כל שעה לפתוח לו שער הגדול לכל איש הנכנס ויוצא כי אם לצורך סוסים וחמורים הטעונים משאות. מתאימין כגון פתח שיש לו שתי דלתות אחת מימין ואחת משמאל עכ\\\"ל:\",8,0],[8,374,7,3,\"בתים הפתוחים לאכסדרה וכו'. תוספתא שם בתים הפתוחים לאכסדרה והמת בא' מהם אם היה דרכו של מת לצאת בחצר בית שער כל הבתים טהורים ואם לאו בית שער טמא וכל הבתים טהורים ורבינו שמשון הביא תוספתא זו בפ\\\"ז דאהלות ופירש בתים הפתוחים לאכסדרה שיש לפני הבתים אכסדרה והאכסדרה פתוחה מכל צדדיה ויש לבתים בית שער מצד אחד. לצאת בחצר לאכסדרה חצר קרי לה שמצד האכסדרה היה דרכו לצאת ולא דרך בית שער. כל הבתים טהורים כלומר כל פתחי הבתים טהורים על המאהילים עליהם שדרך חצר יוציאו את המת ולא דרך בית שער. ואם לאו שאין דרכו של מת לצאת לחצר אלא מבית שער בית שער טמא וכל הבתים טהורים כלומר כל פתחי הבתים עכ\\\"ל. ולפ\\\"ז כי קתני בית שער כל הבתים טהורים ה\\\"ק בית שער וכל הבתים טהורים ובספרי רבינו מצאתי אם היה דרכו של מת לצאת באכסדרה הרי הבית שער טמא והבתים טהורים ולפ\\\"ז צ\\\"ל דלאכסדרה קרי בית שער וקשה לגירסא זו דכיון דקתני אם היה דרכו של מת לצאת באכסדרה ה\\\"ל למיתני ואם לאו. ומצאתי נוסחא אחרת בדברי רבינו שכתוב בה אם היה דרכו של מת לצאת בחצר הרי הבית שער והבתים טמאים ואם לאו בית שער טמא והבתים טהורים וזאת היתה נוסחת ספרי רבינו שביד הראב\\\"ד וכתב עליה א\\\"א בתוספתא טהורים וכן עיקר וכו' ולפי גירסא זו שגורס הבתים טמאים נ\\\"ל שצריך לגרוס אם היה דרכו של מת לצאת באכסדרה א\\\"נ דלאכסדרה קרי חצר כדברי רבינו שמשון וה\\\"ט משום דכיון דדרכו לצאת דרך שם אע\\\"פ שהבית שהמת שם פתחו נעול חשבינן כאילו הוציאוהו שם ולפיכך אכסדרה טמאה וכן שאר בתים הפתוחים לה טמאים אם אין דלתותיהם נעולות וטעמא משום דכיון דחשבינן כאילו המת באכסדרה הרי הטומאה נכנסת לבתים הפתוחים ע\\\"י תקרת האכסדרה שמביאה את הטומאה להם אבל אם היו נעולים אין טומאה נכנסת להם. ואם לאו כלומר אם אין דרכו של מת לצאת באכסדרה כגון שיש לבית פתח ממקום אחר והם רוצים להוציאו באותו פתח הבתים טהורים אפילו הם פתוחים והוא שיהיה פתח הבית שהמת בו נעול ואע\\\"פ כן אכסדרה טמאה לפי שהיא טפילה לבית:\",1,0],[8,374,7,3,\"החדר שלפנים מן הבית מוגף וכו'. תוספתא פ\\\"ח דאהלות:\",2,0],[8,374,7,3,\"וכתב הראב\\\"ד פי' נכנס המת לחדר וכו' והוא שיהא הפתח שבין בית לחדר מוגף שאילו היה פתוח הא ודאי שהיה טמא גם הבית החיצון. ורבינו שמשון הביא תוספתא זו בפ\\\"ד דאהלות ופי' מוגף סגור ואין יכול ליכנס ממנו לבית. לפנימי לחדר שלפנים מהבית נכנסה הטומאה דרך חלון וכו' דכיון דהדלת מוגף אין טומאה נכנסת ממנו לבית ואי משום דסופה לצאת דרך פתח לבית ולא דרך חלון כדאמרן שאין חלונות מצילים על הפתחים הכא כיון דדרך החלון באה הטומאה כדרך שנכנסה יוצאה עד כאן לשונו:\",3,0],[8,374,7,4,\"אין הקבר מטמא מכל סביביו וכו'. ברפ\\\"ו דאהלות תנן נפש אטומה הנוגע בה מן הצדדין טהור מפני שטומאה בוקעת ועולה בוקעת ויורדת אם היה מקום הטומאה טפח על טפח על רום טפח הנוגע בה מכ\\\"מ טמא מפני שהיא כקבר סתום ופירש שם רבינו נפש הוא הבנין שבונים על הקבר וכו' ואוטם הוא הדבר המקשיי אשר אין חלל בתוכו ולא פתח אמרו נפש אטומה ירצה בו שיהיה זה הבנין על עצם הטומאה ולא יהיה המת בארון עד שיהיה שם חלל טפח.\",1,0],[8,374,7,4,\"ומ״ש אפילו הגביה הבניין וכו'. ריש פ״ז דאהלות הטומאה בכותל ומקומה טפח על טפח כל העליות שעל גבה אפילו הן עשר טמאות. ומ״ש הראב״ד לחלק כשיש במקום הטומאה טפח בין כשהטומאה ממעטת החלל לכשאינה ממעטת נ״ל שטעמו מפני שהוא מפרש מה ששנינו אם היה מקום הטומאה טפח על טפח וכו' אנפש אטומה דרישא קאי לומר שגם בסיפא מיירי כלומר שאין שם טפח פנוי שהטומאה ממעטת החלל דיקא נמי דקתני אם יש במקום הטומאה טפח על טפח ולא קתני אם יש שם טפח על טפח דהוה משמע שאין הטומאה ממעטת חלל הטפח וקאמר דהנוגע בה מכ״מ טמא כלומר מלבד שהיא בוקעת ועולה וכו' כדקתני רישא הנוגע בה מכ״מ טמא ובהכי ניחא ליה מה שאמרו בפרק מי שמתו (ברכות דף י״ט) גבי הא דאמר רבי אליעזר ברבי צדוק מדלגים היינו ע״ג ארונות וכו' אהל שיש בו חלל טפח חוצץ מפני הטומאה ושאין בו חלל טפח אינו חוצץ והוא היפך מה שכתבתי בסמוך ששנינו בריש פ״ז דאהלות ובמה שחידש מדה שלישית ניחא ליה והדבר פשוט הוא שאין דעת רבינו כן כמבואר בדבריו פה ובפי' המשנה שכתבתי דכל שאין שם טפח על טפח על רום טפח פנוי טומאה רצוצה היא והנוגע מן הצדדין טהור וזהו פשט המשנה וההיא דמדלגין היינו ע״ג ארונות לא מכרעא לחדש מדה שלישית שהרי התוס' תירצוה בלא חידוש מדה שלישית ורבינו בפרק י״ב כתב דארונות של עץ שמניחים בהם את המת אינם כקבר אבל אם יש בין כיסוי הארון והמת גובה טפח חוצץ והעומד על גבי הארון טהור מן התורה וכו'. ומ״ש עוד הראב״ד וזו הרצוצה אם היא בכותל שבין שני בתים וכו' מבואר במשנה פ״ו דאהלות. ומ״ש ואם יש שם טפח פנוי חלל אינו מטמא באהל רבינו חולק על זה ומההיא דארונות אין ראיה לפי מ״ש רבינו בפרק י״ב:\",2,0],[8,374,7,5,\"זה כלל גדול בטומאת מת וכו' כיצד כרי של תבואה וכו'. בפרק ט\\\"ו דאהלות ובפ\\\"ז:\",1,0],[8,374,7,6,\"בית שמלאו עפר וכו'. גם זה שם:\",1,0],[8,374,7,7,\"טומאה שהיא רצוצה בכותל וכו'. פ\\\"ז דאהלות בסוף המשנה שכתבתי בסמוך סמך לה סוכות טמאות ור\\\"י מטהר וידוע דהלכה כת\\\"ק:\",1,0],[8,374,7,7,\"וכתב הראב\\\"ד א\\\"א בחיי ראשי אין דרך המשנה כדבריו וכו'. וי\\\"ל דאי מהא לא איריא שרבינו מפרש דסמך לה סוכות טמאה ארישא קאי דקתני נפש אטומה הנוגע בה מן הצדדין טהור ומשום דמסיים בה ר\\\"י מטהר קתני לה דאילו בהיה בה טפח על טפח לא פליג ר\\\"י. ומ\\\"ש ויסודי הדברים הללו בתוספתא דאהלות פ\\\"ג הוא מדקתני התם העושה סוכתו על פתחו של קבר המאהיל עליה טמא וכו' אמר ר\\\"ש וכו' אם סוכה שיש לה טפח הרי היא חוצצת על גבה אם סוכה שאין לה פתח זהו גולל עצמו ורבינו סובר שאין זה ענין למשנתנו דהתם לענין מאהיל על הסוכה אם הוא טמא ומתניתין לענין הנכנס באותה סוכה אם נטמא:\",2,0],[8,374,8,1,\"שדה שאבד קבר בתוכה כו' וכל השדה כולה המאהיל עליה נטמא ואם העמיד בתוכה אהל נטמא כל מה שיש באהל. משנה בסוף אהלות ומטמא במגע ובמשא ובאהל:\",1,0],[8,374,8,3,\"בנה בה בית ועליה על גביו וכו' עד שהשרשים מגיעים עד למת. גם זה משנה בסוף אהלות:\",1,0],[8,374,8,3,\"וכתב הראב\\\"ד א\\\"א המשנה אמרה אינה נטעת וכו' משיג על רבינו שכתב אין נוטעים בתוכה אילני מאכל משמע דאילן סרק נוטעין ומתניתין קתני אינה נטעת כל נטע ועוד שמשמע מדבריו שאילן מאכל אין נוטעין אבל מותר לקיימו ומתניתין קתני דאין מקיימין ולדעת רבינו י\\\"ל שהוא מפרש דחוץ מאילן סרק קאי אאין נוטעין וכן משמע מדבריו בפירוש המשנה וכן פירש ה\\\"ר עובדיה וכן פירש רבינו שמשון בחד לישנא ומפרש דמאי דקתני אין מקיימין בה אילנות לא לאסור לקיים בה אילנות הנטועים אתא אלא טעם למה אינה נטעת כל נטע היא כלומר מפני שאין ראוי להקים בה אילן פירותיו מאחר שפירותיו ספק טמאים ויותר נכון לומר שרבינו לא היה גורס ואין מקיימין בה אילנות אלא הכי גריס ואינה נטעת כל נטע חוץ מאילן סרק. ורצה עוד הראב\\\"ד לסתור טעם רבינו שאם הטעם מפני שהשרשים מגיעים עד למת ויטמאו הפירות אם כן לא היה להם למנוע מליטע בה אילן סרק אבל לפי הטעם שאדם נמשך ועושה דירתו ביניהם לפעמים עושה דירתו באילן סרק ולפיכך אסרו לנטעו לכתחלה אבל לטעם רבינו לא ה\\\"ל לאסור ליטע אילן סרק. ולפי מה שכתבתי שמפרש או שגורס רבינו אין כאן השגה:\",2,0],[8,374,8,3,\"התלוליות הקרובות לעיר וכו' עד שאין אדם זוכרו. פי\\\"ו דאהלות ופ\\\"ב דכתובות (דף כ':) וכר\\\"י לגבי ר\\\"מ ודברי רבינו כפי' ר\\\"ח והתוספות הכריחו כן מן הסוגיא וכך היא בתוספתא פי\\\"ז. וסובר רבינו שמה שאמרו בגמרא עד חמשים אמות אזלא וכו' לר\\\"מ איתמר לפיכך השמיטו רבינו:\",3,0],[8,374,8,4,\"שדה בוכין וכו' עד שהרי לא הוחזקה שם טומאה. פי\\\"ח דאהלות זולת הטעם שנתן שהוא בפירקא קמא דמועד קטן (דף ה' ע\\\"ב) טעמא מאי אמר אבימי משום יאוש בעלים נגעו בה ודברי רבינו בפירושה מבוארים בדבריו והראב\\\"ד כתב שלנו יפה משלו וכו' דבריו ע\\\"פ דברי רבינו שמשון שכתב משום יאוש בעלים וכו' שהבעלים מתייאשים ממנה וה\\\"ל מצר שהחזיקו בו רבים שאסור לקלקלו אבל קשה שלפי זה אינו ענין לטומאה ולא היה לתנא לשנותו לענין טומאה.\",1,0],[8,374,8,4,\"ומה שכתב שלא להרגיל רגל אדם שם. תוספתא פרק י\\\"ו:\",2,0],[8,374,8,5,\"קבר הנמצא מותר לפנותו וכו'. בפרק נגמר הדין (סנהדרין דף מ״ז ע״ב) נמצאת אומר ג' קברות הן וכו' קבר הנמצא מותר לפנותו פינהו מקומו טהור ומותר בהנאה קבר הידוע אסור לפנותו פינהו מקומו טמא ואסור בהנאה קבר המזיק את הרבים מותר לפנותו פינהו מקומו טהור ואסור בהנאה ומקשה בגמרא וקבר הנמצא מותר לפנותו דילמא מת מצוה היה ומת מצוה קנה מקומו ומשני שאני מת מצוה דקלא אית ליה ופירש״י קבר הנמצא כגון שהוא חדש ויודע בעל השדה שלא צוה מעולם לקוברו שם ובגזילה נקבר שם. קבר הידוע שנקבר שם מדעת בעל השדה. קבר המזיק את הרבים שקבור במקום הילוך רבים ומיטמאים באהלו. מותר לפנותו שלא קנה את מקומו. מקומו טהור אע״פ שגזרו טומאה על הקברות ואע״פ שנטלו משם לא גזרו על זה ובהנאה נמי מותר ואע״ג דאיסורא דאורייתא הוא דאין תורת כלי עליו. מקומו טמא גזירה דרבנן היא שגזרו טומאה עולמית על הקבר כדי שלא יפנוהו. קבר המזיק את הרבים ניתן רשות לפנותו מפני נזקן של רבים. פינהו מקומו טהור דלא גזור עליה מפני הנזק ומיהו אסור בהנאה דאיסורא דאורייתא הוא ולא פקעא עכ״ל. ובתוספתא פי״ז דאהלות שנויה בסגנון אחר נמצאת אומר ג' קברות הן קבר הנמצא מפנין אותו פינהו מקומו טהור ואסור בהנאה קבר המזיק את הרבים מפנין אותו פינהו מקומו טמא ואסור בהנאה קבר הידוע אין מפנין פינהו מקומו טהור ומותר בהנאה ובמסכת שמחות פי״ד נמצאת אומר שלשה קברות הן קבר הנמצא בתחילה מותר לפנותו ואם פינהו מקומו אסור בהנאה קבר הידוע אסור לפנותו ואם פינהו אסור בהנאה קבר המזיק את הרבים אסור לפנותו ואם פינהו מקומו טמא ובירושלמי סוף נזיר (פ״ט הל' ג') שנויה בסגנון אחר נמצאת אומר שלשה מיני קברות הן קבר הנמצא מפנין אותו פינהו מקומו טמא ואסור בהנאה קבר הידוע אין מפנין אותו פינהו מקומו טהור ומותר בהנאה קבר שהוא מזיק את הרבים מפנין אותו פינהו מקומו טמא ואסור בהנייה הורה רבי אבא בר כהן בכפר עקביה מקומו מותר בהנייה מהו פליג כאן בשקדם הוא את העיר כאן בשקדמתו העיר וכתב הרשב״א בתשובה שגירסת הירושלמי משובשת דהיאך אפשר להחמיר בקבר הנמצא ולטמאו ולאסרו בהנייה יותר מקבר הידוע ואפי' תמצא לומר דבנמצא יש לחוש למת מצוה א״כ היאך אמרו שמותר לפנותו ועוד היאך אפשר לומר שיהא הנמצא מותר לפנותו ויהיה טמא ואסור בהנאה והידוע אסור לפנותו וטהור ומותר בהנאה וכי את שאסור לפנותו מותר בהנאה ואת שמותר לפנותו אסור בהנאה כלפי לייא ומיהו בקבר המזיק אפשר ליישב כגירסת הירושלמי ובדוחק שמותר לפנותו כדי שלא יצטרכו הרבים להתרחק ממנו ומ״מ לא לטהר מקומו כדי שלא יבאו להשתמש בו וליהנות ממנו והנאתו דאורייתא וכדמוקי לה התם בשקדם הקבר את העיר ונעשה שם ברשות וכי קתני בגמרין מקומו טהור ומותר בהנאה בשקדמה העיר לקבר ונעשה שם שלא כדין ולפיכך מקומו טהור שלא גזרו חכמים טומאה על זה וכן לא ירד בו איסור דאורייתא דשלא כדין נעשה שם עכ״ל. ואין דבריו נוחים לי שמ״ש דהיאך אפשר להחמיר בקבר הנמצא יותר מקבר הידוע זה הוא ע״פ מה שפירש רש״י בקבר הנמצא וקבר הידוע אבל לפי מה שנפרש בו לדעת רבינו ניחא ומה שתמה וכי את שאסור לפנותו מותר בהנאה ואת שמותר לפנותו אסור בהנאה נאמר בו טוב טעם ודעת ומה שרצה להעמיד דברי גמרא דידן בשקדמה העיר לקבר יש לתמוה דא״כ לא הוה שתיק גמרא דידן מלפלוגי בהכי וכן מ״ש ואפילו את״ל דבנמצא יש לחוש למת מצוה וכו' הוא דבר תמוה איך יעלה על הדעת לומר כן שהרי אמרו בגמרא מת מצוה קלא אית ליה. ולי נראה דה״פ הירושלמי לדעת רבינו קבר הנמצא היינו שלא היו יודעים שהיה שם קבר מותר לפנותו דכיון שלא היו יודעים בו מסתמא נקבר שם שלא מדעת בעל השדה וכיון דלאו מת מצוה הוא לא קנה מקום קברו ואם פינהו מקומו טמא כלומר השדה שסביבותיו טמא דחיישינן שמא בית הקברות הוא עד שיובדק כמו שיתבאר בפרק שאחר זה ואסור בהנאה כלומר השדה שסביבותיו אסור בהנאה כל זמן שלא נבדק דכיון דמספקינן ליה בבית הקברות דיינינן ליה כבית הקברות שאין נוהגין בהן קלות ראש אין מרעים בהם בהמה וכו' כדאיתא פרק בני העיר (מגילה דף כ״ט) ולדברים אלו קורא רבנו איסור הנאה שהרי כתב בסוף הלכות אבל בתי הקברות אסורים בהנאה כיצד אין אוכלין בהם וכו' כללו של דבר אין נאותין בהם ולא נוהגין בהם קלות ראש ובמצא ג' איירי שצריך לבדוק מן האחרון כ' אמה ואע״פ שמותר לפנותו פינוי המת שאני שאינו אלא מדרבנן מפני כבוד המת. קבר הידוע שאין שם אלא הוא לבדו ומסתמא נקבר שם מדעת בעל השדה אסור לפנותו כיון שמדעת בעל השדה נקבר שם ומקומו טהור ומותר בהנאה מאחר שידוע שאין שם קברים אחרים השדה שסביבותיו טהור ומותר בהנאה כלומר שלא נאסר לאכול ולשתות בו ולנהוג בו קלות ראש. קבר המזיק את הרבים כגון שהוא סמוך לרשות הרבים ומתטמאים העוברים בר״ה מפנין אותו אפילו אם נקבר ברשות בעל השדה כדי שלא יזיק את הרבים ומקומו כלומר השדה שסביבותיו טמא ואסור בהנאה מטעם שנתבאר גבי קבר הנמצא ודברי רבינו כגירסת הירושלמי ונ״ל שהיה רבינו גורס בגמרא דידן פרק נגמר הדין כגירסת הירושלמי דאל״כ לא הוה שביק גירסת גמרא דידן מפני הירושלמי ועי״ל דאסור בהנאה דקתני אקבר גופיה קאי וכגון שהוא קבר בנין הא לאו הכי מותר בהנאה והכי מוקי לה בפרק נגמר הדין ורבינו סמך על מ״ש בסוף הלכות אבל דקבר אינו אסור בהנאה אא״כ הוא של בנין והא דקתני גבי קבר הידוע פינהו מותר בהנאה אפילו בקבר של בנין שרי דכיון דידוע שלא נקבר שם אלא הוא לבדו מסתמא על דעת לפנותו נקבר שם שאין לך מי שרוצה לקבור מתו לבדו בשדה אחר וכיון דע״ד לפנותו נקבר שם הוה ליה כאילו לא היה שם קבר מעולם לענין זה:\",1,0],[8,374,8,5,\"והראב\\\"ד כתב על דברי רבינו זו הפיסקא איני מוצא אותה מכוונת וכו':\",2,0],[8,374,8,5,\"ומ\\\"ש שגירסת רבינו אינה מיושרת ומה יש בין קבר המזיק לקבר הנמצא כלומר שלגירסת רבינו שניהם שוים ואמאי מני להו בתרתי לערבינהו וליתנינהו י\\\"ל שאם הקושיא קושיא אינה על רבינו אלא על הירושלמי שממנו העתיק רבינו דבריו ולירושלמי י\\\"ל דמשום דבקבר המזיק בעי לפלוגי בין שקדם הוא את העיר לקדמתו העיר תנייה בלחודיה ושייך שפיר למיתני ג' קברות הן ועי\\\"ל דאע\\\"ג דלישנא דמיתני בתרווייהו שוה אין דינם שוה דמפנין דקתני בקבר הנמצא היינו לומר שרשאי לפנותו אבל מפנין דקתני בקבר המזיק היינו שצריך לפנותו עכ\\\"פ כדי שלא יזיק את הרבים והכי דייקא לשון רבינו דבקבר הנמצא כתב מותר לפנותו ובקבר המזיק כתב מפנין אותו כלומר עכ\\\"פ מפנין אותו כדי שלא יזיק את הרבים:\",3,0],[8,374,8,5,\"ומ\\\"ש לא ידעתי מהו עד שיבדוק שאני אומר שאפילו בדק ולא מצא שכונת קברות אע\\\"פ שנטלו ואת תבוסתו אפ\\\"ה מקומו מטמא במגע ואסור בהנאה והטומאה אינה אלא כדי להרחיק אדם מן ההנאה. אע\\\"פ שרש\\\"י כתב בפרק נגמר הדין שאע\\\"פ שניטל המת הקבר טמא שגזרו טומאה [עולמית] על הקבר כדי שלא יפנהו רבינו אינו מודה בזה שאחר שנטלו ואת תבוסתו היכן מצינו שמקום הקבר אסור בהנאה דהא אמרינן בפרק נגמר הדין דקבר של בנין הוא דאסור בהנאה אבל אם אינו של בנין מותר דקרקע עולם אינה נאסרת. ולדברי הראב\\\"ד שהוא אסור בהנאה אינו אלא מדרבנן ולמה יחמירו בו עוד לטמאותו כדי להרחיקו מההנאה. ומ\\\"ש והנוסחא המדוייקת קבר הנמצא מותר לפנותו ומקומו אסור בהנאה וטהור והידוע אסור לפנותו ומקומו טמא ואסור בהנאה והמזיק את הרבים מפנין אותו ומקומו טהור ומותר בהנאה. נוסחא זו שכתוב בה בקבר הנמצא טהור ט\\\"ס הוא שהרי הוא ז\\\"ל כתב שהטומאה אינה אלא כדי להרחיק את האדם מן ההנאה ומאחר שכתב דקבר הנמצא אם פינהו מקומו אסור בהנאה על כרחנו צריך לגרוס וטמא וכן מצאתי בספר מוגה:\",4,0],[8,374,8,5,\"ואני תמה על מ\\\"ש שהנוסחא המדוייקת היא כמ\\\"ש שאינה לא כגירסת גמרא דידן ולא כגירסת הירושלמי ולא כגירסת התוספתא ולא כגירסת מסכת שמחות:\",5,0],[8,374,8,7,\"הפוגע במת מצוה אם מצאו בתוך התחום. ירושלמי פרק כה\\\"ג ונזיר (הלכה א').\",1,0],[8,374,8,7,\"ומ״ש מצאו חוץ לתחום אפי' תוך שדה כרכום עד לאיזה צד שירצה וכו'. בס״פ מרובה (בבא קמא דף פ״א ע״ב) ובאבל רבתי (פ״ד) ובירושלמי פכה״ג.\",2,0],[8,374,8,7,\"ומ\\\"ש רבינו קוברו בשדה כרם. גירסת ספרים דידן באבל רבתי קוברו בשדה אילן ובירושלמי פ' כה\\\"ג שנויה במחלוקת דהכי איתא התם שדה כרם ושדה אילן אית תנויי תני קוברו בשדה כרם אית תנויי תני קוברו בשדה אילן מ\\\"ד [קוברו] בשדה כרם אבל בשדה אילן לא מפני אהל הטומאה כלומר ובשדה כרם ליכא למיחש אטומאה דכרמים שלהם היו גפנים שפלים סמוך לארץ הנקראים רוגליות. מ\\\"ד בשדה אילן אבל בשדה כרם לא מפני הכשר בצירה. ופסק רבינו כמ\\\"ד בשדה כרם מפני שיותר ראוי לחוש לאהל הטומאה שהוא כולל מלהכשיר בצירה שהוא פרטי:\",3,0],[8,374,8,8,\"קבר הנמצא וכו' עד משעת מציאה ואילך. תוספתא בפרק רביעי דטהרות:\",1,0],[8,374,8,8,\"וכתב הראב\\\"ד א\\\"א זו התוספתא אינה משוה עם המשנה וכו' ואפשר לומר דלא דמו דנפילת שרץ לית ליה קלא כמו קבורת מת:\",2,0],[8,374,8,9,\"כל המוצא קבר או מת וכו'. [משנה וגמרא] פ\\\"ק דמועד קטן (דף ב'):\",1,0],[8,374,8,9,\"אין מציינין על כזית מצומצם וכו'. שם (דף ה' ע\\\"ב). ובמה מציינין בסיד וכו'. פ\\\"ה דמעשר שני:\",2,0],[8,374,8,9,\"אין מעמידין את הציון ע\\\"ג הטומאה וכו' עד והפרעות. פ\\\"ק דמועד קטן (דף ה' ע\\\"ב) ופירש\\\"י שלא להפסיד את הטהרות שאם הטומאה ממש תחת הציון אינו מרגיש עד שבא אצל הציון פתאום ויטמאו הטהרות שהרי הטומאה תחת הציון אלא עושין הציון סמוך לטומאה ברחוק כל שהוא כשבא על הציון מרגיש מן הטומאה ואינו הולך עליה. אין מרחיקין את הציון ממקום טומאה יותר מכל שהוא שלא להפסיד ארץ ישראל שכשרואה סימן מיד פורש ונמצא ארץ ישראל בטומאה שלא לצורך:\",3,0],[8,374,8,10,\"מצא שדה מצויינת וכו'. שם אמרינן דשדה שנחרש בה קבר לא בעי ציון הואיל ואינה מטמאה באהל ומקשי והא תניא מצא שדה מצויינת ואינו יודע מה טיבה יש בה אילנות בידוע שנחרש בה קבר אין בה אילנות בידוע שאבד בה קבר וכו' אמר ר\\\"פ כי תניא ההיא בשדה שאבד בה קבר דציינוה ופירש\\\"י ואינו יודע מה טיבה אם הוא שדה שנחרש בה קבר ויכול לילך בניפוח (דאינו מטמא באהל) ואם מפני שנאבד בה קבר ואינו יכול ליכנס בה בנפיחה דמטמא באהל. יש בה אילנות בידוע שנחרש השדה לצורך האילנות ויכול להלך שאינה מטמאה באהל אלמא מדקתני בה מצא שדה מצויינת (משמע) דמציינין בית הפרס שנחרש. אר\\\"פ לעולם בית הפרס שנחרש לא בעי ציון והאי דקתני בידוע שנחרש בה קבר בשדה שאבד בה קבר וציינה לאלתר. יש בה אילנות בידוע שנחרש כו' לא בעי ציון אין בה אילנות בידוע שאבד בה קבר ולא נחרש עכ\\\"ל. ומקשה התם וליחוש דילמא אילנות מגואי וקבר מאבראי ומשני בעומדים על הגבולים ודילמא טומאה מגואי ואילנות מבראי במסובכין ואבע\\\"א הא אמרן אין מרחיקין ציון ממקום טומאה שלא להפסיד את א\\\"י. ופירש\\\"י וליחוש דילמא אילנות מגוואי וטומאה מאבראי ולא נחרש במקום טומאה מבחוץ לאילנות אלא בין האילנות והוי שדה שאבד בו קבר ולא נחרש ואמאי קאמר בידוע שנחרש בו קבר. בעומדים האילנות על הגבולים של ר\\\"ה דודאי ליכא טומאה מאבראי דלא קברי אינשי בר\\\"ה אלא בין האילנות הויא טומאה ונחרש בשביל האילנות. ודילמא טומאה מגואי ולא בין האילנות ולא נחרש במקום טומאה. מסובכין שאינם עומדים בשורה אחת סביב הגבולים אלא מעורבין בכל השדה דודאי נחרש כל השדה בשביל האילנות. הא אמרן אין מרחיקין ציון ממקום טומאה וכיון שסמוך לאילנות הציון ודאי טומאה בין האילנות היא ונחרש בשביל האילנות עכ\\\"ל. ולא כתב רבינו דדוקא בעומדים על הגבולים ובמסובכים משום דסמיך אואיבעית אימא דלפ\\\"ז ברייתא בכל גווני מיתניא ותשלום דין זה כתב רבינו בפ\\\"י:\",1,0],[8,374,8,11,\"מצא אבן אחת וכו' עד הרי זה ציון וטמא. ג\\\"ז שם (דף ו') אמר רב יהודה מצא אבן מצויינת תחתיה טמא שתים אם יש סיד ביניהן ביניהן טמא ואם אין סיד ביניהם ביניהם טהור ואע\\\"ג דליכא חורש והתניא מצא אבן אחת מצויינת תחתיה טמא שתים אם יש חורש ביניהם ביניהם טהור ואם לאו ביניהן טמא אמר ר\\\"פ הכא כשהסיד שפוך אל ראשיהם ומרודד לכאן ולכאן אי איכא חורש ביניהם ביניהן טהור דאימור מחמת חורש הוא דאיקפל ואי לא סיד דביני וביני הוא וטמא ופירש\\\"י אבן אחת מצויינת שיש סיד על גבה דאינו צריך להרחיק הציון מן האבן לפי שהאבן גבוה על גבי קרקע ורואה את הציון מיד קודם שיהא נוגע בו אבל בשדה מרחיקין לה ציון בסמוך דזימנין דלא חזי ציון עד דאתי ונגע ומאהיל. שתים מצויינות תחתיהן טמא אבל ביניהן אם יש סיד ביניהם על הארץ טמא דמשום ציון הוא. אע\\\"ג דליכא חורש שלא חרש ביניהם מעולם טהור כי ליכא סיד. אם אין חורש ביניהם טמא ואע\\\"ג דליכא סיד לפי שציין את האבנים שמכאן ומכאן לא חשש לציין בנתים. הכא דקתני כי ליכא חורש טמא כגון סיד שפוך על ראשי אבנים ומרודד לכאן ולכאן ביניהם דאי איכא חורש מחמת חורש הוא דאיקלף שנקלף מן האבנים ונפלו שם ביניהם וטהור ואי לא סיד דביני ביני הוא ומחמת ציון נעשה שם להודיע שיש גם ביניהם טומאה עכ\\\"ל. והתוס' גרסי אע\\\"ג דליכא חרס וזו היא גירסת רבינו ומפרש דביש חרש ביניהם מוכיח שאינו ציון קבר אלא בנין היא שכן דרך לשום חרשים הנקראים שוקף בבנין:\",1,0],[8,374,8,11,\"כתב הראב\\\"ד אם יש חרש ביניהם טהור וכו'. א\\\"א אנן חורש גרסי' וכו'. גירסתו גירסת רש\\\"י וכבר כתבתי שגירסת רבינו כגירסת התוס':\",2,0],[8,374,8,11,\"מצא מצר אחד מצויין וכו' עד סוף הפרק. ג\\\"ז שם. ופירש\\\"י שאין מרחיקין ציון ממקום טומאה ולהכי ציין כל ד' מצריה דיהא כל השדה נטמאת ובציון דמצר אחד לא סגי לכולה דאין מרחיקין ציון ממקום טומאה:\",3,0],[8,374,9,1,\"מי שהיה חופר בשדה ומצא מתים וכו'. בסוף נזיר (דף ס״ד ע״ב) ואהלות פט״ז מ״ג שנינו המוצא מת בתחילה מושכב כדרכו נוטלו ואת תבוסתו מצא שנים נוטלן ואת תבוסתן שלשה אם יש בין זה לזה מארבע אמות ועד שמנה (כמלוא מטה וקובריה) הרי זו שכונת קברות ובגמ' אמר רב יהודה המוצא פרט למצוי מת פרט להרוג מושכב פרט ליושב כדרכו פרט לשראשו מונח בין ירכותיו וכו' וכל הני מ״ט לא אמרינן דילמא עכו״ם הוא וכתב רבינו שם מה שאמר המוצא לא שיהיה מגולה בלתי שיחפש אחריו ויחפור ואומרו מת לא שיהיה הרוג ואומרו מושכב לא שימצאנו יושב ואמר כדרכו לא שיהיה ראשו בין יריכותיו לפי שכל זמן שיהיה בו דבר מאלו אינו עושה שכונת קברות עכ״ל וכתבו התוס' אמרינן דילמא עכו״ם הוא דישראל אין קוברין בענין זה ומשמע לרבינו דלא אימעיטו הני אלא מדין שכונת קברות אבל לא מדין תבוסה ובס״פ המוכר פירות (בבא בתרא דף ק״ב) תניא מצאן רצופין ואין ביניהם מד' אמות ועד ח' יש להם תבוסה ואין להם שכונת קברות.\",1,0],[8,374,9,1,\"ומ\\\"ש רבינו דה\\\"ה למצא מתים רבים בגומא אחת. משום דישראל אין קוברין בענין זה.\",2,0],[8,374,9,1,\"ומ\\\"ש ועפר זה עם ג' אצבעות שחופר הוא הנקרא תבוסת המת. שם בגמרא:\",3,0],[8,374,9,2,\"שדה שנהרגו בה הרוגים וכו' וכן המפנה קברו וכו' וכן בור שמטילין בתוכו נפלים וכו'. פי\\\"ו דאהלות.\",1,0],[8,374,9,2,\"ומ\\\"ש מלקט כל העצמות עצם וכו'. פי' שאין להם תבוסה:\",2,0],[8,374,9,3,\"היה חופר ומצא מת מושכב וכו' עד לפי שרגלים לדבר. משנה בסוף נזיר (דף ס\\\"ד ע\\\"ב) ופט\\\"ז דאהלות:\",1,0],[8,374,9,3,\"וצריך לבדוק מן האחרון כ' אמה. כתב הראב\\\"ד זה שיבוש אלא מן הראשון וד\\\"ז מפרש לה בגמרא דהמוכר פירות איך הוא בא לחשבון זה עכ\\\"ל. באמת כדברי הראב\\\"ד נראה שם בגמרא (דף ק\\\"ב) ואפשר שגירסא אחרת היתה לרבינו בגמרא ומצאתי כתוב רבינו הלך לשיטת רבו ן' מיגש:\",2,0],[8,374,9,3,\"ואם לא מצא שם מת אחר הרי אותן העשרים שבדק טהורות. כתב הראב\\\"ד ואם לא מצא שם מת אחר וכו' א\\\"א דבר זה לא ידעתי מהו וכו' ולי נראה שדעת רבינו שכל העשרים טהורות ומאי דקרי להו שכונת קברות אין פירושו כמו מה ששנינו במשנה מצא ג' אם יש בין זה לזה מד' אמות ועד ח' הרי זה שכונת קברות שפירושו ה\\\"ז בית הקברות אבל שכונת קברות שכתב כאן רבינו פירושו שכ' אמות אלו שכנים לקברות ואעפ\\\"כ הן טהורות ע\\\"פ מה שפירש שהכ' הם נמדדים מהאחרון ובגמרא (דף ס\\\"ה) ע\\\"ב אמרו עלה דמתניתין בדק מעשרים אמה ולא מצא מאי אמר רב מנשיא בר ירמיה אמר רב שכונת קברות מ\\\"ט אמר ר\\\"ל עילה מצאו וטהרו את א\\\"י ומדמסיים וטיהרו את א\\\"י משמע דה\\\"ק אותם קברות הם שכונת קברות וחוצה להם טהור וכך פירש\\\"י:\",3,0],[8,374,9,3,\"ואם היה אחד מאלו שמצא וכו'. בסוף נזיר (דף ס\\\"ה):\",4,0],[8,374,9,4,\"העכו\\\"ם אין להם טומאת קברות וכו'. נלמד ממה שכתבתי בסמוך שאמרו בסוף נזיר וכל הני מ\\\"ט לא אמרינן דילמא עכו\\\"ם הוא.\",1,0],[8,374,9,4,\"ומ\\\"ש שאינם מטמאים באהל. נתבאר בפ\\\"א:\",2,0],[8,374,9,5,\"מת שחסר אבר וכו'. בסוף נזיר מת שחסר אין לו תבוסה ולא שכונת קברות.\",1,0],[8,374,9,5,\"ומ\\\"ש אבר שאם ינטל מן החי ימות. תוספתא בפ\\\"א דאהלות:\",2,0],[8,374,9,5,\"ומתים הנמצאים גלויים וכו'. הוא ממה שאמרו בפרק בתרא דנזיר פרט למצוי:\",3,0],[8,374,9,5,\"והנקבר שלא ברשות וכו'. בתוספתא פי\\\"ו וכרשב\\\"ג וצריך טעם למה פסק כיחידאה דאף על גב דקי\\\"ל כ\\\"מ ששנה רשב\\\"ג במשנתנו הלכה כמותו כבר כתבו המפרשים דבמשנתנו אמרו ולא בברייתא וי\\\"ל שרבינו אינו סובר כן אלא דה\\\"ה בברייתא:\",4,0],[8,374,9,6,\"אחד המוצא ג' מתים כדרכן בתחילה כו'. תוספתא פ\\\"א דאהלות:\",1,0],[8,374,9,6,\"מצא שנים ואחד היה ידוע וכו'. בסוף נזיר (דף ס\\\"ח) מצא שלשה האחד ידוע ושנים תחילה או שנים תחילה ושנים ידועים אין להם תבוסה ואין להם שכונת קברות ורבינו גורס יש להם תבוסה וכך היא גירסת תוספתא:\",2,0],[8,374,9,6,\"כיצד בודק העשרים אמה שאמרנו וכו'. בפרק י\\\"ו דאהלות:\",3,0],[8,374,9,6,\"העמיק אפילו מאה אמה ומצא חרש וכו'. תוספתא פי\\\"ו דאהלות.\",4,0],[8,374,9,6,\"ומ\\\"ש הגיע למים ה\\\"ז כבתולה. שם:\",5,0],[8,374,9,7,\"אינו צריך לחפור תלם אחד מתחילת העשרים ועד סופן וכו'. משנה פרק ט\\\"ז דאהלות:\",1,0],[8,374,9,9,\"היה בודק והגיע בתוך העשרים לנהר וכו' עד אינו אוכל בתרומה. משנה שם:\",1,0],[8,374,9,9,\"כתב הראב\\\"ד אבל קודם שימצא אוכל בתרומה א\\\"א המשנה אמרה בדמע ולא בתרומה ודאית עכ\\\"ל. טעמו שהוא ז\\\"ל מפרש דמע לשון מדומע תרומה שנתערבה בחולין ורבינו מפרש שהתרומה נקראת דמע דכתיב מלאתך ודמעך וכן פירש בפירוש המשנה שם:\",2,0],[8,374,9,10,\"גל טמא שנתערב וכו'. משנה בפ\\\"ט דנדה (דף ס\\\"א) וכחכמים:\",1,0],[8,374,9,11,\"בור שמטילים לתוכו נפלים וכו'. פירקא קמא דפסחים עלה ט' ופרק כל הצלמים (עבודה זרה דף מ״ב) ופרק כל היד (נדה דף ט״ו) ודלא כתירוץ שני להחמיר:\",1,0],[8,374,9,12,\"דבר ידוע שכל אלו הטומאות וכו'. כתב הראב\\\"ד זהו שיבוש גדול שהרי אמרו בכמה מקומות וכו'. וי\\\"ל שרבינו סובר שמה שאמרו ספיקא דאורייתא לחומרא מדרבנן בעלמא הוא שהחמירו בספיקא וכתב הר\\\"ן בספ\\\"ק דקידושין ובתשובה סימן נ' שהביא ראיה לדבריו מדאמרינן פרק עשרה יוחסין התורה אמרה לא יבוא ממזר ממזר ודאי הוא לא יבא הא ממזר ספק יבא וכן דעת הרמב\\\"ן ואע\\\"פ שהביא שם טענות החולקין על רבינו מ\\\"מ זהו דעת רבינו ויש ראיה לדבריו וכיון שכן אין בדברי רבינו שיבוש ואחד מהטענות שכתב שם שטענו על רבינו הוא מדחייב רחמנא אשם תלוי ודבר זה יישבו רבינו שמצאתי כתוב בספר ישן בסוף פרק זה כלשון הזה ואף על פי כן דבר שחייבים על זדונו כרת ספיקו אסור מן התורה שהרי העושה אותו חייב אשם תלוי עכ\\\"ל. ויש לתמוה על הראב\\\"ד שבסוף הלכות כלאים הודה לדברי רבינו וכאן כתב שהוא שיבוש גדול. ומ\\\"ש דהול\\\"ל משום דהוי ספק ספיקא יש לומר שאפי' בנודע שהפילה שם נפל ואין ידוע אם הפילה דבר טמא הוי ספק ספיקא [אבל] דינים אחרים נזכרו בפרק זה שאין בהם אלא ספק אחד והם טהורים ועי\\\"ל דאפי' הא דאין ידוע אם הפילה דבר המטמא לא חשיב ספק ספיקא משום דרוב מפילות דבר המטמא הן מפילות:\",1,0],[8,374,10,1,\"איזהו בית הפרס וכו'. פרק י\\\"ז דאהלות.\",1,0],[8,374,10,1,\"ומ\\\"ש אפילו חרש ע\\\"ג הארון וכו' עד ה\\\"ז עושה בית הפרס. תוספתא שם:\",2,0],[8,374,10,1,\"עד כמה היא נעשית בית הפרס וכו'. משנה פי\\\"ו דאהלות:\",3,0],[8,374,10,3,\"התחיל לחרוש את הקבר וכו'. עד שאין עצמות הקבר מגיעות ליתר ממאה. בפרק י\\\"ו דאהלות:\",1,0],[8,374,10,4,\"חזקת העצמות המכוסות וכו'. תוס' ספי\\\"ו דאהלות:\",1,0],[8,374,10,4,\"היה שם חריץ מלא עצמות אדם וכו'. פרק י\\\"ו דאהלות החורש מלא טמיא מצבירת העצמות משדה שאבד קבר בתוכה או שנמצא בה קבר וכו' אינו עושה בית הפרס ואיני יודע למה השמיט רבינו שנמצא בה קבר אח\\\"כ מצאתיו בספר מוגה:\",2,0],[8,374,10,4,\"וכתב הראב\\\"ד היה שם חריץ מלא עצמות וכו'. א\\\"א זהו פי' מלא טמיא ופשוט הוא:\",3,0],[8,374,10,4,\"וכן החורש את המת וכו'. תוספתא בפרק י\\\"ו דאהלות:\",4,0],[8,374,10,5,\"החורש את הקבר בשדה שאינה שלו וכו'. בפי\\\"ו דאהלות.\",1,0],[8,374,10,5,\"ומ\\\"ש אפי' שותף וכו' עד ושל חבירו אינו עושה בית הפרס. תוספתא בפרק הנזכר:\",2,0],[8,374,10,7,\"עכו\\\"ם שחרש קבר וכו' עד שאין בית הפרס עושה בית פרס. משנה בפרק הנזכר:\",1,0],[8,374,10,8,\"בית הפרס הזה מותר לנטוע בו כל נטע עד ושורף את הקש ואת העצה. משנה פי\\\"ח דאהלות וכחכמים:\",1,0],[8,374,10,8,\"וכתב הראב\\\"ד ולמטה מג' בבית הפרס טהור וכו' א\\\"א אין צורך לזה הטעם וכו'. אין בזה השגה על רבינו שפירושו ג\\\"כ נכון:\",2,0],[8,374,10,9,\"שדה שהוחזקה שהיא בית הפרס וכו' עד הרי היא בחזקתה. תוספתא בפרק י\\\"ו דאהלות:\",1,0],[8,374,10,9,\"וכתב הראב\\\"ד ספרו היה משובש בכאן וכו'. וגירסת רבינו ממקום הטיט וגירסת ספרים דידן בתוספתא כגירסת הראב\\\"ד. והר\\\"י קורקוס ז\\\"ל תמה על הראב\\\"ד שכתב דבאבד מיירי שהרי אותו פרק קודם דין זה ואחריו מיירי בנחרש ותו דבאבד מאי אפילו בית ד' כורין מאי רבותא כי בשדה שאבד לא נזכר שיעור אלא כ\\\"מ שהוא בספק הקבר גם מה שפירש בלשון אפילו משוכה ממקום הטומאה הוא דוחק בלשון ותו דמאי קמ\\\"ל ואם מסופקים אם הקבר שם כי נכנס למקום טהרה מאי הוי וגם החלוקה האחרת דהיינו טהורה מקצתה מאי קאמר כל בית הפרס שאבד בה קבר כך הוא כי המקום שמסתפקים בו טמא והשאר גם כל סביבותיו טהור עכ\\\"ל:\",2,0],[8,374,10,10,\"מצא שדה מצויינת וכו'. תוספתא פרק י\\\"ו דאהלות ואיתא בפ\\\"ק דמועד קטן (דף ה' ע\\\"ב) ויש בספרים שלנו בדברי רבינו חסרון וכך היא הנוסחא הנכונה אם יש בה אילן בידוע שנחרש (בה) קבר בתוכה אין בה אילן בידוע שאבד קבר בתוכה והטעם משום דתנן שדה שנחרש בה קבר ניטעת ושדה שאבד בה קבר אינה ניטעת ואין מקיימין בה אילנות.\",1,0],[8,374,10,10,\"ומ\\\"ש והוא שיהיה באותו מקום זקן או ת\\\"ח. שם א\\\"ר יהודה בד\\\"א בזמן שיש שם חכם או ת\\\"ח שאין כל אדם בקיאים בכך וידוע שכ\\\"מ שא\\\"ר יהודה במה דברים אמורים אינו אלא לפרש:\",2,0],[8,374,10,10,\"וכתב הראב\\\"ד שאין כל אדם בקיאים בכך ויודעים שמותר לנטוע בזו וכו' א\\\"א לא כי אלא שאין הכל זריזין וכו'. ואיני יודע למה דחה פי' רבינו שפירושו דאין בה אילנות הוא כפשוטו:\",3,0],[8,374,10,11,\"המהלך בבית הפרס על גבי אבנים וכו' עד על גבי אדם שכחו רע. בפי\\\"ח דאהלות.\",1,0],[8,374,10,11,\"ומה שכתב עד שתהיינה ארכובותיו נוקשות זו לזו וכו' עד בשעת רכיבה. במציעא פרק המקבל (בבא מציעא דף ק״ה ע״ב):\",2,0],[8,374,10,12,\"המטהר בית הפרס צריך לטהרו במעמד של שני ת\\\"ח. תוספתא פי\\\"ו דאהלות:\",1,0],[8,374,10,12,\"וכיצד מטהרין אותו וכו' עד ונתן על חציו האחר ג' טפחים ה\\\"ז טהור. בפי\\\"ח דאהלות:\",2,0],[8,374,10,12,\"נטל מעל פניו טפח ומחצה וכו'. שם וכת\\\"ק:\",3,0],[8,374,10,12,\"רצפו באבנים. גם זה שם:\",4,0],[8,374,11,1,\"ארץ העכו\\\"ם בתחילה גזרו על גושה בלבד וכו'. בספ\\\"ק דשבת (דף ט\\\"ו ע\\\"ב):\",1,0],[8,374,11,1,\"וכן כלי חרס וכו'. תוספתא בפי\\\"ח דאהלות:\",2,0],[8,374,11,2,\"טומאת אויר ארץ העכו\\\"ם לא עשו אותה כטומאת עפרה וכו' שעל טומאת עפרה שורפים תרומה וקדשים. בפרק קמא דשבת שם.\",1,0],[8,374,11,2,\"ומ״ש והמתטמא בגושא טמא טומאת שבעה וצריך הזייה שלישי ושביעי אבל הנטמא באוירה אינו צריך הזייה שלישי ושביעי וכו'. בפרק כהן גדול (נזיר דף נ״ד נ״ה).\",2,0],[8,374,11,2,\"ומ\\\"ש וכן תרומה וקדשים שנטמאו מחמת אוירה תולין וכו'. בפ\\\"ק דשבת:\",3,0],[8,374,11,3,\"עפר ארץ העכו\\\"ם וכו'. פרק ב' דאהלות.\",1,0],[8,374,11,3,\"ומה שכתב וכמה שיעורן כחותם המרצופין. שם פרק י\\\"ז.\",2,0],[8,374,11,3,\"ומה שכתב והוא כפיקה גדולה של סקאין. בבכורות פרק הלוקח בהמה (בכורות דף כ״ב) פי' פיקה אבלי״ו. של סקאים של עושה סקים:\",3,0],[8,374,11,3,\"עפר בית הפרס ועפר חוצה לארץ שבא בירק וכו'. בפי\\\"ז דאהלות וכחכמים:\",4,0],[8,374,11,4,\"המביא תנורים וכו'. תוספתא דאהלות פרק י\\\"ז:\",1,0],[8,374,11,5,\"המהלך בארץ העכו\\\"ם וכו' עד טהור. משנה בפי\\\"ח דאהלות המהלך בארץ העכו\\\"ם בהרים ובסלעים טמא בים ובשונית טהור איזהו שונית כ\\\"מ שהים עולה בזעפו ופי' רבינו שכח גזירה זו שגזרו על ארץ העכו\\\"ם טומאה אינה על הרריה ועל אבניה כי לא יקברו שם מת כלל אבל הוא טמא להשתפך בהם עפר ארץ העכו\\\"ם (והים והשונית גושה טהור לפי שלא יקברו בה מתים) וכו' וענין אמרו טהור שלא תחייבהו דיני טומאת מת ר\\\"ל הזאת שלישי ושביעי ואין שורפין תרומה וקדשים שנכנסו לשם לפי שזהו דין אוירה ר\\\"ל שהגזירה היא אגושה לשרוף ואאוירה לתלות ואין צריך אלא טבילה ולא הערב שמש עכ\\\"ל.\",1,0],[8,374,11,5,\"ומ\\\"ש וטמא משום אוירה. נלמד ממה שיבא בסמוך:\",2,0],[8,374,11,5,\"הנכנס לארץ העכו״ם בשידה תיבה ומגדל וכו'. בפ״ק דגיטין (דף ח' ע״ב) ובפרק בכל מערבין (עירובין דף ל':) פלוגתא ופסק כרבי מחבירו ועוד דבשילהי חגיגה (דף כ״ה) מוקי סתם מתני' כרבי דאמר אהל זרוק לאו שמיה אהל ופירש ר״ש אהל מיטלטל ונזרק כזה לא שמיה אהל להפסיק בין אוירה:\",3,0],[8,374,11,6,\"סוריא עפרה טמא כחוצה לארץ ואוירה טהור וכו'. בפרק קמא דגיטין (דף ח' ע\\\"ב).\",1,0],[8,374,11,6,\"ומ\\\"ש לפיכך אם היתה סמוכה לארץ ישראל וכו'. בפי\\\"ח דאהלות.\",2,0],[8,374,11,6,\"ומ\\\"ש בשידה תיבה ומגדל. בפרק קמא דגיטין (דף ח' ע\\\"ב).\",3,0],[8,374,11,6,\"ומ\\\"ש שלא יהא מפסיק ביניהם בית הפרס. היינו שדה שאבד קבר בתוכה שהוא מטמא באהל דאילו שדה שנחרש בה קבר מאחר שאינה מטמאה באהל כי מפסיק מאי הוי:\",4,0],[8,374,11,6,\"ומה שכתב וכן ארץ העמים הסמוכה לארץ ישראל וכו': כתב הראב\\\"ד א\\\"א אני לא מצאתי בתוספתא אלא מובלעות עכ\\\"ל. ויש לתמוה שהרי בתוספתא דאהלות פרק י\\\"ח שנינו ארץ העכו\\\"ם אם יכול ליכנס בטהרה טהורה וכמה תהא סמוכה ויהא יכול ליכנס בטהרה רשב\\\"ג אומר אפי' תלם אחד הרי זה מפסיק וזה מבואר בדברי רבינו ומשמע לרבינו שאע\\\"פ ששנינו טהורה היינו לענין שלא גזרו עליה אבל מ\\\"מ צריכה בדיקה. ומובלעות שכתב הראב\\\"ד, שם בפ' הנזכר וכתבה רבינו בס\\\"פ זה:\",5,0],[8,374,11,7,\"מקום ששכנו בו עכו\\\"ם. בפי\\\"ח דאהלות.\",1,0],[8,374,11,7,\"ומ\\\"ש ותרומה וקדשים וכו' תולין וכו'. בפי\\\"ח דאהלות בתוספתא וכת\\\"ק:\",2,0],[8,374,11,8,\"וכמה ישהו במקום וכו'. פי\\\"ח דאהלות.\",1,0],[8,374,11,8,\"ומ\\\"ש אפילו עבד וסריס [או אשה] או קטן בן ט' שנים ויום אחד. תוספתא פי\\\"ח דאהלות וכתוב בספרי רבינו או אשה ונוסחת התוספתא או שפחה ואיני יודע מאי קמ\\\"ל דכיון דגזרו על איש אעפ\\\"י שאין עמו אשה ואפי' הוא סריס וכו' ממילא משמע דגזרו על אשה אע\\\"פ שאין עמה איש ולגירסת התוספתא קשה מאי איריא שפחה דנקט:\",2,0],[8,374,11,9,\"מדור עכו\\\"ם שהיה בו עבד או אשה וכו'. משנה שם.\",1,0],[8,374,11,9,\"ומ\\\"ש או קטן בן ט' שנה. בתוספתא ואיני יודע למה הצריך שיהא בן ט' שנים ואפשר שהטעם שמאחר שפחות מכאן אין ביאתו ביאה אינו יודע לשמור מביאה דוגמא לדבר מה שאמרו לענין יחוד קטנה היודעת טעם ביאה ומאחר שאינו יודע לשמור מביאה ה\\\"ה דאינו יודע לשמור אם קברו שם נפל:\",2,0],[8,374,11,9,\"ואת מה הן בודקין וכו'. כך היא הגירסא הנכונה והדין משנה שם.\",3,0],[8,374,11,9,\"ועל מ״ש מדור העכו״ם שחרב. כתב הראב״ד מדור העכו״ם שחרב הרי הוא בטומאתו עד שיבדק א״א במשנה שנינו רשב״ג אומר עיר של עכו״ם שחרבה אין בה משום מדור העכו״ם ואין עליו מחלוקת ואולי יש הפרש בין עיר שחרבה למדור שחרב עכ״ל. ואיני יודע איך נתפייס הראב״ד בזה שעדיין יקשה על רבינו למה השמיט דין עיר עכו״ם שחרבה וגם מהיכן הוציא לחלק בין עיר עכו״ם שחרבה למדור העכו״ם שחרב ועוד היאך אפשר לטמא במדור ולטהר בעיר והרי בכלל העיר מדור ואיך יטהר ולכן נראה לי שרבינו סובר שמאחר שדין עיר שנויה בשם רשב״ג משמע דרבנן פליגי עליה והלכתא כוותייהו וכ״פ בפי' המשנה שאין הלכה כרשב״ג וכתב רבינו שם שטעם רשב״ג מפני שהב״ח יחפרו בה תמיד ומוציאין מה שיש שם ולפ״ז הדבר ברור דרבנן פליגי עליה ממה שנתבאר בספ״ט בור שמטילין לתוכו נפלים המאהיל עליו טמא דין תורה אע״פ שחולדה וברדלס מצוי שם מפני שכך היא לשון התוספתא ומשמע לרבינו שהם דברי חכמים שחלקו על רשב״ג ואע״ג דרשב״ג נקט עיר וחכמים נקטו מדור הכל אחד דמדור היינו עיר א״נ דמדור הוא בית אחד ושינתה התוספתא ורבינו לכתוב מדור במקום עיר לרבותא דאפילו מדור אחד טמא כ״ש עיר שיש בה מדורות הרבה. וא״ת אפילו תימא דפליגי רבנן עליה הא קי״ל כ״מ ששנה רשב״ג במשנתנו הלכה כמותו י״ל דשאני הכא דגמרא בפ״ק דפסחים (דף ט') ובפרק כל הצלמים (עבודה זרה דף מ״ב) ובפרק כל היד (נדה דף ט״ו) אמרו בחד תירוצא דלא כרשב״ג ואי הוה סבר גמרא דהלכה כוותיה לא הוה אמר תירוצא סתם דלא כהלכתא כך נ״ל לדחוק לדעת רבינו:\",4,0],[8,374,11,10,\"האיצטווניות אין בהם משום מדור העכו\\\"ם וכו'. ודברים אלו משנה פי\\\"ח דאהלות ופירש שם רבינו אצטוונית [הוא] מקום וכו' ואין לו כותל והוא מין ממיני הכרמלית וכו'. צריפין מין ממיני האהלים וכו' והוא מחודד ואין לו גג וכו'. מקום החצים המקומות שיעשו בו החצים. לגיונות מרוצות הפרשים לפי שאלו המקומות אין בהם יישוב ולא יקברו בו ואמנם יעמדו בו בזמן מהזמנים מעט ולזה לא גזרו עליהם:\",1,0],[8,374,11,10,\"כתב הראב\\\"ד והתקרה שע\\\"ג העמודים וכו' א\\\"א זה פירוש האלקטיות עכ\\\"ל. ופשוט הוא וכ\\\"כ רבינו בפירוש המשנה:\",2,0],[8,374,11,11,\"החנות אין בה משום מדור העכו\\\"ם אא\\\"כ היה דר בתוכה. תוספתא בסוף אהלות:\",1,0],[8,374,11,11,\"חצר שהיא טמאה משום מדור העכו\\\"ם וכו'. שם בית שער ואויר החצר בזמן שהם מעורבים במדור העכו\\\"ם טמאים משום מדור העכו\\\"ם אם אינן מעורבים וכו' אינן טמאים וכו' ונראה שרבינו מפרש שהכוונה שבזמן שהחצר טמא בית שער והאויר טמא. ומ\\\"ש בסמוך בית שער ואוירה של חצר אינן טמאים היינו שידוע שלא דרו בחצר ואינה טמאה הילכך אף על פי שדרו בבית שער או באמצע החצר דירת עראי היא זו ואינם טמאים טומאת עצמם לבדם אבל כל שהחצר טמאה גם אוירה ובית שער טמאים ונמשכים אחריה עכ\\\"ל הר\\\"י קורקוס ז\\\"ל ויש לגמגם במה שאמר אף על פי שדרו וכו' באמצע החצר דירת עראי היא זו שאם דירה באמצע החצר דירת עראי היא וטהור היכי משכחת חצר שיהיה טמא משום מדור הטמא וצ\\\"ל דבשדר עכו\\\"ם בבית גם החצר טמא משום מדור העכו\\\"ם אבל כשלא דר אלא בחצר דירת עראי היא וטהור:\",2,0],[8,374,11,11,\"ואין מדור העכו\\\"ם ולא בית הפרס בח\\\"ל. גם זה שם ואם תאמר היכי שייך לומר כן והרי ח\\\"ל כולה טמאה יותר מטומאת מדור העכו\\\"ם ואין לומר דמשום מובלעות הוא דתני הכי דהא משמע התם דאשקלון מהמובלעות ויש בה משום מדור העכו\\\"ם וי\\\"ל דאיצטריך משום כהנים דבח\\\"ל דדוקא בארץ ישראל גזור עכ\\\"ל רבינו שמשון וכתב הר\\\"י קורקוס ז\\\"ל ולדעת רבינו נראה דמובלעות הוא דאיצטריך למיתני הכי ולהו נ\\\"מ ולכך סמך לו דין מובלעות לפרש דלהכי נ\\\"מ דאל\\\"כ אמאי שבקיה עד הכא גבי דין ארץ העכו\\\"ם הוה ליה לכתבו מה שייך למדור העכו\\\"ם אלא ודאי כדכתיבנא וההיא דאשקלון יש בה משום מדור העכו\\\"ם לא חשש לה עכ\\\"ל ואני מצאתי כתוב ואין מדור העכו\\\"ם וכו' היינו דאין לו תקנה כמו שאמר למעלה פ\\\"ו מטהר בית הפרס לפני שני ת\\\"ח ובחוץ לארץ אין תיקון וגם במדור העכו\\\"ם אמר למעלה שבודקין אותו ובחוצה לארץ אין תיקון עכ\\\"ל:\",3,0],[8,374,11,12,\"עיירות המובלעות בארץ ישראל וכו'. עד סוף הפרק תוספתא בסוף אהלות שם:\",1,0],[8,374,12,1,\"טפח על טפח וכו'. משנה פ״ג דאהלות ומימרא דרבא פרק מי שמתו (ברכות דף י״ט ע״ב) ופירוש מרובע כתב רבינו בפירוש המשנה למעט כל שהמקום ארוך וקצר אפילו שיש בתשבורתו טפח על טפח אינו אהל:\",1,0],[8,374,12,1,\"כתב הראב\\\"ד א\\\"א לא בירר את דבריו דחלל טפח פנוי בעינן וכו'. וי\\\"ל שרבינו העתיק לשון המשנה כמות שהוא וכבר נודע שזה הוא דרכו ועוד שלקמן בפרק זה ביאר רבינו שכתב גבי ארונות של עץ אם יש בין כיסוי הארון והמת טפח חוצץ וגם בפ\\\"ז כתב כמה פעמים אם יש לו חלל טפח ואם אין שם חלל טפח ולשון חלל הוא המקום פנוי:\",2,0],[8,374,12,1,\"היה האהל פחות מרום וכו'. בפ\\\"ז דאהלות נפש אטומה הנוגע בה מן הצדדים טהור מפני שטומאתו בוקעת ויורדת ואיכא בכמה דוכתי.\",3,0],[8,374,12,1,\"בד\\\"א בשלא היה האהל אדם או כלים וכו'. בפ\\\"ו דאהלות:\",4,0],[8,374,12,2,\"ומה שכתב וכלי גללים וכלי אבנים וכלי אדמה הבאים במדה הרי הם כאהלים ואינם ככלים ולפיכך חוצצים בפני הטומאה. כך מצאתי בדברי רבינו בספר מוגה וכך היתה נוסחת הראב\\\"ד בדברי רבינו שכתב א\\\"א והלא אפילו של עץ והם באים במדה כדאיתא פרק יש מביאין וחוצצין עכ\\\"ל. וי\\\"ל שגם רבינו סובר כן שהרי בפי\\\"ג כתב דכלי עץ הבאים במדה מביאין וחוצצין וכמו ששנינו וכאן איידי דפתח בכלי אבנים סיים בהו לומר שאף ע\\\"פ שאין מינם מקבל טומאה אינם חוצצים אלא אם כן באים במדה ולא למעט כלי עץ אתא וסמך על מה שכתב בפרק י\\\"ג:\",1,0],[8,374,12,3,\"נסר שהוא נתון על פי תנור חדש וכו'. בפי\\\"ב דאהלות פירש דתנור חדש כל זמן שלא הוסק אינו כלי וחשיב כאבן וישן דהיינו שהוסק הוי כלי ויש בספרי הדפוס חסרון וכך היא הנוסחא הנכונה היתה הטומאה תחת הנסר כלים שעל גביו טהורים טומאה על גביו כלים שתחתיו טהורים:\",1,0],[8,374,12,4,\"נסר שהוא נתון ע\\\"פ שני תנורים וכו'. נראה שזהו פי' מה ששנינו שם נתון ע\\\"פ שני תנורים טומאה ביניהם הם טמאים. והראב\\\"ד כתב שהרי הם כשני אהלים זה בצד זה וכו' א\\\"א אין הטעם הזה מספיק וכו'. מ\\\"ש והמשנה מדברת בעודף מכל צדדיו באמת פשט המשנה כך הוא דקתני בריש פרק י\\\"ב דאהלות נסר שהוא נתון ע\\\"פ תנור חדש ועודף מכל צדדיו בפותח טפח טומאה תחתיו כלים שעל גביו טהורים וכו' ובישן טמא וכו' נתון על פי שני תנורים טומאה ביניהם הם טמאים ר\\\"י בן נורי מטהר ומשמע דנתון על שני תנורים דקתני בסיפא בעודף מכל צדדיו פותח טפח היא דומיא דרישא ועוד דבתר הכי קתני דין נסר שהוא נתון על גבי תנור ישן יוצא מזה ומזה טפח אבל לא מן הצדדין טומאה בצד זה כלים שבצד השני טהורים משמע דעד השתא לא איירי אלא בעודף מכל צדדיו פותח טפח גם מה שהכריע מדקתני הם טמאים גם מה שהכריע מדקתני בתוספתא רבי יוחנן בן נורי מטהר בתנור דברים נכונים הם. ומ\\\"ש ובתוספתא נתון על שני תנורים וחדש באמצע וכו' בא להכריע שאין הדבר כמ\\\"ש דנתון על שני תנורים ישנים אין טמא אלא ביניהם שהרי בתוספתא טמאו אפילו בחדש באמצע ועפ\\\"ז כבר אפשר ליישב דברי רבינו בדוחק:\",1,0],[8,374,12,4,\"וכן נסר שהוא וכו'. גם זה שם:\",2,0],[8,374,12,5,\"אדם שנשא כלים וכו'. ריש פרק ט\\\"ז דאהלות וכרבי עקיבא שאמר אני אתקן שיהיו דברי חכמים קיימים.\",1,0],[8,374,12,5,\"ומה שכתב גזרו על שהיקפו טפח וכו'. בפירקא קמא דשבת (דף י\\\"ז):\",2,0],[8,374,12,6,\"ארונות של עץ וכו'. בפרק מי שמתו (ברכות דף י״ט ע״ב) א״ר אלעזר בר' צדוק מדלגים היינו ע״ג ארונות ואמרינן התם מפני שרוב ארונות יש בהם חלל טפח וחוצץ בפני הטומאה וקשה דאדרבא פותח טפח מטמא יותר דמטמא כל סביביו וכמ״ש בפ״ז ולזה כתב רבינו דהני מילי בקבר אבל בארונות של עץ אין דינם כקבר סתום ולכך פותח טפח הוי אהל וחוצץ ככל אהלים החוצצים בפני הטומאה דבקרא קבר כתיב:\",1,0],[8,374,12,6,\"וכתב הראב\\\"ד א\\\"א זה המחבר דלה מים מבורות עמוקים וכו'. אע\\\"פ שהתוספות שם כתבו כדבריו מ\\\"מ אינו כדאי פי' זה להטעות למי שפירש פי' אחר ולומר עליו שטעה ואין לומר שטעמו מפני שאין דרך להניח מתים בארונות של עץ מגולים על פני השדה שג\\\"כ ארונות של אבן אין דרך להניח המת בתוכן והם מגולים על פני השדה וצ\\\"ל שהיו מניחים הארונות מגולים בעוד שהיו חופרים הקברות ולפעמים היו רבים שהיו תופסין כל הדרך והיו צריכים לדלג עליהם:\",2,0],[8,374,12,6,\"ומ\\\"ש הראב\\\"ד והתוס' שאין הכהנים מוזהרים אלא על טומאה שהנזיר מגלח עליה. הוא בתוספתא דמכות:\",3,0],[8,374,12,7,\"קורה שהיא נתונה מכותל עד ארבעה טפחים. בריש פרק י\\\"ב דאהלות.\",1,0],[8,374,12,7,\"ומה שכתב אף על פי שאין כולה שוה וכו'. כתב הר\\\"י קורקוס דדייק כן רבינו מדקתני מביאה את הטומאה תחת כולה דאי לא כן ליתני מביאה את הטומאה ותו לא.\",2,0],[8,374,12,7,\"ומה שכתב בזמן שהיא עגולה שלשה טפחים. דכל שיש ברחבו טפח יש בהיקפו שלשה טפחים כדתנן בעירובין פירקא קמא (דף י\\\"ג ע\\\"ב) שכן מצינו בדברי הימים בים שעשה שלמה עשר באמה משפתו אל שפתו עגול סביב וקו שלשים באמה יסוב אותו:\",3,0],[8,374,12,8,\"סאה שהיא מוטה על צדה באויר וכו'. תוספתא דאהלות פי\\\"ג פי' סאה זו הוא חלולה וכשהיקפה ד' טפחים וחצי כשתתן קו באמצעה יהיה רחבו של קו טפח ומחצה שהם שש אצבעות וגבהו שלש אצבעות וכשאנו מגביהין הקו אצבע למעלה מאמצעה נמצא גבהו ד' אצבעות שהוא טפח ומתוך שכשעלה אצבע למעלה הוא שמתקצר ועולה נמצא מתקצר מרחבו אצבע מכאן ואצבע מכאן נשאר גם ברחבו טפח הרי בקו זה טפח על טפח מרובע:\",1,0],[8,374,12,8,\"ומ\\\"ש לפיכך אם היתה גבוהה מעל הארץ חצי טפח וכו'. מבואר שנמצא צד העליון גבוה מן הארץ טפח ומחצה וכשאנו מגביהים אצבע למעלה מאמצע גבהה נמצא ששם הוא טפח על טפח:\",2,0],[8,374,12,8,\"וכתב הראב\\\"ד ק\\\"ל אם זה הגבהות שאמר אויר הוא וכו'. איני יודע מי הכניסו במבוכה זו ודברי רבינו מבוארים ע\\\"פ מ\\\"ש:\",3,0],[8,374,12,8,\"וכן עמוד וכו'. משנה פי\\\"ב:\",4,0],[8,374,12,8,\"לפיכך אם היה בהיקף וכו': כתב הראב\\\"ד מה הועיל זה האיש בצורותיו ולא האיר ולא הצהיר מה צורך לכ\\\"ד טפחים וכו'. אין דברים אלו השגה על רבינו שדרך רבינו בספר הזה להעתיק הדברים מהמשנה והתוספתא והגמרא לא לפרשה שכן קראו חיבור לא פירוש כ\\\"ש שמתוך דבריו נעמוד על פירושן כי אין ספק דבשוכב מיירי דזקוף לא מיקרי מוטל אלא עומד גם סתם עמוד אינו חלול אלא אטום ולטמא מה שתחת דופנו מכאן ומכאן מבחוץ ולא משכחת שיהיה לו אהל טפח אא\\\"כ היקפו כ\\\"ד טפחים שנמצא רחבו שמונה טפחים שכל שיש ברחבו טפח יש בהיקפו ג' טפחים ונמצא שיכול אדם לרבע תחת דפנו שמכאן ומכאן טפח על טפח ברום טפח שהרי כשיש כאן ריבוע של ח' על ח' אם תעשה בתוכו אהל של ח' נמצאו הזויות עודפים ח' חומשים לכל קרן דכל אמתא בריבוע' אמתא ותרי חומשי באלכסונה נמצא האלכסון עודף על הרוחב י\\\"ו חומשים תן מהם מחצה לקרן זה ומחצה לקרן זה הרי לכל אחד ח' חומשים ואם באת לעשות בקרן שחוץ לעיגול ריבוע של טפח על טפח נמצא אלכסונו עודף על רחבו שני חומשים ונמצא מדת אלכסונו ז' חומשים לא נשתייר לנו יותר על הצורך אלא חומש אחד ומשום חומש אחד לא דק ועוד דכל אמתא בריבועה אמתא ותרי חומשי אינו מכוון לגמרי שחסר מתוכו מעט ואע\\\"פ שסמוך לארץ אין בו טפח על טפח מ\\\"מ חשיב כשיפועי אהלים:\",5,0],[8,374,13,1,\"כל טפח על טפח ברום טפח קרוי אהל וכו'. כיצד אחד חור שחררוהו מים וכו'. פרק י\\\"ג דאהלות:\",1,0],[8,374,13,2,\"בד\\\"א שהיה האהל חזק ובריא וכו' כיצד שריגי האילנות וכו'. בפ\\\"ח דאהלות בכלל המביאים את הטומאה וחוצצין בפני הטומאה הסככות והפרעות שהם יכולים לקבל וכו' מעזיבה בינונית אלו הן הסככות אילן שהוא מיסך על הארץ ופרעות היוצאות מן הגדר.\",1,0],[8,374,13,2,\"ומ״ש ואם אינם ראויים לקבל מעזיבה בינונית הרי אלו מביאים מדבריהם ואינם חוצצין. בפרק תינוקת (נדה דף ס״ח ע״ב) אמרו סככות ופרעות מדאורייתא אהל מעליא בעינן ורבנן הוא דגזרו וגם בפרק דם הנדה ובפ״ק דמ״ק (דף ה' ע״ב) מוכיח דסככות ופרעות הוו דרבנן וסובר רבינו דע״כ מתניתין דקתני מביאין וחוצצין אהל דאורייתא הוה דאי מדרבנן בשלמא מביאין דהוי חומרא ניחא אלא חוצצין דהוי קולא איך יקלו חכמים לטהר מה שהוא טמא מן התורה ועוד שכל אותם השנויים במשנה אהל מדאורייתא וא״כ כשיכולים לקבל מעזיבה בינונית הוי אהל דאורייתא וההיא דנדה דקאמר שהם דרבנן היינו באין יכולים לקבל מעזיבה בינונית שאינו אהל מאחר שהוא רעוע אלא חכמים גזרו בו לחומרא דהיינו להביא אבל לא לחוץ בפני הטומאה ופי' אם יכולים לקבל מעזיבה בינונית לדעת רבינו היינו שהוא חזק ויש בו כח לקבל מעזיבה לא קלה ולא כבדה אלא ממוצעת בין הכבדות והקלות ואם אינם יכולים היינו שהם רעועים ואין בהם כח לקבל בינונית שאפילו שהם יכולים לקבל רכה דהיינו קלה לאו כלום הוא וז״ש רבינו יכולים לקבל והם עומדים ואם אינם וכו' והם נופלים וכן כתב בפירוש המשנה:\",2,0],[8,374,13,2,\"כתב הראב\\\"ד ואם אינן ראויים לקבל מעזיבה בינונית א\\\"א קשה לי מאי דאמרינן בתוספתא וכו'. כוונת הראב\\\"ד פה להקשות על רבינו שכתב שהטעם שצריך שיהיו מקבלים מעזיבה בינונית הוא מפני שהאהל שמביא וחוצץ צריך שיהיה חזק ובריא והרי אמרו בתוספתא שאע\\\"פ שהתרפו דהיינו שנתקלקלו והרקיבו רואים אותן כאילו הן של מתכת. וכן שנינו שעוף ששיכן מביא וחוצץ ולכך העלה שאין הטעם מפני שצריך שיהא אהל בריא וחזק אלא שיהיו דבוקות ולא יהיו מובדלות זו מזו שאם היו דבוקות אע\\\"פ שנתקלקלו והרקיבו ואין בהם כח לקבל מעזיבה רואין אותן כאילו הן של מתכת ולדעת רבינו י\\\"ל דההיא דהתרפו ל\\\"ק דהתם מיירי להביא טומאה מדבריהם וההיא דעוף ששיכן דמיתניא גבי הנך שמביאין וחוצצין י\\\"ל דאה\\\"נ שצריך שיהיה ראוי לקבל מעזיבה בינונית ולא תיקשי לן עוף מי מקבל שום מעזיבה שיש עופות גדולים שהם ראויים לקבל ועי\\\"ל שרבינו כתב בפירוש המשנה דאיירי בעוף קשור בכותל דהשתא מקבל הוא מעזיבה:\",3,0],[8,374,13,6,\"אלו מביאין וחוצצין וכו' עד כבש כנף הטלית באבן הרי זו מביאה את הטומאה. בפ\\\"ח דאהלות.\",1,0],[8,374,13,6,\"ומה שכתב הבאים במדה. נתבאר בפרק ו'. כתב רבינו שמשון ד' ירקות במחוברים איירי דומיא דסיפא דאי בתלושין אי הוכשרו לא חייצי ואי לא הוכשרו היינו אוכלים טהורים וכ\\\"כ בתוספות פ\\\"ק דסוכה (דף י\\\"ג ע\\\"ב) בד\\\"ה ירקות:\",2,0],[8,374,13,6,\"כתב הראב\\\"ד ופשוטי כלי עור א\\\"א זו היא סקורטיא וקטבליא:\",3,0],[8,374,13,6,\"ועל מ\\\"ש רבינו ורחיים של יד שהרי היא בכלל כלי אבנים: כתב הראב\\\"ד כלי אבנים כל אלו מביאין ואין חוצצין א\\\"א אולי סובר זה המחבר שאין שום כלי חוצץ בפני הטומאה וכו'. כתב שסובר כן רבינו ממ\\\"ש גבי המביאים וחוצצין כלי אבנים כלי גללים כלי אדמה הבאים במדה משמע שאם אינם באים במדה אינן חוצצין וגבי מביאין ולא חוצצין כתב ורחיים של יד שהרי הוא בכלל כלי אבנים משמע בהדיא שסובר דאפי' כלי גללים וכלי אבנים וכלי אדמה אינם חוצצין אם אינם באים במדה ורבינו אינו סובר חילוק זה שחילק הראב\\\"ד שהרי בפי' המשנה דאהלות פ\\\"ח גבי הא דתנן דרחיים של אדם [שהוא רחיים של יד] מביא ואינו חוצץ כתב שהוא ג\\\"כ אם היה על ארובה שבין בית לעליה או בחלון שבין ב' בתים שהוא אינו חוצץ אם לא שם אותו כמו אבן האבנים שהם חוצצין לפי שמתנאי הדברים החוצצים שלא יהיה דעתו לפנותו. ולענין מ\\\"ש הראב\\\"ד שלא אמרו אלא שלא נעשה אהל ולא מעמיד אהל אבל בחור או בחלון שבין בית לבית וכו'. י\\\"ל שרבינו סובר שמאחר ששנינו שאפילו כלי גללים מביאים ולא חוצצין בכל גווני משמע שאינם חוצצין אפילו בחור או בחלון שבין בית לבית וכ\\\"כ הוא ז\\\"ל בפירוש המשנה פ\\\"ו דאהלות ויש קצת סעד לפירושו ממה שמנו בכלל המביאים ואינם חוצצים ריחיים של אדם שאלו יותר ראויים לחוץ בין בית לבית מלהיות אהל:\",4,0],[8,374,13,6,\"ומ\\\"ש והוא שיהיה ראש זו בין רגלי זו ויהיו כלן דבוקות. ז\\\"ל רבינו בפי' המשנה [בתנאי] שיהי' ראש כל בהמה בין רגלי האחרת ויתחברו כולן ויהיו עומדות ולא הולכות וכן נתבאר בתוספתא עכ\\\"ל:\",5,0],[8,374,13,6,\"ומ\\\"ש גבי מביאין ולא חוצצין האדם. בפ\\\"ו דאהלות אדם וכלים נעשים אהלים לטמא אבל לא לטהר:\",6,0],[8,374,13,7,\"נסר שהוא צף על פני המים וכו'. תוספתא פ\\\"ט דאהלות:\",1,0],[8,374,13,8,\"אלו חוצצין ולא מביאין וכו'. משנה בפ\\\"ח דאהלות:\",1,0],[8,374,13,8,\"כתב הראב\\\"ד וחבילי מטה והמשפלות א\\\"א מרזבלין:\",2,0],[8,374,14,1,\"אין טומאה נכנסת לאהל וכו' בד\\\"א בחלון שעשה אותו האדם לתשמיש וכו'. בפרק י\\\"ג דאהלות.\",1,0],[8,374,14,1,\"ומה שכתב שיעורו כפונדיון. לשון המשנה שיעורו מלא מקדח גדול של לשכה ובפי\\\"ז דכלים תנן דהיינו כפונדיון האיטלקי.\",2,0],[8,374,14,1,\"ומ\\\"ש וחלון העשוי לאורה הוא שאין עליו תקרה וכו'. זה הוא פי' רבינו במה ששנינו בפרק י\\\"ג חלון שהוא לאויר שיעורו מלא מקדח:\",3,0],[8,374,14,2,\"חלון הנעשה שלא בידי אדם וכו'. בפרק י\\\"ג דאהלות.\",1,0],[8,374,14,2,\"ומה שכתב והוא כראש גדול של אדם. בפרק י\\\"ז דכלים.\",2,0],[8,374,14,2,\"ומה שכתב או שהיה חלון פקוק ונטל הפקק או שהיתה בו זכוכית ונשברה. תוספתא דאהלות פרק י\\\"ד.\",3,0],[8,374,14,2,\"ומה שכתב והוא שלא חשב עליו לתשמיש וכו'. בפרק י\\\"ג דאהלות:\",4,0],[8,374,14,3,\"מאור שהתחיל לסתמו וכו'. גם זה שם.\",1,0],[8,374,14,3,\"ומה שכתב מפני שלא היה לו טיט לגומרו או שקראו חבירו או שחשכה לילי שבת. פי\\\"ד דתוספתא דאהלות:\",2,0],[8,374,14,4,\"חלון גדול העשוי לאורה וכו'. בפרק י\\\"ג דאהלות שנינו הסריגות והרפפות מצטרפות כמלא מקדח כדברי ב\\\"ש וב\\\"ה אומרים עד שיהא במקום אחד מלא מקדח:\",1,0],[8,374,14,4,\"וכן חלון העשויה לתשמיש ובה סככות ורפפות וכו'. נלמד מהדין הקודם:\",2,0],[8,374,14,5,\"חלון שהיא גלויה לאויר וכו' עד מפני שהוא גלוי לאויר. פי\\\"ג דאהלות שם:\",1,0],[8,374,14,6,\"החור שבדלת וכו' עד הרי הוא כסתום. שם וכר\\\"ע:\",1,0],[8,374,14,7,\"ומ\\\"ש העושה חור בכותל. שם העושה מקום לקנה ולאספתי ולנר שיעורו כל שהוא כדברי בית שמאי בית הלל אומרים בפותח טפח לזון את עיניו ולדבר עם חבירו ולתשמיש בפותח טפח ופירש שם רבינו יאמר שמי שניקב בכותל נקב עובר להגביה בו קנה לענין מה או מסמר ינעול בו הפתח הוא אשר יקרא אספתי וכו' או לשום שם כלי ישימו עליו נר או להשקיף ממנו מי שילך מביתו או לקרות ממנו מי שירצה הנה שיעור זה הנקב פותח טפח עכ\\\"ל:\",1,0],[8,374,14,7,\"וכתב הראב\\\"ד העושה מקום בכותל וכו'. א\\\"א זה עשה פירוש לאספתי ששנינו וכו'. מה שתמה על פי' הרב היוני נתיישב בדברי רבינו שמשון שפירש קנה של גרדי אספתי חרב ויש לאורגים כלי שנקרא חרב עכ\\\"ל. ומה שהקשה על פי' רבינו למה הוציאו בלשון אספתי י\\\"ל שמפני שהמסמר שעושין לנעול בו הפתח הוא משונה משאר מסמרים בעביו ואפשר שגם בתבניתו הוא משונה ייחדו לו שם אחר ולפי' הראב\\\"ד ניחא שכל שלשת הדברים הם מיוחדים למנורה וגם כי כתב ר\\\"ש שי\\\"ג במשנה עצמה לאצבתי אבל איני יודע מה ענין לקנה מנורה בחור שבכותל הלא במנורה עצמה הם מונחים:\",2,0],[8,374,15,1,\"חלון תשמיש שסתמה וכו'. בפי״ג ממס' אהלות אלו ממעטים את הטפח וכו' ואלו שאינם ממעטים וכו' ובפרק לא יחפור (בבא בתרא דף כ') מוכח דתרתי בעינן שלא יהא מקבל טומאה ושלא יהא דעתו לפנותו.\",1,0],[8,374,15,1,\"ומ\\\"ש לפיכך אם סתם החלון או מיעטו באוכלים שאינם מוכשרים וכו' עד וכן כל כיוצא בזה. שם:\",2,0],[8,374,15,2,\"ומ״ש חבית שהיא מליאה גרוגרות וכו' עד ואם לאו אינם חוצצין. בפ״ו דאהלות ונתבאר בפרק לא יחפור (בבא בתרא דף י״ט).\",1,0],[8,374,15,2,\"ומ\\\"ש עשבים המרים וכו' עד שהרי הם ראויים ומקבלים טומאה. גם זה שם:\",2,0],[8,374,15,2,\"כתב הראב\\\"ד או סתמה עד שנשאר בה פחות מטפח א\\\"א פחות מטפח לכזית מן המת וכו'. ואין זה השגה על רבינו דלישנא דמתניתין דפי\\\"ג דאהלות נקט דקתני אלו ממעטין את הטפח וסמך התנא על מה ששנה בפ\\\"ד דאהלות כזית מן המת פתחו בטפח והמת פתחו בד' טפחים וגם רבינו סמך על מ\\\"ש כן בפ\\\"ז:\",3,0],[8,374,15,3,\"מיעט את הטפח בפחות מכזית וכו'. בפי\\\"ג דאהלות:\",1,0],[8,374,15,4,\"סתם החלון בכלי חרש וכו'. פ' לא יחפור שם.\",1,0],[8,374,15,4,\"ומ\\\"ש וצ\\\"ל כלי חרש זה מאוס ונקוב וכו'. נלמד שם מהסוגיא:\",2,0],[8,374,15,4,\"ועל מ\\\"ש רבינו מפני שאינם ראויים למלאכה: כתב הראב\\\"ד א\\\"א דוקא למעט בחלון וכו'. כן הכריחו התוס' בפרק לא יחפור עלה כ' ואין כן דעת רבינו שהרי כתב בפירוש אם סתם החלון או מיעטו:\",3,0],[8,374,15,4,\"ועל מ\\\"ש רבינו וכן פחות מכביצה אוכלים שאינם מוכשרים וכו': כתב הראב\\\"ד אומר אני דלחלון שהוא ד' על ד' וכו'. אין דבריו מוכרחים והר\\\"י קורקוס ז\\\"ל כתב על דבריו בשום מקום לא מצאתי שהוזכר שיעור ד' להביא טומאה רק להוציא ולהציל על שאר הפתחים ואם כוונתו כאן בחלון ד' ובא למעטו עד שלא ישאר טפח כי אז חשוב ואינו מתמעט עד שיבטל המיעוט ואותו נקרא חלון והיינו כל הנהו דלא יחפור דחלון הוזכר שם אבל טפח חור הוא ואין צריך לבטל המיעוט והיינו ההיא מתניתין דאהלות כי שם לא אמרו חלון אלא אלו ממעטים בטפח אם זאת כוונת הראב\\\"ד לא מצאתי מי שחילק בו ובתוס' אחלון טפח מפרשי ההיא דלא יחפור ורש\\\"י כתב בהדיא אם יש טפח בחלון בין בית לבית גם רבינו שמשון והרמב\\\"ם כך פירשוה וכולם חלון נקראים וכמו שכתב חלון שהוא לאויר שיעורו כמלא מקדח לתשמיש שיעורו בטפח ולא מצאתי מקום מאין חילק כן עכ\\\"ל:\",4,0],[8,374,15,5,\"היה בבית מת וכו'. עד סוף הפרק. בפי\\\"ג דאהלות שם וכחכמים:\",1,0],[8,374,15,5,\"ועל מ\\\"ש רבינו או נתמעט בקורי עכביש. כתב הראב\\\"ד א\\\"א זה במקום הכבי שאין בה ממש עכ\\\"ל. ופשוט הוא שזו היתה כוונתו ואע\\\"פ שלשון כבי נאמר בפרק י\\\"ז דכלים על מה שנמצא בתוך שפופרת של קנה לפי שאין דרך לשום בחלון מה שבתוך הקנה ועוד דלא שייך למימר בה שאין בה ממש לכך פירש רבינו שהוא קורי עכביש שדרכן להמצא בחלונות והם דומים ליריעה לבנה שבתוך הקנה ויש מהם דקים יותר מחוט ריר תולעת המשי וזהו שאין בו ממש:\",2,0],[8,374,16,1,\"ארובה שהיא באמצע תקרת הבית וכו'. משנה רפ\\\"י דאהלות (משנה א').\",1,0],[8,374,16,1,\"ועל מ\\\"ש כנגד ארובה טהור, מ\\\"כ ואע\\\"פ שאין בארובה פותח טפח לא אמרינן דהוי כלבוד דשאני טומאה דהכי גמירי לה.\",2,0],[8,374,16,1,\"ומ\\\"ש אם יש בטומאה כדי שתתחלק וכו'. שם כרבי יוסי ויש כאן חסרון בספרי הדפוס וכך היא הנוסחא הנכונה אם יש בטומאה כדי שתתחלק וימצא כשיעור תחת התקרה וכשיעור תחת ארובה הכל טמא ואם לאו הבית טמא וכנגד הארובה טהור.\",3,0],[8,374,16,1,\"ועל מ\\\"ש רבינו אם היה בארובה פותח טפח וכו' וכנגד כל הארובה טמא: כתב הראב\\\"ד א\\\"א כמדומה אני שיש כאן שיבוש וכו'. ודבר פשוט הוא ונ\\\"ל שודאי יש כאן ט\\\"ס וצריך לכתוב וכנגד הטומאה במקום וכנגד כל הארובה. ויש ליישב הגירסא בדוחק דה\\\"ק אם יש בארובה פותח טפח המאהיל על מקצת הטומאה כמאהיל על כולה:\",4,0],[8,374,16,1,\"היה בארובה פותח טפח ונתן אדם רגלו מלמעלה וכו'.\",5,0],[8,374,16,1,\"שם ומ\\\"ש אין בארובה פותח טפח וכו' עד ואין טומאה יוצאת לו. גם זה שם וכחכמים ויש פה בספרי הדפוס חסרון וכך הגירסא הנכונה היתה הטומאה תחת הארובה אם טומאה קדמה את רגלו טמא שהרי האהיל על הטומאה אם רגלו קדמה את הטומאה טהור שהרי רגלו מקצת האהל. וביאור הדבר דבסיפא חשיב כסתום כיון שנסתם קודם שבאה הטומאה אבל אם קדמה הטומאה כשפשט רגלו שם נטמא קודם שסתם הנקב:\",6,0],[8,374,16,2,\"היה כזית מן המת בפי העורב וכו'. תוספתא בפרק י\\\"א דאהלות וכת\\\"ק ואע\\\"פ שכבר נתבאר שאפילו טומאה למטה כל שהיא כנגד ארובה הבית טהור הכא שאני כיון שהאהיל כנגד ארובה נטמא הכל כי נתערבה הטומאה משא\\\"כ שם שאין שום אהל כנגד ארובה לערב הטומאה:\",1,0],[8,374,16,3,\"בית וארובה באמצע תקרת הבית וכו' עד אין טמא אלא הבית. משנה פרק י' דאהלות.\",1,0],[8,374,16,3,\"ומ\\\"ש הכל טמא שאין כלי טמא חוצץ. הוא על פי מה שנתבאר בפרק י\\\"ב ופי\\\"ז גבי אדם וכלים שנעשו אהל על הטומאה שאם היו כלים על גביו אפילו שלא כנגד הטומאה טמאים ואם היתה טומאה על גביו וכלים תחתיו כל כלים שתחתיו טמאים.\",2,0],[8,374,16,3,\"ומה שכתב גבי אין בארובות פותח טפח היתה הטומאה כנגד ארובות וכו' הבית והעלייה טמאים. בקדמה טומאה מיירי וכדדייק לישנא דהיתה טומאה שאם קדם הדבר שנתן לטומאה לא דומיא דמאי דכתב אם רגלו קדמה את הטומאה טהור.\",3,0],[8,374,16,3,\"ומ\\\"ש וכל אלו הדינין בעושה ארובה וכו' כמו שביארנו. בפי\\\"ד:\",4,0],[8,374,16,4,\"הפוחת את המעזיבה וכו'. בפי\\\"ב דאהלות סנדל של עריסה שפחתה בתוך הבית אם יש שם פותח טפח הכל טמא ואם לאו מונים בו כדרך שמונין במת ושינה רבינו לשון המשנה וכתב הפוחת את המעזיבה כלומר שאם נפחת' מאליה תניא בתוספת' ששיעורה מלא אגרוף וביאור המשנה כ' רבינו שם עריס' היא המטה מלשון ערשו ערש ברזל [סנדל של עריסה הוא דומה לעטרה של פתח אשר יעשה מברזל וזה שיעשה מברזל] טבעת יכניסו בו סנדל זה עד שהוא נראה בבית אם היה אותו הנקב טפח על טפח הכל טמא ר\\\"ל העלייה וכל הכלים שבה ואם לא היה באותו נקב טפח על טפח העלייה טהורה וזה הסנדל יטמא בהיותו מאהיל על הטומאה הוא והמטה שנוגעת בו טמאים טומאת ז' והתינוק טמא טומאת ערב דמיירי שהטומאה תחת הפתח וקדמה טומאה לסנדל וא\\\"ת כשאין בו פותח טפח למה עלייה טהורה מ\\\"ש ממה שנתבאר בפרק זה אין בארובות פותח טפח והיתה טומאה כנגד ארובות ונתן דבר שהוא מקבל טומאה העלייה והבית טמאים שהרי עירב הטומאה ותירץ הר\\\"י קורקוס ז\\\"ל שכל דבר שנכנס בעובי המעזיבה וממלא הפחת ויושב שם מהתקרה הוא חשיב ואין אומרים בו עירב את הטומאה ולפיכך דייק רבינו לכתוב והיתה רגל הערס סותמת את הארובה.\",1,0],[8,374,16,4,\"ומ\\\"ש נפחתה המעזיבה מאיליה וכו' כמו שביארנו. בפי\\\"ד:\",2,0],[8,374,16,5,\"ארובה שבתוך תקרת הבית וכו'. בפרק י' דאהלות ארובה שהיא בתוך הבית וקדרה נתונה תחתיה שאם תעלה ואין שפתותיה נוגעות בארובה טומאה תחתיה בתוכה או על גבה טומאה בוקעת ועולה בוקעת ויורדת פי' ארובה שהיא לאויר וקדרה נתונה תחתיה בארץ מכוונת כנגדה שאם תעלה וכו' כלומר שאינה רחבה יותר מהארובה עד שתהא מגעת אפילו כל שהוא בתקרה עד שלא תהא יכולה לצאת טומאה תחתיה רצוצה טומאה בוקעת ועולה בוקעת ויורדת כדין כל טומאה רצוצה אע\\\"ג דאין כלי חרש מיטמא מגבו הכא דטומאה בוקעת תוכה נמי טמא והוא הדין כשהטומאה בתוכה או על גבה דכיון דקי\\\"ל דכלים נעשין אהלים לטמא אבל לא לטהר רואין הטומאה כאילו היא תחתיה ובוקעת ועולה בוקעת ויורדת והבית טהור מאחר שאינה נוגעת אפילו כל שהוא בתקרה.\",1,0],[8,374,16,5,\"ומ\\\"ש היתה הקדרה גבוהה מן הארץ טפח וכו'. שם היתה גבוהה מן הארץ טפח טומאה תחתיה או בבית תחתיה והבית טמא תוכה וגבה טהור בתוכה או על גבה הכל טהור זו היא גירסת רבינו וה\\\"פ מאחר שהיא גבוהה מן הארץ טפח הוי שוליה וגג הבית אהל הילכך טומאה תחת אחת מהם תחת שניהן טמא תוכה וגבה טהור מפני שאינו תחת אהל ואם היתה הטומאה בתוכה או על גבה הכל טהור כלומר תחתיה והבית טהור שמאחר שהיא גבוהה מן הארץ טפח הצילה על כל מה שתחתיה כך פירוש המשנה לפי גירסת רבינו אבל קשה כשהיא גבוהה טפח וטומאה בתוכה או על גבה אמאי תחתיה והבית טהורים הא קי\\\"ל כלים אפילו כלי גללים שאין במינם קבלת טומאה נעשים אהלים לטמא אבל לא לטהר וא\\\"כ גם תחתיה והבית טמאים וכבר השיגו הראב\\\"ד וכתב שהגירסא הכל טמא וק\\\"ל דלדידיה מי ניחא מאי דקתני בגבוהה מן הארץ טפח טומאה תחתיה תוכה וגבה טהור הא מזה הטעם בעצמו היה להם להיות טמאים ואפשר דשאני הכא שאהל הכלי ואהל הבית כחד חשיבי הילכך לא מפלגינן בינייהו וכיון דאהל שתחת הכלי מיעוטא היא הוי טפילה לאהל הבית ודינו כמוהו. ומה שנתן רבינו טעם שאין כלי חרס מטמא מגבו היינו לומר דאילו היה מיטמא מגבו לא היה לו דין אהל כלל.\",2,0],[8,374,16,5,\"ומ\\\"ש היתה הטומאה בתוך הקדרה וכו': כתב הראב\\\"ד טומאה בוקעת ועולה בוקעת ויורדת א\\\"א לא יורדת עד התהום כטומא' רצוצה וכו'. וא\\\"ת תינח כשהיא בתוכה או על גבה אבל כשהטומאה תחתיה הרי היא רצוצה ולמה לא תרד עד התהום ודוחק לומר דלצדדין קתני ואפשר דכיון דקי\\\"ל דאין כלי טמא חוצץ אעפ\\\"י שהטומאה תחתיה הוה ליה כאילו היא מגולה:\",3,0],[8,374,16,5,\"ועל מ\\\"ש רבינו היתה הקדרה גבוהה מן הארץ טפח וכו' היתה טומאה בתוכה או על גבה הבית כולו טהור. כתב הראב\\\"ד א\\\"א זה המחבר משבש המשנה מדעתו וכו'. אני אומר שגירסת רבינו במשנה היתה בתוכה או על גבה הכל טהור ולענין מה שהקשה הרב ר' אברהם בן דוד שהעיקר הוא הכל טמא לפי שהוא כלי טמא ואינו חוצץ ובוקעת הטומאה לתחתיה ואינו חוצץ רבינו בפירוש המשנה כתב שטעם שהבית טהור לפי שהטומאה כנגד ארובה וכן תחת הקדרה טהור לפי שהיא אהל להיותה גבוהה טפח אמנם יטמא כנגד הטומאה לבד עד לרקיע וכן מוכיח בתוספתא שאמרו בה כנגדו עד לרקיע טמא משמע שהשאר טהור ומכ\\\"מ קשה שמאחר שאפילו כלי גללים נעשה אהלים לטמא אבל לא לטהר לא עדיפא קדרה מינייהו וצ\\\"ע:\",4,0],[8,374,16,5,\"היתה הקדרה תחת הארובה וכו'. תוספתא דאהלות פרק י\\\"א:\",5,0],[8,374,16,5,\"היתה הקדרה מונחת בצד אסקופת הבית כו' עד אבל הבית טהור. משנה סוף פ\\\"י דאהלות היתה נתונה בצד האסקופה שאם תעלה והיא נוגעת בשקוף פותח טפח טומאה תחתיה או בתוכה או על גבה טומאה בוקעת ועולה בוקעת ויורדת היתה גבוהה מן הארץ טפח טומאה תחתיה או בבית תחתיה והבית טמא תוכה וגבה טהור תוכה או על גבה הכל טמא. שאם תעלה אינה נוגעת בשקוף פותח טפח או מודבקת בשקוף טומאה תחתיה אין טמא אלא תחתיה ומצאתי בפירוש משניות מוגה שכתב שם רבינו ז\\\"ל אסקופה שם המשקוף התחתון והוא גבוה מהארץ מעט ושקוף שם המשקוף העליון הנכחי אליו והוא אשר נקרא בלשון הכתוב משקוף וענין אמרו שאם תעלה נוגעת בשקוף פותח טפח שאילו חשבנו שהוגבהה ביושר יהיה מפי הכלי פותח טפח נכנס תחת השקוף וכשתהיה ההנחה והיא דבקה בארץ באי זה מקום שתהיה הטומאה מזה הכלי יטמא מה שהיא נכחי לטומאה לבד לפי שהטומאה לא הראתה פעולתה באהל כפי מה שהקדמנו אולם אם היתה גבוהה טפח הנה היא תאהיל ויטמא הבית מסבת פותח טפח אשר ממנה נכנס תחת המשקוף העליון הנכחי אליו וכן אם היתה טומאה בתוכה או על גבה תחתיה טמא לפי שהבית יטמא להגעת הטומאה תחת השקוף ותצא טומאה מהבית אל תחת הקדרה להיותה נכחית בטפח לתחת המשקוף ויטמא תחת הקדרה ג\\\"כ והוא אמרו הכל טמא ואם היה זה הכלי אין ממנו תחת המשקוף אלא פחות מטפח או תהיה נכחית לשטח המשקוף מבחוץ עד שאילו עלתה ביושר ידבק צדה בצד השקוף וזהו אומרו או מודבקת לשקוף הנה היא אז אין חיבור בינה ובין הבית ויהיה דינה דין אהל בפני עצמו עכ\\\"ל. ורישא קשיא שאם תעלה והיא נוגעת בשקוף פותח טפח למה לא יטמא הבית כיון שהשקוף מאהיל על הטומאה וצ\\\"ל דמיירי כשאין הטומאה נכחית לשקוף אלא נכחית לאויר וה\\\"ר עובדיה פירש בענין אחר:\",6,0],[8,374,16,5,\"ועל מ\\\"ש רבינו היתה גבוהה מן הארץ טפח וכו' ותוכה וגבה טהור וכו'. כתב הראב\\\"ד א\\\"א זה האיש מפרש במקומות שאין להם צורך וכו' ואומר אני שזאת הקדרה צרה מפיה ויש לה כוליא טפח וכו'. באמת דברי הראב\\\"ד נכונים ושפתים ישק וכן פירש ר\\\"ש והרא\\\"ש ומכ\\\"מ אין זה תפיסה על רבינו מפני שרבינו בספר הזה מחבר לא מפרש וכתבו הר\\\"ש והרא\\\"ש בוקעת ועולה והבית טהור וכגון שהטומאה מן המשקוף ולחוץ דאי בטפח המשוך לפניה היה הבית טמא תוכה וגבה טהור דנצולת עם דופן הבית:\",7,0],[8,374,16,6,\"קורות הבית והעליה וכו'. משנה פרק י\\\"ב דאהלות:\",1,0],[8,374,16,6,\"ועל מ\\\"ש רבינו וביניהם פותח טפח. כתב הראב\\\"ד א\\\"א אע\\\"פ שאין ביניהם אויר טפח וכו'. נראה מדבריו שהבין בדברי רבינו שמ\\\"ש וביניהם אויר פותח טפח באויר שבין קורה לקורה שבצדה מיירי ומפני כך הקשה עלה שמה צורך שיהיה באויר פותח טפח אפילו אין באויר פותח טפח אין הטומאה עוברת מקורה לקורה הואיל ויש שם אויר ולי נראה שזה דבר פשוט ולא דיבר רבינו אלא באויר שבין קורה לקורה שעליה מיירי ומשום דבעי למיתנא היתה הטומאה בין התחתונה לעליונה בין שתיהם בלבד טמא הקדים לומר דהיינו דוקא כשיש בין תחתונה לעליונה פותח טפח שאילו לא היה ביניהם פותח טפח היתה טומאה בוקעת ועולה ולא היתה מטמאה אלא כנגדה בלבד:\",2,0],[8,374,16,6,\"ועל מ\\\"ש רבינו גבי היו הקורות העליונות מכוונות כנגד האויר שבין קורות התחתונות היתה הטומאה ע\\\"ג קורה העליונה כנגד הטומאה עד לרקיע טמא: כתב הראב\\\"ד א\\\"א וכן על גבי קורה התחתונה עכ\\\"ל. והדין עמו שמאחר שאחד התחתונה ואחד העליונה הן לאויר כך לי שהיתה הטומאה על התחתונה כמו שהיתה על העליונה וכך הוא לשון המשנה היו העליונות כבין התחתונות וטומאה תחת אחת מהן תחת כולן טמא על גביהן כנגדו עד הרקיע טמא ולא חילקנו בין שתהיה על גבי העליונה לשתהיה ע\\\"ג התחתונה ורבינו דנקט ע\\\"ג קורה העליונה צ\\\"ל דל\\\"ד אלא איידי דנקט בבבא קמייתא ע\\\"ג העליונה נקטה נמי הכא:\",3,0],[8,374,16,6,\"ומ\\\"ש אין בקורות פותח טפח וכו'. תוספתא פי\\\"ג דאהלות והוא נלמד ממתני' סוף פי\\\"ד דאהלות:\",4,0],[8,374,16,6,\"ועל מ\\\"ש רבינו לפי שכל טומאה שאינה תחת פותח טפח: כתב הראב\\\"ד א\\\"א כמה לשון זה מקולקל וכו'. וי\\\"ל דרבינו לישנא קלילא נקט וקיצר במקום שהיה לו להאריך ולומר דלא אמרינן חבוט רמי אלא כשיש בקורה רוחב טפח אלא שסמך על מ\\\"ש בפ\\\"ה מהלכות סוכה גבי היה הסיכוך מדובלל:\",5,0],[8,374,16,6,\"בית שנסדק וכו'. משנה פי\\\"א דאהלות.\",6,0],[8,374,16,6,\"ומ\\\"ש אם היה רוחב הסדק כחוט המשקולת. שם בה\\\"א כל שהוא ומפרש בתוספתא פרק י\\\"ב דהיינו כחוט המשקולת:\",7,0],[8,374,16,6,\"וכתב הראב\\\"ד א\\\"א כמה קלקל עלינו את הענין וכו' ובתוספתא כותל שנסדק והוא כותל הבית וכו'. כלומר מדלא פירשה כדמפרש רבינו מאי דתנן הבית שנסדק דהיינו גג וכותליו אלא לכותל לבדו שנסדק קרי במתניתין הבית שנסדק וע\\\"פ זה פירש השיעורים שבמתניתין לטומאה וכמו שמבואר בדבריו ודברי רבינו ופירושו מרווח בפי' דמתני' וכך פירשו רבינו שמשון והרא\\\"ש וז\\\"ל הרא\\\"ש בית שנסדק כגון שפתחו במזרח ואחוריו לצד מערב ונסדק כל גג הבית מצפון לדרום מעבר לעבר:\",8,0],[8,374,16,7,\"אכסדרה שנסדקה וטומאה בצד אחד וכו'. משנה פרק י\\\"א דאהלות פירוש כל אכסדרה היא פרוצה מרוח ד' וסתומה משלש רוחות ונסדקה התקרה מהרוח הפרוץ עד הכותל הפנימי מעבר לעבר הב'.\",1,0],[8,374,16,7,\"ועל מ\\\"ש רבינו עירב את הטומאה. כתב הראב\\\"ד א\\\"א כמה שיבושים נשתבש וכו'. דברי רבינו פשוטים וכך פירשוה הר\\\"ש והרא\\\"ש ואין דברי הראב\\\"ד מובנים לי ואפשר דלטעמיה אזיל שפירש שהסדק הוא בכותל לא בגג ומשיג על רבינו שכתב נתן רגלו וכו' למעלה על הסדק ועדיין דברי הראב\\\"ד צריכים עיון:\",2,0],[8,374,16,7,\"היה אדם מוטל על הארץ וכו'. שם וכב\\\"ה:\",3,0],[8,374,16,7,\"וכן אם היו תחת הסדק וכו'. גם זה שם:\",4,0],[8,374,17,1,\"זיז שהוא יוצא מפתח הבית וכו'. פי\\\"ד דאהלות הזיז מביא את הטומאה בכל שהוא הגיזרה והגבלית בפותח טפח איזהו הזיז שפניו למטה והגיזרה שפניה למעלה ובמה אמרו הזיז מביא את הטומאה בכל שהוא בזיז שהוא גבוה מן הפתח ג' נדבכין שהם י\\\"ב טפח יתר מכאן מביאה את הטומאה בפותח טפח העטרות והפיתוחים מביאים את הטומאה בפותח טפח וכו' זיז שע\\\"ג הפתח מביא את הטומאה בפותח טפח וכו' קנה שע\\\"ג הפתח אפילו מאה אמה מביא את הטומאה כל שהוא דברי רבי יהושע ר\\\"י בן נורי אומר אל יחמיר זה מן הזיז ופירש שם רבינו זה הזיז אשר יביא את הטומאה בכל שהוא כבר התבאר לך צורתו ותנאו וזה שיהיה לו תוספת אל מה שימשך לארץ ויהיה בינו ובין הארץ גבוה י\\\"ב טפחים והוא יוצא מצד פתח [הבית] ונחשוב זה הקנה הנוסף שהוא כבר הגיע לארץ וכלל הטומאה אשר תחתיו לצד הארץ וכו'. [זיז] שעל גבי הפתח ר\\\"ל שיהיה יוצא מהמשקוף ולהיותו למעלה מי\\\"ב טפחים יצטרך שיהיה בו פותח טפח ואז יביא את הטומאה לבית:\",1,0],[8,374,17,1,\"וכתב עוד אר' יהושע להיות הקנה משוך על אורכו ודבוק לכותל אע\\\"פ שהוא למעלה מי\\\"ב טפחים הנה הוא יביא את הטומאה לבית בכל שהוא ואמר ר\\\"י בן נורי שלא תהיה זו חמורה מהזיז אשר לא יביא את הטומאה כאשר היא למעלה מי\\\"ב טפחים אלא בפותח טפח כמו שקדם והלכה כר\\\"י בן נורי עכ\\\"ל:\",2,0],[8,374,17,1,\"והראב\\\"ד כתב על דברי רבינו כאן תמה אני איך הוא מוציא הדברים מפשטן וכו'. נראה מדבריו שהוא תמה על רבינו למה פסק כר\\\"י ב\\\"נ והו\\\"ל לפסוק כר' יהושע מפני שרבי סייע אותו דתניא בתוספתא רבי אומר החמירו בקנה יותר מבזיז שקנה מיטלטל וזיז אינו מיטלטל, ולדעת רבינו י\\\"ל שהוא סובר שרבי לא בא אלא ליתן טעם לדברי רבי יהושע ואפשר דליה לא ס\\\"ל ומאחר דמילתא דרבנן היא פסק כר\\\"י בן נורי דמיקל. ויש לתמוה על הראב\\\"ד למה קראו מוציא דברים מפשטן לפי שפסק כר\\\"י בן נורי וצ\\\"ל דמשום דאע\\\"פ שאפשר לומר דרבי לא בא אלא ליתן טעם לדברי ר' יהושע ואפשר דאיהו סבר כר\\\"י בן נורי פשטא דמילתא היא דכרבי יהושע ס\\\"ל לכך קראו מוציא הדברים מפשטן. ועטרות הם אבנים הבולטים מן הקיר כמין כיפה. ופיתוחים הם סיוד וכיור שעושים לנוי.\",3,0],[8,374,17,1,\"ומ״ש רבינו ודבר ברור הוא וכו'. בפ' מי שמתו (ברכות יט:) ד״ת אהל כל שיש בו חלל טפח חוצץ וכו' אין בו חלל טפח אינו חוצץ:\",4,0],[8,374,17,2,\"זיז שהוא סובב את כל הבית וכו'. בפרק י\\\"ד דאהלות זיז שהוא סובב את כל הבית ואוכל בפתח ג' אצבעות פירוש זיז שהוא רחב טפח וסובב כל כתלי הבית מבחוץ וכנגד הפתח אוכל שלש אצבעות ועל שאר הפתח אין זיז שאם היה אוכל כנגד הפתח טפח היה הבית טמא לד\\\"ה וידוע דהלכה כרבי יהושע. טומאה בבית כלים שתחתיו טמאים טומאה תחתיו ר\\\"א מטמא את הבית ורבי יהושע מטהר:\",1,0],[8,374,17,2,\"וכתב הראב\\\"ד טומאה תחתיו אינו מביא את הטומאה לבית א\\\"א דוקא בזיז שהוא למעלה מי\\\"ב טפחים עכ\\\"ל. כלומר שאילו לא היה למעלה מי\\\"ב טפחים היה מביא את הטומאה בכל שהוא כמו שנתבאר ופשוט הוא והטעם כשטומאה בבית כלים שתחתיו טמאים משום דדרך הטומאה לצאת.\",2,0],[8,374,17,2,\"ומ\\\"ש וכן בחצר שהיא מוקפת אכסדרה. שם במשנה פירוש כי כאשר היה הבית מוקף באכסדראות ואכסדרה אוכלת בפתח שלש אצבעות טומאה בבית כלים שבאכסדרה טמאים טומאה באכסדרה רבי יהושע מטהר הבית:\",3,0],[8,374,17,3,\"חלון העשויה לתשמיש וכו'. פי\\\"ד דאהלות.\",1,0],[8,374,17,3,\"ומ\\\"ש אפילו היה כרוחב אגודל. שם בתוספתא, ומ\\\"כ פי' אפילו לא היה לצד חוץ אלא גודל וכשהזיז אינו גבוה אלא רום אצבעיים עשוי לנוי החלון ומצטרף אהלו עם החלון.\",2,0],[8,374,17,3,\"ומ\\\"ש ואפי' גבוה כל שהוא: בניין היוצא לפני החלון וכו'. בפרק י\\\"ב דאהלות הבטח אינו מביא את הטומאה היה בו זיז ר\\\"א אומר אינו מביא את הטומאה [רבי יהושע אומר] רואין את הבטח כאילו אינו והזיז העליון מביא את הטומאה.\",3,0],[8,374,17,3,\"ומ\\\"ש היה בו זיז וכו'. שם וכרבי יהושע:\",4,0],[8,374,17,3,\"וכתב הראב\\\"ד א\\\"א זאת הפסקא לא נמצאת וכו'. וזה לשון רבינו בפירוש המשנה בטח הוא בניין היוצא מהכותל לפני החלון כי כאשר ישקיף מהארובה הוא נסמך עליו ולזה יקרא בטח וכתב הרא\\\"ש הטעם מפני שהוא מודבק לחלון ואין אויר שתכנס בו טומאה ורבינו שמשון בשם הערוך פירש בו פי' אחר:\",5,0],[8,374,17,3,\"וכיצד מביאין כל הזיזין האלו טומאה וכו'. פשוט הוא:\",6,0],[8,374,17,4,\"שני זיזין זה ע\\\"ג זה וכו' וכן שתי יריעות שהן גבוהות מן הארץ פותח טפח זו ע\\\"ג זו. פי\\\"ד דאהלות:\",1,0],[8,374,17,4,\"כתב הראב\\\"ד תחת התחתון תחתיו בלבד טמא א\\\"א חסר מכאן עיין המשנה עכ\\\"ל. ואני אומר ספר מוטעה נזדמן להראב\\\"ד בדברי רבינו ובנוסחא הנכונה אין שום חסרון וכך היא היה העליון עודף על התחתון פותח טפח וטומאה תחת התחתון או ביניהם תחתיהם וביניהן טמא היתה ע\\\"ג העליון כנגדו ועד הרקיע טמא היה העליון עודף על התחתון פחות מטפח וטומאה תחתיהם תחתיהם וביניהם טמא היתה הטומאה ביניהם או תחת המותר ביניהם ותחת המותר טמא אבל תחת התחתון טהור וזו הבבא האחרונה פלוגתא דר\\\"א ורבי יהושע וידוע דהלכה כרבי יהושע:\",2,0],[8,374,17,4,\"כתב עוד הראב\\\"ד תחתיו בלבד טמא א\\\"א הנוסחא נסוחא מן האחרת עכ\\\"ל. מכאן נראה שמ\\\"ש בהשגה שקודם זו חסר מכאן היינו שהיה בנוסחתו בדברי רבינו שני זיזין זה ע\\\"ג זה וכו' טומאה תחת העליון ביניהם בלבד טמא והשתא קאמר שמ\\\"ש בסיפא גבי יש בכל אחד מהן פותח טפח ואין ביניהן פותח טפח וטומאה תחת התחתון תחתיו בלבד טמא נוסחא זו נכונה מהאחרת כלומר מהנוסחא שכתב לעיל שיש בה חסרון. שנסוחא פירושה נכונה ואפשר דגרסינן נכוחה או נכונה:\",3,0],[8,374,17,4,\"ועל מ\\\"ש רבינו אין בהם פותח טפח וכו'. טומאה בוקעת ועולה בוקעת ויורדת שהרי היא רצוצה. כתב הראב\\\"ד א\\\"א זה הטעם שיבוש אלא שאין שם כדי שיביא את הטומאה לצדדין עכ\\\"ל. טעמו משום דלא מיקרי רצוצה אלא כשאין שם חלל גבוה טפח אבל הכא הרי יש שם חלל גבוה טפח אלא שלפי שאין בגגה רוחב טפח אינה מביאה את הטומאה לצדדין ולדברי רבינו י\\\"ל שמאחר שאין בגגה טפח על טפח על רום טפח טומאה בוקעת ועולה בוקעת ויורדת כל שחסר אחד מאלו דינה כרצוצה ושפיר מיקריא רצוצה:\",4,0],[8,374,17,4,\"כלים או בגדים וכו' עד מפני שהם כקרקע. פט\\\"ו דאהלות:\",5,0],[8,374,17,4,\"כתב הראב\\\"ד ומביא את הטומאה לכל הכלים שתחתיו ראיתי שלא פירשו לא הוא ולא הרב היוני וכו'. ואני אומר אין ספק שפירושו אמיתי ואין תפיסה על רבינו למה לא פירש שרבינו ז\\\"ל בספר הזה מחבר לא מפרש ויש כאן ט\\\"ס וצריך לכתוב של שיש במקום שלשתן. גם חסר בדפוס תיבת אלף וכך היא הנוסחא אפילו גבוהות מן הארץ אלף אמה וכן מבואר בתוספתא וטעם החילוק בין לוחות עץ לטבליות של שיש דשל עץ לא בטילי אגב קרקע וכמאן דליתנהו דמי ומקומם חשיב חלל אבל שיש כקרקע הוא חשיב שהרי מין קרקע הוא:\",6,0],[8,374,17,4,\"ועל מ\\\"ש רבינו אם היתה הטומאה גבוהה מן הארץ: כתב הראב\\\"ד זה שיבוש ראוי להיות אם היתה מן הארץ גבוה הכלי עכ\\\"ל. טעמו דאכלי או לוח העליון הוא דקפדינן שיהא גבוה מן הארץ טפח ולשון המשנה כך היא עד שתהא העליונה גבוה מן הארץ פותח טפח וא\\\"כ אפילו אין הטומאה גבוהה מן הארץ טפח אם הכלי או הלוח העליון גבוה מן הארץ טפח מביא את הטומאה וגם רבינו כתב כן בסוף פי\\\"ו ולכן צריך לומר שסמך כאן על מ\\\"ש שם וה\\\"פ אם היה הלוח או הכלי העליון שהטומאה מלמטה גבוה מן הארץ טפח:\",7,0],[8,374,17,5,\"לוחות של עץ שהן נוגעות זו בזו וכו'. שם טבליות של עץ שהן נוגעות זו בזו בקרנותיהם והם גבוהות מן הארץ פותח טפח טומאה תחת אחת מהן הנוגע בשניה טמא טומאת שבעה כלים שתחת הראשונה טמאים שתחת השניה טהורים ופירש רבינו הנוגע בשניה טמא טומאת שבעה לפי שהיא חלק מאהל המת וכלים שתחתיה טהורים לפי שלא יגיעו בינה ובין הטבלא אשר תחתיה הטומאה פותח טפח עד שתביא לה טומאה ואמנם ימשש זוית לזוית לבד עד כאן לשונו. וכתב ר\\\"ש הנוגע בשניה טמא טומאת שבעה ואע\\\"ג דתנן בריש מכילתין כלים הנוגעים במת וכלים בכלים טמאים [טומאת שבעה] והשלישי בין אדם בין כלים טמא טומאת ערב הא תנן התם אין האהל מתחשב הילכך טבלא שטומאה תחתיה אינו מן המנין עכ\\\"ל. ויש לתמוה על רבינו שכתב כאן והנוגע בלוח זו השניה כנוגע בכלים שנגעו באהל המת וע\\\"פ מה שנתבאר בפ\\\"ה מהלכות אלו אינו טמא אלא טומאת ערב ומתניתין קתני טמאים טומאת שבעה ואפשר דה\\\"ק הוי כנוגע בכלים שנגעו באהל המת בעודם מאהילים על המת דהוי בחיבורין דכה\\\"ג טמאים טומאת שבעה:\",1,0],[8,374,17,5,\"אבל כל הכלים שאמרנו שמביאין את הטומאה ואינם חוצצין וכו'. זה נלמד ממה ששנינו בריש פ\\\"ז דאהלות ובפרק ח':\",2,0],[8,374,17,6,\"חבית שהיא יושבת על שוליה באויר וכו' עד הכל טמא. פ\\\"ט דאהלות חבית שהיא יושבת על שוליה באויר וכזית מן המת נתון תחתיה או בתוכה כנגד קרקרותיה טומאה בוקעת ועולה בוקעת ויורדת והחבית טמאה תחת דפנה מבחוץ טומאה בוקעת ועולה בוקעת ויורדת והחבית טהורה בתוכה ותחת דפנה אם יש בדפנות פותח טפח הכל טמא וכנגד פיה טהור ואם לאו טומאה בוקעת ועולה בוקעת ויורדת פי' קרקרותיה שוליה המחודדים ואתחתיה קאי והוא הדין לזית נתון בתוכה או תחתיה כנגד קרקרותיה וחבית זו של חרס היא ולדעת רבינו רחבה שוה מלמעלה למטה כמו חביות שלנו וע\\\"פ הדברים האלה פירש שם וז\\\"ל אמרו כנגד קרקרותיה ירצה שתהיה הטומאה תחתיה ממה שימשך לחללה לא שתהיה תחת עובי הדפנות וכו' וכאשר היתה טומאה כנגד קרקרותיה אין לפי מה שהשרשנו שיהיה כל מה שהוא נכחי לטומאה מאויר החבית (ומעת שנטמא אוירה נעשית החבית) טמאה לא שכלי חרס יטמא מגבו אבל להיותו מטמא מאוירו וזאת החבית כבר נטמאה אוירה בזה המין מהטומאה אשר יטמא כל מה שיהיה נכחי אליו וכו' ואם היתה הטומאה תחת דפנה מבחוץ והוא שתהיה תחת עובי (החרס) [הגג] ולא יהיה ממנו כלל תחת שוליה ממה שימשך לאוירה הנה החבית טהורה שכלי חרס אינו מטמא מגבו והטומאה בעת שעברה למעלה לא תכנס באוירה לפי שהיא תחת הדופן. ואמרו בתוכה ותחת דפנה הוא שתהיה מקצת הטומאה תחת דפנה ומקצתה תחת שוליה לשון התוספתא כזית מן המת מקצתו נתון תחת דפנה ומקצתו נתון תחת קרקרותיה כל שכנגד הטומאה בין מלמעלה בין מלמטה טמא וכל שאינו כנגד הטומאה בין מלמעלה בין מלמטה טהור ואם יש בדפנה פותח טפח הכל טמא וענין הכל טמא שיהיה כל מה שיגע בחבית טמא ואפילו מה שלא יהיה נכחי לטומאה אבל בהיות עובי (חרסה) [גגה] טפח כבר התפשטה הטומאה בכולה ר\\\"ל כל מקיפה ולזה היה כנגד פיה טהור ר\\\"ל מה שימשך לאוירה לפי שהטומאה כבר התפשטה והראת פעולתה ברוב נכחיותה.\",1,0],[8,374,17,6,\"ומ\\\"ש רבינו בד\\\"א בחבית טהורה וכו'. במשנה הנזכרת ופי' שם רבינו אולם אם כבר נטמאת מקודם באחת הטומאות שיהיה כלי טמא וכלי טמא אינו חוצץ או אם יהיה גבוה על הארץ טפח שהוא אהל או יהיה הטומאה תוכה ועליה כיסוי שיהיה כמו קבר סתום או תהיה כפויה על הטומאה כל מה שיגע באחד מאלו הענינים טמא והוא אמרו הכל טמא ר\\\"ל תוכה וגבה ודפנה ובכלל כל מי שיגע בו [הטומאה הוא] טמא לסבה שזכרנו עכ\\\"ל:\",2,0],[8,374,17,6,\"כתב הראב\\\"ד או על גבה הכל טמא א\\\"א חסר מכאן ואומר אני שכן צריך לפרש לא הכל הכל ממש וכו'. טעמו במ\\\"ש חסר מכאן לומר שלא הוה ליה לרבינו לסתום ולכתוב הכל טמא אלא לפרש וכבר כתבתי שאין זה תפיסה על רבינו שאינו בספר הזה מפרש אלא מחבר ומכ\\\"מ מתוך לשונו של רבינו נראה לי שמה ששנינו הכל טמא לכל החלוקות קאי דבכל חלוקה מהם הנוגע בכ\\\"מ ממנה טמא מפני שהיא כקבר סתום וזה מבואר בלשונו בפי' המשנה שכתב שיהיה כמו קבר סתום ולזה נתכוון במ\\\"ש כאן וכל הנוגע בה כולו טמא:\",3,0],[8,374,17,6,\"היתה מוקפת צמיד פתיל וכו'. תוספתא דאהלות פ\\\"י ויש לתמוה אמאי לא אמרינן טומאה בוקעת ועולה בוקעת ויורדת ומטמאה כל מה שבתוכה וצ\\\"ע:\",4,0],[8,374,17,6,\"חביות שהן יושבות על שוליהן וכו'. משנה פט\\\"ו דאהלות ועיין בדברי רבינו בפי' המשנה ויש פה חסרון בספרי הדפוס וכך היא הנוסחא הנכונה טומאה בוקעת ועולה בוקעת ויורדת מפני שהיא רצוצה בד\\\"א בטהורות אבל אם היו טמאות או גבוהות מן הארץ טפח וטומאה תחת אחת מהן תחת כולן טמא שהרי הכל אהל אחד:\",5,0],[8,374,18,1,\"אדם שהאהיל בידו אחת וכו'. וכן שני בתים וכו'. בספט\\\"ו דאהלות והטעם על פי מה שקדם שהאדם שנטמא במת יטמא הכלים שנגע בהם אבל באהל אינו מטמא אותם שאין מטמא באהל אלא מת עצמו אבל אם בשעה שנוגע במת או מאהיל עליו מאהיל גם על הכלים בידו אם יש בה פותח טפח שהוא שיעור אהל להביא הטומאה הנה נטמאו מפני היותם עם המת תחת אהל אחד שהאדם נעשה אהל להביא את הטומאה:\",1,0],[8,374,18,2,\"אדם שהשקיף וכו' עד מביא ואינו חוצץ. פרק י\\\"א דאהלות וכב\\\"ה. ויש בספרי הדפוס ט\\\"ס בדברי רבינו שכתוב בצד החיצון וצריך למוחקו ולכתוב במקומו בעד החלון:\",1,0],[8,374,18,3,\"נושאי המת וכו'. פ\\\"ו דאהלות.\",1,0],[8,374,18,3,\"ומ\\\"ש וכן אם היה אדם מבפנים או מבחוץ וכו'. כ\\\"כ בפי' המשנה ופשוט הוא:\",2,0],[8,374,18,4,\"תנור שהוא עומד בתוך הבית וכו'. ריש פ\\\"ה דאהלות וכב\\\"ה דתנן תנור שהוא עומד בתוך הבית ועינו קמורה לחוץ והאהילו עליו קוברי המת בש\\\"א הכל טמא ובה\\\"א התנור טמא והבית טהור ר\\\"ע אומר הכל טהור ופי' רבינו עין התנור הוא הנקב אשר בשפלות מהארץ אשר ישליכו ממנו האש ומוציאים ממנו האפר. וקמורה מקובבת והוא שיהיה התנור כולו תחת הבית והנקב הקמור בולט לחוץ והאהילו נושאי המת במת על זה הקובב אמרו ב\\\"ש כבר נדבק האהל בזאת הקובב ונכנסה הטומאה לבית מעליוני התנור כמו אם היתה טומאה תחת זה הקובב ובה\\\"א שהתנור לבד הוא אשר יטמא כי האהיל המת על מקצתו ור\\\"ע אומר שהתנור טהור שאין האהל על עצם התנור אלא על הקובב היוצא ממנו ואין הלכה כר\\\"ע עכ\\\"ל. והרא\\\"ש כתב מיירי כשיש בעין טפח על טפח דאי לאו הכי אפילו טומאה בעין טהור התנור כדתנן פ\\\"ח דכלים בש\\\"א הכל טמא דחזינן לטומאה כאילו היא בתוך העין ויוצאה דרך פי התנור לבית וב\\\"ה לא מחמרי כולי האי להביא טומאה לבית אבל התנור טמא ורבינו שמשון פירש דבאין בעין פותח טפח איירי דאי יש בו פותח טפח למה לא תכנס לבית דלא דמי להני דאמרן בפירקין דאין דרך הטומאה ליכנס דהכא הרי נכנסת לתנור ולמה לא תכנס לבית דרך פתח פיו ועוד דגבי מגדל אוקימנא דלתותיו מגופות וכאן פיו של תנור פתוח ולא מסתבר כלל לחלק בין טומאה עוברת לטומאה עומדת אלא בדלית ליה פותח טפח איירי כן מוכח בתוספתא וסברי ב\\\"ש דנכנסת טומאה לכלי דרך נקב קטן וכו' וב\\\"ה סברי דנכנסת טומאה לכלי דרך נקב קטן ולא לטמא הבית עכ\\\"ל.\",1,0],[8,374,18,4,\"ומ\\\"ש רבינו שהרי אין התנור גבוה מעל הארץ וכו'. נראה לי מתוך דבריו שמפרש דמיירי שהתנור משוקע בקרקע הבית הילכך נמצא דלענין זה אינו אהל אחד עם הבית כדי שיביא לו טומאה שנכנסה לו דרך עינו. והראב\\\"ד כתב זה הטעם אינו כלום שב\\\"ש למה מטמאין את הכל וכו'. על מ\\\"ש הראב\\\"ד שהתוספתא מפרשא שאין התנור טמא אלא בעין גובה טפח ורחב טפח יש לתמוה שרבינו שמשון כתב דבתוספתא מוכח דבדלית בעין פותח טפח מיירי ונראה שהם חולקין בפירוש התוספתא דקתני אמר רבי יוסי בא רבי יוחנן בן נורי אצל רבי חלפתא א\\\"ל מה אתה [אומר] בעין של תנור א\\\"ל טמא א\\\"ל אף אני אומר כן אלא שעקיבא מטהר עין של תנור שיש בה גובה טפח ואין בה רוחב טפח [יש בה רוחב טפח] ואין בה גובה טפח טהורה. רבינו שמשון מפרש דברישא מיירי בעין של תנור דמתניתין ובסיפא מפרש דפלוגתייהו בדלית ביה פותח טפח דאילו הוה ביה פותח טפח מודה ר\\\"ע דטמא והראב\\\"ד מפרש סיפא דה\\\"ק ע\\\"כ לא פליגי אלא בדאית ליה פותח דאי לית ביה פותח מודו כ\\\"ע דטהור. ומ\\\"ש הראב\\\"ד בסוף דבריו ואם נתן על אויר העין נסר שהוא רחב וארוך וכו' הוא תוספתא ופירושה:\",2,0],[8,374,18,4,\"מגדל הבא במדה וכו' עד כלים שבתוכו טהורים. פ\\\"ד דאהלות כלשון רבינו והנה יש בספרי הדפוס חסרון בדברי רבינו וכך צריך לכתוב אצל מ\\\"ש ונפתח לחוץ טומאה בתוכו הבית טהור. והתנה במגדל הנזכר בפרק זה שיהא בא במדה דהיינו שיהא מחזיק מ' סאה שהם כוריים ביבש ולזה יהיה חוצץ בפני הטומאה אבל אם היה פחות מזה הנה הוא יקבל טומאה כשאר כלים המקבלים טומאה ולא יציל על כלים שבתוכו.\",3,0],[8,374,18,4,\"ומ\\\"ש שהוא עומד בתוך הפתח ונפתח לחוץ. מיירי שהמגדל ממלא כל הפתח ואין פותח טפח מכל צד למעלה ולמטה ומן הצדדין נמצא שאין מקום לצאת הילכך הטומאה בוקעת ויוצאת דרך דופני המגדל:\",4,0],[8,374,18,4,\"ומ\\\"ש היתה מוכני שלו וכו'. ז\\\"ל המשנה שם היתה מוכני שלו משוכה לאחריו ג' אצבעות טומאה שם כנגד הקורות הבית טהור בד\\\"א בזמן שיש שם פותח טפח ואינה יוצאת והמגדל בא במדה ופי' שם רבינו הגלגל שבזה המגדל יקרא מוכני והנה זה המוכני חוץ מאחורי המגדל בתוך הבית ג' אצבעות והטומאה באותם שלש אצבעות. ופירוש תחת הקורות שהטומאה במה שיוצא לחוץ שהוא תחת קורות הבית בד\\\"א בזמן שיש בה פותח וכו' כי מה שאנו אומרים שאין הטומאה יוצאה לבית לפי שאין המוכני יוצא אלא ג' אצבעות שהוא פחות מטפח ואנו צריכים הטומאה טפח ואמנם זה בג' תנאים התנאי האחד שיהיה שם פותח טפח כי לא הוצרכנו להבאת הטומאה טפח אלא בזמן שיהיה במקום הטומאה פותח טפח אבל כשאין שם פותח טפח יוצאה ובוקעת ואין צריך לטפח ועוד תנאי שני שזה המוכני לא יהיה יוצא מאחר המגדל לגמרי אלא שיהיה לו דבר שיהיה מונע אותו מלצאת טפח ועוד תנאי ג' שיהא בא במדה דהיינו שיחזיק מ' סאה בלח שהם כוריים ביבש:\",5,0],[8,374,18,4,\"ומ\\\"ש היה המגדל עומד בתוך הבית וכו'. פי' כי אמרינן טומאה בבית מה שבתוכו טהור מיירי בשדלת המגדל מוגף שהמגדל מציל וחוצץ לפי שאינו מקבל טומאה דכלי הבא במדה הוא וכשטומאה בתוכו הבית טמא אע\\\"ג שדלת המגדל מוגף לפי שדרך הטומאה לצאת וכיון שהיא בתוך הבית כל מה שבבית טמא אבל אם היה דלת המגדל פתוח אפילו בטומאה בבית טמא היה טמא מה שבתוך המגדל שהרי הטומאה במגדל דרך פתחו שהוא בתוך אהל הבית:\",6,0],[8,374,18,5,\"ומה שכתב כלים שבין המגדל ובין הארץ וכו'. פירוש אם יש טפח בין מגדל לכותל או בין גג מגדל לקורות או בין שולי המגדל לארץ הכלים טמאים מטומאת הבית שהטומאה נכנסת לכלים דרך הפתח וכשאין שם טפח המגדל חוצץ בפני הטומאה שלא תגיע לכלים כי כאשר היה זה המגדל בתוך הבית הנה הוא כמו בית בבית וכלים שבינו לבין הארץ ושבינו לבין הכותל לא יטמאו אם לא היה שם פותח טפח וכן בינו לבין הקורות ונוסחת התוס' שאנו רואים את הקורות כאילו יורדות וסותמות ד\\\"ה אין טומאה נכנסת לאהל ולא יוצאה ממנו בפחות מטפח ואמרו טומאה שם ר\\\"ל בין הכותל ואחורי מגדל או בין גג הבית וגג המגדל או בין קרקעית המגדל והארץ הנה הבית כולו טמא לפי שהטומאה בתוך הבית לא יציל עליה האהל שהשורש אצלנו אם היה אהל לתוך אהל והיתה טומאה תחת הפנימי החיצון טמא והוא מאמר התוספתא צמיד פתיל ואהלים מצילים על הטהורים מליטמא ואין מצילים על הטמאים מלטמא:\",1,0],[8,374,18,6,\"ומ\\\"ש היה עומד באויר וכו'. פירוש כלים שבעביו שיש חדרים עוברים בעביו בין שתי הלוחות:\",1,0],[8,374,18,6,\"כתב הראב\\\"ד כלים שבין המגדל וכו' אם יש שם פותח טפח כו' א\\\"א לא כל הענינים שוים וכו'. ואני אומר דברים נכונים הם ורבינו לא חשש לפרש מפני שדבר פשוט הוא ואין דרכו בספר זה כי אם להעתיק המשנה כלשונה:\",2,0],[8,374,18,7,\"כל שיפועי אהלים כאהלים וכו'. כאן יש בספרי רבינו חסרון הניכר והוא ט\\\"ס וכך היא הגירסא הנכונה כל שיפועי אהלים כאהלים כיצד אהל שהוא שופע ויורד וכלה עד כאצבע וטומאה באהל כלים שתחת השיפוע טמאים טומאה תחת השיפוע כלים שבאהל טמאים. הטומאה מתוך השיפוע הנוגע בו מתוכו טמא טומאת שבעה והנוגע בשיפוע מאחריו טמא טומאת ערב נעשה השיפוע מאחריו כאילו הוא כלי שנגע באהל היתה הטומאה על אחורי השיפוע הנוגע בו מאחוריו טמא טומאת שבעה והנוגע בשיפוע בתוכו טמא טומאת ערב כחצי זית מתוכו וכו'. ודינים אלו משנה פרק שביעי דאהלות פי' אע\\\"ג דקי\\\"ל דאין חשיב אהל להביא את הטומאה עד שיהא טפח על טפח ברום טפח מרובע לא בעינן שיהא בו טפח על טפח מכל צד אלא אהל משופע ויורד וכלה עד כאצבע הואיל ויש באמצעיתו טפח על טפח אף במקום שאין בו טפח על טפח אלא כאצבע חשיב אהל ומביא את הטומאה תחת כולה הואיל והוא אהל אחד ולשון המשנה אהל שהוא שופע ויורד וכלה עד כאצבע ופי' ר\\\"ש וכלה עד כאצבע למעלה לצד הגג אבל רבינו פירש שם ששופע וכלה לצד מטה ששם אינו אלא כאצבע ולישנא דמתניתין דייקא דקתני ויורד:\",1,0],[8,374,18,7,\"ומה שכתב הנוגע בו מתוכו טמא טומאת ז' וכו'. באהל של פשתן מיירי שהוא מקבל טומאה אע\\\"ג שהוא נטוי לאהל ותורת בית עליו לענין לחוץ בפני הטומאה וכיון שהוא מקבל טומאה וגם חוצץ בפני הטומאה אין ברו כתוכו הילכך צד פנימי וצד חיצון חשובים כשני כלים צד שכלפי הטומאה כנוגע במת וצד שני הוי ככלים בכלים הילכך הנוגע בו מתוכו אחר שפינה המת משם טמא טומאת ז' דהוה ליה כלים באדם ומאחריו טמא טומאת ערב דהוה ליה כלים בכלים ואדם בכלים וע\\\"כ צריך לפרש דמיירי אחר שפינה המת משם דאילו בעוד המת שם אפילו הנוגע מאחריו טמא טומאת ז' כדתנן אין האהל מתחשב כך פירש ר\\\"ש וע\\\"פ זה נפרש לדעת רבינו לענין השיפוע ומה שאחריו וק\\\"ל.\",2,0],[8,374,18,7,\"ומ\\\"ש כחצי זית מתוכו וכו'. כחצי זית מתוכו וכחצי זית מאחריו מצטרפין לטמא את האהל טומאת ז' כדתנן בפרק ט\\\"ז דאהלות כוש שהוא תחוב באהל וכחצי זית מתחתיו וכחצי זית מעל גביו אע\\\"פ שאינם מכוונים טמא אבל הנוגע בו בין מתוכו בין מאחריו אין בו אלא טומאת ערב כיון דליכא כזית בצד אחד א\\\"א לכל צד ליחשב אלא כלים בכלים:\",3,0],[8,374,18,7,\"וכתב הראב\\\"ד א\\\"א איני יודע מה ראה לפרש מתוכו מתוך השיפוע וכו'. ורבינו בפירוש המשנה נותן טעם לדבריו וכתב שהוצרך לפרש כן מפני ששנינו בתוספתא כחצי זית מתוכו כחצי זית מאחריו הנוגע בו בין מתוכו בין מאחריו טמא טומאת ערב ואמר על כל זה והאהל עצמו טמא טומאת ז' למדך בכאן שהדבור אמנם הוא על השיפוע עכ\\\"ל:\",4,0],[8,374,19,1,\"כוורת שהיא מוטלת בארץ וכו'. פ\\\"ט דאהלות בפרק זה קשה היאך כוורת חוצצת הרי נטמאת ואין כלי טמא חוצץ והראב\\\"ד העמידה בשל חרס שאינו מיטמא מגבו ורבינו העמידה במחזקת מ' סאה שכתב שם תחילת מה שתבין בזה הפרק שהדבור הוא בכוורת גדולה המחזקת מ' סאה או יותר אשר כבר קדם המאמר שהיא לא תטמא ושהיא חוצצת בפני הטומאה וכאשר תטמא יאמר הנה תוכה טמא או גבה טמא או הכל טמא לא תחשוב שענין זה הטמאות בעצמה אמנם זה ענין הטמאות הכלים אשר בתוכה או על גבה עכ\\\"ל. והילך לשון המשנה כוורת שהיא בתוך הפתח ופיה לחוץ וכזית מן המת נתון תחתיה או על גבה מבחוץ כל שהוא כנגד הזית תחתיה וגבה טמא וכל שאינו כנגד הזית תוכה והבית טהור בבית אין טמא אלא הבית בתוכה הכל טמא פירוש במוטה על צדה איירי ומקצתה בפנים ומקצתה בחוץ. וק\\\"ל על מה דתנן בנתון תחתיה או על גבה מבחוץ כל שהוא כנגד הזית תחתיה וגבה טמא דבשלמא כשהטומאה תחתיה שיהא גבה טמא ניחא דכיון שאינה גבוהה מהארץ טפח ה\\\"ל טומאה רצוצה ובוקעת ועולה אבל כשהטומא' על גבה למה תחזור הטומאה לירד למטה לטמא תחתיה הרי הכוורת חוצצת בפניה וי\\\"ל שלקמן בפרק זה אבאר דכלים אע\\\"פ שהם אינם מקבלים טומאה כשהטומאה תחתיהן או על גביהן נעשים אהלים לטמא אבל לא לטהר כמו שנתבאר בפי\\\"ב:\",1,0],[8,374,19,1,\"ועל מ\\\"ש רבינו וכל מה שבאויר תוכה טהור חוץ מכלי שהוא כנגד הטומאה והבית טהור. לישנא דמתניתין דייק דקתני וכל שאינו כנגד הזית תוכה והבית טהור דמשמע מינה דתוכה אינו טהור אלא מה שאינו כנגד הזית אבל קשה שמאחר שהטומאה בקעה ונכנסה לכוורת לטמא מה שכנגד הזית למה לא תתפשט הטומאה בכל הכוורת והל\\\"ל בתוכה טמא וגבה טהור דכיון שנכנסה הטומאה בכוורת שהוא אהל חוצץ הכוורת בפניה שלא תבקע ותעלה וי\\\"ל שמאחר שעצם הזית אינו בתוכה אינה מתפשטת בכל הכוורת וכן אינה מעכבת עליה מלבקוע ולעלות.\",2,0],[8,374,19,1,\"ומ\\\"ש היתה הטומאה בבית אין טמא אלא הבית. דכיון דפיה לחוץ אין הטומאה עוברת לכלים שבתוכה או על גבה מבחוץ וכן אינה עוברת לכלים שתחתיה מבחוץ כיון שאינה גבוהה מן הארץ טפח.\",3,0],[8,374,19,1,\"ומ\\\"ש בתוכה הכל טמא. מפני שהכוורת חללה בתוך הבית הרי הטומאה בתוך הבית ולא ימנענה הכוורת מלטמא הבית כמו שנתבאר בתוספתא שאין אהלים מצילים על הטמאים מלטמא וכמו שנתבאר פרק י\\\"ח גבי היתה הטומאה תחת המגדל ותחתיה ועל גבה טמאים כנגד הטומאה דכיון דאין כלי חוצץ בפני הטומאה רואים את הטומאה כאילו היא על גבה והא תנן ברישא דכשהטומאה על גבה מבחוץ כל שהוא כנגד הבית תחתיה וגבה טמא ופשיטא דהכא כשהטומא' חוץ לבית מיירי כמו ברישא ופשיטא נמי שמ\\\"ש כנגד הטומאה לא קאי אלא לכל שעל גבה וכל שתחתיה בלבד:\",4,0],[8,374,19,1,\"ועל מ\\\"ש רבינו היתה הטומאה בתוכה וכו' וכל שתחתיה כנגד הטומאה: כתב הראב\\\"ד זה שיבוש שאף מה שאינו כנגד הטומאה טמא וכו'. והשגה זו אינו אלא לפי מה שהעמיד הוא ז\\\"ל פרק זה בכוורת של חרש שאינה מטמאה מגבה אבל מתוכה טמאה היא אבל לרבינו שהעמידה בכוורת מחזקת מ' סאה שאינה מקבלת טומאה כלל והיא חוצצת ל\\\"ק מידי.\",5,0],[8,374,19,1,\"ומ\\\"ש רבינו היתה גבוהה מן הארץ טפח כו'. ז\\\"ל המשנה (פ\\\"ט מ\\\"ג) היתה גבוהה מן הארץ טפח טומאה תחתיה או בבית או על גבה הכל טמא אלא תוכה ובתוכה הכל טמא הטעם משום דכיון שהיא אהל על הארץ רואין אותה כאילו נתחברה עם גג הבית והיה הכל גג אחד הילכך טומאה תחתיה או בבית כל שתחתיה וכל שבבית פשיטא דטמא שהרי הטומאה והכלים תחת אהל אחד וכיון דקי\\\"ל דכלים נעשים אהלים לטמא אבל לא לטהר א\\\"כ כלים שע\\\"ג רואים אותם כאילו הם תחתיה ונמצא שהם והטומאה תחת אהל אחד ומש\\\"ה כל כלים שע\\\"ג טמאין ותוכה טהור משום דפיה לחוץ ומ\\\"מ כלים שבתוכה כנגד הטומאה טמאים משום דכלים אינם נעשים אהלים לטהר ואילו לא היה שם כוורת היה כל שכנגד הטומאה טמא אינו בדין שתציל הכוורת על כלים שכנגד הטומאה.\",6,0],[8,374,19,1,\"ומ\\\"ש ובתוכה הכל טמא. תוכה והבית פשיטא שטמאים שהרי הוא כאילו שניהם גג אחד וכלים שתחתיה ג\\\"כ טמאים שכיון שהיא גבוהה מהארץ טפח שהוא אהל הוי כאילו היא וגג הבית אהל אחד וכיון שאמרנו שעברה טומאה לבית וכל מה שבבית טמא א\\\"כ גם כל מה שתחתיה טמא וכל כלים שע\\\"ג ג\\\"כ טמאים משום דכלים נעשים אהלים לטמא כמו שנתבאר בפי\\\"ב:\",7,0],[8,374,19,1,\"ועל מ\\\"ש רבינו אבל כל שבאויר תוכה טהור חוץ מכלי שהוא כנגד הטומאה. כתב הראב\\\"ד א\\\"א גם זה שיבוש שהכלי שבתוכה טהור שאין כאן רצוצה עכ\\\"ל פי' דבריו כי כשהטומאה רצוצה אז בוקעת כנגדה אבל כשאינה רצוצה אין חילוק בין כנגדה לשלא כנגדה וכיון שע\\\"י האהל מתפשטת הטומאה אם נכנסת לתוכה הכל טמא וכיון שאינה נכנסת הכל טהור וטעם רבינו דלגבי מה שכנגד הטומאה חשבינן לכוורת כמאן דליתא ונמצא כלי זה מאהיל על הטומאה.\",8,0],[8,374,19,1,\"ועל מ\\\"ש רבינו או שהיתה טומאה על גביהן מביאין ולא חוצצין. כתב הראב\\\"ד א\\\"א אין כאן טעם וכו'. אין תלונתו על רבינו כי אם על המשנה דקתני ברפ\\\"ו (משנה א') דאדם וכלים אפילו כלים שאינם מקבלים טומאה נעשים אהלים לטמא אבל לא לטהר וברפ\\\"ח (משנה א') קתני דכלים שאינם מקבלים טומאה חוצצין וליישב זה נאמר דחוצצין דרפ\\\"ח מיירי בפותח שבין בית לבית וטומאה בא' מהן אבל כשהטומאה תחתיהן או על גביהן נעשים אהלים לטמא אבל לא לטהר כדתנן רפ\\\"ו וכן פירש הרא\\\"ש, וכך הם דברי רבינו כאן אע\\\"פ שבפירוש המשנה לא פירש כן:\",9,0],[8,374,19,1,\"ומה שכתב רבינו בד\\\"א בזמן שהיא כלי וכו'. ג\\\"ז שם במשנה פרק ט' (מי\\\"ב) היתה פחותה שנפחתה ונתבטלה מתורת כלי הרי היא חוצצת ומצלת על מה שתחתיה ועל גבה ופקוקה בקש לרבותא נקט אע\\\"פ שסתם כל הפחת בקש אין שם כלי עליה או אפוצה כלומר מליאה קש וכיוצא בו עד שלא נשאר בה חלל טפח שוב אין לה דין כלי והילכך תוכה וגבה טהור וחוצצת:\",10,0],[8,374,19,1,\"ועל מ\\\"ש רבינו אבל אם היתה פחותה וסתם מקום הנפחת וכו' ותוכה וגבה טהור מפני שהוא אהל של עץ: כתב הראב\\\"ד אין טעם ולא ריח בזה הפירוש ויש כאן פתיות גדולה עכ\\\"ל. יראה שטעמו משום דקשיא ליה מ\\\"ש מפני שהוא אהל של עץ דמה לנו אם יהיה של עץ או של דבר אחר ולא היה לו ליתן טעם אלא מפני שאינו כלי. וי\\\"ל שהוצרך רבינו לומר מפני שהוא אהל של עץ לומר שאינו מקבל טומאה שאילו היה מדבר ארוג או מנסרות נטמא האהל עצמו כדאיתא בפרק במה מדליקין ואין דבר טמא חוצץ וכן אם היה כלי אע\\\"פ שאינו מקבל טומאה לא היה חוצץ כמו שנתבאר פי\\\"ב אבל מאחר שהוא אהל של עץ שאינו מקבל טומאה וגם אינו כלי הרי הוא חוצץ ולפיכך תוכה וגבה טהור:\",11,0],[8,374,19,1,\"היתה מונחת על הארץ ופיה לחוץ וכו'. גם זה שם במשנה וטעמא משום דכיון דלאו כלי הוא כמו שקדם הילכך כזית מן המת נתון תחתיה כנגדו עד התהום טמא דטומאה רצוצה היא ובוקעת ויורדת ועל גבה אף כנגד הזית טהור דכיון דלאו כלי היא חוצצת על גבה כנגדו עד הרקיע טמא ותחתיה טהור דחוצצת היתה הטומאה בבית אין טמא אלא הבית בלבד דכיון דאינה גבוהה טפח אין הטומאה נכנסת תחתיה היתה טומאה בתוכה אין טמא אלא תוכה דכיון דאינה גבוהה טפח אין הטומאה יוצאת מתוכה לבית ומצלת על תחתיה וגבה כיון דלאו כלי היא וכאן איחר רבינו המשנה המוקדמת מפני שרצה לסמוך היתה גבוהה מהארץ טפח דאינו כלי להיתה גבוהה מהארץ טפח דהיתה כלי:\",12,0],[8,374,19,1,\"ועל מ\\\"ש וכזית מן המת נתון תחתיה כנגדו עד התהום טמא. כתב הראב\\\"ד א\\\"א כאן צריך טעם וכו'. כלומר שאין זה כדאי לתרץ הקושיא ולי נראה שהטעם שמאחר שהיה בה חלל טפח אע\\\"פ שעכשיו היא אפוצה אהני לה מה שהיה בה חלל טפח קודם לענין שלא תבקע למעלה ואהני לה מה שהיא עתה אפוצה לענין שתבקע למטה. א\\\"נ מיירי בשיש בה חלל טפח על טפח על רום טפח אלא שאינו במקום אחד והכי דייק לישנא דמתני' ומש\\\"ה דיה שתבקע למטה ואינה כדאי שתבקע למעלה ובפחותה ופקוקה בקש יש שם פותח ופקוקה בקש ולענין שתבקע ותרד למטה חשובה כסתומה ולענין שלא תבקע ותעלה למעלה לא חשובה כסתומה:\",13,0],[8,374,19,2,\"כוורת המוטלת בארץ בתוך הפתח ופיה לפנים וכו'. דין בבא זו כדין בבא ראשונה אלא ששם בבית אין טמא אלא הבית וכאן הכל טמא והטעם מבואר לפי ששם בבית פיה לחוץ וכאן פיה לפנים. ועוד יש חילוק אחר דהכל טמא דקתני במתני' הכא הוי כל מה שבבית וכל מה שתחתיה וכל מה שעל גבה הכל ושם אין תחתיה ועל גבה טמא אלא כנגד הטומאה וגם בזה הטעם משום דכיון דהכא פיה לפנים הוי כאילו פיה וגג הבית אהל אחד וכיון דכלים נעשו אהלים לטמא כלים שתחתיה ושעל גבה רואים כאילו הם בתוכה:\",1,0],[8,374,19,2,\"ומ\\\"ש היתה גבוהה מן הארץ טפח וכו'. גם זה שם וכמבואר בדברי רבינו הטעם:\",2,0],[8,374,19,2,\"ומ\\\"ש היתה פחותה ופקוקה בקש וכו'. גם זה שם במשנה והטעם מפני שכבר נתבאר דהיכא דפיה לפנים וגבוהה מן הארץ טפח שוליה וגגה וגג הבית הכל אהל אחד והילכך טומאה באחד מהם כלים שבכולם טמאים ומ\\\"מ טומאה באחד מהם כלים שעל גבה טהורים וכן אם הטומאה על גבה כלים שבכולם טהורין משום דכיון דאינה כלי חוצץ גגה בין מה שעל גבה למה שתחתיה.\",3,0],[8,374,19,2,\"ומ\\\"ש היתה מונחת על הארץ וכו'. גם זה במשנה שם בבא זו שוה לאידך בבא דהיתה מונחת על הארץ ופיה לחוץ אלא ששם טומאה בבית אין טמא אלא הבית בתוכה אין טמא אלא תוכה וכאן בתוכה או בבית תוכה והבית טמאים והטעם מבואר משום דשם פיה לחוץ וכאן פיה לפנים:\",4,0],[8,374,19,2,\"ועל מ\\\"ש רבינו גבי כוורת המוטלת בארץ וכו' היתה גבוהה מהארץ טפח וטומאה תחתיה או בתוכה או על גבה או בבית הכל טמא וכו'. כתב הראב\\\"ד דברים אלו כבדים וכו' כי מעל גבה והטומאה מבחוץ איך תבא לתחתיה וכו'. לדעת רבינו אין כאן קושיא אע\\\"פ שהעמידה בכוורת מחזקת ארבעים סאה שאינה מקבלת טומאה כלל אף על פי כן טומאה על גבה טמא תחתיה מדתנן ברפ\\\"ו דאפי' כלי גללים נעשים אהל לטמא אבל לא לטהר וכמו שנתבאר:\",5,0],[8,374,19,3,\"כוורת שהיא בתוך הבית וכו'. גם זה שם במשנה פ\\\"י טומאה בתוכה הבית טמא דאפילו אם היתה מוקפת צמיד פתיל אין צמיד פתיל לטומאה אבל אם טומאה בבית מה שבתוכה טהור שאין הטומאה נכנסת לה כיון שאין בין פיה לתקרה פותח טפח שדרך הטומאה לצאת לתוך הבית בפחות מטפח בין עומדת כדאמרן בין מוטה על צדה ואין בין פיה לכותל פותח טפח בין אחת כדאמרן בין שתים זו על גב זו ואין בין פי התחתונה לשולי העליונה פותח טפח וכן אין בין פי העליונה לקורות פותח טפח:\",1,0],[8,374,19,3,\"היתה עומדת בתוך הפתח ופיה למעלה וכו'. פי' הב\\\"ע בשהכוורת ממלאה את כל הפתח ואין פותח טפח מכל צד למעלה ולמטה ומן הצדדים ואין מקום לטומאה לצאת הילכך הטומאה בוקעת ויוצאת דרך דופני הכוורת מידי דהוה אפתחי הבית בזמן שהם נעולים:\",2,0],[8,374,19,4,\"כוורת חלולה שהיא כלי שלם וכו'. ג\\\"ז שם במשנה דינא דהאי בבא כדינא דבבא קמייתא שבפרק זה אלא דהתם מיירי בשמקצתה בתוך פתח הבית והכא מיירי באויר ומפני שהוא תחלת ענין לבבות שכל הכוורת היא באויר התנה שיהא חלולה:\",1,0],[8,374,19,4,\"היתה גבוהה מן הארץ טפח וכו'. גם זה שם ודין בבא זו כדין בבא שנייה שבראש הפרק אלא דהתם איירי בשקצתה תוך הבית והכא מיירי בכולה באויר:\",2,0],[8,374,19,4,\"לפיכך אם היתה כוורת זו המוטלת על הארץ וכו'. ג\\\"ז שם ודין זו כדין בבא דלעיל המתחלת היתה מונחת על הארץ ופיה לחוץ אלא שכאן כולה באויר:\",3,0],[8,374,19,4,\"ומ\\\"ש רבינו או שהיתה באה במדה. ק\\\"ל דמשמע דעד השתא מיירי באינה באה במדה וזה אינו שכבר כתבתי בראש הפ' דברי רבינו שכתב שכל פרק זה מיירי בבאה במדה ונראה שהטעם מפני שבבבות שכתב עד עתה דמיירי בשהכוורת עומדת באויר לא איצטריך שתהא באה במדה דאפילו באינה באה במדה מיירי כתב בבבא זו שאם היא באה במדה אפילו אינה פחותה ופקוקה בקש נמי ועוד דרבינו לישנא דמתני' נקט ששנו בבבא זו ובבבא דגבי כוורת שהיא כלי שני או מחזקת מ' סאה כתבה גם רבינו ואפשר שהטעם ששנה כן התנא הוא מהטעם שכתבתי בסמוך:\",4,0],[8,374,19,5,\"כוורת שהיא כלי שלם וכו'. גם זה שם במשנה ופי' על גבה היינו שהטומאה מאהלת חוץ למעלה מפיה טומאה בוקעת וכו' דכיון דקי\\\"ל דכלים נעשים אהלים לטמא אבל לא לטהר כשהיתה בתוכה או על גבה רואין אותה כאילו היא תחתיה וכשהיא תחתיה הרי היא רצוצה ובוקעת ועולה.\",1,0],[8,374,19,5,\"ומה שכתב אבל אם היתה גבוהה מן הארץ טפח או מכוסה וכו' עד וחוצצת. גם זה שם במשנה וכתנא קמא והכל מבואר ע\\\"פ השרשים הקודמים:\",2,0],[8,374,19,5,\"וראיתי להעתיק פה מה שכתבתי בפירוש משניות פ\\\"ט דאהלות שהיא פרק זה דכוורת ומה שקשה לי בקצת בבות אלו וישמע חכם ויוסיף לקח:\",3,0],[8,374,19,5,\"[מ\\\"א] כוורת שהיא בתוך הפתח ופיה לחוץ וכו'. הראב\\\"ד בהשגות פי\\\"ט מהלכות טומאת מת פירש פרק זה בכוורת של חרס ונדחק מאד בכמה מקומות מפרק זה כמבואר שם בדבריו, ורבינו שמשון והרא\\\"ש פירשו דבכוורת של עץ מיירי ומחולחלת דקתני היינו שדרך הכוורת שעושין לה נקבים בדפנותיה מקום יציאת וכניסת הדבורים ופעמים פוקקין אותן בקש ואותו הפקק אינו תקוע בחוזק אלא רפוי וכיון שהוא רפוי חשיב כפתוח להוציא ממנה הטומאה אבל להכניס לה טומאה חשיב כסתום דבכל דוכתא טומאה יוצא בקל יותר ממה שנכנסת ואע\\\"פ שפירושם נכון מכל מקום נדחקו במאי דקתני רישא וכל שאינו כנגד הזית תוכה והבית טהור דהאי תוכה הוי כמו ותוכה בוי\\\"ו כמבואר בדברי רבינו שמשון וגם מחולחלת דנקט גבי פיה לפנים כמבואר בדברי הרא\\\"ש דלא נפקא לן מידי בפיה לפנים בין במחולחלת לשאינה מחולחלת כיון דפיה לפנים והטומאה יוצאה דרך פיה לבית אלא אגב דתנא ברישא מחולחלת בהדי כלי תני נמי הכא והרמב\\\"ם ז\\\"ל פירשה ג\\\"כ בכוורת של עץ כמבואר בדבריו בפירוש המשנה. וראיתי לבאר פרק זה ע\\\"פ פירושו אחת לאחת למצוא חשבון ולא אביא כל מ\\\"ש הוא עצמו ז\\\"ל בפי' המשנה שלא לכפול הדברים:\",4,0],[8,374,19,5,\"כוורת שהיא בתוך הפתח ופיה לחוץ. במוטה על צדה איירי ומקצתה בפנים ומקצתה בחוץ.\",5,0],[8,374,19,5,\"כזית מן המת נתון תחתיה או על גבה מבחוץ כל שהוא כנגד הזית תחתיה וגבה טמא. כשהטומאה תחתיה כיון דרצוצה היא פשיטא דבוקעת ועולה בוקעת ויורדת וכשהיא על גבה כיון דקי\\\"ל דכלים אינם חוצצים בפני הטומאה א\\\"כ כשהיא ע\\\"ג רואין אותה כאילו היא תחתיה ובוקעת ועולה בוקעת ויורדת וכיון דבוקעת ועולה א\\\"כ מה שבתוכה כנגד הטומאה טמא וכ\\\"כ הרמב\\\"ם פה ובחיבור פי\\\"ט מהלכות טומאת מת. וסיפא דמתני' נמי דיקא\",6,0],[8,374,19,5,\"דקתני וכל שאינו כנגד הזית תוכה והבית טהור משמע בהדיא דאין תוכה טהור אלא מה שאינו כנגד הזית דוקא.\",7,0],[8,374,19,5,\"בבית אין טמא אלא הבית. דכיון דפיה לחוץ אין הטומאה עוברת לכלים שבתוכה או ע\\\"ג מבחוץ וכן אינה עוברת לכלים שתחתיה מבחוץ כיון שאינה גבוהה מן הארץ טפח.\",8,0],[8,374,19,5,\"בתוכה הכל טמא. תוכה פשיטא דטמא והבית טמא משום דכוורת אינה חוצצת בפני הטומאה ועברה הטומאה לבית. ותחתיה וע\\\"ג כנגד הטומאה טמאים משום דכיון דאין כלים חוצצין רואין את הטומאה כאילו היא ע\\\"ג וכן תנא ברישא דכשהיא על גבה כל שהוא כנגד הזית תחתיה וגבה טמא ובזה נסתלק מה שהשיג הראב\\\"ד על מ\\\"ש הרמב\\\"ם פי\\\"ט מהלכות טומאת מת היתה הטומאה בתוכה טמא כל שבבית וכל שבתוכה וכל שעל גבה וכל שתחתיה כנגד הטומאה כמו שביארנו עכ\\\"ל ומתוך מ\\\"ש נתבאר דכנגד הטומאה שכתב קאי בין לכל שע\\\"ג בין לכל שתחתיה.\",9,0],[8,374,19,5,\"ומ\\\"ש הרמב\\\"ם כמו שביארנו רומז למ\\\"ש ברישא כזית מן המת נתון תחתיה או ע\\\"ג מבחוץ כל שהוא כנגד הזית בתחתיה או בגבה טמא:\",10,0],[8,374,19,5,\"[מ\\\"ב] היתה גבוהה מן הארץ טפח טומאה תחתיה או בבית או ע\\\"ג הכל טמא אלא תוכה. הטעם משום דכיון שהיא אהל על הארץ רואין אותה כאילו נתחברה עם גג הבית והיה הכל גג אחד והילכך טומאה תחתיה או בבית כל שתחתיה וכל שבבית פשיטא דטמא שהרי הטומאה והכלים תחת אהל אחד. וע\\\"ג לכאורה נראה דטעמא משום דכיון דקי\\\"ל דכלים נעשים אוהלים לטמא אבל לא לטהר א\\\"כ כלים שע\\\"ג רואין אותן כאילו הן תחתיה ונמצא שהן והטומאה תחת אהל אחד ומש\\\"ה גם כל כלים שע\\\"ג טמאים. ותוכה טהור משום דפיה לחוץ ומ\\\"מ כלים שבתוכה כנגד הטומאה טמאים וכמ\\\"ש הרמב\\\"ם ז\\\"ל בפי\\\"ט מהלכות טומאת מת וטעמא משום דכיון דכלים אינם נעשים אהלים לטהר ואילו לא היה שם כוורת היה כל שכנגד הטומאה טמא א\\\"כ אינו בדין שתציל הכוורת על כלים שבתוכה כנגד הטומאה ובזה נסתלקה השגת הראב\\\"ד גם על דין זה.\",11,0],[8,374,19,5,\"בתוכה הכל טמא. תוכה והבית פשיטא שטמאים שהרי הוא כאילו שניהם תחת גג אחד וכלים שתחתיה ג\\\"כ טמאים שכיון שהיא גבוהה מהארץ טפח שהוא אהל הוי כאילו היא וגג הבית אהל אחד וכיון שאמרנו שעברה טומאה לבית וכל שבבית טמא א\\\"כ גם כל שתחתיה טמא וכל כלים שעל גבה טמאים משום דכלים נעשים אהלים לטמא וכדתנן רפ\\\"ו היתה טומאה תחתיה כלים שע\\\"ג טמאים:\",12,0],[8,374,19,5,\"[מ\\\"ג] בד\\\"א בזמן שהיא כלי מחולחלת היתה פחותה. שנפחתה ונתבטלה מתורת כלי אז היא חוצצת ומצלת על מה שתחתיה ועל גבה.\",13,0],[8,374,19,5,\"ופקוקה בקש. לרבותא נקט אע\\\"פ שסתם כל הפחת בקש אין שם כלי עליה.\",14,0],[8,374,19,5,\"אפוצה. כלומר מליאה קש וכיוצא בו עד שלא נשאר בה חלל טפח שוב אין לה דין כלי\",15,0],[8,374,19,5,\"והילכך כזית מן המת נתון תחתיה כנגדו עד התהום טמא דטומאה רצוצה היא ובוקעת ויורדת ועל גבה אף כנגד הזית טהור דכיון דלאו כלי הוא חוצצת.\",16,0],[8,374,19,5,\"על גבה כנגדו עד הרקיע טמא ותחתיה טהור דחוצצת.\",17,0],[8,374,19,5,\"בבית אין טמא אלא הבית. דכיון דאינה גבוהה טפח אין הטומאה נכנסת תחתיה.\",18,0],[8,374,19,5,\"בתוכה אין טמא אלא תוכה. דכיון דאינה גבוהה טפח אין הטומאה יוצאת מתוכה לבית ומצלת על תחתיה וגבה כיון דלאו כלי היא:\",19,0],[8,374,19,5,\"[מ\\\"ד] היתה גבוהה מן הארץ טפח טומאה תחתיה או בבית תחתיה והבית טמא. דמביאין טומאה מזה לזה.\",20,0],[8,374,19,5,\"תוכה וגבה טהור. דלאו כלי היא וחוצצת:\",21,0],[8,374,19,5,\"[מ\\\"ה] בד\\\"א בזמן שפיה לחוץ היה פיה לפנים וכו'. דין בבא זו כדין בבא ראשונה אלא ששם בבית אין טמא אלא הבית וכאן הכל טמא והטעם מבואר לפי ששם פיה לחוץ וכאן פיה לפנים. ועוד יש חילוק אחר דהכל טמא דקתני הכא הוי כל מה שבבית וכל מה שבתוכה וכל מה שתחתיה וכל מה שע\\\"ג הכל ושם אין תחתיה וע\\\"ג טמא אלא כנגד הטומאה וגם בזה הטעם דכיון דהכא פיה לפנים הוי כאילו פיה וגג הבית אהל וכיון דכלים נעשים אהלים לטמא כלים שתחתיה ושע\\\"ג רואים אותה כאילו הם בתוכה:\",22,0],[8,374,19,5,\"[מ\\\"ו] היתה גבוהה מן הארץ טפח טומאה תחתיה או בבית או בתוכה או ע\\\"ג הכל טמא. טעמא משום דכיון דגבוהה מן הארץ טפח רואין כאילו שוליה וגג הבית אהל וכן רואים כאילו פיה וגג הבית אהל אחד והילכך טומאה תחת אחד מהם כלים שבכולם טמאים וע\\\"ג כיון דכלי היא הא אמרן דנעשה אהל לטמא אבל לא לטהר:\",23,0],[8,374,19,5,\"[מ\\\"ז] במה דברים אמורים בזמן שהיא כלי וכו'. בבא זו שוה לאידך בבא דקתני בה נמי בד\\\"א בזמן שהיא כלי וכו' אלא ששם טומאה בבית אין טמא אלא הבית בתוכה אין טמא אלא תוכה וכאן בתוכה או בבית תוכה והבית טמאים והטעם מבואר משום דשם פיה לחוץ וכאן פיה לפנים:\",24,0],[8,374,19,5,\"[מ\\\"ח] היתה גבוהה מן הארץ טפח טומאה תחתיה או בבית או בתוכה הכל טמא אלא גבה על גבה כנגדו עד הרקיע טמא. כבר נתבאר דהיכא דפיה לפנים וגבוהה מן הארץ טפח שוליה וגבה וגג הבית הכל אהל אחד והילכך טומאה באחד מהם כלים שבכולם טמאים אבל אם טומאה באחד מהם כלים שעל גבה טהורים וכן אם טומאה על גבה כלים שבשאר מקומות טהורים משום דכיון דאינו כלי חוצץ גגה בין מה שעל גבה למה שתחתיה:\",25,0],[8,374,19,5,\"[מ\\\"ט] היתה ממלאה את כל הבית ואין בינה לבין הקורות פותח טפח. כלומר אם היתה כוורת בתוך הבית והיא ממלא את כל גובה הבית ופיה למעלה לקורות הבית ואין בינה לבין הקורות פותח\",26,0],[8,374,19,5,\"טפח טומאה בתוכה הבית טמא דאפילו אם היתה מוקפת צמיד פתיל אין צמיד פתיל לטומאה אבל\",27,0],[8,374,19,5,\"אם טומאה בבית מה שבתוכה טהור שאין הטומאה נכנסת לה כיון שאין בינה לתקרה טפח.\",28,0],[8,374,19,5,\"שדרך הטומאה לצאת לתוך הבית בפחות מטפח.\",29,0],[8,374,19,5,\"ואין דרכה ליכנס בפחות מטפח.\",30,0],[8,374,19,5,\"בין עומדת כדאמרן.\",31,0],[8,374,19,5,\"בין מוטה על צדה ואין בין פיה לכותל פותח טפח.\",32,0],[8,374,19,5,\"בין אחת כדאמרן.\",33,0],[8,374,19,5,\"בין שתים זו על גבי זו ואין בין פי התחתונה לשולי העליונה פותח טפח וכן אין בין העליונה לקורות פותח טפח:\",34,0],[8,374,19,5,\"[מ\\\"י] היתה עומדת בתוך הפתח. ופיה למעלה.\",35,0],[8,374,19,5,\"ואין בינה לבין המשקוף פותח טפח טומאה בתוכה הבית טהור. שהטומאה יוצאת דרך הפתח לחוץ.\",36,0],[8,374,19,5,\"טומאה בבית מה שבתוכה טמא. הב\\\"ע שהכוורת ממלא כל הפתח ואין פותח טפח מכל צד למעלה ולמטה ומן הצדדין ואין מקום לטומאה לצאת הילכך הטומאה בוקעת ויוצאת דרך דופני הכוורת מידי דהוה אפתחי הבית בזמן שהן נעולים:\",37,0],[8,374,19,5,\"[מי\\\"א] היתה מוטה על צדה באויר וכו'. דינא דהאי בבא כדינא דבבא קמייתא דריש פירקין אלא דהתם מיירי בשקצתה בתוך פתח הבית והכא מיירי בשכולה באויר:\",38,0],[8,374,19,5,\"[מי\\\"ב] היתה גבוהה מן הארץ טפח וכו'. גם דינא דהאי בבא כדינא דבבא תניינא דר\\\"פ אלא דהתם מיירי בשקצתה בתוך הפתח והכא מיירי בשכולה באויר:\",39,0],[8,374,19,5,\"בד\\\"א בזמן שהיא כלי היתה פחותה ופקוקה בקש או מחזקת מ' סאה כדברי חכמים וכו'. דכיון שאינה כלי שהיא פחותה או שהיא מחזקת ארבעים סאה שאין דין כלי עליה.\",40,0],[8,374,19,5,\"טומאה תחתיה וכו' טומאה בוקעת ועולה וכו'. שכלי עץ הבא במדה כאהל הוא חשיב לא ככלים ולפי שהיא כאויר ל\\\"ש לן בין אפוצה לשאינה אפוצה דלעיל לא הזכיר אפוצה אלא משום דבפיה לפנים כשאינה אפוצה. כתב הרא\\\"ש כולי פירקין עד השתא איירי נמי במחזקת ארבעים סאה מדמצלת על מה שבתוכה אלא אשמעינן השתא דרבנן פליגי את\\\"ק וסברי דמחזקת ארבעים סאה בנפחתה שבטלה מתורת כלי דמצלת תחתיה ותוכה וע\\\"ג ובהנך בבי דלעיל נמי מצי למיתני או מחזקת ארבעים סאה כדברי חכמים אלא דבלאו הכי תני תרתי פחותה ואפוצה אבל הכא דלא תנא אלא פחותה תנא או מחזקת למיתני תרתי כי הני בבי דלעיל:\",41,0],[8,374,19,5,\"[מי\\\"ג] היתה יושבת על שוליה והיא כלי וכו'. על גבה היינו שהטומאה מאהלת חוצה לה למעלה מפיה.\",42,0],[8,374,19,5,\"טומאה בוקעת וכו' דכיון דקי\\\"ל דכלים נעשים אהלים לטמא אבל לא לטהר כשהיא בתוכה או על גבה רואין אותה כאילו היא תחתיה וכשהיא תחתיה הרי היא רצוצה ובוקעת ועולה וכו':\",43,0],[8,374,19,5,\"היתה גבוהה מן הארץ טפח וכו'. גם זה מהטעם הנזכר שכלים נעשים אהלים לטמא אבל לא לטהר וכדתנן ברפ\\\"ו גבי אהל שהיה נתון על ארבעה כלים טומאה על גביו כלים שתחתיו טמאים טומאה תחתיו כלים שעל גביו טמאים:\",44,0],[8,374,19,5,\"[מי\\\"ד] בד\\\"א בזמן שהיא כלי היתה פחותה ופקוקה בקש וכו'. לרבנן כשאינה גבוהה מהארץ טפח אין חילוק בין אם היא כלי ובין אינה כלי אלא לרבי אלעזר ורבי שמעון הוא דיש חילוק וכן לרבנן כשגבוהה טפח:\",45,0],[8,374,19,5,\"ואיכא למידק במשנה שלישית כשהיתה פחותה ופקוקה בקש וכו' וכזית מן המת נתון כנגדו עד התהום טמא וכן במשנה ז' וכן במשנה י\\\"ג ולמה לא יהיה ג\\\"כ כנגדו עד הרקיע טמא שהרי טומאה רצוצה היא ובוקעת ועולה בוקעת ויורדת וכבר השיג הראב\\\"ד כן. ואפשר לומר דלא מיקרי רצוצה אלא כשהיא בתוך קרקע או בנין אבל כשהיא בתוך עץ וכיוצא בו שאינו כלי אין לה דין טומאה רצוצה והא דהכא כנגדו עד התהום טמא היינו מפני שהיא מונחת על הקרקע והיא רצוצה בוקעת למטה בקרקע כדין קרקע ואינה בוקעת למעלה בכוורת אבל קשה ממתניתין דהיתה יושבת על שוליה דקתני בטומאה תחתיה טומאה בוקעת ועולה וכן קתני נמי בהיתה פחותה וכו' ולפי טעם זה לא היה לה לבקוע ולעלות וצריך עיון:\",46,0],[8,374,19,5,\"ואיכא למידק תו הב\\\"ע אי בכוורת שאינה מחזקת ארבעים סאה בבבא קמייתא ובבבא חמישית ובבבא י\\\"א אמאי כל שאינו כנגד הזית תוכה והבית טהור הא כיון דכלי עץ מיטמא מגבו נטמאת כוורת זו והיאך תציל על מה שבתוכה וכן יקשה בבבא שניה ובבבא י\\\"ב אמאי הכל טמא אלא תוכה ומפני כך העמידוה רבינו שמשון והרא\\\"ש במחזקת מ' סאה שאינה מקבלת טומאה ולפיכך מצלת על מה שבתוכה וכן העמידה ג\\\"כ הרמב\\\"ם בפירוש המשנה אבל קשה על זה ממה שכתב בחיבור פרק י\\\"ט מהלכות טומאת מת שכלי עץ הבא במדה כאהל הוא חשיב לא ככלים ולפיכך חוצץ א\\\"כ דין כוורת המחזקת ארבעים סאה כדין כוורת שהיא פחותה ופקוקה בקש או אפוצה וכדברי חכמים דתנן גבי היתה מוטה על צדה באויר וא\\\"כ היאך פסק הרמב\\\"ם ככל הני סתמי מתני' דהאי פירקא הא כיון דבמחזקת ארבעים סאה מיירי על כרחיך דאל\\\"כ לא היתה מצלת על מה שבתוכה וכדאמרן ואיהו ז\\\"ל ס\\\"ל במחזקת מ' סאה שדינה שוה לפחותה או אפוצה שהיא חשובה כאהל ולא ככלי א\\\"כ כי אינה פחותה או אפוצה כפחותה או אפוצה דמי והיאך חילק ביניהם. ויש לומר דלעולם בכוורת המחזקת ארבעים סאה ואע\\\"פ שכתב הרמב\\\"ם דכלי עץ הבא במדה אינו ככלים לאו למימרא שלא יהא לו דין כלי כלל ויהיה דינו שוה לגמרי לפחותה או אפוצה אלא לענין לחוץ בפני הטומאה דוקא הוא דקאמר דאינו ככלי דאילו כלי שאינו בא במדה אפילו גבוה טפח אינו אהל לטהר שאינו חוצץ והבא במדה חוצץ כשהוא גבוה טפח דהוי אהל אבל כשאינה גבוהה מהארץ טפח דין כלי יש לה לקצת דברים ולישנא דהרמב\\\"ם דייק הכי שכתב שכלי עץ הבא במדה כאהל הוא חשוב לא ככלים ולפיכך חוצץ. משמע בהדיא דדוקא ביש לה דין אהל דהיינו שהיא גבוהה מהארץ טפח הוא דקאמר דאינה ככלים אבל באינה גבוהה מהארץ טפח דין כלים יש לה לקצת דברים ואינה חוצצת. והשתא כל בבי דהאי פירקא דמיירי בשאינה גבוהה מן הארץ טפח ניחא דאע\\\"ג דמחזקת ארבעים סאה דין כלי שאינו בא במדה יש לה לענין זה ובבי דמיירי בהיתה גבוהה מהארץ טפח דמשמע דיהיב לה דין כלי שאינו בא במדה לומר דאינה נעשית אהל לחוץ בפני הטומאה צריך ליישב דבבא שנייה דקתני דעל גבה הכל טמא אלא תוכה לא מטעמא דפרישית לעיל היא אלא כשהיא על גבה בחלק שיש ממנה תחת הבית מיירי ומשום הכי הבית טמא שהרי טומאה באויר הבית ועברה הטומאה תחתיה כיון שהיא גבוהה טפח וע\\\"ג מה שהוא תחת גג הבית פשיטא שהרי הטומאה והכלים תחת אהל אחד ואם כן הא דקתני הכל טמא אלא תוכה היינו לומר דתחתיה והבית ועל גבה טמא ומיהו לאו בחד גוונא דתחתיה והבית כל מה שבהם טמא ועל גבה קצתו דהיינו מה שהוא בתוך הבית טמא ומה שהוא חוצה טהור. וכן צריך לפרש בבבא ששית דעל גבה דקתני היינו דוקא שהטומאה בחלק שהוא בתוך הבית והכל טמא דקתני היינו לומר דגם על גבה טמא מיהו לאו כל גבה אלא דוקא בחלק שממנו בתוך הבית והא דקתני בבבא שמינית הכל טמא אלא גבה היינו חלק גבה שהוא חוץ לבית דאילו החלק שהוא בתוך הבית פשיטא דטמא אבל קשה על פירוש זה מאי דקתני בבבא י\\\"ב היתה גבוהה מן הארץ טפח טומאה תחתיה או על גבה הכל טמא אלא תוכה וכשהיא תחתיה או על גבה אמאי הכל טמא הא כיון דבמחזקת ארבעים סאה עסקינן הרי היא נעשית אהל וחוצצת בפני הטומאה וטומאה תחתיה כלים שעל גבה טהורים וכן טומאה על גבה כלים שתחתיה טהורים ואפשר דהאי מתניתין מיירי באינה מחזקת ארבעים סאה מדקתני בתר הכי או מחזקת ארבעים סאה מכלל דמתני' דקמה בשאינה מחזקת ארבעים סאה עסקינן אבל קשה א\\\"כ אמאי מצלת על מה שבתוכה הא כיון דאינה באה במדה טומאה תחתיה על גבה נטמאת היא עצמה והיאך תציל על מה שבתוכה וצריך עיון:\",47,0],[8,374,19,5,\"תו איכא למידק בפירוש הרמב\\\"ם בבבא קמייתא דכזית מן המת נתון תחתיה ובתוכה כנגד הטומאה טמא וכיון דבקעה הטומאה ועברה בתוכה למה לא יתפשט בכולה ומאי שנא מדין חבית שהיא יושבת על שוליה שבסוף פרק זה דקתני טומאה תחתיה כנגד קרקרותיה טומאה בוקעת ועולה והבית טמא וצ\\\"ע:\",48,0],[8,374,19,6,\"גמל שהוא עומד באויר וכו'. תוספתא באהלות פי\\\"ג ופירושה דכשהוא עומד הוא אהל וחוצץ.\",1,0],[8,374,19,6,\"ומ\\\"ש או על גבי רגלו. ז\\\"ל התוספתא טומאה תחת רגלו או על גבי רגלו והיא רצוצה והתנה שיהא באויר שאם היא תחת אהל כל כלים שתחת האהל טמאים אבל קשה למה לא נאמר גמל חלול הוא והצד העליון מביא את הטומאה כמבואר בפי\\\"ח וצ\\\"ע:\",2,0],[8,374,19,6,\"כבר ביארנו בנזירות. פ\\\"ז.\",3,0],[8,374,19,6,\"ומ\\\"ש ומשם אתה למד וכו'. כבר כתב כיוצא בזה בפרק ג' ובפ\\\"ה והוא בתוספתא דאהלות פ\\\"ט:\",4,0],[8,374,20,1,\"שלשה דברים מצילין באהל המת וכו'. תוספתא פ\\\"ו דכלים אלא שיש בה חסרון הניכר:\",1,0],[8,374,20,1,\"ומ\\\"ש כיצד בית טמא שיש בו וכו'. פ\\\"ח דכלים מתני' דבית שאור מוקף צמיד פתיל ומפורש הוא בתורה.\",2,0],[8,374,20,1,\"ומ\\\"ש וכן אם היה שם אהל וכו'. בפ\\\"ד דאהלות בדין מגדל ופ\\\"ט דאהלות בדין כוורת.\",3,0],[8,374,20,1,\"ומ\\\"ש אבל אם היה כזית מן המת וכו'. בספ\\\"ח דאהלות שתי חביות וכו':\",4,0],[8,374,20,1,\"ועל מ\\\"ש רבינו וכן אהל בתוך אהל וכו'. כתב הראב\\\"ד דוקא באהל שהוא מקבל טומאה וכו'. כלומר שאם האהל הפנימי היה לו פתח לחוץ שלא על החיצון טהור החיצון שהטומאה יוצאה דרך אותו פתח שדרך הטומאה לצאת ואין דרכה ליכנס והב\\\"ע בשאין לו דרך אלא על החיצון א\\\"נ כשאהל הפנימי הוא עשוי מדבר המקבל טומאה שאז אע\\\"פ שיש לו פתח לחוץ שלא על החיצון טמא אף החיצון מפני שאין דבר טמא חוצץ. ודברי רבינו יתבארו בפרק זה גבי חלק הבית במחיצה מכלפי ארצו:\",5,0],[8,374,20,2,\"ומה שכתב אבל הבלועים מצילים וכו' עד את הטומאה וכו'. בפרק בהמה המקשה (חולין דף ע״א) על מימרא דרבא למדו מן הכתוב דטומאה בלועה אינה מטמאה.\",1,0],[8,374,20,2,\"ומה שכתב כיצד כלב שאכל בשר המת וכו'. תוספתא דאהלות פרק י\\\"ב ובמשנה בפרק ח' דכלים תרנגול שבלע את השרץ ונפל לאויר התנור טהור.\",2,0],[8,374,20,2,\"ומ\\\"ש בלע טבעת וכו'. בסוף מקואות בלע טבעת טהורה נכנס לאהל המת הזה ושנה וטבל והקיאה הרי היא כמות שהיתה וכך הם פי' דברי רבינו אע\\\"פ שהם סתומים:\",3,0],[8,374,20,2,\"וכן כל הבלועים וכו'. תוספתא באהלות פי״ב וכן מתבאר בפרק העור והרוטב (חולין דף קכ״א ע״ב) גבי שחט בה שנים או רוב שנים ועדיין היא מפרכסת דבעי רבי זירא מהו שתציל על הבלועים שבתוכה:\",4,0],[8,374,20,2,\"ואם מתו ובשר המת בתוך מעיהם. שם ופי\\\"א דאהלות.\",5,0],[8,374,20,2,\"ומה שכתב או הכלים. כך צריך לגרוס ולא כספרים דגרסי או בכלים:\",6,0],[8,374,20,3,\"וכן מ\\\"ש נשחט רוב א' וכו'. בפרק העור והרוטב עלה קכ\\\"א:\",1,0],[8,374,20,4,\"וכמה תשהא הטומאה במעיהן וכו'. פי\\\"א דאהלות ופסק כר\\\"י בן בתירא ולא כר\\\"ש דאמר כדי שתפול לאור ותשרף דזוטר שיעורא טובא:\",1,0],[8,374,20,4,\"בד״א וכו' אבל זאב שבלע תינוק וכו'. במנחות פרק רבי ישמעאל (מנחות דף ס״ט:) ובפ״ג דתענית (דף כ״א:) ויהיב בגמרא טעמא לעצמות מפני שהם קשים אינם מתעכלים ודברי רבינו הם דלא כפירש״י ז״ל:\",2,0],[8,374,20,5,\"אין הבלועים ניצלים וכו' אבל הבלועים בגוף הכלים וכו' כיצד כוש שנבלעה בו הצינור של מתכת וכו'. פ\\\"ט דכלים.\",1,0],[8,374,20,5,\"ומ\\\"ש וכן מחט או טבעת שהיו מובלעים בטפילת התנור וכו' עד אע\\\"פ שהם שוקעים לתוך אוירה הרי אלו טהורים. בפ\\\"ט דכלים מחט או טבעת שנמצאו בנחושתו של תנור אבל לא יוצאים אם אופה את הבצק והוא נוגע בהם טמא באיזה בצק אמרו בבצק הבינוני נמצאו בטפילת התנור מוקף צמיד פתיל אם בטמא טמאים אם בטהור טהורים נמצאו במגופת החבית מצדיה טמאים מכנגד פיה טהורים נראים בתוכה אבל לא לאוירה טהורים שוקעים בתוכה ותחתיהם כקליפת השום טהורים.\",2,0],[8,374,20,5,\"ועל מ\\\"ש אבל על הבלועים בגוף הכלים והאבנים אינם ניצלים כיצד כוש שנבלעה בו הצנור של מתכת וכו'. כתב הראב\\\"ד הרבה עיינתי וכו'. על מ\\\"ש רבינו שהנבלעים בגוף הכלים והאבנים אינם ניצולים הוקשה לו מדתנן במחט או טבעת שנמצאת בטפילת התנור מוקף צמיד פתיל אם בטהור טהורים וכן מדתנן נמצאו במגופת החבית מכנגד פיה טהורים וכן בנראים לתוכה אבל לא לאוירה ותירץ דהנך הוו טהורים מטעם מוקף צמיד פתיל ויישב מה שקשה על זה מדקיימא לן שאין כלי חרס מציל אלא על האוכלים ועל המשקים ועל כלי חרס וזהו שסיים וכתב אולי בזה החוט יש לי להתלות וכו' כלומר בזה החוט שחלקתי דהנך מטעם צמיד פתיל הוא דטהורים אבל אם לא היה צמיד פתיל אע\\\"פ שהם מובלעים אינם ניצולים, אחר זה כתב שמה שרצה רבינו להוכיח שהנבלעים בגוף הכלים והאבנים אינם ניצולין ממתניתין דכוש [שבלע את הצנורא ומלמד] שבלע את הדרבן וכו' יש להקשות עליה ממתני' דספוג וכו' וכוש שבלע את הצנור היאך סופו לצאת וכו' ואולי יש לתרץ זה דכיון שיוכלו לצאת בידי אדם סופו לצאת קרינא ביה. ומ\\\"ש יכול אני לומר שנראין ואינם יוצאין דאיירי ברישא במחט וטבעת קשיא ליה לא הבנתי דבריו דהתם מיירי במחט וטבעת טמאים אם יטמאו התנור אם לא ונדון דידן בכלי טהור הבלוע אם ינצל מהטומאה ומה ענין זה לענין זה וצ\\\"ע:\",3,0],[8,374,20,5,\"ומ\\\"ש מ\\\"מ מה שפירש בטמא טמאים ובטהור טהורים והסוגיא שכתב על זה אינה כלום כלומר שהראב\\\"ד פירש שבטמא היינו שהתנור ראוי לקבל טומאה אע\\\"פ שהוא מוקף צמיד פתיל טמאים ובטהור שאינו ראוי לקבל טומאה כגון שהוא תנור שלא הוסק ורבינו פירש בטהור היינו שהוא מוקף צמיד פתיל וטמא היינו שאינו מוקף צמיד והראב\\\"ד הקשה על זה שאפילו הוא מוקף צמיד פתיל אינו מציל אלא כלי חרס ולפיכך כתב כאן שהפירוש וההילוך שהולך בזה אינו כלום ועוד שהוא סותר דבריו שפסק בפכ\\\"ג שצמיד פתיל אינו מציל אלא על כלי חרס וכאן כתב שהוא מציל על מחט וטבעת, ורבינו בפי' המשנה כתב וז\\\"ל והוא שתהיה הטבעת או המחט טהורה ויהיה בעצם הטפילה שיטפילו על קרקע התנור והטיט עליו ותחתיו והיה התנור מוקף צמיד פתיל ונתון באהל המת הנה נטמא התנור בכללו ונטמאת הטבעת או המחט אשר בתוכה ואם היה התנור טהור כו' (שהיה הצמיד פתיל כראוי) הנה הטבעת והמחט ג\\\"כ טהורים ולא יטמאו באהל המת שהם בגוף הבנין וזה הבנין כולו טהור עכ\\\"ל. ביאור דבריו דשאני הכא דמגו דמהני צמיד פתיל לתנור מהני נמי להם ובטלים אגב התנור וזה הטעם בעצמו לנמצאו במגופת החבית כנגד פיה אבל כשנמצאו מצדה מאחר שאין לחבית צורך במגופה שבצדיה ה\\\"ל כבלועים בלבינה שאינם ניצולים וכן פי' ר\\\"ש. וכתב עוד תניא בתוספתא אין במשמע אלא בזמן שהיא בתוך החבית ומנין אפילו בתוך המגופה למעלה מאוירה של חבית תלמוד לומר כלי ובכן נסתלקה הקושיא הגדולה שהוקשה להראב\\\"ד שהרי מבואר בתוספתא זו כמ\\\"ש:\",4,0],[8,374,20,6,\"כל הבלועים בקרקעיתו של בית וכו'. פרק ט\\\"ו דאהלות.\",1,0],[8,374,20,6,\"ועל מ\\\"ש רבינו שאין האהלים מונעים את הטומאה כמו שביארנו. כתב הראב\\\"ד אני לא ידעתי אנה נתבאר דבר זה וכו'. וי\\\"ל שמה שאמר רבינו כמו שביארנו היינו מ\\\"ש לעיל בפרק זה וכן אהל בתוך אהל וכזית מן המת באהל הפנימי כל הכלים שבאהל החיצון טמאים ובענין הדין שכתב רבינו שאין האהלים מונעים את הטומאה כתב בפירוש המשנה (פ\\\"ח מ\\\"ו) דהיינו מדתניא בתוספת' צמיד פתיל ואהלים מצילים על הטהורים מליטמא ואין מצילים על הטמאים מלטמא ודבר תימה הוא דהא קי\\\"ל שהאהל חוצץ בפני הטומאה וצ\\\"ל שאם היה חוצץ על פני כל הבית אה\\\"נ שלא היתה עוברת הטומאה למעלה אבל הב\\\"ע כשלא היה החצץ על פני כל הבית שהטומאה עולה דרך המקום שאין בו חצץ ומתפשטת למעלה בכל הבית אי נמי כשאין מקום לטומאה לצאת כי אם דרך למעלה מהחצץ דומיא דאהל בתוך אהל דלעיל וצ\\\"ע:\",2,0],[8,374,20,7,\"ביב שהוא קמור תחת הבית וכו'. פ\\\"ג דאהלות:\",1,0],[8,374,20,8,\"שתי חביות וכחצי זית בכל אחת וכו' עד וכן שני חדרים וכו'. פ\\\"ח דאהלות.\",1,0],[8,374,20,8,\"ומ\\\"ש אין צמיד פתיל לטומאה. תוספתא דכלים פ\\\"ו.\",2,0],[8,374,20,8,\"ומ\\\"ש וכחצי זית בפנימי או באמצעי וכו'. בתוספתא פ\\\"ט דאהלות:\",3,0],[8,374,21,1,\"מנין לצמיד פתיל וכו'. סוף פ\\\"ק דחולין (דף כ\\\"ה) ובספרי פרשת חוקת.\",1,0],[8,374,21,1,\"ומ\\\"ש לכל הכלים שאינם מקבלים טומאה שיצילו בצמיד. בפ\\\"י דכלים.\",2,0],[8,374,21,1,\"ומ\\\"ש ונסרים של עץ וכו'. בפ\\\"ה דאהלות אם היה נסר חלק או סרידה שאין לה אגפים טהור.\",3,0],[8,374,21,1,\"ומ\\\"ש וגולמי כלי מתכות. בתוספתא דכלים פ\\\"ז:\",4,0],[8,374,21,1,\"מה בין אהלים וכו'. בספרי פרשת חוקת כלים מצילים בצמיד פתיל ואהלים בכיסוי:\",5,0],[8,374,21,2,\"משפך שכפהו וכו'. כתב הראב\\\"ד א\\\"א תוספתא דכלים משפך אפילו טהור וכו'. מ\\\"ש הראב\\\"ד וכמאן לא למדנו אע\\\"פ שהוא מנוקב ולא סתמו י\\\"ל שטעם רבינו הוא משום דאי בשסתם הנקב מאי טעמא דרבי מאיר דאמר אינו מציל אף על פי שהראב\\\"ד בהשגה שאחר זו כתב שטעם רבי מאיר מפני שהוא עומד דרך תשמישו בחבית סובר רבינו שאין זה כדאי לומר שאינו מציל. ומ\\\"ש ומשפך ודאי בידי אדם הוא י\\\"ל דמשפך בתחילת עשייתו עושין אותו בענין שישאר נקוב ולא מיקרי בידי אדם אלא היכא שנעשה שלם ואחר כך מנקבין אותו:\",1,0],[8,374,21,3,\"כל הכלים המצילים וכו'. במשנה פ\\\"י דכלים גבי כלי גללים כלי אבנים כלי אדמה וכו' קתני היו כפויין על פיהן מצילין כל שתחתיהן עד התהום רבי אלעזר מטמא וידוע דהלכה כת\\\"ק. ומה שהצריך שיהיה בהם טפח על טפח טעמא שמאחר שהוא מציל מטעם שהוא אהל אינו אהל פחות מטפח ואיתא בתוספתא דכלים פ\\\"ז.\",1,0],[8,374,21,3,\"ומ\\\"ש רבינו אא\\\"כ היה הכלי כלי חרס וכו' כיצד חבית שכפויה על פיה וכו'. כתב הראב\\\"ד אמת כך היא שנויה בספרי וכו'. והנה רבינו בריש פ\\\"י דכלים אמתניתין דאלו כלים מצילים בצמיד פתיל וכו' היו כפויין על פיהם מצילין כל שתחתיהם עד התהום כתב וזה אצלנו א\\\"א בכלי חרס שהוא אם כפה כלי חרס על פיו לא יציל מה שתחתיו לפי שהוא יטמא דרך פתחו באמת ואפילו ידביקהו ע\\\"ה בטיט והדומה לזה לא יציל שאינו לא אהל ולא מוקף צמיד פתיל ונוסחת ספרא חבית שכפאה על פיה ומרחה בטיט מן הצדדים טמאה שנאמר צמיד פתיל עליו ולא צמיד פתיל על גבו וזה נכנס תחת אמרם בספרא בטומאת כלי חרס אמר וכל כלי חרס לרבות האהלים שהאהל של חרס יטמא ולא יציל מה שתחתיו כמו שיצילו האהלים וכו' ומאחר שראה רבינו ספרי וספרא מסכימים לדעת אחת וגם דרשי לה מקראי פסק כן ומתניתין תתפרש על פי זה דכי קתני היו כפויים על פיהם מצילים כל שתחתיהם עד התהום אשאר מיני כלים השנויים במשנה חוץ מכלי חרס ואע\\\"ג דתוספתא פליגא לא חש לה רבינו במקום סיפרא וספרי ודרשת קראי. ומ\\\"ש הראב\\\"ד ואני אומר מה ששנו בספרי שמירח מן הצדדים אינו מציל כשלא מירח שפתיה עם הקרקע וכו' ק\\\"ל לפי דעתו שכל הכלים צריכים צמיד פתיל למה שנו דין זה בחבית יותר מבשאר כלים ולפי דבריו הכי הו\\\"ל למיתני כלי שכפאו על פיו ומרחו בטיט ומדנקט חבית משמע שדין זה מיוחד בכלי חרס:\",2,0],[8,374,21,3,\"ומ\\\"ש עוד הראב\\\"ד גם מ\\\"ש שכל הכלים המצילים בצמיד פתיל אם כפה על פיהם מצילין בלא צמיד פתיל אין לו שרש שכל המשנה שכתבתי ע\\\"י צמיד פתיל היא שנויה בתחילתה. וי\\\"ל דסבר רבינו שאם כדברי הראב\\\"ד הו\\\"ל למיתני מצילין בין מפיהן בין מצדיהן וכו' בין כפויים על פיהם ור\\\"א מטמא בכפויים על פיהם ומדלא צירף היו כפויין בהדי הנך משמע דמלתא באנפי נפשה היא ואפילו בשאינו מוקף צמיד פתיל מציל:\",3,0],[8,374,21,3,\"ומ\\\"ש ודבר פסוק הוא בסיפרי שכל הכלים צריכים צמיד פתיל וכשהם כפויים איך יצאו מתורת כלים י\\\"ל דאין למדים מן הכללות ועוד י\\\"ל דהתם לא אתא אלא לומר דלא תימא שאין מציל בצמיד פתיל אלא כלי חרס כדכתיב בקרא אלא כל הכלים דינם ככלי חרס מרבויא דקרא ועוד י\\\"ל דהתם מיירי כשהם מצילין מתורת צמיד פתיל וכשהם כפויין על פיהם אינם מצילין מתורת צמיד פתיל אלא מתורת אהל:\",4,0],[8,374,21,3,\"ומ\\\"ש אבל משפך אפילו טהור שכתבתי למעלה הוא הטעהו. כבר כתבתי דממתניתין יליף לה רבינו ולא הוצרך ללמדו ממשפך. ומ\\\"ש ר\\\"מ סבר כיון שהוא עומד כדרך תשמישו בחבית אינו מציל לא ירדתי לסוף טעם זה:\",5,0],[8,374,21,3,\"ומ\\\"ש רבינו הדביק פיה לכותל ומירחה מן הצדדים מצלת וכו'. בתוספתא דכלים פ\\\"ז:\",6,0],[8,374,21,3,\"ועל מ\\\"ש רבינו אבל שאר כל הכלים המצילין בצמיד וכו'. כתב הראב\\\"ד א\\\"א אין לי אלא כל הכלים מצילים וכו' טעמו לומר דדוקא כשהכלי כפוי על בור ודות הוא דלא בעינן מירוח אבל כשהוא כפוי לכותל צריך מירוח והביא ראיה מהתוספתא ולאפוקי מדברי רבינו שכתב שאם היו דפנות הכלים דבוקות לדופני הבית מצילים בלא צמיד פתיל ולדעת רבינו י\\\"ל דמירח דקתני לאו דוקא אלא אורחא דמילתא נקט. א\\\"נ דמשום דבעא למיתני סיפא ר\\\"א אומר כפוי על פיו אינו מציל נקט רישא ומירח לאשמועינן דאפילו בהכי פליג ר\\\"א אבל לת\\\"ק בלא מירוח נמי מציל:\",7,0],[8,374,21,3,\"ומ\\\"ש שאין הכלים מצילים וכו' עד שיהיה טפח ממקום אחד. משנה פ\\\"ה דאהלות:\",8,0],[8,374,21,4,\"כשם שמצילין וכו' עד (שיהיה טפח) [שהרי האהילו] על הטומאה. שם:\",1,0],[8,374,21,5,\"קורה שיש בה וכו'. משנה ספ\\\"ה דאהלות קורה שהיא נתונה מכותל לכותל וקדרה תלויה בה טומאה תחתיה כלים שבקדרה ר\\\"ע מטהר וחכמים מטמאין ובתוספתא פ\\\"ו קורה שהיא נתונה מכותל לכותל וקדרה תלויה בה וכו' היה פיה למעלה מודבק לקורה הרי זה מצלת משוכה הימנו בפותח טפח אינה מצלת פחות מטפח רבי עקיבא אומר מצלת וחכמים אומרים אינה מצלת וידוע שהלכה כחכמים וזהו שכתב רבינו והיתה הקורה כולה כלומר שלא תהא משוכה ממנה אפילו פחות מטפח:\",1,0],[8,374,21,5,\"וכתב הר\\\"י קורקוס ז\\\"ל ידוע דבקורה טפח מיירי כי אז מכוסה טהורה ואינה מכוסה טמאה כי הקורה שיש בה טפח נקראת אהל להביא הטומאה לקדרה ולכלים שבתוכה וכלי חרס אינו מטמא מגבו וגם דבכה\\\"ג אפי' אין טומאה תחת הקדירה עצמה הקורה מביאה טומאה לה וטומאה תחתיה היינו תחת הקורה ולכך כתב רבינו וטומאה תחתיה וקדרה תלויה בה היפך מלשון המשנה עכ\\\"ל. והא דקתני בתוספת' אם אין בין פיה לקורה פותח טפח ה\\\"ז מצלת אם יש בין פיה לקורה פותח טפח אינה מצלת אליבא דרבי עקיבא היא ולית הלכתא כוותיה:\",2,0],[8,374,21,6,\"בור שבתוך וכו'. פ\\\"ה דאהלות שם:\",1,0],[8,374,21,6,\"כתב הראב\\\"ד א\\\"א במשנה אינו כן אלא אם היתה באר חלקה וכו'. טעמו לומר שבמתניתין קתני היה נסר חלק או סרידא שאין לה גפיים טהור משמע דבאר חלקה שכפה עליה כלי שאין לו דפנות יוצאות טהור כמו אם כפה עליה נסר והטעם מפני שהכלי שאין לו דפנות אין שם כלי עליו והרי הוא כנסר חלק ורבינו כתב אם היה מכוסה בנסר חלק או בכלי המציל שיש לו דופן הרי כל מה שבבור טהור משמע שאם היה מכוסה בכלי שאין לו דופן טמא וזה היפך מה שנתבאר. וי\\\"ל שדברי רבינו כך פירושם אם כסהו בכלי שיש לו דופן טפח הרי כל מה שבבור טהור הא אם כסהו בכלי שיש לו דופן פחות מטפח כל מה שבבור טמא אבל אם כסהו בכלי שאין לו דפנות כלל לא איצטריך רבינו לפרושי דבכלל נסר חלק הוא:\",2,0],[8,374,21,8,\"החדות הבנוי וכו' עד כך מציל בכותליו. פרק י\\\"א דאהלות וכבית הלל:\",1,0],[8,374,21,8,\"כבר ביארנו וכו':\",2,0],[8,374,21,9,\"תנור ישן בתוך החדש וכו' עד כל שבתוך החדש טהור. פ\\\"י דכלים:\",1,0],[8,374,21,9,\"וכתב הראב\\\"ד א\\\"א אין הטעם שלו מספיק לא לפירושו ולא לפירוש הרב היוני כו'. נראה לי שט\\\"ס יש בהשגה זו וצריך להגיה אין הטעם שלו מספיק אלא לפירושו ולא לפי' הרב היוני כי גירסת רבינו במשנה זו ופירושו בה נכון והסכים הרא\\\"ש לדבריו וגם הראב\\\"ד מסכים כן:\",2,0],[8,374,21,10,\"סרידא של חרס שיש לה שפה וכו'. פי\\\"ב דאהלות כלומר שאין לה שפה אינה מקבלת טומאה דהוי פשוטי כלי חרס וטומאה תחתיה או על גבה טומאה בוקעת ועולה:\",1,0],[8,374,21,11,\"קדרה שכפאה ע\\\"פ החבית וכו'. תוספתא פ\\\"ז דכלים:\",1,0],[8,374,22,1,\"שולי המחצין וכו'. תוספתא פ\\\"ז דכלים. ופירוש מחצין כלי חרס והוא מלשון הגת והמחץ:\",1,0],[8,374,22,2,\"כלי חרס שנתן בו טיט עד חציו וכו'. כתב הראב\\\"ד א\\\"א לשון התוספתא אינו כן וכו'. וי\\\"ל שאינו טעות בידו שהוא ז\\\"ל מפרש דהב\\\"ע בשהקיפו צמיד פתיל וקסבר ר\\\"י שאינו מציל משום דכיון שנתן בו טיט עד חציו ביטלו מתורת כלי ושוב אינו מציל בצמיד פתיל דהו\\\"ל כלבינה שבלעה את הטבעת שאינה מצלת וחכ\\\"א שלא נתבטל מתורת כלי ואע\\\"פ שהשקיע כלים בטיט שבתוכו אם פי הכפישה צמיד פתיל הציל על הכלים שבתוכה אע\\\"פ שהם שקועים בטיט:\",1,0],[8,374,22,3,\"כלי חרס מציל בצמיד פתיל עד שינקב וכו'. בסוף פרק המצניע:\",1,0],[8,374,22,3,\"וכתב הראב\\\"ד ז\\\"ל ובגדול עד שיפחת רובו א\\\"א יש מפרשים בהיפך כלי גדול שלא נפחת רובו אלא במוציא רמון עכ\\\"ל. טעמו דלישנא דגמרא בפרק הנזכר אמר רב אסי שמעתי כלי חרס שיעורו במוציא רמון וכו' והא רבא הוא דאמר מוקף צמיד פתיל עד שיפחת רובו ל\\\"ק הא ברברבי הא בזוטרי ופירש\\\"י עד שיפחת רובו דכל כלי פתוח כתיב דרך פתח נכנסת לו טומאה ולא דרך נקביו אלא במוקף צמיד פתיל שאם ניקב במוציא רמון אינו מציל ברברבי ברוב בזוטרי במוציא רמון בטל ליה מכלי. והתוספות כתבו שר\\\"י הקשה על פי' זה ופירש רברבי במוציא רמון ובזוטרי שמוציא רמון הוא יותר מרוב סגי ברוב ודברי רבינו כפירש\\\"י ודברי הראב\\\"ד כר\\\"י.\",2,0],[8,374,22,3,\"ומ\\\"ש כיצד כלי גדול וכו'. דבריו כפי' ר\\\"ת בפרק הנזכר ולאפוקי מפרש\\\"י. ויש בספרי רבינו בדפוס ט\\\"ס שכתוב שנפחת רובו וצריך למוחקו ולכתוב במקומו חציו וכן מצאתי בספר מוגה.\",3,0],[8,374,22,3,\"ומ\\\"ש וכמה יהיה בנקב וכו'. פ\\\"ט דכלים:\",4,0],[8,374,22,6,\"תנור שהיתה סרידה על פיו וכו' עד ואינם ניצולים עד שיסתם הנקב. שם:\",1,0],[8,374,22,7,\"חבית שהיא מלאה משקין טהורים וכו' גם זה שם:\",1,0],[8,374,22,7,\"וכתב הראב\\\"ד א\\\"א ראיתי את האיש הזה משנה את המליצות וכו'. באמת כי ר\\\"ש והרא\\\"ש פירשו כפי' הראב\\\"ד ורבינו לא נ\\\"ל פירוש זה משום דהיינו דב\\\"ש וב\\\"ה בפ\\\"ה דאהלות אם כלי חרס מציל על הכל ותרתי למה לי ולפיכך פירשה בענין אחר ומה שהקשה עליו הראב\\\"ד היאך החבית והמשקין טהורים ומניקת טמאים אדרבה איפכא מסתברא י\\\"ל שמ\\\"ש שאין העקום כסתום היינו לענין שתקבל המניקת טומאה אבל החבית חשובה כסתומה ע\\\"י עקום המניקת וקל להבין טעם החילוק.\",2,0],[8,374,22,7,\"ומ\\\"ש דמניקת טהורה מפני שאין לה בית קיבול, י\\\"ל שמניקת זו היא עקומה ובמקום העיקום היא זקופה ביותר ומפני כך מתעכבים שם טפות יין וה\\\"ל בית קיבול:\",3,0],[8,374,22,8,\"חבית המוקפת צמיד פתיל וכו'. בפרק עשירי דכלים.\",1,0],[8,374,22,8,\"ומה שכתב אגף חצי הנקב וכו'. בפרק הגוזל קמא (בבא קמא דף ק\\\"ה) מייתי האי מתני' חבית שניקבה וסתמוה שמרים הצילה וקאמר עלה בעי רבא אגף חצייה מהו אמר ליה רב יימר לרב אשי ולאו משנתנו היא זו וכו' פקוקה בזמורה עד שימרח היו שתים עד שימרח מן הצדדין ובין זמורה לחבירתה טעמא דמירח הא לא מירח לא אמאי ותיהוי כי אגף חצייה הכי השתא התם אי לא מירח לא קאי אגף חצייה במידי דקאי קאי ודעת רבינו כדברי התוספות והרשב\\\"א שכתבו בסוף פרק המצניע דאגף חצייה וסתמוה שמרים קא מיבעיא ליה אי חשיבא סתימא או לא ולא איפשיטא.\",2,0],[8,374,22,8,\"ומה שכתב סתם את הנקב בזמורה וכו' עד אינו צריך למרח מן האמצע. פרק עשירי דכלים שם:\",3,0],[8,374,22,8,\"במה מקיפין וכו'. שם:\",4,0],[8,374,22,9,\"מגופת החבית שנתחלחלה וכו' עד אם מירח מן הצדדין הציל. שם וכחכמים:\",1,0],[8,374,22,9,\"כתב הראב\\\"ד מגופת החבית א\\\"א כך פירש הרב היוני ולפי לשון המשנה נ\\\"ל בה פירוש אחר וכו'. ומה שכתב אם כדבריהם הול\\\"ל מירוח שנתחלחל וכו'. יש לומר דלאו בכל מירוח שנתחלחל אמר ר\\\"י דמצלת אלא במגופת החבית שפי החבית נכנסת בתוכה ואינה נשמטת מאליה (עיין בתוספות יום טוב שם):\",2,0],[8,374,22,10,\"חמת של עור הדג וכו'. כתב הראב\\\"ד א\\\"א זאת התוספתא משובשת וכו'. מה שכתב שהתוספתא משובשת נראה דהיינו משום דקתני בה עור הדג והנייר שהלביש בה את החבית וצררן למטה אף על פי שמירח בטיט מן הצדדין אינן מצילין ומשמע דפליגא אמתני' דקתני היתה של נייר או של עור וקשרה במשיחה אם מירח מן הצדדין הציל ורצה הראב\\\"ד לומר שמאחר דאתיא דלא כמתניתין הרי היא משובשת ואין למידין ממנה ולמה פסקה רבינו ויש לומר שאף על פי שבבא אחת תהא משובשת למה לא נלמוד מבבא אחרת.\",1,0],[8,374,22,10,\"ומה שכתב ומתוכה נפרכת שהרי אמרו צמיד על פיה ולא על גבה וכו'. יש לומר דכשהכניס החבית דרך פיה בחמת שנמצא פי החמת לצד שולי החבית וצררה מלמטה היינו כעין מה שכתב בסמוך היתה של נייר או של עור וקשרה במשיחה הרי זו מצלת כלומר והוא שימרח מן הצדדין כדבסמוך ואם לא צררה לא הציל כדבסמוך ואיצטריך לאשמועינן חמת כיון שהוא כלי ועוד שהלביש בה את החבית הרי היא מהודקת ולא תיבעי צרירה קא משמע לן:\",2,0],[8,374,22,11,\"חבית זפותה וכו' עד סוף הפרק. משנה פרק י' דכלים וכחכמים:\",1,0],[8,374,22,11,\"וכתב הראב\\\"ד א\\\"א אף זו לא נ\\\"ל כפירושם וכו'. כלומר שרבינו פירש שנשבר החרס שלצד פי החבית והזפת עומד והראב\\\"ד משיג עליו שלא מצינו בחרס לשון קילוף אלא לשון שבירה ובזפת הוא שמצינו לשון קילוף בסוף ע\\\"ז (דף ע\\\"ד ע\\\"ב) גבי גת של עכו\\\"ם יקלוף את הזפת ולפיכך פי' שאין כאן שבירת חרס אלא שנתקלפה הזפת מן החרס וכו' ולדעת רבינו יש לומר דמדקתני והזפת שלה עומד ממילא משמע שהחרס שלה אינו עומד אלא נשבר קצתו והלך לו ולשון קילוף שייך שפיר כשנקלף החרס מהזפת כמו שנקלף הזפת מהחרס:\",2,0],[8,374,23,1,\"כל הכלים המצילים בצמיד פתיל וכו' עד ומפני זה גזרו שלא יציל כלי חרס על כלי שטף שבתוכו. בפ\\\"ה דאהלות ופ\\\"ק דעדיות (משנה י\\\"ד).\",1,0],[8,374,23,1,\"ומ\\\"ש ולמה לא אמרו כלי חרס של עם הארץ לא יציל על הכל וכו'. פרק חומר בקדש (חגיגה דף כ\\\"ב):\",2,0],[8,374,23,2,\"אדם שהיה נתון בתוך החבית וכו'. תוספתא דאהלות פרק ט\\\"ו:\",1,0],[8,374,23,3,\"כלי חרס שמשתמשין בהן באפר הפרה וכו'. פרק ה' דאהלות היה כלי טהור לקדש ולחטאת הכל טהור שהכל נאמנים על החטאת:\",1,0],[8,374,23,4,\"ארובה שבין בית לעלייה וכו' עד הרי זה מציל על כל מה שבעלייה. פ\\\"ה דאהלות וכב\\\"ה.\",1,0],[8,374,23,4,\"ומ\\\"ש פירשה וחזרה ונגעה בו טמאתו. תוספתא דאהלות פ\\\"ה:\",2,0],[8,374,23,4,\"היה אהל נטוי בעלייה וכו'. פ\\\"ז דאהלות וכרבי יוסי לגבי ר\\\"ש:\",3,0],[8,374,23,4,\"וכתב הראב\\\"ד שהאהל מציל בכיסוי א\\\"א אין זה הטעם כלום וכו':\",4,0],[8,374,24,1,\"בית שחלקו בקנקנים טהורות וכו'. תוספתא פ\\\"ז דאהלות והטעם משום דקי\\\"ל כלי חרס אינו מיטמא מגבו אלא מתוכו וקי\\\"ל כלי טמא אינו חוצץ בפני הטומאה.\",1,0],[8,374,24,1,\"ומה שכתב טחן בטיט וכו'. שם ובמשנה פ\\\"ו:\",2,0],[8,374,24,2,\"בית שחלקו וכו' עד ואם לאו טהורים. משנה פט\\\"ו דאהלות.\",1,0],[8,374,24,2,\"ועל מ\\\"ש רבינו היו הכלים בתוך עובי המחיצה וכו' בין שהיתה הטומאה לפנים וכו'. כתב הראב\\\"ד א\\\"א זה א\\\"א אלא אם הטומאה והכלים בחצץ וכו'. ובאמת דברי רבינו צ\\\"ע ולא מצאתי לו מקום להשען בו אלא אם נאמר דכשאין במקום הכלים טע\\\"ט בטלו לגבי הבניין והרי הם כמו הכותל עצמו שאינו בדין קבלת טומאה וכשיש במקומם טפח על טפח אינם בטלים לגבי הכותל ומקבלי' טומאה וכשהטומא' לפנים מהמחיצה בדרך יציאתה פוגעת בכלים ומטמאתן ואפי' כשהיא בבית מתפשטת הטומא' גם במה שבתוך הכותל אף על פי שאינה עוברת לפנים מהמחיצה כמו שמצינו בכותל שבין שני בתים טומאה באחד מהם וכלים בכותל ואע\\\"פ ששם שנינו מחציה וכלפי טהרה טהורים התם שאני שהם שני בתים אבל הכא שהוא בית אחד אלא שחצצו לא:\",2,0],[8,374,24,3,\"בית שהוא מלא תבן וכו' עד מפני שסתם תבן דעתו לפנותו. משנה פט\\\"ו דאהלות:\",1,0],[8,374,24,4,\"כותל שבין שני בתים וכו' עד מחצה למחצה שניהם טמאים. פ\\\"ו דאהלות:\",1,0],[8,374,24,4,\"היתה המעזיבה לאויר וכו'. תוספתא פ\\\"ז דאהלות:\",2,0],[8,374,24,4,\"ומ״ש גבי מחצה על מחצה העומד מלמעלה כנגד הטומאה טמא. שם ר״מ מטמא ור״ש מטהר ויש לתמוה למה פסק כר״מ במקום ר״ש. וכבר השיגו הראב״ד וכתב א״א מחלוקת ר״מ ור״ש הוא בתוספתא וכו'. וי״ל שטעמו של רבינו משום דמסתבר טעמיה דכיון דטומאה רצוצה היא הרי היא בוקעת ועולה ומה לנו אם היא לאויר ולא טיהרו לעומד מלמעלה כשהטומא' מחציה ולמטה אלא מפני שהטומאה פשטה בכל הבית ושוב אינה בוקעת ועולה. ועי״ל דכיון דבפ' מי שהוציאוהו (עירובין מו:) לא איפשיטא לן ר״מ ור״ש הלכה כמאן מינייהו נקטי' כדברי המחמיר. ומ״ש הראב״ד דר״מ ור״ש הלכה כר״ש איני יודע מנין לו דהא בפרק מי שהוציאוהו לא איפשיטא. גם מ״ש דספיקא לקולא קשה דהא קי״ל ספק טומאה ברה״י טמא ואפשר לומר שהראב״ד סובר דטומאה כזו שהיא במעזיבה אינה אלא מדרבנן. ועי״ל שהטעם שפסק רבינו כר״מ הוא מפני שהוא ז״ל [סבר] דפלוגתייהו באי אפשר לצמצם או לא וכיון דבעלמא קי״ל כמ״ד א״א לצמצם הכא נמי הכי נקיטינן. ודרך זה נראה יותר בדברי רבינו שתלה הדבר בא״א לצמצם:\",3,0],[8,374,24,5,\"וכן כותל המשמש את הבית וכו'. משנה פי\\\"ו דאהלות וכחכמים.\",1,0],[8,374,24,5,\"ומ\\\"ש ואינו מורכב על הכותל. כלומר שאם היה מורכב על הכותל אפילו היתה הטומאה מחציו ולחוץ הבית טמא שהטומא' פושטת בבית מאחר שהכותל מגוף הבית. ואיכא למידק כשהיתה הטומא' מחצה למחצה אמאי העומד מלמעלה טהור ומאי שנא ממ\\\"ש בסמוך גבי טומאה במעזיבה שאם היתה מחצה למחצה העומד מלמעלה טמא משום דא\\\"א לצמצם וצ\\\"ל דסבר רבינו דטפי שייך לומר בכותל שתכנס טומאה לבית ולא תתפשט למעלה ממאי דשייך לומר במעזיבה וצריך טעם למה:\",2,0],[8,374,24,5,\"נטל מהכותל מבפנים וכו'. תוספתא פ\\\"ז דאהלות אלא שהיא כתובה בשיבוש:\",3,0],[8,374,24,5,\"היתה הטומאה נתונה על גבי הכותל וכו'. תוספתא פ\\\"ז דאהלות וכת\\\"ק:\",4,0],[8,374,24,6,\"בית המשמש את הכותל וכו'. משנה פ\\\"ו דאהלות:\",1,0],[8,374,24,7,\"כותל שחצי עביו בנין וכו'. תוספתא פ\\\"ז דאהלות:\",1,0],[8,374,24,8,\"טומאה שהיתה בין קורות הבית וכו'. משנה פ\\\"ו דאהלות טומאה בין הקורות ותחתיהן כקליפת השום אם יש שם פותח טפח הכל טמא אין שם פותח טפח רואים את הטומאה כאילו היא אוטם היתה נראית בתוך הבית בין כך ובין כך הבית טמא ופירש שם רבינו תחת הקורות הוא שתהיה הטומאה בעצם הקורות לא בעצם הבנין ואמרו כקליפת השום [הוא הפלגה והכוונה] שאפילו המחיצה דקה מאד ימנע בינה ובין הבית כאשר לא יהיה בעמידתו טפח על טפח ולא תטמא הבית אבל נחשוב הטומאה כאילו היא במקום סתום אשר לא תטמא זולת מה שיהיה כנגדה לבד בעליונות ושפלות וכו' ואמנם התחייב זה הדין להיות הטומאה בתוך הקורה אמנם אם היתה בעצם הבנין הדין בו מחצה על מחצה כמו שקדם בהלכה שלפני זו וכן אם היתה הטומאה בתוך האבן יהיה הדין בה כמו היותה בתוך הקורה ואע\\\"פ שהיה [המשקוף] אשר בין הבית והעלייה סלע או הדומה לו מן האבנים ובתוספתא אמרו של בניין ידון מחצה על מחצה ושל סלע כקליפת השום וענין נראית שיהיה זאת המחיצה אשר על הטומאה ספיריי כמו הזכוכית והשוהם והדומה להם כל הבית טמא ואפילו לא יהיה במקום הטומאה טפח על טפח עכ\\\"ל.\",1,0],[8,374,24,8,\"ועל מ\\\"ש רבינו ורואין את הטומאה כאילו היא רצוצה בארץ וכו': כתב הראב\\\"ד תמה אני למה לא הזכירו במשנה למעלה במעזיבה וכו'. וליישב דעת רבינו נאמר דאין כל המקומות שוים שהרי שנינו בתוספתא של בנין ידון מחצה על מחצה ושל סלע כקליפת השום וכך מפורש במשנה פ\\\"ו דאהלות והשתא ילפינן לחלק ממעזיבה לקורה דכשם שחילקו בין כותל סלע לכותל בנין כך חילקו בין מעזיבה לקורה דמעזיבה היינו בנין ודינה ככותל בנין שחילקו בה בין כשהטומא' מחציה ולפנים לכשהיא מחציה ולחוץ וכך חילקו במעזיבה בין מחציה ולמעלה למחציה ולמטה וכשהטומאה בין הקורות דינה כמו כשהיא בכותל סלע נידון כקליפת השום וחילוק זה כתבו רבינו בפירוש משנה זו בטומאה בין הקורות ולא נאמר במעזיבה שהטומאה שבתוכה היא רצוצה ובוקעת ועולה בוקעת ויורדת מפני שהמעזיבה עשויה ליסתר והוא הטעם לכותל בנין אבל הקורה אינה עשויה ליבקע ולפיכך דינה כאילו היא טמונה בארץ והשתא מתניתין הכי פירושה טומאה בין הקורות פי' שהטומאה בתוך קורות הבית מובלעת בתוכם אפילו אין תחתיה אלא כקליפת השום אם יש שם פותח טפח כלומר שהקורה רחבה טפח שהוא שיעור להביא טומאה הכל טמא כלומר כל הבית טמא שע\\\"י אותו טפח על טפח נתפשטה טומאה בכל הבית ואם אין בקורה טע\\\"ט אינה מביאה טומאה לבית ואינה מטמאה אלא כנגדה בין למעלה בין למטה והיינו רואים את הטומאה כאילו אוטם כלומר כאילו רצוצה בארץ ולמה שפי' הראב\\\"ד דמאי דקתני יש שם פותח טפח אם יש באותו קליפת השום שתחתיה פתח פתוח בטפח הטומאה יוצאת לבית ק\\\"ל דהיינו מאי דקתני בסיפא היתה נראית בתוך הבית. וכן מ\\\"ש עוד הראב\\\"ד ומ\\\"ש במעזיבה מחציו ולמטה או מחציו ולמעלה בטומאה רצוצה שהיא בוקעת ובקיעתה למקום הסמוך לה ק\\\"ל הרי אמרו טומאה רצוצה בוקעת ועולה עד לרקיע בוקעת ויורדת עד התהום ולא אמרו שאינה בוקעת אלא למקום הסמוך לה ואפש\\\"ל דהתם לא נחתי אלא לומר דאינה מטמאה אלא כנגדה ובהא דמעזיבה לימדונו שבקיעתה למקום הסמוך לה.\",2,0],[8,374,24,8,\"ומ\\\"ש רבינו וכן אם היתה [נראית בתוך] הבית וכו'. במשנה הנזכרת היתה נראית בתוך הבית בין כך ובין כך הבית טמא ופשטה דברישא קאמר שאם אין הטומאה נראית בתוך הבית דהיינו שיש תחתיה כקליפת השום הוא דמפלגינן בין יש שם פותח טפח לאין שם פותח טפח אבל אם היתה נראית בתוך הבית דהיינו שאין תחתיה כקליפת השום בין כך ובין כך כלומר בין שיש שם פותח טפח בין שאין שם פותח טפח הבית טמא שכיון שהיא נראית בתוך הבית הרי היא בתוך הבית ורבינו כ' בפיהמ\\\"ש ענין נראית שיהיה זאת המחיצה ספיריי כמו הזכוכית והשוהם והדומה להם עכ\\\"ל:\",3,0],[8,374,24,8,\"ב' פתחים זה על גב וכו'. תוספתא פי\\\"ג:\",4,0],[8,374,24,8,\"כתב הראב\\\"ד א\\\"א גם זו התוספתא לא ידעתי את טעמה והלא טומאה רצוצה היא והלא היא נראית לתוך הפתח השני שהיא בולטת מעט עכ\\\"ל. ובמה שהקדמתי לעיל דטומאה שבבנין לית לה דין טומאה רצוצה ניחא:\",5,0],[8,374,25,1,\"עמוד העומד בתוך הבית וכו'. בפ\\\"ו דאהלות ולשון רבינו כלשון התוספתא:\",1,0],[8,374,25,2,\"טפח על טפח וכו'. זה מתבאר ממה שיבא:\",1,0],[8,374,25,2,\"כתב הראב\\\"ד והבית כולו טמא א\\\"א זה אינו אלא בשאין שם חלל טפח פנוי וכו'. לטעמיה אזיל שכתב בפ\\\"ז מהלכות אלו על בבת אין הקבר מטמא מכל סביביו עד שיהיה שם חלל טפח על טפח על רום טפח וכו' ועיין במ\\\"ש שם:\",2,0],[8,374,25,3,\"טומאה שבתוך הכותל וכו' עד ואין כותל הטמא כותלה. פ\\\"ז דאהלות:\",1,0],[8,374,25,3,\"כתב הראב\\\"ד השמיט סוף המשנה וכו'. ויש לומר שרבינו פי' במשנה כותל שנית יקרא כותל שנתנוהו על כותל אחר והיו שני כותלים קרובים מאד והיתה הטומאה דחוקה ביניהם עכ\\\"ל ולא הוצרך רבינו לכותבו כאן מפני שכבר נתבאר בדבריו כמה פעמים שטומאה רצוצה טומאה בוקעת ועולה בוקעת ויורדת:\",2,0],[8,374,25,4,\"חור גדול וכו'. תוספתא דאהלות פ\\\"ז אלא ששם שנוי הבית טמא וכן השיגו הראב\\\"ד א\\\"א אינו כן בתוספתא אלא טמא מפני שדרך טומאה לצאת משם ולא ליכנס שם עכ\\\"ל. ובאמת נראה שיש ט\\\"ס בדברי רבינו וצריך להגיה הבית טמא ואם נוסחתו היתה הבית טהור צריך להעמידה כשהחור הזה אינו פתוח לצד פנים אלא לצד חוץ.\",1,0],[8,374,25,4,\"ועל מה שכתב רבינו חור גדול שבעובי הכתלים. כתב הראב\\\"ד מצאתי נוסחא וכתוב בה וכו' ולפי זו הנוסחא אין זה הפי' מתקבל וכו'. ולדעת רבינו י\\\"ל שאין סותר פירושו שגם לפי זה פרדסק פי' שהוא נעשה לתשמיש בין בכותל בין בתיבה.\",2,0],[8,374,25,4,\"ועל מ\\\"ש רבינו רואים את החור כולו כאילו הוא אטום. כתב הראב\\\"ד א\\\"א נראה בשאין בה חלל טפח וכו'. ולא הבנתי דברי הראב\\\"ד וצ\\\"ע:\",3,0],[8,374,25,5,\"שני פרדסקין זה בצד זה וכו'. משנה סוף פ\\\"ו דאהלות פי' פרדסק חלון שהוא בתוך הכותל הנקרא בערבי בזאנא ובלשון לעז אלמאריו:\",1,0],[8,374,25,5,\"ומ\\\"ש היתה טומאה רצוצה בתוך הבנין וכו'. זה פירוש על מה שסיים בה במשנה הנזכרת ורואין את הפרדסקין כאילו הם אוטם ידון מחצה למחצה להביא את הטומאה לבית ומוכיח כפי' זה בתוספתא ומה שאנו מחשבין אותו כאטום התועלת הוא כדי לידון מחצה על מחצה שנכנס גם חלל הפרדסקין מחשבון החצי כאילו היה בנוי כולו:\",2,0],[8,374,25,6,\"כזית מן המת מודבק וכו'. ספי\\\"ב דאהלות:\",1,0],[8,374,25,7,\"כלב שאכל בשר המת וכו'. פי״א דאהלות ואפליגו בה תנאי ופסק כר' יוסי ואיתא בפרק העור והרוטב (חולין דף קכ״ו) ואוקמוה התם בתרי אוקימתי ורבינו לא הזכיר שום אחת מהם:\",1,0],[8,374,25,7,\"וכתב הר\\\"י קורקוס ז\\\"ל דסבר רבינו דע\\\"כ לא אוקימנא הכי אלא להעמיד ר' יוסי טמונה אינה בוקעת כדמוכח התם (דף קכ\\\"ה ע\\\"ב) במתניתין דתיבת המגדל וכיון דאנן קיימא לן דטומאה טמונה בוקעת נקטינן דאפילו לא יהיה בצוארו בוקעת וכיון שכן אזלינן בתר חלל הטומאה מגופו ובמשנה כתב רבינו שהולכים אחר מקום האסטומכא עכ\\\"ל:\",2,0],[8,374,25,8,\"האשה שמת עוברה וכו'. משנה בפ\\\"ז דאהלות האשה שהיא מקשה לילד והוציאוה מבית לבית הראשון טמא בספק והשני טמא בודאי אמר ר\\\"י אימתי בזמן שהיא ניטלת באגפיים אבל אם היתה מהלכת הראשון טהור שמשנפתח הקבר אין פנאי להלך אין לנפלים פתיחת קבר עד שיעגילו ראש כפיקה ובריש פרק שלישי דבכורות (דף כ\\\"ב) איפליגו אי פיקה של שתי או של ערב קאמר ומסקנא דשל שתי קאמר:\",1,0],[8,374,25,9,\"האשה שמקשה לילד וכו'. פרק ז' דאהלות וכתבתיה בסמוך:\",1,0],[8,374,25,10,\"האשה שהפילה שליא וכו'. משנה פרק המפלת (נדה דף כ\\\"ו):\",1,0],[8,374,25,11,\"מי שילדה שני ילדים וכו'. פרק שביעי דאהלות וכתב שם רבינו ההפרש בין יציאת החי תחלה וכו':\",1,0],[8,374,25,11,\"וכתב הראב\\\"ד א\\\"א אני לא הסכמתי לזה הפירוש וכו' ואיך אפשר בראשון מת וכו'. ובקושיא שניה איכא למימר דמאי טהור דקאמר מטומאת מת אבל קושיא קמייתא היא חזקה ואפשר לומר דהכא במאי עסקינן בשהקיפו הרחם בפשוטי כלי עור שאינם מקבלים טומאה שנמצא שלא נגע העובר המת באשה אלא בכלים:\",2,0],[8,374,25,12,\"האשה שילדה ולד מת אפילו נפל קטן כמו שביארנו וכו'. משנה פרק בהמה המקשה (חולין דף ע״א).\",1,0],[8,374,25,12,\"ומ\\\"ש וכן הבולע טבעת טמאה וכו'. שם:\",2,0],[8,374,25,12,\"נשלמו הלכות טומאת מת\",3,0],[8,375,1,1,\"מצות פרה אדומה שתהיה בת שלש שנים וכו'. בריש פרה וכחכמים:\",1,0],[8,375,1,1,\"ואין לוקחין עגלה ומגדלים אותה וכו'. ספרי זוטא:\",2,0],[8,375,1,1,\"כתב הראב\\\"ד א\\\"א לא מן השם הוא זה אלא שאין מקדישין מחוסר זמן למזבח וכו'. ואין זה מוכרח דאי משום הא כבר היה אפשר שיקחו אותה עגלה ולא יקראו עליה שם עד שתעשה פרה ולישנא דספרי זוטא מבואר כדברי רבינו דקתני ויקחו אליך פרה שלא יקחו עגלה ויגדלוה:\",3,0],[8,375,1,1,\"לא מצאו אלא עגלה וכו'. שם:\",4,0],[8,375,1,1,\"ולוקחין אותה מתרומת הלשכה. פרק רביעי דשקלים:\",5,0],[8,375,1,2,\"זה שנאמר בתורה תמימה וכו'. ספרי (דף ב').\",1,0],[8,375,1,2,\"ומ\\\"ש אם היתה ננסת כשירה. פ\\\"ב דפרה:\",2,0],[8,375,1,2,\"היו בה שתי שערות וכו'. בפ\\\"ב דפרה היו בה שתי שערות בתוך גומא אחת פסולה ר\\\"י אומר אפילו בתוך כוס אחד היו בתוך שני כוסות והם מוכיחות זו את זו פסולה ר\\\"ע אומר אפילו ד' אפילו ה' והן מפוזרות יתלוש ר\\\"א אומר אפילו חמשים רבי יהושע בן בתירא אומר אפילו אחת בראשה ואחת בזנבה פסולה ופסק רבינו כת\\\"ק ופירש שם רבינו בתוך גומא אחת בתוך חפירה אחת ירצה שתהיה צמיחתו אחת וכו' וכוס הוא עיגול מן הגשם יש בה כלל מן השיעור בשטח אחד והם מוכיחות זו את זו תורה אחת על חבירתה והוא שתהיה האחת קרוב מהאחרת ונכחית אליה בשטח אחד עכ\\\"ל. ולא נתבאר בדבריו כמה הוא שיעור כוס אחד וק\\\"ל שרבינו כתב תחלה בתוך גומא אחת והיינו כת\\\"ק והיאך כתב אחר כך או בתוך שני כוסות דהיינו כר\\\"י ונמצא שהוא כמזכה שטרא לבי תרי ומצאתי לרבינו שמשון שכתב ( ר\\\"י אומר לתוך כוס אחד גרסינן ולא גרסינן אפילו ובמקום שהיה שונה ת\\\"ק גומא היה שונה ר\\\"י כוס) וגומא וכוס אחד הוא אלא שחייב אדם לומר כלשון רבו שרבו של ר\\\"י היה קורא לגומא כוס והכי מוכח בתוספתא עכ\\\"ל. ואם היה דעת רבינו כן לא ה\\\"ל לפתוח בלשון גומא ולסיים בלשון כוסות ואפשר שכתב כן ללמדנו דהיינו גומא היינו כוס וה\\\"ק אפילו הן בשתי גומות פסולה אם הם מוכיחות זו את זו:\",3,0],[8,375,1,3,\"היו בה שתי שערות עיקרן מאדים וכו'. פרק ב' דפרה וכת\\\"ק.\",1,0],[8,375,1,3,\"ומ\\\"ש וגוזז במספרים וכו'. תוספתא סוף פ\\\"ק דפרה:\",2,0],[8,375,1,4,\"וצריך שישאר מן המאדים וכו'. בפ\\\"ו דנדה (נב:) שתי שערות האמורות בפרה ונגעים איפליגו תנאי בשיעורם ואמרינן בגמ' דהלכה כדברי כולם להחמיר וסובר רבינו שניטלות בזוג הוא השיעור המועט שבכולן ולפיכך בפ\\\"ב מהל' טומאת צרעת גבי שיעור שיער לבן ובפ\\\"א גבי שיעור שיער צהוב כתב ששיעורן כדי שיהיו ניטלות בזוג שזהו להחמיר ששיער לבן ושיער צהוב הם סימני טומאה ובשיעור מועט הם מטמאים וכן פסק כאן לענין פיסול ב' שערות שחורות או לבנות ששיעורו בניטלות בזוג להחמיר אבל בשיער שחור שהוא סימן טהרה כתב בפ\\\"א מהל' הנזכרות שאינו מציל עד שיהיה בהם כדי לכוף ראשן לעיקרן שזהו להחמיר שאינם מצילים עד שיהיו ארוכים אבל יש לתמוה שפסק כאן שצריך שישאר מהמאדים כדי שינטל בזוג ומאחר ששיעור זה הוא להכשיר ה\\\"ל לפסוק כדי לכוף ראשון לעיקרן שהוא השיעור הארוך והוא להחמיר. וכתב הר\\\"י קורקוס ז\\\"ל ואפשר שסובר רבינו דלא אמרינן הלכה כדברי כולן להחמיר אלא לגבי בן או בת אבל לענין פרה נקטינן כר\\\"ע דאמר כדי שיהיו ניטלות בזוג ועוד שמ\\\"ש לפרה היינו לפסול ב' שערות שחורות ובזה הלכה להחמיר אבל בעיקרן מאדים די לנו שנצריך השיעור המועט שלא יחשוב כמאן דליתיה אלא כל שיש שיעור שאנו קורים אותו שיער בקצת מקומות סגי כי לא נתמעט אלא מה שחשיב כאילו אינו דאטו אם מתחלה היו שיעור זה מי נימא דלא חשיבי שיער ודאי שיער הוי וז\\\"ש רבינו שכל שערה וכו' הרי היא כאילו אינה כלומר אבל נטילה בזוג אע\\\"פ שאינה שערה גמורה לכל דבר מכ\\\"מ לא חשיבא כאילו אינה שהרי מחמירים בשבילה:\",1,0],[8,375,1,4,\"וכתב הראב\\\"ד וצריך שישאר א\\\"א אינו מחוור וכו'. ואני אומר דודאי לא איירי אלא כשהן בתוך גומא אחת או לתוך כוס אחד שהן מוכיחות זו את זו כמ\\\"ש לעיל בסמוך דאילו כשאינן בתוך גומא אחת וכו' אינן פוסלות אפילו היו ארוכות ומאי דקתני במתניתין יתלוש נראה לי דלאו לעכובא אלא מפני מראית העין:\",2,0],[8,375,1,5,\"היו קרניה או טלפיה שחורים וכו' עד אין מראיהן פוסלין בפרה. פ״ב דפרה ופי' יגוד יחתוך כמו גודו חיננא ומפרש בפרק מומין אלו (בכורות דף מ״ד) דהא דיגוד היינו דוקא מעילוי זכרות אבל אם השחרות מגיע לזכרות אין לה תקנה שאם יחתוך שם עשאה בעלה מום ולא חשש רבינו לבאר זה מפני שסמך על מה שאמר שכל המומין הפוסלין במוקדשין פוסלין בה:\",1,0],[8,375,1,6,\"ומ\\\"ש היתה בה יבלת וכו'. בפרק ב' שם כר' יהודה לגבי רבי שמעון:\",1,0],[8,375,1,6,\"כתב הראב\\\"ד היתה בה יבלת וחתכה אע\\\"פ שעלה בה שיער אדום פסולה א\\\"א נ\\\"ל הטעם וכו':\",2,0],[8,375,1,7,\"ומ\\\"ש כל המומין וכו'. שם.\",1,0],[8,375,1,7,\"ומ\\\"ש היתה יוצא דופן וכו'. גם זה שם וכת\\\"ק.\",2,0],[8,375,1,7,\"ומ\\\"ש או טריפה. פ\\\"ק דחולין (דף ט').\",3,0],[8,375,1,7,\"ומ\\\"ש או שנרבעה. פ\\\"ב דע\\\"ז.\",4,0],[8,375,1,7,\"ומ\\\"ש שכל הפוסלים את הקדשים. בפ\\\"ב דפרה.\",5,0],[8,375,1,7,\"ומ\\\"ש ואע\\\"פ שהיא כקדשי בדק הבית וכו'. בפ\\\"ק דחולין (דף י\\\"א) אמר דטרפות פוסל בה דחטאת קרייה רחמנא ובפ\\\"ב דע\\\"ז (דף כ\\\"ב) אמרו דרביעה פוסלת בה משום דחטאת קרייה רחמנא:\",6,0],[8,375,1,7,\"ומותר ליקח אותה מן העכו\\\"ם וכו'. בפרק שני דפרה וכחכמים ואיתא בפרק אין מעמידין:\",7,0],[8,375,1,7,\"יתירה פרה על הקדשים וכו'. בפרק בתרא דסוטה (דף מ\\\"ו) ובתוספתא פ\\\"ק דפרה:\",8,0],[8,375,1,7,\"רכב עליה וכו'. בפ\\\"ב דפרה.\",9,0],[8,375,1,7,\"ומ\\\"ש נתן עליה כסות של שקין פסולה. ברפ\\\"ב דע\\\"ז (דף כ\\\"ג) ובפ\\\"ב דסוטה (דף מ\\\"ו) אמר רב יהודה אמר רב הניח עליה עורה של שקין פסלה ופי' רש\\\"י עורה של שקין אגודה של שקין פסלה ואע\\\"ג דלאו עול וכו' כדכתיב בפרשה דמלאכת עול האמורה בה אשר לא עלה עלייה לחודה ואפילו שלא משכה:\",10,0],[8,375,1,7,\"קשרה במוסרה אם היתה מורדת. בר״פ במה בהמה (שבת דף נ״ב) וכאוקימתא דרבינא דבתרא הוא:\",11,0],[8,375,1,7,\"עשה לה סנדל וכו'. בפ\\\"ב דפרה:\",12,0],[8,375,1,7,\"נעשית בה מלאכה מאליה וכו'. בפ\\\"ב דפסחים (דף ל') ופ\\\"ב דמציעא (דף כ\\\"ו ע\\\"ב) בעינן עובד דומיא דעבד מה עבד דניחא ליה אף עובד דניחא ליה.\",13,0],[8,375,1,7,\"ומ\\\"ש לפיכך אם שכן עליה עוף כשירה עלה עליה זכר פסולה. פ\\\"ב דפרה.\",14,0],[8,375,1,7,\"ומ\\\"ש ואצ\\\"ל שהמעוברת פסולה. שם (דף צ\\\"ד) ר' אליעזר אומר פרת חטאת המעוברת כשירה וחכמים פוסלים וידוע דהלכה כחכמים ומפיק לה רבינו מדין עלה עליה זכר דפסולה ולא איצטריך תנא למתני מעוברת אלא משום ר\\\"א:\",15,0],[8,375,1,7,\"והראב\\\"ד כתב א\\\"א אומר אני שר\\\"א שמכשיר במעוברת מודה וכו'. כלומר משיג על רבינו שסובר שמי שפוסל במעוברת פוסל בעלה עליה זכר ומי שמכשיר במעוברת מכשיר בעלה עליה זכר והראב\\\"ד סובר שכבר אפשר שמי שמכשיר במעוברת יפסול בעלה עליה זכר ואין דבריו מוכרחין ומ\\\"מ לשון ואין צ\\\"ל שכתב רבינו אינו נוח לי דכיון דמעוברת לא מיפסלה אלא משום דעלה עליה זכר ל\\\"ש למיתני ואצ\\\"ל דהיא היא:\",16,0],[8,375,1,7,\"הכניסה לרבקה וכו'. ברפ\\\"ב דע\\\"ז (דף כ\\\"ג) ובפ\\\"ב דמציעא (דף ל') ופ\\\"ב דפסחים:\",17,0],[8,375,1,8,\"פרה שנולד בה פיסול תפדה וכן אם מתה תפדה. בתוספתא פירקא קמא דפרה ומייתי לה פירקא קמא דשבועות (דף י\\\"א ע\\\"ב) ופריך עלה מתה תפדה וכי פודין את הקדשים להאכילן לכלבים ומשני משום עורה:\",1,0],[8,375,1,9,\"נשחטה לשם חולין וכו'. שם נשחטה תפדה שחטה על גב מערכתה אין לה פדייה עולמית ופירש\\\"י נשחטה תפדה שנשחטה חוץ למקומה ורבינו מפרש נשחטה לשם חולין ויש לתמוה על מ\\\"ש רבינו ואינה מכפרת דהא לא כתיב בה כפרה ואין לומר שטעמו משום דחטאת קרייה רחמנא דהא חטאת ששחטה לשם חולין כשירה כמו שפסק בפרק ט\\\"ו מפסולי המוקדשין. וי\\\"ל שמאחר שלא עלתה לבעלים שייך לומר בה אינה מכפרת. ועוד י\\\"ל שרמז למה שאמרו בסוף מועד קטן (דף כ\\\"ח) למה נסמכה פרשת פרה וכו' לומר לך מה פרה מכפרת אבל מכל מקום קשה מי הכניסו לרבינו לכתוב דבר שלא הוזכר לא בגמרא ולא בתוספתא. ועוד מאי קמשמע לן דאינה מכפרת פשיטא ואפשר דמשום דבאידך בבא קאמר תפדה מפני עורה כלומר דאין בה הנאה אלא בעורה בלבד קאמר דהאי אינה מכפרת וכיון שכן אף בשרה מותר בהנאה וצריך עיון:\",1,0],[8,375,1,10,\"לקחו פרה ומצאו אחרת נאה ממנה וכו'. גם זה שם:\",1,0],[8,375,1,11,\"אף כהן הדיוט כשר וכו'. ומ״ש ומפי השמועה למדו וכו'. בפרק טרף בקלפי (יומא דף מ״ו ע״ב) ונתתם אותה אל אלעזר אותה לאלעזר ולא לדורות לאלעזר איכא דאמרי לדורות בכ״ג וא״ד לדורות בכהן הדיוט ובפ״ד דפרה (משנה א) תנן ושלא בכ״ג פסולה ר' יהודה מכשיר. ויש לתמוה למה פסק דלא כת״ק ואפשר שהטעם משום דבפרק טרף בקלפי משמע דלמ״ד בכהן הדיוט ניחא טפי ועוד דתניא בספרי אותה אל אלעזר זאת נעשית באלעזר ושאר כל הפרות בכ״ג דברי ר״מ רבי יוסי ורבי יהודה ור״ש וראב״י אומרים זאת נעשית באלעזר ושאר כל הפרות בין בכ״ג בין בכהן הדיוט והכי איתא בתוספתא פ״ג דפרה דהשתא כיון דסתם מתני' ר״מ יחידאה הוא דכמה רבים פליגי עליה לית הלכתא כוותיה ובפ״ג דפרה איכא סתמא אחרינא דלא כר״מ דקתני מפרישין כהן השורף את הפרה ודייק שם רבינו מדלא קתני מפרישין כ״ג השורף את הפרה שכשירה בכל כהן:\",1,0],[8,375,1,12,\"ומ\\\"ש והעושה אותה לבוש ד' כלים של כהן הדיוט. בפ\\\"ד דפרה ובכלי לבן היתה נעשית. ובתוספתא יליף לה בג\\\"ש וכתבה רבינו שם:\",1,0],[8,375,1,13,\"כל העוסקים בפרה וכו'. בפרק טרף בקלפי (יומא דף מ״ג ע״ב) ובפ' הערל והזה הטהור על הטמא טהור מכלל שהוא טמא לימד על טבול יום שכשר בפרה ופרש״י הטהור שטהרתי לך כאן מכלל שהוא טמא לדבר אחר כגון טבול יום שטמא לתרומה דאי ס״ד טהור ממש לשתוק קרא מיניה ואנא ידענא דטמא אסור בפרה דהא חטאת קרייה רחמנא אלא מאי טהור טהור כל דהו ואשכחן טבול יום דאיקרי טהור דכתיב ורחץ במים וטהר:\",1,0],[8,375,1,14,\"הצדוקים היו אומרים וכו' הילכך היו ב\\\"ד בבית שני מטמאין את הכהן וכו'. פ\\\"ג דפרה ואיתא בפרק חומר בקדש (ד' כ\\\"ג):\",1,0],[8,375,1,14,\"וכן כל הכלים וכו'. נלמד ממה שיבא בסמוך:\",2,0],[8,375,1,15,\"החותך שפופרת של קנה וכו'. פרק חמישי דפרה וכרבי יהושע.\",1,0],[8,375,1,15,\"ומה שכתב שעשאוה כטמא מת בשביעי שלו וכו'. בפרק חומר בקדש:\",2,0],[8,375,2,1,\"מעלות יתרות עשו בטהרת פרה אדומה וכו'. מתבאר לקמן והוא בפ\\\"ק דיומא (דף ב') ובפ\\\"ג דפרה וריש פרק פרת חטאת.\",1,0],[8,375,2,1,\"ומה שכתב מפרישין אותו ללשכה מוכנת בעזרה ובית אבן היתה נקראת וכו'. שם.\",2,0],[8,375,2,1,\"ומ\\\"ש ולא היו נוגעין בו אחיו הכהנים וכו'. פ\\\"ק דיומא (דף ח' ע\\\"ב):\",3,0],[8,375,2,2,\"שבעת ימים קודם שריפת הפרה וכו'. ברפ\\\"ג דפרה ובריש יומא.\",1,0],[8,375,2,2,\"ומ\\\"ש וכן מפרישין אותו מאשתו וכו'. נלמד ממה ששנינו בברייתא בריש יומא גבי פרישת כהן גדול ז' ימים קודם יוה\\\"כ:\",2,0],[8,375,2,3,\"הלשכה שהיה יושב בה כל ז' צפונית מזרחית היה וכו'. בפ\\\"ג דפרה שם ובריש יומא. ונראה שרבינו מפרש שהטעם להזכירו שלא יקל בה מפני שהיא נשחטת בחוץ:\",1,0],[8,375,2,4,\"כל יום ויום משבעת ימי ההפרשה מזין עליו וכו'. בפ\\\"ג דפרה ודלא כר' יוסי דיחידאה הוא ועוד דבפ\\\"ק דיומא סבר רבא דלא כוותיה.\",1,0],[8,375,2,4,\"ומה שכתב חוץ מיום רביעי להפרשה וכו' עד והד' אינו צריך הזאה. בפ\\\"ק דיומא עלה ח':\",2,0],[8,375,2,6,\"בכל יום ויום מימי ההפרשה וכו'. בפרק ג' דפרה.\",1,0],[8,375,2,6,\"ומ\\\"ש ואם לא היה שם אלא אפר פרה אחת בלבד וכו'. גם זה שם:\",2,0],[8,375,2,7,\"כשמזין עליו בימי ההפרשה וכו' וכיצד ימצא איש שלא נטמא במת מעולם וכו' עד ומזין על הכהן השורף. בפ\\\"ג דפרה וכר' יוסי דאמר אל תתנו מקום לצדוקים לרדות אלא הוא נוטל ומקדש.\",1,0],[8,375,2,7,\"ומ\\\"ש ומטבילין היו התינוקות. בפ\\\"ג דפרה וצריכין היו התינוקות להזות דברי רבי יוסי הגלילי ר' עקיבא אומר לא היו צריכין להזות כלומר אבל טבילה מיהא בעו כדאיתא בתוספתא והלכה כר\\\"ע מחבירו:\",2,0],[8,375,2,8,\"תינוק שטבל וכו'. בפרק ג' דפרה לא היו עושין לא חטאת על גבי חטאת ולא תינוק על גבי חבירו:\",1,0],[8,375,3,2,\"אין שורפין את הפרה אלא חוץ להר הבית וכו'. בספרי אל מחוץ למחנה להר המשחה וכך מפורש בפרק ג' דפרה ובפרק ג' דמדות ובפרק טבול יום תניא דחוץ למחנה דכתיב בפרה אדומה היינו חוץ לשלשה מחנות דומיא דשריפת פרים. ואיתא נמי בפרק שני שעירי (יומא דף ס\\\"ח) ואם כן צריך לומר דחוץ להר הבית שכתב רבינו לאו דוקא:\",1,0],[8,375,3,2,\"ובהר המשחה היו שורפין אותה וכו' עד שלש פעמים כל אחד ואחד וא'. פ' ג' דפרה.\",2,0],[8,375,3,2,\"ומה שכתב אף מקום שריפתה וכו' תחתיהם חלון וכו'. בתוספתא דפרה פרק ב':\",3,0],[8,375,3,2,\"ומ\\\"ש כמין מגדל היינו לומר שהיתה תחתיו רחב וכל מה שיעלה הוא מיצר.\",4,0],[8,375,3,2,\"ומה שכתב ומראה המערכה היה במערב. ל' המשנה וחזיתה מערבה כי פי' חזיתא מראה וטעמו המקום שמאחזים שם האש לצד המקדש כי המקדש היה במערב הר המשחה. ופי' מגג מין גמי וכתב רבינו שמשון שהטעם מפני שהוא מין שאינו מקבל טומאה שיהא כל מעשה פרה בטהרה.\",5,0],[8,375,3,2,\"ומ\\\"ש ומקבל בשמאלו. שם כת\\\"ק ודעת רבינו שהיה מקבל הדם ביד ולא בכלי ממה שאמרו בספרי מצותה מצות יד לא מצות כלי ובפ\\\"ד כתב בפירוש שאם קיבל דמה בכלי פסולה ומשמעות לשון זה דסיפרי שהוא לעכב ועוד דכתיב בה חוקה.\",6,0],[8,375,3,2,\"ומה שכתב שמזה באצבעו הימנית. בספרי.\",7,0],[8,375,3,2,\"ומ״ש לפיכך על כל הזאה מקנח אצבעו בגופה של פרה. יש לתמוה שהרי פ' דם חטאת (זבחים דף צ״ג ע״ב) ופ״ק דמנחות (דף ז' ע״ב) מסיק דאצבעו מקנח בשפת המזרק ולא בגופה של פרה וצ״ל שסובר רבינו דההוא שקלא וטריא למאי דס״ד דקבלת דמה היה במזרק אבל לדידן שלא היה קבלת דמה אלא ביד ע״כ לומר דמקנח אצבעו בגופה של פרה שהרי לא היה שם מזרק.\",8,0],[8,375,3,2,\"ומה שכתב ושירי הדם שבאצבעו פסולים להזייה. בפרקים הנזכרים:\",9,0],[8,375,3,2,\"כתב הראב\\\"ד ומקבל הדם בשמאלו וכו'. א\\\"א אמת הוא זה שהיה מקבל ביד וכו' שהרי אמרו גמר מלהזות וכו' בשפת המזרק. בפרק דם חטאת. ומ\\\"ש ואני תמה על המדרש וכו' אבל מצותה מצות יד אמרו ולא עכוב כלומר. ומ\\\"ש ולא מצות כלי כלומר אין מצותה מן המובחר בכלי דיקא נמי דלא קתני ולא בכלי אלא ולא מצות כלי. ולדעת רבינו י\\\"ל שבספרי אמרו דיליף מלוג שמן שאין כשר אלא ביד.\",10,0],[8,375,3,2,\"ומה שכתב ומשמר לה עד שיצת האור ברובה. בספרי ובתוספתא.\",11,0],[8,375,3,2,\"ומה שכתב ותקרע בטנה. במשנה פ\\\"ג:\",12,0],[8,375,3,2,\"ומה שכתב אין פחות מטפח. בפ' המפלת (נדה דף כ״ו ע״א):\",13,0],[8,375,3,2,\"ומ״ש משקל ה' סלעים. בפ' טרף בקלפי (יומא דף מ״א).\",14,0],[8,375,3,2,\"ומה שכתב והאזוב האמור בתורה וכו'. בספרי לא אזוב יון ולא אזוב רומי ולא אזוב מדברי ולא כל אזוב שיש לו שם לווי:\",15,0],[8,375,3,2,\"ומה שכתב האזוב והארז וכו'. משנה פרק הקומץ רבה (מנחות דף כ״ז):\",16,0],[8,375,3,2,\"וכורך האזוב עם הארז בלשון של שני. פ\\\"ג דפרה.\",17,0],[8,375,3,2,\"ומ\\\"ש ומשליך אל תוך בטנה וכו'. הכי משמע שם.\",18,0],[8,375,3,2,\"ומ\\\"ש ואינו משליך קודם שיצת ברובה ולא אחר שתעשה אפר וכו'. בספרי ובתוספתא.\",19,0],[8,375,3,2,\"ומ\\\"ש בין שהשליך שלשתן כאחד וכו'. שם בתוספתא:\",20,0],[8,375,3,3,\"נגמרה שריפתה וכו' עד בין כך ובין כך היה נכתש. בפרק שלישי דפרה:\",1,0],[8,375,3,4,\"אין מכניסין כלום מאפרה להניחו בעזרה. כן יש ללמוד ממ\\\"ש לקמן בסמוך:\",1,0],[8,375,3,4,\"ושלשה חלקים היו חולקין וכו'. פ\\\"ג דפרה:\",2,0],[8,375,3,4,\"זה שמתחלק לכל המשמרות וכו'. בתוספתא.\",3,0],[8,375,3,4,\"וכן היו מצניעין מאפר כל פרה וכו'. שם.\",4,0],[8,375,3,4,\"ותשע פרות נעשו וכו'. פרק ג' דפרה וכחכמים:\",5,0],[8,375,4,1,\"אין שוחטין שתי פרות אדומות כאחת וכו'. בספרי.\",1,0],[8,375,4,1,\"ומ״ש לא רצתה פרה לצאת וכו' עד שלא יאמרו שתים שחטו. פ״ג דפרה ואיתא בפ״ג דחולין (דף ל״ב) ובפרק טרף בקלפי (יומא דף מ״ב) פלוגתא דתנאי ואמרינן איכא בינייהו דאפיק חמור בהדה דליכא למיחש שמא יאמרו ופסק כתנא קמא:\",2,0],[8,375,4,3,\"פרה שנשחטה שלא לשמה וכו' עד פסולה. פ\\\"ד דפרה וכת\\\"ק:\",1,0],[8,375,4,3,\"ומה שכתב שחטה על מנת לאכול מבשרה כו'. שם שחטה על מנת לאכול מבשרה או לשתות מדמה כשירה כך היא גירסת רבינו ואע\\\"ג דמסיים בה ר\\\"א אומר אין מחשבה פוסלת בפרה צ\\\"ל דלאו אמאי דסמיך ליה קאי דא\\\"כ היינו ת\\\"ק אלא אריש פירקא קאי דקתני שחטה שלא לשמה וכו' פסולה ועי\\\"ל דת\\\"ק לא מכשר אלא בעל מנת לאכול מבשרה או לשתות מדמה משמע הא שאר מחשבות פוסלות בה ור\\\"א פליג ואמר דאין שום מחשבה פוסלת בה.\",2,0],[8,375,4,3,\"ומ\\\"ש עשאה בבגדי זהב או בבגדי חול פסולה. תוספתא פ\\\"ג דפרה:\",3,0],[8,375,4,4,\"קיבל דמה בכלי פסולה וכו'. ספרי ובספרי זוטא מבואר יותר:\",1,0],[8,375,4,5,\"הזה בכלי אפילו אחת מהן וכו' עד כשירה. תוספתא פרק שלישי דפרה:\",1,0],[8,375,4,5,\"הזה ולא כיון כנגד ההיכל וכו'. בפרק רביעי דפרה הזה ולא כיון כנגד הפתח פסולה.\",2,0],[8,375,4,5,\"ומה שכתב וכן אם שחטה או שרפה וכו'. בראש פרק פרת חטאת זבחים (דף קי\\\"ג) וכר\\\"י.\",3,0],[8,375,4,5,\"ומה שכתב שנאמר ושחט אותה לפניו. טעמו מדסמיך ליה והזה ושרף דמשמע דהכל שוין ודין אחד להם וכדר\\\"י:\",4,0],[8,375,4,6,\"ומ״ש בד״א שהזה או שרף וכו'. בפרק הקומץ רבה (מנחות דף כ״ז ע״ב) תנו רבנן שבע הזאות שבפרה שעשאן וכו' שלא מכוונות אל פני אהל מועד פסולות וכו' והתניא וכו' כשירות וכו' רבא אמר הא והא רבנן הא דקאי מזרח ומערב ואדי הא דקאי צפון ודרום ואדי וגירסת ספרים דידן בספרי רבינו אע״פ שלא כיון כנגד ההיכל בדקדוק כשירה והראב״ד היה גורס בדברי רבינו אף על פי שלא כיון כנגד הפתח וכו' וכתב עליו א״א לא נראה בהזאה וכו' ויש ליישב אותה גירסא לדחוק ולומר שמה שצריך שיכוון ויראה פתחו של היכל הוא למצוה מן המובחר אבל כל שפניו אל ההיכל אל פני אהל מועד מיקרי אף על פי שלא יהיה כנגד הפתח:\",1,0],[8,375,4,7,\"חיסר אחת מן המתנות פסולה. בפרק הקומץ רבה (מנחות דף כ״ז) תנן שבע הזאות שבפרה מעכבות זו את זו ומפרש טעמא בגמרא משום דכתיב בה חוקה וחוקה משמע עיכובא:\",1,0],[8,375,4,7,\"טבל שתים והזה אחת וכו' כיצד טבל אצבעו טבילה ששית וכו'. תוספתא פ\\\"ג ובספרי ושנינו בפרק ד' דפרה הזה מששית שביעית וחזר והזה שביעית פסולה משביעית שמינית וחזר והזה שמינית כשירה. וכתב שם רבינו כשטבל אצבעו טבילה ששית והזה ממנה ששית ושביעית פסלה לפי שמתנאיה וכו' על כל הזאה טבילה ואע\\\"פ ששב אחר זה וטבל טבילה שביעית והזה ממנה הזאה שביעית הנה זה לא יספיק לפי שהוא כבר פסלה אמנם אם הזה מטבילה שביעית שתי הזאות שביעית ושמינית הנה היא כשירה לפי שכבר נשלמו ז' הזאות כמצותה וכל מה שיבא אחר זה לא יפסידה ואפילו שב והזה שמינית או תשיעית לא פסלה.\",2,0],[8,375,4,7,\"ומ\\\"ש אבל הכהן השורף אותה אם הוסיף פסלה. תוספתא פרק ג' דפרה:\",3,0],[8,375,4,7,\"כתב הראב\\\"ד נ\\\"ל הזייתו פסולה אבל אין הפרה נפסלת וכו'. נראה שעל מה שכתב רבינו טבל שתים והזה אחת הזייתו פסולה קאי אלא שמה שכתב ונראה לי אפילו חוץ לגתה קאמר אעפ\\\"י שמחמירים בה יותר מבמערכתה אינו ענין לכאן ובסמוך אבאר:\",4,0],[8,375,4,8,\"הוציא את הדם חוץ ממערכתה והזה פסולה. תוספתא פ' שני וז\\\"ל ניתז מידו כשהוא מזה בין חוץ לגתה בין חוץ למערכתה פסולה ראב\\\"י חוץ לגתה פסולה חוץ למערכתה לא יחזיר ואם החזיר כשירה ואם הוציא דם שבידו והחזירו כשר ור\\\"ש הביאה בפ\\\"ג וז\\\"ל ניתז מידו כשהוא מזה בין חוץ לגתה בין חוץ למערכתה פסולה ראב\\\"י חוץ לגתה פסולה חוץ למערכתה לא יחזיר ואם החזיר כשר ואם הוציא הדם שבידו והחזירו כשר ע\\\"כ. ועל פי זה נראה שהשגה שכתבתי בסמוך היה על זה שכתב רבינו הוציא הדם חוץ ממערכתה והזה פסולה ומשמע שהפרה פסולה ואין לה תקנה והראב\\\"ד סובר שלא נפסלה אלא ההזייה ההיא ולפי מה שתופס הראב\\\"ד הזייתו פסולה ט\\\"ס הוא וצריך למחוק תיבת הזייתו ומ\\\"מ מ\\\"ש והם דברי ראב\\\"י צ\\\"ע ואין להאריך:\",1,0],[8,375,4,9,\"הזה מדמה בלילה אפילו הזה שש הזיות ביום וכו'. תוספתא פ\\\"ג דפרה וטעמא משום דחטאת קרייה רחמנא וכי היכי דקרבנות פסולים בלילה אף פרה כן הכי איתא בספרי:\",1,0],[8,375,4,10,\"שחטה חוץ ממקום שריפתה וכו'. ראש פרק פרת חטאת זבחים (דף קי\\\"ב):\",1,0],[8,375,4,11,\"שרפה חוץ ממערכתה שנשחטה עליה וכו'. פ\\\"ד דפרה חוץ מגתה או בב' גתות או ששרף שתים בגת אחת פסולה:\",1,0],[8,375,4,11,\"כתב הראב\\\"ד שרפה חוץ ממערכה א\\\"א כמדומה לי זה האיש העלה בדעתו וכו'. איני יודע מהיכן הבין הרב ראב\\\"ד בדברי רבינו כן שמאחר שבמקום שרפה חוץ מגתה השנוי במשנה כתב רבינו שרפה חוץ ממערכה שנשחטה עליה וכן עשה בשרפה בשתי גתות או ששרף שתים בגת אחת הרי בהדיא שהוא מפרש דגת ומערכה חדא מילתא נינהו וע\\\"כ לומר שהיתה לו גירסא אחרת בספרי רבינו.\",2,0],[8,375,4,11,\"ומ\\\"ש ואם אחר שנעשית אפר מביא אחרת וכו'. תוספתא פ\\\"ג:\",3,0],[8,375,4,12,\"הפשיטה ונתחה וכו'. פ\\\"ד דפרה.\",1,0],[8,375,4,12,\"ומ\\\"ש ואם חיסר ממנה כלום וכו'. בספרי זוטא בשרה יכול פרט לדמה ת\\\"ל ואת דמה יכול פרט לפירשה ת\\\"ל על פרשה ישרוף:\",2,0],[8,375,4,12,\"פקע מעורה או מבשרה וכו'. תוספתא בפ\\\"ב פקע מעורה ומשערה ומבשרה חוץ לגתה יחזיר ואם לא החזיר פסולה חוץ למערכתה הרי זה מרבה עליו ושורפו במקומו ר\\\"א אומר כזית מעכב פחות מכזית אינו מעכב ומשמע לרבינו דר\\\"א לאו לאיפלוגי אתא אלא לפרושי ובילקוט כתוב הא דכזית מעכב סתמא ואפשר שכך היתה גירסת רבינו:\",3,0],[8,375,4,12,\"פקע מקרניה מטלפיה וכו'. גם זה בתוספתא פרק שני:\",4,0],[8,375,4,13,\"הפרה אינה נפסלת בלינה וכו'. תוספתא פ\\\"ג דפרה ואיתא בספרי:\",1,0],[8,375,4,14,\"שרפה אונן או מחוסר כפרה כשירה. בפ\\\"ב דזבחים (יז:) ובפ' הערל עלה ע\\\"ד וכת\\\"ק דיוסף הבבלי:\",1,0],[8,375,4,14,\"וכתבו התוס' דטעמא משום דטבול יום כשר בפרה ואונן ומחוסר כפורים אתו בק\\\"ו מטבול יום שאסור בנגיעת תרומה ומותר בפרה ובהכי ניחא דאע\\\"ג דאמרינן התם דר\\\"ע פליג ואמר מחוסר כפורים אסור בפרה לא קיימא לן כוותיה משום דסתם לן תנא בפ\\\"ב דפרה שהיתה נעשית בטבול יום:\",2,0],[8,375,4,15,\"שרפה שלא בקידוש ידים ורגלים וכו'. בפרק ד' דפרה וכתנא קמא.\",1,0],[8,375,4,15,\"ומה שכתב והיכן מקדש ידיו ורגליו עד הואיל וכל מעשיה בחוץ. בפרק שני דזבחים עלה כ' וכרבי יוחנן.\",2,0],[8,375,4,15,\"ומ\\\"ש וכן כשמטבילין את הכהן וכו'. שם:\",3,0],[8,375,4,16,\"שרפה שלא בעצים וכו'. בפ\\\"ד דפרה.\",1,0],[8,375,4,16,\"ומ\\\"ש ומצותה שלא ימעט לה עצים מן הראוי לה. בפ\\\"ד דפרה מרבין לה עצים.\",2,0],[8,375,4,16,\"ומ\\\"ש אבל מרבה הוא לה חבילי אזוב. תוספתא פ\\\"ג מרבין לה עצים אמר ר\\\"י אף כשהיו מרבים לא היו מרבים אלא חבילי אזוב שאפרן מרובה ויפה ומשמע לרבינו שר\\\"י לא בא אלא לפרש ובספרי קתני ר' יהודה אומר ישרוף שלא ימעיט את העצים מרבה הוא לה חבילי אזוב וחבילי אזוב יון לרבות את האפר ומשמע לי שעצים הצריכים לשריפה כל עצים היו מניחים אבל כשהיו מרבים עצים יותר מהצורך לא היו אלא חבילי אזוב ואזוב יון.\",3,0],[8,375,4,16,\"ומ\\\"ש אבל משתעשה אפר אם הוסיף בה אפילו עץ אחד וכו'. בפ\\\"ד דפרה לעולם מועלין בה ומרבין לה עצים ומעשיה ביום ובכהן והמלאכה פוסלת בה עד שתיעשה אפר ומשמע לרבינו דעד שתיעשה אפר קאי אמרבין לה עצים:\",4,0],[8,375,4,17,\"כל מעשה הפרה מתחלה ועד סוף אינו אלא ביום. במשנה פ״ד דפרה מעשיה ביום ובכהן ובתוספתא דפרה [פ' שלישי] כל מעשיה ביום חוץ מאסיפת האפר והמלוי והקידוש כל מעשיה בכהנים חוץ מאסיפת האפר והמילוי והקידוש וההזאה ובפרק טרף בקלפי (יומא דף מ״ב מ״ג) מייתו להו מקראי ואית דגרסי באנשים במקום בכהנים.\",1,0],[8,375,4,17,\"ומ\\\"ש והמלאכה פוסלת בה עד שתיעשה אפר. משנה סוף פ\\\"ד דפרה.\",2,0],[8,375,4,17,\"ומ״ש אבל משתעשה אפר וכו'. ומ״ש ומנין שאסיפת האפר בכל אדם מישראל חוץ מחרש שוטה וקטן וכו'. בפרק טרף בקלפי (יומא דף מ״ג) ואסף איש טהור וכו' והניח איש להכשיר את הזר פירוש דלעיל כתיב בכולה מילתא כהן והכא כתיב איש להשמיענו שכשר בכל איש טהור ולהכשיר את האשה פירוש דאי למעט טמא לא איצטריך דחטאת קרייה רחמנא והניח מי שיש בו דעת להניח יצאו חרש שוטה וקטן וכו' ויש לתמוה על רבינו שהשמיט ראיות אלו.\",3,0],[8,375,4,17,\"ומ״ש ומנין שהמלאכה פוסלת בה וכו'. בפ' טרף בקלפי (יומא דף מ״ב) אליבא דרב ובספרי.\",4,0],[8,375,4,17,\"ומ\\\"ש בספרי\",5,0],[8,375,4,17,\"רבינו שנאמר ושרף את הפרה ט\\\"ס יש כאן וצריך למחוק השי\\\"ן משנאמר ולכתוב במקומה וי\\\"ו.\",6,0],[8,375,4,17,\"ומ\\\"ש וכל העוסק בשריפתה ועשה מלאכה אחרת וכו'. משנה כתבתיה בסמוך:\",7,0],[8,375,4,18,\"שחט את הפרה ונשחטה בהמה אחרת עמה וכו'. בפרק שני דחולין (דף ל\\\"א ע\\\"ב) אמר רבא שחט פרה ושחט בהמה אחרת עמה לד\\\"ה פסולה נשחטה בהמה אחרת עמה לרבי נתן פרה פסולה בהמה כשירה לרבנן פרה כשירה בהמה פסולה פשיטא נשחטה בהמה אחרת לרבי נתן איצטריכא ליה סד\\\"א ושחט אותה אמר רחמנא ולא אותה ואת חבירתה וה\\\"ד כגון ששחט שתי פרות בהדי הדדי אבל בהמה דחולין אימא לא קא משמע לן חתך דלעת עמה דברי הכל כשירה. ופרש\\\"י נשחטה בהמה אחרת עמה בלא מתכוין. לרבי נתן דמכשיר שחיטת חולין בלא כוונה בהמה כשירה ופרה פסולה ואע\\\"ג דשלא בכוונה לא מסח דעתיה ולא מיקרי מתעסק במלאכה אחרת הואיל ושחיטתו כשירה מיפסלה משום ושחט אותה ולא אותה ואת חבירתה לרבנן פרה כשירה דהא שחיטה לבהמת חולין לאו שחיטה היא ומשום מלאכה ליכא למיפסל דשלא במתכוין לא מיקרי עסיק במלאכה אחרת אחר דטעמא דמלאכה אחרת משום דמסח דעתיה מפרה הוא והיכא דלא איכוון למלאכה אחרת ליכא היסח דעת והכי אמרינן לקמן נחתכה דלעת עמה דברי הכל כשירה עכ\\\"ל:\",1,0],[8,375,4,18,\"ויש לתמוה על רבינו שפסק בפ' ב' מהלכות שחיטה כרבי נתן דשחיטת חולין בלא כוונה כשירה וכאן פסק דנשחטה בהמה אחרת עמה פרה כשירה וזה היפך דברי רבא וצ\\\"ל שרבינו היה גורס נשחטה בהמה אחרת עמה לר\\\"נ שתיהן כשירות לרבנן פרה כשירה בהמה פסולה פשיטא סד\\\"א ושחט אותה אמר רחמנא ולא אותה ואת חבירתה ואפילו בהמת חולין נמי קמ\\\"ל:\",2,0],[8,375,5,1,\"כל העוסקים בפרה וכו'. פרק ד' דפרה.\",1,0],[8,375,5,1,\"ומה שכתב שנאמר בשוחט ומשליך עץ ארז וכו'. בספרי.\",2,0],[8,375,5,1,\"ומה שכתב וטעונין טבילה והערב שמש. בספרי.\",3,0],[8,375,5,1,\"ומה שכתב אבל המשמרה בשעת עשייתה וכו'. בפרק הפועלים (בבא מציעא דף צ״ג):\",4,0],[8,375,5,2,\"כל מקום שנאמר בתורה בטומאות וכבס בגדיו וכו'. בספרי פרשת שמיני גבי נבילה מנין לעשות שאר כלים כבגדים ת\\\"ל וטמא ובפרשת מצורע גבי זב מסיים בה לאחר פרישתו מטמא משקין וכו' ואינו מטמא בגדים ובפרק ה' דזבים איתיה גבי כלל אמר רבי יהושע ובפירוש המשנה פירקא קמא דכלים ביארו זה רבינו ורבינו שמשון:\",1,0],[8,375,5,2,\"וכן כל העוסקים בפרה וכו'. פרק ד' דפרה.\",2,0],[8,375,5,2,\"ומה שכתב אבל אחר שיפרוש ממעשיה וכו'. שם ביארה רבינו:\",3,0],[8,375,5,2,\"והפרה עצמה אינה מטמאה לא אדם ולא כלים שנגעו בה וכו'. בפרק שמיני דפרה:\",4,0],[8,375,5,3,\"ומ\\\"ש בד\\\"א בזמן שנשרפה כמצותה וכו' עד אינו מטמא בגדים. פ\\\"ד דפרה ואיתא בפ\\\"ב דחולין (דף כ\\\"ט ע\\\"ב):\",1,0],[8,375,5,4,\"ומ\\\"ש השלים לכנוס את אפרה וכו'. כתב הר\\\"י קורקוס ז\\\"ל דהיינו מדכתיב וכבס האוסף את וכו' משמע שאין טומאה למתעסק בה אחר כך אכן גבי פרים יתבאר בסמוך שאין בהם טומאה רק עד שיעשו אפר:\",1,0],[8,375,5,4,\"ולא הפרה בלבד אלא כל החטאות הנשרפות וכו'. משנה בסוף פרק טבול יום (זבחים דף ק״ד) וברייתא בסוף פרק שני שעירי (יומא דף ס״ח ע״ב).\",2,0],[8,375,5,4,\"ומה שכתב מפי השמועה למדו שזה בנין אב וכו'. בסוף פרק התערובות (דף פ\\\"ג) ובספרי:\",3,0],[8,375,5,4,\"במה דברים אמורים שלא אירע בהם פיסול וכו'. בסוף פרק טבול יום (זבחים דף ק״ד ע״ב):\",4,0],[8,375,5,4,\"ואי זהו שורף וכו'. בס״פ טבול יום (זבחים דף ק״ו).\",5,0],[8,375,5,4,\"ומ\\\"ש כך למדו מפי השמועה וכו'. שם:\",6,0],[8,375,5,5,\"מאימתי מטמאים בגדים וכו'. משנה סוף פרק טבול יום (זבחים דף ק״ד) ופרק שני שעירי (יומא דף ס״ח ע״ב):\",1,0],[8,375,5,5,\"יצאו וחזרו לעזרה וכו'. בס״פ טבול יום (זבחים דף ק״ה) בעי ר״א פרים ושעירים הנשרפים שיצאו וחזרו מהו מי אמרינן כיון דנפקי להו איטמו להו או דילמא כיון דהדור הדור וכו' תא שמע היו סובלים אותם במוטות וכו' ואי ס״ד כיון דנפקי להו איטמו הנך דאיכא גוואי [נמי] ליטמו אמר רבינא והא בעינן ואחר יבא אל המחנה וליכא אלא ר״א היכי בעי לה כגון דנקיטי לה בבקולסי ופירש רבינו כפי' התוס' דקס״ד דבעי ר״א אם חזרו הפרים לעזרה ובאו אנשים אחרים ונכנסו בעזרה ונשא אותם בתוך העזרה להוציאן מי אמרינן כיון שמתחילה יצאו יטמאו בגדים אלו או לא ת״ש היו סובלים אותן וכו' ואי ס״ד כיון דנפקי להו איטמו הנך נמי ליטמו ומסיים בה רבינא ואמר ותיסברא שיהא תלוי ביציאת פר לבדו והא בעינן ואחר יבא אל המחנה אלא פשיטא דבעינן שיצאו גם האנשים עם הפרים ולכך דגוואי לא מיטמו וגם בבעיא דילך אנשים אחרים פשיטא שטהורים אלא ר״א היכי בעי בבקולסי שהאנשים יצאו וחזרו ובאו אנשים אחרים ועמדו חוץ לעזרה ומוציאים הפרים שבתוך העזרה במקלות מי אמרינן כיון שהפרים כבר יצאו והאנשים עומדין בחוץ חשיב כאילו מוציאין אותם מפתח העזרה ולחוץ או לא ולא איפשיטא ונתבארו דברי רבינו:\",2,0],[8,375,5,5,\"כתב הראב\\\"ד יצאו וחזרו לעזרה וכו' א\\\"א הסוגיא בפרק טבול יום כך היא וכו'. ומאחר שרבינו יש לו הודאת בעל הריב אין צורך להטפל בו:\",3,0],[8,375,5,6,\"ומאימתי מטמא וכו'. משנה פ\\\"ו דיומא (דף ס\\\"ז ע\\\"ב) וכת\\\"ק.\",1,0],[8,375,5,6,\"ומ\\\"ש עד שעת דחייתו ולעזאזל וכו': כתב הראב\\\"ד אבל אחר שדחהו א\\\"א דבריו סתומים וכו'. ול\\\"נ דפשיטא שכוונת רבינו כפירוש השני. ומ\\\"ש שיש לו פנים במשנת זבים הוא מדתנן בפ\\\"ה. ומ\\\"ש דלא תימא לאחר דחייתו אלא אפילו קודם דחייתו אם פי' הוא ועשהו אחר וכו' טעמו לומר דא\\\"כ למה תלה רבינו הדבר באחר שדחהו אפילו קודם שדחהו נמי אפשר וי\\\"ל שאע\\\"פ שהדין כן הוא שמאחר שפירש מדחייתו שוב אינו מטמא כלים מ\\\"מ רבינו אורחא דמילתא נקט שאין דרך להניח מצותו שיעשנה אחר:\",2,0],[8,375,5,7,\"הנוגע בפרים וכו'. בפ״ח דפרה השורף פרה ופרים והמשלח את השעיר מטמא בגדים פרה ופרים ושעיר המשתלח עצמן אינן מטמאים בגדים ובסוף פרק טבול יום (זבחים דף ק״ה) פרה ופרים ושעיר המשתלח וכו' והם עצמן אין מטמאין בגדים אבל מטמאים אוכלים ומשקים דברי ר״מ וחכמים אומרים פרה ופרים מטמאים אוכלים ומשקים שעיר המשתלח אינו מטמא שהוא חי והחי אינו מטמא בגדים:\",1,0],[8,375,5,7,\"ויש לתמוה על דברי רבינו שהם דלא כר״מ ודלא כחכמים ובתוספתא דפרה ר״ש אומר פרה מטמאה טומאת אוכלים שהיה לה שעת הכושר פרים הנשרפים ושעירים הנשרפים אינם מטמאים טומאת אוכלין שלא היה להם שעת הכושר ונראה שרבינו פסק כמותו ולפי זה לדעת רבינו פרה מטמאה טומאת אוכלים וכמו שנראה ממ״ש לעיל ופרה עצמה אינה מטמאה לא אדם ולא כלים משמע הא אוכלים ומשקים מטמאה אבל קשה למה הניח רבינו דברי חכמים ופסק כר״ש וכתב הר״י קורקוס ז״ל שאפשר שטעמו מפני שדברי ר״ש הוזכרו בכמה מקומות בגמרא פי״ב דמנחות (דף ק״א ע״ב) ופ' שבועות שתים (שבועות דף יא:) ופרק מרובה (בבא קמא דף ע״ז) ופרק אותו ואת בנו (חולין דף פ״א ע״ב) ואין זה כדאי לפסוק כמותו וצ״ע:\",2,0],[8,375,6,1,\"המים שנותנין על אפר פרה וכו'. מפורש בתורה בפרשת פרה ונתן עליו מים חיים אל כלי ושנינו בפרק ה' דפרה ובפ\\\"ק דידים שאין ממלאין אלא בכלי.\",1,0],[8,375,6,1,\"ומ\\\"ש שממלאין מנהרות המושכים. יתבאר בסוף פרק זה:\",2,0],[8,375,6,2,\"הכל כשרים למלאות המים חוץ מחש\\\"ו. נראה דיליף לה מקידוש:\",1,0],[8,375,6,2,\"והכל כשרים לקדש חוץ מחש״ו. משנה פרק ה' דפרה וכת״ק ובפרק קמא דערכין (דף ג') אמרו דהכל כשרים לקדש לאתויי אשה וטעמא דמתניתין מפרש בפרק טרף בקלפי (יומא דף מ״ג):\",2,0],[8,375,6,2,\"ואין ממלאין ואין מקדשין אלא בכלי ואין מזין אלא בכלי. פ\\\"ק דידים:\",3,0],[8,375,6,2,\"והמילוי והקידוש כשרים בלילה. תוספתא בפרק ג' דפרה.\",4,0],[8,375,6,2,\"ומ\\\"ש אבל אין מזין ואין טובלין אלא ביום. פי' אין טובלין היינו טבילת אזוב וכן שנינו בסוף פרה טבל וכו' את האזוב ביום והזה בלילה בלילה והזה ביום פסול אבל הוא עצמו טובל בלילה ומזה ביום וכתבו הראב\\\"ד בהשגה כמשיג על רבינו שקיצר בדבר הצריך ביאור ורבינו סמך על המבין שמאחר דבמילוי וקידוש והזאה עסיק ואתי ממילא משמע דטבילה דקאמר בטבילת אזוב קאמר ולא תיקשי לך שהקדים אין מזין לאין טובלין לישנא דמתני' נקט וכ\\\"כ בפירוש בפי\\\"א טבילת האזוב במים והזאתו ממנו ביום השלישי וביום השביעי אחר שתנץ החמה ואם עבר ועשה משעלה עמוד השחר כשר כמו שביארנו. ומ\\\"ש שם ואחר שיזה עליו ביום השביעי טובל ביום ומעריב שמשו והרי הוא טהור לערב לאו למימרא שצריך לטבול ביום ולאפוקי אם טבל בלילה אלא לקצר זמן טהרתו כתב כן לומר שאם טבל בו ביום כיון שהעריב שמשו הוא טהור אבל אם טבל אחר אותו היום בין ביום בין בלילה אינו טהור עד שיעריב שמשו אחר טבילתו.\",5,0],[8,375,6,2,\"ומ\\\"ש וכל היום כשר להזאה ולטבילה. משנה בספ\\\"ב דמגילה (דף כ' ע\\\"ב):\",6,0],[8,375,6,3,\"בכל הכלים ממלאין ומזין וכו'. בפ\\\"ה דפרה בכל הכלים מקדשין אפילו בכלי גללים בכלי אבנים בכלי אדמה ובספינה מקדשין בה וסובר רבינו דה\\\"ה למילוי והזאה.\",1,0],[8,375,6,3,\"ומ\\\"ש וא' כלי חרס ואחד כל הכלים וכו'. בספרי.\",2,0],[8,375,6,3,\"ומ\\\"ש אבל אין ממלאין ואין מקדשין וכו'. בפרק ה' דפרה ופ\\\"ק דידים.\",3,0],[8,375,6,3,\"ומ\\\"ש ולא בביצת התרנגולת. בפ\\\"ה דפרה וכחכמים.\",4,0],[8,375,6,3,\"ומ\\\"ש ולא בשוקת שבסלע. שם.\",5,0],[8,375,6,3,\"ומ\\\"ש אבל ביצת היוצרים כשירה. שם וכת\\\"ק:\",6,0],[8,375,6,4,\"שולי כלי עץ וכו'. תוספתא פ\\\"ד דפרה ובפ\\\"ח דכלים ודין מגופה שחסר בתוספתא שלנו ט\\\"ס הוא כי ר\\\"ש הזכירה בתוספתא שהביא:\",1,0],[8,375,6,4,\"וביצת הנעמית כשירה לקדש בה. תוספתא פ\\\"ד.\",2,0],[8,375,6,4,\"ומ\\\"ש ואין צ\\\"ל שכשירה למלאת בה ולהזות ממנה, כלומר דעיקר מאי דילפינן דבעינן כלי היינו מדכתיב מים חיים אל כלי כמו שנתבאר וכיון דחשיבא כלי לקידוש אתי מילוי והזאה בכ\\\"ש:\",3,0],[8,375,6,5,\"כלי שחיברו בארץ או בסלע וכו'. בפרק ה' דפרה השוקת שבסלע אין ממלאין בה וכו' היתה כלי וחיברה בסיד ממלאים בה ומקדשים בה ומזין ממנה.\",1,0],[8,375,6,5,\"ומ\\\"ש עשה לה עטרה של טיט וכו'. שם:\",2,0],[8,375,6,6,\"כלי חרס שניקב בכונס משקה וכו'. מימרא דרבא בסוף פרק המצניע (שבת דף צ\\\"ה ע\\\"ב):\",1,0],[8,375,6,7,\"כלי שניקב מלמטה וכו' עד ולהזות ממנו. בפרק חמישי דפרה שם:\",1,0],[8,375,6,8,\"הזולף מים מן המעיין וכו'. תוספתא דפרה פרק חמישי ואע\\\"ג דבנוסחא דידן בתוספתא כתוב כשר ט\\\"ס הוא וצריך להגיה ולכתוב פסול וכך כתבה רבינו במשנה פרק ו' דפרה:\",1,0],[8,375,6,8,\"נתן את החבית במים וכו'. בפרק ו' דפרה נתן ידו או רגלו או עלי ירקות כדי שיעברו המים לחבית פסולים עלי קנים ועלי אגוזים כשרי' זה הכלל דבר שהוא מקבל טומאה פסול ודבר שאינו מקבל טומאה כשר ובפרק ב' דזבחים יליף מקרא:\",2,0],[8,375,6,9,\"המפנה המעיין וכו'. פרה סוף פרק ששי:\",1,0],[8,375,6,10,\"הים הגדול כמקוה וכו'. בפרק שמיני דפרה כל הימים כמקוה שנאמר ולמקוה המים קרא ימים דברי רבי מאיר רבי יהודה אומר הים הגדול כמקוה לא נאמר ימים אלא שיש בו מיני ימים הרבה רבי יוסי אומר כל הימים מטהרים בזוחלין ופסולים לזבים ולמצורעים ולקדש מהם מי חטאת ופירש רבינו רבי יהודה אומר שהים המקיף לבד הוא אשר דינו דין המקוה ולא יחשב כמעיין ואמנם שאר הימים הנה הם כמו מי המעיין וראויה בהם טבילה לזבים ולקדש בהם מי חטאת וכו' ואמר רבי יוסי ששאר ימים זולת הים הגדול נחשבים כמעיין לענין שיטהרו בזוחלין וכו' ונחשבים כמקוה לענין שהם פסולים למי חטאת ולטהרת מצורע ולטבילת הזב והלכה כרבי יוסי עכ\\\"ל בפירוש המשנה אבל כאן נראה שפסק כר\\\"י דמכשיר בשאר ימים לקדש מי חטאת:\",1,0],[8,375,6,10,\"ויש לתמוה עליו דהא קי\\\"ל הלכה כרבי יוסי לגבי רבי יהודה ועוד קשה שבכאן כתב הים הגדול כמקוה לפיכך אין ממלאין ממנו לקידוש ושאר הימים כמעיין משמע דשאר ימים ממלאין מהם מים לקידוש דלענין זה קאמר שהם כמעיין כגוונא דקתני רישא גבי ים הגדול שהוא כמקוה ובפרק תשיעי מהלכות מקואות כתב כל הימים מטהרים בזוחלין ופסולים לזבים ולמצורעים ולקדש בהם מי חטאת והרי הסתירה מבוארת בדין שאר ימים וע\\\"ק שכאן חילק בין ים הגדול לשאר ימים לענין מילוי לקידוש ושם סתם וכתב דין כל הימים בשוה ולא חילק בין ים הגדול לשאר ימים ושם בפרק הנזכר אבאר.\",2,0],[8,375,6,10,\"ומ\\\"ש וכל הנהרות פסולין לקדש מהם מי חטאת: כתב עליו הראב\\\"ד תמה אני על זה האיש שהניח המשנה בעבור התוספתא וכו'. ואפשר לומר שדעת רבינו לומר דמתני' לא פליגא אתוספתא דקתני כל הנהרות פסולים וטעם פיסולם יש מהם מפני שהם מי ביצים ויש מהם מפני שהם מי תערובת ובמתניתין מפרש שמי קרמיון ומי פיגה טעם פיסולם מפני שהם מי ביצים ומי ירדן ומי ירמוך טעם פיסולם מפני שהם מי תערובת ועל הראב\\\"ד יש לתמוה לפי מאי דסבר דמתניתין פליגא אתוספתא דעדיפא מינה הוה ליה למפרך שדבריו סותרין את דבריו שכתב בראש פרק זה להכשיר למלאות מהנהרות המושכין ועל כרחנו צ\\\"ל דהתם בידוע שאינם מי תערובות דיקא נמי דקתני המושכים כלומר שהם מושכים מעצמם בלי שום תערובות והכא כשיש לחוש למי תערובות ומי הירדן ומי ירמוך דפסלה מתניתין מפני שהם מי תערובות לדוגמא נקטינהו ולאו דוקא אלא ה\\\"ה לכל נהרות שיש לחוש בהן למי תערובות וסיפא דמתניתין הכי מוכחא בהדיא דקתני ואלו הם מי תערובות אחד כשר ואחד פסול שנתערבו שניהם כשרים ונתערבו כשרין ור\\\"י פוסל ואי מי ירדן ומי ירמוך דוקא אין מקום לסיפא דמתני' זו ובהכי אתי שפיר התוספתא ומתני' בלא פלוגתא דתוספתא בשיש לחוש למי תערובות עד שיודע שאין בהם תערובות פסול:\",3,0],[8,375,6,11,\"והמים הנגררים וכו'. יתבאר בפ\\\"ט דמקואות:\",1,0],[8,375,6,11,\"והזוחלין מן המעיין וכו'. בפ\\\"ה דמקואות הזוחלין כמעיין:\",2,0],[8,375,6,12,\"מים המוכים והמכזבים פסולין וכו' עד בשני בצורת. פ\\\"ח דפרה. וא\\\"ת איך כתב רבינו הים הגדול כמקוה ואינו כמעיין לפיכך אין ממלאין ממנו לקידוש ומאי איריא משום דאינו כמעיין תיפוק לי דאפילו היה כמעיין נמי היה פסול מטעם שמימיו מלוחים וי\\\"ל שיש מקואות בתוך הים שהם מים מתוקים כמו שהוא ידוע לספנים שמכירים המקומות ההם כשעוברים עליהם ושואבים מהם ושותים ובמים הנשאבים מאותם המקומות הוא דאיצטריך למפסלינהו מפני שאינו כמעיין. ועי\\\"ל דמלוחין לא מיפסלי למי חטאת אלא כשאין תקנה למליחותן אבל מי הים יש תקנה למליחותן י\\\"א ע\\\"י כלי חרס חדש שיסתמו פיו וישקעוהו בתוך הים והמים שהוא מוצץ מאחוריו לתוכו כדרך כלי חרס חדש הם מתוקים וי\\\"א על ידי תקונים אחרים וכיון שיכולין להמתק לא מיפסלי מטעם שהם מלוחים:\",1,0],[8,375,6,12,\"ומ\\\"ש או שהיו מימיהם פעמים מרובים וכו'. תוספתא פ\\\"ח דפרה.\",2,0],[8,375,6,12,\"ומ\\\"ש ומעיין היוצא בתחילה כשר וכו'. שם וכחכמים:\",3,0],[8,375,6,13,\"מי ביצים ומי הירדן וכו'. שם במשנה ופי' מי ביצים מלשון היגאה גומא בלא ביצה וכתבו התוס' בפ\\\"ק דסנהדרין (דף ה' ע\\\"ב) בד\\\"ה פסולין שטיט ועפר מעורב בהם והוי חציצה בין מים לכלי דקרא כתיב מים חיים אל כלי וכן פירש\\\"י:\",1,0],[8,375,6,13,\"ואלו הם מי התערובות וכו' עד ממלאין מהם. גם זה משנה שם וכחכמים:\",2,0],[8,375,6,14,\"המים שנשתנו וכו'. גם זה משנה שם:\",1,0],[8,375,6,15,\"באר שנפל לתוכה חרסית או אדמה וכו'. גם זה משנה שם וכר\\\"ע:\",1,0],[8,375,6,15,\"נפל לתוכה שטף של מימי גשמים וכו'. שם בתוספתא הכל שוים בבאר שירד לתוכה שטף של מימי גשמים שהוא צריך להמתין עד [שיחזרו המים] לכמות שהיו ומפרש רבינו שנעכרו המים שבבאר מחמת מי גשמים וקתני שצריך להמתין עד שיחזרו המים צלולים כמות שהיו ואע\\\"פ שבנפל לתוכן חרסית או אדמה א\\\"צ להמתין שתיצל הכא צריך להמתין:\",2,0],[8,375,6,15,\"כתב הר\\\"י קורקוס שהטעם מפני שמים במים מתערבים יותר:\",3,0],[8,375,6,16,\"אמת המים הבאה מרחוק וכו'. משנה שם וכת\\\"ק:\",1,0],[8,375,7,1,\"המלאכה פוסלת במים קודם שיתקדשו וכו'. יתבאר בסמוך.\",1,0],[8,375,7,1,\"ומ\\\"ש כיצד הממלא מים לקידוש וכו'. בפרק ד' דפרה המלאכה פוסלת במים עד שיטילו את האפר ופירש רבינו המים אשר יובאו לקידוש לא יותר לו שיתעסק בדבר אחר כל עוד שישאבם ולא בעת נושאם ולא בעת יציקתם מכלי אל כלי ובכלל כל עוד שלא יושם בם אפר הפרה המלאכה פוסלת ואם השליך בם האפר וכו' לא יפסלו בעשיית מלאכה ולא בשעת הזאה וכו' ואמרו בספרי אין לי מלאכה פוסלת אלא בפרה במים מניין ת\\\"ל והיתה לעדת בני ישראל למשמרת למי נדה ר\\\"ל שמי נדה כמו פרה כמו שהפרה נפסלת במלאכה וכו' כן המים ואמרו שם יכול אפילו קידשו ת\\\"ל למי נדה כבר הם מי נדה ר\\\"ל שהם יפסלו במלאכה כל עוד שיחשוב בהן להיות מי נדה אמנם אם שבו מי נדה לא יפסלו במלאכה עכ\\\"ל:\",2,0],[8,375,7,2,\"השכר פוסל בקידוש ובהזייה. משנה פרק עד כמה (בכורות דף כ״ט) הנוטל שכרו להזות ולקדש [מי חטאת] מימיו מי מערה ואפרו אפר מקלה:\",1,0],[8,375,7,2,\"ומה שכתב אבל נוטל הוא שכר למלאות את המים או להוליכן. שם בגמרא ובסוף פרק האיש מקדש (קידושין דף נ\\\"ח ע\\\"ב).\",2,0],[8,375,7,2,\"ומה שכתב היה המקדש או המזה זקן וכו' עד כפועל בטל של אותה מלאכה. שם במשנה:\",3,0],[8,375,7,3,\"הממלא באחת ידו וכו'. בפ\\\"ז דפרה.\",1,0],[8,375,7,3,\"ועל מ״ש רבינו שמילוי מלאכה היא כתב הראב״ד א״א דעתי בכל אלו לא משום מלאכה הוא נפסל וכו'. וי״ל שרבינו סובר דאם איתא לא לישתמיט תנא לאדכורי בשום דוכתא טעמא דמלאכה משום היסח הדעת. ומ״ש שיש לו שורש במסכת גיטין הוא בפרק הניזקין (גיטין דף נ״ג) דאותיבנא למאן דאמר היזק שאינו ניכר שמיה היזק מדתניא העושה מלאכה במי חטאת פטור מדיני אדם ומשני בששקל בהם משקלות ופטור משום דלא עשה מעשה בידים והא אמר רבא מי חטאת ששקל בהם משקלות כשירה וכו' אידי ואידי כנגדן ולא קשיא הא דאסח דעתיה הא דלא אסח דעתיה וי״ל לדעת רבינו דההיא דהניזקין שאני דמיירי באחר שאינו בעל המים שאינו פוסל במלאכה אלא מטעם היסח הדעת וכמ״ש רבינו שמשון בפ״ט אמתניתין דשתת מהם בהמה או חיה ונראה שמפני שהרגיש הראב״ד בדחייה זו לא כתב שיש ראיה לזה במסכת גיטין אלא ויש לה שורש כלומר יש קצת סמך לזה במסכת גיטין לא ראיה גמורה דהא איכא למידחי כדאמרן. וא״נ התם בשלא עשה בה מלאכה שלא שקל בגופן אלא כנגדן ומש״ה בעי היסח הדעת אבל אם עשה מלאכה בגופן אפילו לא הסיח דעתו מהן פסולין וכן מתבאר שם בגמרא ועל הראב״ד קשה דכיון דבההוא אוקימתא אמרינן דשוקל משקלות כנגדן לא מיפסלי אא״כ הסיח הכא נמי לא הו״ל למיפסל במתני' בעושה מלאכה שלא בגופן אא״כ הסיח דעתו ומדסתים לה במתני' סתומי משמע דלית לן לפלוגי בהכי בעושה מלאכה:\",2,0],[8,375,7,4,\"הממלא לאחרים וכו'. רבינו כתב בפירוש המשנה בפרק ז' דפרה דהכי איתא בתוספתא פרק ה' והטעם שכל שזה גמר מה שעליו לעשות לא איכפת לן אם יעשה מלאכה ומאחר שזה הממלא לאחרים אינו הוא המקדש אלא האחרים כל אחד מקדש את שלו כיון שגמר מילוי כל אחד אין לו בה עסק עוד ויכול למלאות אחרת:\",1,0],[8,375,7,4,\"מילא לעצמו חבית אחר חבית וכו'. יתבאר בסמוך:\",2,0],[8,375,7,4,\"ומה שכתב הראב\\\"ד וחבית בפני עצמה לשון המשנה ונמלך לקדשן קידוש אחר עכ\\\"ל. לא הבנתי דבריו שזה אינו אלא נמלך לקדשן ה' קידושין השנוי במשנה.\",3,0],[8,375,7,4,\"ומ\\\"ש שהראשונה נפסלת. א\\\"א לא יספיק זה הטעם וכו' לטעמיה אזיל שרצה לתלות הטעם בהיסח הדעת:\",4,0],[8,375,7,5,\"ומ\\\"ש רבינו חמשה שמלאו חמש חביות לקדשן חמשה קידושין וכו' עד הרי כולן כשרים. משנה רפ\\\"ז דפרה וכתב עלה רבינו וזה לשונו תהיה זוכר למה שקדם מהיות המלאכה פוסלת במילוי עד שיטיל את האפר וכבר התבאר בתוספת' שהיחיד אם מילא לאחרים ואפילו מילא להם אלף כלים לאלף קידושין הנה זה מותר ואם מילא לעצמו כלי אחר כלי הנה המילוי הראשון כבר נפסל לפי שכבר עשה מלאכה קודם שישליך בו האפר וזאת המלאכה הוא המילוי השני כאשר מילא זה בהיות שני קידושין אמנם מילא כלים רבים פעם אחר פעם לשומם כולם קידוש אחד הנה זה מותר לפי שהכל דומה כמו מי ששאב בפעם אחת. וה' קידושין הוא שישליך האפר בכל חבית וחבית לבד וקידוש אחד שיערב המימות כולם וישליך אפר בכולם בפעם אחת הנה על זה השורש אמר שאם היו רבים ומילא כל אחד מהם כליו לקדשו בפני עצמו אחר הוטב בעיניהם לשום הכל בקידוש אחד או בהיפך כולם כשרים לפי שלא הגיע בזה מה שיחייב פסלות אמנם אם יהיה יחיד ובא לקדשן ה' קידושים ומילא אחת אחר אחת הנה הראשונה נפסלה מפני שאיבת השניה וכן השניה נפסלה מפני שאיבת השלישית וכן כולן אלא החבית האחרונה שלא נעשה אחריה מלאכה היא כשירה וכו' ואם נהפך הענין ומילאן זו אחר זו לקדשן קידוש אחד וכו' ושב לקדשן ה' קידושין הנה החבית שישליך בה האפר תחילה כשירה בין שהשליכה בחבית שמילא ראשונה או באחרונה לפי שהמים כולם כשרים לפי שבמילוי לא נתחדש בה פסלות וכל מה שיקדש משאר החביות [פסול לפי שכל מה שנשאר מן המים נשארו פסולים לפי שהמילוי] על קידוש אחד נתמלא ואם אמר לאחר קדש לך אלו (מי שיקדש החביות) והוא יעמוד במקומו אין כשר אלא חבית שקידש ראשונה להיותו כולו מילוי אחד ואם אמר קדש לי את אלו כולם כשרים לפי שיקדש אדם לזולתו קידושין רבים זה אחר זה ולא יהיה בזה פסלות כמו שביארנו בתוספתא שמי שיקדש לחבירו זה אחר זה כולם כשרים לפי שאינו הוא אשר מילא עכ\\\"ל. ועל דרך זה פירש רבינו שמשון וכתב ונמלך לקדשן ה' קידושין שקידש זו לעצמה וזו לעצמה אין כשר אלא זה שקידש ראשון לפי שהקידוש ראשון חשוב מלאכה לאחרים שהיו ממולאים ולא ניתן לתוכו אפר ועד שיתן את האפר מלאכה פוסלת במים כדתנן בספ\\\"ד קדש לך את אלו אמילאן לקדש קידוש אחד קאי אין כשר אלא ראשון דכיון שנתן לו נעשו שלו וכאילו ימלאן הוא והקידוש שקידש ראשון חשיב מלאכה לפסול כל האחרים קדש לי את אלו כולם כשרים כי הממלא לא עשה מלאכה והמקדש אין המים שלו שיפסלו האחרים על ידו עכ\\\"ל:\",1,0],[8,375,7,5,\"ומ\\\"ש שהרי לקידוש אחד מלאם. א\\\"א יש כאן עירבוב דברים ודרך אחרת שלא מדרך המשנה ואין כאן המלכה כלל וכו'. רצה לדחות דברי רבינו בדבריו כדי לקיים דבריו שנתן טעם משום היסח הדעת ונדחק בפירוש המשנה כדי לקיים טעמו וכשתראה דברי רבינו בפירוש המשנה שכתבתי בסמוך תראה שאין כאן עירבוב:\",2,0],[8,375,7,5,\"ומ\\\"ש שהוא שלא מדרך המשנה יש לתמוה עליו שמאחר שבמשנה אינו מפורש לא טעמו של רבינו ולא טעמו של הראב\\\"ד איך יאמר על דברי רבינו שהם שלא מדרך המשנה בעבור שהם על דרך טעם אחר זולת טעמו של הראב\\\"ד ואדרבה פשט לשון המשנה מורה על טעמו של רבינו:\",3,0],[8,375,7,6,\"הרוצה למלאות מים לקדשן ומים אחרים כו'. בפ\\\"ז דפרה:\",1,0],[8,375,7,7,\"שנים שהיו ממלאים וכו'. בפרק ז' דפרה וכתב שם רבינו בקידוש אחר שהתערבו המימות והשליך בהם אפר אחד הנה הם יחד כאיש אחד פירוש שסייע זה לזה בהגבהת מימיו על כתפיו או שנטל זה לזה קוץ מידו או מגופו אם שניהם מילאו לצורך קידוש אחד המים כשרים דשניהם כאיש אחד ויכול כל אחד לסייע לחבירו כמו לעצמו ונטילת הקוץ צורך מילוי הוא וצורך הקידוש הוא אבל בשני קידושים כל אחד פסל מימיו במה שסייע חבירו דהוי מלאכה:\",1,0],[8,375,7,7,\"כתב הראב\\\"ד אם מילאו שניהם לקידוש אחד המים כשרים א\\\"א נראה לי מפני שהוא צורך הקידוש וכו'. משמע מדבריו שהוא מפרש ששני המעשים נעשו כאחד נטילת הקוץ והגבהה אבל פשטא דמתניתין משמע דאו נטל קוצו קאמר וכן פירש ר\\\"ש וי\\\"ל בדברי הראב\\\"ד שכתב מפני שהוא צורך הקידוש שלא יוכל למלאות אלא לאחר נטילת הקוץ פתח בצורך קידוש וסיים בצורך מילוי וצ\\\"ל דכיון שאם לא ימלא לא יקדש צורך מילוי הוה ליה צורך קידוש והוצרך לייחס הדבר לצורך קידוש אע\\\"פ שהוא לו סיבה רחוקה מפני שהדבר המאחד אותם הוא שהם לצורך קידוש אחד. ומ\\\"ש ולא יוכל זה להוציאו עד שיגביה לו חבירו איני מבין שהרי אפשר שיטול קוצו של זה אע\\\"פ שלא יגביה לו חבירו:\",2,0],[8,375,7,8,\"השואל חבל למלאות בו וכו' עד ואם היה דולה ומקבץ לתוך ידו המים כשרים. גם זה שם:\",1,0],[8,375,7,10,\"הממלא ונותן לחבית וכו' עד הרי אלו פסולים. גם זה שם. ופירש ה\\\"ר עובדיה המצניע החבית שהוא דולה בה המים לשום בשוקת ולאחר שעירה ממנה הצניעה קודם שיקדש מים בשוקת אין הצנעה זו חשיבא מלאכה לפי שצריך לה עדיין למלאות בה וצורך מילוי הוא וכן כפאה וכו' אבל אם עשה כן להוליך הקידוש והם המים המקודשים הואיל ולא צורך מילוי הוא חשיב כמלאכה ופסל המילוי עכ\\\"ל. וזה ע\\\"ד פ' ר\\\"ש אבל רבינו מפרש שממלא כדי ליתן מים בחבית. ונראה ששיעור דבריו כך הם ובשעה שהיה ממלא מים כדי ליתן בתוכה הצניעה שלא תשבר או כפאה על פיה כדי שתתנגב אם כוונתו בהצנעה זו או בכפייה כדי למלא אותה כשר אבל אם היתה כוונתו להוליך את הקידוש פסול:\",1,0],[8,375,7,11,\"הממלא דלי לשתות וכו'. תוספתא פ\\\"ד מילא דלי לשתות חישב עליו עד שלא הגיע למים מערה וצריך לנגב אם משהגיע למים וחישב מערה ואינו צריך לנגב רשב\\\"ג אומר אין צריך לערות שלשל למלאות ונפסק החבל מידו אם עד שלא הגיע למים חישב עליו מערה וצריך לנגב רשב\\\"ג אומר א\\\"צ לערות. ונראה שיש בה חסרון בסיפא וצריך להגיה בה אם עד שלא הגיע חישב עליו מערה ואינו צריך לנגב ואם משהגיע חשב עליו מערה וצריך לנגב:\",1,0],[8,375,7,11,\"כתב הראב\\\"ד זאת התוספתא מצאנו אותה בשני ספרים בהיפך וכו' עד כדאיתא בתוספתא. ופי' דחוק הוא ואיני יודע מה מלמדנו במה שכתב תחילת התוספתא מילא מים לשתות וכו' שהרי גם רבינו כך כתב ועל פי גירסת רבינו נראה לי דה\\\"פ הממלא דלי לשתות אם עד שלא הגיע הדלי למים חישב אע\\\"פ שלא עלו לו אותם המים למי חטאת וצריך לערותם ואח\\\"כ ימלא לשם מי חטאת מ\\\"מ אהני ליה ההיא מחשבה לענין שאינו צריך לנגב כשימלא לשם מי חטאת אבל אם לא חישב עד שהגיע הדלי למים אין אותה מחשבה מועלת וצריך לגרוס בדברי רבינו בסיפא וצריך לנגב כמו בסיפא דרישא ור\\\"ש פירשה בענין אחר ע\\\"פ גירסתו ואין דבריו מיושבים:\",2,0],[8,375,7,11,\"ומ\\\"ש הראב\\\"ד גבי שלשל הדלי על הדרך הראשון הוא הולך לדעת ת\\\"ק אבל לדעת רשב\\\"ג יש חילוק כדאיתא בתוספתא:\",3,0],[8,375,7,11,\"יש לתמוה דמשמע מדבריו דרשב\\\"ג לא פליג אלא בסיפא ובנוסחא דידן ברישא נמי פליג ועוד ק\\\"ל מה הוצרך לו להשמיענו דרשב\\\"ג פליג אם לומר דהלכה כמותו הא אע\\\"ג דקי\\\"ל כל מקום ששנה רשב\\\"ג במשנתנו הלכה כמותו במשנתנו דוקא אמרו ולא בברייתא:\",4,0],[8,375,7,11,\"מים שמילאן למי חטאת וכו'. משנה פרק ט' דפרה וכרבי יהושע:\",5,0],[8,375,8,1,\"מי שהיו מימיו על כתפו וכו' עד ואם עמד פסל. משנה בפרק ז' דפרה מי שהיו מימיו על כתיפו והורה הוראה והראה לאחרים את הדרך הרג נחש ועקרב ונטל אוכלין להצניען פסול אוכלים לאוכלן כשר נחש ועקרב שהיו מעכבין אותו כשר אמר ר\\\"י זה הכלל דבר שהוא משום מלאכה בין עמד בין לא עמד פסול ודבר שאינו משום מלאכה אם עמד פסול ואם לא עמד כשר ומשמע דר\\\"י לפרושי אתא והלכה כמותו ובתוספתא פ\\\"ו מי שהיו מימיו על כתיפיו ומיאנה בפניו או שחלצה בפניו והרצה סלע לאחר והראה דרך לאחר אם עמד פסול אם לא עמד כשר ופי' והרצה כמו אסור להרצות מעות כנגד נר חנוכה. והשתא מ\\\"ש רבינו ועמד לא קאי להרג נחש ועקרב דכיון דהריגה מלאכה היא אפילו לא עמד פסול דאל\\\"כ לא הו\\\"ל לרבינו לאסוקי בהרג נחש ועקרב בין הנך לנטל אוכלים להצניען אם איתא דאף בהנך בעינן עמד ונטל אוכלין לאכלן ואכלן משמע לרבינו דלא חשיב מלאכה ומש\\\"ה אם אכלן כשהוא מהלך כשר ויש לתמוה דהיאך אפשר דנטל אוכלין להצניען אע\\\"פ שלא הצניען עדיין הויא מלאכה ונטל אוכלין ואכלן לא הויא מלאכה ואפשר דאכילה חשיבא צורך המילוי שאם הוא רעב לא יהיה לו כח למלאת וכ\\\"כ ר\\\"ש בספ\\\"ז דפרה ואם כן מ\\\"ש שזה מצורך הולכת המים קאי גם לאוכלן כשהוא מהלך:\",1,0],[8,375,8,1,\"היה מהלך במים ופרץ וכו'. שם הפורץ על מנת לגדור כשר ואם גדר פסול ואוכל על מנת לקצות כשר ואם קצה פסול ודברי רבינו בפורץ נכוחים וסיפא נראה שהוא מפרשה שאם קצץ קצת פירות מהאילן לאכלן ודעתו להשאיר השאר להקצותן ליבש כשרים אע\\\"פ שבאכילת אלו נשארו האחרים מיוחדים להקצות לא חשיבא מלאכה:\",2,0],[8,375,8,2,\"היה אוכל בשעת וכו'. גם זה שם:\",1,0],[8,375,8,2,\"הממלא מים לקדשן וכו'. הכי משמע בפרק ז' דפרה במתניתין מהמוסר את מימיו לטמא וכן כתבו שם רבינו ור\\\"ש.\",2,0],[8,375,8,2,\"ומ\\\"ש היו שנים שומרים וכו'. גם זה שם:\",3,0],[8,375,8,3,\"המקדש באחת ידו וכו' עד שניהם כשרים. ג\\\"ז שם המקדש באחת ידו ועושה מלאכה באחת ידו אם לו פסול ואם לאחר כשר המקדש לו ולאחר שלו פסול ושל אחר כשר המקדש לשנים כאחד שניהם כשרים ופ' ר\\\"ש אם לו פסול משום דשמא המלאכה קדמה לקידוש ונפסלו המים [קודם שישליכו בהם האפר]. ואם לאחר הוא הקידוש כשר שהרי בעל המים לא עשה מלאכה. המקדש לו ולאחר כאחד או שקידש לחבירו קודם שלו פסול דקידוש של חבירו נחשב מלאכה לפסול מימיו. שניהם כשרים מפני שאין המים שלו עכ\\\"ל. והוא כדרך רבינו אלא שרבינו לא תלה הטעם בשמא כי התחלת ההשתדלות ודאי יהיה קודם ומאז חשיב מלאכה לפסול:\",1,0],[8,375,8,3,\"ודינים אלו הם על שתי הקדמות. האחת שאין המלאכה פוסלת במים אחר שהשליך לתוכן האפר. שנית שאין אדם פוסל מים של חבירו רק בהיותם מסורים לו לשמרם ולכך כשיקדש לעצמו פסל המים במה שהתחיל להשתדל במלאכה בידו האחרת קודם שיתן האפר במים ונמצא שנתן האפר על מים פסולים דאילו משום מלאכה שאחר קידוש לא פסל כמו שביארנו אמנם מקדש לאחר אין לו במים כלום אלא לקדשן ואין המלאכה שעושה הוא פוסלת מים של חבירו ומזה הטעם המקדש לו ולאחר כאחת שלו פסול כי כבר התחיל להתעסק קודם שהשליך האפר וקידוש חבירו היא מלאכה כמו שנתבאר:\",2,0],[8,375,8,5,\"הממלא לעצמו וכו'. תוספתא בפרק חמישי דפרה וכתבה ר\\\"ש בפ\\\"ז דפרה מילא לעצמו בשתי ידיו כאחת בקידוש אחד פסול בב' קידושין כשר. קידש לעצמו בשתי ידיו כאחת בקידוש אחד כשר בב' קידושין פסול. מילא וקידש קידש ומילא בשתי ידיו כאחת שניהם פסולין. מילא לאחד בשתי ידיו כאחת בקידוש אחד כשר בשני קידושין פסול. קידש לאחד בשתי ידיו כאחת בין בקידוש אחד בין בשני קידושין כשר. מילא וקידש קידש ומילא בשתי ידיו כאחת הקידוש כשר והמילוי פסול. זה הכלל כל מלאכה שיש בה מילוי בין לו בין לאחר פסול ושאין בה מילוי מלאכה שלו פסול ושל אחר כשר כל דבר שבידו ועשה מלאכה בין שיש שם שומרים ובין שאין שם שומרים פסול דבר שבידו ולא עשה מלאכה אם יש שם שומרים פסול עכ\\\"ל. ור\\\"ש כתב תוספתא זו בפ\\\"ז וגורס בה מילא לעצמו בשתי ידיו כאחת בקידוש א' פסול בשני קידושין כשר קידש לעצמו בשתי ידיו כאחת בקידוש אחד פסול בשני קידושין כשר וכן יש עוד בגירסתו חילופים אחרים. ופי' מילא לעצמו בשתי ידיו כאחת בקידוש אחד פסול בשני קידושין כשר איפכא הוה מסתברא בקידוש אחד כשר דמילא שתי חביות לקדשן קידוש אחד אפילו בזה אחר זה כשר בשני קידושין פסול דהא בזה אחר זה קתני סיפא האחד פסול והשני כשר והשתא דבבת אחת לא ידיע הי מינייהו קדים ושניהם פסולים שהאחרון נעשה מלאכה לראשון הואיל ומילא לקדש שני קידושין אע\\\"ג דלעצמו ואם באנו ליישב גירסת הספרים יש לפרש דה\\\"ק בקידוש אחד פסול כלומר שלא קידש אלא אחת מהחביות דאיגלאי מילתא דאחרת לא לקידוש נתמלאת ופוסלת חבירתה בשני קידושין שנתקדשו שתי החביות כשר וכגון שקידשן שתיהן בקידוש אחד א\\\"נ בשני קידושין וכגון שקידשן אחד ולעולם בנתמלאו ע\\\"מ לקדש קידוש א' ועוד יש לפרש דאפילו ע\\\"מ לקדשן שני קידושין כיון דבבת אחת מילאן לעצמו כשר דלא פסלינן אלא בזה אחר זה דוקא אע\\\"ג דמילא לו ולאחר פסלינן בסיפא בבת אחת מאחר דזה אחר זה נחשב מלאכה לעצמו שאני קידש לעצמו בשתי ידיו כאחת בקידוש אחד כשר שבחבית אחת הטיל אפר בשתי ידיו בשני קידושין של שתי חביות הטיל אפר פסול אפי' המילוי האחרון דאימא קידוש הראשון קדים ופסלו משום מלאכה. מילא וקידש קידש ומילא בשתי ידיו כאחת שניהם פסולים על חנם נקט תרתי כיון דקתני כאחת ויש לפרש כדפרישית לעיל משום דזימנין מתחיל הקידוש וזימנין מתחיל המילוי מיירי כגון שמילא חבית זו וקידש חבית אחרת ולכך שניהם פסולים דלא ידעינן הי מינייהו קדים דאם מילוי השני קדם לקידוש הראשון שניהן פסולין דמילוי השני פסל מילוי הראשון וקידוש הראשון פסל מילוי השני. מילא לאחר בשתי ידיו כאחת בין בקידוש אחד בין בשני קידושין כשר א\\\"א לפרש בקידוש אחד דהכא כההוא דלעיל שלא קידש אלא חבית אחת אלא כלומר בין מילאן לקדש קידוש אחד בין מילאן לקדש שני קידושין כשר ולא דמי לממלא לשנים כאחת דלעיל שניהם פסולים דלאדם א' שאני ולא דמי למילא לעצמו שחילקנו בין ממלא לקדש קידוש אחד לממלא לקדש ב' קידושין דדין הוא בממלא לעצמו שיש חשיבות במחשבתו לפסול ולהכשיר אבל מחשבה בממלא לצורך אחר לא חשיבא ולא שמה מחשבה לפי שיבא חבירו ויבטל מחשבתו וכלא חישב כלל דמי ומסתברא דכ\\\"ש לעצמו וא\\\"כ הא דמשמע הכא דוקא לאחר אבל לעצמו לא בקידוש אחד הוא דחלוקים דלעצמו פסול ולאחר כשר ולא כמו שפירשתי לעיל שלא נתקדשה אלא אחת מהחביות דא\\\"כ מ\\\"ש לעצמו מ\\\"ש לאחר וצריך להתיישב בדבר. מילא וקידש בשתי ידיו כאחת הקידוש כשר והמילוי פסול בעושה לאחר איירי דבעל המים לא עשה מלאכה והמילוי פסול שהממלא עשה מלאכה שקידש. מלאכה שאין עמה מילוי כלומר שאין המלאכה עם המילוי אלא לאחר שמילא עשה מלאכה. הממלא קודם קידוש שלו פסול כלומר אם המילוי שלו פסלתו מלאכה שלאחריו, ושל אחר שעשה אותו מילוי לאחר כשר דמכיון שמילאהו שוב אין נפסל במלאכה שהממלא עושה אחר כך. כל דבר שבידו ועשה מלאכה בין שיש שם שומרים בין שאין שומרים פסול משום מלאכה שעשה דבר שבידו ולא עשה מלאכה אם יש שומרים כשר כיון שנתכוון לשומרו או הוא או אחר ואם אין שם שומרים פסול משום היסח הדעת עכ\\\"ל. והנך רואה כי נוסחא משובשת נזדמנה לרבינו שמשון וגירסת רבינו היא הנכונה ומסכמת עם נוסחת תוספתא שבידינו ופירושה בבבי קמאי מבואר בדברי רבינו שמשון במ\\\"ש איפכא מסתברא ונראה שרבינו מפרש שמה ששנינו מילא וקידש קידש ומילא לאו למימרא דבעינן תרווייהו אלא היינו לומר מילא וקידש או קידש ומילא ומשום הכי לא נקט בלישניה אלא חדא ואפשר שלא היה בגירסתו בתוספתא אלא אחת ושאר הבבות מתבארות מתוך דברי ר\\\"ש שכתבתי:\",1,0],[8,375,8,5,\"וכתב הראב\\\"ד הממלא לעצמו א\\\"א הדרך הנ\\\"ל בכל אלה וכו'. ולטעמיה אזיל לתלות הכל בהיסח הדעת:\",2,0],[8,375,8,7,\"האומר לחבירו וכו'. משנה שם קדש לי ואקדש לך הראשון כשר מלא לי ואמלא לך האחרון כשר קדש לי ואמלא לך שניהם כשירים מלא לי ואקדש לך שניהם פסולים ופירושה מבואר מדברי רבינו כאן ובפי' המשנה:\",1,0],[8,375,8,7,\"ודינים אלו בנויים על ג' הקדמות. ראשונה שהקידוש וההזאה בשכר פסולים. שנית שהמילוי בשכר כשר. שלישית שהמלאכה פוסלת במים עד שיטילו האפר ואחר שיטיל האפר אין מלאכה פוסלת עוד הילכך כשאמר לו קדש לי ואקדש לך קידוש שני הוא בשכר שכבר קידש לו חבירו בשכר קידוש ואין להקשות גם קידוש ראשון הוא בשכר מה שיקדש לו חבירו דשאני התם דבשעה שקידש לא נתן לו דבר אע\\\"פ שאמר לתת לא מיקרי עושה בשכר ומאחר שנעשה הקידוש בהכשר אינו חוזר ונפסל כשיתן לו וכ\\\"ש שכיון שהקידוש השני פסול נמצא שלא עשה לו כלום ואין כאן שכר ואם א\\\"ל מלא לי ואמלא לך אותו שמילא בתחילה פסול בהיות כוונתו בעת המילוי שימלא לו הוא תמורתו הרי הוא כמילא לו ולאחר בבת אחת אבל השני כשר דלא הוי כמילא לו ולאחר דבשלמא כשזה ממלא לחבירו כדי שימלא לו חבירו אחר כך יש מקום לחשבו כמילא לו ולחבירו אבל כשזה ממלא לחבירו מפני מה שכבר מילא לו אין מילוי זה לעצמו כלל כי כבר נתמלאו מימיו ולא שייך כלל בזה להחשיבו מילא לו ולחבירו כי אין כאן לו אלא הכל לחבירו תגמול ופרעון על מה שכבר מילא לו ואין בכוונתו בעת מילוי זה למילוי אחר שימלאו לו ולא שייך בזה אלא להחשיבו מילוי בשכר וזה מותר הוא. ואם א\\\"ל קדש לי ואמלא לך שניהם כשירים ע\\\"פ מה שנתבאר בקדש לי ואקדש לך הראשון כשר ומלא לי ואמלא לך האחרון כשר. ואם א\\\"ל מלא לי ואקדש לך שניהם פסולים ע\\\"פ מה שנתבאר במלא לי ואמלא לך הראשון פסול ובקדש לי ואקדש לך האחרון פסול:\",2,0],[8,375,8,7,\"ומ\\\"ש רבינו גבי קדש לי ואמלא לך שהמלאכה אינה פוסלת הקידוש. טעמו לומר שהמקדש בתחילה אע\\\"פ שהוא כעושה מלאכה בשעת הקידוש אין בכך כלום כי אין המים שלו ואין אדם פוסל מימיו של חבירו בקידוש כמו שנתבאר גבי מקדש באחת ידו ועשה מלאכה בשנייה. ור\\\"ש פירש בענין אחר והראב\\\"ד כתב זה הטעם אין בו טעם ונ\\\"ל כיון שאינו ממלא אלא בשכר וכו'. גם בזה לטעמיה אזיל לתלות הכל בהיסח הדעת:\",3,0],[8,375,8,8,\"ההולך לקדש הרי זה נוטל את המפתח וכו'. תוספתא פ\\\"ה ההולך לקדש ה\\\"ז נוטל מפתח ופותח קרדום וחופר סולם ומוליך ממקום למקום וכשר [מפני שהוא עוסק עם הקידוש ואם משהוציא את האפר הגיף הדלת אחריו פסול] מפני שהוא עושה עמו מלאכה. פירושה מבואר בדברי רבינו ור\\\"ש בפ\\\"י דפרה פירשה בע\\\"א.\",1,0],[8,375,8,8,\"ומ\\\"ש כסה הכלי שהיה בו האפר וכו' או שזקף את הכלי בארץ וכו' זקף את הכלי שיש בו האפר בידו וכו'. משנה פ\\\"ו דפרה נטל שפופרת וכיסה או שהגיף את הדלת הקידוש כשר והמים פסולים זקפה בארץ פסול לתוך ידו כשר מפני שא\\\"א ופירש רבינו האפר כשר וראוי שישליכנו במים אחרים ויקדש בו לפי שהמלאכה אינה פוסלת באפר כמו שקדם אמנם אלה המים אשר רצה להשליך בהם זה האפר כבר נפסל לסבת התעסקו לשום פקק השפופרת או סגירת הדלת קודם שישליך בהם האפר וכו' וכן אם העמיד זאת השפופרת בארץ ג\\\"כ פסל אלה המים לפי ששמירת השפופרת של אפר מלאכה. אבל ר\\\"ש פירש זקפה בארץ וכו' דכתיב למשמרת ואין זה למשמרת ופשט לשון המשנה משמע כדברי ר\\\"ש מדלא כייל זקפה בארץ בהדי הנך דקתני בהו הקידוש כשר והמים פסולים אלמא דפסוק דקתני גבי זקפה בארץ אקידוש קאי ולדעת רבינו י\\\"ל דלא כייל לה בהדי הנך משום דבעא למיתני בהדה זקפה לתוך ידו:\",2,0],[8,375,8,8,\"נטל את האפר וכו' נתן (את) האפר על המים וכו'. תוספתא וקצתו במשנה ופירש רבינו שמשון בפ\\\"ו והחזירו לשפופרת כשר המילוי דחזרת אפר לשפופרת לאו מלאכה היא:\",3,0],[8,375,8,8,\"קירסם עלה זית וכו'. גם זה תוספתא קירסם עלה זית אם בשביל שיכנס בשפופרת כשר ואם בשביל שתחזיק אפר הרבה פסולה:\",4,0],[8,375,8,8,\"וכתב הראב\\\"ד קירסם אם בשביל שלא יחזיק אמר אברהם לשון התוספתא בשביל שתחזיק אפר הרבה והלשון שלו ערב יותר עכ\\\"ל. ונ\\\"ל שרבינו מפרש אם בשביל שיכנס האפר בשפופרת היינו שעושה העלה כמין מרזב כדי להכניסו בשפופרת ולא יתפזר האפר מכאן ומכאן בעת שיערה מהשפופרת לשוקת כשר ואם בשביל שלא יפול אפר הרבה בשוקת בשעה שהוא מערה מהשפופרת לשוקת והיינו בשביל שתחזיק אפר הרבה כלומר שתחזיק השפופרת אפר הרבה ולא יפול בשוקת יותר מדאי פסול ושינה רבינו אם בשביל שלא יחזיק היינו לומר בשביל שלא יפול לשוקת אפר יותר מדאי והכל עולה לכוונה אחת אלא שלשון בשביל שלא יחזיק ערב יותר שהוא תולה הדבר בשוקת שלא יפול בה אפר הרבה מלתלות בשפופרת שתחזיק אפר הרבה שלשון תחזיק אפר הרבה משמעו שתחזיק מה שיתנו בו יותר ממשמעו שיעכב מה שיש בו. ור\\\"ש פירש קירסם עלה זית להכניסו בשפופרת ולנענע האפר שבתוכו להוציא מקצתו לא חשיב מלאכה וכשר המילוי דהיינו המים ואם בשביל שתחזיק השפופרת אפר הרבה כגון שהעלים ארוכים וסיבבן סביב לשפופרת וראשן בפנים וכולם לחוץ והכניס אפר עד למעלה פסולה מילוי דהיינו המים דחשיבא זו מלאכה עכ\\\"ל:\",5,0],[8,375,9,1,\"כיצד מקדשין את המים וכו'. ואם נתן האפר תחלה ואח\\\"כ נתן עליו המים פסול. ומהו זה שנאמר בתורה וכו'. הכל פ\\\"ב דסוטה (דף י\\\"ו ע\\\"ב) וכרבנן ופ\\\"ק דתמורה (דף י\\\"ב):\",1,0],[8,375,9,2,\"המקדש צריך שיתכוין וכו'. תוספתא פ\\\"ה.\",1,0],[8,375,9,2,\"ומ\\\"ש אבל אם נפל האפר לתוך המים. משנה פ\\\"ו דפרה ומייתי לה בפ' לולב הגזול.\",2,0],[8,375,9,2,\"ומ\\\"ש או שנטל האפר בידו דחפו חבירו או הרוח ונפל האפר מידו על המים. תוספתא פ\\\"ה.\",3,0],[8,375,9,2,\"ומ״ש או שנפל האפר מידו על צד הכלי או על ידו ואח״כ נפל למים הר״ז פסול. (משנה פ״ו) ומייתי לה בפרק הנשרפין (סנהדרין דף ע״ז ע״ב):\",4,0],[8,375,9,3,\"קידש פחות מכדי הזאה וכו'. בפרק דם חטאת עלה נ\\\"ג ופ\\\"ק דמנחות (דף י'):\",1,0],[8,375,9,3,\"היה האפר צף על פני המים וכו'. משנה פ\\\"ו דפרה וכחכמים.\",2,0],[8,375,9,3,\"ומ\\\"ש ואפי' נשבה הרוח וכו'. תוספתא פ\\\"ה וכחכמים:\",3,0],[8,375,9,4,\"כלי קטן שהיה בתוך כלי גדול וכו'. משנה פ\\\"ו המקדש בשוקת והטפי בתוכה אע\\\"פ שפיו צר כל שהוא המים שבתוכו מקודשין:\",1,0],[8,375,9,5,\"ומ\\\"ש היה ספוג בתוך המים וכו'. שם במשנה והטעם שלא נתקדשו המים משום דספוג אינו כלי ואנן קידוש בכלי בעינן.\",1,0],[8,375,9,5,\"ומ\\\"ש נפל ספוג לתוך המים וכו'. וכתב הר\\\"י קורקוס ז\\\"ל נראה שזו היא תוספתא שבסוף פרק ד' ובספרים שלנו כתובה בטעות ובחסרון ונראה שהטעם בזה שכיון שהמים היו מקודשין כבר אע\\\"פ שיטול אותו ויסחוט בשוקת כל שהוא על ידי נטילה אין בכך כלום כי מקודשין היו אמנם לסחוט הספוג בתוך השוקת כי המים שאינם יוצאים רק על ידי שיסחוט הוי כנשפכו כיון שהספוג אינו כלי ואינו חוזר ומקבץ אותם או אפשר שחומרא בעלמא היא אי נמי גזירה אטו נפל קודם קידוש וליטלו שרי דכולי האי לא גזרינן עכ\\\"ל:\",2,0],[8,375,9,6,\"שתי שוקתות שבאבן אחת וכו'. משנה בפ\\\"ה דפרה:\",1,0],[8,375,9,7,\"שתי אבנים שהקיפן זו לזו ועשאן שוקת וכו'. גם זה משנה שם שתי אבנים שהקיפן זו לזו ועשאן שוקת וכן שתי עריבות וכן שוקת שנחלקה המים שביניהם אינם מקודשין עשאן בסיד או בגפסיס והן יכולות להנטל כאחת המים שביניהם מקודשין ופירש רבינו שמשון המים שביניהם שבין שתי עריבות ושבין סדק של שוקת אבל שאר המים מקודשין אלא דאותן שבסדק לא נכנס הקידוש בהן ובתוספתא קתני שהמים שבסדק אינם אגודים בכלי אבל כשעשאה בסיד ויכולות להנטל נחשבים המים שביניהם כצבורים בתוכן ולישנא דתוספתא משמע דכל המים אינן מקודשין כלל ולא יתכן דא\\\"כ הו\\\"ל למיתני פסולין וצריך לדחוק לשון [התוספתא] לפי הענין שפירשתי וז\\\"ל התוספתא שתי אבנים שהקיפן זו לזו ועשאן שוקת וכן שתי עריבות וכן השוקת שנחלקה אמר רבי יוסי בזו ההלכה קפצתי לפני ר\\\"ע אמרתי לפניו שתיהן אינם מקודשות שהמים שבסדק אינם אגודים בכלי עכ\\\"ל. ונראה שמ\\\"ש ר\\\"ש שצריך לדחוק לשון התוספתא היינו לומר דמאי שתיהם אינם מקודשות דקתני חלק משתיהן קאמר דהיינו המים שבסדק ועי\\\"ל דההיא תוספתא רבי יוסי קאמר לה ורבנן פליגי והכי דייק לישנא דקפצתי לפני ר\\\"ע ומתניתין כרבנן:\",1,0],[8,375,9,7,\"והראב\\\"ד כתב ונתן אפר בחלק אחד א\\\"א איני יודע מה טיבו של אחד בכאן וכו'. ורבינו נראה שסובר שאילו היה נותן אפר בזו ובזו המים שביניהן היו מקודשין ממ\\\"נ והב\\\"ע בשלא נתן אלא בחלק אחד השתא איכא למימר במים שביניהם שאינן מקודשין. וכבר כתבתי בסמוך שר\\\"ש דחה פירוש הראב\\\"ד ופירש כפירושו. ומ\\\"מ יש לדקדק על דברי רבינו דכיון שיש סדק ביניהם אינם כלי והיאך יהיו מקודשין אפילו המים שהם בחלק שנתן האפר דהא כלי בעינן וליכא וצ\\\"ל דהב\\\"ע כשאין מים נוזלים מהסדק מפני שחיברה בטיט והו\\\"ל כלי לענין זה אבל לא לענין שאם קידש מים שבחלק אחד שיהיו מים שבחלק השני מקודשין עד שיעשם בסיד וגפסיס ויהיו יכולים להנטל כאחת:\",2,0],[8,375,9,8,\"מים מקודשין שנתערב בהם מים אחרים וכו' עד הרי הוא נראה. משנה פ\\\"ט דפרה וכת\\\"ק ומייתי לה בפרק התערובות ושם אמרו דרבנן סברי הזייה צריכה שיעור הילכך אע\\\"ג דסברי יש בילה כיון שהוא לח בלח מתערב ובכל הזייה יש קצת מהכשר אע\\\"פ כן פסולים כיון שאין בהם שיעור מהכשר וסברי ג\\\"כ אין מצטרפין להזאות הילכך מה שחסר מהראשונה אינו משלים בשניה והשתא כיון שרבינו פוסק שאינה צריכה שיעור ובכל שהוא שיפול על הטמא נטהר אפילו הזאה אחת ראוי שיספיק כדאמרינן גבי דם חולין שנתערב בדם קדשים דכיון שאינה צריכה שיעור יזה:\",1,0],[8,375,9,8,\"וכתב הר\\\"י קורקוס ז\\\"ל אפשר שסובר רבינו שמה שאמרו צריכה שיעור היינו שבאזוב יהיה שיעור הזאה ואז אפילו לא נפל על הטמא אלא כל שהו נטהר כיון שאותו כל שהו בא משיעור שלם אבל מהיות כל שהו מן הפסול מעורב נמצא שאין באזוב שיעור פסולים אבל בדם לא בעינן שיעור כלל וזה בכלל מה שאמרו במנא צריכא שיעור פי' באזוב ולא מיעטו כי אם אגבה דגברא עכ\\\"ל.\",2,0],[8,375,9,8,\"ומ\\\"ש אפילו מים שנתמלא לקידוש. מבואר בתוספתא שאין חילוק בדבר.\",3,0],[8,375,9,8,\"ומ\\\"ש וכן אם ירד לתוכו טל וכו'. פ\\\"ט דפרה:\",4,0],[8,375,9,9,\"המטביל כלי לחטאת וכו'. משנה פרק ה' פי' המטביל כלי למלאות בו מים ולקדשן באפר אם הטבילו במים שאינן ראויים לקדש דהיינו מים שאינן חיים צריך לנגב פן יתערבו שאינם ראויים בראויים אבל אם הטבילו במים הראויים לקדש דהיינו מים חיים אינו צריך לנגב. אם לאסוף לתוכו מים מקודשין שהטביל להכניס לתוכו מים שכבר נתקדשו באפר אפילו הטבילו במים חיים צריך לנגב שלא יתערבו שאינן מקודשין במקודשין:\",1,0],[8,375,9,10,\"קרוייה שהטבילה וכו'. גם זה משנה שם וכת\\\"ק פירוש קירוייה דלעת שניטל מה שבתוכה שהטבילה מעלה בעלמא לחטאת ולא משום טומאה דהא בשלא נטמאת מעולם מיירי. במים שאין ראויים לקדש מקדשין בה לאחר שניגבה ולא חיישינן שמא בלעה מים שאין ראויים לקדש ותחזור ותפלוט. נטמאת אין מקדשין בה אע\\\"פ שחזר והטבילה דחיישי' שמא תפלוט משקין טמאים הבלועים בה דמחמרינן במים טמאים יותר מבמים שאינם ראויים לקדש ומדברי רבינו נראה שהוא גורס במים שהן ראויים לקדש וכך גירסת ספרינו במשנה דלא הקילו להכשיר במים שאינם ראויים לקדש והטעם שהחמירו בלאסוף משום דכל לאסוף עשוי הוא להשהות אותם בתוכה זמן מרובה ובודאי תפלוט מה שבלוע בה אבל כשמקדש בה עשוי הוא שלא לשהותם בתוכה הילכך לא חיישינן שתפלוט המים שבתוכה:\",1,0],[8,375,9,11,\"מים מקודשין שנפל לתוכם שקצים ורמשים וכו'. משנה פ\\\"ט דפרה וכת\\\"ק וכתב רבינו אפילו היו יבשים ביותר כגון הנמלה וכו' לאפוקי מר\\\"ש וראב\\\"י דפליגי התם את\\\"ק.\",1,0],[8,375,9,11,\"ומ\\\"ש נפל לתוכה חיפושית וכו'. שם וכתוב בספרי רבינו גבי חיפושין ולא נשתנו מראיה והוא ט\\\"ס וצריך להגיה ולכתוב ולא נשתנו מראיהן כלומר לא נשתנו מראה המים:\",2,0],[8,375,9,12,\"מים מקודשין ששתה מהן וכו'. משנה שם וכת\\\"ק ורבינו שמשון הסכים לטעם שכתב רבינו. ודע שבמשנה ר\\\"ג אומר אף הנחש פוסל מפני שהוא מקיא ואע\\\"ג דבתוספתא אמרו רבי יוסי ור\\\"ש נראין דברי ר\\\"ג וכדבריו אנו מורים לא חש לה רבינו דמאחר דסתם לן במתניתין דלא כוותיה כסתם מתניתין נקטינן:\",1,0],[8,375,9,13,\"מי חטאת שנשתנו מראיהן וכו':\",1,0],[8,375,9,14,\"אפר חטאת שנשתנו מראיו וכו'. תוספתא פ\\\"ח דפרה:\",1,0],[8,375,9,15,\"החושב על מי חטאת לשתותן וכו'. משנה פ\\\"ט דפרה החושב על מי חטאת לשתות ר\\\"א אומר פסול רבי יהושע אומר כשיטה אמר רבי יוסי בד\\\"א במים שאינן מקודשין אבל במים מקודשין ר\\\"א אומר כשיטה ורבי יהושע אומר כשישתה ואם גרגר כשר ונראה שסובר רבינו שרבי יוסי מפרש דברי ת\\\"ק והכי נקטינן וכרבי יהושע וכן פסק רבינו בפירוש המשנה. וטעם לחלק בין מים מקודשין לשאינן מקודשין כתב רבינו שמשון דכשהם מקודשים אימלוכי ממליך וחוזר בו ממחשבתו ולא חשיב היסח הדעת לר\\\"א עד שיטה ולרבי יהושע עד שישתה בחבית עצמה ומשום משקה פיו המתערב ופירוש אם גרגר ששפך לתוך גרונו ולא נגעה שפתו במים שבכלי לא נפסלו הנשארים שהרי לא נתערב בהם משקה שבפיו:\",1,0],[8,375,9,15,\"כתב הראב\\\"ד משנה כך היא אם אינם מקודשין כשיטה וכו'. נראה שבא להשיג על רבינו שלא חילק בין מקודשין לשאינן מקודשין ואני אומר שבפירוש כתב כאן מי חטאת דהיינו מים מקודשים ודין מים שאינם מקודשין כתב בספ\\\"ז:\",2,0],[8,375,9,16,\"כלי שיש בו מים מקודשין שהניחו מגולה וכו'. משנה בפרק י\\\"א דפרה.\",1,0],[8,375,9,16,\"ומ\\\"ש מפני שיש שם שתי ספיקות וכו'. בפ\\\"ק דחולין (דף ט') אמרו מה טעם מפני שדרכן של שרצים לגלות ולא לכסות וכתב רש\\\"י ואף דאדם נמי דרכו לגלות איכא למיתלי בטהור ובשרצים והוי רובא. ואמרינן בפ\\\"ק דחולין (דף י'.) דדוקא הניחה מכוסה ומצאה מגולה הוא דחיישינן אבל הניחה מגולה ומצאה מגולה לא חיישינן למידי וכשירה ואע\\\"ג דלשתייה חששו חמירא סכנתא מאיסורא:\",2,0],[8,375,9,17,\"המוסר מים מקודשין וכו'. משנה פ\\\"ז דפרה:\",1,0],[8,375,9,18,\"שנים שהיו שומרים את המים וכו'. משנה פ\\\"ח דפרה:\",1,0],[8,375,10,1,\"הממלא מים לקידוש וכו'. בפרק טרף בקלפי (יומא דף מ״ג) אי כתב רחמנא ולקח ונתן ה״א עד דשקיל חד ויהיב חד פי' ההיא גופיה דשקיל כתב רחמנא ולקחו:\",1,0],[8,375,10,1,\"ומ\\\"ש וכן ממלא אדם בכלי ומערה מכלי לכלי וכו'. רבינו שמשון הקשה על מי שסובר בהיפך דהא בכמה דוכתי מוכח שאפילו לכתחילה מותר למלאות בכלי אחד ולערות לקדשם בכלי אחר והרי בדלי ממלא ושוקת קרוי בכל דוכתא מקום שמשליך המים מן הדלי:\",2,0],[8,375,10,2,\"ממלא אדם מים וכו'. תוספתא בסוף חגיגה מוליכין מי חטאת וכו' ממקום למקום וכן משמע שם בגמרא:\",1,0],[8,375,10,2,\"כתב הראב\\\"ד ממלא אדם מים ומניחם אצלו וכו' ואין בכך כלום ומוליכן ממקום למקום וכו'. א\\\"א ובלבד שיהיו שמורים ולא יהיה בהם היסח הדעת עכ\\\"ל. ודבר תימה הוא היאך אפשר שישהו כמה ימים ולא יהא בהם היסח הדעת ולדעת רבינו ניחא די\\\"ל שאין היסח הדעת פוסל בהן אלא כשהוא מתעסק בהם קצת כגון שקלן במשקל דלקמן:\",2,0],[8,375,10,2,\"וכן המים המקודשים וכו'. ומ\\\"ש ומוליכן ממקום למקום וכו'. ודע שמצאתי בספר מוגה שאצל מ\\\"ש רבינו ומעיר לעיר כתוב ומשמר אדם אפר פרה אצלו ומוליכה ממקום למקום ומעיר לעיר:\",3,0],[8,375,10,2,\"פעם אחת הוליכו כלי שהיה בו מי חטאת וכו'. בפרק חומר בקודש (חגיגה דף כ״ג) ופרק האשה שלום (יבמות דף קי״ו ע״ב).\",4,0],[8,375,10,2,\"ומ\\\"ש שאין מעבירין מי חטאת וכו'. משנה פ\\\"ט דפרה:\",5,0],[8,375,10,3,\"מעבירים מים מקודשים בספינה בים הגדול וכו'. בפרק חומר בקדש אחד הירדן ואחד שאר הנהרות רבי חנניא בן עקביא אומר לא אסרו אלא בירדן וכמעשה שהיה משמע דלת\\\"ק נמי דוקא נהרות אבל ים הגדול לא דהא לא דמי לירדן כלל:\",1,0],[8,375,10,3,\"ושטין בספינה על פני המים. כך כתוב בספרים ונ\\\"ל שהוא ט\\\"ס וצריך למחוק תיבת בספינה ולכתוב במקומה בהם וכן מצאתי בספר מוגה:\",2,0],[8,375,10,4,\"המוליך מים לקדשן וכו'. משנה פרק ז' דפרה:\",1,0],[8,375,10,4,\"וכתב הראב\\\"ד ואין צ\\\"ל מים שנתקדשו א\\\"א תמה אני על זה וכו'. וי\\\"ל דרבינו לטעמיה אזיל דסבר דמלאכה דפסלה לא מטעם היסח הדעת וכמו שנתבאר בפ\\\"ז וא\\\"כ אע\\\"ג דמלאכה אינה פוסלת אחר שהטילו אפר היסח הדעת פוסל וכן מתבאר בדין שיבא בסמוך:\",2,0],[8,375,10,5,\"מי חטאת ששקלן וכו'. בפרק הניזקין עלה נ\\\"ג מתיב רבי אלעזר העושה מלאכה במי חטאת ובפרת חטאת פטור מדיני אדם וחייב בדיני שמים ואי אמרת היזק שאינו ניכר שמיה היזק בדיני אדם נמי ליחייב הוא מותיב לה והוא מפרק לה וכו' בששקל בהם משקלות והאמר רבא מי חטאת ששקל בהם משקלות כשירה ל\\\"ק הא בגופן הא בכנגדן בגופן מעשה קא עביד בהו ואי היזק שאינו ניכר שמיה היזק בדיני אדם נמי ליחייב אלא אידי ואידי כנגדן ולא קשיא הא דאסח דעתיה הא דלא אסח דעתיה ופירש\\\"י ששקל בהם משקלות שהיו תלויות בכף מאזנים והיה יודע משקלם ונתן בשר לשקלו בכף שנייה דלא עבד מעשה בידיו אלא במחשבה מיפסלי. דרבא בכנגדן כדפרישית ומתניתא דמשמע פסולות ששקל בגופן כדרך הטבחים לשקול בשר במים שיש להם כלי שיש בו שנתות ונותנים מים בראשונה ונותנים בשר במים עד שהמים עולים לרושם השני וכוונוהו כבר שבמשקל ליטרא או שתים המים עולים ומגיעים לאותו הרושם. מתניתא דאסח דעתיה משמירתן ע\\\"י המשקל ששקל בהם ונפסלו בהיסח הדעת דלמשמרת למי נדה כתיב שצריכות שימור תמיד עכ\\\"ל. ולכאורה אין דברי רבינו מכוונים עם דברי הגמרא ולכן כתב עליו הראב\\\"ד א\\\"א אין הסוגיא הולכת במסכת גיטין על דרך פירושו עכ\\\"ל. ולכוין דברי רבינו עם דברי הגמרא צ\\\"ל שמ\\\"ש מי חטאת ששקלן במשקל היינו לומר ששקל כנגדן ומ\\\"ש אם שקל דברים אחרים במי חטאת היינו ששקל בגופן וכמ\\\"ש רש\\\"י שדרך הטבחים לשקול במים.\",1,0],[8,375,10,5,\"ומ\\\"ש הואיל ועשאן משקלות, היינו לומר שעשה משקולת בגופן וכמו שנתבאר:\",2,0],[8,375,10,5,\"כל אלו הטהורים שממלאין או שמקדשין או שמזין. כך היא הנוסחא הנכונה בדברי רבינו ובפ״ג דפרה תנן דכהן השורף את הפרה היו מטמאין אותו ומטבילין אותו מיד כדי שיהיה טבול יום ומייתי לה בריש יומא. ודין הכלים מתבאר מדין שפופרת שחתכה לחטאת ששנינו בפ״ה דפרה והוזכר פרק הערל ופרק טרף בקלפי (דף ס') ופרק חומר בקודש (חגיגה דף כ״ג) ופרק ב' דזבחים (דף כ״ח):\",3,0],[8,375,10,6,\"הכל כשרים להזות וכו'. משנה בסוף פרה ובפרק טרף בקלפי יליף לה מקראי. ודין ח\\\"ש בתוספתא.\",1,0],[8,375,10,6,\"ומ\\\"ש והערל כשר להזות. בפרק הערל עלה ע\\\"ב ובריש ערכין (דף ג'):\",2,0],[8,375,10,6,\"קטן שיש בו דעת שהזה וכו'. משנה בסוף פרה.\",3,0],[8,375,10,6,\"ומ\\\"ש רבינו ואם אחזה בידו. כלומר אפי' בשעת הזאה פסול כלומר ואין צ\\\"ל אם אחזה בידו בשעת טבילת האזוב דקרא דפסלינן אשה מיניה בטבילה כתיב וטבל במים איש:\",4,0],[8,375,10,7,\"המזה צריך לכוין וכו' עד הזאתו כשירה. מתבאר שם ובפ\\\"ק דיומא:\",1,0],[8,375,10,7,\"וכתב הראב\\\"ד זה אינו שאינו צריך כוונה לטהרו וכו'. ואני אומר דאע\\\"ג דחולין לא בעי כוונה בטבילה בהזאה בעי ולדבריו ז\\\"ל נמי יש חילוק בטבילה להזאה דבטבילה לא בעי כוונה כלל דהא גל שנתלש ונפל על האדם ועל הכלים טהורים ובהזאה בעינן שיתכוין לו. ובספרי זוטא שנינו והזה הטהור על הטמא ולא בזמן שלא נתכוין לטמא:\",2,0],[8,375,10,9,\"המזה אינו צריך טבילה לכל הזייה. מתבאר מהדינים שיבואו שיכול להזות ולשנות בטבילה אחת ונלמד ג\\\"כ ממה ששנינו בסוף פרה מזין על האדם ועל הכלים אפי' הם מאה אלמא בטבילה אחת סגי לכולהו.\",1,0],[8,375,10,9,\"ומ\\\"ש כל שנגע בו מן המים אפילו כל שהוא טהור. פ\\\"ק דיומא (דף י\\\"ד) ופ\\\"ק דנדה:\",2,0],[8,375,10,9,\"טבל את האזוב ונתכוון להזות וכו'. גם זה משנה שם הטביל את האזוב וכו'.\",3,0],[8,375,10,9,\"ומ\\\"ש המנטפים. גם זה שם:\",4,0],[8,375,10,9,\"כתב הראב\\\"ד זה האיש מסרך ומערבב והתוספ' מסודרת כך וכו'. ורבינו כתב בפירוש המשנה כלשון הזה אמר ה' יתברך והזה הטהור על הטמא יצטרך שהמזה יתכוין להזות על הטמא ולזה אם טבל האזוב והוא מכוין שיזה על דבר שהוא מקבל טומאה או על האדם שהוא ג\\\"כ טמא וראוי להזאה הנה היא טבילה כשירה ואם הזה מזאת הטבילה על דבר שאינו מקבל טומאה ונשאר באזוב שארית אפשר שיזה ממנה הזאה שנית הנה לא יצטרך שיטבול האזוב פעם שנית אבל יזה ממנו על דבר שצריך הזאה וזהו אמרם אם יש באזוב לא ישנה אבל אם הטביל האזוב להזות על דבר שאינו מקבל טומאה ואח\\\"כ הזה על דבר שהוא מקבל טומאה הנה היא הזאה פסולה לפי שכשטבל האזוב לא היתה טבילה כשירה ולכן אפילו נשאר באזוב שארית מן המים לא יזה ממנה הזאה שנית עד שיטביל האזוב פעם שניה בכוונה שיזה על הטמא וכו' ובתוספתא אמרו בתתם סבה לזה ההבדל הואיל ותחילת טבילתו פסולה לכך הזאתו פסולה ואמרו מים המנטפים הוא שאם הטביל את האזוב להיות על דבר שאינו מקבל טומאה ונטפו מים מהאזוב טפות הנה אלה הטפות כשירות להזאה עכ\\\"ל. ומאחר שרבינו מסתייע בפירושו מהתוספתא אפשר שנוסחא אחרת היה לו בתוספתא או אף אם היה לו נוסחת הראב\\\"ד היה מפרשה ע\\\"ד זו:\",5,0],[8,375,10,10,\"מי חטאת שנתמעטו וכו'. גם זה משנה שם ופירש\\\"י ובלבד שלא יספג מקנח מצידי הכלי ושוליו ומדכתיב וטבל נפקא לן כדדרשינן בפ\\\"ק דמנחות גבי דם וטבל ולא מספג:\",1,0],[8,375,10,10,\"צלוחית שפיה צר וכו'. גם זה שם צלוחית שפיה צר טובל ומעלה כדרכו ר\\\"י אומר הזאה ראשונה ופירש רבינו שמשון טובל ומעלה כדרכו ולא חיישינן שמא מתוך שנדחק בפיה לצאת יצאו מים מגוף האזוב ונתערבו במי חטאת הזאה ראשונה ולא שנייה ובתוספתא קאמר ר\\\"י איפכא עכ\\\"ל. והראב\\\"ד כתב על דברי רבינו בפעם שנייה א\\\"א ר\\\"מ הוא שאמר כן בתוספתא וכו'. נראה מדבריו שהוא סובר שמ\\\"ש רבינו בפעם שנייה היינו לומר דבפעם שנייה כשירה ולא בפעם ראשונה ומפני כך השיג עליו ולפי האמת רבינו בין בראשונה בין בשנייה מכשיר וכת\\\"ק וה\\\"ק טובל ומעלה כדרכו בין בראשונה בין בשנייה ואינו צריך ליזהר שמא יגע בצידי הכלי בפעם שנייה ויפסול פעם שנייה וכך מבואר בדבריו בפירוש המשנה ומ\\\"מ מ\\\"ש הראב\\\"ד בשם ר\\\"מ בתוספת' היינו בפ' י\\\"א דפרה צלוחית שפיה צר מזין ממנה הזאה שניה אבל לא הזאה ראשונה מפני שהמים ניסוטין דברי ר\\\"מ וי\\\"ל בדברי הראב\\\"ד שכתב אבל משנה בסתם אמרו בין בראשונה בין בשנייה ולפי זה ר\\\"י דאמר הזאה ראשונה היינו לומר דוקא הזאה ראשונה וא\\\"כ היאך כתב אח\\\"כ ונראה במשנה שרבי הוא בן מחלוקתו של ר\\\"מ ומכשיר אפילו בראשונה ולפי זה יקשה עליו דרבי יהודה היינו ת\\\"ק ונראה לומר שהוא ז\\\"ל כתב בתחילה דמשנה בסתם קתני בין בראשונה בין בשנייה ולפי זה ר\\\"י לא מכשר אלא בראשונה ושלש מחלוקות בדבר והלכה כסתם מתניתין ואח\\\"כ כתב שיותר נראה לומר דאין כאן אלא שתי מחלוקות דסתם מתניתין ר\\\"מ ומאי טובל ומעלה כדרכו בשנייה ולא בראשונה כדאמר בתוספתא ורבי יהודה פליג עליה ומכשר אפילו בראשונה ולפי זה אתי ליה שפיר מה שפסק לפי דעתו דדוקא שנייה מכשר דאתי כסתם מתניתין ואפשר לומר שלהשיג על רבינו כתב גם זה לומר דאפילו את\\\"ל דסתם מתניתין לא מכשר אלא בשנייה ופסק כר\\\"מ קשיא דכיון דסתם מתני' ר\\\"מ ור\\\"י פליג עליה הוה ליה למפסק כר\\\"י כל זה לפי מה שהבין הראב\\\"ד בדברי רבינו ונסתלקה מעליו השגתו ומכ\\\"מ איני יודע טעם למה תהיה הראשונה פסולה והשנייה כשירה כר\\\"מ ואפשר לומר שטעמו משום דאיכא למימר בטבילה ראשונה שנתמצה משקה שבגוף האזוב בכניסתו ונדבק בפי הכלי וחזר ונדבק בו ביציאתו וכיון שהזה ממנו פעם ראשונה הלך לו מה שנדבק בו וכשיחזור לטבול פעם שנייה אין בו כי אם מי חטאת בלי שום תערובת אבל עדיין קשה לי מ\\\"ש ונראה במשנה שרבי יהודה הוא בן מחלוקתו דר\\\"מ ומכשיר אפילו בראשונה דמשמע דת\\\"ק דמתני' פוסל בראשונה והיאך אפשר לפרש כן על מה ששנינו טובל ומעלה כדרכו וצריך עיון:\",2,0],[8,375,11,1,\"כיצד מטהרים וכו' לוקח אדם טהור. מקרא מפורש והזה הטהור על הטמא.\",1,0],[8,375,11,1,\"ומ\\\"ש ג' קלחים של אזוב וכו'. בפי\\\"א דפרה מצות אזוב שלשה קלחים ובהם שלשה גבעולין ופירש רבינו שלשה קלחים שלשה שרשים ובכל שורש גבעול אחד ויביא בג' הענפים שלשה גבעולין עכ\\\"ל וכן פירש\\\"י והתוס' בפ\\\"ק דסוכה (דף י\\\"ג) וי\\\"ל בדברי רבינו פה למה שינה לכתוב ובכל בד ובד ולא כתב ובכל קלח וקלח ואפשר שהטעם הוא מפני שהקלח הוא שם לשורש והגבעול לא יהיה בשורש כי אם בבד.\",2,0],[8,375,11,1,\"ומ\\\"ש ואוגדן אגודה אחת. רבינו כתב בפירוש המשנה פי\\\"א דפרה דילפינן דבעינן אגודה מדכתיב ולקח אזוב וכתיב בפסח מצרים ולקחתם אגודת אזוב והוא בספרי וכתבו התוס' דלאו ג\\\"ש גמורה היא ולכך אם לא אגדו כשר א\\\"נ למצוה נתקבלה ולא לעכב.\",3,0],[8,375,11,1,\"ומ\\\"ש וטובל ראשי גבעולין. שם.\",4,0],[8,375,11,1,\"ומ\\\"ש שבכלי. נתבאר פ\\\"ו.\",5,0],[8,375,11,1,\"ומ\\\"ש ומתכוין ומזה. נתבאר בפרק עשירי.\",6,0],[8,375,11,1,\"ומ\\\"ש ביום השלישי וביום השביעי. מבואר בכתוב.\",7,0],[8,375,11,1,\"ומ\\\"ש אחר שתנץ החמה ואם הזה משעלה עמוד השחר כשר. משנה בסוף פרה ופ\\\"ב דמגילה (דף כ').\",8,0],[8,375,11,1,\"ומ\\\"ש ואחר שיזה עליו ביום הרי זה טובל ביום. נתבאר בפ\\\"ו:\",9,0],[8,375,11,1,\"טבל את האזוב בלילה והזה ביום או שטבל את האזוב ביום והזה בלילה הזאתו פסולה. כך היא הגירסא האמיתית בדברי רבינו והיא משנה בסוף פרה:\",10,0],[8,375,11,1,\"ומ\\\"ש והמים מטמאים משום מי חטאת וכו'. בתוספתא טבל את האזוב בלילה פסול לא שהמים פסולים אלא שצריך להטביל שנייה הזה בלילה הזייתו פסולה והמים טמאים משום מי חטאת:\",11,0],[8,375,11,2,\"מי שנטמא במת וכו'. בפרק חומר בקודש (חגיגה דף כ״ב ע״ב):\",1,0],[8,375,11,2,\"מי שהוזה עליו בג' וכו'. יש לתמוה על זה דהא אמרינן בקידושין פרק האומר (דף ס\\\"ב) והזה הטהור על הטמא ביום השלישי וביום השביעי למה לי איצטריך סד\\\"א שלישי למעוטי שני שביעי למעוטי ששי דקא ממעט בימי טהרה אבל היכא דקא עבד בשלישי ובשמיני דקא מפיש בימי טהרה אימא שפיר דמי קמ\\\"ל וכבר השיגו הראב\\\"ד וכתב מי שהוזה עליו בשלישי וכו' טובל בכל עת שירצה אחר השביעי א\\\"א אינו כן בגמרא דקידושין לעולם מונה שלישי ושביעי וטובל אחר הזאה עכ\\\"ל וי\\\"ל שרבינו סמך על מה ששנינו בפסיקתא וחטאו ביום השביעי לרבות הזיית שביעי שאם לא הוזה בשביעי מזה בשמיני ובתשיעי וכן בספרי אין לי אלא שביעי שמיני תשיעי עשירי מניין ת\\\"ל וחטאו ביום השביעי ואח\\\"כ וכבס בגדיו ורחץ במים וטהר בערב. וכן מצאתי בילקוט בשם ספרי זוטא יכול הזאת שביעי תהא סמוכה לשלישי אמר שוב בשביעי אם ללמד שביעי שהוא סמוך לשלישי כבר למד הא מה אני מקיים שביעי אפילו רחוק מן השלישי עכ\\\"ל. והנה בא לידי קונטרס אחד וכתוב בו שרבינו שמשון הקשה על רבינו קושיא זו דהראב\\\"ד וכתב שרבינו פירש ההיא דספרי שבא הכתוב לרבות שמיני תשיעי ועשירי אע\\\"פ שהיתה הזאתו בשלישי ואינו כך כדמוכח ההיא דקידושין אלא מרבה שמיני אם הזה ברביעי ותשיעי אם הזה בחמישי ועשירי אם הזה בששי והאי דבספרי דריש ליה מוחטאו ובקידושין דריש ליה מביום השלישי וביום השביעי ומוקי וחטאו דלא תימא ה\\\"מ לקדשים אבל לתרומה בחד סגי סוגיא דקידושין כרבי חנניא בן גמליאל דאייתר ליה חד קרא וברייתא דספרי כר\\\"מ וקא סבר ר\\\"מ דמחד קרא נפקא תרומה וקדשים עכ\\\"ל. ומכ\\\"מ יש לתמוה למה הניח רבינו גמרא ערוכה ותפס כברייתות. וי\\\"ל שגירסת רבינו בההיא דקידושין סד\\\"א שלישי למעוטי שני וכו' ואי עביד ברביעי ובשמיני דקא מפיש בימי טהרה אימא ש\\\"ד קמ\\\"ל ולענין הזאה בזמנה מיפרשא וכדפירש\\\"י דבפ\\\"ק דיומא נחלקו רבי יוסי ור\\\"מ דלרבי יוסי הזאה בזמנה אינה מצוה אפי' אם נאמר טבילה בזמנה מצוה ור\\\"מ יליף הזאה מטבילה וסוגיא דקידושין אתיא כרבי מאיר דאמר הזאה בזמנה מצוה ולכך אמרו דסד\\\"א דברביעי ובשמיני שפיר דמי קמ\\\"ל דלאו שפיר דמי וכיון דאנן קי\\\"ל כרבי יוסי א\\\"כ ליתא לההיא סוגיא.\",2,0],[8,375,11,2,\"ומ\\\"ש טובל בכל עת שירצה אחר השביעי בין ביום בין בלילה. ומ\\\"ש ומזין עליו ביום. בילקוט בשם ספרי זוטא יכול תהא הזאת שלישי קבועה ביום אבל הזאת שביעי תהא קבועה בלילה והלא דין הוא וכו' אמרת לא אמרתי אלא ביום השביעי:\",3,0],[8,375,11,2,\"ומ״ש בין קודם טבילה וכו'. כתב ה״ר שמשון על זה בתשובה א״א לומר כן דב' טבילות יש כמו שמפרש ר״ת אחת קודם הזאה כדי לקבל הזאה כדאמרינן בפרק החולץ (יבמות דף מ״ו ע״ב) וגמירי דאין הזאה בלא טבילה כלומר בלא טבילה קודם הזאה וכדאמרינן בפ״ב דכריתות מה אבותיכם לא נכנסו לברית אלא במילה וטבילה והרצאת דמים דתקני טבילה ואח״כ הרצאת דמים ותנן בפרק בתרא דמסכת פרה אבל הוא עצמו טובל בלילה ומזה ביום מכל הני משמע דטבילה קודם הזאה ובכל הזאות קאמר גמירי דאין טבילה בלא הזאה בין בהזאת דמים בין בהזאת מי חטאת ואותה טבילה דקודם הזאה בין ביום בין בלילה בין בהזאת שלישי בין בהזאת שביעי ויש טבילה אחרת לאחר הזאה בשביעי שהיא לטהר מטומאתן ואינה אלא לאחר הזאה כדתניא בספרי ורחץ במים וטהר בערב מה ת״ל מפני שהייתי אומר אם קדמה טבילה להזאה יצא ת״ל וחטאו ביום השביעי ואח״כ וכבס בגדיו ורחץ במים וטהר בערב ואותה טבילה אינה אלא ביום כדתנן בפ״ב דמגילה (דף כ') דאין מזין ואין טובלין אלא ביום ומפרש בגמרא משום דאיתקש טבילה להזאה ומשמע במנחות ס״פ רבי ישמעאל (מנחות דף ע״ב) דביום אין בלילה לא ומיהו בירושלמי משמע דבטבילת האזוב קאמר דאיתקש להזאה דכתיב ולקח אזוב וטבל במים איש טהור והזה וכ״נ דבההיא דלא טובלין אלא ביום לא אשכחן פלוגתא ובפ״ק דיומא (דף ח') פליגי ר״מ ורבי יוסי אי מקשי הזאה לטבילה לענין הזאה בזמנה מצוה ומאן דלא מקיש הזאה לטבילה לענין מצוה ה״ה נמי דלא מקיש טבילה להזאה לענין ביום אבל אי בטבילת האזוב איירי ניחא והא דתני רבי חייא פ״ק דיומא (דף ו' ע״ב) זב וזבה וכו' בועל נדה וטמא מת טבילתן ביום ההוא ביום לאו למימרא דלא מהני בלילה שלאחריו דהרי זב וזבה משעבר שביעי שלהם טובלים בין ביום בין בלילה דהא כל נשים ספק זבות שוינהו וטובלות בלילה ובפרק בתרא דנדה (דף ס״ז ע״ב) קאמר ר״ש [אחר תטהר] אחר מעשה תטהר אבל אמרו חכמים אסור לעשות כן שמא תבא לידי ספק וטבילתן ביום דקתני למעוטי לילה שלפניו ולמעוטי דלא הוו כנדה ויולדת ואין צריך להמתין עד לילה שאחריו עכ״ל וכן כתבו גם בפירוש המשנה בסוף פרה ומדברי רבינו נראה דלית ליה ההיא דר״ת שמצריך שתי טבילות וענין דין זה שכתב רבינו כתב בסוף פרה וז״ל אמר ה' והזה הטהור על הטמא ביום השלישי וביום השביעי ולא תהיה ההזאה אלא ביום וכן טבילת האזוב במים אמנם טבילת האיש הטמא עצמו יחוייב בלילה ויזה עליו ממחרת היום זהו אם נזדמן שנתאחרה ההזאה לאחר יום השביעי אשר יזה באי זה יום שיהיה ולשון ספרי אין לי אלא שביעי שמיני תשיעי עשירי מנין ת״ל וחטאו מ״מ אמנם אם לא נתאחרה ההזאה והלך הענין כמצותו הנה מן הראוי שתקדם ההזאה ביום השביעי ואחר ההזאה יטבול במי מקוה ביום השביעי ההוא ויעריב שמשו וז״ל התורה אמרה וחטאו ביום השביעי וכבס בגדיו ורחץ במים וטהר בערב ולשון ספרי שהייתי אומר אם קדמה טבילה להזאה יצא ת״ל וחטאו ואח״כ וכבס בגדיו עכ״ל:\",4,0],[8,375,11,3,\"כל המטמאים מקבלין ההזאה וכו'. בספרי זוטא ואמרינן בפרק דם חטאת (זבחים דף צ״ג) רבי אליעזר אומר מי חטאת שנטמאו מטהרים שהרי נדה מזין עליה כלומר והרי כשהמים יורדים על הנדה מטמאים ואעפ״כ מטהרים את הנדה מטומאת מת ועד כאן לא פליגי רבנן עליה אלא בנטמאו מעיקרא אבל בנדה שהזאה וטומאת המים באים כאחד מודו שמזין עליה:\",1,0],[8,375,11,3,\"וכן הערל מקבל הזאה וכו'. בר״פ הערל (יבמות דף ע״א:) מימרא דר״י ואיתא בפרק בתרא דזבחים.\",2,0],[8,375,11,3,\"ומ\\\"ש וכשימול טובל ואוכל בקדשים לערב. שם ומסיים בה שכן מצינו באבותינו שהזו כשהם ערלים וכדתניא מלו וטבלו ועשו פסחיהם בטהרה:\",3,0],[8,375,11,4,\"מצות אזוב ג' קלחים וכו'. בפי\\\"א דפרה מצות אזוב שלשה קלחים ובהם שלשה גבעולין ובתר הכי קתני רבי יוסי אומר מצות אזוב שלשה וכו' ושיריו שנים וגרדומיו כל שהו ובפ\\\"ק דסוכה עלה י\\\"ג אסיקנא דלרבי יוסי ג' לעכב ולרבנן ג' למצוה וכדתניא אזוב תחילתו שנים ושיריו אחד כשר ואינו פסול עד שתהא תחילתו כשיריו א'.\",1,0],[8,375,11,4,\"ומה שכתב רבינו ושיריו שנים קשה דלתנא קמא שיריו אחד נמי כשר:\",2,0],[8,375,11,4,\"וכתב הר\\\"י קורקוס ז\\\"ל ואפשר דשיריו שנים שכתב רבינו היינו לומר שנים שנשתיירו חשובים כשלשה בתחילה ולכתחילה יכול להזות בהם ואח\\\"כ כתב ואם היו שנים בתחילה כשר פירוש בדיעבד ומינה לאחד שנשתייר דחשיב כשנים בתחילה דומיא דאינך דלכתחילה ובספרים כתוב או אם לקח ובספר כתיבת יד מצאתי ואם לקח והוא סיוע לפירוש זה דהוי מילתא באפי נפשה ועד השתא מיירי בלכתחילה ולמצוה והשתא אתא לאורויי בדיעבד ולעכב עכ\\\"ל. ואין דבריו מיושבים דלא משמע מדברי רבינו כלל דשיריו אחד כשר ולכן נ\\\"ל דרך אחר שכתב תחילה וז\\\"ל ואפשר שסובר רבינו דבהא פליגא ברייתא אמתני' דמאי דקתני במתניתין שיריו שנים דברי ת\\\"ק הם אלא שמה שלא נתבאר במשנה לרבנן דהיינו תחלתו הוא דמוכחינן מברייתא דסגי בשנים וג' למצוה ולא לעכב אבל במאי דפריש במתניתין שיריו שנים לא סמכינן אברייתא ונקטינן כמתניתין ומ\\\"מ זה דוחק עכ\\\"ל. ולי נראה שדרך זה הוא היותר נכון לומר בכוונת רבינו:\",3,0],[8,375,11,4,\"ומ\\\"ש רבינו אפילו לא נשאר מכל גבעול מהם אלא כל שהוא כשר, זהו ששנינו וגרדומיו כל שהוא ופירש\\\"י גרדומיו כשמזין בו פעמים הרבה מתוך שגבעוליו רכים משתברים וכל שהוא המשתייר באגודה כשר ובלבד שישתייר מכל אחת ואחת כל שהוא שתהא שם אגודתו קיימת.\",4,0],[8,375,11,4,\"ומ\\\"ש ושירי האזוב בכל שהוא, איני יודע מאי קאמר שהרי כתב דשנים בעינן בשיריו ואי אגרדומיו קאמר קשה שהרי כבר אמר ואם נאמר דה\\\"ק ששירי אזוב בכל שהו אכתי יקשה קצת למה שינה וקרא לגרדומים שירים:\",5,0],[8,375,11,4,\"קלח שיש בו ג' בדין וכו' עד כשר. בפי\\\"א דפרה שם:\",6,0],[8,375,11,4,\"האזוב הקצר וכו'. משנה רפי\\\"ב וכת\\\"ק.\",7,0],[8,375,11,4,\"ומ\\\"ש נסתפק לו וכו'. גם זה שם:\",8,0],[8,375,11,5,\"אין מזין לא ביונקות וכו' עד פטור. שם פי\\\"א:\",1,0],[8,375,11,5,\"ומאימתי מזין באזוב משינץ. הכי משמע בתוספתא שכתב רבינו שמשון פי\\\"א דפרה:\",2,0],[8,375,11,5,\"ואזוב שהוזה בו וכו'. משנה שם:\",3,0],[8,375,11,5,\"כל אזוב שיש לו שם לווי פסול וכו'. גם זה משנה שם:\",4,0],[8,375,11,6,\"אזוב של אשרה ושל עיר הנדחת ושל ע\\\"ז. תוספתא כתבה רבינו שמשון בפרק הנזכר ופירש רבינו שמשון של אשרה איכא לאוקמי באשרה דמשה משום דמיכתת שיעורה.\",1,0],[8,375,11,6,\"ומה שכתב ושל תרומה טמאה פסולה וכו' עד כשר. משנה בפרק י\\\"א דפרה וכתב רבינו שם ואם תאמר ואיך אפשר בו ההזאה והוא יטמא החטאת ואפילו היתה כתרומה טהורה וכו' לפי שכבר התבאר שהתרומה לא תטמא אא\\\"כ תהיה כביצה עכ\\\"ל. ולפי זה נאמר שגזרו פחות מכביצה אטו כביצה, ורבינו שמשון כתב שטעם תרומה טהורה לא יזה מפני שמפסידה א\\\"נ מפני שמכשירה לקבל טומאה:\",2,0],[8,375,11,7,\"אזוב שלקטו לעצים וכו'. גם זה משנה שם והטעם שמנגבו כדי שלא יתערבו מים פסולים עם מים כשרים.\",1,0],[8,375,11,7,\"ומ\\\"ש לקטו לחטאת וכו'. שם בפלוגתא דתנאי ופסק כרבים:\",2,0],[8,375,12,1,\"אדם שנטמא במת וכו' כיון שנגע כל שהוא ממי הנדה וכו'. בפרק דם חטאת (זבחים דף צ״ג) מסיק רבא דפליגי ר״א ורבנן בהזאה אי צריכה שיעור אי לא ורבנן סברי אינה צריכה שיעור.\",1,0],[8,375,12,1,\"ומ\\\"ש בכ\\\"מ מעור בשרו של טמא עלתה לו הזאה וכו' אבל אם נגעה בלשונו אינה כלום אע\\\"פ שהלשון כאיברים שבגלוי וכו'. פ\\\"ק דקידושין עלה כ\\\"ה וכחכמים:\",2,0],[8,375,12,1,\"וכן כלי שנטמא במת וכו'. זה בכלל מה שאמרו הזאה אין לה שיעור ומתניתין היא בסוף פרה מזין על האדם ועל הכלים אפילו הם מאה:\",3,0],[8,375,12,2,\"שני כלים וכו'. מתבאר ממה שיבא בסמוך:\",1,0],[8,375,12,2,\"והזה על שני כלים ונסתפק לו וכו'. בפרק י\\\"ב דפרה:\",2,0],[8,375,12,4,\"כלים המפוצלים. בריש פרק במה טומנין (שבת דף מ״ח ע״ב) וריש פרק במה אשה (שבת דף נ״ח ע״ב):\",1,0],[8,375,12,5,\"שני כלים שחברן. מתבאר ממה שיבוא בסמוך:\",1,0],[8,375,12,6,\"שלל הכובסין והבגד שהוא תפור בכלאים וכו' עד המפוצלת. בסוף פרה:\",1,0],[8,375,12,7,\"המחבר ג' כסתות וכו' עד כל שהן. פכ\\\"ט דכלים ויש כאן חסרון מט\\\"ס וכך היא הנוסחא הנכונה או י\\\"ב מטפחות הרי אלו חיבור לטומאה ולהזאה יתר מכאן חיבור לטומאה ולא להזאה:\",1,0],[8,375,12,8,\"כיסוי המיחם וכו'. בסוף פרה שם וכבית הלל:\",1,0],[8,375,12,9,\"הזוג והענבל חיבור וכו'. שם:\",1,0],[8,375,12,10,\"הכוש שפותלים בו החבלים וכו'. בסוף פרה כוש של רובן לא יזה לא על הכוש ולא על הפיקא ואם הזה מוזה של פשתן חיבור ופירוש רובן גמי שפותלים ממנו החבלים וטעם החילוק בין כוש של רובן לשל פשתן מפני ששל פשתן חלקיו מחוברים יותר:\",1,0],[8,375,12,10,\"וכתב הראב\\\"ד א\\\"א בכל מה שמאריך וכו'. אין זו השגה שרבינו בחיבור הזה אינו בא לפרש לשון המשנה ומ\\\"מ מתוך דבריו נלמד שרובן הוא דבר שפותלים ממנו החבלים:\",2,0],[8,375,12,11,\"עור של עריסה וכו'. שם ופירושו עור שמשימים על עריסה של קטן ודרכו להיות מחובר בטבעות הקבועים בעריסה ועשויין כעין פיקות:\",1,0],[8,375,12,11,\"המלבן של מטות וכו'. גם זה שם ופירושו שמניחים תחת כרעי המטה מלבנות של עץ שלא ירקבו מלחלוחית הקרקע והם חקוקים והכרע נכנס בהם:\",2,0],[8,375,12,12,\"כל ידות הכלים הקדוחות וכו'. שם וכת\\\"ק:\",1,0],[8,375,13,1,\"מעלות יתירות עשו בטהרת החטאת וכו' עד והיתה מטפחתו כמדרס הזב לענין החטאת. בספ\\\"ב דחגיגה (דף כ'):\",1,0],[8,375,13,3,\"כל ולד הטומאות אע\\\"פ שאינו מטמא אדם וכו' לפיכך אמרו המקדש מי חטאת לא ינעול את הסנדל וכו'. בפרק שמיני דפרה:\",1,0],[8,375,13,3,\"וכתב הראב\\\"ד הפיסקא אחרת ק\\\"ל וכו'. ויש לומר דכיון שאין זה מן הדין אלא מעלה בעלמא אע\\\"פ שאמרו שלא ינעול את הסנדל שהוא דבר קל לא הטריחו עליו לפשוט בגדיו. ומ\\\"ש ועוד עד שניחוש למשקין טמאים ניחוש לשאר טומאות וכו' י\\\"ל דמשקין עשויים ליפול על הסנדל שלא מדעת. ומ\\\"ש ועוד למה ליה למימר המקדש לימא הנוגע או המזה י\\\"ל דכיון דאין זה אלא משום מעלה בעלמא כשיקפידו בכך על המקדש סגי והר\\\"י קורקוס ז\\\"ל כתב שאפשר דלרבותא נקט מקדש דאפילו במקדש החמירו וכ\\\"ש במזה שראוי ליזהר יותר ומ\\\"מ מה שפירש הראב\\\"ד שלא חשו אלא שמא יפלו מהמשקין עצמם על הסנדל נכון הוא ולע\\\"ד נ\\\"ל כן בע\\\"א שחששו שמא יפלו ממי חטאת המקודשין על הסנדל ויטמאוהו וכן פירש ר\\\"ש בלשון שני וז\\\"ל ועוד יש לפרש במשקין שאחר הקידוש דמטמאין כלים ואין מטמאין אדם:\",2,0],[8,375,13,4,\"מי שנטמאו ידיו בלבד וכו'. משנה פרק ב' דחגיגה (דף י\\\"ח ע\\\"ב) ופרק י\\\"ב דפרה הטהור לחטאת שנטמאו ידיו נטמא גופו ומטמא את חבירו וחבירו את חבירו אפי' הם מאה.\",1,0],[8,375,13,4,\"ומ\\\"ש אפילו לא נטמא אלא ידו אחת וכו'. כך יש ללמוד ממה ששנינו בפרק י' דפרה הטהור לחטאת שנגע באוכלין בידו טמא:\",2,0],[8,375,13,5,\"כל הטעון טבילה וכו'. בפי\\\"א דפרה וכחכמים:\",1,0],[8,375,13,5,\"טמא שנגע במקצת אפר חטאת וכו'. ברפ\\\"ח דעדיות:\",2,0],[8,375,13,6,\"אין מונין לחטאת ראשון ושני ושלישי וכו'. מבואר במשנה שכתבתי בסמוך ומטמא את חבירו וחבירו את חבירו אפילו הם מאה ואיתא נמי בתוספתא פי\\\"א.\",1,0],[8,375,13,6,\"ומה שכתב וכן כלים הטהורים לחטאת. פרק י\\\"ב דפרה:\",2,0],[8,375,13,7,\"כל הראוי להתטמא במדרס הזב וכו'. משנה רפ\\\"י דפרה כל הראוי לטמא מדרס מדף לחטאת בין טמא בין טהור ואדם כיוצא בו:\",1,0],[8,375,13,7,\"וכתב הראב\\\"ד אם הנידו הטהור א\\\"א זהו מדף שבמשנה וכו'. וי\\\"ל שדבר זה שכתב רבינו מבואר במשנה שכתבתי בסמוך וחכ\\\"א הטמא מדף והטהור אינו מדף וכשהניד את הטמא מיירי ולא במגעו וכמו שכתב רבי' שם בארוכה והוכיח כן מהתוספת' וכן פי' ר\\\"ש ואותן שניות שהביא הראב\\\"ד אינן עניין למשנה זו דהתם בנוגע במדף שהוא עליונו של זב וכתבם רבינו לקמן בסמוך והכא במניד את הטומאה ונקרא מדף מלשון קול עלה נדף וביאר רבינו שם שהוא תנועה חלושה יותר מתנועת היסט:\",2,0],[8,375,13,7,\"ומ\\\"ש או שהניד את רוקו או את מימי רגליו וכו'. תוספתא כתבה ר\\\"ש בפרק י' דפרה.\",3,0],[8,375,13,7,\"ומ\\\"ש אבל כלי שאינו ראוי למדרס וכו' כלי הטמא בטמא מת וכו'. משנה שם ופסק כחכמים שאמרו הטמא מדף והטהור אינו מדף וביארו בתוספתא שטמא זה ששנינו היינו דוקא טמא מת.\",4,0],[8,375,13,8,\"ומה שכתב כיצד מפתח שהוא טמא מת וכו'. שם בתוספתא ואף על פי ששם אמרו דרבי יוחנן בן זכאי מטהר משמע דס\\\"ל כר\\\"א דאמר כל שאינו ראוי לטמא מדרס אינו מדף אף על פי שהוא טמא מת אבל לחכמים שאמרו שטמא מת מדף נטמא. ואמרו עוד בתוספתא על דברי חכמים הטמא שאמרו טמא מת ולא טמא מדף כלומר מה שאמרו חכמים שאם הכלי טמא נטמא המנידו דוקא כשהיה הכלי טמא מת אבל אם היה הכלי טמא טומאת מדף לבד לא נטמא המנידו כי זה הכלי הוא ולד הטומאה לבד ולכך כתב רבינו כלי הטמא בטומאת מת:\",1,0],[8,375,13,8,\"ומה שכתב וכן אם הסיט את השרץ או את שכבת זרע וכו'. שם בתוספתא ואף על פי ששם שנו נבילה עם אלו השמיטה רבינו מפני שנבילה מדאורייתא מטמאה בהיסט:\",2,0],[8,375,13,9,\"הטהור לחטאת שנגע בכלים וכו'. משנה שם וכתב הר\\\"י קורקוס ז\\\"ל איכא למידק שרבינו כתב למעלה אבל כלי שאינו ראוי למדרס אינו מטמא את הטהור לחטאת אלא א\\\"כ נגע בו ומשמע דאם נגע מיהת אפילו בכלי טהור גמור כל שאינו טהור לחטאת מטמא את האדם הנוגע בו דהא בכלי טהור גמור מיירי התם אלא שראוי למדרס ועלה דייק אבל אם אינו וכו' אא\\\"כ נגע ואילו הכא לא מטמאינן לאדם הנוגע בכלי אלא א\\\"כ היה טמא מדף מיהת דהיינו שהיה בעליונו של זב ומאי איריא משום שהיה בעליונו של זב תיפוק לי משום שאינו טהור לחטאת ונגע בו האדם הטהור ותירץ שמה שכתב רבינו למעלה היינו שנגע בידיו ואפשר דמשום הכי מסתם לה דלפעמים מטמא אדם או הכלי בנגיעה באי זו נגיעה שתהיה דהיינו כשהוא מדף ולפעמים מטמא בנגיעה בידיו לבד והיינו כל כלי שאין בו שום טומאה אלא שאינו טהור לחטאת דהוי כאוכלים טהורים ולמעלה קיצר וסתם כי אינו עיקר מקומו דכולה דין הנדה ותנועה מפרש שם ועתה מפרש דיני הנגיעה בפרטיו ובזה עלו דברי רבינו מכוונים עכ\\\"ל:\",1,0],[8,375,13,9,\"ומה שכתב וכן כלי. הוא דין כלי שהוזכר במשנה שם:\",2,0],[8,375,13,10,\"הטהור לחטאת שנגע באוכלין ומשקין וכו'. גם זה משנה שם:\",1,0],[8,375,13,10,\"ומה שכתב נגע בהם ברגלו וכו' טהור. אטהורים דוקא קאי אבל טמאים אפילו נגע בהם ברגלו נטמא דלא גרע מכלי טמא מדף שהוא ולד ומטמא את האדם הטהור לחטאת בכל נגיעה:\",2,0],[8,375,13,10,\"ומה שכתב או שהסיטן בידו. גם זה שם ופסק כחכמים.\",3,0],[8,375,13,10,\"ומה שכתב וכן אם נגע בידו בתנור וכו'. משנה שם:\",4,0],[8,375,13,11,\"הטהור לחטאת שהכניס ראשו ורובו כו'. בפרק אחד עשר דפרה הטהור לחטאת שהכניס ראשו לתוך מי חטאת נטמא וכתב שם רבינו כבר ביארנו שהטהור לחטאת לא יטמא במי חטאת וכו' וידוע הוא שמי חטאת מים שאובים הם ואם הכניס ראשו ורובו לתוך מי חטאת טמא לחטאת מצד מים שאובים ומעת שנטמא לחטאת יטמאוהו מי חטאת שנגע בהם וישוב ראשון לטומאה עד כאן לשונו:\",1,0],[8,375,13,12,\"הכל נאמנים על טהרת חטאת וכו'. פרק ה' דפרה.\",1,0],[8,375,13,12,\"ומה שכתב והרי נאמר בתורה וכו'. תוס' פ\\\"ג דחגיגה.\",2,0],[8,375,13,12,\"ומה שכתב לפיכך עם הארץ שהביא כלי מביתו וכו'. תוספתא דפרה:\",3,0],[8,375,14,1,\"כלי חרס שהיה בו אפר חטאת וכו'. משנה פרק עשירי דפרה קלל של חטאת שנגע בשרץ טהור נתנו על גביו ר\\\"א מטהר וחכמים מטמאין וידוע דהלכה כחכמים.\",1,0],[8,375,14,1,\"ומ\\\"ש שנאמר והניח וכו' במקום טהור וכו'. בסיפרי.\",2,0],[8,375,14,1,\"ומה שכתב ולא על גבי השרץ בלבד אלא אפילו הניחו על גבי אוכל שני וכו'. שם נגע באוכלין ומשקין ובכתבי הקדש טהור נתנו על גביהן ר' יוסי מטהר וחכמים מטמאין ואיני יודע למה השמיט רבינו כתבי הקדש.\",3,0],[8,375,14,1,\"ומ\\\"ש שלא יהיה על גבו שום טומאה. ט\\\"ס הוא וצריך להגיה שלא יהיה על גבי שום טומאה:\",4,0],[8,375,14,1,\"וכן כלי חרס שהיה בו אפר חטאת וכו'. תוספתא דאהלות:\",5,0],[8,375,14,1,\"וכתב הר\\\"י קורקוס ז\\\"ל וז\\\"ל של אבן טהור כתב ר\\\"ש מאחר דלא מקבל טומאה לא מד\\\"ת ולא מד\\\"ס ע\\\"כ. והדבר קשה כיון שהוא משולשל לתוך הבית כי הוי של אבן מאי הוי והרי גל שהוא במקום טמא אין הפרש בין חרס לאבן שהרי גם חרס אינו מיטמא מגבו ואפילו הכי נטמא ורבינו נראה שלא טיהר רק באינו משולשל ולכך לא כתב בין משולשל בין שאינו משולשל אלא בין אין בו טפח בין יש בו טפח ומשמע דאדסמיך ליה לחוד קאי דהיינו אינו משולשל ולא בא לחדש בשל אבן אלא יש בו טפח ותוספתא אפשר דל\\\"ג בה רבינו בין משולשל עכ\\\"ל:\",6,0],[8,375,14,3,\"וכן כלי שיש בו אפר וכו'. משנה פי\\\"א דפרה החטאת אינה ניצולת בצמיד פתיל ומים שאינן מקודשין ניצולין בצמיד פתיל:\",1,0],[8,375,14,4,\"וכן אוכלין ומשקין של קדש וכו'. מימרא פרק חומר בקדש (דף כ\\\"ב) וכתב רבינו שם כי התורה לא הצריכה מקום טהור אלא לאפר ולמים מקודשים מפני האפר שבהם ומשם נתבאר לרבינו.\",1,0],[8,375,14,4,\"ומה שכתב וכלי ריקן הטהור לחטאת וכו': במה דברים אמורים כשהיו הבעלים טהורים וכו'. תוספתא פ\\\"ו דפרה מי שהיה הוא ומימיו באהל המת ומימיו מוקפים צמיד פתיל כשהוא טהור (כך) מימיו טהורים הוא מבפנים ומימיו מבחוץ כשם שהוא טמא כך מימיו טמאים הוא מבחוץ ומימיו מבפנים כשם שהוא טהור כך מימיו טהורים:\",2,0],[8,375,14,4,\"וכתב הראב\\\"ד א\\\"א מצאתי בשתי נוסחאות כשם שהוא טהור וכו'. ואני אומר שנוסחתו משובשת דקתני כשם שהוא טהור כך מימיו טהורים ובדין היה לו ז\\\"ל לומר לא ידעתי מהו אבל הנוסחא האמיתית כמ\\\"ש כשהוא טהור מימיו טהורים ותנא והדר מפרש כיצד שאם הוא בחוץ ומימיו מבפנים כשם שהוא טהור כך מימיו טהורים. ומ\\\"ש הראב\\\"ד ואולי אמר אם הוא והם מוקפים צמיד פתיל וכיוצא בהם ה\\\"ז טהורים עכ\\\"ל טעמו ממה שנתבאר בפ' כ\\\"ג מה' טומאת מת שצמיד פתיל מציל על האדם באהל המת. ומ\\\"ש כללו של דבר חכמים הולכים אחר התופס המים בידו ור\\\"ע הולך אחר המים והלכה כחכמים עכ\\\"ל. לא ידעתי מקום מחלוקת ר\\\"ע וחכמים בזה ובספר כ\\\"י נמצא כתוב לשון זה בפני עצמו וקאי לדין שיבוא בסמוך שנחלקו בו ר\\\"ע וחכמים:\",3,0],[8,375,14,5,\"הטהור לחטאת שהיה עומד על גבי התנור וכו'. משנה בפ\\\"י דפרה וכחכמים.\",1,0],[8,375,14,5,\"ומ\\\"ש וכן הזייה שעברה על גבי טומאה וכו'. בפרק דם חטאת עלה צ\\\"ג:\",2,0],[8,375,14,7,\"כלי שיש בו מימי חטאת וכו'. משנה ספ\\\"י דפרה לגין של חטאת שנגע בשל קדש ושל תרומה של חטאת טמא של קדש ושל תרומה טהורים שניהם בשתי ידיו שניהם טמאים שניהם בשתי ניירות שניהם טהורים של חטאת בנייר ושל תרומה בידו שניהם טמאים של תרומה בנייר ושל חטאת בידו שניהם טהורים:\",1,0],[8,375,14,7,\"וכתב הראב\\\"ד שהם מטמאים במשא מפני שנטמאו א\\\"א נ\\\"ל צריך להיות אע\\\"פ שנטמאו וכו'. ביאור דבריו שהוקשה להראב\\\"ד למה נתן טעם לטומאתו בנשיאת מי נדה מפני שנטמאו מחמת הכלי של קדש תיפוק לי שמי נדה אפילו לא נטמאו מטמאין את האדם במשא ולכך הגיה וכתב אע\\\"פ במקום מפני וה\\\"ק אע\\\"פ שנטמאו מחמת הכלי של קדש וכיון שכן בטל חשיבותן ולא היה ראוי לטמא במשא אעפ\\\"י כן הם מטמאין במשא ואח\\\"כ חזר לקיים גירסת מפני וה\\\"פ שאמר רבינו אם תקשה למה תליתי טומאת כלי של חטאת מפני שנגע בו אדם שנגע בכלי שאינו טהור לחטאת שאין טומאתו אלא משום מעלה בעלמא עדיפא הל\\\"ל שכלי חטאת נטמא מפני שנגע בו אדם שנשא מי חטאת שהוא טמא מדאורייתא די\\\"ל דכיון שנפסלו מחמת שנגע בהם אדם שנוגע בכלי שאינו טהור לחטאת בטלה ממנו טומאה זו. ומה שכתב ויש לזה שורש במשנה הוא בספ\\\"ט זהו פי' דברי הראב\\\"ד אבל טעם רבינו הוא מבואר בפירוש המשנה שלפרש משנה זו הניח ז' שרשים ובשורש הז' כתב שמי חטאת לא יטמאו האיש אשר הוא טהור לחטאת בלוקחו אותם כמו מה שיטמאו זולתו [במגע ובמשא] ואם היה טמא לחטאת אשר לא יכון לחטאת הנה מי חטאת יטמאוהו במגע ובמשא וכו' וכשהגיע לחלוקה זו כתב וכששב טמא לחטאת מפני החזיקו לגין של קדש בידו נטמא גם לגין של חטאת אשר בידו האחרת ומפני היותו ג\\\"כ טמא לחטאת יטמאו אותו מי חטאת אשר נשא בידו כמו שביארנו בשורש הז' מאלו השרשים וישוב טמא לתרומה ג\\\"כ ולזה יטמא לגין של תרומה או של קדש אשר בידו מפני מי חטאת אשר בידו השנייה. ובדין שניהם טהורים כתב ולזה אמרנו אם היה לגין של תרומה בנייר ושל חטאת בידו שניהם טהורים לפי שהוא לא יטמא בלגין של תרומה לפי שהנייר מבדיל ביניהם וישאר טהור לחטאת כמו שהיה ויהיה [לגין] של חטאת שבידו השנייה טהור ולא יטמאוהו [ג\\\"כ] נשיאות מי חטאת לפי שהוא ראוי להזות עכ\\\"ל:\",2,0],[8,375,14,8,\"ומ\\\"ש הסיט ב' כלים בידו וכו'. שם וכחכמים.\",1,0],[8,375,14,8,\"ומ\\\"ש כמו שביארנו. הוא בפרק שקודם זה:\",2,0],[8,375,14,9,\"כל ספק הטומאות וכו'. משנה פי\\\"ב דפרה כל ספק הטהור לתרומה טהור לחטאת כל התלוי לתרומה נשפך לחטאת אם עשו על גביו טהרות תלויות ופירש רבינו אם יש חולין שעשו אותם על טהרת הקדש ועל טהרת החטאת והודיענו שאם נעשו על טהרת החטאת ונתחדש להם כמו זה הספק ישארו תלויות ולא נאמר הואיל ונעשו על טהרת החטאת וכמו שהספק בחטאת תשפך ג\\\"כ אלו הטהרות ישרפו מפני שאלו נעשה לאכילה ולכך אין לשורפם אמנם החטאת אינה לאכילה ולכך אפילו שתשפך אין חשש. וידוע דאם עשו על גביו קאי אספק שעשו על גבי ספק זה טהרות:\",1,0],[8,375,14,9,\"והרפפות אינם ככלים וכו'. [שם במשנה] הרפפות טהורות לקדש ולתרומה ולחטאת ופירש רבינו רפפות שבכות מעץ ואמר שאינם כלים שיקבלו טומאה ולזה לא יטמאו לא קדש ולא תרומה לפי שהם אינם ראויים לטומאה:\",2,0],[8,375,14,10,\"דבילה של תרומה וכו'. משנה פי\\\"א וכת\\\"ק והקשה רבינו שמשון היכי פסיק ותני חייב מיתה והא כל שהיא טמאה אינו חייב מיתה כדאמר שמואל בפרק כל הבשר ופסקה רבינו בפ\\\"ז מה' תרומות ותירץ הר\\\"י קורקוס ז\\\"ל שנראה שדעת רבינו דכי קתני האוכל חייב מיתה היינו כמו שחייב באוכל תרומה והוא טמא דהיינו בשהיא טהורה דהכא לא נחית תנא אלא לאשמועינן שהוא נטמא בנגיעה זו דהויא נגיעת מי חטאת שלא לצורך ונטמא טומאה שחייב מיתה באכילת הדבילה בשביל אותה טומאה ובודאי דהוי דיניה כדין טמא בעלמא דאטהורה חייב מיתה ואטמאה פטור. ובין טמאה וכו' ה\\\"ק לא מיבעיא כשהיא טמאה שנטמאו המים אלא אפילו שהיא טהורה נטמאו דלגבי חטאת הויא טמא ואותו שאכלה כדתקני נטלה ואכלה אם יש בה כביצה חייב מיתה ככל טמא דעלמא והיינו כשהיא טהורה וא\\\"ת והרי נטמאו המים והמים יחזרו ויטמאו אותה אפילו היתה טהורה הא לא קשיא ההוא מעלה בעלמא ואין טומאת מעלה פוטרתו מחיוב מיתה מן התורה כל שכן שאע\\\"פ שנטמאו לחטאת לא מפני זה יחזרו ויטמאו את הדבילה עד כאן לשונו:\",1,0],[8,375,15,1,\"הנוגע במי חטאת שלא לצורך הזאה. כלומר דאילו הנוגע בהם לצורך הזאה טהור הוא וכמ\\\"ש רבינו בפירוש המשנה פ\\\"ק דכלים הלכה שניה בשם התוספתא שאין נושא מי חטאת או נוגע בהם טמא אא\\\"כ שלא לצורך אבל אם היה לצורך טהור.\",1,0],[8,375,15,1,\"ומה שכתב הנה למדת שמי הנדה אב מאבות הטומאה. יליף הכי מדמטמאים אדם וקי\\\"ל אין אדם וכלים מקבלים טומאה אלא מאב הטומאה:\",2,0],[8,375,15,1,\"ומ\\\"ש וטומאת מגען בכל שהוא וכו'. בריש כלים תנן דמי חטאת שאין בהם כדי הזאה הרי אלו מטמאים אדם וכלים במגע וכו' ואינם מטמאין במשא וכו' [ואם] יש בהם כדי הזאה מטמאים את האדם במשא לטמא בגדים:\",3,0],[8,375,15,1,\"ומה שכתב רבינו שאינו מטמא בגדים אלא בשעת מגעו. כן כתבו שם רבינו ורבינו שמשון והוא ממה ששנינו בסוף זבים כלל אמר ר' יהושע כל המטמא בגדים בשעת מגעו וכו' לאחר פרישתו ממטמאיו וכו' ואינו מטמא בגדים והק\\\"ו שכתב רבינו הוא בספרי:\",4,0],[8,375,15,1,\"ומה שכתב רבינו שהנוגע במי חטאת מטמא בגדים. יש לתמוה דבריש כלים שם אנבילה ומי חטאת שיש בהם כדי הזאה שהם מטמאים את האדם במשא לטמא בגדים וחשוכי בגדים במגע פירש ר\\\"ש שמנועים הבגדים מטומאה אי איכא מגע בלא משא ושמא י\\\"ל דסבר רבינו דלא קאי האי וחשוכי בגדים אלא אנבילה בלחוד וקצת משמע כן מדברי רבינו שמשון אע\\\"פ שה\\\"ר עובדיה כתב דאמי חטאת נמי קאי. ואחר כך מצאתי לרבינו שכתב בפ\\\"י משאר אבות הטומאה מי חטאת שיש בהם כדי הזאה אע\\\"פ שהם כנבלה וכמרכב שאין מטמאין בגדים אלא הנושאן הרי הנוגע בהם מטמא בגדים בשעת מגעו משום נושא שא\\\"א שיגע במים שלא יסיט אותם והשתא מתניתין דוחשוכי בגדים במגע ה\\\"פ כשנגע במי חטאת אינם מטמאים בגדים מטעם מגע אלא מטעם משא שבמגעו שא\\\"א שיגע במים שלא יסיט:\",5,0],[8,375,15,1,\"ומה שכתב רבינו אינו מדבר במזה על הטמא וכו'. פ\\\"ק דנדה עלה ט'.\",6,0],[8,375,15,1,\"ומ\\\"ש וכמה הוא שיעור הזאה וכו'. בפי\\\"ב דפרה:\",7,0],[8,375,15,1,\"בד\\\"א שמי חטאת מטמאין וכו' אבל אחר שעשו מצותן אינן מטמאין כלל. כך היא הנוסחא הנכונה בדברי רבינו והדין הוא משנה שם מי חטאת שעשו מצותן שאינם מטמאין וקתני במתניתין שהיו עושין מעשה כן ולפיכך פסק רבינו כן ולא חשש למה ששנינו בפ\\\"ה דעדיות (משנה ג') שזה מקולי ב\\\"ש וחומרי ב\\\"ה שזהו דעת ר' ישמעאל לבדו ולא קי\\\"ל כוותיה. ומה ששנינו שם המנטפים כשירים ולפיכך הם מטמאים לשם מי חטאת. כבר ביאר רבינו דהיינו דוקא בשטבל האזוב להזות על דבר שאינו מקבל טומאה:\",8,0],[8,375,15,1,\"וכתב הראב\\\"ד שאינו מקבל טומאה א\\\"א כתבתי למעלה מה שנ\\\"ל מהתוספתא עכ\\\"ל. הוא בפרק עשירי ושם כתבתי ליישב דעת רבינו:\",9,0],[8,375,15,2,\"אין מי חטאת מטמאין את הכל וכו' אבל מי חטאת שנפסלו וכו':\",1,0],[8,375,15,3,\"מי חטאת שנטמאו וכו'. פ\\\"ט דפרה מי חטאת שנפסלו מטמאין את הטהור לתרומה בידיו ובגופו ואת הטהור לחטאת לא בידיו ולא בגופו נטמאו מטמאין את הטהור לתרומה בידיו ובגופו ואת הטהור לחטאת בידיו אבל לא בגופו פירוש נפסלו פי' ששתת מהם בהמה וכיוצא מטמאים את הטהור לתרומה כאילו היו מים כשרים בין שנגע בהם בידיו בין שנגע בהם בגופו דכמי חטאת כשירים חשיבי וטומאה זו דרבנן היא דמדאורייתא כיון שנפסלו פרחה מהם טומאה החמורה ומשום הכי תני מטמאין את האדם דמשמע הטהור לתרומה דוקא לתרומה אבל לא לחולין ואת הטהור לחטאת לא בידיו כלומר אין מטמאין את הטהור בין נגע בהם בידיו בין נגע בהם בגופו וכתב שם רבינו שהטעם לפי שהוא ממין מה שהוא טהור לו ואם נטמאו מי חטאת ונגע בהם הטהור לחטאת בידיו נטמא גופו כדין טהור לחטאת שנגע במשקין טמאין אבל אם נגע בהם בגופו לא נטמא שכן דין נוגע במשקין טמאין:\",1,0],[8,375,15,4,\"מי חטאת שנפלו לתוכן מי מעיין וכו'. תוספתא פ\\\"ח ומסיים בה בין כך ובין כך פסול להזות [מהן] והשמיטו רבינו לפי שסמך על מ\\\"ש בפרק תשיעי:\",1,0],[8,375,15,4,\"וכתב הר\\\"י קורקוס ז\\\"ל וק\\\"ל שהרי כבר נתבאר דמי חטאת שנפסלו פרחה לה טומאת התורה מינייהו ולכך נוגע בהם טהור לחטאת והכא קתני מטמאים במשא ומשמע טומאה גמורה ככל מי חטאת ואין לומר דמיעוטא לא מטמא אלא מדרבנן דהא נתערב מים סתמא כתב בסמוך ועוד דשתת מהם בהמה שכתב לדעתו משום תערובת הרוק הוא והוי כל שהו ואפשר לומר כי מה שטהרנו לחטאת היינו במגע אבל במשא כיון שנושא אותם והם מי חטאת ואע\\\"פ שנתערב בהם כל שהוא ונפסלו מפני שנמצאת טבילת האזוב חציה מן הפסול ואנן בטבילה בעינן שיעור מ\\\"מ כשנושא כולם הרי נושא מי חטאת שיעור הזאה ולכך מטמאים במשא ולא במגע ועדיין אינו נוח לי עכ\\\"ל:\",2,0],[8,375,15,4,\"אפר פרה שנתערב באפר מקלה וכו'. פ\\\"ט דפרה אפר כשר שנתערב באפר מקלה הולכין אחר הרוב לטמא.\",3,0],[8,375,15,4,\"ומ\\\"ש אבל מטמאים במשא. בפ\\\"ג דבכורות עלה כ\\\"ג:\",4,0],[8,375,15,5,\"אפר כשר שנתנו על גבי המים שאינם ראויים לקדש וכו'. פ\\\"ט דפרה דהוי דינם כדין מי חטאת שנפסלו:\",1,0],[8,375,15,6,\"מי חטאת שנפסלו וכו'. שם וכת\\\"ק.\",1,0],[8,375,15,6,\"ומ\\\"ש שנא' חטאת היא. כתב שם רבינו בספרי מייתי לה מהאי קרא:\",2,0],[8,375,15,7,\"פרה ששתת מי חטאת וכו'. שם פרה ששתתה מי חטאת בשרה טמא מעת לעת רבי יהודה אומר בטלו במעיה וסבר רב אשי בפרק קמא דפסחים (דף י\\\"ח) דלרבי יהודה בטלו לגמרי דאפילו טומאה קלה לא מטמאה ופסק רבינו כרבי יהודה משום דאמרינן בספרי ובפירקא בתרא דמקואות דל\\\"ח זקנים ור' יוסי הגלילי ור' טרפון כולם סוברים כרבי יהודה:\",1,0],[8,375,15,8,\"המזה מחלון שמזין ממנו על הרבים וכו'. בפרק י\\\"ב דפרה וכתב שם רבינו עוד טעם אחר משום דמחלון של רבים דומה לספק טומאה ברשות הרבים ומחלון של יחיד דומה לספק טומאה ברשות היחיד:\",1,0],[8,375,15,8,\"מחליקין היו העם וכו'. גם זה שם:\",2,0],[8,375,15,8,\"וכתב הראב\\\"ד שמא פסולים הן א\\\"א ורובן מן המים שעשו מצוותן עכ\\\"ל. ואיני יודע מה מלמדנו דמאי דתנן המים שעשו מצוותן שעשו כולם מצוותן ודאי הם ולא רובן בלבד אלא כולם נמי בחזקת שנעשו מצוותן הם:\",3,0],[8,375,15,9,\"המזה באזוב הטמא לחטאת וכו'. בפי\\\"ב דפרה המזה באזוב טמאה אם יש בו כביצה המים פסולים וכו' ופירש שם רבינו דהמים פסולים היינו באזוב הטמא לחטאת אבל אם היה האזוב הטמא לקדש או לתרומה המים טמאים ובספרי רבינו כתוב כאן גבי כביצה והזייתו כשירה והוא טעות סופרים וצריך להגיה והזייתו פסולה וכך הוא בספר מוגה:\",1,0],[8,375,15,9,\"ומה שכתב ואזוב זה מטמא את חבירו. לאו אדסמיך ליה קאי אלא איש בו כביצה כי אין אוכל מטמא אוכל עד שיהא בו כביצה:\",2,0],[8,375,15,10,\"המגביה כלי שהוזה עליו וכו'. שם אוחז הוא הטהור בקרדום הטמא ובכנפו ומזה עליו אע\\\"פ שיש עליו מים כדי הזייה טהור וכפי' ר\\\"ש שם:\",1,0],[8,375,15,10,\"נשלמו הלכות פרה אדומה:\",2,0],[8,376,1,1,\"צרעת עור הבשר הוא שילבין מקום מן העור וכו'. בריש נגעים תנן מראות נגעים שנים שהם ד' בהרת עזה כשלג שנייה לה כסיד ההיכל שאת כקרום ביצה שנייה לה כצמר לבן דר\\\"מ וחכ\\\"א שאת כצמר לבן שנייה לה כקרום ביצה ובריש שבועות (דף ה' ע\\\"ב) אמרינן דמתניתין דלא כר\\\"ע דאי ר\\\"ע כיון דאמר זו למעלה מזו א\\\"כ טהרת סיד ההיכל מלצרף בהדי מאן לצרפיה לצרפיה בהדי בהרת איכא שאת דעדיפא מינה לצרפיה בהדי שאת לאו תולדה דידה הוא וכו' והיכא שמעינן לר\\\"ע [דאמר] זו למעלה מזו אילימא מהא דתניא א\\\"ר יוסי שאל יהושע בנו של ר\\\"ע מר\\\"ע מפני מה אמרו מראות נגעים שנים שהם ארבעה אמר ליה ואי לאו מה יאמרו יאמרו מקרום ביצה ולמעלה טמא א\\\"ל לומר שמצטרפין זה עם זה א\\\"ל ויאמרו מקרום ביצה ולמעלה טמא ומצטרפין זה עם זה א\\\"ל לומר לך כל כהן שאינו בקי בהן ובשמותיהן אינו רואה את הנגעים ואילו מסיד ההיכל ולמעלה לא קאמר מדלא א\\\"ל ש\\\"מ דשמיע ליה לר\\\"ע דאמר כולהו לבהדי שאת מצטרפין ודילמא שאת ותולדתה בהרת ותולדתה אלא מדרבי חנינא ופירש\\\"י מי ששנה משנה זו בלשון אבות ותולדות דלא כר\\\"ע דאי כר\\\"ע כיון דאמר לקמן מראות נגעים זו למעלה מזו נשנו כסדר מעלתן השלג והצמר והסיד והקרום ואמרינן לקמן שכסדר משנתן הם מצטרפין זה לזה ואין אחד מצטרף לגבוה ממנו שתי מעלות [אלא מעלה אחת]. א\\\"כ דהוא שנאן בלשון אבות ותולדות טיהרת מראה סיד מלהצטרף דמדמתני לסיד שנייה לבהרת ולא תניא נמי שניה לשאת והרי אף משאת היא פחותה ש\\\"מ ס\\\"ל לתנא דלאו בת מינא דשאת היא ולא מצטרפא בהדה ומהשתא בהדי מאן נצרפה אי בהדי בהרת אביה הא איכא שאת שהיא כצמר דעדיפא מינה בלובן נמצאת בהרת למעלה מהסיד שתי מעלות ור\\\"ע זו למעלה מזו בעי נצרפה בהדי שאת שהיא מעלה אחת לאו תולדה דידיה דהא שקלת לה מיניה ושויתה מין בהרת ולר\\\"ע הכי איבעי ליה למיתני בהרת עזה כשלג ושאת כצמר לבן ושניה לה סיד ההיכל וקרום דנימצי למימר כולהו מינא דהדדי נינהו ובהרת ושאת מצטרפין ושאת וסיד נמצא לו צירוף לסיד והכי אמרינן בת\\\"כ בבהרת ושאת דמצטרפי והיה מלמד שמצטרפין זה עם זה אבל השתא דמחלקת תולדה לזו ותולדה לזו סבירא לן שאין מצטרף כל אחד כי אם עם אביו עכ\\\"ל:\",1,0],[8,376,1,1,\"ולפי זה לרבנן בהרת ושאת מצטרפין זה עם זה מדכתיב והיה ולא כתיב והיו אבל סיד אינה מצטרפת אלא עם בהרת אביה וקרום ביצה אינה מצטרפת אלא עם שאת אביה דשתי התולדות אינן מצטרפות דתולדה דבהרת אינה מצטרפת עם תולדה דשאת דלא קאי והיה אלא אשאת ובהרת דכתיבי בהדיא במקרא ולא אתולדות דאתו מרבויא. ולר\\\"ע אין מצטרפין אלא כסדר מעלתן וכצמר וכסיד וכקרום ואין אחד מצטרף לגבוה ממנו שתי מעלות אלא מעלה אחת והא דתנן בפ\\\"ק דנגעים ד' מראות הללו מצטרפין זה עם זה כבר פירש\\\"י שם לא שיהיו כל ד' מראות מצטרפין דאין התולדה מצטרפת אלא עם האב שלה אלא מצטרפין לר\\\"ע כדאית ליה ולרבנן כדאית להו. והשתא רבינו שכתב שנגע שהיה מקצת הלובן כמראה הבהרת ומקצתו כמראה השאת ומקצתו כמראה הספחת הכל כמראה אחד הוא חשוב דלא כרבנן ולא כר\\\"ע:\",2,0],[8,376,1,1,\"ונ\\\"ל שרבינו מפרש דמאי דאמר ר\\\"ע זו למעלה מזו וזו למעלה מזו לא לענין צירוף קאמר דאינה מצטרפת לגבוה ממנה שתי מעלות כדפירש\\\"י אלא כל ד' מראות מצטרפין זה עם זה אפילו לגבוה ממנה ג' מעלות כפשטא דמתני' וכדמשמע מדא\\\"ל ר' יהושע לר\\\"ע יאמרו מקרום ביצה ולמעלה מצטרפין זה עם זה ולפי זה ניחא שאינו צריך לידחק במה שנדחקו רש\\\"י והתוספות במאי דא\\\"ל יאמרו מקרום ולמעלה טמא ומצטרפין וכן מפורש בהדיא בירושלמי וז\\\"ל ומנין שמצטרפין זה עם זה אמר רבי מנא מנו אותם חכמים שנים ומנו אותם ד' מה שנים מצטרפין זה עם זה אף ד' מצטרפין זה עם זה ר\\\"א בשם רבי אבין אם בשאינו מינו מצטרף לא כ\\\"ש מין במינו עכ\\\"ל פי' בשאינו מינו בהרת עם שאת מין במינו פי' אב ותולדתו ונראה שבאו לאפוקי דלא נימא דרשא דוהיה מלמד שמצטרפים בהרת עם שאת וכדפירש\\\"י אלא כולן מצטרפין זה עם זה ואף לר\\\"א בשם ר' אבין כיון שמצטרפים עם שאת שאינו מינו אמרינן דה\\\"ה לתולדה דשאת מצטרף והא דקאמר זו למעלה מזו היינו לענין חוזק לבנונית של זה על זה דר\\\"ע סבר דשלג לבן מצמר וצמר לבן מסיד וסיד לבן מקרום ורבנן סברי דשלג לבן מסיד וצמר לבן מקרום וכדאמרינן בגמרא (דף ו' ע\\\"ב) משל דרבנן למה הדבר דומה לתרי מלכי ותרי אפרכי וכו' מלכו של זה למעלה מאפרכיה דנפשיה ומלכו של זה למעלה מאפרכיה דנפשיה וסיד וצמר מוחלקין בלבנוניתם זה מזה וכן שלג וצמר ואפ\\\"ה מצטרפי הני מדכתיב והיה וסיד מצטרף עם שלג משום דתולדה דידיה היא וכן קרום מצטרף עם צמר משום דתולדה דידיה היא והא דאמרינן בגמרא סיד בהדי מאן לצרפיה וכו' היינו אי מתניתין ר\\\"ע דלבנונית של זו למעלה מזו וזו תולדתו של זו וזו תולדה של זו כמתניתין אבל לפום קושטא דמתני' דלא כר\\\"ע לית ליה לר\\\"ע אב ותולדה אלא כולן מצטרפות זו עם זו אפי' עם הגבוה ממנה ג' מעלות דוהיה משמע ליה דאכולהו קאי ופסק רבינו כר\\\"ע משום דאע\\\"ג דסתמא דמתני' דריש נגעים דלא כוותיה הא איכא סתמא אחרינא דפשטא דידה כוותיה אתיא דקתני ד' מראות אלו מצטרפות זו עם זו כך היה נראה לומר כדי ליישב לשון זה שכתב רבינו נגע שהיה מקצת הלובן כמראה הבהרת וכו' הכל כמראה אחד הוא חשוב אבל יקשה לזה מ\\\"ש קודם לכן שהמראה שהוא כסיד ההיכל הוא ספחת הבהרת והמראה שהוא כקרום ביצה הוא ספחת השאת מכאן אמרו מראות נגעים שנים שהן ד' בהרת וספחתה שאת וספחתה והיינו כרבנן:\",3,0],[8,376,1,1,\"ואיכא למידק על רבינו דמיחזי כמזכי שטרא לבי תרי דמהאי לישנא משמע דפסק כרבנן ומאידך לישנא שכתב נגע שהיה מקצת כמראה הבהרת וכו' הכל כמראה אחד הוא חשוב א\\\"כ למה מנאום חכמים וכו' שכל כהן שאינו מכיר המראות ושמותיהן וכו' משמע דפסק כר\\\"ע ויש לתמוה על הראב\\\"ד שלא השיגו בזה:\",4,0],[8,376,1,1,\"וליישב דברי רבינו נ\\\"ל שהוא סובר דכי אמרינן מתניתין דלא כר\\\"ע היינו למאי דס\\\"ד דר\\\"ע סבר זו למעלה מזו כלומר ואין זו מצטרפת לגבוה ממנה שתי מעלות אבל בתר הכי לא אשכחן ליה דסבר הכי דהא כי בעינן לאתויי מדשאל רבי יהושע לר\\\"ע דחי ליה וכי הדר מייתי מדרבי חנינא דחי ליה אימור דשמעת ליה בפתוך בחלוק מי שמעת ליה וכי תימא כי היכי דשמעת ליה בפתוך הכי שמעת ליה בחלוק ובפתוך גופיה מי שמעת ליה והתניא ר\\\"ע אומר אדמדם שבזה ושבזה וכו' אמרי אה\\\"נ והתניא רבי נתן אומר לא שאמר ר\\\"ע של סיד דיהה הימנה אלא של צמר דיהה הימנה והשתא לא שני אלא מאי דאקשי ליה בפתוך מי שמעת ליה אבל מאי דאקשי ליה אימור דשמעת ליה בפתוך בחלוק מי שמעת ליה קשיא ואפילו מאי דשני בפתוך לאו שינויא הוא לגמרי דהא במתני' תנן בר\\\"ע של סיד דיהה הימנה ודלא כרבי נתן ומעתה כיון דלא אשכחן לר\\\"ע שלא תצטרף זו עם שלמעלה שתי מעלות בחלוק מיהא שפיר אתיא מתניתנין כר\\\"ע וכיון דאשכחן לר\\\"ע דמקרום ולמעלה מצטרפין כל ד' מראות זו עם זו אפילו עם הגבוה ממנה שלש מעלות ולא אמרו שנים שהם ד' אלא לומר לך כל כהן שאינו בקי בהם ובשמותיהן אינו רואה את הנגעים אית לן למימר דמתני' נמי הכי סברה וליכא פלוגתא בינייהו דמתני' דקתני להו בלשון אבות ותולדות לא לענין צירוף תני להו אלא לענין שצריך הכהן להיות בקי בהן ובשמותיהן אבל כולם מצטרפות זו עם זו ובהכי ניחא דבעי התם גמרא סתמא ספחת לבהרת מנ\\\"ל ואי איתא ה\\\"ל לפרושי דלרבנן דוקא קא בעי ומדסתים ליה סתומי משמע דלכולי עלמא בעי דליכא פלוגתא בינייהו:\",5,0],[8,376,1,3,\"וכתב הראב\\\"ד ולובן שהוא דיהה א\\\"א שנה משנתו כר\\\"ע וכו'. נראה מדבריו שהוא מפרש דר\\\"ע דאמר זו למעלה מזו היינו לומר שלובן של זו יותר מזו ולובן של זו יותר משל זו ורבנן פליגי ואמרי דסיד וצמר לבנוניתם שוה אלא דשל סיד נוטה ללובן השלג ושל צמר נוטה ללובן אחר ומש\\\"ה תמה על רבינו למה פסק כר\\\"ע ולא כסתם מתני' ובמ\\\"ש לדעת רבינו אין מקום להשגה זו. וכתב עוד הראב\\\"ד זה עם זה בין להקל א\\\"א אינו נראה כן מן הגמרא וכו'. וגם להשגה זו אין מקום במ\\\"ש לדעת רבינו:\",1,0],[8,376,1,4,\"היה במראה הלובן מד' מראות אלו מקצת אדמומיות מעורבת בו וכו'. בפירקא קמא דנגעים.\",1,0],[8,376,1,4,\"ומ\\\"ש וכיצד מראה הפתוך בארבע מראות אלו וכו'. בריש שבועות (דף ו').\",2,0],[8,376,1,4,\"ועל מה שכתב רבינו הפתוך שבבהרת הוא המראה הרביעית כתב הראב\\\"ד א\\\"א נ\\\"ל כי זה שיבוש וכו'. טעמו לפי שהוא מפרש שהסדר הוא מלמעלה למטה שהכוס שבו שני טיפי דם הוא בבהרת ושיש בו ארבעה טיפי דם הוא בצמר ושל שמנה טיפין הוא בסיד ושל י\\\"ו טיפין הוא בקרום ורבינו סובר שהסדר הוא מלמטה למעלה וטעם רבינו מבואר שכל שהלובן שלו יותר אינו ניכר שהוא פתוך אלא אם כן יפלו בו הרבה טיפי דמים:\",3,0],[8,376,1,5,\"כל המראות האלו בין הלבן בין הפתוך מצטרפין זה עם זה וכו'. בפרק קמא דנגעים בתר דקתני מראות פשוטות ומראות פתוכות תנא ארבע מראות אלו מצטרפין זה עם זה משמע דאכולהו קאי בין פשוטות בין פתוכות בין פשוטות עם פתוכות:\",1,0],[8,376,1,6,\"כל מראה צרעת עור הבשר וכו'. בריש שבועות (דף ו' ע\\\"ב) ת\\\"ר בהרת עמוקה וכן הוא אומר ומראהו עמוק מן העור כמראה חמה העמוקה מן הצל ובספרי אמרו מראה הנגע עמוק ואין ממשו עמוק ואמרו עוד שאת אין שאת אלא גבוה ומפני זה כתב הראב\\\"ד מן הצמחים העולים בגוף א\\\"א לא נאמר זה אלא בבהרת אבל בשאת מראהו גבוה מן העור שאין שאת אלא גבוה עכ\\\"ל. וכ\\\"נ דעת אונקלוס שתרגם שאת עמקא. ואפשר לומר שסובר רבינו דכיון דבהרת צריכה להיות עמוקה הוא הדין לשאת ומ\\\"ש בספרי שהיא גבוהה לאו למימרא שהיא גבוהה ממש אלא שהיא גבוהה יותר מבהרת כלומר שאינה עמוקה כמותה אבל לעולם עמוקה היא, ובזה עלה ארוכה למ\\\"ש רש\\\"י בפירוש התורה ומראיה אין עמוק מן העור לא ידעתי פירושו דוק ותשכח. כתוב בספרי רבינו לא עמוק במשיחתו וט\\\"ס הוא וצריך להגיה לא עמוק במשישתו וכן מצאתי בספר מוגה והוא ההיא דספרי שכתבתי בסמוך:\",1,0],[8,376,1,7,\"שיעור כל נגעי צרעת וכו'. ברפ\\\"ו דנגעים גופה של בהרת כגריס הקילקי מרובע מקום הגריס ט' עדשות מקום עדשה ארבע שערות נמצאו ל\\\"ו שערות ופירש שם רבינו שכאשר היה הנגע מרובע יהיה צמיחת ל\\\"ו שערות והוא כגריס הקילקי לפי שרחבו ו' באורך ו' ויהיה ג\\\"כ באורך ג' עדשים ברוחב ג' עדשים לפי שהעדשה ארכה צמיחת שתי שערות ורחבה צמיחת שתי שערות:\",1,0],[8,376,1,8,\"ומ\\\"ש נגע שהיה ברחבו כדי צמיחת חמש שערות וכו'. נלמד ממה ששנינו במשנה הנזכר גופה של בהרת כגריס הקילקי מרובע:\",1,0],[8,376,1,8,\"וכל השיעורים הל\\\"מ. בריש עירובין (דף ד'):\",2,0],[8,376,1,9,\"כ\\\"מ שנאמר בהרת וכו'. זה הוא הקדמה לכל מה שיבא:\",1,0],[8,376,1,9,\"בהרת שהיא עזה כשלג וכו' לפיכך אין משערין הכל אלא בבינוני. פ\\\"ב דנגעים וכחכמים:\",2,0],[8,376,1,10,\"שלשה סימני טומאה בצרעת עור הבשר וכו'. בפ\\\"ג דנגעים ובפ\\\"ז.\",1,0],[8,376,1,10,\"ומ\\\"ש שאין בנגעי עור הבשר הסגר יותר על ב' שבועות. משנה פ\\\"ב דערכין (ח' ע\\\"ב) והוא מבואר בתורה:\",2,0],[8,376,1,11,\"בהרת שהיתה עזה כשלג וכו'. בפרק רביעי דנגעים היתה עזה ונעשית כהה או כהה ונעשית עזה הרי היא כמות שהיתה ובלבד שלא תתמעט מארבעה מראות.\",1,0],[8,376,1,11,\"ומה שכתב רבינו אם כן מהו זה שנאמר בתורה והנה כהה הנגע וכו' וכן אם לא כהה ולא פשה וכו'. כדברי רבינו כתב הרמב\\\"ן בפירוש התורה ור\\\"ש בפרק קמא דנגעים ולאפוקי ממ\\\"ש רש\\\"י בפירוש התורה אם כהה הוכהה מראיתו הא אם עמד במראיתו ולא פשה טמא וכבר האריך בזה ה\\\"ר אליה מזרחי שם:\",2,0],[8,376,2,1,\"שיער לבן שהוא סימן טומאה בצרעת וכו'. בפ\\\"ד דנגעים ובתורת כהנים ושער מיעוט שער שתי שערות.\",1,0],[8,376,2,1,\"ומ״ש וכמה יהא אורכן וכו'. משנה פרק בא סימן (נדה דף נ״ב ע״ב) פלוגתא דתנאי ואיפסיקא הלכתא כמחמיר וסובר רבינו שהאומר כדי שיהיו ניטלות בזוג הוא המחמיר שהוא השיעור המועט.\",2,0],[8,376,2,1,\"ומ\\\"ש היתה אחת ארוכה. בפ\\\"ק דנגעים.\",3,0],[8,376,2,1,\"ומה שכתב או אחת מלמטה וכו'. בפ\\\"ד.\",4,0],[8,376,2,1,\"ומ״ש אף על פי שהלבן כל שהוא טמא. שם כמה לבנונית יהא ר' מאיר אומר כל שהוא ר' שמעון אומר כדי לקרוץ בזוג ופסק כר״מ דמחמיר משום דכיון דלא איפסיקא הלכתא בפרק מי שהוציאוהו (עירובין דף מ״ו ע״ב) בפלוגתא דר' מאיר ור' שמעון הלכה כדברי מי נקטינן כדברי המחמיר וכ״כ בעל הליכות עולם ואע״ג דתניא בתוספתא ר״מ אומר כל שהוא וחכ״א כשיעור לא חש לה רבינו לפסוק כחכמים ע״ד מאי דאמרינן בפרק החולץ (יבמות דף מ״ג) אם רבי לא שנאה רבי חייא מנא ליה:\",5,0],[8,376,2,2,\"שתי שערות לבנות וכו'. בפ\\\"ד דנגעים.\",1,0],[8,376,2,2,\"ומ\\\"ש ובין שהיו שתי שערות בתוך הבהרת וכו'. משנה רפ\\\"ד דנגעים שהפסיון מטמא חוץ לנגע משא\\\"כ בשיער לבן.\",2,0],[8,376,2,2,\"ומה שכתב היו שתי שערות בתוך הנגע וכו'. בת\\\"כ ובתוספתא דנגעים פ\\\"ב:\",3,0],[8,376,2,3,\"לובן השערות מטמא בכל מראה וכו'. ריש פרק ד' דנגעים:\",1,0],[8,376,2,4,\"אין שיער לבן סימן טומאה עד שיהיה בגוף הבהרת וכו'. בפרק קמא דנגעים תנן על שתי שערות לבנות נסמך השחין לשתיהן או לאחת מהן הקיף השחין את שתיהן או את אחת מהן או חלקן השחין ומחית השחין והמכוה ומחית המכוה והבוהק להקל וא\\\"ת הא קיימא לן ששיער לבן הוא סימן טומאה גם בשחין ומכוה וא\\\"כ דל בהרת מהכא תיפוק ליה משום שחין ומכוה שיש בהם שיער לבן ויש לומר משכחת לה כגון שהיא מכה טריה ונקרא מורד ואינה מטמאה:\",1,0],[8,376,2,5,\"ומ\\\"ש הלכו להם השחין והבוהק וכו'. שם במשנה הנזכרת:\",1,0],[8,376,2,6,\"אין שיער לבן סימן טומאה וכו'. בספ\\\"ד דנגעים:\",1,0],[8,376,2,7,\"היתה בו בהרת ובה שער לבן וכו'. בפ\\\"ה דנגעים וכחכמים:\",1,0],[8,376,2,9,\"בהרת כחצי גריס וכו'. שם ודלא כרבי עקיבא.\",1,0],[8,376,2,9,\"ומה שכתב ספק שיער לבן קדם וכו' עד הרי זה טמא. שם בסוף הפרק וכתנא קמא ואע״ג דבפרק הפועלים (בבא מציעא דף פ״ו) אמרינן דקב״ה אמר טהור לא בשמים היא ואע״ג דאמרינן מאן נוכח רבה בר נחמני ואיהו אמר טהור ויצתה נשמתו בטהרה י״ל דכיון דבשעת יציאת נשמה הוא דאמר הכי הוי בכלל לא בשמים היא ואינו כדאי להוציא מכלל שבידינו דהלכה כת״ק ועוד שבתחילת פרק ה' דנגעים סתם לן תנא הכי:\",2,0],[8,376,2,9,\"ומה שכתב ויראה לי שטומאתו בספק. הטעם משום דכיון דספק הוא אי זה מהם קדם אי אפשר לומר דטמא שאמרו הוא טמא ודאי אלא טמא מספק קאמר:\",3,0],[8,376,3,1,\"אין המחיה סימן טומאה עד שיהיה כעדשה. פשוט בפ\\\"ד דנגעים.\",1,0],[8,376,3,1,\"ומ\\\"ש מרובעת. שם בפ\\\"ק.\",2,0],[8,376,3,1,\"ומ\\\"ש וכמה הוא שיעורה וכו'. בת\\\"כ ומחית בשר חי יכול כל שהוא ת\\\"ל שער לבן ומחית מה שיער לבן מקום שתי שערות אף מחיה במקום שתי שערות ונתבאר בדברי רבינו בפירוש המשנה רפ\\\"ו דנגעים ומדברי ר\\\"ש בפ\\\"ד הלכה ב' בשם ת\\\"כ ובפ\\\"ז הלכה ב' שהמחיה מכלל הגריס שעל מה ששנינו שם בהרת כגריס ובה מחיה כעדשה כתב ובה מחיה כעדשה ובין הכל כגריס וגם רבינו כתב כן בפרק הנזכר הלכה א'.\",3,0],[8,376,3,1,\"ומ\\\"ש והוא שתהיה המחיה באמצע הבהרת וכו'. בפ\\\"ק דנגעים תנן דאין המחיה סימן טומאה אא\\\"כ היתה מבוצרת כלומר שהיא באמצע הבהרת כמו המבצר שהוא בתוך העיר ושתהיה מכונסת אבל אם היתה מן הצד או שהיתה מפוזרת אינה סימן טומאה:\",4,0],[8,376,3,2,\"המחיה מטמאה בכל מראה וכו'. ברפ\\\"ד דנגעים שהמחיה מטמאה בכל מראה:\",1,0],[8,376,3,3,\"אין המחיה סימן טומאה עד שתהיה בגופה של בהרת וכו'. בפ\\\"ק דנגעים:\",1,0],[8,376,3,4,\"המחיה סימן טומאה לעולם וכו'. בפ\\\"ד דנגעים שהמחיה מטמאה הפוכה ושלא הפוכה:\",1,0],[8,376,3,4,\"זה שנאמר בתורה והיא הפכה שיער לבן וכו'. בספרי:\",2,0],[8,376,3,5,\"בהרת כגריס מצומצם וכו'. פרק ששי:\",1,0],[8,376,3,5,\"היתה המחיה פחותה מכעדשה וכו'. ג\\\"ז שם.\",2,0],[8,376,3,5,\"ומה שכתב נתמעטה המחיה וכו'. שם וכחכמים:\",3,0],[8,376,3,5,\"וכתב הראב\\\"ד ה\\\"ז כמות שהיתה א\\\"א ואינה טהורה עכ\\\"ל ביאור דבריו דבמתניתין תנן ר\\\"מ מטמא וחכמים מטהרים ולאו למימרא שיטהרנו ויפטור אותו אלא היינו לומר דאין כאן סימן טומאה ויסגיר ולפיכך לא כתב רבינו הרי זו טהורה אלא הרי זו כמו שהיתה ואין כאן סימן טומאה כלומר ויסגיר וכוונת הראב\\\"ד לומר שיפה כיון רבינו לשנות לשון המשנה:\",4,0],[8,376,3,6,\"בהרת יתירה מכגריס וכו'. בפ\\\"ו שם.\",1,0],[8,376,3,6,\"ומ\\\"ש ולא תקרב המחיה וכו'. פשוט הוא על פי מה שנתבאר בפרק זה:\",2,0],[8,376,3,7,\"בהרת כגריס ובשר חי כעדשה וכו'. שם וכת\\\"ק.\",1,0],[8,376,3,7,\"ומ\\\"ש נתמעט הבשר החי שביניהם וכו'. שם וכר\\\"ע מחבירו:\",2,0],[8,376,3,8,\"בהרת שהיתה בראש אבר מן האיברים וכו'. ג\\\"ז שם:\",1,0],[8,376,3,8,\"ומ\\\"ש אבל ראשי דדים של איש והיבולת והדלדולים וכו'. שם וכת\\\"ק:\",2,0],[8,376,3,8,\"וכתב הראב\\\"ד מפני שהמחיה חולקת א\\\"א לא ימצא דבר זה אלא בשאין בראש האבר מקום יושב כגריס וכו'. טעמו שבא ליישב למה יחדו מחיה יותר משיער ופסיון ומשיג על רבינו שכתב מפני שהמחיה חולקת את הנגע דמה לשון חלוקה במחיה והלא הוא מחשבון הגריס וכו' וי\\\"ל לדעת רבינו שהוא מפרש שאילו היתה בהרת כגריס בראש אחד מאיברים אלו אפשר שיהיה נראה כולו כאחד אבל מתוך שהמחיה בתוכה אין העין שולט בכל הבהרת כאחד:\",3,0],[8,376,3,9,\"ומ\\\"ש וכל ראשי איברים אלו וכו'. תוספתא:\",1,0],[8,376,4,1,\"הפשיון מטמא בכל שהוא. בפרק רביעי דנגעים.\",1,0],[8,376,4,1,\"ומ\\\"ש והוא שיהיה הפשיון מאחת ממראות נגעים. בפרק ד' יש במחיה מה שאין בפסיון וכו' שהמחיה מטמאה בכל מראה משא\\\"כ בפסיון כלומר שהפסיון אינו מטמא אא\\\"כ הוא מד' מראות ובפרק קמא תנן שאם הבוהק חילק בין האום לפסיון טהור.\",2,0],[8,376,4,1,\"ומ\\\"ש ואין הפסיון סימן טומאה וכו' אבל אם פשה לתוך הנגע הרי הוא כמות שהיה וכו'. בפ\\\"ו וכרבי עקיבא:\",3,0],[8,376,4,2,\"אין הפשיון וכו'. הכי משמע בפ\\\"ו משנה ב' ובת\\\"כ יכול יהא הפשיון מטמא בתחילה ת\\\"ל אחרי הראותו יכול אם ראהו שהוא פושה והולך יזקק לו ת\\\"ל לטהרתו אינו נזקק לו אלא בשעה שרואה אותו מטומאה לטהרה והביאה ר\\\"ש בפ\\\"ק וגורס בשעה שרואה אותו אם לטומאה אם לטהרה ופי' אם לטומאה בסוף הסגר ראשון שנקרא עליו שם טומאה אם לטהרה בסוף הסגר שני או לאחר הפיטור:\",1,0],[8,376,4,3,\"אין הבהרת פושה לתוך השחין וכו'. פ\\\"ו ופרק ט'.\",1,0],[8,376,4,3,\"ומ\\\"ש ולא לתוך מחית השחין ולא לתוך מחית המכוה. הכי משמע בפירקא קמא.\",2,0],[8,376,4,3,\"ומה שכתב אבל בהרת שפשתה לתוך הבוהק הרי זו פשיון. הכי משמע שם:\",3,0],[8,376,4,4,\"השחין והמכוה וכו' עד ה\\\"ז מוחלט. שם:\",1,0],[8,376,4,5,\"בהרת כגריס וכו'. בפ\\\"ד בהרת כגריס ופשתה כחצי גריס ועוד והלך מן האום כחצי גריס ר\\\"ע מטמא וחכמים מטהרים ופירש רבינו ר\\\"ע סבר כי כאשר הגיע תוספת על אי זה פנים שיהיה הנה הוא פשיון וחכ\\\"א שהפסיון הוא שיוסיף על הנגע אשר היה תחילה וכאשר הלך מן האום כחצי גריס הנה לא נשאר נגע שלם אע\\\"פ שהנשאר מן האום עם הפסיון יותר מכגריס הנה הוא טהור וידוע דהלכה כחכמים:\",1,0],[8,376,4,5,\"היתה כגריס וכו'. בפ\\\"ד וכחכמים וטעמא כטעם מה שקדם בדין שקודם זה:\",2,0],[8,376,4,5,\"היתה בו בהרת והסגירו וכו'. בפ\\\"ד הלכה וחזרה בסוף שבוע הרי היא כמות שהיתה לאחר הפיטור תראה בתחילה ופירש ר\\\"ש הלכה וחזרה בסוף שבוע הסגירו בבהרת כגריס ובסוף השבוע הלכה לה וחזרה בו ביום או שהלכה באמצע השבוע של ימי הסגרו ובסוף השבוע חזרה הרי היא כמות שהיתה ומסגירו הסגר שני לאחר הפיטור דראה אותה הכהן בסוף שבוע שהלכה לה ופטרו אם אח\\\"כ חזרה תראה בתחילה או עמדה בו שני שבועות ופטרו ואח\\\"כ הלכה ושוב חזרה:\",3,0],[8,376,4,5,\"וכתב הראב\\\"ד והלכה הבהרת בסוף ימי הסגר א\\\"א זה המחבר פעם מפרש וכו'. נראה שגירסת רבינו במשנה היתה כמ\\\"ש והעתיק לשונה כמנהגו ושפיר משתמע לשון בסוף ימי הסגר קודם פיטורו:\",4,0],[8,376,4,5,\"נתמעטה בתוך ימי הסגר וכו'. לכאורה נראה דהיינו דתנן בפ\\\"ד כנסה ופשתה או פשתה וכנסה ר\\\"ע מטמא וחכמים מטהרים ופסק כחכמים אבל כתב הראב\\\"ד הרי זה יסגיר או יפטור א\\\"א המשנה אמרה בזה ר\\\"ע מטמא וכו'. נראה שנוסחת הראב\\\"ד ברבינו ה\\\"ז יסגיר או יפטור וכן מצאתי בספר רבינו מוגה והיינו לומר שאם הוא בשבוע ראשון יסגיר ואם הוא בסוף שבוע שני יפטור. וראיתי נוסחא בדברי רבינו שכתוב בה בסוף ימי הסגר במקום בתוך ימי הסגר ולי בתוך ימי הסגר אפשר שכולל גם לסוף ואתי שפיר כגירסת הראב\\\"ד יסגיר או יפטור וכמו שכתבתי:\",5,0],[8,376,4,5,\"ביאור דברי הראב\\\"ד ששם שנינו למטה מפיסקא זו בהרת כגריס ופשתה כחצי גריס והלך מן האום כחצי גריס רבי עקיבא אומר תראה בתחילה וחכמים מטהרים ומאחר שדעת רבי עקיבא שם תראה בתחילה א\\\"א שיטמא בזו אי בתוך ימי הסגר מיירי דמ\\\"ש דההיא נמי פשתה וכנסה הוא שמתחילה היתה כגריס ופשתה כחצי גריס והלך מן האום כחצי גריס והיינו וכנסה שחזרה כמות שהיתה ואמר תראה בתחילה ולא חשש למה שפשה כיון שחזר לכשיעור וא\\\"כ למה יחליט בזו. ומ\\\"ש כלומר מחליט נזהר שלא נפרש דמאי מטמא דאמר ר\\\"ע תראה בתחילה ולאפוקי מחכמים דמטהרים והשתא לא תיקשי ממשנה זו לזו לכך אמר דליתא דלישנא דמטמא לא משמע אלא מחליט. וליישב דברי רבינו י\\\"ל שמצאתי במשניות מוגהות כתוב על אותה משנה דר\\\"ע אומר תראה בתחילה כתוב בלשון הזה זו המשנה אינה בנוסחת הרמב\\\"ם וא\\\"כ בטלה לה קושיא מעיקרא. ועל מ\\\"ש ואולי לא כתב זאת כנגד אותה הפיסקא אלא שמועה בפני עצמה עשה ק\\\"ל שאם כדבריו כן הוא צריך לחקור אותה שמועה בפני עצמה שעשה וכי מאין הוציאה ונראה שטעמו שפיסקא זו הוציאה רבינו מדתניא בת\\\"כ גבי הסגר ראשון לא פשה שאם כנס ופשה כאילו לא כנס הנגע שאם פשה וכנס כאילו לא פשה ודכוותה דריש התם בהסגר שני וההיא מיירי ודאי בשכנסה ופשתה או פשתה וכנסה קודם ששלמו ימי ההסגר ומש\\\"ה יסגיר אם הוא בשבוע ראשון או יפטור אם הוא בסוף שבוע שני ומתניתין דכנסה ופשתה ופשתה וכנסה ר\\\"ע מטמא וחכמים מטהרים מיירי בשאחר פיטור כנסה ופשתה או פשתה וכנסה וההיא דת\\\"כ אליבא דחכמים היא ור\\\"ע פליג עלה ולית הלכתא כוותיה ויותר נראה לומר דבההיא מודה רבי עקיבא כיון שבתוך הסגרו הוא וסמך רבינו דין זה לדין הסמוך לו דמיירי בהלכה הבהרת וחזרה קודם הפיטור כדמיירי דין זה ודינא דמתני' דכנסה ופשתה וכו' דמיירי לאחר הפיטור כתבה רבינו בהרת שכנסה אחר הפיטור ופשתה וכו' ומ\\\"מ נראה שאנו מוכרחים לפרש דטמא דאר\\\"ע היינו לומר דתראה בתחילה ולאפוקי מחכמים דמטהרים דאילו להחליט אין שום טעם בפשתה וכנסה:\",6,0],[8,376,4,6,\"בהרת כגריס ופשתה וכו'. כך היא הנוסחא הנכונה בדברי רבינו והוא משנה בפרק ד' ופסק כחכמים וא\\\"ת ומאי נ\\\"מ במה שתראה בתחילה הרי שיער לבן ומחיה מטמאין בתחילה ממ\\\"נ טמא הוא ומדברי רבינו שם נלמד דנפקא מינה להיכא שהשיער והמחיה אין בהם כל התנאים הצריכין לטמא והר\\\"ש כתב דנ\\\"מ דלרבנן בעי איתויי קרבן אכל חד וחד ולר\\\"ע כנגע ראשון חשיב וכי מתסי מהאי מייתי חד קרבן:\",1,0],[8,376,4,6,\"היתה בו בהרת כגריס וכו'. ריש פרק ה':\",2,0],[8,376,4,7,\"בהרת כגריס וחוט וכו'. בפ\\\"ד:\",1,0],[8,376,4,7,\"היו שתי בהרות וכו'. ג\\\"ז שם ונ\\\"מ אם מצטרפות כגון שנולד שערה אחת בנגע זה ושערה אחת בנגע זה שאם מצטרפות הוי סימן טומאה ויחליט:\",2,0],[8,376,4,7,\"הסגירו שבוע אחד וכו'. בפרק ז' עודהו מסגירו ופוטרו ונולדו לו סימני טומאה יחליט ופירש רש\\\"י ופוטרו כלומר או פוטרו כגון בסוף שבוע שני ואפילו לאחר הפיטור אם נולדו סימני טומאה יחליט:\",3,0],[8,376,4,8,\"בהרת שטהרה מתוך וכו'. תוספתא פ\\\"ב בהרת שטהרה מתוך החלט מחיה ושיער לבן מתוך פשיון ומתוך הסגר אינה משמש את הסגור מעתה אבל עלו לו ליטמא בשיער לבן ובפשיון והביאה ר\\\"ש בפ\\\"ד וגריס אינה משמשת הסגר מעתה ופי' שטהורה מתוך החלט מחיה שרבתה הבהרת על המחיה ונתמעטה מכעדשה ופשיון לא חשיב כמ\\\"ד אין הנגע פושה לתוכו או טהרה מתוך הסגר כגון שעמד בעיניו עד סוף שבוע שני ופטרו אינה משמשת הסגר מעתה דאין מסגירין בה לעולם אבל עלו לו ליטמא בשיער לבן אם חזרו או אם חזר ופשה:\",1,0],[8,376,4,8,\"וכתב הר\\\"י קורקוס ז\\\"ל וא\\\"ת וכיון שטהרה מתוך הסגר מה יחזור להסגר וי\\\"ל דקמ\\\"ל אפילו נשתנית משלג לסיד ומסיד לשלג וכדאיתא התם בתוספתא אחרת סמוכה לזאת בהרת אחרת שנשתנית משלג וכו' הרי היא כמות שהיתה ואפשר שעיקר החידוש משום מתוך החלט הוא דסד\\\"א כיון שהנגע נשאר והסימנים הם שהלכו יסגיר בה ולכך כתב רבינו מתוך החלט אחר מתוך הסגר וקתני סיפא אבל עלו לו וכו' כלומר מוכנת היא שאם נולד בה זה סימן טומאה מחליט כמו שנתבאר אבל הסגר אין בנגע זה עוד בשום סבה בעולם ונראה שהגירסא אבל עלו לה ואפשר דעלו לו אמתוך הסגר קאי משום פשיון נקט הכי והכוונה אותם הסגרים עלו לו לענין פשיון דלא הוי כתחילה ויסגיר אלא מחליט וכן בשיער מחליט עכ\\\"ל:\",2,0],[8,376,4,9,\"בהרת שכנסה אחר הפיטור וכו'. בפ\\\"ד וכחכמים וכמו שכתבתי לעיל:\",1,0],[8,376,4,9,\"כתב הראב\\\"ד בהרת שכנסה א\\\"א זו היא הפיסקא במשנת נגעים וכו'. טעמו משום דבפ\\\"ט גבי שאלו את ר\\\"א אמרינן שמא תכנוס ותפשה משמע בהדיא שאם כנסה ואח\\\"כ פשתה לכמות שהיתה טמאה ולכך הוצרך להעמידה לזו בבהרת כגריס ורבינו שלא פירשו אין עליו השגה לו הונח שהיינו מוכרחים לפרש כדברי הראב\\\"ד לפי שהוא זכרונו לברכה בספר זה מחבר לא מפרש:\",2,0],[8,376,4,10,\"בהרת כגריס ובה מחיה וכו'. שם וכתנא קמא:\",1,0],[8,376,4,10,\"ומ\\\"ש היה השיער לבן בתוך הבהרת וכו'. גם זה שם בהרת היא ומחיתה כגריס ושיער לבן בתוך הבהרת הלכה הבהרת טמאה מפני שיער לבן הלך שיער לבן טמא מפני המחיה ר' שמעון מטהר מפני שלא הפכתו הבהרת כגריס ופסק כת\\\"ק:\",2,0],[8,376,4,11,\"בהרת ובה מחיה ופשיון וכו'. גם זה שם:\",1,0],[8,376,4,11,\"החליטו בשיער לבן וכו'. בפ\\\"ה:\",2,0],[8,376,5,1,\"מי שהיתה לו מכה בעור בשרו וכו'. ברפ\\\"ט דנגעים ואמרינן בפ\\\"ק דחולין (דף ח') דמחמת האש לאיתויי חמי האור והוא מ\\\"ש רבינו או בברזל או באבן שליבנו באש ובספרי מייתי לה מדכתיב מכוה מכוה ריבה ואיתא בפרק כיצד צולין (דף ע\\\"ב).\",1,0],[8,376,5,1,\"ומ\\\"ש בין שהיתה המכה מחמת חולי הגוף וכו'. בת\\\"כ שחין אין לי אלא שחין שעלה מאליו לקה בעץ או באבן [מנין] ת\\\"ל שחין שחין ריבה וזו היא ששנינו בפ\\\"ו ובפירקא אחריני השחין והמכוה והקדח והוא מלשון כי אש קדחה באפי ושחין פירש\\\"י לשון חמימות כמו שנה שחונה. ודע דבפ\\\"ק דחולין אמרינן שאם לקה באבן מעיקרא אינו מחמת האור והרי זה שחין ולא ידעתי למה השמיטו רבינו:\",2,0],[8,376,5,2,\"ליבן שפוד וכו'. בפ\\\"ק דחולין איבעיא להו ליבן שפוד והכה בו משום שחין נידון או משום מכוה נידון למאי נפקא מינה לכדתניא וכו' אם שחין קודם למכוה ביטל מכוה את השחין ואם מכוה קודמת לשחין ביטל שחין את המכוה והכא ה\\\"ד כגון דהוה ביה חצי גריס שחין מעיקרא וליבן שפוד והכה בו ונפיק ביה חצי גריס אחר מאי חבטא קדים ואתי הבלא ומבטל לחבטא וה\\\"ל שחין ומכוה ולא מצטרפי או דילמא הבלא קדים ואתי חבטא ומבטל להבלא וה\\\"ל שחין ושחין ומצטרף ת\\\"ש דא\\\"ר זירא אמר שמואל ליבן סכין ושחט בה שחיטתו כשירה חידודה קודם לליבונה אלמא חבטא קדים חידוד שאני ת\\\"ש ליבן שפוד והכה בו נידון משום מכות אש אלמא חבטא קדים התם נמי דברזייה מיברז. ופירש רש\\\"י וליבן שפוד והכה בו ובהכאה זו יש תורת שחין ותורת מכוה ואיבעיא לן הי קדים ואתי דליתי בתרא ולבטליה. חבטא קדים כח ההכאה קדים להרע לו לאדם והוי שחין ואתי הבל האור אחרון ומבטל ליה והו\\\"ל מכוה ולא מצטרף בהדי חצי גריס קמא דהוה ליה שחין ומכוה. חידוד שאני שמתוך שהוא חד אין הבל האור שבו חזק וחתיכתו קודם להבלו. אלמא חבטא קדים ואתי הבלא ומבטל ליה. דברזייה מברז שלא הכהו בכח אלא דקרו ואין כאן חבטא אלא הבל אבל הכהו דאיכא חבטא אימא דהא הוי בתרא ומבטל הבלא מיברז פיינ\\\"ט בלעז עכ\\\"ל. נמצא לפי זה שהבעיא היא בשהכהו בשפוד כדרך שמכה בשבט. ורבינו נראה שמפרש דכשהכהו דרך דקירה מיירי אלא דמאי דאמור דברזייה מיברז היינו שראשו של שפוד לא היה דק אלא עב כברזא של חבית ומשום הכי תניא דפשיטא לן דנידון משום מכוה דחבטא קדים ואתי הבלא ומבטל ליה ובעיין בשראש השפוד דק כדרך השפודים ואילו היה דבר שהוא חד כחידודו של סכין פשיטא לן נמי דחידוד קדים ואתי הבלא ומבטל אבל מתוך שראשו של שפוד אף על פי שהוא דק אין חידודו כחידודו של סכין מספקא לן הי קדים כנ\\\"ל ליישב הסוגיא לדעת רבינו:\",1,0],[8,376,5,2,\"לקה במי טבריא וכו'. בריש פרק ט' דנגעים:\",2,0],[8,376,5,3,\"השחין והמכוה כל זמן שהם מכות טריות וכו'. שם ובפ\\\"ו ויליף לה מקראי בת\\\"כ:\",1,0],[8,376,5,5,\"השחין והמכוה אין מצטרפין זה עם זה וכו'. גם זה שם ובת\\\"כ ובפ\\\"ק דחולין (דף ח') יליף לה מקרא:\",1,0],[8,376,5,5,\"היה בתוך כפו צרבת שחין כגריס וכו'. גם זה שם:\",2,0],[8,376,5,6,\"שחין שנעשית מכוה וכו'. ברייתא פ\\\"ק דחולין (דף ח') כתבתיה בסמוך ותוספתא דנגעים ספ\\\"ג.\",1,0],[8,376,5,6,\"ומ\\\"ש אם אין ידוע אם שחין היה. בתוספתא הביאה ר\\\"ש בפ\\\"ט הרי הם לפניך ואין ידוע אם שחין אם מכוה טהור ונראה שרבינו היה גורס טמא ובת\\\"כ תניא ובשר כי יהיה בעורו שחין או בשר כי יהיה בעורו מכות אש מלמד שאין שחין ומכוה מצטרפין זה עם זה לא שבאו ואין ידוע אם שחין הוא אם מכוה היא אלא אפי' כחצי גריס שחין וכחצי גריס מכוה אין מצטרפין. ונראה דלדעת רבינו ה\\\"פ לא שחילקן הכתוב לשתי פרשיות לומר שצריך שידע אם הוא שחין או אם היא מכוה ואם לאו אינם טמאים דכל כה\\\"ג ודאי שהם טמאים ולא חילקן הכתוב אלא לענין צירוף אפילו כחצי גריס שחין כלומר ל\\\"מ אם רוב שחין שאינו מצטרף עם מיעוט מכוה או איפכא אלא כחצי גריס מזה וכחצי גריס מזה שהם שקולים מזה כזה אינם מצטרפים:\",2,0],[8,376,5,7,\"הסגירו בבהרת שבשחין וכו'. תוספתא ספ\\\"ג פירוש נעשה עור הבשר שנתרפא השחין לגמרי ונמצא הבהרת בעור הבשר או איפכא יראה בתחילה ואותו לא עלה לו כאילו לא הוסגר:\",1,0],[8,376,5,8,\"מי שנשר כל שיער ראשו וכו'. בפ\\\"י דנגעים איזו היא קרחת אבל נשם וסך נשם פירוש נשם סם שהוא משיר השיער מכה שאינה ראויה לגדל שיער ומשמע דה\\\"ה לגבחת.\",1,0],[8,376,5,8,\"ועל מ\\\"ש בין מחמת חולי, יש לתמוה דבת\\\"כ תניא איפכא יכול אפילו נשר מחמת חולי יהא טמא ת\\\"ל קרחת וגבחת מה קרחת בידי שמים אף גבחת בידי שמים. ונראה דרבינו גריס יכול נשר מחמת חולי יהא טהור ת\\\"ל קרחת וכו' ועל כרחך צריך לגרוס כן ואידך גירסא משובשת היא דהא חולי בידי שמים הוא והיאך אפשר לומר דממעט ליה מבידי שמים.\",2,0],[8,376,5,8,\"ומ\\\"ש אע\\\"פ שראוי לגדל לאחר זמן, כ\\\"כ שם רבינו אבל ר\\\"ש כתב הקרחת והגבחת הם בראש כדמפרש ואין זה כמו נתק דנתק חוזר ומגדל שיער ומיטמא בכל מראה וקרחת וגבחת אין מגדלין עוד שיער ואין מטמאין אלא בד' מראות ואע\\\"פ שר\\\"ש הביא ברייתא דת\\\"כ דקתני מה קרחת שאינה ראויה לגדל שיער אף גבחת שאינה ראויה לגדל שיער בספרים דידן בת\\\"כ גרסינן איפכא אי מה קרחת שאינה ראויה לגדל שיער אף גבחת שאינה ראויה לגדל שיער מנין אכל נשם וסך נשם ת\\\"ל קרחת קרחת ריבה. ומ\\\"מ לדעת רבינו צ\\\"ע מה בין קרחת וגבחת לנתק וצ\\\"ל שדעתו כמ\\\"ש הרמב\\\"ן בפירוש התורה שמ\\\"ש כי יהיה בו נגע בראש או בזקן אין צריך שיהיה שום שינוי בעור הראש אלא כיון שניתק שיער כגריס בראש או בזקן ונעקר משורשו לגמרי הוא הנגע ואם נולד בו שיער צהוב דק טמא וזו היא צרעת הראש או הזקן והפרשה השנייה ואיש כי ימרט ראשו לימדה כי אין דין הנתקין אלא כאשר ימרט אמצעות הראש וישאר השיער מקיף את הנתק מכל צד אבל אם ימרט אחור הראש או פאת הפנים וינתק כל הצד ההוא אינו נידון בסימני ראש וזקן אלא בסימני עור בשר והטעם כי בטבעי בני אדם רבים שיקרח להם מיעוט השיער בפאתי הראש לאחור או לפנים ואין הנתוק בהם חולי אחר אלא הרי הוא כשאר הגוף אבל כאשר ינתק השיער באמצעות מקום השיער אינו אלא חולי שקורין אותו הלועזים שלנו טינג\\\"א ובערב אילפעפ\\\"ע ומיעט הכתוב שנקרח מפאת פניו או מאחוריו שכן דרך בני אדם להקרח ואמר הכתוב וכי יהיה בקרחת או בגבחת נגע לבן אדמדם שיטמא כשאר הגוף בפתוך ובחלק ואמר כמראה צרעת עור בשר שיהיה מוחלט במחיה או בפשיון שהיא הצרעת החלוטה בעור הבשר והזכירו רז\\\"ל שאינו מטמא בשיער לבן כמו ששנינו שהמחיה מטמא בקרחת ובגבחת מה שאין כן בשיער לבן ונדרש הוא בתורת כהנים עכ\\\"ל:\",3,0],[8,376,5,9,\"הקרחת והגבחת מטמאות בב' סימנים וכו'. גם זה שם.\",1,0],[8,376,5,9,\"ומה שכתב ויש בהם הסגר שני שבועות. בפרק שלישי.\",2,0],[8,376,5,9,\"ומה שכתב ולפי שאין בהם שיער אין השיער לבן סימן טומאה. ז\\\"ל רבינו שמשון בסוף פרק עשירי במחיה ובפשיון בתורת כהנים נפקא לן מדכתיב צרעת פורחת היא צרעת מלמד שמטמאה במחיה וכו' היא שאינה מטמאה בשיער לבן וסובר רבינו שהתורה מיעטה מהטעם שכתב:\",3,0],[8,376,5,10,\"הקרחת והגבחת אינן מצטרפות זו עם זו וכו' בפרק עשירי.\",1,0],[8,376,5,10,\"ומה שכתב ולא לשאר עור הבשר ולא בהרת עור הבשר פושה לתוכן. בפרק ששי חזר הראש והזקן ונקרחו וכו' אין מצטרפין בנגעים ואין הנגע פושה לתוכן ובתוספתא סוף פרק ג' השחין והמכוה והנתקין והקרחת והגבחת ועור אין פושין מזה לזה:\",2,0],[8,376,5,11,\"הקרחת או הגבחת או הזקן שנקרח וכו'. תוספתא פ\\\"ד.\",1,0],[8,376,5,11,\"ומ\\\"ש אלא שאין מטמאין בשיער לבן. בת\\\"כ:\",2,0],[8,376,5,11,\"הראש והזקן קודם שיצמח בהם השיער וכו' וכן הדלדולין וכו'. משנה פ\\\"ו.\",3,0],[8,376,5,11,\"ומ\\\"ש וכן זקן האשה והסריס וכו'. תוספתא פרק ד':\",4,0],[8,376,6,1,\"אלו מקומות באדם שאינן מתטמאין בבהרת וכו'. משנה פ\\\"ו.\",1,0],[8,376,6,1,\"ומ\\\"ש שנאמר בעור בשרו וכו'. בת\\\"כ. פירש ר\\\"ש הקמטים שבשאר הגוף והקמטים שבצואר ותנא סיפא לגלויי רישא דל\\\"ת דוקא שבצואר דלא מתחזו כאחריני. ודין ראש וזקן שיש בהם שיער בת\\\"כ יליף לה מקרא. והשחין והמכוה המורדין כך הגירסא הנכונה ולאפוקי מספרים שכתוב בהם והמורדין בוי\\\"ו ופי' המורדין מלשון עין שמרדה כלומר שלא נתרפאית ולא נקרם העור. ופירוש אין מצטרפים בנגעים שאפילו רוב הגריס בעור ומעט במקומות אלו אינן מצטרפין ואין הנגע פושה לתוכן שכמו שאין מטמאין משום אום אין מטמאים משום פשיון. ופי' אין מטמאין משום מחיה שכאשר היה הדבר אשר בתוך הנגע אחד מאלו לא נחשוב אותו מחיה.\",2,0],[8,376,6,1,\"ואין מעכבים את ההופך כולו לבן. פשוט הוא דהיינו לומר שההופך כולו לבן שאמרה תורה טהור הוא אם לא הפכו מקומות אלו לבן עכ\\\"ז הוא טהור כיון שהפך לבן כל שאר הגוף:\",3,0],[8,376,6,1,\"ומ\\\"ש ואודם השפתים וכו'. תוספתא פרק ב' וכתב הר\\\"י קורקוס וק\\\"ל דהא גבי הזאה וגבי טבילה חשבינן ליה כגלוי ואפשר דשאני הכא דקפדינן טובא אראיה, וראהו, לכל מראה, והנכון דממעטין משום דכתיב זימני טובא עור בשרו והכי ממעטין נמי עור כף הרגל מפני שאינו נראה וגלוי תדיר אף על גב דבכל דוכתא חשיב גלוי וה\\\"ה לאודם כי כשסוגר פיו שאינו מדבר אינו נראה:\",4,0],[8,376,6,2,\"הראש והזקן שנשר וכו'. שם:\",1,0],[8,376,6,3,\"בהרת הסמוכה לראש וכו'. תוספתא פרק שני בשם רבי יוסי בר יהודה:\",1,0],[8,376,6,3,\"וכתב הראב\\\"ד א\\\"א זו אינה עיקר רבי יוסי בר יהודה קתני לה והלא שאלו את ר\\\"א וכו'. וליישב דברי רבינו י\\\"ל דאף על גב דמתניא בשם רבי יוסי בר יהודה כיון דלא קאמר התם דאיכא דפליג עליה נקטינן כוותיה ומה שהקשה ממה ששאלו את ר\\\"א י\\\"ל דשאני הכא דגלי קרא ואמר בעור הבשר משמע שתהא מוקפת מעור הבשר. ורבינו נראה שסמך על מה ששנינו בתוספתא פ\\\"ק סתם לעולם אין הכהן רשאי לטמאו עד שיהיו עיניו בו ובעור הבשר שחוצה לו ומדסתם לן כר\\\"י בר יהודה אלמא הלכתא כוותיה או דליכא מאן דפליג עליה ומאי דמייתי הראב\\\"ד מדר\\\"א ל\\\"ק דאיכא למימר דפשיון דל\\\"פ שאני דאע\\\"ג דאינו ראוי לשאר סימנים אם ראוי לפשיון טמא ואם אינו ראוי לפשיון אע\\\"פ שראוי לשאר סימנין טהור. ומ\\\"ש ועוד שראוי לפשיון מצד אחר אינה טענה דבעינן שיהא כל חוצה לו בעור הבשר וראוי לפשיון מכל צד:\",2,0],[8,376,6,3,\"וכתב הר\\\"י קורקוס ז\\\"ל אע\\\"פ שבת\\\"כ משמע דרבנן פליגי אר\\\"י בר\\\"י דקתני התם וראה את הנגע בעור הבשר שיהא רואה כל הבשר עמו כולו כאחד ר\\\"י בר\\\"י אומר מה ת\\\"ל בעור הבשר שיהא כל חוצה לו עור הבשר וראוי לפשיון פרט לנגע שהוא סמוך לראש וכו' משמע דת\\\"ק דמפיק לקרא לדרשא אחריתי פליג אדרבי יוסי בר\\\"י וכיון דקי\\\"ל כת\\\"ק כמו שיתבאר בפ\\\"ט א\\\"כ אידחיא לה לדרבי יוסי הא ל\\\"ק דאפשר דת\\\"ק תרתי ש\\\"מ כי כיון שלמד שיהא רואה חוצה לו עמו ממילא שכל חוצה לו הוי עור הבשר והוא הראוי לפשיון א\\\"נ דכיון דכתיב בעור הבשר בבי\\\"ת משמע דה\\\"ק את הנגע אשר הוא בעור הבשר אז יראה אותו ומדכתיב כן גבי וראה משמע שצריך לראות הכל דאי לא לכתוב כן גבי כי תהיה והיינו דבתוספתא שנו שתי הדרשות אחת בפ\\\"א והאחת בפ\\\"ב משמע דלא פליגי דאי פליגי גבי הדדי איבעי למתנינהו. גם ר\\\"ש כתב ההיא דרבי יוסי בפ\\\"ט ולא כתב דפליגא אמתני' דשאלו את רבי אליעזר נראה שדעתו כדעת רבינו עכ\\\"ל:\",3,0],[8,376,6,4,\"אלו בהרות וכו'. ריש פ\\\"ז.\",1,0],[8,376,6,4,\"ומ\\\"ש וכן אם היתה הבהרת בראש או בזקן וכו'. שם וכחכמים.\",2,0],[8,376,6,4,\"ומ\\\"ש נשתנו מראיהן וכו'. שם וכרבי עקיבא:\",3,0],[8,376,6,5,\"כל ספק נגעים וכו'. האחד בסוף פ\\\"ג מהלכות אלו. והב' בפ\\\"ד מהלכות אלו היתה בו בהרת כגריס והסגירו ובסוף שבוע הרי היא כסלע וכו'. שם (במשנה בראש פ\\\"ה).\",1,0],[8,376,6,5,\"ומ\\\"ש טהור עד שלא נזקק לטומאה אבל משנזקק לטומאה ספיקו טמא וכו'. במשנה פרק ה' ובתורת כהנים יליף להו מקראי:\",2,0],[8,376,6,6,\"ומ\\\"ש וכן מי שהיתה בו בהרת ובה שיער לבן וכו'. תוספתא פ\\\"ב.\",1,0],[8,376,6,6,\"ומ\\\"ש אע\\\"פ שהלך שיער אחד מהם וכו'. שם נשרו בו שתים טמא ושלש טהור:\",2,0],[8,376,6,7,\"מי שבא אצל כהן וכו'. משנה פרק שביעי:\",1,0],[8,376,7,1,\"מי שהיתה בו בהרת והוחלט וכו'. רפ\\\"ח הפורח מן הטמא טהור וכו' מן הטהור טמא.\",1,0],[8,376,7,1,\"ומ\\\"ש רבינו שאם נהפך מתוך הסגר טהור. כתב רבינו שם דהכי איתא בספרא מפני שהמוסגר טמא יאמר לו.\",2,0],[8,376,7,1,\"ומ\\\"ש ה\\\"ז טמא מוחלט:\",3,0],[8,376,7,2,\"הבא בתחילה והוא כולו הפך לבן וכו'. בפ\\\"ח הבא כולו לבן יסגיר נולד לו שיער לבן יחליט. ומשמע דה\\\"ה אם נולדה לו מחיה יחליט וכן פיר\\\"ש אלא חדא מינייהו נקט והכי איתא בת\\\"כ.\",1,0],[8,376,7,2,\"ומ\\\"ש החליטו בשיער לבן וכו'. שם ויש כאן חסרון בספרי רבינו מט\\\"ס אצל והשחירו שתיהן או אחת מהם צריך לכתוב הקצירו שתיהן או אחת מהן.\",2,0],[8,376,7,2,\"ומ\\\"ש מפני שבא כולו לבן בתחילה: אחר שפרחה הצרעת בכולו כאחת וכו'. שם אם בכולו פרחה כאחת מתוך הטהרה טמא מתוך הטומאה טהור. ותנן תו התם בהרת ובה פשיון פרחה בכולו טהור ובת\\\"כ אין לי אלא בזמן שפרחה בכולו כאחת פורחת וחוזרת מנין ת\\\"ל פרוח תפרח:\",3,0],[8,376,7,2,\"אחד שהיה כולו מראה אחד וכו'. בפרק קמא:\",4,0],[8,376,7,3,\"היתה בו בהרת כגריס וכו'. בפ\\\"ח. וא\\\"ת כשהלכה המחיה ואח\\\"כ פרחה בכולו הרי פרחה מתוך פיטור וה\\\"ל להיות טמא. וי\\\"ל דהב\\\"ע בשהלכה המחיה וקודם שהראהו לכהן פרחה בכולו.\",1,0],[8,376,7,3,\"ומ\\\"ש ואפילו נולד לו שיער לבן. שם וכחכמים וטעמם מפורש בתוספתא.\",2,0],[8,376,7,3,\"ומ\\\"ש נולדה לו מחיה טמא. שם.\",3,0],[8,376,7,3,\"ומ\\\"ש והוא שתהיה כעדשה וכו'. בת\\\"כ פלוגתא ופסק כרבי יוסי לגבי ר\\\"מ:\",4,0],[8,376,7,3,\"היתה בו בהרת ובה שיער לבן וכו'. ג\\\"ז שם:\",5,0],[8,376,7,3,\"החליטו בפשיון וכו'. שם בהרת ובה פשיון פרחה בכולו טהור וכולן שחזרו בהם ראשי איברים הרי אלו טמאים:\",6,0],[8,376,7,4,\"אף ראשי איברים שאינם מטמאים וכו'. ברפ\\\"ח הפורח מן הטמא טהור חזרו בו ראשי איברים טמא עד שתתמעט בהרתו מכגריס:\",1,0],[8,376,7,4,\"נהפך כולו למראה צרעת וכו'. משנה שם פרחה בכולו אבל לא בבהק טמא חזרו בו ראשי איברים כמין בוהק טהור חזרו בו ראשי איברים פחות מכעדשה ר\\\"מ מטמא וחכ\\\"א בוהק פחות מכעדשה סימן טומאה בתחילה ואינו סימן טומאה בסוף וידוע דהלכה כחכמים ופי' שם רבינו אמר ית' כאשר יתלבן כולו והנה כסתה הצרעת ולזה יצטרך שיהיה למראה הלובן אשר יכלול כל גופו צרעת לא בוהק וכאשר כל גופו אחד מד' מראות או כולן הנה הוא טהור אולם וכו' אם כללו הלבן וקצת זה הלובן צרעת וקצתו בוהק הנה הוא טמא עד שישוב זה הבוהק לאחת מד' מראות ואם כללהו הצרעת יהיה טהור כמו שאמרנו עוד נתגלה ממנו ראשי איברים אם לא חשוב בשר חי אבל יחסר הלובן ממנו עד שישוב בוהק הנה הוא טהור כמו שהיה לאומרו וביום הראות בו בשר חי יטמא לא מקום לבן ואמר ית' או כי ישוב הבשר החי ונהפך ללבן ולא אמר ונהפך לצרעת כמו שאמר תחילה וכסתה הצרעת הנה יתבאר מכל זה שבעת פריחת הצרעת לא יטהר ונאמר בו כולו הפך לבן עד שיחזור מקום הבהק צרעת ואצל הראות [בו] בשר חי אחר זה לא יטמא בו עד שיחזור ממנו הלובן לגמרי [שאפילו בוהק לא ישאר בזה] הבשר החי חזרו בו ראשי איברים פחות מכעדשה ר\\\"ל כי כאשר היה בשר חי כעדשה ופחות מכעדשה מזה העדשה בהק וכו' אומרים חכמים שבעת פרחה הצרעת בגופו כאשר כללהו כולו זולת פחות מכעדשה בשר חי וישלם שלימות השיעור כעדשה בהק הנה הוא נשאר בטומאתו ונאמר שכעדשה בכללה בשר חי יחשב לאמרו והנה כסתה הצרעת וזה בוהק כמו שקדם אמנם כאשר כללה הצרעת [בכולו] וטהר נתגלה ממנו בשר חי כעדשה וכו' קצת זאת העדשה [בהק] הנה אינו סימן טומאה ולא נחשוב אותה כולה בשר חי עד שיהא בשר חי זולת הבהק כעדשה עכ\\\"ל:\",2,0],[8,376,7,4,\"וכתב הראב\\\"ד חזר בו כעדשה מקצתה א\\\"א אומר אני ספרו הטעהו וכו'. ואיני מבין דבריו שאם מה ששנו חכמים סימן טומאה בתחילה ואינו סימן בסוף לא קאי אלא לבהק למה שנו פחות מכעדשה עם הבהק ועוד שלא הוצרכו חכמים לדבר אלא בחזרו בו ראשי איברים פחות מכעדשה לחלוק עם רבי מאיר דאילו בבהק כבר נתבאר משפטו ברישא שהוא סימן טומאה בתחילה ואינו סימן טומאה בסוף וא\\\"כ ע\\\"כ לומר דסימן טומאה בתחילה ואינו סימן טומאה בסוף קאי אפחות מכעדשה ואם כדברי הראב\\\"ד דגריס ופחות מכעדשה היאך אפשר לומר דפחות מכעדשה סימן טומאה בתחילה הרי בפ\\\"ח במתני' דכל הראוי לטמא בנגע הבהרת מעכב את הפריחה משמע בהדיא דפחות מכעדשה אינו סימן טומאה בתחילה ולשיטת רבינו אפי' נגרוס בהק ופחות מכעדשה כדגרס הראב\\\"ד א\\\"ש דה\\\"ק שיש שם בוהק ופחות מכעדשה בשר חי כלומר שהבהק משלימו לכעדשה:\",3,0],[8,376,7,5,\"כל טמא שפרחה הצרעת בכולו וכו'. שם נתכסו טהור נתגלו טמא אפילו מאה פעמים ובתורת כהנים יליף לה מקרא:\",1,0],[8,376,7,5,\"התחיל הבשר החי להתגלות. שם בריש פרק הפורח מן הטמא טהור חזרו בו ראשי איברים טמא עד שתתמעט בהרתן מכגריס:\",2,0],[8,376,7,6,\"כל הראוי ליטמא בנגע הבהרת וכו'. שם כל הראוי לטמא בנגע הבהרת מעכב את הפריחה וכל שאינו ראוי לטמא בנגע הבהרת אינו מעכב את הפריחה כיצד פרחה בכולו אבל לא בראש ובזקן ובשחין ובמכוה ובקדח המורדין חזר הראש והזקן ונקרחו השחין והמכוה והקדח ונעשו צרבת טהורים פרחה בכולו אבל לא בכחצי עדשה הסמוך לראש ולזקן ולשחין ולמכוה ולקדח חזר הראש והזקן ונקרחו השחין והמכוה והקדח ונעשו צרבת אע\\\"פ שנעשה מקום המחיה בהרת טמא עד שתפרח בכולו ופירש רבינו שמשון כל הראוי לטמא בנגע הבהרת כגון עור הבשר מעכב את הפריחה אינו טהור עד שתפרח עליהם וכל שאינו ראוי לטמא בנגע הבהרת כגון ראש וזקן וכל הני דחשיב בהדייהו אין מעכבים את הפריחה שאע\\\"פ שלא פרח הנגע עליהם כמו שפרח בשאר הגוף טהור ונעשו צרבת טהורים אע\\\"ג דעכשיו נקרחו הראש והזקן ראויים לטמא בנגע בהרת וכן שחין ומכוה וקדח המורדין שנעשו צרבת כשאר עור בשר כיון דבשעת פריחה לא היו ראויים לא מעכב וטהור אע\\\"פ שנעשה מקום המחיה בהרת טמא דפריחה קמייתא לאו פריחה היא כיון דאשתייר מעור הבשר חצי עדשה סמוך לראש פריחה דהשתא שנתכסית המחיה של חצי עדשה נמי לא חשיב כיון דכבר נקרחו ונעשו צרבת דהרי הן בעור הבשר ולא מהני עד דפרח נמי עלייהו עכ\\\"ל. ודברי רבינו תמוהים שכתב בחזר הראש והזקן ונקרחו וכו' טמא ויש לתמוה על הראב\\\"ד שלא השיגו בזה ונראה שרבינו גורס פרחה בכולו אבל לא בראש ובזקן ובשחין ובמכוה ובקדח המורדין או בכחצי עדשה הסמוך להם הרי זה טהור חזר הראש והזקן ונקרחו השחין והמכוה והקדח ונעשו צרבת טמא:\",1,0],[8,376,7,6,\"היו בו שתי בהרות וכו'. שם שתי בהרות אחת טמאה ואחת טהורה פרחה מזו לזו ואח\\\"כ פרחה בכולו טהור פירוש אחת טמאה מוחלטת בשיער לבן או במחיה או בפשיון ואחת טהורה בסוף שבוע שני או לאחר הפיטור ופרחה מזו לזו אפילו מטהורה לטמאה ואח\\\"כ בכולו משום דטהורה נעשת טמאה כשפרח ממנה לטמאה דהרי פשתה וכי פרחה אחר כך בכולו הו\\\"ל פורח מן הטמא וטהור ורבינו נתן טעם אחר לשבח דכיון שהיה מוחלט כבר ומן הטומאה פרחה בכולו כי פרחה ברישא מטהורה לטמאה מאי הוי.\",2,0],[8,376,7,6,\"ומ\\\"ש ולא עוד אלא אפילו היו אחת בשפתו העליונה וכו'. שם בשפתו העליונה ובשפתו התחתונה בשתי אצבעות בשני ריסי עיניו אע\\\"פ שמדובקין זה לזה והן נראין כאחת טהור ופירש ר\\\"ש בשפתו העליונה חצי גריס בהרת וכן בשפתו התחתונה וכשסגר פיו נראית בהרת כגריס וכן בשתי אצבעות או שני ריסי עיניו כשמדבקן נראית כגריס שלם. ופירש רבינו שם אע\\\"פ שמדובקים זה לזה והן נראין כאחד טהור הענין בזה המאמר כי כאשר פרחה הצרעת בכל גופו וכללה שני איברים מתדבקים הנה התדבקותם לא יועיל אלא משירבה הלובן יכלול אותו יחד כמו שיכללהו האבר האחד ואם היו שתי אצבעות דרך משל כאשר יתפרקו יראה מה שביניהם בשר חי וכאשר יחוברו ויראו כאחד יראה הלובן כולל להם הנה הוא טהור וזהו ענין אע\\\"פ שמדובקים זה לזה ר\\\"ל אע\\\"פ שלא יראה כולו לבן אלא אצל חיבורם קצת לקצת הנה הוא טהור עכ\\\"ל:\",3,0],[8,376,7,6,\"וכתב הראב\\\"ד ולא עוד אלא אפילו היו וכו'. א\\\"א איני יודע מאי אפילו עכ\\\"ל. טעמו דלא שייך לומר ולא עוד אלא אפילו אלא כששני הדברים הם מענין אחד אבל לא כשכל אחד ענין לעצמו והכא רישא הוי ענין אחר לאשמועינן דאע\\\"ג דברישא פרחה מן הטהורה טהור וסיפא אשמעינן שאף ע\\\"פ שאין בכל אחת כגריס מאחר שע\\\"י דיבוקם נראה כגריס הוי טמא וכשפרח ממנה הוי פורח מן הטמא וטהור וכיון שהם שני עניינים לא יצדק בהם לשון ולא עוד ורבינו כפי פירושו שכתבתי דסיפא אשמעינן שאע\\\"פ שאינו נראה כולו לבן אלא בשעת חיבורן זה לזה חשיב הפך כולו לבן והשתא הוו שני הדברים מענין אחד ושפיר דמי למיתני ולא עוד:\",4,0],[8,376,7,7,\"יש מראה נגעו לכהן ונשכר וכו'. בסוף פרק ח':\",1,0],[8,376,8,1,\"נגעי הראש והזקן הוא שיפול השיער וכו'. כתב הראב\\\"ד א\\\"א מהתוספתא נראה וכו'. ופשט דברי רבינו כת\\\"כ שהוא יותר סמכא מהתוספתא וכך נראה מדבריו עוד בסוף הלכות אלו שכתב הצרעת הוא שם האמור בשותפות וכו' ונפילת קצת שיער הראש או הזקן קרוי צרעת ולפי זה קרחת וגבחת ונתק אחד הוא אלא כשיש בו בהרת נידון כדין הנזכר שם וכשאין בו בהרת נידון בשיער צהוב דק ופשיון:\",1,0],[8,376,8,1,\"ואין נתק פחות מכגריס המרובע. בתוספתא פ\\\"ד ובת\\\"כ.\",2,0],[8,376,8,1,\"ומ\\\"ש ולא נאמר עמוק בנתקים וכו'. בת\\\"כ:\",3,0],[8,376,8,1,\"והאשה והסריס שהעלה זקנם וכו'. תוספתא פ\\\"ד זקן האשה וזקן הסריס וכו' משהעלו שיער הרי הם כזקן לכל דבר ואיתא בפ\\\"ק דקידושין ברייתא וגמרא:\",4,0],[8,376,8,2,\"הנתקים מטמאין בב' סימנין וכו'. משנה בפ\\\"י.\",1,0],[8,376,8,2,\"ומה שכתב ששיער צהוב האמור בתורה הם שתי שערות. בת\\\"כ.\",2,0],[8,376,8,2,\"ומה שכתב ואין שם בנתק שיער שחור כלל יחליט. כלומר שאם היה שם שיער שחור לא יחליט כמו שיתבאר.\",3,0],[8,376,8,2,\"ומ\\\"ש לא היה בו שיער לא שחור ולא צהוב יסגיר שבוע אחד. מפורש בתורה וכי יראה הכהן את נגע הנתק וכו' ושער שחור אין בו והסגיר הכהן את נגע הנתק שבעת ימים.\",4,0],[8,376,8,2,\"ומ\\\"ש ובשביעי רואהו אם נולד בו שער צהוב דק או שפשה הנתק יחליט. ג\\\"ז מפורש בתורה וראה הכהן את הנגע ביום השביעי והנה לא פשה הנתק ולא היה בו שיער צהוב וכו' והתגלח ותניא בת\\\"כ מנין לשיער הצהוב שיטמא שלא בפסיון והפסיון שיטמא שלא בשיער צהוב ת\\\"ל לא יבקר לשיער הצהוב טמא הוא:\",5,0],[8,376,8,2,\"ומ\\\"ש נולדו בו שתי שערות יפטור אותו. מפורש בתורה ושער שחור צמח בו נרפא הנתק טהור הוא ונתבאר בת\\\"כ דשיער היינו שתי שערות.\",6,0],[8,376,8,2,\"ומ\\\"ש לא פשה ולא נולד בו שיער צהוב ולא שיער שחור יגלח סביבות הנתק וכו'. מפורש בתורה והתגלח ואת הנתק לא יגלח ושנינו בת\\\"כ וכי מה יש בנתק לגלח אלא מגלח חוצה לו ומניח שתי שערות סמוך לנתק כדי שיהא ניכר כשיפשה וכן תרגם אונקלוס וכך שנינו במשנה פ\\\"י:\",7,0],[8,376,8,3,\"כיצד מגלחין את הנתק וכו'. בפ\\\"י.\",1,0],[8,376,8,3,\"ומ\\\"ש ותגלחתו כשירה בכל אדם וכו'. בתורת כהנים והתגלח בכל אדם לפי שמצינו שתגלחת האחרונה בכהן ת\\\"ל והתגלח בכל אדם והתגלח בכל דבר לפי שמצינו שתגלחת אחרונה בתער תלמוד לומר והתגלח בכל דבר והתגלח אפילו נזיר לפי שנאמר תער לא יעבור על ראשו יכול אפילו מנוגע ת\\\"ל והתגלח אע\\\"פ שהוא נזיר:\",2,0],[8,376,8,3,\"הסגירו ולא גילחו וכו'. בתוספתא [פרק רביעי] דנגעים:\",3,0],[8,376,8,4,\"שיער צהוב האמור בתורה וכו'. בספרי.\",1,0],[8,376,8,4,\"ומ\\\"ש וזה שנאמר דק הוא שיהיה קצר וכו'. ברפ\\\"י וכר\\\"ע וכמה שיעור קצר זה כתב ר\\\"ש:\",2,0],[8,376,8,5,\"שתי שערות הצהובות הדקות סימן טומאה בין שהיו זו וכו'. בפ\\\"י שיער צהוב דק מטמא במכונס ובמפוזר מבוצר ושלא מבוצר הפוך ושלא הפוך דברי רבי יהודה ר\\\"ש אומר אינו מטמא אלא הפוך פי' הפוך שקדם הנתק לשיער צהוב שלא הפוך שהשיער צהוב קדם לנתק. וידוע דהלכה כר' יהודה לגבי ר\\\"ש.\",1,0],[8,376,8,5,\"ומ\\\"ש והוא שיהיו ניטלות בזוג. בפ\\\"ו דנדה (דף נ\\\"ב ע\\\"ב) איפליגו תנאי בשיעור שתי שערות האמורות בכל מקום ואמרינן בגמרא דהלכה כדברי כולם להחמיר ושיעור כדי שיהיו ניטלות בזוג הוי שיעור מועט שבכולן והוי להחמיר וכבר כתבתי כן בפרק ב' מהלכות אלו גבי שיער לבן:\",2,0],[8,376,8,6,\"השיער השחור וכו'. בתורת כהנים:\",1,0],[8,376,8,6,\"ומה שכתב ואינן מצילות עד שיהיה אורכן כדי לכוף ראשן לעיקרן. על פי מה שנתבאר שהלכה כדברי כולם להחמיר ושיער שחור שהוא בא לטהר צריך שיעור הגדול שהוא כדי לכוף ראשן לעיקרן שזה הוא להחמיר ומה שיש לדקדק על דברי רבינו בפ\\\"א מהלכות פרה כתבתי שם.\",2,0],[8,376,8,6,\"ומ\\\"ש בין שהיו זו בצד זו בין שהיו מפוזרות וכו' עד רחוק מן הקמה שתי שערות. בפ\\\"י הצומח מציל מיד השיער צהוב דק ומיד הפסיון מכונס ומפוזר מבוצר ושלא מבוצר והמשואר מציל מיד שיער צהוב [דק] ומיד פסיון מכונס [ומפוזר] ומבוצר ואינו מציל מן הצד עד שיהא רחוק מן הקמה מקום שתי שערות פי' נתק כגריס שהוחלט בשער צהוב או בפסיון וצמחו בנתק שתי שערות שחורות מצילות. בין מכונס דשתיהן במקום אחד בין מפוזר זה ברוח זה וזה ברוח זה. מבוצר באמצע הנתק. ושלא מבוצר דקיימי בנתק מן הצד. והמשואר שקדמו שתי שערות שחורות הללו לנתק דכשניתק שיער ראשו או זקנו כגריס נשארו מהם שתים בתוך הנתק ואם הם מבוצרות באמצע הנתק מצילות אבל אם עומדות מן הצד אינן מצילות אא\\\"כ רחוקות מסוף הנתק המוקף שערות כשיעור מקום שתי שערות ולשערות המקיפות את הנתק קמה קרי להו וכששערות הללו רחוקות מקום שתי שערות מן הקמה היינו נמי מבוצר:\",3,0],[8,376,8,7,\"שתי שערות שצמחו וכו'. שם וכתב הר\\\"י קורקוס ז\\\"ל דלהציל מיד הפסיון קאמר דסד\\\"א יצטרף עם השחור להציל כיון דבפני עצמו לא הוי סימן טומאה:\",1,0],[8,376,8,10,\"שני נתקים זה בצד זה. גם זה בפ\\\"י שני נתקים זה בצד זה ושטה של שיער מפסקת ביניהם נפרץ ממקום אחד טמא משני מקומות טהור כמה תהיה הפרצה מקום שתי שערות נפרץ ממקום אחד כגריס טמא ומפרש רבינו דשיטה של שיער מפסקת ביניהם דקתני היינו שיטה של שיער שחור ומפרש דטמא דקתני רישא היינו לומר דאינו טהור על ידי השיער שחור שהרי הוא כמות שהיה דאכתי לאו מבוצרות הן. ומה ששנינו נפרץ במקום אחד כגריס טמא היינו אפילו נפרץ משני מקומות כמ\\\"ש הראב\\\"ד וכמו שמבואר הטעם בדברי רבינו:\",1,0],[8,376,8,10,\"ומ\\\"ש רבינו נתק שהשיער השחור מקיפו. גם זה שם שני נתקים זה לפנים מזה ושיטה של שיער מפסקת ביניהם נפרץ ממקום א' טמא משני מקומות טהור כמה תהא הפרצה מקום שתי שערות נפרץ ממקום אחד כגריס טהור ופירושה מבואר בדברי רבינו:\",2,0],[8,376,8,11,\"נתק שהיה חוט יוצא ממנו וכו'. תוספתא בפ\\\"ד וה\\\"פ שאם יש בחוט רוחב ב' שערות נתק זוקק לטמא שאר נתקים בשיער צהוב ובפסיון שאם השיער צהוב בחוט הוי כאילו הוא בנתקים האחרים וכן אם פשה החוט הוי כאילו פשו השתי נתקים.\",1,0],[8,376,8,11,\"ומ\\\"ש ומצילים בצומח בו, כלומר שאם צמח שיער שחור בחוט הוי כצומח בשתי הנתקים ומציל מיד שיער צהוב או פסיון שבנתקים אבל במשוייר אינו מציל עד שיהא בחוט כגריס דמשוייר אינו מציל אלא מבוצר כמו שנתבאר בפרק זה ואי אפשר להיות מבוצר אא\\\"כ יש בו כגריס כמו שנתבאר גבי בהרת:\",2,0],[8,376,8,12,\"מי שהיה בראשו נתק וכו'. בפ\\\"י מי שהיה בו נתק כגריס וניתק כל ראשו טהור ותניא בתורת כהנים מנין שאם היה בו נתק כגריס וניתק כל ראשו טהור ת\\\"ל ואיש כי ימרט ראשו וכו' יכול הזקן מעכבו ודין הוא וכו' ת\\\"ל ראשו טהור הוא אין הזקן מעכב או אינו אלא ניתק ראשו טהור ניתק זקנו לא יהיה טהור ת\\\"ל ואיש להביא את הזקן ומשמע לרבינו שאין דרשה זו מבוררת כ\\\"כ ולפיכך כתב ואע\\\"פ שאין זה מפורש בתורה שבכתב וכו':\",1,0],[8,376,8,12,\"ומה שכתב או אחר הפיטור. תוספתא הביאה ר\\\"ש בפ\\\"י ניתק ראשו וזקנו כולו כאחד בין מתוך החלט בין מתוך הסגר בין מתוך הפיטור טהור משום פריחה. ופי' ר\\\"ש ניתק ראשו וזקנו כלומר או זקנו. בין מתוך הפיטור טהור משום פריחה כלומר אם פטרו ואח\\\"כ פרחה בכולו טהור עכ\\\"ל. ויש לשאול מ\\\"ש מבהרת דפורח בכולו אחר הפיטור טמא. וי\\\"ל דשאני התם דקרא מוכח שאין הפריחה מטהרת אלא פורח מן הטמא ואילו הכא כתיב ואיש כי ימרט ראשו וגו' משמע בכל גוונא ואין טעם להחמיר כל אחר הפטור כיון דליכא לאוכוחי הכי מקרא ולא מטמאינן אלא בבא כן בתחלה דלא מיקרי פריחה ואין להקל בכולו יותר מבקצתו ומדמינן ליה לנגע עכ\\\"ל הר\\\"י קורקוס ז\\\"ל:\",2,0],[8,376,8,13,\"הבא בתחלה וכל ראשו נתוק וכו'. תוספתא פ\\\"ד והביאה ר\\\"ש בפ\\\"י הבא כולו נתק יסגיר בסוף שבוע א' ובסוף שבוע ב' נולד לו שיער שחור מן הצד טהור חזר וניתק טמא משום פשיון ופירש ר\\\"ש הבא כולו וכו' אין פריחה בתחלה טהורה בנתק כמו שאינה טהורה בבא כולו לבן אלא שמציל וחשיב כשחור משוייר. טמא משום פסיון ומש\\\"ה נקט מן הצד דבאמצע אין טמא משום פשיון דאין הנתק פושה לתוכו כדאמרן גבי בהרת אבל לענין הצלה מציל בין באמצע בין מן הצד עכ\\\"ל:\",1,0],[8,376,8,13,\"כתב הראב\\\"ד נולד לו שיער שחור טהור א\\\"א ואפילו הלך השחור וכו'. וי\\\"ל שרבינו סמך על מ\\\"ש למעלה נתק שהוחלט וכו' ונולד בו שיער שחור וטיהר אע\\\"פ שהלך השיער השחור ה\\\"ז טהור שנאמר נרפא הנתק שסימני טומאה עומדים:\",2,0],[8,376,8,13,\"וכתב הר\\\"י קורקוס ז\\\"ל ואיכא למידק מ\\\"ט דהא בשחור מטמא משום פסיון קרי כאן נרפא הנתק טהור הוא ומה לי צמח אחר החלט או אחר הסגר כי היכי דהתם לא חשבינן ניתוק השיער השחור לפשיון עד שיפשה פשיון אחר גם בזה לא יחשב לפשיון ונראה דכשהיה שם סימן טומאה ובא השחור וביטלו וטיהר אז אנו אומרים נרפא טהור אבל כשטיהר מתוך הסגר לא קרינן ביה נרפא דגם בלא שיער שחור היה אפשר להיות טהור אם עמד בין שני הסגרים הילכך כל שנולד בסוף ההסגר שיער שחור חשבינן כאילו תחלתו כן היה וכשניתק הרי פשה הנתק ועדיין צריך בירור עכ\\\"ל:\",3,0],[8,376,8,13,\"הבא כולו נתוק וכו' הלך השיער שחור טמא משום פשיון. תוספתא כתבתיה בסמוך:\",4,0],[8,376,8,14,\"הראש והזקן אין מעכבין זה את זה. משנה פ\\\"י ופסק כר' יהודה לגבי ר\\\"ש.\",1,0],[8,376,8,14,\"ומ\\\"ש ואין מצטרפין זה עם זה ואין פושין מזה לזה. שם.\",2,0],[8,376,8,14,\"ומ\\\"ש ואי זהו זקן וכו'. שם.\",3,0],[8,376,8,14,\"ומה שכתב מותח את החוט וכו'. בתוספתא [פ' רביעי]:\",4,0],[8,376,9,1,\"הכל מתטמאין בנגעים אפילו קטן בן יומו. משנה פ' יוצא דופן (נדה דף מ״ג ע״ב) ויליף לה בגמרא שם (דף מ״ד) ובריש ערכין (דף ג') מדכתיב אדם כי יהיה בעור בשרו אדם כל דהו.\",1,0],[8,376,9,1,\"ומ\\\"ש והעבדים. מדתנן רפ\\\"ג הכל מטמאים בנגעים חוץ מן העכו\\\"ם וגר תושב משמע דוקא הני אבל עבדים שישנן במצות שהאשה חייבת מטמאים.\",2,0],[8,376,9,1,\"ומ\\\"ש והכל כשרים לראות את הנגעים. שם ובריש ערכין קאמר דהיינו לאתויי שאינו בקי בהן ובשמותיהן והא אמר מר אינו בקי בהן ובשמותיהן אינו רואה את הנגעים ל\\\"ק הא דמסברו ליה וסבר הא דמסברו ליה ולא סבר וכתב רבינו בפ\\\"א וז\\\"ל שכל שאינו מכיר המראות ושמותיהם כשמלמדים אותו ומודיעים אותו לא יראה הנגע עד שיבין ויכיר ויאמר זו היא הבהרת זו היא ספחת וכו' ומשמע לכאורה דההיא בסומך על עצמו אבל בפרק זה מיירי כשאינו סומך על עצמו כמבואר בדבריו. אבל איכא למידק על מה שאמרו דמסברו ליה וכו' במאי עסקינן אי בשאינו סומך על עצמו מאי איריא דמסברו ליה וסבר אפילו כהן שוטה נמי וכמ\\\"ש רבינו בסמוך והרא\\\"ש הרגיש בזה וכתב ברפ\\\"ג דנגעים ההוא שוטה לאו דוקא דצריך שיהיה פקח קצת דמסברו ליה וסבר אלא דקרי לגבי חכם שבישראל שוטה ונ\\\"ל לפרש כן דברי רבינו שמ\\\"ש בפ\\\"א בשאינו סומך על עצמו נמי היא ולישניה דייק שכתב שם עד שיבין ויכיר ויאמר זו היא הבהרת וזו היא ספחת וכו' ואי בסומך על עצמו לא סגי בהכי עד שיהיה בקי בנגעי אדם כולם ובנגעי בגדים ובנגעי בתים וכמ\\\"ש בפרק זה הילכך ודאי בשאינו סומך על עצמו היא ולא נמנע מלכתוב בפרק זה דאפילו שוטה אומר לו החכם והוא מחליט וכו' מפני שסמך על מ\\\"ש שם:\",3,0],[8,376,9,1,\"וכל הנגעים אדם רואה אותם וכו'. בסוף פרק שני דנגעים וכתנא קמא:\",4,0],[8,376,9,2,\"אע\\\"פ שהכל כשירים וכו'. שם [בפרק ג'].\",1,0],[8,376,9,2,\"ומה שכתב ואפילו היה הכהן קטן או שוטה. בתורת כהנים מרבה אפילו שוטה וכבר כתבתי בזה בסמוך:\",2,0],[8,376,9,2,\"במה דברים אמורים כשהיה הכהן סומך על דברי החכם. נתבאר בסמוך.\",3,0],[8,376,9,2,\"ומה שכתב ויהיה בקי בכל הנגעים ובשמותיהן וכו'. בתורת כהנים ובתוספתא פרק קמא:\",4,0],[8,376,9,3,\"כהן שטימא את הטהור וכו'. תוספתא פ\\\"ק דנגעים ובתורת כהנים סוף פרשת תזריע.\",1,0],[8,376,9,3,\"ומ\\\"ש ומצורע שנרפא בין מתוך הסגר וכו'. תוספתא פ\\\"ק דנגעים:\",2,0],[8,376,9,4,\"אין הכהן רשאי לטמא את הטמא וכו'. בתורת כהנים ובתוספתא נתבארה לעיל פ\\\"ו גבי בהרת הסמוכה לראש או לעין וצריך טעם למה הוצרך רבינו לחזור לשנותה פה. ומצאתי כתוב בספר מוגה תוספת בלשון רבינו ואינו רשאי לטהרו עד שיהיו עיניו במקום הנגע ובמקום הבשר שחוצה לו והוא לשון התוס' פ\\\"ק אלא ששם כתוב לטמאו:\",1,0],[8,376,9,4,\"וכהן שראה הנגע בתחלה וכו'. תוספתא דנגעים פירקא קמא ובתורת כהנים.\",2,0],[8,376,9,4,\"ומ\\\"ש ואין השני יכול לטמאו בפסיון וכו'. פשוט הוא.\",3,0],[8,376,9,4,\"ומ\\\"ש ונאמן כהן לומר נגע זה פשה וכו'. תוספתא פ\\\"ק דנגעים:\",4,0],[8,376,9,5,\"חלל פסול לראיית נגעים וכו'. בת\\\"כ.\",1,0],[8,376,9,5,\"ומה שכתב אבל בעלי מומין כשרים וכו'. גם זה בת\\\"כ.\",2,0],[8,376,9,5,\"ומ\\\"ש ובלבד שלא יהא סומא אפילו באחת מעיניו ואפילו כהן שכהה מאור עיניו וכו'. בפ\\\"ב דנגעים:\",3,0],[8,376,9,6,\"אין רואין את הנגעים אלא ביום. בתורת כהנים ובפירקא קמא דמועד קטן (דף ח') ובפ' אחד דיני ממונות (סנהדרין דף ל״ד ע״ב).\",1,0],[8,376,9,6,\"ומה שכתב ואין רואין לא בשחרית ולא בין הערבים ולא בתוך הבית ולא ביום המעונן וכו' ולא בצהרים וכו'. בפ\\\"ב דנגעים.\",2,0],[8,376,9,6,\"ומ\\\"ש אימתי רואין בשעה רביעית ובחמישי' ובשמיני' ובתשיעית שם ופסק כר\\\"י לגבי ר\\\"מ.\",3,0],[8,376,9,6,\"ומה שכתב בין נגעי אדם בין נגעי בגדים ובתים [נלמד מהיקשא דכתב רבינו בסוף פרק י\\\"ג]:\",4,0],[8,376,9,7,\"בכל יום רואין את הנגעים חוץ משבת ויום טוב. שם במשנה פרק קמא דאין רואין בשבת ומשמע לרבינו דהוא הדין ליו\\\"ט. ולענין חול המועד איפליגו במשנה פ\\\"ק דמ\\\"ק (דף ז') ומשמע דהלכה כחכמים דאמרי דאפילו בחול המועד אין רואין נגעים ומשמע לי דחול המועד הוי בכלל יו\\\"ט שכתב רבינו וכ\\\"כ בפ\\\"ז מהלכות יו\\\"ט אין רואין את הנגעים במועד וכך הוא סתם משנה ברגל נותנים לו כל ימי הרגל ואמרינן עלה בגמרא בהסגר ראשון כולי עלמא לא פליגי דחזי ליה ופרש\\\"י בהסגר ראשון שאם מטהר ליה משמח ליה אי לא מטהר ליה לא מטמא ליה יותר מדמעיקרא אלא מסגר ליה פעם שנייה והתוס' פירשו בענין אחר ויש לתמוה למה השמיטו רבינו ואפשר שסובר דלא קאי אלא אתנאי דברייתא ולא אחכמים דמתניתין.\",1,0],[8,376,9,7,\"ומ\\\"ש חל יום ז' שלו בשבת או ביו\\\"ט מעבירין לאחריו ויש בדבר להקל ולהחמיר וכו'. בפ\\\"ק דנגעים ופסק כר\\\"ע מחבירו:\",2,0],[8,376,9,8,\"חתן שנראה בו נגע וכו' וכן ברגל נותנין לו כל ימות הרגל. פרק ג' דנגעים:\",1,0],[8,376,9,9,\"אין מסגירין ולא מחליטין וכו' מפני שיום ז' עולה למניין שבוע ראשון ולמניין שבוע שני וכו'. בפ\\\"ג דנגעים שם:\",1,0],[8,376,9,10,\"אין מסגירין בתוך ימי הסגר וכו'. שם ופי' ר\\\"ש אין מסגירין את המוסגר היינו לומר שאם הסגירו בנגע אחד ואח\\\"כ נולד בו נגע אחר שראוי להסגירו או להחליטו אין נזקק לו ועל לא מחליטין את המוחלט פירש שאם החליטו בנגע א' ואח\\\"כ נולד לו נגע אחר שראוי להסגירו או להחליטו אין נזקקין לו ונ\\\"מ לקרבן ולמילי טובא דכי מיתסי מן האחד אין על השני תורת מוסגר ולא תורת מוחלט עד שיזקק לו אח\\\"כ ובאותו נגע נמי משכחת לה דאין מחליטין את המוסגר שאם הסגירו בבהרת כגריס ובאמצע השבוע נולד בו שיער לבן או מחיה אין מחליטו וכי אזלא לה מחיה או שיער לבן בסוף השבוע לא מיחייב קרבן אלא חוזר ומסגירו הסגר שני עכ\\\"ל:\",1,0],[8,376,9,10,\"ומ\\\"ש אבל אם היו בו שני נגעים וכו'. שם אבל בתחלה בסוף שבוע המסגיר מסגיר והמחליט מחליט מסגיר ופוטר מחליט ופוטר ובתוספת' פ\\\"ק עודהו מסגירו ופוטרו נולד בו נגע הרי זה נזקק לו ואם משהסגירו נולד לו נגע אחר אינו נזקק לו לטומאה או לטהרה עד סוף שבוע ובתורת כהנים יליף לה לכולהו מילתא מקראי:\",2,0],[8,376,9,10,\"ואין רואין שני נגעים כאחת וכו'. ריש פ\\\"ג דנגעים:\",3,0],[8,376,9,11,\"נגוע שבא לכהן לראותו וכו'. תוספתא ספ\\\"ק דנגעים.\",1,0],[8,376,9,11,\"ומ\\\"ש באו לפניו שנים רואה את הראשון וכו'. במשנה פ\\\"ג:\",2,0],[8,376,9,12,\"אין הכהן זקוק לבקש תחת אצילי ידיו וכו' וכיצד יעמוד לפני הכהן וכו' עד סוף הפרק. בפ\\\"ב דנגעים.\",1,0],[8,376,9,12,\"ומ\\\"ש וכן בהופך כולו לבן. ומה שכתב וכיצד יעמוד לפני הכהן וכו'. בפ\\\"ב דנגעים.\",2,0],[8,376,9,12,\"ומ\\\"ש כמו שיתבאר. הוא בפרק י\\\"א:\",3,0],[8,376,10,1,\"התולש סימני טומאה וכו'. בפרק ז' דנגעים התולש סימני טומאה והכוה את המחיה עובר בלא תעשה ובתוספתא פ\\\"ג.\",1,0],[8,376,10,1,\"ומ\\\"ש בין כולן בין מקצתן. שם בתוספתא ובספרי פרשת כי תצא.\",2,0],[8,376,10,1,\"ומ״ש או הקוצץ הנגע כולו מבשרו. בפרק ר״א דמילה (שבת דף קל״ב קל״ג) ובפרק ג' דמכות (דף י״ג ע״ב) אמרינן דקוצץ בהרתו הוי בלאו מדכתיב השמר בנגע הצרעת וכ״מ שנאמר השמר פן ואל אינו אלא לא תעשה.\",3,0],[8,376,10,1,\"ומ\\\"ש או מן הבגד או מן הבית וכן מ\\\"ש בין בתוך הסגר או בתוך החלט. בתוספתא פ\\\"ג ובספרי פרשת כי תצא מרבה לה מקרא.\",4,0],[8,376,10,1,\"ומ\\\"ש בין קודם שיבא לכהן בין לאחר הפיטור. בתוספתא ובספרי פ' כי תצא מרבה מקרא בין עד שלא נזקק לטומאה בין משנזקק לטומאה.\",5,0],[8,376,10,1,\"ומה שכתב אבל אינו לוקה עד שיועילו מעשיו וכו'. כיצד היתה בו בהרת ובה ג' שערות לבנות וכו'. בתוספתא אמרינן דכה\\\"ג פטור:\",6,0],[8,376,10,1,\"וכן המגלח את הנתק לוקה וכו'. בת\\\"כ מנין לתולש סימני טומאה מתוך נגעו שעובר בלא תעשה ת\\\"ל ואת הנתק לא יגלח.\",7,0],[8,376,10,1,\"ועל מ\\\"ש רבינו ואינו חייב עד שיגלח כל הנתק בתער. כתב הראב\\\"ד א\\\"א טעה בזה שהרי אמרו והתגלח בכל דבר וכו'. ורבינו נראה שסובר שלא אמרו בכל דבר אלא דוקא היכא דשני בדבוריה דה\\\"ל למכתב וגלח וכתב והתגלח.\",8,0],[8,376,10,1,\"ומ\\\"ש ועל זה נאמר ואת הנתק לא יגלח. י\\\"ל כלפי לייא דאדרבה משם ראיה מדלא מסיים ביה ואת הנתק לא יתגלח משמע דלאו בגוונא דרישא הוא. ומה שטען הראב\\\"ד עוד שהוא כתולש סימני טומאה י\\\"ל שאינו חייב אלא בתולש סימני טומאה ממש לא הגורם שלא יהיה פשיון ניכר בו ועוד שאפשר שלא יפשה:\",9,0],[8,376,10,1,\"ומותר למצורע לישא במוט על כתיפו וכו' ולקשור הסיב על רגלו וכו'. תוספתא פרק ג' ומייתי לה פרק ר״א דמילה (שבת דף קל״ג):\",10,0],[8,376,10,2,\"התולש סימני טומאה וכו'. משנה פרק שביעי דנגעים וכר' עקיבא שהודה לו ר\\\"ג ור' יהושע ואמרו לו יפה אמרת כדאמרינן בתוספתא:\",1,0],[8,376,10,2,\"ואין לו טהרה וכו'. שם וכחכמים:\",2,0],[8,376,10,3,\"מי שנקצצה בהרתו וכו'. שם:\",1,0],[8,376,10,3,\"ומה שכתב קצצה בכוונה אם קצץ כל הבשר החי וכו'. שם קצצה מתכוין ר\\\"א אומר לכשיולד לו נגע אחר ויטהר ממנו וחכ\\\"א עד שתפרח בכולו וכתב רבינו שם כבר בארנו בתוספתא כי כאשר חתך הבהרת בכללה עם קצת בשר חי המקיף בה משטח הגוף הנה אין לו טהרה עולמית לדברי הכל חתך קצת הבהרת ונשאר ממנה כל שהוא הנה הוא יטהר כשתפרח בכולו לדברי הכל ואמנם חלקו במשנה כשחתך בצמצום והלכה כחכמים עכ\\\"ל. וכתב רבינו שמשון דטעמא משום דהיכא דעקר הנגע כל כך דקצץ עמה בשר חי ראוי לקנסו טפי וכששייר ממנה לא קנסינן ליה כולי האי כשלא דקדק לחטט אחריה עכ\\\"ל. ולע\\\"ד נראה דטעמא משום דכיון דאין לו טהרה עד שתפרח בכולו כשקצץ בשר החי המקיפה והדר פרחה בכולו חזינן למקום אותו בשר חי המקיפה כאילו עדיין אותו בשר חי עומד שם והרי לא פרחה בכולו:\",2,0],[8,376,10,4,\"התולש שערה לבנה אחת וכו' והלך המותר הרי זה טמא. תוספתא פרק קמא דנגעים ומיירי בתולש מתוך החלט דוקא כמו שנתבאר:\",1,0],[8,376,10,5,\"מי שהיתה בהרת בערלתו ימול. בספ\\\"ז.\",1,0],[8,376,10,5,\"ומ״ש ואע״פ שהיא מילה שלא בזמנה וכו'. בפרק ר״א דמילה (שבת דף קל״ב קל״ג).\",2,0],[8,376,10,5,\"ומה שכתב ואם מל והלך בעור הערלה וכו'. תוספתא פ\\\"ג מצורע מוחלט ימול וחייב בקרבן:\",3,0],[8,376,10,6,\"מצות עשה שיהיה המצורע המוחלט מכוסה כל ראשו וכו'. בפרק אלו מגלחין (מועד קטן דף ט״ו) מצורע מהו בעטיפת הראש ת״ש ועל שפם יעטה מכלל שחייב בעטיפת הראש ובת״כ ועל שפם יעטה חופה ראשו כאבל וכן תירגם אונקלוס.\",1,0],[8,376,10,6,\"ומ\\\"ש פורם בגדיו. מקרא מלא הוא.\",2,0],[8,376,10,6,\"ומ״ש ומודיע כל העוברים עליו שהוא טמא. בס״פ בהמה המקשה (חולין דף ע״ח) [שבת ס״ז] ובת״כ.\",3,0],[8,376,10,6,\"ומה שכתב אפילו כ״ג שנצטרע פורע ופורם עד אפילו בשבתות וימים טובים. הכל ראש פרק אלו מגלחין (מועד קטן דף ט״ו).\",4,0],[8,376,10,6,\"ומ\\\"ש והרי הוא מותר ברחיצה ובסיכה ובנעילת הסנדל ובתשמיש המטה. שם בעיי ולא איפשיטו ולקולא ואיני יודע למה השמיט שמותר בעשיית מלאכה שגם היא שם בעיא דלא איפשיטא.\",5,0],[8,376,10,6,\"ומה שכתב שמותר בתשמיש המטה. אע\\\"פ ששם אמרו במצורע אסור בתשמיש המטה בפ\\\"ק דמ\\\"ק (דף ז' ע\\\"ב) איפליגו תנאי אם אסור בתשמיש אף בימי חלוטו ופסק רבינו כמ\\\"ד מותר משום דרבי ור' חייא סברי כוותיה ומתני' דפירקא בתרא דנגעים הכי משמע דקתני בימי ספרו ואסור בתשמיש המטה מכלל דעד השתא היה מותר:\",6,0],[8,376,10,7,\"דין המצורע שיהיה לו מושב לבדו ודין זה בעיירות המוקפות חומה וכו'. פרק קמא דכלים:\",1,0],[8,376,10,8,\"המצורעת אינה פורעת ואינה פורמת. משנה ספ\\\"ג דסוטה (דף כ\\\"ג) ויליף לה בגמרא מקראי.\",1,0],[8,376,10,8,\"ומה שכתב ולא עוטה על שפם, משום דכיון דאינה פורעת ופורמת ממילא דאינה עוטה על שפם דתרווייהו בחד קרא נינהו:\",2,0],[8,376,10,8,\"ולא המצורעים בלבד וכו'. בתורת כהנים:\",3,0],[8,376,10,9,\"וטומטום ואנדרוגינוס וכו' ספק. כלומר והוי ספיקא דאורייתא ולחומרא:\",1,0],[8,376,10,10,\"אחד מצורע מוסגר וכו'. משנה פ\\\"ק דמגילה (דף ח' ע\\\"ב) ופירקא קמא דכלים ויליף לה בגמרא מקרא ודקדק רבינו לכתוב לענין טומאה משום דלענין קרבנות אשם ולוג שמן יש ביניהם שאין מביאים אלא המוחלט:\",1,0],[8,376,10,11,\"המצורע אב מאבות הטומאה וכו'. בריש מסכת כלים אבות הטומאה השרץ וכו' הרי אלו מטמאים אדם וכלים במגע וכלי חרס באויר וכו' למעלה מהם נבילה וכו' שהם מטמאים את האדם במשא לטמא בגדים במגע וכו' למעלה מהם מרכב שהוא מטמא תחת אבן מסמא וכו' למעלה מן המשכב הזב שהזב עושה משכב וכו' למעלה מן הזב זבה שהיא מטמאה את בועלה למעלה מן הזבה מצורע שהוא מטמא בביאה וכתב שם רבינו ומאמרו במצורע שהוא למעלה מהזבה תדע שהוא יטמא במשא כמוה ושהוא יעשה משכב ומושב כזב וזבה וכו' [ואמרו בספרי] באמרו ה' במצורע מוחלט כאשר נרפא מהצרעת וכבס [המטהר את] בגדיו וטהר אמרו מה בא זה ללמדנו אם ללמד שמטמא בגדים במגע והלא ק״ו הוא וכו' א״כ למה נאמר וכבס המטהר את בגדיו מלטמא משכב ומושב עכ״ל. ובסוף זבים שנינו הנוגע בזב ובזבה ובנדה וביולדת ומצורע וכו' מטמא שנים ופוסל אחד אחד הנוגע ואחד המסיט אחד הנושא וא' הנישא ואף על פי שבפסחים פרק אלו דברים (פסחים דף ס״ז) אמרו זב חמור ממצורע שכן עושה משכב ומושב צ״ל שרבינו יפרש דהתם בימי ספירו קאמר א״נ שאינו גורס כי אם זב חמור שמטמא כלי חרס בהיסט.\",1,0],[8,376,10,11,\"ומה שכתב ואחד המוסגר ואחד המוחלט בכל אלו, היינו מדתנא אין בין מצורע מוסגר למצורע מוחלט אלא פריעה ופרימה:\",2,0],[8,376,10,12,\"חומרא יתירה יש במצורע וכו'. בפ\\\"ק דכלים ובפי\\\"ג דנגעים וכת\\\"ק.\",1,0],[8,376,10,12,\"ומ\\\"ש שנאמר מחוץ למחנה מושבו. בת\\\"כ:\",2,0],[8,376,10,12,\"היה עומד תחת האילן וכו'. בפי\\\"ג דנגעים.\",3,0],[8,376,10,12,\"ומ\\\"ש ספק עמד וכו'. אפשר שהוא מדתנן כל ספק נגעים טהור א\\\"נ משום דהוי ספק טומאה בר\\\"ה דסתם אילן הוא בר\\\"ה:\",4,0],[8,376,10,12,\"הכניס המצורע ראשו ורובו לבית וכו'. שם:\",5,0],[8,376,10,12,\"נכנס לבית הכנסת וכו'. גם זה שם ופירש ר\\\"ש גבוה עשרה טפחים דפחות אינה מחיצה להפסיק. רוחב ד' אמות משום ד' אמות של תפלה א\\\"נ משום דזהו שיעור מקומו של אדם כדאמרינן גבי עירוב בפרק מי שהוציאוהו וכו'. נכנס ראשון ויוצא אחרון כדי שלא יטמאו אותם העומדים בבית הכנסת בכניסתן וביציאתם באויר שמן הפתח עד המחיצה עכ\\\"ל. והראב\\\"ד כתב נכנס ראשון ויוצא אחרון א\\\"א שמא יתערב עם הצבור דרך העברתו ויטמא אותם עכ\\\"ל:\",6,0],[8,376,11,1,\"טהרת מצורע מצות עשה וכו'. בפי\\\"ד שנינו שלשה מגלחין ותגלחתן מצוה הנזיר והמצורע והלוים ובס' המצות כתב רבינו טעם למה מנה טהרת המצורע בפני עצמה והבאת קרבנות מצוה בפני עצמה והוא כי כוונת ותכלית התגלחת ליטהר מלטמא בשרץ ואז לא יהיה רק מחוסר כפורים ותכלית הקרבנות להשלים כפרתו ונמצא שאין התגלחת נקשרת עם הקרבנות:\",1,0],[8,376,11,1,\"כיצד מטהרים את המצורע וכו'. ריש פרק י\\\"ד דנגעים.\",2,0],[8,376,11,1,\"ומה שכתב וקבלה היא שיהיה של חרס, כך כתוב בספרי רבינו והוא ט\\\"ס שבפירוש כתוב בתורה כלי חרס וכך צריך להגיה וקבלה היא שיהיה חדש וכך נמצא בספר כתיבת יד. וכתב הר\\\"י קורקוס שטעם רבינו שכתב שהיא קבלה משום דהיינו מאי דדרשינן בפרק ב' דסוטה אל כלי חרס על מים חיים מה מים חיים שלא נעשה בהם מלאכה אף כלי ולפי שדרשא זו אינה מוכרחת כתב שקבלה היתה בידם פי' וקרא כעין אסמכתא עכ\\\"ל:\",3,0],[8,376,11,1,\"ומה שכתב ושיעור זה מדברי סופרים. בתורת כהנים ובפ\\\"ב דסוטה (דף י\\\"ז ע\\\"ב) מים שדם הצפור ניכר בהם ושיערו חכמים רביעית:\",4,0],[8,376,11,1,\"ומה שכתב לשם טהרת צרעת. בת\\\"כ ולקח למטהר לשם מטהר בין איש בין אשה בין קטן מכאן אמרו לקח לאיש כשירות לאשה לאשה כשירות לאיש לבית כשר למצורע למצורע כשר לבית.\",5,0],[8,376,11,1,\"ומ\\\"ש ושוחט את הברורה שבשתיהן. בת\\\"כ ושחט את האחת הברורה שבשתיהן.\",6,0],[8,376,11,1,\"ומ\\\"ש וממצה עד שיהא הדם ניכר במים. יתבאר בסמוך.\",7,0],[8,376,11,1,\"ומ\\\"ש וחופר וקובר וכו' בפניו. פי\\\"ד.\",8,0],[8,376,11,1,\"ומ\\\"ש ודבר זה קבלה מפי השמועה. ומ\\\"ש ונוטל עץ ארז ומצותו שיהיה אורכו אמה ועביו כרביע כרע מכרעי המטה. בפרק י\\\"ד דנגעים.\",9,0],[8,376,11,1,\"ומ\\\"ש ואזוב שאין לו שם לווי כמו שביארנו. בפרק י\\\"א דהלכות פרה אדומה.\",10,0],[8,376,11,1,\"ומ״ש אין פחות מטפח. בפרק המפלת (נדה דף כ״ו.)\",11,0],[8,376,11,1,\"ומ״ש ושני תולעת משקלו שקל. פ' טרף בקלפי (יומא דף מ״ב).\",12,0],[8,376,11,1,\"ומ\\\"ש ואם טעמו פסלו. בת\\\"כ.\",13,0],[8,376,11,1,\"ומ\\\"ש וכל השיעורים הלכה. בריש עירובין (דף ד').\",14,0],[8,376,11,1,\"ומ\\\"ש ולוקח עם שלשתן הצפור החיה. כך היא הגירסא.\",15,0],[8,376,11,1,\"ומ\\\"ש וארבעה מינין אלו מעכבין זה את זה. משנה בפ\\\"ג דמנחות (דף כ\\\"ז).\",16,0],[8,376,11,1,\"ומ\\\"ש ועץ ארץ ואזוב שנתקלפו פסולים. פ' היה מביא (דף ס\\\"ו).\",17,0],[8,376,11,1,\"ומ\\\"ש וכורך האזוב עם הארז וכו' עד ומשלח את הצפור. בפרק י\\\"ד דנגעים ומקיף פירושו וסומך ובתורת כהנים למדו שאינו אוגד אותה עמהם מדכתיב את הצפור החיה יקח אותה מלמד שמפרישה לעצמה:\",18,0],[8,376,11,1,\"כיצד משלחה וכו'. גם זה שם ובפ\\\"ב דקידושין ובתורת כהנים תניא לא יעמוד ביפו וישלחנה לים ולא יעמוד בגבת וישלחנה למדבר ולא יעמוד בגבת וישלחנה כלפי לעיר:\",19,0],[8,376,11,1,\"שלחה וחזרה חוזר ומשלחה. תוספתא פרק ח' דנגעים ומייתי לה בפ\\\"ב דקידושין:\",20,0],[8,376,11,1,\"כיצד מגלחו מעביר תער על כל בשרו וכו' עד ולמעט שיער שבתוך החוטם. בפ\\\"ב דסוטה עלה י\\\"ו ות\\\"כ ופסק כר\\\"ע מחבירו ונתן רבינו טעם לשיער החוטם לפי שאינו נראה:\",21,0],[8,376,11,1,\"וכתב הראב\\\"ד א\\\"א והלא ריבה שיער של בית הסתרים וכו'. וטעם רבינו דכיון דריבה ומיעט מוקמינן ריבויא לבית השחי שאם יגביה זרועו יהא נראה ומוקמינן מיעוטא לשיער החוטם שאינו נראה כלל.\",22,0],[8,376,11,1,\"ומ\\\"ש ואחר כך מכבס בגדיו וטובל וכו'. בפרק י\\\"ד דנגעים.\",23,0],[8,376,11,1,\"ומ\\\"ש ומלטמא משכב ומושב. בת\\\"כ.\",24,0],[8,376,11,1,\"ומ\\\"ש והמצורעת מותרת בתשמיש המטה. ברפ\\\"ב דכריתות (דף ח') ויליף לה מדכתיב וישב מחוץ לאהלו ולא מחוץ לאהלה:\",25,0],[8,376,11,2,\"כל שבעת הימים האלו וכו'. בריש כלים תנן דמצורע בימי ספרו הוא מאבות הטומאה ומטמא אדם וכלים במגע וכלי חרס באויר ואינו מטמא במשא. ומייתי לה מקרא בפרק קמא דב\\\"ב (דף ט' ע\\\"ב) שמטמא אדם:\",1,0],[8,376,11,2,\"ומ\\\"ש וביום השביעי מגלחו תגלחת שנייה וכו' עד לא עשה כלום. בפי\\\"ד דנגעים:\",2,0],[8,376,11,3,\"ומה שכתב ואינו מגלחו אלא כהן. בתוספתא.\",1,0],[8,376,11,3,\"ומ\\\"ש וכל היום כשר לטהרת המצורע. משנה סוף פ\\\"ב דמגילה (דף כ' ע\\\"ב):\",2,0],[8,376,11,5,\"תגלחת המצורע וטבילתו וכו' עד בין בישראל. תוספתא פ\\\"ח ות\\\"כ. ובנוסחת ספרי רבינו נראה שיש ט\\\"ס וצריך להגיה ולכתוב תגלחתו של מצורע טבילתו והזאתו מעכבין בו ושאר כל מעשיו אין מעכבין בו וכן כתב הראב\\\"ד שט\\\"ס הוא וז\\\"ל איני יודע מהו אדרבה אלו הן שמעכבין טהרתו וכו'. ויש ליישב שאין כאן ט\\\"ס דאינן מעכבות היינו שאין אחת מעכבת חבירתה דתגלחת לא מעכבא טבילה או הזאה וכן כולם וז\\\"ש רבינו זו את זו ושאר מעשיו דהיינו עץ ארז ואזוב ושני תולעת וצפרים מעכבים דצפורים מעכבים לעץ ארז וארז מעכב לאזוב וכן כולם ונסתלקה השגת הראב\\\"ד כך מצאתי כתוב. ויש ט\\\"ס אחר בדברי רבינו שכתוב שחיטת הצפור והתגלחת ביום וההזייה ושאר כל מעשיו בין ביום בין בלילה וצריך להגיה ולכתוב שחיטת הצפור והתגלחת וההזייה ביום וכך הוא בתוספתא וכן נמצא בספר רבינו כתיבת יד. ופירש וכל שאר מעשיו אין מעכבין בו כגון שילוח צפרים וכיבוס בגדים. בין ביום בין בלילה כגון לקיחת צפרים ושילוח צפורים וכיבוס בגדים וטבילה:\",1,0],[8,376,11,5,\"אלו באנשים וכו' אלו בכהנים. בתוספתא ובת\\\"כ מייתי לה מקרא:\",2,0],[8,376,11,6,\"טהרת מצורע זו נוהגת בארץ ובחוצה לארץ וכו' עד ואין מצורע מטהר מצורע. תוספתא פרק ח' דנגעים ותורת כהנים.\",1,0],[8,376,11,6,\"ומה שכתב ואין מטהרים שני מצורעים כאחת. [סוטה ח']:\",2,0],[8,376,11,7,\"עץ ארז ואזוב. תוספתא פ\\\"ח דנגעים וכרבי יהודה ורבי טרפון שעשו מעשה.\",1,0],[8,376,11,7,\"ומה שכתב וכן צפור המשתלחת וכו'. תוספתא פ\\\"ח ובתורת כהנים ובפירקא קמא דקידושין יליף שמותרת באכילה.\",2,0],[8,376,11,7,\"ומ״ש שיכול לטהר בה מצורעים אחרים. בתוספתא וכך משמע בפרק שילוח הקן (חולין דף ק״מ) דאמר רבא בטהורות איצטריך שלא יזווג לה אחרת קודם שילוחיה כלומר שאם נזדמן לו מצורע אחר לאחר שטיהר את זה ועדיין לא שילח הצפור לא יאמר אזווג אחרת עם זו ואטהר מצורע זה השני ואח״כ אשלח בעד שניהם משמע אחר ששלחה אם בא לידו כשרה לטהר בה מצורע אחר.\",3,0],[8,376,11,7,\"ומ״ש אבל הצפור השחוטה אסורה בהנאה. בס״פ האיש מקדש (קידושין דף נ״ז) ובתורת כהנים.\",4,0],[8,376,11,7,\"ומ\\\"ש ומאימתי תאסר משעת שחיטתה. שם וכר\\\"י:\",5,0],[8,376,11,7,\"שחטה שלא בעץ ארז וכו'. שם פלוגתא דתנאי ופסק כמ״ד שחיטה שאינה ראויה שמה שחיטה משום דקי״ל כרבנן דפליגי אר״ש בפרק אותו ואת בנו (חולין דף פ') ובפרק מרובה (בבא קמא דף ע״א):\",6,0],[8,376,11,7,\"והאוכל כזית מצפור השחוטה עבר על עשה ול\\\"ת וכו'. בסוף חולין (דף ק\\\"מ):\",7,0],[8,376,11,8,\"אין לוקחין שתי צפרים מצפורי עיר הנדחת וכו'. שם אמוראי וכל חד אמר חדא מהני וסובר רבינו דהנך אמוראי לא פליגי לענין דינא:\",1,0],[8,376,11,8,\"ומצותן שיהיו שתיהן שוות וכו'. בפי״ד דנגעים ומייתי לה ר״פ שני שעירי (יומא דף ס״ב ע״ב):\",2,0],[8,376,11,8,\"לקח שתי צפרים לשם איש וכו'. בתורת כהנים:\",3,0],[8,376,11,9,\"שחט אחת מהם וכו'. בפי\\\"ד דנגעים שם:\",1,0],[8,376,11,9,\"וכתב הראב\\\"ד והראשונה מותרת בהנאה א\\\"א ובתוספתא ארישא ושתיהן מותרות באכילה עכ\\\"ל. וז\\\"ל התוספתא שחט אחת מהן ונמצאת שנייה שלא דרור או שנמצאת טרפה יקח זוג לשניה ושתיהן מותרות ויביא שתים בתחלה שחטה ומתה חבירתה או שנעשית טריפה שתיהן אסורות ויביא שתים בתחלה עכ\\\"ל. ונראה דשניה שכתוב ברישא ט\\\"ס הוא דא\\\"כ קשיא רישא אסיפא וה\\\"ג שחט אחת מהן ונמצאת שלא דרור קאמר דיקח זוג לשניה ואם רצה לאכול את שתיהן ולהביא שתים בתחלה רשאי מפני שלא נאסרה לא השחוטה ולא חבירתה מאחר ששחיטה פסולה היתה ומן הדין לא הו\\\"ל להראב\\\"ד לתפוס אלא בוהראשונה מותרת באכילה אלא משום דתוספתא דקתני ושתיהן מותרות באכילה ובנמצאת טריפה השחוטה מותרת בהנאה וחבירתה מותרת באכילה וה\\\"ק הראב\\\"ד כיון דברישא שתיהן מותרות באכילה מינה נשמע דבסיפא שנייה מותרת באכילה והוא משיג על רבינו למה השמיט זה. וי\\\"ל שרבינו סובר שכיון שלא הוזכר כן במשנה משמע דמתניתין לא סברה הכי דא\\\"כ לא הוה שתקא מיניה. ומ\\\"מ לענין פי' התוספתא לפי גירסתנו שאין שנוי בה באכילה נראה לפרש דאנמצאת שלא דרור ואנמצאת טריפה קאי שזו מותרת באכילה וזו מותרת בהנאה ולא קאי אשניה כלל. אח\\\"כ מצאתי שרבינו שמשון בפי\\\"ד הביא תוספתא זו כמו שהיא כתובה ופירשה ויישבה:\",2,0],[8,376,11,9,\"וכתב הר\\\"י קורקוס ז\\\"ל לשון התוספתא בספרים שלנו כתובה בטעות שכתוב יקח זוג לשניה ושתיהן מותרות ויביא שתים בתחלה ולשון זה אין לו קיום דאי יקח זוג איך יביא שתים בתחלה אלא יקח זוג הוא ט\\\"ס וכאשר כתבתיה כתבה רבינו שמשון ופשוט עכ\\\"ל. ולי נראה לקיים הגירסא וה\\\"ק יקח זוג לשניה או יביא שתים בתחילה:\",3,0],[8,376,12,1,\"צרעת בגדים כגריס וכו'. בת\\\"כ יליף לה מקרא:\",1,0],[8,376,12,1,\"ירקרק הוא הירוק שבירוקין וכו'. בת\\\"כ והיה הנגע ירקרק יכול כל מראה ירוק ת\\\"ל ירקרק ירוק שבירוקין אדום יכול כל מראה אדום ת\\\"ל אדמדם אדום שבאדומים.\",2,0],[8,376,12,1,\"ומ\\\"ש ככנף הטווס וכו'. בתוספתא פ\\\"ק דנגעים ופסק כסומכוס לגבי ר\\\"א וצריך טעם למה.\",3,0],[8,376,12,1,\"ומ\\\"ש ושני מראות אלו מצטרפין זה עם זה. בת\\\"כ יליף לה מקרא:\",4,0],[8,376,12,1,\"במראה ירקרק או אדמדם מסגירין את הנגע וכו'. מקראות התורה והיה הנגע ירקרק או אדמדם בבגד וראה הכהן והסגיר את הנגע שבעת ימים וראה את הנגע ביום השביעי כי פשה הנגע בבגד ושרף את הבגד ואם יראה הכהן והנה לא פשה בבגד וצוה הכהן וכבסו את אשר בו הנגע והסגירו שבעת ימים שנית וראה הכהן אחרי הוכבס את הנגע והנה לא הפך הנגע את עינו והנגע לא פשה טמא הוא באש תשרפנו ואם ראה הכהן והנה כהה הנגע אחרי הוכבס אותו וקרע אותו מן הבגד ואם תראה עוד בבגד פורחת היא באש תשרפנו את אשר בו הנגע והבגד או השתי או הערב אשר תכבס וסר מהם הנגע וכובס שנית וטהר. ושנינו בפי\\\"א דנגעים העומד בראשון יכבס ויסגיר העומד בשני ישרף הפושה בזה ובזה ישרף וכו' הכהה בראשון יכבס ויסגיר הכהה בשני קורעו ושורף מה שקרע וצריך מטלית ובת\\\"כ וראה הכהן אחרי הוכבס והנה לא הפך ולא פשה טמא הוא הפך ולא פשה איני יודע מה יעשה לו ת\\\"ל והסגירו שבעת ימים שנית דברי ר\\\"י וחכ\\\"א מטמא משום עומד הא מה אני מקיים והנה לא הפך הנגע את עינו והנה לא פשה טמא הפך טמא בכל מין שהוא מטמא לו ופי' ה\\\"ר אליה מזרחי ז\\\"ל דברי ר\\\"י דוקא אם עמד בעינו הראשון ולא הפך אז הוא טמא וטעון שריפה אבל אם נהפך ממראה למראה כגון מירקרק לאדמדם או ההיפך נגע חדש הוא וטעון הסגר בתחילה וחכמים סברי דינו כעומד בעינו בראשון דכיון דלא נהפך למראה טהור אלא למראה טמא כגון מירקרק לאדמדם או ההיפך ששניהם מראות טומאה הן לא הפך קרינן ביה ואי זה יקרא הפך כשנהפך למראה שאינו מטמא לו אבל זה שנהפך למראה שהוא מטמא לו לא הפך קרינן ביה וטעון שריפה וזהו ששנינו בת\\\"כ אליבא דחכמים הא מה אני מקיים והנה לא הפך הנגע את עינו והנגע לא פשה טמא דמשמע מיניה הא הפך ולא פשה לא הוי טמא כשהפך ממין דמטמא לו למין דלא מטמא לו דאע\\\"ג דהוה ירקרק והפך אדמדם או ההיפך אכתי לא הפך קרינן ביה דלא הפך למין דלא מטמא לו אבל אם הפך למין דלא מטמא לו לא עכ\\\"ל. ובת\\\"כ תניא תו והנה כהה הנגע למראה שני ולא למראה שלישי:\",5,0],[8,376,12,1,\"והשתא מ\\\"ש רבינו שאם עמד במראהו ולא פשה יכבס ויסגיר, היינו מדאמר קרא שאם בסוף הסגר שני עמד בעינו ולא פשה ישרף משמע הא בסוף הסגר ראשון יסגיר וכן מדאשכחן דבסוף הסגר שני הפך ולא פשה ישרף לדעת חכמים הא בסוף הסגר ראשון יסגיר ותנן בפי\\\"א דנגעים נשתנה ולא פשה כאילו לא נשתנה וא\\\"כ ה\\\"ל עומד בסוף שבוע ראשון ויסגיר וזהו שכתב או שהוסיף המראה להאדים ולהוריק ולא פשה יכבס ויסגיר.\",6,0],[8,376,12,1,\"ומ\\\"ש או שפשה וכהה משני המראות שהוסגר בהם. בפי\\\"א הכהה בראשון יכבס ויסגיר ומשמע לרבינו דהיינו אפילו אם פושה והוא פשוט דכיון שכהה ממראות הטומאה כי פשה מאי הוי:\",7,0],[8,376,12,1,\"ומה שכתב ובסוף שבוע שני רואה אם כהה למראה שלישית ה\\\"ז טעון כיבוס וטהור. היינו מדכתיב בסוף שבוע שני שאם כהה הנגע אחרי הוכבס את הנגע וקרע אותו מן הבגד ותניא בת\\\"כ והנה כהה הנגע למראה שני ולא למראה שלישי משמע בהדיא שאם כהה למראה שלישי אינו צריך לקרוע ובתוספתא פ\\\"ה אליבא דחכמים:\",8,0],[8,376,12,1,\"ומה שכתב ואם נשתנה הנגע ממה שהיה וכו'. נראה דהיינו מדכתיב בסוף הסגר שני והנה לא הפך הנגע את עינו והנגע לא פשה באש תשרפנו משמע הא אם הפך את עינו מאחר דלא פשה לא ישרפנו והוי כדין כהה הנגע שקורע מקום הנגע מהבגד והא דתנן נשתנה ולא פשה כאילו לא נשתנה לא שיהא לגמרי כאילו לא נשתנה דליהוי כעומד שני שבועות אלא לאפוקי מדר\\\"י דאמר יראה בתחלה תנא דאינו נראה בתחלה אלא דנין אותו כדין נגע שאירע בו כך.\",9,0],[8,376,12,1,\"ומה שכתב ומכבסו כולו כיבוס שני. היינו מדכתיב והבגד או השתי וכו' אשר תכבס וסר מהם הנגע וכובס שנית וטהר:\",10,0],[8,376,12,1,\"וכתב הראב\\\"ד ואם נשתנה ממה שהיה א\\\"א טעה בכאן טעות גדולה. טעמו להשיג על רבינו מדאמר קרא בכהה וקרע והיינו בכהה למראה שני דהיינו מירקרק לירוק ומאדמדם לאדום אז וקרע אבל מירקרק לאדמדם ומאדמדם לירקרק הוי מראשון לראשון ואין זה כהה וישרף וכבר נתתי טעם לדברי רבינו דדייק מדכתיב והנה לא הפך הנגע את עינו באש תשרפנו משמע הא אם הפך את עינו לא ישרף והפך היינו מירקרק לאדמדם מאדמדם לירקרק דאי לא כן הו\\\"ל למכתב והנה לא כהה הנגע. ומ\\\"ש עוד והמשנה אמרה נשתנה ופשה וכו'. כבר ישבתי המשנה לדעת רבינו. ומה שכתב עוד ומה שאמרה המשנה הכהה בראשון יכבס ויסגיר הכהה בשני קורעו ושורף מה שקרע כהה למראה שני קאמר וכו' כלומר א\\\"ת שטעמו של הרמב\\\"ם מדתנן בפרק י\\\"א דנגעים הכהה בראשון יכבס ויסגיר דמשמע ליה דכהה היינו מירקרק לאדמדם ומאדמדם לירקרק והא קתני דכהה בשני קורעו ושורף מה שקרע לאו מילתא היא דכהה אינו מירקרק לאדמדם דההוא הוי מראשון לראשון אלא מירקרק לירוק שהוא למראה שני ותדע דכהה דמתניתין הוי כמו כהה דקרא ובכהה דקרא אמרו בתורת כהנים דהיינו למראה שני ואז קורעו ושורף מה שקרע אבל אם כהה למראה שלישי אינו טעון קריעה אלא כיבוס לבד ומראה שני משמע מראה שהוא שפל מן הראשון דומיא דמראה שלישי שר\\\"ל שהוא שפל מהשני וזה טעם הזכירו כאן מראה שלישי שנראה שאינו ענין לו ומירקרק לאדמדם אינו מראה שפל ממנו אלא שוה לו. וא\\\"ת ע\\\"כ יש לך לומר דמירקרק לירוק הוי מראה שלישי וטהור דאי לאו כן למה אמרו שאין הנגעים מטמאים אלא בירקרק שבירוקים ובאדמדם שבאדומים לכך אמר אבל בתחלה אין נזקקין אלא לירקרק ואדמדם כלומר אבל לא לירוק ואדום דהפרש יש בין קודם שנזקק לטומאה לאחר שנזקק לטומאה. ומ\\\"ש וכן הוא המשנה לדעת חכמים בא להכריע עוד דכהה דמתניתין היינו מירקרק לירוק ולא מירקרק לאדמדם מדתנן בפרק י\\\"א דנגעים הכהה בתחלה רבי ישמעאל אומר יכבס ויסגיר וחכמים אומרים אינו זקוק לו ובשלמא אם כהה היינו ירוק או אדום היינו דאמרי רבנן אין זקוק לו שכיון דעדיין לא נזקק לטומאה לאו כלום הוא אבל אם הוא מירקרק לאדמדם אמאי אין נזקקין לו וכפי מה שכתבתי לדעת רבינו אין צורך להשיב על טענותיו דרבינו מקרא הוא דורש אפילו אם תמצי לומר דפירושא דמתניתין כפירוש הראב\\\"ד אין בכך כלום שדין זה אינו ענין לכהה דמתניתין אלא לנשתנה ולא פשה וכדפרישית. ועוד י\\\"ל אפשר דרבינו מפרש דכהה בשני דמתניתין היינו נשתנה מירקרק לאדמדם ומה שטען הראב\\\"ד על זה דכהה דמתניתין הוי דומיא דקרא יש להשיב דמידי איריא הא כדאיתא והא כדאיתא ועוד דבין כהה דקרא ובין כהה בשני דמתניתין הוי מירקרק לאדמדם דוקא והוא מראה שני שאמרו בתורת כהנים אבל נשתנה לירוק או לאדום זהו כהה למראה ג' שאמרו בתורת כהנים דטהור שכשם שאין הירוק והאדום סימן טומאה בתחלה אף לא בסוף. ומה שרצה להכריע מדתנן הכהה בתחלה אינו זקוק לו שאם הוא מירקרק לאדמדם למה אינו זקוק לו י\\\"ל דכיון דקודם שנזקק לטומאה הוא אינו זקוק לו כדאשכחן בפסיון שאינו מטמא בתחלה כמו ששנינו בתורת כהנים וכי היכי דמפליג הראב\\\"ד בירוק ואדום בין קודם שנזקק לטומאה לאחר שנזקק לטומאה הכי מפליג רבינו בנשתנה מירקרק לאדמדם ובאי זה דרך משני דרכים אלו עלו דברי רבינו כהוגן בלא טעות:\",11,0],[8,376,12,2,\"נגע שהיה ירקרק ופשה אדמדם וכו'. משנה פי\\\"א דנגעים:\",1,0],[8,376,12,3,\"נגע שהיה באמצעו מקום נקי וכו'. בת\\\"כ נגע הנתק מקיש נגע לנתק מה נתק אינו פושה אף נגע וכל שהוא קרוי נגע בכלל:\",1,0],[8,376,12,4,\"הפשיון הסמוך בבגדים כל שהוא וכו'. בפי\\\"א דנגעים ובתורת כהנים יליף לה מקראי:\",1,0],[8,376,12,4,\"וכתב הראב\\\"ד א\\\"א אם תעיין בדרש תורת כהנים וכו'. השיג על רבינו למה כתב בבגדים דמשמע שדין זה מיוחד בבגדים ואינו כן שאדם ובגדים ובתים שוין בדין זה. וז\\\"ל הראב\\\"ד בפירושו לת\\\"כ הוא פרט לשפשתה לבוהק פי' דקי\\\"ל פשיון כל שהוא והרחוק כגריס בנגעי בגדים ובתים ואע\\\"ג דלא אשכחן לה בפירוש שמעינן לה מכללי דמתניתין דפשיון הרחוק לא מטמא בנגעים דאדם דתנן בנגעים פ\\\"ד בהרת כגריס וחוט יוצא ממנה אם יש בו רוחב ב' שערות זוקק לשיער לבן ולפשיון אבל לא למחיה שמעינן מהא דאי לית ביה רוחב שתי שערות אינו זוקק לפשיון דאם פשה חוץ לאותו חוט לא מטמא משום פסיון אלמא פסיון הבא מרחוק לא מטמא ותנן בנגעים פ\\\"ק היה בו פסיון והלך לו הפשיון או שהלכה לה האום או שנתמעטה ואין בזה ובזה כגריס השחין ומחית השחין המכוה ומחית המכוה חולקין בין האום לפשיון הרי אלו להקל שמעינן מהאי טעמא דשחין ומכוה ובוהק חולקין בין האום לפשיון הוא טהור משום דשחין ומכוה ובוהק לא חזי לפשיון אבל עור הבשר בעלמא אע\\\"פ שחולק ביניהם טמא אלמא פשיון הרחוק מטמא אלא ש\\\"מ חדא בפשיון כל שהוא וחדא בפסיון שהוא כגריס עכ\\\"ל. וי\\\"ל לדעת רבינו שאע\\\"פ שהם שוים בסמוך ורחוק הם מוחלקין בחוזר דבבתים הוי כשני גריסין כדתנן בספי\\\"ב דנגעים:\",2,0],[8,376,12,5,\"מי שמכבס את הנגע בשבוע ראשון וכו'. בת\\\"כ יליף לה מקרא:\",1,0],[8,376,12,5,\"וכל נגעי בגדים וכו'. בפ' דם חטאת (זבחים דף צ״ה):\",2,0],[8,376,12,6,\"בגד שקרע מקום הנגע וכו' עד בסימנים. בפי\\\"א דנגעים וכפשטא דמתניתין ולא כדמשמע בתוספתא:\",1,0],[8,376,12,8,\"בגד שבא כולו בתחלה ירקרק או אדמדם וכו'. בפרק כל היד עלה י\\\"ט ובפרק הנחנקין (סנהדרין דף פ\\\"ז ע\\\"ב) רבי נתן בן אבטולמוס אומר מנין לפריחת בגדים שהיא טהורה וכו' וקשיא לי דהתם משמע דרבנן פליגי עליה ואמאי שבק רבנן ופסק כרבי נתן:\",1,0],[8,376,12,8,\"וכתב הראב\\\"ד ואחר שפטרו וכו'. א\\\"א לא מצאתי נוסחא מאושרת בזה וכו'. כתב הר\\\"י קורקוס ז\\\"ל ונראים הדברים ק\\\"ו בבגדים פי' דעיקר פריחה לטהר באדם כתיבא ומ\\\"מ רבינו השוה דין פריחת בגדים לדין פריחת נתקים שנתבאר רק ח' שאפי' פריחה לאחר הפיטור מטהרת בהם:\",2,0],[8,376,12,9,\"ומה שכתב רבינו וזה שנאמר בבגדים בקרחתו וכו'. כלומר לא יקשה עליך קרא דבקרחתו או בגבחתו דמשמע דקרחתו היינו האריג וגבחתו היינו המוכין וקתני או דאין פירוש קרחתו וגבחתו כן אלא קרחתו אלו השחקים גבחתו אלו החדשים וכן פירש בתורת כהנים וכן תרגם אונקלוס.\",1,0],[8,376,12,9,\"ומה שכתב רבינו כנס ופשה ישרף. בתוספתא פרק חמישי:\",2,0],[8,376,12,9,\"בגד שמוכין יוצאין על פניו מן האריג וכו'. בסוף פרק י\\\"א דנגעים:\",3,0],[8,376,12,10,\"הבגדים הצבועים וכו'. בפרק י\\\"א דנגעים העורות והבגדים הצבועים אינם מטמאין בנגעים הבתים בין צבועים בין שאינם צבועים מטמאין בנגעים דר\\\"מ רבי יהודה אומר העורות כבתים ר\\\"ש אומר הצבועים בידי שמים מטמאים [בנגעים] בידי אדם אינם מטמאין [בנגעים] ופירש ר\\\"ש הצבועים אפי' בידי שמים ובת\\\"כ יליף טעמייהו מקראי בין צבועים ואפילו בידי אדם העורות כבתים בבגדים ובתים מודו ר\\\"י ור\\\"ש לר\\\"מ:\",1,0],[8,376,12,10,\"בגד ששתיו צבוע וכו'. בפרק י\\\"א דנגעים שם. וכתב ר\\\"ש בסתם בגדים הערב נראה בכרים ובכסתות השתי נראה כדמשמע בתוספתא והדבר תלוי לפי ענין האומנות ולכך סתם ושנה אחר הנראה:\",2,0],[8,376,12,10,\"פחות מג' אצבעות וכו'. בפי״ב ובפרק במה מדליקין (שבת דף כ״ט) מייתי לה מקרא:\",3,0],[8,376,12,11,\"בגד שארג בו פחות מג' על ג' וכו'. בפי\\\"ב דנגעים שם:\",1,0],[8,376,12,12,\"התופר מטליות וכו'. נלמד מהדין שיבא בסמוך:\",1,0],[8,376,12,13,\"בגד שהוא מטליות וכו'. בפרק אחד עשר דנגעים ובתורת כהנים קייטא שיש בה פספסים צבועים ולבנים פוסים מזה לזה שאלו את ר' אליעזר והרי הוא פספס יחידי ומסקנא יסגיר שמא יעמוד שני שבועות והעומד בבגדים שני שבועות טמא ופירש רבינו קייטא בגד מחובר מחתיכות קטנות וכל חתיכה נקראת פספס מן פס ידא. וסובר תנא דמתניתין שאע\\\"פ שאין בכל חתיכה שלש על שלש מטמא בנגעים כאילו היה ארוג כי התפירה חיבור גמור הוא וסובר שכשיש בין שתי חתיכות לבנות חתיכה צבועה בינתיים אינה חשובה הפסק ומועיל הפשיון מחתיכה לבנה זו לחתיכה לבנה הרחוקה וע\\\"פ מה שנתבאר דבבגדים מטמא פשיון רחוק ובתוספתא פליג רבי נחמיה וסובר דבעינן שיהיה באחת הלבנה ג' על ג' ואינה הלכה אלא כת\\\"ק וכרבי אליעזר ורבותיו שבמשנה אמרו שאלו את ר\\\"א הרי הוא פספס יחידי פי' שאין שם לבן אלא חתיכה אחת שאין בה ג' על ג' וכל השאר צבוע מה יהא דינה שהרי אין בה מקום לפסיון כי הנגע ממלא כולה כי אין בה אלא כגריס לבד אמרו לו מה תועלת בהסגר זה שהרי אין שם חתיכה אחרת לבנה שיפשה לה א\\\"ל לא שמעתי א\\\"ל רבי יהודה בין בתירא אלמד בו א\\\"ל אם לקיים דברי חכמים הן א\\\"ל שמא יעמוד כך שני שבועות והעומד בבגדים שני שבועות טמא א\\\"ל חכם גדול אתה שקיימת דברי חכמים:\",1,0],[8,376,13,1,\"אין מטמא בנגעים אלא בגדי צמר ופשתים וכו'. מפורש בתורה.\",1,0],[8,376,13,1,\"ומ\\\"ש בין קשה בין רך. ומ\\\"ש אף העור הצבוע בידי שמים מטמא בנגעים. כבר כתבתי בפרק שקודם דבפרק י\\\"א איפליגו תנאי בעורות דלר\\\"מ אף הצבועים בידי שמים אינם מטמאין בנגעים ולר' יהודה אפילו צבועים בידי אדם מטמאים בנגעים ולר\\\"ש הצבועים בידי שמים מטמאים בנגעים ובידי אדם אינם מטמאין בנגעים ורבינו כתב אף העור הצבוע בידי שמים מטמא בנגעים ואין לפרש דה\\\"ק אצ\\\"ל דצבוע בידי אדם מטמא בנגעים אלא אף הצבוע בידי שמים מטמא דהא משמע במתניתין ובת\\\"כ דיותר ראויים לטמא הצבועים בידי שמים מהצבועים בידי אדם הילכך ודאי ה\\\"ק אע\\\"פ שהוא צבוע מטמא בנגעים והוא שיהיה צבוע בידי שמים וא\\\"כ פסק כרבי שמעון ויש לתמוה היאך פסק כר\\\"ש נגד ר\\\"י וי\\\"ל משום דבצבועים בידי אדם ה\\\"ל ר\\\"מ ור\\\"ש תרי נגד ר\\\"י והלכה כרבים ועי\\\"ל דהא דר\\\"ש שנויה בתוספתא בשם רבי עקיבא וידוע דהלכה כרבי עקיבא מחבירו:\",2,0],[8,376,13,1,\"והלבדים כבגדים וכו'. בתוספתא רפ\\\"ה והאהלים מטמאים בנגעים וכו'. שם ובתורת כהנים:\",3,0],[8,376,13,2,\"כל הבגדים וכו' עד יראו בתחלה. ר\\\"פ י\\\"א דנגעים:\",1,0],[8,376,13,2,\"בגד שהוא כלאים וכו'. בתורת כהנים:\",2,0],[8,376,13,3,\"צמר גמלים וצמר רחלים וכו'. ברפ\\\"ט דכלאים ובפי\\\"א דנגעים:\",1,0],[8,376,13,3,\"ורחל בת עז וכו'. בפ\\\"ב דבכורות (דף י\\\"ז):\",2,0],[8,376,13,3,\"בגד שהיה שתיו פשתן וכו'. תוספתא פ\\\"ה בגד ששתיו סריקין וכו' ואינו מפרש כר\\\"ש שהוא צבע אלא מין משי כמו הכלך והסריקון וה\\\"ה לקנבוס:\",3,0],[8,376,13,4,\"העור שאינו מעובד וכו'. בת\\\"כ.\",1,0],[8,376,13,4,\"ומ\\\"ש וכן העור שהוא גולם וכו'. תוספתא פרק ששי ובת\\\"כ:\",2,0],[8,376,13,4,\"וכל כלי העור וכו':\",3,0],[8,376,13,5,\"עורות חיה שבים וכו'. ריש פי\\\"א דנגעים ובת\\\"כ מייתי לה מקרא.\",1,0],[8,376,13,5,\"ומ\\\"ש והוא שיחברנו לו כדרך חיבורי בגדים לטומאה. שם ובתורת כהנים מייתי לה מקרא:\",2,0],[8,376,13,6,\"כל כלי הראוי להתטמא בשאר הטומאות וכו'. בפי\\\"א דנגעים:\",1,0],[8,376,13,6,\"החמת והתורמל וכו'. שם.\",2,0],[8,376,13,6,\"ומ\\\"ש וכן כל כיוצא בהן וכו':\",3,0],[8,376,13,7,\"סדין המקומט וכו'. תוספתא פירקא קמא:\",1,0],[8,376,13,8,\"השתי והערב וכו'. בפרק אחד עשר דנגעים ובפרק קמא:\",1,0],[8,376,13,8,\"וכמה יהא בפקעת וכו'. שם:\",2,0],[8,376,13,8,\"היתה הפקעת מקובצת וכו'. גם זה שם:\",3,0],[8,376,13,9,\"שתי פקעיות וכו'. גם זה שם המעלה מן הפקעת לחבירתה וכו' ושני דפי חלק השני במשנה פי' רבינו בעת הבדל בגד או חלוק מחבירו כאשר ישארו שתי חתיכות מחוברות בחוט מן השתי או מן הערב:\",1,0],[8,376,13,9,\"ומה שכתב נראה הנגע בנפש המסכת וכו' עד הסדין טהור. גם זה שם ופירוש נפש היינו הערב כי חוטי הערב בשתי כנפש בתוך הגוף ומעמדת אותו כנפש ושתי העומד הוא השטוח כדי לארוג.\",2,0],[8,376,13,9,\"ומ\\\"ש פשה מן הנימין וכו'. תוספתא בפ\\\"ה:\",3,0],[8,376,13,10,\"חלוק שנראה בו נגע מציל את האמריות שבו וכו'. בפי\\\"א דנגעים חלוק שנראה בו נגע מציל את האמריות שבו אפילו הן ארגמן ובת\\\"כ ושרף את הבגד וכו' א\\\"כ למה נאמר בצמר או בפשתים להוציא אמריות שבו אוציא אמריות של זהב ושל שירים שאין מינן מטמא בנגעים ולא אוציא של ארגמן ושל זהורית טובה שמינן מטמא בנגעים ת\\\"ל אשר בו הנגע הראוי לקבל נגע עכשיו ופי' ר\\\"ש ארגמן וזהורית הוא צמר צבוע ותולעת שני מינן מטמא בנגעים דהיינו צמר שאינו צבוע. הראוי לקבל נגע עכשיו לאפוקי הני שהם צבועים עכ\\\"ל. וז\\\"ל רבינו שם מאמרו בצמר או בפשתים יורה שבהן מה שישרוף ומה שיעזוב ובאה הקבלה שיעזוב ממנו האמריות שבו ואפילו היו מארגמן אשר הוא צמר שלא תחשוב שהם לא יצילו מן השריפה אם לא יהיו ממשי או מזהב והדומה לו לא שיהיו מצמר ופשתים עכ\\\"ל. ונראה שרבינו סובר שאפילו האמריות מצמר לבן אינן נשרפות עם הבגד מאחר שנתמעטו מהכתוב ותנא דנקט ארגמן אורחא דמלתא נקט שדרך לעשות האמריות מארגמן אבל אה\\\"נ אפילו מן הצמר לבן הם ניצולות וה\\\"ל כאילו אמר אפילו הם מצמר:\",1,0],[8,376,13,11,\"בגד מוסגר שצבעו וכו'. תוספתא פ\\\"ה וכת\\\"ק.\",1,0],[8,376,13,11,\"ומ\\\"ש וכן אם נתערב באחרים וכו' עד ומותר בהנייתו. משנה בספי\\\"א דנגעים.\",2,0],[8,376,13,11,\"ומ\\\"ש היתה בהן אחת ג' על ג' וכו'. תוספתא בפ\\\"ה ולאפוקי מר\\\"א בר\\\"ש דאמר שאם נראה נגע בזו שהיתה ג' על ג' כולן ישרפו:\",3,0],[8,376,13,12,\"בגד מוחלט שנתערב וכו'. משנה ספי\\\"א דנגעים. ובת\\\"כ מייתי לה מקרא.\",1,0],[8,376,13,12,\"ומה שכתב אפילו אחד בכמה אלפים:\",2,0],[8,376,13,13,\"אחד בגד או כלי עור וכו'. בת\\\"כ זאת תורת נגע הצרעת בגד הצמר או הפשתים או השתי או הערב או כל כלי עור מקישן לבית מה בית מטמא בביאה אף כולם מטמאין בביאה וכתבה ר\\\"ש בפי\\\"ג דנגעים הלכה ח' ופירש ר\\\"ש מקישן לבית בפסוק זאת תהיה דכתיב ולצרעת הבגד ולבית וכיון דהקיש התם בגד לבית וה\\\"ה לכל הכתובים כאן עם הבגד כגון שתי וערב וכלי עור.\",1,0],[8,376,13,13,\"ומ\\\"ש ומטמא במגע ומשא. ומ\\\"ש ועושה משכב ומושב וכו'. ומ\\\"ש כיצד בגד מנוגע וכו' שהכניס מהם אפי' כזית לבית טהור נטמא וכו'. בפי\\\"ג דנגעים:\",2,0],[8,376,13,13,\"וכתב הראב\\\"ד וכן משכב ומושב המונח תחת האבן והניח כזית מהן למעלה וכו' א\\\"א בחיי ראשי טעה בדמיונותיו וכו'. ואני אומר מאן יהיב לן מעפרא דמרן הראב\\\"ד ומלינן עיינין דמקשה לרבינו על אבן המנוגעת והוא דבר שלא הוזכר בדברי רבינו כלל ואין ספק שספר מוטעה נזדמן לו בדברי רבינו:\",3,0],[8,376,13,14,\"מטלית שיש בה שלש על שלש וכו'. תוספתא שם:\",1,0],[8,376,13,14,\"ומה שכתב היו בה כמה זיתים וכו'. משנה פי\\\"ג שם:\",2,0],[8,376,13,14,\"אע\\\"פ שכל השיעורים הל\\\"מ וכו':\",3,0],[8,376,13,15,\"בגדים המנוגעים וכו'. תוספתא פרק שביעי:\",1,0],[8,376,14,1,\"צרעת בתים כשני גריסין וכו'. בפי\\\"ב ובת\\\"כ מייתי לה מקרא.\",1,0],[8,376,14,1,\"ומ\\\"ש שרחבו כמו צמיחת שש שערות בגוף וכו'. נלמד ממה ששנינו בפר\\\"ו שמקום הגריס ל\\\"ו שערות והיינו לומר שהיא שש על שש שבתשבורת הם ל\\\"ו על ל\\\"ו:\",2,0],[8,376,14,2,\"ושני המראות מצטרפין זה עם זה. יליף מבגדים:\",1,0],[8,376,14,2,\"ופשיון הסמוך כל שהו וכו'. בס\\\"פ י\\\"ב ובת\\\"כ יליף לה מקרא:\",2,0],[8,376,14,3,\"אין נגעי בתים מטמאים וכו'. בתורת כהנים ומסיים בה ומראיהם שפל מן הקיר ולא ממשן וזו כוונת רבינו במה שכתב שיהיו שוקעות בקיר וכמ\\\"ש תחלה מראה הנגע וכו':\",1,0],[8,376,14,3,\"ומה שכתב ובב' המראות מסגירין או מחליטין ובפסיון נותצין וכו'. מבואר בתורה אלא שהחלט זה שכתב בלא פסיון איני ידוע מהו:\",2,0],[8,376,14,4,\"כשיראה נגע בבית וכו'. בפרק י\\\"ב.\",1,0],[8,376,14,4,\"ומה שכתב ואפילו חבילי עצים אפילו חבילי קנים. שם וכר\\\"י ויש לתמוה למה פסק כמותו במקום רבי שמעון ורבי מאיר דרבים נינהו ואפשר שרבינו סובר דבהא ל\\\"פ וצ\\\"ע:\",2,0],[8,376,14,5,\"בית אפל וכו'. בפ\\\"ב ואיתא בפ\\\"ק דחולין (דף י' ע\\\"ב) ומייתי לה מקרא בת\\\"כ:\",1,0],[8,376,14,5,\"ויעמוד על פתח הבית וכו'. בפי\\\"ב ובת\\\"כ מייתי לה מקרא ואע\\\"פ שלא הוזכר במשנה אלא לענין הסגר משמע לרבינו דה\\\"ה לענין מחליט ופוטר:\",2,0],[8,376,14,5,\"ומה שכתב ואם עמד תחת המשקוף או שהלך לתוך ביתו וכו'. בת״כ ובפ״ק דחולין ופ' הנודר מן הירק (נדרים דף נ״ו ע״ב):\",3,0],[8,376,14,6,\"אין הבית מטמא בנגעים עד שיהא בו ד' אמות על ד' אמות וכו'. בריש סוכה (דף ג' ע\\\"ב).\",1,0],[8,376,14,6,\"ומ\\\"ש ויהיה לו ד' כתלים. כתב רבינו בפי' המשנה פי\\\"ב דהיינו מדכתיב קירות הבית תרי זימני והוא בת\\\"כ ופ' גט פשוט וזהו ששנינו בפי\\\"ב בית טריגון אינו מטמא בנגעים והוא בעל ג' כתלים כי טריגון הוא מלשון יוני שטריאה הם ג':\",2,0],[8,376,14,6,\"ומה שכתב והוא בנוי בארץ. בת\\\"כ בבית ארץ פרט לבית הבנוי בספינה או באסקריא ועל ד' קורות והוא במשנה פי\\\"ב.\",3,0],[8,376,14,6,\"ומ\\\"ש באבנים ועפר ועצים. שם בפי\\\"ב.\",4,0],[8,376,14,6,\"ומ\\\"ש או שהיה עגול. שם.\",5,0],[8,376,14,6,\"ומ\\\"ש או בעל ה'. בתוספתא פ\\\"ו ואיתא נמי בפרק גט פשוט ובספ\\\"ק דנזיר (דף ח') בית פנטיגון אינו מטמא בנגעים והוא נגזר מלשון יוני שפינט\\\"י הם חמשה ויליף לה בת\\\"כ מקראי.\",6,0],[8,376,14,6,\"ומ\\\"ש והיה בנוי על ד' עמודים וכו'. משנה רפי\\\"ב ופי' שם רבינו ר\\\"ל אפילו יהיו בלתי על ד' עמודים בארץ ועליהם גג הנה יטמא בנגעים אע\\\"פ שהוא פתוח מד' צדדין:\",7,0],[8,376,14,7,\"כמה אבנים יהיו בו וכו'. שם וכר\\\"ע מחבירו:\",1,0],[8,376,14,7,\"וכמה עצים יהיו בו וכו'. שם וכת\\\"ק:\",2,0],[8,376,14,8,\"הלבינים והשיש וכו'. נלמד ממה שיבוא בסמוך:\",1,0],[8,376,14,8,\"בית שאחד מצידיו וכו' עד טהור. בפרק י\\\"ב ובמקום מ\\\"ש בספרי רבינו ואחד באבנים כתוב במשנה ובת\\\"כ ואחד בלבנים וכ\\\"נ להגיה בספרי רבינו וכן מוכיח תחלת לשונו שכתב הלבנים והשיש:\",2,0],[8,376,14,9,\"ומ\\\"ש בספרי רבינו בית שלא היו בו לבנים וכו'. ט\\\"ס הוא וצריך לכתוב אבנים במקום לבנים. וכתב הראב\\\"ד ונראה בו נגע א\\\"א זה המאסף תפס לשון המשנה ולא דקדק במה שאמרו וכו' אבל נ\\\"ל דלענין טומאת הבית וכו'. אפריון נמטייה למרן דהוא מותיב לה והוא מפרק לה דלענין טומאת הבית אע\\\"פ שלא היו בשעת בניין ולא הוזכרו אלא לענין נתיצה וכו' אלא דאיכא למתמה עליה למה פתח בתמיה רבה כיון דאיכא לשנויי כדשני ואפשר דמשום דאכתי איכא למיתמה עלה למה השמיטו:\",1,0],[8,376,14,10,\"בית שסיככו בזרעים וכו'. בפ' העור והרוטב עלה קכ\\\"ט אמר רב מתנא הרי אמרו בית שסיככו בזרעים טהרו טומאתו לאו דאורייתא דאי סלקא דעתך דאורייתא מצינו לזרעים שמטמאין טומאה חמורה כששימש מעשה עץ שימש ופירש רש\\\"י הרי אמרו וכו' דבית המסוכך בזרעים דהוי בית וכו' כגון שסיכך ביתו בשבולים ובהם הזרעים וכיון שעשה מהם סכך ביטל הזרעים ונעשה אהל חשוב ואם פרחה צרעת באותו בית הרי כל הבית כתליו ואהל שלו לטמא אדם וכלים:\",1,0],[8,376,14,11,\"ירושלים וח״ל וכו'. בפי״ב ובס״פ מרובה (בבא קמא דף פ״ב ע״ב) ופ״ק דיומא (דף י״ב) ופרק בני העיר (מגילה דף כ״ו).\",1,0],[8,376,14,11,\"ומ\\\"ש ובתי עכו\\\"ם. נלמד ממה שיבא בסמוך ודייק לכתוב שבארץ ישראל דאילו שבחוצה לארץ אפילו של ישראל אינם מטמאין:\",2,0],[8,376,14,12,\"הלוקח בתים מן העכו\\\"ם וכו'. בפרק י\\\"ב ומייתי לה מקרא בת\\\"כ:\",1,0],[8,376,14,13,\"בית שצדו אחד עכו\\\"ם וכו'. תוספתא פרק ו'.\",1,0],[8,376,14,13,\"ומ\\\"ש ושאר כל הבתים כו' עד בין צבועים בידי שמים. בפי\\\"א:\",2,0],[8,376,14,14,\"בית האשה וכו'. בפרק קמא דיומא עלה י\\\"א ע\\\"ב תניא בית הכנסת ובית השותפין ובית האשה מיטמאין בנגעים פשיטא מהו דתימא ובא אשר לו הבית לו ולא לה לו ולא להם קמ\\\"ל ואימא ה\\\"נ אמר קרא בבית ארץ אחוזתכם וכו' ובית הכנסת מי מטמא בנגעים וכו' ת\\\"ל ובא אשר לו הבית מי שמיוחד לו יצאו אלו שאין מיוחדין לו ל\\\"ק הא רבי מאיר והא רבנן וכו' ול\\\"ק הא דאית בה בית דירה הא דלית בה בית דירה ואיבעית אימא הא והא דלית בה בית דירה והא דכרכים והא דכפרים ומקשה על שינויא בתרא ומסיק אלא מחוורתא כדשנינן מעיקרא דאית ביה בית דירה:\",1,0],[8,376,14,15,\"קירות האבוס וקירות המחיצה שבבית וכו'. בפי\\\"ב ופירש רבינו שמשון קירות המחיצה של חצרות גנות ופרדסים ורבינו פירש קירות המחיצה הוא תקרה שלא נעשה לדירה אמנם נעשה להיות צל לאשר תחתיו מבהמות מהשמש ואיצטריך אפילו שהם בבית שאם בא הנגע בכותלי הבית מטמא ובכותל האבוס והמחיצה אשר שם אין מטמא וקרא בבית כתיב וז\\\"ש רבינו שבבית:\",1,0],[8,376,15,1,\"נגעי בתים יש בהם הסגר שלשה שבועות שהם י\\\"ט יום. בפרק שלישי דנגעים:\",1,0],[8,376,15,2,\"ומה שכתב ואפילו מצאו כולו בתחלה ירקרק או אדמדם וכו'. יליף מנגעי בגדים.\",1,0],[8,376,15,2,\"ומה שכתב ובשביעי רואהו אם כהה הנגע וכו'. בריש פרק י\\\"ג הכוהה בראשון וההולך לו קולפו והוא טהור הפושה בראשון חולץ וקוצה וטח ונותן לו שבוע חזר ינתץ לא חזר טעון צפרים עמד בראשון ופשה בשני חולץ וקוצה וטח ונותן לו שבוע חזר ינתץ לא חזר טעון צפרים עמד בזה ובזה חולץ וקוצה וטח ונותן לו שבוע חזר ינתץ לא חזר טעון צפרים אם עד שלא טיהרו בצפרים נראה בו נגע הרי זה ינתץ ואם משיטהרו בצפרים נראה בו נגע יראה בתחלה ובתורת כהנים מייתי לה מקרא:\",2,0],[8,376,15,3,\"כשהוא חולץ את האבנים וכו'. בפרק י\\\"ב ובתורת כהנים מייתי לה מקראי ולקחו אבנים אחרות משמע ולא אבנים מצד זה לצד זה עפר ולא סיד וגפסיס ולקחו אבנים אין פחות משתי אבנים ונתנו אל תחת האבנים אין פחות משתי אבנים מכאן אמרו אין חולצין פחות משתי אבנים ולא מביאים פחות משתים ואין מביא אחת תחת שתים ולא שתים תחת אחת אלא מביא שתים תחת ג' וג' תחת ד' וד' תחת ג' ותחת שתים פי' דלא קפדינן אלא שיהיו רבים תחת רבים דהיינו אבנים תחת אבנים ומיעוט רבים שתים ורבינו לא חש אלא להעתיק לשון המשנה:\",1,0],[8,376,15,4,\"היה הכותל בינו לבין חבירו וכו'. בפרק הנזכר:\",1,0],[8,376,15,5,\"אבן שבזוית וכו'. בפרק י\\\"ג פירוש אבן שבזוית אבן שבינו ובין חבירו וטעמא משום דכתיב וחלצו ובנתיצה ונתץ לשון יחיד וכתיב נמי אבניו.\",1,0],[8,376,15,5,\"ומה שכתב ויש בדבר ספק וכו'. בפרק העור והרוטב (חולין דף קכ\\\"ח) בעיא דלא איפשיטא:\",2,0],[8,376,15,6,\"בית שנראה בו נגע וכו'. בפי\\\"ג:\",1,0],[8,376,15,7,\"הלוקח אבנים וכו'. שם:\",1,0],[8,376,15,8,\"כיצד מטהרים את הבית. מפורש בתורה.\",1,0],[8,376,15,8,\"ומה שכתב שמזה על המשקוף של בית מבחוץ. ריש פרק י\\\"ד:\",2,0],[8,376,16,1,\"בית המנוגע אב מאבות הטומאות וכו'. ומ\\\"ש וכל הנוגע בו יטמא. בפי\\\"ג.\",1,0],[8,376,16,1,\"ומ\\\"ש וכל כזית מהם מטמא במגע ובמשא. בפרק י\\\"ג אבניו ועציו ועפרו מטמאין בכזית.\",2,0],[8,376,16,1,\"ומ\\\"ש שהם מטמאין במגע ובמשא. בתוספתא פ\\\"ו.\",3,0],[8,376,16,1,\"ומ\\\"ש שמטמא בביאה. בפי\\\"ג מפורש שאבן אחת ממנו מטמא בביאה.\",4,0],[8,376,16,1,\"ומה שכתב וכולן אסורין בהנאה. בצרעת בגדים כתיב צרעת ממארת ודרשו בתורת כהנים תן בו מארה ואל תהנה בו וא\\\"כ הוא הדין לבתים דגם בהם כתיב צרעת ממארת.\",5,0],[8,376,16,1,\"ומ\\\"ש ואם שרפן וכו'. ומ\\\"ש וכולן משלחין אותה חוץ לעיר אע\\\"פ שאינה מוקפת חומה. בתורת כהנים:\",6,0],[8,376,16,2,\"בית מוסגר אינו מטמא אלא מתוכו וכו' אבל המוחלט מטמא מתוכו ומאחריו. בפי\\\"ג שם.\",1,0],[8,376,16,2,\"ומ\\\"ש שנאמר צרעת ממארת וכו' וכי טהור היה וכו'. בתורת כהנים.\",2,0],[8,376,16,2,\"ומ\\\"ש וכן אבנים שיש בהם הנגע. תוספתא פ\\\"ז:\",3,0],[8,376,16,3,\"אחד המוסגר ואחד המוחלט וכו'. [בפי\\\"ג] וכר\\\"א דיליף לה בקל וחומר.\",1,0],[8,376,16,3,\"ומה שכתב וכן אבן המנוגעת וכו' עד ואם הניחה שם טמאהו. בפרק י\\\"ג:\",2,0],[8,376,16,4,\"המאהיל בידו על אבן וכו'. בתוספתא פ\\\"ז:\",1,0],[8,376,16,5,\"טהור שנכנס המנוגע וכו'. בפי\\\"ג.\",1,0],[8,376,16,5,\"ומ\\\"ש שנאמר והשוכב בבית וכו'. בתורת כהנים:\",2,0],[8,376,16,7,\"מי שנכנס לבית המנוגע וכו'. בפרק י\\\"ג:\",1,0],[8,376,16,7,\"וכן העכו\\\"ם והבהמה וכו'. תוספתא פ\\\"ז ובתורת כהנים:\",2,0],[8,376,16,8,\"מי שהיה עומד בבית המנוגע וכו'. בפרק י\\\"ג:\",1,0],[8,376,16,8,\"ומ\\\"ש וכן העומד בחוץ ופשט ידיו וכו'. ג\\\"ז שם וכת\\\"ק:\",2,0],[8,376,16,9,\"כל המציל בצמיד פתיל באהל המת מציל וכו'. שם וכר\\\"י לגבי ר\\\"מ:\",1,0],[8,376,16,10,\"הצרעת הוא שם האמור בשותפות וכו'. שהמספר בלשון הרע משתנות קירות ביתו וכו'. דברי רבינו ראויים אליו ז\\\"ל:\",1,0],[8,376,16,10,\"נשלמו הלכות טומאת צרעת\",2,0],[8,377,1,1,\"הזב והזבה והנדה והיולדת וכו'. בפירקא קמא דכלים מני להו באבות הטומאה:\",1,0],[8,377,1,1,\"ומה שכתב מטמאים כלים במגע. דכתיב וכלי חרס אשר יגע בו הזב ישבר וכל כלי עץ ישטף במים.\",2,0],[8,377,1,1,\"ומה שכתב ומטמא אדם במגע ובמשא. דכתיב הנוגע בבשר הזב יכבס בגדיו ורחץ במים וטמא עד הערב וכתיב והנושא אותם יכבס בגדיו ורחץ במים וכו' ובפרק חמישי דזבים תנן הנוגע בזב ובזבה בנדה וביולדת וכו' מטמא שנים ופוסל אחד וכו' אחד הנוגע ואחד המסיט אחד הנושא ואחד הנישא ותניא בתורת כהנים והדוה בנדתה והזב את זובו מה הזב מטמא במשא אף הזוב מטמא במשא לזכר לרבות את המצורע ולנקבה לרבות היולדת.\",3,0],[8,377,1,1,\"ומה שכתב ומטמא משכב ומושב ומרכב מתחתיו. דכתיב כל המשכב אשר ישכב עליו הזב יטמא וכל הכלי אשר ישב עליו יטמא וכל המרכב אשר ירכב עליו הזב יטמא.\",4,0],[8,377,1,1,\"ומה שכתב ומטמא מדף על גבו. פרק ד' דזבים ופרק ו' דעדיות (משנה ב') ובתורת כהנים:\",5,0],[8,377,1,2,\"אחד זבה קטנה וכו'. בת\\\"כ יליף לה מקרא.\",1,0],[8,377,1,2,\"ומ״ש או מחמת אונס. בת״כ ובפרק בנות כותים (נדה דף ל״ב ע״ב) יליף לה מקרא.\",2,0],[8,377,1,2,\"ומ\\\"ש ואחד בעל ב' ראיות וכו'. בפ\\\"ק דמגילה (דף ח') משנה וגמרא:\",3,0],[8,377,1,3,\"קטנה בת יום אחד וכו'. משנה פרק יוצא דופן (נדה דף מ\\\"ג ע\\\"ב ומ\\\"ד ע\\\"ב):\",1,0],[8,377,1,4,\"קטן בן יום אחד מטמא בזיבה. שם (דף מ״ג ע״ב) ובר״פ בנות כותים (נדה דף ל״ג):\",1,0],[8,377,1,4,\"ואחד גרים ועבדים. רפ\\\"ב דזבים הכל מיטמאין בזיבה אף הגרים אף העבדים בין משוחררים בין שאינם משוחררים.\",2,0],[8,377,1,4,\"ומ\\\"ש שמטמאין בנדה:\",3,0],[8,377,1,5,\"סריס אדם וסריס חמה מטמאין בזיבה וכו'. רפ\\\"ב דזבים:\",1,0],[8,377,1,6,\"אין האשה מטמאה בלובן ולא האיש באודם וכו'. בריש פרק בנות כותים (נדה דף ל״ב ע״ב) ובפרק כל היד:\",1,0],[8,377,1,7,\"טומטום ואנדרוגינוס וכו'. רפ\\\"ב דזבים.\",1,0],[8,377,1,7,\"ומ\\\"ש לפיכך אין שורפין עליהם תרומה וקדשים ואין חייבים עליהם על טומאת המקדש. שם וטומאתן בספק ומבואר בתוספתא בפ\\\"ב דזבים:\",2,0],[8,377,1,7,\"ראה לובן ואודם כאחד וכו'. שם ובפרק המפלת עלה כ\\\"ח ויליף לה מקרא.\",3,0],[8,377,1,7,\"ומ\\\"ש וכן הנוגע בלובן ואודם שלו כאחד וכו'. שם בתוספתא:\",4,0],[8,377,1,7,\"ומ\\\"ש הוא עצמו שנגע בלובן ואודם וכו'. שם הוא עצמו שנגע בלובן ואודם ונכנס למקדש פטור וגירסא משובשת היא וצריך להגיה חייב:\",5,0],[8,377,1,7,\"וכתב הראב\\\"ד בלובן ואודם שראה א\\\"א אולי טעה בלשון התוספתא וחילק וכו'. ואין דברים אלו כדאי לכתוב שטעה טעות גדולה או קטנה שהרי אפשר לפרש התוספתא בנגע בשלו אבל אי קשיא הא קשיא מ\\\"ש נגע הוא מנגעו אחרים דכיון דבנגעו אחרים אינם חייבים על ביאת המקדש משום דבעינן שתהא טומאת זכר ודאי או טומאת נקבה ודאית מאותו טעם בעצמו יש לפטור בשנגע הוא בעצמו ויש לדחוק ולפרש לשון רבינו כפירוש הראב\\\"ד דבנגעו טומטום ואנדרוגינוס בשל אחרים מיירי אלא שלשון שראה שכתב רבינו קשה לזה:\",6,0],[8,377,1,8,\"דם הנדה או דם הזבה וכו'. משנה פרק יוצא דופן (נדה דף מ״ג ע״ב).\",1,0],[8,377,1,8,\"ומ״ש במגע ובמשא. בריש פרק דם הנדה (נדה דף נ״ד ע״ב) מנא ה״מ דדם הנדה מטמא אמר חזקיה דאמר קרא והדוה בנדתה מדוה כמותה מה היא מטמאה אף מדוה מטמא:\",2,0],[8,377,1,8,\"וכבר ביארנו בענין איסור נדה וכו'. בפ\\\"ה מהא\\\"ב.\",3,0],[8,377,1,8,\"ומ״ש אבל אם ראתה דם ירוק הרי הוא טהור וכו'. משנה פ' כל היד (נדה דף י״ט) וכחכמים.\",4,0],[8,377,1,8,\"ומ\\\"ש שהרוק מתעגל ויוצא. שם בגמרא:\",5,0],[8,377,1,9,\"אשה שיצא הולד מדפנה וכו'. בר״פ יוצא דופן (נדה דף מ״א:) אמרינן דביוצא ולד ודם דרך דופן ר״ש מטהר וחכמים מטמאים ובמקור מקומו טמא פליגי מר סבר מקור מקומו טמא ומר סבר מקור מקומו טהור ופירש״י רבנן סברי טיפה עצמה מטמא במגע משום דנגעה במקור ומקור מקומו טמא ואיתמר עלה אמר ריש לקיש לדברי המטמא בדם מטמא באשה לדברי המטהר בדם מטהר באשה רבי יוחנן אמר אף לדברי המטמא בדם מטהר באשה ויליף ר״י מקרא שאין אשה טמאה עד שיצא מדוה דרך ערותה וידוע דהלכה כר״י:\",1,0],[8,377,1,10,\"מקור האשה שנעקר וכו'. שם מקור שנעקר ונפל לארץ טמאה וכו' למאי אילימא לטומאת שבעה דם אמר רחמנא ולא חתיכה אלא לטומאת ערב ופירש\\\"י שנעקר חתיכת בשר:\",1,0],[8,377,1,10,\"וכן מקור שהזיע כשתי טיפי מרגליות וכו'. שם אמר ר\\\"י מקור שהזיע כשתי טיפי מרגליות טמאה למאי אילימא לטומאת שבעה ה' דמים טמאים באשה ותו לא אלא לטומאת ערב ודוקא תרתי אבל חדא אימא מעלמא אתיא. ופירש\\\"י טיפי מרגליות דם לבן וצלול. לטומאת ערב מפני שנגע במקור ונוגע בה. מעלמא מן הצדדין:\",2,0],[8,377,1,12,\"זובו של זב מאבות הטומאות וכו' ומטמא במגע ובמשא. פ״ק דכלים ובפרק דם הנדה (נדה דף נ״ד ע״ב) יליף לה מקרא.\",1,0],[8,377,1,12,\"ומ״ש בכל שהוא. משנה ר״פ יוצא דופן (נדה דף מ'):\",2,0],[8,377,1,12,\"ראיה ראשונה של זב וכו'. בריש זבים וכב\\\"ה.\",3,0],[8,377,1,12,\"ומ״ש בין מאיש קטן. בפרק בנות כותים (נדה דף ל״ב ע״ב) בעיא דאיפשיטא והיינו למגע אבל למשא לא מטמא אלא בשתי ראיות דאז מקרי זב אבל בראיה אחת לא מיקרי זב כמו שלמדו שם מהכתובים.\",4,0],[8,377,1,12,\"ועל מ\\\"ש רבינו בין מאיש גדול בין מאיש קטן, כתב הראב\\\"ד א\\\"א אין לשונו מיושר. טעמו לומר שעל מ\\\"ש והרי היא כש\\\"ז לא יצדק לומר בין מאיש קטן אבל טומאת ראיה ראשונה של זב בקטן אינו אלא מטעם שהיא תחלת זוב והכתוב הקיש בזב קטן לגדול כמו שמפורש בפרק בנות כותים עלה ל\\\"ד ורבינו גם כן לכך נתכוון.\",5,0],[8,377,1,12,\"ומ\\\"ש וכן המשכבות והמושבות וכו'. בסוף נדה (עב:) ובתוספתא דזבים פרק קמא וכבית הלל:\",6,0],[8,377,1,12,\"ראה אחת מרובה כשתים וכו'. בתוספתא דזבים וכב\\\"ה:\",7,0],[8,377,1,13,\"ראיה ראשונה של מצורע וכו'. בפרק בנות כותים עלה ל\\\"ד ל\\\"ה וכדאסיק אביי:\",1,0],[8,377,1,14,\"רוק הזב ושכבת וכו'. בפ״ק דכלים זובו של זב ורוקו ושכבת זרעו ומימי רגליו וכו' מטמאים במגע ובמשא ובר״פ דם הנדה (נדה דף נ״ה ע״ב) יליף רוקו מדכתיב וכי ירוק הזב בטהור ומרבי ליה בין לטומאת מגע בין לטומאת משא ומימי רגליו מייתי לה (דף נ״ו) מדתניא זובו טמא וזאת לרבות מימי רגליו ושכבת זרעו מייתי לה בס״פ כיצד הרגל (דף כ״ה) מק״ו ור' יהושע נתן טעם לש״ז דמטמא אף במשא משום דא״א בלא צחצוצי זיבה כל שהוא ומשמע לרבינו דה״ה למימי רגליו וכתב רבינו טעם זה שהוא יותר פשוט וקצר. ומ״כ מאי דמטמא מימי רגליו מהאי טעמא ק״ל דבנדה יליף מוזאת ואפשר לתרץ דגמרא יליף מוזאת לומר דאפילו ר״א דמטהר ממשא לש״ז דסבירא ליה כיון דכתיבא ביה ש״ז לא מטמאה הכא מודה מרבויא דוזאת אבל לדידן דקי״ל כר' יהושע דא״א וכו' ה״ה למימי רגליו וראיה לדבר דאמרינן בתורת כהנים זאת תורת הזב מה הזב וכו' ומייתי לה בנדה (דף כ״ב) ובתר הכי בת״כ יכול אף מימי רגלים יהו סותרים וכו' ומהי תיתי שיהו סותרים והא ש״ז גופא לא סתרא אלא משום צחצוחי זיבה אלא ודאי משום דמימי רגליו נמי אי אפשר בלא צחצוחי זיבה קאמר הכי. וממ״ש רבינו פ״ק דכלים נראה דתרוייהו נפקי מוזאת ויהיב רבינו טעמא מאי שנא דמרבינן הני טפי מאחריני משום דא״א להו בלא צחצוחי זיבה. ואפשר שלזה נתכוון רבינו כאן עכ״ל:\",1,0],[8,377,1,15,\"אחד זב ואחד נדה ויולדת וזבה וכו':\",1,0],[8,377,1,16,\"תשעה משקין בזב וכו'. בריש פרק דם הנדה (נדה דף נ״ה ע״ב) ובת״כ.\",1,0],[8,377,1,16,\"ומה שכתוב בספרי\",2,0],[8,377,1,16,\"רבינו כמותו טעות סופר הוא וצריך להגיה ולכתוב כמותן ובזה יבא לשונו דבור על אפניו הרי אלו שלשה מן הזב וחביריו כמותן משאר האדם כלומר כשם ששלשה אלו טהורים משאר האדם כך הם טהורים כשהם מהזב וחביריו הנזכר בראש הפרק.\",3,0],[8,377,1,16,\"ועל מה שכתב רבינו כל אחד מאלו כמשקין טמאים שאין מטמאין אדם כתב הראב\\\"ד א\\\"א אף בזה טעה וכו'. מ\\\"ש משמעתא קמייתא דאלו דברים דמסכת ברכות (דף נ\\\"א ע\\\"ב) היינו לומר דגבי מוזגין את הכוס ואחר כך נוטלין לידים משמע דבכל שהוא מטמו כלי וידים כי אין רגילות להיות נדבק רביעית בידים ולא בכלי ואני אומר שמאחר שדבריו יכולים להתפרש דלא מיירי אלא לענין מגע אין כאן טעות:\",4,0],[8,377,1,16,\"כיחו וניעו ומי האף וכו'. בריש פרק דם הנדה (נדה דף נ״ה ע״ב).\",5,0],[8,377,1,16,\"ומ\\\"ש ורירו. בתוספתא פרק בתרא דזבים.\",6,0],[8,377,1,16,\"ומ\\\"ש ובכלל הרוק הן חשובים, כלומר ומשום הכי לא מנה אלא ג' דאל\\\"כ שבעה מיבעי ליה:\",7,0],[8,377,1,16,\"דם היוצא מפי האמה וכו'. שם (בנדה דף נ\\\"ו) זובו טמא הוא [הוא טמא] ואין דם היוצא מפיו ומפי האמה טמא ומשמע דהיינו ודאי לענין שלא יטמא כזב אבל מטמאין כמשקין טמאין וכן מפורש בתוספתא דזבים פרק אחרון:\",8,0],[8,377,1,16,\"ומ\\\"ש היה מוצץ ורוקק דם וכו'. בפרק מצות חליצה עלה ק\\\"ה יבמה שרקקה [דם] תחלוץ לפי שא\\\"א לדם בלא צחצוחי רוק מיתיבי יכול יהא דם היוצא מפיו ומפי האמה טמא ת\\\"ל זובו הוא זובו טמא ואין דם היוצא מפיו ומפי האמה טמא ל\\\"ק כאן במוצצת כאן בשותת:\",9,0],[8,377,2,1,\"דם הנדה וכו'. אינו מטמא אלא כל זמן שהוא לח וכו'. ריש פרק דם הנדה (נדה דף נ״ד ע״ב) ויליף לה מקראי.\",1,0],[8,377,2,1,\"ומה שכתב ואם היו המים הפושרין בתחלתן וכו'. שם פלוגתא דתנאי ופסק לחומרא בדאורייתא:\",2,0],[8,377,2,1,\"וכתב הראב\\\"ד אם שורין אותו א\\\"א נ\\\"ל דלא בעינן מעת לעת אלא לשרץ ונבילה עכ\\\"ל. טעמו משום דבאינך שהם דברים רכים בשרייה כל דהו סגי להו אבל מפשט דברי המשנה משמע כדברי רבינו וכך הוא דעת התוספות:\",3,0],[8,377,2,2,\"פשתן שטוואתו נדה וכו'. פרק התערובות עלה ע\\\"ט:\",1,0],[8,377,2,3,\"זב שהניח פיו על פי הכוס עד כשהן נדות. תוספתא פ\\\"ה דטהרות אלא שבנוסחא דידן כתוב במי רגלים או ביין אין רואים אותם כאילו הם מים ונ\\\"ל שט\\\"ס הוא:\",1,0],[8,377,2,4,\"כתב הראב\\\"ד זב שנשך את הפת ואת הבצל המסיטן טהור א\\\"א מצאתי בשתי נסחאות טמא בשתיהם ומה שחילקן וכו'. ונוסחת רבינו נכונה שאין עליה תשובה לומר למה חילקן ולא עירבן ורבינו שמשון הביא תוספתא זו בפרק רביעי וגירסתו כגירסת רבינו:\",1,0],[8,377,2,7,\"ומ\\\"ש רבינו שואלים כלי מי רגלים. רבינו לא גריס כלי וכן נמצא בספר רבינו כתיבת יד דל\\\"ג כלי:\",1,0],[8,377,2,8,\"חרס שהיה הזב וכו'. ג\\\"ז שם בתוספתא וכראב\\\"י ובפרק התערובות עלה ע\\\"ט:\",1,0],[8,377,2,9,\"זבה שנעקרו מימי רגליה. בפרק יוצא דופן (נדה דף מ\\\"ב) בעיא דלא איפשיטא ואף על גב דאמר רבה בבעיא בתרייתא את\\\"ל לא פסק רבינו כן משום דגמרא אמר תיקו בהאי בעיא דזבה.\",1,0],[8,377,2,9,\"ומה שכתב וכן עכו\\\"ם שנעקרו מימי רגליה וכו'. גם זה שם בעיא דלא איפשיטא:\",2,0],[8,377,2,10,\"העבדים מטמאים בזיבה ובנדה וכו'. ברפ\\\"ב דזבים תנן דעבדים אפילו שאינם משוחררים מטמאים בזיבה.\",1,0],[8,377,2,10,\"ומ\\\"ש אבל העכו\\\"ם אין מטמאים וכו' וחכמים גזרו וכו'. בפרק בנות כותים עלה ל\\\"ד.\",2,0],[8,377,2,10,\"ומ\\\"ש זכרים ונקבות. שם אמרינן דב\\\"ש מפלגי בין זכרים לנקבות וב\\\"ה לא מפלגי.\",3,0],[8,377,2,10,\"ומ\\\"ש והוא שיהיה הזכר בן ט' שנים ויום אחד ולמעלה והנקבה בת ג' שנים ויום אחד ולמעלה. פ\\\"ב דע\\\"ז (דף ל\\\"ז) במסקנא:\",4,0],[8,377,2,10,\"בעת שגזרו עליהם לא גזרו על שכבת זרע שלהם כו'. בפרק בנות כותים (נדה דף ל״ד):\",5,0],[8,377,2,10,\"נמצאת למד. ודם הנכרית כרוקה וכמימי רגליה וכו'. בפרק בנות כותים וכבית הלל:\",6,0],[8,377,3,1,\"בועל נדה כנדה. מבואר בתורה ואם שכוב ישכב איש אותה ותהי נדתה עליו.\",1,0],[8,377,3,1,\"ומה שכתב ומטמא אדם במשא וכו'. כן משמע בפירקא קמא דכלים דתנן למעלה מהם בועל נדה משמע שיש בהם כל החומרות שהוזכרו בקודמין כן נראה שהוא דעת רבינו:\",2,0],[8,377,3,2,\"אין משכב בועל נדה ומרכבו וכו'. בפ״ק דכלים למעלה מהם בועל נדה שהוא מטמא משכב תחתון כעליון ובריש פרק בנות כותים (נדה דף ל״ב ל״ג) דהיינו לומר דאי איכא עשר מצעות זו על זו שיהיה תחתונו של בועל נדה כעליונו של זב שאינו מטמא אלא אוכלים ומשקים ולא אדם וכלים.\",1,0],[8,377,3,2,\"ומה שכתב ולמה נגרעה טומאת משכבו וכו'. שם ובתורת כהנים:\",2,0],[8,377,3,3,\"אחד הבא על הנדה או על וכו'. בסוף נדה (דף ע\\\"ב).\",1,0],[8,377,3,3,\"ומה שכתב אחד המערה ואחד הגומר. משנה פרק הבא על יבמתו (יבמות דף נ״ג ע״ב) ובתורת כהנים פרשת מצורע.\",2,0],[8,377,3,3,\"ומה שכתב בין גדול שבא על הקטנה וכו'. במה דברים אמורים כשהיה הבועל בן תשע שנים ויום אחד והנבעלת היתה בת שלש שנים ויום אחד וכו'. פרק יוצא דופן (נדה דף מ״ד מ״ה).\",3,0],[8,377,3,3,\"ומה שכתב וכן בועל הזב וכו'. בסוף נדה (דף ע\\\"ג).\",4,0],[8,377,3,3,\"ומה שכתב ואחד הנוגע בזב או הנבעלת מן הזב. נדה שם:\",5,0],[8,377,3,4,\"הנדה והזבה כו' כולן מטמאות למפרע מעת לעת וכו'. בריש נדה וכחכמים דשקלי וטרו אמוראי לפרושי מילתייהו ופרט רבינו את אלו מפני שבפרק יוצא דופן (נדה דף מ״ב) פרטום שהרי על כל הנשים אמרו בריש נדה. ואפשר דלרבותא נקט הני וכ״ש אחרות והני בכלל דקתני מתני' הן.\",1,0],[8,377,3,4,\"ומ\\\"ש ועד שלאחר התשמיש הרי היא כפקידה ושלפני תשמיש אינו כפקידה וכו'. שם עלה ה' אמר רב יהודה אמר שמואל עד שלפני תשמיש אינו [ממעט] כפקידה מ\\\"ט א\\\"ר קטינא וכו' מתוך שמהומה לביתה אינה מכנסת לחורין ולסדקין:\",2,0],[8,377,3,5,\"אשה שיש לה וסת וכו'. משנה שם:\",1,0],[8,377,3,5,\"הגיע שעת וסתה ולא בדקה עצמה וכו'. משנה פרק בנות כותים (נדה דף ל״ט).\",2,0],[8,377,3,5,\"ומ\\\"ש ואם מצאה עצמה טהורה וכו'. שם פלוגתא דרב ושמואל וידוע דהלכה כרב באיסורי:\",3,0],[8,377,3,6,\"כל אשה שיש לה וסת וכו'. משנה בנדה פרק האשה (דף ס\\\"ג).\",1,0],[8,377,3,6,\"ומה שכתב היתה למודה להיות רואה בתחלת הוסת וכו' עד עת שמצאה דם. נדה שם:\",2,0],[8,377,3,7,\"הרואה כתם וכו'. פרק קמא דנדה (דף ה') כל הנשים כתמן טמא למפרע ונשים שאמרו חכמים דיין שעתן כתמן כראייתן וכתב רבינו עד עת הפקידה אפילו הוי טפי ממעת לעת ואם כן הוא חמור יותר מראייתה דאילו בראייתה תופס הזמן המועט כמו שנתבאר וכאן תולה בפקידה דוקא דומיא דבגד דהוי טמא למפרע אפילו ימים רבים עד שעת בדיקה:\",1,0],[8,377,3,7,\"וכתב הר\\\"י קורקוס ז\\\"ל וטעם יש בדבר דאילו רואה עתה אין טעם להחמיר עליה למפרע ביותר ממעת לעת אמנם כתם שאינה יודעת מתי יצא דם זה מגופה יש להחמיר ולומר דסמוך לפקידה יצא עכ\\\"ל.\",2,0],[8,377,3,7,\"ומה שכתב וכן הבגד שנמצא עליו כתם וכו'. בפרק דם הנדה (נדה דף נ״ו ע״ב):\",3,0],[8,377,3,7,\"ומה שכתב אפילו כבסתו ולא בדקתו וכו'. שם אסיקנא דעד שעת כיבוס חזקתו בדוק ומשמע דהיינו דוקא בסתמא אבל אם אומרת שהיא יודעת שלא בדקתו טמא.\",4,0],[8,377,3,7,\"ומה שכתב ואפילו נמצא הכתם לח. שם במשנה (דף נ\\\"ז ע\\\"ב):\",5,0],[8,377,3,8,\"וכל הנשים שדיין שעתן וכו'. בפירקא קמא דנדה עלה ה' פלוגתא דתנאי ופסק כרבי חנינא בן אנטיגנוס לגבי רבי מאיר משום דרבי מאיר מחמיר בכתם מבראייתה ובסוף פרק הרואה כתם (נדה דף נ״ח ע״ב) תנן דאמר רבי עקיבא שלא אמרו חכמים בכתמים להחמיר אלא להקל.\",1,0],[8,377,3,8,\"ומה שכתב כל אלו הנשים הטמאות למפרע וכו'. שם (דף ה') לא פליג ר' חנינא בן אנטיגנוס אלא בנשים שדיין שעתן אבל בשאר נשים מודה שכתמן כראייתן ותניא תו התם (דף ו') הרואה דם מטמאה מעת לעת ומה היא מטמאה משכבות ומושבות אוכלים ומשקים וכלי חרס המוקפים צמיד פתיל ואינה מטמאה את בועלה למפרע וכו' הרואה כתם מטמאה למפרע ומה היא מטמאה אוכלין ומשקין משכבות ומושבות וכלי חרס המוקף צמיד פתיל וכו' ומטמאה את בועלה ומסיק התם דמעת לעת שבנדה עושה משכב ומושב לטמא אדם לטמא בגדים.\",2,0],[8,377,3,8,\"ומה שכתב וכן רוקן ומימי רגליהם טמאים למפרע. נראה דיליף לה בקל וחומר מכלי חרס המוקף צמיד פתיל.\",3,0],[8,377,3,8,\"ומה שכתב אבל אינה מטמאה את הבועל למפרע משום בועל נדה אלא משום נוגע בלבד. בפרק כל היד עלה ט\\\"ו כששהתה מעת לעת ומפקידה לפקידה בעלה מטמא משום מגע ואינו מטמא משום בועל ופירש רש\\\"י מטמא משום נוגע [במעת לעת בנדה] טומאת ערב בספק דרבנן לתלות ואינו מטמא משום בועל לטמא טומאת ז' ואפילו לתלות.\",4,0],[8,377,3,8,\"ומה שכתב אבל הרואה כתם הבועל אותה וכו'. שם במשנה (דף י\\\"ד) מודים חכמים לרבי עקיבא ברואה כתם שהיא מטמאה את בועלה ואמרינן בגמרא (דף ט\\\"ו) דמכאן ולהבא דוקא קתני דמטמאה את בועלה לרבנן דהלכתא כוותייהו:\",5,0],[8,377,3,8,\"ומה שכתב רבינו אבל הרואה כתם הבועל אותה וכו'. לשון אבל אינו נוח לי ונמצא בספר כתיבת יד כתוב וכל במקום אבל והיא הגירסא הנכונה:\",6,0],[8,377,3,9,\"מעוברת שהוציא העובר את ידו והחזירה וכו'. בפרק המפלת (נדה דף כ״ח) ומסיק דלחומרא הוא דקאמר רב הונא ומדרבנן אבל ימי טוהר אין נותנין לה דלאו לידה היא עד שיצא רובו וזה שכתב רבינו טומאת יולדת (י״ד) וכו' מדברי סופרים:\",1,0],[8,377,3,9,\"וטומאת מעת לעת או מפקידה לפקידה. בפרק כל היד (נדה דף ט״ו) אמרו מעת לעת דרבנן:\",2,0],[8,377,3,9,\"וטומאת וסתות. בפרק כל היד פסקו התוספות דווסתות דרבנן דר״נ דהוא בתרא מוקי התם (דף י״ו) פלוגתא דרב ושמואל בהכי ולרב הוו דרבנן וקיימא לן כרב באיסורי וכן יש שם מחלוקת רבי אליעזר ורבי יהושע בזה ורבי יהושע סבר דהוי דרבנן וכן יש מחלוקת חכמים ורבי מאיר בזה וחכמים סברי דהוו דרבנן וכ״פ בשאלתות וכ״פ ר״ח. וטומאת כתמים בפרק כל היד ובפרק הרואה כתם (נדה דף נ״ז נ״ח) אמרו שהיא מדרבנן:\",3,0],[8,377,3,9,\"ומ\\\"ש לפיכך אין שורפין עליהם וכו'. ברייתא פירקא קמא דנדה (דף ו').\",4,0],[8,377,3,9,\"ומ\\\"ש וכן חולין שנעשו על טהרת הקדש וכו'. גבי מעת לעת שבנדה איכא תרי לישני התם ופסק כלישנא בתרא ואע\\\"ג שהוא להחמיר בדרבנן משום דאלישנא קמא פרכינן פירכי טובא ושני להו בשינויי דחיקי ועוד כי בסוף הסוגיא (דף ז') הקשו על חולין הטבולים לחלה שאמרו שם דחמירי וגזרו בהו טומאה והא מעת לעת שבנדה שלא גזרו בה דאמר מר קבלה מיניה רב שמואל בחולין שנעשו על טהרת הקדש ולא בחולין שנעשו על טהרתן תרומה משמע דהכי קי\\\"ל כיון דפריך מינה בסתמא ומשני התם דלא דמו דהתם אין תרומה מעורבת בהם אבל חלה מעורבת בהם ואבע\\\"א הנח מעת לעת דרבנן ופסק כפירוש שני להקל בדרבנן:\",5,0],[8,377,4,1,\"ארבע נשים דיין שעתן וכו'. משנה פ\\\"ק דנדה.\",1,0],[8,377,4,1,\"ומה שכתב היתה בחזקת מעוברת וכו'. ברייתא שם (דף ח' ע\\\"ב).\",2,0],[8,377,4,1,\"ומה שכתב ראתה דם ואח\\\"כ הוכר עוברה וכו'. שם (דף מ') בעיא דאיפשיטא:\",3,0],[8,377,4,1,\"איזו היא מניקה וכו'. ברייתא שם (דף ז' ע\\\"ב).\",4,0],[8,377,4,1,\"ומ\\\"ש אפילו מת בנה וכו'. שם במשנה וכחכמים.\",5,0],[8,377,4,1,\"ומ\\\"ש אבל אחר כ\\\"ד חדש וכו'. שם (דף ט') בברייתא וכרבי יהודה ורבי יוסי ור\\\"ש לגבי ר\\\"מ:\",6,0],[8,377,4,1,\"איזו היא בתולה וכו'. שם במשנה (דף ו' ע\\\"ב).\",7,0],[8,377,4,1,\"ומ\\\"ש או ילדה וכו'. ברייתא שם:\",8,0],[8,377,4,1,\"איזו היא זקנה וכו'. שם במשנה.\",9,0],[8,377,4,1,\"ומ\\\"ש ואיזו היא סמוך לזקנותה וכו'. שם (דף ט') היכי דמי סמוך לזקנותה אמר רב יהודה כל שחברותיה אומרות עליה זקנה היא ור\\\"ש אומר כל שקורים לה אמא אמא ואינה בושה רבי זירא ורבי שמואל בר רב יצחק ח\\\"א כל שאינה מקפדת וחד אמר כל שאינה בושה מאי בינייהו איכא בינייהו בושה ואינה מקפדת ופסק רבינו כר\\\"ש משום דרבי זירא ור\\\"ש ב\\\"ר יצחק משמע דסברי כוותיה ובפלוגתא דר' זירא ור\\\"ש ב\\\"ר יצחק פסק לקולא משום דמידי דרבנן היא:\",10,0],[8,377,4,1,\"עברו עליה ג' עונות וראתה וכו'. שם תנו רבנן זקנה שעברו עליה שלש עונות וראתה דיה שעתה ועוד עברו עליה שלש עונות וראתה דיה שעתה ועוד עברו עליה שלש עונות וראתה הרי היא ככל הנשים ומטמאה מעת לעת ומפקידה לפקידה ומדברי רבינו נראה שלא היה גורס אלא שתי פעמים עברו עליה שלש עונות ואתי ליה שפיר מאי דתנן בההוא פירקא (דף ז' ע\\\"ב) ובמה אמרו דיה שעתה בראיה ראשונה אבל בשניה מטמאה מעת לעת ואינו צריך לידחק במה שנדחקו בו התוספות.\",11,0],[8,377,4,1,\"ומ\\\"ש או פחות או יתר. בברייתא הנזכרת אסיקנא דל\\\"ש בין כוונה לפיחתה או הותירה:\",12,0],[8,377,4,2,\"בתולה שראתה דם וכו'. שם (דף י' ע\\\"ב) ולשון אפילו שופעת שכתב רבינו קשה דבגמרא פריך אפילו שופעת וכ\\\"ש פוסקת אדרבה פוסקת הויא כשתי ראיות ומשני אימא ושופעת ופרש\\\"י וסמי מכאן אפילו ויש לומר שמאחר שרבינו כתב בהדה דולפת שפיר דמי למיתני לגבה אפילו שופעת:\",1,0],[8,377,4,3,\"תינוקת שלא הגיע זמנה לראות וכו'. שם (דף ט' ע\\\"ב) תנו רבנן תינוקת שלא הגיע זמנה לראות וראתה פעם ראשונה דיה שעתה ושניה דיה שעתה פעם שלישית הרי היא ככל הנשים ומטמאה מעת לעת ומפקידה לפקידה עברו עליה שלש עונות וראתה דיה שעתה ועוד עברו עליה ג' עונות וראתה דיה שעתה ועוד עברו עליה ג' עונות הרי היא ככל הנשים ומטמאה מעת לעת ומפקידה לפקידה וכתב הרשב\\\"א בת\\\"ה הארוך ברייתא זו ד\\\"ה היא וטעמא דמילתא דכל שלא הגיע זמנה לראות אין לה דמים וראיה ראשונה שראתה אינה אלא מקרה ואינה ראיה להצטרף עד שתתחזק בראיות אחרות הילכך ראיה ראשונה אינה אלא כאחת ואין לה כח להחזיק הראשונה אבל כשתראה עוד פעם שלישית עם השתי ראיות אחרונות תתחזק הראשונה ואלו השתים מגלות על הראיה הראשונה שראיה גמורה היתה ולא מקרה ומעתה לפי הטעם הזה אפילו לרשב\\\"ג נמי מוחזקת היא ובזו אין הפרש בין רבי לרשב\\\"ג ואע\\\"פ שיש מגדולי המפרשים והפוסקים שפירשו דלרבי דוקא אתיא לפי שאין הראשונה ראויה להצטרף לעולם והילכך לרשב\\\"ג אינה מוחזקת עד שתראה ד' ראיות מסתברא לי שא\\\"א להעמידה שאם כן כל אותה סוגיא ושקלא וטריא דרב גידל ורב כהנא וחזקיה ור\\\"י ור\\\"ש בן יהוצדק וכל נחותי ימא אתו כרבי ודלא כהלכתא דאנן בווסתות כרשב\\\"ג סבירא לן כדאיפסקא הלכתא בב\\\"ק ולפיכך נ\\\"ל הדרך שכתבתי נכון וברור עכ\\\"ל. וכך היא דעת רבינו שפסקה לברייתא זו ויש בספרי רבינו חסרון הניכר וצריך להגיה עברו עליה ג' חדשים ואח\\\"כ ראתה דיה שעתה עברו עליה ג' חדשים אחרים ואח\\\"כ ראתה דיה שעתה עברו עליה שלשה חדשים אחרים וראתה מטמאה למפרע:\",1,0],[8,377,4,4,\"תינוקת שהגיע זמנה לראות וכו' עד ואח\\\"כ ראתה דיה שעתה. גם זה שם.\",1,0],[8,377,4,4,\"ומה שכתב עברו עליה שלשה חדשים אחרים וכו'. פשוט הוא:\",2,0],[8,377,4,5,\"מעוברת ומניקה וכו'. משנה שם (דף ז' ע\\\"ב) ובמה אמרו דיה שעתה בראייה ראשונה אבל בשניה מטמאה מעת לעת ואם ראתה את הראשונה מאונס אף בשניה דיה שעתה ובגמרא (דף י' ע\\\"ב) אמר רב אכולהו וכו' ופסק רבינו כר\\\"י ור' יוסי ור\\\"ש לגבי ר\\\"מ ואע\\\"ג דרבי יוחנן סבר כר\\\"מ הא רב דהלכה כוותיה באיסורי לגבי שמואל סבר כוותייהו ולא שבקינן רובא דתנאי למפסק כר\\\"מ דיחידאה הוא ועוד דלית הלכתא כוותיה לגבי חד מינייהו וכיון דרב סבר הכי לא חיישינן לדרבי יוחנן בהא:\",1,0],[8,377,4,5,\"וכתב הר\\\"י קורקוס ז\\\"ל שיש הוכחה לפסק זה ממה שאמרו אחר כך כתנאי וכיון שאחר שהזכירו פלוגתא דאמוראי אמרו כתנאי משמע דאמוראי לא שמיע להו מן הך ברייתא דאי הוה שמיע להו הל\\\"ל הלכתא כפלוני הילכך אפלוגתא דתנאי איכא למיסמך למפסק כרובא וכ\\\"ש דמתניתין סתמא קתני וטפי משמע דאכולהו קאי ושוב מצאתי בירושלמי שאמרו דר\\\"י סבר כרב עכ\\\"ל. ובכן נסתלק מעל רבינו מ\\\"ש עליו הרב ראב\\\"ד מטמאות למפרע אמר אברהם הא דלא כהלכתא דקיי\\\"ל כרבי יוחנן דאמר מעוברת ומניקה דיין שעתן כל ימי עיבורן וכל ימי מניקותן:\",2,0],[8,377,4,6,\"מעוברת או מניקה שראתה דם וכו'. משנה שם (דף ז' ע\\\"ב) רבי יוסי אומר מעוברת ומניקה שעברו עליהן ג' עונות דיין שעתן ומשמע לרבינו דלא פליג אלא אר\\\"א דאמר התם כל הנשים דיין שעתן אבל ת\\\"ק לא פליג אר' יוסי ודלא כפרש\\\"י דפליג ולפי פירוש רבינו רבי יוסי נמי כת\\\"ק ס\\\"ל דמעוברת משיודע עוברה ומניקה משנולד אלא דאתא למימר דבעברו עליהן ג' עונות פעם אחת בלבד דיין שעתן אבל אם עברו עליהן ג' עונות פעם שניה מטמאות למפרע ות\\\"ק לא פליג עליה:\",1,0],[8,377,4,6,\"הרואה דם טוהר וכו': וכל שדיה שעתה אע\\\"פ שאינה מטמאה למפרע וכו'. משנה סוף פ\\\"ק דנדה (דף י\\\"א) אע\\\"פ שאמרו דיה שעתה צריכה להיות בודקת חוץ מן הנדה והיושבת על דם טוהר.\",2,0],[8,377,4,6,\"ומה שכתב וכל אשה המרבה לבדוק משובחת. ריש פרק כל היד (נדה דף י״ג):\",3,0],[8,377,4,7,\"חכמים תקנו וכו'. בריש נדה (דף ד' ע\\\"ב) ופרש\\\"י שחרית להכשיר טהרות של לילה להוציא מכלל ספק טומאה שאם תמצא טהורה תדע שלא ראתה בלילה ולכשתמצא ערבית טמאה יצאו אלו מספק.\",1,0],[8,377,4,7,\"ומ\\\"ש וכל אוכלת תרומה בודקת וכו'. משנה ספ\\\"ק דנדה (דף י\\\"א):\",2,0],[8,377,4,7,\"וכל אשה בודקת בשעה שעוברת לשמש מטתה. שם במשנה שצריכה לבדוק בשעה שעוברת לשמש ביתה ובגמרא (דף י\\\"א ע\\\"ב) אמר רב יהודה אמר שמואל לא שנו אלא באשה עסוקה בטהרות דמגו דבעיא בדיקה לטהרות בעיא נמי בדיקה לבעלה אבל אינה עסוקה בטהרות לא בעיא בדיקה ואסיקנא דאע\\\"ג דיש לה וסת אם היא עסוקה בטהרות צריכה בדיקה לבעלה ואם אינה עסוקה בטהרות אע\\\"פ שאין לה וסת אינה צריכה בדיקה לבעלה ולפי זה יש לתמוה על רבינו שכתב שכל הנשים שיש להם וסת בחזקת טהרה לבעליהן דמאי איריא יש להם וסת אפילו אין להם וסת הרי הן בחזקת טהרה לבעליהן כל שאינה עסוקה בטהרות וכבר השיגו הראב\\\"ד וכתב כל הנשים שיש להם וסת א\\\"א איני יודע מהו זה דקי\\\"ל כל לבעלה אינה צריכה בדיקה אא\\\"כ עסוקה בטהרות ואפילו אשה שאין לה וסת עכ\\\"ל. וליישב דעת רבינו י\\\"ל שהוא ז\\\"ל סובר שמה שאמרו בגמרא לא שנו אלא בעסוקה בטהרות וכו' היינו דוקא בעד שלפני תשמיש אבל בעדים דלאחר תשמיש לעולם צריכה כ\\\"כ המ\\\"מ בפ\\\"ד מהא\\\"ב:\",3,0],[8,377,4,8,\"חזקת בנות ישראל וכו'. פ\\\"ק דנדה עלה י' ע\\\"ב:\",1,0],[8,377,4,9,\"החרשת והשוטה וכו'. משנה ריש פרק כל היד (נדה דף י\\\"ג ע\\\"ב):\",1,0],[8,377,4,10,\"כל הכתמים הבאים וכו'. משנה וגמרא בסוף פרק דם הנדה (נדה דף נ״ו):\",1,0],[8,377,4,11,\"כל הכתמים הטמאים וכו'. בפ\\\"ט דנדה (דף ס\\\"א ע\\\"ב) ז' סמנים מעבירים על הכתם וכו' הטבילו ועשה על גביו טהרות העביר עליו ז' סמנים ולא עבר ה\\\"ז צבע הטהרות טהורות ואינו צריך להטביל עבר או שדיהה [ה\\\"ז כתם] הטהרות טמאות וצריך להטביל ובגמרא (דף ס\\\"ב ע\\\"ב) תניא ר' חייא אומר דם הנדה ודאי מעביר עליו שבעה סמנים ומבטלו ופירש\\\"י דם הנדה ודאי כגון נדה שקנחה בסדין דם אע\\\"ג דודאי דם הוא מעביר עליו ז' סמנים ומבטלו ואפילו לא עבר הרי הוא בטל וטהור הואיל ואין אדם מקפיד עליו אחר העברת סמנין מדאזל ליה חזותא ואע\\\"ג דקאמר התם אהא דר' חייא רבי לא שנאה ר' חייא מנא ליה ופירש\\\"י דאינה משנה ומשובשת היא ר\\\"ל הוא דאמר הכי לפרוקי מאי דאותיב עליה ר\\\"י אבל ר\\\"י סבר דמשנה היא דהא מותיב מינה לר\\\"ל ואמוראי בתראי נמי סברי לה התם להא דר' חייא. ומ\\\"מ מה שכתב\",1,0],[8,377,4,11,\"רבינו בין עבר בין לא עבר מטבילו קשיא לי דהא בלא עבר תנן ה\\\"ז צבע ואינו צריך להטביל. וי\\\"ל דאינו צריך להטביל פעם שניה קתני אבל פעם ראשונה צריך להטביל וכדקתני ברישא דמתניתין הטבילו. וא\\\"ת אם הוא צבע למה צריך להטבילו י\\\"ל דכיון דנחת לידי ספק טומאה צריך טבילה ואם הטבילו קודם שעברו עליו ז' סמנין כיון דאיגלאי מילתא דצבע הוא עלתה לו אותה טבילה ואי איגלאי מילתא דכתם הוא לא עלתה לו אותה טבילה כיון שהיה שם דם הנדה בעין וצריך להטבילו שנית:\",2,0],[8,377,4,12,\"בגד שאבד בו כתם וכו' ומבטלו. בפרק ט' דנדה (דף ס\\\"א).\",1,0],[8,377,4,12,\"ומה שכתב אבדה בו ש\\\"ז וכו'. שם ופירש\\\"י במחט מקום הזרע קשה והמחט מתעכב מלהכנס בו. חדש אין נבדק בחמה לפי שהוא עב ומהודק אבל שחוק נבדק בחמה שוטחו בחמה מקום הזרע הוי סתום ואין החמה נראית כנגדו כל כך:\",2,0],[8,377,4,13,\"בגד שהיה עליו כתם וכו'. משנה כתבתיה בסמוך.\",1,0],[8,377,4,13,\"ומ\\\"ש שהרי הקפיד על הכתם להסירו וכו'. שם בגמרא:\",2,0],[8,377,4,14,\"כתם שהעביר עליו ששה סמנים וכו'. ברייתא שם (דף ס\\\"ב) ובספרי רבינו כתוב פעמיים צנון והוא ט\\\"ס וצריך לכתוב במקומו צפון והוא הנקרא בלעז שאבו\\\"ן:\",1,0],[8,377,4,14,\"העביר עליו ז' סמנין וכו'. גם זה ברייתא שם העביר עליו ז' סמנין ולא עבר שנאן ועבר טהרותיו טהורות אמר ר' זירא ל\\\"ש אלא הטהרות שנעשו בין תכבוסת ראשונה לשניה אבל טהרות שנעשו אחר תכבוסת שניה טמאות שהרי הקפיד עליו ועבר אמר ליה ר' אבא לרב אשי מידי בקפידא תליא מילתא א\\\"ל אין דתניא רבי חייא אומר דם הנדה ודאי מעביר עליו ז' סמנין ומבטלו ואמאי הא דם נדה הוא אלמא בקפידא תליא מילתא הכא נמי בקפידא תליא מילתא ופירש\\\"י שנאן ועבר טהרותיו טהורות דאם איתא דדם הוא בהעברה קמייתא הוה עבר. תכבוסת העברת סמנים. שהרי הקפיד עליו כשחזר והעבירן גילה דעתו שמקפיד עליו בספק דם. ועבר ע\\\"י העברה זו ונעשה בו מעשה דם שכן דרך דם לעבור ע\\\"י ז' סמנים. מידי בקפידא תליא בתמיה כיון דטהרות שבינתים טהורות אלמא לאו דם הוא אחרונות משום קפידא אמאי טמאוה דם הנדה ודאי כגון נדה שקנחה בסדין דם אע\\\"ג דודאי דם הוא מעביר עליו ז' סמנין ומבטלו ואפילו לא עבר הרי הוא בטל וטהור הוא הואיל ואין אדם מקפיד עליו אחר העברת סמנין מדאזל לה חזותא עכ\\\"ל וה\\\"ה בפ\\\"ט מהא\\\"ב פירש הסוגיא לדעת רבינו עיין עליו. ואם תאמר והרי כיון שהעביר עליו ז' סמנין ולא עבר אין זה כתם אלא צבע וכמ\\\"ש רבינו למעלה וא\\\"כ אין כאן עוד טומאה אפילו אחר תכבוסת שניה ואפילו מקפיד ותירצו התוספות עיין עליו:\",2,0],[8,377,4,14,\"והר\\\"י קורקוס ז\\\"ל כתב וז\\\"ל ומדברי רבינו נ\\\"ל שאפשר לפרש בדרך אחרת דודאי ע\\\"י כיבוס משתנה הוא ומראיתו מכהה וה\\\"נ מיירי בנשתנה ע\\\"י כיבוס ראשון ובכי הא לא הוי צבע וכמ\\\"ש רבינו למעלה לא עבר כלל ה\\\"ז צבע ואם עבר וכו' דכל שהוא ודאי עובר או מכהה באופן שלא ישאר אלא רישומן לבד וכיון שנשתנה הרי נתבטל וטהור אף על פי שהוא כתם כי מסתמא אינו מקפיד עוד עליו ולכך טהור אבל זה שחזר והעבירו הקפיד על רושם כל שהוא ולכך טמא עד שיבטלו ויטבילו וז\\\"ש הואיל וגילה דעתו שהוא מקפיד עליו ורוצה להוציא רישומו כי בודאי אין שם אלא רישומו עד כאן לשונו:\",3,0],[8,377,4,15,\"האשה שמתה וכו'. משנה וגמרא בסוף נדה (דף ע\\\"א) וכת\\\"ק:\",1,0],[8,377,5,1,\"הזב והזבה וכו' יולדת שלא טבלה וכו'. בפרק במה אשה (שבת ס״ד:) ובפרק בנות כותים עלה ל״ה ובת״כ שנינו וידיו לא שטף במים אפי' לאחר כמה שנים:\",1,0],[8,377,5,3,\"יולדת שירדה לטבול וכו'. בפרק יוצא דופן עלה מ\\\"ב:\",1,0],[8,377,5,4,\"יולדת שטבלה אחר שבעה וכו'. משנה בסוף נדה (דף ע\\\"א) וכבית הלל.\",1,0],[8,377,5,4,\"ומה שכתב רבינו נמצאת אתה למד שהיולדת בתוך ימי טוהר אוכלת במעשר וכו'. שיעור הלשון כך הוא שהיולדת דינה הוא שבתוך ימי טוהר אוכלת במעשר וכו':\",2,0],[8,377,5,4,\"וכתב הראב\\\"ד ותהיה טהורה לכל א\\\"א כמה דבריו מבולבלים וכו'. מ\\\"ש ומשנה שלימה היא בפרק חומר בקודש (חגיגה דף כ\\\"א) אונן ומחוסר כפורים צריכים טבילה לקדש אבל לא לתרומה. ומ\\\"ש ואם יאמר הני מילי לאכילה אבל למגע לא הרי דבריו סותרים זה את זה כלומר שהוא כתב ותהיה טהורה לכל דמשמע לכל מילי בין למגע בין לאכילה והוא אומר דמתניתין דמצרכה טבילה הני מילי לאכילה. וליישב דברי רבינו יש לומר שמה שכתב רבינו לכל היינו לומר שתהיה טהורה בין לקדש בין לתרומה במגע דוקא וזה מבואר בדבריו שהרי כתב שלאכילה אף לתרומה יראה לו שצריכה טבילה כך היה נראה לומר אלא שמדברי רבינו בפרק שנים עשר מהלכות שאר אבות הטומאה נראה שמחוסר כפורים עד שלא הביא כפרתו אסור ליגע בקדש ולפיכך צריך לפרש דברי רבינו דה\\\"ק ומטמאה את הקדשים בולד הטומאות עד שתשלים ימי טוהר וגם תהיה טהורה לכל דהיינו על ידי הבאת קרבנותיה.\",3,0],[8,377,5,4,\"ומה שכתב רבינו ויראה לי מצאתי בספר מוגה כלשון הזה ויראה לי שמאחר שהיא מטמאה את הקדש שהיא צריכה טבילה בסוף ואחר תגע בקדש אף על פי שאינה צריכה טבילה אחרת לאכילת התרומה:\",4,0],[8,377,5,5,\"יולדת שהיא מצורעת וכו'. משנה פרק בנות כותים (נדה דף ל״ד) וכב״ה ויליף לה מדכתיב ולנקבה לרבות מצורעת למעיינותיה וברפ״ב דטבול יום ושאר כל הטמאים וכו' משקים היוצאים מהם כמשקין שהוא נוגע בהם אלו ואלו תחילה חוץ מן המשקה שהוא אב הטומאה והיינו משקה הזב:\",1,0],[8,377,5,6,\"זבה קטנה וכו'. משנה בסוף נדה (דף ע\\\"ב) ומודים ברואה תוך אחד עשר יום וטבלה לערב ושמשה שמטמאים משכב ומושב וחייבין בקרבן טבלה ביום שלאחריו ושמשה הרי זו תרבות רעה ומגען ובעילתן תלויים.\",1,0],[8,377,5,6,\"ומה שכתב רבינו שטבלה ביום השמור שלה וכו'. הוא מה ששנינו טבלה ביום שלאחריו וכו'.\",2,0],[8,377,5,6,\"ומה שכתב טבלה בליל השמור וכו'. זה הוא מה ששנינו ומודים ברואה בתוך י\\\"א יום וטבלה לערב וכו' וביאר רבינו כל זה בפרק ששי מהלכות איסורי ביאה:\",3,0],[8,377,5,7,\"הרואה דם ביום י\\\"א וכו'. גם זה שם במשנה וכבית הלל:\",1,0],[8,377,5,8,\"וכתב הראב\\\"ד אע\\\"פ שאסורה לשמש לערב א\\\"א יש כאן שיבוש ולמה אסורה לשמש לערב והלא יצא מגרגרנותו וכו'. ואין ספק שספר מוטעה נזדמן להראב\\\"ד שבספרינו כתוב עד לערב. ומ\\\"ש אבל הרואה דם בעשירי וכו'. שם וכר\\\"י:\",1,0],[8,377,5,9,\"זב וזבה גדולה וכו'. בפרק כיצד צולין (פסחים דף פ״א) ובפרק שני דנזיר (דף ט״ו ע״ב) נתבאר שאפי' ראתה בשביעי אחר טבילה סותרת הכל ופרק בנות כותים (נדה דף ל״ג ע״ב) אמרו ואחר תטהר אמר רחמנא אחר אחר לכולן שלא תהא טומאה מפסקת ביניהם ובפרק תינוקת (נדה דף ס״ז ע״ב) אמרו מכדי האידנא כלהו ספק זבות שווינהו רבנן ליטבלינהו ביממא דשבעה ומשני משום דר״ש דתניא אחר תטהר אחר אחר לכולן ר״ש אומר אחר מעשה תטהר אבל אמרו חכמים אסור לעשות כן שמא תבא לידי ספק ובת״כ אחר תטהר אחר המעשה תטהר כיון שטבלה יכולה להתעסק בטהרות אבל אמרו חכמים לא תעשה כן שלא תבא לידי ספק:\",1,0],[8,377,5,9,\"אע\\\"פ שהם עושים משכב ומושב למפרע וכו'. הכי איתא בפ\\\"ק דמגילה (דף ח' ע\\\"ב) א\\\"ל רבא אלא מעתה גבי זב דכתיב וכבס בגדיו וטהר התם מאי וטהר מעיקרא איכא אלא טהור השתא מלטמא כלי חרס בהיסט אע\\\"ג דהדר חזי לא מטמא למפרע. וכתב רש\\\"י אף על פי שטבילתו ביום ואם ראה אחר טבילה בו ביום סתר הכל ומטמא משכב ומושב וכו' אפילו הכי מהני ליה טבילה לטהרו מלטמא כלי חרס שהסיט בין טבילה לראיה והכי דריש לה בת\\\"כ ונראה בעיני דהא דדרשינן ליה וטהר מלטמא כלי חרס מדכתביה להאי קרא בתר קרא אשר יגע בו הזב דנפקא לן מיניה היסט כלי חרס לזב ואין לך עוד טמא שמטמא כלי חרס בהיסט אלא הוא עכ\\\"ל:\",2,0],[8,377,6,1,\"כבר ביארנו שהזב וחביריו וכו'. בתחילת פ' ראשון.\",1,0],[8,377,6,1,\"ומ\\\"ש ובין שישב על המשכב וכו'. בת\\\"כ אין לי אלא בזמן ששכב על המשכב וישב על המושב מנין שכב על המושב וישב על המשכב ת\\\"ל יטמא ריבה.\",2,0],[8,377,6,1,\"ומה שכתב ואי זהו מרכב וכו'. בתורת כהנים ובפרק כ\\\"ג דכלים.\",3,0],[8,377,6,1,\"וטפיטן של סוס הוא הנקרא בערבי סרג אל פרס:\",4,0],[8,377,6,2,\"המשכב והמרכב כל אחד מהם אב וכו'. בפ\\\"ק דכלים מונה אותה באבות הטומאות ובתורת כהנים אמרו שהמשכב נעשה אב הטומאה לטמא אדם ולטמא בגדים ובפרשת זבים כתיב כל המשכב אשר ישכב עליו הזב יטמא וכל הכלי אשר ישב עליו יטמא ואיש אשר יגע במשכבו ורחץ במים וגו' וכל המרכב אשר ירכב עליו הזב יטמא וכל הנוגע בכל אשר יהיה תחתיו יטמא עד הערב והנושא אותם יכבס בגדיו ורחץ במים וגו' ודריש בת\\\"כ דוהנושא אותם קאי על כל מאי דכתיב בענין מעיינותיו ומרכבו ומושבו ודם הנדה ובפרק כ\\\"ג דכלים שנינו מה בין מרכב למושב מרכב חלק מגעו ממשאו ומושב לא חלק מגעו ממשאו כלומר שבנוגע במשכב נאמר יכבס בגדיו וגו' ובנוגע במרכב נאמר יטמא עד הערב ולא נאמר יכבס בגדיו למדנו שאינו מטמא בגדים אפילו נוגע בהם עד שלא פירש ממטמאיו ונוגע במשכב מטמא בגדים עד שלא פירש ממטמאיו אבל פירש ממטמאיו אינו מטמא כלים מדכתיב יכבס בגדיו דמשמע דוקא בגדיו שהוא לבוש בשעת נגיעה והוא הדין לשאר כלים שהוא נוגע בהם באותה שעה והכי תניא בת\\\"כ ואיש אשר יגע במשכבו יכבס בגדיו בשעת מגעו מטמא בגדים פירש אינו מטמא בגדים ותניא תו בת\\\"כ מנין לעשות שאר כלים כבגדים ת\\\"ל וטמא יכול יטמא אדם וכלי חרס ת\\\"ל בגד בגד הוא מטמא ולא אדם וכלי חרס ובפ\\\"ב דזבים תנן כלל אמר רבי יהושע כל המטמא בגדים בשעת מגעו מטמא אוכלים ומשקים להיות תחילה והידים להיות שניות ואינו מטמא לא אדם ולא כלי חרס לאחר פרישתו ממטמאיו מטמא משקים להיות תחילה והאוכלים והידים להיות שניות ואינו מטמא בגדים:\",1,0],[8,377,6,2,\"נמצאת למד שהזב והזבה וכו'. נתבאר בפרק ראשון ובפרק זה.\",2,0],[8,377,6,2,\"ומה שכתב ואינו מטמא לא אדם ולא כלי חרס. כבר כתבתי בסמוך דהכי דריש בתורת כהנים:\",3,0],[8,377,6,2,\"הנה למדת שכל טמא שנאמר בו יכבס בגדיו וכו'. נתבאר בסמוך.\",4,0],[8,377,6,2,\"ומה שכתב ועושה אותם ראשון לטומאה כמוהו:\",5,0],[8,377,6,3,\"כל הכלים שינשאו למעלה מן הזב וכו'. בפרק בנות כותים (נדה דף ל״ב ל״ג) יליף מקרא דוכל הנוגע בכל אשר יהיה תחתיו יטמא דעליונו של זב אינו מטמא אלא אוכלים ומשקים.\",1,0],[8,377,6,3,\"ומ\\\"ש שהם נקראים מדף. בפ\\\"ד דזבים תנן שהזב עושה משכב ומושב מתחתיו לטמא אדם ולטמא בגדים ועל גביו מדף לטמא אוכלים ומשקים וכתב רבינו טומאת מדף הוא כי הזב וחביריו וכו' כשהיה עליו למעלה ממנו אוכלים ומשקים נטמאו ואפילו אם היו בינו ובינם חציצות רבות וכן כשיש למעלה מן הזב כלים מונחים זה על זה הרי הכלי העליון טמא טומאת מדף ואע\\\"פ שבינו ובין הזב חציצות רבות אמנם הכלי ההוא טמא טומאה קלה ר\\\"ל שאינו אב הטומאה אבל דינו כדין כלים שנגעו בזב שמטמאין אוכלים ומשקים בלבד לא אדם וכלים וכבר נתבאר כי כל הכלים הראויים למשכב שתחת הזב כולם אב הטומאה ואין חילוק בין המשכב התחתון הדבק בקרקע או המשכב הדבק לגופו וכל הכלים אשר על הזב כולם ראשון לטומאה ואין חילוק בין הבגד הדבק על גופו מלמעלה ובין הבגד העליון שכנגד הרקיע הכל טמא טומאת מדף ואין הדין כן במת אבל דין כלים שעל גביו או כלים שתחתיו או כלים שנגעו בו דין אחד לכולם וכו' ויליף לה בסיפרא מקראי. והלשון הזה של מדף וכו' בכאן עיקרו מנדף והוא ממאמרם ריחו נודף יריח למרחק הרבה הפליג הענין הזה על הזב אשר יטמא כלים שעל גביו ואפי' היה ביניהם חציצה רבה כאילו יעבור ריחו ויגיע אליהם ויטמאם על דרך הדמיון עכ\\\"ל:\",2,0],[8,377,6,3,\"ומ״ש וטומאת מדף מדבריהם. הוא ממה שאמרו בריש נדה (דף ד' ע״ב) בטומאה דרבנן דיקא נמי דקתני מדף כד״א קול עלה נדף ואע״ג דבפרק בנות כותים (נדה דף ל״ב ל״ג) יליף לה מקרא משמע לרבינו שהוא אסמכתא דהא בת״כ דריש האי תחתיו תחתיו ממש ולא לעליונו כדדריש בפרק בנות כותים ובזה נתיישב מ״ש עליו הראב״ד א״א יש טומאת מדף מדבריהם אבל זו אע״פ שהיא קרויה מדף אינה מדבריהם שהרי התורה אמרה והנוגע בכל אשר יהיה תחתיו יטמא עד הערב ודרשינן לה במסכת נדה כל אשר יהיה תחתיו הזב ואמרה תורה יטמא עד הערב אלמא כלי שטף נמי מטמא במגע עכ״ל. ומה שסיים אלמא כלי שטף נמי מטמא במגע היינו לומר שכיון שעליונו של זב מטמא מן התורה לדעת הראב״ד הרי הוא ראשון ומטמא כלי שטף במגע אבל לדעת רבינו שאינו טמא אלא מדרבנן אינו מטמא כלים כלל:\",3,0],[8,377,6,3,\"כתב הר\\\"י קורקוס ז\\\"ל תמהני מהראב\\\"ד שרוצה לפרש כוליה קרא בעליונו שמטמא גם כלי שטף במגע דהא הלכה רווחת היא דעליונו של זב אוכלים ומשקים לבד מטמא וכמו שכתבתי ממשנה פ\\\"ד דזבים ופ\\\"ו דעדיות גם בתוספתא דזבים פ\\\"ג גם בת\\\"כ גם בפרק בנות כותים באותה סוגיא שהזכיר הראב\\\"ד:\",4,0],[8,377,6,4,\"הזב והזבה וכו'. משנה וגמרא בפרק תינוקת (נדה דף ס״ט ע״ב) ושנינו בתורת כהנים שטומאה זו מדברי סופרים:\",1,0],[8,377,6,5,\"כל מקום שאתה שומע טומאת משכב ומרכב וכו'. שם בגמרא ובפ\\\"ק דכלים שנינו למעלה מהם מרכב שהוא מטמא תחת אבן מסמא למעלה מן המרכב משכב ששוה מגעו למשאו והוא מלשון והיתית אבן חדה ושומת על פום גובא כמו שאמרו בפ\\\"ב דנדה שם דהיינו אבן כבדה העשויה להניח ואינה מיטלטלת ורבותא הוי אע\\\"פ שאין נרגש כובד הזב היושב עליה במה שתחתיה כי ע\\\"י כובד האבן אין כובד הזב מעלה ולא מוריד לכלים שתחתיה ואין מגיע להם כובדו ובת\\\"כ יליף להו מקראי.\",1,0],[8,377,6,5,\"ומ״ש רבינו וכן אם היה אחד ממטמאי משכב ומושב למטה ואבן עליו. בפ״ה דזבים כל הנישא על גבי הזב טמא כל שהזב נישא עליו טהור חוץ מן הראוי למשכב ולמושב והאדם כיצד אצבעו של זב ( תחת האבן או) תחת הנדבך הטהור מלמעלה מטמא שנים ופוסל אחד פירש מטמא אחד ופוסל אחד הטמא מלמעלן והטהור מלמטן מטמא שנים ופוסל אחד פירש מטמא אחד ופוסל אחד האוכלים והמשקין המשכב והמושב והמדף מלמעלן מטמאים אחד ופוסלים אחד פירשו מטמאים אחד ופוסלים אחד המשכב והמושב מלמטן מטמאין שנים ופוסלים אחד האוכלים והמדף מלמטה טהורים מפני שאמרו כל הנושא והנישא על המשכב טהור חוץ מן האדם ופי' רבינו שמדף ששנינו היינו אוכלים או משקים וכלי שטף שאינן ראויים למשכב ומושב. ואע״פ שבמשנה זו לא הזכירו מרכב כללו רבינו עם משכב ומושב שודאי דינם שוה שע״ז אמרו בר״פ בכל מערבין (עירובין דף כ״ז) שאין למדין מן הכללות אפילו במקום שנאמר בהם חוץ דהא איכא מרכב:\",2,0],[8,377,6,5,\"כתב הראב\\\"ד ואינו מטמא לא אדם ולא כלים א\\\"א כבר כתבנו למעלה שעליונו של זב מטמא כלי שטף במגע עכ\\\"ל. וכבר כתבתי טעם דברי רבינו:\",3,0],[8,377,6,6,\"כתוב בספרי רבינו האוכלים והכלים והמשקים, והוא חילוף מט\\\"ס וצריך להגיה האוכלים והמשקים והכלים:\",1,0],[8,377,6,6,\"ומ\\\"ש והכלים שאינם עשויים לא למשכב ולא למושב ולא למרכב. בפ\\\"ג דחגיגה (כ\\\"ג ע\\\"ב) ובפ\\\"ו דשבת (דף נ\\\"ט) יכול כפה סאה וישב עליה יהא טמא וכו' תלמוד לומר אשר ישב עליו והיושב על הכלי יטמא מי שמיוחד לישיבה יצא זה שאומרים לו עמוד ונעשה מלאכתנו:\",2,0],[8,377,7,1,\"הזב מטמא את המשכב והמושב והמרכב בה' דרכים וכו'. בסוף פרק שני דזבים וכתב שם רבינו ראיה מהפסוק.\",1,0],[8,377,7,1,\"ומה שכתב וכל אחד מחמשה דרכים אלו הוא הנקרא מדרס בכ\\\"מ, כם כתב רבינו שם גם כן:\",2,0],[8,377,7,2,\"וכן המשכב והמרכב מטמאים את האדם בשבעה דרכים וכו'. ג\\\"ז בסוף פ\\\"ב דזבים:\",1,0],[8,377,7,2,\"ומ\\\"ש רבינו מפי השמועה למדו שמקום שהזב יושב ומטמא וכו'. בת\\\"כ והיושב על הכלי אשר ישב עליו הזב יטמא מקום שהזב יושב ומטמא ישב הטהור ויטמא אין לי אלא בזמן שהוא יושב עליו והזב שם מנין לעשות ריקם כמלא ת\\\"ל כלי לעשות ריקם כמלא פי' ריקם כשאינו שם מלא כשהוא שם.\",2,0],[8,377,7,2,\"ומ\\\"ש אעפ\\\"י שהיתה אבן מבדלת וכו'. בת\\\"כ יליף לה מקרא:\",3,0],[8,377,7,3,\"אין הזב מטמא את המשכב וכו'. בת\\\"כ.\",1,0],[8,377,7,3,\"ומה שכתב כיצד מקצת טמא על המשכב וכו'. בפ\\\"ה דזבים הטמא על מקצת משכב והטהור על מקצת משכב טמא מקצת טמא על המשכב ומקצת טהור על המשכב טהור נמצאת טומאה נכנסת לו ויוצאת ממנו במיעוטו ופירש שם רבינו כבר קדם לנו כי אשר יטמא משכב ומרכב לא יטמא אותו עד שינשא רובו עליו וכן האיש הטהור כשינשא על משכב טמא צריך שינשא רובו ואז יטמא אמר יתברך באדם אשר ישב על משכב הזב ואם על המשכב הוא ובא הפירוש הוא עד שינשא רובו עליו ודע כי אנחנו לא נחוש על רוב המשכב ומיעוטו אמנם על רוב הנישא ואפי' היה על מיעוט המשכב הוא מטמא אותו ומיטמא ממנו ולשון סיפרא או על הכלי אשר הוא יושב עליו או על מקצתו והנה יהיה ביאור המשנה כך רוב הטמא על קצת משכב ורוב הטהור על מקצתו נטמא הטהור נמצאת טומאה נכנסת למשכב ויוצאת ממנו במיעוטו לפי שמקצתו נטמא וטימא זולתו:\",2,0],[8,377,7,3,\"וכתב הראב\\\"ד ומקצת הטהור על אותו משכב א\\\"א לא ידעתי מהו על אותו משכב שאפי' על משכב שהוא טמא גמור אם לא ישב עליו הטהור רובו טהור דהכי דריש לה בספרא ואם על המשכב הוא עד שינשא רובו עליו כדרך שנכנסת לו הטומאה כך היא יוצאה ממנו עכ\\\"ל וי\\\"ל שדבר פשוט הוא וכך מבואר בדבריו בפי' המשנה שכתבתי וגם פה מבואר בתחילת דבריו שכתב אבל אם נישא מיעוטו הואיל ולא נגע ה\\\"ז טהור ולא כתב אותו משכב אלא כדי לסיים שהמשכב והנישא עליו טהורים ואין כאן מקום לטעות בו:\",3,0],[8,377,7,4,\"זב שהיה מוטל על חמשה ספסלין וכו'. משנה פ\\\"ד דזבים ופירש רבינו שמשון לאורכן ששכב אורכו לאורכן טמאים שעל כל אחד ואחד נשען רובו פעמים על זה פעמים על זה לרוחבן ששוכב אורכו לרוחבן ולכך טהורין דאין רובו נשען על אחד מהם ישן לרוחבן ספק נתהפך לארכן טמאים ורבינו פירש שם בהיפך ורש\\\"י בהמצניע (דף צ\\\"ג) פירש כרבינו שמשון וכן משמע בתוספתא פ\\\"ק:\",1,0],[8,377,7,4,\"היה מוטל על ששה כלים וכו'. גם זה שם ודייק רבינו לכתוב אין טמא משום משכב לומר דלא מיעט שאר כלים אלא מטומאת משכב אבל לא מטומאת מגע ונפקא מינה דטמא משום משכב הוי אב הטומאה לטמא אדם וכלים:\",2,0],[8,377,7,4,\"עמד על שני משכבות וכו': וכתב הראב\\\"ד אני ראיתי המשנה כך וכו'. ומשנה זו בפרק ד' דזבים וסבור רבינו דכיון דבשם רבי שמעון שנינו טהורים משמע דרבנן פליגי עליה ומטמו בכל גוונא. וכן נראה מדבריו בפירוש המשנה שכתב ואין הלכה כר\\\"ש:\",3,0],[8,377,7,5,\"היה יושב על גבי המטה וכו' עד הרי הכלים שתחת לוח המכבש טהורים. שם וכת\\\"ק:\",1,0],[8,377,7,7,\"וכתב הראב\\\"ד מפני שהוא רפוי א\\\"א כל מ\\\"ש בזה הרבה יגיעות וכו' עד יצפון לישרים תושיה: ואני אומר שנראה מדבריו שהוא סובר שרבינו מפרש שיושב על המכבש היינו שיושב על הלוח הנתון על הבגדים ומפני כך הקשה עליו מה שהקשה ואין הדבר כן אלא ביושב על קצה המכבש שאצל הלוח המונח על הבגדים ואילו היה הלוח דחוק על הבגדים היו הבגדים רצוצים תחת המכבש והיה היושב על קצה המכבש נישא על הבגדים ועכשיו שהלוח המונח על הבגדים רפוי כשהוא יושב על קצה המכבש אינו נישא על הבגדים ואפשר דמשום הכי נקט תנא מכבש של כובס כלים מפני שאין דרך להדקו מפני שאין צורך לכובס בהידוק דכשיתפשטו קמטיו קצת סגי להו. אבל מכבש של חייטים מהדקים אותו בכל כחם כדי שיהיו הבגדים עומדים זקופים ומה ששנו בתוספתא בזמן שטעון אבנים כלים שתחתיו טהורים הטעם מפני שע\\\"י אבנים אינו מהודק אבל כשהוא קשור בחבלים הוא מהודק:\",1,0],[8,377,7,8,\"זב שדרס על כלי וכו'. בפרק בא סימן (נדה דף מ״ט ע״ב) ופרק חומר בקדש (דף כ״ב) ובפרק במה אשה (שבת דף נ״ט):\",1,0],[8,377,7,8,\"היה הכלי משמש לישיבה וכו'. בתורת כהנים:\",2,0],[8,377,8,1,\"כבר ביארנו בתחילת ספר זה וכו'. בפרק א':\",1,0],[8,377,8,1,\"אבל אם הסיטה הטומאה את האדם לא נטמא. בפרק רבי עקיבא כמו שאכתוב בסמוך:\",2,0],[8,377,8,3,\"אין בכל אבות הטומאות וכו'. בר״פ ר״ע (שבת דף פ״ג ע״ב) כל הטומאות המסיטות טהורות חוץ מהיסטו של זב שלא מצינו לו חבר בכל התורה כולה. ואיתיה נמי בפרק יוצא דופן וברפ״ה דזבים המסיט את הזב או שהזב מסיטו מטמא אוכלים ומשקים וכלי שטף במגע ונתבאר גם בפ״ג דזבים ושם כתב רבינו כל זה:\",1,0],[8,377,8,3,\"ומ\\\"ש ואחד זב וזבה נדה ויולדת בכל הדברים האלו. בפ\\\"ה דזבים.\",2,0],[8,377,8,3,\"ומ\\\"ש והזב שהסיט וכו' אפילו כלי חרס טמאים וכו' חומר בהיסט הזב וכו' ואם הסיטו טימאהו. בתורת כהנים וכלי חרס אשר יגע בו הזב ישבר יכול אפילו נגע בו הזב מאחוריו ת\\\"ל אשר יגע בו ולהלן הוא אומר אשר תבושל בו מה בו האמור להלן מאוירו אף כאן מאוירו מאחר שלמדנו שאינו מטמא אלא מאוירו מה ת\\\"ל אשר יגע בו מגע שהוא ככולו הוי אומר זה היסטו:\",3,0],[8,377,8,3,\"וכן כלי חרס שהוא נבוב וכו'. בפ\\\"ב דעדיות (משנה ה') לפסין אירניות שהן טהורות באהל המת וטמאות במשא הזב ופי' רבינו שהן מחבתות ועושין אותם מזדווגות וכשנשלם בישולם חולקים אותם באמצע ונעשית שתי מחבתות וכו' וקודם חילוקם וכו' מתטמאות במשא הזב ר\\\"ל כשנשא אותם הזב ונדנד אותם ואינם מתטמאות באהל המת והטעם בזה שכלי חרס לא יטמא במת ולא בשרץ ולא בזולתם אלא מאוירו וכו' זולתי בטומאת הזב בלבד ר\\\"ל כשנטמא במשא הזב וכו' ולשון התוספתא אין טומאה לכלי חרס אלא מאוירו ובהיסט הזב ובשביל אלה העיקרים אמרנו באלה הלפסין קודם חילוקם כיון שאין להם אויר ולא דרך פתח אלא כמו כדור נבוב שאינן מתטמאים באהל המת ומתטמאות במשא הזב עכ\\\"ל. ובספרי רבינו כתוב כפרור והוא ט\\\"ס וצריך להגיה ולכתוב במקומו ככדור:\",4,0],[8,377,8,3,\"וכן מחט שהיתה בלועה בתוך העץ וכו'. בפ\\\"ט דכלים מלמד שבלע את הדרבן ולבינה שבלעה את הטבעת וכו' הסיטן הזב נטמאו. ותמיה לי מאי וכן דהא קמא הוי חידושא טפי שהוא מציל באהל וזה אינו מציל:\",5,0],[8,377,8,4,\"זב שהכניס ידו וכו' שאין הנדה וכיוצא בה מטמאים לאיברים. נראה שרבינו מפרש כן מה שאמרו ריש פרק ר״ע (שבת דף פ״ב ע״ב) דנדה אינה לאיברים:\",1,0],[8,377,8,4,\"וכתב הראב\\\"ד על דברי רבינו זה אינו מחוור אצלי כי מאחר שאויר מטמא במגע וכו'. ואין בזה השגה על רבינו שפירושים שונים הם ורש\\\"י מפרש פירוש שלישי:\",2,0],[8,377,8,5,\"זב שהיה קנה אחוז בתוך קומטו וכו'. בפרק יוצא דופן (נדה דף מ״ג) אמר ריש לקיש קנה בקומטו של זב והסיט בו את הטהור טהור קנה בקומטו של טהור והסיט בו הזב טמא מ״ט דאמר קרא כל אשר יגע בו הזב וידיו לא שטף זהו היסטו של זב שלא מצינו לו טומאה בכל התורה כולה ואפקיה רחמנא בלשון נגיעה למימרא דהיסט ונגיעה כידיו מה התם מאבראי אף הכא מאבראי:\",1,0],[8,377,8,6,\"הזב בכף מאזנים וכו'. בפ\\\"ד דזבים הזב בכף מאזנים ומשכב ומושב כנגדו כרע הזב טהורים כרעו הם טמאים ופירשו רבינו ורבינו שמשון טהורים דקתני רישא היינו טהורים מדין משכב אבל טמאים הם משום היסט ובסיפא טמאים משום משכב לפי שכבר נתלה הזב במשכב ההוא והוא אחד מחמשה דרכים שהזב מטמא את המשכב כמו שנתבאר בפרק שביעי:\",1,0],[8,377,8,6,\"היה בכף שנייה שאר הכלים וכו'. שם הזב בכף מאזנים ואוכלים ומשקים בכף שנייה טמאים ופירש רבינו אין חילוק בכאן בין כרע הזב לכרעו האוכלים [טהורין שהרי אוכלים] טמאים בהיסט הזב דהיינו ראשון לטומאה ודבר ידוע דאוכלים ומשקים לאו דוקא:\",2,0],[8,377,8,7,\"הזב וטהור וכו'. בפרק ג' דזבים.\",1,0],[8,377,8,7,\"ומ״ש והוא האילן שאין בעובי עיקרו רובע הקב. בפרק המקבל (בבא מציעא דף ק״ה ע״ב):\",2,0],[8,377,8,7,\"ומ\\\"ש והוא שנחבא בה ודוחק אותה תזוז בו. שם כל שנחבאת בחזיונה ומפרש רבינו בחזיונה כשאוחז בה והיא נחבאת תוך ידו וכופף אותה היא מזזת אותו ולזה קורא כחה רע. ואף ע\\\"פ שבמשנה שנו דעלו בסולם צורי טהור כלומר אפילו אם אינו קבוע במסמר לא חשש רבינו להזכירו משום דכי ניזיל בתר טעמא ממילא משמע:\",3,0],[8,377,8,8,\"זב וטהור שהיו שניהם כאחד וכו'. בפ\\\"ג דזבים וכחכמים:\",1,0],[8,377,8,11,\"זב שנישא מקצתו על הטהור וכו' וכן חיבורי הזב שנישאו על הטהור. בפ\\\"ה דזבים ופירש שם רבינו שהכוונה לומר שאין אנו צריכין שינשא רובו של זב על הטהור או רובו של טהור על הזב כי אם במשכב ומושב אבל באדם אפילו מקצת נושא או מקצת נישא טמא. ובתוספתא ואלו הן מקצתן ראשי אצבעות ידים ורגלים כלומר אפילו זה יקרא מקצת ובת\\\"כ דריש לה מקראי.\",1,0],[8,377,8,11,\"ומ\\\"ש ואלו הם החיבורים וכו'. תוספתא בפרק [ה'] דזבים:\",2,0],[8,377,9,1,\"דבר שהיה מחובר בארץ וכו' עד וכן כל כיוצא באלו. בפרק רביעי דזבים.\",1,0],[8,377,9,1,\"ומה שכתב זה הכלל כל שנפל מכח היסטו טמא מכח הרעדה טהור. תוספתא בפרק [ד'] ואיתיה בפרק בכל מערבין וכתוב בספרים או הסיר והוא ט\\\"ס וצריך לכתוב במקומו או הניד:\",2,0],[8,377,9,2,\"תנור שהיתה הפת דבוקה וכו'. תוספתא דזבים פ\\\"ד:\",1,0],[8,377,9,3,\"אין המשכב או המרכב מטמא כלים וכו'. בפ\\\"ה דזבים כל הנושא ונישא על גבי המשכב טהור חוץ מן האדם ותנן תו התם ככר של תרומה שהוא נתון על גבי המשכב והנייר בינתים בין מלמעלה בין מלמטה טהור.\",1,0],[8,377,9,3,\"ומ\\\"ש וכן אם הסיט וכו'. פשוט הוא דכיון דאינו מטמא במשא לא יטמא בהיסט:\",2,0],[8,377,9,4,\"הזב והטהור שישבו בספינה קטנה היכולה להמיט באדם אחד או באסדא או שרכבו ע\\\"ג בהמה. כך היא הנוסחא הנכונה בדברי רבינו והיא משנה ברפ\\\"ג דזבים:\",1,0],[8,377,9,4,\"וכן נדה שישבה עם הטהורה וכו'. ברפ\\\"ד דזבים רבי יהושע אומר נדה שישבה עם הטהורה במטה כפה שבראשה טמאה מדרס ישבה בספינה כלים שבראש הנס שבספינה טמאים מדרס וכתב רבינו שם בפירוש המשנה הנזכר רבי יהושע חולק על סתם [המשנה] הקודמת אשר אין מטמא מדרס (אלא) כשהם יושבים בספינה או באסדא אלא בגדים שעליו שאפשר שידרוס הטמא אבל כלים שבראש הטהור אינם מדרס וכן לא ישים ת\\\"ק כלים שבראש הנס מדרס ואין הלכה כרבי יהושע:\",2,0],[8,377,9,4,\"והראב\\\"ד כתב על דברי רבינו תמה אני איך עירב ובילבל את הדברים וכו'. ואין בזה השגה על רבינו שפירושו מחוור דרבי יהושע לאיפלוגי אתנא קמא אתא ולשון רבי יהושע אומר הכי משמע ולא מצינו בשום מקום חילוק בין זב לנדה ומאי דנקט רבי יהושע נדה איכא למימר משום דבעי למתני שישבה עם הטהורה במטה שזה שייך בנקבה טפי מבזכר. ומ\\\"ש הראב\\\"ד דאין כאן טומאת ספק אלא כאותה ששנינו וכו' כדאיתא בנדה י\\\"ל דמשם נלמד דגמרא לאו כרוכלא ליזיל וליתני:\",3,0],[8,377,9,5,\"הנדחק בריחיים וכו'. תוספתא דאהלות פרק תשיעי אלא שהיא כתובה בשיבוש שכתוב בה שאין עוקרים במקום שעוקרים:\",1,0],[8,377,9,5,\"וכתב הראב\\\"ד מצאתי נוסחא באי זה ריחים אמרו וכו'. ואף על פי שנוסחת תוספתא דידן שעוקרים אותה ודוחפין אותה ממקומה כבר יכול להתפרש בה פירוש רבינו:\",2,0],[8,377,10,1,\"עם הארץ אע\\\"פ שהוא ישראל וכו'. משנה פ\\\"ב דחגיגה (דף י\\\"ח ע\\\"ב) בגדי ע\\\"ה מדרס לפרושים.\",1,0],[8,377,10,1,\"ומ\\\"ש ואם נגע בכלי חרס מאוירו טימאהו. כלומר דאילו נגע בו מאחוריו טהור דאין כלי חרס מקבל טומאה מאחוריו אבל אם הכניס ידו באוירו אע\\\"פ שלא נגע בו טימאהו.\",2,0],[8,377,10,1,\"ומ\\\"ש ושורפין את התרומה על מגען אף על פי שטומאתן בספק. בפרק ד' דטהרות על ששה ספיקות שורפין את התרומה וחד מינייהו על ספק בגדי עם הארץ.\",3,0],[8,377,10,1,\"ומה שכתב ואינם נאמנים על הטהרות. פשוט בכמה מקומות בגמרא מהם בפרק חומר בקודש (חגיגה דף כ״ב כ״ג) ובפרק עד כמה (בכורות דף ל' ע״ב).\",4,0],[8,377,10,1,\"ומ\\\"ש ולעולם הוא בחזקה זו וכו' עד ובטהרתן. בפ' עד כמה.\",5,0],[8,377,10,1,\"ומ\\\"ש ושלא יקח מע\\\"ה דבר לח וכו' עד ובכסותו. בפ\\\"ב דדמאי ואע\\\"פ ששם שנינו שצריך שיקבל עליו שלא ימכור לע\\\"ה לח ויבש השמיטו רבינו משום דההיא כמ\\\"ד אסור לגרום טומאה לחולין שבא\\\"י ורבינו סובר שאינה הלכה כמו שנתבאר בפ\\\"ח מהלכות בכורים:\",6,0],[8,377,10,6,\"הבא לקבל דברי חבירות וכו' עד אין צריכין לקבל דברי חבירות כבתחילה. פרק עד כמה (בכורות דף ל' ע״ב) והטעם שאם אמר איני מקבל אלא לטהרת ידים מקבלים מפני שאינו משייר דבר שלם שהרי מקבל עליו נט״י שהוא עיקר אכילת חולין בטהרה אבל אם קיבל לטהרות ולא לנט״י הוי כמשייר הכל כי העיקר הוא זה.\",1,0],[8,377,10,6,\"ומ\\\"ש כשמקבלים אותו חוששין לו כל שלשים יום וכו'. שם עד כמה מקבלין אותו וכו':\",2,0],[8,377,10,7,\"עם הארץ שקיבל עליו דברי חבירות וכו'. תוספתא פרק תשיעי דטהרות.\",1,0],[8,377,10,7,\"ומ\\\"ש ונשאל החבר וכו'. בסוף פרק עד כמה (בכורות דף ל' ל\\\"א) רואה את קדשיו ומעשרותיו ונשאל על טהרותיו:\",2,0],[8,377,10,8,\"חבר שנעשה גבאי וכו'. בסוף פרק עד כמה (בכורות דף ל\\\"א):\",1,0],[8,377,10,9,\"עם הארץ שקיבל עליו וכו'. שם וכחכמים.\",1,0],[8,377,10,9,\"ומה שכתב וכל החשוד לחמור וכו'. שם במשנה ובגמרא (דף ל'):\",2,0],[8,377,10,10,\"חבר שנחשד על הטהרות וכו'. נלמד מדין מי שיצאת טריפה מתחת ידו:\",1,0],[8,377,10,11,\"החשוד על השביעית וכו'. משנה וגמרא פרק עד כמה (בכורות דף ל'):\",1,0],[8,377,10,11,\"וכל החשוד על דבר וכו'. פרק כל פסולי המוקדשין (בכורות דף ל״ה) במשנה פלוגתא דר״מ ורשב״ג ופסק כרשב״ג שכל מקום ששנה רשב״ג במשנתנו הלכה כמותו. והראב״ד כתב על דברי רבינו כבר כתבתי עליו במקום אחר שאין זה כלום עכ״ל. והוא בפרק י״ב מהלכות מעשר ובפרק ח' מהלכות שמיטה ובפי״א מהלכות עדות ושם הלצתי בעד רבינו:\",2,0],[8,377,11,1,\"כבר ביארנו. בסוף פרק י\\\"ג מהלכות פרה:\",1,0],[8,377,11,1,\"וכן נאמנים הם על טהרת יין ושמן. משנה בפרק חומר בקדש (חגיגה דף כ\\\"ד ע\\\"ב):\",2,0],[8,377,11,1,\"וכן נאמנים הם על התרומה וכו' בשעת הגיתות והבדים. גם זה משנה שם:\",3,0],[8,377,11,3,\"עם הארץ שנעל בית בדו וכו'. נראה שזו היא ששנינו בפ\\\"ט דטהרות הגומר את זיתיו ושייר קופה אחת יתננה לעני כהן דברי ר\\\"מ ר\\\"י אומר יוליך לו את המפתח מיד ר\\\"ש אומר מעת לעת ופסק כרבי יהודה ואע\\\"ג דבתוספתא קתני ברבי יהודה כל אותו יום לא חש לה רבינו דמשמע דמשבשתא היא דפליגא אמתניתין.\",1,0],[8,377,11,3,\"ומ\\\"ש ואם לא עשה כן וכו':\",2,0],[8,377,11,4,\"הביא לו עם הארץ חבית של תרומה וכו'. משנה פרק חומר בקדש שם:\",1,0],[8,377,11,4,\"אפילו בשעת הגיתות והבדים וכו'. בפרק חומר בקדש (דף כ\\\"ה) תנא אין נאמנין לא על הקנקנים ולא על התרומה קנקנים דמאי אי קנקנים דקדש מגו דנאמן אקדש נאמן נמי אקנקנים אלא אקנקנים דתרומה פשיטא השתא אתרומה אינו נאמן אקנקנים נאמן אלא בריקנים דקדש ובשאר ימות השנה ובמלאים דתרומה ובשעת הגיתות ורבינו משוה קנקנים ריקנים דקדש לתרומה שגם גבי תרומה כתב אין נאמנים על הכלי הריקם לומר שהוא טהור לתרומה משמע שאינו גורס במלאים דתרומה אלא בריקנים דקדש בכל השנה ודתרומה בשעת הגיתות אבל קשה לזה ששם הקשו על זה מדתנן כדי יין וכדי שמן המדומעות מאי לאו מדומעות דתרומה כלומר וקתני מתניתין דנאמנים עליה בשעת הגיתות והבדים וקודם שבעים יום ומשני במדומעות דקדש ובמטהר טבלו ליטול ממנו נסכים ומשמע דמלאים ממדומע קאמר ומקשה אמאי דאמר דמלאים דתרומה בשעת הגיתות אינו נאמן וכגירסא דספרים דידן:\",2,0],[8,377,11,4,\"וכתב הר\\\"י קורקוס ז\\\"ל שצ\\\"ל לדעת רבינו שהוא ז\\\"ל מפרש דלעולם בריקנים מיירי והמקשה היה מפרש לה בריקנים שמכניסים בהם המדומע ומאן דמשני מפרש לה בריקנים לקדש דנאמן לומר שהוא טהור ויכול חבר לקחת אותו בחזקת טהור דאילו מלא בכל השנה נאמן ולמה אמרו בין הגתות וקודם שבעים יום לבד:\",3,0],[8,377,11,5,\"כלי שהיה בתוכו יין וכו'. משנה וגמרא שם ודברי רבינו כפירוש התוספות:\",1,0],[8,377,11,5,\"במה דברים אמורים בשאר א\\\"י וכו'. משנה שם (דף כ\\\"ו) בירושלים נאמנים על הקדש ובגמרא תנא נאמנים על כלי חרש [גסין] לקדש וכ\\\"כ למה שאין עושין כבשונות בירושלים ופירש\\\"י על כלי חרס הגסים וכל שכן הדקים ובהדיא תניא בירושלים נאמנים על טהרת כל הכלים לקודש וכל כך למה מהדר אף על הדקים.\",2,0],[8,377,11,5,\"ומ\\\"ש אף ע\\\"פ שהמשקים שבתוכו טמאים אפי' היה בגדו שהוא מדרס וכו'. שם וכרבי יוחנן:\",3,0],[8,377,11,6,\"מן המודיעית ולפנים וכו'. משנה בפרק חומר בקדש (דף כ\\\"ה ע\\\"ב) ובגמרא (דף כ\\\"ו) תנא נאמנים בכלי חרס הדקים לקודש ופירש\\\"י בגמרא מן המודיעים ולפנים שאין עושין כבשונות בירושלים לא לדקים ולא לגסים ומיהו בדקים הוצרך לאנשי ירושלים דכל יחיד ויחיד נסכו בביתו לכך הוסיפו להם טהרה ליחידים מגבול מודיעית אבל בעלי הלשכה המספיקים נסכים לצבור די להם בנכנסים לתוך העיר ולשם בלבד האמינום על החביות א\\\"נ יחידים צריכין לדקים אף לבישול שלמיהם יום יום עכ\\\"ל. ורבינו שסתם וכתב מן המודיעית ולפנים נאמנים על כלי חרס ולא חילק בין דקים לגסים יש לתמוה עליו וכבר השיגו הראב\\\"ד וכתב א\\\"א בגמרא מפרש שאינו נאמן אלא על כלי חרס הדקים לקודש עכ\\\"ל. וליישב דברי רבינו אפשר שדקדק ולא כתב כל כלי חרס לומר דלא על כל כלי חרס קאמר וסתם כלי חרס הוו דקים וזה דוחק ויותר נכון לומר שטעמו משום דעל ההיא דתנא נאמנים על כלי חרס הדקים אמר ר\\\"ל והוא שניטלים בידו אחת ור\\\"י אמר אפילו שאין ניטלים בידו אחת ומשמע לרבינו דר\\\"ל מפורש דדקים דוקא ור\\\"י מפרש דלאו דוקא דהוא הדין לגסים כדקתני באידך ברייתא דבחד ברייתא אשמעינן נאמנות דדקים ובאידך ברייתא אשמעינן נאמנות דגסים והוה ליה כאילו תנא נאמנים על כלי חרס בין דקים בין גסים:\",1,0],[8,377,11,6,\"והמודיעית עצמה פעמים כלחוץ וכו'. שם תנא מודיעית [עצמה] פעמים כלפנים פעמים כלחוץ כיצד קדר יוצא וחבר נכנס כלפנים שניהם נכנסים או שניהם יוצאים כלחוץ. ופירש\\\"י מודיעית הכרך עצמו. קדר יוצא מלפנים מן המודיעית ונכנס למודיעית וחבר בא מחוץ למודיעית ונכנס למודיעית. כלפנים מותר ליקח ממנו שהקדר לא יחזור עוד לאחריו ואם לא עכשיו יקח אימתי. שניהם נכנסים מחוץ למודיעית ובאו בתוך הכרך. כלחוץ אלא ימתין עד שיהא מן הכרך ולפנים וכן שניהם יוצאים הואיל ומצאו לפנים ושם לא לקח ממנו לא יקח עוד וכל שכן קדר נכנס וחבר יוצא הואיל וסוף הקדר ליכנס לפנים יחזור החבר הצריך ליקח ויקח:\",2,0],[8,377,11,7,\"קדר שהביא קדירות וכו'. משנה שם הקדר שהוא מוכר [הקדירות] נכנס לפנים מן המודיעית הוא הקדר והן הקדירות והן הלוקחין נאמן יצא אינו נאמן:\",1,0],[8,377,11,8,\"הלוקח כלי חרס מן הכבשן וכו'. בריש פ\\\"ה דפרה איפליגו תנאי במילתא ומייתי לפלוגתא בתוספתא פ\\\"ד דפרה ומסיים בה זו משנה ראשונה רבותינו אמרו פותח ונוטל ואינו נמנע והחבר בא אפילו לאחר שלשה ימים ונוטל ופסק כמשנה אחרונה ותמהני עליו דכיון דלא הוזכרה משנה אחרונה במתניתין משמע דס\\\"ל לרבי דליתא למשנה אחרונה והיאך הניח דברי רבי במתניתין ותפס דברי התוספתא וכעין מה שאמרו אם רבי לא שנאה רבי חייא מנא ליה ויש לתמוה על הראב\\\"ד שלא השיגו בזה:\",1,0],[8,377,11,8,\"ודע דמתניתין הכי איתא המביא כלי חרס לחטאת טובל ולן על הכבשן וכו' ולתרומה פותח את הכבשן ונוטל רבי שמעון אומר מן הסדר השני רבי יוסי אומר מן הסדר השלישי ונראה שרבינו מפרש שדברי תנא קמא דמתניתין דאמר פותח את הכבשן ונוטל היינו דברי רבותינו דתוספתא וה\\\"ק פותח את הכבשן ונוטל ואינו נמנע אלא שבמשנה קיצרו בלשון משום דממילא משמע ויש לדקדק בלשון התוספתא מאי והחבר בא וכו' דבכלל ואינו נמנע הוא. ונראה לי שוי\\\"ו זו היא במקום שי\\\"ן והכי קאמר נוטל ואינו נמנע שהחבר בא אפילו אחר שלשה ימים ונוטל:\",2,0],[8,377,11,9,\"טומאת ע\\\"ה ברגל וכו'. בס\\\"פ חומר בקדש (דף כ\\\"ז) ובפרק בנות כותים:\",1,0],[8,377,11,10,\"הפותח את חביתו ברגל וכו'. משנה שם וכחכמים:\",1,0],[8,377,11,10,\"ודע דאמרינן בגמרא יתיב רב אמי וכו' עד שאין צריך להניחה ומשמע לכאורה דלמסקנא לרבנן מותר להניחה ורבינו לא פסק כן משום דמשמע ליה דבדרך דחייה איתמר ומה שרצה להכריע משום דרבי יהודה יגמור קאמר איכא למידחי דאורחא דמילתא נקט דכיון שיש לו רשות לגמור אין לו צורך להניחה לרגל אחר אי נמי דעדיף היתרא דיגמור דהוי בשעת איסור מלהניחה דלא הוי אלא בשעת היתר וא\\\"נ האי דקתני לא יניחנה רבנן הוא:\",2,0],[8,377,11,11,\"אחר הרגל במוצאי יום טוב וכו'. גם זה משנה שם:\",1,0],[8,377,11,11,\"וכל הכלים טעונין טבילה וכו'. משנה שם כל הכלים שהיו במקדש טעונין טבילה חוץ ממזבח הזהב ומזבח הנחושת מפני שהם כקרקע דברי רבי אליעזר וחכמים אומרים מפני שהם מצופין ובגמרא (דף כ\\\"ז) מפני שהם מצופין אדרבא כיון דמצופין נינהו מיטמו וכו' ופסק רבינו כרבנן וכתירוצא בתרא דפשטא דמתני' הכי משמע וגם כיון דבתרא הוא הוי עיקרא ועיין במה שאכתוב בפרק רביעי מהלכות כלים:\",2,0],[8,377,11,12,\"ע\\\"ה שאמר טהור אני וכו':\",1,0],[8,377,12,1,\"המפקיד כלים אצל ע\\\"ה וכו'. בפ\\\"ח דטהרות.\",1,0],[8,377,12,1,\"ומ\\\"ש או שנתן כלי לאומן ע\\\"ה. תוספתא פ\\\"ח דטהרות המוסר כלים לאומנים ע\\\"ה טמאים מדרס וטמא מת ומשמע ודאי דהיינו בסתמא אבל אם מכירו שהוא אוכל בתרומה טהורים מטמא מת אבל טמאים מדרס וכדתנן במתניתין גבי המפקיד כלים אצל ע\\\"ה והתוספתא סמכה בזה על מה ששנינו במשנה גבי מפקיד דמאי שנא:\",2,0],[8,377,12,1,\"וכתב הראב\\\"ד הרי אלו טמאים א\\\"א מצאתי שתי נוסחאות וכו'. ונראה מדבריו שהיה גורס בדברי רבינו במפקיד ובנותן כלי לאומן הרי אלו טמאים מדרס וטהורים מטמא מת וניחא ליה באומן דהכי מתנייא בתוספתא בגירסא הנכונה לדעת הראב\\\"ד וקשיא ליה על אותה גירסא מדתנן גבי מפקיד טמא מדרס וטמא מת ומ\\\"ש מאומן והשתדל למצוא טעם לחלק ביניהן כי האומן מקפיד יותר שלא יגע טמא מת בכלים שנתנו לו וסיים דבריו שעירב מפקיד עם אומן לומר שאינם טמאים מדרס טעה כלומר דבמפקיד הל\\\"ל דטמא מת נמי הוי וכל זה בנוי על הגירסא המשובשת שנזדמנה לו בספרי רבינו והגירסא האמיתית כמ\\\"ש בספרינו על מפקיד ונותן כלי לאומן ע\\\"ה הרי אלו טמאים מדרס וטמא מת ואם מכירו שהוא אוכל בתרומה טהורים מטמא מת וכבר ביארתי טעמו:\",3,0],[8,377,12,2,\"המניח כליו בפני ע\\\"ה וכו' עד שאין לו רשות שיכנס. תוספתא פ\\\"ח דטהרות וגורס רבינו המניח כליו וכו' טמאים מדרס וטהורים מטמא מת:\",1,0],[8,377,12,2,\"וכתב הר\\\"י קורקוס ונראה שטעמו דכיון שלא הפקידן אינן ברשותו אלא לענין מדרס שבקל יהיו מדרס דמכל מקום ברשותו הם קצת כיון שא\\\"ל שמור לי את אלו אבל לענין טומאת מת לא כי אינם ברשותו לגמרי כההיא דהמפקיד אצל ע\\\"ה או נתן לאומן ע\\\"ה אבל נתנם על כתפו הוי מפקיד לגמרי ונפקד גמור והוו ברשותו לכל דבר עכ\\\"ל:\",2,0],[8,377,12,2,\"ומ\\\"ש הניח גיתו וביתו. ט\\\"ס הוא וצריך להגיה ולכתוב בורו במקום ביתו:\",3,0],[8,377,12,3,\"המוסר מפתח ביתו לע\\\"ה וכו'. משנה פ\\\"ז דטהרות ואיתא בפ' בתרא דע\\\"ז (דף ע' ע\\\"ב):\",1,0],[8,377,12,4,\"המניח כליו וכו'. משנה פ\\\"ז דטהרות המניח כליו בחלון של אורייארין ר\\\"א בן עזריה מטהר וחכ\\\"א עד שיתן לו מפתח או חותם או עד שיעשה לו סימן ופירש רבינו אורייארין הבלנים שבמרחצאות ויש במרחצאות חלונות ישימו כל איש לבושו בחלון מהם וידוע שהלכה כחכמים:\",1,0],[8,377,12,4,\"ומ\\\"ש אפילו מצא החותם מקולקל וכו'. תוספתא פרק ח' דטהרות:\",2,0],[8,377,12,5,\"המניח ע\\\"ה בתוך ביתו וכו'. משנה פ\\\"ז דטהרות ופירש רבינו כבר ידעת שאוכלין ומשקין טומאתן קלה וכן כלי חרס לא יהיה אב הטומאה ולכן גזרו שיטמא כל מה שבבית מאלה המינים וכו' אמנם המשכבות והמושבות אשר הם אב הטומאה לא נדון עליהן שהם שבו אב הטומאה אלא כשאין בע\\\"ה רואה מי שיכנס בבית ולא מי שיצא ממנו ונפרד ע\\\"ה בשמירה וכן כלי חרס המוקפים צמיד פתיל לא יטמאו במגע אלא במשא הזב וכו' ולזה לא נדון בו בטומאה עד שיפרד ע\\\"ה בו מבלי פחד ולא נשאר לו מי שיראהו אפילו כרות ידים ורגלים וכו' להיות הבית מגיע ברשות ע\\\"ה שב כמו ביתו של ע\\\"ה שהכל טמא עכ\\\"ל:\",1,0],[8,377,12,6,\"חבר שהיה ישן וכו' עד הרי הם טמאים. תוספתא פ\\\"ח דטהרות:\",1,0],[8,377,12,9,\"המניח עם הארץ בתוך ביתו וכו'. משנה פ\\\"ז דטהרות.\",1,0],[8,377,12,9,\"ומ\\\"ש הניחו ישן ומצאו ער וכו'. שם וכחכמים:\",2,0],[8,377,12,9,\"וכן המניח אומנים וכו'. ג\\\"ז שם וכחכמים:\",3,0],[8,377,12,10,\"אשת חבר שהניחה וכו'. גם זה שם וכחכמים:\",1,0],[8,377,12,11,\"האשה שנכנסה וכו' וכן האשה שיצאה וכו'. ג\\\"ז שם וכחכמים:\",1,0],[8,377,12,12,\"גבאי מלכות שנכנסו. ג\\\"ז שם והובאה בפרק חומר בקדש (דף כ\\\"ו) וגירסת רבינו הגבאים שנכנסו לתוך הבית הבית טמא אם יש עמהם עכו\\\"ם נאמנים לומר לא נגענו וכתב רבינו סבת זה מה שזכרו בתוספתא מפני שאימת עכו\\\"ם עליהם.\",1,0],[8,377,12,12,\"ומ\\\"ש בד\\\"א בזמן שיש שם עדים וכו'. פשוט דארישא קאי והוא בתוספתא דטהרות פ\\\"ח וקתני התם אם יש עכו\\\"ם עמהם אע\\\"פ שהמשכון בידם אע\\\"פ שהעכו\\\"ם מעיד בהם שנכנסו ואמרו לא נגענו הרי אלו נאמנים מפני שאימת עכו\\\"ם עליהם:\",2,0],[8,377,12,13,\"הגנבים שנכנסו וכו'. משנה פ\\\"ז דטהרות:\",1,0],[8,377,12,14,\"הגבאים והגנבים שעשו תשובה וכו'. בפ' חומר בקדש שם משנה וגמרא גבי גנבים וכתב רבינו דה\\\"ה לגבאי מלכות אם עשו תשובה:\",1,0],[8,377,12,15,\"המניח את ביתו פתוח וכו'. בפרק ח' דטהרות.\",1,0],[8,377,12,15,\"ומ\\\"ש אפילו הניחו נעול ומצאו פתוח וכו'. שם וכחכמים:\",2,0],[8,377,12,16,\"קורדום שאבד בבית וכו'. פ\\\"ק דפסחים עלה י' וכרבנן:\",1,0],[8,377,12,16,\"כתב רבינו שנשאל אמאי הכא תלינן באדם טמא ומטמאינן לכל טהרות שבבית מספק מ\\\"ש מהא דאמרינן בפ\\\"ק דנדה (דף ד') גבי ככר של תרומה שנתונה ע\\\"ג הדף ומדף טמא נתון תחתיה אע\\\"פ שאם נפלה א\\\"א [לה שתפול] אא\\\"כ נגעה [בדף ובא ומצאה במקום אחר] טהורה וכו' עד שיאמר ברור לי שלא נכנס אדם לשם א\\\"ר אילעאי לא נצרכה אלא למקום מדרון [וכן הקשו תוספות פסחים (י':) ד\\\"ה שאני יע\\\"ש] והשיב גבי קרדום אמרינן אדם נכנס שם ונטל הקרדום ועשה בו צרכיו והחזירו לזוית אחרת והרי זה בחזקת רשע ששואל שלא מדעת גזלן הוא והרשע פחות מעם הארץ שהוא בחזקת טמא אבל בככר אין לומר כן שאין אדם שואל ככר להחזירו בעצמו שאין בדבר תועלת שהרי אינו כלי שיעשה בו מלאכה ואילו נכנס לבית זה אדם רשע היה נוטלו והולך לו ולפיכך אנו אומרים לא נכנס כאן אלא חבר שחזקתו טהור:\",2,0],[8,377,12,17,\"הדר עם עם הארץ בחצר וכו'. משנה רפ\\\"ה דטהרות וכרבי יוסי:\",1,0],[8,377,12,18,\"חבר שהיתה לו מחיצה וכו'. תוספתא רפ\\\"ט דטהרות:\",1,0],[8,377,12,19,\"חבר שהיה גגו למעלה. תוספתא פרק ח' דטהרות וכת\\\"ק.\",1,0],[8,377,12,19,\"ומ\\\"ש ולא משום יין נסך. הכי משמע בפרק בתרא דע\\\"ז (עלה ע'):\",2,0],[8,377,12,19,\"היו הגגות זה בצד זה וכו'. תוספתא פ\\\"ט דטהרות וטעמא משום דכיון שהם זה בצד זה הרי הם כחצר אחד שפושט ידו ואין מכלים דבר ומינה נשמע דהוא הדין לגגו של עם הארץ למעלה דחיישינן שמא יפשוט ידו ויגע שיטען שנפל איזה דבר מגגו לשל חבר ולכך פושט ידו לבקשו משא\\\"כ כשגגו של חבר למעלה שאין לעם הארץ שום טענה לפשוט ידו שם משום הכי לא חיישינן זהו יישוב דברי רבינו אבל קשה דבפרק בתרא דע\\\"ז (דף ע' ע\\\"ב) גרסינן וגגו של חבר בצד גגו של עם הארץ אותו חבר שוטח שם פירות ומניח שם כלים ואע\\\"פ שידו של עם הארץ מגעת לשם ורב ור\\\"י איפליגו התם בחצר החלוקה במסיפס דבסמוך ור\\\"י סבר שאע\\\"פ שידו של עם הארץ מגעת לשם ומדמה לה להא דגגו של חבר בצד גגו של עם הארץ אע\\\"פ שידו של עם הארץ מגעת לשם טהורות הטהרות וי\\\"ל דההיא דאותו חבר שוטח שם פירות וכו' היא סברת רשב\\\"ג בתוספתא דפליג את\\\"ק ומותיב מינה לר\\\"י לאוקומי לר\\\"י ככ\\\"ע אבל לענין הלכה נקטינן כתנא קמא:\",3,0],[8,377,12,20,\"שתי חצירות וכו'. בפירקא בתרא דע\\\"ז שם:\",1,0],[8,377,12,21,\"חצר החלוקה במסיפס וכו'. כך היא הגירסא הנכונה ובספרים כתוב החלוקה בספינה וט\\\"ס הוא. וכבר כתבתי בסמוך דבפ' בתרא דע\\\"ז איפליגו רב ור\\\"י במילתא ופסק כר\\\"י ופירוש מסיפס מחיצה נמוכה:\",1,0],[8,377,12,22,\"חבר שנפל דליו וכו'. משנה פ\\\"ח דטהרות וכתב רבינו ולא יסתפק עליך אמרו בדלי טמא אע\\\"פ שהוא בתוך הבור לפי שהוא מעת שהגיע ברשות ע\\\"ה שב טמא מת והטעם שלא חילקו חכמים בכלים שברשות עם הארץ:\",1,0],[8,377,12,23,\"אשת עם הארץ שנכנסה וכו'. משנה פרק ח' דטהרות שם וכתב רבינו אם נכנסה שלא ברשות אלא להוציא ענין פלוני ותצא הנה לא הורשת להשתמש ולגעת לאשר בבית כי אימת בעל הבית עליה ולא תשלח ידה לדבר:\",1,0],[8,377,12,23,\"קדר חבר שהכניס קדירותיו. משנה ריש פרק ז' דטהרות וכתנא קמא:\",2,0],[8,377,12,23,\"ומה שכתב במה דברים אמורים בשהניחן סמוך לר\\\"ה וכו'. בפ\\\"ב דכתובות (דף כ\\\"ד ע\\\"ב). וכתב הראב\\\"ד מוכיחין שהונחו למכור א\\\"א אין זה הטעם יפה וכו'. ואיני יודע מה ראה הראב\\\"ד בטעם זה לטעון עליו שהרי הכל יודעים שהביא למכור וכי כל המביאים קדרות מביאים למכור והלא כבר אפשר שמביאם לעצמו או לחבירו שצוה להביאם לו ומה שנתן טעם הראב\\\"ד בשכלי אומנותו בידו הכל באים לראות האומניות ועל ידי כן ממשמשין בקדירות איני יודע מה חידוש יש בכלי אומנות כלי חרס עד שיבאו הכל לראותם. ורש\\\"י פירש כמו שפירש רבינו:\",3,0],[8,377,12,23,\"חבר שהניח וכו'. תוספתא דטהרות פ\\\"ט:\",4,0],[8,377,13,1,\"כהן שטיהר כליו וכו'. בפרק ז' דטהרות המניח כליו מגת זו לגת הבאה כליו טהורים ובישראל עד שיאמר בלבי היה לשמרם:\",1,0],[8,377,13,2,\"הרוצה לעשות יינו בטהרה וכו' וצריך לעמוד על האומנים וכו'. בפ\\\"י דטהרות וכרבי יוסי:\",1,0],[8,377,13,2,\"יצאו חוץ לפתח בית הבד וכו'. ג\\\"ז שם:\",2,0],[8,377,13,3,\"הבדדין והבוצרים וכו'. שם:\",1,0],[8,377,13,4,\"המטהר את הבדדין וכו'. שם וכרבי יוסי:\",1,0],[8,377,13,5,\"היו חמריו וכו'. ברייתא בסוף פרק ב' דחגיגה (דף כ' ע\\\"ב) ומקשה בגמרא מאי שנא רישא ומ\\\"ש סיפא ואסקה רבי יצחק נפחא רישא בבא להם דרך עקלתון ומשמע דה\\\"ק הב\\\"ע בשבעל הבית יכול לבא להם דרך עקלתון פתאום דמרתתי ואמרי השתא אתי. ויש לתמוה על רבינו למה השמיט מלהזכיר דרישא מיירי דוקא בשיכול לבא להם דרך עקלתון וצ\\\"ל שבכלל מ\\\"ש והם מפחדים ליגע ואומרים עכשיו יבא שהרי הוא יבא אחרינו היא דבא להם דרך עקלתון דאמר רבי יצחק נפחא לאו למימרא דבא דרך עקלתון דוקא בעינן שכל שהוא בא אחריהם הוי כבא להם דרך עקלתון שהרי הוא רואה והם אינם רואין אותו:\",1,0],[8,377,13,6,\"חבר שהיה לבוש בחלוק וכו'. תוספתא בפרק שמיני דטהרות שם:\",1,0],[8,377,13,6,\"היה סל על כתיפו וכו'. שם (דף כ') ובפרק שני דחגיגה בגמרא היה סל על כתיפו ומגריפה בתוך הסל [ואמר] היה בלבי על הסל ולא היה בלבי על המגריפה הכל טהור ומגריפה טמאה וכו'. ולטמא מגריפה לסל אין כלי מטמא כלי ולטמא מה שבסל וכו' באומר שמרתיה מדבר המטמאה ולא מדבר הפוסלה ופירש\\\"י הסל של תאנים על כתיפו ומגריפה הוא כלי ברזל וכו' שבו מבדילים תאנים המדובקות זו בזו. המטמאה הנותן לה טומאה לטמא אחרים. הפוסלה מלהשתמש בה טהרות לכתחילה אי נמי נ\\\"מ לאוכל הדבוק בה שהוא פסול באכילה ומכל מקום אם נגעה בטהרות אינה מטמאתן. וקשה שדברי רבינו הם בהיפך שבגמרא משמע שמה שבסל טהור ורבינו כתב שהוא פסול וליישב נראה לומר דרבינו קשיא ליה דאי כדפירש\\\"י קשה דלא הוה ליה למיתני מגריפה טמאה אלא מגריפה פסולה ותו איכא למידק מאי האי דפריך וליטמא מה שבסל מאן א\\\"ל דלא ליטמא דהא בברייתא לא אידכר אלא דינא דסל ומגריפה ועוד מאן א\\\"ל דאיכא תאנים בסל דילמא בסל ריקם מיירי לכך סובר רבינו דכיון דמגריפה להפריד תאנים המדובקים היא עשויה אין לה ענין עם הסל אלא א\\\"כ יש בו תאנים ומש\\\"ה פריך וליטמא מה שבסל וליתני הסל טהור ומה שבתוכו והמגריפה טמאים ומשני דלא מצי תני הכי משום דמה שבסל אינו טמא אלא פסול דהב\\\"ע באומר שמרתיה מדבר המטמאה כלומר הנותן לה כח טומאה שהאוכל שיגע בה יהיה טמא ויפסול את אחרים ולא מדבר הפוסלה כלומר מדבר שאינו מטמאה אלא לעשות האוכל שיגע בה פסול ולא יטמא האוכל ההוא את אחרים והשתא אתי שפיר דלא תני בברייתא דינא דמה שבתוך הסל דמאחר דקתני הסל טהור ומגריפה טמאה ממילא משמע שמה שבתוך הסל אינו לא טמא ולא טהור אלא פסול והשתא אתי שפיר דקאמר מגריפה טמא וסלקי דברי רבינו כהוגן. ודע שיש בספרי רבינו טעות סופר וכך היא הגירסא הנכונה והמגריפה טמאה וכל תרומה שבסל פסולה והוכרח רבינו לאוקומה בתרומה משום דאילו בחולין אין שני עושה שלישי:\",2,0],[8,377,13,6,\"היה משתמש מן החבית בטהרה וכו'. תוספתא בפרק שמיני דטהרות.\",3,0],[8,377,13,6,\"ומה שכתב ואם אמר בלבי היה לשומרה וכו'. כך יש ללמוד ממה ששנינו בברייתא פרק אין דורשין (חגיגה דף כ') גבי היה משמר החבית בחזקת יין ונמצא שמן:\",4,0],[8,377,13,6,\"נתחלפו לו כלים וכו'. בספ\\\"ג דחגיגה שם:\",5,0],[8,377,13,7,\"חבר שמת וכו'. תופסתא בפרק ט' דטהרות וכתב רבינו שמשון בפרק ח' דכלים דכיון דאפשר לתקן בטבילה לא חשו אם החמירו בהם ואפילו בכלי חרס דלא פלוג בכלים:\",1,0],[8,377,13,7,\"וכתב הראב\\\"ד כל זה אינו אלא לקודש או לתרומה אבל לחולין לא מחזקינן טומאה ואם כתב כן להשיג על רבינו שסתם ולא חילק כבר נודע שדרך רבינו לכתוב המשנה או התוספתא כצורתה. ועוד שאין דבריו מוכרחים שכבר אפשר דאף לחולין חששו:\",2,0],[8,377,13,8,\"מי שאמר לו עד אחד נטמאו טהרותיך וכו'. בפרק שלישי דקידושין (דף ס\\\"ה ע\\\"ב):\",1,0],[8,377,13,8,\"היה עושה עמו בטהרות או בזבחים וכו'. פרק הניזקין (גיטין דף נ\\\"ד:) וכאוקימתא דרבא ובסוף הלכות פסולי המוקדשין הארכתי בביאור דעת רבינו:\",2,0],[8,377,13,8,\"וכתב הראב\\\"ד נראה לי שאם היה עושה בשכר אפילו אחר כמה ימים נאמן וכו'. ואין בזה השגה על רבינו שלא ביאר שכבר נודע שדרכו להעתיק הגמרא כצורתה ודין הס\\\"ת כבר כתבו במקומו וממילא ילמוד אדם משם לכאן:\",3,0],[8,377,13,8,\"סליקו הלכות מטמאי משכב ומושב\",4,0],[8,378,1,1,\"הנבילה אב מאבות הטומאה. בריש כלים מני לה באבות הטומאה.\",1,0],[8,378,1,1,\"ומה שכתב ששיעורה בכזית. מפורש בכמה מקומות מהם פירקא קמא דאהלות ופרק העור והרוטב (חולין דף קי״ז ע״ב) ובתורת כהנים סוף פרשת שמיני יליף מדכתיב והאוכל מנבלתה יכבס בגדיו וטמא עד הערב לא בא אלא ליתן שיעור לנוגע ולנושא בכזית כמו האוכל ואיתיה פרק יוצא דופן (נדה דף מ״ב ע״ב). ודקדק רבינו לכתוב מבשרה למעט עצמות כדאיתא בפרק ו' דעדיות (משנה ג') ובסוף פרק בהמה המקשה (חולין דף ע״ז:) ובתורת כהנים פרשת שמיני:\",2,0],[8,378,1,1,\"ומה שכתב מטמא אדם וכלים במגע וכו'. בריש כלים ובתורת כהנים מייתי לה מדכתיב כל הנוגע בנבלתם יטמא עד הערב והנושא את נבלתם יכבס בגדיו וטמא עד הערב הנוגע יטמא עד הערב ואין הנוגע מטמא בגדים והנושא יכבס בגדיו מלמד שהנושא מטמא בגדים:\",3,0],[8,378,1,1,\"וכתב רבינו בפירקא קמא דכלים דע שאומרו יתברך יכבס בגדיו אין הכוונה בו שהוא יטמא הבגדים שהוא לבוש לבד אבל הכוונה שהוא יטמא אי זה בגד ילבש אותו או לא וכן שאר הכלים ולשון סיפרא מטמא שאר כלים כבגדים זולת כלי חרס שהוא לא יטמאהו זולת האב וכו' וזה אשר אמרנו שהוא מטמא בגדים וכלים בתנאי שיגע בהם והוא מחובר בזב אשר טימאהו ויהיו אלו הכלים אז ראשון ולא שני לפי שהוא לא יטמא מפני נגיעתו לבד אבל מפני נגיעתו והוא לא פירש ממטמאיו אולם כאשר פירש ממטמאיו יהיה אז ראשון והוא ולד הטומאה ולא יטמא בגדים. ודבריו אלה מבוארים בסוף זבים הנושא את הנבילה מטמא שנים ופוסל א' פירש מטמא אחד ופוסל אחד.\",4,0],[8,378,1,1,\"ומה שכתב כמרכב הזב. כלומר כמו שהמרכב אינו מטמא בגדים במגע ומטמא בגדים במשא כמו שנתבאר בפרק ו' מהלכות מטמאי משכב ומושב:\",5,0],[8,378,1,1,\"כיצד אדם שנגע בנבילה וכו'. ואם נגע בבגדים אפילו בשעת מגעו בנבילה. נתבאר בסמוך.\",6,0],[8,378,1,1,\"ומה שכתב וכן כלים שעליו טהורים לפי שהוא ולד. כך היא הנוסחא האמיתית ולא כמו שכתב בספרים לפי שהן וטעות סופר הוא.\",7,0],[8,378,1,1,\"ומה שכתב ואינו מטמא לא אדם ולא כלי חרס. בתורת כהנים הנושא יכבס בגדיו מנין לעשות שאר כלים כבגדים ת\\\"ל טמא יכול יטמא אדם וכלי חרס ת\\\"ל בגד בגד הוא מטמא ואינו מטמא אדם וכלי חרס.\",8,0],[8,378,1,1,\"ומ\\\"ש ואפילו בשעת נשיאתו כמו שביארנו במטמאי משכב ומושב. פ\\\"ו:\",9,0],[8,378,1,2,\"אחד בהמה וחיה וכו'. בפרק בהמה המקשה (חולין דף ע' ע״ב) יליף דנבלת בהמה וחיה בין טמאין בין טהורים מטמאים:\",1,0],[8,378,1,2,\"ושחיטת בהמה וחיה הטהורים מטהרתן. במשנה פרק בהמה המקשה (חולין דף ע״ב ע״ב) דטריפה שחיטתה מטהרתה מטומאה.\",2,0],[8,378,1,2,\"ומ״ש ואפילו שחט חולין בעזרה וקדשים בחוץ. משנה בפרק חטאת העוף (זבחים דף ס״ח) שחט חולין בפנים וקדשים בחוץ אינה מטמאה בבית הבליעה.\",3,0],[8,378,1,2,\"ומ״ש ואם אירע פיסול בשחיטתה הרי זו נבילה וכו'. משנה בפרק השוחט (חולין דף ל״ב):\",4,0],[8,378,1,3,\"בהמה טמאה וחיה טמאה וכו'. במשנה פרק בהמה המקשה (חולין דף ע״ב ע״ב):\",1,0],[8,378,1,3,\"וכל הנבילות וכו'. משנה פרק ד' דמעילה (דף ט\\\"ו):\",2,0],[8,378,1,4,\"מוח הרי הוא וכו'. מתבאר בפרק העור והרוטב עלה קכ\\\"ה:\",1,0],[8,378,1,4,\"ודם הנבילה אינו וכו'. בפרק בתרא דעדיות וכתב שם רבינו שכן הלכה ובפרק המנחות והנסכים (מנחות דף ק״ג ע״ב) א״ר יהושע בן בתירא שכך עשו מעשה.\",2,0],[8,378,1,4,\"ומ\\\"ש אלא הרי הוא כמשקין טמאים וכו'. כתב רבינו בעדיות בפ' הנזכר שכך נתבאר בירושלמי וכ\\\"כ רש\\\"י בפרק המוציא:\",3,0],[8,378,1,5,\"חלב בהמה טהורה וכו'. בס״פ חטאת העוף (זבחים דף ס״ט.) ובפרק בתרא דעוקצין.\",1,0],[8,378,1,5,\"ומ\\\"ש ואם הוכשר וכו'. בפרק בתרא דעוקצין:\",2,0],[8,378,1,5,\"והנוגע בחלב החופה את הכוליא וכו'. בפרק העור והרוטב (חולין דף קכ״ו):\",3,0],[8,378,1,5,\"אבל בהמה טמאה והחיה בין טהורה בין טמאה וכו'. בס״פ חטאת העוף (זבחים דף ע'):\",4,0],[8,378,1,6,\"הכוי חלבו מטמא כבשרו וטומאתו בספק וכו'. בפ\\\"ב דבכורים:\",1,0],[8,378,1,7,\"ואלו דברים שאין מטמאין וכו'. משנה פרק העור והרוטב (חולין דף קי״ז ע״ב).\",1,0],[8,378,1,7,\"ומ\\\"ש אפילו עיקרן הרך וכו'. שם בגמרא.\",2,0],[8,378,1,7,\"ומ\\\"ש בד\\\"א בזמן שפירשו מן הנבילה אבל הנוגע באחד מכל אלו כשהם מחוברים וכו' והוא שיהיה בבשר כזית וכו'. בס\\\"פ העור והרוטב:\",3,0],[8,378,1,8,\"האלל בין שפלטתו חיה וכו'. במשנה בראש פרק העור והרוטב מני אלל בהדי הנך דאין מצטרפין לטמא טומאת נבילות ומסיים בה רבי יהודה אומר האלל המכונס אם יש בו כזית במקום אחד חייב עליו ופירש\\\"י המכונס הנאסף במקום אחד דהואיל ואחשביה לא בטיל וחשיב הבשר נבילה וחייב עליו אם נגע ונכנס למקדש או אכל קדש ובגמרא (דף קכ\\\"א) מאי אלל ר\\\"י אמר מרטקא ר\\\"ל אמר בשר שפלטתו סכין וכו' ת\\\"ש רבי יהודה אומר האלל המכונס אם יש בו כזית במקום אחד חייבין עליו אמר רב הונא והוא שכנסו בשלמא למ\\\"ד בשר שפלטתו סכין היינו דכי איכא כזית מיחייב אלא למ\\\"ד מרטקא כי איכא כזית מאי הוי עץ בעלמא הוא אליבא דרבי יהודה כ\\\"ע לא פליגי כ\\\"פ אליבא דרבנן ופירש\\\"י והוא שכנסו וכו' אבל מתכנס מאליו כגון על ידי תינוקות שלא במתכוון לא:\",1,0],[8,378,1,8,\"וכתב הראב\\\"ד ואם כנסו והיה בו כזית א\\\"א לא נהיר דכי מעיינת בשמעתא וכו'. טעמו דרבי יהודה יחידאה הוא ולית הלכתא כוותיה והיאך פסק רבינו כמותו. ומ\\\"ש ורבי יהודה גופיה אליבא דרבי ישמעאל קמיירי היינו לומר דבההוא פירקא (דף קכ\\\"ד) תנן עור שהיו עליו כשני חצאי זיתים מטמא במגע אבל לא במשא דברי רבי ישמעאל ר\\\"ע אומר לא במגע ולא במשא וכו' מפני שהעור מבטלן ומסיק בגמרא דלרבי ישמעאל בין פלטתו חיה בין פלטתו סכין אין העור מבטלו ואמרינן בגמרא דרב הונא דאמר והוא שכנסו כרבי ישמעאל וכיון דקי\\\"ל הלכה כר\\\"ע מחבירו ה\\\"ל הא דרבי יהודה דלא כהלכתא. וליישב דעת רבינו י\\\"ל דמשמע לרבינו דכיון דרב הונא מפרש דברי ר' יהודה אלמא ס\\\"ל דהלכתא כוותיה ואין זה כדאי דהא אפשר דמפרש מילתיה דרבי יהודה לאו משום דהלכתא כוותיה אלא למשמע מיניה לרבנן דאפילו בשכנסו פליגי ועוד דאיתא בגמרא (דף קכ\\\"א ע\\\"ב) אמר רב הונא שני חצאי זיתים שישנן ע\\\"ג העור העור מבטלן ומסיק בגמרא דלר\\\"ע קאמר לאשמועינן דאפילו בפלטתו חיה סבר ר\\\"ע דהעור מבטלן והשתא איכא למימר כיון דרב הונא אמר מימריה אליבא דר\\\"ע אלמא דהלכתא כוותיה וטפי הוה עדיף למסמך על האי מימרא דרב הונא דאתיא כר\\\"ע דהלכה כמותו מחבירו מלמיסמך אאידך מימרא דאתיא כרבי ישמעאל דפליג אר\\\"ע וכרבי יהודה דפליג ארבנן וע\\\"ק שרבינו לקמן בסמוך פסק כר\\\"ע ולכך נראה לומר שסובר רבינו דר\\\"י כר\\\"ע נמי אתי דע\\\"כ לא טיהר ר\\\"ע אלא כשעודם בעור אבל אם כנסו טמא דליכא למימר ביה העור מבטלו כיון שעכשיו אינו בעור ואע\\\"ג דבגמרא לא משמע הכי דאהא דאמר רב הונא שני חצאי זיתים שישנן ע\\\"ג העור העור מבטלן קאמר ת\\\"ש רבי יהודה אומר האלל המכונס וכו' עד ורב הונא דאמר כר\\\"ע איכא למימר דאה\\\"נ דהוה מצי למימר דלא שייכא פלוגתא דרבי ישמעאל ור\\\"ע בדרבי יהודה דהתם בעודם בעור ודרבי יהודה שכנסו ואינו בעור אפילו ר\\\"ע מודה אלא שהשיב לו לפי דרכו שלא היה מחלק בין עודם בעור לכנסו ואינו בעור וכיון שחילוק זה מסתבר טעמיה נראה לרבינו לחלק בכך ומ\\\"מ עדיין הקושיא הראשונה במקומה עומדת למה פסק כרבי יהודה דיחידאה הוא וצ\\\"ל דטפי משמע דרב הונא סבר דהלכה כרבי יהודה כיון דאמר מילתיה אליביה דאי למשמע מיניה לרבנן טפי עדיף למימר על מלתייהו דרבנן והאלל אמר רב הונא אע\\\"פ שכנסו שלא היה מאריך בכך יותר מהשתא כי אמרה על רבי יהודה הילכך ודאי דסבר על רב הונא דהלכה כרבי יהודה:\",2,0],[8,378,1,9,\"ואלו בהמות וכו'. משנה פרק העור והרוטב (חולין דף קכ״ב) ואע״ג דבההיא מתניתין מני בהדי הנך עור ראש העגל הרך ועור הפרסות השמיטם רבינו פה ובפ״ד מהמ״א משום דאמרינן בפרק הנזכר ובפרק אלו טרפות (חולין דף נ״ה) דיחידאה היא.\",1,0],[8,378,1,9,\"ומ\\\"ש ואם עשה בהם מעשה וכו' כיצד אוזן חמור וכו' עד כל זמן שלא טענה. שם בגמרא.\",2,0],[8,378,1,9,\"ומ\\\"ש הגיע זמנה לטעון וכו'. שם בעיא ולא איפשיטא:\",3,0],[8,378,1,10,\"המפשיט נבלת בהמה וכו'. משנה שם (דף קכ\\\"ג) המפשיט בבהמה ובחיה וכו' לשטיחה כדי אחיזה ולחמת עד שיפשיט את החזה המרגיל כולו חיבור לטומאה ליטמא ולטמא. ובגמרא כמה כדי אחיזה טפח כפול ודעת רבינו כשיטת הר\\\"י מאורלינ\\\"ש דלא מטמא אלא עד כדי אחיזה ולא כדי אחיזה בכלל ואמרינן בגמרא מכאן ואילך מאי אמר רב (טהור הטהור) טהור המופשט רב אסי אמר טפח הסמוך לבשר טמא ופסק רבינו כרב לגבי רב אסי ועוד דבגמרא מתיב על רב אסי מברייתות ושנינהו בשינויי דחיקי וכתב רבינו בפירוש המשנה שהמפשיט לשטיח יקרע קודם מזנבה עד צוארה ואח\\\"כ יפשיט ומפשיט לחמת הוא קורע העור בין שתי הרגלים מרגל לרגל ואח\\\"כ חותך מכל צד בסכין או בידו עד שיצא כל העור שלם בהיקפו ומרגיל הוא שיוציא העור כולו שלם ממקום הרגל בלתי חתך ולא קרע עד שאם יקשור מקום הרגלים ימלאו אותו מים ולכך זה הוא חיבור עד שלא ישאר בו כלום.\",1,0],[8,378,1,10,\"ומה שכתב וכן המפשיט בשרצים וכו'. שם רבי דוסתאי בן יהודה משום ר\\\"ש אומר המפשיט בשרצים חיבור עד שיפשיט את כולו. ויש לתמוה על רבינו למה פסק כן דהא כיון דבלשון יחיד קתני לה משמע דרבנן פליגי עליה:\",2,0],[8,378,1,10,\"עור שעל הצואר וכו'. משנה שם (דף קכ\\\"ג) וכחכמים:\",3,0],[8,378,1,10,\"וכל עור שהוא חיבור וכו'. שם במשנה ליטמא ולטמא:\",4,0],[8,378,1,11,\"עור שיש עליו כזית נבילה וכו'. משנה שם (דף קכ\\\"ד).\",1,0],[8,378,1,11,\"ומ\\\"ש מפני שהעור בשערו. נמצא בספר כתיבת יד מפני שהעור ושערו שומר לבשר והיא גירסא נכונה. וציב פי' רבינו חוט דק שנתפשט מן העור הסמוך לבשר.\",2,0],[8,378,1,11,\"ומ\\\"ש בד\\\"א שפלטתו חיה וכו'. שם ואע\\\"ג דאיכא התם לישנא אחרינא פסק רבינו כי האי לישנא משום דאמרינן התם דכי אתא רבין וכל נחותי אמרו כי האי לישנא ופירש\\\"י מרודד דק וקלוש וארוך ורחב דכי מצרפת ליה הוי כזית ומיהו לא טרח איניש ומצרף ליה ומיהו פלטתו חיה דלאו איהו בטליה לא בטיל:\",3,0],[8,378,1,12,\"עור שיש עליו כשני חצאי זיתים בשר וכו'. משנה שם עור שיש עליו כשני חצאי זיתים מטמא במשא ולא במגע דברי רבי ישמעאל ר\\\"ע אמר לא במגע ולא במשא ומודה ר\\\"ע בכשני חצאי [זיתים] שתחבן בקיסם והסיטן שהוא טמא ומפני מה ר\\\"ע מטהר בעור מפני שהעור מבטלן. ופירש\\\"י מטמא במשא שהרי נשא כזית נבילה. ולא במגע דא\\\"א ליגע ביחד ושתי נגיעות אין מצטרפות. לא במגע ולא במשא כדמפרש שהעור מבטלו. ומודה ר\\\"ע דאע\\\"ג דלא הוי כזית מעורה במקום אחד דלאו עור חיבור שהמסיט שני חצאי זיתים ביחד טמא. ובגמרא תניא בנבלתה ולא בעור שיש עליו שני חצאי זיתים יכול אף במשא ת\\\"ל והנושא יטמא דברי רבי ישמעאל ר\\\"ע אומר הנוגע והנושא את שבא לכלל מגע בא לכלל משא לא בא לכלל מגע לא בא לכלל משא ואיתא תו בגמרא אמר עולא שני חצאי זיתים שתחבן בקיסם אפילו מוליך ומביא כל היום כולו טהור מ\\\"ט כתיב נשא וקרינן נושא בעינן נושא והוא דנישא בבת אחת וכו' ת\\\"ש מודה ר\\\"ע בכשני חצאי זיתים שתחבן בקיסם והסיטן שהוא טמא אמאי והא לאו נישא הוא במרודד. ופירש\\\"י והוא דנישא שיהא כזית מחובר הניטל כולו כאחד בלא בית יד אחר. במרודד שיש כאן חצי זית ורחוק ממנו חצי זית ורצועות בשר מרודד מזה לזה ומחברתן עכ\\\"ל. ומדברי רבינו שכתב שאין חיבורי אדם חיבור נראה שאינו מפרש כן אלא שהוא מרודד בידים ודבוק זה בזה ומשמע דכי תנן מודה ר\\\"ע בכשני חצאי זיתים והסיטן שהוא טמא בהיסט קאמר דטמא ולא במגע והכי משמע נמי מדקתני ומודה ר\\\"ע משמע דמודה לרבי ישמעאל דמטמא במשא ואם כן קשה שזה היפך מאי דתניא לא בא לכלל מגע לא בא לכלל משא וצ\\\"ל דלא אמרו כן אלא בתחובין בעור דוקא וכמבואר ברישא דברייתא וגם רבינו כשכתב שכל שאינו מטמא מן הנבילה במגע אינו מטמא במשא קאי אמאי דכתב ברישא עור שיש עליו כשני חצאי זיתי בשר נבילה העור מבטלן שאם לא תאמר כן נמצאו דבריו סותרים זה את זה תוך כדי דבור הילכך ע\\\"כ לומר כן:\",1,0],[8,378,1,13,\"בשר נבילה וכו'. פ\\\"ג דבכורות עלה כ\\\"ג וכר\\\"י ואע\\\"ג דאסיקנא בקשיא כיון דלא אסיקנא בתיובתא.\",1,0],[8,378,1,13,\"ומ\\\"ש לפיכך נצל מן הנבלה וכו'. בפכ\\\"ג ונזיר עלה נ' בעא מיניה אביי מרבא יש נצל לבהמה וקאמר דלמ\\\"ד טומאה חמורה עד לגר פשיטא דאין לה נצל כי תבעי למ\\\"ד טומאה חמורה עד לכלב ולא איפשיטא:\",2,0],[8,378,1,13,\"בשר נבילה שיבש וכו'. משנה ר״פ דם הנדה (נדה דף נ״ד ע״ב).\",3,0],[8,378,1,13,\"ומ\\\"ש ואפילו באוכלין טמאים אינו מטמא:\",4,0],[8,378,1,14,\"בשר נבילה שהיה סרוח וכו'. בפרק שלישי דבכורות עלה כ\\\"ג:\",1,0],[8,378,1,15,\"שליא של נבילה וכו'. משנה פרק בהמה המקשה (חולין דף ע״ז):\",1,0],[8,378,1,15,\"הקיבה והחלב של וכו'. בס״פ כל הבשר (חולין דף קי״ו ע״ב) אסיקנא דאע״ג דאין מעמידין בעור קיבת נבילה מעמידין בקיבת נבילה ובקיבה כשירה שינקה מהטריפה מ״ט חלב המכונס בה פירשא בעלמא היא:\",2,0],[8,378,1,16,\"בהמה ששפעה חררת וכו'. בפ\\\"ג דבכורות (דף כ\\\"א ע\\\"ב) ופירש\\\"י ברוב דם וגנונים שיוצאים עמו ומקשה בגמרא (דף כ\\\"ג ע\\\"ב) מאי איריא משום ביטול ברוב תיפוק לי דלא איתחזי כלל הא נמי איתחזי מעיקרא אגב אימיה ופירש\\\"י לאו סרוח מעיקרא היה דהא חזאי לגר אגב אימיה כל זמן שהיתה בבטן כלומר ולכך הוצרך לטעם ביטול ברוב:\",1,0],[8,378,1,17,\"נבלה שנתערבה בשחוטה וכו'. בפרק ג' דבכורות עלה כ\\\"ג תני רבי חייא נבילה ושחוטה בטילות זו בזו וכו' אמר רבי יוסי בר חנינא טהור מלטמא במגע אבל מטמא במשא ופירש\\\"י טעמא דמטמא במשא דהא מ\\\"מ הטומאה נשא ובפרק הקומץ עלה כ\\\"ג אמר רב חסדא נבילה בטילה בשחוטה שא\\\"א לשחוטה שתיעשה נבילה ושחוטה אינה בטילה בנבילה שאפשר לנבילה שתיעשה שחוטה דלכי מסרחא פרחה טומאתה ורבי חנינא אמר איפכא ובעי עלה אליבא דמאן אי אליבא דרבנן הא אמרי מין במינו בטל אי אליבא דרבי יהודה הא אמר בתר חזותא אזלינן אידי ואידי מין במינו הוא אלא אליבא דרבי חייא דתני רבי חייא נבילה ושחוטה בטלות זו בזו רבי חייא אליבא דמאן אי אליבא דרבנן הא אמרי וכו' אי אליבא דר\\\"י כל מין במינו לא בטיל לעולם אליבא דר\\\"י וכי א\\\"ר יהודה מין במינו לא בטיל ה\\\"מ היכא דאפשר ליה למיהוי כוותיה אבל היכא דלא אפשר ליה למיהוי כוותיה בטיל ובהא קמיפלגי רב חסדא סבר בתר מבטל אזלינן ורבי חנינא סבר בתר בטל אזלינן ופירש\\\"י נבילה בשחוטה אם יש שתי חתיכות שחוטה ואחת נבלה ואין ידוע אי זו היא בטלה בהן שאם נגע באחת החתיכות אינו טמא דאמרינן שחוטה היא. שא\\\"א לשחוטה שתעשה נבילה והו\\\"ל מין בשאינו מינו ובטל לדברי הכל. ושחוטה אינה בטילה בנבילה אם יש שתי חתיכות נבילה ואחת שחוטה ביניהן אינה בטילה ואם נגעה אחת בתרומה אינה נשרפת עליה אלא תולין דשמא זו היא השחוטה. שאפשר לנבילה שתעשה שחוטה לקמיה מפרש טעמיה דרב חסדא דאזיל בתר מבטל הואיל וא\\\"א לרוב להיות כמועט הוי כמין בשאינו מינו ולא אזלינן בתר בטל דאע\\\"ג דאיפשר למועט להיות כמרובה הוי כמין בשאינו מינו. בטלות זו בזו ורבי חנינא ורב חסדא מפרשי טעמא דרבי חייא דרב חסדא סבר נבילה בשחוטה א\\\"ר חייא ולא שחוטה בנבילה:\",1,0],[8,378,1,17,\"וכתב הראב\\\"ד אבל הנבילה אפשר א\\\"א חסרון דעת אני רואה בכאן דכולה מילתא במנחות אליבא דר\\\"י היא וכו'. טעמו לומר דכיון דקי\\\"ל כרבנן לא היה לו לכתוב טעם האמור אליבא דר\\\"י ועוד למה כתב כרב חסדא כיון דרבי חנינא פליג עליה ואפשר לומר דלרווחא דמילתא כתב רבינו דאפילו למאן דס\\\"ל כר\\\"י דמין במינו לא בטיל מודה בהא ובפלוגתא דר\\\"ח ורב חסדא כתב כרב חסדא דבתרא הוא:\",2,0],[8,378,1,17,\"והר״י קורקוס ז״ל כתב דמאחר דבפרק משילין (ביצה דף ל״ח ע״ב) ובפ״ג דבכורות מייתי להא דרב חסדא ולא הזכירו שם שהיא אליבא דר״י וגם מדקאמר הכי איהו בסתמא משמע דלהלכה אמר כן יש לדחוק לומר דע״כ לא מסקינן בפרק הקומץ דאליבא דר״י קאמר ולא אליבא דרבנן אלא משום דהוה ס״ל דבטל לגמרי קאמר בין למגע בין למשא ולפ״ז הוי ביטול זה ביטול גמור ככל ביטול איסורין וכיון שכן לרבנן אין לחלק בדין ביטול אבל כיון דאסיקנא דדוקא במגע לא מטמא אבל במשא מטמא דטומאה כמאן דאיתא דמי א״כ אין ביטול זה כשאר ביטול דחשיב הדבר הבטל כמאן דליתיה משמע דסברי דלענין טומאה אין לומר ביטול ברוב כמו בשאר איסורין וכמו שכתבו שם התוספות למאי דמפרש לה בנימוחו מעתה אפשר דאפי' רבנן מודו דדוקא היכא דאפשר להיות כמוהו הוא דבטל ביטול זה אבל כשא״א להיות כמוהו לא בטיל ויהיה דין מגע בזה כדין משא לר״י כמה שאפשר להיות כמוהו עכ״ל:\",3,0],[8,378,1,17,\"ומדברי רבינו שכתב ואין הכל מטמא במגע משמע שאפילו נגע בכל הזיתים ביחד טהור ויש לתמוה מאי שנא ממשא וכתב הר\\\"י קורקוס ז\\\"ל שהטעם שכיון שהטומאה על ידי נגיעת בשרו בטומאה וכל זית הוא בפני עצמו חשיבא כל נגיעה באפי נפשה כי כל נגיעה ונגיעה מחולקת היא לבדה ובכל זית יש נגיעה בפני עצמה כי הבשר הנוגע בזית זה אינו הנוגע בזית זה וחשיב כנוגע וחוזר ונוגע אבל נושאו ביחד אין מקום לחלק הזיתים ולעשותו כנושא כל זית בפני עצמו וקל להבין כך נראה לי דעת רבינו עכ\\\"ל. ואם תאמר מ\\\"ש דבחררת דם דבסמוך דמשום ביטול ברוב אינה מטמאה לא במגע ולא במשא והכא אין ביטול ברוב מועיל אלא למגע ולא למשא ותירץ הר\\\"י קורקוס ז\\\"ל דחררת דם שאני שבטל ביטול כי נתערבה החררה בדם וגנונים ונמחית בהם והוי הכל כמו הדם והגנונים ואין כאן עוד דבר שיטמא אבל כאן אין לומר כן דבאפי נפשה קאי אלא שאינה ניכרת:\",4,0],[8,378,2,1,\"בהמה או חיה שנשחטה וכו'. משנה בפרק העור והרוטב (חולין קי״ז:).\",1,0],[8,378,2,1,\"ומ\\\"ש נחרה והרי היא מפרכסת ואבר הפורש וכו' ובשר הפורש וכו'. ברייתא שם (דף קכ\\\"א ע\\\"ב).\",2,0],[8,378,2,1,\"ומ\\\"ש וכן טהורה שנפסלה בשחיטתה וכו'. הכי משמע התם דכל שאינה ניתרת באותה שחיטה דומיא דשחט רוב שנים אינה מטמאה אפילו טומאת אוכלין בעודה מפרכסת:\",3,0],[8,378,2,1,\"חלק הבהמה לשנים וכו' עד לכל דבר. בפ\\\"ב דחולין עלה כ\\\"א:\",4,0],[8,378,2,2,\"בהמה שמת עוברה וכו'. משנה פרק בהמה המקשה (חולין דף ע' ע\\\"ב) וכתנא קמא:\",1,0],[8,378,2,3,\"בשר הפורש מבהמה וחיה עד כנבלה. בפרק העור והרוטב (חולין דף קכ״ח ע״ב).\",1,0],[8,378,2,3,\"ומ״ש בין טמאים: אחד אבר מן החי וכו' או אבר הפורש מן השליל שבבטנה. בפרק בהמה המקשה (חולין דף ע״ב) הוציא ידו וחתכו ואח״כ שחט את אמו שבחוץ טמא פירש אותו אבר שחתך טמא:\",2,0],[8,378,2,3,\"האיברים אין להם שיעור וכו'. בפרק קמא דאהלות.\",3,0],[8,378,2,3,\"ומ״ש והוא שיהיה האבר כברייתו בשר וגידים ועצמות. בס״פ העור והרוטב (חולין דף קכ״ח).\",4,0],[8,378,2,3,\"ומ\\\"ש ויהיה עליו בשר כדי להעלות ארוכה. בפ\\\"ק דכלים גבי אבר מן החי מן האדם ומשמע דה\\\"ה לאבר מן החי מן הבהמה והכי אמרינן בפרק העור והרוטב.\",5,0],[8,378,2,3,\"ומ\\\"ש או חסר עצמו טהור. בפ\\\"ו דעדיות (משנה ג') ובפ\\\"ב דאהלות גבי אבר מן החי מן האדם ונתבאר בפ\\\"ב מהלכות טומאת מת ובתוספתא פ\\\"ק דאהלות תני דה\\\"ה לאבר מן החי מן הבהמה:\",6,0],[8,378,2,4,\"הכוליא והלשון והשפה וכו'. בסוף פרק העור והרוטב יכול יהא בשר הפורש מן החי טמא וכו' עד כוליא וניב שפתים איכא בינייהו ומדכתב רבינו ויהיה האבר כברייתו בשר וגידים ועצמות משמע דפסק כרבי ויש לתמוה למה לא פסק כרבי עקיבא מחבירו ועוד קשה דכיון שפסק כרבי הו\\\"ל למעט ארכובה כמו שמיעט כוליא ולשון ושפה וצריך עיון:\",1,0],[8,378,2,5,\"האבר והבשר המדולדלין וכו'. משנה פרק העור והרוטב (דף קנ\\\"ז).\",1,0],[8,378,2,5,\"ומ\\\"ש נשחטה הבהמה וכו'. שם במשנה פלוגתא דר\\\"מ ור\\\"ש ופסק כר\\\"מ:\",2,0],[8,378,2,5,\"וכתב הר״י קורקוס ז״ל שטעמו משום דבפרק מי שהוציאוהו (עירובין דף מ״ו ע״ב) אמרינן ר״מ ור״ש הלכה כדברי מי וסלקא בתיקו הילכך נקטינן כדברי המחמיר כמו שכתוב בהלכות עולם ועוד דהתם בעי רבה בהמה בחייה מהו שתעשה יד לאבר והיינו אליבא דר״מ גם בפרק בהמה המקשה מוכיח שהלכה כר״מ:\",3,0],[8,378,2,5,\"כתב הר\\\"י קורקוס כבר נתבאר דבשר הפורש מן החי אין בו טומאת נבילות ומה שהזכיר רבינו בשר מדולדל משום סיפא דקאמר דהוי כשאר אוכלים אפילו בעודה במקומה מחוברים הזכירו והוא הנזכר במשנה עכ\\\"ל.\",4,0],[8,378,2,5,\"ומ\\\"ש ואינם מטמאים כנבילה וכו'. שם בגמרא.\",5,0],[8,378,2,5,\"ומה שכתב אבל אם מתה הבהמה וכו'. שם במשנה פלוגתא דרבי מאיר ורבי שמעון ופסק כרבי מאיר וכדבסמוך.\",6,0],[8,378,2,5,\"ומה שכתב ומה בין אבר מן החי וכו'. שם ברייתא.\",7,0],[8,378,2,5,\"ומה שכתב וזה וזה שוין לשיעור. כלומר דמטמאין בכל שהן ושצריך שיהיה בהם בשר וגידים ועצמות ויהיה עליו בשר כדי להעלות ארוכה נוסחא אחרת מצאתי בדברי רבינו שכתוב בה וזה וזה אין לו שיעור היא נוסחא נכונה:\",8,0],[8,378,2,6,\"טריפה שנשחטה וכו'. משנה בפרק בהמה המקשה (חולין דף ע״ב:).\",1,0],[8,378,2,6,\"ומ\\\"ש וכן השוחט את הבהמה ומצא בה עובר מת וכו'. משנה שם:\",2,0],[8,378,2,6,\"מצא בה בן ח' חי נטרף וכו'. א״א לפרש דאשוחט את הבהמה קאי דהא תנן בפרק בהמה המקשה (חולין דף ע״ד) השוחט את הבהמה ומצא בה בן ח' חי או מת [או בן תשעה מת] קורעו ומוציא את דמו כלומר ומותר באכילה שאין צריך שחיטה דשחיטת אמו מטהרתו אלא בשלא שחטה מיירי או ששחטה ונתנבלה בידו וקרעה ומצא בה בן ח' שאין שחיטה מטהרתו וכדתנן התם (דף ע״ב:) בן שמונה חי אין שחיטתו מטהרתו לפי שאין למינו שחיטה. אבל קשיא לי מ״ש נטרף אע״פ שנשחט אחר שנטרף אין שחיטתו מטהרתו מאי איריא נטרף אפילו לא נטרף נמי ונ״ל דהכי קאמר קרעה ומצא בה בן שמונה חי נטרף כלומר דינו כטריפה שאע״פ שהוא אסור באכילה אינו מטמא כל זמן שהוא חי ואם נשחט כיון שאין למינו שחיטה לא חשיבא שחיטה והו״ל נבילה, אבל לשון אחר שנטרף אינו נוח לי לפירוש זה דמאי אחר הרי טריפה הוא מתחלתו וצ״ל דמשום דאילו לא קרעה אלא שחטה או היה ממתין עד שתלד לא היה שם טריפות שייך לומר אחר שנטרף כלומר אחר שקרעה שהרי בכך נטרף:\",3,0],[8,378,2,6,\"לפיכך ולד בהמה וכו'. זה נלמד ממה שנזכר בסמוך בבן ח' שגם זה אין למינו שחיטה כל זמן שלא עברו עליו שבעה ימים גמורים כמבואר בפרק [רביעי] מהמ״א ובפרק ר״א דמילה (שבת דף קל״ד ע״ב) כל ששהה שמנה ימים בבהמה אינו נפל הא לא שהה ספיקא הוי:\",4,0],[8,378,2,6,\"וכתב הר\\\"י קורקוס ז\\\"ל שאפשר שלכך כתב רבינו אין שחיטתו מטהרתו מידי נבילה פירוש שאינו ודאי טהור אבל גם אינו ודאי נבילה וז\\\"ש שהוא כנפל:\",5,0],[8,378,2,7,\"השוחט את הבהמה וכו'. בפרק בהמה המקשה (חולין דף ע״ה ע״ב) וכר״י אליבא דרבנן.\",1,0],[8,378,2,7,\"ומה שכתב ואם נתנבלה אמו וכו'. זה פשוט שמאחר שאין שחיטת אמו מטהרתו הרי הוא חי ואין החי מתטמא וכו':\",2,0],[8,378,2,7,\"כתב הר\\\"י קורקוס ז\\\"ל כתב רבינו בהלכות מאכלות אסורות שאם שחט טריפה ומצא בה בן תשעה חי צריך שחיטה להתירו ולא ביאר רבינו בזה מה יהיה דינו לענין אם מת קודם שנשחט כי מהסוגיא דשם נראה שאם מת טהור מלטמא אף על פי דלענין אכילה בעי שחיטה לענין טומאה נטהר בשחיטת אמו וכן מתבאר גם בפרק כיסוי הדם ונראה שהוא בכלל מה שכתב רבינו טריפה שנשחטה וכו' דכי היכי דטיהר אותה אף על פי שאסורה באכילה גם כן הדין בעובר. ומ\\\"ש עליה וכן השוחט את הבהמה ומצא בה עובר מת היינו אפילו טריפה ועל מ\\\"ש קודם קאי וכן מ\\\"ש\",3,0],[8,378,2,7,\"כאן ואם מת קודם שיפריס אפי' כשהאם טריפה מיירי כי שחיטת טריפה ושחיטת כשירה לענין טומאה שוים הם מקרא דוכי ימות מן הבהמה דאף על גב דאין מועילה לטהר מידי נבילה בכשרה מטהרת בין היא בין העובר דכגופה דמי וקרוב לזה יתבאר בסמוך גבי אבר שיצא לחוץ, ומכל מקום מ\\\"ש ואם מת קודם שיפריס לא קאי אאם נתנבלה כי אין שם שחיטה כלל ולא קאי אלא אשוחט את הבהמה ומצא בה וכו' והוא במשנה פרק בהמה המקשה כתנא קמא עכ\\\"ל:\",4,0],[8,378,2,8,\"טריפה שנשחטה. בפרק בהמה המקשה (חולין דף ע״ג):\",1,0],[8,378,2,9,\"בהמה המקשה לילד וכו'. משנה שם (דף ע\\\"ב) וכחכמים:\",1,0],[8,378,2,9,\"הוציא העובר את ידו וכו'. שם עלה ס\\\"ט:\",2,0],[8,378,2,10,\"שחיטת עכו\\\"ם נבילה וכו'. משנה בריש חולין (דף י\\\"ג).\",1,0],[8,378,2,10,\"ומ\\\"ש ואפילו ישראל עומד ע\\\"ג ואם שחט בסכין יפה. פשוט שם דישראל עומד על גביו לא אמרו אלא בחש\\\"ו.\",2,0],[8,378,2,10,\"ומ\\\"ש אחד העכו\\\"ם ואחד הכותי. שם עשאום כעכו\\\"ם גמורים לכל דבריהם.\",3,0],[8,378,2,10,\"ומ\\\"ש ואחד גר תושב. טעמו דכל שלא קיבל עליו כל המצות לא יצא מכלל עכו\\\"ם:\",4,0],[8,378,2,10,\"ומ\\\"ש וקרוב זה בעיני שאף זה מד\\\"ס וכו', כתב עליו הראב\\\"ד זו אחת מסברותיו וכו'. ואני שמעתי ולא אבין מ\\\"ש ואין מטמאין ואין מיטמאין דאטו אנן מטמאין בטומאת העכו\\\"ם וטהרתן עסקינן שיטעון עליו כן. וכן מ\\\"ש כי הם כבהמות מה ענין זה לששחיטתן תהא מטמאה במשא דהא אפשר דשחיטת קוף נמי לא תטמא במשא כיון דשם שחיטה עליה ושוב אין כאן מי שיחשוב אותם לכלום. אבל אי קשיא על דברי רבינו הא קשיא שכתב שבגלל ע\\\"ז נתרחקו הכותים ונאסרה שחיטתן שזו מנין לו שהרי איסור שחיטתן מדכתיב וזבחת נפקא ואף שחיטת קוף ממקרא זה נאסרה כמו שאמרו בתוספתא ריש חולין וזבחת ואכלת ולא שזבח העכו\\\"ם ולא שזבח הקוף ואין זה ענין לע\\\"ז ומזה ימשך טומאתם דכל שאינה זבוחה על ידי ישראל הרי היא כמתה בלא שחיטה ונבילה היא ואפשר שמפני שהרגיש רבינו בזה כתב וא\\\"א לחייב כרת על טומאה זו על ביאת מקדש ואכילת קדשיו כלומר לחייבו עליהם קרבן אלא בראיה ברורה כלומר שאע\\\"פ שיש לטעון עליו כמו שכתבתי מ\\\"מ כיון שיש לומר דלא נאסרה אלא בגלל ע\\\"ז א\\\"א לחייבו קרבן על טומאה זו על ביאת מקדש כדין החייב כרת על ביאת המקדש בטומאה שהוא ודאי מן התורה והיותר קרוב בעיני רבינו שהוא מד\\\"ס ומשום לתא דע\\\"ז ולטעמיה אזיל שכתב בפ\\\"ד מהלכות שחיטה עכו\\\"ם ששחט שחיטתו נבילה ולוקה על אכילתו מן התורה שנאמר וקרא לך ואכלת מזבחו וגדר גדול גדרו בדבר שאפילו עכו\\\"ם שאינו עובד ע\\\"ז שחיטתו נבילה ולפי דעתו ז\\\"ל מה שאמרו בתוספתא דוזבחת ואכלת ולא שזבח העכו\\\"ם ולא שזבח הקוף אסמכתא בעלמא היא:\",5,0],[8,378,2,11,\"קוליית הנבילה וכו'. משנה וגמרא פרק העור והרוטב עלה קכ\\\"ה:\",1,0],[8,378,2,12,\"קולית שחישב עליה לנוקבה וכו'. שם בעיא דאיפשיטא דמחוסר נקיבה לאו כמחוסר מעשה דמי ורבינו שכתב שהוא ספק נראה שהיה לו גירסא אחרת. והר\\\"י קורקוס ז\\\"ל כתב שאפשר שלא סמך רבינו על אותו פשיטות משום דבפרק טבול יום אמרו דמחוסר יציאה כמחוסר מעשה דמי ומשמע דה\\\"ה למחוסר נקיבה וה\\\"ז ספק:\",1,0],[8,378,3,1,\"נבלת העוף הטהור וכו'. כל זה בת\\\"כ פרשת אחרי מות ומייתי קצתו בפ\\\"ה דזבים וקצתו בפרק חטאת העוף ובפרק יוצא דופן.\",1,0],[8,378,3,1,\"ומ\\\"ש היה נוגע באדם ובכלי חרס וכו'. בת\\\"כ שם יכול יטמא אדם וכלי חרס ת\\\"ל בגד בגד הוא מטמא ולא אדם וכלי חרס.\",2,0],[8,378,3,1,\"ומ\\\"ש ואחר שבלע אינו מטמא שאר כלים וכו'. בתורת כהנים שם:\",3,0],[8,378,3,2,\"אין נבילת העוף הטהור צריכה מחשבה. פשוט בפרק בא סימן עלה נ':\",1,0],[8,378,3,2,\"חישב עליה לאכילה וכו'. בריש טהרות נבילת עוף טהור צריכה מחשבה ואינה צריכה הכשר והיינו דוקא בכפרים אבל בשווקים אינה צריכה מחשבה ולא הכשר כמו ששנינו בפ\\\"ג דעוקצין:\",2,0],[8,378,3,3,\"פרה אדומה וכו'. כתב הראב״ד א״א בחיי ראשי כאשר עיינתי את הדברים במקומם וכו'. ביאור הדברים דגרסינן בפרק טבול יום (זבחים דף ק״ה) ת״ר פרים ופרה ושעיר המשתלח וכו' עד צריכים הכשר טומאה ממקום אחר ופירש״י צריכין הכשר טומאה ממקום אחר הא דתנא דבי רבי ישמעאל ה״ק כל שאין סופו לטמא טומאה חמורה צריך הכשר טומאה ממקום אחר שיגע בשרץ או בנבילה ולא שיטמאו מאליו אבל מי שסופו לטמא טומאה חמורה א״צ ליגע בטומאה ומטמא טומאת אוכלים מאליו כגון פרה ופרים אבל חזי לטומאה מיהת בעלמא בעינן ולא ב״ח דלא אשכחן בבהמות בעלי חיים מטמאים ולפי פי' זה בין פרה ופרים בין נבילת עוף טהור א״צ ליגע בהם טומאה ולהאי פירושא ניחא מ״ש רבינו בנבילת עוף טהור שאף ע״פ שלא נגעה בהם טומאה מטמאים טומאת אוכלים אבל קשה מ״ש בפרה ופרים שצריכים ליגע בטומאה:\",1,0],[8,378,3,3,\"והראב\\\"ד מפרש דה\\\"ק האי דאמר רבי ישמעאל שסופו לטמא טומאה חמורה א\\\"צ הכשר היינו לומר שיהיו ראויים לקבל טומאה לומר דא\\\"צ הכשר מים אבל לעולם צריך הכשר טומאה ממקום אחר דהיינו דכל זמן שלא נגע בהם אינם מטמאים טומאת אוכלים ושעיר אינו מקבל טומאה משום דחי הוא ועל זה כתב דנהי דלהאי פירושא ניחא מ\\\"ש רבינו בפרה ופרים אבל קשה מ\\\"ש בנבלת עוף טהור שאע\\\"פ שלא נגע בה טומאה מטמא טומאת אוכלים ואח\\\"כ הקשה עוד דאע\\\"ג דלפום הכי סוגיא דזבחים ניחא האי פירושא בדרבי ישמעאל וכדאמרן סוגיין בעלמא דרבי ישמעאל א\\\"צ לא הכשר מים ולא הכשר שרץ ותיקשי ליה לרבינו בפרה ופרים מדרבי ישמעאל ולשון נמי שכתב אינו נוח לי דלא הוי מעין מ\\\"ש לעיל אלא איפכא:\",2,0],[8,378,3,3,\"וליישב דעת רבינו י\\\"ל שרבינו מפרש דרבי ישמעאל אין צריכין הכשר טומאה ולא הכשר שרץ קאמר מיהו היינו דוקא בנבלת עוף דנקט וכל כיוצא בה שהן מטמאין אדם במגע לאפוקי פרה ופרים שאינם מטמאים אלא המתעסקים בהם ולא את הנוגעים בהם בלא מתעסקים דכגון אלו צריכים הכשר שרץ שיקבלו טומאה ממנו ואז יטמאו אוכלים ומשקים ושעיר המשתלח שאינו מטמא טומאה מפני שהוא חי אינו מטמא אוכלים ומשקים ומה שאמרו צריכים הכשר טומאה ממקום אחר ה\\\"פ אע\\\"פ שאמר רבי ישמעאל שמי שסופו לטמא טומאה חמורה א\\\"צ הכשר שרץ היינו דוקא במי שיש לו הכשר טומאה ממקום אחר דהיינו שהוא מטמא הנוגעים בו אפילו בלא מתעסקים לאפוקי פרה ופרים שאינם מטמאים את הנוגעים בהם בלא מתעסקים. אחר שכתבתי זה מצאתי לרבינו בפירוש המשנה בסוף זבים אמתני' דהנוגע בשרץ שדקדק לשון כיוצא בזה:\",3,0],[8,378,3,4,\"כזית מנבלת הבהמה וכו'. בפרק יוצא דופן עלה מ\\\"ב וכרבא.\",1,0],[8,378,3,4,\"ומ\\\"ש או שהכניסו לתוך בליעתו וכו'. ג\\\"ז שם וכרבא:\",2,0],[8,378,3,5,\"הכורך כזית וכו'. תוספתא פ\\\"ה דזבים. והטעם נראה דהיינו משום דכיון דחזרת מין מאכל הוא מין במינו אינו חוצץ משא\\\"כ בסיב וכ\\\"כ ר\\\"ש:\",1,0],[8,378,3,6,\"הבולע נבלת העוף הטהור וכו'. בת\\\"כ פרשת אחרי מות יכול אם הקיאה תהא מטמאה בגדים דרך יציאתה ת\\\"ל אשר תאכל בדרך אכילתה היא מטמאה ואינה מטמאה דרך יציאתה:\",1,0],[8,378,3,7,\"מעי של נבלת העוף הטהור וכו'. כתב הראב\\\"ד זו המימרא לא מצאתי בשום מקום וכו' בפרק רבי ישמעאל דאמר אילפא ביצי נבילת עוף טהור מקצתן בחוץ וכו' והתוספות כתבו בפרק רבי ישמעאל עלה ע' על הא דאילפא שר\\\"ת מצא בספר ר\\\"ג מעי נבלת עוף טהור מקצתו בחוץ וכו' ומפרש רבינו דהיינו לומר שאם יש בבית הבליעה כזית טמא ואף על פי שלפי זה קשה האי דמסיים בה מבחוץ אינו מטמא בגדים דמאי קמשמע לן י\\\"ל דה\\\"ק אף על פי שמקצתו בחוץ במקום שאינו מטמא קצתו אחר שהוא בבית הבליעה מטמא והר\\\"י קורקוס ז\\\"ל האריך להקשות על פירוש רש\\\"י ופירוש רבינו תם ולהכריח פירוש רבינו:\",1,0],[8,378,3,8,\"בלע ממנה אבר שלם וכו' אפילו נטל צפור וכו'. תוספתא בסוף זבים שם ואיתא בפרק גיד הנשה (חולין דף ק״ב) לענין איסור אכילה:\",1,0],[8,378,3,9,\"הכנפיים והנוצה וכו'. בריש טהרות (פ\\\"א משנה ב).\",1,0],[8,378,3,9,\"ומה שכתב שהחרטום והצפרנים מצטרפין. גם זה שם.\",2,0],[8,378,3,9,\"ומה שכתב דהיינו דוקא במקומות הרכים הקרובים מן הבשר. בפרק העור והרוטב עלה קכ\\\"א.\",3,0],[8,378,3,9,\"ומה שכתב ראשי אגפיים וראש הזנב. בריש טהרות שם וכתנא קמא.\",4,0],[8,378,3,9,\"ומה שכתב והעצמות אפילו הרכות. משום דראשי אגפיים וראש הזנב וחרטום וצפרנים מיתנו בריש טהרות בהדי הדדי וכי היכי דחרטום וצפרנים מיירי במקומות הרכים ראשי אגפיים וראש הזנב נמי מיירי בהאי גוונא:\",5,0],[8,378,3,10,\"האוכל מנבלת העוף הטהור מן העצמות וכו'. בפרק קמא דביצה עלה ז'.\",1,0],[8,378,3,10,\"ומ\\\"ש בעצמות הרכים. משום דאל\\\"כ פשיטא דלאו בני אכילה נינהו כלל.\",2,0],[8,378,3,10,\"ומ\\\"ש ומן הדם. תוספתא סוף זבים.\",3,0],[8,378,3,10,\"ומ\\\"ש אבל האוכל מן האשכול של ביצים וכו'. בפרק קמא דביצה. ופירש\\\"י שלל של ביצים כשהם כבושים ושלולים וקבועים בשדרה. מן האשכול מבשר השדרה שהביצים אדוקים שם.\",4,0],[8,378,3,10,\"ומ\\\"ש או שהמחהו בחמה וכו'. פ\\\"ק דביצה ותוספתא בסוף זבים ובפ' העור והרוטב:\",5,0],[8,378,3,11,\"נבלת העוף הטהור וכו'. בפרק ח' דטהרות (משנה ו) גבי גוזל שנפל לגת ופרק שביעי דנזיר דף נ' ופרק שלישי דבכורות דף כ\\\"ג נתבאר דאפילו טומאה קלה חלה עד לכלב.\",1,0],[8,378,3,11,\"ומה שכתב וכן אם יבשה וכו'. נתבאר בפרק ראשון.\",2,0],[8,378,3,11,\"ומה שכתב והאוכל נצל של נבילת העוף הטהור ה\\\"ז טהור. אף על פי שבנצל של בהמה כתב בפרק א' שהוא ספק כתב כאן שהוא טהור משום דמשמע ליה דכיון דבנזיר פרק ז' איבעיא להו אם יש נצל לבהמה משמע דבעוף פשיטא ליה דאין נצל דאל\\\"כ הכי הוה ליה למיבעי נצל בשאר ב\\\"ח או לא:\",3,0],[8,378,3,12,\"עוף טהור שנטרף וכו'. במשנה בס״פ חטאת העוף (זבחים דף ס״ט) כרבי יוסי ורבי מאיר לגבי רבי יהודה.\",1,0],[8,378,3,12,\"ומה שכתב ואפילו נשחט בעזרה. גם זה שם שחט חולין בפנים וקדשים בחוץ אינם מטמאות בבית הבליעה.\",2,0],[8,378,3,12,\"ומ\\\"ש ואם נמלק ונמצאת טריפה וכו'. שם במשנה ודלא כרבי מאיר.\",3,0],[8,378,3,12,\"ומ\\\"ש והמולק חולין בפנים או שמלק קדשים בחוץ וכו'. שם במשנה (דף ס\\\"ח ע\\\"ב):\",4,0],[8,378,3,13,\"המולק קדשים בפנים וכו'. שם בברייתא (דף ס\\\"ט):\",1,0],[8,378,3,13,\"כיוצא בו עגלה ערופה וכו'. סוף פרק חטאת העוף (זבחים דף ע' ע״ב):\",2,0],[8,378,3,14,\"נבילת העוף הטמא טהורה וכו'. בריש טהרות (פרק א' משנה ג') וממה שכתב רבינו הרי היא כאוכלים טמאים משמע דאפילו לא נגע בה שרץ הם טמאים וכן משמע מדבריו בפירוש המשנה וקשה על זה דהא אמרי' דדוקא מי שסופו לטמא טומאה חמורה אין צריך הכשר שרץ ונבילת עוף טמא אין בה שום טומאה אלא שמוכנת לקבל טומאה על ידי מחשבה והכשר כשאר אוכלים וכן כתב ר\\\"ש וכן נראה מדברי רש\\\"י בשלהי גיד הנשה (חולין דף ק\\\"ב) ד\\\"ה ה\\\"ג וכן כתב ה\\\"ר עובדיה ז\\\"ל ותירץ הר\\\"י קורקוס ז\\\"ל שבכלל מה שכתב רבינו והוכשרה הוי הכשר מים ונגיעת שרץ כי כן נקרא הכשר שרץ והדעת מכריע דכיון דבעינן הכשר מים היינו לקבל טומאה להבא אם יגע בה שרץ כי על ידי מים לבד תיעשה אוכל [ולא] טמא למפרע וגם מדברי רבינו יש להוכיח כן כי גבי נבילת עוף טהור כתב אף על פי שלא נגע בטומאה אחרת וכאן לא כתב כן עכ\\\"ל:\",1,0],[8,378,3,15,\"אחד העוף הטהור ואחד העוף הטמא וכו'. בת\\\"כ פרשת שמיני על פסוק ולאלה תטמאו:\",1,0],[8,378,3,16,\"אבר מן המת מן העוף וכו'. כתב כן להבדיל בין אבר מן המת ואבר מן הנבילה לאבר מן השרץ שאין להם שיעור ולמד כן מדלא הזכיר התנא אלא אלו גבי הא דתנן בפרק קמא דאהלות (משנה ז') האיברים אין להם שיעור:\",1,0],[8,378,4,1,\"שמנה שרצים האמורים בתורה וכו':\",1,0],[8,378,4,2,\"השרץ אב מאבות הטומאה וכו' עד ואינו מטמא במשא. בריש כלים.\",1,0],[8,378,4,2,\"ומה שכתב והנוגע בו אינו מטמא בגדים בשעת מגעו. פשוט שהרי אין כתוב בהם שהנוגע בהם יכבס בגדיו אלא הנוגע בהם במותם יטמא עד הערב.\",2,0],[8,378,4,2,\"ומה שכתב ושיעור טומאתו בכעדשה. בתורת כהנים ובשלהי פירקא קמא דחגיגה (דף י\\\"א) ובפרק כהן גדול ונזיר (דף נ\\\"ב).\",3,0],[8,378,4,2,\"ומה שכתב וכל השרצים וכו'. משנה פרק ד' דמעילה [דף ט\\\"ו]:\",4,0],[8,378,4,3,\"האיברים אין להם שיעור וכו'. בפרק קמא דאהלות:\",1,0],[8,378,4,3,\"אבר מן השרץ כברייתו וכו'. זהו פירוש מה ששנינו האיברים אין להם שיעור:\",2,0],[8,378,4,4,\"ומ\\\"ש והוא שיהיה בבשר שעליו או במוח שבעצם כדי להעלות ארוכה. מתבאר בפרק העור והרוטב עלה קכ\\\"ה:\",1,0],[8,378,4,5,\"בשר מן החי הפורש וכו' עד ואם פירשו מן החי טהורים. בפרק העור והרוטב (חולין דף קכ״ח ע״ב):\",1,0],[8,378,4,7,\"דם השרץ כבשרו ומצטרף בכעדשה. משנה פ\\\"ד דמעילה (דף נ\\\"ד שהוא י\\\"ז):\",1,0],[8,378,4,7,\"ומ\\\"ש כל זמן שהוא מחובר בבשר. שם בגמרא אמר רב חנין וכו' ומפרש רבינו דהיינו לומר דדוקא בעוד הדם בשרץ אבל אם פירש הדם מן השרץ אינו מצטרף:\",2,0],[8,378,4,8,\"עצמות השרץ וגידיו וצפרניו טהורים. בת\\\"כ מנבלתם ולא מן העצמות ולא מן השינים ולא מן הצפרנים.\",1,0],[8,378,4,8,\"ומ״ש וגידיו: ועור החולד והעכבר וכו'. משנה וגמרא בפ' העור והרוטב (חולין קכ״ב ע״א ע״ב) וכתנא דמתני':\",2,0],[8,378,4,9,\"קוליית השרץ וכו':\",1,0],[8,378,4,10,\"ביצת השרץ המרוקמת וכו'. משנה וגמרא בפרק העור והרוטב (חולין דף קכ״ה ודף קכ״ו ע״ב) ושנינו בתוספתא דחולין פ״ח כמה היא ריקומה כדי שיראה השרץ מתוכה:\",1,0],[8,378,4,11,\"השרץ שחציו בשר וכו'. משנה שם.\",1,0],[8,378,4,11,\"ומ\\\"ש ואם השריץ ע\\\"פ כולו וכו'. יש לתמוה דבגמרא משמע איפכא בין ללישנא קמא בין ללישנא בתרא לת\\\"ק:\",2,0],[8,378,4,11,\"והר\\\"י קורקוס ז\\\"ל כתב הדבר מוכרח שדברי רבינו כר' יהודה או שסובר דלמאן דמתני לדריב\\\"ל אסיפא דהיינו על דברי רבי יהודה משמע שסובר דהלכה כמותו כיון שמפרש דבריו ואין זה מוכרח או אפשר שסובר שאינו חולק על ת\\\"ק וקצת משמע כן מדקאמר בלשון רישא וסיפא וגם זה דוחק אם לא שהיתה לרבינו גירסא אחרת ולמדו שם בברייתא חציו בשר וחציו אדמה מדכתיב בשרץ דמשמע כל שהוא משריץ ואפשר דעל ברייתא זו סמך דכיון דמרבינן כל שהוא משריץ מינה שכל שהוא חציו לארכו כולו הוא משריץ וכולו מטמא אפילו נגע באדמה ואפשר דלנוגע בבשר לא איצטריך אלא לנוגע באדמה שכל שמקצתו בשר חשיב כולו שרץ וא\\\"כ מתניתין לפ\\\"ז בלא השריץ אלא שלפ\\\"ז קשה אדריב\\\"ל ועדיין צ\\\"ע עכ\\\"ל:\",3,0],[8,378,4,12,\"בשר השרץ שנפסד וכו'. נתבאר בפ\\\"א.\",1,0],[8,378,4,12,\"ומ״ש יבש וכו'. משנה בפרק דם הנדה (נדה דף נ״ד ע״ב).\",2,0],[8,378,4,12,\"ומ״ש אפילו כאוכלים טמאים אינו מטמא. ומ״ש במה דברים אמורים במקצת השרץ וכו'. בפרק דם הנדה (נדה דף נ״ו) ופירש״י שלדו דפוס צורתו קיימת שלא נשבר ונתפזר:\",3,0],[8,378,4,12,\"ומ\\\"ש וקרוב בעיני שטומאה זו מדבריהם. אע\\\"ג דבגמרא מייתי לה מקרא משמע לרבינו דאסמכתא בעלמא היא דכיון שנתייבש כ\\\"כ הרי הוא כעפר אע\\\"פ ששלדו קיים אלא שחכמים גזרו בו טומאה:\",4,0],[8,378,4,13,\"כזית מן הנבילה וכעדשה מן השרץ וכו'. בפ״ג דטהרות ופרק כל המנחות באות מצה (מנחות דף נ״ד ע״ב):\",1,0],[8,378,4,13,\"וכתב הר\\\"י קורקוס ז\\\"ל ולא דמי לחיוב שבת דאיבעיא לן בפרק המצניע אם יש דיחוי וסלקא בתיקו וכתב רבינו בהלכות שבת פי\\\"ח דהוי ספק דהתם שאני שאם הניחה באותה שעה הוה מיפטר ולכך י\\\"ל שלא תצטרף ההנחה עם העקירה:\",2,0],[8,378,4,14,\"השרץ אינו מטמא עד שימות וכו'. בפרק קמא דאהלות ופרק קמא דחולין עלה כ\\\"א וכר\\\"ל ומפרש רבינו דרבותא קמ\\\"ל אע\\\"פ שמעורין בעור הגוף דאל\\\"כ פשיטא:\",1,0],[8,378,4,14,\"שאר שקצים ורמשים וכו'. בת\\\"כ.\",2,0],[8,378,4,14,\"ומ\\\"ש ואפילו כאוכלים טמאים אינם:\",3,0],[8,378,5,1,\"שכבת זרע אב מאבות הטומאה וכו' עד ואינה מטמאה במשא. בריש כלים.\",1,0],[8,378,5,1,\"ומ\\\"ש ואין המתטמא בה מטמא בגדים בשעת מגעו. זה פשוט דכתיב ואיש כי תצא ממנו ש\\\"ז ורחץ במים את כל בשרו וטמא עד הערב ואילו כיבוס בגדים לא קאמר:\",2,0],[8,378,5,1,\"ואחד הנוגע בה ואחד הרואה אותה בבשרו וכו'. בפרק יוצא דופן (נדה דף מ״ג ע״ב) או איש לרבות את הנוגע ובסוף זבים תנן בעל קרי כמגע שרץ כלומר שהוא ראשון:\",3,0],[8,378,5,1,\"וכמה שיעורה וכו'. בפרק יוצא דופן עלה מ\\\"ג אמר ר' חנילאי משום ר\\\"א בר\\\"ש ש\\\"ז לרואה במשהו לנוגע בכעדשה והא אנן מטמאין בכל שהן תנן מאי לאו לנוגע לא לרואה.\",4,0],[8,378,5,1,\"ומ\\\"ש ואין הרואה טמא עד שתצא ממנו. משנה שם (דף מ.) הזב ובעל קרי אינן מטמאין עד שתצא טומאתן לחוץ. ומ\\\"ש ויחתום ממנו פי האמה. שם (דף מג:) אמר שמואל זב צריך בחתימת פי האמה שנאמר או החתים בשרו מזובו והא אנן תנן מטמאים בכל שהן הוא דאמר כר' נתן דתניא ר' נתן אומר משום ר' ישמעאל זב צריך בחתימת פי האמה ולא הודו לו מ\\\"ט דר' ישמעאל דאמר קרא או החתים בשרו מזובו ורבנן ההוא מיבעי ליה לח מטמא ואינו מטמא יבש ונראה מדברי רבינו שהוא פוסק כשמואל ויש לתמוה דכיון דר' ישמעאל הוא דאמר הכי ולא הודו לו וסתם מתניתין דלא כוותיה אע\\\"ג דשמואל משמע דסבר כוותיה הא רב חנילאי סבר דלא כוותיה ואיהו עדיף דאתא כרבנן דלא הודו לו וכסתם מתניתין ואפשר היה ליישב זה לומר דטעמא משום דגרסינן בפרק המפלת עלה כ\\\"ב בעא מיניה מרב הונא הרואה קרי בקיסם מהו וכו' עד כחתימת פי האמה ופירש\\\"י הרואה קרי בקיסם וכו' עד בצר ליה שיעורא כדי קיסם וכיון דרבה ורב הונא ס\\\"ל כשמואל פסק כוותייהו וקשה שהוא ז\\\"ל פסק בסמוך דלרואה בכל שהוא כרב חנילאי ונמצא כמזכי שטרא לבי תרי ודבריו סותרים את דבריו:\",5,0],[8,378,5,1,\"וכתב הראב\\\"ד עד שתצא ממנו ויחתום ממנו פי האמה א\\\"א זה שיבוש דכל שהוא אינו צריך חתימת פי האמה וכו'. ויש לתמוה עליו איך לא הקשה עליו שהוא עצמו פסק בסמוך בהיפך וליישב דעת רבינו נאמר שהוא ז\\\"ל סובר דרב הונא לא פליג ארב חנילאי דאיהו נמי סבר דלרואה כל שהוא כסתם מתניתין ומאי דאמר אינו מטמא אלא בחתימת פי האמה לא בשיעורא קאמר אלא היינו לומר שצריך שיגע בפי האמה וכך פירשו התוספות ולישנא דרבינו דייק כן שכתב עד שתצא ממנו ויחתום ממנו פי אמה ולא כתב כדי חתימת פי אמה ובזה אין כאן לא שיבוש ולא בלבול:\",6,0],[8,378,5,1,\"אחר שכתבתי זה מצאתי שגם הריטב״א סובר כרבינו והקשה על שיטת רש״י שהיא כשיטת הראב״ד וגריס כחתימת פי האמה בכ״ף שאיך אפשר שישיב לו כפי דעת ר' נתן ולימא ליה רבה אנא אליבא דרבנן מיבעיא לי דהלכתא כוותייהו וכ״ש דקשה שאמר אותו דרך תמיהא ובדרך פשוט והוא אליבא דיחיד ולא הקשו עליו מסתם מתניתין דתנן איפכא וכמו שהקשו פרק יוצא דופן על שמואל שאמר כן ועל רב חנילאי הקשו ג״כ וכאן לא הקשו כלל ונדחק הריטב״א לקיים דברי רב הונא אפילו כרבנן ומ״מ הקשה לשיטת רש״י חדא שבכל הספרים כתיב בחתימת פי האמה בבי״ת ומשמע דלאו לשיעורא ועוד שהרי בפרק אלו דברים (פסחים דף ס״ז ע״ב) אמר ר״ש דבעל קרי צריך שיעור אמרינן דכר' נתן ס״ל משמע דלרבנן אין בעל קרי צריך שיעור ואם איתא לימא דר״ש אפילו כרבנן ומשום דחשיב ליה נוגע צריך שיעור א״כ ע״כ רב הונא אליבא דר״ש הוא דמיירי וע״ק דעיקר טעמא דבעי שיעורא היינו משום דחשיב ליה נוגע ואין דינו תלוי בשיעורא הכי הל״ל והלא הוא עצמו אינו מטמא אלא משום נוגע:\",7,0],[8,378,5,1,\"ומ\\\"ש לפיכך אפילו ראה בקיסם וכו'. הם דברים תמוהים דרב הונא דאמר (נדה דף כ\\\"ב) תיפוק ליה דהוא עצמו אינו מטמא אלא בחתימת פי האמה משמע דהיינו לומר וכיון דבקיסם ליכא חתימת פי האמה טהור וכן פירש\\\"י ע\\\"פ דרכו שפירש דלענין שיעורא אמר וכן פירשו התוספות ע\\\"פ דרכם שפירשו דלענין שיגע בחתימת פי האמה קאמר וצ\\\"ל שרבינו מפרש שרבה ששאל הרואה קרי בקיסם מהו היינו לומר אם הכניס קיסם בתוך האמה בפנים ועבר הקרי עליו ויצא ובא מפי האמה ומיבעיא ליה אי אמרינן דבעינן שמשנעקר ממנו עד שיצא מפי האמה הכל יהיה ממנו בלי שום ד\\\"א שיעבור הקרי עליו או לא ואהדר ליה דהוא עצמו כלומר כשרואה קרי בלא קיסם אינו מיטמא אלא בחתימת פי האמה כלומר אע\\\"פ שנעקר הקרי ובא סמוך לפי האמה אינו מטמא עד שיגיע לפי אמה ממש דממנו דקרא לא קאי אלא לפי אמה ממש וכיון שכן כי הכניס קיסם בפנים ועבר הקרי עליו מה בכך מאחר שאח\\\"כ הגיע לפי אמה ממש ויצתה מפי אמה טמא הוא:\",8,0],[8,378,5,1,\"ואחד הרואה מחמת בשרו וכו'. בפרק אלו דברים (דף ס\\\"ד ע\\\"ב) ובפרק בנות כותים עלה ל\\\"ה פשוט דש\\\"ז מטמאה באונס פי' באונס ממאכל או משתה וכו' כמו שנתבאר בפ\\\"ב ממחוסרי כפרה:\",9,0],[8,378,5,2,\"אין שכבת זרע של קטן מטמאה וכו'. בריש פרק בנות כותים (נדה דף ל\\\"ב ע\\\"ב) איש אין לי אלא איש בן תשע שנים ויום אחד מנין ת\\\"ל ואיש ופירש\\\"י אין לי אלא איש ואיש אשר תצא ממנו שכבת זרע:\",1,0],[8,378,5,3,\"שכבת זרע אדומה טהורה וכו'. בריש פרק בנות כותים עלה ל\\\"ב.\",1,0],[8,378,5,3,\"ומ\\\"ש ונמשכת. בתוספתא דזבים שנינו שכבת זרע היא קשורה ודומה ללובן ביצה שאינה מוזרת:\",2,0],[8,378,5,4,\"וכל ש\\\"ז שאין גופו של אדם וכו'. פרק יוצא דופן עלה מ\\\"ג אמר שמואל כל ש\\\"ז שאין כל גופו מרגיש בה אינה מטמאה מ\\\"ט ש\\\"ז אמר רחמנא בראויה להזריע וכו' לישנא אחרינא אמר שמואל וכו' עד הא טמויי מטמיא:\",1,0],[8,378,5,4,\"וכתב הראב\\\"ד על דברי רבינו לישנא בתרא דגמרא אזרועי הוא דלא מזרעא הא טמויי מטמיא עכ\\\"ל. כלומר משיג על רבינו למה לא פסק כלישנא בתרא. וי\\\"ל שטעם רבינו משום דרבא לא סבר כלישנא בתרא אבל אי קשיא הא קשיא דבתרי לישני קמאי הוה ליה למפסק כלישנא בתרא דכל ש\\\"ז שאינו יורה כחץ אינה מטמאה והוא ז\\\"ל נראה שפסק כלישנא קמא דכל שכבת זרע שאין כל גופו מרגיש בה אינה מטמאה. וע\\\"ק שפסק בבעיא דרבא כלישנא מציעאה דטמא וזה סותר מה שפסק קודם לכן כלישנא קמא ונ\\\"ל שפסק כלישנא מציעאה דאינו יורה כחץ בכלל אין גופו מרגיש הוא אלא דכי הוו תרי לישני כדי לומר מאי בינייהו אנו צריכים לומר שאינו בכלל אין גופו מרגיש בה וא\\\"כ כי נקט רבינו שאין גופו מרגיש בה הוי אינו יורה כחץ בכלל וכ\\\"ש שכבר ביאר בסמוך דנעקר בהרגשה ויצא שלא בהרגשה טמא ותו ליכא למיטעי ואילו הוה נקט לישנא דשאינו יורה כחץ הוה אפשר לומר דאם נעקר שלא בהרגשה (ויצא בהרגשה) ולכלול גם את זה נקט לישנא דשאין גופו מרגיש בה:\",2,0],[8,378,5,5,\"המהרהר בלילה וכו'. בפ״ח דמקוואות המהרהר בלילה ועמד ומצא בשרו כלומר איברו חם טמא ובפרק יוצא דופן (נדה דף מ״ג) מותיב מינה לשמואל דאמר כל שכבת זרע שאין כל גופו מרגיש בה אינה מטמאה דהא הכא כשמצא בשרו חם טמא שמא יצא ממנו אמאי והא לא ארגיש ומוקי לה במשמש מטתו בחלומו דא״א בלא הרגשה.\",1,0],[8,378,5,5,\"ומה שכתב הרהר ולא מצא בשרו חם וכו'. נלמד ממה שנתבאר בסמוך וכך הוא בתוספתא כלשון רבינו:\",2,0],[8,378,5,6,\"המטיל מים וכו'. בפ\\\"ח דמקוואות.\",1,0],[8,378,5,6,\"ומ\\\"ש היו לבנים ונמשכים טמא. שם וכת\\\"ק פי' חלוקים שמטיף טיפין חלוקים כמין שלשלת כך כתב ה\\\"ר עובדיה ורבינו כתב חלוקים שלשלת ההזלה וכשזה יארע בתחלה אנו אומרים שמא עצר השתן הוא זה ואינו קרי וכן אם הכל כן מתחילה ועד סוף אבל אם באמצע או בסוף לבד ולא בתחלה הוי כמין קרי וטמא ופי' נמשכים שיהא השתן מתדבק קצתו בקצתו ואז הוא טמא בין יהיה בתחלה או באמצע או בסוף.\",2,0],[8,378,5,6,\"ומ\\\"ש המטיל טיפין עבות וכו'. שם המטיל טיפין עבות מתוך האמה טמא דברי ר\\\"א חסמא ומשמע דרבנן פליגי עליה ואמרי טהור:\",3,0],[8,378,5,7,\"בעל קרי שטבל וכו'. גם זה שם.\",1,0],[8,378,5,7,\"ומ\\\"ש במה דברים אמורים בחולה וכו'. שם וכר' יוסי ופסק כמותו משום דבסוף פ\\\"ק דחולין (דף כ\\\"ד ע\\\"ב) מפרשי אמוראי מילתיה.\",2,0],[8,378,5,7,\"ומ\\\"ש עד כמה הוא ילד וכו'. בספ\\\"ק דחולין (שם):\",3,0],[8,378,5,8,\"וכל אשה ששמשה וכו'. בפ\\\"ח דמקוואות:\",1,0],[8,378,5,9,\"אחד האיש וכו'. מפורש בתורה סוף פרשת מצורע:\",1,0],[8,378,5,9,\"ואין האשה וכו'. בפרק יוצא דופן עלה מ\\\"א ומ\\\"ב אליבא דרבנן.\",2,0],[8,378,5,9,\"ומ״ש והוא שתהיה בת שלש שנים וכו'. בת״כ ואשה פרט לקטנה או יכול שאני מוציא בת ג' שנים ויום א' ת״ל ואשה ואיתא בפרק בנות כותים (נדה דף ל״ב). ומ״ש בספרי\",3,0],[8,378,5,9,\"רבינו אשר ישכב את אשה ט\\\"ס הוא דאדרבה מאשה הוה משמע למעט כל קטנה ולא מרבינן בת שלש שנים אלא מוי\\\"ו דואשה ועוד שזה אינו פסוק אלא כך צריך לגרוס שנאמר ואשה אשר ישכב איש אותה.\",4,0],[8,378,5,9,\"ומ\\\"ש היתה קטנה מבת שלש שנים וכו'. מתבאר ממה שנזכר בסמוך.\",5,0],[8,378,5,9,\"ומ״ש לפיכך הבועל גדולה וכו'. בפ' ד' אחין (יבמות דף ל״ד ע״ב) ובת״כ אותה פרט לדבר אחר שכבת זרע פרט למערה:\",6,0],[8,378,5,11,\"האשה שפלטה ש״ז וכו'. בפרק ח' דמקואות כר״א בן עזריה דאמר הפולטת ש״ז ביום השלישי טהורה וכמו שיתבאר בסמוך ומ״מ יש לתמוה על רבינו למה לא פסק כר״ע דהלכה כמותו מחבירו או כחכמים דאמרי בפרק ר״ע (שבת דף ע״ז ע״ב) זו דברי רבי ישמעאל ור״ע אבל חכ״א שש עונות שלימות וזה היה נכון יותר משום דרבים נינהו ועוד דמדקאמר גמרא אבל חכ״א משמע שדוחה דברי הראשונים ותופס דברי חכמים עיקר וי״ל שרבינו גורס אבל חכמים אומרים שלש עונות וכך כתב בפי' המשנה פ״ח דמקואות והיא גירסת הרשב״א ובפרק ר״ע (שבת דף פ״ו) אמרו בשלמא ר״א בן עזריה כרבנן דסברי בה' עבוד פרישה פירוש דכולהו ממתן תורה ילפי דכתיב היו נכונים לשלשת ימים ולר״א בן עזריה בחמישי פירשו ובשבת ניתנה תורה לכ״ע ובליל שבת טבלו כולם וצ״ל לפי שיטה זו דבחמישי עבוד פרישה היינו בבקר בהשכמה ואז יש ג' עונות יום ה' וליל ו' ויום ו' ובזה יבא ר״א כרבנן דבעו ג' עונות והשתא ניחא שפסק כחכמים.\",1,0],[8,378,5,11,\"ומ\\\"ש הרי היא טמאה כרואה קרי לפיכך סותרת יום א' וכו'. בפרק יוצא דופן עלה מ\\\"ב.\",2,0],[8,378,5,11,\"ומ\\\"ש אע\\\"פ שלא יצתה לחוץ וכו'. זהו מה שאמרו שם דרואה הויא לטמא בפנים כבחוץ.\",3,0],[8,378,5,11,\"ומ\\\"ש אלא נעקרה והגיעה לבין השיניים וכו'. שם בעלה מ\\\"א ע\\\"ב על מאי דתנן כל הנשים מטמאות בבית החיצון אמרינן הי ניהו בית החיצון ואר\\\"י בין השיניים:\",4,0],[8,378,5,12,\"שכבת זרע עצמה שנפלטה וכו'. פשוט הוא וכן משמע בפרק ר\\\"ע:\",1,0],[8,378,5,13,\"וכמה היא עונה יום או לילה. הכי אמרינן בפרק ר\\\"ע:\",1,0],[8,378,5,13,\"כיצד נבעלה בליל שבת וכו'. כן פי' רבינו דברי ר\\\"א בן עזריה בפרק ח' דמקוואות ולא כדפרש\\\"י בפרק רבי עקיבא:\",2,0],[8,378,5,13,\"והאיש שפירשה ממנו ש\\\"ז וכו'. כך היא הגירסא הנכונה והדין בפר\\\"ע עלה פ\\\"ו (ע\\\"ב) על פלוגתא דהני תנאי אמר רב חסדא מחלוקת שפירשה מהאשה אבל פירשה מהאיש טמאה כל זמן שהיא לחה.\",3,0],[8,378,5,13,\"ומה שכתב והפורש ממנו טמא. נראה שרבינו מפרש כר\\\"ח ור\\\"ת שפירשו דמיירי בזכר שנרבע ופלט ש\\\"ז ובהא שייך לומר שהפולט טמא אפילו פלט אחר כמה עונות:\",4,0],[8,378,5,14,\"שכבת זרע אינה מטמאה וכו'. משנה בריש פרק דם הנדה (נדה דף נ״ד ע״ב):\",1,0],[8,378,5,15,\"כבר ביארנו בפרק זה שהרואה קרי וכו' וכן האשה שפלטה וכו' אבל שאר האמורים בפרק זה וכו'. בתוספתא דמקוואות פ\\\"ו כל אלו שאמרו טהורים לחולין וטמאים לתרומה:\",1,0],[8,378,5,16,\"נכרית שפלטה וכו'. פ\\\"ח דמקואות.\",1,0],[8,378,5,16,\"ומ\\\"ש וכן הבהמה וכו'. הכי משמע בפרק ר\\\"ע עלה פ\\\"ו.\",2,0],[8,378,5,16,\"ומ״ש לאחר זמן זה הרי היא ספק וכו'. שם בעיא בין בנכרית בין בבהמה ולא איפשיטא ואע״ג דנכרית משמע דאיפשיטא שם באת״ל ע״פ דרכו של רבינו לפסוק כאת״ל לא חש רבינו לההוא את״ל משום דבפרק בנות כותים (נדה דף ל״ד ע״ב) מסיק לה בתיקו:\",3,0],[8,378,5,17,\"כבר ביארנו וכו' לפיכך בת ישראל וכו'. בפ\\\"ח דמקואות ונתבאר בפ' בנות כותים דטהורה אפילו מדבריהם:\",1,0],[8,378,5,18,\"עכו\\\"ם שהרגיש וכו' וטבל. פי' לשם גירות פ' יוצא דופן עלה מ\\\"ג בעיא דלא איפשיטא:\",1,0],[8,378,5,19,\"גדולה ששכב אותה וכו'. בת״כ דריש ואשה אשר ישכב איש אותה איש פרט לקטן ומשמע לרבינו דהיינו קטן פחות מבן ט' דומיא דאשה דלא ממעטינן מינה אלא פחותה מבת ג' והכי איתא בריש פרק בנות כותים (נדה דף ל״ב).\",1,0],[8,378,5,19,\"ומ\\\"ש או נכרי. מבואר במה שקדם בסמוך.\",2,0],[8,378,5,19,\"ומ\\\"ש או בהמה. ממעיט מדכתיב איש.\",3,0],[8,378,5,19,\"ומה שכתב שנאמר ואיש אשר ישכב את אשה. גם פה הוא טעות סופר וצריך להגיה ולכתוב במקומו ואשה אשר ישכב איש אותה:\",4,0],[8,378,6,1,\"טומאת ע״ז מד״ס. מבואר בפרק רבי עקיבא (שבת דף פ״ב פ״ג):\",1,0],[8,378,6,1,\"וארבע טומאות יש בה וכו'. מתבאר והולך:\",2,0],[8,378,6,2,\"עבודה זרה עצמה מטמאה וכו' כשרץ וכו'. משנה בפרק כל הצלמים (עבודה זרה דף מ״ו ע״ב) וכחכמים אליבא דר״א דפרק ר' עקיבא (שבת דף פ״ב ע״ב) דפשטא דמתנייתא אתו כוותיה.\",1,0],[8,378,6,2,\"ומ״ש ושיעורה כזית. בפרק ר״ע (שבת דף פ״ג ע״ב) ובירושלמי פ״ג דעבודה זרה:\",2,0],[8,378,6,3,\"קצץ אבר ממנה וכו'. גם זה שם:\",1,0],[8,378,6,3,\"כקולי אבות הטומאות דנו בה וכו'. ג\\\"ז שם:\",2,0],[8,378,6,4,\"נתפרקה עבודה זרה אף על פי שההדיוט יכול להחזירה וכו'. שם בעיא דלא איפשיטא:\",1,0],[8,378,6,5,\"כל משמשי ע\\\"ז כשרץ. גם זה שם ברייתא ע\\\"ז כשרץ ומשמשיה כשרץ ומשמע דבין לעיקר טומאתה בין לשיעורה משוה להו.\",1,0],[8,378,6,5,\"ומ\\\"ש ואפילו קצץ ממשמשים כזית מן הכלי וכו'. מאחר ששיעורה כזית יש לנו לומר כן דסתם כלי גדול מכזית.\",2,0],[8,378,6,5,\"ומ\\\"ש זו חומר במשמשיה וכו'. פשוט הוא ממה שקדם שע\\\"ז אינה מטמאה לאיברים ומשמשיה אם קצץ מהם כזית טמא:\",3,0],[8,378,6,5,\"ובית ע\\\"ז עצמו וכו':\",4,0],[8,378,6,6,\"המכניס ראשו ורובו וכו'. בתוספתא דע\\\"ז פרק שביעי וירושלמי פ\\\"ג דע\\\"ז.\",1,0],[8,378,6,6,\"ומ\\\"ש וכן כלי חרס וכו' ספסלין וכו'. תוספתא בסוף זבים.\",2,0],[8,378,6,6,\"ומ\\\"ש וכולם ראשון לטומאה. מאחר דעבודה זרה היא אב הוו אלו ראשון:\",3,0],[8,378,6,7,\"תקרובת ע״ז וכו'. בפ״ק דחולין עלה י״ג ע״ב וכרבנן דר״י בן בתירא וכלישנא בתרא דמוקי סתם מתניתין כוותייהו ואע״ג דבפרק אין מעמידין (עבודה זרה דף ל״ב ע״ב) ובפרק כל הצלמים מוקי סתם מתניתין כר״י בן בתירא הא דחולין דלישנא בתרא עדיפא דהויא כרבים ועוד דטומאת ע״ז דרבנן ונקטינן בה לקולא כדמסקי בפרק ר״ע.\",1,0],[8,378,6,7,\"ומ\\\"ש ושיעורה בכזית, כמו שיעור ע\\\"ז עצמה. ובסמוך יתבאר דיין נסך מטמא בכזית:\",2,0],[8,378,6,7,\"כל דבר שמקריבין לה וכו'. בפ\\\"ב דע\\\"ז (דף כ\\\"ט ע\\\"ב) שנינו בשר היוצא מבית ע\\\"ז אסור מפני שהוא כזבחי מתים ובפרק העור והרוטב קכ\\\"ט הרי אמרו תקרובת ע\\\"ז של אוכלין טמאה.\",3,0],[8,378,6,7,\"ומ\\\"ש ואע\\\"פ שאין תקרובת ע\\\"ז של אוכלין וכו' וכן ע\\\"ז ומשמשיה וכו'. הכל בע\\\"ז פ' רבי ישמעאל (דף נ\\\"ב) דברי רבינו כדברי התוספות שפירשו הא דקאמר כלים לא מבעיא לן דכיון דאית להו טהרה במקוה טומאה נמי בטלה דמיירי בכלים של תקרובת ע\\\"ז:\",4,0],[8,378,6,8,\"יין שנתנסך לע\\\"ז מטמאה וכו'. תוספתא בסוף זבים יין שראה את העכו\\\"ם שהוא מנסכו אם יש בו כזית מטמאים טומאה חמורה ואם לאו אין מטמאין אלא טומאת משקין בלבד ובפרק שני דע\\\"ז (דף ל' ע\\\"ב) יין נסך אסור בהנאה ומטמא טומאה חמורה בכזית סתם יינם אסור בהנאה ומטמא טומאת משקין ברביעית.\",1,0],[8,378,6,8,\"ומ\\\"ש רבינו שנאמר אשר חלב זבחימו יאכלו וכו'. שם (דף כ\\\"ט ע\\\"ב) אמתניתין דאלו אסורים בהנאה היין:\",2,0],[8,378,6,11,\"כל אב טומאה שמטמא במגע וכו'. בפ' אחרון דזבים משנה ראשונה ושנייה ועשירית מתבאר מפירוש רבינו בהן:\",1,0],[8,378,6,12,\"ומ\\\"ש בד\\\"א בשאר כל האבות חוץ מן הנבילה והמרכב וכו'. מבואר במשנה עשירית שכתבתי שהיא בסוף זבים וחילוק הנבילה נתבאר בדברי רבינו בתחלת הלכות אלו וחילוק המרכב מן המשכב נתבאר בפ\\\"ו מהלכות מטמאי משכב ומושב.\",1,0],[8,378,6,12,\"ומה שכתב והנושא מטמא בגדים. בסוף זבים משנה הנושא את המרכב וכו' הנושא את הנבילה וכו' עד ופוסל א' וכפי' רבינו ור\\\"ש:\",2,0],[8,378,6,13,\"ומ\\\"ש מי חטאת שיש בהם כדי הזייה וכו'. במשנה פ\\\"ק דכלים למעלה מהם נבילה ומי חטאת שיש בהם כדי הזיה שהם מטמאים את האדם במשא לטמא בגדים וחשוכי בגדים במגע.\",1,0],[8,378,6,13,\"ומ\\\"ש הרי הנוגע בהם מטמא בגדים בשעת מגעו משום נושא מפני שא\\\"א שיגע במים שלא יסיט אותם וכו' וכן הנוגע בצמר הנבילה או בנימי המרכב וכו'. תוספתא פ\\\"ה דזבים וכתבה רבינו שמשון שם בפרק הנזכר וגירסתו היא הנכונה ולפ\\\"ז הא דתנן וחשוכי בגדים במגע היינו לומר דאין מטמאין בגדים מדין מגע אלא מדין מסיט וכתב הר\\\"י קורקוס ז\\\"ל ואפשר דנ\\\"מ לאם היו קרושין כגליד דליכא היסט:\",2,0],[8,378,6,14,\"הבולע נבלת עוף טהור וכו'. משנה פ\\\"ה דזבים האוכל מנבלת עוף טהור והיא בבית הבליעה מטמא שנים ופוסל אחד וכו' הקיאה או בלעה מטמא א' ופוסל א' וכתב רבינו שם כבר ביארנו וכו' שבולע נבלת עוף טהור מטמא בגדים בשעת בליעתו והוא אז כמי שנגע באב מאבות הטומאה דאורייתא וכאשר הקיאה אחר שבלעה או בלע אותה אחר שנכנסה באסטומכא יהיה כמו שפירש ממטמאיו וישאר ראשון לטומאה ולא יטמא בגדים אז עכ\\\"ל.\",1,0],[8,378,6,14,\"ומ\\\"ש רבינו פה וכבר ביארנו. הוא בפ\\\"ג מהלכות אלו:\",2,0],[8,378,6,15,\"השורף פרה אדומה וכו' כמו שביארנו. בפרק קמא דפרה.\",1,0],[8,378,6,15,\"ומ״ש רבינו אם נגעו באוכלים וכו'. מפשט לשון רבינו נראה דאשורף ומשלח קאי ודבר תימה הוא שהיאך אפשר שיטמאו בגדים ולא יטמאו אוכלים אלא להיות שני לכך נראה דאפרה ופרים ושעיר עצמם קאי והוא מדאיתא בפרק טבול יום (זבחים דף ק״ה) פרה ופרים ושעיר המשתלח וכו' והן עצמם אינם מטמאים בגדים אבל מטמאים אוכלים ומשקים דברי ר' מאיר וחכמים אומרים פרה ופרים מטמאים אוכלים ומשקים ושעיר המשתלח אינו מטמא [אוכלים ומשקים] מפני שהוא חי ומכל מקום צריך לי למוד מנין לו שאינן מטמאין אוכלים אלא להיות שני ועוד קשה שנראה מדבריו ששעיר המשתלח גם כן מטמא אוכלין והיינו כרבי מאיר ולמה פסק כמותו במקום חכמים וצריך עיון:\",2,0],[8,378,6,16,\"הנוגע באב מאבות הטומאה וכו'. בת\\\"כ פרשת שמיני.\",1,0],[8,378,6,16,\"ומ\\\"ש וכן זב שדרס על המשכב וכו'. בתוספתא דמכשירין פרק שני ונראה מתוך דבריהם שהטעם מפני שאין הטמא נטהר אלא בעלייתו מהמקוה לא בעודו בתוך המקוה:\",2,0],[8,378,7,1,\"דבר מפורש בתורה וכו'. אבל מדברי סופרים גזרו על האוכל הטמא וכו'. פרק קמא דפסחים עלה י\\\"ד.\",1,0],[8,378,7,1,\"ומ\\\"ש וכן אם נגע אוכל הטמא במשקין טמאין. ומ\\\"ש ואין אוכל מטמא כלי וכו' ואפילו מדבריהם. בפרק קמא דנדה עלה ז' (ע\\\"ב).\",2,0],[8,378,7,1,\"ומ\\\"ש וכן גזרו על המשקים טמאים שיטמאו אוכלין או משקין או כלים שנגעו בהם. גם זה שם:\",3,0],[8,378,7,2,\"אין לך ולד הטומאה וכו'. בפ\\\"ח דפרה כל ולד הטומאות אינו מטמא כלים אלא משקה נטמא משקה טימאהו:\",1,0],[8,378,7,2,\"ומ\\\"ש והוא שיהיו אותם המשקים טמאים מחמת אב וכו'. בפ\\\"ק דשבת עלה י\\\"ד ע\\\"ב אהא דמני בפוסלין את התרומה מדרבנן אוכלים וכלים שנטמאו במשקים קאמר כלים דמיטמאו במשקים דמאי אילימא במשקים דזב דאורייתא נינהו וכו' אלא במשקין הבאים מחמת שרץ וגזירה משום משקים דזב ומשמע לרבינו דהיינו לומר שצריך שיהיו המשקים טמאים מחמת שרץ וכיוצא בו שהוא אב הטומאה כדי שיטמאו כלים ובירושלמי פרק חומר בקדש אמרו היו ידיו טמאות ואחורי הכוס טהורים משקה לחוץ ע\\\"ג הכוס ואחזו בבית צביטתו פשיטא שאין משקה מיטמא מן היד לטמא את הכוס:\",2,0],[8,378,7,2,\"והראב״ד כתב טמאים מחמת אב א״א ריבה דברים ונקודים שלא לצורך וכו'. טעמו דאמרינן בברכות פרק אלו דברים (ברכות דף נ״ב) נוטלים לידים ואחר כך מוזגין את הכוס שאם אתה אומר מוזגין את הכוס תחלה גזירה שמא יטמאו משקין שאחורי הכוס מחמת ידים ויחזרו ויטמאו את הכוס ואי אפשר לומר דמחמת ידים דקאמר לא טומאת ידים לבד קאמר אלא היינו לומר שיהא טמא טומאת הגוף מחמת שרץ וכיוצא בו וכשיגע בידיו במשקין שבאחורי הכוס יטמאם ויחזרו ויטמאו את הכוס דהא פריך התם וליטמאו ידים לכוס כלומר בלא משקין ומשני ידים שניות הם ואין שני עושה ג' בחולין אלא על ידי משקין:\",3,0],[8,378,7,2,\"וכתב הר\\\"י קורקוס ז\\\"ל דההיא לא מכרעא כולי האי דלב\\\"ש הוא שאמרו כן ואע\\\"ג דמשמע דב\\\"ה מודו בעיקר דינא אפשר דלטעמייהו קאמרי להו כלומר אפילו יהיה הדין כן איכא טעמא להקדים מזיגת הכוס ולא שבקינן פשטא דסוגיא בשבת ופשיטותא דירושלמי מקמי ההיא דאלו דברים וכיון דמדרבנן הוא אזלינן לקולא עד כאן לשונו. וכתב עוד ולפי שיטת רבינו יצטרך לפרש מ\\\"ש בפ\\\"ב דטבול יום עלה דההיא דקדירה וכו' ואם היו ידיו מסואבות הכל טמא דלא קאי אקדירה אלא אמשקים ופירוש הכל בין משקה תרומה בין משקה חולין ע\\\"כ:\",4,0],[8,378,7,2,\"ומפני מה גזרו וכו'. מבואר במ\\\"ש בסמוך דאיתא פ\\\"ק דשבת:\",5,0],[8,378,7,3,\"כשגזרו על המשקים וכו'. בפכ״ה דכלים וטעמא מפרש בר״פ על אלו מומין (בכורות דף ל״ח).\",1,0],[8,378,7,3,\"ומ\\\"ש בד\\\"א לתרומה אבל לקדש וכו'. גם זה שם בפכ\\\"ה דכלים ופרק חומר בקדש (דף כ\\\"ד).\",2,0],[8,378,7,3,\"ומ\\\"ש בין בכלי חרס בין בכלי שטף: כתב הראב\\\"ד א\\\"א אין השכל נותן שיעשו וכו'. וההיא דבכורות היא ר\\\"פ על אלו מומין וכבר ביאר הראב\\\"ד המקום שממנו למד רבינו לומר כן דמקיש כלי שטף לכלי חרס וא\\\"כ מה כלי שטף נטמא גבו לא נטמא תוכו אבל גבו מיהא טמא אף כלי חרס כן והראב\\\"ד משיג עליו שאין השכל נותן שיהיו משקים מטמאין כלי חרס מגבו מה שאין המת והשרץ מטמאים ואם תאמר שעשו מעלה במשקים מפני שהם עלולים לקבל טומאה כשם שעשו בהם שלעולם הם תחלה לכך כתב ולא גזרו חכמים במשקים אלא משום משקה זב וזבה וכו' ועל ראיית רבינו מפרק על אלו מומין טען הראב\\\"ד דאינה ראיה דהתם לא להקיש כלי חרס לכלי שטף באו כי היכי דנימא מה כלי שטף מיטמא מגבו אף כלי חרס מיטמא מגבו ואדרבה להקיש כלי שטף לכלי חרס באו לומר דכי היכי דכלי חרס בעלמא חלוק גבו מתוכו אף כלי שטף הכי חלוק גבו מתוכו ומיהו הא כדאיתא והא כדאיתא דכלי חרס אינו מקבל טומאה מגבו כלל אפילו לגבו וכלי שטף מקבל טומאה לגבו מיהא וזה פירוש ומכלי שטף נסבא וכו' ולדעת רבינו י\\\"ל דכיון דפשטא דגמ' משמע שמשוה אותם זה לזה וזה לזה ולענין מה שהוקשה לו שאין השכל נותן וכו' י\\\"ל דמשום דמשקים עלולים לקבל טומאה עבוד בהו האי מעלה לטמא יותר ממה שהזב והזבה עצמם מטמאין כי היכי דעבוד בהו שיהיו תחלה לעולם:\",3,0],[8,378,7,4,\"כבר ביארנו וכו' ולמה לא עשו בטומאת משקים היכר זה וכו'. בריש פרק על אלו מומין (בכורות דף ל״ח):\",1,0],[8,378,7,5,\"כבר ביארנו שהאוכלים והמשקים וכו'. בפרק ה' מטומאת מת.\",1,0],[8,378,7,5,\"ומה שכתב אבל המשקים אחד משקה שנגע באב הטומאה או שנגע בראשון וכו'. במשנה פרק ב' דטבול יום ושאר כל הטמאים בין קלים בין חמורים משקים היוצאים מהם כמשקים שהוא נוגע בהם אלו ואלו תחלה ובפירקא קמא דפסחים (דף י\\\"ד ע\\\"ב) אמרו אי מדרבנן מאי איריא נטמאו באב הטומאה אפילו בראשון ושני נמי תחלה הוו דתנן כל הפוסל את התרומה מטמא את המשקים להיות תחלה ובתוספתא פרק א' דטבול יום אחד משקה שנטמא באב הטומאה ואחד משקה שנטמא בולד הטומאה ה\\\"ז תחלה לעולם ומטמא את חבירו וחבירו את חבירו אפילו הם מאה.\",2,0],[8,378,7,5,\"ומה שכתב וכולם מטמאים את הכלים. בפרק ח' דפרה כל ולד הטומאות אינו מטמא כלים אלא משקה נטמא משקה טימאן ופירושה מבואר דולד הטומאה היינו ראשון ושני ואינם מטמאים לפי שאין כלי מקבל טומאה אלא מאב הטומאה אבל המשקה אף על פי שלא נטמא אלא מולד הטומאה מטמא כלים:\",3,0],[8,378,7,5,\"וכן כלי שנטמאו אחוריו במשקין וכו'. בפרק שמיני דטהרות אחורי כלים שנטמאו במשקים רבי אליעזר אומר מטמאין את המשקים ואין פוסלין את האוכלין רבי יהושע אומר מטמאים את המשקים ופוסלים את האוכלים ובפירקא קמא דנדה (דף ז':) איפסיקא הלכתא כרבי אליעזר ומפרש התם דה\\\"ק רבי אליעזר מטמאין את המשקים אפילו דחולין ואין פוסלים את האוכלין אפילו דתרומה:\",4,0],[8,378,7,5,\"ודע דאמרינן בפירקא קמא דנדה ומ\\\"ש אחורי כלים דנקט משום דקילי דתנן כלי שנטמא מאחוריו במשקין אחוריו טמאים תוכו אזנו ואוגניו וידיו טהורים נטמא תוכו כולו טמא ופירש רש\\\"י משום דקילי אבל תוכו כיון דהחמירו ביה רבנן וכו' מודה רבי אליעזר שפוסלין את האוכלין וכן כתב רבינו שמשון בפרק ב' דטבול יום.\",5,0],[8,378,7,5,\"ומה שכתב ומטמאים כלים אחרים וכו'. על פי מה שנתבאר דמשקין מטמאין כלים:\",6,0],[8,378,7,6,\"ומ\\\"ש אחורי הכלי שנטמאו במשקין וכו' אפילו אוכלי תרומה הרי הם טהורים. ע\\\"פ מה שנתבאר דר\\\"א דאמר אין פוסלין את האוכלין היינו אפילו אוכלים דתרומה.\",1,0],[8,378,7,6,\"ומ\\\"ש שהכלי שנטמאו אחוריו ה\\\"ז טמא כולו לקדש וכו'. משנה בר\\\"פ חומר בקדש (דף כ' ע\\\"ב) ובפרק כ\\\"ה דכלים:\",2,0],[8,378,8,1,\"כל הנוגע בידיו בראשון לטומאה וכו'. ברפ\\\"ג דידים האוכלים והכלים שנטמאו במשקים מטמאים את הידים להיות שניות דברי ר' יהושע וחכ\\\"א את שנטמא באב הטומאה מטמא את הידים בולד הטומאה אינו מטמא את הידים והלכה כחכמים דאמרי את שנטמא באב הטומאה דה\\\"ל ראשון בין שהוא אוכל או כלי מטמא את הידים ואין צ\\\"ל אם הוא אדם או משקים.\",1,0],[8,378,8,1,\"ומ\\\"ש עד הפרק. כלומר עד חיבור היד לזרוע שכל זה קרוי יד כדמשמע בפרק כל הבשר ובפרק שני דידים שנינו שהידים טומאתן וטהרתן עד הפרק.\",2,0],[8,378,8,1,\"ומ\\\"ש וכן המכניס ידיו וכו'. שם וכחכמים.\",3,0],[8,378,8,1,\"ומה שכתב או שהכניס ידיו לבית המנוגע. גם זה שם.\",4,0],[8,378,8,1,\"ומ\\\"ש וטומאת הידים. בפ\\\"ק דשבת (דף י\\\"ד):\",5,0],[8,378,8,1,\"וכתב הראב\\\"ד אוכל או משקים א\\\"א כן הוא במשנת ידים וכו'. התם על ידי משקין נטמא כלומר ומש\\\"ה אינו מטמא את הידים אבל אם נטמא כלי בשרץ מטמא את הידים אע\\\"פ שאינו אלא ולד ומקום תפיסת דברי הראב\\\"ד כתוב בטעות סופרים וצריך למוחקו ולכתוב במקומו או כלי:\",6,0],[8,378,8,2,\"הידים שניות אפילו הכניס ידיו לבית המנוגע וכו'. ברפ\\\"ג דידים וכחכמים.\",1,0],[8,378,8,2,\"ומ\\\"ש או שנגע בידיו באדם וכו'. שם כל המטמא בגדים בשעת מגעו מטמא את הידים להיות תחלה דברי ר\\\"ע וחכ\\\"א להיות שניות:\",2,0],[8,378,8,3,\"הפיגול והנותר וכו'. בסוף פסחים (דף ק\\\"כ) תנן הפיגול והנותר מטמאים את הידים ובסוף פ\\\"ד דמעילה (דף י\\\"ז) תנן שהפיגול והנותר אינן מצטרפין לטומאת ידים מפני שהיא מדרבנן.\",1,0],[8,378,8,3,\"ומ\\\"ש אבל שאר אוכלין מצטרפים. שם במשנה כל האוכלים מצטרפים זה עם זה לפסול את הגויה בכחצי פרס.\",2,0],[8,378,8,3,\"ומ״ש וצריד של מנחות. בפ״ב דחולין (דף ל״ז) בעיא דלא איפשיטא ובפרק המנחות והנסכים (מנחות דף ק״ב ע״ב) אמרו דלא מיבעיא ליה אלא מדאורייתא דאילו מדרבנן פשיטא ליה דמונין ראשון ושני ופירש״י צריד של מנחות קורטי קמח הצרוד במנחה ואין שמן נכנס לתוכו וקי״ל חיבת הקדש מכשרת מונים בו ראשון ושני כלומר אם נטמא מטמא אחרים או לא.\",3,0],[8,378,8,3,\"ומ\\\"ש ששיעורן בכביצה. בסוף פסחים איכא מ\\\"ד ששיעור פיגול ונותר לטמא את הידים הוי בכזית ואיכא מ\\\"ד דהוי בכביצה. ופסק בה רבינו להקל בדרבנן:\",4,0],[8,378,8,3,\"כתב הראב\\\"ד כמה דבריו מבולבלים ומה ענין ערבוב צריד של מנחות וכו' ולדעת רבינו י\\\"ל דסמך אההיא דפרק המנחות והנסכים שכתבתי בסמוך דמדרבנן פשיטא ליה דמונים בו ראשון ושני:\",5,0],[8,378,8,4,\"קולית הפיגול או הנותר וכו'. בפרק העור והרוטב (חולין דף קכ״ה) תנן קולית המוקדשין הנוגע בה בין נקובה בין סתומה טמא ופירש״י הפיגול והנותר מטמאים את הידים וגזרו אף בעצמות ששימשו נותר [ובגמ' שם] הואיל ונעשו בסיס לדבר האסור ופירש״י בפרק כיצד צולין (פסחים דף פ״ג) ששימשו נותר שנותר בהם מוח חוץ לזמנו ושמשוהו העצמות הללו:\",1,0],[8,378,8,5,\"בשר קדש שיצא וכו'. בפרק כיצד צולין עלה פ\\\"ה איבעיא להו יוצא גזרו ביה רבנן טומאה או לא מי אמרינן נותר דגזרו ביה טומאה (משום) דאתי לאיעצולי ביה אבל יוצא אפוקי בידים לא מפקי ליה בידים לא גזרו ביה רבנן טומאה או דילמא לא שנא ואסיקנא ביוצא בפסח לא מיבעיא לן דלא גזרו טומאה משום דבני חבורה זריזין הם ומזהר זהירי ביה כי קא מיבעיא לן ביוצא בקדשים מאי תיקו:\",1,0],[8,378,8,6,\"אין טומאת ידים במקדש וכו'. בפ\\\"ק דפסחים (דף י\\\"ט):\",1,0],[8,378,8,7,\"מי שנטמאת ידו אחת וכו'. משנה בפ' חומר בקדש בתרומה אם נטמאת אחת מידיו חבירתה טהורה ובקדש מטביל את שתיהן שהיד מטמא את חבירתה בקדש אבל [לא] בתרומה ומשמע דהכי פירושא דמתניתין בתרומה אם נטמאת אחת מידיו בטומאת ידים אע\\\"פ שנגעה בחבירתה חבירתה טהורה ובקדש מטביל את שתיהן אם נגעה ידו אחת באחרת אבל אם לא נגעה זו בזו אינו צריך להטביל אלא הטמאה בלבד ותני והדר מפרש שהיד מטמאה את חבירתה בקדש אבל לא בתרומה.\",1,0],[8,378,8,7,\"ומ\\\"ש אבל לתרומה בנטילת ידים בלבד יטהרו ידיו. משנה פ\\\"ב דחגיגה נוטלין לידים לחולין ולמעשר ולתרומה ולקדש מטבילין ופירש\\\"י לחולין ולמעשר ולתרומה די להם בנטילה בכלי שאין בו אלא רביעית מים. ולקדש מטבילין אבל לאכול שלמים או חטאת או אשם לכהנים יש מעלה שצריך להטביל ידים במ' סאה ואע\\\"פ שאינם אלא סתם ידים שלא נגעו בטומאה [דאורייתא] המטמאה כל הגוף:\",2,0],[8,378,8,8,\"שלמה ובית דינו גזרו וכו' עד אף לתרומה. פרק קמא דשבת עלה י\\\"ד (ע\\\"ב):\",1,0],[8,378,8,8,\"וכתב הראב\\\"ד ואחר כך גזרו על אכילת חולין שצריך נטילת ידים עכ\\\"ל. ואין מזה תפיסה על רבינו שאין כאן מקום דין נטילה לחולין ובהלכות ברכות שהוא מקומו כתבו.\",2,0],[8,378,8,8,\"ומ\\\"ש ואם נגע בתרומה. בסוף זבים ומני ידים בהדי הנך דפוסלין את התרומה.\",3,0],[8,378,8,8,\"ומ\\\"ש ונשרפת על טומאה זו. מימרא דאילפא בפרק קמא דשבת (דף י\\\"ז ע\\\"ב):\",4,0],[8,378,8,9,\"לט אדם ידיו במפה וכו'. בפרק כל הבשר (חולין דף ק״ז) התירו מפה לאוכלי תרומה ולא התירו מפה לאוכלי טהרות ומפרש רבינו דלאוכלי חולין גרידא התירו וכמ״ש בפרק [ששי] מהלכות ברכות:\",1,0],[8,378,8,10,\"הואיל והידים שניות וכו'. זה מבואר על השורש שקדם בסוף פרק שקודם זה שמשקה שנגע בשני הוא תחילה לעולם.\",1,0],[8,378,8,10,\"ומ\\\"ש אבל אין משקים אלו שנטמאו מחמת הידים מטמאים כלים. זה על שורש מ\\\"ש בפרק שקודם זה אין לך ולד טומאה שמטמא כלים אלא משקים טמאים בלבד והוא שיהיו אותם משקין טמאים מחמת אב מאבות הטומאה ושם נתבאר ולפ\\\"ז מה ששנינו בפ\\\"ב דטבול יום גבי קדירה שהיא מליאה משקים אם היו ידיו מסואבות הכל טמא לא אקדירה קאי אלא אמשקה בין דחולין בין דתרומה אבל קדירה טהורה שאין משקים שנטמאו מחמת ידים מטמאים את הכלים:\",2,0],[8,378,8,10,\"והראב\\\"ד כתב אבל אין משקין א\\\"א לא ידעתי מהו זה והוא סותר דבריו וכו'. מ\\\"ש והוא סותר דבריו כלומר שהוא כתב שהמשקים תחילה אלמא מטמאין ועכשיו אמר שאין מטמאין וא\\\"ת לא כתב שאין מטמאין אלא אכלים אף זו שיבוש וכו'. ותמהני על פה קדוש מה מקום היה לו לומר שסותר את דבריו שדבריו מבוארים שלא כתב שאין מטמאין אלא לכלים ומה שהקשה עליו מפרק אלו דברים כבר הקשה עליו כן בפרק שקודם זה ומה צורך לכפול הדברים וכבר כתבתי שם ליישב דברי רבינו:\",3,0],[8,378,8,10,\"וכן גזרו חכמים וכו'. בפ\\\"ב דטהרות וכרבי יהושע דאמר האוכל אוכל ראשון ואוכל שני שני וסתם לן תנא כוותיה בסוף זבים דמני לאוכל אוכל שני בהדי הנך דפוסלין את התרומה.\",4,0],[8,378,8,10,\"ומ\\\"ש ועל השותה משקים טמאים וכו'. בסוף זבים מני לה בהדי הנך שפוסלים את התרומה.\",5,0],[8,378,8,10,\"ומ\\\"ש עד שיטבול. לומר דאינו צריך הערב שמש כמ\\\"ש בפרק שאחר זה.\",6,0],[8,378,8,10,\"ומ\\\"ש ואם נגע באוכלים עשאם שלישי. פשוט הוא דכיון דתנן שהוא פוסל את התרומה הוה ליה אוכל תרומה שנגע בו שלישי וכדתנן בפ\\\"ב דטהרות השלישי שבתרומה פסול ואינו מטמא.\",7,0],[8,378,8,10,\"ומ\\\"ש ואם נגע במשקין וכו'. נתבאר בסוף פרק שקודם זה.\",8,0],[8,378,8,10,\"ומ\\\"ש אבל לא לטמא אוכלים. נתבאר בפרק שקודם זה:\",9,0],[8,378,8,10,\"וכתב הראב\\\"ד ולא אפילו לטמא אוכלים של חולין שלא גזרו אלא לתרומה עכ\\\"ל. ואני אומר שזה דבר פשוט ומבואר בדברי רבינו בסמוך:\",10,0],[8,378,8,10,\"ומפני מה גזרו וכו' עד במשקים שבפיו. פ\\\"ק דשבת (דף י\\\"ד):\",11,0],[8,378,8,11,\"אינו מתטמא וכו' עד מצטרפין לרביעית. משנה סוף פ\\\"ד דמעילה (דף י\\\"ז) ודעת רבינו דלא כר\\\"ת דפיסול גוויה לחוד היא גזירה קדמונית ליפסל מלאכול תרומה ושיעורה כחצי פרס וגזירת די\\\"ח דבר הוי למגע ושיעור כביצה ולאפוקי מסברא זו כתב רבינו אינו מתטמא עד שיאכל מאוכלים טמאים כחצי פרס וכן דעת רש\\\"י בפ\\\"ק דשבת וכן נראה דעת ריב\\\"א:\",1,0],[8,378,8,11,\"אכל מעט ושהה וכו' אם שתה מעט ושהה וכו'. בפרק ג' דכריתות (דף י\\\"ג):\",2,0],[8,378,8,11,\"אכל פחות מכשיעור וכו'. שם:\",3,0],[8,378,8,12,\"אשה שהיא ראשון לטומאה וכו'. גם זה שם:\",1,0],[8,378,8,13,\"המעוברת התירו לה לאכול וכו' פחות פחות מכשיעור וכו' אלא הרי היא טהורה. כך היא הנוסחא הנכונה בדברי רבינו גם זה שם התירו לעוברה לאכול פחות מכשיעור ואפילו טובא מפני הסכנה ומשמע לרבינו דהאי היתר הוא לענין שאינה צריכה טבילה:\",1,0],[8,378,9,1,\"הבא ראשו ורובו במים שאובים וכו'. בסוף זבים מני לה בהדי הנך דפוסלין את התרומה:\",1,0],[8,378,9,1,\"ומפני מה גזרו טומאה על אדם זה וכו'. בפ\\\"ק דשבת (דף י\\\"ד):\",2,0],[8,378,9,1,\"טבל א\\\"צ הערב שמש וכו'. בת\\\"כ פ' שמיני כל הנוגע בהם יטמא עד הערב ואין האוכל אוכלים טמאים ולא השותה משקים טמאים עד הערב וכ\\\"כ רש\\\"י בפ\\\"ק דשבת וכתב רבינו בהקדמתו לסדר טהרות בספרא אמרו כלים שנטמאו במשקים עולין מידי טומאתן בו ביום ובפי\\\"א ממסכת פרה שנינו כל הטעון ביאת מים מד\\\"ס וכו' לאחר ביאתו מותר בכולן:\",3,0],[8,378,9,2,\"מי שנפלו עליו וכו' עד הרי זה טהור. בפרק שלישי דמקואות:\",1,0],[8,378,9,2,\"נפלו על ראשו וכו' וכן אם בא ראשו כו'. תוספתא פרק שלישי דמקואות ויש חסרון לשון בספרי רבינו מט\\\"ס וכך היא הנוסחא הנכונה או שנפלו על רובו ולא על ראשו או שנפלו על ראשו בלבד מלמעלה:\",2,0],[8,378,9,3,\"הבא מראשו וכו'. בעיא בפרק שני דגיטין (דף ט\\\"ז) ופסקה לקולא דמידי דרבנן הוא:\",1,0],[8,378,9,4,\"היו שלשת הלוגין וכו'. תוספתא פרק שלישי דמקואות ופרק שביעי דפרה:\",1,0],[8,378,9,4,\"שלשת לוגין אלו וכו'. שם:\",2,0],[8,378,9,5,\"בראשונה היו מניחין וכו'. פ\\\"ק דשבת (דף י\\\"ד).\",1,0],[8,378,9,5,\"ומ\\\"ש ולא עוד אלא מי שהיו ידיו טהורות וכו' עד שהם דברי חכמה מטמאין את הידים. פ\\\"ג דידים וכת\\\"ק:\",2,0],[8,378,9,6,\"ומ\\\"ש כשהם מחוברים לספר וכו'. בפרק כל כתבי [שבת קט\\\"ז.]:\",1,0],[8,378,9,7,\"תרגום שבעזרא וכו' עד ובדיו. בפרק רביעי דידים:\",1,0],[8,378,9,8,\"הכותב הלל ושמע וכו' עד אינם מטמאים את הידים. שם בתוספתא פ\\\"ב:\",1,0],[8,378,9,11,\"ומה שכתב ספרי המינים וכו'. שם במשנה ובתוספתא.\",1,0],[8,378,9,11,\"ומה שכתב פרשת סוטה וכו'. ירושלמי פרק ב' דסוטה:\",2,0],[8,378,10,1,\"כל המתטמא וכו' טבל הרי הוא כשני לטומאה וכו'. בסוף זבים מני טבול יום בהדי הנך דפוסלים את התרומה ופ\\\"ק דפסחים (דף י\\\"ד) אמרו שמן שנפסל בטבול יום מאי הוי שלישי.\",1,0],[8,378,10,1,\"ומ\\\"ש הכתוב קרא לטבול יום טמא. בפ\\\"ק דשבת (דף י\\\"ד ע\\\"ב) טבול יום דאורייתא הוא דכתיב ובא השמש וטהר:\",2,0],[8,378,10,2,\"אחד טבול יום. בתוספתא דטהרות פ\\\"ק אחד טבול יום מטומאה חמורה ואחד טבול יום מטומאה קלה ואפילו טבול יום מן הזב ומן הזבה הרי הוא כטבול יום מן השרץ כך היא הגירסא הנכונה וכתבה רבינו בהקדמתו לסדר טהרות. ובפרק כשם (דף כ\\\"ט) אמרו מה לטבול יום שכן אב הטומאה ותיתי מטבול יום דשרץ:\",1,0],[8,378,10,2,\"כל הטעון הערב שמש בין אדם וכו' הרי הוא כשני לטומאה. כלומר ואם נגע בחולין טהור דאין שני עושה ג' בחולין כדאיתא בפרק כשם (דף כ\\\"ט ל') ואם נגע בתרומה פוסל ואינו מטמא דתנן בפרק שני דטבול יום קדירה שהיא מליאה משקים ונגע בה טבול יום וכו' המשקים פסולים והקדרה טהורה ואם היה משקה חולין הכל טהור ובתוספתא דטבול יום פ\\\"ב שנינו טבול יום אינו מטמא משקה חולין ופוסל אוכלי תרומה.\",2,0],[8,378,10,2,\"ועל מ\\\"ש רבינו בין מד\\\"ס. הוא תמיהא לי מדתנן בפרק י\\\"א דפרה דטעון ביאת מים מד\\\"ס לאחר ביאתו מותר בכולן אלמא דטבול יום של ד\\\"ס מותר אף בתרומה ובקדש מיד ואינו טעון הערב שמש ואפשר לומר דיש בטומאות של דברי סופרים שטעונין הערב שמש ויש שאינם טעונים וצ\\\"ע:\",3,0],[8,378,10,3,\"טבול יום פוסל וכו'. בריש פרק ב' דמעילה (דף ח') אהא דתנן נמלקה הוכשרה להפסל בטבול יום להפסל אין אבל לטמויי לא מתניתין מני רבנן היא דתניא טבול יום אבא שאול אומר תחילה לקדש רבי מאיר אומר מטמא את הקדש ופוסל את התרומה וחכ\\\"א כשם שהוא פוסל משקה תרומה ואוכלי תרומה כך הוא פוסל משקה קדש ואוכלי קדש ומפרש טעמא דחכמים משום דכיון דטבל קלשא טומאה פסול משוי טמא לא משוי כלומר ואינו כשאר שני שמטמא ג' בקדש ודבר ידוע שכשאומר פסול עניינו שלא יטמא זולתו וכמבואר בדברי רבינו ברפי\\\"א ובפי\\\"א דפרה תנן דטעון ביאת מים מן התורה לאחר ביאתו פוסל בקדש ובתרומה אליבא דחכמים ומותר בחולין ובפ\\\"ח דפרה תנן כל הפוסל את התרומה מטמא משקים להיות תחילה לטמא אחד ולפסול אחד חוץ מטבול יום:\",1,0],[8,378,10,4,\"כל המטמאים וכו'. בטבול יום רפ\\\"ב משקה טבול יום כמשקים שהוא נוגע בהם אלו ואלו אינם מטמאים ושאר כל הטמאים בין קלים בין חמורים משקים היוצאים מהם כמשקים שהוא נוגע בהם אלו ואלו תחלה חוץ מן המשקה שהוא אב הטומאה ובפרק כיסוי הדם (דף פ\\\"ח) ביארו ואמרו קלים שרץ חמורים זב וכלל רבינו בכלל טמאים קלים אוכל אוכלים טמאים שמאחר ששנינו כל הטמאים משמע דכללא כייל גם לזה ואע\\\"פ שאמרו קלים שרץ לאו דוקא שרץ אלא לדוגמא נקטיה.\",1,0],[8,378,10,4,\"ומ\\\"ש רבינו וכן טבול יום וכו' ואם נגע במשקה תרומה הרי הם שלישי וכו'. כלומר שמה ששנינו אינם מטמאים היינו לומר דכל חד כדיניה דחולין אינם מטמאים אלא טהורים ותרומה הויא שלישי וקדש רביעי ונקט אין מטמאין לישנא דכייל לכולהו ואיכא טהורים ואיכא פסולים:\",2,0],[8,378,10,4,\"ודע שמצאתי כתוב בספר מוגה ואם נגע במשקה קדש הוא או מחוסר כפורים הרי הן רביעי וטעמא מפני שרבינו סובר שמחוסר כפורים פוסל את הקדש בנגיעה כמו טבול יום כדמשמע בר\\\"פ טבול יום וכמ\\\"ש רבינו בהקדמתו לסדר טהרות:\",3,0],[8,378,10,5,\"ועתה יתבאר לך שאין שלישי שבתרומה וכו'. בפ\\\"ב דטהרות הראשון והשני שבתרומה טמאים ומטמאים השלישי פסול ואינו מטמא הרביעי נאכל בנזיד הקדש הראשון והשני ושלישי שבקדש טמאים ומטמאים הרביעי פסול ואינו מטמא החמישי נאכל בנזיד הקדש ונתבאר בפ\\\"ק דפסחים (דף ט\\\"ז) ובפ\\\"ב דחולין (דף ל\\\"ד ל\\\"ה):\",1,0],[8,378,10,5,\"לפיכך קדירה וכו' עד וספק הידים טהור. פרק שני דטבול יום והדברים מבוארים בטעמא דטבול יום הוא כשני ואין שני עושה שלישי בחולין אבל פוסל הוא את התרומה אבל הקדרה לא נטמאה דמשקים שנגע בהם טבול יום לא הוו תחילה ואינם מטמאין כלים כמו שנתבאר בפ\\\"ז שהוא דעת רבינו:\",2,0],[8,378,10,6,\"אחד טהור וכו'. פשוט הוא:\",1,0],[8,378,10,6,\"ומאחר שמשקה וכו'. משנה בסוף נדה (דף ע\\\"א ע\\\"ב):\",2,0],[8,378,10,7,\"מכל אלו הדברים וכו'. שהאדם יהיה אב הטומאה ויהיה ראשון וכו'. נתבאר בפ\\\"ה מהל' טומאת מת ובהל' מטמאי משכב:\",1,0],[8,378,10,8,\"כבר ביארנו שכלי חרס לא יהיה אב טומאה לעולם. פ\\\"ה מהלכות טומאת מת:\",1,0],[8,378,10,9,\"האוכלים לא יהיו אב טומאה לעולם וכו'. נתבאר בפ\\\"ז מהלכות אלו:\",1,0],[8,378,10,10,\"ואין אתה מוצא משקין שניות לעולם וכו'. חזר לכתוב כן לאפוקי ממ\\\"ש בקצת נוסחאות בסוף פ\\\"ק דפסחים (דף י\\\"ז ע\\\"ב) הכא בבשר שנטמא במשקים שניות שנטמאו מחמת שרץ וסובר רבינו שהוא טעות סופר כמ\\\"ש בהקדמתו לסדר טהרות:\",1,0],[8,378,11,1,\"כל מקום שנאמר באוכלים פסול וכו' הראשון שבחולין וכו'. משנה פרק שני דטהרות ואיתא בפ\\\"ב דחולין (דף ל\\\"ה) ופ\\\"ק דפסחים (דף ט\\\"ז):\",1,0],[8,378,11,2,\"ואין שני עושה ג' בחולין. בפ\\\"ב דטהרות ופי\\\"א דפרה ופ\\\"ק דנדה (דף ז') ובפרק כשם (דף ל') אמרו דכ\\\"ע אין שני עושה שלישי בחולין ובפ\\\"ב דחולין (דף ל\\\"ג ל\\\"ד) כולה סוגיא הכי רהטא וכן בחגיגה (דף כ\\\"ד) ובפסחים שם:\",1,0],[8,378,11,2,\"ומנין לאוכל שני שהוא פסול בחולין וכו'. משנה פרק כשם (כ\\\"ז:) וכריב\\\"ז.\",2,0],[8,378,11,2,\"ומ״ש וכן שרץ שנפל וכו'. פ״ח דכלים ואיתא בפ״ק דפסחים (דף כ') ופרק תולין (שבת קל״ח:):\",3,0],[8,378,11,3,\"הראשון והשני שבתרומה טמאים ומטמאין וכו'. בפ\\\"ב דטהרות:\",1,0],[8,378,11,3,\"מנין לאוכל שלישי וכו'. פרק הערל עלה ע\\\"ד:\",2,0],[8,378,11,4,\"הראשון והשני וכו'. פ\\\"ב דטהרות שם:\",1,0],[8,378,11,4,\"ומנין לשלישי בקדש וכו' עד אינו דין שיעשה רביעי בקדש. פרק כשם (דף כ\\\"ט ע\\\"ב) ופ\\\"ק דפסחים (דף י\\\"ח ע\\\"ב) ופרק חומר בקדש (דף כ\\\"ד):\",2,0],[8,378,11,5,\"בשר תאוה וכו'. בתוספתא דנדה פ\\\"ט.\",1,0],[8,378,11,5,\"ומ\\\"ש רבינו מטמא את הקדש, מאחר שטהור לתרומה לא היה לו לטמא את הקדש ואפשר דלשון מטמא דנקט לאו דוקא אלא היינו לומר שפוסל את הקדש ולישנא דתוספתא נקט ולאו דוקא זה דעת הר\\\"י קורקוס ז\\\"ל. ואין נ\\\"ל שהרי שנו בתוספתא חזרו וגזרו כנבילה עצמה מטמא במשא נראה שגזרו והחמירו עליו בקדש ביותר ואין לתרומה שייכות בזה יותר מהחולין:\",2,0],[8,378,11,6,\"חיבורי אוכלים וכו'. בס״פ טבול יום בעא רבי זירא מרבי אמי בר חייא וכו' הא דתנן חיבורי אוכלים על ידי משקים חיבור לטומאה קלה ואינו חיבור לטומאה חמורה מונין בו ראשון ושני או אין מונין בו ראשון ושני א״ל כל היכא דמטמא אדם מונין בו ראשון ושני אין מטמא אדם אין מונין בו ראשון ושני ופירש רש״י חיבורי אוכלין וכו' ומשמע דפשט ליה דכיון דאוכלים אינם מטמאים אדם אין מונים בו ראשון ושני. וזהו שכתב הראב״ד והדבר ספק א״א אינו כן אלא כבר פשטוה בזבחים שאין מונים בו ראשון ושני עכ״ל. וטעם רבינו נראה שהוא מדגרסינן בפרק הקומץ רבה (מנחות דף כ״ד) בעי רבי ירמיה צירוף כלי וחבור מים וכו' וכיון דהא דמיא להך וסלקא בתיקו ה״ה לאידך ואע״ג דרבי אמי בר חייא פשטה מ״מ מידי ספיקא לא נפקא. ונראה מדברי רבינו דהכי קא מיבעיא ליה אי חשיבי שני האוכלים שחיברם המשקה כגוף א' ואם נגע שרץ באחד מהם ה״ל תרווייהו ראשון והנוגע באוכל שבצד האחר הוי שני או דילמא אע״פ שהמשקה מחברם מ״מ היינו להיות אוכל שבצד זה טמא אע״פ שלא נגע בו השרץ ומכל מקום אינו נחשב כאילו נגע בו השרץ ודיינו שנחשוב אותו כאילו נגע באוכל שנגע בו השרץ דהוה ליה שני ואוכל הנוגע בו שלישי:\",1,0],[8,378,11,7,\"השני שבחולין וכו'. בפ\\\"ב דטהרות שני שבחולין מטמא משקה חולין ופוסל לאוכלי תרומה.\",1,0],[8,378,11,7,\"ומ\\\"ש אם נגע במשקה חולין טמאין. איני יודע למה לא כתב שנעשו תחילה כמ\\\"ש בבא שאחר זו:\",2,0],[8,378,11,8,\"השלישי שבתרומה וכו'. שם השלישי שבתרומה מטמא משקה קדש ופוסל לאוכלי קדש.\",1,0],[8,378,11,8,\"ומ\\\"ש אבל אם נגע שלישי שבתרומה במשקה תרומה הרי הוא טהור. הכי משמע מדלא קתני ופוסל אוכלי קדש ומשקה תרומה.\",2,0],[8,378,11,8,\"ומ\\\"ש וכן רביעי שבקדש אם נגע במשקה קדש ה\\\"ז טהור. שם הראשון והשני והשלישי שבקדש טמאים ומטמאים הרביעי פסול ואינו מטמא. וכתב הראב\\\"ד אם נגע במשקה קדש ה\\\"ז טהור א\\\"א זה שיבוש שהרי אמרו השלישי שבכולן וכו'. והיא משנה בפ\\\"ב דטהרות ופשטה מוכיח כדברי הראב\\\"ד ואפשר לומר לדעת רבינו דמאי מטמא משקה קדש דקאמר פוסל משקה קדש וכעין מה שפי' רבינו שמשון בפרק הנזכר גבי הראשון שבחולין טמא ומטמא השני פסול ואינו מטמא הראשון והשני שבתרומה טמאים ומטמאים השלישי פסול ואינו מטמא הראשון והשני והשלישי שבקדש טמאים ומטמאים הרביעי פסול ואינו מטמא דטמא ומטמא דקתני בכולהו היינו טמא ופוסל ומטמא לאו דוקא נקט וכן נמי הא דקתני בכולהו פסול ולא מטמא היינו פוסל ולא פוסל. ומ\\\"ש הראב\\\"ד ההוא משקה נמי פוסל משקה אחרינא לא דק דמשקה הנוגע במשקה אחר עושהו תחילה כמו שנתבאר בפ\\\"י:\",3,0],[8,378,11,9,\"חולין שנעשו וכו'. בפרק ב' דטהרות ר\\\"א אומר האוכל אוכל ראשון וכו' רבי יהושע אומר האוכל אוכל ראשון ואוכל שני שני שלישי שני לקדש ולא שני לתרומה בחולין שנעשו לטהרת תרומה ומייתי לה בפרק ב' דחולין (דף ל\\\"ג ע\\\"ב) ופירש רש\\\"י בחולין שנעשו על טהרת תרומה כלומר האי אוכל ראשון שני ושלישי בחולין מיירי וכו' ובאי זה אוכל חולין אתה מוצא שלישי הא שני לא עביד שלישי בחולין אתה מוצאו בחולין שנעשו על טהרת תרומה.\",1,0],[8,378,11,9,\"ומה שכתב ואם נגע בקדש אינו עושהו רביעי ואפילו משקה קדש אינו פוסל. ומה שכתב וחולין שנעשו על טהרת הקדש וכו'. כתב הראב״ד א״א זה האיש תפס הדרך המסוכסכת בסירים וכו'. ביאור הדברים דבפרק ב' דחולין (דף ל״ג) תנן השוחט בהמה חיה ועוף ולא יצא מהם דם כשרים ונאכלים בידים מסואבות לפי שלא הוכשרו בדם. ובגמרא טעמא דלא יצא מהם דם הא יצא מהם דם אין נאכלים בידים מסואבות אמאי ידים שניות הם ואין שני עושה שלישי בחולין וממאי דבחולין עסקינן דקתני חיה (דאילו קדשים חיה בקדשים מי איכא וכו') אמר רבי אלעזר א״ר הושעיא הכא בחולין שנעשו על טהרת הקדש עסקינן ודלא כרבי יהושע וכו' דאמר שלישי ושני לקדש ולא שני לתרומה בחולין שנעשו על טהרת תרומה על טהרת תרומה אין על טהרת הקדש לא קסבר חולין שנעשו על טהרת הקדש לית בהו שלישי ופי' רש״י על טהרת הקדש כגון אדם הרגיל לאכול קדשים ורוצה להיות רגיל תדיר בשמירת טהרתן ושומר אף חולין מכל טומאות הפוסלות בקדש וכו'. ודלא כרבי יהושע דאמר חולין שנעשו על טהרת הקדש לא פסיל בהו שלישי דבטלה דעתו ואין יכול להתפיס על חולין טהרת הקדש אמר עולא (דף ל״ד) חברייא אמרין בחולין שנעשו על טהרת הקדש ודלא כרבי יהושע ואנא אמינא רבי יהושע היא ולא מיבעיא קאמר ל״מ חולין שנעשו על טהרת הקדש דחמירי דאית בהו ג' אלא אפילו חולין שנעשו על טהרת תרומה נמי אית בהו שלישי מאן חברייא רבה בר בר חנא היא דאמר רבה בר בר חנא אמר ר״י מאי אהדרו ר״א ורבי יהושע אהדדי וכו' א״ל אף אני לא אמרתי אלא בתרומה וכו' אמר רבי זירא אמר רבי אסי אמר רבי יוחנן אמר רבי ינאי האוכל שלישי של חולין שנעשו על טהרת הקדש נעשה גופו שני לקדש איתיביה רבי זירא לרבי אסי שלישי ושני לקדש ואין שני לתרומה בחולין שנעשו על טהרת תרומה על טהרת תרומה אין על טהרת הקדש לא א״ל לא מיבעיא קאמר והא אף אני לא אמרתי [אלא בתרומה] קאמר אמוראי נינהו ואליבא דר״י. (דף ל״ה) יתיב רב יצחק בר שמואל בר מרתא קמיה דר״נ ויתיב וקאמר האוכל שלישי של חולין שנעשו על טהרת הקדש טהור לאכול בקדש שאין לך דבר שעושה רביעי אלא קדש מקודש בלבד ופירש רש״י קודש מקודש קדש גמור שקדש גופו כגון בשר קרבן וכו' אבל שלישי של קדש המקודש בקדושת הפה לא מתיב רמי בר חמא וכו' א״ל הנח לתרומה וכו' אמר רבא מדרסות קאמרת וכו' מתיב רב הונא בר נתן השני שבחולין מטמא משקה חולין ופוסל אוכלי תרומה והשלישי מטמא משקה קודש ופוסל אוכלי קדש בחולין שנעשו על טהרת הקדש תנאי היא דתניא חולין שנעשו על טהרת הקדש הרי הם כחולין ר״א ברבי צדוק אומר הרי הם כתרומה לטמא שנים ולפסול אחד ובריש פרק חומר בקדש (חגיגה דף כ' ע״ב) מונה מעלות בקדש מבתרומה ואמר רבי אילא אמר רבי חנינא בר פפא וכו' ראשונות בין לקדש בין לחולין שנעשו על טהרת הקדש אחרונות לקדש אבל לא לחולין שנעשו על טהרת הקדש וגרסינן תו התם (דף כ״ב) רבא סבר לה כי הא דאמר ר״נ אמר רבה בר אבוה וכו' שש ראשונות בין לקדש בין לחולין שנעשו על טהרת הקדש אחרונות לקדש אבל לא לחולין שנעשו על טהרת הקדש ואחת מהאחרונות היא הרביעי בקדש פסול ובפרק ב' דחגיגה (דף י״ט ע״ב) על מתניתין דהתם אמר רב מרי שמע מינה חולין שנעשו על טהרת הקדש כקדש דמו ובפירקא קמא דנדה (דף ו' ע״ב) גבי מעת לעת שבנדה מטמא בין לקדש בין לתרומה דייק מדלא קתני לה גבי מעלות ופריך ר״נ והא תניא לקדש אבל לא לתרומה ומשני לה רבי שמואל בר יצחק [דה״ק] לחולין שנעשו על טהרת הקדש ולא לחולין שנעשו על טהרת תרומה וטעם רבינו משום דהא דקתני חולין שנעשו ע״ג הקדש הרי הם כחולין וכו' משנה בספ״ב דטהרות וכיון דסתם לן תנא דלאו כקדש דמו הכי נקטינן ואע״ג דסתם לן תנא בפרק השוחט (חולין דף ל״ג) דלא כרבי יהושע אין משם ראיה דכקדש דמו משום דהא איכא התם אוקימתא אחריתא שאינה עניין לזה ותו דהא כמה אמוראי דסברי דלא כקדש דמו ורבא דבתרא הוא סבר הכי נקטינן כוותיהו והכי אמר סתם גמרא בשלהי נדה (דף ע״א ע״ב) אמתניתין דבראשונה היו אומרים היושבת על דם טוהר מערה מים לפסח חזרו לומר הרי היא כמגע טמא לקדשים לקדשים אין לחולין לא אלמא חולין שנעשו על טהרת הקדש לאו כקדש הם וכתב רבינו בפ״ב דטהרות כ״מ שתמצא במשנה זכרון שלישי בחולין שנעשו על טהרת הקדש הוא למשנה ראשונה וכיוצא בזה כתב בפ״ב דחגיגה ודבר פשוט דהלכה כמשנה אחרונה:\",2,0],[8,378,11,10,\"האוכל וכו'. בפרק ב' דטהרות הראשון והשני והשלישי שבקדש טמאים ומטמאים הרביעי פסול ואינו מטמא החמישי נאכל בנזיד הקדש ופירושה נלמד ממה שיתבאר בסמוך שאמרו במתניתין דהראשון שבחולין טמא ומטמא וכו' והשלישי נאכל בנזיד הדמע:\",1,0],[8,378,11,10,\"וכתב הראב\\\"ד אלא בחמישי שהוא טהור א\\\"א אומר אני החמישי וכו':\",2,0],[8,378,11,10,\"ביאור הדברים דבפ\\\"ב דטהרות שם תנן הראשון שבחולין טמא ומטמא השני פסול ולא מטמא השלישי נאכל בנזיד הדמע הראשון והשני שבתרומה טמאים ומטמאים השלישי פסול ולא מטמא הרביעי נאכל בנזיד הקדש הראשון והשני והשלישי שבקדש טמאים ומטמאים הרביעי פסול ולא מטמא החמישי נאכל בנזיד הקדש עכ\\\"ל ופירוש הראב\\\"ד דחוק מאד ודברי רבינו כפשטא דמתניתין ומאי דקתני הרביעי שבתרומה והחמישי שבקדש ה\\\"ק שלישי שבתרומה והרביעי שבקדש אסורים לאכול קדש אפילו אין הקדש בעין אלא מעורב בנזיד ואינו מותר לאוכלו אלא הרביעי שבתרומה והחמישי שבקדש שהם טהורים גמורים שהרי אין רביעי בתרומה ולא חמישי בקדש:\",3,0],[8,378,11,11,\"האוכל שלישי שבתרומה עצמה וכו'. בפרק שני דחולין (דף ל\\\"ד ע\\\"ב) אמר עולא האוכל שלישי של חולין שנעשו על טהרת תרומה נפסל גופו מלאכול בתרומה מאי קמ\\\"ל תנינא שלישי שני לקדש ואין שני לתרומה בחולין שנעשו על טהרת תרומה שני הוא דלא הוי הא שלישי הוי אי מההיא ה\\\"א וכו' קא משמע לן איתיביה רב המנונא לעולא הראשון שבחולין טמא ומטמא והשני פסול ולא מטמא השלישי נאכל בנזיד הדמע ואי אמרת נפסל גופו מלאכול בתרומה ספינן ליה מידי דפסיל ליה לגופיה א\\\"ל הנח לנזיד הדמע דליכא כזית בכדי אכילת פרס אר\\\"י אמר רבי האוכל שלישי של תרומה עצמה אסור לאכול ומותר ליגע ואיצטריך דר\\\"י ופירש רש\\\"י בנזיד הדמע בתבשיל שתרומה מעורבת בו כגון שלישי זה עם מקפה של חולין הוא מותר לתת לתוכו תבלין של תרומה ושום ושמן דתרומה ולאוכלו וכו'. דליכא כזית בכדי אכילת פרס דבנזיד הדמע תבלי תרומה מועטין. והא דר\\\"י אמר רבי איתא בפרק טבול יום וקאמר עלה באכילה עבוד רבנן מעלה בנגיעה לא עבוד רבנן מעלה:\",1,0],[8,378,11,12,\"האוכל שלישי שבתרומה וכו'. שם יתיב רב יצחק בר שמואל בר מרתא קמיה דר\\\"נ ויתיב וקאמר האוכל שלישי של חולין שנעשו על טהרת הקדש טהור לאכול בקדש שאין לך דבר שעושה רביעי בקדש אלא קדש מקודש בלבד מתיב רמי בר חמא שלישי שני לקדש ואין שני לתרומה בחולין שנעשו על טהרת תרומה אמאי לאו קדש מקודש הוא א\\\"ל הנח לתרומה שטהרתה טומאה היא אצל הקדש וכו' דתנן בגדי אוכלי תרומה מדרס לקדש והדר מתיב עליה ומסיק תנאי היא דתניא חולין שנעשו על טהרת הקדש הרי הם כחולין ר\\\"א ברבי צדוק אומר הרי הם כתרומה לטמא שנים ולפסול אחד ומשמע דרבי יצחק בר שמואל בר מרתא סבר כר\\\"א ברבי צדוק וכן פירש\\\"י ומאחר שרבינו פסק לעיל בסמוך כת\\\"ק דפליג אר\\\"א ברבי צדוק קשה היאך פסק כאן כרבי יצחק וצ\\\"ל שרבינו מפרש כפירוש ראשון שכתב הרשב\\\"א דרבי יצחק כתנא קמא דרבי אליעזר ברבי צדוק סבר דאמר חולין שנעשו על גבי הקדש הרי הם כחולין ולכך אומר האוכל שלישי אין גופו נפסל דטהור גמור הוא ואפילו הוא עצמו אינו פוסל את הקדש בנגיעתו:\",1,0],[8,378,11,13,\"כל קדש האמור וכו' אבל חלות תודה וכו' עד הרי הם כחולין. תוספתא פ\\\"ק דטהרות אלא שהיא כתובה בשיבוש:\",1,0],[8,378,11,15,\"ומ\\\"ש ועיסה הטבולה לחלה הרי הן כחולין. פרק כשם (דף ל') בתירוצא בתרא ובספרי רבינו כתוב החלה והתרומה ותשלומי ד' וה' וט\\\"ס הוא וצריך למחוק ד' וה' ולכתוב במקומה תרומה:\",1,0],[8,378,11,16,\"כל דבר שודאו מטמא וכו'. פ\\\"ק דנדה עלה ז':\",1,0],[8,378,12,1,\"אחת עשרה מעלות וכו'. משנה וגמרא בפרק חומר בקדש (דף כ\\\"ב) וכר\\\"נ דאמר י\\\"א שנו דרבא סבר כוותיה:\",1,0],[8,378,12,3,\"ומ\\\"ש וטמאה במדרס שנשא עמה. אינו מדוקדק דהא בגמ' (דף כ\\\"ב ע\\\"ב) הכי אמרי' קדש מ\\\"ט לא משום מעשה שהיה דאמר רב יהודה אמר שמואל מעשה באחד שהיה מעביר חבית של יין [קודש] ממקום למקום ונפסקה רצועה של סנדלו ונטלה והניחה ע\\\"פ החבית ונפלה לאויר החבית ונטמאת באותה שעה אמרו הנושא את המדרס נושא את התרומה אבל לא את הקדש הרי שנטמאה במדרס שנפל לאויר חבית לא במדרס שנשא עמה. ועוד יש לדקדק עליו דאמרינן בגמרא א\\\"ה תרומה נמי הא מני רבי חנניא בן עקביא היא דאמר לא אסרו אלא בירדן ובספינה וכמעשה שהיה מאי היא דתניא לא ישא אדם מי חטאת ואפר חטאת ויעבירם בנהר ובספינה וכו' ולא ישיטם על פני המים וכו' רבי חנניא בן עקביא אומר לא אסרו אלא בירדן ובספינה וכמעשה שהיה ורבינו פסק כאן כרבי חנניא בן עקביא דלא אסרו אלא כמעשה שהיה בקדש אבל לא בתרומה ובפרק עשירי מהלכות פרה פסק כת\\\"ק וי\\\"ל שטעמו משום דהכא סתם לן תנא כרבי חנניא בן עקביא והתם סתם לן בפ\\\"ט דפרה כת\\\"ק ויש לנו לומר ראה רבינו דבריו של רבי חנניא בן עקביא בנושא את המדרס ודבריו של ת\\\"ק במעביר בנהר וכדאמרינן בפרה.\",1,0],[8,378,12,3,\"ומ\\\"ש ואם עבר ונשא וכו' טהור. שם פלוגתא דאמוראי ופסק כמאן דמיקל דמילתא דרבנן היא:\",2,0],[8,378,12,6,\"ומ\\\"ש ומפני מה הצריכום טבילה לקדש וכו'. שם בגמ' (דף כ\\\"ג) דגמרינהו חבר ומשום צנורא דע\\\"ה דנפול אימת אילימא מקמי דליגמריה הא לאו מנא הוא אלא בתר דגמריה מיזהר זהיר בהו לעולם מקמי דגמריה ודילמא בעידנא דגמריה עדיין לחה היא:\",1,0],[8,378,12,7,\"ומ\\\"ש וכל המעלות של דבריהם הם וכו'. שם (ע\\\"ב) הכלי מצרף מה שבתוכו וכו'. מנא ה\\\"מ אמר רבי חנין דאמר קרא כף אחת עשרה זהב מלאה קטרת הכתוב עשאו לכל מה שבכף אחת כלומר והויא דאורייתא וכו' ופליגא [דרבי חנין] אדרבי חייא בר אבא אמר ר\\\"י דאמר וכו' מעדותו של ר\\\"ע נשנית משנה זו כלומר והויא מדרבנן. ופסק רבינו כר\\\"י משום דהוא מריה דגמרא טפי מרבי חנין ומ\\\"מ קרא דאייתי רבי חנין כתבו רבינו לרמז בעלמא.\",1,0],[8,378,12,7,\"ומ\\\"ש אפילו שאין לו תוך מצרף מה שעליו וכו'. שם:\",2,0],[8,378,12,8,\"ומה שכתב היו שני הצבורים בתוך הכלי וכו'. בפרק הקומץ רבה עלה כ\\\"ד הושיט אחד לביניהם מהו צריך לכלי הכלי מצרפו אין צריך לכלי אין הכלי מצרפו ופירש רש\\\"י הושיט חצי עשרון אחד לבין הנך חצאי עשרון מהו אם נגע טבול יום בזה מהו שיטמא אותם שנים. אין צריך לכלי כגון האי חצי עשרון שלישי דאין צריך לכלי דהא אינו מצטרף עם אלו למנחה אחת אין הכלי מצרפו וטהורים הראשונים ורבינו מפרש בענין אחר כמבואר בדבריו:\",1,0],[8,378,12,8,\"וכתב הראב\\\"ד על דברי רבינו לא נטמא אלא זה שנגעה א\\\"א זה שיבוש שאותו אמצעי שנתן ביניהם וכו'. ותמהני על פה קדוש למה דחה פירוש רבינו בשתי ידים לומר עליו שהוא שיבוש שהרי יש ליתן בו טוב טעם ודעת לומר שאין הכלי מצרף אלא כשאין ביניהם דבר שאין צריך לכלי אבל אי קשיא על דברי רבינו הא קשיא למה לא יצטרף העשרון האמצעי עם אותו שנטמא שהרי אין דבר מפסיק ביניהם. לכך נ\\\"ל שדעת רבינו שאילו היה המפסיק ביניהם חצי עשרון אין ה\\\"נ שהיה מצטרף אבל הכא במאי עסקינן בשדבר אחר שאינו סולת מפסיק ביניהם וזהו שכתב רבינו ודבר אחר ביניהם והשתא דברי רבינו מכוונים בלי שיבוש ואדרבה על פירוש הראב\\\"ד יקשה למה לא יצטרף האמצעי עם הטמא שאין דבר מפסיק וישאר השלישי טהור וזה היה יותר ראוי מלהצטרף שנים שדבר מפסיק ביניהם וכן יקשה לפירוש רש\\\"י ואף על פי שיש לדחוק ולומר דכיון שזה העשרון היה שלם מתחילה יותר ראויים להצטרף חלקיו זה עם זה מלהצטרף עם חלק אחר פירוש רבינו יותר נוח ואף על פי שבירושלמי פרק חומר בקדש נראה כפירוש הראב\\\"ד אין זה כדאי לדחות פירוש רבינו שהוא נוח:\",2,0],[8,378,12,9,\"היו שני צבורים בכלי וכו'. שם בעי רבי ירמיה צירוף כלי וחבור מים וכו' עד תיקו ופסק רבינו כבעיא ראשונה דטעמא מפני שאמרו בה את\\\"ל חשיב לה כנפשט:\",1,0],[8,378,12,10,\"אוכל קדש שנטמא וכו'. נלמד ממה שיבא בסמוך.\",1,0],[8,378,12,10,\"ומ\\\"ש בא טבול יום ונגע וכו'. שם בעיא דלא איפשיטא:\",2,0],[8,378,12,11,\"הרביעי בקדש. משנה פ' חומר בקדש (דף כ' ע\\\"ב):\",1,0],[8,378,12,11,\"וכן שלישי בתרומה אם נגע וכו' כמו שביארנו. בפי\\\"א.\",2,0],[8,378,12,11,\"ומ\\\"ש (וכן) והשלישי שבתרומה או שבקדש וכו'. משנה פרק חומר בקדש הרביעי בקדש פסול והשלישי בתרומה:\",3,0],[8,378,12,12,\"מי שנטמאת ידו אחת וכו'. משנה פרק חומר בקדש בתרומה אם נטמאת אחת מידיו חבירתה טהורה ובקדש מטביל שתיהן שהיד מטמאה את חבירתה בקדש אבל לא בתרומה.\",1,0],[8,378,12,12,\"ומה שכתב או ביד חבירו. שם (דף כ\\\"ד ע\\\"ב) כרבי יוחנן ואף ריש לקיש הדר ביה.\",2,0],[8,378,12,12,\"ומה שכתב פסל את השנייה. שם רבי יוחנן וריש לקיש אמרו אחד ידו ואחד יד חבירו ולפסול אבל לא לטמא תנאי היא וכו' דתניא יד נגובה מטמאה את חבירתה לטמא בקדש אבל לא לתרומה דברי רבי רבי יוסי ברבי יהודה אומר אותה יד לפסול אבל לא לטמא ופסק רבינו כרבי יוסי ברבי יהודה משום דרבי יוחנן וריש לקיש הוו סברי כוותיה.\",3,0],[8,378,12,12,\"ומ\\\"ש ואם היתה ידו בלולה במשקה וכו'. כן כתב רבינו שם בפירוש המשנה:\",4,0],[8,378,12,12,\"וכתב הראב\\\"ד ואם היתה ידו בלולה במשקה א\\\"א זה אינו מן הסוגיא וכו'. ואין זה השגה דכיון דכל הני מילי מעלות דרבנן אמרינן דכיון דעל ידי משקה מטמאה את היד טומאה גמורה לכל דבר גזרו בקדש למעלתה גם בלתי נגיעה.\",5,0],[8,378,12,12,\"ומ\\\"ש רבינו ואפילו נגע בה כשהיא נגובה. כלומר אע\\\"פ שנגע בה לא נטמאת מאחר שהיא נגובה דאילו היתה לחה פשיטא שנטמאת על ידי המשקה:\",6,0],[8,378,12,13,\"אוכלים נגובים וכו'. משנה פרק חומר בקדש (דף כ':) [אוכלים] אוכלין נגובים בידים מסואבות בתרומה אבל לא בקדש ובגמרא וכי יש נגובה לקדש והלא חיבת הקדש מכשרתן לא צריכה כגון שתחב לו חבירו לתוך פיו או שתחב הוא לעצמו בכוש ובכרכר וביקש לאכול צנון או בצל חולין עמהם לקדש גזרו בהו רבנן לתרומה לא גזרו בהו רבנן וכתב רבינו בפירוש המשנה העיקר אצלנו חיבת הקדש מכשרתו ואין צריך הכשר וכיון שזהו העיקר האוכל אוכלין נגובים בידיו והם טמאות שיטמאו ואין אנו צריכין בזה לדבר אבל דיבר בכאן אם לא לקחן בידים אלא במלקחים ודומיהן וזה גזירה שמא יאכל אחר כך שום דבר של משקה בידיו ויטמא את הקדש שבפיו עכ\\\"ל. ולפי זה הא דקתני וביקש לאכול צנון או בצל היינו לומר שדרך צנון או בצל להדיחם במים וכשאוכלם נגעו ידיו בהם ונטמאו ומטמאים את הקדש שבפיו ורש\\\"י פירש בענין אחר ואיכא למידק מאי קשיא ליה לרבי חנינא בן אנטיגנוס והלא חיבת הקדש מכשרתן אימא דהיא גופה קמשמע לן דחיבת הקדש מכשרתן ואפשר דחיבת הקדש מכשרתן דאורייתא היא אי נמי דרבנן אינה מאחת עשרה מעלות השנויות שם שגזרו בקדש. ודע שיש בספר רבינו טעות סופר וכך היא הנוסחא הנכונה ואין צריך לומר שאם נגעה טומאה באוכלים של קדש שלא הוכשרו שנטמאו מפני שחיבת הקדש מכשרתן:\",1,0],[8,378,12,14,\"ומה שכתב במה דברים אמורים לפסול האוכל עצמו וכו' אבל למנות בו ראשון ושני. בפרק ב' דחולין (דף ל\\\"ו) גבי בעיא דצריד של מנחות בעיא דלא איפשיטא ויש לתמוה על רבינו שהוא עצמו כתב בפרק שמיני מהלכות אלו בפשיטות שמונים בו ראשון ושני ונ\\\"ל שטעמו שם כמ\\\"ש שם דאיתא בפרק המנחות והנסכים דלא מיבעיא אלא מדאורייתא דאילו מדרבנן פשיטא ליה דמונים מיהו ה\\\"מ כשנטמא הצריד טומאה דאורייתא וכדפירש רש\\\"י שם דאז חיבת הקדש מכשרתן ואף על פי שלא הוכשר כמי שהוכשר דמי ומדאורייתא מספקא לן אי מונין בו ראשון ושני ומדרבנן פשיטא לן דמונים משום דטומאה דאורייתא היא אבל בטומאת ידים שהיא דרבנן איכא למימר שלא החמירו בו רבנן למנות בו ראשון ושני אפילו מדרבנן ובפ\\\"ח מיירי כשנטמא הצריד טומאה דאורייתא ולפיכך פסק דמונים בו ראשון ושני מדרבנן מיהא אבל הכא דמיירי בטומאת ידים שהיא דרבנן כתב שהדבר ספק כמ\\\"ש בד\\\"א לפסול האוכל עצמו וכו' אבל למנות בו וכו' לאו אאין צריך לומר שאם נגעה טומאה וכו' דסמיך ליה קאי אלא ארישא דמילתא שכתב גבי ידים מסואבות חיבת הקדש מכשרתן:\",1,0],[8,378,12,15,\"האונן אחר שתם זמן אנינתו וכו'. משנה בפרק חומר בקדש (דף כ\\\"א) האונן ומחוסר כפורים צריכין טבילה לקדש אבל לא לתרומה.\",1,0],[8,378,12,15,\"ומ\\\"ש ומפני מה הצריכום טבילה וכו'. שם בגמרא (דף כ\\\"ד ע\\\"ב).\",2,0],[8,378,12,15,\"ומ\\\"ש ולא עשו מעלה זו אלא לאכילה וכו'. בר\\\"פ טבול יום ואע\\\"ג דלא איתמר התם אלא גבי אונן משמע לרבינו דה\\\"ה למחוסר כפורים כיון דבהדי הדדי מיתנו:\",3,0],[8,378,12,16,\"שש מעלות הראשונות וכו'. בפרק חומר בקדש (חגיגה דף כ\\\"א ע\\\"ב):\",1,0],[8,378,12,16,\"ומ\\\"ש לפיכך חולין שנעשו על טהרת הקדש וכו' כמו שביארנו. בפרק י\\\"א. ומה שכתב הראב\\\"ד גם אני ביארתי שאלו דברי יחיד הן ואין הלכה ואילו כל הסוגיות הולכות על דרך שהם בקדש עכ\\\"ל כבר כתבתי שם טעם רבינו:\",2,0],[8,378,13,1,\"חמש מעלות עשו חכמים בבגדים וכו'. משנה פ\\\"ב דחגיגה (דף י\\\"ח ע\\\"ב) וכרב אחא (דף י\\\"ט ע\\\"ב) דמוקי למתניתין כולה כרבנן ותני בסיפא ה' מעלות.\",1,0],[8,378,13,1,\"ומ\\\"ש ועמי הארץ עצמם כזבין לטהרות כמו שביארנו. בפ\\\"י דמטמאי משכב ומושב.\",2,0],[8,378,13,1,\"ומ\\\"ש ובגדי אוכלי חוליהן בטהרה וכו'. ג\\\"ז משנה בפ\\\"ב דחגיגה.\",3,0],[8,378,13,1,\"ומ\\\"ש אבל אוכלי חוליהן בטהרה וכו'. ירושלמי שם.\",4,0],[8,378,13,1,\"ומ\\\"ש ובגדי אוכלי מעשר שני וכו' עד מדרס לקדש. משנה בפרק ב' דחגיגה.\",5,0],[8,378,13,1,\"ומ\\\"ש אבל אוכלי תרומה עצמן וכו'. גם זה שם בירושלמי.\",6,0],[8,378,13,1,\"ומ\\\"ש ובגדי אוכלי קדש מדרס לחטאת. משנה פ\\\"ב דחגיגה.\",7,0],[8,378,13,1,\"ומ\\\"ש אבל הטהור לקדש וכו'. ג\\\"ז שם בירושלמי:\",8,0],[8,378,13,2,\"וכן עשו חכמים מעלות בטבילה וכו' עד הוחזק לקל. משנה פ\\\"ב דחגיגה.\",1,0],[8,378,13,2,\"ומ\\\"ש טבל סתם ולא נתכוון וכו'. שם טבל ולא הוחזק כאילו [לא] טבל פי' הוחזק נתכוון היינו למעשר וממנו ולמעלה אבל לחולין אמרי' התם בגמרא דלא בעי כוונה בין בטבילה בין בנטילה.\",2,0],[8,378,13,2,\"ומ\\\"ש וכל המעלות האלו מד\\\"ס וכו'. שם משמע הכי:\",3,0],[8,378,13,3,\"מי שהיה טהור לתרומה וכו'. בפ\\\"ז דטהרות (משנה ח') וכחכמים.\",1,0],[8,378,13,3,\"ומ״ש וא״צ הערב שמש. הכי משמע בר״פ טבול יום (זבחים דף צ״ט):\",2,0],[8,378,13,3,\"והר\\\"י קורקוס ז\\\"ל הוקשה לו מ\\\"ש רבינו בספי\\\"ב האונן וכו' והסיחו דעתם ושמא נטמאו והוי דוקא לקדש והרי אף לתרומה צריכים טבילה כמ\\\"ש כאן והאריך ביישוב קושיא זו ולי הדבר פשוט דהתם לא הסיחו דעתם מטהרת גופם קאמר אלא שהסיחו דעתם מלאכול קדש שהרי הם אסורים לאכלו אנו חוששים שמא הסיחו דעתם גם מטהרת גופם וצריכים טבילה אע\\\"פ שאומרים שהם יודעים שלא הסיחו דעתם מטהרת גופם והיא מעלה בקדש ולא החמירו עליהן להצריכם הזאה שלישי ושביעי לחוש שמא נטמאו במת שמאחר שהם אומרים שיודעין שלא הסיחו דעתם מטהרת גופם דיינו שנגזור עליהם טבילה משום מעלה בעלמא:\",3,0],[8,378,13,3,\"היו ידיו טהורות וכו'. בפרק שביעי דטהרות וכתב שם הרא\\\"ש שהידים עסקניות ונגעו במקום הטינופת וצריכים נטילה לנגיעת תרומה אבל לא בשביל דחיישינן שמא נגעו בטומאה דא\\\"כ ליבעי כל גופו טבילה ועוד למה סתם ידים שניות ליחוש שמא נגעו באב הטומאה עכ\\\"ל.\",4,0],[8,378,13,3,\"ומ\\\"ש ואם לא שמר מטומאת מת וכו' ואם ידע שלא נטמא במת וכו'. בר\\\"פ טבול יום:\",5,0],[8,378,13,4,\"וכן גזרו חכמים על הכלים הנמצאים וכו'. וכן הרוקים הנמצאים. שם בפ\\\"ד דטהרות (משנה ה') על ששה ספיקות שורפין את התרומה וכו'. על ספק כלים הנמצאים על ספק רוקים הנמצאים ומייתי לה בפ\\\"ק דשבת (דף ט\\\"ו ע\\\"ב) ובפ\\\"ג דנדה (דף ל\\\"ג ע\\\"ב):\",1,0],[8,378,13,5,\"כל הכלים וכו'. משנה פ\\\"ח דשקלים (משנה ב') כל הכלים הנמצאים בירושלים דרך ירידה לבית הטבילה טמאים דרך עלייה טהורים וכו' דברי ר\\\"מ רבי יוסי אומר כלים טהורים חוץ מן הסל והמגריפה והמריצה המיוחדים לקברות וידוע דהלכה כרבי יוסי ולא חשש רבינו להוציא מן הכלל כלים המיוחדים לקברות לפי שדבר פשוט הוא שהם טמאים.\",1,0],[8,378,13,5,\"ומ\\\"ש שלא גזרו טומאה על הכלים הנמצאים בירושלים. בפירקא קמא דפסחים (דף י\\\"ט ע\\\"ב).\",2,0],[8,378,13,5,\"ומ\\\"ש חוץ מן הסכינין לשחיטת הקדשים וכו'. יתבאר ממה שיבא בסמוך והוא שנוי אצל מתניתין דכל הכלים וכו' שכתבתי בסמוך:\",3,0],[8,378,13,5,\"וכתב הראב\\\"ד חוץ מן הסכינים א\\\"א דבר זה אמר מפני וכו'. ומאחר שהעלה רואה אני את דבריו הרי הוא מסכים לדברי רבינו.\",4,0],[8,378,13,5,\"ומה שכתב אבל מצא סכין בי\\\"ד בניסן וכו'. שם סכין שנמצאת בי\\\"ד שוחט בה מיד בי\\\"ג שונה ומטביל קופיץ בין בזה ובין בזה שונה ומטביל חל י\\\"ד להיות בשבת שוחט בה מיד בט\\\"ו שוחט בה מיד נמצאת קשורה לסכין הרי זה כסכין ופירוש משנה זו מבואר כאן בדברי רבינו:\",5,0],[8,378,13,5,\"וכתב הראב״ד שוחט בה קדשים מיד א״א אין דברי המשנה כך וכו'. אין פירושו של הראב״ד מוכרח וכבר אפשר לפרש כפירוש רבינו אבל מה שקשה לי בדברי רבינו דבפרק אלו דברים (פסחים דף ע') אמרינן איבעיא להו לבן תימא יש משום שבירת עצם [בחגיגה] או אין בה משום שבירת עצם וכו' ת״ש סכין שנמצאת בי״ד וכו' עד לא מטביל לה ופירש״י שוחט פסחו מיד ואין צריך להטבילה וכו' משמע מהא דטעמא משום דחזקה אדם מטביל סכיניו לצורך שחיטת הפסח ורבינו עצמו כתב כן בפירוש המשנה ולמה תלה כאן רבינו הטעם בלא גזרו על הסכינים הנמצאים ביום זה ואפשר שלזה נתכוון הראב״ד שכתב וכל מ״ש כאן אינו כלום. וליישב דעת רבינו נ״ל דהכי קאמר שלא גזרו על הסכינים ביום זה מפני שחזקה שאדם מטביל סכיניו לצורך שחיטת הפסח. ועדיין יש לשאול למה השמיט דין הקופיץ בזה ובזה שונה ומטביל וי״ל משום דמאי דמפליג במתניתין בין קופיץ לסכין צריך לאוקומה כבן תימא דיחידאה הוא ואי מוקמינן לה כרבנן צריך לאוקומה בנשיא גוסס בי״ג ומת בי״ד דהוא מילתא דלא שכיחא ולכך כתב סתם דין הסכינים הנמצאים שבכלל זה הקופיץ ואע״ג שכתב לשחיטת הקדשים ה״ק לצורך שחיטת הקדשים שהקופיץ צורך שחיטת קדשים הוא לשבר עצמות החגיגה:\",6,0],[8,378,13,6,\"כתב הראב\\\"ד מפני שעשו אותה ביום הזה א\\\"א מים הרעים שתה כשפירשו לו וכו'. תמהני על פה קדוש שקרא מים הרעים לפי שלא ערב לו. ומ\\\"ש שאין כאן הזאה כל עיקר אבל אמרו שונה וכו' י\\\"ל דרבינו מדנקט תנא שונה יליף לה דהיינו לומר אנו מחזיקים אותו שכבר הזה עליו הזאה ראשונה כדי לטהרו לצורך יו\\\"ט והיום יום ז' ולכן שונה להזות עליו שנית ומטבילו ולדברי הראב\\\"ד קשה לישנא דשונה ועוד שכתב שמא עדיין לא הטבילו ואם לא הזה עליו איך יטהר בטבילה לחוד אם הוא טמא מת ועוד שכתב ואת\\\"ל שצריכה הזאה לא מן הטעם שלו וכו' שנראה שדברים אלו הם כדברי רבינו ממש ונ\\\"ל דה\\\"ק שאין כאן הזאה כלל אלא טבילה בלבד והטעם משום דכלי זה הוא ספק טמא ספק טהור ואת\\\"ל טמא שמא אינו טמא מת אלא טמא בשאר טומאות שאינן טעונות אלא טבילה לבד וא\\\"ת שלעולם נחוש לטומאת מת שצריך הזאה לא מן הטעם שלו שעשאוה ביום זה כאילו הוא שביעי שלה אלא הטעם שבודאי הקדים בעליו וכו' כלומר שרבינו תלה הטעם בשחכמים עשאוה ביום זה כאילו הוא יום שביעי שלה והראב\\\"ד סובר שלא הוצרכו חכמים לעשותה כי היא מעצמה בחזקה שודאי הקדים בעליה והזה הראשונה וכו'. וסתם דבריו וכל זה איננו שוה שעם כל זה נראה בעיניו יותר נכון לומר שאינו צריך הזאה מהטעם שכתבתי ולשון שונה יתפרש לדעת הראב\\\"ד אע\\\"פ שיש לומר שמא כבר הטבילו בעליו ישנה זה ויטבילנו ולדעת רבינו ניחא טפי. ומ\\\"ש לא מן הטעם שלו אלא שבודאי הקדים בעליו וכו' אומר אני שגם זה הוא הטעם שלו דמה טעם עשאוה חכמים ביום זה כאילו הוא שביעי שלה משום דחזקה שכבר הקדים בעליו והזה הראשונה וכו':\",1,0],[8,378,13,8,\"כל הרוקים הנמצאים בירושלים וכו'. שקלים פרק שמיני כרבי יוסי:\",1,0],[8,378,13,9,\"כשם שהראשון כו'. תוספתא פרק ה' דטהרות:\",1,0],[8,378,13,10,\"תרומה וקדשים שנטמאו וכו'. מתבאר ממה שיבא בסמוך:\",1,0],[8,378,13,11,\"ומ״ש ויש שם ספיקות שאין שורפין עליהם וכו' ויש שם ספיקות ששורפין עליהם וכו'. בטהרות פ״ד ופרק בנות כותים (נדה דף ל״ג ע״ב) וכתב רבינו גבי שורפין ואצ״ל קדשים וגם גבי אין שורפין כתב כן ונראים שהם כדברים סותרים זה את זה וביאור הדברים פשוט דקדשים חמירי מתרומה ומה ששורפין עליו תרומה דחשבינן ליה בודאי טמא מכ״ש דחשבינן ליה לקדש בודאי טמא ושורפין וידוע שראוי ליזהר [מ] לשרוף קדשים יותר ממה שראוי ליזהר מלשרוף תרומה וא״כ הספק שאין שורפין עליו תרומה מכ״ש שלא ישרפו עליו קדשים:\",1,0],[8,378,13,12,\"ומה שכתב אבל על ספק ספק הטומאה אין שורפין וכו'. כך הגירסא האמיתית בספרי רבינו ואיתא בפרק בנות כותים שם:\",1,0],[8,378,13,13,\"על ששה ספיקות וכו'. פרק חמישי דטהרות שם ולישנא דמתניתין על ספק מי רגלי אדם שהם כנגד מי רגלי בהמה ופירוש רבינו בה ע\\\"פ התוספתא.\",1,0],[8,378,13,13,\"ומ\\\"ש אבל אם נסתפק לו וכו'. שם וכת\\\"ק ואיתא בפרק בנות כותים:\",2,0],[8,378,14,1,\"שנים עשר ספיקות וכו'. פ\\\"ד דטהרות והשמיט רבינו ספק בכורות וספק נזירות מפני שאינה ענין לטומאה וטהרה והכניס במקומם ספק עובר ועומד וספק שתי רשויות:\",1,0],[8,378,14,2,\"ספק מים שאובים למקוה כיצד וכו'. פ\\\"ב דמקואות.\",1,0],[8,378,14,2,\"ומ\\\"ש ואין מורין לו וכו'. בתוספתא דמקואות פ\\\"ב אמר כן רבי יוסי גבי מקואות וסובר רבינו שאין חולק עליו גם סובר שה\\\"ה לדין זה:\",2,0],[8,378,14,3,\"ספק טומאה צפה על פני המים כיצד וכו' בין שהיו המים בכלים או בקרקעות וכו'. בפרק ד' דטהרות וכתנא קמא.\",1,0],[8,378,14,3,\"ומה שכתב אפילו אין שם אלא מלא אדם וטומאה וכו'. שם כרבי יוסי ומשמע לרבינו שאין חולק עליו:\",2,0],[8,378,14,3,\"ולא אמרו ספק טומאה צפה וכו'. בסוף נזיר (דף ס\\\"ג ס\\\"ד):\",3,0],[8,378,14,3,\"וכל הנתלין ונגררין וכו'. שם (דף ס\\\"ד) וגירסתו בגמרא הניטלים בטי\\\"ת ופירשו התוספות הניטלים אדם עומד במים וחבירו היה משלשל שרץ ספק נגע בו אדם העומד במים או הנגררים שחבירו היה גורר שרץ ע\\\"פ המים ספק נגע ספיקו טמא מפני שהם כמונחים כיון שאם אדם תופס בם אין כאן דין טומאה צפה:\",4,0],[8,378,14,4,\"שרץ שהיה מונח בכלי וכו'. בעיא שם ומסיים את\\\"ל בתר כלי אזלינן כלומר כיון שהוא מונח בכלי אין לו דין צף וכבר ידוע שדרך רבינו לפסוק כאת\\\"ל.\",1,0],[8,378,14,4,\"ומה שכתב או שהיה מונח על המת וכו'. כל הני בעיי דאיפשיטו שם באת\\\"ל.\",2,0],[8,378,14,4,\"ומה שכתב היה שרץ וכו'. שם בעיא דאיפשיטא באת\\\"ל אלא דבנוסחי דידן איפשיטא לחומרא ובנוסחת רבינו איפשיטא לקולא.\",3,0],[8,378,14,4,\"ומה שכתב היה מונח על גבי מי חטאת וכו'. שם בעיא דלא איפשיטא פירוש מספקא ליה מפני שהם עבים מפני האפר המעורב בהם דדילמא דמו לאוכלא.\",4,0],[8,378,14,4,\"ומ\\\"ש רבינו ויראה לי שספיקו טהור. נראה שטעמו משום דכיון שטהרו חכמים טומאה צפה ע\\\"פ המים הו\\\"ל ספיקא דרבנן ולקולא:\",5,0],[8,378,14,5,\"כדרך שטהרו ספק טומאה וכו' כיצד עריבה וכו'. תוספתא פ\\\"ה דטהרות:\",1,0],[8,378,14,6,\"ומ\\\"ש שרץ שנמצא צף וכו'. תוספתא בסוף טהרות ופירש ר\\\"ש לפועלים היינו אוכלי חוליהם בטהרה וא\\\"ת מאי שנא מעריבה דבסמוך דמטהרין לתרומה ואפשר דהכא שאני שהוא יין דמתוך שהיא צפה טהורה לפועלים ומתוך שאינה צפה ע\\\"פ המים טמאה לתרומה:\",1,0],[8,378,14,7,\"ספק משקים לטמא אחרים וכו' כיצד היה מקל בידו וכו'. משנה פרק רביעי דטהרות.\",1,0],[8,378,14,7,\"ומה שכתב וכן אם נסתפק לו אם נגעו משקים טמאים וכו'. ומה שכתב וכן אם נסתפק לו אם נגעו במשקים אלו וכו'. טעם כולם משום דטומאת משקים דרבנן.\",2,0],[8,378,14,7,\"ומה שכתב אבל טמא שפשט ידו. משנה פ\\\"ד דטהרות:\",3,0],[8,378,14,8,\"חבית שהיא מליאה משקים וכו'. בתוספת' דטהרות פ\\\"ה (מגע) טמא מת שפשט ידו לאויר החבית ספק נגע ספק לא נגע ספק אוכלים ומשקים טמא והכלי טהור. ונראה שספק אוכלים ט\\\"ס הוא דספק משקים ליטמא טמא אבל ספק אוכלים טהור וכך הם דברי רבינו שלא הזכיר לטמא אלא ספק משקים.\",1,0],[8,378,14,8,\"ומ\\\"ש וכן אם נכנסו משקים שהם טמאים מספק וכו'. שם חבית שיש בה משקים טהורים עד חציה ונפלו משקים לאוירה ספק טמאים ספק טהורים המשקים טהורים שאין מיטמאים אלא מחמת החבית נפלו על גבי המשקים משקים טמאים והחבית טהורה פירוש שאין מיטמאים אלא מחמת החבית וכדתנן בפרק ח' דכלים השרץ שנמצא בתנור הפת שבתוכו שנייה שהתנור תחילה והכא כיון שהחבית טהורה אף המשקים טהורים.\",2,0],[8,378,14,8,\"ומ\\\"ש וכן אם נפלו משקים אלו וכו'. שם אפה פת בתנור ונפלו משקים לאוירו ספק טמאים [ספק טהורין] הפת טהורה שאינה מיטמאת אלא מחמת התנור ומסיים בה נפלו על גבי הפת הפת טמאה והתנור טהור והשמיטו רבינו והטעם משום דמשמע ליה דמשבשתא היא דספק משקים ליטמא טמא אמרו לא ספק אוכלים ואי בעית לתרוצה צריך לאוקומה כשהיו בפת גומות ובהם משקים ומי הכניסנו בתגר זה הילכך להשמיטה עדיף:\",3,0],[8,378,14,9,\"המרבץ ביתו וכו' עד הרי ז. ו טמאה בספק. תוספתא דטהרות פרק ה' וכתב הראב\\\"ד הניח הככר עד שנגבו המים א\\\"א נ\\\"ל מפני מראית העין וכו' וטעם רבינו הגון:\",1,0],[8,378,14,11,\"ספק ידים וכו' עד והככרים כמו שהיו. משנה פ\\\"ב דידים.\",1,0],[8,378,14,11,\"ומ\\\"ש וכן אם היו ידיו טמאות וכו'. גם זה שם.\",2,0],[8,378,14,11,\"ומ\\\"ש ספק היה דבר חוצץ וכו'. נלמד ממה שנתבאר בסמוך:\",3,0],[8,378,14,12,\"היתה ידו אחת טמאה וכו'. זה נלמד ממ\\\"ש בראש הפרק גבי ספק מים שאובים למקוה אין מורין לו לטבול במקוה זה ולעשות טהרות לכתחילה:\",1,0],[8,378,15,1,\"ספק דברי סופרים כיצד וכו'. פ\\\"ד דטהרות:\",1,0],[8,378,15,1,\"ומ\\\"ש וכן אם אכל אוכלים טמאים וכו' וספק נגע בטהרות אלו וכו'. פשוט הוא שזה בכלל ספק ד\\\"ס.\",2,0],[8,378,15,1,\"ומ\\\"ש וכן האוכל ספק אוכלים טמאים וכו'. גם זה בכלל ספק ד\\\"ס.\",3,0],[8,378,15,1,\"ומ\\\"ש וכן האוכל תרומה תלויה טהור. תוספתא פ\\\"ה דטהרות.\",4,0],[8,378,15,1,\"ומ\\\"ש אבל אב הטומאה שהוא מד\\\"ס וכו'. משנה פ\\\"ד דטהרות.\",5,0],[8,378,15,1,\"ומ\\\"ש אא\\\"כ היה האב עצמו טמא בספק וכו' כמו שביארנו. בפי\\\"ג:\",6,0],[8,378,15,2,\"ספק החולין וכו'. משנה פ\\\"ד דטהרות:\",1,0],[8,378,15,3,\"ספק הקרבנות כיצד וכו'. שם ומייתי לה בסוף פירקא קמא דכריתות (דף ח'):\",1,0],[8,378,15,4,\"ספק נגעים כיצד וכו'. גם זה שם:\",1,0],[8,378,15,5,\"ספק עומד ועובר וכו'. בפרק שלישי דעדיות (משנה ז') ובפרק ששי דטהרות הטמא עומד והטהור עובר הטהור עומד והטמא עובר וכו' ספק האהיל ספק לא האהיל וכו' רבי יהושע מטמא וחכמים מטהרים וזה ע\\\"פ מה ששנינו פרק י\\\"ג דנגעים הטמא עומד תחת האילן והטהור עובר טמא הטהור עומד תחת האילן והטמא עובר טהור ואם עמד טמא וידוע דהלכה כחכמים:\",1,0],[8,378,15,6,\"ספק שרצים כו'. בפ\\\"ד דטהרות ספק שרצים כשעת מציאתן ובתוספתא אי זהו ספק שרצים שטיהרו חכמים זה ספק הנזרקין ובמשנה דטהרות רפ\\\"ד שנינו הזורק טומאה ממקום למקום ככר לבין המפתחות מפתח לבין הככרות טהור פי' מפתח טמא ואין ידוע אם נגע בככרות בעת עוברו עליהם וכן ככר לבין מפתחות טמאים אנו דנין הדבר כשעה שמצאנו אותו וכיון שעכשיו אין נגיעה טהור:\",1,0],[8,378,15,7,\"השרץ בפי חולדה וכו'. בפרק רביעי דטהרות.\",1,0],[8,378,15,7,\"ומ\\\"ש היתה מהלכת בו ונוגע בככרות וכו'. תוספתא פרק ד' דטהרות וכחכמים.\",2,0],[8,378,15,7,\"ומ\\\"ש במה דברים אמורים בזמן שנטלתו וכו' עד הרי אלו טמאות. שם בתוספתא.\",3,0],[8,378,15,7,\"ומ\\\"ש ראוהו חי בפיה. אע\\\"פ שמצאוהו מת בפיה כך היא הנוסחא הנכונה והיא בתוספתא בפרק הנזכר:\",4,0],[8,378,15,7,\"וכן השרץ בפי חולדה וכו'. משנה פרק ד' דטהרות שם:\",5,0],[8,378,15,8,\"ספק רשות הרבים כיצד. תוספתא פ\\\"ו דטהרות:\",1,0],[8,378,15,8,\"וכל אלו הספיקות וכו'. הדבר מבואר דלא קאי אמאי דסליק מיניה שהוא ספק ר\\\"ה אלא לספיקות הקודמים לזה:\",2,0],[8,378,15,8,\"וכתב הראב\\\"ד מפני שאין בהם א\\\"א זה שיבוש אלא אע\\\"פ שיש בהם עכ\\\"ל. ולכאורה משמע כדברי הראב\\\"ד דשאין בו דעת להשאל אפילו ברה\\\"י טהור בכל הספיקות ומאי רבותא דהני דקתני אלו ספיקות שטהרו חכמים אלא ודאי דהני אפילו שיש בהם דעת להשאל טיהרום אלא שבפ\\\"ק דחולין (דף ט' ע\\\"ב) אמרו על ההיא דשרץ בפי חולדה ומהלכת ע\\\"ג ככרות של תרומה דטעמא הוי משום דככר אין בו דעת להשאל ומשם למד רבינו דכל הני טיהרום מטעם זה וצ\\\"ל דמשמע לרבינו דכי תנן אלו ספיקות שטיהרו חכמים לאו למימרא שנשתנו אלו משאר ספיקות שאע\\\"פ ששאר ספיקות טמאות אלו טהורות אלא הספיקות שטיהרו חכמים מטעם שאין בו דעת להשאל מני ואזיל:\",3,0],[8,378,15,9,\"ספק ב' רשויות כיצד וכו'. משנה פ\\\"ו דטהרות במתניתין ד' ספקות ר' יהושע מטמא וחכמים מטהרים:\",1,0],[8,378,15,9,\"אע\\\"פ שספק ר\\\"ה טהור וכו'. בפ\\\"ב דע\\\"ז (דף ל\\\"ו:):\",2,0],[8,378,15,10,\"שרץ שנמצא שרוף וכו'. פ\\\"ט דטהרות.\",1,0],[8,378,15,10,\"ומ\\\"ש ומחט שנמצאת וכו'. שם פ\\\"ג:\",2,0],[8,378,15,11,\"שני עדים אומרים לו נטמא וכו'. ספ\\\"ה דטהרות וכחכמים.\",1,0],[8,378,15,11,\"ומ\\\"ש ואעפ\\\"כ אין אומרים לו עסוק בטהרות וכו'. תוספתא שם (פ\\\"ו) טהור ואין אומרים לו עסוק בטהרות אלא יחוש לעצמו. וכתב ר\\\"ש יחוש לעצמו דלגבי אחרים לא מהני מאי דקאמר לא נטמאתי אלא לדידיה דוקא הוא דמהני עכ\\\"ל ולישנא לא משמע כפירושו אלא הכי קאמר אפילו לעצמו יחוש ולא יתעסק בטהרות עד שיטבול.\",2,0],[8,378,15,11,\"ומ\\\"ש עד אומר נטמא וכו' עד סוף הפרק. משנה שם ספ\\\"ה דטהרות:\",3,0],[8,378,16,1,\"מפני מה טהרו חכמים וכו'. תוספתא דטהרות.\",1,0],[8,378,16,1,\"ומה שכתב ומפני מה החמירו ברשות היחיד וכו'. פירקא קמא דחולין (דף ט' ע״ב) ופרק כשם (דף כ״ח כ״ט) ופרק שני נזירים (נזיר דף נ״ז):\",2,0],[8,378,16,1,\"וכתב הראב\\\"ד הרי היא טמאה לבעלה עד שתשתה א\\\"א ובתוספתא מפרש עוד טעם אחר וכו'. וי\\\"ל לדעת רבינו שאותו טעם רבן שמעון בן גמליאל אמרו ויש לגמגם עליו דהא שלשה הם רבים כמו שכתב רבינו בסמוך והרי הם יכולים להשאל ולפיכך השמיטו רבינו והטעם הראשון הוא דברי בן זומא ששאלוהו והשיב וקבלו תשובתו ועוד דסוגיין דגמרא בכל דוכתא דספק טומאה ברשות היחיד טמא מסוטה ילפינן לה:\",3,0],[8,378,16,2,\"ומ\\\"ש וכשם שהסוטה ובועלה שנים וכו'. בפ' ב' נזירים.\",1,0],[8,378,16,2,\"ומ\\\"ש בד\\\"א כשהיה זה שנטמא בספק יש בו דעת להשאל וכו'. פ\\\"ק דנדה (דף ד' ע\\\"ב) ופרק כשם (דף כ\\\"ח ע\\\"ב) ובתוספתא דטהרות (פ\\\"ו).\",2,0],[8,378,16,2,\"ומ\\\"ש כיצד חש\\\"ו וכו'. משנה פ\\\"ג דטהרות:\",3,0],[8,378,16,3,\"הסומא והישן והמהלך וכו'. תוספתא פ\\\"ג דטהרות:\",1,0],[8,378,16,3,\"בד\\\"א שכל שאין בו דעת לישאל וכו' כיצד תינוק טמא וכו'. משנה פ\\\"ג דטהרות וכחכמים:\",2,0],[8,378,16,4,\"היו משקים טמאים וכו'. שם.\",1,0],[8,378,16,4,\"ומ\\\"ש ואם היה כלב וכו'. שם וכראב\\\"י דמשנתו קב ונקי.\",2,0],[8,378,16,4,\"ומ\\\"ש נמצא בבצק וכו'. שם.\",3,0],[8,378,16,4,\"ומ״ש במה דברים אמורים כשהיו המשקים צלולים וכו'. ס״פ עשרה יוחסין (קידושין דף פ' ע״ב) אמר ר״י ב״ל לא שאנו אלא במשקים לבנים וכו' ופירושו וכו'. ורבינו מפרש דר״י לא מפליג אלא בין צלולים לעכורים דצלולים אפילו אדומים הם נבלעים בבצק ואינם ניכרים ועכורים אפילו לבנים הם ניכרים ומאי דאמר פירושו לא שמע היינו לומר דלצלולים קרו לבנים ולעכורים קרו אדומים:\",4,0],[8,378,16,5,\"איזו היא חזקה וכו'. שם וכר\\\"י:\",1,0],[8,378,16,6,\"היו טומאות וטהרות וכו'. בתוספתא רפ\\\"ד ואיתא פ\\\"ק דנדה (דף ה' ע\\\"ב) היה וכו' עוטף בטליתו וכו' וטומאות וטהרות למעלה מראשו ספק נגע ספק לא נגע ספיקו טהור ואם א\\\"א לו אא\\\"כ נגע טמא וכתבו התוספות פי' טליתו טמא וטהרות בצדו או טליתו טהור וטומאות בצדו כגון שרץ ואינו יודע אם נגע אם לא נגע אי נמי טומאות וטהרות בצדו וטליתו טהור ואינו יודע אם נגע לטומאה ואח\\\"כ לטהרה וקמ\\\"ל דלא הוי ס\\\"ס שמא לא נגע הטלית בשרץ ואפילו נגע שמא לא נגע בטהרות דאם נגע בשרץ כמו כן נגע בטהרות עוד כתבו על מה שאמרו ואם א\\\"א אא\\\"כ נגע ואם תאמר פשיטא כיון דא\\\"א ודאי נגע וי\\\"ל דלאו לא אפשר כלל קאמר אלא כלומר קרוב לודאי וכן מוכיח בתוספתא שאמרו ואם א\\\"א אלא א\\\"כ נגע ספיקו טמא מדקאמר ספיקו משמע דלא הוי ודאי נגע עכ\\\"ל. וכ\\\"כ רש\\\"י:\",1,0],[8,378,16,7,\"ככר של תרומה וכו'. תוספתא דטהרות ופ\\\"ק דנדה עלה ד' ככר ע\\\"ג הדף וכו'.\",1,0],[8,378,16,7,\"ומ\\\"ש אע\\\"פ שהוא במקום מדרון. פירושו אע\\\"פ שהמדרס במקום מדרון שאפילו נפלה ככר על המדרס לא נשאר שם אבל אם המדרס בקרקע שוה פשיטא דטהור שאם היה נופל שם היה נשאר וכן פי' התוספות:\",2,0],[8,378,16,8,\"תינוק שנמצא וכו' וכן חמור וכו'. פ\\\"ג דטהרות:\",1,0],[8,378,16,9,\"תינוק שהיה תופס וכו'. תוספתא דטהרות פרק שלישי:\",1,0],[8,378,16,10,\"וארבעה ספיקות וכו'. גם זה תוספתא בפ' הנזכר.\",1,0],[8,378,16,10,\"ומ״ש הגדיל עד שיהא בו דעת לישאל וכו' עד אוכלין על גביו טהרות. בס״פ לולב הגזול (סוכה דף מ״ב).\",2,0],[8,378,16,10,\"ומ\\\"ש כיצד בודקים אותו. תוספתא פ\\\"ג דטהרות ופ\\\"ק דחגיגה שם:\",3,0],[8,378,17,1,\"כזית מן המת וכו'. פרק ד' דטהרות ואם תאמר הרי טומאה זו אין לה מקום כיון שהיא בפי עורב וספיקה טהור כמו שנתבאר בפרק ט\\\"ו גבי שרץ בפי חולדה ונבילה בפי הכלב ותירץ רבינו שמשון שכל המאהילים חשיבי יש לטומאה מקום אפילו בנזרקים:\",1,0],[8,378,17,1,\"וכן הממלא בכלי וכו'. פרק ד' דטהרות הממלא בעשרה דליים ונמצא שרץ באחד מהם הוא טמא וכולם טהורים ומה שמחלק בין יש לו אוגנים לאין לו נלמד ממה שיבא בסמוך ומפרש רבינו דהממלא בעשרה דליים היינו שהוא ממלא בכלי ונותן בעשרה כלים ואיני יודע מי הכריחו לפרש כן.\",2,0],[8,378,17,1,\"ומה שכתב וכן הממלא בעשרה דליים וכו'. פירקא קמא דנדה (עלה ג' ע\\\"ב) המדלה עשרה דליים מים זה אחר זה ונמצא שרץ באחד מהם הוא טמא וכולם טהורים ואמר ריש לקיש משום רבי ינאי לא שאנו אלא שאין לה אוגנים אבל אם יש לה אוגנים טמאים ונראה דה\\\"פ הכלי שנמצא בו השרץ הוא טמא וכולם טהורים מפני שאנו תולים שהיה השרץ בכלי קודם שהטיל בו מים וכל הדליים ושאר הכלים טהורים משום דאפילו אם תמצי לומר שהשרץ היה בבור ועלה בדלי וממנו נפל לכלי הדלי והכלי טהורים משום דהו\\\"ל טומאה צפה על פני המים אבל כשיש בדליים אוגנים חיישינן שמא אחר שיצאו המים נשאר בדלי ונטמא הדלי ואחר כך נפל השרץ לכלי. אבל קשה למה תשעה הכלים טמאים. ועל מ\\\"ש בבבא קמייתא ואם היה לכלי שמילא בו אוגנים וכו' קשה דזו אינה טענה אלא לטומאת הכלי שמילא בו לא לטמא שאר כלים וע\\\"ק דברישא טיהר מפני שאין בהם דעת לישאל ואם כן למה טימא כשיש בו אוגנים הא אין בהם דעת לישאל וצריך עיון:\",3,0],[8,378,17,1,\"המערה מכלי לכלי וכו'. פרק ד' דטהרות.\",4,0],[8,378,17,1,\"ועל מה שכתב רבינו מפני שהם כלים. א\\\"א תמה אני וכו'. ומ\\\"ש שהרי טומאה הבאה בידי אדם היא כלומר וכיון שהטומאה באה בידי אדם ה\\\"ל יש בה דעת לישאל ולדעת רבינו י\\\"ל שמאחר שלא נודע לאדם לא חשיבא באה בידי אדם. ומ\\\"ש ואף על גב דר\\\"י ס\\\"ל וכו'. בפירקא קמא דנדה שם:\",5,0],[8,378,17,2,\"קופה שנשתמש בה וכו' אם יש לה שוליים וכו'. פשוט בפ\\\"ק דנדה.\",1,0],[8,378,17,2,\"ומ\\\"ש או אזנים וכו'. שם כר\\\"י.\",2,0],[8,378,17,2,\"ומ\\\"ש ואפילו נשתמש בה בטהרות בזוית זו וכו'. גם זה שם וכר\\\"י:\",3,0],[8,378,17,3,\"הזולף את הבור וכו' עד הכל טמא. בסוף טהרות וכתב הר\\\"ש זולף מלשון שפיכה כמו מזלפים עליו ביד וכמו מזלפין על גבי האישים והכא הוצאת יין ושמן מן הבור זולף קרי ליה ויתכן דנופל לשון זולף בדבר שאין נעשה בבת אחת אלא מעט מעט דמתניתין דממלא כלים זה אחר זה מן הבור:\",1,0],[8,378,17,4,\"היה קוצה זיתים וכו'. בתוספתא פרק י״א דטהרות כחכמים ולא כרבי דפליג עלייהו ואמר דאם נמצא במעטן זיתים שבגג טהורים ואע״ג דסתם מתניתין פרק ט' דטהרות כרבי לא חש לה רבינו. ויש לתמוה דהא אמרינן בפרק החולץ (יבמות דף מ״ב ע״ב) דסתם במתניתין ומחלוקת בברייתא הלכה כסתם דמתניתין.\",1,0],[8,378,17,4,\"ומ\\\"ש נמצא בין כותל לזיתים וכו'. במשנה שם ופירש רבינו שמשון טהור ולא חיישינן שמא היה על הזיתים:\",2,0],[8,378,17,5,\"הקורץ מקרצת וכו' ונמצא השרץ וכו' עד אף העיסה טמאה. תוספתא דטהרות (פי\\\"א) וכחכמים ופירש ר\\\"ש הקורץ מלשון קרץ מצפון. מקרצות חתיכות של בצק וטעמא דעיסה כטעמא דמעטן עכ\\\"ל. ונמצא בתוכה ודאי בעיסה היה דאי במקרצת נפל לא היה בתוכה אלא על גבה:\",1,0],[8,378,17,6,\"אוכל טמא וכו' עד הולכים אחר הרוב. תוספתא דטהרות פ\\\"ד ובספרי רבינו כתוב אע\\\"פ שאין עליה משקה רותח וט\\\"ס הוא וצ\\\"ל טופח במקום רותח:\",1,0],[8,378,17,7,\"וכן אם היו דמים טהורים וכו' עד שהוא טהור. תוספתא דטהרות ריש פרק ז':\",1,0],[8,378,17,8,\"עיר שיש בה נבילות וכו'. שם וכת\\\"ק:\",1,0],[8,378,17,9,\"האשה שמגבבת וכו' עד סוף הפרק. תוספתא פ\\\"ג דטהרות:\",1,0],[8,378,18,1,\"כל שאתה יכול וכו'. פ״ו דטהרות וכתבו התוספות בפרק חזקת (בבא בתרא דף נ״ה ע״ב) דאפילו ס״ס טמא מפני כי מן הדין אפילו חד ספיקא ראוי לטהר דאוקמה אחזקתה וכיון דמטמאינן בחד ספיקא דילפינן מסוטה מ״ל חד ספיקא מה לי כמה ספיקי:\",1,0],[8,378,18,2,\"תשעה צפרדעים וכו'. תוספתא פ\\\"ו דטהרות:\",1,0],[8,378,18,2,\"זה הכלל כל ספק וכו'. משנה פ\\\"ז דטהרות.\",2,0],[8,378,18,2,\"ומ\\\"ש לפיכך עצמות המת ועצם נבילה וכו'. משנה פ\\\"ה דטהרות וכחכמים:\",3,0],[8,378,18,3,\"המוצא מת מושכב וכו'. פרק כיצד צולין עלה פ\\\"א (ע\\\"ב) ודע דמסיים בה במה דברים אמורים במהלך ברגליו אבל טעון או רכוב טמא וכו' לפי שטעון או רכוב א\\\"א שלא יגע ולא יאהיל ופירש רש\\\"י בד\\\"א דמשובר ומפורק טהור טעון משוי ע\\\"כ הולך נע ונד לכאן ולכאן ומאהיל על צדדיו עכ\\\"ל. ואיני יודע למה השמיטו רבינו ואפשר שסמך על מה שכתבו בפרק ו' מהלכות קרבן פסח ושם כתבתי בביאור דינים הללו:\",1,0],[8,378,18,4,\"שרץ שנמצא במבוי וכו'. משנה פרק דם הנדה (נדה דף נ״ו) השרץ שנמצא במבוי מטמא למפרע עד שיאמר בדקתי את המבוי הזה ולא היה בו שרץ או עד שעת כיבוד ובגמרא איבעיא להו עד שעת כיבוד חזקתו בדוק או דילמא חזקתו מתכבד ומאי נפקא מינה דאמר כיבד ולא בדק אי אמרת חזקתו בדוק הא לא בדק אי אמרת חזקתו מתכבד הא מתכבד ופירש רש״י חזקתו בדוק מי מחזקינן דבדיק ליה בשעת כיבוד וכו' או משום דחזקתו מתכבד דאי הוה התם בשעת כיבוד הוה נפיק האי שרץ מחמת כיבוד ואסיקנא דחזקתו בדוק.\",1,0],[8,378,18,4,\"ומ\\\"ש בד\\\"א שמצאו יבש וכו'. שם במשנה לר\\\"ש ופסק רבינו כוותיה משום דר\\\"א מפרש מילתיה בגמרא:\",2,0],[8,378,18,5,\"שני רוקין ברה\\\"י וכו'. פרק ד' דטהרות שני רוקין אחד טמא ואחד טהור תולין על מגען ועל משאן ועל היסטן ברה\\\"י ועל מגען בר\\\"ה בזמן שהם לחים ועל משאן בין לחים בין יבשים ופירושה מבואר כדברי רבינו.\",1,0],[8,378,18,5,\"ומ\\\"ש כבר ביארנו שאם נגע ברוק הנמצא וכו'. שם היה רוק יחידי ונגע בו ונשאו והסיטו בר\\\"ה שורפין עליו את התרומה ואין צ\\\"ל ברה\\\"י.\",2,0],[8,378,18,5,\"ומ\\\"ש כבר ביארנו. הוא בפרק י\\\"ג מהלכות אלו:\",3,0],[8,378,18,6,\"מי שישב ברשות הרבים וכו'. בפרק ה' דטהרות:\",1,0],[8,378,18,7,\"מי שאבד לו כלי וכו'. תוספתא דטהרות.\",1,0],[8,378,18,7,\"ומ\\\"ש אבד לו בר\\\"ה וכו'. משנה פ\\\"ח דטהרות:\",2,0],[8,378,18,7,\"כתב הראב\\\"ד או מקצתו טמא א\\\"א בתוספתא בר\\\"ה אבד ביום ומצא בלילה טמאים מדרס וטהורין טמא מת וברה\\\"י טמא מדרס וטמא מת. ולקמן אצל מ\\\"ש רבינו וכן מי שאבדו כליו ברה\\\"י ומצאן אפילו בו ביום הרי הם טמא מדרס וטמא מת כמו שביארנו כתב הוא לא ביאר כן למעלה אלא שאם אבד ומצא בו ביום אפילו ברה\\\"י טהורים וכן הוא במשנה ובתוספתא עכ\\\"ל:\",3,0],[8,378,18,7,\"והילך לשון המשנה המאבד ביום ומצא ביום טהור ביום ומצא בלילה בלילה ומצא ביום ביום ומצא ביום של אחריו טמא זה הכלל כל שעבר עליו הלילה או מקצתו טמא פירוש דביום אמרינן דסתמא אם היה אדם נוגע בו היה מגביהו כדרך כל מוצא אבדה אבל אם היה אבוד אפילו שעה אחת מהלילה אפשר שבאותה השעה דרסו עליו ולא ראוהו וז\\\"ל התוספתא המאבד והמוצא ברה\\\"י ועבר עליהם הלילה טמא מדרס וטמא מת בר\\\"ה ועבר עליהם הלילה טמאים מדרס וטהורים טמא מת ר\\\"ש מטהר וכו' ומודים חכמים לר\\\"ש במניח ושוכח וכו' ברה\\\"י שעבר עליהם לילה טמאים מדרס וטהורים מטמא מת ע\\\"כ ומדברי ר\\\"ש נראה דאינו גורס גבי רה\\\"י עבר עליו הלילה וכתב דמשום חומרת רה\\\"י דספיקו טמא לא מפלגינן בין יום ללילה ומתני' דקתני ביום ומצא ביום מיירי בר\\\"ה וכן נראה מדברי רבינו וכוונת הראב\\\"ד בהשגה הראשונה להשיג על רבינו שכתב דבר\\\"ה אם עבר עליו הלילה סתם וכתב ה\\\"ז בחזקת טמא דמשמע שהוא טמא מדרס וטמא מת כעין מ\\\"ש ברישא וליישב דברי רבינו נאמר דאדרבה מדברישא כתב טמא מדרס וטמא מת משמע דכשכתב סתם טמא אינו אלא טמא מדרס בלבד:\",4,0],[8,378,18,7,\"ובהשגה השנית משיג עליו שהוא לא ביאר כן למעלה וכו' ועוד דהמשנה ותוספתא הוו תיובתא למ\\\"ש שאם מצאם אפילו בו ביום טמאים:\",5,0],[8,378,18,7,\"ואני אומר שאני תמה על מ\\\"ש שהוא לא ביאר כן למעלה וכו'. שדבריו מבוארים באר הטב דברה\\\"י סתם וכתב ה\\\"ז טמא ולא חילק בין עבר עליו הלילה ללא עבר עליו כדמפליג בר\\\"ה. ומה שהקשה עליו מהמשנה אינה קושיא שמה ששנינו המאבד ביום ומצא ביום טהור פי' רבינו דהיינו דוקא בר\\\"ה אבל ברה\\\"י טמא ומה ששנינו בתוספתא המאבד והמוצא ברה\\\"י ועבר עליהן הלילה טמא דמשמע הא אם לא עבר עליו הלילה טהור י\\\"ל דברה\\\"י אפילו מאבד ומוצא ביום טמא ולא כתב ועבר עליהם הלילה אלא משום דבעי למיתני בסיפא דבר\\\"ה ועבר עליהם הלילה טמאים ור\\\"ש מטהר תנא ברישא גבי רה\\\"י ועבר עליהן הלילה טמאים לאשמועינן דאע\\\"ג דר\\\"ש פליג בסיפא מודה ברישא דמתניתין מסייעא לרבינו דקתני בדין שוטח כלים דבסמוך שאם נפלו והלך להביאם טמאים ולא מפליג בין יום ללילה וכן שנינו עוד שם נפל דליו לתוך בורו של עם הארץ והלך להביא במה יעלנו טמא מפני שהונח ברשות ע\\\"ה שעה אחת ולא מפליג בין יום ללילה:\",6,0],[8,378,18,8,\"הניח כלי או שכח וכו'. תוספתא פרק תשיעי דטהרות שם:\",1,0],[8,378,18,9,\"המאבד ומצא בתוך הבית וכו'. שם בתוספתא. וכתב רבינו שמשון דלא שכיחי התם עכו\\\"ם ועם הארץ בתוך הבית של חבר:\",1,0],[8,378,18,10,\"השוטח כלים וכו'. משנה פרק ח' דטהרות פירוש דהוי ככל ספק טומאה דבר\\\"ה טהור ברה\\\"י טמא וכ' רבינו שמא נגעו בהם טמאים פי' דלמדרס אין לחוש שאין דרך העוברים לדרוס על בגדים השטוחים לייבש אבל אפשר שנגעו בהם משא\\\"כ באבידה שאין רואים ודורסים עליה ולכך אין מקום לחלק בזה בין יום ללילה כמו באבידה וכשמשמרן אפילו נגיעה לא נגעי.\",1,0],[8,378,18,10,\"ומ\\\"ש וכן מי שאבדו כליו וכו'. תוספתא פ\\\"ט דטהרות:\",2,0],[8,378,18,11,\"שוטה אחת בעיר וכו' עד ואם לאו ישאלנה. טהרות פ\\\"ה פירוש כי השוטה אינה יודעת עתות וסתה ולכך תמיד היא בחזקת טמאה וכן הנכרית וכתב ר\\\"ש אבל איש שוטה לא שאין האיש רגיל בזיבות וגבי נכרית ה\\\"ה לעכו\\\"ם דעשאום כזבים. ובמשנה הזכירו כותית ורבינו השמיטה משום דעשאום כעכו\\\"ם ובכלל נכרית היא:\",1,0],[8,378,18,13,\"מי שישן בר\\\"ה וכו'. שם וכחכמים:\",1,0],[8,378,18,14,\"נגע בר\\\"ה וכו'. ג\\\"ז שם וכחכמים.\",1,0],[8,378,18,14,\"ומ\\\"ש ואם ראוהו חי וכו'. בתוספתא דטהרות פ\\\"ז:\",2,0],[8,378,18,15,\"המסוכן ברה\\\"י וכו'. משנה ריש פרק ו' דטהרות וכת\\\"ק.\",1,0],[8,378,18,15,\"ומ\\\"ש מעשה באחד וכו'. תוספתא דטהרות פ\\\"ו:\",2,0],[8,378,18,16,\"טמא שהיה עומד ומדבר וכו'. משנה פ\\\"י דטהרות מי שהיה עומד ומדבר על שפת הבור וניתזה צינורא מפיו ספק הגיעה לבור ספק לא הגיעה ספיקו טהור ובתוספתא בסוף טהרות מסיים בה של שמן ספיקו טמא של יין ספיקו טהור מפני שהבל הבור קולטת ופירש ר\\\"ש כשניתזה הצינורא על שפת הבור של יין קולטה השפה ומונעה מלירד ובבור סיד שאינו מקבל טומאה אבל בבור של שמן שלפני הבד מתוך שהשמן מחליק ומצחצח טפת הצינורא מחלקת ויורדת עד למטה עכ\\\"ל:\",1,0],[8,378,19,1,\"שני שבילין וכו' וכן השרץ וכו'. פ\\\"ה דטהרות:\",1,0],[8,378,19,2,\"שני שבילין אחד טמא וכו' וכן אם נטמאו בטומאה קלה וכו'. שם שני שבילין אחד טמא ואחד טהור וכו' שני ככרים אחד טמא ואחד טהור וכו' ובפרק קמא דפסחים עלה י' ובפרק שני דכתובות אמר רבי יוסי בבת אחת דברי הכל טמאים בזה אחר זה דברי הכל טהורים לא נחלקו אלא בבא לישאל עליו ועל חבירו רבי יוסי מדמי ליה לבת אחת ורבי יהודה מדמי ליה לזה אחר זה וידוע דהלכה כרבי יוסי.\",1,0],[8,378,19,2,\"ומה שכתב ואפילו ככר טמאה וכו'. שם בתוספתא רבי יוסי אומר טמא שאפילו טמאה שנתערבה במאה טהורות טמא:\",2,0],[8,378,19,3,\"ככר טמא שנתערב וכו'. תוספתא פ\\\"ו דטהרות שם:\",1,0],[8,378,19,4,\"שני שבילין אחד טמא וכו'. נדה פרק האשה (דף ס'):\",1,0],[8,378,20,1,\"כל מקום שהוא רה\\\"ר וכו'. נלמד ממה שיבא בסמוך:\",1,0],[8,378,20,2,\"ארבע אמות הסמוכות לר\\\"ה וכו'. פ\\\"ק דבתרא (דף י\\\"ב).\",1,0],[8,378,20,2,\"ומ\\\"ש וכן הכרמלית וכו'. בסוף פ\\\"ו דטהרות האצטוונית רה\\\"י לשבת ור\\\"ה לטומאה:\",2,0],[8,378,20,3,\"יש שם מקומות וכו' ואלו הם השבילים המפולשים וכו'. שם וכת\\\"ק ואיתא בפ\\\"ב דעירובין (דף כ\\\"ב ע\\\"ב).\",1,0],[8,378,20,3,\"ומ\\\"ש והבקעה המוקפת וכו'. דין הבקעה פ\\\"ו דטהרות שם ואיתא בפ\\\"ק דשבת (דף ו' ע\\\"ב) וכאוקימתא דרב אשי.\",2,0],[8,378,20,3,\"ומ\\\"ש ובסילקי וכו' והפורן וכו' וחצר שהרבים וכו'. פ\\\"ו דטהרות.\",3,0],[8,378,20,3,\"ומ\\\"ש וכן מבואות היורדים לים וכו' והבימוסות והמרחצאות. תוספתא פרק שלישי דטהרות.\",4,0],[8,378,20,3,\"ומה שכתב וכן כל העזרה וכו'. פירקא קמא דפסחים (דף י\\\"ח ע\\\"ב):\",5,0],[8,378,20,4,\"גנות העיר וכו' עד רה\\\"י לכל. תוספתא דטהרות פ\\\"ז:\",1,0],[8,378,20,6,\"הבקעה המוקפת גדר וכו'. פ\\\"ו דטהרות וכאוקימתא דרב אשי פרק קמא דשבת (דף ו' ע\\\"ב) ומייתי מתניתין דטהרות בפ\\\"ט דבתרא (דף קנ\\\"ג ע\\\"ב) ואמר רבא לא שאנו אלא שלא עברו עליה ימות הגשמים אבל עברו עליה ימות הגשמים רה\\\"י לכאן ולכאן:\",1,0],[8,378,20,6,\"ואלו הם ימות החמה וכו' ואלו הם ימות הגשמים וכו'. תוספתא דטהרות פ\\\"ז:\",2,0],[8,378,20,6,\"בין העגולים של ענבים וכו' עד שכנגדה. בסוף טהרות:\",3,0],[8,378,20,7,\"שאר כל המקומות וכו':\",1,0],[8,378,20,8,\"ויש מקומות שאינם רשות היחיד וכו': כיצד אילן שהוא עומד ברשות הרבים וכו' עד שהחנות רשות היחיד. טהרות פרק ו':\",1,0],[8,378,20,9,\"וכתב הראב״ד שהחנות רשות היחיד א״א הפירוש הזה חשך ולא אור ומה בין זה לזה אבל רישא וכו'. איני יודע למה חרד כל החרדה הזאת לומר שהפי' הזה חשך ולא אור ועוד מה זה שכתב ומה בין זה לזה והלא כבר ביאר רבינו מה בין זה לזה כשהוא חנות אחת טמא הרי כלל החנות דבר טמא שהוא מונח בר״ה ספק נכנס ונטמא ספק לא נכנס טהור כדין ספק טומאה ברשות הרבים אבל כשהם שתי חנויות אחת טמאה ואחת טהורה ונכנס ודאי לאחת מהם ואינו יודע לאיזו מהם הו״ל נכנס לרשות היחיד ואינו יודע אם נטמא דהוי ספק טומאה ברשות היחיד וטמא וכן מבואר בדברי רבינו בפירוש המשנה והוא פירושו של הראב״ד: וכן בקעה בימות הגשמים וכו'. בפרק ששי דטהרות וכחכמים ואיתא בפרק קמא דפסחים (דף י') ופרק חזקת (בבא בתרא דף נ״ה) ופרק בתרא דעבודה זרה (דף ע'):\",1,0],[8,378,20,10,\"מקום שהיה רשות היחיד וכו'. שם:\",1,0],[8,378,20,11,\"דברים שהם בר\\\"ה וכו'. תוספתא דטהרות פ\\\"ז:\",1,0],[8,378,20,11,\"וכתב הראב\\\"ד או בנייר ונתון לתוכה ספק נגע א\\\"א לא ידעתי מהו זה וכו'. ואני אומר שגירסת רבינו בתוספתא לא היתה כגירסת הראב\\\"ד והטעם מבואר שמאחר שהככר שהוא המקבל טומאה נתון לתוכה הרי הוא כרשות היחיד ועוד שכיון שהיא על כתיפו הוי כמונח ברה\\\"י כמו ששנינו בפרק רביעי דטהרות שני רוקים וכו' וכיון שהוא מונח על כתיפו הוי יש בו דעת לישאל וספיקו בכל ענין טמא ואי זה סופר טועה הגיה מדעתו בבא זו לחלק בין הכניס ידו לתוכה ללא הכניס מפני שבבבא ראשונה חילקו בכך ולא שת לבו לזאת דלא שייך לחלק בה בכך כמ\\\"ש ותמהני על אדוננו הראב\\\"ד ז\\\"ל שלא דקדק בכך ואפשר שמפני שהרגיש בכך לא כתב כלשון משיג אלא כמסתפק:\",2,0],[8,378,20,13,\"ומ\\\"ש היה זב רוכב על חמורו וכו' עד סוף הפרק. שם בתוספתא וכרבי יוסי מחבירו:\",1,0],[8,378,20,13,\"סליקו הלכות אבות הטומאות\",2,0],[8,379,1,1,\"כל אוכל המיוחד למאכל אדם וכו'. ריש פ\\\"ג דעוקצין כל האוכלין המיוחדין למאכל אדם צריכים הכשר ואינם צריכים מחשבה.\",1,0],[8,379,1,1,\"ומ״ש וכל שאינו מיוחד למאכל אדם וכו'. שם ובפרק בהמה המקשה (חולין דף ע״ז) במשנה גבי שוחט בהמה ומצא בה שליא.\",2,0],[8,379,1,1,\"ומ\\\"ש וזה אינו מקבל טומאה עד שיבלל תחילה וכו'. מבואר בפ\\\"ג דעוקצין ובכמה דוכתי בגמרא:\",3,0],[8,379,1,2,\"ואלו הם השבעה משקים וכו'. פ\\\"ו דמכשירין אלא ששם אמרו דדוקא דבש דבורים אבל דבש צרעים אינו מכשיר ואמרינן בפרק קמא דבכורות (דף ז' ע\\\"ב) שהטעם מפני שיש לו שם לווי כלומר אבל דבש סתם אינו אלא דבש דבורים ולפיכך כתב רבינו דבש סתם:\",1,0],[8,379,1,2,\"ואינם מכשירין עד שיפלו על האוכלין ברצון הבעלים. בריש מכשירין ובפרק ג' דקידושין (דף נ\\\"ט:) ופרק ב' דמציעא (דף כ\\\"ב:) יליף לה מקרא:\",2,0],[8,379,1,2,\"ולא יהיו סרוחים וכו'. בפרק קמא דפסחים (דף י\\\"ח) ובסוף מכשירין ובתורת כהנים פרשת שמיני ובתוספתא דטהרות פ\\\"ט:\",3,0],[8,379,1,2,\"וכיון שהוכשר האוכל וכו'. כן משמע בפ\\\"ב דמציעא וכדפירש\\\"י וכן משמע בפרק קמא דפסחים ובפ\\\"ב דחולין ובתוספתא דמכשירין פ\\\"ב:\",4,0],[8,379,1,3,\"אוכל שהיה בלול במי פירות וכו'. בפי\\\"א דתרומות דבש תמרים ויין תפוחים וכו' ושאר כל מי פירות וכו' ר\\\"א מטמא משום משקה ורבי יהושע אומר וכו' ז' משקים טמאים ושאר כל המשקים טהורים ופירש רבינו ר\\\"א סובר שדבש תמרים וכו' מקבלים טומאה משום משקה והם נכללים במה שאמר ה' וכל משקה אשר ישתה בכל כלי יטמא והעיקר אצלנו כי ז' משקים בלבד הם שמקבלים טומאה ועליהם בלבד ועל תולדותיהם אמר הכתוב וכל משקה אשר ישתה והם ג\\\"כ שמכשירים את הזרעים לטומאה וכו' ואין מטמאים ואין מכשירין לטומאה שום דבר מהמשקים אלא השבעה בלבד עכ\\\"ל וידוע דהלכה כרבי יהושע:\",1,0],[8,379,1,4,\"וכתב הראב\\\"ד כך אין מקבלין טומאה א\\\"א לא מצאתי שאין מקבלין טומאה כלל וכו'. השתדל הרב ז\\\"ל להביא ראיות שמי פירות אינם מצטרפין כדי לדייק שלא אמרו אלא שאין מצטרפין אבל הם עצמם בני קבולי טומאה. עוד חשש שמא רבינו כתב שאין מי פירות מקבלין טומאה מפני שאמרו בתוספתא דבש תמרים אינו אוכל ולא משקה וה\\\"ה לשאר מי פירות. וכתב לסתור ראיה זו והאריך בזה: ואני אומר שטעמו של רבינו מדתנן ר\\\"א מטמא משום משקה דלישנא דמטמא עצמו משום משקה משמע דהיינו שמקבלים טומאה כשאר משקים ועלה קתני רבי יהושע ושאר כל המשקים טהורים משמע דבמאי דמטמא ר\\\"א עצמן משום משקה מטהר רבי יהושע לומר שאין מי פירות עצמם מקבלים טומאה ופשטא דלישנא דושאר כל המשקים טהורים הכי משמע ומה שרצה להביא ראיה הראב\\\"ד מדתנן במסכת טבול יום עיסה שהוכשרה במשקה וכו' אני אומר דאדרבא משם ראיה לדברי רבינו שאם כדברי הראב\\\"ד הו\\\"ל למיתני עיסה שהוכשרה ונילושה במי פירות דהוה משמע דמי פירות קאי גם אהוכשרה ומדקתני שהוכשרה במשקה משמע בהדיא דמשקה לחוד ומי פירות לחוד דהכשר לא הוי אלא במשקה דלאו מי פירות ולענין אי מצרף או לא לא הוי אלא למי פירות ונראה שזו תשובה נצחת. ומה שרצה לדייק מדאמרי' בתוספתא דעוקצין פ\\\"ק דמי פירות אינם מחברים איצטרופי הוא דלא מצטרפי הא אינהו גופייהו בני קיבולי טומאה נינהו אין דיוק זה דיוק דלגופא איצטריך דאע\\\"ג דאינהו גופייהו אינם מקבלים טומאה סד\\\"א דמצרפי קמ\\\"ל. ומה שכתב הראב\\\"ד לחלק בין משקים היוצאים מעליהם לסחטן למשקים איני יודע זו מנין לו לחלק בכך מאחר שלא נמצא כן בביאור. ומה שהביא ראיה ממה שאמרו השמן לא אוכל ולא משקה אינה ראיה מוכרחת שרבינו העמידה בשמן קרוש כדלקמן. ומ\\\"ש ואיה איפה עסיס רמונים ויין תפוחים שמיישנין אותו לרפואת בני מעים איני יודע מה טענה היא זו לומר שמקבלים טומאה ומצאתי בת\\\"כ אין לי אלא מים מנין הטל והיין השמן והדם והדבש והחלב ת\\\"ל וכל משקה אי כל משקה יכול מי תותים או מי פירות או מי רמונים ושאר כל מיני פירות ת\\\"ל מים מה מים מיוחדים שאין להם שם לווי יצאו מי תותים ומי רמונים ושאר כל מיני פירות שיש להם שם לווי ע\\\"כ הרי שלא מיעט שאר מי פירות מפני שיצאו מאליהם אלא מפני שיש להם שם לווי וטענה זו שייכא אפילו בסחטן למשקים וזה פשוט ומבואר כדברי רבינו:\",1,0],[8,379,1,5,\"זיתים וענבים שלא הביאו שליש אינם מכשירים וכו'. ירושלמי פ\\\"ק דמעשרות והטעם משום דלא חשיבא תבואה אלא כשזורעין אותה ומצמיח וכשלא הביאה שליש אינו ראוי לזריעה כדאיתא בפ\\\"ק דראש השנה (דף י\\\"ג) וכבר נתבאר בסמוך שכל מה שאינו מכשיר אינו מקבל טומאה:\",1,0],[8,379,1,6,\"אלו דברים וכו'. בפ״ג דעוקצין ופרק בא סימן (נדה דף נ״א ע״ב):\",1,0],[8,379,1,7,\"השבת סתמו לאכילה גופו וכו'. בפרק ג' דעוקצים השבת משנתן טעמו בקדירה אין בו משום תרומה ואינו מטמא טומאת אוכלים ופירש רבינו שבת בלשון ערבי שבת והעיקר אצלנו סתם שבת לכמך עשוי ולא לקדירה ופי' הדברים [האלה כי בידוע כי השבת] נאכל כמו שהוא חי אחר המזון וכו' לא שיבושל בקדירה וע\\\"כ כל זמן שלא נתבשל חייב בתרומה ומטמא טומאת אוכלין אבל כשנתבשל כיון שהשליך כחו בבישול וימצא בבישול טעם השבת כבר תמה תועלתו והנשאר ממנו אחר כך הוא במדרגת השמרים אשר אינם ראויים לאכילה וע\\\"כ אינו חייב בתרומה ולא יטמא טומאת אוכלים עכ\\\"ל ור\\\"ש כתבו בפרק בא סימן משמע דטעמא משום דסתם שבת לכמך עשויה הא אי הוה סתמא לקדירה לא הוה עליה תורת אוכל דתבלין אין מטמאין טומאת אוכלים עכ\\\"ל וכ\\\"כ הריטב\\\"א הא עד שלא נתנה מטמאה ובסתם שבת קאמר אלמא סתמא לכמכא עכ\\\"ל הרי מבואר כדברי רבינו ושלא כדברי הראב\\\"ד שכתב ואם חשב עליו לקדירה א\\\"א לא כן שאינם יוצאים מידי טומאה במחשבה עד שתתן טעם לקדירה:\",1,0],[8,379,1,8,\"התמרים והגרוגרות וכו'. תוספתא בסוף טבול יום אלא שכתוב בה עד שיפסלו לכלב והיא נוסחא נכונה:\",1,0],[8,379,1,9,\"הכרשינין אם ייחדן וכו'. תוספתא בסוף טבול יום כרשינין מטמאים טומאת אוכלים דברי רבי יהודה ר\\\"ש אומר אינם מטמאין ופסק כרבי יהודה ומשמע לרבינו דדוקא אם ייחדן למאכל אדם והטעם מפני שהם מאכל בהמה ואין אוכלים אותם בני אדם אלא בזמן רעב כדאיתא בירושלמי סוף חלה:\",1,0],[8,379,1,10,\"הקור הרי הוא כעץ וכו'. בפרק ג' דעוקצין.\",1,0],[8,379,1,10,\"ומ״ש ואם שלקו וטגנו. בפרק בכל מערבין (עירובין דף כ״ח ע״ב):\",2,0],[8,379,1,11,\"החרצנים והזגין וכו'. תוספת' בסוף עוקצין ופרק י\\\"ג דטהרות:\",1,0],[8,379,1,12,\"זיתים וענבים הקשים וכו'. בפרק שלישי דעוקצין פריצי זיתים וענבים ב\\\"ש מטמאים וב\\\"ה מטהרים ובתוספתא אלו הם פריצי זיתים וענבים היוצאים מתחת הגפת ומתחת הזגים.\",1,0],[8,379,1,12,\"ומ\\\"ש ועד כמה עד ארבעה קבים לכל כור. בפרק המקבל עלה ק\\\"ה.\",2,0],[8,379,1,12,\"ומ\\\"ש ואם כנסן לאוכלים וכו'. תוספתא בסוף עוקצין:\",3,0],[8,379,1,13,\"הכפניות. בפ\\\"ג דעוקצין פירוש כפניות תמרים רעים שלא בשלו כל צרכן.\",1,0],[8,379,1,13,\"ומ\\\"ש הפגין והבוסר. שם כר\\\"ע מחבירו.\",2,0],[8,379,1,13,\"ומ\\\"ש והקצח. שם הקצח ב\\\"ש מטהרים וב\\\"ה מטמאים ובפ\\\"ה דעדיות מונה אותה מקולי ב\\\"ש ומחומרי ב\\\"ה:\",3,0],[8,379,1,14,\"לולבי זרדים וכו'. פ\\\"ג דעוקצין לולבי זרדין ושל ערל ועלי הלוף השוטה אינם מקבלים טומאת אוכלים עד שימתקו.\",1,0],[8,379,1,14,\"ומ\\\"ש והחרובין. שם בתוספתא:\",2,0],[8,379,1,15,\"החרדל והתורמוסים ושאר כל הנכבשים וכו'. תוספתא שם:\",1,0],[8,379,1,16,\"זיתים שכבשן וכו' עד מפני שאינו אוכל. משנה רפ\\\"ב דעוקצין:\",1,0],[8,379,1,18,\"דבש בכוורתו וכו'. בפ' הספינה (בבא בתרא דף פ').\",1,0],[8,379,1,18,\"ומ\\\"ש רדה הדבש וכו'. בסוף עוקצין וכבית הלל:\",2,0],[8,379,1,18,\"דבש הזב וכו' עד טומאת אוכלים. תוספתא פרק ב' דטהרות:\",3,0],[8,379,1,19,\"השמן הקרוש וכו'. תוספתא פ״ב דטהרות אלא שהיא כתובה בשיבוש. וכתב הראב״ד א״א אין בתוספתא שקרש וכו'. ויש לומר לדעת רבינו שאע״פ שאין בתוספתא שקרש א״א לומר דבכל שמן מיירי שהרי הוא משבעה משקים ולפיכך פירש דבקרוש מיירי ולא נראה לו להעמידה ביוצא מאליו ומה שהביא הראב״ד ראיה מדתנן במסכתא טהרות הרוטב והגריסין וכו' מאי תחילה לעולם וכו' וחכמים מודים לו. איני יודע זו מנין לו אדרבא כיון דבלשון יחיד נאמר משמע דרבנן פליגי עליה אחר כך מצאתי בתוספות שכתבו בפרק אור לארבעה עשר (פסחים דף י״ד ע״ב) בד״ה אפי' מכאן משמע דשמן חשוב משקה ולקמן גבי משקה בית מטבחייא וכן בכמה דוכתי והא דתנן רבי מאיר אומר שמן תחילה לעולם וחכ״א אף הדבש רבי שמעון שזורי אומר היין פירוש דוקא יין אבל הנך לא ופסקינן בהקומץ רבה דהלכתא כוותיה אומר רבינו תם דהתם מיירי בנקרש ואחר כך נימוח כדמשמע בתוספתא דאמרינן התם במה אמרו שמן תחילה לעולם בנקרש ואחר כך נמוח ובלא נקרש משמע דכולי עלמא מודו וכן משמע בריש פרק שלישי דטהרות דקתני התם הרוטב והגריסין והחלב והשמן בזמן שהם משקה טופח הרי הן תחילה קרשו ואח״כ נימוחו הרי אלו שניים ובתר הכי קתני רמ״א השמן תחילה לעולם והיינו לעולם אפילו קרשו ואהא קאי ר״ש שזורי עכ״ל הרי שהם מסכימים לדעת רבינו.\",1,0],[8,379,1,19,\"וכן הדם שקרש וכו' עד בטלה דעתו. שם:\",2,0],[8,379,1,20,\"חלב שקרש וכו'. גם זה שם לפי גירסת רבינו. והראב\\\"ד שכתב א\\\"א אינו כן אלא אמרו בתוספתא וכו', גירסא אחרת היתה לו בתוספתא:\",1,0],[8,379,1,21,\"דבש תמרים וכו' ושאר כל מי פירות וכו' עד בטלה דעתו. תוספתא פרק שני דטהרות:\",1,0],[8,379,1,22,\"השלג אינו אוכל וכו' עד לא נטמא כולו. תוספתא פרק שני דטהרות ומייתי לה בפרק שני דנדה (דף י\\\"ז) ומקשה היכי משכחת לה דנגעה טומאה בכולו ומוקי לה כגון שהעביר השלג על אויר תנור ושלג בתוכו דנטמא מאויר כלי חרס שהתורה העידה על כלי חרס ואפילו מלא חרדל כלומר שאין נוגעים כל הגרעינין בתנור אפ\\\"ה טמא ולפי זה מה שכתב רבינו העבירו על גבי כלי חרס לא על גביו ממש קאמר אלא באוירו ומ\\\"מ קשה שהיה לו לפרש:\",1,0],[8,379,1,23,\"החלב שבכחל וכו' עד טומאת אוכלים. תוספתא פ\\\"ב דטהרות. כתב הראב\\\"ד מצאתי נוסחאות חלוקות וכו'. ורבינו אע\\\"פ שכתב בפרק תשיעי מהמ\\\"א שחלב הקיבה פירשא בעלמא איכא למימר דכשחשב עליו הוי אוכל לענין טומאה דומיא דשיליא שכתב רבינו בפרק ראשון משאר אבות הטומאה:\",1,0],[8,379,1,24,\"ענבים שדרכן משיהלך בהם וכו'. ירושלמי פ\\\"ו דתרומות ותוספתא פי\\\"א דטהרות.\",1,0],[8,379,1,24,\"ומה שכתב נשתייר בהם גרגרין וכו'. שם בתוספתא:\",2,0],[8,379,1,24,\"וכן הזיתים וכו' עד טומאת אוכלין. שם בתוספתא. וכתב הראב\\\"ד בשאינן פרוצים וכו'. נראה שטעמו לומר דהא דקתני סיפא נשתיירו בהם גרגרים שלמים לא תימא שאף ע\\\"פ שהם פרוצים קצת קרי להו שלמים ומתטמאין טומאת אוכלין דליתא דאינם מתטמאי טומאת אוכלים אלא כשאינם פרוצים כלל שאם הם פרוצים קצת שוב אין עליהם תורת אוכלים ואם תאמר איך אפשר שיטענו ולא יהיו פרוצי' כלל ושני כגון שלא דחקה עליהם הקורה כל הצורך וכו' ולפי זה תיבת אלא צריך למוחקה וצ\\\"ע:\",3,0],[8,379,1,25,\"הערלה וכלאי הכרם וכו'. תוספתא בסוף עוקצין ואיתא בפרק המנחות (דף ק\\\"א) ופ\\\"ק דבכורות (דף ט' ע\\\"ב) ערלה וכלאי הכרם ושור הנסקל ועגלה ערופה וצפורי מצורע ופטר חמור ובשר בחלב כולם מטמאים טומאת אוכלים ר\\\"ש אומר אין מטמאים וידוע דהלכה כת\\\"ק.\",1,0],[8,379,1,25,\"ומ\\\"ש בשור הנסקל שנשחט. כלומר דאי נסקל מטמא טומאה חמורה דנבילה היא. ופטר חמור פירש\\\"י בפרק קמא דבכורות שנשחט ועדיין מפרכס שלא ירד לטומאת נבילה אבל אם נגע בו שרץ מטמא טומאת אוכלין שאם חזר ונגע באוכלים אחרים מטמאים אע\\\"פ שמפרכס כדאמרינן בפרק העור והרוטב.\",2,0],[8,379,1,25,\"ומ״ש ועגלה ערופה בין שנשחטה בין שנערפה. בפרק אותו ואת בנו (חולין דף פ״א ע״ב) תנן דהשוחט פרת חטאת ועגלה ערופה ר״ש פוטר וחכמים מחייבים ובגמרא (דף פ״ב) ועגלה ערופה לאו שחיטה ראויה היא והתנן נמצא ההורג עד שלא תערף העגלה תצא ותרעה בעדר א״ר יוחנן עגלה ערופה אינה משנה ועריפת העגלה מטהרת אותה כמו שחיטה כדאמרינן בס״פ חטאת העוף (זבחים דף ע' ע״ב) מדא״ר ינאי כפרה כתיב בה כקדשים וכי היכי דמליקת קדשים מטהרת מידי נבילה גם עריפת העגלה כן ובמקום שחיטה עומדת וכ״כ רבינו בפ״ג מהל' שאר אבות הטומאה.\",3,0],[8,379,1,25,\"ומ״ש ובשר פרה אדומה. בפרק אותו ואת בנו (חולין פ״א ע״ב) ופרת חטאת שחיטה שאינה ראויה והתניא ר״ש אומר פרה מטמאה טומאת אוכלין הואיל והיה לה שעת הכושר ואמר ר״ל אומר היה ר״ש פרה נפדית ע״ג מערכתה א״ר יוחנן פרת חטאת אינה משנה.\",4,0],[8,379,1,25,\"ומ״ש והפגול והנותר. בפרק המנחות והנסכים (מנחות דף ק״א) אמרינן דלר״ש יש פיגול ונותר שאינו מטמא טומאת אוכלים ולטעמיה אזיל דסבר דאיסורי הנאה אינם מטמאים טומאת אוכלים אבל לרבנן בכל גוונא מטמאים טומאת אוכלים אלא אם כן היה להם שעת הכושר ומה ששנינו בתוספתא דסוף עוקצים פיגול אינו מטמא טומאת אוכלים ר״ש היא ובלא היה לו שעת הכושר ולית הלכתא כוותיה:\",5,0],[8,379,2,1,\"כל האוכלים הגדילים מן הקרקע וכו'. נלמד ממה שיבא בסמוך ובפרק בתרא דעוקצים תבואה שנעקרה ומעורה אפילו בשורש קטן טהורה ומשמע לרבינו דהיינו דוקא כשיכולה לחיות דאל\\\"כ חשיבא כעקורה כדאמרי' גבי ערלה וכדאמרי' גבי הני דבסמוך:\",1,0],[8,379,2,2,\"ייחור של תאנה וכו'. בפרק ב' דעוקצים וכחכמים.\",1,0],[8,379,2,2,\"ומ״ש ויש בדבר ספק וכו'. בפרק העור והרוטב (חולין דף קכ״ח ע״ב) בעיא דלא איפשיטא:\",2,0],[8,379,2,3,\"ירקות שיבשו וכו'. שם עלה קכ\\\"ז ע\\\"ב:\",1,0],[8,379,2,3,\"וכתב הראב\\\"ד ואפילו צמקו כלומר דלישנא דגמרא שצמקו ורבינו נראה דמשמע ליה דהיינו צמקו היינו יבשו דאם לא יבשו אע\\\"פ שצמקו עדיין תורת אוכל עליהם הילכך לישנא דברייתא דנקט צמקו לאו דוקא ושם בגמרא קרי לצמקו יבשו ובתוספתא דטבול יום פרק רביעי איתא להאי ברייתא וכתוב בה שיבשו כלשון רבינו:\",2,0],[8,379,2,4,\"אילן שנפשח וכו'. שם.\",1,0],[8,379,2,4,\"ומ\\\"ש וכן אם יבש האילן וכו'. כתב הראב\\\"ד דבר זה אינו לא במשנה וכו'. ומ\\\"ש אבל אם יבשו בו פירות במחובר הרי הם כמחוברים. תמהני דהא בפרק העור והרוטב אמרינן אליבא דשמואל דכי תניא הרי הן כמחוברין לאו לענין טומאה וממילא משמע דלענין טומאה חשיבי תלושין וכדברי רבינו. ומ\\\"ש ואולי מבכורים גמר לה וכו'. לימוד רחוק הוא זה ועוד דבכורים לא מצאתי יבש האילן אלא יבש המעיין:\",2,0],[8,379,2,5,\"תאנים שיבשו וכו'. בפ' העור והרוטב שם:\",1,0],[8,379,2,6,\"כל האוכלים וכו'. הכי משמע בר״פ העור והרוטב (חולין דף קי״ח) שם ובפ״ג דעוקצים לענין טומאת אוכלין כל שאינה יכולה לחיות מקרי אוכל אע״פ שמפרכסת אע״ג דלגבי טומאת נבילות בעינן שתמות שאני התם דכתיב כי ימות:\",1,0],[8,379,2,6,\"נולד בהם טריפה וכו'. בפרק בהמה המקשה בעיא דלא איפשיטא:\",2,0],[8,379,2,6,\"האבר או הבשר וכו'. משנה ס״פ העור והרוטב (חולין ד' קכ״ט.)\",3,0],[8,379,2,6,\"ומ\\\"ש נשחטה הבהמה וכו'. שם נשחטה הבהמה הוכשרו בדמיה דברי רבי מאיר רבי שמעון אומר לא הוכשרו ופסק כר\\\"מ דמחמיר דבפרק מי שהוציאוהו אסתפק לן ר\\\"מ ור\\\"ש כמאן מינייהו הלכה הלכך נקטינן כדברי המחמיר. ועוד דבעיא דרבא דאיתא בגמרא אתיא אליבא דר\\\"מ וכיון דבעי אליביה משמע דסבר דהלכה כוותיה.\",4,0],[8,379,2,6,\"ומ\\\"ש שהבהמה כולה כמו יד לאבר זה. שם אמרינן הכי לר\\\"מ ופסק כמותו משום דבגמרא בעי בעיא והיא אליביה. וקשה לי למה שינה לשון המשנה שאמרה הוכשרו בדמיה וכתב הוכשרה בשחיטה דאתי כיחידאה דהא תנן בפרק שני דחולין (דף ל\\\"ג) השוחט בהמה חיה ועוף ולא יצא מהם דם כשרים ונאכלים בידים מסואבות וכו' ר\\\"ש אומר הוכשרו בשחיטה ויש לתמוה שהוא ז\\\"ל פסק לקמן בסמוך כת\\\"ק וכאן משמע שפסק כר' שמעון וצריך לומר שסמך על מ\\\"ש בסמוך לקמן בהדיא דתו ליכא למטעי.\",5,0],[8,379,2,6,\"ומה שכתב ויש בדבר זה ספק וכו'. בפרק העור והרוטב עלה קכ\\\"ח בעיא דלא איפשיטא:\",6,0],[8,379,2,7,\"השוחט בהמה חיה ועוף וכו'. משנה פ\\\"ב דחולין שם וכת\\\"ק:\",1,0],[8,379,2,8,\"אוכלים שהוכשרו וכו'. בריש פרק העור והרוטב שם כשם שאין מקבלים טומאה אלא לכשיתלשו כך אין מקבלים הכשר עד שיתלשו ופירש\\\"י כשם שאין זרעים מקבלים טומאה אלא לכשיתלשו כדאמרינן בתורת כהנים אם אתה אומר מחוברים טמאים טימאת את הכל שאין לך מחוברים שאין שרצים מצויים אצלם:\",1,0],[8,379,2,8,\"ומ\\\"ש או כשהוכשרו במים המחוברים בקרקע. בת\\\"כ גבי מים מחוברים יכול אפילו הם בבורות שיחין ומערות יהו מכשירין ת\\\"ל בכלי יטמא ובפרק ד' דמכשירין שנינו צנון שבמערה נדה מדיחתו והוא טהור העלתו כל שהוא מן המים טמא ופירש ר\\\"ש והוא טהור שלא הוכשר בעודו במערה והא דאמרינן בפ\\\"ק דפסחים דמחוברים מכשרי היינו בנתנים על הפירות בעוד המים מחוברים ובלבד שיתלשו לבסוף כמו צנון דהכא שהודח במערה ואח\\\"כ העלתו עכ\\\"ל וכך הם דברי רבינו שם בפיהמ\\\"ש וע\\\"פ זה צריך לפרש דברי רבינו כאן.\",2,0],[8,379,2,8,\"ומ\\\"ש שאב המים בכלי וכו'. הכי משמע בתורת כהנים:\",3,0],[8,379,2,9,\"קישות שנטעה כו'. בסוף פרק ב' דעוקצים קישות שנטעה בעציץ והגדילה ויצאה חוץ לעציץ טהורה ופירש רש\\\"י שנטעה בעציץ שאינו נקוב והוכשרה שם ונטמאת דכתלושה דמיא לכל דבר כדאיתא בשלהי המצניע והגדילה ויצאה חוץ לעציץ ונחשבת כמחובר ופרחה לה טומאה עכ\\\"ל. ובתוספתא שנינו היה משקה בעציץ שאינו נקוב נפלו משקים ע\\\"ג קישות ונטמאת הגדילה ויצאת חוץ לעציץ טהורה:\",1,0],[8,379,2,9,\"כתב הראב\\\"ד אע\\\"פ שיצאת חוץ לעציץ א\\\"א אין כאן אע\\\"פ וכו'. ומתוך דברי רבינו בפי' המשנה וכאן נראה שאינו מפרש כן אלא הכא בקישות טהורה שנטעה בעציץ נקוב עסקי' שכיון שהיא נטועה אינה מקבלת טומאה ואם הגדילה ויצאת חוץ לעציץ סד\\\"א שאותה שיצאה חוץ הויא כתלוש ומקבלת טומאה קמ\\\"ל דאע\\\"פ כן טהורה כלומר אינו מקבל טומאה ולאפוקי מר\\\"ש דפליג התם ואמר מה טיבה ליטהר אלא הטמא בטומאתו והטהור יאכל כלומר מה שיצא לחוץ מקבל טומאה ומה שבתוך העציץ יאכל דאינו מקבל טומאה. ומה שכתב הראב\\\"ד וכן שנויה במשנה לא ידענא מאי קאמר שבמשנה אינו שנוי כיון ואם הכוונה לומר שהוא מוכרח לפרש כן במשנה כיון שאפשר לפרש פירוש אחר במשנה אין פירושו מוכרח. ואפשר שעל התוספתא קאמר שבתוספתא מבואר כפירוש הראב\\\"ד ולדעת רבינו צריך לומר שמה ששנינו בתוספתא דין אחר הוא ואינו ענין לדין המשנה:\",2,0],[8,379,2,9,\"ועציץ שהוא נקוב וכו' עד מכשירין. בסוף פ\\\"ב דעוקצין.\",3,0],[8,379,2,9,\"ומ\\\"ש דעציץ נקוב דינו כארץ גם לענין המים שבתוכו שאינם מכשירים את הזרעים. כן כתב שם רבינו ור\\\"ש:\",4,0],[8,379,2,11,\"ומ\\\"ש כלי גללים וכו'. שם כלי גללים וכלי אדמה שהשרשים יכולים לצאת בהם אינם מכשירין את הזרעים ודברי רבינו בפירושה כאן כפי' ר\\\"ש והראב\\\"ד והוא הנכון ולא כמו שפירש רבינו בפירוש המשנה:\",1,0],[8,379,2,11,\"כתב הראב\\\"ד אני מוצא אפילו בכלי חרס גמור וכו'. אין זו קושיא על רבינו דלישנא דמתניתין נקט ומאי דקשיא ליה להראב\\\"ד מתניתין כבר יישבה הוא עצמו וכתב ואולי יתפרש שם פירוש אחר:\",2,0],[8,379,2,12,\"עציץ שמילאהו עפר וכו'. שם:\",1,0],[8,379,2,13,\"משקים טמאים וכו'. בריש מכשירין.\",1,0],[8,379,2,13,\"ומ\\\"ש והוא שלא יהיו בקרקע. הוא על פי מה שנתבאר לעיל שהמים המחוברים אינם מכשירים בעוד הפירות בתוכן:\",2,0],[8,379,2,14,\"כל אוכל שנפסד. בפ״ג דבכורות עלה כ״ג ע״ב אמרינן דבסרוחה מעיקרא לא צריך קרא למעוטי עפרא בעלמא הוא ומשמע לרבינו דכל שאינו ראוי לאוכל אדם הוי עפרא בעלמא. וכתב הראב״ד מי שלמדהו וכו'. ומה שהביא ראיה מכלל אמרו בטהרות וכו' מה טהור שאינו מקבל טומאה וכו' י״ל שאין היקש זה מוכרח דמידי איריא הא כדאיתא והא כדאיתא ובפירוש אמרו בר״פ דם שחיטה (כריתות דף כ״א) ומחשבה לכלב לאו מחשבה היא והתנן כלל אמרו בטומאה כל המיוחד לאוכל אדם טמא עד שיפסל מאכילת הכלב ההוא לאסוקי טומאה מיניה דכיון דמעיקרא הוה חזי לאדם לאסוקי מטומאה עד שיפסל מאכילת הכלב הכא לאחותי ליה טומאה אי חזי לאדם חזי לכלב אי לא חזי לאדם לא חזי לכלב וזה מבואר כדברי רבינו והרי מימיו מים חיים מן המקדש הם יוצאים. ומה שהביא ראיה ממדרש ספרא י״ל שמה שאמרו אין משקה יוצא לא ע״י פרה ולא ע״י עופות היינו דוקא כשנטמא קודם שנסרח אבל אם נסרח קודם שנפסל מאוכל אדם שוב אינו מקבל טומאה.\",1,0],[8,379,2,14,\"ומה שכתב וכן משקה שנסרח וכו' כדרך שאינו מכשיר שנאמר אשר ישתה. בת\\\"כ ואבארנו בסמוך:\",2,0],[8,379,2,15,\"העור ששלקו וכו'. בר\\\"פ בכל מערבין עלה כ\\\"ח ע\\\"ב ובסוף פרק בהמה המקשה:\",1,0],[8,379,2,16,\"ומה שכתב עור החמור כו'. בסוף פרק בהמה המקשה בעיא דלא איפשיטא.\",1,0],[8,379,2,16,\"ומה שכתב בפני עצמו. משום דתנן העור והרוטב וכו' מצטרפין לטמא טומאת אוכלין והיינו אפילו בלא שליקה ולכך כתב בפני עצמו דכל ששלקו אפילו אין בו בשר מטמא ובעור חמור בהכי מיבעיא לן:\",2,0],[8,379,2,17,\"חטים שבגללי בקר וכו'. תוספתא סוף פ\\\"ח דטהרות אלא שכתוב בנוסחא שבידינו אע\\\"פ שחישב עליהם לאוכלין אינם מטמאים טומאת אוכלין כנסן לאוכלין מטמאין טומאת אוכלין ואנו אין לנו אלא כנוסחת רבינו ונראה שגם זאת נוסחת הראב\\\"ד מאחר שלא השיגו. ובמנחות פ' ר' ישמעאל עלה ס\\\"ט בעי רמי בר חמא חטים שבגללי בקר ושעורים שבגללי בהמה מהו למאי אי לימא לטמא טומאת אוכלים תנינא חטים שברעי בקר ושעורים שבגללי בהמה חישב עליהם לאכילה אין מטמא טומאת אוכלים ליקטן לאכילה מטמא טומאת אוכלין וזה כגירסת תוספתא דידן וצ\\\"ל שגם שם היתה גירסת רבינו משונה משלנו. ואפשר לפרש דברי רבינו ע\\\"פ גירסת התוספתא דה\\\"פ התוספתא כשליקטן סתם אע\\\"פ שאח\\\"כ חישב עליהם אינם מטמאים אבל אם כנסן לאכילה כלומר אם כשליקטן חישב עליהם לאכילה מטמאים.\",1,0],[8,379,2,17,\"ומ\\\"ש ואם חישב עליהם לאכילה. אליקטן קאי כלומר אם כשליקטן חישב עליהם לאכילה מטמאים אבל אם כשליקטן לא חישב עליהם לאכילה אע\\\"פ שאחר כך חישב עליהם אינם מטמאים:\",2,0],[8,379,2,18,\"כל אוכל שנטמא וכו'. בפ\\\"ג דבכורות עלה כ\\\"ג וכר' יוחנן.\",1,0],[8,379,2,18,\"ומה שכתב או שיבש כחרס וכו'. בפרק דם הנדה (נדה דף נ״ה) משמע דיבש כחרס עפרא בעלמא הוא.\",2,0],[8,379,2,18,\"וכל האוכלים שנטמאו וכו'. תוספתא פרק קמא דטבול יום:\",3,0],[8,379,2,19,\"זרעים טמאים שזרעם וכו'. בת״כ פרשת שמיני מנין לזרעים טמאים שזרען טהרו שנאמר אשר יזרע טהור או יכול אפילו לא השרישו ת״ל הוא. ובפרק ב' דמעשרות תנן בצלים משהשרישו בעליה טהרו מלטמא ובירושלמי שם התורה ריבתה בטהרות זרעים מ״ט כי יפול מנבלתם על כל זרע זרוע אשר יזרע טהור הוא ובתרומות פרק תשיעי תנן שתילי תרומה שנטמאו ושתלן טהרו מלטמא ומייתי לה בפרק כל שעה (פסחים דף ל״ד) בלשון קצר ופירש רש״י משום דכיון שחיברה לקרקע בטלה ע״ג קרקע ויצאה מתורת אוכל.\",1,0],[8,379,2,19,\"ומה שכתב אפילו בדבר שזרעו כלה. מההיא דתנן בצלים משהשרישו בעליה טהרו מלטמא ובצלים דבר שאין זרעו כלה הוא כדתנן בפרק בתרא דמעשרות:\",2,0],[8,379,2,20,\"אוכלים שמחוברים לכלים וכו'. בסוף פרק העור והרוטב עלה קכ\\\"ט:\",1,0],[8,379,2,21,\"כל משקה שנטמא וכו'. בת\\\"כ פרשת שמיני ר' אליעזר אומר אשר ישתה פרט למשקה סרוח אמרו לו אין משקים יוצאים ידי עופות ולא ידי פרה ומשמע לרבינו דמה דאמרו לו אינו אלא לומר שאם נטמא ואח\\\"כ נסרח אינו עולה מידי טומאתו ע\\\"י הסרחון אבל אם נסרח קודם שנטמא שוב אין טומאה חלה עליו כדאשכחן באוכלין ור\\\"א סבר שאף אם נטמא ואח\\\"כ נסרח טהור והלכה כאמרו לו. א\\\"נ דאמרו לו סברי דאף אם נסרחה ואח\\\"כ נטמא טמא ור\\\"א פליג עלייהו בהא דכיון שהיה סרוח מקודם לא חלה עליו טומאה והלכה כמותו דמשוה דין משקים לאוכלים משום דאם איתא דסברה גמרא כאמרו לו דמפלגי בינייהו לא הוה שתיק גמרא מלפלוגי בינייהו ודרך זה נראה יותר שהוא דעת רבינו מדכתב לעיל בסמוך דרשא דאשר ישתה כדברי ר\\\"א וכאן שכתב שאין המשקים יוצאים ידי הכלב אע\\\"פ שהם כדברי אמרו לו פירוש דבריו אינו כמו שנתכוונו הם ואשכחן לו ז\\\"ל כיוצא בזה בפרק [א'] מהא\\\"ב גבי שלא ניתנה התראה אלא להבחין בין שוגג למזיד וכמ\\\"ש שם הרב המגיד. ועי\\\"ל דסבר רבינו דאמרו לו לא לחלוק על ר\\\"א באו אלא לפרשם ודייק לשונם שאין משקים יוצאים דמשמע שאין יוצאין מידי טומאתן שהיו טמאים ובאי זה מדרכים אלו נסתלקה השגת הראב\\\"ד שכתב ממדרש ת\\\"כ נראה שאפילו לכתחלה מקבלים טומאה וכו' ויש בקצת ספרי רבינו תיבה יתירה וכך היא הנוסחא הנכונה שאין המשקה יוצא על ידי הכלב לעולם וה\\\"פ שאין המשקה יוצא מידי טומאתו שנטמא והוא טהור על ידי הכלב כלומר כל זמן שהוא ראוי לכלב אע\\\"פ שאינו ראוי לאדם. וכתב הראב\\\"ד ממדרש ת\\\"כ נראה שאפילו לכתחלה מקבלין טומאה וכו' וכבר כתבתי בזה:\",1,0],[8,379,2,21,\"ואין למשקה שנטמא טהרה חוץ מן המים בלבד. [שהמים מיטהרין במקוה] במשנה דפ\\\"ב דביצה (דף י\\\"ז ע\\\"ב) ושאין שאר משקים מיטהרים במקוה בפ\\\"ד דמכשירים ותוספתא פרק קמא דטבול יום:\",2,0],[8,379,2,21,\"ומטבילין חמין בצונן וכו'. כך מצאתי בספרי רבינו המוגהים והוא משנה בפרק בתרא דמקואות וכב\\\"ה:\",3,0],[8,379,2,22,\"מקל שהיא מלאה משקים. כלומר מים טמאים.\",1,0],[8,379,2,22,\"והטביל מקצתה וכו'. בפ\\\"ח דטהרות וכחכמים:\",2,0],[8,379,2,23,\"שלג שנטמא וכו'. תוספתא בפ\\\"ב דטהרות וכנוסחת רבינו שמשון ואיתא בפ\\\"ב דנדה (דף י\\\"ז):\",1,0],[8,379,2,24,\"התמד הטמא וכו'. בספ\\\"ק דחולין (דף כ\\\"ו) וכדאסיק רב גביהא:\",1,0],[8,379,2,25,\"קדירה שמליאה משקים וכו'. בפרק ד' דמכשירין:\",1,0],[8,379,2,25,\"וכתב הראב\\\"ד אע\\\"פ שהיא בתוך המקוה א\\\"א זו הנוסחא עיקר וכו'. נ\\\"ל דאסיפא דמילתא קאי פשט אב הטומאה את ידו וכו'. שנוסחא אחרת יש בקצת ספרי רבינו שכתוב בה שהרי המים חוצצים בתוכה ולכן כתב שנוסחא זו עיקר שאין מי המקוה מטהרים כלי חרס דלאותה גירסא קשה מאי איריא שהמים חוצצים דמשמע שאם לא היו חוצצים היתה טהורה וזה שקר ועוד שאם היה לקדירה טהרה לא היו המים חוצצים:\",2,0],[8,379,2,27,\"מי שפיכות הרי הם בחזקת טומאה וכו' עד והנוטפים מהם טהורים. פ\\\"ב דמכשירין:\",1,0],[8,379,2,27,\"וכתב הראב\\\"ד ממי השפיכות הכל טמא א\\\"א לא ידעתי טעם לזה וכו'. וא\\\"ת שלפי טעם זה אפילו לא נפלו מי שפיכות נמי וי\\\"ל דלא גזרו אלא שיש שם מי שפיכות ופשוט הוא ולטעם רבינו קשה דאדרבא הל\\\"ל כשנפלו מי שפיכות למי גשמים קמא קמא בטיל וכן ברישא הל\\\"ל הכי ונ\\\"ל דהכא שאין מים אלו מכונסים אלא הולכים ונגרים הילכך המים הבאים באחרונה הם שוטפים את הראשונים הילכך בתר בתראי אזלינן ועל דרך ששנוי במשנה:\",2,0],[8,379,2,27,\"ומ\\\"ש ורבו הנטיפות. היינו לומר שהיו הטפות יותר עבות וכדמפרש בתוספתא אליבא דחכמים:\",3,0],[8,379,2,28,\"הסך שמן טהור וכו'. בפרק ד' דעדיות וכב\\\"ה ודברי הראב\\\"ד בפירושו למשנה זו בע\\\"א:\",1,0],[8,379,3,1,\"כבר ביארנו וכו'. בפ\\\"א:\",1,0],[8,379,3,2,\"אוכל שהוא מיוחד לאדם וכו'. בפרק ג' דעוקצין.\",1,0],[8,379,3,2,\"ומה שכתב וכל אוכל שסופו לטמא וכו'. בפרק בא סימן עלה נ״א ובפרק העור והרוטב (חולין דף קכ״א) תנא דבי ר' ישמעאל וכי יותן מים על זרע מה זרעים שאין סופן לטמא טומאה חמורה וכו':\",2,0],[8,379,3,3,\"יש אוכלים שצריכים הכשר וכו'. פ\\\"ג דעוקצים.\",1,0],[8,379,3,3,\"ומ\\\"ש דגים טהורים וחגבים טהורים בכ\\\"מ וחגבים טמאים ודגים טמאים וכו'. תוספתא רפ\\\"ה דטבול יום וצ\\\"ע דבפ\\\"ג דעוקצין תנן דגים טמאים וחגבים טמאים צריכין מחשבה בכפרים ואפשר שרבינו היה גורס במשנה קטנים במקום טמאים וכמ\\\"ש לקמן בסמוך.\",2,0],[8,379,3,3,\"ומ\\\"ש וכן חלב בהמה טהורה שמתה וכו'. בתוספתא פ\\\"ה שם:\",3,0],[8,379,3,3,\"ואלו צריכין מחשבה והכשר וכו' עד והפטריות. בפ\\\"ג דעוצקין ודקדק רבינו לכתוב בשר הפורש מן החי משום דאבר הפורש מן החי מטמא טומאה חמורה ואינו צריך הכשר.\",4,0],[8,379,3,3,\"ומ״ש וחלב בהמה טהורה שחוטה. בשלהי פ' העור והרוטב (חולין דף קכ״ט) כלומר דאילו של נבילה לא בעי מחשבה כמו שנתבאר.\",5,0],[8,379,3,3,\"ומ\\\"ש ושאר ירקות שדה כגון הבצלים הקשים. מדברי רבינו נראה שהוא מפרש מ\\\"ש במשנה ושאר כל ירקות שדה ושמרקעין ופטריות היינו לומר כגון שמרקעין והם הבצלים הקשים ביותר.\",6,0],[8,379,3,3,\"ומ\\\"ש וכן חגבים וכו'. שם דגים טמאים וחגבים טמאים צריכים מחשבה בכפרים וכבר כתבתי שרבינו נראה שגורס קטנים במקום טמאים:\",7,0],[8,379,3,3,\"עולשין שזרען לבהמה וכו'. פרק בא סימן עלה נ':\",8,0],[8,379,3,3,\"עולשין שליקטן לבהמתו וכו'. פרק העור והרוטב עלה קכ\\\"ח:\",9,0],[8,379,3,3,\"האלל אם חשב עליו וכו'. בפרק העור והרוטב (חולין דף קכ״א) אהאי דאמר רבי יהודה האלל המכונס אם יש כזית במקום אחד חייבין עליו וכו' למ״ד דאלל היינו בשר שפלטתו סכין אמרינן ה״ד אי דחשיב עליה אפילו באנפי נפשיה מטמא ופי' רש״י ליטמא טומאת אוכלין דקיימא לן דמחשבה שויא אוכלא כל מידי דמצי למיכליה ואף על גב דלאו אורחיה:\",10,0],[8,379,3,3,\"וכן העצמות המחוברים בבשר וכו'. בר״פ העור והרוטב (חולין דף קי״ז ע״ב) תנן העצמות והגידים והקרנים והטלפים מצטרפין לטמא טומאת אוכלים ובגמרא (דף קכ״א) קרנים אמר ר״פ במקום שחותכים ויוצא מהם דם ובפ״ק דטהרות תנן החרטום והצפרנים מטמאים ומיטמאים ומצטרפים ובפרק העור והרוטב מפרש דה״מ במקום שמובלעים בבשר ופירש״י דלענין טומאת אוכלין קאמר ובפרק קמא דטהרות תנן תו הכנפים מטמאים ומיטמאים ומשמע לרבינו דעצמות דקתני היינו במחוברים בבשר שהם ראויים לאכול קצת דומיא דמאי דאמרינן דקרנים וחרטום וצפרנים ודלא כפירוש רש״י:\",11,0],[8,379,3,3,\"ואלו שאין צריכין לא מחשבה ולא הכשר וכו'. בפ\\\"ג דעוקצים נבלת בהמה טהורה בכ\\\"מ ונבלת העוף הטהור והחלב בשוקים אינם צריכים לא מחשבה ולא הכשר ומ\\\"כ בחלב בהמה טהורה שחוטה מיירי וכך היא הנוסחא האמיתית בספרי רבינו וכן פירש ר\\\"ש וכן פירש\\\"י והתוספות בפ\\\"ק דבכורות ופרק בא סימן והטעם שנתן רבינו מפני שסופן לטמא אדם וכלים לא קאי אלא אשארא דאילו חלב טהורה אפילו של נבילה אינו מטמא טומאה חמורה וטעמא דחלב משום דבכרכים עם רב ואוכלים אותו ואיתא מחשבה בסתם ואיתא הכשר בשחיטה:\",12,0],[8,379,3,3,\"ואלו צריכין מחשבה ואינם צריכים הכשר וכו'. שם.\",13,0],[8,379,3,3,\"ומה שכתב והוא שחשב על פחות מכזית. כתב כן משום דקשיא ליה נבלת בהמה טומאת אוכלים למה לי הא מטמאה אדם וכלים ולפיכך כתב דהב״ע בשחשב על פחות מכזית כדאמרינן בפרק דם שחיטה (כריתות דף כ״א) דאי איכא פחות מכזית דאין עליו טומאת נבלות וצרפו לפחות מכביצה אוכלים אם חישב על פחות מכזית זה לאכילה מצטרף עם אוכלים להשלימו לכביצה לטמא טומאת אוכלים ופריך א״ה ליבעי נמי הכשר שהרי פחות מכזית אין סופו לטמא טומאה חמורה ומשני דלא בעי הכשר אלא באוכלים שאין בהם צד טומאה חמורה אבל פחות מכזית זה כיון דהוי נבילה ואינו מצטרף לכזית מטמא טומאה חמורה אין צריך הכשר:\",14,0],[8,379,3,4,\"ישראל ששחט בהמה טמאה לנכרי וכו'. משנה ר״פ העור והרוטב (חולין דף קי״ז ע״ב) השוחט בהמה טמאה לנכרי והיא מפרכסת מטמאה טומאת אוכלים ובגמרא (דף קכ״א) אמר ר' אסי שונים ישראל בטמאה ונכרי בטהורה צריכים מחשבה והכשר מים ממקום אחר הכשר מים למה לי סופו לטמא טומאה חמורה וכל שסופו לטמא טומאה חמורה לא בעי הכשר וכו' אמר חזקיה הואיל ויכול לגורדה ולהעמידה על פחות מכזית ופירש״י אמר חזקיה שאני מתניתין דבמפרכסת קיימינן וכו' ויש לתמוה למה פסק רבינו שאינה צריכה הכשר ואפשר לומר דסבר דהא פליגא אההיא דפרק דם שחיטה שכתבתי בסמוך דאע״ג דלא הוי כזית מיקרי סופו לטמא טומאה חמורה הואיל וחזי לאצטרופי וכההיא קי״ל דסתם גמרא קאמר לה:\",1,0],[8,379,3,4,\"שחט בה אחד או נחרה וכו'. שם ופירש\\\"י שחט בה אחד אינה מטמאה טומאת אוכלים דלא אשכחן היתר אכילה בדכוותה לא לישראל ולא לבני נח וכן בנחרה ועודה מפרכסת:\",2,0],[8,379,3,4,\"וכן עכו\\\"ם ששחט וכו' שחט בה אחד וכו'. שם ופירש\\\"י מטמא טומאת אוכלים וכו'. והראב\\\"ד כתב א\\\"א יש לנו קושיא בזה וכו'. אין כאן השגה על רבינו דרבינו לישנא דברייתא נקט ומ\\\"מ לענין קושייתו אפשר לומר שהטעם משום הואיל עכו\\\"ם בטהורה הואיל וטהורה היא ואית בה שם שחיטה בעלמא הויא אוכל אבל כי נחרה לא שייך בה הואיל וכן ישראל בטמאה נמי כיון דשחט ואית בה שם שחיטה עביד לה אוכל אבל כי נחרה אין כאן שם שחיטה וה\\\"ה נמי היכא דשהא בה או דרס בה או איכא פגימת הסכין דלא מטמאה טומאת אוכלים כיון דלית בה שם שחיטה:\",3,0],[8,379,3,5,\"החותך בשר מאבר מן החי וכו'. בפרק העור והרוטב (חולין דף קכ״ח ע״ב) ת״ר החותך כזית בשר מאבר מן החי חתכו ואח״כ חישב עליו טהור חישב עליו ואח״כ חתכו טמא וכו' א״ל ר' אסי לרבי זירא טומאת בית הסתרים היא וטומאת בית הסתרים לא מטמא א״ל וכו' שאילתיה לר' אבא בר ממל וא״ל הא מני ר״מ היא דאמר טומאת בית הסתרים מטמאה א״ל ולאו זימנין סגיאין אמרה קמאי ואמרי ליה שאני לר״מ בין טומאה דבעיא הכשר לטומאה דלא בעיא הכשר אמר רבא ומאי קושיא דילמא בשהוכשר א״ל רבא בר רב חנן לרבא למה לי הכשר הרי מטמא טומאה חמורה אגב אביו א״ל כששימש מעשה עץ שימש ופירש״י החותך כזית בשר מאבר מן החי בתוספתא לא גרסינן כזית אלא בשר מאבר מן החי וכגון דאיכא כביצה. חתכו ואח״כ חישב עליו להאכילו לנכרי. טהור דהא בשר הפורש מאבר מן החי טהור הילכך טומאת עצמו אין בו ומשחישב עליו לא נגע בטומאה שיקבלנה אבל חישב עליו והורידו באביו באבר לתורת אוכל ואח״כ חתכו קיבל טומאה מאביו קודם לכן מטומאה חמורה שהיתה עליו בעודו אבר שלם כשחתכו והלכה לה טומאה חמורה נשארה עליו הקלה שלא היתה בו עד עתה וכו'. טומאת בית הסתרים וכו' בשהוכשר קודם חתיכה קתני הך ברייתא דטמאה. הרי מטמא טומאה חמורה אגב אביו בעודו מחובר באבר היה אב הטומאה לטמא אדם וכלים ותנא דבי רבי ישמעאל וכו' מה זרעים וכו' וכל שכן זה שכבר טמא. כששימש אותו שימוש טומאה חמורה לאו בתורת אוכל שמשה שאין האבר מטמא כלום על ידי אותו בשר אלא בתורת עץ שימש שנחשב עם הגידים והעצמות ליעשות אבר והם כעץ והשתא אתעביד ליה אוכל ופנים חדשות באו לכאן עכ״ל:\",1,0],[8,379,3,5,\"וכתב הראב״ד טעה בכל זה וכו'. ואני אומר שעם היות כי באמת קושיותיו על רבינו חזקות אין לחשדו שתפס התוספתא שמצא ונעלמו ממנו דברי הגמרא או לא חשש להם ולכן נראה לי שליישב דעת רבינו יש לומר דסבירא ליה כדאמר ליה רבא בר רב חנן לרבא למה לי הכשר הרי מטמא טומאה חמורה אגב אביו ואם כן אין צריך לאוקומה כרבי מאיר דכרבי עקיבא אתיא דכיון דמטמא טומאה חמורה אגב אביו אין צריך לא הכשר מים ולא הכשר שרץ כדאמרינן בפרק בא סימן ורבא בר רב חנן כי אמר ליה לרבא למה לי הכשר ה״מ למימר ליה למה לי לאוקמה כרבי מאיר אלא דבעא לאקשויי ליה למאי דאוקי לה רבא גופיה בשהוכשר וממילא משמע דלא צריכין לאוקמי כרבי מאיר אלא דלא נחת אלא לאקשויי ליה למאי דאוקי בשהוכשר ואף על גב דשני ליה רבא כששימש מעשה עץ שימש שינויא בעלמא הוא ולא סמכינן עליה ואף על גב דשתיק ליה רבא ב״ר חנן לאו משום דקיבלה מיניה אלא משום דלמאי דאקשי ליה שינויא הוא ואף על גב דמשמע התם דאביי ור״פ ורב מתנא סבירא להו כהאי שינויא דכששימש מעשה עץ שימש איכא למימר דלשינויא דשני רבא קאמרי ולהו לא ס״ל ואפילו את״ל דס״ל כהנהו מילי כששימש מעשה עץ שימש לא דמי האי מעשה עץ להנהו דהנהו לומר דנתבטל מתורת אוכל ונעשה כעץ אבל האי שימש מעשה עץ אינו כן אלא היינו לומר שאין האבר מטמא על ידי אותו בשר אלא שנחשב עם הגידים והעצמות ליחשב אבר והן כעץ והשתא אתעביד ליה אוכל ופנים חדשות באו לכאן וכדפי' רש״י והשתא כיון דלא מיקרי אבר אלא כשהוא בשר וגידים ועצמות אם כן שפיר אמרינן שהאבר מטמא על ידי אותו בשר ולמה שפירשו התוספות כששימש מעשה עץ שימש היינו לומר דמאותו השם שהיה מטמא טומאה חמורה דהיינו משום אבר מן החי עתה אין אבר מן החי שאין בו אלא בשר ואינו קרוי אבר ולא דמי לנבלת עוף טהור ופרים הנשרפים שכשטימא טומאה חמורה היה משום שורף פרים והשתא נמי הם פרים וה״פ כששימש מעשה עץ לא מתורת אוכל כמו שהוא עתה אלא מתורת עץ בעלמא עכ״ל. הרי דלא קרי ליה מעשה עץ אלא משום דלא היה טומאתו משום אוכל אלא משום אבר הרי שאין זה דומה לשאר מעשה עץ האמורים שם ועוד דבהנך הטומאה חמורה היא בסוף ובזו הטומאה חמורה היא בתחלה ונראה שזהו מה שאמרו בפרק בהמה המקשה (חולין דף ע״ב ע״ב) אמאי טומאת בית הסתרים היא וטומאת בית הסתרים לא מטמא לימא רבי מאיר לטעמיה דתנן ג' על ג' שנחלקו טהור מן המדרס אבל טמא מגע מדרס דברי רבי מאיר וכו' לאו איתמר עלה אמר עולא לא שנו אלא ג' על ג' שנחלק אבל ג' על ג' הבאות מבגד גדול בשעת פרישתן מאביהן מקבלות טומאה מאביהם ולפי זה ברייתא דהחותך בשר מאבר מן החי אתיא כרבי עקיבא ולפי זה הנך רבנן דאוקמוה כרבי מאיר לא הוה שמיע להו דעולא דאמר ל״ש אלא ג' על ג' שנחלק וכו' אבל אנן דשמיע לן נקטינן כוותיה ואתיא ברייתא כר״ע ואע״פ שהרשב״א כתב בשם התוספות בפרק העור והרוטב דהכא לא מצי למימר דבשעת פרישתן מקבלות טומאה מאביהן א״נ אוכלין כמאן דמפרשי דמו דמיירי כגון שלא היה בו יותר בשר ואין עליו שוב דין אבר מן החי עכ״ל הדבר מבואר כמה יש בזה מהדוחק ומוטב לומר דלא הוה שמיע להו ההיא דעולא ודרבינא ומכל אילין טעמי דלעיל סבר רבינו דמתניתין כר״ע והלכתא כוותיה:\",2,0],[8,379,3,5,\"ומה שכתב וכל המטמא טומאה חמורה אינו צריך הכשר. בפרק ג' דעוקצין חלב בהמה טהורה אינו מטמא טומאת נבילה לפיכך הוא צריך הכשר חלב בהמה טמאה מטמא טומאת נבילה לפיכך אינו צריך הכשר:\",3,0],[8,379,3,8,\"פחות מכזית מנבלת בהמה טמאה וכו' עד הכל מתטמא טומאה חמורה. בריש פרק דם שחיטה (דף כ\\\"ח) ופסק כשתי האוקימתות משום דס\\\"ל דלא פליגי וכן משמע לשון רב חנניא שאמר אפילו תימא כזית כגון שחיפהו בבצק משמע בהדיא דלא פליג אאוקימתא דרבי חייא ואע\\\"פ שבתוספות הוקשה להם על זה דא\\\"כ למה הוצרך לומר דמשום דמטמא טומאת משא הוא דמיבעי הכשר לישני דכיון דאם מסיר הבצק מטמא טומאה חמורה דומיא דמאי דאמר ר' חייא כיון דאי מצרף ליה וכו' י\\\"ל דאי הוה אמר הכי הוה קשה לן מאי איריא אם מסלק הבצק הא בבצק נמי איכא טומאה חמורה להכי נקט טעמא דקושטא דהשתא נמי טומאה חמורה יש בו ורבי חייא פשיטא דסבר לדרב חנניא דכ\\\"ש הוא:\",1,0],[8,379,3,8,\"וכתב הראב\\\"ד הכל צריך מחשבה א\\\"א מגמרא דכריתות נראה וכו'. ואני אומר שאין זה מוכרח ויש מקום לפירוש רבינו:\",2,0],[8,379,3,9,\"החותך בשר וכו'. כתב הראב״ד ואינו צריך הכשר א״א זה שיבוש שצריך הכשר וכו'. ביאור הדברים דתנן בפרק ג' דעוקצין החותך מן האדם כלומר מן האדם החי צריך מחשבה והכשר ע״כ השיג על רבינו שכתב שאינו צריך הכשר ולדעת רבינו י״ל דרבינו איירי בשחתכו להאכילו לכלב ומש״ה אינו צריך הכשר וכך מפורש בפרק דם שחיטה (כריתות דף כ״א) אמר מר אוציא דם מהלכי שתים שיש בהם טומאה חמורה ואין בהם טומאה קלה ורמינהי החותך מן האדם מן החי צריך מחשבה ואין צריך הכשר וק״ל מחשבה למה לי תעשה חתיכה שלו מחשבה ואמר ר״ל בחותכו לכלב ומחשבה לכלב לאו מחשבה היא והתנן כלל אמרו בטומאה כל המיוחד לאוכל אדם טמא עד שיפסל מאכילת כלב ההוא לאסוקי טומאה מיניה דכיון דמעיקרא הוה חזי לאדם לאסוקי מטומאה עד שיפסל מאכילת כלב הכא לאחותי לה טומאה אי חזי לאדם חזי לכלב אי לא חזי לאדם לא חזי לכלב ע״כ בגמרא וע״פ הדברים האלה הוכרח רבינו לפרש דהא דתנן בפרק ג' דעוצקין החותך מן האדם צריך מחשבה והכשר לאו בחותך לאדם היא דהא ההיא אינה צריכה מחשבה וכן ליכא לאוקומה בחותך לכלב דההיא אינה צריכה הכשר כמבואר בגמרא שכתבתי בסמוך וכן אין לאוקומה בשחתכה סתם לא לאדם ולא לכלב דלאו בשופטני עסקינן שאין להם במעשיהם כוונה לשום דבר הילכך ע״כ לומר דלישנא דחותך לאו דוקא אלא לומר שנחתך שלא על ידי אדם וזהו שכתב רש״י גבי צריכים מחשבה והכשר בשר הפורש מן החי מן האדם ולא כתב חותך אלא כתב פורש במקום חותך. ולשון רבינו שכתב אם חישב עליו למאכל אדם צריך מחשבה אינו נוח וצריך לפרש דה״ק אם חישב עליו למאכל אדם צריכה מחשבה זו ועל מה שסיים הראב״ד וחתיכתו לאדם זו היא מחשבתו יש לתמוה דרבינו לא איירי בחותך לאדם אלא בחותך לכלב ואח״כ חישב עליו לאדם:\",1,0],[8,379,3,10,\"גוזל שנפל לגת וכו'. בפרק קמא דטהרות גוזל שנפל לגת וחישב עליו להעלותו לעכו\\\"ם טמא לכלב טהור רבי יוחנן בן נורי מטמא ובפרק בא סימן עלה נ' במאי עסקינן אילימא בכרכים למה לה מחשבה והתנן וכו' נבלת עוף טהור והחלב בכרכים אין צריך לא מחשבה ולא הכשר אלא בכפרים ומי איכא למאן דאמר דלא בעי מחשבה והא תנן וכו' נבלת עוף טהור בכפרים צריכה מחשבה ואינה צריכה הכשר אמר רבי חנינא לעולם בכרך וגתו מאסתו ועשאו ככפר.\",1,0],[8,379,3,10,\"ומה שכתב חישב עליו להאכילו לכלב וכו'. שם פרק שמיני דטהרות:\",2,0],[8,379,4,1,\"כמה שיעור אוכלין לטומאה וכו'. בת\\\"כ מכל האוכל מלמד שמטמא בכל שהוא יכול יטמא לאחרים בכל שהוא ת\\\"ל אשר יאכל אוכל הנאכל והיינו כביצה. וכתבו רש\\\"י בפרק כל שעה עלה ל\\\"ג והתוספות חלקו עליו שם וכתבו שגם רש\\\"י חזר בו בפרק אותו ואת בנו וגם שם בפרק כל שעה כתב בסוף דבריו ואני שמעתי דאף לקבל טומאה בעי כביצה מ\\\"מ דעת רבינו הוא כפשטא דההיא דת\\\"כ:\",1,0],[8,379,4,1,\"ואין אוכל מטמא וכו'. בפרק יום הכיפורים (דף פ') טומאת אוכלים בכביצה ומייתי לה מקרא ובפרק כיצד משתתפין עלה פ\\\"ג גבי טומאת אוכלים תניא רבי נתן ורבי דוסא אמרו כביצה שאמרו כמוה ובקליפתה וחכמים אומרים כמוה בלא קליפתה וידוע דהלכה כחכמים:\",2,0],[8,379,4,1,\"וכן האוכל אוכלים טמאים וכו'. משנה פרק כיצד משתתפין (עירובין דף פ״ב פ״ג) וכר״י בן ברוקא שהזכירוהו שם בברייתא בלשון חכמים אומרים:\",3,0],[8,379,4,2,\"המשקין מתטמאין כל שהן ומטמאין בכל שהן וכו'. בפרק כל שעה עלה י\\\"ד אהא דאמרינן הב\\\"ע דאיכא משקים בהדי בשר כתבו התוספות מכאן מדקדק ריב\\\"א דמשקים מטמאים בפחות מרביעית דסתם משקין דבהדי בשר לית בהו רביעית ולקמן נמי אמרינן גבי מים אבל פחות מרביעית טמאים והא דאמרינן בפרק ב' דע\\\"ז (דף ל\\\"ו) גבי יין נסך דמטמא טומאת משקין ברביעית ובפ' שני דנדה (דף י\\\"ט) גבי דם הירוק ובכמה דוכתי אומר ריב\\\"א דבפסול גוייה איירי דשיעורו ברביעית כדתנן בפרק רביעי דמעילה (דף י\\\"ז):\",1,0],[8,379,4,3,\"כל המשקים מצטרפין וכו' וכל האוכלים מצטרפין וכו'. משנה פ\\\"ד דמעילה:\",1,0],[8,379,4,4,\"העור המחובר בבשר. משנה ר״פ העור והרוטב (חולין דף קי״ז ע״ב) העור והרוטב והקיפה והאלל והעצמות והגידים והקרניים והטלפיים מצטרפין לטמא טומאת אוכלים ופירש״י העור כגון פחות מכביצה בשר ועורה אדוק בה משלימו לכביצה מצטרף מפני שהוא שומר ובגמרא (דף ק״כ) מאי רוטב אמר רבא שומנא א״ל אביי הוא עצמו יטמא טומאת אוכלין אלא חלב דקריש וכו' אי קריש מצטרף ואי לא קריש לא מצטרף. ופירש״י חלב דקריש ליחה היוצאה מן הבשר ואיני יודע למה סתם רבינו והמרק ולא התנה שיהיה קרוש כדאמרינן בגמרא.\",1,0],[8,379,4,4,\"ומ\\\"ש רבינו והתבלין. הוא פירוש קיפה וכר\\\"פ דמסיק הכי וכל הני דתנן היינו להצטרף עם הבשר כדפירש\\\"י:\",2,0],[8,379,4,4,\"ואמרינן תו בגמרא (דף קכ\\\"א) מאי אלל ר\\\"י אמר מרטקא ופירש\\\"י גיד השדרה והצואר והוא רחב ולבן וקשה מאד ור\\\"ל אמר בשר שפלטתו סכין אבל מרטקא לא מצטרף ור\\\"י סבר מרטקא נמי מצטרף ויש לתמוה על רבינו למה לא פירש דמרטקא נמי מצטרף כר\\\"י וי\\\"ל שסמך על מ\\\"ש והגידים דכל גידים במשמע:\",3,0],[8,379,4,4,\"ואמרינן תו בגמרא האי בשר שפלטתו סכין היכי דמי אי דחשיב עליה אפילו באנפי נפשיה מטמא ואי דלא חשיב עליה בטולי בטליה ר' אבין ור' מיאשא חד אמר מקצתו חישב עליו וחד אמר מקצתו פלטתו חיה ומקצתו פלטתו סכין ומשמע דמר אמר חדא ומר אמר חדא ולענין דינא לא פליגי:\",4,0],[8,379,4,4,\"ואמרינן תו בגמרא תנן התם (בפ\\\"ק דטהרות) החרטום והצפרניים מיטמאין ומטמאין ומצטרפין חרטום עץ בעלמא הוא אר\\\"א בחרטום תחתון תחתון נמי עץ בעלמא הוא אר\\\"פ תחתון של עליון. צפרניים א\\\"ר אלעזר מקום המובלעים בבשר. קרניים אמר ר\\\"פ מקום שחותכין ויוצא מהם דם.\",5,0],[8,379,4,4,\"ומ\\\"ש והכנפיים והנוצה. בפ\\\"ק דטהרות תנן הכנפיים והנוצה מתטמאות ומטמאות ולא מצטרפות ומדברי רבי' נראה שהיה גורס ומצטרפות:\",6,0],[8,379,4,6,\"כביצה אוכלים טמאים וכו' עד חזרו לכמות שהיו. בפרק ג' דטהרות ובפ\\\"ד מהלכות שאר אבות הטומאה נתבאר דין זה יפה בדברי רבינו ורבינו קיצר כאן וסמך על מ\\\"ש שם:\",1,0],[8,379,4,9,\"עלי בצלים וכו'. בפרק ב' דעוקצין:\",1,0],[8,379,4,9,\"פת סופגנין וכו'. שם:\",2,0],[8,379,4,9,\"בשר העגל וכו'. בפ\\\"ב דעוקצין:\",3,0],[8,379,4,10,\"האגוז והתמרים וכו'. תוספתא פרק רביעי דטבול יום ופירשה ר\\\"ש שם בפרק ב':\",1,0],[8,379,4,16,\"כל שטומאתו ושיעורו שוים וכו' עד מצטרפין לטמא כקל שבשניהם. משנה בפרק ד' דמעילה (דף י\\\"ז).\",1,0],[8,379,4,16,\"ומה שכתב שאם לא היו שוים לא בשיעור ולא בטומאה כגון בשר הנבילה ובשר השרץ. כלומר דנבילה מטמאה אף במשא ושרץ אינו מטמא אלא במגע:\",2,0],[8,379,4,16,\"ומה שכתב כיצד כחצי ביצה וכו' עד סוף הפרק. בפירקא קמא דטהרות:\",3,0],[8,379,5,1,\"ידות האוכלים וכו'. בפ\\\"א דעוקצין:\",1,0],[8,379,5,2,\"כל שהוא יד ואינו שומר וכו'. בריש פ\\\"א דעוקצין:\",1,0],[8,379,5,3,\"כשם שיד לטומאה כך יד להכשר וכו'. בריש פרק העור והרוטב (חולין דף קי״ז קי״ח) וכר״י:\",1,0],[8,379,5,3,\"ויש יד לפחות מכזית ויש שומר לפחות מכפול. שם (קי\\\"ח ע\\\"ב) אמר רב אין יד לפחות לכזית ואין שומר לפחות מכפול ור\\\"י אמר יש יד לפחות מכזית ויש שומר לפחות מכפול וידוע דהלכה כר\\\"י ופירש\\\"י אין יד לפחות מכזית וכו' ונגעה טומאה ביד הואיל ואין עיקרו כזית וכו':\",2,0],[8,379,5,3,\"ושומר שחלקו אינו מצטרף עם האוכל. בא\\\"פ העור והרוטב עלה קי\\\"ט:\",3,0],[8,379,5,4,\"ומנין לשומרי אוכלים וכו'. שם (דף קי\\\"ז:):\",1,0],[8,379,5,5,\"ומנין לידות האוכלין וכו'. בר״פ העור והרוטב (חולין דף קי״ח):\",1,0],[8,379,5,6,\"הבוצר לגת וכו'. בפ\\\"ק דסוכה עלה י\\\"ג ע\\\"ב וכתוב בספרים מפני שמוציא את המשקה וט\\\"ס הוא וצריך למחוק תיבת שמוציא ולכתוב במקומו שמוצץ וכך מצאתי בספר מוגה והוא לשון הגמרא דלא ניחא ליה דלא נמצייה לחמריה ופירש\\\"י מוצצות את היין ומפסידות:\",1,0],[8,379,5,7,\"הקוצר לסיכוך וכו'. שם פלוגתא דאמוראי ופסק כמאן דמיקל וצריך טעם למה. וכתב הר\\\"י קורקוס דטעמא משום דלמאי דבעי לאוקומי דרב מנשיא כתנאי מיתוקם כת\\\"ק וטענה חלושה היא.\",1,0],[8,379,5,7,\"ומ\\\"ש שהרי אינו צריך ליד. כלומר שא\\\"צ שיהיה יד לאוכל כיון שאין צריך לאוכל:\",2,0],[8,379,5,8,\"כל ידות האוכלין שבססן בגורן טהורים. בפ\\\"ק דעוקצים וכת\\\"ק ומייתי לה בפ\\\"ק דסוכה עלה י\\\"ד:\",1,0],[8,379,5,9,\"פסיגה של אשכול וכו' וכן שרביט תמרה וכו' וכן שרביט קטניות וכו'. בפרק קמא דעוקצין שם:\",1,0],[8,379,5,10,\"לעולם אין שומר על גבי שומר וכו'. בריש פרק העור והרוטב עלה קי\\\"ט:\",1,0],[8,379,5,11,\"שלש קליפות בבצל וכו'. בפ״ב דעוקצין ואע״ג דר' יהודה קאמר לה פסק רבינו כוותיה משום דבר״פ העור והרוטב (חולין דף קי״ט ע״ב) מייתי ראיה מיניה א״נ שסובר רבינו דר״י הוא מפרש דברי ת״ק:\",1,0],[8,379,5,12,\"כל הקליפין מתטמאות וכו'. בפרק שני דעוקצין:\",1,0],[8,379,5,12,\"קליפי פולין ותורמסין וכו' קליפת מלפפון וכו'. תוספתא בפרק רביעי דטבול יום:\",2,0],[8,379,5,12,\"השעורים בזמן שהם יבשים וכו'. מנחות פ' ר' ישמעאל (מנחות דף ע' ע״ב) חטה בין קלופה בין שאינה קלופה מצטרפת שעורה קלופה מצטרפת שאינה קלופה אינה מצטרפת ומקשה עליו מדתנא דבי רבי ישמעאל על כל זרע זרוע אשר יזרע כדרך שבני אדם מוציאין לזריעה חטה בקליפתה ושעורה בקליפתה וכו' ותירצו הא בלחות הא ביבשות ומפרש רבינו דיבשות מצטרפות שכך דרך להוציא לזריעה יבשות ולחות אין מצטרפות ודלא כפירש״י:\",3,0],[8,379,5,15,\"כל הגרעינין מתטמאות וכו' עד כל שכנגד הבשר מצטרף. פרק שני דעוקצין:\",1,0],[8,379,5,15,\"וכתב הראב\\\"ד חוץ מגרעינות הרוטב א\\\"א לשון המשנה גרעינה של רוטב אע\\\"פ שיוצאת מצטרפת עכ\\\"ל. כלומר משיג על רבינו שלא ה\\\"ל לסתום דבריו אלא לפרש אע\\\"פ שיוצאת מצטרפת ואני אומר שמתוך דבריו של רבינו מתבארים הדברים שמה שכתב חוץ מגרעינת הרוטב קאי למאי דסמיך ליה דקתני ולא מצטרפות ולא הוצרך לכתוב אע\\\"פ שיוצאת דמדסתים לה סתומי ממילא משמע דבכל גווני מצטרפת אע\\\"פ שיוצאת:\",2,0],[8,379,5,15,\"כתב עוד הראב\\\"ד החותל של גרעינה א\\\"א אינו נראה כן מן המשנה וכו'. ומ\\\"ש שלשון של המשנה חותל של תמרה רוטב ועל פי לשון זה טרח לפרש שהוא קליפה או עלה שעל התמרה אני אומר שנוסחא משובשת נזדמנה לו במשנה ונוסחא דידן גרעינה של רוטב אף ע\\\"פ שיוצאת מצטרפת ושל יבשה אינה מצטרפת לפיכך חותל של יבשה מצטרף ושל רוטב אינו מצטרף ופירש רבינו שם חותל לפוף כמו והחתל לא חותלת ופירוש רוטב תמרה לחה וכן נקרא בערבי וכל הגרעינין של פירות היבשים הם יד ולא שומר ולכך אין מצטרפין אמנם של רוטב הוא שומר כי אם תוסר הגרעין תתחלחל התמרה הלחה ותפסד כי הגרעינה הוא המעמידה והמקיימה כראוי ולכך מצטרף כדין כל שומר אבל היבשה אף אם תוסר הגרעין לא תפסד התמרה כלל ולכך אינו שומר ואינו כדין יד ופירוש חותל הוא קרום דק של התמרה וכשהתמרה לחה אותו הקרום אינו שומר כלל רק הגרעין הוא השומר ואותו הקרום הוא נפרד מעצם התמרה הלחה אמנם כשהתמרה יבשה אותו הקרום דבוק בעצם התמרה והוא שומר לה לא הגרעין ואילו יוסר הגרעין ונשאר הקרום לא תפסד התמרה ולכך הקרום מצטרף והגרעין אינו מצטרף. ועל מה שפירש הראב\\\"ד שהוא קליפה או עלה שעל התמרה הוא דבר תימה שלא מצינו לתמרה עלה או קליפה שיזרקו אותה גם מה שעלה בדעתו לפרש שהוא כיס מבגד או מחריות כבר דחהו הוא ז\\\"ל בעצמו הילכך נוסחת רבינו ופירושו עיקר:\",3,0],[8,379,5,15,\"כתב הראב\\\"ד גרעינה של רוטב א\\\"א כל זה שיבוש וכו'. ואיני יודע מה שיבוש יש כאן מאחר שרבינו העתיק לשון המשנה ומה שיתפרש בלשון המשנה יתפרש בדבריו. ומ\\\"ש ולפ\\\"ז התוספתא מה שאמרה המשנה גרעינה שמקצתה יוצאת וכו' אפשר לומר שרבינו סובר שאין זה דיוק דאף אם התמרה קיימת אינו מצטרף מה שיוצא והתוספתא דקתני הנאכל חציו אורחא דמילתא נקט ולאו דוקא. ומ\\\"ש כמו שכתבתי למעלה איני רואה היכן כתב כן ובספר כ\\\"י נמצא כמו שכתב למעלה וגם זה אינו מתיישב שרבינו לא כתב כן והר\\\"י קורקוס ז\\\"ל כתב נראה שהכוונה כמו שהוזכר ברישא דמתניתין דהיינו מאי דקתני אע\\\"פ שיוצא מצטרף דמשמע אפילו היוצא עצמו מצטרף ומיירי ע\\\"כ בתמרה קיימת וסיפא בנאכלת עכ\\\"ל.\",4,0],[8,379,5,15,\"ומ\\\"ש היה עליו הבשר מצד אחד וכו'. שם היה עליו הבשר מצד אחד ר' ישמעאל אומר רואין אותו כאילו מקיפו בטבעת וחכ\\\"א שכנגד האוכל מצטרף כגון הסיאה והאזוב והקורנית ופי' שם רבינו דברי חכמים אנו רואים כאילו כבר נחתך מה שתחת הבשר יצטרף כל מה שתחת הבשר לבשר אע\\\"פ שהבשר אינו סובב בעצם אנו רואים אותו שכבר סר עד שלא ישאר מגוף העצם אלא שיעור דק מדובק בבשר כדקות שבט האזוב אשר עם דקותו כבר מצאנוהו שומר למה שעליו מן העלין עכ\\\"ל.\",5,0],[8,379,5,15,\"ומ\\\"ש רבינו אינו מצטרף אלא העצם שתחת הבשר עד חלל העצם. תוספתא רפ\\\"ד דטבול יום:\",6,0],[8,379,5,15,\"כתב הראב״ד ושאר העצם אין מצטרף א״א כל זה שיבוש וכו'. דעתו ז״ל שכל החכמים שנזכרו בתוספתא כולם בחדא מילתא פליגי ואין כאן דעת רבינו אלא פלוגתא דר' יהודה וחכמים דסיפא פלוגתא באפי נפשה היא ולא לאפלוגי את״ק אתו ופשטא דתוספתא הכי מוכחא ולהראב״ד דשביק מתניתין ועביד כברייתא קשה איך כתב שהם כדברי יחידים והם סתם וחכמים וגם רישא דתוספתא סתמא היא ואדרבה דברי אותם חכמים דתוספתא תני להו בפרק העור והרוטב (חולין דף קי״ט) בלשון אחרים אומרים:\",7,0],[8,379,5,16,\"קולית שהיה עליו בשר וכו'. שם בתוספתא וכחכמים ומייתי לה בפרק העור והרוטב וכבר כתבתי בסמוך דפלוגתא באנפי נפשה היא דפליגי ר\\\"י וחכמים דפליגי בקולית שיש עליה בשר והלכה כחכמים:\",1,0],[8,379,5,18,\"גרעיני זיתים וכו' עד מתטמאין. תוספתא פ\\\"ד דטבול יום וגירסת רבינו נכונה:\",1,0],[8,379,5,22,\"ואלו מתטמאים וכו' עד סוף הפרק. בפרק קמא דעוצקין וביארו רבינו בפיהמ\\\"ש:\",1,0],[8,379,6,1,\"האגוזים והשקדים וכו'. בפרק ב' דעוקצים. וכתב הראב\\\"ד א\\\"א הוא משנה את הלשונות וכו'. ואיני רואה מקום לומר שרבינו תפס לשון התוספתא שבתוספתא פ\\\"ד דטבול יום שנינו שאע\\\"פ שרצץ חיבור ורבינו כתב שאם רצץ אינו חיבור כדברי המשנה.\",1,0],[8,379,6,1,\"ומ\\\"ש שנסדקה קליפתן. י\\\"ל שרבינו דקדק בלשון המשנה דקתני חיבור עד שירצץ דמדקתני עד שירצץ משמע שקודם הריצוץ קדם צד פירוק חיבור והיינו שנסדקה קליפתן ואשמעינן דאעפ\\\"כ עדיין חשוב חיבור כל זמן שלא רצץ וזה מבואר בדברי רבינו ואין כאן שינוי לשון והתוספתא כפי נוסחא דידן אפשר שאינה חולקת על המשנה דה\\\"ג אע\\\"פ שרצץ חיבור עד שיגיע לפרק וה\\\"פ אע\\\"פ שריצץ כלומר אע\\\"פ שריצץ קצת דהיינו שנסדקה קליפתן חיבור עד שיגיע כלומר עד שיהא אותו ריצוץ כ\\\"כ גדול שיוכל ליטול הקליפה ביד בלי צורך שום ריצוץ עוד:\",2,0],[8,379,6,2,\"ביצה מגולגלת וכו'. משנה פרק ב' דעוקצין.\",1,0],[8,379,6,2,\"ומה שכתב ואם נתבלה וכו'. תוספתא סוף פרק ד' דטבול יום ופירוש נתבלה בקליפתה נראה דהיינו לומר שהיא מדובקת ביותר בקליפתה מלשון תבל עשו שהוא לשון עירוב ואפשר לפרש שהוא לשון תבלין כלומר שנתן בה תבלין בעודה בקליפתה שנוח לו שלא לקלפה לגמרי כשאוכלה כדי לתבלה בתבלין שעל קליפתה:\",2,0],[8,379,6,4,\"ומה שכתב עצם שיש בו מוח וכו'. משנה פרק ב' דעוקצין שם:\",1,0],[8,379,6,4,\"צמר שבראשי כבשים וכו' עד לקלף. תוספתא ספ\\\"ד דטבול יום:\",2,0],[8,379,6,4,\"הרימון שפרדו וכו'. משנה פ\\\"ב דעוקצין:\",3,0],[8,379,6,5,\"השרביטין של תמרים וכו'. תוספתא פרק ג' דטבול יום:\",1,0],[8,379,6,6,\"מלפפון שחתכו וכו' אפילו אמר חציו אני אוכל שחרית וכו'. תוספתא פרק ד' דטבול יום ויש לתמוה על גירסא זו שהיא בהיפך ממה ששנינו במשנה גבי שאר דינין אוכל שהתחיל בו אינו חיבור וגירסת ר\\\"ש בתוספתא נכונה ויש ליישב גירסא זו דה\\\"ק התחיל לפרק חתיכה וכל העולה עמה חיבור זה לזה דכל העולים ביחד הם חיבור זה לזה והנשאר כלומר כל הנשאר שלא עלה עמו אינו חיבור לזה שעלה ואע\\\"פ שהוא פשוט לאו לרבותא קתני לה אלא סיומא דמילתא היא וע\\\"ד זה יתפרש מאי דקתני היו שנים או שלשה וכו' זה שהתחיל בו\",1,0],[8,379,6,6,\"חיבור וכן מה שכתב זה החצי שהתחיל בו חיבור וכו'. והנך דתנן במתניתין אוכל שהתחיל בו אינו חיבור היינו לענין אוכל שהתחיל בו עם השאר שאינו עולה עמו:\",2,0],[8,379,6,7,\"המחתך ירקות וכו'. משנה פרק ב' דעוקצין:\",1,0],[8,379,6,7,\"וכתב הראב\\\"ד ואפילו התחיל לפרק א\\\"א לשון המשנה אינו כן וכו'. נראה שמשיג על רבינו למה שינה לשון המשנה וטעם רבינו דמתניתין לאו לגופה איצטריך האוכל שהתחיל בו אינו חיבור ולא אתא אלא לדיוקי הא אוכל שלא התחיל בו חיבור ולפיכך דקדק רבינו לכתוב הדין המחודש עצמו ואף על פי שהוא כמשנה לשון המשנה זהו שינוי לטובה:\",2,0],[8,379,6,9,\"אוכל שנפרס וכו'. רפ\\\"ג דטבול יום וכחכמים:\",1,0],[8,379,6,10,\"כל האוכלים שהיו עליו וכו'. שם וכתוב בספרי רבינו או שדרכו וט\\\"ס הוא וצריך למחוק או ולכתוב במקומו את:\",1,0],[8,379,6,10,\"ומ\\\"ש היתה לו יד ועלה וכו' לא היתה לו יד ולא עלה וכו'. תוספתא פרק ב' דטבול יום.\",2,0],[8,379,6,10,\"ומ\\\"ש הרי זה חיבור בטבול יום וכו'. בפרק העור והרוטב נראה דר\\\"י סבר כוותיה כיון שאמר דבריו בסתם וסבר כוותיה.\",3,0],[8,379,6,10,\"ומ\\\"ש אוחזים אותו באי זה מהם שירצה. פירושו שהולכים בו להחמיר ובאי זה מהם שיאחוז אותו ויעלה בו הוי חיבור:\",4,0],[8,379,6,11,\"האגוזים שקצצן וכו'. משנה פ\\\"ב דעוקצין.\",1,0],[8,379,6,11,\"ומ\\\"ש אפילו היו לפניו ק' כור וכו'. בתוספתא פ\\\"ד דטבול יום:\",2,0],[8,379,6,11,\"וכתב הראב\\\"ד א\\\"א לשון המשנה אגוזים שאמנן והבצלים שחמרן עכ\\\"ל. כתב כן כדי לתמוה על פירוש רבינו ולפרש פירוש אחר כדבסמוך. ורבינו כתב בפירוש המשנה אמנן גדלן וחבר קצתן לקצתן מלשון ויהי אומן את הדסה וכו' וחמרן שנתן קצתן לקצתן מלשון ויצברו אותם חמרים חמרים:\",3,0],[8,379,6,11,\"וכתב עוד הראב\\\"ד הרי אלו חיבור א\\\"א נ\\\"ל שכלן נעשו יד זה לזה לקיימן עכ\\\"ל. ואיני יודע מה צורך לטעם זה כיון שהם מחוברים אע\\\"פ שלא יהיו יד זה לזה ה\\\"ל חיבור לטומאה:\",4,0],[8,379,6,13,\"קליעה של שום וכו' עד שבעה משקים בלבד. תוספתא ספ\\\"ג דטבול יום:\",1,0],[8,379,6,13,\"וכתב הראב\\\"ד א\\\"א זה לא ידעתי מה הפרש יש וכו'. זה כתב להשיג על רבינו שפירש בצלים שחמרן שחיברן כמו חבל למה שם אמרו שהוא חיבור וכאן אמרו שאינו חיבור ולדעת רבינו אפשר לומר דאין ה\\\"נ דקליעה של שום הוי חיבור לענין שאם נטמא אחד מהם נטמא חבירו כדין בצלים שחמרן ולא אמרו שאינו חיבור אלא לענין שאם נפל משקה על אחד מהם חבירו טהור כלומר לא הוכשר חבירו וזה שסיים שאין חיבורי אדם חיבור לכל דבר משמע לקצת דברים הויא חיבור וה\\\"ה לבצלים שחמרן שאם נפל משקה על אחד מהם חבירו טהור כלומר שלא הוכשר חבירו. ומ\\\"ש ועוד מי ראה מעולם וכו' אינה קושיא שאולי בימיהם היו נוהגים כן. ומ\\\"ש וע\\\"כ נ\\\"ל שאמנן ושחמרן וכו' יש לתמוה שגם על פירושים אלו יש לתמוה מי ראה מעולם וכו':\",2,0],[8,379,6,14,\"הממעך אוכלים זה בזה וכו'. תוספתא פירקא קמא דטהרות.\",1,0],[8,379,6,14,\"ומ\\\"ש לפיכך עיגול של דבילה. תוספתא פ\\\"ב דטבול יום:\",2,0],[8,379,6,15,\"התמרים והגרוגרות וכו'. תוספתא פ\\\"ד דטבול יום:\",1,0],[8,379,6,16,\"הזיתים שעטנן וכו'. כך היא הגירסא האמיתית ובספרי רבינו כתוב שנטמאו וט\\\"ס הוא והדין תוספתא פ\\\"ק דטהרות.\",1,0],[8,379,6,16,\"ומה שכתב לפיכך שרץ הנמצא על אום של זיתים וכו'. פי\\\"א דטהרות:\",2,0],[8,379,6,16,\"היתה לו אום של זיתים וכו'. תוספתא פ\\\"י דטהרות.\",3,0],[8,379,6,16,\"ומ\\\"ש ואם משהפכה ועשו וכו'. שם פלוגתא דתנאי ופסק כרבי מחבירו:\",4,0],[8,379,6,17,\"אוכל פרוד וכו'. בפ\\\"ג דעדיות ופ\\\"ח דטהרות ופסק כחכמים דפליגי ארבי דוסא.\",1,0],[8,379,6,17,\"ומ\\\"ש אע\\\"פ שאינו חיבור להתטמא ואינו כגוף אחד כמו שביארנו בפרק הרי הוא מצטרף לכביצה לטמא אוכלים אחרים. ומ\\\"ש ואם לא כנסו וכו'. בפ\\\"ב דטבול יום מעשה קדירה וקטנית בזמן שהם פרודין אינו חיבור בזמן שהם גוש חיבור אם היו גושים הרבה הרי אלו ימנו:\",2,0],[8,379,6,17,\"וכתב הראב\\\"ד א\\\"א אינו צריך להיות גוש אחד. ומ\\\"ש ואם אינם נוגעים אם יש תחתיהם משקה עומד וכו'. בפ\\\"ח דטהרות וכתבו רבינו בפרק שאחר זה:\",3,0],[8,379,6,18,\"ככר של תרומה וכו' עד סוף הפרק. בספ\\\"ק דטהרות:\",1,0],[8,379,6,19,\"ככרות של תרומה נושכות זו בזו. חסר בספרי רבינו חלוקה אחת וכך צריך לכתוב נטמאת אחת מהם במשקין טמאים כולם שניות ואע\\\"פ שפירשו אחר מכאן וכך מצאתי בספר מוגה:\",1,0],[8,379,7,1,\"הניצוק אינו חיבור וכו'. בפ\\\"ח דטהרות:\",1,0],[8,379,7,2,\"ומ\\\"ש בד\\\"א בשעירה וכו'. בפרק ה' דמכשירין.\",1,0],[8,379,7,2,\"ומ\\\"ש ומפני מה אמרו וכו':\",2,0],[8,379,7,3,\"ומ\\\"ש לפיכך האשה שהיו ידיה טהורות וכו'. בפ\\\"ה דמכשירין:\",1,0],[8,379,7,4,\"נחיל דבש הזיפים וכו'. בפ\\\"ה דמכשירים ופי' שם רבינו דזיפים וצפחת שני מקומות בא\\\"י שהיה דבשם בתכלית העובי וע\\\"כ יחבר ניצוק שלהם בין המשקים שבשני הכלים.\",1,0],[8,379,7,4,\"ומ\\\"ש מפני שיש להם ריר וכו' לפיכך כל האוכלים וכו'. בפ\\\"ז דנזיר (דף נ' ע\\\"ב) וכרבי זירא ומר בריה דרבינא ולא שבקינן לפשיטותיה דרבינא משום דחייתיה דרב אשי.\",2,0],[8,379,7,4,\"ומ\\\"ש ואפי' היו עבים הרבה כגון הגריסין. כתב כן לאפוקי מב\\\"ש שאמרו בפ\\\"ה דמכשירין שמקפה של גריסין הוא חיבור, ולשון לפיכך היאך נמשך זה ממה שאמר למעלה הוא משום דברישא קאמר דתרתי בעינן דיש להם ריר והם נמשכים כדבק משום הכי קאמר לפיכך כל האוכלים אין ניצוק שלהם חיבור אפילו הם עבים הואיל וחסרו התנאי השני שהוא הריר.\",3,0],[8,379,7,4,\"ומ\\\"ש והחלב המותך. בפרק כה\\\"ג ונזיר:\",4,0],[8,379,7,5,\"הניצוק אינו חיבור לטהרה וכו' וכן הקטפרס וכו' אבל המשקים שבאשבורן וכו'. בפרק שמיני דטהרות והמשך דברי רבינו מבואר שכתב תחילה כיצד הניצוק אינו חיבור לטומאה ונמשכו הדברים עד כאן בביאור חילוקים דשייכי לזה ואח\\\"כ כיצד הניצוק אינו חיבור לטהרה:\",1,0],[8,379,7,6,\"עריבה שהוא קטפרס וכו'. שם ונראה מדברי רבינו שמה ששנינו אם היה משקה עומד אפילו כעין החרדל מצטרף אמשקה קאי שהוא מועט כעין החרדל:\",1,0],[8,379,7,7,\"כבר ביארנו שטבול יום אינו מטמא חולין כלל וכו'. בפ\\\"י משאר אה\\\"ט וחזר לכתבו להקדמה למה שעתיד לכתוב:\",1,0],[8,379,7,8,\"יש דברים שאינם חיבור בטבול יום וכו'. יתבאר בפרק שאחר זה:\",1,0],[8,379,7,8,\"ומפני מה הקילו בטבול יום וכו'. נרמז בפ״ב דזבחים ופרק הערל (יבמות דף ע״ב):\",2,0],[8,379,7,8,\"ועוד הקילו בטבול יום שיש אוכלים וכו'. בספ\\\"ק דטבול יום וכחכמים ועוד שנינו שם שהתיאה והחלתית והאלום טהורים בטבול יום ואיני יודע למה השמיטו רבינו:\",3,0],[8,379,7,9,\"כל יד האוכלים וכו'. רפ\\\"ג דטבול יום.\",1,0],[8,379,7,9,\"ומ\\\"ש וכן כל האוכל וכו'. תוספת' דטבו\\\"י פ\\\"ב.\",2,0],[8,379,7,9,\"ומ\\\"ש וכל שאינו חיבור וכו'. תוספתא פ\\\"א דטבול יום:\",3,0],[8,379,8,1,\"חלות או ככרים וכו'. בריש מס' טבול יום. כתב הראב\\\"ד וכן המים שהרתיחו א\\\"א זה כתב במקום קולית של מים וכו'. ור\\\"ש פירש כפי' רבינו.\",1,0],[8,379,8,1,\"ומה שכתב ואורז. שם כרבי יהודה ויש לתמוה למה פסק כיחידאה ודוחק לומר דסבר רבינו דרבי יהודה מסיים דברי ת\\\"ק הוא:\",2,0],[8,379,8,2,\"ומ\\\"ש בצק שיצא וכו'. שם:\",1,0],[8,379,8,3,\"רקיק שנחרך וכו'. תוספתא פרק טבול יום אלא שכתובה בשיבוש. וכן כתב הראב\\\"ד א\\\"א מצאתי זו המלה משובשת בתוספתא וכו'. ומה שכתב וסוף התוספתא וכן רימון שנימוק וכו' כלומר ומסופה נלמד לרישא שהיא כמו שכתב רבינו:\",1,0],[8,379,8,3,\"בשר הקדש וכו'. פרק ב' דטבול יום (דף קנ\\\"א) וכת\\\"ק:\",2,0],[8,379,8,3,\"שמן שצף וכו'. גם זה שם וכתנא קמא:\",3,0],[8,379,8,4,\"ירק תרומה וכו'. פרק ג' דטבול יום וכת\\\"ק:\",1,0],[8,379,8,5,\"חוט של ביצה. ג\\\"ז שם וכת\\\"ק:\",1,0],[8,379,8,6,\"חבית שניקבה וכו'. פרק ב' דטבול יום וכתנא קמא ואף על גב דבעבודה זרה פרק רבי ישמעאל (עבודה זרה דף ס') אמרינן דר״פ כרבי יהודה ורבינו בפי״ב מהמ״א פסק כרב פפא תירץ הר״י קורקוס ז״ל שסובר רבינו דרב יימר הוא דמוקים לר״פ כיחידאה ואתא לאפלוגי עליה אבל ר״פ ודאי שמיע ליה ואי הוה אמר מלתיה כיחידאה הוה מפרש בהדיא שפוסק כר״י הילכך אמרינן דלכ״ע אמרה למלתיה וסובר דלגבי טומאה הוי חיבור טפי מלענין יי״נ וכדאמרינן התם השתא טהרותיו טהורות יי״נ מיבעיא וכן כתב הרשב״א דלרבנן לענין טהרות הוי חיבור דחמירי להו טפי:\",1,0],[8,379,8,7,\"המערה מכלי לכלי וכו'. שם:\",1,0],[8,379,8,8,\"טבול יום שהיה תורם וכו'. גם זה שם וכת\\\"ק.\",1,0],[8,379,8,8,\"ומה שכתב ואם היה בבור פיטס וכו'. תוספתא פ\\\"ב דטבול יום. וכתב הראב\\\"ד א\\\"א לשון התוספתא ואם היה פיטס וכו'. כלומר שבתוספתא אינו כתוב ואם היה בבור פיטס אלא ואם היה פיטס ופירושו שלא היה שם בור אלא פיטס ונפלה החבית לתוך הפיטס ותיקון לשון הראב\\\"ד כך הוא שלא היה שם בור אבל היה תורם היין שבפיטס ותיבת אם ותיבת שם צריך למחקם ונראה שגם רבינו היה מפרש כן.\",2,0],[8,379,8,8,\"ומ\\\"ש בספרי רבינו ואם היה הבור קטן ט\\\"ס הוא וצריך למחוק תיבת קטן ולכתוב במקומה פיטס וכן מצאתי בספר מוגה והיינו לומר שבמקום בור היה פיטס וטעם דין זה מפני שהחבית והפיטס שניהם כלי והכל אחד ונראה שזו היא כוונת הראב\\\"ד במה שכתב ואפשר מפני שכבר נתבטל בכניסתו לפיטס:\",3,0],[8,379,8,9,\"הסולת של מנחות וכו'. ריש פרק ח' דעדיות ומייתי לה פרק קמא דפסחים (דף י\\\"ט) ופ\\\"ה דיומא (דף מ\\\"ח) ופ' בתרא דחגיגה (דף כ\\\"ג ע\\\"ב).\",1,0],[8,379,8,9,\"ומה שכתב במה דברים אמורים בגחלים שחותה וכו'. בירושלמי פרק חומר בקדש אהא דתנן הכלי מצרף מה שבתוכו לקדש תמן תנינן הוסיף ר\\\"ע הסולת והקטורת והלבונה והגחלים שנגע טבול יום במקצתן שפסל את כולן וכו' מאי גחלים אמר רבי בון בר כהנא תפתר בגחלים של יום הכיפורים שבמה שהוא חותה הוא מכניס אבל בגחלים שבכל יום לא כההיא דתנינן נתפזר ממנו כקב גחלים היה מכבדן לאמה:\",2,0],[8,379,8,9,\"כתב הראב\\\"ד א\\\"א אמת הוא שכך אמרו בירושלמי פרק בתרא דחגיגה אבל סוף השמועה עלתה וכו'. טעמו משום דהתם מסיים בה אמר ר' מתניה וכי סלת וקטורת וכו' יש לומר שרבינו יפרש שאינו מסקנא אלא פלוגתא ופסק כמאן דמיקל בדרבנן דהא דרבי מתניה לא מכרעא שיאמר רבי בון דגחלים של כל יום אע\\\"פ שנזקקו לכליין מאחר שמתפזר מהם ואינם משמשות אין לומר בהם מצרפן שא\\\"כ נתקדשו כולם ואיך ישליכו המתפזר מהם לאמה. והתוספות כתבו בשם רבינו ניסים גאון ז\\\"ל כדברי רבי בון וכדברי רבינו:\",3,0],[8,379,8,10,\"מקפה או רקיק וכו'. פרק שני דטבול יום:\",1,0],[8,379,8,11,\"ירק של חולין וכו'. פרק שלישי דטבול יום וכרבי עקיבא מחבירו:\",1,0],[8,379,8,13,\"המקפה של תרומה וכו' עד בעיגול של דבילה. פ\\\"ב דטבול יום. כתב הראב\\\"ד א\\\"א לשון המשנה וכו'. טעמו שחסר בלשון רבינו מלשון המשנה. ויש לומר שרבינו קיצר הלשון ופירושו כפי' המשנה וכך פירוש לשונו ושאר כל הנדוכין שדרכן לדוכן במשקין כלומר ודכן במשקים כך דינם ואם דכן שלא במשקין אף על פי שהם גוש בקערה וכו':\",1,0],[8,379,8,14,\"עיסה שקרא שם וכו'. תוספתא רפ\\\"ב דטבול יום:\",1,0],[8,379,8,15,\"עיסה שנדמעה וכו'. משנה פ״ג דטבול יום וכתנא קמא ומייתי לה בפרק יוצא דופן (נדה דף מ״ו מ״ז):\",1,0],[8,379,8,16,\"עיסה שהוכשרה במשקין וכו'. שם כרבי עקיבא מחבירו:\",1,0],[8,379,8,18,\"מעשר ראשון שהוכשר וכו'. רפ\\\"ד דטבול יום:\",1,0],[8,379,8,18,\"וכן האשה שהיא טבולת יום וכו' עד החבית בטבלה. שם ומייתי לה בפ\\\"ק דנדה (דף ז'):\",2,0],[8,379,8,19,\"טבול יום מטומאת מת וכו' חוץ מזב וזבה בשביעי שלהם. פרק תינוקת (נדה דף ס״ז ע״ב) וברייתא בתורת כהנים:\",1,0],[8,379,9,1,\"השמן או הדבש וכו'. פרק ג' דטהרות רבי מאיר אומר השמן תחלה לעולם וחכמים אומרים אף הדבש רבי שמעון שזורי אומר אף היין ופסק כחכמים ואע״ג דבפרק הקומץ (מנחות דף ל' ע״ב) אמרינן דהלכה כר״ש שזורי לא סמך רבינו על זה משום דבפרק בהמה המקשה (חולין דף ע״ה ע״ב) סבר רב אשי שאין הלכה כמותו אלא במסוכן ובתרומת מעשר של דמאי וכתב רבינו בפירוש המשנה כוונת אומרו תחלה לעולם שאם נטמא ואחר נקפה (אחר זה) ואחר נמחה ואחר נקפה אפילו היה זה אלף פעמים הנה הוא תחלה אפילו בעת הקפותו לפי שהקפאתו אינה הקפאה לפי שלא יקפאו באמת ומשקה יחשב ואפילו בעת ההקפאה ואף על פי שמלשונו כאן היה נראה לומר שהם כמשקה בעת שנימוחו דוקא לא בעת הקפאתם כבר אפשר לפרש דאפילו בשעת הקפאתם קאמר כמו שכתב בפירוש המשנה:\",1,0],[8,379,9,2,\"הרוטב והגריסין והחלב וכו'. משנה ריש פרק ג' דטהרות הרוטב והגריסין והחלב בזמן שהם משקה טופח הרי אלו תחלה קרשו הרי אלו שניים חזרו ונמוחו כביצה מכוון טהור יתר מכביצה טמא שכיון שיצאת טיפה הראשונה נטמאת מכביצה ופירש שם רבינו כבר ביארנו פעמים רבות שהמשקים תחלה לעולם וכו':\",1,0],[8,379,9,2,\"וכן טמא מת שסחט זיתים וענבים וכו' עד במשא הזב. שם.\",2,0],[8,379,9,2,\"ומה שכתב שהמשקה כמופקד באוכל וכאילו הוא גוף אחר ברי״ש גרסינן וכדאמרינן בפרק כל שעה (פסחים דף ל״ג ע״ב) רב אחא בשם רבי יוחנן ומשמע דרבא נמי סבר כוותיה:\",3,0],[8,379,9,3,\"קדירה שמלאה וכו' עד והקדירה טהורה. פ\\\"ב דטהרות:\",1,0],[8,379,9,4,\"טמא שהיה אוכל ענבים וכו'. בפרק י' דטהרות. וכתב הראב\\\"ד ולא נשמט ממנו עוקצו אמר אברהם לשון המשנה נפל ממנו גרגיר יחידי וכו'. פשוט הוא. ומ\\\"ש בתוספתא בד\\\"א שנגע הטמא במקום חותם וכו'. בפרק י\\\"א דטהרות אלא שכתוב שם בשיבוש ובתוספתא שביד הראב\\\"ד היה כתובה כתיקנה והעתיקה ופירשה ורבינו השמיטה אפשר דמשום דמילתא דפשיטא היא:\",1,0],[8,379,9,4,\"כתב הראב\\\"ד כמו שביארנו א\\\"א והוא שלא נגע במשקה. ופשוט הוא:\",2,0],[8,379,9,5,\"גוש של זיתים טמאים וכו'. פרק שלישי דטהרות:\",1,0],[8,379,9,6,\"עצים שנבלעו בהם משקים טמאים וכו'. סוף פ\\\"ד דמכשירין עצים שנפלו עליהם משקין וכו':\",1,0],[8,379,9,7,\"שרץ שנמצא בריחים וכו'. ספ\\\"ט דטהרות:\",1,0],[8,379,9,8,\"עם הארץ שהושיט ידיו וכו'. בשילהי ע\\\"ז (דף ע\\\"ה ע\\\"ב) וכדאורו ליה רבנן לר' ירמיה:\",1,0],[8,379,9,9,\"הגפת והזגין וכו'. פ\\\"ט דכלים:\",1,0],[8,379,9,10,\"הבדדים שהיו נכנסים ויוצאים וכו'. בפ\\\"י דטהרות:\",1,0],[8,379,9,10,\"ככרות הקדש שהיו בהם גומות וכו'. ספ\\\"ק דטהרות:\",2,0],[8,379,9,11,\"אבעבוע הנעשה בעובי החבית וכו'. בספ\\\"ב דטבול יום. כתב הראב\\\"ד אם נגע אב הטומאה במשקה א\\\"א ואם לנגיעת המשקים דברה המשנה וכו'. מה שכתב אם לנגיעת המשקים דברה המשנה מה צורך להיותו אב הטומאה והלא אף טבול יום פוסל אותה וכו' י\\\"ל דלרבותא דסיפא נקטיה שאף על פי שהוא אב הטומאה אם נגע באבעבוע לא נטמאו משקים שבחבית:\",1,0],[8,379,10,1,\"כבר ביארנו וכו'. בפרק ראשון:\",1,0],[8,379,10,2,\"תולדות המים וכו'. פ\\\"ו דמכשירין.\",1,0],[8,379,10,2,\"ומ\\\"ש אבל מי רגלי בהמה וכו'. תוספתא בסוף מכשירין אלא שכתובה בשיבוש קצת:\",2,0],[8,379,10,3,\"הדם המנוי מן וכו' מן הבהמה והחיה והעופות הטהורים. משנה פ\\\"ו דמכשירין.\",1,0],[8,379,10,3,\"ומה שכתב אבל דם הקילוח אינו מכשיר. פרק דם שחיטה עלה כ\\\"ב ופרק שני דחולין (דף ל\\\"ו):\",2,0],[8,379,10,3,\"השוחט ונתז דם וכו'. פרק השוחט שם וכדאסיק רבי אלעזר:\",3,0],[8,379,10,3,\"תולדות הדם וכו' עד הרי הם כחלב. בפרק ששי דמכשירין:\",4,0],[8,379,10,4,\"לפיכך חלב הזכר וכו'. שם כרבי שמעון בן אלעזר ופסק כמותו דמשמע דליכא מאן דפליג עליה:\",1,0],[8,379,10,4,\"וכן חלב בהמה וחיה וכו'. בסוף מכשירין וכרבי עקיבא דיהיב טעמא למילתיה.\",2,0],[8,379,10,4,\"ומה שכתב אבל חלב האשה וכו'. פשוט הוא:\",3,0],[8,379,10,5,\"המשקים שיוצאים וכו'. שם. וכתוב בספרי רבינו מתטמאין בלא הכשר וטעות סופר הוא וצריך להגיה מטמאין בלא הכשר.\",1,0],[8,379,10,5,\"ומה שכתב וכן דם מגפתו של זב וחלב האשה ודמעת עינים וכו'. בפרק דם הנדה (נדה דף נ״ה ע״ב).\",2,0],[8,379,10,5,\"ומ\\\"ש לפיכך נדה או זבה וכו'. פרק ח' דכלים:\",3,0],[8,379,10,6,\"כבר ביארנו וכו'. בפרק י' משאר אבות הטומאה והוא משנה ברפ\\\"ב דטבול יום:\",1,0],[8,379,10,7,\"הזיעה והליחה הסרוחה וכו' עד נקיים. פרק ששי דמכשירין:\",1,0],[8,379,10,8,\"השותה שאר משקים ויצאו וכו'. בסוף מקואות אכל אוכלים טמאים ושתה משקין טמאין טבל והקיאן טמאין מפני שאינם טהורים בגוף שתה מים טמאים טבל והקיאן טהורים מפני שהם טהורים בגוף.\",1,0],[8,379,10,8,\"ומ\\\"ש או שיצאו מלמטה וכו' וכן מ\\\"ש נסרחו או שיצאו מלמטה הרי הם טהורים. שם בתוספתא ופירש שם רבינו כבר ביארנו שהמים לבדם בלתי שאר משקים וכו' עד ולכן אם מקיאן שמה יהיו טהורות וכן פירש רבינו שמשון. וכתב הראב\\\"ד מפני שנטמאו במגען א\\\"א והוא ששתה רביעית וכו' ואני אומר נוסחא משובשת נזדמנה להראב\\\"ד בדברי רבינו שהיה כתוב בה שתה מים טמאים והקיאן הרי אלו טמאים מפני שנטמאו במגען ומצאה מסכמת לסברתו שסובר שבטלה טומאתן בהיותן בתוך מעיו וע\\\"פ זה כתב מה שכתב אבל הנוסחא האמיתית היא מפני שלא טהרו ביציאתן וכך היא בספרים המדוייקים ופירושה מבואר שהטעם שהם טמאים מפני שלא טהרו כלומר שלא טבל בעודם בגוף לפיכך נשארו בטומאתן כמות שהיו ולא טהרה אותם היותם בתוך מעיו אא\\\"כ נסרחו או יצאו מלמטה וזה מבואר בפשט דברי המשנה ובפירושה לרבינו ולרבינו שמשון:\",2,0],[8,379,10,12,\"כבר ביארנו וכו' אפילו שתה משקין טמאים וכו' עד מחצה למחצה טמא. בפ\\\"ב דמכשירין:\",1,0],[8,379,10,12,\"ומ\\\"ש הכניסו לה כלים וכו'. ז\\\"ל רבינו בפירוש המשנה כשנכנס בדבר למרחץ ונבלל זה ברצונו הוא וכבר הוכשר כי מן הידוע שיבלל בהכרח עכ\\\"ל. ומינה ג\\\"כ לכלים שהזיעו דחשיבי תלושין ברצון:\",2,0],[8,379,10,14,\"המוהל כשמן וכו'. פ\\\"ו דמכשירין:\",1,0],[8,379,10,14,\"משקין המנטפין וכו' השוקל וכו' עד שמנטפים. שם פרק חמישי:\",2,0],[8,379,10,15,\"הדורס ענבים וכו':\",1,0],[8,379,10,16,\"משקה בית וכו'. פרק קמא דפסחים עלה י\\\"ו וכרב דאמר דכן ממש דהלכתא כוותיה באיסורי:\",1,0],[8,379,10,17,\"פרת קדשים וכו'. בפ״ק דפסחים (דף י״ט) תנן התם על מחט שנמצאת בבשר וכו' עד הכל טהור האי מחט מאי עבידתיה וכו' עד מחוץ לירושלים האי בשר דאתכשר במאי וכו' עד משום דהוי משקה סרוח וכו'. וכתב הראב״ד אבל להתטמא מדבריהם א״א והלא במסכת חולין למדו לחיבת הקדש שמכשרתן מן התורה אלא שהוא ספק אם מונים בו ראשון ושני או לא עכ״ל. ובאמת השגתו חזקה על דברי רבינו שבפרק השוחט (חולין דף ל״ו) אהא דבעי ר״ל צריד של מנחות מונין בו ראשון ושני או לא כי מהני חיבת הקדש למפסליה גופיה למימני ביה ראשון ושני לא או דילמא לא שנא אסיקנא אטו ר״ל לתלות קא מיבעיא ליה כי קא מיבעיא ליה לשרוף מכלל דחיבת הקדש דאורייתא מנ״ל אילימא מדכתיב והבשר אשר יגע בכל טמא וכו' אלא מסיפא והבשר לרבות עצים ולבונה עצים ולבונה בני אכילה נינהו אלא חיבת הקדש מכשרא להו ומשויא להו אוכל ה״נ חיבת הקדש מכשרתן ואפשר שטעמו של רבינו משום דהתם סבר רב יוסף דחיבת הקדש הויא דרבנן ומאי דאמרינן מכלל דחיבת הקדש דאורייתא מנא ליה וכו' אליבא דריש לקיש הוא דקא מיבעיא לה אבל רב יוסף סבר שאין חיבת הקדש מכשרת אלא מדרבנן ופסק כוותיה משום דבתרא הוא:\",1,0],[8,379,11,1,\"הבוצר ענבים וכו' אבל הבוצר לדרוך וכו'. פ\\\"ק דשבת עלה ט\\\"ז.\",1,0],[8,379,11,1,\"ומ\\\"ש ומפני מה גזרו וכו'. שם עלה י\\\"ז.\",2,0],[8,379,11,1,\"ומ\\\"ש ועוד מפני שאינו מקפיד עליו וכו'. כתב הראב\\\"ד לא ידעתי מהו וכו'. ואפשר שטעם רבינו מדאמרינן בגמרא גזירה משום הנושכות דאמר רבה בר נחמן פעמים שאדם הולך לכרמו לידע אם הגיעו ענבים לבצירה וכו' ופירש\\\"י הנושכות אשכולות הנושכות זו את זו וכו' ורבינו נראה שמפרש דהכי קאמר משום אשכולות הנושכות כלומר אשכולות הנשוכות כלומר שהם ממועכות קצת והמשקה זב מהם וא\\\"ת מאין יבאו אשכולות נשוכות לכן אמר פעמים שאדם הולך לכרמו וכו' ומזלפו עליהם ובא רבינו ליתן טעם למה מזלפו עליהם שהרי הכל לדריכה עומד ולפיכך אינו חושש אם מזלפו עליהם ועוד שאפילו לא יזלפנו עליהם בכוונה ממילא הוא זב עליהן שהוא משליך אותו על האשכולות שהוא מקפיד עליו מלהשליכו בארץ. ומ\\\"ש הראב\\\"ד ואולי שבוש המעתיק הוא כו' מלבד שהוא דוחק לשבש הספר אין פירושו נוח לי והדבר ברור כמה יש בו מן הדוחק וע\\\"פ מה שרצה לפרש לא היה צריך לשבש הלשון אלא לומר דהכי קאמר מפני שני טעמים גזרו וכו' האחד מפני שפעמים שאדם נכנס לכרמו וכו' השני מפני שמתוך שבתחילה אינו מקפיד על המשקה ובוצר בקופות כשרואה שהוא זב מקפיד עליו ובוצר בקופות מזופפות:\",3,0],[8,379,11,2,\"הבוצר ענבים וכו'. תוספתא פרק י\\\"א דטהרות:\",1,0],[8,379,11,3,\"הבוצר ענבים ונתנם בעביט וכו'. משנה פרק י' דטהרות הנותן מן הסלים ומן המשטיח של אדמה וכו' וכבית הלל.\",1,0],[8,379,11,3,\"ומה שכתב וכן הנוטל מן הסלים וכו'. תוספתא פי\\\"א דטהרות. וכתב הראב\\\"ד קשיא לי וכו'. נראה מדבריו לכאורה שהוא סובר שרבינו הוציא דין זה מהמשנה ולפיכך הביא לשונו לומר שלא נאמר שם וזרקם לגת כמ\\\"ש רבינו, ואפשר שאע\\\"פ שרבינו כתב דברי התוספתא משיג עליו שמאחר שבמשנה לא אמרו זרקן לגת משמע שאם זרקן לגת הוכשרו לא היה לו לחוש מהתוספתא, ולענין מה שהקשה הראב\\\"ד י\\\"ל שלא גזרו אלא על הבוצר לגת וה\\\"ה ללוקח מן הסלים ומן המשטיח של אדמה לדרוך דשעת לקיחתו מהם הוי כבוצר לדרוך אבל היכא דלקיחתו לא היתה ע\\\"ד לדרוך אינו בכלל גזירת בוצר לגת ואפי' מה שהותיר וזרקו לגת אינו נכנס באותה גזירה כלל ולישנא דרבינו דייק הכי שכתב הרי הגת טהורה שהרי לא הוכשרו והרי נבצרו לאכילה ובסיפא כתב ולקח מהם לדורכן:\",2,0],[8,379,11,4,\"ומ\\\"ש ענבים שהיו בסלים וכו' כדי שלא יקח מהם ויטמאן. תוספתא שם אלא שהיא כתובה בשיבוש וכן כתב הראב\\\"ד א\\\"א מצאתי תוספתא על העניינים הללו:\",1,0],[8,379,11,5,\"כרם שהוא עומד בבית הפרס וכו'. ריש פי\\\"ח דאהלות. כתב הראב\\\"ד אלא מפני שהוא ספק בחיי ראשי אין דעתי מקבלת וכו'. ואין בזה השגה:\",1,0],[8,379,11,6,\"המוסק את זיתיו וכו'. זה פשוט.\",1,0],[8,379,11,6,\"ומה שכתב וכן המוסק זיתיו לדרוך וכו'. בריש פסחים (ג:) בוצרין בטהרה ואין מוסקין בטהרה ובריש פ\\\"ט דטהרות זיתים מאימתי מקבלים טומאה וכו' ר\\\"ג אומר משתגמר מלאכתן וחכ\\\"א כדבריו.\",2,0],[8,379,11,6,\"ומ\\\"ש ומפני מה יוכשרו הזיתים וכו'. בתוספתא דטהרות רפ\\\"י.\",3,0],[8,379,11,6,\"ומ\\\"ש לפיכך זיתים שלא נגמרה מלאכתן וכו' נפלו עליהם משקים טמאים אחר שנגמרה מלאכתן וכו'. משנה פ\\\"ט דטהרות.\",4,0],[8,379,11,6,\"ומ\\\"ש ומתטמא ומכשיר. פ\\\"ו דמכשירין:\",5,0],[8,379,11,7,\"חבית של זיתים וכו'. פרק רביעי דעדיות:\",1,0],[8,379,11,8,\"זיתים שמסקן וכו'. כן משמע בריש פרק תשיעי דטהרות וכרבן גמליאל דאמר משתגמר מלאכתן וחכמים אומרים כדבריו:\",1,0],[8,379,11,8,\"גמר מלמסוק וכו'. שם.\",2,0],[8,379,11,8,\"ומה שכתב אפילו אינו עתיד להוסיף וכו' ואם הערים וכו'. תוספתא פרק עשירי דטהרות:\",3,0],[8,379,11,8,\"גמר מליקח וכו'. משנה פרק תשיעי דטהרות:\",4,0],[8,379,11,10,\"העוטן זיתיו וכו' עד אלא הוכשרו. תוספתא פ\\\"ט דטהרות:\",1,0],[8,379,11,10,\"גמר את זיתיו וכו'. גם זה שם:\",2,0],[8,379,11,11,\"הלוקח מעטן וכו'. גם זה שם ופירש ר\\\"ש אף על פי שיש לעכו\\\"ם מוסקי זיתים במקום אחר לא אמרינן עתיד להוסיף ולא נגמרה מלאכתן אלא יעשו בטומאה.\",1,0],[8,379,11,11,\"ומה שכתב ונאמן ע\\\"ה וכו':\",2,0],[8,379,11,12,\"הרוצה ליטול מזיתים וכו'. משנה פ\\\"ט דטהרות וכב\\\"ה:\",1,0],[8,379,11,13,\"המניח את זיתיו בכותש וכו'. שם.\",1,0],[8,379,11,13,\"ומה שכתב הניחם למלחם וכו'. שם וכבית הלל:\",2,0],[8,379,11,14,\"ומה שכתב הפוצע זיתים וכו'. שם.\",1,0],[8,379,11,14,\"ומ\\\"ש פצען לסופגן במלח וכו'. בפרק חבית עלה קמ\\\"ה.\",2,0],[8,379,11,14,\"ומ\\\"ש וכן אם פצען וכו'. שם וכתנא קמא:\",3,0],[8,379,11,15,\"המניח זיתים בגת וכו'. בפ\\\"ט דטהרות המניח זיתים בגג לגרגרם אפילו הם רום אמה אינם מוכשרים ופירש שם רבינו לגרגרן לעשות מהם גרעינין הכוונה להתייבש ולהתנגב ואפילו היה גבהן אמה אשר נדע עתה שכבר נתייבשו העליונות הנה התחתונות יובללו לכן מאחר שכוונתו הניגוב אינם מוכשרים עכ\\\"ל. וכתב הראב\\\"ד א\\\"א לייבשם שיבוש וכו'. כוונתו לומר שלייבשן היינו לאכילה וזה לא הוצרך לכתבו שכבר כתב לעיל שהמוסק זיתיו לכבשן לא הוכשרו ועוד שמשנה זו שנויה אצל דיני המוסק זיתיו לשמן אם נגמרה מלאכתן ע\\\"י אותה נתינה או לאו. וטעם רבינו כמו שפירש ר\\\"ש שמעלה אותם לגג למתקן בחמה לספתן במלח ולאוכלם אלא שרבינו שמשון גורס הרי אלו מוכשרים ומפרש דניחא ליה שיזועו שם דחזו לאכילה טפי ורבינו גורס אינם מוכשרים ולדעתו נאמר דאשמעינן שאף על פי שמתוך שהעמידן רום אמה היה אפשר לומר דניחא ליה שיזועו קמ\\\"ל דכיון שדעתו היה לייבשן לא אמרינן הכי:\",1,0],[8,379,11,15,\"נתנן בבית שילקו וכו' עד שעדיין לא נגמרה מלאכתן. שם:\",2,0],[8,379,11,16,\"העוטן זיתיו וכו' עד כפתחין. תוספתא פ\\\"י דטהרות:\",1,0],[8,379,11,17,\"הדורך בטומאה וכו'. בסוף טהרות כלי של בית הבד ושל גת והעקל בזמן שהן של עץ מנגבן והם טהורים בזמן שהן של גמי מיישנן כל שנים עשר חודש או חולטן בחמין רבי יוסי אומר אם נותנן בשבלת הנהר דיו ובסוף עבודה זרה [דף ע\\\"ה.] בעו מיניה מרבי אבהו הני גורני דארמאי מאי אמר להו רבי אבהו תניתוה הרי שהיו גיתיו ובית בדיו טמאים וביקש לעשותם בטהרה הדפים והעדשים והלולבין מדיחן והעקלים של נצרים ושל בצבוץ מנגבן של שיפה ושל גמי מיישנן שנים עשר חדש וכו' רבי יוסי אומר הרוצה לטהרם מיד מגעילן ברותחים או חולטן במי זיתים רבן שמעון בן גמליאל אומר משום רבי יוסי מניחן תחת צנור שמימיו רודפים וכמה עונה ומפרש התם דעונה היינו שתים עשרה שעות וכתב רש\\\"י מדיחן במים ועל משנה זו יש לסמוך שאין צריך אפר לגת מדפשיט מינה רבי אבהו ולא אמרינן זו אינה משנה דקתני בה דסגי לגת בהדחה ומתניתין קתני דבעי ניגוב שמע מינה קמו בה רבנן בתראי ופשטו הלכתא כוותיה עכ\\\"ל. ומשמע דרבי יוסי לא לאיפלוגי אתנא קמא אתא אלא לומר שאם רצה לטהרם מיד מגעילן וכו' ות\\\"ק מודה ליה וכן הא דאמר רבן שמעון ב\\\"ג משום רבי יוסי לא פליג אדרבי יוסי קמייתא אלא כל חד אמר חד מתרי תלת תקוני וה\\\"ה לאינך:\",1,0],[8,379,12,1,\"כל דברי הכשר אוכלים וכו' מפי השמועה למדו וכו' שאר שבעה משקין. בפרק ששי דמכשירין:\",1,0],[8,379,12,1,\"ומ\\\"ש והוא שינתן עליהן ברצון הבעלים. הרשב\\\"א כתב בפרק השוחט עלה ל\\\"א גבי פירות שנשרו לתוך אמת המים וכו' מכאן דקדקו התוספות דלא בעינן רצון הבעלים מדקאמר מי שידיו טמאות משמע אפילו אחר שאינו בעל הפירות ועוד דעיקרו מדכתיב וכי יותן מים וכו' והרמב\\\"ם כתב והוא שינתן עליהם ברצון הבעלים עכ\\\"ל. וליישב לדעת רבינו י\\\"ל דמשמע ליה דפשיטא דרצון בעלים בעינן דאין סברא דרצון אחרים יגרום טומאה לדבר שאינו שלהם והנך דמייתי הרשב\\\"א לא מכרע.\",2,0],[8,379,12,1,\"ומ\\\"ש ואחר שנעקרו מהקרקע וכו'. בריש פרק בעור והרוטב (חולין דף קי\\\"ח).\",3,0],[8,379,12,1,\"ומ\\\"ש ונתלשו המשקין. זה נלמד מדתנן בפרק רביעי דמכשירין שצנון שבמערה נדה מדיחתו והוא טהור העלתהו כל שהוא מן המים טמא פי' דאז הוכשרו וכתבו התוספות בפ\\\"ב דחולין עלה ל\\\"א ע\\\"ב והא דאמרינן בפ\\\"ק דפסחים דאיכא תרי קראי לענין הכשר חד בתלושין וחד במחוברים וצריכי היינו כשנפלו במחוברים דמתכשרי לאחר שהעלם וכבר כתב רש\\\"י בפירקא קמא דחולין עלה י\\\"ו דאי אחשבינהו לגשמים בירידתם לצורך שום דבר וכו':\",4,0],[8,379,12,2,\"כל משקה שנפל על האוכל וכו'. בריש מכשירין.\",1,0],[8,379,12,2,\"נפל שלא ברצונו וכו' כיצד הטומן פירותיו וכו' או הנותן פירותיו וכו'. סוף פירקא קמא דמכשירין:\",2,0],[8,379,12,2,\"וכתב הראב\\\"ד לא תימא שנפל על האוכל וכו'. משיג על רבינו שאין נראה כן מדבריו פה ויש לומר שמ\\\"מ הוא נלמד מדין כופה קערה על הכותל שיבא בפרק זה:\",3,0],[8,379,12,3,\"משקין שנתלשו וכו'. כתב הראב\\\"ד ואילו היה בקרקע. ומ\\\"ש ודבר זה מפורש במסכת מכשירין. הוא מה שכתבתי בסמוך צנון שבמערה נדה מדיחתו וכו' ומכ\\\"מ מ\\\"ש ואילו היה בקרקע ונתלו וכו' וגם אלו כמו כן מוכשרים אין הנדון דומה לראיה דה\\\"ק כיון שנתלשו שלא לרצון הרי הם כאילו הם עדיין בקרקע ולא נתלשו וזה מבואר בדברי רבינו:\",1,0],[8,379,12,3,\"כיצד הכופה קערה על הכותל וכו'. פ\\\"ד דמכשירין.\",2,0],[8,379,12,3,\"ומ\\\"ש אם היה כותל בית וכו'. באוקימתא דר\\\"פ פ\\\"ק דחולין עלה י\\\"ו:\",3,0],[8,379,12,4,\"השוחה לשתות. ריש פ\\\"ד דמכשירין:\",1,0],[8,379,12,5,\"הממלא את החבית וכו'. שם:\",1,0],[8,379,12,6,\"מי שירדו עליו גשמים וכו'. גם זה שם.\",1,0],[8,379,12,6,\"ומ\\\"ש אע\\\"פ שירדו מצד העליון וכו'. בתוספתא פרק קמא דמכשירין.\",2,0],[8,379,12,6,\"ומה שכתב והוא שינתקם מעליו וכו'. בפ\\\"ג דכריתות עלה ט\\\"ו ע\\\"ב זב וטמא מת שהיו מהלכין בדרך וכו' אמר רב יוסף בניתזים בכל כוחן כלומר דאל\\\"כ בשעת פרישתן נטמאו ועיין ברבינו שמשון ריש מכשירין.\",3,0],[8,379,12,6,\"ומ\\\"ש ובזמן שהם טהורין וכו' ואם ניער וכו' עד המים שעליו טמאים. פרק ד' דמכשירין:\",4,0],[8,379,12,6,\"וכתב הראב\\\"ד א\\\"א שיבוש יש כאן כו':\",5,0],[8,379,12,6,\"וכתב עוד הראב\\\"ד ואם ניער וכו' כמדומה אני שנשתבש וכו'. בשתי השגות אלו טעמו שהוא ז\\\"ל מפרש שהניעור השנוי במשנה היינו מה ששנו בברייתא לאחר שיצאו מכלי ובזה הוא שאמרו שינתקם בכל כחו כדי שלא יטמא בשעת פרישתו ומה שאמרו בברייתא המים נתלשין מצד עליון תחתון הוא כשהם עדיין בבגד עצמו ולא יצדק לומר בהם והוא שינתקם מעליו בכל כחו וי\\\"ל שכך פירוש דברי רבינו אע\\\"פ שירדו מצד העליון לתחתון טהורים בין בעודם בבגד בין לאחר שיצאו מהבגד והא דטהורים לאחר שיצאו מהבגד הוא שינתקם מעליו בכל כחו שאל\\\"כ בשעת פרישתן נתטמאו ולענין הכשר בזמן שהם טהורים כלומר שהם על אדם טהור אינם מכשירים בין כשהם בבגד בין לאחר שיצאו מן הבגד מפני שאינם לרצון ואם ניער הרי זה בכי יותן משום דהוה ליה לרצון ובהשגה הראשונה כתוב לפי שהם ניטלין והוא ט\\\"ס וצריך לכתוב במקומו לפי שהם בטלים. ובהשגה השנית כתוב שנשתבש כל המשנה וחסר בי\\\"ת וכך צריך לכתוב בכל המשנה:\",6,0],[8,379,12,7,\"חבית שהיתה מלאה פירות וכו'. שם וכב\\\"ה.\",1,0],[8,379,12,7,\"ומה שכתב ואף על פי שרצונו:\",2,0],[8,379,12,8,\"עריבה שירד הדלף וכו'. שם.\",1,0],[8,379,12,8,\"ומ\\\"ש נטלה לשפכה וכו'. שם וכבית הלל.\",2,0],[8,379,12,8,\"הניחה שירד הדלף לתוכה הניתזים והצפים וכו'. ג\\\"ז שם וכב\\\"ה.\",3,0],[8,379,12,8,\"ומ\\\"ש ואם נטלה לשפכה וכו'. שם:\",4,0],[8,379,12,9,\"המטביל את כליו וכו'. שם:\",1,0],[8,379,12,10,\"פירות שנפלו וכו'. שם:\",1,0],[8,379,12,11,\"הנותן פירותיו לתוך המים וכו' כיצד צנון וכו'. ג\\\"ז שם:\",1,0],[8,379,12,12,\"קופה שהיא מליאה תורמוסין וכו'. גם זה שם:\",1,0],[8,379,13,1,\"הממלא בקילון וכו'. סוף פ\\\"ד דמכשירין שם:\",1,0],[8,379,13,1,\"וכתב הראב\\\"ד וכיון שנחשבו וכו'. אילו לא היה קשה אלא זה שהוקשה להראב\\\"ד היה אפשר לדחוק ולומר לדעת רבינו דמעיקרא אין בדעתו שיהיו כתלושין ברצון אלא המשקה שישאר בו עד ג' ימים לפי שא\\\"א למלאות בקילון אלא א\\\"כ ישאר בו משקה ג' ימים ואם אחר ג' ימים ישאר בו משקה כיון שאינו תלוש לרצונו אינו מכשיר אבל אי קשיא לדעת רבינו הא קשיא דמשמע דס\\\"ל דר\\\"ע פליג אתנא קמא ופסק כת\\\"ק ובתוספתא פ\\\"ב דמכשירין שנינו הממלא בקילון פירש ר\\\"ע אם נגבו מיד טהורים ואם לא נגבו אפילו מכאן עד שלשים יום טמאין סתמן ג' ימים ע\\\"כ הרי בהדיא דר\\\"ע מפרש ואפשר לומר שסובר רבינו שאם היה מזכיר בתוספתא סברת ת\\\"ק ואח\\\"כ היה אומר פירש ר\\\"ע היינו אומרים שלפרש דברי ת\\\"ק אתא אבל מאחר שלא הוזכר בתוספתא אלא דברי ר\\\"ע יש לנו לומר דפי' ר\\\"ע לאו לישנא דפי' הוא אלא הוי כמו אמר ר\\\"ע ולענין פי' דברי הראב\\\"ד הביא דברי רבי עקיבא במשנה ובתוספתא שתולה הדבר בנגבו ולא נגבו דמשמע כפירושו שתלה הדבר באם נגבו והיינו אם יש בו להטפיח וכתב שאין דעתו נוחה בכל זה משום דקשיא ליה הדבר באם נגבו נחזי אנן אם יש בו להטפיח ואילו לפירוש רבינו ניחא הא ומ\\\"מ יש להעמיד דברי הראב\\\"ד כגון שהשליך פירות בקילון ולא ידע אם היה בו להטפיח:\",2,0],[8,379,13,2,\"עצים שנפלו עליהם משקים וכו'. שם:\",1,0],[8,379,13,2,\"היו רגליו וכו' עד אין להם מחשבה. הכל פ\\\"ד דמכשירין שם:\",2,0],[8,379,13,4,\"המוריד את הגלגלים וכו' עד ואין להם מחשבה. ספ\\\"ג דמכשירין:\",1,0],[8,379,13,6,\"הטובל במים וכו'. נלמד ממה שיבא בסמוך.\",1,0],[8,379,13,6,\"ומ\\\"ש מי שטבל בנהר וכו' וכן מי שדחהו חברו וכו'. רפ\\\"ה דמכשירין:\",2,0],[8,379,13,6,\"טבל בנהר ועלה וכו'. תוספתא בפרק שני דמכשירין:\",3,0],[8,379,13,8,\"השט על פני המים וכו' עד אינם תלושים ברצון. משנה פ\\\"ה דמכשירין:\",1,0],[8,379,13,9,\"המודד את הבור וכו'. שם וכר\\\"ע מחבירו כ\\\"ש דבר פלוגתיה הודה לו כדאיתא בתוספתא:\",1,0],[8,379,13,9,\"פשט ידו וכו'. שם במשנה. כתב הראב\\\"ד אינם כתלושים א\\\"א לשון המשנה ושעל האבן טהורה וכמדומה לי שעל הכשר הוא הכל עכ\\\"ל. ודבר פשוט הוא ומפני שלשון טהורים אינו מורה על הכשר שינה רבינו וכתב אינם כתלושין ועוד מפני שהאבן בבור וקתני שאע\\\"פ שהאבן נראה למעלה משטח המים והחלק הנראה ממנו בלול אין דין המים אשר על החלק היוצא ממנו דין מים תלושין:\",2,0],[8,379,13,10,\"החובט על השלח וכו'. שם וכתנא קמא:\",1,0],[8,379,13,12,\"המים העולים וכו' עד לצרפו. שם. וכתב הראב\\\"ד וכן המים שעל הקסייה של שלחנות א\\\"א פירש בערוך קערות ור\\\"ש פירש השלחנות יש להם בגדים וכו' וכיוצא בזה פירש רבינו:\",1,0],[8,379,13,12,\"ומ\\\"ש המניח את האוד בגשמים לעשותו פחם. כך הגירסא הנכונה והדין תוספתא סוף פ\\\"ב דמכשירין המניח אוד בגשמים לכבותו אינו בכי יותן ואם בשביל פחם ה\\\"ז בכי יותן ולשון המשנה בפ\\\"ה דמכשירין המניח אוד בגשמים לכבותו הרי זה בכי יותן ויש לתמוה על רבינו למה הניח המשנה ותפס התוספתא ואפשר לומר דמשמע לרבינו דלעשות פחם גם הוא מכבה אלא שכששונה לכבותו כנגד אם בשביל פחם הוי לכבותו בלבד בלי כוונת עשיית פחם והתוספתא באה לפרש דלכבותו דקתני מתניתין היינו כשהוא מכבה שלא לעשותו פחם אינו בכי יותן:\",2,0],[8,379,13,12,\"ומ\\\"ש המוציא מסמר לגשמים לכבותו. מפורש בתוספתא שם וכן משמע במתניתין דקתני המוציא מסמר לגשמים לצרפו הרי זה בכי יותן הא שלא לצרפו אינו בכי יותן:\",3,0],[8,379,13,13,\"שלשל את המשולת וכו' שלשל את הכלכלה. תוספתא סוף פ\\\"ב דמכשירין:\",1,0],[8,379,13,14,\"הממחק את הכרישה וכו' והסוחט שערו וכו'. משנה פ\\\"ק דמכשירין הממחק את הכרישה והסוחט שערו בכסותו רבי יוסי אומר היוצאים בכי יותן ואת שבו אינן בכי יותן מפני שהוא מתכוון שיצאו מכולו ופסק רבינו כרבי יוסי משום דאתי כב\\\"ה דהתם גבי מרעיד את האילן להשיר ממנו משקין:\",1,0],[8,379,13,14,\"ומ\\\"ש וכרישה עצמה הוכשרה כו'. פ\\\"ג דכריתות (דף ט\\\"ו ע\\\"ב):\",2,0],[8,379,13,15,\"המרעיד את האילן וכו'. פ\\\"ק דמכשירין וכב\\\"ה.\",1,0],[8,379,13,15,\"ומ\\\"ש וכן אם נתזו על המחוברים וכו'. תוספתא פרק קמא דמכשירין המרעיד את האילן להשיר ממנו משקים ונפלו על תלושים שבו ועל המחוברים שתחתיו ב\\\"ש אומרים בכי יותן ובית הלל אומרים על התלושין בכי יותן ועל המחוברים אינם בכי יותן:\",2,0],[8,379,13,16,\"המרעיד את האילן ונפל על חבירו וכו' ונפלו המים על הפירות המחוברין שתחתיהן. כך היא הגירסא האמיתית והדין משנה פרק קמא דמכשירין המרעיד אילן ונפל על חבירו או סוכה ונפלה על חבירתה ותחתיהם זרעים או ירקות המחוברים לקרקע בית שמאי אומרים בכי יותן וב\\\"ה אומרים אינם בכי יותן וממה שכתב רבינו כאן נראה שהוא מפרש שמרעיד האילן להשיר ממנו מים ונפלו על אילן אחר ומשם נפלו על זרעים או ירקות שתחתיו אותם מים שנפלו על אותם זרעים או ירקות אם נגעו בהם פירות תלושין לא הוכשרו מפני שאותם מים אינם חשובים תלושין ברצון לפי שלא נתכוון שיפלו על אותם זרעים וירקות המחוברים לקרקע ואילו היו אותם זרעים וירקות תלושים אע\\\"פ שלא נתכוון שיפלו עליהם כיון שנתכוון להשירם מהאילן ובסוף נפלו על התלושין הוה להו כתלושין ברצון זה נראה מדברי רבינו אבל קשיא לי מאי איריא נפלו על חבירו אפילו נפלו מהאילן עצמו על הזרעים והירקות המחוברים אינם בכי יותן ואם נגעו בהם פירות תלושים לא הוכשרו כמו שכתב בסמוך שאם ניתזו על המחוברים אינם תלושים ברצון ויש לומר דהתם כשלא נתכוון שיפלו על המחוברים היא וכדדייק לישנא דניתזו והיינו דומיא דנפל על חבירו שלא נתכוון שיפלו על הזרעים והירקות המחוברים אבל אם נתכוון שיפלו על המחוברים הרי הן בכי יותן והשתא לשון רבינו הוי כלל ופרט דברישא תני שאם ניתזו על המחוברין אינם תלושים ברצון והדר מפרש כיצד המרעיד את האילן ונפל על חבירו וכו' ולפ\\\"ז הא דקתני בתוספתא על המחוברים אינם בכי יותן המרעיד אילן ונפל על חבירו הוא ואע\\\"פ שלא נתבאר כן בתוספתא יש לומר שסמכה על המשנה דקתני ונפל על חבירו ובפירוש המשנה פירש רבינו בע\\\"א וז\\\"ל אין ספק כי הירקות והזרעים טופחים במים וכו'.\",1,0],[8,379,13,16,\"והרב רבי אברהם בן דוד כתב אינם תלושים ברצון א\\\"א היה לו לומר שאינם מקבלים הכשר במחובר וכו'. נראה מדבריו שהוא סובר שמה שכתב רבינו שאם ניתזו על המחוברים אינם תלושים ברצון לענין הכשר המחוברים עצמם קאמר וכבר כתבתי שאין הדבר כן אלא לעניין פירות תלושים שנגעו באותם המים קאמר שלא הוכשרו:\",2,0],[8,379,13,16,\"ומ\\\"ש עוד הראב\\\"ד ובמרעיד את האילן ונפל על חבירו וכו'. לשיטתיה אזיל דלענין הכשר המחוברים עצמם היא שנויה והמעיין בדברי רבינו כאן יראה שאין דעתו כן אלא לענין פירות שנגעו באותם מים קאמר דאינם מכשירין אותם כמ\\\"ש. ומ\\\"ש הראב\\\"ד ב\\\"ש סברי כיון שמתכוון להפיל את האילן וכו' וב\\\"ה סברי אעפ\\\"כ וכו'. שפתים ישק ומ\\\"מ מ\\\"ש רבותא הוא לב\\\"ש דוחק הוא לומר דאשמעינן רבותא לב\\\"ש דלית הלכתא כוותייהו. ומ\\\"ש אם נתלשו ומשקה טופח עליהם הרי הם בכי יותן משמע דלבית הלל אינם בכי יותן וסתם מתניתין בפ\\\"ד דמכשירין גבי פירות שנפלו לתוך אמת המים וגבי צנון שבמערה וגבי קופה שהיא מלאה תורמוסים שאף ע\\\"פ שנפלו הפירות במים שבקרקע כשהוציא הפירות משם הו\\\"ל כאילו נבללו במים תלושין ומינה נשמע דה\\\"ה כשנפל מים על ירקות המחוברים ונתלשו ודוחק לומר דאתו הני סתמי דלא כב\\\"ה ועוד דבפ\\\"ק דשבת (דף י\\\"ז) גבי בוצר לגת משמע שאם כשנתלשו שהיין משקה טופח עליהם מודו ב\\\"ה דהוי בכי יותן:\",3,0],[8,379,13,16,\"ומ\\\"ש והתוספתא שעל משנה זו צריכה אומן כבר כתב בה רבינו שמשון שהיא משובשת ופירשה ע\\\"פ הגהתו ולפי מה שפירשתי דברי רבינו אין בהם שיבוש וכבר כתבתי בה בסמוך:\",4,0],[8,379,13,17,\"שמרים של תרומה וכו'. בפרק המוכר פירות עלה צ\\\"ז תנו רבנן שמרים של תרומה וכו' אמר רבי יוחנן וכו' כדרך שאמרו לענין איסורן כך אמרו לענין הכשירן [ומאי נ\\\"מ] אי דמיא אכשורי מכשרי אי דחמרא אכשורי מכשרי לא צריכא שתמדו במי גשמים וכיון דשקיל ורמי להו במנא אחשבינהו [לא צריכא] בנתמד מאליו וכיון דנגיד קמא קמא אחשבינהו אמר רב פפא בפרה ששותה ראשון ראשון. ופירשב\\\"ם כך אמרו לענין הכשר דראשון ושני של תרומה חשיב יין לענין הכשר והראשון של מעשר חשיב יין לענין הכשר. לא צריכא כלומר לא נפקא לן מינה אלא שתמדו לההיא דתרומה ומעשר במי גשמים דצריכי מחשבה אבל אי חשבינן ליה יין מכשיר בלא מחשבה וכו' ופרכינן וכיון דשפכינהו האי גברא להני מי גשמים ממנא שנטפו למנא דשמרים אחשבינהו ומכשרי ומאי נפקא לן מינה ל\\\"ש [מעשר] ל\\\"ש תרומה לעולם מכשרי. שנתמד מאליו שנפלו הגשמים לתוך השמרים והילכך בתרומה דראשון ושני דחשיב יין לענין הכשר נמי מכשרי אבל שלישי דחשיב מים לגבי תרומה לענין הכשר נמי מי גשמים ולא מכשרי דלא הוה בהו מחשבה. ופרכינן ואכתי מאי נ\\\"מ והא כיון דנגיד מושך. קמא קמא ראשון ושני גלי דעתיה דניחא ליה שירדו גשמים לכאן לעולם אולי יקלטו טעם יין ושלישי לתרומה נמי מכשר ולא שנא יין ול\\\"ש מים אכשורי מכשר ומה חילוק יש עדיין בהכשירן. בפרה ששותה ראשון ראשון והילכך בשלישי ליכא שום מחשבה ולא מכשר שלישי דתרומה ושני דמעשר. וכתב הרמב\\\"ן זה שהקשו בגמרא כיון דקא נגיד קמא קמא אחשביה כלומר כיון שהוציא ראשון ושני גלי אדעתיה דניחא ליה שירדו גשמים פעם אחרת. וכתבו התוספות ונתמד מאליו נראה דהשתא איירי שפיר אפילו במים יפים שאינם מי גשמים דכיון שנתערבו בשמרים אינם ראויים להכשיר עכ\\\"ל. וזה דעת רבינו שלא הזכיר מי גשמים. כתוב בספרי רבינו שנתמדתו והוא ט\\\"ס וצריך לכתוב במקומו שנתמדו:\",1,0],[8,379,14,1,\"פירות שירד הדלף לתוכן וכו'. פרק ה' דמכשירין וכחכמים:\",1,0],[8,379,14,2,\"המעלה פירותיו לגג וכו'. רפ\\\"ו דמכשירין.\",1,0],[8,379,14,2,\"ומ\\\"ש שיש להם מעשה דין תורה וכו' עד מחשבתו מועלת מדבריהם. בפרק קמא דחולין עלה י\\\"ג:\",2,0],[8,379,14,3,\"המעלה את האגודות וכו'. בפ\\\"ו דמכשירין ופי' בשביל שימתינו שיעמדו זמן ארוך ולא יפסדו והוי לשון המתנה:\",1,0],[8,379,14,4,\"המוליך חיטים לטחון וכו' החמרים שהיו עוברים וכו'. שם פ\\\"ג וכחכמים:\",1,0],[8,379,14,7,\"שק שהוא מלא וכו' עד הפירות שבצידן. שם פירוש דניחא ליה שיתלחלחו הפירות כדי שיראו גסים:\",1,0],[8,379,14,7,\"הרודה פת חמה וכו'. שם וכרבי יוסי פירוש ומיירי בפת שנילוש במי פירות שאינם מכשירין שאל\\\"כ הרי הוכשר משעת לישה. ומיירי בשלא ראו הפת עד אחר זמן ואינו ידוע אם היה עליו משקה טופח:\",2,0],[8,379,14,8,\"המרבץ את ביתו כו'. שם:\",1,0],[8,379,14,8,\"וכתב הראב\\\"ד ואם מחמת העריבה לא הוכשרו א\\\"א נראה לי אם נתנם בעריבה וכו'. לשון המשנה ואם מחמת עצמן אינם בכי יותן ורבינו כתב אם מחמת העריבה:\",2,0],[8,379,14,9,\"ומ\\\"ש הטומן בטיט הנגוב וכו'. שם הטומן בטיט הנגוב רבי שמעון אומר אם יש בו משקה טופח בכי יותן ומשמע לרבינו דליכא מאן דפליג עליה דרבי שמעון דטעמא דמסתבר הוא:\",1,0],[8,379,14,10,\"המרבץ את גורנו וכו'. שם פירש הרא\\\"ש דאין לחוש שמא טננו והוכשרו כי מרוב יובש הגורן המים נבלעים בקרקע ומדברי התוספתא נראה שאפילו היה משקה טופח עליהם כלומר מחמת עצם החרס אינם בכי יותן וכן נראה מדברי רבינו והטעם משום דלא ניחא ליה לאינש שישארו מים בגורן לפי שהם מזיקים הילכך אע\\\"פ שעכשיו שמח בחטים שנתן בו לא הוכשרו:\",1,0],[8,379,14,12,\"המרבץ את ביתו במים וכו'. תוספתא פ\\\"ב:\",1,0],[8,379,14,14,\"הנוער אגודה של ירק וכו' עד וזה על גבי זה. משנה פ\\\"ק דמכשירין וכבית הלל:\",1,0],[8,379,14,15,\"הנופח בעדשים וכו'. שם וכחכמים:\",1,0],[8,379,14,16,\"נשך באוכל ונפל האוכל הרי וכו'. בסוף פרק שלישי דטבול יום טהור שנגס מן האוכל ונפל על בגדיו ועל ככר של תרומה טהור ופירש שם רבינו לענין הכשר והם דבריו כאן:\",1,0],[8,379,14,16,\"היה אוכל זיתים פצועים וכו' עד שלא ברצון. שם:\",2,0],[8,379,14,17,\"עולשין שליקטן וכו'. ברייתא פ' העור והרוטב (חולין דף קכ״ח).\",1,0],[8,379,14,17,\"ומ\\\"ש ואם היתה עליהם משקה טופח וכו'. בתוספתא דטבול יום פ\\\"ה:\",2,0],[8,379,15,1,\"מים שבכלים מתמטאין וכו' אבל מים שבקרקעות וכו'. זה למד רבינו ממה שיבא בסמוך:\",1,0],[8,379,15,1,\"וכתב הראב\\\"ד הדרך הזאת שכתב רחוקה מכליותי וכו'. ומ\\\"ש לא מצאתי קבלת טומאה וכו'. אם כפי פירוש רבינו במשניות בפ\\\"ק דמקואות הוא נלמד מה צורך שנמצא כן במקום אחר:\",2,0],[8,379,15,1,\"ומ\\\"ש מה שאמרו אם לא הדיח טהור כבר פירשנו בתוספתא וכו' מפני שראה שמה ששנינו אם לא הדיח טהור א\\\"ש לפירוש רבינו נדחק לפרשו:\",3,0],[8,379,15,1,\"ומ\\\"ש רבינו אבל מים שבקרקעות כגון מי בורות שיחין ומערות וכו'. פ\\\"ק דמקואות שש מעלות במקואות זו למעלה מזו מי גבאים שתה טמא ושתה טהור טמא וכו' עד נפל לתוכן המת וכו' ושתה טהור טהור:\",4,0],[8,379,15,1,\"ומ\\\"ש בין שהיו שאובים. כ\\\"כ רבינו בפירוש המשנה בפרק הנזכר ולמד כן מדקתני מתניתין מי בורות:\",5,0],[8,379,15,1,\"וכתב הראב\\\"ד או שנפלו לתוכם משקים א\\\"א זהו תימה לדבריו כשהלך בהם הטמא אין רצון גדול מזה עכ\\\"ל וט\\\"ס הוא שלא הוה ליה לתפוס אלא באו שהלך בהם הטמא ויש לומר שטעם רבינו משום דדמי לעובר במים שנתבאר בפי\\\"ג שהמים שעל בשרו אינם תלושים ברצון לפי שאין כוונתו אלא לעבור לצד אחר ולא ליבלל במים וה\\\"נ דכוותה:\",6,0],[8,379,15,1,\"כתב עוד הראב\\\"ד נטמא הככר במים שבידיו א\\\"א ולמים שבידו למה להו רצון וכו'. וי\\\"ל שרבינו סובר דכיון שלא נטמא הככר כשנפל למים אם העלה מן המים שלא לרצון לא היה מטמא:\",7,0],[8,379,15,2,\"מי גבאים וכיוצא בהן וכו' ומקואות שאין בהם מ' סאה שנטמאו וירדו להם גשמים ורבו מי גשמים עליהם. כ\\\"ה הנוסחא האמיתית בדברי רבינו ובספרים יש חסרון הניכר והדין הוא בפ\\\"ק דמקואות כב\\\"ה. וכתב הראב\\\"ד א\\\"א אין במשנה שנטמאו וכו'. וי\\\"ל דמדקתני פסקו הגשמי' הקרובי' לעיר ולדרך טמאים והרחוקים טהורים עד שיהלכו רוב בני אדם והיינו משום דחיישינן שמא שתה טמא או מילא בכלי טמא כדפירש רבינו שמשון כי קתני בסמוך מאימתי היא טהרתו ממילא משמע דהיינו ממה שחששנו לו כששנינו הקרובים לעיר ולדרך טמאים ויפה כיון רבינו במה שכתב ונטמאו:\",1,0],[8,379,15,3,\"במה דברים אמורים בגבא שאפשר לשתות ממנה וכו'. בתוספתא בריש מקואות במה דברים אמורים בגבא שאפשר לשתות ולא יהא מקום פרסות רגליו ניכרות אבל גבא שאי אפשר לו לשתות עד שיהא מקום רגליו ניכרים מצא שם מקום פרסת רגלי אדם מקום פרסת רגלי בהמה גסה טמא מקום פרסת בהמה דקה טהור והטעם מבואר דמקום פרסת רגלי בהמה גסה איכא למיחש שאדם טמא רוכב על סוס או חמור בא לשם וירד ושתה מה שאין לחוש כן במקום פרסת בהמה דקה ופירוש רבינו בתוספתא זו נכון:\",1,0],[8,379,15,3,\"והראב\\\"ד כתב א\\\"א לישנא דתוספתא ולא יהיו מקום פרסות רגלים ניכרים בגבא אלא אם כן מקום פרסות רגלים ניכרים עכ\\\"ל טעמו שבתוספתא אינו מוזכר חילוק בין אפשר לשתות מהגבא לאי אפשר לשתות ממנו אלא בדוחק גדול ומנין לו לרבינו לחלק בכך וכבר כתבתי שדברי רבינו הם פירוש לדברי התוספתא וכבר אפשר שהיה דעת הרב רבי אברהם בן דוד לפרש התוספתא בגבא שאפשר לשתות ואין פרסות רגלים ניכרים היינו כגון שסביבותיו אבנים או סלעים שאין מקום פרסות רגלים ניכרים בהם וגבא שא\\\"א לו לשתות עד שיהא מקום רגלים ניכרים בהם היינו שסביבותיו מקום חול או טיט העבה שמקום פרסות רגלים ניכרים בהם ושוב אין צורך למה שחילק רבינו בין אפשר לשתות ממנו לא\\\"א לשתות ממנו אלא בדוחק שלא הוזכר בתוספתא:\",2,0],[8,379,15,4,\"חזקת טיט וכו'. תוספתא שם ופירש רבינו שמשון חזקת טיט כמו חקיקת טיט וכו' ורבינו גריס חזקת:\",1,0],[8,379,15,4,\"גבא שנפל לתוכו וכו'. גם זה שם ופירש רבינו שמשון שהקפהו שקפה השמן והסירו מעל גבי המים:\",2,0],[8,379,15,5,\"ומה שכתב שמן ושאר המשקים וכו'. נלמד מהדין שהזכיר בסמוך:\",1,0],[8,379,15,6,\"מי תמצית שלא פסקו וכו'. משנה שם:\",1,0],[8,379,15,7,\"מי שהיה אוכל תרומה וכו'. סוף פרק ח' דכלים וכרבי יוסי:\",1,0],[8,379,15,8,\"האשה שהיתה אוכלת וכו'. שם. וכתב הראב\\\"ד זו הנוסחא לא מצאתיה וכו'. ואיני יודע למה שיבש הגירסא כיון שלפירוש רבינו גירסת הספרים נכונה ודעת רבינו דאף על גב דרישא דמתניתין דקתני האשה שנטף חלב מדדיה וכו' מיירי באשה טמאה ותנור טהור סיפא דקתני היתה גורפתו והכה הקוץ וכו' מיירי בתנור טמא ואשה טהורה אוכלת תרומה:\",1,0],[8,379,15,8,\"ומ\\\"ש רבינו שהרי רצונה להוציא המשקה מפיה וכו'. זה הטעם צריך לנכוית ונתנה אצבעה לתוך פיה דאילו להכה הקוץ ויצא ממנה דם תיפוק ליה מפני הדם:\",2,0],[8,379,16,1,\"כל האגודות שבשווקים וכו' עד הרי הם בחזקת טומאה. פ\\\"ו דמכשירין:\",1,0],[8,379,16,2,\"ומ\\\"ש עם הארץ נאמן לומר לא הוכשרו. ירושלמי פ\\\"ב דדמאי:\",1,0],[8,379,16,3,\"ומ\\\"ש כל הדגים בחזקת מוכשרין. שם וכל הדגים בחזקת טומאה וכתב רבינו מפני שהוא אוכל מוכשר במים והידים ממשמשים בו הטמא והטהור:\",1,0],[8,379,16,3,\"הדגים בין שצדן בחרס וכו' עד לצודן בטהרה. תוספתא פרק שלישי דמכשירין:\",2,0],[8,379,16,4,\"כל הציר בחזקת מוכשרין. כתב הראב\\\"ד לשון המשנה בפ\\\"ו דמכשירין בחזקת טומאה והוא נכון יותר משלו עכ\\\"ל. וטעם רבינו ששינה להשמיענו טעם הטומאה שהוא מפני שהוא מוכשר על ידי שחזקתו שנותנים לתוכו מים וממילא משמע שהוא טמא וכמו שכתב לקמן בסמוך לפיכך חזקתו טמא:\",1,0],[8,379,16,4,\"ציר טהור שנפל לתוכו וכו'. שם דברי ראב\\\"י. וכתב הראב\\\"ד פירשו בפרק ג' דבכורות לפי שנחשדו עמי הארץ וכו'. טעמו דבפרק ג' דבכורות (דף כ\\\"ג ע\\\"ב) מייתי הא דאמר ראב\\\"י ציר טהור שנפל לתוכו מים כל שהוא טמא ואמר רב נחמן עלה זאת אומרת נחשדו עמי הארץ לערב מחצה בציר ופריך עלה ולמה לי מחצה אפילו בציר ממחצה נמי והני משהו הו\\\"ל פלגא ופלגא לא בטיל ומשני אימא עד מחצה ואי בעית אימא טומאת ע\\\"ה דרבנן וטומאת משקין דרבנן ברובא גזרו רבנן בפלגא ופלגא לא גזרו ופירש\\\"י ציר טהור כגון שהשיקו במים שנפל לתוכו מים כל שהן טמא כדמפרש נחשדו עמי הארץ לערב מים בצירן וכי נפיל ביה כל שהוא מצא מין את מינו ורבו מים על הציר וטמאים ולמאן דלית ליה טומאה שבטלה חוזרת ונעורת מוקי לה שנפלו בה לאחר השקה מי ע\\\"ה כל שהוא. עד למחצה קרוב למחצה עכ\\\"ל. ולדבריו הסכימו התוספות ומדברי רבינו כאן לא משמע דהוי טעמא משום דחזקה שהיו בו מים מקודם וע\\\"י הני מים כל שהוא הוי רובא מים אלא אע\\\"פ שידענו שאין בו מים אחרים אלא אלו בלבד מכשיר ומשיג עליו דהא דלא כרב נחמן והא ודאי השגה גדולה היא שיפסוק הוא הפך הגמרא וליישב דברי רבינו צריך לומר דודאי בציר סתם שחזקתו שהיה בו מים מיירי והשיקו וטהר וכדברי רש\\\"י והיינו טעמא דטמא משום דע\\\"י מים כל שהוא ניעורו המים הראשונים וכר\\\"נ אלא שקיצר ולא הזכיר הטעם כמנהגו בכמה מקומות להשמיט טעם הדבר ואע\\\"פ שבפירוש המשנה כתב שאין שם מים אלא הני כל שהוא לא נחוש כיון שהם היפך הגמרא ונעמיד דבריו בחיבור בענין שיסכימו לדברי הגמ':\",2,0],[8,379,16,4,\"נפל לתוכו יין וכו'. תוספתא ספ\\\"ק דמכשירין ובספרי רבינו כתוב מים וט\\\"ס הוא וכן מצאתי בספר מוגה:\",3,0],[8,379,16,4,\"וכן מי פירות שנתערבו וכו' נתערבו במים וכו'. כתב הראב\\\"ד א\\\"א אין זה לא במשנה ולא בתוספתא וכו'. ורבינו אפשר שהיתה גירסתו בתוספתא ספ\\\"ק דמכשירין הפוכה מגירס' הראב\\\"ד וגירסתנו היה שונה מי פירות שנפל לתוכם מים הולכים אחר הרוב דברי ר\\\"מ וחכמים אומרים אפילו נפלו לתוכם מים כל שהם טמאים ופסק כחכמים:\",4,0],[8,379,16,4,\"וציר חגבים טמאים וכו'. בפ\\\"ז דעדיות ובפרק י' דתרומות העיד רבי צדוק על ציר חגבים טמאים שהוא טהור וקאמר עלה בירושלמי מאי טהור טהור מלהכשיר הא לטמא מטמא ורבינו מפרש לה בניחותא ולפרושי מתניתין אתא והראב\\\"ד מפרש לה בלשון בעיא וקשה לי על פירוש זה מהיכן עלה בדעתו להסתפק בכך כיון דטהור סתמא קתני בכל גווני משמע ואפשר דמפני שהם טמאים הוקשה לו היאך יהא צירן טהור ומפני כך נסתפק שמא מאי טהור טהור מלהכשיר אבל מטמא הוא או שמא טהור לגמרי קאמר משום דזיעה בעלמא הוא:\",5,0],[8,379,16,4,\"ומה שכתב הראב\\\"ד וא\\\"כ לענין טומאה לאו משקה הוא וכו' דמשמע דפשיטא ליה דאינו מטמא קשה דאם כן הרי עלתה בבעיא בירושלמי ונראה דלא כתב הראב\\\"ד אלא לצד אחד מצדדי הבעיא:\",6,0],[8,379,16,5,\"הלוקח ציר מעם הארץ וכו'. פרק ג' דבכורות עלה כ\\\"ב:\",1,0],[8,379,16,5,\"ומ\\\"ש בספרי רבינו ואם היה רובו מלח של דגים. בספר כתיבת יד נמצא ואם היה רובו מליחה של דגים והיא גירסא נכונה:\",2,0],[8,379,16,6,\"הפירות בכל מקום וכו'. הכי משמע בתוספתא סוף מכשירין:\",1,0],[8,379,16,7,\"ומ\\\"ש האוג בכ\\\"מ וכו' וכן כל הקישואים והדילועים וכו'. שם:\",1,0],[8,379,16,8,\"כל הכתוב בתורה וכו'. בפרק ב' דחולין (דף ל\\\"ד ע\\\"ב) גבי הא דאמרינן ואי אמרת נפסל גופו מלאכול ומי ספינן ליה מידי דפסיל לגופיה כן כתב רש\\\"י בפירוש ראשון וכן דעת התוספות:\",1,0],[8,379,16,9,\"כשם שמותר לאכול וכו' כך מותר לגרום טומאה וכו'. בפ\\\"ד דע\\\"ז עלה נ\\\"ה בראשונה היו אומרים אין בוצרין עם העכו\\\"ם בגת שאסור לגרום טומאה לחולין שבא\\\"י וכו' חזרו לומר וכו' בוצרין עם העכו\\\"ם בגת שמותר לגרום טומאה לחולין שבא\\\"י.\",1,0],[8,379,16,9,\"ומ״ש ויש לו לטמא את החולין המתוקנין. כלומר הא דאמרי' דלגרום דוקא מותר אבל לטמא אותם להדיא לא הני מילי כשאינם מתוקנים עדיין ומשום תרומה שבהם אבל אם הם מתוקנים להדיא נמי מותר לטמאם. וצ״ע דבפ״ק דנדה עלה ו' אמרינן איפכא עיין שם ובסוף פרק הניזקין (גיטין דף ס״ב) ובפירש״י פרק כשם (דף ל' ע״ב) בד״ה מאי לאו:\",2,0],[8,379,16,9,\"וכן מותר לאדם ליגע בכל הטומאות וכו'. פ\\\"ק דר\\\"ה (דף י\\\"ו ע\\\"ב) ובת\\\"כ:\",3,0],[8,379,16,9,\"ומ\\\"ש ואף כהנים ונזירים מותרים להתטמא בשאר טומאות וכו'. זה פשוט שלא הוזהרו בתורה אלא מטומאת מת:\",4,0],[8,379,16,10,\"כל ישראל מוזהרים וכו'. בפ\\\"ק דר\\\"ה (דף ט\\\"ז:):\",1,0],[8,379,16,10,\"ומ\\\"ש ואם נטמא אינו לוקה. בת\\\"כ ובנבלתם לא תגעו ברגל וקתני עלה אחרים אומרים יכול אם נגע בנבילה ילקה ת\\\"ל ולאלה תטמאו הוי אומר רשות ומשמע לרבינו דלתנא קמא נמי אינו לוקה ברגל:\",2,0],[8,379,16,11,\"הטמא והטהור יחדיו מפי השמועה למדו וכו'. בספרי.\",1,0],[8,379,16,11,\"ומה שכתב אבל לא יאכל הבעל עם אשתו וכו'. משנה בפרק קמא דשבת (דף י\\\"א) לא יאכל הזב עם הזבה מפני הרגל עבירה:\",2,0],[8,379,16,11,\"וכתב הראב\\\"ד אנו אומרים אפילו על שלחן אחד במפה אחת אסור. ואין זו השגה על רבינו שהוא מפרש דמאי דתנן לא יאכל הזב עם הזבה היינו בקערה אחת ועל שלחן אחד במפה אחת חומרא בעלמא הוא לענין איסור למאן דסבר הכי:\",3,0],[8,379,16,12,\"אע\\\"פ שמותר לאכול וכו' חסידים הראשונים היו אוכלים חולין בטהרה וכו'. משנה בספ\\\"ב דחגיגה (דף י\\\"א ע\\\"ב).\",1,0],[8,379,16,12,\"ומ\\\"ש שהפרישות מביאה לידי טהרת הגוף וכו'. בפ\\\"ק דע\\\"ז (דף כ' ע\\\"ב) ונוסחת רבינו כדאיתא בירושלמי פ\\\"ג דשקלים:\",2,0],[8,379,16,12,\"סליקו הלכות טומאת אוכלין\",3,0],[8,380,1,1,\"שבעה מיני כלים הם וכו':\",1,0],[8,380,1,2,\"ומה שכתב מפי השמועה למדו שזה שנאמר בתורה וכל מעשה עזים וכו'. בספ\\\"ק דחולין (דף כ\\\"ה ע\\\"ב) מה ת\\\"ל וכל מעשה עזים תתחטאו להביא דבר הבא מן העזים מן הקרניים ומן הטלפיים שאר בהמה וחיה מנין תלמוד לומר וכל מעשה עזים א\\\"כ מה תלמוד לומר עזים פרט לעופות.\",1,0],[8,380,1,2,\"ומה שכתב חוץ מכלים העשויים מכנף העזניה בלבד וביצת הנעמית המצופה. בפי\\\"ז דכלים:\",2,0],[8,380,1,3,\"כלים העשויים מעצמות חיה שבים וכו' עד הכל מקבל טומאה. שם:\",1,0],[8,380,1,5,\"כלי זכוכית וכו'. בפ\\\"ק דשבת (דף י\\\"ו ע\\\"ב) כלי זכוכית מ\\\"ט גזור בהו רבנן טומאה וכו' עד הואיל ונראה תוכו כברו ופירש\\\"י וכו':\",1,0],[8,380,1,5,\"וכתב הראב\\\"ד אין זה הטעם על דרך ההלכה וכו'. פשטא דגמרא כהראב\\\"ד ולדעת רבינו י\\\"ל שהוא סובר שכשהקשו אלא מעתה לא ליטמו מגבן בכלל זה הוא שיתטמאו מאוירן ככלי חרס וכי שני רב אשי הואיל ותוכו נראה כברו הוי נמי טעמא בין לשמטמאים מגבן בין מאוירן דכיון דלא דמו לכלי חרס שאין תוכן נראה כברן וכלי זכוכית תוכן נראה כברן אין לדמותן לגמרי לכלי חרס ושלא כפירש\\\"י:\",2,0],[8,380,1,6,\"כלי גללים וכלי אבנים וכלי אדמה וכו'. מנחות פרק רבי ישמעאל עלה ס״ט ע״ב ושבת ר״פ במה אשה (שבת דף נ״ח) ובכמה דוכתי ופירוש כלי גללים כלים העשויים מגללי בהמה ופי' כלי אדמה כלי חרס עד שלא הוסק בכבשן:\",1,0],[8,380,1,8,\"פיל שבלע הוצין וכו'. מנחות פ' רבי ישמעאל (מנחות ס״ט.) בעיא דלא איפשיטא.\",1,0],[8,380,1,8,\"ומ\\\"ש אבל כפיפה שנטמאת וכו'. שם:\",2,0],[8,380,1,8,\"פשוטי כלי חרס וכו'. פ\\\"ב דכלים.\",3,0],[8,380,1,8,\"ומ״ש ולא טומאת מדרס. בפרק ר״ע עלה פ״ד ופרק על אלו מומין (בכורות דף ל״ח).\",4,0],[8,380,1,8,\"ומ\\\"ש ולא מד\\\"ס:\",5,0],[8,380,1,9,\"כלי מתכות אחד פשוטיהן וכו'. רפ\\\"א דכלים ופ\\\"ק דחולין (דף כ\\\"ה) ופרק קמא דשבת (דף ט\\\"ז).\",1,0],[8,380,1,9,\"ומה שלמדה רבינו מדכתיב בכל דבר. בסיפרא.\",2,0],[8,380,1,9,\"ומ\\\"ש אפילו תיבה וכו' שהם מקבלים מ' סאה וכו'. תוספתא ריש פרק פי\\\"א דכלים וטעמא משום דכלי מתכות לא איתקש לשק:\",3,0],[8,380,1,10,\"כלי עץ וכלי עור וכלי עצם וכו'. רפ\\\"ב ורפט\\\"ו דכלים כלי עץ וכלי עור וכלי עצם פשוטיהם טהורים ומקבליהם טמאים.\",1,0],[8,380,1,10,\"ומ״ש שפשוטיהם מקבלים טומאה מד״ס. בפרק המוכר את הבית (בבא בתרא דף ס״ו) שאני פשוטי כלי עץ דטומאה דמדרבנן וכדעת התוספות שסוברים דקושטא דמילתא הכי הוא ומכ״מ יש כלי עץ שאינן מקבלים טומאה אפילו מדרבנן כמבואר בפ״ד וכאן רמז וכתב כגון הלוחות והכסא.\",2,0],[8,380,1,10,\"ומ״ש מפי השמועה למדו וכו' וכן מ״ש בד״א שטומאת פשוטיהם מד״ס וכו' אבל במדרס הזב וחביריו מתטמאין מן התורה וכו'. פרק על אלו מומין (בכורות דף ל״ח) והא דומיא דשק בעינן וכו' בהנך דחזו למדרסות ופרק רבי עקיבא (שבת דף פ״ד) אמרינן דכיון דכתיב וכל המשכב דרשינן כל שיש במינו טהרה במקוה מטמא מדרס.\",3,0],[8,380,1,10,\"ומ\\\"ש רבינו שכלי עור פשוטיהם מקבלים טומאה מדרבנן הוא מפני מה שהוזכרו בפי\\\"ו דכלים פשוטי כלי עץ שמקבלים טומאה וכתב שם שהם בכלל מה שאמרו בגמרא פשוטי כלי עץ מדרבנן ירצה כלי עץ ושאר המנויים עמו שאינם מקבלים טומאה מדאורייתא.\",4,0],[8,380,1,10,\"ומ\\\"ש וכן כלי זכוכית וכו'. בתוספתא כל מדרס כלי זכוכית טהורים ור\\\"ש גורס טמאים והיא גירסת רבינו:\",5,0],[8,380,1,11,\"כל שהוא ארוג וכו'. בפרק במה אשה (שבת דף ס״ד) אטו בגד לאו ארוג הוא וכו' ור״פ התכלת (מנחות דף ל״ט ע״ב) ובפ״ב דשבת (דף כ' ע״ב) מדברי תנא דבי רבי ישמעאל שירים וכלך וכו' מאו בגד.\",1,0],[8,380,1,11,\"ומה שכתב והלבדים וכו'. בסיפרא פ\\\"ח ובתוספתא דכלים פרק ה' דב\\\"ב:\",2,0],[8,380,1,12,\"השק הוא חוטי שיער וכו' אבל החבלים והמשיחות וכו'. בפרק במה אשה עלה ס\\\"ד ובת\\\"כ:\",1,0],[8,380,1,13,\"כל הכלים העשויים וכו'. בפרק קמא דכלים קרי למפץ כלי עץ ובפרק י\\\"ו קרי כלי עץ לסלים של עץ ושל תמרה וכוורת הקש וכוורת הקנים וקנונית וקלתות והם עשויים מערבה דקה וסוגין והם קופות:\",1,0],[8,380,1,13,\"אחד כלי חרס וכו'. בריש פרק ב' דכלים.\",2,0],[8,380,1,13,\"ומה שכתב כל כלי העשוי מהעפר וכו' כן כתב רבינו שם.\",3,0],[8,380,1,13,\"ומה שכתב והתנור והכיריים וכו'. פשוט הוא:\",4,0],[8,380,2,1,\"העושה כלי קיבול וכו'. בפ' י\\\"ז דכלים.\",1,0],[8,380,2,1,\"ומ\\\"ש אבל העושה כלים מן הלפת כו'. תוספתא פ\\\"ז דכלים ב\\\"מ:\",2,0],[8,380,2,2,\"קנה מאזנים וכו'. שם.\",1,0],[8,380,2,2,\"ומה שכתב ואין טמא וכו' והמשמש את בית הקיבול וכו'. בתוספתא פרק ז' דכלים בבא מציעא:\",2,0],[8,380,2,3,\"בית קיבול העשוי למלאות וכו'. שם מפני מה תחתית הצורפים טמאה ושל נפחים טהורה.\",1,0],[8,380,2,3,\"ומ\\\"ש מפני שהם מגביהים את הברזל וכו'. תוספתא שם:\",2,0],[8,380,2,3,\"וכתב הראב\\\"ד א\\\"א לשון המשנה תחתית הצורפין טמאה וכו'. ואם כוונתו לומר ששינה לשון המשנה זה שינוי לטובה הוא כי ביאר דבריה:\",3,0],[8,380,2,3,\"כתב עוד הראב\\\"ד ואם היתה של צורפים א\\\"א תוספתא מפני מה תחתית של צורפים וכו'. משיג על רבינו למה השמיט סוף לשון התוספתא וי\\\"ל דממילא משמע דזיל בתר טעמא:\",4,0],[8,380,2,4,\"הכף החקוק וכו'. בתוספתא דכלים ב\\\"מ פ\\\"ח חמור שתחת המלבן והספסלים שתחת הרגלים טהורים כפותין שתחת הרגלים אע\\\"פ שחקוקים ומקבלים טהורים ואין בהם משום קיבול:\",1,0],[8,380,2,4,\"שפופרת הקש וכו'. משנה סוף פרק י\\\"ז דכלים וכר\\\"ע מחבירו.\",2,0],[8,380,2,4,\"ומ\\\"ש אפילו אינה יכולה לקבל אלא טיפה אחת. פשוט הוא דשפופרת הקש הכי הויא:\",3,0],[8,380,2,5,\"שפופרת (הקנה) שחתכה וכו'. תוספתא פי\\\"ד דכלים אלא שיש בה חסרון וגם היא כתובה בשיבוש:\",1,0],[8,380,2,5,\"וכתב הראב\\\"ד קשיא לי מה ששנינו בכלים פי\\\"ו וכו' והר\\\"י קורקוס ז\\\"ל תירץ דבית המזוזה דתנן התם מיירי שאינה ראויה לקיבול שום דבר כ\\\"א לשום בו מזוזה:\",2,0],[8,380,2,6,\"כלי שאורגים אותו וכו'. משנה ס\\\"פ כ\\\"ב דכלים קנקילון שיש בה בית קיבול כסות טמאה העשויה ככוורת טהורה:\",1,0],[8,380,2,7,\"סנדל של בהמה וכו'. שם פי״ד ואיתא בפרק במה אשה (שבת דף נ״ט):\",1,0],[8,380,2,8,\"הצורר מרגלית וכו'. שם פרק כ\\\"ו.\",1,0],[8,380,2,8,\"ומה שכתב אבל צרור המעות. שם וכתנא קמא ואיתא בסוף פרק ארבע מיתות (סנהדרין דף ס\\\"ה) וכתב רבינו בפירוש המשנה אולם כאשר כיס מעות בעור זה הנה מקומו (ואע\\\"פ) בית קיבול אין עליו תמונת כיס מטעם פירוד המעות:\",2,0],[8,380,2,8,\"וכתב הראב\\\"ד א\\\"א תוספתא צרור מרגלית בזמן שתוכו טמא וכו'. נ\\\"ל שפי' התוספתא כשנוטל ממנו המרגלית אם ניכר שיש לו תוך טמא ואם אינו ניכר לו תוך אלא הוא פשוט טהור.\",3,0],[8,380,2,8,\"ומה שכתב נראה מן הענין הטעם וכו'. זהו טעם לדברי המשנה שטימאה בצרור המרגלית וטיהרה בצרור המעות:\",4,0],[8,380,3,2,\"כל כלי עץ וכו'. בסוף חגיגה (דף כ\\\"ו ע\\\"ב) גבי שלחן ותיפוק לי דכל עץ העשוי לנחת הוא וכל כלי עץ העשוי לנחת לא מיטמא מ\\\"ט דומיא דשק בעינן מה שק מיטלטל מלא וריקן אף כל מיטלטל מלא וריקן ופירש\\\"י כלי עץ העשוי לנחת במקום אחד. דומיא דשק בעינן לענין טומאה הוקשו כלי עץ לשק דכתיב כל אשר יפול עליו מהם במותם יטמא מכל כלי עץ או בגד או עור או שק. מה שק מיטלטל מלא וריקן יצא העשוי לנחת דאינו מיטלטל מלא וריקן יצא כלי עץ המחזיק ארבעים סאה בלח שהם כוריים ביבש אף על פי שמיטלטל ריקן אינו מיטלטל מלא שאם יטלטלנו מלא ישבר עכ\\\"ל:\",1,0],[8,380,3,2,\"ומה שכתב רבינו וכל כלי עץ שהוא [עשוי] להתטלטל מלא וריקן וכו' וכל כלי עץ שהוא סתם וכו' עד ולפיכך אינם מקבלים טומאה. משנה פרק ט\\\"ו דכלים השידה והתיבה והמגדל וכו' שיש להם שוליים והם מחזיקים ארבעים סאה בלח שהם כוריים ביבש הרי אלו טהורים ושאר כל הכלים בין מקבלים בין שאינם מקבלים טמאים דברי רבי מאיר רבי יהודה אומר דרדור עגלה וקסטות המלכים ועריבת העבדנין ובור ספינה קטנה והארון אף על פי שמקבלים טמאים שאינם עשויים לטלטל אלא במה שבתוכן ושאר כל הכלים המקבלים טהורים שאינם מקבלים טמאים:\",2,0],[8,380,3,2,\"וכתב הראב\\\"ד דבר זה איני יודע מאין הוציאו וכו' ואינו מחוור דהתם איסורא נמי איכא בטלטולם וכו'. איני יודע מה איסור יש בטלטולם ועוד דאפילו אם היה איסור בטלטולם מכל מקום כי ממעטינן משק כלי העשוי לנחת משום דאין דרכו ליטלטל מלא וריקן הוא אף על פי שלא יהא איסור בדבר דומיא דמחזיק ארבעים סאה בלח דממעטינן ליה אף על גב דליכא איסור בטלטולו. ומה שכתב אולי לא כמו שהוא סובר וכו' אין השגה באולי והראיה שהביא אינה מכרחת. ומה שכתב על כל כלי עץ שהוא עשוי לטלטל מלא וריקן אפילו מחזיק מאה סאה מיטמא:\",3,0],[8,380,3,3,\"השידה והתיבה והמגדל של זכוכית וכו' ושאר כלי זכוכית וכו'. כתב הראב\\\"ד ושאר כלי זכוכית א\\\"א אמת כך מצא בתוספתא וכו':\",1,0],[8,380,3,4,\"כל כלי שיש בשיבורו אמה על אמה וכו'. תוספתא דכלים פ\\\"ה דב\\\"מ:\",1,0],[8,380,3,4,\"וכשמודדין הכלי מודדין אותו מבחוץ וכו'. רפי\\\"ח דכלים וכב\\\"ה:\",2,0],[8,380,3,5,\"היה בתוך הכלי תיבה קטנה וכו'. שם:\",1,0],[8,380,3,5,\"כתב הראב\\\"ד היה בתוך הכלי תיבה קטנה א\\\"א מעולם לא שמענו מוכני פירושו תיבה וכו'. וליישב דעת רבינו י\\\"ל דלא שמענו אינה ראיה:\",2,0],[8,380,3,6,\"ומ\\\"ש היו בו מגורות וכו'. תוספתא דכלים פ\\\"ח דב\\\"מ:\",1,0],[8,380,3,7,\"כלי עץ שאינו מקבל וכו':\",1,0],[8,380,3,8,\"השידה והתיבה וכו'. משנה פרק י\\\"ח דכלים:\",1,0],[8,380,4,1,\"שלש מדות בכלי עץ וכו'. תוספתא פי\\\"ג דכלים.\",1,0],[8,380,4,1,\"ומ\\\"ש וכל כלי עץ העשוי לתשמיש הכלים בלבד שהרי הוא משמש משמשי אדם וכו'. במשנה פי\\\"ו דכלים.\",2,0],[8,380,4,1,\"ומ\\\"ש כגון מנורה של עץ וכו'. בתוספתא פרק י\\\"ג דכלים ובת\\\"כ שם הקולב והמנורה והנחותא מפרש רבינו בפי' המשנה פרק י\\\"ו דכלים נחותא היא חתיכת עץ תושם תחת הכלים תושבת להם וכאן פי' שהוא כלי שמניחים תחת הכלים, וקולב פי' שהיא הדפוס וכן הוא בלשון ערב.\",3,0],[8,380,4,1,\"ומ\\\"ש כגון כיסוי הקפצה וכו' עד בשעת מלאכה בלבד. משנה פי\\\"ו דכלים:\",4,0],[8,380,4,1,\"וכתב הראב\\\"ד והקלב שבונים עליו תיק לספר א\\\"א לא ידעתי מהו זה וכו'. ואני אומר שרבינו כתב שזהו אנגלין של ספר השנוי שם במשנה. ומ\\\"ש אבל מנו אותן בת\\\"כ כבר כתבתי שרבינו מפרש שקולב הוא דפוס בלשון ערב ולכן כלל כל הדפוסים בלשון קלב ובמשנה קרא לדפוס של תיק אנגלין של ספר ולדפוס של מצנפת אימום של גודלי מצנפות ולדפוס התפילין תפוס של תפלה:\",5,0],[8,380,4,1,\"כתב הראב\\\"ד מפני שהם משמשי הכלים א\\\"א יש מאלו הרבה מפני שהכלים עצמם משמשים עם הקרקע וכו'. ורבינו סובר שאין צורך לזה מאחר שהם משמשי הכלים בשעת המלאכה בלבד:\",6,0],[8,380,4,2,\"מלבן המטה וכו'. תוספתא פרק ט\\\"ו דכלים רבינו בפירוש המשנה פרק י\\\"ח דכלים פירש כל חלקי המטה ודבר ידוע כי כל דבר עגול ובולט נקרא פיקא ואפשר שזה המלבן מורכב בפיקות ויש לו רגלים מתרכבים במטה ועל ידיהם מתחבר עמה והרי הוא כאבר מאיבריה אבל אם הוא מונח על אותם שנקראו לשונות אע\\\"פ שמסורג בחבלים אין זה חיבור כי אינו נקרא חיבור רק כשיש לו רגלים ומורכב בהם עם המטה וחלוקה זו היא סיפא דמתניתין (דף כ\\\"ט) דקתני מלבן שנתנו על לשונות רבי מאיר ורבי יהודה מטמאים ר' יוסי ור' שמעון מטהרים וסיפא דתוספתא הכי איתא במסורג בחבלים ואין לו רגלים ר' מאיר ור' יהודה מטמאים ר' יוסי ור' שמעון מטהרים שאין עושין מלאכה בגופו והאי סיפא דתוספתא היא סיפא דמתניתין ותרווייהו חדא פלוגתא היא דמלבן שנתנו על לשונות דמתניתין היינו מסורג בחבלים דתוספתא והכוונה דהיכא דלא הוי מלובש בפיקות ויש לו רגלים אפילו שמסורג בחבלים והיינו נתון שנתון על הלשונות אינו חיבור ודמי למלבני בני לוי שהם טהורים כי עתה אינם חלק מהמטה אלא בפני עצמם הם חשובים ונראה מדברי רבינו כי כשהוא על הלשונות להיותו גבוה מהמטה יש מקום וטעם יותר לטהר מברישא שאינו על הלשונות כי אם למטה בפיקות ומחובר על ידי הכלים דהוי בפני המטה וכמטה עצמו הוא:\",1,0],[8,380,4,2,\"נתנו על שתי לשונות וכו'. משנה פרק י\\\"ח דכלים כרבי יוסי ור\\\"ש לגבי ר\\\"מ ור\\\"י:\",2,0],[8,380,4,2,\"כתב הראב\\\"ד מפני שהוא ממשמשי הכלים א\\\"א לישנא דתוספתא וכו'. ולרבינו יש לומר שמאחר שמצא טעם נכון לא הוצרך לטעם התוספתא ועי\\\"ל שרבינו מפרש התוספתא דאינו עושה מלאכה בגופו היינו שאינו עושה מלאכה תמיד אף שלא בשעת מלאכה:\",3,0],[8,380,4,3,\"מכבש של אושכף וכו'. תוספתא סוף פרק י\\\"ט דכלים והוא פרק ראשון דבבא בתרא:\",1,0],[8,380,4,3,\"כתב הראב\\\"ד מכבש של שכף פירוש אושכף א\\\"א זו המימרא מצאתיה בתוספתא דכלים לטהר וכו':\",2,0],[8,380,4,4,\"חפויי המטה טהורים וכן כל החיפויין וכו'. משנה בספי\\\"ו דכלים ובת\\\"כ פרשת שמיני מייתי לה מדכתיב אשר יעשה מלאכה בהם פרט לחיפויי הכלים:\",1,0],[8,380,4,4,\"וכן כלי עץ או עצם וכו'. בסוף חגיגה (דף כ״ו ע״ב) ופרק שתי הלחם (מנחות דף צ״ו ע״ב):\",2,0],[8,380,4,4,\"וכתב הראב\\\"ד א\\\"א לא ידעתי מהו ולא מצאתי לזה שורש ואדרבא ראוי להיות בהיפך כו' ורבינו בפי\\\"א ממסכת כלים אהא דתנן קלוסטרא טמאה ומצופה טהורה כתב אם היה זאת הקלוסטרא מאחד מאלו המתכות הנה היא תקבל טומאה מפני שההיא יש לה שם בפ\\\"ע ואם היתה מעץ והוא מחופה מברזל וכו' ויש לתמוה עליו דממקום שבא הוי איפכא דהא בסוף חגיגה אהא דתנן כל הכלים שהיו במקדש טעונים טבילה חוץ ממזבח הזהב ומזבח הנחשת מפני שהם כקרקע דברי ר\\\"א וחכ\\\"א מפני שהם מצופין איתא בגמרא (דף כ\\\"ז) מזבח הנחשת דכתיב מזבח אדמה תעשה לי מזבח הזהב דכתיב המנורה והמזבחות איתקש מזבחות זה לזה מפני שהם מצופים אדרבא כיון דמצופים נינהו מטמו אימא וחכמים מטמאים מפני שהם מצופין ואבע\\\"א רבנן לר\\\"א קאמרי מאי דעתך משום דמצופין בטיל ציפויין גבייהו ופירש\\\"י אדרבה משום דמצופין נינהו נטמאו וכו' עד ובלאו האי קרא נמי לא מקבלי טומאה הרי בהדיא דמשום דמצופין נינהו מטמאו אף ע\\\"פ שלא היו ראויים ליטמאות מעצמן והיאך רבינו כותב בהיפך ולא עוד אלא שמביא ראיה מסוף חגיגה האמור שם היפך דבריו וצ\\\"ע וההיא קלוסטרא מצופה טהורה כבר פירשה ר\\\"ש דה\\\"ק אם נעשה הקלוסטרא מברזל טהור וציפוייה ממתכת טמא כמו שמזהיבים כלי כסף לנוי טהורה דבתר עיקר אזלינן וכתב הר\\\"י קורקוס ז\\\"ל שיטת הראב\\\"ד כשיטת רש\\\"י ז\\\"ל באותה סוגיא אבל רבינו מפרש אותה כי כמו שהקושיא הראשונה שהקשה ות\\\"ל דעשוי לנחת הכוונה היא להקשות על המשנה שאמרה הזהרו שלא תגעו דאי נמי יגעו לא מטמאי להו הכי נמי הדר פריך עלה דא\\\"נ לאו לנחת הוא כדתרצת דמגביהין אותו אכתי ת\\\"ל דאפילו נגעו לא מטמאי ליה משום דכלי בטל אגב ציפוי כדתנן השלחן וכו' והציפוי נמי לא מטמא כדתנן וכדיליף לה בת\\\"כ ולפי זה שחיפן בשיש דקתני לאו דוקא והשתא פריך דומה בדומה דכי היכי דהתם בטל הכלי וטהור הכא נמי הכא בטל וטהור כי כל החיפויים טהורים אפילו של מתכת דאע\\\"ג דלא איתקש לשק היינו כי הוי כלי פשוט אבל חיפוי לאו כלי הוא וטהור דכולהו ציפויין נתמעטו דהוו עראי ומשני שאני שלחן דלא בטל דרחמנא קרייה עץ והלכך מטמא אע\\\"פ שיש עליו חיפוי מה שאין כן בשאר כלים דודאי בטלי לגבי ציפוי וטהורים כיון שהציפוי טהור והכלי מצופה כולו בדבר הטהור זו היא שיטת רבינו באותה סוגיא וניחא שפיר מאי דפריך ותיפוק ליה משום ציפוי דהדר פריך שנית על המשנה דאילו לשיטת רש\\\"י והראב\\\"ד דכיון שכבר העלינו שאינו עשוי לנחת והילכך מיטמא מאי הדר פריך דאפילו עשוי לנחת טמא ומאי נ\\\"מ בהאי קושיא כיון דבלאו הכי איתרצא שפיר וכל ההיא סוגיא ושקלא וטריא לא נ\\\"מ מידי ולדעת רבינו תרי ותיפוק לי דפריך מתפרשי בחד גוונא אלא שקשה מה שאמרו שם בחגיגה עלה דמתניתין דקתני כל הכלים שהיו במקדש טעונים טבילה חוץ ממזבח הזהב ומזבח העולה מפני שהם כקרקע דברי רבי אליעזר וחכמים אומרים מפני שהם מצופים ופריך בגמרא עלה אדרבא כיון דמצופין נינהו מטמאו ומשני אימא וחכמים מטמאים מפני שהם מצופין ואבע\\\"א רבנן לרבי אליעזר קאמרי וכו' מוכח מהאי סוגיא שהציפוי סבה ליטמא כדברי רש\\\"י וריב\\\"א וצריך לדחוק לשיטת רבינו דאע\\\"ג דלתירוצא קמא ודאי בהכי הוא וכס\\\"ד דמקשה מכל מקום אפשר דתירוצא בתרא לא סבר הכי וכוונת אמרם מבטל בטיל ציפויין לגבייהו כלומר אתה סובר דמשום ציפוי ליטמא יותר והוא בהיפך דציפויין לא מיטמאו דבטלים אגב כלי דלא חשיבי כדי שיטמא הכלי בשבילו והכלי בשביל עצמו ודאי אינו מטמא כיון שמצופה והלכך מפני שהן מצופין לא מיטמו ואין צריך טעם אחר ולא בטיל ציפוייהו לא אהני דוקא קאמר אלא אכולהו כלים המצופין קאמר ואתא מתניתין כפשטה וחכ\\\"א הטעם שאין מטמאים מפני שהם מצופין וקושיא אדרבא ליתא דהמקשה הוה סבר הכי ותירוצא בתרא סבר איפכא עכ\\\"ל:\",3,0],[8,380,4,7,\"העושה כלי מקצתו וכו' עד הרי אלו מקבלים טומאה. משנה בסוף פי\\\"ג דכלים:\",1,0],[8,380,4,7,\"ומה שכתב וכן המעבד והמזרה וכו'. שם וכתב רבינו דשלשה כלים אלו הם כלי הגרן והם כדמיון כף האדם יבורו בו החטים והשעורים ויתחלפו שמותם כפי התחלפות תמונתם כי מהם רוב השינים יבורו בו החטים בסוף הענין וממנו מעט השינים אין לו כי אם שלש שינים לבד יבורו בו החטים בתחלת הענין מהתבן הגס והוא המעבד ורבת שינים ממנו המזרה והיותר רב השינים מהם מגוב עכ\\\"ל:\",2,0],[8,380,4,10,\"מקל שעשה בראשו מסמר וכו'. פרק י\\\"ד דכלים מקל שעשה בראשו מסמר כמין חזיינא טמא סימרו וכו' טמא וכולן שעשאן לנוי טהורים ופירש רבינו יעשו בראש המקלות חתיכת ברזל עגולה דומה לרמון ונקראת חזיינא וכו' ויקראו אותה אלרמוס וכן ינעצו מסמרים בראשי המקלות להיות ההכאה בהם יותר חזקה וכו' ועשאן לנוי הוא שיעשו לייפות בו את המקל ורוב מה שיעשו זה במסמרים דקים מצויירים בבדיל לבן על צד היופי וזה לא יטמא לפי השורש הקדום והוא אמרו מתכת המשמש את העץ טהור אולם אם כיון באלו המסמרים שיכה בו ויגוף בו הנה יהיה אז העץ משמש את המתכת שהוא טמא ע\\\"כ. ובתוספתא בבא מציעא פרק ד' מקל שעשה בו מסמר להיות תופס בו במקום הדייש טהור ואם בשביל שלא תהא הארץ אוכלתו טמא ותחלת דברי רבינו הם דברי התוספתא וטעמא דמילתא שכשעשאו כדי שיהא אוחז בו הוי מתכת המשמש את העץ אבל כדי שלא תהא הארץ אוכלתו אע\\\"ג דלכאורה נראה שגם הוא מתכת המשמש את העץ שהרי לא נעשה אלא לשמור את העץ כתב הר\\\"י קורקוס ז\\\"ל שצ\\\"ל שכל שהוא לקיימו שאם לא הוא היה נאכל הכל חשבינן למקיים שהוא עיקר הכלי וטמא והרי זה דומה לטבעת של מתכת וחותמה של אלמוג דטמאה דאזלינן בתר טבעת המעמדת אף על פי שעיקר התשמיש הוא בחותם ולא הוי משמש את העץ אלא היכא דהוי לנוי שאין שם שום תועלת אלא יפוי העץ בלבד.\",1,0],[8,380,4,10,\"ומה שכתב רבינו וכן מקל שקבע בו מסמרים וכו' עשאן לנוי וכו'. כבר נתבאר שהם דברי המשנה וכלל רבינו עשה בראשו מסמר כמין חזיינא בכלל סימרו.\",2,0],[8,380,4,10,\"ומה שכתב וכן מנקיות וכו'. שם במשנה עשה בראשו מניקת וכן בדלת טהורה ופירש רבינו מניקת איבוב והרבה יש שיעשו איבוב מברזל או מנחושת בחלונות ובשערים לנוי ויהיה מתכת המשמש את העץ ודע דמסיים מתניתין על הא דעשה בראשו מניקת היתה כלי וחיברה לו טמאה וכו' ולא כתבה רבינו פה:\",3,0],[8,380,5,1,\"כל הכלים אין מקבלין וכו' עד צפירה אחת. בפרק י\\\"ו דכלים ופירש שם רבינו אחר שעושים אותם מכסכס אותם בעור דג ידוע שימרקם ויבהיקם. ופירוש גמר שלא לשוף שבעת עשייתו גמר והסכים בלבו שלא ישופם ולא ימרקם אלא שישמש בהם בלא שיפה. ויחסום פירושו משיעשה השפה שמחברת האריגה וימנענה מלפרוק מלשון לא תחסום שור שהוא קשירת פיו. ויגמור התלויות פירושו שיגמור האוזן שנתלה בה:\",1,0],[8,380,5,1,\"ומ\\\"ש הקנונים הקטנים וכו'. שם ופירש רבינו קנונים וקלתות כלים יעשו מערבה דקה על תמונת קערות שיאכל אדם בהם וכו' והסיוגים הגדולים הם הקופות הגדולות מאד וכו' ומלאכת אריגת אלו הכלים הגדולים יקחו תחלה הגמי או הערבה או הדבר אשר יארגו ממנו ויחברו אותם בידיהן חבל (א') ארוך עד שיהיה ארכו מאה אמה או יותר ואז יחזרו זה אצל זה ויתפרו מזה החבל או החוט איזו תמונה שירצו וכו' ודורין קיבוץ דור והוא העיגול וכו' ויאמר שאלו הכלים הגדולים כאשר יתפרו רוחב קרקעיתו עוד יגביהו לו שפה שני דורים שהם שני עיגולים לרוחב שלהם ר\\\"ל על עיגולים לפי שיעור רוחב הכלי כולו כפי אשר יסכים יהיה רחבו כן וכו' אז מקבל טומאה. וכתב עוד וב' צפירות שני עיגולים מעיגולי זה הארוך והוא מענין אמרו באה הצפירה וכו' וערק כלי משעם גם כן כדמיון קופה לו שפה מעטת הגובה וזה הכלי מעט הרחב ארוך דימה לתיבת האושכפים ולזה יקרא ערק תרגום שרוך נעל ערקת מסאנא.\",2,0],[8,380,5,1,\"ומ\\\"ש המחצלת משיכרות ההוצין וכו'. בסוף פרק ב' דכלים:\",3,0],[8,380,5,1,\"כתב הראב\\\"ד והערק משיעשה בו צפירה א\\\"א פי' בערוך נפה וכו'. וכן פירש ר\\\"ש בשם הערוך ובשם גאון:\",4,0],[8,380,5,1,\"וכל כלי הנסרים וכו'. משנה פ\\\"כ דכלים:\",5,0],[8,380,5,1,\"גולמי כלי עץ וכו'. בסוף פ\\\"ק דחולין (דף כ\\\"ה).\",6,0],[8,380,5,1,\"ומ\\\"ש חוץ משל אשכרוע וכו'. בס\\\"פ י\\\"ב דכלים:\",7,0],[8,380,5,1,\"ועל מה שכתב רבינו קרוב בעיני שכלי עצם ככלי אשכרוע וכו'. כתב הראב\\\"ד אמר אברהם זאת הקורבה לא ידעתי מאין באה לו וכו'. ואני אומר דלשון התוספתא כך הוא כל גולמי כלי עץ טמאים חוץ משל פירשע [פירוש אשכרוע] מפני שהם מחוסרים שליקה ר' יהודה אומר העושה כלים מגרופות של זית טהורים מפני שהם מחוסרים שליקה וממירין את מה שבהם ומשמע לרבינו דכיון דלא תנא ת\\\"ק בשל פירשע ממירין את שבהם כדקתני ר' יהודה בגרופות של זית משמע דשל פירשע אין ממירין את שבהם ולפיכך לא הזכירו רבינו אלא הטעם מפני שהם מחוסרים שליקה דכלים של פירשע הם יפים ואין יופיים ניכר כל זמן שמחוסרים שליקה ואפשר שמשם למד רבינו לשל עצם שהם יפים ואין יופיים ניכר כל זמן שהם גולמים. ומ\\\"ש ואי סבירא ליה כרב נחמן דאמר בסוף פרק קמא דחולין כלומר דאמרינן התם דגולמי כלי מתכות טהורים וגולמי כלי עץ טמאים מאי שנא הני ומאי שנא הני ר' יוחנן אמר הואיל ולכבוד עשויים ר\\\"נ אמר הואיל ודמיהם יקרים מאי בינייהו איכא בינייהו כלי עצם ואזדא ר\\\"נ לטעמיה דאמר ר\\\"נ כלי עצם ככלי מתכות דמו ופירש\\\"י הואיל ולכבוד עשויים וכו' ונ\\\"ל שרבינו סובר דלא קי\\\"ל כר\\\"נ משום דקי\\\"ל כר\\\"י לגביה אלא שבא על כלי עצם מטעם אחר דאע\\\"ג דלכלי עץ דמו וכדר\\\"י מ\\\"מ דמו לשל אשכרוע שהוא מין עץ וגולמו טהור:\",8,0],[8,380,5,1,\"כלי עץ שאין עליו צורת כלי וכו'. בפרק כ\\\"ב דכלים כופת שסירקו וכרכמו ועשאו פנים ר' עקיבא מטמא וחכמים מטהרים עד שיחוק בו ופירש שם רבינו כופת חתיכת עץ:\",9,0],[8,380,5,1,\"ארובות של נחתומין שסודרין עליהם החלות כשהן וכו' עד והלוח שעורכים עליו מתטמא. פט\\\"ו דכלים וכתב רבינו שם ארובות הנחתום לוחות הנחתום אשר יסדיר עליהם הלישה ויש עליהן צורת כלי ושל בעלי בתים אין להם צורת כלי ולזה לא יטמאו אא\\\"כ צבען וקשטן וייפן ומשחן בששר או כרכמן בכרכום ואז יהיה בהם צורת כלי ויהיה טמא לפי שפשוטי כלי עץ טהורים וכו' אמנם יטמאו בגזרה דרבנן עכ\\\"ל וסרוד הוא כלי מעץ ישתמשו בו בעת הלישה לרחוץ את הידים ויטוחו ממנו פני הלחם וכיוצא בזה ממה שיצטרך אליהם וע\\\"ש שהוא לתשמיש נקרא סרוד בגדי השרד מתרגמינן לבושי שימושא:\",10,0],[8,380,5,1,\"וכתב הראב\\\"ד א\\\"א דבר זה בהיפך וכו'. טעמו לומר שרבינו פירש שארובות סודרים עליהם החלות כשהם בצק ואינו כן שזוהי מלאכת הסרוד נמצא שהיפך רבינו מלאכת הסרוד ואומר שהיא מלאכת הארובות ואין זו השגה ומאחר שאין הכרע לפירושו יותר מלפירוש רבינו ועוד שא' מהפירושים שפירש רבינו שמשון בשם הערוך הוא ארוכות בכ\\\"ף לוחים ארוכים שמקריבים עליהם לחם והוא כפירוש רבינו. ומ\\\"ש ואם יחדו טמא והכי איתא בתוספתא כלומר משיג על רבינו למה השמיט הא דאם ייחדו טמא וי\\\"ל שיפרש רבינו דהאי ייחוד היינו ע\\\"י סירקן או כרכמן דקתני מתניתין ויש לדקדק בדברי רבינו שסרוד נותנים בו המים א\\\"כ יש בו בית קיבול ולמה של בעלי בתים טהור ואפשר דהכי קאמר שנותנים בו כלי של מים:\",11,0],[8,380,5,1,\"וכתב עוד הראב\\\"ד והלוח שעורכים עליו טמא א\\\"א זה שיבוש עכ\\\"ל. נראה שטעמו מפני ששנינו בפרק הנזכר סרוד של נחתומים וכו' נפרץ מרוח אחת טהור רבי שמעון אומר אם התקינו להיות קורץ עליו טמא וכן המעריך טמא ומשמע ליה להראב\\\"ד דוכן המעריך טמא מדברי רבי שמעון הוא ולית הלכתא כוותיה ורבינו סובר דאתנא קמא קאי:\",12,0],[8,380,5,1,\"כלי עץ שהסלתים מרקדים עליו וכו' עד ליכנס בו טהור. שם:\",13,0],[8,380,5,1,\"כתב הראב\\\"ד כלי עץ א\\\"א בערוך פירש נפה של שיער וכו'. מ\\\"ש ובו דברה המשנה תחלה כלומר דבראש הפרק קתני כלי עור. ומ\\\"ש עוד וממה שאמר ר' יהודה בסמוך אף של גדלת וכו' כלומר שהוא ז\\\"ל מפרש של גדלת שהנפה עשויה משיער שגודלים בה והבנות יושבות בתוכה וגודלות היינו לומר שהן גודלות הנפה עצמה ומדקתני של גדלת משמע דעד השתא לא איירי בנפה של שיער ולפי מה שפירשו רבינו ור\\\"ש דגדלת היינו האשה שהיא גודלת שיער לנשים אין מכאן ראיה.\",14,0],[8,380,5,1,\"ופירוש זה הכלל העשוי לקבלה וכו' של אוצרות ושל גרנות יעשו אותה לכנס וללקט מן הצדדין מה שבגורן או שבאוצר לקבצו אל האמצע ושל גרוסות יש לה בית קיבול שמכניסים בה לריחים ושל גתות להשליך בה חוץ מן הגת ופירוש רחת פאלה בלע\\\"ז:\",15,0],[8,380,5,2,\"כל התלויים טהורים חוץ מתלויי וכו' עד טהור. שם וכחכמים. פירוש מקל הבלשין הוא שמחפשין בו התבן אם יש בו תבואה שיסתירו התבואה בתבן מפני עישור המלך תרגום ויחפש ובלש. ולסייע בשעת מלאכה הוא שמכניסים ידיהם בתלוי ויעזר בו בעת שימושו:\",1,0],[8,380,5,4,\"נבלי המשוררים מתטמאין וכו' עד צורת כלי. גם זה שם פי' הכנורות חלולים ומנוקבים בצד הנימין ודרך המנגנים לתת בתוכו המעות שמקבלין מבני אדם אבל של בני לוי אינם עשויים לכך ולפיכך טהורים. ופירוש הבטנון כלי מכלי הניגון שמשים אותו האדם בבטנו כשמנגן בו:\",1,0],[8,380,5,4,\"כתב הראב\\\"ד והנקטימון א\\\"א קשיא לי וכו'. ובמ\\\"ש רבינו בפירוש המשנה נתיישב זה שכתב וז\\\"ל והנקטימון הוא רגל מעץ יעשה אותו מי שנחתך רגלו לילך בו והוא ירצה בכאן עץ הניגון המפורסם צורת דמות רגל (ושוק) מעץ וגם ר\\\"ש כתב אין זה לוקטמין דפרק במה אשה דהכא והתם טהור. ואירוס פירש רבינו עגולה דומה לגרבל ויכה עליה מצד אחד ביד ושמו בערבי אלתאר ובלע\\\"ז טנבורו:\",2,0],[8,380,5,5,\"קוצים שאורגים בהם וכו'. פרק י\\\"ו דכלים פטילייא טמאה וחסינא טהורה ופירש שם רבינו פטילייא דומה לקופה מערבה וכו' וכמו שפירש כאן:\",1,0],[8,380,5,5,\"וכתב הראב\\\"ד א\\\"א לשון המשנה וכו' וחסינא טהורה והטעם מפני שאינה עשויה לטלטל:\",2,0],[8,380,5,6,\"עלים שמסרגים אותם וכו'. שם סוגניות של עלים טהורות של נסרים טמאות ופי' ר\\\"ש סוגניות מלשון סוגה בשושנים עושין כמין כפיפה קטנה [מן העלין] ומכסין בה פירות ואינה אלא מלאכת עראי. נצרים צורי דקל:\",1,0],[8,380,5,6,\"כתב הראב\\\"ד עלים שמסרגים א\\\"א זה סוגניות שבמשנה. ופשוט הוא:\",2,0],[8,380,5,7,\"חותל של הוצין וכו'. שם ופירוש חותל כלי מהוצין ישימו בו התמרים הנקראין רוטב וכתב ר\\\"ש דכיון שאין מוציא מה שבתוכו עד שיקרענו או עד שיתירנו הוי תשמיש עראי.\",1,0],[8,380,5,7,\"ומ\\\"ש או שחשב וכו'. תוספתא דב\\\"מ פ\\\"ו:\",2,0],[8,380,5,7,\"וכן הקרן וכו'. תוספתא שם:\",3,0],[8,380,5,8,\"השופר אינו מקבל טומאה וכו'. גם זה שם:\",1,0],[8,380,5,9,\"קערה שקבעה וכו'. כלים פ\\\"כ, וכתב הר\\\"י קורקוס ז\\\"ל דהא דהויא מכלל השידה וטהורה דוקא כשהיא טהורה כגון שהיא באה במדה:\",1,0],[8,380,5,10,\"האקון והרטוב וכו'. כלים סוף פרק כ\\\"ג:\",1,0],[8,380,5,10,\"וכתב הראב\\\"ד האקון א\\\"א פי' בערוך כלי של מצודת דגים וגם רבינו פירש כן והרטוב מכלי ציידי העופות והוא מעץ וכלוב גיולא בלעז ככלוב מלא עוף ומדף לוח מסובך מעץ ובזה העץ מסובך דבר יחזיק בו הצייד מרחוק וכאשר ינוח העוף בזה הכלי ינוח חוט הכלי ויפול עליו זה הלוח. ומצודות הסכרים מצודות יפסיקו המים במים עד שיתקבצו שם הדגים:\",2,0],[8,380,5,12,\"הספסלים שבפונדקאות וכו'. תוספתא פרק י\\\"ט דכלים.\",1,0],[8,380,5,12,\"ומ\\\"ש זה הכלל כל שניטל וכו'. ג\\\"ז שם.\",2,0],[8,380,5,12,\"ומ\\\"ש היתה אחד מרגליו של אבן אינו מקבל טומאה. משנה פכ\\\"ה דכלים:\",3,0],[8,380,6,1,\"כל כלי שנטמא ונשבר. רפ\\\"ב דכלים וריש פט\\\"ו:\",1,0],[8,380,6,2,\"כמה שיעור השבר וכו'. רפי\\\"ז דכלים.\",1,0],[8,380,6,2,\"ומ\\\"ש והרמון שאמרו. שם.\",2,0],[8,380,6,2,\"ומ\\\"ש לפי דעתו של רואה. שם גבי שיעור כביצה וכר' יוסי.\",3,0],[8,380,6,2,\"ומ\\\"ש ויהיו בכלי ג' רמונים וכו'. שם:\",4,0],[8,380,6,2,\"כתב הראב\\\"ד ויהיו בכלי שלשה רמונים א\\\"א אין מדבריו אור לחשכים וכו'. ורבינו שמשון כתב לכאורה משמע דמוציא רמון דכל דוכתא לאו רמון א' דוקא וכו' ומה שטען הראב\\\"ד על רבינו שסתם ולא פירש אינה טענה שכבר נודע שרבינו בזה הספר מחבר לא מפרש. ומ\\\"ש וקצת ראיה לזה הפי' דברי רשב\\\"ג וכו' כלומר דתנן התם הרמונים שאמרו ג' אחוזים זה בזה רשב\\\"ג אומר בנפה ובכברה כדי שיטול ויהלוך ובקופה כדי שיפשיל לאחוריו ופי' ר\\\"ש שיטול ויהלך מתוך נענוע של נטילה והילוך נפיל טפי. ומ\\\"ש פי' אחר הרמונים שמשערין בהם לא ממין הגדולים וכו'. רבינו שמשון כתב על פי' זה לא יתכן כלל לפרש כן דהא קתני באידך בבא לא גדול ולא קטן אלא בינוני אבל הראב\\\"ד כתב זה הפי' בענין שיתכן. ומ\\\"ש ואולי זה הוא פי' זה המחבר. לא ידעתי מנין לומר כן שהרי דבריו סתומים כדברי המשנה:\",5,0],[8,380,6,2,\"ניקב הכלי במוציא זית וכו'. ריש פרק אלו קשרים (שבת דף קי״ב ע״ב) בעיא דאיפשיטא ופירש רש״י פנים חדשות משירדה לו טומאה נתחדשו פנים הללו ואין זה הראשון שכבר נתקלקל בו כדי ביטולו:\",6,0],[8,380,6,3,\"כלים שעשאם מתחלה נקובים וכו': כתב הראב\\\"ד זאת לא מצאתי וכו'. ולי נראה שרבינו מפרש הא דתניא פרק כלי עור והוא בתוספתא פרק י\\\"ג דכלים הסל והפחלץ של גמלים וכו' שעשאן מתחלתן מקבלי רמונים טמאים היינו לומר שעשאן מתחלתן שאינם מקבלים רמונים דומיא דמאי דתנן שולי קורפיות ושולי קוסים הצידונים אע\\\"פ שאינם יכולים לישב שלא מסומכים טמאים שלכך נעשו מתחלתן ומה שהקשה ממה ששנינו הפחלץ של גמלים טהור מכלום צ\\\"ל שהוא מפרש פחלץ עשוי כתבנית אחת וצ\\\"ע:\",1,0],[8,380,6,4,\"אפיפירות שעשה להם קנים וכו'. בפי\\\"ז דכלים ופירש רבינו אפיפירות כלי ארוג מקנים ימתחו זמורות הכרמים.\",1,0],[8,380,6,4,\"ומ\\\"ש אע\\\"פ שכולה נקובה כמוציא רמון. בתוספתא שם:\",2,0],[8,380,6,5,\"כל הכלים שאינם יכולים לקבל וכו'. שם כר״ש לגבי ר״מ. וכתב הר״י קורקוס ז״ל קשה דהא איבעיא לן בפרק מי שהוציאוהו (עירובין דף מ״ו ע״ב) ר״מ ור״ש הלכתא כמאן וסלקא בתיקו ודרך רבינו לפסוק כדברי המחמיר שבהם ואיך פסק כר״ש לקולא דודאי משמע דכזית הוי נקב מועט מרובו וי״ל שרבינו סמך על מ״ש בסוף המצניע (שבת דף צ״ה צ״ו) דלא אמרינן ברובו אלא לענין צמיד פתיל אבל לענין טומאה בזיתים עכ״ל.\",1,0],[8,380,6,5,\"ומ\\\"ש נגממו שעורן במה שהן. ופירש רבינו אם נשאר שיקבל כל שהוא יטמא:\",2,0],[8,380,6,6,\"הסלים של פת וכו'. שם:\",1,0],[8,380,6,7,\"ומ\\\"ש קופת הגננים וכו'. שם ומפרש רבינו שהם דברי ת\\\"ק:\",1,0],[8,380,6,8,\"ומ\\\"ש בית קערות. ג\\\"ז שם.\",1,0],[8,380,6,8,\"ומ\\\"ש וכן בית הרעי וכו' הואיל ומקבל את הרעי הרי זה מקבל טומאה. שם וכת\\\"ק:\",2,0],[8,380,6,9,\"כל כלי עץ שנחלק וכו'. בפי\\\"ו דכלים.\",1,0],[8,380,6,9,\"ומ\\\"ש וכגון תמחוי המזנון. ע\\\"ש שמשימין בכל קערה מין אחד של תבשיל תרגום למינו לזנוהי.\",2,0],[8,380,6,9,\"ומ\\\"ש וכן בית לגינין וכו'. תוספתא פי\\\"ג דכלים שם:\",3,0],[8,380,6,10,\"משפלת שאמצעיתה גבוהה וכו'. גם זה שם:\",1,0],[8,380,6,10,\"השלחן והדולפקי וכו'. משנה פרק כ\\\"ב דכלים:\",2,0],[8,380,6,11,\"כלי נסרים וכו'. שם פ\\\"כ נתחסמו אע\\\"פ שנשרו שפתותיהן כל שהן טמא:\",1,0],[8,380,6,12,\"טבלא שמילאה עצים וכו'. תוספתא פרק י\\\"ט:\",1,0],[8,380,6,13,\"ומה שכתב ספסל שנתפרק וכו'. שם:\",1,0],[8,380,6,14,\"הסלים של גמלים וכו'. תוספתא ספי\\\"ב:\",1,0],[8,380,6,15,\"השלחן או הדולפקי וכו'. משנה פרק כ\\\"ב וכת\\\"ק.\",1,0],[8,380,6,15,\"ומ\\\"ש ואם חיפה הכל טהור בין בציפוי עומד וכו' עד סוף הפרק. ועיין במה שכתבתי ספ\\\"ד:\",2,0],[8,380,7,1,\"כלי עור וכו'. פרק י\\\"ו דכלים:\",1,0],[8,380,7,1,\"עור העריסה וכו' עד וישרטט. תוספתא ריש פרק י\\\"ג:\",2,0],[8,380,7,2,\"עור שאין עליו וכו' לפיכך כף של עור וכו'. משנה פי\\\"ו.\",1,0],[8,380,7,2,\"ומה שכתב וכן העור שמלקטים בו. שם המלקט של בקר והחסום שלה והמדף של דבורים והמניפה הרי אלו טהורים:\",2,0],[8,380,7,3,\"כל בית האצבעות וכו'. פכ\\\"ו:\",1,0],[8,380,7,4,\"האבנט של עורות וכו'. שם הזון והבורכייר טמאין והשרולים טמאים ומפרש הזון האבנט של עור והבורכייר עורות שתופרין הקיטעים על ארכובותיהם והשרולין עורות העשויות כעין טבעות שמכניסין אותם בזרועותיהם וכו':\",1,0],[8,380,7,5,\"עור שתופרים ממנו כיסוי ליד וכו'. פרק י\\\"ו קסיא של זורי גרנות של הולכי דרכים של עושי פשתן טמאה אבל של צבעים ושל נפחים טהורה וכו' זה הכלל העשוי לקבלה טמא מפני הזיעה טהור ונראה שרבינו היה גורס של זורעי גנות במקום של זורי גרנות ויותר נראה שהוא ט\\\"ס בספרי רבינו:\",1,0],[8,380,7,6,\"כמה שיעור הנקב וכו' החמת משתנקב וכו'. פי\\\"ז:\",1,0],[8,380,7,8,\"ומה שכתב התורמל שנפחת וכו' עד שאינן מקבלות כדרכן. פרק י\\\"ט:\",1,0],[8,380,7,9,\"כלי עור שיש לו לולאות וכו'. ריש פרק כ\\\"ו:\",1,0],[8,380,7,10,\"כיס של שנצות וכו' עד צורת הכלי. שם:\",1,0],[8,380,7,11,\"עור שכרך בו וכו':\",1,0],[8,380,7,12,\"התפילין של ראש וכו'. בפרק י\\\"ח:\",1,0],[8,380,7,12,\"וכן סנדל שהוא טמא מדרס וכו' עד טהור. פרק כ\\\"ו:\",2,0],[8,380,7,14,\"תפילה שנטמאת וכו':\",1,0],[8,380,7,15,\"הכדור והאימום וכו' עד סוף הפרק. ריש פרק כ\\\"ג:\",1,0],[8,380,8,2,\"כל כלי מתכות וכו'. בסוף פירקא קמא דחולין (דף כ\\\"ה ע\\\"א):\",1,0],[8,380,8,2,\"ומה שכתב כיצד הסייף וכו' והסכין וכו'. בפרק י\\\"ד דכלים.\",2,0],[8,380,8,2,\"ומה שכתב לפיכך העושה כלים וכו' עד שידוע שנעשו מן הכלים. שם פרק י\\\"א.\",3,0],[8,380,8,2,\"ומה שכתב אבל מסמרות שאין ידוע וכו'. שם וכבית הלל:\",4,0],[8,380,8,2,\"וכתב הראב\\\"ד הרי אלו מקבלים טומאה לפי שאינם גולמים א\\\"א חסרון דעת אני רואה בכאן וכו'. [רבינו] כתב בפי' המשנה שם ואין הכוונה שיותך זאת הגרירה או אלו הקצוות ויעשה מהם כלים שזה יקבל טומאה בלא ספק אמנם הכוונה שכל אלו הקצוות [דיבק וחיבר אותם במסמרים] עד שעשה מהם דמיון כלי הנה הוא לא יקבל טומאה מן הסבה שזכרנו ואף על גב דמתניתין מיתניא גבי כלי מתכות שחוזרין לטומאתן ישנה ה\\\"ק כל כהאי גוונא אפילו מכני כלים וכו' לא אמרינן בהו שחזרו לטומאה ישנה כיון שהם גולמים לא קרינן בהו חזר ועשה מהם כלים אבל העושה כלי משברי כלי מתכות וכו' ע\\\"כ אינם נעשים כלים אלא על ידי התכה ואז עושים מהם כלים גמורים לא גולמים ולפיכך חזרו לטומאתן ישנה וז\\\"ש בבבא קמייתא שהכלים הנעשים מכני כלים וכו' שלא על ידי התכה אינם אלא גולמים:\",5,0],[8,380,8,3,\"כלי מתכות וכו':\",1,0],[8,380,8,4,\"מחט שלא ניקבה וכו':\",1,0],[8,380,8,5,\"נמצא הטמא בכלי עץ וכו'. בסוף פרק קמא דחולין (דף כ\\\"ה ע\\\"ב):\",1,0],[8,380,8,6,\"כל כלי המלחמה וכו' וכל תכשיטי האדם וכו'. סוף פרק י\\\"א דכלים.\",1,0],[8,380,8,6,\"ומה שכתב אפילו דינר שנפסל וכו'. שם פי\\\"ב.\",2,0],[8,380,8,6,\"ומה שכתב וכן קמיע של מתכת וכו'. תוספתא פרק ח' דכלים:\",3,0],[8,380,8,8,\"כל תכשיטי הבהמה והכלים וכו'. ריש פרק י\\\"ב דכלים טבעת אדם טמאה טבעת בהמה וכלים ושאר כל הטבעות טהורות.\",1,0],[8,380,8,8,\"ומה שכתב חוץ מזוג של בהמה וכלים המשמיע קול לאדם. בתוספתא פ\\\"ח כל תכשיט בהמה כגון השירים והנזמים והקטלאות והטבעות טהורים ואין טמא אלא זוג המשמיע קול\",2,0],[8,380,8,8,\"לאדם ומ\\\"ש כיצד העושה זוגים למכתשת וכו' עד אף על פי שאין לו ענבול. בפרק במה אשה עלה נ\\\"ח:\",3,0],[8,380,8,9,\"כל הפרצופות וכו' עד שבו חותמין בלבד. תוספתא פרק שמיני דכלים:\",1,0],[8,380,8,9,\"וכל הטבעות טהורות וכו'. ריש פרק במה בהמה (שבת דף נ\\\"ב ע\\\"ב):\",2,0],[8,380,8,9,\"טבעת השיר וכו' וכן מקל וכו'. שם:\",3,0],[8,380,8,10,\"כל הכלים יורדים וכו'. סוף פרק כ\\\"ה דכלים:\",1,0],[8,380,8,11,\"חרש שוטה וקטן יש להם מעשה וכו'. ריש פרק ו' דמכשירין ופ\\\"ק דחולין (דף י\\\"ג):\",1,0],[8,380,8,12,\"זוג של דלת וכו'. בר\\\"פ במה אשה עלה נ\\\"ח:\",1,0],[8,380,8,15,\"אומן שעושה וכו' עד סוף הפרק. תוספתא פ\\\"ח דכלים:\",1,0],[8,380,9,1,\"כל כלי מתכות וכו' עד הכל מקבל טומאה. פרק י\\\"א דכלים:\",1,0],[8,380,9,1,\"כתב הראב\\\"ד כיצד עקרב של פרומביא א\\\"א נ\\\"ל שלא מן השם הוא זה וכו'. לא ידעתי למה ידחה טעם אחד מפני שיש לו טעם אחר.\",2,0],[8,380,9,1,\"ומ\\\"ש לא בא למעט אלא כסויי הכלים וכו' כמו שמפורש במקומו. לא ידענא מאי קאמר וצ\\\"ע:\",3,0],[8,380,9,3,\"טסים של ברזל שמניחין על וכו' עד משנפרק. ג\\\"ז שם:\",1,0],[8,380,9,4,\"טבעת אחת וכו' עד כבלים. פרק במה אשה עלה ס\\\"ג:\",1,0],[8,380,9,4,\"כתב הראב\\\"ד ואין לכל גרגיר ממנו שם בפ\\\"ע א\\\"א כל מ\\\"ש משום שיש לו שם בפני עמצו או משום שאין לו שם בפ\\\"ע וכו'. ואין דבריו מוכרחים:\",2,0],[8,380,9,5,\"קטלא של חוליות וכו' עד צואר קטנה. פרק י\\\"א דכלים:\",1,0],[8,380,9,6,\"כל הכיסויים וכו'. פרק י\\\"ד שם כל הכיסויים טהורים חוץ משל מיחם.\",1,0],[8,380,9,6,\"ומ\\\"ש ומכיסוי טני של רופאים וכו'. פי\\\"ב דכלים כיסוי טני של מתכת וכו' של רופאים טמא:\",2,0],[8,380,9,7,\"כיסוי של מתכת וכו'. שם פי\\\"ד כיסוי טני של מתכת שעשה בו מראה ר' יהודה מטהר וחכמים מטמאים:\",1,0],[8,380,9,8,\"כל המשקולות של מתכת וכו'. שם פי\\\"ב קנה מאזנים של סרוקות טמא מפני אונקיות ושל בעלי בתים אם יש בו אונקיות טמא:\",1,0],[8,380,9,8,\"כתב הראב\\\"ד קנה מאזנים של עץ א\\\"א נ\\\"ל אפילו של מתכת וכו'. ואפשר שרבינו לרבותא נקט דאפילו קנה של עץ טמא מפני האונקיות התלויות בו אע\\\"פ שאינם קבועות בו:\",2,0],[8,380,9,8,\"וכתב עוד הראב\\\"ד דבר מזוייף הוא זה בעיני שהרי לא הזכירו במשנה לבעלי בתים קבע. י\\\"ל שרבינו דייק לשון המשנה דגבי סרוקות קתני טמא מפני אונקיות וגבי בעלי בתים קתני אם יש בו אונקיות ולישנא דיש בו משמע שהן קבועות בו:\",3,0],[8,380,9,9,\"משקלות שנשתברו וכו'. תוספתא סוף פ\\\"ט:\",1,0],[8,380,9,10,\"סלע שנפסלה וכו'. משנה פי\\\"ב:\",1,0],[8,380,9,11,\"אונקלי של כתפים וכו' עד הרי הם כמקצת כלי. שם:\",1,0],[8,380,9,11,\"ומ\\\"ש ואפילו אונקלי שבכתלים וכו'. שם:\",2,0],[8,380,9,13,\"שלשלת שיש בה בית נעילה וכו' עד ושל בעלי בתים טהורה. ריש פי\\\"ב:\",1,0],[8,380,9,15,\"שלשלת של מושחי קרקע וכו' עד י' טפחים. פי\\\"ד:\",1,0],[8,380,9,16,\"הכדור של מתכת והסדן: הקנטר של בנאי והדקר של חרס. פרק י\\\"ד.\",1,0],[8,380,9,16,\"ומה שכתב וחמור של נפח. שם.\",2,0],[8,380,9,16,\"ומה שכתב והמטולטלת וכו' עד סוף הפרק. סוף פי\\\"ב.\",3,0],[8,380,9,16,\"ומה שכתב והאפרכס של מתכת. סוף פרק י\\\"ד:\",4,0],[8,380,10,1,\"מסמרות שמחזיקים בהם וכו'. ומ\\\"ש וכן המסמרות שתוקעין בהם וכו'. פרק י\\\"ב אונקלי שבכתלים טהורה:\",1,0],[8,380,10,1,\"כיצד מסמר שהתקינו וכו'. פ' י\\\"ב:\",2,0],[8,380,10,1,\"וכתב הראב\\\"ד טהור עד שיצרפנו א\\\"א פירוש לפי שהמסמר שנוקבים בו את החבית וכו'. וטעם נכון הוא.\",3,0],[8,380,10,1,\"ומה שכתב או להוציא את הפתילה וכו'. ומ\\\"ש התקינו לפתוח בו את החבית וכו'. משנה פרק י\\\"ב וכחכמים:\",4,0],[8,380,10,4,\"ומה שכתב מסמר העשוי בסימן לשמירת הפתח וכו' עד מסמר הגרדי וכו'. שם:\",1,0],[8,380,10,4,\"וכתב הראב\\\"ד מסמר הגרע א\\\"א לא נראה כן מהתוספתא וכו'. ולדברי רבינו אפשר שבתוספתא מחשיב האיזמל שמקיזים בו שהוא משמש עם הקרקע מפני שהמוקז סומך על זרועו של עץ תקוע בקרקע ותנא דמתניתין לא חשיב מפני כך משמש עם הקרקע ולפיכך טמא:\",2,0],[8,380,10,5,\"אלו כלי מתכות המתטמאות בעגלה העול וכו' עד ושאר כל המסמרות שבה טהורים. פרק י\\\"ד:\",1,0],[8,380,10,6,\"עקרב בית הבד מקבל וכו'. פרק י\\\"ב:\",1,0],[8,380,10,6,\"ארון של גרוסות אע\\\"פ שהוא וכו' עד מקבלת טומאה. שם:\",2,0],[8,380,10,7,\"ריחים של פלפלין מקבלת טומאה וכו'. משנה סוף פרק שני דביצה (דף כ\\\"ג ע\\\"ב):\",1,0],[8,380,10,8,\"הדלת של מתכת שבמגדל של בעלי וכו'. פי\\\"ב דכלים:\",1,0],[8,380,10,9,\"טסין של מתכת שמנערין בהן את הקדרה מקבלין וכו'. שם הייתינים טמאים והרכין טהורים ובתוספתא (פ\\\"ב דב\\\"מ) אלו הם הייתינים אלו שהחנווני מנער בהם את הקדרה ואלו הן הפרכין אלו הקבועים בכירים ופי' רבינו שמשון מנער מלשון ותער כדה:\",1,0],[8,380,10,9,\"וכתב הראב\\\"ד טסין של מתכת א\\\"א מתניתין פי\\\"ב היתינין טמאים וכו':\",2,0],[8,380,10,10,\"המלקחיים שממעך בהם את הפתילה וכו'. כלומר מלקחיים שנוטל בהם הקדרה ומערה אותה לקערות. ולי נראה דאפשר לפרש שנוטל הקדרה במלקחיים ומנערה מלמעלה למטה וטסין שהן קבועין בכירים היינו ברזלים התלויים במוקד ובסופם מזלגים שהקדרה תלויה בהם על האש כדי שלא תהיה יושבת על האש ממש ותשרף וכבר ראיתי ברזלים אלו בבית קצת בני אדם:\",1,0],[8,380,10,11,\"קלוסטרא שנועלין בה הדלתות אם היתה וכו'. משנה פרק י\\\"א ופירש רבינו שם קלוסטרא כלי מקשיי וכו':\",1,0],[8,380,10,12,\"הפין והפורנא טמאים. שם ופירש שם רבינו הפין הם השיניים הקבועין בפותחת והפורנא הוא המקום עצמו אשר תכנס בו הפין:\",1,0],[8,380,10,13,\"פיקה של מתכת טהורה וכו'. שם ופירש שם רבינו פיקה דמיון חצי כדור נקוב וכו':\",1,0],[8,380,10,14,\"הכוש והפימא וכו' עד אע\\\"פ שהוא מצופה טמאה. גם זה שם ופירש שם רבינו הוא מטוה וכו':\",1,0],[8,380,10,16,\"החצוצרת שמפוצלת חוליות וכו'. שם קרן עגולה טמאה ופשוטה טהורה אם היתה מצופית שלה של מתכת טמאה הקו שלה וכו' כיוצא בו קני מנורה טהורים וכו' עד הכל טמא ופירש רבינו שם קרן ירצה בו החצוצרת וכו':\",1,0],[8,380,10,16,\"כתב הראב\\\"ד ואם יכולין הכל לפרקה וכו' זאת הפיסקא וכו'.\",2,0],[8,380,10,16,\"ומה שכתב רבינו שאם אינו יודע להחזירה אלא אומן מקבלת טומאה וכו'. הקשה עליו הראב\\\"ד דבר זה רחוק מן הדעת ובהפך נמצא במשנה פרק כ\\\"ו וכו'. וי\\\"ל דהכא שאני שהוא של חוליות ואם אינה תקועה בחוזק אינו חיבור כלל:\",3,0],[8,380,10,17,\"קורת החצים וכו' עד והקולר מקבל טומאה. ריש פי\\\"ב:\",1,0],[8,380,11,2,\"כמה הוא שיעור השבר וכו' כיצד כלי של מתכת עד למוד בהן שמן. ריש פרק י\\\"ד:\",1,0],[8,380,11,2,\"מסננת של חרדל וכו'. סוף פרק י\\\"ד:\",2,0],[8,380,11,2,\"מגריפה שניטלה כפה וכו'. פרק י\\\"ג וכחכמים:\",3,0],[8,380,11,4,\"מסרק של צמר וכו' עד אחת טהור. בסוף פרק י\\\"ג ועיין בפרק החולץ (יבמות דף מ\\\"ג) שהקשו רישא אסיפא ותירצו הא בגוייתא הא בברייתא וצריך עיון למה לא כתב רבינו כאותו תירוץ ובאידך דמקשה רישא דקתני וכולן אחת אחת בפני עצמן טמאות לסיפא דקתני התקינו אין לא התקינו לא וכתב כשינויא דרב פפא ושבק שינויא דסתם גמרא ועוד דמסיק גמרא דלית הלכתא כהאי סתמא משום דגרסי בה דווקני זו דברי רבי שמעון ויש לתמוה על הראב\\\"ד שלא השיגו:\",1,0],[8,380,11,5,\"הכרומים שנשברו וכו'. בפרק י\\\"ג:\",1,0],[8,380,11,7,\"מגירה שניטלה וכו' עד מפני שהיא מקצת כלי. שם:\",1,0],[8,380,11,7,\"כתב הראב\\\"ד והרונקי בפ\\\"ע א\\\"א פירש בערוך ברזל של רהיטני וכו'. גם רבינו שמשון כתב כדברי הראב\\\"ד מפני התוספתא ולרבינו אפשר לומר שהתוספתא פליגא אמתניתין ואתיא כתנא אחרינא ואנן כמתני' נקיטינן:\",2,0],[8,380,11,8,\"הסייף והסכין וכו'. ריש פרק י\\\"ג הסייף והסכין והפגיון והרומח מגל יד ומגל קציר והשחור וזוג של ספרים שנחלקו הרי אלו טמאים מדרס ופירש שם רבינו פגיון סכין מעוות דומה למגל קטן וכו' והשחור מספריים קטנים:\",1,0],[8,380,11,9,\"מספריים שנחלקה וכו'. שם וכחכמים:\",1,0],[8,380,11,12,\"שריון שנחלק וכו' עד את הגחלים. תוספתא ריש פרק י' שהוא פרק ג' דבבא מציעא:\",1,0],[8,380,11,13,\"מראה של מתכת וכו'. משנה פרק י\\\"ד מראה שנשברה אם אינה מראה את רוב הפנים טהורה:\",1,0],[8,380,11,13,\"ומ\\\"ש או שנטשטשה:\",2,0],[8,380,11,16,\"מחט שניטל קצתה הנקוב וכו' עד ואם לאו טמאה. פרק י\\\"ג:\",1,0],[8,380,11,17,\"הסייף והסכין וכו' וכן צינורא שפשטה וכו'. משנה פי\\\"ג:\",1,0],[8,380,11,18,\"מפתח עקום וכו' עד זה לתוך זה טהור. בסוף פרק י\\\"ד:\",1,0],[8,380,11,20,\"כלי שיש בראשו וכו' עד מפני הכותב. בפרק י\\\"ג:\",1,0],[8,380,11,20,\"וכתב הראב\\\"ד כלי שיש בראשו האחד כף להרים בו הדשן וכו' א\\\"א זה כתב תחת זולמטרא ומעולם לא עלה על דעת וכו'. וי\\\"ל דאין ויכוח בזה כי הכוונה אחת שבראשו כף יהיה למה שיהיה או ליקח תבשיל או ליקח דשן הדין שוה. ומ\\\"ש והמלה עצמה לעז היא:\",2,0],[8,380,11,20,\"כתב עוד הראב\\\"ד כלי שבראשו אחד כף כסבכה וכו'. א\\\"א זה עשה תחת קליגריפין ובערוך לא פירש כן וכו'. וג\\\"ז אין בו ויכוח כי הכוונה אחת.\",3,0],[8,380,11,20,\"ומ\\\"ש והוא שיהיה הנשאר יכול לעשות וכו':\",4,0],[8,380,11,21,\"קורדום שניטל עושפו וכו' עד נשבר מקיפו טהור. משנה פרק י\\\"ג:\",1,0],[8,380,11,24,\"מינקת של מתכת וכו'. פי\\\"ד מקל שעשה בראשו מסמר וכו' עשה בראשו מניקת וכן בדלת טהורה היתה כלי וחברה לו טמאה מאימתי הוא טהרתה בש\\\"א משיחבל ובה\\\"א משיחבר ובתוספתא פ\\\"ד דב\\\"מ מניקה שעשאה לתחת הדלת אע\\\"פ שמשתמש בה טהורה היתה טמאה ועשאה לתחת הדלת טמא עד שעה שתטהר מאימתי היא טהרתה בש\\\"א משיחבל ובה\\\"א משיחבר.\",1,0],[8,380,11,24,\"ומ\\\"ש לפיכך דף של נחתומין וכו'. בפט\\\"ו וכחכמים:\",2,0],[8,380,11,24,\"וכתב הראב\\\"ד א\\\"א טעה בכאן טעות גדולה וכו'. ופשט המשנה והתוספתא כדברי הראב\\\"ד ועל דרך זה הם דברי רבינו בפירוש המשנה וכפי דבריו כאן ה\\\"פ מניקה כמין שפופרת קצרה עושין של מתכת ומכניסין בראש המקל והיינו דקתני עשה בראשו כלומר בראש המקל מניקת וכן אם עשה שפופרת של מתכת תחת הדלת כדי שלא תאכלנו האש והשתא קאמר שאם זאת השפופרת נטמאת וקבעה בראש המקל או בדלת טהרה מטומאתה היתה כלי כלומר אבל אם זאת השפופרת לא נטמאה וזהו היתה כלי כלומר שלא היה עליה אלא שם כלי בלבד לא שם כלי טמא וחברה למקל או לדלת טמאה כלומר עדיין לא בטל שם כלי מעליה והרי היא מקבלת טומאה כמות שהיתה והדר קאמר הא דאמרינן ברישא שאם היתה טמאה וקבעה במקל או בדלת טהרה מטומאתה מאימתי תטהר בש\\\"א משיחבל כלומר משיכה עליה כל כך בתחיבתה בעץ עד שתתחבל כלומר שתתקלקל ובה\\\"א משיחברנה בעץ היטב טהרה וז\\\"ש רבינו משיקבענה וכו' ויחברנה עם העץ ותוספתא ה\\\"פ מניקת שעשאה לתחת הדלת כלומר שקבעה תחת הדלת אחר שנטמאה טהורה מטומאתה אע\\\"פ שמשתמש בה אחרי שקבעה בדלת היתה טמאה כלומר אבל אם היתה ראויה לקבל טומאה ולא נטמאה ועשאה תחת הדלת טמאה כלומר עדיין היא מקבלת טומאה כמו שהיתה עד שתטהר כלומר עד שישנה מעשיה והדר קאמר מאימתי היא טהרתה ארישא קאי כדפרישית במתניתין:\",3,0],[8,380,12,1,\"כלי עץ וכלי עור וכו'. ריש פרק ב' וריש פרק ט\\\"ו דכלים:\",1,0],[8,380,12,1,\"ומ\\\"ש וכן כלי מתכות וכו' חזרו לטומאה הישנה. שם רפי\\\"א:\",2,0],[8,380,12,2,\"ומפני מה גזרו על כלי מתכות וכו'. פרק קמא דשבת עלה י\\\"ו:\",1,0],[8,380,12,3,\"אחד כלי שנטמא במת או בשאר הטומאות וכו'. רפי\\\"א וכתנא קמא:\",1,0],[8,380,12,3,\"נטמא במת והזה עליו בשלישי וכו'. סוף פרק י\\\"ד וכרבי יהושע:\",2,0],[8,380,12,3,\"וכתב הראב\\\"ד ואין לו טהרה עד שיזה עליו שלישי ושביעי ויטביל כשהוא כלי קודם שבירה או יזה עליו שלישי ושביעי ויטביל אחר שיתיכנו א\\\"א אני לא הכרתי דבריו וכו'. ואין הכרח בדבר:\",3,0],[8,380,12,4,\"ברזל טמא וכו' וכן טיט שבללו בגללים וכו'. פי\\\"א:\",1,0],[8,380,12,5,\"כלי מתכות וכו'. תוספתא פרק שמיני אלא שכתובה בחילוף וכך היא גירסת ר\\\"ש:\",1,0],[8,380,12,8,\"קרדום שעשאו וכו' עד אחר המקבל. שם:\",1,0],[8,380,12,9,\"כלי מתכות שנטמא וכו':\",1,0],[8,380,12,15,\"כלי זכוכית שנטמאו וכו'. פרק קמא דשבת (דף י\\\"ו):\",1,0],[8,380,12,15,\"וכן כלי זכוכית שנשברו וכו' עד ברוב גובהו טהור. בסוף כלים:\",2,0],[8,380,12,15,\"ומה שכתב דצלוחית קטנה היא הניטלת ביד אחת וגדולה היא הניטלת בשתי ידים. הכי משמע בתוספתא בסוף כלים. וכתב הראב\\\"ד נפגם בו שליש א\\\"א דעת כריסו היא וכו' ואני אומר שרבינו היה גורס שליש ברובו ופירושו בה נכון והראב\\\"ד היה גורס שלש ולפיכך פירש מה שפירש:\",3,0],[8,380,12,15,\"ומה שכתב ניקב וסתמו וכו'. שם וכת\\\"ק:\",4,0],[8,380,12,15,\"והכוס והצלוחית וכו' עד מקבלים טומאה. תוספתא בסוף כלים:\",5,0],[8,380,12,17,\"זכוכית שעושים אותה למראה טהור וכו'. משנה שם אספקלריא טהורה:\",1,0],[8,380,12,17,\"התרווד של זכוכית וכו'. שם וכר\\\"ע מחבירו:\",2,0],[8,380,12,18,\"תמחוי של זכוכית וכו'. שם תמחוי שעשאו אספקלריא טמא ואם מתחילה עשאו לשם אספקלריא טהור:\",1,0],[8,380,12,18,\"וכל כלי זכוכית וכו'. תוספתא בסוף כלים:\",2,0],[8,380,13,2,\"כבר ביארנו וכו' נמצא הטמא בכלי חרס וכו' עד אוכלים ומשקין עד שיגעו בהן. פ\\\"ק דחולין (דף כ\\\"ד ע\\\"ב). ומה שהביא ראיה מדכתיב אל תוכו מתוכו הוא מתטמא וכו' בת\\\"כ הוא ובפרק קמא דחולין מייתי לה מקרא אחרינא:\",1,0],[8,380,13,3,\"אין כלי חרס מטמא כלים מאוירו וכו' עד ואתה טמאתני. פרק שמיני דכלים ופ' שמיני דפרה:\",1,0],[8,380,13,4,\"כלי חרס שנגעו משקין טמאים וכו' נגעו אוכלין וכו'. ריש פרק ב' דכלים גבי כלי חרס מיטמאים מאחוריהם:\",1,0],[8,380,13,4,\"כתב הראב\\\"ד א\\\"א כבר כתבתי במקום אחר מה שנראה לנו על זה עכ\\\"ל:\",2,0],[8,380,13,5,\"אחד כלי חרס שנכנסה טומאה לאוירו וכו': כתב הראב\\\"ד מפי השמועה למדו שזה שנאמר אל תוכו לרבות את האהלים א\\\"א הלכתא כוותיה ולא מטעמיה וכו':\",1,0],[8,380,13,6,\"גומא שהיה השרץ וכו' לפיכך השרץ שנמצא וכו' עד אין לו במה יתלה. משנה פרק ט' דכלים:\",1,0],[8,380,13,6,\"נמצאו בנחושתו של תנור וכו'. שם:\",2,0],[8,380,13,8,\"ומ\\\"ש נמצא שרץ במקום הנחת עצים וכו'. שם וכחכמים:\",1,0],[8,380,13,9,\"השרץ שנמצא בעין של תנור וכו' עד מן הסתימה ולפנים. שם פרק שמיני:\",1,0],[8,380,13,9,\"כתב הראב\\\"ד וכן אם נמצא באויר העין טהור וכו'. א\\\"א זה כתב מפני שראה במשנה וכו'. גם ר\\\"ש פירש כפירוש הראב\\\"ד ולא נתחוור רבינו בפי' זה משום דמאי קמ\\\"ל דאם היה התנור באויר אפילו כזית מן המת טהור מילתא דפשיטא היא:\",2,0],[8,380,13,10,\"כלי חרס ששותים בו וכו'. בספ\\\"ב המסרק של צרצור רבי אליעזר מטהר וחכמים מטמאים:\",1,0],[8,380,13,11,\"כלי חרס שהיו לו ג' שפיות וכו'. ספ\\\"ד.\",1,0],[8,380,13,11,\"ומ\\\"ש היו שוות וכו'. שם וכחכמים:\",2,0],[8,380,13,12,\"אלפסים זו בתוך זו וכו'. שם ספ\\\"י:\",1,0],[8,380,13,12,\"כתב הראב\\\"ד היה השרץ בתחתונה וכו' עד חוזר ומטמא את האלפס א\\\"א אני כתבתי עודפות וכו'. ומה שכתב וסוף דבר אין זה כלום שא\\\"כ הכל טמא מאויר התחתונה, לא ירדתי לעומק דעתו שמאחר שהוא ז\\\"ל מעלה כאן דכל מה שהוא תוך אויר התחתונ' נטמא ולא נפטר מטומאה מטעם תוך תוכו היאך חזר וכתב שכששתיהן שוות ועודפות על האמצעיות כולן טהורות חוץ מן העליונה שכל האמצעיות שהתחתונה עודפת עליהן ה\\\"ל להיות טמאות דהא לא מטהרי משום תוך תוכו כפי מ\\\"ש בסמוך וצ\\\"ע. ומה שכתב ומכאן יש סיוע למ\\\"ש שהמשקה מטמא כלי חרס מגבו, ורבינו בפי' המשנה כתב וז\\\"ל כבר ביארנו במה שקדם אמרם בכלי חרס אל תוכו ולא תוך תוכו וכו' והוא פירוש יפה:\",2,0],[8,380,13,13,\"טבלא של חרס וכו'. בסוף פרק שני:\",1,0],[8,380,13,14,\"ומ\\\"ש היו בתיו קבועים במסמר וכו': כתב הראב\\\"ד היו בתיו קבועים א\\\"א והוא שיש שם דופן עודף עכ\\\"ל. ופשוט הוא נלמד ממתניתין דבסמוך ולכן לא חשש רבינו לכתבו:\",1,0],[8,380,14,1,\"כל המציל בצמיד פתיל וכו'. פרק שמיני בית שאור מוקף צמיד פתיל ונתון לתוך התנור וכו' ופירש שם רבינו יצטרך שנקדים בכאן שרשים וכו':\",1,0],[8,380,14,3,\"ומ\\\"ש טבעת טמאה וכו'. פ\\\"ט כוש שבלע את הצינורא ומלמד שבלע את הדרבן לבינה שבלעה את הטבעת וכו':\",1,0],[8,380,14,4,\"תרנגול שבלע שרץ וכו'. גם זה שם:\",1,0],[8,380,14,5,\"דברים שבתוך הפה וכו' כיצד אדם וכו'. גם זה שם מגע טמא מת שהיו אוכלים ומשקים לתוך פיו וכו'.\",1,0],[8,380,14,5,\"ומ\\\"ש והיה לו בתוך קומטו כו'. פרק יוצא דופן עלה מ\\\"ב ע\\\"כ:\",2,0],[8,380,14,5,\"כתב הראב\\\"ד שסוף משקה לצאת א\\\"א יש כאן שיבוש וכו'. ואיני יודע מה שיבוש יש כאן שרבינו העתיק לשון המשנה ואם מפני שלא כתב דין התוספתא י\\\"ל שמאחר ששנינו וכן חתיכה של לפת ושל גמי משמע בהדיא דדוקא הני משום דדמו לספוג אבל שאר דברים דינם כחרסים דקתני שאם לא הוסק התנור טהור:\",3,0],[8,380,14,6,\"ספוג שבלע וכו'. פ\\\"ט וכת\\\"ק.\",1,0],[8,380,14,6,\"ומ\\\"ש בד\\\"א במשקין וכו'. פרק האשה שהיא עושה צרכיה עלה ס\\\"ב ע\\\"ב כר\\\"י וכאוקימתא דרב פפא.\",2,0],[8,380,14,6,\"ומ\\\"ש וכן בגפת חדשה וכו'. פרק תשיעי דכלים:\",3,0],[8,380,14,7,\"כלי חרס שחלקו במחיצה וכו' לפיכך תנור שחצצו וכו'. ריש פרק ח' וכתנא קמא:\",1,0],[8,380,14,9,\"כלי שהיתה הטומאה בתוכו וכו'. בספ\\\"ק דחולין (דף כ\\\"ה).\",1,0],[8,380,14,9,\"ומ\\\"ש כיצד כוורת או קופה וכו' עד נטמא. רפ\\\"ח שם:\",2,0],[8,380,14,9,\"וכמה יהיה בנקב אם היה בכלי שטף במוציא זיתים וכו': כתב הראב\\\"ד א\\\"א זה ההפרש לא נמצא בשום מקום וכו'. ודעת רבינו שכל נקב שמוציאו מתורת כלי הרי הוא כשבר כלי ואינו מציל בצמיד פתיל. ומה שכתב ומשנה שלימה היא בפ\\\"ח היינו דתנן ניקבו העשוי לאוכלים שיעורו כזיתים העשוי למשקים שיעורו המשקים [העשוי] לכך וכך מטילין אותו לחומרו בכונס משקה איני יודע מה הכרע מביא ממנה הראב\\\"ד שהרי רבינו כתבה ומפרשה בכלי חרס אבל בכלי שטף שיעורו לענין צמיד פתיל כשיעורן לקבל טומאה מהטעם שכתבתי.\",3,0],[8,380,14,9,\"ומ\\\"ש ואם היה בכלי חרס העשוי לאוכלים וכו' עד מטילין אותו לחומרו. ריש פ\\\"ג וסוף פ\\\"ט:\",4,0],[8,380,14,10,\"סתם נקב כלי חרס וכו'. כתב הראב\\\"ד טעה בכל זה וכו':\",1,0],[8,380,14,11,\"כוורת פחותה וכו'. משנה ריש פרק ח':\",1,0],[8,380,14,12,\"החמת והכפישה:\",1,0],[8,380,14,13,\"עור פשוט וכו':\",1,0],[8,380,14,14,\"כלי חרס שהיתה טומאה בתוכו וכו' לפיכך חבית שהיתה מליאה וכו' עד סוף הפרק. בפ\\\"ח חבית שהיא מליאה משקין [טהורין] ונתונה למטה מנחושתו של תנור וכו':\",1,0],[8,380,15,1,\"אין כלי חרס וכו'. סוף פרק ד' כלי חרס מאימתי מקבלין טומאה משיצרפן בכבשן והיא גמר מלאכתן.\",1,0],[8,380,15,1,\"ומ\\\"ש התנור משיסיקנו וכו' עד שיעורו ככירה. רפ\\\"ה:\",2,0],[8,380,15,2,\"תנור שהתחיל לבנותו וכו'. רפ\\\"ה תנור תחלתו ארבעה ושיריו ארבעה דברי רבי מאיר וחכמים אומרים במה דברים אמורים בגדול אבל בקטן תחלתו כל שהוא ושיריו ברובו ואמרינן בפרק העור והרוטב וכמה כל שהוא טפח:\",1,0],[8,380,15,2,\"הכירה משיתחיל בה [שלש] אצבעות וכו'. שם כירה תחלתה שלש ושיריה שלש.\",2,0],[8,380,15,2,\"ומ\\\"ש הכופח אם עשאו וכו'. שם:\",3,0],[8,380,15,3,\"תנור שהוסק מאחוריו וכו'. משנה פרק רביעי:\",1,0],[8,380,15,5,\"תנור שהסיקו להיות צולה בו וכו' עד נטמא הכל. תוספתא דכלים פ\\\"ד אלא שבסוף יש קצת שינוי:\",1,0],[8,380,15,5,\"וכתב הראב\\\"ד אני לא מצאתי בתוספתא כדבריו וכו'. משיג על רבינו מסוף התוספתא שהיא מוחלקת מנוסחת רבינו ונוסחת הראב\\\"ד אינה מכוונת דקתני סיפא נטמא אחד במשקין הרי חבירו טהור והלא ברישא הדין כן ואם כן מאי איכא בין רישא לסיפא ואי משום דקתני סיפא מטמא במגע ובאויר גם ברישא קתני דשרץ הכל טמא ואם תאמר דהכל טמא ברישא היינו החלק שנטמא והעובי שביניהן בלבד כדפירש הראב\\\"ד ובסיפא אם נטמא אחד נטמא גם חבירו הוה ליה לפרושי וא\\\"ת דבסיפא לא נטמא אלא הוא לבד ולא העובי שביניהם הוה ליה למיתני דרך שלילה לא נטמא חבירו ונראה שלפיכך כתב הראב\\\"ד ולא נתבררה אצלי כהוגן. ועל פסק רבינו ק\\\"ל דמשמע דרבי יוחנן בן נורי דאמר חולקים את עוביו לטעמיה אזיל דאמר במתניתין פרק ב' דכלים גבי בית תבלין של עץ שנטמא אחד מהן במשקה לא נטמא חבירו רבי יוחנן בן נורי אמר חולקים את עביו ומאחר דרבינו פסק כההיא בפרק דלא כרבי יוחנן בן נורי הכי נמי הוה ליה למיפסק בהא דלא כוותיה ואפשר לומר דכיון דהכא לא איפליגו רבנן משמע שיש איזה טעם לפלוגי בין ההיא דהתם להא דהכא:\",2,0],[8,380,15,6,\"תנור או כירה וכו'. סוף פ\\\"ה.\",1,0],[8,380,15,6,\"ומה שכתב כיצד אין מתטמאין מאוירן וכו':\",2,0],[8,380,15,7,\"תנור של מתכת שניקב וכו' עד עדיין אינה מקבלת טומאה. משנה שם:\",1,0],[8,380,15,8,\"תנור שאינו מחובר בארץ וכו'. פרק כל הכלים עלה קכ\\\"ה:\",1,0],[8,380,15,10,\"כור של צורפי מתכות וכו' עד מתטמאה. פרק ח' דכלים:\",1,0],[8,380,15,11,\"אבנים שחיברן זו לזו וכו'. תוספתא ריש פרק ד' דכלים וכרבי יהודה.\",1,0],[8,380,15,11,\"ומ\\\"ש וטירת הכירה טהור. שם:\",2,0],[8,380,15,12,\"שתי חביות וכו'. תוספתא דכלים פרק חמישי:\",1,0],[8,380,15,14,\"העושה שלשה פטפוטין וכו' עד של מתכת. משנה רפ\\\"ו דכלים.\",1,0],[8,380,15,14,\"ומ\\\"ש וכן אבנים שלא מירחם בטיט וכו' עד אינה מקבלת טומאה. שם:\",2,0],[8,380,15,18,\"האבן שהוא שופת עליה וכו' עד חזרו השתים של כירה לטומאתן. גם זה שם:\",1,0],[8,380,15,19,\"דוכן של חרס וכו' עד סוף הפרק. פרק ז'.\",1,0],[8,380,15,19,\"ומ\\\"ש לפיכך אם היה מחובר בארץ וכו':\",2,0],[8,380,16,1,\"תנור גדול וכו'. רפ\\\"ה דכלים ופרק העור והרוטב (חולין דף קכ\\\"ד).\",1,0],[8,380,16,1,\"ומה שכתב והכירה שיריה שלש אצבעות וכו' עד שיעורו ככירה. רפ\\\"ה דכלים:\",2,0],[8,380,16,2,\"תנור שנטמא וכו'. שם וכתנא קמא.\",1,0],[8,380,16,2,\"ומה שכתב חילקו לשנים וכו'. שם:\",2,0],[8,380,16,2,\"חילקו לשנים בשוה וכו'. פ\\\"ב דבכורות עלה י\\\"ז.\",3,0],[8,380,16,2,\"ומ\\\"ש אבל טבלא של חרס וכו':\",4,0],[8,380,16,3,\"תנור שחילקו לשלשה וכו' עד אופות בו והוא טהור. פרק ה' דכלים:\",1,0],[8,380,16,3,\"ומה שכתב היתה בו חוליא אחת וכו'. תוספתא פרק רביעי:\",2,0],[8,380,16,6,\"תנור שבא מחותך וכו' עד ואם לאו טהור. פרק חמישי דכלים:\",1,0],[8,380,16,7,\"המביא שברי חרס וכו'. תוספתא ריש פרק שלישי:\",1,0],[8,380,16,8,\"פטם שקרזלו וכו':\",1,0],[8,380,16,11,\"תנור של סדקין וכו' עד ואם יש בו רוב תנור מקבל טומאה. תוספתא פ\\\"ד:\",1,0],[8,380,16,12,\"תנור שנתן בו עפר עד חציו וכו'. משנה פרק ה':\",1,0],[8,380,16,13,\"הכירה מקום שפיתת וכו'. פרק כירה (שבת דף ל״ח ע״ב).\",1,0],[8,380,16,13,\"ומה שכתב לפיכך כירה שנחלקה וכו'. משנה פ\\\"ז דכלים:\",2,0],[8,380,16,14,\"הקלתות של בעלי בתים וכו' עד סוף הפרק. ריש פ\\\"ז:\",1,0],[8,380,17,2,\"כל ידות הכלים וכו': לפיכך האבן היוצאת וכו' עד שיעורו ככירה. פרק חמישי:\",1,0],[8,380,17,3,\"מוסף התנור וכו' עד ושל צבעים טהור. שם:\",1,0],[8,380,17,4,\"עטרת הכירה וכו' עד ואפילו על שלש אבנים טמאה. גם זה שם:\",1,0],[8,380,17,5,\"בית הפך וכו' גם זה שם וכר״מ ואע״ג דרבי שמעון פליג עליה פסק כר״מ משום דבפרק במה טומנין (שבת דף מ״ח ע״ב) אמרינן מאן תנא כל המחובר לו הרי הוא כמוהו ר״מ דתנן בית הפך ובית התבלין וכו' ועוד דר״מ מחמיר.\",1,0],[8,380,17,5,\"ומ\\\"ש לפי שאינם חיבור לה אלא מדברי סופרים וכו'. בפרק במה טומנין כן כתב רבינו שמשון וצריך עיון:\",2,0],[8,380,17,6,\"חצר הכירה וכו'. פ\\\"ז.\",1,0],[8,380,17,6,\"ומ\\\"ש לפי שאינה חיבור לה אלא מדבריהן. נלמד ממה שכתבתי בסמוך דאיתא בפרק במה טומנין. וכתב הראב\\\"ד אבל אם נטמאת אחת מהן מאוירה אין חבירתה טמאה וכו' א\\\"א לי נראה מ\\\"ש אינו מיטמא באויר וכו'. טעמו משום דמסיים בה במתניתין כיצד משערין אותה רבי ישמעאל אומר נותן את השפוד וכו' ופירש ר\\\"ש משום דכירה גבוה וכו' וגם רבינו פירש שם להיות חצר הכירה נגד פי הכירה אמר איך נדע מה מהאויר וכו'. ומשיג הראב\\\"ד על רבינו שהשמיט השערה זו דרבי ישמעאל דמדסתם לה סתומי משמע שכל שלא נכנס השרץ תוך כתלי החצר לא נטמא החצר ואפשר לומר שרבינו בכאן סובר דרבי ישמעאל לא לפרש דברי ת\\\"ק בא אלא לחלוק ופסק כת\\\"ק:\",2,0],[8,380,17,6,\"היתה חצר הכירה מופרשת וכו'. בפ\\\"ז:\",3,0],[8,380,17,7,\"ניטל אחד מהם וכו'. שם וכרבי מאיר לגבי רבי שמעון:\",1,0],[8,380,17,7,\"עשה לה שני הפטפוטים וכו'. גם זה שם וכר\\\"מ דמחמיר לגבי ר\\\"ש.\",2,0],[8,380,17,7,\"ומ\\\"ש ואין מדקדקים בכל השיעורים האלו וכו':\",3,0],[8,380,18,5,\"כלי חרס אינו מקבל טומאה וכו' לפיכך הכסא והמטה וכו' עד מסננת לתוכו את הירק. בפ\\\"ב:\",1,0],[8,380,18,5,\"ומ\\\"ש זה הכלל וכו'. תוספתא דכלים פרק ב'. כתב הראב\\\"ד וחבית הדפונה בשולי המחץ וכו' ולא נעשית לקבלה וכו' א\\\"א כלל כלל לא נתקבל בעיני זה הפירוש וכו'. ולא זכינו לדעת מה היה הראב\\\"ד מפרש בה ולדעת רבינו יש לומר דל\\\"ק שחבית זו קטנה ביותר ולא נעשית לקבלה אלא בית יד המחץ שהוא ניטל העושים אותו כמין חבית קטנה לנוי כן פירש רבינו בפירוש המשנה וקרוב לזה פירש ר\\\"ש:\",2,0],[8,380,18,5,\"וכתב עוד הראב\\\"ד חבית של שייטין חדה וארוכה עכ\\\"ל. ואיני יודע למה היא טהורה שאע\\\"פ שאינה יכולה לישב שלא מסומכת טמאה שלכך נעשית מתחלתה כמו שולי קורפיות ושולי קוסים הצדוניים שאע\\\"פ שאינם יכולים לישב שלא מסומכין טמאים מפני שלכך נעשו מתחילתן כדאיתא בפרק ד' ואפשר דשאני התם שנעשו לקבלה אלא שקשה א\\\"כ תיפוק לי מהאי טעמא לחוד כמ\\\"ש רבינו וג\\\"ז טעם רבינו שמשון שכתב חבית של שייטין כמין חבית חלולה מבפנים ואין לה פה כדי ללמד בה לשוט ע\\\"פ המים:\",3,0],[8,380,18,5,\"כתב עוד הראב\\\"ד וכן מגופת היוצרים שיש לה תוך טמאה א\\\"א זה כתב תחת מה שראה במשנה וכו'. וז\\\"ל בפירוש המשנה מגופת היוצרים וכו' ור\\\"ש פירש מגופת היוצרים להכי נקט יוצרים וכו':\",4,0],[8,380,18,6,\"טיטרוס אע\\\"פ שהוא נקוב וכו'. משנה שם כרבי יוסי:\",1,0],[8,380,18,6,\"כתב הראב\\\"ד א\\\"א אני שונה רבי יוסי מטמא וכו'. ועל מה שטען על רבינו מדרבי יוסי קתני מפני שהוא מוציא פרוטות והוא אמר אע\\\"פ שמוציא פרוטות י\\\"ל שכך פירוש דברי רבינו אע\\\"פ שהוא נקוב מתטמא מפני שאינו נקוב נקב גדול שיצאו ממנו כל המים אלא נקוב נקבים קטנים והמים יוצאים ממנו מעט מעט באיחור גדול ולזה נקרא מוציא פרוטות לא לומר שהנקב ההוא מוציא פרוטה קטנה כמו שכתב הראב\\\"ד בדעת רבינו אלא כמו שפירשתי וכן כתב בפירוש המשנה וז\\\"ל טיטרוס הוא כלי חרס תושבתו רחבה וכו' וכאן הוסיף שהרי המים מתכנסין בצדדין והם עשויין לקבלה וג\\\"ז בכלל מפני שהוא מוציא פרוטות שמתוך שהנקבים דקים ואין המים יוצאים אלא מעט מעט באיחור גדול המים מתכנסים בצדדין שאילו היו הנקבים גדולים לא היו המים מתכנסים ונמצא שלא היה נעשה לקבלה:\",2,0],[8,380,18,7,\"הלפיד של חרס וכו'. שם.\",1,0],[8,380,18,7,\"ומ\\\"ש וכן כל וכו'. זהו פירוש מה ששנינו שם ובית שקעו של נר מטמא באויר וכו' כן פירש שם רבינו:\",2,0],[8,380,18,8,\"גסטרא שמניחים וכו'. שם:\",1,0],[8,380,18,9,\"ספינה של חרס וכו'. שם ובפרק רבי עקיבא:\",1,0],[8,380,18,10,\"כל הכלים שנשברו וכו'. בת\\\"כ פרשת שמיני מנין לרבות שברי כלי חרס ת\\\"ל וכל כלי חרס:\",1,0],[8,380,18,10,\"כתב הראב\\\"ד מפני השמועה למדו שזה לא בא לרבות אלא שברי כלי חרס א\\\"א כמה אני תמה על זה וכו':\",2,0],[8,380,18,10,\"ומ\\\"ש בד\\\"א כשהיה לחרס זה תוך לקבל בו המשקין כשהיה החרס יושב לא סמוך. בפ\\\"ב דכלים הדקים שבכלי חרס וקרקרותיהן ודפנותיהן יושבים שלא מסומכים:\",3,0],[8,380,18,11,\"החרס שאינו יכול לישב וכו'. ריש פרק ד' וכת\\\"ק:\",1,0],[8,380,18,12,\"כלי חרס ששוליהם חדים וכו'. שם:\",1,0],[8,380,18,13,\"כמה יקבל החרס וכו'. בפ\\\"ב (דף ח') וכרבי ישמעאל וצ\\\"ע למה לא פסק כר\\\"ע ואפשר שסובר רבינו דרבי ישמעאל הוה רביה אך קשה דבמתניתין תנן מסאתים ועד שלש ועד חמש סאין בלוג דברי רבי ישמעאל ובדר\\\"ע תנן מלחמיות ועד חצבים גדולים בלוג וכיון שפסק ברישא כרבי ישמעאל אמאי נקט בסיפא לישנא דר\\\"ע ואפשר דעד חמש סאין דנקט רבי ישמעאל לאו דוקא חמש סאין דה\\\"ה לטפי ומשום הכי נקט חצבים גדולים לכלול כל מה שהם גדולים:\",1,0],[8,380,18,15,\"כלי חרס קטן וכו'. תוספתא פ\\\"ב הפכין והגלילין והחביות שביהודה יש להם קרקרנות ואין להם דפנות:\",1,0],[8,380,18,16,\"חזקת חרסים הנמצאים וכו'. תוספתא פ\\\"ג:\",1,0],[8,380,18,16,\"כתב הראב\\\"ד א\\\"א מצאתי נוסחא זו מוחלפת וכו'. ואני אומר נוסחא דידן כנוסחת רבינו ואיני יודע למה כתב הראב\\\"ד שאינו יודע שהרי מפורשת בדברי רבינו מפני שרוב חרסים הנמצאים בבית היוצר הם גסטריות לכלים כלומר הם ראויים להושיבם תחת הכלים לקבל המשקים הנוטפים מהם. ועל מה שפירש הראב\\\"ד לפי גירסתו ק\\\"ל שכתב והיוצר הסיקן עם שאר כלים שלא לצורך למה יסיקם שלא לצורך ועוד שכתב שאינן נחשבות בעצמן שהחשיבות מחשב השברים שאם הם ראויין לשמש תשמיש כלי כי לא אחשבינהו מאי הוי:\",2,0],[8,380,19,1,\"כמה שיעור השבר וכו'. בריש פרק ג' ובסוף פרק המצניע (שבת דף צ״ו):\",1,0],[8,380,19,2,\"ומ\\\"ש חמש מדות בכלי חרס וכו'. בס\\\"פ המצניע וכפירש\\\"י:\",1,0],[8,380,19,3,\"החבית שיעורה כאגוזים. בפרק כ\\\"ג דכלים וכרבי יהודה.\",1,0],[8,380,19,3,\"ומ\\\"ש האלפס והקדרה וכו'. שם:\",2,0],[8,380,19,3,\"וכן עריבה של חרס וכו'. תוספתא פ\\\"ג:\",3,0],[8,380,19,4,\"הפך והטני וכו'. משנה פרק שלישי וכתנא קמא:\",1,0],[8,380,19,6,\"חבית שנפחתה וכו'. רפ\\\"ד וכחכמים.\",1,0],[8,380,19,6,\"ומ\\\"ש נתרעעה וכו'. שם:\",2,0],[8,380,19,7,\"חבית שניטלו אזניה וכו'. בפ\\\"ד.\",1,0],[8,380,19,7,\"ומ\\\"ש אפילו אזן אחת וכו' עד נדונית כחבית. תוספתא פ\\\"ג:\",2,0],[8,380,19,8,\"חבית שנסדקה וכו'. משנה פ\\\"ב.\",1,0],[8,380,19,8,\"ומ\\\"ש והיאך יודע דבר זה וכו'. תוספתא פ\\\"ב:\",2,0],[8,380,19,9,\"גסטרא שנתרעעה וכו'. משנה פרק רביעי.\",1,0],[8,380,19,9,\"ומ\\\"ש וכן גסטרא שנפחתה וכו':\",2,0],[8,380,19,11,\"גסטרא שחדודין יוצאין ממנה וכו'. משנה פרק ד':\",1,0],[8,380,19,11,\"כתב הראב\\\"ד על מ\\\"ש נכנסה הטומאה באויר הגיסטרא אפילו היתה כנגד החידוד לא נטמא החידוד א\\\"א אני איני אומר כן אלא שאם נכנס שרץ לתוך הגיסטרא וכו'. יש לתת טעם לפירוש רבינו דכשם שמטמא במגע היינו לומר שאם נגע שרץ בגיסטרא נטמאו גם החידודין כך אינו מטמא באויר היינו לומר שאף ע\\\"פ שנטמאת הגיסטרא באויר לא נטמאו החידודין:\",2,0],[8,380,19,15,\"חבית שנתרעעה וכו' עד ואינן בכלל הכלים. משנה פרק שלישי:\",1,0],[8,380,19,16,\"ומ\\\"ש משפך של חרס וכו'. שם וכרבי עקיבא:\",1,0],[8,380,20,1,\"כבר ביארנו וכו'. רפי\\\"ז.\",1,0],[8,380,20,1,\"ומ\\\"ש לפיכך הטופל כלי חרס וכו' עד את הקרויה. פ\\\"ג:\",2,0],[8,380,20,2,\"הטופל כלי חרס וכו'. תוספתא רפ\\\"ג.\",1,0],[8,380,20,2,\"ומה שכתב טפל כלים וכו':\",2,0],[8,380,20,3,\"חבית שניקבה וכו'. תוספתא שם אלא שהגירסא מהופכת בנוסחאותנו. וזהו שכתב הראב\\\"ד ובגפסים אינו חיבור א\\\"א מצאתי בשתי נוסחאות בהיפך מזה באלו חיבור ובשאר דברים אינם חיבור. ונוסחא נכונה היא לענין זפת וסיד וגפסים שהם סותמים סתימה יפה אבל בבעץ וזפת אינה נכונה שאינן סותמים סתימה יפה:\",1,0],[8,380,20,4,\"דברים הלחים וכו'. משנה פרק ג' יבלית שטופלים בה הפטסים הנוגע בה טמא.\",1,0],[8,380,20,4,\"ומה שכתב שאפילו נטמא הכלי מאוירו, צ\\\"ע. ומפרש רבינו דהאי הנוגע בו היינו אוכלים ומשקים דוקא שאין כלי חרס מטמא אדם וכלים.\",2,0],[8,380,20,4,\"ומ\\\"ש טפילו של תנור וכו'. שם הנוגע בטיפולו של תנור טמא.\",3,0],[8,380,20,4,\"ומ\\\"ש והוא שיהא בעובי הטפילה טפח וכו' עד שלש אצבעות. תוספתא ריש פרק רביעי:\",4,0],[8,380,20,8,\"חבית שניקבה וכו' עד הרי זה כגוף הכלי. משנה פ\\\"ג:\",1,0],[8,380,20,8,\"כתב הראב\\\"ד מגופת חבית שטפל בטיט וכו'. א\\\"א טעה בהצעת וכו'. לא היה כאן מקום לכל החרדה הזאת שג\\\"כ רבינו סובר דמתניתין מילי מילי קתני כמו שמבואר בדבריו בפירוש המשנה וגם פה לא יוכל להזהר עוד ממה שעשה פה שהפסיק בין דין יבלית שטופלין בהם פטסים ונוגע בטפילת התנור לדין מגופת החבית בדברים אחרים ומה שהזכיר במגופת החבית שטפל בטיט עליה ועל החבית טעמו משום דמגופה פירושו סתימה כמו יגיפו הדלתות ומשמעה ששם אותה ע\\\"פ החבית בלא שום חיבור והא פשיטא דאינה חיבור ולא איצטריך לאשמועינן ולפיכך פירש דמיירי שטפל בטיט עליה ועל החבית והשתא קמשמע לן שאע\\\"פ שהיא מחוברת לחבית על ידי אותה טפילה אינה חיבור מפני שהיא עומדת לינטל. ומ\\\"ש מי ראה מעולם טפילה על גבי מגופה וכו' י\\\"ל דמעט טיט שמניחים על גבי מגופה כדי לחברה לחבית הלא גם הוא טופל יקרא ואין בדברי רבינו טעות:\",2,0],[8,380,20,9,\"בצק שבסדקי עריבה וכו'. משנה פרק אלו עוברין (פסחים דף מ״ו) וכאוקימתא דאסיק רב פפא:\",1,0],[8,380,20,10,\"המשיחות והרצועות וכו'. תוספתא פרק י\\\"ו דכלים אלא שיש בה קצת חסרון:\",1,0],[8,380,20,12,\"יד קורדום וכו' עד אפילו ארוכים כל שהן טמאים. משנה פרק כ\\\"ט דכלים:\",1,0],[8,380,20,13,\"מקל שעשאו יד לקורדום וכו' עד שאין כל הקורה חיבור. פרק כ':\",1,0],[8,380,20,16,\"עגלה שנטמאה וכו' עד לא נטמאת המצודה אפילו כשהיא מתוחה. בפרק כ\\\"א:\",1,0],[8,380,20,16,\"וכן מסכת נסוכה וכו' עד משפרעה טהור. שם:\",2,0],[8,380,20,17,\"החוט שהשילו למחט וכו' עד מן הקשר ולחוץ אינו חיבור. תוספתא פרק י\\\"ו אלא שיש בה חסרון:\",1,0],[8,380,20,17,\"החבל שהוא קשור בקופה וכו'. משנה בסוף מקואות:\",2,0],[8,380,21,5,\"החוטים היוצאים וכו' עד אינם חיבור. בפרק כ\\\"ט:\",1,0],[8,380,21,5,\"כתב הראב\\\"ד ושל חלוק שהוא קרוע וכו'. א\\\"א זה עשה תחת אפרקסותו ולא ידעתי וכו'. ורבינו שמשון בשם הגאון והערוך פירשו קרוב לדברי רבינו.\",2,0],[8,380,21,5,\"ומ״ש בשיעור הקנה והחוטים. בפרק הספינה (בבא בתרא דף פ״ט):\",3,0],[8,380,21,7,\"החבל שמסרגין וכו' עד על צורך המטה. פרק י\\\"ט החבל היוצא מן המטה עד חמשה טפחים טהור מחמשה ועד עשרה טמא מעשרה ולחוץ טהור ובפרק אלו טריפות (חולין דף נ\\\"ד ע\\\"ב) מסיק חמשה כלמעלה עשרה כלמטה:\",1,0],[8,380,21,8,\"אבנט של אריג וכו' עד הרי זה מקבל טומאה. פי\\\"ט:\",1,0],[8,380,21,9,\"מטה שהיתה טמאה מדרס וכו' עד מעשרה ולחוץ טהור. שם כרבי יוסי:\",1,0],[8,380,21,9,\"במה דברים אמורים למדרס אבל לשאר טומאות וכו':\",2,0],[8,380,21,11,\"מטה הטמאה וכו' עד פירשו טמאים טומאת ערב. בפרק י\\\"ט:\",1,0],[8,380,21,12,\"כרע שהיתה טמאה וכו' עד סוף הפרק. פרק שמנה עשר:\",1,0],[8,380,21,12,\"ומ\\\"ש ואם הזה על המטה טהרה וכו':\",2,0],[8,380,22,1,\"כמה שיעור הבגד וכו'. פרק כ\\\"ז.\",1,0],[8,380,22,1,\"ומה שכתב מכוונות עם המלל. כך היא הגירסא והיא בפרק כ\\\"ח שלש על שלש שאמרו חוץ מן המלל דברי רבי שמעון וחכמים אומרים שלש על שלש מכוונות ופירוש מלל דרך תופרי בגדים למלול מהבגד לכופלן מעט סביב התפירה ואח\\\"כ תופר:\",2,0],[8,380,22,1,\"במה דברים אמורים בבגדי צמר ופשתים וכו'. שבת פרק שני (דף כ\\\"ו כ\\\"ז):\",3,0],[8,380,22,1,\"אבל האורג בגד וכו'. נראה שכתב כן מדתניא בפרק במה אשה עלה ס\\\"ג ע\\\"ב אריג כל שהוא טמא.\",4,0],[8,380,22,1,\"ומה שכתב חוץ מטומאת מדרס וכו'. פשוט הוא:\",5,0],[8,380,22,2,\"הבגדים העבים וכו'. בפרק כ\\\"ח העבים והרכים אין בהם משום שלשה על שלשה:\",1,0],[8,380,22,3,\"כל הקליעות וכו'. פ\\\"ג דעדיות וכחכמים:\",1,0],[8,380,22,3,\"הקלע שבית קיבול אבן שבה ארוג וכו'. ג\\\"ז שם וכחכמים:\",2,0],[8,380,22,3,\"המכמורות והרשתות וכו'. בספ\\\"ג.\",3,0],[8,380,22,3,\"ומה שכתב העושה בגד מן החרם טהור מן זוטו מתטמא. בפכ\\\"ח:\",4,0],[8,380,22,4,\"עשה חלוק וכו'. תוספתא:\",1,0],[8,380,22,5,\"משמרת של יין וכו'. גם זה שם:\",1,0],[8,380,22,6,\"מטפחות ספרים. פרק כ\\\"ח וכב\\\"ה:\",1,0],[8,380,22,7,\"כסת הסבלים וכו' ומשמרת של יין אינה מתטמאה במדרס. פכ\\\"ח:\",1,0],[8,380,22,8,\"בגד שחישב עליו לצורות וכו'. פרק דם חטאת עלה צ\\\"ד:\",1,0],[8,380,22,8,\"בעה\\\"ב שעשה מטפחות וכו'. תוספתא דכלים פרק י\\\"ב:\",2,0],[8,380,22,9,\"חלוק העשוי כסבכה וכו'. בפ' כ\\\"ח חלוק של יוצאת החוץ העשוי כסבכה טמא ופירש רבינו של יוצאת החוץ אשר יצאו לשחוק הנה הן ילבשו זה המלבוש:\",1,0],[8,380,22,10,\"כפה שנתנו על הספר וכו'. בפכ\\\"ח:\",1,0],[8,380,22,11,\"העושה אספלנית כו' עד וראוי למשכב. שם וכתנא קמא:\",1,0],[8,380,22,12,\"מאימתי יקבל הבגד טומאה וכו':\",1,0],[8,380,22,15,\"סבכה שמניחות הבנות בראשיהן וכו' טהורה. בספכ\\\"ח:\",1,0],[8,380,22,19,\"חלוק של בגד וכו' עד מפני שהיא כאבנט. תוספתא פכ\\\"ג דכלים:\",1,0],[8,380,22,20,\"טלית של עני וכו'. תוספתא פרק כ\\\"ד דכלים:\",1,0],[8,380,22,21,\"מטליות שאין בהם שלשה על שלשה וכו' ואם חישב עליהם וכו'. בפ' דם חטאת עלה צ\\\"ד.\",1,0],[8,380,22,21,\"ומ\\\"ש שכל פחות משלש על שלש וכו'. משנה בכלים פכ\\\"ז:\",2,0],[8,380,22,22,\"פחות משלשה על שלשה וכו'. ריש פרק כ״ח דכלים פחות משלשה על שלשה שהתקינו לפקוק בו את המרחץ ולנער בו את הקדירה ולקנח בו את הריחים בין מן המוכן בין שאינו מוכן טמא דברי רבי אליעזר רבי יהושע אומר בין מן המוכן בין שאינו מן המוכן טהור רבי עקיבא אומר מן המוכן טמא משאינו מוכן טהור ובפרק במה מדליקין (שבת דף כ״ט) מפרש דבהניחו בקופסא כ״ע לא פליגי דטמא ובזרקו לאשפה כ״ע לא פליגי דטהור כ״פ בתלאו במגוד דהיינו יתד או הניחו אחורי הדלת ומסיק התם דהדר ביה רבי עקיבא לגבי רבי יהושע הלכך הלכה כרבי יהושע ואם כן יש לתמוה על רבינו למה פסק בתלאו במגוד או הניחו אחורי הדלת שהוא טמא וצריך עיון:\",1,0],[8,380,22,23,\"שלשה על שלשה שהיה מושלך באשפה וכו'. פרק כ\\\"ז דכלים.\",1,0],[8,380,22,23,\"ומ\\\"ש מלח גס. ג\\\"ז שם וכחכמים:\",2,0],[8,380,22,26,\"שלשה על שלשה שנקרע וכו' עד מפני שהיא חשובה. שם:\",1,0],[8,380,22,26,\"כתב הראב\\\"ד שלשה על שלשה א\\\"א לשון התוספתא שבכה שנקרעה וכו'. וצריך עיון:\",2,0],[8,380,22,27,\"שלש על שלש שנתנה בכדור וכו' עד סוף הפרק. ריש פרק כ\\\"ח.\",1,0],[8,380,22,27,\"ועל מה שכתב ומתטמא במדרס כתב הראב\\\"ד אני אין לי אלא שאר טומאות וכו'. ורבינו מפרשה לענין טומאת מדרס שלשה על שלשה טפחים מיטמא בו ואין בזה הכרע:\",2,0],[8,380,23,1,\"המפץ הוא המחצלת וכו' ואעפ\\\"כ מתטמא היא במדרס וכו'. ומ\\\"ש וכן מתטמא במת וכו'. בפרק ג' דעדיות ובספ\\\"ק דסוכה (דף כ').\",1,0],[8,380,23,1,\"ומ״ש וזה כלל גדול וכו'. משנה פרק בא סימן (נדה דף מ״ח):\",2,0],[8,380,23,2,\"כבר ביארנו וכו' השק שיעורו וכו' עד טהורים מכלום. פרק כ\\\"ז דכלים:\",1,0],[8,380,23,3,\"במה דברים אמורים בקרע אחד מהם וכו' אבל הקוצץ בכוונה וכו' עד טהור מכלום. סוף פרק ד' דמעילה (דף יח):\",1,0],[8,380,23,3,\"כתב הראב\\\"ד שכל פחות משלש אצבעות על שלש טהור א\\\"א זה כתב מדעתו וכו'. ואני אומר שאין לומר שכתב זה מדעתו אלא איזה בקיאות מצא דהאי כל שהוא אינו אלא בערך שאר שיעורים אבל צריך שלא יהיה פחות משלש אצבעות. ומה שכתב ואולי במקצע ולפיכך אפילו כל שהוא וכו'. לא הבנתי דהא רבינו במקצע מיירי ואפילו הכי התנה שלא יהיה פחות משלש אצבעות וצ\\\"ע:\",2,0],[8,380,23,4,\"המחבר שני טפחים וכו'. פרק כ' דכלים:\",1,0],[8,380,23,5,\"בלויי נפה וכו'. שם וכחכמים:\",1,0],[8,380,23,7,\"חלוק של קטן וכו'. גם זה שם וכחכמים:\",1,0],[8,380,23,7,\"ואלו נמדדים כפולים וכו' עד בכל הטומאות. גם זה שם:\",2,0],[8,380,23,8,\"מטלית שהיא מדרס וכו' עד על האריג. פרק כ\\\"ח דכלים:\",1,0],[8,380,23,8,\"תפר המטלית על הבגד וכו' עד ונעשה הכל אב. שם וכחכמים:\",2,0],[8,380,23,9,\"שלשה על שלשה שנטמא במדרס וכו'. בפרק כ\\\"ז דכלים וכרבי יוסי.\",1,0],[8,380,23,9,\"ומ״ש אבל בגד שנטמא במדרס וכו'. בפרק בהמה המקשה (חולין דף ע״ב) ופירוש רבינו שלא כפירוש רש״י:\",2,0],[8,380,23,10,\"סדין שנטמא במדרס וכו'. פ\\\"ב וכבית הלל:\",1,0],[8,380,23,11,\"טלית שהיא מדרס וכו' עד סוף הפרק. בפרק העור והרוטב (חולין דף קכ״ג):\",1,0],[8,380,24,1,\"אלו עורות מתטמאין במדרס וכו'. פרק כ\\\"ו דכלים.\",1,0],[8,380,24,1,\"ומה שכתב ועור שעשאהו לנותנו על לבו בשעת הקציר וכו'. תוספתא פרק ד' [דבבא מציעא] דכלים.\",2,0],[8,380,24,1,\"ומה שכתב ועור שלופפין הכסות בו ועור התפור בתיבה. משנה בפכ\\\"ו עב כסות ותכריך כסות מדרס.\",3,0],[8,380,24,1,\"ומה שכתב כל העורות המתטמאין במדרס וכו'. שם:\",4,0],[8,380,24,2,\"ואלו עורות שאין מתטמאין במדרס וכו'. שם עור הסרוק עור הסורק ר\\\"א אומר מדרס וחכ\\\"א טמא מת.\",1,0],[8,380,24,2,\"ומ\\\"ש ועור שלופף בו הארגמן וכו'. שם עב הארגמן ותכריך ארגמן ב\\\"ש אומרים טמא מדרס וב\\\"ה אומרים טמא מת:\",2,0],[8,380,24,3,\"עור שעשאו חיפוי וכו'. שם וכת\\\"ק:\",1,0],[8,380,24,4,\"עור שעשאו לעקבו וכו'. תוספתא פ\\\"ד [דב\\\"ב] דמסכת כלים:\",1,0],[8,380,24,5,\"מנעל שעל האימום וכו'. משנה בפרק כ\\\"ו וכחכמים פירוש אימום פורמ\\\"א בלעז וטעמא משום דאינו מחוסר מלאכה הצריכה אומן שהדיוט יכול לשמטו מהאימום:\",1,0],[8,380,24,6,\"כל עור הראוי וכו'. שם כל מקום שאין חסרון מלאכה מחשבה מטמאתן וכל מקום שיש חסרון מלאכה אין מחשבה מטמאתן אלא הענבה ופירש רבינו עונבה עור שמחפין בו המרכב וכן פירש רבינו שמשון:\",1,0],[8,380,24,6,\"כתב הראב\\\"ד ואם חישב עליו להיות עור שלחן א\\\"א כמדומה אני זו היא קטבליא עכ\\\"ל ורבינו בפכ\\\"א פירוש סקרוטיא עור שאוכלין עליו וקטבליא פירוש עור ששוכבין עליו.\",2,0],[8,380,24,6,\"ומ\\\"ש רבינו ואם חישב עליו להיות עור שלחן וכיוצא בו הרי זה מתטמא במדרס. בפכ\\\"ו אלו עורות טמאים מדרס עור שחישב עליו לשטיח עור סקרוטיא עור קטבליא וכו' וכתבם רבינו בתחילת פרק זה.\",3,0],[8,380,24,6,\"ומ\\\"ש במה דברים אמורים בעורות בעל הבית וכו'. גם זה שם וטעמא משום דבעל הבית אינו עשוי למכרן ועושה מהם מטות ודלבקאות וטבליות ומשחישב עליהן לדבר שראוי לו בלא חסרון מלאכה מקבלין טומאה מיד ושל עבדן העשוי למכור אין מחשבה מטמאתו דעביד דמימליך ומזבין והלוקח יעשה מהם מנעלין ועדיין לא נגמרה מלאכתן לכך:\",4,0],[8,380,24,7,\"אין אדם מטמא במדרס וכו' שנאמר והנוגע במשכבו. פרק מרובה עלה ס\\\"ו.\",1,0],[8,380,24,7,\"ומ\\\"ש גזל משכב ודרס עליו וכו' גנב משכב וישב עליו טמא וכו'. מתבאר ממה שיבא וממה שקדם.\",2,0],[8,380,24,7,\"ומ\\\"ש ודרס עליו בלא נגיעה. טעמו שלא נתמעט משכב שאינו שלו אלא מטומאת מדרס לא מטומאת מגע ולפי זה מ\\\"ש גנב משכב וישב עליו טמא היינו אפילו בלא נגיעה ומכל מקום יש לתמוה דהא מיעוטא דמשכב שאינו שלו גבי נוגע כתיב.\",3,0],[8,380,24,7,\"ומ״ש לפיכך גנב שגנב עור וכו' עד אלא א״כ נתייאשו הבעלים. פרק כ״ו דכלים וכחכמים ובפרק הגוזל בתרא (בבא קמא דף קי״ד) אמר עולא מחלוקת בסתם אבל בידוע כלומר דשמעיניה דמייאש ד״ה יאוש קני ואף ע״ג דרבה פליג עליה משמע דהלכתא כוותיה דהא אביי דבתרא הוא סובר כוותיה ופשטא דמתניתין אתיא כוותיה ותו דהא דקאמר במרובה ואף רבי אלעזר סובר חיוביה לאחר יאוש אתיא כעולא ולפיכך כתב רבינו לעיל בסמוך גבי גזל משכב ואם נתייאשו הבעלים טמא:\",4,0],[8,380,24,8,\"עור שנטמא במדרס וכו'. ספכ\\\"ו וכחכמים:\",1,0],[8,380,24,9,\"כל כלי עור שנטמא במדרס הזב וכו'. תוספתא פרק ו' דב\\\"ב דמסכת כלים.\",1,0],[8,380,24,9,\"ומה שכתב כיצד החמת שעשה שטיח וכו'. משנה פרק כ\\\"ח דכלים:\",2,0],[8,380,24,11,\"כלים שעיקר עשייתן לקבלה וכו'. ריש פ\\\"ב דכלים הכרים והכסתות שנפחתו הרי אלו טמאים מדרס ופירש שם רבינו שאלו הכלים כאילו נעשו מתחילה לשני דברים יחד להיותה מכלי קיבול ולישב עליה ולזה כאשר נפחתו ויצאו מדין כלי קיבול ונטהרו מטומאת שרץ הנה נשארו בדין המשכב ויטמאו במדרס ופירוש מרצופין אלפרגא\\\"ש.\",1,0],[8,380,24,11,\"ומה שכתב אבל כלים שעיקר עשייתן לקבלה בלבד עד סאה. ג\\\"ז שם נפחתו וכו':\",2,0],[8,380,24,11,\"וכל החמתות שנפחתו וכו'. [פכ\\\"ו מ\\\"ד] וכת\\\"ק:\",3,0],[8,380,24,11,\"וחמת חלילין וכו'. בפרק כ':\",4,0],[8,380,25,1,\"כל פשוטי כלי עץ וכו'. תורת כהנים:\",1,0],[8,380,25,2,\"המטה והכר וכו' עד את הכלים. פרק כ״ג ופירש רבינו שמשון של מת המיוחדים למת והטעם שהם טמאים מדרס מפרש בתוספתא מפני שהנשים יושבות עליהם ומבכות מתיהם. ומשבר של חיה עשו לישב עליו בעת הלידה וכסא של כובס שהוא כובס עליו את הכלים רבינו ור״ש פירשו שהוא מכבש ולפי דבריהם יהיה טמא מדרס מפני שיושב עליו כשהכלים בתוכו להדקו כדי שיכבשו הכלים ועל מה שפירש רש״י בפרק רבי עקיבא (שבת דף פ״ח ע״ב) שהוא דף ארוכה מנוקבת נקבים הרבה [ומאספים עליה בגדים] ומניח מוגמר תחתיה והבגדים מתגמרים צריך לומר שכשמאספים עליה בגדים יושב עליה. ודע דמתניתין הכי איתא כסא של כלה וכו' אמר רבי יוסי אין בהם משום מושב ואף על גב דבמתניתין הכא ליכא מאן דפליג עליה משמע לרבינו דכיון דמשמא דיחידאה קאמר לה פליגי עליה רבים ועוד דמתניתין ספכ״ב דכסא של כלה שניטלו חפויו בפשטא פליגא ארבי יוסי:\",1,0],[8,380,25,2,\"ומה שכתב וכסא של קטן וכו'. בפרק כ\\\"ג:\",2,0],[8,380,25,5,\"כסא של ברזל וכו' עד ואחת של שיש אינו מקבל טומאה. בספכ\\\"ב ופירוש טרסקל סל:\",1,0],[8,380,25,5,\"כתב הראב\\\"ד הפריש העור המחופה על הברזל וכו'. א\\\"א נ\\\"ל בשנטמא כשהוא מחובר קאמר וכו'. ואני אומר פירוש הראב\\\"ד יפה הוא אבל מדברי רבינו נראה שהוא מפרש כפירוש האחר שכתב מתטמא דמשמעו מקבל טומאה ומה שהוקשה להראב\\\"ד על אותו פירוש יש לומר דסד\\\"א דכיון דהופרש העור מן ברזל ה\\\"ל ככלי שנשבר ולא יטמא לא זה ולא זה קמ\\\"ל:\",2,0],[8,380,25,6,\"ומ\\\"ש נסרים שבמרחץ וכו'. שם וכחכמים ופירש רבינו ששגמן כמו שעמן והוא הגמי והכוונה בזה כי כאשר חיברן בשעם עד ששבו לוח אחד הבלנים ישבו עליהם והמים ילכו תחתיהם אומרים חכמים שהם לא יטמאו במדרס הזב מפני שאינם עשויים לכוונה שישבו עליהם אלא שילכו המים תחתיהם:\",1,0],[8,380,25,7,\"הכלכלה והסל וכו'. בספכ\\\"ב:\",1,0],[8,380,25,8,\"קורות בית הבד שעשה ראשה האחד כסא וכו'. בפכ\\\"ב כסא אין טמא אלא מקומו קבעו בקורת בית הבד טמא ואינו חיבור לה עשה בראשה כסא טהור מפני שאומרים לו עמוד ונעשה מלאכתנו:\",1,0],[8,380,25,8,\"ומ\\\"ש וכן אם קבע הכסא בקורה גדולה וכו' וכן הדין בכסא שקבעו בעריבה וכו'. בפכ\\\"ב כסא שקבעו בעריבה בית שמאי מטמאין ובית הלל מטהרין וידוע דהלכה כבית הלל וא\\\"ת מ\\\"ש מכסא שקבעו בקורת בית הבד שהוא טמא ויש לומר דהאי נמי הכסא טמא ולא אמרו בית הלל מטהרים אלא לענין שאינו חיבור לה שאם נטמאת העריבה לא נטמא הכסא:\",2,0],[8,380,25,9,\"קצת הקורה וכו'. בפרק כ\\\"ב ישיבת הסתת טמאה מדרס.\",1,0],[8,380,25,9,\"ומ\\\"ש ומקום ישיבה שאחורי הקרון וכו'. תוספתא פ\\\"א דב\\\"ב דמסכת כלים:\",2,0],[8,380,25,10,\"ראשי כלונסות וכו'. תוספתא פרק ב' דב\\\"ב שם.\",1,0],[8,380,25,10,\"ומ\\\"ש וכן כופת של תמרה וכו'. תוספתא דכלים שם כופת חלק שאין בו גובה טפח טהור ושיש בו גובה טפח רבי מאיר ורבי שמעון מטמאים רבי יוסי ורבי אלעזר ברבי צדוק מטהרים ומשמע התם דהלכה כמטהרים ופירוש כופת חתיכת עץ.\",2,0],[8,380,25,10,\"ומה שכתב וכן בול של עץ וכו'. משנה פכ\\\"ב דכלים כופת שסירקו וכרכמו ועשאו פנים רבי עקיבא מטמא וחכמים מטהרים עד שיחוק בו ובול הוא חתיכת עץ מלשון לבול עץ אסגוד (ישעיהו מ״ד:י״ט):\",3,0],[8,380,25,11,\"ראשי כלונסאות החקוקין עד טהורים. תוספתא פ\\\"ב דב\\\"ב:\",1,0],[8,380,25,13,\"העושה כפה וכו' מחצלת וכו'. בספי\\\"ז מחצלת הקש ר\\\"ע מטמא ור\\\"י בן נורי מטהר והלכה כר\\\"ע מחבירו ותנן תו התם של קנים ושל חלף טהורה ומפרש כאן רבינו דהיינו לומר שהיא טהורה מן המדרס וז\\\"ל הטעם מפני שמתוך שהיא קשה אינה ראויה לשכיבה ובפי' המשנה כתב רבינו דטהורה מטומאת שרץ קאמר אבל טמאה מדרס ומ\\\"ש כאן נ\\\"ל עיקר.\",1,0],[8,380,25,13,\"ומ\\\"ש ושאר המחצלאות וכו'. בספ\\\"ק דסוכה (דף כ') וכת\\\"ק:\",2,0],[8,380,25,14,\"מחצלת שעשה לה קנים וכו'. בסוף פרק כ' מחצלת שעשה לה קנים לארכה טהורה וחכמים אומרים עד שיעשה כמין כי פירוש כשעשה קנים לארכה אינה ראויה לשכיבה שהקנים מזיקים לשוכב ולפיכך היא טהורה וחכ\\\"א עד שימשוך הקנים עליו משלשה צדדין על דמיון כי יונית כן כתב רבינו בפירוש המשנה.\",1,0],[8,380,25,14,\"ומה שכתב כאן כעין גאם ט\\\"ס הוא וצריך להגיה כמין כי וידוע דהלכה כחכמים.\",2,0],[8,380,25,14,\"ומ\\\"ש נחלקה לרחבה וכו'. שם ודלא כר\\\"י דיחידאה הוא.\",3,0],[8,380,25,14,\"ומה שכתב לאורכה וכו' עד ותתנקב. שם ופירש שם רבינו ראשי מעדנים הן קצות הקשרים הגדולים אשר יקשרו בקצות החבל אשר יארגו בהם המחצלאות ויחבר הקנים וכאשר התיר קצות החבל הנה כבר נשרו כולם ושבו בדמיון קנים מפורדים ולזה לא תטמא.\",4,0],[8,380,25,14,\"ומ\\\"ש כמו שביארנו הוא בפ\\\"ה:\",5,0],[8,380,25,15,\"תיבה שפתחה וכו' פתחה מצדה וכו'. בספי\\\"ט:\",1,0],[8,380,25,16,\"עגלה של קטן וכו'. משנה בספ\\\"ב דיו\\\"ט (דף כ\\\"ג:):\",1,0],[8,380,25,17,\"מקל של זקנים וכו'. בס״פ במה אשה (שבת דף ס״ז) מפרש רבא טעמא דטהור משום דלתרוצא עבידא ופירש״י לתקן פסיעותיו ולזקוף קומה מפני שרגליו ושוקיו רותתות ולא לסמיכת כל גופו:\",1,0],[8,380,25,18,\"סנדל של סיידין וכו'. בפרק ג' דעדיות סנדל של סיידין ר״ע מטמא וחכמים מטהרים ופסק רבינו כר״ע משום דאמרינן בסוף פרק במה אשה (שבת דף ס״ו) דר״מ סבר כוותיה ורבי יוסי או ר״י בן נורי פליג עליה א״כ הו״ל ר״ע ור״מ רבים ופירש״י סנדל של סיידין מוכרי סיד וכשמתעסקין בו נועלים אותו ושל עץ הוא מפני שהסיד שורף העור ומקשה בגמרא טמא מדרס הא לאו להילוכא עבידי אמר רב אחא בר רב עולא שכן הסייד מטייל בו עד שמגיע לביתו:\",1,0],[8,380,25,19,\"קב של קיטע וכו'. משנה סוף פרק במה אשה.\",1,0],[8,380,25,19,\"ומ\\\"ש ומתטמא במדרס. שם כרבא:\",2,0],[8,380,25,20,\"ואלו טמאים משום מרכב וכו'. בפרק כ\\\"ג דכלים אלו טמאים משום מרכב זירוז האשקלוני ומדוכה המדית ועביט של גמל וטפיטן של סוס ר\\\"י אומר טפיטן של סוס טמא משום מושב מפני שעומדין עליו בקומפון אבל אוכף של נאקה טמא ומשמע לרבינו דמדוכה המדית היינו מרדעת החמור. כתב הראב\\\"ד א\\\"א אוכף של נאקה וכו'. ואמת שרבינו בפירוש המשנה פירש כהראב\\\"ד אבל אין הפירוש ההוא מוכרח וכבר אפשר לפרש דמאי דקתני אבל אוכף של נאקה טמא רבי יוסי קאמר לה דמודה רבי יוסי בשל נאקה שאינו מיוחד אלא לרכיבה וכבר כתב הר\\\"ר עובדיה ז\\\"ל שרבותיו פירשו כן וזהו פירוש של רבינו כאן:\",1,0],[8,380,26,1,\"כלי עץ וכו'. בפרק כ' כופת שקבעו בנדבך וכו' עד ונתן עליו את המעזיבה טהור אך מה\",1,0],[8,380,26,1,\"שכתב קבעו במסמרים וכו' אינו במשנה אבל נלמד הוא מסברא דעדיף מקבעו בבנין:\",2,0],[8,380,26,2,\"ספסל שניטל אחד מראשיו וכו'. בפכ\\\"ב אלא שגירסת המשנה בניטל אחד מראשיו טהור וצ\\\"ע וטעמא דאם יש בו גובה טפח טמא משום דאז ראוי לישב עליו ובפחות מטפח הוי כיושב על הקרקע:\",1,0],[8,380,26,3,\"כסא של כלה וכו'. שם וכבית הלל ופר\\\"ש חיפוייו לשון חפי פותחת כמין שינים יוצאים מכל צד כדי שיסמכו עליהם וב\\\"ה מטהרים משום דלא חזי לכלה והוה כנשבר.\",1,0],[8,380,26,3,\"ומ\\\"ש ואם לא היו חיפוייו יוצאים וכו'. שם פירוש מחברים ד' נסרים יחד כמין תיבה בלי כיסוי ושולים ומניחים עליו שלשה נסרים זה בצד זה ונקראים חיפויים ויושבים עליהם וכשאינם בולטים מן הכסא מכל צד דרכו מתחלתו להיות מטהו על צדו ויושב עליו:\",2,0],[8,380,26,4,\"כסא שניטלו חיפוייו וכו'. נראה שזהו פירוש מה ששנו שם כסא שנטל חפויו האמצעית והחיצונים קיימים טמא ניטלו החיצונים והאמצעי קיים טמא.\",1,0],[8,380,26,4,\"ומה שכתב ניטלו שנים מחפוייו זה בצד זה טהור. שם וכחכמים:\",2,0],[8,380,26,5,\"שידה שניטל העליון וכו' עד טהורים. שם וכחכמים:\",1,0],[8,380,26,6,\"תיבה שנפחתה מצדה וכו' עד בטלה הטפלה. ספי\\\"ט:\",1,0],[8,380,26,7,\"עריבה של עץ וכו'. בפ\\\"כ עריבת פיסונות בש\\\"א מדרס ובה\\\"א טמא מת כלומר ולא מדרס.\",1,0],[8,380,26,7,\"ומ\\\"ש ושלשין בה את הבצק שמחזקת משני לוגין וכו'. גם זה שם עריבה משני לוגין עד תשעה קבין שנסדקה טמאה מדרס.\",2,0],[8,380,26,7,\"ומ\\\"ש עד שאינו יכול לרחוץ בה רגלו אחת וכו'. תוספתא פרק י\\\"ח דכלים אלא שנראה שכתובה בשיבוש:\",3,0],[8,380,26,7,\"ומה שכתב הניחה בגשמים וכו' עד וטהורה משאר טומאות. משנה פרק כ' דכלים:\",4,0],[8,380,26,7,\"כתב הראב\\\"ד לפי גודלה וסדק שלה א\\\"א אין דרך התוספתא כן וכו'. ורבינו לפי שראה דברי התוספתא כמעורבבין לא חש לכתבה:\",5,0],[8,380,26,8,\"עריבה גדולה וכו' עד בכל הטומאות. שם וכחכמים:\",1,0],[8,380,26,9,\"מטה שניטלו שתי ארוכות שלה וכו' עד שהכל הולך אחר הישנות. פי\\\"ט:\",1,0],[8,380,26,12,\"מטה שהיתה טמאה מדרס וכו' עד להבא. פי\\\"ח וכת\\\"ק דרבי נחמיה:\",1,0],[8,380,26,13,\"מטה שנפרקו איבריה וכו'. בפי\\\"ח דכלים מטה מיטמאה חבילה ומיטהרת חבילה דברי רבי אליעזר וחכמים אומרים מיטמאה איברים ומיטהרת איברים ובפ\\\"ק דסוכה עלה י\\\"ו מייתי לה וקאמר עלה מאי ניהו אמר רב חנן אמר רבי ארוכה ושתי כרעיים קצרה ושתי כרעיים למאי חזו למסמכינהו אגודא ולמיתב עלייהו ומישדא אשלי ופירש רש\\\"י למסמכינהו אגודא לקרבן אצל הכותל הרחב כמלא רוחב מטה ונותן עצים מן הכרעיים ולכותל למראשותיה ולמרגלותיה ומישדא אשלי ונותן חבלים ומסרג וראוי למשכב ומטמא מדרס:\",1,0],[8,380,26,13,\"וכתב הראב\\\"ד מפני שראויין לסמכן א\\\"א זה לדעת רבי נחמיה וכו'. כלומר משיג על רבינו שפסק כאן כרבי נחמיה שהוא יחידאה כלומר דהאי פלוגתא שייכא בדרבי נחמיה ות\\\"ק שכתבתי בסמוך ואי מהא לא הוה קשיא דאיכא למימר כיון דחכמים דר\\\"א סברי כרבי נחמיה נקטינן כוותייהו אבל מ\\\"ש דקשיא דידיה אדידיה קשיא דלעיל בסמוך פסק כתנא קמא דרבי נחמיה והכא פסק כרבי נחמיה וי\\\"ל שרבינו סובר דלא שייכא האי פלוגתא בהאי פלוגתא דפלוגתא דת\\\"ק ורבי נחמיה כשהיתה המטה טמאה מדרס ובהא הלכה כת\\\"ק דמטהר בניטלה ארוכה ושתי כרעיים דכיון שאין צורת המטה עומד אזלא לה טומאה ופלוגתא דרבי אליעזר וחכמים במטה טהורה וקאמרי חכמים שאע\\\"פ שניטלה ארוכה ושתי כרעיים מקבלת טומאה מפני שראויים לסמכן ולישן ולישנא דרבינו דייק הכי בהדיא ולישנא דמתניתין נמי דייקא הכי דגבי פלוגתא דרבי נחמיה קתני מטה שהיתה טמאה מדרס וגבי פלוגתא דר\\\"א קתני מטה מיטמאת איברים:\",2,0],[8,380,26,14,\"מטה שנטמאת כולה וכו'. משנה סוף פרק י\\\"ח וכחכמים וסוכה (דף י\\\"ו):\",1,0],[8,380,26,15,\"המפרק את המטה וכו'. ריש פרק י\\\"ט שם:\",1,0],[8,380,27,1,\"שלש תיבות הן וכו' עד (הלכה ט\\\"ו) ושעושין לשחק בה לשותי שכר טהורה מכלום. הכל בפרק כ\\\"ד וכתב שם רבינו לא יעלם ממך בכל זה הפרק השרש שקדם זכרו והוא אמרם כל הטמא מדרס מיטמא טמא מת [וכאשר יאמר טמא טמא מת הכוונה שלא יטמא מדרס] וכו' אבל יטמא במת ובשאר טומאות וכן פירש\\\"י בפרק רבי עקיבא. ופירש עוד בקתדרא קצרה ומוקפת מג' צדדין טמא מדרס שלישיבה היא מיוחדת. כמטה שהיא ארוכה ומתחתיה מקבלת גמעה של עור שאין בה שום נקב ואינה מיוחדת לישיבה. ושל אבנים העשויה להוליך בה אבנים טהורה מכלום אינה מקבלת שום טומאה לפי שפרוצה מתחתיה נקבים גדולים ולאו כלי הוא דכל הכלים שיעורן ברמונים עכ\\\"ל:\",1,0],[8,380,27,1,\"והבאה במדה היינו שמחזקת ארבעים סאה בלח שהם כוריים ביבש כדאיתא בפרק ט\\\"ו ממסכת כלים.\",2,0],[8,380,27,1,\"ודין תיבה שנפחתה מצדה טמאה אף מדרס שהרי ראויה לשכב עליה.\",3,0],[8,380,27,1,\"מלמעלה טמאה טמא מת ולא מדרס לפי שאם בא לישב עליה אומרים לו עמוד ונעשה מלאכתנו:\",4,0],[8,380,27,4,\"ודין תריס הכפוף הוא תריס גדול שמקיף את האדם משלש רוחותיו טמא מדרס מפני ששוכבים עליו במלחמה.\",1,0],[8,380,27,4,\"שמשחקים בו בקונפין כלומר פארה אישגר\\\"יימיר והוא קטן ואינו ראוי לשכב עליו.\",2,0],[8,380,27,4,\"דיצת הערביים הוא קטן ביותר והערביים עושים לדיצה ושמחה ואינו כלי של תשמיש וזהו שכתב\",3,0],[8,380,27,4,\"רבינו לפי שהיא עשויה לצורה:\",4,0],[8,380,27,5,\"ותרבוסים הם כלים של עור כעין ארגזים ושל ספרים והם מקיזי דם הם גדולים והם לישב או למזגא עלייהו והבאים\",1,0],[8,380,27,5,\"להקיז ושאוכלין עליו אינו ראוי לישב מפני שאומרים לו עמוד ונעשה מלאכתנו:\",2,0],[8,380,27,6,\"בססיות הם מושבות תרגום כנו בסיסיה ושלפני מטה ושלפני סופרים הם לישב עליהם ושל דלפקי אינו עשוי לישיבה שאין דרך לישב לפני הדלפקי ואין הבסיס שלפניו אלא לסדר עליו התבשילין כמו על הדלפקי:\",1,0],[8,380,27,7,\"ומטות של זגגין שנותנין בה כלי זכוכית תמיהא לי אמאי טמאה טמא מת מאי שנא מתרבוסין ששוטחין עליו זיתים דטהור מכלום מפני שאינו ממשמשי אדם:\",1,0],[8,380,27,8,\"ומשפלות הם קופות והיה דרכן לישב על של זבל ולא על של תבן.\",1,0],[8,380,27,8,\"ופוחלץ של גמלים סבכה שטוענים על הגמלים מליאה וטהורה מכלום מפני שנקביה רחבים ביותר:\",2,0],[8,380,27,9,\"ומפצין של צבעין תמיהא לי אמאי טמא טמא מת ומ\\\"ש מתרבוסין ששוטחין עליו\",1,0],[8,380,27,9,\"זיתים וממפץ של גתות שהם טהורים לפי שאינם ממשמשי אדם:\",2,0],[8,380,27,9,\"כתב הראב\\\"ד [לעיל ה\\\"ב] עריבה מב' לוגין ועד תשעה קבין שנסדקה טמאה מדרס א\\\"א והוא שחשב עליה לישיבה וכו'. כבר כתבתי בפרק שקודם זה שרבינו לא חשש לכתוב התוספתא מפני שהיא כמעורבבת:\",3,0],[8,380,27,9,\"כתב הראב\\\"ד לפי שאינו ממשמשי אדם א\\\"א זה הטעם מצא חן בעיניו וכו'. ואני אומר שמאחר שהטעם שנתן רבינו הוא צודק אם יש טעם אחר בדבר אין בכך כלום. ומה שכתב הראב\\\"ד כדי שלא יתלכלכו אצבעותיו בשמן העורות. איני יודע מהו וצ\\\"ע:\",4,0],[8,380,27,10,\"ומ\\\"ש שלש חמתות וכו'. שם.\",1,0],[8,380,27,10,\"ומ\\\"ש וכמה שיעורן החמת ד' קבין והתורמיל ה'. ברפ\\\"כ דכלים והטעם שכשהם גדולים כשיעור הזה או יותר הם משמשים מדרס עם מלאכתן אבל פחות לא. ושל עורות הדג טהור מכלום. מפני שכל כלי שנעשה מדבר הגדל בים אינו מקבל שום טומאה כדאיתא בפי\\\"ו דכלים:\",2,0],[8,380,27,12,\"ומ\\\"ש גבי שלשה סדינין העשוי לפרוכת טמא טמא מת. בסוף פירקא קמא דיום טוב (דף ד') מפרש טעמא מפני שהשמש מתחמם בו שמתעטף בשוליו יש לו תורת כלי:\",1,0],[8,380,27,13,\"ומ\\\"ש גבי ג' מטפחות של ידים טמאה מדרס. בירוש' פ\\\"ח דכלאים מפרש טעמא מפני שנותנה על פי הכסת וישן עליה ושל ספרים טמאה טמא מת ואינה טמאה מדרס מפני שאין משתמשים בהם ומ\\\"מ טמא טמא מת מפני שפעמים עושין אותה כמין תיק ונותנה בחיקו ומתחמם בה וכדרך שאמרו לענין איסור כלאים בירושלמי:\",1,0],[8,380,27,14,\"ומ\\\"ש גבי ג' פרקלינין של ציידי חיה ועוף טמא מדרס שהרי נשען עליו. איני יודע מה צורך לו להשען עליו:\",1,0],[8,380,27,15,\"ומ\\\"ש גבי ג' סבכות הן של ילדה טמאה מדרס. אפשר שהיו באותו זמן הילדות נותנות סבכה שלהן על פי כסת וישינות עליה והזקנות לא היו נוהגות כן:\",1,0],[8,380,27,15,\"כתב הראב\\\"ד ושעושין לשחק בה א\\\"א לשון המשנה ושל יוצאות החוץ טהורה מכלום וכו'. ורבינו נראה שמפרש של יוצאת החוץ (לאנשים) היוצאים מן השורה שהם שותי שכר ומשחקין קרי יוצאת החוץ וסבכה זו עשויה לשחק בה הליצנים לפני שותי שכר:\",2,0],[8,380,27,16,\"שלשה סנדלין הם וכו'. תוספתא דכלים פרק ב' דב״ב והגירסא הנכונה של מתכת של בהמה בלא וי״ו בפי״ד דמסכת כלים ומייתי לה בפרק במה אשה (שבת דף נ״ט) ומקשי גמרא למאי חזי ופרש״י אי [משום בהמה הא] אין תכשיט לבהמה ומשני אמר רב ראוי לשתות בו מים במלחמה ורבי חנינא אמר ראוי לסוך בו שמן במלחמה ור״י אמר בשעה שבורח מן הקרב מניחו ברגליו ורץ על הקוצים ועל הברקנים ותמהו התוספות לר״י יטמא מדרס וצ״ל דכיון שאינו נוטלו לשום מנעל אלא להנצל מן הקוצים ומן הברקנים לא חשיב מנעל.\",1,0],[8,380,27,16,\"ומ\\\"ש של שעם ושל צפירה טהור מכלום. נראה דחדא מילתא היא של שעם שגודלים אותו בסיבוב דצפירה לשון סיבוב הוא א\\\"נ צפירה שם מין גמי הוא וא\\\"ת אמאי טהורה מכלום וי\\\"ל דבשל בהמה מיירי וה\\\"ק של אדם בכל גווני טמא מדרס בין של עור בין של מתכת בין של שעם אבל של בהמה אם הוא של מתכת טמא טמא מת מטעמי דאמרינן בגמרא ואם הוא של שעם טהור מכלום דכלי בהמה טהורים:\",2,0],[8,380,27,16,\"כללו של דבר וכו'. ת\\\"כ.\",3,0],[8,380,27,16,\"ומ\\\"ש וכל המתטמא מדרס וכו'. משנה פרק בא סימן (עלה מ\\\"ט) וסוכה (עלה כ'):\",4,0],[8,380,27,17,\"שלש קופות הן וכו'. משנה פרק כ\\\"ד. כתב הראב\\\"ד שלש קופות הן וכו' שאם ניקבה במוציא רמון שתיהן טהורות א\\\"א לא נתחוור אצלי זה הטעם ולמה שתיהן טהורות וכו'. ואפשר לפרש דברי רבינו כאן דאין הכי נמי שאם היתה נקובה במוציא רמון ואחר כך תיקנה וטלה עליה שהיא טמאה והכא במאי עסקינן כשטלה על נקב קטן שהיה בה ואחר כך ניקבה הגדולה כמוציא רמון טהורה אף הקטנה אף על פי שהיא שלימה ועי\\\"ל דבניקבה הגדולה כמוציא רמון טהרה מטומאתה וכשטלה עליה הקטנה לא חזרה לטומאתה ואף על פי שהיתה זו הקטנה טמאה הרי היא כחלק מהגדולה וגם היא טהורה:\",1,0],[8,380,27,18,\"שלשה פנקסות הן וכו'. שם ופי' רבינו פנקסאות הן כל שתי לוחות מזדווגות יהיו לסופר או לזולתו וכו'. ואפיפירין הוא כסא של פרקים כאשר יתפשט יהיו שני לוחות וישב הסופר עליו וכאשר יתקבץ ישוב לוח אחד וכו'. וחלקה הוא לוח פשוט אין לה בית קיבול ולא כלי קיבול והוא מפשוטי כלי עץ:\",1,0],[8,380,28,1,\"כל הכלים וכו'. נפלו משקין טמאים וכו'. פכ\\\"ה וכתב רבינו שנטמאו אחוריהם במשקין משום דאמרינן בפרק קמא דפסחים עלה י\\\"ז (ע\\\"ב) עלה דמתניתין דהני מילי בטומאת משקין שהיא דרבנן אבל בטומאת שרץ מאחר שהיא דאורייתא נטמא תוכו נטמא גבו. וכתב\",1,0],[8,380,28,1,\"רבינו לתרומה כלומר אבל לקדש הא תנן בסוף ההוא פירקא כלי הקדש אין להם אחוריים ותוך ואין להם בית הצביטה.\",2,0],[8,380,28,1,\"ומ\\\"ש ואפילו אחורי הכלי כולו לא נטמאו. הכי משמע במשנה ובתוספתא דכלים פרק ג':\",3,0],[8,380,28,1,\"כתב הראב\\\"ד הרי זה מנגבן והן טהורים א\\\"א תוכן טהור וכו'. ולרבינו י\\\"ל שכיון שלא הוזכר כן במשנה מנין לנו לגזור כן ויותר נראה לומר דמלשון מנגבן והן טהורים דייק לה הראב\\\"ד וגם רבינו סובר כן ולא הוצרך לפרש:\",4,0],[8,380,28,2,\"אחד כלי השק וכו'. בריש פרק כ\\\"ה דכלים:\",1,0],[8,380,28,2,\"כתב הראב״ד לא נטמא תוכן א״א ואף לא אחוריהן וכו'. נראה שטעמו משום דס״ל שהוא הדין שאם נטמא תוכן לא נטמאו אחוריהן וכמ״ש ר״ש בראש הפרק הנזכר דאיכא דגרסי הכי בפירקא קמא דפסחים ואף על פי שר״ש דחה אותה גירסא הראב״ד סבר כוותה וזהו שכתב ואף לא אחוריהן כלומר כשם שאם נטמאו אחוריהם במשקין לא נטמא תוכן כן אם נטמא תוכן לא נטמא אחוריהן אי נמי טעמו לומר דמדכתב רבינו לא נטמא תוכן משמע דאחוריהן מיהא טמא והראב״ד סובר שאף אחוריהם לא טמאו. ומ״ש עיין בבכורות. היינו דאמרינן בפרק על אלו מומין (בכורות דף ל״ח) דמדאורייתא אין משקה מטמא כלי ורבנן הוא דגזור ביה ועבדו ביה היכרא כי היכי דלא נשרוף עליה תרומה:\",2,0],[8,380,28,3,\"פשוטי כלי שטף וכו'. פרק כ\\\"ה דכלים וכרבי יהודה.\",1,0],[8,380,28,3,\"ומ\\\"ש אבל פשוטי כלי שטף הראויים למדרס וכו' עד נטמא הכלי כלו. בפרק אלו מומין עלה ל\\\"ח:\",2,0],[8,380,28,3,\"וכן מדות יין ושמן. פרק כ\\\"ה דמסכת כלים מדות יין ושמן וזומא ליסטרא ומסננת של חרדל ומשמרת יין יש להם אחוריים ותוך דברי רבי מאיר רבי יהודה אומר אין להם אחוריים רבי שמעון אומר יש להם נטמאו מאחוריהם מה שבתוכם טהור וצריך להטביל וטעמא דר' יהודה משום דכל הני כלים יש מאחוריהם חקק בית מושב כעין שעושין לכלי כסף ופעמים שכופהו על פיו ומשתמש בחקק שבאחוריו:\",3,0],[8,380,28,3,\"כתב הראב\\\"ד אם נפלו משקין על מקצתן נטמאו כולן כמו הבגדים א\\\"א הא דלא כהלכתא וכו'. וי\\\"ל שלענין טומאת הכלי עצמו ר\\\"ש סובר כרבי יהודה שהרי אמר כשנטמאו מאחוריהן צריך להטביל את כל הכלי וכאן לא איירי רבינו אלא לענין טומאת הכלי עצמו לא לענין טומאת מה שבתוכו:\",4,0],[8,380,28,4,\"המרדע והמלמד וכו'. שם כרבי יהודה לגבי רבי מאיר פירוש מרדע הוא מקל ארוך בראשו האחד ברזל רחב וחדוד לחתוך ושמו חרחור ובראשו השני ברזל כעין מרצע ושמו דרבן שבו מלמד פרה לתלמיה:\",1,0],[8,380,28,5,\"כיס בתוך כיס וכו'. פרק כ\\\"ו.\",1,0],[8,380,28,5,\"ומה שכתב במה דברים אמורים כשהיו שפתותיהן שוין וכו' עד לא נטמא חבירו. תוספתא פרק ד' דבבא בתרא. ומה שחילק בין טומאת משקים לטומאת שרץ שם במה דברים אמורים במשקה אבל בשרץ שניהם שוים ומשמע לי דה\\\"פ דדוקא בטומאת משקין שהיא דרבנן מפלגינן בין נטמא פנימי לנטמא חיצון אבל בטומאת שרץ שהיא דאורייתא אפילו נטמא חיצון נטמא פנימי וכבר כתבתי כן בראש הפרק:\",2,0],[8,380,28,6,\"החוקק רובע וכו'. משנה פרק כ\\\"ה.\",1,0],[8,380,28,6,\"ומה שכתב נטמאו אחורי הרובע וכו'. שם כחכמים:\",2,0],[8,380,28,7,\"קומקומוס שהיו וכו' והיה מרתיח וכו'. שם.\",1,0],[8,380,28,7,\"ומה שכתב לתרומה, כלומר אבל לא לקדש כדתנן התם בסמוך כלי הקדש אין להם אחוריים ותוך:\",2,0],[8,380,28,7,\"סליקו להו הלכות כלים:\",3,0],[8,381,1,1,\"כל הטמאים בין אדם וכו' אלא בטבילה במים הנקוין בקרקע:\",1,0],[8,381,1,2,\"כל מקום שנאמר בתורה וכו' וזה שנאמר בזב וידיו לא שטף במים וכו'. בת\\\"כ:\",1,0],[8,381,1,3,\"כל הכלים שנטמאו וכו' חוץ מכלי חרס. פרק ר\\\"ע עלה פ\\\"ד.\",1,0],[8,381,1,3,\"ומ\\\"ש וכלי זכוכית. פ\\\"ק דשבת עלה ט\\\"ו.\",2,0],[8,381,1,3,\"ומ\\\"ש אפילו חיברו בקרקע וכו'. תוספתא דכלים פרק ששי:\",3,0],[8,381,1,4,\"המפץ אינו בכלל הכלים המקבלים וכו'. פרק ר\\\"ע עלה פ\\\"ד ובעירובין ק\\\"ד ופירש\\\"י דטעמא דלית ליה טהרה במקוה משום דכי כתיבא בפרשת שרצים ובפרשת מדין כתיבא והנך כלים דכתיבי התם ילפינן להו טבילה אבל פשוטי כלי עץ שלא נכתבו שם לענין טומאה לא ילפינן להו טבילה ולית להו טהרה במקוה דהא לא כתיבא בהו כי היכי דאוכל ומשקה אין להם טהרה במקוה לפי שלא למדנו להם טבילה בתורה עכ\\\"ל וכן כתב רבינו לקמן בסמוך:\",1,0],[8,381,1,4,\"כתב הראב\\\"ד שאין מתטהר במקוה אלא הכלים האמורים בתורה א\\\"א הרבה דברים ועדיין לא השלים וכו' עד לא בא לכלל זה זהו טעם העיקר. ורבינו בדבריו נכלל הכל.\",2,0],[8,381,1,4,\"ומ\\\"ש ואין למפץ טהרה אלא קריעתו עד שישאר פחות מששה על ששה טפחים. בספ\\\"כ דכלים מחצלת שנחלקה ונשתיירו בה שלשה מעדנים של ששה טפחים טמאה משמע הא פחות מששה טפחים טהורה:\",3,0],[8,381,1,5,\"הזב אין לו טהרה אלא במעיין וכו'. בסוף פ\\\"ק דמקואות:\",1,0],[8,381,1,6,\"כל חייבי טבילות וכו'. בפ\\\"ח דפסחים עלה צ' ע\\\"ב ויומא (דף ו').\",1,0],[8,381,1,6,\"ומ\\\"ש ובעל קרי טובל והולך וכו'. יומא (דף פ\\\"ח) ושבת (קכ\\\"א):\",2,0],[8,381,1,6,\"וכתב הראב\\\"ד וכן לטמא שרץ ולכל הטמאים וכו'. ואני אומר שגם רבינו סובר כן ולא נקט בעל קרי אלא משום דכתיב ביה קרא מפורש:\",3,0],[8,381,1,7,\"כל הטובל וכו' עד והרי הוא כגופו דין תורה. בריש עירובין (דף ד' ע\\\"ב) ובריש סוכה (דף ו'):\",1,0],[8,381,1,7,\"וכל הטמאים שטבלו בבגדיהם וכו'. בפ\\\"ב דיו\\\"ט עלה י\\\"ח וכו' נדה מערמת וטובלת בבגדיה:\",2,0],[8,381,1,8,\"כל הטובל צריך להתכוין לטבילה וכו'. פרק ב' דחולין עלה ל״א פלוגתא דרב ור״י ופסק רבינו כרב משום דמשמע בגמרא דר״נ בר יצחק סבר כוותיה ועוד דבפרק אין דורשין (חגיגה דף י״ט) סוגיין כרב דאמר חולין לא בעו כוונה ולא מדכרינן התם דר״י כלל ועוד דמשמע ליה לרבינו שמ״ש בפ״ב דחולין ומנא תימרא דחולין לא בעו כוונה דתנן גל שנתלש לישנא דגמרא הוא ולא סיומא דמילתיה דר״נ דאלמא מסקנא דגמרא כרב וכן פסק ר״ח וסמ״ג.\",1,0],[8,381,1,8,\"ומ\\\"ש או ירדה להקר. פשוט הוא דהוי כאילו אמר ואצ\\\"ל אם ירדה להקר.\",2,0],[8,381,1,8,\"ומ\\\"ש אבל לתרומה וקדשים וכו'. משנה בפרק ב' דחגיגה (דף י\\\"ח ע\\\"ב):\",3,0],[8,381,1,9,\"הכופת ידיו ורגליו וכו'. תוספתא דמקואות רפ\\\"ח. ונראה דהיינו לומר דהיכא דלא טבל כדרך גדילתו בודקין אותו ואם נכנסו המים בכל המקומות שהיה נכנס אילו טבל כדרך גדילתו עלתה לו טבילה ואם לאו לא עלתה לו טבילה:\",1,0],[8,381,1,9,\"הקופץ לתוך המקוה וכו'. שם ספ\\\"ה. וכתב הריב\\\"ש בתשובה שרבינו מפרש מפני שהקופץ למקוה אף אם מתכוין לטבול הרואים סבורים שאינו מתכוין אלא להקר וכן הטובל פעמיים כיון שטבל כראוי למה חוזר וטובל יחשבו שאינו טובל אלא להקר ואם יגע בתרומה וקדשים יהיו סבורים דלא בעי כוונה עכ\\\"ל.\",2,0],[8,381,1,9,\"והאומר לחבירו כבוש ידך עלי במקוה נראה שהוא מטעם זה מפני שנראה כמשחק ואינו מתכוון לטבול ומיהו במסכת דרך ארץ פרק תשיעי משמע דמיירי בשאין במקוה אלא ארבעים סאה מצומצמים דכשזה מכניס ידו במקוה לכבוש עליו חיישינן שמא יוציאנה קודם שיטבול זה ונמצא טובל במקוה חסר שהרי חסרו המים שטפחו בידו של זה שהכניסה לכבוש עליו ועל דרך זה יש לפרש ההיא דהקופץ לתוך המים וההיא דטובל פעמים במקוה דמיירי בשלא היו במקוה אלא ארבעים סאה מצומצמים וחיישינן שמא כשקפץ במקוה ניתזו מהם וחסרו וכן בטובל במקוה פעמיים והריב\\\"ש כתב שנראה לו שלא פירש כן מפני שראה שכתב דברים אלו פה אצל טובל בלא כוונה וענין טבילה בארבעים סאה מצומצמות כתב בסוף פרק ח':\",3,0],[8,381,1,10,\"בית הסתרים וכו'. משנה בפ\\\"ט דמקואות ות\\\"כ ונדה (דף מ\\\"ב ע\\\"ב):\",1,0],[8,381,1,10,\"ומ\\\"ש ואעפ\\\"כ צריכין להיות ראויים וכו'. בפ\\\"ק דקידושין (דף כ\\\"ה).\",2,0],[8,381,1,10,\"ומ\\\"ש לפיכך אמרו חכמים וכו'. בפרק תינוקת:\",3,0],[8,381,1,10,\"האשה טובלת וכו'. בפרק תינוקת (נדה דף ס״ז) אמר ר״ל האשה לא תטבול אלא כדרך גדילתה כדתנן גבי ראיית נגעים אשה נראית כאורגת וכמניקה את בנה:\",4,0],[8,381,1,11,\"אשה אינה טובלת בנמל וכו'. בפרק תינוקת והטעם שנתן רבינו כתב הרי\\\"ף בפרק שני דשבועות והתוספות והרא\\\"ש כתבוהו בפרק תינוקת בשם ר\\\"ח ורבינו תם.\",1,0],[8,381,1,11,\"ומ\\\"ש ואם הקיף לה מפץ וכו'. כך פירשו התוספות והרא\\\"ש בפרק תינוקת דההיא דאבוה דשמואל עביד מפצי לבנתיה ביומי תשרי לפר\\\"ח ור\\\"ת.\",2,0],[8,381,1,11,\"ומ״ש ולא תטבול על גבי כלי חרס או סל וכו'. ג״ז בפרק תינוקת (נדה דף ס״ו ע״ב) אמר רבא אשה לא תעמוד ע״ג כלי חרס ותטבול סבר רב כהנא למימר טעמא מאי משום גזירת מרחצאות פירוש שדרך מרחצאות שלהם לישב ע״ג איצטבאות דדמי לכלי חרס ואתו למימר טבילה עולה בהן הא ע״ג סילתא ש״ד כלומר ע״ג בקעת עבה א״ל רב חנן מנהרדעא התם טעמא מאי משום דבעיתא סילתא נמי בעיתא ופירש״י בעיתא שלא תפול ולא טבלה שפיר:\",3,0],[8,381,1,11,\"וכתב הראב\\\"ד דבדיעבד אם טבלה עלתה לה טבילה ומיהו כתב דדוקא בכלי חרס דכיון שאינו מקבל טומאה מגביו ולא חזי למדרס ליכא משום גזירת מרחצאות וסילתא נמי לאו בר קבולי טומאה אבל בכלי עץ אפילו דיעבד לא עלתה לה טבילה ודייק לה מדתנן בפרק ה' דמקואות מעיין שהעבירו ע\\\"ג כלים או ע\\\"ג ספסל רבי יהודה אומר הרי הוא כמו שהיה רבי יוסי אומר הרי הוא כמקוה ובלבד שלא יטבול ע\\\"ג ספסל אלמא כל שהוא ראוי למדרס כספסל וכן שאר כלים שמקבלים טומאה לא מהניא בהו טבילה משום גזירת מרחצאות דליכא למימר דטעמא משום דבעיתא דהא לאו באדם עסקינן אלא בכלים ולפי זה הא דעבד אבוה דשמואל מפצי לבנתיה למחיצות עבדינהו משום צניעות שהרי מקבלות טומאה וכדתנן פ\\\"ק דסוכה ואיכא גזירת מרחצאות עכ\\\"ל. וכן פסק הרשב\\\"א, והרא\\\"ש סתם וכתב אמר רבא אשה לא תעמוד ע\\\"ג כלי או ע\\\"ג בקעת של עץ ותטבול משום דבעיתא ולא טבלה שפיר ומדברי רבינו משמע שדעתו לומר שאם טבלה לא עלתה לה טבילה מדקאמר ולא תעלה לה טבילה ולא קאמר שמא לא תטבול יפה ומיהו איכא למידחי משום דא\\\"כ הל\\\"ל הכי אם טבלה ע\\\"ג כלי חרס או סל לא עלתה לה טבילה מפני שמפחדת ואינה טובלת כהוגן ומדלא קאמר הכי משמע דלכתחילה הוא דאסור אבל לא בדיעבד והדבר מוכרע. ומ\\\"מ רבינו והרא\\\"ש לא זכרו את גזירת מרחצאות שהזכירו הראב\\\"ד והרשב\\\"א נראה שהם סוברים דכי א\\\"ל משום דבעיתא בטיל ליה טעמא דגזירת מרחצאות דהוה ס\\\"ד דרב כהנא ואגמריה דלא גזרו חכמים בכך מעולם וההיא מתני' דפ\\\"ה דמקואות דמייתי הראב\\\"ד מינה כתבה הרא\\\"ש בפרק תינוקת ופירש ע\\\"ג אחורי כלים וטעמא דרבי יוסי משום דגזר אטו תוך כלי וי\\\"מ דטעמא דאסור כדאמרינן אשה לא תעמוד ע\\\"ג כלי חרס ותטבול ולא נהירא דהתם הוי טעמא משום דבעיתא ואפי' אסילתא נמי אבל הכא לא יטביל קתני דמשמע אפילו דלא שייכא בהו טעמא דביעתותא עכ\\\"ל. ורבינו כתבה לדרבא כאן ולא חילק בין כלי חרס לכלי עץ דמשמע ליה דסילתא דאמרינן בגמרא הוא סל וסל כלי עץ הוא והוא ז\\\"ל משוה אותו לכלי חרס ובפ\\\"ט כתב מעיין שמימיו נמשכים ע\\\"ג כלים שאין להם בית קיבול כגון שלחן וספסל וכיוצא בהן ה\\\"ז כמקוה ובלבד שלא יטביל ע\\\"ג הכלים עכ\\\"ל:\",4,0],[8,381,1,11,\"ואיכא למידק עליה מאי אתא רבא לאשמועינן דלא תעמד ע\\\"ג כלי וסילתא ותטבול הא מתניתין היא ועוד דיהיב טעמא משום דבעיתא דמשמע שאם הם קבועים בענין דלא בעיתא מותרת לטבול והא מתניתין בטבילת כלים מיירי דלא שייך בהו ביעתותא ועוד דאפילו הוה מיירי באדם הרי אסרה ע\\\"ג ספסל דמאן דקאים על גב ספסל מסתמא לא מבעית וי\\\"ל דמתניתין בשכל מי המעיין עוברים על הספסל שאילו היה כלי שיש לו בית קיבול היו נפסלים מלטבול אפילו במים שנמשכים מן הכלי וכדתנן מעיין שהעבירו ע\\\"ג השוקת פסול והשתא שכלי זה אין לו בית קיבול אינו נפסל ומ\\\"מ גזור שלא יטבלו על הכלי עצמו אע\\\"פ שאין לו בית קיבול גזירה אטו כלי שיש לו בית קיבול ובמים הנמשכים ממנו נמי גזרו קצת ואמרו דלא יטהרו אלא באשבורן כמקוה אבל אם לא היו כל מי המעיין עוברין על הספסל ליכא למיגזר כלל דהא אפילו כלי שיש לו בית קיבול כיון שקצת מהמים אינם עוברים עליו לא פסק דין מעיין מהמים הנמשכים וכדתנן גבי מעין שהעבירו על השוקת העבירו ע\\\"ג שפה כל שהוא כשר הילכך כשהוא כלי שאין לו בית קיבול כספסל וכיוצא בו אי נמי כלי שיש לו בית קבול אלא שאין המים עוברים מתוכה כי אם אחוריו כגון שהוא כפוי על פיו מותר לטבול על גביו ואתא רבא למימר דהיכא דכלי חרס מונח בקרקעית המעיין ואין כל המים עוברים עליו דודאי מדינא מותרת לעמוד על גביו ולטבול אפילו הכי לא תעשה כן משום דבעיתא וכדמסיק בגמ' דטעמיה משום ביעתותא ומש\\\"ה ע\\\"ג סילתא נמי לא תעמוד ותטבול משום ביעתותא ועי\\\"ל דהא דתנן שלא יטבול ע\\\"ג ספסל דוקא הוא לומר דע\\\"ג כלים שאין להם בית קיבול אין מטבילין גזירה אטו כלים שיש להם בית קיבול שיבאו להטביל בתוכם דלא יחלקו בין כלים לכלים אבל ע\\\"ג אחורי כלים שיש להם בית קיבול לא גזרינן דכיון שהכלים שיש להם בית קיבול דרך להעמידן ופיהם למעלה ואלו כפויים על פיהם מידע ידיע לרואים ששינו להניחן כך מפני שאם היו מונחים כדרכן היה אסור לטבול בהן ואתא רבא למימר דאע\\\"ג דלא שייך למיגזר בהו אטו כשהם מונחים כדרכם מ\\\"מ לא תעמוד עליהם משום דבעיתא ומתניתין דייקא כשיטה זו דקתני רישא ע\\\"ג כלים או ע\\\"ג ספסל ובסיפא קתני ובלבד שלא יטביל ע\\\"ג ספסל ושבקינהו לכלים לומר דע\\\"ג כלים שיש להם בית קיבול מותר להטביל דלא גזרינן בגבן אטו תוכן מטעמא דפרישית ומיהו היינו דוקא לענין להטביל על גבן אבל לענין מים הנמשכים מהם משמע דגזרו בהם שלא יטהרו אלא באשבורן כמקוה כשם שגזרו בכלים שאין בהם בית קיבול וטעמא איכא במילתא דבשלמא להטביל על גבן שרי משום דבשעה שמטביל רואה שהוא מונח בשינוי ולא אתי לאחלופי במונח כדרכו אבל כשמטביל במים הנמשכין ממנו אין ניכר שהכל מונח שלא כדרכו שהרי אין הכלי לפניו במקום שמטביל בו הלכך גזרו ביה שמא יאמרו כלי היה מונח למעלה ממקום שהטביל בו ולא יבחינו אם היה מונח בשינוי אם לא א\\\"נ י\\\"ל דע\\\"ג ספסל דסיפא אכולה מילתא דרבי יוסי קאי לומר דהא דקאמר רבי יוסי הרי הוא כמקוה וכן מאי דקאמר שלא יטביל על גבן היינו דוקא ע\\\"ג ספסל וכיוצא בו כלים שאין להם בית קיבול אבל ע\\\"ג אחורי כלים שיש להם בית קיבול הרי הוא כמות שהיה וגם מטבילין על גבן ומטעמא דפרישית ורישא נקט ע\\\"ג כלים לומר דר\\\"י משוה ע\\\"ג כלים לעל גבי ספסל אבל לרבי יוסי לא איצטריך למנקט ע\\\"ג כלים לגבי ספסל דהא מוחלקים הם לגמרי ולשיטה זו ניחא שלא כתב רבינו דין העבירו ע\\\"ג כלים שיש להם בית קיבול לענין דהרי הוא כמקוה כמ\\\"ש בע\\\"ג ספסל:\",5,0],[8,381,1,12,\"אחד האדם או הכלים לא יהיה דבר חוצץ וכו'. בפ\\\"ט דמקואות.\",1,0],[8,381,1,12,\"ומ\\\"ש דבר תורה וכו'. בריש עירובין (דף ד' ע\\\"ב):\",2,0],[8,381,2,1,\"אלו חוצצין באדם וכו'. פרק ט' דמקואות.\",1,0],[8,381,2,1,\"ומ\\\"ש לפלוף שחוץ לעין. יתבאר בסוף פרק זה.\",2,0],[8,381,2,1,\"ומ\\\"ש והדם יבש שע\\\"ג המכה. תוספתא דמקואות פ\\\"ו.\",3,0],[8,381,2,1,\"ומ\\\"ש וטיט של דרכים הנמצא שם תמיד אפילו בימות החמה. כך מפורש בתוספתא פ\\\"ז פירוש מה ששנינו במשנה פ\\\"ט שיתדות דרכים חוצצין:\",4,0],[8,381,2,2,\"ומ״ש הדבש והדיו והחלב והדם. פרק כל כתבי (דף ק״ב ע״ב) ופ״ג דזבחים (דף ל״ה) ופ״ג דמנחות (דף כ״א) וס״פ תמיד נשחט (פסחים דף ס״ה:):\",1,0],[8,381,2,2,\"ומ\\\"ש ושרף התות והתאנה וכו'. בתוספתא דמקואות ומסיים בה טעם לשאר השרפין מפני שהם לכלוך הפירות פירוש ודרך בני אדם להקפיד עליהם:\",2,0],[8,381,2,2,\"ומ\\\"ש ודם שנסרך בבשר וכו'. כן כתב סמ\\\"ג וכתב שהטעם שאפילו לח חוצץ מפני שהוא דרך בני אדם להקפיד עליהם אמנם בפרק כל הפסולים אומר שבח הוא לבני אהרן שיהלכו עד ארכובותיהם בדם והא הוי חציצה אלמא בבשר לח אינו חוצץ עכ\\\"ל. וי\\\"ל דהכא שאני דנסרך בבשר וכן מפורש בגמרא פרק ג' דמנחות אמר רב דימי בין לח בין יבש חוצץ מיתיבי הדם וכו' לחים אינה חוצצים לא קשיא הא דסריך הא דלא סריך ומפרש רבינו נסרך לבשר:\",3,0],[8,381,2,2,\"האבר והבשר המדולדלים חוצצין. תוספתא שם ונראה שהטעם מפני שמעת שנדלדלו הם חשובים כקטועים והוי כאילו נתגלה מקום חיבורם ונראה לבוא שם מים ועכשיו כשזה בא לטבול נמצאו אבר ובשר זה חופים על מקום חיבורן ומונעין אותו מלבא במים והו\\\"ל כבית הסתרים שאם יש דבר חוצץ מעכב בטבילה. ועי\\\"ל דהא דקאמר דחוצצין היינו לומר שאם נמצא בהם שום דבר חוצץ לא עלתה לו טבילה שאף על פי שהם מדולדלים כגוף הם חשובים:\",4,0],[8,381,2,3,\"בית הסתרים באשה חוצץ וכו'. משנה פרק ט' דמקואות.\",1,0],[8,381,2,3,\"ומה שכתב במה דברים אמורים בנשואה וכו'. תוספתא:\",2,0],[8,381,2,4,\"האגד שע\\\"ג המכה וכו'. עד אינן חוצצין. תוספתא.\",1,0],[8,381,2,4,\"ומה שכתב והטבעות וכו'. שבת עלה נ\\\"ב ע\\\"ב:\",2,0],[8,381,2,5,\"חוטי צמר וכו'. משנה רפ\\\"ט דמקואות ושבת עלה נ\\\"ז.\",1,0],[8,381,2,5,\"ומ\\\"ש אבל חוטי שיער. שם ואע\\\"ג דבשם רבי יהודה היא שנויה אמרינן בר\\\"פ במה אשה דמודים לו חכמים:\",2,0],[8,381,2,6,\"ומ\\\"ש חוטין שבצואר וכו' אבל חבקים שבצואר וכו'. ריש פרק במה אשה:\",1,0],[8,381,2,7,\"שיער שעל הלב וכו' וכן קלקלי הזקן וכו'. פ\\\"ט דמקואות שם:\",1,0],[8,381,2,8,\"חץ התחוב באדם וכו' וכן מי שבלע טבעת טמאה. בסוף מקואות.\",1,0],[8,381,2,8,\"ומ\\\"ש שכבר ביארנו. בה' טומאת מת פכ\\\"ד:\",2,0],[8,381,2,8,\"נכנסו צרורות וכו'. בתוספתא דמקואות פ\\\"ח נכנסו צרורות וקסמים בסדקי רגליו מלמטה ר\\\"ע אומר אינו חוצץ ומשמע לרבינו דכיון דבשמא דיחידאה קתני לה פליגי עליה רבנן ועי\\\"ל דטעמא דר\\\"ע משום דס\\\"ל דבית הסתרים לא בעינן שיהיו ראויים לביאת מים ובפ\\\"ק דקידושין (דף כ\\\"ה) ובפרק תינוקת אמרינן דבעינן שיהיו ראויים לביאת מים:\",3,0],[8,381,2,9,\"אספלנית מלוגמא וכו'. דברים אלו במחלוקת הם שנויים בתוספתא בפרק הנזכר וכבר נתבאר דהלכה כמ\\\"ד דבעינן שיהיו ראויים לביאת מים:\",1,0],[8,381,2,9,\"היתה בו שערה אחת וכו'. תוספתא בפרק הנזכר:\",2,0],[8,381,2,10,\"לא יטבול אדם וכו'. משנה פ\\\"ט דמקואות.\",1,0],[8,381,2,10,\"ומ\\\"ש ואם טבל אינו חוצץ. תוספתא פרק ח' דמקואות:\",2,0],[8,381,2,11,\"האוחז באדם ובכלים וכו'. משנה פ\\\"ח דמקואות האוחז באדם ובכלים ומטבילם טמאים ואם הדיח ידיו במים טהורים ר\\\"ש אומר ירפה כדי שיבאו בהם המים ומשמע לרבינו דת\\\"ק סבר דלא מהני רפיון ידים:\",1,0],[8,381,2,12,\"המפשלת בנה וכו'. בפרק תינוקת (דף פ\\\"ז) וכגירסת ר\\\"ח שכתבו התוספות:\",1,0],[8,381,2,13,\"נדה שנתנה שערה בפיה וכו'. בפרק ח' דמקואות.\",1,0],[8,381,2,13,\"ומה שכתב או שנמצא עצם בין שיניה וכו'. בפרק קמא דקידושין (דף כ״ה) ובפרק תינוקת (נדה ס״ו:)\",2,0],[8,381,2,13,\"נתנה מעות בפיה וכו'. שם טהורה מטומאתה אבל טמאה היא ע\\\"ג רוקה פירוש טהורה מטומאת נדה ומותרת לבעלה פירוש וטמאה על גבי רוקה שנתלש על המעות קודם טבילה וטמאה מתורת מגע דרוקה מטמא במגע ובמשא:\",3,0],[8,381,2,14,\"ואלו שאין חוצצין באדם וכו'. משנה פ\\\"ט דמקואות. ודע דאיתא בתוספתא רבי יונתן בן יוסף אומר ציפורן שפירשה רובה הרי זו אינה חוצצת ורבינו סתם דבריו כלשון המשנה ולא חילק ואפשר שהוא ז\\\"ל מפרש דלרבותא נקט פירשה רובה וכ\\\"ש מיעוטה א\\\"נ דאה\\\"נ דמפרש דבדוקא נקט פירשה רובה אלא דכיון דמשמע דיחידאה קאמר לה משמע דרבים פליגי עליה.\",1,0],[8,381,2,14,\"ומ\\\"ש לפלוף שבעין. יתבאר בסוף פרק זה:\",2,0],[8,381,2,15,\"שתי שערות או יתר וכו'. בפרק תינוקת (נדה דף ס״ז) אמר רבה בר בר חנא נימא אחת קשורה חוצצת ג' אינן חוצצות שתים איני יודע ור״י אמר אין לנו אלא אחת ופסק כר״י.\",1,0],[8,381,2,15,\"ומ\\\"ש והוא שיהיה מקפיד עליו וכו'. הוא ע\\\"פ מה שנתבאר בסוף פ\\\"א:\",2,0],[8,381,2,15,\"כתב הראב\\\"ד ויראה לי ששערו של אדם כגופו (של אדם) הוא חשוב וכו'. א\\\"א כדברי הגאונים הוא העיקר עכ\\\"ל ואין בזה הכרע:\",3,0],[8,381,2,16,\"תקנת עזרא היא וכו'. בסוף פרק מרובה (בבא קמא דף פ\\\"ב).\",1,0],[8,381,2,16,\"ומה שכתב ואם אפשר לה לחוף בלילה וכו'. בפרק תינוקת (נדה דף ס״ח) שלח רבין באגרתיה אשה לא תחוף בערב שבת ותטבול במוצאי שבת ותמה על עצמך היאך אשה חופפת ביום וטובלת בלילה והא בעינן תיכף לחפיפה טבילה וליכא וכו' והלכתא אשה חופפת ביום וטובלת בלילה והלכתא אשה לא תחוף אלא בלילה אלא קשיא הלכתא אהלכתא ל״ק הא דאפשר הא דלא אפשר ונראה מדברי רבינו שהוא סובר דלהאי מסקנא ליתא לפיסקא דפסק התם מרימר כרב חסדא וכדמתרץ רב יימר אלא לעולם לא הפסיק בין יום דחפיפה ליום דטבילה יותר מיום אחד ומפרש רבינו הא דאפשר הא דלא אפשר דהיינו לומר דהיכא דא״א לחוף בליל טבילה מפני הדחק כגון שא״א למצוא מים חמין בליל טבילה מפני שיוצאים בשיירא או מפרשים בים וכיוצא בזה או מפני החולי כלומר שיש לה חולי שהמים חמין מזיקין לה בעת התעוררות החולי ויודעים שבליל טבילה היא העונה דכיון דא״א לעשות בע״א יכולה להקדים לחוף קודם ליל הטבילה ואפילו אם יכריח הדוחק או החולי להקדים לחוף מיום ראשון והטבילה אינה עד ליל שלישי יש לה רשות אבל להרחיק יותר לא דהא אמאי דשלח רבין באגרתיה אשה לא תחוף בע״ש ותטבול במו״ש אמרינן דהיינו בדאפשר אבל בדלא אפשר שפיר דמי ודוקא בשיעור הרחקה זו אבל להרחיק טפי לא דלא לחנם נקט רבין האי שיעורא ונ״ל שלדעת רבינו ע״ש ומו״ש דנקט לדוגמא נקטינהו ולאו דוקא אלא ה״ה לחוף ביום ראשון ולטבול בליל שלישי וכן כיוצא בשאר הימים דהא לפי מ״ש מפני דוחק או חולי אין טעם לתלות ההיתר הזה בע״ש ומו״ש יותר מבשאר הימים:\",2,0],[8,381,2,17,\"טבלה ועלתה וכו'. בפרק תינוקת (נדה דף ס״ו ע״ב) אמר רבא טבלה ועלתה ונמצא עליה דבר חוצץ אם סמוך לחפיפה טבלה אינה צריכה לחוף ולטבול ואם לאו צריכה לחוף ולטבול איכא דאמרי באותו יום שחפפה טבלה אינה צריכה לחוף ולטבול ואם לאו צריכה לחוף ולטבול ופסק כלישנא בתרא:\",1,0],[8,381,2,17,\"וכתב הראב\\\"ד אם באותו היום שחפפה טבלה א\\\"א הא קי\\\"ל כלישנא בתרא וכו'. טעמו מפני שהוא גורס כהרי\\\"ף והר\\\"ן דבלישנא בתרא גרסינן אם סמוך לחפיפה טבלה ולפי גירסתם הלכה כלישנא בתרא דתלי מילתא באם סמוך לחפיפה טבלה שהוא זמן מועט מאם ביום שחפפה טבלה דמשמע אפילו חפפה בבקר וטבלה בערב נמי ולפיכך משיג על רבינו למה פסק כלישנא קמא ונראה עוד שהראב\\\"ד גורס כלישנא קמא אינה צריכה לחוף ולטבול ובלישנא בתרא גורס אינה צריכה לא לחוף ולא לטבול ומשיג על רבינו למה פסק כלישנא קמא דמשמע שאינו פוטרה אלא מחפיפה ולא מטבילה ה\\\"ל למפסק כלישנא בתרא דפטר לה אף מטבילה והשיג עליו עוד ממה שלא כתב דין זה אצל דין מי שטבל ועלה ונמצא עליו דבר חוצץ וכתבו אצל דין תיכף לחפיפה טבילה דמשמע דמש\\\"ה אמרינן כשנמצא עליה דבר חוצץ דאי לא טבלה סמוך לחפיפה צריכה לחוף ולטבול אבל אם לא היה צריך לסמוך טבילה לחפיפה לא הוה אמרינן דצריכה לחוף ולטבול וכתב שזה אינו דאפילו אי לא הוה בעינן לכתחילה למיסמך טבילה לחפיפה היכא דאשתכח ריעותא הוה חיישינן כל שלא סמכה טבילה לחפיפה כך נראה לי ביאור דברי הרב רבי אברהם בן דוד וליישב דעת רבינו י\\\"ל דאיהו ז\\\"ל גריס כגירסא דידן דלישנא בתרא הוא אם ביום שחפפה טבלה וגם גריס ביה אם סמוך לחפיפה טבלה אינה צריכה לחוף ולטבול ומפרש דהיינו לומר דאינה צריכה תרתי חפיפות וטבילה דבטבילה לחודה סגי אבל טבילה מיהא בעיא בכל גוונא ובזה נסתלקו מעליו שתי השגות הראשונות ובהכי ניחא נמי ההשגה השלישית דכיון דחפיפה אינה אלא תקנת עזרא אי לא הוה מתקן לסמוך טבילה לחפיפה אפילו לא טבלה ביום החפיפה ונמצא עליה אחר טבילה דבר החוצץ לא היתה צריכה לחזור ולחוף אבל מאחר שהתקין שביום טבילה חפיפה כשנמצא עליה דבר חוצץ אם לא טבלה ביום חפיפה הצריכוה לחזור ולחוף והר\\\"ן כתב בפרק ב' דשבועות (דף ש\\\"מ) וז\\\"ל הרמב\\\"ם כתב אם ביום שחפפה טבלה וכו' משום דלמקצת נוסחאות לישנא בתרא הוא ומיהו לאו למימרא דלההוא לישנא כל שחפפה באותו יום אע\\\"פ שלא היה סמוך לטבילה דלא חיישינן ואע\\\"פ שנמצא עליה דבר החוצץ דהיכי אפשר דאע\\\"ג דאתיא לידי ריעותא לא נחוש ואע\\\"פ שהרחיקה טבילתה מחפיפתה אלא להכי נקט יום לאשמועינן טעמא דנמצא עליה דבר חוצץ הא לאו הכי אינה צריכה לחוף ולטבול אע\\\"פ שלא חפפה ביום שטבלה וזה לא נתבאר יפה בדברי הרמב\\\"ם וכבר השיגו הראב\\\"ד עכ\\\"ל. נראה שהר\\\"ן מפרש שהראב\\\"ד סובר בדברי רבינו שדעתו לומר שכל שחפפה באותו יום אע\\\"פ שלא היה סמוך לטבילה לא חיישינן אף ע\\\"פ שנמצא עליה דבר חוצץ והשיגו משום דהיכי אפשר דאע\\\"ג דאתייליד ריעותא לא נחוש אף ע\\\"פ שהרחיקה טבילתה מחפיפתה דלא אשמעינן האי לישנא אלא דהיכא דלא נמצא עליה דבר החוצץ אינה צריכה לחוף ולטבול אע\\\"פ שלא חפפה ביום שטבלה וז\\\"ש הראב\\\"ד דאפילו לא בעינן סמוך לכתחילה השתא דאשתכח ריעותא חיישינן וכו' ואיני יורד לסוף דעתו של הר\\\"ן בזה שכתב וזה לא נתבאר יפה בדברי הרמב\\\"ם שמבואר הוא מאד בדבריו דבנמצא עליה דבר החוצץ קאמר אם ביום שחפפה טבלה אינה צריכה לחוף פעם שניה שהרי תחילת לשונו הוא טבלה ועלתה ונמצא עליה דבר החוצץ ודוחק לומר שהיתה להם נוסחא אחרת בדברי רבינו ומ\\\"ש בביאור דברי רבינו ובביאור דברי הראב\\\"ד הוא הנכון:\",2,0],[8,381,2,18,\"לא תחוף אשה וכו'. בפרק תינוקת (נדה דף ס״ו ע״ב) וברפ״ב דמסכת כלים כתב רבינו בפירוש המשנה דנתר שהוא שקורין בלשון לעז גריד״א וכן כתב הריב״ש שהוא מוחה ביד הנשים שלא יחופו ראשן בגריד״א ביום הטבילה וכתב הטור דהוא הדין לשאר דברים המסבכים את השיער וכתב מהרי״ק בדיעבד אם עיינה וראתה יפה שערה שאינו נקשר דלא מסובך זה בזה ולא נקטף עלתה לה חפיפה:\",1,0],[8,381,2,19,\"נדה שנתנה תבשיל לבנה וכו'. בפרק תינוקת (נדה דף ס״ז):\",1,0],[8,381,2,20,\"שרטה בבשרה וכו'. בפרק תינוקת אמר רמי בר אבא הני ריבדי דכוסילתא עד תלתא יומי לא חייצי מכאן ואילך חייצי:\",1,0],[8,381,2,20,\"וכתב הראב\\\"ד מפני שהדם נקפה כגלד שעל המכה א\\\"א זה שיבוש שהרי שנינו גלד שעל המכה אינו חוצץ וכו'. ואני אומר שמ\\\"ש על דברי רבינו שהוא שיבוש הוא לפי הנוסחא שנזדמנה לו בדברי רבינו שהיה כתוב בה כגלד שעל המכה אבל לנוסחא שהיא כגלד שעל גבי מכה וכך היא בספרים שלנו אין כאן שיבוש דלשון שעל גבי היינו ע\\\"ג המכה מבחוץ ונ\\\"א מצאתי שכתוב בה שחוץ למכה והיא הנכונה:\",2,0],[8,381,2,20,\"ומ\\\"ש הלא דבר הנראה לעינים הוא וכו'. זה פשוט שהטעם שלא רצה לתלות אלא בשלשה ימים הוא ממאי דאיתמר בריבדא דכוסילתא:\",3,0],[8,381,2,20,\"ומ\\\"ש דמאן לימא לן שהשריטות דומות לריבדא אפשר לומר שרבינו אינו מפרש ריבדא וינטוש\\\"א כדמשמע שמפרש הראב\\\"ד אלא מפרש דריבדא ר\\\"ל שריטה ואפילו את\\\"ל דריבדא היא וינטוש\\\"א לא משמע ליה לפלוגי בין שריטות הללו לשריטות אחרות דהא חזינן שאין דם שופע משריטות שנעשו ע\\\"י וינטוש\\\"א שלשה ימים ולא אפילו חצי יום הלכך אין לחלק בין שריטות לשריטות וגמרא דנקט ריבדא לאו דוקא אלא אורחא דמילתא נקט וא\\\"ת שהראב\\\"ד מפרש דריבדא היינו שאנגראדור\\\"ה נאמר דרבינו אינו מפרש כן אלא שהיא שריטה:\",4,0],[8,381,2,20,\"וכן לפלוף שבעין. בפ״ט דמקואות תנן גבי אלו חוצצין לפלוף שחוץ לעין וגבי אלו שאינן חוצצין תני לפלוף שבעין ובפרק תינוקת (נדה דף ס״ז) אמר מר עוקבא לפלוף שבעין לח אינו חוצץ יבש חוצץ אימתי נקרא יבש משהתחיל לירק וכתבו התוספות לח אינו חוצץ דוקא שבתוך העין מפני שהליחה שבעין מלחלחתו ואינה מניחתו להיות יבש אבל לפלוף חוץ לעין אפילו לח [חוצץ] והכי משמע בפ״ט דמקואות וכו' דלא מפליג בין לח ליבש אלא בין חוץ לעין לתוך העין והיינו בלח דיבש בעין נמי חוצץ ע״כ וכ״נ מדברי רבינו שכתב לעיל דלפלוף שחוץ לעין חוצץ ולפלוף שבעין אינו חוצץ וכאן כתב לפלוף שבעין אם היה יבש והוא שהתחיל להוריק חוצץ ובנדה משמע בהדיא דלעיל מיירי בלח ומש״ה מפליג בין בעין לחוץ לעין דאילו יבש אפילו בתוך העין נמי חוצץ. והרא״ש כתב בפ' תינוקת (הל' מקואות סי' כ״ה) אהא דמר עוקבא והיינו כי הך דתנן שחוץ לעין חוצץ שבתוך העין אינו חוצץ כי אותו שבתוך העין הוא לח ומחוץ לעין הוא יבש ומפרש מר עוקבא שיעור יבשותו משיתחיל לירק עכ״ל. נראה מדבריו שהוא סובר שבתוך העין לא שייך ביה יבשות ואע״פ שהוא יבש הרבה חוצץ מפני שהדמעה מלחלחתו במקום דיבוקו ואינו חוצץ ומר עוקבא דאמר יבש חוצץ בחוץ לעין דוקא קאמר וכ״כ הטור בשמו וכתב (הטור בי״ד סימן קצ״ח) וז״ל והרמב״ם חילק על שבתוך העין בין בתוך שלשה ימים לאחר שלשה ושחוץ לעין כתב סתם חוצץ אפילו תוך שלשה עכ״ל. ונראה שכתב כן מפני שנמצא לרבינו שכתב כאן שרטה בבשרה והוציאה דם וטבלה בתוך שלשה ימים אין מקום השריטות חוצץ לאחר ג״י חוצץ מפני שהדם קופה שם כגלד שעל גבי מכה וכן לפלוף שבעין אם היה יבש והוא שהתחיל להוריק חוצץ בנדה ועלה על דעת הטור דכיון דעל מאי דמפליג בשריטות בין תוך שלשה ימים לאחר שלשה כתב וכן לפלוף שבעין שהוא להשוות לפלוף שבעין לשריטות גם לענין לחלק בין תוך שלשה לאחר שלשה ואם זו היתה דעת הטור יש לתמוה על רבינו איך נתן סימן ליבשותו שהתחיל להוריק שאם הוא תוך שלשה ימים אפילו הוריק נמי אינו חוצץ ואם הוא לאחר שלשה ימים אפילו לא הוריק נמי חוצץ ואם תאמר דתוך שלשה ימים אינו חוצץ אפילו הוריק ואחר שלשה ימים נמי אינו חוצץ עד שיוריק דתרתי בעינן לשיחוץ שיהיה אחר שלשה וגם שיוריק או תאמר איפכא דאחר שלשה אע״פ שלא הוריק חוצץ ותוך ג' אם הוריק חוצץ לא הוריק אינו חוצץ א״כ יקשה מאי וכן דהא בשריטה לא תלי אלא בימים ובלפלוף תלי גם בהורקה וכיון שמה שהכריחו לטור בדברי רבינו דבלפלוף נמי מחלק בין תוך שלשה לאחר שלשה אינו אלא משום דמתיבת וכן משמע שמשוה אותם לגמרי מאחר שאינו משוה אותם לגמרי אזל ליה הכרח ועוד דלפ״ז אין אחד משני הפירושים מבואר בדברי רבינו וכיון דשקולים הם הי מינייהו נקטת ועוד שלא מצינו בגמרא מי שעלה על דעתו לחלק בלפלוף שבעין בין תוך שלשה לאחר שלשה ומהי תיתי ליה לרבינו לפלוגי בינייהו ועל הטור שהביא דברי רבינו בסגנון זה יש לדקדק מה היה סבור בדבריו דאין לומר שהיה סבור שאינו מחלק בלפלוף אלא בין שלשה לאחר שלשה ולא בין הוריק ללא הוריק שהרי כתב אם היה יבש והוא שהתחיל להוריק חוצץ ואם היה סובר דבתרווייהו מפליג בין תוך שלשה לאחר שלשה ובין הוריק ללא הוריק וכפירוש אי זה משני הפירושים שכתבתי לעיל הוה ליה לפרש ולכתוב כן בשמו ולא לסתום כמו שעשה וכ״ש שכבר הוכחתי שאין לאחד מאותם הפירושים קיום. לכך נ״ל שהוא פשוט דלא מפליג רבינו בלפלוף בין תוך שלשה לאחר שלשה כלל אלא בהתחיל להוריק בלבד תליא מילתא.\",5,0],[8,381,2,20,\"ומ\\\"ש על שרטה בבשרה וכו' וכן לפלוף שבעין לא להשוותם לחלק בין תוך שלשה לאחר שלשה כתב כן אלא לומר דכשם שדם היוצא משריטות משכחת לה דחוצצין אע\\\"פ שהדם הזה מהגוף יצא וגם אינו עומד אלא ע\\\"פ השריטה בלבד מפני שאנו חוששין שנתפשט חוץ למקום השריטה אע\\\"פ שאינו נראה כך לפלוף שבעין אע\\\"פ שיצא מהגוף וגם אינו אלא בתוך העין ולא חוצה לו חוצץ אם הוא יבש דהיינו שהתחיל להוריק א\\\"נ דה\\\"ק כשם שדם זה כשנתייבש חוצץ כך לפלוף שבעין כשנתייבש חוצץ אלא שיבשותו של זה תלויה בשלשה ימים ושל זה תלוי בשיתחיל להוריק:\",6,0],[8,381,2,21,\"כוחל שבעין וכו'. פרק תינוקת (נדה דף ס״ז) אמר שמואל כחול שבתוך העין אינו חוצץ שעל גבי העין חוצץ אם היו עיניה פורחות אפילו על גבי העין אינו חוצץ ומפרש רבינו פורחות פתוחות ולא פתוחות יותר מדאי קאמר דאם כן לא עלתה לה טבילה אף על פי שאין להם כחול כמו שכתב רבינו בסמוך אלא היינו לומר שאינם סגורות תמיד אלא שפותחתן וסוגרתן וכלישנא קמא דרש״י. והטור נזדמנה לו נוסחא משובשת בדברי רבינו וגירסת ספרים שלנו בדברי רבינו עיקר שכתוב בהם ואם היו עיניה פתוחות אף על גבי העין אינו חוצץ ומצאתי נוסחא אחרת שכתוב בה ואם היו עיניה פורחות והיא הנכונה:\",1,0],[8,381,2,22,\"פתחה עיניה ביותר וכו'. שם אמר ר\\\"י פתחה עיניה ביותר או עיצמה עיניה ביותר לא עלתה לה טבילה:\",1,0],[8,381,2,22,\"בד\\\"א לענין טהרות וכו'. בפרק תינוקת בתר מאי דאמרינן נתנה תבשיל לבנה לא עלתה לה טבילה והני ריבדי דכוסילתא מתלתא יומין ואילך חייצי וההיא דלפלוף שבעין יבש חוצץ וההיא דכוחל שע\\\"ג העין חוצץ אא\\\"כ היו עיניה פורחות וההיא דפתחה עיניה ביותר או עיצמה עיניה ביותר לא עלתה לה טבילה אמרינן ולית הלכתא ככל הני שמעתתא אלא כי איתמר הכי לענין טהרות איתמר אבל לבעלה ש\\\"ד כך היא גירסת הרי\\\"ף וכן היה גורס רבינו ויש לתמוה על רבינו למה לא הזכיר ההיא דלפלוף שבעין בגירסא בד\\\"א לענין טהרות ונ\\\"ל שטעמו משום דמדין שרט ישן משתמע שפיר שהרי השוה אותם לעיל בלשון וכן לומר דכשם שזה חוצץ יבש כך זה חוצץ יבש זה כשיעור יבשותו וזה כשיעור יבשותו כמו שפירשתי לעיל וכיון דאשמעינן בחד מינייהו דאפי' יבש שיעור יבשותו אינו חוצץ אלא לטהרות אבל לא לבעלה ממילא נשמע דה\\\"ה לאידך דאפילו יבש שיעור יבשותו אינו חוצץ אלא לטהרות ולא לבעלה ומדברי רבינו שכתב נדה שנתנה תבשיל לבנה לא עלתה לה טבילה מפני השמנונית שעל ידיה ואח\\\"כ כתב בד\\\"א לענין טהרות וכו' נראה דבתבשיל שאינו נדבק לגמרי מיירי אלא דכיון דסתם תבשיל אית ביה שמנונית חיישינן שמא נדבק בידה וחייץ מדרבנן לטהרות אבל לא לבעלה ולפ\\\"ז אם היה התבשיל מדברים הנדבקים שחוצצין מדאורייתא אף לבעלה חוששין שמא נדבקו בה וצריכה לטבול וכבר היה אפשר לומר שמ\\\"ש רבינו שאינם חוצצין אלא מדבריהם לא משום דשמנונית אינו מהדברים החוצצין בכ\\\"מ קאמר הכי דשמנונית שכתב רבינו היינו רבב וחייץ מדאורייתא אף לבעלה אלא משום דכיון דאין אותו הרבב על רוב גופה אפילו אם מקפיד עליו לא חייץ מדאורייתא אלא מדרבנן דמדאורייתא תרתי בעינן רובו ושיהיה מקפיד עליו וכיון דלא מיתסר אלא מדבריהם לא גזרו אלא לטהרות ולא לבעלה. אבל קשה על זה דא\\\"כ כשכתב בפ\\\"א מד\\\"ס שכל דבר החוצץ אם היה מקפיד עליו לא עלתה לו טבילה אע\\\"פ שהוא על מיעוטו גזירה משום רובו שם היה לו לכתוב דהיינו לטהרות אבל לבעלה לא גזרו ועוד דמ\\\"ש ממפשלת בנה לאחריה וטבלה שכתב שלא עלתה לה טבילה חיישינן שמא היה טיט ברגלי התינוק ונדבק באמו ולא חילק בין טהרות לבעלה לפיכך נראה שפירוש ראשון עיקר ויש לדקדק בדברי רבינו שכתב לעיל דין המפשלת בנה לאחריה וטבלה שלא עלתה לה טבילה ומשמע דאף לבעלה לא עלתה לה טבילה ולפי מ\\\"ש התוספות והרא\\\"ש הא דמפשלת את בנה אחריה דין נתנה תבשיל לבנה היא הו\\\"ל לרבינו לפרש דהא דחיישינן במפשלת את בנה לטהרות היא ולא לבעלה כמ\\\"ש בנתנה תבשיל לבנה וכל אינך שמעתתא דבתרה ולמה הוציא שמועה זו מכלל אותן שמועות כיון דלית הלכתא ככל הני שמעתתא קאי גבי לשמועה שקודם זו וצ\\\"ל שבגירסת רבינו היה כתוב מפשלת בנה קודם נתנה תבשיל לבנה אלא שצריך לתת טעם מ\\\"ש נתנה תבשיל לבנה ממפשלת בנה שזו עלתה לה טבילה לבעלה וזו לא עלתה לה טבילה ואפשר שהטעם משום דנותנת תבשיל לבנה יודעת שדרך תבשיל לידבק ובודאי נזהרת ולפיכך מותרת לבעלה אלא דלטהרות החמירו אבל מפשלת בנה אינה עשויה ליתן אל לבה שיש טיט בידי התינוק או ברגליו לפיכך חשו לה אף לבעלה:\",2,0],[8,381,2,22,\"וכל החוצץ בנדה לטהרות וכו': כתב הראב״ד וחוצץ בגר בשעת טבילה א״א אף זה תמה גר למה הקישו לטבילת טהרות עכ״ל. טעמו מדתניא בפרק החולץ (יבמות דף מ״ו ע״ב) כל דבר שחוצץ בטבילה חוצץ בגר ובעבד משוחרר ובנדה ופירש״י ובנדה לבעלה ואע״פ שאין טבילתו לענין מגע טהרות כשאר טבילות עכ״ל ורבינו מפרש דבנדה דקתני לענין טהרות קאמר משום דבתוספתא דמקואות פ״ו קתני כל החוצצין בכלים חוצצין בנדה ובגר ובשעת טבילה ובחולין אין חוצצין ע״כ וודאי דכל לבעלה חולין הוא וא״כ הרי דמאי דלא חייץ בנדה לבעלה אי חייץ בה לטהרות חייץ נמי בגר:\",3,0],[8,381,2,23,\"מי שטבל ועלה וכו'. בפ\\\"ק דחולין (דף י'):\",1,0],[8,381,3,3,\"ואלו חוצצין בכלים הזפת והחמר. משנה פרק ט' דמקואות:\",1,0],[8,381,3,3,\"הזפת שבכוס ושבצלוחית וכו' הזפת שבתמחוי וכו' המור והקומוס וכו'. בתוספתא דמקואות פרק שביעי:\",2,0],[8,381,3,3,\"היה זפת או חמר וכיוצא בהן וכו' עד על המרדעת. משנה פרק ט' דמקואות:\",3,0],[8,381,3,3,\"ומה שכתב על המרדעת משני צדדין. בסוף פרק אלו קשרים (שבת דף קי\\\"ד):\",4,0],[8,381,3,4,\"ומ\\\"ש על בגד תלמידי חכמים וכו'. משנה פרק ט' דמקואות ושבת קי\\\"ד וכרבי יוסי:\",1,0],[8,381,3,5,\"היו על המטפחות וכו'. שם (דף קל\\\"ד):\",1,0],[8,381,3,6,\"טבח שהיה דם על בגדו וכו'. בס״פ דם חטאת (זבחים דף צ״ח):\",1,0],[8,381,3,7,\"ומ\\\"ש ה\\\"ז ספק אם חוצץ וכו'. שם בעיא דלא איפשיטא:\",1,0],[8,381,3,9,\"היה הזפת או החמר וכו' לכלוכי צואה וכו' אבל לכלוכי שמרים וכו'. תוספתא דמקואות פ\\\"ז אלא שבסוף כתוב שם שע\\\"י הקרדום ושע\\\"י המגריפה אינן חוצצין הגלידו הרי אלו חוצצין ונראה שהיא נוסחא נכונה וצריך להגיה כן בלשון רבינו:\",1,0],[8,381,3,10,\"דבר ברור הוא וכו' אין בדבר זה הפרש וכו'. דברים פשוטים הם:\",1,0],[8,381,3,15,\"כל ידות הכלים וכו' עד לעקמומית שבה. ריש פרק עשירי דמקואות:\",1,0],[8,381,3,15,\"כתב הראב\\\"ד היה בו מקום שאין המים נכנסים בו וכו' א\\\"א זה עשה תחת מה שראה במשנה וכו'. קנישקנין פירש\\\"י כלי שיש לו שתי פיות וכן פירש הערוך שהוא כלי שיש לו שני נקבים בצדו ולפי דברי הראב\\\"ד מתני' ה\\\"פ כלי שהטבילו כדרכו כלומר שוליו למטה ואין בו נקב זולת פיו והיינו בלא זרבובית לא עלתה לו טבילה עד שיטנו על צדו שע\\\"י כך יכנסו המים בכולו שאילו היה נקב בצדו דהיינו זרבובית לא היה צריך להטותו על צדו שאפילו יטבילנו דרך שוליו ע\\\"י הנקב בצדו יכנסו המים בכולו:\",2,0],[8,381,3,16,\"בהמה שהיה וכו'. משנה וגמרא בריש פרק במה בהמה (שבת דף נ\\\"א ע\\\"ב):\",1,0],[8,381,3,17,\"לא יטביל אדם את הקומקומוס בפחמין שבו וכו'. משנה פ\\\"ט דמקואות:\",1,0],[8,381,3,18,\"כלי שהוא מלא משקין וכו' עד הרי זה טהור. בסוף מקואות וכתנא קמא:\",1,0],[8,381,3,19,\"כלי שתוכו טהור וכו'. פרק התערובות עלה ע\\\"ח (ע\\\"ב) אמרינן נותן טעם ברוב אי הוי דאורייתא תנאי היא דתניא דלי שיש בו יין לבן וחלב והטבילו הולכין אחר הרוב ר' יהודה אומר רואין אותו כאילו הוא יין אדום אם דיהא מראהו כשר ואם לאו פסול ורמינהו כלי שהוא מלא רוקין והטבילו וכו' אמר אביי ל\\\"ק הא דידיה הא דרביה וכו' רבא אמר בדלי שתוכו טהור וגבו טמא עסקינן דמדינא סגי להו בכל דהו ורבנן הוא דגזרו בהו דילמא חייס עלייהו ולא מבטיל ליה וכיון דאיכא רובא לא צריך ופירש\\\"י דלי טמא שיש בו יין לבן או חלב שאין מראיהן ניכר בתוך המים והטבילו. תנאי היא דרבנן פליגי [עליה דרבי יהודה] וכוותיה קיימינן. בדלי שהוא טהור וגבו טמא כגון שנטמא גבו בטומאת משקין דרבנן דקי\\\"ל תוכו אוגנו אזנו וידיו טהורים. דמדינא סגי ליה בכניסת מים לתוכו כל דהו שתעלה טבילה לשפתו דהא תוכו אין צריך טבילה ורבנן הוא דגזור שיטבילנו יפה דאי אמרת דסגי ליה בטבילת גבו דילמא חייס עלייהו [על מי החטאת] שלא יתערבו מי המקוה לתוכו [ויפסלו] ולא מטביל ליה לשפת הכלי לפיכך גזרו עליו להטבילו [ולפוסלו] וכיון דאיכא ריבויא תו לא צריך דהא טבילת תוכו חומרא בעלמא הוא עכ\\\"ל:\",1,0],[8,381,3,19,\"כתב הראב\\\"ד אמר אברהם נשתבש בשמעתא דזבחים וכו'. נראה שטעמו מפני שהוא מפרש הא דרבא כדפרשינן דקאי אר' יהודה דשני אביי אליביה התם הא דידיה הא דרביה ואתא רבא למימר לעולם חד תנא הוא וכרביה ס\\\"ל והכי קאמר ברובא סגי בדלי שהוא טהור וגבו טמא וכו' ופשטא דשמעתא הכי מוכח ורבינו נראה שמפרש דרבא לא קאי אדאביי אלא מילתא באנפי נפשה היא דאתא לפרושי ברייתא דדלי שיש בו יין לבן ואפשר שהביאו לפרש כן שלא היה גורס רבא אמר אלא אמר רבא ומילתא באנפי נפשה היא וכדאמרן ועדיין ק\\\"ל שכתב רבינו סתם אבל אם היה בו יין אדום לא עלתה לו טבילה דמשמע דבשום פנים לא עלתה לו טבילה והא ליתא אלא דאם דיהא מראהו כשר ולזה נתכוון הראב\\\"ד שכתב וביין אדום בעינן שידהו מראיו לדברי הכל ואפשר לדחוק ולומר דמשמע דמילתא דפשיטא היא שאם דיהו מראיו הרי הוא מים:\",2,0],[8,381,3,19,\"ומ\\\"ש רבינו או משאר משקין. צ\\\"ל דמשקים אדומים קאמר:\",3,0],[8,381,3,20,\"לגין שהוא מלא וכו' עד כאילו לא טבלה. תוספתא פ\\\"ז:\",1,0],[8,381,3,20,\"כתב הראב\\\"ד לישנא דתוספתא וכו'. בפ\\\"י דמקואות אלו שאין צריכין שיבאו בהם המים קשרי העני והנימין וחבט של סנדל ותפילה של ראש בזמן שהוא חוצה ושל זרוע בזמן שאינה עולה ויורדת ואזני החמת ואזני התרמיל ופירש שם רבינו קשרי העני הקשר שיקשור בגדיו אם יקרעו אשר אין כוונתו להתירם וכן קשרי הנימין והם הקשרים אשר יקשרו קצוות פתילים היוצאים מן הבגד וכו' וחבט של סנדל לולאות האזנים עכ\\\"ל:\",2,0],[8,381,3,21,\"ומ\\\"ש ואם הקפיד עליהם חוצצין וכו'. נראה שלמד כן רבינו מדנקט קשרי העני משמע הא של בע\\\"ה צריכים שיבואו בהם המים וטעמא משום דסתם בע\\\"ה מקפיד וסתם עני אינו מקפיד אבל אם הקפיד העני הוי חציצה ואם לא הקפיד בע\\\"ה לא הוי חציצה דכלל גדול שנינו בספ\\\"ט זה הכלל כל המקפיד עליו חוצץ שאינו מקפיד עליו אינו חוצץ ובתוספתא פ\\\"ח שנוי בפירוש כדברי רבינו:\",1,0],[8,381,3,24,\"ואלו שצריכים שיבואו בהם וכו'. פרק י' דמקואות אלו שהם צריכין שיבאו בהם המים הקשר שבפרקסין שבכתף ושפה של סדין צריך למתח ותפלה של ראש בזמן שאינה חוצה ושל זרוע בזמן שהיא עולה ויורדת ושנצין של סנדל ונראה שרבינו מפרש דה\\\"ק הקשר שבפרקסין ושבכתף ופרקסין ר\\\"ל חלוקים וה\\\"פ הקשר שבפתחי החלוקים שהם עשויות לולאות וכן הקשר שבלולאות שבכתף:\",1,0],[8,381,3,24,\"ומ\\\"ש רבינו לחלק בין נימי הבגדים שנקשרו מאליהן לקשרי נימי הבגדים שקשרן תוספתא פ\\\"א:\",2,0],[8,381,3,24,\"ומ\\\"ש שפה של סדין צריך למתח. פירושו הקמטים שיש בשפת הסדין צריך למתחן כדי שיבאו בהם המים:\",3,0],[8,381,3,24,\"הסלים של גת ושל בד וכו'. ג\\\"ז תוספתא פ\\\"ח:\",4,0],[8,381,3,24,\"הכר והכסת וכו' עד וינוחו מבעבוען. פ\\\"י דמקואות:\",5,0],[8,381,3,25,\"כל ידות הכלים וכו'. שם וכת\\\"ק:\",1,0],[8,381,3,26,\"כלי טמא שנתן בתוכו כלים אחרים וכו'. בפ״ו דמקואות דלי שהוא מלא כלים והטבילו הרי אלו טהורים ואם לא טבל אין המים מעורבים עד שיהיו מעורבין כשפופרת הנאד ובפ' חומר בקודש (חגיגה דף כ״ב) מאי קאמר ואם לא טבל ה״ק ואם אינו צריך להטבילו ופירש״י ואם אינו צריך להטבילו ואתה בא לטהר כדים שבתוכו ע״י מים המעורבים למקוה עד שיהו מעורבים דרך פה רחב כשפופרת הנאד אבל כשהכלי טמא אפי' פיו צר כל שהו כלים שבתוכו טהורים דמגו דסלקא טבילה לגופו של כלי ליטהר ע״י מים הנכנסין דרך פיו דכטומאתו כן טהרתו סלקא נמי טבילה לכלים שבתוכו:\",1,0],[8,381,3,26,\"ומ\\\"ש ואם הטהו על צדו וכו'. תוספתא פ\\\"ה:\",2,0],[8,381,3,26,\"ומ\\\"ש בד\\\"א לתרומה אבל לקדש וכו'. משנה וגמ' ר\\\"פ חומר בקדש:\",3,0],[8,381,3,26,\"ומ\\\"ש כמו שביארנו למעלה במקומו. פי\\\"ב משאר אה\\\"ט:\",4,0],[8,381,4,2,\"דין תורה שכל מים מכונסים וכו' שיערו חכמים אמה על אמה וכו'. פשוט במסכת מקואות ובכמה מקומות בגמרא מהם בסוף מסכת ע\\\"ז (דף ע\\\"ה ע\\\"ב) ובספ\\\"ק דחגיגה (דף י\\\"א) ובעירובין פ\\\"ק (דף ד' ע\\\"ב) ופ\\\"י דפסחים (דף ק\\\"ט ע\\\"ב) ופ\\\"ג דיומא (דף ל\\\"א) ומשמע בפרק עושין פסין דהני אמה על אמה ברום שלש אמות במרובע הוא ולא בעיגול:\",1,0],[8,381,4,2,\"ומ\\\"ש רבינו בין שאובים בין שאינם שאובים ומד\\\"ס שהמים השאובים פסולים לטבילה. דעת רבינו כדעת ר\\\"י שכתבו התוס' בספ\\\"ק דפסחים בשם ר\\\"י והביאו ראיות לדבר וכתב הר\\\"ן בפרק המוכר את הבית ובפ\\\"ב דשבועות שכן נראה מדברי הר\\\"י ן' מיגש ושכן דעת הגאונים וכתב הרמב\\\"ן שכן דעת הרי\\\"ף ויש חולקים בדין זה ככתוב על ספר ב\\\"י:\",2,0],[8,381,4,2,\"ולא עוד אלא מקוה מים וכו'. רפ\\\"ג דמקואות ופ\\\"ק דעדיות ופ\\\"ק דשבת ופרק ב' דחגיגה (דף ט\\\"ו):\",3,0],[8,381,4,2,\"אע\\\"פ שפיסול מים שאובים מדברי סופרים למדוהו בהיקש וכו'. בת\\\"כ:\",4,0],[8,381,4,3,\"ומ\\\"ש רבינו כיצד המניח קנקנים בראש הגג וכו' עד הרי זה ישבור את הקנקנים עד והמים הנקווים מהם מקוה כשר. משנה בפ\\\"ב דמקואות המניח קנקנים בראש הגג לנגבן ונתמלאו מים ר\\\"א אומר אם עונת גשמים היא או אם יש מעט מים בבור ישבר ואם לאו לא ישבר רי\\\"א בין כך ובין כך ישבר או יכפה אבל לא יערה פירוש רבי אליעזר סבר הא דמכשרינן במניח קנקנים אע\\\"פ שיש בו קצת תפיסת ידי אדם היינו דוקא ע\\\"י תערובת מים אחרים דוקא שישבר הקנקנים ולא ישים ידיו בהם אף לכפותם דאז חשיב תפיסת ידי אדם לפסול ור\\\"י סבר דמכשרינן אפילו עשה כל המקוה מהם ואפילו שלח יד בהם לכפותם ובלבד שלא יגביהם לערותן:\",1,0],[8,381,4,4,\"ומ\\\"ש עוד רבינו המניח כלים תחת הצינור. משנה פ\\\"ד דמקואות המניח כלים תחת הצינור וכו' פוסלים את המקוה אחד המניח ואחד השוכח כדברי ב\\\"ש וב\\\"ה מטהרים בשוכח אר\\\"מ נמנו ורבו ב\\\"ש על ב\\\"ה ומודים בשוכח בחצר שהוא טהור א\\\"ר יוסי עדיין מחלוקת במקומה עומדת ומייתי לה בפרק קמא דשבת (דף י\\\"ו ע\\\"ב) ואיתמר עלה אמר רב משרשיא דבי רב אמרי הכל מודים בשהניחם בשעת קישור עבים טמאים בשעת פיזור עבים ד\\\"ה טהורים לא נחלקו אלא שהניחם בשעת קישור עבים ונתפזרו וחזרו ונתקשרו מ\\\"ס בטלה מחשבתו ומ\\\"ס לא בטלה מחשבתו ופירש\\\"י תחת הצינור שקבעו ולבסוף חקקו להמשיך מים למקוה דשוב אינו נפסל אבל הכלים פוסלים משום שאינם מטהרים. בשכח ולא חשיב שאיבה הואיל ולא לכך נתכוונו. בחצר שלא תחת הצינור ונתמלא מן הנוטפים ונפלו למקוה שהוא טהור. במניח תחת הצינור ובשהניחן בשעת קישור עבים ואח\\\"כ נתפזרו ושכחן כדמוקי לה לקמן הוא דפליגי ביה דגלי דעתיה שרצה שיפלו לתוכו ומשום פיזור עבים לא בטלה מחשבתו ראשונה אבל במניח בחצר ואפי' בשעת קישור עבים ונתפזרו לא מוכחא מחשבה קמייתא שפיר מעיקרא הילכך בטלה. במקומה עומדת במניח תחת הצינור בקישור עבים לא נמנו ורבו עליהם לבטל דברי ב\\\"ה דלא חזרו בהם. הניחן תחת הצינור בשעת קישור עבים ואיחרו גשמים לבא ויצא למלאכתו ושכחן דברי הכל הואיל ומתחילה לכך נתכוון לא בטלה מחשבתו. בשכחן דברי הכל טהורים דליכא גלוי דעתא. בטלה מחשבתו דכי נתפזרו אסח דעתיה דסבר לא ירדו גשמים עוד עכ\\\"ל:\",1,0],[8,381,4,4,\"ובפ\\\"ב דמקוואות תנן הסייד ששכח עציץ בבור ונתמלא מים אם היה המים צפין על גביו כל שהן ישבר אם לאו לא ישבר דברי ר\\\"א ר\\\"י אומר בין כך ובין כך ישבר המסדר קנקנים בתוך הבור ונתמלאו מים אע\\\"פ שבלע הבור את מימיו הרי זה ישבר ותניא בתוספתא פרק שלישי ר\\\"י אומר בין כך ובין כך ישבר [רבי יוסי אומר משום ר\\\"י אף יטה ובלבד שלא יטול] כלומר שלא יטול בידיו ויערן פי' הסייד שסד את הבור בסיד והביא הסיד בעציץ ושכח העציץ בבור ונתמלא מים אם המים צפים ע\\\"ג העציץ לא חשיבי המים שבתוכו שאובים כיון שמחוברים למקוה וישבר העציץ אבל אם הגביה ועירה המים למקוה נעשו שאובים ואם לא היו צפים נעשו שאובים ור\\\"י סבר אפילו אין המים צפים על גביו לא חשיבי המים שבתוכו שאובים כיון שמחוברים למקוה וישבר אבל לא יכפה דחשיב תפיסת ידי אדם יותר ממניח קנקנים לנגבן דהתם לא חישב עליהם לקבלה מעולם דלא העלם אלא לנגבם. המסדר קנקנים בתוך הבור שהוא מלא מים כדי שיבלעו המים בתוך דפני הקנקנים ולא יבלעו היין שינתן לתוכן ונתמלאו מים שנבלעו המים בדפנותיהם וגם עברו לתוכן עד שנתמלאו מים אע\\\"פ שבלע הבור מימיו ישבר הקנקנים שהמים שבתוכן לא חשיבי שאובים שלא כיון שיכנסו המים לתוכן. ודברי רבינו תמוהים מכמה פנים חדא דמשמע שפסק כב\\\"ש דפסלי במניח תחת הצינור אף בשוכח ואמאי שבק ב\\\"ה ופסק כב\\\"ש ואע\\\"ג דרבי מאיר אמר נמנו ורבו ב\\\"ש על ב\\\"ה הא ר\\\"י אמר עדיין מחלוקת במקומה עומדת וקי\\\"ל ר\\\"מ ורבי יוסי הלכה כר\\\"י. ועוד שכתב דמניח כלים תחת הצינור בכל עת ובכל זמן פסולים כלומר בין שהניחן בשעת קישור העבים פסולים וזה היפך ממאי דאוקימנא בפ\\\"ק דשבת דהכל מודים בשהניחן בשעת פיזור עבים שהם טהורים. ועוד שכתב שגזרו על השוכח בחצר והא בהדיא תנן דמודים ב\\\"ש בשוכח בחצר שהוא טהור. ועוד שהוא מניח חילוק דבשעת קישור העבים ושעת פיזור העבים בחצר ולא בצינור ולפ\\\"ז משמע דכי אמרינן לא נחלקו אלא שהניחן בשעת קישור העבים ונתפזרו וחזרו ונתקשרו מ\\\"ס בטלה מחשבתו ומ\\\"ס לא בטלה מחשבתו דהיינו לומר דב\\\"ה סברי בטלה מחשבתו וב\\\"ש סברי לא בטלה וכיון שהוא ז\\\"ל פוסק כב\\\"ש כמו שקדם ה\\\"ל לפסוק גם בזה דפסולים כב\\\"ש דאמרי לא בטלה מחשבתו ועוד דלפי מה שהוא ז\\\"ל מניח חילוק דקישור עבים ופיזורם בחצר מיירי בשכח וכן אם הניחם בשעת קישור עבים ונתפזרו וחזרו ונתקשרו למה לא כתב דין השוכח:\",2,0],[8,381,4,4,\"ונראה לומר שרבינו ז\\\"ל מפרש דכי אמר ר\\\"י עדיין מחלוקת במקומה עומדת פליג בין אמאי דאמר ר\\\"מ נמנו ורבו ב\\\"ש על ב\\\"ה בין למאי דאמר מודים בשוכח בחצר שהוא טהור דסבר ר\\\"י דבין במניח בין בשוכח בין תחת הצינור בין בחצר סברי ב\\\"ש דפסול וב\\\"ה מטהרים בשוכח תחת הצינור וכ\\\"ש בשוכח בחצר ומשום דאיכא למיתמה אסברת ר\\\"י דנהי דתחת הצינור גזרו ב\\\"ש שוכח אטו מניח משום דדרך להניח כלים תחת הצינור לקבל מים הילכך שייך למיגזר ביה אבל בחצר דאינו מצוי כ\\\"כ להניח בו כלים לקבל מים נהי דאסרו במניח לא היה להם לגזור בשוכח ולהכי אוקי רב משרשיא דבין לר\\\"מ בין לרבי יוסי אליבא דב\\\"ש בקישור עבים ופיזור עבים תליא מילתא דכשהניחן בשעת קישור עבים אע\\\"פ שהוא חצר ד\\\"ה טמאים כלומר בין לר\\\"מ בין לרבי יוסי כיון שהוא שעת קישור עבים כך עשוי לירד מים בחצר כמו שעשוי לקלח הצינור ולב\\\"ש דגזרי בצינור שוכח אטו מניח ה\\\"נ גזרו בהניח בחצר בשעת קישור עבים שוכח אטו מניח וב\\\"ה דלא גזרי בצינור ה\\\"נ לא גזרי ובהניחן בשעת פיזור עבים ד\\\"ה טהורים כלומר דבין לר\\\"מ בין לרבי יוסי מודו ב\\\"ש דטהור ואפילו במניח וכ\\\"ש בשוכח לא נחלקו אלא בשהניחן בשעת קישור עבים ונתפזרו וכו' מ\\\"ס בטלה מחשבתו וכו' כלומר לא נחלקו ר\\\"מ ורבי יוסי אליבא דב\\\"ש אלא בשהניחן בשעת קישור עבים ונתפזרו וכו' מ\\\"ס בטלה מחשבתו כלומר דר\\\"מ סבר דמודו ב\\\"ש דבטלה מחשבתו ואפי' במניח טהורים דכיון דנתפזרו העבים אסח דעתיה והילכך אע\\\"פ שלא שכח טהורים והא דקאמר ר\\\"מ דמודים בשוכח לאו משום דליבעי שישכח ממש אלא לנתפזרו העבים קרי שוכח דכשם שהשוכח הוא מסיח דעתו מהדבר כך כשנתפזרו העבים הסיח דעתו מהמים ומ\\\"ס לא בטלה מחשבתו כלומר רבי יוסי דאמר עדיין מחלוקת במקומה עומדת סבר דלב\\\"ש כיון שהניח בשעת קישור עבים אע\\\"פ שנתפזרו לא בטלה מחשבתו הילכך הם פסולים וסובר עוד רבינו דהלכה כר\\\"מ משום דבגמרא אמרינן דר\\\"ט ס\\\"ל כוותיה:\",3,0],[8,381,4,4,\"והשתא ניחא כל דבריו שמ\\\"ש בתחת הצינור דבכל עת ובכל זמן פסולין היינו משום דסבר דמאי דאוקי רב משרשיא דבשעת פיזור עבים ד\\\"ה טהורים וכו' לא קאי אלא למניח בחצר דוקא אבל במניח תחת הצינור פסולין משום דהיינו כב\\\"ש דהלכתא כוותייהו לדעתו ז\\\"ל כר\\\"מ דאמר נמנו ורבו ב\\\"ש על ב\\\"ה:\",4,0],[8,381,4,4,\"ומ\\\"ש וכן המניח הכלים בחצר בשעת קישור עבים פסולים וכן גזרו בשוכח וכו'. מבואר ע\\\"פ דעתו ז\\\"ל דמפרש דמאי דאמר רב משרשיא הכל מודים בשהניחם בשעת קישור עבים טמאים וכו' אמניח או שוכח בחצר קאי דשעת קישור עבים לחצר כצינור דכל זמן דמי וכי היכי דבצינור גזרי ב\\\"ש דהלכתא כוותיה ה\\\"נ גזרי בחצר בשעת קישור עבים:\",5,0],[8,381,4,4,\"ומ\\\"ש הניחם בחצר בשעת פיזור עבים כשרים. מבואר על פי זה דהיינו דאמר רב משרשיא בשעת פיזור עבים ד\\\"ה טהורים דאפי' לא שכח נמי טהורין דכיון דחצר הוא ובשעת פיזור עבים הוי כמו שהניחם בראש הגג לנגבן דבכל גוונא טהורים:\",6,0],[8,381,4,4,\"ומ\\\"ש וכן אם הניחן בשעת קישור עבים ונתפזרו וחזרו ונתקשרו כשרים. גם זה שם מבואר ע\\\"פ דעתו ז\\\"ל דרב משרשיא אמניח בחצר קאי ור\\\"מ סבר דנתפזרו העבים מודו ב\\\"ש דבטלה מחשבתו והוי כהניחם בשעת פיזור העבים דטהורים בכל גווני ובכך עלו דברי רבינו כהוגן וכבר העלה רבינו דעתו זה בפי' המשנה אכן דבריו סתומים וחתומים בביאור שיטת ההלכה ולכן הארכתי להוציא לאור משפטם לדעתו ז\\\"ל:\",7,0],[8,381,4,4,\"אח\\\"כ מצאתי להר\\\"א בנו של רבינו שכתב וז\\\"ל מן הלשון עצמו אתה למד שלא נחלקו ת\\\"ק ור' יוסי אלא בשוכח בחצר שכך אמר ת\\\"ק המניח כלים תחת הצינור וכו' אמר ר\\\"מ נמנו ורבו ב\\\"ש על ב\\\"ה ולא פליג רבי מאיר על רבי יוסי בזה וחזר ת\\\"ק ואמר ומודים בשוכח בחצר שהוא טהור כלומר לא פליגי ב\\\"ש על ב\\\"ה בשוכח בחצר ולא פליג ר\\\"מ על ת\\\"ק בזה אבל פליג רבי יוסי על תנא קמא בזו דאמר עדיין מחלוקת במקומה עומדת וכשם שנחלקו ב\\\"ש וב\\\"ה בשוכח תחת הצינור כך נחלקו בשוכח בחצר ואילו היה הדבר כמו שעלה על לבך שרבי יוסי חולק על ר\\\"מ בנמנו ורבו בתחילה ה\\\"ל לחלוק וכך היה צ\\\"ל אמר רבי מאיר נמנו ורבו בית שמאי על בית הלל ורבי יוסי אומר עדיין מחלוקת במקומה עומדת ואמאי שתיק התנא על מחלוקת רבי יוסי ולא שנאה אלא על פסקן ומודים שהוא ענין אחר ושקשה על זה הפירוש מדאקשינן בגמרא הניחא לרבי מאיר אלא לרבי יוסי חסרו להו קושיא יפה היא אבל איכא לתרוצה ולא דחינן לשון המשנה ומשנינן צורת הענין בזו הקושיא דאיכא למימר הואיל ומילתא דכלים פסיקא בצינור ובחצר חדא מדרבו וחדא מדאודו דרבי מאיר לא פליג על ת\\\"ק דמודים בית שמאי בשוכח בחצר ומדלא פליג עליה כוותיה ס\\\"ל ולפיכך חשב אליבא דר\\\"מ האי מתניתין ממניינא אלא לרבי יוסי דאמר דמילתא דכלים לא פסיקא דהא בחצר איכא מחלוקת לדבריו לא יכול למימני מניח כלים דלא פסיקא מילתייהו בצינור וחצר אליבא דידיה ולפיכך נפקא מילתא דכלים ממניינא לטעמיה וחסרו להו, ראיה לזה הפירוש הנכון הא דאקשינן בתר הכי הא ניחא לרבי יוסי אלא לר\\\"מ טפיא ליה כלומר לרב יוסי דמפיק מילתא דכלים ממניינא הואיל ויש בה מחלוקת וליכא למימנא ניחא ליה אי חשיב תינוק עכו\\\"ם מכלל המנין לא טפיין ליה אלא לר\\\"מ דפסיקא מילתא דכלים ולפיכך א\\\"א לאפוקה ממנין אי חשיב תינוק עכו\\\"ם כדאמרת דהוה ממניינא הא טפיין להו ופרקינן ר\\\"מ אוכלים וכלים חדא חשיב להו ואי כדסליק אדעתייכו דפלגינן צינור מחצר כנראה מקושייתך על פירוש הרב ז\\\"ל דאמרת בכללא אמאי לא קמה לה השוכח תחת הצינור ממניינא וכו' אילו הדבר כן שהצינור והחצר מוחלקים עד שיוכל החולק באחד מהם למנות השני היו שנים במנין ולעולם קשיא לר\\\"מ וטפיין להו ואע\\\"ג דחשיב אוכלים וכלים שנטמאו במשקים בחדא הילכך ליכא לפרושי אלא כדפרשינן. ושקשה לך מדגרסיתו ב\\\"ה סברי בטלה מחשבתו ובית שמאי סברי לא אמרינן בטלה מחשבתו התשובה שאין לשון הגמרא כך בהרבה ספרים חקרנו וכתוב בהם מר סבר בטלה מחשבתו ומר סבר לא בטלה מחשבתו ולעולם אימא לך מר דהוא ת\\\"ק ומר דהוא רבי יוסי כדפריש אבא מארי בפירוש המשנה ולא ק\\\"ל מידי עכ\\\"ל:\",8,0],[8,381,4,6,\"כיצד פוסלין וכו' שאם היה במקוה פחות מארבעים סאה כו' הכל פסול. בפרק שני דמקואות.\",1,0],[8,381,4,6,\"ומה שכתב אבל מקוה שיש בו ארבעים סאה וכו' [ולא עוד אלא וכו']. בפרק ששי ופרק שביעי דמקואות:\",2,0],[8,381,4,7,\"מקוה שיש בו ארבעים סאה וכו'. בפ״ז דמקואות תנן היו בו ארבעים סאה נתן סאה ונטל סאה כשר ובס״פ הערל (יבמות דף פ״ב ע״ב) אמרינן היו ארבעים סאה מכוונות נתן סאה ונטל סאה כשר ואמר ר״י וכו'. עד רובו וכתבו המפרשים דהיינו דוקא במי פירות אבל מים שאובין אפילו אלף סאין אינן פוסלין את המקוה השלם שיש בו ארבעים סאה וממ״ש רבינו כאן נראה שהוא סובר דהא דאמרינן בפרק הערל עד רובו במים שאובים דוקא היא אבל במי פירות לא מכשרינן אלא בנתן סאה אחת ונטל סאה כדקתני מתניתין דמקואות ואמי פירות דקתני ברישא קאי ולפ״ז ההיא דמייתי בפרק הערל אינה מתניתין דמקואות דההיא דמקואות במי פירות ודהערל במים שאובים ודין מי פירות כתבו רבינו בפ״ז והרא״ש כתב בסוף נדה (הל' מקואות סי' א') שדברי רבינו תמוהים שמתחילה כתב כיון שיש בו ארבעים סאה ממלא בכתף ושופך כל היום אע״פ שרבין עליו מים שאובים כשר ולמה יפסל בנתן סאה ונטל סאה ביותר מרובן ואין לומר דהא דמכשר ברישא משום דיש במקוה ארבעים סאה מים כשרים הילכך אינו נפסל ברביית מים פסולים אבל בנתן סאה ונטל סאה שלא נשארו במקוה ארבעים סאה מים כשרים א״א שלא יטול גם מן הכשרים הילכך אינו כשר אלא עד רובו דהא איהו גופיה כתב מקוה העליון שיש בו ארבעים סאה מים כשרים והיה ממלא בכלי ונותן לתוכו עד שירדו המים וירדו לתחתון ארבעים סאה הרי התחתון כשר וגם העליון הוא כשר אע״פ שכל אחד מהם רוב מים שאובים ואין בשניהם ארבעים סאה מים כשרים אלא ודאי ההיא דנתן סאה ונטל סאה במי פירות כמו שפירש ר״ת והחמירו חכמים במי פירות דלא חזו לטבילה כלל דמקוה מים כתיב הילכך פסלי ברובא עכ״ל:\",1,0],[8,381,4,7,\"ונראה שאפשר לומר שטעם רבינו דמדינא שרי בכל גווני אלא דהיכא דנתן סאה ונטל סאה כי הוי רובו מיחזי להו לאינשי שניטלו הכשרים ונכנסו תחתם שאובים ויבאו להכשיר בכולם שאובים לגמרי ולפיכך גזרו בו מפני מראית העין אבל בהך דמקוה העליון ומקוה התחתון כיון דלא ניטלו ביד ליכא למיחש למראית העין וכבר הזכיר חילוק זה הרמב\\\"ן בפרק המוכר את הבית:\",2,0],[8,381,4,8,\"אין המים השאובים פוסלים את המקוה וכו'. בסוף פ\\\"ק דתמורה (דף י\\\"ב) ראב\\\"י אומר מקוה שיש בו כ\\\"א סאה מי גשמים ממלא בכתף י\\\"ט סאה ופותקן למקוה והם טהורים שהשאובה מטהרת ברבייה ובהמשכה וגרסינן תו התם א\\\"ר יוחנן שאובה שהמשיכוה כולה טהורה ופירש\\\"י ופותקן למקוה שלא יערה מן הדלי לתוך המקוה דאפילו בשלשה לוגין מיפסיל מקוה בכה\\\"ג אבל יעשה חריץ וגומא למרחוק ויערה מן הדלי לתוך הגומא ויקלחו המים דרך החריץ לתוך המקוה והיינו המשכה. והן טהורים כלומר כשר לטבול בו. מטהרת ברבייה ובהמשכה כשהרוב ממי הגשמים שנפלו מעצמם לתוכו והמשיך מיעוט של שאובה לתוכו דרך חריץ מטהרת השאובה:\",1,0],[8,381,4,8,\"ומ\\\"ש וכן גג שהיה בראשו עשרים סאה ומשהו וכו'. תוספתא פרק ד' דמקואות:\",2,0],[8,381,4,10,\"ומ\\\"ש מי גשמים ומים שאובים שהיו מתערבים בחצר וכו'. משנה פרק ד' דמקואות:\",1,0],[8,381,4,10,\"ויש לתמוה על דברי רבינו דממשנה זו משמע דלא מכשרינן בשאובה שהמשיכוה אלא דוקא כשנתערבו קודם שירדו למקוה אבל לא נתערבו לא כדיליף הרא\\\"ש מדקתני סיפא היו מקלחים לתוך המים וכו' ואילו הוא ז\\\"ל כתב לעיל מקוה שיש בו עשרים סאה ומשהו מים כשרים והיה ממלא ושואב חוץ למקוה [והמים נמשכין ויורדין למקוה הרי הוא כשר הרי שאפילו שלא נתערבו קודם שירדו למקוה מכשיר] וצ\\\"ל שרבינו ז\\\"ל מפרש דהא דקתני היו מקלחין ממקום שאיבתן לתוך [המים היינו לומר שלא היו נמשכין אלא המים השאובין היו מקלחין ממקום שאיבתן לתוך המקוה] בלי המשכה כלל ומש\\\"ה קתני שאם לא היו ארבעים סאה מים כשרים במקוה נפסל בשלשה לוגין מים שאובים שנפלו בו אבל אם היו השאובים נמשכים אע\\\"פ שלא היו במקוה ארבעים סאה מים כשרים היו השאובים משלימים שיעורו כדלעיל וכפירוש הזה נראה מדבריו בפירוש המשנה אבל אכתי קשה מדקתני רישא אימתי בזמן שמתערבין עד שלא יגיעו למקוה דמשמע שמפני שנתערבו מקודם הוא דמכשרינן הא לאו הכי לא צ\\\"ל דהא דקתני שמתערבים היינו לאפוקי היכא דלא נפלו רוב כשרים ברישא דהיכא דהיה במקוה פחות מעשרים סאה ומשהו מים כשרים הוא נפסל בשלשה לוגין מים שאובים אף ע\\\"פ שנפלו בו בהמשכה אבל כשהם מתערבים קודם שירדו והם נמשכים ויורדים אע\\\"פ שאין רוב הכשרים ניכר ועומד לעצמו כיון שגם השאובים אינם יורדים למקוה בפני עצמם אלא מעורבים עם הכשרים ובדרך המשכה כשרים והכי משמע מדבריו ז\\\"ל שכתב אין המים שאובין פוסלין את המקוה בשלשה לוגין עד שיפלו לתוך המקוה מן הכלי אבל אם נגררו המים השאובים וכו' אינם פוסלים את המקוה עד שיהיו מחצה למחצה אבל אם היה רוב מן הכשרים הרי המקוה כשר כיצד מקוה שיש בו עשרים סאה ומשהו מים כשרים והיה ממלא ושואב וכו' שהשאובה שהמשיכוה כשירה אם היה שם רוב ארבעים סאה מן הכשר כלומר דדוקא במקוה רוב ארבעים סאה מן הכשר הוא דמכשרינן כשנפלו בו מים שאובים ע\\\"י המשכה הא לאו הכי לא ואח\\\"כ כתב וכן גג שהיה בראשו כ' סאה ומשהו מי גשמים וכו' מבואר דהיינו לומר שאפילו שאב ונתן לתוך המקוה בלא המשכה כלל שכבר נפסל המקוה בשלשה לוגין מים שאובים שנפלו לתוכו אם היו רוב כשרים במקוה כשר ע\\\"י המשכה שימשיכה כולה למקום אחר ואח\\\"כ כתב מי גשמים ומים שאובים שהיו מתערבים בחצר ונמשכים ויורדים וכו' לומר דאפי' לא היו רוב מים כשרים ניכר ועומד לעצמו כשנתערבו בו המים השאובים כיון שגם השאובים אינם יורדים למקוה בפני עצמה אלא מעורבים עם הכשרים ובדרך המשכה כשרים והיינו דכתב אימתי בזמן שמתערבין עד שלא יגיעו למקוה כלומר שאם לא היו מתערבין קודם שיגיעו למקוה אע\\\"פ שהיו השאובים נמשכים ויורדים אם לא היו במקוה רוב מ' סאה מן הכשרים קודם שיתערבו עמהם השאובים פסול ואח\\\"כ כתב אבל אם היו הכשרים והפסולים מקלחים לתוך המקוה וכו' כלומר וכל זה הוא דוקא כשהיו השאובים נמשכים ויורדים אבל אם היו מקלחים כלומר שהיו השאובים יורדים למקוה בלא המשכה אפי' היו הכשרים בתוך המקוה ארבעים סאה חסר קורטוב נפסלו כולם מעת שנפלו בהם שלשה לוגין מים שאובים ואין להם תקנה אלא ע\\\"י שימשיכם כדלעיל. ומה שהפסיק רבינו בהוראת מקצת חכמי המערב באמצע דבריו הוא מפני שחכמי המערב ורבינו חולקים בפירוש מה שאמרו בגמרא שאובה שהמשיכוה כולה כשירה לפיכך סמך ענין לו ועוד מפני שמשנה זו הוי תיובתא לחכמי המערב כמ\\\"ש רבינו בפירוש המשנה לפיכך אחר הוראתם כתב דברי המשנה דמינה נשמע דליתא לההיא הוראה:\",2,0],[8,381,4,10,\"וטעם הוראת חכמי המערב נראה שהיתה מדגרסינן בפרק קמא דתמורה אמתני' דאין מים שאובין פוסלין את המקוה אלא לפי חשבון מאן תנא א\\\"ר חייא בר אבא אר\\\"י ראב\\\"י היא דתניא ראב\\\"י אומר מקוה שיש בו כ\\\"א סאה מי גשמים ממלא בכתף י\\\"ט סאה ופותקן למקוה והם טהורים שהשאובה מטהרת ברבייה והמשכה מכלל דרבנן סברי דרבייה ובהמשכה לא אלא דכי אתא רבין אר\\\"י שאובה שהמשיכוה כולה כשירה מני לא רבנן ולא ר\\\"א אלא אמר רבה לפי חשבון כלים ויוסי בן חוני היא וכו' ומשמע לחכמי המערב דראב\\\"י בעי רבייה דכשרים והמשכה דשאובים ורבנן לא באו רבייה דכשרים אלא כל ארבעים סאה שאובים שהומשכו כשר ואפילו אין בהם תערובת כשרים כלל וכן פירש\\\"י וסוברים דקי\\\"ל כרבנן דרבים נינהו ורבינו כתב בפירוש המשנה שהם טעו בהוראה זו לסיבת מיעוט שמירת המשנה והחקירה למה שבה כלומר שנעלמה מהם מתניתין דמים שאובים ומי גשמים שנתערבו בחצר ובעוקא וכו' שכתבתי לעיל דמשמע מינה בהדיא דבלא רוב מים כשרים לא מתכשרי מים שאובים ע\\\"י המשכה ואני אומר שאין [מאותה הוראה] הוכחה שנעלמה אותה משנה מהם דאפשר דהוו ידעי לה ולא פסקו כמותה משום דהוו מפרשי לה כפירוש רבינו שמשון דאתיא דלא כרבי אליעזר ב\\\"י ודלא כרבנן דפליגי עליה כדמשמע בסוף פ\\\"ק דתמורה ואפילו אי הוו סברי דראב\\\"י היא איכא למימר דלא פסקו כמותה משום דס\\\"ל דלא קי\\\"ל כוותיה ואע\\\"ג דסתם תנא כוותיה לא קי\\\"ל כההוא סתמא מדחזינן דכי אתא רבין אמר ר\\\"י שאובה שהמשיכוה כולה [כשירה] וכיון דסתמא אמר הכי משמע דהכי הלכתא ולא כסתם מתניתין:\",3,0],[8,381,4,10,\"ועדיין יש לדקדק בדברי רבינו שכתב מקוה שיש בו כ' סאה ומשהו מים כשרים והיה ממלא ושואב חוץ למקוה והמים נמשכים ויורדים וכו' הרי הוא כשר ואפילו השלימו לאלף סאה שהשאובה שהמשיכוה כשירה אם היה רוב ארבעים סאה מן הכשר ומשמע דהא כראב\\\"י אתיא דאמר מקוה שיש בו כ\\\"א סאה וכו' פותקן למקוה ואח\\\"כ כתב וכן גג שהיה בראשו כ' סאה ומשהו מי גשמים וכו' שהשאובה שהמשיכוה כולה כשירה ומשמע דהיינו כרבנן וכדאמר רבין שהמשיכוה כולה כשירה והיאך רבינו מזכי שטרא לבי תרי דמעיקרא פסק כראב\\\"י והדר פסק כרבנן. ונ\\\"ל שרבינו סובר דה\\\"פ דשמעתא התם מדקאמרה מאן תנא דסבר אין מים שאובים פוסלים את המקוה אלא לפי חשבון ראב\\\"י היא משמע דאיכא רבנן דפליגי עליה דראב\\\"י ואמרו דמים שאובים פוסלים את המקוה שלא לפי חשבון כלומר דאפילו קדמו רוב כשרים והמשיך לתוכן י\\\"ט סאין שאובין פסלי א\\\"כ הא דקאמר רבין שאובה שהמשיכוה כולה כשירה כלומר שאם היו כ\\\"א סאה מי גשמים ועירה י\\\"ט סאין שאובין בלא המשכה שנפסלו כולם ואח\\\"כ המשיכם כולם למקום אחר כשרים כמאן דלא כרבנן דהא לא מכשרי שאובה ע\\\"י המשכה כלל ודלא כראב\\\"י דאם איתא דהוה מכשר בה אם איתא דרבנן פליגי עליה לא הוה שתיק מינה כי היכי דלא נימא דעד כאן לא אכשר אלא כשהמשיך הי\\\"ט שאובים לתוך הכ\\\"א כשרים שלעולם היו הכשרים בכשרותם אבל היכא שעירה השאובים לתוך הכשרים בלא המשכה שנפסלו הכשרים מודה לרבנן דפסלי [אפילו המשיכם אח\\\"כ] הילכך ע\\\"כ לומר דליכא מאן דפליג על ראב\\\"י ואע\\\"ג דמשמע דיחידאה איתמר איכא דכוותה בפרק ארבע מיתות דהשתא רבין אגמרן דאע\\\"ג דמדברי ראב\\\"י לא משמע דשרי אלא בשהמשיך י\\\"ט שאובים לתוך כ\\\"א כשרים הוא הדין דשרי בעירה הי\\\"ט שאובים בלא המשכה ואחר כך המשיך את כולם דהא איכא למימר שאע\\\"פ שבעת שעירה הי\\\"ט שאובים בלא המשכה נפסל הכל מ\\\"מ כיון שהמשיך הכל כשרים ופסולין יחד עדיף טפי מהיכא דלא המשיך אלא הי\\\"ט שאובים בלבד הילכך שני דינים הללו שקולים ונקט חד מינייהו ולא חש למינקט אידך משום דכיון דליכא מאן דפליג עליה שפיר ילפינן חד דינא מחבריה. אי נמי ה\\\"פ הא ודאי דרבנן פליגי אראב\\\"י מדנקיט לה בלישנא דיחידאה ואי כדקאמרת מאן תנא דאמר אין מים שאובים פוסלים את המקוה אלא לפי חשבון ראב\\\"י משמע דרבנן דפליגי אראב\\\"י לחומרא פליגי וכמ\\\"ש לעיל וא\\\"כ דרבין דלא כמאן דלא כראב\\\"י דהא ע\\\"כ לא שרי ראב\\\"י אלא בשעירה הי\\\"ט שאובים לתוך הכ\\\"א כשרים בדרך המשכה ולא בשעירה אותם שלא כדרך המשכה שכבר נפסלו ושוב לא תועיל בהם המשכה הילכך ע\\\"כ לומר דרבנן דפליגי אראב\\\"י לקולא פליגי ושרו אפילו בשעירה הי\\\"ט שאובים בלי המשכה אע\\\"פ שנפסלו כולם כיון שחזר והמשיכן הוכשרו מאחר דאיכא רבייה והמשכה ופוסק רבינו כרבנן דרבים נינהו וגם דרבין אמר ר\\\"י אתי כוותייהו ולפיכך כתב תחילה דהיכא דהמשיך הי\\\"ט שאובים דכשר דכ\\\"ע מכשרי בה ואח\\\"כ כתב שאפילו עירה הי\\\"ע שאובים בלא המשכה שנפסל הכל אם חזר והמשיך הכל הוכשר כרבנן דפליגי אראב\\\"י וכדרבין וזה נראה עיקר:\",4,0],[8,381,5,1,\"מקוה שנפלו אליו שלשה לוגין מים שאובים וכו' עד מצטרף לשלשה לוגין. בפ\\\"ג דמקואות מכלי אחד משנים משלשה מצטרפין מד' אין מצטרפין בד\\\"א בזמן שהתחיל השני עד שלא פסק הראשון ובד\\\"א בזמן שלא נתכוון לרבות אבל אם נתכוון לרבות אפילו קורטוב בכל השנה מצטרפין לשלשה לוגין ומשמע לי דנתכוון לרבות היינו שכשהוא מטיל אותם מים שאובים למקוה הם על דעת לרבות מי המקוה שיהיו בו מים בשפע ולא יחסר על ידי טבילות שיטבלו בו אז מצטרפין אפילו קורטוב בכל שנה אבל אם לא הטיל על דעת זו בזה אמרו מד' אין מצטרפין והטור ורבינו ירוחם פירשו בע\\\"א:\",1,0],[8,381,5,1,\"ומ\\\"ש בין שקדמו השאובים וכו'. בפ\\\"ב דמקואות וכחכמים דאמרי בין בתחילה בין בסוף שיעורה ג' לוגין:\",2,0],[8,381,5,1,\"ומ\\\"ש כיון שנפלו ג' לוגין מים שאובים לתוך מ' סאה נפסל הכל ונעשה שאוב. נראה כסותר למ\\\"ש בפ\\\"ד מקוה שיש בו ארבעים סאה מים שאינם שאובים ושאב בכד ושפך לתוכו כל היום כולו כשר וכ\\\"כ עוד בספ\\\"ו ומשמע מדבריו שם דאפילו בשאב ושפך על דעת לרבות מי המקוה קא מכשר ושמא י\\\"ל דלתוך ארבעים סאה דנקט הכא כשהם ארבעים סאה עם השלשה שאובים שנפלו איירי אבל אם היו מ' סאה שלמים מים כשרים כולם לא נפסלו במים שאובים שנפלו לתוכן וכיוצא בזה פירש רבינו שמשון התוספתא דקתני שתי בריכות של מ' מ' סאה זו ע\\\"ג זו ונפלו שלשה לוגין מים לעליונה ונפתקו ובאו לתחתונה כשרים שאני אומר שלמו מ' סאה עד שלא ירדו שלשה לוגין וכיוצא בזה כתב רבינו בפ\\\"ב דערלה שפירש הירושלמי מתניתין הערלה מעלה את הכלאים כיצד סאה ערלה שנפלה למאתים:\",3,0],[8,381,5,2,\"שנים שהטילו זה לוג ומחצה וכו'. משנה פ\\\"ג דמקואות וכחכמים:\",1,0],[8,381,5,2,\"ומ\\\"ש גבי סוחט כסותו והגביהה. הוא מדתנן בפ\\\"ז דמקואות גבי מקוה שיש בו מ' סאה מכוונות וכו' הטביל בו את הסגוס והעלהו ומקצתו נוגע במים טהור פירוש סגוס בגד עב של צמר והרבה מים נבלעים בו וכל זמן שמקצתו במים אין המים שבתוכו נחשבים שאובים כל זמן שלא העלהו לגמרי מן המים וטהור המקוה אבל אם העלהו כולו מים שבתוכו שאובים והמקוה נחסר והמים שמתמצים מתוכו למקוה פוסלין אותו הרי שכל זמן שמקצתו נוגע במים אין המים שבתוכו נחשבים כשאובים:\",2,0],[8,381,5,3,\"המטביל כר וכו'. פרק ז' דמקואות.\",1,0],[8,381,5,3,\"ומה שכתב אבל הקופה והשק וכו'. שם בפרק ו':\",2,0],[8,381,5,4,\"מקוה שיש בו ג' גומות וכו'. בפ\\\"ג דמקואות וכת\\\"ק וכתב הר\\\"ש משמע דדוקא שידוע אבל ספק פסול:\",1,0],[8,381,5,5,\"שני מקואות אין בכל אחד מהן מ' סאה וכו' אבל מקוה שאין בו ארבעים סאה וכו'. שם רפ\\\"ג ודלא כרבי יהושע אלא כרבי יוסי וכחכמים:\",1,0],[8,381,5,6,\"בור שהוא מלא מים שאובים וכו'. שם:\",1,0],[8,381,5,6,\"ומ\\\"ש מקוה שיש בו עשרים סאה מי גשמים וכו' וכן אם עשה מקוה וכו'. שם גבי מקוה שאין בו ארבעים סאה ונפלו לו שלשה לוגין מים שאובים וחכ\\\"א לעולם הוא בפיסולו עד שיצא ממנו מילואו ועוד כיצד הבור שבחצר ונפלו לו שלשה לוגין לעולם הוא בפיסולו עד שיצאו מלואו ועוד או עד שיעמיד בחצר מ' סאה ויטהרו העליונים מן התחתונים ר\\\"א בן עזריה פוסל אא\\\"כ פסק ופירש רבינו שמשון שיעמיד בחצר ארבעים סאה מקוה כשר למטה מהפסול ופותקו לכשר כדי שיתחברו ויטהר העליון הפסול מן התחתון הכשר כר\\\"מ בספ\\\"ב דחגיגה דאית ליה גוד אסיק וכ\\\"ש אם הכשר למעלה ור\\\"א פוסל דלית ליה גוד אסיק ואפשר דאפילו גוד אחית נמי לית ליה כרבנן דאמרי בתוספתא אין מטבילין לא בתחתונה ולא בעליונה אא\\\"כ פסק שפסקו מימיו ויצאו ממנו מילואו ועוד עכ\\\"ל. ורבינו נראה שפוסק כרבנן דלית להו אפילו גוד אחית לענין מקואות ולפיכך סתם וכתב וכן אם עשה מקוה שיש בו ארבעים סאה מים כשרים ועירבו עם המקוה הזה הפסול טהרו אלו את אלו ולא כתב שאפילו הוא עליון או תחתון כשר ואע\\\"פ שיש לדחות שסתם דבריו לומר דבכל ענין כשר בפ\\\"ח גבי ג' גומות שבנחל יתבאר דלית ליה גוד אחית ואהא דתנן והאמה נכנסת לו ויוצאה ממנו פירש רש\\\"י דהיינו חרדלית של גשמים כלומר דאילו היתה אמת המים נובעין אפילו אינה אלא כל שהוא היתה מטהרת את המים השאובים שבבור:\",2,0],[8,381,5,7,\"המסלק את הטיט לצדדין וכו'. בפ\\\"ב דמקואות וכת\\\"ק:\",1,0],[8,381,5,8,\"גייס העובר ממקום למקום וכו'. תוספתא דמקואות פ\\\"ג ר' יוסי אומר זילף בידיו וברגליו שלשה לוגין למקוה פסול הוליכו עם הקרקע כשר לגיון העובר ממקום למקום וכן שיירא העוברת ממקום למקום וזלפו בידיהם וברגליהם שלשה לוגין למקוה כשר ולא עוד אלא אפילו עשו מקוה בתחילה כשר ופירש הרא\\\"ש לגיון הוא חיל רוכבי סוסים וכן שיירא ואם עשו מקוה ברגלי בהמות כשר אבל אדם שזילף בידיו או ברגליו שלשה לוגין למקוה חסר פסלו עכ\\\"ל אבל מדברי רבינו שמשון נראה שאינו מחלק בין אדם לבהמה שכתב וזילפו בידיהם וברגליהם שלשה לוגין למקוה כשר אבל עם הקרקע קאמר ובמה ששנינו הוליכו עם הקרקע פירש דהיינו המשכה שמערה חוץ למקוה והם נמשכים למקוה ע\\\"כ ולפי זה הא דתניא ולא עוד אלא אפילו עשו מקוה בתחילה כשר כמאן דאמר שאובה שהמשיכוה כולה כשירה אתיא אבל למאן דלא מכשר אלא כשהמשיך רובא ליתא להאי תוספת' ורבינו משמע לו שהוא מפרש התוספתא שהעבירו על גבי קרקע או שניתנו ע\\\"י דריסת רגלי אדם או בהמה כשר שאין חילוק בין אדם לבהמה לענין זה וצ\\\"ל דהא דאמר רבי יוסי זילף בידיו וברגליו שלשה לוגין למקוה פסול מפרש רבינו דלא ע\\\"י נתיזה היה אלא שנטל בידיו וברגליו שלשה לוגין והטילן למקוה ולפי שהיה מפרש כן לא הוצרך לכתוב דברי ר\\\"י דמדין המסלק את הטיט הוא נלמד:\",1,0],[8,381,5,9,\"מקוה שאין בו ארבעים סאה וכו': כתב הראב\\\"ד ופסולים להקוות עליהם א\\\"א זה שיבוש אלא כשרים להקוות עליהן וכו'. ובאמת שכדברי הראב\\\"ד כתב ר\\\"ש בתוספתא דמקואות פ\\\"ק כי שם הוא מקום דינים אלו דקתני גבא שאין בו ארבעים סאה ונפל לתוכן פחות משלשה לוגין מים טמאים פסולים לחלה ולתרומה וליטול מהם לידים וכשרים להקוות עליהם, ירדו גשמים רבו ושטפו כדברי בית שמאי ובית הלל אומרים רבו אע\\\"פ שלא שטפו וכדברי ר\\\"ש שטפו אע\\\"פ שלא רבו כשרים לחלה ולתרומה וליטול מהם לידים וכשרים להקוות עליהם וכיצד רבו אע\\\"פ שלא שטפו כדברי בית הלל מקוה שהוא מחזיק ארבעים סאה ובתוכו י\\\"ט סאה ונפל לתוכו פחות משלשה לוגין מים שאובים טמאים כיון שנפל לתוכו כ\\\"א סאה של מי גשמים טהורים מפני שרבו וכיצד שטפו אע\\\"פ שלא רבו כדברי ר\\\"ש מקוה שהוא מחזיק כ' סאה ובתוכו י\\\"ט סאה ונפלו לתוכו פחות משלשה לוגין מים שאובים טמאים כיון שנפל לתוכו סאה אחת של מימי גשמים טהורים מפני ששטפו וכמה שטפו כל שהן, נפלו לתוכו שלשה לוגין מים שאובים טמאים פסולים לחלה ולתרומה וליטול מהם לידים ופסולין להקוות עליהן וירדו גשמים ושטפו כדברי בית שמאי וכדברי בית הלל רבו אע\\\"פ שלא שטפו וכדברי ר\\\"ש שטפו אע\\\"פ שלא רבו כשרים לחלה ולתרומה וליטול מהם לידים ופסולים להקוות עליהם עד שיצא ממנו מילואו ועוד אי זהו מילואו ועוד מקוה שהוא מחזיק עשרים סאה ובתוכו י\\\"ט סאה ונפלו לתוכו שלשה לוגין מים שאובים טמאים, רבו מי גשמים ונתמלאו לעולם הוא בפיסולו עד שיצא ממנו מילואו ועוד דבר מועט למעט שלשה לוגין. מקוה שיש בו ארבעים סאה חסר קורטוב ונפלו לתוכו שלשה לוגין מים שאובים טמאים פסולים לחלה ולתרומה וליטול מהם לידים ופסולין להקוות עליהם, פחות משלשה לוגין אפילו כולם טמאים כיון שנפל לתוכו קורטוב אחד של מימי גשמים טהורים וכשם שטהורים לטבילה כך טהורים לכל דבר ע\\\"כ לשון התוספתא. ורבינו נראה שהיה גורס בבא דרישא נמי פסולים להקוות עליהם ואע\\\"פ שפחות משלשה לוגין מים שאובים אינם פוסלים את המקוה וא\\\"כ כשרים להקוות עליהם שאני הכא דהני פחות משלשה לוגין מים שאובים הוו טמאים ולפיכך הם פסולים להקוות עליהן ומיהו ה\\\"מ כשלא רבו הכשרים הנקוים עליהם כגון שהיו במקוה כ' סאה או יותר מים כשרים כשנפלו הפחות משלשה לוגין מים שאובים טמאים דכיון דכי מקוה עלייהו להשלימם לשיעור מקוה אין מים האחרונים רבים על הראשונים נפסלו ואפילו מרבה מים יותר ממה שצריך לשיעור מקוה דלא חשיבא רבייה אלא במאי דצריך לשיעור מקוה אבל אם מים כשרים שהיו במקוה בעת שנפלו הפחות משלשה לוגין הללו היו פחותים מכ' סאה דהשתא כי מקוה עלייהו להשלימם לשיעור מקוה הוו מים בתראי רבים על מים דהוו ברישא כשר. וה\\\"פ דרבינו מקוה שאין בו מ' סאה וכו' כלומר יש בו מים כשרים שיעור חצי מקוה או יותר ונפל לתוכו פחות משלשה לוגין מים טמאים שאובים פסולים להקוות עליהם, ירדו עליהם גשמים ורבו עליהם כלומר אבל אם שיעור המים הראשונים היה מועט עד שכשירדו גשמים וישלימו למ' סאה נמצא שמים אחרונים רבים על הראשונים כשרים. כנ\\\"ל לפרש למימרא דבדוקא נקטה תוספתא מקוה שהוא מחזיק ארבעים סאה אלא דאי הוה ס\\\"ל לרבינו הכי לא היה סותם דבריו לפיכך נראה דבכל ענין שרבו מים אחרונים על מים ראשונים הוכשרו. ובין כך ובין כך לישנא דנקט רבינו גבי ירדו עליהם גשמים וכו' כשרים להקוות עליהם אינו נוח לי ומאי להקוות עליהם דקאמר הכי הל\\\"ל כשרים לטבול בהם. ואפשר דמשום דלא פסיקא ליה מילתא שיהא בהם מ' סאה דהא אפשר דמים קמאי הוו מועטים שאפילו עם מים אחרונים שרבו עליהם אין שם מ' סאה לפיכך כתב כשרים להקוות עליהם לומר דמים טמאים שנפלו בו נתבטלו וממילא משמע שאם יש שם ארבעים סאה כשר לטבול בו:\",1,0],[8,381,5,9,\"ומ\\\"מ קשה דקתני סיפא מקוה שיש בו ארבעים סאה חסר קורטוב ונפלו לתוכו פחות משלשה לוגין אפי' כולם טמאים כיון שנפל לתוכו קורטוב של מי גשמים טהורים לטבילה ולכל דבר והא קתני רישא דכל שלא רבו מים אחרונים על הראשונים פסולים וצ\\\"ל שרבינו מפרש דשאני לן בין מקוה שאין בו מ' סאה כלומר שאין בו אלא ל\\\"ט או פחות למקוה שיש בו ארבעים סאה חסר קורטוב דכיון שיש עליו שם מ' סאה לא פסלוהו כלל פחות משלשה לוגין מים טמאים:\",2,0],[8,381,6,1,\"כל הכלים המקבלים וכו'. ריש פרק רביעי דמקואות:\",1,0],[8,381,6,2,\"כל כלי שלא נעשה לקבלה וכו'. שם סילון שהוא נראה מכאן ומכאן ורחב באמצע אינו פוסל מפני שלא נעשה לקבלה:\",1,0],[8,381,6,3,\"השוקת שבסלע וכו'. משנה שם השוקת שבסלע וכו' אינה פוסלת את המקוה היתה כלי וחיברה בסיד וכו' פוסלת את המקוה ניקבה מלמטה או מן הצד ואינה יכולה לקבל מים כל שהו כשירה וכמה יהא בנקב כשפופרת הנאד אמר רבי יהודה בן בתירא מעשה בשוקת יהוא שהיתה בירושלים והיתה נקובה כשפופרת הנאד והיו כל טהרות שבירושלים נעשות על גבה ושלחו ב\\\"ש ופחתוה שב\\\"ש אומרים עד שיפחת רובה ופירש הרא\\\"ש השוקת שבסלע שחקקוה בסלע ואינה חשובה כלי הואיל ומתחלתה נחקקה בסלע וה\\\"ה אם קבע האבן וחיברו בקרקע ואח\\\"כ חקקו כדאיתא בפרק המוכר את הבית אבל אם היתה כלי ואח\\\"כ חיברה חשובה כלי ופוסלת את המקוה. כמה יהא בנקב פשטא דמתניתין קאי אמאי דסליק מינה כמה יהא בנקב לבטלו מתורת כלי שלא יפסול את המקוה מחמת שאיבה ומייתי עובדא דשוקת יהוא שהיתה נקובה כשפופרת הנאד כדי שלא יפסלו המים המקלחים בתוכם אבל בפ\\\"ק דיבמות (דף ט\\\"ו) מייתי הך דשוקת יהוא על ענין עירוב מקואות כשפופרת הנאד ומשמע שלא היו ארבעים סאה בשוקת והיה מחובר למקוה שלם בנקב כשפופרת הנאד ומילתא באפי נפשה היא ולא קאי ארישא אבל ניקבה דרישא לא בעי כשפופרת הנאד כיון שהנקב הוא למטה בשוקת ואינה יכולה לקבל מים כ\\\"ש נתבטלה מתורת כלי ובתוספתא פליגי תנאי בהא דתניא קסטלין המקלח מים בכרכים אם היה נקוב כשפופרת אינו פוסל את המקוה ואם לאו פוסל את המקוה הלכה זו עלו בני אסיא שלשה רגלים ולרגל השלישי הכשירו להם אפילו נקב כמחט אמר ר\\\"א ברבי יוסי הלכה זו הוריתי ברומי לטהרה וכשבאתי אצל חבירי אמרו לי יפה הורית בד\\\"א מן הצד אבל מלמטה אינו פוסל את המקוה ואם היה מקבל כל שהו מן הנקב ולמטה פוסל את המקוה פירוש כל זה מדברי חביריו שאמרו לו יפה הורית דבד\\\"א דבעינן כשפופרת הנאד מן הצד אבל אם ניקב בשוליו אינו פוסל אם ניקב כמלא מחט ואם היה מקבל כל שהוא פי' שנקוב מן הצד כשפופרת הנאד וגבוה מעט מהשוליים ומקבל מן הנקב ולמטה מים כל שהו פוסל את המקוה וסוגיא דיבמות במקומה ההיא דשוקת יהוא בעירוב מקואות ס\\\"ל כתנא דסבר מלמטה מהני נקב כל שהוא הילכך צריך לשנות פשטא דמתניתין ולומר דמילתא באפי נפשה היא ולא קאי ארישא וכתב ר\\\"מ נראה דהלכה כר\\\"א ברבי יוסי דמעשה רב וחביריו נמי הודו לו דיפה הורה וסתמא דגמרא מייתי לההיא דשוקת יהוא לענין עירוב מקואות אלמא לא קיימא אניקבה מלמטה לענין כלי המקוה דהתם לא בעינן כשפופרת אלא כמלא מחט וכר\\\"א ברבי יוסי וכן בפסקי רבינו שמחה בניקבה למטה בשוליה שאין יכול לקבל מים לא בעינן כשפופרת הנאד וכן הביא רבינו שמשון ראיה מן התוספתא דלמטה בשוליה סגי בנקב כל שהוא ולמדנו מזה שמותר לעשות גיגית גדולה של עץ או שוקת אבן ויעשה למטה בשוליים נקב כל שהו ויושיבנה על הארץ וימשוך לתוכה מים ויטבול בה עכ\\\"ל:\",1,0],[8,381,6,3,\"ומ\\\"ש יושיבנה על הארץ. כך מפורש בתוספתא דקתני עלה ההיא דר\\\"א ברבי יוסי פקקו בסיד ובבנין אינו פוסל את המקוה בסיד ובגפסיס פוסל את המקוה על גבי הארץ ועל גבי סיד וגפסיס או שמירחו בטיט מן הצדדין אינו פוסל את המקוה ופירש רבינו שמשון והרא\\\"ש בסיד ובבנין שהביא סיד וצרורות ופקק בו הנקב לא חשיבא סתימה אבל בסיד וגפסיס יחד חשיבא סתימה מעלייתא וחשיב כלי הושיבו על גבי הארץ כלומר לא סתם הנקב אלא הושיבו על הארץ כדי שלא יצאו המים או על גבי סיד וגפסיס או שמירח הנקב מן הצדדים אכתי לא הוי כלי ואינו פוסל את המקוה:\",2,0],[8,381,6,3,\"ומתוך דברי רבינו שכתב כאן משמע לי שהוא מפרש מתניתין כפשטא דכמה יהא בנקב קאי למאי דסליק מיניה דהיינו לענין לבטלו מתורת כלי שלא יפסול המקוה מחמת שאיבה קאמר כמה יהא בנקב כשפופרת הנאד ולפ\\\"ז צ\\\"ל בההיא דפ\\\"ק דיבמות דתרי שוקת יהוא היו בירושלים חדא שהיו מטבילים בתוכה ולא היה בה מ' סאה אלא על ידי עירובה עם מקוה שבצדה על ידי נקב שביניהם ועוד שוקת יהוא אחרת היתה שהיו המים נמשכים בה ויורדים למקוה ועשו בה נקב לבטלה מתורת כלי והיינו הך דתנן במסכת מקואות ושיעורא דנקב דעירוב מקואות ושיעורא דלבטלו מתורת כלי שוים הם דבתרווייהו הוי כשפופרת הנאד ואע\\\"ג דבתרווייהו קתני כל טהרות שהיו בירושלים נעשות על גבה אין למדין מן הכללות וקצת הטהרות היו נעשות בשוקת זו ובזמן אחר היו כל הטהרות נעשות בשוקת זו ואף אם נאמר דדא ודא אחת היא ובין הכא ובין התם לא לענין עירוב מקואות מיתניא אלא לענין נקב המבטלה מתורת כלי וכפשטא דמתניתין דמסכת מקואות והא דקאמר עלה התם ותנן עירוב מקואות כשפופרת הנאד בעביה ובחללה כשתי אצבעות חוזרת למקומן לא מייתי לה אלא ללמוד ממנה שיעורא דשפופרת הנאד כמה הוי ולא לומר דההיא דשוקת מיתניא לענין עירוב מקואות כלל:\",3,0],[8,381,6,4,\"ומ\\\"ש רבינו הלוקח כלי גדול כגון חבית גדולה וכו'. נראה שטעמו מההיא דתניא בתוספתא קסטלין המחלק מים בכרכים והוא ז\\\"ל מפרש דקסטלין היינו שדרך כרכים להניח במקום מוצא המים חבית גדולה או עריבה גדולה של חרס ושם מתכנסין כל המים הבאים לכרך ומשם יפרדו לקלח המים לכל מעיינות הכרך וסובר ז\\\"ל דהלכה כר\\\"א ברבי יוסי כיון שהודו לו חביריו וסובר עוד דמאי דאמר ר\\\"א ברבי יוסי הלכה זו הוריתי ברומי לטהרה פירושו הוריתי דשיעור נקב דקסטלין להכשירו למקוה יהא כשיעורו לטהרה דהיינו כמוציא זית שזהו שיעור המטהר לכלי חרס מידי טומאה לגמרי כמבואר בדבריו פרק י\\\"ט מהלכות כלים. ומה ששנינו בתוספתא בד\\\"א מן הצד וכו' סיומא דמילתא דת\\\"ק הוא ואינו ענין לדברי ר\\\"א ברבי יוסי ומשמע ליה ז\\\"ל דלענין לטבול בתוכו איתניא תוספתא ולהכי נקט קסטלין שהוא כלי דסתמו שהוא מחזיק מים מרובים שיש בהם כדי לטבול בתוכו ולפיכך כתב ה\\\"ז כשר ללמדנו דלהטביל ולטבול בתוכו נמי כשר וגבי סתמו בסיד או בגפסיס כתב עדיין הוא פוסל את המקוה כלישנא דתוספתא לאשמועינן דלא מיבעיא דאין טובלים בתוכו אלא מיפסל נמי פסיל את המקוה דכיון דאכתי כלי הוא הוה ליה מים שאובים ופוסלים את המקוה וכל היכא דאין מימיו פוסלים את המקוה משום דלא חשיב כלי כשר לטבול בו וכן מ\\\"ש בסמוך אבל כלי שחיברו בסלע פוסל את המקוה ניקבה מלמטה או מן הצד כשפופרת הנאד כשירה ואינה פוסלת את המקוה היינו לומר דכיון דניקב כשפופרת הנאד לא חשיב כלי וכשר לטבול בו ואצ\\\"ל שאינו פוסל את המקוה. ואם תאמר הרי שם כתב כלי סתם ואף כלי חרס במשמע והצריך בו שיהא בנקב כשפופרת הנאד והיכי מכשר ביה הכא בנקב המטהרו דהיינו במוציא זית וי\\\"ל דהתם שאני שחיבר הכלי בסלע בעודו שלם כדמשמע מדבריו שמאחר שהיה שלם בשעה שחיברו בסלע לא נתבטל שלימותו עד שינקוב נקב כשפופרת הנאד אבל הכא שניקבו ואח\\\"כ קבעו וכדקתני ונקבו וקבעו בארץ כיון שניקב נקב המטהרו מידי טומאה ובטל שם כלי מיניה קודם שקבעו שפיר דמי א\\\"נ דכלי שקבעו בסלע דקאמר בכלי אבנים דומיא דשוקת דנקט ברישא ומשום דכלי אבנים אינם מקבלים טומאה לא שייך לשעורי בהו בכדי טהרה הלכך משערינן בהו כשפופרת הנאד אי נמי אפי' אם ת\\\"ל דכלי שחיברו בסלע כל כלי במשמע ואפי' כלי חרס איכא למימר דגזרו ביה משום דשוקת שבסלע כשירה בלא שום נקב ואיכא למיחש דאתו למיטעי ולאכשורי בכלי שחיברו בסלע בלא שום נקב ולפיכך הצריכו בכלי שחיברו בסלע לעשות נקב גדול כשפופרת הנאד כי היכי דליהוי היכרא במילתא ומ\\\"ש אח\\\"כ השידה והתיבה שבים אין מטבילין בהם אא\\\"כ היו נקובים כשפופרת והיא משנה בפ\\\"ז דמקואות הטעם שלא הצריכו בהם נקב המטהרם כמו שאמרו בכלי חרס נראה דהיינו משום דכלי חרס שאני דשיעור המטהרם הוי בציר משפופרת הנאד הילכך כיון דבטל שם כלי מינייהו בנקב במוציא זית בהכי סגי אבל בשידה ותיבה שהם כלי עץ ששיעור המטהרן גדול מאד שהוא במוציא רמון ראו חכמים דלבטלו מתורת כלי לענין מקוה דלא סגי ליה בכשפופרת הנאד שהוא שיעור המספיק לענין עירוב מקואות דאע\\\"ג דלבטלו מכלי לענין טומאה צריך שהיה נקב יותר גדול דלשיעורא דלטומאה וטהרה לחוד ושיעורא דלענין מקואות לחוד:\",1,0],[8,381,6,4,\"ומ\\\"ש וכן אם פקק את הנקב בסיד ובבניין אינו פוסל וכו'. מבואר שכל זה מהתוספתא שהבאתי לעיל אלא שרבינו ז\\\"ל מפרש דתוספתא אשמעינן דלאכשורי מים שבחבית או עריבה של חרס הללו תרתי בעינן חדא דנוקב נקב המטהרו דהיינו במוציא זית ועוד צריך שיקבענו בארץ דומיא דקסטלין או שיהיה בו הוכחה שהוא דבר של בניין ולא דבר של כלי או שיורי כלי ומש\\\"ה קתני שאם פקקו בסיד ובבניין כלומר בצרורות וכיוצא בהן כעין בנין לא חשיב כלי כלל ולפיכך אינו פוסל את המקוה וה\\\"ה דכשר לטבול בו אלא איידי דבעי למינקט סיפא פוסל נקט רישא אינו פוסל אבל כשסתמו בסיד או בגפסיס לבד כיון דאין דרך בנין באלו לבדם בלא אבנים או צרורות נמצא שחיסר אחד מהתנאים הצריכים לבנין הלכך עדיין שם כלי או שיורי כלי עליו ופוסל את המקוה כמו שהיה פוסל קודם שסתמו ובתר הכי קתני שאע\\\"פ שלא קבעו בארץ דהיינו קבורה בארץ כדרך הקסטלין וגם לא בנאו בצרורות אלא שהושיבו על הארץ ומירח מן הצדדין בטיט להדביק הכלי לארץ כשר ולא מיבעיא אם הושיבו על הארץ אלא אפי' הושיבו על גבי סיד וגפסיס ומירח בטיט מן הצדדין להדביקו לסיד וגפסיס כשר שמאחר שהסיד והגפסיס על הארץ הם עומדות כארעא סמיכתא נינהו וכל שמירח מן הצדדין בטיט חשיב כקבוע וכשר ואע\\\"פ שכתוב בתוספתא או שמירחו מפרש לה רבינו כאילו כתוב ומירחו ואפשר שכך היתה גירסתו בתוספתא. ומ\\\"מ איכא למידק אמאי כתב והוליכו על גבי הארץ וכו' ולא כתב והניחו על גבי הארץ ולפיכך נראה שאפשר לפרש דה\\\"ק אם גרר על גבי הארץ או על גבי הסיד ונסתם הנקב מחמת שנדבק בו באותה גרירה ואח\\\"כ מירח בטיט מן הצדדין כלומר סביבות הנקב כדי להעמיד מה שנדבק בו בשעת גרירה כשר והשתא הוי שפיר כבנין שמה שנדבק בו ע\\\"י הגרירה הוי כצרורות ומירוח הטיט הוי במקום סיד שטחין בבנין ומש\\\"ה כשר כנ\\\"ל לפרש לדעת רבינו:\",2,0],[8,381,6,4,\"וכתב הראב\\\"ד ועשאהו מקוה הרי זה כשר א\\\"א דבר זה אינו מחוור להטביל וכו'. ואני אומר שמ\\\"ש רבי יהודה אומר בכלי גדול ארבעה טפחים וכו' הוא במשנה השידה והתיבה שבים שכתבתיה ואתא לאפלוגי את\\\"ק דאמר כשפופרת הנאד:\",3,0],[8,381,6,4,\"ומ\\\"ש שהשידה והתיבה בכלי מנוקב בכדי טהרתו הוא, איני יודע לו טעם דהא סתם שידה ותיבה דעץ נינהו וכלי עץ שיעור טהרתן בכמוציא רמון והוי טפי טובא מכשפופרת הנאד דמכשר ביה ת\\\"ק:\",4,0],[8,381,6,4,\"ומ\\\"ש איך אפשר שלא יהא בקרקעיתו ודפנו חרס הראוי לקבל טומאה וכו' ונמצאת טבילה זו בכלים. יש לתמוה עליו אם טענה זו תספיק לשוויינהו כלים לענין דטבילה בתוכו הויא טבילה בכלים למה לא תועיל לפסול המקוה במים היוצאים ממנו דחשיבי מים היוצאים וכיון דחזינן דלפסול את המקוה לא חשיבי כלים ה\\\"ה דלטבול בתוכו לא חשיבי כלים דמהי תיתי לן לפלוגי בינייהו מיהו בהא איכא למימר דלטעמיה אזיל שסובר שהמים העוברים בכלים ויוצאים חוצה לו אע\\\"פ שפסולים לטבול בהם אם נפלו למקוה לא פסלוהו אבל קשה שלא היה לו להקשות מסברתו לרבינו ועוד דלפי דבריו כי ניקב כשפופרת הנאד נמי לא הוה לן למישרי למיטבל בגויה מההוא טעמא גופיה דאיך אפשר שלא יהא בקרקעיתו ודפנו חרס הראוי לקבל טומאה על ידי יחודו אלא ודאי אע\\\"פ שאילו יחדו להשתמש בו היה בקרקעיתו חרס הראוי לקבל טומאה כיון שלא יחדו להשתמש בו אין עליו תורת כלי:\",5,0],[8,381,6,6,\"המניח טבלא תחת הצינור וכו'. משנה פ\\\"ד דמקואות ופירש ר\\\"ש אם יש לזבז מד' רוחותיה דאי משלש אין זה בית קיבול:\",1,0],[8,381,6,6,\"החוטט בצינור וכו' עד ה\\\"ז כשר. שם וכת\\\"ק:\",2,0],[8,381,6,6,\"ומ״ש ואפי' קבעו אחר שחקק בו וכו'. בפרק המוכר את הבית (בבא בתרא דף ס״ה ע״ב) ובפרק מרובה (בבא קמא דף ס״ז):\",3,0],[8,381,6,7,\"הספוג והדלי וכו' עד כמו שביארנו. פרק ו' דמקואות. ופירש ר\\\"ש הספוג והדלי כשאין בהם שלשה לוגין בעין אא\\\"כ תצרף עמהם המים הדבוקים בהם וכיון שאין השלשה לוגין בעין לא מיקרי נפלו ולא גזור רבנן וכשר להקוות עליו והרא\\\"ש פירש הספוג שבלועים בו שלשה לוגין מים וכשנפלו למקוה נתערבו המים הבלועין בו עם מי המקוה וכן הדלי שפיו צר ובו שלשה לוגין מים שאובים ונפל למקוה ולא יצאו כל המים שבתוכו אלא נתערבו עם מי המקוה לא פסלוהו שלא אמרו אלא שלשה לוגין שנפלו ונתערבו כולם עם מי המקוה עכ\\\"ל:\",1,0],[8,381,6,8,\"השידה והתיבה שבים וכו' עד פוסלין את המקוה. משנה בפ\\\"ז דמקואות וכתב ר\\\"ש שק או קופה לא בעו נקיבה כשפופרת הנאד וכו' וכן בסל וגרגותני לא בעינן שיתערבו המים דרך פיו אלא אפי' אין מתערבין אלא דרך הנקבים שבתוכו בטלים מים שבתוכו אגב מי מקוה כיון דמלא נקבים ואין מחזיק מים כלל וכן מוכח בתר הכי עכ\\\"ל:\",1,0],[8,381,6,9,\"גיסטרא טמאה וכו' מעיין היוצא מן התנור טמא וכו'. גם זה משנה שם וכתב ר\\\"ש ושפתה למעלה מן המים ואפ\\\"ה כיון דשבר כלי הוא בטלי מימיה אגב מקוה וכשרים להטביל בה כלים והרא\\\"ש כתב גיסטרא שבר כלי והיא טמאה ושפתה חוץ למים אלא שיש בה פגימות בשפתה כמו כלי חרס שנשבר שאין מקום השבר שוה ונכנסים המים לגיסטרא דרך אותם פגימות והכלי שהטביל טהרו מטומאתן כי מי המקוה מחוברים למים שבתוכה עכ\\\"ל:\",1,0],[8,381,6,10,\"חבית מלאה מים וכו'. פרק קמא דמכות (דף ד') אמר רב יהודה אמר רב חבית מליאה מים שנפלה לים הגדול הטובל שם לא עלתה לו טבילה חיישינן לשלשה לוגין שלא יהו במקום אחד ודוקא לים הגדול דקאי וקיימא אבל נהרא בעלמא לא ופירש\\\"י הטובל שם באותו מקום לא עלתה לו טבילה שמא כל מים שהיו בחבית עומדים יחד ושמא בא זה ראשו ורובו במים שאובים וזה אחד מהפוסלים את התרומה אבל מדברי רבינו משמע דלעניין עלייה מטומאה ע\\\"י טבילה זו קאמר וקשה שהרי כתב בפ\\\"ד מקוה שיש בו ארבעים סאה אפילו שאב ושפך לתוכו כל היום כולו כשר וסתם מקואות קוו וקיימי דומיא דים ואפ\\\"ה מכשיר ואפשר לדחוק ולומר דמשום בא ראשו ורובו במים שאובים קאמר דלא עלתה לו טבילה ולענין פיסול תרומה וכדפרישית ויותר נכון לומר דלעניין עלייה מטומאה ע\\\"י טבילה זו קאמר ושאני ההיא דפ\\\"ד שמתוך שבאו השאובים בדרך שפיכה הם מתערבים בכל מי המקוה ואין שם שלשה לוגין שאובים במקום אחד משא\\\"כ בחבית שנפלה דלאו דרך שפיכה אתא:\",1,0],[8,381,6,11,\"מים שאובים שהיו בצד המקוה וכו'. נראה שכתב כן מדתנן בפ\\\"ו דמקואות האביק שבמרחץ בזמן שהוא באמצע פוסל מן הצד אינו פוסל מפני שהוא כמקוה סמוך למקוה ואע\\\"ג דמסיים במתניתין וחכ\\\"א אם מקבלת האמבטי רביעית עד שלא יגיעו לאביק כשר ואם לאו פסול ר\\\"א ברבי צדוק אומר אם מקבל האביק כל שהוא פסול לא חש רבינו לדבריהם משום דס\\\"ל כתנא קמא:\",1,0],[8,381,6,12,\"שתי בריכות זו למעלה מזו וכו'. שם המטהרת שבמרחץ התחתונה מליאה שאובים והעליונה כשרים אם יש כנגד הנקב שלשה לוגין פסול כמה יהא בנקב ויהיה בו שלשה לוגין אחד משלש מאות ועשרים לבריכה דברי רבי יוסי ר\\\"א אומר אפילו התחתונה מלאה כשרים והעליונה מלאה שאובים ויש כנגד הנקב שלשה לוגין כשר שלא אמרו אלא שלשה לוגין שנפלו ופסק כרבי יוסי דנימוקו עמו ודבר פשוט הוא דלרבותא נקט רבי יוסי התחתונה מלאה שאובים לומר דאפי' הכי פוסלת וכל שכן היכא דעליונה שאובים והתחתונה כשרים וכבר נתבאר שאין המים השאובים פוסלים אלא בשאין בכשרים ארבעים סאה:\",1,0],[8,381,6,14,\"שלשה מקואות זה בצד זה. ג\\\"ז שם ומדקדוק דברי רבינו נראה שהוא סובר דהא דקתני המקואות טהורים היינו לומר שלא נפסלו בתערובת השאוב אבל השאוב בפיסולו עומד אבל בפירוש המשנה כתב שגם המקוה השאוב כשר מפני שהושק למ' סאה כשירים וכן דעת המפרשים וכן צריך לפרש דבריו פה:\",1,0],[8,381,7,1,\"אין המקוה נפסל לא בשינוי הטעם ולא בשינוי הריח. פרק כל הבשר (חולין דף ק״ו) מים שנפסלו מלשתות בהמה אין נוטלין אבל מטבילין ובפ״ק דשבת (דף י״ד) אמרינן שהיו טובלין במי מערות סרוחים:\",1,0],[8,381,7,1,\"ומ\\\"ש אלא בשינוי מראה לבד. פ\\\"ו דמקואות:\",2,0],[8,381,7,1,\"ומ״ש וכל דבר שאין עושין בו מקוה לכתחילה וכו'. בר״פ חבית (שבת דף קמ״ד ע״ב):\",3,0],[8,381,7,1,\"ומ\\\"ש כיצד היין וכו' אינם פוסלין את המקוה בשלשה לוגין וכו'. נלמד מדין שלשה לוגין חסר דינר מים שאובים שנפל לתוכן דינר חלב וכו' שכתב רבינו בס\\\"פ זה ובספ\\\"ק דחולין (דף כ\\\"ה ע\\\"ב) ובפ\\\"ז דמקואות תנן התמד משהחמיץ אינו פוסל את המקוה כלומר בשלשה לוגין:\",4,0],[8,381,7,1,\"ומ\\\"ש ופוסלים בשינוי מראה אפילו מקוה שיש בו ארבעים סאה וכו'. בפרק ז' דמקואות:\",5,0],[8,381,7,1,\"וכן מקוה שיש בו עשרים סאה וכו'. פשוט הוא שהרי אין כאן לא פיסול שינוי מראה ולא פיסול מים שאובים:\",6,0],[8,381,7,1,\"ומ\\\"ש ואין הסאה שנפלה עולה וכו'. טעמו משום דבפרק שביעי דמקואות לא משכח שיעלו מי פירות את המקוה אלא כשהיו בו ארבעים סאה ונתן סאה ונטל סאה:\",7,0],[8,381,7,4,\"ומ\\\"ש (בהל' ד') והשכר:\",1,0],[8,381,7,6,\"יש מעלים את המקוה וכו' עד הרי המ' שנשארו מקוה כשר. בפ\\\"ז דמקואות אלו מעלים ולא פוסלים השלג והברד והכפור והגליד והמלח וטיט הנרוק אר\\\"ע היה רבי ישמעאל דן כנגדי לומר השלג אינו מעלה את המקוה והעידו אנשי מידבא משמו שאמר להם צאו והביאו שלג ועשו מקוה בתחילה וסובר רבינו דבשלג דחזינן שהתיר רבי ישמעאל לעשות מקוה בתחילה הוא דמכשרינן ולא גמרינן מינה לאינך דאם איתא לא הוו שתקי מינה במשנה ובתוספתא ומדברי רש\\\"י משמע דאף שלג אם עשה ממנו מקוה שהוא פסול דהא דתנן מעלים את המקוה מעלין היינו משלימין אשלומי אין אבל בפני עצמו לא וא\\\"כ ת\\\"ק דמני שלג בהדי הנך דמעלין סבר דבפני עצמו לא ופליג אר' ישמעאל וקי\\\"ל כת\\\"ק ורבינו סובר דכרבי ישמעאל נקטינן משום דעבד מעשה ומעשה רב אי נמי דתנא קמא נמי כרבי ישמעאל סבר בשלג ומשום אינך נקט לישנא דמעלין:\",1,0],[8,381,7,6,\"וכתב הראב\\\"ד דשלג צריך למעכן ביד שיהא כעין הכפור והברד אבל התפוח וחלול כמות שהוא לא ונראה שלזה נתכוון רבינו שכתב וריסקו:\",2,0],[8,381,7,7,\"מקוה שהדיח בו וכו'. פ\\\"ז דמקואות:\",1,0],[8,381,7,8,\"ומה שכתב מי הצבע וכו'. שם בשם רבי יוסי ומשמע דליכא מאן דפליג עליה במקוה:\",1,0],[8,381,7,9,\"מקוה שנפל לתוכו יין וכו' עד הרי זה לא יטבול בו. שם:\",1,0],[8,381,7,9,\"ומה שכתב והטובל במקום שנשתנה לא עלתה לו טבילה. נלמד ממה שיבא בסמוך:\",2,0],[8,381,7,9,\"ומ\\\"ש אפילו חבית של יין וכו'. תוספתא פ\\\"ה דמקואות:\",3,0],[8,381,7,9,\"כתב הראב\\\"ד לא עלתה לו טבילה א\\\"א בתוספתא הטובל בין במקום היין. ופשוט הוא במשנה פ\\\"ז דמקואות ומבואר בדברי רבינו:\",4,0],[8,381,7,11,\"שלשה לוגין מים שאובים וכו' עד ולא מי פירות. שם וכת\\\"ק ומייתי לה בפ\\\"ק דחולין (דף כ\\\"ז):\",1,0],[8,381,7,12,\"מקוה שנשתנה וכו'. נלמד הוא מדין הדיח בו סלי זיתים וענבים:\",1,0],[8,381,7,12,\"וכתב הראב\\\"ד מצאתי בתוספתא פ\\\"ה מקוה שאין בו מים מ' סאה וכו'. ורבינו שמשון פי' ולא עוד אלא אפי' חזר אחר כך למראיו כשר להקוות עליו עכ\\\"ל נראה מדבריו כשהקוה עליו להשלימו למ' סאה הוא דכשר אבל היין מעלה אותו כדברי הראב\\\"ד ורבינו נראה שלא היה מפרש כפירוש הראב\\\"ד דא\\\"כ לא הוה שתיק מיניה:\",2,0],[8,381,8,1,\"כל המעורב למקוה וכו'. ריש פרק ו' דמקואות:\",1,0],[8,381,8,1,\"ומה שכתב גומות הסמוכות לפי המקוה ומקום רגלי פרסות בהמה וכו'. שם בפרק חמישי מטבילין בחריצין ובנעיצין ובפרסת החמור המעורבת בבקעה:\",2,0],[8,381,8,2,\"חורי המערה וכו'. רפ\\\"ו דמקואות:\",1,0],[8,381,8,3,\"מחט שהיתה נתונה וכו'. בסוף פרק ז' דמקואות:\",1,0],[8,381,8,4,\"עוקה שבתוך וכו'. שם:\",1,0],[8,381,8,5,\"כותל שבין שני מקואות וכו'. ריש פרק ו' דמקואות וכת\\\"ק ופירש רבינו שתי הוא הארוך וכמוהו בכותל מלמעלה למטה וערב הרחב וכמוהו בכותל מימין לשמאל וכן פירש הראב\\\"ד בספר בעלי הנפש ורבינו שמשון והרא\\\"ש פירשו בהיפך:\",1,0],[8,381,8,6,\"כמה הוא שיעור הנקב וכו'. שם עירוב מקואות כשפופרת הנאד כעביה וכחללה בשתי אצבעות חוזרות למקומן ואיתא בפ\\\"ק דיבמות (דף ט\\\"ו) ובחגיגה פ\\\"ג ופי' חוזרות למקומן שהן מתהפכות בריוח בחלל הנקב:\",1,0],[8,381,8,6,\"ומ\\\"ש ואינם בגודל אלא שתי אצבעות ראשונות וכו'. בתוספתא שתי אצבעות שאמרו בבינוניות של כל אדם ולא מארבע בטפח:\",2,0],[8,381,8,6,\"כל שיעמוד כשפופרת הנאד וכו'. בפרק ששי דמקואות ודלא כרבן שמעון בן גמליאל:\",3,0],[8,381,8,6,\"ספק שיש בנקב וכו'. שם:\",4,0],[8,381,8,7,\"מטהרין את המקואות וכו'. ג\\\"ז שם ופי' רבינו שמשון העליון כגון שני מקואות בשיפועו של הר העליון אין בו מ' סאה והתחתון יש בו מ' סאה או יותר מביא סילון ונותן ראשו אחד בעליון וראשו אחד בתחתון וצריך להעמיק ראשו העליון בתוך המקוה החסר עד שירדו למטה שיהו מושקים למטה למקוה השלם כחוט השערה ליחשב כמקוה אחד וטובל אפי' בעליון ופעמים שלמעלה מגיעים המים עד שפת הסילון ובראשו של מטה מועטים כחוט השערה ולכך נקט מניח ידיו תחתיו שלא יצאו מים לחוץ כשמתמלא עד שעה שהשיק ולכך נקט הרחוק מן הקרוב ולא חיישינן שמא בא אדם והפסיק השקתו דלא עלתה לו טבילה וקשיא היאך מתחברים ע\\\"י כחוט השערה וגבי כותל קתני כשפופרת הנאד או כקליפת השום ונראה לפרש דלא איירי הכא בחסר אלא בשלם אלא שהוא שאוב ומשיקו לכשר להכשירו וסגי בחוט השערה דהיה לו בשאובה דרבנן ושמא מטעם זה לא חיישינן בסילון אפי' יהא קטפרס עכ\\\"ל:\",1,0],[8,381,8,7,\"כתב הראב\\\"ד שאין הסילונות פוסלים את המקוה א\\\"א בתוספתא ואם היה הסילון כפוף כל שהוא פוסלו וכו'. ואני אומר דהא דתנן בפ\\\"ד דמקואות סילון שהוא צר מכאן ומכאן ורחב מן האמצע אינו פוסל מפני שלא נעשה לקבלה הויא תיובתיה דהראב\\\"ד אלא ע\\\"כ לומר דהאי תוספתא מיירי כשעשאו כפוף על דעת קבלה:\",2,0],[8,381,8,8,\"שלש גומות שבנחל וכו'. תוספתא פרק ג' דמקואות שלש גומות שבנחל העליונה ותחתונה של כ' כ' סאה והאמצעית של מ' סאה וכו' רבי יהודה אומר רבי מאיר היה אומר מטבילין בין בתחתונה בין בעליונה ואני אומר בתחתונה ולא בעליונה וחכ\\\"א בין כך ובין כך אין מטבילין אלא באמצעית שיש בה מ' סאה ופסק כחכמים ונראה מדברי רבינו שאינו מפרש מחלוקתם בגוד אחית וגוד אסיק כדמשמע בפרק אין דורשין אלא באם המים הנזחלים מערבין המקואות וצריך טעם למה שינה ממאי דמשמע בגמרא דמפרש פלוגתייהו וצ\\\"ל דהיא היא דמאיזה טעם אין המים הנזחלין מערבין את המקואות משום דלית ליה לא גוד אסיק ולא גוד אחית. וכתב הריב\\\"ש בתשובה וז\\\"ל והא דמשמע בפרק אין דורשין דבגוד אחית לא פליגי דלכ\\\"ע אמרינן היינו ר\\\"מ ור\\\"י אבל רבנן דפליגי עלייהו בתוספתא ס\\\"ל דאין קטפרס לעולם חיבור אפי' ע\\\"י גוד אחית עכ\\\"ל. ולי נראה שרבינו מפרש שלא אמרו בפרק אין דורשין דפליגי בגוד אסיק אלא ר\\\"מ ורבי יהודה אבל חכמים טעמייהו משום דאין מים הנזחלים מערבים את המקואות:\",1,0],[8,381,8,9,\"טיט רך שהפרה שוחה ושותה ממנו וכו'. בפ\\\"ב דזבחים (דף כ\\\"ב):\",1,0],[8,381,8,10,\"מקוה שיש בו מ' סאה מים וטיט וכו'. בסוף פ\\\"ב דמקואות וכרבי יהושע:\",1,0],[8,381,8,11,\"כל שתחילת ברייתו מן המים וכו'. בפרק שני דזבחים ואמרינן בגמרא אפי' בעיניה נמי ופירש\\\"י אפי' אם כל המקוה נעשה מהם:\",1,0],[8,381,8,11,\"ומ\\\"ש ומטבילין בעינו של דג. ג\\\"ז שם ופירש\\\"י דג גדול שנימוק שומן עינו בחורו:\",2,0],[8,381,8,12,\"מקוה שיש בו מ' סאה מכוונות וכו'. בפ\\\"ז דמקואות וכת\\\"ק ובפ\\\"ב דחגיגה (דף י\\\"ט) אמרו שלא נחלקו אלא במעלות דרבנן אבל לעלות מטומאה גמורה לטהרה ד\\\"ה טמא:\",1,0],[8,381,8,12,\"הטביל בו תחילה סגוס עבה וכו'. שם וא\\\"ת מאחר שפסק רבינו בסמוך כת\\\"ק דשני טמא אע\\\"פ שרגליו של ראשון נוגעות במים היאך פסק בהטביל בו סגוס עבה והגביהו אם היה מקצת הסגוס נוגע במים הטובל באחרונה טהור שהרי כולם מעורבים ומאי שנא מרגליו של ראשון נוגעות במים תירץ הריב\\\"ש בתשובה שהסגוס עבה הוא בולע את המים ואינו כמו האדם שאין המים בלועים בעצם חלקיו אלא בשטח גופו וכיון שטופח על גופו אינו חיבור הרי נחסרו המים אבל הסגוס העבה הוא בלוע הרבה מן המים ולזה כשקצתו הוא במים הרי הוא כאילו כל המים הבלועים בבגד בקצתו של מעלה נוגעים במים שבקצתו שבתוך המים והרי כל המים מעורבים למקוה עכ\\\"ל. וק\\\"ל על תירוץ זה דמה לי שיהיו בלועים בעצם חלקיו ומה לי שיהא טופח על גופו ומה טעם הוא לומר שבשביל שהסגוס בלוע מים הרבה יהיה חיבור ומה שכתב וכיון שטופח שעל גופו אינו חיבור קשה שזהו מערכה על הדרוש לכן נ\\\"ל שהטעם משום דכשהגביה קצת הסגוס אינו כ\\\"כ קטפרס כמו שהוא האדם ועי\\\"ל שהטעם מפני שאין על האדם אלא טופח ואפשר שבקצת מקומות נקוב ונמצא שאינו חיבור:\",2,0],[8,381,8,12,\"הטביל בו את המטה וכו'. בספ\\\"ז דמקואות:\",3,0],[8,381,8,12,\"הטביל בו יורה וכו'. תוספתא פ\\\"ו דמקואות:\",4,0],[8,381,8,13,\"מקוה שמימיו מרודדין וכו'. משנה ספ\\\"ג דמקואות:\",1,0],[8,381,9,1,\"שש מעלות במקואות וכו'. בריש מקואות מי גבאים מי בורות שיחין ומערות ומי תמציות שפסקו ומקואות שאין בהם ארבעים סאה ומסיים בה כשרים לחלה וליטול מהם לידים:\",1,0],[8,381,9,1,\"ומה שכתב שהם שאובים. כתב הראב\\\"ד הואיל ואינם מתטמאין אלא לרצון א\\\"א כבר כתבתי עליהן וכו'. וגם אני כתבתי שם טעם לדברי רבינו:\",2,0],[8,381,9,1,\"ומה שכתב והוא שיטול מהם בכלי כמו שביארנו. כתב הראב\\\"ד והוא שיטול מהם בכלי א\\\"א ואם אינם שאובים וכו'. כבר כתבתי בטור א\\\"ח סימן קנ\\\"ט שדעת רש\\\"י כדעת רבינו שאין טבילת ידים מועילה אפילו לחולין אלא במים שראוי להטביל בהם כל גופו והילכך מים מכונסים בקרקע אע\\\"פ שאינם שאובים אם אין בהם ארבעים סאה אין מטבילין בהם הידים ואף על פי שהרב רבינו יונה והרשב\\\"א סוברים כדעת הראב\\\"ד כבר כתבתי שם שלשון התוספתא מסייע לרבינו:\",3,0],[8,381,9,2,\"למעלה מהם מי תמצית שלא פסקו וכו'. שם בריש מקואות למעלה מהם מי תמציות שלא פסקו ומסיים בה כשרים לתרומה וליטול מהם לידים:\",1,0],[8,381,9,2,\"ומ\\\"ש אבל אין בהם מ' סאה. הכי משמע מדקתני בתר הכי למעלה מהם מקוה שיש בו מ' סאה אלמא דעד השתא מיירי כשאין בו ארבעים סאה:\",2,0],[8,381,9,2,\"ומ\\\"ש ומטביל בהם את המים שנטמאו וכן מ\\\"ש פסקו הגשמים וכו'. תוספתא בפרק [א'] דמקואות:\",3,0],[8,381,9,4,\"החופר בצד הים וכו' עד הרי הן כמי גבאין. תוספתא בפ\\\"ק וא\\\"ת למה לא חילק בחופר בצד הנהר בין כל זמן שהיו באים מחמת הנהר כמו שחילק בחופר בצד המעיין ואפשר לדחוק ולומר דאה\\\"נ דתני במעיין והוא הדין לנהר ועי\\\"ל דנהר אינו חשוב כמעיין לענין זה משום דבנהר הרבה פעמים רבים נוטפים על הזוחלים אבל קשה מחופר בצד הים לכן נ\\\"ל דים הגדול ונהרות כיון שאין דינם כמעיין לענין מי חטאת כמ\\\"ש רבינו בפ\\\"י מהלכות פרה הוא הדין שהם מוחלקים ממנו לענין זה:\",1,0],[8,381,9,8,\"למעלה מהם מקוה שיש בו מ' סאה וכו' עד ולקדש מהם מי חטאת. משנה בפ\\\"ק דמקואות:\",1,0],[8,381,9,8,\"מה בין מעיין למקוה וכו' והמעיין מטהר בכל שהוא. בת\\\"כ ולאו דוקא בכל שהוא אלא כ\\\"מ שגופו עולה בבת אחת ור\\\"י סובר דהא דמעיין מטהר בכל שהוא דוקא לכלים אבל לא לאדם ורבינו אע\\\"פ שלא כתב בפירוש שמטהר בכל שהוא לאדם מ\\\"מ מדכתב קודם לכן דמקוה שיש בו מ' סאה שבו טובל כל אדם טמא חוץ מן הזב ובו מטבילין כלים כשכתב אח\\\"כ למעלה מזה המעיין שמימיו מועטין וכו' שהמעיין אין למימיו שיעור וכו' גם לטבילת אדם שכתב לעיל בסמוך קאי:\",2,0],[8,381,9,8,\"ומ\\\"ש המקוה אינו מטהר אלא באשבורן וכו' המקוה לא תעלה בו טבילה לזבים וכו'. מבואר פ\\\"ק דמקואות ובכלל מ\\\"ש רבינו טבילה לזבים ה\\\"ה למצורעים ולקדש מהם מי חטאת וסמך על מ\\\"ש לעיל בסמוך:\",3,0],[8,381,9,9,\"מעיין שמימיו יוצאים וכו'. רפ\\\"ה דמקואות:\",1,0],[8,381,9,9,\"היו מימיו נמשכים לתוך בריכה וכו'. שם העבירו על גבי בריכה והפסיקו הרי הוא כמקוה חזר והמשיכו פסול לזבים ולמצורעים ולקדש מהם מי חטאת עד שידע שיצאו הראשונים ונראה שמפרש רבינו דמתני' בבריכה מליאה מי מקוה עסקינן והא דקתני מתניתין והפסיקו היינו לומר שמי המעיין היו יורדין לבריכה ולא היו יוצאים חוצה לה ולפיכך הרי הוא כמקוה דכיון דאין מי המעיין נמשכים ויוצאים מהבריכה אע\\\"פ שעדיין קילוח מי המעיין יורדין לתוכה אינם מעלים את המים שבתוך הבריכה מדין מקוה ואם אח\\\"כ המשיכו כלומר שעשה שימשך ויצא מהצד האחר פסול לזבים וכו' עד שידע שיצאו המים הראשונים שירדו מהמעיין לבריכה דכיון שנקוו בבריכה פסק מינייהו שם מים חיים ולפיכך פסולים לזבים וכו' ומ\\\"מ דינם כמעיין לענין טבילה שמאחר שמי המעיין נכנסים לה ויוצאים ממנה מעלים הם את המים שבבריכה להיות כמעיין:\",2,0],[8,381,9,10,\"מעיין שמימיו נמשכים וכו'. שם ופסק כר\\\"י:\",1,0],[8,381,9,11,\"מעיין שהיו אמות קטנות נמשכות ממנו וכו'. שם מעיין שהוא מושך כנדל ריבה עליו והמשיכו הרי הוא כמו שהיה היה עומד וריבה עליו והמשיכו שוה למקוה לטהר באשבורן ולמעיין להטביל בו בכל שהוא ופירוש משנה זו מבואר בדברי רבינו וכך פי' הרא\\\"ש אבל הראב\\\"ד כתב הרי הן כמעיין לכל דבר א\\\"א תוספתא ואינו מטהר בזוחלין אלא עד מקום שהיה יכול להלך בתחלתו עכ\\\"ל. ורבינו והרא\\\"ש שלא חילקו בין מקום שהיה זוחל בו מתחלתו למקום שנתרחב נ\\\"ל שהם מפרשים דההיא תוספתא פליגא אמתניתין דלא מפלגא בינייהו ומדברי הר\\\"ן משמע שרבינו סובר דהלכה כההיא תוספתא דמפלגא בינייהו ואיני יודע מנין לומר כן דאם איתא הו\\\"ל לפלוגי בינייהו בהדיא ולא למיסתמא סתומי:\",1,0],[8,381,9,11,\"ומלשון רבינו שכתב וריבה עליו מים שאובים לתוך המעיין משמע דהא דתנן ריבה עליו והמשיכו הרי הוא כמו שהיה במרבה בגומת המעיין דוקא היא ששם הוא חשיבות מימיו ומבטלים כל המים הבאים עליהם אבל ריבה במקוה משך המעיין למטה אם רבו נוטפין עליו נפסל מלטהר בזוחלין ואם רבו שאובים עליו נפסל מלטהר אפילו באשבורן דכיון דרובו שאובין הו\\\"ל כאילו כולו שאובין שהרי מדכתב וריבה עליו מים שאובים לתוך המעיין משמע דבריבה לתוך גומת המעיין דוקא מיירי וכן נראה מדבריו בפירוש המשנה שכתב על מתני' דמעיין שהוא מושך כנדל וריבה עליו ששפך מים שאובים בעיקר המעיין וכ\\\"כ הר\\\"ן בפשיטות שזהו דעת רבינו אבל ק\\\"ל שמאחר שמי המעיין מטהרים בכ\\\"ש אפילו בזוחלין לא גרעו ממקוה שיש בו ארבעים סאה וכיון דבמקוה שיש בו ארבעים סאה אפילו נפלו עליו כל מים שאובים שבעולם לא פסלוהו ה\\\"ה למים הנזחלין מן המעיין לכך נ\\\"ל דלתוך המעיין שכתב כאן ובעיקר המעיין בפיר' המשנה לא אגומת המעיין דוקא קאי דבמים הנמשכים וניגרים מן המעיין נמי שייך למימר בהו הני לישני בתוך המעיין ועיקר המעיין ואפשר שכתב הני למעוטי היכא דריבה המים שאובים מחוץ למים הניגרים מהמעיין ונתפשטו השאובים ונגעו במים הנגרים מהמעיין דכל כה\\\"ג אפי' נוגעים בגומת המעיין עצמו לא נתבטלו במי המעיין:\",2,0],[8,381,9,12,\"כל הימים מטהרין בזוחלין וכו'. שם פ\\\"ח דפרה ובפ\\\"ה דמקואות כל הימים כמקוה שנאמר ולמקוה המים קרא ימים דברי ר\\\"מ ר\\\"י אומר הים הגדול כמקוה לא נאמר ימים אלא שיש בו מיני ימים הרבה ר\\\"י אומר כל הימים מטהרים בזוחלין ופסולים לזבים ולמצורעים ולקדש מהם מי חטאת ומשמע דהלכה כר\\\"י וכן פסקו רבינו והרא\\\"ש ופירש\\\"י בפרק שמנה שרצים ר\\\"י אומר כל הימים וים הגדול תורת מעיין עליהם לענין שהם מטהרין בזוחלין וכן פי' רבינו שמשון אבל רבינו פירש אמר ר\\\"י ששאר הימים זולת הים הגדול נחשבים כמעיין לענין שיטהרו בזוחלין ושהמימות הניגרים הנזחלים מכולם יטהרו בכ\\\"ש כמעיין ונחשבים כמקוה לענין שהם פסולים למי חטאת ולטהרת מצורע ולטבילת הזב עכ\\\"ל ונראה מתוך דבריו ז\\\"ל שהוא מפרש דמודה רבי יוסי בים הגדול שהוא כמקוה ואינו מטהר בזוחלין וכך הם דבריו בפ\\\"ו מהלכות פרה לחלק בין ים הגדול לשאר ימים כמו שאכתוב לשונו בסמוך אבל בכאן פסק סתם כל הימים מטהרים בזוחלין וכו' ולא חילק בין ים הגדול לשאר ימים ובפ\\\"ו מהלכות פרה כתב הים הגדול כמקוה ואינו כמעיין לפיכך אין ממלאין ממנו לקידוש וכל הנהרות פסולים לקדש מהם מי חטאת ושאר הימים כמעיין והמים הנגררים משאר הימים והם הנקראים זוחלים פסולים והזוחלים מן המעיין הרי הם כמעיין וכשרים עכ\\\"ל. והרי כאן שתי סתירות אחת בענין ים הגדול כמ\\\"ש והשנית ששם כתב ששאר ימים כמעיין ומשמע דכשרים למלאות מהם לקידוש כדין מעיין כגוונא דרישא דקתני גבי ים הגדול שהוא כמקוה וכאן כתב שכל הימים פסולים לקדש מהם מי חטאת ומתוך כך נ\\\"ל שרבינו סובר דלכולהו תנאי לענין טבילת שאר טמאים כל המים דינם כמעיין ליטהר בין באשבורן בין בזוחלין ולא איפליגו אלא לטבילת זבים ומצורעים וקידוש מי חטאת דכתיב בהו מים חיים דר\\\"מ סבר כולהו ימים כמקוה ופסולים להני תלת מילי דבעי מים חיים ורבי יהודה סבר דים הגדול הוא דמיפסיל להני תלת מילי אבל שאר ימים כשרים אף להנך תלת מילי בין בזוחלין בין באשבורן כדין מעיין ואתא רבי יוסי למימר לרבי יהודה שפיר קא אמר לפלוגי בין ים הגדול לשאר ימים ומיהו לאו לאכשורי שאר ימים להנך תלת מילי בין בזוחלין בין באשבורן אלא דוקא באשבורן כשרים אף להנך תלת מילי אבל כשהן זוחלין אע\\\"פ שהם מטהרים לכל הטמאים אף בזוחלין מ\\\"מ פסולים להנך תלת מילי דבעו מים חיים ואפשר דטעמיה משום דכשהם זוחלין דמו לנהרות וכיון דכל הנהרות פסולין למידי דבעי מים חיים גזרינן בזוחלין דשאר ימים אטו נהרות אבל בזוחלין מן המעיין לא גזרו לפי שעל הרוב הם מים מועטים ולא אתו לאיחלופי בנהרות ואפשר שמפני כך הפסיק רבינו בין ים הגדול לשאר ימים כדין כל הנהרות שרצה להקדים דין פיסול הנהרות לדין פיסול שאר ימים בזוחלין להודיענו דמשום גזירה אטו שאר נהרות נפסלו ופסק כרבי יוסי וא\\\"ת היאך מכשיר שאר ימים באשבורן להנך תלת מילי הא תנן בפ\\\"ח דפרה דמים המוכים דהיינו שהם מרים או מלוחים פסולים ואין לומר דבמים מתוקים מיירי מדמפליג בינייהו לים הגדול אלמא דבמלוחים דומיא דים הגדול מיירי ואפשר דמים מלוחים דפסילי היינו שמחמת הארץ שעוברין עליה נעשו מלוחים אבל היכא שמתחלת ברייתן הם מלוחים כגון מי הים כשרים כנ\\\"ל לפרש לדעת רבינו ובכן למדנו לדברי הכל דבין ים הגדול בין שאר הימים כשרים לטבילת טמאים בין בזוחלין בין באשבורן חוץ מן הזב הזכר ולמצורעים ולקדש מהם מי חטאת שאינם כשרים בזוחלין אבל באשבורן אף להנך תלת מילי כשרים וה\\\"מ בשאר ימים אבל ים הגדול פסול להנך תלת מילי בין בזוחלין בין באשבורן והשתא א\\\"ש דפסק כרבי יוסי ובהלכות פרה שהוא מקומו כתב הדינים באורך שים הגדול הוא כמקוה גמור ולכן הוא פסול למלאות לקידוש בין שהוא באשבורן בין שהוא בזוחלים וממילא משמע שהוא פסול לטבילת זבין ומצורעין אבל שאר ימים אע\\\"פ שהם פסולים להנך תלת מילי דוקא כשהן זוחלים אבל כשהם באשבורן הרי הם כמעיין וכשרים אף להנך תלת מילי וזהו שהאריך בלשונו גבי ים הגדול וכתב הים הגדול כמקוה ואינו כמעיין כלומר אין לו דין מעיין בשום ענין כלל וגבי שאר ימים כתב שהם כמעיין כלומר יש להם דין מעיין בקצת ולא כים הגדול שאין לו דין מעיין כלל בשום פנים שאלו יש להם דין מעיין גם להנך תלת מילי והיינו דוקא כשהם אשבורן אבל כשהם זוחלים פסולים להנך תלת מילי ובהלכות אלו סתם וכתב שכל הימים פסולים להנך תלת מילי ולא חשש לפרש דהיינו דוקא כשהם זוחלין אבל שאר ימים זולת ים הגדול אם הם אשבורן כשרים אף להנך תלת מילי מפני שסמך על מ\\\"ש במקומו בהלכות פרה ששאר ימים הם כמעיין וע\\\"פ דרך זה נמצאו דברי רבינו מכוונים ומיושרים:\",1,0],[8,381,9,13,\"המים הזוחלים מן המעיין וכו'. בפרק ה' דמקואות הזוחלים כמעיין והנוטפין כמקוה ופירש רבינו הזוחלין היינו הנהרות והיאורות המושכים מן המעיינות יש להם דין מעיין לכל דבר הנוטפים פי' מעיין שעל ההר ומימיו נופלים טפה טפה למטה בשיפולי ההר אע\\\"פ שאותם טפות יורדות במרוצה תיכף זו אחר זו כיון שאינו זוחל אלא יורדים בהפסק יש להם דין מקוה ובעו ארבעים סאה ואינם מטהרים בזחילה ופסולים לזבים ולמצורעים ולקדש מי חטאת עכ\\\"ל:\",1,0],[8,381,9,13,\"היו הזוחלין מן המעיין וכו' ואם רבו הנוטפין על הזוחלין וכו'. הכי משמע מדאמרינן בס״פ במה אשה (שבת דף ס״ה) דאבוה דשמואל עביד מקואות לבנתיה ביומי ניסן משום דמיטרא במערבא סהדא רבא פרת סבר שלא ירבו הנוטפים על הזוחלין כלומר ואז אינם מטהרים בזוחלים אלא באשבורן משמע דוקא בשרבו הא אי הוו כהדדי מטהרי בזוחלין וקשיא לי מדתנן בפ״ה דמקואות העיד רבי צדוק על זוחלין שרבו על הנוטפין שהם כשרים ומשמע דוקא כשרבו הא אי כהדדי נינהו אינם כשרים לטהר בזוחלין. אחר כך מצאתי להראב״ד בספר בעלי הנפש שהרגיש בקושיא זו ותירץ דהא דרבי צדוק משום דא״א לצמצם היא ומספיקא בעינן רובא א״נ איכא למימר דהא דרבי צדוק לאו לענין אשבורן הוא אלא להכשירן לטבילת זבים ומצורעים וכו' דבעו מים חיים אבל לענין אשבורן אפילו מחצה לא בעינן וכן עיקר דתנן בפ״ק דמקואות למעלה מהם מעיין שמימיו מועטים שרבו עליו מים שאובים שוה למקוה לטהר באשבורן ולמעיין להטביל בו בכל שהוא ש״מ עכ״ל. וכן פירש רבינו בפירוש המשנה הא דרבי צדוק להכשירן לזבין ולמצורעים וכו':\",2,0],[8,381,9,13,\"ומ\\\"ש רבינו לפיכך צריך להקיף מפץ וכו'. גבי בנתיה דאבוה דשמואל דבסמוך אמרינן דעביד להו מקואות ביומי ניסן ומפצי ביומי תשרי ונראה שרבינו מפרש דאף ביומי תשרי איכא למיחש שירבו נוטפין על הזוחלין וביומי ניסן שהנהרות גדלים הרבה היה ממשיך למקואות מים מהנהר וביומי תשרי שנתמעטו מי הנהר ואינם נמשכים למקואות היה מקיף מקום מהנהר במחיצת מפצים כדי שיהיו המים נקוים ולא יהיו זוחלים ורבינו כתב תיקון היקף המפצים ללמדנו שאפי' כשא\\\"א לעשות מקואות חוץ לנהר אפשר לעשותם בתוכו:\",3,0],[8,381,9,14,\"נוטפין שעשאן זוחלין וכו'. בפ\\\"ה דמקואות נוטפין שעשאן זוחלין סומך אפילו מקל אפילו קנה וכו' דברי רבי יהודה רבי יוסי אומר כל דבר שהוא מקבל טומאה אין מזחילין בו ומקל הוי פשוטי כלי עץ שאינם מקבלים טומאה אלא מדרבנן ואיפליגו בהו והלכה כרבי יוסי:\",1,0],[8,381,9,15,\"זוחלין שקלחן בעלי אגוז וכו'. פ\\\"ז דעדיות:\",1,0],[8,381,9,16,\"מי גשמים הבאים מן המדרון וכו'. בסוף פ\\\"ה דמקואות בש\\\"א מטבילין בחרדלית וב\\\"ה אומרים אין מטבילין ומודים שהוא גודר כלים וטובל בהם וכלים שגדר בהם לא הוטבלו:\",1,0],[8,381,9,16,\"ומ\\\"ש רבינו שחרדלית הם מי גשמים הבאים מן המדרון וכן מ\\\"ש שאע\\\"פ שיש מתחילתן ועד סופן ארבעים סאה. מפורש בתוספתא פ\\\"ד:\",2,0],[8,381,9,17,\"גל שנתלש וכו' ארבעים סאה וכו'. משנה סוף פ\\\"ה דמקואות:\",1,0],[8,381,9,17,\"ומ\\\"ש ואם נתכוון והיה יושב ומצפה וכו' לדבר שנתכוון לו. כלומר אם לתרומה אם לקדש והוא נלמד ממאי דאיתמר עלה בפרק ב' דחולין (דף ל\\\"א) ובסוף פרק ב' דחגיגה (דף י\\\"ט):\",2,0],[8,381,9,18,\"ומה שכתב אין מטבילין בגל וכו'. בפרק ב' דחולין שם (ע\\\"ב) מטבילין בראשון ואין מטבילין בכיפין ופירש רש\\\"י מטבילין כלים בראש הגל הנתלש מן הים והלך למרחוק ובא לארץ נכנס אדם תחת ראשו ומקבלו דהוי טבילה זו במחובר לקרקע ואין מטבילין בכיפין שלא יזרוק כלים בכיפי הגל דהיינו באמצעית שהוא עשוי ככיפה וטעמא כדמפרש שהיא טבילת אויר ואין מטבילין באויר עכ\\\"ל ולא נתברר מתוך דבריו שם למה אין מטבילין באויר אבל בפרק ב' דחגיגה כתב שהטעם מפני שלא אמרה תורה מקוה של אויר לטבילה ומשמע לי דנפקא ליה מדכתיב אך מעין ובור מקוה מים דהנך אין דרכן להיות באויר ודברי רבינו תמוהים מכמה אנפי חדא דממה שכתב לפי שאין מטבילין בזוחלין משמע דים אינו מטהר בזוחלין ורבינו כתב בפרק זה כל הימים מטהרים בזוחלין ואין לומר דהתם בשאר ימים שמטהרים בזוחלין וכרבי יוסי והכא בים הגדול וכדמשמע מפשט דברי רבינו בפירוש המשנה דלא אמר רבי יוסי דמטהר בזוחלין אלא שאר ימים אבל ים הגדול לא דאם כן לא הוה ליה למיסתם ולמיכתב כל הימים מטהרים בזוחלין אלא הו\\\"ל לאפוקי ים הגדול מכללם ואפילו את\\\"ל שסמך על מה שכתב בדין גל שנתלש מן הים דמשמע הים הידוע שהוא הים הגדול וקאמר ביה דאינו מטהר בזוחלין דאם כן הו\\\"ל למסמכיה לדין כל הימים מטהרין שכתב ועוד הו\\\"ל לאקדומי דאין ים הגדול מטהר בזוחלין ובתר הכי לימא שהטעם שאין מטבילין באויר היינו משום דאתי בקל וחומר מזוחלין או לימא לפי שאינו מטהר בזוחלין או לפי שאין מטבילין בו בזוחלין דלישתמע בגריעותיה דאין מטבילין בזוחלין משום דים הגדול הוא דלפי מ\\\"ש משמע דאזוחלין דעלמא קאי ועוד דמדכתב היו שני ראשי הגל נוגעים בארץ מטבילין בו וכן ממה שכתב גל שנתלש מן הים ונפל על האדם ועל הכלים הרי אלו טהורים משמע בהדיא שגל זה מטהר בזוחלין דאין לומר שמה שכתב היו שני ראשי הגל נוגעים בארץ כשהם במקום אשבורן הוא דאם כן הוה ליה לפרושי ועוד דרישא דקתני גל שנתלש מן הים ונפל על האדם ועל הכלים על כרחך דרך זחילה נפל עליהם ואפילו הכי הם טהורין לכך נראה דלעולם לדעת רבינו ים הגדול מטהר בזוחלין:\",1,0],[8,381,9,18,\"ומה שכתב לפי שאין מטבילין בזוחלין, לא בים הגדול קאמר אלא ה\\\"פ אויר יותר גרוע מזוחלין ומאן דחזי דמטביל באויר בגל הנתלש מן הים אתי להטביל בזוחלין דנוטפין דאמרי מסתייא לגרועי נוטפין ממעיין חד דרגא לומר דאין מטבילין באויר דנוטפין אבל בזוחלין דנוטפין שפיר דמי ולפיכך גזרו שלא יטביל באויר דגל שנתלש מן הים כדי שיהא היכר בדבר דהשתא ליכא למיחש לטעותא כלל דכולי עלמא ידעי דנוטפין גריעי ממעיין וכי גרעי ליה חד דרגא ממילא משמע להו דאין מטבילין בזוחלין ואע\\\"פ שאין זה מבואר יפה בדברי רבינו מ\\\"מ כיון שאם באנו לומר שהוא ז\\\"ל מחלק בין ים הגדול לשאר ימים לענין טבילת טמאים אינו מבואר בדבריו וגם יש בו כמה דוחקים וקושיות כמו שכתבתי אפילו אם היינו יכולים ליישבם בדוחק נראה לי דמוטב לאחוז בדרך זו להשוות דעתו עם דעת הפוסקים מלאחוז בדרך האחרת דמשוינן ליה חולק עלייהו ועוד דכיון דאיהו ז\\\"ל סבר דכולו שאוב כשר מן התורה למה יגזרו חכמים על הים הגדול שלא יטהר בזוחלין דהא לא שייך למיגזר ביה אטו חרדלית של גשמים כדכתב ר\\\"מ דמהאי טעמא אמרו לטבול בנהרות בר מיומי תשרי ועוד דבים הגדול לא משכחת לעולם שירבו נוטפין על המעיין ואע\\\"ג דרחמנא קרייה מקוה היינו לענין דברים שהצריכה תורה מי מעיין קאמר דים זה לאותם דברים דינו כמקוה אבל חכמים מה להם בכך כיון שלפי האמת הוא מעיין אלא שהתורה גזרה לפוסלו לאותם דברים לפיכך דעתי מסכמת דלדעת רבינו בין ים הגדול בין שאר ימים מטהרין בזוחלין וכמו שכתבתי לעיל:\",2,0],[8,381,10,2,\"ספק מים שאובים שטהרו חכמים וכו' עד ואם לזה נפלו נפסל. פ\\\"ב דמקואות:\",1,0],[8,381,10,4,\"מקוה שהניחו ריקן וכו' עד שהרי יש שם מקוה כשר קבוע. תוספתא דמקואות פרק ב' וקשה אמאי פסל במכתשת בצדו הא ספק מים שאובים הוא ויש לומר דמדתנן ספק מים שאובים למקוה משמע דלא הכשירו מים שאובים מספק אלא כשהיתה שם מקוה מים ונסתפק אם נפלו בו מים שאובים אבל אם היה ריקן ונמצא מלא אינו בכלל זה ובשלא היתה מכתשת בצדו כשר אע\\\"פ שהיה ריקן מקודם מטעמא דמסיים בתוספתא שחזקת המקואות כשירות כלומר שחזקת הממלא מקוה מחדש אינו ממלאו אלא ממים כשרים ועי\\\"ל דבמכתשת בצדו אף על גב דספק הוא לא הכשירו בו מפני שהפיסול הוא בעין וכדקתני מפני שהפיסול מוכיח וכשרובו כשר אע\\\"פ שהפיסול בעין כשר מפני שיש שם רוב מקוה כשר קבוע:\",1,0],[8,381,10,5,\"כל המקואות הנמצאים וכו' עד שחזקתן מן הגשמים. משנה רפ\\\"ח דמקואות ותוספתא פ\\\"ו ופירוש מפתח שער העיר ומיהו משמע שאין זה אלא בזמן שהיו ישראל שרויים על אדמתם אבל האידנא דין א\\\"י שוה לארץ העכו\\\"ם בזה וכן משמע בתוספתא:\",1,0],[8,381,10,6,\"הטמא שירד לטבול וכו' עד הרי זה טהור. שם פ\\\"ב:\",1,0],[8,381,10,6,\"כתב הראב\\\"ד ה\\\"ז טהור א\\\"א ואם היה אב הטומאה מד\\\"ס ספיקו טמא עכ\\\"ל. ואני אומר דבר זה מבואר במשנה פרק רביעי דטהרות אלו ספיקות שטיהרו חכמים ספק ד\\\"ס אכל אוכלים טמאים וכו' אכל דבר שהוא אב הטומאה והוא מד\\\"ס ספיקו טמא ומאחר שרבינו לא כתב כאן להקל אלא באכל אוכלים טמאים וכו' ממילא משמע דדוקא בהני הוא דמטהר ולא בדבר שהוא אב הטומאה אע\\\"פ שהוא מד\\\"ס:\",2,0],[8,381,10,7,\"שני מקואות אחד כשר וכו'. תוספתא דמקואות פ\\\"ב:\",1,0],[8,381,10,7,\"וכתב הראב\\\"ד הראשונות תלויות והשניות ישרפו א\\\"א לא ידעתי טעם לזה ואולי מפני שנגעו זה בזה וכו'. ורבינו שמשון בפ\\\"ב דמקואות הביא תוספתא זו יותר באורך ופירשה ולענין מאי דקתני ראשונות תלויות והשניות ישרפו כתב ראשונות תלויות דשניות פסולות הן בעלמא ואינן מטמאות הראשונות ואכתי ראשונות בספיקן הן עומדות אבל שניות ישרפו ממה נפשך דנטמאו בנגיעת הראשונות לכל הפחות ובסיפא דראשונות טומאה קלה ושניות טומאה חמורה ונגעו אלו באלו הוי איפכא מטעמא דפרישית דשניות תלויות וראשונות ישרפו עכ\\\"ל:\",2,0],[8,381,11,1,\"כבר ביארנו: ומ\\\"ש וידים שצריכות טבילה. הוא על פי מה שנתבאר בפרק ששי דברכות:\",1,0],[8,381,11,1,\"ומ\\\"ש שבמקום שהאדם טובל בו כלים ידים טובלים. תוספתא פרק א' דמקואות:\",2,0],[8,381,11,1,\"ומ״ש אבל ידים שאין צריכות וכו'. בפרק כל הבשר (חולין דף ק״ו) אמרינן גבי חמי טבריה כל גופו טובל בהם ידיו לא כ״ש:\",3,0],[8,381,11,1,\"ומ״ש ואם הטבילן במים שאובים וכו' לא טהרו ידיו. טעמו מדאמרינן בפרק כל הבשר (חולין דף ק״ו) האי אריתא דדלאי אין מטבילין בו את הידים דהו״ל מים שאובים:\",4,0],[8,381,11,1,\"ומ\\\"ש שאין נוטלין אלא מן הכלים ומכח נותן כמו שביארנו בהלכות ברכות. פ\\\"ו:\",5,0],[8,381,11,2,\"כל החוצץ בטבילה חוצץ בידים. ברייתא בפרק כל הבשר (חולין דף ק״ו ע״ב):\",1,0],[8,381,11,2,\"וכל העולה למדת מקוה וכו'. פ\\\"ב דזבחים (דף כ\\\"ב):\",2,0],[8,381,11,2,\"וכל הנוטל ידיו צריך לשפשף. תוספתא פ\\\"ק דידים:\",3,0],[8,381,11,5,\"הנוטל שתי ידיו לתרומה וכו'. כן משמע פרק שני דידים:\",1,0],[8,381,11,5,\"ומ\\\"ש לפיכך אם נפל ככר של תרומה כו' ואם נטל ראשונים ושניים למקום אחד וכו' עד בראש או בכותל ה\\\"ז טהורה. פ\\\"ב דידים:\",2,0],[8,381,11,5,\"כתב הראב\\\"ד הנוטל שתי ידיו לתרומה א\\\"א ואף לחולין וכו'. ואני אומר שרבינו סובר דלא בעינן מים שניים אלא לתרומה אבל לא לחולין וכן נראה מדבריו בפירוש המשנה בהקדמתו למסכת ידים ולפיכך בפרק ששי מהלכות ברכות בענין נטילת ידים לחולין לא הזכיר מים שניים כלל ולפיכך כתב כאן הנוטל שתי ידיו לתרומה צריך לחזור וליטול פעם שנייה דוקא לתרומה דאילו לחולין לא בעינן פעם שנייה ונראה שטעמו מדתנן בפרק ב' דידים נפל ככר של תרומה על הראשונים טמא ואם איתא דלחולין נמי צריך מים שניים אמאי נקט נפל ככר של תרומה אפילו של חולין נמי והירושלמי שכתב הראב\\\"ד הוא במסכת ברכות פרק אלו דברים [ובירושלמי דמסכת] חלה פ\\\"ב תני מים שלפני המזון רשות ושלאחר המזון חובה אלא שבראשונים נוטל ומפסיק ובשניים נוטל ואינו מפסיק מהו נוטל ומפסיק רבי יעקב בר אחא אמר נוטל ושונה ע\\\"כ. ופירשו רבינו שמשון בריש מסכת ידים:\",3,0],[8,381,11,6,\"נטל שתי ידיו משטיפה אחת וכו'. רפ\\\"ב דידים נטל לידו אחת משטיפה אחת ידו טהורה לשתי ידיו משטיפה אחת רבי מאיר מטמא עד שיטול מרביעית ופי' שם רבינו כאשר נטמאו ידיו שתיהן ורחץ אותם בשפיכה אחת אמר ר\\\"מ כי לא יצא ברחיצה הזאת וכו' והלכה כתנא קמא אשר יאמר כי אפילו היו שתי ידיו משטיפה אחת יצא:\",1,0],[8,381,11,6,\"ומ\\\"ש אפילו ירדו ה' זה בצד זה וכו'. שם נוטלים ארבעה וחמשה זה בצד זה או זה על גב זה ובלבד שירפו שיבאו בהם המים:\",2,0],[8,381,11,7,\"נטל מקצת ידו וכו'. בפ\\\"ב דגיטין (דף ט\\\"ו ט\\\"ז) ואע\\\"ג דדחי ואמר דהא דתניא טופח על מנת להטפיח חיבור דילמא לענין מקואות ור\\\"י היא כלומר אבל לענין נטילת ידים לא פסק רבינו להקל משום דדרך דחייה קאמר לה ועוד דהו\\\"ל ספיקא בדרבנן ולקולא:\",1,0],[8,381,11,7,\"ומ\\\"ש בד\\\"א במים ראשונים וכו'. זו היא ששנינו בריש ידים מוסיפים על השניים ואין מוסיפים על הראשונים וכן פירשה רבינו שם בפי' המשנה והביא ראייה מהתוספתא. והראב\\\"ד כתב ואם עדיין יש על מקצת שנטל בתחילה טופח על מנת להטפיח הרי זו טהורה א\\\"א טעה בזה וכו'. נראה שטעמו מדתניא בתוספתא ריש ידים מי רביעית נותנים לאחד אף לשנים וכו' מוסיפים על השניים דברי ר\\\"מ רבי יוסי אומר מי רביעית נוטלין לאחד אבל לא לשנים מוסיפים על השניים ואין מוסיפים על הראשונים ע\\\"כ. וסובר הראב\\\"ד שדברי רבינו כאן כר\\\"מ דאמר מוסיפין על הראשונים ומשיג עליו שאין הלכה כמותו אלא כרבי יוסי דאמר אין מוסיפין על הראשונים. גם סבר הראב\\\"ד שדברי רבינו הם כשנטל מקצת ידו בפחות מרביעית ולכן משיג עליו עוד שלמה פסק כן שזהו כר\\\"מ דאילו לרבי יוסי כל פחות מרביעית אין שם נטילה עליו כך נ\\\"ל לפרש דבריו אע\\\"פ שאין תיבת אבל שכתב נוחה לפירוש זה:\",2,0],[8,381,11,7,\"ומ\\\"ש עוד ואין טופח להטפיח מועיל בזה וכו'. כלומר דההיא דפרק ב' דגיטין דמהני טופח על מנת להטפיח שאני התם שמעיקרא נטל מקצת ידו מרביעית אי נמי שעל נטילת מקצת יד אחרונה הוא שסובר הראב\\\"ד שרבינו אינו מצריך רביעית מאחר שלא הזכירן ועל זה משיג כדפרישית וזה מוכיח יותר בסוף לשונו:\",3,0],[8,381,11,7,\"ומ\\\"ש עוד ואולי קבע הלכה כר\\\"מ דתוספתא מפני ששנאו סתם במשנה כלומר בא ליתן טעם לדברי רבינו למה פסק כר\\\"מ לגבי רבי יוסי משום דסתם לן תנא כוותיה וזה טעם נכון לפי מה שסבר הוא בדברי רבינו שפוסק על הראשונים מי רביעית נותנין לאחד אף לשנים אבל רבינו כתב בסמוך שלא נאמר כן אלא על השניים אבל לראשונים לעולם רביעית בעי' גם מבואר בדבריו שהוא פוסק שאין מוסיפין על הראשונים וכסתם מתניתין דקתני מוסיפים על השניים ואין מוסיפין על הראשונים והיינו שאין שם טופח על מנת להטפיח דאילו היה כן מהני אף בראשונים כדאמרינן פרק ב' דגיטין דכל שיש שם טופח על מנת להטפיח לא קרינן ביה מוסיפין שהכל חשוב כנטילה אחת:\",4,0],[8,381,11,7,\"כתב עוד הראב\\\"ד אבל במים שניים נוטל מקצת ידיו וכו' א\\\"א טעה אף בזה וכו'. וכבר ביארתי טעם רבינו שכל שיש שם טופח על מנת להטפיח לא קרינן ביה מוסיפים שהכל חשוב כנטילה אחת:\",5,0],[8,381,11,8,\"שיעור המים שנוטלים בהם תחילה וכו'. בריש ידים מי רביעית נותנים לאחד אף לשנים וכו'. כתב הראב״ד אבל מים שניים וכו' א״א כל זה כתב בשיבוש וכו'. וטעמו מדתנן בריש ידים מי רביעית נותנים לידים לאחד אף לשנים מחצי לוג לשלשה ולארבעה מלוג לחמשה ולעשרה ולמאה ומפרש לה הראב״ד במים ראשונים ומשמע ליה דכי קתני דמרביעית נוטלין אף לשנים הוי בלא תוספת הוא הדין דמלוג לשלשה ולארבעה הוי בלא תוספת דחושבניה דדין כחושבניה דדין אבל מלוג לחמשה ולעשרה ולמאה על כרחיך אי אפשר בלא תוספת מים שיוסיפו ורבינו סובר שאין דברי משנה זו אלא במים שניים אבל מים ראשונים אין פחות מרביעית לכל אחד ואחד וטעמו מדאמרינן בפרק כל הבשר (חולין דף ק״ז) אשיעורא לא קפדינן דתנן מרביעית נוטלין לאחד ואף לשנים ולא היא שאני התם משום דאתו משיורי טהרה ומפרש רבינו דהיינו לומר דמתני' במים שניים דוקא משום דכבר נעשית הטהרה במים הראשונים ומפני כך אין צריך שיעור אלא כדי שימשח היד אבל במים הראשונים אינו בפחות מרביעית לכל אחד ואחד ופי' זה כתב רבינו עצמו בפירוש המשנה והראב״ד יפרש שיורי טהרה ששנים באו ליטול כאחד ומכ״מ נתבאר שאין שיבוש בדברי רבינו דפירושים מחולקים הם מר מפרש הכי ומר מפרש הכי ולישנא דאתו משיורי טהרה יותר נוח לפירוש רבינו ופירש שם רבינו הנטילה הזאת התירו בפחות מרביעית וכו':\",1,0],[8,381,11,9,\"כלי שהיה בו רביעית מים כשרים וכו'. בפ\\\"ב דזבחים עלה כ\\\"ב אמר ריש לקיש כל המשלים למי מקוה משלים למי כיור לרביעית אינו משלים למעוטי מאי וכו' אמר רב פפא למעוטי נתן סאה ונטל סאה דתנן מקוה שיש בו ארבעים סאה מכוונות נתן סאה ונטל סאה כשר וכו' אמר ר\\\"י עד רובו ומפרש רבינו דהיינו לומר דבנתן מים הפסולים לנטילה וחזר ונטל כשיעור שנתן הוא וממעט להו שאינם משלימים ברביעית אף על פי שמשלימים במקוה אבל כשנתן לרביעית מעט מים פסולים ולא חזר ונטל כשרים מפני שלא נתמעט שיעור רביעית של מים כשרים:\",1,0],[8,381,11,10,\"כל המים הפסולים לנטילה במים ראשונים וכו':\",1,0],[8,381,11,11,\"וכל אותם הדברים שביארנו שם בנטילת ידים לפת חולין וכו'. יש לתמוה דאיפכא הוה ליה למימר דכל הדברים שצריכים לתרומה צריכים בחולין דהא תרומה עדיפא ואפשר דמשום דבהלכות ברכות שהן קדמו להלכות אלו כתב דיני חולין שייך למימר הכי:\",1,0],[8,381,11,11,\"נשלמו הלכות מקואות\",2,0],[8,382,1,2,\"אפילו עכו״ם כו'. יש לתמוה על זה שכתב שאסור לעשקו דהא קרא לא תעשוק את רעך כתיב דמשמע לאפוקי עובד כוכבים ועוד קשה דאמרינן בפרק הגוזל ומאכיל (בבא קמא דף קי״ג:) דהפקעת הלואתו מותר ועושק היינו הפקעת הלואתו כמ״ש רבינו בסמוך אי זהו עושק וכו' כגון שהיה לו ביד חבירו הלואה או שכירות ויש לומר שרבינו סובר כדפי' רש״י הפקעת הלואתו שאין גזל ממש שרי כי ליכא חלול השם כגון היכא דטען ליה ליורש נתתיו לאביך ומת דלא ידע העכו״ם בהדיא דקא משקר וגם התוס' כתבו שם אף על גב דטעות העכו״ם מותר אסור להטעות העכו״ם כשהוא יודע שגוזל ועושה עצמו כלא יודע. ודייק רבינו לכתוב אסור לגזלו או לעשקו ולא כתב שעובר עליו בלא תעשה לומר שאין איסור זה מן התורה:\",1,0],[8,382,1,6,\"גזל שתים שוות פרוטה והחזיר אחת גזילה יש כאן מצות השבת גזלה אין כאן. בפ' הגוזל עצים בעיא ופשט גזלה אין כאן השבה אין כאן ומקשה התם אי גזלה אין כאן השבה יש כאן אמרי ה\\\"ק אע\\\"פ שגזלה אין כאן מצות השבה אין כאן וכתב הרא\\\"ש פירוש הרמ\\\"ה אע\\\"פ שגזלה אין כאן ואין ב\\\"ד כופין אותו להחזיר כיון דאין בו שוה פרוטה ודאי אם לא החזיר אחת מדעתו אלא בציווי ב\\\"ד כופין אותו להחזיר את השניה כההיא דתניא הוזקקו ב\\\"ד לשוה פרוטה גומרים אף בפחות משוה פרוטה [אלא השתא דהחזיר אחת מדעתו גזילה אין כאן דאין ב\\\"ד נזקקין לפחות משוה פרוטה] מצות השבה אין כאן ומעצמו חייב להחזיר לקיים מצות השבה ואין ב\\\"ד נזקקין לכופו. עוד פירש אע\\\"פ שהגזילה אין כאן ואין ב\\\"ד נזקקין לכופו בתורת ממון מצות השבה אין כאן ומכין אותו עד שתצא נפשו לקיים מצות השבה עכ\\\"ל. והטור כתב פירוש שני דהרמ\\\"ה וכתב עליו וכ\\\"כ הרמב\\\"ם גזילה יש כאן השבה אין כאן עכ\\\"ל. וק\\\"ל על דברי רבינו דכיון דבין למאי דאמרינן מעיקרא בין למאי דאסיקנא אמרינן דגזילה אין כאן היאך פוסק בהפך דגזילה יש כאן. ומצאתי נוסחא אחרת בדברי רבינו גזילה אין כאן מצות השבת גזילה אין כאן וגם על נוסחא זו ק\\\"ל כיון שהקשו בגמ' על זה והעלו אע\\\"פ שגזלה אין כאן למה לא כתב כדברי המסקנא. ונראה ליישב נוסחא זו שרבינו מפרש דס\\\"ד דמקשה גזילה אין כאן ביד הגזלן כיון שלא נשאר בידו שוה פרוטה השבה אין כאן שלא קיים השבה עד שישיב הכל ומש\\\"ה מקשה אי גזילה אין כאן כלומר דלא מיקרי גזילה מה שבידו מפני שאין בה שוה פרוטה השבה יש כאן כלומר במה שהשיב סגי דשפיר מיקרי השבה אע\\\"פ שנשארה בידו אגודה כיון שאין בו שוה פרוטה ומתרץ דה\\\"ק אע\\\"פ שגזלה אין כאן כלומר אע\\\"פ שבמה שהשיב לא יש שיעור פרוטה והרי הוא כאילו לא החזיר דבר מצות השבה אין כאן כלומר במה שנשאר בידו שאינו שוה פרוטה אין בו מצות השבה והילכך אינו חייב להשיב. וכיון שכתב מצות השבה כמו שהוא בתירוץ לא חשש לכתוב תיבת אע\\\"פ. ואפשר שבגרסתו בגמ' לא היה כתוב תיבת אע\\\"פ. וה\\\"ה כתב על דברי רבינו בעיא דאיפשיטא שם בזה הלשון גזילה אין כאן מצות השבה אין כאן פירוש שלא קיים מצות השבה ואע\\\"פ שאין כאן גזילה חשובה במה שהוא מעכב לעצמו ואם בא לקיים מצות והשיב את הגזילה יחזיר הכל כיון שבתחלה היתה הגזילה שוה פרוטה וכן פירשו ז\\\"ל עכ\\\"ל. ותמהני עליו דהא איכא לאקשויי על זה אי גזילה אין כאן השבה יש כאן כמו שהקשו בגמרא:\",1,0],[8,382,2,4,\"הגוזל והשביח ומכר או וכו'. כתב הטור על זה והוא הולך לשיטתו שאינו מחשיב לידה וגיזה שינוי מעשה עכ\\\"ל. ואני אומר שאע\\\"פ שכך היא סברת רבינו אינו ענין לכאן שהרי לא הזכיר כאן רבינו גיזה ולידה אלא שבח סתם ואע\\\"פ שסתמו כפירושו שאם הוא שבח שיש בו שינוי מעשה קנויה היא לו הגזלה אפילו בלא יאוש מ\\\"מ יותר נכון לומר דלשיטתיה דקודם יאוש אין לגזלן כלום אזיל וכמ\\\"ש ה\\\"ה מאחר שמפורש שתלה הדבר בלפני יאוש:\",1,0],[8,382,2,11,\"גזל לשון של מתכת וכו' או שגזל טווי ועשאו בגד וכו' ה״ז שינוי בידו. תימה דבריש פרק הגוזל (בבא קמא דף צ״ו) משמע דהאי חוזר לברייתו הוא דאמרינן התם חופיא ועבדיה שרשורא לא קנה מ״ט דהדר סתר ליה והוי חופיא וא״כ טווי ועשהו בגד נמי מצי סתר ליה והוי טווי:\",1,0],[8,382,3,4,\"גזל בהמה והזקינה וכו' אבל אם גזל בהמות וכחשו וכו' או עבדים והזקינו וכו' אומר לו הרי שלך לפניך ומחזיר הגזילה בעצמה. הטור כתב וז\\\"ל ובגוזל עבדים וכחשו כחשא דלא הדר כתב רב אלפס דמשלם כשעת הגזילה דעבדי כמטלטלי דמו וכ\\\"כ הרמב\\\"ם עכ\\\"ל. ונוסחא משובשת נזדמנה לו בדברי רבינו:\",1,0],[8,382,4,9,\"הגוזל אחד מחמשה וכו' הרי כל אחד מהם נשבע שגזלו. כ\\\"כ הרי\\\"ף והרא\\\"ש בפרק המפקיד והטעם משום דכלל הוא לכל נוטל מעות מחבירו שהוא צריך לישבע אי נמי דכיון דמדינא פטור אלא דמשום דעבד איסורא אתה קונסו אין ראוי לקונסו לשלם בלא שבועה:\",1,0],[8,382,4,14,\"מעשה באחד שחטף לשון של כסף וכו'. כתב ה\\\"ה נראה מדברי הרב שהגוזל את חבירו צריך להחזיר לו בעדים, ורבינו ירוחם בנל\\\"א ח\\\"ד והריב\\\"ש בסי' שצ\\\"ב כתבו כדבריו שרבינו סובר כן. ואיני יודע מהיכן למדו לומר שהוא סובר כן ומכ\\\"מ כתב הריב\\\"ש שרבו כמו רבו החולקים עליו וכתב שהרמ\\\"ה השיב להרמב\\\"ן שאינו צריך להחזיר לו בעדים וקלסו הרמב\\\"ן וכתב עליו הרמב\\\"ן שפתים ישק ובפ\\\"ד דטוען נסתפק ה\\\"ה בדעת רבינו:\",1,0],[8,382,5,2,\"אסור ליהנות בדבר הגזול וכו'. כתב עליו הטור אינו נראה כן מהא דאמר שמואל דינא דמלכותא דינא תדע דקטלי דיקלי וגשרי גשורי ועברינן עליהו ואי לאו דינא היכי עברינן עלייהו ופריך אביי ודילמא משום דאייאוש מרייהו אלמא לאחר יאוש שרי עכ\\\"ל. וכבר נתיישב זה בדברי ה\\\"ה שכתב דשאני התם דאיכא יאוש ושינוי רשות:\",1,0],[8,382,5,8,\"ואסור ליהנות מן הגזלן וכו'. כתב הרב המגיד פסק כשמואל וכו' זה תימה קצת שהרי כתב בפ\\\"ו מהל' גניבה גבי גנב וכו'. וכבר כתבתי אני שם שאין זה ענין לזה:\",1,0],[8,382,5,10,\"נטלו המוכסים כסותו והחזירו לו אחרת וכו' ואם היה ותיק ומחמיר על עצמו וכו'. טעמו מדתנן פ' הגוזל ומאכיל (בבא קמא דף קי״ד) נטלו מוכסים את חמורו ונתנו לו (חמור) אחר נטלו לסטים את כסותו ונתנו לו (כסות) אחרת הרי אלו שלו מפני שהבעלים מתייאשים מהם ובגמרא תנא אם נטל מחזיר לבעלים הראשונים קסבר יאוש כדי לא קני ומעיקרא באיסורא אתא לידיה ואיכא דאמרי אם בא להחזיר יחזיר לבעלים הראשונים מ״ט יאוש כדי קני מיהו אי אמר אי אפשי בממון שאינו שלי מחזיר לבעלים הראשונים. ופירש״י אם בא להחזיר שחסיד הוא יחזיר לבעלים הראשונים ולא למוכס ופסק רבינו (כלישנא בתרא דאתי) כסתם מתניתין דקתני הרי אלו שלו מדינא ואע״ג דבעלמא קי״ל יאוש כדי לא קני ואע״ג דכי אתא לידיה הוה ליה יאוש ושינוי רשות מ״מ באיסורא אתא לידיה הכא שאני שהוא במכירה שהרי לא נתנה לו בחנם אלא תמורת חמורו ונמצא שאינו נהנה מהגזילה ואינו יודע בודאי שזו גזולה כלומר דבשעה שנתנוה לו לא ידע שהיא גזולה ואע״פ שחזקתה גזולה בסתמא וגם אח״כ ידע שהיא גזולה וכדקתני מחזיר לבעלים הראשונים מ״מ כיון שבשעה שנתנוה לו לא ידע שהיא גזולה וגם אינו נהנה ממנה שהרי תמורת חמורו נתנוה לו לא אמרי' באיסורא אתא לידיה וכיון דאיכא יאוש ושינוי רשות הרי אלו שלו מדינא ואם בא להחמיר על עצמו שלא נסמוך על דברים הללו וכיון דאיגלאי מילתא שגזולה היתה חשיב ליה דבאיסורא אתא לידיה ומש״ה הרוצה להחזיר יחזיר לבעלים הראשונים ולא למוכר:\",1,0],[8,382,5,11,\"ומ\\\"ש אבל מכס שפסקו המלך וכו' ולא עוד אלא שהוא עובר המבריח ממכס זה וכו' בין שהיה המלך עכו\\\"ם בין שהיה המלך ישראל. נראה לכאורה שטעמו משום דאל\\\"כ כי אקשי בפ' הגוזל בתרא להבריח מהמכס מי שרי והאמר שמואל דינא דמלכותא דינא ה\\\"ל לשנויי כאן במלך ישראל כאן במלך עכו\\\"ם. אבל יש לגמגם בזה משום דאיתא התם בגמ' איכא דמתני' (לה) אהא נודרין להרגין ולחרמין ולמוכסים וכו' שהיא של בית המלך אע\\\"פ שאינה של תרומה וכו' והאמר שמואל דינא דמלכותא דינא וכו' רב אשי אמר במוכס עכו\\\"ם דתניא ישראל ועכו\\\"ם שבאו לדין וכו' ור\\\"ע טעמא דאיכא קידוש השם הא ליכא קדוש השם באים (בעקיפין) וגזל עכו\\\"ם מי שרי והתניא וכו' מנין לגזל עכו\\\"ם שהוא אסור וכו' ל\\\"ק כאן בגזלו כאן בהפקעת הלואתו פי' רש\\\"י הפקעת הלואתו שאין גוזל ממש שרי כי ליכא חילול השם כגון היכא דטען ליה ליורש נתתים לאביך ומת דלא ידע עכו\\\"ם דמשקר ולהבריח מכס הוי כהפקעת הלואתו. והשתא כיון דהברחה מן המכס לא הוי אלא כהפקעת הלואתו אמאי אסור להבריח מן המכס במלך עכו\\\"ם. ושמא י\\\"ל דהכא שאני שהעמיד המלך ישראל לגבות לו חלקו דהוי כאילו המלך עצמו גובהו דהשתא מלבד שאם יודע יש חילול השם בדבר אפשר שיהיה סכנת נפשות בדבר אבל עכו\\\"ם שחכר המכס מן המלך שאז אם יודע לא יהיה בדבר סכנת נפשות מאחר שאין המלך מפסיד בזה הוא שאמרו שמותר להבריח ממנו המכס דהוי כהפקעת הלואתו:\",1,0],[8,382,5,16,\"וכן מלך שגזר וכו' אבל אינו עובד בו כעבד. וטעמו משום דקיימא לן דהא דאסור להעביד העבד עברי בדברים שהם מיוחדים לעשיית העבדים כגון להוליך כליו אחריו לבית המרחץ או לחלוץ לו מנעליו משום שנאמר לא תעבוד בו עבודת עבד ה\\\"מ עבד עברי שנפשו שפלה מפני שנמכר אבל ישראל שלא נמכר מותר להשתמש בו כעבד וכמבואר בפרק חמישי מהלכות עבדים וקמ\\\"ל דהני כיון דבדינא דמלכותא משתעבדי בהו משום כרגא דיהבי עלייהו ה\\\"ל כמכורים ודינם כדין עבד עברי שאסור לעבוד בו עבודת עבד:\",1,0],[8,382,6,1,\"קורות ואבנים ועצים וכיוצא בהם כו'. כתב הרב המגיד ברייתא פרק אלו מציאות וכו'. ומיהו עיקר הדין דאין יכולים להציל אע\\\"פ שלא נתייאשו הרי הן של מוצאן וכו' נ\\\"ל שגם רבינו סובר כן ממ\\\"ש בפרק י\\\"א:\",1,0],[8,382,6,1,\"ואם אינו יודע אם נתייאשו וכו'. כן יש ללמוד מפלוגתא דאביי ורבא ביאוש שלא מדעת:\",2,0],[8,382,6,11,\"והמשחק בקוביא עם העכו\\\"ם אין בו איסור גזל וכו'. כתב הטור על דברי רבינו יראה שפוסל משחק בקוביא משום גזל אפילו שיש לו מלאכה אחרת וע\\\"כ מחלק בין משחק בקוביא עם העכו\\\"ם או עם ישראל עכ\\\"ל. וטעמו משום דפ' זה בורר (דף פ\\\"ד:) אמתניתין דפסל משחק בקוביא לעדות בעי בגמרא מאי קא עביד אמר רמי בר חמא משום דהוי אסמכתא ואסמכתא לא קניא רב ששת אמר כל כה\\\"ג לאו אסמכתא היא אלא לפי שאין עסוקין בישובו של עולם מאי בינייהו איכא בינייהו דגמר אומנתא אחריתי והתנן אר\\\"י אימתי בזמן שאין לו אומנות אלא הוא אבל יש לו אומנות שלא הוא הרי זה כשר אלמא טעמא דמתני' משום יישובו של עולם הוא וכ\\\"ת פליגי רבנן עליה דר\\\"י והאמר ריב\\\"ל כ\\\"מ שאמר ר\\\"י אימתי ובמה אינו אלא לפרש דברי חכמים ר\\\"י וכו' גברא אגברא קא רמית מ\\\"ס פליגי ומ\\\"ס לא פליגי הא קמן דלרב ששת דמשחק בקוביא לא מיפסיל משום גזל אלא משום שאינו עוסק ביישובו של עולם, ר\\\"י לפרש דברי חכמים אתא ולא מקרי אינו עוסק ביישובו של עולם אלא כשאין לו אומנות אחרת וכיון דלא מתסר משום גזל לא שאני לן בין משחק עם העכו\\\"ם למשחק עם ישראל ומאחר שרבינו כתב דמשחק עם העכו\\\"ם אינו אסור משום גזל אלא משום שאינו עוסק בישובו של עולם משמע בהדיא שסובר דעם ישראל מיתסר משום גזל כרמי בר חמא וכבר נתבאר בגמרא דלרמי בר חמא פליגי רבנן עליה דר\\\"י וסברי דאפילו יש לו אומנות שלא הוא פסול, וכתב ה\\\"ה על דברי רבינו זה קצת תימה אצלי דהא משמע פ' זה בורר דההיא אוקמתא דאמר אסמכתא היא ולא קניא אידחיא וקי\\\"ל כרב ששת וכו' ובפי\\\"ב מהל' עדות כתבתי ליישב דעת רבינו:\",1,0],[8,382,8,2,\"הגוזל את אביו ונשבע לו וכו'. כתב הטור על דברי רבינו ואין זה מדרך המשנה אלא כמו שפירשתי שיתננה לאחי הגזלן או לאחי אביו אם אין לו אחים כלומר דלרש\\\"י שפירש יתן לבניו ולאחיו דקתני מתני' לבניו של אביו או לאחיו של אב אם אין לו בנים שפיר נקט לבניו ברישא אבל לפירוש רבינו הוה ליה למינקט תחלה לאחיו ואח\\\"כ לבניו. ואני אומר שאפילו היה כדבריו אין זה כדאי לומר על פירוש רבינו אין זה מדרך המשנה כל שכן שהתוספות פירשו כפירוש רבינו ונתנו טעם לשבח למה נקט לבניו ברישא:\",1,0],[8,382,8,2,\"כתב עוד הטור וגם מ\\\"ש שיעשה חשבון עם אחיו משמע נוטל חלק בגזילה זה אינו אלא אינו נוטל בה מאומה. פשטא דמילתא כך הוא לכאורה אבל רבינו מפרש בענין אחר וכן כתב ה\\\"ה וזה לשונו נראה שהרב מפרש משלם קרן וחומש ומ\\\"מ מעכב בידו שאר נכסים יותר מחלקו המגיעו בהם כפי מה שיהיה מגיעו בהם מקרן וחומש שנתן בהם וזהו שכתב עושה עמהם חשבון וזה אם אינו רוצה לתת חלקו עכ\\\"ל. ונראה שטעמו של רבינו שכיון שנתן כל הגזילה לבניו או לאחיו הרי קיים מצות השבת גזילה ומעתה למה לא יתבע חלקו בנכסי אביו:\",2,0],[8,382,9,11,\"לקחה הגזלן מן הבעלים וכו'. כתב הטור (סי' שע\\\"ד) מלשון הרמב\\\"ם יראה הוא הדין נמי אם קנאה מהנגזל קודם שמכרה או נתנה לאחר ואחר שקנאה מכרה ונתנה לאחר דאמרינן נמי שלא כיון לקיימה ביד הראשון ואין נראה דמיד כשקנאה נתקיימה ביד הלוקח ואינו יכול למוכרה עוד לאחר עכ\\\"ל. וי\\\"ל לדעת רבינו דהב\\\"ע כגון שלקחה מיד זבנה או אורתה דהא תיכף שלקחה גלי דעתיה דלאו לאוקומה קמי לוקח ראשון לקחה וכן פירש הרב רבינו ניסים בשם הראב\\\"ד. ועוד י\\\"ל דלא אמרינן דלקחה כי היכי דליקום בהימנותיה אלא כל היכא דלא זבנה או אורתה בתר הכי דהא דאמרן דניחא ליה דליקום בהימנותיה אומדן דעתא בעלמא הוא ונ\\\"מ להיכא דמית גזלן בתר הכי אבל כל היכא דזבנה או אורתה הא גלי דעתיה דליתיה לאומדן דעתא דידן וכיון שהוא מוחזק בקנין השדה מבעליו זה שרוצה להוציאו מחזקתו עליו הראיה ולפי זה אפילו לא זבנה או אורתה אלא שהוא עצמו בא לערער להוציאה מיד הלוקח וטוען שלעצמו קנאה ולא כי היכי דליקום בהימנותיה מהימן:\",1,0],[8,382,9,13,\"נתנוה הבעלים לגזלן מתנה קנאה הלוקח וכו'. כתב ה\\\"ה זה מחלוקת רב אחא ורבינא וכו' ורבינו פסק כמ\\\"ד כמכר ואולי משום דמסתבר טעמא דמ\\\"ד כמכר לדעתו ז\\\"ל עכ\\\"ל. ויותר נראה בעיני לומר דטעמו לפי שהלוקח מוחזק בקרקע ובטענה כל דהו מוקמינן ליה בידיה וכמ\\\"ש הטור בשם הרמ\\\"ה:\",1,0],[8,382,10,5,\"אמר לו בעל השדה עקור אילנך ולך וכו'. פשט דברי רבינו נראה דאכל מאי דכתב לעיל קאי בין עשויה ליטע בין אינה עשויה ליטע אלא שהרב המגיד כתב נראה שאין דעת הרב בזה אלא בשדה שאינה עשויה ליטע שאז הדין עם בעל השדה וכו' וכ\\\"נ מן ההלכות עכ\\\"ל. ואני איני רואה בדברי בעל ההלכות הוכחה בזה:\",1,0],[8,382,10,7,\"ובעל בנכסי אשתו והשותף בשדה וכו' כיורד ברשות הן. בסוף הפרק כתב ה\\\"ה דהיינו דוקא באשתו קטנה וכ\\\"כ הרשב\\\"א שצריך להגיה כאן בעל בנכסי אשתו קטנה:\",1,0],[8,382,11,2,\"אבל אוכל נבילה להכעיס הרי הוא אפיקורוס. בפרק ב' דע\\\"ז (דף כ\\\"ו:) מומר פליגי רב אחא ורבינא חד אמר [לתיאבון] מומר להכעיס מין הוא וחד אמר אפי' להכעיס נמי מומר ופסק כמ\\\"ד אפיקורוס משום דאמרינן התם דר\\\"י ור' אבהו סברי הכי ויש לתמוה למה בפ\\\"ג מהל' תשובה לא מנאו בכלל אפיקורוס.\",1,0],[8,382,11,2,\"ומ\\\"ש והאפיקורוסים בפ' הנזכר כתב מי הם הנקראים אפיקורוסים ומשמע ודאי שדינם אחד.\",2,0],[8,382,11,2,\"ומ\\\"ש עכו\\\"ם ומחללי שבת בפרהסיא. מבואר בפ\\\"ק דחולין (דף ג':) שדינם כעכו\\\"ם:\",3,0],[8,382,11,3,\"אבידת העכו\\\"ם מותרת וכו' ואם החזירה לקדש את השם וכו'. בירושלמי פרק אלו מציאות.\",1,0],[8,382,11,3,\"ומ\\\"ש ובמקום שיש חילול השם אבידתו אסורה ומ\\\"ש וחייב להחזירה. נראה דהיינו לומר דאע\\\"ג דלא אתאי לידיה חייב להשיבה כיון שיש חילול השם בדבר אם לא ישיבנה כגון שמצאה במקום רוב ישראל שיחשוב העכו\\\"ם שישראל גנבוה:\",2,0],[8,382,11,11,\"המאבד ממונו לדעת אין נזקקין לו וכו' ואע\\\"פ שאסור לרואה דבר זה ליטול לעצמו וכו'. כתב הטור על זה ואין נראה כן דאבידה מדעת הוי הפקר עכ\\\"ל. ודעת רבינו שבשביל שזה אינו חושש לפקח על נכסיו לא נאמר שהפקירם:\",1,0],[8,382,11,13,\"מצא שק או קופה וכו' ואומד את דעתו אילו היה שלו אם היה מחזירן לעצמו וכו'. בפ' אלו מציאות (בבא מציעא דף ל':) אמר רבא כל שבשלו מחזיר בשל חבירו נמי מחזיר:\",1,0],[8,382,11,13,\"היה דרכו להחזיר כלים כאלו בשדה וכו' מצאן בשדה חייב להחזירן וכו'. כתב הרא\\\"ש ראיתי גדולים שפסקו כיון דלא איפשיטא אזלינן לחומרא [ומיחייב להחזיר בשדה וכיון דאיחייב איחייב אף בעיר] ויראה לי כיון שפטרה תורה את הזקן שאין לו לזלזל בכבודו איסור הוא לגבי דידיה שמזלזל בכבוד התורה במקום שאינו חייב [ומשום ספק ממון חבירו אם הוא מחוייב בו לא זלזל בספק איסור] וחכם שבא לעשות לפנים משורת הדין יותר מממונו יעשה כמו שעשה ר' ישמעאל בר' יוסי אבל אין לו רשות לזלזל בכבודו ולדעת רבינו י\\\"ל דלא מיקרי מזלזל בכבוד התורה בשביל כך אדרבא הוא כבוד שמים שאין דרכו בכך בשלו והוא מיטפל בשל חבירו לפנים משורת הדין:\",2,0],[8,382,11,14,\"ומ״ש וכן אם מצא בהמה והכישה חייב להטפל בה ולהחזירה. מימרא דרב וכו'. ומפרש טעמא בפרק הספינה (בבא בתרא דף פ״ח) משום דאנקטה נגרי ברייתא ופיר״ש כלומר דרגילה לברוח ולילך מרחוק (ומש״ה) נתחייב בה. ולפ״ז דוקא בהמה דשייך בה ה״ט הוי דינא הכי אבל בכלים דלא שייך בהו ה״ט אע״פ שהתחיל יכול להניחם. ונמוקי יוסף כתב וז״ל הכישה נתחייב בה להחזירה הואיל והתחיל נתחייב בהשבה גמורה כך פירש״י ז״ל ולפ״ז ה״ה לכלים וכך הם דברי הרמב״ם בהלכות גזילה והרנב״ר תמה דלא משמע כן פרק הספינה דהתם קאמר טעמא משום דאנקטינהו נגרי ברייתא עכ״ל. ומלשון רבינו שכתב וכן אם מצא בהמה והכישה משמע דדוקא בבהמה הוא דהוי דינא הכי ולא בכלים אע״ג דבמצא כלים בשדה קאמר דחייב להחזירם אפילו בעיר התם שאני דכיון דדרכו להחזיר בשדה נתחייב בהם אבל בשמצאם במקום שאין דרכו להחזיר יכול להניחם אבל מדיהיב טעמא שהרי התחיל במצוה משמע דה״ה לכלים דה״ט שייך בהו ומשמע שעל זה תמה הרנב״ר ואמר דבפרק הספינה לא משמע כן וכו' ובפרק הכונס אמר הכי רבא בהדיא. ונראה לי דבבהמה דוקא קאמר רבינו והתחיל במצוה דקאמר ה״פ התחיל במצות השבה ואם לא יגמרנה הרי נמשך היזק לבעל אבידה דאנקטינהו נגרי ברייתא. ויש הוכחה לזה מדכתב אחר כך לעולם הוא חייב להטפל בה עד שיחזירנה לרשות בעליה וכו' אבל ב״ח לעולם חייב להטפל עד שיכניסה לרשות הבעלים המשתמרת כו'.\",1,0],[8,382,11,14,\"ההולך בדרך הטוב והישר וכו' ואע\\\"פ שאינה לפי כבודו. ודין זה דאינה לפי כבודו אין זה מקומו ואיחרו כדי לכתוב קודם לו ההיא דב\\\"ח לעולם חייב להטפל בה וכו' דהוי טעמא משום נגרי ברייתא דנילף מינה דהכישה מה\\\"ט הוא:\",2,0],[8,382,11,15,\"החזיר את האבידה בשחרית וכו'. בפ' הכונס (בבא קמא דף נ״ו:) גבי פלוגתא דרב יוסף ורבה בשומר אבידה אי כש״ח דמי או כש״ש איתיביה רב יוסף לרבה החזירה למקום שיראנה אינו חייב להטפל בה נגנבה או אבדה חייב באחריותה מאי נגנבה או אבדה לאו נגנבה מביתו או אבדה מביתו לא ממקום שהחזירה והא קתני אינו חייב ליטפל בה א״ל הב״ע כגון שהחזירה בצהרים ותרתי קתני וה״ק החזירה שחרית למקום שיראנה ושכיח דעייל ונפיק וחזי לה אינו חייב ליטפל בה החזירה בצהרים למקום שיראנה דלא שכיח דעייל ונפיק דלא חזי לה ונגנבה או אבדה חייב באחריותה איתיביה לעולם הוא חייב עד שיחזירנה לרשותו מאי לעולם לאו אפילו לביתו ש״מ כש״ש דמי א״ל מודינא לך בב״ח דכיון דנקטי להו נגרי ברייתא בעי נטירותא יתירתא ואע״ג דהא דקאמר החזיר שחרית למקום שיראנה רבה הוא דאוקי ברייתא הכי ולא קי״ל כוותיה בשומר אבידה אלא כרב יוסף דאמר כשומר שכר דמי וכמבואר פי״ג לא פליגי אלא בגנובה או אבודה מביתו אם חייב או פטור אבל אם החזירה שחרית למקום שיראנה ושכיח דעייל ונפיק וחזי לה אינו חייב ליטפל בה דהשבה מעליא היא זו:\",1,0],[8,382,11,17,\"ההולך בדרך הטוב והישר וכו'. בפ' אלו מציאות (דף ל\\\"ז:) ר' ישמעאל בר' יוסי [הוה קאזיל באורחא] פגע ביה ההוא גברא דהוה דרי פתכא דאופי [אותבנהו וקא מיתפח] א\\\"ל דלי לי א\\\"ל כמה שוין א\\\"ל פלגא דזוזא יהב ליה פלגא דזוזא ואפקרה וכו' והא ר' ישמעאל בר' יוסי זקן ואינה לפי כבודו הוה לפנים משורת הדין הוא דעבד:\",1,0],[8,382,12,1,\"מי שאבדה לו אבידה וכו' אם היה אביו שקול כנגד רבו של אביו קודמת וכו'. מה שקשה על זה ממ\\\"ש בפ\\\"ה מהל' ת\\\"ת יישבתי שם:\",1,0],[8,382,13,1,\"המוצא אבידה וכו' אפילו היתה שוה פרוטה בעת המציאה והוזלה חייב להכריז עליה. דברי הרב המגיד תמוהין שכתב שדעת הרב הפך מאי דאסיקנא:\",1,0],[8,382,13,5,\"הסימנים המובהקים וכו'. כתב ה\\\"ה דפסק רבינו כמ\\\"ד סימנים דאורייתא וכו'. וקשה שבפי\\\"ג מהלכות גירושין גבי מצאוהו הרוג או מת וכו' אע\\\"פ שיש סימנים בגופו ובכליו ואפילו שומא אין מעידין עליו כתב ה\\\"ה לא נתכוון בכאן אלא לסימנים שמחזירין עליהם אבדה ואעפ\\\"כ אין מעידין עליהם בכאן וכתב ג\\\"כ שהסימנים המובהקים שהם מן התורה אף כאן מעידים עליהם וא\\\"כ הרי שכתב שסימנים דאבעיא לן בגמרא אם הם דאורייתא לדעת רבינו לא שרינן אשת איש אפומייהו משום דלאו דאורייתא נינהו וכאן כתב שפוסק כמ\\\"ד דסימנים דאורייתא וא\\\"כ ה\\\"ל למשרי אשת איש אפומייהו וה\\\"ל לפרש שמ\\\"ש שם רבינו אע\\\"פ שיש סימנים בגופו ובכליו היינו כגון ארוך וגוץ וכגון חיוורי וסומקי וכפי מ\\\"ש בשמו בפי\\\"ג מהל' גירושין הוה ליה לפרש כאן כשכתב הסימנין המובהקין סומכים עליהם וכו' היינו במובהקין ביותר.\",1,0],[8,382,13,5,\"ומ\\\"ש והמדה והמשקל וכו' סימנים מובהקים הם היינו סימנים חשובים קצת והם דאבעיא לן עלייהו בגמרא אי הוי דאורייתא ולא איפשיטא ומ\\\"מ לענין ממון מחזירין אבידה עליהם. ודיוק לשון רבינו כן מדלא כתב הסימנין המובהקין סומכין עליהם וכו' דין תורה ואלו הם סימנין מובהקים מדה או משקל, או ה\\\"ל לכתוב והמדה והמשקל סימנים מובהקים הם מן התורה:\",2,0],[8,382,13,7,\"זה נתן מדת ארכה ורחבה וזה נתן מדת האמריות שבה וכו'. קשה שמדת האמריות היינו מדת ארכה וכבר כתב דין זה בסמוך ושמא י\\\"ל דנותן מדת האמריות שבה היינו לומר שנותן מדת אורך ורוחב האמריות שבה:\",1,0],[8,382,13,16,\"אווזים ותרנגולים גדולים מיטפל בהם שלשים יום וכו'. טעמו של רבינו משום דכשהם קטנים ביותר טרחם ומזונם מרובה יותר מהגדולים שהם הולכים ומנקרים באשפות:\",1,0],[8,382,14,12,\"המוצא כלי חרש וכיוצא בהם וכו'. כתב\",1,0],[8,382,14,12,\"ה\\\"ה ומ\\\"ש חייב להכריז שאם יבא תלמיד חכם וכו' פירש הר\\\"א דהכרזה זו אינה בבתי כנסיות ובבתי מדרשות אלא מקום שת\\\"ח מצויים שם וכו'. ואני אומר שמפשט דברי רבינו נראה שאפילו מצא במקום שאין ת\\\"ח מצויין שם אם בא ת\\\"ח ואמר יש לי טביעות עין בכלי שאבדתי חייב להראותו לו והטעם משום דכיון שהאובד הוא ת\\\"ח כשמרגיש שאבד אע\\\"פ שאין לו סימן אינו מתייאש לפי שהוא יודע שיחזירו לו בטביעות עין:\",2,0],[8,382,15,1,\"כל המוצא אבידה בין שיש בה סימן וכו' ואם היה דבר שאין בו סימן זכה בו ואינו חייב להחזירו. כתב הטור על זה ולא נהירא (אלא יהא מונח עד שיבא אליהו) וגם ה״ה כתב על דברי רבינו זו באמת קשה ודאי והיאך יזכה בו ויהיה שלו וכו'. ואפשר לומר לדעת רבינו דהא דאמרינן בריש פרק אלו מציאות (בבא מציעא כ״א:) בפלוגתא דאביי ורבא ביאוש שלא מדעת הויא בדבר שאין בו סימן ואיפסיקא הלכתא כאביי דאמר יאוש שלא מדעת לא הוי יאוש משום דהא לא ידע דנפל מיניה היינו לומר שאסור לו ליטלם אבל אם עבר ונטלם זכה בהם משום דכיון שהם בידו ואינו יודע למי יחזירם שהרי אין בהם סימן ולמקום שנטלם אין לו להחזירה כמו שנתבאר ממילא זכה בהם דאין לנו לומר שיעמדו עד שיבא אליהו אלא היכא דאתמר הכי בהדיא:\",1,0],[8,382,15,1,\"כתב ה\\\"ה (לפי הנראה מהסוגיא האמורה על משנתנו וכו') הנ\\\"ל מדברי רבינו שהוא גורס כן בסוף אותה סוגיא וכו'. ואני אומר הנך רואה כמה דחוקים דבריו לחדש גירסא מדעתו ועוד שהגירסא מבואר שהיא דחוקה מאד. ולכן נ\\\"ל שרבינו סובר דכיון דר' אבא בר זבדא אמר סתם (דף כ\\\"ה:) כל ספק הינוח לכתחלה לא יטול בין שיש בה סימן בין שאין בה סימן קאמר והא דקאמר גבי מצא אחר הגפה או הגדר גוזלות מקושרים מ\\\"ט דאמרינן הני איניש אצנעינהו ואי שקיל להו לית להו למרייהו סימנא בגווייהו לאו למימרא דלא איירי מתני' אלא בשאין בו סימן דבין ביש בו סימן בין באין בו סימן מיירי והיכא דאית בהו סימן אסור ליגע בהם מפני שגורם להטריח הבעלים והיכא דלית בהו סימן איכא טעמא רבה שגורם שיאבדו הבעלים ממונם וכי פריך ליהוי קשר סימן וליהוי מקום סימן לאו למימרא דאי הוה קשר או מקום סימן היה מותר ליטלם אלא משום דאיהו אמר עלה דמתני' דהיכא דלית בהו סימן איכא טעמא רבה כדי שלא יפסידו הבעלים מקשי ליה דהא מתני' בשיש בה סימן דקשר או מקום מיירי ואהדר ליה דמתניתין באין בה סימן נמי מיירי דלישנא דמקושרים משתמע בין קשר שיש בו סימן בין קשר שאין בו סימן דהיינו שמקושרים בכנפיהם ומיירי בין במקום סימן בין בשאינו סימן וכגון שמדדים. כך נ\\\"ל ליישב דעת רבינו:\",2,0],[8,382,15,8,\"מצא פירות מפוזרים וכו'. כתב הטור [סימן רס\\\"ב] על זה ולא נהירא דבגמרא מוקי למתני' דמצא פירות הרי אלו שלו במכנשתא דביזרי שמדעת הונחו שם ונתייאשו הבעלים וכו' הא לאו הכי אסורים מפני שלא ידעו הבעלים שנפלו שיתייאשו מהם ודאי אם דרך נפילתן מוצא שם וידוע שנתייאשו בעלים מותרים אבל סתמא לא עכ\\\"ל. טעמו דכי אותבינן עליה דאביי דאמר יאוש שלא מדעת לא הוי יאוש ממתני' דמצא פירות מפוזרים הרי אלו שלו שני במכנשתא דביזרי ואם כדברי רבינו טפי הוי עדיף לאוקמה בדאשכחינהו דרך נפילה. וי\\\"ל לדעת רבינו דהא דאקשינן אי דרך נפילה אפילו טובא נמי וכו' גם אליבא דאביי דהלכתא כוותיה מקשינן לה דכיון דיקירי מידע ידיע כדאמרינן בעיגולי דבילה והא דמותבינן לאביי ממתנית' ומתרצינן לה במכנשתא דביזרי היינו מקמי דידעינן טעמא דיקירי אבל בתר דידעינן מתני' בכל אנפי מיתוקמא כאביי וכ\\\"כ הרמב\\\"ן לדעת הרי\\\"ף וכ\\\"כ נמוקי יוסף:\",1,0],[8,382,15,10,\"מצא כריכות ברה\\\"י וכו'. כתב ה\\\"ה מ\\\"ש במקצת ספרי הרב וכו'. ול\\\"נ שאפשר לומר שמ\\\"ש כאן אינו סימן מובהק היינו משום דאיכא למיחש שמא עברו בני אדם באותו רה\\\"י וגלגלוהו ממקומו אבל היכא דידוע שלא נתגלגל כגון שהוא מונח בצד הגדר הוי מקום סימן מובהק וכמ\\\"ש פרק י\\\"ג:\",1,0],[8,382,15,11,\"מצא עיגול ובתוכו חרס וכו'. כתב הטור על זה איני יודע למה פסק כר' יהודה וא\\\"א הרא\\\"ש ז\\\"ל פסק כחכמים וכו' עכ\\\"ל. וכתב החכם המרשים דאפשר שטעם רבינו משום דאמר בגמרא דכ\\\"ע סימן הבא מאליו הוי סימן אלמא הלכתא היא אע\\\"ג דדנינן מיניה אי נמי משום דקי\\\"ל בחתיכות בשר כל שיש שינוי בחיתוכן חייב להכריז אע\\\"פ שלא נעשה בכוונה וה\\\"ל כסימן הבא מאליו עכ\\\"ל. ואין דבריו נכונים כלל שמ\\\"ש דמשום דאמרינן דכ\\\"ע סימן הבא מאליו הוי סימן אלמא הלכתא היא וכו' סברא הפוכה היא דכיון דבגמ' אמרינן גבי סימן העשוי לידרס לימא כתנאי וכו' סברוה דכ\\\"ע סימן הבא מאליו הוי סימן ובסימן העשוי לידרס קמפלגי ואמר רב זביד משמיה דרבא אי ס\\\"ד דקסבר ת\\\"ק סימן העשוי לידרס לא הוי סימן וכו' אלא הכא בסימן הבא מאליו קמפלגי הרי שנדחית סברת הסברוה בטענה והיאך אפשר לפסוק הלכתא כוותיה גם מ\\\"ש דמשום דקי\\\"ל בחתיכות בשר כל שיש שינוי בחיתוכן חייב להכריז וכו' אינו נראה דלא מיקרי סימן הבא מאליו אלא דבר שבודאי נעשה שלא בכוונה כגון ככר ובתוכו מעות עיגול ובתוכו חרס משא\\\"כ בחתוכא דבשרא המשונה דרובא דרובא הוא נעשה בכוונה [ומ\\\"ש שהרי\\\"ף פסק כר' יהודה לא נמצא בספרים שלנו שהרי\\\"ף פסק כן] אבל טעם מחלוקת רבינו והרא\\\"ש [תלוי בגירסת המשנה] שרבינו גורס אלו מציאות שלו וכו' מצא פירות מפוזרים הרי אלו שלו דברי ר\\\"מ ר' יהודה אומר כל דבר שיש בו שינוי חייב להכריז וכו' וכיון דפלוגתא דר\\\"מ ור' יהודה היא הלכה כר' יהודה והרא\\\"ש לא גריס דברי ר\\\"מ אלא סתם מתני' היא והלכתא כוותה:\",1,0],[8,382,16,1,\"המוצא מחטין וצנורות וכו'. נ\\\"ל שמיירי שמצא אלו על גב אלו דאל\\\"כ דרך נפילה הם. ונראה שרבינו ז\\\"ל מפרש הא דתניא אימתי מותרים בזמן שמצאן אחד אחד אבל אם מצאן שנים שנים חייב להכריז לא ברבים איירי אלא מחט אחת או שתי מחטין קאמר ויש לתמוה על פירוש זה דהא בהדיא מפרש בגמרא מאי בדי שוכי וגם על דינו יש לתמוה אמאי במצא שנים חייב להכריז מ\\\"ש ממצא שני מטבעות דאפילו עשויין כמגדל אינו חייב להכריז:\",1,0],[8,382,16,4,\"המוצא מעות בחנות וכו'. כתב הטור על זה ואינו נראה כן מתוך הגמרא אלא הוא של החנוני וטעמא שדרך הבאים להחליף ליתן מעותיהם על השולחן משא\\\"כ בחנות שאין דרך הבאים לקנות ליתן חפציהם על התיבה. טעמו מדאמרינן בגמרא ניתני מצא בשולחנות כדקתני רישא מצא בחנות וכו' אלמא בלישנא דמצא בחנות לא על גבי תיבה משמע ומשום דקשיא מ\\\"ש על גבי תיבה מעל גבי שולחן לכך כתב וטעמא שדרך הבאים להחליף ליתן מעותיהם על השולחן משא\\\"כ בחנות וכו' ול\\\"נ שטעמו של רבינו דכיון דמאי דאמרינן מאי איריא דתני בין הכסא לשולחני של שולחני ניתני על השולחן שייך נמי בחנות במאי איריא דתני בין תיבה לחנוני של חנוני ניתני ע\\\"ג תיבה לחנוני מדלא תני הכי משמע דעל גבי תיבה הרי הוא של מוצאו והא דקאמר א\\\"נ בשלחנות כדקתני רישא מצא בחנות הכי פירושו וא\\\"נ לא היה הכרח זה ה\\\"ל להכריח מדלא קתני מצא בשולחנות כדקתני מצא בחנות והיינו מפרשים דעל גבי שלחן לא הוי בכלל שלחנות והשתא דקתני לפני שלחני הוי שלחן בכלל ומ\\\"מ אע\\\"ג דקתני מצא בחנות הוי ע\\\"ג תיבה בכלל מדקתני סיפא בין תיבה לחנוני של חנוני ולא קתני על גבי תיבה נמצא דעל גבי תיבה ועל גבי שלחן דינם שוה אלא דלעיל גבי שלחן מכריעים מרישא ומסיפא דהרי אלו שלו ולע\\\"ג תיבה לא מכריעין ליה אלא מסיפא:\",1,0],[8,382,16,9,\"מצא מטמון וכו' ואם היה תוך הכותל מלא מהם חולקין. כתב הרב המגיה רחוק הוא שרבינו רוצה לומר על הבבא שלמעלה דמוכח בגמרא דאזלינן בתר קתא ושנציה אפילו היכא דמוכח בזה האחר הואיל וברייתא דתניא אם היה כותל ממולא מהם חולקים קאי על המשנה דמיירי באדרא ונסכיה. לכך נראה דט\\\"ס הוא וצ\\\"ל אחר הבבא של מטה דמחלק בלשונות של זהב בין חציו לחוץ לחציו לפנים. ועל זה קאי אם נמצא תוך הכותל מלאה עכ\\\"ל:\",1,0],[8,382,16,11,\"לפיכך אם היה משכיר לאחרים וכו'. כתב ה\\\"ה ומ\\\"ש ג' עכו\\\"ם כתב עליו הר\\\"א בגמ' מסקינן אפי' לג' ישראל והאמת דר\\\"נ הכי ס\\\"ל התם והלכתא כוותיה בדיני ואולי מפני שרבא חולק בההוא דר\\\"נ וכו'. ואני אומר שלא היה צריך ה\\\"ה להכריע דבר זה מדעתו ולכתבו בלשון אולי שהרי בפירוש כתב הרי\\\"ף ואוקמה רב מנשיא כר' יעקב בג' עכו\\\"ם ור\\\"נ אמר אפי' בג' ישראל ואזדא ר\\\"נ לטעמיה וכו' ורבא פליג עליה אפי' ג' חייב להכריז וכו' והלכתא כרבא דבתרא הוא עכ\\\"ל:\",1,0],[8,382,17,1,\"כל מציאה שאמרנו בה וכו' אבל אם ראה את המציאה אפילו נפל עליה וכו'. כתב הרב המגיד משנה מפורשת פרק שנים אוחזין וכו' סתם נראה שהוא סומך על האוקימתא הראשונה וכו'. אין דברי הרב המגיד נראין בכאן דא\\\"כ לא ה\\\"ל לרבינו לכתוב אפי' נפל עליה ומדכתב לשון אפילו הדבר ברור דלא תפס כאוקימתא קמייתא:\",1,0],[8,382,17,5,\"שנים שראו גמל או חמור של מציאה וכו'. כתב ה\\\"ה והכוונה שבגמל גופיה אם היו שני מנהיגים קנו שניהם וכו'. דעתו לומר שרבינו מפרש דכי אמרינן לערבינהו וליתנינהו שנים שהיו מושכים ומנהיגים בין בגמל בין בחמור היינו לומר דאי תנא הכי הוה משתמע דבין היו שניהם מושכים בגמל ובחמור ובין שניהם מנהיגים בגמל בין היה אחד מושך ואחד מנהיג בין בגמל בין בחמור קנו שניהם וכי מתרץ איכא חד צד דלא קני היינו לומר דנהי אם היו שניהם מושכים בגמל או בחמור וכן אם שניהם הנהיגו בגמל או בחמור קנו שניהם מיהו היכא דאחד משך ואחד הנהיג חד קני וחד לא קני איכא דאמרי מושך בחמור כלומר שאם אחד משך ואחד הנהיג החמור מנהיג קני מושך לא קני אבל בגמל אפי' אחד מושך ואחד מנהיג קנו שניהם איכא דאמרי הנהגה בגמל כלומר שאם אחד משך ואחד הנהיג הגמל מושך קני מנהיג לא קני אבל בחמור אפי' אחד מושך ואחד מנהיג קנו שניהם ופסק כלישנא בתרא. ויש לתמוה למה לא כתב רבינו בפ\\\"ב דמכירה שהבהמה נקנית בהנהגה ודוחק לומר שרבינו מחלק לומר דהנהגה קני דוקא במציאה והפקר דמנא ליה הא. ושמא י\\\"ל שסמך על מ\\\"ש פה ויותר נראה לומר שמ\\\"ש בפ\\\"ב מהל' מכירה או הכישה במקל ורצה לפניו היינו הנהגה:\",1,0],[8,382,17,5,\"כתב הר\\\"ן דלהרי\\\"ף רכוב לחודיה קני ורכוב ומנהיג יחלוקו כסתמא דמתני' וכ\\\"נ מדברי הרמב\\\"ם פי\\\"ז מהל' גזילה עכ\\\"ל. וגם ה\\\"ה כתב פה שרבינו סובר כהרי\\\"ף דרכוב קני אפי' אינו מנהיג ברגליו. ונראה שהבינו כן בדברי רבינו מדנקט רוכב סתם משמע אפי' אינו מנהיג ובפ\\\"ב מהל' מכירה כתב בהדיא כיצד קונים את הבהמה במשיכה אצ\\\"ל אם משכה והלכה או שרכב עליה והלכה בו ויש מקום לבעל דין לחלוק דוהלכה בו שכתב בפ\\\"ב מהל' מכירה היינו ע\\\"י שהנהיגה ברגליו ומ\\\"ש פה היה אחד רוכב היינו במנהיג ברגליו וסמך על מ\\\"ש בפ\\\"ב מהל' מכירה. ונראה שאפי' לדעת הר\\\"ן וה\\\"ה בדברי רבינו רוכב לא קנה אא\\\"כ הלכה כמ\\\"ש בפ\\\"ב מהל' מכירה והלכה ומיהו בעקירת יד ורגל סגי שכך כתב אין צ\\\"ל אם משכה והלכה בו שקנה אלא אפילו שקרא לה ובאה או שהכישה במקל ורצה לפניו כיון שעקרה יד ורגל קנאה וקרא לה ובאה לא חשיב כמו רכב עליה דהא בלשון אפילו קאמר לה וכיון דבקרא לה ובאה כיון שעקרה יד ורגל קנה כ\\\"ש ברכב:\",2,0],[8,382,17,8,\"חצירו של אדם קונה לו וכו'. כתב ה\\\"ה ופירוש דבעינן תרתי בחצר שאינה משתמרת וכו' ול\\\"נ דאלימא קניית הד' אמות טפי מפני שהוא יכול לנטות עצמו וליטלה וכן עיקר עכ\\\"ל. ול\\\"נ טעם אחר דארבע אמות שאני דכיון דמשום דלא אתי לאינצויי תקינו רבנן דליקני לא ראו לחלק בין אמר ללא אמר דא\\\"כ אכתי הוו אתו לאינצויי:\",1,0],[8,382,17,8,\"כתב נימוקי יוסף על מתניתין דאמר זכתה לי שדי כתב הרנב\\\"ר דדוקא דאמר הכי כיון דצבי וגוזלות הללו מהלכים הם כל שהוא מתעורר לקנותם משתמרים לו דאי רץ אחריהם [מגיעם] כדאיתא בגמרא ואם לא אפי' עומד בצד שדהו אינה משתמרת לו ואינו דומה ליד דידו משתמרת וזו אינה משתמרת וכך הם דברי הרמב\\\"ם בפרק י\\\"ז מהלכות גזילה. מה שכתב שכך הם דברי הרמב\\\"ם אינו מחוור שהרי לטעמו של הר\\\"ן דוקא בהני שהם מהלכים הוא דבעי דלימא זכתה לי שדי אבל במציאה שאינה מהלכת כלל אפילו לא אמר הכי קני ואילו לדברי רבינו אפילו במציאה שאינה מהלכת צריך שיאמר זכתה לי שדי שהרי סתם וכתב ואם נפלה שם מציאה הרי היא של בעל החצר ועל זה כתב שאם לא אמר זכתה לי שדי כל הקודם זכה:\",2,0],[8,382,17,10,\"כתב ה\\\"ה קטנה יש לה חצר וכו'. דין קטן וקטנה מפורשים הם וכו'.\",1,0],[8,382,17,10,\"ומ\\\"ש וארבע אמות של אדם כחצירו לענין מציאה. אפשר שרמז בזה למה שכתבו הראשונים שאין ד\\\"א קונות כל זמן שיש בה דעת אחרת מקנה וכו'. תמהני על ה\\\"ה שהרי רבינו בפ\\\"ד מהלכות זכיה כתב שארבע אמות קונות לענין מתנה:\",2,0],[8,382,17,13,\"מציאת בנו ובתו וכו' ומציאת בתו הנערה אע\\\"פ שאינה סומכת על שולחנו. בפרק נערה שנתפתתה אהא דתנן האב זכאי בבתו במציאתה יהיב טעמא בגמ' (דף מ\\\"ז) משום איבה ופירש\\\"י משום איבה דכיון דאינו חייב במזונותיה אי אמרת מציאתה שלה איכא איבה ולא זיין לה תו, וכתבו התוספות ולר\\\"י נראה איבה דמציאתה היינו שלא יקדשנה למנוול ומוכה שחין והא דאמרינן גבי מציאת בנו ובתו הקטנים לא קטן קטן ממש אלא גדול וסומך על שלחן אביו קטן הוא היינו דוקא בקטן אבל בקטנה אפי' אינה סמוכה על שלחן אביה הויא מציאה לאב משום איבה שלא יקדשנה למנוול ומוכה שחין עכ\\\"ל. ודברי רבינו כדברי ר\\\"י:\",1,0],[8,382,17,13,\"ומ\\\"ש ואפי' היתה מכורה אמה. בפ\\\"ק דמציעא (דף י\\\"ב:) גבי הא דתנן מציאת עבדו ושפחתו העברים הרי אלו שלהם האי שפחה היכי דמיא אי דאייתי שתי שערות מאי בעיא גביה ואי דלא אייתי שתי שערות אי איתיה לאבוה דאבוה הוא לעולם דאיתיה לאב ומאי הרי הן שלהן לאפוקי דרבה ופירש\\\"י לאפוקי שאינו של רבה אלא של אביה וקרי ליה שלהן משום דאב מינה קזכי:\",2,0],[8,382,17,13,\"סליקו הלכות גזלה ואבדה בס\\\"ד\",3,0],[8,383,1,1,\"כל הורג נפש וכו'. ומ\\\"ש מיתתו בסייף. בפרק אלו הנשרפין (דף ע\\\"ו:) במתני' מני רוצח בהדי נהרגין.\",1,0],[8,383,1,1,\"ומ״ש שנאמר נקום ינקם מפי השמועה למדו שזו מיתת סייף. בפרק ארבע מיתות (סנהדרין דף נ״ב ע״ב).\",2,0],[8,383,1,1,\"ומ\\\"ש בין שהרג חבירו בברזל בין ששרפו באש מיתתו בסייף. הכי משמע במתני' פרק אלו הן הנשרפין ובסיפרי פרשת מסעי על פסוק ואם באבן יד הכהו:\",3,0],[8,383,1,2,\"מצוה ביד גואל הדם וכו' שנאמר גואל הדם הוא ימית את הרוצח. בפ' נגמר הדין (דף מ\\\"ה:) ובספרי פן ירדוף גואל הדם מצוה ביד גואל הדם לרדוף.\",1,0],[8,383,1,2,\"ומ\\\"ש וכל הראוי לירושה הוא גואל הדם.. לא רצה גואל הדם וכו' ב\\\"ד ממיתין את הרוצח בסייף. פ' נגמר הדין מצוה בגואל הדם ומנין שאם אין לו גואל שב\\\"ד מעמידין לו גואל שנאמר בפגעו בו מכל מקום:\",2,0],[8,383,1,3,\"האב שהרג את בנו וכו'. בסוף פ' אלו הן הגולין (מכות דף י״ב).\",1,0],[8,383,1,3,\"ומ\\\"ש ואחד הזכר ואחד הנקבה בגאולת הדם:\",2,0],[8,383,1,4,\"ומוזהרים ב\\\"ד שלא ליקח כופר מן הרוצח וכו' ואפי' רצה גואל הדם לפטרו. (בכתובות פ\\\"ג) (דף ל\\\"ז:):\",1,0],[8,383,1,5,\"רוצח שהרג בזדון אין ממיתין אותו העדים ולא הרואין אותו עד שיבוא לבית דין וכו'. בפרק אלו הן הגולין (מכות דף י״ב) ועוד תניא בסיפרי לפי שהוא אומר ורצח גואל הדם שומע אני יהרגנו בינו לבין עצמו תלמוד לומר ולא ימות הרוצח עד עמדו לפני העדה.\",1,0],[8,383,1,5,\"ומ\\\"ש והוא הדין לכל חייבי מיתות בית דין. שם יכול יהרוג אותו משהרג ומשנאף תלמוד לומר ולא ימות הרוצח עד עמדו וכו':\",2,0],[8,383,1,6,\"ומ״ש אבל הרודף אחר חבירו להרגו וכו'. שם ובפ' בן סורר ומורה (סנהדרין דף ע״ב:) במשנה.\",1,0],[8,383,1,6,\"ומ\\\"ש ואפילו היה הרודף קטן. פרק בן סורר ומורה אמר רב הונא קטן הרודף ניתן להצילו בנפשו קסבר רודף א\\\"צ התראה לא שנא גדול ולא שנא קטן:\",2,0],[8,383,1,8,\"ומ״ש ואם יכולין להצילו באבר מאיברי הרודף וכו'. בסוף פ' נגמר הדין (סנהדרין דף מ״ט) ובריש פ' המניח (בבא קמא דף כ״ח) ובס״פ בן סורר ומורה (סנהדרין דף ע״ד).\",1,0],[8,383,1,8,\"ומ\\\"ש אע\\\"פ שלא הרג. אין לשון אע\\\"פ נוח לי דאדרבא מפני שלא הרג עדיין הוא שהורגין כדי שלא יהרגנו דאילו כבר הרגו אינם רשאין להורגו וצ\\\"ל דה\\\"ק כיון שלא הרג לא היה ראוי להורגו ואע\\\"פ כן הורגין אותו כדי להציל את הנרדף.\",2,0],[8,383,1,8,\"ומ\\\"ש שנאמר וקצותה את כפה וכו' ואחד כל דבר שיש בו סכנת נפשות וכו'. בסיפרי:\",3,0],[8,383,1,9,\"ומ״ש לפיכך הורו חכמים שהאשה שהיא מקשה וכו'. בספ״ז דאהלות האשה שהיא מקשה לילד מחתכים את הולד במעיה ומוציאין אותו איברים איברים שחייה קודמין לחייו יצא ראשו אין נוגעין בו שאין דוחין נפש מפני נפש ובפ' בן סורר (סנהדרין דף ע״ב) אהא דאמר רב קטן הרודף ניתן להצילו בנפשו איתיביה יצא ראשו אין נוגעין בו שאין דוחין נפש מפני נפש שאני התם דמשמיא קא רדפי לה וזהו שכתב רבינו וזהו טבעו של עולם:\",1,0],[8,383,1,10,\"אחד הרודף אחר חבירו להרגו וכו'. משנה בס״פ בן סורר ומורה (סנהדרין דף ע״ב:) אלו הם שמצילים אותם בנפשם הרודף אחר חבירו להרגו או אחר הזכור או אחר נערה המאורסה אבל הרודף אחר הבהמה והמחלל את השבת והעובד ע״ז אין מצילים אותם בנפשם ויליף בגמרא מקרא דלכל עריות בין חייבי מיתות בין חייבי כריתות מצילין אותם בנפשם:\",1,0],[8,383,1,12,\"רדף אחר ערוה ותפסה ושכב עמה והערה וכו'. שם (דף ע\\\"ג) אחד הרודף אחר חבירו להרגו ואחר הזכור ואחר נערה מאורסה וכו' מצילין אותם בנפשו וכו' נעבדה בה עבירה אין מצילין אותן בנפשו זה הולך על השורש שקדם שמחוייבי מיתות שעברו ועשו אין ממיתין אותם עד שיגמר דינם בב\\\"ד וזה כיון שהערה כבר עשה העבירה:\",1,0],[8,383,1,12,\"רדף אחר ערוה וכו'. בס\\\"פ בן סורר ומורה פלוגתא דרבי יהודה ורבנן ופסק כרבנן ודבר פשוט הוא שמ\\\"ש באיבריו ה\\\"ק ומונעים אותו בחתיכת איבריו מלבעול:\",2,0],[8,383,1,13,\"כל היכול להציל באבר מאיבריו וכו'. שם (דף ע\\\"ד) ר' יונתן בן שאול אומר רודף שהיה רודף אחר חבירו להרגו ויכול להצילו באחד מאיבריו ולא הציל כלומר ולא הצילו אלא בנפשו נהרג עליו ומשמע לרבינו דאי אפשר לומר שב\\\"ד ממיתין אותו שמאחר שלא נתכוון אלא להציל לא שייך ביה התראה ולא נקט ר' יונתן בן שאול נהרג עליו אלא לומר שהוא חייב מיתה לשמים:\",1,0],[8,383,1,14,\"כל היכול להציל ולא הציל וכו'. בס״פ בן סורר ומורה (סנהדרין דף ע״ג) מניין לרואה את חבירו שהוא טובע בנהר או חיה גוררתו או לסטים באים עליו שהוא חייב להצילו ת״ל לא תעמוד על דם רעך והא מהכא נפקא מהתם נפקא אבידת גופו מנין ת״ל והשבותו לו אי מהתם ה״א ה״מ בנפשיה אבל מיטרח ומיגר אגורי אימא לא קמ״ל. וכתב הרא״ש והניצול חייב לפרוע למציל מה שהוציא דאין אדם חייב להציל נפש חבירו בממונו היכא דאית ליה ממונא לניצול וכתב הגהות מיימון עבר על לא תעמוד וכו' בירושלמי מסיק אפי' להכניס עצמו בספק סכנה חייב עכ״ל. ונראה שהטעם מפני שהלה ודאי הוא ספק:\",1,0],[8,383,1,15,\"הרואה רודף אחר חבירו להרגו וכו'..\",1,0],[8,383,2,1,\"כל ההורג חבירו בידו וכו' כגון שהכהו בסייף או באבן הממיתה או שחנקו וכו'. בסיפרי:\",1,0],[8,383,2,2,\"ומ״ש אבל השוכר הורג להרוג את חבירו או ששלח עבדיו והרגוהו. בפרק האיש מקדש (קידושין דף מ״ג) האומר לשלוחו צא הרוג את הנפש הוא חייב ושולחו פטור ואע״ג דמסיים בה שמאי הזקן אומר שולחו חייב פסק כת״ק ועוד דבחד לישנא אמרינן דמאי חייב בדיני שמים ודינא רבא ודינא זוטא איכא בינייהו.\",1,0],[8,383,2,2,\"ומ״ש או שכפתו והניחו לפני הארי וכו'. פרק הנשרפין (סנהדרין דף ע״ז) אמר רבא כפתו לפני ארי פטור.\",2,0],[8,383,2,2,\"ומ\\\"ש וכן ההורג את עצמו ומנין שכן הוא הדין שנאמר שופך דם האדם וכו':\",3,0],[8,383,2,4,\"וכל אלו הרצחנים וכיוצא בהם שאינם מחוייבים מיתת ב״ד אם רצה מלך ישראל ישתדל להורגם בדין המלכות וכו'.. וכן אם ראו ב״ד להרגם וכו'. בפרק נגמר הדין (סנהדרין דף מ״ו) ב״ד מכין ועונשים שלא מן התורה וכו' ומעשה באחד שרכב על הסוס בשבת בימי יוונים [והביאוהו לב״ד] וסקלוהו כך היא הגירסא האמיתית וכן כתבה רבינו בפכ״ד מהל' סנהדרין ולא כגירסא דספרים דידן ופירש״י שהשעה צריכה לכך שהיו פרוצים בעבירות שהיו רואים לחצן של ישראל שהיוונים גוזרים עליהם גזרות והוי מצות בזויות בעיניהם:\",1,0],[8,383,2,5,\"הרי שלא הרגם המלך ולא היתה השעה צריכה לכך וכו'..\",1,0],[8,383,2,6,\"אחד ההורג את הגדול או את הקטן בן יומו וכו' והוא שכלו לו חדשיו. בפרק יוצא דופן (נדה דף מ״ד) שנינו תינוק בן יום אחד ההורגו חייב ובגמרא דכתיב איש כי יכה כל נפש מ״מ ומסיים בה במתני' והרי הוא לאביו ולאמו ולכל קרוביו כחתן שלם ובגמ' למאי הלכתא אמר רב פפא לענין אבילות כמאן דלא כרשב״ג דאמר כל ששהה שלשים יום באדם אינו נפל הא לא שהה ספיקא הוי הכא במאי עסקינן דקים ליה שכלו לו חדשיו ועיין במ״ש ה״ה בפי״א מהל' יבום.\",1,0],[8,383,2,6,\"ומ\\\"ש בין זכר בין נקיבה:\",2,0],[8,383,2,8,\"אחד ההורג את הבריא או את החולה הנוטה למות וכו'. בפרק בן סורר ומורה (דף ע\\\"ח) ת\\\"ר הכוהו עשרה בני אדם בעשרה מקלות ומת בין בבת אחת בין בזה אחר זה פטורים ר' יהודה בן בתירא אומר בזה אחר זה האחרון חייב מפני שקירב מיתתו אמר רבא הכל מודים בהורג את הטריפה שהוא פטור בגוסס בידי שמים שהוא חייב לא נחלקו אלא בגוסס בידי אדם מר מדמי לה לטריפה ומר מדמי ליה לגוסס בידי שמים ופסק רבינו כת\\\"ק ואע\\\"ג דאמרינן התם תני תנא קמיה דרב ששת ואיש כי יכה כל נפש אדם להביא (את) המכה את חבירו וכו' ויש בו כדי להמית ובא אחר והמיתו שהוא חייב וסתמא כר\\\"י בן בתירא לאו משום דתהוי הלכתא כוותיה אלא לאשמועינן דיחידאה הוא.\",1,0],[8,383,2,8,\"ומ\\\"ש וכל אדם בחזקת שלם וההורגו נהרג וכו'. נראה שלמד כן מדתנן בספ\\\"ק דמכות (דף ז') ר\\\"ט ור\\\"ע אומרים אילו היינו בסנהדרין לא נהרג אדם מעולם ומפרש בגמ' דהוו שיילי לעדים ראיתם טריפה הרג או שלם ומשמע דלית הלכתא כוותייהו דמסיים בה ר\\\"ג אומר אף הם מרבים שופכי דמים בישראל:\",2,0],[8,383,2,9,\"אדם טריפה שהרג את הנפש נהרג וכו' עד אינה עדות. מימרא דרבה בפרק הנשרפים [סנהדרין דף ע\\\"ח]:\",1,0],[8,383,2,10,\"אחד ההורג את ישראל וכו'. במכילתא וכי יכה איש את עבדו אף עבדו ושפחתו בכלל שנאמר (והמית איש או אשה) והרי הכתוב מוצאו מכללו להקל עליו שיהא נידון ביום או יומים לכך נאמרה פרשה זו ויליף התם מקרא דבעבד כנעני הכתוב מדבר ואיתיה בספרי כמו שאכתוב בסמוך.\",1,0],[8,383,2,10,\"ומה שכתב ואם הרג בשגגה גולה. ברייתא בפרק ב' דמכות (דף ח':):\",2,0],[8,383,2,11,\"ישראל שהרג גר תושב וכו'. במכילתא וכי יזיד איש על רעהו רעהו להוציא את אחרים ומשמע לרבינו דגר תושב בכלל אחרים כמו שהוא לענין גלות כמו שיתבאר. איסי בן עקיבא אומר קודם מתן תורה היינו מוזהרים על שפיכות דמים לאחר מתן תורה שהוחמרו הוקלו באמת אמרו פטור מדיני בשר ודם ודינם מסור לשמים. וזהו שכתב\",1,0],[8,383,2,11,\"רבינו אינו נהרג עליו בב\\\"ד כלומר אבל בדיני שמים חייב.\",2,0],[8,383,2,11,\"ומה שכתב ואחד ההורג את עבד אחרים או ההורג את עבדו וכו'. בסיפרי פרשת מסעי על פסוק אם בשנאה יהדפנו משמע דמכה עבד אחרים דינו שוה למכה ישראל.\",3,0],[8,383,2,11,\"ומה שכתב שהעבד קבל עליו מצות ונוסף על נחלת ה', בא רבינו ליתן טעם למה חייבים על העבד ולא על גר תושב מפני שהעבד קבל עליו מצות ישראל ונוסף על נחלת ה' שהם ישראל מה שאין כן בגר תושב:\",4,0],[8,383,2,12,\"מה בין עבדו לעבד אחרים וכו' שנאמר לא יוקם כי כספו הוא ומהו יום או יומים. במכילתא:\",1,0],[8,383,2,16,\"המוכר עבדו ופסק עמו שישמשנו שלשים יום עד סוף הפרק. בפרק החובל (בבא קמא דף צ') פלוגתא דתנאי ופסק כר' אליעזר משום דמפרשי אמוראי טעמיה ובמכילתא הא דר״א בשם רבי יצחק בלי שום פלוגתא:\",1,0],[8,383,3,1,\"המכה את חבירו בזדון וכו' אומדים דבר שהכהו בו ומקום שהכהו עליו וכו'. בספרי [פ' מסעי]:\",1,0],[8,383,3,2,\"ומ\\\"ש כשם שאומדים החפץ שהכה בו וכו' כך אומדים כח ההכאה..\",1,0],[8,383,3,4,\"כלי ברזל לא נתנה בו תורה שיעור וכו'. בפרק הנשרפין (סנהדרין דף ע״ו) אמר שמואל מפני מה לא נאמר יד בברזל שהברזל ממית בכל שהוא וכו' וה״מ דברזיה מיברז ופירוש רש״י לא נאמרה יד בברזל כמו שנאמרה באבן יד בכלי עץ יד משמע שיש בה מלא אחיזה דבעינן שיעורא אבל ברזל כתיב ואם בכלי ברזל הכהו. דברזיה מיברז פנוש״ט בלעז אבל הכהו לאורכו דרך הכאה שיעורא בעינן:\",1,0],[8,383,3,5,\"המכה את חבירו בלא כלי והמיתו וכו'. הכי משמע בפרק הנשרפין (סנהדרין דף ע״ח:) במתניתא דנתכוין להכותו על מתניו ולא היה בה כדי להמית על מתניו וכו' נתכוון להכות את הגדול ולא היה כדי להמית את הגדול:\",1,0],[8,383,3,7,\"וכן הדוחף את חבירו מראש הגג וכו'..\",1,0],[8,383,3,8,\"אחד המכה את חבירו וכו'. בספרי פרשת מסעי על פסוק ואם באבן אשר ימות בה הכהו:\",1,0],[8,383,3,9,\"הדוחף את חבירו וכו' וכן אם כבש עליו וכו'. משנה וגמרא פרק הנשרפין (סנהדרין דף ע\\\"ו:).\",1,0],[8,383,3,9,\"ומה שכתב והוא הדין למניח ידו על פי חבירו וחוטמו וכו'. ומה שכתב או שכפתו והניחו בחמה או בצנה עד שמת. מימרא דרבא בפרק הנשרפין (סנהדרין דף ע״ז).\",2,0],[8,383,3,9,\"ומה שכתב או שבנה עליו מקום וכו'. נראה שפירש רבינו שזה בכלל מה שאמרו שם או באיבה לרבות המצמצם או שהוא נלמד מדין הכניסו לבית שיש דאיתיה התם וכתבו רבינו בסמוך אף על גב דהתם בעינן שהדליק עליו את הנר התם שאני שהיה פתח לביתא דשיישא אבל אם בנה לפני הפתח של ביתא דשיישא אע\\\"ג דלא אדליק ביה שרגא חייב.\",3,0],[8,383,3,9,\"ומה שכתב אבל הכופת את חבירו והניחו ברעב עד שמת או שכפתו והניחו במקום שסוף החמה או הצנה לבא שם וכו'. מימרא דרבא שם:\",4,0],[8,383,3,10,\"ומה שכתב או שכפה עליו גיגית או שפרע עליו את המעזיבה. שם אתמר כפה עליו גיגית [וכו' ופירש רש\\\"י] ומת בהבלא או שפרע עליו את המעזיבה והוא ישן ונכנסה שם הצנה פטור שההורג בא לאחר זמן [ע\\\"כ]. ופסק להקל בדיני נפשות ומ\\\"מ יש לתמוה מה בין כפה זה למה שכתב לעיל בסמוך שאם בנה עליו מקום עד שמנע ממנו הרוח שהוא חייב ושמא י\\\"ל שהבונה עליו מקום מכל צדדיו קודם שיסתום הכותל האחרון כבר נתמעט הרוח וכשסתם הכותל הרביעי אז כלה הרוח ונתרבה ההבל שהמיתו ולפיכך חייב משא\\\"כ בשכפה עליו גיגית וצ\\\"ע.\",1,0],[8,383,3,10,\"ומה שכתב או שהשיך עליו את הנחש. שם במשנה שיסה בו את הכלב שיסה בו את הנחש פטור השיך בו את הנחש ר' יהודה מחייב וחכמים פוטרין ובגמ' (דף ע\\\"ח) לדברי חכמים ארס נחש מעצמו הוא מקיא לפיכך נחש בסקילה והמכיש פטור ופירש רש\\\"י מעצמו מקיא בנשיפתו וכשהשיכו זה עדיין לא היה בו כדי להמית לפיכך גרמא בעלמא הוא אע\\\"פ שיודע שסופו להקיא מיהו לאו מכחו מיית:\",2,0],[8,383,3,11,\"ומ\\\"ש וכן הדוחף את חבירו בבור וכו'. מימרא דרבא שם (דף ע\\\"ז:):\",1,0],[8,383,3,12,\"הזורק צרור בכותל וכו' וכן אלו שמשחקין בכדור וכו'. מימרא וברייתא שם:\",1,0],[8,383,3,13,\"זרק אבן למעלה והלכה וכו'. מימרא דרב פפא שם:\",1,0],[8,383,3,13,\"הכופת את חבירו והניחו במקום וכו'. גם זה מימרא דרב פפא שם:\",2,0],[8,383,4,1,\"המתכוין להרוג את זה והרג את זה וכו'. בפרק הנשרפין (סנהדרין דף ע״ט) נתכוון להרוג את זה והרג את זה חייב ור״ש פוטר מאי טעמא דר״ש אמר קרא וארב לו וקם עליו עד שיתכוין לו ורבנן אמרי דבי ר' ינאי פרט לזורק אבן לגו ופירש״י פרט לזורק אבן לגו לתוך חבורת בני אדם עכו״ם וישראלים אבל נתכוון לישראל זה והרג את חבירו לא אתא קרא למעוטי ואמרינן תו בגמ' בשלמא לרבנן וכו' (ניחא) אלא לר״ש האי ונתת נפש תחת נפש מאי עביד ליה ממון וכדרבי ובתר הכי אמר רבא האי תנא דבי חזקיה מפקא מדרבי ומפקא מדרבנן דתנא דבי חזקיה מכה אדם ומכה בהמה מה מכה בהמה לא חלקת בה בין שוגג למזיד וכו' אף מכה אדם לא תחלוק בו בין שוגג למזיד בין מתכוין לשאין מתכוין בין דרך ירידה לדרך עליה לחייבו ממון אלא לפוטרו ממון מאי שאין מתכוין אילימא שאין מתכוין כלל היינו שוגג אלא פשיטא שאין מתכוין לזה אלא לזה וכו' שמע מינה לאו בר קטלא הוא ולאו בר ממונא הוא ומשמע קצת דרבא דבתרא הוא סבירא ליה כתנא דבי חזקיה ועוד דגמרא נקיט לה בפ' אלו נערות (כתובות דף ל״ה) לעיקר מהטעם שכתבו התוס' ולפיכך פסק כמותו ומעתה נתיישב מה שהשיג הראב״ד על רבינו למה פסק כר״ש אבל קשה מ״ש הזורק אבן לתוך עדה מישראל וכו' והא שם אליבא דמאן דאמר נתכוון להרוג את זה והרג את זה פטור אמרינן קאי ראובן ושמעון ואמר לחד מינייהו או כסבור ראובן ונמצא שמעון פטור עד שיאמר לפלוני אני מתכוין וא״כ למה כתב רבינו הזורק לתוך עדה מישראל פטור הא בהני גווני דעדיפי מינה פטור לכך נ״ל שפסק כרבנן וטעמא דזורק אבן לגו פטור משום דלא שייך ביה התראה ולאפוקי ממ״ש רש״י בספ״ק דכתובות (דף ט״ו) והיינו דנקט רבינו לתוך עדה מישראל לומר דאפילו כולם ישראלים פטור מטעמא דאמרן ואע״ג דלישנא דנקט רבינו המתכוין להרוג את זה והרג את זה פטור הוי לישנא דר״ש אין בכך כלום דלר״ש הוי מטעם אחר ולדידן הוי מטעמא אחרינא:\",1,0],[8,383,4,2,\"נתכוין להכות את חבירו על מתניו וכו' פטור ממיתת ב\\\"ד. משנה שם.\",1,0],[8,383,4,2,\"ומ״ש ואינו גולה וכו'. בר״פ אלו הן הגולין (מכות דף ז':) בבלי דעת פרט למתכוין להרוג את הבהמה והרג את האדם לעכו״ם והרג ישראל לנפל והרג בן קיימא.\",2,0],[8,383,4,2,\"ומ״ש אבל אם נתכוון להכותו על מתניו וכו' הרי זה נהרג. משנה בפרק הנשרפין (סנהדרין דף ע״ט):\",3,0],[8,383,4,3,\"המכה את חבירו באבן וכו'. ברייתא בפרק הנשרפין (סנהדרין דף ע״ח:) אמדוהו למיתה אומדין אותו לחיים לחיים אין אומדין אותו למיתה ופירש״י אין אומדין אותו למיתה לומר טעינו באומד ראשון לחייבו שהרי יצא מב״ד זכאי ואמרינן מחמת חולי אחר שבא עליו הכבידה המכה.\",1,0],[8,383,4,3,\"ומה שכתב ואם אמדוהו למיתה אוסרין את המכה בבית הסוהר מיד. שם אם יקום והתהלך בחוץ על משענתו ונקה המכה וכי תעלה על דעתך שזה מהלך בשוק וזה נהרג אלא וכו' מלמד שחובשין אותו ופי' רש\\\"י דמשמע לכשיקום ונקה מכלל דעד השתא חבוש הוא והכי איתא במכילתא:\",2,0],[8,383,4,4,\"ומ\\\"ש זה שנאמר בתורה על משענתו אינו שיהלך והוא נשען וכו'. כן תרגם אונקלוס על משענתו על בורייה והכי איתא במכילתא:\",1,0],[8,383,4,5,\"אמדוהו למיתה והקל ממה שהיה ולאחר וכו'. משנה שם (דף ע\\\"ח) המכה את חבירו וכו' ואמדוהו למיתה והיקל ממה שהיה ולאחר מכאן הכביד ומת חייב ר' נחמיה אמר פטור שרגלים לדבר ופסק רבינו כת\\\"ק אלא שמה שסיים וכתב שרגלים לדבר קשה לי דבמתני' משמע שהם סיום דברי רבי נחמיה וכן פירש\\\"י וצ\\\"ל שרבינו מפרש שסיום דברי ת\\\"ק הם וה\\\"ק שרגלים לדבר שמת מחמת מכה זו שהרי מתחלה אמדוהו למיתה:\",1,0],[8,383,4,6,\"הכוהו עשרה בני אדם וכו'. שם פלוגתא דתנאי ופסק כתנא קמא.\",1,0],[8,383,4,6,\"ומ\\\"ש והוא הדין לשנים שדחפוהו וכו'. פשוט הוא מדאמרינן בגמרא דטעמא דת\\\"ק משום דכתיב ואיש כי יכה כל נפש אדם כל נפש עד דאיכא כל נפש.\",2,0],[8,383,4,6,\"ומ\\\"ש או שהיו רבים יושבים ויצא חץ מביניהם וכו'. גם זה שם (דף פ'):\",3,0],[8,383,4,7,\"זרקו בו עשרה אבן זה אחר זה וכו'. כך היא הגירסא בספרי רבינו המדוייקים והדין שם (דף ע\\\"ח) ואיש כי יכה כל נפש אדם להביא המכה את חבירו ואין בו כדי להמית ובא אחר והמיתו שהוא חייב:\",1,0],[8,383,4,7,\"רוצח שנגמר דינו וכו'. שם (דף ע\\\"ט:) במשנה רוצח שנתערב באחרים כולם פטורים ר' יהודה אומר כונסין אותם לכיפה ובגמ' מאן אחרים אילימא אחרים כשרים פשיטא ותו בהא לימא רבי יהודה כונסין אותם לכיפה א\\\"ר אבהו אמר שמואל הכא ברוצח שלא נגמר דינו שנתערב ברוצחים אחרים שנגמר דינם עסקינן רבנן סברי אין גומרים דינו של אדם שלא בפניו הילכך כלם פטורים ור\\\"י מיפטרינהו לגמרי נמי לא כיון דרוצחים נינהו הילכך כונסין אותם לכיפה ופסק כת\\\"ק.\",2,0],[8,383,4,7,\"ומ\\\"ש ואוסרין את כולן. זה ע\\\"פ מ\\\"ש בפרק זה שאוסרין את המכה בבית הסוהר מיד:\",3,0],[8,383,4,8,\"ההורג נפשות ולא היו שם עדים וכו'. משנה שם (דף פ\\\"א:) ההורג נפשות שלא בעדים מכניסין אותו לכיפה ומאכילין אותו לחם צר ומים לחץ ובגמ' מנא ידעינן אמר רב בעדות מיוחדת ושמואל אמר שלא בהתראה ורב חסדא אמר [אבימי כגון] דאתכחוש בבדיקות ולא בחקירות ומשמע לרבינו דמר אמר חדא ומר אמר חדא ולא פליגי. ומפרש בגמ' דנותנין לו לחם צר ומים לחץ עד שיוקטן מעיינו והדר מאכילין אותו שעורים עד שכריסו מתבקעת. ומפרש רבינו עדות מיוחדת שלא ראו אותו עדים כאחד אלא זה אחר זה ורש\\\"י פירש עדות מיוחדת שנים רואין אותו אחד מחלון זה ואחד מחלון זה אבל ע\\\"פ עד אחד דבה בעלמא הוא:\",1,0],[8,383,4,10,\"האפיקורוסין והם עובדי ע\\\"ז וכו'. בפ\\\"ב דע\\\"ז (דף כ\\\"ו) תני ר' אבהו קמיה דר\\\"י העכו\\\"ם ורועי בהמה דקה לא מעלין ולא מורידין אבל האפיקורוסים והמסורות והמומרים מורידין ולא מעלין א\\\"ל אני שונה לכל אבידת אחיך לרבות את המומר ואת אמרת מורידין סמי מכאן מומר ולישני ליה כאן במומר אוכל נבילות לתיאבון כאן במומר אוכל נבילות להכעיס קסבר אוכל נבילות להכעיס אפיקורוס הוא כלומר והא תנא ליה רישא אתמר מומר פליגי רב אחא ורבינא חד אמר לתיאבון מומר להכעיס אפיקורוס הוי וחד אמר אפילו להכעיס נמי מומר אלא איזהו אפיקורוס זה העובד ע\\\"ז ומדברי רבינו נראה שהיה גורס אפיקורוס במקום המסורות אמר מר מורידין אבל לא מעלין השתא אחותי מחתינן אסוקי מבעיא אמר רב יוסף בר חמא וכו' לא נצרכה שאם היתה מעלה בבור מגררה דנקיט ליה עילא ואמר לא תיחות חיותא עלה רבה ורב יוסף דאמרי תרוייהו לא נצרכה שאם היתה אבן ע\\\"פ הבור מכסה אמר לעבורי חיותא עליה רבינא אמר שאם היה סולם בבור מסלקו אמר בעינא לאחותי ברי מאיגרא ופי' רש\\\"י שאם היה מעלה בבור עשויה בקרקע ויכול לעלות מגררה והאי לא מעלין דקאמר אין מניחין לעלות קאמר עכ\\\"ל. ורבינו תפס ההיא דרבינא שהיא היותר מצויה ומינה נשמע לשארא:\",1,0],[8,383,4,11,\"ודקדק רבינו לכתוב העכו\\\"ם שאין בינינו וביניהם מלחמה כלומר דהא דתניא בסוף קדושין ובמ\\\"ס טוב שבעכו\\\"ם הרוג היינו בשעת מלחמה וכמ\\\"ש התוספות בשם הירושלמי ובפלוגתא דרב אחא ורבינא פסק כמאן דאמר מומר להכעיס אפיקורוס הוא משום דסברא הוא שכיון שעושה להכעיס אפיקורסות נזרקה בו ועוד דר' אבהו ור\\\"י סברי הכי:\",1,0],[8,383,4,12,\"ומ\\\"ש רבינו בישראל בעל עבירה העומד ברשעו וכו' אבל ישראל בעל עבירות שאינו עומד ברשעו תמיד אלא עושה עבירות להנאת עצמו וכו' מצוה להצילו. איכא למידק דרישא נמי עושה להנאת עצמו הוא דהא רועי בהמה דקה מחמת חמדת ממון הם עושים וי\\\"ל שאע\\\"פ שאלו ואלו עושין לתיאבון רישא עומד ברשעו תמיד וסיפא אינו עומד ברשעו תמיד והתנה בסיפא לתיאבון לאפוקי שאם אוכל נבילות להכעיס אע\\\"פ שאינו עומד ברשעו תמיד הרי הוא בכלל האפיקורוסים כמו שקדם ומצוה להרגו:\",1,0],[8,383,5,1,\"כל ההורג בשגגה גולה וכו'..\",1,0],[8,383,5,2,\"אין הרוצח בשגגה גולה וכו' אפילו שחט בו כל שני הסימנין וכו'. בפרק מי שאחזו (גיטין דף ע':) תניא שחט בו שנים או רוב שנים הרי זה אינו גולה וכו' משום דחיישינן שמא הרוח בלבלתו א\\\"נ הוא קירב מיתתו מאי בינייהו איכא בינייהו דשחטיה בביתא דשיישא ופירכס א\\\"נ דשחטיה בברא ולא פרכס ולמד משם כל מיני רציחה במכל שכן. וכתב הראב\\\"ד נמצא לדבריו מה שאמרו וכו' טעמו שהוא סובר שאם אינו גולה ע\\\"י כך ג\\\"כ אינו נהרג על ידי כך ומשום הכי מקשה לרבינו ממה שאמרו חובשין אותו ולא ידעתי אמאי לא אקשי ליה ממאי דמוקי ההיא דמלמד שחובשין אותו לענין גלות ולי נראה שדעת רבינו שלא אמרו ההיא דשחט בו שנים או רוב שנים אלא לענין גלות בלבד דאם לא כן לינקוט ברייתא אינו נהרג על ידו וכן כתבו שם התוספות דוקא בגלות חיישינן להני טעמי אבל במזיד לעולם חייב ושמא יש שום דרשא גבי גלות כמו שיש חילוק בין גלות למיתה לענין ירידה ועליה וכתבו עוד והא דמשמע באלו נערות כי מוקי ונקה המכה בשוגג דחייב גלות אפילו לא מת לאלתר מיירי בביתא דשיישא וכגון דלא פרכס:\",1,0],[8,383,5,3,\"ישראל שהרג בשגגה את העבד או את גר תושב וכו'. משנה בפ' אלו הן הגולין (מכות דף ח':) הכל גולין ע״י ישראל וישראל גולין על ידיהם חוץ מע״י גר תושב וגר תושב אינו גולה אלא ע״י גר תושב ובגמ' הכל גולין ע״י ישראל לאתויי מאי לאתויי עבד ומשמע דקאי נמי למאי דקתני וישראל גולין על ידיהם ואמרינן תו בגמ' (דף ט') חוץ מע״י גר תושב אלמא גר תושב עכו״ם הוא אימא סיפא גר תושב גולה ע״י גר תושב ל״ק כאן בגר תושב שהרג גר תושב כאן בגר תושב שהרג ישראל ופירש רש״י חוץ מגר תושב ומשמע דמתרוייהו ממעט ליה דלא הוא גולה ע״י הריגתו אלא נהרג ולא ישראל גולה עליו. ל״ק וכו' גר תושב שהרג גר תושב גולה כדקתני בהדיא ורישא כשהרג את ישראל אינו גולה דלא סגי ליה בגלות עכ״ל. וכתב הראב״ד א״א אין נ״ל כן מן ההלכה וכו'. ולי קשה דמתני' הוא הכל גולין ע״י ישראל וישראל גולין על ידיהם חוץ מע״י גר תושב הרי בהדיא שישראל אינו גולה ע״י גר תושב וכן העבד דינו כישראל כמו שנתבאר בפ' ב' וא״כ אינו גולה ע״י גר תושב וכן קשה על מ״ש שגר תושב שהרג את העבד גולה מאחר שעבד הוא כישראל הרי הוא בכלל מה ששנינו וישראל גולין על ידיהם חוץ מע״י גר תושב. ונ״ל שט״ס יש בכאן וכך צריך להגיה ולכתוב ישראל שהרג בשגגה את העבד גולה וצריך למחוק משם גר תושב ומ״מ מ״ש שהעבד גולה ע״י גר תושב ושגר תושב גולה ע״י העבד אפשר לקיימו מפני שהעבד אינו כישראל גמור אבל צ״ע מנין לרבינו לחלק בכך:\",1,0],[8,383,5,4,\"גר תושב שהרג את ישראל בשגגה וכו'. בסיפרי ולגר ולתושב אי כשם שגולה ע״י ישראל כך ישראל גולה על ידו אמרת אם כשהרגו ישראל פטור ק״ו שלא יגלה אלא אם הרגו ישראל הרג ואם הוא הרג את ישראל נהרג ונ״ל דהכי פירושה מדכתיב לגר ולתושב הייתי שומע שגולה ע״י ישראל וישראל גולה על ידו אבל אי אפשר לומר כן משום דאם כשהרגו ישראל במזיד פטור דוכי יזיד איש על רעהו כתיב ולא עכו״ם ק״ו שלא יגלה על ידו כשהרגו בשגגה הילכך על כרחך לומר דאין ישראל גולה ע״י גר תושב ופטור הוא ולא הוא גולה על ישראל אלא נהרג וכי כתיב לגר ולתושב לענין גר תושב שהרג גר תושב בלבד הוא דכתיב ובפרק אלו הן הגולין (מכות דף ט') רמו קראי אהדדי כתיב לבני ישראל ולגר ולתושב בתוכם תהיינה שש הערים וכתיב והיו לכם הערים למקלט לכם ולא לגרים וכו' ל״ק כאן בגר תושב שהרג ישראל כאן בגר תושב שהרג גר תושב ורמינהו לפיכך גר ועכו״ם שהרגו נהרגין קתני גר דומיא דעכו״ם מה עכו״ם ל״ש דקטל בר מיניה ל״ש דקטל דלאו בר מיניה נהרג אף גר ל״ש דקטל בר מיניה לא שנא דקטל לאו בר מיניה נהרג וכו' אמר רבא פרט לאומר מותר א״ל אביי אומר מותר אנוס הוא א״ל שאני אומר קרוב למזיד הוא ופירש״י לפיכך אשבע מצות שנצטוו בני נח קאי וקי״ל אזהרתן זו מיתתן לפיכך גר תושב או עכו״ם שהרגו נהרגין ואפילו בשוגג שאין בני נח צריכים התראה כדאמרינן בסנהדרין ופירש״י באומר מותר [נהרג] דלאו בר גלות הוא.\",1,0],[8,383,5,4,\"ומ\\\"ש וכן גר תושב שהרג גר תושב מפני שעלה על דעתו שמותר להרגו ה\\\"ז וכו'. נתבאר בסמוך לרבא דהלכתא כוותיה לגבי אביי ואע\\\"ג דרב חסדא סבר כאביי.\",2,0],[8,383,5,4,\"ומ\\\"ש עכו\\\"ם שהרג את העכו\\\"ם בשגגה אין וכו'. נתבאר בסמוך:\",3,0],[8,383,5,5,\"הבן שהרג את אביו וכו'. משנה פ' אלו הן הגולין (מכות דף ח':) האב גולה ע״י בן והבן גולה ע״י האב ובגמרא והא אמרת יצא האב המכה את בנו דגמיר והא אמרת אף ע״ג דגמיר מצוה קא עביד (דכתיב יסר בנך ויניחך וגו') בשוליא דנגרי שוליא דנגרי חיותיה הוא דגמיר אומנותא אחריתי.\",1,0],[8,383,5,5,\"ומ\\\"ש אבל אם יסר את בנו כדי ללמדו תורה וכו'. משנה שם (ע\\\"א) ואשר יבא את רעהו ביער מה חטבת עצים רשות אף כל רשות יצא האב המכה את בנו והרב המכה את תלמידו ושליח ב\\\"ד ומפרש רבינו דשליח בית דין היינו שהכה את בעל דין הנמנע מלבא לב\\\"ד. והראב\\\"ד ז\\\"ל כתב א\\\"א זו לא שמענו מעולם וכו'. ואין לו שמענו השגה:\",2,0],[8,383,5,7,\"בתחלה אחד שוגג ואחד מזיד מקדימין לערי מקלט וכו'. משנה שם (דף ט' ע\\\"ב) ופירש רש\\\"י בתחלה כלומר תחלת משפט כל הרוצחים ואפילו מזידים ויליף טעמא בסיפרי מוארב לו וגו' ונס אל אחת וגו':\",1,0],[8,383,5,8,\"ומה שכתב כשמשיבין אותו מוסרין לו שני תלמידי חכמים וכו'. משנה וברייתא שם:\",1,0],[8,383,5,9,\"רוצח בשגגה שהרגו גואל הדם חוץ וכו'. שם (דף י':) אמר רב הונא רוצח שגלה לעיר מקלט ומצאו גואל הדם והרגו פטור קסבר ולו אין משפט מות בגואל הדם הוא דכתיב ופירש\\\"י בגואל הדם הכתוב מדבר וה\\\"ק פן ירדוף גואל הדם אחרי הרוצח והשיגו והכהו נפש ולא יתיירא מב\\\"ד כי לו אין משפט מות וסוף המקרא האומר כי לא שונא הוא וגו' מוסב על ראשו פן ירדוף גואל הדם אני אומר לך להכין לו הדרך כי לא שונא הוא לו ולא הרגו מדעת:\",1,0],[8,383,5,10,\"נכנס לעיר מקלטו ויצא חוץ לתחום בזדון הרי וכו'. משנה שם (דף י\\\"א:) רוצח שיצא חוץ לתחום ומצאו גואל הדם ר\\\"י הגלילי אומר מצוה ביד גואל הדם רשות ביד כל אדם ר\\\"ע אומר רשות ביד גואל הדם וכל אדם אין חייבים עליו בגמ' (דף י\\\"ב) מ\\\"ט דר\\\"י הגלילי מי כתיב אם רצח ור\\\"ע וכי כתיב ירצח וכו' ת\\\"ר אם יצוא יצא הרוצח אין לי אלא במזיד בשוגג מנין ת\\\"ל אם יצוא יצא מ\\\"מ והתניא במזיד נהרג בשוגג גולה לא קשיא הא כמאן דאמר אמרינן דברה תורה כלשון בני אדם הא כמאן דאמר לא אמרינן דברה תורה כלשון בני אדם אמר אביי מסתברא כמאן דאמר דברה תורה כלשון בני אדם שלא יהא סופו חמור מתחלתו מה תחלתו במזיד נהרג בשוגג גולה אף סופו במזיד נהרג בשוגג גולה ופירש\\\"י סופו צאתו חוץ לתחום תחלתו הרציחה. ופסק רבינו כר\\\"ע וכאביי דאמר מסתברא כמאן דאמר שאם יצא במזיד נהרג ואם יצא בשוגג אינו נהרג ואע\\\"ג דאיתא התם אמר מר זוטרא בר טוביה אמר רב רוצח שיצא חוץ לתחום ומצאו גואל הדם והרגו נהרג עליו כמאן לא כר\\\"י הגלילי ולא כר\\\"ע הוא דאמר כי האי תנא דתניא ר\\\"א אומר עד עמדו לפני העדה למשפט מה ת\\\"ל לפי שנאמר ורצח גואל הדם את הרוצח יכול מיד ת\\\"ל עד עמדו לפני העדה למשפט והיה נראה לפסוק הלכתא כר\\\"א מאחר דרב דרבן של כל בני גולה הוא קאי כוותיה וכדאשכחן בפ' חבית ובשאר דוכתין דפסקינן כרב דפליג אסתם מתני' מ\\\"מ לא חש רבינו להא מכמה טעמים חדא משום דר\\\"א שמותי הוא ועוד דמדחזי' דרבי אייתי במתני' דר\\\"י הגלילי ור\\\"ע ולא אייתי דר\\\"א משמע דלא סבר לה כוותיה כלל ועוד דאביי דבתרא הוא אתי דלא כר\\\"א:\",1,0],[8,383,5,11,\"ומ\\\"ש הרגו בתוך תחום עיר מקלטו וכו'. זה פשוט דאל\\\"כ מאי אהני ליה עיר מקלט:\",1,0],[8,383,5,12,\"המזבח קולט וכו'. שם אמר רב יהודה אמר רב שתי טעיות טעה יואב באותה שעה דכתיב וינס יואב אל אהל ה' ויחזק בקרנות המזבח טעה שאינו קולט אלא גגו והוא תפס בקרנותיו טעה שאינו קולט אלא מזבח בית עולמים והוא תפס במזבח של שילה אביי אמר בהא נמי מיטעא טעה טעה שאינו קולט אלא כהן ועבודה בידו והוא זר הוי.\",1,0],[8,383,5,12,\"ומ\\\"ש לפיכך ההורג בשגגה וקלטו מזבח והרגו שם ה\\\"ז נהרג עליו וכו':\",2,0],[8,383,5,14,\"וכן מי שקלטו המזבח אין מניחים אותו שם. בד״א במחוייב גלות אבל מי שפחד מן המלך וכו' וברח למזבח ונסמך לו ואפי' היה זר ה״ז ניצל וכו'. יש לתמוה שזו טענה טובה ליואב לומר שלא טעה והיאך אמרו שטעה ועוד שא״כ לא היו יכולין לקחתו משם להמיתו שהרי לא הרג בהתראה לאבנר ועמשא וצ״ע. והתוס' כתבו בס״פ נגמר הדין (סנהדרין דף מ״ח:) על הא דקאמר מאי [טעמא] קטלתיה לעמשא וא״ת היאך נתחייב יואב במאי דקטליה לעמשא והא בעי התראה ואפי' למ״ד חבר אינו צריך התראה הכא לא היה חבר בדבר זה שהיה חושבו מורד במלכות וה״ל שוגג וי״ל דלא נתחייב אלא משום הוא גופיה דהוה מורד במלכות עכ״ל. ופשטא דקרא ודשמעתא לא משמע אלא שנהרג מפני שהרג ואפי' לפי דבריהם עדיין הקושיא במקומה עומדת שכיון שלא היה חייב מיתה אלא מדינא דמלכותא המזבח היה קולטו כמה שכתב רבינו ומיהו בהא אפשר לדחוק ולומר דמורד במלכות שאני שאין המזבח קולטו:\",1,0],[8,383,6,1,\"שלשה הם ההורגים בלא כוונה וכו'. הקדמה זו הקדים רבינו והיא נלמדת מהדינים שיבואו בפרק זה בסותר כתלו לאשפה שהקרוב לפשיעה והקרוב לאונס אינם גולים ובפרק המניח (בבא קמא דף ל״ב:) גבי הנכנס לחנותו של נגר [שלא ברשות] ונתזה בקעת וטפחה על פניו ומת פטור אמרינן מאי פטור מגלות דלא סגי ליה בגלות משום דה״ל שוגג קרוב למזיד ודן רבינו שהקרוב לאונס אם הרגו גואל הדם נהרג עליו והקרוב למזיד אם הרגו גואל הדם אינו נהרג עליו:\",1,0],[8,383,6,5,\"וכן כל הרצחנים שהרגו בע\\\"א. כתב הראב\\\"ד תימה הוא וכו'. וי\\\"ל דלא בע\\\"א קאמר רבינו אלא היינו בעדות מיוחדת כלומר שהעיד עד אחד היום וחבירו למחר או שראהו אחד אחר האחד וכמ\\\"ש רבינו בפ\\\"ד גבי ההורג נפשות שלא בעדים שכונסין אותו לכיפה ואוקמוה בגמרא בעדות מיוחדת א\\\"נ שהרג בפני עדים בלא התראה או שהוכחשו בבדיקות ולא בחקירות ונראה דלרמוז להא דהוכחשו בבדיקות כתב רבינו וכיוצא בהן ונראה שרבינו כתב מסברא שלא יהיו אלו חמורים מההורג שלא בכוונה שזה נהרג ע\\\"י גואל הדם ואלו לא יהרגו ע\\\"י גואל הדם:\",1,0],[8,383,6,6,\"כיצד הזורק אבן לרה״ר וכו'. משנה פ' אלו הן הגולין (מכות דף ח') הזורק אבן לרה״ר והרג ה״ז גולה ראב״י אומר אם מכשיצאת האבן מידו הוציא הלה את ראשו ה״ז פטור וידוע דהלכה כראב״י דמשנתו קב ונקי ובגמ' לרה״ר מזיד הוא א״ר שמואל בר יצחק בסותר את כותלו איבעיא ליה לעיוני בסותר את כותלו בלילה בלילה נמי איבעיא ליה לעיוני בסותר את כתלו לאשפה האי אשפה היכי דמי אי שכיחי בה רבים פושע הוא אי לא שכיחי בה רבים אנוס הוא אמר רב פפא לא צריכא אלא באשפה העשויה ליפנות בה בלילה ואינה עשויה ליפנות בה ביום ואיכא דמיקרי ויתיב פושע לא הוי דהא אינה עשויה ליפנות בה ביום אנוס נמי לא הוי דהא איכא דמיקרי ויתיב:\",1,0],[8,383,6,8,\"ומ\\\"ש רבינו ואם אחר שנפלה האבן בא זה וישב ונפלה עליו. פירושו אם כשנעקרה האבן מהכותל קודם שתפול למטה בא זה וישב ונפלה עליו וטעמא דראב\\\"י מפרש בגמ' משום דכתיב ומצא פרט לממציא את עצמו:\",1,0],[8,383,6,10,\"השונא שהרג בשגגה וכו'. משנה שם (דף ט':) וכת\\\"ק.\",1,0],[8,383,6,10,\"ומ״ש ואיזהו שונא וכו'. פ' זה בורר (סנהדרין דף כ״ז:).\",2,0],[8,383,6,10,\"ומ״ש וכן אם נכנס לקרן זוית וכו'. פ' אלו הן הגולין (מכות דף ז':) ת״ר אם בפתע פרט לקרן זוית בלא איבה פרט לשונא הדפו שדחפו בגופו או השליך עליו להביא ירידה שהוא צורך עלייה בלא צדיה פרט למתכוין לצד זה והלכה לצד אחר ואשר לא צדה פרט למתכוין לזרוק שתים וזרק ד'. ופירש״י פרט לקרן זוית שלשון פתע הוא בסמוך כדמתרגמינן בתכיף. פרט לקרן זוית שאם היה זה יוצא ממבוי זה ונכנס לזה לפנות לימין או לשמאל וסכינו בידו וזה בא כנגדו בקרן זוית ולא ראהו והרגו. שדחפו בגופו בלא מתכוין וכו'. בלא צדיה לשון צידוד שלא נתכוין לצדד לצד ב' ואשר לא צדה שלא נתכוון לזרוק בצדו ובסמוך לו אלא למקום שזרק אבל לא היה יודע שיש שם אדם. פרט למתכוין לזרוק שתים וזרק ארבע וכן לזרוק ארבע וזרק שמונה.\",3,0],[8,383,6,10,\"ומ\\\"ש או שעלה על דעתו שמותר להרוג. שם ת\\\"ר בשגגה פרט לאומר מותר שהאומר מותר קרוב למזיד הוא בבלי דעת וכו' פרט למתכוין להרוג את הבהמה והרג את האדם לעכו\\\"ם והרג את ישראל. ויש לתמוה על מ\\\"ש רבינו שאם דחפו בגופו אינו גולה דהא משמע בברייתא שכתבתי דגולה ואפשר לומר שרבינו מפרש דפרט דקתני ברישא קאי נמי אסיפא והוי כאילו אמר הדפו פרט לדחפו בגופו כלומר דהדפו משמע שהדפו במתכוין פרט לדחפו בגופו שלא במתכוין. כתב המגיה [מהר\\\"ם פאדווא] צ\\\"ע על מאי דאיתא בברייתא פרט לקרן זוית דבר\\\"פ המניח גבי נזיקין משמע דקרן זוית פטור משום דאנוס הוא ורש\\\"י פירש שם (דף כ\\\"ז:) דנכנס ממבוי למבוי והחזיר פניו ולא ראהו וכענין זה פירש הא דפ' הגולין ורבינו פירש משום דקרוב למזיד הוא ואולי דדעת רבינו משום דדבר הלמד מעניינו הוא בלא איבה הסמוך לו שהוא פרט לשונא דטעמו משום דקרוב למזיד לכן דחק עצמו לפרש גם קרן זוית זה ולא רצה לפרשו כההיא דפרק המניח עכ\\\"ל:\",4,0],[8,383,6,11,\"הנכנס לחצר בעה\\\"ב שלא וכו'. משנה שם (דף ח').\",1,0],[8,383,6,11,\"ומ״ש לפיכך הנכנס לחנות הנגר וכו'. פ' המניח (בבא קמא דף ל״ב:) ת״ר הנכנס לחנותו של נגר שלא ברשות וניתזה בקעת וטפחה על פניו ומת פטור ואם נכנס ברשות חייב מאי חייב אמר ר״י בר חנינא חייב בארבעה דברים ופטור מגלות לפי שאין דומה ליער וכו' אמר רבא ק״ו ומה יער וכו' אלא אמר רבא מאי פטור מגלות דלא סגי ליה בגלות והיינו טעמא דר״י בר חנינא משום דהוי שוגג קרוב למזיד וכו' רב פפא משמיה דרבא מתני לה ארישא הנכנס לחנותו של נגר שלא ברשות וניתזה בקעת וטפחה לו על פניו ומת פטור אמר ר״י בר חנינא חייב בארבעה דברים ופטור מגלות מאן דמתני לה אסיפא כ״ש ארישא ומאן דמתני לה ארישא אבל אסיפא כיון דברשות חייב גלות ופסק רבינו כמאן דמתני לה ארישא משום דרב פפא משמיה דרבא דבתרא הוא קאמר ליה ועוד דטעמיה דר״י בר חנינא לפי שאינו דומה ליער א״ש כי מתנינן ליה ארישא ומאן דמתני לה אסיפא צריך לשבושי ולומר דלא אמר טעמא דלפי שאין דומה ליער אלא טעמא משום דה״ל שוגג קרוב למזיד:\",2,0],[8,383,6,12,\"מי שהיה דולה את החבית וכו'. כל דינים אלו משנה פרק שני דמכות (דף ז') ובגמרא מנא הני מילי אמר שמואל דאמר קרא ויפל עליו וימות עד שיפול דרך נפילה ורבינו ברוחב שכלו נתן טעם לדבר. ודע דבמתניתין תנן היה מושך במעגלה ונפלה עליו והרגתו (פטור) ולא ידעתי למה השמיטו רבינו ומכל מקום נלמד הוא משאר דינים שכתב:\",1,0],[8,383,6,13,\"קצב שהיה מקצב וכו'. שם קצב שהיה מקצב תני חדא לפניו חייב לאחריו פטור ותנא אידך לאחריו חייב לפניו פטור [ותניא אידך בין לפניו בין לאחריו חייב] ותניא אידך בין לפניו בין לאחריו פטור ל\\\"ק כאן בירידה שלפניו כאן בירידה שלאחריו כאן בעליה שלפניו כאן בעליה שלאחריו כאן בירידה שלפניו ושלאחריו כאן בעליה שלפניו ושלאחריו ופירש\\\"י כל דרך עליה פטור וכל דרך ירידה חייב הילכך הא דתניא לפניו חייב לאחריו פטור בירידה שלפניו ועליה שלאחריו השפיל זרועו להרים בכח והרים מכח לפניו בהשפלתו חייב הרג בעליתו לאחריו פטור והא דתניא לאחריו חייב לפניו פטור בעליה לפניו וירידה של אחריו כגון המרים ידו בכח עד שהשפילו דרך אחוריו ממעל לכתפיו וחזר והגביהן להכות לפניו הרג בהשפלתו דרך אחוריו חייב הרג בהגבהתו פטור והא דתניא בין לפניו בין לאחריו חייב בירידה שלפניו או שלאחריו והא דתניא בין לפניו בין לאחריו פטור בעליה שלפניו ושלאחריו:\",1,0],[8,383,6,13,\"ומ\\\"ש זה הכלל כל שבדרך ירידתו גולה וכו'. משנה שם:\",2,0],[8,383,6,13,\"ומ\\\"ש ואפי' בירידה שהיא צורך עליה. שם ברייתא או השליך עליו להביא ירידה שהיא צורך עליה ופירש\\\"י דמרבה לה לחייב גלות עליה וכן משמע לישנא דברייתא דבהא קאמר להביא ובאינך דמיתניא התם קאמר פרט לזה ומדברי רבינו נראה שהוא מפרש דלפיטורא מייתי לה ומ\\\"מ צריך ליישב לדעת רבינו הא שכתבתי בסמוך תני חדא לפניו חייב לאחריו פטור ותניא אידך וכו' עד כאן בעליה שלפניו ושלאחריו היאך יתפרש לדעתו וצ\\\"ע:\",3,0],[8,383,6,14,\"ומה שכתב כיצד היה עולה בסולם וכו'. שם בעא מיניה רבי אבהו מר\\\"י היה עולה בסולם ונשמטה שליבה מתחתיו ונפלה והרגה מהו כה\\\"ג עליה היא או ירידה היא א\\\"ל כבר נגעת בירידה שהיא צורך עליה פירש\\\"י עליה היא או ירידה בתר דידיה אזלינן והוא היה עסוק בעליה או בתר שליבה אזלינן והעולה עליה היה דוחקה ומשפילה כלפי מטה. ובמ\\\"ש הרי נגעת וכו' כתב רש\\\"י הרי נגעת כאן בירידה שהיא צורך עליה והא רבינן לה לעיל לחיובא ורבינו מפרש איפכא דהא אייתינן לה לעיל לפיטורא:\",1,0],[8,383,6,14,\"וכן המתכוין לזרוק בצד זה והלכה לה לצד אחר וכו'. ברייתא כתבתיה בפרק זה.\",2,0],[8,383,6,14,\"ומה שכתב או שהיתה לו אבן מונחת בחיקו וכו'. סוף פרק כיצד הרגל.\",3,0],[8,383,6,14,\"ומ\\\"ש וכן הסומא וכו'. פלוגתא דר' יהודה ור\\\"מ במשנה פרק אלו הן הגולין ופסק כר\\\"י ומפרש בגמרא טעמיה משום דכתיב בלא ראות פרט לסומא:\",4,0],[8,383,6,15,\"ומ\\\"ש היתה אבן בחיקו והכיר בה וכו'. ס\\\"פ כיצד הרגל (דף כ\\\"ו:):\",1,0],[8,383,6,15,\"נשמט הברזל מן העץ המתבקע וכו'. משנה פ\\\"ב דמכות (דף ז':) נשמט הברזל מקתו [והרג] רבי אומר אינו גולה וחכ\\\"א גולה מן העץ המתבקע רבי אומר גולה וחכ\\\"א אינו גולה ופירש\\\"י מן העץ המתבקע יצא קיסם ונתז למרחוק והרג.\",2,0],[8,383,6,15,\"ומ\\\"ש וכן הזורק אבן לתמר וכו'. שם (דף ה') אמר רב פפא דהוי מחלוקת רבי ורבנן דהא דמי למן העץ המתבקע ורבינו נראה שאינו מפרש כן אלא מן העץ המתבקע אנשמט ברזל דרישא קאי:\",3,0],[8,383,7,1,\"תלמיד שגלה לעיר מקלט וכו' וכן הרב שגלה וכו'. בפ' אלו הן הגולין (מכות דף י'):\",1,0],[8,383,7,2,\"עבד שגלה לעיר מקלט וכו' אבל אשה שגלתה לערי מקלט וכו'. בסוף פ\\\"ק דגיטין (דף י\\\"ב):\",1,0],[8,383,7,3,\"רוצח שנגמר דינו להגלותו וכו'. בפרק אלו הן הגולין (מכות דף י״א:) אמר אביי נקיטינן נגמר דינו ומת מוליכין עצמותיו לשם דכתיב לשוב לשבת בארץ עד מות הכהן ואיזוהי ישיבה שהיא בארץ הוי אומר זו קבורה.\",1,0],[8,383,7,3,\"ומה שכתב ובעת שימות הכהן הגדול וכו' נראה לי דאכל רוצח קאי והוא שם תנא מת קודם שמת הכהן הגדול מוליכין עצמותיו על קברי אבותיו דכתיב ישוב הרוצח אל ארץ אחוזתו אי זו היא ישיבה שהיא בארץ אחוזתו הוי אומר זו קבורה. ומצאתי מוגה בספרי רבינו ורוצח שמת בעיר מקלטו קוברים אותו שם ובעת שימות הכהן הגדול מוליכין עצמות הרוצח משם לקברי אבותיו ע\\\"כ. והוא מבואר כמו שכתבתי:\",2,0],[8,383,7,4,\"שאר הלוים השוכנים בערי מקלט וכו'. מימרא שם (דף י\\\"ב):\",1,0],[8,383,7,5,\"רוצח שהרג בשגגה וכן לוי שהרג במדינתו וכו'. משנה שם ע\\\"ב.\",1,0],[8,383,7,5,\"ומה שכתב ואם הרג חוץ מערי הלוים וכו'. שם:\",2,0],[8,383,7,6,\"עיר מקלט שרובה רצחנים וכו' וכן עיר שאין בה זקנים וכו'. שם (דף י':). וכתב הראב\\\"ד עיר מקלט שיש בה רוצחים א\\\"א שיש בה רוב רצחנים עכ\\\"ל. ספר מוטעה נזדמן להראב\\\"ד בדברי רבינו:\",1,0],[8,383,7,7,\"רוצח שגלה לעיר מקלט וכו'. משנה שם (דף י\\\"ב:):\",1,0],[8,383,7,8,\"הגולה אינו יוצא מעיר מקלטו לעולם וכו'. גם זה משנה שם (דף י\\\"א:):\",1,0],[8,383,7,9,\"אחד כהן גדול המשוח בשמן המשחה וכו'. גם זה משנה שם ע\\\"א.\",1,0],[8,383,7,9,\"ומ\\\"ש אבל משוח מלחמה אינו מחזיר. גם זה משנה שם ודלא כר' יהודה:\",2,0],[8,383,7,10,\"רוצח שנגמר דינו לגלות וכו' עד ואין יוצאין מעיר מקלט לעולם. גם זה משנה שם:\",1,0],[8,383,7,11,\"נגמר דינו לגלות ואחר כך מת הכה\\\"ג וגו' עד שנגמר דינו בפניו. גם זה משנה שם:\",1,0],[8,383,7,12,\"נגמר דינו ונמצא הכהן הגדול בן גרושה או בן חלוצה וכו'. שם נגמר דינו ונעשה כהן בן גרושה או בן חלוצה פליגי בה רבי אמי ורבי יצחק נפחא חד אמר מתה כהונה וחד אמר בטלה כהונה לימא בפלוגתא דרבי אליעזר ורבי יהושע קא מפלגי וכו' אליבא דרבי אליעזר כולי עלמא לא פליגי כי פליגי אליבא דרבי יהושע מאן דאמר מתה כרבי יהושע ומ\\\"ד בטלה עד כאן לא אמר ר' יהושע התם דכתיב ברך ה' חילו ופועל ידיו תרצה וכו' אבל הכא אפי' ר' יהושע מודה. ופירש רש\\\"י מתה כהונה הרי הוא כמת ואין הרוצח גולה. בטלה כהונה איגלאי מלתא למפרע שלא היה כהן גדול והוה ליה האי רוצח נגמר דינו בלא כ\\\"ג ואינו חוזר לעולם וכו'. ופועל ידיו תרצה עבודותיו כשירות אבל לענין שאר דבריו אינו כהן. ופסק רבינו כמ\\\"ד בטלה כהונה משום דבפ\\\"ג דקדושין (דף ס\\\"ו:) אמרינן דטעמא דרבי יהושע משום דכתיב ברך ה' חילו ואתי כמ\\\"ד בטלה כהונה ועוד דהכי משתמע בירושלמי פרק ה' דתרומות:\",1,0],[8,383,7,13,\"רוצח ששב לעירו וכו' ואם הרגו גואל הדם נהרג עליו. זה נראה שהוא פשוט:\",1,0],[8,383,7,14,\"ומה שכתב אע״פ שנתכפר אינו חוזר לשררה שהיה בה לעולם וכו'. משנה בס״פ אלו הן הגולין (מכות דף י״ג) וכרבי יהודה לגבי ר״מ:\",1,0],[8,383,7,15,\"אף על פי שהחובל באביו ובאמו וכו' אינו חייב גלות וכו'. בסיפרי פרשת מסעי מכה נפש בשגגה אי מכה נפש שומע אני אף מכה אביו ואמו במשמע ת\\\"ל רוצח הוא מכה נפש לא אמרתי אלא רוצח מכה נפש יצא המכה אביו ואמו שאינו גולה:\",1,0],[8,383,8,1,\"מצות עשה להפריש ערי מקלט וכו' ואין ערי מקלט נוהגת אלא בארץ ישראל. מפורש בכתוב פרשת מסעי את שלש הערים תתנו מעבר לירדן ואת שלש הערים תתנו בארץ כנען ומה ששנינו בסיפרי אין לי אלא שקולטות בארץ כנען בחו\\\"ל מנין ת\\\"ל תהיינה צ\\\"ל דה\\\"ק אין לי אלא שקולטות אלא לבני הארץ לבני חו\\\"ל מנין א\\\"נ חוץ לארץ קרי לעבר הירדן:\",1,0],[8,383,8,3,\"אין אחת מערי מקלט קולטות עד שיובדלו כולן וכו'. משנה פ' אלו הן הגולין (מכות דף ט':).\",1,0],[8,383,8,3,\"ומ\\\"ש ולמה הבדילן וכו'. שם:\",2,0],[8,383,8,4,\"בימי מלך המשיח מוסיפין ג' אחרות וכו'. בירושלמי פרק הגולין (דף ל\\\"ב.) ובספרי פרשת שופטים על פסוק ואם ירחיב ה' את גבולך וכו' ויספת לך עוד שלש ערים על השלש האלה.\",1,0],[8,383,8,4,\"ומ\\\"ש והיכן מוסיפין אותן בערי הקיני והקנזי והקדמוני:\",2,0],[8,383,8,5,\"וחייבים ב\\\"ד לכוין הדרכים לערי מקלט וכו'. זה פירוש מה שאמרו בספרי תכין לך הדרך תכוין לך סרטאות שיהיו מפולשות לתוכו:\",1,0],[8,383,8,5,\"ורוחב דרך ערי מקלט אין פחות מל\\\"ב אמה. בפרק המוכר פירות (דף קע\\\"ב) דרך הרבים ט\\\"ז אמה דרך ערי מקלט ל\\\"ב וכו'. מאי קרא תכין לך הדרך דרך הדרך:\",2,0],[8,383,8,5,\"ומקלט מקלט היה כתוב על פרשת דרכים וכו'. פ' אלו הן הגולין (מכות דף י'):\",3,0],[8,383,8,6,\"בט\\\"ו באדר בכל שנה בית דין מוציאין שלוחין וכו' עד כאילו שפכו דמים. בפרק קמא דמועד קטן (דף ה'):\",1,0],[8,383,8,7,\"וכן מושחין בין כל עיר ועיר וכו'. בפרק אלו הן הגולין (מכות דף ט':). וכתב הראב״ד וכן משוין. ואיני יודע מה מלמדנו:\",1,0],[8,383,8,8,\"אין עושין אותן לא עיירות גדולות וכו' עד מצויה שם. גם זה שם (דף י') ופירש\\\"י אין עושין אותן טירין קטנים לפי שאין מזונות מצויים שם ולא כרכים גדולים שהכל נקבצים שם תמיד ותהא רגל גואל הדם מצויה שם ויארוב לו במקום שווקים שימצאו מזונות לקנות במקום אוכלוסים שיהיו כפרים וישוב סמוכים להם שלא יבואו גואל הדם מרובים על העיר בחיל:\",1,0],[8,383,8,9,\"כל ערי הלוים קולטות עד אינן קולטות אלא לדעת. גם זה שם:\",1,0],[8,383,8,10,\"ורוצח הדר בעיר מקלט וכו'. משנה בסוף פ' אלו הן הגולין (מכות דף י״ג) מעלין היו שכר דברי ר' יהודה ר״מ אומר לא היו מעלין להן שכר ובגמרא אלא אמר רבא מחלוקת במ״ב דמר סבר ועליהם תתנו כי הנך לקליטה ומר סבר ועליהם תתנו כי הנך מה הנך לכל צרכיהם אף הני נמי לכל צרכיהם אבל בשש דברי הכל לא היו מעלין להם שכר ופירש״י לכם לרוצחים נאמר והיו לכם הערים למקלט וידוע דהלכה כר' יהודה:\",1,0],[8,383,8,11,\"כל עיר הקולטת תחומה קולט כמוה. משנה שם:\",1,0],[8,383,8,11,\"אילן שהוא עומד בתוך תחום ערי מקלט וכו'. משנה שם (דף י\\\"ב) אילן שהוא עומד בתוך התחום ונופו נוטה חוץ לתחום או עומד חוץ לתחום ונופו נוטה בתוך התחום הכל הולך אחר הנוף ואסיק רב אשי מאי אחר הנוף אף אחר הנוף ופירש\\\"י דהיינו לומר דהיכא דעיקרו בחוץ ונופו בפנים שדי עיקרו בתר נופו לחומרא ולא תימא כדקאי קאי אבל היכא דעיקרו בפנים ונופו בחוץ שדי נופו בתר עיקרו ולא מצי קטיל בנופו ומשום דבכולי גמרא שדינן נוף בתר עיקר איצטריך הכא למימר דלענין מקלט זמנין דשדינן עיקר בתר נוף לחומרא עכ\\\"ל. וכך הם דברי רבינו אבל קשה לן דהא לא אצטריך רב אשי לשנויי הכי אלא לרבי יהודה אבל לרבנן שפיר מיפרשא מתני' כפשטה שהכל הולך אחר הנוף כדמפרש טעמייהו בגמ' ערי מקלט בדירה תלה רחמנא בנופו מתדר ליה בעיקרו לא מיתדר ליה ופירש רש\\\"י בדירה תלה רחמנא דכתיב כי בעיר מקלטו ישב ונופו ראוי לדירה יותר מעיקרו ולמה הניח רבנן ופסק כר' יהודה ושמא נקט להקל בדיני נפשות ואין זה כדאי וצ\\\"ע:\",2,0],[8,383,8,11,\"ואע\\\"פ שהתחום קולט אין הרוצח דר בו וכו'..\",3,0],[8,383,9,1,\"הרוג שנמצא נופל לארץ וכו'. ויוצאים חמשה זקנים מב\\\"ד שבירושלים. משנה בפרק ט' דסוטה (דף מ\\\"ד:) שלשה מב\\\"ד הגדול שבירושלים היו יוצאים רבי יהודה אומר חמשה שנאמר ויצאו זקניך ושופטיך זקניך שנים שופטיך שנים אין ב\\\"ד שקול מוסיפין עליהם עוד אחד. ויש לתמוה למה פסק כר' יהודה אע\\\"ג דבגמ' אמרינן דת\\\"ק ר\\\"ש מ\\\"מ כיון דסתם לן תנא כוותיה הכי הוה ליה למיפסק ואפשר דכיון דבפ\\\"ק דסנהדרין (דף י\\\"ד) שנויה במחלוקת הוה ליה סתם ואח\\\"כ מחלוקת דבתרי סדרי יש סדר למשנה ואין הלכה כסתם והדרינן לכללין דר\\\"ש ור' יהודה הלכה כר' יהודה.\",1,0],[8,383,9,1,\"ומ\\\"ש ומודדין אל הערים. בספרי ומדדו אל הערים אשר סביבות החלל מן החלל אל הערים ולא מן הערים אל החלל.\",2,0],[8,383,9,1,\"ומ\\\"ש אפילו נמצא בצד עיר זו שהדבר ידוע בודאי שהיא הקרובה וכו'. שם שאפילו נמצא בעליל לעיר היו מודדין שמצוה לעסוק במדידה ופירש\\\"י בעליל לעיר במגולה ופשוט שאין עיר קרובה כזו:\",3,0],[8,383,9,2,\"ומה שכתב קוברין את הנהרג במקומו. פרק עגלה ערופה (סוטה דף מ״ה:) וסוף פרק מרובה (ב״ק דף פ״א:).\",1,0],[8,383,9,2,\"ומה שכתב וחוזרין זקני ירושלים למקומן. במשנה פרק ט' דסוטה נפטרו זקני ירושלים והלכו להן וזקני אותה העיר מביאים עגלת בקר ופירש רש\\\"י נפטרו זקני ירושלים שאין עליהם אלא למדוד כדכתיב ויצאו זקניך ושופטיך ומדדו.\",2,0],[8,383,9,2,\"ומה שכתב משל אנשי אותה העיר. ומה שכתב ומורידין אותה אל נחל ששוטף בחזקה וזהו איתן האמור בתורה. שם במשנה איתן כמשמעו קשה ובגמרא (דף מ\\\"ז) תנו רבנן מנין לאיתן שהוא קשה שנאמר איתן מושבך וכו' אחרים אומרים מנין לאיתן שהוא ישן שנאמר גוי איתן הוא גוי מעולם הוא ונראה דמשמע לרבינו דקשה היינו שהוא שוטף בחזקה ופסק כתנא קמא דאתי כסתם מתניתין. ודע ששם במשנה שנינו אף על פי שאינו איתן כשר ופירש\\\"י דלא כתיב ביה עיכובא ולא נאמר אלא למצוה ולא ידעתי למה השמיטו רבינו:\",3,0],[8,383,9,3,\"ומ\\\"ש עורפין אותה שם בקופיץ מאחריה. שם במשנה פי' למה שנאמר וערפו שם את העגלה בנחל.\",1,0],[8,383,9,3,\"ומ\\\"ש של אותה עיר עם כל זקניה אפילו מאה וכו'. שם במשנה וזקני אותה העיר רוחצים במים במקום עריפתה ובגמרא (דף מ\\\"ו:) ת\\\"ר כל זקני העיר ההיא הקרובים אל החלל ירחצו את ידיהם על העגלה הערופה בנחל שאין ת\\\"ל הערופה ומה ת\\\"ל הערופה על מקום עריפתה של עגלה ושנינו בספרי וכל זקני העיר ההיא אפילו הם מאה:\",2,0],[8,383,9,3,\"ומ\\\"ש ואומרים שם בתוך הנחל. בספרי יכול יעלו מן הנחל ויאמרו ת\\\"ל בנחל שתהא ענייתן ואמירתן בנחל.\",3,0],[8,383,9,3,\"ומה שכתב בלשון הקדש. פרק אלו נאמרין (סוטה דף ל״ב) ופ' עגלה ערופה (סוטה דף מ״ד:) ופירש״י מה שהזקנים אומרים ידינו לא שפכו את הדם הזה והכהנים אומרים כפר לעמך ישראל בלשון הקדש הוזקקו מן התורה לאמרה ובגמרא יליף לה מקרא:\",4,0],[8,383,9,3,\"ומ\\\"ש כלומר שלא בא לידינו הנהרג הזה וכו'. שם במשנה ואומרים ידינו לא שפכו את הדם הזה ועינינו לא ראו וכי על דעתנו עלתה שזקני ב\\\"ד שופכי דמים הם אלא שלא בא לידינו ופטרנוהו בלא [מזון לא ראינוהו והנחנוהו] בלא לויה.\",5,0],[8,383,9,3,\"ומ\\\"ש הכהנים אומרים. שם במשנה וכן מפורש בדברי המתרגם פסוק כפר לעמך ישראל.\",6,0],[8,383,9,3,\"ומ\\\"ש בלשון הקדש. נתבאר בסמוך.\",7,0],[8,383,9,3,\"ומ\\\"ש שאומרים כפר לעמך ישראל לא זה בלבד צריכים לומר אלא כל המקרא אומרים עד בקרב עמך ישראל כמו שמפורש שם במשנה ורבינו רישא דקרא נקט.\",8,0],[8,383,9,3,\"ומ\\\"ש והקב\\\"ה מכפר על הדם שנאמר ונכפר להם הדם. שם במשנה ואינם צריכים לומר ונכפר להם הדם אלא רוח הקדש מבשרתן אימתי שתעשו ככה הדם מתכפר לכם:\",9,0],[8,383,9,4,\"כשמודדין מן החלל וכו'. פרק כיצד מעברין (דף ל\\\"ה:) אמרינן אין מקדרין לא בערי מקלט ולא בעגלה ערופה מפני שהן של תורה ופירש רש\\\"י בעגלה ערופה כשבא למדוד הערים שסביבות החלל לידע אי זו היא הקרובה מכולן [וטעמא] מפני שמדידתן של תורה הילכך לא משערינן בהו מידי אלא מודדין הרים וגאיות כקרקע חלקה:\",1,0],[8,383,9,4,\"ואין מודדין אלא לעיר שיש בה בית דין של כ״ג. משנה פרק עגלה ערופה (סוטה דף מ״ד:) אין מודדין אלא לעיר שיש בה בית דין ובגמרא (דף מ״ה:) משום דבעינן זקני העיר וליכא:\",2,0],[8,383,9,4,\"ואין מודדין לירושלים וכו'. משנה וגמ' שם:\",3,0],[8,383,9,5,\"נמצא קרוב לירושלים וכו'. משנה שם (דף מ\\\"ד:) נמצא סמוך לספר או לעיר שרובה עכו\\\"ם או לעיר שאין בה ב\\\"ד לא היו עורפין אין מודדין אלא לעיר שיש בה ב\\\"ד ובגמרא (דף מ\\\"ה:) פשיטא כיון דתנא לעיר שאין בה ב\\\"ד אנא ידענא דאין מודדין אלא לעיר שיש בה ב\\\"ד הא קמ\\\"ל כדתניא מנין שאם נמצא סמוך לעיר שאין בה בית דין שמניחין אותה ומודדין לעיר שיש בה ב\\\"ד ת\\\"ל ולקחו זקני העיר ההיא מ\\\"מ ופירש רש\\\"י דהאי העיר יתירה הוא דמצי למכתב והיתה העיר הקרובה אל החלל ולקחו זקניה עגלת בקר. ועל נמצא סמוך לספר או לעיר שרובה עכו\\\"ם אמרינן בגמרא דכתיב כי ימצא פרט למצוי ומפרש רבינו שהוא מצוי שיהרגוהו עכו\\\"ם וכן מפורש בירושלמי:\",1,0],[8,383,9,6,\"אין העיר הקרובה מביאה וכו'. בסוף פ\\\"ב דבתרא (דף כ\\\"ג:) רוב וקרוב הולכים אחר הרוב ואע\\\"ג דרובא דאורייתא וקורבה דאורייתא אפילו הכי רובא עדיף מתיב ר' זירא והיה העיר הקרובה אל החלל ואע\\\"ג דאיכא אחריתי דנפישי מינה בדליכא וליזיל בתר רובא דעלמא ביושבת בין ההרים ופירש\\\"י בין ההרים שאין דרך רוצחים לבא ממקומות אחרים לכאן עכ\\\"ל. ויש לתמוה על רבינו למה לא כתב חילוק זה דיושבת בין ההרים ונ\\\"ל לדחוק ולומר שסובר רבינו דקושיא דליזיל בתר רובא דעלמא לאו קושיא הוא דפשיטא דקרובה בעינן דהא בקרובה תלה רחמנא ואי הוה אזלינן בתר רובא דעלמא לעולם היו מודדין לעיר הגדולה שבעולם ומאי דא\\\"ל ביושבת בין ההרים לפי דרכו השיבו אבל לקושטא דמילתא ליתיה:\",1,0],[8,383,9,8,\"נמצא הנהרג מכוון בין שתי עיירות וכו'. בספ\\\"ב דבכורות (דף י\\\"ח) תנא נמצא מכוון בין שתי עיירות שתיהן מביאות שתי עגלות דברי ר\\\"א וחכ\\\"א יביאו עגלה אחת בשותפות ויתנו מאי קסברי רבנן אי קסברי אפשר לצמצם וקרובה ואפילו קרובות ליתי תרתי ואי קרובה ולא קרובות אפילו חדא לא לייתי אלא לאו שמע מינה קסברי רבנן אי אפשר לצמצם ואפילו בידי אדם ש\\\"מ:\",1,0],[8,383,9,9,\"מהיכן מודדין מחוטמו וכו'. משנה פרק עגלה ערופה (סוטה דף מ״ד:) מנין היו מודדין ר״א אומר מטיבורו ר״ע אומר מחוטמו ראב״י אומר ממקום שנעשה חלל מצוארו ופסק כר״ע ויש לתמוה דהא קי״ל משנת ראב״י קב ונקי וצ״ל שסובר שלא נאמר כלל זה לדחות מאי דקי״ל הלכה כר״ע מחבירו:\",1,0],[8,383,9,9,\"נמצא גופו במקום אחד וכו'. משנה שם נמצא ראשו במקום אחד וגופו במקום אחר מוליכין הראש אצל הגוף דברי ר' אליעזר ר\\\"ע אומר הגוף אצל הראש ובגמרא במאי קא מפלגי אי לימא לענין מדידה [קמיפלגי] הא מדקתני סיפא מנין היו מודדין מכלל דרישא לאו במדידה עסקינן אמר ר' יצחק במת מצוה קנה מקומו וכו' והיכא דנמצא ראשו במקום אחד וגופו במקום אחר מוליכין הראש [אצל הגוף] דברי ר\\\"א ר\\\"ע אומר הגוף אצל הראש וידוע דהלכה כר\\\"ע:\",2,0],[8,383,9,10,\"נמצאו מתים רבים וכו'.. נמצאו זה ע״ג זה מודדין מן העליון כמות שהן וכו'. בר״פ עגלה ערופה (סוטה דף מ״ה) אמר אביי הריני כבן עזאי בשוקי טבריה א״ל ההוא מרבנן [לאביי] שני חללים זה ע״ג זה מהיכן הוא מודד מין במינו הוי טמון ומין במינו לא הוי צף ומעליון מודד או דילמא מין במינו הוי צף ומין במינו לא הוי טמון ומתחתון מודד או דילמא מין במינו הוי טמון ומין במינו הוי צף ולא מתחתון [מודד] ולא מעליון מודד א״ל תניתוה עומר שהחזיק בו להוליכו לעיר והניחו ע״ג חבירו ושכחו התחתון שכחה והעליון אינו שכחה ר״ש בן יהודה אומר משום (ר״ש) שניהם אינם שכחה התחתון מפני שהוא טמון והעליון מפני שהוא צף סברוה דהני תנאי כר' יהודה סבירא להו דאמר בשדה פרט לטמון וכו' לא אי כר' יהודה ס״ל דכ״ע מין במינו הוי טמון והכא בפלוגתא דר״י ורבנן קמפלגי דרבנן כרבנן ור״ש בן יהודה כר' יהודה. ופירש״י תניתוה לחדא מינייהו דפלוגתא היא בטמון אבל צף לא פשט ליה מינה דהא אוקימנא טעמא דעליון משום דאחזוק ביה וצף ולא ידעינן מאי הוי עלה עכ״ל. ומשמע דבעיא דטמון איפשיטא לסברת סברוה דלת״ק מין במינו לא הוי טמון ודחי ליה דאיפשט דלכ״ע מין במינו הוי טמון ורבינו נראה שפושט דמין במינו הוי טמון ויש לתמוה דהא מצי למימר כיון דלא איפשיטא מנין לו לפשוט כן ולכל זה נתכוון הראב״ד שכתב זה הפסק אינו מתברר מן הגמרא. ואפשר לומר שטעם רבינו משום דמלישנא דסברוה משמע דלא קאי האי סברא ומלישנא דאי כר״י ס״ל דכ״ע מין במינו הוי טמון ומדלא קאמר ליה בלשון דילמא משמע דקושטא דמילתא הכי הוא ובבעיא דצף נראה לדחוק ולומר דפשיטא לרבינו דלא מקרי צף משום דמתני' קתני צף על פני המים ומשמע דלא מיקרי צף אלא על פני המים דוקא ואע״ג דההוא מרבנן מיבעיא ליה בצף לא חש אביי למפשטה משום דמילתא דפשיטא היא ממתני' כדאמרן ואע״ג דבירושלמי פשט דאין מודדין מן התחתון משום שהוא טמון ולא מן העליון מפני שהוא צף פסק רבינו כדמשמע ליה מגמרא דידן וצ״ע:\",1,0],[8,383,9,12,\"נאמר כי ימצא חלל לא חנוק ולא מפרפר וכו'. פרק עגלה ערופה (סוטה דף מ״ה ע״ב) ופירש״י חלל לא מיקרי אלא בכלי ברזל כעין חרב.\",1,0],[8,383,9,12,\"ומ\\\"ש באדמה לא טמון בגל וכו' עד על פני המים. משנה שם (דף מ\\\"ד:):\",2,0],[8,383,9,12,\"לא נודע מי הכהו הא אם נודע לא היו עורפין אפילו ראה ההורג עד אחד. ברייתא שם (דף מ\\\"ז:).\",3,0],[8,383,9,12,\"ומ\\\"ש אפילו עבד או אשה או פסול לעדות בעבירה לא היו עורפין: ומ\\\"ש לפיכך משרבו הרצחנין בגלוי בטלה עגלה ערופה. משנה וברייתא שם:\",4,0],[8,383,9,13,\"עד אחד אומר ראיתי את ההורג וכו' בד\\\"א בשבאו שניהם כאחד וכו'. משנה שם עד אחד אומר ראיתי (את ההורג) ועד אומר לא ראית אשה אומרת ראיתי ואשה אומרת לא ראית היו עורפין עד אחד אומר ראיתי ושנים אומרים לא ראית היו עורפין שנים אומרים ראינו ועד אחד אומר להן לא ראיתם לא היו עורפין ובגמ' עד אחד אומר ראיתי את ההורג וכו' טעמא דמכחיש ליה הא לא מכחיש ליה עד אחד מהימן וכו' השתא דאמרת עד אחד מהימן אידך חד היכי מצי מכחיש ליה והאמר עולא כ\\\"מ שהאמינה תורה עד אחד הרי כאן שנים ואין דבריו של אחד במקום שנים אמר לך עולא תני לא היו עורפין וכן אמר רבי יצחק ור' חייא אמר תני [לא] היו עורפין וכו' ולר' חייא קשיא דעולא לא קשיא כאן בבת אחת כאן בזה אחר זה ופירש\\\"י (דף ל\\\"א:) הרי כאן שנים הרי הוא כשנים כאן בבת אחת כאן בזה אחר זה [מתני'] כשהעידו שניהם בתוך כדי דיבור דבטלו דבריו מיד דלא נתקיימה עדותן בבית דין והיכן האמינתו תורה כשנים כגון אם העיד עדותו ויצא דתו לא מצי חד לאכחושי עכ\\\"ל. ופסק רבינו כר' חייא והטעם כתבתי בפ\\\"א מהל' סוטה:\",1,0],[8,383,9,16,\"ומ\\\"ש באו שנים אחר שהעיד האחד וכו'. נתבאר במשנה שכתבתי בסמוך.\",1,0],[8,383,9,16,\"ומ\\\"ש אשה אומרת ראיתי את ההורג וכו' עד בין שבאו זו אחר זו. נתבאר במשנה שכתבתי בסמוך וע\\\"כ לא מפלגינן בין באו בבת אחת לבאו זה אחר זה אלא דוקא כשהעד הראשון הוא כשר ולאפוקי מהראב\\\"ד שכתב אשה אומרת ראיתי וכו' עד זו אחר זו נראה מהגמ' שזה שיבוש דבזה אחר זה וכו'.\",2,0],[8,383,9,16,\"ומ\\\"ש רבינו שנים אומרים ראינו וכו'. אחד אומר ראיתי ושנים אומרים לא ראית וכו' בד\\\"א בשהיו שלשתן כשרים או פסולים וכו'. שם (דף מ\\\"ז:) תנן עד אחד אומר ראיתי את ההורג ושנים אומרים לא ראית וכו' היו עורפין הא חד וחד לא היו עורפין תיובתא דר' חייא ולטעמיך אימא סיפא שנים אומרים ראינו ועד אחד אומר לא ראיתם לא היו עורפין הא חד וחד היו עורפין אלא מתני' כולה בפסולי עדות וכדר' נחמיה דאמר כ\\\"מ שהאמינה תורה עד אחד הלך אחר רוב דעות וכו' ועשו שתי נשים באשה אחת כשני אנשים באיש אחד אבל שתי נשים באיש אחד כי פלגא ופלגא דמי ופירש\\\"י בזה כתבתי בפ\\\"א מהלכות סוטה וממ\\\"ש שם יתבארו דברי רבינו כאן. וכתב הראב\\\"ד שנים אומרים ראינו וכו' עד עורפין גם זה שיבוש עכ\\\"ל. ותמיהא לי דהא דברי רבינו משנה שלימה הם והיאך כתב שהוא שיבוש ואפשר שטעמו משום דבגמ' מקשה מהאי בבא דמשמע מינה הא חד וחד היו עורפין ותיובתא דרבי חייא ואיצטריך לשנויי אלא כולה מתני' בפסולי עדות וכרבי נחמיה וא\\\"כ לא היה לו לרבינו לכתוב בבא זו כי היכי דלא נידוק מינה הא חד וחד היו עורפין ותקשה לרבי חייא וי\\\"ל דרבינו לא לדיוקא כתביה שאי אפשר למידק מינה הכי שהרי כתב בהדיא דעד אחד ועד אחד לא היו עורפין ואם תאמר משנה שאינה צריכה היא ויש לומר שרצה להעתיק המשנה כצורתה כיון שהיא גופה אמת בלא דיוק ואי אפשר לטעות לדייק בה ומפני שכתב ה\\\"ז נאמן כשנים לענין זה רצה לכתוב דין השנים:\",3,0],[8,383,9,16,\"וכתב עוד הראב\\\"ד שתי נשים או שנים פסולים אומרים וכו' עד עורפין גם זה שיבוש שלא אמרו אלא בדאתא עד אחד כשר מעיקרא וכו'. ואיני יורד לסוף דעתו של הראב\\\"ד שהרי דברי רבינו מפורשים בגמרא דללישנא בתרא שתי נשים באיש אחד כי פלגא ופלגא דמי והיינו דאתא ע\\\"א לבסוף ולא אמרו הלך אחר רוב דעות אלא בשכולם נשים או פסולים:\",4,0],[8,383,9,17,\"ועל מ\\\"ש רבינו ג' נשים או ג' פסולים וכו' כתב הראב\\\"ד אפילו בזה אחר זה. ופשוט הוא בדברי רבינו שסתם ולא חילק:\",1,0],[8,383,10,1,\"אין דין עגלה ערופה [נוהג] אלא בארץ וכן בעבר הירדן. בספרי סוף פרשת שופטים אשר ה' אלהיך נותן לך לרבות עבר הירדן:\",1,0],[8,383,10,2,\"עגלה ערופה בת שתי שנים וכו'. בריש מס' פרה וכחכמים:\",1,0],[8,383,10,2,\"ואין המומין פוסלין. משנה פ' עגלה ערופה (סוטה דף מ״ה).\",2,0],[8,383,10,2,\"ומ\\\"ש ואעפ\\\"כ אם היתה טרפה פסולה וכו'. ירושלמי שם אלא שמשמע שם שלפ\\\"ז מחוסרת אבר פסולה ויש לתמוה למה השמיטו רבינו:\",3,0],[8,383,10,3,\"כל העבודות פוסלות את העגלה וכו' עד אין פוסלין אלא עד שעת מלאכה. בפרק עגלה ערופה (סוטה דף מ״ו):\",1,0],[8,383,10,4,\"כל מלאכה שהיא לצרכה וכו'. נלמד מדיני פרה השנויים בפ\\\"ב ממס' פרה:\",1,0],[8,383,10,5,\"אין עורפין את העגלה אלא ביום וכו' וכל היום כשר לעריפתה. משנה בפרק ב' דמגילה (דף כ' ע\\\"ב):\",1,0],[8,383,10,5,\"ואין עורפין שתי עגלות כאחת וכו'. בפירקא קמא דסוטה (דף ח') ויהיב טעמא מפני שאין עושין מצות חבילות חבילות:\",2,0],[8,383,10,6,\"עגלה ערופה אסורה בהנאה וכו'. משנה בפ' בתרא דע\\\"ז (דף ע\\\"ד):\",1,0],[8,383,10,6,\"ונקברת במקום עריפתה. בס\\\"פ ב\\\"ש (זבחים מ\\\"ו):\",2,0],[8,383,10,6,\"ומשתרד לנחל תיאסר וכו'. בפרק בתרא דכריתות (דף כ\\\"ד:) אתמר עגלה ערופה אימתי נאסרת רב המנונא אמר מחיים רבא אמר לאחר עריפה וכו' ולרב המנונא מאימתי אמר ר' ינאי גבול שמעתי בה ושכחתי ונסבין חבריא למימר ירידתה לנחל איתן אוסרתה וכו' אמר רבא מנא אמינא לה דתנן עגלה ערופה וכו' (אם נמצא ההורג) עד שלא נערפה תצא ותרעה בעדר ואי אמרת מחיים אמאי תצא ותרעה בעדר הא אתסרא לה מחיים תני עד שלא נראית לעריפה אימא סיפא משנערפה תקבר במקומה תני משנראית לעריפה א\\\"כ אימא סיפא שעל הספק באה מתחלה כיפרה ספיקה והלכה לה ואם מחיים עדיין לא כיפרה ספיקה תנאי היא ופסק רבינו כרב המנונא משום דרבי ינאי וחברייא הכי ס\\\"ל אבל קשה דלפ\\\"ז הוה ליה לפסוק שאם נמצא ההורג אחר ירידתה לנחל אסורה בהנאה והוא פסק לקמן בסמוך שאם נמצא ההורג עד שלא נערפה העגלה תצא ותרעה בעדר. והרשב\\\"א כתב שנשאל על זה והשיב היטבת לראות כי גם בעיני יפלא שהוא זיכה שטרא לבי תרי דפליגי בכריתות וטרחתי להעמיד דבריו ולא יכולתי אבל מה אעשה והראב\\\"ד לא חלק עליו בזה כלום עכ\\\"ל. וליישב דעת רבינו אפשר לומר שהוא סובר דהא דמקשה משנערפה העגלה תצא ותרעה בעדר לאו קושיא היא דאיכא למימר שאני עגלה דאדעתא שימצא ההורג לא אקדשוה ואיגלאי מילתא דהקדש טעות הוה ואע\\\"פ שהתוס' תירצו זה ואמרו דסברא היא דגמרי ומקדשי דלא מסקי אדעתייהו שימצא ההורג רבינו לא ניחא ליה בההוא תירוצא וסובר דגמ' לפום מאי דס\\\"ד דגמר ומקדיש בכל גוונא אסיק מאי דאסיק דמתני' פליגא וסברה דאינה נאסרת מחיים ולא אמרינן דאדעתא שימצא ההורג לא אקדשוה דלא מסקי אדעתייהו שימצא ההורג אבל לפום קושטא איכא למימר דמתני' נמי סברה דירידתה לנחל אוסרתה ואף על פי כן אם נמצא ההורג אפילו אחר שהורידוה לנחל תצא ותרעה בעדר משום דאדעתא שימצא ההורג לא אקדשוה שהרי דבר מצוי הוא שימצא ההורג וכל שכן לפי מה שפירשו קצת מפרשים שמתועלת המדידה והעניינים הנעשים במצוה שע\\\"י כך הוא קרוב שיתגלה מי הוא ההורג דהא ודאי מעיקרא מסקי אדעתייהו שימצא ההורג ולא גמרי ומקדשי הילכך נקטינן דירידתה לנחל אוסרתה ונקטינן במתני' דנמצא ההורג עד שלא תערף העגלה תצא ותרעה בעדר משום דאדעתא שימצא ההורג לא אקדשוה:\",3,0],[8,383,10,7,\"נמצאו העדים זוממין וכו'. בפרק בתרא דכריתות שם (דף כ\\\"ד) א\\\"ר יהודה אמר רב מודים חכמים לר' מאיר באשם תלוי שהוזמו עדיו שיצא וירעה בעדר ויש ללמוד משם לעגלה ערופה:\",1,0],[8,383,10,8,\"נמצא ההורג וכו' עד הרי זה יהרג. משנה פרק עגלה ערופה (סוטה דף מ״ז) ופירש״י כיפרה ספיקה היא עשתה את שלה ואם לא נמצא ההורג נתכפר מספק ולכשימצא נעשה ודאי ויהרג ומיהו באיסור הנאה קיימא דכפרה כתיב בה כקדשים:\",1,0],[8,383,10,9,\"הנחל שנערפה בו אסור בזריעה ועבודה לעולם וכו' עד אינה אלא בגופה של קרקע. משנה וברייתא שם (דף מ\\\"ז:):\",1,0],[8,383,10,10,\"אנשי עיר קרובה שנתאחרו וכו'. בפ' בתרא דכריתות (דף כ\\\"ו) אהא דאמר ר\\\"א שאין יוה\\\"כ מכפר אלא על חטא שאין מכיר בו אלא המקום פריך אלא מעתה עגלה ערופה שעבר עליה יוה\\\"כ לא יביא שהרי אין מכיר אלא הקב\\\"ה ושני ר\\\"פ אמר קרא כפר לעמך ישראל וכו' ראויה כפרה זו שתכפר על יוצאי מצרים פירש רש\\\"י על יוצאי מצרים דכתיב אשר פדית והרי כמה יה\\\"כ עבר עליהם ועדיין הם צריכין לכפרה זו אם נמצא חלל ביניהם כדכתיב קרא:\",1,0],[8,383,11,1,\"מ\\\"ע לעשות אדם מעקה לגגו וכו'. ומ\\\"ש והוא שיהיה בית דירה אבל בית האוצרות וכו'. יש לתמוה על זה דהא תניא בסיפרי אין לי אלא בית מנין הבונה בית התבן ובית הבקר ובית העצים ובית האוצרות ת\\\"ל לא תשים דמים בביתך יכול אף בונה בית שער אכסדרא ומרפסת ת\\\"ל בית בית מיוחד שהוא בית דירה יצאו אלו שאינם בית דירה וכן כתבה ספר מצות גדול הרי דבית הבקר ובית האוצרות חייב והיאך פטר רבינו. ואפשר שטעמו משום דבפ\\\"ק דיומא (דף י\\\"א) לענין מזוזה אמרינן דהני תנאי היא ותנא בסיפרי סבר כמאן דמחייב ורבינו בהל' מזוזה פוסק כמאן דפטר:\",1,0],[8,383,11,1,\"וכל בית שאין בו ד\\\"א על ד\\\"א פטור מן המעקה. ברייתא בפ\\\"ק דסוכה (דף ג':):\",2,0],[8,383,11,2,\"בית של שני שותפין וכו'. שם בפ' ראשית הגז (חולין דף קל״ו) אהא דתניא בהמת השותפין חייבת בראשית הגז ור' אלעאי פוטר אמר רבא מודה ר' אלעאי בתרומה וכו' מעקה אע״ג דכתב רחמנא לגגך דידן אין דשותפות לא כתב רחמנא כי יפול הנופל ממנו אלא גגך למאי אתא למעוטי בתי כנסיות ובתי מדרשות ופירש״י כי יפול הנופל כל שראוי ליפול הימנו ואפילו של שותפות. בתי כנסיות שאין חלק לאחד מהם בו שאף לבני עבר הים הוא ועוד שאינו בית דירה. ודע דאמרינן בגמ' בתר הכי א״ר ביבי בר אביי ליתנהו להני כללי דתניא בהמת השותפין חייבת בבכורה ור' אלעאי פוטר א״ר חנינא מסורא ליתנהו להני כללי דתניא בהמת השותפין חייבת במתנות ורבי אלעאי פוטר ופי' רש״י ליתנהו להני כללי דאמר רבא דמודה רבי אלעאי בכל הני דהא תניא דפליג ר' אלעאי בבכורה ולא מרבי לה מבקרכם וצאנכם עכ״ל. משמע שהוא מפרש דאכולהו מילי דלעיל קאי ומעקה מכללן וכ״כ סמ״ג שר' אלעאי פוטר בית דשותפין ממעקה וכתב ויכול להיות שאין הלכה כר' אלעאי אע״פ שהלכה כמותו בראשית הגז לענין פיטור חו״ל וכתב שזה טעמו של רבינו ואני אומר עוד שאפשר שרבינו מפרש דלא קאי ליתנהו להני כללי אלא לקצת דברים שאמר רבא ואין מעקה מכללן אלא אף ר' אלעאי מודה בו כדאמר רבא:\",1,0],[8,383,11,2,\"היתה רה\\\"ר גבוה מגגו וכו'. בפ\\\"ה דב\\\"ק (דף נ\\\"א) ממנו ולא לתוכו שאם היתה רה\\\"ר גבוה מגגו י' טפחים ונפל ממנו לתוכו פטור שנאמר ממנו ולא לתוכו:\",2,0],[8,383,11,3,\"גובה המעקה אין פחות מעשרה טפחים וכו'. בסיפרי כמה הוא מקום מעגלו שלשה טפחים בית דורסו עשרה ופירש ספר מצות גדול מעגלו גובהו בבור ג' טפחים ובבית גובהו עשרה. והראב\\\"ד כתב על דברי רבינו גובה המעקה אין פחות מעשרה טפחים א\\\"א דוקא ממקום דורסו והוא המקום הנמוך שבו אבל שאר צדדים ג' טפחים עכ\\\"ל. נראה שהיה מפרש כן הברייתא הנזכרת ונראה לי שהטעם הוא שמאחר שמצד אחד הוא גבוה י' טפחים ע\\\"י כך הוא נזהר משאר צדדין שאין גבהם אלא ג' טפחים:\",1,0],[8,383,11,3,\"וצריך להיות המחיצה חזקה וכו'. פשוט הוא:\",2,0],[8,383,11,3,\"כל המניח גגו בלא מעקה וכו'. בספרי ופשוט הוא:\",3,0],[8,383,11,4,\"אחד הגג ואחד כל דבר שיש בו סכנה וכו'. בסיפרי אין לי אלא גג מנין לרבות בורות שיחין ומערות חריצין ונעיצין ת\\\"ל לא תשים דמים בביתך:\",1,0],[8,383,11,4,\"חייב לעשות חוליא גבוה עשרה טפחים. מכאן נראה שלא היה מפרש רבינו מקום מעגלו כמו שפירש ספר מצות גדול:\",2,0],[8,383,11,4,\"וכן כל מכשול שיש בו סכנת נפשות וכו'. בפ\\\"ק דב\\\"ק (דף ט\\\"ו:) תניא ר' נתן אומר מנין שלא יגדל אדם כלב רע בתוך ביתו ולא יעמיד סולם רעוע בתוך ביתו שנאמר ולא תשים דמים בביתך:\",3,0],[8,383,11,5,\"הרבה דברים אסרו חכמים מפני שיש בהם סכנת נפשות וכו'..\",1,0],[8,383,11,6,\"ואלו הן לא יניח אדם פיו על הסילון וכו' ולא ישתה בלילה מן הנהרות וכו'. בפ\\\"ק דע\\\"ז (דף י\\\"ב:):\",1,0],[8,383,11,6,\"ולא ישתה מים מגולים וכו'..\",2,0],[8,383,11,7,\"ואלו הם המשקים האסורים משום גילוי המים והיין והחלב. פרק ח' דתרומות.\",1,0],[8,383,11,7,\"ומ\\\"ש ואפי' מזוג. פ\\\"ב דע\\\"ז (דף ל').\",2,0],[8,383,11,7,\"ומ\\\"ש ואפי' התחיל טעמו להשתנות לחומץ. ג\\\"ז שם.\",3,0],[8,383,11,7,\"ומ\\\"ש והדבש והציר. בפרק אלו טריפות (חולין דף מ\\\"ט:):\",4,0],[8,383,11,8,\"ומ\\\"ש השום שנתרסק. בפ\\\"ק דביצה (דף ז':).\",1,0],[8,383,11,8,\"ומ\\\"ש ואבטיח שנחתך ונתגלה אסור. בפרק ב' דע\\\"ז (דף ל':).\",2,0],[8,383,11,8,\"ומ\\\"ש יין מבושל ויין תוסס וכו'. שם.\",3,0],[8,383,11,8,\"ומ\\\"ש ויין או מים וכו' כל זמן שההבל עולה מהן. ירושלמי בפרק ח' דתרומות.\",4,0],[8,383,11,8,\"ומה שכתב וכן משקין שהיה המשקה יורד מלמעלה לתוכן טיפה טיפה וכו'. בפ\\\"ב דעבודה זרה (דף ל':):\",5,0],[8,383,11,9,\"ומ\\\"ש מי כבשים ומי שלקות ומי תורמוסין וכו'. [שם בירושלמי מי כבשים ומי שלקות ומי תורמוסין הרי אלו מותרין] מים שהדיח בהם כבשים ושלקין ותורמוסים הרי אלו אסורים ומפרש רבינו דהיינו דוקא כשלא נשתנה טעמן שאם נשתנה טעמן היינו מי תורמוסין דשרו וכ\\\"נ מתוספתא אלא שכתובה בחילוף.\",1,0],[8,383,11,9,\"ומ\\\"ש וכן מים ששרה בהם פרישין וכו'. שם:\",2,0],[8,383,11,10,\"יין שנתחבר בו דברים חדים כפלפלים או דברים מרים וכו'. שם ובגמרא דידן בפרק ב' דעבודה זרה:\",1,0],[8,383,11,11,\"כל המשקין האסורים משום גילוי וכו'. בפרק ב' דע\\\"ז:\",1,0],[8,383,11,11,\"וכמה ישהו ויאסרו וכו'. משנה פרק ח' דתרומות ומייתי לה פירקא קמא דחולין (דף י'):\",2,0],[8,383,11,12,\"שיעור המים שיאסרו אם נתגלו וכו'. משנה פרק שמיני דתרומות וכת\\\"ק:\",1,0],[8,383,11,13,\"מעיין המושך כל שהוא אין בו משום וכו'. ירושלמי פ\\\"ח דתרומות:\",1,0],[8,383,11,13,\"לגין מגולה שהניחו וכו'. ירושלמי שם לגין שהניחו בשידה תיבה ומגדל שכחו וחזר ומצאו אסור בדק ואח\\\"כ הניחו מותר.\",2,0],[8,383,11,13,\"ומ\\\"ש או בתיק שלו או בבור וכו'. בתוספתא פ\\\"ו.\",3,0],[8,383,11,13,\"ומ\\\"ש ואם היה בהם נקב אסור כמה יהא בנקב וכו'. (שם) ובירושלמי פרק ח' דתרומות ומסיים בה עד שלא תכנס ראש אצבע קטנה של תינוק בן יומו ואיני יודע למה השמיטו רבינו וצ\\\"ל דמדסתם של קטן משמע היותר קטן שבכולם היינו בן יומו:\",4,0],[8,383,11,14,\"חבית שנתגלתה וכו'. שם ובגמרא דידן פ\\\"ב דע\\\"ז:\",1,0],[8,383,11,15,\"ומ\\\"ש ולא ישקה מהם לבהמתו וכו'. בפרק ב' דע\\\"ז.\",1,0],[8,383,11,15,\"ומ\\\"ש אבל משקה אותן לחתול מפרש בגמרא דה\\\"מ לחתול שלו אבל לא לחתול של חבירו משום דאע\\\"ג דלא ממית ליה ארס הנחש מכחיש ליה ואע\\\"ג דהדר ברייא זימנין דבעי לזבוניה ומפסיד ליה מיניה ורבינו השמיט זה משום דהשתא אין דרך למכור חתול:\",2,0],[8,383,11,16,\"עיסה שנילושה וכו'. בירושלמי פרק שמיני דתרומות מתיר רבי נחמיה ומשמע דתנא קמא אוסר.\",1,0],[8,383,11,16,\"ומה שכתב אפילו של תרומה תשרף. תוספתא פרק ו':\",2,0],[8,383,12,1,\"בהמה חיה או עוף שנשכן הנחש. משנה סוף פרק אלו טריפות (חולין דף נ\\\"ח:).\",1,0],[8,383,12,1,\"ומה שכתב או שאכלו סם המות הממית האדם הרי אלו אסורים. שם בגמרא וכתב רבינו דהיינו דוקא קודם שישתנה בגופו כלומר שאם שהה עד שנשתנה בגופו שוב אינו מזיק.\",2,0],[8,383,12,1,\"ומה שכתב לפיכך בהמה חיה ועוף שנמצאו חתוכי רגלים וכו' עד הרי אלו מותרים. עובדא שם (דף נ\\\"ט):\",3,0],[8,383,12,2,\"וכן נקורי תאנים וכו'. משנה פרק ח' דתרומות.\",1,0],[8,383,12,2,\"ומ\\\"ש ואפילו ראה צפור וכו'. פ\\\"ק דחולין (דף ט'):\",2,0],[8,383,12,3,\"ומ\\\"ש תאנה או ענב וכו'. בפ\\\"ב דע\\\"ז (דף ל':) ופ\\\"ח דתרומות בירושלמי:\",1,0],[8,383,12,4,\"אסור לאדם ליתן מעות וכו'. בירושלמי פרק ח' דתרומות א\\\"ר אמי צריכין למיחש למה דברייתא חששין אסור למיתן פריטין גו פומא תבשילא תותי ערסא פיסתא תחות שיחיא מיצנע סכינא גו פוגלא סכינא גו אתרוגא א\\\"ר יוסי בר בון כל זיעא דנפקא מבר נש סם המות הוא חוץ מזיעת הפנים:\",1,0],[8,383,12,5,\"וכתב הראב\\\"ד וכן לא יתן אדם פס וכו'. א\\\"א בירושלמי אסור למיתן פיסתא וכו'. ועל מ\\\"ש רבינו וכן לא יתן התבשיל תחת המטה כתב א\\\"א גם זה בירושלמי ומפרשין מפני רוח רעה.\",1,0],[8,383,12,5,\"ועל מ\\\"ש וכן לא ינעוץ הסכין וכו'. כתב גם זה מפרשים משום בזוי שעושה מהם תיק לסכין עכ\\\"ל. ואין הכרח לפירוש זה יותר מזה וירא שמים יצא את כולם:\",2,0],[8,383,12,6,\"וכן אסור לעבור תחת קיר נטוי. בפ\\\"ק דראש השנה (דף ט\\\"ז:).\",1,0],[8,383,12,6,\"ומ\\\"ש או ליכנס לחורבה. בפ\\\"ק דברכות (דף ג'):\",2,0],[8,383,12,8,\"וכן אסור ליהודי להתייחד עם העכו\\\"ם וכו' עד אל אדוני שעירה. בפרק ב' דעבודה זרה (דף כ\\\"ה:):\",1,0],[8,383,12,9,\"אסור ליקח רפואה מן העכו\\\"ם וכו'. שם אמר ר\\\"י וכו' ספק חי ספק מת אין מתרפאין מהם ודאי מת מתרפאין מהם הא איכא חיי שעה לחיי שעה לא חיישינן וכו' מיתיבי לא ישא ויתן אדם עם האפיקורוסים ואין מתרפאין מהם אפילו לחיי שעה וכו' שאני אפיקורסות דמשכא ואתי לממשך בתרייהו.\",1,0],[8,383,12,9,\"ומה שכתב ומותר ליקח רפואה מן העכו\\\"ם לבהמה וכו'. משנה שם מתרפאין מהם [ובגמרא] ואיכא דאמרי וכו' אמר רבי יוחנן כל מכה של חלל אין מתרפאין מהם מאי בינייהו איכא בינייהו גב היד וגב הרגל דאמר רב אדא בר מתנא אמר רב גב היד וגב הרגל הרי הן כמכה של חלל ומחללין עליהן את השבת ופסק רבינו כלישנא קמא להחמיר בסכנת נפשות וכ\\\"ש דמסתבר טעמיה. ולזה נתכוון עוד במה\",2,0],[8,383,12,9,\"שכתב ואם היתה של סכנה אסור ליקח ממנו כלומר אפילו שהמכה מבחוץ אם היתה של סכנה כגון גב היד וגב הרגל אסור ליקח ממנו:\",3,0],[8,383,12,10,\"ומה שכתב ומותר לשאול לרופא עכו\\\"ם וכו'. גם זה שם ומפרש טעמא דסבר דמשאיל לי משאיל לאיניש אחרינא ואתי ההוא גברא לאורועי נפשיה:\",1,0],[8,383,12,11,\"ואסור להסתפר מהם. משנה שם וכחכמים ואמרינן בגמרא (דף כ\\\"ט) שאם ישראל רואה במראה מותר להסתפר מהם אפי' ברה\\\"י משום דע\\\"י המראה מתחזי כאדם חשוב ומתיירא להורגו:\",1,0],[8,383,12,14,\"אסור למכור כל כלי המלחמה וכו' עד לישראל שהוא לסטים. בפירקא קמא דעבודה זרה (דף ט\\\"ו:):\",1,0],[8,383,12,14,\"ומה שכתב וכן כל המכשיל עור וכו'.\",2,0],[8,383,12,15,\"ואסור להשיא עצה טובה לעכו\\\"ם או וכו'. בפרק קמא דבתרא (דף ד') וכשינויא בתרא דקאמר ואי בעית אימא שאני בית המקדש דאי לאו מלכותא לא מתבני:\",1,0],[8,383,13,1,\"מי שפגע וכו'. ומה שכתב בין שהיה עליה יותר ממשאה. בסוף פרק אלו מציאות (בבא מציעא דף ל״ב) במשנה רבי יוסי הגלילי אומר אם היה עליו יותר ממשאו אינו זקוק לו ומשמע דרבנן פליגי עליה ופסק כוותייהו:\",1,0],[8,383,13,2,\"ומ\\\"ש ולא יפרוק ויניחנו נבהל וילך אלא יקום עמו וכו'. שם בגמ':\",1,0],[8,383,13,4,\"היה כהן וכו'. שם משנה.\",1,0],[8,383,13,4,\"ומה שכתב וכן אם היה זקן שאין דרכו לטעון ולפרוק עד פורק וטוען עמו. גם זה שם:\",2,0],[8,383,13,5,\"פרק וטען וחזרה ונפלה וכו'. משנה שם.\",1,0],[8,383,13,5,\"ומ\\\"ש לפיכך צריך להדדות עמו עד פרסה. שם (דף ל\\\"ג):\",2,0],[8,383,13,6,\"מאימתי יתחייב לפרוק ולטעון עמו. ברייתא שם:\",1,0],[8,383,13,7,\"מצוה לפרוק עמו בחנם וכו'. משנה וגמרא שם (דף ל\\\"ב ל\\\"ג) וכתנא קמא.\",1,0],[8,383,13,7,\"ומה שכתב וכן בשעה שמדדה עמו וכו'. מימרא שם:\",2,0],[8,383,13,8,\"מצא בהמת חבירו רבוצה וכו'. נלמד ממה שיבא בסמוך אם היה זקן או חולה חייב וטעמא משום דהני כמאן דליתנהו דמי.\",1,0],[8,383,13,8,\"ומ\\\"ש שאם היה בעל הבהמה שם והלך וישב לו וכו' עד חייב לטעון ולפרוק לבדו. משנה שם:\",2,0],[8,383,13,9,\"בהמת העכו\\\"ם וכו'. שם (דף ל\\\"ב:) בהמת עכו\\\"ם ומשוי ישראל וחדלת ואי אמרת צער ב\\\"ח דאורייתא אמאי וחדלת עזוב תעזוב מ\\\"מ לעולם צער ב\\\"ח דאורייתא והתם בטעינה א\\\"ה אימא סיפא בהמת ישראל ומשוי עכו\\\"ם עזוב תעזוב ואי בטעינה אמאי עזוב תעזוב משום צערא דישראל א\\\"ה אפילו רישא נמי רישא בחמר עכו\\\"ם סיפא בחמר ישראל מאי פסקא סתמא איניש בתר חמריה אזיל ואע\\\"ג דבתר הכי אמרינן והא וחדלת ועזוב תעזוב בפריקה הוא דכתיבי אלא הא מני ר\\\"י הגלילי היא דאמר צער ב\\\"ח לאו דאורייתא מ\\\"מ שמעינן ממאי דשקלינן וטרינן בה לדידן דקי\\\"ל צער ב\\\"ח דאורייתא והטעם משום דאמרינן שם בגמרא על רבנן ור\\\"ש מדברי שניהם נלמוד צער ב\\\"ח דאורייתא ואע\\\"ג דמתיב עליה הא שני כל מאי דאותביה ואע\\\"ג דר\\\"י הגלילי פליג ואמר צער ב\\\"ח לאו דאורייתא יחידאה הוא וכן פסקו הרי\\\"ף והגאונים צער ב\\\"ח דאורייתא והשתא מ\\\"ש רבינו גבי בהמת העכו\\\"ם אם היה העכו\\\"ם מחמר אחר בהמתו אינו זקוק לה היינו דוקא לטעון אבל לפרוק חייב משום צער בעלי חיים דאורייתא וכדאוקימנא וכך מתפרשים דברי רבינו משום דמסיפא שכתב ואם לאו חייב לפרוק ולטעון דמשמע אבל ברישא אינו חייב בתרוייהו אלא בחדא דהיינו לטעון וסמך עוד על מ\\\"ש בסוף הפרק הפוגע בשנים וכו' מצוה לפרוק בתחלה משום צער ב\\\"ח ואין לומר דרבינו סבר דצער ב\\\"ח דרבנן וכר\\\"י הגלילי מכמה טעמי חדא דלא הוה ליה למיפסק כיחידאה ועוד דהא תנן דלר\\\"י הגלילי אם היה עליו יותר ממשאו אינו זקוק לו ורבינו סתם ולא חילק בכך ועוד דתניא דלר\\\"י הגלילי רובץ ולא רבצן רובץ ולא עומד תחת משאו ולא מפורק ורבינו לא חילק בכך הילכך ע\\\"כ לומר שהוא פוסק כרבנן דצער ב\\\"ח דאורייתא:\",1,0],[8,383,13,9,\"כתב הטור בסימן רע\\\"ב על דברי רבינו ואין דבריו מובנים לי ברישא שהעכו\\\"ם מחמר למה אין חייב לסייעו משום איבה וכי גרע מבהמה והמשא של עכו\\\"ם וכן בסיפא בהמה של ישראל והמשא של עכו\\\"ם למה לי משום ישראל תיפוק לי משום מצות פריקה כיון שהיא בהמת ישראל עכ\\\"ל. וכתב על זה החכם המרשים דבריו מובנים דברישא כיון שמשוי של ישראל לא חיישינן לאיבה והיינו טעמא דמקשה בגמ' בהמת עכו\\\"ם ומשוי ישראל אמאי וחדלת ול\\\"ק ליה דילמא טעמא משום איבה אבל אם הישראל [שם] חייב אפי' לטעון ולא משום דין פריקה וטעינה דודאי תורה לא משתעי אלא בשהכל של ישראל אלא משום צערא דישראל חייב נמי משום צערא דבהמה והיינו טעמא דסיפא דכיון דאין הכל של ישראל אין כאן מצות פריקה וטעינה כלל ומשום צערא דישראל שייך אפילו בטעינה חייב דאילו בפריקה צערא דבהמה נמי איכא אי נמי נקט בסיפא טעמא דצערא דישראל משום טעינה לחוד דסליק מיניה עכ\\\"ל. ואין דבריו מחוורים שכתב אבל אם הישראל שם חייב אפי' לטעון ולא משום דין פריקה וטעינה וכו' אלא משום צערא דישראל וכו' ומנ\\\"ל דחייב משום צערא דישראל אם לא שהתורה הזהירה על פריקה וטעינה:\",2,0],[8,383,13,9,\"ועל הטור יש לתמוה למה לא הקשה על הרישא דליחייב לפרוק משום צער בע\\\"ח וזה בעצמו קשה גם על החכם המרשים שכתב דברישא כיון שהמשוי של ישראל לא חיישינן לאיבה והא בלא טעמא דאיבה קשה למה כתב ואינו זקוק לה דמשום צער בעלי חיים ליחייב מיהא לפרוק ול\\\"נ דמעיקרא לק\\\"מ דרבינו חיוב ופיטור מטעם טעינה ופריקה בלחוד אתא לאשמועינן דאילו חיובו משום איבה בסוף דבריו אשמעינן שכתב אינו חייב להטפל בו אלא משום איבה.\",3,0],[8,383,13,9,\"ומ\\\"ש רבינו אבל בהמת העכו\\\"ם ומשאו וכו'. שם:\",4,0],[8,383,13,11,\"חמרים שרגליו של אחד מהם רעועות וכו'. תוספתא (פ\\\"ב דב\\\"ק) כתבוה הרי\\\"ף והרא\\\"ש ר\\\"פ אחד דיני ממונות. וכתב הראב\\\"ד חמרים שרגליו של אחד מהם רעועות וכו' פירוש אין חבריו רשאים לדרוס עליו וכו'. ותמיהא לי שיהיה להם רשות לדרוס על החמור שנפל שאפשר שימיתוהו בדריסתם ול\\\"נ דה\\\"פ שאינם רשאים לילך להם ולהניחו כל זמן שלא נפל:\",1,0],[8,383,13,12,\"ומה שכתב וכן שתי ספינות וכו'. ברייתא שם (סנהדרין דף ל\\\"ב) ופירש רש\\\"י קרובה לעירה:\",1,0],[8,383,13,13,\"הפוגע בשנים וכו' עד כדי לכוף את יצרו הרע. בסוף פרק אלו מציאות (בבא מציעא דף ל״ב ל״ג):\",1,0],[8,383,13,14,\"השונא שנאמר בתורה לא מאומות העולם הוא וכו'. שם (דף ל\\\"ב:) ת\\\"ש שונא שאמרו שונא ישראל ולא שונא אומות העולם ואי אמרת צער ב\\\"ח דאורייתא מה לי שונא ישראל מה לי שונא אומות העולם מי סברת אשונא דקרא קאי אשונא דמתניתין קאי ופירוש רש\\\"י שונא שאמרו קס\\\"ד שונא שאמרו לשונא דקרא קאי דמשתעי בפריקה כי תראה חמור שונאך רובץ אשונא דמתני' קאי אהך מתניתא דלעיל דשונא לטעון הוא עכ\\\"ל. והשתא יש לתמוה מאחר שרבינו פוסק דצער ב\\\"ח דאורייתא על כרחך שונא שנאמר בתורה בין שונא ישראל בין שונא א\\\"ה הוא וא\\\"כ היאך כתב השונא שנאמר בתורה לא מא\\\"ה הוא אלא מישראל ואפשר לדחוק ולפרש לשון רבינו דה\\\"ק לא שונא אומות העולם בלבד הוא אלא אף בשונא מישראל מיירי והקדים זה כדי לומר והיאך יהיה לישראל שונא מישראל ועוד י\\\"ל דבפרק ע\\\"פ (דף קי\\\"ג:) על הא דקאמר שהרואה דבר ערוה בחבירו לא יעיד בו יחידי אמר רב מותר לשנאתו שנאמר כי תראה חמור שונאך רובץ תחת משאו מאי שונא אילימא שונא עכו\\\"ם והתניא שונא שאמרו שונא ישראל ולא שונא א\\\"ה אלא פשיטא שונא ישראל ומי שרי למסנייה והא כתיב לא תשנא את אחיך בלבבך וכו' אלא לאו כהאי גוונא וכו' הרי בהדיא דרב סבר דשונא דקרא בשונא ישראל ולא בשונא אומות העולם וא\\\"ת א\\\"כ הדרא קושיא לדוכתא אי אמרת צער ב\\\"ח דאורייתא מה לי שונא ישראל ומה לי שונא א\\\"ה י\\\"ל דהוה מצי לשנויי ישראל בחנם עכו\\\"ם בשכר כמ\\\"ש התוס'. ועל מ\\\"ש רבינו מצוה לטעון ולפרוק עמו איכא למידק דהא קרא דכי תראה חמור שונאך בפריקה מיירי כדכתיב רובץ תחת משאו ואילו קרא דטעינה דהיינו קרא דכתיב לא תראה את חמור אחיך או שורו נופלים בדרך דרמי טוענייהו באורחא משמע כדאמרינן בגמ' הא לא כתיב ביה שונא וי\\\"ל דכיון דחזינן דלגבי פריקה השוה הכתוב שונא לאוהב אית לן למימר דה\\\"ה לטעינה שהוא כאוהב:\",1,0],[8,383,13,14,\"סליקו להו הלכות רוצח ושמירת נפש בס\\\"ד\",2,0],[8,384,1,1,\"האומר לשליח צא ומכור לי קרקע וכו'. בריש האיש מקדש (קידושין דף מ״א ע״ב) אמרינן ששלוחו של אדם כמותו בכל התורה כולה וילפינן לה מקדושין וגירושין ואתיא מבינייא:\",1,0],[8,384,1,1,\"ואין העושה שליח צריך קנין. נתבאר בסוף פ\\\"ה מהלכות מכירה:\",2,0],[8,384,1,1,\"ולא עדים וכו' ואין צריכים עדים וכו'. בקידושין פרק האומר (דף ס\\\"ה ע\\\"ב) מעובדא דמר זוטרא ורב אחא סבא דאמר להו רב אשי לא איברי סהדי אלא לשקרי שמעינן דבכל מידי דממון היכא דשניהם מודים שכך עבד לא בעינן עדים:\",3,0],[8,384,1,2,\"שליח שעבר על דברי משלחו וכו'. זה פשוט ומתבאר בסמוך בבא דהאומר לשלוחו מכור לו משדה שלי בית סאה ובכמה מקומות בגמרא אמרו מצי למימר ליה לתקוני שדרתיך ולא לעוותי:\",1,0],[8,384,1,2,\"וכן אם טעה בכל שהוא וכו'. בכתובות פרק אלמנה ניזונית (כתובות דף צ״ט ע״ב) דאמרו ליה לרב נחמן אע״ג דטעה שליח [ממכרו קיים] א״ל טעה שליח לא קאמינא והא אמר מר אין אונאה לקרקעות הני מילי היכא דטעה בעל הבית אבל טעה שליח א״ל לתקוני שדרתיך ולא לעוותי ובהאיש מקדש גבי הא דאמר ר״נ האחין שחלקו הרי הן כלקוחות פחות משתות נקנה מקח לא אמרן אלא היכא דלא שוי שליח אבל שוי שליח א״ל לתקוני שדרתיך ולא לעוותי:\",2,0],[8,384,1,3,\"נתן מעות לשלוחו לקנות לו קרקע וכו'. מעשה בבתרא בפרק גט פשוט (בבא בתרא דף קס״ט ע״ב) ופירש שלא באחריות שפירש בשטר שאין לו עליו אחריות דאילו בסתם הא קי״ל אחריות ט״ס הוא וכמ״ש רבינו פי״ט מהלכות מכירה. וא״ת אם זה השליח כשקנה הקרקע פירש שקונהו למשלח למה נחייב השליח לקיים המקח נימא ביטול מקח כמו כשנתאנה שאין מחייבין לשליח ואם לא פירש שקונה אותו למשלח אלא קנה סתם והוה ליה כקונה לעצמו למה נחייב המשלח המוכר שיקבלנה נימא ליה אתה קנית לעצמך ומדברי רבינו פ״ב נראה שמעשה זה בסתם היה וכמ״ש שם דאילו הודיעו דלמשלח קונהו היה המקח בטל וקשה א״כ למה נחייב המשלח לקבלה כמ״ש. והר״ן בפרק האיש מקדש תירץ דאה״נ דאין כופין למשלח ויכול לומר לו תן לי מעותי דלתקוני שדרתיך ולא לעוותי ויותר הייתי רוצה באחריות מוכר מאחריותך אלא אם הוא חפץ בקרקע יקבל השליח עליו אחריות, ולי נראה דאה״נ דמחייבין למשלח לקבלה כשיקבל עליו השליח אחריות מפני שהרי קנאה במעות המשלח ואין כאן אונאה לגבי המשלח שה״ז יקבל עליו אחריות ונראה שזו כוונת רבינו שכתב חוזר ומוכרה למשלח באחריות הואיל וקנה אותן במעותיו ובפ״ז מהלכות מכירה נראה כן. והראב״ד כתב על דברי רבינו באמת כך הוא דרך הגמ' וכו':\",1,0],[8,384,1,3,\"לפיכך אם וכו'. זה פשוט דכל דבר שבממון תנאו קיים:\",2,0],[8,384,1,4,\"האומר לשלוחו וכו'. כתובות פרק אלמנה (דף צ\\\"ט) איבעיא להו א\\\"ל (פירוש לשלוחו) זבין לי ליתכא ואזיל וזבין ליה כורא מאי ואיכא דאמרי הא לא תיבעי לך דודאי מוסיף על דבריו הוא [וליתכא מיהא קני] כי תבעי לך דא\\\"ל זיל זבין כורא ואזל וזבין ליתכא מאי כלומר ומשכח לזבוני האי ליתכא בתרא בדמי ליתכא קמא דאי לאו הכי פשיטא דמעביר על דבריו הוי ושקלי וטרו בגמ' למפשטה וכתב הרי\\\"ף וסוגיין דמעביר על דבריו הוי כלומר ולא קנה ובלאו הכי כיון דבעיא לא איפשיט להדיא אית לן לאוקומי קרקע בחזקת בעליה ולא יוציאנה מספק דדילמא מעביר על דבריו הוי והיינו בבעיא בתרייתא אבל בקמייתא נקטינן כא\\\"ד דפשטי' דמוסיף על דבריו הוי וקנה ודע שהנוסחא של ספרי רבינו שבידינו משובשת וכך צריך לגרוס בבבא השנית ולא קנה הלוקח וכך היא בספרים מדוייקים וכתב הר\\\"ן בפרק אלמנה ניזונת שאין השליח יכול לקנות אפילו באותם דמים שהרשוהו בעלים למכור לפי שכיון שהוא שליח הרי הוא ביד הבעלים וכ\\\"כ הטור וכ\\\"כ מגיד משנה פי\\\"ז מהלכות אישות:\",1,0],[8,384,1,4,\"אמר לו מכור לי שדה וכו'. שם פשיטא אמר לחד [קפידא] כלומר ואי זבין לתרי לא הוי זביניה זביני זו גירסת הרי\\\"ף והיא גירסת רבינו ופירש הרמב\\\"ן דאפילו מכר לשניהם בשטר אחד דליכא למימר לא ניחא לי דליפשו שטרי עילואי הוי קפידא משום אפושי בעלי דינין:\",2,0],[8,384,1,4,\"אמר לו מכור לי שדה וכו' שם סתמא מאי רב הונא אמר לאחד ולא לשנים רב חסדא ורבה בר רב הונא דאמרי תרוייהו לאחד ואפי' לשנים לאחד ואפילו למאה אקלע ר\\\"נ לסורא עול לגביה רב חסדא ורבה בר רב הונא א\\\"ל כה\\\"ג מאי א\\\"ל לאחד ואפילו לשנים לאחד ואפילו למאה והו\\\"ל רב הונא יחיד ולית הלכתא כוותיה ועוד דהא קיימא לן דהלכתא כר\\\"נ בדיני וא\\\"ת לפי גירסת הרי\\\"ף ורבינו כי אמרו סתמא מאי היינו שא\\\"ל צא מכור שדה שלי ולא הזכיר לו לא אחד ולא שנים וא\\\"כ היאך אמר רב הונא לאחד ולא לשנים וכן בני פלוגתיה אמרו לאחד ואפילו לשנים דמשמע שהזכיר בדבריו למכור לאחד וי\\\"ל דה\\\"פ לאחד ולא לשנים כלומר כשאמר לו למכור דעתו וכוונתו למכור לאחד ולא לשנים ודפליגי עליה סברי שכוונתו שימכור כאשר ימצא בין לאחד בין לשנים בין למאה:\",3,0],[8,384,1,5,\"הנותן מעות לשלוחו וכו'. ירושלמי פרק איזהו נשך (דף י' ע\\\"ב) הנותן מעות לחבירו ליקח בהן פירות למחצית ואמר לא לקחתי אין לו עליו אלא תרעומת ולמד משם רבינו דין השליח וקשה למה לא כתב רבינו סוף הירושלמי שאומר ואם ידוע שלקח מוציא ממנו בעל כרחו וי\\\"ל שדין זה לא שייך בדיני שליח אלא בדיני מקח וממכר וכבר נתבאר בדבריו פ\\\"ו מהלכות מכירה:\",1,0],[8,384,1,5,\"נתן לו מעות ליקח בהם חטים וכו' כך העלה הרי\\\"ף בקמא פרק הגוזל עצים דאם פחתו פחתו לשליח מפני שהוא משנה ואם הותירו הותירו לבעל המעות:\",2,0],[8,384,1,5,\"היה השער קצוב וכו'. כתובות פרק אלמנה (דף צ\\\"ח) כאן שנה רבי פירוש במתניתין הכל לבעל המעות כדתניא הוסיפו לו אחת יתירה הכל לשליח דברי רבי יהודה רבי יוסי אומר [ גירסתנו הפוכה ר\\\"י דברייתא קמייתא חולקין ובשניה הכל לבעל המעות:] הכל לבעל המעות והתניא רבי יוסי אומר חולקין אמר רמי בר אבא אמר רבי יצחק לא קשיא כאן בדבר שיש לו קצבה כאן בדבר שאין לו קצבה כלומר ומתני' בדבר שאין לו קצבה ופירש\\\"י שיש לו קצבה כגון קטנית הנמכר בחנות במדה מלא כלי בפרוטה [אם הוסיפו אחת יתירה] חולקין דמתנה הואי י\\\"ל לשליח ניתנה וי\\\"ל לבעל המעות ניתנה אבל דבר שאין לו קצבה [כגון] חלוק וטלית וירק הנמכרים באומד פעמים מוותרים למכור בזול פעמים בצמצום הכל לבעל המעות שאין כאן מתנה אלא מכר אבל הרי\\\"ף כתב ולמה חולקין השליח ובעה\\\"ב הואיל ובאת לשליח הנאה ע\\\"י בעל הבית חולק עמו נראה שאפילו נתן המוכר לשליח בפירוש כיון שבאת הנאה לשליח ע\\\"י בעל הבית חולק עמו ולזה נוטים דברי רבינו וכתבו התוספות דמי שמינה את חבירו לקבל מעותיו מן העכו\\\"ם וטעה העכו\\\"ם ונתן לו יותר שהכל לשליח ואע\\\"פ שטעה העכו\\\"ם מעצמו ור\\\"ת חולק בדבר ונ\\\"ל דלדעת הרב אלפסי ורבינו שהטעם משום דכיון שבאת לשליח הנאה ע\\\"י בעל הבית חולקין הוא הדין דה\\\"נ חולקים וכתבו עוד שאם מסר ישראל לחבירו מאתים לשלם לעכו\\\"ם והטעה העכו\\\"ם ולא שלם אלא מאה דאז ודאי המעות כל שעה ברשות המשלח:\",3,0],[8,384,1,6,\"מי שהיה חייב לחבירו ממון בין משום וכו'. כן העלה הרב אלפסי ז\\\"ל בכתובות פרק הכותב:\",1,0],[8,384,1,6,\"וכן אם היה החוב בשטר וכו'. שם פרק הכותב (כתובות דף פ״ה) בגמרא עובדא ואמרו לענין שלומי שליח מאי ואסיקנא דבין א״ל שקול שטרא והב זוזי או הב זוזי ושקול שטרא משלם והטעם דכיון שפרעון המעות תלויים בשטר ובהזכרת לקיחת השטר גלי דעתיה שירא לתת לו המעות בלא שיתן לו השטר אבל כשלא הזכיר לו שטר לא בתחלה ולא בסוף נראה שאינו חושש אע״פ שישאר השטר בידו:\",2,0],[8,384,1,7,\"השולח מעות שבידו ביד שלוחו וכו'. פרק האיש מקדש (קידושין דף מ״ג) אמר רבא אמר ר״נ אמר לשנים צאו וקדשו לי את האשה הן הן שלוחיו הן הן עדיו וכן בדיני ממונות כלומר אם אמר לשנים תנו מנה זה לפלוני שאני חייב לו הם אומרים נתננו והוא אומר לא נטלתי מגו דיכלי למימר ליה אהדרינהו ללוה יכלי למימר ליה פרענוהו למלוה ואסיקנא דהשתא דתקון רבנן שבועת היסת כלומר דאי הוו אמרי אהדרונהו ללוה אז בעו לאשתבועי שבועת היסת כי אמרי פרענוהו למלוה מיחייבי נמי שבועת היסת דפרעינהו למלוה ולא מיקבלא עדותן דנוגעין בעדותן הן ומשתבע מלוה דלא שקיל ופרע ליה לוה כלומר דה״ל כדין חנוני על פנקסו המפורש במשנת כל הנשבעין שכתב רבינו פרק י״ו מהלכות מלוה ולוה מיהו לאו בחד גוונא משתבעי דשבועת מלוה היא שבועת המשנה בנקיטת חפץ כשבועה דפועלים שהרי הוא נשבע ונוטל כמותן אבל שבועת השלוחין אינה שבועת המשנה ששבועת המשנה אינה אלא בנשבעין ונוטלין אלא שבועת היסת כשבועת החנוני וזה דעת רבינו שכתב השליח נשבע היסת שנתן ובע״ח והפועל נשבע שלא לקח הרי שבשבועת המלוה לא הזכיר היסת אלא ודאי נשבע שבועת המשנה ולא ידעתי מניין לו להר״ן ז״ל שכתב שדעת רבינו שהמלוה נשבע שבועת היסת ותמה עליו ואולי נוסחא משובשת נזדמנה לו ובנוסחא מדוייקת כתוב בפירוש וב״ח או הפועל נשבע שבועת התורה:\",1,0],[8,384,1,7,\"כתב מהרי\\\"ק בשורש ק\\\"כ על מ\\\"ש רבינו שאין הלה יכול להשבע היסת מפני שאין כאן מי שטען בודאי שלקח אפשר לומר דדוקא בכה\\\"ג שאין הב\\\"ח מודה בשום פרעון אבל היכא שמודה בפרעון אלא שטוען שמצד אחר היה חייב לו חייב לישבע היסת:\",2,0],[8,384,1,7,\"בד\\\"א בשהיה השליח מכחיש וכו' אבל אם בא השליח וכו'. כלומר משום דאין נשבעין היסת אלא בטענת ברי ואע\\\"פ שכשהשליח מכחיש לבעל חוב נשבע היסת וב\\\"ח אינו טוען ברי שלא פרעו שאני התם שהמלוה טוען ברי שלא קבלם אבל היכא שהמלוה ליתיה קמן דנשייליה אין כאן אלא טענת ספק ואין משביעין עליה:\",3,0],[8,384,1,7,\"וכן אם מתו השלוחין או הלכו להן וכו' משום דהוה ליה איני יודע אם פרעתיך כיון דליכא מאן דמכחיש ליה ואינו יכול להשביעו אפילו שבועת היסת:\",4,0],[8,384,1,8,\"ראובן ששלח כתב לשמעון ואמר לו מנה וכו'. כך כתב הרב אלפסי ז\\\"ל פ' הגוזל עצים היכא דשדר [ליה לחבריה] כתבא ואמר ליה ההוא מידי דאית לי גבך שדרינהו ניהלי [בהדי פלניא ושדרינהו ניהליה] לא מיחייב באחריותו דהכי נהגו האידנא תגרי וכתב הטור ומשמע מדבריו אפילו לא ייחד לו שום אדם ובעל התרומות כתב וז\\\"ל אבל מדברי הרמב\\\"ם ז\\\"ל משמע דס\\\"ל שצריך לייחד לו שליח בפירוש עכ\\\"ל ונוסחא דידן בהרי\\\"ף ז\\\"ל שדרינהו לי בהדי פלניא וכך הם דברי רבינו. כתב הרא\\\"ש לא ידענא למה הוצרך לתלות דבר זה במנהג אם יש עדים שהוא כתב ידו או אם הוא מודה שהוא כתב ידו ואפילו רבה דאמר דשליח שעשאו בעדים לא הוי שליח בכה\\\"ג מודה עכ\\\"ל ונראה שכך הוא דעת רבינו שסתם דבריו ולא תלה הדבר במנהג וכתב עוד הרי\\\"ף וה\\\"מ מדעתיה דלוה או נפקד אבל בעל כרחיה לא וזהו שכתב רבינו אם רצה לשלחו:\",1,0],[8,384,1,8,\"ואם טען המלוה ואמר לא וכו'. משום שאומר לו מנה לי בידך והלה אומר פרעתיך שנתתיו לשלוחך לפיכך נשבע היסת ונפטר:\",2,0],[8,384,1,8,\"אפילו היו כתובים בו סימנים לא וכו'. פרק הגוזל עצים (בבא קמא דף ק״ד) א״ר יהודה אמר שמואל אין משלחין מעות בדיוקני פירוש סימנין וצורות שביניהם ור' יוחנן אמר משלחין ופסק הרי״ף כשמואל:\",3,0],[8,384,1,8,\"שמעון חייב באחריותו וכו'. נ\\\"ל הטעם לפי שכיון שאינו יודע שהיה כתב ידו הוה ליה כאומר לו מנה לי בידך והלה אומר איני יודע אם פרעתיך שחייב:\",4,0],[8,384,1,8,\"ויש מי שהורה וכו'. נראה לי הטעם לפי שאפשר שכתב ולאו אדעתיה ורמו רבנן עליה שבועה כי היכי דלידוק כמו שאמרו בהכותב גבי פוגמת כתובתה דפרע דייק דמפרע לא דייק ורמו רבנן שבועה עליה כי היכי דתידוק:\",5,0],[8,384,1,9,\"לוי שבא בשליחות ראובן וכו'. באמת פשט לשון זה שכתב ראובן נשבע וכו' כדין כל מודה מקצת קשה שמודה מקצת הטענה נשבע ולא משלם וזה נשבע ונוטל והטור כתב מפני קושיא זו שאינו מבין דברי רבינו ונראה לי ליישב דברי רבינו דלצדדין קתני דכי קתני לוי שבא בשליחות ראובן ולקח נ' משמעון היינו ששלח ראובן לומר לשמעון שילוה לו כ' דינרים וישלחם לו ביד לוי ושמעון אומר נ' היו וראובן אומר לא היו אלא כ' הרי ראובן נשבע שבועה דאורייתא שלא היו אלא כ' כדין כל מודה מקצת שהוא נשבע ולא משלם ולוי נשבע היסת ונפטר זהו כששלח ראובן ללוות משמעון אותם המעות אבל אם לא שלח ראובן אלא לגבות חובו משמעון ישלם שמעון מביתו שהרי ראובן אומר ודאי לא פרעתני שמאחר שלא מניתיו שליח להביא אלא כ' מה שנתת לו יותר לא בשליחותי נתת לו [וא\\\"כ לא הוי כהגיע לידי וגם הוא לא הביאם לי] ושמעון אומר שמא עשיתו שליח להביא כל החוב והוה ליה כאומר שמא פרעתיך הילכך ישלם שמעון לראובן כל חובו אחר שישבע ראובן שלא קיבל אלא כ' ולא חשש רבינו לכתוב שישבע ראובן לפי שסמך לו על מ\\\"ש בפרק זה דבשליח אומר נתתי וב\\\"ח אומר לא לקחתי שישבע הב\\\"ח שלא לקח וישלם לו הלה חובו ולישנא דרבינו דייק הכי שכתב וישלם שמעון מביתו אם חייב לראובן משמע דעד השתא מיירי בשאינו חייב לראובן:\",1,0],[8,384,2,1,\"אין העכו״ם נעשה שליח וכו' וכן אין ישראל וכו'. מסקנא דגמ' במציעא פ' איזהו נשך (בבא מציעא דף ע״א ע״ב) אהא דאמר רב אשי התם דבכל התורה כולה יש שליחות לעכו״ם דלא ילפינן מתרומה ואיכא דאמרי דאמר נמי דאנן לדידהו הוינן להו שליח וקאמר גמרא עלה הא דרב אשי בדותא היא אלא ילפינן כל התורה כולה מתרומה וכי היכי דאינהו לדידן לא הוו שליח אנן לדידהו נמי לא הוינן:\",1,0],[8,384,2,2,\"עושה אדם שליח איש או אשה אפי' אשת איש וכו'. דתנן בעירובין פרק חלון (עירובין דף ע״ט) מזכה לבני המבוי העירוב על ידי בנו ובתו הגדולים ועל ידי עבדו ושפחתו העברים ועל ידי אשתו אבל אינו מזכה ע״י בנו ובתו הקטנים [ולא על ידי] עבדו ושפחתו הכנענים מפני שידם כידו והמבוי מדין שליחות שהוא כאילו אותו אחר עשאו שליח לזכות בשבילו וקתני דע״י אשתו מזכה אלמא אפילו אשת איש נעשית שליח ועבדו ושפחתו הכנענים לא ממעט להו אלא מפני שידם כידו כלומר והוה ליה כעדיין העירוב ברשותו ולא נכנס עדיין לרשות אותם שרוצה לזכות להם הא לאו הכי יכולים להיות שלוחים וטעמא לפי שישנן במקצת מצות ואינם כעכו״ם דהא קרינן בהו בני ברית ובפרק השואל (דף צ״ח ע״ב) נמי תנן השואל את הפרה ושלחה ביד בנו או ביד עבדו או ביד שלוחו וכו' ומתה פטור ואמר רב התם אפילו עבד כנעני ואפילו שמואל דאמר דוקא ע״ע לא ממעט כנעני אלא משום דידו כיד רבו הא בשליחות שאינו נוגע לרבו בר שליחות הוא ואמרינן נמי בפרק שני דגיטין (דף כ״ג ע״ב) אמר ר' חייא בר אבא א״ר יוחנן אין העבד נעשה שליח לקבל גט אשה מיד בעלה לפי שאינו בתורת גיטין וקידושין הא למשא ומתן דאיתיה נעשה שליח ושם בפ״ב היו רוצים לדרוש מה אתם ישראל אף שלוחכם ישראל להוציא עבדים ואסיקנא אמרי דבי ר' ינאי לא מה אתם בני ברית אף שלוחכם בני ברית כלומר ועבדים בני ברית הם דכתיב מחוטב עציך לעברך בברית.\",1,0],[8,384,2,2,\"ומ״ש אבל מי שאינן בני דעת וכו'. בסוף המביא תניין גבי הא דתנן הכל כשרים להביא את הגט חוץ מחש״ו אמרינן בשלמא חש״ו לאו בני דעה נינהו ופירש״י וגבי שליחות איש בעינן ולא קטן דשליחות נפקא לן מויקחו להם איש שה לבית אבות אחד לוקח לכולם ע״כ וכיון שכן לכל מילי פסולים ובריש האיש מקדש (קידושין דף מ״ב ע״ב) מיבעי לכדרבי יצחק דא״ר יצחק איש זוכה ולא קטן זוכה ובפרק התקבל (גיטין דף ס״ד ע״ב) אמרו דקטנה זכיא בעירוב שהוא מדרבנן אבל לא בשאר דברים דהוו מדאורייתא:\",2,0],[8,384,2,2,\"לפיכך השולח בנו קטן וכו'. בבבא בתרא פרק הספינה (בבא בתרא דף פ״ז ע״ב) משנה השולח בנו אצל חנוני [ופונדיון בידו] ומדד לו באיסר שמן ונתן לו את האיסר ושבר את הצלוחית ואבד את האיסר חנוני חייב רבי יהודה פוטר שעל מנת כן שלחו ופיר״ש השולח בנו אצל חנוני ופונדיון בידו שהם ב' איסרים להביא לו שמן באיסר ואיסר יתן לו החנוני וכן עשה מדד לו באיסר שמן ונתן לו חנוני לתינוק את האיסר להביא לאביו השמן והאיסר ואמרו בגמרא בשלמא בשמן ואיסר בהא פליגי דרבנן סברי לאודועי שדריה כלומר להודיע לחנוני שצריך לשמן שדריה האב לבנו כדי שישלח לו חנוני ע״י שלוחו פיקח ור' יהודה סבר לשדורי ליה שדריה אלא שבר צלוחית אבידה מדעת היא כלומר דאע״ג דפונדיון נמי הוי אבידה מדעת מ״מ כיון שנשאר אצלו לא מיפטר עד שיבא לידו שוה פונדיון שמן ואיסר ואם היה מחזיר אותו פונדיון ה״נ דהוה פטור ודבר פשוט דהלכה כחכמים דלאודועי שדריה ומכיון שאמרו דצלוחית אבידה מדעת היא למדנו שאם פירש וא״ל שלח לי עם הקטן שהוא פטור:\",3,0],[8,384,2,3,\"האומר לחבירו מנה שיש לי בידך וכו'. משנה במציעא פרק השואל (דף צ\\\"ח ע\\\"ב) ז\\\"ל השואל את הפרה ואמר לו השואל שלחה לי ביד בני או ביד עבדי או ביד שלוחי או ביד בנך או ביד עבדך או ביד שלוחך או שא\\\"ל המשאיל הריני משלחה לך ביד בני וכו' וא\\\"ל השואל שלח ושלחה ומתה חייב כלומר השואל דהו\\\"ל כאילו הגיע לידו ובנו דקתני משמע דקטן הוא דאילו גדול היינו שלוחו ובר מן דין דין הקטן נלמד ממ\\\"ש בסמוך דצלוחית אבידה מדעת היא ועד השתא מיירי דשולח לקנות והכא בשולח לו חובו או פקדונו.\",1,0],[8,384,2,3,\"ומ\\\"ש וכן שנים שהתנו וכו'. כך העלה הרי\\\"ף בקמא פרק הגוזל עצים:\",2,0],[8,384,2,3,\"וכתב הראב\\\"ד וכן שנים שהתנו וכו' הרי המשלח פטור. א\\\"א ובשבועת היסת עכ\\\"ל ואני אומר דבודאי דבנגנב או נאבד כיון שהשליח מודה לא שייך התם שבועת היסת ולא נתכוון הראב\\\"ד אלא היכא דכפר בו השליח וכיון דבשאר החלוקות לא שייך לא חשש רבינו לכתוב שישבע היסת משום חלוקה אחת. או כוונת הראב\\\"ד ז\\\"ל שאפילו השליח מודה שקבלם אלא שנגנבו או אבדו צריך המשלח לישבע שבועת היסת דעד אחד לא פטריה משבועה דנוגע בדבר הוא או אפ\\\"ה לא קשיא שכבר נתבאר דין השליח בפרק הקודם ולא הוצרך לכפלו כאן:\",3,0],[8,384,2,4,\"השליח שקנה או שמכר וכו'. למד כן רבינו מההוא עובדא דפרק גט פשוט שכתבתי בתחלת פ\\\"א שאמר שהמקח קיים לגבי שליח שקנה שלא באחריות ובפרק אלמנה ניזונת אמרו שאם טעה שליח נתבטל המקח וסובר רבינו דכי אמרינן נתבטל המקח היינו כשהודיע שהוא שליח וכי אמרינן שהמקח קיים לגבי השליח היינו כשלא הודיע שהוא שליח.\",1,0],[8,384,2,4,\"ומ\\\"ש ויהיה דין בינו ובין זה ששלחו. כבר נתבאר בפ\\\"א:\",2,0],[8,384,2,5,\"ראובן שקנה שדה משמעון וכו'. ברייתא פרק הגוזל עצים (בבא קמא דף ק״ב) והטעם שכתב שטרו הראשון בשם לוי כדי שלא יצאו עליה עסיקין כשידעו שהיא של לוי שהוא אדם גדול ועל החלוקה הראשונה הקשו בגמ' פשיטא ותירצו מהו דתימא יודע היית שלעצמי אני לוקחה ולא כתבתי שטר בשם לוי אלא להצילה מעסיקין וזוזי בכדי לא שדינא אלא אדעתא דכתבת לי שטר אחרינא קמ״ל גם אסיפא הקשו פשיטא ותירצו לא צריכא כגון שלא התנה עם המוכר אלא אמר לעדים בפני המוכר עוד שטר אחר תכתבו לי על שדה זו מהו דתימא יאמר המוכר אני הייתי סובר שאתה רוצה לכתוב שטר אחר בשם לוי קמ״ל שאמר לו לכך אמרתי לעדים בפניך לומר שממך אני רוצה שתכתוב שטר בשמי ורבינו סתם הדברים דמשמע ליה שבכלל הלשון הוא או לא היה בנוסחתו כן בגמרא:\",1,0],[8,384,2,6,\"הסרסור שליח הוא וכו'. נ״ל דממתניתין דכתובות פרק אלמנה ניזונת (כתובות דף צ״ח) אלמנה שהיתה כתובתה מאתים ומכרה שוה מאה במאתים או שוה מאתים במאה נתקבלה כתובתה יש ללמוד כן שהרי הוא דומה לסרסור שנוטל שכר שגם היא נהנית במכירה זו שגובה כתובתה ואמרינן בההוא פירקא דבר שאין לו קצבה הכל לבעל המעות וכ״כ רשב״ם והרא״ש ז״ל וכתב המרדכי שהסרסור ש״ש אפילו בשעת הליכה:\",1,0],[8,384,2,6,\"ראובן אומר במאה וכו' נשבע הסרסור שבועת התורה. שכיון שאינו מכחיש את שמעון לומר שלא נמכר אלא שאומר שא\\\"ל במאה ה\\\"ל סרסור מודה במקצת ובזה נתיישבה השגת הראב\\\"ד ז\\\"ל שכתב אין כאן שבועת התורה וכו'.\",2,0],[8,384,2,6,\"ומ\\\"ש ואם כבר נתן נשבע היסת הטעם משום דהו\\\"ל כופר בכל והוא הדין אפילו לא נתנה לו אלא שא\\\"ל הילך:\",3,0],[8,384,2,6,\"ואם ידע הלוקח שחפץ זה של ראובן וכו'. כלומר דעד השתא עסקינן בדין שבין המוכר והסרסור והשתא מיירינן בדין של לוקח עם המוכר והסרסור וטעם הדין דכיון שידע הלוקח שחפץ זה של ראובן דומה לדין שכתב למעלה שאם הודיע שהוא שליח אם נמצא שעבר על דעת המשלח בטל המקח ומ\\\"ש הראב\\\"ד שיאמר לו קנוניא אתם עושים עלי וכי בשביל טענה זו החלושה נפסיד למוכר שאומר שמעולם לא הסכים למכור באותו הסך והחפץ הוא שלו אלא ודאי חייב להחזיר לו החפץ אע\\\"פ שהסרסור מכחישו ואם מפני טענת קנוניא יחרים על מי שנתן רשות כלומר לפי שלמעלה תפס שני חלוקות אם נתן כבר הסרסור הנ' למוכר או שלא נתן כנגד אם לא נתן הדמים אבל טוען שנתן לו רשות אמר על מי שנתן לו רשות וכנגד הב' שנתן לו הדמים אמר או שרצה בנ' כלומר שקבל הנ' ונתרצה וחזר בו אח\\\"כ וא\\\"ת ולמה צריך שידע שחפץ זה של ראובן כשידע שאינו של הסרסור סגי וכמו שכתבתי י\\\"ל שאם לא ידע למי הוא לא יחזיר לו שיאמר לו האיש שאתה אומר שהוא בעל החפץ אינו זה והלה ישמע ולא יגיד שהוא לא נתרצה בחמשים אחר שאינו בעל החפץ א\\\"נ שמציאות הדבר הוא אומר שידע שחפץ זה של פלוני ונתנו לזה הסרסור:\",4,0],[8,384,2,7,\"כל סרסור שהודיע ללוקח וכו'. כתב הראב\\\"ד כשהפקידו לו לא א\\\"ל כלום וכו'. כוונת הראב\\\"ד במ\\\"ש שהפקידו אצלו היינו לומר שהפקידו אצלו למכרו דאל\\\"כ מי נתן לו רשות לנפקד למכור הפקדון אבל מ\\\"ש ואם א\\\"ל מכור לי חפץ זה בכמה שתמצא וכו' קשה אם היה החפץ שוה ק' והלך ומכרו בנ' וכי יעלה על הדעת שבשביל שאמר לו מכור בכמה שתמצא שהמכר יהיה קיים ודאי לא נתכוון לומר לו בכמה שתמצא אלא מעט פחות מעט יתר אבל דברי רבינו ברורים שהנותן חפץ לסרסור למכור סתם או הוא נותן לו ואחר כך בא הסרסור ואומר לבד זה מצאתי ופסק רבינו שהמוכר יכול לבטל המקח כיון שלא נתן לו רשות למכור בכך וכך ונ\\\"ל לדעת רבינו שאע\\\"פ שהמוכר יכול לבטלו אין הלוקח יכול לבטלו אם המוכר רצה לקיים המקח מאחר שקנה הלוקח באחד מדרכי הקניין אינו יכול לחזור בו:\",1,0],[8,384,2,7,\"וכן סרסור וכו'. האי וכן ט״ס הוא וצריך למחוק וכן ולכתוב במקומו כל וכן הוא בספרים המדוייקים והדין הוא משנה בבתרא פרק הספינה (בבא בתרא דף פ״ז) נשברה החבית נשברה לסרסור ומפרש רבינו כתוספות שכתבו שהיה סרסור שניהם ומדד להם כדרך כל סרסורין שמודדין בשכר שנותנין להם ונשברה החבית ע״י מדידה נשברה לסרסור וכגון שלא היה מחמת אונס אלא ע״י שלא נזהר יפה במדידה:\",2,0],[8,384,2,8,\"הלוקח כלים מבית האומן וכו'. ברייתא במציעא פרק האומנין (בבא מציעא דף פ״א) כתבה הרי״ף בפרק השואל הלוקח כלים מבית האומן לשגרן לבית חמיו ופירוש סבלונות לארוסתו וא״ל אם מקבלין אותן ממני אני נותן לך דמיהן ואם לאו אני נותן לך לפי טובת הנאה שבהם כלומר שיחזיקו לי טובה שפקדתים בסבלונות ונאנסו בהליכה חייב בחזרה פטור מפני שהוא כנושא שכר ופירש״י ונאנסו בהליכה חייב דהואיל וקצץ דמיהם ומשכם לשם לקיחה הרי הם כלקוחין [ודין זה] דומה לדין שכתב רבינו ספ״ד מה' מכירה נוטל כלי מן האומן ע״מ לבקרו דבקץ דמיו עסקינן ואין מדברי רבינו הכרע שהוא כתב הברייתא כלשונה אבל נראים דברי רש״י ולשון הברייתא מסייעתו דבקץ דמים עסקינן שא״ל אתן לך דמיהם משמע שכבר היו קצובין והגהות כתבו שגם ר״י הסכים לדברי רש״י. ודע דפטור דקתני היינו מאונסין אבל לעולם חייב כנושא שכר וכך מסיימת הברייתא בנוסחאותינו כמ״ש בחזרה פטור מפני שהוא כנושא שכר כלומר ולא כשואל ופירש״י שנשיאות שכרו הוא שנהנה שנתפאר בהם וכן מוכיח שם בגמרא דאמר אמימר התם אמילתא אחריתי פטור משואל וחייב בש״ש ומייתי הך ברייתא לסיוע והכי דייק לישנא דרבינו שכתב ואם נאנסו בחזרה פטור דמשמע דפיטורא לא הוי אלא מאונסין:\",1,0],[8,384,2,8,\"נטלן על מנת למכרן וכו'. גם זה שם ובהלכות מעשה ואתא לקמיה דר\\\"נ וחייביה ונתן טעם משום דאילו אשכח לזבוני בחזרתו מי לא זבנה:\",2,0],[8,384,2,9,\"כל שליח וכו' ואם היה האונס במקום שאפשר להביא עליו עדים וכו'. ס״פ האומנים (בבא מציעא דף פ״ב פ״ג) הביאו מעשים משומרים ושלוחים ופסקו כאיסי דתניא איסי בן יהודה אומר אין רואה שבועת ה' תהיה בין שניהם הא יש רואה יביא ראיה ויפטר ופי' ר״ח דחידושיה דאיסי היינו דכי יש רואה ליכא שבועה אלא או יביא ראיה ויפטר או ישלם והכריע הרי״ף כדבריו וכ״כ הרא״ש והר״ן וזה דעת רבינו:\",1,0],[8,384,2,9,\"מעשה באחד שאמר לשלוחו וכו'. מעשה שם ואמרו כמאן כאיסי ומכאן למדו המפרשים דלאו דוקא בשבועת השומרים אמרה איסי אלא אפילו בעלמא בין בשליחות או שותפות ויש לדקדק במ\\\"ש רבינו ממעות שהיו לי בידו משמע הא לאו הכי אלא שא\\\"ל קנה ואני אשלם לך יכול לומר לו איני רוצה המקח ואין לו עליו אלא תרעומת וצ\\\"ע.\",2,0],[8,384,2,9,\"ומ\\\"ש וקול יש לו פירוש אימת החמיצו ושל מי היו ואצל מי היו שמא שלך היו או קנית חומץ בדמים פחותים ולא החמיצו אצלך:\",3,0],[8,384,3,1,\"מי שהיתה לו קרקע וכו' או שהיו לו מטלטלין וכו'. בבבא קמא פרק מרובה (בבא קמא דף ע') דכתבינן אורכתא אמטלטלין דלא כפריה ללישנא בתרא שפסק כמותו הרי״ף ז״ל וכתב פקדון לאפוקי מלוה וכמ״ש בפירוש בפרק זה:\",1,0],[8,384,3,1,\"וצריך לקנות מידו וכו'. נ\\\"ל דמדאיפליגו בגמרא אי שליחא שוייה או שותפא אלמא דכשהקנה לו עסקינן דאי לא מהי תיתי דשותפא שוייה ועוד ממה שאמרו בגמרא וכתבו רבינו בפרק זה שאם הקנה לו שליש או רביע דן על הכל הא לאו הכי אינו דן אלמא קניין בעי:\",2,0],[8,384,3,1,\"ואם לא כתב לו. כלומר שלא כתב לו דון וזכה והוצא לעצמך וכן אמרו במרובה אמרי נהרדעי [כל] אורכתא דלא כתיב בה דון וזכה ואפיק לנפשך לית בה מששא מאי טעמא משום דא\\\"ל האיך לאו בעל דברים דידי את:\",3,0],[8,384,3,1,\"ואף על פי שכתב לו כן וכו'. שם אמר אמימר אם תפס לא מפקינן מיניה כלומר אם תפס שליח ממון שהוציא ועכבו לעצמו רב אשי אמר כיון דכתב ליה כל דמתענית מן דינא קבילית עלי שליח שווייה ואיכא [מאן] דאמר שותפא שווייה למאי נפקא מינה למיתפס פלגא וכתב הרי\\\"ף דרב יהודאי גאון פסק דשליח שוייה ונ\\\"ל הטעם דכרב אשי קיימא לן דבתראה הוא ולא שבקינן לישנא דאמר סתמא דגמרא אליבא דרב אשי משום דאיכא דאמרי ובנוסחאות שלנו כתוב בגמרא והלכתא שליח שווייה ונראה מכאן שאם לא כתב כל מאי דמתענית מן דינא וכו' דלא שווייה שליח ושותפא שווייה:\",4,0],[8,384,3,1,\"וכל ההוצאות וכו'. מהא דרב אשי שכתבתי בסמוך דאמר דכתב ליה כל דמתענית מן דינא עלי הדר וכתב בעל העיטור בשם הגאונים שאף על פי שלא כתב כל מאי דמתענית וכו' אינו יכול לומר נתבע לאו בעל דברים דידי את שאין זה אלא בין המורשה והמרשה כלומר שהוא לתקנת המרשה שלא יוכל המורשה להחזיק בממון כמ\\\"ש בסמוך:\",5,0],[8,384,3,2,\"הקנה וכו'. שם אמר אביי ואי כתב ביה למחצה לשליש ולרביע מגו דמשתעי דינא אפלגא משתעי דינא אכולה ופירש\\\"י אי כתב בה למחצה ולשליש דון וזכי לנפשך והמותר שלי עכ\\\"ל כלומר דאע\\\"ג דלשאר הממון לא כתב דון וזכה לנפשך לא מצי למימר ליה לאו בעל דברים דידי את:\",1,0],[8,384,3,2,\"כתב הראב\\\"ד דוקא שליש או רביע עד המאה ע\\\"כ לשונו:\",2,0],[8,384,3,3,\"אחד מן האחין וכו'. בכתובות פרק מי שהיה נשוי (כתובות דף צ״ד) שאין בעל דין יכול לומר לאחד מהשותפין שבא לדון עמו אם חבירו במקום אחר לאו בעל דברים דידי את אבל אם אינו במקום אחר יכול לומר לו כן ולמד רבינו שכיון שאינו יכול לומר לאו בעל דברים דידי את אפילו נתחייב שותף זה יש על חבירו לקבל דינו דהא בהא תליא.\",1,0],[8,384,3,3,\"ומ\\\"ש לפיכך אם היה במדינה אחרת. שם מבואר זה החילוק.\",2,0],[8,384,3,3,\"ומ\\\"ש לפיכך יש לנתבע לעכב וכו'. דהא בהא תליא כמ\\\"ש ובח\\\"מ כתב [הטור] שהרא\\\"ש חולק עם רבינו והוא סובר כרבינו ומשמע התם שאם היה חייב שבועה ונשבע לאחד מן השותפין שבועה לאחד שבועה למאה:\",3,0],[8,384,3,4,\"הבעל בנכסי אשתו וכו'. גיטין סוף פרק השולח (גיטין דף מ״ח ע״ב) מימרא דאביי:\",1,0],[8,384,3,5,\"מי שהיה לו ביד חבירו פקדון וכו'. בב״ק פ' הגוזל עצים (בבא קמא דף ק״ד) איתמר שליח שעשאו בעדים רב חסדא אמר הוי שליח רבה אמר לא הוי שליח ופסק הרי״ף כרב חסדא משום דקיימי התם ר״י ור״א כוותיה וכתב דה״מ דהוי שליח לענין שאינו חייב באחריותן אבל אם לא רצה ליתנם לו אין כופין אותו עד שיביא הרשאה דדון וזכי לנפשך וכתב רבינו עד שיבא בהרשאה על הפקדון כלומר דאילו במלוה לא מהני הרשאה:\",1,0],[8,384,3,5,\"וכל הבא בהרשאה וכו'. בפרק שבועת העדות (שבועות דף ל״א) מימרא דרב וכתבו התוספות דהני מילי כשעושה בשביל שהוא אלם ובעל טענות שמתעבר על ריב לא לו והראב״ד ז״ל כתב דוקא כשהוא עם בעל דינו וכו' ולי תרוייהו איתנהו דכללא דמילתא כל שהבעל דין אינו יכול להוציא מיד הלוה או מפני אלמותו או מפני רחוק המקום מצוה עביד להציל עשוק מיד עושקו אבל אם הלוה אינו אלם יותר מבעל דינו ושניהם בעיר אחת ואפילו הלוה בעיר אחרת ואית למלוה דרכא עליה אז לא טוב עשה:\",2,0],[8,384,3,6,\"התובע חבירו בדין וכו'. בבבא קמא פרק מרובה (בבא קמא דף ע') לישנא בתרא דנהרדעי לא כתבינן אורכתא אמטלטלי דכפריה משום דמיחזי כשיקרא אבל לא כפריה כתבינן ורבינו חננאל כתב דלא ידע טעמא על מה נהגו לכתוב הרשאה אמטלטלין דכפריה ורבינו תם האריך ליתן טעם למנהג ודבריו תלויין בסוגיית הגמרא ואין כאן מקום להאריך:\",1,0],[8,384,3,6,\"וכן מי שנתחייב לו חבירו שבועה וכו'. זה פשוט בטעמו:\",2,0],[8,384,3,7,\"מי שהיה לו מעות פקדון וכו'. במציעא פרק הזהב (בבא מציעא דף מ״ה מ״ו) ובקמא פרק הגוזל עצים (בבא קמא דף ק״ד ע״ב) דאין מטבע נקנה אלא אגב קרקע כי הא דרב פפא הוה מסיק תריסר אלפי זוזי בי חוזאי אקנינהו ניהליה לרב שמואל בר אבא אגב אסיפא דביתיה ומפרש רבינו שאותם דמים בפקדון היו אצלם דאם תמצא לומר שהיו מלוה כיון דאינם בעין א״א להקנותם וכמ״ש בסמוך:\",1,0],[8,384,3,7,\"היתה לו מלוה ביד אחר וכו'. הכי משמע בבתרא פרק מי שמת (בבא בתרא דף קמ״ח) דאמרינן התם אמר רבא אמר ר״נ שכ״מ שאמר הלואתי לפלוני כלומר מלוה על פה שחייב לי פלוני הלואתו לפלוני ואע״ג דליתא בבריא ולא משכח התם שיקנה בריא מלוה אלא במעמד שלשתן וכבר נתבאר בפ״ו מהלכות מכירה דין קניית השטר שהוא בכתיבה ומסירה וא״כ מן הדין אין הרשאה במלוה אלא מתקנת הגאונים אבל בתוספות פרק מרובה הוכיחו קצת במנהג שכותבין הרשאה אף בהלואה. ולא ידעתי מה חידש הראב״ד שכתב ואפילו היה החוב בשטר וכו' א״א אם לא מסר לו שטר החוב, שהרי כתב או בהקניית שטר חוב:\",2,0],[8,384,3,7,\"ומ\\\"ש רבינו ודברים אלו קלים הם עד מאד וכו'. נראה דלא קאי אלא אמאי דתקון שאם לא היה למקנה קרקע מקנהו ארבע אמות מחלקו שיש לו בא\\\"י אבל מה שתקנו שכותבין הרשאה אף על המלוה תקנה טובה היא שהרי מ\\\"ש שזה מי יאמר שיש לו חלק בא\\\"י וכו' אינו ענין לתקנה קמייתא.\",3,0],[8,384,3,7,\"ומ\\\"ש שזה מי יאמר שיש לו חלק בא\\\"י כלומר שמא הוא מזרע גרים או משוחררים שאין להם חלק בארץ.\",4,0],[8,384,3,7,\"ומ\\\"ש וכן הורו שאם היתה לו מלוה אצל חבירו בין בשטר וכו' מפני שהוא כפירת שעבוד קרקעות כלומר שמשעה שנטל קניין או כתב שט\\\"ח עליו נשתעבדו קרקעותיו למלוה ועל תביעת קרקע אע\\\"ג דכפריה כותבין הרשאה דכיון דקרקע אינה נגזלת כפריה כלא כפריה היא.\",5,0],[8,384,3,7,\"ומ\\\"ש שאם הרשהו ליטול מעות שיש לו ביד חבירו וכו' ואין לו קרקע וכו' היינו לומר שאם יש לו מעות פקדון ביד חבירו וצריך להקנותם לו אגב קרקע אם אין לו קרקע מקנהו אגב ד' אמות שבא\\\"י.\",6,0],[8,384,3,7,\"ומ\\\"ש או לתבוע ממנו הלואה ולא היה למקנה קרקע מקנהו ארבע אמות מחלקו שבא\\\"י באמת איני יודע מה צורך להקנאת ארבע אמות להרשאת גביית מלוה שהרי אינה נקנית אגב קרקע והרשאה אינה צריכה אלא קניין סודר ושמא מתוך שהקילו מצד שתועיל הרשאה למלוה החמירו מצד להצריכה קניין אגב ד\\\"א קרקע ודוחק:\",7,0],[8,384,3,8,\"מי שהרשה לאחד וכו'. כך כתב הרי\\\"ף בקמא פרק מרובה דכיון דקיימא לן דשליח הוי אי בעי לבטולי שליחותיה ואורוכי איניש אחרינא אית ליה רשותא למעבד הכי:\",1,0],[8,384,3,8,\"ואין למורשה לכתוב הרשאה וכו'. פרק הגוזל קמא כתב הרי\\\"ף וגברא דמורכין ליה לית ליה רשותא לאורוכי איניש אחרינא דיכול למימר אין רצוני שיהא פקדוני ביד אחר:\",2,0],[8,384,3,8,\"לפיכך אם התנה וכו'. זה פשוט:\",3,0],[8,384,3,9,\"הבא בהרשאה וכו'. נימוקי יוסף בפרק מרובה כתב שכך הורו הגאונים ונ\\\"ל הטעם שכיון שפסקנו דשליח שווייה דינו כדין השליח ואומר לו לתקוני שדרתיך ולא לעוותי אם לא התנה בפירוש בין לתקן בין לעוות.\",1,0],[8,384,3,9,\"ומה שכתב לפיכך אם התנה עמו וכו' אפילו מחל לו על הכל הרי זה מחול. פשוט הוא:\",2,0],[8,384,3,11,\"ראובן שבא בהרשאת שמעון וכו'. אין ספק שדעת רבינו דהיכא דכפריה קודם הרשאה לא כתבינן לה אבל אם כשנכתבה ההרשאה לא נודע לנו שהיה כופר אע\\\"פ שכפר אח\\\"כ לא בטלה ההרשאה מפני זה שהרי בעת כתיבתה כדין נכתבה ואף ע\\\"פ שהראב\\\"ד כתב בדרך אפשר כן הוא האמת וטעם הדין נראה מפני שלוי יערים ויאמר יבא שמעון וישבע והדין עמו כדאמרינן בהכותב תשתבע במאתין אפשר דמכספיא ומודיא ולוי אומר כן לפי שמשער בדעתו שלא יצא שמעון ממקומו ויבא כאן להשבע וללכת עם לוי בדינא ודיינא להוציא ממנו הממון לכך נתחכמו עליו חכמים ואמרו נוציא הממון מידו ליד ב\\\"ד ואז יהיה הרשות ביד שמעון לבא ולהשבע וליטול מיד ממונו ואולי מצד זה יתפשר לוי עם השליח ולא יצטרך שמעון לבא כאן:\",1,0],[8,384,4,1,\"כשירצו השותפין להשתתף כו' עד הרי אלו לאמצע. כל זה מפורש בדברי רבינו בטעמו.\",1,0],[8,384,4,1,\"ומ\\\"ש ויטילו אותם לתוך כיס אחד. נ\\\"ל דלאו דוקא דה\\\"ה אם כל אחד הגביה כיס חבירו שזכה בה ונתקיים השותפות וכן כתוב בח\\\"מ ומכאן ששנים שהתנו ביניהם שכל מה שירויחו אפילו ממציאות יהיה לאמצע לאו כלום הוא לדעת רבינו אם לא נשבעו על זה שאז חייב לקיים שבועתו כמבואר בדבריו פרק כ\\\"ב מה' מכירה ופ\\\"ו מהלכות ערכין ושלא כעיטור והגהות שכתבו דמהני אפילו בלא שבועה וכדבריהם הוא דעת הראב\\\"ד שכתב ורבותי הורו שאדם יכול להקנות את עצמו לחבירו בקניין כדין עבדים וכשם שמצינו באומרת יקדשו ידי לעושיהן עכ\\\"ל כוונתו לומר שכשם שהעבד משתעבד לעשות מלאכות שלא באו לעולם כיון שגופו הוא בעולם כך השותפין משתעבדים זה לזה וי\\\"ל דלא דמי משום דהתם משתעבד גופו בהדיא אבל כאן אין שניהם משתעבדים זה לזה בפירוש והו\\\"ל כמוכרים זה לזה דשלב\\\"ל דלא קנו ומה שרצה להשוותו ליקדשו ידי אין הנדון דומה לראיה דהתם מתורת קיום הנדר נגעו בה וכמ\\\"ש רבינו בהלכות מכירה והלכות ערכין פ\\\"ו. וכתב מהרי\\\"ק בשורש קפ\\\"ב שמודה רבינו היכא דכל בעלי אומנות אחד התנו אהדדי אפילו בלא קניין אין יכולים לחזור בהם.\",2,0],[8,384,4,1,\"ומ\\\"ש וכן אם עירבו פירותיהם. קשה דמה קנייה יש בעירוב הפירות דנהי שאותו שהם ברשותו קנה אבל האחר במה קנה ונ\\\"ל דהכי פירושה אם עירבו פירותיהם והגביהם כל אחד מהם דומיא דמעות. כתב מהרי\\\"ק בשורש כ' דאפילו לדברי רבינו שהצריך נתינת מעות לכיס דוקא בתחלת השותפות בעינן קניין אבל היכא שכבר היו שותפים מקודם מודה הוא דכל תנאיהם קיימים בלא קניין וכ\\\"ש בהיות התנאים שוים לשניהם דבההיא הנאה דסמכי אהדדי וכו' עכ\\\"ל ואין נ\\\"ל שרבינו יסבור כן:\",3,0],[8,384,4,3,\"השותפין שהטילו לכיס זה מנה וזה מאתים וכו'. כתובות פרק מי שהיה נשוי (כתובות דף צ״ג) אמר שמואל שנים שהטילו לכיס זה מנה וזה מאתים [והותירו או פיחתו] השכר לאמצע אמר רבה מסתברא מילתיה דשמואל [בשלקחו] שור לחרישה ועומד לחרישה אבל [לקחו] שור לחרישה ועומד לטביחה פירוש כגון שנמלכו עליו להעמידו לטביחה לחלוק באיבריו ואח״כ נזדמן להם ומכרוהו חי זה נוטל לפי מעותיו וזה נוטל לפי מעותיו ורב המנונא אמר אפילו [לקחו] שור לחרישה ועומד לטביחה השכר לאמצע פירוש הואיל וכשהוא חי מכרוהו ועדיין לא חלקו שכיון שלא חלקו עדיין השותפות קיימת ולפיכך השכר לאמצע ופסק הרי״ף כרב המנונא משום דאותביה לרבה התם מברייתא דתניא השכר לאמצע ואע״ג דשני לא סמכינן אשינויא. וכתב הר״ן דלרב המנונא לאו דוקא לקחו מתחלה לחרישה אלא אפילו לקחו לטביחה ועומד לטביחה ונמלכו ומכרוהו חי השכר לאמצע אלא דלישנא דרבא נקט וראיה לדבר מדאותבינן עליה דשמואל אליבא דכולי עלמא מדתנן התם וכן שלשה שהטילו לכיס הותירו או פיחתו כך הם חולקים כלומר כדקתני בבבא דלעיל מינה דחולקין לפי מעות מאי לאו פיחתו פיחתו ממש הותירו הותירו ממש א״ר נחמן אמר רבה בר אבוה לא הותירו זוזי חדתי פיחתו אסתירי צינאתא כלומר המטבע בעין והיה ישן וחדשוהו או שהיה חדש ופסלוהו אז חולקין לפי המעות דכל חד מאי דיהיב שקיל אבל אם נשאו ונתנו בהם והוסיפו על החשבון או פיחתו מהחשבון חולקין לאמצע ואם איתא דאפילו רב המנונא מודה דבדבר הראוי להתחלק חולקין לפי מעות מאי דוחקייהו לשנויי הכי ולא אוקמה כגון שלקחו פירות או סחורה שהם ראויים ליחלק אלא ודאי משמע דאפילו בכה״ג השכר לאמצע וטעמא מפורש בירושלמי עכ״ל וכך הם דברי רבינו שכתב אפילו לקחו שור לטביחה ונראה עוד מדברי הרי״ף שאפילו לקחוהו מתחלה לחרישה אם אח״כ טבחו חולקין לפי מעות שנתנו ורב המנונא אמר אפילו לקחו שור לחרישה ועומד לטביחה השכר לאמצע הואיל וכשהוא חי מכרוהו ועדיין לא חלקו שכיון שלא חלקו השותפות קיימת ולפיכך השכר לאמצע אלמא דטעמא משום שמכרוהו חי הא אם טבחוהו חולקים לפי מעות וכך נראה ג״כ מדברי רבינו שכתב אם מכרוהו חי ואיני מבין דברי הר״ן שכתב אבל טבחוהו ד״ה השכר לאמצע מכמה פנים אחד שנראה מהרי״ף היפך כמ״ש ועוד היאך אפשר לומר שאם טבחוהו ד״ה לאמצע וכשמכרוהו יש חולק לומר שחולקין לפי מעות איפכא מסתברא לכך אני אומר דט״ס הוא גם בעיטור כתב כדעת הרי״ף כמ״ש:\",1,0],[8,384,4,3,\"כתב הראב\\\"ד ז\\\"ל על דברי רבינו א\\\"א לא נתחוורו דברים הללו וכו'. כבר כתבתי שדברי רבינו כדברי הרי\\\"ף:\",2,0],[8,384,4,3,\"במה דברים אמורים כשנשאו וכו'. כבר כתוב בסמוך:\",3,0],[8,384,4,3,\"במה דברים אמורים בסתם וכו'. זה פשוט דכל דבר שבממון תנאו קיים:\",4,0],[8,384,4,4,\"השותפין שהתנו ביניהם וכו'. במציעא פרק המקבל (בבא מציעא דף ק״ה) אמר רבא הני בי תרי דעבוד עסקא בהדי הדדי ורווח וא״ל חד לחבריה תא נפלוג אי א״ל אידך נירווח טפי דינא הוא דמעכב ומסיים התם דאין שום אחד מהם יכול ליטול חלקו מן הקרן ולא מן השכר וכמו שאכתוב בסמוך ומפרש רבינו דה״ה כשעשו השותפות לזמן קצוב וסובר עוד דהוא הדין אם נשתתפו במעותיהן:\",1,0],[8,384,4,4,\"נשתתפו סתם וכו'. בפרק איזהו נשך (בבא מציעא דף ס״ט) וכתבה הרי״ף בפרק המקבל הנהו תרי כותאי דעבוד עסקא בהדי הדדי [אזל חד מינייהו] פליג זוזי בלא דעתא דחבריה וא״ל ר״פ מאי נפקא לך מינה ומעובדא דאיסור ורב ספרא שבפרק אלו מציאות וכתבה הרי״ף גם בהמקבל שחלק רב ספרא שלא מדעת איסור וכתב כדברי רבינו ובפרק שאחר זה משמע דיכול הוא לחלוק ואין חבירו יכול לעכב עליו והיינו בשנשתתפו סתם.\",2,0],[8,384,4,4,\"ומ\\\"ש ואם לא היתה באותה סחורה וכו'. פשוט הוא:\",3,0],[8,384,4,4,\"היה זמן ידוע למכירת אותה סחורה וכו'. גיטין ס״פ כל הגט (גיטין דף ל״א ע״ב) תניא רבי יהודה אומר בשלשה פרקים מוכרים את התבואה וכו' למאי הלכתא אמר רבא ואיתימא רב פפא לשותפין ופר״ח ור״ת דעד זה הזמן יכולים לעכב ואז ימכרו ויחלוקו וכתב רבינו ירוחם שנראה שאם מכר בלא רשות באותו זמן שאין ראוי לימכר אותה סחורה ונתייקרה חייב לשלם דה״ל פשיעה וכ״כ העיטור:\",4,0],[8,384,4,4,\"היה עליהם חוב לאחר וכו' ואם הם אחראים וכו'. מההיא דהמקבל שכתבתי לעיל דאמר רבא הנהו בי תרי דעבוד עסקא בהדי הדדי ורווח וא\\\"ל חד לחבריה תא ניפלוג אי א\\\"ל אידך נרווח טפי דינא הוא דמעכב ואי א\\\"ל הב לי פלגי דרווחא אמר ליה רווחא לקרנא משתעבד ואי א\\\"ל הב לי פלגי רווחאי ופלגי קרנאי א\\\"ל עסקא להדדי משתעבד כלומר ואם נחלוק שמא אפסיד בסחורה שאקנה וחלקך ישתכר ואנו יחד קבלנו ונשתעבדו החלקים זה לזה ואי א\\\"ל ניפלוג רווחא [ונפלוג קרנא] ואי מטי לך דרינא בהדך א\\\"ל לא מזלא דבי תרי עדיף:\",5,0],[8,384,4,4,\"כתב מהרי\\\"ק בשורש ק\\\"כ שמ\\\"ש רבינו אם אינם אחראים זה לזה חולקין צריך לפרש כגון שפירשו בהדיא שאינן אחראין זה לזה ולא יתחייב האחד בחלק חבירו שאם לא כן יקשה דמכל מקום הם ערבים זה לזה כמ\\\"ש רבינו בפרק כ\\\"ה מהלכות מלוה וא\\\"כ היאך יכול האחד לכוף חבירו לחלוק הלא יאמר לו הלה אין רצוני לחלוק פן תפסיד נכסיך או תבריחם ונמצא כל החוב מוטל עלי לפרוע:\",6,0],[8,384,4,4,\"אמר לו חבירו נחלוק וכו'. כבר נתבאר בסמוך:\",7,0],[8,384,4,5,\"הנותן מעות לחבירו לילך למדינה וכו':\",1,0],[8,384,5,1,\"המשתתף עם חבירו בסתם וכו' ולא יתעסק בסחורה אחרת. ברייתא הביאה הרי״ף אגב גררא בפרק איזהו נשך (בבא מציעא דף ס״ט) גמרא אין מושיבין חנווני למחצית שכר:\",1,0],[8,384,5,1,\"ולא ימכור בהקפה וכו'. רבינו ירוחם כתב בשם הגאונים שאם יש קצת בני אדם מוכרים בהקפה וקצתם שלא בהקפה אין לו למכור על הספק שלא מדעת חבירו דכל אשראי ספק הוא וזהו דעת רבינו שכתב אלא דבר שדרכו לימכר תמיד בהקפה וכתב בעיטור דמדאמרינן בההיא דפרק כל הגט למאי הלכתא לשותפי ש\\\"מ שותף אינו יכול למכור בלא דעת חבירו אלא הכל לפי מנהג מוכרי העיר ואם שינה חייב והיכא דזבין חד מינייהו באשראי בלא רשותא דחבריה איכא פלוגתא ביני רבוואתא ומסתברא כיון דאורחא דתגרי בהכי פטור והכי נמי אי אזיל ומשדר עיסקא בימא באורחא דתגרי ופסיד פטור אבל אי אתרי ביה אף על גב דעבד בממונא דחבריה כנטירותא דידיה חייב והכי שדרו במתיבתא דמר רב כהן צדק עכ\\\"ל:\",2,0],[8,384,5,1,\"עבר ועשה וכו'. הטעם שכיון שא\\\"ל ונתרצה הרי מחל לו ומחילה אינה צריכה קניין כמפורש בדברי רבינו פרק חמישי מהלכות מכירה:\",3,0],[8,384,5,2,\"אחד מן השותפין שעבר ומכר. יתבאר בסמוך:\",1,0],[8,384,5,2,\"לפיכך הנותן מעות וכו'. כך העלה הרי\\\"ף בהגוזל קמא שאם לסחורה נתן לו בתורת שותפות אם פחתו פחתו לשליח מפני שהוא משנה ואם הותירו הותירו לאמצע:\",2,0],[8,384,5,2,\"וכן אם הלך ונשתתף וכו'. שזה הדין דומה ממש לדין שנזכר בסמוך שהרי שותפו לא נתן מעותיו שישתף עמו אחר:\",3,0],[8,384,5,2,\"אבל אם נשתתף עם אחר וכו'. קשה שלא ימנע או הם שותפים בכל ממון שבידם או לא אם הם שותפין בכל היאך יש לזה ממון שאינו של השותפות ואם אינם שותפים בכל פשיטא שהריוח וההפסד הוא לעצמו. ונ\\\"ל דבשלא נשתתפו בכל מעות שבידם עסקינן ואפ\\\"ה ה\\\"א דכיון דאין לו להתעסק בסחורה אחרת מפני שמתרשל בעסק השותפות כשנתעסק בסחורה אחרת הריוח לאמצע קמ\\\"ל:\",4,0],[8,384,5,3,\"הנותן מעות לחבירו ליקח וכו'. תוספתא כתבה הרא\\\"ש פרק איזהו נשך פירוש רשאי ליקח לעצמו מאותו המין ממעות אחרים שאינם דמי השותפין ולא חיישינן שמתוך שקנה לעצמו מאותו המין יבא הפסד למה שקנה בדמי השותפות והוא שלא ימכור שניהם כאחד שמא מה שקנה לעצמו אינו משובח כמו של השותפות ונמצא חבירו נפסד בכך:\",1,0],[8,384,5,3,\"וכתב הראב\\\"ד על דברי רבינו זו התוספתא אינה מחוורת ואין למדין ממנה עכ\\\"ל. ואיני יודע למה דחה תוספתא זו שאולי קצתם ימכרו ביוקר וקצתם בזול ויחשוב אותם שביוקר לעצמו ושבזול לחבירו לכך אמרו חכמים שמתחלה יברור חלקו:\",2,0],[8,384,5,3,\"ולא יקח לעצמו חטים וכו'. ג\\\"ז תוספתא כתבה שם הרא\\\"ש. ולא יקח וכו' אנותן מעות לחבירו ליקח בהם פירות למחצית שכר דנקט ברישא קאי וקאמר דממעות השותפות לא יקח לעצמו חטים ולחבירו שעורים.\",3,0],[8,384,5,3,\"ופירוש כדי שיהיו מעות שניהם שוים בחבלה כלומר שאם יהיה הפסד שלא יפסיד האחד יותר מחבירו. אבל קשה אמאי נקט חבלה ולא נקט הריוח ואפשר לפרשו מענין יחד כלומר כדי שיהיה ריוח והפסד שניהם שוה ולא ישתכר בשלו יותר מבשל חבירו. וי\\\"ס דגרסי בקבלה והיינו לומר שיהא קבלה בריוח והפסד שוה. וגירסת רבינו ירוחם כדי שיהיו שניהם שוים בחבילה וה\\\"פ שכשישאו שניהם משא להביא אל העיר אם הם שני מינין אולי אחד מהם יהיה כבד יותר מחבירו ואם תחשוב לפי מדה יגיע לזה חצי השכר ואם לפי כובד המשא יגיעוהו שני שלישים ואולי המתעסק לא ידקדק בזה ואם השעורים שלו נמצאו גזל לבעל המעות:\",4,0],[8,384,5,4,\"אחד מן השותפין שאמר נוליך הסחורה למקום פלוני וכו':\",1,0],[8,384,5,5,\"אחד מן השותפים שבא וכו'. נראה שלמד כן מדתניא בסוף פרק כל הגט (גיטין דף ל״א ע״ב) רבי יהודה אומר מוכרים התבואה וכו' למאי נפקא מינה לשותפים:\",1,0],[8,384,5,6,\"שותפין ששמו פירותיהם ונשתתפו וכו':\",1,0],[8,384,5,7,\"שותפין שמחלו להם וכו'. תוספתא כתבה הרי\\\"ף פרק הגוזל בתרא וכתב הרא\\\"ש דרישא מיירי שביקש אחד מהם מהמוכס שימחול לו ומחל לו הוא לאמצע כאילו הוא שלוחם לבקש בשביל כולם ואם מעצמו בלא פיוס אמר אני מוחל בשביל פלוני הוא שלו לבדו:\",1,0],[8,384,5,7,\"היו באים בדרך וכו'. בהגוזל בתרא (דף קי\\\"ו ע\\\"ב) תנו רבנן שיירא שהיתה מהלכת במדבר ועמד עליה גייס וטרפה ועמד אחד והציל הציל לאמצע ואם אמר לעצמי אני מציל הציל לעצמו ופרכינן ה\\\"ד אי דיכולין להציל אפילו אמר נמי ולא כלום הוא ואי דאין יכולין להציל אפילו לא אמר נמי אמר רמי בר חמא הכא בשותפות עסקינן כגון זה שותף חולק שלא לדעת חבירו אמר פליג לא אמר לא פליג:\",2,0],[8,384,5,8,\"דבר הידוע לשני שותפין וכו'. בריש בתרא (דף ד') גבי הא דתנן השותפין שבנו את הכותל לאמצע לפיכך אם נפל הכותל המקום והאבנים של שניהם פשיטא לא צריכא דנפל לרשותא דחד מינייהו אי נמי דפנינהו חד לרשותיה מהו דתימא ליהוי אידך המע\\\"ה קמשמע לן כתב הרי\\\"ף ז\\\"ל ש\\\"מ מהא דמילתא דידיעא לתרי שותפי אף ע\\\"ג דאיתא השתא ברשותא דחד מינייהו לא נפיק מחזקה דאידך מ\\\"ט משום דשותפין לא קפדי אהדדי הילכך לית להו חזקה חד אחבריה אלא בראיה א\\\"נ לאחר חלוקה וכ\\\"כ הרא\\\"ש וסיים ואין לו ראיה אלא בעדים. ונראה מדברי רבינו שאם חלקו השותפות אע\\\"פ שדבר זה ידוע לשותפות אם הוא ביד אחד מהם הוי אידך המע\\\"ה וטעמא משום דתלינן שנפל לחלקו כשחלקו השותפות וזהו שכתב הרי\\\"ף אי נמי לאחר חלוקה:\",1,0],[8,384,5,9,\"אחד מן השותפין שבא לחלוק וכו'. פרק ב' דמציעא (דף ל\\\"א ע\\\"ב) איסור ורב ספרא עבוד עסקא בהדי הדדי אזל רב ספרא פלג ליה בלא דעתיה דאיסור באפי תרי אתא לקמיה דרבה בר רב הונא א\\\"ל זיל אייתי תלתא דפלגת קמייהו [א\\\"נ תרי מגו תלתא] א\\\"נ תרי סהדי דפלגת באפי תלתא א\\\"ל וכו' כיון דדידי שקלי גילוי מילתא בעלמא בתרי סגיא תדע דתנן אלמנה מוכרת שלא בפני ב\\\"ד וכו' ולאו איתמר עלה וכו' אלמנה אינה צריכה ב\\\"ד של מומחין אבל צריכה ב\\\"ד של הדיוטות הרי מפורש דבשלשה הדיוטות סגי כלומר דלא גמירי ולא סבירי אבל מ\\\"מ בקיאי בשומא בעינן דאי לא היכי ידעי למיפלג ופשיטא דנאמנים בעינן דאי לא היכי מהימנינן להו:\",1,0],[8,384,5,9,\"בד״א בשחלקו פירות וכו'. מציעא פרק איזהו נשך (בבא מציעא דף ס״ט) הני תרי כותאי דעבוד עסקא בהדי הדדי אזל חד מינייהו פלג בלא דעתא דחבריה אתו לקמיה דרב פפא א״ל מאי נפקא לך מינה הא אמר רב נחמן זוזי כמאן דפליגי דמי לשנה זבנו חמרא בהדי הדדי קם אידך פלג ליה בלא דעתא דחבריה אתו לקמיה דרב פפא אמר ליה מאן פלג לך א״ל קא חזינא דבתר דידיה קא אזיל מר אמר רב פפא כי האי גוונא ודאי צריך לאודועי [אמר ליה] זוזי מי שקיל טבי ושביק חסרי [א״ל לא א״ל] חמרא כ״ע ידעי דאיכא דבסים ואיכא דלא בסים:\",2,0],[8,384,5,9,\"בד\\\"א כשהיו המעות כולן מטבע אחד וכו'. שם גופא א\\\"ר נחמן זוזי כמאן דפליגי דמו הני מילי טבי וטבי תקולי ותקולי אבל טבי ותקולי לא כלומר אי שקל טבי שהם קלים ויוצאים בהוצאה ושבק תקולי שהם צורה אחרת שאין יוצאין כל כך בהוצאה א\\\"נ שקל תקולי ושבק טבי שהם יותר קלים לא:\",3,0],[8,384,5,10,\"אסור להשתתף עם עכו\\\"ם וכו'. בסנהדרין פרק ארבע מיתות מימרא דאבוה דשמואל כתבה הרי\\\"ף סוף פ\\\"ט דעבודה זרה ואם עבר ונשתתף עמו יש מתירין לקבל שבועה ממנו ויש אוסרין:\",1,0],[8,384,5,10,\"וכבר ביארנו. בפרק ה' מהלכות מאכלות אסורות:\",2,0],[8,384,5,11,\"אחד מן השותפין וכו'. כן כתב הרא\\\"ש בפרק המקבל גבי ההוא שתלא וכתב שכן דעת הר\\\"מ והביא ראיה מהתוספתא וכתב שם נימוקי יוסף שכן דעת הרמב\\\"ן והרשב\\\"א וכ\\\"כ הריטב\\\"א בשם רבו:\",1,0],[8,384,6,1,\"שנים שהם נושאין ונותנין וכו'. מפורש במציעא פרק איזהו נשך (בבא מציעא דף ס״ט):\",1,0],[8,384,6,2,\"תקנו חכמים שכל הנותן מעות לחבירו. במציעא פרק המקבל (בבא מציעא דף ק״ד ע״ב) אמרי נהרדעי האי עיסקא פלגא מלוה ופלגא פקדון והיינו כשנתן מעות להתעסק סתם ולא התנה וכן פירש רש״י באיזהו נשך (דף ס״ח) במשנת אין מושיבין חנווני למחצית שכר וכן משמע מדברי רבינו בסמוך שכתב ועוד תקנו חכמים שכל הנותן מעות לחבירו וכו' ולא התנו ביניהם שום תנאי שיהיה שכר המתעסק באותו חצי של פקדון שליש ריוח הפקדון וכו' אלמא דע״כ לא תקנו חכמים אלא בשלא התנו ביניהם שום תנאי אבל אם התנו הכל לפי תנאם והוא שלא יהא בתנאי צד איסור רבית כמו שאמר בפרק זה.\",1,0],[8,384,6,2,\"ומ\\\"ש רבינו ואם נגנב או אבד החצי של פקדון אין המתעסק חייב לשלם כתב עליו הראב\\\"ד ז\\\"ל ולמה לא יהיה וכו'. וטעם רבינו מפני שאינו נושא שכר על שמירת הממון אלא על שמתעסק בו והרב רבינו אברהם בר דוד ז\\\"ל מדמה ליה לשוכר שאע\\\"פ שאינו נוטל שכר על שמירתו מ\\\"מ בההיא הנאה דמשכח בהמה לעשות בה מלאכתו חשוב כאילו נוטל שכר על שמירתו הכא נמי בההיא הנאה דמשכח זוזי למעבד בהו עיסקא חשיב כאילו נוטל שכר על שמירתן:\",2,0],[8,384,6,2,\"והיאך יעשו וכו'. משנה במציעא פרק איזהו נשך (בבא מציעא דף ס״ח) אין מושיבין חנווני למחצית שכר ולא יתן לו מעות ליקח בהם פירות למחצית שכר אלא א״כ נותן לו שכרו כפועל בטל ופירשו כפועל בטל של אותה מלאכה דבטיל מינה כלומר אם היה נגר או נפח כמה אדם רוצה ליטול ליבטל ממלאכה כבידה כזו לעשות מלאכה אחרת קלה כך פירש״י והתוס' מפרשים כפועל בטל היינו כיושב בטל לגמרי:\",3,0],[8,384,6,2,\"ואם היה לו עסק אחר וכו' וכן אם א\\\"ל הריוח יהיה לך וכו'. שם (דף ס\\\"ט) אמר רב מותר שליש בשכרך הרי זה מותר ושמואל אמר לא מצא מותר שליש ילך לביתו ריקן אלא אמר שמואל קוצץ לו דינר ואמרינן התם דכי אמר רב מותר שליש בשכרך מותר כגון דאית ליה בהמה לדידיה דאמרי אינשי גביל לתורא גביל לתורי וידוע דהלכה כרב באיסורי וסובר רבינו דכיון דרב מיירי בשיש לו בהמה שמואל נמי מיירי בההוא גוונא ודוקא בהכי הוא דשרי בקוצץ לו דינר אבל אין לו בהמה אחרת לא והבבא הראשונה שכתב היא דברי שמואל לאשמועינן דאפילו בכי הא בעינן יש לו בהמה אי נמי דמה שכתב אם א\\\"ל כל הריוח יהיה לך שלישו לא מוכח דאמותר שליש קאמר אלא מדברי התוספתא היא בבא זו כמו שאכתוב בסמוך. ובבא שנייה דברי רב ולאשמועינן היתרא מיהו הני מילי דבעינן שיהיה לו עסק אחר כשלא התנו מעיקרא אלא שבשעה שבאו לחלוק אמר לו אם כשנעשה חשבון נמצא ריוח מותר שליש יהיה בשכרך או דינר בשכרך אבל אם מתחלה התנו כן אע\\\"פ שאין לו עסק אחר מותר לדעת רבינו שכיון שהתנה מעיקרא תנאי ממון הוא ואיסורא ליכא כיון ששכר המתעסק יתר על שכרו אפילו כל שהו וזהו שכתב רבינו בסמוך ואם התנו שאם יהיה שכר יטול המתעסק\",4,0],[8,384,6,2,\"וכו' ומה שכתב רבינו עוד בסמוך עוד תיקנו חכמים שכל הנותן מעות לחבירו להתעסק בהן וכו' ולא רצה ליתן שכר עמלו בכל יום וכו' כלומר כשבאו לעשות חשבון לא רצה ליתן לו שכר כל יום ויום או ליתן לו דינר לכל ימי השותפות אם היה לו עסק אחר ומתחלת השותפות לא התנו שום תנאי ואם לא תפרש כן דהכא כשלא התנו מעיקרא עסקינן קשיא לרבינו דידיה אדידיה דהכא פסק דלא שרי באומרו שליש הריוח או עשיריתו יהיה שלך אלא ביש לו עסק אחר דוקא ולקמן אמרינן וכן אם התנו שאם יהיה שכר יטול תשיעית וכו' ורבותי הורו וכו' עד ולא יראה לי זה הרי שאפילו בדלית ליה עיסקא אחרינא שרי מיהו אפשר שאף כאן לא דיבר רבינו אלא דוקא כשהתנו מעיקרא אבל לא התנו מעיקרא שוב אין תנאי מועיל וכתב כאן הדין ביש לו עסק אחר דלכולי עלמא שרי ולקמן כתב דבאין לו עסק אחר הוא מחלוקת בינו ובין רבותיו ודרך ראשון נראה יותר:\",5,0],[8,384,6,2,\"כתבו תלמידי הרשב\\\"א והא דאמרינן בשמעתין דאי מתנה בהדיה שקול פלגא בהפסד יהיב ליה תרי תילתי באגר שתות יותר מהראוי לו בשכר טרחו ודיו בכך אע\\\"ג דלא מטי ליה בכל יום כפועל בטל כיון דשקיל מיניה וביה ואפשר דהוי ביה רווחא טובא דמטי ליה כפועל בטל או טפי לא הקפידו חכמים בדבר ושרי בהכי ואפילו במושיב חנווני סגי בהכי וכדתניא בתוספתא במושיב חנווני אבל אם אמר לו בשליש אחר שותף שלי והשליש עשוי עליך בבטלה מותר והכי קאמר בשליש תהיה שותף שלי שאטול אני שליש ואתה שליש והשליש האחר יהיה בשכר בטלתך והיינו פלגא בהפסד ותלתא באגר עכ\\\"ל. ונראה בעיני שמה שכתב רבינו וכן אם אמר ליה כל הריוח יהיה לך שלישו וכו' היא מהתוספתא הזאת וע\\\"פ מה שפירשוה תלמידי הרשב\\\"א ז\\\"ל. ולפי זה דברי הרב במותר שליש בשכרך לא הזכירם רבינו וצ\\\"ע למה ואע\\\"פ שהגהות כתבו בפ\\\"ח דלא כשמואל אלא כרב וכו' מ\\\"מ רבינו לא הזכיר ההיא דמותר שליש. אח\\\"כ מצאתי בספר התרומות ח\\\"ג שמה שכתב הרמב\\\"ם בפ\\\"ח מהלכות מלוה וכן אם מכרה לו בשתים ואמר ליה היתר על שתים וכו' היינו ההיא דמותר שליש:\",6,0],[8,384,6,2,\"ואם היה זה המתעסק אריסו וכו'. גם זה שם (דף ס\\\"ט) עובדא דר\\\"א מהגרוניא זבין בהמה ויהיב לאריסיה מפטים ליה ויהיב ליה רישא באגריה ויהיב פלגא רווחא אמרה ליה דביתהו אי משתתפת בהדיה יהיב לך נמי מאליתא אזל זבין בהדיה פליג ליה מאליתא אמר ליה תא נפלגיה לרישא אמר ליה השתא כמעיקרא נמי לא אמר ליה עד האידנא זוזי דידי הוו אי לא הוה יהיבנא לך טפי פורתא מיחזי כרבית השתא שותפי אנן מאי קאמרת טרחנא טפי פורתא אמרי אינשי סתם אריסא למארי ארעא משתעבד. וסובר רבינו שהוא הדין לענין העסק אם היה לו עסק אחר בדידיה קא טרח וההוא טירחא יתירא בלאו הכי משתעבד ליה וקשה שהרי בהאי עובדא אמרינן דהיכא דכולהו זוזי דר\\\"א דהיינו עסק בעי למיתן ליה טפי פורתא ואע\\\"ג שהאריס היה לו מלאכה אחרת שסתם אריס הוא לעבוד הקרקע ועוד דלא אהני ליה טעמא דאריסא למארי ארעא משתעבד אלא היכא דשותפי נינהו אבל מעיקרא דכוליה זוזי הוו דר\\\"א לא אהני טעמא דאריסא למארי ארעא משתעבד ורבינו כתב סתם דאריס אין צריך להעלות לו שכר וי\\\"ל שיש כמה ימים בשנה שהאריסים בטלים שאין האדמה צריכה עבודה ולכך הוה ליה אין לו עסק אחר וזהו שכתב רבינו אריסו והיה לו עסק אחר ואם איתא דסתם אריס עסק אחר יש לו למה ליה למימר והיה לו עסק אחר ואריסיה דר\\\"א לא הוה ליה עסק אחר ולהכי מעיקרא הוה יהיב ליה רישא באגריה אע\\\"ג דהוה אריסיה ואחר שנשתתף הרי יש לו עסק אחר שהוא מתעסק במעותיו ומש\\\"ה לא יהיב ליה מידי דאריסא למארי ארעא משתעבד אי נמי שרבינו סובר שמה שהיה נותן לו מתחלה טפי פורתא לאו מדינא דמדינא אריסא למארי ארעא משתעבד אלא משום דלא ליתחזי כרבית הוה יהיב ליה טפי פורתא ומשום מדת חסידות וכי אשתתף בהדיה ליכא למיחש תו למיחזי כרביתא דכיון דשותפי נינהו משמע לאינשי שאין ליטול זה יותר מזה. אי נמי דכי אמרינן דביש לו עסק אחר מותר ה\\\"מ כשהוא ממין אותו עסק וכמו שאמרו בגמרא טעמא דגביל לתורא גביל לתורי אבל אם אין לו עסק מאותו המין אע\\\"פ שהוא ממין אחר לא וע\\\"פ מ\\\"ש בתירוץ ראשון וכ\\\"כ רבינו ירוחם בדיני שותפין ולפי תירוץ זה מ\\\"ש\",7,0],[8,384,6,2,\"רבינו ואם היה לו עסק אחר כל שהוא להתעסק בו עם מעותיו של זה פירושו כשזה המתעסק משים קצת מעות בעסק עם מעות חבירו אבל כשיש לו אומנות אחרת או עסק אחר לא. ולכן קודם שנשתתף האריס עם ר\\\"א היה נותן לו חלק יתר על החצי כדין מתעסק דלית ליה עיסקא אחריתי ולפי מ\\\"ש לעיל ביישוב שני גבי שלישיתו או עשיריתו בשכרך ר\\\"א היה מתנה עמו מעיקרא ואחר שנשתתף עמו חשיב ליה כמו אית ליה עיסקא אחריתי ואע\\\"פ שהיה לו לתת לו חלק יתר לא נתן לו דאריסא למארי ארעא משתעבד כנ\\\"ל לדעת רבינו:\",8,0],[8,384,6,3,\"ועוד תקנו חכמים וכו'. נראה שזה הדין הוציאו רבינו מעובדא דבני רב עיליש דמייתי פרק איזהו נשך (בבא מציעא דף ס״ח ע״ב) דנפק עלייהו שטרא דהוה כתיב ביה פלגא באגר פלגא בהפסד ואמר רבא אי פלגא באגר תרי תילתי בהפסד ואי פלגא בהפסד תרי תילתי באגר ומפרש רבינו אי פלגא היה נוטל בעל המעות באגר ה״ל להפסיד בהפסד תרי תילתי ואי פלגא בהפסד היה מפסיד המתעסק הוה ליה ליטול בריוח תרי תילתי וכן פירש״י ומשמע לרבינו דה״פ כיון דכתיב ביה פלגא באגר פלגא בהפסד א״א לפרשו כפשוטו משום דאיסורא הוא ורב עיליש לא הוה ספי איסורא לאינשי הילכך ע״כ לפרושי בגוונא דליהוי היתרא וכתקנת חכמים דשתות כל הריוח הוי למתעסק יתר על חלקו וכן אינו פורע שתות ההפסד וכן משמע ממה שכתב רבינו בתחלת פ״ז:\",1,0],[8,384,6,3,\"וכתב הראב\\\"ד נראה לי שהוא שיבוש וכו'. נראה שדעת הראב\\\"ד לומר דהמקבל עסק סתם שקיל מקבל בהפסד פלגא כיון דפלגא מלוה צריך להפסיד פלגא דאי לא דארי מקבל בהפסד אלא תילתא לאו פלגא מלוה הוא הילכך אי הוה הפסד מפסיד פלגא ואי הוה רווחא שקיל תרי תילתי משום שכר טורחו ומש\\\"ה אמר רבא דאי פלגא בהפסד תרי תילתי באגר משום דהכי ודאי דינא בעלמא ומאי דאמר תרי תילתי בהפסד משום תנאה הוא דקאמר הכי וכ\\\"כ תלמידי הרשב\\\"א בשם הרמב\\\"ן ז\\\"ל וכ\\\"כ סמ\\\"ג במ\\\"ע סימן פ\\\"ב ובסמוך אבאר דעת רבינו ונימוקי יוסף כתב בפרק המקבל שכך נראה מדברי רבינו אע\\\"פ שאין כן דעת הראב\\\"ד עכ\\\"ל ואין דברי נימוקי יוסף נראין כלל:\",2,0],[8,384,6,4,\"ומ\\\"ש רבינו יש מי שטועה ואומר שהנותן עסק סתם אם יהיה שם שכר יטול המתעסק חציו וכו'. נראה שטעם סברא זו היא על פי דרך הראב\\\"ד שאומר שחלוקה אחת מדברי רבא היא תקנת חכמים אלא שהראב\\\"ד סובר שהוא פלגא בהפסד תרי תילתי באגר ובעל סברא זו סובר בהיפך במאי דאמר פלגא באגר תרי תילתי בהפסד ואבעל המעות קאי כמו שנתבאר וכתב רבינו שסברא זו היא טעות משום דאין לומר דחלוקה אחת מדברי רבא היא תקנת חכמים ולא האחרת אלא שתיהן תקנת חכמים כמו שנתבאר לדעתו:\",1,0],[8,384,6,5,\"הורו רבותי וכו'. דברים אלו נראין כדברי הספר החתום בלי טעם וה' האיר עיני לירד לעמקן והילך ביאורן. דעת רבותיו דכי אמר בגמרא פלגא באגר תרי תילתי בהפסד וכו' היינו לומר דבתר חלק הפקדון אזלינן לעולם שאם היה שם ריוח נוטל המתעסק שליש בריוח הנוגע לבעל הפקדון מוסף על ריוח המגיע לחלק המלוה וז\\\"ש בגמרא אי פלגא בהפסד תרי תילתי באגר נמצא שאם הפסיד ששה מפסיד בעל הפקדון ג' ואם הרויחו אינו נוטל אלא שנים והשלשה הראוי לחלקו נותנו למתעסק בשכר ואם היה שם הפסד בעל הפקדון מפסיד הפסד המגיע לחלק הפקדון ופורע יותר שליש חלק המגיע לחלקו כדי להקל מעל המתעסק וזהו שאמרו בגמרא אי פלגא באגר תרי תילתי בהפסד נמצא שאם הרויחו ששה נוטל המתעסק שלשה ובעל הפקדון שלשה ואם הפסידו מפסיד בעל הפקדון שלשה המגיעים לחלקו ומפסיד עוד שליש חלק הפסד המגיעו דהיינו אחד נמצא מפסיד ארבעה שהם תרי תילתי וס\\\"ל כמ\\\"ש דלעולם בתר חלק הנוגע לפקדון אזלינן ולא בתר חלק הנוגע למלוה כלל ורבינו דחה פירוש זה מטעם דלפי זה אפשר שיפחות ויטול שכר וכו' לכן הוא ז\\\"ל מפרש שאם היה שם הפסד לא אזלינן אלא בתר חלק המגיע למלוה שאינו פורע שליש אחד מהפסד המגיע לחלקו וזה שאמר אי פלגא באגר תרי תילתי בהפסד נמצא שאם הרויחו ששה נוטל המתעסק שלשה ואם הפסידו ששה אינו מפסיד אלא שנים דהיינו פחות שליש מחלק המגיעו. ולענין ריוח סובר רבינו דאזלינן בתר חלק הפקדון שהמתעסק נוטל שליש חלק המגיע לפקדון נוסף על המגיע לחלקו וזהו שאמר אי פלגא בהפסד תרי תילתי באגר נמצא שאם הפסידו ששה מפסיד המתעסק שלשה ואם הרויחו ששה נוטל שלשה שהם נוגעים לחלקו ושליש מחלק חבירו דהיינו ארבעה שהם שני שלישים. ולא רצה רבינו לפרש דגם לענין ריוח אזלינן בתר חלק המלוה וכמו שכתבו תלמידי הרשב\\\"א ז\\\"ל בשם הרמב\\\"ן ז\\\"ל שסובר דבין לענין הפסד בין לענין ריוח אזלינן בתר חלק המלוה והיה נמצא לפי זה שנוטל המתעסק בריוח שליש ריוח הנוגע לחלקו יותר על חלקו הראוי לו והילכך אם התנו שיפסיד המתעסק הרביע והרויחו נוטל שליש דאם ד\\\"מ הרויחו ארבעה ועשרים נוטל ששה הנוגעים לו ועוד שליש חלק שהם שנים הרי שמנה ואילו לדעת רבינו נוטל י\\\"ב ששה הראויים לו ושליש חלק חבירו שהם ששה אחרים והטעם שלא פירש רבינו כפירוש הרמב\\\"ן ז\\\"ל משום דקשיא ליה דא\\\"כ אפשר שיטול המתעסק כל הריוח ויטול גם מהקרן להשלים ריוח שלו כגון שהתנו שיפרע בעל המעות אחד מחמשה בהפסד והרויחו ה' הרי המתעסק נוטל ד' המגיעים לחלקו ועוד שליש דהיינו אחד ושליש נמצא שצריך ליטול מהקרן שליש דינר ואם הרויחו עשרה צריך ליטול שני שלישי דינר ואם הרויחו ט\\\"ו צריך ליטול דינר מהקרן להשלים הריוח וזה תימה גדול ודבר שאין הדעת סובלתו כמו שקדם לו ז\\\"ל ולא חשש רבינו לבאר זה לפי שממה שכתב לעיל נלמוד זה או לפי שלא ראה הוא ז\\\"ל מי שסבר כסברת הרמב\\\"ן ז\\\"ל לא כתב מה שקשה עליה. והוי יודע שתלמידי הרשב\\\"א ז\\\"ל כתבו סברת רבותיו של רבינו וכתבו שאם שליש חלק הפקדון נעלה יותר מחלק המלוה אינו חייב הנותן לתת לו כלום מביתו אבל כל זמן שיש על המתעסק לשלם ראוי לפוטרו עד כדי הפסד שליש הפקדון וזהו הדרך הנכון וכן כתב הרב אלפסי ז\\\"ל בתשובה וגם הפירוש הזה לא ישר בעיני רבינו משום דכיון שהמלוה צריך להפסיד שליש יותר המגיע לו כפי פירושם בגמרא מנא ליה לפוטרו בלא שום גילוי מהגמרא ולכן יותר נכון בעיניו לפרש כמו שכתבתי. ואל יקשה בעיניך לדעת רבינו למה לגבי ההפסד אנו הולכים אחר חלק המלוה ולגבי הריוח אנו הולכים אחר חלק הפקדון דטעם נכון יש בדבר דביש ריוח ראוי שאם טרח בפקדון מרובה יטול שכר הרבה ואם טרח בפקדון מועט יטול חלק מועט שאם תאמר ניזיל בתר מלוה לקתה מדת הדין דזימנין שחלק המלוה מועט ונמצא שטרח בפקדון מרובה בשכר מועט הילכך דינא הוא דניזיל בתר חלק הפקדון אבל לענין ההפסד הוי איפכא דאי אזלינן בתר חלק הפקדון לקתה מדת הדין דזימנין שחלק הפקדון מרובה ונמצא שהמקבל אינו מפסיד כלום ולפעמים נוטל מעות מהנותן הילכך אזלינן בתר חלק מלוה שיסייע הנותן למקבל בשליש הפסד המגיע שנמצא לפי זה שלעולם אין המקבל מפסיד אלא שני שלישים מהפסד הנוגע לחלקו והשליש האחר מסייעו בו הנותן בשכר טורחו ולעולם אין הנותן נוטל אלא שני שלישים מריוח הנוגע לו דהשליש האחר נותנו למקבל בשכר טורחו ובזה הושוו כל המדות:\",1,0],[8,384,7,1,\"לפיכך שטר עסק וכו'. בבתרא פרק המוכר את הבית (בבא בתרא דף ע' ע״ב) כתבה הרי״ף ז״ל במציעא פרק המקבל שטר כיס היוצא על היתומים דייני גולה אמרו נשבע ונוטל כולו ודייני ארץ ישראל אמרו נשבע וגובה מחצה ואסיקנא התם הילכתא כדייני ארץ ישראל שאותו חצי דמשום פקדון חיישינן שמא נאנס או שמא פרעו שהמפקיד אצל חבירו בשטר וא״ל החזרתי נאמן וטוענין ליורש:\",1,0],[8,384,7,2,\"המתעסק שהפסיד וחזר וטרח עד וכו'. במציעא פ' המקבל (בבא מציעא דף ק״ה) אמר רבא האי מאן דקביל עיסקא מן חבריה ופסיד טרח ומלייה ולא אודעיה לא מצי א״ל דאי מהאיך פסידא בהדאי משום דא״ל להכי טרחת למליותיה כי היכי דלא ליקרו לך מפסיד עסקי ופירש״י דמדלא אודעתן מעיקרא נכלם היית בדבר ואדעתא דמילוי קרנא טרחת ומשמע בהדיא דאי אודעיה בשהפסיד ואחר כך הרויח מחשב על ההפסד בפני עצמו ועל הריוח בפני עצמו ובאמת שרבינו סתם הדברים ועל כל פנים יש לנו לפרשם וכן משמע מדקדוק לשונו וקל להבין:\",1,0],[8,384,7,3,\"נתן לו מאתים יריעות וכו' עד וכן כל כיוצא בזה. שם מימרא דרבא:\",1,0],[8,384,7,4,\"אין המתעסק יכול לחלוק וכו'. כך העלה הרב אלפסי ז\\\"ל במציעא פרק המקבל והכריע בראיות נגד החולקים בזה וכתב דמהא דאמר רבא התם להכי קרי ליה עיסקא דא\\\"ל לאיעסוקי ביה יהבי לך ולא שיטול חצי הממון שהוא מלוה למישתי ביה שכרא שמעינן דלית לשותף למיפלגיה לממונא בשום צד אלא להתעסק בכולו יחד ואם חלק בפני כל בית דין שבעולם לא מהני ליה ולא ירדתי לסוף דעתו של הטור מה היה דעתו בדברי רבינו שכתב עליו בטור י\\\"ד סימן קע\\\"ז ולא נהירא דדבר פשוט הוא זה עד כאן ואולי חשב שזה פי' למימרא דרבא דלהכי קרו ליה עיסקא וכו' ואינו במשמע דבריו ועוד שכתב שזה פשוט והרי הריא\\\"ף כתב שרבוואתא הורו היפך זה אלא דברי רבינו טובא סוכלתנו ונהירו אית בהו:\",1,0],[8,384,7,5,\"המתעסק שנתן מתנה לאחרים וכו'. כתב מ\\\"ע דאיתא בתשובת הגאונים ובספר מצות גדול:\",1,0],[8,384,7,5,\"ואם יש שם עדים שהמטלטלין אלו מן המעות וכו'. במציעא פרק המקבל (בבא מציעא דף ק״ד ע״ב) רבא אמר להכי קרו ליה עיסקא שאם מת לא יעשה מטלטלין אצל בניו וכתב נימוקי יוסף בשם רבינו האי דכל היכא דאיתיה לההוא עיסקא בעיניה גבי מיתמי בלא שבועה וכ״כ הרא״ש:\",2,0],[8,384,7,6,\"הנותן מעות לחבירו ליקח בהם פירות למחצית שכר וכו' עד בעל כרחו. ירושלמי כלשון רבינו כתבו הרי\\\"ף ז\\\"ל פרק איזהו נשך וכתב הרב רבינו ניסים בקידושין ראש פרק האומר בשם בעל מתיבות דהני מילי בשלקח בזוזי משלח אבל אם לא לקח בזוזי משלח אינו מוציא ממנו והיינו דאמרינן התם דרבה בר בר חנא יהיב זוזי לרב למזבן ליה ארעא וזבנה רב לנפשיה וכן כתב ה\\\"ה פרק שביעי מהלכות מכירה ובאותו פרק תמצא דין זה בשלימות בענין אם שלח יד באותן המעות קודם שיקנה בהן או אמר בפני עדים שחוזר בו משליחותו שאז המקח לשליח אבל אם אין עדים בדבר אף על פי שהשליח אומר ששלח בהן יד וזקפו עליו מלוה המקח למשלח ובנימוקי יוסף פרק איזהו נשך משנת אין מושיבין חנווני וכו' כתוב שיש לחלק בין בשעשאו שליח לצורך המשלח לכשאמר לו למחצית שכר דבהאי ירושלמי אמר למחצית שכר ולכך מוציא ממנו אבל בפרק האומר עשאו שליח לצורך המשלח ולכך מה שעשה עשוי ורבינו חולק על זה בפרק שביעי מהלכות מכירה:\",1,0],[8,384,7,7,\"נתן לו מעות וכו'. גם זה ירושלמי כתבו הרב אלפסי פרק איזהו נשך ונראה לי הטעם דדוקא פירות שהזכיר לו רשאי ליקח ולא דבר שאינו נקרא פירות כגון כסות או עצים:\",1,0],[8,384,7,7,\"המושיב את חבירו בחנות וכו'. תוספתא הביאה בעל נימוקי יוסף בפרק איזהו נשך והרא\\\"ש כתבה גם כן בפרק הנזכר עלה קמ\\\"ד:\",2,0],[8,384,8,1,\"הנותן ביצים לבעל התרנגולים להושיב התרנגולים וכו'. ברייתא במציעא פרק איזהו נשך (בבא מציעא דף ס״ח ע״ב):\",1,0],[8,384,8,1,\"וכן השם עגלים וכו'. משנה שם אין שמין עגלים וסייחים למחצה אא\\\"כ נותן לו שכר עמלו ומזונו ומפרש רבינו בשכר עמלו היינו כפועל בטל:\",2,0],[8,384,8,1,\"ומגדל אותם וכו'. ג\\\"ז שם במשנה:\",3,0],[8,384,8,1,\"ואינו יכול למכור שלא מדעת חבירו וכו'. ברייתא שם:\",4,0],[8,384,8,1,\"ומ\\\"ש ואם א\\\"ל הרי הראש והאליה וכו'. ג\\\"ז שם (דף ס\\\"ט) ר\\\"א מהגרוניא זבין בהמה ויהיב לאריסיה מפטים לה ויהיב ליה רישא באגריה ויהיב פלגא רווחא:\",5,0],[8,384,8,1,\"כתב הראב\\\"ד ז\\\"ל וכן השם בהמה על המפטם וכו' עד יתר על מחצית השכר מותר א\\\"א דבר זה אינו מחוור וכו':\",6,0],[8,384,8,1,\"היו למפטם וכו'. ג\\\"ז שם אמר רב מותר שליש בשכרך מותר כלומר אע\\\"פ שהוא ספק משום דאמרי אינשי גביל לתורא גביל לתורי:\",7,0],[8,384,8,1,\"ואם היה אריסו. שם מסיים בעובדא דר\\\"א מהגרוניא דאשתתף בהדיה כלומר שנתן לו חצי המעות וחלק עמו בשוה משום דאריסא למארי ארעא משתעבד ואין ספק שרבינו בשותפות מיירי שכך כתב אפילו לא תעלה לו אלא דבר מועט בכל ימי השותפות הזאת דיו:\",8,0],[8,384,8,2,\"השם עגלים וסייחים וכו'. זה פשוט:\",1,0],[8,384,8,3,\"שמין פרה וחמור וכו'. משנה באיזהו נשך (דף ס\\\"ט ע\\\"ב):\",1,0],[8,384,8,3,\"ואין שמין עגל עם אמו וכו'. שם במשנה ובברייתא רשב\\\"ג אומר שמין עגל עם אמו וסייח עם אמו כלומר וא\\\"צ להעלות מזונות לעגל ולסייח ופסק הרי\\\"ף דלא כרשב\\\"ג ואע\\\"ג דבכ\\\"מ ששנה רשב\\\"ג במשנתנו הלכה כמותו נ\\\"ל דטעמא דהרי\\\"ף מדאמרינן בגמרא ורשב\\\"ג לא בעי שכר עמלו ומזונו איכא גללים ואידך גללים אפקורי מפקר להו ובפרק אלו מציאות גבי השבת אבידה פריך ואימא לאתויי גללים ומשני סתם גללים אפקורי מפקר להו וממילא לא קי\\\"ל כרשב\\\"ג ואע\\\"ג דאפשר לשנויי אליביה שינויא דחיקא הוא:\",2,0],[8,384,8,4,\"השם בהמה לחבירו וכו'. ברייתא שם:\",1,0],[8,384,8,4,\"ילדה הבהמה וכו' מקום שנהגו וכו'. משנה שם:\",2,0],[8,384,8,4,\"חייב המתעסק וכו'. ברייתא שם (דף ע') ואע\\\"ג דרבי יוסי פליג אהא הלכה כת\\\"ק:\",3,0],[8,384,8,4,\"רצה להטפל בהם וכו'. שם (דף ס\\\"ט) בברייתא מכאן ואילך נוטל מחצה בשלו ומחצה בשל חבירו ופירש\\\"י דשכר עמל ומזון ליכא וכו' דכיון דבעי למיטרח בה משום מחצה שלו שהוא קרן גמור ואינו מלוה כי טרח משום דידיה קא טרח לא מיחזי כרבית:\",4,0],[8,384,8,4,\"ואם לא התנה כן וכו'. כך כתבו קצת מפרשים ואמרו דדמיא להא דתנן בבתרא האחין שהשביחו את הנכסים השביחו לאמצע אם אמרו ראו מה שהניח לנו אבא הרי אנו עושים ואוכלים השביחו לעצמם:\",5,0],[8,384,8,4,\"מקום שנהגו להעלות שכר וכו'. זהו פירוש מה ששנינו בברייתא פרק איזהו נשך מקום שנהגו להעלות שכר כתף למעות מעלין לבהמה מעלין להעלות ולדות בשכר עמלו ומזונו מעלין ואין משנין ממנהג המדינה והראב\\\"ד ז\\\"ל כתב האי פירושא לא נהיר וכו':\",6,0],[8,384,8,5,\"ראובן שהיתה לו שדה וכו'. דלא שייך צד רבית בקרקע כדשייך במטלטלין שכן מצינו חכמי הגמרא שהיו להם אריסים:\",1,0],[8,384,8,5,\"אריס אומר למחצה וכו'. פלוגתא דרב יהודה ורב נחמן במציעא פרק המקבל (בבא מציעא דף ק״י) ופסק כרב נחמן בדיני:\",2,0],[8,384,8,6,\"בעל שהוריד אריסים בנכסי אשתו וכו' עד ושמין להן כאריס. בעיא דאיפשיטא בכתובות פרק האשה שנפלו (כתובות דף פ' ע״א) והטעם שאם היה הבעל אריס יודע בטיב אריסות שאם לא ירדו אלו היה יורד הוא הרי האשה אומרת להם לא הועלתוני דבר ואינה נותנת להם אלא הוצאה שיעור שבח ואם אין הבעל אריס הרי הועילוה דארעא לאריסי קיימא.\",1,0],[8,384,8,6,\"ומ\\\"ש ואין להם מן ההוצאה אלא שיעור השבח ובשבועה. כך מפורש שם לגבי בעל ופשיטא דלא עדיפי מיניה:\",2,0],[8,384,8,7,\"האחין או שאר היורשין וכו'. שבכ\\\"מ שנינו האחין השותפין ואם האחין הם שותפין למה ליה למיתניא אחים אטו משום דאחים נינהו ה\\\"א דגריעי אלא ודאי הכי קאמר האחין שלא חלקו או השותפים שנשתתפו וסובר רבינו דלאו דוקא אחים אלא הוא הדין שאר יורשים.\",1,0],[8,384,8,7,\"ועל מ\\\"ש רבינו ירושת מורישן כתב הראב\\\"ד א\\\"א לא האירו דבריו וכו'. ואיני יודע מניין לו לחלק בכך:\",2,0],[8,384,8,7,\"אחד מן האחין וכו'. משנה בבתרא פרק מי שמת (בבא בתרא דף קמ״ד ע״ב) האחין השותפין שנפל אחד מהם לאומנות נפל לאמצע חלה ונתרפא נתרפא משל עצמו ובגמרא תנא לאומנות המלך שלח רבין משמיה דרבי אילעא לא שאנו אלא שחלה בפשיעה אבל חלה באונס נתרפא מן האמצע. והוי יודע דתניא בגמרא אבבא דרישא שאם נפל לאומנות המלך מחמת האחין לאחין פירוש לאמצע ואם מחמת עצמו לעצמו וכתבה הרי״ף ואיני יודע למה השמיטה רבינו ונראה שלזה כיון הראב״ד שכתב אחד מן האחין או השותפין שנפל לאומנות המלך וכו' א״א גם בזה קיצר מאד עכ״ל:\",3,0],[8,384,9,1,\"השותפין כולן וכו'. משנה בשבועות פרק כל הנשבעין (שבועות דף מ״ה) ואלו נשבעין שלא בטענה השותפין והאריסין והאפוטרופין והאשה הנושאת והנותנת בתוך הבית ובן הבית ופירש רבינו אפוטרופין שמינו אותם ב״ד דאילו מינם אבי היתומים לא ישבעו כמו שנתבאר בפרק זה:\",1,0],[8,384,9,1,\"כל אחד מאלו נשבע וכו'. שם (דף מ\\\"ח ע\\\"ב) בגמרא אמרינן אמתניתין דואלו נשבעין שלא בטענה אטו בשופטני עסקינן כלומר שמשביעין בלא טענה ומהדרינן ה\\\"ק ואלו נשבעין שלא בטענת ברי אלא בטענת שמא כלומר שטוענו שמא עכבת משלי:\",2,0],[8,384,9,1,\"ולמה תיקנו חכמים וכו'. מפורש שם בגמרא:\",3,0],[8,384,9,2,\"ואין כל אחד מאלו נשבע וכו'. שם אמר רב יוסף בר מניומי אמר ר\\\"נ והוא שיש טענה ביניהם שתי כסף כמאן כשמואל והא תני רבי חייא לסיועיה לרב אימא כפירת טענה שתי כסף כרב כלומר דבפרק שבועת הדיינים פליגי רב ושמואל והלכה כרב וכמו שפסק רבינו פ\\\"ג מטוען ונטען ופירוש דברי רב שם הם שהטענה צריכה שתהיה שתי כסף ופרוטה ויכפור בשתי כסף ויודה בפרוטה ורש\\\"י גבי שבועת השותפין פירש שגם שם צריך הודאה בפרוטה דקרובה היא לשבועה דאורייתא אלא שטענת שמא היא אבל דעת רבינו כדעת ר\\\"י ן' מיגאש דבשבועת השותפין לא בעינן הודאה ונ\\\"ל דהיינו טעמא דכיון דמעיקרא הוה ס\\\"ד דבלא שום טענה משביעים להו כשהשיבו ה\\\"ק נשבעין בטענת שמא די לנו שנאמר שחידש שהיה שם טענה ולא שהיה שם טענה וכפירה ועוד דאי הוה בעינן טענה וכפירה כעין דאורייתא למה ליה לר\\\"נ למימר דבעינן כפירת טענה שתי כסף כרב אלא ודאי לא בעינן הודאה וכיון דלא בעינן הודאה ממילא בטענת שתי כסף סגי דע\\\"כ לא אמרינן בשבועת הדיינים דבעינן שתי כסף ופרוטה אלא היכא דבעינן הודאה אבל היכא דלא בעינן הודאה בשיעור כפירה דהיינו שתי כסף סגי. אי נמי דנהי דבמודה במקצת בעינן הודאה היינו טעמא משום דעיקר אותה שבועה על הודאה היא באה שאילו כפר בכל פטור היה אבל שבועת השותפין כיון דכופר במה שטענו מחוייב לישבע כיון דמשום ספק הוא וכ\\\"נ מדברי הרי\\\"ף והרא\\\"ש:.\",1,0],[8,384,9,3,\"מכאן הורו רבותי שאם מת השותף וכו' ויש מי שהורה וכו'. איני יודע מה ראיה מביא רבינו מדמשביעין את האשה שנעשית אפוטרופא בחיי בעלה דהא איכא לאוקומה בשחושדים אותה בשתי כסף ואין לומר דמייתי ראיה מדקתני לה סתם ולא חילק בין חושדין אותה לאינם חושדים אותה דהא פשיטא דאיכא למימר דסמך על מאי דאמר ר\\\"נ והוא שיש טענה ביניהם שתי כסף:\",1,0],[8,384,9,4,\"אף על פי שאין שם עדים וכו'. כן כתב הרא\\\"ש ריש שבועת הדיינים בשם הר\\\"י ן' מיגש ורבינו נמשך לדעת רבו:\",1,0],[8,384,9,4,\"איזהו בן הבית וכו'. ברייתא שם:\",2,0],[8,384,9,4,\"וכן אפוטרופוס שמינהו אבי יתומים וכו'. בגיטין פרק הניזקין (גיטין דף נ״ב) פלוגתא דאבא שאול ורבנן במתניתין ופסקו בגמרא הלכה כאבא שאול דאמר מינהו אבי היתומים לא ישבע:\",3,0],[8,384,9,4,\"וכן האשה שלא נעשת אפוטרופא וכו'. בכתובות פרק הכותב מימרא דרב מתנא ופסק הרי\\\"ף כן:\",4,0],[8,384,9,5,\"המשלח ביד חבירו וכו' עד שנשא ונתן. כתב מ\\\"ע הוא בתשובת הגאונים:\",1,0],[8,384,9,5,\"ודע שהרשב\\\"א בתשובה חולק שאומר לא אמרו אלא בבן הבית שמתעסק תמיד בבית כגדול האחין וכן פירש\\\"י וכן מסתבר שאם כדברי הרמב\\\"ם ליתני השליח דהוי רבותא טפי ועוד הביא ראיות לדבר. וכתב עוד שאם הוא חשוד על השבועה חזרה שבועה למקומה ואף הרמב\\\"ם יודה בזה וטען טענות בדבר:\",2,0],[8,384,9,6,\"השותפין שנושאין ונותנין וכו'. דין זה פשוט בטעמו:\",1,0],[8,384,9,7,\"חלקו השותפין וכו'. משנה פרק כל הנשבעין (שבועות דף מ״ח) חלקו השותפין והאריסין אינו יכול להשביען וכתב הרי״ף והוא הדין לשאר ופשוט הוא:\",1,0],[8,384,9,7,\"וכתב בח\\\"מ בשם הרמ\\\"ה דמדנקט חלקו השותפין ונתגרשה האשה ונתפרדו האחין זה מזה ולא תבעו ולא נקט חלקו סתמא משמע דוקא באלו אבל באחריני אפילו חלקו נמי והשתדל לתת טעם לדבר ולפי נוסחאותינו אכולהו קאי וכסברת הרי\\\"ף וכמ\\\"ש:\",2,0],[8,384,9,7,\"אבל אם היה לו טענת ודאי וכו'. זה פשוט דהא אינש דעלמא דלאו שותף אם טענו טענת ודאי צריך לישבע ומשום דשותף הוא לא גרע.\",3,0],[8,384,9,7,\"ומ\\\"ש ומגלגל עליה כל מה שירצה. שם במשנה נתגלגלה עליו שבועה ממקום אחר מגלגלין עליו את הכל כלומר מגלגלין גם את זו עליו:\",4,0],[8,384,9,7,\"וכן אם נתחייב לו שבועה וכו' בין של דבריהם. שם איבעיא להו מגלגלין בדרבנן ואיפשיטא דמגלגלין ומפורש בדברי רבינו דגלגול שבועה אפילו בשמא על שמא איתא וכדברי הרמב\\\"ן ז\\\"ל והר\\\"נ בפ\\\"ק דקידושין:\",5,0],[8,384,9,8,\"השותפין שחלקו ונשאר להם חובות אבל וכו' עד סוף הפרק. כתב מ\\\"ע דאיתיה בתשובת הגאונים וספר מצות גדול.\",1,0],[8,384,9,8,\"ומ\\\"ש אבל אם נשאר ביניהם כל שהו מן הפירות שעדיין לא חלקו וכו'. נלמד ממה שאמר הרב אלפסי בפרק הנשבעין ואם אמר הנתבע כבר חלקנו ולא אשתייר ליה גבאי ולא מידי והוא אומר עדיין לא חלקנו ועדיין אית לי גביה כך וכך:\",2,0],[8,384,9,9,\"מי שתבע את חבירו וכו'. כך כתב הרי\\\"ף בס\\\"פ הנשבעין:\",1,0],[8,384,10,1,\"שותף שטען על חבירו שכך היה תנאי ביניהם וכו':\",1,0],[8,384,10,3,\"התובע שותפו להשביעו שבועת וכו' טענו שעדיין שותפי אתה ונשאר לי אצלך כך וכך וכו'. כך כתב הרי\\\"ף בס\\\"פ הנשבעין:\",1,0],[8,384,10,5,\"ראובן שהטיל לכיס וכו' ומ\\\"ש טען ראובן ששמעון יודע וכו' יגלגל על שמעון וכו'. כלומר ישבע שבועת השותפין ויגלגל עליו שאינו יודע בודאי סכום הפחת הזה וה\\\"ה שאם רצה משביעו היסת שאינו יודע בודאי סכום הפחת ויגלגל עליו שבועת השותפין כמ\\\"ש בתחלת הפרק.\",1,0],[8,384,10,5,\"ומ\\\"ש ואם לא נתעסק שמעון בשותפות זו כלל. כלומר דהשתא אין לו לישבע שבועת השותפין ישבע שמעון היסת שאינו יודע וכו' והטעם דברישא ישבע ראובן ויפטר אבל לא תועיל לו שבועתו לגבות משמעון עוד חמשים שהוא תשלום החלק הנוגע לו בהפסד שאינו נשבע ונוטל וכמ\\\"ש בסוף דבריו שאין השותף מהנשבעין ונוטלין ונראה שדקדק לכתוב ישבע ראובן שבועת השותפין שפחתו ולא כתב שפחתו לו חמש מאות מפני שכיון שאינו נוטל כל חלק הפסד המגיע לשמעון דהיינו מאתים וחמשים מיחזי כאילו נשבע לשקר ולפיכך נשבע שפחתו ולא פחתו פחות מת' וכדאמרינן בריש מציעא על זה ישבע שאין לו בה פחות מחציה וכשטען ראובן ששמעון יודע בודאי בפחת זה כלומר וצריך לשלם לו חמשים תשלום הנוגע לחלקו בהפסד צריך לישבע שאינו יודע ואם לא רצה לישבע ישלם ודקדק לכתוב שטען ראובן ששמעון יודע בודאי בפחת זו לפי שאם לא היה טוען אלא שמא יודע הא קי\\\"ל דאין משביעין על טענת שמא וכמ\\\"ש בפ\\\"א מטוען וא\\\"כ לא היה יכול לכתוב ואם לא נתעסק וכו' ישבע שמעון היסת אבל מ\\\"ש יגלגל על שמעון שאינו יודע אפילו לא טענו שיודע שמעון בודאי יכול לגלגל וכמ\\\"ש ה\\\"ה בפ\\\"א מטוען דאיתא בפ\\\"ק דקידושין והיינו לומר שישבע שבועת השותפין ויגלגל עליו.\",2,0],[8,384,10,5,\"ומ\\\"ש ולא עוד אלא וכו'. ארישא קאי דקתני אין אומרים ישבע ראובן וכו' וישלם שמעון חמשים מביתו אלא ישבע ראובן שבועת השותפין שפחתו וילך במנה שבידו בלבד ולא ישבע שמעון כלומר והשתא קאמר שכבר אפשר שיטול שמעון חמשים והיינו אם המנה בידו והוקשה לו כיון דראובן טען שפחתו ת\\\"ק ה\\\"ל לשמעון ליתן כל המנה שבידו לראובן וניחא ליה משום דאין השותף מהנשבעין ונוטלין הילכך שבועת ראובן אינה מעלה ולא מורדת לענין זה הילכך חולקין שניהם המנה הנשאר מאחר שהוא ביד שמעון וטעם זה עולה גם למ\\\"ש ברישא שלא ישלם לו כלום:\",3,0],[8,384,10,5,\"וכתב הראב\\\"ד מי שאמר שישלם שמעון חמשים הולך על הדרך שאמר הוא למעלה הטילו לכיס זה מנה וזה מאתים השכר או הפחת לאמצע ונמצא ראובן מפסיד מאתים וחמשים ושמעון כמו כן מאתים וחמשים אלא שאיני מודה שישלם שמעון כלום וכן בכל גרעון שיהיה שם שלא קיבל זה אחריות לזה אלא זה מפסיד ממה שהיה לו וזה מפסיד ממה שהיה לו לפי מעותיהם וכו' נמצא לראובן בהפסד הת\\\"ק של\\\"ג דינרים בקירוב ולשמעון קס\\\"ז נשארו לשמעון באותו המנה ל\\\"ג והשאר לראובן וזהו דין אמת עכ\\\"ל. ומ\\\"ש [מ\\\"ש] שישלם שמעון חמשים הולך על הדרך שכתב הוא למעלה כלומר בפיסקא הטילו לכיס זה מנה וזה מאתים השכר או הפחת לאמצע והראב\\\"ד חולק עליו לענין ההפסד שהוא סובר שכל אחד מפסיד לפי מעותיו ומודה בשכר שחולקין אותו לאמצע ואע\\\"פ שזה מעותיו מועטים נוטל בשכר כמו שנוטל מי שמעותיו מרובים:\",4,0],[8,384,10,6,\"טען שמעון שיש ללוי וכו': כתב הראב\\\"ד ומאחר שהשטר של לוי מפורש שהוא מן השיתוף של ראובן וכו'. ודבריו דברי טעם הם ונראה שלא יחלוק עליהם רבינו.\",1,0],[8,384,10,6,\"ומ\\\"ש נפטר לוי בהודאת שמעון מיירי כשהשטר ביד שמעון ולענין כל החוב א\\\"נ אפילו אם השטר ביד ראובן ואפ\\\"ה כתב שנפטר לוי לענין שיגבה ראובן משמעון תחלה מחצה ואם לא יוכל להוציא משמעון יגבה מלוי:\",2,0],[8,384,10,6,\"סליקו להו הלכות שלוחין ושותפין\",3,0],[8,385,1,1,\"ועל זה שמכרוהו בית דין הוא אומר כי תקנה עבד עברי. במכילתא:\",1,0],[8,385,1,1,\"מוכר עצמו כיצד זה ישראל שהעני ביותר וכו' ואינו רשאי למכור את עצמו עד שלא ישאר לו כלום וכו'. בת\\\"כ פרשת בהר סיני מנין שאין אדם רשאי למכור עצמו ולהניח באפונדתו וליקח לו בהמה וליקח לו כלים וליקח לו בית אלא א\\\"כ העני תלמוד לומר וכי ימוך ונמכר הא אינו נמכר אלא אם כן העני וברייתא זו מתפרשת מתוך דברי רבינו.\",2,0],[8,385,1,1,\"ומה שכתב או ליתנם לבעל חובו:\",3,0],[8,385,1,2,\"כבר ביארנו שאין האשה וכו'. משנה בסוטה סוף פרק היה נוטל (סוטה דף כ״ג).\",1,0],[8,385,1,2,\"ומ\\\"ש וכן אינה מוכרת עצמה. מבואר במכילתא:\",2,0],[8,385,1,2,\"ואינה קונה לא עבד עברי וכו'. ברייתא במציעא פרק איזהו נשך (בבא מציעא דף ע״א) פסק כת״ק דרבן שמעון בן גמליאל:\",3,0],[8,385,1,2,\"ואין הגר נקנה וכו'. גם זה ברייתא שם וכתב ספר מצות גדול ומה ששנינו במכילתין דבין לרבי ישמעאל בין לר' עקיבא גר נקנה בע\\\"ע לשם מדבר בגר הבא על בת ישראל שמשפחת אם היא לו משפחה כך פירש מורי עכ\\\"ל:\",4,0],[8,385,1,3,\"עבד עברי שמכרוהו ב\\\"ד אין מוכרין אותו אלא לישראל או לגר. כך היא הגירסא הנכונה והוא מדתניא בספרי כי ימכר לך מנין כשהוא נמכר אינו נמכר אלא לך תלמוד לומר כי ימכר לך ובפרק איזהו נשך שם תניא גר צדק האמור לענין מכירה דכתיב וכי ימוך אחיך עמך ונמכר לך ולא לך אלא לגר שנאמר לגר ולא לגר צדק אלא לגר תושב שנאמר לגר תושב משפחת גר זה עכו\\\"ם כשהוא אומר או לעקר זה הנמכר לעבודת כוכבים עצמה אמר מר ולא לך אלא לגר למימרא דגר קני ע\\\"ע ורמינהי אין הגר נקנה בע\\\"ע ואין אשה וגר קונים ע\\\"ע גר לא נקנה בע\\\"ע ושב אל משפחתו בעינן והא ליכא ואין אשה וגר קונים ע\\\"ע אשה לאו אורח ארעא גר נמי גמירי דמיקני קני דלא מיקני לא קני אר\\\"נ בר יצחק אינו קונה ודינו כישראל אבל קונה ודינו כעכו\\\"ם דתניא הנרצע והנמכר לעכו\\\"ם אינו עובד לא את הבן ולא את הבת. ופירש\\\"י אינו עובד לא את הבן ולא את הבת ועבדו לעולם ולא לבן. והנמכר לעכו\\\"ם. ילפינן בקידושין וחשב עם קונהו ולא עם יורשי קונהו:\",1,0],[8,385,1,4,\"בא ואמר לך וכו'. הכי משמע פשטיה דקרא אחרי נמכר גאולה תהיה לו ואיתיה בת\\\"כ בא ואמר הריני נמכר יכול הוזקק לו תלמוד לומר אחרי נמכר הא אין אתה נזקק לו אלא משימכר:\",1,0],[8,385,1,5,\"אחד המוכר עצמו וכו' אינו נמכר בפרהסיא על אבן המקח וכו'. בתורת כהנים פרשת בהר סיני:\",1,0],[8,385,1,6,\"כל עבד עברי אסור לעבוד בו בפרך וכו'. שם לא תרדה בו בפרך שלא תאמר לו החם את הכוס הזה והוא אינו צריך הצן לי את הכוס והוא אינו צריך עדור תחת הגפן עד שאבא:\",1,0],[8,385,1,6,\"וכתב הראב\\\"ד מכאן אמרו חכמים שלא יאמר לו עדור וכו' עד מקום פלוני. א\\\"א הסברא שלו היא זו אבל חכמים לא פירשו בו טעם קצבה ולא אמרו שלא יאמר לו עדור תחת הגפנים עד שאבא משום קצבה ולא קצבה אלא שלא יאמר לו עד שאבא והוא מתעכב לבא וכו'. ואיני רואה בכל הדברים האלו השגה לדברי רבינו דמה לי אומר עד שאבא והוא מתעכב לבא עד שיצטער כדברי הראב\\\"ד מה לי שהטעם מפני שלא נתן קצבה כדברי רבינו שטעם הצער בלא נתן לו קצבה מפני שהוא מצטער בכל שעה כמו שאמרו דשאני בין בהבאה שיש לה קצבה לשאין לה קצבה ואם נתן לו מלאכה שאין לו קצבה כדי לצערו הדבר מסור לה' שיודע אם נתכוון לצערו. ומ\\\"ש ועוד העבד לא יהיה אלא כפועל וכו'. איכא לאקשויי ולדידיה מי ניחא אלא מאי אית לך למימר דמיירי בשעשה כך שאמר לו עד שאבא ונתאחר מלבא לרבינו נמי מיירי בשאמר ליה עד שאבא וטעמא משום דלא נתן לו קצבה:\",2,0],[8,385,1,6,\"ומה שכתב וכן העכו\\\"ם שנמכר לו וכו'. מבואר בכתוב.\",3,0],[8,385,1,6,\"ומה שכתב ואין אנו נזקקין לכנוס לרשותו של עכו\\\"ם וכו'. בתורת כהנים:\",4,0],[8,385,1,7,\"כל עבד עברי וכו' עד כשהיה עושה מקודם. הכל במכילתא ובתורת כהנים:\",1,0],[8,385,1,7,\"במה דברים אמורים וכו'. גם זה שם אבל בבנו ותלמידו רשאי וכתב רבינו שהוא הדין לשאר כל אדם שאינו עבד ונתן טעם לדבר:\",2,0],[8,385,1,8,\"אנשים שאינם נוהגים כשורה וכו' עד מותר להשתמש בו כעבד. מציעא פרק איזהו נשך (בבא מציעא דף ע״ג ע״ב). וכתב הראב״ד ז״ל בחיי ראשי לא נאמרו דברים הללו בגמרא וכו'. ואינה השגה שהוא ז״ל מפרש משעבדי בהו טפי שפורעין עשרה ומשתמשין בהם שוה ט״ו ורבינו מפרש שמשתעבדים יותר מדאי ויש הוכחה לפירוש רבינו מדסמך לזה בגמרא ההיא דמי שאינו נוהג כשורה מותר להשתעבד בו.\",1,0],[8,385,1,8,\"ומה שכתב רבינו אבל לא כעבד כלומר כעבד כנעני:\",2,0],[8,385,1,9,\"כל עבד עברי וכו' עד כקונה אדון לעצמו. פירקא קמא דקידושין (דף כ'):\",1,0],[8,385,1,9,\"ואף על פי כן צריך העבד לנהוג בעצמו מנהג עבדות וכו'. בתורת כהנים כי ימכר לך אחיך שתנהוג בו באחוה יכול אף הוא ינהוג עמך באחוה ת\\\"ל עבד יכול אף אתה תתנהג עמו כעבד ת\\\"ל אחיך הא כיצד אתה נוהג באחוה והוא נוהג בעצמו בעבדות:\",2,0],[8,385,1,10,\"אין אמה העבריה נוהג וכו'. בפרק המקדיש שדהו (ערכין דף כ״ט) אין עבד עברי נוהג אלא בזמן שהיובל נוהג שנאמר עד שנת היובל יעבוד עמך:\",1,0],[8,385,2,1,\"עבד עברי שמכרוהו בית דין נקנה בכסף וכו'. משנה פרק קמא דקידושין (דף י\\\"ד) עבד עברי נקנה בכסף ובשטר ובכל מקום הוי שוה כסף ככסף דילפינן מנזקין ועבד עברי דכתיב בהו ישיב כמו שכתבו התוספות בריש קידושין. אבל קשה שכתב רבינו עבד עברי שמכרוהו בית דין ובגמרא ילפינן מקראי דלא שנא בין מכרוהו בית דין למוכר עצמו. ומצאתי בספר מוגה שכתב כלשון הזה עבד עברי שמכרוהו בית דין והמוכר עצמו נקנה בכסף (לענין זה):\",1,0],[8,385,2,1,\"כיצד בשטר וכו'. שם (דף ט\\\"ז) שטר אמה העבריה מי כותבו רב הונא אמר אדון כותבו רב חסדא אמר אב כותבו ופסק כרב חסדא דאב צריך לכתוב בתי מכורה לך והוא הדין לעבד דלא ידעינן דעבד נקנה בשטר אלא מדכתיב אחיך העברי או העבריה הוקשו זה לזה ובאמה כתיב לא תצא כצאת העבדים ודרשינן אבל נקנית היא כקניין העבדים ולמדנו שקניינה יהיה בשטר ולא בחזקה מדכתיב אם אחרת יקח לו הקישה הכתוב לאחרת כלומר אשה הנקנית בשטר מכל מקום עיקר למידת קניינות בשטר הוי מעבד כנעני וכשם שהוא או רבו המוכרו כותבין השטר כן אמה העבריה אב כותבו והוא הדין לעבד עברי כמו שכתבתי:\",2,0],[8,385,2,2,\"מכרוהו ב\\\"ד עובד שש שנים. כלומר ולא יותר כמו שיתבאר בסמוך.\",1,0],[8,385,2,2,\"ומה שכתב מיום מכירתו במכילתא ובשביעית שביעית למכירה או אינו אלא לשנים ת\\\"ל שש שנים יעבוד הוי שביעית למכירה ולא שביעית לשנים ובפרק קמא דקידושין ירושלמי נמי שביעית של מכירה לא שביעית של עולם.\",2,0],[8,385,2,2,\"ומה שכתב ואם פגעה בו שנת השמטה כן נלמד ממה שכתבתי בסמוך בשם מכילתא והירושלמי שביעית למכירה ולא שביעית של עולם. ורבינו כתב בפירוש המשנה שזהו למאמר הכתוב שש שנים יעבוד ובשביעית דמשמע שאף בשביעית יעבוד.\",3,0],[8,385,2,2,\"ומ\\\"ש אבל אם פגעה בו שנת יובל וכו'. שם ושב אל משפחתו וכו' אמר ראב\\\"י במה הכתוב מדבר במכרוהו ב\\\"ד שתים ושלש שנים לפני היובל שהיובל מוציאו:\",4,0],[8,385,2,3,\"המוכר עצמו וכו'. גם זה בברייתא שם (דף י\\\"ד ע\\\"ב) המוכר עצמו נמכר לשש ויתר על שש מכרוהו בית דין אינו נמכר אלא לשש ומפרש טעמא בגמרא דכתיב ועבדך שש שנים וגו' ולא המוכר עצמו ואף על גב דרבי אליעזר פליג התם ואמר זה וזה אינו נמכר אלא לשש פסק כת\\\"ק:\",1,0],[8,385,2,3,\"הרי שמכר עצמו לעשר שנים וכו'. גם זה שם (דף ט\\\"ו) אמר רבי אליעזר בן יעקב ושב אל משפחתו במה הכתוב מדבר אם במוכר עצמו הרי כבר אמור כלומר דכתיב לעיל מיניה עד שנת היובל יעבוד עמך וכו' אלא במכרוהו בית דין שתים ושלש שנים לפני היובל שהיובל מוציאו:\",2,0],[8,385,2,4,\"אחד המוכר עצמו וכו'. שם (דף ט\\\"ז:) תניא מנין לבורח שחייב להשלים ת\\\"ל שש שנים יעבוד ומברייתא אחרת משמע שאינו חייב להשלים ואוקמה רב ששת כגון שברח ופגע בו יובל ובסמ\\\"ג כתב ואם פגע בו יובל יצא בד\\\"א בחלה אבל בברח אין היובל מוציאו כדאיתא בירושלמי דקידושין מאי טעמא זה ברשותו וזה אינו ברשותו עכ\\\"ל ויש לתמוה למה דחה גמ' דידן מפני הירושלמי:\",1,0],[8,385,2,5,\"חלה בין שחלה שנה אחר שנה וכו'. ברייתא שם יכול אפילו חלה חייב להשלים ת\\\"ל ובשביעית יצא כלומר יצא מכל מקום ורמינן עלה מדתניא חלה שלש ועבד שלש אינו חייב להשלים חלה כל שש חייב להשלים אמר רב ששת בעושה מעשה מחט כלומר הא דתניא דאינו חייב להשלים היינו בעושה מעשה מחט בחליו שהוא מעשה קל ומדהוה מצי לתרוצי כאן שחלה למקוטעים כאן שחלה רצופים משמע ליה לרבינו דלא שני לן והדר אמרינן הא גופא קשיא אמרת חלה שלש ועבד שלש אינו חייב להשלים הא ארבע חייב להשלים אימא סיפא חלה כל שש חייב להשלים הא ארבע אין חייב להשלים הכי קאמר חלה ד' נעשה כמי שחלה כל שש וחייב להשלים.\",1,0],[8,385,2,5,\"ומ\\\"ש ואם פגע בו יובל יצא. למדו בקל וחומר מבורח וכתבו התוספות שי\\\"א שדין השכיר כדין עבד עברי לענין אם חלה אבל לא נראה להם כן אלא שהשכיר חייב להשלים כל ימי החולי:\",2,0],[8,385,2,6,\"המוכר עצמו לעכו\\\"ם וכו'. שם (דף ט\\\"ו ע\\\"ב) אם לא יגאל באלה כלומר בקרובים דכתיב לעיל מיניה או דודו או בן דודו וגו' רבי אומר באלה הוא נגאל ואין נגאל בשש ואע\\\"ג דר\\\"י הגלילי ורבי עקיבא פליגי ארבי ומפקי להאי באלה לאם פדאוהו קרובים או אחרים אם משתעבד להם או לא פסק רבינו כמותו משום דבתר הכי אמילתייהו דרבי יוסי ורבי עקיבא אמר רבי חייא בר אבא אמר ר' יוחנן זו דברי רבי יוסי הגלילי ורבי עקיבא אבל חכמים אומרים הכל לשחרור מאן חכמים רבי היא דמפיק להאי באלה לדרשא אחרינא כלומר לומר באלה הוא נגאל ואינו נגאל בשש ומדאתא ר' חייא במסקנא דמילתא למימר זו דברי ר\\\"י וכו' ואפקיה לרבי בלשון חכמים אלמא הלכתא כוותיה ס\\\"ל:\",1,0],[8,385,2,7,\"ומ\\\"ש וקרוב קרוב קודם. שם מימרא דרב נחמן בר יצחק ובתורת כהנים יליף לה מקרא.\",1,0],[8,385,2,7,\"ומ\\\"ש ובית דין כופין את קרוביו וכו'. שם ובכל וגו' גאולה תתנו לרבות בתים ועבד עברי ואוקמוה בעבד עברי הנמכר לעכו\\\"ם ואמרינן התם דאף על גב דהא כתיב בתריה או דודו או בן דודו וגו' איצטריך האי קרא לקובעו חובה.\",2,0],[8,385,2,7,\"ומ״ש לא פדאוהו קרוביו וכו' מצוה על כל אדם מישראל לפדותו. בגיטין פרק השולח (גיטין דף מ״ו ע״ב) תנן המוכר את עצמו ואת בניו לעכו״ם אין פודין אותם ואמרינן בגמ' והוא שמכרן ושנה ושילש משמע הא קודם לכן מצוה לפדותו.\",3,0],[8,385,2,7,\"ומ\\\"ש ובין שפדאוהו קרובים וכו'. כרבי דאמר התם הכל לשחרור כלומר בין קרובים בין שאר כל אדם ופסק רבינו כמותו מהטעם שכתבתי למעלה:\",4,0],[8,385,2,7,\"ויש לו ללוות ולגאול את עצמו וכו'. תמהני על פסק זה ששם בגמרא (דף כ' ע\\\"ב) אמרינן דבעא ר\\\"ה מרב ששת עבד עברי הנמכר לעכו\\\"ם נגאל לחצאין או לא ופשט ליה דאינו נגאל ולקמן בגמרא אמרינן עבד עברי הנמכר לעכו\\\"ם יוכיח שיפה כחו ליגאל בשנה שנייה ואין לוה וגואל לחצאין ולא נראה לי הכרח אחר מאותה הסוגיא אלא שאחר שפשט רב ששת אמר אביי אם תמצא לומר נגאל לחצאין משכחת לה לקולא ולחומרא אלמא אביי דהוא בתראה לא ס\\\"ל כפשיטותיה דרב ששת ואכתי קשיא שאין זה כדאי לדחות פשיטותיה של רב ששת ומצאתי לסמ\\\"ג שכתב הנמכר לעכו\\\"ם מסיק שם רב ששת שאין לוה וגואל וגם אינו נגאל לחצאין ויש לתמוה שלא שת לבו להביא דברי רבינו כמנהגו:\",5,0],[8,385,2,7,\"אבל הנמכר לישראל אין הקרובים פודים אותו. שם (דף כ\\\"א) עבד עברי הנמכר לישראל נגאל לקרובים או לא אליבא דרבי לא תיבעי לך דאמר ומה מי שאינו נגאל באלה אלמא לא מיפרק כלומר דאמר בברייתא שכתבתי לעיל שיכול ומה מי שאינו נגאל באלה נגאל בשש מי שנגאל באלה אינו דין שיגאל בשש ת\\\"ל באלה באלה הוא נגאל ואינו נגאל בשש למדנו דאליבא דרבי עבד עברי הנמכר לישראל אינו נגאל לקרובים ומפרש רבינו דהיינו שאין הקרובים חייבים לפדותו וכבר פסק רבינו הלכה כרבי.\",6,0],[8,385,2,7,\"ומ\\\"ש ואינו לוה וגואל ואינו גואל לחצאין:\",7,0],[8,385,2,8,\"אחד המוכר עצמו וכו'. כך שנינו שם במשנה וקונה את עצמו בשנים וביובל ובגרעון כסף והדרכים הללו נוהגים בכל מיני עבד עברי דסתם שנינו אותם חוץ מיוצא בשש שנים שפירש רבינו דלא הוי בנמכר לעכו\\\"ם:\",1,0],[8,385,2,8,\"ונותן הנשאר כסף או שוה כסף ויוצא. שם וקונה את עצמו בכסף תנא בכסף ובשוה כסף.\",2,0],[8,385,2,8,\"ומ\\\"ש וכן הנמכר לעכו\\\"ם מחשב הדמים וכו'. מבואר בכתוב:\",3,0],[8,385,2,8,\"ומ\\\"ש ומשיב השאר כסף לא תבואה ולא כלים וכו'. בת\\\"כ בכסף הוא נגאל ואינו נגאל לא בתבואה ולא בכלים ובירושלמי פרק קמא דקידושין והיה כסף ממכרו בכסף הוא נגאל ואינו נגאל לא בתבואה ולא בכלים בכל אתר את עביד שוה כסף ככסף והכא לית את עביד שוה כסף ככסף אמר ר' אבא מרי שניא היא ששנה עליו הכתוב כסף מכסף:\",4,0],[8,385,2,9,\"כל עבד עברי או עבריה שיצא בגרעון כסף וכו'. ברייתא בפרק קמא דקידושין עלה כ':\",1,0],[8,385,2,10,\"הנמכר לעכו\\\"ם וכו' פעמים יהיה להקל ופעמים להחמיר וכו'. שם (דף כ' ע\\\"ב) אמר אביי אם תמצא לומר נגאל לחצאין משכחת לה לקולא ולחומרא וכמו שכתב רבינו:\",1,0],[8,385,2,11,\"הרב שמחל לעבד וכו'. שם אמתניתין הקונה עצמו בשטר אמרו בגמרא (דף ט\\\"ז) ה\\\"ד אילימא שיחרור לימא ליה באפי תרי או באפי בי דינא זיל אמר רבא זאת אומרת עבד עברי גופו קנוי והרב שמחל על גרעונו אין גרעונו מחול:\",1,0],[8,385,2,12,\"אדון שמת אם הניח בן זכר וכו'. ברייתא שם (דף י\\\"ז ע\\\"ב) עבד עברי עובד את הבן ואינו עובד את הבת ובברייתא אחרת אמרו דאינו עובד את האח וכתב רבי לוי בן גרשון בפרשת משפטים שיתבאר מזה שאין האדון שליט למכור עבדו או לתתו לאחר:\",1,0],[8,385,2,12,\"והנמכר לגר צדק או לעכו״ם וכו'. דין העכו״ם מפורש באותה ברייתא הנמכר לעכו״ם אינו עובד לא [את] הבן ולא את הבת ודין הגר צדק מפורש במציעא פרק איזהו נשך (בבא מציעא דף ע״א) גר קונה עבד עברי ודינו כעכו״ם שאינו עובד לא את הבן ולא את הבת ולפי זה לא שנא אם הבן הורתו ולידתו שלא בקדושה או בקדושה ואפשר דהיינו טעמא שכיון שלא מצינו שיוכל לימכר לגר צדק אלא מדכתיב ונמכר לגר תושב הנמכר לגר הרי דינו כעכו״ם כשם שהעכו״ם אינו עובד לבנו כן אינו עובד לבן הגר ותפס רבינו גר צדק וכ״ש לגר תושב ותפס עכו״ם לומר שבענין זה שוה הוא לעכו״ם ואפשר עוד שהגר תושב בכלל עכו״ם הוא אבל קשה שהיה לנו להשוותו ג״כ לגאולת קרובים וללוה וגואל וגואל לחצאין ואפשר דהתם היינו טעמא כדי שלא יטמע בין העכו״ם מה שאין כן בגר צדק והא דאינו עובד את הבן לאו משום שלא יטמע הוא אלא גזירה היא דהא נרצע אינו עובד את הבן אע״ג שלא שייך ביה שמא יטמע הילכך יש לנו לומר שהוקשו לענין זה:\",2,0],[8,385,2,12,\"מצוה לומר לו צא בשעת יציאתו וכו': אפי' חלה והוציא עליו רבו הוצאות וכו':\",3,0],[8,385,3,1,\"כל עבד עברי הרי האדון חייב וכו'. זה שחייב לזון אשתו ובניו פ\\\"ק דקידושין (דף כ\\\"ב) ובמכילתא נמי דריש הכי וקאמר תו יכול יהא חייב במזונות ארוסה ושומרת יבם תלמוד לומר אשתו להוציא שומרת יבם שאינה אשתו עמו להוציא ארוסה שאינה עמו:\",1,0],[8,385,3,1,\"אבל אם היתה מאיסורי לאוין וכו'. יתבאר בסמוך:\",2,0],[8,385,3,1,\"במכרוהו בית דין נאמר וכו'. פ\\\"ק דקידושין (דף כ\\\"ב) ויצא מעמך הוא ובניו אם הוא נמכר בניו [ובנותיו מי] נמכרים מכאן שרבו חייב במזונות בניו כיוצא בדבר אתה אומר אם בעל אשה הוא וכו' אם הוא נמכר אשתו מי נמכרת מכאן שרבו חייב במזונות אשתו:\",3,0],[8,385,3,1,\"אחד אשה ובנים שהיו לו בשעת מכירה וכו' עד וכל שזוכה הבעל באשתו זוכה זה. הכל במכילתא דר\\\"ש כתבה הרמב\\\"ן בפרשת משפטים ז\\\"ל אם בעל אשה הוא מה הוא חייב במזונותיו אף אשתו ובניו חייב במזונותיהם עדיין אני אומר אשה ובנים שהיו לו עד שלא לקחו רבו רבו חייב במזונותיהן וכו' ת\\\"ל אם בעל אשה הוא וכו' שתי נשים כאן אחת עד שלא לקחו רבו ואחת משלקחו רבו יכול אפילו היתה אלמנה לכ\\\"ג גרושה וחלוצה לכהן הדיוט ת\\\"ל ויצאה אשתו עמו אשה שראויה להתקיים עמו יצאה זו וכו' יכול אפילו נשא אשה שלא מדעת רבו תלמוד לומר הוא מה הוא מדעת רבו אף אשתו מדעת רבו יכול יהא מעשה בניו ובנותיו של רבו ת\\\"ל הוא מעשה ידיו של רבו ואין מעשה בניו ובנותיו של רבו עד כאן בברייתא ורבינו תפס הברייתא כפשטה אף על פי שהרמב\\\"ן פירש בה פירוש אחר כמבואר בפירוש התורה שלו. ומכל מקום לדברי רבינו צ\\\"ע אם חייב במזונות בניו כשהם יותר מבני שש או לא. עוד צריך לדקדק שכתב בראש הפרק אבל אם היתה מאיסורי לאוין אפילו שנייה אינו חייב במזונותיה ומנא לן דשנייה נמי דהא לא הזכירו בברייתא אלא חייבי לאוין לחוד ועוד שכיון שמעמו דרשינן אשה הראויה לו לא ממעט אלא איסורי תורה אבל איסורי סופרים משמע שלא נתכוונה התורה למעט ואפשר דכיון דכל מילי דרבנן אסמכינהו אלאו דלא תסור ועוד דשניות ילפינן להו מושמרתם את משמרתי שפיר איכא למימר דמעטינהו קרא. ודע שאף על פי שבברייתא אמרו יכול יהא מעשה בניו ובנותיו של רבו וכו' ולא הזכירו מעשה ידי אשתו הוא הדין לאשתו אלא דחדא מינייהו נקט תדע מדקתני סיפא ת\\\"ל הוא דמשמע דוקא הוא מעשה ידיו לרבו אבל לא אשתו ולא בניו:\",4,0],[8,385,3,2,\"אף על פי שהאדון וכו'. אפשר שלמד כן מהברייתא שכתבתי לעיל אם הוא נמכר אשתו ובניו מי נמכרים אלמא דאינם משועבדים לו כלל:\",1,0],[8,385,3,3,\"מי שמכרוהו בית דין וכו'. בפירקא קמא דקידושין (דף ט\\\"ו) ובמכילתא אם אדוניו יתן לו אשה רשות וזהו שכתב\",1,0],[8,385,3,3,\"רבינו יש לרבו כלומר הרשות ביד רבו.\",2,0],[8,385,3,3,\"ומה שכתב בין בנו של אדון אם מת אביו הרי זה נותן לו שפחה. ומה שכתב וכופהו על זה. בפירקא קמא דקידושין (דף י\\\"ד ע\\\"ב) המוכר את עצמו אין רבו מוסר לו שפחה כנענית מכרוהו ב\\\"ד רבו מוסר לו שפחה כנענית רבי אליעזר אומר זה וזה רבו מוסר לו שפחה כנענית וכו' מאי טעמא דתנא קמא מיעט רחמנא גבי מכרוהו בית דין אם אדוניו יתן לו אשה לו ולא למוכר עצמו ואידך לו בעל כרחו ואידך מכי משנה שכר שכיר נפקא דתניא כי משנה שכר שכיר עבדך שכיר אינו עובד אלא ביום עבד עברי בין ביום בין בלילה וכי תעלה על דעתך שעבד עברי עובד בין ביום בין בלילה והלא נאמר כי טוב לו עמך וכו' אמר רבי יצחק מכאן שרבו מוסר לו שפחה כנענית:\",3,0],[8,385,3,3,\"והמוכר עצמו אסור בשפחה כנענית וכו'. ברייתא פ\\\"ק דקידושין (דף י\\\"ד) המוכר עצמו נמכר לשש ויתר על שש מכרוהו ב\\\"ד אינו נמכר אלא לשש וכו' המוכר עצמו אין רבו מוסר לו שפחה כנענית מכרוהו ב\\\"ד רבו מוסר לו שפחה כנענית ומפרשינן טעמא בגמ' דאמר קרא אם אדוניו יתן לו אשה לו ולא למוכר עצמו:\",4,0],[8,385,3,4,\"אין עבד עברי מותר בשפחה כנענית וכו'. ברייתא פ\\\"ק דקידושין (דף כ') אם בגפו יבא בגפו יצא ר' אליעזר בן יעקב אומר יחידי נכנס יחידי יצא ואמר רב נחמן בר יצחק דה\\\"ק יש לו אשה ובנים רבו מוסר לו שפחה כנענית אין לו אשה ובנים אין רבו מוסר לו שפחה כנענית ומשנת ראב\\\"י קב ונקי ועוד דרב נחמן בר יצחק פירש דבריו אלמא כוותיה סבירא ליה.\",1,0],[8,385,3,4,\"ומ\\\"ש אפילו היה הנמכר כהן וכו'. שם (דף כ\\\"א) איבעיא להו עבד עברי כהן מהו שימסור לו רבו שפחה כנענית וכו' רב אמר מותר ושמואל אמר אסור וידוע דהלכתא כרב באיסורי ועוד שרב נחמן הכריע שם שא\\\"א לומר דאסור:\",2,0],[8,385,3,5,\"אם היו לו אשה ובנים וכו' ואינו יכול ליתן לו שתי שפחות וכו'. ומ\\\"ש ולא ליתן שפחה אחת לשני עבדיו העברים. במכילתא ר\\\"ע אומר אם אדוניו יתן לו אשה המיוחדת לו שלא תהא כשפחת הפקר:\",1,0],[8,385,3,5,\"נרצע שמסר לו רבו וכו'. בפרק המניח (דף כ\\\"ג):\",2,0],[8,385,3,6,\"המוכר עצמו אינו נרצע וכו'. ברייתא פירקא קמא דקידושין (דף י\\\"ד ע\\\"ב) ופסק כתנא קמא דאמר המוכר עצמו אינו נרצע מכרוהו בית דין נרצע ויליף לה מדכתיב ורצע אדוניו את אזנו אזנו שלו ולא של מוכר עצמו:\",1,0],[8,385,3,7,\"אף על פי שהניח בן וכו'. ברייתא שם:\",1,0],[8,385,3,8,\"עבד עברי כהן אינו נרצע וכו'. ברייתא שם (דף כ״א) ופרק על אלו מומין (בכורות דף ל״ז):\",1,0],[8,385,3,8,\"ואינו שב לשררה שהיה בה. פלוגתא דר״מ ור' יהודה במכות סוף פרק אלו הן הגולין (מכות דף י״ג) ופסק כרבי יהודה:\",2,0],[8,385,3,9,\"מביאו לב\\\"ד של ג'. במכילתא והגישו אדוניו אל האלהים אצל הדיינים שימלך במוכריו.\",1,0],[8,385,3,9,\"ומ\\\"ש לסוף שש. יתבאר בסמוך:\",2,0],[8,385,3,9,\"ומ\\\"ש אל הדלת או אל המזוזה כשהם עומדים בבניין. יתבאר בסמוך.\",3,0],[8,385,3,9,\"ומ\\\"ש בין דלת ומזוזה של אדון וכו': ונוקב את אזנו הימנית. במכילתא ובפ\\\"ק דקידושין (דף ט\\\"ו) נאמר כאן אזן ונאמר להלן אזן מה להלן בימין אף כאן בימין.\",4,0],[8,385,3,9,\"ומ\\\"ש בגופה של אזן. פירוש בתנוך ולא בבשר וזה מחלוקת בפ\\\"ק דקידושין ופסק כחכמים.\",5,0],[8,385,3,9,\"ומ\\\"ש במרצע של מתכת. פירוש בכל דבר שהוא של מתכת ובפ\\\"ק דקידושין (דף כ\\\"א ע\\\"ב) אמרינן דאיכא מאן דאמר דבכל דבר שהוא נוקב רוצעין ורבי סבר דדוקא בדבר של מתכת ומשום דכתב קרא ולקחת דהיינו כלל במרצע פרט באזנו ובדלת חזר וכלל אנו דנין כעין הפרט מה הפרט של מתכת אף כל של מתכת אף אם אינו מרצע וידוע דהלכה כרבי מחבירו ובמכילתא סתם כרבי:\",6,0],[8,385,3,9,\"עד שיגיע לדלת וכו'. פ\\\"ק דקידושין (דף כ\\\"ב) ת\\\"ר אילו נאמר אזנו בדלת הייתי אומר וכו' ירצענה לאזן מאבראי ויניחנה על הדלת וידקור כנגד אזנו בדלת ת\\\"ל באזנו ובדלת הא כיצד דוקר והולך עד שמגיע אצל דלת ובמכילתא ונתת באזנו ובדלת בדלת אתה נותן אבל אי אתה נותן במזוזה או יעבור באזנו ובדלת תלמוד לומר ורצע אדוניו את אזנו באזנו אתה מעביר ואי אתה מעביר בדלת:\",7,0],[8,385,3,9,\"ולא נאמר מזוזה אלא שיהיה עומד וכו': ומה מזוזה כשהיא עומדת וכו'. בפירקא קמא דקידושין שם שומע אני בין עקורה בין שאינה עקורה תלמוד לומר מזוזה מה מזוזה מעומד כלומר דבלאו הכי לא מיקרי מזוזה אף דלת נמי מעומד:\",8,0],[8,385,3,9,\"האדון הוא שרוצע וכו'. במכילתא ורצע אדוניו למה נאמר לפי שמצינו בכ\\\"מ ששלוחו של אדם כמותו אבל כאן הוא ולא שלוחו:\",9,0],[8,385,3,9,\"ואין רוצעין שני עבדים וכו'. פירקא קמא דסוטה עלה ח':\",10,0],[8,385,3,10,\"ואם אמר יאמר העבד וכו' עד הרי זה כאומר אחר שש. ברייתא פ\\\"ק דקידושין (דף כ\\\"ב) תניא בסיפרי פ' ראה על כן אנכי מצוך הדבר הזה היום ביום רוצעין ולא בלילה ונרמז בדברי רבינו שכתב שנשאר מן היום שוה פרוטה:\",1,0],[8,385,3,11,\"היתה לעבד וכו' עד שיהיו שניהם בטובה. ברייתא פ\\\"ק דקידושין (דף כ\\\"ב) כלשון רבינו:\",1,0],[8,385,3,11,\"ומ\\\"ש שניהם חולים. בעיא שם עמך בעינן והא איכא כלומר שהרי הוא שרוי כמו שרבו שרוי בין טוב ובין רע או דילמא כי טוב לו עמך בעינן והא ליכא תיקו ופסק רבינו להקל על העבד ולא יוכל להשתעבד בו אף אם העבד רוצה:\",2,0],[8,385,3,12,\"מה בין מוכר עצמו וכו' עד מעניקין לו. ברייתא פ\\\"ק דקידושין (דף י\\\"ד ע\\\"ב) כתבתי רובה למעלה וטעמיה ואחזור לכתבה כאן הטעם שמוכר עצמו אינו נרצע למאמר הכתוב בעבד שמכרוהו ב\\\"ד ורצע אדוניו את אזנו אזנו ולא אזנו של מוכר עצמו ואמר הכתוב אם אדוניו יתן לו אשה לו ולא למוכר עצמו ואמר עוד ועבדך שש שנים זה ולא מוכר את עצמו שיכול לימכר יותר על שש ואמר עוד הענק תעניק לו ולא למוכר את עצמו וכבר כתבתי דר\\\"א פליג אכל הני ואומר ששניהם שוים וידוע דהלכה כת\\\"ק.\",1,0],[8,385,3,12,\"ומ\\\"ש מכרוהו בית דין אינו נמכר אלא לישראל וכו'. בסיפרי מנין כשבית דין מוכרין אותו אינו נמכר אלא לך תלמוד לומר כי ימכר לך אחיך העברי:\",2,0],[8,385,3,13,\"מפי השמועה למדו שאין האשה נרצעת וכו'. בסיפרי ואף לאמתך תעשה כן להענקה יכול אף לרציעה ת\\\"ל ואם אמור יאמר העבד העבד ולא אמה:\",1,0],[8,385,3,14,\"כל המשלח עבדו ואמתו ריקם עובר בל\\\"ת. פשוט הוא.\",1,0],[8,385,3,14,\"ומה שכתב והרי הכתוב נתקו לעשה. טעמו משום דהוי כמו שילוח הקן דכתיב לא תקח האם על הבנים שלח תשלח את האם ותנן בסוף חולין דלחכמים הוי לאו שניתק לעשה:\",2,0],[8,385,3,14,\"אחד היוצא בסוף שש וכו' עד ואח\\\"כ יצא. ברייתא פ\\\"ק דקידושין (דף י\\\"ז) וכת\\\"ק ופירש הטעם בגמרא כדברי רבינו:\",3,0],[8,385,3,14,\"העניק תעניק לו וכו'. ברייתא שם יכול לא יהו מעניקין אלא מצאן גרן ויקב מנין לרבות כל דבר ת\\\"ל אשר ברכך וגו' א\\\"כ מה ת\\\"ל צאן גרן ויקב לומר לך מה צאן גרן ויקב מיוחדים שישנן בכלל ברכה אף כל שישנן בכלל ברכה יצאו כספים דברי ר\\\"ש ראב\\\"י אומר יצאו פרדות כלומר וכל שכן כספים ור\\\"ש פרדות משבחן בגופייהו ופסק רבינו כר\\\"ש דמסתבר טעמיה:\",4,0],[8,385,3,14,\"וכמה נותן לו. שם פלוגתא דר\\\"מ אמר ט\\\"ו סלעים ור\\\"ש חמשים ור\\\"י אמר שלשים ופסק כר\\\"י דה\\\"ל ר\\\"ש ור\\\"י תרי לגבי ר\\\"מ דלתרוייהו בעי טפי מט\\\"ו ולענין חמשים דאמר ר\\\"ש ה\\\"ל ר\\\"מ ור\\\"י תרי לגבי ר\\\"ש.\",5,0],[8,385,3,14,\"וכתב בין ממין אחד וכו'. לאפוקי מר\\\"מ שדקדקו בגמרא מדבריו שצריך ליתן לו מכל המינין ור\\\"י שאין לדקדק כן מדבריו משמע דבין ממין אחד בין ממינין הרבה:\",6,0],[8,385,3,14,\"בין שנתברך הבית וכו'. ברייתא שם וכת\\\"ק:\",7,0],[8,385,3,15,\"אם פגע בו יובל וכו'. ברייתא שם:\",1,0],[8,385,3,15,\"ענק ע\\\"ע לעצמו וכו'. ברייתא שם.\",2,0],[8,385,3,15,\"וענק אמה וכו'. ג\\\"ז שם ברייתא:\",3,0],[8,385,3,15,\"ואם מת אביה וכו'. שם תני חדא ענק אמה העבריה לעצמה ותני חדא ענק אמה העבריה לאביה וכו' ל\\\"ק הא דאיתיה לאב הא דליתיה לאב כו' לעצמה ולא לאחין לפי שאין אדם מוריש זכות בתו לבנו. ויש לדקדק על מ\\\"ש ואם מת האב קודם שיבא לידו משמע שאע\\\"פ שבא לידה אינו מורישו ובריש נערה שנתפתתה משמע שהוא מורישו וצ\\\"ל דבא לידה כבא לידו דמי:\",4,0],[8,385,4,1,\"אמה העבריה היא הקטנה שמכרה וכו'. בפרק אלו נערות (כתובות דף מ' ע\\\"ב) תני קטנה מבת יום אחד עד שתביא שתי שערות יש לה מכר וכו' משתביא שתי שערות וכו' אין לה מכר ובריש פרק ט' דערכין (דף כ\\\"ט ע\\\"ב) מייתי לה מקל וחומר השתא מכורה כבר יוצאה [בסימנין] שאינה מכורה על אחת כמה וכמה שאין יכול למכרה וקרוב לזה איתא במכילתא:\",1,0],[8,385,4,1,\"אף הקטנה שהיא איילונית וכו'. בריש פירקא קמא דקידושין (דף ד') מייתי לה מדכתב רחמנא ויצאה חנם וכו' ודרשינן ויצאה חנם אלו ימי נערות אין כסף אלו ימי בגרות ופריך דלכתוב רחמנא נערות ותו לא איצטריך למכתב בגרות דכי נפקא לה מנערות בגרות מאי בעיא גביה ואמרינן דאילו לא כתב אלא נערות ה\\\"א דאתיא סימני נערות הוו זבינה זבינא דלא אתיא סימני נערות לא הוו זבינה זבינא לכך איצטריך לומר דיש שיוצאה בבגרות אף על פי שאין לה נערות והיינו אילונית וממילא שמעינן דזבינה זביני:\",2,0],[8,385,4,1,\"אבל הטומטום. בתוספתא דבכורים פרק בתרא:\",3,0],[8,385,4,2,\"אין האב רשאי למכור וכו'. פרק קמא דקידושין (דף כ'.) כמה קשה אבקה של שביעית אדם נושא ונותן בפירות שביעית לסוף מוכר מטלטליו ושדותיו ואח\\\"כ מוכר בתו ואמרינן התם דיוזיף ברביתא ולא ליזבון ברתיה משמע מכאן דאין לו למכרה עד בלתי השאיר לו שריד:\",1,0],[8,385,4,2,\"ואעפ\\\"כ כופין את האב וכו'. שם (דף י\\\"ח) ומפדין אותה בעל כרחו ואסיקנא דהיינו בע\\\"כ דאב ואיכא למידק דהא פריך לאביי א\\\"ה ע\\\"ע נמי נכפינהו לגבי משפחה משום פגם משפחה הדר אזיל ומזבין נפשיה ה\\\"נ הדר אזיל ומזבין לה הא קתני אינה נמכרת ונשנית ומנו ר\\\"ש היא ומאחר שפסק רבינו בסוף פרק זה דמוכר ושונה כתנא קמא הוה ליה למיפסק דאין מפדין אותה בע\\\"כ ואפשר שהוא ז\\\"ל סובר דלא דמי ע\\\"ע לאמה דבע\\\"ע איכא למיחש דאזיל ומזבין נפשיה ואכיל להו לדמי על דעת שבני משפחה יפדוהו והדר אזיל ומזבין נפשיה כמה פעמים על סמך זה ונמצא מפסיד לגבי משפחה אבל גבי אמה שלאב המוכר אנו כופין שיפדנה כי כייפינן ליה אפילו מאה פעמים ליכא הפסד במילתא א\\\"נ דגבי אמה כיון דאין האב רשאי למוכרה אלא א\\\"כ העני ולא נשאר לו כלום ליכא למימר הדר מזבין לה דאי אית ליה ממונא לא מצי מזבין לה ואי לית ליה ליזבין וליזבין ובדין דהוה מצי לשנויי ליה דשאני עבד עברי מאמה העבריה אלא דאהדר ליה לפום שיטתיה דמשוה להו ועי\\\"ל דניחא ליה לאוקומיה כר\\\"ש משום דסיפא דברייתא אתי כוותיה אבל אה\\\"נ דלתנא קמא דר' שמעון נמי מפדין אותה בע\\\"כ דאב:\",2,0],[8,385,4,2,\"ברח האב וכו' עובדת עד שתצא. כלומר באחד מהדרכים שנזכיר אבל אין כופין את הקרובים לפדותה שכבר נתבאר רפ\\\"ג שרבינו פוסק כרבי דאמר דנמכר לישראל אין כופין לקרובים לפדותו:\",3,0],[8,385,4,3,\"אמה העבריה נקנית וכו'. משנה פ\\\"ק דקידושין (דף י\\\"ד ע\\\"ב) ע\\\"ע נקנה בכסף ובשטר ובגמרא (דף י\\\"ו) והפדה מלמד שנקנית בכסף ושוה כסף ככסף כמ\\\"ש רפ\\\"ב ושטר ילפינן לה מדכתיב לא תצא כצאת העבדים אבל נקנית בקניין העבדים ולמדנו שיהיה בשטר ולא בחזקה לפי שכתוב אם אחרת הקישה הכתוב לאחרת הנקנית בשטר:\",1,0],[8,385,4,3,\"ואינה נקנית בפרוטה וכו'. קשה דהא לא ילפינן דנמכר לישראל נקנה בכסף אלא מדכתיב והפדה והוקש עברי לעבריה ומהאי ילפינן נמי גרעון כסף וכיון שכן היה לנו לומר דגם נמכר לישראל לא יקנה בפרוטה כמו אמה ואיני רואה דבר מתיישב בזה רק ששאלו בגמרא (דף י\\\"ד ע\\\"ב) ע\\\"ע נקנה בכסף מנ\\\"ל אמר קרא מכסף מקנתו אשכחן ע\\\"ע הנמכר לעכו\\\"ם וכו' נמכר לישראל מנ\\\"ל אמר קרא והפדה והוקש עברי לעבריה מדכתיב כי ימכר לך אחיך העברי או העבריה אשכחן מכרוהו ב\\\"ד מוכר עצמו מנ\\\"ל יליף שכיר שכיר הניחא למאן דיליף וכו' אלא למאן דלא יליף שכיר שכיר מאי איכא למימר אמר קרא וכי תשיג וי\\\"ו מוסיף על ענין ראשון וילמד עליון מתחתון כלומר וכי תשיג כתוב בנמכר לעכו\\\"ם ולעיל מיניה כתיב נמכר לישראל ואף ע\\\"ג דבגמרא לא אשכחן בתר הכי תנא דיליף שכיר שכיר אלא כולהו ילפי מ\\\"מ מדכתיב וכי תשיג מצינן למילף דכיון דאיכא כסף דהיינו פרוטה נקנה בכך:\",2,0],[8,385,4,3,\"ושטר אמה העבריה האב כותבו. כבר כתבתי רפ\\\"ב שהוא מחלוקת רב הונא ורב חסדא ופסק כרב חסדא דיליף דנקנית בשטר מלא תצא כצאת העבדים וא\\\"כ כשם שמוכר העבד או הקרקע כותב השטר ואומר שדי או עבדי מכור לך או קנוי לך ואינו נכתב בלשון הקונה לומר שדך מכורה לי [כך במוכר בתו] ומה שלמדנו מאם אחרת הקישה הכתוב אינו אלא גילוי בעלמא ובירושלמי פרק קמא דקידושין סדר מכירה כך הוא אני פלוני מכרתי בתי לפלוני:\",3,0],[8,385,4,4,\"אמה העבריה עובדת שש וכו'. משנה פרק קמא דקידושין (דף י\\\"ד ע\\\"ב) עבד עברי נקנה בכסף ובשטר וקונה את עצמו בשנים וביובל ובגרעון כסף יתירה עליו אמה העבריה שקונה את עצמה בסימנין כלומר יתירה עליו שקונה את עצמה בכל אלו ובסימנין:\",1,0],[8,385,4,4,\"מת האדון אף על פי שהניח בן וכו'. ברייתא שם (דף י\\\"ז ע\\\"ב) והקשו והרי דרשנו ואף לאמתך להענק כמוזכר בדברי רבינו פ\\\"ג ותירצו א\\\"כ נכתוב רחמנא ואף לאמתך מאי תעשה ש\\\"מ תרתי:\",2,0],[8,385,4,4,\"וכן מגרעת מפדיונה וכו'. זה פשוט דעיקר גרעון בה כתיב דמדכתיב והפדה דמשמע שאף האדון מסייע בפדיונה למדנו שקונה את עצמה בגרעון כסף שהוא מנכה לשני עבודתה המגיע לפי דמי קניינה. ומ\\\"ש\",3,0],[8,385,4,4,\"רבינו וכן קאי למה שכתב שיוצאה בתחלת שבע וביובל ובמיתת האדון:\",4,0],[8,385,4,4,\"ואם כתב לה שטר שחרור וכו'. ברייתא שם בעבד עברי כתבתיה למעלה וכיון שהוקשו עברי לעבריה למדנו שגם היא קונה את עצמה בשטר:\",5,0],[8,385,4,5,\"יתירה עליו אמה העבריה וכו'. משנה שם (דף ד') ובריש מכילתין יליף לה מדכתיב ויצאה חנם אלו ימי נערות:\",1,0],[8,385,4,5,\"היתה הבת אילונית וכו'. בריש קידושין אמרו דאע\\\"ג דלא הוה קרא אילו הוה ס\\\"ד דנמכרת ה\\\"א דנפקא מק\\\"ו ומה סימנין שאין מוציאין מרשות אב מוציאין מרשות אדון בגרות שמוציאה מרשות אב אינו דין שמוציאה מרשות אדון וקרא דאין כסף אלו ימי בגרות לא איצטריך אלא לשיכול למוכרה מ\\\"מ השתא דכתיב קרא למדנו כן בין מק\\\"ו בין מקרא:\",2,0],[8,385,4,6,\"אין אמה העבריה יוצאה בראשי איברים וכו'. כך אמרו פ\\\"ק (דף י\\\"ו) והקשו והא אפיקתיה לאבל נקנית בקניין העבדים וכמו שכתבתי למעלה ותירצו א\\\"כ לימא קרא לא תצא כעבדים מאי כצאת שמע מינה תרתי:\",1,0],[8,385,4,6,\"וכן עבד עברי וכו'. אף על פי שלא מצאתי כן בפירוש אפשר ללמדו מדאיתקש עברי לעבריה וכמוזכר לעיל:\",2,0],[8,385,4,6,\"נמצאת למד וכו'. פשוט הוא ונתבאר במה שקדם:\",3,0],[8,385,4,7,\"יעד אותה האדון לעצמו וכו'. פרק קמא דקידושין (דף י\\\"ח) ברייתא ע\\\"ע יוצא בשנים וביובל מה שאין כן בעבריה ואוקמה רב ששת כגון שיעדה יעדה פשיטא גיטא בעיא מהו דתימא לא ליבטלא הני הלכתא מינה קמ\\\"ל:\",1,0],[8,385,4,7,\"ומצות יעוד קודמת וכו'. משנה ספ\\\"ק דבכורות (דף י\\\"ג):\",2,0],[8,385,4,7,\"כיצד מצות יעוד וכו' עד ואינו נוהג בה מנהג שפחות. ברייתא פ\\\"ק דקידושין (דף י\\\"ט ע\\\"ב) כלשון רבינו.\",3,0],[8,385,4,7,\"ומ\\\"ש סמוך לשקיעת החמה פירוש אע\\\"פ שאין בנשאר מהיום שיעור ששוה עבודתו פרוטה לפי שמעות הראשונות כלומר מעות שנתן האדון לאביה לקידושין ניתנו וכל שאמר לה כן בתוך שש הוה ליה ייעוד למפרע משעת מכירה ולכך אע\\\"פ שהוא סמוך לשקיעת החמה אינו צריך ליתן לה כלום ואע\\\"פ שר' יוסי ברבי יהודה חולק שם ואומר דמעות הראשונות לא לקידושין ניתנו הלכה כת\\\"ק:\",4,0],[8,385,4,7,\"ואינו מייעד שתים וכו'. במכילתא:\",5,0],[8,385,4,7,\"וכיצד מיעדה לבנו אם היה בנו גדול. בפ\\\"ק דקידושין (דף י\\\"ט) בעי ר\\\"ל מהו שייעד לבנו קטן וכו' ת\\\"ש דאמר ר' ינאי אין יעוד אלא בגדול:\",6,0],[8,385,4,8,\"אין האדון מייעד וכו'. פ\\\"ק דקידושין שם ואמר ר\\\"נ בר יצחק דרשינן הכי מדכתיב יעדה שהוא לשון דיעה דרשינן שהוא צריך להודיעה והיינו כדי שתתרצה שאל\\\"כ מה תועלת יש בהודעתה:\",1,0],[8,385,4,8,\"אם מת האדון וכו'. זה פשוט:\",2,0],[8,385,4,9,\"הייעוד כאירוסין וכו'. בעיא דאיפשיטא פ\\\"ק דקידושין (דף י\\\"ח ע\\\"ב):\",1,0],[8,385,4,9,\"אם שלש אלה וכו'. איני רואה מה צורך לרבינו לכתוב דברים אלו אלא שהשלים לבאר הפסוק שהתחיל לבאר אשר לא יעדה:\",2,0],[8,385,4,10,\"אין האדון יכול למכור וכו'. במכילתא:\",1,0],[8,385,4,10,\"וכן עבד עברי. מהיקשא דכי ימכר לך אחיך העברי או העבריה:\",2,0],[8,385,4,10,\"ויראה לי וכו'. כלומר דדבר פשוט הוא שלא ימכרו ממכרת עבד כלומר לימכר ולחזור אותו האדון למוכרו אלא שהוצרך לפרש כן באמה לפי שמצינו שנתנה לו תורה רשות ליעדה לבנו סד\\\"א כיון שיכול ליעדה לאחר שאינו אדון מה לי בנו מה לי אחר קמ\\\"ל:\",3,0],[8,385,4,11,\"אין האמה העבריה נמכרת וכו' עד קידושין תופסין בהם. פירקא קמא דקידושין (דף כ'):\",1,0],[8,385,4,13,\"המקדש את בתו וכו' עד כמו שביארנו. ברייתא שם ופסק כת\\\"ק אלא דאיכא למידק דאמרינן התם (דף י\\\"ח ע\\\"ב) אפלוגתא דת\\\"ק ור\\\"ש ובפלוגתא דהני תנאי דתניא בבגדו בה כיון שפירש טליתו עליה שוב אינו רשאי למוכרה דברי ר\\\"ע ר\\\"א אומר כיון שבגד בה שוב אינו רשאי למוכרה כלומר ות\\\"ק כר\\\"ע ומשמע דה\\\"פ כיון שפירש טליתו עליה האדון לשם יעוד שוב אין האב רשאי למוכרה וא\\\"כ היאך פסק דאם יעד אותה האדון ומת האדון או גירשה וחזרה לרשות האב הרי האב מוכרה פעם שנייה ושמא י\\\"ל דרבינו היה מפרש כיון שפירש טליתו עליה היינו אם קידשה לאחר אבל אם יעדה אדון אה\\\"נ שרשאי למוכרה דס\\\"ל מוכרה לשפחות אחר שפחות:\",1,0],[8,385,4,14,\"המוכר את בתו ואח\\\"כ הלך וקידשה וכו'. שם (דף י\\\"ט ע\\\"ב) גבי הא דתניא דמיעדה אפילו בסוף שש סמוך לשקיעת החמה משל לאומר לאשה תתקדשי לי מעכשיו לאחר שלשים יום ובא אחר וקידשה בתוך שלשים יום שמקודשת לראשון:\",1,0],[8,385,4,16,\"המוכר את בתו ופסק וכו'. ברייתא שם פירקא קמא דקידושין ופסק כחכמים דפליגי ארבי מאיר:\",1,0],[8,385,5,1,\"עבד כנעני נקנה וכו' נקנה בכסף או בשטר או בחזקה. משנה פ\\\"ק דקידושין (דף כ\\\"ב ע\\\"ב) עבד כנעני נקנה בכסף ובשטר ובחזקה.\",1,0],[8,385,5,1,\"ומ\\\"ש או בחליפין. שם תנא אף בחליפין.\",2,0],[8,385,5,1,\"ומה שכתב או במשיכה. שם אמר שמואל עבד כנעני נקנה במשיכה:\",3,0],[8,385,5,1,\"וקונה את עצמו וכו'. יתבאר בסמוך:\",4,0],[8,385,5,1,\"ועבד קטן וכו'. פרק קמא דקידושין שם אמר רב אשי עבד קטן כבהמה דמי:\",5,0],[8,385,5,2,\"כיצד קונה את עצמו בכסף וכו'. שם (דף כ\\\"ג) נתבאר בגמרא שלדעת חכמים דקיימא לן כוותייהו עבד קונה את עצמו בכסף ע\\\"י אחרים אפילו שלא מדעתו לפי שזכות הוא לעבד לצאת מתחת יד רבו וזכין לאדם שלא בפניו וכן נתבאר שם שאם הקנה לעבד ע\\\"מ שיצא בו לחירות לא קנה רבו:\",1,0],[8,385,5,2,\"ואחד הכסף או שוה וכו'. שם (דף ט\\\"ז) אהא דתנן דעבד עברי קונה את עצמו בכסף תנא קונה את עצמו בכסף ובשוה כסף בכסף דכתיב מכסף מקנתו שוה כסף נמי ישיב גאולתו אמר רחמנא לרבות שוה כסף ככסף דילפינן מניזקין וע\\\"ע דכתיב בהו ישיב כמ\\\"ש התוספות בריש קידושין:\",2,0],[8,385,5,3,\"כיצד בשטר וכו' הרי את בן חורין כו'. פרק המגרש (גיטין דף פ״ה ע״ב) תנן גופו של גט שחרור הרי את בן חורין הרי את של עצמך ואיבעיא לן בגמרא אמר לעבדו אין לי עסק בך מהו ופשטוה דיצא בן חורין והכי איתא נמי בריש קידושין (דף ו') ואע״פ שהאומר אין לי עסק בשדה זו לא אמר כלום וכמו שנתבאר בדברי רבינו פ' ג' מהלכות זכייה ומתנה עבד שאני שיכול לזכות בעצמו מכיון שסלק זכותו ממנו וקטן נמי זכו בו שמים משום דמייתי ליה לכלל מצות משא״כ בשדה.\",1,0],[8,385,5,3,\"ומ\\\"ש ומוסר לו את השטר וכו' או שהיו העדים חתומים וכו'. כמו בגט אשה.\",2,0],[8,385,5,3,\"ומ\\\"ש שהרי גיטו וידו באים כאחד. כך כתוב בפ\\\"ק דקידושין (דף כ\\\"ג) אליבא דרבנן דקי\\\"ל כוותייהו דבשטר קונה עצמו אפי' על ידי עצמו משום דגיטו וידו באים כאחד:\",3,0],[8,385,5,3,\"אמר לו שלא בכתב וכו'. גיטין פרק השולח (גיטין דף מ' ע״ב) ת״ר האומר עשיתי פלוני עבדי בן חורין עשוי בן חורין הרי הוא בן חורין [הרי הוא בן חורין וכו'] אמר ר״י וכולן בשטר ופירש״י האי אומר דקתני כותב הוא שכתב לו אחד מן לשונות הללו ומסר לו אבל באמירה בעלמא לא הוי בן חורין:\",4,0],[8,385,5,3,\"ועל מ״ש רבינו ואעפ״י שקנו מידו. כתב הראב״ד ז״ל דבר זה אינו מחוור שהקניין הרי הוא ככסף מההוא מעשה דכומתא והלכה כר״ש שהכסף גומר בו עכ״ל וההוא מעשה דכומתא איתיה בפרק השולח (גיטין דף ל״ט ע״ב) והכי איתא התם לאפוקי מהאי תנא דתניא ר״ש אומר יכול יהא כסף גומר בה כדרך ששטר גומר בה ת״ל והפדה לא נפדתה אורעה כל הפרשה כולה ללא חופשה לומר לך שטר גומר בה ואין כסף גומר בה וכו' ההיא אמתא דהוי מרה שכיב מרע (אתיא בכיא קמיה] אמרה ליה עד אימת תשתעביד ותיזיל ההיא איתתא שקל כומתיה ושדא בה אמר לה זיל קני הא וקני נפשך אתו לקמיה דרב נחמן אמר להו לא עשה ולא כלום מאן דחזא סבר משום דהלכה כר״ש ולא היא אלא משום דהוה ליה כליו של מקנה ופירש רש״י דהוה ליה כליו של מקנה וקי״ל כרב וכו' דהלכתא בכליו של קונה עכ״ל ומשמע שאילו היה בכליו של קונה הוי שיחרור וכן כתב [הרא״ש] בשם רש״י והתוס' וכתב עוד אבל רבינו חננאל כתב שאינה קונה עצמה בחליפין אלא צריכה נמי גט חירות וכתב הרמב״ן ז״ל דלפי דברי ר״ח [כך היה מפרש כיון דהויא בכליו של מקנה] לא עשה כלום אף להוציאה מידי שיעבוד אבל בכליו של קונה יצאה מידי שיעבוד וצריכה גט שיחרור ובתוספתא כתבו שאפשר לומר דהכא לא בתורת חליפין היא אלא בתורת דמים וכיון שכן אילו היה בכליו של קונה ובתורת דמים יצאה שהרי כסף גומר בה וכן דעת הרמב״ם ז״ל דאין העבד קונה עצמו בחליפין כלל ואינו יוצא בו מידי שיעבוד עכ״ל. ומ״ש עוד הראב״ד והלכה כר״ש שהכסף גומר בו קשיא לי ר״ש סבר שאין הכסף גומר ולכן נ״ל שט״ס יש כאן וצריך להגיה שאין הלכה כר״ש:\",5,0],[8,385,5,3,\"הכותב לשפחתו הרי את מותרת וכו'. פרק המגרש (גיטין דף פ״ה ע״ב) פשיטא אמר לשפחתו הרי את מותרת לכל אדם לא אמר כלום ואיתא נמי בריש קידושין (דף ו' ע״ב) ופירש״י שם דטעמא משום דאין זה לשון שחרור דשפחה דאי בת חורין משוה לה אינה מותרת לעבדים אבל לשון גט הוא לאשה שמתירה לכל שהיתה אסורה לו על ידו:\",6,0],[8,385,5,4,\"כיצד בראשי איברים המכה את עבדו בכוונה. פרק קמא דקידושין (דף כ\\\"ד ע\\\"ב) ושחתה עד שיתכוון לשחתה ואליבא דרבנן ה\\\"פ עד שיתכוון לעין ואע\\\"פ שלא נתכוין לשחתה וכמו שיתבאר אבל אם לא נתכוון לעין כלל פטור.\",1,0],[8,385,5,4,\"ומ\\\"ש וחסרו אחד מכ\\\"ד ראשי איברים יצא לחירות וצריך גט שיחרור. שם מחלוקת תנאים אם צריך גט שיחרור והכריע הרי\\\"ף שם כמ\\\"ד צריך גט שחרור בין בשן ועין בין בשאר ראשי איברים.\",2,0],[8,385,5,4,\"ומ\\\"ש א\\\"כ למה נאמר בתורה שן ועין וכו'. שם:\",3,0],[8,385,5,4,\"אבל המסרס עבדו וכו'. גם זה שם (דף כ\\\"ה) בכולם כלומר בראשי איברים עבד יוצא בהם לחירות בן עזאי אומר אף הלשון ואף על פי שלפעמים מתכסה חשיב גלוי רבי אומר אף הסירוס כלומר סירוס דביצים שאף על פי שטמונים בכיס חשיבי גלוי והרי\\\"ף כתב הלשון כך ולא הכריע ולא היה לו להביא דברי רבי ובן עזאי ומכיון שהביאם אלמא הלכתא כוותייהו ס\\\"ל אבל רבינו סובר דכיון דיחידאי נינהו לית הלכתא כוותייהו וכתב הרא\\\"ש בפסקיו והסירוס דביצים פליגי בשכרתן ועודן תלויין בכיס אבל אם נתקן מהכיס לגמרי לכ\\\"ע הוי מום שבגלוי ורבינו לא חילק:\",4,0],[8,385,5,4,\"וכן המפיל שן הקטן כו' סופו לחזור. מבואר שם:\",5,0],[8,385,5,5,\"אין יוצא בראשי איברים וכו' אלו הן ראשי איברים שאינן וכו'. ברייתא פ\\\"ק דקידושין (דף כ\\\"ה):\",1,0],[8,385,5,5,\"אבל העינים וכו'. כלומר ואין צריך למנותם:\",2,0],[8,385,5,6,\"היתה לו אצבע יתירה וכו'. שם (דף כ\\\"ד ע\\\"ב) א\\\"ר חייא בר אשי היתה לו יתרת וחתכה עבד יוצא בה לחירות א\\\"ר חסדא והוא שנספרת על גב היד ופירש\\\"י נספרת על גב היד שהיתה בשורת שאר אצבעות:\",1,0],[8,385,5,6,\"היתה עינו סמויה וכו'. מימרא דרב ששת שם:\",2,0],[8,385,5,7,\"הכהו על עינו וסמאה וכו' הכהו כנגד עינו ואינו רואה וכו'. ברייתא שם וכתבו התוס' פרק הגוזל עצים (בבא קמא דף צ״ח) בד״ה מתיב רבא וא״ת ואמאי עבד יוצא בהם לחירות והא בעינן מומין שבגלוי דומיא דשן ועין ובחרשו היכי הוי בגלוי וי״ל נהי שאין ניכר בו כלום כשהוא ישן או עומד במקום אחד ושותק מ״מ כיון דלפי מנהגו שמתנהג והולך ניכר שהוא חרש חשיב מום שבגלוי ועוד יש לומר דאין צריך שיהא קלקול בגלוי אלא שהאבר שיש בו קלקול יהא בגלוי עכ״ל:\",1,0],[8,385,5,8,\"הכהו על עינו וחסרה מאורה וכו'. [ברייתא שם]:\",1,0],[8,385,5,9,\"היתה עינו כהה וכו'. ברייתא שם:\",1,0],[8,385,5,10,\"הכהו על ידו וצמתה וכו'. ברייתא שם ופירש\\\"י צמתה יבשה:\",1,0],[8,385,5,10,\"תלש בזקנו וכו'. תמהני על דין זה שהרי שם בגמרא אמרו אי מה הפרט מפורש מומין שבגלוי ובטל ממלאכתו ואינו חוזר אף כל מומין שבגלוי ואינו חוזר ובטל ממלאכתו אלמה תניא תלש בזקנו ודלדל בו עצם עבד יוצא בהם לחירות לחפשי ישלחנו ריבויא הוא הרי מפורש שתלישת העצם אין בה ביטול מלאכה ואפילו הכי יוצא לחירות וי\\\"ל שרבינו מפרש דכי אמרינן אי מה הפרט מפורש וכו' אלמה תניא תלש בזקנו וכו' היינו לומר דתלש בזקנו ודלדל בו עצם אף על פי שבטלו ממלאכתו ואין סופו לחזור כיון שאינו בגלוי שהרי העור מכסה לא היה יוצא לחירות אי לאו ריבויא דלחפשי ישלחנו ואין להקשות אם כן סירוס דביצים נמי ליתי מריבויא דלחפשי דהא בטל לגיד המחובר לו ממלאכתו ואין סופו לחזור ויש לומר שאף על פי שסרסו הביצים כיון שעדיין תלויים בכיס יכול להתקשות קצת על ידי הדחק ונמצא שלא בטלו ממלאכתו לגמרי אי נמי אינו חוזר היינו שסופו לייבש וליפול כדפרישית אבל ביצים שכרתן ועודם תלויים בכיס אין סופן לייבש וליפול:\",2,0],[8,385,5,11,\"הפיל את שינו וכו'. בסוף פרק שני דבבא קמא (דף כ\\\"ו ע\\\"ב) אמרינן שאם היתה אבן מונחת לו בחיקו [בין] שלא הכיר בה [בין שהכיר בה ושכחה] ועמד ונפלה לענין עבד פלוגתא דרבן שמעון בן גמליאל ורבנן דתניא הרי שהיה רבו רופא ואמר ליה כחול לי עיני וסימאה חתור לי שיני והפילה שיחק באדון ויצא לחירות רבן שמעון בן גמליאל אומר ושיחתה עד שיתכוון לשחתה ופירש רש\\\"י לענין עבד אם נפלה על עבדו וסימאה עינו עכ\\\"ל ומשמע דלרבנן יצא לחירות ולפיכך יש לתמוה על רבינו שפסק שלא יצא לחירות ולקמן בסמוך פסק כרבנן ואפשר לומר דמשום דקשיא ליה מה ענין זה לענין פלוגתא דרבן שמעון בן גמליאל ורבנן דהתם שאני שנתכוון ליגע בעין ובשן משא\\\"כ בהא דהיתה אבן מונחת לו בחיקו שלא היתה לו כוונה כלל ולכן נראה שמפרש רבינו דה\\\"פ לענין עבד אפילו לפי פלוגתא דרשב\\\"ג ורבנן פטור ודוחק ועוד י\\\"ל שטעם רבינו מדאמרינן בפ\\\"ק דקידושין (דף כ\\\"ד ע\\\"ב) על האי ברייתא דהרי שהיה רבו רופא ורבנן האי ושחתה מאי עבדי ליה מיבעי להו לכדתניא הרי שהושיט ידו למעי שפחתו וסימא עובר שבמעיה פטור מ\\\"ט דאמר קרא ושחתה עד שיתכוון לשחתה ופירש\\\"י לכדתניא הושיט ידו למעי שפחתו להוציא עוברה דלא נתכוין לעין כלל אבל כחול עיני דנתכוון לעין אע\\\"ג דלא נתכוון לשחתה חייב ופסקו הרי\\\"ף והרא\\\"ש ז\\\"ל כת\\\"ק דרשב\\\"ג והא דאמר רבא היתה אבן מונחת לו בחיקו פלוגתא דרשב\\\"ג ורבנן פליגא אהא דאמרינן בפ\\\"ק דקידושין וכוותה נקטינן דהיא בדוכתה ועוד דאפשר דאף רבא דאמר לענין עבד פלוגתא דרשב\\\"ג ורבנן לאו לקושטא דמילתא אמרה אלא לומר דלכאורה משמע דפלוגתא דרשב\\\"ג ורבנן היא ולמיכלל מילי טובא כההיא דהיתה אבן מונחת בחיקו אתא למימר דנ\\\"מ לענין ניזקין ולענין ארבעה דברים ולעניין שבת ולענין גלות וכדאיתא התם וקאמר דאף לענין עבד משמע לכאורה דפלוגתא דרשב\\\"ג ורבנן היא ומיהו לפום קושטא דמילתא לרבנן נמי לא יצא לחירות מושחתה כההיא דפ\\\"ק דקידושין:\",1,0],[8,385,5,12,\"הושיט ידו למעי שפחתו וכו'. ברייתא פירקא קמא דקידושין שם:\",1,0],[8,385,5,13,\"הרי שהיה רבו רופא וכו'. גם זה שם ופסק כרבנן:\",1,0],[8,385,5,14,\"המפיל שן עבדו וסימא את עינו וכו'. בפרק מרובה. ודע שכתב רבינו בפ\\\"ד מהלכות חובל כל עבד שיצא לחירות ולא הגיע גט שיחרור לידו אין לו קנס ואחרים שחבלו בו אינו יכול להוציא מהם לעצמו ולא האדון יכול להוציא מהם לפיכך המפיל שן עבדו ואחר כך סימא עינו יוצא בשינו ואינו נותן לו דמי עינו ואם תפס אין מוציאין מידו עכ\\\"ל. וטעמא מדאיבעיא לן בפ' השולח מעוכב גט שיחרור אם יש לו קנס ובעינן למפשטה מדתניא הפיל את שינו וסימא את עינו יוצא בשינו ונותן לו דמי עינו ודחינן דילמא כמאן דאמר אינו צריך גט שיחרור וא\\\"כ כשכתב רבינו פה ונותן לו דמי עינו היינו כשכתב לו גט שיחרור בין הפיל שינו לסימא עינו א\\\"נ מאי נותן לו דמי עינו דקאמר לא שגוזרים ב\\\"ד שיתן לו אלא היינו לומר שאם תפס אין מוציאין מידו וסמך על מ\\\"ש בפ\\\"ד מהלכות חובל ובזה נסתלקה השגת הראב\\\"ד שכתב וז\\\"ל דבריו סותרים זא\\\"ז וכו':\",1,0],[8,385,5,15,\"מי שחציו עבד וחציו בן חורין וכו'. ברייתא בפרק החובל (בבא קמא דף צ') ומפרש טעמא משום דאמר קרא עבדו המיוחד ואע\\\"ג דההיא ר\\\"א היא ושאר תנאי פליגי עליה משמע התם דהלכה כר\\\"א משום דאמוראי מפרשי טעמיה:\",1,0],[8,385,5,16,\"עבדי צאן ברזל יוצאים בראשי איברים וכו'. שם (דף פ\\\"ט:) תני חדא עבדי מלוג יוצאים בשן ועין לאשה אבל לא לאיש ותניא אידך לא לאיש ולא לאשה ומוקי לה בגמרא דכולי עלמא אית להו תקנת אושא אלא כאן קודם תקנה כאן לאחר תקנה כלומר דברייתא דלאשה ולא לאיש קודם תקנה וברייתא דלא לאיש ולא לאשה אחר תקנה ואי בעית אימא אידי ואידי לאחר תקנה אלא מאן דאמר לאשה ולא לאיש מאי טעמא כדרבא וכו' לימא דרבא תנאי היא לא דכ\\\"ע אית להו דרבא והכא אלמוה רבנן לשיעבודא דבעל ואיבעית אימא דכולי עלמא לית להו להני תנאי תקנת אושא והכא בקניין פירות כקניין הגוף דמי קמיפלגי ובפלוגתא דהני תנאי וכו' כלומר ומאן דאמר לא לאיש ולא לאשה אתי כר\\\"א שכתבתי בסמוך דהלכתא כוותיה והשתא אי לאוקימתא קמייתא דמאן דאמר לא לאיש ולא לאשה בתר תקנתא קאמר ליכא מאן דפליג עליה ואי לאוקימתא בתרייתא כיון דאתי כר\\\"א והלכתא כוותיה הכי נקטינן:\",1,0],[8,385,5,17,\"יציאת העבד בראשי איברים וכו'. בפ״ק דסנהדרין (דף ח') ופ״ק דב״ק וס״פ אלו נערות (כתובות דף מ').\",1,0],[8,385,5,17,\"ומ\\\"ש לפיכך העבד שאמר לרבו הפלת את שיני וכו'. בפרק מרובה אמרינן מעשה בר\\\"ג שסימא את עין עבדו והיה שמח וא\\\"ל ר\\\"ג לר' יהושע אי אתה יודע שטבי עבדי יצא לחירות א\\\"ל ר' יהושע אין בדבריך כלום שכבר אין לו עדים ודייק עלה הא יש לו עדים חייב וש\\\"מ מודה בקנס ואחר כך באו עדים חייב ומשני שאני ר\\\"ג דשלא בב\\\"ד אודי והא רבי יהושע אב ב\\\"ד הוה חוץ לב\\\"ד הוה הא קמן דאודי שלא בפני ב\\\"ד לא נתחייב בהודאתו וכדא\\\"ל אין בדבריך כלום שכבר אין לו עדים ומ\\\"מ כיון דהודאה בב\\\"ד שאינו סמוך לאו הודאה היא לפוטרו בין תפס קודם הודאה בין תפס אחר הודאה לא מפקינן מיניה ועבד כיון שהוא תפוס בעצמו יצא לחירות בין הודה בין לא הודה. ולפי זה מ\\\"ש\",2,0],[8,385,5,17,\"רבינו ואין דנין בו אלא בב\\\"ד סמוכים לאו למימרא דאינו יוצא לחירות אלא בב\\\"ד סמוכים דהא כיון דקי\\\"ל דאם תפס ניזק אין מוציאין מידו וכמו שפסק רבינו בפ\\\"ה מהלכות סנהדרין ועבד תפוס בעצמו הוא לא מצי לאשתעבודי ביה אם העידו עליו עדים אלא היינו לומר דאין דנין בו כמשפטו שאם הודה הרב קודם שבאו עדים לא יצא העבד לחירות דהיינו דוקא כשהודה בפני ב\\\"ד סמוכים אבל בפני ב\\\"ד שאינן סמוכים אין הודאתו הודאה לפוטרו.\",3,0],[8,385,5,17,\"ובמ\\\"ש לפיכך העבד שאמר לרבו הפלת את שיני וכו' פטור פירוש אם נשבע האדון שלא הפיל שינו ולא סימא עינו פטור מקרבן דאין חייבים קרבן אלא על שבועת כפירת ממון והכא לאו כפירת ממון הוא דבהודאה נמי פטור משום דהוי מודה בקנס וא\\\"כ כי כפר אשתכח דלא כפר ממונא ולפיכך סיים\",4,0],[8,385,5,17,\"וכתב שכל מודה בקנס פטור מלשלמו כלומר פיטור דגבי מודה בקנס הוא פיטור מלשלמו אבל פיטור דגבי כפירת קנס הוא פיטור מקרבן וללמדנו דהא דמודה בקנס פטור מלשלם דוקא במודה בפני ב\\\"ד הוא ולזה כתב ואין דנין בו אלא בב\\\"ד סמוכים אי נמי בדין תורה קאמר עד לא תקון רבנן דאם תפס אין מוציאין מידו אבל אין לומר דה\\\"ק אין דנין בו לקבל עדות העדים לידע אם יניחו מה שתפס בידו או אם יוציאוהו מידו דעבד כיון שהוא תפוס בעצמו צריכין הם לקבל עדות העדים לידע אם יניחו רבו להשתעבד בו אם לא:\",5,0],[8,385,6,1,\"הכותב שטר שיחרור לעבדו וזיכה לו בו ע\\\"י אחר וכו'. בסוף פ\\\"ק דגיטין (דף י\\\"ב ע\\\"ב) איפליגו ר\\\"מ וחכמים אי זכות הוא לעבד שיצא מתחת יד רבו או לאו והלכה כחכמים דאמרי זכות הוא לו ובפ\\\"ק דקידושין (דף כ\\\"ב ע\\\"ב) תנן דחכמים אומרים דעבד קונה עצמו בשטר ע\\\"י אחרים.\",1,0],[8,385,6,1,\"ומ\\\"ש אבל אם אמר תנו גט זה לעבדי אינו יכול לחזור בו ולא יצא העבד לחירות וכו'. בפ\\\"ק דגיטין (דף י\\\"א) תנן האומר תנו גט זה לאשתי ושטר שיחרור זה לעבדי אם רצה לחזור בשניהם יחזור דברי ר\\\"מ וחכמים אומרים בגיטי נשים אבל לא בשיחרורי עבדים לפי שזכין לאדם שלא בפניו ואין חבין לו אלא בפניו. וכתב הרי\\\"ף אבל לא בשיחרורי עבדים והני מילי לחזרה דלא מצי רביה למהדר ביה אבל עבדא לא נפיק לחירות עד דמטי גיטא לידיה דתנן האומר תנו גט זה לאשתי ושטר שיחרור זה לעבדי ומת לא יתנו לאחר מיתה דאין גט לאחר מיתה ושמעת מינה דלחזרה הוא דזכין לו לעבד אבל מיפק לחירות לא נפיק עד דמטי גיטא לידיה ואשכחן זכייה כה\\\"ג עכ\\\"ל והרא\\\"ש תמה עליו דהחזרה והחירות דברים אחדים הם והא בהא תליא הילכך נראה כפירוש רש\\\"י וכפירוש ר\\\"ת דרש\\\"י פירש דל\\\"ג תן משום דתן משמע שנותן ליד השליח דבכה\\\"ג נשתחרר העבד מיד בקבלת השליח אלא גרסינן תנו דמשמע שאינו מוסר להם הגט אלא מצוה להם לכתוב וליתן ורבינו תם פירש דל\\\"ג זה דהוי משמע שמסרו לידם אלא גרסינן תנו גט לאשתי הילכך לא יתנו לאחר מיתה עכ\\\"ל וגם הר\\\"ן חולק על הרי\\\"ף. ורבינו תפס דברי הרי\\\"ף עיקר ופסק כמותו:\",2,0],[8,385,6,2,\"הכותב בשטר עשיתי פלוני עבדי בן חורין. ברייתא פרק השולח (גיטין דף מ').\",1,0],[8,385,6,2,\"ומ\\\"ש כתב בשטר אעשנו בן חורין לא יצא לחירות. שם וכחכמים:\",2,0],[8,385,6,3,\"האומר עשיתי פלוני עבדי בן חורין וכו'. גם זה שם:\",1,0],[8,385,6,3,\"אמר כתבתי גט שיחרור ונתתי לו וכו'. גם זה שם:\",2,0],[8,385,6,4,\"מי שצוה בשעת מיתתו וכו'. ג\\\"ז שם (דף מ) כי אתא רב דימי א\\\"ר יוחנן וכו' פלונית שפחתי אל ישתעבדו בה לאחר מותי כופין את היורשים וכותבין לה גט שיחרור אמרו לפניו רבי אמי ור' אסי רבי אי אתה מודה שבניה עבדים ופירש\\\"י אי אתה מודה דאל ישתעבדו אינו לשון שיחרור ולא לשון הפקר אלא לא יטריחוה בעבודתם אבל עבדים היוצאים ממנה מעכשיו עבדים הם ואמאי כופין לשחררה ויפסידו ולדות מכאן ולהבא שלא צוה להם אביהם כן עכ\\\"ל ומדשתק להו ר' יוחנן אלמא הדר ביה וכתב הרא\\\"ש ז\\\"ל שלא יטריחוה במלאכות כבדות והר\\\"ן כתב משום מצוה לקיים דברי המת אסור להשתעבד בה ומעשה ידיה לא פקע בהכי.\",1,0],[8,385,6,4,\"ומ\\\"ש וכן אם אמר עשו לה קורת רוח וכו'. שם אם אמר יעשו לה קורת רוח כופין את היורשים ועושים לה קורת רוח ופירש הרי\\\"ף מאי קורת רוח אי אמרה האי עבידתא לא למעבד בה לא כייפינן לה ורש\\\"י פירש שאם לא נתקררה דעתה אלא בשיחרור כופין היורשין לשחררה והכי מסתבר להרא\\\"ש.\",2,0],[8,385,6,4,\"ומ\\\"ש צוה ואמר שחררוה כופין את היורשים וכו'. פשוט הוא דקיימא לן מצוה לקיים דברי המת וכ\\\"כ התוס' גבי עובדא דכומתא:\",3,0],[8,385,6,5,\"בששה דרכים שוים שיחרורי עבדים לגיטי נשים וכו'. מתבארים והולכים.\",1,0],[8,385,6,5,\"ומ\\\"ש כיצד כל השטרות העולים בערכאות כשרים חוץ מגיטי נשים ושיחרורי עבדים. משנה פירקא קמא דגיטין (דף י' ע\\\"ב):\",2,0],[8,385,6,6,\"כל שטר שיש עליו וכו' עד והוא שיהיה כותי חבר. משנה וגמרא פרק קמא דגיטין (דף י').\",1,0],[8,385,6,6,\"ומ\\\"ש בגט אשה הוא אומר וכתב לה לשמה ובגט שיחרור הוא אומר או חופשה לא נתן לה עד שיכתוב לשמה. בתוספתא דגיטין פ\\\"ב.\",2,0],[8,385,6,6,\"ומ\\\"ש בגט אשה הוא אומר וכתב ונתן וכו' ובגט שיחרור הוא אומר וכו'. בפרק קמא דגיטין (דף ט' ע\\\"ב) אהא דתנו רבנן בשלשה דברים שוו גיטי נשים לשיחרורי עבדים מקשו ותו ליכא והא איכא לשמה וכו' והא איכא מחובר ומשני כי קתני פסולא דרבנן דאורייתא לא קתני:\",3,0],[8,385,6,6,\"אחד גיטי נשים וכו'. בפ\\\"ק דגיטין:\",4,0],[8,385,6,7,\"וכיצד שוין במוליך ומביא וכו'. בפ\\\"ק דגיטין (דף ט') תנן אחד גיטי נשים וא' שיחרורי עבדים שוים במוליך ומביא.\",1,0],[8,385,6,7,\"ומ\\\"ש שהמביא גט שיחרור בארץ ישראל א\\\"צ לומר בפני נכתב ובפני נחתם וכו'. הכי משמע שם במשנה.\",2,0],[8,385,6,7,\"ומ\\\"ש כשם שהאשה עצמה מביאה את גיטה ואינה צריכה לקיימו וכו' וכשם שהאשה אומרת בפני נכתב ובפני נחתם וכו' כך העבד וכו'. משמע לרבינו שכל זה בכלל מה ששנינו אחד גיטי נשים וא' שיחרורי עבדים שוים במוליך ומביא:\",3,0],[8,385,6,7,\"כתב הראב\\\"ד אינו צריך לקיימו א\\\"א זה הדרך הולך על דרך לא טוב וכו'. וה\\\"ה בהל' גיטין פ\\\"ז ופי\\\"ב כתב בזה עיין עליו:\",4,0],[8,385,6,8,\"ומ\\\"ש כל הכשר להביא גט האשה כשר להביא גט העבד. ג\\\"ז בכלל מה ששנינו ששוו גיטי נשים לשיחרורי עבדים במוליך ומביא:\",1,0],[8,385,6,8,\"והעבד מקבל גט חבירו וכו'. מימרא דר' יוחנן בסוף פרק ב' דגיטין (דף כ\\\"ג ע\\\"ב) ופירש\\\"י מיד רבו של חבירו שאין רבו שלו דכיון דעבד איתיה בתורת שיחרור שליחא נמי מצי מיהוי. אבל לא מיד רבו שלו אם שניהם של איש אחד דיד עבד כיד רבו דמי וכשמסר גט בידו לא יצא מרשותו ואף על גב דעבד מקבל גט לעצמו התם הוא דגיטו וידו באים כאחד דשיחרורא דידיה הוא אבל לאחרינא לא עכ\\\"ל:\",2,0],[8,385,6,8,\"הכותב שטר אירוסין לשפחתו וכו'. ברייתא בפרק השולח (גיטין דף מ') פלוגתא דרבי מאיר ורבנן והלכה כרבנן דאמרי הכי ומשמע התם דאי לא אמר לה אלא התקדשי גרידא אמרינן ודאי שיחררה מעיקרא וחלו הקידושין וכן כתב רש״י בהדיא:\",3,0],[8,385,7,1,\"גט שיחרור צריך שיהיה עניינו דבר הכורת וכו' לפיכך הכותב לעבדו וכו'. בפ״ק דגיטין (דף ח' ע״ב) מייתי הא דתנן הכותב כל נכסיו לעבדו יצא בן חורין שייר קרקע כל שהו לא יצא בן חורין ר״ש אומר לעולם הוא בן חורין עד שיאמר כל נכסיי נתונים לאיש פלוני עבדי חוץ מאחד מריבוא שבהם ואיפסיקא הלכתא בגמרא כת״ק ואמר רב אשי דטעמא דת״ק משום דלאו כרות גיטא הוא ופירש הרי״ף דכיון דשייר ליה קרקע כל שהו וכתב הכי בגיטא ה״ל לרביה זכותא בגויה דגיטא וכגון זה אינו כריתות דבעינן דליהוי גיטא דחירותא כוליה לעבדא וליכא וכך הם דברי רבינו והתוספות והרא״ש פירשו בע״א ואמרינן בפרק מי שמת (בבא בתרא דף קמ״ט) דשייר קרקע דתנן לאו דוקא דה״ה לשייר מטלטלין:\",1,0],[8,385,7,2,\"עבד שהביא גט וכו'. ברייתא שם (דף ח' ע\\\"ב) ופירש\\\"י עצמו קנה דנאמן הוא על שיחרורו לומר בפני נכתב ואין צריך עדים לקיימו. נכסים לא קנה דבעי עדים כשאר קיום שטרות.\",1,0],[8,385,7,2,\"ומ\\\"ש וכן אם היה כתוב בו כל נכסי קנויים לך וכו'. שם בעיא ופשטה רבא הכי:\",2,0],[8,385,7,3,\"המשחרר שני עבדים בשטר וכו'. בפרק השולח (גיטין דף מ״ב) תני חדא הכותב נכסיו לשני עבדיו קנו ומשחררין זה את זה ותניא אידך האומר כל נכסי נתונים לפלוני ופלוני עבדי אף עצמן לא קנו ואוקימנא הא דאמר כולו הא דאמר חצי חצי והא מדקתני סיפא אם אמר חצי חצי לא קנו מכלל דרישא דאמר כולו פרושי קא מפרש אף עצמן לא קנו כיצד כגון דאמר חצי חצי וכו' ואיבעית אימא לא קשיא כאן בשטר אחד כאן בשני שטרות בשטר אחד מאי איריא [דאמר] חצי חצי אפילו אמר כולו נמי לא קני ה״נ קאמר אף עצמן לא קנו בד״א בשטר אחד אבל בשני שטרות קנו ואם אמר חצי חצי אף בשני שטרות נמי לא קנו וכתב הר״ן דהיינו טעמא דחצי חצי לא מהני לפי שאין העבד משתחרר אלא מחמת השטר שנמסר בידו ובעינן שלא יהא בו שיור כלל ואף על פי ששטר חבירו מוכיח דליכא שיורא גבי נותן הרי הוא אינו משתחרר בשטר חבירו שלא זכה בו עכ״ל וכך הם דברי רבינו והמפרשים פירשו בענין אחר:\",1,0],[8,385,7,4,\"המשחרר חצי עבדו בשטר וכו'. שם ת\\\"ר המשחרר חצי עבדו רבי אומר קנה וחכמים אומרים לא קנה אמר רבה מחלוקת בשטר וכו' דרבנן גמרי לה לה מאשה מה אשה חציה לא אף עבד חציו לא אבל בכסף ד\\\"ה קנה.\",1,0],[8,385,7,4,\"ומ\\\"ש בד\\\"א בששחרר חציו בשטר וכו'. שם (דף מ\\\"ב) אמר רבה מחלוקת בששחרר חציו והניח חציו אבל שחרר חציו ומכר או נתן במתנה חציו כיון דקא נפיק מיניה כוליה ד\\\"ה קנה ופירש\\\"י והניח חציו דבעינן דניפוק כוליה מיניה כי אשה אבל שחרר חציו ומכר תחלה חציו או בבת אחת וכ\\\"כ הר\\\"ן וכי אמרינן בשחרר חציו ונתן במתנה חציו קנה כגון שנתן תחלה דהשתא ליכא שיורא בשיחרור דיליה או כגון שהוא כותב בשטר שיחרור עצמו שהוא נותן חציו האחר לאותו אחר ומזכה השטר לאחד בשביל שניהם וכיון דליכא שיורא בשטר שיחרור קני.\",2,0],[8,385,7,4,\"ומ\\\"ש וכן עבד של שני שותפים וכו'. שם מימרא דרבינא ופירש\\\"י דכיון דאין לו בו אלא חציו אפילו רבנן מודו דקנה כי שחרריה לפלגיה דהא לא שייר מידי והוי כאשה דנפקא מיניה לגמרי:\",3,0],[8,385,7,5,\"הכותב לשפחתו מעוברת וכו'. ברייתא בתמורה בפ' כיצד מערימין (תמורה כ״ה:) ובקידושין פ' האומר (דף ס״ט) וכתבה הרי״ף בפרק השולח האומר לשפחתו הרי את בת חורין וולדך עבד ולדה כמותה דברי ר' יוסי הגלילי וחכ״א דבריו קיימים והלכה כחכמים.\",1,0],[8,385,7,5,\"ומ\\\"ש הרי את שפחה וולדך ב\\\"ח וכו'. שם הרי את שפחה וולדך ב\\\"ח אם היתה עוברה זכתה לו ומוקי לה כרבי דאמר המשחרר חצי עבדו קנה כולו ואנן קי\\\"ל כרבנן דפליגי עליה ואמרי לא קנה:\",2,0],[8,385,7,5,\"כתב הראב\\\"ד קשיא רישא אסיפא וכו'. ודבריו אינם השגה אלא פירוש וטעם ושפתים ישק:\",3,0],[8,385,7,6,\"שפחה חרופה אם רצה לשחרר וכו' ותיעשה א״א גמורה. כך היא הגירסא הנכונה והוא בפרק השולח (גיטין דף מ״ג ע״ב) איתמר חציה שפחה וחציה בת חורין שנתקדשה לראובן ונשתחררה וחזרה ונתקדשה לשמעון רב יוסף בר חמא אר״נ פקעי קידושי ראשון ר' זירא אמר ר״נ גמרו קידושי ראשון ופירש״י גמרו קידושי ראשון ע״י השיחרור גמרו ומשמע שפוסק רבינו כרבי זירא ועיין בפ״ד מהלכות קידושין בדברי רבינו ובדברי ה״ה:\",1,0],[8,385,7,6,\"כתב הראב\\\"ד פירוש המאורסת לע\\\"ע וכו':\",2,0],[8,385,7,7,\"מי שחציו עבד וכו'. משנה בפרק השולח (גיטין דף מ״א).\",1,0],[8,385,7,7,\"ומ\\\"ש בד\\\"א בעבד וכו' אבל השפחה וכו' ואם נהגו בה החוטאים מנהג הפקר וכו'. שם בגמרא:\",2,0],[8,385,7,8,\"מי שחציו עבד וחציו ב\\\"ח וכו'. שם (דף מ') ההוא עבדא דבי תרי קם חד מינייהו ושחרריה לפלגיה אמר אידך השתא שמעי בי רבנן ומפסדו ליה מינאי אזל אקנייה לבנו קטן שלחה רב יוסף בריה דרבא לקמיה דרב פפא שלח ליה כאשר עשה כן יעשה לו וכו' אנן קים לן בינוקא דמקרבא דעתיה לגבי זוזי מוקמינן ליה אפוטרופוס ומקרקש ליה בזוזי וכתב ליה גיטא דחירותא על שמיה. ופירש\\\"י מפסדי ליה מינאי כדאמרינן במתניתין כופין את רבו ועושה אותו ב\\\"ח. אקנייה לבנו קטן שאין ראוי לכופו בב\\\"ד. מוקמינן ליה אפוטרופוס לינוקא לברור לו דמים יפים כמו שהוא נישום בשוק שהרי צריך העבד לכתוב שטר על חצי דמיו ומקרקש ליה עבדא זוזי דבר מועט לינוקא ולא יצטרכו ב\\\"ד לכופו שהוא ישחררהו מדעתו בשביל זוזי ובלאו קרקושי זוזי לא אפשר דינוקא לאו בר כפייה הוא ואפוטרופסין אין רשאין להוציא עבדים לחירות ולא לחוב ליתומים כדאמרינן בהניזקין ותינוק זה מקחו מקח וממכרו ממכר במטלטלין וכו' ואפוטרופוס מוקמינן לעיין בתקנתו ולשומו בדמים מעולים והתוספות כתבו דלא נראה לר\\\"ש פירש\\\"י דמפרש כתב ליה גיטא דחירותא על שמיה דקטן שאין מעשה קטן כלום להתירו בבת חורין אלא נ\\\"ל לפרש דכתב ליה גיטא על שמיה דאפוטרופוס ואע\\\"ג דבעלמא אין האפוטרופסין רשאים להוציאם לחירות הכא כיון שלא עשה כהוגן הפקירוהו בית דין ונתנוהו לאפוטרופוס לשחררו וכו' ובלא קרקושי זוזי לא רצו ב\\\"ד ליתן רשות לאפוטרופוס לשחררו דאין נכון לעבור על דעתו של תינוק ור\\\"ת מפרש דלאו קנסא הוא וכו' דבדין יכול האפוטרופוס לשחררו בכך כדאמרינן בהניזקין וכו' ואפילו בלא קרקושי אלא משום דמיחזי כחוכא ואיטלולא שהתינוק עומד וצווח שלא למכור לפי שאביו מלמדו לצווח ואיכא לזות שפתים אבל כי קא מקרקש ליה זוזי לא יחוש לדברי האב וגיטא דחירותא נמי לא הוה צריך דכסף גומר בלא שטר וכו' אלא שלפי שעושה בע\\\"כ של אב צריך גיטא דחירותא מדרבנן שלא יאמר לו עבדי אתה וגם הרשב\\\"א והר\\\"ן תמהו על פירש\\\"י והעלו שהאפוטרופוס כותב השטר וכן דעת הרי\\\"ף וכן נראה שהוא דעת הרא\\\"ש וכתב הרי\\\"ף יש שואלים וכי מאחר דמוקמינן אפוטרופוס למאי הלכתא אמרינן ידעינן בינוקא דמקרבא דעתיה לגבי זוזי ומהדרי רבנן משום דחיישינן דילמא מסתביך ביה ינוקא בההוא עבדא וכיון דמקרקשינן ליה בזוזי לא אתי לאיסתבוכי ביה עכ\\\"ל. והראב\\\"ד כתב על דברי רבינו נשתבש כאן שיבוש גדול וכו'. ואיני יודע למה כתב שנשתבש שיבוש גדול והרי נתבאר שהרי\\\"ף ורוב המפרשים סוברים כדברי רבינו:\",1,0],[8,385,7,9,\"שכ\\\"מ שכתב כל נכסיו לעבדו ועמד וכו'. מימרא פירקא קמא דגיטין (דף ט'):\",1,0],[8,385,8,1,\"המוכר את עבדו לעכו״ם יצא בן חורין. משנה פרק השולח (גיטין דף מ״ג) ופירש״י יצא בן חורין אם ברח מן העכו״ם או שקנסוהו ב״ד לפדותו כדאמרינן לקמן כשיפדנו לא ישתעבד לו וקנס חכמים הוא שהפקיעו מן המצות.\",1,0],[8,385,8,1,\"ומ\\\"ש וכופין את רבו לחזור ולקנותו מן העכו\\\"ם עד עשרה בדמיו. שם מימרא דריב\\\"ל וכלישנא בתרא.\",2,0],[8,385,8,1,\"ומ\\\"ש וכותב לו גט שיחרור ויוצא. פשוט הוא.\",3,0],[8,385,8,1,\"ומ\\\"ש וקנס זה אין גובין אותו ודנין אותו אלא בב\\\"ד מומחין. כן כתב הרי\\\"ף וז\\\"ל וחזינן לגאון דקאמר דלא מגבינן האי קנסא אלא בא\\\"י אבל בח\\\"ל לא דלא מגבינן קנסא בבבל עד כאן לשונו והרא\\\"ש כתב ותמהתי על דברי הגאון דמה ענין זה לקנסות דאין גובין בבבל דהיינו קנסות שחייבה תורה ואין גובין אותן בבבל משום דבעינן מומחין ואין סמוכים בבבל אבל אם חכמים תיקנו קנסות לעשות סייג לתורה למה לא יגבו אותם בבבל עכ\\\"ל ורבינו כתב כדברי הגאון והרי\\\"ף.\",4,0],[8,385,8,1,\"ומ\\\"ש ואם מת המוכר אין קונסין את היורש וכו'. שם בעיא דאיפשיטא:\",5,0],[8,385,8,2,\"לוה על עבדו מן העכו\\\"ם וכו'. שם לוה עליו מן העכו\\\"ם כיון שעשה לו עכו\\\"ם נימוסו יצא לחירות מאי נימוסו וכו' אמר רב ששת זמן ופירש\\\"י זמן אם לא פרעתיך יהא חלוט לך ואקשינן עליה מדתניא האריסין וכו' ועכו\\\"ם שמשכן שדהו לישראל אע\\\"פ שיעשה לו נימוסו פטורה מן המעשר ומשני ל\\\"ק הא דמטי זימניה הא דלא מטא זימניה ומקשה אלא גבי עבד דמטא זימניה צריכא למימר ומשני אלא אידי ואידי דלא מטא זימניה ול\\\"ק הא לגופא הא לפירא ואיבעית אימא בשלוה ע\\\"מ למשכנו ולא משכנו ופירש\\\"י הא לגופא גבי עבד דקבע לו זמן לגופו שאם לא יתן עד אותו זמן יהא גופו חלוט לעכו\\\"ם ומעכשיו היה משתעבד בו וכיון דזילזל בתקנתא דרבנן דאסרו למכור עבד לעכו\\\"ם קנסוהו ואע\\\"ג דלא מטא זימניה. ואמאי דמשני ע\\\"מ למשכנו ולא משכנו פירש\\\"י דהכי קאמר לעולם בדמטא זימניה ואיצטריך לאשמועינן היכא דעדיין לא משכנו שאעפ\\\"כ יצא לחירות הואיל ובידו למשכנו הוא ורבינו השמיט דין זה נראה שטעמו מפני שהוא מפרש דהאי שינויא קאי למאי דאמר הא לגופא הא לפירא כלומר עבד ודאי מיירי במשכנו לגופא כלומר להיות הגוף קנוי לו וכדפרישית אבל שדה מיירי בשלא משכנו אלא לפירות ואיבעית אימא דשדה נמי במשכנו לגופא והיינו טעמא דפטור משום דלוה עליו למשכנו ולא משכנו עדיין ולפ\\\"ז לא נפקא לן מהאי שינויא לגבי עבד:\",1,0],[8,385,8,2,\"גבאו העכו\\\"ם בחובו או שבאו עליו מצירים וכו'. שם (דף מ\\\"ד) ת\\\"ר גבאו בחובו או שלקחו סקריקון לא יצא לחירות:\",2,0],[8,385,8,3,\"מכר עבדו לאחד מגדולי המלך וכו'. שם אמר רב המוכר עבדו לפרהנג עכו\\\"ם יצא לחירות ומפרש טעמא משום דה\\\"ל לפייס ולא פייס:\",1,0],[8,385,8,4,\"מכרו לעכו\\\"ם לשלשים יום מכרו חוץ ממלאכתו חוץ מן המצות חוץ משבתות וי\\\"ט. כך היא הגירסא הנכונה ופירש\\\"י חוץ ממלאכתו גופו קנוי לך ובלבד שלא תשתעבד בו שלא מכרו אלא להשיאו לשפחתו לולדות דהשתא לא מיפקע ממצות לחלל שבתות א\\\"נ מכרו למלאכתו חוץ משבתות וי\\\"ט ופסק רבינו הרי זה ספק משום דבפרק הנזכר הוו בעיי דלא איפשיטו.\",1,0],[8,385,8,4,\"ועל מה שכתב רבינו לפיכך אם תפס העבד כדי דמיו וכו' כתב הראב\\\"ד א\\\"א אין בקנסות תפיסה מועלת אלא במי שחסרו ממון עכ\\\"ל ואין בדבריו הכרע ואפילו לפי דבריו מה שהפקיעו מהמצות אין לך חסרון גדול מזה ועוד שירדה בו בפרך וכמ\\\"ש בעל מ\\\"ע:\",2,0],[8,385,8,5,\"ומ\\\"ש אחד מוכר עבדו לעכו\\\"ם עובד ע\\\"ז או שמכרו לגר תושב. שם.\",1,0],[8,385,8,5,\"ומ\\\"ש אפילו לכותי. שם בעיא דלא איפשיטא ומשמע לרבינו דע\\\"כ לא איבעיא לן אלא קודם שגזרו עליהם אבל אחר שעשאום עכו\\\"ם לכל דבריהם כדאיתא בפ\\\"ק דחולין הא ודאי דין כותי כדין עכו\\\"ם וכ\\\"כ הר\\\"ן:\",2,0],[8,385,8,5,\"ומ\\\"ש מכרו לישראל מומר. שם בעיא דלא איפשיטא:\",3,0],[8,385,8,6,\"המוכר עבדו לח\\\"ל יצא בן חורין. משנה שם (דף מ\\\"ג):\",1,0],[8,385,8,6,\"ומ\\\"ש כופין את רבו וכו'. ברייתא שם.\",2,0],[8,385,8,6,\"ומ\\\"ש ומפני מה קנסו כאן הלוקח לבדו וכו'. שם:\",3,0],[8,385,8,6,\"המוכר עבדו לסוריא ואפילו לעכו. בפ\\\"ק דגיטין עלה ח' בעיא דאיפשיטא:\",4,0],[8,385,8,7,\"בן בבל שנשא אשה בארץ ישראל וכו'. בפרק השולח (גיטין דף מ\\\"ד ע\\\"ב) בעיא דלא איפשיטא:\",1,0],[8,385,8,8,\"עבד שיצא אחר רבו לסוריא ומכרו שם וכו'. מימרא וברייתא שם.\",1,0],[8,385,8,8,\"ומ\\\"ש וכופין את הלוקח לשחררו. [נתבאר לעיל ה\\\"ו]:\",2,0],[8,385,8,9,\"עבד שאמר לעלות לא\\\"י כופין וכו'. בסוף כתובות (ק\\\"י:) הכל מעלין לא\\\"י ואין הכל מוציאין ובגמרא הכל לאיתויי עבדים ואע\\\"פ שרש\\\"י פירשה בע\\\"ע רבינו מפרש בעבד כנעני וכ\\\"כ בשם הראב\\\"ד:\",1,0],[8,385,8,10,\"עבד שברח מח״ל וכו'. בפרק השולח (גיטין דף מ״ה) ההוא עבדא דערק מח״ל לארץ אזל מאריה אבתריה אתא לקמיה דר' אמי א״ל לכתוב ליה שטרא אדמיה וכתוב ליה גיטא דחירותא ואי לא מפיקנא ליה מינך מדר' אחי בר יאשיה דאמר וכו' לא תסגיר עבד אל אדוניו בעבד שברח מח״ל לארץ הכתוב מדבר:\",1,0],[8,385,8,11,\"עבד זה שברח לארץ וכו':\",1,0],[8,385,8,12,\"הקונה עבד מן העכו״ם סתם ולא רצה למול וכו'. מימרא דריב״ל בפרק החולץ (יבמות דף מ״ח ע״ב).\",1,0],[8,385,8,12,\"ומ\\\"ש ואם התנה העבד עליו תחלה וכו'. שם שלח רבין משמיה דרבי אלעאי וכו' אי זהו עבד ערל שמותר לקיימו זה שלקחו רבו ע\\\"מ שלא למולו ואמר רב פפא דאתי אפילו כר\\\"ע דאמר אין מקיימין עבדים שאינם מולים דה\\\"מ היכא דלא אתני אבל היכא דאתני אתני ורבינו כתב בפ\\\"א ממילה ובפי\\\"ד מאיסורי ביאה כלשון הזה ואם התנה עליו מתחלה והוא אצל רבו עכו\\\"ם שלא ימול אותו מותר לקיימו והוא ערל ובלבד שיקבל עליו שבע מצות ויהיה כגר תושב ואין מקיימין עבד כזה אלא בזמן היובל עכ\\\"ל ובכאן סמך על מ\\\"ש שם:\",2,0],[8,385,8,12,\"וכן עבד שמל וטבל לשם עבדות וכו'. בפרק השולח (גיטין דף מ״ד) ומה שאמרו וכותב ומעלה בערכאות שלהם כתבו התוספות דהיינו לומר שאע״פ שנראה כמקיים המקח שרי:\",3,0],[8,385,8,13,\"המפקיר עבדו וכו'. מימרא דרב ור\\\"י שם (דף ל\\\"ח ע\\\"ב).\",1,0],[8,385,8,13,\"ומ\\\"ש ואם מת האדון וכו'. מסקנא שם:\",2,0],[8,385,8,14,\"עבד שברח מבית האסורים וכו' וכופין את רבו וכו'. שם מימרא דרבי יוחנן:\",1,0],[8,385,8,15,\"עבד שנשבה אם וכו'. משנה שם (דף ל\\\"ז ע\\\"ב) עבד שנשבה ופדאוהו אם לשם עבד ישתעבד אם לשם ב\\\"ח לא ישתעבד רשב\\\"ג אומר בין כך ובין כך ישתעבד ובגמרא במאי עסקינן אילימא לפני יאוש לשם ב\\\"ח אמאי לא ישתעבד אלא לאחר יאוש לשם עבד אמאי ישתעבד אמר אביי לעולם לפני יאוש וכו' רבא אמר לעולם לאחר יאוש ולשם עבד ישתעבד לרבו שני לשם ב\\\"ח לא ישתעבד לא לרבו ראשון ולא לרבו שני לרבו שני לא דהא לשם ב\\\"ח פרקיה לרבו ראשון נמי לא דהא לאחר יאוש הוה רשב\\\"ג אומר בין כך ובין כך ישתעבד כדחזקיה דאמר חזקיה מפני מה אמרו בין כך ובין כך ישתעבד שלא יהא כל אחד ואחד הולך ומפיל עצמו לגייסות ומפקיע עצמו מיד רבו וכתב הרי\\\"ף חזינן לגאון דפסק הלכה כרבנן ונראה ממה שכתב הרשב\\\"א והר\\\"ן בשם הרמב\\\"ן שהם סוברים שהרי\\\"ף סובר כדברי הגאון דהלכה כרבנן ואע\\\"פ שהרא\\\"ש כתב בשם הראב\\\"ד דהלכה כרשב\\\"ג והביא כמה ראיות הרשב\\\"א כתב בשם הרמב\\\"ן ז\\\"ל לדחות כל ראיות הראב\\\"ד והעלה דהלכה כרבנן וכך הם דברי רבינו.\",1,0],[8,385,8,15,\"ומ\\\"ש דאם לא נתייאש ממנו רבו ראשון שנוטל פדיונו מרבו תוספתא כתבוה שם הרשב\\\"א והר\\\"ן ז\\\"ל עבד שנשבה ופדאוהו לשם עבד ישתעבד ורבו נותן דמיו לשם ב\\\"ח לא ישתעבד רשב\\\"ג אומר בין כך ובין כך ישתעבד ורבו נותן דמיו וכתב הר\\\"ן דלפני יאוש מיתוקמא ומש\\\"ה לת\\\"ק משתעבד לרבו ראשון ומ\\\"מ ילפינן מינה דכשהוא משתעבד לרבו ראשון חייב ליתן דמיו לשני ופשטא דהך תוספתא משמע דאפילו לשם ב\\\"ח צריך ראשון ליתן דמיו אלא שהרמב\\\"ם כתב דלשם ב\\\"ח חוזר לרבו ראשון בלא כלום עכ\\\"ל ואני תמה על מ\\\"ש דפשטא דתוספתא משמע דאפילו לשם ב\\\"ח צריך ראשון ליתן דמיו דאדרבה פשטא משמע איפכא דלגבי לשם עבד תני ורבו נותן דמיו ולגבי לשם ב\\\"ח לא תני הכי ועוד דכיון דלשם ב\\\"ח פדאו הרי הפקיר דמיו והיאך יעלה על הדעת שיטול פדיונו מרבו ראשון:\",2,0],[8,385,8,15,\"כתב הראב\\\"ד עבד שנשבה וכו' א\\\"א זהו כרשב\\\"ג ואביי עכ\\\"ל. ביאור דבריו לומר שדין זה אינו כמ\\\"ש רבינו כחכמים וכדאוקי רבא דאין הלכה אלא כרשב\\\"ג וכמו שכתבתי שזהו דעתו של הראב\\\"ד וכאביי וכמ\\\"ש הרשב\\\"א דמאן דפסק כרשב\\\"ג היינו משום דמוקי מתניתין בלפני יאוש כאוקימתא דאביי:\",3,0],[8,385,8,16,\"עבד שעשאו רבו אפותיקי ושיחררו וכו'. משנה בפרק השולח (גיטין דף מ' ע״ב) עבד שעשאו אפותיקי לאחרים ושיחררו [שורת הדין] אין העבד חייב כלום אלא מפני תיקון העולם כופין את רבו ועושה אותו ב״ח וכותב שטר על דמיו רשב״ג אומר אינו כותב אלא משחרר ובגמרא מי שחררו אמר רב רבו ראשון שורת הדין אין העבד חייב כלום לרבו שני כדרבא דאמר רבא הקדש חמץ ושיחרור מפקיעין מידי שעבוד אלא מפני תיקון העולם שמא ימצאנו בשוק ויאמר לו עבדי אתה כופין את רבו שני ועושה אותו ב״ח וכותב עבד שטר על דמיו רשב״ג אומר אין העבד כותב אלא המשחרר כותב במאי קא מיפלגי במזיק שעבודו של חבירו קמיפלגי דמר סבר חייב ומר סבר פטור וכתבו התוס' והרשב״א והר״ן דמתניתין באפותיקי מפורש מיירי דא״ל לא יהא לך פרעון אלא מזו דאי באפותיקי סתם למה ליה למשחרר דלכתוב השתא הא כתוב וקאי דהא משתעבד ליה כל נכסיו ופסקו הרי״ף והרא״ש כרשב״ג דדינא דגרמי הוא:\",1,0],[8,385,8,17,\"עבד שהשיאו רבו בת חורין. בפרק השולח (גיטין דף ל״ט מ') אמר ר' זירא וכו' אמר רב עבד שנשא ב״ח בפני רבו יצא לחירות ואוקימנא דהיינו כשהשיאו רבו אשה דאי לאו דשחרריה לא הוה מעביד ליה איסורא על ידיה.\",1,0],[8,385,8,17,\"ומ\\\"ש או שהניח לו רבו תפילין בראשו. גם זה שם.\",2,0],[8,385,8,17,\"ומ\\\"ש או שא\\\"ל רבו לקרות שלשה פסוקים וכו'. נלמד מהא דהניח לו רבו תפילין בראשו וכ\\\"כ הרא\\\"ש שם.\",3,0],[8,385,8,17,\"ומ\\\"ש וכופין את רבו לכתוב גט שחרור בנוסחת הרי\\\"ף והרא\\\"ש מסיים בהא דא\\\"ר זירא עבד שנשא בת חורין בפני רבו ולא עוד אלא שכופין את רבו וכותב לו שטר שיחרור:\",4,0],[8,385,8,17,\"וכן אם נדר נדר וכו'. בפרק בתרא דנזיר (דף ס\\\"ב ע\\\"ב) תנן הפר לעבדו יצא לחירות ומשלים נזירתו זו היא גירסת רבינו ומפרש דתרתי קתני בהפר חדא דיצא לחירות תרתי דמשלים נזירותו אבל הראב\\\"ד היה גורס הפר לעבדו ויצא לחירות משלים נזירותו לפיכך כתב א\\\"א נראה לי שיבוש הוא נשתבש בלשון המשנה וכו'. דעתו לומר שאע\\\"פ שהוא גורס יצא לחירות בלא וי\\\"ו ה\\\"ל לפרש מפני קושיא זו דחדא קתני עבד שנדר והפר לו רבו ואח\\\"כ יצא העבד לחירות משלים נזירותו ונראה שטעם רבינו שאע\\\"פ שבמה שהוא מפר נדרו נראה שיש לו רשות עליו מ\\\"מ כיון שהיה לו רשות עליו לכופו ולא כפאו גילה דעתו שהפקיר שעבודו דהפרה לגבי כפייה הפקעת שעבוד היא:\",5,0],[8,385,8,17,\"אבל אם לוה מעבדו וכו' עד ולא מיחה בו. ברייתא בפ' השולח (גיטין דף מ'):\",6,0],[8,385,8,18,\"ומ\\\"ש ואסור לאדם ללמד את עבדו תורה ואם למדו לא יצא לחירות. נלמד ממה שאמרו שאם קרא שלשה פסוקים בבה\\\"כ בפני רבו לא יצא לחירות:\",1,0],[8,385,8,19,\"הלוקח עבד מן העכו״ם וקדם וטבל וכו'. בפ' החולץ (יבמות מ״ה:) א״ר חמא בר גוריא אמר רב הלוקח עבד מן העכו״ם וקדם וטבל לשם בן חורין קנה עצמו בן חורין מאי טעמא עכו״ם גופא לא קני ליה מאי דקני ליה הוא דמקני ליה לישראל וכיון דקדם וטבל לשם בן חורין אפקעיה לשעבודיה וכו'. אמר שמואל וצריך לתקפו במים ופירש רש״י לתקפו במים כשמטבילו לשם יהדות לעבדות צריך שיתקפנו לתת עליו עול מלאכה במים כדי שתהא נראית כטבילת עבדות שאפילו יאמר הוא לשם ב״ח לא יהא ממשות בדבריו ואיתמר עלה מתיב רב חסדא מעשה בבלוריא הגיורת שקדמו עבדיה וטבלו לפניה ובא מעשה לפני חכמים ואמרו קנו עצמם בני חורין טעמא דבפניה הא שלא בפניה לא אמר רבא בפניה בין בסתם בין במפרש שלא בפניה במפרש אין בסתם לא זו היא גירסת הרי״ף והיא גירסת רבינו אף על פי שרש״י והרא״ש גורסים בענין אחר:\",1,0],[8,385,8,20,\"ישראל שתקף בעכו\\\"ם קטן וכו'. זה פירש רבינו על מה שאמרו בפ\\\"ק דכתובות (דף יא) א\\\"ר הונא גר קטן מטבילין אותו על דעת בית דין:\",1,0],[8,385,8,21,\"גר שקדמו וכו'. נראה שלמד כן מההיא דמעשה בבלוריא הגיורת שקדמו עבדיה וטבלו לפניה משמע דלפניה ובפניה הוה והיינו דדייק גמרא טעמא דבפניה וכתבה רבינו לעיל בסמוך וכאן כתבה לענין שטבלו לפניה ונ\\\"ל דגרסינן הכא בדברי רבינו וטבלו לפניו בלמ\\\"ד:\",1,0],[8,385,9,1,\"ישראל שבא על שפחה כנענית וכו'. בפרק שמיני דיבמות (דף ע\\\"ח ע\\\"ב) ובספ\\\"ג דקידושין שולד שפחה כמותה.\",1,0],[8,385,9,1,\"ומ\\\"ש אע\\\"פ שהיא שפחתו. מבואר במכילתא ובתורת כהנים פרשת בהר סיני ועיין במ\\\"ש רבינו ובדברי מ\\\"מ פרק רביעי מהלכות נחלות:\",2,0],[8,385,9,1,\"כתב הראב\\\"ד לא נהיר ומהו לכל דבר עכ\\\"ל. כך מצאתי בנוסחא אחת ונראה שטעמו מפני שכתב הרי\\\"ף בפ\\\"ד דיבמות בשם קצת גאונים שאם בא על שפחתו הולד חשוב בנו וקצתם מספקא להו ומפני כך כתב דלא נהיר מה שכתב רבינו בפשיטות שאע\\\"פ שהיא שפחתו הוא עבד לכל דבר דספיקא הוי ואזלינן ביה לחומרא שהוא זוקק את אשת אחיו לחליצה ואינו פוטר את אשת אביו ורבינו אזיל לטעמיה שכתב בפ\\\"א מהלכות יבום וחליצה דפשיטא ליה שאינו זוקק ולא פוטר:\",3,0],[8,385,9,2,\"אחד הקונה עבד כנעני מישראל וכו'. בפרק החולץ (יבמות דף מ״ה ע״ב) אהא דאמר רב הלוקח עבד מן העכו״ם וקדם וטבל לשם ב״ח קנה עצמו ב״ח מ״ט עכו״ם גופא לא קני מאי דקני ליה הוא דמקני לישראל וכיון דקדם וטבל לשם ב״ח אפקעה לשעבודיה וכו' אמר רב אויא לא שאנו אלא בלוקח מן העכו״ם אבל עכו״ם גופיה קני דכתיב וגם מבני התושבים הגרים עמכם מהם תקנו אתם קונים מהם ולא הם קונים מכם ולא הם קונים זה מזה לא הם קונים מכם למאי אילימא למעשה ידיו אטו עכו״ם לא קני לישראל למעשה ידיו וכו' אלא לאו לגופיה וקאמר רחמנא אתם קונים מהם אפילו גופו ואע״ג דפריך ליה רב אחאי כתבו הרי״ף והרא״ש דהלכתא כוותיה ופירש״י אבל עכו״ם גופיה עכו״ם שמכר עצמו לישראל קנאו ישראל לגופיה ואם קדם וטבל לשם בן חורין לא קנה עצמו ב״ח.\",1,0],[8,385,9,2,\"ומ\\\"ש וכן מוכר בניו ובנותיו שנאמר וממשפחתם אשר עמכם אשר הולידו בארצכם מבואר בכתוב:\",2,0],[8,385,9,3,\"אחד מן האומות שבא על שפחה כנענית שלנו וכו'. בפרק הערל (יבמות דף ע\\\"ח ע\\\"ב) ובסוף פרק ג' דקידושין (דף ס\\\"ח ע\\\"ב) כי אתא רבין אמר רבי יוחנן באומות הלך אחר הזכר כדתניא מנין לאחד מן האומות שבא על הכנענית והוליד בן שאתה רשאי לקנותו בעבד שנאמר וגם מבני התושבים הגרים עמכם מהם תקנו יכול אפילו אחד מהכנענים שבא על אחת מהאומות והוליד בן אתה רשאי לקנותו בעבד תלמוד לומר אשר הולידו בארצכם מן הנולדים בארצכם ולא מן הגרים בארצכם ומפרש רבינו דלענין אם הולד עבד או בן חורין איתמר אבל רש\\\"י פירש דלענין אם יש לולד דין ז' עממין והוא בכלל לא תחיה כל נשמה או לא איתמר ומכל מקום יש לתמוה עליו שר\\\"י אמר הלך אחר הזכר ולפי דברי רבינו אינו הולך אלא אחר הנקבה שכתב שאם האם כנענית הבן עבד כנעני ואם האם משאר אומות אין הבן עבד והראב\\\"ד מפרש כפירוש רש\\\"י ולפיכך השיג על רבינו וכתב אחד מן האומות שבא על שפחה כנענית שלנו א\\\"א זהו בהיפך ממה שאמרו בגמרא וכו'. ולדעת רבינו י\\\"ל דמשמע ליה דלא מיירי התם לענין אם הוא בכלל לא תחיה כל נשמה שאינו ענין לסוגיות דשם והוא גורס בדברי ר' יוחנן באומות הלך אחר הנקבה וגורס בשתי הבבות דמייתי לה מאשר הולידו בארצכם וה\\\"פ מניין לאחד מן האומות שבא על הכנענית שאתה רשאי לקנותו בעבד כלומר שהוא עבד שנאמר אשר הולידו בארצכם דהיינו שהאם היא מארצכם שהיא כנענית יכול שאפילו אחד מהכנענים שבא על אחת מהאומות שהולד עבד כלומר ולעולם נלך אחר צד העבדות בין שהאב כנעני בין שהאם כנענית וגלי קרא באם כנענית והוא הדין לאב כנעני תלמוד לומר אשר הולידו בארצכם כלומר ועבד לא אמרינן ביה הולידו דאין לו יחס והוי כאילו אמר לא אמרתי שנלך אחר צד עבדות אלא במי ששייך ביה הולדה לאפוקי עבד דלא שייך ביה הולדה שאין הולכים אחר צד עבדות שלו וסמ\\\"ג כתב בשם הגמרא כדברי רבינו:\",1,0],[8,385,9,4,\"מלך עכו״ם שעשה מלחמה והביא שביה וכו'. נראה שטעמו מדגרסינן בפרק החולץ (יבמות דף מ״ו) אמר ליה רב פפא לרבא חזי מר הני דבי פפא בר אבא דיהבי זוזי אאינשי לכרגייהו ומשתעבדי בהו וכי נפקי צריכי גיטא דחירותא או לא אמר ליה הכי אמר רב ששת מוהרקייהו דהני בטפסיא דמלכא מנח ומלכא אמר מאן דלא יהיב כרגא משתעבד למאן דיהיב כרגא ופירש רש״י והתוספות והרא״ש דעכו״ם היו הנקנים וכתבו התוספות מספקא ליה אי דינא דמלכותא דינא או לא ואף על גב דלא קני גופא הכא קני או דילמא ה״נ לא קני אלא למעשה ידיו עכ״ל וכיון דפשט ליה דצריכי גיטא דחירותא אלמא גופם קנוי משום דינא דמלכותא וזהו\",1,0],[8,385,9,4,\"שכתב והרי הוא כעבד כנעני לכל דבר כלומר שגופו קנוי לגמרי ומיהו איכא לספוקי אם היינו דוקא בישראל הקונה את העכו\\\"ם בדינים אלו אבל עכו\\\"ם שקנה עכו\\\"ם אחר בדינים אלו לא קנה גופו דאמרינן בפרק השולח שבאי גופיה מי קני ליה אין קני ליה למעשה ידיו דאמר ריש לקיש מניין לעכו\\\"ם שקונה את העכו\\\"ם למעשה ידיו שנאמר וגם מבני התושבים וכו' ולא הם קונים זה את זה לגופו הרי מפורש דאין עכו\\\"ם קונה את עכו\\\"ם לגופו ואפילו לקחו בשביה ואם כן אפשר דאף בדינא דמלכותא נמי לא קני ליה דכיון דעכו\\\"ם לאו בר מיקני עכו\\\"ם אחר לגופו הוא בדינא דמלכותא נמי לא קני ליה או אפשר דאלים דינא דמלכותא לאקנויי ליה לגופיה וההיא דפרק השולח בששבאו מעצמו שלא בדינא דמלכותא דאילו בדינא דמלכותא הוה קני ליה גופיה אף על פי שהוא עכו\\\"ם וזה נראה יותר אבל מדברי הרשב\\\"א בתשובה נראה שסובר כלשון ראשון:\",2,0],[8,385,9,5,\"עכו״ם שקנה עכו״ם לעבדות לא קנה גופו וכו'. קשה שהרי בהדיא אמרינן בפרק החולץ (יבמות דף מ״ו) דלוקח עבד מן העכו״ם לא קנה גופו משום דעכו״ם לא מצי מקנה לישראל אלא מאי דאית ליה ביה דהיינו זכות מעשה ידיו וכתבו רבינו בפרק שקודם זה והיאך כתב כאן עכו״ם שקנה עכו״ם לעבדות וכו' אעפ״כ אם מכרו לישראל הרי גופו קנוי לישראל וי״ל דה״ק עכו״ם שמכר עצמו לעכו״ם לא קנה העכו״ם גופו ואעפ״כ אם העכו״ם מכר עצמו לישראל הרי גופו קנוי לישראל כדאמרינן בגמרא אתם קונים מהם ויותר נ״ל דה״ק עכו״ם שקנה עכו״ם לעבדות לא קנה גופו אעפ״כ אם בא העכו״ם הקונה הזה ומכרו לישראל הרי גופו קנוי לישראל אחר שיטבילנו לשם עבדות דלא אמרו דאין גופו קנוי לישראל אלא קודם שיטבילנו לשם עבדות אבל אחר שהטבילו לשם עבדות קני ליה לגופיה:\",1,0],[8,385,9,6,\"האשה קונה שפחות ואינה קונה עבדים. ברייתא בפ' איזהו נשך (בבא מציעא דף ע״א).\",1,0],[8,385,9,6,\"ועל מ\\\"ש רבינו שאינה אסורה לקנות אלא עבד בן תשע שנים וכו' כתב הטור ונראה דאין להתיר בפחות מבן תשע שמא תשהנו אף לאחר שיגדיל עכ\\\"ל. ויש לומר שרבינו לא חייש להכי משום דכיון דעיקרא דמילתא לא הוי אלא חששא בעלמא דיינו שנאסור לה לקנות עבד ראוי לביאה אבל שנגזור שלא תקנה שאינו ראוי משום דלכשיגדיל אתיא לידי חשד זו אין לנו:\",2,0],[8,385,9,6,\"וכן אסור לאדם לשחרר עבד כנעני וכו'. בפרק שלשה שאכלו (ברכות דף מ״ז ע״ב) ובפרק השולח (גיטין דף ל״ח ע״ב) מימרא דרב יהודה. ותיבת וכן שכתב אינו נוח לי שנראה שאין לו קשר עם מה שלמעלה:\",3,0],[8,385,9,6,\"ומ\\\"ש ומותר לדבר מצוה אפילו למצוה של דבריהם כגון שלא היו עשרה בבית הכנסת וכו'. ג\\\"ז שם וכתב הר\\\"ן בפרק השולח על הא דעובר בעשה דלאו עשה גמור הוא דא\\\"כ היכי דחינן ליה משום מצוה דעשרה בבה\\\"כ ויש מתרצים שלא אמרה תורה לעולם בהם תעבודו אלא משום שלא יתן להם מתנת חנם כענין שכתוב בעכו\\\"ם לא תחנם וכיון דאיכא מצוה לאו משום חנינה דידהו קא עביד אלא לצורך והו\\\"ל כנותן דמי עצמו עכ\\\"ל. ובגמ' פרק שלשה שאכלו פריך על הא דאמרינן להשלים עשרה בבה\\\"כ מצוה הבאה בעבירה היא ומשני מצוה דרבים שאני.\",4,0],[8,385,9,6,\"ומ\\\"ש וכן שפחה שנוהגים בה העם מנהג הפקר וכו'. בפרק השולח שם פלוגתא דאביי ורבינא ופסקו הפוסקים כרבינא דאמר הכי:\",5,0],[8,385,9,7,\"יכול הרב לומר וכו'. מסקנא בגמרא פ\\\"ק דגיטין (דף י\\\"ב ע\\\"א).\",1,0],[8,385,9,7,\"ומ\\\"ש בד\\\"א בעבדיו וכו' אבל עבדים שהכניסה לו אשתו וכו'. דברים של טעם הם והראב\\\"ד כתב לא נתברר לי דבר זה וכו'. וי\\\"ל שאפשר שרבינו יודה בכך ולא איירי אלא באומר עשה עמי ואיני זנך כמו שכתב בתחלת הבבא:\",2,0],[8,385,9,7,\"וכתב הטור בד\\\"א שיכול לומר עשה עמי ואיני זנך שהשנים כתקנן שימצא מרחמים שירחמו עליו אבל בשנת בצורת אינו יכול לומר עשה עמי ואיני זנך אבל יכול לומר צא מעשה ידיך במזונותיך אע\\\"פ שהיא שנת בצורת ושמא לא יספיקו לו מעשה ידיו למזונותיו וטעמו מדאיתא בגמרא שם תניא רשב\\\"ג אומר יכול העבד לומר לרבו בשני בצורת או פרנסני או הוציאני לחירות כי היכי דחזו לי אינשי ומרחמי לי ורבנן סברי מאן דמרחם אבני חרי אעבד נמי רחומי רחים ואע\\\"ג דהאי אוקימתא איתמרא בגמרא למימר דבין לרשב\\\"ג בין חכמים אין הרב יכול לומר לעבד עשה עמי ואיני זנך ובמסקנא אסיקנא דיכול לומר כן מכל מקום כיון דא\\\"א לאוקמי ברייתא באומר לו עשה עמי ואיני זנך דמר סבר יכול ומר סבר אינו יכול דא\\\"כ מאי או פרנסני או הוציאני לחירות דקאמר או פרנסני או תן לי מעשה ידי בפרנסתי מיבעי ליה ועוד מ\\\"ש בשני בצורת דנקט כדמקשינן בגמרא ע\\\"כ אית לן לאוקומה באומר צא מעשה ידיך במזונותיך אבל לומר לו עשה עמי ואיני זנך בין לרשב\\\"ג בין לחכמים אינו יכול וכי היכי דלא תיקשי אמסקנא דגמרא אית ל\\\"ל דע\\\"כ לא אסיקנא דיכול אלא בשאר שנים אבל לא בשני בצורת וכ\\\"כ התוספות והרשב\\\"א והרא\\\"ש וכך הם דברי הטור ופסקו כחכמים אבל הרי\\\"ף כתב מסקנא דגמרא סתם ולא חילק משמע דס\\\"ל דכיון דלההיא אוקימתא לכ\\\"ע אין הרב יכול לומר עשה עמי ואיני זנך ואנן אסקינן סתמא דיכול ולא מפלגינן בין שני בצורת לשאר שנים ליתא לההיא אוקימתא וע\\\"כ מוקמינן לה דפליגי באי יכול לומר לו עשה עמי ואיני זנך או לא והא דנקט או הוציאני לחירות וכן הא דנקט שני בצורת לאו דוקא וכן דעת רבינו שסתם ולא חילק:\",3,0],[8,385,9,8,\"מותר לעבוד בעבד כנעני בפרך. כן משמע מדלא אזהר רחמנא שלא לרדות בפרך אלא בע\\\"ע שהוא ישראל גמור.\",1,0],[8,385,9,8,\"ומ\\\"ש ואע\\\"פ שהדין כך מדת חסידות ודרכי חכמה שיהיה אדם רחמן וכו' עד סוף הפרק. הם דברי רבינו ראויים אליו.\",2,0],[8,385,9,8,\"ומ״ש חכמים הראשונים היו נותנים לעבד מכל תבשיל ותבשיל וכו'. בירושלמי פרק החובל אהא דאמר רבי יוחנן הקוטע יד עבד חבירו רבו נוטל נזקו וצערו ריפוי שבתו ובשתו והא רבי יוחנן אכיל קופר ויהיב לעבדיה שתי חמר ויהיב לעבדיה וקרי אנפשיה הלא בבטן עושני עשהו אמרי תמן במדת הדין ברם הכא במדת רחמים ובגמרא דידן פרק אע״פ (כתובות דף ס״א) אבוה בר איהי ומנימין בר איהי חד ספי מכל מינא ומינא וחד ספי מחד מינא מר אשתעי אליהו בהדיה ומר לא משתעי אליהו בהדיה הנהו תרי חסידי וכו' מר מקדים ספי ומר מאחר ספי דקדים ספי משתעי אליהו בהדיה דמאחר ספי לא משתעי אליהו בהדיה ובס״פ הניזקין (גיטין דף ס״ב) אסור לאדם שיטעום כלום עד שיתן מאכל לבהמתו שנאמר ונתתי עשב בשדך לבהמתך והדר ואכלת ושבעת:\",3,0],[8,385,9,8,\"בריך רחמנא דסייען.\",4,0],[8,386,1,8,\"והבעל יורש את כל נכסי אשתו מד\\\"ס. כתב הרב המגיד שסובר רבינו שהיא מדבריהן וכבר היה אפשר לומר שסובר רבינו שהיא מדאורייתא ומ\\\"ש שהיא מד\\\"ס לטעמיה אזיל שסובר שכל דבר שאינו מפורש בתורה נקרא ד\\\"ס אלא שבפ\\\"ו משמע בהדיא מדברי רבינו שסובר שהיא מדבריהם שכתב ירושת הבעל אע\\\"פ שהיא מדבריהם עשו חיזוק לדבריהם כשל תורה:\",1,0],[8,386,2,10,\"הבא אחר נפלים וכו'. כתב הרב המגיד מפורש בגמרא שאין הלכה כשמואל וכו'. ואני אומר שאין דבריו אלה מכוונים דשמואל לא אמר אלא לענין חמש סלעים אבל לענין נחלה לדידיה נמי בן תשעה שהוציא ראשו חי הבא אחריו אינו בכור וכן מבואר בגמרא:\",1,0],[8,386,3,4,\"אין הבכור נוטל פי שנים בשבח וכו' והוא שישתנו הנכסים וכו'. הר\\\"ן כתב לענין הלכה קי\\\"ל כרבא בחפורי והוו שבלי שלפופי והוו תמרי דפליגי בהו רבי ורבנן אסור לעשות כדברי רבי ומיהו אם עשה עשוי וכן פסק ר\\\"ח דאע\\\"ג דאמר רב פפא לקמן דאין הבכור נוטל פי שנים במלוה וקי\\\"ל כוותיה לא פליג אדרבא ואפשר דרב פפא לא אמר אלא במלוה קסבר כיון דליתיה ברשותיה ראוי גמור הוא אבל בשלפופי והוו תמרי חפורי והוו שבלי דאיתיה ברשותיה אפשר דמודה לרבא ואם עשה עשוי אבל ראיתי להרמב\\\"ם בפ\\\"ג מהל' נחלות שכתב אין הבכור נוטל פי שנים בחפורי שנעשו שבלים וכפניות שנעשו תמרים וכיון שלא כתב יותר מכלל דס\\\"ל דאפי' עשה אינו עשוי וכדבריו נ\\\"ל דהא סוגיין רהטא דטפי מיקריא מוחזק מלוה משבח דאיפליגו ביה רבי ורבנן לפיכך נ\\\"ל דברי הרמב\\\"ם ז\\\"ל עיקר אע\\\"פ שגדולי האחרונים כתבו בהפך עכ\\\"ל:\",1,0],[8,386,3,6,\"בד\\\"א כשלא מיחה אבל מיחה באחיו וכו'. כתב ה\\\"ה וקי\\\"ל דרבה ורב יוסף הלכתא כרבה עכ\\\"ל. ויש לתמוה עליו חדא דאנן איפכא תנינן דהלכתא כרב יוסף וכדאיתא בפרק ועוד דמשמע דליכא פלוגתא בין רבה ורב יוסף בהא דהא אסיקנא דרב יוסף לא אמר אפילו דרכום אלא ליתן לו היזק ענביו משמע בהדיא דמחאה דענבים לא מהניא [להיכא דדרכום] לכ\\\"ע דלא איירי רב יוסף אלא לענין אם דרכו הפשוטים הענבים שלא מדעת הבכור ונפחתו שמשלמים לו דמי היזק ענביו פי שנים ומר אמר חדא ומר אמר חדא ולא פליגי וצ\\\"ע:\",1,0],[8,386,3,9,\"שומרת יבם [שמתה] אפילו עשה בה אחד וכו'. בפרק האשה שנפלו כתב הר\\\"ן בשם הרמב\\\"ן ז\\\"ל שרבינו מפרש דהויה דאביי ורבא לפרוקה לדב\\\"ש אתמר ורבא ה\\\"ק אי נפלו לה כשהיא תחתיו דבעל דכ\\\"ע עדיפא מידה דודאי ס\\\"ל בכל מקום דאיהו מוחזק טפי מינה הילכך לב\\\"ש דמספקא להו אי נשואין עושה נכסי בחזקת יורשי הבעל הן ומיהו לב\\\"ה פשיטא להו דאפילו אירוסין ודאי אינה עושה הילכך ל\\\"ש נפלו כשהיא שומרת יבם לא שנא נפלו כשהיא תחתיו דבעל לעולם נכסים בחזקת יורשי האב ולפיכך כתב דמשפחת בית אביה יורשים נכסי מלוג בסתם דמשמע אפי' נפלו תחתיו דבעל והוא ז\\\"ל מפרש נכסים בחזקתן נצ\\\"ב כפירש\\\"י ומאי בחזקתן יחלוקו עכ\\\"ל:\",1,0],[8,386,4,3,\"אמר עבדי וחזר ואמר בני וכו' ואם היו קורים לו עבד בן מאה וכו'. נראה שרבינו היה גורס בגמ' התם דקרו ליה עבדא בר אמה:\",1,0],[8,386,5,1,\"לפיכך מי שמת והניח בן וטומטום וכו'. יש לתמוה למה לא יהא נזון הטומטום דאפילו את\\\"ל שהיא נקבה מזונות מיהא אית לה. וי\\\"ל דלא איירי רבינו אלא לענין ירושה אבל אין הכי נמי שהוא נזון דממ\\\"נ יש לו מזונות:\",1,0],[8,386,5,7,\"נפל הבית עליו ועל בן בתו וכו'. כתב ה\\\"ה שיש לתמוה היאך פסק רבינו כברייתא וכו' עד לא מצא בזה תירוץ. והנה הרא\\\"ש בכלל פ\\\"ד כתב לתרץ קושיא זו שיש לחלק דאם נפל הבית עליו ועל אמו שאם מת הבן תחלה ואח\\\"כ האם באו נכסים ליד קרוביה לכן מעמידים כל הנכסים לאלתר ביד קרוביה אבל בנפל הבית עליו ועל בן בתו ממ\\\"נ הנחלה ממשמשת בקבר לבת שהיא קרובה לבת וספק מת האב תחלה ותחזור ותמשמש למעלה לקרוב קרוב קודם הילכך הואיל וממ\\\"נ ממשמשת הנחלה מן האב לבת אע\\\"פ שהיא עדיין בחזקת אותו שבט הואיל ויצאה מיד מי שהיתה עד היום וספק תורידנה למטה או תעלנה למעלה יחלוקו:\",1,0],[8,386,7,3,\"אבל היו לו סימנים מובהקין בגופו וכו' אם אבד זכרו אחר כך יורדין לנחלה בעדות זו וכו'. משמע מדבריו אלה שאין צריך שנשמע שמת. וממה שכתב לקמן בסמוך נראה שצריך שנשמע אחר כך שמת וצריך עיון:\",1,0],[8,386,7,5,\"שבוי שנשבה וברח וכו'. כתב ה\\\"ה וממימרא זו יש ללמוד שאין מורידין קרוב למטלטלים היינו דוקא בנשבה אבל בלא נשבה מורידין קרוב למטלטלין של קטן אעפ\\\"י שאין מורידין אותו לקרקעות וזה מבואר בדברי רבינו ובדברי הרב המגיד פרק עשירי:\",1,0],[8,386,7,10,\"שמעו בו שמת וכו'. יש לתמוה למה השמיט רבינו הא דתניא בגמרא דשמעו בו שמת שממשמשין ובאים וקדם ותלש ואכל ה\\\"ז זריז ונשכר:\",1,0],[8,386,8,2,\"לעולם אין מורידין קרוב לנכסי קטן. בפרק עשירי כתב דהני מילי בקרקעות אבל במעות ממנין אפילו קרוב:\",1,0],[8,386,9,1,\"האחין שעדיין לא חלקו וכו' עד אבל אם שבחו נכסים מעצמן השבח לאמצע. כתב ה\\\"ה לפי מה שנמצא בספרי רבינו גירסתו בגמ' מוחלפת משלנו עד זה מורה לשון רבינו. ול\\\"נ שהיה גורס רבינו ל\\\"ש אלא ששבחו נכסים מחמת עצמן אבל שבחו נכסים מחמת נכסים השבח לאמצע ואסיפא דמתני' קאי דקתני אם אמרו ראו מה שהניח לנו אבא הרי אנו עושים ואוכלים השביחו לעצמן קאמר דה\\\"מ כשהשביחו מחמת עצמן דהיינו שהוציאו הוצאות משלהם או שטרחו בגופם אבל שבחו נכסים מחמת נכסים דהיינו ששכרו פועלים מממון תפיסת הבית אפילו אמרו ראו מה שהניח לנו אבא השביחו לאמצע:\",1,0],[8,386,11,11,\"ומי שנשתטה או נתחרש בית דין פוסקין עליו צדקה וכו'. הר\\\"ן בפרק נערה שנתפתתה כתב על דברי רבינו ולא ידעתי למה דלרב חסדא דאמר תכשיט נהי דאברייתא קאי אפשר דדבר אחר דאמר מר עוקבא גבי נשתטה הכי נמי מפרש ליה ותכשיט שמענו אבל צדקה מנין עכ\\\"ל. ואפשר לומר שטעם רבינו משום דמסתמא כל אדם ניחא ליה למעבד צדקה מממוניה וגם כי ממונו של אדם משועבד לעשות ממנו צדקה וכשהלך למ\\\"ה אין פוסקין צדקה מפני שהוא עושה צדקה בכל מקום שהוא והיינו טעמא דאיפליגו רב חסדא ורב יוסף בפירוש דבר אחר דגבי מי שהלך למדינת הים ולא איפליגו בדבר אחר דגבי מי שנשתטה:\",1,0],[8,387,1,1,\"מצות עשה של תורה למנות שופטים ושוטרים וכו'. ברייתא פ' קמא דסנהדרין (דף ט\\\"ז:) דיליף מקרא שופטים ושוטרים שמעמידין שופטים ושוטרים לכל עיר ועיר ודע דהתם [יליף] מקרא שמעמידין שופטים ושוטרים לכל שבט ושבט וצריך טעם למה השמיטו רבינו:\",1,0],[8,387,1,2,\"אין אנו חייבין להעמיד וכו' אבל בח\\\"ל וכו'. ברייתא ספ\\\"ק דמכות (דף ז') מה ת\\\"ל בשעריך בשעריך אתה מושיב בתי דינין בכל פלך ופלך ובכל עיר ועיר ובחו\\\"ל אתה מושיב בכל פלך ופלך ואי אתה מושיב בכל עיר ועיר ואם נוסחא זאת היתה לרבינו כך צריך לגרוס בדבריו אבל בח\\\"ל אין אנו חייבין להעמיד בית דין אלא בכל פלך ופלך [ולא בכל עיר ועיר] או נוסחא אחרת נזדמנה לו בגמ' ופירוש פלך אפרכיה:\",1,0],[8,387,1,3,\"קובעין בתחלה וכו'. ומניינם ע\\\"א וכו'. משנה פרק קמא דסנהדרין:\",1,0],[8,387,1,3,\"הגדול שבחכמה וכו'. ומושיבין הגדול שבשבעים משנה לראש ויושב מימינו והוא הנקרא אב בית דין ושאר השבעים וכו'. כל הגדול מהם בחכמה יהיה קרוב לנשיא משמאלו יותר מחבירו. בתוספת' דסנהדרין הנשיא יושב באמצע וזקנים יושבים מימינו ומשמאלו א\\\"ר אליעזר ברבי צדוק כשהיה רבן גמליאל יושב בבית דין ביבנה אבא יושב מימינו וזקנים משמאלו מפני מה אחד יושב מימינו של זקן מפני כבודו של זקן ע\\\"כ. ויש לתמוה על דברי רבינו שנראה שאינם כדברי ת\\\"ק שאמר זקנים יושבים מימינו ומשמאלו דמשמע שקצתם מימינו וקצתם משמאלו ואילו רבינו כתב שלא היה מימינו אלא אב ב\\\"ד. ונ\\\"ל שסובר רבינו דר\\\"א בר' צדוק לא לאיפלוגי אתא אלא לפרושי דמאי דאמר ת\\\"ק זקנים יושבים מימינו ומשמאלו לאו למימר שהיו כ\\\"כ זקנים מימינו כמו משמאלו שלא היה יושב מימינו כ\\\"א אחד בלבד ומה טעם יושב אותו אחד לימינו כדי לכבד אותו זקן וסובר רבינו דמסתמא אותו זקן שיושב לימינו הוא האב בית דין שהוא הגדול שבשבעים:\",2,0],[8,387,1,3,\"ואיכא למידק בדברי רבינו שכתב יושבים לפניו כפי שניהם וכפי מעלתם ואח\\\"כ כתב כל הגדול ממנו בחכמה פתח בשנים וסיים בחכמה ונ\\\"ל שמ\\\"ש וכפי מעלתם היינו כפי מעלתם בחכמה וכשכתב כל הגדול מחבירו בחכמה היינו כשהם שוים בשנים:\",3,0],[8,387,1,3,\"והם יושבים בכמו חצי גרן וכו'. משנה בסנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ו:):\",4,0],[8,387,1,3,\"ועוד מעמידין וכו'. משנה בסנהדרין פ' אלו הן הנחנקין (סנהדרין דף פ״ו:) ושלשה בתי דינין היו שם אחד יושב על פתח הר הבית ואחד יושב על פתח העזרה ואחד יושב בלשכת הגזית שמשם תורה יוצאה לכל ישראל ובברייתא בגמ' בית דין של ע״א יושבים בלשכת הגזית ושני בתי דינים של כ״ג אחד יושב על פתח הר הבית ואחד יושב על פתח העזרה:\",5,0],[8,387,1,3,\"ומעמידין וכו'. שיש בה ק\\\"כ וכו'. משנה ספ\\\"ק דסנהדרין (דף ב':) כמה יהיה בעיר ותהיה ראויה לסנהדרין ק\\\"כ ואע\\\"ג דפליג התם רבי נחמיה ואמר דבעינן ר\\\"ל פסק רבינו כת\\\"ק:\",6,0],[8,387,1,3,\"ויושבת בשער העיר וכו'. וכמה יהיה מניינם כ\\\"ג. משנה סוף פ\\\"ק דסנהדרין (דף ב') סנהדרי קטנה היתה של כ\\\"ג:\",7,0],[8,387,1,4,\"עיר שאין בה ק\\\"כ וכו'. נלמד מדתנן בסוף פ\\\"ק כמה יהא בעיר ותהיה ראויה לסנהדרין ק\\\"כ והא פשיטא שאין מניחין אותה בלא ב\\\"ד ופחות שבבתי דינין הוא של שלשה:\",1,0],[8,387,1,6,\"כל עיר שאין בה וכו'. ספ\\\"ק דסנהדרין (דף י\\\"ז:) אמר רב יהודה כל עיר שאין בה שנים אחד לדבר ואחד לשמוע אין מושיבין בה סנהדרין ובביתר היו שלשה וביבנה ד' וכו'. מיתיבי שלישית חכמה רביעית אין למעלה הימנה כלומר דקתני שלישית במדרגה ראשונה משמע דאין מושיבין סנהדרין עד שיהיו שם שלשה ומשני הוא דאמר כי האי תנא דתניא שניה חכמה שלישית אין למעלה הימנה כלומר כשיש בה שנים אחד יודע לדבר ואחד לשמוע ראויה להושיב בה סנהדרין וכשיש בה שלשה אין למעלה הימנה ומפרש רבינו אחד לדבר יודע ללמד ולהורות בכל התורה ואחד לשמוע יודע לשאול ולהשיב כלומר בכל התורה כולה והשאר נראה שצריך שיהיו יודעים לשאול ולהשיב בקצת דינין אע\\\"פ שאינם יודעים לשאול ולהשיב בכל התורה דאל\\\"כ היאך יתמנו בסנהדרין אנשים שאינם יודעין לשאול ולהשיב ורש\\\"י פירש בע\\\"א אבל מכל מקום קשה שכתב רבינו היו בה ד' הרי זו סנהדרי חכמה ושם אליבא דברייתא הראשון בשלשה היא חכמה ואליבא דהוא דאמר כי האי תנא בשנים הוי חכמה וארבעה אין למעלה הימנה אליבא דכ\\\"ע ובירושלמי דשקלים פ' ואלו הן הממונים סנהדרין שהיו בה שנים יודעים לדבר וכולן ראויים לשמוע הרי זו ראויה לסנהדרין שלשה הרי זו כבינונית ד' הרי זו חכמה וצריך לומר שרבינו היתה לו גירסא אחרת:\",1,0],[8,387,1,6,\"והראב\\\"ד כתב א\\\"א כך צריך להגיה שנים ראויים לדבר וכו'. ונראה שהיתה לו גירסא אחרת:\",2,0],[8,387,1,7,\"כל סנהדרי קטנה וכו' עד ואחד כותב דברי המזכין. הכל משנה בסנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ו:):\",1,0],[8,387,1,10,\"ומ\\\"ש ולמה אין סנהדרין אלא בעיר וכו'. ספ\\\"ק דסנהדרין (דף יז:) מפרש להו גמרא הכי ופירש\\\"י שני סופרים לכתוב דברי המחייבין ודברי המזכים וכל שעה יושבים לפני הדיינים ושני חזנים שמשי ב\\\"ד להלקות החייב ולהזמין בעלי דינין לדין ושני בעלי דינין שאל\\\"כ את מי הם דנין. ושני זוממין שיתייראו העדים להעיד שקר שלא יוזמו ושני זוממי זוממין שמא יתחייב בעל דין ע\\\"פ עדים וישכיר שנים להזימן לפיכך צריך שנים אחרים בעיר שיתייראו אלו מהם אם נבא להזים העדים יבאו אלו השנים ויזומו אותנו רופא למול תינוקות אומן מקיז דם לבלר לכתוב ספרים. ודע שאין לגרוס בדברי רבינו ואומן בוי\\\"ו דא\\\"כ הוה ליה קכ\\\"א אלא כך צריך לגרוס ורופא אומן בלא וי\\\"ו וכן מצאתי בספר ישן והיינו לומר שהוא רופא יודע לרפאות החלאים וגם הוא אומן במלאכת היד אבל סמ\\\"ג כתב רופא והוא המוהל ואומן והוא המקיז דם וא\\\"כ הם קכ\\\"א אלא שנראה שתקן לזה שלא מנה השלישי שמצטרף עם גבאי צדקה שכך כתב כשיגיעו לחלק נוטלין אחד מן העם משמע אחד מן המנויים לעיל ודוחק לפרש כן ולכן הגירסא שכתבתי נראה לי עיקר:\",1,0],[8,387,2,1,\"אין מעמידין בסנהדרין וכו'. כתב הרמ\\\"ך תימה מה צורך לדיינים שידעו רפואות וחשבונות וחכמת המזלות עכ\\\"ל. ואני אומר דמתקופות ומזלות לא קשיא דודאי צריכין לידע כדי שידעו לעבר שנים וחדשים.\",1,0],[8,387,2,1,\"ומה שכתב ואין מעמידין בסנהדרין אלא כהנים וכו'. משנה פרק אחד דיני ממונות (סנהדרין דף ל״ב) אין הכל כשרים לדון דיני נפשות אלא כהנים לוים וישראלים המשיאים לכהונה וכיון דסנהדרין דנין דיני נפשות ממילא דאין מעמידין בהם אלא כהנים לויים וישראלים המשיאים לכהונה. ויש לתמוה על רבינו שכתב שנאמר והתיצבו שם עמך שהרי בגמרא (דף ל״ז:) הביא ראיה מפסוק זה ודחו דילמא התם משום שכינה כלומר לפי שאותם שבימי משה שרתה שכינה עליהם כדכתיב ואצלתי מן הרוח אשר עליך ולפיכך היה צריך שיהיו מיוחסין אבל בסנהדרין דעלמא לא בעינן אלא אמר רב נחמן בר יצחק אמר קרא ונשאו אתך אתך בדומים לך להוי כלומר דהאי קרא בסנהדראות שנתמנו בעצת יתרו כתיב והקל מעליך ונשאו אתך ובהנהו ליכא משום שכינה. ואפשר לומר דס״ל לרבינו דהאי קושיא ודילמא משום שכינה לא הויא אלא אליבא דרבי יהודה ולא אליבא דרבנן דאמרינן בספ״ק דסנהדרין דסנהדרי גדולה של ע״א ואמרינן התם ורבי יהודה עמך משום שכינה משמע:\",2,0],[8,387,2,2,\"ומצוה להיות בסנהדרי גדולה וכו'. בספרי פרשת שופטים:\",1,0],[8,387,2,3,\"אין מעמידין בסנהדרין לא זקן מופלג וכו'. פ' אחד דיני ממונות (סנהדרין דף ל״ו:) גמרא דיני נפשות מתחילין מן הצד ברייתא וטעם האכזריות בזקן פירש״י ששכח כבר צער גידול בנים:\",1,0],[8,387,2,4,\"אין מושיבין מלך וכו'. סנהדרין פרק כ״ג (סנהדרין דף י״ח:) ברייתא אין מושיבין מלך בסנהדרין משום דכתיב לא תענה על ריב על רב כתיב ואי אמר מלך חובה תו לא מצו אינך למחזי ליה זכותא לא מלך ולא כ״ג בעיבור השנה ומדנקט בסיפא כ״ג בהדי מלך משמע דברישא דוקא מלך ועוד דהא תנן בהדיא כהן גדול דן ודנין אותו ואמרינן בגמרא דמילתא דפשיטא היא אלא דאיידי דבעי למיתני המלך לא דן ולא דנין אותו תנא כ״ג דן ודנין אותו:\",1,0],[8,387,2,5,\"מלכי בית דוד וכו'. משנה שם (דף י\\\"ח) המלך לא דן ולא דנין אותו ומפרש בגמ' (דף י\\\"ט) דהני מילי במלכי ישראל משום עובדא דינאי ושמעון בן שטח אבל מלכי בית דוד דנין ודנין אותם:\",1,0],[8,387,2,6,\"כשם שבית דין מנוקים וכו'. פ' אחד דיני ממונות (סנהדרין דף ל״ו:) אהא דתנן ואין הכל כשרים לדון דיני נפשות אלא כהנים לוים וישראלים המשיאים לכהונה אמרו בגמ' מ״ט דתני רב יוסף כשם שבית דין מנוקין בצדק כך מנוקין מכל מום אמר אמימר מאי קראה כולך יפה רעיתי ומום אין בך ודילמא מום ממש אלא אמר רב אחא אמר קרא והתיצבו שם עמך עמך בדומין לך וכיון שהלכו להביא ראיה מפסוק אחר אלמא דקושטא הכי הוא דעל מום ממש קאמר שיהיו מנוקים מכל מום ועוד דאמרינן בפרק מצות חליצה (יבמות דף ק״א) למעוטי סומין מדתני רב יוסף נפקא דתני רב יוסף כשם שב״ד מנוקים בצדק כך מנוקים מכל מום:\",1,0],[8,387,2,6,\"צריך להשתדל וכו'. ספ\\\"ק דסנהדרין (דף י\\\"ז) ופרק ששי דמנחות (דף ע\\\"ה) אמר רבי יוחנן אין מושיבין בסנהדרין אלא בעלי קומה ובעלי חכמה ובעלי מראה ובעלי זקנה ובעלי כשפים ויודעים בשבעים לשון שלא תהא סנהדרין שומעת מפי התורגמן וכתב רבינו יודעין ברוב הלשונות משום דדבר זר הוא להמציא מי שידע בכל ע' לשון ומשמע לרבינו דהאי אין מושיבין היינו דהיכא דמשתכחי אבל אי לא משתכחי לא מעכבי כל הני ויש סעד לדבר מדאמרו גבי משה ואילו נבוני לא אשכח:\",2,0],[8,387,2,7,\"בית דין של שלשה וכו'..\",1,0],[8,387,2,8,\"אמרו חכמים וכו'. ברייתא בסנהדרין פ' אלו הן הנחנקין (סנהדרין דף פ״ח:) גמרא זקן ממרא ע״פ ב״ד ותוספתא בסוף שקלים ובפ״ב דתוספתא דחגיגה:\",1,0],[8,387,2,9,\"בית דין של שלשה שהיה אחד מהם גר וכו'. בפ' מצות חליצה (יבמות דף ק״א ע״ב) גרסינן אמר רבא גר דן את חבירו דבר תורה שנאמר שום תשים עליך עליך הוא דבעינן מקרב אחיך וכו'. אבל גר דן את חבירו גר ואם היתה אמו מישראל דן אפילו ישראל ומפרש רבינו כהרי״ף ורוב המפרשים שכתבו דהיינו לדיני ממונות דוקא ובפ' החולץ ובפ' י' יוחסין אמרינן נמי כיון דאמו מישראל מקרב אחיך קרינן ביה והא דבעינן אמו מישראל אפילו אמו מישראל קאמר וכ״ש אם אביו מישראל ואע״פ שאין אמו מישראל כך כתבו התוס' בפרק מצות חליצה (בד״ה לענין חליצה) ודין גר דן את חבירו כתבו רבינו ספי״א מהלכות אלו והטעם שלא כתבו כאן וכתבו שם הוא משום דהא בדיני תנאי דיינים שבב״ד של כ״ג וב״ד של ג' ממונים לדון את ישראל מיירי הילכך דין גר דן את חבירו גר אינו ענין לכאן אלא בפי״א דבחילוקים שבין דיני ממונות לדיני נפשות קא עסיק:\",1,0],[8,387,2,9,\"היה אחד ממזר וכו'. פ' אחד דיני ממונות (סנהדרין דף ל״ו:) הכל כשרים לדון דיני ממונות לאתויי מאי וכו' לאתויי ממזר.\",2,0],[8,387,2,9,\"ומ\\\"ש אפילו שלשתן ממזרים נ\\\"ל דה\\\"ה לשלשתן גרים שאמם מישראל כיון דמקרב אחיך קרינן בהו אלא דאיצטריך לאשמועינן פסולה דגר שאין אמו מישראל דאפילו חד מינייהו גר פסילי אבל אה\\\"נ כיון דמכשרינן בגר שאמו מישראל שאפילו שלשתן גרים שאמם מישראל נמי מכשרינן וכיון שהשמיענו רבינו דאפילו שלשתן ממזרים כשרים ממילא שמעינן לשלשתן גרים שאמן מישראל וכל שכן הוא דהא ממזר גריע מגר שאמו מישראל דהא ממזר פסול לבא בקהל וגר כשר לבא בקהל ואע\\\"ג דגר שאין אמו מישראל כשר לבא בקהל ואפילו הכי פסול שאני התם דלא קרינן ביה מקרב אחיך:\",3,0],[8,387,2,9,\"וכן אם היה כל אחד מהם וכו'. שם (דף ל\\\"ד:) ההוא סמיא פירוש באחד מעיניו דהוה דאין דינא ולא אמר ליה ר' יוחנן ולא מידי משום דתנן התם בההוא פירקא דיני ממונות דנים ביום וגומרים בלילה פירוש דכיון דכולהו אינשי לא מצו למחזי בלילה כדחזי סומא באחד מעיניו ביום וכיון דקתני גומרים בלילה דין הוא לסומא באחד מעיניו שידון ביום לכתחלה וכ\\\"כ הרי\\\"ף ואמרינן התם נמי דהא לא חש ר\\\"י לסתמא דנדה דפליג אהא סתמא דהכא משום דהאי סתמא דקתני לה גבי הלכתא דדינא עדיף טפי אי נמי דההוא סתמא דהתם רבי מאיר ודהכא רבנן ולהכי פסק ר' יוחנן כסתמא דהכא דאתיא כרבנן וכתבו ההגהות על מ\\\"ש\",4,0],[8,387,2,9,\"רבינו אבל סומא בשתי עיניו וכו'. והיינו כר\\\"מ ואין נ\\\"ל שרבינו מפרש ההוא סמיא דהוה דאין דינא דהיינו באחד מעיניו דוקא כמו שמפרש הרי\\\"ף וכמו שכתבתי וא\\\"כ כרבנן פסק:\",5,0],[8,387,2,9,\"מה שאין כן בסנהדרין. אפשר לפרש שלשון רבינו דקאי אכל מאי דמדכר לעיל בן גר שאמו מישראל בין ממזר בין סומא באחד מעיניו וא\\\"כ גר שאמו מישראל פסול לסנהדרין דלא גרע מחליצה דבעינן שיהיה אביו ואמו מישראל וכ\\\"כ בעל נמוקי יוסף בפרק מצות חליצה בשם הרי\\\"ף ורב אחא משבחא אלא שק\\\"ל שהיה לו לרבינו לבאר דבריו יותר וכיון דגר שנשא ישראלית הוא מהמשיאין לכהונה ולכתחלה מורין כן כדאיתא בפ' עשרה יוחסין איכא למימר הרי הוא בכלל ונשאו אתך ואל תשיבני מגר שנשא גיורת דבתו כשרה לכהונה דהא אמרינן התם דלכתחלה אין מורין כן ועוד דאע\\\"ג דנימא דהוי בכלל ונשאו אתך מצד שכשר לכהונה כיון דלא קרינן ביה מקרב אחיך לאו בכלל ונשאו אתך הוא. ומ\\\"מ לדעת רבינו הדין דין אמת דלדיני נפשות בעינן שיהא ישראל מכל צדדיו שכיון שלא כתב הכשר באמו מישראל אלא בב\\\"ד של שלשה אלמא דלסנהדרין מיפסל וכן נראה מדבריו סוף פ\\\"ה מהלכות אלו:\",6,0],[8,387,2,10,\"אע\\\"פ שאין ב\\\"ד פחות מג'. בריש סנהדרין (דף ג') רב אחא בריה דרב איקא אמר מדאורייתא חד נמי כשר שנאמר בצדק תשפוט עמיתך וק\\\"ל למה לא פסק כרבא דפליג התם ארב אחא ואמר דמדאורייתא בעינן ג' דהא רבא בתרא הוא ומריה דגמ' ובתשובת הרשב\\\"א שמצאתי ואכתבנה לקמן בסמוך נתן טעם למה פסק רבינו כן:\",1,0],[8,387,2,10,\"ומדברי סופרים וכו'. משנה ריש סנהדרין דיני ממונות בג':\",2,0],[8,387,2,10,\"ושנים שדנו אין דיניהן דין. שם (ה':) תניא רשב\\\"ג אומר יפה כח פשרה מכח הדין ששנים שדנו בעלי דינין יכולין לחזור בהם ואע\\\"ג דשמואל סבר דפליגי רבנן עליה ואמר דשנים שדנו דיניהם דין הא אמרינן התם רבי אבהו אמר שנים שדנו אין דיניהם דין לד\\\"ה ופסק רבינו כמותו משום דכל היכא שאנו יכולים למעט המחלוקת יש לנו למעט ועוד דאמרינן פ' שני דכתובות ובפ' זה בורר ודילמא רבנן דבי רב אשי כשמואל סבירא ליה אלמא דאין הלכה כמותו ועוד דגרסינן בירושלמי רבי יוחנן וריש לקיש דאמרי תרווייהו שנים שדנו אין דיניהן דין והא ודאי כרבי יוחנן קיימא לן לגבי שמואל וכל שכן כד הוי ר\\\"ל בהדי ר\\\"י והני מילי דאין דיניהן דין באינן מומחין ולא קבלום עליהם בעלי דינין דאם הם מומחין לרבים או נטלו רשות אפילו אחד דינו דין כמו שכתב רבינו בסמוך ואם קבלום עליהם ומכל מקום קיימא לן בדברי רבינו שכתב לעיל בסמוך שמותר לאחד לדון מן התורה והיינו כרב אחא בריה דרב איקא ובהדיא אמרינן התם בגמרא דלרב אחא בריה דרב איקא אית ליה דשמואל דאמר שנים שדנו דיניהם דין והיאך פסק רבינו כאן דלא כשמואל. ואפשר לומר שכך מפרש רבינו לרבא דאמר דמדאורייתא בעינן תלתא הא ודאי לית ליה דשמואל דהא מדאורייתא תלתא בעינן לרב אחא אית ליה דשמואל כלומר אפשר לקיים דברי שמואל כיון דמדאורייתא לא בעינן תלתא בדיעבד שנים דיניהם דין וכיון דחזינן דשמואל ור' אבהו לא פליגי אי מדאורייתא חד כשר או לא אלמא דאפילו ר' אבהו מודה דמדאורייתא חד כשר ומדרבנן הוא דבעינן תלתא אלא דאלמוה רבנן לתקנתייהו למימר דאפילו דיעבד לא סגי בלא תלתא ואע\\\"ג דאמרינן (דף ל\\\"ד:) אי מה ריבים בשלשה אף נגעים בשלשה תלמוד לומר והובא אל הכהן וכו' דמשמע דמדאורייתא דיני ממונות בשלשה צ\\\"ל לפי זה דדרך אסמכתא קאמר הכי:\",3,0],[8,387,2,10,\"אחר כך מצאתי שנשאל הרשב\\\"א והשיב וז\\\"ל:\",4,0],[8,387,2,10,\"כתבת התימה מהרמב\\\"ם שפסק כרב אחא דמדאורייתא חד נמי כשר ועם זה פסק דשנים שדנו אין דיניהן דין:\",5,0],[8,387,2,10,\"אני אומר כי הרב פסק כרב אחא מדקתני בברייתא דיני ממונות בשלשה ואם היה מומחה לרבים דן אפילו יחידי וסבור הרב ז\\\"ל דברייתא הכי קתני דיני ממונות בשלשה משום יושבי קרנות כרב אחא ומדאורייתא אפילו יחיד שאינו מומחה לרבים דן אפילו יחידי לכתחלה ואפילו מדרבנן דאוקמוה אדיניה ולית ליה להאי תנא עירוב פרשיות וכמו שפירש\\\"י ומ\\\"מ מדרבנן כל שאינו מומחה לרבים בעינן שלשה ואלמוה לתקנתא דאי ליכא ג' אפי' בדיעבד אין דיניהן דין ואם תאמר א\\\"כ אמאי לא אקשו מהאי ברייתא לר' אבהו יש לומר דאמר לך ר' אבהו אנא דאמרי כר' שמעון בן גמליאל דאמר הדין בשלשה ושמא הזקיקו לרב לומר כך מדגרסינן בפ' ראוהו ב\\\"ד והם שלשה וכו' ואמאי לימא הכא נמי לא תהא שמיעה גדולה מראיה ואסיקנא הך סיפא איצטריכא ליה שאין היחיד נאמן ע\\\"י עצמו סד\\\"א הואיל ותנא דיני ממונות בשלשה ואם היה מומחה לרבים דן אפילו יחידי הכי נמי בקדשים ביחיד קא משמע לן ואימא הכי נמי אין לך מומחה לרבים בישראל יותר ממשה רבינו וא\\\"ל עד דהוי אהרן אחיך אלמא דברייתא דאם היה מומחה לרבים דבר תורה קאמר ולפיכך פסק הרב כך ומכל הנך ראיות שכתבתי למעלה ראה הרב דלית הלכתא כשמואל ולפיכך פסק דאפי' מדרבנן פסלי חד דלאו מומחה ואפי' שנים וניחא לי נמי קצת לדבריו הא דאכשרו תרי בפרוזבול וכן בביטול הגט וקרו להו ב\\\"ד ואם איתא כיון דאית לן עירוב פרשיות אפילו בהא היאך קרו להו ב\\\"ד בשום ענין ואע\\\"ג דאמרינן בריש פירקין דרבא לית ליה דשמואל ורב אחא אית ליה דשמואל אפשר לומר דאפילו רב אחא לית ליה דשמואל דאמר דאם דנו דיניהם דין אלא מעיקרא דדינא קאמר כנ\\\"ל לדעת הרב אלא שק\\\"ל הא דאותביניה לר' אבהו דאמר שנים שדנו ד\\\"ה אין דיניהם דין מדן את הדין זיכה את החייב וחייב את הזכאי מה שעשה עשוי דאלמא לרב אחא לא קשיא דלדידיה מה שעשה עשוי עדיין יש לי לומר דאנן לא שמעינן לרב אחא דאית ליה דשמואל ומן התקנה הילכך לא אפשר לן לאקשויי ליה מינה אלא לכשת\\\"ל דלית אקשי ליה מינה ומתרצינן ליה לר' אבהו עכ\\\"ל:\",6,0],[8,387,2,11,\"אחד שהיה מומחה לרבים. שם (דף ד') ת\\\"ר דיני ממונות בשלשה ואם היה מומחה לרבים דן אפי' יחידי ואמר רב נחמן כגון אנא דן דיני ממונות ביחידי ואסיקנא דהכי קאמר כגון אנא דגמירנא וסבירנא ואע\\\"ג דלא נקיט רשותא מבי ריש גלותא דינו דין.\",1,0],[8,387,2,11,\"ומה שכתב רבינו או שנטל רשות מבית דין. דפירוש אע\\\"פ שאינו מומחה לרבים דגמיר וסביר אבל מומחה הוא דאי שאינו מומחה הרי כתב רבינו ספ\\\"ד שאין רשותו מועלת כלום והיאך יהיה מותר לו לדון יחידי ואין לומר דאפי' באינו מומחה עסקינן והיינו טעמא דמצי דאין משום דקבלו בעלי דינין עלייהו דא\\\"כ לאו מתורת נוטל רשות הוא דמצי דאין אלא מכח קבלת הבעלי דינין וא\\\"ה אפי' רועה בקר נמי אלא ודאי כדאמרן:\",2,0],[8,387,2,11,\"אבל אינו חשוב ב\\\"ד. כלומר להיות הודאה בפניו כמודה בפני ב\\\"ד וכמו שנתבאר זה בדבריו בספ\\\"ה:\",3,0],[8,387,2,11,\"ואע\\\"פ שהוא מותר וכו'. משנה במס' אבות:\",4,0],[8,387,2,12,\"יש לאדם לעשות דין וכו'. בבא קמא פרק המניח (בבא קמא דף כ״ז:) פלוגתא דרב יהודה ורב נחמן וסבר רב נחמן דעביד איניש דינא לנפשיה אפילו במקום דליכא פסידא פירוש אם לא יבא לב״ד וידוע דהלכתא כרב נחמן בדיני:\",1,0],[8,387,2,13,\"אע\\\"פ שב\\\"ד של ג' וכו'. פ\\\"ק דסנהדרין (דף ז':) רב הונא כי הוה אתי דינא קמיה מכניף ומייתי עשרה רבנן מבי רב אמר כי היכי דנמטייה שיבא מכשורא פירוש שיגיענו נסורת קטנה מן הקורה כלומר שאם נטעה ישתלש העונש בין כולהו ויקלו מעלי:\",1,0],[8,387,2,13,\"וצריכין שיהיו היושבים כולם שם בב״ד ת״ח וראויים. ברייתא פרק שבועת העדות (שבועות דף ל':) ומניין לדיין שלא ישב תלמיד בור לפניו פירוש לישא וליתן עמו שלא יטעהו תלמוד לומר מדבר שקר תרחק:\",2,0],[8,387,2,14,\"ואסור לאדם חכם וכו'. ברייתא בסנהדרין פ' זה בורר (כ\\\"ג) כך היו נקיי הדעת עושים אין יושבין בדין עד שיודעים עם מי יושבים:\",1,0],[8,387,3,1,\"עד אימתי סנהדרי קטנה וב\\\"ד של שלשה וכו'. פ\\\"ק דשבת (דף י') עד אימתי יושבים בדין א\\\"ר ששת עד זמן סעודה ושם בסמוך אמרו ששעה ששית היא זמן סעודת תלמידי חכמים ואם כן הוה ליה לרבינו לכתוב עד תחלת שש כדי שיסעדו בשעה ששית אם לא נאמר דמשמע ליה עד זמן סעודה עד סוף זמן סעודה והיינו עד סוף שש ולא תקשי לך היאך יסעדו אחר שש שהוא כזורק אבן לחמת דהא אמרינן דאי טעים מידי בצפרא לית לן בה:\",1,0],[8,387,3,1,\"אבל ב״ד הגדול היו יושבין וכו'. ברייתא בסנהדרין פרק אלו הן הנחנקין (סנהדרין דף פ״ח:):\",2,0],[8,387,3,1,\"ובשבתות וימים טובים וכו'. באותה ברייתא ובשבתות וימים טובים בחיל ובתוספתא דחגיגה פרק ב' כתוב נכנסים לבית המדרש שבהר הבית והטעם פירש\\\"י שלא יהיו נראים כיושבים בדין שבלשכת הגזית היו דנין:\",3,0],[8,387,3,2,\"ואין ב\\\"ד של ע\\\"א צריכין וכו'. עד ואם לאו לא יצא עד שיבא אחר. סנהדרין פרק אחד ד\\\"מ (דף ל\\\"ז) והטעם שלא יפחתו מכ\\\"ג דריש ליה התם מאל יחסר המזג פירוש אל יחסרו מחלק הג' שהוא כדי הראוי למזוג וכ\\\"ג שליש של שבעים דסתם מזיגה על חד תרי ושאני מזיגה דרבא דהוי על חד תלת וי\\\"מ אל יחסר מז\\\"ג בגימטריא חמשים אבל אם חסרו מ\\\"ט שנשארו כ\\\"ב אין לחוש ומכאן למד רבינו שלא היו יושבים כולם תמיד ולא היו מתקבצים אלא בעת הצורך:\",1,0],[8,387,3,3,\"אין מתחילין את הדינין וכו'. בסנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ב) דיני נפשות דנין ביום וגומרים ביום דיני ממונות דנין ביום וגומרין בלילה ואמרינן עלה בגמרא (דף ל״ד:) מה״מ אמר רבי חייא בר פפא דאמר קרא ושפטו את העם בכל עת וכו'. דרבא רמי כתיב ושפטו את העם בכל עת וכתיב והיה ביום הנחילו וכו' הא כיצד יום לתחלת דין לילה לגמר דין פירוש משום דכתיב ושפטו ועיקר משפט היינו גמר דין ובתר הכי אמרינן מתניתין דלא כר״מ דתניא היה ר״מ אומר מה תלמוד לומר [על פיהם יהיה] כל ריב וכל נגע וכו' מקיש ריבים לנגעים מה נגעים ביום אף ריבים ביום ויש לתמוה למה תפס רבינו קרא דמייתו בגמרא אליבא דר״מ ושביק קרא דמייתי ליה אליבא דרבנן. ויש לומר דאמרינן התם בגמרא לקמן ור״מ ביום הנחילו מאי עביד ליה מיבעי ליה לכדתני רבה בר חנינא קמיה דרב נחמן וכו' ביום אתה מפיל נחלות ואי אתה מפיל נחלות בלילה והא דרבה בר חנינא הלכה היא וכמו שכתב רבינו בפרק זה והשתא כיון דביום הנחילו איצטריך למידרש ביום אתה מפיל גורלות ממילא בטלה לה ההיא ראיה דרבא וא״כ אע״ג דלא קי״ל כר״מ מדרשא דדריש למעט בלילה בין לתחלת דין בין לגמר דין דרשינן ליה למעוטי לתחלת דין וקרא דושפטו את העם בכל עת דרשינן אגמר דין ואם תאמר כיון דדרשינן דאין גומרין דין בלילה מכל ריב וכל נגע לא מצית למדרש ושפטו לגמר דין דהא אמרינן ורבי מאיר ושפטו מאי דריש ביה ואמר רבא לאתויי יום המעונן דאע״ג דאין רואים בו נגעים דנין בו מושפטו ואם כן לילה לגמר דין מנא לן. ויש לומר דלא איצטריך לרבנן קרא דושפטו ליום המעונן שאינם מקישים ריבים לנגעים אלא לומר מה זה ביום אף זה ביום לא לשום היקשא אחרת אבל ר״מ דמקיש להו לגמרי אצטריך ושפטו לאפוקי יום המעונן תדע דר״מ מקיש להו לגמרי ורבנן לא גמרי מנגעים אלא דריבים ביום ותו לא דהא סומא באחד מעיניו פסול לר״מ דומיא דנגעים ולרבנן כשר:\",1,0],[8,387,3,4,\"וכן אין מקבלים עדות וכו'. כתב בעל נמוקי יוסף בשם הרמב״ן בפרק יש נוחלין ופ' אחד דיני ממונות דאפילו נתקבל פסול דאמרינן בר״ה (דף כ״ה ע״ב) למה לי למיתני נחקרו העדים וכו' סד״א תהוי חקירת העדים כתחלת דין ומקודש מקודש כגמר דין ולקדשיה בלילה מידי דהוה אדיני ממונות וכו' דגומרין בלילה קמ״ל אלמא קבלת עדות כתחלת דין הוא שאינה אלא ביום אפילו בדיעבד דתנן ביבמות פ' מצות חליצה (יבמות דף ק״ד) חלצה בלילה חליצתה כשרה ורבי אליעזר פוסל ומפרשינן בגמרא דמר סבר חליצה כתחלת דין דמיא ומר סבר כגמר דין דמיא אלמא תחלת דין בלילה אפילו דיעבד פסול והוא הדין לקבלת עדות דתרווייהו כי הדדי נינהו וכמו שכתבתי:\",1,0],[8,387,3,4,\"ואין מקיימין שטרות וכו'. זה דבר פשוט שהרי צריך קבלת עדות ואפילו על פי הדברים שכתב רבינו פ\\\"ה מהלכות עדות שיכולים לקיים השטר על פיהם ואין שם קבלת עדות כיון שהטעם הוא משום דבדרבנן עד נעשה דיין מכל מקום הוה ליה כקבלת עדות ולא הוי אלא ביום:\",2,0],[8,387,3,4,\"ובדיני ממונות וכו'. לא קאי אלא אראש דבריו אין מתחילין את הדינין וכך שיעור הלשון ובדיני ממונות דוקא אם התחילו דנין ביום מותר לגמור בלילה אבל בדיני נפשות אסור לגמרו בלילה דאילו קבלת עדות הוא הוי כתחלת דין לא שייך ביה אם התחילו גומרין דכוליה התחלה הוא ודין זה דבדיני ממונות גומרין בלילה ולא בדיני נפשות כבר נתפרש בסמוך:\",3,0],[8,387,3,5,\"הנחלות כדינין וכו'. סנהדרין פ' אחד דיני ממונות (סנהדרין דף ל״ד:) ובתרא פ' יש נוחלין (בבא בתרא דף קי״ג:) והיה ביום הנחילו את בניו ביום אתה מפיל נחלות ולא בלילה ואסיקנא דדין נחלות קאמר פירוש דבפרשת נחלות כתיב לחקת משפט דמשמע הפלת נחלות דין קצוב הוא בשעת המיתה הכל כמו שאמר המת ואין הדבר צריך דיינין אלא כל אחד מיורשיו יחזיקוהו שומעי הצואה בשלו וכיון דאמר קרא ביום הנחילו משמע דהני מילי דצואת המת הוי דין פסיק ואין צריך עוד לדיינים ביום אבל בלילה לא הוי דין פסיק וצריך דיינים ואלו ששמעו צואת המת יעידו בפניהם ויש מחלוקת בין המפרשים דאיכא מ״ד דכיון דדברי שכיב מרע ככתובים וכמסורים דמו לא הוי אלא מדרבנן כי מרבי הכא לא מרבינן אלא בקנין ואיכא מ״ד דבלא קנין מיירי ואליבא דרבי יוחנן בן ברוקה והרוצה לעמוד על עיקרן של דברים יעיין בחשן המשפט:\",1,0],[8,387,3,5,\"כתב\",2,0],[8,387,3,5,\"הרמ\\\"ך הנחלות כדינים וכו'. תימה למה הביא לשון שסותר אותו בגמרא והל\\\"ל לפיכך אין דיני נחלות בלילה ועוד תימה לן היכי תלי תניא בדלא תניא שאמר הנחלות כדינים ואדרבא לפסק הלכה כל הדינים מנחלות גמרינן כדרמי הכא כתיב ושפטו את העם בכל עת וכתיב והיה ביום הנחילו את בניו הא כיצד יום לתחלת דין לילה לגמר דין עכ\\\"ל:\",3,0],[8,387,3,6,\"שנים שנכנסו לבקר את החולה וכו'. פ' אחד דיני ממונות (סנהדרין דף ל״ד:) ובפרק יש נוחלין (בבא בתרא דף קי״ג:) מימרא דרב יהודה אמר רב כלשון רבינו ואמר רב חסדא עלה לא שנו אלא ביום אבל בלילה כותבין ואין עושין דין משום דהוו להו עדים ואין עד נעשה דיין ופירש״י רצו כותבין בלשון עדות והיורשין יבואו לבית דין ובית דין יעשו כפי הצואה. רצו עושין דין השומעין רשאין ושליטין להיות מחזיקין כל אחד בשלו הכל כמו ששמעו. שנים אין עושין דין דמתחלתו לא נראו להיות לדיינים אבל בלילה שאינו ראוי לדין כותבין ואין עושין דין אפילו למחר שמתחלתם לא נראו לישב לשם לדין עכ״ל. ובפרק יש נוחלין כתב רשב״ם דדוקא נקט שנכנסו לבקר הילכך רצו עושין דין אבל נכנסו להעיד הרי הם עדים ואין עד נעשה דיין והביא ראיה לדבריו מדאמרינן פ״ק דמכות גבי נמצא אחד מהם קרוב או פסול עדותן בטלה דאמרינן להו למחזי אתיתו או לאסהודי ואי לאסהודי נמצא אחד מהם קרוב או פסול עדותם בטלה ופירש הוא ז״ל דאמרינן להו מתחלה כשראיתם העדות נתכוונתם להעיד או לראות הדבר אלמא כונה להעיד פסולה וגם הביא ראיה מתשובת זקנו רש״י ובעלי התוספות חלקו עליו וההיא דפ״ק דמכות פירשוה בענין אחר מ״מ רבינו ז״ל מסכים לדבריו שהרי ההיא דמכות רבינו בפרק חמישי מהלכות עדות מפרשה כדברי רשב״ם שכן כתב שם על פי שנים עדים או שלשה עדים לעשות ג' כשנים וכו' וכיצד בודקין את הדבר כשיבאו לבית דין עדים מרובים כת אחת אומרים להם כשראיתם זה שהרג או חבל להעיד באתם או לראות כל מי שאומר לא להעיד עליו אלא לראות מה הדבר ובכלל העם באתי מפרישים אותו וכל מי שאומר לא הייתי עומד אלא להעיד ולכוין העדות מפרישין אותו אם נמצא באלו שנתכוונו להעיד קרוב או פסול עדותן בטלה בד״א בשהיה בהם קרוב או פסול אבל אם כולם כשרים אחד שנתכוון להעיד או שלא נתכוון להעיד הואיל וראה הדבר וכוון עדותו והיה שם התראה חותכין הדין על פיו בין בדיני ממונות בין בדיני נפשות. ומה שהקשו א״כ אין לך גט כשר כשנותנין בפני קרובים או קדושין אם נתכוונו להעיד לא קשיא דכיון שנהגו ליחד עדים אף אם יתכוונו הקרובים להעיד אין בכך כלום דאין כוונה פוסלת אלא כשאין עדים מיוחדים ואם תאמר והא בעינן הגדה בשאר ממון חוץ מקידוש החדש משום דכתיב כזה ראה וקדש וקיום שטרות דרבנן ואם כן היכי אמרינן רצו עושים דין תירץ הריטב״א דמה שצוה בפניהם חשוב הגדת עדים דהודאת בעל דין כמאה עדים דמי. אבל בעל נמוקי יוסף כתב בסנהדרין רצו עושין דין פירש״י שהם פוסקים הדין על פי צוואתו ואין צריך בית דין אחר נראה מפירושו שהוא עשאן בית דין של עצמו ואין היורשין יכולים לדון בפני אחר שצואה בעצמה הוא פסק דין שנפסק בפני אלו שהם ב״ד ושמעינן מהא דב״ד יכולים לדון ע״פ ראייתם בלא קבלת עדות אחרת כיון שהם יודעים הדבר ושלא כדברי המפרשים דבדיני ממונות בעינן שיעידו בפניהם דהגדה בעינן ושאני הכא דאיכא הגדת בעל דבר והודאת בעל דין כמאה עדים דמי עכ״ל. ולי נראה דאי איכא למידק מלשון רש״י איפכא איכא למידק מיניה דאי לנוסחת ספרינו דגרסינן ברש״י רצו עושין דין השומעין רשאין ושליטין להחזיק כל אחד בשלו הכל כמו ששמעו מדקאמר הכל כמו ששמעו משמע טעמא דשמעו דאיכא הגדה אבל אי ליכא הגדה לא ואפילו אם תמצא לומר שלא היה גורס כדברי רש״י כי אם כמו שכתב בשמו איכא למימר דמדקאמר על פי צואתו משמע דוקא משום דאיכא צואה דהיינו הגדה ועל פיה פוסקין הדין אבל אי ליכא הגדה לא ואין לומר דושמעינן מהא לא קאי לרש״י אלא למימרא דרב יהודה דהיכי שמעינן מינה הכי דהא הריטב״א פירש על הא דר' יהודה דמה שצוה בפניהם חשוב הגדה ובעל נמוקי יוסף גופיה בפרק יש נוחלין מייתי הא דכתב הריטב״א על הא דרב יהודה וכתב עוד רשב״ם דה״מ דרצו עושין דין דמשמע דאפילו החולה אין יכול לחזור בו כגון מתנת שכיב מרע במקצת וקנו מיניה דתו לא מצי הדר ביה אבל בלא קנין כיון דיכול לחזור בו אין עושין דין שאין לדיינים לעשות דין בדבר שאפשר להבטל עדיין ואם רצו אין דיניהן דין דעדיין לא קנו עד שימות האב שמא יחזור בו:\",1,0],[8,387,3,7,\"כל ב\\\"ד של ישראל וכו'. פ\\\"ק דסנהדרין (דף ז'):\",1,0],[8,387,3,7,\"לפיכך צריכים וכו' ובעטיפה. דאמרינן בפ\\\"ק דשבת מאימתי התחלת הדין משיעטפו הדיינים ושאר הדברים הטעם מפני מורא שכינה:\",2,0],[8,387,3,8,\"כל סנהדרין וכו' שנאמר לא תכירו פנים במשפט. כתוב בסמ\\\"ג מל\\\"ת סי' קפ\\\"ד תניא במכילתין לא תכירו פנים אזהרה זו לממונה להושיב דיינים שלא יאמר איש פלוני נאה וכו' מעלה הכתוב על שמינהו כאילו הכיר פנים:\",1,0],[8,387,3,8,\"ועוד אמרו כל המעמיד לישראל דיין שאינו הגון וכו' עד בלבד. פ\\\"ק דסנהדרין שם.\",2,0],[8,387,3,8,\"ומ\\\"ש שהוא כאילו הקים מצבה. צ\\\"ע היכא מייתי ליה והרב מהר\\\"י קולון האריך הרבה בשורש קי\\\"ז לבקש מנוח לכף רגלו אמאי דריש לה רבינו מלא תקים לך מצבה ובפרק קמא דסנהדרין מייתי לה מלא תטע לך אשרה ורואה אני דבריו טובים ונכוחים אילו היה דרכו של רבינו לדרוש הפסוקים מדעתו ולהניח הדרשה המפורשת בגמ' ומכיון שאין דרכו כן נ\\\"ל דבשום דוכתא דריש לה מלא תקים לך מצבה:\",3,0],[8,387,3,9,\"כל דיין שנתן ממון אסור לעמוד מפניו וכו'. ירושלמי בסוף בכורים ר' מנא מקל לאלין דמתמניין בכסף רבי אימי קרא עליהון אלהי כסף וכו' אמר רבי יאשיה וטלית שעליו כמרדעת של חמור אמר ר' אשיין זה שהוא מתמנה בכסף אין עומדין מפניו ואין קורין אותו רבי והטלית שעליו כמרדעת של חמור:\",1,0],[8,387,3,10,\"כך היה דרך וכו'. פ\\\"ק דסנהדרין ר' זירא הוה מיטמר מלסמוכי ואיתיה נמי בירושלמי סוף בכורים:\",1,0],[8,387,4,1,\"אחד בית דין הגדול וכו'. נתבאר מתוך מאי דאיתא בפרק קמא דסנהדרין (דף ה'):\",1,0],[8,387,4,1,\"ואחד הנסמך וכו' אפילו לא היה אותו סמוך בסנהדרין מעולם. למד כן מדאשכחן דלאחר החורבן דלא הוו סנהדרין היו סומכין:\",2,0],[8,387,4,2,\"וכיצד היא הסמיכה וכו'. פ' קמא דסנהדרין שם:\",1,0],[8,387,4,3,\"ואין סומכין וכו' אלא בשלשה. שם במשנה סמיכת זקנים בשלשה דברי ר' שמעון רבי יהודה אומר בחמשה ופירש\\\"י סמיכת זקנים על ראש פר העלם דבר של צבור ובגמ' (דף י\\\"ג:) תנא סמיכה וסמיכת זקנים בשלשה מאי סמיכה וסמיכת זקנים אמר רבי יוחנן מיסמך סבי לקרות להם רבי ומשמע דאע\\\"ג דאפליגו במתני' רבי יהודה ור' שמעון בסמיכת זקנים על ראש פר העלם דבר של צבור אי הויא בשלשה או אי הויא בחמשה בסמיכת סבי לקרות להם רבי לכ\\\"ע הויא בשלשה כדקתני בברייתא שכתבתי בסמוך:\",1,0],[8,387,4,3,\"ומ\\\"ש והוא שיהיה האחד וכו'. נראה מדבריו דבאחד סמוך סגי אף על פי שהשנים האחרים אינם סמוכים נ\\\"ל שטעמו דמדאמרינן התם בגמ' (דף י\\\"ג:) אמר ליה אביי לרב יוסף מיסמך סבי פירוש לקרות רבי בשלשה מנ\\\"ל אילימא מדכתיב ויסמוך את ידיו עליו א\\\"ה תיסגי בחד וכ\\\"ת משה במקום ע\\\"א קאי א\\\"ה ליבעי ע\\\"א קשיא וסובר רבינו דכיון דאסיקנא בקשיא ופשיטא דלא בעינן ע\\\"א ואם כן בחד סגי ולדחויה דברייתא דבעינן ג' אי אפשר א\\\"כ יש לנו לומר דכי קתני בברייתא ג' לאו בכולהו סמוכין עסקינן דאם כן קשיא דאביי אלא חד סמוך סגי ומיהו בעינן עמיה שנים דהוו שלשה:\",2,0],[8,387,4,4,\"אין קרוי אלהים וכו'. בב״ק פרק החובל (בבא קמא דף פ״ד) אלהים בעינן וליכא ופירש״י אלהים בעינן והיינו מומחים וסמוכים:\",1,0],[8,387,4,5,\"בראשונה וכו' עד אלא אם כן היה הנשיא עמו. בירושלמי פירקא קמא דסנהדרין:\",1,0],[8,387,4,6,\"אין סומכין זקנים בח\\\"ל וכו'. פ\\\"ק דסנהדרין (דף י\\\"ד) אמר ר' יהושע בן לוי אין סמיכה בח\\\"ל ופירשו לה התם לומר דאין סומכין בח\\\"ל ואסיקנא נמי התם דאפילו סומכין בארץ ונסמכין בחוצה לארץ אין סומכין:\",1,0],[8,387,4,6,\"היו שניהם בארץ וכו'. נראה שלמדה ממה שכתבנו בסמוך דכיון שאמרו בגמרא סומכין בארץ ונסמכין בחוצה לארץ לא סמכי משמע הא סומכין ונסמכין בארץ מצו סמכי אפילו אינם יחד דאי אפילו סומכין ונסמכין בארץ בעינן שיהיו במקום אחד מאי איריא סומכין בארץ ונסמכין בחוצה לארץ הא אפילו שניהם בארץ כיון דאינם במקום אחד לא מצו סמכי אלא ודאי כדאמרן:\",2,0],[8,387,4,6,\"וכל ארץ ישראל שהחזיקו וכו'. נראה שהוציא כן ממאי דאמרינן בריש סנהדרין וכתבו רבינו בסוף פ' זה שרשות בני ארץ ישראל מועלת לעיירות העומדות על הגבולים ואם לעיירות האלו מהני כל שכן דמהני למה שהחזיקו עולי מצרים אע\\\"פ שלא החזיקו עולי בבל:\",3,0],[8,387,4,7,\"יש לסומכין וכו'. ירושל' ר\\\"פ חלק:\",1,0],[8,387,4,8,\"ויש להם למנות וכו'. בריש סנהדרין (דף ה') אמרינן שרבי נתן רשות לרב לדון אבל לא להתיר בכורות ומכל מקום צריך עיון מנין לרבינו שצריך שיהיה ראוי לכל הדברים:\",1,0],[8,387,4,9,\"וכן יש לסומכין וכו'. שם ע\\\"ב אמר ליה רבי יוחנן לרב שמן הרי אתה ברשותנו עד שתבא אצלנו ופירש\\\"י ברשותנו רשות נתונה לך לדון:\",1,0],[8,387,4,11,\"חכם מופלא וכו' הרי שלא היה בא\\\"י אלא סמוך אחד וכו'. בפירוש המשנה פרק קמא דסנהדרין כתב כן אלא ששם כתב הדבר סתם וכאן כתב והדבר צריך הכרע:\",1,0],[8,387,4,12,\"בית דין שנסמכו וכו'. משנה סוף פ' קמא דמכות (דף ז'):\",1,0],[8,387,4,13,\"ומה שכתב ראשי גליות שבבבל וכו' עד אין לו רשות עד שיטול רשות מראש גלות. הכל בריש סנהדרין (דף ה') פשיטא מהכא להכא ומהתם להתם מהני דהכא שבט והתם מחוקק כדתניא לא יסור שבט מיהודה אלו ראשי גליות שבבבל שרודים את ישראל בשבט ומחוקק מבין רגליו אלו בני בניו של הלל שמלמדין תורה ברבים כלומר שיש להם שררה מועטת וכל אחד מהם יש לו רשות להפקיר דהפקר ב\\\"ד הפקר ושל א\\\"י יש לו לתת רשות בכל א\\\"י ושבבבל בחוצה לארץ מהתם להכא מאי ואיפשיטא דמהתם להכא לא מהני ולפי שמעלת ראשי גליות שבבבל גדולה מנשיאי א\\\"י כתב רבינו ראשי גליות שבבבל במקום מלך הם עומדים והלכך אין רשות בני א\\\"י מועלת לכוף בחוצה לארץ וכדאיפשיטא בגמ' ומשמע שלא הוצרכו בגמ' לשאול אי מהני מבבל לא\\\"י שאע\\\"פ שראשי גליות בבל רודים את העם במקל אינו דין שיועיל רשותם לא\\\"י ודינם שכל אחד יעמוד בשלו ואדרבה הוה ס\\\"ד דרשות א\\\"י מועילה לחוצה לארץ אבל ספר מצות גדול כתב הרשות שיתן ריש גלותא שבבבל לבני בבל אף לבני א\\\"י מועיל שהרי בבבל השבט ובא\\\"י המחוקק כדתניא לא יסור שבט מיהודה וכו' ואמרינן בירושלמי שריש גלותא שבבבל גדול מהנשיא שבא\\\"י לפי שהוא מהזכרים והנשיא מהנקבות עכ\\\"ל וקשה לזה דה\\\"ל לגמ' למימר פשיטא דמהכא להתם מהני מהתם להכא מאי ומ\\\"מ הכי משמע מדברי רבינו שכתב ראשי גליות שבבבל במקום מלך הם עומדים ויש להם לרדות את ישראל בכ\\\"מ ולדון עליהם בין רצו בין לא רצו. ומצאתי בספר מספרי רבינו שהיה מוגה בו בלשון הזה וכל דיין הראוי לדון שנתן לו ראש גלות רשות לדון יש לו לדון בכל העולם אע\\\"פ שלא רצו בעלי דינים בין בארץ בין בחוצה לארץ אע\\\"פ שאינו דן דיני קנסות ע\\\"כ וכן משמע קצת בגמ' דכי נקיט רשותא אע\\\"ג דלא קבל זה עלייהו דן אותה בעל כרחם דכי בעי מהתם להכא מאי פשיט ליה מרבה בר בר חנה דדן דינא וטעה ואמר ליה ר' חייא אי קבלוך עלייהו לא תשלם ואי לא זיל שלים והא רשותא הוה נקיט אלא שמע מינה מהתם להכא לא, משמע דאי הוה נקיט רשותא אפילו לא קבלוה עלייהו לא הוה משלם אלמא דכופם לדון:\",1,0],[8,387,4,14,\"ומ\\\"ש רבינו ובעיירות העומדות על הגבולים. הוא ממה שהקשו על מה שאמרו מהתם להכא לא מהני אלא רבה בר בר חנה שנטל רשות כשהיה יורד לבבל למה לי ומשני לעיירות העומדות על הגבולים ופירש\\\"י הנמשכות אחר ארץ ישראל:\",1,0],[8,387,4,15,\"מי שאינו ראוי לדון וכו'. בפירקא קמא דסנהדרין (דף ז':) דבי נשיאה אוקמוה דיינא דלא הוה גמיר וביזהו רבי יהודה בר נחמני. ועל מה שכתב\",1,0],[8,387,4,15,\"רבינו שהוא כמקדיש בעל מום למזבח האריך מהר\\\"י קולון בשורש קי\\\"ו:\",2,0],[8,387,5,1,\"אין מעמידין וכו'. פרק קמא דסנהדרין תנן אין דנין את השבט ופירש בגמ' (דף י\\\"ד:) דבשבט שהודח כולו עסקינן ולא את נביא שקר ולא את כהן גדול אלא על פי ב\\\"ד של ע\\\"א ואין מוציאין למלחמת הרשות וכו' ואין מוסיפין על העיר ועל העזרות וכו' ואין עושין סנהדראות לשבטים ואין עושין עיר הנדחת אלא על פי ב\\\"ד של ע\\\"א ופירש בגמ' דדיני נפשות דכ\\\"ג הוא דבעינן ע\\\"א אבל דיני ממונות דנין בג' כשאר כל אדם וזהו שכתב\",1,0],[8,387,5,1,\"רבינו אבל דיני ממונות דכ״ג בשלשה ובסוטה פרק עגלה ערופה (סוטה דף מ״ד) תנן ושלשה מבית דין הגדול שבירושלים היו יוצאים ובפ״ק דסוטה (דף ז') תנן שהיו מעלים את הסוטה לבית דין הגדול שבירושלים ובפ״ק דסנהדרין (דף ט״ז) אמרינן דמיתת זקן ממרא של כ״ג והמראתו בעינן על פי בית דין של ע״א ונראה שלזה נתכוון רבינו\",2,0],[8,387,5,1,\"שכתב אין עושין זקן ממרא ולא כתב אין ממיתין זקן ממרא וקשיא לן מדתנן בפרק י' דסהנדרין (דף פ\\\"ט) גבי זקן ממרא אין ממיתין אותו לא בבית דין שבעירו ולא בבית דין שביבנה אלא מעלין אותו לבית דין הגדול שבירושלים ונשאר לנו לדעת מנין שאין מעמידין מלך אלא בבית דין הגדול:\",3,0],[8,387,5,1,\"כתב\",4,0],[8,387,5,1,\"הרמ\\\"ך ואין מוסיפין על העיר וכו'. תימה הוא זה שמביא האי קרא דכל הדבר הגדול למדידת החלל ולמלחמת הרשות ולתוספת העיר והעזרות ובגמ' מביא פסוק אחר דמדידת החלל הוי מזקניך ושופטיך ותוספת העיר והעזרות הוי מוכן תעשו דדרשינן וכן תעשו לדורות והוא מביא האי קרא דכל הדבר הגדול והו\\\"ל להביא לעיל גבי כ\\\"ג דאין דנין דיני נפשות שלו כדמייתי בגמ' וצריך עיון עכ\\\"ל:\",5,0],[8,387,5,2,\"אין דנין דיני נפשות וכו'. משנה פ\\\"ק דסנהדרין דיני נפשות בכ\\\"ג הרובע והנרבע בכ\\\"ג שנאמר והרגת את האשה ואת הבהמה ואומר ואת הבהמה תהרגו שור הנסקל בכ\\\"ג שנאמר השור יסקל וגם בעליו יומת כמיתת הבעלים כך מיתת השור הזאב והארי והדוב והנמר והברדלס והנחש מיתתו בכ\\\"ג ר' אליעזר אומר כל הקודם להרגן זכה רבי עקיבא אומר מיתתן בכ\\\"ג. ובגמ' (דף ט\\\"ו:) הזאב והארי וכו' אמר ריש לקיש והוא שהמיתו אבל לא המיתו לא אלמא קסבר יש להם תרבות ויש להם בעלים רבי יוחנן אמר אע\\\"פ שלא המיתו אלמא קסבר אין להם תרבות ואין להם בעלים ותניא כוותיה דריש לקיש ולפיכך פסק רבינו כוותיה ואמרינן תו בגמ' רבי עקיבא היינו תנא קמא איכא בינייהו נחש ופירש\\\"י איכא בינייהו נחש דתנא קמא חשיב ליה בהדי הנך ובעי כ\\\"ג ורבי עקיבא באינך סבירא ליה כוותיה בר מנחש:\",1,0],[8,387,5,2,\"ועל מה שכתב\",2,0],[8,387,5,2,\"רבינו אבל נחש שהמית אחד הורג אותו. כתב הראב\\\"ד א\\\"א זהו כרבי עקיבא ולא ידעתי למה ע\\\"כ. ויש לומר שטעם רבינו דבארי ודוב וכו' סבירא ליה לר' עקיבא כתנא קמא והוה ליה רבי אליעזר יחיד לגבייהו ובנחש ס\\\"ל לר' עקיבא כרבי אליעזר והוה ליה תנא קמא יחיד לגבייהו:\",3,0],[8,387,5,3,\"המוציא שם רע וכו'. משנה שם המוציא שם רע בשלשה דברי רבי מאיר וחכ\\\"א בכ\\\"ג מפני שיש בה דיני נפשות וידוע דקי\\\"ל כחכמים ובגמ' (דף ח') וכי יש בו דיני נפשות מאי הוי אמר עולא בחוששין ללעז קא מיפלגי רבי מאיר סבר אין חוששין ללעז ורבנן סברי חוששין ללעז וכו'. מיתיבי וחכמים אומרים תבעו ממון בשלשה תבעו נפשות בכ\\\"ג בשלמא לרבא תבעו ממון תחלה בשלשה תבעו נפשות תחלה אפילו ממון בכ\\\"ג אלא לעולא קשיא אמר רבא וכו' הב\\\"ע כשהביא הבעל עדים שזנתה והביא האב עדים והזימום לעדי הבעל בא לגבות ממון מבעל בשלשה ובמקום נפשות בכ\\\"ג ופירש\\\"י וחכמים אומרים וכו' מפני שיש בה דיני נפשות קס\\\"ד דה\\\"ק משום מוציא שם רע דשייך ביה דיני נפשות וכגון שמביא עדים ובגמ' פרכינן וכי יש בה דיני נפשות מאי הוי השתא מיהא לאו דיני נפשות דליכא עדים. רבי מאיר סבר אין חוששין ללעז אין חוששין שמא יבאו לבית דין ויצא הקול וישמעו עדים ויבאו ויעידו שזנתה תחתיו ועכשו אין הבעל יודע בהם ותבעי כ\\\"ג דשמא יבא לידי נפשות ורבנן סברי חוששין וכו'. ובמקום דאיכא דיני נפשות כלומר וכל היכא דאיכא למיחש לנפשות כגון בתחלת הדין אפילו אין לו עדים יש לחוש שמא ישמעו ויבאו עדים כ\\\"ג בעי עכ\\\"ל. ואע\\\"פ שאמוראים אחרים פירשו בעניינים אחרים פסק רבינו כעולא משום דאביי אמר בתר הכי דכ\\\"ע חוששין ללעז ומשמע דכל הני אמוראי הכי ס\\\"ל וכמבואר בדברי התוספות ועוד דהא רבה דהוא בר פלוגתיה יישב ברייתא אליביה:\",1,0],[8,387,5,3,\"ומניין שאין דנין וכו'. משנה פ' קמא דסנהדרין:\",2,0],[8,387,5,4,\"מכות בשלשה. משנה שם וכת\\\"ק:\",1,0],[8,387,5,5,\"עריפת העגלה בחמשה. משנה שם עריפת העגלה בשלשה דברי רבי שמעון רבי יהודה אומר בחמשה וידוע דהלכה כרבי יהודה. ודע שמה שכתב כאן רבינו עריפת העגלה העתיק לשון המשנה כמנהגו ואין הכוונה אלא על המדידות כמו ששנינו בפרק עגלה ערופה וכתבוה התוספות:\",1,0],[8,387,5,6,\"עיבור החדש בשלשה. משנה שם:\",1,0],[8,387,5,7,\"מ\\\"ש עיבור השנה בשבעה. שם במשנה עיבור השנה בשלשה רשב\\\"ג אומר בשלשה מתחילין ובחמשה נושאין ונותנין וגומרים בשבעה ואם גמרו בשלשה מעוברת. ופסק כרשב\\\"ג אי משום דבכל מקום ששנה במשנתנו הלכה כמותו אי משום דבגמ' מפרשי אמוראי טעמיה אלמא הלכתא כוותיה ואע\\\"פ שלא כתב כאן רבינו אלא בשבעה סמך על מ\\\"ש בפרק ד' מהלכות קידוש החדש כל דברי רשב\\\"ג:\",1,0],[8,387,5,8,\"דיני קנסות וכו' עד ואפי' אחד מומחה דן אותם. בריש סנהדרין תנן דיני ממונות בג' גזילות וחבלות בג' ופירש בגמ' דה\\\"ק דיני ממונות פירוש בהודאות והלואות בג' הדיוטות גזילות וחבלות בג' מומחין ותנן נמי התם תשלומי כפל ותשלומי ד' וה' והאונס והמפתה בג' פירוש מומחין ואסיקנא בגמ' (דף ה') אהא דת\\\"ר דיני ממונות בג' ואם היה מומחה לרבים דן אפילו יחידי דאפילו לא נקיט רשותא מריש גלותא כיון דגמיר וסביר דן דיני ממונות אפילו יחידי ואע\\\"ג דתנן במס' אבות אל תהי דן יחידי התם עצה טובה קמ\\\"ל כמו שנכתב בדברי רבינו סוף פרק שני.\",1,0],[8,387,5,8,\"ומ״ש שם לפיכך דנין וכו' שליחות ב״ד של א״י עושין וכו'. בר״פ החובל (בבא קמא דף פ״ד:) ובסוף גיטין (דף פ״ח:):\",2,0],[8,387,5,8,\"כתב\",3,0],[8,387,5,8,\"הרמ\\\"ך לפיכך דנין בהודאות וכו'. תימה כיון שהוא פסק כרב אחא בריה דרב איקא דמן התורה חד נמי כשר דכתיב בצדק תשפוט עמיתך מנין שיהיה סמוך ועוד דאי בסמוך מיירי אפילו בדרבנן כשר ולא גזרינן משום יושבי קרנות ביחיד מומחה אפי' לא יהיה סמוך דן אפי' לכתחלה ותימה היא לפסק שלו אמאי אצטריך למימר בהודאות והלואות שליחותייהו קא עבדינן בלי שליחותייהו יכולים חכמי בבל שאין סמוכים לדון דינייהו בהודאות והלואות כיון דגמירי וסבירי וצריך עיון עכ\\\"ל. ועיין בתשובת הרשב\\\"א שכתבתי בפרק שני על שנים שדנו אין דיניהם דין:\",4,0],[8,387,5,9,\"אין ב\\\"ד של חוצה לארץ וכו'. ר\\\"פ החובל שם אמרינן דכי עבדינן שליחותייהו דדייני א\\\"י במילתא דשכיח ואית ביה חסרון כיס אבל מידי דלא שכיח אי נמי לית ביה חסרון כיס לא עבדינן שליחותייהו אע\\\"ג דבסוף גיטין שם אההוא עובדא דאשכחיה אביי לרב יוסף דהוה מעשה אגיטי אמרינן דכי עבדינן שליחותייהו במידי דשכיח ולא מדכר התם חסרון כיס יש לומר דדיני גיטין משום עיגונא עדיפא מהיכא דאיכא חסרון כיס דהכי נמי תירץ הר\\\"ן דהיינו טעמא דמקבלים גרים בזמן הזה אע\\\"ג דלא שכיח דלהכניס אדם תחת כנפי השכינה עדיף מממונא דשכיח ורב יוסף לפי מה שהקשה לו אביי השיבו כי עבדינן שליחותייהו במילתא דשכיח אבל מילתא דלא שכיח לא אבל אה\\\"נ דבעינן נמי אית בה חסרון כיס וכתבו התוס' דאע\\\"ג דהשתא ליכא ב\\\"ד מומחין בא\\\"י מ\\\"מ שליחותייהו דקמאי עבדינן:\",1,0],[8,387,5,9,\"וכן כל הקנסות וכו'. דגרסינן בבא קמא פ' המניח (בבא קמא דף כ״ז ע״ב) שלח ליה רב חסדא לרב נחמן הרי אמרו לרכובה פירוש הכאה בארכובה ג' ולבעיטה ה' וכו' שלח ליה חסדא חסדא קנסא קא מגבית בבבל ומייתי לה נמי בר״פ החובל (בבא קמא פ״ד:) ואמרי' תו בר״פ החובל בקנסא לא עבדינן שליחותייהו:\",2,0],[8,387,5,9,\"וכל המשלם חצי נזק וכו'. זה פשוט דכיון דאסיקנא בסוף פרק קמא דב״ק (דף ט״ו:) ובסוף אלו נערות (כתובות דף מ״א) דפלגא נזקא קנסא בר מח״נ צרורות דהוי ממונא וקי״ל דאין דיני קנסות בחו״ל ממילא קי״ל דכל ח״נ אין גובין בחו״ל בר מח״נ צרורות:\",3,0],[8,387,5,10,\"כל הנישום כעבד וכו'. ר\\\"פ החובל.\",1,0],[8,387,5,10,\"ומ\\\"ש רבינו דשבת וריפוי גובין. יש לתמוה דהא אמרינן שם בר\\\"פ החובל דאדם באדם אע\\\"ג דאית ביה חסרון כיס לא עבדינן שליחותייהו ואפשר לומר דאה\\\"נ דדינא הכי הוי ולא כתב שגובין אותם אלא מפני תיקון העולם אבל לא משמע כן מדבריו שכתב לעיל בסמוך אבל בהמה שחבלה בחברתה או דברים המצויים אבל אין בהם חסרון כיס כגון תשלומי כפל אין דנין אותן דייני חוצה לארץ ומדלא כתב גבי דברים שאין מצויים ויש בהם חסרון כיס אדם שחבל באדם משמע דס\\\"ל דמדינא אדם באדם כי אית ביה חסרון כיס דנין אותו דייני חוצה לארץ לכן נראה לי שרבינו מפרש דהא דאמרינן דאדם באדם אע\\\"ג דאית ביה חסרון כיס לא עבדינן שליחותייהו לא אמרו אלא לענין נזק דאית ביה חסרון כיס ואפילו הכי לא דיינינן ליה בבבל וכל שכן לצער ובשת דלית בהו חסרון [כיס] אבל ריפוי ושבת כיון דאית בהו חסרון כיס דיינינן להו בבבל לטעמא משום דאמר רבא כל הנישום כעבד אין גובין אותו בבבל וכדתנן בר\\\"פ החובל משמע הא שאר דברים שאינם נישומין כעבד נגבין בבבל דאל\\\"כ הוה ליה למסתם סתומי ולמימר אדם שחבל באדם אין גובין אותו בבבל ומכל מקום צער ובשת אינם נגבין בבבל משום דלית בהו חסרון כיס ומפני כך כשכתב דברים שאינם מצויים אע\\\"פ שיש בהם חסרון כיס אין דנין דייני חוצה לארץ לא רצה לכתוב כגון אדם שחבל באדם דא\\\"כ הוה משמע דאף שבת וריפוי אינם נגבים בבבל וכתב כגון בהמה שחבלה בחברתה ואחר כך כתב משפט אדם שחבל באדם וחילק בין נזק וצער ובשת לשבת וריפוי:\",2,0],[8,387,5,11,\"בהמה שהזיקה את האדם וכו' עד כך מעידים את הבהמה בפניהם בחוצה לארץ. הכל שם ריש פרק החובל (בבא קמא דף פ״ד) ההוא תורא דאלס ידא דינוקא אתא לקמיה דרבא וכו' רבא לטעמיה דאמר נזקי שור בשור ונזקי שור באדם גובין אותו בבבל נזקי אדם באדם ונזקי אדם בשור אין גובין אותו בבבל מאי שנא נזקי אדם באדם ונזקי אדם בשור דלא אלהים בעינן וליכא נזקי שור בשור ושור באדם אלהים בעינן וליכא אלא מאי שנא שור בשור ושור באדם דשליחותייהו קא עבדינן וכו' אדם באדם ואדם בשור נמי שליחותייהו קא עבדינן ואסיקנא כי עבדינן שליחותייהו במילתא דשכיח ואית ביה חסרון כיס אבל מילתא דשכיחא ולית בה חסרון כיס אי נמי מילתא דלא שכיחא ואית בה חסרון כיס לא עבדינן שליחותייהו הילכך אדם באדם אע״ג דאית ביה חסרון כיס כיון דלא שכיחא לא עבדינן שליחותייהו בושת אע״ג דשכיח כיון דלית ביה חסרון כיס לא עבדינן שליחותייהו ושור בשור גובין בבבל והאמר רב שור שהזיק אין גובין אותו בבבל דאזיק מאן אילימא דאזיק אדם מאי איריא שור דאזיק אדם אפילו אדם דאזיק אדם נמי אין גובין אותו בבבל אלא פשיטא דאזיק שור וקתני אין גובין אותו בבבל אמרי התם בתם הכא במועד והאמר רבא אין מועד בבבל אמרי דאייעד התם ואייתיוה להכא והא מילתא דלא שכיחא היא ומילתא דלא שכיחא את אמרת דלא עבדינן שליחותייהו דאתו רבנן דהתם וייעדוה הכא סוף סוף מילתא דלא שכיחא היא ובמילתא דלא שכיחא לא עבדינן שליחותייהו אלא כי קאמר רבא בשן ורגל דמועדין מתחלתן נינהו ובפרק קמא דב״ק (דף ט״ו:) ובסוף פרק אלו נערות (כתובות דף מ״א) אמרינן דכלבא דאכל אימרי ושונרא דאכל תרנגולי זוטרי אורחיה הוא ומגבינן בבבל:\",1,0],[8,387,5,13,\"מי שגנב וכו'. דאמרי' בהחובל (דף פ\\\"ד) דבתשלומי כפל וד' וה' נעביד שליחותייהו ומשמע לרבינו דלא קשיא ליה אלא בכפל חוץ מהקרן אבל בקרן פשיטא ליה דעבדינן שליחותייהו ובזה אין מקום למה שהקשו בתוספות דהיאך היו דנין דיני גזילות וגניבות דאפשר לומר דלא היו דנין רק על הקרן וקשה דתנן בראש סנהדרין גזילות וחבלות בשלשה ופירש בגמ' שהם מומחים וע\\\"כ גזילות היינו שדנין על הקרן דהא תני בתר הכי תשלומי כפל בשלשה ועוד דבגזילות לא שייך תשלומי כפל וא\\\"כ כי אמרינן גזילות בשלשה מומחין בדין הקרן אמרו והיאך כתב רבינו הקרן דנין אותו דייני ח\\\"ל. וכתב נמוקי יוסף בשם הרא\\\"ה דגזילות נראה מכל הגמ' דמילתא דשכיחא נינהו וגובין אותן בבבל כדאמרינן בההוא דגנב פדנא דתורי וכו' והקשה מהא דסנהדרין ותירץ דגזילה ממש כעין דויגזול את החנית לא שכיחא אבל שאר גזילות כגון שולח יד בפקדון וכיוצא שכיחי ומגבינן להו בבבל וכן אפשר לתרץ ההיא דסנהדרין לדעת רבינו ור\\\"י תירץ בסוף פרק המגרש דגזילות שעל ידי חבלות קאמר דאין דנין בבבל שחבל בחבירו וגזלו ובכי האי גוונא איכא לאוקמי ההיא מתני' דסנהדרין לדעת רבינו:\",1,0],[8,387,5,14,\"ולא כל המשלם על פי עצמו וכו'. שאדם משלם בשת ופגם על פי עצמו מבואר במשנה ס״פ אלו נערות (כתובות דף מ״א) ופ' שבועת הפקדון (שבועות דף ל״ו:) ומייתי לה ר״פ נערה שנתפתתה (כתובות דף מ״ב.) ודין הכופר במשנה סוף פרק אלו נערות. והוצרך רבינו לכתוב זה משום דכיון דלישנא דגמ' פ״ק דסנהדרין גבי מומחין תלי ליה בדיני קנסות וקיימא לן דאין אדם משלם קנס על פי עצמו סד״א דבהכי תליא מילתא וכל מידי דאדם משלם על פי עצמו לא ניבעי מומחין קמשמע לן דלא שהרי בשת ופגם וכופר אדם משלם על פי עצמו ואין גובין אותו בדייני חוצה לארץ:\",1,0],[8,387,5,15,\"דיני גרמות וכו'. שכן מצינו שהיו דנים בבבל דינא דגרמי דאמרינן בבבא קמא פרק הגוזל עצים (בבא קמא דף צ״ח:) אכפייה רפרם לרב אשי ששרף שטר חבירו בילדותו ואגבי מיניה כי כשורא לצלמא פירוש שגבה ממנו גוביינא מעלייא כל מה שכתוב בשטר פרעון גמור מן העידית כקורה זו הנבחרת משאר הקורות לתקן בה צורה ודיוקנאות:\",1,0],[8,387,5,16,\"וכן דין המוסר וכו'. מדאשכחן בפ' בתרא דבב\\\"ק כמה אמוראי דהוו דייני דיני מסורות בבבל.\",1,0],[8,387,5,16,\"ומה שכתב אף על פי שלא עשה מעשה היינו לומר שאף על פי שלא נשא ונתן ביד ממון חבירו לעכו\\\"ם אלא שהלשין בפיו וכההוא דאחוי כריא דתבנא דחבריה וסלקא דעתך אמינא כיון שמחייבין אותו אע\\\"פ שלא עשה מעשה ביד דמי לקנס ולא יגבוהו בחוצה לארץ קמשמע לן דמגבין אותו בחוצה לארץ כהנהו עובדי דפירקא בתרא דבבא קמא:\",2,0],[8,387,5,17,\"מנהג הישיבות בחוצה לארץ וכו'. כתב הרי\\\"ף בפרק החובל שזה מנהג השתי ישיבות:\",1,0],[8,387,5,17,\"וכן אם תפס וכו'. בפ\\\"ק דבבא קמא (דף ט\\\"ו) ובכתובות סוף פרק אלו נערות (דף מ\\\"ב:) ואי תפס לא מפקינן מיניה ופירוש רבינו נכון הוא וכן פירש\\\"י ואע\\\"פ שהקשה רבינו תם דאם כן יתפוס כל אשר לו דאין דנין דיני קנסות ואם נוציא המותר ונשאיר כדי נזק הרי אנו דנין דיני קנסות י\\\"ל דכשהניזק צועק בפנינו ואנו מגבין אותו אז מקרי שפיר שאנו דנין דיני קנסות אבל כשהניזק תופס יותר ממה שהוא דינו והמזיק צועק בפנינו ואנו כופין לניזק שיחזיר המותר על נזקו לא מקרי דנין דיני קנסות רק מצילין עשוק מיד עושקו וכן יש לדקדק מדברי רש\\\"י שם דוק ותשכח:\",2,0],[8,387,5,18,\"יחיד שהוא מומחה לרבים אע\\\"פ שהוא דן וכו' אבל הג' אע\\\"פ שאינן סמוכין והרי הן הדיוטות כו':\",1,0],[8,387,6,1,\"כל דיין שדן דיני ממונות וכו'. פ' אחד דיני ממונות (סנהדרין דף ל״ב) תנן דיני ממונות מחזירין בין לזכות בין לחובה ודיני נפשות מחזירין לזכות ואין מחזירין לחובה ופירש״י מחזירין סותרין את הדין לאחר שגמרוהו וידעו שטעו מחזירין את הדבר בין לזכות בין לחובה. ובגמרא (דף ל״ג) רמינן עלה דמתני' ממתני' אחריתי דתנן מה שעשה עשוי וישלם מביתו ופריק רב יוסף כאן במומחה כאן בשאינו מומחה ורב נחמן אמר כאן שיש גדול ממנו בחכמה ובמנין כאן שאין גדול ממנו בחכמה ובמנין ורב ששת אמר כאן כלומר דמחזירין בטעה בדבר משנה כאן שטעה בשקול הדעת ואסיקנא בגמרא דטועה בדבר משנה מיקרי אפילו טועה בדברי האמוראים האחרונים ואמרינן היכי דמי שיקול הדעת כלומר שאם אין הדין מפורש בשום מקום מנא ידעינן שטעה אמר רב פפא כגון תרי תנאי או תרי אמוראי דפליגי אהדדי ולא אתמר הלכתא כחד מינייהו וסוגיין בעלמא כחד ופירש רש״י רוב הדיינין נראין להם דברי האחד ואזל איהו ועבד כאידך והטור פירש כגון דסתם גמרא פריך ממילתיה ונראה שזה הוא דעת הרי״ף ממ״ש בפ' שבועת הדיינין גבי פלוגתא דראב״י ורבנן ואפשר דכולהו פירושי איתנהו וכל חד מינייהו טועה בשיקול הדעת הוי וכל אחד נקט פירוש אחד וה״ה לאינך ורב חסדא אמר כאן שנשא ונתן ביד כאן שלא נשא ונתן ביד ורבינו פוסק כרב חסדא דמסקנא דשמעתא היא וכן פסקו בהלכות ומאי דקאמר רב ששת נמי הלכתא היא דסוגיין בעלמא נעשה כמי שטעה בדבר משנה וחוזר בכתובות (ק':) ב״ד שמכרו בלא הכרזה נעשו כמי שטעו וכו' וכן בשבועות ובדוכתי אחריני ולכך פסק דטועה בדבר משנה חוזר. וכתב הטור בשם הראב״ד ז״ל שאם טעה בפסקי הגאונים שלא שמע דבריהם ואילו שמע היה חוזר בו הוי טועה בדבר משנה וכתב הרא״ש ולא מיבעי בפיסקי הגאונים אלא אפילו חכמי כל דור ודור שאחר הגאונים לא קטלי קני באגמא הוו ואם פסק הדין שלא כדבריהם וכששמע דבריהם ישרו בעיניו והודה שטעה טועה בדבר משנה הוא וחוזר וכך יש לדקדק שסובר רבינו שטועה בדברי הפוסקים הוי טועה בדבר משנה מדכתב כגון דינין המפורשים במשנה ובגמרא ומדכתב תיבת כגון משמע דאתא לרבות טועה בדברי הפוסקים.\",1,0],[8,387,6,1,\"ומ\\\"ש שאם אי אפשר להחזיר פטור מדאמרינן בגמ' דרבי טרפון האכיל בהמה שניטל האם שלה לכלבים וטועה בדבר משנה הוה דהא סתם מתני' באלו טריפות ניטל האם שלה כשרה ואמרינן עלה כיון דאילו הואי פרה דינך לאו דינא ולא כלום עבדת השתא נמי לאו כלום עבדת כלומר כיון שלא האכלתה לכלבים בידיך ומדברי הטור נראה שפירש דברי רבינו אפילו שנשא ונתן ביד וכך כתב הרשב\\\"א בתשובה ולי נראה דעד כאן לא פטרינן לטועה בדבר משנה אלא ממה שנעשה על פיו לא ממה שעשה בידים וזהו שכתב\",2,0],[8,387,6,1,\"רבינו אע\\\"פ שגרם להזיק והיינו בשלא נשא ונתן ביד אבל כשנשא ונתן ביד מזיק ממש הוא וחייב לשלם ואע\\\"פ שמומחה שנטל רשות מר\\\"ג אפילו נשא ונתן פטור התם שאני דהפקר ב\\\"ד הפקר וכן פירש\\\"י גבי הא דאמרינן לינקט רשותא מריש גלותא וכמו שנדקדק מלשונו בסמוך וכן גבי הא דאמרינן (סנהדרין ה') מהכא להכא וכו' מהני דהכא שבט והתם מחוקק פירש\\\"י שבט לשון שררה ויש להם רשות להפקיר דהפקר ב\\\"ד הפקר ע\\\"כ אלמא דמדין הפקר נגעו בה וכמו שפירשתי וכשנתנו לו רשות ע\\\"ד כן נתנוהו לו שלמי שיחייב בשקול דעתו אפילו נשא ונתן פטור וכן אם קבלוה עלייהו אע\\\"ג דלא נקיט רשותא משום דמסתמא אדעתא דהכי קבלו עלייהו לדונם כפי שקול דעתו ויפטר בכל ענין כיון דמומחה הוא. זה נראה בדעת רבינו. ואחר שכתבתי זה מצאתי שכתבו התוס' גבי ההיא דהאכיל ר' טרפון לכלבים וא\\\"ל ר\\\"ע לאו כלום עבדת בלא נשא ונתן ביד איירי דאי האכילה ר\\\"ט לכלבים טובא עבד, הרי מפורש בדבריהם מה שדקדקתי בלשון רבינו:\",3,0],[8,387,6,2,\"אם הדיין מומחה ונטל רשות וכו'. פ\\\"ק דסנהדרין (דף ה') אמר רב האי מאן דבעי למידן דינא ואי טעי בעי למיפטר לישקול רשותא מבי ריש גלותא וכן אמר שמואל ופירש\\\"י דכיון דברשות נחת לא משלם כלומר כיון דברשות ב\\\"ד נחת וב\\\"ד יש כח בידם להפקיר ממון לא משלם:\",1,0],[8,387,6,2,\"או שלא היה נוטל אבל קבלוהו עליהם וכו'. שם גבי רבה בר בר חנה דן דינא וטעה ואתא קמיה דר' חייא וכן מר זוטרא בריה דרב נחמן ואתא לקמיה דרב יוסף ואמרו להו אי קבלוך עלייהו לא תשלם ואי לא זיל שלים והני תרי מומחין הוו ועוד דתנן דן את הדין וזיכה את החייב וחייב את הזכאי מה שעשה עשוי וישלם מביתו ואוקימנא לה דנשא ונתן ביד כמו שכתבתי למעלה ואוקימנא בפ\\\"ק דסנהדרין בקבלו בעלי דינין וקתני סיפא ואם היה מומחה לרבים פטור ועוד ראיה מר' טרפון שאמר לו ר\\\"ע אי נמי בשיקול הדעת טעית מומחה לרבים אתה וכל המומחה לרבים פטור מלשלם וההיא דר\\\"ט דמי לקבלוהו בעלי דינין וכמו שביארתי הרי שמומחה שקבלוהו בעלי דינין אפילו נשא ונתן ביד פטור:\",2,0],[8,387,6,3,\"מ\\\"ש היה הטועה מומחה ולא נטל רשות ולא קבלוהו. נלמד מהני עובדי דרבה ומר זוטרא דאמרו להו ואי לא קבלוך עלייהו זיל שלים.\",1,0],[8,387,6,3,\"ומ\\\"ש או שלא היה מומחה אבל קבלו אותו בעלי דינין עליהם וכו' ממתני' דדן הדין וכו' ואוקמה רב חסדא בנשא ונתן וקתני סיפא אם היה מומחה אלמא ברישא באינו מומחה עסקינן דהיינו בפ\\\"ק דסנהדרין בקבלוהו בעלי דינין וכמו שכתבנו למעלה.\",2,0],[8,387,6,3,\"ומ\\\"ש רבינו ואם אי אפשר להחזיר ישלם מביתו הנה דעת רבינו נפלאת בעיני שבכל הדינים האלו הוא נמשך אחר דעת ההלכות זולתי בדין הזה שההלכות הביאו דעת גאון אחד שסובר כן וחלקו עליו וסתרו דבריו ואי אפשר לומר שרבינו סובר כדעת הגאון ההוא שטענת הגאון היא דכי אסיקנא בשנשא ונתן דלא כר\\\"מ דדאין דינא דגרמי אבל אנן דקיי\\\"ל כוותיה מי שאינו מומחה שטעה בשקול הדעת אם א\\\"א להחזיר ישלם מביתו וההלכות דחו דבריו דאפילו לר\\\"מ פטור שאע\\\"פ שגרם להזיק לא נתכוון להזיק ועד כאן לא חייב ר\\\"מ אלא בגורם המתכוין אבל לא בגורם שאינו מתכוין כי האי ורבינו בראש הפרק כתב שאע\\\"פ שגרם להזיק לא נתכוון. וי\\\"ל שאע\\\"פ שרבינו סובר בשאר הדינין הנזכרים בפרק הזה כדעת ההלכות בדין זה סובר כדעת הגאון דלא תלי האי דינא בהנהו דיני וסבירא ליה לרבינו דבדין זה הלכה כדעת הגאון ולא מטעמיה וזה לפי שבעל דין אין לו להפסיד אם לא ע\\\"פ הפקר ב\\\"ד במומחה דנקיט רשותא או ע\\\"פ קבלת עצמו והיינו מומחה דלא נקיט רשותא וקבלוהו עלייהו בעלי דינין וכמ\\\"ש אבל בדלא נקיט רשותא דליכא הפקר בית דין ולא קבלוהו אע\\\"פ שהוא מומחה וכן מי שאינו מומחה אע\\\"פ שקבלוהו לא מהני דאדעתא דדין תורה קבלוהו וכיון דאינו מומחה לא הוה אפשר ליה למידן דין תורה אם נשאו ונתנו הוה ליה מזיקין ממש וכיון שהחזיקו דבריהם כל כך דינם דין ומשלמין וכשלא נשאו ונתנו יחזיר ואם א\\\"א ישלם מביתו כי היכי דלא ליפסיד מארי דינא ואע\\\"ג דגבי טועה בדבר משנה כתב שאם א\\\"א להחזיר פטור שאני התם דגלי לן גמרא גבי ר\\\"ט דטעה בדבר משנה ואמרינן כיון דאילו איתה לפרה דינך לאו דינא ולאו כלום עבדת השתא נמי לאו כלום עבדת דוקא גבי טועה בדבר משנה דגלי לן גמרא גלי אבל בשקול הדעת דלא גלי אית לן למינקט דינא כי היכי שלא להפסיד בעל דין ועוד דבשלמא אם נאמר דמי שאינו מומחה אע\\\"פ שלא נשא ונתן ביד אם א\\\"א ישלם מביתו היינו דטעי רבי טרפון דסבירא ליה דאפילו נקיט רשותא כל היכא דלא אפשר ישלם ואמר ליה רבי עקיבא דמאן דטעה בדבר משנה אפילו לא נקיט רשותא אי נמי טועה בשיקול הדעת ונקיט רשותא פטור ואי לא נקיט חייב אלא אי אמרת דאפילו מאן דלא נקיט רשותא פטור א\\\"כ רבי טרפון דמומחה וסמוך הוה במאי טעי הא אפילו אינו מומחה פטור ויש לנו למעט הטעות כל מה שנוכל וכיון דכן ע\\\"כ הוא כדאמרן ועוד מדברי ר\\\"ע נלמוד דקאמר ליה מומחה אתה וכל המומחה לרבים פטור ואם איתא דאפילו אינו מומחה דקבלו פטור לימא ליה כיון דקבלוך פטור אתה דמסתמא דין זה שאלו מלפניו דלא דינא דממון הוה דנימא שכפאם לדון לפניו וכיון דלא א\\\"ל הכי שמע מינה דאפילו קבלוה עלייהו כיון שאינו מומחה חייב והוא הדין למומחה ולא קבילו עלייהו דתרוייהו בחד טעמא שייכא וחד דינא אית להו וליכא למימר דחדא ועוד קאמר כדקאמר גמרא דא\\\"כ הוו להו תרי ועוד וחדא ועוד אמרינן ליה בדוחק קל וחומר תרי ועוד. והוי יודע שהרי\\\"ף כתב דשקול הדעת דליכא לברורי בה טעותא אם שלמו הכל על פיו ובא דיין אחד ופטר לא יחזיר דכיון דליכא לברורי דטעה זכה אידך במאי דתפס ואם שלם החצי ונשאר החצי כל אחד מהם זכה במה שבידו ואם לא נתן דבר פטור והיינו ההיא עובדא דמייתי פרק דיני ממונות זוטא (דף כ\\\"ט:) גבי ההוא גברא דהוו קרי ליה עכברא דשכיב אדינרי דאתו לקמיה דרבי ישמעאל ברבי יוסי וחייבינהו ליתמי ושלימו פלגא והדר אתו לקמיה דרבי חייא ופטרינהו אמרו א\\\"כ נהדר לן פלגא אמר להו כבר הורה זקן ופירש הוא ז\\\"ל דלא דמי הא טעותא דרבי ישמעאל ברבי יוסי דטעה בשקול הדעת לשקול הדעת דאמרינן לעיל דאילו התם הא אמרינן בהדיא היכי דמי שקול הדעת כגון תרי תנאי או תרי אמוראי דאיפליגו בהדי הדדי ולא אתמר הלכתא כחד מינייהו וסוגיין בעלמא כחד מינייהו ואזל איהו ועבד כאידך היינו שקול הדעת וטעמא דמילתא כיון דסוגיין בעלמא כחד מינייהו ואזיל איהו ועבד כאידך איגלאי מילתא דודאי טעה אלא כיון דלא אתמר ביה הלכתא בהדיא לאו דבר משנה הוא ואילו שקול הדעת דהכא לית ראיה לרבי חייא לברורי ביה טעותא דר' ישמעאל בר' יוסי הלכך ליכא כח לאהדורי לעובדא דידיה ומשום הכי קאמר כבר הורה זקן וכך הם דברי הרא\\\"ש בפרק זה בורר על האי עובדא ואפשר לי לומר דרש\\\"י שפירש בסוגיין דעלמא היינו שרוב הדיינים נראה להם כדברי האחד והרב אלפסי ז\\\"ל לא פליגי דאע\\\"ג דלא פשט המנהג אם אחר שנפסק הדין נשאל לחכמים ורובם פסקו כאידך מיקרי נמי שיקול הדעת כפירש\\\"י ורבי חייא ורבי ישמעאל ברבי יוסי לא היו עמהם חכמים אחרים באותה העיר הילכך הוה ליה ההוא דינא שקול ואי שלמו קם דינא דזכה אידך במאי דבידיה והוו להו יתומים המוציא מחבירו ועליהם הראיה דטעה אידך ואי לא שלמו אידך הוה ליה מוציא מחבירו ולא לשלמו וה\\\"ה לשלמו פלגא:\",3,0],[8,387,6,4,\"אבל מי שאינו מומחה וכו'. זה דבר פשוט בעצמו וכבר קדם הדבור לרבינו בסוף פרק ד' שראש גולה שנתן רשות למי שאינו יודע שהוא כמקדיש בעלי מומין למזבח שאין הקדושה חלה עליו וא\\\"כ אע\\\"פ שנטל רשות כיון דלאו מומחה הוא ולא קבלוה עלייהו אין דינו דין כלל וכ\\\"כ הרב אלפסי ז\\\"ל אבל דברי רבינו צ\\\"ע שאחר\",1,0],[8,387,6,4,\"שכתב ואם טעה ונשא ונתן ביד חייב לשלם מביתו וחוזר ולוקח מבעלי דין\",2,0],[8,387,6,4,\"כתב ואם אין לו להחזיר וכו' ישלם והרי כבר אמר תחלה שכיון שנשא ונתן ביד ישלם מביתו א\\\"כ מה שייך תו למימר ואם אין לו להחזיר ישלם הרי כבר שלם בין יש לבעל דין להחזיר בין אין לו ואין לומר שכלפי שאמר אם טעה ונשא ונתן ביד חייב לשלם מביתו וחוזר ולוקח מבעל דין אמר לא תימא על כל פנים חוזר ולוקח ואם אין לו להחזיר לא יפסיד הדיין אלא יחזיר הבעל דין שנתן לו לכן אמר שאפילו שאין לו להחזיר יפסיד הדיין ופירוש ישלם יפסיד מה שישלם דא\\\"א לומר כן שהרי רבינו כתב ישלם כדין כל גורם להזיק ואי דנשא ונתן ביד מזיק בידים הוא לכך צריך לגרוס בדברי רבינו לדעתי ואם טעה ונשא ונתן ביד חייב לשלם מביתו וחוזר ולוקח מבעל דין זה שנתן לו שלא כהלכה ואם לא נשא ונתן ביד חוזר בעל דין ונוטל מחבירו מה שנתן לו ואם אין לו להחזיר או שטמא או שהאכיל דבר המותר לכלבים ישלם כדין כל גורם להזיק שזה מתכוין להזיק הוא ואם לא ימצא בשום ספר רק כנוסחת ספרינו צריכים אנו לפרש שואם אין לו להחזיר וכו' לא קאי אלא אנשא ונתן ביד וטעם דין זה שאחר שאין דינו דין כלל הדר דינא ואם נשא ונתן ביד הוה ליה מזיק משלם הוא מביתו וחוזר ועושה דין עם הבעל דין האחר שאומר לו בעל דין איני רוצה להתדיין עם שום אדם אבל אתה שנשאת ונתת ביד לך ועשה דין עמו ואם לא נשא ונתן ביד כל היכא דאית ליה לבע\\\"ד אינו מחוייב לעשות עמו דין דא\\\"ל אמת שחייבתיך אבל היה לך לעכב הממון וכיון שלא נשא ונתן ביד פטור מלעשות דין אבל אם אין לו להחזיר וכו' חייב לשלם שזה אחר שאינו מומחה ולא קבלוהו עליהם גורם להזיק בכוונה הוא וקי\\\"ל כר' מאיר דדאין דינא דגרמי וממ\\\"ש\",3,0],[8,387,6,4,\"רבינו הרי זה בכלל בעלי זרוע ואינו בכלל הדיינים יתברר לך שמי שאינו מומחה ולא קבלוהו עליהם בין טעה בדבר משנה בין טעה בשקול הדעת כולהו חד דינא אית להו ואינו בכלל מ\\\"ש רבינו בראש הפרק כל דיין שטעה וכו' שזה אינו בכלל הדיינים:\",4,0],[8,387,6,5,\"דיין שטעה וחייב שבועה וכו'. בעל העיטור כתב שהרי\\\"ף כתב בתשובה שמי שחייבוהו ב\\\"ד שבועה חמורה ועשו ביניהם פשרה ואחר כך ראו שלא היה עליו אלא חרם סתם יכול הוא לחזור שיש לו לומר אילו היה יודע שאין עליו שבועה לא היה עושה פשרה והוה ליה הקנין בטעות ומי שנתחייב שבועה ונתן ממון לפוטרו משבועה ואח\\\"כ מצא ראיה שנתחייב בממון הפשרה בטלה דכיון שנתחייב בממון אין כאן שבועה אבל עשו פשרה ולא הזכירו שבועה הפשרה קיימת [עכ\\\"ל] וא\\\"כ הוא הדין נמי לדיין שטעה וחייב שבועה וכו' ונראה לי דהיינו דוקא בשטעה בדבר משנה אי נמי בשיקול הדעת ואיכא לברורי טעותא אבל אי ליכא לברורי טעותא המע\\\"ה וכמו שכתבתי בפרק זה בשם הרי\\\"ף ז\\\"ל:\",1,0],[8,387,6,7,\"שנתעצמו בדין וכו' עד עבד לוה לאיש מלוה. סנהדרין סוף פרק זה בורר (סנהדרין דף ל״א:) וכתבו התוס' דמאי דקאמר ואם אמר כתבו ותנו לי וכו' היינו דוקא היכא דנתעצמו בדין וכפאום אבל בעלמא אין כותבין ונותנין לו וכן משמע בפרק אי זהו נשך מעובדא דתרי כותאי דעבדי עסקא דא״ל חזינא דכל בתר דידי קאזיל מר וקאמר כי האי ודאי צריך לאודועי משמע דבעלמא לא. וכתב נמוקי יוסף גבי האי עובדא דתרי כותאי בשם הרשב״א ז״ל והר״ן והראב״ד ורבינו תם ור״י דדוקא היכא דאיכא חשדא כי התם צריך להודיע הטעם אבל ליכא חשדא וכפאוהו דצריך לכתוב וליתן לו אין צריך לכתוב הטעם אלא פלוני טען כך ופלוני כך ונראה לנו שהדין עם פלוני ובית דין של בית הועד הם ידעו טעמו של דבר ואם לא כפאוהו וליכא חשדא אין כותבין לו וכתב עוד נמוקי יוסף דמאי\",1,0],[8,387,6,7,\"דקאמר ואם הוצרך וכו' מבית דין הגדול שבירושלים וכו' לא שיפסקו ב\\\"ד הגדול עליהם את הדין דהא בעינן שיהיו בעלי דינין עומדין לפי הדיינים אלא שב\\\"ד הגדול מודיעין דעתם לב\\\"ד זה והם דנין אותם:\",2,0],[8,387,6,7,\"כתב\",3,0],[8,387,6,7,\"הרמ\\\"ך אבל אם אמר המלוה וכו' תימה למה הביא האי קרא דעבד לוה לאיש מלוה כיון דמסיק לבסוף דניזק או נגזל או תובע אחר יכול לכוף הנתבע לעלות עמו ורבותי ורבינו תם מפרשים דניזק ומזיק לא מצו מעכבי דטעמא דמלוה משום דעבד לוה לאיש מלוה אבל בשאר תביעות ליכא עבד עכ\\\"ל. ול\\\"נ דיש לומר דבשאר תביעות נמי שייך לומר שהתובע מתרעם מחבירו שהזיקו הוי הנתבע עבד לו עד שיסלק היזקו או יברר שאינו מזיקו:\",4,0],[8,387,6,7,\"כתב הרמ\\\"ך על דברי רבינו יש לתמוה עליו שפירש נלך לבית הועד נלך לבית דין הגדול ומההיא דפ' הגוזל זוטא (דף קי\\\"ב:) אית למוכח דחילוק איכא בין ב\\\"ד הגדול לבית הועד וכ\\\"כ רבינו תם והר\\\"י בר אשר ונראים דבריהם עכ\\\"ל:\",5,0],[8,387,6,8,\"בד\\\"א כשהיו שם עדים וכו'. היינו כדי שלא יהא כ\\\"א תובע את חבירו ואומר לבי דינא רבא אזילנא ויבא להתפשר עמו כדי שלא להתבטל ממלאכתו ולילך לעיר אחרת לידון עם בעל דינו:\",1,0],[8,387,6,9,\"וכן הדין בזמן הזה שאין וכו'. למד כן מדאמרינן בפרק אחד דיני ממונות (סנהדרין דף ל״ב:) הלך אחר ב״ד יפה אחר רבי אליעזר ללוד אחר רבי מתיא בן חרש לרומי משמע שבלוד או ברומי הוה ב״ד הגדול שאין למעלה הימנו. וממ״ש\",1,0],[8,387,6,9,\"רבינו ומקומות שיש בהם תלמידים שאין כמותם נראה שדעתו כדעת קצת מפרשים שאומרים שאם דייני עירם הדיוטות אפי' לוה מצי מעכב ולומר איני דן אלא בב\\\"ד של מומחין ומהרי\\\"ק בשורש צ' כתב שמאחר שכתב מרדכי בסוף פרק זה בורר בשם א\\\"ז דלית לן השתא בית הועד קיבוץ תלמידי חכמים שיתבייש מהם אע\\\"פ שבזמן רבינו היו מקומות ראויים שיכוף המלוה את הלוה ללכת שם לדין אין ראוי לומר שיחלוק רבינו על א\\\"ז שהרי ידוע הוא שבכל יום הדורות מתמעטים ולכן אפשר לומר דבימי א\\\"ז אפילו רבינו היה מודה דלא היה שום ב\\\"ד ראוי להקרא בית הועד, ודבריו תמוהים בעיני שהרי רבינו לא תלה הדבר בבית הועד אלא במקומות שיש חכמים גדולים מומחים לרבים ומקומות שיש בהם תלמידים שאינם כמותם ודבר זה מצוי בכל דור ודור:\",2,0],[8,387,7,1,\"אחד מבעלי דינין שאמר וכו'. משנה סנהדרין ריש פ' דיני ממונות בתרא (דף כ\\\"ג) דיני ממונות בשלשה זה בורר לו אחד וזה בורר לו אחד ושניהם בוררים להם עוד אחד דברי ר' מאיר וחכמים אומרים שני הדיינים בוררים להם עוד אחד ולפי גירסת ספרים שלנו בדברי רבינו שכתוב בהם והם בוררים להם דיין שלישי פסק רבינו כר' מאיר אע\\\"ג דרבנן פליגי עליה משום דר' אלעזר ורב פפא שקלי וטרו לפרושי מילתיה ואם היינו מוצאים נוסחא שאין כתוב בה וא\\\"ו דוהם היינו אומרים דפסק כחכמים וכך מצאתי בספר ישן מאד הרי אלו שני הדיינים שבירר זה אחד וזה אחד בוררים להם דיין שלישי עכ\\\"ל ואין כתוב והם ואם כן פסק כחכמים וכן גורס ספר מצות גדול והיא הנוסחא האמיתית דאמרינן בגמ' דלרבנן בדעת דיינים סגי ואמרינן תו בגמ' דמתני' הכי קאמר כשזה בורר לו אחד וזה בורר לו אחד יצא הדין לאמתו כלומר דמתני' לא קתני בחיוב שיצטרכו לברירת דיינים אלא אם האחד בורר דיין אחד והאחד בורר דיין אחד כשבוררין שלישי יצא הדין לאמיתו וזהו שכתב רבינו אחד מבעלי דינין שאמר וכו' כלומר אם קרה מקרה ואמר התם רב פפא דאפי' הוי מומחה יכול לעכב ופסק רבינו כרב פפא אע\\\"ג דאיכא מאן דפליג עליה משום דמוקי מתניתין אפילו במומחין ועוד דבתרא הוא. ודע שמה שכתב\",1,0],[8,387,7,1,\"רבינו אפילו היה אחד שבררו בעל הדין חכם וכו' אלא גם הוא בורר מי שירצה דמשמע שאפי' לוה יכול לומר איני דן אצל זה היינו דוקא כששני הדיינים בעיר אחת אבל אם הדיין שבורר בעל דין שני הוא בעיר אחרת לא וכמו שנתבאר בסוף פרק ששי והכי אמרינן בגמ' כגון בי דיני דרב הונא ורב חסדא דאמר ליה מי קא מטרחנא לך ופירש\\\"י דתרווייהו במקום אחד והתוספות כתבו שהיו סמוכים זה לזה חוץ לשלש פרסאות ואם כן כל שאינו רחוק אלא שלש פרסאות לוה יכול לעכב וכתב בח\\\"מ סימן י\\\"ג על דברי רבינו ואני כתבתיה למעלה שהמומחה דן את האדם בע\\\"כ ואפשר לומר דעת הרמב\\\"ם ז\\\"ל אינו אלא דוקא כשבירר כבר אחד דאז אינו יכול לכוף חבירו דאם לא כן לא היה הדין שוה דכמו שבורר האחד כך יש לו לחבירו לברור אחד אם ירצה אבל כל זמן שלא נברר המומחה יכול לכוף שניהם לדון לפניו עכ\\\"ל. ופירש\\\"י שמתוך כך יצא הדין לאמיתו דצייתי בעלי דינין דסבר החייב הרי אני בעצמי ביררתי האחד ואם היה יכול להפך בזכותי היה מהפך והדיינין בעצמן נוחה דעתן להפך בזכות שניהם מפני ששניהם ביררום. וכתב הרא\\\"ש לפי שיש חסרי הדעת טועים בדברי רש\\\"י ולומדים ממנו שהדיין יש לו להפך בזכות מי שבררו ועומד במקומו להפך דברים אשר לא כדין ונהגו כמה אנשים לברור להם דיין בעל תחבולות ונתלו בדברי רש\\\"י שמשמע שיש לו להפך בזכותו וחלילה וחס שלא דקדקו בדבריו שכתב דסברי הרי ביררתי שסובר כך שיהפך בזכותו יותר מבזכות האחר ומתוך כך צייתי לדינייהו אבל הדיין עצמו חלילה שיהפוך למצוא סברא לזכותו אם לא שיראה לו דין גמור אבל אם היה יכול להטעות את חבירו שיקבל סברתו אע\\\"פ שהוא מפוקפק בה הוא בכלל מטה משפט אבל דעת הרב מתוך שזה בררו מבין דבר לאשורו אם יש לו זכות נושא ונותן עם חבירו וכן עושה הדיין השני למי שבררו ונמצא שלא ישאר שום צד זכות נעלם מעיני הדיינים שניהם והשלישי שומע משא ומתן של שניהם ומכריע ביניהם ויוצא הדין לאמיתו עכ\\\"ל:\",2,0],[8,387,7,2,\"מי שקבל עליו קרוב או וכו'. משנה בסנהדרין פרק זה בורר (סנהדרין דף כ״ד) אמר לו נאמן עלי אבא נאמן עלי אביך נאמנים עלי שלשה רועי בקר ר' מאיר אומר יכול לחזור בו וחכמים אומרים אינו יכול לחזור בו היה חייב לחבירו שבועה ואמר לו דור לו בחיי ראשך ר' מאיר אומר יכול לחזור בו וחכמים אומרים אינו יכול לחזור בו ובגמרא איפליגו ר' יוחנן ור״ל באי מחלוקת לפני גמר דין או לאחר גמר דין ורב יהודה ור' יוחנן איפליגו אי באתן לך מחלוקת או במחול לך ואמר רבא מחלוקת באתן לך אבל במחול לך דברי הכל אינו יכול לחזור בו וסבר נמי דפלוגתייהו לאחר גמר דין אבל לפני גמר דין ד״ה יכול לחזור בו ואמרינן נמי התם (דף כ״ד:) שלח ליה רב נחמן בר רב חסדא לרב נחמן בר יעקב ילמדנו רבינו (אי) לפני גמר דין מחלוקת או לאחר גמר דין מחלוקת והלכה כדברי מי שלח ליה לאחר גמר דין מחלוקת והלכה כדברי חכמים וכו' שלחו ליה מבי רב לשמואל ילמדנו רבינו לפני גמר דין וקנו מידו מאי שלח להו אין לאחר קנין כלום ונראה דכי אמרינן רב אשי אמר הכי שלח ליה לאו למיפלג אדינא קמא אתי אלא למימר דלא שלח ליה למשאל בהאי גוונא אבל אין ה״נ דדינא הכי הוי וכיון דרבא דבתרא הוא סבירא ליה דמחלוקת באתן לך אבל במחול לך אינו יכול לחזור בו ומחלוקת לאחר גמר דין אבל לפני גמר דין יכול לחזור בו כוותיה נקיטינן ופירוש מחלוקת באתן לך דנתבע אמר לתובע אם יחייבוני פסולים אלו אתן לך בהא דוקא פליג ר״מ דהואיל והממון בידו אין כח לתובע להוציאו אלא בדיינים כשרים אבל במחול לך כגון תובע אמר לנתבע אם יזכוך פסולים הללו יהא מחול לך אין יכול לחזור בו דהא זכה זה במה שבידו מכיון שיצא זכאי וכתב נמוקי יוסף בשם הרא״ה והאחרונים דמחול לך אין פירושו שיאמר כן בפירוש דא״כ היכי ס״ד דבמחול לך מחלוקת דכיון דקי״ל לאחר גמר דין מחלוקת הרי זכו אותו והויא מחילה גמורה אלא הכי פירושה דאמר ליה תובע לנתבע הרי עלי לעשות מתביעה זו בכל מה שיאמרו אבא ואביך הן לפטור הן לחיוב שאין בלשון הזה לשון מחילה ופירוש גמר דין גבי נאמן עלי אבא או אביך הכל מודים דלפני גמר דין היינו קודם שיפסקו הדין ויאמר איש פלוני אתה זכאי איש פלוני אתה חייב ולאחר גמר דין הוי לאחר הפסק.\",1,0],[8,387,7,2,\"ומה שכתב רבינו נגמר הדין והוציא הממון בדין זה הפסול היינו לומר דכיון שנגמר הדין הוה ליה כאילו הוציא הממון כבר ואינו יכול לחזור בו ושלא כדברי הטור והרמ\\\"ך שכתבו שנראה מדברי רבינו וכן כתב נמוקי יוסף בראש מרובה דכל שלא הוציא יכול לחזור בו ואי אפשר לומר כן דאי אפילו בדור לי בחיי ראשך כתב רבינו נגמר ונשבע כמו שאמר לו אינו יכול לחזור וחייב לשלם ואפי' שלא אמר ב\\\"ד איש פלוני זכאי כמו שנכתוב בסמוך כל שכן הכא שנגמר הדין באיש פלוני זכאי שאינו יכול לחזור בו אלא ודאי כמו שפירשתי נראה עיקר אבל בדהיה חייב לחבירו שבועה נחלקו המפרשים שיש אומרים שכיון שפסק הדין על עצמו ואמר דור לי בחיי ראשך היינו גמר דין ומיהו נמי ה\\\"מ כשקבל עליו הלה אבל לא קבל עליו יכול לחזור בו דכיון שלא קבל לא חשיב גמר דין וא\\\"כ מעת שפסק הדין על עצמו עד שיקבל עליו הלה הוי לפני גמר דין וכיון שקבל הלה על עצמו הוי לאחר גמר דין וכתב נמוקי יוסף בשם האחרונים שזה דעת הרי\\\"ף ובפ' המפקיד כתב נמוקי יוסף ששיטה זו היא המחוורת בעיני רוב המפרשים וזה דעת רבינו כמבואר בדבריו ויש חולקים בדבר ומחלוקתם תלוי בחילוף גירסא פרק יש נוחלין ובדקדוק סוגית הגמ' בריש פרק המפקיד ובפרק שבועת הדיינים.\",2,0],[8,387,7,2,\"ומ\\\"ש רבינו אפילו קבל עליו וכו' בשני עדים כשרים או בשלשה ב\\\"ד מומחין היינו כרש\\\"י שפירש דמאי דאמרינן בגמרא כגון דקבליה עליה בחד היינו אליבא דר\\\"מ לומר דאע\\\"ג דלא קבליה לההוא פסול אלא בחד דיינא דאיכא תרי אחריני בהדיה אמר ר\\\"מ יכול לחזור בו וא\\\"כ ר\\\"ע ורבנן בין שקבלו עליו בדיין אחד או בשלשה פליגי ולא כדברי התוס' שפירשו דאליבא דרבנן היא ולומר דדוקא כי קבליה עליה בחד דיינא הוא דאינו יכול לחזור בו אבל אם קבליה עליה בשלשה אפילו רבנן מודו דיכול לחזור בו ואי קנו מיניה הא פסקינן דאין לאחר קנין כלום ואפילו קבל עליו לבעל דינו כבי תרי וקנו מידו אינו יכול לחזור בו כדגרסינן פרק שבועת הדיינים וכן כתב הרי\\\"ף:\",3,0],[8,387,7,6,\"מי שנתחייב בבית דין והביא עדים או ראיה לזכותו וכו'. משנה שם (דף ל\\\"א) כל זמן שהוא מביא ראיה סותר את הדין פירוש כגון שלא אמרו לו הבא עדים וראיה אלא כיון שראו שלא הביאם פסקו הדין והביא עדים או ראיה סותר הדין אמרו לו כל ראיות שיש לך הבא מכאן עד שלשים יום הביא בתוך ל' יום סותר לאחר שלשים יום אינו סותר אמר רשב\\\"ג מה יעשה זה שלא מצא בתוך שלשים ומצא לאחר שלשים אמרו לו הבא עדים אמר אין לי עדים אמרו הבא ראיה אמר אין לי ראיה ולאחר זמן מצא עדים ומצא ראיה הרי זו אינו כלום אמר רשב\\\"ג מה יעשה זה שלא היה יודע שיש לו עדים ומצא עדים לא היה יודע שיש לו ראיה ומצא ראיה אמרו לו הבא עדים אמר אין לי עדים הבא ראיה אמר אין לי ראיה לאחר זמן מצא עדים ומצא ראיה ראה שהוא מתחייב ואמר קרבו איש פלוני ופלוני והעידוני או שהוציא ראיה מתוך אפונדתו הרי זו אינה כלום עד כאן במשנה ואמרינן בעלמא כל מקום ששנה רשב\\\"ג במשנתנו הלכה כמותו חוץ מערב וצידן וראיה אחרונה וראיה אחרונה היינו הבבא השנית של משנה זו דפליג בה רשב\\\"ג ואמרינן בגמרא כי אתא רב שמואל בר יהודה אמר ר' יוחנן לעולם מביא ראיה וסותר עד שיסתום טענותיו כיצד א\\\"ל הבא עדים אמר אין לי עדים הבא ראיה אין לי ראיה אבל באו עדים ממדינת הים או שהיתה דסקיא של אביו פירוש שק של עור ששטרות אביו מונחין בו מופקד ביד אחר הרי זה מביא וסותר:\",1,0],[8,387,7,9,\"בד\\\"א בגדול שנתחייב וכו'. שם ההוא ינוקא דתבעוהו לקמיה דר\\\"נ אמר אית לך סהדי א\\\"ל לא אית לך ראיה א\\\"ל לא חייביה ר\\\"נ הוה קא בכי ואזיל שמעי הנך אינשי אמרו ליה אנן ידעינן במילי דאבוך אמר ר\\\"נ בהא אפי' רבנן מודו דינוקא במילי דאבוה לא ידע ומפרש רבינו שהיה קטן בעת מיתת אביו ועכשיו הגדיל וכן כתב הרמ\\\"ה ונ\\\"ל הטעם דאילו השתא נמי קטן הוה הא קי\\\"ל אין מקבלין עדות שלא בפני בעל דין וקטן כשלא בפניו דמי ועוד דאין נזקקין לנכסי יתומים אלא אם כן רבית אוכלת בהם אבל התוספות פירשו דהשתא נמי קטן היה והא דאין נזקקין קא הדר ביה ר\\\"נ ואמר דיתמי דאכלי דלאו דידהו ליזלו בתר שיבקייהו ומהאי טעמא נמי מקבלין עדות על הקטן א\\\"נ קיום שטר הוה וקטן הוה בעי למפסליה בטענת פרוע או מזוייף בלא עדים וראיה וקיימוהו דמקיימין את השטר שלא בפני בעל דין וכן דעת הרא\\\"ש דקטן הוה השתא דאילו הגדיל בשעת העמדה בדין אמרינן או ידע קודם בואו לדין או חקר אחר שתבעוהו לדין כיון דבר דעת הוא דינו כאחר דעלמא ואין בדבריו אלה כדאי לסתור דברי רבינו דכיון דבשעת מיתת אביו לא הוה ידע במילי דאבוה משום דקטן הוה אע\\\"פ שבשעת העמדה בדין היה גדול אינו יודע מי ומי היודעים זכותו כדי שיחקור מהם:\",1,0],[8,387,7,10,\"מי שקנו מידו וכו'. כתב ספר מצות גדול שכך הורו הגאונים והביא הוא ז\\\"ל ראיה מירושלמי דגרסינן התם המתנה אם לא אעשה לך כך וכך ביום פלוני יהא כך ואירע לו אונס רבי יוחנן אומר אונסא כמאן דלא עבד וריש לקיש אמר אונסא כמאן דעבד והלכתא כרבי יוחנן לגבי ריש לקיש:\",1,0],[8,387,8,1,\"ב\\\"ד שנחלקו וכו' עד וכל אלה הדברים דברי קבלה הם. משנה פ\\\"ק דסנהדרין:\",1,0],[8,387,8,2,\"ב״ד של שלשה וכו' עד יוסיפו הדיינים שנים. משנה פרק זה בורר (סנהדרין דף כ״ט):\",1,0],[8,387,8,2,\"אמרו שלשה מהם זכאי וכו' עד ומעמידין את הממון בחזקת בעליו. הם דברים פשוטים ובסוף פרק שאחר זה יתבאר שיכולים להוסיף דיינים עד ע\\\"א ולא יותר:\",2,0],[8,387,8,2,\"כתב הראב\\\"ד א\\\"א רואה אני בגמרא וכו'. טעמו של הראב\\\"ד מדאמרינן בסוף פ\\\"ק דסנהדרין (דף י\\\"ז) ההוא דאמר איני יודע כמאן דליתיה דמי ואי אמר טעמא לא שמעינן ליה וסבור לראב\\\"ד דבין בדיני ממונות בין בדיני נפשות קאמר ורבינו סובר דלא קאמר אלא בדיני נפשות דוקא והטעם אכתוב בפרק שאחר זה:\",3,0],[8,387,8,2,\"והרמ\\\"ך\",4,0],[8,387,8,2,\"כתב נמצאו חמשה נושאים ונותנים וכו'. תימה היאך ישאו ויתנו חמשה והא האחד אומר איני יודע וכיון שאינו יודע לא ישא ולא יתן מ\\\"מ אם ידע אחר מכאן יכול לישא וליתן דכי אמרינן אי אמר טעמא לא שמעינן ליה בדיני נפשות לחובה הוא דאמרינן אבל לזכות אף בדיני נפשות שמעינן ליה דלא גרע מאחד מהתלמידים ודיני ממונות לזכות הוא דחובתו של זה זכותו של זה וצ\\\"ע עכ\\\"ל:\",5,0],[8,387,8,2,\"ודע שהרשב\\\"א בתשובה כתב שהוא סבור כדברי הראב\\\"ד ושכן דעת כמה גדולים:\",6,0],[8,387,8,2,\"וכתב עוד ז\\\"ל וכן נ\\\"ל מהירושלמי דב\\\"ד של שלשה שאמר אחד איני יודע והוסיפו שנים ואח\\\"כ אמר אחד מהארבעה איני יודע שהדין נגמר ע\\\"פ השלשה כאילו היתה תחלת ישיבתן בשלשה אלו דגרסינן התם בפרק היו בודקין (הלכה ו') תני למה אמרו מוסיפין דיינים שאם היו שנים מהראשונים מזכים ואחד מהאחרונים ליגמר הדין בשלשה אמר ר' אילא מכיון שנראה דינו ליגמר בארבעה אין גומרים אותו בשלשה אמר ר' יוסי ותשמע מינה שלשה שדנו ומת אחד מהם חותמים בשנים וכותבין אע\\\"פ שחתמנו בשנים בשלשה דננו ונראה לי פירושו שאם היו שנים מהראשונים מזכין ואחד מהאחרונים יושב עמהם בדין כלומר נושא ונותן עמהם ודן ואינו רוצה לומר מזכה אלא דן עמהן בין לזכות בין לחובה אע\\\"פ שאמר הרביעי איני יודע נגמר הדין בשלשה שהרביעי שאמר איני יודע אינו מכללם אלא כמאן דליתיה דמי ולפיכך נגמר הדין בשלשה אלה ולפיכך היה סבור רבי אילא דכיון שהיתה ישיבתן בארבעה לא יגמר בפחות מארבעה והרביעי שאמר איני יודע מעכב בארבעה כאחד מהשלשה שאמר איני יודע והא דקאמר ברישא שנים מהראשונים מזכים ואחד מהאחרונים לאו למימרא שיהא אותו שמן הראשונים מזכה ג\\\"כ ושיהו שלשתן מזכין והרביעי חולק ומחייב שא\\\"כ היאך יחלוק רבי אילא ויאמר שיהיו צריכים כולן להשוות לדעת אחת ולא ילך אחר השלשה שאם תאמר לפי שאלו ב\\\"ד שקול וכל ב\\\"ד שקול הרי הוא כאילו ירדו לדעות שא\\\"כ אף אנו נאמר כן בדיני נפשות כל שמוסיפין שנים צריכים להיות כולם נוטים לדעת אחת וזה אינו דהא כשהיה ב\\\"ד הטיה לטובה באחד והטיה לרעה בשנים ואע\\\"פ שכל שהוסיפו הרי הם ב\\\"ד שקול ואין לומר שיחלק רבי אילא בין דיני נפשות לדיני ממונות אלא נראה שעל כרחנו יש לנו לפרש כמו שפירש' וכל ששנים מזכין מן הראשונים ואחד מהאחרונים יושב ודן עמהם אע\\\"פ שחולק ומחייב יגמר הדין ע\\\"פ ב\\\"ד זה כאילו היתה תחלת ישיבתן בשלשה וקי\\\"ל כרישא דירושלמי ושתים זו שמענו חדא דאין האומר איני יודע נחשב מכלל הבית דין מדקאמר רבי אילא שנראה דינו ליגמר בארבעה ועוד דאם אמר אחד מן הארבעה איני יודע יגמר הענין ע\\\"פ שלשה שהם מנין הראוי ונ\\\"ל כי בירושלמי נסרך הרמב\\\"ם במה שכתב ז\\\"ל או שאמרו שלשה זכאי ואחד חייב ואחד אמר איני יודע וכו' הולכין אחר הרוב ע\\\"כ הצריך שלשה לומר זכאי כפשוטו של ירושלמי זה וגרם לו זה מה שהוא סבור שאף האומר איני יודע כמאן דאיתיה דמי וא\\\"כ עד שיהיו שלשה מזכין או מחייבין אין כאן רוב עכ\\\"ל והרבה סעד לדברי רבינו שפשט הירושלמי אתי כוותיה:\",7,0],[8,387,8,2,\"כתב הרמ\\\"ך אם ארבעה אומרים זכאי או חייב וכו'. אע\\\"פ שלא פירשו כן רבותי יפה פירש זה הרב דכיון דאיכא שלשה שיודעים בדיני ממונות אבל בדיני נפשות לא אמרינן הכי כדמוכח בשמעתין ולפי סוגית הגמ' לא נראה דברי הרב דהא חזינא בפ\\\"ק (ה':) דמקשה לשמואל משנים אומרים זכאי ואחד אומר איני יודע דאמרינן יוסיפו הדיינים ומקשה ואמאי ולהוי כשנים שדנו ומתרץ שאני התם דאדעתא דתלתא יתיבי ה\\\"נ אע\\\"ג דשלשה יכולים לעשות דין לבדם כיון דאדעתא דחמשה יתבי לא יכלי תלתא למגמר דינא עכ\\\"ל. ויש לומר דשאני התם שמתחלה היו שלשה שייך למימר הכי כשאחד אומר איני יודע אבל הכא ליכא למימר אדעתא דארבעה או ה' נחתי מאחר שמתחלה לא היו אלא ג':\",8,0],[8,387,8,3,\"כל מי שאמר איני יודע אינו צריך וכו'..\",1,0],[8,387,9,1,\"סנהדרין שפתחו כולם בדיני נפשות וכו'. סוף פירקא קמא דסנהדרין (דף י\\\"ז.) מימרא דרב כהנא ויהיב טעמא דכיון דאם לא מצאו לו זכות ביום אחד מעבירין אותו עד למחר שמא ימצאו טעמי זכות ויפטרוהו והני תו לא חזו ליה זכותא:\",1,0],[8,387,9,2,\"סנהדרי קטנה שנחלקו וכו'. משנה בסנהדרין פרק היו בודקין (סנהדרין דף מ').\",1,0],[8,387,9,2,\"ומה שכתב וזה שאמר איני יודע הרי הוא כמי שאינו וכו'. מדאמרינן ספ\\\"ק דסנהדרין (דף י\\\"ז) אמר ר' אבהו במוסיפין עושין בית דין שקול לכתחלה פשיטא מהו דתימא האי דקאמר איני יודע כמאן דאיתיה דמי ואי אמר מילתא שמעינן ליה קמ\\\"ל האי דקאמר איני יודע דכמאן דליתיה דמי ואי אמר טעמא לא שמעינן ליה וסובר רבינו דדוקא לחובה הוא דלא שמעינן ליה אבל לזכות שמעינן ליה דהא אפילו חייב בהדיא חוזר ומלמד זכות וממאי דפרכינן פשיטא מפיק רבינו דלא מיירי הכא אלא בדיני נפשות דתנן בהו בהדיא מוסיפין שנים שנים דאילו בדיני ממונות לא תנן אלא יוסיפו הדיינים ולא תנן בהדיא אי חד או תרי והיכי פריך פשיטא אלא ודאי בדיני נפשות עסקינן וכיון דבדיני ממונות לא אתמר האי מימרא אי ההוא דאמר איני יודע הדר ואמר טעמא שמעינן ליה ועוד דטעמא מאי אמרינן דכמאן דליתיה דמי דמשום חומר דיני נפשות אין לו לחזור וללמד חובה אבל בדיני ממונות דלא שייך האי טעמא הוי כמאן דאיתיה ועוד דבדיני ממונות מה שהוא חובה לזה הוא זכות לזה ואי אמר טעמא שמעינן ליה.\",2,0],[8,387,9,2,\"ועל מ\\\"ש רבינו יוסיפו הדיינים שנים נמצאו חמשה נושאין ונותנין בדבר כתב הראב\\\"ד א\\\"א אני רואה בגמ' שאותו שאמר איני יודע אינו מן המניין ואי אמר טעמא לא שמעינן ליה נמצא לאחר שהוסיפו אינו אלא ארבעה, ובמה שכתבתי נתיישבה השגה זאת דלא מיירי ההיא דאי אמר טעמא לא שמעינן ליה אלא בדיני נפשות דוקא אבל לא בדיני ממונות ורבינו בפרק ח' מיירי לענין דיני ממונות שהרי בב\\\"ד של שלשה מיירי. ומ\\\"ש ועוד הראשון הרי הוא אומר איני יודע ואינו לא מזכה ולא מחייב השגה זו איני מכיר וכי אי אפשר שמתחלה היה מסופק בדבר ולכן אמר איני יודע ובמשא ובמתן הותר לו הספק ההוא ונטה לצד אחד.\",3,0],[8,387,9,2,\"ומ״ש רבינו ואם לא ראה גדול שבדיינים אומר נזדקן הדין ופוטרין אותו. סוף פרק היו בודקין (סנהדרין דף מ״ב) לא ראו מאי א״ר אחא פוטרין אותו וכו' אמר ר' יוחנן פוטרין אותו ועוד שם תנו רבנן אומרים בדיני ממונות נזדקן הדין ואין אומרין בדיני נפשות נזדקן הדין מאי נזדקן הדין אילימא קש דינא כלומר זקן דין זה ועמוק וצריך להמתין בו איפכא מיבעי ליה כלומר שבדיני נפשות צריך לעיין יותר אמר רב הונא בר מנוח משמיה דרב אחא בריה דרב איקא איפוך ותפס כוותיה ולא מצאתי טעם מספיק למה תפס כן דהא התם בסמוך פליג רב אשי ואמר לעולם לא תיפוך ומאי נזדקן הדין חכם דינא כלומר יפה עמדנו על בוריו והוה ליה לתפוס כוותיה דבתרא הוא ומאריה דגמ' טפי מרב הונא בר מנוח ועוד דלא מפיך לברייתא אם לא שנאמר דטפי משמע בלשון נזדקן קש דינא מחכם דינא וצ״ע:\",4,0],[8,387,9,2,\"כתב הראב\\\"ד היו אלו כנגד אלו ואחד אומר איני יודע א\\\"א זה א\\\"א. והטעם להראב\\\"ד בזה שאותו שאומר איני יודע אינו מן המנין וכיון שמתחלה היו כ\\\"ג ונסתלק אחד כשאמר איני יודע ומוסיפין עליהם שנים שנים לעולם הם זוגות וא\\\"א להיות שבדיינים הנמנים חוץ מאותו שנסתלק שיהיו אלו כנגד אלו ואחד אומר איני יודע לפי שמנין כזה אינו זוגות ובמה שכתבתי בסמוך שדעת רבינו שאותו שאמר איני יודע יכול לחזור ולזכות נתיישב זה שכיון שבידו לזכות הרי הוא מהמנין.\",5,0],[8,387,9,2,\"ומה שכתב רבינו היו אלו כנגד אלו וכו'. הוא כגון שהיו בשלשה [ועשרים] ואמר אחד איני יודע והוסיפו שנים והיו י\\\"ב מזכין וי\\\"ב מחייבין ואותו האחד אומר איני יודע או שחזר אותו שאמר איני יודע וזיכה ואחד מאותם שהוסיפו אמר איני יודע מוסיפין והולכין וכו':\",6,0],[8,387,9,3,\"ב״ד הגדול וכו'. ס״פ היו בודקין (סנהדרין דף מ״ב) תניא ר״י אומר כשם שאין מוסיפין על ב״ד של ע״א כך אין מוסיפין על ב״ד של כ״ג ואע״ג דלית הלכתא בב״ד של כ״ג בב״ד של ע״א משמע דכ״ע מודו מדקאמר כשם שאין מוסיפין ועוד דלא אשכחן במוסיפין דמתני' תוספת אלא עד ע״א נראה דאין מוסיפין משם ומעלה:\",1,0],[8,387,10,1,\"אחד מהדיינים בדיני נפשות וכו'. ומ״ש רבינו ובכלל לאו זה שלא יחזור המלמד זכות. משנה פרק אחד דיני ממונות (סנהדרין דף ל״ב) אמנם ראיית הפסוק לא נזכרה שם:\",1,0],[8,387,10,2,\"במה דברים אמורים בשעת משא ומתן וכו'. מימרא דרב שם (דף ל\\\"ד) ופירש רש\\\"י דבשעת משא ומתן בעינן שיעמוד בדבריו לחזר אחר ראיות שמא ימצא חיזוק לזכות דשמא לא טעה אבל בשעת גמר דין שחיפש כבר הכל ועכשיו נראה שטעה חוזר ומלמד חובה:\",1,0],[8,387,10,3,\"תלמיד שהיה מזכה ומת רואין וכו'. סנהדרין פרק נגמר הדין (סנהדרין דף מ״ג) בעא מיניה רב אחא בר הונא מרב ששת אמר אחד מן התלמידים יש לי ללמד עליו זכות ונשתתק מהו ופירש״י מי אמרינן אי לא נשתתק הוה מיחוש בדבריו וצריך לסתור הדין ולהביא דיינים אחרים מנפח רב ששת בידיה נשתתק אחד אפילו אחד בסוף העולם נמי פירש״י מנפח כלומר רוח הוא זה שכיון שנשתתק מה הועיל אי להכי אתית למיחש בכל היוצאים ליהרג נמי אימא שמא יש אחד בסוף העולם. התם לא קאמר הכא קאמר מאי ת״ש דאמר ר' יוסי בר חנינא אחד מן התלמידים שזיכה כלומר הוציא דבריו וטעמו לאור ומת רואין אותו כאילו הוא חי ועומד במקומו זיכה אין לא זיכה לא:\",1,0],[8,387,10,5,\"שנים שאמרו טעם אחד וכו'. סנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ד) בעא מיניה ר' אסי מר' יוחנן אמרו שנים טעם אחד משני מקראות מהו אמר ליה אין מונין להם אלא אחד פירש״י משום דחד מהנך קראי לאו להכי אתא דקי״ל לא נכתבו שני מקראות לטעם אחד הילכך חד מינייהו מטעא טעי.\",1,0],[8,387,10,5,\"ומ\\\"ש רבינו אפילו משני מקראות כלומר לא מיבעיא אם הם ממקרא אחד דלא חשיבי אלא כחד אלא אפי' אם אמרו שניהם טעם אחד משני מקראות לא חשיבי אלא כחד מהטעם שכתבתי ובזה אין מקום למה שהשיג הרמ\\\"ך:\",2,0],[8,387,10,6,\"ומפי השמועה למדו שאין מתחילין בדיני וכו'. משנה בסנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ה) דיני נפשות מתחילין מן הצד פירוש מן הקטנים:\",1,0],[8,387,10,7,\"וכן אין פותחין בדיני נפשות לחובה וכו'. משנה שם דיני נפשות פותחין לזכות ואין פותחין לחובה ואמרינן עלה בגמרא היכי אמרינן להו ואתמר התם סברות טובא ואביי ורבא דאמרי תרווייהו הכי אמרינן ליה אי לא קטלת לא תדחל ותני כוותייהו:\",1,0],[8,387,10,8,\"אמר אחד מהתלמידים וכו'. משנה בסנהדרין פרק היו בודקין (סנהדרין דף מ') אמר אחד מהתלמידים יש לי ללמד עליו חובה משתקין אותו אמר יש לי ללמד עליו זכות מעלים אותו ומושיבין אותו עמהם ולא היה יורד משם כל היום ובגמ' (דף מ״ב) והתניא אם יש ממש בדבריו [לא היה יורד משם לעולם ואם אין ממש בדבריו] אינו יורד כל היום וכו' אמר אביי תרגימה אאין ממש בדבריו.\",1,0],[8,387,10,8,\"ומ\\\"ש אפי' אמר הנידון עצמו וכו'. שם במשנה אפי' הוא אומר יש לי ללמד על עצמי זכות שומעין לו ובלבד שיהא ממש בדבריו:\",2,0],[8,387,10,9,\"ב״ד שטעו וכו'. משנה בסנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ב):\",1,0],[8,387,10,9,\"במה דברים אמורים כשטעו וכו'. שם בגמ' (דף ל\\\"ג:) אמר ר' חייא בר אבא אמר ר' יוחנן והוא שטעה בדבר שאין הצדוקים מודים בו אבל טעה בדבר שהצדוקים מודים בו זיל קרי בי רב הוא:\",2,0],[8,387,10,9,\"כיצד אמרו הבא על הערוה וכו'. שם אההיא דר' יוחנן דבסמוך היכי דמי אין חוזרין אמר ר' אבהו אמר ר' יוחנן כגון שטעה שלא כדרכה שאין הצדוקים מודים בו ובפ\\\"ק דהוריות (דף ד') גרסינן אמר שמואל אין ב\\\"ד חייבים עד שיורו בדבר שאין הצדוקים מודים בו:\",3,0],[8,387,11,1,\"מה בין דיני ממונות וכו' עד וביום שלאחריו לחובה. הכל משנה בסנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ב) ובקצת ספרי רבינו דיני ממונות מטין ע״פ עד אחד וכו' והיא גירסא משובשת וצריך למחוק תיבת עד וכך מצאתי בנוסחא ישנה וכך הוא כפי המתבאר בגמ' והענין הוא כמו שביאר רבינו ז״ל בראש פ״ח:\",1,0],[8,387,11,2,\"לפיכך אין דנין וכו' עד ומתחילין בדינו. משנה וגמ' שם:\",1,0],[8,387,11,3,\"דיני ממונות אע\\\"פ שדנין אותם בכל יום וכו' מדבריהם שאין דנין בע\\\"ש. כך היא הגירסא הנכונה וכן מצאתי בספר ישן שלא היה כתוב למדו כמו בספרינו והדין ירושלמי כתבו הרא\\\"ש בפ' אחד דיני ממונות וז\\\"ל הירושלמי אסור לדון דיני ממונות בע\\\"ש והא מתני' דפליגא אין דנין דיני נפשות בע\\\"ש דיני נפשות הוא דלא דיינינן בע\\\"ש הא דיני ממונות דיינינן אמרי כאן להלכה כאן לדברי תורה וכן הוא בספר מצות גדול:\",1,0],[8,387,11,4,\"הכי גרסינן אחד דיני נפשות ואחד דיני מלקיות ואחד דיני גלות הדינים האלו שוים בהם וכו'. ומה שכתב שדיני מלקיות כדיני נפשות מדאמר רבה בפ\\\"ק דסנהדרין מלקות במקום מיתה עומד וכמו שיתבאר פרק ששה עשר מהלכות אלו ודיני גלות גם הם דיני נפשות:\",1,0],[8,387,11,4,\"ואין אחד מהם בשור הנסקל. פרק אחד דיני ממונות (סנהדרין דף ל״ו:) אמר ר' אבהו וכולן כלומר הדרכים האלו אין נוהגין בשור הנסקל חוץ מכ״ג:\",2,0],[8,387,11,5,\"המסית אין דיניו כשאר דיני נפשות מכמנין לו את וכו' ואינו צריך התראה. משנה בסנהדרין פרק ארבע מיתות כל חייבי מיתות שבתורה אין מכמנין להם חוץ מזה אמר לשנים הן עדיו ומביאים אותו לב\\\"ד וסוקלין אותו אמר לאחד וכו' מכמנין לו עדים לאחורי הגדר.\",1,0],[8,387,11,5,\"ומה שכתב ואם יצא מב״ד זכאי וכו'. פ' אחד דיני ממונות (סנהדרין דף ל״ג:) תנו רבנן מנין ליוצא מב״ד חייב ואמר אחד יש לי ללמד עליו זכות שמחזירין אותו תלמוד לומר נקי אל תהרוג ומנין ליוצא מב״ד זכאי ואמר אחד יש לי ללמד עליו חובה שאין מחזירין אותו ת״ל צדיק אל תהרוג אמר רב שימי בר אשי וחילופיהן למסית:\",2,0],[8,387,11,5,\"ואין טוענין למסית. ברייתא בסנהדרין פרק זה בורר (סנהדרין דף כ״ט) בדיני נפשות אע״ג דלא טען טוענין לו ואין טוענין למסית ופירש״י אין טוענין ב״ד בשבילו טענות זכות אא״כ טענם הוא:\",3,0],[8,387,11,5,\"ומושיבין בדינו זקן וכו'. ברייתא פרק אחד דיני ממונות (סנהדרין דף ל״ו:) אין מושיבין בסנהדרין זקן וסריס ומי שאין לו בנים וכו' וחילופיהן במסית דרחמנא אמר לא תחמול ולא תכסה עליו:\",4,0],[8,387,11,6,\"דיני ממונות והטומאות והטהרות מתחילין מן הגדול וכו'. משנה שם (דף ל\\\"ב):\",1,0],[8,387,11,7,\"דיני ממונות וכן הטומאות והטהרות וכו'. ברייתא שם (דף ל\\\"ו) הטהרות והטומאות האב ובנו הרב ותלמידו מונין להם שנים דיני ממונות ודיני נפשות ודיני מכות קידוש החדש ועיבור השנה וכו' אין מונין להם אלא אחד ופירש\\\"י הטהרות והטומאות שהוראתן ביחיד ואין בהם מנין אם כן חולקין וצריך לעמוד [למנין] אם רבו המטמאים או המטהרים מונין [את האב ובנו או את הרב ותלמידו] שנים אבל דיני [ממונות] ונפשות ומכות שמנין שלהם אף בתחלת הדין ומן התורה שזה צריך שלשה וזה כ\\\"ג וכן קידוש החדש שצריך שלשה דמשפט כתיב ביה וכו' וכן עיבור השנה שצריך ג' וה' וז' וכו' ע\\\"כ. אבל גירסת רבינו אינה כן אלא כך היא דיני ממונות הטהרות והטומאות אב ובנו הרב ותלמידו מונים להם שנים דיני נפשות ומכות וכו' אין מונין להם אלא אחד:\",1,0],[8,387,11,7,\"וכתב הראב\\\"ד דיני ממונות וכן הטומאות והטהרות וכו' א\\\"א אין הגמרא כן עכ\\\"ל. ומאחר שגירסא אחרת היתה לרבינו אין כאן השגה:\",2,0],[8,387,11,8,\"ומ\\\"ש רבינו זה שאנו מונין האב עם הבן וכו'. כתב כן כי היכי דלא תיקשי לן היאך גומרין את הדין בקרובים:\",1,0],[8,387,11,8,\"וכתב הראב\\\"ד חיי ראשי איני רואה לא טעם ולא ריח בדברים אלו וכו'. וי\\\"ל שדעת רבינו לומר דכי פסלינן קרובים לדון היינו דוקא כשעומדים שם בשעת גמר דין דהיינו כשאומרין איש פלוני אתה זכאי איש פלוני אתה חייב אבל קודם לכן נושאים ונותנין עמהם ונמנין עמהם לראות אם רבו המזכין או המחייבין ואפשר שהטעם בדיני ממונות כיון שיחיד מומחה דן אותם א\\\"כ ה\\\"ל דומיא דטהרות וטומאות וכפירש\\\"י ולכך עולין למנין וכמו שכתבתי ואפ\\\"ה בשעת גמר דין לא ישבו שם שאין גומרין שום דין בקרובים:\",2,0],[8,387,11,10,\"תלמיד שהיה חכם וכו'. שם (דף ל\\\"ו) אמר רב שונה אדם לתלמידו ודן עמו בדיני נפשות ואותיבנא עליה מברייתא דהטהרות והטומאות אב ובנו רב ותלמידו מונין להם שנים דיני נפשות וכו' אין מונין להם אלא אחד ופריק כי קאמר רב כגון רב כהנא ורב אסי דלגמריה דרב הוו צריכי ולסבריה לא הוו צריכי ופירש\\\"י הטעם דכיון דלסבריה לא צריך גברא באפי נפשיה הוא דאי משום גמרא דשמע מיניה כל ישראל נמי ממשה קבלו ואין אלו טעמים הבנת לבו דנימא אם היתה חכמתו מפי רב אחר היה אומר טעם אחר:\",1,0],[8,387,11,11,\"הכל כשרים וכו'. משנה שם (דף ל\\\"ב) הכל כשרים לדון דיני ממונות ואין הכל כשרין לדון דיני נפשות אלא כהנים ולוים וישראלים המשיאים לכהונה ואמרינן עלה בגמרא (דף ל\\\"ו:) הכל לאיתויי מאי אמר רב יהודה לאתויי ממזר ואקשינן עלה דהא תנינא בפרק בא סימן (נדה דף מ\\\"ט:) יש ראוי לדון דיני ממונות ואין ראוי לדון דיני נפשות והוינן בה לאיתויי מאי ואמר רב יהודה לאיתויי ממזר ואסיקנא חדא לאיתויי גר וחדא לאתויי ממזר ומפרש רבינו דהאי גר דמרבינן הכא היינו דוקא כשאמו מישראל וכמו שכתבתי בפרק שני:\",1,0],[8,387,11,11,\"וגר דן את חבירו וכו'. ביבמות פרק מצות חליצה (יבמות דף ק״ב) אמר רבא גר דן את חבירו ואם היתה אמו מישראל דן אפילו ישראל והיינו לענין דיני ממונות דוקא ודלא כרש״י שפירש דלדיני נפשות נמי אלא כדעת רבינו הסכימו כל הפוסקים שראיתי דבריהם:\",2,0],[8,387,11,11,\"והסומא באחת מעיניו כשר לדון וכו'. כבר נתבאר לעיל סוף פרק שני דמייתי לה מדאמרינן בפרק אחד דיני ממונות (סנהדרין דף ל״ד:) ההוא סמיא פירוש באחת מעיניו דהוה בשכונתיה דר״י דהוה דאין דינא ולא אמר ליה ולא מידי:\",3,0],[8,387,12,1,\"אומרים להם מכירים אתם אותו וכו'. משנה בסנהדרין פרק היו בודקין (סנהדרין דף מ') מכירים אתם אותו התריתם בו:\",1,0],[8,387,12,2,\"אחד תלמיד חכם וכו'. בפרק קמא דסנהדרין (דף ח':) גבי פלוגתא דר\\\"מ ורבנן במוציא שם רע רב פפא אמר הכא באשה חבירה עסקינן וקא מיפלגי בפלוגתא דר\\\"י בר יהודה ורבנן דתניא ר' יוסי בר' יהודה אומר חבר אינו צריך התראה לפי שלא ניתנה התראה אלא להבחין בין שוגג למזיד ופסק רבינו כרבנן ופירש\\\"י אלא להבחין שלא יוכל לומר סבור הייתי שמותר ויש לתמוה על רבינו שפוסק כרבנן דחבר נמי צריך התראה היאך נתן טעם שלא ניתנה אלא להבחין בין שוגג למזיד דהוי טעם לר\\\"י בר' יהודה דאמר חבר אינו צריך מפני שכבר הוא יודע שהוא אסור וי\\\"ל דלרבנן נמי הויא התראה להבחין בין שוגג למזיד אלא דהוי בגוונא אחריתי דחבר וע\\\"ה שוין בו כגון להודיע שחתיכה זו חלב או שהיום שבת. ואחר שכתבתי זה מצאתי לרב המגיד שכתב כיוצא בזה בתחלת הלכות איסורי ביאה ואע\\\"ג דבההיא אוקימתא אתו חכמים דמתני' כר\\\"י בר' יהודה לא חיישינן לה למיפסק כוותיה משום דאיכא התם אוקימתי אחריני דלא תלי פלוגתא דר\\\"מ וחכמים בפלוגתא דר\\\"י ורבנן:\",1,0],[8,387,12,2,\"וכיצד מתרין בו וכו'. ברייתא שם פרק היו בודקין (סנהדרין דף מ:) שהיו שואלים את העדים קיבל עליו התראה התיר עצמו למיתה המית תוך כדי דיבור:\",2,0],[8,387,12,2,\"וכן אם שתק וכו'. מדבעינן שיתיר עצמו למיתה ועוד דתניא פרק אלו הן הנשרפין (דף פ\\\"א:) התרו בו ושתק התרו בו והרכין בראשו פירוש או התרו בו והרכין בראשו פעם ראשונה ושניה מתרין בו שלישית כונסין אותו לכיפה אלמא דאין מלקין אותו אע\\\"פ שהרכין בראשו והוא הדין למיתה דמלקות במקום מיתה עומד.\",3,0],[8,387,12,2,\"ומה שכתב וחייב אתה עליה מיתת בית דין כלומר שאין צריך שיודיעוהו באי זו מיתה הוא נהרג וזה לפי שפסק כרבנן דפליגי ארבי יהודה דאמר עד שיודיעוהו באיזו מיתה הוא נהרג ורבנן סברי שכיון שהודיעוהו שהוא חייב מיתת ב\\\"ד סגי בהכי כדאיתא פרק קמא דסנהדרין ופרק אלו הן הנשרפין.\",4,0],[8,387,12,2,\"ומ\\\"ש וצריך שיעבור וכו'. כבר כתבתי בסמוך הברייתא האומרת ששואלים אותו תוך כדי דיבור אלמא דבלאו הכי לא קטלינן ליה:\",5,0],[8,387,12,2,\"ובין שהתרה בו וכו'. ספ\\\"ק דמכות (דף ו':) אמר רבא מתרה שאמרו אפי' מפי עצמו ואפילו מפי השד ופירש\\\"י מפי עצמו ההרוג עצמו התרה בו ואפשר לפרש בו עוד פירוש אחר שההורג היה מתרה בעצמו ואומר ראוי לי לימנע מלעשות זאת שא\\\"כ יהרגוני ב\\\"ד ואחר כך גבר יצרו עליו ועשאה ולמד רבינו ק\\\"ו לעבד ואשה ודין השד כיון אליו רבינו באומרו אפי' שמע קול המתרהו ולא ראהו:\",6,0],[8,387,12,3,\"אמרו העדים היתה לו התראה וכו' עד ויראה לי. הכל משנה סוף פרק אחד דיני ממונות (סנהדרין דף ל״ז):\",1,0],[8,387,12,4,\"משנגמר דינו אין משהין אותו וכו'. בסוף הנחנקין (סנהדרין דף פ״ט) גבי זקן ממרא אמרו במשנה היו משמרין אותו עד הרגל וממיתין אותו שנאמר וכל העם ישמעו וייראו דברי ר' עקיבא ר' יהודה אומר אין מענין דינו של זה להמתין מלהמיתו עד הרגל אלא ממיתין אותו מיד משמע דאף ר' עקיבא לא אמר אלא בזקן ממרא משום דכתיב ביה וכל העם ישמעו וייראו אבל בשאר חייבי מיתות מודה דאין מענין דינם. ובפ' אחד דיני ממונות (סנהדרין דף ל״ה) הקשו על מאי דתנן שאין דנין דיני נפשות בע״ש וליגמריה לדיניה בשבת וליקטליה בחד בשבא ותירצו נמצא אתה מענה דינו.\",1,0],[8,387,12,4,\"ומ\\\"ש אפילו היתה עוברה וכו'. משנה בפ\\\"ק דערכין (דף ז') האשה שיצאה ליהרג אין ממתינין לה עד שתלד ישבה על המשבר ממתינין לה עד שתלד. ופירש\\\"י אין ממתינין לה עד שתלד אלא הורגין ולדה עמה דחד גופא היא ישבה על המשבר קודם שנגמר הדין ממתינין לה עד שתלד דכיון דעקר ונע ממקומו גופא אחרינא הוא.\",2,0],[8,387,12,4,\"ומה שכתב ומכין אותה כנגד בית ההריון וכו'. שם ויהיב טעמא כדי שלא תבא לידי ניוול:\",3,0],[8,387,12,4,\"וכל אשה שתהרג מותר ליהנות בשערה. שם במשנה ובגמ' מפרש טעמא:\",4,0],[8,387,12,5,\"מי שיצא ליהרג והיה זבחו וכו'. גם זה שם:\",1,0],[8,387,13,1,\"מי שנגמר דינו וכו' עד אפילו יודע בעצמו ששקר העידו עליו וכך הוא מתודה. משנה פרק נגמר הדין (סנהדרין דף מ״ב:) ואע״פ שלא הזכירה במשנה (דף מ״ג) בכרוז אלא המיתה והעבירה והעדים הזכיר רבינו גם המקום והזמן שכך אמרו בגמ' אמר אביי וצ״ל ביום פלוני ובשעה פלונית ובמקום פלוני דילמא איכא דידע ואתא ומזים להו והמשנה קצרה משום דפשיטא דע״י כן ילמדו עליו זכות באמרם עמנו היה ביום פלוני.\",1,0],[8,387,13,1,\"ומ\\\"ש מוסרין לו ב' תלמידי חכמים פירוש פעם שלישית דוקא כך פירש בגמרא.\",2,0],[8,387,13,1,\"ומה שכתב ועדיו הם ההורגין אותו וכו'. ומה שכתב ורוצח שלא הרגוהו עדיו כו'. נלמד ממאי דתניא בפרק נגמר הדין (סנהדרין דף מ״ה:) מות יומת המכה רוצח הוא אין לי אלא במיתה הכתובה בו מנין שאם אי אתה יכול להמיתו במיתה הכתובה בו שאתה ממיתו בכל מיתה שאתה יכול להמיתו תלמוד לומר מות יומת המכה מ״מ ואסיקנא התם דלא גמרינן מרוצח משום דהוו רוצח וגואל הדם שני כתובים הבאים כאחד ואין מלמדין ובפי״ד הארכתי בדין זה על דברי רבינו עיין שם:\",3,0],[8,387,13,2,\"ואחר שמתודה משקין אותו וכו'. שם (דף מ\\\"ג) מימרא דרב חסדא:\",1,0],[8,387,13,3,\"זה היין וכו'. שם ברייתא נשים יקרות שבירושלים היו מתנדבות ומביאות ואסיקו בגמ' דאם לא התנדבו באים משל צבור:\",1,0],[8,387,13,4,\"אין ב״ד יוצאין וכו'.. וכל ב״ד שהרגו וכו'. פ' ד' מיתות (סנהדרין דף ס״ג) ר״ע אומר מנין לסנהדרין שהרגו את הנפש שאין טועמין כל אותו היום תלמוד לומר לא תאכלו על הדם:\",1,0],[8,387,13,4,\"ואין מברין וכו'. שם רבי דוסא אומר מנין שאין מברין על הרוגי ב\\\"ד תלמוד לומר לא תאכלו על הדם:\",2,0],[8,387,13,4,\"ודברים אלו אסורים וכו'. שם על כולם אינו לוקה משום דהוה ליה לאו שבכללות כלומר שאנו לומדים ממנו דברים רבים:\",3,0],[8,387,13,5,\"בחולו של מועד וכו'. מועד קטן (דף י\\\"ד):\",1,0],[8,387,13,6,\"הרוגי בית דין וכו'. משנה פרק נגמר הדין (סנהדרין דף מ\\\"ו:):\",1,0],[8,387,13,7,\"מי שנגמר דינו וברח וכו' עד ה\\\"ז יהרג. משנה ספ\\\"ק דמכות (דף ז') מי שנגמר דינו וברח ובא לפני אותו ב\\\"ד אין סותרין את דינו כל מקום שיעמדו שנים ויאמרו מעידים אנו באיש פלוני שנגמר דינו בב\\\"ד של פלוני ופלוני ופלוני עדיו הרי זה יהרג ומה ששינה רבינו וכתב ובא לב\\\"ד אחר יתבאר בסמוך:\",1,0],[8,387,13,7,\"במה דברים אמורים ברוצח וכו'. בסנהדרין פ' נגמר הדין (סנהדרין דף מ״ה:) אמר שמואל נקטעה יד העדים פטור והקשו עליו מהא דתנן כל מקום שיעמדו שנים ויאמרו וכו' תרגמה שמואל בהן הן עדיו כלומר שאותם שמעידין שנגמר דינו הם עדיו הראשונים שהעידו עליו בבית דין ונתחייב על פיהם ובתר הכי אוקימנא להא דשמואל בשאר חייבי מיתות לבד מרוצח וממילא כי אוקימנא למתניתין בהן הן עדיו דוקא בשאר חייבי מיתות דומיא דשמואל אבל ברוצח אפילו אינן עדיו הראשונים.\",2,0],[8,387,13,7,\"ומה שכתב ויהרגוהו בידם דכתיב יד העדים תהיה בו בראשונה וכו'. ומה שכתב והוא שיעידו עליו בבית דין של כ\\\"ג. פשוט דאין הורגין אלא בבית דין של כ\\\"ג:\",3,0],[8,387,13,8,\"מי שנגמר דינו בב\\\"ד של חוצה לארץ וכו'. בסוף פ\\\"ק דמכות (דף ז') הקשו במשנה שכתבתי בסמוך רישא אסיפא דמרישא משמע דלפני ב\\\"ד אחר סותרין דינו ומסיפא משמע דאפילו לפני ב\\\"ד אחר אין סותרים דקתני כל מקום ואמר אביי ל\\\"ק כאן בארץ ישראל כאן בחוצה לארץ דתניא רבי יהודה ברבי דוסתאי אומר משום ר' שמעון בן שטח ברח מארץ ישראל לחוצה לארץ אין סותרין דינו מח\\\"ל לארץ סותרין את דינו מפני זכותה של ארץ ישראל ובבבא זו כתב רבינו דין נגמר דינו בחוצה לארץ וברח לארץ ישראל ובבא שקודם זו המתחלת מי שנגמר דינו וברח לב\\\"ד אחר כתב דין נגמר דינו בארץ ישראל וברח לחוצה לארץ ולכך כתב שם וברח לב\\\"ד אחר דכל שלא ברח מחוצה לארץ לארץ ל\\\"ש לן בין אותו ב\\\"ד לב\\\"ד אחר דבכל מקום אין סותרין את דינו:\",1,0],[8,387,14,1,\"ארבע מיתות וכו'. בסנהדרין (דף מ\\\"ט:) ריש פרק ארבע מיתות נמסרו לבית דין סקילה שרפה הרג וחנק:\",1,0],[8,387,14,1,\"שכל מיתה האמורה בתורה סתם היא חנק. ברייתא פרק ארבע מיתות (סנהדרין דף נ״ב:):\",2,0],[8,387,14,1,\"וההורג את חבירו מיתתו בסייף. משנה פרק הנשרפין (סנהדרין דף ע״ו:) בברייתא פרק ארבע מיתות יליף לה מקרא.\",3,0],[8,387,14,1,\"ומ\\\"ש וכן אנשי עיר הנדחת מיתתן בסייף. משנה פרק הנשרפין שם:\",4,0],[8,387,14,2,\"כל מיתה מהם מצות עשה היא וכו'.. ואין רשות למלך להרוג וכו'..\",1,0],[8,387,14,3,\"כל מחוייב מיתת בית דין וכו'..\",1,0],[8,387,14,4,\"סקילה חמורה וכו'. כך העלו בגמרא פרק ארבע מיתות (סנהדרין דף מ״ט:) דכסדר שנשנו כך סדר חומרתן ואע״ג דר״ש פליג התם במתני' הלכה כת״ק:\",1,0],[8,387,14,4,\"וכל מי שנתחייב בשתי מיתות וכו'. משנה בסנהדרין פרק אלו הן הנשרפין (דף פ\\\"א) מי שנתחייב בשתי מיתות ב\\\"ד נידון בחמורה ואמר בגמרא דאפילו נגמר דינו בקלה וחזר ועבר עבירה חמורה נדון בחמורה:\",2,0],[8,387,14,5,\"ואחד האיש ואחד האשה וכו'. פ\\\"ק דקידושין (דף ל\\\"ה) ופ\\\"ק דב\\\"ק (דף ט\\\"ו) איש או אשה השוה הכתוב אשה לאיש לכל עונשין שבתורה:\",1,0],[8,387,14,6,\"כל חייבי מיתות שנתערבו וכו'. משנה פרק אלו הן הנשרפין (דף ע\\\"ט:):\",1,0],[8,387,14,7,\"מי שנגמר דינו וכו'. משנה שם רוצח שנתערב באחרים כולם פטורים רבי יהודה אומר כונסין אותו לכיפה ובעו בגמרא מאן אחרים ואמר שמואל דפלוגתייהו ברוצח שלא נגמר דינו שנתערב באחרים שנגמר דינם ופטרי רבנן משום דאין גומרין דינו של אדם אלא בפניו וכיון דאין מכירין אותו ה\\\"ל שלא בפניו וידוע דהלכה כרבנן ור\\\"ל ס\\\"ל דבהא כולי עלמא לא פליגי דפטירי ורבה נמי משמע דהכי ס\\\"ל דבהא כולי עלמא לא פליגי דפטירי ואם כשנתערב מי שלא נגמר דינו עם מי שנגמר פטור כל שכן כשנתערב מי שנגמר דינו עם שאר העם דפטירי אבל מכל מקום יש לדקדק בלשון רבינו למה לא כתב מי שנגמר דינו שנתערב עם שאר העם או עם מי [שלא] נגמר דינו ולא נודע מי הוא כולן פטורין והיה מקצר יותר. ודע שמה\",1,0],[8,387,14,7,\"שכתב לפי שאין גומרין דינו של אדם אלא בפניו לא קאי אלא אסוף מילתיה שכולן רוצחים אלא שזה נגמר דינו וזה לא נגמר דינו אבל ברישא דמי שנגמר דינו שנתערב עם שאר העם אין צריך לטעם זה דתיפוק ליה דאינך לאו מחוייבי מיתה נינהו:\",2,0],[8,387,14,8,\"מי שעמד על נפשו וכו'. סנהדרין פרק נגמר הדין (סנהדרין דף מ״ה:) אמר שמואל נקטעה יד העדים פטור מ״ט דבעינן יד העדים בראשונה וליכא אלא מעתה עדים גדמים דמעיקרא הכי נמי דפסילי שאני התם דאמר קרא יד העדים שהיתה כבר וכו' ומי בעינן קרא כדכתיב והתניא מות יומת המכה רוצח הוא אין לי אלא במיתה הכתובה בו מניין שאם אי אתה יכול להמיתו במיתה הכתובה בו שאתה ממיתו בכל מיתה שאתה יכול להמיתו ת״ל מות יומת המכה מ״מ שאני התם דאמר קרא מות יומת ופירש״י יד העדים יד שהיתה להם תהיה להם בשעת מיתה אבל גדמים מעיקרא לא משתמע מיניה דזו היא יד שלהם וכו' אין לי אי לא כתב אלא יומת אלא מיתה הכתובה בו סייף עכ״ל. ולפום ריהטא משמע דרוצח משום דכתיב ביה מות יומת אשתני משאר חייבי מיתות בתרתי חדא דשאר חייבי מיתות בעינן דלא ימיתנו אלא במיתה הכתובה בו ורוצח אתה ממיתו בכל מיתה שאתה יכול תרתי דבשאר חייבי מיתות בעינן יד העדים בראשונה ואילו ברוצח לא בעינן דמדמקשה מההיא דרוצח אתה ממיתו בכל מיתה שאתה יכול משמע דהא בהא תליא דאי בעינן יד העדים בראשונה אי אתה ממיתו בכל מיתה שאתה יכול ואי אתה ממיתו בכל מיתה שאתה יכול לא בעינן יד העדים בראשונה ויש לתמוה על רבינו שכתב שגם בשאר מחוייבי מיתה ממיתין אותם בכל מיתה שיכולין ואין חילוק בין רוצח לשאר אלא אי בעינן יד העדים בראשונה אי לא דלדידיה מאי מקשה לשמואל מרוצח שאתה ממיתו בכל מיתה שאתה יכול דהא בשאר מחוייבי מיתה הכי דינא אלא שיד עדים בראשונה בעינן וה״ה גבי רוצח ואפשר לומר דכי מקשה לשמואל לישנא דברייתא דייק דקאמר שאם אי אתה יכול להמיתו דמשמע דקאי לבית דין או לכל אחד מישראל דכל הקודם בו זכה דאי קאי לעדים שאם אינם יכולים להמיתו מיבעי ליה אלא משמע דלא בעינן יד עדים בראשונה וקשיא לשמואל אבל אה״נ דשאר חייבי מיתות נמי הוי דינא דממיתין אותו בכל מיתה אלא דבעינן יד עדים בראשונה ואין לי אלא מיתה הכתובה בו פירוש יד העדים בראשונה ושני ליה דשאני רוצח דכתיב ביה מות יומת לרבות אפי' דליכא יד עדים בראשונה. ויש לדקדק שתפס רבינו דין דנקטעה יד העדים גבי מי שעמד על נפשו דמשמע דאם לא עמד על נפשו חייב ולפום סוגיין משמע דשמואל סתם מיירי בין עמד על נפשו בין לא עמד:\",1,0],[8,387,14,9,\"כל הרוגי ב״ד וכו' עד בקברות אבותיהם. משנה פ' נגמר הדין (סנהדרין דף מ״ו):\",1,0],[8,387,14,9,\"ויש לקרוביהם וכו':\",2,0],[8,387,14,10,\"צריכים בית דין להתיישב וכו'. משנה סוף פירקא קמא דמכות (דף ז') סנהדרין ההורגת אחת בשבוע נקראת חובלנית ואף על גב דפליגי תנאי התם פסק כתנא קמא:\",1,0],[8,387,14,10,\"אף על פי כן אם אירע להם וכו'. מדאמרינן במשנה פרק נגמר הדין (סנהדרין דף מ״ה:) אין דנין שנים ביום אחד הא בשני ימים דנין:\",2,0],[8,387,14,10,\"היו שניהם בעבירה אחת ומיתה אחת וכו' עד אין הורגין שניהם ביום אחד. גם זה שם (דף מ\\\"ו:):\",3,0],[8,387,14,11,\"אין דנין דיני נפשות וכו'. סנהדרין פרק ארבע מיתות (סנהדרין דף נ״ב:) ובאת אל הכהנים הלוים ואל השופט בזמן שיש כהן יש משפט בזמן שאין כהן אין משפט.\",1,0],[8,387,14,11,\"ומ\\\"ש והוא שיהיה ב\\\"ד הגדול שם בלשכה שבמקדש. כך אמרו וקמת ועלית אל המקום מלמד שהמקום גורם:\",2,0],[8,387,14,12,\"בתחלה וכו'. בסוף מס' מדות (פרק ה'):\",1,0],[8,387,14,12,\"שאין ישיבה בעזרה אלא למלכי בית דוד. בפרק חלק (סנהדרין דף ק״א) על ענין ירבעם אמרו גמירי דאין ישיבה בעזרה אלא למלכי בית יהודה ופירש״י גמירי הלכה למשה מסיני ולא מקרא.\",2,0],[8,387,14,12,\"ומה שכתב ומשנתקלקלה השורה גלו ממקום למקום ולעשרה מקומות גלו וסופן לטבריה ומשם לא עמד ב\\\"ד הגדול עד עתה וקבלה שבטבריה עתידים לחזור תחלה. בפ\\\"ד דר\\\"ה (דף ל'):\",3,0],[8,387,14,13,\"ארבעים שנה וכו'. כן מפורש בסנהדרין פרק היו בודקין (סנהדרין דף מ״א):\",1,0],[8,387,14,14,\"בזמן שדנין וכו'. משנה סוף פ\\\"ק דמכות (דף ז') סנהדרין נוהגת בארץ ובחוצה לארץ וכבר כתב זה רבינו ולא שנאה כאן אלא להשמיענו שאותם ארבעים שנה שבטלו דיני נפשות בא\\\"י ג\\\"כ בטלו בחוצה לארץ אע\\\"פ שהיה כהן מקריב:\",1,0],[8,387,15,1,\"כיצד מצות הנסקלים וכו' עד ויד כל העם באחרונה. משנה פרק נגמר הדין (סנהדרין דף מ״ה).\",1,0],[8,387,15,1,\"ומה שכתב ומכסין ערותו מלפניו הכי איתא במשנה האיש מכסין אותו מלפניו והאשה מלפניה ומאחריה דברי ר' יהודה וחכמים אומרים האיש נסקל ערום ואין האשה נסקלת ערומה וסבירא ליה לרבינו דלא פליגי אלא באשה אבל באיש כולי עלמא מודו דמכסין אותו מלפניו ואף על פי שהוא מכוסה מלפניו קראוהו ערום ופסק כחכמים.\",2,0],[8,387,15,1,\"ומה שכתב שהרי נאמר סקול יסקל וכו'. שם בגמרא.\",3,0],[8,387,15,1,\"ומה שכתב ואם לא מת מדחיפה זו מגביהים העדים אבן שהיתה מונחת שם משא שני בני אדם והעד השני מרפה ידו וכו'. ברייתא שם ותמהני למה לא כתב רבינו כמו ששנינו במשנה דוחפו על מתניו כלומר דוחפו על מתניו מאחוריו והוא נהפך ונופל על לבו וחוזר והופכו על מתניו וכתב רש\\\"י הטעם שכשהוא מושכב פרקדן מגונה יותר ואפשר גם כן שהטעם כדי שיהיה לבו לצד מעלה שבכדי שהעד השני יטול את האבן ויתנה על לבו ולפיכך לא חשש רבינו לכתבו מכיון שכתב בסמוך מגביהין העדים אבן וכו' ומשליך האבן על לבו שפשיטא שאז לבו לצד מעלה גם קיצר שלא פירש שדוחפין אותו מעומד כדי שיפול ממקום יותר גבוה כי כך אמרו בגמרא:\",4,0],[8,387,15,2,\"עובד ע״ז וכו'. ברייתא בכתובות פרק נערה (כתובות דף מ״ה:) ופירוש שער שעבד בו היינו שער העיר שעבד בה:\",1,0],[8,387,15,3,\"מצות הנשרפין כו' עד שתצא נפשו. משנה פרק ד' מיתות (סנהדרין דף נ״ב):\",1,0],[8,387,15,6,\"מצות עשה לתלות את המגדף ועובד ע\\\"ז וכו'. משנה שם (דף ה':) כל הנסקלים נתלים דברי ר\\\"א וחכ\\\"א אינו נתלה אלא המגדף והעובד ע\\\"ז וידוע דהלכה כחכמים:\",1,0],[8,387,15,6,\"והאיש נתלה וכו'. ג\\\"ז שם ופסק כחכמים:\",2,0],[8,387,15,7,\"כיצד מצות הנתלין וכו' עד אינו עובר עליו. משנה שם (דף מ\\\"ו).\",1,0],[8,387,15,7,\"ומ\\\"ש ותולהו סמוך לשקיעת החמה יצא לו ממה שאמרו שם (ע\\\"ב) בברייתא משהין אותו עד סמוך לשקיעת החמה וגומרין דינו וממיתין אותו ואחר כך תולין אותו. ויש לדקדק שרבינו לא כתב שממיתין אותו סמוך לשקיעת החמה כמו שאמרו בברייתא אלא כתב ותולהו סמוך לשקיעת החמה שנראה שאין הקפידא אלא שיתלוהו סמוך לשקיעת החמה וכבר אפשר שימיתוהו מבעוד יום. ויש לומר שמאחר שכתב אחר שסוקלין אז משקעין את הקורה וכו' משמע שתיכף לסקילה תליה וכיון שכתב שתולהו סמוך לשקיעת החמה ממילא משמע שסקילתו הויא קרוב לשקיעת החמה:\",2,0],[8,387,15,9,\"אין תולין וכו'. שם תנו רבנן עץ שומע אני בין בתלוש בין במחובר תלמוד לומר קבור מי שאינו מחוסר אלא קבורה יצא זה שמחוסר קציצה וקבורה ורבי יוסי אומר מי שאינו מחוסר אלא קבורה יצא זה מי שמחוסר חפירה תלישה וקבורה כלומר דאף נעוץ נתמעט מן המשמע הזה ורבנן תלישה לאו כלום היא כלומר אין כאן חסרון מעשה ומדברי רבינו נראה דדוקא מחובר לקרקע ממעט אבל לא נעוץ ואתי כרבנן:\",1,0],[8,387,15,9,\"שהעץ שנתלה עליו וכו'. ברייתא שם (דף מ\\\"ה ע\\\"ב) דכל הני נקברים עמו והתניא אין נקברים עמו אמר רב פפא מאי עמו בתפיסתו:\",2,0],[8,387,15,10,\"כל הנסקלין וכו' עד סוף הפרק. במשנה פ' ארבע מיתות הוזכרו הנשרפין ונהרגין ופרק הנחנקין הוזכרו הנחנקין:\",1,0],[8,387,15,11,\"ומה שכתב אבל לאחר מיתת אשתו וכו'. בפרק הנשרפין (סנהדרין דף ע״ו:) פלוגתא דרבי ישמעאל ורבי עקיבא ופסק כרבי עקיבא:\",1,0],[8,387,16,1,\"ואף על פי שמלקות בשלשה. פלוגתא דר' ישמעאל ות\\\"ק פ\\\"ק דסנהדרין (דף י') דרבי ישמעאל סבר דהוי בכ\\\"ג ותנא קמא סבר דהוי בג' ופסק כת\\\"ק.\",1,0],[8,387,16,1,\"ומ\\\"ש במקום מיתה היא עומדת ק\\\"ל לאי זה ענין הוי עומד במקום מיתה מאחר שרבינו פוסק דהוי בשלשה דאליבא דר' ישמעאל דסבר דהוי בכ\\\"ג הוא דאמר רבא במקום מיתה עומד ולפיכך צריך כ\\\"ג. ונראה דלענין זה הוא עומד במקום מיתה שצריך מומחין ושצריך עדים והתראה ודרישה וחקירה כד\\\"נ וכמ\\\"ש רבינו בסמוך ולמדנו כן ממ\\\"ש רבא מלקות במקום מיתה עומד ונהי דלמאי דאיפליגו רבנן עליה דר' ישמעאל ואמרו דסגי בשלשה אינו עומד במקום מיתה מ\\\"מ לענין דבעינן מומחין דלא אשכחן דאיפליגו עליה הוי במקום מיתה ועוד ראיה דבעינן מומחין מדאיפליגו רבי ישמעאל ורבנן באי בעינן כ\\\"ג או אי סגי בשלשה ואם איתא דלרבנן לא בעי מומחין אדמיפלגי באי בעינן כ\\\"ג ליפלגו באי בעינן מומחין א\\\"ו מומחין סמוכים בעינן דלהא מילתא במקום מיתה עומד:\",2,0],[8,387,16,4,\"עבר על לאו שניתק לעשה וכו'. פרק בתרא דמכות (דף ט\\\"ו:) תני תנא קמיה דר' יוחנן כל מצות לא תעשה שיש בה קום עשה קיים עשה שבה פטור ביטל עשה שבה חייב וכו' ור\\\"ל אומר קיימו ולא קיימו במאי קא מיפלגי וכו' מר סבר התראת ספק שמה התראה ומר סבר לא שמה התראה וביאור הדברים שמשעבר על לא תעשה שיש בה קום עשה כגון שנטל האם על הבנים לרבי יוחנן אינו חייב עד שיבטל העשה כגון שיהרגנה וכל שלא הרגה פטור לפי שיכול הוא עדיין לקיים העשה והרי כאן שגמר הלאו תלוי בביטול העשה וכשמתרין בו אל תקח האם ספק הוא שמא לא יבטל העשה להרגה אלמא התראת ספק שמה התראה ור\\\"ל סובר שבשעה שעבר הלאו נגמר חיובו למלקות אבל העשה ניתן לעקור המלקות ולכשיבוא לב\\\"ד אז יקיים העשה ויפטר או ילקה ואם היה גמר הלאו תלוי בביטול העשה לא היה לוקה עליו משום דהויא התראת ספק ולא שמה התראה וידוע דהלכתא כר' יוחנן לגבי ר\\\"ל ואע\\\"פ שתפס רבינו לשון קיום בלשונו ואליבא דר\\\"י דפסק כוותיה הו\\\"ל לתפוס לשון ביטול אין חשש מכיון שכתב ועבר ולא קיים דמשמע ממש שביטלו דהיינו עבר ולא קיימו היינו בטלו דאי לא ביטלו אי אתה יכול לקרות בו עבר ולא קיימו שהרי עדיין בידו לקיימו. אך ק\\\"ל דבגמ' משמע דלמ\\\"ד ביטלו ולא ביטלו אינו חייב עד שהוא בעצמו יבטל העשה כגון שלקח האם על הבנים והמיתה אבל אם מתה מעצמה פטור ואונס לא משכח התם גוונא דילקה כשיבטל העשה אליבא דר\\\"י ורבינו כתב פ\\\"ה דהל' נערה בתולה שאונס שגירש כופין אותו להחזיר ואינו לוקה ואם מתה גרושתו קודם שיחזירנה או נתקדשה לאחר לוקה ומעתה משמע דלא סבירא ליה לרבינו כר\\\"י אלא כר\\\"ל והיינו לשון קיום וכמו שכתבתי והשתא קשה דכר\\\"י הו\\\"ל למיפסק אי משום דהלכתא כוותיה לגבי ר\\\"ל אי משום דהא פסק כוותיה בהתראת ספק וממילא הלכתא כוותיה בהא נמי כיון דקא מפלגי בהתראת ספק ומשם נמשך מחלוקתם בלאו שניתק לעשה אי בעינן ביטלו או לא קיימו וי\\\"ל דהיינו לפי גירסת רש\\\"י אבל לפי גירסת הרי\\\"ף שגורס תני קיימו ולא קיימו כר' יוחנן אתי שפיר מ\\\"ש רבינו וכפירוש אחרים שכתב הר\\\"ן בסוף חולין ולענין התראת ספק אמרינן בפרק הלוקין דפלוגתא דר\\\"י ור\\\"ל היא ור\\\"י סבר שמה התראה וידוע דהלכתא כוותיה לגבי ר\\\"ל וכן פסק רבינו פה ובפ\\\"ה מהלכות שבועות כתב שאין לוקין על התראת ספק אא\\\"כ היה לאו שלו מפורש בתורה ואיני יודע מנין לו חלוק זה:\",1,0],[8,387,16,5,\"עבר עבירה שיש בה מלקות ומיתת ב״ד וכו'. בפרק אותו ואת בנו (חולין דף פ״א) דרבי יוחנן אומר דשוחט אותו ואת בנו לעבודה זרה חייב וכגון דאתרו ביה משום אותו ואת בנו ולא אתרו ביה משום עבודה זרה ואזדא לטעמיה דאמר רבי יוחנן חייבי מיתות שוגגין כלומר שלא התרו בו משום מיתה ויש בה עוד חיוב דבר אחר כגון מלקות והתרו בו משום מלקות חייב וריש לקיש פליג עליה ופסק כר' יוחנן:\",1,0],[8,387,16,6,\"אינו צריך שני עדים למלקות וכו' אבל האיסור עצמו בעד אחד יוחזק. נראה שלמד כן מדאמרינן עד אחד נאמן באיסורין ומפרש רבינו נאמן לאסור הדבר.\",1,0],[8,387,16,6,\"ומ\\\"ש בד\\\"א שלא הכחיש וכו'. מדאמרי' בהנזקין שאם א\\\"ל נטמאו טהרותיך שאינן בידו אינו נאמן ומשמע לרבינו דהיינו בשהכחישו:\",2,0],[8,387,16,7,\"שתק בעת שהעיד וכו'. בקדושין פרק האומר (דף ס\\\"ה:) אמר אביי אמר לו עד אחד נטמאו טהרותיך והלה שותק נאמן ומשמע דמיירי בשאחר כך טען להכחיש העד דאי לאו הכי פשיטא דמהימן. ומכל מקום ממ\\\"ש\",1,0],[8,387,16,7,\"רבינו ואחר שעבר והתרו בו טוען להכחיש העד משמע שאם טען להכחישו קודם שעבר הויא הכחשה:\",2,0],[8,387,16,9,\"כיצד מלקין אותו וכו' עד הרי החזן גולה. כלל הדברים משנה במכות פרק אלו הן הלוקין (מכות דף כ\\\"ב):\",1,0],[8,387,16,9,\"ומה שכתב וצריך להיות יותר בדעה וחסר בכח ברייתא שם (דף כ\\\"ג) פלוגתא דרבי יהודה ורבנן ופסק כרבנן:\",2,0],[8,387,16,9,\"ומה שכתב ומגביה הרצועות בשתי ידיו. שם תנא כשהוא מגביה מגביה בשתי ידיו.\",3,0],[8,387,16,9,\"ומה שכתב ושתי רצועות של חמור כך פירשו בגמרא:\",4,0],[8,387,16,10,\"ומה שכתב שאין מכין שנים כאחד. בספרי ויליף לה מדכתיב יכנו:\",1,0],[8,387,16,11,\"ומה שכתב הגדול שבדיינים קורא וכו'. עד והשלישי אומר לחזן הכה. ברייתא שם ונתבאר שם שמצוה לצמצם שיסיים הפסוקים כשיגמור המלקות ואם לאו חוזר לתחלת המקרא וכן הוא במשמע לשון רבינו:\",1,0],[8,387,16,12,\"ואם לא מת הרי החזן עבר על מצות לא תעשה וכו'. ברייתא בסיפרי והובאה פרק אלו הן הלוקין.\",1,0],[8,387,16,12,\"ומה שכתב אם הוסיף עובר בלאו. שם אין לי כלומר דאסור להוסיף אלא מכה רבה מכה מועטת מנין תלמוד לומר לא יוסיף מכל מקום:\",2,0],[8,387,16,12,\"והוא הדין לכל מכה את חבירו וכו'. זה פשוט בעצמו.\",3,0],[8,387,16,12,\"ומה שכתב אפילו הכה עבד. למדו מדתנן בפרק החובל (בבא קמא דף פ\\\"ז) החובל בעבד כנעני של אחרים חייב בכולם וכיון שהוא חייב על העבד ממון בהכאת שוה פרוטה ממילא שכשאין בה שוה פרוטה עובר ותניא בפרק ב' דמכות (דף ח' ע\\\"ב) עבד ועכו\\\"ם גולה ולוקה על ידי ישראל וישראל גולה ולוקה על ידי עכו\\\"ם ומשמע דלרבותא נקט עכו\\\"ם שישראל לוקה על ידו וכל שכן שהוא לוקה על ידי עבד שהוא מקיים מצוה ואוקימנא בגמרא דהא דלוקה ישראל על ידו בשהכהו הכאה שאין בה שוה פרוטה ובפרק אלו נערות איתמר דדוקא משום דלית בה שוה פרוטה לוקה אבל אי אית בה שוה פרוטה ממונא משלם מלקא לא לקי:\",4,0],[8,387,17,1,\"כיצד מלקין את המחוייב וכו' שאין מוסיפין וכו'. משנה פרק בתרא דמכות (דף כ\\\"ב) כמה מלקין אותו מ' חסר אחת וכו' רבי יהודה אומר מ' שלימות ופסק כחכמים ומדברי רבינו נראה שמה שאינו לוקה ארבעים שלימות הוא תקנת חכמים שכך כתב לפיכך אמרו חכמים ולמד כן ממה שאמר רבה שם כמה טפשאי שאר אינשי דקיימי מקמי ס\\\"ת ולא קיימי מקמי גברא רבה דאילו בספר תורה כתיב ארבעים ואתו חכמים ובצרי חדא הרי שהחכמים הם שעשו כן ואע\\\"פ ששם דרשו מדכתיב במספר ארבעים ולא כתיב ארבעים במספר נראה שסובר רבינו שהוא אסמכתא בעלמא ויותר נראה לי דלטעמיה אזיל שכל דבר שאינו מפורש בהדיא בתורה קרי דברי סופרים וחכמים קבלו ממרע\\\"ה דרשא זו ומטעם זה:\",1,0],[8,387,17,2,\"כשאומדין את החוטא וכו'. שם במשנה:\",1,0],[8,387,17,2,\"אמדוהו שיכול לקבל עשרים וכו'. ברייתא פרק קמא דסנהדרין (דף ז'):\",2,0],[8,387,17,2,\"אמדוהו לקבל מ' וכו' עד יותר על האומד. משנה שם מכות (דף כ\\\"ב):\",3,0],[8,387,17,3,\"אמדוהו היום וכו' עד כיוצא בזה. שם במתני' אמדוהו לקבל מ' לקה מקצת ואמרו אין יכול לקבל מ' פטור אמדוהו לקבל י\\\"ח ומשלקה אמרו שיכול הוא לקבל מ' פטור ואמרינן בגמ' לקה אין לא לקה לא ורמינהי אמדוהו לקבל מ' וחזרו ואמרו אין יכול לקבל מ' פטור אמדוהו לקבל י\\\"ח וחזרו ואמדוהו ואמרו שיכול לקבל מ' פטור אמר רב ששת לא קשיא הא דאמדוהו ליומיה הא דאמדוהו אמחר וליומא אחרא ונ\\\"ל שלדעת רבינו כך פירושו דרמי מתרווייהו מרישא ומסיפא דהכא דקתני בין כשאמדוהו לשמונה עשרה וחזרו ואמדוהו לארבעים בין כשאמדוהו לארבעים ואמרו אינו יכול לקבל ארבעים אי לקה כבר פטור ואי לא לקה חייב דבאמדוהו לקבל שמונה עשרה וחזרו ואמדוהו לקבל ארבעים לוקה ארבעים ובאמדוהו לקבל ארבעים וחזרו ואמרו אינו יכול לקבל ימתין עד שיבריא או לוקה ומתרפא וחוזר ולוקה והתם תני בתרווייהו דאע\\\"ג דלא לקה פטור ואמר רב ששת ל\\\"ק הא דאמדוהו ליומיה כלומר ברייתא בדאמדוהו ללקות בו ביום ונשתהה עד למחר אע\\\"ג דלא לקה אזלינן בתר אומדנא קמא לקולא דכיון דליומיה אמדוהו הו\\\"ל כאילו לקה כבר ואפילו הכי כי אמדוהו לקבל ארבעים וחזרו לומר אינו יכול פטור והו\\\"ל כאילו התחילו להלקותו מאתמול ואמרו אינו יכול לקבל הא דאמדוהו למחר וליומא אחרא כלומר מתני' לא כשאמדוהו שילקה היום אלא אמדוהו שילקה למחר אם הלקוהו ואח\\\"כ אמדוהו הרי נפטר במלקותו שלקה בין רב למעט ואם אמדוהו קודם שילקה אזלינן בתר אומד שני בין לקולא בין לחומרא כיון שאומד ראשון לא היה אלא ללקות אחר זמן ופירוש זה נראה בעיני יותר מהשני פירושים שפירש\\\"י ורבינו תפס שבראשון אמדוהו לי\\\"ב ואחר לי\\\"ח והוא הדין איפכא וזהו שכתב וכן כל כיוצא בזה. אי נמי דלרבינו לא מקשה אלא מסיפא דקתני אמדוהו לקבל י\\\"ח משלקה אמרו יכול לקבל מ' פטור טעמא דלקה הא אמרו קודם שלקה חייב ורמינהי אמדוהו לקבל י\\\"ח וחזרו ואמרו יכול לקבל מ' פטור ואמר רב ששת ל\\\"ק הא כלומר ברייתא דאמדוהו ללקות בו ביום ונשתהה עד מחר ומש\\\"ה אזלינן בתר אומדן קמא כיון דללקות בו ביום אמדוהו הא כלומר מתניתין כשאמדוהו ללקות למחר אי אמדוהו קודם שלקה אזלינן בתר אומדן שני כיון שמתחלה לא ללקות בו ביום אמדוהו אבל אי לקה אע\\\"פ שחזרו ואמדוהו כיון שלקה נפטר וכן כל כיוצא בו דנקט רבינו לומר דלאו דוקא אמדוהו לי\\\"ב וחזרו ואמדוהו לי\\\"ח דהוא הדין לשאר חשבונות:\",1,0],[8,387,17,4,\"מי שנתחייב מלקיות הרבה וכו' עד שנקלה פטור. משנה שם [ע\\\"ב]. ואמנם\",1,0],[8,387,17,4,\"מ\\\"ש כיצד נתחייב וכו' מ\\\"ה. צ\\\"ע כי כפי טעם רש\\\"י צריך לגרוס מ\\\"ב ואם גירסת רבינו נכונה צריך טעם לדבר גם\",2,0],[8,387,17,4,\"מ\\\"ש אבל אם אמדוהו וכו' צ\\\"ע:\",3,0],[8,387,17,5,\"אבל אם נתקלקל וכו'. ברייתא שם (דף כ\\\"ג) והיא משובשת בנסחתנו ומ\\\"מ למדנו ממנה שאם נתקלקל קודם ההכאה דלוקה שכך כתוב בה אפילו קלקל בתחלה כלומר קודם ההכאה מלקין אותו. אבל\",1,0],[8,387,17,5,\"מ\\\"ש אפילו נתקלקל משיצא מב\\\"ד ללקות ואפילו מבערב צ\\\"ע בנסחת הגמ' שתהיה אמיתית:\",2,0],[8,387,17,5,\"אמדוהו לשתי מלקיות עד ולוקה האומד השני. ברייתא שם קלה בין בראשונה בין בשניה פוטרין אותו נפסקה רצועה בשניה פוטרין אותו בראשונה אין פוטרין אותו ומפרש רבינו ראשונה ושניה מלקות ראשונה ומלקות שניה וכי קתני פוטרין אותו לגמרי משמע בין בראשונה בין בשניה ואין פוטרין היינו ממלקות שניה אבל ממלקות ראשונה נפטר ורש\\\"י פירש בע\\\"א:\",3,0],[8,387,17,6,\"כפתוהו וכו'. מימרא דשמואל שם:\",1,0],[8,387,17,7,\"כל מי שחטא וכו' עד נפטרו מידי כריתתן. משנה שם:\",1,0],[8,387,17,8,\"כהן גדול שחטא וכו'. ירושלמי ריש פרק בתרא דהוריות אמר רבי אלעזר כהן גדול שחטא מלקין אותו ואין מעבירין אותו מגדולתו אמר רבי מנא כתיב כי נזר שמן משחת אלהיו עליו אני ה' כביכול מה אני בגדולתי אף אהרן בגדולתו אמר רבי אבין קדוש יהיה לך כביכול מה אני בקדושתי אף אהרן בקדושתו ר' חנינא ור' אחא בשם ריש לקיש כהן משיח שחטא מלקין אותו בבית דין של שלשה אין תימר בבית דין של עשרים ושלשה נמצאת עלייתו ירידה היא לו ר\\\"ל אמר נשיא שחטא מלקין אותו בבית דין של שלשה מה מחזרין ליה אמר רבי חגי מוטב דינון מחזרין ליה דו קטלין ליה ונראה דמשמע ליה ז\\\"ל דה\\\"ק מוטב שאותן המחזירים אותו יהרגוהו שלא יאריך ימים כיון שהיה מעולה וחטא במזיד בענין שנתחייב מלקות אי נמי מה שאמר שהוא כאילו הורגים אותו הוא מפני שבני אדם יזלזלו אותו הילכך לא יחזירוהו והכי משמע מדאיצטריך למילף מקראי דכ\\\"ג מחזירין ממילא משמע דנשיא כיון דלית ביה קראי אין מחזירין אותו:\",1,0],[8,387,18,1,\"אלו הן הלוקין וכו'. פרק בתרא דמכות (דף י\\\"ג) איפליגו רבי ישמעאל ורבי עקיבא בברייתא דרבי ישמעאל סבירא ליה דחייבי מיתות נמי לוקין ורבי עקיבא ס\\\"ל דאין לוקין ודייקי התם דמדלא תנן במתניתין דאלו הן הלוקין חייבי מיתות דכר\\\"ע אתיא ופסק רבינו כרבי עקיבא משום דהלכתא כוותיה לגבי רבי ישמעאל ועוד דקם ליה מחלוקת בברייתא וסתם במתני' כסתם דמתניתין קיימא לן.\",1,0],[8,387,18,1,\"ומה שכתב וכן העובר על לא תעשה שחייבין עליה מיתה בידי שמים נלמד מדברי רבי עקיבא שאמר חייבי כריתות ישנן בכלל מלקות ארבעים שאם עשה תשובה בית דין של מעלה מוחלים להם חייבי מיתות בית דין אינן בכלל מלקות ארבעים שאם עשו תשובה אין מוחלים להם וחייבי מיתה בידי שמים בההוא טעמא דכרת שייכי דאם עשו תשובה בית דין של מעלה מוחלים להם ואם כן בדין הוא דלקו:\",2,0],[8,387,18,1,\"אבל אם לאו שאין בו מעשה וכו'. פרק ארבע מיתות (סנהדרין דף ס״ג) אמר רבי אלעזר הנודר והמקיים בשם ע״ז לוקה ופריך דהוה ליה לאו שאין בו מעשה ומשני ההוא כר״י דאמר לוקין עליו ומדפריך גמרא בפשיטות הוה ליה לאו שאין בו מעשה ואין לוקין עליו אלמא הכי קיימא לן ועוד מדמשני ההוא כר״י ולא משני סבר לה כר״י אלמא דאליבא דר״י אמר הכי וליה לא סבירא ליה ועוד דאמר בפרק בתרא דמכות (דף י״ז) ופרק שבועות שתים בתרא (שבועות דף כ״א) דרבי יוחנן ס״ל לאו שאין בו מעשה אין לוקין עליו והא קיימא לן דהלכתא כוותיה לגבי ריש לקיש:\",3,0],[8,387,18,2,\"כל לאו שאין בו מעשה וכו'. פרק בתרא דמכות שם ופרק ג' דשבועות שם מימרא דר' יוחנן כל ל\\\"ת שבתורה לאו שיש בו מעשה לוקין עליו ושאין בו מעשה אין לוקין עליו חוץ מנשבע ומימר ומקלל חבירו בשם והקשו בתוספות בפרק שלישי דשבועות דאמאי לא חשיב נמי עדים זוממים ותירצו כיון דכתיב בהו מלקות בהדיא לא חשש למיתנינהו דהמוציא שם רע הא כתיב ביה ויסרו אותו ועדים זוממים למדום מוהצדיקו את הצדיק שהן לוקין:\",1,0],[8,387,18,2,\"וכל לאו שניתן לאזהרת מיתת ב״ד. מכות פ' אלו הן הלוקין (מכות י״ג:) פלוגתא דר' ישמעאל ור״ע ופסק כר״ע ובכל דוכתא נמי אמרינן הוה ליה לאו שניתן לאזהרת מיתת ב״ד ואין לוקין עליו אלמא דהכי הלכתא ופריש התם רבא דאי אתרו ביה לקטלא כ״ע ל״פ דאין לוקה ומת כי פליגי דאתרו ביה למלקות ופירוש לאו שניתן לאזהרת מיתת ב״ד לאו שניתן לאזהרת דבר שחייבין עליו מיתת ב״ד והטעם שאין לוקין עליו לפי שלא ניתן לאזהרת עונש מלקות כשאר לאוין שהרי הוצרך להזהירו שאם לא כן לא היה יכול לחייבו מיתה:\",2,0],[8,387,18,2,\"כל לאו שניתן לתשלומין וכו'. בפרק בתרא דמכות (דף י\\\"ז) קאמר גמרא דלאו דלא תגזול כיון דחייב בתשלומין אין אדם לוקה ומשלם וק\\\"ל דהא בפרק אלו נערות (כתובות דף ל\\\"ב:) אמר רבי יוחנן דכל היכא דאיכא ממון ומלקות מילקא לקי ממונא לא משלם וצריך עיון:\",3,0],[8,387,18,2,\"וכל לאו שניתק לעשה וכו'. משנה בסוף חולין (דף קמ\\\"א) ובפרק בתרא דמכות (דף ט\\\"ז) הנוטל אם על הבנים משלח ואינו לוקה ואפילו רבי יהודה דאמר לוקה ואינו משלח אמר בגמרא דמודה דלאו שניתק לעשה אין לוקין עליו אלא היינו טעמא דאמר לוקה ואינו משלח משום דשלח מעיקרא משמע.\",4,0],[8,387,18,2,\"ומה שכתב אלא אם לא קיים עשה שבהן כבר ביארתי בס\\\"ד בפרק ט\\\"ז:\",5,0],[8,387,18,2,\"ועל לאו שבכללות וכו'. סנהדרין פ' ד' מיתות (סנהדרין דף ס״ג) דרשו מלא תאכלו על הדם שלא יאכל מהבהמה קודם שתצא נפשה ושלא יאכל בשר קדש בעוד הדם במזרק ושאין מברין על הרוגי בית דין ושסנהדרין שהרגו את הנפש אין טועמין כלום ואמרינן עלה דעל כולם אין לוקין משום דהוי לאו שבכללות:\",6,0],[8,387,18,2,\"ושאר כל לאוין שבתורה. כלומר שהם לאוין מפורשין לא שיבואו מכלל עשה דלאו הבא מכלל עשה עשה נמצא עכשיו ששה מיני לאוין שאין לוקין עליהם. אחד לאו שאין בו מעשה. שני לאו שניתן לאזהרת מיתת ב\\\"ד. שלישי לאו שניתן לתשלומין. רביעי לאו שניתק לעשה. חמישי לאו שבכללות. ששי לאו הבא מכלל עשה. על כל אלו אין לוקין וכל שאין בו אחד מאלו לוקין עליו:\",7,0],[8,387,18,3,\"אי זהו לאו שבכללות וכו' כגון לא תאכלו על הדם. כבר נתבאר זה בסמוך:\",1,0],[8,387,18,3,\"וכן אם נאמר לא תעשה דבר פלוני וכו'. בס״פ כל שעה (פסחים דף מ״א) אמר אביי אכל נא לוקה שתים נא ומבושל לוקה שלש רבא אמר אין לוקין על לאו שבכללות איכא דאמרי תרתי הוא דלא לקי חדא מיהת לקי איכא דאמרי חדא נמי לא לקי דלא מייחד לאויה כלאו דחסימה כלומר מה שאמר הכתוב לא תחסום שור שאינו מזהיר אלא על דבר אחד וסמיך ליה פרשת מלקות לעיל מיניה ופירוש הלכה זו לדעת רבינו דאביי סבר לוקין על לאו שבכללות וכשאכלו נא עבר ב' לאוין אחד אל תאכלו ממנו נא והשני אל תאכלו כי אם צלי אש וכבר אכלו בלתי צלי וכשאכלו נא ומבושל לוקה שלש אחת על שאכלו נא ואחת על שאכלו מבושל והג' על שאכלו בלתי צלי וכיון דקי״ל בסנהדרין (דף ס״ג) אין לוקין על לאו שבכללות נדחו דברי אביי וקי״ל כרבא והוא פוסק כלישנא קמא דחד מיהא לקי כדי למעט במחלוקת אביי ורבא כל מאי דאפשר ולכן הוא סובר שבין שאכלו נא ומבושל או נא או מבושל אינו לוקה (אלא) אחת והשגת הראב״ד שכתב א״א אביי ורבא עכ״ל נראה שהיא איך פסק כאביי במקום רבא וכן כתב הרמ״ך ג״כ ובמה שכתבנו נתיישב שגירסת רבינו אינה כגירסתנו אלא דרבא הוא דאמר לאו שבכללות אין לוקין עליו ועיין במ״ש בפ״ח מק״פ.\",2,0],[8,387,18,3,\"ומ\\\"ש ובחדש הוא אומר וכו' עד וכן כל כיוצא בזה. כתב הרב בספר המצות שלו בשורש ט' דהכי איתא בכריתות והוי יודע שהרמב\\\"ן חלוק על רבינו במין השני של לאו שבכללות אם תרצה לעמוד על עיקרן של דברים עיין בהשגותיו:\",3,0],[8,387,18,3,\"נאמר לא ימצא בך וכו'..\",4,0],[8,387,18,4,\"מי שלקה בבית דין וכו'. משנה בסנהדרין פרק אלו הן הנשרפין (דף פ\\\"א ע\\\"ב) מי שלקה ושנה בבית דין כונסין אותו לכיפה ומאכילין אותו שעורים עד שכריסו נבקעת ואמרו בגמ' דדוקא במלקות שיש בו כרת ושכל שלש פעמים היו עבירה אחת:\",1,0],[8,387,18,5,\"מי שעבר על איסור כרת או מיתת ב\\\"ד וכו'. ג\\\"ז משנה שם ההורג נפשות שלא בעדים כונסים אותו לכיפה ומאכילין אותו לחם צר ומים לחץ ובגמ' מ\\\"ש הכא דקתני נותנים לו לחם צר ומים לחץ ומאי שנא התם דקתני מאכילים אותו שעורים אמר רב ששת אידי ואידי נותנים לו לחם צר ומים לחץ עד שיוקטן מעיינו והדר מאכילין אותו שעורים עד שכריסו נבקעת ותניא התם התרו בו ושתק התרו בו והרכין בראשו פירוש או הרכין בראשו פעם ראשונה ושניה מתרין בו שלישית כונסין אותו לכיפה ואע\\\"ג דפליג אבא שאול ואמר שלישית מתרין בו רביעית כונסין אותו לכיפה פסק כת\\\"ק ועוד דאתי כסתם מתניתין דבשלישית כונסין:\",1,0],[8,387,18,5,\"וגרסינן בגמרא עלה דמתניתין ההורג נפשות שלא בעדים כונסין אותו לכיפה מנא ידעינן אמר רב בעדות מיוחדת ושמואל אמר שלא בהתראה ורב חסדא אמר אבימי כגון דאתכחוש בבדיקות ולא אתכחוש בחקירות כדתנן מעשה ובדק בן זכאי בעוקצי תאנים ופירש\\\"י מנא ידעינן הואיל וליכא עדות. בעדות מיוחדת דשנים מעידים עליו ועדותן אמת אלא שאין מיתתו מסורה לב\\\"ד כגון שנים רואין אותו אחד מחלון זה ואחד מחלון זה דאמרינן במסכת מכות דלא מיקטל עלייהו אבל ע\\\"פ ע\\\"א מוציא דבה בעלמא הוא. בעוקצי תאנים בדיקות יתירי ונהי דבן זכאי פטר ליה בההיא הכחשה מקטלא מיהו עדות אמת היא ועייל לכיפה עכ\\\"ל:\",2,0],[8,387,18,6,\"הגונב כלי שרת וכו' עד ופוצעים את מוחו בגזירין. משנה שם ואמרו בגמרא והמקלל בקוסם תני רב יוסף יכה קוסם את קוסמו רבנן ואי תימא רבה בר מרי אמרי יכהו קוסם לו ולקונו ולמקנו ופירש\\\"י יכה קוסם את קוסמו שמקלל כלפי מעלה בקוסם יכה הקוסם את קוסמו היינו כלפי מעלה שנותן קסמים הללו בלבו וקסבר המקלל דהא מחשב ליה האי קוסם בעיניו שהוא ראוי ויש בו כח לקלל בו. יכהו קוסם מקלל את חבירו ואומר יכהו הקוסם הזה לו ולקונו ולמקנו דהיינו כלפי מעלה שהוא קונה את העולם ומקנה לבריותיו את טובו עכ\\\"ל:\",1,0],[8,387,18,6,\"גזירת הכתוב היא וכו':\",2,0],[8,387,19,1,\"כל לא תעשה שיש בו כרת וכו'. כולן נמנו במשנה ואלו הן הלוקין (דף י\\\"ג) וקצתם מייתי לה התם מקרא עונש ואזהרה:\",1,0],[8,387,19,2,\"כל מחוייבי מיתה ביד״ש וכו'. הכי נמנו בברייתא בסוף הנשרפין (סנהדרין דף פ״ג) ומייתי לה מקראי דהוו במיתה. ועל מה שמנה רבינו בכלל מחוייבי מיתה ביד״ש שלוקין עליו מחוסר כפורים ששימש יש לתמוה שבפרק ד' מהלכות ביאת המקדש כתב שאע״פ שעבודתו פסולה וחילל הרי זה פטור וכתב הר״י קורקוס ז״ל דע״כ ט״ס הוא וצריך לכתוב במקומו יתר בגדים ששימש:\",1,0],[8,387,19,4,\"פצוע דכא שנשא בת ישראל ובעל. כתב הראב\\\"ד לא ידעתי נשואין מה צורך וכו'. וכבר נשאל רבינו ע\\\"ז מחכמי לוניל והשיב בארוכה לקיים דבריו כתבו ה\\\"ה פט\\\"ו מהל' איסורי ביאה:\",1,0],[8,387,20,1,\"אין בית דין עונשין באומד הדעת וכו'. ברייתא פרק אחד דיני ממונות (סנהדרין דף צ\\\"ו) אמתניתין דהיו מאיימין על עדי נפשות שמא תאמרו מאומד תנו רבנן כיצד מאומד אומרים להם שמא כך ראיתם שרץ אחר חבירו לחורבה ורצתם אחריו ומצאתם סייף בידו ודמו מטפטף והרוג מפרפר אם כן ראיתם לא ראיתם כלום:\",1,0],[8,387,20,1,\"וכן אם העידו עליו שנים וכו':\",2,0],[8,387,20,2,\"כל מי שעשה דבר וכו':\",1,0],[8,387,20,3,\"איש שאנסוהו וכו'. בהרבה מקומות אין קישוי אלא לדעת מהם ביבמות ריש הבא על יבמתו (יבמות דף נ״ג:) אמר רבא אין אונס לערוה לפי שאין קישוי אלא לדעת והוצרך רבינו לטענת אין קישוי אלא לדעת כגון שאנסוהו לתקוע עצמו בערוה וכיון שכן הרי הוא עושה מעשה וק״ל שאע״פ שהוא עושה מעשה כיון שהוא אנוס דין הוא שיפטר וכמ״ש רבינו בסמוך שאע״פ שהיה מצווה שיהרג ואל יעבור הואיל ואנוס הוא אינו נהרג והיינו אפילו עשה מעשה בידים ומי עדיף טענת אין קישוי אלא לדעת מעושה מעשה בידים ואפשר לומר דבשלמא מעשה שבידים הוא דבר שיכול לעשות באונס ושלא ברצונו אבל קישוי כל שאינו מרוצה בדבר א״א לו להתקשות וכיון שנתקשה ודאי מרוצה הוא ולפיכך חייב והיינו דאמר רבא אין אונס לערוה דמשמע דאין עליו שם אונס וכיון שאין עליו שם אונס בדין שיהא חייב וכמ״ש למדנו מעתה שאם נתקשה לאשתו ואנסוהו שיבא הוא עצמו על הערוה פטור ואם אנסוהו להתקשות ותקעוהו בערוה חייב וצ״ע. ועדיין קשה היאך כתב רבינו שחייב מיתת ב״ד אפילו את״ל שהיה לדעת מאחר שכתב שאנסוהו פשיטא ודאי שלא התרו בו כיון שלא היתה התראה היאך יתחייב מיתת ב״ד וכן השיגו הרמ״ך. וי״ל דחייב דקאמר היינו לומר שאין לו דין אנוס אלא הרי הוא כמי שעשה ברצון בלא התראה שיש עליו דין חיוב מיתת ב״ד אע״פ שאין ב״ד ממיתין אותו מפני שלא התרו בו דיקא נמי דקתני חייב מיתת ב״ד ולא קתני ב״ד ממיתין אותו כעין דקתני בבא דלעיל אין ב״ד ממיתין אותו:\",1,0],[8,387,20,3,\"אבל האשה וכו'. בכתובות פ' נערה מימרא דרבא (דף נ\\\"א:) ותניא כוותיה ומה שנאמר שם הוא לענין שהיא מותרת לבעלה ולמד משם רבינו לענין מיתת ב\\\"ד.\",2,0],[8,387,20,3,\"ומה שכתב מפני שיצרה נתגבר עליה ויקשה בעיניך א\\\"כ כל עוברי עבירה פטורים דהא ודאי יצרם נתגבר עליהם יש לומר שלא מטעם יצרה נתגבר עליה לחוד הוא דפטורה אלא אנו אומרים כיון שתחלתה באונס עכשיו יצרה נתגבר עליה פטורה בהאי תגבורת כיון דמכח אונס קא אתי. ודע שאפילו אנסוה להביא הערוה עליה היא פטורה וכמו שיתבאר בדברי רבינו וכתב רבינו דין זה לאשמועינן הא דאפילו היא אומרת הניחו לו וכו':\",3,0],[8,387,20,4,\"אסור לב\\\"ד לחוס על וכו':\",1,0],[8,387,20,7,\"הגס לבו בהוראה וכו'. במס' אבות פ\\\"ד:\",1,0],[8,387,20,8,\"כל דיין שבא לפניו דין וכו'. יבמות פרק ב״ש (יבמות דף ק״ט:) רעה אחר רעה תבא וכו' לתוקע עצמו לדבר הלכה ומפרש דהיינו דיינא דאתי דינא לקמיה וגמר הלכה ומדמי מילתא למילתא ואית ליה רבה ולא אזיל משאיל ופירש״י והיינו תוקע שסומך ונשען על מה שהוא יודע. וסובר רבינו דהאי רב אין פירושו רבו ממש דא״כ היאך הוא דן במקום רבו אלא הכוונה גדול ממנו בחכמה:\",1,0],[8,387,20,8,\"כי רבים חללים הפילה וכו'. סוף פ\\\"ק דע\\\"ז (דף י\\\"ט:) ופירש\\\"י הפילה לשון נפל שלא מלאו ימיו כלומר תלמיד שלא מלאו ימיו רבים חלליו ועצומים המתעצמים ומחרישים ומתאפקים מלהורות הורגין את דורם ועצומים לשון ועוצם עיניו:\",2,0],[8,387,20,8,\"וכל המונע עצמו מן הדין וכו'. במסכת אבות:\",3,0],[8,387,20,9,\"תלמיד אל יורה וכו'. ברייתא פרק קמא דסנהדרין (דף ה':) והיינו דוקא ברבו מובהק וכמו שכתב רבינו בפרק חמישי דהלכות תלמוד תורה:\",1,0],[8,387,20,10,\"אל תאמר וכו'. בפ\\\"ק דסנהדרין (דף ז':) אמרו ושפטתם צדק אפילו בין בית לעליה וכו' אפילו בין תנור לכירה. ועוד שם (דף ח') אמר ריש לקיש יהא חביב עליך דין של פרוטה כדין של מאה מנה למאי הלכתא אילימא לעיוני ביה ומפסקיה פשיטא הרי בהדיא שדין אלף מנה ודין פרוטה שוין:\",1,0],[8,387,20,11,\"אין הדיינים יושבים וכו'. במציעא פ' הזהב (בבא מציעא דף נ״ח:) א״ר קטינא אם הוזקקו בית דין לשוה פרוטה גומרין אפילו לפחות משוה פרוטה תחלת הדין בעינן פרוטה גמר דין לא בעינן פרוטה ופירש״י אם הוזקקו ב״ד בין תובע לנתבע גומרין אפי' בפחות אם חזר השני ותבעו פחות משוה פרוטה קודם שעמדו בדין משם נזקקין לו אבל מלשון רבינו שכתב גומרין דינו נראה דדוקא אם התובע הא' חזר ותבע גומרין דכיון שהם יושבים הוה ליה כאילו תבע פחות משוה פרוטה זה עם שוה פרוטה שתבע בראשונה אבל אם הנתבע הוא שתבע פחות משוה פרוטה הוה ליה כאיניש דעלמא ואין נזקקין לו. ומיהו אפשר שגם (כשהתובע) [כשהנתבע] תובעו פחות מפרוטה בכלל גומרין דינו הוא שהרי אם יזכה בדין צריכים הם לנכות לו ממה שחייבוהו לפרוע תחלה:\",1,0],[8,387,20,12,\"וכל המטה משפט וכו':\",1,0],[8,387,21,1,\"מ״ע לשפוט השופט בצדק וכו' ולא יסביר פנים לאחד וכו'. ברייתא פרק שבועת העדות (שבועות דף ל'):\",1,0],[8,387,21,2,\"שני בעלי דינים שהיה אחד מהם מלובש בגדים יקרים וכו'. גם זה שם ברייתא (דף ל\\\"א):\",1,0],[8,387,21,3,\"לא יהיה אחד יושב ואחד עומד וכו' עד ועמדו שני האנשים. בפרק הנזכר (דף ל') תניא ועמדו שני האנשים מצוה לבעלי דינין שיעמדו אמר ר' יהודה שמעתי שאם רצו ב\\\"ד להושיב את שניהם מושיבים אינו אסור אלא שלא יהא אחד עומד ואחד יושב אחד מדבר כל צרכו ואחד אומר לו קצר דבריך תנו רבנן בצדק תשפוט עמיתך שלא יהא אחד יושב ואחד עומד וכו' ואמר עולא מחלוקת פירוש דר' יהודה וחכמים בבעלי דינין אבל בעדים ד\\\"ה בעמידה שנאמר ועמדו שני האנשים אמר רב הונא מחלוקת בשעת משא ומתן אבל בשעת גמר דין ד\\\"ה דיינים בישיבה ובעלי דינין בעמידה שנאמר וישב משה לשפוט את העם ויעמוד העם וגו' דהא עדים כגמר דין דמו וכתיב בהו ועמדו שני האנשים דביתהו דרב הונא הוה לה דינא קמיה דרב נחמן אמר היכי אעביד אי איקום מקמה מסתתמן טענתיה דבעל דינה לא איקום מקמה אשת חבר הרי היא כחבר אמר ליה לשמעיה אפרח עלי בר אווזא ושדי עלאי כלומר ואעמוד ולא יבין זה שבשבילה עמדתי אלא מפני האווז הפורח ובא עלי והא אמר מר מחלוקת בשעת משא ומתן אבל בשעת גמר דין ד\\\"ה דיינין בישיבה ובעלי דינין בעמידה דיתיב כמאן דשארי מסאניה ע\\\"כ בגמרא ודעת רבינו לפסוק כר\\\"י וכתב הר\\\"ן ז\\\"ל דטעמא משום דאע\\\"ג דרבים פליגי עליה הא אידך ברייתא דבצדק תשפוט שלא יהא אחד עומד וכו' קתני לדר\\\"י בסתמא ועובדא דדביתהו דר\\\"ה כר\\\"י אתיא דאמר אפרח בר אווזא כלומר ואקום מפניה ואושיבנה ואשב כל זמן שמיישבין טענותיהם ומדפרכינן משעת גמר דין משמע דלא קשיא לן אלא בשעת גמר דין היכי עביד ומפרקינן דההיא שעתא זוטרתי היא ומצי יתיב כמאן דשארי מסאניה דאילו לרבנן כיון דס\\\"ל דבעלי דינין בעמידה ממילא דיינינן בישיבה דהכי רהטא כולה סוגיין דכל היכא דבעלי דינין בעמידה דיינים בישיבה וא\\\"כ רב נחמן היכי לעביד הא אינו רשאי לא להושיבה ולא לעמוד הוא ובכולי דינא אי אפשר דליתיב כמאן דשארי מסאניה אלא ודאי כר' יהודה אזלא וכוותיה נקיטינן ובקצת נוסחאות כתוב בגמרא בפירוש דבשעת גמר דין הוא שכך כתוב בהן דיתיב כמאן דשארי מסאניה ואמר איש פלוני אתה זכאי איש פלוני אתה חייב ועוד דעולא דאמר מחלוקת בבעלי דינין ור\\\"ה דאמר מחלוקת בשעת משא ומתן כר' יהודה שייכי וי\\\"א דעדים בעמידה דאמרינן דוקא בעמידה כלומר ואפי' העידו בדיעבד בישיבה אין עדותן עדות ויש חולקין עליהם וזה דעת רבינו שכתב בסוף דבריו שאחר הגמרא נהגו להושיב העדים ובשלמא אי בדיעבד כשרים מפני המחלוקת הושיבם כיון דעדותם עדות אבל אי אפי' בדיעבד פסולים וכי לסלק המחלוקת הכשירו עדות הפסולים וקבעוהו מנהג א\\\"ו כדאמרן וכן כתוב בירושלמי וכיון שעדים בישיבה דיעבד כשרים ה\\\"ה לבעלי דינין יושבים בשעת גמר דין דכשרים דהא קבלת עדות כשעת גמר דין דמיא וכן דיינים שקבלו עדות או גמרו דינם כשהם עומדים דיניהם דין דכיון דמכשרינן עדים ובעלי דינין בישיבה ממילא משמע דדיינים בעמידה כשרים דכיון דאמרינן דבשעת גמר דין ד\\\"ה דיינין בישיבה ובעלי דין בעמידה הוכחנו דבעלי דין בעמידה היינו לכתחלה אבל בדיעבד בישיבה כשרים ממילא דיינים בישיבה דאמרינן היינו לכתחלה אבל בדיעבד בעמידה כשרים בשעת גמר דין וקבלת עדות כגמר דין דמיא.\",1,0],[8,387,21,3,\"ומ\\\"ש רבינו ולא ישב אחד למעלה ואחד למטה וכו':\",2,0],[8,387,21,4,\"תלמיד חכם ועם הארץ שבאו לדין וכו'. מימרא שם:\",1,0],[8,387,21,4,\"ולא יקדים התלמיד וכו'. שם אמר רבה בר רב הונא האי צורבא מרבנן וע\\\"ה דאית להו דינא בהדי הדדי לא נקדים צורבא מרבנן וליתיב משום דמיחזי כמאן דסדר ליה לדיניה ולא אמרן אלא דלא קביע ליה עידניה אבל קביע ליה עידניה לית לן בה מימר אמר בעידניה טריד ופירש\\\"י לא ליקדים ליתיב לפני הדיין קודם שיבא בעל דינו ואפילו יושב ושותק דמיחזי כמאן דמסדר לטענתיה וגורם שיחשדוהו כמטעים דבריו לדיין ועובר בלא תשא שמע שוא קבע ליה עידניה שהדיין רבו ויש לו קביעות ללמוד עכ\\\"ל. ודע שנסחת רבינו האמיתית היא ואם היה קבוע לו זמן לקרות ובא בזמנו מותר וממ\\\"ש\",2,0],[8,387,21,4,\"רבינו לא יקדים התלמיד וישב לפני רבו משמע שהוא ז\\\"ל מפרש דלפני רבו הוא דלא יקדים משום דכיון דיש לו קירוב דעת עמו אתי עם הארץ לומר שהוא מסדר טענותיו לפניו אבל לפני דיין אחר שאינו רבו לא אתי למימר הכי:\",3,0],[8,387,21,6,\"היו לפני הדיינים בעלי דין הרבה וכו'. מה\",1,0],[8,387,21,6,\"שכתב שדין ת״ח קודם לדין ע״ה הוא בפרק שבועת העדות (שבועות דף ל') שלח רב יוסף לרב נחמן עולא חבירנו עמית בתורה ובמצות ואמרו דשלח ליה הכי למישרא ליה בתיגרא ופירש״י לפסוק דינו קודם של ע״ה.\",2,0],[8,387,21,6,\"ומ\\\"ש שדין היתום קודם לדין האלמנה ודין האלמנה לדין ת\\\"ח וא\\\"כ מכ\\\"ש שדין היתום קודם לדין ת\\\"ח ק\\\"ל מדאמרינן בשני דייני גזילות (דף ק\\\"ה:) דרב ענן שדריה לקמיה דר\\\"נ ושלח ליה נדייניה מר להאי גברא דאנא ענן פסילנא ליה לדינא אמר מדשלח לי הכי ש\\\"מ קריביה הוא הוה קאים דינא דיתמי קמיה וכו' סלקיה לדינא דיתמי ואחתיה לדיניה וצ\\\"ע.\",3,0],[8,387,21,6,\"ומה שכתב ודין האשה קודם לדין האיש הוא מימרא דרבא בפרק נושאין על האנוסה (דף ק\\\"ז):\",4,0],[8,387,21,7,\"אסור לדיין לשמוע דברי אחד מבעלי דינין וכו'. בפ״ק דסנהדרין (דף ז':) שמוע בין אחיכם ושפטתם אמר ר' חנינא אזהרה לב״ד שלא ישמע דברי בעל דין קודם שיבא בעל דין חבירו ואזהרה לבעל הדין שלא יטעים דבריו לדיין קודם שיבא בעל דין חבירו קרי ביה נמי שמע בין אחיכם ובפרק שבועת העדות (שבועות דף ל״א) תניא מנין לדיין שלא ישמע וכו' ת״ל מדבר שקר תרחק ומנין לבעל דין שלא יטעים דבריו וכו' ת״ל מדבר שקר תרחק רב כהנא מתני מלא תשא ולא תשיא. פירש״י לא תשא אזהרה למקבל קרי ביה לא תשיא אזהרה לבעל דין. שמע שוא שהמטעים דבריו שלא בפני בעל דינו אינו בוש מדבר שקר. וקשה שנראה מפשט לשון רבינו שאיסור הדיין נפיק מלא תשא אבל לא איסור הבעל דין דאי לא ליערבינהו וליתנינהו. ונראה לי שרבינו רצה להביא שתי הדרשות דרשת מדבר שקר תרחק ודרשת לא תשא והקדים לא תשא להיותה יותר מפורשת לדרשה בדיין ולא בבעל דין משום דנפיק מלא תשיא וההיא אסמכתא היא ולהכי לא ערבינהו אלא כתב וכן בעל דין מוזהר וכו' וכן בעל דין נפיק מהאי קרא וכתב וגם על זה כלומר בין על אזהרת הדיין בין על אזהרת הבעל דין נאמר מדבר שקר\",1,0],[8,387,21,7,\"תרחק ומה שכתב או שלא בפני חבירו כלומר שאפילו בא חבירו ואחר כך יצא אסור להשמיע דבריו שלא בפניו:\",2,0],[8,387,21,8,\"לא יהיה הדיין שומע מפי התורגמן וכו'. ומשנה ספ\\\"ק דמכות (דף ו':) שלא תהא סנהדרין שומעת מפי התורגמן ואמרינן בגמ' הנהו לעוזי דאתו לקמיה דרבא אוקי רבא תורגמן בינייהו והיכי עביד הכי והתנן שלא תהא סנהדרין שומעין מפי התורגמן רבא מידע הוי ידע מאי דהוו אמרי אהדורי הוא דלא הוה ידע ואע\\\"פ שיש מי שפירש שהנהו לעוזאי היו עדים דעת רבינו לפרש שהיו בעלי דינין כפשט לישנא דאתו לקמיה דרבא:\",1,0],[8,387,21,9,\"צריך הדיין לשמוע וכו' ולשנות טענותיהם וכו'. בסנהדרין פרק זה בורר ירושלמי כלשון רבינו:\",1,0],[8,387,21,9,\"ומצדק את הדין בלבו וכו'. בפרק קמא דסנהדרין (דף ז':) ושפטתם צדק אמר ר\\\"ל צדק את הדין ואח\\\"כ חתכהו:\",2,0],[8,387,21,10,\"מנין לדיין שלא יעשה מליץ וכו'. פרק שבועת העדות (שבועות דף ל':) מנין לדיין שלא יעשה סניגרון לדבריו ת״ל מדבר שקר תרחק וסניגרון פירוש מליץ מלשון סניגור ומפרש רבינו שהכוונה שלא יעשה הדיין מליץ לדבריו של בעל דין כלומר שלא יהיה לו סניגור לו בטענותיו לומר יפה הוא אומר ורש״י פירש בענין אחר:\",1,0],[8,387,21,10,\"ולא ילמד אחד מבעלי דינין וכו'. ירושלמי פרק זה בורר רב הונא מיקל לדיינא דאמר מקבלין אתון חד סהיד אלא יימרון אינון את לא תימא. ועוד דאמרינן בסוף כל הנשבעין (דף מ\\\"א) אמר רב הונא לכל אין מגלגלין חוץ משכיר רב חסדא אמר לכל אין מקילין וכו' מאי בינייהו איכא בינייהו לפתוח לו ומפרש רבינו דהשואל מאי בינייהו לא הבין כוונת רב חסדא ונראה לו דהיינו דברי רב הונא והשיב לו דאיכא בינייהו לפתוח לו דלרב הונא מגלגלין והוסיף רב חסדא ואמר דאף ע\\\"ג דלכל אין פותחין לומר השבע וטול בשכיר פותחין ומר אמר חדא ומר אמר חדא ולא פליגי וכן כתב רבינו ס\\\"פ י\\\"א מהלכות שכירות ולכל הנשבעין אין מקילין חוץ מן השכיר שמקילין עליו ופותחין לו תחלה ואומרים לו אל תצער עצמך השבע וטול הרי מבואר בדבריו כמו שפירשתי ולאחר שהוא מפרש כן למדנו מכאן דלשאר דינין אין פותחין וכמ\\\"ש כאן רבינו:\",2,0],[8,387,21,11,\"ראה הדיין זכות לאחד מהם. ג\\\"ז שם רב הונא כד הוה חזי זכו לבר נש בדינא ולא הוה ידע ליה הוה פתח ליה על שום פתח פיך לאלם ובגמ' דידן בכמה דוכתי אמרינן כגון האי פתח פיך לאלם הוא ומפרש רבינו דהיינו דוקא כשהבעל דין מבקש לומר אלא שאינו יודע לחבר הדברים וכו' הא לאו הכי לא משום דנראה כעורכי הדיינין:\",1,0],[8,387,22,1,\"שנים שבאו לפניך לדין וכו'. פירקא קמא דסנהדרין (דף ז') תניא רבי שמעון בן לקיש אומר שנים שבאו לפניך אחד רך ואחד חזק וכו' אבל משתשמע דבריהם וכו' שנאמר לא תגורו מפני איש ואמר רב חנן אל תכניס דבריך מפני איש ומפרש התם דדריש ליה מלשון אסיפה כמו ולא תאגור:\",1,0],[8,387,22,1,\"ואם היה ממונה לרבים וכו':\",2,0],[8,387,22,2,\"וכן תלמיד וכו'. ג\\\"ז שם ודריש לה מלא תגורו ובפרק שבועת העדות דריש להא מדבר שקר ורבינו תפס שתיהן:\",1,0],[8,387,22,3,\"ומנין לדיין שלא יושיב תלמיד בור לפניו וכו' ומנין לתלמיד וכו'. פ' שבועת העדות (שבועות דף ל״א:) ברייתא כלשון רבינו:\",1,0],[8,387,22,4,\"מצוה לומר לבעלי דינין וכו' במה דברים אמורים וכו'. פירקא קמא דסנהדרין (דף ו' ע\\\"ב) רבי יהושע בן קרחה אומר מצוה לבצוע ודריש לה ממשפט שלום ומקרא דדוד ואמרינן מאי מצוה מצוה למימר להו הכי דינא בעיתו או פשרה בעיתו ואמרינן התם ודוקא מקמי גמר דין אבל לאחר גמר דין אי אתה רשאי לבצוע ואמרינן היכי דמי גמר דין אמר רב יהודה אמר רב (מכי אמר) איש פלוני אתה חייב איש פלוני אתה זכאי:\",1,0],[8,387,22,5,\"אף על פי שרצו בעלי הדין בפשרה וכו'. שם מסקנא דגמרא והלכתא בפשרה צריכה קנין:\",1,0],[8,387,22,6,\"יפה כח הפשרה וכו'. ריש סנהדרין (דף ה':) תניא רבן שמעון בן גמליאל אומר הדין בשלשה פשרה בשנים יפה כח הפשרה וכו'. וכתבו המפרשים דלאו דוקא שנים דהוא הדין אחד דכיון דקיימא לן דבעי קנין ביחיד נמי מהניא. ואיכא למידק מה יפוי כח יש בפשרה מבדין דכיון דפשרה מיירי בשקנו מידן הלא דין ג\\\"כ אם קנו מידם שידון להם אחד אפילו קרוב או פסול אינם יכולים לחזור בהם כמבואר בפרק שביעי. ויש לומר דכיון דסתם דין לא בעי קנין וכל פשרה בעיא קנין שפיר מצי למימר יפה כח פשרה העשויה כמשפטה דהיינו בקנין מכח הדין העשוי כמשפטו דהיינו בלא קנין. ומיהו איכא למידק דהא דתניא תו התם (דף ז') ביצוע בשלשה דברי ר\\\"מ וחכמים אומרים פשרה ביחיד אמרינן לימא תלתא תנאי בפשרה דמ\\\"ס בשלשה ומ\\\"ס בשנים ומ\\\"ס ביחיד אמר רב אחא בר איקא וכו' מאן דאמר תרי אפילו חד נמי והא דקאמר תרי כי היכי דליהוו עליה סהדי וכיון דגמ' מסיק דלרשב\\\"ג נמי פשרה ביחיד ס\\\"ל למה פסק רבינו דבפשרה שנים. ויש לומר דסבר רבינו דלא איתמר הכי אלא למדחי דלא נימא דתלתא תנאי בפשרה אבל פשטא דמילתא דרשב\\\"ג דפשרה בשנים דוקא היא ולא ביחיד וכן נראה מדברי הרי\\\"ף שכתב דברי רשב\\\"ג סתם. אלא דאכתי איכא למידק אמאי פסק כרשב\\\"ג דאמר בשנים כחכמים דאמרי ביחיד הוה ליה למיפסק וצ\\\"ע:\",1,0],[8,387,22,7,\"אסור לאחד מהדיינים וכו'. בסנהדרין פרק זה בורר (סנהדרין דף כ״ט) משנה ומנין שכשיצא אחד מן הדיינים לא יאמר אני הוא המזכה וכו':\",1,0],[8,387,22,7,\"ומעשה בתלמיד אחד. שם (דף ל\\\"א) מעשה ההוא תלמידא דאפיק מילתא מבי רב אמי בתר כ\\\"ב שנין ואפקיה רב אמי ואכריז עליה דין גלי רזיא:\",2,0],[8,387,22,8,\"שאל אחד מבעלי דינין וכו'. שם (דף ל') מיכתב היכי כתבינן ר' יוחנן אמר זכאי רשב\\\"ל אמר פלוני ופלוני מזכין (פלוני) ופלוני מחייב ר' אלעזר אמר מדבריהם נזדכה פלוני ופירש\\\"י היכי כתבינן פסק דין במקום שיש מחלוקת ונטו אחרי רבים זכאי סתמא משום שאם היו אומרים פלוני מחייב היה רכילות ורשב\\\"ל חייש למיחזי כשיקרא אי אמר סתמא זכאי דהוה משמע דכולהו זיכו הדין כאחד ורבי אלעזר אומר כדי להעמיד דברי שניהם כותבים מדבריהם נזדכה דמשמע דיש מחלוקת ביניהם ומתוך דבריהם נזדכה והשתא ליכא משום מיחזי כשיקרא ולא משום הולך רכיל וכתב הרא\\\"ש והלכתא כר\\\"א דאית ליה דתרווייהו ומסתבר טעמיה:\",1,0],[8,387,22,9,\"כך היה מנהגם של אנשי ירושלים וכו'. שם תניא ר' נחמיה אומר כך היה מנהגם של נקיי הדעת שבירושלים וכו':\",1,0],[8,387,22,10,\"דיין שהוא יודע בחבירו וכו'. ברייתא פרק שבועת העדות (שבועות דף ל':) מניין לדיין שיודע בחבירו שהוא גזלן וכו' שלא יצטרף עמו תלמוד לומר מדבר שקר תרחק:\",1,0],[8,387,22,10,\"וכך היו נקיי הדעת וכו'. ברייתא ריש פרק זה בורר (סנהדרין דף כ״ג) כלשון רבינו:\",2,0],[8,387,23,1,\"לא תקח שוחד אין צריך לומר לעות את הדין וכו'. פרק שני דייני גזילות (דף ק\\\"ה) ושוחד לא תקח מה תלמוד לומר אם ללמד שלא לזכות את החייב ושלא לחייב את הזכאי הרי נאמר לא תטה משפט אלא אפי' לזכות את הזכאי ולחייב את החייב אמרה תורה ושוחד לא תקח:\",1,0],[8,387,23,3,\"כל דיין וכו'. שבת פרק במה בהמה יוצאה (שבת דף נ״ו) מה אני מקיים ויטו אחרי הבצע שלא עשו כמעשי אביהם שהיה שמואל הצדיק מחזר בכל מקומות ישראל ודן אותם בעריהם והם לא עשו כן אלא ישבו בעריהם כדי להרבות שכר לסופריהם ולחזניהם כלומר לשלוחים המזמינין לדין:\",1,0],[8,387,23,3,\"ולא שוחד ממון בלבד וכו'. פרק שני דייני גזילות (דף ק\\\"ה) ודייק לה מדלא כתיב בצע לא תקח וקאמר היכי דמי שוחד דברים כי הא דשמואל הוה קא עבר במעברא וכו' ומייתי התם כל הני עובדי דמייתי הכא רבינו וסבירא ליה לרבינו דכל הני עובדי דהוו מימנעי מדינא לאו מדת חסידות בלחוד הואי אלא כך היא שורת הדין דכל כי הני פסילי לדינא ושלא כדעת התוספות שכתבו דחסידות בעלמא הוה:\",2,0],[8,387,23,4,\"כל דיין וכו'. שם מימרא דרבה בר רב שילא:\",1,0],[8,387,23,5,\"כל דיין שנוטל וכו'. משנה בבכורות פ\\\"ד (דף כ\\\"ד) וכתב הר\\\"ן בסוף האיש מקדש דמדתנן דיניו בטלים ולא תנן דינו בטל משמע דלאו אותו הדין שידוע שנטל בו שכר הוא בלבד שבטל אלא כל דיניו שדן פסולים אלא א\\\"כ ידוע שלא נטל בהם שכר:\",1,0],[8,387,23,5,\"אבל אם וכו'. פ' שני דייני גזירות (כתובות דף ק״ה) עובדא דקרנא הוה שקיל איסתרא מזכאי ואיסתרא מחייב ודאין להו דינא והיכי עביד הכי והא כתיב ושוחד לא תקח וכ״ת ה״מ היכא דלא שקיל מתרווייהו דילמא אתי לאצלויי דינא קרנא כיון דשקיל מתרווייהו לא אתי לאצלויי דינא וכו' והא תניא ושחד לא תקח וכו' אפילו לזכות את הזכאי ולחייב את החייב ומשני ה״מ דשקיל בתורת שוחד קרנא בתורת אגרא הוה שקיל ובתורת אגרא מי שרי והתנן הנוטל שכר לדון דיניו בטלים ה״מ אגר דינא קרנא אגר בטלה הוה שקיל והדר פריך ואגר בטלה מי שרי ומסיק קרנא בטלה דמוכח הוה שקיל דהוה תהי באמברא דחמרא ויהבי ליה זוזא משמע דאפי' שכר בטלה דמוכח כל שנוטל מזה יותר מזה א״נ שקיל בשוה אי הוו בתורת שוחד או בתורת שכר בטלה דלא מוכח אסור ולא שרי אלא דשקיל מתרווייהו בשוה שכר בטלה דמוכח ונתבררו דברי רבינו.\",2,0],[8,387,23,5,\"ומה שכתב זה בפני זה נראה דדייק ליה מדאמרינן התם רב הונא הוה אמר להו הבו לי גברא דדלי בחריקאי פירוש במקומי משמע שעם שניהם היה מדבר ועוד שאם נוטל זה שלא בפני זה יחשוב חבירו שנתן לו יותר או הנותן עצמו יחשוב שלא נטל רק ממנו ויחשדהו שנוטל שוחד:\",3,0],[8,387,23,6,\"אסור לדיין וכו'. שם (דף ק\\\"ה:) אמר רב פפא לא לידון איניש לא למאן דרחים ליה ולא למאן דסני ליה וסובר רבינו דהכא לא עסקינן באוהבו דהיינו שושבינו ובשונאו שלא דבר עמו שלשה ימים באיבה אלא אפילו באוהב כדרך האוהבים ושונא כדרך השונאים ואפילו הכי קאמר דלא לידון ליה. ואם תאמר בפרק זה בורר גבי הא דתנן דלרבי יהודה האוהב והשונא פסולים לעדות אי זהו האוהב זה שושבינו והשונא כל שלא דבר עמו שלשה ימים באיבה ואמרינן התם דפליגי רבנן עליה לענין עדות שהם כשרים אבל לדין פסולים משמע דלא פסלי רבנן לדין אלא בשושבינו ושלא דבר עמו שלשה ימים באיבה דוקא אבל לא שאר אוהבים ושונאים ואם כן מנ\\\"ל למפסלינהו. ואפשר לומר לדעת רבינו דכיון דאמרינן בפרק זה בורר שאינו יכול לדון לאוהבו ולשונאו ואשכחן רב פפא דאמר סתם לא למאן דרחים ליה ולא למאן דסני ליה בסתם ולא חילק אית לן למימר דכי פסלי רבנן לדין לאו בגוונא דרבי יהודה בלחוד הוא דפסלי אלא בכל גוונא דרחים או סני ליה מיפסיל:\",1,0],[8,387,23,7,\"כל שני תלמידי חכמים וכו'. סנהדרין פרק זה בורר (סנהדרין דף כ״ט) תניא איסי בן יהודה אומר והוא לא אויב לו ולא מבקש רעתו מכאן (אזהרה) לשני תלמידי חכמים ששונאים זה את זה שאסורין לישב בדין זה עם זה וטעם רבינו נכון הוא:\",1,0],[8,387,23,9,\"לעולם יראה דיין עצמו וכו' עד מה שעיניו רואות. הכל פרק קמא דסנהדרין (דף ז') כלשון רבינו:\",1,0],[8,387,23,10,\"לעולם יהיו וכו'. פ\\\"ק דאבות:\",1,0],[8,387,24,1,\"יש לדיין לדון וכו'. כתובות פ' הכותב (כתובות דף פ״ה) ההיא אתתא דאיחייבא שבועה בבי דינא דרבא אמרה ליה בת רב חסדא ידענא בה דחשידא אשבועתא אפכה רבא לשבועה אשכנגדה ומייתי התם על שטרא דאתא לקמיה דרבא ואמר רב פפא ידענא ביה דשטרא פריע הוא ולא הימניה ואמר ליה רב אדא בר מתנא ולא יהא רב פפא כבת רב חסדא ואמר ליה בת רב חסדא קים לי בגווה מר לא קים לי בגויה אמר רב פפא השתא דאמור רבנן קים לי בגויה מילתא היא כגון אבא מר ברי דקים לי בגויה קרענא שטרא אפומיה קרענא ס״ד אלא מרענא שטרא אפומיה ואמרינן נמי התם ההוא גברא דאפקיד שב מרגניתא דציירן בסדיניה בי רבי מיישא וכו' שכיב רבי מיישא ולא פקיד פירוש לא צוה לאנשי ביתו שחטפתו מיתה אתו לקמיה דרבי אמי אמר ליה חדא ידענא ברבי מיישא דלא אמיד ועוד הא יהיב סימנא ולא אמרן אלא באיניש דלא רגיל דעייל ונפיק אבל רגיל דעייל ונפיק להתם לא אימור איניש אחרינא אפקיד ומיחזא חזא ורב נחמן ור' אבא דנו נמי כי האי דינא דרבי אמי וסובר רבינו שועוד זה לאו דוקא אלא תרתי בעינן דלא אמיד וסימן דאי אמיד מה מועיל הסימן דילמא זבנה מיניה אי נמי הכי קאמר חדא דלא אמיד וליכא למיחש דילמא דרבי מיישא נינהו ועוד לדילמא דאיניש אחרינא הוי נמי ליכא למיחש דהא קא יהיב סימנא וא״כ תרווייהו בעינן ואע״ג דטענינן ליתמי כל מאי דמצי טעין אבוהון ואילו הוה רבי מיישא קיים והוא טעין שלי הוא הוה מהימן אע״ג דלא אמיד דאימור מציאה אשכח או מתנה נתנו לו מ״מ לא טענינן ליתמי דמילתא דלא שכיח היא כי היכי דלא טענינן להו נאנסו כדאמרינן בסוף פ' המוכר את הבית. וכתב הרי״ף בפ' הכותב בשם גאון דהאידנא לא אפשר ליה לדיין למימר קים לי בגויה דלא בריר לן קים לי בגויה היכי הוא הילכך לית לן לאורועי שטרא או לאפוכי שבועה אלא בעדות ברורה ואע״פ כן בעדות אדם נאמן מחמיצין את הדין ודורשין וחוקרין עד שיתברר הדבר ויצא הדין לאמיתו עכ״ל:\",1,0],[8,387,24,1,\"וכתב הראב\\\"ד וכן אם יצא שטר חוב לפניו עד לא תפרע אלא בשבועה א\\\"א דבר זה הוציא וכו'. ומ\\\"ש דוק ותשכח פרק אע\\\"פ ובשבועות פרק הדיינים דכל ריע שטרא וכו' חתרתי בפרק אע\\\"פ ולא מצאתי אמנם מה שהביא מפרק שבועת הדיינים גם שם אין רבינו חננאל מודה לו כי הוא מפרש כל ריע שטרא שבגמ' דהיינו שצריך שישבע בעל השטר קודם שיגבה וכתבו התוס' בפרק הכותב שהלשון משמע מדלא מסיק לא מקרע קרעינן ולא מגבא גבינן ביה כדאמרינן באלו נערות. אבל אי קשיא על רבינו הא קשיא שמאחר שהוא מפרש ריע שטרא דהכא כר\\\"ח למה ריע שטרא דשבועת הדיינים מפרש שהשטר בטל לגמרי וישבע הלוה היסת ויפטר כמבואר בדבריו פרק י\\\"ד מהלכות מלוה. וי\\\"ל שנמשך בשני המקומות אחר הרי\\\"ף וטעמם משום דסבירא להו דריע דאלו נערות דאיכא תרי סהדי דמהדר בתר זיופא לא ידעינן אי האי שטרא מזוייף הוא לא מיקרע קרעינן ליה דליכא סהדי דהאי שטרא מזוייף הוא ולא מיגבא גבינן ביה דהא איכא תרי סהדי דמהדר אזיופא וריע דשבועת הדיינים כיון דמודה דקבל המעות הא מודה דשטרא פריעא הוא ואיבטיל לגמרי והכא לית לן למימר דבעד אחד לא ליגבי בהאי שטרא אלא היינו דאפילו אית ביה נאמנות לא ליגבי בלא שבועה. ודע שעיקר החידוש לדעת רבינו הוא שהאשה וקרוב שדעתו סומכת עליהם מחייב ליה שבועה כאילו היה עד אחד כשר דאילו כשעד כשר מעיד כן אפי' אין דעתו סומכת עליו לא יפרע אלא בשבועה ומאי רבותיה דדעתו סומכת עליו ולפי זה הא דלא הימניה רבא לרב פפא צריך לומר שרב פפא היה קרוב לתובע או לנתבע וכל שכן שרבינו אומר שכפי מה שדעתו סומכת בדברי העד יעשה אם שלא יפרע אלא בשבועה אם שיצוה לפרוע לאותו שלא נפגם או אפי' שלא יצא עליו שטר אחר לא יגבה בזה וזהו\",2,0],[8,387,24,1,\"שכתב או ישליך השטר בפניו ולא יתן לו דהיינו לא מקרע קרעינן ליה ולא מיגבא גבינן ביה הכל כפי מה שדעת הדיין סומכת על זה:\",3,0],[8,387,24,3,\"הסכימו רוב בתי דיני ישראל וכו'. כך כתב הרי\\\"ף בשם גאון. ומיהו איכא למידק דמשמע דלא אמר גאון הכי אלא בענין לאורועי שטרא או לאפוכי שטרא אבל לענין להוציא מן היתומים באומדן דעת המת או הטוען מש\\\"מ דבהא לא איירי גאון וכן משמע ממ\\\"ש הרי\\\"ף ז\\\"ל על הנהו עובדי למימרא דהלכה רווחת היא ולית בה פלוגתא ולא כתב על זה שום דבר משמע דעוד היום הוי דינא הכי ורבינו שכתב דהאידנא אין מוציאין מן היתומים אלא בראיה ברורה משמע דס\\\"ל שכיון שטעמו של גאון משום דהאידנא לא בריר לן קים לי בגויה היכי הוא דהיינו לומר שרבו בתי דינים שאינם הגונים מההוא טעמא אית לן למימר דאין מוציאין מן היתומים אלא בראיה ברורה לא בדעת הדיין ולא באומד המת או הטוען ואע\\\"פ שבפ\\\"ו מהל' שאלה פסק שמי שבא ואמר כך וכך הפקדתי אצל אביכם ונתן סימנים מובהקים ונמצא הפקדון כמו שאמר והיה יודע הדיין שלא היה המת אמוד שזה הפקדון שלו יש לו לדיין לתת הפקדון לזה שנתן סימניו והוא שלא יהא המפקיד רגיל ליכנס אצל זה שמת וכיוצא בזה כתב בפרק י\\\"א מהלכות נחלות שם כתב דין הגמ' וסמך על מ\\\"ש כאן מה שהסכימו רוב דייני ישראל:\",1,0],[8,387,24,3,\"כיצד יעשה ידרוש בו וכו'. ריש פרק אחד דיני ממונות (סנהדרין דף ל״ב:) אסיקנא דדין מרומה בעינן דרישה וחקירה:\",2,0],[8,387,24,3,\"אלא יסלק עצמו וכו'. מההיא ברייתא דפרק שבועת העדות (שבועות דף ל״א) דמדבר שקר תרחק:\",3,0],[8,387,24,3,\"ומנין לדיין שהוא יודעבדין שהוא מרומה וכו'. ברייתא פ' שבועת העדות:\",4,0],[8,387,24,4,\"יש לב״ד להלקות מי שאינו מחויב וכו'. ברייתא דר' אליעזר פ' נגמר הדין (סנהדרין דף מ״ו) ופרק האשה רבה (יבמות דף צ':) אמר ראב״י שמעתי שב״ד מכין ועונשין שלא מן הדין ולא לעבור על דברי התורה אלא לעשות סייג לתורה:\",1,0],[8,387,24,5,\"וכן יש לב\\\"ד בכל מקום וכו' להלקות אדם ששמועתו רעה וכו'. בסוף קידושין (דף פ\\\"א) אמר רב מלקין על לא טובה השמועה שנאמר אל בני כי לא טובה השמועה אשר אנכי שומע ופירש\\\"י מי שיצא עליו קול שהוא עובר עבירות מלקין אותו דלא טובה השמועה לאו הוא דכתיב בבני עלי אל בני לאו יש כאן על כי לא טובה השמועה ע\\\"כ. ומלקין אותו אלאו דקאמר אסמכתא בעלמא הוא והתם נמי מייתי דמר זוטרא הוה מותיב לה אפסירא אכתפיה ומקרי ליה אל בני ופירש\\\"י להודיע שעל לאו זה הוא לוקה.\",1,0],[8,387,24,5,\"ומ\\\"ש והוא שיהא קול שאינו פוסק וכו'. נלמד ממה שאמרו בפ' ב' דיבמות גבי טוען ונתבאר בהלכות אישות פרק כ\\\"א ובהלכות סוטה פ\\\"ב:\",2,0],[8,387,24,5,\"וכן מבזין וכו'. סוף פרק שלישי מגילה (דף כ\\\"ה) האי מאן דסני שומעניה שרי לבזוייה בג' ש' בן עכו\\\"ם בן שפחה וכתב הר\\\"ן דה\\\"מ באיניש דעלמא אבל צורבא מרבנן לא אלא כסהו כלילה וכבר כתב רבינו דיני תלמידי חכמים בהלכות תלמוד תורה:\",3,0],[8,387,24,6,\"וכן יש לדיין תמיד, פי' אפילו בזמן הזה,\",1,0],[8,387,24,6,\"להפקיר וכו'. במקומות רבים בגמרא הפקר ב״ד הפקר מהם פרק השולח (גיטין דף ל״ו:) אמתני' דהתקין הלל פרוזבול, ופ' אלו מגלחין (מועד קטן דף ט״ז) ומייתי מקרא דמייתי לה רבינו:\",2,0],[8,387,24,9,\"וכן יש לדיין וכו'. פ' אלו מגלחין שם מנ\\\"ל דמשמתינן דכתיב אורו מרוז דהכי סברא דגברא רבה פלוני דכתיב אמר מלאך ה' פירוש דהכי סברא וכו' שצריך השליח בית דין כשמשמת לומר בשליחות ב\\\"ד שיאמר לו דעת פלוני הרב לנדותך על זה שאם לא יאמר לו משמו של הרב הגדול אין להאשימו כשלא חש לדבריו לפי שסובר שאומר השליח מדעתו אבל כשמזכיר לו הבית דין ולא חש ראוי הנדוי לחול עליו וזהו שכתב\",1,0],[8,387,24,9,\"רבינו ויאמר שנדוהו או החרימו על דעתו פירוש על דעתו של גדול הב\\\"ד וכדפרישית. ועוד שם ומנא ליה דפרטינן חטאיה בצבורא וכו' ומנא ליה דנצינן ומחינן ולייטינן ותלשינן שער ומשבעינן וכפתינן ואסרינן ועבדינן לו הרדפה ומביא ראיה מהפסוקים הללו שמביא רבינו והרדפה יש בו פירושים ודעת רבינו שהוא לדחוף ולסחוב על הארץ:\",2,0],[8,387,24,10,\"כל אלו הדברים וכו'. דברי רבינו ראויים אליו והרי אמרו גדול כבוד הבריות שדוחה ל\\\"ת דהיינו לאו דלא תסור וא\\\"כ לא הותר בזויים רק לכבוד המקום:\",1,0],[8,387,25,1,\"וכל פרנס וכו'. פ\\\"ק דראש השנה (דף י\\\"ז):\",1,0],[8,387,25,2,\"ולא יפסיע וכו'. פרק קמא דסנהדרין (דף ז':) ומפיק לה מלא תעלה במעלות וסמיך אלה המשפטים כלומר אף לשופטים אני מזהיר ופירוש לא יפסיע שכשהיה המתורגמן דורש היו הצבור יושבים לארץ המפסיע ביניהם לילך ולישב במקומו נראה כמפסיע על ראשן:\",1,0],[8,387,25,2,\"והרי הוא אומר ואצוה את שופטיכם וכו'. פ' קמא דסנהדרין (דף ז:) צא ולמד וכו':\",2,0],[8,387,25,3,\"כדרך שנצטוה וכו'. פ\\\"ק דסנהדרין:\",1,0],[8,387,25,4,\"כיון שנתמנה אדם פרנס וכו'. בקידושין פרק עשרה יוחסין (קידושין דף ע') גבי עובדא דר' יהודה בר יחזקאל:\",1,0],[8,387,25,5,\"אסור לנהוג קלות ראש בשליח וכו' והרי השליח נאמן כשנים וכו'. פרק הגוזל בתרא (בבא קמא דף קי״ב:) אמר רבא שליחא דבי דינא מהימן כבי תרי וה״מ לשמתא אבל לפתיחא לא מ״ט ממונא הוא דמחסר ליה דבעי מיתב ליה זוזי לספרא פירש״י פתיחא שטר שמתא וכי שרו ליה שמתא לא שרו ליה עד דיהיב זוזא דפתיחא לספרא. ויש לתמוה דכיון דאומר פלוני הקלני משמתין אותו על פיו מאי רבותיה דרב דמנגיד מאן דמצער שליחא דבי דינא הא שמתא דחמירא מנגודא מחייב. ושמא י״ל שמלבד השמתא הוה מנגיד ליה ואפשר לדייק כן מלשון רבינו שאחר שכתב שאם אמר פלוני הקלני או הקלה הדיין וכו' משמתין אותו על פיו כתב וכל המצער שליח ב״ד מכין אותו מכת מרדות משמע דה״ק אם אמר פלוני הקלני וכו' דינו שמשמתין אותו ואם רצו ב״ד להחמיר עליו ולזכות אותו מלבד השמתא הרשות בידו ועי״ל שפלוני הקלני לא נקט ליה בהדי הנך לענין השמתא אלא לענין שהוא נאמן כשנים:\",1,0],[8,387,25,6,\"ואין שליח ב״ד חייב וכו'. פרק אלו מגלחין (מועד קטן דף ט״ז) ומנא ליה דאי מתפקר בשליח ב״ד ואתי ואמר לא מתחזי כלישנא בישא דכתיב העיני האנשים ההם תנקר ופירש״י ואי לאו דשליחא אמר למשה משה לא הוה ידע:\",1,0],[8,387,25,6,\"וכל המצער וכו'. פ\\\"ק דקידושין (דף י\\\"ב:) רב מנגיד אמאן דמקדש בשוקא וכו' ואמאן דמצער שלוחא דרבנן ופי' רש\\\"י שליח דרבנן שמזמינו לדין מפי הדיינים וקם עליו והכהו וכתב הר\\\"ן ז\\\"ל ולשון מצער לא משמע כולי האי אלא אפי' מבזה אותו בפני אחרים ומביישו:\",2,0],[8,387,25,7,\"שליח שאמר פלוני שלחני וכו'. מימרא דרבא פירקא קמא דסנהדרין (דף י\\\"ח):\",1,0],[8,387,25,8,\"מי ששלחו לו ב״ד וכו'. פ' הגוזל בתרא (בבא קמא דף קי״ג) אמר רבא האי מאן דכתבו עליה פתיחא על דלא אתי לדינא עד דאתא לדינא לא מקרעינן ליה פירש״י ואע״ג דאמר אתינא אתינא, על דלא ציית דינא כיון דאמר צייתנא קרעינן ליה.\",1,0],[8,387,25,8,\"ומה שכתב ונותן שכר הסופר נלמד מדין השליח הנזכר למעלה דאמרי' אבל לפתיחא לא מאי טעמא ממונא הוא דמחסר ליה דבעי למיתב זוזא לספרא:\",2,0],[8,387,25,8,\"קבעו לו ב\\\"ד זמן וכו'. שם אמר רב חסדא קובעין זמן שני וחמישי ושני וכו' ולמחר כתבינן פירש\\\"י קובעין זמן ליום שני בשבת ואם לא יבא מזמנין אותו ליום ה' ואם לא יבא מזמנין אותו ליום שני ועד למחר לא כתבינן פתיחא שכל היום ממתינין שמא יבא ואמרינן התם דרב אסי חזא דרב כהנא אזמין ההיא אתתא בפניא ובצפרא כתיב עלה פתיחא ואמר ליה לא סבר לה מר להא דאמר רב חסדא קובעין שני וחמישי ושני ואמר ליה הני מילי גברא דאניס וליתיה במתא אבל הכא כיון דאיתה במתא ולא אתיא מורדת היא. ולא ידעתי מה תמהו הגהות על רבינו שלא כתב דין האשה שהרי אי איתה במתא אפי' אגברא נמי כתבינן ואי ליתה במתא אפילו אאתתא לא כתבינן אלא דאורחא דמילתא דאתתא איתה במתא אבל בכלל דברי רבינו דבריהם ואפשר דמשום הכי סיים ואמר אבל הכא דאיתה במתא וכו' ולא אמר אבל איתתא כיון דאיתה במתא:\",3,0],[8,387,25,9,\"אין קובעין זמן לא בימי ניסן וכו' עד מפני שהכל טרודין בע\\\"ש. גם זה שם מימרא דרב יהודה כלשון רבינו:\",1,0],[8,387,25,10,\"מי שהוא במדינה וכו'. שם (דף קי\\\"ב קי\\\"ג) אמר רבינא יהבינן זמנא פירוש מזמנין בעל דין ליום פלוני לדין אפומא דאתתא ואפומא דשבבי ולא אמרן אלא דליתיה במתא אבל איתיה במתא לא וכו' דאמרי כלומר אתתא ושבבי אשכחיה כלומר שליחא דב\\\"ד ואמר ליה ולא עבדי שליחותייהו ולא אמרן אלא דלא חליף אבבא דבי דינא אבל חליף אבבא דבי דינא אמרי אשכחוה בי דינא ואמרי ליה ולא אמרן אלא דאתי ביומיה אבל לא אתי ביומיה לא אימא אשתלויי אשתלי פירוש שכחו ולא אמרו לו:\",1,0],[8,387,25,11,\"מי שבא לבית דין וכו'. בפ' אלו מגלחין (מועד קטן דף ט״ז) מנדין לאלתר ושונין לאחר שלשים ומחרימין לאחר ששים וכו' אמר רב חסדא מתרין ביה ב' וה' וה״מ לממונא אבל לאפקירותא מנדין לאלתר ואפשר שרבינו לא היה גורס אלא מנדין לאלתר ומחרימין לאחר שלשים יום ואם נפשך לומר שהיה גורס כגירסת ספרינו יש לומר שהוא מפרש דלרב חסדא כיון דמתרין ביה ברישא ואחר כך מנדין אותו כי משהי תלתין יומין מחרימין אותו תלתין יומין בהתראת שני וחמישי ושני במקום משהי עצמו בנידוי שלשים יום פעם ראשונה קאי ומחרימין אותו. ומדאמרינן הני מילי בממונא אבל לאפקירותא לאלתר כתב רבינו מי שבא לב״ד וקבל הדין כלומר זה דוקא הוא דמתרינן ביה אבל אי אמר לא צייתנא לדינא היינו אפקירותא ומנדין אותו לאלתר ויש הוכחה לזה בפרק הגוזל בתרא והנה רבינו כתב פ' ו' מהל' ת״ת לגבי אפקירותא דמנדין לאלתר ושונין לאחר שלשים ומחרימין אחר ששים ונראה לי דהיינו טעמא דאין מחרימין אלא אחר נידוי שקדם לו התראה ולפיכך באפקירותא דמנדין לאלתר הוה ליה נידויי הראשונים כהתראה ולפיכך אין מחרימין עד אחר ששים אבל נידוי על ממון דבעינן שיקדים לו התראה מחרימין לאחר שלשים פרק קמא דקידושין רב מנגיד אמאן דחלא עליה שמתא דרבנן שלשים יום:\",1,0],[8,387,25,11,\"אסור לקלל דיין וכו'. עיין בביאורי לחו\\\"מ סי' כ\\\"ז:\",2,0],[8,387,26,1,\"כל המקלל דיין וכו'. בסוף פ' ארבע מיתות (סנהדרין דף ס״ו) אלהים לא תקלל היינו הדיין ואמרי' בגמרא דאפי' לר' אליעזר בן יעקב דאמר האי אלהים קדש הוא והוי אזהרה למברך את השם יליף נמי דיין מהכא לא תקלל ולא כתיב ולא תקל.\",1,0],[8,387,26,1,\"ומ\\\"ש וכן אם קלל הנשיא אחד ראש הסנהדרין או המלך. למדה מדתנן בהוריות ואי זהו הנשיא זה המלך שנאמר ועשה אחת מכל מצות ה' אלהיו נשיא שאין על גבו אלא ה' אלהיו אמרי' דדוקא התם דכתב ה' אלהיו אמרי' דוקא מלך אבל היכא דלא כתיב לאו דוקא אלא הוא הדין לראש הסנהדרין. אחר שכתבתי זה מצאתי במכילתא אלהים לא תקלל אין לי אלא דיין נשיא מנין ת\\\"ל נשיא בעמך לא תאור:\",2,0],[8,387,26,1,\"ולא דיין ונשיא בלבד וכו'. בפ' שבועת העדות (שבועות דף ל״ה) תנן המקלל עצמו וחבירו בכולן עובר בלא תעשה ובגמ' (דף ל״ו) חבירו דכתיב לא תקלל חרש ומשום דלא תיקשי לן מה לחרש שכן חרישותו גרמה לו כלומר שאפי' שהוא שפל הזהירה תורה על קללתו אבל לא הזהירה לאיניש דעלמא לכך כתב רבינו ולמה נאמר חרש וכו' והוא ממה ששנינו בפסיקתא ולא תקלל חרש מרבה אני אפילו בר ישראל שאינו שומעך ק״ו לפניו:\",3,0],[8,387,26,1,\"ויראה לי שהמקלל הקטן הנכלם לוקה. למדה רבינו מדאמרינן בהחובל (דף פ\\\"ו) דקטן דמכלמינן ליה ומיכלם יש לו בשת וסובר רבינו דהוא הדין לענין קללה, ובטור ח\\\"מ סי' כ\\\"ז גורס המקלל את הישן חייב מפני שהוא כחרש וגירסא נכונה היא:\",4,0],[8,387,26,2,\"המקלל את המת פטור. מדאיצטריך בפ' אלו הן הנחנקין (סנהדרין דף פ״ה ע״ב) למילף דחייב על קללת אביו ואמו לאחר מיתה אלמא דבשאר כל אדם פטור ובת״כ לא תקלל חרש אין לי אלא חרש מנין לרבות כל אדם תלמוד לומר ונשיא בעמך לא תאור אם כן למה נאמר חרש מה חרש מיוחד שהוא בחיים אף כל שהוא בחיים יצא המקלל את המת שהוא פטור:\",1,0],[8,387,26,2,\"הואיל ומקלל כל אדם מישראל חייב וכו' וכן נשיא שקלל אביו חייב וכו'. במכילתא על פסוק אלהים לא תקלל.\",2,0],[8,387,26,2,\"ומ\\\"ש בין קטן כלומר קטן הנכלם:\",3,0],[8,387,26,3,\"המקלל עצמו לוקה וכו'. סוף שבועת העדות (שבועות דף ל״ו):\",1,0],[8,387,26,3,\"ואחד המקלל עצמו או וכו'. משנה שם (דף ל\\\"ה:) המקלל עצמו וחבירו בכולן פירוש בכל השמות והכנויים עובר בל\\\"ת ומשמע דכל שאינו בשם או כינויי אינו עובר בל\\\"ת והוא הדין לנשיא ודיין שאינו לוקה עד שיקללם בשם. והנה הראב\\\"ד כתב על דברי רבינו א\\\"א אינו לוקה אלא בשם המיוחד וכו'. ואני אומר שפשט הירוש' כדברי רבינו דהכי איתא התם (שבועות ספ\\\"ד) המקלל עצמו וחבירו בכולן עובר בלאו מהו ללקות חברייא אמרי אינו לוקה אמר לון רבי יוסי למה שהוא ל\\\"ת שאין בו מעשה והרי הממיר והנשבע לשקר לאו שאין בו מעשה עד כאן. ומשמע שר' יוסי בא לחלוק על דברי חברייא ואמר למה אתם אומרים שאינו לוקה מפני של\\\"ת שאין בו מעשה הוא אין זו טענה שהרי הממיר והנשבע לשקר לאו שאין בו מעשה ואפ\\\"ה לוקין עליו וה\\\"ה למקלל עצמו וחבירו וכדיהיב טעמא בריש תמורה והראב\\\"ד נראה שמפרש שלא אמרו חברייא אינו לוקה אלא בשאר שמות חוץ משם המיוחד ור' יוסי מתמה אמאן דבעי מהו ללקות דמהיכא תיסק אדעתין ללקות ואפי' על שם המיוחד כיון דלאו שאין בו מעשה הוא והשיבו לו שבדין הוא לוקה על שם המיוחד אע\\\"פ שאין בו מעשה כדאשכחן בממיר ונשבע לשקר וכטעמא דיהיב בריש תמורה:\",2,0],[8,387,26,3,\"וארור בו שבועה וכו'. גם זה שם ומייתי לה התם מקראי ופירש\\\"י צריך אדם לפרוש ממנו אם א\\\"ל חכם ארור בלשון נדוי ואם אמר אדם לחבירו לשם שבועה וקבלו עליו שבועה היא והמקלל את חבירו בלשון ארור הוא לה' קללה היא וחייב:\",3,0],[8,387,26,4,\"אינו לוקה עד שיתרו בו וכו'. נראה לי דסד\\\"א דכיון דמקלל חבירו חידוש הוא דלאו שאין בו מעשה אין לוקין עליו התראה נמי לא ניבעי קמשמע לן אי נמי ה\\\"א דכיון דאורחא דקללה בריהטא ובכעס הוא לא ניבעי התראה קמשמע לן:\",1,0],[8,387,26,4,\"או שהיתה הקללה וכו'. משנה שם פסק כת\\\"ק דר\\\"מ:\",2,0],[8,387,26,5,\"אף על פי שאינו לוקה וכו'. כבר ביאר רבינו דין התלמיד חכם בהלכות תלמוד תורה:\",1,0],[8,387,26,6,\"אע\\\"פ שיש לו וכו'. בפרק ב' דכתובות אמרינן דנשיא שמחל על כבודו כבודו מחול לכ\\\"ע.\",1,0],[8,387,26,6,\"ומ\\\"ש אינו יכול למחול על קללתו. נראה לי הטעם שכיון שהתורה חייבתו מלקות חטא למקום ואינו יכול למוחלו:\",2,0],[8,387,26,6,\"אבל מי שנתחייב נדוי וכו'. נראה מכאן דמי שנתחייב נדוי אע\\\"פ שיעשה כל תשובות שבעולם אין לו כפרה עד שינדוהו כל שלא מחל לו חבירו:\",3,0],[8,387,26,7,\"כל הדן בדיני עכו\\\"ם ובערכאות שלהם וכו' לפניהם ולא לפני עכו\\\"ם וכו'. גיטין פ' תשיעי (דף פ\\\"ט):\",1,0],[8,387,26,7,\"היתה יד עכו״ם וכו'. למדוה הפוסקים מדאמרינן בסוף החובל (בבא קמא דף צ״ב:) קרית חברך ולא ענך רמי גודא שדי ביה פירש״י כותל הפל עליו כלומר הניחו ויפול ברשעו דחהו בידים, הכי נמי כיון דלא ציית דינא יביאהו בערכאותיהם אבל אי ציית דינא אין לו להביאו בערכאותיהם כדבסמוך:\",2,0],[8,387,26,7,\"סליקו הלכות סנהדרין בס\\\"ד\",3,0],[8,388,1,1,\"העד מצווה להעיד וכו'. בבא קמא ריש הכונס (בבא קמא דף נ״ה:) תניא היודע עדות לחבירו ואינו מעיד לו פטור מדיני אדם וחייב בדיני שמים ופריך בגמרא (דף נ״ו) במאי עסקינן אילימא בבי תרי פשיטא דאורייתא הוא אם לא יגיד ונשא עונו אלא בחד. ואיכא למידק דמנא ליה לגמרא דתרי מיחייב דאורייתא מאם לא יגיד וכו' אימא הני מילי כשעבר על השבועה כדכתיב ושמעה קול אלה ותירצו התוספות דהכי קאמר קרא כשעובר בדבר אם לא יגיד היה נושא עון אז יביא קרבן שבועה אבל בלא שבועה נמי איכא נשיאות עון כדתנן בסנהדרין פרק אחד דיני ממונות שהיו אומרים לעדים שמא תאמרו מה לנו ולצרה הזאת כלומר מה לנו להכניס ראשנו בדאגה זאת אפילו על האמת לפי שהיו מאיימין עליהם כמה איומים והלא כבר נאמר והוא עד או ראה או ידע אם לא יגיד וכו'. וכתב\",1,0],[8,388,1,1,\"רבינו להעיד בבית דין לומר דדוקא בבית דין הוא שחייב להעיד שאם אמר אינו יודע שוב אינו יכול להעיד אבל חוץ לבית דין אין לחוש כיון שיכול להגיד ולהעיד וכן דעת התוספות והרא\\\"ש אי נמי מדכתיב אם לא יגיד ונשא עונו במקום שאילו היה מגיד היה מחייב ממון לאפוקי חוץ לבית דין דאפילו היה מגיד לא היה מחייב ממון. ויש לדקדק בלשון רבינו שכתב העד מצווה להעיד בבית דין דמשמע עד יחידי ומסיק שנאמר אם לא יגיד וכו' ובפרק הכונס לא מייתי קרא אלא לשני עדים דקרא לא משמע אלא לשנים וכל מקום שנאמר עד הרי כאן שנים עד שיפרוט לך הכתוב אחד שנאמר לא יקום עד אחד באיש אבל לעד אחד ליכא קרא. ויש לומר דרבינו גם כן לא מיירי אלא כשיש שני עדים בדבר וקאמר דמצוה על כל אחד מהם להעיד מאם לא יגיד דאילו היכא דליכא אלא עד אחד כבר כתב רבינו סוף פרק י\\\"ז דפטור מדיני אדם וחייב בדיני שמים וכדברי הגמרא בפרק הכונס.\",2,0],[8,388,1,1,\"ומה שכתב בין בעדות שיחייב בו את חבירו בין בעדות שיזכהו בו מדלא מפליג קרא וסתם וכתב ואם לא יגיד ועוד דדומיא דמחייב קרבן שבועה אם נשבע נושא עון כשלא נשבע וקרבן שבועה ודאי מיחייב בין בעדות שיחייב בו את חבירו בין בעדות שיזכהו בו.\",3,0],[8,388,1,1,\"ומה שכתב והוא שיתבענו. בפרק שבועת העדות (שבועות דף ל\\\"א:) דכל שלא שמעו מפיו שאמר להם בואו והעידוני אינם חייבים קרבן שבועה ובפקדון חייבים ומשמע דהוא הדין נמי בנשיאות עון בלא שבועה בעינן שישמעו מפיו דאי לא תימא הכי ליפלוג בעדות גופה בין היכא דאיכא שבועה להיכא דליכא ועוד דהא אמרינן דכל היכא דמחייב קרבן שבועה אם לא נשבע נשיאות עון מיהא איכא מכלל דכי לא מחייב קרבן שבועה אפילו נשבע כי לא נשבע ליכא נשיאות עון.\",4,0],[8,388,1,1,\"ומה שכתב רבינו והוא שיתבענו להעיד בדיני ממונות. נראה מדבריו דבדיני נפשות אפילו לא תבעוהו חייב ואפשר דטעמא משום דחייבים העדים לינקם ממנו וסמך לדבר מצאתי שכתב הרא\\\"ש ז\\\"ל פירקא קמא דמכות שכל הרואה דבר ערוה חייב להעיד לקיים מה שנאמר ובערת הרע בקרבך.\",5,0],[8,388,1,1,\"ומה שכתב שנאמר והוא עד וכו'. לא קאי למאי דסליק מיניה אלא למאי דפתח ביה העד מצווה להעיד בבית דין שנאמר והוא עד וכו':\",6,0],[8,388,1,2,\"היה העד חכם גדול וכו'. פ' שבועת העדות (שבועות דף ל':) אמר רבה בר רב הונא האי צורבא מרבנן דידע בסהדותא וזילא ביה מילתא למיזל לבי דינא דזוטר מיניה לאסהודי קמיה לא ליזיל וכו' ה״מ בממונא אבל באיסורא אין חכמה ואין תבונה ואין עצה וכו' כ״מ שיש חילול השם אין חולקין כבוד לרב ופירש״י אבל באיסורא כגון אשה הבאה לפני חכם להתירה לינשא ותלמיד זה יודע שבעלה חי אין חכמה לפני ה' נראה מדבריו דדוקא כשרוצים להתיר את האסור אבל אם רוצים לאסור את המותר לא ליזיל ומדנקט גמרא כ״מ שיש חילול השם וכו' משמע הכי דאילו באיסור המותר ליכא חילול השם יתברך טפי מהוצאת ממון שלא כדין אבל מדברי רבינו שאחר\",1,0],[8,388,1,2,\"שכתב אבל בעדות שמפריש בה מן האיסור חזר\",2,0],[8,388,1,2,\"וכתב וכן בעדות נפשות או מכות נראה דסבירא ליה דדיני נפשות אע\\\"ג דאי ליכא עדים פוטרין אותו וליכא איסורא דאין לדיין אלא מה שעיניו רואות מ\\\"מ חילול השם איכא דיש עדים בדבר ולא יתברר דין מדיני נפשות ודיני מכות במילי טובא בתר דיני נפשות גרירין אי נמי דכשם שאילו היו רוצים להרגו וזה יודע לו זכות היה חייב להעיד להצילו כדי שלא ישפך דם נקי הוא הדין נמי אם רוצים לפוטרו לפי שאין עדים וזה יודע לו חובה שהוא כאילו הרגו לאחר כיון שיודע עדות לנקום נקמתו ואינו נוקם וכמ\\\"ש הרא\\\"ש פ\\\"ק דמכות שכל הרואה דבר ערוה חייב להעיד לקיים ובערת הרע מקרבך ודיני מכות כבר כתבתי דבמילי טובא בתר דיני נפשות גרירן אי נמי דכיון דחד ממחוייבי מלקות הוא המכה את חבירו ושייך ביה זה הטעם השני של דיני נפשות שכשם שהוא חייב להציל לזה אם הדין עמו כך הוא חייב לנקום נקמתו של זה וכיון דבחד ממחייבי מלקות שייך למימר הכי לא פלוג רבנן:\",3,0],[8,388,1,3,\"כהן גדול וכו'. בסנהדרין פ\\\"ב (דף י\\\"ח) תנן כ\\\"ג דן ודנין אותו מעיד ומעידין אותו וכו' המלך לא דן ולא דנין אותו לא מעיד ולא מעידין אותו וגרסינן בגמרא עלה דמתני' כ\\\"ג מעיד והתניא והתעלמת פעמים שאתה מתעלם וכו' כגון זקן ואינו לפי כבודו (והכא נמי זילותא הוא לכהן גדול לאסהודי) אמר רב יוסף מעיד למלך והתנן לא דן ולא דנין אותו לא מעיד ולא מעידין אותו אלא אמר ר' זירא מעיד לבן מלך בן מלך הדיוט הוא אלא מעיד בפני המלך והא אין מושיבין מלך בסנהדרין משום יקרא דכ\\\"ג אתי ויתיב מקבלין ניהליה לסהדותיה קאי הוא ואזיל ומעיינינן ליה אנן בדיניה ע\\\"כ. נראה דלמסקנא דאמרינן אלא מעיד בפני המלך לאו בעדות שנוגע למלך עסקינן דהא לעיל דאמרי' דמעיד למלך מקשינן עליה מדתנן המלך לא דן ולא דנין אותו ואם כן היכי מהדר לאוקומי בנוגע למלך הא תיקשי ליה אלא ודאי באינו נוגע למלך עסקינן ואם כן היאך כתב רבינו אלא עדות שהוא למלך ישראל בלבד הא בגמ' לא קיימינן הכי וצ\\\"ע. ומדברי רבינו שכתב דין כ\\\"ג סמוך לדין צורבא מרבנן דמפלגינן ביה בין עדות ממון לעדות שמפריש בה מן האיסור וסתם דבריו בכ\\\"ג משמע דבכ\\\"ג לא שני לן בין עדות ממון לעדות שמפריש בה מאיסור:\",1,0],[8,388,1,4,\"מצות עשה וכו' ומסיעין אותם מענין לענין. בסנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ב:) פותחין בזכות וכו' מי לא תניא רשב״א אומר מסיעין את העדים ממקום למקום כדי שתטרף דעתם ויחזרו בהם ומפרש רבינו ממקום למקום מענין לענין.\",1,0],[8,388,1,4,\"ומה שכתב שמ״ע לדרוש את העדים וכו' ולהרבות בשאלתם וכו' איתא בפרק היו בודקין (סנהדרין דף מ') ובפרק זה יתבאר:\",2,0],[8,388,1,4,\"וצריכין הדיינין וכו'. משנה בסנהדרין פרק ה' שם היו בודקין אותם בשבע חקירות באי זה שבוע ובאי זו שנה וכו' העובד ע\\\"ז את מה עבד ובמה עבד.\",3,0],[8,388,1,4,\"ומה שכתב אפילו אמר היום הרגו וכו' או אמש הרגו. פלוגתא דרבי יוסי ותנא קמא שם בברייתא ופסק כת\\\"ק:\",4,0],[8,388,1,5,\"החקירות והדרישות וכו'. משנה שם מה בין חקירות לבדיקות חקירות אחד אומר איני יודע עדותן בטלה בדיקות אחד אומר איני יודע אפילו שנים אומרים אין אנו יודעין עדותן קיימת ואמרינן בגמ' (דף מ\\\"א:) דהיינו טעמא דבחקירות אמר אחד אינו יודע עדותן בטלה דהוה ליה עדות שאי אתה יכול להזימה וכל עדות שאי אתה יכול להזימה אינה עדות אבל בדיקות אפילו אמרו כולן אין אנו יודעים עדות שאתה יכול להזימה היא שהזמה אינה תלויה בכך אלא הכחשה דמאי שייך עמנו הייתם גבי בדיקות ועוד שם במשנה כל המרבה בבדיקות הרי זה משובח מעשה ובדק בן זכאי בעוקצי תאנים:\",1,0],[8,388,2,1,\"מה בין חקירות וכו'. כבר נתבאר בסוף פ\\\"א:\",1,0],[8,388,2,1,\"ובזמן שהם מכחישין זא״ז אפילו בבדיקות עדותן בטלה. משנה שם אחד חקירות ואחד בדיקות בזמן שמכחישין זה את זה עדותן בטלה ואע״ג דאמר רב חסדא אחד אומר כליו לבנים ואחד אומר כליו שחורים הרי זה נכון הא איתותב ואע״ג דשני לא שבקינן פשטא דמתניתין וניקום ונסמוך אשינויי ועוד דהא אמרינן בפרק זה בורר (סנהדרין דף ל':) דרבא פליג עליה דרב חסדא וודאי דהלכתא כוותיה לגבי רב חסדא דהא בתרא הוא. וכתב הראב״ד וכן העד השני וכו' עד הרי עדותן בטלה א״א טעה בזה כי הבדיקות אם אמר איני יודע אין עדותן בטלה עכ״ל. ואני אומר שלא טעה בכך אלא שהוא ז״ל סובר שהכוונה בכלי שבידו הוא מכלל החקירות וכמבואר בדבריו בפרק שקודם זה. אבל אי קשיא על דברי רבינו הא קשיא שכתב בפ״א ומכלל החקירות יתר על השבע השוות בכל שאם העידו עליו שעבד ע״ז וכו' ומנ״ל הא דהא בין חקירות בין בדיקות מדאורייתא נינהו וטעמא דחקירות פסלי כשאומר איני יודע נתבאר בפרק היו בודקין משום דהוי עדות שאי אתה יכול להזימה ובשלמא בשבע חקירות השוות בכל העדים נזומין על ידן אבל במ״ש רבינו שהם מכלל החקירות אם אמר איני יודע למה עדותו בטלה הא אין העדים נזומין על ידן וצ״ע. ותמהני על סמ״ג שכתב יתר על השבע היו חוקרין אותן וכו' הדברים האלה נקראים בדיקות ולא הזכיר סברת רבינו:\",2,0],[8,388,2,3,\"היו העדים מרובים וכו'. משנה שם (דף מ') מה בין חקירות לבדיקות חקירות אמר אחד איני יודע עדותן בטלה בדיקות אמר עד אחד איני יודע אפילו שנים אומרים אין אנו יודעים עדותן קיימת ואמר בגמ' (דף מ\\\"א:) מאי אפילו שנים אומרים פשיטא כי אמר אחד איני יודע עדותן קיימת כי אמרי בי תרי נמי עדותן קיימת ואסיק רבא דהכי קאמר אפי' בחקירות שנים אומרים ידענו ואחד אומר איני יודע עדותן קיימת פירוש אם יש שלשה עדים.\",1,0],[8,388,2,3,\"ומה שכתב אבל אם הכחיש וכו', מדקתני סיפא דמתני' אחד חקירות ואחד בדיקות בזמן שמכחישין זה את זה עדותן בטילה ומשמע דקאי אכל מאי דאתמר ברישא דהיינו כשהם שלשה עדים:\",2,0],[8,388,2,4,\"עד אחד אומר ברביעי בשבת וכו'. משנה שם אחד אמר בשנים בחדש ואחד אומר בשלשה עדותן קיימת שזה ידע בעיבורו של חדש וזה לא ידע בעיבורו של חדש אחד אומר בג' ואחד אומר בה' עדותן בטילה והא דעדותן קיימת דוקא בשכיוונו ביום מימי השבוע שאל\\\"כ הא מתכחיש ביומי השבוע ופשוט הוא:\",1,0],[8,388,2,4,\"בד\\\"א עד חצות וכו'. מימרא דרב אסי אמר ר' יוחנן שם (דף מ\\\"א:):\",2,0],[8,388,2,5,\"אמר האחד בשלשה והשני וכו'. משנה שם:\",1,0],[8,388,2,5,\"אמר עד אחד בשתי שעות ביום וכו' עד עדותן בטלה. גם זה משנה שם ואע״ג דפלוגתא דרבי יהודה ורבנן היא הלכה כתנא קמא דאמר הכי. ומיהו איכא למידק דאמרינן בפרק אור לארבעה עשר (פסחים דף י״ב) דלת״ק אדם טועה בשתי שעות חסר משהו והיאך כתב רבינו שדרך האדם לטעות שעה אחת שהוא דלא כמסקנא דגמ' ועוד דקשיא דידיה אדידיה דמתחלת דבריו משמע שאין אדם עשוי לטעות יותר משעה אחת וממ״ש בסוף שאם הוא אמר בשלשה והשני אמר בה' עדותן בטלה משמע הא אם השני אמר בד' וחצי עדותן קיימת וי״ל שמה שכתב שדרך האדם לטעות שעה אחת רוצה לומר בין השעה השניה לשלישית או בין שעה ג' לד' פירוש שדרך אדם לטעות כשעומדין בשעה שלישית קורין אותה שניה וטועין מתחלת השניה עד סוף השלישית וכן בין ג' לד' שטועה משניה לג' ואפי' שהראשון יאמר שעה שניה והשני אמר שעה שלישית נאמן שהראשון כוונתו היתה על תחלת שעה שניה והשני לסוף שלישית אפילו הכי עדותן קיימת דעביד איניש למיטעי בין שעה אחת לחבירתה ואפילו בכל הכמות של השתי שעות ומפני שאין הטעות אלא בשעה אחת שהשניה קורא ג' או הג' שניה מפני זה קורא אותה רבינו טעות שעה אחת ואף אם הזמן טעות ב' שעות חסר משהו כמו שהעלו בגמ' ולפיכך דקדק רבינו בלשונו ולא כתב שדרך העם לטעות שעה אחת אלא כתב שדרך העם לטעות בשעה אחת שר״ל הוא טועה בשם השעה וזה הטעות יפול מתחלת שעה אחת עד סוף שעה אחרת. והרב הדיין ה״ר משה ן' אלאשקאר ז״ל כתב רבא אית ליה בפרק אור לי״ד דלדברי ר״מ אדם טועה שתי שעות חסר משהו ולדברי ר' יהודה אדם טועה ג' שעות חסר משהו וידוע שהרמב״ם פסק כר״מ משום דסתם מתניתין כוותיה וא״כ צריך ליישב לשון הרמב״ם דהא דקאמר שדרך העם לטעות בשעה רוצה לומר שיעמוד בשעה אחת ויטעה בשעה שלפניה או שלאחריה דקרי לשניה שלישית או איפכא והיינו טעות שעה אחת אלא דכי דייקינן אפשר שיהיה הטעות שתי שעות כדאיתא התם והרב ז״ל סתים לה סתומי דכפשטה טעות שעה אחת היא וקושטא דמילתא דלא דייקינן בהו בסהדי בכמה בשעה בתחלתה או בסופה כדמסיק בפרק היו בודקין וזה דרך הרב לסתום הדברים ולקרבם אל המושכל עכ״ל:\",2,0],[8,388,2,5,\"אמר עד אחד קודם הנץ החמה וכו'. מימרא דרב שימי בר אשי שם (דף מ\\\"ב):\",3,0],[8,388,3,1,\"אחד דיני ממונות וכו'. סנהדרין (דף ל\\\"ב) ריש פרק אחד דיני ממונות ואחד דיני נפשות בדרישות וחקירות ורמינן עלה מדתניא דדיני ממונות לא בעו דרישה וחקירה ואמר רב חנינא דבר תורה אחד דיני ממונות ואחד דיני נפשות בדרישה וחקירה ומה טעם אמרו דיני ממונות לא בעינן דרישה וחקירה כדי שלא תנעול דלת בפני לוין כלומר ומתני' דאורייתא קמי תקנתא וברייתא דרבנן בתר תקנתא ורבא אמר מתני' דהכא בדיני קנסות ואידך בהודאות והלואות כלומר תרווייהו בתר תקנתא דרבנן ומתני' בדיני קנסות דליכא למיחש לנעילת דלת ורב פפא אמר אידי ואידי בהודאות והלואות כאן בדין מרומה כאן בדין שאינו מרומה פירוש לא בשיודעים בו שהוא מרומה דא\\\"כ חייב לסלק עצמו ממנו וכמו שכתב רבינו פרק כ\\\"ד מהלכות סנהדרין וזה\",1,0],[8,388,3,1,\"שכתב וכן אם ראה הדיין שהדין מרומה וחשש לו כלומר חששא בעלמא לא שיודע כן בודאי וסובר רבינו דהני תלתא אמוראי מר אמר חדא ומר אמר חדא ובענין דינא לא פליגי וכמו שפירשתי דכולהו סברי דהודאות והלוואות לא בעו דרישה וחקירה ודיני קנסות בעו דרישה וחקירה ובדין מרומה כ\\\"ע מודו דברייתא הוא פרק שבועת העדות:\",2,0],[8,388,3,3,\"ואם הכחישו העדים זה את זה בבדיקות וכו'. סנהדרין פרק זה בורר (סנהדרין דף ל':) אמר רב יהודה עדות המכחשת זו את זו בבדיקות כשירה בדיני ממונות משמע הא בחקירות עדותן בטלה ומפרשי נהרדעי הכחשה דבדיקות אפילו אחד אומר מנה שחור ואחד אומר מנה לבן מצטרפי ואוקימנא כר״ש בן אלעזר דאמר לא נחלקו ב״ש וב״ה על שתי כיתי עדים שאחת אומרת מאתים ואחת אומרת מנה שיש בכלל מאתים מנה על מה נחלקו על כת אחת שב״ש אומרים נחלקה עדות וב״ה אומרים יש בכלל מאתים מנה וידוע דהלכה כב״ה ובפ' חזקת הבתים (בבא בתרא דף מ״א:) עבד רב יהודה עובדא כב״ה ואליבא דרשב״א ואמרינן נמי בפ' זה בורר (סנהדרין דף ל״א) אחד אומר חבית של יין ואחד אומר חבית של שמן הוה עובדא ואתא לקמיה דרבי אמי וחייביה רבי אמי לשלומי ליה חביתא דחמרא מגו חביתא דמשחא כמאן כרשב״א אימור דאמר רשב״א היכא דיש בכלל מאתים מנה כה״ג מי אמר לא צריכא לדמי כלומר דזה אומר בפני הודה לו דמי חבית יין וזה אומר דמי חבית שמן דתרווייהו מסהדי אדמי חבית יין אחד אומר בדיוטא העליונה ואחד אומר בדיוטא התחתונה א״ר חנינא מעשה בא לפני רבי וצירף עדותן. וי״ל דהב״ע כגון שאדם יכול לראות שתי הדיוטות הא לאו הכי אין מצטרפין דהוה ליה מכחישין זה את זה בחקירות ואפי' בדיני ממונות פסילי וכמו שנתבאר בסמוך וכ״כ הפוסקים:\",1,0],[8,388,3,4,\"דין תורה שאין מקבלין עדות וכו'. בפרק גט פשוט (בבא בתרא דף קס״ח) תנן מי שנמחק שטר חובו מעמיד עליו עדים וכו' והם עושין לו קיומו ובב״ק פרק הגוזל קמא (דף פ״ח) גבי שורף שטרותיו של חבירו פרכינן אי דאיכא סהדי דידעי מאי הוה (כתיב) בשטרא ליכתבו ליה שטרא מעליא וקשה היכי מצו כתבי הא ביבמות פ' ד' אחין (יבמות דף ל״א:) אמרינן דהיינו טעמא דלא כתבינן זמן כשמקדש בשטר משום דאית לן לאנוחי גבי סהדי וזמנין דלא דכירי וחזו בכתבא ואתו ומסהדי ורחמנא אמר מפיהם ולא מפי כתבם והתוספות האריכו בישוב קושיא זאת בפ״ב דכתובות ופ״ג דבתרא ופרק ארבעה אחין ועיין בהרי״ף פ' ד' אחין ומדברי רבינו למדנו תירוץ יפה דאה״נ דדין תורה מפיהם ולא מפי כתבם בין בדיני ממונות בין בדיני נפשות ורבנן הקילו בדיני ממונות כדי שלא תנעול דלת בפני לוין וההיא דפ' ד' אחין דהוי דיני נפשות לא מצו מסהדי דאוקמוה אדין תורה וההיא דהגוזל דמצו מסהדי בדיני ממונות היינו מדרבנן כדי שלא תנעול דלת בפני לוין ולכן בקנסות ומכות וגלות דלא שייך נעילת דלת אין דנין על פי כתב ידן והר״ש בר צמח כתב שאין דברי רבינו מכוונים דודאי עדים החתומים בשטר כשרין ומקרא מלא דבר הכתוב (ירמיהו ל״ב:מ״ד) שדות בכסף יקנו וחתום עכ״ל. ואני אומר דאי מהא לא קשיא דהאי קרא דברי קבלה הוא ולא דבר תורה אך קשה לי דאמרינן בכמה דוכתי מהם סוף פרק ב' דכתובות (דף כ״א) כיון דקיום שטרות דרבנן הימנוה רבנן בדרבנן אלמא דמדאורייתא עדים החתומים על השטר נעשה כמי שנחקרה עדותן בב״ד ולא בעי קיום וצ״ע:\",1,0],[8,388,3,5,\"כל עד שנחקרה עדותו וכו'. בפרק שבועת העדות (שבועות דף ל״א:) משנה השביע עליהם חמש פעמים לפני ב״ד וכפרו אינם חייבים אלא אחת אמר רבי שמעון מה טעם הואיל ואינם יכולים לחזור ולהודות ובכל דוכתא אמרינן כיון שהגיד שוב אינו חוזר ומגיד ובתוספתא דסנהדרין יכולים לחזור בהם עד שיחקר עדותם בב״ד נחקרה אין יכולים לחזור בהם ובתוספתא ריש פרק שני דכתובות ובירושלמי פ״ב דכתובות עדים שהעידו לטמא ולטהר לרחק ולקרב לאסור ולהתיר לפטור ולחייב עד שלא נחקרה עדותן בב״ד אמרו מבודין היינו הרי אלו נאמנין משנחקרה עדותן בב״ד אמרו מבודין היינו אינן נאמנים.\",1,0],[8,388,3,5,\"ומ\\\"ש אפילו נתן טעם לדבריו. מפורש בפרק נגמר הדין דאי הדרי בהו סהדי אע\\\"ג דקא יהבי טעמא למלתייהו קרינן בהו כיון שהגיד שוב אינו חוזר ומגיד.\",2,0],[8,388,3,5,\"ומ״ש רבינו כל עד שנחקרה עדותו וכו' אינו יכול לחזור בו כללו של דבר וכו'. נראה דדוקא כשהעיד בב״ד אינו יכול לחזור אבל אם שאלוהו על עדותו ואמר איני יודע יכול לחזור ולהעיד ולישנא דכיון שהגיד שוב אינו חוזר ומגיד הכי דייק דהיכא דהגיד בתחלה כלומר שאמר עדותו אינו חוזר ומגיד אבל כל שאמר שאינו יודע לא מיקרי מגיד ואם נתן אמתלא למה אמר בתחלה איני יודע נאמן ועוד דכשהעיד כבר אם עתה חוזר בו אע״פ שיטעון מפני פחדו עשיתי או משום טענה אחרת אינו נאמן דהא משוי נפשיה רשיעא דאסהיד שקרא והיינו טעמא דכשהשביעם בפני ב״ד אינם יכולים לחזור ולהעיד דמשוו נפשייהו רשיעי אבל כי אמר איני יודע לא משוי נפשיה רשיעא דיכול לומר מפני הפחד אמרתי איני יודע דהיינו שב ואל תעשה וראיה מדאמרינן בפרק המפקיד (בבא מציעא דף ל״ט:) ובפרק שני דכתובות (דף כ״ז:) מרי בר איסק אתא ליה אחא מבי חוזאה א״ל פלוג לי בנכסי דאבא א״ל לא ידענא לך אתו לקמיה דרב חסדא וכו' א״ל לההוא דאתא אייתי סהדי דאחוה את א״ל אית לי סהדי ומסתפו מיניה דגברא אלמא הוא א״ל לדידיה זיל אייתינהו את דלאו אחוך הוא א״ל דינא הכי המע״ה א״ל הכי דאיננא לך ולכל אלמי חבירך השתא נמי אתו ומשקרי תרתי לא עבדי ומשמע מפירש״י דהכי קאמר חדא דשתקי מלהעיד האמת וחדא דמסהדי שיקרא לא עבדי הרי שאמרו שם דאשמא לא יעידו מפני פחדו של זה חיישינן אבל לשמא יעידו שקר לא חיישינן וטעמא כדפרישית ועוד דאם לא כן למה ליה למתני' למינקט השביע עליהם חמש פעמים בפני ב״ד וכפרו אינם חייבים אלא אחת דמשמע דאפילו בפעם ראשונה השביעם ופטור דקתני חוץ משבועה ראשונה לינקוט תבעם בפני ב״ד וכפרו וחזר ותבעם חמש פעמים והשביעם פטור אפילו משבועה ראשונה דהא אינו יכול לחזור ולהודות אלא ודאי כדאמרן ולזה נוטה דעת הר״ן בפרק שבועת העדות. ואין להקשות ממה שדקדקתי בראש הלכות אלו מלשון רבינו דהעד מצווה להעיד בב״ד דוקא משום דכיון שאמר איני יודע שוב אינו יכול להעיד דהתם בשאינו נותן אמתלא אלא אומר אז לא רציתי להעיד ועכשיו אני רוצה והכא כשנותן אמתלא לדבריו וכמו שכתבתי.\",3,0],[8,388,3,5,\"ומה שכתב וכן אינו יכול להוסיף בעדותו תנאי הוא ממאי דאמרינן בפ\\\"ב דכתובות דעדים האומרים תנאי היו דברינו למעקר סהדותייהו קמא אתו כלומר וכיון שהגיד אינו חוזר ומגיד אלא דהתם מהימני משום דאין כתב ידם יוצא ממקום אחר והוה ליה כאילו עדיין לא השלימו עדותן וכיון שאין דברים אחרונים סותרים לראשונים לגמרי נאמנים אבל הכא שכבר נחקרה עדותן וגמרו דבריהם ועתה באים לחזור ולומר תנאי היה הוו להו חוזרים ומגידים ולא מהימני:\",4,0],[8,388,3,6,\"עדים החתומים על השטר וכו'. פרק שני דכתובות (דף י\\\"ח:) משנה העדים שאמרו כתב ידינו הוא זה אבל אנוסים היינו קטנים היינו פסולי עדות היינו הרי אלו נאמנים אם יש עדים שהוא כתב ידם או שהיה כתב ידם יוצא ממקום אחר אינן נאמנין ואמרינן בגמ' דאם כתב ידן יוצא ממקום אחר אפי' אמרו אנוסים היינו מחמת נפשות אין נאמנים משום דעדים החתומים על השטר נעשה כמי שנחקרה עדותן בבית דין וכיון שהגיד שוב אינו חוזר ומגיד ואמר רמי בר חמא לא שנו היכא דאין כתב ידן יוצא נאמנים אלא שאמרו אנוסים היינו מחמת נפשות אבל אנוסים היינו מחמת ממון אין נאמנים מאי טעמא לפי שאין [אדם] משים עצמו רשע:\",1,0],[8,388,3,7,\"וכן אם אמרו אמנה היו דברינו וכו'. שם (דף י\\\"ט) א\\\"ר יהודה אמר רב האומר שטר אמנה הוא זה אינו נאמן פירש\\\"י לא לוה כלום אלא כתבו ומסרו למלוה שאם יצטרך ללוות ילוה והאמינו שלא יתבענו אא\\\"כ מלוהו ואוקמה רב אשי בדקאמרי עדים ודאין כתב ידם יוצא ממקום אחר והיינו טעמא דלא מהימני כדרב הונא דאמר אסור לאדם שישהא שטר פרוע בתוך ביתו משום שנא' ואל תשכן באהליך עולה ואמר רב ששת בריה דרב אידי שמע מינה עדים שאמרו אמנה היו דברינו אין נאמנין מאי טעמא כיון דעולה הוא אעולה לא חתימי:\",1,0],[8,388,3,8,\"אמרו העדים שטר מכר זה וכו'. שם אמר רב נחמן אמנה היו דברינו אין נאמנין מודעא היו דברינו אין נאמנין מר בר רב אשי אמר אמנה היו דברינו אין נאמנין מודעא היו דברינו נאמנין מאי טעמא האי ניתן ליכתב והאי לא ניתן ליכתב ופסק רבינו כמר בר רב אשי דבתרא הוא וכן פסק הרי\\\"ף והרא\\\"ש ז\\\"ל ופירוש ניתן ליכתב לדעת רבינו דשטרא מיהא מהני דכי מבטלי זביני מחמת מודעא צריך המוכר להחזיר הדמים שקבל כמ\\\"ש בשטר וא\\\"כ אפי' בשכתב ידם יוצא ממקום אחר נאמנין דלא עקרי סהדותייהו לגמרי דאכתי מהני לאהדורי זוזי אפומא דההוא שטרא אי נמי דהאי ניתן ליכתב קאי אמודעא שבידם לכתבה ולכתוב זמנה קודם שטר המכר דאותו יום עצמו ואם כן אפילו כתב ידם יוצא ממקום אחר נאמנין שאין אנו חוזרים ומגידים שעדיין לא הגידו כיון שבידם לפסול הגדת המכר משעה ראשונה ולא דמי לאנוסים היינו מחמת נפשות אבל לרש\\\"י שפירש דניתן ליכתב להציל אנוס מיד אונסו צריך לומר דדוקא בשאין כתב ידם יוצא ממקום אחר אבל בשכתב ידם יוצא ממקום אחר לא דאע\\\"ג דניתן ליכתב מהאי טעמא כי אמרו אנוסים היינו מחמת נפשות כל שכן דניתן ליכתב ואפי' הכי כשכתב ידן יוצא ממקום אחר אינם נאמנים משום דעקרי לסהדותייהו והוו להו חוזרים ומגידים:\",1,0],[8,388,3,10,\"אמרו על תנאי היה וכו'. שם בעא מיניה רבא מרב נחמן עדים שאמרו תנאי היו דברינו פירש\\\"י על תנאי מכרה לו שיעשה לו כך וכך ולא ראינו שקיים לו תנאו וזה אומר לא קיים לי ואינו מכר מהו אמר ליה כי אתו לקמן לדינא אמרינן להו זילו קיימו תנאייכו וחותו לדינא. עד אומר תנאי ועד אומר אינו תנאי א\\\"ר פפא תרוייהו בשטרא מעליא קא מסהדי והאי דקאמר תנאי הוה ליה חד ואין דבריו של אחד במקום שנים מתקיף לה רב הונא בריה דרב יהושע א\\\"ה אפי' תרווייהו נמי אלא אמרינן הנך למעקר סהדותייהו אתו האי נמי למעקר סהדותיה אתי פירש\\\"י למעקר סהדותייהו אתו לומר לא חתמנו אלא על מנת שיתקיים התנאי וכיון דתנאי מילתא אחריתי היא מהימני דעדות בפני עצמו הוא חד נמי כיון דאית לן למימר דמילתא אחריתי היא ושטרא ממילא מיעקר אשתכח דאין בשטר חתום אלא עד אחד. ודע שרבינו האי ז\\\"ל וכת אחת של ראשונים פירשו דאפי' בשכתב ידם יוצא ממקום אחר עסקינן וכת אחת מן האחרונים כתבו כדברי רבינו והכריע הרמב\\\"ן כדבריהם וטענת שתי הכתות הלא הם כתובים על פירוש הר\\\"ן פ\\\"ב דכתובות:\",1,0],[8,388,3,11,\"גם בדיני ממונות אין מקבלים עדות אלא בפני בעל דין וכו'. לפי שלמעלה חילק בין דיני ממונות לדיני נפשות אמר שבדין זה אין חילוק שגם בדיני ממונות אין מקבלין עדות שלא בפני בעל דין ודין זה הנה הוא בבבא קמא פרק בתרא (דף קי\\\"ב:) אמר רב אסי אמר רבי שבתי מקבלים עדים שלא בפני בעל דין תהי בה רבי יוחנן וכי מקבלים עדים שלא בפני בעל דין פירוש משום דאמר קרא והועד בבעליו אמרה תורה יבא בעל השור ויעמוד על שורו קבלה מיניה רבי יוסי בר חנינא כגון שהיה הוא חולה או עדיו חולים או שהיו עדיו מבקשים לילך למדינת הים ושלחו לו ולא בא וכו'. אמר רבא הלכתא מקיימין את השטר שלא בפני בעל דין ואפילו (הלה) עומד וצווח ואי אמר קבעו לי זמנא עד דמייתינא סהדי ומרענא לשטרא קבעינן ליה וכתוב בגי' דאם עברו וקבלו עדים שלא בפני בעל דין לא עשו כלום דהוו להו טועים בדבר משנה דחוזר וכן נראה מדקדוק דברי רבינו שכתב גם בדיני ממונות משמע שבדיני ממונות נמי אם קבלו עדות שלא בפני בעל דין לא עשו כלום כמו בדיני נפשות וכתבו התוספות (בד\\\"ה ושלחו לו) דמשמע דבעינן שלחו לו ולא בא בהדי עדיו חולים או מבקשים לילך למדינת הים מדלא קאמר או שלחו לו כדקאמר או שהיו עדיו חולים אבל בעל נמוקי יוסף כתב מדלא קאמר או ששלחו לו דקדקו המפרשים ז\\\"ל דקאי אדסליק מיניה שאם היו עדיו מבקשים לילך צריך להודיע לו שיבא קודם שיקבלו כיון שיש שהות ואם לא בא מקבלין עדותן שלא בפניו ואין סברא לומר דקאי נמי אהוא חולה או עדיו חולים דכיון שהדבר נחוץ ודאי מקבלים ואין צריך לשלוח לו דאם לא עכשיו אימתי דסתם חולים לסכנה חיישינן להו עכ\\\"ל. ולפי דבריו אפשר לומר נמי דהוא הדין אם היה במקום רחוק והיו עדיו מבקשים לילך למדינת הים דאין אומרין נמתין עד שישלחו לו דהא בין כך ובין כך ילכו העדים וכתב הר\\\"ן ז\\\"ל פרק אלמנה נזונת גבי מוכרת שלא בבית דין צריכה שבועה דנתבע המביא עדים לפטור עצמו מקבלים אותן שלא בפני בעל דין ורבינו כתב הדברים כמו שכתובים בגמרא ואין בדבריו הכרע והא דמקיימין השטר שלא בפני בעל דין פירשה רש\\\"י ז\\\"ל דמיירי בגוונא דההיא דלעיל דהיינו כגון שהיה הוא חולה או עדיו חולים וכו' הא לאו הכי אין מקיימין אבל דעת התוספות והרא\\\"ש ז\\\"ל כדעת רבינו לומר דאפילו בדליכא חדא מהני גווני מקיימין והיינו טעמא דכיון דקיום שטרות דרבנן משום דעדים החתומים על השטר נעשה כמי שנחקרה עדותן בבית דין לא החמירו חכמים בו כמו בקבלת עדות שהוא של תורה דבעינן בפני בעל דין ואם יש לו עדים שיעידו שהוא מזוייף או שיעידו שהעדים פסולים היו קודם שחתמו בשטר יפסול ואין מבטלין השטר וקיומו:\",1,0],[8,388,3,12,\"כל מי שיש לו ראיה בעדים וכו'. מההיא דמרי בר איסק (בכתובות דף כ\\\"ז:) שהבאתי לעיל בפ' זה אגב גררא דאמר ליה רב חסדא לאיתויי סהדי וא\\\"ל איהו דינא הכי המע\\\"ה ואמר ליה הכי דאיננא לך ולכל אלמי דחברך וכתבו התוספות דהכא ב\\\"ע שאמרו לו אותם עדים לא נאמר לך דבר על עדות זו שרגלים לדבר דמסתפו מיניה ומש\\\"ה אמר ליה אייתינהו את ויעידוך שאינו בן אביך או שאין יודעים לך עדות וקאמר אי מסתפו מיניה השתא נמי מסהדי שיקרא או שאינו אחיו או שאין יודעים לו עדות ומשני תרתי לא עבדי חדא שישתקו מלהעיד וחדא שישקרו ויאמרו אין אנו יודעים שהוא אחיו ולפי זה אם אמרו אין אנו יודעים היה מרי בר איסק פטור והכריחם לפרש כן משום דאל\\\"כ לא שבקת חיי דכל אדם שיהיה חייב לחבירו עשיר יאמר עליו שהוא אלמא ואם לא יביא עדים יפסיד אבל מדברי רש\\\"י נראה שאע\\\"פ שהיו אומרים אין אנו יודעים היה מרי בר איסק חייב דאיכא למימר דמסתפו מיניה עד שיעידו כדבריו שכן פירש בהמפקיד (דף ל\\\"ט:) זיל אנת אייתי סהדי דלאו אחוך הוא אותם עדים שיש לו לזה שבאו משם ומכירים בו מי הוא הביאם אתה ויעידו שאינו בן אביך או בקש עדים אחרים א\\\"ל מרי לרב חסדא אי מינאי דחלי מה הועלת סוף סוף אתו סהדי ולא מסהדי אלא כמותי ולא כמותך. תרתי לא עבדי מיראתך יעשו אחת שישתקו אבל שתים לא יעשו לא דיין שישתקו ולא יעידו האמת אלא גם שיעידו שקר עכ\\\"ל. הרי מפורש בדבריו שלא היה מרי בר איסק נפטר עד שהיו מעידים העדים כדבריו לפ\\\"ז אפשר לומר שאפילו אין רגלים לדבר שלא אמרו העדים לא נאמר לך דבר מעדות זו אלא שטוען התובע שבעל דינו אלם ויראים העדים ממנו נחייב לאלם שיביאם הוא ומה שהקשו התוס' דא\\\"כ לא שבקת חיי וכו' אפשר לומר שאין זה דבר המסור לטענת בעל דין לבד אלא גם לראות עיני ב\\\"ד אם הוא אלם כדי שייראו העדים ממנו אם לאו ואפשר שדעת רבינו כן\",1,0],[8,388,3,12,\"שכתב ואם ידעו ב\\\"ד שבעל דינו אלם וטען התובע שהעדים מפחדים וכו' כלומר דתרתי בעינן שידעו ב\\\"ד שהוא אלם ושיטעון התובע שהעדים מפחדים ממנו ואם תאמר סוף סוף לא שבקת חיי לאלמי שמאחר שמוחזק באלם יטעון בעל דינו שהעדים יראים ממנו ונמצא האלם מפסיד כל אשר לו יש לומר דכיון דאלמי נינהו יפסידו כל אשר להם וכה\\\"ג דיינינן להו עד שישובו בתשובה ויהיו כשאר כל אדם ואז דיינינן להו כשאר אינשי:\",2,0],[8,388,4,1,\"עדי נפשות צריכין שיהיו שניהם רואין וכו' עד לפיכך אם נמצאת כת אחת מהן זוממין וכו' שהרי הוא נהרג בעדות הכת השניה. בפ\\\"ק דמכות (דף ו':) היו שנים רואים אותו מחלון זה ושנים רואים אותו מחלון זה ואחד מתרה בו באמצע בזמן שמקצתם רואים אלו את אלו הרי אלו עדות אחת כלומר וכל עוד שלא הוזמו כולן אין נהרגין ואם לאו הרי אלו שתי עדיות לפיכך אם נמצא אחת מהם זוממין הוא והן נהרגין והשניה פטורה פירוש ההורג נהרג בעדות כת שניה שלא הוזמה והכת שהוזמה נהרגת ע\\\"פ המזימין ואם הוזמה כת שניה אחר שנהרג הרוצח פטורה היא דהא קי\\\"ל הרגו אין נהרגין ואמרינן בגמ' משמיה דרב דעדות מיוחדת פירוש אחד רואהו מחלון זה ואחד מחלון זה ואינם רואים זה את זה פסולה ותניא נמי הכי לא יומת על פי עד אחד להביא שנים שרואים אותו אחד מחלון זה ואחד מחלון זה ואין רואים זה את זה שאין מצטרפין ולא עוד אלא אפילו בזה אחר זה בחלון אחד אין מצטרפין אמר ליה רב פפא לאביי השתא ומה אחד מחלון זה ואחד מחלון זה דהאי קא חזי כולי מעשה והאי קא חזי כולי מעשה אמרת לא מצטרפי בזה אחר זה דהאי חזא פלגא דמעשה והאי חזא פלגא דמעשה מיבעיא אמר ליה לא נצרכה אלא לבועל את הערוה שכמה שרואה כל אחד די ואפי' הכי לא מצטרפי ולכך כתב\",1,0],[8,388,4,1,\"רבינו שראהו זה שעשה מלאכה בשבת כלומר שאף ע\\\"פ שיש די בראיית כל אחד לא מצטרפי ואמרינן תו בגמ' אמר רבא אם היו רואים את המתרה או המתרה רואה אותן מצטרפין כך היא גירסת ספרינו אבל מדברי רבינו נראה שהיה גורס היו רואים את המתרה והמתרה רואה אותן מצטרפין וכך הוא גירסת סמ\\\"ג.\",2,0],[8,388,4,1,\"ומ״ש צריכין להעיד כאחד ובב״ד אחד אפשר שהוציאו מדאמרינן בפרק זה בורר (סנהדרין דף ל') ר' נתן אומר (בדיני ממונות) שומעין דבריו של זה היום וכשיבא חבירו למחר (שומעין את דבריו) משמע דבדיני נפשות כולי עלמא מודו דצריכים להעיד כאחד. ומכל מקום נראה לי דגירסת רבינו כך וצריכים להעיד כאחד בבית דין אחד בלא וא״ו ולא כספרינו שכתוב ובבית דין בוא״ו דכיון דמעידים כאחד משום דמקישין הגדה לראיה פשיטא דהוי בבית דין אחד דדוחק לומר דאתו לאפוקי שלא יהיו שני בתי דינין בבית אחד והם שומעים דבריהם כאחד. אחר כך נתיישבתי בדבר ונראה לי לקיים הנוסחא דאתא לאפוקי ממה שכתב לקמן וכן אם העידו שני העדים בבית דין זה וחזרו והעידו בבית דין אחר יבא אחד מכל ב״ד ויצטרפו וס״ל לרבינו דהיינו בדיני ממונות אבל בדיני נפשות לא יבא אחד מכל ב״ד ויצטרפו אלא צריך מלבד שצריך שיעידו שני העדים כאחד עוד צריך שאותם שלשה ועשרים שהיו ביחד כששמעו דברי שני העדים שידונו אותם לא שיצטרפו קצת מב״ד זה וקצת מב״ד זה וידונו אותם וסוגיא דשמעתא מוכחא דבדיני ממונות עסקינן דאמרינן (בבא בתרא דף קס״ה:) אליבא דר' נתן לא תיבעי לך וכו' והא ר״נ ות״ק לא איירו אלא בד״מ כמו שיתבאר:\",3,0],[8,388,4,2,\"אבל בדיני ממונות אף על פי שלא ראו אלו את אלו וכו'. סנהדרין פרק זה בורר (סנהדרין דף ל') תניא אין עדותן מצטרפת עד שיראו שניהם כאחד רבי יהושע בן קרחא אומר אפי' בזה אחר זה ואמרינן התם דהלכה כרבי יהושע בן קרחא. וכתב סמ״ג אמנם בפרק השולח משמע דרב אשי סובר כרבנן שמקשה מדבריהם על מחלוקת רבי ורבן שמעון בן גמליאל עד כאן לשונו. ואני אומר שרב אשי לא אמר כן אלא בני הישיבה אמרו על דברי רב אשי הכי נמי מסתברא ונדחו דדילמא כריב״ק ס״ל וא״כ לא משמע מהכא דרב אשי סבר כרבנן ואפי' אי הוה משמע דסבר כרבנן לא הוה שבקינן פסק מפורש דאתמר הכא דהוא דוכתיה משום דיוקא דדוכתא אחרינא ואין לפקפק בזה:\",1,0],[8,388,4,3,\"וכן אם אמר האחד בפני הלוהו וכו'. שם בפלוגתא דאמוראי ואמרינן בסיפא דמילתא נהרדעי אמרי בין הודאה אחר הודאה בין הודאה אחר הלואה בין הלואה אחר הלואה בין הלואה אחר הודאה מצטרפין כמאן כר' יהושע בן קרחא ורב דאמר הודאה אחר הלואה הלואה אחר הודאה לא מצטרפי הא איפריך ונראה מלשון רבינו שכתב והשני שהעיד אחר זמן דמשמע העדות היה אחר זמן עדות חבירו אבל הראיה שהלוהו קודם לו היתה שאם עד הודאה אומר שקדם זמן שהודה לו לזמן שאומר העד שהלוהו אין מצטרפין דאמנה דמסהיד האי לא מסהיד האי וק\\\"ל מהא דלעיל ואף על גב דבאחד אומר דמי חבית של יין ואחד אומר דמי חבית של שמן שמצטרפין התם איכא למימר דאמנה חד הוא דמסהדי אלא שהעדים עשויין לטעות בין דמי חבית של יין לדמי חבית של שמן אבל הכא אין אדם עשוי להודות קודם שילוה וכיון שעד אחד אומר שלוה ביום פלוני ועד זה אומר שהודה מקודם הא ודאי שיקרא קאמר. ודע דבהלואה אחר הלואה כתבו האחרונים והביאו הרא\\\"ש בפסקיו דהא דמצטרפין היינו כשזה תובע שני מנים אחד מניסן ואחד מתשרי ויש לו עד אחד על כל אחד מהמנים שאין ביניהם הכחשה אבל אם אינו תובע אלא מנה אחד והם מעידים על שני מנים על כרחך אחד מהם שקר לפי דברי התובע והוא נאמן על עצמו:\",1,0],[8,388,4,4,\"וכן בעת שמעידין בב\\\"ד וכו'. ג\\\"ז שם ואין עדותן מצטרפת עד שיעידו שניהם כאחד רבי נתן אומר שומעין דבריו של זה היום וכשיבא חבירו למחר שומעין דבריו ואמרי' התם דמודה רבי יהושע בן קרחא לרבי נתן וא\\\"כ כיון דקי\\\"ל כר\\\"י בן קרחה ממילא הויא לה הלכה כרבי נתן ועוד דהתם באותו פרק גמ' גמרו את הדבר מכניסין אותן וכו' דחיקנא לאוקומי מתניתין כר' נתן אלמא כוותיה קי\\\"ל ועוד דהא רשב\\\"ג דמתני' דכתובות פ\\\"ב (דף כ\\\"ז:) סובר כר' נתן כדאיתא התם וכן פסק הרי\\\"ף:\",1,0],[8,388,4,5,\"וכן אם היה עד אחד בכתב ועד אחד ע״פ וכו'. בתרא פרק גט פשוט (בבא בתרא דף קס״ה:) שלחו ליה חברייא לר' ירמיה עד אחד בכתב ועד אחד על פה אליבא דר' יהושע בן קרחה מהו שיצטרפו ושלח להו יצטרפו ומפרש רבינו שהנפקותא היא לשווייה עדות בשטר דאילו למלוה על פה כיון דמכשרינן הלואה אחר הודאה פשיטא דכשרים דמה לי שניהם ע״פ מה לי אחד בכתב ואחד על פה ופירוש ברור הוא ומדקדוק לשון רבינו שכתב שניהם מצטרפין לעשות המלוה בשטר ואינו יכול לומר פרעתי משמע דלא אמרינן שנעשית מלוה בשטר אלא לענין שלא יוכל לומר פרעתי אבל לא לטרוף לקוחות דאע״ג דסתם קנין לכתיבה עומד הני מילי כשנטל קנין בפני שנים אבל הכא שלא נטל קנין אלא בפני אחד לא. והטור כתב בסימן נ״א בשם רבינו שנעשה מלוה בשטר גמור ומה שכתבתי נראה יותר:\",1,0],[8,388,4,6,\"העיד האחד בב\\\"ד זה וכו'. שאלו שם לר' ירמיה אליבא דרבי נתן ושלח להו דמצטרפין:\",1,0],[8,388,4,6,\"וכן אם העידו שני העדים בב\\\"ד זה וכו'. גם זה שם שלחו ליה חברייא לר' ירמיה שנים שהעידו בב\\\"ד זה וחזרו והעידו בב\\\"ד זה מהו שיבא אחד מכל ב\\\"ד ויצטרפו ושלח להו דמצטרפין ופי' רשב\\\"ם שנים שהעידו בב\\\"ד על חתימת יד שני עדים והלכו להם שנים מאותם ג' ב\\\"ד למדה\\\"י דהשתא לא מצו הוו חד ב\\\"ד וחזרו והעידו בב\\\"ד אחר והלכו להם שנים וחזרו העדים בב\\\"ד אחר והלכו שנים ונשתייר אחד מכל ב\\\"ד וב\\\"ד מהו שיבא אותו אחד שנשתייר מכל בית דין ובית דין דהויין שלשה ב\\\"ד ויצטרפו שלשה לקיים השטר בעדותן עד כאן לשונו.\",2,0],[8,388,4,6,\"ומ\\\"ש אבל העד עם הדיין שהעידו שני העדים בפניו אין מצטרפין. בכתובות פ\\\"ב ומפרשים התם טעמא משום דמאי דמסהיד סהדא לא אסהיד דיינא ומאי דמסהיד דיינא לא מסהיד סהדא פירוש שהעד מעיד על ההודאה או על הלואה והדיין מעיד שהעידו בפניו שהודאה או הלואה זו אמת או שקיימו השטר בפניו. וה\\\"ר שלמה בר\\\"ש בר צמח ז\\\"ל כתב בתשובה על זה שכתב רבינו אבל עד ודיין שהעידו שני עדים בפניו אין מצטרפין שהמפרשים פירשו ההיא דפ\\\"ב דכתובות (דף כ\\\"א) בשטר שיש בו קיום ולא הכירו כ\\\"א עד אחד וחתימת דיין אחד שאין לצרף עדותן משום דאמאי דמסהיד האי לא מסהיד האי וע\\\"פ דרך זה למדו מכאן דקיום שטרות צריך קיום אבל הרי\\\"ף בפ' גט פשוט פירש בדרך אחר כגון שיש עד בהלואה זו ודיין אחד מעיד שבמושב ב\\\"ד של ג' שהיה הוא אחד מהם באו שני עדים והעידו שזה חייב לזה מנה שאין לצרף עדותן דמאי דמסהיד סהדא לא מסהיד דיינא משמע מפירושו ז\\\"ל דדוקא בעדות ע\\\"פ היא זו ולא בקיום השטר אבל אם היה השטר מקויים שוב אינו צריך קיום והרמב\\\"ם כתבה ע\\\"פ דרכו של הרי\\\"ף א\\\"כ הרי גילה דעתו כאן הרמב\\\"ם שאין קיום ב\\\"ד צריך קיום לפי שהוא בשיטת הרי\\\"ף רבו אמרה ומ\\\"מ כתב דלענין מעשה כיון שר\\\"ח והרמב\\\"ן והרשב\\\"א ז\\\"ל סוברים דמעשה ב\\\"ד צריך קיום הכי נקטינן לענין ממון להקל על הנתבע וכל היכא דאיכא פלוגתא דרבוותא נקטינן הכי להקל על הנתבע כמו שכתבו המפרשים בפ\\\"ק דע\\\"ז וכ\\\"כ הרמב\\\"ן והר\\\"ן בפ' אלו טרפות עכ\\\"ל:\",3,0],[8,388,4,7,\"אע״פ שמצטרפין העדות בדיני ממונות וכו'. בבא קמא פרק מרובה (בבא קמא דף ע':) ובבא בתרא פ' חזקת (בבא בתרא דף נ״ו:) אמרי דרבנן דרשי יקום דבר ולא חצי דבר למעוטי שנים אומרים שערה אחת בגבה ואחת בכריסה ומפרש רבינו גבה וכריסה צד ימין וצד שמאל ואמרינן נמי התם דאחד אומר אחת בגבה ואחד אומר אחת בכריסה הוי חצי דבר וחצי עדות וה״ה לאחד מעיד שאכלה שנה אחת ואחד מעיד שאכלה שנה שנייה ואחד מעיד שאכלה שנה ג' אבל היו שנים מעידים על שנה אחת ושנים על שנה שניה ושנים על שנה ג' משנה שלימה היא בפ' חזקת הבתים דמצטרפין וא״ת מ״ש משנים אומרים אחת בגבה ושנים אומרים אחת בכריסה ותירץ הרי״ף משום דגבי שלש שנים מגו דמהני סהדותייהו לענין פירות שאכל בשנה ראשונה שחייב לשלם אם לא ימצא עדים יותר מהני להיכא דמצא עדים יותר והוא חזקה והתוס' תירצו דגבי ג' שנים ראו כל מה שהיו יכולים לראות באותה שנה. ומכל מקום מה שכתב\",1,0],[8,388,4,7,\"רבינו אבל אם העידה האחת שראתה שתי שערות בצד ימין והעידה שניה וכו' קשיא למאי נפקא מינה דמצטרפין הא כל כת מהן מעידים על דבר שלם ומה הם צריכים לכת השניה דאין לומר דלא סגי בשתי שערות בגבה או בכריסה עד שיהיו שתי שערות בשני המקומות. ולכן אני אומר שהנסחא האמיתית בדברי רבינו היא כמו שמצאתי בספר ישן וז\\\"ל אבל אם העיד האחד שראה שתי שערות בצד ימין והעד השני שראה שתי שערות בצד שמאל מצטרפין וכן כל כיוצא בזה עכ\\\"ל כך היא נוסחת דפוס וויניציא. ועכ\\\"ז צריך עיון מנא לן דמצטרפין הא הויא לה עדות מיוחדת ונהי דלדיני ממונות כשר לדיני נפשות פסול כדאיתא פרק קמא דמכות ונתבאר בראש פרק זה ודין זה דשתי שערות בדיני נפשות שייך דהיינו לענין עונשין ולענין גיטין וקדושין א\\\"כ אמאי מצטרפין. ונ\\\"ל דנ\\\"מ לענין אי חשבינן ליה כגדול לענין מקח וממכר או לענין אם עדותו עדות אבל לענין דיני נפשות בעינן ששני העדים יראו השתי שערות עצמם שבצד אחד שראה חבירו והכי מוכח לשון רבינו דבדיני ממונות עסיק שתחלת דבריו אע\\\"פ שמצטרפין העדים בדיני ממונות ולמד רבינו כן מכיון דקי\\\"ל דעדותן מצטרפין אע\\\"ג דאמאי דמסהיד האי לא מסהיד האי כמו שנתבאר:\",2,0],[8,388,5,1,\"אין חותכין דין מן הדינין וכו'. פשוט בהרבה מקומות בגמרא מהם שבועות פרק שבועות הדיינין לא יקום עד אחד באיש (אין לי אלא בדיני נפשות בדיני ממונות מנין ת\\\"ל לכל חטאת):\",1,0],[8,388,5,2,\"בשני מקומות האמינה תורה עד אחד בסוטה וכו'. משנה פ' מי שקנא לה (דף ל\\\"א) אמר עד אחד אני ראיתיה שנטמאת לא היתה שותה:\",1,0],[8,388,5,2,\"ובעגלה ערופה וכו'. פרק בתרא דסוטה (דף מ\\\"ז) עד אומר ראיתי את ההורג ועד אומר לא ראית היו עורפין ואמרינן בגמ' דאי לא הוה מכחיש ליה הוה מהימן ומייתי לה מקרא:\",2,0],[8,388,5,2,\"וכן מדבריהם בעדות אשה וכו'. יבמות פרק האשה שלום (יבמות דף קי״ז:) משנה עד אחד אומר מת ונשאת ובא אחר ואמר לא מת הרי זו לא תצא ופירש בגמ' דה״ק עד אומר מת והתירוה לינשא ובא אחר ואמר לא מת לא תצא מהיתרה הראשון אלמא דע״פ עד אחד מתירין אותה ובהדיא תנן בסוף שהוחזקו להיות משיאין ע״פ עד אחד:\",3,0],[8,388,5,3,\"ומ\\\"ש וכל מקום שעד אחד מועיל אשה ופסול כמו כן מעידים. בסוף יבמות (דף קכ\\\"ב) תנן שהוחזקו להיות משיאים ע\\\"פ ע\\\"א ע\\\"פ עבד או ע\\\"פ שפחה ובפרק בתרא דסוטה (דף מ\\\"ז) תנן אשה אומרת ראיתי את ההורג ואשה אומרת לא ראית היו עורפין והא אוקמוה דאילו לא הוות מכחשא לה לא היו עורפין:\",1,0],[8,388,5,3,\"חוץ מעד אחד של שבועה וכו'. איני יודע מהיכן הוציא רבינו דין זה אם לא מדאמרינן לכל עון ולכל חטאת אינו קם אבל קם הוא לשבועה משמע דבראוי לעדות עון וחטאת בצירוף אחר עסקינן:\",2,0],[8,388,5,3,\"ע\\\"פ שנים עדים וכו' עד או כשחטף חפץ מידו. משנה פ\\\"ק דמכות (דף ה:) קרובה ללשון רבינו:\",3,0],[8,388,5,3,\"ומ\\\"ש בין בדיני ממונות בין בדיני נפשות. באותה משנה סובר רבי כך ור' יוסי פליג עליה ופסק שמואל כר' יוסי ור\\\"נ כרבי וידוע דהלכתא כוותיה בדיני ואע\\\"ג דשמואל רביה הוה מ\\\"מ הלכה כר\\\"נ דהא רבינא דהוא בתרא מוקי בפ\\\"ק דסנהדרין (דף ט':) ר\\\"מ כרבי יוסי ורבנן כרבי אלמא הלכה כרבי ס\\\"ל:\",4,0],[8,388,5,5,\"וכיצד בודקין את הדבר וכו'. שם (דף ו') היכי אמרינן להו פירוש לקרוב ופסול למבדקינהו אם מתחלה לעדות נתכוונו למיחזי אתיתו או לאסהודי אתיתו אי אמרי לאסהודי אתו נמצא אחד מהם קרוב או פסול עדותן בטלה אי אמרי למחזי אתו מה יעשו שני אחים שראו באחד שהרג את הנפש ודעת רבינו לפרשה כפשטה דהיינו דאמרינן להו מתחלה כשראיתם העדות נתכוונתם להעיד או לראות הדבר וכפירש\\\"י ורשב\\\"ם.\",1,0],[8,388,5,5,\"ומ\\\"ש במה דברים אמורים ופה יש חסרון לשון בספר הדפוס וכ\\\"כ בספר מוגה אם נמצא באלו שנתכוונו להעיד קרוב או פסול עדותן כולה בטלה בד\\\"א כשהיה בהן קרוב או פסול אבל אם כולם כשרים אחד שנתכוון להעיד או שלא נתכוון להעיד וראה הדבר וכיון עדותו והיה שם התראה חותכין הדין על פיו בין בדיני ממונות בין בדיני נפשות, וכן דעת הרא\\\"ש בתשובה:\",2,0],[8,388,5,6,\"שטר שהיו עדיו מרובים וכו'. דעת רבינו בזה כדעת הרי״ף בשם גאון פ״ק דמכות (דף ו') ופרק ב' דגיטין (דף י״ח:) אמרינן חתום בתחילה פי' בשנים הראשונים קרוב או פסול אמרי לה כשר דתנאי הוא ואמרי לה פסול משום דאתי לאחלופי בקיום שטרות דעלמא ופסק רבינו בפ' תשיעי מהל' גירושין כלישנא בתרא דפסול ונתן ז״ל שם טעם למה בשטרות פסול ובגיטין היה כשר אילולי שגזרו משום שאר שטרות משום דבגיטין עיקר הדבר בהם עדי מסירה שאפילו חתום בעדים צריך ליתנו לה בפני עדים וכיון דאיכא עדי מסירה לא נחוש לעדי חתימה אבל השטרות אע״פ שכשרים בעדי מסירה מכל מקום אין כ״כ עיקר בהם עדי מסירה כמו בגיטין והא דתניא בבתרא ריש פ' גט פשוט (בבא בתרא דף קס״ב:) היו ארבעה או חמשה חתומים על השטר ונמצאו שנים הראשונים קרובים או פסולים תתקיים העדות בשאר מפרשה רבינו כשאין שם עדים שישבו כלם לחתום וההיא דגיטין בשיש עדים שישבו כלם לחתום וסובר רבינו דשנים ראשונים לרבותא נקטיה אע״פ שנראה יותר שהם עיקר העדות וכל שכן אם נמצאו אמצעים או אחרונים קרובים או פסולים דתתקיים העדות בשאר. ואם תאמר כיון דלא פסלינן בגיטין משום שאר שטרות אלא כשהפסול חתום בתחלה משמע דבאמצע או בסוף כשר בין בגיטין בין בשאר שטרות ואם כן כך היה לו לרבינו לכתוב שטר שהיו עדיו מרובין ונמצא אחד משנים הראשונים קרוב או פסול יש לומר דלעולם בשטרות בין בתחלה בין באמצע בין בסוף פסולים אם ישבו כולם לחתום אבל בגיטין כיון דמשום גזירה דשטרות הוא דוקא כשחתומים בתחלה פסלינן להו משום דאתו לאחלופי שנראה שהם היו עיקר החתימה אבל כשהם באמצע או בסוף מימר אמרי שנים הראשונים חתמו לשם עדים והשאר למלויי בעלמא ולא אתו לאיחלופי ואע״ג דקי״ל עדים החתומים על השטר כמי שנחקרה עדותן בב״ד דמי ואם כתב ידם יוצא ממקום אחר אינן נאמנין לומר אנוסים היינו הכא אם היו קיימים היו נאמנים לומר אם כולם ישבו לחתום אם לאו משום דאתרע שטרא שחתומים בו קרובים או פסולים:\",1,0],[8,388,5,8,\"כל עד שהעיד בדיני נפשות וכו'. פרק היו בודקין תנן אמר אחד מן העדים יש לי ללמד עליו זכות וכו' משתקין אותו ובפרק אחד דיני ממונות (סנהדרין דף ל״ג:) דרשי ליה מועד אחד לא יענה בנפש למות ומשמע לרבינו ששיעור הכתוב כך הוא ועד המעיד למות לא יענה בנפש ואפשר דבשום מקום דרשו ליה הכי ואף על גב דשיעור הכתוב כך הוא סוף סוף אייתר למות דמועד לא יענה בנפש שמעינן דבדיני נפשות איירי דוקא ולמות אייתר לכדתניא התם מנין לאחד מן התלמידים שאמר יש לי ללמד עליו זכות שומעין לו ואם אמר יש לי ללמד עליו חובה אין שומעין לו:\",1,0],[8,388,5,8,\"שאין עד נעשה דיין אפילו בדיני ממונות. בבא קמא פרק החובל (בבא קמא דף צ' ע״ב) אמרינן ההוא גברא דתקע לחבריה אתא לקמיה דרבי יהודה נשיאה אמר ליה הא אנא הא רבי יוסי הגלילי זיל הב ליה מנה צורי ושיילינן התם מאי הא אנא הא רבי יוסי הגלילי אילימא הא אנא דחזיתיך הא רבי יוסי הגלילי דאמר מנה צורי וכו' למימרא דעד נעשה דיין והתניא סנהדרין שראו אחד שהרג את הנפש מקצתם נעשים עדים ומקצתם נעשים דיינים דברי רבי טרפון רבי עקיבא אומר כלם עדים הם ואין עד נעשה דיין עד כאן לא קאמר רבי טרפון אלא דמקצתם נעשים עדים ומקצתם נעשים דיינים אבל עד נעשה דיין פירוש לדון על פי ראייתו לא קאמר כי תניא ההיא כגון שראהו בלילה פירש״י ולמחרת כשבאים לדין אין דנין אלא על פי שמועה לפיכך צריך למקצתו להעיד ואם אין שם אלא שלשה צריך להושיב אחרים ולהעיד בפניהם אבל ראו ביום עושין על פי הראיה לרבי טרפון מיד ורבי יהודה נשיאה כרבי טרפון סבירא ליה ואיבעית אימא הכי קאמר ליה הא אנא דסבירא לי כרבי יוסי הגלילי דאמר מנה צורי הא סהדי דמסהדי בך זיל הב ליה ומכיון שהביאו ראיה מפלוגתא דרבי טרפון ורבי עקיבא לההוא גברא דהוה חייב מנה צורי שמע מינה דלא שאני לן בין דיני נפשות לדיני ממונות דבכולהו אין עד נעשה דיין פירוש עד שהעיד כבר אבל אם לא העיד מעידין בפניו ודן אפילו בדיני נפשות וכרבי טרפון ופוסק רבינו כרבי טרפון אי משום דכי אמרינן הלכה כרבי עקיבא מחבירו אבל לא מרבו ורבי טרפון רבו היה וכמאן דאמר הכי בהכותב ועוד דלחד תירוצא רבי יהודה נשיאה כרבי טרפון סבירא ליה וכיון דקיימא לן כרבי טרפון לא תיקשי לן מההיא דבפרק שני דמכות שכתבו המפרשים דההיא רבי עקיבא אמרה אבל אנן דקיימא לן כרבי טרפון אפילו בדיני נפשות עד שראה ולא העיד דן וכמו שכתבתי והראיה שרבינו סובר דדוקא אם העיד אינו דן אבל אם לא העיד דן שכתב בתחלת הבבא כל דיין שהעיד בדיני נפשות וכו' אבל לא ימנה וכו' משמע דוקא העיד אבל לא העיד לא:\",2,0],[8,388,5,9,\"במה דברים אמורים בדבר שצריך עדים מן התורה וכו'. פרק שני דכתובות (דף כ\\\"א:) עד נעשה דיין בדרבנן ובפ\\\"ק דגיטין (דף ה':) בפני כמה נותנו רבי יוחנן אמר בפני שנים דסבר שליח נעשה עד ועד נעשה דיין:\",1,0],[8,388,6,1,\"כבר ביארנו שקיום שטרות מדבריהם וכו'. בסוף פרק שני דכתובות (דף כ\\\"ח) כיון דקיום שטרות מדרבנן הימנוה רבנן בדרבנן:\",1,0],[8,388,6,1,\"אף על פי כן אין מקיימין שטרות אלא בשלשה. מימרא דרב נחמן פרק חזקת הבתים (בבא בתרא דף ל״ט מ').\",2,0],[8,388,6,1,\"ומ\\\"ש ואפילו שלשתן הדיוטות פשוט דהא כתב רבינו בפ\\\"ה מהלכות סנהדרין דלהודאות והלואות סגי בשלשה הדיוטות.\",3,0],[8,388,6,1,\"ומ\\\"ש אין מקיימין שטרות בלילה. נתבאר בפ\\\"ג מהלכות סנהדרין:\",4,0],[8,388,6,2,\"באחד מחמשה דרכים וכו'. כל דרכי הקיום הם בכתובות בפרק שני (דף כ' כ\\\"א) ואמרינן התם ש\\\"מ דיינין המכירים חתימת ידי עדים אין צריכין להעיד בפניהם ואע\\\"ג דדחי התם רב אשי ואמר דילמא לעולם אימא לך צריכין לא שבקינן מאי דפשיטא ליה לגמרא משום דחיה דרב אשי וכן פסק הרי\\\"ף:\",1,0],[8,388,6,2,\"הדרך השני וכו'. זו בכלל הראשונה היא שאם כשמכירין חתימתן יכולים לקיים כ\\\"ש כשחתמו בפניהם:\",2,0],[8,388,6,2,\"הדרך השלישי. משנה שם (דף כ':) זה אומר זה כתב ידי וזה אומר זה כתב ידי צריכין שיצטרף עמהם אחר דברי רבי וחכמים אומרים אין צריכין שיצטרף עמהם אחר אלא נאמן אדם לומר זה כתב ידי וידוע שאין הלכה כרבי מחבריו:\",3,0],[8,388,6,2,\"הדרך הרביעי וכו'. בההוא פירקא בכמה דוכתי במשנה ובגמ' (דף כ\\\"ה) מהם אמר רב יהודה אמר רב שנים החתומים על השטר ומת אחד מהם צריכים שנים מן השוק להעיד עליו.\",4,0],[8,388,6,2,\"ומ\\\"ש רבינו שאם מתו או שהיו במדינה אחרת. אורחא דמילתא נקט שאם היו שם הם עצמם היו מעידים אבל אה\\\"נ שאם רצו לקיים השטר ע\\\"פ עדים אחרים אע\\\"פ שהם במדינה יכולים והראיה ממ\\\"ש רבינו פ\\\"ג עדים החתומים על השטר וכו' בד\\\"א כשאפשר לקיים השטר שלא מפיהם כגון שהיו שם עדים שזה כתב ידן ונתבאר בגמ' וכמ\\\"ש שם אלמא שאע\\\"פ שהם במדינה שהרי אומרים אנוסים היינו וכו' יכולים לקיים השטר ע\\\"פ עדים אחרים וכ\\\"ש היכא דלא אמרי מידי:\",5,0],[8,388,6,2,\"החמישי שיהיה כתב ידם יוצא ממקום אחר וכו'. משנה שם (דף י\\\"ח:) כתבתיה בפ\\\"ג העדים שאמרו כתב ידינו הוא אבל אנוסים היינו וכו' אם יש עדים שהוא כתב ידם או שהיה כתב ידם יוצא ממקום אחר אינן נאמנין פירוש במה שאמרו אנוסים היינו ואם אפי' כשאומרים אנוסים היינו בכתב ידם יוצא סגי כל שכן באינם אומרים:\",6,0],[8,388,6,3,\"אין מקיימין את השטר משטרות אחרים. כלומר היינו דוקא כשמקיימין אותו ע״י דמיון החתימה לחתימה אבל היכא דמקיימין החתימה בטביעות עין ליכא למיחש שמא זייף דאם איתא דזייף ניכר היה וכן כתבו התוספות (דף כ' בד״ה דילמא) וכתבו בסמ״ג וק״ל שהרי רבא טעה בחתימתו בפרק גט פשוט (בבא בתרא דף קס״ז) ואני אומר שאין זו קושיא דאנן הכי אמרינן דלא שכיח למטעי כשמקיים החתימה בטביעות עין וכשמקיימין ע״י דמיון חתימה לחתימה שכיח למיטעי ולישנא דגמרא הכי מוכח דלא עסקינן אלא במקיים מתוך שטר אחר דאמרינן בפרק שני דכתובות (דף כ') א״ר אסי אין מקיימין את השטר משטר שקראו עליו ערער אא״כ הוחזק בב״ד אמרי נהרדעי אין מקיימין את השטר אלא (משטר) שתי שדות או משתי כתובות והוא שאכלום שלש שנים ובשופי כלומר בלא ערעור (אמר רב שימי בר אשי) וביוצא מתחת ידי אחר אבל מתחת ידי עצמו לא חיישינן דילמא זיופי זייף זאת היא גירסת הרי״ף והיא גירסת רבינו כפי מ״ש הר״ן וה״פ דר' אסי אמר דשטר שקרא עליו ערער אע״פ ששתק הערער אין מקיימין ממנו אלא א״כ הוחזק בב״ד אבל כל שלא קרא עליו ערער אע״פ שלא הוחזק מקיימין ממנו ואתו נהרדעי לפרושי דכי אמרינן דמקיימין משטר שלא קרא עליו ערער אע״פ שלא הוחזק דוקא בשני שטרות של שתי שדות או שתי כתובות וכו' אבל משטר אחד שלא הוחזק אין מקיימין ונמצינו למדין דבין קרא עליו ערער או לא קרא אם הוא מוחזק בב״ד מקיימין ממנו ובשטר אחד סגי ואם לא הוחזק צריך שני שטרות משתי שדות שאכלום בעליהם שלש שנים בלא ערעור. ולהראב״ד גירסא אחרת וכלל סברתו דלעולם בעינן שני שטרות או שהוחזקו שניהם בב״ד או שאכלום בעליהן שלש שנים בלא ערעור אע״פ שהוחזק בב״ד אי לא קרא עליו ערער אין מקיימין ממנו דאין מקיימין אלא משטר אחד שהוחזק אחר שקרא עליו ערער או משני שטרות אפילו שלא הוחזקו אם אכלום בעליהם שלש שנים בלא ערעור ומה שאמרו נהרדעי שתי שדות או שתי כתובות היינו לאפוקי שטרי הודאות והלואות דאפשר דמזוייפות נינהו ולוה לא ידע בהו כלל אבל משתי שדות כיון שהלוקח אוכל פירותיהם והאחר לא ערער ליכא למיחש למידי וכן שתי כתובות כיון שנשים הללו יושבות תחת בעליהן ולא ידעינן שיש להן כתובות אחרות אלמא לאו שטרי זייפי נינהו. ודע דלרבינו שהטעם שאין מקיימין משטר שיוצא מתחת ידו דחיישינן שמא הוא זייף הכל אם השטר מקויים מקיימין ממנו ואפילו משטר אחד אבל לרש״י שפירש דחיישינן שמא נסתכל בכתב ידן של עדים וכיון וזייף השלישי אפילו אם הם מקויימין כיון שיוצאים מתחת ידו אין מקיימין מהם:\",1,0],[8,388,6,4,\"ב\\\"ד שכתבו במושב שלשה היינו וכו'. נ\\\"ל שהוציאו מדפרכינן בגמ' (דף כ\\\"א) לרב יהודה אמר שמואל דאמר הלכה כחכמים מההוא שטרא שנתקיים בבי דינא דמר שמואל והוה כתיב ביה מדאתא רב ענן ואסהיד אחתימת ידיה ואדחד דעמיה ומנו רב חנן ומדאתא רב חנן ואסהיד על חתימת ידיה ואדחד דעמיה ומנו רב ענן אשרנוהי וקיימנוהי כדחזי ואסיקנא דההוא שטרא דיתמי הוה וחש שמואל לב\\\"ד טועים וסבר שמואל דילמא איכא דס\\\"ל כרבי וכו' סבר אעביד רווחא כי היכי דלא מפסדי יתמי ונראה שמפרש רבינו שמן הדין לא היה צריך לכתוב הדרך שבה נתקיים אלא שחשש שמואל שמא הב\\\"ד שיבא לפניו שטר זה יאמר דילמא ב\\\"ד שקיימוהו טועים היו ולא אחזיקנו במקויים אחר שלא נתברר בו הדרך שבה נתקיים לכן כתב בו הדרך שבה נתקיים וסבר אם אכתוב כרבנן דילמא איכא דס\\\"ל הלכה כרבי וסובר רבינו דמדאמרי' וחש שמואל לב\\\"ד טועים חששא בעלמא היתה ולא מן הדין:\",1,0],[8,388,6,5,\"ולעולם אין ב״ד בודקין וכו'. פ' מצות חליצה (יבמות דף ק״ו) ובתרא סוף יש נוחלין (בבא בתרא דף קל״ח:) בי דינא בתר בי דינא לא דייקי בתר עדים דייקי:\",1,0],[8,388,6,6,\"שלשה שישבו לקיים את השטר וכו'. מימרא דר' זירא בפ\\\"ב דכתובות (דף כ\\\"ב) ג' שישבו לקיים את השטר ומת אחד מהם צריכין למכתב במותב תלתא כחדא הוינא וחד ליתוהי ואמר רב נחמן בר יצחק ואי כתיב ביה [שטרא דנן נפק לקדמנא] בי דינא תו לא צריך ודילמא ב\\\"ד חצוף הוא כשמואל דאמר דשנים שדנו דיניהם דין אלא שנקרא ב\\\"ד חצוף ואסיקנא דכתיב ביה ואמר לנא רבנא אשי (לאזדקוקי ליה ולקיומיה) וכו' דואמר לנא רבנא אשי תלתא נינהו ואע\\\"פ שלא נראה פירוש זה בעיני רש\\\"י מ\\\"מ כך נראה מדברי רבינו וכתב הר\\\"ן בשם הרא\\\"ה דחד ליתוהי לאו דוקא ולא גרע במותב תלתא מבי דינא ועיקר חידושא דרבי זירא דכיון דלא חתימי ביה אלא תרי צריכי למכתב תלתא דאילו הוו חתימי ביה תלתא לא הוה צריך אבל חד ליתוהי לא מעלה ולא מוריד:\",1,0],[8,388,6,7,\"שלשה שישבו לקיים את השטר וכו'. שם (דף כ\\\"א:) אמר רבי אבא אמר רב שלשה שישבו לקיים את השטר וקרא ערער על אחד מהם פירוש לומר שהוא פסול עד שלא חתמו מעידין עליו וחותם משחתמו אין מעידין עליו וחותם ואסיקנא דבערער דגזלנותא עסקינן וקאמרי הני ידעינן ביה דעבד תשובה אבל ערער דפגם משפחה גילוי מילתא בעלמא הוא כלומר ומעולם לא נפסל זה והרי שלשה היו אבל כשמעידים שעשה תשובה הרי פסול היה עד שעה זו שהעידו שעשה תשובה כך פירשו ר\\\"ח והרי\\\"ף שמועה זו גם רבינו נלוה עמם ומשמע מדבריהם שגזלן שעשה תשובה לא מתכשר אלא מעת שהעידו עליו בב\\\"ד שעשה תשובה ולשון רבינו שלא כתב אלא ערער משפחה להכשיר נוטה לדברי הרי\\\"ף שסובר דשנים אומרים לא גזל לא מחתמינן ליה ולא מפקינן ממונא אפומיה וכן כתב בפירוש בפי\\\"ב מאלו ההלכות ושלא כדברי ר\\\"ח שכתב דמוקמינן גברא אחזקתיה. ודע שרש\\\"י מפרש עד שלא חתמו מעידין חביריו על זה שהוא כשר משחתמו אין מעידין עליו דנוגעים בעדות נינהו שגנאי להם שישבו עם פסול בדין:\",1,0],[8,388,6,8,\"מותר לכתוב הקיום בשטר וכו'. בכתובות פ' הכותב (כתובות דף פ״ה) אמר רב פפי וכו' האי אשרתא דדייני פירוש קיום השטר דמיכתבא מקמי דנחוו סהדי אחתימות ידייהו פסולה משום דמיחזי כשיקרא ואסיקנא התם דליתא אלא כתבינן לה דלמיחזי כשיקרא לא חיישינן ואע״ג דפ״ב דכתובות (דף כ״א:) מותבינן מדרב פפי דרך הגמ' להקשות אפי' מדבר דלא הוי הלכתא הכי:\",1,0],[8,388,6,8,\"ואין הדיינים צריכים לקרות השטר וכו'. כתובות פ' שני דייני גזילות (דף ק\\\"ט) תני ר' חייא אין העדים חותמים על השטר אא\\\"כ קראוהו אבל הדיינים חותמים אע\\\"פ שלא קראוהו וכתב הר\\\"ן דדוקא מה שיש בגוף השטר הוא דאין צריכין לקרות אבל מ\\\"מ צריכים הם לראות מי הם המלוה והלוה כדי שלא יהיו קרובים לדיינים ולא לעדים המעידים בפניהם אבל הרשב\\\"א מכשיר בעדי קיום קרובים לדייני קיום ולא נתחוורו דבריו להר\\\"ן בכתובות סוף פרק האשה שנתארמלה:\",2,0],[8,388,7,2,\"מעיד אדם על כתב קרובו וכו' ואלו מדברים שנאמנים הגדולים להעיד בגדלם מה שראו בקטנם. פ\\\"ב דכתובות משנה (דף כ\\\"ח) ואלו נאמנים להעיד בגדלן מה שראו בקטנן נאמן אדם לומר זה כתב ידו של אבא וזה כתב ידו של רבי וזה כתב ידו של אחי ואמרינן בגמ' והוא שיש גדול עמו כלומר מעיד עמו דכיון דקיום שטרות דרבנן הימנוה רבנן בדרבנן:\",1,0],[8,388,7,3,\"שטר שעדיו ראובן ושמעון וכו'. כתובות פ\\\"ב (דף י\\\"ט:) ת\\\"ר שנים שהיו חתומים על השטר ומתו ובאו שנים מן השוק ואמרו ידענו שכתב ידם הוא זה אבל אנוסים היו וכו' הרי אלו נאמנים הא אילו לא אמרו אנוסים היו בשנים שאמרו כתב ידם הוא סגי.\",1,0],[8,388,7,3,\"ומה שכתב אבל אם העיד זה על כתב ידי ראובן וכו'. נלמד מדאמרינן התם (דף כ\\\"א) אמר רב יהודה אמר רב שנים החתומים על השטר ומת אחד מהן צריכין שנים מן השוק להעיד עליו אלמא דלא סגי בחד.\",2,0],[8,388,7,3,\"ומ\\\"ש רבינו ואם יש שלישי מעיד על כתב ראובן וכו' פשוט הוא דכיון דשנים יכולים להעיד על חתימות ידי שנים הרי יש כאן שנים מעידים על שתי החתימות:\",3,0],[8,388,7,4,\"אמר הראשון זה כתב ידי וכו'. שם אליבא דרבנן וקי\\\"ל כוותייהו עדים המעידים על חתימת עצמן על מנה שבשטר הם מעידים כלומר שהם כאילו אומרים אנו ראינו המלוה וחתמנו וא\\\"כ כשזה אומר זה כתב ידי יוצא על פיו חצי הממון שאותו המעיד עמו אינו מעלה ואינו מוריד שהרי הוא לבדו נאמן על חתימתו וכשנצטרף עם האחר להעיד על חתימת חבירו חוזר ויוצא רביע הממון על פיו נמצאו שלשת רבעי הממון יוצאין על פי עד אחד ואנן על פי שנים עדים בעינן חצי דבר על פיו של זה וחציו על פיו של זה.\",1,0],[8,388,7,4,\"ומ״ש וכן אם העיד אחיו או בנו וכו' מעשה בפרק חזקת הבתים (בבא בתרא דף נ״ז) ופסק כן רב אשי מהטעם שכתב רבינו:\",2,0],[8,388,7,5,\"שנים שחתומים על השטר ומת אחד מהן וכו'. מימרא דרב יהודה אמר רב שכתבתי בסמוך:\",1,0],[8,388,7,5,\"ומ\\\"ש ואם לא נמצא אלא עד אחד. שם ואי ליכא אלא חד אמר אביי לכתוב חתימת ידיה אחספא ושדי ליה בבי דינא ומקיימי ליה ולא צריך איהו לאסהודי אחתימת ידיה ואזיל איהו והאי ומסהדי אאידך ופירש רבינו לכתוב חתימת ידיה אחספא בפני עדים והדין עמו דאל\\\"כ היאך יכירו שזאת חתימת ידו לשיקיימו השטר ממנו:\",2,0],[8,388,7,6,\"שלשה שישבו לקיים את השטר וכו'. שם (דף כ\\\"א:) מימרא דרב הונא כלשון רבינו ואע\\\"ג דלקבלת עדות בעינן שלשה ואלו השנים בעת שמעידין אין שם אלא דיין אחד אפילו הכי בדרבנן אפי' בשעה שמעידין נעשים דיינים:\",1,0],[8,388,7,7,\"שנים שהיו חתומים על השטר וכו'. ברייתא שם (דף י\\\"ט:) כלשון רבינו.\",1,0],[8,388,7,7,\"ומ\\\"ש אלא שמעידים השנים שבשטר וכו'. מסקנא דגמ' שם אוקי תרי להדי תרי ואוקי ממונא בחזקת מריה:\",2,0],[8,388,8,1,\"מי שחתם על השטר וכו'. למד רבינו דין זה ממה שאמרו בכתובות פ\\\"ב (דף כ') תנו רבנן כותב אדם עדותו על השטר ומעיד עליה אפילו לאחר כמה שנים אמר רב הונא והוא שזוכרה מעצמו ורבי יוחנן אמר אע\\\"פ שאינו זוכרה מעצמו ואמרו בירושלמי רב הונא כרבי דאמר עדים המעידים חתימתם צריכין לצרף עמהם אחר ור' יוחנן כרבנן דאמרי אין צריכין פירוש כשהעדים באים לקיים חתימתן אם זוכרים המלוה ולא השטר אפי' לרבי אין צריך לצרף עמהם אחר ועל מנה שבשטר הן מעידים וכשאין זוכרים המלוה אפי' על ידי השטר אפי' רבנן מודו דצריכין לצרף דאין מעידין אלא על כתב ידם וכי פליגי היינו כשזוכרים המלוה על ידי השטר דלרבנן חשיב זכירה ועל מנה הם מעידים ולרבי לא חשיב זכירה הרי דאליבא דכ\\\"ע כל שלא נזכר על ידי השטר אינו יכול להעיד וגם הרא\\\"ש כתב בפ' הנזכר שמתוך הירושלמי הזה משמע שאם העדים שכחו לגמרי המלוה דאף מתוך ראיית השטר אין זוכרים אותו מודו רבנן דצריכין לצרף עמהם אחר ואין ספק שמ\\\"ש רבינו הרי הן כחרשים וכו' דהיינו דוקא כל זמן שאין עדים אחרים שאם יש שם עד אחד שמעיד על שתי החתימות ודאי דמהני כדמשמע בירושלמי ובזה נסתלקה קושיית הראב\\\"ד:\",1,0],[8,388,8,2,\"אחד הזוכר את העדות וכו'. שם אמאי דאמר רבי יוחנן והוא שזוכרה מעצמו אמר רבא ש\\\"מ מדרבי יוחנן הני בי תרי דידעי סהדותא ומנשי חד מינייהו מדכר חד לחבריה אבעיא להו עצמו מאי ואסיקנא עצמו לא ואי צורבא מרבנן הוא אפי' עצמו ופירש\\\"י עצמו מאי אם בעל דין עצמו מזכירו עד שנזכר מאי ואי צורבא מרבנן הוא העד אפי' עצמו של בעל דין דצורבא מרבנן אי לאו דכי רמי אנפשיה מדכר שפיר לא הוה סמיך אספיקא למיקם ואסהודי אבל רבינו מפרש אי צורבא מרבנן הוא התובע וקשה דבשלמא לרש\\\"י כיון דהעד צורבא מרבנן אי לאו דרמא אנפשיה ואידכר לא הוה מסהיד אבל אם העד אינו תלמיד חכם אף אם התובע תלמיד חכם מאן לימא לן שהעד רמא אנפשיה ואידכר דילמא סמך על דברי התובע והנתבע יחשוב כך והטור כתב לשון זה בשם רבינו ובמקום התובע כתב בעל דין והשתא אפשר ליישבו דאנתבע קאמר שאם היה תלמיד חכם הוא יודע שאין העד מעיד אא\\\"כ זכר ולא יחשוד לעד שאינו זוכר:\",1,0],[8,388,8,3,\"וקל הוא שהקילו וכו'. נראה שיצא זה לרבינו מדאמרי' ביבמות פ' ד' אחין (יבמות דף ל״א:) מפני מה לא תקנו זמן בקידושין אמרינן היכי לינחיה גבי עדים אי דכירי ליתו ולסהדו ואי לא זמנין דחזו כתבא ואתו ומסהדי ורחמנא אמר מפיהם ולא מפי כתבם ומשמע ליה דאפי' בזוכרה ע״י הכתב עסקינן התם ומשני דהאי בדיני נפשות הוא דלא מהני ובדיני ממונות הקילו כמו שהקילו לדון דיני ממונות על פי השטר וכמבואר בדברי רבינו פ״ג מהלכות אלו:\",1,0],[8,388,8,4,\"הואיל והדבר כן וכו'. לעיל קאי שכתב שאין אדם מעיד על כתב ידו שהוא זה אלא על הממון הואיל וכן שטר שיצא לב\\\"ד וכו'. וכתב מהר\\\"י קולון בסוף שורש ע\\\"ד שכ\\\"כ בה\\\"ג משמיה דרב יהודאי סהדא דחתים על השטר ואמר אין חתימתי היא אי לא קים ליה ממאי דכתב מהימן ומקשו רבנן קמיה אלא מעתה האי שטרא דקא אתי מעלמא ואוקמו ליה בחתימת ידי סהדי דחתימי עליה היכי מוקמי ליה דילמא אי הוו סהדי הוו אמרי לא קים לן במאי דכתיב ביה והדר להו לכתחלה לא אמרינן אי אמרי אינהו דלא קים להו מהימני עכ\\\"ל:\",1,0],[8,388,8,4,\"והראב\\\"ד כתב על דברי רבינו א\\\"א יש מי שאין מורין כן וכו'. ואני אומר דאדרבה כי אמרי אמנה היו דברינו שבאים לסתור השטר אינם נאמנים אבל כשאומרים אין אנו זוכרים עדות זו כיון שאינם באים לסתור השטר איכא למימר אפומא דמאן בעית למיגבא האי מנה אפומא דהני סהדי הא לא דכירי וא\\\"כ אפומא דמאן מגבית להו:\",2,0],[8,388,8,5,\"אחד הכותב וכו'. רש\\\"י והרי\\\"ף פירשו ההיא (דף כ') דכותב אדם עדותו על השטר אם עשאוהו עד בדבר וירא לשוכחו כותבו על פנקסו ומצניעו ומעיד על פיו אפי' לאחר כמה שנים וסובר רבינו דבין היתה אותה כתיבה בשטר או על פנקסו כיון שנזכר אחר שראה הכתב מעיד עליה ואם לא נזכר אע\\\"פ שהעדות כתובה בשטר אינו מעיד עליה ולדידיה לישנא דברייתא דייקא דקתני כותב אדם עדותו על השטר דהיינו שטר ממש ובשאין כתב ידו יוצא ממקום אחר ואין עדים מצויים לקיימו והוא הדין אם נמצא כתוב בפנקסו ונזכר שמעיד אפילו אחר כמה שנים וכו':\",1,0],[8,388,8,5,\"וכתב הראב\\\"ד אחד הכותב עדותו על השטר א\\\"א זה אינו ואחר זה כתב א\\\"א אפשר לקיימו וכו'. ואזדא לטעמיה שכתב קודם זה העדים החתומים על השטר אע\\\"פ שאינם זוכרים עדותם דנים על פי השטר וא\\\"כ אם היתה עדותו כתובה בשטר מה לנו ולזכירתו הא בלא זכירתו גובין בשטר לכך כתב א\\\"א זה אינו וחזר לבקש מציאות שיהא אפשר לקיימו וכתב על מ\\\"ש זה אפשר לקיימו וכו' יש לתמוה איך על ידי שיראה השטר יזכור שנצטווה לתתו למלוה ומפני כך כתב ואין הדעת נוחה בכל זה וכל זה על פי סברתו. אבל לדעת רבינו שאם אין עדי השטר זוכרים עדותם אין גובין על פי השטר אם אין שם עדי קיום כמו שנתבאר בסמוך שפיר שייך למימר אחד כותב עדותו על השטר שהרי צריכין אנו לזכירת העדים אף על פי שיש למלוה שטר:\",2,0],[8,388,9,1,\"עשרה מיני פסלות הם וכו'. פסול נשים ועבדים וקטנים בפרק החובל (בבא קמא דף פ\\\"ח) ובסוף פירקא קמא דראש השנה (דף כ\\\"ב) תנן גבי פסולים לעדות דמני התם כל עדות שאין האשה כשרה לה אף הם אין כשרים לה ובפרק שבועת העדות (שבועות דף ל') יליף מקרא דנשים פסולות לעדות בגיטין פרק ב' (דף כ\\\"ג) משנה הכל כשרים להביא את הגט חוץ מחרש שוטה וקטן וסומא ועכו\\\"ם.\",1,0],[8,388,9,1,\"ומ\\\"ש והרשעים. בפרק זה בורר (סנהדרין דף כ\\\"ד:) תנן אלו הן הפסולים המשחק בקוביא ומלוי ברבית ומפריחי יונים וסוחרי שביעית.\",2,0],[8,388,9,1,\"ומ\\\"ש והבזויין. בסוף פירקא קמא דקידושין (דף מ':) אמרו האוכל בשוק וכו' ויש אומרים פסול לעדות אמר רב אידי בר אבין והלכה כיש אומרים.\",3,0],[8,388,9,1,\"ומ\\\"ש והקרובים. בפרק זה בורר (סנהדרין דף נ\\\"ג).\",4,0],[8,388,9,1,\"ומ״ש והנוגעים בעדותן. פרק חזקת הבתים (בבא בתרא דף מ״ב מ״ג) פרכינן דאמר השותפין מעידים זה על זה אמאי נוגעים בעדותן הם:\",5,0],[8,388,9,2,\"הנשים פסולות לעדות וכו'. בפרק שבועת העדות (שבועות דף ל') אמרינן ועמדו שני האנשים בעדים הכתוב מדבר כלומר ללמד שאין עדות בנשים ובסיפרי ועמדו שני האנשים נאמר כאן שני ונאמר בעדות על פי שנים עדים מה כאן אנשים אף להלן אנשים מכאן שאין האשה כשרה להעיד. ואיני יודע למה הניח רבינו מלכתוב ראיה זו. והראיה שהביא אינה נוחה לי שהרי כל התורה בלשון זכר נאמרה:\",1,0],[8,388,9,3,\"ואין מוציאין ממון מספק וכו'. מוסכם בכל הגמ' דמספיקא לא מפקינן ממונא וכ\\\"ש דאין עונשין:\",1,0],[8,388,9,4,\"העבדים פסולים וכו'. בפ' החובל (בבא קמא דף פ״ח) מייתי לה מגזלן וקטן או אשה בהצד השוה ואיכא מאן דמייתי לה מדרשה דלא יומתו ודרשה זו שכתב רבינו ליתא התם וצ״ע היכא איתא:\",1,0],[8,388,9,5,\"מי שחציו עבד. זה דבר פשוט דכיון דחציו אינו כשר פסול הוא:\",1,0],[8,388,9,6,\"כל מי שנשתחרר וכו'. גיטין פרק השולח (גיטין דף ל״ט) אמר עולא אמר ר' יוחנן המפקיר עבדו יצא לחירות וצריך גט שחרור כלומר יצא לחירות משום דזכה בעצמו וצריך גט שחרור להתירו בבת ישראל וא״כ כיון דאינו בן ברית גמור אין ראוי להעיד:\",1,0],[8,388,9,7,\"הקטנים פסולים וכו'. בבתרא פרק מי שמת (דף קכ\\\"ה:) אמרינן דפחות מבן שלש עשרה אין עדותו עדות משום דבעינן ועמדו שני האנשים וליכא:\",1,0],[8,388,9,7,\"ואם הגיע לעשרים שנה וכו'. למד כן ממה שאמרו בפ' יוצא דופן (נדה דף מ״ז) נתבאר בדברי רבינו פ״ב מהלכות אישות וסובר שהוא הדין לענין עדות:\",2,0],[8,388,9,8,\"קטן שהגיע לכלל שנותיו וכו'. דעת רבינו שיש לאיש סימנין מלמעלה וכתב בפ\\\"ב מהל' אישות והשיג עליו הראב\\\"ד וה\\\"ה הניח הדבר בצ\\\"ע:\",1,0],[8,388,9,8,\"ובן שלש עשרה וכו'. כתב רבינו ירוחם שכן כתוב בירושלמי ומפרש רבינו דהיינו כשהביא שתי שערות דאי לאו הכי דינו כקטן לכל מילי ובפ' מי שמת (בבא בתרא דף קנ״ה:) אמר רב הונא בריה דרב יהושע ולעדות עדותו עדות אמר מר זוטרא לא אמרן אלא במטלטלי אבל למקרקעי אין עדותן עדות וכתבו המפרשים דקאי אמאי דאמרינן התם לעיל מהאי מימרא דפחות מבן עשרים אע״פ שהוא בן י״ג שאינו בקי בטיב מקח וממכר אינו מוכר בנכסי אביו וקאמר דלענין עדות עדותו עדות למטלטלים והם הם דברי רבינו ולמדנו מכאן שבן י״ג שהביא שתי שערות ובקי בטיב משא ומתן עדותו עדות אף לקרקע:\",2,0],[8,388,9,9,\"השוטה פסול לעדות וכו'. שהשוטה פסול זה פשוט ומבואר בכמה מקומות.\",1,0],[8,388,9,9,\"ומ\\\"ש לפי שאינו בן מצות. צ\\\"ע היכא איתא שהטעם שהוא פסול לפי שאינו בן מצות דבפ\\\"ק דחגיגה תנן הכל חייבים בראיה חוץ מחש\\\"ו ושם (דף ג':) אמרו אי זהו שוטה היוצא יחידי בלילה והלן בבית הקברות והמקרע את כסותו איתמר אמר רב הונא עד שיהו כולן בבת אחת ור' יוחנן אמר אפילו באחת מהן וקי\\\"ל כר' יוחנן וכן פסק הרא\\\"ש בריש חולין וז\\\"ש\",2,0],[8,388,9,9,\"רבינו בדבר מן הדברים לומר דאפילו בדבר אחד ונתברר שם דדוקא בדעביד להו דרך שטות ואין הכוונה שבפעם אחת שיעשה אחד מאלו דרך שטות מיקרי שוטה אלא כשדרכו בכך וז\\\"ש\",3,0],[8,388,9,9,\"רבינו ונמצאת דעתו משובשת תמיד וכו' ותניא תו התם (דף ד') אי זהו שוטה זה המאבד כל מה שנותנין לו ומשמע מדברי רבינו דס\\\"ל דהני מילי דקתני בברייתא לאו דוקא אלא ה\\\"ה לכל דבר שדרך השוטה לעשות אותם והנך לדוגמא נקטינהו ומפני כך לא הזכיר רבינו אותם דברים השנויים שם בברייתא אלא סתם וכתב כל מי שנטרפה דעתו ונמצאת דעתו משובשת תמיד בדבר מן הדברים וכו' לכלול גם שאר דברים שלא נזכרו בברייתא ומה שהכריחו לפרש כן כתבתי בטור אבן העזר סי' קכ\\\"א:\",4,0],[8,388,9,9,\"הנכפה בעת כפייתו פסול וכו'. ברייתא פ' ראוהו ב״ד (ראש השנה דף כ״ח) עתים חלים עתים שוטה כשהוא שוטה כשוטה לכל דבריו וה״נ משמע בפ״ב דכתובות (דף כ') גבי ההוא עובדא דבר שטיא זבין נכסי:\",5,0],[8,388,9,10,\"הפתאים וכו'. כן כתב בעל העיטור באות קו\\\"ף שכן כתב הרי\\\"ף בתשובה:\",1,0],[8,388,9,11,\"חרש מדבר ואינו שומע וכו'. בגיטין ר״פ מי שאחזו (גיטין דף ע״א) תניא אם לא יגיד פרט לאלם שאינו יכול להגיד ואמרינן התם שאע״פ שיכול להגיד מתוך הכתב פסול דרחמנא אמר מפיהם ולא מפי כתבם ואפשר דמשמע ליה לרבינו דה״ה למדבר ואינו שומע דכתיב ושמעה קול אלה פרט למי שאינו יכול לשמוע:\",1,0],[8,388,9,11,\"וכן אם נשתתק וכו'. שם כשם שבודקין אותו לגיטין כך בודקין וכו' לעדיות ואסיקנא דדוקא בעדות אשה דאקילו בה רבנן אבל בשאר עדויות לא ופירש\\\"י בעדות אשה להשיאה דאקילו בה בעד אחד קרוב ושפחה.\",2,0],[8,388,9,11,\"וממ\\\"ש רבינו או שיהא ראוי להעיד בפיו וכו' נראה דס\\\"ל דפקח ששלח כתב ידו לב\\\"ד כיון שראוי להגיד ולשמוע כשר הוא דכל הראוי לבילה אין בילה מעכבתו ולסברת התוספות ביבמות פ' ד' אחין ולא כפירש\\\"י בפירוש החומש שכתב על פי שנים עדים פרט לשלא ישלחו כתב ידם לב\\\"ד ועכ\\\"פ דברי רבינו צ\\\"ע אבל הטור כתב לשון רבינו וכך כתב צריך להעיד בבית דין בפיו ויהיה ראוי לשמוע הדיינים וכו' ואם כן לא סבירא ליה אלא כרש\\\"י דאינו יכול לשלוח עדותו לבית דין וקצת משמע כן ממה שכתב פ' ג' מהלכות אלו דין תורה שאין מקבלין וכו' הרי שלא התיר אלא לחתום בשטר וכן נראה מתשובת רב שרירא שכתב הטור בסי' ס\\\"ט:\",3,0],[8,388,9,12,\"הסומים אע\\\"פ שמכירים הקול וכו'. הכי אמרינן בפ\\\"ב דגיטין (דף כ\\\"ג) דאע\\\"ג דידעי בטביעות עינא דקלא הם פסולים אך הראיה שהביא מאו ראה צ\\\"ע היכא איתא:\",1,0],[8,388,9,12,\"הסומא באחת מעיניו וכו'. זה פשוט דכיון דכשר לדון דיני ממונות וכמו שכתב רבינו פ״ב דהל' סנהדרין כ״ש דכשר להעיד דאפי' מאן דאמר אינו כשר לדון מודה דכשר להעיד וכדתנן בנדה פ' בא סימן (נדה דף מ״ט:) יש שכשר להעיד ואינו כשר לדון ואמרינן בגמרא דהיינו לאיתויי סומא באחת מעיניו לר״מ דכשר להעיד ואין כשר לדון וכתב רש״י אבל בשתי עיניו אפילו לעדות פסול דכתיב או ראה משמע דסומא באחת מעיניו כיון דלא אימעיט כשר אפי' לד״נ:\",2,0],[8,388,10,1,\"הרשעים פסולים וכו'. בפ' זה בורר (סנהדרין דף כ״ה) ובפרק מרובה (בבא קמא דף ע״ב:) אמרינן גבי עד זומם רשע הוא והתורה אמרה אל תשת ידך עם רשע אל תשת רשע עד כלומר מה שאמרה תורה אל תשת ידך עם רשע עניינו אל תשת רשע להיות עד:\",1,0],[8,388,10,1,\"ואפילו עד כשר שיודע בחבירו וכו'. בפ' שבועת העדות (שבועות דף ל' ע״ב) מנין לעד שיודע בחבירו שהוא גזלן שלא יצטרף עמו ת״ל מדבר שקר תרחק כלומר אפילו שהעדות אמת משום שגורם לפסוק הדין על פי שנים ואין כאן אלא עד אחד ואצ״ל היכא דעד שעמו עד שקר ולא ראה דבר זה מעולם שאסור לו להעיד עמו וצריך עיון אמאי לא מייתי רבינו הא דיודע בחבירו שהוא גזלן שלא יצטרף עמו מהיכא דמייתי ליה בגמרא דהיינו ממדבר שקר תרחק:\",2,0],[8,388,10,2,\"אי זהו רשע וכו':\",1,0],[8,388,10,3,\"עבר עבירה שחייבין עליה מלקות וכו'. בסנהדרין פרק זה בורר (סנהדרין דף כ״ה) ובספ״ק דר״ה (דף כ״ב) מוכח בהדיא דאיכא פסולי עדות דאורייתא ופסולי עדות דרבנן:\",1,0],[8,388,10,3,\"כיצד אכל בשר בהמה בחלב וכו'. בסנהדרין פ' זה בורר (סנהדרין דף כ״ז) מומר אוכל נבילות לתיאבון ד״ה פסול כלומר דמשום ממון קא עביד דהא שכיח בזול טפי מדהיתרא ה״ל כרשע דחמס ופסול לעדות להכעיס אביי אמר פסול דהוה ליה רשע ורחמנא אמר אל תשת רשע עד ורבא אמר כשר רשע דחמס בעינן כלומר דכתיב להיות עד חמס רשע בדבר ממון בעינן ואסיקנא התם דהלכתא כאביי ולכן כתב כאן רבינו אלו העבירות דלאו דחמס נינהו ולא חילק בין אם עושה כן לתיאבון או להכעיס:\",2,0],[8,388,10,4,\"ועוד יש שם רשעים שהם פסולים וכו'. פ' זה בורר (סנהדרין דף כ״ה:). ויש לדקדק בדברי רבינו מאי האי קרא דנקט לא יקום עד חמס דלא אמרינן במרובה (דף ע״ב) בגמרא דעד דחמס בעינן אלא אליבא דרבא דאמר עד זומם מכאן ולהבא הוא נפסל ולית הלכתא כוותיה. וי״ל דנקט האי קרא משום דהני בני תשלומין נינהו ואינם בני מלקות וקאמר שאע״פ שהחזירו ממון האיסור עדיין הם בפיסולם עד שיעשו תשובה. ויש לדקדק עוד דמשמע מדברי רבינו דחמסן מדאורייתא פסול ואע״פ שרבינו ירוחם כתב שיש מי שסובר כן דבר תמוה הוא דבהדיא אמרי' בפ' זה בורר שם דמדרבנן הוא דפסול דאהא דהוסיפו עליהם החמסנים אמרינן מעיקרא סבור דמי קא יהיב אקראי בעלמא הוא כיון דחזו דחטפי כלומר בע״כ של בעלים גזרו בהו רבנן ולכן נ״ל דחמסנים הכתוב בספרי רבינו ט״ס הוא וצריך להגיה גזלנים במקום חמסנים ולגירסת ספרינו צ״ל דחמסנים דקאמר הכא רבינו לישנא דקרא נקט והרצון בו גזלנין תדע דקתני סיפא מעת שגנב וגזל ואם איתא דדוקא נקט או חמס מבעי ליה ועוד דלקמן בסמוך כתב דחמסנים פסולים מדבריהם:\",1,0],[8,388,10,4,\"ומ\\\"ש וכן עד זומם וכו'. פיסול עד זומם יתבאר בסמוך.\",2,0],[8,388,10,4,\"ומ\\\"ש אע\\\"פ שהוזם בעדות ממון ושלם פירושו שאילו הוזם בעדות שאינו של ממון שהרי הוא חייב מלקות כיון שלקה חזר לכשרותו כמבואר פרק י\\\"ב וכל שלא לקה ודאי שאינו נכשר אפילו נתן כמה ממון אבל כשהוזם בעדות ממון שהוא משלם ואינו לוקה סד\\\"א כיון ששלם הממון הוכשר קמ\\\"ל דלא דומיא דגנב וחמסן וכמו שיתבאר פי\\\"ב מהלכות אלו מאימתי חזרת מלוי ברבית וכו' והתם כשהחזירו ממון האיסור ואפ\\\"ה לא מתכשרי כיון דעדים דחמס נינהו עד שיעשו תשובה:\",3,0],[8,388,10,4,\"ומאימתי הוא נפסל וכו'. בב״ק פ' מרובה (בבא קמא דף ע״ב:) ובסנהדרין פרק זה בורר (סנהדרין דף כ״ז) פלוגתא דאביי ורבא ואיפסיקא הלכתא כאביי שזו אחת משמועות יע״ל קג״ם וטעמא דלמפרע הוא נפסל מפרש התם דמההוא שעתא דאסהיד ה״ל רשע והתורה אמרה אל תשת רשע עד:\",4,0],[8,388,10,4,\"וכן המלוה ברבית וכו'. משנה בסנהדרין פרק זה בורר (סנהדרין דף כ״ד:) דמני מלוה ברבית בכלל הפסולים ואמר רבא (דף כ״ה) לוה ברבית פסול לעדות ומתני' ה״ק מלוה הבאה ברבית ופסולין דקתני אתרווייהו. וכתב רבינו ירוחם שרבינו לא מנה עדים בפסולי עדות שכתב בפ״ד מהלכות מלוה ולוה שהערב והעדים והסופרים עוברים על לא תשימון עליו נשך ונראה מדבריו שהם פסולים עכ״ל. ואני אומר שזה משנה שלמה בפרק איזהו נשך (בבא מציעא דף ע״ה:) ואינו מיוחד לרבינו אבל אין משם ראיה שהם פסולים שאע״פ שעוברין בלא תשימון כיון דאינם בני מלקות וגם כן לא נטלו ממון דלהוו עדים דחמסן לא מיפסלי וכן כתב רבינו בראש פרק זה שמי שעבר עבירה שחייבין עליה מלקות או מיתת ב״ד הוא שנקרא רשע הא לאו הכי לא אלא אם הוא עד דחמס כמו שכתב ועוד יש שם רשעים וכו' וזה נראה ברור. והרב המגיד כתב בפ״ד מהל' מלוה גבי שטר שיש בו רבית שיש מי שפירש שאע״פ שהרבית מפורש בשטר אין העדים נפסלים בכך לפי שלאו זה אינו ידוע לכל וסוברים שלא תשימון אינו אלא למלוים עכ״ל:\",5,0],[8,388,10,4,\"וכן כל העובר על גזל של דבריהם וכו' כיצד החמסנים וכו'. שם (דף כ\\\"ה:) תנא הוסיפו עליהם הגזלנים והחמסנין ומקשה גזלן דאורייתא הוא ומוקי לה בגזלן דרבנן ומדפרכינן הכי בגזלן ולא בחמסן משמע דמדרבנן הוא דפסילי ואע\\\"ג דבפרק קמא דמציעא (דף ה':) אמרינן לא תחמוד לאינשי בלא דמי משמע להו דמשמע דלאינשי משמע אבל קושטא לא הוי כבר כתבו התוספות די\\\"ל דה\\\"פ דמשמע להו וקושטא הכי הוי נמי:\",6,0],[8,388,10,4,\"וכן הרועים וכו'. שם עוד הוסיפו עליהן הרועים והגבאים והמוכסים וכו' אמר רבא רועה שאמרו אחד רועה בהמה דקה ואחד רועה בהמה גסה ובפ\\\"ק דמציעא (דף ה') בעובדא דההוא רעיא אמרינן דה\\\"מ ברועה בהמות שלו אבל רועה בהמות דעלמא כשר דאין אדם חוטא לרעותן בשדות אחרים ולא לו:\",7,0],[8,388,10,4,\"ולפיכך סתם רועה פסול וכו'. פרק זה בורר (סנהדרין דף כ״ה:) אמר רב יהודה סתם רועה פסול:\",8,0],[8,388,10,4,\"ומגדלי בהמה דקה בא\\\"י פסולין וכו'. שם אהא דאמר רבא אחד רועה בהמה דקה וכו' מקשינן והאמר רבא רועי בהמה דקה בא\\\"י פסולין בחו\\\"ל כשרים רועי בהמה גסה אפילו בא\\\"י כשרים ומהדרינן ההוא במגדלי אתמר ופירש\\\"י במגדלי אתמר שמגדלין אותה בבתיהם ואפילו הכי בארץ ישראל פסולין מגדלי בהמה דקה דעבידא דמשמטא ורהטא לתוך השדות אבל גסה לא משתמטא ואפשר לנטורה אבל רועה שמרען בחוץ באפר של ישוב אפי' בהמה גסה פסול שנכנס בשדה של אחרים עכ\\\"ל. וטעמא דמחמרינן טפי בא\\\"י היינו משום יישוב א\\\"י וכן כתבו התוס':\",9,0],[8,388,10,4,\"וכן המוכסין וכו'. שם א״ר יהודה סתם גבאי כשר פירוש גובה מנת המלך ושכרו קצוב וידוע וסתמו כשר עד דחזינן שלוקח יותר מוכס היינו שקונה מנת המלך בכך וכך לשנה והוא גובה לעצמו חשוד ליקח יותר ממה שצוה המלך ליטול והכי אמרינן נמי בפ' שבועת הדיינין (שבועות דף ל״ט) דאמרי' אין לך משפחה שיש בה מוכס שאין כולם מוכסין ושיש בה לסטים שאין כולם לסטים מפני שמחפין עליו ואילו משפחה שיש בה גבאי לא קאמר. ואני אומר שבזמן הזה סתם גבאי נמי פסול שגם הוא ידוע שלוקח יותר:\",10,0],[8,388,10,4,\"ואם נודע וכו'. זה פשוט דהא גזלן הוא. וצריך עיון אם הוא פסול מדאורייתא מכיון שנודע שגזל ואע\\\"פ שכתב רבינו בסוף דבריו שכל אלו פסלום משום גזל לא קאי אהא דאם נודע שלקחו וכו' ואגב גררא נסביה, או אי לא מיפסיל אלא מדרבנן משום דמורי היתרא שהוא עסוק במלאכת המלך וראוי לו ליטול שכר מעבדיו, והדעת נוטה דמדאורייתא מיפסיל:\",11,0],[8,388,10,4,\"וכן מפריחי יונים וכו'. משנה פ' זה בורר (סנהדרין דף כ״ד:) דמני גבי פסולין מפריחי יונים וטעמייהו משום גזל אבל במדבר שרי וזהו שכתב\",12,0],[8,388,10,4,\"רבינו ביישוב. ודע ששם (דף כ\\\"ה) אמרו מאי מפריחי יונים הכא תרגימו אי תקדמיה יונך ליון (אתן לך כך וכך) ר' חמא בר אושעיא אמר ארא (כלומר מלומד להביא יונים ממקומם לבית בעלים על כרחן) מאן דאמר אי תקדמיה יונך ליון מאי טעמא לא אמר ארא אמר לך ארא מפני דרכי שלום בעלמא ומ\\\"ד ארא מאי טעמא לא אמר אי תקדמיה יונך ליון אמר לך היינו משחק בקוביא. ומעתה כיון שכתב רבינו מפריחי יונים ביישוב משמע דסבירא ליה דארא פסול ויש לתמוה שהרי בסוף פרק זה כתב וכן לא יונים בלבד אמרו וכו' אלמא דס\\\"ל כמ\\\"ד אי תקדמיה יונך ליון וא\\\"כ היאך פסל ארא דהא מדקאמר משום דרכי שלום בעלמא הוא משמע דלא מיפסיל. וי\\\"ל דס\\\"ל דהיינו ארא וכמו שכתב כאן וכיון דארא פסול כל שכן אי תקדמיה יונך ליון ומשום דפיסולא אי תקדמיה יונך ליון הוי משום משחק בקוביא כמו שאמרו בגמרא סמכו למשחק בקוביא וכתבו בסוף פרק זה ואע\\\"פ שהלשון דחוק קצת שכתב ולא יונים בלבד אמרו דמשמע שהזכיר כבר למעלה יונים בההוא גוונא דאי תקדמיה יונך ליון יש לומר שתפס לשון הברייתא ולא קאי למה שהזכיר כך נ\\\"ל:\",13,0],[8,388,10,4,\"וכן סוחרי שביעית וכו'. שם באותה משנה וסוחרי שביעית אמר רבי יהודה מתחלה לא היו קורין אותן אלא אוספי שביעית משרבו האנסין חזרו לקרותן סוחרי שביעית א\\\"ר יהודה אימתי בזמן שאין להן אומנות אלא הוא אבל אם יש להן אומנות שלא הוא כשר וכו' ומפרש בגמ' דבתחלה היו אומרים אחד זה ואחד זה פסולים משרבו האנסין וכו' חזרו לומר אוספין כשרים סוחרים פסולים וידוע דכל היכא דא\\\"ר יהודה אימתי אינו אלא מפרש דברי חכמים והלכה כמותו וכך פוסק שם הגמ' בפירוש.\",14,0],[8,388,10,4,\"ומ\\\"ש רבינו והם בני אדם שיושבים בטלים לפי שאם אינן יושבין בטלים כשנושאין ונותנין בפירות לא נאמר שהן אוספין פירות שביעית אבל נאמר שהן פירות שלפני שביעית אבל כשהם יושבים בטלים וכיון שבאה שביעית פושטים ידם ונושאים ונותנים בפירות אז נחזיקם שהם אוספים פירות שביעית ועושין בהם סחורה אורחא דמילתא נקט אבל אה\\\"נ דאוספים או סוחרים פסולים אם אין שם אונס:\",15,0],[8,388,10,4,\"וכן משחק בקוביא וכו'. גם זה באותה משנה דמני בהדי הנהו דפסולי משחק בקוביא ואמר רבי יהודה אימתי בזמן שאין לו אומנות. וא״ת והרי פסול הוא משום גזל שכן כתב רבינו בהל' גזילה פ״ו שאסור לשחק בקוביא משום גזל וכיון שכן אפילו יש לו אומנות אחרת פסול וי״ל דהב״ע במשחק עם העכו״ם שאין בו משום גזל וכמ״ש רבינו שם ואפ״ה אם אין לו אומנות אחרת פסול משום שאינו עוסק ביישובו של עולם. וא״ת הרי רבינו כתב הרי זה בחזקת שאוכל מן הקוביא שהוא גזל ואי במשחק עם העכו״ם אין כאן גזל י״ל דלעולם במשחק עם העכו״ם וסובר רבינו שאינו עוסק ביישובו של עולם פי' שכיון שאין לו אומנות אחרת הרי הוא בחזקת שמשחק עם ישראל והוא גזל ואע״פ שלא ראינוהו סתמו כודאי אי נמי דהכא אפילו במשחק עם ישראל עסקינן אלא שאינו משחק במעות ואם היה לו אומנות להתפרנס לא היינו חושדים אותו שדרך העשירים שבגמר מלאכתן שוחקים להעביר השעה אבל כיון שאין לו אומנות סתמו שמשחק במעות ואע״פ שלא ראינו מעולם שמשחק במעות סתמו כודאי תדע שאילו היה פסולו משום ודאי גזל מאי איריא אין לו אומנות אפילו בפעם אחת לבד נפסל משום גזלן וכך אמרו בפרק זה בורר בפירוש דלמ״ד דאיסורא דמשחק בקוביא משום גזל אפי' יש לו אומנות אחרת הוא פסול גם רבינו כתב כאן הרי זה בחזקת שאוכל מן הקוביא שהוא גזל ואי במשחק עם ישראל במעות מאי בחזקת הרי אני רואה אותו משחק במעות וגוזל ואוכל אלא ודאי דהכא לאו במשחק עם ישראל במעות עסקינן. ולפי שהרב המגיד נתקשה בדברי רבינו פרק ששי מהל' גזילה והניחה בצ״ע אני אהיה מובין לפניך ואכתוב לך כאן לשון הגמרא ואפרשה לפי דעת רבינו. בפ' זה בורר (סנהדרין דף כ״ד:) אמרו משחק בקוביא מאי קאי עביד אמר רמי בר חמא משום דהוה אסמכתא ואסמכתא לא קניא רב ששת אמר כל כי האי גוונא לאו אסמכתא היא אלא לפי שאין עוסקין בישובו של עולם מאי בינייהו איכא בינייהו דגמר אומנותא אחריתי תנן אמר ר״י אימתי בזמן שאין לו אומנות אלא הוא אבל אם יש לו אומנות שלא הוא הרי זה כשר אלמא סתמא דמתני' משום יישובו של עולם קשיא לרמי בר חמא וכ״ת פליגי רבנן עליה דר' יהודה והאמר ריב״ל כל מקום שא״ר יהודה אימתי אינו אלא לפרש דברי חכמים ר' יוחנן אמר אימתי לפרש ובמה לחלוק גברא אגברא קא רמית פי' ריב״ל ור' יוחנן ארמי בר חמא מר סבר פליגי ומר סבר לא פליגי ולא פליגי והתניא בין שיש לו אומנות שלא הוא בין שאין לו אומנות אלא הוא הרי זה פסול ההיא ר' יהודה משום ר' טרפון היא ע״כ לשון הגמ' וסובר רבינו דהלכה כרמי בר חמא מדאמרינן בשבת פרק שואל (שבת דף קמ״ט) מנה גדולה כנגד קטנה אף בחול אסור משום קוביא אלמא סתמא דגמרא סבירא ליה כרמי דהוי אסמכתא ושם נדחקו התוס' לומר דאתי כר' יהודה משום דר' טרפון וקשה דא״כ למה כשפסקו בסנהדרין הלכה כר״י דמתניתין לא היה שם פוצה פה לחלוק ועוד שבספ״ק דר״ה (דף כ״ב) אמתניתין דאלו הם הפסולין המשחק בקוביא וכו' זה הכלל כל עדות שאין האשה כשרה לה אף הם אינם כשרים לה אמר רב מנשיא זאת אומרת גזלן [של] דבריהם כשר לעדות אשה אלמא דמשחק בקוביא משום גזל מיפסיל וכרמי בר חמא משום דהוי גזלן ועוד דמדאמרי' פרק זה בורר (סנהדרין דף כ״ו:) אמר ר' אבהו א״ר אלעזר הלכה כרבי יהודה ומדקאמר הלכה מכלל דפליגי אלמא כרמי ס״ל ועוד דבפ' זה בורר שאלו על המשנה מאי מפריחי יונים איכא מ״ד אם יקדמו יונך ליון אתן לך כך וכך והקשו עליו היינו משחק בקוביא ותירץ תנא תולה בדעת עצמו דהוי אסמכתא והדר תנא תולה בדעת יונו וצריכא דאי תנא [תולה] בדעת עצמו התם הוא דלא גמר ומקני דאמר קים לי בנפשאי דידענא טפי אבל תולה בדעת יונו אימא לא ואי תנא תולה בדעת יונו דאמרו [בנקשא תליא מילתא] אנא ידענא לנקושי טפי פי' להשמיע קול להפריחם אבל תולה בדעת עצמו אימא לא צריכא ומוקי התם לבר פלוגתיה כרבי יוסי דפליג ארבנן ואילו מאן דאמר אי תקדמך יונך ליון אתי ככ״ע משמע מכל הני דכרמי בר חמא קי״ל ומאחר שלא מצינו מי שנחלק בפירוש על מאמר ריב״ל ור״י יש לנו ליישב מתני' אליבא דרמי בר חמא ולומר דמתניתין מיירי בין במשחק עם ישראל במעות בין עם העכו״ם או עם ישראל בחנם ור' יהודה לא בא אלא לפרש דברי חכמים ולומר דמשחק עם העכו״ם או עם ישראל בחנם לא מיפסל אלא אם אין לו אומנות אחרת לפי שאינו עוסק בישובו של עולם והשתא אתי שפיר דלא פליג רמי אריב״ל ורבי יוחנן ואתיא נמי ברייתא דבין יש לו אומנות בין אין לו ככ״ע דמיירי במשחק עם ישראל במעות ורמי בר חמא נתן טעם למשחק בקוביא דרך כלל משום גזל שגם משחק עם העכו״ם טעם פסולו הוא לפי שאינו עוסק בישובו של עולם והוא חשוד שמשחק עם ישראל במעות שהוא גזל וכמו שכתבתי לדעת רבינו אי נמי שהתחיל לתת טעם למשחק עם ישראל במעות משום גזל ודעתו היה לתת טעם למשחק עם העכו״ם לפי שאינו עוסק ביישוב העולם אלא דלא שבקיה רב ששת למגמר למילתיה עד שנחלק עליו ואמר דאפילו משחק עם ישראל במעות לא הוי אסמכתא וכשהשיב איכא בינייהו דגמר אומנותא אחריתי לא השיב אלא במשחק עם ישראל במעות אבל עם העכו״ם לפי שאינם עוסקים ביישוב העולם הוי לתרווייהו אלא שהמקשה לא הבין דבריו וס״ד דמתניתין לא מיירי אלא במשחק עם ישראל במעות ולכך הקשה לו דמתניתין משמע דטעמא לפי שאינם עוסקים ביישוב העולם והשיבו לפי דרכו מה תעלה על דעתך להקשות ממאמר ריב״ל לרמי וכי גברא אגברא קא רמית אבל קושטא דמילתא דרמי מודה לריב״ל ור' יוחנן וכמו שכתבתי וא״ת א״כ דכ״ע מודו דר' יהודה לא בא אלא לפרש למה ליה לגמרא התם למיפסק הלכתא כוותיה י״ל משום דס״ד דרמי סבר דפליגי ולא אתברר התם דלא פליגי לפום הכי איצטריך למיפסק הלכתא כוותיה אבל לפום קושטא לא הוה צריך וכיון שכן הדין עם רבינו לפסוק כרמי בר חמא וכפי מה שפירשתי ודבריו נכונים וברורים. ודע שבנוסחא אחרת כתוב ה״ז בחזקת שאוכל מן הקוביא שהוא אבק גזל וכתב הטור שכיון שכתב רבינו ה״ז בחזקת שאוכל מן הקוביא אלמא דאם יש לו ממון אחר שאוכל ממנו אינו פסול עכ״ל. ואיני מבין דבריו שרבינו אומר שאף על פי שיש לו ממון אחר מכל מקום חזקתו שאוכל מן הקוביא ג״כ:\",16,0],[8,388,10,4,\"ולא בקוביא בלבד וכו'. ברייתא שם כלשון רבינו.\",17,0],[8,388,10,4,\"ומה שכתב והוא שלא תהיה לו אומנות וכו'. כבר נתבאר בסמוך:\",18,0],[8,388,10,5,\"אריס שלקח וכו'. שם בסנהדרין (דף כ\\\"ו) אמר רב נחמן גנב ניסן וגנב תשרי לא שמיה גנב ה\\\"מ באריס בדבר מועט ובדבר שנגמרה מלאכתו ופירש\\\"י ניסן זמן קציר תשרי זמן בציר ואסיף באריסא דטרח בה ומורי היתרא ליטול דבר מועט יותר על חלקו מפני טורחו דבר שנגמר מלאכתו דמשוי נפשיה כפועל ומורי בה היתרא וסבר לא קפיד ע\\\"כ. אבל גירסת רבינו נראה שהיתה ובדבר שלא נגמרה מלאכתו וכן מצאתי בהלכות הרי\\\"ף ז\\\"ל ואפשר דהיינו טעמא שכל שלא נגמרה מלאכתו מורה ואמר כיון שאני עוסק במלאכה מותר אני ליקח דבר מועט אבל כל שנגמרה מלאכתו אינו מורה אלא דרך גניבה הוא נוטל ודוקא באריס שיש לו חלק בגוף הפירות אבל אם אין לו חלק בגוף הפירות פסול בכל שהוא והכי משמע בגמ': הולך ובונה במה לעצמו וכו' א\\\"ר פפא כמאן מקבלין האידנא סהדותא מע\\\"ה כרבי יוסי וסובר רבינו דבחגיגה מיירי בע\\\"ה שיש לו דרך ארץ ומצות אבל אינו לא במקרא ולא במשנה ובפסחים מיירי בסתם ע\\\"ה דסתמו הוא דליתיה לא במקרא ולא במשנה ולא בדרך ארץ:\",1,0],[8,388,11,5,\"וכן הבזויין וכו' ואוכלים בשוק בפני כל העם. ספ\\\"ק דקידושין (דף מ':) ת\\\"ר האוכל בשוק הרי זה דומה לכלב וי\\\"א פסול לעדות אמר רב אידי בר אבין הלכה כי\\\"א וכתבו בתוס' דדוקא אוכל פת פסול אבל לא אוכל פירות א\\\"נ ל\\\"ש פת ל\\\"ש פירות אלא אם חוטף ואוכל הוא דמיפסיל וכגון שאין בו שוה פרוטה או שאינו מקפיד עליו דאי לא תיפוק לי משום גזל והכריחם בזה הא דאמרינן בירושלמי ר\\\"ש ברבי הוה אכיל בשוק חזייה ר\\\"מ (אמר לו) אין שבח לתלמיד לאכול בשוק משמע דלאחר אין קפידא והיינו באוכל פירות או באינו חוטף ואפ\\\"ה אין שבח לת\\\"ח ורבינו סתם דבריו ואין בהם הכרע א\\\"נ שרבינו סובר דהא דאמרינן פסול לעדות היינו באוכל בפני כל העם אבל אם אוכל בשוק שאין בו רוב עם אלא קצת עוברים ושבים לא מיפסיל מש\\\"ה והיינו ההיא דירושלמי מ\\\"מ אינו שבח לת\\\"ח:\",1,0],[8,388,11,5,\"וכגון אלו שהולכים וכו'.. ומכלל אלו האוכלים וכו'. סנהדרין פרק זה בורר (סנהדרין דף כ״ו:) אמר ר״נ אוכלי צדקה של העכו״ם בפרהסיא פסולים לעדות והוא דאפשר ליה לאיתזוני בצנעה ומבזי נפשיה:\",2,0],[8,388,11,6,\"מה בין וכו'. שם א\\\"ר אלעזר כולן פי' כל הפסולין לעדות צריכין הכרזה בב\\\"ד ואסיקנא דה\\\"מ פסולים דרבנן אבל פסולים דאורייתא לא בעו הכרזה:\",1,0],[8,388,11,7,\"עד אחד נאמן וכו'. איתא בדוכתי טובא:\",1,0],[8,388,11,7,\"שהרי רשע בעבירה ששחט וכו'. פ\\\"ק דחולין ונתבאר בדברי רבינו פ\\\"ד מהלכות שחיטה:\",2,0],[8,388,11,7,\"אבל החשוד וכו'. פ\\\"ה דבכורות (דף ל\\\"ה) פלוגתא ופשטו בפרק בתרא דיומא (דף ע\\\"ח) אין הלכה כר\\\"מ דאמר החשוד בדבר לא דנו ולא מעידו אלא כרשב\\\"ג דאמר נאמן הוא על של חבירו ואינו נאמן על של עצמו והכי אמרינן בריש מציעא ובכמה דוכתי חזקה אין אדם חוטא ולא לו:\",3,0],[8,388,11,8,\"וכתב הראב\\\"ד לפיכך וכו' א\\\"א זה אינו כן וכו'. ואני אומר דמה שהביא הראב\\\"ד והעתיק מפ\\\"ד דדמאי אינו ענין לנדון שלנו דהתם על של עצמו הוא ואינו נאמן עליו אלא בשבת בלבד משום דאימת שבת על ע\\\"ה ולא נתכוון להשיג אלא מסיפא דההיא דמסיים בה לא מצאו אמר לו אחר שאינו נאמן על המעשרות מעושרין הם אוכל על פיו חשכה מוצאי שבת לא יאכל עד שיעשר והרי בבא זו הוא מעיד על של חבירו ואפ\\\"ה משחשכה מוצאי שבת אינו נאמן וי\\\"ל דשאני ההיא דאיכא למיחש שמא אמר לו כך כדי שלא ימנע מלאכול בשבת. ומ\\\"ש ואי קשיא לך פיסקא אחריתי הנכנס לעיר וכו' הא אמרינן בירושלמי אכסנאי שאני י\\\"ל שהוצרכו לומר כן בירושלמי משום דאומר על עצמו שאינו נאמן ואין דרך בני אדם לומר כן על עצמן והוה לן למיחש לגומלין ומש\\\"ה לא הוה לן להימוניה ואפי' לגירסא דידן במתני' ואמר לו אני (איני) [אינו] נאמן איש פלוני נאמן אכתי הוה לן למיחש לגומלין אלא משום דבאכסנאי הקילו. ומ\\\"ש ועוד משנה שלימה החשוד בדבר לא דנו ולא מעידו אינה ראיה דההוא סתמא היא בפ\\\"ד דבכורות ובפ\\\"ה שנויה במחלוקת דר\\\"מ אמר הכי ורשב\\\"ג פליג עליה ואמר נאמן הוא על של חבירו וסתם ואח\\\"כ מחלוקת אין הלכה כסתם ובפ' בתרא דיומא איפסיקא הלכתא כרשב\\\"ג. ומ\\\"ש ומומי בכור שאני וכו' י\\\"ל דכיון דגמ' לא מפליג הכי גם רבינו לא מפליג וכבר כתבתי בזה בפ' י\\\"ב מהל' מעשרות:\",1,0],[8,388,11,8,\"וכן כל כיוצא בזה משאר איסורים [על] הרשעים ואין אימת בעל הממון עליהן. אין נסחא זו מכוונת ומצאתי נסחא אחרת וכ\\\"כ בה ונאמן הנחשד למכור בשר בכור לומר בשר זה שמוכר פלוני חולין וכן כל כיוצא בזה משאר האיסורין לפי שאימת האיסורין על הרשעים ואין אימת הממון עליהם עכ\\\"ל וכך היא נסחת ויניציא:\",2,0],[8,388,11,9,\"מלכי ישראל לא וכו'. סנהדרין פ' כה״ג (סנהדרין דף י״ח) דתנן המלך לא דן ולא דנין אותו א״ר יוסף (דף י״ט) ל״ש אלא מלכי ישראל אבל מלכי בית דוד דנין ומעידין אותם. וזהו שכיון רבינו באומרו מלכי ישראל וטעם הדבר ועניינו כתבתי בארוכה פ״ג מהל' מלכים ומלחמותיהם:\",1,0],[8,388,11,9,\"אבל כ\\\"ג וכו'. משנה שם וכבר נתבאר בהל' סנהדרין פ\\\"ב ובפ\\\"ה מהלכות אלו ושם הארכתי:\",2,0],[8,388,11,10,\"שהעכו״ם לא מורידין וכו'. פרק אין מעמידין (עבודה זרה דף כ״ו) תני ר' אבהו קמיה דרבי יוחנן העכו״ם ורועי בהמה דקה לא מעלין ולא מורידין אבל האפיקורוסים והמסורות והנהפכים לע״ז מורידין ולא מעלין ואוקמוה התם דוקא במומר לע״ז להכעיס:\",1,0],[8,388,11,10,\"ויש לחסידיהם וכו'. פלוגתא דר' אליעזר ור' יהושע בפ' חלק תפס רבינו סברת ר\\\"י דהלכתא כוותיה לגבי ר' אליעזר:\",2,0],[8,388,12,1,\"כל הנפסל וכו'. כל זה נלמד מדאמרינן בסנהדרין פרק זה בורר (סנהדרין דף כ״ו) הנהו קבוראי דקברו נפשא ביו״ט ראשון של עצרת שמתינהו רב פפא ופסלינהו לעדות אכשרינהו רב הונא בריה דר' יהושע א״ל רב פפא והא רשעים נינהו סברי מצוה עבדינן והא קא משמתינן להו כלומר וחוזרין ושונין בעבירה סברי כפרה עבדי לן רבנן כלומר מותר לחלל יו״ט בשביל המצות ונשב בנדוי משום כפרה. נראה מכאן שאע״פ שלא התרו בהם פסולין דהא הנהו קבוראי לא אתרו בהו דאי אתרו בהו לא שייך למימר דסברי מצוה עבדינן ואפ״ה פסלינהו רב פפא וע״כ לא אכשרינהו רב הונא בריה דרב יהושע אלא משום דסברי מצוה עבדינן הא לאו הכי אע״ג דלא אתרו בהו פסילי ומשמע נמי דכל היכא דאיכא למיתלי דילמא לא ידעו שהיה אסור לא מיפסלי:\",1,0],[8,388,12,2,\"אין אדם נפסל בעבירה ע\\\"פ עצמו וכו'. בפירקא קמא דסנהדרין (דף ט':) מימרא דרבא:\",1,0],[8,388,12,2,\"לפיכך ראובן שהעיד עליו וכו'. סנהדרין פרק זה בורר (סנהדרין דף כ״ה) מעשה בר ביניתוס אסהידו ביה תרי סהדי חד סהדא אמר קמאי דידי אוזיף ברביתא וחד סהדא אמר לדידי אוזפן ברביתא פסליה רבא וכו' משום דפלגינן דיבורא וכמו שנפרש בסמוך:\",2,0],[8,388,12,2,\"וכן מי שהעיד וכו'. פ\\\"ק דסנהדרין (דף ט':) אמר רב יוסף רבעו לאונסו הוא ואחר מצטרפין להרגו לרצונו רשע הוא והתורה אמרה אל תשת רשע עד רבא אמר אדם קרוב אצל עצמו ואין אדם משים עצמו רשע כלומר על עדות עצמו אינו נעשה רשע שהרי התורה פסלה קרוב לעדות ואדם קרוב אצל עצמו ופלגינן דיבורא ונהרג הרובע על פיו והוא אינו פסול לעדות ופסק כרבא. וא\\\"ת הרי כתב רבינו פ\\\"ג מהלכות אלו ומייתי לה פ\\\"ב דכתובות (דף י\\\"ח:) שהעדים שאמרו כתב ידינו הוא זה אבל אנוסים היינו מחמת שוחד שלקחנו על עדות זו אינם נאמנים לפסול השטר משום דאין אדם משים עצמו רשע ואמאי לא פלגינן דיבורא נהימנינהו במאי דאמרי פסולים היינו ולא מחמת ממון והתוס' תירצו תירוצים הרבה על קושיא זו בפ\\\"ק דסנהדרין ובסוף פ\\\"ב דיבמות ובפרק ב' דכתובות ולדעתי המחוור שבהם דהתם עיקר העדות אנוסים היינו שבאו לומר שלא ראו המלוה אם כן מיד עושים עצמם רשעים כיון שחתמו אם לא יעשו פירוש לדבריהם הלכך לא שייך פלגינן דיבורא אבל הכא עיקר העדות להרוג את פלוני הילכך פלגינן דיבורא ולגבי להשים עצמו רשע אינו נאמן. וכתב המרדכי פ' זה בורר דקרובי הנרצח כשרים להעיד על הרוצח ואפילו הנרצח עצמו כל זמן שהוא חי ואינו טריפה יכול להעיד כדמשמע מפלוני רבעני לאונסי וסברא דנאמנים להעיד כיון דכבר מת אחיו ונ\\\"מ ליורשיו וכן נמצא בספר החכמה דקרובי הנרצח יכולים להעיד עכ\\\"ל:\",3,0],[8,388,12,2,\"פלוני בא על אשתי וכו'. פ\\\"ק דנסהדרין (דף י\\\"ט) מימרא דרבא כלשון הזה:\",4,0],[8,388,12,2,\"פלוני רבע את שורי וכו'. שם (דף י') בעיא ופשטה דאין אדם קרוב אצל ממונו ומפרש רבינו כרש\\\"י שפירש דכיון דאין אדם קרוב אצל ממונו לא פלגינן דיבורא והשור יסקל וי\\\"מ דכיון דאין אדם קרוב אצל ממונו גם על השור נתכוון להעיד ומתוך שאינו נאמן על השור שהוא ממונו אינו נאמן על הרובע דעדות שבטלה מקצתה בטלה כולה וזהו שכתב הראב\\\"ד א\\\"א מן המפרשים הטובים וכו':\",5,0],[8,388,12,3,\"שנים שהעידו על אחד שהוא פסול וכו'. פ\\\"ב דכתובות (דף כ\\\"א:) מימרא כתבתיה פרק ו' א\\\"ר אבא אמר רב הונא אמר רב ג' שישבו לקיים השטר וקרא ערער על אחד מהם פירוש לומר שהוא פסול עד שלא חתמו מעידין עליו וחותם משחתמו אין מעידין עליו וחותם ערער דמאי אי ערער דגזלנותא תרי ותרי נינהו וכו' לעולם אימא לך ערער דגזלנותא וקאמרי הני ידעינן ביה דעבד תשובה ומפרש רבינו כרש\\\"י דכי אמרינן ערער דמאי אעד שלא חתמו וכו' קאי ואמאי מעידין עליו וחותם דהא אמר ליה אוקי תרי בהדי תרי ואוקי ממונא בחזקת מריה ואע\\\"ג דאיכא למימר נמי אוקי גברא אחזקתיה חזקה דממונא אלימא טפי והרי\\\"ף האריך שם והביא ראיה בדין זה כדעת רבינו ודלא כר\\\"ח שפירש דאמאי דאמרינן משחתמו אין מעידין עליו קאי וה\\\"ק ואמאי תרי ותרי נינהו ואוקי גברא אחזקתיה:\",1,0],[8,388,12,4,\"כל מי שנתחייב מלקות בין שעשה תשובה. כלומר אם לא היתה שם התראה או שחסר דבר מהדברים שצריך לחייבו מלקות בין שלקה בב\\\"ד כלומר שנתחייב כפי הדין מלקות ולקה חוזר לכשרותו ולמדו כן ממאי דתנן בסוף מכות (דף כ\\\"ג) ונקלה אחיך לעיניך משנקלה הרי הוא אחיך ומצאתי בנוסחת רבינו בספרים ישנים מאד שגורסים כך כל מי שנתחייב מלקות כיון שלקה בבית דין חזר לכשרותו וכן היא גירסת ספר מצות גדול ומ\\\"מ נראה לי שגירסתנו יותר אמיתית שביאר רבינו משפט הנפסל מחמת עבירה שחייבין עליה מלקות בין אם הדין נותן להלקותו או שלא להלקותו ולפי הגירסא האחרת לא ביאר דין הנפסל בעבירה שחייבין מלקות ואין הדין נותן להלקותו ובפרק שני מהל' טוען ונטען כתב דאם היו עליו עדים שלקה ועשה תשובה יחזור לכשרותו בין לעדות בין לשבועה וביאור דבריו שאם לקה ועודנו לא נכנע לבבו לא חזר לכשרותו עד שתצטרף תשובה עם המלקות ולפי זה גם אותה גירסא נפרש דוקא נתחייב מלקות אלא עבר עבירה שאילו נתקיימו בה התנאים הצריכים היה חייב מלקות.\",1,0],[8,388,12,4,\"ומ\\\"ש אבל שאר פסולי עדות שהם פסולים משום ממון שחמסו או שגזלו אע\\\"פ ששלמו צריכין תשובה והרי הן פסולים עד שיודע שחזרו בהם מדרכם הרעה לומר דלא תימא כשם שהמחוייב מלקות כיון שלקה הוכשר כך המחוייב ממון גזל או חמס כיון ששלם הוכשר אלא הרי הוא בפסלותו עד שיודע ששב מדרכו הרעה בלי ערמה וכמו שנתבאר פרק י' מהלכות אלו:\",2,0],[8,388,12,4,\"כתב הטור בסי' ל\\\"ד וז\\\"ל כתב הרמב\\\"ם אע\\\"פ שהחזירו הגנב והגזלן הממון שגנבו וגזלו ושילם העד זומם הממון שהוזם עליו פסולים ואיני יודע למה לא יוכשרו אחר שהחזירו הממון ואפשר שר\\\"ל אע\\\"פ ששלמו כיון דבכפיית ב\\\"ד שילמו פסולים עד שישובו מעצמם עכ\\\"ל. ולי נראה שזה דבר פשוט הוא ולא היה צריך רבינו להזכירו אלא אפי' החזיר ברצונו נמי ונפקא ליה מדאמרינן מאימתי חזרת מלוי ברבית וכו' ומשמע דכשהחזיר ממון האיסור ברצונו עסקינן ואפי' הכי לא מתכשרי עד שיעשו תשובה וכן בדין שאע\\\"פ שהחזירו הממון מכל מקום עבירה דעבוד עבוד וצריכים תשובה ממנה:\",3,0],[8,388,12,7,\"ומה שכתב רבינו בחזרת מלוי ברבית ומשחקי בקוביא ומפריחי יונים וסוחרי שביעית. ברייתא פרק זה בורר (סנהדרין דף כ״ה:) כלשון רבינו:\",1,0],[8,388,12,8,\"ומה שכתב בסוחרי שביעית ולא חזרת דברים וכו'. שם בסוף הברייתא אמר רבי נחמיה לא חזרת דברים בלבד אמרו וכו' ומשמע דלפרש דברי תנא קמא אתא:\",1,0],[8,388,12,9,\"מאימתי חזרת המועל וכו'. ירושלמי כתבו סמ\\\"ג.\",1,0],[8,388,12,9,\"ומ\\\"ש או יתחייב בב\\\"ד וכו'. נ\\\"ל שלמדה רבינו מההיא דטבח שכתב בסמוך:\",2,0],[8,388,12,9,\"ומ\\\"ש וכן הטבח וכו'. שם (דף כ\\\"ה) ההוא טבח דאישתכח דנפיק טרפה מתותי ידיה פסליה ר\\\"נ ועבריה אזל ורבי מזייה וטופריה ואסיקנא התם שאינו כשר עד שילבש שחורים וכו' ויחזיר אבדה וכו' אי נמי יוציא טרפה בדבר חשוב וסובר רבינו דהא עובדא בשוחד ובודק לעצמו ומוכר לאחרים מיירי ומשום הכי לא הכשירוהו עד שילבש שחורים וכו' דכיון דהוי מילתא דממון מצריכין ביה הני מילי לאכשורי לשיתברר לנו שחזר בו מחמדת ממון אבל השוחט לאחרים ויצאה טרפה מתחת ידו כיון דלאו מידי דממון הוא כיון שעשה תשובה מתכשר אבל תשובה מיהא בעי וכן נראה מדברי רבינו שכתב שהרי הוא בכלל אוכלי טרפה שהם פסולים לעדות נראה שטעם הפסול ביוצא טרפה מתחת ידו לפי שכיון שהוא מאכיל הטריפות חזקה שגם הוא אוכל והוה ליה עובר על לאו דובשר בשדה טרפה שא\\\"ת שאינו נפסל אלא מפני שהוא מאכיל טרפות ועבר על ולפני עור וכו' הא לא מיפסיל בהכי דאינו נפסל אלא כשעבר עבירה שחייבין עליה מלקות וכמ\\\"ש רבינו בפרק עשירי ואלפני עור לא לקי אלא ודאי מש\\\"ה מיפסיל דחשיד הוא שגם הוא אוכל וזהו שכתב\",3,0],[8,388,12,9,\"רבינו שהרי הוא בכלל אוכלי טרפות שהם פסולים לעדות כלומר שכל מאכילי או אוכלי טרפה בין של עצמם בין של אחרים פסולים הם ומטעמא דכתיבנא לא נשתנה דינם אלא שהמאכילים משל אחרים בתשובה כשרים ומאכילים משל עצמם אינם כשרים עד שילבש שחורים וכו' ויחזיר אבידה או יוציא טריפה וכו'. זה נ\\\"ל שהוא מבואר בדברי רבינו אבל הוצרכתי להאריך לפי שמצאתי כתוב בח\\\"מ סי' ל\\\"ד ז\\\"ל לשון הרמב\\\"ם טבח שבודק לעצמו ומכר לאחרים ויצאה טריפה מתחת ידו יראה מלשונו שהבודק לאחר אינו נפסל אם יצאה טריפה מתחת ידו ע\\\"כ ויש לתמוה עליו שמאחר שהיה מפרש כן בדברי רבינו למה לא כתב כן בשם אביו הרא\\\"ש שגם הוא ס\\\"ל דההוא דטבח שיצתה טרפה מתותי ידיה ביש לו בה הנאת ממון הוא שכך כתב בפסקיו ובשאר כל ממון אם בא לידו באיסור ורוצה לעשות תשובה צריך להוציא הממון מתחת ידו כדחזינן לעיל גבי חשוד על הטריפה דאין מקבלין תשובתו עד שיתברר על ידי ממון אחר ששב בתשובה שלימה כ\\\"ש שבאותו ממון של איסור צריך להוציא מתחת ידו עכ\\\"ל אלמא דבההיא דחשוד על הטרפה בשיש לו בה הנאת ממון עסקינן. ולי נראה שאין הדברים אמורים אלא לענין חזרה דביוצא טרפה מתחת ידו והיה מוכר לאחרים אינו חוזר לכשרותו עד שילבש וכו' אבל היוצא מתחת ידו טרפה ואינו שלו נהי דמיפסיל אבל בתשובה מתכשר וכמ\\\"ש. ומיהו אפשר לקיים דברי הטור בסברת רבינו דטבח שיצתה טרפה מתחת ידו אם אין לו בה הנאת ממון לא מיפסל משום דאין לו בה הנאה לא חשדינן ליה במזיד אלא בשוגג ומאי דאמרינן או יוציא טריפה בדבר חשוב היינו לעצמו דאילו לאחרים מאי איכפת ליה אי הוי דבר חשוב או לא ועוד שהרי העבירוהו והוא הלך שם לשוב בתשובה ואיך יעבור גזירתם.\",4,0],[8,388,12,9,\"ומ\\\"ש רבינו שיקרעו שטרותיהן מעצמן כלומר שאם ב\\\"ד כפו אותם על כך לא עלתה להם תשובה כיון שבאונס עשו וביאר רבינו במלוי ברבית שצריך שיהיו מעצמן לכולם:\",5,0],[8,388,12,10,\"וכן עד זומם וכו'. נ\\\"ל שגם זה למד ממעשה דטבחא שכתבתי בסמוך:\",1,0],[8,388,13,1,\"הקרובים פסולים וכו' עד כולן פסולים מדבריהם. פרק זה בורר (סנהדרין דף כ״ז:) אמתניתין דואלו הן הקרובין שיילינן מה״מ דת״ר לא יומתו אבות על בנים וכו' בעדות בנים ובנים לא יומתו על אבות בעדות וכו' אשכחן אבות לבנים ובנים לאבות וכל שכן אבות להדדי בנים לבנים מנלן א״כ לכתוב קרא לא יומתו אבות על בן מאי בנים דאפי' בנים להדדי וכו' אשכחן קרובי האב קרובי האם מנלן אמר קרא אבות אבות תרי זימני אם אינו ענין לקרובי האב תנהו ענין לקרובי האם ע״כ בגמרא, ופירש״י לא יומתו שני אבות בעדות בניהם ועל כרחיך הני שני אבות באחין קא משתעי שהן קרובים מן הכל דבאב ובנו לא מצי למימר דאם כן לא הוה קרי להו אבות דחד אב וחד בן נינהו וכו' אשכחן אבות לבנים ראובן לבן שמעון דהיינו אחי אביו ובנים לאבות בן שמעון לראובן דהיינו בן אחיו וכל שכן אבות להדדי דהא בנים מכח דידהו קא אתו עכ״ל. וסובר רבינו שכל מה שאנו דורשים בפירוש הכתוב הוא מדאורייתא ומה שנדרש באם אינו ענין כיון שפשט הכתוב אינו מורה עליו מיקרי דברי סופרים ואם תאמר והלא גם שם מסיים בברייתא אשכחן לחובה לזכות מנלן א״ק יומתו יומתו תרי זימני אם אינו ענין לחובה תנהו ענין לזכות אשכחן בדיני נפשות בדיני ממונות מנא לן א״ק משפט אחד יהיה לכם משפט השוה לכם וא״כ נאמר דדוקא עדות לחובה ובדיני נפשות הוא דפסיל מדאורייתא אבל לזכות ובדיני ממונות לא מיפסלי אלא מדרבנן כיון שלא למדום אלא באם אינו ענין. וי״ל דבשלמא קרובי האם פשט הכתוב אינו מורה על פסולם כלל דלא פסל אלא קרובי האב דוקא אבל גבי זכות אע״ג דנקט לחובה לית לן למימר דדוקא נקט פיסולא לחובה ולא לזכות דמ״ט איכא לפלוגי בינייהו אלא ודאי נקט חובה וה״ה לזכות ואדרבה אית לן למימר השתא לחובה דיש ידים מוכיחות דקושטא קאמרי דהא קרובים רחמי להדדי ואי לאו קושטא לא הוו מסהדי אפילו הכי לא מהימני לזכות דיש לומר דמשקרי כדי להיטיב לקרובים לא כל שכן דלא מהימני ולגבי דיני ממונות כיון דודאי לא מהימני לזכות ה״ה לחובה ולא מפלגינן בינייהו כי היכי דלא מפלגינן בדיני נפשות בין זכות לחובה אי נמי דאית לן למימר השתא ומה כשהקרוב בא לחייב מיתה לקרובו שהשכל גוזר דקושטא קאמר שאפילו כשהוא אמת דרכו להעלימה כדי להצילו השתא דמסהיד למקטליה בצדק כל אמרי פיו אפי' הכי אשמעינן קרא דלא מהימן לשאר עדיות לא כל שכן דלא מהימן וקרוב לזה כתב הרב בספר מצות אשר לו מצוה רפ״ח וא״כ בלאו דרשא דאם אינו ענין הוה אמרינן דפסילי לנפשות וממונות בין לזכות בין לחובה ולא איצטריך להו למידרש לזכות אלא משום דאייתר להו יומתו וכדאמרי' בעלמא מילתא דאתיא בק״ו טרח וכתב לה קרא ואיידי דדריש לזכות דריש נמי לדיני ממונות ממשפט אחד יהיה לכם ולאו להאי דרשא בלחוד אייתר דמיניה ילפינן לכמה דברים שדיני ממונות ודיני נפשות שוים וכדתנן (דף ל״ב) אחד דיני ממונות ואחד דיני נפשות בדרישה וחקירה שנאמר משפט אחד יהיה לכם כללא דמילתא (דמלתא) שלזכות ולדיני ממונות מפשט הכתוב נלמוד כן ולכך אמר דפסילי מדאורייתא אבל קרובי אם אדרבה פשטיה דקרא משמע אבות ולא אם ולהכי אמר דהוי מדבריהם. זה נראה לי להעמיד דברי רבינו:\",1,0],[8,388,13,2,\"הגרים אינם בדין הקרובים וכו'. יבמות פ' נושאין על האנוסה גר שנתגייר כקטן שנולד דמי ומותרין לישא זה אשתו של זה אם מת או גירשה ואמר רבא נמי התם (דף צ\\\"ח) דאמור רבנן אין אבות לעכו\\\"ם לא תימא משום דשטופי זמה דלא ידיע אבל ידיע חיישינן דהא שני אחין תאומים דטפה אחת היא ונחלקה לשתים וקתני סיפא לא חולצים ולא מייבמין וכתב רבינו שנתגיירו כלומר שהיתה הורתם ולידתם שלא בקדושה דאילו הורתם שלא בקדושה ולידתם בקדושה הרי הם אחים מן האם ופסילי מדרבנן ואפשר דאע\\\"ג דלידתם בקדושה אם הורתם שלא בקדושה לאו אחים נינהו ולישנא דנתגייר שייך אפילו נתגיירה אמו כשהיא מעוברת שאינו כן כמ\\\"ש בביאור ח\\\"מ וביבמות פרק כיצד (דף כ\\\"ב) אמר רב נחמן (גרים) הואיל ואתו ליד נימא בהו מילתא אחים מן האם לא יעידו ואם העידו עדותן עדות אחים מן האב מעידין לכתחלה אמימר אמר אפילו אחים מן האם נמי מעידין לכתחלה ומאי שנא מעריות (דאמרינן התם דאסורות) ערוה לכל מסורה עדות לב\\\"ד מסורה ופירש\\\"י ערוה לכל מסורה הכל נושאין נשים ואי שרית לקיימה אתי נמי למישרי ערוה בישראל דכ\\\"ע לא ידעי דטעמא דגר משום דכקטן שנולד דמי עדות לב\\\"ד מסור ואי נמי מכשרת עדות אחים גרים לא אתו לאכשורי אחים ישראל דב\\\"ד ידעי דגר שנתגייר כקטן שנולד דמי:\",1,0],[8,388,13,3,\"האחין זע\\\"ז וכו'. בתרא פ' י\\\"נ (דף קכ\\\"ח) שלח ליה ר' אחא לרב יוסף בר חמא הלכתא שלישי בשני כשר רבא אמר אף בראשון מר בר רב אשי אכשר באבא דאבא ולית הלכתא כמר בר רב אשי ע\\\"כ בגמ' ומפרש רבינו דמר בר רב אשי סבר דשלישי בראשון הוא ומש\\\"ה אכשר ביה ולית הלכתא כוותיה דאב ובנו ראשון בראשון הוא כמו אח ואחיו שהם ראשון בראשון והוה ליה אבא דאבא שני בראשון וכ\\\"פ הרי\\\"ף והרא\\\"ש ז\\\"ל ודלא כרשב\\\"ם שפי' ולית הלכתא כמר בר רב אשי דבני בנים עד אלף דורות לא יעידו לאבותיהם דבן ירך אביו הוא ופסק רבינו כרבא וכ\\\"פ הרי\\\"ף ורשב\\\"ם ודלא כרבינו תם וה\\\"ג שפסקו שאין הלכה כרבא אלא כרב דאמר פ' זה בורר שלישי בראשון פסול:\",1,0],[8,388,13,6,\"כל אשה שאתה פסול לה וכו'. סנהדרין פרק זה בורר (סנהדרין דף כ״ח:) רב איקלע למיזבן גוילי ובעו מיניה מהו שיעיד אדם באשת חורגו בסורא אמרי דבעל כאשתו בפומבדיתא אמרי אשה כבעלה והני תרי לישני לא פליגי אהדדי אלא מר אמר חדא ומר אמר חדא וכ״כ נמוקי יוסף והכי משמע בירושלמי:\",1,0],[8,388,13,7,\"כל שתי נשים וכו'. פ' זה בורר שם ת\\\"ר חורגו לבדו ר' יוסי אומר גיסו פי' פסולין לעדות ואסיקנא התם דהכי קאמר חורגו לבד אבל גיסו הוא ובנו וחתנו ואתא ר' יוסי למימר גיסו לבדו וכ\\\"ש חורגו וכו' א\\\"ר יהודה אמר שמואל הלכה כר' יוסי. ואיכא למידק דהיכי קתני גיסו לבדו אי פירוש גיסו היינו אחי אשתו הא בנו הוי פסיל להאי דהא בעל אחות אביו הוא ואי פירוש גיסו שהם בעלי שתי אחיות הא הוי לבנו דגיסו בעל אחות אמו ותירץ הרי\\\"ף דגיסו לבדו לא אתא למעוטי אלא בן גיסו באשה אחרת והביא ראיה מהירושלמי אבל רש\\\"י והתוס' פירשו דגיסו לבדו אתא למעוטי חתנו אבל לא מיעט בנו ולזה הסכים הרא\\\"ש בפסקיו ופי' רש\\\"י והתוס' לא כיון אליו רבינו שהרי כתב שאין אדם מעיד לחתן אחות אשתו ולכן תמהני על ההגהות שעל מ\\\"ש שכל שתי נשים שהן זו עם זו שני בשני בעליהן מעידין זה לזה כתבו וכן פר\\\"י דתרי בעל כאשתו לא אמרינן בקורבה שנתרחקה קצת ואפילו לקח זה האשה וזה בת אחותה וכל שכן באלו והרי רבינו כתב בסמוך שחתן אחות אשתו פסול לו אלא ודאי דעת רבינו כהרי\\\"ף שכן כתב וכן לא יעיד לבן אחות אשתו ולא לבעל בת אחות אשתו וכו' לבעל בת אחות אשתו הוי ראשון בשני ואמרינן תרי זימני בעל כאשתו וא\\\"כ צריך לדקדק מנין לו לרבינו דכשהנשים שני בשני בעליהן כשרים זה לזה. ונראה שלמד כן מהירושלמי שפירש דהב\\\"ע דגיסו לבדו פסול ולא בנו ולא חתנו בשיש לו בנים וחתנים מאשה אחרת אבל מאותה אשה אף חתנו פסול והרי הוא וחתן אחות אשתו נשותיהן ראשון בשני נינהו ואפילו הכי פסול ממילא שמעינן דלא מיפסיל אלא דוקא בההוא גוונא אבל (כששתי הנשים שני בשני) מיהא כשר כיון שלא מצינו מי שאמר תרי זימני בעל כאשתו בשני בשני וכיון דמעיקרא הוה מיבעיא לן אי אמרינן בעל כאשתו אפילו חדא זימנא מסתיין לפסול היכא דאיתמר בהדיא אבל היכא דלא אתמר (הא ודאי) כשר ולפי שרבינו למד דין זה ממה שאמרו חורגו וגיסו לבדם לכך גבי ראשון בראשון כתב המשל כגון שלקח זה אשה וזה בתה שהוא בעל חורגתו והו\\\"ל חורגו וכן בעלי אחיות דהיינו גיסו אבל בשני בשני לא כתב משל משום דמדיוקא קא אתי ואין המשל כתוב בגמ' ומתוך מה שלמדנו דדוקא כשהשתי נשים זו עם זו שני בשני הוא דבעליהן כשרים אבל לא כשהן שני בראשון:\",1,0],[8,388,13,10,\"כל איש שאין אתה מעיד לו וכו'. למד כן מהדין שכתב בסמוך אחי האח מן האם מעידין זה לזה ואע\\\"פ שאחיו של זה הוא אחיו של זה לפי שאין ביניהם קורבה כלל וזה כיוצא בו וכתב רבינו כאן דין זה להיותו נוגע לענין אישות:\",1,0],[8,388,13,11,\"אבי כלה ואבי חתן וכו'. סנהדרין פ' זה בורר (סנהדרין דף כ״ח:) מימרא דרב חסדא:\",1,0],[8,388,13,12,\"אחי האח מן האם וכו'. גם זה שם מימרא דרב חסדא:\",1,0],[8,388,13,13,\"האיש עם אשתו ראשון בראשון. כלומר דאי הוה שני בשני לא היה פסול להעיד לקרובותיה וכמו שכתב רבינו בסמוך:\",1,0],[8,388,13,13,\"לפיכך אינו מעיד לא לבנה וכו'. שם במשנה וברייתא חורגו פסול וכבר נתבאר בפ' זה דבעל כאשתו ואשה כבעלה ולכך פסול לאשת בנה ולבעל בתה:\",2,0],[8,388,13,13,\"ולא לאביה וכו'. שם (דף כ\\\"ח) א\\\"ר נחמן אחי חמותי לא יעיד לי בן אחי חמותי ובן אחות חמותי לא יעיד לי וא\\\"כ ודאי דפסול הוא לחמותו ולחמיו וחמיו הוא ג\\\"כ מפורש במשנה והא אמרינן דבעל כאשתו ואשה כבעלה וא\\\"כ הרי בעל חמותו ואשת חמיו פסולין ונ\\\"ל שלא היתה כוונת רבינו כאן אלא ללמדנו דאשה כבעלה בכל הני דאילו להשמיענו קרובי האשה הפסולים הו\\\"ל לכתוב גם אחי חמותו ובן ובת אחי חמותו:\",3,0],[8,388,13,14,\"אשתו ארוסה וכו'. שם אמר רבה בר בר חנה מעיד אדם לאשתו ארוסה ודחו ואמרו מאי דעתיך כדאמר ר' חייא בר אמי אשתו ארוסה לא אונן וכו' מתה אינו יורשה וכו' התם בשארו תלה רחמנא אכתי לאו שארו היא הכא משום איקרובי דעתא הוא והא איקרבא דעתיה לגבה וסובר רבינו דדוקא לגבה איקרבא דעתיה אבל לגבי קרוביה אכתי לא איקרבא ושיעור לשון רבינו כך אבל אם העיד לקרובי ארוסתו וכו' אין פוסלין אותה עד שישאנה ואח\\\"כ אם יעיד עליה יפסלו עדותו ומשמע מדברי רבינו שלכתחלה אין מקבלין עדות הארוס לקרובי ארוסתו ואם העיד אין פוסלין עדותו והם דברי הרי\\\"ף בתשובה כמ\\\"ש העיטור באות קו\\\"ף קבלת עדות וכתבו המרדכי בהגהות סנהדרין וכן מצאתי כתוב בשם גאון:\",1,0],[8,388,13,15,\"זה שפסלה תורה וכו' אלא גזירת הכתוב הוא. בב״ב ס״פ מי שמת (בבא בתרא דף קנ״ט):\",1,0],[8,388,13,15,\"לפיכך האוהב והשונא וכו'. פרק זה בורר (סנהדרין דף כ״ט) אליבא דרבנן וכן פסק הרי״ף ז״ל:\",2,0],[8,388,14,1,\"כל מי שאין אתה מעיד לו וכו'. סנהדרין פרק זה בורר (סנהדרין דף כ״ז:) משנה היה קרוב ונתרחק הרי זה כשר רבי יהודה אומר אפילו מתה בתו ויש לו בנים ממנה הרי זה קרוב ובגמרא (דף כ״ח:) אמר רבא אמר רב נחמן אין הלכה כר' יהודה:\",1,0],[8,388,14,2,\"מי שהיה יודע לחבירו עדות וכו'. בתרא פרק יש נוחלין (בבא בתרא דף קכ״ח) ברייתא כלשון רבינו כתבה הרי״ף פרק זה בורר.\",1,0],[8,388,14,2,\"ומ\\\"ש אע\\\"פ שיכול לכוין מדת הקרקע. שם אמר שמואל דסומא אם מכוין מדת הקרקע ומסיים מצריה כשר ואידחיא ליה מדתניא האי ברייתא סתמא דסומא פסול ולא מכשר אלא בפתוח ונסתמא וחזר ונתפתח:\",2,0],[8,388,14,3,\"ואלו הן הדברים וכו' עד אינו נאמן. משנה וברייתא בכתובות סוף פרק ב' (דף כ\\\"ח):\",1,0],[8,388,14,3,\"נאמן אדם לומר זה כתב ידו של אבי וכו'. כבר נתבאר בדברי רבינו פרק שביעי:\",2,0],[8,388,14,3,\"זכור אני בפלונית וכו'. שם מאי טעמא כיון דרוב נשים בתולות נשאות גלויי מילתא בעלמא הוא:\",3,0],[8,388,14,3,\"ושהמקום הזה בית הפרס. פירושו כתב הר\\\"ן דאי איכא בקעה שמוחזק לנו שיש בית הפרס והבקעה כולה בספק טומאה כי מסהיד שהמקום הזה בית הפרס ושכל מה שהוא חוץ ממנו טהור מהימן. אבל הראב\\\"ד כתב בית הפרס לשון טומאה קלה הוא כלומר כבר הוקלה טומאתו שנדש ונופח והוא טהור לעושה פסח ומה טעם נאמן בו משום דטומאת בית הפרס אפילו קודם דישה ונפוח אינה אלא מדרבנן שמא גלגלה עצם כשעורה לשם ע\\\"כ. ומכל מקום הדבר נראה שאין עדות זו אלא להקל דומיא דכל הנך דמתניתין אבל לא שיהא נאמן להחמיר שאם נאמינהו להחמיר בדרבנן כל שכן בדאורייתא עכ\\\"ל הר\\\"ן ז\\\"ל:\",4,0],[8,388,14,3,\"ועד כאן היינו באים בשבת שצמצום התחום עד אלפים אמה בלבד מדבריהם. כלומר מדאורייתא אינו אסור אלא חוץ לשנים עשר מיל כמו שנתבאר בדברי רבינו פרק כ\\\"ז מהלכות שבת:\",5,0],[8,388,14,3,\"ושהיינו מוליכים חלה ומתנות לפלוני כהן על ידי עצמו. פירוש כך העיד התינוק על ידי היה אבי שולח לו חלה ומתנות אבל אם אמר שהיה שולחם על ידי אחר אינו נאמן דדילמא לא דק:\",6,0],[8,388,14,3,\"ואכלנו בקצצה של פלוני וכו'. שם (דף כ\\\"ח:) תנו רבנן כיצד קצצה אחד מן האחים שנשא אשה שאינה הוגנת לו כלומר שיש לה פסול משפחה באים בני משפחה ומביאין חבית מליאה ושוברין אותה באמצע רחבה ואומרים אחינו בית ישראל שמעו אחינו פלוני נשא אשה שאינה הוגנת לו ומתיראים אנו שמא יתערב זרעו בזרענו בואו וקחו לכם דוגמא פירוש אות וסימן זכרון לדורות שלא יתערב זרעו בזרענו. ודע שהראב\\\"ד מפרש דמשפחה זו פסולה היינו לענין דאי הוו תרי פסלינן לה אפומייהו ואי חד הוא חיישינן לה ולא מכרזינן עלה ומשפחה זו כשרה אי תרי נינהו מכשרינן לה אפומייהו ואף על גב דהות קיימא בחזקת פסלות וכן שאכלנו בקצצה של בת פלוני דאי תרי נינהו פסלינן לזרעא אפומייהו ואי חד הוא חיישינן לה אבל הר\\\"ן כתב דכי אמר שנאמן התינוק לומר אמר לי אבא משפחה זו פסולה ומשפחה זו כשרה מיירי במשפחות כהנים שיצא עליה חשש פסול כהונה ואותה משפחה נחלקה לבתי אבות וקאמר שנאמן התינוק להכשיר משפחת בית אב אחד שיעיד ויאמר אותו חשש על משפחת בית אב פלוני הוא ולא על משפחת בית אב פלוני ולא נקטה באומר משפחה זו כשרה בלבד לפי שאם היינו מוחזקין באיסור משפחה אחת אין התינוק נאמן להכשירה אפילו לתרומה מדרבנן אבל כשאנו מוחזקים בכלל שיש פסול באותה משפחה סתם ואין אנו יודעים בבירור אם על כולה אם על מקצתה נאמן התינוק לבד לברר בשם אביו ולומר אותו פסול על משפחת בית אב פלוני הוא ולא על משפחת בית אב פלוני וסומכים על עדות זו להאכיל אותו שהוא מכשיר תרומה דרבנן אבל ודאי אין התינוק נאמן לפסול שזה לא שמענו בשום מקום והיאך יהא נאמן במה שאומר בשם אביו והלא לא היה אביו נאמן דהא קיימא לן אין ערער פחות משנים אלא ודאי כדאמרן ומשפחה זו פסולה דקתני בשביל הכשר האחרת נקטה כדתנן שהמקום הזה בית הפרס וכמו שפירשתי וכתב שדברי רבינו מטין לדבריו שנראה מדבריו שרצונו לומר שאין תלוי אם נאמינהו בעדות זו או לא נאמינהו אלא להאכילו בתרומה של דבריהם או לדחותו ממנה שאילו היה סובר שהיה נאמן לדחות את הכהן המוחזק בכשרות מתרומה של דבריהם כל שכן שנאמן לדחותו משל תורה ואף על פי כן סתם הדברים יותר מדאי וכתב עוד דאף על גב דאמרינן בגמרא אמתניתין והוא שיהא גדול מעיד עמו לא קאי אכולהו אלא אזה כתב ידו של אבא ויצתה בהינומא ושהיה חולק עמנו על הגורן למסקנא דהתם דמוקמינן לה כר' יהודה דאמר מעלין מתרומה ליוחסין והילכך לתרומה נמי בעינן שנים כיוחסין אבל אשארא דתנן במתניתין לא בעינן ולאותן שנאמרו בברייתא כיון שלא נאמרה אותה מימרא עליהם פשיטא דלא בעינן גדול מעיד עמו אלא בעדותו לחודה סגי והרב המגיד כתב בפרק ט\\\"ז מהלכות אישות שדעת רבינו דלא קאי והוא שיהא גדול מעיד עמו אלא אזה כתב ידי בלבד:\",7,0],[8,388,14,4,\"אם היה עכו\\\"ם או עבד וכו'. ג\\\"ז שם ומפרש טעמא בגמרא דאע\\\"ג דהוה דעתיה לאיגיורי כיון דעכו\\\"ם הוה לא הוה דייק:\",1,0],[8,388,14,5,\"מי שהיה יודע לחבירו בעדות וכו'. בבא בתרא פרק מי שמת (בבא בתרא דף קנ״ט) הובאה בהלכות פרק זה בורר כלשון רבינו ואמר בגמרא גבי גזלן כגון שהוחזק כתב ידו בבית דין וכתבו התוס' דעיקר הפירוש שראו בית דין כתב ידו זה קודם שנעשה גזלן דליכא למימר שאחר כך חתם וכ״כ הרי״ף ומשמע דלאו דוקא ב״ד דהוא הדין ראוהו עדים קודם שנעשה גזלן מהני דהא ליכא למיחש שמא אחר כך חתם וכ״נ מדברי הטור חושן משפט סי' מ״ו ואמרי' התם דלגבי חתנו אע״פ שלא הוחזק כתב ידו בב״ד אחרים מעידים עליו משום דלא פסלינן משום דלא מהימן ומכאן למד רבינו הטעם שכתב לחלוק בין פסולו מחמת עבירה למחמת קורבה:\",1,0],[8,388,14,6,\"שטר שיש בו שני עדים בלבד. כלומר דאילו היו יותר משנים מן הסתם יש לנו להחזיק שטר זה בכשר כמו שנתבאר ספ״ה ודין זה בסנהדרין פרק זה בורר (סנהדרין דף כ״ח) ההיא מתנתא דהוו חתימי עלה תרי גיסי וסבר רב יוסף לאכשורה ואותביה אביי ומסיק שאפילו הביא עדים כשרים שמסר לו שטר מתנה זו בפניהם לא מתכשרא דמודה רבי אליעזר במזוייף מתוכו שהוא פסול (משום דבמאי קני ליה בהאי שטרא האי שטרא חספא בעלמא הוא) וכתבו התוס' בס״פ מי שמת (בבא בתרא דף קנ״ט בד״ה ואע״פ) שאם היו שנים מעידים ואח״כ נעשו קרובים שאחר מעיד על כתב ידם שמכירים אותו ולא חיישינן שמא היום נתן:\",1,0],[8,388,14,7,\"הכותב כל נכסיו לשני בני אדם וכו'. ירושלמי הובאה בהלכות פ\\\"ק דמכות פלוגתא דר\\\"י ור\\\"ל ופסק כר\\\"י וכן דעת רבינו ודלא כרבינו האיי ורבינו אפרים והרמ\\\"ה שפסקו כר\\\"ל דבתרי גופי לד\\\"ה פלגינן דבורא. והוי יודע דלשון הכתוב בירושלמי כך הוא כתב כל נכסיו לעבדו את אמר הוא גיטו הוא מתנתו מה את עבד לה בגט הוא ועררו בטל או במתנה הוא ועררו קיים יבא כהדא כתב כל נכסיו לשני בני אדם כאחת והיו העדים כשרים לזה ופסולים לזה רבי אילא בשם ר' אחי איתפלגון ר' יוחנן ור\\\"ל חד אמר מאחר שהם פסולים לזה פסולין לזה וחד אמר כשרים לזה ופסולים לזה. ומאחר שרבינו כאן והרי\\\"ף ז\\\"ל פ\\\"ק דמכות פסקו דמאחר שהם פסולים לזה פסולים לזה קשה היאך הרי\\\"ף פ\\\"ק דגיטין ורבינו פרק שביעי דהלכות עבדים פסקו בכותב כל נכסיו לעבדו דפלגינן דבורא וקנה עצמו אע\\\"פ שלא קנה הנכסים עד שיתקיים השטר בחותמיו והרי בירושלמי תלאום זו בזו. והר\\\"ן כתב ביישוב זה ואפשר דהתם הכי קאמר דלריש לקיש דקאמר התם פלגינן דיבורא כל שכן הכא דפלגינן גבי כותב כל נכסיו לעבדו ומיהו לרבי יוחנן אפשר דבכותב נכסיו לעבדו פלגינן דיבורא משום דעבד ונכסים תרי גופי נינהו אבל כותב כל נכסיו לשני בני אדם הוי עדות שבטלה מקצתה בטלה כולה ע\\\"כ וזה דוחק גדול שהרי כשאומרים בירושלמי אתיא כהדא הוא כמו כשאומרים בגמרא דילן כתנאי שר\\\"ל דבר זה פלוגתא דהני תנאי הוא ויותר נראה לומר דאין הכי נמי דלדעת ר' אילא איפליגו רבי יוחנן ור\\\"ל בכותב כל נכסיו לעבדו נמי אלא דאנן כיון דחזינן דבפלוגתא דרבי יוחנן וריש לקיש ודאי פסקינן כר\\\"י אי משום דכוותיה קי\\\"ל לגבי ר\\\"ל אי משום דמתניתין מסייעא ליה כדאמרינן התם וכיון דבגמרא דילן איפליגו אביי ורבא בכותב כל נכסיו לעבדו וס\\\"ל לרבא דפלגינן דיבורא וכלל גדול בידינו דהלכתא כוותיה לגבי אביי ואחר שלא פסק שם הגמרא כאביי אלמא לא סבירא ליה דרבי אילא דלא דמיא האי פלוגתא להך דלגבי כותב כל נכסיו לעבדו נהי דלגבי נכסים בעינן קיום אבל לגבי עבד עצמו לא בעינן משום דהוי ככותב בשטר אחד הריני משחרר פלוני עבדי והריני נותן נכסי במתנה לאיש פלוני דלגבי עבד ודאי לא בעינן קיום והכי נמי כיון דמתחלה עבד ועכשיו בן חורין ובעל נכסים בבחינת עצמו הוי כאומר הריני משחרר פלוני עבדי ובבחינת הנכסים הוי כאומר נכסי נתונים לאיש פלוני דהא פנים חדשות באו כאן והוה ליה תרי עובדי בתרי גופי דפלגינן דבורא אבל כשכתב כל נכסיו לשני בני אדם כאחד כלומר שכתב כל נכסי נתונים לפלוני ולפלוני שהוא מעשה אחד בשני גופים לא פלגינן דיבורא ופשיטא דכגמרא דידן קי\\\"ל ולא כרבי אילא ולפי שיטה זו פשוט הוא שאילו כתב שדה פלונית נתונה לפלוני ושדה פלונית לפלוני שלאותו שהם כשרים לו מהניא מתנה שהרי שני מעשים כשני גופים הם וכיון שרבינו כתב דין זה כך אני מכריע לומר שזה דעת רבינו ומכאן למדו וכתב בעיטור דמסתברא דירושלמי בנכסים שאין מוחלקין אבל מוחלקין כשרים לשאינו קרוב. אבל בעבד המביא גיטו וכתוב בו עצמך ונכסי קנויים לך פלגינן דיבורא. אחר כך מצאתי שכתב הרא\\\"ש ספ\\\"ק דמכות ורבינו יואל הלוי כתב הלכה כר\\\"י וכתב דרבינו לית ליה ההוא דירושלמי דמדמי להו אהדדי ומודה ר\\\"י בכותב כל נכסיו לשני בני אדם דמאחר שהם פסולים לזה פסולים לזה וטעמא משום דאתי לאיחלופי בשטרות דעלמא שלא יאמרו קרוב כשר להעיד אבל בגט שחרור לא חיישינן לאיחלופי הואיל וצריך לומר בפני נכתב ובפני נחתם וכהאי גוונא אמרינן בריש גיטין ובפרק ב' דגיטין עכ\\\"ל. ולמדתי משם שמה שכתבתי דגמרא דידן לא ס\\\"ל דאתי כהדא דההיא דירושלמי שיטה נכונה היא דהכי סבירא ליה לרבינו יואל:\",1,0],[8,388,15,1,\"כל עדות שתבא הנאה לאדם וכו'. בתרא פרק חזקת (בבא בתרא דף מ״ג) ואמרינן התם דלא סגי כשיסלק עצמו מן הקרקע כשיאמר דין ודברים אין לי על שדה זו או אין לי עסק בה או ידי מסולקות הימנה דלא אמר כלום עד שיקנו מידו והקשו בתוספות דהא בעינן תחלתו וסופו בכשרות כמו שנתבאר פרק י״ד והכא הוי תחלתו בפסלות והוי כמו קרוב ונתרחק ותירצו דלא שייך תחלתו בפסלות הכא כיון שאין פיסולו תלוי בגוף אלא בממון:\",1,0],[8,388,15,2,\"בני העיר שנגנב ס\\\"ת שלהם. ברייתא שם ואמרו בגמרא דכיון דלשמיעה קאי והוי נוגע בעדות עד דאזיל לעיר אחרת לדור אין דנין ואין מעידין אנשי אותה העיר עליו:\",1,0],[8,388,15,3,\"האומר תנו מנה וכו' במה דברים אמורים וכו'. ג\\\"ז ברייתא וגמ' שם:\",1,0],[8,388,15,4,\"קרקע שבין וכו'. שם (דףמ\\\"ב ע\\\"ב) אמר שמואל וכו' השותפין מעידין זה לזה ופריך בגמרא (דף מ\\\"ג) אמאי נוגעים בעדותן הן כלומר דכל זמן שלא חלקו לגמרי אם יטול מערער מן השדה יפסידו שניהם ותירצו בשקנו מידו שסילק עצמו מכל השדה והקשו עוד וכי קנו מידו מאי הוי פי' דסוף סוף נוגע בעדות הוא שאם יבא ב\\\"ח דידיה יטרוף אותה שדה שסילק עצמו ממנה אם תשאר ביד השותף אבל אם יטלנה המערער ודאי לא יטרוף ממנו והאי הנאה היא לדידיה דלא ליהוי לוה רשע ולא ישלם ותירצו כשקבל עליו אחריות כלומר שאם יבא ב\\\"ח דידיה ויטרפנה ממנו ישלמנה לו דהשתא מאי איכפת ליה להעמידה בפני ב\\\"ח הא לגבי לוקח נמי כיון דמקבל עליה אחריות מיקרי רשע וזהו שכתב\",1,0],[8,388,15,4,\"רבינו אלא אם כן סילק עצמו ממנה וכו' ושאם בא ב\\\"ח וכו' כלומר וגם קבל על עצמו שאם בא ב\\\"ח שלו וטרפה וכו':\",2,0],[8,388,15,5,\"העורר על השדה וכו'. שם (מ\\\"ו:) שלח ליה ר\\\"נ בר רב חסדא לר\\\"נ ברבי יעקב אריס מעיד או אינו מעיד הוה יתיב רב יוסף קמיה אמר ליה הכי אמר שמואל מעיד והתניא אינו מעיד ל\\\"ק הא דאיכא פירא בארעא הא דליכא פירא בארעא כלומר דכי איכא פירא לא יעיד דנוגע בעדות הוא לפי שהיה אותו נותן למחצה לשליש ולרביע ואם יזכה המערער הרי שלא ברשותו ירד וידו על התחתונה אבל לית ליה פירא בארעא וגם לא טרח בה שנה זו לעשות בה צורכי זריעה תו ליכא למיחש למידי שהרבה שדות ימצא להיות בהם אריס:\",1,0],[8,388,15,5,\"אבל השוכר אם לקח השכירות בידו וכו'. שם בראש הפרק (דף כ\\\"ט) לענין חזקת שלש שנים דבעינן רצופות ובתים בלילה לא ידעי כלומר ואין מעידין עליהם ואפ\\\"ה הויא חזקה ואמר התם רבה כגון דאתו בי תרי ואמרי אנן אגרינן מיניה ודרינן ביה תלת שנין ביממא ובליליא אמר ליה רב יימר לרב אשי הני נוגעים בעדותן הן דאי לא אמרי הכי אמרינן להו זילו הבו ליה אגר ביתא להאי אמר ליה דייני דשפילי פי' שפלים שאינם בקיאים בדין הכי דייני מי לא עסקינן כגון דנקיטי אגר ביתא ואמרי למאן ניתביה:\",2,0],[8,388,15,6,\"שמעון שלוה והיה ראובן ערב וכו'. פרק חזקת הבתים (בבא בתרא דף מ״ו:) ת״ר ערב מעיד ללוה והוא דאית ליה ארעא אחריתי ופרשב״ם ערב מעיד ללוה אם יצאו עסיקין על שדותיו של לוה והוא דאית ליה ללוה ארעא אחריתי שוה כנגד חוב שנתערב דאי לא הוי נוגע בעדות דב״ח יגבה ממנו. ודע ששם (דף מ״ז) אמרו קבלן אמרי לה מעיד ואמרי לה אינו מעיד ומכיון שלא חילק רבינו בין ערב לקבלן אלמא דכלשון ראשון סבירא ליה דלא מפליג בין קבלן לערב וכן כתב רבינו ירוחם לדעת רבינו:\",1,0],[8,388,15,6,\"וכן לוקח ראשון מעיד ללוקח שני וכו'. שם באותה ברייתא לוקח ראשון מעיד ללוקח שני והוא דאית ליה ארעא אחריתי פ' כגון לוי ויהודה שקנו שתי שדות מראובן בזה אחר זה וקיימא לן דאין ב\\\"ח גובה אלא מן האחרון ואם אין לו גובה משלפניו לוי ללוקח ראשון מעיד ליהודה להעמיד בידו שדה שלקח מראובן ומפרש רבינו והוא דאית ליה לראובן ארעא אחריתי שיכול להעמידה בפני ב\\\"ח דאי לא נוגע בעדות הוא ורשב\\\"ם מפרש דהוא הדין אם יש ללוקח שני קרקע אחרת שלקח מראובן דאז לא יגבה ב\\\"ח אלא מאותו קרקע של לוקח שני ורבינו לא חשש לכתוב כן דבכלל דבריו הוא דכיון דשדה זו של לוקח שני היתה של ראובן שלקחה לוקח שני אחר לוקח ראשון הוה ליה קרקע של ראובן:\",2,0],[8,388,15,6,\"כתב הראב\\\"ד דוקא בשעשאה אפותיקי עכ\\\"ל:\",3,0],[8,388,16,2,\"ראובן שגזל שדה משמעון וכו' עד וכן כל כיוצא בזה. בתרא פרק חזקת (בבא בתרא דף מ״ג:) ת״ר מכר לו בית מכר לו שדה אין מעיד לו עליה מפני שאחריותו עליו מכר לו פרה מכר לו טלית מעיד לו עליה מפני שאין אחריותו עליו מאי שנא רישא ומאי שנא סיפא אמר רב ששת רישא בראובן שגזל שדה משמעון ומכרה ללוי ואתא יהודה וקא מערער דלא ליזיל שמעון לאסהודי ליה ללוי דלאו דיהודה היא דניחא ליה דהדרא כלומר ניחא ליה דקיימא ביד לוי כי היכי דהדרא ליה שיש לו עדים שהיא שלו ואקשינן ובההוא זכותא דמפיק לה מלוי ליפקה מיהודה ומהדרינן דאמר השני נוח לי והראשון קשה הימנו ומקשינן תו ולוקמה בגזלן כלומר למה ליה למיתני מכר ליתני גזל לו בית גזל לו שדה אין מעיד לו עליה וכו' ומהדרינן משום דקא בעי למיתני סיפא מכר לו פרה מכר לו טלית דוקא מכר דהוה ליה יאוש ושינוי רשות וכגון דמית גזלן אבל לא מכר דהדרא ליה לא תנא רישא נמי מכר ואקשינן תו ולוקמיה ביורש כלומר בגזל והוריש ואתא יהודה להוציאה מיד היורש דלא ליזיל שמעון וליסהיד לבן גזלן משום דאי תיקום ארעא ביד היורש יוציאנה שמעון מידו אבל אם היא ביד יהודה אמרי' היכא דקיימא תיקום שמעינן מהכא דבין שהשדה הגזולה בידו בין מכרה בין מת והורישה אין מעיד בעלה עליה ובפרה וטלית כל שלא מת ראובן או לא מכרה אין מעיד לו ג״כ עליה אבל אם מכרה ומת כיון דמטלטלין נינהו מעיד לו עליה ואף על פי שהקשו שם על זה ודחו אוקימתא זו היינו לענין שלא נפרש הברייתא כאוקימתא זו אבל מ״מ הדין דין אמת וכן כתב שם רשב״ם:\",1,0],[8,388,16,3,\"ראובן שמכר שדה לשמעון שלא באחריות וכו'. שם (דף מ\\\"ג) אמר שמואל המוכר שדה לחבירו שלא באחריות פי' שהתנה שלא יהיה לו אחריות דאילו לא כתב אחריות בשטר הא קיימא לן אחריות טעות סופר הוא אין מעיד לו עליה מפני שמעמידה בפני ב\\\"ח ואוקמה (דף מ\\\"ה) בדלית ליה ארעא אחריתי לדידיה דאמר לא ניחא לי למהוי לוה רשע ולא ישלם ולגבי לוקח לא הוי רשע ולא ישלם דא\\\"ל להכי זבני לך שלא באחריות ורבינו כתב הדברים סתם שפשוט הוא שאם יש שדה אחרת לראובן שלא יטרוף בעל חוב לשדה זו:\",1,0],[8,388,16,4,\"ראובן שמכר פרה או טלית לשמעון וכו' עד וכן כל כיוצא בדברים אלו. פרק חזקת (בבא בתרא דף מ״ג:) סיפא דברייתא שכתבתי בסמוך מכר לו פרה מכר לו טלית מעיד לו עליה מפני שאין אחריותו עליו אמרו טעמא בגמרא (דף מ״ד:) משום דמטלטלי לא משתעבדי לבעל חוב ואפילו עשאם אפותיקי כלומר וכיון דאין בעל חוב גובה מהם אין לו הנאה בעדותו ואקשינן וליחוש דילמא אקני ליה מטלטלי אגב מקרקעי וכתב ליה דאקנה ומהדרינן דקאמרי עדים ידעינן בהאי דלא הוה ליה ארעא מעולם ואקשינן תו מדאמר רב פפא המוכר שדה שלא באחריות וכו' אם נמצאת שאינה שלו חוזר עליו וא״כ היאך יעיד לו עליה דהא אית ליה הנאה שלא יחזור עליו ומהדרינן הב״ע במכיר בה שהיא בת חמורו ורב זביד אמר אפילו נמצאת שאינה שלו אינו חוזר עליו דא״ל להכי זבני לך שלא באחריות מתוך זה נתבררו דברי רבינו. אבל קשה שכאן פסק כרב פפא דאמר נמצאת שדה שאינה שלו אפילו שלא באחריות חוזר עליו שכתב בד״א בשהיה שמעון מודה שזו הפרה והטלית וכו' ופשטא דשמעתא משמע דאליבא דרב פפא הוא דאוקימנא במכיר בה שהיא בת חמורו דאילו לרב זביד כיון שאינו חוזר עליו אפילו אינו מכיר שהיא בת חמורו מעיד לו עליה. וכן כתב נמוקי יוסף דאליבא דרב זביד בכל ענין מצי מעיד וכן רשב״ם וכן בח״מ סי' ל״ז ורבינו ירוחם בנ״ב ח״ה ובפרק י״ט מהל' מכירה כתב רבינו המוכר קרקע וכו' אפי' נודע בודאי שזו הארץ גזולה ויצאה מיד הלוקח אין המוכר חייב כלום והיינו כרב זביד גם בפ' זה כתב ראובן שמכר שדה לשמעון שלא באחריות וכו' הרי הוא רוצה שתעמוד ביד שמעון וכו' ואי קי״ל כרב פפא תיפוק לי דאם יוציאו בטענה שאינה שלו יחזור עליו ויש לומר דרבינו משמע ליה דאפילו לרב זביד בעינן לאוקומי ברייתא כשמכיר בה שהיא בת חמורו אי מוקים לה בשמכר סתם דע״כ לא פליג ארב פפא אלא כשהתנה בפירוש שאין לו עליו אחריות והיינו דאמר ליה להכי זבני לך שלא באחריות וע״כ היינו כשהתנה כן בפירוש שאל״כ הא קי״ל אחריות טעות סופר הוא וא״כ במכר לו פרה וטלית או שאר מטלטלין סתם אפילו לרב זביד בעינן שיכיר שהיא בת חמורו לשיוכל להעיד לו עליה משום דאם אינו מכיר ונמצאת שאינה שלו חוזר עליו כיון דקנה סתם וכן נראה שהיתה דעת הרי״ף שכתב ורב זביד אמר אפי' נמצאת שדה שאינה שלו וכו' ורב זביד פליג ארב פפא והלכתא כוותיה עכ״ל. ואיכא למידק דהא פשיטא דרב זביד פליג ארב פפא ומאי אתא לאשמועינן וצ״ל דאתא לאשמועינן דלא פליג רב זביד אאוקימתא דאוקימנא במכיר בה שהיא בת חמורו אלא ארב פפא לחודיה פליג וכמו שכתבתי. ועוד יש ראיה שיש לפרש דרב זביד לא פליג אאוקימתא דמכיר בה שהיא בת חמורו מדאמרי' התם (דף מ״ה) בסמוך מכריז רבא ואי תימא רב פפא דסלקין וכו' ולא אמרן אלא שאינו מכיר בה שהיא בת חמורו וכו' אמימר אמר אפי' ליכא כל הני לא מ״ט מידע ידיע דסתם עכו״ם אנס הוא ומשמע שאם הוא ישראל בעינן שיכיר בה שהיא בת חמורו ואי לאו בעי לפצויי ליה וכיון דגם אמימר הכי ס״ל ולחד לישנא גם רבא ס״ל הכי ומדמכריז ולא הוה מאן דפליג עליה אלא אמימר וגם הוא משמע דמודה בישראל דבעינן שיכיר בה שהיא בת חמורו משמע דליכא מאן דפליג בהא ואפילו רב זביד מודה בהכי וכדפרישית ולפי שיטה זו ברייתא ה״פ מכר לו בית אין מעיד לו עליה דאפילו פירות ומכר לו בהדיא שלא באחריות הוי נוגע בדבר מפני שבעל חובו גובה ממנה אבל מכר לו פרה וטלית אפשר לו להעיד עליה דכל שלא פירש שהוא מקבל עליו אחריות אין ב״ח גובה מהם מיהו אם מכרם סתם צריך שיכיר בה שהיא בת חמורו לכ״ע אבל במוכר בהדיא שלא באחריות לרב זביד אינו צריך שיכיר ולרב פפא צריך שיכיר והלכה כרב זביד ולפיכך כתב רבינו ראובן שמכר פרה וכו' ולא הזכיר שם שלא באחריות כשם שהזכיר גבי מכר שדה וטעמא משום דבעא לאשמועינן דבמוכר סתם בעינן שיכיר בה שהיא בת חמורו אבל במפרש שמוכר לו שלא באחריות לא איצטריך ליה לאשמועינן דסמך על מ״ש בפי״ט מהלכות מכירה דאפילו נמצאת שדה שאינה שלו אינו חוזר עליו והכא אשמעינן דאפילו דאינו מעמידה בפני ב״ח אינו מעיד לו עליה אא״כ מכיר בה ומיהו במכיר בה סגי אע״ג דקי״ל אחריות טעות סופר הוא מ״מ כיון שהוא מכיר בה נמצא שהמוציאה מידו אונס הוא שאנסו ואינו חוזר עליו כמבואר פי״ט מהל' מכירה וא״כ כל שמפרש בהדיא שמוכר שלא באחריות פשיטא דאפילו אינו מכיר שהיא בת חמורו שמעיד לו עליה ובהכי אתי שפיר מאי דאיכא למידק דבגמרא קדים ומשני דקאמרי עדים ובתר הכי משני דמכיר בה וכו' ורבינו הפכם בלשונו והיינו טעמא משום דאי הוה נקיט סדר הגמ' לומר בסוף כל הדברים דדוקא במכיר בה שהיא בת חמורו וכו' הוה משמע דלעולם לא מצי מעיד אלא במכיר בה דוקא ולפיכך כתב בד״א במכיר וכו' סמוך למה שכתב מכר פרה או טלית ולא הזכיר שפירש שלא באחריות דאהא דוקא הוא דבעינן שיכיר ואחר כך כתב תנאי אחר שהוא כולל בין למה שכתב דהיינו שלא פירש שלא באחריות בין היכא דפריש דשלא באחריות הוא מוכר וזהו שהאריך בלשונו ואמר בד״א שיעיד ראובן לאבד זכות יהודה וכו' כדי לכלול דבשום ענין אין ראובן מעיד לו וכו' אלא אם כן העידו שלא היתה לו קרקע וכו' דל״ש פירש דשלא באחריות הוא מוכר ול״ש לא פירש צריך תנאי זה לשיוכל להעיד. ומה שאמרו בגמרא ורב זביד אמר אפי' נמצאת וכו' אצל אוקימתא דמכיר בה שהיא בת חמורו היינו לומר דלרב פפא א״א להעמיד הברייתא אלא דוקא במכיר אבל לרב זביד יש להעמיד בין במכיר בין שאינו מכיר אם פירש דשלא באחריות הוא מוכר אבל אין הכי נמי שאם מכר סתם אין להעמידה אלא דוקא במכיר ומש״ה פריך גמרא מדרב פפא דלדידיה אפי' פירש שלא באחריות אם נמצאת שאינה שלו חוזר עליו ואילו לרב זביד לא קשיא דאיכא לאוקמה כשמכר לו שלא באחריות:\",1,0],[8,388,16,4,\"וכתב נמוקי יוסף בשם הראב\\\"ד דכל הני דפסילי משום נוגע בדבר לא פסילי אלא כי מסהדי לזכותם אבל לחובתם פשיטא דמהימני דהודאת בעל דין כמאה עדים דמי:\",2,0],[8,388,16,4,\"וכן שאר מיני פסולים וכו'. אם בפסולים מחמת עבירה פשיטא דרשע הוא ואם בפסולים מחמת קורבה ירושלמי הובא בהלכות פרק זה בורר דמייתי מרבויא דקרא שלא יהו הדיינים קרובים לעדים ולא לבעלי דינים ולא זה לזה:\",3,0],[8,388,16,5,\"ולפיכך אין סומכים וכו'. ה\\\"ה לבית דין של שלשה ולא נקט אין סומכין בסנהדרין אלא לאשמועינן דאלו שמוסיפין עד שבעה לעבר השנה אם היה בהם קרובים אין בכך כלום דמתחילין בשלשה ומוסיפין עד שבעה ואז גומרין ואם גמרו בשלשה מעוברת וכיון שכן אותו תוספת אפילו שיהיו קרובים כיון שהג' ראשונים כשרים אין בכך כלום אבל ג' הראשונים צריך שיהיו כשרים או לפחות ג' מהם דכיון דאם גמרו בג' מעוברת בתלתא מינייהו דכשרים סגי וזהו שכתב\",1,0],[8,388,16,5,\"רבינו שאם היה בהם קרובים ולא כתב שאם היו כולם קרובים:\",2,0],[8,388,16,6,\"כל הכשר לדון וכו'. משנה בנדה פ' בא סימן (נדה דף מ״ט:) ואמר רבי יוחנן שם בגמרא ובסנהדרין פ' אחד דיני ממונות (סנהדרין דף ל״ד) דאתא לאתויי סומא באחת מעיניו שכשר להעיד ואינו כשר לדון ואמרינן דלא קי״ל כההוא סתמא אלא כסתמא דסנהדרין דדיני ממונות דנין ביום וגומרין בלילה וכולהו אינשי לא חזו בליליא כדחזי סומא באחת מעיניו ביום וכיון דגומרין בלילה הוא הדין דסומא באחת מעיניו דן לכתחלה א״כ לא קי״ל כההוא סתמא וקשה א״כ למה פסקו רבינו ויש לדחוק ולומר דטעמא דאידחי ההוא סתמא משום דאמר דסומא באחת מעיניו שאינו כשר לדון דיני ממונות וכבר פסק רבינו בפ״ב מהלכות סנהדרין דסומא באחת מעיניו כשר לדון דיני ממונות ולא תפס לשון המשנה פה אלא משום האוהב והשונא והגר וכל הני דמני הכא רבינו שהם כשרים להעיד ואינם כשרים לדון:\",1,0],[8,388,16,6,\"ואיכא למידק א״כ אמאי דחי בגמרא האי סתמא לימא דאתא לאיתויי כל הני דמני הכא רבינו. ומצאתי בתוס' פרק בא סימן (נדה דף נ' ד״ה ור״מ) שהקשו קושיא זו לענין אוהב ושונא ותירצו דלא פסיקא ליה שהרי לכל העולם כשרים ואין תירוץ זה נוח לי דאכתי נימא דאתא לאיתויי גר ומשוחרר שהם כשרים להעיד ואינם כשרים לדון ד״מ ועוד קשה דהוה ליה למימר דהא דקתני יש שכשר להעיד ואינו כשר לדון בדיני נפשות איירי ושפיר אתי לאיתויי סומא באחת מעיניו שהוא פסול לדיני נפשות וכן לאיתויי זקן וסריס וממזר שהם כשרים להעיד ופסולים לדיני נפשות והא הוה עדיף מלמידחי סתם מתניתין מהלכה. וי״ל דאה״נ דלדידן שפיר מיתוקמא מתניתין כדאמרן ולא שקיל וטרי גמרא אלא אליבא דר' יוחנן דאמר דמתניתין דיש שכשר להעיד ואינו כשר לדון לאיתויי סומא באחת מעיניו שאינו כשר לדון אפילו דיני ממונות ואליבא דידיה הוא דקשו סתמי אהדדי ואידחי ההוא סתמא אבל לדידן לא קשו סתמי אהדדי ושפיר מתוקמי כדאמרן. וא״ת ר' יוחנן מאי דוחקיה לומר דקשו סתמי אהדדי ולא אוקים להו כדאמרן י״ל שכך היה מקובל מרבותיו שפירוש דמתניתין דיש שכשר להעיד ואינו כשר לדון מיירי לדיני ממונות ובסומא מאחת מעיניו דמש״ה הוכרח לומר דליתא לההוא סתמא:\",2,0],[8,388,16,6,\"האוהב והשונא. משנה בסנהדרין פרק זה בורר (סנהדרין דף כ״ז:) אלו הן הקרובים וכו' האוהב והשונא וכו' א״ל לא נחשדו ישראל על כך ומפרש בגמרא (דף כ״ט) דדוקא לעדות לא נפסלו אבל לדון נפסלו מיתורא דקרא והוא לא אויב לו והיינו טעמא דכיון דסני ליה לא מצי לאהפוכי בזכותיה ותמהני למה לא כתב רבינו במה ששנינו שם איזהו האוהב זה שושבינו והשונא כל שלא דבר עמו שלשה ימים באיבה ואמרינן התם משמיה דרבא דמיום ראשון ואילך בטלה שושבינות וכשר להעיד:\",3,0],[8,388,16,6,\"הגר. פירוש שאין אמו מישראל שאינו כשר לדון אפילו דיני ממונות כמו שנתבאר פ\\\"ב מהל' סנהדרין והמשוחרר דינו כדין הגר:\",4,0],[8,388,16,6,\"וכן הזקן והסריס וכו'. פי' אלו שהזכיר עד עתה אין כשרים לדון אפילו דיני ממונות אבל הזקן והסריס וכו' לדיני נפשות דוקא הוא דאין כשרים אבל לדיני ממונות כשרים הם. ודין זה דזקן וסריס ברייתא בסנהדרין פ' אחד דיני ממונות (סנהדרין דף ל״ו:). וק״ל למה לא כתב ג״כ מי שאין לו בנים שפסלו באותה ברייתא וי״ל שסמך על מה שכתבו פ״ב מהלכות סנהדרין וכן עשה בזקן ששם כתב זקן מופלג וכאן כתב זקן לבד אלא סמך על מ״ש שם ועוד שטעם הסריס ומי שאין לו בנים אחד דטעם מי שאין לו בנים לפי שאינו יודע צער גידול בנים ואינו רחמן והוא עצמו טעם הסריס:\",5,0],[8,388,16,6,\"והממזר וסומא באחת מעיניו וכו'. משנה פ' בא סימן (נדה דף מ״ט ע״ב) יש שראוי לדון דיני ממונות ואין ראוי לדון דיני נפשות ואמרינן בגמרא דחדא מהני מתניתין לאיתויי ממזר דכשר לדון דיני ממונות ואין כשר לדון דיני נפשות:\",6,0],[8,388,16,6,\"וסומא באחת מעיניו. נדה פרק בא סימן וסנהדרין פ' אחד דיני ממונות (סנהדרין דף ל״ד:) ההוא סמיא פי' באחת מעיניו דהוה בשבבותיה דרבי יוחנן דהוה דאין דינא פי' דיני ממונות ולא א״ל מידי משום דתנן בפרק אחד דיני ממונות (סנהדרין דף ל״ב) בדיני ממונות גומרין בלילה וכולהו אינשי לא חזו בליליא כדחזי סומא ביום וכיון דגומרין בלילה סומא באחת מעיניו דן לכתחלה ביום ומאחר דכשר לדון דיני ממונות פשיטא דכשר להעיד דכל הכשר לדון כשר להעיד וכיון דתנן במתניתין דיני נפשות גומרין ביום ממילא דסומא באחת מעיניו פסול לדון דיני נפשות וכבר כתבתי זה פרק שני מהלכות סנהדרין:\",7,0],[8,388,17,1,\"מי שהעידו לו אנשים רבים וכו'. משנה בסנהדרין פרק אחד דיני ממונות (סנהדרין דף ל״ז) כיצד מאיימין על עדי נפשות שמא תאמרו משמועה עד מפי עד ומפי אדם נאמן ואמרי' בגמרא דה״ה דפסילי בדיני ממונות ובזה בורר גבי עדי ממון תנן אם אמר העד הוא אמר לי שהוא חייב לו או איש פלוני אמר לי שהוא חייב לו לא אמר כלום עד שיאמר בפנינו הודה שהוא חייב לו מאתים זוז:\",1,0],[8,388,17,2,\"ולפיכך מאיימין וכו' עד וגומרין הדין. משנה פרק זה בורר כתבתיה בסמוך.\",1,0],[8,388,17,2,\"ומ\\\"ש מודיעין אותם כח עדות שקר וכו'. שם בגמרא ונראה מדברי רבינו שסובר דלא אידחי מימרא דרב יהודה ורבא אלא לענין שלא יאיימו אותם בהני כללי כי יחשבו שינצלו אבל בהני פרטי שיגיע להם באותו עון מאיימין עליהם והיינו דאמר רב אשי בהדיא (דף כ\\\"ט) סהדי שקרי אאוגרייהו זילי שהוא רע נוגע להם בפרט וה\\\"ה לשאר רעות פרטיות שמאיימין עליהם:\",2,0],[8,388,17,3,\"המטמין עדים וכו'. סנהדרין פרק זה בורר (סנהדרין דף כ״ט) ברייתא כלשון הזה:\",1,0],[8,388,17,4,\"אחד המודה בפני עדים וכו'. שם במשנה עד שיאמר בפנינו הודה שהוא חייב לו מאתים זוז ופירש רש\\\"י שיהיו שניהם בפנינו ולהודות נתכוון להיות לו עדים בדבר ואמרי' בגמרא מסייע ליה לרב יהודה אמר רב דאמר צריך שיאמר אתם עדי והיו עלי עדים הרי הוא כמו אתם עדי:\",1,0],[8,388,17,4,\"בין שאמר הלוה וכו'. שם מימרא דרבינא ואי תימא רב פפא.\",2,0],[8,388,17,4,\"ומה שכתב דרך מאמין לדבריו כלומר דאם טען משטה הייתי בך שראיתיך אומר דברים שאינם ואמרתי הלא משחק הוא נאמן. וכבר נתבארו דינין אלו בדברי רבינו בהלכות טוען ונטען:\",3,0],[8,388,17,7,\"השוכר עדי וכו' וכן היודע וכו'. ברייתא בבא קמא ריש פרק הכונס (בבא קמא דף נ״ה:) השוכר עדי שקר והיודע עדות לחבירו ואינו מעיד לו פטור מדיני אדם וחייב בדיני שמים ואמרו בגמרא דהיינו בעד אחד דאילו בשנים מדאורייתא מחייב ובראש הלכות אלו הארכתי בזה:\",1,0],[8,388,18,1,\"מי שהעיד וכו' ומצוה לעשות לו כמו שרצה לעשות וכו'. משנה בסנהדרין סוף אלו הן הנחנקין (סנהדרין דף פ״ט) כל הזוממין מקדימין לאותה מיתה כלומר אין להם לצפות מיתה אחרת אלא משכימין לאותה מיתה שנגמר לה דינו של נידון:\",1,0],[8,388,18,1,\"ואם העידו במלקות וכו' ואם העידו לחייבו ממון וכו'. משנה פירקא קמא דמכות (דף ה') משלשין בממון ואין משלשין במכות וכו' אלא כל אחד ואחד לוקה ארבעים:\",2,0],[8,388,18,1,\"ואין לוקין במקום תשלומין. שם במשנה (דף ד') פלוגתא דר״מ ורבנן ופסק כרבנן דאמרי כל המשלם אינו לוקה ובכתובות פרק אלו נערות (כתובות דף ל״ב:) מקשי ונימא כל הלוקה אינו משלם כלומר ונדייניה במלקות ומשני בפירוש רבתה תורה עדים זוממים לתשלומין מכדי כתיב ועשיתם לו כאשר זמם יד ביד למה לי דבר הניתן מיד ליד ורבי אלעזר יהיב טעמא משום דלאו בני התראה נינהו:\",3,0],[8,388,18,2,\"בד\\\"א בעדים שהוזמו וכו' עד הרי אלו זוממין ונהרגין וכו'. משנה פ\\\"ק דמכות (דף ה') אין העדים נעשים זוממין עד שיזומו את עצמן כלומר שיזימו אותם בעסקי גופם של עדים ולא בעסקי ההרוג וההורג כדמפרש ואזיל כיצד אמרו מעידין אנו באיש פלוני שהרג את הנפש אמרו להם היאך אתם מעידים (שזה הרג את זה) שהרי נהרג זה או ההורג זה היה עמנו במקום פלוני אין אלו זוממין אבל אמרו להם היאך אתם מעידים שהרי אתם הייתם עמנו אותו היום במקום פלוני הרי אלו זוממין ונהרגים על פיהם:\",1,0],[8,388,18,3,\"וזו שהאמינה תורה עדות האחרונים וכו'. דאמרינן במרובה (דף ע״ב:) ובפרק זה בורר (סנהדרין דף כ״ז) עד זומם חידוש הוא מאי חזית דסמכת אהני סמוך אהני ואע״ג דרבא הוא דאמר הכי ולית הלכתא כוותיה הא דלית הלכתא כוותיה היינו במאי דקאמר דאינו נפסל למפרע אבל במאי דקאמר דחידוש הוא ודאי מוסכם הוא:\",1,0],[8,388,18,3,\"אפילו היו העדים הראשונים מאה כו'. משנה פ\\\"ק דמכות (דף ה':) ע\\\"פ שנים עדים או שלשה עדים יומת המת אם מתקיימת העדות בשנים למה פרט הכתוב בשלשה אלא להקיש שלשה לשנים מה שלשה מזימין את השנים אף שנים יזומו את השלשה ומנין אפילו מאה ת\\\"ל עדים:\",2,0],[8,388,18,4,\"עדים זוממין אינן צריכין התראה. כתובות פ' אלו נערות (כתובות דף ל״ג) ר' אלעזר אמר עדים זוממין ממונא משלמי ומילקא לא לקו משום דלאו בני התראה נינהו ואביי נמי אע״ג דמעיקרא פליג עליה לבסוף הדר ביה ובפ״ק דמכות וכתובות (דף ל״ב) אמר מה לעדים זוממין שכן אינם צריכים התראה:\",1,0],[8,388,18,4,\"ועדים שהוכחשו ולבסוף הוזמו וכו'. ב״ק פרק מרובה (בבא קמא דף ע״ג:) אמר רבא עדים שהוכחשו ולבסוף הוזמו נהרגין דהכחשה תחלת הזמה היא אלא שלא נגמרה ופירש״י שהוכחשו שנים אומרים הרג ושנים אומרים לא הרג ולבסוף הוזמו שבאת כת שלישית ואמרה עמנו הייתם נהרגין ואע״ג דאביי פליג עליה הא קי״ל דהלכתא כרבא לגבי אביי בר מיע״ל קג״ם:\",2,0],[8,388,18,5,\"אין מזימין את העדים אלא בפניהם וכו'. כתובות פ\\\"ב (דף כ') אמר רבי אבהו אין מזימין את העדים אלא בפניהם ומכחישין את העדים שלא בפניהם והזמה שלא בפניהם נהי דהזמה לא הויא הכחשה מיהא הויא וטעמא דאין מזימין את העדים אלא בפניהם פירש\\\"י שהרי באין לענשן או נפש או ממון והתורה אמרה והועד בבעליו יבא בעל השור ויעמוד על שורו:\",1,0],[8,388,18,6,\"עדי נפשות שהוכחשו וכו'. בב״ק פרק מרובה (בבא קמא דף ע״ד:) אמרו אפלוגתא דאביי ורבא שכתבתי למעלה ובפלוגתא עדים שהוכחשו ולבסוף הוזמו רבי יוחנן ורבי אלעזר חד אמר נהרגין וחד אמר אין נהרגין תסתיים דר״א הוא דאמר אין נהרגין דאמר רבי אלעזר עדים שהוכחשו בנפש לוקין ואי סלקא דעתך ר״א הוא דאמר נהרגין אמאי לוקין ה״ל לאו שניתן לאזהרת מיתת ב״ד ואין לוקין עליו אלא לאו ש״מ רבי אלעזר הוא דאמר אין נהרגין ואקשינן לוקין תרי ותרי נינהו מאי חזית דסמכת אהני סמוך אהני אמר אביי בבא הרוג ברגליו אלמא דלמ״ד נהרגין ה״ל לאו שניתן לאזהרת מיתת ב״ד ואפילו בא הרוג ברגליו אין לוקין וכיון שפסקנו כרבא דאמר נהרגין ממילא קי״ל דעדים שהוכחשו בנפש אין לוקין ופי' לאו שניתן לאזהרת מיתת ב״ד היינו שהוא לאו שניתן לאזהרה שלא יעשה כך שלא ימיתוהו ב״ד ואין לוקין עליו דמיתת ב״ד היא עונשו של לאו.\",1,0],[8,388,18,6,\"ומ\\\"ש אבל ב\\\"ד מכין אותן וכו'. פשוט הוא:\",2,0],[8,388,18,7,\"עדים זוממין צריכים הכרזה. סנהדרין סוף הנחנקין (סנהדרין דף פ״ט) ת״ר ד' צריכין הכרזה מסית ובן סורר ומורה וזקן ממרא ועדים זוממים משום דבכולהו כתיב ישמעו וייראו ולמד רבינו שהכרזה צריכה שתהיה בכל המקומות ממה ששנו שם במשנה דזקן ממרא אליבא דר״י כותבין ושולחין בכל המקומות איש פלוני נתחייב מיתה בב״ד ואפילו ר״ע דפליג עליה התם לא אשכחן דפליג עליה אלא בזקן ממרא משום דסבר דמשמרים אותו עד הרגל אבל באינך דצריכי הכרזה כיון דלא אשכחן ליה דפליג מסתמא כר״י ס״ל ודבר פשוט הוא שצריכין לכתוב על איזו עבירה נהרג שאל״כ היאך יראו ויוסרו הנשארים:\",1,0],[8,388,18,8,\"חיוב העדים זוממין לשלם וכו'. פ\\\"ק דמכות (דף ב':) בברייתא המדברת בעדים זוממין משום ר\\\"ע אמרו אף אין משלמין על פי עצמן ואמרו בגמרא מ\\\"ט דר\\\"ע קסבר קנסא הוא וקנס אין משלם על פי עצמו אמר רבה תדע שהרי לא עשו מעשה ומשלמין וכן אמר רב נחמן וכיון דהני אמוראי יהבי טעמא למלתיה וגמרא אמר התם כמאן דלא כרבי עקיבא אמימרא דרב יהודה דבסמוך לה ומשני לה אליבא דר\\\"ע אלמא הלכתא כוותיה:\",1,0],[8,388,18,8,\"אבל אם אמרו העדנו על זה וכו'. שם (דף ג') אמר רב יהודה אמר רב עד זומם משלם לפי חלקו ומוקי לה גמרא באומר העדנו והוזמנו בב\\\"ד של פלוני וחייבנו ממון סד\\\"א כיון דלחבריה לא מצי מחייב ליה איהו נמי לא מחייב קמ\\\"ל:\",2,0],[8,388,19,1,\"שנים שהעידו וכו' עד ומזימין אותם. מימרא דרבא ספ\\\"ק דמכות (דף ה') כלשון רבינו ונ\\\"ל שצריך להגיה שמא גמל קל ביותר נזדמן להם שכך אמרו בגמרא גמלא פרחא ובנסחא אחרת מספרי רבינו כתוב שמא כר קל ביותר נזדמן להם עכ\\\"ל וזו נוסחא אמיתית שכר בלשון מקרא הוא גמל קל דכתיב שלחו כר (ישעיה ט\\\"ז):\",1,0],[8,388,19,2,\"שנים שאמרו באחד בשבת וכו' עד וכן כל כיוצא בזה. מימרא דרבא פ\\\"ק דמכות ולפי גירסת הגמרא שבידינו כך ראוי להיות לשון רבינו אבל באו שני עדים בשלישי בשבת וכו' אלא מערב שבת נגמר דינו או בשני בשבת אין עדים אלו שהוזמו נהרגים שהרי מ\\\"מ וכו' וכך מצאתי בנסחא מדוייקת פירוש דאזלינן בתר שעת העדות וכיון דבאותה שעה נגמר דינו להריגה אין נהרגין ובסוף דבריו כך ראוי להגיה אפילו אמרו באחד בשבת גנב וטבח ומכר ובשני בשבת נגמר דינו אין העדים אלו שהוזמו משלמין וכו'. ונ\\\"ל דה\\\"ה אם גנב וטבח ומכר ונגמר דינו בשני אלא דאורחא דמילתא נקט שאין כל המעשים האלו נעשים ביום אחד ובנסחא אחרת כתוב אפילו אמרו בשני בשבת ופירש\\\"י דכי אמרינן דכשלא נגמר דינו והוזמו משלמין דוקא בקנס משום דהוה מצי למיפטר נפשיה בהודאה ואשתכח דאינהו הוו מפסדי ליה אבל בעדות ממון פטורים שהרי לא היו מפסידין אותו כלום אחר שהוא מחוייב ועומד ופשוט הוא:\",1,0],[8,388,19,3,\"אין עדי השטר נעשים זוממין וכו'. זה דעת הרי\\\"ף בב\\\"ק פ' מרובה והביא ראיה מהא דת\\\"ר (סנהדרין ל\\\"ה) שטר שזמנו כתוב באחד בניסן בשמטה ובאו עדים ואמרו היאך אתם מעידים על השטר הזה והלא באותו היום עמנו הייתם במקום פלוני השטר כשר והעדים כשרים חיישינן שמא איחרו וכתבוהו. ולי נראה עוד ראיה מדתניא בגט פשוט (דף קע\\\"א) וכתבו רבינו פכ\\\"ג מהלכות מלוה ולוה שטר שזמנו כתוב בשבת או בעשרה בתשרי שטר מאוחר הוא וכשר הרי שלהכשיר השטר אומרים שהוא מאוחר וממילא מתכשרי עדים:\",1,0],[8,388,19,3,\"אמרו בזמנו כתבנוהו וכו'. כתבתי בסמוך שדעתו כדעת הרי\\\"ף והוא ז\\\"ל כתב כן שם.\",2,0],[8,388,19,3,\"ומ״ש הרי נפסלו למפרע. הוא פלוגתא דאביי ורבא בב״ק פ' מרובה (בבא קמא דף ע״ב:) ובסנהדרין פרק זה בורר (סנהדרין דף כ״ז) ואביי סבר למפרע הוא נפסל וזו אחת משמועות יע״ל קג״ם דהלכתא בהו כאביי וכבר כתבתי זה בפ״י מהלכות אלו.\",3,0],[8,388,19,3,\"ומ\\\"ש ואפשר שביום זה שהעידו בב\\\"ד וכו' והם שקרו ואמרו בזמנו כתבנו כלומר ולא מפסדינן להני שטרי דאינשי דאיכתבו מקמי הכי מספיקא:\",4,0],[8,388,20,1,\"עד שיהיו שניהם ראויים לעדות. משנה פ\\\"ק דמכות (דף ה:) מה שנים נמצא אחד מהם קרוב או פסול עדותן בטלה אף השלשה כן מנין אפילו מאה ת\\\"ל עדים וכיון דעדותן בטלה פשיטא דאין נהרגין:\",1,0],[8,388,20,1,\"ויזומו שניהם. ג\\\"ז שם ר\\\"ש אומר מה שנים אינם נהרגים עד שיהיו שניהם זוממין אף שלשה אינן נהרגין עד שיהיו שלשתן זוממין ומנין אפילו מאה ת\\\"ל עדים:\",2,0],[8,388,20,1,\"ומה שכתב אחר שנגמר הדין. שם אין העדים זוממין נהרגין עד שיגמר הדין:\",3,0],[8,388,20,1,\"אבל אם הוזם אחד מהם וכו'. שיעור הלשון כך הוא או שהוזמו שניהם קודם גמר דין ואפילו אם אחר גמר דין הוזמו שניהם אבל נמצא אחד מהן קרוב או פסול אינן נענשין.\",4,0],[8,388,20,1,\"ומה שכתב אע\\\"פ שהוזמו ונפסלו וכו' כלומר דאילו הוכחשו לא היו נפסלין דזו באה בפני עצמה ומעידה וזו באה בפני עצמה ומעידה כדאיתא בפרק חזקת ובפרק כל הנשבעין דאיפליגו רב הונא ורב חסדא בשתי כתי עדים המכחישות זו את זו והלכה כרב הונא לגבי רב חסדא דרביה הוא ורב הונא הוא דאמר זו באה בפני עצמה ומעידה ועוד טענות אחרות כתבו שם הרי\\\"ף והתוס':\",5,0],[8,388,20,2,\"נהרג זה שהעידו עליו וכו'. פ\\\"ק דמכות (דף ה':) תניא ברבי אומר לא הרגו נהרגין הרגו אין נהרגין אמר לו אביו בני לאו ק\\\"ו הוא א\\\"ל למדתנו רבינו שאין עונשין מן הדין פירוש מק\\\"ו. ופירוש דברי רבינו כך הם אינם נהרגים מק\\\"ו דנימא השתא משום כאשר זמם מחייבין ליה משום כאשר עשה לא כ\\\"ש אלא דוקא כאשר זמם הוא דחייב לא כאשר עשה ודבר זה שאין עונשין מן הדין מפי הקבלה הוא:\",1,0],[8,388,20,2,\"אבל אם לקה זה שהעידו עליו לוקין וכן אם יצא הממון וכו'. צריך לבקש טעם מאין לו לרבינו לחלק בין מיתה לממון ומלקות דלכאורה משמע דל\\\"ש ממון או מלקות או מיתה בכולהו בעינן כאשר זמם ולא כאשר עשה ואף כי אפשר לחלק בין ממון למיתה דממון אפשר בחזרה וכיון שכך כך לי עשה כמו זמם וכן כתבו התוספות בריש ב\\\"ק (דף ה':) ד\\\"ה ועדים זוממים אהא דמני רבי חייא עדים זוממין בכ\\\"ד אבות נזיקין וז\\\"ל פי' ריב\\\"א דאפילו שילם ע\\\"פ עדים זוממין חייבין דלא שייך בממון כאשר זמם ולא כאשר עשה דאפשר בחזרה ור\\\"י מפרש דלא צריך להאי טעמא דגבי ממון מחייבינן להו בק\\\"ו דגבי ממון עונשין מן הדין והא דאמרינן במכות הרגו אין נהרגין דהיינו משום דהתם אין עונשין מן הדין עכ\\\"ל. ועוד כתב שם מ\\\"מ אין סברא לחלק בין מלקות למיתה וכ\\\"כ רבינו ירוחם בנ\\\"ב ח\\\"ז בשם רש\\\"י וכנראה שלזה כיון הראב\\\"ד שכתב שיבוש הוא זה ואע\\\"פ שתפס בנהרג זה שהעידו עליו תחלת הבבא נקט ומיהו רבינו ירוחם כתב שכדברי רבינו נראה עיקר. ואפשר לתת טעם לדברי רבינו דלא אמרינן כאשר זמם ולא כאשר עשה אלא היכא דהרגו על פיהם משום דגדול עונשם מנשוא אין ראוי לתת להם מיתת ב\\\"ד שתכפר עליהם אלא ראוי להניחם שיהיו נדונין אחר מיתה בעונשים נוראים דוגמא לדבר נותן כל זרעו למולך שהוא פטור מה שאין לומר כן בהלקו ע\\\"פ עדותם. ועוד י\\\"ל טעם אחר שמאחר שאלהים נצב בעדת אל אילולא שהיה חייב זה מיתה לא היה מניח הקב\\\"ה שתאבד נפש אחת מישראל ומאחר שהניח הקב\\\"ה לב\\\"ד שיסכימו להרוג את זה ונהרג חייב מיתה היה הילכך אין לעדים משפט מות מה שאין לומר כן במלקות:\",2,0],[8,388,20,3,\"היו העדים שלשה וכו'. משנה פ\\\"ק דמכות (דף ה':) ר\\\"ש אומר מה שנים אינם נהרגים עד שיהו שניהם זוממין אף שלשה אין נהרגין עד שיהו שלשתן זוממין מנין אפילו מאה ת\\\"ל עדים ומדשקלי וטרו אליביה ש\\\"מ דהלכתא כוותיה ובגמ' (דף ו') אמר רבא והוא שהעיד כל אחד בתוך כדי דבור של חבירו כלומר התם קאמר מתניתין מאה כשנים אבל אם העידו השנים ואחר זמן העידו האחרים הרי הם כשתי כתות לענין הזמה בלבד וכן דעת התוספות ולאפוקי מדברי ר\\\"י שכתב שהם כשתי כתות לכל דבר וטעם רבינו והתוספות דבשלמא לענין הזמה בהגדה תליא מילתא וכיון שלא הגידו תוך כדי דיבור הרי הן כשתי כתות להזמה אבל בנמצא אחד מהם קרוב או פסול כיון שמעת שראו העדות נפסלו מה לי אם העידו תוך כדי דיבור או לא וכיון שהוזמו קצתם ה\\\"ל נמצא אחד מהם פסול ועדותם בטלה והתם נמי אמרינן דתוך כדי דבור היינו כדי שאלת תלמיד לרב ושיעור לשון רבינו כך הוא הרי נחלקה העדות והשנים שהוזמו נענשין אע\\\"פ שהשנים שהיה בין דבריהם ודברי הראשונים הפסק אין נענשין ואע\\\"פ שבטלה העדות וכו':\",1,0],[8,388,20,3,\"וכתב הראב\\\"ד אבל אם היה הפסק וכו' עד נפסלה כולה א\\\"א איני יודע מהו וכו'. טעמו שכיון שהיה הפסק בין כת ראשונה לכת שניה הרי אלו שתי עדויות ואע\\\"פ שהוזמה כת ראשונה תתקיים העדות בכת שניה ויהרג הרוצח ורבינו סובר שמאחר ששתי הכתות באו להעיד כאחד אע\\\"פ שהיה הפסק בין כת לכת הרי הן ככת אחת לענין שאם בטלה עדות הכת האחת בטלה ג\\\"כ עדות הכת השניה ובהכי ניחא נמי מ\\\"ש ועוד מה זה שאמר וכו' ומה עונש ראוי להם כי לדעתו שהוכשרה כת שניה להעיד שייך למיפרך מה עונש ראוי להם אבל לרבינו שאינה כשירה להעיד ה\\\"ל כולהו ככת אחת ואפ\\\"ה אלו נענשין ואלו אין נענשין:\",2,0],[8,388,20,4,\"העיד האחד ונחקרה וכו'. בסנהדרין פרק ארבע מיתות (סנהדרין דף ס') על מה ששנינו גבי מגדף שהיו אומרים לאחד מהעדים אמור מה ששמעת בפירוש והשני אומר אף אני כמוהו אמר ר״ל ש״מ אף אני כמוהו בדיני ממונות ובדיני נפשות ומעלה הוא דעבוד רבנן פי' שהצריכו כל העדים לפרש עדותן והכא כיון דלא אפשר אוקמוה אדאורייתא פירוש דלא אפשר לפרש ברכת השם דאי סלקא דעתך פסול הכא משום דלא אפשר קטלינן ליה לגברא ומאחר שעדותו עדות ממילא שהוא נעשה עד זומם. ונ״ל שעיקר הגירסא כך הוא שכל עד שאמר כך אחר עדות חבירו ה״ז כמי שנחקר והעיד וכו' ובספר מוגה מצאתי שכל שאמר אחר עדות חבירו הרי זה כמי שנחקר וכו':\",1,0],[8,388,20,4,\"ואין לעדים זוממין שגגה וכו'. למד זה ממימרא דר״א פרק אלו נערות (כתובות דף ל״ג) שכתבתי פי״ח דעדים זוממין לאו בני התראה נינהו ואמר רבא (תדע) אימת נתרי בהו מעיקרא אמרי אשתלין ונראה שמפרש רבינו שכחנו האיסור ולכן לא נתרה בהם משמע שאפילו היו שוגגים חייבים הם ומ״מ קשה שהרי אחר זה הקשה אביי ניתרי בהו בתוך כדי דיבור ואמרינן הדר אמר אביי לאו מילתא היא דאמרי אי ס״ד עדים זוממין צריכים התראה כי לא מתרינן בהו לא קטלינן להו מי איכא מידי דאינהו בעו קטיל בלא התראה ואינהו בעו התראה הא בעינן ועשיתם לו כאשר זמם לעשות לאחיו וליכא. ואם כן הטענה היא משום דהדר אמר אביי ולא משום מאי דאמר רבא אשתלין ועוד שאין טעם שאין להם שגגה תלוי כשאין להם מעשה וכן אין טעם שאין צריכים התראה תלוי כשאין להם מעשה וצ״ע:\",2,0],[8,388,20,4,\"כתב הראב\\\"ד א\\\"א זה הטעם לא ידעתי מהו וכו'. ביאור דבריו דבריש כריתות איפליגו תנאי דאיכא מאן דאמר דמגדף היינו עובד עבודה זרה וחכמים אומרים דהיינו מברך את השם ולפי דברי רבינו מגדף לדעת חכמים כיון שאין בו מעשה לא יהא צריך התראה:\",3,0],[8,388,20,5,\"כשם שהשנים מזימין את המאה וכו'. משנה פ\\\"ק דמכות (דף ה') באו אחרים והזימום באו אחרים והזימום כולם יהרגו ופירש רבינו כפירש\\\"י והרי\\\"ף:\",1,0],[8,388,20,6,\"כת שהעידה על ראובן וכו'. ק\\\"ו מבבא דלעיל כי שנים יכולים להזים חמשים כתות כ\\\"ש ששנים יזומו לשנים ושנים לשנים ועוד יש לפרש שרבינו סובר ששתי החלוקות בכלל פירוש דברי המשנה דבאו אחרים והזימום באו אחרים והזימום. כתוב בספרי רבינו כת שהעידה על ראובן וכו' ובאו שנים עדים והזימום אלו הארבע תיבות הם יתרים וצריך למוחקם וכן נמצא בספר מדוייק:\",1,0],[8,388,20,7,\"עדים שהעידו על איש טריפה וכו'. סנהדרין פרק אלו הן הנשרפין (דף ע\\\"ח) אמר רבא ההורג את הטריפה פטור וטרפה שהרג לפני ב\\\"ד חייב שלא בפני ב\\\"ד פטור בפני ב\\\"ד מאי טעמא חייב דכתיב ובערת הרע מקרבך כלומר והרי ראוהו רוצח שלא בפני ב\\\"ד פטור דהויא לה עדות שאי אתה יכול להזימה וכל עדות שאי אתה יכול להזימה לא שמה עדות ופירש\\\"י שלא בפני ב\\\"ד ואתה בא לחייבו ע\\\"פ עדים פטור דאין עדותן עדות דהויא עדות שאי אתה יכול להזימה לקיים בה דין הזמה שאם הוזמו אין נהרגין דגברא קטילא בעו למיקטל:\",1,0],[8,388,20,7,\"וכן העדים שהיו טריפה וכו'. שם רב אשי אמר אפילו עדי טרפה שהוזמו אינן נהרגין לפי שאינן בזוממי זוממין כלומר וכיון שכן הו\\\"ל עדות שאי אתה יכול להזימה ואינה עדות וקשה לי היאך דנין ע\\\"פ עדי טריפה הא הו\\\"ל עדות שאי אתה יכול להזימה שהרי אנו אומרין שאין זוממיה נהרגין ואפשר לומר דבשעת עדותן לא הכירו בהם שהיו טריפה:\",2,0],[8,388,20,8,\"עדים שהעידו על אחד והרשיעוהו וכו'. משנה ריש פ\\\"ק דמכות:\",1,0],[8,388,20,8,\"ומ\\\"ש העידו על שורו וכו'. ברייתא שם (ע\\\"ב) ת\\\"ר ארבעה דברים נאמרו בעדים זוממין אין נעשין בן גרושה ובן חלוצה ואין גולין לערי מקלט ואין משלמין את הכופר ואין נמכרין בעבד עברי:\",2,0],[8,388,20,9,\"כך קבלו חכמים וכו'. שם אמר עולא רמז לעדים זוממין שלוקין מן התורה מנין פירוש עדי בן גרושה או עדי גלות שפטרן הכתוב מדין הזמה מנין שהם לוקין דכתיב והצדיקו את הצדיק והרשיעו את הרשע והיה אם בן הכות הרשע משום דוהצדיקו את הצדיק והרשיעו את הרשע והיה אם בן הכות הרשע אלא עדים שהרשיעו את הצדיק ואתו עדים אחריני והצדיקו את הצדיק דמעיקרא ושוינהו להני רשעים והיה אם בן הכות הרשע פירוש בתמיה אי הצדיקו והרשיעו בדיינין קאמר וצדיק ורשע בבעלי דינין למה לי והצדיקו וכו' ליכתוב כי יהיה ריב בין אנשים ונגשו אל המשפט ושפטום והיה אם בן הכות למה הוזכרה כאן צדקת צדיק וכי כל מקום שהצדיקו ב\\\"ד את הזכאי וחייבו את החייב יש מלקות דאתא קרא למיתלי בוהצדיקו והרשיעו אלא על כרחך בעדים משתעי עדים שקרנים שהרשיעו צדיק ובאו אחרים והזימום והצדיקו את הנדון שהוא צדיק והרשיעו את העדים הרשעים והיה אם בן הכות הרשע אם הזמה זו בת מלקות היא שאינו יכול לקיים בה דין הזמה כגון בעדי בן גרושה או גלות והפילו השופט והכהו ומקשה גמרא ותיפוק לי מלא תענה ברעך עד שקר כלומר כל עונשי לאוין מלקות אלא במקום שפירש לך בו עונש וכאן שאינו יכול לעונשן בעונש הכתוב בהם ילקו ומהדר משום דה\\\"ל לאו שאין בו מעשה ואין לוקין עליו:\",1,0],[8,388,20,9,\"אבל אם העידו עליו שאכל בשר בחלב וכו'. כלומר העידו שהוא חלל או שהוא חייב לגלות דוקא הם מפי הקבלה ורמזם הכתוב בוהצדיקו וכו' אבל לבשר בחלב או לבש שעטנז לא איצטריך האי אסמכתא דמפשטיה דקרא דכתב כאשר זמם ילפינן לה דהא נתכוונו לחייבו מלקות:\",2,0],[8,388,20,10,\"שנים שהעידו על ראובן וכו'. בסנהדרין ס״פ הנחנקין (סנהדרין דף פ״ט) מני במתניתין בהדי נחנקין זוממי בת כהן ובועלה שכל המוזמין מקדימין לאותה מיתה חוץ מזוממי בת כהן ובועלה כלומר המוזמין נדונין במיתה הראויים למות בה המנאפים חוץ מזוממי בת כהן שאינן מומתין בשריפה כמוה אלא בחנק כמוהו ותניא (דף צ') רי״א מה ת״ל ועשיתם לו כאשר זמם לעשות לאחיו לפי שכל המוזמין שבתורה זוממין ובועליהן כיוצא בהן בת כהן היא בשריפה ואין בועלה בשריפה זוממין איני יודע אם לו הוקשו אם לה הוקשו כשהוא אומר לעשות לאחיו לאחיו ולא לאחותו:\",1,0],[8,388,21,1,\"עדים שהעידו שפלוני גירש אשתו וכו'. משנה פ\\\"ק דמכות (דף ג') כלשון זה:\",1,0],[8,388,21,1,\"ומשערין באשה שאם האשה היתה חולה וכו' וכן אין טובת הנאה של כתובה המרובה וכו'. שם כיצד שמין א\\\"ר חסדא בבעל רב נתן בר אושעיא אמר באשה א\\\"ר פפא באשה ובכתובתה ומפרש רבינו דהכי קא מיבעיא ליה כששמין כמה אדם רוצה ליתן בכתובתה של זו בבעל שמין לראות אם הוא זקן או חולה ודאי כתובתה שוה יותר ואם בחור או בריא אינה שוה כ\\\"כ ולא נשגיח באשה אם היא בחורה או זקנה וחולה או דילמא לא נשער אלא באשה לראות אם היא זקנה או חולה או אם היא בחורה או בריאה ולא נשגיח לענין הבעל וכן פי' הרא\\\"ש ז\\\"ל ופסק כרב נתן ורב פפא דאמר באשה שמין משום דה\\\"ל רב חסדא חד לגבי תרי ועוד דרב פפא בתרא הוא והלכתא כוותיה והוסיף רב פפא לומר בכתובתה הן שמין שאם היא של אלף יתנו בטובת הנאתה מאה ואם היא של מאה לא יתנו עשרה. כנ\\\"ל לפרש לדעת רבינו ורש\\\"י פירש בדרך אחרת וכתב שלבו מגמגם בו:\",2,0],[8,388,21,2,\"העידו על זה שחייב לפלוני אלף זוז וכו'. משנה שם:\",1,0],[8,388,21,3,\"העידו על שורו של זה שנגח וכו':\",1,0],[8,388,21,4,\"העידו על פלוני שהפיל שן עבדו וכו' העידו שסימא את עינו וכו'. ברייתא בב״ק פרק מרובה (בבא קמא דף ע״ג:) מעידני באיש פלוני שסימא את עין עבדו והפיל את שינו שהרי הרב אומר כן ונמצאו זוממין משלמין דמי עין לעבד ואמר רבא ה״ד אילימא כדקתני דליכא כת אחרינא משלמין דמי עין לעבד בתר דמפקי ליה לחירות דמי עיניה קבעי לשלומי ועוד דמי כוליה עבד לרב בעי לשלומי ועוד שהרי הרב אומר כן הרב מי ניחא ליה אלא לאו כגון דאתו בי תרי ואמרי הפיל את שינו סימא את עינו דבעי מיתב ליה הרב דמי עינו ואתו בי תרי מציעאי ואמרי עינו והדר שינו דלא בעי למיתב ליה אלא דמי שינו נמצאו זוממין משלמין דמי עין לעבד ואע״ג דאביי לא מוקי לה אלא בשתי כתי עדים מ״מ הא קאמר דכת שניה אפכינהו ואזמינהו לכת ראשונה ולכ״ע ברייתא מיירי כשעדים אחרונים מכחישים את הראשונים וקתני אותם שנמצאו זוממין משלמין דמי עין לעבד וכך פירושו שכיון שהפיל את שינו הרי יצא לחירות בשינו וכי הדר סימא עינו חייב ליתן לו דמי עינו ואלו שהעידו שתחלה סימא עינו והדר הפיל שינו נמצא שאין האדון חייב לתת לו אלא דמי שינו שהוא דבר מועט והפסידוהו הרבה שהיה חייב ליתן לו בשביל עינו וכי אמרינן משלם דמי עין לעבד היינו לומר ההפרש שיש בין דמי שן לדמי עין כנ״ל. ואע״פ שפסק רבינו פ״ד מהל' חובל ומזיק שהאדון אינו משלם אא״כ תפס העבד משלמין לו העדים שהרי הפסידוהו שאפילו יתפוס לא יועילהו ודבר קרוב הוא לתפוס וכיון שכן משלמי ליה ובזה אין מקום להשגת הראב״ד שכתב העידו על פלוני שהפיל שן עבדו וכו' א״א והוא כתב בהלכות חובל וכו'. ומדאמרינן דמי כולי עבד לרב בעי לשלומי פירוש דמי כוליה עבד נמי כלומר עם דמי העין דהא תרוייהו בעי לאפסודי משמע דאילו העידו על האדון שהפיל שינו ואח״כ סימא עינו והוזמו שמשלמין לאדון דמי העבד ודמי עינו. ומ״מ צ״ע בדברי רבינו שכיון שהוא פסק פי״ח כרבא דאמר הכחשה תחלת הזמה היא וא״כ למה כתב והוזמו ואח״כ נמצא הדבר בהפך דמשמע דוקא הוזמו ואח״כ הוכחשו אבל הוכחשו ואח״כ הוזמו לא. וי״ל דאה״נ דאפילו הוכחשו ואח״כ הוזמו אלא כי היכי דלא לשתמע דוהוזמו קאי אסהדי בתראי נקט והוזמו סמוך לסהדי קמאי דאילו בתראי מפיהם אנו חיים ואח״כ דנקט לאו דוקא. ובנוסחא מדוייקת מצאתי שאין כתוב ואח״כ אלא כך כתוב והוזמו ונמצא הדבר הפך:\",1,0],[8,388,21,5,\"עדי קינוי וסתירה וכו'.. בא עד אחד והעיד שזנתה וכו':\",1,0],[8,388,21,6,\"העידו שנים שגנב וכו' עד אין הטביחה או המכירה מחייבתו לשלם כלום. משנה בב״ק פרק מרובה (בבא קמא דף ע״ב:) ובגמרא (דף ע״ג) אוקמוה לרישא כשהעידו על הגניבה ואטביחה בבת אחת והוזמו דאילו העידו על אחת מהן קודם לאחרת כשהוזמו על א' מהן פסולים הן מעת שהעידו על אותה עדות ראשונה דהא אמרי' דעד זומם למפרע הוא נפסל וא״כ כשהעידו עדות שניה פסולים היו ואין חייבין לשלם אלא כשהעידו בבת אחת. ורבינו כתב לשון המשנה לבד וסמך על מ״ש בפ״י מהלכות אלו דעד זומם למפרע הוא נפסל ובנמצא אחד מן הראשונים זומם בטלה כל העדות ופירש״י ואפילו חזרו והוזמו אחרונים אח״כ אין משלמין שהרי בטלה עדותן כבר והוכחשו דכיון דלא גנב לא טבח ואהכי לא מחייבי וכו' וכל שכן אם הוזמו שנים הראשונים תחלה שעדות שניה בטלה אלא שבזמן שלא הוזם אלא אחד בטלו שתיהן אבל כשהוזמו שניהם לא בטלה עדות ראשונה אלא משלמים כפל ומוכרח הוא ורבינו לא חשש לפרש לסבה שכתבתי:\",1,0],[8,388,21,7,\"העידו שנים שאכלה שנה ראשונה וכו' עד משלם חצי דמיה. משנה פרק חזקת הבתים (בבא בתרא דף נ״ו) וכבר כתבתי סוף פ״ד החילוק שיש בין העידו שנים שאכלה שנה ראשונה ושנים שאכלה שנה שניה ושנים שאכלה שנה שלישית לשנים אומרים ראינו שער בצד שמאלו ושנים אומרים ראינו שער אחד בצד ימינו בו ביום שאין מצטרפין ואם תאמר כשהעידו שנים שאכל שנה ראשונה וכו' אמאי מחייבינן לכלהו יאמרו אנן לסיועי למערער ולחיובי פירי למחזיק אתינן שהרי לא העדנו על ג' שנים יחד וכמו שאמרו בגמ' בבבא שאחר זו וכמו שאכתוב בסמוך בס״ד ותירצו התוספות (שם ע״ב בד״ה משלשים) דכיון דמחזיק מביאן לב״ד ודאי לטובתו באו להחזיקו בקרקע ולא לחייבו פירות:\",1,0],[8,388,21,8,\"שלש כיתי עדים שנתקיים בעדותן וכו'. ברייתא פרק כיצד הרגל (דף כ\\\"ד) העידוהו שנים בראשונה כלומר שנגח נגיחה ראשונה שנים בשניה ושנים בשלישית הרי כאן שלש עדויות והן עדות אחת להזמה נמצאת כת ראשונה זוממת הרי כאן שתי עדויות והוא פטור והם פטורים נמצאת כת שנייה זוממת הרי כאן עדות אחת והוא פטור והן פטורין נמצאת כת שלישית זוממת כולם חייבים ועל זה נאמר ועשיתם לו כאשר זמם כלומר בין כולם חייבים לשלם החצי נזק של העדאת נגיחה שלישית והקשו שאם באו אלו השלש כתות בשלשה ימים יפטרו עצמם הראשונים ויאמרו אנו לא באנו לחייבו אלא חצי נזק דאטו היינו יודעים שיבאו לסוף שלשה ימים ליעדו ואם באו ביום אחד יאמרו האחרונים אנו לא ידענו בעדות הראשונים ואע\\\"פ שהיו שם בב\\\"ד שכל היושבים בבית דין אינם באים להעיד וא\\\"כ לא באנו לחייבו אלא ח\\\"נ ותירצו דקא מרמזי רמוזי כלומר שהיו רומזים אלו לאלו שיעידו רב אשי אמר כשבאו רצופים רבינא אמר במכירין בעל השור ואין מכירין את השור אלא היכי מייעדי ליה דאמרי תורא נגחנא אית לך בבקרך איבעי לך לנטורי לכולהו בקרך פירוש רב אשי אתא למימר אפילו דלא מרמזי רמוזי כגון שבאו רצופין אם באו ביום אחד כולם באו ביחד להעיד ואם בשלשה ימים כיון שבכל עדות באו השלש כתות ביחד רגלים לדבר דידעי הני בהני ואתא רבינא למימר אפילו שלא באו רצופין במכירין בעל השור ואין מכירין את השור דכיון דתם אינו משתלם אלא מגופו ואם אינם מכירים השור ודאי לא לחייבו חצי נזק באו אלא לעשותו מועד שהיו יודעים בעדות הראשונים.\",1,0],[8,388,21,8,\"ובמ\\\"ש רבינו נמצאו שלשתן זוממין כולם חייבים לשלם הנזק שאע\\\"פ שהוא תם משלם חצי נזק קשה למה ישלמו יותר מחצי נזק כיון שעדיין אינו חייב לשלם יותר מחצי נזק. ופירש מורי הרב ה\\\"ר יעקב בירב שדעת רבינו כדעת רבינו תם שכתבו שם התוספות דאע\\\"ג דעדיין לא חייב נזק שלם מ\\\"מ כיון שמייעדים אותו וממילא מתחייב נזק שלם כשהוזמו צריכים לשלם כפי מה שתעלה נגיחה ד' כשיגח, ושיעור לשון רבינו כך הוא נמצאו שלשתן זוממין כלם חייבין לשלם הנזק שאע\\\"פ שכשיעידוהו שלש פעמים עדיין הוא תם עכ\\\"ז משלמין חצי שלישי של צד העדאה ולפי זה אינו מתיישב\",2,0],[8,388,21,8,\"מ\\\"ש משלם חצי נזק לשון יחיד ואם איתא משלמין מיבעי ליה. לכך נ\\\"ל לפרש באופן אחר על פי דרך זו שהוא כאומר תדע שע\\\"כ אע\\\"פ שאינו חייב לשלם נזק שלם כשהוזמו חייבין לשלם שאל\\\"כ לענין הזמה מה בין שתי עדויות הראשונות לעדות אחרונות שעושה אותו מועד והלא אע\\\"פ שהיה תם היה משלם ח\\\"נ ועל כרחין נפקא לן מעדות שלישית שמשלמין לו נ\\\"ש. ועי\\\"ל דה\\\"ק בין כולם חייבין לשלם לו הנזק שעשו לו דהיינו חצי נזק של צד העדאה שכלם סייעו בו דאילו חצי נזק של צד תמות לא סייעו בו שתי כתות הראשונות שאפילו בעדות כת שלישית לבד היה חייב לשלמו שהרי אע\\\"פ שהוא תם חייב לשלם חצי נזק. ואח\\\"כ מצאתי בספר ישן כולם חייבין לשלם חצי נזק וכך היא נסחת דפוס וויניציא וגם נסחא דידן כך יש לפרש דחייבים לשלם הנזק דקתני היינו חצי נזק ולישניה דייקא הכי דקתני חייבים לשלם הנזק ולא קתני משלם נזק שלם וזה פשוט. וכתב נמוקי יוסף פרק חזקת שנראה מדברי רבינו שחילק בשור המועד בין רומזים לשאינם רומזים וכן שאר חילוקים ולא חילק בחזקה דחזקה שאני דכיון דמחזיק מייתי להו מסתברא דלא מייתי איניש חוביה לנפשיה ובודאי ידעו דאיכא סהדי אחריני שמשלימין עדות החזקה הילכך משלשין ביניהם דהך אומדנא דמוכח לא גרעא מרמיזא עכ\\\"ל וכ\\\"כ ההגהות בשם התוספות:\",3,0],[8,388,21,9,\"וכן שנים שהעידו בבן סורר ומורה וכו' עד והוזמו כלן נהרגין. בסנהדרין פרק הנחנקין (סנהדרין דף פ״ו:) אמר אביי הכל מודין בבן סורר ומורה [והכל מודים בבן סורר ומורה] ומחלוקת בבן סורר ומורה הכל מודים בבן סורר ומורה בעדים הראשונים שאין נהרגין מתוך שיכולים לומר להלקותו באנו פירוש דבן סורר ומורה מתרין בו אביו ואמו בפני הדיינים וכשבאים עדים הראשונים שאכל ושתה מגניבה מלקין אותו חזר וגנב ואכל ושתה נידון בכ״ג למיתה. והכל מודים בבן סורר ומורה בעדים אחרונים שנהרגין מתוך שעדים הראשונים יכולים לומר להלקותו באנו כלומר דלית לן למימר אי לאו סהדותא דקמאי לא מיקטיל בסהדותא דהני אלא אמרינן הואיל ויש עונש ע״פ ראשונים שזה לקה על ידיהם תו לא שייכא ההוא סהדותא קמייתא בברייתא והני בתראי כוליה דבר קא עבדי. ומחלוקת בבן סורר ומורה שנים אומרים בפנינו גנב ושנים אומרים בפנינו אכל כלומר בעדות שניה דהנך שתי כתות צריכות זו לזו ואין הראשונים יכולים לומר להלקותו באנו הוי מחלוקת דחזקיה ור' יוחנן דאיפליגו בעדי גניבה ועדי מכירה בנפש שהוזמה דחזקיה אמר דאין נהרגין ור' יוחנן אמר נהרגין כרבנן דאמרי דבר ואפילו חצי דבר והלכתא כוותייהו וכמ״ש ספ״ד:\",1,0],[8,388,21,9,\"העידו שנים שגנבו וכו'. שם אתמר עדי גניבה ועדי מכירה בנפש שהוזמו חזקיה אמר אין נהרגין ורבי יוחנן אמר נהרגין וכו' ואמר רב פפא בעדי מכירה דכ\\\"ע לא פליגי דנהרגין כי פליגי בעדי גניבה וטעמא דר' יוחנן משום דסבר דעדי גניבה לא להלקותו באו דלאו שניתן לאזהרת מיתת בית דין הוא ואין לוקין עליו וא\\\"כ אינן באין אלא להרגו ואע\\\"פ ששתיהן צריכות זו לזו והוה ליה כל חדא חצי דבר מיקטל כרבנן. וצריך עיון למה כתב רבינו בבא שקודם זו העידו שנים שזה גנב נפש מישראל ומכרו והוזמו הרי אלו נחנקין דכל שכן הוא מבבא זו ונראה שהיא הצעה לדין זה:\",2,0],[8,388,21,9,\"העידו שנים שמכרו לזה הישראל וכו'. ג\\\"ז שם אמר רב אסי עדי מכירה בנפש שהוזמו אין נהרגין מתוך שיכול לומר עבדי מכרתי ואמרו שם דאתיא נמי כרבנן ובדלא אתו עדי גניבה. ויש לדקדק בדברי רבינו שכתב שמכרו לזה הישראל דמשמע שאם מכרו לעכו\\\"ם אינו חייב ומנין לנו לומר כן, ונ\\\"ל ששיעור הלשון העידו שמכר לזה הישראל:\",3,0],[8,388,21,9,\"באו עדי גניבה וכו'. שם כשהעמידוהו בדלא אתו עדי גניבה הקשו אי הכי מאי למימרא לא צריכא דאתו לבסוף ואכתי מאי למימרא לא צריכא דקא מרמזי רמוזי מהו דתימא רמיזא מילתא היא קמ\\\"ל רמיזא לאו כלום היא. וא\\\"ת מ\\\"ש דלעיל גבי שור מועד אמרינן דרמיזא מילתא היא ותירצו בתוס' דדיני נפשות שאני:\",4,0],[8,388,21,10,\"מוציא שם רע על אשתו וכו' חזר הבעל והביא עדים וכו'. פ\\\"ק דסנהדרין (דף ט':) אמר רב יוסף הביא הבעל עדים שזנתה והביא האב עדים והזימום לעדי הבעל עדי הבעל נהרגין ואין משלמין ממון חזר והביא הבעל עדים והזימום לעדי האב עדי האב נהרגין [ומשלמין] ממון לזה ונפשות לזה ופירש\\\"י ואין משלמין ממון אע\\\"פ שהיו מפסידים אותה כתובתה אין משלמין טובת הנאת כתובתה וכו' דכיון דבשבילה הן נהרגין אין משלמין לה ממון דמתחייב בנפשו פטור מהתשלומין וכו' ואי משום מאה סלע דהוה בעו לאפסודיה לאב והוה ליה מיתה לזה [לאשה] ותשלומין לזה [לאב] לאו עלייהו רמי לשלומי אלא על הבעל שהרי על ידן הבעל בא לשלם לאב דכל זמן שלא הביא הבעל עדים שזינתה תחתיו אינו מתחייב לשלם מאה סלע ע\\\"י עצמו וכו'. ומשלמין ממון מאה כסף לבעל שבאו לחייב כשהזימו את עדיו. ממון לזה לבעל ונפשות לזה. [ונהרגין בשביל העדים] דקא סבר רב יוסף כי פטר רחמנא מתחייב בנפשו מהתשלומין היכא דמיתה וממון [משום חד] קא אתו עליה עכ\\\"ל. וסובר רבינו דעיקר חידושא דרב יוסף הוא סיפא דמילתא ממון לזה ונפשות לזה אע\\\"פ שהוא מתחייב בנפשו משלם דאילו רישא מילתא דפשיטא הוא דכיון דמתחייב בנפשו הוא ומפני כך השמיט רבינו מרישא ואין משלמין וגם הנהרגין לא כתבו כמי שבא ללמדנו חידוש אלא בדרך פשיטות שכתב הרי עדי הבעל נהרגין. ואם תאמר דהא בפ\\\"ח דהלכות חובל ומזיק פסק רבינו כרבא דאמר בהגוזל בתרא ובפרק בן סורר ומורה רודף שהיה רודף אחר חבירו להרגו ושבר כלים בין של נרדף בין של כל אדם פטור והא כשהכלים הם של כל אדם הוה ממון לכל אדם ונפשות לנרדף ואפילו הכי פטור. ויש לומר דכיון דרודף ניתן להצילו בנפשו הוה ליה מחוייב מיתה לכל אדם והוי מיתה ותשלומין לאחד. אי נמי דדוקא גבי עדים זוממין ממון לזה ונפשות לזה חייב משום דבעינן שתתקיים הזמה כלפי כל אחד אבל ממון ונפשות בחד גברא פטור כיון דמתקיים בו קצת הזמה כך תירצו התוספות בפרק אלו נערות:\",1,0],[8,388,21,10,\"וכן שנים שהעידו על זה שבא על נערה המאורסה וכו'. ג\\\"ז שם (דף י') אמר רבא פלוני בא על נערה מאורסה והוזמו נהרגין ואין משלמין ממון בתו של פלוני והוזמו נהרגין ומשלמין ממון ממון לזה ונפשות לזה ומפרש רבינו דכשהעידו פלוני בא על נערה המאורסה הרי אלו באים לחייב מיתה לזה ולכך נהרגין ואין לומר הם היו באים להפסיד לאבי הנערה הקנס שהיה חייב הבעל ליתן אם לא היו באים אלו שהרי לא הזכירו שם הנערה ולמאן מפסדי אבל כשהזכירו שמה שאמרו בא על בתו של פלוני הרי באו להפסיד לאביה הקנס שהיה הבעל ראוי ליתן לו אילו לא העידו אלו והוה ליה ממון לזה ונפשות לזה וזהו שכתב ומשלמין הקנס לאבי הנערה כנ\\\"ל. ולא כמו שכתוב בספרים ומשלמין הקנס לנטען וכך מצאתי בנסחא מדוייקת ואפילו לפי הנסחאות דגרסי לנטען יש ליישב קצת שפירושו לאביה שטוענין עליו שבתו זנתה:\",2,0],[8,388,21,10,\"פלוני רבע השור וכו'. גם זה שם מימרא דרבא והיא מתפרשת על דרך המימרא הקודמת פלוני בא על נערה מאורסה והוזמו וכו':\",3,0],[8,388,22,1,\"שתי כתי עדים וכו' עד בפני עצמה. בשבועות פרק כל הנשבעין (שבועות דף מ״ז:) ובבתרא פרק חז״ה (דף ל״א:) אתמר שתי כתי עדים המכחישות זו את זו אמר רב הונא זו באה בפני עצמה ומעידה וזו באה בפני עצמה ומעידה פירוש דהואיל ואין ידוע אי זו מהם פסולה אין לך לפסול לא זו ולא זו ורב חסדא אמר בהדי סהדי שקרי למה לי ופסק כרב הונא וכן פסקו הרי״ף והתוס' והביאו הרבה ראיות לזה וכתב הרי״ף עוד דעד אחד מזו הכת ועד אחד מזו הכת אפילו לרב הונא עדותן בטלה דהא בודאי אחד מהם פסול וזהו הדין הראשון שכתב רבינו:\",1,0],[8,388,22,2,\"ראובן שהוציא על שמעון וכו'. שם בשבועות מלוה ולוה ושני שטרות יד בעל השטר על התחתונה כלומר בין לרב הונא בין לרב חסדא שהרי זה בא עליו מכח שתי כתות אחת כשרה ואחת פסולה הילכך גדול יפסיד דמספיקא לא מפקינן ממונא אבל ממ\\\"נ גובה הקטן דיש בכלל מאתים מנה וישבע על השאר כן כתב הרי\\\"ף שם:\",1,0],[8,388,22,2,\"יראה לי ששבועה זו וכו'. הר\\\"ן כתב דשבועת היסת היא זו דליכא למימר דשבועת התורה היא מפני שזה תובעו מאתים וזה אי אפשר לו לכפור במנה דהא כיון שיש עליו שטר שהוא שעבוד קרקעות הוה ליה כטוענו כלים וקרקעות והודה בקרקעות וכפר בכלים ופטור. גם הראב\\\"ד כתב יש מקשים על זה והלא שטר שעבוד קרקעות הוא וכו'. והנה הוא ז\\\"ל חילק השגת הר\\\"ן לשתים. ונ\\\"ל ליישב דעת רבינו דכי אמרינן שאם תבעו מנה חמשים בשטר וחמשים בלא שטר והודה בחמשים שבשטר דלא מיקרי מודה מקצת הטענה היינו כשהוא אומר לו בשטר זה אני תובעך שהרי ידוע לו שבשטר זה ובעדים אלו הוא תובעו וזהו שכתב רבינו בפ\\\"ד דטוען ונטען בדין זה ק' דינרים יש לי בידך נ' שבשטר זה וכן צריך שהחמשים אחרים יתבענו ע\\\"פ שכן כתב גם שם וחמשים בלא שטר אבל הכא שתובע לו ש' בשטר ואנו אומרים שבכלל מאתים מנה כשהוא תובעו אינו מייחד לו מה תובע ממנו בשטר ומה תובע ממנו בלא שטר ולא מקרי שטר שעבוד קרקעות אלא כשהשטר כשר אבל כשאין השטר כשר כי הכא דלא ידעינן הי מינייהו כשר לא קרינן ביה שטר שעבוד קרקעות. ומ\\\"ש הראב\\\"ד ועוד אני אומר וכו' לא קשיא שכיון שזה תובע שני השטרות כאחד כטענה אחת חשיבי ואע\\\"פ שהם שתי כיתי עדים. אבל אי קשיא הא קשיא שאילו היה מודה זה בקנס לא היה צריך לישבע לו על השאר לפי שלא היה אפשר לו לכפור בהם ורבינו כתב בפרק הנזכר שאין מודה במקצת חייב שבועה עד שיודה בדבר שאפשר לו לכפור בו ולא תהא הודאת פיו גדולה מהעדאת עדים אבל לא אמרו שתהא העדאת עדים גדולה מהודאת פיו וצ\\\"ע:\",2,0],[8,388,22,3,\"הוציא ראובן שטר על לוי וכו'. שם שני מלוין ולוה אחד ושני שטרות היינו מתניתין פירוש דקתני דינא דחנוני על פנקסו דכל אחד נשבע ונוטל ואפילו כתוב בשטר נאמנות שבועה בעו אבל רש\\\"י פירש דבשום גוונא אין חילוק בין שטר זה לשאר שטרות אפילו כי ליכא נאמנות לא בעי לאשתבועי ליה אא\\\"כ אמר לו אשתבע לי:\",1,0],[8,388,22,4,\"הוציא ראובן שטר על שמעון וכו'. שם בעיא אליבא דרב הונא ולא איפשיטא ופסק כספיקי ממון דהוו קולא לתובע וכן פסק שם הרי\\\"ף:\",1,0],[8,388,22,4,\"במה דברים אמורים כשבאו שתי הכתות וכו'. כן כתב הרי\\\"ף שם ומילתא דסברא הוא:\",2,0],[8,388,22,5,\"מי שהביא עדים ונחקרה עדותן וכו'. פ\\\"ק דמכות (דף ה':) עובדא דאתא לקמיה דרבי יוחנן ופסק כן משום דאיכא למימר אם הוא מוחזק לחזר אחר עדי שקר כל ישראל מי הוחזקו כלומר לשמוע לו דסתם ישראל בחזקת כשרים:\",1,0],[8,388,22,5,\"אבל שטר שקרא עליו ערער וכו'. בכתובות פרק אלו נערות (כתובות דף ל״ו:) אמר רב פפא ש״מ האי שטרא ריעא לא מגבינן ביה ה״ד וכו' אי דאתו בי תרי ואמרי לדידן אמר לן זייפו לי האי שטרא דכיון דקא מהדר אזיופא אימור זיופי זייף וכתב הר״ן שכך היא גרסת הרי״ף והיא היא גרסת רבינו ולפי זה לא מרעינן אלא שטר שעל אותו פלוני מאותו סך שאומרים העדים שאמר להם לזייף אבל שטרות שיש לו על אותו פלוני שאינן מאותו סך וכן כל שאר שטרות לא ריעי:\",2,0],[8,388,22,5,\"ויראה לי שאם באו עדי השטר וכו'. כלומר וכשכתב ידם יוצא ממקום אחר דאי לאו הכי כיון שאין זוכרים ההלואה אין עדותן עדות כמ\\\"ש בפרק שמיני מהלכות אלו אי נמי אפילו זוכרים ההלואה איצטריך לאשמועינן דסד\\\"א כיון שאין מעידין שחתמו אלא שזוכרים ההלואה וכשכתב זה נראה להם שהוא כתב ידם ליחוש דילמא זייף וכוון לכתוב כתב דומה לחתימות אותם עדים ולא ליהוי אלא מלוה על פה קמ\\\"ל דכיון דעדים זוכרים שראו ההלואה ושזה כתב ידם הרי רגלים לדבר שהשטר כשר ואע\\\"פ שאין זוכרים אם חתמו:\",3,0],[8,388,22,5,\"סליקו הלכות עדות בס\\\"ד\",4,0],[8,389,1,1,\"בית דין הגדול שבירושלים הם עיקר תורה שבעל פה וכו':\",1,0],[8,389,1,4,\"כשהיה ב״ד הגדול קיים וכו' עד זה אוסר וזה מתיר. ברייתא בסנהדרין פרק הנחנקין (סנהדרין דף פ״ח:) תניא אמר ר' יוסי מתחלה לא היו מרבים מחלוקות בישראל וכו' עד ונעשית תורה כשתי תורות. ומה שלא כתב רבינו שבאים לב״ד שסמוך לעירו כמו שכתוב בברייתא הנזכרת לפי שכיון שאנו מחזרים לאי זה בית דין שיודיעם האמת ממילא משמע שילכו לב״ד שסמוך לעירו קודם שיעלו לירושלים או שלא היה בגירסתו של רבינו וזה נראה יותר:\",1,0],[8,389,1,5,\"שני חכמים וכו'. בפ\\\"ק דע\\\"ז (דף ז') תניא היו שנים אחד מטמא ואחד מטהר אחד אוסר ואחד מתיר אם היה אחד מהם גדול בחכמה ובמנין הלך אחריו ואם לאו הלך אחר המחמיר ר' יהושע בן קרחה אומר בשל תורה הלך אחר המחמיר בשל סופרים הלך אחר המיקל אמר רב יוסף הלכה כר' יהושע בן קרחה ומדת\\\"ק מפליג בין גדול בחכמה ובמנין לאינו גדול משמע דריב\\\"ק אפילו אחד גדול מחבירו בחכמה ובמנין בשל תורה הלך אחר המחמיר וכו' ולכך סתם רבינו ולא חילק.\",1,0],[8,389,1,5,\"ומ\\\"ש רבינו שלא בזמן הסנהדרין כלומר דאילו בזמן הסנהדרין לא היינו צריכים לכך שעכ\\\"פ היה מתברר הדין כמ\\\"ש לעיל בסמוך:\",2,0],[8,389,2,1,\"בית דין הגדול שדרשו וכו'. למד כן רבינו ממאי דאשכחן תנאי בתראי דפליגי אקמאי וכן אמוראי בתראי פליגי אקמאי והא דתנן בפ\\\"ק דעדיות (משנה ה') שאם יראה ב\\\"ד את דברי היחיד ויסמוך עליו שאין ב\\\"ד יכול לבטל דברי ב\\\"ד חבירו עד שיהא גדול ממנו בחכמה ובמנין מוקי לה רבינו בשאותו יחיד ואותם רבים נחלקו בגזירה או תקנה כלומר שאם ב\\\"ד פסק כדעת היחיד אין ב\\\"ד אחר יכול לחלוק ולפסוק כדעת הרבים אלא אם היה גדול וכו' וכמו שיתבאר בסמוך אבל אם נחלקו בשזה דורש באחת מן המדות וזה באחרת אה\\\"נ שיכול לבטל דבריו אפילו שאינו גדול כמוהו בחכמה ובמנין. ואם תאמר אם כן אמאי לא פליגי אמוראי אתנאי דהא בכל דוכתא מקשינן לאמורא ממתניתין או מברייתא וצ\\\"ל אנא דאמרי כי האי תנא ואם לא יאמר כן קשיא ליה וכפי דברי רבינו הרשות נתונה להם לחלוק על דברי התנאים. ואפשר לומר שמיום חתימת המשנה קיימו וקבלו שדורות האחרונים לא יחלקו על הראשונים וכן עשו גם בחתימת הגמ' שמיום שנחתמה לא ניתן רשות לשום אדם לחלוק עליה:\",1,0],[8,389,2,1,\"שנאמר אל השופט אשר יהיה בימים ההם וכו'. בר\\\"ה סוף פרק שני (דף כ\\\"ה:) אמרו שיפתח בדורו כשמואל בדורו ומייתי התם קרא דובאת אל הכהנים הלוים ואל השופט אשר יהיה בימים ההם וכי תעלה על דעתך שאדם הולך אצל שופט שלא היה בימיו הא אין לך לילך אלא אצל שופט שיהיה בימיך:\",2,0],[8,389,2,2,\"ב״ד שגזרו גזירה או תקנו וכו'. נראה שרבינו מפרש הא דתנן פ״ק דעדיות שאין ב״ד יכול לבטל דברי ב״ד חבירו עד שיהא גדול ממנו בחכמה ובמנין היינו כשנחלקו בגזירה או תקנה וב״ד של ראשונים ראו לגזור או לתקן כך וב״ד שאחריהם ראו לתקן בענין אחר אינם יכולים לבטל דברי הראשונים עד שיהיו גדולים מהם בחכמה ובמנין אבל דברים שראו ב״ד לגזור ולאסור לעשות סייג אם פשט איסורן בכל ישראל אין ב״ד הגדול אחר יכול לעקרן אפילו היה גדול מהראשונים. וא״ת הא אמרינן בגיטין פרק השולח (גיטין דף ל״ו:) גבי התקין הלל פרוזבול אמר שמואל אי איישר חילי יותר מהלל אבטליניה ואמרינן נמי התם דאי לדרי עלמא תקין הלל פרוזבול אין בידינו כח לבטל דאין ב״ד יכול לבטל דברי ב״ד חבירו וכו' משמע הא גדול בחכמה ובמנין יכול לבטלן. י״ל דפרוזבול לאו גדר הוא פן יפרצו על דברי תורה דאדרבה דין תורה הוא שישמט והלל הפקיע הממון ותיקן דלא לישמיט ואע״ג דאמרינן התם שהתקין פרוזבול לפי שראה שנמנעו העם מלהלוות זה את זה ועוברים על מה שכתוב בתורה השמר לך פן יהיה דבר עם לבבך בליעל לאו איסורא לגמרי הוו עבדי כשנמנעין מלהלוות דהא שב ואל תעשה הוא ודרך כלל עיקר תקנת הפרוזבול לא היה סייג לתורה אלא מפני תקנת העניים שלא תנעול דלת בפניהם ומפני תקנת העשירים שלא יפסידו וכן פירש״י שם על הא דבעי מאי פרוזבול אמר רב חסדא פרוס בולי ובוטי כלומר עשירים ועניים ובהא ניחא לי למה פירש בו רב חסדא שהוא פרוז בוטי דאנן פרוזבול קרינן דהיינו תקנת העשירים שלא יעברו על ד״ת ומנ״ל לפרושי דהוא נמי תקנת העניים אלא משום דמשמע דלאו סייג לתורה עבד אלא תיקון לעשירים שלא יפסידו ותיקון לעניים שלא תנעול דלת בפניהם וכמו שכתבתי ובריש מגילה נמי דאמרינן ואי ס״ד אנשי כנסת הגדולה י״ד וט״ו הוא דתקון אתו רבנן ועקרו תקנתא דתקינו אנשי כנסת הגדולה הא אין ב״ד יכול לבטל דברי חבירו אא״כ היה גדול וכו' התם ודאי לאו סייג לתורה הוא ומש״ה אי איכא גדולים מהם בחכמה ובמנין יכולין לעקור תקנתם. אך קשה מדפריך בע״ז פרק אין מעמידין (עבודה זרה דף ל״ז) אהא דאמרינן דר' יהודה נשיאה התיר את השמן של עכו״ם דהיכי מצי למישבק תקנתא דהלל ושמאי והתנן אין ב״ד יכול לבטל דברי ב״ד חבירו וכו' והא ודאי גזרת שמן משום סייג הוא כדאמרינן פ״ק דשבת (דף י״ז:) גזרו על שמנן משום יינן וא״כ היכי פריך מדתנן אין ב״ד יכול לבטל אא״כ היה גדול וכו' דמשמע הא אם היה גדול יכול לבטל והרי רבינו כתב בסמוך דבדבר שהוא סייג אפי' גדול אין יכול לבטל. לכך י״ל דהכי פריך היאך ביטל תקנת הראשונים הא אפילו היתה מאותם שיכול ב״ד אחר לבטלם כגון שלא היתה לסייג ולגדר לא היה יכול לבטלה דהא אין ב״ד יכול וכו' ומ״ש הראב״ד ולא אפילו אליהו וב״ד וכו' יתבאר בסמוך:\",1,0],[8,389,2,2,\"היה גדול בחכמה וכו' עד לבטל דבריו. ג״ז שם באותה משנה. וכתב הראב״ד עיטור שוקי ירושלים בפירות קשיא עליה וכו' מפני שנתבטל הטעם של ראשונים ולא היה גדול כראשונים עכ״ל. פירוש דבריו דאמרינן בפ״ק דביצה (דף ה') שתיקנו חכמים שמהלך יום אחד לכל צד לא יפדו פירות נטע רבעי אלא יעלו ויאכלום בירושלים ומפרש התם טעמא כדי לעטר שוקי ירושלים בפירות ואמרינן נמי התם דר' יוחנן בן זכאי נמנה עליהם והתיר שלא יעלו הפירות לירושלים אלא יפדו ויאכלום במקומם משום דבתר חרבן מה לנו לעטר את שוקי ירושלים לצורך העכו״ם ומ״מ קושית הראב״ד איני מכיר דמי אמר לו שריב״ז לא היה גדול כראשונים וא״ת מדאמרינן בפרק יש נוחלין (בבא בתרא דף קל״ד) וכן בסוכה (דף כ״ח) פ' תלמידים היו לו להלל גדול שבכלן יונתן בן עוזיאל קטן שבכלן ריב״ז דילמא קטן שבכלם לא בחכמת התורה קאמר אלא בשאר חכמות הוא שהיו גדולים ממנו תדע דהא קאמר התם שלא הניח ממשלות כובסים משלות שועלים שיחת שדים ושיחת מלאכי השרת ומעשה מרכבה ובאותן חכמות אפשר שהיו גדולים ממנו אבל לא בחכמת התורה וראיה לדבר שנתמנה נשיא וראש ישיבה במקום הלל ואם היה קטן שבתלמידים היאך היו ממנים אותו ולא היו ממנים לאחד מהגדולים אלא ודאי בחכמת התורה גדול כמותם ואפשר גדול מהם היה ועוד דאפילו נימא שגם בחכמת התורה היה קטן מכולם כבר אפשר שהיה גדול ממתקני התקנה ההיא ואל יקשה בעיניך היאך אחרונים גדולים מהראשונים דהא אשכחן רבה דהוה גדול מרב יהודה כדאמרינן (תענית כ״ד וע״ע ברכות כ') רב יהודה כי הוה מטי להאשה שהיא כובשת ירק הוה אמר הוייות דרב ושמואל חזינא הכא ואילו אנן מתנינן תליסר מתיבתא ומאי דאמרינן בפ״ק דביצה (דף ד':) והשתא דידעינן בקביעא דירחא מאי טעמא עבדינן תרי יומי משום דשלחו מתם הזהרו במנהג אבותיכם שבידכם זמנין דגזרי המלכות גזירה ואתי לאיקלקולי משמע דאי לא משום חששא דגזירה לא עבדינן תרי יומי והא ודאי אין ב״ד שבימי האמוראים גדול כשל המתקנים שני ימים אלמא שאע״פ שאינו גדול ממנו כיון דאיבטיל טעמא יכול לבטלו יש לומר דהתם ה״ק כיון דבקיאינן בקיבועא דירחא מאי טעמא עבדינן תרי יומי היה להם לחכמים שבאותו זמן שהיו מהקובעים שני ימים לתקן דלא נעביד תרי יומי אי נמי דהוה קים להו שהמתקנים אמרו בפירוש אם יבא זמן שיעמדו על החשבון ולא על פי הראיה לא נעביד תרי יומי ולדעת הראב״ד ה״ל לגמ' לאקשויי עליה מדתנן אין ב״ד יכול לבטל דברי בית דין חבירו וכו' ולתרוצי דהיינו במידי דלא נתבטל הטעם אבל היכא שנתבטל הטעם יכול לבטל אפילו אינו גדול כמוהו:\",2,0],[8,389,2,2,\"אפילו בטל הטעם וכו'. בפרק קמא דביצה (דף ה') אמרינן דדבר שנאסר במנין אע\\\"פ שנתבטל הטעם צריך מנין אחר להתירו ומשמע לרבינו דהיינו מנין גדול ממנו וה\\\"ה דבעינן שיהיה חכם ממנו וחדא מינייהו נקט:\",3,0],[8,389,2,3,\"במה דברים אמורים בדברים שלא אסרה אותם וכו'. נ״ל שלמד כן רבינו מדאמרינן בע״ז פרק אין מעמידין (עבודה זרה דף ל״ו) בכל בית דין יכול לבטל דברי בית דין חבירו חוץ מי״ח דבר שאפילו יבא אליהו ובית דינו אין שומעין לו ומשמע לרבינו דה״פ בכל תקנות בית דין יכול בית דין אחר לבטל דבריו חוץ מי״ח דבר וכיוצא בהם שהם דברים שנעשו סייג לתורה דמאי רבותא די״ח דבר משאר תקנות דהנהו דפרק קמא דביצה דביצה שנולדה ביום ראש השנה אסורה ביום שני אין שם סייג לאסור ביום שני של ראש השנה יותר משני ימים של שאר ימים טובים וההיא דעיטור שוקי ירושלים בפירות ודאי דאין שם משום סייג וכן בההיא דפרוזבול דאמר שמואל אי איישר חילי (מהלל) אבטליניה אין בו סייג לתורה כמו שהוכחתי למעלה.\",1,0],[8,389,2,3,\"ומה שכתב רבינו אם פשט איסורן בכל ישראל. כך אמרו שם בפרק אין מעמידין אהא דבכל בית דין יכול לבטל דברי בית דין חבירו חוץ מי\\\"ח דבר אמר רב משרשיא מה טעם הואיל ופשט איסורו ברוב ישראל וכתב רבינו בכל ישראל על סמך מאי דקי\\\"ל רובו ככולו וכיון ששיטה זו אפשרית אין כח ביד הראב\\\"ד לדחותה מפני שיטתו דלא שני ליה בין תקנות שהם לסייג לתקנות שאינם לסייג וכולי טעמא תלי בפשט איסורן או לא פשט ולפיכך כתב למעלה א\\\"א לא אפילו אליהו ובית דינו הואיל ופשט איסורן בכל ישראל כדאיתא בע\\\"ז עכ\\\"ל. וכבר יישבתי ההיא דע\\\"ז לדעת רבינו:\",2,0],[8,389,2,4,\"ויש לבית דין לעקור וכו'. זה פשוט בעצמו ולא הוצרך לכתבו אלא דלא נימא חכמים עשו חיזוק לדבריהם יותר משל תורה אפילו בכי הא קמ\\\"ל דלא.\",1,0],[8,389,2,4,\"ומ״ש דאפילו דברי תורה יש לכל בית דין לעקרו. הכי תניא בסנהדרין פרק נגמר הדין (סנהדרין דף מ״ו) אראב״י שמעתי שב״ד מכין ועונשין שלא מן הדין ולא לעבור על ד״ת כלומר לקבוע הלכה כן אלא לעשות סייג לתורה כלומר לפי שעה וכבר נתבאר זה בדברי רבינו פ' (ארבעה ועשרים) מהלכות סנהדרין:\",2,0],[8,389,2,5,\"בית דין שנראה להם לגזור וכו'. פרק אין מעמידין (עבודה זרה דף ל\\\"ז) וסמכו רבותינו על דברי רשב\\\"ג ורבי אליעזר ברבי צדוק שהיו אומרין אין אנו גוזרין גזירה על הצבור אלא א\\\"כ רוב הצבור יכולים לעמוד בה:\",1,0],[8,389,2,6,\"הרי שגזרו בית דין גזירה ודימו וכו'. נ\\\"ל שלמדה מדאמרינן באין מעמידין (דף ל\\\"ה) אהא דשאל ר' ישמעאל את ר' יהושע מפני מה אסרו גבינת העכו\\\"ם אמר עולא כי גזרי גזירה במערבא לא מגלו טעמא עד תריסר ירחי שתא דילמא איכא איניש דלא ס\\\"ל ואתו לזלזולי בה ואם איתא שבית דין יכולים לכוף שתתפשט מאי איכפת לן דמאן דמזלזל בה יכפוהו בית דין אלא משמע שאם יפקפקו בה ולא פשטה אינן רשאין לכוף את העם ללכת בה ועוד דקל וחומר הוא מהדין שכתב רבינו בסמוך גזרו ודימו שפשטה וכו' שאם אפילו אחר כמה שנים בית דין קטן מהם יכול לבטלה כל שכן שהן עצמם אינם יכולים לכוף את העם ללכת בה:\",1,0],[8,389,2,7,\"גזרו ודימו שפשטה וכו'. בפרק אין מעמידין (עבודה זרה דף ל״ז) כי פרכינן רבי יהודה נשיאה היכי שרי מישחא דהא לא היה גדול כתלמידי שמאי והלל שאסרוהו ועוד שהוא מי״ח דבר ואפילו אליהו ובית דינו אינו יכול לבטלן מהדרינן דשמן לא פשט איסורו ברוב ישראל דאמר רבי שמואל בר אבא אמר רבי יוחנן ישבו רבותינו ובדקו על שמן שלא פשט איסורו ברוב ישראל וסמכו רבותינו על דברי רשב״ג ורבי אלעזר ברבי צדוק שהיו אומרים אין גוזרים גזירה על הצבור אלא א״כ רוב הצבור יכולים לעמוד בה וה״פ לדעת רבינו כיון שמצאו שלא פשט איסורו אמרו להתירו שהרי מצינו שאין גוזרים גזירה על הצבור אלא אם כן רוב הצבור יכולין לעמוד בה וכיון דכן אפילו גזרו לא הויא גזירה הרי כאן מפורש דרבי יהודה נשיאה לא היה גדול כראשונים וגם היה דבר שהוא סייג לתורה כדאמרינן בפ״ק דשבת גזרו על שמנן משום יינן ואפ״ה התירו לפי שלא פשט איסורו בכל ישראל. וא״ת והיכי סמך רבי יהודה נשיאה על מה שבדק דילמא בימי הראשונים נתפשט ואח״כ פקפקו בה ומתוך כך היה נ״ל לומר שאפילו נתפשטה בתחלה כיון שעכשיו אין רוב ישראל נוהגין בה מתירין אותה אלא שראיתי שכתב רש״י לא פשט עדיין לא החזיקו רובן באותה גזירה לנהוג בה איסור משמע מלשונו שבדק רבי יהודה נשיאה אם מיום שנגזרה גזירה עד היום פשט איסורו באיזה זמן ומצא שבשום זמן לא פשט איסורו בכל ישראל:\",1,0],[8,389,2,8,\"וכל בית דין שהתיר וכו'. שם (דף ל\\\"ז) אמרו דר' יהודה נשיאה התיר שני דברים ואמרו לו שיתיר גם את הפת ולא רצה דאם כן קרו לן בי דינא שריא דתנן בסוף עדיות (פ\\\"ח מ\\\"ד) שהעיד יוסי בן יועזר על שלשה דברים להתיר וקרו ליה יוסי שריא:\",1,0],[8,389,2,9,\"הואיל ויש רשות לגזור וכו'. כתב הראב\\\"ד א\\\"א את כל אלה ישא רוח וכו'. ואני אומר שמ\\\"ש הראב\\\"ד שכל דבר שגזרו עליו ואסרוהו וכו' וכי רבינו אינו אומר כן שהוא משיג עליו שהרי בשר עוף בחלב שהביא רבינו לדמיון ודאי שלעולם אסור וגם בתחלת דבריו כתב כן בפירוש הואיל ויש רשות לבית דין לגזור ולאסור דבר המותר ויעמוד איסורו לדורות ואם סמך השגתו במה שאמר וסמכוהו למקרא וכו' והלא רבינו אינו אומר שאסור אלא כשאומרים שהוא של תורה ממש אבל כשאומרים קרא אסמכתא בעלמא הרי הם אומרים שאינו של תורה ושאין הפסוק ההוא מורה עליו אלא שהוא אסמכתא בעלמא. ומ\\\"ש ואם גרע לפי צורך שעה וכו' כבר כתב רבינו בפרק זה וכן אם ראו לבטל מצות עשה או לעבור על מל\\\"ת כדי להחזיר רבים לדת וכו' עושין לפי מה שצריכה השעה. ומ\\\"ש ולא תמצא איסור מוסיף וכו' נראה שזה עיקר השגתו ולא ידעתי טעם לסברתו וכי האומר שבשר עוף בחלב אסור מן התורה שהתורה אסרה מין אחד של בשר וה\\\"ה לכל מידי דמיקרי בשר לא יקרא מוסיף הא ודאי מוסיף נקרא:\",1,0],[8,389,2,9,\"על מ\\\"ש רבינו\",2,0],[8,389,2,9,\"פה מפי השמועה למדו שזה שאסר הכתוב וכו' בין בשר בהמה בין בשר חיה. קשה ממ\\\"ש בפרק תשיעי מהלכות מאכלות אסורות דבשר חיה אינה אלא מד\\\"ס וי\\\"ל דהתם קושטא דמילתא קאמר שפסק כר\\\"ע אבל מ\\\"מ כיון דחזינן בגמרא (חולין קט\\\"ז) דלוי איקלע לבי (יוסף רישבא) ואמר אתריה דר\\\"י בן בתירא הוה ואמינא דילמא דרש להו כר\\\"י הגלילי מעתה כשיעמוד ב\\\"ד ויאמר בשר חיה מותר מן התורה אלא שאנו נאסור אותו מפני סייג כבר אפשר שיהיה גורע אם יהיה במקום שנוהגין כרבי יוסי הגלילי וכדי ליקח משל בדבר דשייך ביה גורע ושייך ביה מוסיף נקטה בענין זה ולא חשש שנבוא לטעות מכאן לענין הדין מאחר שבמקומו (פסק) כר' עקיבא דחיה אינה מן התורה:\",3,0],[8,389,3,1,\"מי שאינו מודה בתורה שבעל פה וכו'. זה דעת רבינו וכ\\\"כ בפירוש המשנה בסנהדרין פרק הנחנקין:\",1,0],[8,389,3,2,\"ולא מעלין אותו והרי הוא כשאר וכו'. ברייתא בפרק אין מעמידין (עבודה זרה דף כ״ו) האפיקורסים והמסורות והנהפכים לע״ז מורידין ולא מעלין אותן כלומר מן הבור מסורות המוסרים ממון חבריהם לאנס ומשמע בגמרא דהיינו להכעיס דשביק היתרא ואכיל איסורא אבל לתיאבון מצוה להצילו ואסור לעמוד על דמו וכ״כ רבינו פרק רביעי מהלכות רוצח ושמירת נפש. ועל מ״ש ולא מעלין הקשו בגמרא השתא (אחותי אחתינן) אסוקי מבעיא ותירצו שאם היה סולם בבור מסלקו ואמר בעינא לאחותי ברי מאיגרא ועוד תירצו תירוצים בתחבולות כיוצא בזו נאמרו שם:\",1,0],[8,389,3,3,\"במה דברים אמורים באיש שכפר בתורה שבעל פה וכו'. זה דעת רבינו וכ\\\"כ בפירוש המשנה בפ\\\"ק דחולין:\",1,0],[8,389,3,4,\"אבל זקן ממרא האמור בתורה הוא חכם אחד מחכמי וכו'. מפורש בסנהדרין פרק הנחנקין (סנהדרין דף פ״ז) כמו שיתבאר בסמוך.\",1,0],[8,389,3,4,\"ומ\\\"ש שיש בידו קבלה ודן פירוש שיש בידו קבלה ואומר כך קבלתי או שהוא דן באחת מהמדות שהתורה נדרשת בהן:\",2,0],[8,389,3,4,\"ומ״ש מתודה ויש לו חלק לעוה״ב. בפרק נגמר הדין (סנהדרין דף מ״ג) שנינו שכל מי שיוצא ליהרג אומרין לו התודה לפי שכל המתודה יש לו חלק לעוה״ב וכתב רבינו בזקן ממרא שמתודה ויש לו חלק לעוה״ב לאפוקי ממי שאינו מודה בתורה שבע״פ שאותו אין לו חלק לעוה״ב:\",3,0],[8,389,3,4,\"אף על פי שהוא דן והם דנין הוא קבל והם קבלו הרי וכו'. שם (דף פ\\\"ח) אמר רב כהנא וכו' אינו נהרג עד שיאמר כך הוא בעיני והן אומרים מפי השמועה וכו' ור' אלעזר אמר אפילו הוא אומר מפי השמועה והם אומרים כך הוא בעינינו נהרג כדי שלא ירבו מחלוקות בישראל ואסיקנא לדרב כהנא בתיובתא וקם ליה הלכה כרבי אלעזר וזהו שכתב רבינו אע\\\"פ שהוא דן והן דנים דהיינו הוא אומר כך נראה בעיני והם אומרים כך נראה בעינינו הוא קבל והם קבלו ר\\\"ל דהיינו הוא אומר מפי השמועה והם אומרין מפי השמועה והיינו דלא כרב כהנא וממילא משמע דה\\\"ה לאם הוא קבל והם דנין שנידון בזקן ממרא ובפ' ד' כתב רבינו כן בפירוש וכאן כתב כללי הדין ולא חשש לפרטיו:\",4,0],[8,389,3,4,\"ואם רצו ב\\\"ד למחול על כבודן וכו'. שם אמר ר' יאשיה שלשה דברים סח לי זעירא מאנשי ירושלים בעל שמחל על קנויו קנויו מחול בן סורר ומורה שרצו אביו ואמו למחול לו מוחלין לו זקן ממרא שרצו בית דין למחול לו מוחלין לו וכשבאתי אצל חברי שבדרום על שנים הודו לי על זקן ממרא לא הודו לי כדי שלא ירבו מחלוקות בישראל:\",5,0],[8,389,3,7,\"אין זקן ממרא חייב מיתה עד שיהא וכו'. ברייתא שם (דף פ\\\"ו:) כי יפלא במופלא שבבית דין הכתוב מדבר וכתב רבינו בפירוש המשנה דה\\\"פ מי שלא יפלא ממנו אלא הדבר הנפלא הקשה אבל תלמיד שלא הגיע להוראה הכל אצלו פלא:\",1,0],[8,389,3,7,\"ויחלוק על ב\\\"ד בדבר שזדונו כרת ושגגתו חטאת או בתפילין. שם (דף פ\\\"ז) תנו רבנן זקן ממרא אינו חייב אלא על דבר שזדונו כרת ושגגתו חטאת דברי ר\\\"מ רבי יהודה אומר על דבר שעיקרו מדברי תורה ופירושו מדברי סופרים ר' שמעון אומר אפילו דקדוק אחד מדקדוקי סופרים ופסק רבינו כר\\\"מ משום דאיתא התם ברייתא ז\\\"ל כי יפלא במופלא שבב\\\"ד הכתוב מדבר ממך זה יועץ כלומר שנחלק בעיבור השנה הקרוי סוד ועצה וכן הוא אומר ממך יצא חושב על ה' רעה יועץ בליעל דבר זו הלכה כלומר הל\\\"מ וכו' בין דם לדם בין דם נדה או דם לידה או דם זיבה בין דין לדין בין דיני נפשות או דיני ממונות או דיני מכות בין נגע לנגע בין נגעי אדם או נגעי בתים או נגעי בגדים דברי אלו הערכין והחרמים וההקדשות ריבות זו השקאת סוטה ועריפת העגלה וטהרת המצורע בשעריך זו לקט שכחה ופאה ואמרינן התם אמר ליה רב הונא בר חיננא לרבא תרגמה לי להא מתניתא אליבא דר\\\"מ אמר ליה רבא לרב פפא פוק תרגימה ליה ותרגמה לו דמכל הני שהוזכרו בברייתא נפיק מינייהו דבר שחייבין על זדונו כרת ושגגתו חטאת וכמו שנתבאר בדברי רבינו בפרק שאחר זה הברייתא ותרגומה וכיון דחזינן הני אמוראי בתראי דמהדרי לאוקומי ברייתא אליבא דר\\\"מ אלמא כוותיה קי\\\"ל דאינו חייב אלא על דבר שזדונו כרת ושגגתו חטאת ולקמן בגמ' (דף פ\\\"ח:) אמרינן אמר ר' אלעזר אמר ר' אושעיא אינו חייב אלא על דבר שעיקרו מדברי תורה ופירושו מדברי סופרים ויש בו להוסיף ואם הוסיף גורע ואין לנו אלא תפילין אליבא דרבי יהודה ופירש\\\"י ויש בו להוסיף על מה שפירשו חכמים ואם הוסיף גורע ופוסל הראשון בתוספתו ואין לנו אלא תפילין שעיקרן בתורה ופירושן מדברי סופרים שהם ארבעה בתים ויש להוסיף חמשה או יותר ואם הוסיף גורע דקא עבר בבל תוסיף ולא עבד מצוה עכ\\\"ל. ומעתה כיון שרבינו פוסק כר\\\"מ דאינו חייב אלא על דבר שזדונו כרת ושגגתו חטאת לא היה לו לכתוב או בתפילין דכיון דתפילין לא נפיק מינייהו דבר שחייבין על זדונו כרת ושגגתו חטאת אינו נעשה זקן ממרא כשנחלק בהם וכבר השיגו הראב\\\"ד ז\\\"ל בפרק שאחר זה שכתב חוץ ממצות תפילין בלבד וכו' א\\\"א זה שבוש דלדעת ר\\\"מ הוא דבעינן דבר שזדונו כרת ושגגתו חטאת ובתפילין פטור ולדעת ר' יהודה הוא שחייב בתפילין עכ\\\"ל. ונראה לי דסבירא ליה לרבינו דר' אלעזר א\\\"ר אושעיא לפרושי מילתיה דר' יהודה אתא והכי קאמר אע\\\"פ שר' יהודה לא הזכיר אלא דבר שעיקרו מדברי תורה ופירושו מדברי סופרים עוד צריך לדעתו תנאי אחר שיש בו כדי להוסיף ואם הוסיף גורע וכפי התנאים האלו נמצא שאין שם דבר שיתחייב עליו זקן ממרא אלא על תפילין לפי שאין דבר שיתקבצו בו התנאים האלה אלא תפילין אליבא דר' יהודה כלומר האי מימרא דר' אושעיא פירוש מילתא דר' יהודה היא וכיון שבא לפרש דברי ר' יהודה אלמא כוותיה קיימא לן ועוד דהא כלל בידינו ר\\\"מ ור\\\"י הלכה כר' יהודה ולדחוייה לדר\\\"מ א\\\"א דהא אמוראי בתראי מהדרי לאוקומי ברייתא אליביה כמו שכתבתי הילכך כתרוייהו קי\\\"ל דבדבר שחייבין על זדונו כרת ועל שגגתו חטאת או בתפילין הוא נעשה זקן ממרא ושאר דברי הראב\\\"ד באותה השגה אפרשם ואיישבם בפרק הבא בסייעתא דשמיא. והרמ\\\"ה הקשה על דברי רבינו מאי קסבר אי סבר כר\\\"מ אתפילין נמי לא לחייב ואי סבר כסתם משנה דמחייבא אתפילין ההיא ודאי דלא כר\\\"מ ותירצו לו דר\\\"י מוסיף הוא על דברי ר\\\"מ לחייב אפילו על דבר שאין זדונו כרת ושגגתו חטאת אי איכא תורה ויורוך:\",2,0],[8,389,3,7,\"ויורה לעשות כהוראתו. משנה שם (דף פ\\\"ו:) אינו חייב עד שיורה לעשות שנאמר והאיש אשר יעשה בזדון.\",3,0],[8,389,3,7,\"ומה שכתב או יעשה הוא על פי הוראתו. ברייתא שם ואפרשנה בסוף פרק זה בעזרת שדי:\",4,0],[8,389,3,7,\"ויחלוק עליהן והן יושבים בלשכת הגזית. ברייתא שם (דף פ\\\"ז) ועלית אל המקום מלמד שהמקום גורם והיינו לאפוקי אם מצאם חוץ למקומם והמרה עליהם ובהדיא תניא בפ\\\"ק (דף י\\\"ד:) מצאן זקן ממרא לב\\\"ד אבית פאגי והוא מקום לפנים מחומת ירושלים והמרה עליהם יכול תהא המראתו המראה ת\\\"ל וקמת ועלית אל המקום מלמד שהמקום גורם ופירש\\\"י והתוספות דבית פאגי לאו דוקא אלא כ\\\"מ חוץ ללשכת הגזית אינו מקומן:\",5,0],[8,389,3,7,\"אבל אם היה תלמיד וכו'. משנה בפרק הנחנקין (סנהדרין דף פ״ו:).\",6,0],[8,389,3,7,\"ומ\\\"ש שנאמר כי יפלא וכו' עד מלמד שהמקום גורם לו מיתה. כבר נתבאר מתוך מה שכתבתי בסמוך:\",7,0],[8,389,3,7,\"וכל אלו וכיוצא בהן שהן וכו':\",8,0],[8,389,3,8,\"וכיצד דנין זקן ממרא וכו' עד ה\\\"ז פטור. משנה בהנחנקין שם. אך\",1,0],[8,389,3,8,\"במ\\\"ש אם שמע וקבל מהן מוטב. כתוב במשנה אם שמעו אמרו להם ומפשט הדברים נראה דה\\\"ק אם אותו ב\\\"ד ששמעו אותו דין אמרו להם הדין ומדברי רבינו נראה שהוא מפרשה כך אם שמעו זקן ממרא וקבלו לעשות כדברי אותו ב\\\"ד אמרו להם סברתם:\",2,0],[8,389,3,8,\"הורה לעשות או שעשה וכו'. משנה שם כתבתיה למעלה אינו חייב עד שיורה לעשות ובברייתא (דף פ\\\"ח:) ת\\\"ר אינו חייב עד שיעשה כהוראתו או שיורה לאחרים ויעשו כהוראתו ופריך בגמ' בשלמא יורה לאחרים ויעשו כהוראתו מעיקרא כלומר קודם שיבא לבית דין שבלשכת הגזית לישאל לאו בר קטלא הוא והשתא בר קטלא אלא שיעשה כהוראתו מעיקרא נמי בר קטלא הוה התינח היכא דאורי בחלב ודם דמעיקרא לאו בר קטלא והשתא בר קטלא אלא היכא דאורי בחייבי מיתת ב\\\"ד מעיקרא נמי בר קטלא הוא מעיקרא בעי התראה השתא לא בעי התראה מסית דלא בעי התראה כלומר אם היה מסית ומורה טעם היתר לומר אין בלשון זה הסתה מאי איכא למימר הא מעיקרא נמי מיקטיל בלא התראה מעיקרא אי אמר טעמא לזכותא לאצוליה מקבלינן מיניה השתא אי אמר טעמא לא מקבלינן מיניה שהרי שמע מפי ב\\\"ד שלא לעשות והמרה:\",3,0],[8,389,3,8,\"גומרין דינו למיתה בב\\\"ד שבעירו. בפ\\\"ק דסנהדרין (דף ט\\\"ז) תנן דאין דנין נביא שקר אלא בב\\\"ד של ע\\\"א ואמרינן בגמ' מה\\\"מ אר\\\"י בר חנינא אתיא הזדה הזדה מזקן ממרא מה להלן בשבעים ואחד אף כאן בע\\\"א והא הזדה כי כתיבא בקטלא הוא דכתיב וקטלא בכ\\\"ג הוא הרי מפורש דקטלא דזקן ממרא הוי בכ\\\"ג וא\\\"א דאקטלא ממש דהא בהדיא תנן דאינו אלא בב\\\"ד הגדול כמו שאכתוב בסמוך אלא על גמר דינו קאמר שהוא בכ\\\"ג וכן משמע מתוך פירש\\\"י וזהו שכתב רבינו גומרין דינו למיתה בב\\\"ד שבעירו:\",4,0],[8,389,3,8,\"ואין ממיתין אותו בב״ד שבעירו וכו'. משנה בפרק הנחנקין (סנהדרין דף פ״ט) אין ממיתין אותו לא בב״ד שבעירו ולא בב״ד שביבנה אלא מעלין אותו לב״ד הגדול שבירושלים ומשמרין אותו עד הרגל וממיתין אותו ברגל שנאמר וכל העם ישמעו וייראו דברי ר״ע רבי יהודה אומר אין מענין דינו של זה אלא ממיתין אותו מיד וכותבין ושולחים בכל המקומות איש פלוני נתחייב מיתה בב״ד ומפרש רבינו דולא בבית דין שביבנה היינו אם ב״ד הגדול יצא חוץ לירושלים.\",5,0],[8,389,3,8,\"ומ\\\"ש ועד הרגל משמרין אותו. פסק כר\\\"ע לגבי רבי יהודה דהלכה כר\\\"ע מחבירו:\",6,0],[8,389,3,8,\"וארבעה צריכין הכרזה זקן ממרא ועדים וכו'. ברייתא שם. והוי יודע שאין הכרזת אלו הארבעה שוה שזקן ממרא משמרין אותו עד הרגל כמ\\\"ש רבינו בסמוך והשלשה האחרים ממיתין אותם מיד והכרזתם היא ששולחים בכל המקומות איש פלוני נתחייב מיתה בב\\\"ד וכן כתב רבינו בסוף הלכות אלו על בן סורר ומורה ובפרק י\\\"ח מהל' עדות גבי עדים זוממים והיינו טעמא דכיון דלא אשכחן לר\\\"ע דפליג אלא בזקן ממרא אלמא באינך כרבי יהודה סבירא ליה וכבר כתבתי זה שם:\",7,0],[8,389,4,1,\"זה שחלק על בית דין הגדול בדבר וכו' אפילו היה הוא מפי הקבלה וכו'. כבר כתבתי פרק שלפני זה דפלוגתא דרב כהנא ור\\\"א היא בפרק הנחנקין ואיתותב רב כהנא וקיימא לן כר\\\"א דאמר אפילו הוא אומר מפי השמועה והם אומרים כך הוא בעינינו נהרג:\",1,0],[8,389,4,1,\"וכן אם חלק עליהם בגזרה מן הגזירות וכו'. דבר זה פשוט בעצמו שכיון שהמקדש בחמץ משש שעות ולמעלה אין חוששין לקידושיו כדאיתא בפירקא קמא דפסחים ונתבאר בדברי רבינו בהלכות אישות הרי מחלוקת זה בדבר שחייבים על זדונו כרת ושגגתו חטאת:\",2,0],[8,389,4,2,\"אחד דבר שחייבין על זדונו כרת וכו' עד בין הוא מחמיר והם מקילין חייב ואם לא תבא המחלוקת לידי כך פטור. הכל ברייתא בהנחנקין כתבתיה בפרק שלפני זה וגם שם כתבתי שתרגמוה אליבא דרבי מאיר וכמ\\\"ש רבינו. אך קשה\",1,0],[8,389,4,2,\"במ\\\"ש וכן אם נחלקו בהשקאת סוטה וכו' הרי זו אסורה ליבמה וכו' שאין איסור הסוטה על יבמה להתחייב עליה כרת וצ\\\"ע מנ\\\"ל הא ורש\\\"י פירש בע\\\"א דוק ותשכח:\",2,0],[8,389,4,3,\"חוץ ממצות תפילין בלבד וכו': כתב הראב\\\"ד זה שבוש דלדעת ר\\\"מ הוא דבעינן דבר שזדונו כרת ושגגתו חטאת וכו'. וכבר השבתי לתחלת דבריו בפרק שקודם זה ולהשיב ליתר דבריו אכתוב לשון הגמרא ואוכיח דעת רבינו. בסנהדרין (דף פ\\\"ח:) גרסינן אמר ר\\\"א א\\\"ר הושעיא אינו חייב אלא על דבר שעיקרו מדברי תורה ופירושו מד\\\"ס ויש בו להוסיף ואם הוסיף גורע ואין לנו אלא תפילין אליבא דרבי יהודה והא איכא לולב דעיקרו מדברי תורה ופירושו מד\\\"ס ויש בו להוסיף ואם הוסיף גורע בלולב מאי סבירא לן אי ס\\\"ל דלולב אין צריך אגד האי לחודיה קאי והאי לחודיה קאי כלומר ואין זה גורע ואי סבירא לן דצריך אגד (מעיקרא) גרוע ועומד הוא כלומר דמתחלתו לא עשה כהוגן שאגד שם תוספת מצוה ואנן בעינן גורע דהשתא שהיה כשר מתחלתו ופוסלו בתוספתו והאיכא ציצית דעיקרו מדברי תורה ופירושו מד\\\"ס ויש בו להוסיף ואם הוסיף גורע בציצית מאי סבירא לן אי ס\\\"ל דקשר העליון לאו דאורייתא האי לחודיה קאי והאי לחודיה קאי כלומר דכיון דלא נקשר אינו חיבור עם השאר והראוי למצוה היא המצוה והעודף כמי שאינו ואי סבירא לן דקשר העליון דאורייתא גרוע ועומד הוא אי הכי תפילין נמי אי עביד ד' בתי ואייתי אחרינא ואנח גבייהו האי לחודיה קאי והאי לחודיה קאי ואי עביד ה' בתי גרוע ועומד הוא הא אמר רבי זירא בית חיצון שאינו רואה את האויר פסול. והראב\\\"ד ז\\\"ל הוקשה לו שאם הדברים כפשוטן דלא מחייב רבי יהודה אלא בתפילין לבד כשהזכירו בברייתא שכתבתי בפרק שקודם זה מחלוקת ר\\\"מ ורבי יהודה ור\\\"ש הו\\\"ל להזכיר דברי רבי יהודה ברישא דכל תנא בתרא לטפויי אתא ורבי יהודה אינו מחייב אלא בתפילין לבד ור\\\"מ מחייב בכל דבר שחייבין על זדונו כרת ועל שגגתו חטאת ור\\\"ש מחייב על כל הדברים אף על דקדוק אחד מדקדוקי סופרים ומכח קושיא זו רוצה לפרש דר' יהודה לאו אתפילין בלחוד מחייב אלא אף אלולב וציצית ואפשר לדעת הראב\\\"ד ז\\\"ל שהוא הדין לכל מצות שעיקרן מדברי תורה ופירושן מדברי סופרים אלא שתפס לולב וציצית משום דבהנהו משמע דקאמר גמרא דלא מחייב והראב\\\"ד ז\\\"ל נראה שמפרש דר\\\"א אמר רבי אושעיא אילו תניח בדעתך שיצטרף תנאי אחר והוא שצריך שיהיה בו להוסיף ואם הוסיף גורע לא תמצא שיהיה מתחייב אלא בתפילין שאין מי שסובר כן אלא ר' יהודה ולא בעל המאמר ואהא הוא דשקיל וטרי גמרא אם כשנניח התנאי הזה אם יכנסו לולב וציצית בכלל או לא אבל ע\\\"פ האמת אע\\\"פ שאין בו להוסיף אם הוא דבר שעיקרו מד\\\"ת ופירושו מדברי סופרים חייב אליבא דרבי יהודה ושיעור לשון הראב\\\"ד כך הוא והוא הדין שחייב אם הוסיף בלולב וציצית אם התוספת פוסל את העיקר דהיינו למ\\\"ד לולב צריך אגד אי למ\\\"ד קשר העליון דאורייתא שאם הוסיף ולא פסל כלומר למאן דאמר לולב אין צריך אגד וקשר העליון לאו דאורייתא אע\\\"פ שהעביר אותם בבל תוסיף כיון שלא נתקיים העשה אינו חייב ומ\\\"ש בלולב וציצית נמי משכחת לה וכו' מקשה נגד הגמרא אמאי לא משכח בלולב יש בו להוסיף ואם הוסיף גורע ועד השתא לאו גרוע ועומד היה הא משכחת לה למאן דאמר לולב צריך אגד ולמאן דאמר קשר העליון דאורייתא כגון שאגד ארבעה מינין והוסיף החמישי וקשר שמונה חוטין והוסיף התשיעי ותירץ דזה אינו כלום וכו' ודבריו אינם מובנים לי דהא תעשה ולא מן העשוי ליתיה אלא בציצית ולא בלולב ובציצית (ו) מתוך דבריו נלמד דהיינו טעמא משום דלהוסיף חוט תשיעי צריך להתירו ולחזור ולקשור ואם כן פנים חדשות באו לכאן דמעת שנקשרו פעם שנית עם החוט התשיעי גרוע ועומד הוא אבל טעם הלולב אמאי לא שייך בזה יש בו להוסיף וכו' לא יכולתי ללמוד מתוך דבריו אבל התוס' תירצו דכיון דקודם נפסל הו\\\"ל גרוע ועומד אבל תפילין אם הניחן בראשו בכשרות והניח גבייהו בית חמישי ה\\\"ז מוסיף גורע שפוסלן ומבטל מצוה שעל ראשו ולא דמי ללולב דאם נטלו ובעודו בידו הוסיף מין חמישי אין זה מבטל מצותו דמדאגבהיה נפיק ביה עכ\\\"ל. ומ\\\"ש וי\\\"א דוקא בתפילין וכו' ואומר אני דמודה ר' יהודה וכו' אמר כן כי היכי דלא תיקשי לשיטה זו הקושיא שהקשיתי לעיל דר' יהודה לא אתא אלא לגרועי וארישא הוה ליה לברייתא להזכיר דברי רבי יהודה וכמה שכתבתי לבאר שהוא מוסיף על דברי רבי מאיר שהוא סובר שחייב על תפילין מוסף על חייבי כריתות דקאמר ר' מאיר וק\\\"ל למה הראב\\\"ד פתח דבריו זה שבוש דלדעת רבי מאיר וכו' דילמא רבינו סובר כי\\\"א וכסברת הראב\\\"ד [גופיה] שכתב ואומר אני דמודה רבי יהודה וכו' ופסק כר' יהודה דדוקא בחייבי כריתות ותפילין הוא דחייב ואפשר לומר שלפי שיטת י\\\"א תפילין דמחייב בהו מקרא ילפינן להו ורבינו כתב שהוא הלכה מפי הקבלה וא\\\"כ ודאי לא סבירא ליה כאותה שיטה. כך נ\\\"ל פירוש דברי הראב\\\"ד ורבינו תופס השמועה כפשטה ומפרש דהא דאמר ר\\\"א היא פירוש דברי ר' יהודה וא\\\"כ לרבי יהודה אין חיוב אלא בתפילין וכמו שהוכחתי בפ' הקודם לזה.\",1,0],[8,389,4,3,\"ומ\\\"ש רבינו זה אומר טהור וזה אומר שני לטומאה הרי זה פטור מהמיתה הוא ממה שנתבאר בדברי ר. בינו פ' שלישי מהל' ביאת המקדש ששני לטומאה שנכנס למקדש אין חייבין עליו כרת:\",2,0],[8,389,5,1,\"המקלל אביו ואמו נסקל וכו'. משנה בסנהדרין פ' ד' מיתות (סנהדרין דף נ״ג ס״ו) ובגמ' ומקלל אביו ואמו וכו' מות יומת בסקילה אתה אומר בסקילה או אינו אלא אחת מכל מיתות האמורות [בתורה] נאמר כאן אביו ואמו קלל דמיו בו ונאמר באוב וידעוני דמיהם בם מה להלן בסקילה דבהדיא כתיב באבן ירגמו אותם אף כאן בסקילה:\",1,0],[8,389,5,1,\"ואחד המקלל בחייהן או לאחר מיתתן. משנה בפ' הנחנקין (סנהדרין דף פ״ה:):\",2,0],[8,389,5,1,\"וצריך עדים וכו'. ונראה לי שהוצרך לכתוב כן במקלל ובמכה אביו משום דסלקא דעתך אמינא דהכאת אביו ואמו וקללתן על הרוב היא בתוך הבית ואין נמצאים שם עדים כשרים וא\\\"כ לא ניבעי עדים והתראה קמשמע לן:\",3,0],[8,389,5,1,\"ואחד האיש ואחד האשה וכן הטומטום וכו'. בפרק ארבע מיתות (סנהדרין דף ס״ו) ת״ר איש (אשר יקלל את אביו וכו') מה תלמוד לומר איש איש לרבות בת טומטום ואנדרוגינוס.\",4,0],[8,389,5,1,\"ומ\\\"ש והוא שיהו גדולים וכו'. פשוט בעצמו:\",5,0],[8,389,5,2,\"אינו חייב סקילה וכו'. משנה שם ובסוף שבועת העדות (שבועות דף ל״ו) המקלל אביו ואמו אינו חייב עד שיקללם בשם (קללם) ובמשנה (דף ל״ה) המקלל אביו ואמו בכולן כלומר בכנויין חייב דברי ר״מ וחכמים פוטרים ופסק כחכמים.\",1,0],[8,389,5,2,\"ומ\\\"ש ולוקה כדרך שלוקה וכו'. הוא סומך על מה שפסק בפכ\\\"ו מהל' סנהדרין שהמקלל את חבירו אפילו בכנוי לוקה וכבר כתבתי שם מנא לן הא ומ\\\"מ צ\\\"ע בדברי רבינו שפסק כאן כחכמים ובגמ' (דף ל\\\"ו) אמרו דטעמייהו משום דכתיב בנקבו שם יומת מה תלמוד לומר שם לימד על מקלל אביו ואמו שאינו חייב עד שיקללם בשם ופירש\\\"י (אם אינו ענין לו דהא כתיב ונוקב שם) תנהו ענין למקלל אביו ואמו ובפ' ד' מיתות לעיל מהא מתניתין אמברך את השם אמרינן תנא עד שיברך שם בשם מנה\\\"מ אמר שמואל דאמר קרא ונוקב שם בנקבו שם יומת והא ודאי חכמים לית להו הא דשמואל דאי איתא דאית להו הא תו לא מצו ילפי האי קרא דמקלל אביו ואמו צריך שיקלל בשם דהא לגופיה איצטריך וכ\\\"כ רש\\\"י דחכמים לא ס\\\"ל הא דדרשינן לעיל מהאי קרא עד שיברך שם בשם דאפילו לא ברך שם בשם מחייבי רבנן ומאחר שפסק כאן כחכמים היאך פסק בפ\\\"ב מהל' ע\\\"ז כדשמואל דבעינן שיברך שם בשם ובפ\\\"ב דהל' ע\\\"ז יישבתיו:\",2,0],[8,389,5,3,\"וכן המקלל וכו'. נראה שלמד כן ממאי דאיתא במכות פרק אלו הן הגולין (מכות דף י״ב) תני חדא אב שהרג בנו נעשה לו גואל הדם ותניא אידך אין בנו נעשה לו גואל הדם ל״ק הא בבנו הא בבן בנו פירש״י הא דתניא אין בנו נעשה לו גואל הדם בבנו של רוצח קאמר והא דתני בנו נעשה לו גואל הדם בבנו של הרוג קאמר שהוא בן בנו של רוצח ואינו מוזהר על כבודו:\",1,0],[8,389,5,4,\"אזהרה של מקלל אביו וכו' עד הרי אביו בכלל ישראל. בפ' ד' מיתות (סנהדרין דף ס״ו) אסיקנא דאתיא מדכתב רחמנא אלהים לא תקלל ונשיא בעמך לא תאור וכתב נמי לא תקלל חרש דליכתוב קרא או אלהים וחרש או נשיא וחרש אלהים למה לי אם אינו ענין לגופו תנהו ענין לאביו וא״כ היאך כתב רבינו דמלא תקלל חרש לחוד אתיא. ונ״ל דרבינו סומך אמאי דאמרינן תו התם הניחא למ״ד אלהים חול אלא למ״ד אלהים קדש כלומר וכאן הזהיר על ברכת השם מאי איכא למימר הא אין כאן קרא יתירא ופריך דליכא למימר דגמר חול מקדש דדילמא קרא אקדש אזהר אחול לא אזהר ומשני א״כ ליכתוב קרא לא תקל מאי לא תקלל ש״מ תרתי ורבינו סובר כמ״ד אלהים קדש דהא ר״ע הוא דאמר הכי התם ור' ישמעאל פליג עליה והלכה כר״ע מחבירו ומשמע ליה שכשאמרו א״כ ליכתוב קרא לא תקל חוזר ממ״ש למעלה ומייתי ליה מלא תקלל חרש וכ״ת מה לחרש שכן חרישותו גרמה לו כלומר לפי שהוא שפל הזהיר עליו הכתוב שלא תבזהו א״כ ליכתוב רחמנא לא תקל מאי לא תקלל ש״מ תרתי חדא אזהרה לחרש וחדא אזהרה לאב וכנ״ל לדעת רבינו או שנאמר דס״ל לרבינו דכיון דאמרינן בשבועת העדות (דף ל״ו) דמקלל חבירו מנ״ל דחייב ומהדרינן דכתיב לא תקלל חרש ולא מפליג התם בין חרש לשאר כל אדם והטעם שנאמר חרש כבר נתבאר בדברי רבינו פכ״ו מהל' סנהדרין והא סוגיא דפ' ד' מיתות פליגא עלה דההיא דמפליג בין חרש לשאר כל אדם וכההיא דשבועת העדות קי״ל כיון דאיכא טעמא למה נאמר חרש:\",1,0],[8,389,5,5,\"המכה אביו וכו'. משנה ריש הנחנקין בסנהדרין (דף פ\\\"ד:) אלו הן הנחנקין המכה אביו ואמו:\",1,0],[8,389,5,5,\"ואחד האיש וכו' וכן טומטום וכו'. נ\\\"ל שלמדה מדאמרינן הכי במקלל כמו שכתבתי למעלה ורבינו סובר דמקשינן הכאה לקללה כמו שאבאר בפרק זה בס\\\"ד:\",2,0],[8,389,5,5,\"אינו חייב חנק וכו'. משנה בפרק הנחנקין (סנהדרין דף פ״ה:):\",3,0],[8,389,5,6,\"מי שהכה את אביו על אזנו וכו'. בב״ק פרק החובל (בבא קמא דף פ״ו:) אמר רבא החורש את אביו נהרג לפי שאי אפשר בלא חבורה טיפתא דדמא נפלה באודניה:\",1,0],[8,389,5,7,\"המקיז דם לאביו או שהיה רופא וחתך וכו'. בריש הנחנקין (סנהדרין דף פ״ד:) בעיא דאיפשיטא ואכתבנה בסמוך:\",1,0],[8,389,5,7,\"אף על פי שהוא פטור לכתחלה לא יעשה וכו'. שם רב לא שביק לבריה למשקל ליה סילוא כלומר אם נתחב לו קוץ בבשרו לא היה מניח בנו להוציאו מר בריה דרבינא לא שביק לבריה למפתח ליה כוותא כלומר כויה להוציא ליחה ממנה דילמא חביל והוה ליה שגגת חנק.\",2,0],[8,389,5,7,\"ומה שכתב אבל אם אין שם מי שיעשה אלא הוא וכו'. נראה לי שלמד כן מדאיבעיא לן בן מהו שיקיז לאביו ופשטיה מואהבת לרעך כמוך כלומר ולא הוזהרו ישראל לעשות לחבריהם אלא דבר שאינו חפץ לעשות לעצמו ורב דימי פשט ממכה אדם ומכה בהמה מה מכה בהמה לרפואה פטור אף מכה אדם לרפואה פטור ומדיליף לה ממכה בהמה ודאי פטור ומותר קאמר אלא דרב פפא ורבינא כיון שהיו מוצאים מי שירפאם לא הוו שבקי לבנייהו משום דדילמא הוו חבלי בהו טפי ממה שהוא כדרך הרפואה וכ\\\"כ נמוק\\\"י בשם הרמב\\\"ן:\",3,0],[8,389,5,8,\"אזהרה של מכה וכו'. משמע לי שלמדה ממאי דאתמר באזהרת מכה אביו וכמו שכתבתי בסמוך. ובסנהדרין פרק הנחנקין (סנהדרין דף פ״ה) בעו מרב ששת בן מהו שיעשה שליח ב״ד לאביו להכותו ולקללו כלומר אם נתחייב אביו מלקות או נידוי ופשט דשרי ואותבוה מדתניא ומה מי שמצווה להכותו מצוה שלא להכותו מי שאינו מצוה להכותו אינו דין שמצוה שלא להכותו מאי לאו אידי ואידי במקום מצוה הא בבנו הא באחר לא אידי ואידי לא שנא בנו לא שנא אחר ולא קשיא כאן במקום מצוה כאן שלא במקום מצוה והכי קתני ומה במקום מצוה שמצוה להכותו מצוה שלא להכותו שלא במקום מצוה שאינו מצוה להכותו אינו דין שמצוה שלא להכותו ופירש״י ומה מי שמצוה להכותו ברייתא תניא הכי במכילתא מאי לאו אידי ואידי מצוה ואינו מצוה תרווייהו במקום מצוה והא בבנו והא באחר וה״ק ויליף אזהרה למכה אביו ומה אחר שמצוה להכותו במקום מצוה דכתיב יכנו מצוה שלא להכותו יותר מארבעים דכתיב לא יוסיף פן יוסיף בנו שאינו מצוה להכותו אפילו במקום מצוה אלמא אינו נעשה שליח לכך אינו דין שמוזהר שלא להכותו שלא במקום מצוה ומה במקום מצוה שמצוה להכותו מצוה שלא להכותו יותר מארבעים שלא במקום מצוה לא כל שכן ויליף אזהרה למכה אביו או חבירו מהכא:\",1,0],[8,389,5,9,\"שתוקי חייב על אמו וכו': אבל בנו מן השפחה וכו'. משנה ביבמות פרק כיצד (דף כ\\\"ב) מי שיש לו בן מכל מקום פוטר את אשת אביו מן הייבום וחייב על מכתו ועל קללתו ובנו הוא לכל דבר חוץ ממי שיש לו בן מן השפחה ומן הנכרית:\",1,0],[8,389,5,9,\"ומה שכתב רבינו שאינו חייב על אמו הוא לפי שאם עדיין לא נשתחררה אין דינה כישראלית ואם נשתחררה והוא לא נשתחרר היא הויא לה כקטן שנולד והוא לא חשיב בנה ובין נשתחררה או לא נשתחררה אם הוא נשתחרר הוה ליה כקטן שנולד ופטור עליה כמו הגר שכתב רבינו בסמוך אי נמי דיליף לה ממ\\\"ש רבינו בסמוך מי שאינו חייב על אביו אינו חייב על אמו:\",2,0],[8,389,5,9,\"וכן גר שהורתו שלא בקדושה וכו'. זה פשוט דכיון שהיתה הורתו שלא בקדושה וכו' דינו כגר גמור שאינו יורש אביו כדאשכחן ברב מרי כדאיתא בפרק מי שמת (בבא בתרא דף קמ״ט:):\",3,0],[8,389,5,10,\"כשם שאינו חייב וכו'. כלומר מי שאביו ידוע ואפילו הכי אינו חייב עליו אינו חייב על אמו לאפוקי שתוקי דטעמא דלא מחייב אאבוה הוא משום דלא ידעינן מנו:\",1,0],[8,389,5,11,\"הגר אסור לקלל וכו'. קצת ראיה מצאתי לזה מדאמרינן ביבמות פרק כיצד (דף כ\\\"ב) ואיתיה בדברי רבינו פרק י\\\"ד מהל' איסורי ביאה שלא אסרו ערוה לגר אלא כדי שלא יאמרו באנו מקדושה חמורה לקדושה קלה:\",1,0],[8,389,5,11,\"אבל העבד וכו':\",2,0],[8,389,5,12,\"מי שהיו וכו'. ברייתא סנהדרין פרק הנחנקין (סנהדרין דף פ״ה) היוצא ליהרג ובא בנו והכהו וקללו חייב בא אחר והכהו וקללו פטור והקשו שם מ״ש בנו ומ״ש אחר ותירצו אחר היינו טעמא דפטור דאמר קרא ונשיא בעמך לא תאור בעושה מעשה עמך כלומר וזה שעבר עבירה שחייב עליה מיתה לאו עושה מעשה עמך התינח קללה הכאה מנ״ל דמקשינן הכאה לקללה א״ה בנו נמי וכו' הב״ע כשעשה תשובה א״ה אחר נמי אמר רב מרי בעמך במקויים שבעמך כלומר בראוי להתקיים ולא זה שנגמר דינו א״ה בנו נמי מידי דהוה לאחר מיתה ופירש״י דילפינן לקמן מקלל לאחר מיתה חייב וא״ת והא תנן המכה לאחר מיתה פטור והכא מחייב ליה אהכאה דקתני הכהו וקללו היינו טעמא דפטור מכה לאחר מיתה משום דבעינן חבורה ולאחר מיתה ליכא חבורה וכו' ויוצא ליהרג איכא חבורה דחי הוא אלא דסופו למות עכ״ל. מדאוקימנא להא דיוצא ליהרג ובא בנו והכהו וקללו חייב ואחר פטור כשעשה תשובה שמעינן בהדיא דכל שלא עשה תשובה אפילו בנו פטור ואם עשה תשובה דוקא בנו חייב אבל אחר אפילו עשה תשובה פטור וגם בפרק כיצד (דף כ״ב:) על אותה משנה שכתבתי בפרק זה מי שיש לו בן מ״מ וכו' וחייב על מכתו ועל קללתו אמרו בגמרא מ״מ לאיתויי מאי אמר רב יהודה לאיתויי ממזר ואמאי קרי כאן ונשיא בעמך לא תאור בעושה מעשה עמך הב״ע כשעשה תשובה.\",1,0],[8,389,5,12,\"ומ\\\"ש רבינו שאע\\\"פ שלא עשו תשובה אסור להכותן ולקללן. נלמד מהדין שכתב בסמוך עבר אביו ואמו על עבירה שלוקין עליה וכו' לא יכה אותם:\",2,0],[8,389,5,12,\"ואם ביישו חייב בקנס המבייש. כלומר מי שהוא המבייש בין שהוא בנו או אחר שאם יש לו בנים אחרים חייב זה לתת להם הקנס וכן איתא בהנחנקין דקודם דאוקימנא ברייתא (דף פ\\\"ה) שכתבתי בסמוך היוצא ליהרג ובא בנו והכהו וקללו וכו' כשעשה תשובה אמר התם רב ששת דהיינו טעמא דאחר פטור משום דגברא קטילא הוא ופריך עליה והאמר רב ששת ביישו ישן ומת כלומר תוך שינתו חייב ופירש\\\"י טעמא דהא מתביישים בניו והאי נמי ל\\\"ש ומדפריך מהא דרב ששת אהא ממילא משמע דאם ביישו להאי חייב:\",3,0],[8,389,5,14,\"עבר אביו ואמו וכו' עד ולא תכסה עליו. שם בעו מיניה מרב ששת בן מהו שיעשה שליח בית דין לאביו להכותו ולקללו ופירש\\\"י אם נתחייב אביו נידוי או מלקות ואמרינן בתר הכי מאי הוי עלה אמר רבה בר רב הונא וכן תנא דבי ר' ישמעאל לכל אין הבן נעשה שליח לאביו להכותו ולקללו חוץ ממסית שהרי אמרה תורה לא תחמול ולא תכסה עליו:\",1,0],[8,389,5,15,\"מי שנתחייב שבועה לבנו וכו'. כתב סמ\\\"ג שכך הורו הגאונים ופירש הוא ששבועת האלה היינו כמו שרגילים להחרים בנדוי ושמתא וכיוצא בזה:\",1,0],[8,389,5,15,\"וכבר בארנו וכו'. בפרק ראשון מהלכות רוצח:\",2,0],[8,389,5,15,\"ולא על ההכאה בלבד וכו':\",3,0],[8,389,6,1,\"כבוד אב ואם מצות וכו' עד הנה השוה אותם בעונש. ברייתא בפ\\\"ק דקידושין (דף ל':) קרובה ללשון רבינו:\",1,0],[8,389,6,2,\"הקדים אב לאם לכבוד וכו'. שם תניא רבי אומר גלוי וידוע לפני מי שאמר והיה העולם שבן מכבד את אמו יותר מאביו מפני שמשדלתו בדברים לפיכך הקדים הקב\\\"ה כבוד אב לכבוד אם וגלוי וידוע לפני מי שאמר והיה העולם שהבן מתיירא מאביו יותר מאמו מפני שמלמדו תורה לפיכך הקדים הכתוב מורא האם למורא האב ומשמע מהכא ששניהם שוים בין לכבוד בין למורא:\",1,0],[8,389,6,3,\"אי זהו מורא וכו'. שם (דף ל\\\"א:) ת\\\"ר אי זהו מורא ואי זהו כבוד מורא לא עומד במקומו ולא יושב במקומו ולא סותר את דבריו ולא מכריעו ופירש\\\"י לא עומד במקומו במקום המיוחד לאביו לעמוד שם בסוד זקנים עם חביריו בעצה ולא מכריעו אם היה אביו וחכם אחר חלוקים בדבר הלכה לא יאמר נראים דברי פלוני. ורבינו ירוחם כתב בשם הרמ\\\"ה דלא ישב אפילו במקום המיוחד לו לישב בביתו וגם על מה שפירש\\\"י ולא מכריעו הקשה הרמ\\\"ה אם כן היינו סותר דבריו אלא אפילו נראין לו דברי אביו אינו יכול לומר נראין לי דברי אבי שנראה כמכריע את דבריו אלא אם יש לו תשובה להשיב על דברי החולקים משיב עכ\\\"ל. ואפשר שרש\\\"י כשכתב לא יאמר נראין דברי פלוני על אי זה מהם שיאמר נתכוון שאפילו כשיאמר שנראין דברי אביו נראה כמכריע את דבריו:\",1,0],[8,389,6,3,\"ולא יקרא בשמו וכו'. ברייתא שם משנה שם אביו כלומר שיאמר כך אמר אבא מארי ולא יזכיר את שם אביו ומדקאמר משנה שם אביו סתם משמע ליה לרבינו דל\\\"ש בחייו ל\\\"ש לאחר מותו צריך לשנות:\",2,0],[8,389,6,3,\"היה שם אביו וכו'. צ\\\"ע מהיכן מוצאו וכל הלשון עד אין בכך כלום נסתפקתי בו והעירותי עליו בפ\\\"ה מהלכות ת\\\"ת:\",3,0],[8,389,6,3,\"איזהו כבוד מאכיל וכו'. ברייתא שם כבוד מאכיל ומשקה מלביש ומכסה ומכניס ומוציא איבעיא להו משל מי כלומר מאכיל ומשקה משלו או משל אביו רב יהודה אמר משל בן רב נתן בר אושעיא אמר משל אב אורו ליה רבנן לרב ירמיה וכו' כמ\\\"ד משל אב ופסק רבינו כאותה הוראה חדא דרבים נינהו ועוד דהלכה למעשה היא וכן פסקו הרי\\\"ף והתוספות:\",4,0],[8,389,6,3,\"ואם אין ממון לאב וכו'. כך פסק הרי\\\"ף שם וז\\\"ל והיכא דרויח הבן והאב לית ליה כייפינן לבן ושקלינן מיניה בתורת צדקה ויהבינן לאבוה כי הא דרבה כפה לרב נתן בר אמי ואפיק מיניה ת' זוזי לצדקה וכן שדרו ממתיבתא. וכתב סמ\\\"ג דאיתא בירושלמי דפאה דבכבוד אב ואם אין כתוב כבד מהונך שאפילו אין לך כלום אתה צריך לטחון ברחיים בשבילם וכתב הוא ז\\\"ל דהיינו כשאין לאביו והתוספות כתבו דאיתא בירושלמי אמר ר' יוסי הלואי דהוויין כל שמעתתי ברירן לי כי האי שכופין את הבן לזון את אביו ועוד הביא ראיה ממקום אחר מהירושלמי דמשמע בהדיא דכופין.\",5,0],[8,389,6,3,\"ומ\\\"ש ומכניס ומוציא. כבר נתבאר בלשון הברייתא שכתבתי בבבא שקודם זו:\",6,0],[8,389,6,3,\"ועומד מפניו וכו'. בפ\\\"ק דקידושין שם רב יוסף כד שמע קל כרעא דאימיה אמר איקום מקמי שכינה דאתיא וגם מדאיבעיא לן בבנו והוא רבו כדבסמוך משמע דבאינו רבו פשיטא דחייב לעמוד מפניו:\",7,0],[8,389,6,4,\"והאב שהיה תלמיד וכו'. שם (דף ל\\\"ג ע\\\"ב) איבעיא להו בבנו והוא רבו מהו לעמוד מפני אביו ובעי למפשטה מדא\\\"ל שמואל לרב יהודה קום מקמי אבוך ורב יהודה רבו של אביו היה ודחו התם דשאני יחזקאל אביו של רב יהודה דבעל מעשים הוה דאפילו מר שמואל נמי קאים מקמיה ובתר הכי איבעיא לן בנו והוא רבו מהו שיעמוד אביו מפניו והא נמי לא איפשיטא ורבינו פסק בחדא לקולא ובחדא לחומרא וצריך טעם. ומצאתי שכתב הרב רבינו נסים וכתב רבינו חננאל שאע\\\"פ שהוא רבו חייב לעמוד מפני אביו אבל אביו אינו חייב לעמוד לפניו ואף הרב רבינו משה בר מיימון ז\\\"ל כתב כן בפ\\\"ו מהלכות ממרים וצריך עיון למה ונראה לי דאע\\\"ג דלא מיפשיט בגמרא דילן ילפי לה מדגרסינן בירושלמי (פ\\\"ק דקדושין) אמו של רבי טרפון ירדה לטייל לתוך חצירה בשבת ונפסק קורדיקין שלה והלך רבי טרפון והניח שתי ידיו תחת פרסותיה והיתה מהלכת עליהם עד שהגיעה למטתה פעם אחת חלה ר' טרפון ונכנסו חכמים לבקרו ואמרה להם התפללו על טרפון בני שהוא נוהג בי כבוד יותר מדאי אמרון לה מאי עביד לה יותר מדאי ותנית להון עובדא אמרון אפילו הוא עושה כן אלף אלפים עדיין לא הגיע לכבוד שאמרה תורה ע\\\"כ בירושלמי. ובודאי דקימה דרבו אינה אלא מדין חכם ואם איתא שאין הבן חייב לעמוד מפני אביו כשהבן רבו לא היתה רשאה אמו של רבי טרפון לקבל הימנו כך הילכך אע\\\"ג דבגמרא דילן מספקא לן שבקינן ספקינן ונקטינן פשטייהו ולא משמע משום דבעלת מעשים הוות מדאמרינן סתמא עדיין לא הגיע לכבוד שאמרה תורה עכ\\\"ל. ותמהני דהא בגמרא דידן נמי מייתי דומיא דההוא עובדא דירושלמי דר' טרפון כל אימת דהות בעיא אימא למיסלק לפוריא גחין וסלקא עליה ואפילו הכי איבעיא להו אלמא דגמרא דידן סבר דההוא עובדא לא מכרעא ואפשר שטעמו לומר דכיון דבירושלמי לא איבעיא להו משמע דמיפשט פשיטא להו מההוא עובדא ואע\\\"ג דגמרא דידן לא משמע ליה למיפשט מההוא עובדא לא שבק פשיטותא דידיה משום ספיקא דגמרא דידן:\",1,0],[8,389,6,4,\"וחייב לכבדו בשאר דרכיו וכו' עד זכרונו לחיי העולם הבא. ברייתא בפ\\\"ק דקידושין (דף ל\\\"א:) כלשון רבינו ופירש\\\"י הנשמע בדבר אביו למקום אם מכיר באנשי המקום שמכבדים אביו לחלוק לו כבוד לקבל דברים שיאמר בשמו אל יתלה הכבוד בעצמו ואפילו יודע שכבדוהו כאביו יתלה הכבוד באביו שלחוני בשביל אבא שהוא צריך לי אבל אם אינו נשמע למקום בדבר אביו אל יתלה באביו שאינו לו אלא גנאי:\",2,0],[8,389,6,5,\"הריני כפרת משכבו. עלי יבא כל רע הראוי לבא על נפשו מכאן ואילך כבר קבל מה שקבל שאין משפט רשעי ישראל בגיהנם אלא שנים עשר חדש:\",1,0],[8,389,6,6,\"אחד האיש וכו'. ברייתא שם (דף ל':) איש אמו ואביו תיראו אין לי אלא איש אשה מנין כשהוא אומר תיראו הרי כאן שנים אם כן מה ת\\\"ל איש איש ספק בידו לעשות אשה אין ספק בידה לעשות מפני שרשות אחרים עליה אמר רב אידי בר אבין אמר רב נתגרשה שניהן שוין ופירש\\\"י ספק יכולת שאין מוחה בידו רשות אחרים בעלה. נתגרשה מבעלה הרי היא כאחיה במצות כיבוד:\",1,0],[8,389,6,7,\"עד היכן הוא כיבוד אב ואם וכו'. שם (דף ל\\\"ב) אהא דאיבעיא לן מאכיל את אביו משל מי אמרינן ת\\\"ש שאלו את רבי אליעזר עד היכן כיבוד אב ואם אמר להם כדי שיטול ארנקי ויזרקנו לים בפניו ואינו מכלימו ואי אמרת משל אביו מאי נפקא לן מינה כלומר ואי אמרת כבוד האב על הבן בחסרון כיס אינו אלא משל אב אם כן האי ארנקי דקאמר רבי אליעזר משל אב הוא ומאי נפקא מינה להכלימו ואוקמוה בראוי ליורשו ומאחר שרבינו פסק לעיל שאינו מאכיל אלא משל אב אם כן האי ארנקי היינו כשהוא של אב דוקא וכמו שנתבאר ואם כן היאך כתב ואפילו נטלו כיס של זהובים שלו. ויש לומר דסבירא ליה דכי אמרינן דוקא משל אב הני מילי לכבדו אבל כדי שלא לצערו יש לו לאבד כל ממון שבעולם ועי\\\"ל דהא דאמרינן דמשל אב דוקא היינו מדינא דאינו חייב לחסר כיסו בשבילו אבל מ\\\"מ אם יחסר כיסו בשבילו בכלל מצות כיבוד הוא ולישנא דעד היכן כיבוד אב ואם הכי דייק. ואם תאמר א\\\"כ מאי מותיב מינה למאן דאמר משל אב יש לומר דאין הכי נמי דמאן דמותיב לא אסיק אדעתיה לפלוגי בהכי ומאן דתריץ הוה מצי לשנויי הכי אלא דאהדר ליה לפום שיטתיה דלא הוה מפליג בינייהו:\",1,0],[8,389,6,7,\"ועד היכן מוראן וכו'. שם (דף ל\\\"א) בעו מיניה מרב עולא עד היכן כיבוד אב ואם אמר להם בואו וראו מה עשה עכו\\\"ם אחד באשקלון וכו' כי אתא רב דימי אמר פעם אחת היה לבוש סריקון של זהב והיה יושב בין גדולי עירו ובאת אמו וקרעתו ממנו וטפחה לו על ראשו וירקה לו בפניו ולא הכלימה:\",2,0],[8,389,6,8,\"אף על פי שבכך וכו'. דברי רבינו ראויים אליו ונלמד מהדין שכתב בסמוך שהמכה בנו גדול מנדין אותו.\",1,0],[8,389,6,8,\"ומה שכתב שהאב שמחל וכו'. מימרא דרב חסדא פרק קמא דקידושין (דף ל\\\"ב):\",2,0],[8,389,6,9,\"והמכה בנו גדול וכו'. פרק ואלו מגלחין (מועד קטן דף י״ז):\",1,0],[8,389,6,10,\"מי שנטרפה דעתו של אביו וכו'. בפ\\\"ק דקידושין (דף ל\\\"א:) אמרי' רב אסי הוה ליה ההיא אימא זקנה אמרה ליה בעינא תכשיטין עבד לה בעינא גברא נעיין לך בעינא גברא דשפיר כוותך שבקה ואזל לארעא דישראל.\",1,0],[8,389,6,10,\"ומ\\\"ש ויצוה אחרים להנהיגם כראוי. עצה טובה קמשמע לן ואין ספק שכן עשה רב אסי. וכתב הראב\\\"ד ז\\\"ל אין זו הוראה נכונה וכו'. ואילו היה רבינו מוציא דין זה מדעתו היה השגתו השגה אבל אחר שהוא מוציא אותו מעובדא דרב אסי שכתבתי אין מקום להשגתו והר\\\"ן כתב על השגה זו ולא ידעתי למה דהא דרב אסי הכי מוכח אולי הוא ז\\\"ל סובר דדוקא למיסק לא\\\"י ואינו מחוור עכ\\\"ל:\",2,0],[8,389,6,11,\"הממזר חייב בכבוד אביו וכו'. טעמו מדתנן בפ\\\"ב דיבמות (דף כ\\\"ב) מי שיש לו בן מ\\\"מ פוטר את אשת אביו מהיבום וחייב על מכתו ועל קללתו חוץ ממי שיש לו בן מהשפחה ומהנכרית ובגמרא מ\\\"מ לאיתויי מאי וכו' לאיתויי ממזר וכו' אמאי (חייב על מכתו ועל קללתו) קרי כאן ונשיא בעמך לא תאור בעושה מעשה עמך ואוקימנא בשעשה תשובה וכתב הרי\\\"ף על זה ה\\\"מ לענין חיובא אבל לענין איסורא אפילו לא עשה תשובה אסור לבן להכותו ולקללו דגרסינן בפרק הנחנקין לכל אין הבן נעשה שליח לא להכות אביו ולא לקללו חוץ ממסית ומדיח שהרי אמרה תורה לא תחמול ולא תכסה עליו וכ\\\"כ הרא\\\"ש ולאפוקי מהתוס' שכתבו דההיא דהנחנקין בשעשה תשובה היא:\",1,0],[8,389,6,11,\"ודע שעל מ\\\"ש רבינו שהממזר חייב בכבוד אביו כתב הטור רסי' ר\\\"מ וז\\\"ל נ\\\"ל כיון שהוא רשע אינו חייב בכבודו כדאמרינן גבי הניח להם פרה גזולה חייבים להחזיר מפני כבוד אביהם ופריך והא לאו עושה מעשה עמך הוא פירוש ואין חייבין בכבודו ומשני בשעשה תשובה אלמא כל זמן שלא עשה תשובה אינם חייבים בכבודו עכ\\\"ל. גם הגהות מיימון כתבו כן בשם ספר המצות אלא שהטור הוסיף תיבת גזולה ואינו כן דבנטלה ברבית מיירי כמבואר בריש פרק איזהו נשך ואין משם ראיה לסתור דברי רבינו דמדינא אינם חייבים להחזיר דאמר קרא אל תקח מאתו נשך ותרבית לדידיה אזהר רחמנא לבריה לא אזהר אלא דמשום כבוד אביהם חייבים להחזיר ודוקא בדעבד תשובה ולא הספיק להחזיר עד שמת דהוה לה ההיא פרה כאילו לא הורישה לבניו מאחר שהיה בדעתו להחזירה והוא דבר המסויים הילכך אע\\\"פ שעדיין לא הוציאה מרשותו חייבים להחזיר מפני כבוד אביהם אבל כי לא עבד תשובה בניו ירשוה והתורה לא חייבתם להחזיר דלדידיה אזהר לבריה לא אזהר הילכך הוי לגמרי ממונא דידהו ואינם חייבין לכבד את האב בממונם דהא איפסיקא הלכתא כמאן דאמר משל אב אבל בשאר כבוד דלית ביה חסרון כיס אין הכי נמי דמחייבי אע\\\"פ שהוא רשע כדמשמע מההיא דפרק הנחנקין:\",2,0],[8,389,6,11,\"ראהו עובר על דברי תורה וכו'. ברייתא פ\\\"ק דקידושין (דף ל\\\"ב) ובסנהדרין פרק הנשרפין:\",3,0],[8,389,6,12,\"מי שאמר לו אביו וכו'. ברייתא בריש יבמות (דף ו') ובסוף אלו מציאות (בבא מציעא דף ל״ב) יכול אמר לו אביו היטמא או אל תחזיר אבידה ישמע לו תלמוד לומר איש אמו ואביו תיראו ואת שבתותי תשמורו אני ה' כלכם חייבים בכבודי.\",1,0],[8,389,6,12,\"ומ\\\"ש רבינו אפילו של דבריהם. נראה שהטעם משום דכיון דקי\\\"ל דכל מילי דרבנן אסמכינהו אלאו דלא תסור הרי הוא ככל דברי תורה:\",2,0],[8,389,6,13,\"אמר לו אביו השקני מים וכו'. ברייתא פ\\\"ק דקידושין (דף ל\\\"ב) אלעזר בן מתיא אומר אבא אומר השקני מים ומצוה לעשות מניח אני כבוד אבא ועושה אני את המצוה שאני ואבא חייבין במצות איסי בן יהודה אומר אם אפשר למצוה שתעשה ע\\\"י אחרים תעשה ע\\\"י אחרים וילך הוא בכבוד אביו אמר רב מתנה הלכה כאיסי בן יהודה ופירש\\\"י אבא אומר השקני מים ויש מצוה אחרת לפניו לעשות כגון לקבור את המת או לויה. על כרחך לומר דהיינו דוקא במצוה עוברת שאילו אין זמנה עובר אפילו א\\\"א לעשות ע\\\"י אחרים עוסק בכבוד אביו ואח\\\"כ במצוה וכ\\\"כ רבינו ירוחם בשם הרא\\\"ש. וכתב הר\\\"ן והלכה כאיסי בן יהודה מיהו ה\\\"מ כששתיהן לפניו אבל כשהתחיל במצוה אע\\\"פ שאפשר לעשותה ע\\\"י אחרים אם נזדמנה לו מצוה שא\\\"א לעשותה ע\\\"י אחרים לא יניח את הראשונה דהא קי\\\"ל דעוסק במצוה פטור מן המצוה ולא מפלגינן בין מצוה למצוה וגם לזה כיון רש\\\"י כשכתב ויש מצוה אחרת לפניו:\",1,0],[8,389,6,13,\"וגדול ת\\\"ת וכו'. מימרא דרבא במגילה (דף ט\\\"ז ע\\\"ב):\",2,0],[8,389,6,14,\"אמר לו אביו השקני מים וכו'. ברייתא בפ\\\"ק דקידושין:\",1,0],[8,389,6,15,\"חייב אדם לכבד וכו' עד סוף הפרק. בכתובות פרק הנושא (כתובות דף ק״ג) ת״ר בשעת פטירתו של רבי אמר לבני אני צריך נכנסו בניו אצלו אמר להם הזהרו בכבוד אמכם והקשו בגמרא דאורייתא היא דכתיב כבד את אביך ואת אמך אשת אב הואי אשת אב נמי דאורייתא היא דתניא כבד את אביך ואת אמך את אביך זו אשת אביך ואת אמך זה בעל אמך וי״ו יתירה כלומר דואת אמך לרבות אחיך הגדול ה״מ כלומר דחייב בכבוד אשת אביו בחיים אבל לאחר מיתתו לא כלומר ולהכי מזהר להו עילוה ומשמע ליה לרבינו דכי היכי דאינו חייב בכבוד אשת אב אלא בחיי אב ה״נ לא מיחייב בכבוד בעל אמו אלא בחיי אמו וכן משמע ליה דאשת אביו ובעל אמו כיון דמאת מרבינן להו ככתובים מפורשים דמו אבל אח גדול דלא מייתינן לה אלא מדרשה דוי״ו לא חשיב ככתוב מפורש בתורה אלא מד״ס:\",1,0],[8,389,7,1,\"בן סורר ומורה וכו' והיכן הזהיר וכו'. בסנהדרין פרק ד' מיתות (סנהדרין דף ס״ג) א״ר יוחנן אזהרה לבן סורר ומורה מנין ת״ל לא תאכלו על הדם ופירש״י לא תאכלו אכילה שתהרגו עליה. ואף על פי שהוא לאו שבכללות כתב רבינו בספר המצות במצוה קצ״ה שאחר שהעונש מפורש אין לחוש על האזהרה אם היא מן הדין או מלאו שבכללות:\",1,0],[8,389,7,1,\"ודע שבמנין המצות כתב כלשון הזה קצ\\\"ה שלא לאכול ולשתות דרך זולל וסובא שנאמר בננו זה זולל וסובא. ויש לתמוה שאין בפסוק זה אזהרה ואינו אלא סיפור דברים שאומרים אביו ואמו ובספר המצות כתב בלשון הזה קצ\\\"ה הזהירנו מהיות זולל וסובא בימי הנערות ובתנאים מתוארים בדין סורר ומורה והוא אמרו לא תאכלו על הדם וביאור זה שבן סורר ומורה מכלל חייבי מיתות ב\\\"ד ולשון התורה בו בסקילה וכבר התבאר שכל מי שחייב כרת או מיתת ב\\\"ד הוא מצות ל\\\"ת זולת הפסח והמילה א\\\"כ אחר שנדון בן זולל וסובא על התנאים הנזכרים בסקילה ידענו זה המעשה שהוא מוזהר ממנו בהכרח ונתבאר העונש אם כן צריך שנחקור על האזהרה לפי שלא ענש הכתוב אא\\\"כ הזהיר ולשון גמרת סנהדרין אזהרה לבן סורר ומורה מנין ת\\\"ל לא תאכלו על הדם עכ\\\"ל. וברמזים הלכות ממרים כתב שלא יהיה הבן סורר ומורה על קול אביו ואמו:\",2,0],[8,389,7,2,\"אינו חייב סקילה עד שיגנוב משל אביו וכו'. בסנהדרין פרק בן סורר (סנהדרין דף ע״א) תנן גנב משל אביו ואכל ברשות אביו משל אחרים ואכל ברשות אחרים משל אחרים ואכל ברשות אביו אינו נעשה בן סורר ומורה עד שיגנוב משל אביו ויאכל ברשות אחרים ובגמרא משל אביו ואכל ברשות אביו בעית כלומר מתפחד מאביו שלא יבין הילכך לא מימשיך משל אחרים ואכל ברשות אחרים אע״ג דלא בעית לא שכיח ליה וכ״ש משל אחרים ואכל ברשות אביו דלא שכיח ליה ובעית עד שיגנוב משל אביו ויאכל ברשות אחרים דשכיח ליה לגנוב משל אביו ולא בעית מאביו שאינו רואהו וכה״ג מימשיך.\",1,0],[8,389,7,2,\"ומ\\\"ש ויקנה בשר ויין. משנה שם (דף ע').\",2,0],[8,389,7,2,\"ומ\\\"ש בזול שם מימרא דרב הונא וטעמא דאם אינם בזול לא מימשיך:\",3,0],[8,389,7,2,\"בחבורה שכולן רקנין ופחותים. שם (דף ע' ע\\\"ב) א\\\"ר אבהו אינו חייב עד שיאכל בחבורה שכולן סריקין פירוש ריקים תרגומה סריקין:\",4,0],[8,389,7,2,\"ויאכל הבשר חי ואינו חי וכו'. שם אמר רב חנין בר מולדא אמר רב הונא אינו חייב עד שיאכל בשר חי וישתה יין חי ופירשו התם יין חי מזיג ולא מזיג בשר חי בשיל ולא בשיל ופירש\\\"י יין חי דקאמר רב הונא מזיג ולא מזיג לאפוקי היכא דנתן בו מים הרבה ואע\\\"פ שרוב בני אדם שותים כן (דבתר יין מזיג לא מימשיך) בשיל ולא בשיל דזו היא מדת גנב למהר אבל בשיל שפיר לא מימשיך למעבד כה\\\"ג לפי שמתוך שהוא גנב ועושה בסתר אין לו שהות:\",5,0],[8,389,7,2,\"והוא שיאכל משקל חמשים דינרים וכו'. משנה שם מאימתי הוא חייב משיאכל תרטימר בשר וישתה חצי לוג יין האיטלקי, ואמרו בגמרא שתרטימר בשר הוא משקל חצי מנה ופירש\\\"י יין האיטלקי טוב ומעולה הוא ומימשיך בתריה אבל בחמרא אחרינא אינו חייב בחצי לוג. אבל מדברי רבינו שלא כתב יין האיטלקי משמע דאיטלקי לאו דוקא אלא תנא יין משובח שבארצו נקט וה\\\"ה לשאר יינות, ומשמע ליה לרבינו דעד שיאכל תרטימר בשר היינו במלוגמא אחת וישתה חצי לוג יין היינו בבת אחת:\",6,0],[8,389,7,2,\"גנב משל אביו וכו' עד הרי זה פטור. משנה שם כתבתיה לעיל היא וגמרא שעליה:\",7,0],[8,389,7,2,\"וכן אם גנב משל אביו וכו'. נ\\\"ל שטעות סופר יש כאן וכן צריך להגיה והיתה אכילת עבירה אפילו מדבריהם פטור והדין משנה שם (דף ע') אכל בחבורת מצוה אכל בעיבור החדש אכל מעשר שני בירושלים אכל נבילות וטריפות שקצים ורמשים וכו' אכל דבר שהוא מצוה ודבר שהוא עבירה ובגמרא אכל בחבורת מצוה וכו' הא קמ\\\"ל דאע\\\"ג דכולה סריקין כיון דבמצוה קא עסיק לא מימשיך וכו' אכל דבר שהוא מצוה ודבר שהוא עבירה דבר שהוא מצוה תנחומי אבלים דבר עבירה תענית צבור וטעמא מאי כלומר אמאי מיפטר אדבר עבירה אמר קרא איננו שומע בקולנו ולא בקולו של מקום ופירש\\\"י דאיננו שומע בקולנו מיעוטא הוא ולאפוקי האי דאף בקולו של מקום אינו שומע:\",8,0],[8,389,7,3,\"אכל כל מאכל וכו'. משנה שם (דף ע') אכל כל מאכל ולא אכל בשר שתה כל משקה ולא שתה יין אינו נעשה בן סורר ומורה ואיתא נמי התם אמר רבא אכל בשר עוף אינו נעשה בן סורר ומורה ופירש רש\\\"י אכל בשר עוף טהור דלא חשיב ולא מימשיך בתריה והא אנן תנן אכל נבילות וטריפות שקצים ורמשים אינו נעשה בן סורר ומורה הא טהורים נעשה בן סורר ומורה כי תנן נמי מתניתין להשלים ופירש רש\\\"י כי תנן במתניתין דאיצטריך לאשמועינן דפטור אשקצים להשלים שאפילו אכל תרטימר בשר חסר כזית מבהמה טהורה והשלימו לתרטימר מבשר עופות טמאים פטור דאינו שומע בקולו של מקום דכוותה בטהורים מחייב:\",1,0],[8,389,7,4,\"אכל בשר חי ושתה וכו'. שם מימרא דרבה ורב יוסף:\",1,0],[8,389,7,5,\"לא ענש הכתוב וכו'. שם בראש הפרק (דף ס\\\"ח:) מאימתי נעשה סורר ומורה משיביא שתי שערות ועד שיקיף זקן התחתון וכו' שנאמר כי יהיה לאיש בן בן ולא איש כלומר וזה משהקיף זקן התחתון איש הוא קטן פטור שלא בא לכלל מצות כלומר ולפיכך אין לחייבו קודם שיביא שתי שערות וידוע דלא קרינן ביה הביא שתי שערות אלא בתר י\\\"ג שנה אבל מקמי הכי שומא נינהו כדאיתא בפ' יוצא דופן ונתבאר בדברי רבינו פ\\\"ב מהל' אישות ובגמ' תני ר' חייא עד שיקיף עטרה כי אתא רב דימי אמר הקפת גיד ולא הקפת ביצים ופירש\\\"י תני רבי חייא במתניתיה הכי משיביא שתי שערות עד שיקיף עטרה וכי אתא רב דימי פירשה דהא דתנא עד שיקיף עטרה לאשמועינן דהקפת זקן התחתון דמתני' הקפת גיד קאמר סמוך לביצים ולא הכיס של ביצים דהוי לבתר הכי טובא:\",1,0],[8,389,7,6,\"וכל ימיו של בן סורר ומורה וכו'. שם (דף ס\\\"ט) א\\\"ר כרוספדאי וכו' כל ימיו של בן סורר ומורה אינם אלא ג' חדשים בלבד ואיתא נמי התם תנא דבי ר' ישמעאל בן ולא אב ואמרינן התם דה\\\"ק בן ולא הראוי לקרותו אב ופירש\\\"י והיינו לאחר ג' חדשים אחר שהביא שתי שערות שראוי להיות העובר ניכר אם היה בא על האשה משהביא שתי שערות והיא מתעברת:\",1,0],[8,389,7,6,\"הא למדת וכו'. כלומר ממ\\\"ש שאם הקיף שיער פטור משמע אפילו קודם שישלים ג' חדשים והדין איתיה בגמרא שם א\\\"ר כרוספדאי כל ימיו של בן סורר ומורה אינן אלא ג' חדשים בלבד והא אנן תנן משיביא שתי שערות ועד שיקיף זקן התחתון הקיף זקן אע\\\"ג דלא מלו ג' חדשים מלו ג' חדשים ואף על גב דלא הקיף:\",2,0],[8,389,7,7,\"כיצד דנין וכו'. משנה שם (דף ע') מתרין בו בפני ג' ומלקין אותו חזר וקלקל נדון בעשרים ושלשה ואינו נסקל עד שיהיו שם שלשה הראשונים שנאמר בננו זה זהו שלקה בפניכם ובגמרא מתרין בפני ג' למה לי בתרי סגי אמר אביי ה\\\"ק מתרין בו בפני ב' ומלקין אותו בפני ג' מלקות בבן סורר ומורה היכא כתיבא כדרבי אבהו דאמר רבי אבהו למדנו ויסרו מויסרו ויסרו מבן ובן מבן והיה אם בן הכות הרשע ופירש\\\"י כדר' אבהו בכתובות גבי מוציא שם רע מנ\\\"ל דלקי דכתיב ולקחו זקני עירו את האיש ויסרו אותו. למדנו ויסרו דמוציא שם רע מויסרו אותו דבן סורר ומורה וההוא ויסרו דבן סורר ומורה למדנו מבן שכתוב בו וההוא בן למדנו מבן והיה אם בן הכות הרשע. וזהו שכתב\",1,0],[8,389,7,7,\"רבינו שנאמר ויסרו אותו והא דלא ילפינן מלקות בבן סורר ומורה מקרא דאייתינן לעיל לא תאכלו על הדם משום דהוי לאו שבכללות ואין לוקין עליו כדאיתא בפרק ארבע מיתות.\",2,0],[8,389,7,7,\"ומ\\\"ש אפילו היו שנים הראשונים הן האחרונים. אפשר שלמד כן מדתנן במרובה (דף ע') גנב ע\\\"פ שנים וטבח על פיהם או ע\\\"פ שנים אחרים משלם תשלומי ארבעה וחמשה ומ\\\"מ צ\\\"ע במה שלא הצריך לבדוק אם הקיף זקן אלא בעת שרוצים לגמור דינו למיתה למה לא הצריך לבדקו קודם שילקוהו שאם הוא גדול כיון דאינו נעשה בן סורר ומורה לאו בר מלקות הוא:\",3,0],[8,389,7,8,\"ואם מחלו לו וכו'. בסנהדרין פ' הנחנקין (סנהדרין דף פ״ח) א״ר יאשיה ג' דברים שח לי זעירא מאנשי ירושלים בעל שמחל על קינויו קינויו מחול בן סורר ומורה שרצו אביו ואמו למחול לו מוחלין לו זקן ממרא שרצו בית דינו למחול לו מוחלין לו וכשבאתי אצל חבירי שבדרום על שנים הודו לי ועל זקן ממרא לא הודו לי כדי שלא ירבו מחלוקות בישראל ומפרש רבינו דה״מ דאביו ואמו יכולים למחול קודם שנגמר דינו דאילו משנגמר דינו גברא קטילא הוא:\",1,0],[8,389,7,9,\"ברח עד שלא נגמר דינו וכו'. משנה פרק בן סורר ומורה (סנהדרין דף ע״א:):\",1,0],[8,389,7,10,\"היה אביו רוצה וכו' עד ולא חרשים. הכל משנה שם כלשון רבינו ופירש\\\"י בננו זה משמע שרואים אותו. חרשים אינם יודעים אם קבל דבריהם אם לאו שאם אמר להם איני מקבל אינו שומע לו ואע\\\"פ שרואים שאין מקיים מצותן מיהו איננו שומע בקולנו כתיב ואיכא להפוכי בזכותיה ולמדרש דבשעת הקול קאמרי דלא שמע:\",1,0],[8,389,7,11,\"גזירת הכתוב הוא וכו'. שם (דף ס\\\"ט ע') תניא אמר ר' שמעון בדין הוא שתהא בת ראויה להיות כבן סורר ומורה שהכל מצויים אצלה בעבירה כלומר וכשהיא זוללה וסובאה בקטנותה סופה כשלא תמצא למודה עומדת בפרשת דרכים ומרגלת הבריות לעבירה בשביל אתנן אלא גזירת הכתוב הוא בן ולא בת:\",1,0],[8,389,7,12,\"טומטום שנקרע ונמצא זכר וכו'. מימרא פ' יש נוחלין:\",1,0],[8,389,7,13,\"בן סורר ומורה צריך הכרזה. ברייתא בפרק הנחנקין (סנהדרין דף פ״ט):\",1,0],[8,389,7,13,\"ומה שכתב כיצד מכריזין עליו וכו':\",2,0],[8,389,7,14,\"בן סורר ומורה הרי הוא ככל הרוגי בית דין שממונם ליורשיהן וכו': סליקו הלכות ממרים בס\\\"ד\",1,0],[8,390,1,1,\"מצות עשה להתאבל על הקרובים. דעת הגאונים כדעת רבינו וכן דעת הרי\\\"ף והרמב\\\"ן אע\\\"פ שר\\\"ת ור\\\"י חולקין ומ\\\"מ הראיה שהביא רבינו ממה שנאמר ואכלתי חטאת היום הייטב בעיני ה' יש לתמוה עליה שבמקרא לא צוה שיתאבלו אלא שאמר אהרן שלא ייטב בעיני ה' שיאכל חטאת באותו יום ובספר המצות שלו כתב המצוה ל\\\"ז היא שנצטוו הכהנים שיטמאו לקרובים וזה בעצמו הוא מצות איבול כלומר כל איש מישראל חייב להתאבל על קרוביו כלומר ששה מתי מצוה ולחזק חיוב זה ביאר אותו בכהן שהוא מוזהר על הטומאה שיטמא על כל פנים כשאר ישראל כדי שלא יחלש דין אבילות וכבר התבאר שאבילות יום ראשון דאורייתא ובביאור אמרו במועד קטן אינו נוהג אבילות ברגל אי אבילות דמעיקרא היא אתי עשה דרבים ודחי עשה דיחיד הנה כבר התבאר שחיוב אבילות הוא מ\\\"ע אמנם ביום ראשון לבד והשאר דרבנן ואפילו הכהן חייב לנהוג ביום ראשון ויטמא לקרוביו והבן זה עכ\\\"ל. וגם על ראיה זו יש לתמוה שטומאה ענין אחד ואבילות ענין אחר ואם צוה שיטמא לקרוביו אין במשמע זה שיתאבל עליהם:\",1,0],[8,390,1,1,\"ואין אבילות מן התורה וכו'. כ\\\"כ הרי\\\"ף והרמב\\\"ן וכן הרשב\\\"א דלא אמרו הגאונים אלא ביום מיתה והוא עצמו יום הקבורה.\",2,0],[8,390,1,1,\"ומ\\\"ש אבל שאר השבעה ימים אינו דין תורה אע\\\"פ שנאמר בתורה ויעש לאביו אבל שבעת ימים ניתנה תורה ונתחדשה הלכה ומרע\\\"ה תיקן להם לישראל וכו':\",3,0],[8,390,1,2,\"מאימתי יתחייב אדם באבל וכו'. בפרק אלו מגלחין (מועד קטן דף כ״ז) ת״ר מאימתי כופין המטות משיצא מפתח ביתו דברי ר״א ר' יהושע אומר משיסתם הגולל וידוע דהלכה כר' יהושע וסתימת הגולל היינו לאחר שיתנו המת בקבר וימלאו הקבר עפר.\",1,0],[8,390,1,2,\"ומ\\\"ש אבל כל זמן שלא נקבר המת אינו אסור בדבר מהדברים שאבל אסור בהם ומפני טעם זה רחץ דוד וסך כשמת הילד טרם שיקבר. כתב הטור שכ\\\"כ הרי\\\"ץ בן גיאת ושהרמב\\\"ן חלוק עליו:\",2,0],[8,390,1,3,\"הרוגי מלכות וכו'. באבל רבתי פ' שני וכתב הרמב\\\"ן ז\\\"ל והר' יונה והרא\\\"ש והמרדכי בשם ר\\\"י דה\\\"מ כגון הרוגי ביתר שהיתה גזירת מלכות עליהם מחמת שנאה ולא מחמת ממון וכיון שכן אינה עשויה להבטל ומפני כך חל עליהם אבילות מיד שנתיאשו מלבקש אבל מי שלא הניחו השלטון לקבור עד שיפדוהו בממון הרבה לא חל עליהן אבילות דכיון דבממון הדבר תלוי אפשר שאח\\\"כ יתפייס בדמים מועטים ומפני כך לא חל עליהם אבילות ואפשר שלזה נתכוון רבינו במ\\\"ש הרוגי מלכות שאין מניחין אותם להקבר דמשמע שכן משפטי המלכות שאין מניחין אותם להקבר ואינו הדבר התלוי בממון אלא בחסדי המלך שיתן רשות:\",1,0],[8,390,1,4,\"מי שטבע בנהר וכו'. ג\\\"ז באבל רבתי (שם) כתוב בעיטור בשם תשובת הרי\\\"ף מי שטבע במים שאין להם סוף אין היתר לאשתו וכיון דבחזקת קיים מסתברא דלא נהיג אבילותא והא דתניא באבל רבתי טבע בנהר או שנפל בים מאימתי מונין לו משנתייאשו לבקש איכא למימר שנפל ומת או שנפל למים שיש להם סוף עכ\\\"ל:\",1,0],[8,390,1,5,\"מי שדרכן לשלוח המת וכו'. בפרק אלו מגלחין (מועד קטן דף כ״ב) אמר להו רבא לבני מחוזא אתון דלא אזליתו בתר ערסא מכי מהדריתו אפייכו מבבא דאבולא אתחילו ומנו:\",1,0],[8,390,1,6,\"הנפלים אין מתאבלין עליהן. מתבאר ממה שיבא בסמוך.\",1,0],[8,390,1,6,\"ומ״ש וכל שלא שהה ל' יום באדם ה״ז נפל. בפ' ר״א דמילה (שבת דף קל״ה) אמר רשב״ג כל ששהה ל' יום באדם אינו נפל וכו' הא לא שהה ספיקא הוי ואיפסיקא התם בגמ' הלכתא כוותיה הילכך לגבי אבילות דרבנן הוא הוי ספיקא לקולא.\",2,0],[8,390,1,6,\"ומ״ש אפילו מת ביום ל' וכו'. הכי אסיק רב אשי בפ' יש בכור (בכורות דף מ״ט):\",3,0],[8,390,1,7,\"ומ״ש ואם נודע בודאי שנולד לתשעה חדשים גמורים אפילו מת ביום שנולד מתאבלים עליו. הכי אמרינן בפ' ר״א דמילה ובפ' יוצא דופן (נדה דף מ״ד:) וכתבו הגהות בשם רש״י דלא קים לן בדבר זה כלל אלא שלא שמשה עם בעלה כל ימי עיבורה:\",1,0],[8,390,1,7,\"ומ\\\"ש בן ט' שנולד מת ובן ח' שמת וכו'. באבל רבתי פ\\\"ק מחותך מרוסס נפלים ובן ח' חי בן ט' מת אין מתעסקין עמו בכל דבר. ומשמע לרבינו דבכלל אין מתעסקין עמהם בכל דבר הוי שאין מתאבלים עליהן:\",2,0],[8,390,1,7,\"ועל מ\\\"ש רבינו ובן ח' שמת אפילו לאחר ל' יום. כתב הראב\\\"ד זה אינו מחוור וכו'. וה\\\"ה בפ\\\"א מהל' יבום כתב טעם לדברי רבינו:\",3,0],[8,390,1,9,\"כל הרוגי מלכות אף על פי שנהרגו בדין המלך וכו' הרי אלו מתאבלין עליהם. ומ״ש ממונם למלך. בסוף פרק נגמר הדין (סנהדרין דף מ״ח:):\",1,0],[8,390,1,9,\"ומ\\\"ש אבל כל הרוגי ב\\\"ד וכו' עד שיתעכל הבשר. משנה שם:\",2,0],[8,390,1,9,\"ומ\\\"ש ממונם ליורשיהם. שם:\",3,0],[8,390,1,10,\"כל הפורשים מדרכי צבור וכו'. באבל רבתי פרק שני.\",1,0],[8,390,1,10,\"ומ\\\"ש וכן האפיקורסין והמוסרים. כל אלו בכלל פורשים מדרכי צבור:\",2,0],[8,390,1,11,\"המאבד עצמו לדעת וכו'. באבל רבתי בפרק ב' המאבד עצמו לדעת אין מתעסקין עמו בכל דבר וכו' אין קורעין עליו ואין חולצין ולא מספידין עליו אבל עומדים עליו בשורה ואומרין עליו ברכת אבלים מפני שהוא כבוד החיים וכללו של דבר כל שהוא כבוד חיים מתעסקין בו כל שאינו כבוד של חיים אין הרבים מתעסקין עמו לכל דבר וסובר רבינו דאבילות אינו מדברים של כבוד החיים והרמב\\\"ן חולק בדבר:\",1,0],[8,390,1,11,\"ואיזהו המאבד עצמו לדעת וכו' עד סוף הפרק. שם:\",2,0],[8,390,2,1,\"אלו שאדם חייב להתאבל עליהם דין תורה. בפרק ואלו מגלחין (מועד קטן דף כ' ע״ב) ת״ר כל האמור בפרשת כהנים שכהן מיטמא להם אבל מתאבל עליהם ואלו הן אשתו אביו ואמו אחיו ואחותו בנו ובתו הוסיפו עליהם אחיו ואחותו הבתולה מאמו ואחותו הנשואה בין מאביו בין מאמו. וא״ת מאחר שרבינו סובר דמדין קרובים שהכהן מיטמא להם למדנו שמתאבלים עליהם כמ״ש בתחלת הלכות אלו ואשתו כתובה באורייתא לענין טומאת כהן דכתיב כ״א לשארו הקרוב אליו ואמרינן בפ' האשה רבה (יבמות דף צ') ובפרק כיצד (דף כ״ב) שארו זו אשתו ובר״פ טבול יום אמרו שמתה אשתו של יוסף הכהן וטמאוהו על כרחו וכ״כ רבינו לקמן בפרק זה אשתו של כהן מתטמא לה והיינו ודאי מדאורייתא וכן משמע עוד מדבריו רפ״ג וא״כ למה כתב שאינו מתאבל עליה מן התורה ואפשר לומר דרבינו אזיל לטעמיה שסובר שכל דבר שאינו מפורש בתורה ממש אע״פ שדינו דין תורה מיקרי מד״ס ואשתו אינה מפורש בתורה דשארו אינו מוכרח שיהא פירוש אשתו שהרי אונקלוס תרגם לשארו לקריביה דקריב ליה:\",1,0],[8,390,2,1,\"ומ\\\"ש וכן האשה על בעלה. כך כתבו הרמב\\\"ן והרא\\\"ש וטעמא דכיון דאבלות כטומאה כשם שהאשה מטמאה לבעלה כך היא מתאבלת עליו:\",2,0],[8,390,2,2,\"ומ\\\"ש ואם היתה אחותו וכו'. כתב הרמב\\\"ן על זה בתורת הבית זה לא ידענו לו צד סמך ומקום טענה:\",1,0],[8,390,2,3,\"בנו או אחיו הבא מן השפחה ומן הנכרית. כ\\\"כ הרמב\\\"ן והרא\\\"ש וטעמא מפני שכך הדין לענין טומאה כתב אינו מתאבל עליהם כלל כלומר אפילו מדבריהם:\",1,0],[8,390,2,3,\"ומ\\\"ש וכן מי שנתגייר וכו'. הוא נלמד מדין בנו מן השפחה ומן העכו\\\"ם ועוד דגר שנתגייר כקטן שנולד דמי:\",2,0],[8,390,2,3,\"וכן אשתו ארוסה אינו מתאבל עליה וכו'. בפ' ד' אחין (יבמות דף כ״ט:) אשתו ארוסה אינו אונן עליה ואינה אוננת עליו ומשמע לרבינו דה״ה לאבילות:\",3,0],[8,390,2,5,\"כל קרובים שהוא חייב להתאבל עליהם וכו' עד אין מתאבלין זה על זה. בפ' אלו מגלחין (מועד קטן דף כ':) ובפ״ק דכתובות (דף ד':).\",1,0],[8,390,2,5,\"ומ\\\"ש וכן יראה לי שאם מתה אשת קרובו וכו'. כך כתבו הגהות בשם רש\\\"י ז\\\"ל:\",2,0],[8,390,2,5,\"כתב הרמב\\\"ן והרא\\\"ש והגהות דהאידנא נהגו להקל באבילות של המתאבלים עליהם וסומכים על זה שאינו אלא בשביל כבוד האבל ואם רצה האבל למחול על כבודו אינו צריך להתאבל עמו והאידנא כל האבלים נוהגין למחול על כבודם:\",3,0],[8,390,2,6,\"כמה חמורה מצות אבילות וכו'. לטעמיה שכתב בספר המצות שלו שכתבתי בתחלת הלכות אלו אזיל:\",1,0],[8,390,2,6,\"לה יטמא מצות עשה שאם לא רצה להיטמא וכו'. בריש פרק טבול יום (זבחים דף ק'):\",2,0],[8,390,2,6,\"ומה שכתב במה דברים אמורים בזכרים וכו': כתב הראב\\\"ד קשיא הא דתניא וכו'. והרמב\\\"ן כתב על דברי רבינו ולפי זה הא דתניא לא מטמאה לו לאו דוקא בארוסה אלא שיטפיה נקט אבל לא נתברר לי מהיכן יצאה לרב זאת הסברא ושמא הוא דורש בזה כל שישנו בלא יטמא ישנו ביטמא והני נשי הואיל וליתנהו בלא יטמא ליתנהו במצות יטמא א\\\"נ כי כתיב בני אהרן ולא בנות אהרן אכוליה עניינא כתיב ובסוף דבריו כתב והדברים צריכין לימוד והרא\\\"ש כתב שלא נתיישבו לו דברי הרמב\\\"ם כי הרבה צריך ראיה לפטור נשים מהמצוה זאת:\",3,0],[8,390,2,7,\"אשתו של כהן מתטמא לה על כרחו וכו'. בר\\\"פ טבול יום:\",1,0],[8,390,2,7,\"ומ\\\"ש ואינו מטמא לה אלא מד\\\"ס. אזדא לטעמיה שכתבתי בתחלת פרק זה אצל מ\\\"ש ומדבריהם שיתאבל האיש על אשתו הנשואה:\",2,0],[8,390,2,7,\"ומ״ש עשאוה כמת מצוה שאין לה יורש אלא הוא וכו'. בר״פ האשה רבה (יבמות דף פ״ט:) מאימתי יורש אדם את אשתו קטנה וכו' ויורשה ומטמאה לה וכו'. והא הכא דמדאורייתא אביה מטמא לה ומדרבנן מטמא לה בעל משום דה״ל מת מצוה ומי הויא מת מצוה והתניא איזהו מת מצוה כל שאין לו קוברים קורא ואחרים עונין אותו אין זה מת מצוה ה״נ כיון דלא ירתי לה קריא ולא ענו לה ומשמע שלא הוצרכו לכן אלא באשתו קטנה אבל בגדולה מדינא מטמא לה דכתיב כ״א לשארו וי״ל דכיון דקריא ולא ענו לה שייך נמי בגדולה נקט טעמא דשויא בכולהו:\",3,0],[8,390,2,7,\"ומ״ש ואינו מטמא אלא לנשואה בלבד וכו'. בפרק ארבעה אחין (יבמות דף כ״ט:) אשתו ארוסה לא אונן ולא מטמא לה:\",4,0],[8,390,2,8,\"וכן כל אותן שאמרו וכו'. ברייתא בת\\\"כ כתבוה הרי\\\"ף והרא\\\"ש בעמיו בזמן שהם עושין מעשה עמיו ולא שפירשו מדרכי צבור:\",1,0],[8,390,2,8,\"ומ\\\"ש והנפלים. בתורת כהנים ולבנו ולבתו יכול אפילו נפלים תלמוד לומר לאביו ולאמו מה אביו ואמו של קיימא אף בנו ובתו של קיימא יצאו נפלים:\",2,0],[8,390,2,8,\"ומ\\\"ש והמאבד עצמו לדעת. נראה שהטעם שמאחר שנדחית הטומאה כדי שיתאבל כיון שסובר רבינו שאין מתאבלים עליו ממילא משמע שאין מטמא לו וזה טעם שייך גם בהרוגי ב\\\"ד:\",3,0],[8,390,2,8,\"ועד מתי מצווה להתטמא לקרוביו וכו'. באבל רבתי פרק עד אימתי מטמא להם ר\\\"מ אומר כל אותו היום ר\\\"ש אומר עד שלשה ימים ר' יהודה אומר משום ר' טרפון עד שיסתם הגולל מעשה שמת ר\\\"ש בן יהוצדק בלוד ובא רבי יוחנן אחיו מהגליל וכו' ובאו ושאלו את ר' טרפון וחכמים אמרו להם יטמא ומשמע דהלכה כרבי יהודה משום רבי טרפון דהלכה כרבי יהודה לגבי ר\\\"מ ולגבי ר\\\"ש וכל שכן הכא דמשום ר' טרפון קאמר לה ועוד דחכמים סברי כר' טרפון וכן פסקו הרמב\\\"ן והרא\\\"ש:\",4,0],[8,390,2,9,\"אשתו הפסולה אינו מטמא לה. בפרק האשה רבה (יבמות דף צ':) ובפ״ב דיבמות (דף כ״ב:) יליף לה מקרא:\",1,0],[8,390,2,9,\"ומ״ש לפיכך מי ששמעה שמועה שמת בעלה וכו'. משנה בפרק האשה רבה (יבמות דף פ״ז:):\",2,0],[8,390,2,9,\"ומ\\\"ש אבל מטמא לאמו אע\\\"פ שהיא חללה. בת\\\"כ דריש לה מקרא:\",3,0],[8,390,2,9,\"ומ\\\"ש וכן מטמא לבנו ולבתו וכו' אע\\\"פ שהם פסולים אפילו היו ממזרים וכו'. בפ\\\"ב דיבמות (דף כ\\\"ב:):\",4,0],[8,390,2,10,\"אחותו הנשואה אינו מטמא לה וכו'. איכא למידק מאחר דאפילו לארוסה אינו מטמא כמ\\\"ש רבינו לקמן בסמוך אמאי איצטריך למיכתב דאינו מטמא לנשואה. וי\\\"ל דמשום דארוסה אם נתגרשה מטמא לה קאמר דבנשואה לעולם אינו מטמא לה אפילו נתגרשה:\",1,0],[8,390,2,10,\"ומ״ש הבתולה פרט לאנוסה ומפותה וכו'. בפ' הבא על יבמתו (יבמות דף ס') תנו רבנן אחותו ארוסה ר״מ ורבי יהודה אומרים מטמא לה ר' יוסי ור״ש אומרים אינו מטמא לה אנוסה ומפותה ד״ה אינו מטמא לה ומוכת עץ אינו מטמא לה דברי ר״ש וכו' מ״ט דר״מ ור' יהודה דדרשי הכי ולאחותו הבתולה פרט לאנוסה ומפותה יכול שאני מוציא אף מוכת עץ ת״ל אשר לא היתה לאיש מי שהוויתה על ידי איש יצתה זו שאין הוויתה ע״י איש הקרובה לרבות את הארוסה אליו לרבות את הבוגרת ור״ש ורבי יוסי וכו' דדרשי הכי ולאחותו הבתולה פרט לאנוסה ומפותה ומוכת עץ אשר לא היתה פרט לארוסה שהיתה הקרובה לרבות ארוסה שנתגרשה אליו לרבות את הבוגרת ופסקו הפוסקים כרבי יוסי ור״ש לגבי ר״מ ור' יהודה ובמוכת עץ פסקו דלית הלכתא כר״ש לגבי ר' יוסי ור' יהודה ור״מ.\",2,0],[8,390,2,10,\"ומ\\\"ש אע\\\"פ שהיא ארוסה לכהן:\",3,0],[8,390,2,12,\"אחיו ואחותו מאמו וכו'. בתורת כהנים:\",1,0],[8,390,2,13,\"הספיקות אינו מטמא להם שנאמר לה יטמא וכו'. ברייתא בת\\\"כ וכתבוה הרי\\\"ף והרמב\\\"ן והרא\\\"ש:\",1,0],[8,390,2,14,\"אין הכהן מיטמא לאבר מן החי מאביו וכו': כתב הראב״ד א״א הרב אינו פוסק כן עכ״ל. ועתה אבאר הנה כתב הרי״ף בהלכות טומאה לה יטמא ואינו מטמא על איבריה שאין אדם מטמא על אבר מן החי מאביו אבל מטמא על עצם כשעורה מאביו וכתב עליו הרמב״ן ולא מחוורא שמעתתיה דגרסינן בפ' ג' מינין (נזיר דף מ״ג:) א״ר חסדא אמר רב נקטע ראשו של אביו אינו מיטמא לו מ״ט דאמר קרא לאביו בזמן שהוא שלם ולא בזמן שהוא חסר פירוש ואע״פ שמצא ראשו כיון שאינו כברייתו אינו מטמא [לו ואקשינן עלה דרב מהא מתניתא לה יטמא לה הוא מיטמא ואינו מיטמא לאיבריה] שאינו מיטמא על אבר מן החי של אביו אבל מטמא על עצם כשעורה מן המת של אביו קשיא לרב ומסקנא דרב דאמר כי האי תנא דתניא מעשה שמת אביו של רבי צדוק בגינזק ובאו והודיעוהו לאחר ג' שנים ובא ושאל את ר' יהושע בן אלישע וארבעה זקנים ואמרו לאביו בזמן שהוא שלם ולא בזמן שהוא חסר וקי״ל מעשה רב [ועוד דרבים נינהו] ועוד כיון דלא אשכחן אמורא דפליג עליה דרב חסדא אמר רב קי״ל הלכה כבתראי עכ״ל. והרא״ש כתב שמ״ש הרי״ף אבל מטמא הוא על עצם כשעורה של אביו ע״כ לומר דהיינו דוקא ע״י חזרה שאם כבר נטמא לקבור את אביו ונחסר עצם כשעורה חוזר עליו ומטמא לו לקברו ואתי כר״י דפליג התם אר' יהושע בן אלישע וארבעה זקנים דאל״כ אתי דלא כמאן והקשה עליו למה פסק כיחידאה נגד ר' יהושע בן אלישע וארבעה זקנים ועוד כי עשו מעשה ומעשה רב ועוד כי שיטת הגמרא בכל מקום דהלכה כאמוראי גם כי יפסוק דלא כסתם מתניתין כ״ש הכא דרב חסדא ס״ל כרבים ועוד דבדאורייתא אזלינן לחומרא ולא יטמא לו עכ״ל. ודעת רבינו כהרמב״ן והרא״ש והלכה כרב חסדא אמר רב:\",1,0],[8,390,2,14,\"ודע דסוגיא דפ' ג' מינים הכי איתא אמר רב חסדא אמר רב נקטע ראשו של אביו אינו מטמא לו מ\\\"ט דאמר קרא לאביו בזמן שהוא שלם ולא בזמן שהוא חסר וכו' מיתיבי לה יטמא לה הוא מטמא ואינו מטמא לאיבריה לפי שאינו מטמא לאבר מן החי של אביו אבל מחזיר הוא על עצם כשעורה מאי מחזיר הוא על עצם כשעורה לאו למימרא דאי מחסר פורתא לא ההיא ר\\\"י היא דתניא ר' יהודה אומר לה הוא מטמא ואינו מיטמא לאיבריה שאינו מטמא על אבר מן החי של אביו אבל מטמא הוא לאבר מן המת של אביו והתניא וכו' כראב\\\"י לה מטמא ואינו מטמא לאיבריה פרט לכזית מן המת וכזית נצל ומלא תרווד רקב יכול לא יטמא לשדרה וגולגולת ולרוב בנינה ולרוב מניינה כתיב ואמרת אליהם הוסיף לך הכתוב טומאה אחרת וכו' ההיא נמי ר\\\"י היא ורב דאמר כי האי תנא דתניא מעשה שמת אביו של רבי צדוק בגינזק וכו' ובא ושאל את רבי יהושע בן אלישע וארבעה זקנים ואמרו לאביו בזמן שהוא שלם ולא בזמן שהוא חסר. ופירש\\\"י נקטע ראשו של אביו אע\\\"פ שהראש בצד הגוף הואיל וכבר נקטע אינו מטמא וכו' בזמן שהוא שלם שלא נתפרדו איבריו זה מזה ולא בזמן שהוא חסר כגון זה שנקטע ראשו. מאי מחזיר הוא על עצם כשעורה דאילו מחסר פורתא כלומר דבשעה שנגע בה ברישא הוה חסר להך עצם פורתא [כשעורה] ואפילו הכי היה מותר ליטמא בה וקשיא לרב חסדא דהא סתמא לדברי הכל היא. לא ההיא רבי יהודה היא דתניא הכי גרסינן רבי יהודה אומר לה יטמא ואינו מטמא לאיבריה לפי שאין אדם מטמא על עצם כשעורה מאביו וכו' כלומר לאיברים הוא דאינו מטמא בין בחייו בין במותו לפי שאין אדם מטמא תחלה על עצם כשעורה מאביו לפי שלא התירה תורה ליטמא אלא בדבר שעיקר הגוף בו אבל מטמא הוא לעיקר הגוף לכתחלה ואם נחסר הוא הולך ובודק אחריו ואפילו על עצם כשעורה ואנא אמינא כרבנן דפליגי עליה דרבי יהודה וכו' וספרים שכתוב בהם לפי שאינו מטמא לאבר מן החי של אביו אבל מיטמא לאבר מן המת של אביו שבשתא היא וכו' והתני רב כהנא כראב\\\"י כלומר בברייתא דראב\\\"י וכו' הוסיף לך טומאה אחרת דבשדרה ורוב בניינה כגון שתי שוקים וירך אחת וברוב מנינה כגון קכ\\\"ה איברים הימנה שיכול ליטמא וכו'. ובא ושאל את ר' יהושע וכו' מהו ליטמא ולהביאו בקברי אבותיו וכו' ולא בזמן שהוא חסר ולאחר שלש שנים א\\\"א לו שאינו חסר עכ\\\"ל. כתבתי כל זה לשתי תועליות. האחת כדי שיתבארו דברי רבינו ויובנו יפה. השנית להתבונן מתוך סוגיא זו שיש מקום להשיב בעד הרי\\\"ף ממה שהשיגו עליו לומר דפסק כיחידאה דהיינו רבי יהודה דאיכא למימר דלאו יחידאה הוא דהא ראב\\\"י סבר כוותיה ואע\\\"ג דהכא הוו תרי ורבי יהושע בן אלישע וארבעה זקנים הוה ליה חמשה הני תרי עדיפי משום דהוו מרי גמרא טפי מאינך ועוד דמשנת ראב\\\"י קב ונקי ומה שכתבנו דלא אשכחן אמורא דפליג עליה דרב חסדא איכא למימר דרב כהנא פליג עליה דמאחר דהוה תני כדראב\\\"י משמע דהכי ס\\\"ל ואע\\\"ג דרב חסדא משמיה דרב קאמר לה אפשר שהרי\\\"ף לא היה גורס אמר רב ואפילו אי גריס ליה אפשר דאליבא דההוא תנא דגינזק קאמר וליה לא סבירא ליה ואשכחן דכוותה בריש שבועות גבי פלוגתא דר\\\"י ור\\\"ל ומ\\\"מ לענין מעשה מאחר שרבינו והרמב\\\"ן והרא\\\"ש מסכימים לדעת אחת הכי נקטינן וכ\\\"ש שהם מחמירין בשל תורה. ונשאר לדקדק בדברי רבינו שכתב וכן שאר קרובים דהא כ\\\"ש הוא ואיך כתבו בלשון וכן ודוחק לומר דסד\\\"א שהיה שום מיעוט באביו דוקא וגזירת הכתוב הוא קמ\\\"ל:\",2,0],[8,390,2,15,\"הטומאה לקרובים דחויה היא וכו' לפיכך אסור לכהן זה להתטמא למת ואפילו בעת שמתטמא לקרוביו וכו'. בפ' ג' מינים (נזיר דף מ״ב:) כהן שהיה לו מת מונח על כתפו והושיטו לו מתו ומת אחר ונגע בו יכול יהא חייב ת״ל להחלו מי שאינו מחולל יצא זה שמחולל ועומד והוינן בה מדתנן היה מטמא למתים כל היום אינו חייב אלא אחת אמרו לו אל תטמא אל תטמא והוא מטמא חייב על כל אחת ואחת ואמאי והא מיטמא וקאי ואמר ר״ה נזיר שהיה עומד בבית הקברות והושיטו לו מתו ומת אחר ונגע בו חייב אמאי הא מיטמא וקאי ומפרקינן לה דכי אמרי' הושיטו לו מתו ומת אחר ונגע פטור בחיבורי אדם במת אבל פירש ממתו ונגע במת אחר חייב וטעמא משום דמוסיף טומאה על עצמו שאדם כשהוא תפוס במת הנוגע בו כנוגע במת עצמו ונעשה אב הטומאה וכשפירש מן המת הוא עצמו אב הטומאה והנוגע בו ראשון לטומאה וכתבו הרמב״ן והרא״ש ולא תימא הא דקתני יכול יהא חייב ת״ל להחלו חיובא הוא דליכא הא איסורא איכא דתניא באבל רבתי היה עומד וקובר את מתו עד שהוא בתוך הקבר מקבל מאחרים וקובר פירש הרי זה לא יטמא נטמא בו ביום רבי טרפון מחייב ורבי עקיבא פוטר נטמא לאחר אותו יום הכל מודים שהוא חייב מפני שהוא סותר יום אחד והלכה כרבי טרפון דקי״ל סתם במתני' ומחלוקת בברייתא הלכה כסתם ותנן אמרו אל תטמא אל תטמא והוא מטמא חייב על כל אחת ואחת אע״ג דמיטמא וקאי ועוד דרב הונא דהוא אמורא קאי כוותיה ואף ר' עקיבא מודה דאסור דקתני רישא פירש הרי זה לא יטמא ולא פליג אלא בחיובא דפטר בו ביום ועוד דבמסכת נזיר שנו מחלוקתם להפך יצא ונכנס ר' טרפון פוטר ור' עקיבא מחייב א״ל ר' טרפון וכי מה הוסיף זה חילול על חילולו אמר ר' עקיבא בשעה שהיה הוא שם טמא טומאת שבעה פירש טמא טומאת ערב חזר ונכנס טמא טומאת שבעה פירוש הנוגע בו א״ל ר' טרפון כל הפורש ממך כפורש מחייו והרי לפי זה הלשון כ״ש שהדבר פשוט שהלכה כדברי המחייב הילכך אין הכהנים נכנסים לבית הקברות לקבור מתי מצוה שלהם שאפילו היה תפוס בהן בכניסה ובחיבורין מותר בהן להטמא לאחרים כשהוא פורש מהן לאחר קבורה נמצא מטמא לאחרים ואסור לפיכך משפחות כהונה עושים שכונת קבורה שלהם בסוף בית הקברות וכל שמת לו מת קובר בסוף השכונה כדי שלא יכנס לבית הקברות ולא יטמא בקברות אחרים ואע״פ שר״ת כתב דהלכה כר' עקיבא בההיא דאבל רבתי דנטמא בו ביום פטור ומותר הכהן להכניס מתו לבית הקברות ולקברו ואפילו ר״ע אוסר טומאה בו ביום מדבריהם גדול כבוד מתו שדוחה ל״ת דדבריהם והביא ראיה מפרק דם הנדה, הרמב״ן והרא״ש דחו ראייתו והעלו כדברי רבינו וכך נראה שהוא דעת התוספות בפרק דם הנדה:\",1,0],[8,390,3,1,\"כל כהן שנטמא למת וכו' הרי זה לוקה שנאמר לנפש לא יטמא בעמיו. פשוט הוא:\",1,0],[8,390,3,1,\"ומה שכתב ואחד הנוגע במת או המאהיל או הנושא.. ואחד המת ואחד שאר טומאות הפורשות מן המת וכו'. בת\\\"כ אין לי אלא המת מנין לרבות את הדם ת\\\"ל לנפש ואומר כי הדם הוא הנפש מנין לרבות כל הטומאות הפורשות מן המת ת\\\"ל ואמרת אליהם לרבות הטומאות הפורשות מן המת. ורבינו נראה שסובר דכיון דילפינן לדם ה\\\"ה לשאר טומאות הפורשות מן המת דמאי שנא ולא הוה צריך קרא למילף שאר טומאות הפורשות אלא אסמכתא בעלמא הוא:\",2,0],[8,390,3,4,\"נכנס ויצא וחזר ונכנס וכו' וכן אם נגע במת והתרו בו וכו'. משנה פ' ג' מינין (נזיר דף מ״ב) ופ' בתרא דמכות (דף כ״א) היה מטמא למתים כל היום אינו חייב אלא אחת אמרו לו אל תטמא אל תטמא והוא מטמא חייב על כל אחת ואחת:\",1,0],[8,390,3,4,\"ומה שכתב היה נוגע ולא פירש וכו'. שם בגמרא וכתבתיה בספ\\\"ב:\",2,0],[8,390,3,6,\"כהן גדול אינו מטמא לקרובים וכו'. בפ' ג' מינין (נזיר דף מ״ב:) אתמר אמר רבה אמר רב הונא מקרא מלא דבר הכתוב לא יטמא כשהוא אומר לא יבא להזהירו על הטומאה להזהירו על הביאה אבל טומאה וטומאה לא ורב יוסף אמר וכו' אמר רב הונא אפילו טומאה וטומאה איתיביה אביי נזיר שהיה עומד בבית הקברות והושיטו לו מת ונגע בו יכול יהא חייב ת״ל להחלו במי שאינו מחולל יצא זה שמחולל ועומד א״ל ותיקשי לך מתני' דתנן אמרו אל תטמא אל תטמא והוא מיטמא חייב על כל אחת ואחת ואמאי הא מיטמא וקאי אלא קשיא אהדדי ל״ק כאן בחיבורין כאן שלא בחיבורין פי' בעודו מחובר למת אם נגע במת אחר פטור משום דכתיב להחלו יצא זה שמחולל ועומד אבל אם פירש ממת זה ונגע במת אחר חייב ואמרינן בתר הכי אבל טומאה וטומאה לא דהא מיטמא וקאי טומאה וביאה נמי הא מיטמא וקאי וכו' אמר רבא הכניס גופו טומאה וביאה בהדי הדדי קא אתיין והא א״א דלא עייל אצבעתא דכרעיה ברישא ונחית להו טומאה ואסיקנא אלא אמר רב פפא כגון שנכנס בשידה תיבה ומגדל ובא חבירו ופרע עליו את המעזיבה דטומאה וביאה בהדי הדדי קא אתיין מר בר רב אשי אמר כגון דעייל כשהוא גוסס ונפק נשמה אדיתיב");
